INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'V začetku je Bog ustvaril nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Zemlja pa je bila brez oblike ter prazna in tema je bila na obličju globin in Božji Duh se je premikal na obličju vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, '[1. dan] Bog je rekel: »Naj bo svetloba.« In bila je svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Bog je videl svetlobo, da je bila dobra in Bog je ločil svetlobo od teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Bog je svetlobo imenoval Dan, temo pa je imenoval Noč. In večer in jutro sta bila prvi dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, '[2. dan] Bog je rekel: »Naj bo nebesni svod na sredi vodá in naj razdeli vode od vodá.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Bog je naredil nebesni svod in razdelil vode, ki so bile pod nebesnim svodom od vodá, ki so bile nad nebesnim svodom. In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Bog je nebesni svod imenoval Nebo. In večer in jutro sta bila drugi dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, '[3. dan] Bog je rekel: »Naj bodo vode pod nebom zbrane skupaj na en kraj in naj se pojavi kopna zemlja.« In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Bog je kopno zemljo imenoval Zemlja, zbiranje skupnih vodá pa je imenoval Morja, in Bog je videl, da je bilo to dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Bog je rekel: »Naj zemlja rodi travo, zelišče, ki obrodi seme in sadno drevo, ki obrodi sad po svoji vrsti, čigar seme je v njem samem na zemlji.« In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, '§ Zemlja je rodila travo in zelišče, ki obrodi seme po svoji vrsti in drevo, ki obrodi sad po svoji vrsti, čigar seme je v njem samem, po njegovi vrsti. In Bog je videl, da je bilo to dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'In večer in jutro sta bila tretji dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, '[4. dan] Bog je rekel: »Naj bodo svetilke na nebesnem svodu neba, da razdelijo dan od noči; in naj bodo za znamenja, za letne dobe, za dneve in leta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'in naj bodo za svetilke na nebesnem svodu neba, da na zemljo dajejo svetlobo.« In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Bog je naredil dve veliki luči: svetlejšo luč, da vlada dnevu in šibkejšo luč, da vlada noči; naredil je tudi zvezde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Bog jih je postavil v nebesni svod neba, da na zemljo dajejo svetlobo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'in da vladajo nad dnevom in nad nočjo in da ločijo svetlobo od teme. In Bog je videl, da je bilo to dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'In večer in jutro sta bila četrti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, '[5. dan] Bog je rekel: »Naj vode obilno rodijo gibljivo ustvarjeno bitje, ki ima življenje in perjad, da lahko leti nad zemljo v odprtem nebesnem svodu neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Bog je ustvaril velikanske kite in vsako živo ustvarjeno bitje, ki se giblje, ki so jih vode obilno rodile po svoji vrsti in vsako krilato perjad po svoji vrsti. In Bog je videl, da je bilo to dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Bog jih je blagoslovil, rekoč: »Bodite rodovitne in se množite ter napolnite vode v morjih in naj se perjad pomnoži na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'In večer in jutro sta bila peti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, '[6. dan] Bog je rekel: »Naj zemlja rodi živo ustvarjeno bitje po svoji vrsti, živino in plazečo stvar in žival zemlje po svoji vrsti.« In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Bog je naredil žival zemlje po svoji vrsti in živino po svoji vrsti in vsako stvar, ki se plazi po zemlji, po svoji vrsti. In Bog je videl, da je bilo to dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Bog je rekel: »Naredimo človeka po naši podobi, po naši podobnosti in naj imata gospostvo nad ribo morja in nad zračno perjadjo in nad živino in nad vso zemljo in nad vsako plazečo stvarjo, ki se plazi na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Tako je Bog ustvaril človeka po svoji lastni podobi, po Božji podobi ga je ustvaril Bog. Moškega in žensko ju je ustvaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Bog ju je blagoslovil in Bog jima je rekel: »Bodita rodovitna in se množita in napolnita zemljo ter si jo podjarmita in imejta gospostvo nad ribami morja in nad zračno perjadjo in nad vsako živo stvarjo, ki se giblje na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Bog je rekel: »Glejta, dal sem vama vsako zeleno zelišče, ki obrodi seme, ki je na obličju vse zemlje in vsako drevo, na katerem je sad drevesa, ki obrodi seme; naj vama bo to za hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Vsaki zemeljski živali in vsaki zračni perjadi in vsaki stvari, ki se plazi na zemlji, v kateri je življenje, sem dal za hrano vsako zeleno zelišče.« In bilo je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Bog je videl vsako stvar, ki jo je naredil, in glej, to je bilo zelo dobro. In večer in jutro sta bila šesti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Tako sta bila končana nebo in zemlja in vsa njuna vojska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, '[7. dan] Na sedmi dan je Bog končal svoje delo, ki ga je naredil; in na sedmi dan je počival od vsega svojega dela, ki ga je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Bog je blagoslovil sedmi dan ter ga posvetil, zato ker je na ta [dan] počival od vsega svojega dela, ki ga je Bog ustvaril in naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'To so rodovi neba in zemlje, ko so bili ustvarjeni, na dan, ko je Gospod Bog naredil zemljo in nebo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'in vsako poljsko rastlino, preden je bila na zemlji in vsako poljsko zelišče, preden je zraslo, kajti Gospod Bog na zemljo ni poslal dežja in ni bilo človeka, da obdeluje tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Toda meglica se je dvigala iz zemlje in namakala celotno obličje tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Gospod Bog je iz prahu tal oblikoval človeka in v njegove nosnice vdihnil dih življenja, in človek je postal živa duša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Gospod Bog je zasadil vrt proti vzhodu v Edenu in tja je postavil človeka, ki ga je oblikoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Gospod Bog je naredil, da iz tal požene vsako drevo, ki je prijetno pogledu in dobro za hrano; tudi drevo življenja v sredi vrta in drevo spoznanja dobrega in zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'In reka je izvirala iz Edena, da namaka vrt in od tam je bila razdeljena v štiri glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Ime prve je Pišón. To je ta, ki obkroža celotno deželo Havilá, kjer je zlato');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'in zlato te dežele je dobro; tam je bdelij in kamen oniks.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, '§ Ime druge reke je Gihon. Ta ista je ta, ki obkroža celotno deželo Etiopijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, '§ Ime tretje reke je Hidekel. To je ta, ki gre proti vzhodu Asirije. In četrta reka je Evfrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Gospod Bog je vzel človeka ter ga postavil v edenski vrt, da ga prirezuje in da ga varuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Gospod Bog je človeku zapovedal, rekoč: »Od vsakega vrtnega drevesa lahko prosto ješ,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'toda od drevesa spoznanja dobrega in zla, ne smeš jesti od njega, kajti na dan, ko boš od njega jedel, boš zagotovo umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Gospod Bog je rekel: » To ni dobro, da bi bil človek sam. Naredil mu bom pomoč, primerno zanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Iz tal je Gospod Bog oblikoval vsako poljsko žival in vsako zračno perjad in jih privedel k Adamu, da vidi, kako jih bo poimenoval. In kakorkoli je Adam vsako živo ustvarjeno bitje poimenoval, to je bilo njeno ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Adam je dal imena vsej živini, zračni perjadi in vsaki poljski živali, toda za Adama ni bilo najti pomoči, primerne zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Gospod Bog je storil, da je na Adama padlo globoko spanje in je zaspal. Vzel je eno izmed njegovih reber ter namesto le-tega zaprl meso');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'in [iz] rebra, ki ga je Gospod Bog vzel iz človeka, je naredil žensko in jo privedel k človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Adam je rekel: »To je sedaj kost iz mojih kosti in meso iz mojega mesa. Imenovala se bo Ženska, ker je bila vzeta iz Moškega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Zatorej bo moški zapustil svojega očeta in svojo mater in se bo trdno pridružil svoji ženi in oba bosta eno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Oba sta bila naga, mož in njegova žena in ni ju bilo sram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Torej kača [pa] je bila bolj premetena kakor katerakoli izmed poljskih živali, ki jih je Gospod Bog naredil. In rekla je ženski: »Da, ali je Bog res rekel: ›Ne bosta jedla od vsakega vrtnega drevesa?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'In ženska je rekla kači: »Midva lahko jeva od sadja vrtnih dreves,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'toda o sadu drevesa, ki je v sredi vrta, je Bog rekel: ›Ne bosta jedla od njega niti se ga ne bosta dotikala, da ne bi umrla.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Kača je ženski rekla: »Zagotovo ne bosta umrla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, '§ kajti Bog ve, da se bodo na dan, ko bosta od njega jedla, vajine oči potem odprle in bosta kakor bogovi, poznavajoč dobro in zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'In ko je ženska videla, da je bilo drevo dobro za jed in da je bilo prijetno očem in da si je drevesa želeti, da naredi nekoga modrega, je vzela od njegovega sadu in jedla ter dala tudi svojemu soprogu, [ki je bil] z njo, in on je jedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Oči so se obema odprle in spoznala sta, da sta bila naga. Skupaj sta sešila figove liste ter si naredila predpasnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'In zaslišala sta šum Gospoda Boga, ki je v svežini dneva hodil po vrtu, in Adam ter njegova žena sta se pred prisotnostjo Gospoda Boga skrila med vrtna drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Gospod Bog je zaklical Adamu in mu rekel: »Kje si?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Ta je rekel: »Zaslišal sem tvoj šum na vrtu in sem se zbal, ker sem bil nag, in sem se skril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Rekel je: »Kdo ti je povedal, da si bil nag? Mar si jedel od drevesa, od katerega sem ti zapovedal, da ne bi smel jesti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Mož je rekel: »Ženska, ki si mi jo dal, da je z menoj, ona mi je dala od drevesa in sem jedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Gospod Bog je rekel ženski: »Kaj je to, kar si storila?« Ženska je rekla: »Kača me je preslepila in sem jedla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Gospod Bog je rekel kači: »Ker si to storila, si prekleta nad vso živino in nad vsako poljsko živaljo. Po svojem trebuhu boš šla in prah boš jedla vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, '§ Postavil bom sovraštvo med teboj in žensko in med tvoje seme in njeno seme; to ti zdrobi glavo, ti pa boš ranila njegovo peto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ženski je rekel: »Silno bom pomnožil tvojo bridkost in tvoje spočetje. V bridkosti boš rojevala otroke, in tvoje hrepenenje bo k tvojemu soprogu in on bo vladal nad teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Adamu pa je rekel: »Ker si prisluhnil glasu svoje žene in si jedel od drevesa, o katerem sem ti zapovedal, rekoč: ›Ne boš jedel od njega;‹ prekleta so tla zaradi tebe, v bridkosti boš jedel od le-teh vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Tudi trnje in osat ti bodo obrodila; in poljsko zelišče boš jedel;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'v potu svojega obraza boš jedel kruh, dokler se ne vrneš v tla, kajti od tam si bil vzet, kajti prah si in v prah se boš vrnil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Adam je svojo ženo imenoval Eva; ker je bila mati vseh živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Adamu in njegovi ženi je Gospod Bog naredil plašča iz kož ter ju oblekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Gospod Bog je rekel: »Glej, človek je postal kakor eden izmed nas, da pozna dobro in zlo. In sedaj, da ne iztegne svoje roke in vzame tudi od drevesa življenja ter jé in živi na veke,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'ga je Gospod Bog zato odposlal iz edenskega vrta, da orje tla, iz katerih je bil vzet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, '§ Tako je izgnal človeka in na vzhodu edenskega vrta namestil kerube in ognjen meč, ki obrača vsako pot, da varuje pot drevesa življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Adam je spoznal svojo ženo Evo in ta je spočela ter rodila Kajna in rekla: »Dobila sem človeka od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'In ponovno je rodila njegovega brata Abela. In Abel je bil čuvaj ovc, toda Kajn je bil orač tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Tekom časa se je pripetilo, da je Kajn od sadu tal prinesel daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'In tudi Abel je prinesel prvence od svojega tropa in od njihove tolšče. In Gospod je imel spoštovanje do Abela in njegove daritve,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'toda do Kajna in njegove daritve [pa] ni imel spoštovanja. In Kajn je bil zelo ogorčen in njegovo obličje je upadlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Gospod je rekel Kajnu: »Zakaj si ogorčen? In zakaj je tvoje obličje upadlo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Če delaš dobro ali ne boš sprejet? Če pa ne delaš dobro, greh leži pri vratih. Njegovo poželenje naj bo k tebi, ti pa boš vladal nad njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Kajn je govoril s svojim bratom Abelom, in ko sta bila na polju, se je pripetilo, da se je Kajn dvignil zoper svojega brata Abela in ga ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Gospod je rekel Kajnu: »Kje je tvoj brat, Abel?« On pa je rekel: »Ne vem. Sem mar jaz čuvaj svojega brata?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Rekel je: »Kaj si storil? Glas krvi tvojega brata iz tal vpije k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Sedaj si preklet pred zemljo, ki je odprla svoja usta, da iz tvoje roke sprejme kri tvojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Ko boš oral tla, ti odslej ne bodo obrodila svoje moči; na zemlji boš ubežnik in potepuh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Kajn je Gospodu rekel: »Moja kazen je večja, kakor jo lahko prenesem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Glej, danes si me napodil izpred obličja zemlje, in skrit bom pred tvojim obličjem, in na zemlji bom ubežnik ter potepuh; in zgodilo se bo, da me bo ubil vsak, kdor me najde.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Gospod mu je rekel: »Zatorej kdorkoli ubije Kajna, bo nanj nadeto sedemkratno maščevanje.« In Gospod je na Kajna namestil znamenje, da kdorkoli ga najde, ga ne bi ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kajn je odšel izpred Gospodove prisotnosti in prebival v deželi Nod, vzhodno od Edena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Kajn je spoznal svojo ženo in ta je spočela ter rodila Henoha. Ta je zgradil mesto in ime mesta imenoval Henoh, po imenu svojega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Henohu se je rodil Irád, in Irád je zaplodil Mehujaéla, in Mehujaél je zaplodil Metušaéla, in Metušaél je zaplodil Lameha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lameh si je vzel dve ženi: ime prve je bilo Ada, ime druge pa Cila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada je rodila Jabála; ta je bil oče teh, ki prebivajo v šotorih in teh, ki imajo živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Ime njegovega brata je bilo Jubál; bil je oče vseh teh, ki prijemajo harfo in piščal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Cila pa je rodila tudi Tubál Kajina, učitelja vsakega rokodelca z bronom in železom, in Tubál Kajinova sestra je bila Naáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lameh je rekel svojima ženama, Adi in Cili: »Poslušajta moj glas, vidve, Lamehovi ženi, prisluhnita mojemu govoru, kajti umoril sem človeka, ki mi prizadeva rane in mladeniča, za mojo rano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Če bo Kajn sedemkrat maščevan, resnično, Lameh [pa] sedeminsedemdesetkrat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam je spet spoznal svojo ženo in rodila je sina in njegovo ime je imenovala Set. »Kajti Bog,« je rekla, »mi je določil drugega potomca namesto Abela, ki ga je ubil Kajn.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'In Setu, tudi njemu se je rodil sin, in njegovo ime je imenoval Enóš. Potem so ljudje začeli klicati Gospodovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'To je knjiga Adamovih rodov. Na dan, ko je Bog ustvaril človeka, ga je naredil po Božji podobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Moškega in žensko ju je ustvaril in ju blagoslovil in njuno ime imenoval Adam, na dan, ko sta bila ustvarjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Adam je živel sto trideset let in zaplodil sina po svoji lastni podobnosti, po svoji podobi in imenoval ga je Set.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Adamovih dni, potem ko je zaplodil Seta, je bilo osemsto let, in zaplodil je sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Vseh dni, ko je Adam živel, je bilo devetsto trideset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set je živel sto pet let ter zaplodil Enóša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Potem ko je Set zaplodil Enóša, je živel osemsto sedem let ter zaplodil sinove in hčere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'in vseh Setovih dni je bilo devetsto dvanajst let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enóš je živel devetdeset let in zaplodil Kenána,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'in potem, ko je Enóš zaplodil Kenána, je živel osemsto petnajst let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Vseh Enóševih dni je bilo devetsto pet let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenán je živel sedemdeset let ter zaplodil Mahalaléla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Potem ko je Kenán zaplodil Mahalaléla, je živel osemsto štirideset let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Vseh Kenánovih dni je bilo devetsto deset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalalél je živel petinšestdeset let ter zaplodil Jereda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Potem ko je Mahalalél zaplodil Jereda, je živel osemsto trideset let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Vseh Mahalalélovih dni je bilo osemsto petindevetdeset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jered je živel sto dvainšestdeset let ter zaplodil Henoha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Potem ko je Jered zaplodil Henoha, je živel osemsto let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Vseh Jeredovih dni je bilo devetsto dvainšestdeset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoh je živel petinšestdeset let ter zaplodil Matuzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Potem ko je Henoh zaplodil Matuzalema, je tristo let hodil z Bogom ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Vseh Henohovih dni je bilo tristo petinšestdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henoh je hodil z Bogom in ni ga bilo, kajti Bog ga je vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Matuzalem je živel sto sedeminosemdeset let in zaplodil Lameha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Potem ko je Matuzalem zaplodil Lameha, je živel sedemsto dvainosemdeset let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Vseh Matuzalemovih dni je bilo devetsto devetinšestdeset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lameh je živel sto dvainosemdeset let ter zaplodil sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Njegovo ime je imenoval Noe, rekoč: »Ta isti nas bo tolažil, glede našega dela in garanja naših rok, zaradi tal, ki jih je Gospod preklel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Potem ko je Lameh zaplodil Noeta, je živel petsto petindevetdeset let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Vseh Lamehovih dni je bilo sedemsto sedeminsedemdeset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noe je bil star petsto let in Noe je zaplodil Sema, Hama ter Jafeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Pripetilo se je, ko so se na obličju zemlje ljudje začeli množiti in so se jim rojevale hčere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'da so Božji sinovi videli človeške hčere, da so bile lepe in so si jih jemali za žene od vseh, ki so si jih izbrali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, '§ Gospod je rekel: »Moj duh se ne bo vedno prepiral s človekom, kajti on je prav tako meso, vendar bo njegovih dni sto dvajset let.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, '§ Takrat, v tistih dneh, so bili na zemlji velikani; in tudi potem, ko so Božji sinovi vstopali noter v človeške hčere in so jim te rodile otroke, so ti isti postali mogočni možje, ki so bili iz davnine, možje z ugledom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Bog pa je videl, da je bila človekova zlobnost na zemlji velika in da je bila vsaka miselna zamisel njegovega srca nenehno samo zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'To je pokesalo Gospoda, da je na zemlji naredil človeka in to ga je užalostilo pri njegovem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Gospod je rekel: »Uničil bom človeka, ki sem ga ustvaril, izpred obličja zemlje,« tako človeka kakor žival in plazečo stvar ter perjad neba, kajti to me je pokesalo, da sem jih naredil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Toda Noe je našel milost v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'To so Noetovi rodovi. Noe je bil pravičen človek in popoln v svojih rodovih in Noe je hodil z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Noe je zaplodil tri sinove: Sema, Hama in Jafeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Tudi zemlja je bila izprijena pred Bogom in zemlja je bila napolnjena z nasiljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Bog je pogledal na zemljo in glej, bila je izprijena, kajti vse meso na zemlji je izpridilo svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, '§ Bog je Noetu rekel: »Konec vsega mesa je prišel predme, kajti zemlja je po njih napolnjena z nasiljem, in glej, uničil jih bom, z zemljo [vred].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, '§ Naredi si ladjo iz gofrovega lesa. V ladji boš naredil prostore in jo zunaj in znotraj zasmolil s smolo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'In to je oblika, po kateri jo boš naredil: dolžina ladje naj bo tristo komolcev, njena širina petdeset komolcev in njena višina trideset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, '§ Ladji boš naredil okno in komolec nad tem jo boš končal. Vrata ladje boš napravil na njeni strani; s spodnjim, drugim in tretjim nadstropjem jo boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Glej jaz, celó jaz, privedem na zemljo poplavo vodá, da uničim vse meso, v katerem je dih življenja izpod neba in vsaka stvar, ki je na zemlji, bo umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Toda s teboj bom vzpostavil svojo zavezo, in prišel boš na ladjo, ti in tvoji sinovi in tvoja žena in žene tvojih sinov s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Od vsake žive stvari, od vsega mesa, boš s seboj na ladjo privedel [po] dva od vsake vrste, da jih s teboj obvaruješ žive; naj bodo samec in samica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Od perjadi po njihovi vrsti in od živine po njihovi vrsti, od vsake zemeljske plazeče stvari po njeni vrsti, [po] dva od vsake vrste bosta prišla k tebi, da ju obvaruješ živa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'K sebi vzemi od vse hrane, ki se jé in jo boš zbral k sebi, in ta bo za hrano zate in zanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Noe je storil tako; glede na vse, kar mu je Bog ukazal, je storil tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Gospod je rekel Noetu: »Pridi ti in vsa tvoja hiša v ladjo, kajti pred seboj sem te videl pravičnega v tem rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Od vsake čiste živali boš vzel k sebi po sedmero, samca in njegovo samico. Od živali, ki niso čiste, po dvoje, samca in njegovo samico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Tudi od perjadi neba po sedmero, samca in samico, da na obličju vse zemlje ohraniš seme živo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Kajti še sedem dni in povzročil bom, da na zemljo dežuje štirideset dni in štirideset noči; in vsako živo snov, ki sem jo naredil, bom uničil izpred obličja zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Noe je storil glede na vse, kar mu je Gospod zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noe je bil star šeststo let, ko je bila na zemlji poplava vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Noe je zaradi poplavnih vodá vstopil v ladjo in njegovi sinovi in njegova žena in žene njegovih sinov z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Od čistih živali in od živali, ki niso čiste in od perjadi in od vsake stvari, ki se plazi na zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'so po dve in dve vstopile k Noetu v ladjo, samec in samica, kakor je Bog zapovedal Noetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Po sedmih dneh pa se je pripetilo, da so bile na zemlji poplavne vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'V šeststotem letu Noetovega življenja, v drugem mesecu, sedemnajsti dan meseca, istega dne so izbruhnili vsi studenci velike globine in okna neba so bila odprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'In dež je bil na zemlji štirideset dni in štirideset noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Prav isti dan so vstopili v ladjo Noe ter Sem in Ham in Jafet, Noetovi sinovi in Noetova žena in z njim tri žene njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Oni in vsaka žival po njeni vrsti in vsa živina po njeni vrsti in vsaka plazeča stvar, ki se plazi na zemlji, po njeni vrsti in vsaka perjad po njeni vrsti, vsaka ptica od vsake sorte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Vstopile so k Noetu v ladjo, [po] dve in dve od vsega mesa, v katerem je dih življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Te, ki so vstopile, so vstopile samec in samica od vsega mesa, kakor mu je Bog zapovedal. Gospod pa ga je zaprl noter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Na zemlji je bila poplava štirideset dni. Vode so narasle in podpirale ladjo in ta je bila dvignjena nad zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Vode so prevladale in silno narasle na zemlji in ladja je plula na obličju vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Vode so silno prevladale na zemlji in vsi visoki hribi, ki so bili pod celotnim nebom, so bili pokriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Vode so se dvignile [in] prevladale [za] petnajst komolcev in gore so bile pokrite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Umrlo je vse meso, ki se je gibalo na zemlji, tako od perjadi, od živine, od živali in od vsake plazeče stvari, ki se plazi na zemlji in vsakega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Vse, v čigar nosnicah je bil dih življenja, od vsega, kar [jih] je bilo na kopni zemlji, je umrlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Uničena je bila vsaka živa snov, ki je bila na obličju tal, tako človek kakor živina, plazeče stvari in perjad neba; in bile so uničene z zemlje. Živ je ostal samo Noe in tisti, ki so bili z njim na ladji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Vode so prevladovale na zemlji sto petdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Bog se je spomnil Noeta in vsake žive stvari in vse živine, ki je bila z njim v ladji in Bog je naredil veter, da je šel prek zemlje in vode so se znižale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Tudi studenci globin in okna neba so bili ustavljeni in dež z neba je bil zadržan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Vode so se nenehno vračale iznad zemlje in po koncu sto petdesetih dni so bile vode znižane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Ladja je obstala v sedmem mesecu, na sedemnajsti dan meseca, na gorah Araráta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'In vode so nenehno upadale do desetega meseca. V desetem mesecu, na prvi dan meseca, so bili vidni vrhovi gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Ob koncu štiridesetih dni se je pripetilo, da je Noe odprl okno ladje, ki jo je naredil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'in izpustil krokarja, ki je letal sem ter tja, dokler se vode iznad zemlje niso posušile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Od sebe je izpustil tudi golobico, da vidi, če so se vode znižale iznad obličja tal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'toda golobica ni našla počitka za podnožje svojega stopala in se je vrnila k njemu v ladjo, kajti vode so bile na obličju celotne zemlje. Potem je iztegnil svojo roko in jo prijel ter potegnil k sebi v ladjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Okleval pa je še drugih sedem dni in golobico ponovno izpustil iz ladje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Golobica je zvečer priletela k njemu, in glej, v njenem kljunu je bil odtrgan oljčni list. Tako je Noe spoznal, da so bile vode iznad zemlje znižane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Okleval je še drugih sedem dni in izpustil golobico, ki se ni več ponovno vrnila k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Pripetilo se je v šeststoprvem letu, v prvem mesecu, prvi dan meseca, [da] so se vode iznad zemlje posušile. Noe je odstranil pokrivalo ladje ter pogledal in glej, obličje tal je bilo suho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, '§ V drugem mesecu, na sedemindvajseti dan meseca, je bila zemlja suha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Bog je spregovoril Noetu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '»Pojdi iz ladje ti in tvoja žena in tvoji sinovi in žene tvojih sinov s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'S seboj privedi vsako živo stvar, ki je s teboj od vsega mesa, tako od perjadi kakor od živine in od vsake plazeče stvari, ki se plazi na zemlji, da se bodo na zemlji lahko obilno plodili in bodo rodovitni in se množili na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Noe se je izkrcal in njegovi sinovi in njegova žena in žene njegovih sinov z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Vsaka žival, vsaka plazeča stvar in vsaka perjad in karkoli se plazi na zemlji, po svojih vrstah, so se izkrcali iz ladje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noe je zgradil oltar Gospodu in vzel od vsake čiste živali in od vsake čiste perjadi ter na oltarju daroval žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Gospod je zavohal prijeten vonj in Gospod je v svojem srcu rekel: »Zaradi človeka tal ne bom več ponovno preklel, kajti zamisel človekovega srca je zla od njegove mladosti niti ne bom več ponovno udaril vsake žive stvari, kakor sem storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Dokler ostaja zemlja, čas setve in žetve in mraz in vročina in poletje in zima in dan in noč ne bodo prenehali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Bog je blagoslovil Noeta in njegove sinove ter jim rekel: »Bodite rodovitni in se množite ter na novo napolnite zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Strah pred vami in groza pred vami bo na vsaki zemeljski živali in na vsaki zračni perjadi, na vsem, kar se giba na zemlji in na vseh ribah morja; izročene so v vašo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Vsaka gibajoča stvar, ki živi, naj bo hrana za vas; celó kakor zelena zelišča, sem vam izročil vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Toda mesa z njegovim življenjem, ki je njegova kri, ne boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Zagotovo bom terjal vašo kri vaših življenj. Terjal jo bom iz roke vsake živali in iz človeške roke. Iz roke vsakega človekovega brata bom terjal človeško življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kdorkoli prelije človeško kri, bo po človeku prelita njegova kri, kajti človeka je naredil po Božji podobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vi pa bodite rodovitni in se množite, na zemlji obilno obrodite in se množite na njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Bog je spregovoril Noetu ter z njim njegovim sinovom, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '»Jaz, glejte, jaz vzpostavljam svojo zavezo z vami in z vašim zarodom za vami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'in z vsakim živim ustvarjenim bitjem, ki je z vami, od perjadi, od živine in od vsake zemeljske živali z vami; od vsega, kar prihaja iz ladje, do vsake zemeljske živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'In z vami bom vzpostavil svojo zavezo; niti vse meso ne bo več iztrebljeno s poplavnimi vodami niti ne bo več poplave, da uniči zemljo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Bog je rekel: »To je simbol zaveze, ki jo sklepam med seboj in vami in vsakim živim ustvarjenim bitjem, ki je z vami, za neprestane rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Svojo mavrico postavim v oblak in ta bo za simbol zaveze med menoj in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'In zgodilo se bo, ko nad zemljo privedem oblak, da bo mavrica vidna v oblaku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'in spomnil se bom svoje zaveze, ki je med menoj in vami in vsakim živim ustvarjenim bitjem od vsega mesa in vode ne bodo več postale poplava, da uničijo vse meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'In v oblaku bo mavrica in pogledal bom nanjo, da se bom lahko spomnil večne zaveze med Bogom in vsakim živim ustvarjenim bitjem od vsega mesa, ki je na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Bog je rekel Noetu: »To je simbol zaveze, ki sem jo utrdil med seboj in vsem mesom, ki je na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Noetovi sinovi, ki so se izkrcali iz ladje, so bili Sem, Ham in Jafet. Ham pa je Kánaanov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'To so trije Noetovi sinovi, in od njih je bila prekrita vsa zemlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'In Noe je začel biti poljedelec ter zasadil vinograd');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'in pil od vina in se napil in bil je nag v svojem šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Ham, Kánaanov oče, pa je videl nagoto svojega očeta in zunaj povedal svojima dvema bratoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Sem in Jafet sta vzela obleko in si jo položila na obe njuni rami in šla, obrnjena nazaj in pokrila nagoto njunega očeta. In njuna obraza sta bila obrnjena nazaj in nista videla očetove nagote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Noe se je prebudil iz svojega vina ter spoznal, kaj mu je storil njegov mlajši sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Rekel je: »Preklet bodi, Kánaan. Svojim bratom bo služabnik služabnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Rekel je: »Blagoslovljen bodi Semov Gospod Bog, Kánaan pa bo njegov služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Bog bo povečal Jafeta in prebival bo v Semovih šotorih, Kánaan pa bo njegov služabnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Noe je po poplavi živel tristo petdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Vseh Noetovih dni je bilo devetsto petdeset let, in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'To so torej rodovi Noetovih sinov, Sema, Hama in Jafeta, in tem so se po poplavi rodili sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jafetovi sinovi: Gomer, Magóg, Madáj, Javán, Tubál, Mešeh in Tirás.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Gomerjevi sinovi: Aškenáz, Rifát in Togarmá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Javánovi sinovi: Elišá in Taršíš, Kitéjec in Dodaním.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'S temi so bili otoki poganov razdeljeni po njihovih deželah, vsakdo po svojem jeziku, po svojih družinah, v svojih narodih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, '§ Hamovi sinovi: Kuš, Micrájim, Put in Kánaan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Kuševi sinovi: Sebá, Havilá, Sabtá, Ramá in Sabtehá. In Ramájeva sinova: Šebá in Dedán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kuš je zaplodil Nimróda. Ta je začenjal biti mogočen na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Bil je mogočen lovec pred Gospodom, zakaj rečeno je: »Celo kakor Nimród, mogočen lovec pred Gospodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Začetek njegovega kraljestva pa je bil Babel, Ereh, Akád in Kalne v šinárski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, '§ Iz tiste dežele je odšel proti Asúrju in zgradil Ninive ter mesta Rehobót, Kelah in');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Resen med Ninivami in Kelahom; isto je veliko mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Micrájim je zaplodil Ludima, Anamima, Lehabima, Nafthima,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrusima, Kasluhima (iz katerega je prišel Filistejec) in Kaftorima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kánaan je zaplodil Sidóna, svojega prvorojenca, Heta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebusejca, Amoréjca, Girgašéjca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hivéjca, Arkejca, Sinéjca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvadéjca, Cemaréjca in Hamatéjca, in nato so bile družine Kánaancev razširjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Meja Kánaancev je bila od Sidóna, ko prideš v Gerár, do Gaze; ko greš v Sódomo, Gomóro, Admo, in Cebojím, celó do Leše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'To so Hamovi sinovi po svojih družinah, po svojih jezikih, svojih deželah in po svojih narodih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Tudi Semu, očetu vseh Eberjevih otrok, Jafetovemu starejšemu bratu, celó njemu so bili rojeni otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Semovi otroci: Elám, Asúr, Arpahšád, Lud in Arám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Arámovi otroci: Uc, Hul, Geter in Maš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpahšád je zaplodil Šelaha, in Šelah je zaplodil Eberja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eberju sta bila rojena dva sinova. Enemu je bilo ime Peleg, kajti v njegovih dneh je bila zemlja razdeljena in ime njegovega brata je bilo Joktán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktán je zaplodil Almodáda, Šelefa, Hacarmáveta, Jeraha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoráma, Uzála, Diklá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obála, Abimaéla, Šebá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofírja, Havilá in Jobába. Vsi ti so bili Joktánovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Njihovo prebivališče je bilo od Meše, ko greš k Sefárju, vzhodnemu gorovju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'To so Semovi sinovi po svojih družinah, po svojih jezikih, po svojih deželah, po svojih narodih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'To so družine Noetovih sinov po svojih rodovih v svojih narodih in z njimi so bili po poplavi razdeljeni narodi na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Celotna zemlja pa je bila enojezična in enega govora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Pripetilo se je, ko so potovali od vzhoda, da so našli ravnino v šinárski deželi in tam so prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, '§ Rekli so drug drugemu: »Pojdimo, delajmo opeko in jih temeljito žgimo.« In opeko so imeli za kamen, blato pa so imeli za malto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Rekli so: »Pojdimo, zgradimo si mesto in stolp, čigar vrh bo lahko segal do neba in naredimo si ime, da ne bomo razkropljeni po obličju celotne zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Gospod pa je prišel dol, da vidi mesto in stolp, ki so ga gradili človeški otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Gospod je rekel: »Glej, ljudstvo je eno in vsi imajo en jezik in to so začeli delati in zdaj ne bo nič zadržano pred njimi, kar so si domislili storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Pojdimo, gremo dol in jim tam zmešajmo njihov jezik, da ne bodo mogli razumeti govora drug drugega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Tako jih je Gospod od tam razkropil naokoli po obličju celotne zemlje in prenehali so graditi mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Zato je ime tega mesta imenovano Babel, ker je tam Gospod zmešal jezik vse zemlje, in od tam jih je Gospod razkropil naokoli po obličju vse zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, '§ To so Semovi rodovi. Sem je bil star sto let in dve leti po poplavi je zaplodil Arpahšáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Potem ko je Sem zaplodil Arpahšáda, je živel petsto let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpahšád je živel petintrideset let ter zaplodil Šelaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Arpahšád je, potem ko je zaplodil Šelaha, živel štiristo tri leta ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Šelah je živel trideset let ter zaplodil Eberja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Šelah je, potem ko je zaplodil Eberja, živel štiristo tri leta ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber je živel štiriintrideset let ter zaplodil Pelega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Eber je, potem ko je zaplodil Pelega, živel štiristo trideset let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg je živel trideset let ter zaplodil Reguja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Peleg je, potem ko je zaplodil Reguja, živel dvesto devet let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu je živel dvaintrideset let ter zaplodil Serúga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Regu je, potem ko je zaplodil Serúga, živel dvesto sedem let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serúg je živel trideset let ter zaplodil Nahórja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Serúg je, potem ko je zaplodil Nahórja, živel dvesto let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahór je živel devetindvajset let ter zaplodil Teraha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Nahór je, potem ko je zaplodil Teraha, živel sto devetnajst let ter zaplodil sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terah je živel sedemdeset let ter zaplodil Abrama, Nahórja in Harána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Torej to so Terahovi rodovi. Terah je zaplodil Abrama, Nahórja in Harána; Harán pa je zaplodil Lota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Harán je umrl pred svojim očetom Terahom v deželi svojega rojstva, v Uru Kaldejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram in Nahór sta si vzela ženi. Ime Abramove žene je bilo Sarája; in ime Nahórjeve žene Milka, hči Harána, Milkinega očeta in Jiskinega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Toda Sarája je bila jalova; ni imela nobenega otroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Terah je vzel Abrama, svojega sina in vnuka Lota, Haránovega sina in svojo snaho Sarájo, ženo svojega sina Abrama in odšli so iz Ura Kaldejcev, da gredo v kánaansko deželo in prišli so v Harán ter tam prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Terahovih dni je bilo dvesto pet let, in Terah je umrl v Haránu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Gospod je torej rekel Abramu: »Pojdi ven iz svoje dežele in iz svojega sorodstva in iz hiše svojega očeta v deželo, ki ti jo bom pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Iz tebe bom naredil velik narod in blagoslovil te bom in tvoje ime naredil veliko in ti boš blagoslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Blagoslovil bom tiste, ki te blagoslavljajo in preklel tistega, ki te preklinja, in v tebi bodo blagoslovljene vse družine zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Tako je Abram odšel, kakor mu je Gospod spregovoril in Lot je šel z njim. Abram pa je bil star petinsedemdeset let, ko je odšel iz Harána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram je vzel svojo ženo Sarájo in Lota, sina svojega brata ter vse njuno imetje, ki sta ga zbrala in duše, ki sta jih pridobila v Haránu in šli so, da gredo v kánaansko deželo in prišli so v kánaansko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram je šel skozi deželo do kraja Sihem, na Moréjevo ravnino. In takrat je bil v deželi Kánaanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Gospod se je prikazal Abramu ter rekel: »To deželo bom dal tvojemu potomcu.« In tam je zgradil oltar Gospodu, ki se mu je prikazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Od tam se je prestavil h gori na vzhodu Betela ter postavil svoj šotor in Betel je imel na zahodu, Aj pa na vzhodu. Tam je zgradil oltar Gospodu ter klical h Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, '§ Abram je potoval in še vedno šel proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'V deželi pa je bila lakota in Abram je odšel dol v Egipt, da tam začasno prebiva, kajti lakota v deželi je bila boleča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Toda pripetilo se je, ko je prišel blizu, da vstopi v Egipt, da je rekel svoji ženi Saráji: »Glej, torej vem, da si na pogled lepa ženska,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'zato se bo zgodilo, ko te bodo Egipčani zagledali, da bodo rekli: ›To je njegova žena‹ in bodo mene ubili, toda tebe bodo ohranili pri življenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Reci, prosim te, [da] si moja sestra, da bo zaradi tebe lahko dobro z menoj in bo moja duša živela zaradi tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Pripetilo se je, ko je Abram prišel v Egipt, da so Egipčani zagledali žensko, da je bila zelo lepa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Tudi faraonovi princi so jo videli in jo priporočili pred faraonom in ženska je bila vzeta v faraonovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'In zaradi nje je [z] Abramom dobro ravnal, in imel je ovce, vole, osle, sluge, dekle, oslice in kamele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Gospod pa je zaradi Abramove žene Saráje trpinčil faraona in njegovo hišo z velikimi nadlogami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Faraon je poklical Abrama ter mu rekel: »Kaj je to, kar si mi storil? Zakaj mi nisi povedal, da je bila tvoja žena?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '§ Zakaj si rekel: ›Moja sestra je?‹ Tako bi jo lahko vzel k sebi za ženo. Zdaj torej glej svojo ženo, vzemi jo in pojdi svojo pot.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Faraon je glede njega zapovedal svojim ljudem in poslali so ga proč in njegovo ženo in vse, kar je imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, '§ Abram se je dvignil iz Egipta na jug, on in njegova žena in vse, kar je imel in Lot z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram je bil zelo bogat z živino, s srebrom in z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, '§ Odšel je na svoja potovanja od juga celó do Betela, na kraj, kjer je bil od začetka njegov šotor, med Betelom in Ajem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'na kraj z oltarjem, ki ga je tam najprej naredil in tam je Abram klical h Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Tudi Lot, ki je odšel z Abramom, je imel trope, črede in šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Zemlja pa ju ni mogla podpirati, da bi lahko prebivala skupaj, kajti njuno imetje je bilo veliko, tako da nista mogla prebivati skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Bil pa je prepir med čredniki Abramove živine in čredniki Lotove živine, in takrat so v deželi prebivali Kánaanci in Perizéjci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Abram je rekel Lotu: »Naj ne bo prepira, prosim te, med menoj in teboj in med mojimi čredniki in med tvojimi čredniki, kajti mi smo bratje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Mar ni vsa dežela pred teboj? Prosim te, loči se od mene. Če boš vzel levico, potem bom odšel na desno, ali če ti odideš na desnico, potem bom jaz odšel na levo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, '§ Lot je povzdignil svoje oči in pogledal vso jordansko ravnino, ki je bila, preden je Gospod uničil Sódomo in Gomóro, vsepovsod dobro namakana, kakor Gospodov vrt, podobna egiptovski deželi, ko prideš do Coarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Potem si je Lot izbral vso Jordansko ravnino in Lot je odpotoval vzhodno in ločila sta se drug od drugega, eden od drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram je prebival v kánaanski deželi, Lot pa je prebival v mestih ravnine in svoj šotor postavljal v smeri Sódome.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Toda sódomski možje so bili zlobni in silni grešniki pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Gospod je rekel Abramu, potem ko je bil Lot ločen od njega: »Dvigni torej svoje oči in poglej, od kraja, kjer si, proti severu, proti jugu, proti vzhodu in proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Kajti vso deželo, ki jo vidiš, bom dal tebi in tvojemu potomstvu na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Tvojega semena bom naredil kakor zemeljskega prahu, tako da če človek lahko prešteje zemeljski prah, potem bo prešteto tudi tvoje seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Vstani, prehodi deželo po njeni dolžini in po njeni širini, kajti tebi jo bom dal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, '§ Potem je Abram odstranil svoj šotor in prišel ter prebival na mamrejski ravnini, ki je v Hebrónu in tam zgradil oltar Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, '§ Pripetilo se je v dneh šinárskega kralja Amraféla, elasárskega kralja Arjóha, elámskega kralja Kedorlaómerja in tidálskega kralja narodov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'da so se ti vojskovali s sódomskim kraljem Berom in gomórskim kraljem Biršájem, admaškim kraljem Šinábom, cebojímskim kraljem Šeméberjem in kraljem Bele, kar je Coar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Vsi ti so se skupaj srečali v Sidímski dolini, kar je slano morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dvanajst let so služili Kedorlaómerju, v trinajstem letu pa so se uprli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'V štirinajstem letu je prišel Kedorlaómer ter kralji, ki so bili z njim in udarili Rafájevce pri Ašterót Karnájimu in Zuzéjce pri Hamu in Emejce v Šavé Kirjatájimu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'in Horéjce na njihovem gorovju Seír, do El Párana, ki je poleg divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, '§ In vrnili so se ter prišli do En Mišpáta, kar je Kadeš in udarili vso deželo Amalečanov in tudi Amoréjce, ki so prebivali v Hacecón Tamáru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'In odšli so sódomski kralj, gomórski kralj, admaški kralj, cebojímski kralj in belaški kralj (isti je coarski) in se združili v bitki z njimi v Sidímski dolini');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, '§ z elámskim kraljem Kedorlaómerjem, s Tidálom, kraljem narodov, šinárskim kraljem Amrafélom in elasárskim kraljem Arjóhom: štirje kralji proti petim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, '§ Sidímska dolina pa je bila polna blatnih jam in sódomski kralj in gomórski kralj sta pobegnila in padla tja. Tisti, ki so preostali, pa so pobegnili h goram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Pobrali so vse dobrine Sódome in Gomóre in ves njihov živež ter odšli svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Vzeli so Lota, sina Abramovega brata, ki je prebival v Sódomi in njegove dobrine ter odrinili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, '§ Prišel pa je nekdo, ki je pobegnil in povedal Hebrejcu Abramu, kajti ta je prebival na ravnini Amoréjca Mamreja, Eškólovega in Anêrjevega brata; in ti so bili zavezniki z Abramom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Ko je Abram slišal, da je njegov brat ujet, je oborožil tristo osemnajst svojih izurjenih služabnikov, rojenih v njegovi lastni hiši in jih zasledoval do Dana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, '§ Ponoči se je razdelil zoper njih, on in njegovi služabniki in jih udaril in jih zasledoval do Hobe, ki je na levi roki od Damaska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Vse dobrine je privedel nazaj in prav tako je privedel nazaj svojega brata Lota in njegove dobrine in tudi žene in ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Sódomski kralj pa je odšel ven, da ga sreča po njegovi vrnitvi iz pokola Kedorlaómerja in kraljev, ki so bili z njim pri dolini Šavé, ki je kraljeva dolina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melkízedek, kralj v Salemu, je prinesel kruh in vino in ta je bil duhovnik najvišjega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, '§ Blagoslovil ga je ter rekel: »Blagoslovljen bodi Abram od najvišjega Boga, lastnika neba in zemlje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'in blagoslovljen bodi najvišji Bog, ki je tvoje sovražnike izročil v tvojo roko.« In on mu je dal desetine od vsega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, '§ Sódomski kralj pa je rekel Abramu: »Daj mi osebe, dobrine pa vzemi zase.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram je rekel sódomskemu kralju: »Svojo roko sem dvignil h Gospodu, najvišjemu Bogu, lastniku neba in zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'da ne bom vzel ne od nitke niti ne do vezalke in da ne bom vzel nobene stvari, ki je tvoja, da ne bi ti rekel: ›Jaz sem Abrama naredil bogatega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Samó tisto, kar so mladeniči pojedli in delež ljudi, ki so šli z menoj, Anêr, Eškól in Mamre; naj si vzamejo svoj delež.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Po teh stvareh je Gospodova beseda prišla Abramu v videnju, rekoč: »Ne boj se, Abram. Jaz sem tvoj ščit in tvoja silno velika nagrada.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram je rekel: »Gospod Bog, kaj mi hočeš dati, glede na to, da odhajam brez otrok in je oskrbnik moje hiše Eliézer iz Damaska?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram je rekel: »Glej, nobenega potomca mi nisi dal in glej, nekdo, rojen v moji hiši, je moj dedič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Glej, Gospodova beseda je prišla k njemu, rekoč: »Ta ne bo tvoj dedič, temveč tisti, ki bo izšel iz tvoje lastne notranjosti, bo tvoj dedič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Privedel ga je daleč naprej ter rekel: »Poglej zdaj proti nebu in štej zvezde, če jih lahko prešteješ.« Rekel mu je: »Tako bo tvoje seme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Veroval je v Gospoda in on mu je to štel za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Rekel mu je: »Jaz sem Gospod, ki te je privedel iz Ura Kaldejcev, da ti dam to deželo, da jo podeduješ.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Rekel je: »Gospod Bog, po čem bom spoznal, da jo bom podedoval?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, '§ Rekel mu je: »Vzemi mi triletno telico, triletno kozo, triletnega ovna, grlico in mladega goloba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Ta je k sebi vzel vse to in jih na sredini razpolovil in vsak kos položil nasproti drugemu, toda ptic ni razpolovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Ko je na trupla prišla perjad, jo je Abram odganjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'In ko je sonce zahajalo, je na Abrama padlo globoko spanje in glej, nanj je padla groza velike teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Abramu je rekel: »Zagotovo vedi, da bo tvoje potomstvo tuje v deželi, ki ni njihova in jim bo služilo, oni pa jih bodo mučili štiristo let');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'in prav tako bom sodil ta narod, ki mu bodo služili. Potem pa bodo izšli z velikim imetjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Ti pa boš v miru odšel k svojim očetom; pokopan boš v dobri visoki starosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Toda v četrtem rodu bodo ponovno prišli sèm, kajti krivičnost Amoréjcev še ni dopolnjena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Pripetilo se je, da ko je sonce zašlo in je bila tema, glej kadečo talilno peč in gorečo svetilko, ki sta šli med temi kosi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Na isti dan je Gospod z Abramom sklenil zavezo, rekoč: »Tvojemu semenu sem dal to deželo, od egiptovske reke do vélike reke, reke Evfrata:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kenéjce, Kenázovce, Kadmonéjce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Hetejce, Perizéjce, Rafájevce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Amoréjce, Kánaance, Girgašéjce in Jebusejce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Torej Sarája, Abramova žena, mu ni rodila otrok. Imela pa je pomočnico, Egipčanko, ki ji je bilo ime Hagára.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, '§ Sarája je Abramu rekla: »Glej torej, Gospod me je zadržal pred rojevanjem. Prosim te, pojdi noter v mojo služkinjo, lahko se zgodi, da dosežem otroke prek nje.« Abram je prisluhnil Sarájinemu glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Sarája, Abramova žena, je vzela Hagáro, svojo egipčansko služabnico, potem ko je Abram deset let prebival v kánaanski deželi in jo dala svojemu soprogu Abramu, da postane njegova žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Šel je noter v Hagáro in ona je spočela. Ko pa je videla, da je spočela, je bila njena gospodarica prezirana v njenih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Sarája je rekla Abramu: »Moja žalitev bodi na tebi. Svojo služabnico sem dala v tvoje naročje, ko pa je videla, da je spočela, sem bila v njenih očeh prezirana. Gospod [naj] sodi med menoj in teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Toda Abram je rekel Saráji: »Glej, tvoja služabnica je v tvoji roki. Stôri ji, kakor ti ugaja.« Ko pa je Sarája z njo trdo postopala, je ta pobegnila pred njenim obrazom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Gospodov angel jo je našel pri vodnem studencu v divjini, pri izviru, na poti v Šur.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Rekel je: »Hagára, Sarájina služabnica, od kod prihajaš? Kam hočeš oditi?« Rekla je: »Pobegnila sem izpred obličja svoje gospodarice Saráje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Gospodov angel ji je rekel: »Vrni se k svoji gospodarici in se podrêdi pod njene roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Gospodov angel ji je rekel: »Tvoje seme bom silno pomnožil, da le-to zaradi množice ne bo preštevno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Gospodov angel ji je rekel: »Glej, ti si z otrokom in rodila boš sina in imenovala ga boš Izmael, ker je Gospod uslišal tvojo stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'In on bo divji človek, njegova roka bo zoper vsakega človeka in roka vsakega človeka zoper njega in prebival bo v prisotnosti vseh svojih bratov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Klicala je ime Gospoda, ki ji je govoril: »Ti, Bog, me vidiš,« kajti rekla je, »sem tudi tukaj gledala za tistim, ki me vidi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Zatorej se je izvir imenoval Beêr Laháj Roí; glej, ta je med Kadešem in Beredom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Hagára je Abramu rodila sina in Abram je svojega sina, ki ga je rodila Hagára, imenoval Izmael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Ko je Hagára Abramu rodila Izmaela, je bil Abram star šestinosemdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Ko je bil Abram star devetindevetdeset let, se je Gospod prikazal Abramu in mu rekel: »Jaz sem Vsemogočni Bog, hodi pred menoj in bodi popoln.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Svojo zavezo bom sklenil med seboj in teboj in te silno namnožil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Abram je padel na svoj obraz in Bog je z njim govoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '»Kar se mene tiče, glej, moja zaveza je s teboj in ti boš oče mnogih narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Niti se tvoje ime ne bo več imenovalo Abram, temveč bo tvoje ime Abraham, kajti naredil sem te za očeta mnogih narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Naredil te bom silno rodovitnega in iz tebe bom naredil narode in iz tebe bodo prišli kralji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Vzpostavil bom svojo zavezo med seboj in teboj in tvojim semenom za teboj po njihovih rodovih za večno zavezo, da bom Bog tebi in tvojemu semenu za teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Tebi in tvojemu semenu za teboj bom dal deželo, v kateri si tujec, vso kánaansko deželo, za večno posest in jaz bom njihov Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Bog je rekel Abrahamu: »Držal se boš moje zaveze, torej ti in tvoje seme za teboj po njihovih rodovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'To je moja zaveza, ki se je boste držali, med menoj in teboj in tvojim potomstvom za teboj: vsak fantek med vami naj bo obrezan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obrezali boste meso svoje prednje kožice in to bo simbol zaveze med menoj in vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Kdor je star osem dni, naj bo med vami obrezan, vsak fantek po svojih rodovih, kdor je rojen v hiši ali kupljen z denarjem kateregakoli tujca, ki ni iz tvojega potomstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Kdor je rojen v tvoji hiši in kdor je kupljen z denarjem, mora biti obrezan in moja zaveza bo v vašem mesu za večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Neobrezan fantek, katerega meso njegove prednje kožice ni obrezano, naj bo ta duša iztrebljena iz svojega ljudstva; prelomil je mojo zavezo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Bog je rekel Abrahamu: »Kar se tiče tvoje žene Saráje, njenega imena ne boš več klical Sarája, temveč Sara bo njeno ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Blagoslovil jo bom in ti tudi od nje dal sina. Da, blagoslovil jo bom in ona bo mati narodov, kralji ljudstev bodo iz nje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Potem je Abraham padel na svoj obraz, se zasmejal in v svojem srcu rekel: »Ali bo otrok rojen njemu, ki je star sto let? In ali bo Sara, ki je stara devetdeset let, rodila?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Abraham je rekel Bogu: »Oh, da bi Izmael lahko živel pred teboj!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Bog je rekel: »Tvoja žena Sara ti bo zares rodila sina in ti boš njegovo ime klical Izak in vzpostavil bom svojo zavezo z njim za večno zavezo in s tvojim semenom za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'In kar se tiče Izmaela, sem te uslišal: ›Glej, blagoslovil sem ga in naredil ga bom rodovitnega in ga silno pomnožil. Dvanajst princev bo zaplodil in naredil ga bom [za] velik narod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Toda svojo zavezo bom vzpostavil z Izakom, ki ti ga bo rodila Sara ob tem določenem času, v naslednjem letu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'In prenehal je govoriti z njim in Bog se je dvignil od Abrahama.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Abraham je vzel svojega sina Izmaela in vse, ki so bili rojeni v njegovi hiši in vse, kar je kupil s svojim denarjem, vsakega moškega izmed ljudi Abrahamove hiše in obrezal meso njihove prednje kožice na prav isti dan, kakor mu je rekel Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham je bil star devetindevetdeset let, ko je bil obrezan v mesu svoje prednje kožice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'In njegov sin Izmael je bil star trinajst let, ko je bil obrezan v mesu svoje prednje kožice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Na prav isti dan sta bila obrezana Abraham in njegov sin Izmael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Vsi ljudje njegove hiše, rojeni v hiši in kupljeni z denarjem od tujca, so bili obrezani z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Gospod se mu je prikazal na Mamrejevih ravninah, on pa je sedel pri šotorskih vratih, v vročini dneva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'in povzdignil svoje oči in pogledal in glej, pri njem so stali trije možje in ko jih je zagledal, je stekel od šotorskih vrat, da jih sreča in se priklonil proti tlom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'ter rekel: »Moj Gospod, če sem torej našel naklonjenost v tvojih očeh, te prosim, ne odidi proč od svojega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Naj bo prineseno, prosim te, malo vode in umijte svoja stopala in se spočijte pod drevesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Prinesel bom grižljaj kruha in potolažite svoja srca. Nató boste šli dalje, kajti zato ste prišli k svojemu služabniku.« In rekli so: »Stôri tako, kakor si rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham se je podvizal v šotor k Sari ter ji rekel: »Brž pripravi tri mere fino mlete moke, zamesi jo in na ognjišču pripravi kolače.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Abraham je stekel k čredi, vzel nežno in dobro tele ter ga dal mladeniču in ta je pohitel, da ga pripravi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Vzel je maslo, mleko in tele, ki ga je pripravil in to postavil prednje, in stal je poleg njih, pod drevesom, oni pa so jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Rekli so mu: »Kje je tvoja žena Sara?« Rekel je: »Glejte, v šotoru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, '§ In on je rekel: »Zagotovo se bom vrnil k tebi glede na čas življenja in glej, tvoja žena Sara bo imela sina.« Sara pa je to slišala pri vratih šotora, ki je bil za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Torej Abraham in Sara sta bila stara in zelo zvrhana v letih in s Saro je prenehalo biti po običaju žensk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Zato se je Sara v sebi zasmejala, rekoč: »Bom še imela užitek, potem ko sem se postarala [in] je tudi moj gospod postal star?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Gospod je rekel Abrahamu: »Zakaj se je Sara zasmejala, rekoč: ›Bom zares rodila otroka jaz, ki sem stara?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Je za Gospoda katerakoli stvar pretežka? Ob določenem času se bom vrnil k tebi, glede na čas življenja in Sara bo imela sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Potem je Sara zanikala, rekoč: »Nisem se zasmejala,« kajti bila je prestrašena. On pa je rekel: »Ne, toda zasmejala si se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Možje so vstali od tam in pogledali proti Sódomi in Abraham je odšel z njimi, da jih pospremi na pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Gospod je rekel: »Mar naj pred Abrahamom prikrijem to stvar, ki jo počnem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'glede na to, da bo Abraham zagotovo postal velik in mogočen narod in bodo v njem blagoslovljeni vsi narodi zemlje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Kajti poznam ga, da bo ukazal svojim otrokom in svoji družini za njim in se bodo držali Gospodove poti, da izvajajo pravičnost in sodbo, da bo Gospod nad Abrahama lahko privedel to, kar je govoril o njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Gospod je rekel: »Ker je vpitje Sódome in Gomóre veliko in ker je njihov greh zelo boleč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'bom torej šel dol in pogledal, ali so storili povsem glede na njihovo vpitje, ki je prišlo do mene; in če ne, bom vedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Možje so svoje obraze obrnili od tam in odšli proti Sódomi, toda Abraham je kljub temu stopil pred Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Abraham se je približal in rekel: »Hočeš prav tako uničiti pravične z zlobnimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Morda je znotraj mesta petdeset pravičnih. Hočeš prav tako uničiti kraj in mu ne prizanesti zaradi petdesetih pravičnih, ki so v njem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'To bodi daleč od tebe, da storiš na ta način, da z zlobnimi pokončaš pravične in da bi bili pravični kakor zlobni, to bodi daleč od tebe. Mar ne bo Sodnik vse zemlje storil pravično?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Gospod je rekel: »Če najdem v Sódomi, znotraj mesta, petdeset pravičnih, potem bom zaradi njih prizanesel celemu kraju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham pa je odgovoril in rekel: »Glej torej, nase, ki sem samo prah in pepel, sem vzel, da govorim Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Morda jih bo manjkalo pet do petdesetih pravičnih. Hočeš mesto uničiti zaradi pomanjkanja petih?« On pa je rekel: »Če jih najdem tam petinštirideset, ga ne bom uničil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Ponovno mu je spregovoril in rekel: »Morda jih bo tam najdenih štirideset.« On pa je rekel: » Tega ne bom storil zaradi štiridesetih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Rekel mu je: »Oh naj moj Gospod ne bo jezen, jaz pa bom govoril: ›Morda jih bo tam najdenih trideset.‹« On pa je rekel: » Tega ne bom storil, če jih tam najdem trideset.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Rekel je: »Glej torej, vzel sem nase, da govorim Gospodu: ›Morda jih bo tam najdenih dvajset.‹« On pa je rekel: »Ne bom ga uničil zaradi dvajsetih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Rekel je: »Oh naj Gospod ne bo jezen, jaz pa bom govoril samo še tokrat: ›Morda jih bo tam najdenih deset.‹« On pa je rekel: »Ne bom ga uničil zaradi desetih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Gospod je odšel svojo pot takoj, ko je prenehal govoriti z Abrahamom. Abraham pa se je vrnil na svoj kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Zvečer sta k Sódomi prišla dva angela in Lot je sedel pri sódomskih velikih vratih, in ko ju je Lot zagledal, je vstal, da ju sreča in se je s svojim obrazom upognil k tlom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'ter rekel: »Glejta torej, moja gospoda, vstopita, prosim vaju, v hišo svojega služabnika in ostanita vso noč in umijta svoja stopala in bosta zgodaj vstala ter nadaljevala po svojih poteh.« Onadva pa sta rekla: »Ne, temveč bova vso noč ostala na ulici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Zelo ju je silil in obrnila sta se k njemu in vstopila v njegovo hišo in naredil jima je gostijo, spekel nekvašeni kruh in so jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Toda preden so se ulegli, so možje mesta, torej sódomski možje, obdali hišo, tako mladi kakor stari, vse ljudstvo iz vsake četrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Klicali so k Lotu ter mu rekli: »Kje sta moža, ki sta to noč prišla k tebi? Privedi ju ven k nam, da ju bomo lahko spoznali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot je od vrat odšel k njim in vrata zaprl za seboj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'ter rekel: »Prosim vas, bratje, ne storite tako zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Glejte torej, imam dve hčeri, ki nista spoznali moža. Naj vam, prosim vas, njiju pripeljem k vam in storite jima, kakor je dobro v vaših očeh. Samo tema možema ne storite ničesar, kajti zato sta prišla pod senco moje strehe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Rekli so: »Umakni se.« In ponovno so rekli: »Ta pajdaš je prišel, da začasno prebiva in hoče biti sodnik. Torej bomo s teboj postopali slabše kakor z njima.« In zelo so pritiskali na človeka, torej Lota in se približali, da zlomijo vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Toda moža sta iztegnila svojo roko in potegnila Lota k njim v hišo ter zaprla vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Može, ki so bili pri hišnih vratih, pa sta udarila s slepoto, tako male kakor velike, tako da so se utrudili, da bi našli vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Moža sta Lotu rekla: »Imaš, razen teh tukaj, še koga? Zeta, svoje sinove, svoje hčere in karkoli imaš v mestu, jih odvedi iz tega kraja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'kajti uničila bova ta kraj, ker je njihovo vpitje naraslo pred Gospodovim obličjem in Gospod naju je poslal, da ga uničiva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lot je odšel ven in svojima zetoma, ki sta poročila njegovi hčeri, spregovoril ter rekel: »Vstanita, pojdita ven iz tega kraja, kajti Gospod bo to mesto uničil.« Toda videti je bil kakor nekdo, ki je zasmehoval svoja zeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Ko je vstalo jutro, sta angela podvizala Lota, rekoč: »Vstani, vzemi svojo ženo in svoji dve hčeri, ki sta tukaj, da ne bi bil použit v krivičnosti tega mesta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Medtem ko se je obotavljal, sta moža prijela njegovo roko, roko njegove žene in roki njegovih dveh hčera – Gospod mu je bil usmiljen – in odvedla sta ga naprej in ga postavila zunaj mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'In pripetilo se je, ko sta jih privedla daleč naprej, da je rekel: »Pobegnite zaradi svojega življenja. Ne glejte za seboj niti ne ostanite na vsej ravnini. Zbežite h gori, da ne bi bili použiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot pa jima je rekel: »Oh ne tako, moj Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Glej torej, tvoj služabnik je našel milost v tvojem pogledu in ti si poveličal svoje usmiljenje, ki si mi ga izkazal z rešitvijo mojega življenja, jaz pa ne morem pobegniti h gori, da me ne bi zajelo neko zlo in umrem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Glej torej, to mesto je blizu, da pobegnem vanj in to je majhno. Oh, dovoli mi pobegniti tja (mar ni to majhno?) in moja duša bo živela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Rekel mu je: »Glej, sprejel sem te tudi glede te stvari, da ne bom uničil tega mesta, za katero si govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Pohiti, zbeži tja, kajti ničesar ne morem storiti, dokler ne prideš tja.« Zato je bilo ime tega mesta imenovano Coar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Sonce je vstalo nad zemljo, ko je Lot vstopil v Coar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Potem je Gospod na Sódomo in na Gomóro deževal žveplo in ogenj od Gospoda z neba');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'in razdejal je ti mesti, vso ravnino, vse prebivalce mest in to, kar je raslo na tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Toda njegova žena je za njim pogledala nazaj in postala solnat steber.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham je vstal zgodaj zjutraj h kraju, kjer je stal pred Gospodom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'in pogledal proti Sódomi in Gomóri in proti vsej deželi ravnine in zagledal in glej, dim dežele se je dvigal kakor dim iz talilne peči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'In pripetilo se je, ko je Bog uničil mesta ravnine, da se je Bog spomnil Abrahama in Lota poslal iz srede razdejanja, ko je razdejal mesti, v katerih je prebival Lot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot je iz Coarja odšel navzgor, prebival na gori in njegovi hčeri z njim, kajti bal se je prebivati v Coarju in prebival je v votlini, on in njegovi dve hčeri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Prvorojena je rekla mlajši: »Najin oče je star in tukaj ni moškega na zemlji, da pride noter v naju po navadi vse zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Pridi, najinega očeta pripraviva piti vino in bova ležali z njim, da lahko ohraniva seme najinega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'To noč sta svojega očeta pripravili piti vino in vstopila je prvorojena in ležala s svojim očetom in ni zaznal, ne ko se je ulegla, ne ko je vstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Naslednji dan se je pripetilo, da je prvorojena rekla mlajši: »Glej, sinoči sem bila s svojim očetom. Pripraviva ga tudi to noč piti vino in pojdi ti in lezi z njim, da bova lahko ohranili seme najinega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Tudi to noč sta svojega očeta pripravili piti vino in mlajša je vstala in ležala z njim in ni zaznal, ne ko se je ulegla, ne ko je vstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Tako sta bili obe Lotovi hčeri z otrokom s svojim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Prvorojena je rodila sina in njegovo ime imenovala Moáb. Isti je oče Moábcev do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Mlajša, tudi ona je rodila sina in njegovo ime imenovala Ben Amí. Isti je oče Amónovih otrok do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham je od tam odpotoval proti južni deželi in prebival med Kadešem in Šurom in začasno prebival v Gerárju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'O Sari, svoji ženi, je Abraham rekel: »Ona je moja sestra.« In kralj Abiméleh iz Gerárja je poslal in vzel Saro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Toda Bog je ponoči v sanjah prišel k Abimélehu in mu rekel: »Glej, ti si samo mrtev človek zaradi ženske, ki si jo vzel, kajti ona je moževa žena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Toda Abiméleh se ji ni približal in rekel je: » Gospod, hočeš ubiti tudi pravičen narod?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ali mi ni rekel: ›Ona je moja sestra?‹ In ona, celo ona sama je rekla: ›On je moj brat.‹ To sem storil v neokrnjenosti svojega srca in nedolžnosti svojih rok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Bog mu je v sanjah rekel: »Da, vem, da si to storil v neokrnjenosti svojega srca, kajti tudi jaz sem te zadržal pred pregrešitvijo zoper mene, zato ti nisem dovolil, da se je dotakneš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Zdaj torej vrni človeku njegovo ženo, kajti on je prerok in molil bo zate in boš živel. Če pa je ne povrneš, vedi, da boš zagotovo umrl, ti in vse, kar je tvojega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Zato je Abiméleh zgodaj zjutraj vstal in poklical vse svoje služabnike ter jim v njihova ušesa povedal vse te stvari in ljudje so bili boleče prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Potem je Abiméleh poklical Abrahama in mu rekel: »Kaj si nam storil? In kaj sem ti zagrešil, da si nadme in na moje kraljestvo privedel velik greh? Storil si mi dejanja, ki sploh ne bi smela biti storjena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Abiméleh je rekel Abrahamu: »Kaj si si domišljal, da si storil to stvar?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham je rekel: »Ker sem mislil: ›Zagotovo na tem kraju ni strahu Božjega in zaradi moje žene me bodo ubili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Vendar je zares moja sestra; je hči mojega očeta, toda ne hči moje matere in postala je moja žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Pripetilo se je, ko me je Bog pripravil do tega, da se oddaljim od hiše svojega očeta, da sem ji rekel: ›To je tvoja prijaznost, ki mi jo boš izkazala: na vsakem kraju, kamor bova prišla, o meni reci: ›Moj brat je.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Abiméleh je vzel ovce, vole, sluge in postrežnice ter jih dal Abrahamu in mu vrnil njegovo ženo Saro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Abiméleh je rekel: »Glej, moja dežela je pred teboj. Prebivaj, kjer ti ugaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Sari pa je rekel: »Glej, tvojemu bratu sem dal tisoč koščkov srebra. Glej, on ti je pokrivalo tvojim očem, vsem, ki so s teboj in z vsemi drugimi.« Tako je bila opravičena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Tako je Abraham molil k Bogu in Bog je ozdravil Abiméleha, njegovo ženo in njegove dekle, in rodile so otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Kajti Gospod je zaradi Abrahamove žene Sare, trdno zaprl vse maternice Abimélehove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Gospod je obiskal Saro, kakor je rekel in Gospod je Sari storil, kakor je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Kajti Sara je spočela in Abrahamu rodila sina v njegovi visoki starosti, ob določenem času, o katerem mu je govoril Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham je ime svojega sina, ki se mu je rodil, ki mu ga je rodila Sara, imenoval Izak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Abraham je obrezal svojega sina Izaka, ko je bil star osem dni, kakor mu je zapovedal Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham je bil star sto let, ko se mu je rodil sin Izak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, '§ Sara je rekla: »Bog me je pripravil, da se smejem, tako da se bodo vsi, ki slišijo, smejali z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Rekla je: »Kdo bi rekel Abrahamu, da bo Sara dojila otroke? Kajti rodila sem mu sina v njegovi visoki starosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Otrok je rasel in bil odstavljen in Abraham je tega istega dne, ko je bil Izak odstavljen, priredil veliko praznovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'In Sara je videla sina Egipčanke Hagáre, ki ga je rodila Abrahamu, posmehovati se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Zato je rekla Abrahamu: »Spôdi to sužnjo in njenega sina, kajti sin te sužnje ne bo dedič z mojim sinom Izakom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Stvar zaradi njegovega sina pa je bila v Abrahamovih očeh zelo boleča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Bog je Abrahamu rekel: »Naj to ne bo boleče v tvojem pogledu zaradi dečka in zaradi tvoje sužnje. V vsem tem, kar ti je Sara rekla, prisluhni njenemu glasu, kajti po Izaku se bo imenovalo tvoje potomstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'In tudi iz sina sužnje bom naredil narod, ker je tvoje seme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraham je vstal zgodaj zjutraj, vzel kruh in meh vode, dal to Hagári, namestil to na njeno ramo in otroka in jo poslal proč in odpravila se je in tavala po beeršébski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Voda v mehu je bila porabljena in otroka je odvrgla pod enega izmed grmov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Odšla je in se mu usedla nasproti, dobro pot proč, kakor bi bil streljaj loka, kajti rekla je: »Naj ne vidim otrokove smrti.« In sedela je nasproti njemu in povzdignila svoj glas ter zajokala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Bog je slišal dečkov glas in Božji angel je bil poklican iz nebes k Hagári ter ji rekel: »Kaj te pesti, Hagára? Ne boj se, kajti Bog je slišal dečkov glas, kjer je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Vstani, dvigni svojega dečka in ga drži v svoji roki, kajti naredil ga bom [v] velik narod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Bog je odprl njene oči in zagledala je vodni izvir in odšla je in meh napolnila z vodo ter dečku dala piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Bog je bil z dečkom in ta je rasel, prebival v divjini in postal lokostrelec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Prebival je v Paránski divjini in njegova mati mu je vzela ženo iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Ob tistem času se je pripetilo, da sta Abiméleh in Pihól, vrhovni poveljnik njegove vojske, govorila Abrahamu, rekoč: »Bog je s teboj v vsem, kar počneš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Zdaj mi torej tukaj pri Bogu prisezi, da z menoj ne boš ravnal napačno niti z mojim sinom niti s sinovi mojih sinov, temveč glede na prijaznost, ki sem jo storil tebi, boš ti storil meni in deželi, v kateri se mudiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Abraham je rekel: »Prisegel bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham pa je grajal Abiméleha zaradi vodnega izvira, ki so ga Abimélehovi služabniki nasilno odvzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abiméleh je rekel: »Ne vem, kdo je storil to stvar, niti mi ti nisi povedal, niti do danes nisem slišal o tem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Abraham je vzel ovce in vole ter jih dal Abimélehu in oba sta sklenila zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Abraham je sedem jagnjic iz tropa postavil posebej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Abiméleh je rekel Abrahamu: »Kaj pomeni teh sedem jagnjic, ki si jih postavil posebej?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Rekel je: »Kajti teh sedem jagnjic boš vzel iz moje roke, da mi bodo lahko priča, da sem jaz izkopal ta vodnjak.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Zato je ta kraj imenoval Beeršéba, ker sta tam oba prisegla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Tako sta sklenila zavezo pri Beeršébi. Potem je Abiméleh vstal in Pihól, vrhovni poveljnik njegove vojske in vrnila sta se v deželo Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham je v Beeršébi zasadil nasad ter tam klical ime Gospoda, večnega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'In Abraham je mnogo dni začasno prebival v filistejski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Po teh stvareh pa se je pripetilo, da je Bog skušal Abrahama ter mu rekel: »Abraham.« In rekel je: »Glej, tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Rekel je: »Vzemi sedaj svojega sina, svojega edinega sina Izaka, ki ga ljubiš in pojdi v deželo Moríja; in tam ga daruj v žgalno daritev na eni izmed gorá, o kateri ti bom povedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Abraham je zgodaj zjutraj vstal, osedlal svojega osla in s seboj vzel dva izmed svojih mladeničev in svojega sina Izaka in nacepil drv za žgalno daritev in vstal ter odšel na kraj, o katerem mu je Bog povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Potem je Abraham tretji dan povzdignil svoje oči in daleč stran zagledal kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Abraham je rekel svojima mladeničema: »Vidva ostanita tukaj z oslom, jaz in deček pa bova šla tamkaj, oboževala in ponovno prišla k vama.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Abraham je vzel drva žgalne daritve in ta položil na svojega sina Izaka, v svojo roko pa je vzel ogenj in nož in oba skupaj sta odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Izak je spregovoril svojemu očetu Abrahamu in rekel: »Moj oče.« Ta je rekel: »Tukaj sem, sin moj.« Rekel je: »Glej ogenj in drva, toda kje je jagnje za žgalno daritev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham je rekel: »Moj sin, Bog si bo priskrbel jagnje za žgalno daritev.« Tako sta oba skupaj odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Prišla sta do kraja, o katerem mu je povedal Bog in Abraham je tam zgradil oltar in razporedil drva ter zvezal svojega sina Izaka in ga položil na oltar, na drva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Abraham je iztegnil svojo roko in vzel nož, da svojega sina zakolje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Gospodov angel pa je iz nebes zaklical k njemu in rekel: »Abraham, Abraham.« Ta je rekel: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Rekel je: »Svoje roke ne položi na dečka niti mu ničesar ne stôri, kajti sedaj vem, da se bojiš Boga, glede na to, da sem videl, da mi nisi odrekel svojega sina, svojega edinega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Abraham je povzdignil svoje oči in pogledal in za seboj zagledal ovna, s svojimi rogovi ujetega v goščavo. Abraham je odšel, vzel ovna in ga namesto svojega sina daroval za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, '§ Abraham je ime tega kraja imenoval Jahve–jire, kakor je rečeno do tega dne: ›Na gori Gospodovi bo videno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Gospodov angel pa je iz nebes drugič zaklical k Abrahamu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'in rekel: »Pri sebi sem prisegel,« govori Gospod, »kajti ker si storil to stvar in nisi zadržal svojega sina, svojega edinega sina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'te bom v blagoslavljanju blagoslovil in v množenju bom pomnožil tvoje seme kakor zvezd neba in kakor peska, ki je na morski obali in tvoje seme bo imelo v lasti velika vrata svojih sovražnikov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'in v tvojem semenu bodo blagoslovljeni vsi narodi zemlje, ker si ubogal moj glas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Tako se je Abraham vrnil k svojima mladeničema in vstali so ter skupaj odšli k Beeršébi in Abraham je prebival pri Beeršébi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Po teh stvareh pa se je pripetilo, da je bilo Abrahamu povedano, rekoč: »Glej, Milka, tudi ona je tvojemu bratu Nahórju rodila otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Njegovega prvorojenca Uca, njegovega brata Buza, Arámovega očeta Kemuéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Keseda, Hazója, Pildáša, Jidláfa in Betuéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'In Betuél je zaplodil Rebeko. Teh osem je Milka rodila Nahórju, Abrahamovemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Njegova priležnica, ki ji je bilo ime Reúma je tudi rodila Tebaha, Gahama, Tahaša in Maahája.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, '§ Sara je bila stara sto sedemindvajset let. To so bila leta Sarinega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sara je umrla v Kirját Arbi; ista je Hebrón v kánaanski deželi. Abraham je prišel, da žaluje za Saro in da joka za njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Abraham je vstal pred svojo mrtvo in Hetovim sinovom spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '»Tujec sem in začasen prebivalec z vami. Dajte mi posest grobišča z vami, da lahko pokopljem svojo mrtvo izpred svojega obličja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Hetovi otroci so Abrahamu odgovorili, rekoč mu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '»Poslušaj nas, moj gospod. Ti si med nami mogočen princ. V izbiri naših mavzolejev pokoplji svojo mrtvo. Nobeden izmed nas ne bo pred teboj zadržal svojega mavzoleja, pač pa da lahko pokoplješ svojo mrtvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Abraham je vstal in se priklonil ljudstvu dežele, torej Hetovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Posvetoval se je z njimi, rekoč: »Če je vaše mišljenje, da naj pokopljem svojo mrtvo izpred svojih oči, me poslušajte in zame prosite Coharjevega sina Efróna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'da bi mi lahko dal votlino Mahpélo, ki jo ima, ki je na koncu njegovega polja, kajti za kolikor denarja je vredna, naj mi jo da v posest za grobišče med vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Efrón pa je prebival med Hetovimi otroki. In Efrón Hetejec je odgovoril Abrahamu v občinstvu Hetovih otrok, torej vseh teh, ki so vstopali pri velikih vratih njegovega mesta, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '»Ne, moj gospod, poslušaj me. Polje ti dam in votlino, ki je tam, to ti dam. V prisotnosti sinov svojega ljudstva ti to dam. Pokoplji svojo mrtvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Abraham se je priklonil pred ljudstvom dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Spregovoril je Efrónu, v občinstvu ljudstva dežele, rekoč: »Če to hočeš dati, prosim te, poslušaj me. Za to polje ti bom dal denar. Vzemi ga od mene, jaz pa bom svojo mrtvo pokopal tam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efrón je odgovoril Abrahamu, rekoč mu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '»Moj gospod, prisluhni mi. Zemlja je vredna štiristo šeklov srebra. Kaj je to med menoj in teboj? Pokoplji torej svojo mrtvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham je prisluhnil Efrónu in Abraham je Efrónu odtehtal srebro, ki ga je omenil v občinstvu Hetovih sinov, štiristo šeklov srebra, trenuten denar pri trgovcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'In Efrónovo polje, ki je bilo v Mahpéli, ki je bilo pred Mamrejem, polje in votlina, ki sta bila tam in vsa drevesa, ki so bila na polju, ki so bila na vseh mejah naokoli, so bila zagotovo potrjena');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'za posest Abrahamu v prisotnosti Hetovih otrok, pred vsemi, ki so vstopali pri velikih vratih njegovega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'In po tem je Abraham pokopal svojo ženo Saro v votlini polja Mahpéli pred Mamrejem, isti je Hebrón v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Polje in votlina, ki je tam, sta bila zagotovo potrjena Abrahamu v posest za grobišče od Hetovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham je bil star in že zelo zvrhan v starosti in Gospod je Abrahama blagoslovil v vseh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Abraham je najstarejšemu služabniku svoje hiše, ki je vladal nad vsem, kar je imel, rekel: »Položi, prosim te, svojo roko pod moje stegno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'jaz pa te bom primoral priseči pri Gospodu, Bogu nebes in Bogu zemlje, da mojemu sinu ne boš vzel žene izmed kánaanskih hčera, med katerimi živim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'temveč boš šel v mojo deželo in k mojemu sorodstvu in vzel ženo mojemu sinu Izaku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Služabnik pa mu je rekel: »Morda mi ženska ne bo voljna slediti v to deželo. Ali moram tvojega sina ponovno privesti v deželo, od koder si prišel?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham mu je rekel: »Pazi, da mojega sina ne privedeš ponovno tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Gospod, Bog nebes, ki me je vzel iz hiše mojega očeta in iz dežele mojega sorodstva in ki mi je govoril in mi to prisegel, rekoč: ›To deželo bom dal tvojemu semenu,‹ bo pred teboj poslal svojega angela in ti boš mojemu sinu od tam vzel ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Če pa ti ženska ne bo voljna slediti, potem boš prost pred to mojo prisego, samo mojega sina ne privedi ponovno tja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Služabnik je svojo roko položil pod stegno Abrahama, svojega gospodarja in mu glede te zadeve prisegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Služabnik je vzel deset kamel izmed kamel svojega gospodarja in se odpravil, kajti vse dobrine njegovega gospodarja so bile v njegovi roki. Vstal je in odšel v Mezopotamijo, v Nahórjevo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Svojim kamelam je storil, da so pokleknile zunaj mesta, pri vodnem izviru, ob večernem času, v času, ko gredo ženske ven zajemat vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Rekel je: »Oh Gospod, Bog mojega gospodarja Abrahama, prosim te, pošlji mi danes veliko sreče in mojemu gospodarju Abrahamu izkaži prijaznost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Glej, tukaj stojim pri vodnem izviru in hčere mestnih mož prihajajo zajemat vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Naj se mi zgodi, da gospodična, ki ji bom rekel: ›Spusti svoj lončen vrč, prosim te, da bom lahko pil‹ in bo rekla: ›Pij in tudi tvojim kamelam bom dala piti,‹ naj bo ta tista, ki si jo določil za svojega služabnika Izaka in s tem bom vedel, da si mojemu gospodarju izkazal prijaznost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Pripetilo se je, preden je nehal govoriti, glej, da je prišla ven Rebeka, ki je bila rojena Betuélu, sinu Milke, žene Nahórja, Abrahamovega brata, s svojim lončenim vrčem na svoji rami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Gospodična pa je bila zelo lepa na pogled, devica, niti je noben mož ni spoznal in odšla je dol k izviru in napolnila svoj lončen vrč ter prišla gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Služabnik je stekel, da jo sreča in reče: »Pusti mi, prosim te, popiti malo vode iz tvojega lončenega vrča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Rekla je: »Pij, moj gospod« in se podvizala ter spustila svoj lončen vrč na svojo roko ter mu dala piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'In ko mu je dala piti, je rekla: »Tudi za tvoje kamele bom zajela vodo, dokler se ne napijejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Odhitela je in svoj lončen vrč izpraznila v korito in ponovno stekla k izviru, da zajame vodo in jo zajela za vse njegove kamele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Človek, začuden ob njej, je ohranil svoj mir, da izve, ali je Gospod naredil njegovo potovanje uspešno ali ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Pripetilo se je, ko so se kamele napojile, da je človek vzel zlat uhan, težak pol šekla in dve zapestnici za njeni roki, težki deset šeklov zlata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'in rekel: »Čigava hči si? Povej mi, prosim te. Ali je za nas prostor v hiši tvojega očeta, da prenočimo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Rekla mu je: » Sem hči Betuéla, Milkinega sina, ki ga je rodila Nahórju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Poleg tega mu je rekla: »Imamo dovolj tako slame kakor krme in prostora za prenočitev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Človek je sklonil svojo glavo ter oboževal Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Rekel je: »Blagoslovljen bodi Gospod, Bog mojega gospodarja Abrahama, ki mojega gospodarja ni pustil brez svoje milosti in svoje resnice. Bil sem na poti in Gospod me je vodil v hišo bratov mojega gospodarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Gospodična je stekla ter te stvari povedala tistim iz hiše svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebeka pa je imela brata in njegovo ime je bilo Labán. In Labán je stekel k človeku, k izviru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Pripetilo se je, ko je zagledal uhan in zapestnici na roki svoje sestre in ko je slišal besede svoje sestre Rebeke, rekoč: »Tako mi je mož govoril,« da je prišel k človeku. In glej, stal je s kamelami pri izviru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Rekel je: »Vstopi, ti blagoslovljen od Gospoda. Zakaj stojiš zunaj? Kajti pripravil sem hišo in prostor za kamele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Mož je vstopil v hišo, on pa je odpasal njegove kamele in jim dal slamo in krmo za kamele in vodo, da umije njegova stopala in stopala mož, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Predenj je bila postavljena hrana, da bi jedel, toda rekel je: »Ne bom jedel, dokler ne povem svoje naloge.« On pa je rekel: »Spregovori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Rekel je: »Jaz sem Abrahamov služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'In Gospod je silno blagoslovil mojega gospodarja in postal je velik in dal mu je trope, črede, srebro, zlato, sluge, dekle, kamele in osle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Sara, žena mojega gospodarja, je mojemu gospodarju rodila sina, ko je bila stara. In njemu je dal vse, kar ima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Moj gospodar me je zaprisegel, rekoč: ›Mojemu sinu ne boš vzel žene izmed kánaanskih hčera, v katerih deželi prebivam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'temveč boš šel k hiši mojega očeta in k mojemu sorodstvu in vzel ženo mojemu sinu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Svojemu gospodarju sem rekel: ›Morda mi ženska ne bo hotela slediti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Rekel mi je: › Gospod, pred katerim hodim, bo s teboj poslal svojega angela in osrečil tvojo pot in vzel boš ženo za mojega sina iz mojega sorodstva in iz hiše mojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Potem boš prost pred to mojo prisego, ko prideš k mojemu sorodstvu. Če ti je ne bodo dali, potem si prost pred mojo prisego.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Danes sem prišel k izviru in rekel: ›O Gospod, Bog mojega gospodarja Abrahama, če sedaj osrečiš mojo pot, ki jo hodim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Glej, stojim pri vodnem izviru in naj se zgodi, da ko pride naprej devica, da zajame vodo in ji rečem: ›Daj mi za piti, prosim te, malo vode iz svojega lončenega vrča‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'in mi reče: ›Pij in prav tako bom zajela za tvoje kamele,‹ naj bo ta ista ženska, ki jo je Gospod določil za sina mojega gospodarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'In preden sem v svojem srcu prenehal govoriti, glej, je prišla Rebeka s svojim lončenim vrčem na svoji rami. Odšla je dol do izvira in zajela vodo. Rekel sem ji: ›Daj mi piti, prosim te.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Podvizala se je in spustila svoj lončen vrč iz svoje rame ter rekla: ›Pij in tudi tvojim kamelam bom dala piti.‹ Tako sem pil in tudi kamele je napojila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Vprašal sem jo ter rekel: ›Čigava hči si?‹ Rekla je: ›Hči Betuéla, Nahórjevega sina, ki mu ga je rodila Milka.‹ In položil sem uhan na njen obraz in zapestnici na njeni roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Sklonil sem svojo glavo in oboževal Gospoda in blagoslovil Gospoda, Boga svojega gospodarja Abrahama, ki me je vodil po pravi poti, da vzame svojemu sinu hčer gospodarjevega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'In sedaj, če hočete prijazno in iskreno postopati z mojim gospodarjem, mi povejte. Če ne, mi povejte, da se lahko obrnem na desno roko ali na levo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Potem sta Labán in Betuél odgovorila ter rekla: »Stvar izvira od Gospoda. Ne moreva ti govoriti dobro ali slabo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Glej, Rebeka je pred teboj, vzemi jo in pojdi in naj bo žena sinu tvojega gospodarja, kakor je govoril Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Pripetilo se je, da ko je Abrahamov služabnik slišal te besede, je oboževal Gospoda, priklanjajoč se k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Služabnik je prinesel naprej dragocenosti iz srebra in dragocenosti iz zlata in oblačilo in jih dal Rebeki. Tudi njenemu bratu in njeni materi je dal dragocene stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Jedli so in pili, on in ljudje, ki so bili z njim in ostali vso noč. Vstali pa so zjutraj in rekel je: »Pošljite me proč, k mojemu gospodarju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Njen brat in njena mati pa sta rekla: »Naj gospodična ostane z nami nekaj dni, vsaj deset, potem bo šla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Rekel jim je: »Ne preprečujte mi, glede na to, da je Gospod osrečil mojo pot. Pošljite me proč, da lahko grem k svojemu gospodarju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Rekla sta: »Poklicala bova gospodično in poizvemo pri njenih ustih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'In poklicala sta Rebeko ter ji rekla: »Hočeš iti s tem človekom?« In rekla je: »Šla bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'In odpustili so svojo sestro Rebeko in njeno dojiljo in Abrahamovega služabnika in njegove ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'In blagoslovili so Rebeko ter ji rekli: »Ti si naša sestra, bodi mati tisočev milijonov in naj tvoje seme obvladuje velika vrata tistih, ki jih sovražijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Rebeka je vstala in njene gospodične in zajahale so kamele ter sledile človeku. In služabnik je vzel Rebeko ter odšel svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, '§ Izak je prišel po poti izvira Laháj Roí, kajti prebival je v južni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Izak je odšel ven, da ob večeru premišljuje na polju in je povzdignil svoje oči in videl in glej, prihajale so kamele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeka je povzdignila svoje oči in ko je zagledala Izaka, se je spustila s kamele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Kajti služabniku je rekla: »Kdo je ta človek, ki hodi po polju, da nas sreča?« Služabnik je rekel: »To je moj gospodar.« Zato je vzela zagrinjalo in se pokrila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Služabnik je povedal Izaku vse stvari, ki jih je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Izak jo je privedel v šotor svoje matere Sare in vzel Rebeko in postala je njegova žena in jo je ljubil in Izak je bil potolažen po smrti svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Potem si je Abraham spet vzel ženo in njeno ime je bilo Ketúra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Rodila mu je Zimrána, Jokšána, Medána, Midjána, Jišbáka in Šuaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jokšán je zaplodil Šebá in Dedána. Dedánovi sinovi so bili: Ašurí, Letušéj in Leuméj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Midjánovi sinovi: Efá, Efer, Henoh, Abidá in Eldaá. Vsi ti so bili Ketúrini sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham je vse, kar je imel, dal Izaku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Toda sinovom priležnic, ki jih je imel Abraham, je Abraham dal darila in jih poslal proč od Izaka, svojega sina, medtem ko je še živel, proti vzhodu, v vzhodno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'To so dnevi let Abrahamovega življenja, ki jih je živel, sto petinsedemdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Potem je Abraham izročil duha in umrl v lepi, visoki starosti, starec in bogat z leti in pridružen je bil svojim ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Njegova sinova, Izak in Izmael, sta ga pokopala v votlini Mahpéli, na polju Efróna, sina Hetejca Coharja, ki je pred Mamrejem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'polju, ki ga je Abraham kupil od Hetovih sinov. Tam je bil pokopan Abraham in njegova žena Sara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Pripetilo se je po Abrahamovi smrti, da je Bog blagoslovil njegovega sina Izaka in Izak je prebival pri izviru Laháj Roí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Torej to so rodovi Izmaela, Abrahamovega sina, ki ga je Egipčanka Hagára, Sarina pomočnica, rodila Abrahamu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'To so imena Izmaelovih sinov po njihovih imenih, glede na njihove rodove: Izmaelov prvorojenec Nebajót, Kedár, Adbeél, Mibsám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mišmá, Dumá, Masá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadád, Temá, Jetúr, Nafíš in Kedma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'To so Izmaelovi sinovi in to so njihova imena po njihovih mestih in po njihovih gradovih. Dvanajst princev glede na njihove narode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'To so leta Izmaelovega življenja, sto sedemintrideset let in izročil je duha ter umrl in bil zbran k svojemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, '§ Prebivali so od Havíle do Šura, to je pred Egiptom, ko greš proti Asiriji. In umrl je v prisotnosti vseh svojih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'To so rodovi Abrahamovega sina Izaka. Abraham je zaplodil Izaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, '§ Izak je bil star štirideset let, ko je vzel za ženo Rebeko, hči Betuéla, Sirca iz Padan–arama, sestro Sirca Labána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Izak je rotil Gospoda zaradi svoje žene, ker je bila jalova in Gospod je bil od njega izprošen in njegova žena Rebeka je spočela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Otroka znotraj nje pa sta se borila in rekla je: »Če je tako, zakaj potemtakem sem?« In odšla je, da poizve od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Gospod ji je rekel: »Dva naroda sta v tvoji maternici in dve vrsti ljudstva bosta ločeni iz tvoje notranjosti in eno ljudstvo bo močnejše kakor drugo ljudstvo in starejši bo služil mlajšemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Ko so bili dopolnjeni njeni dnevi, da bi rodila, glej, sta bila v njeni maternici dvojčka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Prvi je prišel ven rdeč vsepovsod, kakor kosmata obleka. Njegovo ime so poimenovali Ezav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Nató je prišel ven njegov brat, njegova roka pa je držala Ezavovo peto. Njegovo ime so poimenovali Jakob. Ko ju je rodila, je bil Izak star šestdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Fanta pa sta zrasla. Ezav je bil spreten lovec, človek polja, Jakob pa je bil preprost človek, ki je prebival v šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Izak je ljubil Ezava, ker je jedel od njegove divjačine, toda Rebeka je ljubila Jakoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Jakob je kuhal juho, Ezav pa je prišel iz polja in je bil oslabel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Ezav je rekel Jakobu: »Nahrani me, prosim te, s to isto rdečo juho, kajti oslabel sem.« Zato je bilo njegovo ime imenovano Edóm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jakob je rekel: »Prodaj mi danes svojo pravico prvorojenstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ezav je rekel: »Glej, jaz sem na točki smrti. Kakšno korist mi bo storila pravica prvorojenstva?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob je rekel: »Danes mi prisezi.« In prisegel mu je ter svojo pravico prvorojenstva prodal Jakobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Potem je Jakob dal Ezavu kruh in lečino juho. Ta je jedel, pil in vstal ter odšel svojo pot. Tako je Ezav preziral svojo pravico prvorojenstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Bila je lakota v deželi, poleg prve lakote, ki je bila v Abrahamovih dneh. In Izak je odšel k filistejskemu kralju Abimélehu v Gerár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Prikazal se mu je Gospod ter rekel: »Ne hodi dol v Egipt; prebivaj v deželi, ki ti bom o njej povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Začasno bivaj v tej deželi in jaz bom s teboj in te bom blagoslavljal, kajti tebi in tvojemu potomcu bom dal vse te dežele in jaz bom izpolnil prisego, ki sem jo prisegel tvojemu očetu Abrahamu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'in tvojemu semenu bom storil, da se pomnoži kakor zvezde neba in tvojemu semenu bom dal vse te dežele in v tvojem semenu bodo blagoslovljeni narodi zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'zato ker je Abraham ubogal moj glas in ohranil moj ukaz, moje zapovedi, moje zakone in moje postave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'In Izak je prebival v Gerárju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Možje [tega] kraja so ga vprašali o njegovi ženi in rekel je: »Ona je moja sestra,« kajti bal se je reči: » Ona je moja žena.« Rekel je, »da me ne bi možje [tega] kraja ubili zaradi Rebeke,« kajti bila je zelo lepa na pogled.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Pripetilo se je, ko je bil tam dolgo časa, da je Abiméleh, kralj Filistejcev, pogledal skozi okno in zagledal in glej, Izak se je ljubimkal s svojo ženo Rebeko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Abiméleh je poklical Izaka ter rekel: »Glej, ona je zagotovo tvoja žena. Kako si rekel: ›Ona je moja sestra?‹« Izak mu je odgovoril: »Ker sem rekel: ›Da zaradi nje ne bi umrl.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abiméleh je rekel: »Kaj je to, kar si nam storil? Nekdo izmed ljudstva bi lahko mirno ležal s tvojo ženo in ti bi nad nas privedel krivdo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Abiméleh je vsem svojim ljudem naročil, rekoč: »Kdor se dotakne tega moža ali njegove žene, bo zagotovo usmrčen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Potem je Izak sejal v tej deželi in v istem letu prejel stokratno in Gospod ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Mož je postal velik in šel naprej in rasel, dokler ni postal zelo velik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'kajti imel je posest tropov in posest čred in veliko število služabnikov, in Filistejci so mu zavidali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Kajti vse vodnjake, ki so jih služabniki njegovega očeta izkopali v dneh njegovega očeta Abrahama, so Filistejci zamašili in jih napolnili s prstjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Abiméleh je rekel Izaku: »Pojdi od nas, kajti mnogo mogočnejši si kakor mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Izak se je odpravil od tam in svoj šotor postavil v dolini Gerár ter tam prebival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Izak je ponovno izkopal vodnjake, ki so jih izkopali v dneh njegovega očeta Abrahama, kajti Filistejci so jih po Abrahamovi smrti zamašili. Njihova imena je poimenoval po imenih, po katerih jih je imenoval njegov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, '§ Izakovi služabniki so kopáli v dolini in tam našli vodnjak izvirne vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Čredniki iz Gerárja pa so se prepirali z Izakovimi čredniki, rekoč: »Voda je naša.« In ime vodnjaka je poimenoval Esek, ker so se z njim prepirali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'In izkopali so še en vodnjak in tudi za tega so se prepirali. Njegovo ime je poimenoval Sitna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Odstranil se je od tam ter izkopal nov vodnjak. Zanj pa se niso prepirali in njegovo ime je imenoval Rehobót in rekel je: »Kajti sedaj je Gospod za nas pripravil prostor in bomo rodovitni v deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'In od tam se je dvignil v Beeršébo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Isto noč se mu je prikazal Gospod ter rekel: »Jaz sem Bog Abrahama, tvojega očeta. Ne boj se, kajti jaz sem s teboj in zaradi svojega služabnika Abrahama te bom blagoslovil in pomnožil tvoje seme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Tam je zgradil oltar in klical h Gospodovemu imenu ter tam postavil svoj šotor in tam so Izakovi služabniki izkopali vodnjak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Potem so iz Gerárja odšli k njemu Abiméleh in Ahuzát, eden izmed njegovih prijateljev ter Pihól, vrhovni poveljnik njegove vojske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Izak pa jim je rekel: »Zakaj ste prišli k meni, glede na to, da me sovražite in ste me odposlali od sebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Rekli so: »Zagotovo smo videli, da je bil s teboj Gospod in smo rekli: ›Naj bo torej prisega med nami, torej med nami in teboj in naj sklenemo zavezo s teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'da nam ne boš storil nobene škode, kakor se mi nismo dotaknili tebe in kakor ti nismo storili nič drugega, temveč dobro in smo te odposlali v miru.‹ Ti si torej blagoslovljen od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'In pripravil jim je gostijo in jedli so ter pili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Zjutraj pa so zgodaj vstali in drug drugemu prisegli in Izak jih je odposlal proč in od njega so odšli v miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Istega dne se je pripetilo, da so prišli Izakovi služabniki in mu povedali glede vodnjaka, ki so ga izkopali ter mu rekel: »Našli smo vodo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'In imenoval ga je Šiba; zato je ime mesta Beeršéba do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Ezav je bil star štirideset let, ko je vzel Judito, hčer Hetejca Beeríja in Basemáto, hči Hetejca Elóna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'ki sta bili Izaku in Rebeki v žalostno mišljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Pripetilo se je, ko je bil Izak star in so bile njegove oči zatemnjene, tako da ni mogel videti, da je poklical najstarejšega sina Ezava ter mu rekel: »Moj sin.« Ta mu je odgovoril: »Glej, tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Rekel je: »Glej, jaz sem torej star, ne poznam dneva svoje smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Zdaj torej vzemi, prosim te, svoja orožja, svoj tul za puščice in svoj lok ter pojdi ven na polje in mi ujemi nekaj divjačine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'ter mi pripravi okusno hrano, kakor jo imam rad in mi jo prinesi, da bom lahko jedel, da te moja duša lahko blagoslovi preden umrem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka pa je slišala, ko je Izak govoril svojemu sinu Ezavu. In Ezav je odšel na polje, da lovi za divjačino in da jo prinese.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rebeka pa je spregovorila svojemu sinu Jakobu, rekoč: »Glej, slišala sem tvojega očeta govoriti tvojemu bratu Ezavu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '›Prinesi mi divjačino in pripravi mi okusno jed, da bom lahko jedel in te pred svojo smrtjo blagoslovil pred Gospodom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Zdaj torej, moj sin, ubogaj moj glas glede tega, kar ti zapovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Pojdi torej k tropu in mi od tam prinesi dva dobra kozlička od koz in pripravila ju bom [v] okusno jed za tvojega očeta, kakor jo ima rad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Prinesel jo boš k svojemu očetu, da bo lahko jedel in da te pred svojo smrtjo lahko blagoslovi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob pa je svoji materi Rebeki rekel: »Glej, moj brat Ezav je kosmat človek, jaz pa sem gladek človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Moj oče me bo morda želel potipati, jaz pa se mu bom zdel kakor slepar in bom nadse privedel prekletstvo, ne pa blagoslova.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Njegova mati pa mu je rekla: »Na meni bodi tvoje prekletstvo, moj sin. Samo ubogaj moj glas in pojdi in mi ju prinesi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Odšel je, dobil in ju prinesel svoji materi in njegova mati je pripravila okusno jed, kot jo je njegov oče imel rad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Rebeka je vzela čedna oblačila svojega najstarejšega sina Ezava, ki so bile z njo v hiši in jih nadela na svojega mlajšega sina Jakoba');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'in na njegove roke položila kožo kozjih kozličkov in na gladkost njegovega vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Okusno jed in kruh, kar je pripravila, je dala v roke svojega sina Jakoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Ta je prišel k svojemu očetu in rekel: »Moj oče.« On je rekel: »Tukaj sem, kdo si ti, moj sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob je rekel svojemu očetu: »Jaz sem tvoj prvorojenec Ezav. Storil sem glede na [to], kar si mi zaukazal. Vstani, prosim te, sedi in jej od moje divjačine, da me tvoja duša lahko blagoslovi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Izak pa je svojemu sinu rekel: »Kako to, da si to tako hitro našel, moj sin?« In on je rekel: »Ker je Gospod, tvoj Bog, to privedel k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Izak je rekel Jakobu: »Pridi bliže, prosim te, da te lahko potipam, moj sin, če si ti moj pravi sin Ezav ali nisi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jakob je odšel bliže k svojemu očetu Izaku in ta ga je potipal ter rekel: »Glas je Jakobov glas, toda roki sta Ezavovi roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'In ni ga razpoznal, ker so bile njegove roke kosmate, kakor roke njegovega brata Ezava. Tako ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Rekel je: » Ali si ti moj pravi sin Ezav?« In on je rekel: »Jaz sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Rekel je: »Prinesi to bliže k meni in jedel bom od divjačine svojega sina, da te moja duša lahko blagoslovi.« To je prinesel bliže k njemu in on je jedel, in prinesel mu je vina in je pil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Njegov oče Izak mu je rekel: »Pridi torej bliže in me poljubi, moj sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'In on se je približal ter ga poljubil in zavohal je vonj njegovega oblačila in ga blagoslovil ter rekel: »Poglej, vonj mojega sina je vonj polja, ki ga je Gospod blagoslovil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'zato naj ti Bog da od rose z neba, rodovitnost zemlje in obilo od žita in vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Naj ti ljudstva služijo in se ti narodi priklanjajo. Bodi gospodar nad svojimi brati in naj se sinovi tvoje matere priklanjajo pred teboj. Preklet bodi, kdorkoli te preklinja in blagoslovljen bodi, kdor te blagoslavlja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Pripetilo se je, takoj ko je Izak končal z blagoslavljanjem Jakoba in je Jakob komaj odšel izpred prisotnosti svojega očeta Izaka, da je iz svojega lova vstopil njegov brat Ezav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Tudi on je pripravil okusno jed in jo prinesel k svojemu očetu in svojemu očetu rekel: »Naj moj oče vstane in jé od divjačine svojega sina, da me bo tvoja duša lahko blagoslovila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Njegov oče Izak pa mu je rekel: »Kdo si ti?« In on mu je rekel: »Jaz sem tvoj sin, tvoj prvorojenec Ezav.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Izak je silno zatrepetal ter rekel: »Kdo? Kje je tisti, ki je vzel divjačino in mi jo prinesel in sem jedel od vsega, preden si ti prišel in sem ga blagoslovil. Da, in ostal bo blagoslovljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Ko je Ezav slišal besede svojega očeta, je zajokal z velikim in silno grenkim jokom ter svojemu očetu rekel: »Blagoslovi me, celó tudi mene, oh moj oče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Ta pa je rekel: »Tvoj brat je prišel s premetenostjo in odvzel tvoj blagoslov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Rekel je: »Ali ni pravilno imenovan Jakob? Kajti dvakrat me je izpodrinil. Odvzel je mojo pravico prvorojenstva, in glej, sedaj je odvzel moj blagoslov.« In rekel je: »Ali zame nisi prihranil blagoslova?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Izak pa je odgovoril in Ezavu rekel: »Glej, naredil sem ga za tvojega gospodarja in vse njegove brate sem mu dal za služabnike, in z žitom in vinom sem ga oskrbel; kaj pa naj sedaj storim tebi, moj sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Ezav je svojemu očetu rekel: »Imaš samo en blagoslov, moj oče? Blagoslovi me, celó tudi mene, oh moj oče.« Ezav je povzdignil svoj glas in zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, '§ Njegov oče Izak je odgovoril in rekel: »Glej tvoje bivališče bo rodovitnost zemlje in od rose z neba od zgoraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'S svojim mečem boš živel in svojemu bratu boš služil. In zgodilo se bo, ko boš imel gospostvo, da boš njegov jarem zlomil s svojega vratu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'In Ezav je sovražil Jakoba zaradi blagoslova, s katerim ga je njegov oče blagoslovil. Ezav je v svojem srcu rekel: »Dnevi žalovanja za mojim očetom se bližajo, potem bom svojega brata Jakoba ubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Te besede Ezava, njenega najstarejšega sina, pa so bile povedane Rebeki in poslala je in poklicala svojega mlajšega sina Jakoba ter mu rekla: »Glej, tvoj brat Ezav, kar se tebe tiče, samega sebe tolaži, nameravajoč te ubiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Zdaj torej, moj sin, ubogaj moj glas in vstani, zbeži k mojemu bratu Labánu v Harán');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'in ostani z njim nekaj dni, dokler se ne odvrne razjarjenost tvojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Dokler se jeza tvojega brata ne odvrne od tebe in pozabi to, kar si mu storil. Potem bom poslala in te dobila od tam. Zakaj bi bila prikrajšana tudi za vaju oba v enem dnevu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Rebeka pa je Izaku rekla: »Naveličana sem svojega življenja zaradi Hetovih hčera. Če Jakob vzame ženo izmed Hetovih hčera, takšni kakor sta ti, ki sta izmed hčera dežele, kakšno dobro mi bo storilo moje življenje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Izak je poklical Jakoba, ga blagoslovil, mu naročil ter mu rekel: »Ne boš si vzel žene izmed Kánaanovih hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, '§ Vstani, pojdi v Padan–aram, k hiši Betuéla, očeta tvoje matere in od tam si vzemi ženo izmed hčera Labána, brata tvoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Bog Vsemogočni naj te blagoslovi in te naredi rodovitnega in te namnoži, da boš lahko postal množica ljudstva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'in ti da Abrahamov blagoslov, tebi in tvojemu semenu s teboj, da boš lahko podedoval deželo, v kateri si tujec, ki jo je Bog dal Abrahamu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, '§ Izak je odposlal Jakoba in ta je odšel v Padan–aram, k Labánu, sinu Sirca Betuéla, brata Jakobove in Ezavove matere Rebeke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Ko je Ezav videl, da je Izak blagoslovil Jakoba in ga odposlal v Padan–aram, da si od tam vzame ženo in da mu je med blagoslovom dal naročilo, rekoč: »Ne boš si vzel žene izmed Kánaanovih hčera,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, '§ in da je Jakob ubogal svojega očeta in svojo mater ter odšel v Padan–aram,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'je Ezav videl, da Kánaanove hčere njegovemu očetu Izaku niso ugajale');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'in je Ezav potem odšel k Izmaelu in si k ženama, ki ju je imel, vzel Mahaláto, hčer Abrahamovega sina Izmaela, Nebajótovo sestro, da postane njegova žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jakob pa je odšel iz Beeršébe in odšel proti Haránu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Ker pa je sonce zašlo, se je spustil na nek kraj in se tam vso noč zadrževal in vzel je kamne tega kraja in jih položil za svoje blazine in se ulegel na ta kraj, da zaspi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Sanjal je in glej lestev, postavljeno na zemljo in njen vrh je segal do nebes. In glej, Božji angeli so se vzpenjali in spuščali po njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'In glej, Gospod je stal nad njo ter rekel: »Jaz sem Gospod, Bog tvojega očeta Abrahama in Izakov Bog. Deželo, na kateri ležiš, bom dal tebi in tvojemu semenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Tvojega semena bo kakor zemeljskega prahu in razširjen boš na zahod, na vzhod, na sever in na jug. In v tebi in v tvojem semenu bodo blagoslovljene vse družine zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Glej, jaz sem s teboj in varoval te bom na vseh krajih, kamor greš in ponovno te bom privedel v to deželo, kajti ne bom te zapustil, dokler ne storim tega, o čemer sem ti govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Jakob se je zbudil iz svojega spanja in rekel: »Zagotovo je na tem kraju Gospod, jaz pa tega nisem vedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Bil je prestrašen in rekel: »Kako grozen je ta kraj! To ni nič drugega kakor Božja hiša in to so velika nebeška vrata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Jakob je zgodaj zjutraj vstal in vzel kamen, ki ga je podstavil za svoje blazine in ga postavil za steber in nanj, na njegov vrh, izlil olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Ime tega kraja je imenoval Betel, toda ime tega kraja je bilo najprej imenovano Luz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Jakob se je zaobljubil, rekoč: »Če bo Bog z menoj in me bo varoval na tej poti, ki jo hodim in mi bo dal za jesti kruha in oblačilo, da ga oblečem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'tako da ponovno v miru pridem k hiši svojega očeta, potem bo Gospod moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'In ta kamen, ki sem ga postavil za steber, bo Božja hiša. Od vsega, kar mi boš dal, ti bom zagotovo dajal desetino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Potem je Jakob odšel na svoje potovanje in prišel v deželo vzhodnega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Pogledal je in na polju zagledal izvir in glej, tam so bili trije tropi ovac, ležeč pri njem, kajti iz tega izvira so napajali trope. Na vodnjakovih ustih pa je bil velik kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Tja so se zbirali vsi tropi in odvalili so kamen iz vodnjakovih ust, napojili ovce in kamen ponovno položili na vodnjakova usta, na njegovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jakob jim je rekel: »Moji bratje, od kod ste?« Odgovorili so: »Iz Harána smo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Rekel jim je: »Poznate Nahórjevega sina Labána?« Rekli so: »Poznamo ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Rekel jim je: »Ali je zdrav?« Rekli so: »Zdrav je in glej, njegova hči Rahela prihaja z ovcami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Rekel je: »Glej, še dolg dan je niti ni čas, da bi se živina zbrala skupaj. Napojite ovce in odženite jih past.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Rekli so: »Ne moremo, dokler se ne zberejo vsi tropi in dokler kamna ne odvalijo iz vodnjakovih ust. Potem napojimo ovce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Medtem ko je še govoril z njimi, je prišla Rahela z ovcami svojega očeta, kajti ona jih je varovala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Pripetilo se je, ko je Jakob opazil Rahelo, hčer materinega brata Labána in ovce materinega brata Labána, da se je Jakob približal in odvalil kamen od vodnjakovih ust in napojil trop Labána, brata svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Jakob je poljubil Rahelo in povzdignil svoj glas in zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Jakob je Raheli povedal, da je brat njenega očeta in da je Rebekin sin. In ta je stekla ter povedala svojemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Pripetilo se je, ko je Labán slišal te novice o Jakobu, sinu svoje sestre, da je stekel, da ga sreča, ga objel, poljubil in privedel k svoji hiši. In Labánu je povedal vse te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'In Labán mu je rekel: »Zagotovo si moja kost in moje meso.« In z njim je ostal čas enega meseca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Labán je rekel Jakobu: »Ker si moj brat, zakaj bi mi služil zaman? Povej mi kakšna naj bodo tvoja plačila?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Labán pa je imel dve hčeri. Starejši je bilo ime Lea, ime mlajše pa je bilo Rahela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea je bila nežnih oči, toda Rahela je bila krasna in lepega videza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jakob pa je ljubil Rahelo in rekel: »Sedem let ti bom služil za Rahelo, tvojo mlajšo hčer.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Labán je rekel: »Bolje je to, da jo dam tebi, kakor da bi jo dal kateremukoli drugemu moškemu. Ostani z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jakob je sedem let služil za Rahelo in zdela so se mu [kot] le nekaj dni, zaradi ljubezni, ki jo je imel do nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Jakob je rekel Labánu: »Daj mi mojo ženo, kajti moji dnevi so dopolnjeni, da lahko grem noter vanjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Labán je zbral skupaj vse može tega kraja in priredil gostijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Pripetilo pa se je zvečer, da je vzel svojo hčer Leo in jo privedel k njemu in on je šel noter k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'In Labán je svoji hčeri Lei za pomočnico dal svojo služabnico Zilpo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Pripetilo se je zjutraj, glej, to je bila Lea, in Labánu je rekel: »Kaj je to, kar si mi storil? Ali nisem s teboj služil za Rahelo? Zakaj si me potem preslepil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Labán je rekel: »V naši deželi se ne sme tako storiti, da se mlajšo izroči pred prvorojeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Dopolni njen teden in dali ti bomo tudi njo, za službo, ki jo boš služil z menoj še drugih sedem let.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob je storil tako in dopolnil njen teden, on pa mu je dal tudi svojo hčer Rahelo za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Labán je svoji hčeri Raheli dal svojo pomočnico Bilho, da postane njena služabnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Odšel je tudi k Raheli in Rahelo je ljubil bolj kakor Leo in pri njem je služil še drugih sedem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Ko je Gospod videl, da je bila Lea osovražena, je odprl njeno maternico, toda Rahela je bila jalova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lea je spočela, rodila sina in njegovo ime imenovala Ruben, kajti rekla je: »Zagotovo je Gospod pogledal na mojo stisko. Sedaj me bo torej moj soprog ljubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Ponovno je spočela in rodila sina ter rekla: »Ker je Gospod slišal, da sem bila osovražena, mi je zato dal tudi tega sina,« in njegovo ime je imenovala Simeon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Ponovno je spočela in rodila sina in rekla: »Torej tokrat bo moj soprog pridružen k meni, ker sem mu rodila tri sinove,« zato je bilo njegovo ime imenovano Lévi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Ponovno je spočela in rodila sina in rekla: »Sedaj bom hvalila Gospoda,« zato je njegovo ime poimenovala Juda; in prenehala je rojevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Ko je Rahela videla, da Jakobu ne rojeva otrok, je Rahela zavidala svoji sestri in Jakobu rekla: »Daj mi otroke, sicer umrem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakobova jeza je bila vžgana zoper Rahelo in rekel je: » Sem jaz namesto Boga, ki je pred teboj zadržal sad tvoje maternice?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Rekla je: »Glej, moja služabnica Bilha, pojdi noter vanjo in rodila bo na mojih kolenih, da bom po njej tudi jaz lahko imela otroke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'In dala mu je za ženo Bilho, svojo pomočnico, in Jakob je šel noter k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha je spočela in Jakobu rodila sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Rahela je rekla: »Bog me je sodil in je tudi slišal moj glas in mi dal sina,« zato je njegovo ime imenovala Dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Rahelina služabnica Bilha je ponovno spočela in Jakobu rodila drugega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Rahela je rekla: »Z velikimi boji sem se bojevala s svojo sestro in sem prevladala,« in njegovo ime je imenovala Neftáli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Ko je Lea videla, da je prenehala rojevati, je vzela svojo služabnico Zilpo in jo dala Jakobu za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Leina služabnica Zilpa je Jakobu rodila sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, '§ Lea je rekla: »Prihaja krdelo,« in njegovo ime je imenovala Gad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Leina služabnica Zilpa je Jakobu rodila drugega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Lea je rekla: »Srečna sem, kajti hčere me bodo imenovale blagoslovljena,« in njegovo ime je imenovala Aser.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben je šel v dneh pšenične žetve in na polju našel nadliščke in jih prinesel svoji materi Lei. Potem je Rahela rekla Lei: »Daj mi, prosim te, nadliščke svojega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Ta pa ji je rekla: » Je to majhna zadeva, da si mi vzela soproga? In hočeš mi vzeti tudi nadliščke mojega sina?« Rahela je rekla: »Zato bo to noč ležal s teboj za nadliščke tvojega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Jakob je zvečer prišel iz polja in Lea je odšla ven, da ga sreča ter mu rekla: »Moraš priti noter k meni, kajti zagotovo sem te najela z nadliščki svojega sina.« In to noč je ležal z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Bog je prisluhnil Lei in je spočela in Jakobu rodila petega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Lea je rekla: »Bog mi je dal najemnino, ker sem svojo deklo dala svojemu soprogu,« in njegovo ime je imenovala Isahár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lea je ponovno spočela in Jakobu rodila šestega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Lea je rekla: »Bog me je opremil z dobro doto. Sedaj bo moj soprog prebival z menoj, ker sem mu rodila šest sinov« in njegovo ime je imenovala Zábulon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Potem je rodila hčer in njeno ime je imenovala Dina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Bog pa se je spomnil Rahele in Bog ji je prisluhnil ter odprl njeno maternico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Spočela je in rodila sina in rekla: »Bog je odvzel mojo grajo,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'in njegovo ime je imenovala Jožef; in rekla: » Gospod mi bo dodal [še] drugega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Pripetilo se je, ko je Rahela rodila Jožefa, da je Jakob rekel Labánu: »Pošlji me proč, da lahko grem na svoj lasten kraj in v svojo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Daj mi moje žene in moje otroke, za katere sem ti služil in me pusti iti, kajti poznaš mojo službo, ki sem ti jo opravljal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Labán mu je rekel: »Prosim te, če sem v tvojih očeh našel naklonjenost, ostani, kajti iz izkušnje sem se naučil, da me je Gospod zaradi tebe blagoslovil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'In rekel je: »Določi mi svoja plačila in dal ti jih bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Rekel mu je: »Ti veš kako sem ti služil in kako je bila tvoja živina z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Kajti bilo je malo, kar si imel, preden sem prišel in to je sedaj naraslo v množico in Gospod te je od mojega prihoda blagoslavljal. Kdaj bom torej poskrbel tudi za svojo lastno hišo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'In rekel je: »Kaj naj ti dam?« Jakob je rekel: »Nobene stvari mi ne boš dal. Če hočeš zame storiti to stvar, bom ponovno pasel in varoval tvoj trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Danes pojdem skozi ves tvoj trop in iz njega odstranim vso lisasto in pikasto živino in vso rjavo živino med ovcami in pikasto ter lisasto med kozami. Od teh bo moja najemnina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Tako bo moja pravičnost odgovarjala zame v času, ki pride, ko bo prišel, za moj najem pred tvojim obrazom. Vse, kar ni lisasto in pikasto med kozami in rjavo med ovcami, to bo pri meni šteto za ukradeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Labán je rekel: »Glej, hočem, da bi bilo glede na tvojo besedo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'In ta dan je odstranil kozle, ki so bili krožno progasti in pikasti in vse koze, ki so bile lisaste in pikaste in vsako, ki je imela na sebi nekaj belega in vse rjavo med ovcami in jih dal v roko svojih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Med seboj in Jakobom je določil tri dni potovanja in Jakob je hranil preostanek Labánovih tropov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Jakob si je vzel šibe zelenega topola in od leskovega in kostanjevega drevesa in na njih olupil bele proge in storil, da se prikaže belina, ki je bila na šibah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Palice, ki jih je olupil, je postavljal pred trope v žlebove, v napajalna korita, ko so tropi prišli, da pijejo, da bi se obrejili, ko so prišli pit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Tropi so se obrejili pred palicami in skotili krožno progasto, lisasto in pikasto živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Jakob je v Labánovem tropu ločeval jagnjeta in postavljal obraze tropov h krožno progastemu in vsemu rjavemu. Svoje lastne trope pa je spravljal posebej in jih ni spravljal v Labánovo živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Pripetilo se je, da kadarkoli se je brejila močnejša živina, je Jakob polagal šibe pred očmi živine v žlebove, da bi se lahko obrejile med palicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Toda ko je bila živina slabotna, jih ni polagal. Tako je bila slabotnejša živina Labánova, močnejša pa Jakobova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Mož je silno narasel in imel mnogo živine, dekel, slug, kamel in oslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Slišal pa je besede Labánovih sinov, rekoč: »Jakob je vzel vse, kar je bilo našega očeta, in od tega, kar je bilo našega očeta, je dobil vso to slavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jakob je gledal Labánovo obličje in glej, ni bilo proti njemu kakor poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Gospod je Jakobu rekel: »Vrni se v deželo svojih očetov in k svojemu sorodstvu in jaz bom s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jakob je poslal in poklical Rahelo in Leo na polje k svojemu tropu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'ter jima rekel: »Vidim obličje vajinega očeta, da le-to do mene ni kakor poprej, toda Bog mojega očeta je bil z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vedve vesta, da sem z vso svojo močjo služil vajinemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Vajin oče pa me je zavedel in mi desetkrat spremenil moja plačila, toda Bog mu ni dovolil, da bi me prizadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Če je rekel tako: ›Lisasta bodo tvoja plačila;‹ potem je vsa živina kotila lisaste. Če pa je rekel tako: ›Krožno progasta bodo tvoja najemnina,‹ potem je vsa živina kotila krožno progaste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Tako je Bog odvzel živino od vajinega očeta in jo dal meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Pripetilo se je ob času, ko se je živina obrejila, da sem povzdignil svoje oči in videl sanje in glej ovni, ki so skakali na živino, so bili krožno progasti, lisasti in sivi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'In Božji angel mi je v sanjah spregovoril, rekoč: ›Jakob.‹ Rekel sem: ›Tukaj sem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Rekel je: ›Povzdigni torej svoje oči in poglej, vsi ovni, ki skačejo na živino, so krožno progasti, lisasti in sivi, kajti videl sem vse, kar ti je Labán storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jaz sem Bog Betela, kjer si mazilil steber in mi zaobljubil prisego. Sedaj vstani, pojdi ven iz te dežele in se vrni v deželo svojega sorodstva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Rahela in Lea sta mu odgovorili in rekli: » Ali je še kak delež ali dediščina za naju v hiši najinega očeta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Ali nisva pri njem šteti [kakor] tujki? Kajti prodal naju je in popolnoma požrl tudi najin denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Kajti vsa bogastva, ki jih je Bog vzel od najinega očeta, ta so najina in najinih otrok. Sedaj torej karkoli ti je Bog rekel, stôri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Potem je Jakob vstal in svoje sinove in svoji ženi posadil na kamele');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, '§ in odvedel proč vso svojo živino in vse svoje dobrine, ki jih je pridobil, živino od svojega zaslužka, ki jo je pridobil v Padan–aramu, da bi šel k svojemu očetu Izaku v kánaansko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Labán je odšel, da ostriže svoje ovce. Rahela pa je ukradla malike, ki so bili [od] njenega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakob se je nenadoma odtihotapil od Sirca Labána, v tem, da mu ni povedal, da je pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Tako je pobegnil z vsem, kar je imel in vstal ter prečkal reko in svoje obličje nameril proti gori Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Labánu je bilo tretji dan povedano, da je Jakob pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'S seboj je vzel svoje brate in ga zasledoval sedem dni potovanja in dohiteli so ga na gori Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Bog je prišel ponoči, v sanjah, k Sircu Labánu ter mu rekel: »Pazi, da Jakobu ne govoriš niti dobrega niti slabega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Potem je Labán dohitel Jakoba. Torej Jakob je svoj šotor postavil na gori, Labán pa se je s svojimi brati utaboril na gori Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Labán je rekel Jakobu: »Kaj si storil, da si se nenadoma odtihotapil od mene in odvedel moji hčeri kakor ujetnici vzeti z mečem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Zakaj si skrivaj pobegnil in se odtihotapil od mene in mi nisi povedal, da bi te lahko odposlal z veseljem in s pesmimi, z bobniči in s harfo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Nisi mi dovolil, da poljubim svoje sinove in svoje hčere? To si torej s takšnim početjem storil nespametno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'V moči moje roke je, da vam škodujem. Toda sinoči mi je govoril Bog tvojega očeta, rekoč: ›Pazi se, da Jakobu ne govoriš niti dobrega niti slabega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'In sedaj, čeprav imaš potrebo oditi, ker si že dolgo hrepenel po hiši svojega očeta, zakaj si vendar ukradel moje bogove?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jakob je odgovoril in Labánu rekel: »Ker sem se bal, kajti rekel sem: ›Morda mi hočeš s silo odvzeti svoji hčeri.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Pri komerkoli najdeš svoje bogove, naj ta ne živi. Pred svojimi brati spoznaj kar je tvojega z menoj in to vzemi k sebi.« Kajti Jakob ni vedel, da jih je ukradla Rahela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Labán je odšel v Jakobov šotor in v Lein šotor in v šotore obeh dekel, toda ni jih našel. Potem je odšel od Leinega šotora in vstopil v Rahelin šotor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Torej Rahela je vzela družinske malike in jih položila na kamelino opravo in sedla nanje. Labán pa je preiskal ves šotor, toda ni jih našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Svojemu očetu pa je rekla: »Naj moj gospod ne bo razžaljen, da ne morem vstati pred teboj, kajti običaj žensk je nad menoj.« In iskal je, toda podob ni našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jakob je bil ogorčen in se pričkal z Labánom in Jakob je odgovoril ter Labánu rekel: »Kaj je moj prekršek? Kaj je moj greh, da si me tako silovito zasledoval?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Glede na to, da si preiskal vse moje stvari, kaj si našel od vseh svojih družinskih stvari? Položi to tukaj pred mojimi brati in svojimi brati, da lahko sodijo med nama obema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Teh dvajset let sem bil s teboj. Tvoje ovce in tvoje koze niso zavrgle svojih mladičev in ovnov tvojega tropa nisem jedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Tega, kar je bilo raztrganega od živali, nisem prinesel k tebi. Sam sem nosil to izgubo. Iz mojih rok si zahteval karkoli je bilo ukradenega podnevi ali ukradenega ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Tak sem bil. Podnevi me je požirala suša in zmrzal ponoči in moje spanje je odšlo izpred mojih oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Tako sem bil dvajset let v tvoji hiši. Služil sem ti štirinajst let za tvoji hčeri in šest let za tvojo živino, ti pa si mi desetkrat spremenil moja plačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Razen če ne bi bil z menoj Bog mojega očeta, Abrahamov Bog in Izakov strah, bi me sedaj zagotovo odposlal praznega. Bog je videl mojo stisko in trud mojih rok in te je včerajšnjo noč oštel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Labán je odgovoril in Jakobu rekel: » Ti hčeri sta moji hčeri in ti otroci so moji otroci in ta živina je moja živina in vse, kar vidiš, je moje. In kaj naj danes storim tema svojima hčerama ali njunim otrokom, ki sta jih rodili?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Zdaj torej pridi, skleniva zavezo, ti in jaz; in naj bo to za pričo med menoj in teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Jakob je vzel kamen in ga postavil za steber.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Jakob je rekel svojim bratom: »Zberite kamne;« in vzeli so kamne ter naredili kup in jedli tam na kupu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Labán ga je imenoval Jegár Sahadutá, toda Jakob ga je imenoval Galéd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Labán je rekel: »Ta kup je danes priča med menoj in teboj.« Zato je bilo ime le-tega imenovano Galéd');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'in Micpa, kajti rekel je: » Gospod gleda med menoj in teboj, ko smo odsotni eden od drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Če boš prizadel moji hčeri ali če boš poleg mojih hčera vzel druge žene, ni z nama nobenega človeka. Glej, Bog je priča med menoj in teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Labán je rekel Jakobu: »Glej ta kup in glej ta steber, ki sem ga postavil med menoj in teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Ta kup naj bo priča in ta steber naj bo priča, da ne bom šel čez ta kup k tebi in da ne boš šel čez ta kup k meni zaradi škodovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, '§ Bog Abrahamov in Bog Nahórjev, Bog njunega očeta, [naj] sodi med nama.« In Jakob je prisegel pri strahu svojega očeta Izaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Potem je Jakob na gori žrtvoval klavno daritev in poklical svoje brate, da jedo kruh. Jedli so kruh in se vso noč zadrževali na gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Zgodaj zjutraj je Labán vstal, poljubil svoje sinove in svoje hčere ter jih blagoslovil in Labán je odpotoval ter se vrnil na svoj kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jakob pa je odšel na svojo pot in Božji angeli so ga srečali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Ko jih je Jakob zagledal, je rekel: »To je Božja vojska« in ta kraj je imenoval Mahanájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Jakob je pred seboj poslal poslance k svojemu bratu Ezavu v deželo Seír, Edómovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Zapovedal jim je, rekoč: »Tako boste govorili mojemu gospodu Ezavu: ›Tvoj služabnik Jakob nam je rekel: ›Začasno sem bival z Labánom in tam ostal do sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Imam vole, osle, trope, sluge in postrežnice. Poslal sem, da povem svojemu gospodu, da lahko najdem milost v tvojem pogledu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Poslanci so se vrnili k Jakobu, rekoč: »Prišli smo k tvojemu bratu Ezavu in tudi on prihaja, da te sreča in z njim štiristo mož.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Potem je bil Jakob silno prestrašen in zaskrbljen. Razdelil je ljudstvo, ki je bilo z njim, trope, črede in kamele na dve četi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'in rekel: »Če pride Ezav k eni skupini in jo udari, potem bo druga skupina, ki je ostala, pobegnila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Jakob je rekel: »Oh, Bog mojega očeta Abrahama in Bog mojega očeta Izaka, Gospod, ki mi je rekel: ›Vrni se v svojo deželo in k svojemu sorodstvu in jaz bom dobro postopal s teboj,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'sam nisem vreden najmanjše od teh milosti in od vse resnice, ki si jo izkazal svojemu služabniku, kajti s svojo palico sem prečkal ta Jordan, sedaj pa sem narastel v dve četi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Reši me, prosim te, iz roke mojega brata, iz Ezavove roke, kajti bojim se ga, da ne bi prišel in udaril mene in matere z otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'In ti praviš: ›Zagotovo ti bom storil dobro in tvojega semena naredil kakor morskega peska, ki zaradi množice ne more biti preštet.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'To isto noč je tam prenočil in od tega, kar je prišlo v njegovo roko, je vzel darilo za svojega brata Ezava:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'dvesto koz in dvajset kozlov, dvesto ovc in dvajset ovnov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'trideset molznih kamel z njihovimi žrebeti, štirideset krav in deset bikov, dvajset oslic in deset žrebet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Izročil jih je v roko svojih služabnikov, vsako čredo posebej. Svojim služabnikom pa je rekel: »Prečkajte pred menoj in pustite prostor med čredo in čredo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Predvsem pa je naročil, rekoč: »Ko te sreča moj brat Ezav in te vpraša, rekoč: ›Čigav si? In kam greš? In čigavi so ti pred teboj?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Tedaj boš rekel: › To so od tvojega služabnika Jakoba. To je darilo, poslano k mojemu gospodu Ezavu in glej, tudi on je za nami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'In tako je ukazal drugemu in tretjemu in vsem, ki so sledili čredam, rekoč: »Na ta način boste govorili Ezavu, ko ga najdete.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Poleg tega recite: »Glej, tvoj služabnik Jakob je za nami. Kajti rekel je: ›Pomiril ga bom z darilom, ki gre pred menoj in zatem bom videl njegov obraz. Mogoče me bo sprejel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Tako je šlo darilo pred njim, sam pa je to noč prenočil v skupini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Vstal je to noč, vzel svoji dve ženi, svoji dve postrežnici, svojih enajst sinov in prečkal plitvino Jabók.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Vzel jih je in jih poslal preko potoka in poslal čez, kar je imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jakob je ostal sam in z njim se je bojeval mož do dnevnega svita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Ko je videl, da zoper [Jakoba] ni prevladal, se je dotaknil vdrtine na njegovem stegnu. Vdrtina Jakobovega stegna je bila izpahnjena, kakor [bi] se z njim boril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Rekel je: »Pusti me, kajti dan se že svita.« [Jakob] je rekel: »Ne bom te izpustil, razen če me blagosloviš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Rekel mu je: »Kako ti je ime?« Rekel je: »Jakob.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, '§ Rekel je: »Tvoje ime se ne bo več imenovalo Jakob, temveč Izrael, kajti kot princ si imel moč z Bogom in z ljudmi in si prevladal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Jakob ga je vprašal in rekel: »Povej mi, prosim te, svoje ime.« Rekel je: »Zakaj je to, da me sprašuješ po mojem imenu?« In tam ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jakob je kraj poimenoval Penuél, kajti videl sem Boga iz obličja v obličje in moje življenje je ohranjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Ko je prečkal Penuél, je sonce vstajalo nad njim, on pa je šepal na svojem stegnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Zato Izraelovi otroci ne jedo od kite, ki se krči, ki je na vdrtini stegna, do današnjega dne, ker se je dotaknil vdrtine Jakobovega stegna na kiti, ki se krči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jakob je povzdignil svoje oči, pogledal in glej, prišel je Ezav in z njim štiristo mož. Otroke je razdelil Lei in Raheli ter dvema pomočnicama.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Najbolj spredaj je postavil pomočnici ter njune otroke, za njimi Leo ter njene otroke, nazadnje pa Rahelo in Jožefa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Šel je pred njimi in se sedemkrat priklonil do tal, dokler se ni približal svojemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ezav je stekel, da ga sreča, ga objel, se spustil na njegov vrat in ga poljubil, in oba sta jokala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Povzdignil je svoje oči in zagledal ženske in otroke ter rekel: »Kdo so ti s teboj?« Rekel je: »Otroci, ki jih je Bog milostljivo dal tvojemu služabniku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Nato sta se približali pomočnici, oni in njuni otroci ter se priklonili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Tudi Lea s svojimi otroki se je približala in se priklonila in potem sta prišla bliže Jožef in Rahela ter se oba priklonila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Rekel je: »Kaj nameravaš z vso to čredo, ki sem jo srečal?« On pa je rekel: » Ti so, da najdem milost v očeh mojega gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Ezav je rekel: »Dovolj imam, moj brat. To, kar imaš, obdrži zase.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob je rekel: »Ne, prosim te, če sem torej našel milost v tvojih očeh, potem sprejmi moje darilo v moji roki, kajti zato sem videl tvoj obraz, kot da sem videl Božje obličje in ti si bil zadovoljen z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Vzemi, prosim te, moj blagoslov, ki je priveden k tebi, ker je Bog milostljivo postopal z menoj in ker imam dovolj.« Prigovarjal mu je in on je to vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Rekel je: »Naj greva najino potovanje in naj greva, jaz pa bom šel pred teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Rekel mu je: »Moj gospod ve, da so otroci nežni in [da] so z menoj tropi in črede z mladiči in če jih bodo ljudje en dan preveč gonili, bo ves trop poginil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Naj moj gospod, prosim te, gre preko pred svojim služabnikom, jaz pa bom mirno vodil dalje, kolikor bodo živina, ki gre pred menoj in otroci zmožni prenesti, dokler ne pridem k mojemu gospodu v Seír.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Ezav je rekel: »Naj torej pustim s teboj nekaj ljudstva, ki je z menoj.« Rekel je: »Kaj potrebujem to? Naj najdem milost v očeh svojega gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Tako se je ta dan Ezav vrnil na svojo pot v Seír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, '§ Jakob pa je odpotoval v Sukót, si zgradil hišo in naredil šotore za svojo živino. Zato se ime kraja imenuje Sukót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, '§ Ko je Jakob prišel iz Padan–arama, je prišel v Salem, mesto v Sihemu, ki je v kánaanski deželi in svoj šotor postavil pred mestom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Kupil je kos poljskega zemljišča, kjer je razširil svoj šotor, iz roke otrok Hamórja, Sihemovega očeta, za sto koščkov denarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Tam je postavil oltar in ga imenoval El–elohe–Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina, Lejina hči, ki jo je rodila Jakobu, pa je odšla, da pogleda hčere dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Ko jo je zagledal Sihem, sin Hivéjca Hamórja, princ dežele, jo je vzel in legel z njo ter jo omadeževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Njegova duša se je pridružila k Jakobovi hčeri Dini in ljubil je gospodično in gospodični prijazno govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Sihem je spregovoril svojemu očetu Hamórju, rekoč: »Pridobi mi to gospodično za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob je slišal, da je omadeževal njegovo hčer Dino. Torej njegovi sinovi so bili z živino na polju in Jakob je ohranil svoj mir, dokler niso prišli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Sihemov oče Hamór je odšel k Jakobu, da se z njim posvetuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Ko so to slišali Jakobovi sinovi, so prišli s polja. Možje so bili užaloščeni in zelo ogorčeni, ker je storil neumnost v Izraelu, ležeč z Jakobovo hčerjo, katera stvar se sploh ne bi smela zgoditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hamór se je z njimi posvetoval, rekoč: »Duša mojega sina Sihema hrepeni za vašo hčerjo. Prosim vas, dajte mu jo za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Poročajte se z nami in svoje hčere dajajte nam in jemljite naše hčere k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Prebivali boste z nami in dežela bo pred vami. Prebivajte in trgujte v njej in si pridobite posesti v njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sihem je rekel njenemu očetu in njenim bratom: »Naj najdem milost v vaših očeh in kar mi boste rekli, bom dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Prosite me kolikorkoli veliko doto in darilo in bom dal, če mi boste rekli, toda dajte mi gospodično za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Jakobovi sinovi pa so Sihemu in njegovemu očetu Hamórju varljivo odgovorili ter rekli, ker je omadeževal njihovo sestro Dino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Rekli so jima: »Ne moremo storiti te stvari, da damo svojo sestro nekomu, ki je neobrezan, kajti to bi nam bil očitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Toda v tem se bomo strinjali z vami, če boste, kakor smo mi, da bo vsak moški izmed vas obrezan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'potem vam bomo dajali svoje hčere in vaše hčere jemali k nam in prebivali bomo z vami in postali bomo eno ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Toda če nam ne boste prisluhnili, da bi bili obrezani, potem bomo vzeli svojo hčer in odšli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Njihove besede so ugajale Hamórju in Hamórjevemu sinu Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Mladenič ni odlašal storiti stvari, ker je imel veselje v Jakobovi hčeri. Bil pa je bolj častitljiv kakor vsa hiša njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Hamór in njegov sin Sihem sta prišla k velikim vratom njihovega mesta in se posvetovala z možmi njihovega mesta, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '»Ti ljudje so z nami miroljubni, zato naj prebivajo v deželi in v njej trgujejo, kajti dežela, glejte, ta je dovolj velika zanje. Jemljimo si njihove hčere za žene in dajajmo jim svoje hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Samo v tem se bodo možje strinjali z nami, da prebivajo z nami, da bi bili eno ljudstvo, če bo vsak moški izmed nas obrezan, kakor so obrezani oni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ali ne bo njihova živina in njihovo imetje in vsaka njihova žival naša? Naj se samo strinjamo z njimi in bodo prebivali z nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Hamórju in njegovemu sinu Sihemu so prisluhnili vsi, ki so odšli od velikih vrat tega mesta, in vsak moški je bil obrezan, vsi, ki so šli od velikih vrat njegovega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Pripetilo pa se je na tretji dan, ko so bili občutljivi, da sta dva izmed Jakobovih sinov, Simeon in Lévi, Dinina brata, vzela vsak svoj meč in predrzno prišla nad mesto in usmrtila vse njihove moške.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Usmrtila sta Hamórja in njegovega sina Sihema z ostrino meča, Dino pa vzela iz Sihemove hiše ter odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Jakobovi sinovi so prišli na umorjene in oplenili mesto, ker so omadeževali njihovo sestro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Vzeli so njihove ovce, njihove vole, njihove osle in to, kar je bilo v mestu in to, kar je bilo na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Vse njihovo premoženje, vse njihove malčke in vse njihove žene so ujeli in oplenili celo vse, kar je bilo v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jakob je rekel Simeonu in Léviju: »Privedla sta me v neprijeten položaj, da zaudarjam med prebivalci dežele, med Kánaanci in Perizéjci. Jaz sem maloštevilen, oni pa se bodo zbrali zoper mene in me ubili, in jaz bom uničen, jaz in moja hiša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Rekli so: »Naj bi z našo sestro postopal kakor s pocestnico?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Bog je Jakobu rekel: »Vstani, pojdi gor v Betel in tam prebivaj in tam naredi oltar Bogu, ki se ti je prikazal, ko si zbežal pred obličjem svojega brata Ezava.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Potem je Jakob rekel svoji družini in vsem, ki so bili z njim: »Odstranite tuje bogove, ki so med vami in bodite čisti ter zamenjajte svoje obleke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'in vstanimo, pojdimo gor v Betel in tam bom postavil oltar Bogu, ki mi je odgovoril na dan moje tegobe in je bil z menoj na poti, [na] katero sem odšel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Jakobu so izročili vse tuje bogove, ki so bili v njihovi roki in vse njihove uhane, ki so bili v njihovih ušesih in Jakob jih je skril pod hrast, ki je bil pri Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Odpotovali so, Božja strahota pa je bila nad mesti, ki so bila naokoli njih in niso zasledovali Jakobovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Tako je Jakob prišel v Luz, ki je v kánaanski deželi, to je Betel, on in njegovo ljudstvo, ki je bilo z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Tam je zgradil oltar in kraj imenoval El-Betel, ker se mu je tam prikazal Bog, ko je bežal pred obličjem svojega brata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'toda Rebekina dojilja Debóra je umrla in pokopana je bila za Betelom, pod hrastom in ime le-tega je bilo imenovano Alon–bakut.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Bog se je ponovno prikazal Jakobu, ko je ta prišel iz Padan–arama in ga blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Bog mu je rekel: »Tvoje ime je Jakob. Tvoje ime se ne bo več imenovalo Jakob, temveč bo tvoje ime Izrael.« In njegovo ime je imenoval Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Bog mu je rekel: »Jaz sem Bog Vsemogočni. Bodi rodoviten in se mnôži. Narod in skupina narodov bo iz tebe in kralji bodo prišli iz tvojih ledij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Deželo, ki sem jo dal Abrahamu in Izaku, bom dal tebi in tvojemu semenu za teboj bom dal deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Bog se je dvignil od njega, na kraju, kjer je govoril z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jakob je postavil steber na kraju, kjer je govoril z njim, kamnit steber in nanj izlil pitno daritev in nanj izlil olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Jakob je ime kraja, kjer je z njim govoril Bog, imenoval Betel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Odpotovali so iz Betela in bilo je le še malo poti, da pridejo v Efráto in Rahela je bila v porodnih mukah in imela težak porod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Pripetilo se je, ko je bila v težkem porodu, da ji je babica rekla: »Ne boj se, imela boš tudi tega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Pripetilo se je, ko je bila njena duša v odhajanju (kajti umrla je), da je njegovo ime imenovala Ben Oní. Toda njegov oče ga je imenoval Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Rahela je umrla in bila pokopana na poti v Efráto, ki je Betlehem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jakob je na njenem grobu postavil steber. To je steber Rahelinega groba do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Izrael je odpotoval in svoj šotor razpel onstran stolpa Edar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Pripetilo se je, ko je Izrael prebival v tej deželi, da je Ruben šel in ležal z Bilho, priležnico svojega očeta, Izrael pa je to slišal. Torej Jakobovih sinov je bilo dvanajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Leini sinovi: Jakobov prvorojenec Ruben, Simeon, Lévi, Juda, Isahár in Zábulon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rahelina sinova: Jožef in Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Sinova Bilhe, Raheline pomočnice: Dan in Neftáli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Sinova Zilpe, Leine pomočnice: Gad in Aser. To so Jakobovi sinovi, ki so mu bili rojeni v Padan–aramu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jakob je prišel k svojemu očetu Izaku v Mamre, v mesto Arbo, ki je Hebrón, kjer sta Abraham in Izak začasno prebivala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Izakovih dni je bilo sto osemdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'In Izak je izročil duha in umrl in bil zbran k svojemu ljudstvu, star in izpolnjen z dnevi. Pokopala pa sta ga njegova sinova Ezav in Jakob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Torej to so rodovi Ezava, ki je Edóm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezav je svoje žene vzel iz Kánaana: Ado, hčer Hetejca Elóna, Oholibámo, hčer Anája, hčer Hivéjca Cibóna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'in Basemáto, Izmaelovo hčer, Nebajótovo sestro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada je Ezavu rodila Elifáza, Basemáta je rodila Reguéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibáma je rodila Jeúša, Jaláma in Koraha. To so Ezavovi sinovi, ki so se mu rodili v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ezav je vzel svoje žene, svoje sinove, svoje hčere, vse osebe svoje hiše, svojo živino, vse svoje živali in vse svoje imetje, ki ga je pridobil v kánaanski deželi in odšel v deželo izpred obličja svojega brata Jakoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Kajti njunih bogastev je bilo preveč, da bi mogla prebivati skupaj. Dežela, v kateri sta bila tujca, ju ni mogla podpirati zaradi njune živine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Tako je Ezav prebival na gorovju Seír. Ezav je Edóm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'To so rodovi Ezava, očeta Edómcev na gorovju Seír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'To so imena Ezavovih sinov: Elifáz, sin Ezavove žene Ade in Reguél, sin Ezavove žene Basemáte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Elifázovi sinovi so bili: Temán, Omár, Cefó, Gatám in Kenáz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna je bila priležnica Ezavovemu sinu Elifázu in Elifázu je rodila Amáleka. To so bili sinovi Ezavove žene Ade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'To so sinovi Reguéla: Nahat, Zerah, Šamá in Mizá. To so bili sinovi Ezavove žene Basemáte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, '§ Ti so bili sinovi Ezavove žene Oholibáme, hčere Anája, Cibónove hčere; Ezavu je rodila Jeúša, Jaláma in Koraha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'To so bili vojvode Ezavovih sinov. Sinovi Elifáza, prvorojenega Ezavovega sina: vojvoda Temán, vojvoda Omár, vojvoda Cefó, vojvoda Kenáz,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'vojvoda Korah, vojvoda Gatám in vojvoda Amálek. To so vojvode, ki so izšli iz Elifáza v deželi Edóm. To so bili Adini sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'To so sinovi Ezavovega sina Reguéla: vojvoda Nahat, vojvoda Zerah, vojvoda Šamá in vojvoda Mizá. To so vojvode, ki so izšli iz Reguéla v Edómovi deželi. To so sinovi Ezavove žene Basemáte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'To pa so sinovi Ezavove žene Oholibáme: vojvoda Jeúš, vojvoda Jalám, vojvoda Korah. To so bili vojvode, ki so izšli iz Ezavove žene Oholibáme, Anájeve hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'To so Ezavovi sinovi, ki je Edóm in to so njihove vojvode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'To so sinovi Horéjca Seírja, ki je naselil deželo: Lotán, Šobál, Cibón, Anáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dišón, Ecer in Dišán. To so vojvode Horéjcev, Seírjevi otroci v deželi Edóm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Lotánova sinova sta bila Horí in Hemám; Lotánova sestra pa je bila Timna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Šobálovi otroci so bili tile: Alván, Manáhat, Ebál, Šefo in Onám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, '§ To sta Cibónova otroka: oba, Ajá in Aná. To je bil ta Anáj, ki je našel mule v divjini, ko je pasel osle svojega očeta Cibóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Anájeva otroka sta bila ta: Dišón in Oholibáma, Anájeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'To so Dišónovi otroci: Hemdán, Ešbán, Jitrán in Kerán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ecerjevi otroci so tile: Bilhán, Zaaván in Akán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dišánova otroka sta tale [dva]: Uc in Arán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'To so vojvode, ki so izšli iz Horéjcev: vojvoda Lotán, vojvoda Šobál, vojvoda Cibón, vojvoda Anáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'vojvoda Dišón, vojvoda Ecer in vojvoda Dišán. To so vojvode, ki so izšli iz Horéjcev, med njihovimi vojvodami v deželi Seír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'To so kralji, ki so kraljevali v edómski deželi, preden je katerikoli kralj kraljeval nad Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Beórjev sin Bela je kraljeval v Edómu in ime njegovega mesta je bilo Dinhába.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Bela je umrl in namesto njega je zakraljeval Zerahov sin Jobáb iz Bocre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Jobáb je umrl in namesto njega je zakraljeval Hušám iz dežele Temáncev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Hušám je umrl in namesto njega je zakraljeval Bedádov sin Hadád, ki je udaril Midján na moábskem polju in ime tega mesta je bilo Avít.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Hadád je umrl in namesto njega je zakraljeval Samlá iz Masréke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Samlá je umrl in namesto njega je zakraljeval Šaúl iz Rehobóta ob reki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Šaúl je umrl in namesto njega je zakraljeval Ahbórjev sin Báal Hanán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Ahbórjev sin Báal Hanán je umrl in namesto njega je zakraljeval Hadár. Ime njegovega mesta je bilo Pagú in ime njegove žene je bilo Mehetabéla, hči Me-Zahábove hčere Matréde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'To so imena vojvod, ki so izšli iz Ezava, glede na njihove družine, po njihovih krajih, po njihovih imenih: vojvoda Timná, vojvoda Alvá, vojvoda Jetét,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'vojvoda Oholibáma, vojvoda Elá, vojvoda Pinón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'vojvoda Kenáz, vojvoda Temán, vojvoda Mibcár,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'vojvoda Magdiél, vojvoda Irám. To so edómski vojvode, glede na njihova prebivališča v deželi njihove posesti. On je Ezav, oče Edómcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob je prebival v deželi, v kateri je bil njegov oče tujec, v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'To so Jakobovi rodovi. Jožef je bil star sedemnajst let, ko je s svojimi brati pasel trop in deček je bil s sinovi Bilhe in s sinovi Zilpe, ženama svojega očeta. Jožef je svojemu očetu prinesel njihovo zlo poročilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, '§ Torej Izrael je bolj ljubil Jožefa kakor vse svoje otroke, ker je bil sin njegove visoke starosti. Naredil mu je plašč iz mnogih barv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Ko so njegovi bratje videli, da ga je njihov oče bolj ljubil kakor vse njegove brate, so ga zasovražili in niso mogli miroljubno govoriti z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Jožef je sanjal sanje in te je povedal svojim bratom, oni pa so ga še bolj sovražili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Rekel jim je: »Poslušajte, prosim vas, te sanje, ki sem jih sanjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Kajti, glejte, na polju smo vezali snope in glejte, moj snop je vstal in tudi stal pokončno. Glejte, vaši snopi so stali naokoli in se globoko priklanjali mojemu snopu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Njegovi bratje so mu rekli: »Ali boš zares kraljeval nad nami? Ali boš zares imel gospostvo nad nami?« In še bolj so ga zasovražili zaradi njegovih sanj in zaradi njegovih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Sanjal je še druge sanje in te povedal svojim bratom in rekel: »Glejte, še sem sanjal sanje. Glejte globoko so se mi priklanjali sonce in luna in enajst zvezd.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Te je povedal svojemu očetu in svojim bratom. Njegov oče pa ga je oštel in mu rekel: »Kaj so te sanje, ki si jih sanjal? Naj zares pridemo jaz, tvoja mati in tvoji bratje, da se ti priklonimo k zemlji?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Njegovi bratje so mu zavidali, toda njegov oče je obeležil besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Njegovi bratje so odšli, da pasejo trop svojega očeta v Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Izrael je rekel Jožefu: »Mar tvoji bratje ne pasejo tropa v Sihemu? Pridi in poslal te bom k njim.« Ta mu je rekel: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Rekel mu je: »Pojdi, prosim te, poglej če je dobro s tvojimi brati in dobro s tropi in besedo mi ponovno prinesi nazaj.« Tako ga je poslal iz hebrónske doline in je prišel v Sihem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Našel pa ga je nek mož in glej, taval je po polju in človek ga je vprašal, rekoč: »Kaj iščeš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Rekel je: »Iščem svoje brate. Povej mi, prosim te, kje pasejo svoje trope.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Človek je rekel: »Odpravili so se od tod, kajti slišal sem jih reči: ›Pojdimo v Dotán.‹« Jožef je odšel za svojimi brati in jih našel v Dotánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Ko so ga od daleč zagledali, celo preden se jim je približal, so se zoper njega zarotili, da ga ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Drug drugemu so rekli: »Glejte, ta sanjač prihaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Pridimo torej, ubijmo ga in ga vrzimo v neko jamo in bomo rekli: ›Neka zla žival ga je požrla‹ in bomo videli, kaj bo nastalo iz njegovih sanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ruben pa je to slišal in ga osvobodil iz njihovih rok in rekel: »Naj ga ne ubijemo mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ruben jim je rekel: »Ne prelijmo krvi, temveč ga vrzimo v tole jamo, ki je v divjini in ne položimo roke nanj,« da bi ga lahko osvobodil iz njihovih rok, da ga ponovno izroči njegovemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, '§ Pripetilo pa se je, ko je Jožef prišel k svojim bratom, da so Jožefa slekli iz njegovega plašča, njegovega plašča iz mnogih barv, ki je bil na njem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'in ga prijeli ter vrgli v jamo. Jama pa je bila prazna, v njej ni bilo vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, '§ Usedli so se, da jedo kruh in povzdignili so svoje oči, pogledali in glej, skupina Izmaelcev je prihajala iz Gileáda, s svojimi kamelami, nesoč dišave, balzam in miro, da to odnesejo dol v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Juda je rekel svojim bratom: »Kakšna korist je to, če ubijemo svojega brata in prikrijemo njegovo kri?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Pridite in prodajmo ga Izmaelcem in naj naša roka ne bo nad njim, kajti on je naš brat in naše meso.« Njegovi bratje so bili zadovoljni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Potem so šli mimo midjánski trgovci in Jožefa so potegnili ter dvignili iz jame in Jožefa prodali Izmaelcem za dvajset koščkov srebra in ti so Jožefa pripeljali v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Ruben pa se je vrnil k jami in glej, Jožefa ni bilo v jami. Raztrgal je svoja oblačila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'in se vrnil k svojim bratom ter rekel: »Otroka ni in kam naj grem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Vzeli so Jožefov plašč, zaklali kozlička izmed koz in plašč pomočili v kri');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, '§ in poslali so plašč iz mnogih barv in ga prinesli k svojemu očetu ter rekli: »To smo našli. Védi torej, ali je to plašč tvojega sina ali ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Prepoznal ga je in rekel: » To je plašč mojega sina. Zla žival ga je požrla. Jožef je brez dvoma raztrgan na koščke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Jakob je raztrgal svoja oblačila in na svoja ledja oblekel vrečevino in mnogo dni žaloval za svojim sinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Vsi njegovi sinovi in vse njegove hčere so vstali, da ga potolažijo, toda odklonil je, da bi bil potolažen in rekel je: »Kajti žalujoč bom šel v grob k svojemu sinu.« Tako je njegov oče jokal za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Midjánci pa so ga prodali v Egipt k Potifárju, faraonovemu častniku in poveljniku straže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Pripetilo se je ob tistem času, da je Juda šel dol od svojih bratov in vstopil k nekemu Adulámcu, katerega ime je bilo Hirá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Juda je tam videl hčer nekega Kánaanca, katerega ime je bilo Šua in vzel jo je ter šel noter k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Ta je spočela in rodila sina in njegovo ime je imenoval Er.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Ponovno je spočela ter rodila sina in njegovo ime je imenovala Onán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Spet je spočela in rodila sina in njegovo ime je imenovala Šelá. Bil je pri Kezíbu, ko ga je rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda je vzel ženo za svojega prvorojenca Era, ki ji je bilo ime Tamara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Judov prvorojenec Er pa je bil zloben v Gospodovih očeh in Gospod ga je usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Juda je rekel Onánu: »Pojdi noter k ženi svojega brata in jo poroči ter svojemu bratu obudi potomca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Onán pa je vedel, da potomec ne bo njegov in pripetilo se je, ko je šel noter k ženi svojega brata, da je to izlil na tla, da svojemu bratu ne bi dal potomca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Stvar, ki jo je storil, je razžalila Gospoda, zaradi česar je tudi njega usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Potem je Juda rekel svoji snahi Tamari: »Ostani vdova, v hiši svojega očeta, dokler moj sin Šelá ne odraste,« kajti rekel je: »Da ne bi morda tudi on umrl, kakor sta njegova brata.« Tamara je odšla in prebivala v hiši svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, '§ Tekom časa je Šuova hči, Judova žena, umrla in Juda je bil potolažen in se dvignil k svojim strižcem ovc v Timno, on in njegov prijatelj Adulámec Hirá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'To je bilo povedano Tamari, rekoč: »Glej, tvoj tast gre v Timno, da ostriže svoje ovce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Iz sebe je odložila svoje vdovske obleke, se pokrila z zagrinjalom, se ogrnila in sedla na odprt kraj, ki je na poti v Timno, kajti videla je, da je Šelá odrastel, pa mu ni bila dana za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Ko jo je Juda zagledal, je mislil, da je pocestnica, ker je imela svoj obraz zakrit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Na poti se je obrnil k njej in rekel: »Daj, prosim te, naj pridem noter vate,« (kajti ni vedel, da je bila njegova snaha.) Ona pa je rekla: »Kaj mi hočeš dati, da lahko prideš vame?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Rekel je: »Poslal ti bom kozlička od tropa.« Rekla je: »Ali mi boš dal jamstvo, dokler ga ne pošlješ?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Rekel je: »Kakšno jamstvo naj ti dam?« Rekla je: »Svoj pečat in svoje okrasne vrvice in svojo palico, ki je v tvoji roki.« To ji je dal in prišel noter vanjo in ta je spočela z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Vstala je ter odšla proč in poleg sebe položila svoje zagrinjalo iz sebe in si nadela obleke svojega vdovstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda je poslal kozlička po roki svojega prijatelja Adulámca, da prejme svoje jamstvo iz roke ženske, toda ta je ni našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Potem je vprašal ljudi tega kraja, rekoč: »Kje je pocestnica, ki je bila javno poleg poti?« Rekli so: »Na tem kraju ni bilo nobene pocestnice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Vrnil se je k Judu in rekel: »Ne morem je najti in tudi ljudje tega kraja so rekli, da na tem kraju ni bilo nobene pocestnice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda je rekel: »Naj si ona to vzame k sebi, da ne bova osramočena. Glej, poslal sem tega kozlička, ti pa je nisi našel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Pripetilo se je približno tri mesece kasneje, da je bilo Judu povedano, rekoč: »Tvoja snaha Tamara je igrala pocestnico in prav tako poglej, ona je z otrokom od vlačugarstva.« Juda je rekel: »Privedite jo naprej in naj bo sežgana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Ko je bila privedena naprej, je poslala k svojemu tastu, rekoč: »Po moškem, čigar [last] je to, sem z otrokom.« Rekla je: »Razpoznaj, prosim te, čigav je ta pečat, okrasne vrvice in palica.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda jim je priznal in rekel: »Bolj pravična je bila kakor jaz, zato ker je nisem dal svojemu sinu Šeláju.« In ni je več ponovno spoznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Pripetilo pa se je v času njenih porodnih muk, glej, da sta bila v njeni maternici dvojčka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Ko je bila v porodnih mukah se je pripetilo, da je eden iztegnil svojo roko in babica je prijela ter na njegovo roko privezala škrlatno nit, rekoč: »Ta je prvi prišel ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, '§ Pripetilo pa se je, ko je svojo roko potegnil nazaj, glej, je prišel ven njegov brat. Rekla je: »Kako si izbruhnil? Ta prodor bodi na tebi.« Zato je bilo njegovo ime imenovano Parec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Nato je prišel ven njegov brat, ki je imel na svoji roki škrlatno nit in njegovo ime je bilo imenovano Zerah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Jožef je bil priveden dol v Egipt, in faraonov častnik Potifár, poveljnik straže, Egipčan, ga je kupil iz roke Izmaelcev, ki so ga privedli tja dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Gospod pa je bil z Jožefom in bil je uspešen človek in bil je v hiši svojega gospodarja Egipčana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Njegov gospodar je videl, da je bil z njim Gospod in da je Gospod naredil, da je v njegovi roki vse uspevalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Jožef je našel naklonjenost v njegovih očeh in mu služil. Postavil ga je za nadzornika nad svojo hišo in vse, kar je imel, je položil v njegovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Pripetilo se je čez čas, ko ga je postavil za nadzornika v svoji hiši in nad vsem, kar je imel, da je Gospod zaradi Jožefa blagoslovil Egipčanovo hišo in Gospodov blagoslov je bil nad vsem, kar je imel v hiši in na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Vse, kar je imel, je pustil v Jožefovi roki in ni vedel, kar bi moral, razen kruha, ki ga je jedel. Jožef pa je bil čedne zunanjosti in lepega videza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Pripetilo se je po teh stvareh, da je gospodarjeva žena vrgla svoje oči na Jožefa in rekla: »Lezi z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Toda odklonil je in ženi svojega gospodarja rekel: »Glej, moj gospodar ne ve kaj je z menoj v hiši in vse, kar ima, je zaupal v mojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Nikogar večjega v tej hiši ni kakor jaz niti ni nobene stvari zadržal pred menoj, razen tebe, ker si njegova žena; kako lahko jaz potem storim to veliko zlobnost in grešim zoper Boga?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Pripetilo se je, ko je dan za dnem govorila Jožefu, da ji ni prisluhnil, da leži z njo ali da bi bil z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Pripetilo se je okoli tega časa, da je Jožef odšel v hišo, da opravi svoje opravilo in tam v hiši ni bilo nikogar od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Ona pa ga je ujela za njegovo obleko, rekoč: »Lezi z menoj« in pustil je svojo obleko v njeni roki, pobegnil in izginil ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Pripetilo se je, ko je videla, da je v njeni roki pustil svojo obleko in je pobegnil naprej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'da je zaklicala k možem svoje hiše in jim govorila, rekoč: »Vidite, k nam je privedel Hebrejca, da nas zasmehuje. Prišel je k meni, da leži z menoj, jaz pa sem zaklicala z močnim glasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Pripetilo se je, ko je zaslišal, da sem povzdignila svoj glas in zakričala, da je svojo obleko pustil pri meni, pobegnil in izginil ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Njegovo obleko je položila poleg sebe, dokler njen gospodar ni prišel domov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Govorila mu je glede na te besede, rekoč: »Hebrejski služabnik, ki si ga privedel k nam, je prišel noter k meni in me zasmehoval');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'in pripetilo se je, ko sem povzdignila svoj glas in zakričala, da je svojo obleko pustil pri meni in pobegnil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Pripetilo se je, ko je njegov gospodar slišal besede svoje žene, ki mu jih je govorila, rekoč: »Na ta način mi je storil tvoj služabnik,« da je bil vžgan njegov bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Jožefov gospodar ga je vzel in ga vtaknil v ječo, kraj, kjer so bili zvezani kraljevi jetniki in bil je tam v ječi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Toda Gospod je bil z Jožefom in mu izkazal usmiljenje in mu dal naklonjenost v očeh čuvaja ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Čuvaj ječe je v Jožefovo roko zaupal vse jetnike, ki so bili v ječi in karkoli so tam storili, je bil on izvršitelj tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Čuvaj ječe ni gledal na nobeno stvar, ki je bila pod njegovo roko, ker je bil z njim Gospod in tisto, kar je naredil, je Gospod storil, da je to uspevalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Pripetilo se je po teh stvareh, da sta točaj egiptovskega kralja in njegov pek užalila njunega gospoda, egiptovskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Faraon je bil ogorčen zoper dva izmed svojih častnikov, zoper šefa točajev in zoper šefa pekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Zaprl ju je v hišo poveljnika straže, v ječo, kraj, kjer je bil zvezan Jožef.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, '§ Poveljnik straže je Jožefa zadolžil z njima in ta jima je stregel in [neko] razdobje sta ostala v ječi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Sanjala sta oba izmed njiju, vsak človek svoje sanje v isti noči, vsak človek glede na razlago svojih sanj, točaj in pek egiptovskega kralja, ki sta bila zvezana v ječi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Jožef je zjutraj prišel k njima, pogledal nanju in glej, bila sta žalostna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Vprašal je faraonova častnika, ki sta bila z njim v ječi hiše njegovega gospodarja, rekoč: »Zakaj sta danes videti tako žalostna?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Odgovorila sta mu: »Sanjala sva sanje, pa ni nobenega razlagalca le-teh.« Jožef jima je rekel: » Ali razlage ne pripadajo Bogu? Povejta mi jih, prosim vaju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Glavni točaj je svoje sanje povedal Jožefu in mu rekel: »V mojih sanjah, glej, je bil pred menoj vinski trs,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'in na vinskem trsu so bile tri mladike in te so bile kakor bi vzbrstele in bi njihovo cvetje poganjalo in bi njihovi šopi obrodili zrelo grozdje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'V moji roki je bila faraonova čaša in vzel sem grozdje ter ga stisnil v faraonovo čašo in čašo podal v faraonovo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Jožef mu je rekel: »To je razlaga: ›Tri mladike so trije dnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Že v treh dneh bo faraon povzdignil tvojo glavo in te ponovno postavil na tvoje mesto in faraonovo čašo boš po prejšnji navadi, ko si bil njegov točaj, izročal v njegovo roko.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Toda pomisli name, ko bo dobro s teboj in mi izkaži prijaznost, prosim te in me omeni faraonu in me privedi iz te hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'kajti zares sem bil ukraden proč iz hebrejske dežele in tudi tukaj nisem storil ničesar, da bi me vtaknili v grajsko ječo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Ko je glavni pek videl, da je bila razlaga dobra, je Jožefu rekel: »Tudi jaz sem bil v svojih sanjah in glej, na svoji glavi sem imel tri bele košare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'V najvišji košari je bilo vse vrste pekovskih izdelkov za faraona in ptice so jih jedle iz košare na moji glavi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Jožef je odgovoril in rekel: »To je njihova razlaga: ›Tri košare so trije dnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Že v treh dneh bo faraon vzdignil tvojo glavo iz tebe in te obesil na drevo in ptice bodo iz tebe jedle tvoje meso.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Pripetilo se je tretji dan, ki je bil faraonov rojstni dan, da je priredil gostijo vsem svojim služabnikom in med svojimi služabniki povzdignil glavo glavnega točaja in glavnega peka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Glavnega točaja je ponovno vrnil v njegovo točajstvo in čašo je podajal v faraonovo roko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'toda glavnega peka je obesil, kakor jima je Jožef razložil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Vendar se glavni točaj ni spomnil Jožefa, temveč je nanj pozabil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Pripetilo se je ob koncu dveh polnih let, da je faraon sanjal in glej, stal je poleg reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Glej, iz vode je prišlo sedem krav, lepega videza in debelega mesa in hranile so se na travniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Glej, za njimi je iz reke prišlo sedem drugih krav, bolnega videza in suhega mesa in so obstale poleg drugih krav na bregu reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Krave bolnega videza in suhega mesa so pojedle sedem krav lepega in obilnega videza. Tako se je faraon prebudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Zaspal je in drugič sanjal in glej, sedem žitnih klasov je vzklilo na enem steblu, bujnih in dobrih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Glej, za njimi je zraslo sedem tankih klasov in ožganih z vzhodnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Sedem tankih klasov je požrlo sedem bujnih in polnih klasov. Faraon se je prebudil in glej, bile so sanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Pripetilo se je zjutraj, da je bil njegov duh vznemirjen in poslal je ter dal poklicati vse tamkajšnje egiptovske čarovnike in vse modre može in faraon jim je povedal svoje sanje, toda nikogar ni bilo, ki bi jih faraonu lahko razložil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Potem je faraonu spregovoril glavni točaj, rekoč: »Ta dan se spominjam svojih krivd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraon je bil ogorčen nad svojima služabnikoma in me zaprl pod stražo v hišo poveljnika straže, oba, mene in glavnega peka');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'in sanjala sva sanje v eni noči, jaz in on. Sanjala sva vsak glede na razlago svojih sanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Tam je bil z nama mladenič, Hebrejec, služabnik poveljnika straže in povedala sva mu in razložil nama je najine sanje. Razložil je vsakemu človeku glede na njegove sanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Pripetilo se je, kakor nama jih je razložil, tako je bilo. Mene je ponovno vrnil v mojo službo, njega pa je obesil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Tedaj je faraon poslal in poklical Jožefa in naglo so ga privedli iz grajske ječe in obril se je ter zamenjal svoja oblačila in prišel k faraonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Faraon je rekel Jožefu: »Sanjal sem sanje in nikogar ni, ki bi jih lahko razložil. O tebi pa sem slišal govoriti, da lahko razumeš sanje, da jih razložiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Jožef je faraonu odgovoril, rekoč: » To ni v meni. Bog bo dal faraonu odgovor miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Faraon je Jožefu rekel: »V svojih sanjah, glej, sem stal na bregu reke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'in glej, iz reke je prišlo sedem krav, debelega mesa in lepega videza in hranile so se na travniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'In glej, sedem drugih krav je prišlo gor za njimi, mršavih in bolnega videza in suhega mesa, kakršnih po slabosti nisem še nikoli videl v vsej egiptovski deželi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'in krave suhega in bolnega videza so pojedle prvih sedem obilnih krav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Ko so jih pojedle, se ni moglo vedeti, da so jih pojedle, temveč so bile še vedno bolnega videza, kakor poprej. Tako sem se prebudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'In v svojih sanjah sem videl, in glej, sedem klasov je vzbrstelo na enem steblu, polnih in dobrih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'in glej, sedem klasov, izsušenih, tankih in ožganih z vzhodnikom, je pognalo za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Tanki klasi so požrli sedem dobrih klasov in to sem povedal čarovnikom, toda nikogar ni bilo, ki bi mi jih lahko razodel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Jožef je rekel faraonu: »Faraonove sanje so ene. Bog je faraonu pokazal, kaj namerava storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Sedem dobrih krav je sedem let in sedem dobrih klasov je sedem let. Sanje so ene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'In sedem krav suhega in bolnega videza, ki bodo prišle za njimi, je sedem let in sedem praznih klasov, ožganih z vzhodnikom, bo sedem let lakote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'To je stvar, ki sem jo povedal faraonu: ›Kar Bog namerava storiti, je pokazal faraonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Glej, pride sedem let velikega obilja po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Za temi pa se bo dvignilo sedem let lakote in vse obilje v egiptovski deželi bo pozabljeno in lakota bo použila deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Obilje v deželi se ne bo poznalo zaradi razloga lakote, ki bo sledila, kajti ta bo zelo boleča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Zaradi tega so se sanje faraonu ponovile dvakrat. To je, ker je stvar osnovana od Boga in jo bo Bog kmalu izpolnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Zdaj naj torej faraon poišče razumnega in modrega moža ter ga postavi nad egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Naj faraon to stori in naj določi častnike nad deželo in naj v sedmih obilnih letih poberejo petino v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Naj zberejo vso hrano tistih dobrih let, ki pridejo in žito prihranijo pod faraonovo roko in naj hrano čuvajo v mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Ta hrana bo deželi za zalogo zoper sedem let lakote, ki bo v egiptovski deželi, da dežela zaradi lakote ne bo propadla.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Stvar je bila dobra v faraonovih očeh in v očeh vseh njegovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Faraon je rekel svojim služabnikom: »Ali lahko najdemo takšnega kakor je ta, moža, v katerem je Božji Duh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Faraon je rekel Jožefu: »Ker ti je Bog pokazal vse to, ne obstaja nihče tako razumen in moder, kakor si ti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ti boš nad mojo hišo in glede na tvojo besedo bo vladano vsemu mojemu ljudstvu, samo v prestolu bom večji kakor ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Faraon je rekel Jožefu: »Glej, postavil sem te nad vso egiptovsko deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Faraon je iz svoje roke snel svoj prstan, ga dal na Jožefovo roko, ga oblekel v suknje iz tankega lanenega platna in okoli njegovega vratu obesil zlato verižico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'in pripravil ga je, da se pelje v drugem bojnem vozu, ki ga je imel in pred njim so klicali: »Upognite koleno.« In postavil ga je za vladarja nad vso egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Faraon je Jožefu rekel: »Jaz sem faraon in brez tebe noben človek ne bo dvignil svoje roke ali stopala po vsej egiptovski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Faraon je Jožefovo ime imenoval Cafenát Panéah in mu dal za ženo Asenáto, hčer Potifêra, duhovnika iz Ona. In Jožef je odšel nad vso egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Jožef je bil star trideset let, ko je stal pred faraonom, egiptovskim kraljem. In Jožef je odšel izpred faraonove prisotnosti in šel skozi vso egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'V sedmih obilnih letih je zemlja obrodila v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Zbral je vso hrano sedmih let, ki je bila v egiptovski deželi in hrano shranil v mestih, hrano polja, ki je bila naokoli vsakega mesta, je shranil v istem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Jožef je zbral žita kakor morskega peska, zelo veliko, dokler ni prenehal šteti, kajti tega je bilo brez števila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Preden je prišla lakota, sta bila Jožefu rojena dva sinova, ki mu ju je rodila Asenáta, hči Potifêra, duhovnika iz Ona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Jožef je ime prvorojenega imenoval Manáse, »Kajti Bog,« je rekel, »me je pripravil pozabiti vse moje garanje in vso hišo mojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Ime drugega je imenoval Efrájim: »Kajti Bog mi je storil, da bom rodoviten v deželi svoje stiske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Sedem let obilja, ki je bilo v egiptovski deželi, je bilo končanih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Začelo je prihajati sedem let pomanjkanja, glede na to, kakor je rekel Jožef in pomanjkanje je bilo po vseh deželah, toda v egiptovski deželi je bil kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Ko je bila vsa egiptovska dežela izstradana, je ljudstvo vpilo k faraonu za kruh, faraon pa je vsem Egipčanom rekel: »Pojdite k Jožefu; kar vam reče, storite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Lakota je bila nad vsem obličjem zemlje in Jožef je odprl vsa skladišča in prodajal Egipčanom in lakota je v egiptovski deželi hudo naraščala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Vse dežele so prišle v Egipt k Jožefu, da kupijo žito, zato ker je bila lakota tako huda v vseh deželah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Torej ko je Jakob videl, da je bilo v Egiptu žito, je Jakob rekel svojim sinovom: »Zakaj gledate drug drugega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Rekel je: »Glejte, slišal sem, da je v Egiptu žito, pojdite tja dol in ga kupite za nas od tod, da bomo lahko živeli in ne umrli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Jožefovih deset bratov je odšlo dol, da bi v Egiptu nakupili žita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Toda Jožefovega brata Benjamina Jakob ni poslal s svojimi brati, kajti rekel je: »Da ga ne bi morda doletela nesreča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Med temi, ki so prihajali, so prišli Izraelovi sinovi kupovat žito, kajti lakota je bila v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Jožef pa je bil guverner nad deželo in on je bil tisti, ki je prodajal vsemu ljudstvu dežele. In prišli so Jožefovi bratje in se priklonili pred njim s svojimi obrazi k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Jožef je zagledal svoje brate in jih prepoznal, toda naredil se jim je tujca in jim surovo govoril in jim rekel: »Od kod prihajate?« Rekli so: »Iz kánaanske dežele, da kupimo hrano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Jožef je svoje brate prepoznal, oni pa ga niso prepoznali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Jožef se je spomnil sanj, ki jih je sanjal o njih in jim rekel: »Ogleduhi ste. Prišli ste, da vidite nezavarovanost dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Rekli so mu: »Ne, moj gospod, temveč so tvoji služabniki prišli kupit hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Vsi smo sinovi enega moža. Mi smo zvesti možje, tvoji služabniki niso ogleduhi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Rekel jim je: »Ne, temveč ste prišli, da vidite nezavarovanost dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Rekli so: »Tvojih služabnikov je dvanajst bratov, sinovi enega moža v kánaanski deželi in glej, najmlajši je ta dan z našim očetom in enega ni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Jožef pa jim je rekel: »To je to, kar sem vam govoril,« rekoč: »Ogleduhi ste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'S tem boste preizkušeni. Pri faraonovem življenju ne boste šli od tod, razen če ne pride sèm vaš najmlajši brat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Pošljite enega izmed vas in naj gre po vašega brata, vi pa boste zadržani v ječi, da se bodo vaše besede lahko dokazale, če je v vas kaj resnice, ali pa ste, pri faraonovem življenju, zagotovo ogleduhi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Vse skupaj jih je za tri dni zaprl v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Jožef jim je tretji dan rekel: »Storite to in živite, kajti bojim se Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Če ste pravi možje, naj bo eden izmed vas zvezan v hiši vaše ječe, vi pa pojdite, nesite žito za lakoto svojih hiš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'toda svojega najmlajšega brata privedite k meni. Tako bodo vaše besede preverjene in ne boste umrli.« In storili so tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Rekli so drug drugemu: »Mi smo resnično krivi glede svojega brata v tem, [da] smo videli tesnobo njegove duše, ko nas je rotil, pa mu nismo prisluhnili. Zato je nad nas prišla ta tegoba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben jim je odgovoril, rekoč: »Mar vam nisem govoril, rekoč: ›Ne grešite zoper otroka,‹ pa me niste hoteli poslušati? Zato, glejte, tudi njegova kri je zahtevana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Niso pa vedeli, da jih je Jožef razumel, kajti govoril jim je po tolmaču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Obrnil se je okoli, proč od njih in zajokal. In ponovno se je vrnil k njim, se posvetoval z njimi in od njih vzel Simeona ter ga zvezal pred njihovimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Potem je Jožef zapovedal, da naj njihove vreče napolnijo z žitom in denar vsakega povrnejo v njegovo vrečo in jim dajo preskrbo z živežem za na pot. In tako so jim storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Svoje osle so natovorili z žitom in odpotovali od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Ko pa je eden izmed njih odprl svojo vrečo, da da svojemu oslu krmo v gostišču, je odkril svoj denar, kajti, glej, ta je bil v ustju njegove vreče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Svojim bratom je rekel: »Moj denar je povrnjen in glejte, ta je celo v moji vreči.« Njihovo srce jim je omagalo in bili so prestrašeni, rekoč drug drugemu: »Kaj je to, kar nam je storil Bog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Prišli so k svojemu očetu Jakobu v kánaansko deželo in mu povedali vse, kar se jim je pripetilo, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '»>Mož, ki je gospodar dežele, nam je surovo govoril in nas prijel za ogleduhe dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Mi pa smo mu rekli: ›Mi smo pravični možje, mi nismo ogleduhi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Nas je dvanajst bratov, sinov našega očeta. Enega ni, najmlajši pa je ta dan z našim očetom v kánaanski deželi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Mož, gospodar dežele, pa nam je rekel: »S tem bom spoznal, da ste pravični možje. Enega izmed svojih bratov pustite tukaj z menoj in vzemite hrano za lakoto svojih družin in odidite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Svojega najmlajšega brata pa privedite k meni. Potem bom vedel, da niste ogleduhi, temveč, da ste pravični možje. Tako vam bom osvobodil vašega brata, vi pa boste preprodajali v deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Pripetilo se je, ko so izpraznili svoje vreče, glej, da je bil sveženj denarja vsakega človeka v njegovi vreči. Ko so tako oni, kakor njihov oče, zagledali svežnje denarja, so bili prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Njihov oče Jakob jim je rekel: »Oropali ste me mojih otrok. Jožefa ni in Simeona ni in proč hočete odvesti [še] Benjamina. Vse te stvari so zoper mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben je spregovoril svojemu očetu: »Moja dva sinova ubij, če ga ne privedem k tebi. Izroči ga v mojo roko, jaz pa ga bom ponovno privedel k tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, '§ Rekel je: »Moj sin ne bo šel dol s teboj, kajti njegov brat je mrtev, on pa je ostal sam. Če ga po poti, na katero greste, zadene nesreča, potem boste moje sive lase z bridkostjo privedli do groba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Lakota v deželi pa je bila huda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Pripetilo se je, ko so pojedli žito, ki so ga prinesli iz Egipta, da jim je njihov oče rekel: »Ponovno pojdite, kupite nam malo hrane.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juda mu je spregovoril, rekoč: »Človek nam je slovesno izpričal, rekoč: ›Ne boste videli mojega obraza, razen če bo z vami vaš brat.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Če hočeš z nami poslati našega brata, bomo šli dol in ti kupili hrano,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'toda če ga nočeš poslati, ne bomo šli dol, kajti človek nam je rekel: ›Ne boste videli mojega obraza, razen če bo z vami vaš brat.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Izrael je rekel: »Zakaj postopate z menoj tako slabo, da ste možu povedali, da imate še brata?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Rekli so: »Mož nas je strogo povprašal o našem stanju in o našem sorodstvu, rekoč: › Ali vaš oče še živi? Imate še enega brata?‹ In povedali smo mu glede na pomen teh besed. Mar bi lahko zagotovo vedeli, da bo rekel: ›Svojega brata pripeljite dol?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Juda pa je svojemu očetu Izraelu rekel: »Pošlji dečka z menoj in bomo vstali ter šli, da bomo lahko živeli in ne umrli, tako mi, kakor ti in tudi naši malčki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Jaz bom poroštvo zanj. Iz moje roke ga boš zahteval. Če ti ga ne privedem in postavim predte, potem naj krivdo nosim na veke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'kajti razen, če se ne bi obotavljali, bi se zagotovo sedaj drugič vrnili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, '§ Njihov oče Izrael jim je rekel: »Če mora biti to sedaj tako, storite tole. Vzemite od najboljših sadov dežele v svoje posode in odnesite dol človeku darilo, malo balzama, malo meda, dišave, miro, oreščke in mandlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'V svoje roke vzemite dvojen denar. Denar, ki je bil priveden nazaj v ustjih vaših vreč, ga ponovno odnesite v svoji roki; morda je bila to pomota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Vzemite tudi svojega brata in vstanite, ponovno pojdite k človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Bog Vsemogočni pa naj vam da usmiljenje pred človekom, da lahko odpošlje proč vašega drugega brata in Benjamina. Če bom oropan svojih otrok, sem oropan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Možje so vzeli to darilo in v svojo roko vzeli dvojen denar in Benjamina. Vstali so in odšli dol k Egiptu in obstali pred Jožefom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Ko je Jožef z njimi zagledal Benjamina je gospodarju svoje hiše rekel: »Privedi te može domov in zakolji in pripravi, kajti ti možje bodo opoldan kosili z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Človek je storil kakor je Jožef zaukazal in človek je može privedel v Jožefovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Možje pa so bili prestrašeni, ker so bili privedeni v Jožefovo hišo. Rekli so: »Zaradi denarja, ki je bil prvič vrnjen v naše vreče, smo bili privedeni noter; da lahko zoper nas iščejo priložnost in padejo na nas in vzamejo za sužnje nas in naše osle.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Približali so se oskrbniku Jožefove hiše ter se z njim posvetovali pri hišnih vratih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'in rekli: »Oh gospod, prvič smo zares prišli dol, da kupimo hrano');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'in pripetilo se je, ko smo prišli v gostišče, da smo odprli svoje vreče in glej, denar vsakega človeka je bil v ustju njegove vreče, naš denar v polni teži in mi smo ga ponovno prinesli v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'In še en denar smo prinesli dol v svojih rokah, da kupimo hrano. Ne moremo povedati, kdo je naš denar položil v naše vreče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Rekel je: »Mir vam bodi, ne bojte se. Vaš Bog in Bog vašega očeta vam je v vaše vreče dal zaklad. Jaz sem imel vaš denar.« In k njim je privedel Simeona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Človek je može privedel v Jožefovo hišo in jim dal vode in umili so si svoja stopala in njihovim oslom je dal krmo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'In pripravili so darilo za Jožefa, ki je prišel opoldan, kajti slišali so, da bodo tam jedli kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Ko je Jožef prišel domov, so mu prinesli darilo, ki je bilo v njihovi roki, v hišo in se mu priklonili k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Vprašal jih je o njihovi blaginji in rekel: » Ali je vaš oče zdrav, starec, o katerem ste govorili? Ali še živi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Odgovorili so: »Tvoj služabnik, naš oče, je dobrega zdravja, on je še vedno živ.« In sklonili so svoje glave in se globoko priklonili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Povzdignil je svoje oči in zagledal svojega brata Benjamina, sina svoje matere ter rekel: » Ali je to vaš mlajši brat, o katerem ste mi govorili?« Rekel je: »Bog ti bodi milostljiv, moj sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Jožef se je podvizal, kajti njegova notranjost je hrepenela za njegovim bratom in iskal je kje bi se zjokal in vstopil v svojo sobo in se tam zjokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Umil si je obraz, odšel ven in se zadrževal ter rekel: »Pripravite kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Pripravili so posebej zanj in posebej zanje in posebej za Egipčane, ki so jedli z njim, ker Egipčani ne smejo jesti kruha s Hebrejci, kajti to je Egipčanom ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sedeli so pred njim, prvorojenec glede na njegovo pravico prvorojenstva in najmlajši glede na svojo mladost in možje so se čudili drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Vzel je in jim poslal jedi izpred sebe, toda Benjaminovih jedi je bilo petkrat več kakor od kateregakoli izmed njih. In pili so in bili veseli z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Oskrbniku svoje hiše je zapovedal, rekoč: »Vreče mož napolni s hrano, kolikor lahko nesejo in denar vsakega človeka položi v ustje njegove vreče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Mojo čašo pa, srebrno čašo, položi v ustje vreče najmlajšega in njegov žitni denar.« Ta je storil glede na besedo, ki jo je Jožef spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Takoj, ko je bila zjutraj svetloba, so bili možje odposlani, oni in njihovi osli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Ko so odšli ven iz mesta in še ne daleč proč, je Jožef rekel svojemu oskrbniku: »Vstani, sledi možem in ko jih boš dohitel, jim reci: ›Zakaj ste zlo nagradili za dobro?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Mar ni to tisto iz česar moj gospod pije in s čimer zares vedežuje? S takšnim dejanjem ste storili zlo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Ta jih je dohitel in jim spregovoril te iste besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Rekli so mu: »Zakaj moj gospod govori te besede? Bog ne daj, da bi tvoji služabniki storili glede na to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Glej, denar, ki smo ga našli v ustjih svojih vreč, smo iz kánaanske dežele ponovno prinesli k tebi, kako bi potem ukradli srebro ali zlato iz hiše tvojega gospodarja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Pri komerkoli izmed tvojih služabnikov bi bilo to najdeno, naj umre, mi pa bomo tudi sužnji mojemu gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Rekel je: » Naj bo sedaj tudi to glede na vaše besede. Ta, pri komer bo to najdeno, bo moj služabnik, vi pa boste brez krivde.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Potem so naglo sneli vsak mož svojo vrečo k tlom in vsak mož je svojo vrečo odprl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'On pa je iskal in začel pri najstarejšem in nehal pri najmlajšem in čaša je bila najdena v Benjaminovi vreči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Potem so raztrgali svoja oblačila in vsak človek je otovoril svojega osla in vrnili so se v mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Juda in njegovi bratje so prišli v Jožefovo hišo, kajti še je bil tam in padli so pred njim na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Jožef jim je rekel: »Kakšno dejanje je to, kar ste storili? Ali ne veste, da tak mož, kakor jaz, lahko zagotovo vedežuje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda je rekel: »Kaj bomo rekli mojemu gospodu? Kaj naj govorimo? Ali kako se bomo očistili? Bog je odkril krivičnost svojih služabnikov. Glej, mi smo gospodovi služabniki, tako mi, kakor tudi ta, pri komer se je našla čaša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Rekel je: »Bog ne daj, da bi tako storil. Temveč človek, v čigar roki je najdena čaša, bo moj služabnik. Kar pa se tiče vas, se v miru dvignite k svojemu očetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Potem se mu je približal Juda in rekel: »Oh, moj gospod, naj tvoj služabnik, prosim te, spregovori besedo v ušesa mojega gospoda in naj tvoja jeza ne gori zoper tvojega služabnika, kajti ti si celo kakor faraon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Moj gospod je svoje služabnike vprašal, rekoč: ›Imate očeta ali brata?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'In mi smo mojemu gospodu rekli: ›Imamo očeta, starca in otroka njegove visoke starosti, malčka. Njegov brat je mrtev in on je sam ostal od svoje matere in njegov oče ga ljubi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Ti pa si rekel svojim služabnikom: ›Privedite ga dol k meni, da lahko svoje oči usmerim nanj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Mi pa smo mojemu gospodu rekli: ›Deček ne more zapustiti svojega očeta, kajti če bi zapustil svojega očeta, bi njegov oče umrl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Svojim služabnikom si rekel: ›Razen če pride dol z vami vaš najmlajši brat, ne boste več videli mojega obraza.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Pripetilo se je, ko smo prišli gor k tvojemu služabniku, mojemu očetu, da smo mu povedali besede mojega gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Naš oče je rekel: ›Pojdite ponovno in nam kupite malo hrane.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Mi pa smo rekli: ›Ne moremo iti dol. Če bo z nami naš najmlajši brat, potem bomo šli dol, kajti ne smemo videti moževega obraza, razen če bo z nami naš najmlajši brat.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Tvoj služabnik, moj oče, nam je rekel: ›Vi veste, da mi je žena rodila dva sinova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Eden je odšel od mene in rekel sem: ›Zagotovo je raztrgan na koščke‹ in od takrat ga nisem videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, '§ Če tudi tega vzamete od mene in ga zadene nesreča, boste moje sive lase z bridkostjo privedli do groba.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Zdaj torej, ko pridem k tvojemu služabniku, svojemu očetu in dečka ne bo z nami, glede na to, da je njegovo življenje vezano na življenje dečka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, '§ se bo zgodilo, ko bo videl, da dečka ni z nami, da bo umrl. Tvoji služabniki bodo sive lase tvojega služabnika, našega očeta, z bridkostjo privedli do groba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Kajti tvoj služabnik je postal pôrok za dečka mojemu očetu, rekoč: ›Če ga ne privedem k tebi, potem bom na veke prinašal krivdo svojemu očetu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Zdaj torej, prosim te, naj tvoj služabnik ostane namesto dečka suženj mojemu gospodu, deček pa naj gre gor s svojimi brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Kajti kako bom šel k svojemu očetu, dečka pa ne bo z menoj? Da ne bi morda videl zla, ki bi prišlo na mojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Potem se Jožef ni mogel več zadržati pred vsemi tistimi, ki so stali z njim in zaklical je: »Naredite, da vsakdo gre izpred mene.« Noben človek ni stal z njim, medtem ko se je Jožef dal spoznati svojim bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Na glas je zajokal in Egipčani in faraonova hiša so slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Jožef je svojim bratom rekel: »Jaz sem Jožef. Ali moj oče še živi?« Bratje pa mu niso mogli odgovoriti, kajti ob njegovi prisotnosti so bili zbegani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Jožef je svojim bratom rekel: »Približajte se mi, prosim vas.« Prišli so bliže. Rekel je: »Jaz sem vaš brat Jožef, ki ste ga ste prodali v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Zdaj torej ne bodite užaloščeni niti jezni nase, da ste me prodali sèm, kajti Bog me je poslal pred vami, da ohrani življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Kajti ti dve leti je bila lakota v deželi in še pet let je, v katerih ne bo niti setve niti žetve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Bog pa me je poslal pred vami, da vam na zemlji ohrani potomstvo in da vaša življenja reši z veliko osvoboditvijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Tako sedaj niste bili vi, ki ste me poslali sèm, temveč Bog. Naredil me je očeta faraonu in gospodarja vsej njegovi hiši in vladarja po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Pohitite in pojdite gor po mojega očeta in mu recite: ›Tako govori tvoj sin Jožef: ›Bog me je naredil gospodarja vsemu Egiptu. Pridi dol k meni, ne mudi se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Prebival boš v gošenski deželi in boš blizu mene, ti in tvoji otroci, tvojih otrok otroci in tvoji tropi, tvoje črede in vse, kar imaš');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'in tam te bom hranil. Kajti še pet let lakote je, da ne bi ti in tvoja družina in vse, kar imaš, prišlo v revščino.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Glejte, vaše oči vidijo in oči mojega brata Benjamina, da so to moja usta, ki vam govorijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Vi pa boste mojemu očetu povedali o vsej moji slavi v Egiptu in o vsem tem, kar ste videli in pohiteli boste in mojega očeta privedli sèm dol.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Planil je na vrat svojega brata Benjamina ter zajokal in Benjamin je jokal na njegovem vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Poleg tega je poljubil vse svoje brate in jokal nad njimi in potem so njegovi bratje govorili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, '§ Njegova slava je bila slišana v faraonovi hiši, rekoč: »Prišli so Jožefovi bratje.« In to je dobro ugajalo faraonu in njegovim služabnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Faraon je rekel Jožefu: »Reci svojim bratom: ›To storite. Natovorite svoje živali in pojdite in pridite v kánaansko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Vzemite svojega očeta in svoje družine in pridite k meni in jaz vam bom dal dobrega iz egiptovske dežele, vi pa boste jedli tolščo dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Sedaj ste zapovedani, storite tole. Vzemite si vozov iz egiptovske dežele za svoje malčke in za svoje žene in pripeljite svojega očeta in pridite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Ne ozirajte se na vaše stvari, kajti dobrine vse egiptovske dežele so vaše.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Izraelovi otroci so tako storili in Jožef jim je dal vozove, glede na faraonovo zapoved in dal jim je popotnico za pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Vsem izmed njih je dal, vsakemu moškemu je dal zamenjavo oblačila. Toda Benjaminu je dal tristo koščkov srebra in pet zamenjav oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Svojemu očetu je poslal na ta način: deset natovorjenih oslov z dobrimi stvarmi iz Egipta in deset oslic, natovorjenih z žitom, kruhom in hrano za svojega očeta po poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Tako je svoje brate poslal proč in so odrinili in rekel jim je: »Glejte, da se po poti ne prepirate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Dvignili so se iz Egipta in prišli v kánaansko deželo k svojemu očetu Jakobu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'in mu povedali, rekoč: »Jožef je še živ in je guverner nad vso egiptovsko deželo.« Jakobovo srce pa je slabelo, kajti ni jim verjel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Povedali so mu vse Jožefove besede, ki jim jih je rekel. In ko je videl vozove, ki jih je poslal Jožef, da ga odpeljejo, je oživel duh njihovega očeta Jakoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Izrael je rekel: » To je dovolj, moj sin Jožef je še živ. Šel bom in ga pogledal, preden umrem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Izrael je šel na svojo pot z vsem, kar je imel in prišel v Beeršébo in žrtvoval klavne daritve Bogu svojega očeta Izaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Bog je Izraelu spregovoril v videnjih noči in rekel: »Jakob, Jakob.« Ta je rekel: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Rekel je: »Jaz sem Bog, Bog tvojega očeta. Ne boj se iti dol v Egipt, kajti iz tebe bom tam naredil velik narod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'S teboj bom šel dol v Egipt in zagotovo te bom ponovno privedel gor in Jožef bo svojo roko položil na tvoje oči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Jakob je vstal izpred Beeršébe in Izraelovi sinovi so odvedli svojega očeta Jakoba, svoje malčke in svoje žene v vozove, ki jih je faraon poslal, da ga odpeljejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Vzeli so svojo živino in svoje dobrine, ki so jih pridobili v kánaanski deželi in prišli v Egipt, Jakob in vse njegovo potomstvo z njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'njegovi sinovi in sinovi njegovih sinov z njim, njegove hčere in hčere njegovih sinov in vse svoje potomstvo je s seboj privedel v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'To so imena Izraelovih otrok, ki so prišli v Egipt. Jakob in njegovi sinovi: Ruben, Jakobov prvorojenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Vsi Rubenovi sinovi: Henoh, Palú, Hecrón in Karmí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeonovi sinovi: Jemuél, Jamín, Ohad, Jahín, Cohar in Šaúl, sin kánaanske ženske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Lévijevi sinovi: Geršón, Kehát in Merarí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Judovi sinovi: Er, Onán, Šelá, Parec in Zerah, toda Er in Onán sta umrla v kánaanski deželi. Parecova sinova pa sta bila Hecrón in Hamúl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isahárjevi sinovi: Tolá, Puvá, Job in Šimrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Zábulonovi sinovi: Sered, Elón in Jahleél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, '§ To so Leini sinovi, ki jih je rodila Jakobu v Padan–aramu z njegovo hčerjo Dino. Vseh duš njegovih sinov in njegovih hčera je bilo triintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gadovi sinovi: Cifjón, Hagí, Šuní, Ecbón, Erí, Aród in Arelí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Aserjevi sinovi: Jimná, Jišvá, Jišví, Berijá in njihova sestra Sêraha. In Berijájeva sinova: Heber in Malkiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'To so sinovi Zilpe, ki jo je Labán dal svoji hčeri Lei in te je rodila Jakobu: šestnajst duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Sinova Jakobove žene Rahele: Jožef in Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Jožefu sta bila v egiptovski deželi rojena Manáse in Efrájim, katera mu je rodila Asenáta, hči Potifêra, duhovnika iz Ona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Benjaminovi sinovi so bili Bela, Beher, Ašbél, Gerá, Naamán, Ehí, Roš, Mupím, Hupím in Ard.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'To so Rahelini sinovi, ki so bili rojeni Jakobu. Vseh duš je bilo štirinajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Danovi sinovi: Huším.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Neftálijevi sinovi: Jahceél, Guní, Jecer in Šilém.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'To so sinovi Bilhe, ki jo je Labán dal svoji hčeri Raheli in te je rodila Jakobu. Vseh duš je bilo sedem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Vseh duš, ki so z Jakobom prišle v Egipt, ki so prišle iz njegovih ledij, poleg žen Jakobovih sinov, vseh duš je bilo šestinšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Jožefova sinova, ki sta bila rojena v Egiptu, sta bili dve duši. Vseh duš Jakobove hiše, ki so prišle v Egipt, je bilo sedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Pred njim je poslal k Jožefu Juda, da njegov obraz usmeri v Gošen, in prišli so v gošensko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Jožef je pripravil svoj bojni voz in odšel v Gošen, da sreča svojega očeta Izraela in se mu predstavi in planil je na njegov vrat in na njegovem vratu dolgo časa jokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Izrael je Jožefu rekel: »Sedaj naj umrem, ker sem videl tvoj obraz, ker si še vedno živ.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Jožef je rekel svojim bratom in vsej očetovi hiši: »Odšel bom gor in faraonu pokazal ter mu rekel: ›Moji bratje in hiša mojega očeta, ki so bili v kánaanski deželi, so prišli k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ljudje so pastirji, kajti njihovo ukvarjanje je, da pasejo živino in pripeljali so svoje trope in svoje črede in vse, kar imajo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'In zgodilo se bo, ko vas bo faraon poklical in vam rekel: ›Kaj je vaš poklic?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'da boste rekli: ›Ukvarjanje tvojih služabnikov je okoli živine od naše mladosti celo do sedaj, tako mi in tudi naši očetje.‹ Da boste lahko prebivali v gošenski deželi, kajti vsak pastir je Egipčanom ogabnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Potem je prišel Jožef in povedal faraonu ter rekel: »Moj oče, moji bratje, njihovi tropi, njihove črede in vse, kar imajo, so prišli iz kánaanske dežele. Glej, v gošenski deželi so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Vzel je nekatere izmed svojih bratov, pet mož in jih predstavil faraonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Faraon je njegovim bratom rekel: »Kakšen je vaš poklic?« Faraonu so odgovorili: »Tvoji služabniki so pastirji, tako mi, kakor tudi naši očetje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Poleg tega so faraonu rekli: »Zato smo prišli, da začasno prebivamo v deželi, kajti tvoji služabniki nimajo pašnika za svoje trope, kajti huda lakota je v kánaanski deželi. Sedaj te torej prosimo, naj tvoji služabniki prebivajo v gošenski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Faraon je Jožefu spregovoril, rekoč: »Tvoj oče in tvoji bratje so prišli k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egiptovska dežela je pred teboj. V najboljši deželi pripravi svojemu očetu in bratom, da prebivajo. V gošenski deželi naj prebivajo in če poznaš med njimi katerekoli marljive ljudi, potem jih naredi gospodarje nad mojo živino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Jožef je privedel svojega očeta Jakoba in ga postavil pred faraona in Jakob je blagoslovil faraona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Faraon je Jakobu rekel: »Koliko si star?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob je faraonu rekel: »Dni let mojega popotovanja je sto trideset let. Malo in zli so bili dnevi let mojega življenja in nisem dosegel dni let življenja svojih očetov v dneh njihovega popotovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Jakob je blagoslovil faraona in odšel izpred faraona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Jožef je namestil svojega očeta in svoje brate ter jim dal posest v egiptovski deželi, v najboljšem delu dežele, v Ramesésovi deželi, kakor je faraon zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Jožef je vzdrževal svojega očeta, svoje brate in vso družino svojega očeta s kruhom, glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'In ni bilo kruha v vsej deželi, kajti lakota je bila zelo huda, tako da je egiptovska dežela in vsa kánaanska dežela zaradi lakote slabela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Jožef je zbral ves denar, ki se je našel v egiptovski deželi in v kánaanski deželi, za žito, ki so ga kupovali. In Jožef je denar prinesel v faraonovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Ko pa je v egiptovski deželi in v kánaanski deželi zmanjkalo denarja, so vsi Egipčani prišli k Jožefu in rekli: »Daj nam kruha, kajti zakaj bi umrli v tvoji prisotnosti? Kajti denarja je zmanjkalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Jožef je rekel: »Dajte svojo živino in jaz vam bom dal za vašo živino, če je denarja zmanjkalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Svojo živino so privedli k Jožefu in Jožef jim je dal kruha v zameno za konje in za trope in za živino od čred in za osle in to leto jih je nahranil s kruhom za vso njihovo živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Ko je bilo to leto končano, so prišli k njemu drugo leto in mu rekli: » Tega ne bomo skrivali pred mojim gospodom, da je naš denar porabljen. Moj gospod ima tudi naše črede in živino. Sploh ni veliko ostalo v očeh mojega gospoda, razen naših teles in naših zemljišč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Zakaj bi umrli pred tvojimi očmi, tako mi kakor naša dežela? Kupi nas in našo deželo za kruh, pa bomo mi in naša dežela služabniki faraonu. Daj nam seme, da bomo lahko živeli in ne umrli, da dežela ne bo zapuščena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Jožef je vso egiptovsko deželo kupil za faraona, kajti Egipčani so prodali vsak človek svoje polje, ker je nad njimi prevladala lakota in tako je dežela postala faraonova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Kar se tiče ljudstva, jih je premestil v mesta, od enega konca egiptovskih meja, celo do drugega njegovega konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Samo zemljišč duhovnikov ni pokupil, kajti duhovniki so imeli od faraona njim določen delež in jedli svoj delež, ki jim ga je faraon dajal, zato svojih zemljišč niso prodali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Potem je Jožef rekel ljudstvu: »Glejte, danes sem kupil vas in vašo deželo za faraona. Glejte, tukaj je seme za vas in vi boste posejali deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Z donosom se bo zgodilo, da boste peti del dali faraonu, štirje deli pa bodo vaši lastni, za seme polja in za vašo hrano in za tiste iz vaših družin in za hrano za vaše malčke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Rekli so: »Rešil si naša življenja. Naj najdemo milost v očeh mojega gospoda, mi pa bomo faraonovi služabniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Jožef je to naredil v egiptovski deželi [za] zakon do današnjega dne, da bo imel faraon peti del, razen dežele duhovnikov, ki ni postala faraonova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Izrael je prebival v egiptovski deželi, v pokrajini Gošen in v njej so imeli posesti in rastli ter se silno pomnožili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jakob je v egiptovski deželi živel sedemnajst let. Tako je bila celotna Jakobova starost sto sedeminštirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Približal se je čas, ko je Izrael moral umreti in poklical je svojega sina Jožefa ter mu rekel: »Če sem sedaj našel milost v tvojem pogledu, položi, prosim te, svojo roko pod moje stegno ter z menoj postopaj dobrotljivo in iskreno. Ne pokoplji me, prosim te, v Egiptu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'temveč hočem ležati s svojimi očeti in ti me boš odnesel iz Egipta in me pokopal na njihovem grobišču.« Rekel je: »Storil bom kakor si rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Rekel je: »Prisezi mi.« In prisegel mu je. In Izrael se je priklonil na vzglavju postelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Pripetilo se je po teh stvareh, da je Jožefu nekdo povedal: »Poglej, tvoj oče je bolan,« in ta je s seboj vzel svoja dva sinova, Manáseja in Efrájima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'In nekdo je Jakobu povedal ter rekel: »Glej, tvoj sin Jožef prihaja k tebi.« Izrael se je okrepil in se usedel na postelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Jakob je Jožefu rekel: »Bog Vsemogočni se mi je prikazal pri Luzu, v kánaanski deželi, me blagoslovil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'in mi rekel: ›Glej, jaz te bom naredil rodovitnega in te namnožil in jaz bom iz tebe naredil množico ljudstev in to deželo bom dal tvojemu semenu za teboj za večno posest.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'In sedaj, tvoja dva sinova, Efrájim in Manáse, ki sta ti bila rojena v egiptovski deželi, preden sem prišel k tebi v Egipt, sta moja; kakor Ruben in Simeon, bosta moja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Tvoji potomci pa, ki jih boš zaplodil za njima, bodo tvoji in imenovani bodo po imenu svojih bratov v svoji dediščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, '§ Kar pa se mene tiče, ko sem prišel iz Padana, je v kánaanski deželi poleg mene umrla Rahela, na poti, ko je bilo le še malo poti, da pride v Efráto. Pokopal sem jo tam, na poti v Efráto; ta isti je Betlehem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Izrael je zagledal Jožefova sinova in rekel: »Kdo sta ta [dva]?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Jožef je svojemu očetu rekel: »Onadva sta moja sinova, katera mi ju je Bog dal na tem kraju.« Rekel je: »Privedi ju, prosim te, k meni in jaz ju bom blagoslovil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Torej, Izraelove oči so bile od starosti zatemnjene, tako da ni mogel videti. In privedel ju je bliže k njemu in on ju je poljubil ter ju objel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Izrael je Jožefu rekel: »Nisem si mislil, da bom videl tvoj obraz in, glej, Bog mi je pokazal tudi tvoje seme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Jožef ju je prestavil izmed svojih kolen in se sam, s svojim obrazom, priklonil k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Jožef je prijel oba, Efrájima na svojo desnico proti Izraelovi levici in Manáseja na svojo levico proti Izraelovi desnici in ju privedel k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Izrael je iztegnil svojo desnico in jo položil na Efrájimovo glavo, ki je bil mlajši, svojo levico pa na Manásejevo glavo, premišljeno vodeč svoji roki, kajti Manáse je bil prvorojenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Blagoslovil je Jožefa in rekel: »Bog, pred katerim sta hodila moja očeta, Abraham in Izak, Bog, ki me je hranil vse moje dolgo življenje do današnjega dne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'angel, ki me je odkupil od vsega zla, naj blagoslovi dečka. Naj bo moje ime imenovano na njiju in ime mojih očetov, Abrahama in Izaka. Naj zrasteta v množico na sredi zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Ko je Jožef videl, da je njegov oče svojo desnico položil na Efrájimovo glavo, ga je to razžalilo in prijel je roko svojega očeta, da jo odmakne z Efrájimove glave na Manásejevo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Jožef je svojemu očetu rekel: »Ne tako, moj oče, kajti ta je prvorojenec, svojo desnico položi na njegovo glavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Njegov oče pa je odklonil in rekel: »Vem to, moj sin, vem to, tudi on bo postal ljudstvo in tudi on bo velik, toda njegov mlajši brat bo resnično večji kakor on in njegovo seme bo postalo množica narodov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Blagoslovil ju je ta dan, rekoč: »V tebi bo Izrael blagoslovljen, rekoč: ›Bog [naj] te naredi kakor Efrájima in kakor Manáseja‹« in Efrájima je postavil pred Manáseja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Izrael je rekel Jožefu: »Glej, jaz umrem, toda Bog bo z vami in vas bo ponovno privedel v deželo vaših očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Poleg tega sem ti dal en delež nad tvojimi brati, ki sem ga s svojim mečem in s svojim lokom vzel iz roke Amoréjcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Jakob je svojim sinovom zaklical in rekel: »Zberite se skupaj, da vam bom lahko povedal to, kar vas bo doletelo v poslednjih dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Zberite se skupaj in poslušajte, vi, Jakobovi sinovi in prisluhnite Izraelu, svojemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, ti si moj prvorojenec, moja mogočnost in začetek moje moči, odličnost dostojanstva in odličnost moči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'nestabilen kakor voda, ti se ne boš odlikoval. Ker si odšel k postelji svojega očeta, takrat si jo omadeževal. Dvignil se je k mojemu ležišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon in Lévi sta brata, sredstva krutosti so v njunih prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, '§ Oh moja duša, ne pridi v njuno skrivnost, v njun zbor, moja čast, ne bodi združena, kajti v svoji jezi sta usmrtila človeka in v svoji svojevoljnosti sta spodkopala zid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Prekleta bodi njuna jeza, kajti bila je kruta in njun srd, kajti bil je neizprosen. Razdelil ju bom v Jakobu in razkropil v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, ti si ta, ki ga bodo tvoji bratje hvalili. Tvoja roka bo na vratu tvojih sovražnikov, otroci tvojega očeta se bodo priklanjali pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, '§ Juda je levji mladič. Od plena, moj sin, si se dvignil. Sklonil se je, ležal kakor lev in kakor star lev; kdo ga bo prebudil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, '§ Žezlo ne bo odšlo od Juda niti palica zakona izmed njegovih stopal, dokler ne pride Šilo in k njemu bo zbiranje ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Privezujoč svojega oslička k trti in svojega osličjega žrebeta k izbrani trti, je svoje obleke opral v vinu in svoja oblačila v krvi grozdnih jagod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Njegove oči bodo rdeče od vina in njegovi zobje beli od mleka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zábulon bo prebival pri morskem zavetju in bo za zavetje ladjam in njegova meja bo do Sidóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, '§ Isahár je močan osel, počivajoč med dvema bremenoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Videl je, da je bil počitek dober in da je bila dežela prijetna in sklonil svojo ramo, da prenaša in postal služabnik davku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan bo sodil svoje ljudstvo kakor enega izmed Izraelovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan bo kača ob poti, gad na stezi, ki piči konjska kopita, tako da bo njegov jezdec padel vznak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Pričakoval sem tvojo rešitev duše, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, krdelo ga bo premagalo, toda nazadnje bo on premagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Iz Aserja bo njegov kruh zajeten in oskrboval bo kraljeve slaščice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, '§ Neftáli je spuščena košuta. On daje ljubke besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Jožef je rodovitna veja, rodovitna veja pri vodnjaku, čigar mladike segajo preko zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Lokostrelci so ga boleče užalostili, streljali nanj in ga sovražili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Toda njegov lok je ostal v moči in lakti njegovih rok so bili okrepljeni z rokami mogočnega Jakobovega Boga (od tam je pastir, Izraelov kamen),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'celó z Bogom svojih očetov, ki ti bo pomagal in z Vsemogočnim, ki te bo blagoslovil z blagoslovi z neba od zgoraj, blagoslovi iz globine, ki leži spodaj, blagoslovi prsi in maternice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Blagoslovi tvojega očeta so prevladali nad blagoslovi mojih prednikov do skrajne meje večnih hribov. Ti bodo na Jožefovi glavi in na têmenu tistega, ki je bil ločen od svojih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin bo ropal kakor volk. Zjutraj bo požrl plen, ponoči pa bo razdelil ukradeno blago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Vsi ti so dvanajsteri Izraelovi rodovi in to je to, kar jim je njihov oče govoril in jih blagoslovil; vsakega glede na svoj blagoslov jih je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Zapovedal jim je in jim rekel: »Jaz bom zbran k svojemu ljudstvu. Pokopljite me z mojimi očeti v votlini, ki je na polju Hetejca Efróna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'v votlini, ki je na polju Mahpéli, ki je pred Mamrejem, v kánaanski deželi, ki jo je Abraham kupil s poljem Hetejca Efróna za posest in grobišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tam so pokopali Abrahama in njegovo ženo Saro, tam so pokopali Izaka in njegovo ženo Rebeko, in tam sem pokopal Leo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Nakup polja in votline, ki je na njem, je bil od Hetovih otrok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Ko je Jakob naredil konec zapovedovanju svojim sinovom, je svoja stopala dvignil v posteljo, izročil duha in bil zbran k svojemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Jožef je padel na očetov obraz, jokal na njem in ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Jožef je zapovedal svojim služabnikom zdravnikom, naj balzamirajo njegovega očeta in zdravniki so balzamirali Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Štirideset dni je bilo izpolnjeno zanj, kajti tako so izpolnjeni dnevi tistih, ki so balzamirani in Egipčani so žalovali za njim sedemdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Ko so dnevi njegovega žalovanja minili, je Jožef govoril faraonovi hiši, rekoč: »Če sem torej našel milost v vaših očeh, govorite, prosim vas, na faraonova ušesa, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, '›Moj oče me je zaprisegel, rekoč: ›Glej, jaz umrem. V mojem grobu, ki sem si ga izkopal v kánaanski deželi, tam me boš pokopal.‹ Zato me torej pusti iti gor, prosim te in pokopljem svojega očeta in bom ponovno prišel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Faraon je rekel: »Pojdi gor in pokoplji svojega očeta, kakor te je zaprisegel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Jožef je odšel gor, da pokoplje svojega očeta in z njim so odšli gor vsi faraonovi služabniki, starešine njegove hiše, vse starešine egiptovske dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'vsa Jožefova hiša, njegovi bratje in hiša njegovega očeta. Samo svoje malčke, svoje trope in svoje črede so pustili v gošenski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Z njim so odšli gor tako bojni vozovi kakor konjeniki in to je bila zelo velika skupina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Prišli so k mlatišču Atádu, ki je onstran Jordana in tam so žalovali z velikim in zelo bolečim objokovanjem in za svojega očeta je pripravil sedemdnevno žalovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Ko so prebivalci dežele, Kánaanci, videli žalovanje na Atádovih tleh, so rekli: »To objokovanje je Egipčanom boleče.« Torej je bilo ime le-tega imenovano Abél Micrájim, ki je onkraj Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Njegovi sinovi so mu storili glede na to, kakor jim je zapovedal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'kajti njegovi sinovi so ga odnesli v kánaansko deželo in ga pokopali v votlini polja Mahpéle, ki ga je Abraham kupil s poljem za grobno posest od Hetejca Efróna, pred Mamrejem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Potem ko je pokopal svojega očeta, se je Jožef vrnil v Egipt, on in njegovi bratje in vsi, ki so z njim odšli gor, da pokopljejo njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Ko so Jožefovi bratje videli, da je bil njihov oče mrtev, so rekli: »Jožef nas bo morda sovražil in nam bo zagotovo poplačal vse zlo, ki smo mu ga storili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, '§ K Jožefu so poslali poslanca, rekoč: »Tvoj oče je dal zapoved, preden je umrl, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '›Tako boste rekli Jožefu: ›Odpusti, prosim te sedaj, prekršek svojih bratov in njihov greh, kajti storili so ti zlo in sedaj, prosimo te, odpusti prekršek služabnikom Boga svojega očeta.‹« In Jožef je jokal, ko so mu govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Tudi njegovi bratje so padli dol pred njegovim obličjem in rekli: »Glej, mi smo tvoji služabniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Jožef jim je rekel: »Ne bojte se, kajti ali sem jaz na mestu Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Toda kar se tiče vas, ste zoper mene mislili zlo, toda Bog je to preobrnil v dobro, da izvrši, kakor je to današnji dan, da veliko ljudi reši živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Zdaj se torej ne bojte, hranil bom vas in vaše malčke.« Potolažil jih je in prijazno govoril z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Jožef je prebival v Egiptu, on in hiša njegovega očeta in Jožef je živel sto deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Jožef je videl Efrájimove otroke tretjega rodu. Tudi otroci Mahírja, Manásejevega sina, so bili vzgojeni na Jožefovih kolenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Jožef je rekel svojim bratom: »Jaz umiram, Gospod pa vas bo zagotovo obiskal in vas privedel ven iz te dežele, v deželo, ki jo je prisegel Abrahamu, Izaku in Jakobu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Jožef je Izraelove otroke zaprisegel, rekoč: »Bog vas bo zagotovo obiskal in vi boste moje kosti odnesli od tod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Tako je Jožef umrl, star sto deset let in balzamirali so ga in položen je bil v krsto v Egiptu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Torej to so imena Izraelovih otrok, ki so prišli v Egipt. Z Jakobom je prišel vsak mož in njegova družina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Lévi in Juda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isahár, Zábulon in Benjamin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan in Neftáli, Gad in Aser.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Vseh duš, ki so prišle iz Jakobovih ledij, je bilo sedemdeset duš, kajti Jožef je bil že v Egiptu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Jožef je umrl in vsi njegovi bratje in ves ta rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Izraelovi otroci pa so bili rodovitni in obilno narasli in se namnožili in postali silno mogočni in dežela je bila napolnjena z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Sedaj je tam vstal nov kralj nad Egiptom, ki ni poznal Jožefa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Svojemu ljudstvu je rekel: »Glejte, ljudstva Izraelovih otrok je več in mogočnejši so, kakor smo mi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Pridite, modro ravnajmo z njimi, da se ne bi namnožili in se pripeti, ko izpade kakšna vojna, da se pridružijo tudi našim sovražnikom in se borijo zoper nas in tako jih napodimo iz dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Zato so nadnje postavili preddelavce, da jih stiskajo z njihovimi bremeni. In za faraona so gradili zakladni mesti Pitóm in Ramesés.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Toda bolj so jih stiskali, bolj so se množili in rastli. In bili so užaloščeni zaradi Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Egipčani so s krutostjo Izraelove otroke prisilili, da so služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Njihova življenja so zagrenili s trdim suženjstvom, z malto, z opeko in z vsemi vrstami službe na polju. Vse njihove službe, s katerimi so jih pripravili, da jim služijo, so bile s krutostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Egiptovski kralj je spregovoril hebrejskima babicama, katerih prvi je bilo ime Šifra, ime drugi pa Pua');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, '§ in rekel: »Ko hebrejskim ženam opravljata službo babice in jih vidita na stolčkih; če je sin, potem ga ubijta, toda če je hči, potem naj živi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Toda babici sta se bali Boga in nista delali, kakor jima je egiptovski kralj ukazal, temveč sta fantke rešili žive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Egiptovski kralj je dal poklicati babici in jima rekel: »Zakaj sta storili to stvar in fantke rešili žive?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Babici sta faraonu rekli: »Zato ker Hebrejke niso kakor Egipčanke, kajti one so krepke in rodijo prej ko babice pridejo k njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Zato je Bog z babicama dobro postopal in ljudstvo se je pomnožilo in postalo zelo mogočno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Pripetilo se je, ker sta se babici bali Boga, da jima je naredil hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Faraon je vsemu svojemu ljudstvu zapovedal, rekoč: »Vsakega sina, ki je rojen, boste vrgli v reko, vsaka hči pa naj bo rešena živa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Odšel je mož iz Lévijeve hiše in za ženo vzel Lévijevo hčer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Ženska je spočela in rodila sina in ko je videla, da je bil čeden otrok, ga je skrivala tri mesece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Ko pa ga ni mogla več skrivati, je zanj vzela pletenico iz ločja, jo namazala z blatom in s smolo in vanjo položila otroka in to položila v rogoz poleg rečnega brega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Njegova sestra pa je stala daleč stran, da izve kaj se bo z njim zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'In dol je prišla faraonova hči, da se pri reki umije, njene služabnice pa so hodile vzdolž rečnega brega in ko je med rogozom zagledala pletenico, je poslala svojo služabnico, da odide ponjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Ko jo je ta odprla, je zagledala otroka in glej, dojenček je jokal. Do njega je imela sočutje ter rekla: »To je eden izmed hebrejskih otrok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Potem je njegova sestra rekla faraonovi hčeri: »Ali naj grem in k tebi pokličem dojiljo izmed hebrejskih žensk, da bo lahko otroka dojila zate?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Faraonova hči ji je rekla: »Pojdi.« Deklica je odšla in poklicala otrokovo mater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Faraonova hči ji je rekla: »Odnesi tega otroka proč in ga dôji zame, jaz pa ti bom dajala tvoja plačila.« In ženska je vzela otroka ter ga dojila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Otrok je zrastel in privedla ga je k faraonovi hčeri in ta je postal njen sin. Njegovo ime je imenovala Mojzes. Rekla je: »Ker sem ga potegnila iz vode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Pripetilo se je v tistih dneh, ko je Mojzes odrasel, da je odšel k svojim bratom, gledal na njihova bremena in oprezal za Egipčanom, ki je udarjal Hebrejca, enega izmed njegovih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Pogledal je to pot in tisto pot in ko je videl, da tam ni bilo nobenega človeka, je Egipčana usmrtil in ga skril v pesek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Ko je drug dan odšel ven, glej, dva moža izmed Hebrejcev sta se skupaj prepirala in temu, ki je storil napačno, je rekel: »Čemu udarjaš svojega rojaka?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ta pa je rekel: »Kdo te je naredil princa in sodnika nad nama? Ali me nameravaš ubiti, kakor si ubil Egipčana?« Mojzes se je zbal ter rekel: »Ta stvar se je zagotovo izvedela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Torej, ko je faraon slišal to stvar, je iskal Mojzesa, da ga ubije. Mojzes pa je pobegnil izpred faraonovega obličja in prebival v midjánski deželi in se usedel poleg vodnjaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Torej duhovnik iz Midjána je imel sedem hčera in prišle so, zajele vodo in napolnile korita, da bi napojile trop svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Prišli pa so pastirji ter jih odgnali proč, toda Mojzes je vstal, jim pomagal in napojil njihov trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Ko so prišle k svojemu očetu Reguélu, je rekel: »Kako je to, da ste danes prišle tako zgodaj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Rekle so: »Egipčan nas je osvobodil iz roke pastirjev in nam prav tako zajel dovolj vode in napojil trop.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Svojim hčeram je rekel: »In kje je? Zakaj je to, da ste človeka pustile? Pokličite ga, da bo lahko jedel kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mojzes je bil zadovoljen, da prebiva s človekom in ta je Mojzesu dal svojo hčer Cipóro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Rodila mu je sina in njegovo ime je imenoval Geršóm, kajti rekel je: »Tujec sem bil v tuji deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Pripetilo se je tekom časa, da je egiptovski kralj umrl, Izraelovi otroci pa so vzdihovali zaradi razloga suženjstva in vpili in njihovo vpitje je zaradi razloga suženjstva prišlo do Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Bog je slišal njihovo stokanje in Bog se je spomnil svoje zaveze z Abrahamom, Izakom in Jakobom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Bog je pogledal na Izraelove otroke in Bog je imel do njih spoštovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Torej Mojzes je varoval trop svojega tasta Jitra, midjánskega duhovnika in vodil trop k zadnjemu delu puščave in prišel h gori Boga, k Horebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Gospodov angel se mu je prikazal v ognjenem plamenu iz srede grma in pogledal je in glej, grm je gorel z ognjem, pa grm ni bil použit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Mojzes je rekel: »Sedaj se bom obrnil vstran in pogledal ta velik prizor, zakaj grm ne zgori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Ko je Gospod videl, da se je obrnil vstran, da bi videl, je Bog iz srede grma zaklical k njemu ter rekel: »Mojzes, Mojzes.« Ta je rekel: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Rekel je: »Ne približaj se, svoje čevlje sezuj s svojih stopal, kajti prostor, na katerem stojiš, je sveta zemlja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Poleg tega je rekel: »Jaz sem Bog tvojega očeta, Bog Abrahama, Bog Izaka in Bog Jakoba.« In Mojzes je skril svoj obraz, kajti bal se je, da bi pogledal na Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Gospod je rekel: »Zagotovo sem videl stisko svojega ljudstva, ki je v Egiptu in slišal njihovo vpitje zaradi njihovih preddelavcev, kajti poznam njihove bridkosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'in prišel sem dol, da jih osvobodim iz roke Egipčanov in jih privedem iz te dežele gor v dobro in veliko deželo, deželo, kjer tečeta mleko in med, v deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Zdaj torej, glej, k meni je prišlo vpitje Izraelovih otrok in videl sem tudi zatiranje, s kakršnim so jih Egipčani zatirali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Pridi torej zdaj in jaz te bom poslal k faraonu, da lahko privedeš moje ljudstvo, Izraelove otroke, iz Egipta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mojzes pa je Bogu rekel: »Kdo sem jaz, da bi šel k faraonu in da bi lahko Izraelove otroke privedel iz Egipta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Rekel je: »Zagotovo bom s teboj in to ti bodi simbol, da sem te jaz poslal. Ko boš ljudstvo privedel iz Egipta, boste na tej gori služili Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mojzes je Bogu rekel: »Glej, ko pridem k Izraelovim otrokom in jim bom rekel: ›K vam me je poslal Bog vaših očetov,‹ pa mi bodo rekli: ›Kakšno je njegovo ime?‹ Kaj naj jim rečem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Bog je Mojzesu rekel: »JAZ SEM, KI SEM.« Rekel je: »Tako boš govoril Izraelovim otrokom: ›JAZ SEM me je poslal k vam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Bog je Mojzesu poleg tega povedal: »Tako boš rekel Izraelovim otrokom: ›K vam me je poslal Gospod, Bog vaših očetov, Bog Abrahama, Bog Izaka in Bog Jakoba. To je moje ime na veke in to je moj spomin vsem rodovom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Pojdi in zberi skupaj vse Izraelove starešine ter jim reci: ›Prikazal se mi je Gospod, Bog vaših očetov, Bog Abrahama, Izaka in Jakoba, rekoč: ›Zagotovo sem vas obiskal in videl to, kar vam je storjeno v Egiptu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'In rekel sem: »Jaz vas bom privedel gor iz egiptovske stiske v deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev, v deželo, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Prisluhnili bodo tvojemu glasu in ti boš prišel, ti in Izraelove starešine, k egiptovskemu kralju in mu boste rekli: › Gospod, Bog Hebrejcev, se je srečal z nami in sedaj nas pusti iti, rotimo te, tri dni potovanja v divjino, da bomo lahko žrtvovali Gospodu, našemu Bogu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Prepričan pa sem, da vam egiptovski kralj ne bo pustil oditi, ne, niti z mogočno roko ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Svojo roko bom iztegnil in Egipt udaril z vsemi čudeži, ki jih bom storil v njihovi sredi in nató vas bo pustil oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Temu ljudstvu bom dal naklonjenost v očeh Egipčanov in zgodilo se bo, ko greste, da ne boste odšli prazni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'temveč si bo vsaka ženska izposodila od sosede in od tiste, ki začasno biva v njeni hiši, dragocenosti iz srebra in dragocenosti iz zlata in oblačil, in vi jih boste nadeli na svoje sinove in na svoje hčere in boste oplenili Egipčane.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mojzes je odgovoril in rekel: »Toda, glej, ne bodo mi verjeli niti prisluhnili mojemu glasu, kajti rekli bodo: › Gospod se ti ni prikazal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Gospod mu je rekel: »Kaj je to v tvoji roki?« Rekel je: »Palica.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Rekel je: »Vrzi jo na tla.« Vrgel jo je na tla in ta je postala kača in Mojzes je pobegnil pred njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Gospod je rekel Mojzesu: »Iztegni svojo roko in jo primi za rep.« Iztegnil je svojo roko in jo ujel in v njegovi roki je postala palica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '»Da bodo oni lahko verjeli, da se ti je prikazal Gospod, Bog njihovih očetov, Bog Abrahama, Bog Izaka in Bog Jakoba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Gospod mu je nadalje rekel: »Sedaj daj svojo roko v svoje naročje.« Svojo roko je položil v svoje naročje, ko pa jo je izvlekel, glej, je bila njegova roka gobava kakor sneg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Rekel je: »Svojo roko ponovno daj v svoje naročje.« In ponovno je svojo roko položil v svoje naročje in izvlekel jo je iz svojega naročja in glej, ponovno je bila spremenjena kakor drugo njegovo meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '»Zgodilo se bo, če ti ne bodo verjeli niti prisluhnili glasu prvega znamenja, da bodo verjeli glasu zadnjega znamenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Zgodilo se bo, če ne bodo verjeli tudi tema dvema znamenjema niti prisluhnili tvojemu glasu, da boš iz reke zajel vodo in jo izlil na suho zemljo in voda, ki jo zajameš iz reke, bo na suhih tleh postala kri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mojzes je Gospodu rekel: »Oh moj Gospod, jaz nisem zgovoren, niti poprej niti odkar si spregovoril svojemu služabniku, temveč sem počasen za govorjenje in počasnega jezika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Gospod mu je rekel: »Kdo je naredil človekova usta? Ali kdo naredi nemega ali gluhega ali da vidi ali slepega? Ali ne jaz, Gospod?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Sedaj torej pojdi in jaz bom s tvojimi usti in te učil kaj boš govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Rekel je: »Oh moj Gospod, pošlji, prosim te, po roki tistega, ki ga ti hočeš poslati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Gospodova jeza je bila vžgana zoper Mojzesa in rekel je: » Mar ni Lévijevec Aron tvoj brat? Vem, da lahko dobro govori. In tudi, glej, prihaja, da te sreča in ko te zagleda, bo v svojem srcu vesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ti mu boš govoril in v njegova usta polagal besede in jaz bom s tvojimi usti in z njegovimi usti in vaju učil, kaj bosta storila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'On bo tvoj govornik ljudstvu in on bo, celó on bo tebi namesto ust in ti boš njemu namesto Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'In v svojo roko boš vzel to palico, s katero boš delal znamenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Mojzes je odšel, se vrnil k svojemu tastu Jitru in mu rekel: »Pusti me iti, prosim te in se vrniti k mojim bratom, ki so v Egiptu in videti ali so še živi.« Jitro je Mojzesu rekel: »Pojdi v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Gospod je v Midjánu rekel Mojzesu: »Pojdi, vrni se v Egipt, kajti vsi ljudje, ki so ti stregli po življenju, so mrtvi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Mojzes je vzel svojo ženo in svoja sinova in jih posadil na osla in se vrnil v egiptovsko deželo in Mojzes je v svojo roko vzel Božjo palico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Gospod je rekel Mojzesu: »Ko greš, da se vrneš v Egipt, glej, da boš pred faraonom storil vse te čudeže, ki sem jih položil v tvojo roko, toda jaz bom zakrknil njegovo srce, da ljudstvu ne bo dovolil oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Faraonu boš rekel: ›Tako govori Gospod, Izrael je moj sin, celo moj prvorojenec‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'in jaz ti pravim: ›dovoli mojemu sinu oditi, da mi bo lahko služil. Če pa mu boš odklonil oditi, glej, bom ubil tvojega sina, celó tvojega prvorojenca.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Pripetilo se je po poti v gostišče, da ga je srečal Gospod in si prizadeval, da ga ubije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tedaj je Cipóra vzela oster kamen in odrezala prednjo kožico svojega sina in jo vrgla k njegovim stopalom ter rekla: »Zagotovo si mi krvav soprog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Tako ga je pustil oditi. Potem je rekla: »Krvav soprog si zaradi obreze.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Gospod je rekel Aronu: »Pojdi v divjino, da srečaš Mojzesa.« Ta je odšel in ga srečal na gori Boga ter ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Mojzes je povedal Aronu vse besede Gospoda, ki ga je poslal in vsa znamenja, ki mu jih je zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Mojzes in Aron sta odšla ter zbrala skupaj vse starešine Izraelovih otrok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'in Aron je govoril vse besede, ki jih je Gospod govoril Mojzesu in v očeh ljudstva storil znamenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Ljudje so verovali in ko so slišali, da je Gospod obiskal Izraelove otroke in da je pogledal na njihovo stisko, potem so sklonili svoje glave in oboževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Potem sta Mojzes in Aron vstopila in faraonu rekla: »Tako govori Gospod, Izraelov Bog: ›Pusti moje ljudstvo oditi, da bodo v divjini lahko imeli praznovanje meni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Faraon je rekel: »Kdo je Gospod, da bi ubogal njegov glas, da bi pustil Izraela oditi? Ne poznam Gospoda niti Izraelu ne bom pustil oditi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Rekel je: »Bog Hebrejcev se je srečal z nami. Pusti nas oditi, prosimo te, tri dni potovanja v puščavo in žrtvujemo Gospodu, našemu Bogu, da on ne pade na nas s kužno boleznijo ali z mečem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Egiptovski kralj pa jima je rekel: »Zakaj vidva, Mojzes in Aron, pustita ljudstvo od njihovih del? Odidita k svojim bremenom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, '§ Faraon je rekel: »Glejta, ljudstva dežele je torej mnogo, vidva pa jim delata počitek pred njihovimi bremeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Faraon je istega dne zapovedal preddelavcem ljudstva in njihovim nadzornikom, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '»Ljudstvu ne boste več dajali slame, da delajo opeko, kakor poprej. Naj gredo in sami nabirajo slamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Število opek, ki so jih naredili poprej, boste položili nanje. Ne boste zmanjšali od tega dolga, kajti brezdelni so, zato vpijejo, rekoč: ›Pojdimo in žrtvujmo našemu Bogu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Več dela naj bo položenega na ljudi, da se bodo lahko trudili s tem in naj se ne ozirajo na prazne besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Preddelavci ljudstva so odšli ven in njihovi nadzorniki in ljudstvu spregovorili, rekoč: »Tako govori faraon: ›Ne bom vam dajal slame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Pojdite, dobite slamo kjer jo lahko najdete, vendar dolg vašega dela ne bo zmanjšan.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, '§ Tako je bilo ljudstvo razkropljeno naokoli po vsej egiptovski deželi, da zbira strnišče namesto slame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Preddelavci so jih priganjali, rekoč: »Izpolnjujte svoja dela, svoje dnevne naloge, kakor ko je bila slama.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Nadzorniki Izraelovih otrok, ki so jih faraonovi preddelavci postavili nadnje, so bili pretepeni in zahtevali: »Zakaj niste izpolnili svoje naloge v izdelavi opek, tako včeraj in danes, kakor poprej?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Potem so nadzorniki Izraelovih otrok prišli in vpili k faraonu, rekoč: »Zakaj tako postopaš s svojimi služabniki?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Nobena slama ni dana tvojim služabnikom, oni pa nam pravijo: ›Delajte opeko.‹ Glej, tvoji služabniki so pretepeni, toda krivda je na tvojem lastnem ljudstvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Toda rekel jim je: »Vi ste brezdelni, vi ste brezdelni, zato pravite: ›Pojdimo in naredimo žrtvovanje Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Pojdite torej sedaj in delajte, kajti slama vam ne bo dana, vendar boste izročili število opek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Nadzorniki Izraelovih otrok so videli, da so bili v zlem primeru, potem ko je bilo rečeno: »Ne boste zmanjšali dolga od opek svoje dnevne naloge.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Srečali so Mojzesa in Arona, ki sta stala na poti, ko so prišli od faraona');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'in jima rekli: » Gospod naj pogleda na vaju in sodi, ker sta storila našemu okusu, da je preziran v faraonovih očeh in v očeh njegovih služabnikov, da položi meč v njihovo roko, da nas ubijejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mojzes se je vrnil h Gospodu ter rekel: »Gospod, zakaj si tako zlo ravnal s tem ljudstvom? Zakaj je to, da si me poslal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Kajti odkar sem prišel k faraonu, da govorim v tvojem imenu, je temu ljudstvu storil zlo niti sploh nisi osvobodil svojega ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Potem je Gospod rekel Mojzesu: »Sedaj boš videl kaj bom storil faraonu, kajti z močno roko jih bo pustil oditi in z močno roko jih bo pognal iz svoje dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Bog je Mojzesu spregovoril in mu rekel: »Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Prikazal sem se Abrahamu, Izaku in Jakobu po imenu Bog Vsemogočni, toda po svojem imenu, Jahve, jim nisem bil znan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Z njimi sem utrdil tudi svojo zavezo, da jim dam kánaansko deželo, deželo njihovega popotovanja, v kateri so bili tujci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'In tudi sam sem slišal stokanje Izraelovih otrok, ki jih Egipčani držijo v suženjstvu, in spomnil sem se svoje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Zatorej reci Izraelovim otrokom: ›Jaz sem Gospod in jaz vas bom izpeljal izpod bremen Egipčanov in jaz vas bom odstranil iz njihovega suženjstva in jaz vas bom odkupil z iztegnjenim laktom in z velikimi sodbami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Jaz vas bom vzel k sebi za ljudstvo in jaz vam bom Bog in vi boste vedeli, da jaz sem Gospod, vaš Bog, ki vas osvobaja izpod bremen Egipčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Jaz vas bom privedel v deželo, v zvezi s katero sem prisegel, da jo dam Abrahamu, Izaku in Jakobu, in dal vam jo bom za dediščino. Jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mojzes je tako govoril Izraelovim otrokom. Toda Mojzesu niso prisluhnili zaradi tesnobe duha in zaradi krutega suženjstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '»Vstopi in govori faraonu, egiptovskemu kralju, da naj pusti Izraelove otroke oditi iz njegove dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mojzes je govoril pred Gospodom, rekoč: »Glej, Izraelovi otroci mi niso prisluhnili. Kako bo potem faraon slišal mene, ki sem neobrezanih ustnic?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, '§ Gospod je govoril Mojzesu in Aronu ter jima naložil skrb za Izraelove otroke in faraona, egiptovskega kralja, da Izraelove otroke privedeta iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'To so poglavarji hiš svojih očetov. Sinovi Rubena, Izraelovega prvorojenca: Henoh in Palú, Hecrón in Karmí; to so bile Rubenove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeonovi sinovi: Jemuél, Jamín, Ohad, Jahín, Cohar in Šaúl, sin kánaanske ženske. To so Simeonove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'To so imena Lévijevih sinov glede na njihove rodove: Geršón, Kehát in Merarí. Let Lévijevega življenja je bilo sto sedemintrideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Geršónova sinova: Libni in Šimí, glede na njuni družini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél. Let Kehátovega življenja je bilo sto triintrideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Meraríjeva sinova: Mahlí in Muší. To so družine Lévijevcev glede na svoje rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amrám si je za ženo vzel Johébedo, sestro svojega očeta. Rodila mu je Arona in Mojzesa. Let Amrámovega življenja je bilo sto sedemintrideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jichárjevi sinovi: Korah, Nefeg in Zihrí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Uziélovi sinovi: Mišaél, Elicafán in Sitrí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aron si je vzel za ženo Elišébo, Aminadábovo hčer, Nahšónovo sestro. Rodila mu je Nadába in Abihúja, Eleazarja in Itamárja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korahovi sinovi: Asír, Elkaná in Abiasáf. To so družine Korahovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Aronov sin Eleazar si je za ženo vzel eno izmed Putiélovih hčera. Rodila mu je Pinhása. To so poglavarji očetov Lévijevcev glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To sta tista Mojzes in Aron, ki jima je Gospod rekel: »Izpeljita Izraelove otroke iz egiptovske dežele glede na njihove vojske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'To sta tista, ki sta govorila egiptovskemu kralju faraonu, da izpeljeta Izraelove otroke iz Egipta. To sta tista Mojzes in Aron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'In pripetilo se je na dan, ko je Gospod spregovoril Mojzesu v egiptovski deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da je Gospod spregovoril Mojzesu, rekoč: »Jaz sem Gospod. Govori faraonu, egiptovskemu kralju vse, kar ti povem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mojzes je rekel pred Gospodom: »Glej, jaz sem neobrezanih ustnic in kako mi bo faraon prisluhnil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Gospod je rekel Mojzesu: »Poglej, naredil sem te faraonu za boga. Tvoj brat Aron pa bo tvoj prerok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Govoril boš vse, kar ti ukažem. Tvoj brat Aron pa bo govoril faraonu, da Izraelove otroke pošlje iz svoje dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Zakrknil bom faraonovo srce in pomnožil svoja znamenja in svoje čudeže v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Toda faraon vama ne bo prisluhnil, da bom svojo roko lahko položil nad Egipt in izpeljal svoje vojske in svoje ljudstvo, Izraelove otroke, z velikimi sodbami, iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'In Egipčani bodo spoznali, da jaz sem Gospod, ko iztegnem svojo roko nad Egipt in Izraelove otroke izpeljem izmed njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mojzes in Aron sta storila; kakor jima je Gospod zapovedal, tako sta storila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mojzes je bil star osemdeset let, Aron pa triinosemdeset let, ko sta govorila faraonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '»Ko vama bo faraon rekel, rekoč: ›Pokažita mi čudež za vas,‹ potem boš rekel Aronu: ›Vzemi svojo palico in jo vrzi pred faraona‹ in le-ta bo postala kača.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Mojzes in Aron sta odšla k faraonu in storila, kakor jima je Gospod zapovedal. Aron je svojo palico vrgel pred faraona in pred njegove služabnike in postala je kača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Potem je tudi faraon poklical modre može in čarodeje. Torej egiptovski čarovniki, tudi oni so na podoben način storili s svojimi izrekanji urokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Kajti vsak je vrgel svojo palico in postale so kače, toda Aronova palica je požrla njihove palice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, '§ In zakrknil je faraonovo srce, da jim ni prisluhnil, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Gospod je rekel Mojzesu: »Faraonovo srce je zakrknjeno, odklanja pustiti ljudstvo, da odide.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Zjutraj pojdi k faraonu. Glej, on gre ven k vodi in [ko] pride, boš stal nasproti pri rečnem bregu in palico, ki je bila spremenjena v kačo, boš vzel v svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Rekel mu boš: › Gospod, Bog Hebrejcev, me je poslal k tebi, rekoč: ›Odpusti moje ljudstvo, da mi bodo lahko služili v divjini‹ in glej, doslej nisi hotel poslušati.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Tako govori Gospod: ›V tem boš vedel, da sem jaz Gospod. Glej, s palico, ki je v moji roki, bom udaril na vode, ki so v reki in spremenjene bodo v kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ribe, ki so v reki, bodo poginile in reka bo zaudarjala in Egipčanom se bo gnusilo piti vodo iz reke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Gospod je spregovoril Mojzesu: »Reci Aronu: ›Vzemi svojo palico in iztegni svojo roko nad egiptovske vode, nad njihove vodotoke, nad njihove reke, nad njihove ribnike in nad vse njihove vodne tolmune, da bodo lahko postali kri in da bo lahko kri po vsej egiptovski deželi, tako v posodah iz lesa, kakor v posodah iz kamna.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mojzes in Aron sta storila tako kakor je Gospod zapovedal in ta je dvignil palico in udaril vode, ki so bile v reki, pred faraonovim pogledom in pogledom njegovih služabnikov, in vse vode, ki so bile v reki, so bile spremenjene v kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ribe, ki so bile v reki, so poginile in reka je smrdela in Egipčani niso mogli piti vode iz reke in kri je bila po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Egiptovski čarovniki so tako storili s svojimi izrekanji urokov in faraonovo srce je bilo zakrknjeno niti jima ni prisluhnil, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Faraon se je obrnil in odšel v svojo hišo niti tudi ni k temu usmeril svojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Vsi Egipčani so okoli reke kopáli za vodo, da [bi] pili, kajti vode iz reke niso mogli piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Dopolnjenih je bilo sedem dni, potem ko je Gospod udaril reko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Gospod je spregovoril Mojzesu: »Pojdi k faraonu in mu reci: ›Tako govori Gospod: ›Odpusti moje ljudstvo, da mi bodo lahko služili.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Če pa odkloniš, da jih odpustiš, glej, bom vse tvoje meje udaril z žabami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Reke bodo rodile žab v obilju, ki bodo šle gor in prišle v tvojo hišo, v tvojo spalnico, na tvojo posteljo, v hiše tvojih služabnikov, na tvoje ljudstvo, v tvoje peči in v tvoje nečke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Žabe bodo prišle tako nate, kakor na tvoje ljudstvo in na vse tvoje služabnike.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Gospod je spregovoril Mojzesu: »Reci Aronu: ›Iztegni svojo roko s svojo palico nad vodotoke, nad reke in nad ribnike ter povzroči žabam, da pridejo nad egiptovsko deželo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Aron je iztegnil svojo roko nad egiptovske vode in žabe so prišle gor ter pokrile egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Čarovniki so tako storili s svojimi izrekanji urokov in nad egiptovsko deželo privedli žabe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Potem je faraon dal poklicati Mojzesa in Arona ter rekel: »Rotita Gospoda, da lahko odstrani žabe od mene in od mojega ljudstva; jaz pa bom pustil ljudstvu oditi, da bodo lahko žrtvovali Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mojzes je rekel faraonu: »Slava nad menoj. Kdaj naj rotim zate in za tvoje služabnike in za tvoje ljudstvo, da uniči žabe pred teboj in tvojimi hišami, da bodo lahko preostale samo v reki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Rekel je: »Jutri.« Rekel je: » To bodi glede na tvojo besedo, da lahko spoznaš, da ni nikogar podobnega Gospodu, našemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Žabe bodo odšle od tebe in od tvojih hiš in od tvojih služabnikov in od tvojega ljudstva. Preostale bodo samo še v reki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Mojzes in Aron sta odšla izpred faraona. Mojzes je klical h Gospodu zaradi žab, ki jih je privedel zoper faraona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Gospod je storil glede na Mojzesovo besedo in žabe so poginile po hišah, po vaseh in po poljih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Zbrali so jih skupaj na kupe in dežela se je usmradila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Toda ko je faraon videl, da je bil predah, je zakrknil svoje srce in jima ni prisluhnil, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, '§ Gospod je rekel Mojzesu: »Reci Aronu: ›Iztegni svojo palico in udari prah dežele, da [iz] tega lahko nastanejo uši po vsej egiptovski deželi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, '§ Storila sta tako, kajti Aron je iztegnil svojo roko s svojo palico in udaril prah dežele in [iz] tega so nastale uši na človeku in na živali. [Iz] vsega prahu dežele so nastale uši po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, '§ Čarovniki so tako storili s svojimi izrekanji urokov, da odstranijo uši, toda niso mogli, tako so bile uši na človeku in na živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Potem so čarovniki rekli faraonu: »To je Božji prst.« Faraonovo srce pa je bilo zakrknjeno in jim ni prisluhnil, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Gospod je rekel Mojzesu: »Vstani zgodaj zjutraj in stopi pred faraona. Glej, ta prihaja k vodi in mu reci: ›Tako govori Gospod: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Ali pa, če ne boš hotel pustiti mojemu ljudstvu oditi, glej, bom poslal roje muh nate, na tvoje služabnike, na tvoje ljudstvo in v tvoje hiše. Hiše Egipčanov bodo polne rojev muh in tudi zemlja, na kateri so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Na ta dan bom oddvojil gošensko deželo, v kateri prebiva moje ljudstvo, da tam ne bo rojev muh; z namenom, da lahko spoznaš, da sem jaz Gospod v sredi zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Jaz bom položil ločnico med svojim ljudstvom in tvojim ljudstvom. Jutri bo to znamenje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, '§ In Gospod je storil tako. Prišel je nadležen roj muh v faraonovo hišo, v hiše njegovih služabnikov in v vso egiptovsko deželo. Dežela je bila okužena zaradi roja muh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Faraon je dal poklicati Mojzesa in Arona ter rekel: »Pojdite, žrtvujte vašemu Bogu v deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mojzes pa je rekel: »Ni primerno tako storiti, kajti ogabnost Egipčanom bomo žrtvovali Gospodu, našemu Bogu. Glej, pred njihovimi očmi bomo žrtvovali gnusobo Egipčanov in mar nas ne bodo kamnali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Šli bomo tri dni potovanja v divjino in žrtvovali Gospodu, našemu Bogu, kakor nam bo zapovedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Faraon pa je rekel: »Pustil vam bom oditi, da boste lahko žrtvovali Gospodu, svojemu Bogu, v divjini; samo ne boste odšli zelo daleč proč. Rotite zame.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mojzes je rekel: »Glej, ven grem od tebe in rotil bom Gospoda, da roji muh lahko jutri odidejo od faraona, od njegovih služabnikov in od njegovega ljudstva, toda faraon naj ne postopa več varljivo z nedovoljevanjem ljudstvu, da gre žrtvovat Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Mojzes je odšel izpred faraona in rotil Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Gospod je storil glede na Mojzesovo besedo in roje muh odstranil od faraona, od njegovih služabnikov in od njegovega ljudstva. Niti ena ni preostala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Faraon pa je tudi tokrat zakrknil svoje srce niti ni hotel odpustiti ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Potem je Gospod rekel Mojzesu: »Pojdi noter k faraonu in mu povej: ›Tako govori Gospod, Bog Hebrejcev: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Kajti, če odkloniš, da bi jih pustil oditi in jih hočeš trdno držati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'glej, Gospodova roka je na tvoji živini, ki je na polju, na konjih, na oslih, na kamelah, na volih in na ovcah. Tam bo zelo nadležna živinska kuga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Gospod bo oddvojil med izraelsko živino in egiptovsko živino in nič ne bo poginilo, od vsega, kar je [last] Izraelovih otrok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Gospod je določil čas, rekoč: »Jutri bo Gospod to stvar storil v deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Gospod je naslednji dan storil to stvar in vsa egiptovska živina je poginila, toda izmed živine Izraelovih otrok ni poginila niti ena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Faraon je poslal in glej, niti ena izmed izraelske živine ni poginila. Faraonovo srce pa je bilo zakrknjeno in ljudstvu ni pustil oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Gospod je rekel Mojzesu in Aronu: »K sebi vzemita prgišča pepela iz talilne peči in naj ga Mojzes potrese proti nebu pred faraonovimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Ta bo postal droben prah po vsej egiptovski deželi in tvori bodo izbruhnili z mehurji na ljudeh in na živali po vsej egiptovski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Vzela sta pepel iz talilne peči in stala pred faraonom. Mojzes ga je potresel proti nebu in ta je postal tvor, ki je izbruhnil z mehurji na ljudeh in na živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Čarovniki pa zaradi tvorov niso mogli stati pred Mojzesom, kajti tvor je bil na čarovnikih in na vseh Egipčanih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Gospod pa je zakrknil faraonovo srce in ta jima ni prisluhnil, kakor je Gospod govoril Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Gospod je rekel Mojzesu: »Vstani zgodaj zjutraj in stopi pred faraona ter mu reci: ›Tako govori Gospod, Bog Hebrejcev: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Kajti tokrat bom vse svoje nadloge poslal na tvoje srce in na tvoje služabnike in na tvoje ljudstvo, da boš lahko vedel, da na vsej zemlji ni nikogar podobnega meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Kajti sedaj bom iztegnil svojo roko, da lahko udarim tebe in tvoje ljudstvo s kužno boleznijo, ti pa boš iztrebljen z zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Zagotovo sem te dvignil zaradi tega razloga, da pokažem na tebi svojo moč, in da bo moje ime lahko razglašeno po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Doklej se povišuješ zoper moje ljudstvo, da jim nočeš pustiti oditi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Glej, jutri ob tem času bom povzročil, da bo deževala zelo boleča toča, kakršne ni bilo v Egiptu od njegovega nastanka celo do sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Pošlji torej sedaj in zberi svojo živino in vse, kar imaš na polju, kajti na vsakega človeka in žival, ki bo najdena na polju in ne bo privedena domov, bo nanje priletela toča in bodo umrli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kdor se je med faraonovimi služabniki bal Gospodove besede, je svoje služabnike in svojo živino primoral, da so pobegnili v hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'kdor pa se ni oziral na Gospodovo besedo, je svoje služabnike in svojo živino pustil na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Gospod je rekel Mojzesu: »Iztegni svojo roko proti nebu, da bo lahko toča po vsej egiptovski deželi, na ljudeh, na živali in na vsakem poljskem zelišču po vsej egiptovski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Mojzes je svojo palico iztegnil proti nebu in Gospod je poslal grmenje in točo in spotoma je ogenj padal na zemljo; Gospod je deževal točo na egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Tako je bila tam toča in ogenj, pomešan s točo, zelo boleč, takšen kot ni bilo nobenega podobnega temu po vsej egiptovski deželi, odkar je postala narod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Toča je udarila povsod, po vsej egiptovski deželi vse, kar je bilo na polju, tako človeka kakor žival. Toča je udarila vsako zel na polju in zlomila vsako drevo na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Samo v gošenski deželi, kjer so bili Izraelovi otroci, tam ni bilo toče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Faraon je poslal in dal poklicati Mojzesa in Arona ter jima rekel: »Tokrat sem grešil. Gospod je pravičen, jaz in moje ljudstvo pa smo zlobni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Rotita Gospoda (kajti dovolj je), da ne bo več mogočnih grmenj in toče, in jaz vam bom pustil oditi in ne boste več ostali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mojzes mu je rekel: »Takoj, ko odidem iz mesta, bom razširil svoje roke h Gospodu in grmenje bo prenehalo niti nič več ne bo toče, da lahko spoznaš, da je zemlja Gospodova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Toda kar se tiče tebe in tvojih služabnikov vem, da se še ne boste bali Gospoda Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Udarjena sta bila lan in ječmen, kajti ječmen je bil v klasu, lan pa je bil [v] cvetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Toda pšenica in pira nista bili udarjeni, kajti nista bili zreli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Mojzes je odšel iz mesta od faraona in svoje roke razširil h Gospodu. Grmenja in toča sta prenehali in dež se ni izlival na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Ko pa je faraon videl, da so dež, toča in grmenja prenehali, je še bolj grešil in zakrknil svoje srce, on in njegovi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Faraonovo srce je bilo zakrknjeno niti ni hotel pustiti Izraelovih otrok oditi, kakor je Gospod govoril po Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Gospod je rekel Mojzesu: »Pojdi noter k faraonu, kajti zakrknil sem njegovo srce in srce njegovih služabnikov, da lahko ta svoja znamenja pokažem pred njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'in da ti lahko poveš v ušesa svojih sinov in sinov svojih sinov, kakšne stvari sem storil v Egiptu in moja znamenja, ki sem jih storil med njimi, da boste lahko spoznali, kako [to], da sem jaz Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Mojzes in Aron sta vstopila k faraonu ter mu rekla: »Tako govori Gospod, Bog Hebrejcev: ›Doklej boš odklanjal, da se ponižaš pred menoj? Pusti moje ljudstvo oditi, da mi bodo lahko služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Ali pa, če odkloniš, da pustiš moje ljudstvo oditi, glej, bom jutri v tvojo pokrajino privedel leteče kobilice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Pokrile bodo obličje zemlje, da nekdo ne bo mogel videti zemlje. Pojedle bodo preostanek tega, kar je ušlo, kar vam ostaja od toče in pojedle bodo vsako drevo, ki vam raste zunaj polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Napolnile bodo tvoje hiše in hiše vseh tvojih služabnikov in hiše vseh Egipčanov, kar niti tvoji očetje niti očetje tvojih očetov niso videli od dneva, ko so bili na zemlji, do današnjega dne.‹« In obrnil se je ter odšel ven od faraona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Faraonovi služabniki so mu rekli: »Doklej nam bo ta človek zanka? Pusti ljudi oditi, da bodo lahko služili Gospodu, svojemu Bogu. Mar še ne veš, da je Egipt uničen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Mojzes in Aron sta bila ponovno privedena k faraonu. Rekel jima je: »Pojdite, služite Gospodu, svojemu Bogu, toda kdo so tisti, ki bodo šli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mojzes je rekel: »Šli bomo s svojimi mladimi in s svojimi starimi, s svojimi sinovi in s svojimi hčerami in s svojimi tropi in s svojimi čredami bomo šli, kajti imeti moramo praznik Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Rekel jima je: »Naj bo Gospod tako z vami, kakor bom jaz pustil oditi vam in vašim malčkom. Glejta na to, kajti zlo je pred vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ne tako. Pojdite sedaj vi, ki ste možje in služite Gospodu, kajti to ste si želeli.« In izgnana sta bila izpred faraonove prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Gospod je rekel Mojzesu: »Iztegni svojo roko nad egiptovsko deželo zaradi letečih kobilic, da bodo lahko prišle nad egiptovsko deželo in pojedle vsako zemeljsko zelišče, celó vse, kar je pustila toča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mojzes je iztegnil svojo palico nad egiptovsko deželo in Gospod je ves ta dan prinašal vzhodnik nad deželo in vso to noč, in ko je bilo jutro, je vzhodnik prinesel leteče kobilice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Leteče kobilice so se dvignile nad vso egiptovsko deželo in počivale po vseh egiptovskih pokrajinah. Bile so zelo nadležne. Pred njimi ni bilo takšnih letečih kobilic kakor te niti takšnih ne bo za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Kajti pokrile so obličje celotne zemlje, tako da je bila dežela temna. Pojedle so vsa zelišča dežele in vse sadje dreves, ki jih je pustila toča. Niti ena zelena stvar ni preostala na drevesih ali na poljskih zeliščih po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Potem je faraon v naglici dal poklicati Mojzesa in Arona ter rekel: »Grešil sem zoper Gospoda, svojega Boga in zoper vaju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Zdaj torej oprostita, prosim vaju, moj greh, samo še tokrat in rotita Gospoda, svojega Boga, da mi lahko odvzame samo to smrt.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'In odšel je ven od faraona in rotil Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, '§ Gospod je [veter] obrnil [v] mogočen močan zahodnik, ki je odnesel leteče kobilice in jih vrgel v Rdeče morje. Tam ni ostala niti ena leteča kobilica po vseh egiptovskih pokrajinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Toda Gospod je zakrknil faraonovo srce, tako da ta ni hotel pustiti Izraelovih otrok oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Gospod je rekel Mojzesu: »Iztegni svojo roko proti nebu, da bo lahko tam tema nad egiptovsko deželo, celó tema, ki se jo bo lahko čutilo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Mojzes je iztegnil svojo roko proti nebu in tri dni je bila gosta tema po vsej egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Drug drugega niso videli niti tri dni ni nihče vstal iz svojega kraja, toda vsi Izraelovi otroci so imeli v svojih prebivališčih svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Faraon je klical k Mojzesu ter rekel: »Pojdite, služite Gospodu. Samo vaši tropi in vaše črede naj ostanejo; naj gredo z vami tudi vaši malčki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mojzes je rekel: »Moraš nam dati tudi klavne daritve in žgalne daritve, da bomo lahko darovali Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Tudi naša živina bo šla z nami. Niti kopito ne bo ostalo zadaj, kajti od nje moramo vzeti, da služimo Gospodu, svojemu Bogu in ne vemo s čim moramo služiti Gospodu, dokler ne pridemo tja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Toda Gospod je zakrknil faraonovo srce in ta jim ni hotel pustiti oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Faraon mu je rekel: »Spravi se od mene, pazi se, da ne vidiš več mojega obraza, kajti na ta dan, [ko] zagledaš moj obraz, boš umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mojzes je rekel: »Dobro si govoril, tvojega obraza ne bom več ponovno videl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Gospod je rekel Mojzesu: »Še eno nadlogo več bom privedel nad faraona in nad Egipt, potem vam bo pustil oditi. Ko vam bo pustil oditi, vas bo zagotovo vse skupaj sunil od tod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Govori torej v ušesa ljudstvu in naj si vsak mož izposodi od svojega soseda in vsaka ženska od svoje sosede dragocenosti iz srebra in dragocenosti iz zlata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Gospod je dal ljudstvu naklonjenost v očeh Egipčanov. Poleg tega je bil človek Mojzes zelo velik v egiptovski deželi, v očeh faraonovih služabnikov in v očeh ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Mojzes je rekel: »Tako govori Gospod: ›Okoli polnoči bom odšel ven, v sredo Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Vsi prvorojenci v egiptovski deželi bodo umrli, od faraonovega prvorojenca, ki sedi na njegovem prestolu, celo do prvorojenca dekle, ki je za mlinom in vse prvorojeno od živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Veliko vpitje bo po vsej egiptovski deželi, kot takšnega tam ni bilo niti ne bo več podobnega temu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Toda zoper kateregakoli izmed Izraelovih otrok niti pes ne bo premaknil svojega jezika, zoper človeka ali žival, da boste lahko vedeli, kako Gospod postavlja razliko med Egipčani in Izraelom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Vsi ti tvoji služabniki bodo prišli dol k meni in se mi priklonili, rekoč: ›Pojdi ven ti in vse ljudstvo, ki ti sledi.‹ In potem bom šel ven.« In od faraona je odšel v veliki jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Gospod je rekel Mojzesu: »Faraon vama ne bo prisluhnil, da bodo moji čudeži lahko pomnoženi v egiptovski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mojzes in Aron sta vse te čudeže storila pred faraonom, Gospod pa je zakrknil faraonovo srce, tako da ta ne bi pustil Izraelovih otrok oditi ven iz svoje dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Gospod je spregovoril Mojzesu in Aronu v egiptovski deželi, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '»Ta mesec vam bo začetek mesecev. Ta vam bo prvi mesec v letu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Govorita vsej Izraelovi skupnosti, rekoč: ›V desetem dnevu tega meseca si bo vsakdo vzel jagnje, glede na hišo svojih očetov, jagnje za hišo‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'in če bo družina premajhna za jagnje, naj ga on in njegov sosed, poleg njegove hiše, vzameta glede na število duš. Vsak človek bo glede na svoje prehranjevanje preštet na jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Vaše jagnje bo brez pomanjkljivosti, samec prvega leta. Vzeli ga boste izmed ovc ali izmed koz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Varovali ga boste do štirinajstega dne istega meseca in celoten zbor Izraelove skupnosti ga bo zvečer zaklal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Vzeli bodo od krvi in le-to potegnili s črto na dva podboja in na naddurje hiš, v katerih ga bodo jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'In v tej noči bodo jedli meso, pečeno na ognju in nekvašen kruh, in z grenkimi zelišči ga bodo jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ne jejte od njega surovega niti vsega skuhanega z vodo, temveč pečenega na ognju. Njegovo glavo z njegovimi nogami in z njegovo drobovino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'In ničesar od njega ne boste pustili do jutra. To, kar od njega ostane do jutra, boste sežgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Tako ga boste jedli: z vašimi ledji opasanimi, vašimi čevlji na vaših stopalih in vašo palico v vaši roki. Jedli ga boste v naglici. To je Gospodova pasha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Kajti to noč pojdem skozi egiptovsko deželo in udaril bom vse prvorojeno v egiptovski deželi, tako človeka kakor žival in zoper vse egiptovske bogove bom izvršil sodbo. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Kri vam bo za simbol na hišah, kjer ste. Ko zagledam kri, bom šel mimo vas in nadloga ne bo na vas, da vas uniči, ko udarim egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Ta dan vam bo v spomin, in vi ga boste ohranjali kot praznik Gospodu skozi svoje rodove. To praznovanje boste ohranjali kot odredbo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sedem dni boste jedli nekvašeni kruh; celo prvi dan boste iz svojih hiš odstranili kvas, kajti kdorkoli jé kvašeni kruh od prvega dne do sedmega dne, bo ta duša iztrebljena iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Na prvi dan bo sveti sklic in na sedmi dan vam bo sveti sklic. V teh ne bo opravljena nobena vrsta dela, razen tega, kar mora vsak človek jesti, samo to lahko delate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Obeležili boste praznik nekvašenega kruha, kajti na prav isti dan sem vaše vojske privedel iz egiptovske dežele. Zato boste ta dan v svojih rodovih obeleževali kot odredbo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'V prvem mesecu, na štirinajsti dan meseca zvečer, boste jedli nekvašeni kruh do enaindvajsetega dne meseca zvečer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sedem dni naj v vaših hišah ne bo najti kvasa, kajti kdorkoli jé to, kar je kvašeno, celo ta duša bo iztrebljena iz Izraelove skupnosti, bodisi da je tujec ali rojen v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ničesar kvašenega ne boste jedli. V vseh svojih prebivališčih boste jedli nekvašeni kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Potem je Mojzes dal poklicati vse Izraelove starešine in jim rekel: »Izberite in vzemite si jagnje glede na svoje družine in zakoljite pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Vzeli boste šop izopa in ga pomočili v kri, ki je v umivalniku in vratno preklado ter dva podboja premazali s krvjo, ki je v umivalniku; in nihče izmed vas do jutra ne bo šel ven pri vratih svoje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Kajti Gospod bo šel skozi, da udari Egipčane in ko na vratni prekladi in dveh stranskih podbojih zagleda kri, bo Gospod šel mimo vrat in ne bo dopustil, da bi pokončevalec vstopil v vaše hiše, da vas udari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Vi pa boste to stvar obeležili kot odredbo sebi in svojim sinovom na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'In zgodilo se bo, ko boste prišli v deželo, ki vam jo bo dal Gospod, glede [na to], kar je obljubil, da boste ohranjali to službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Zgodilo se bo, ko vam bodo vaši otroci rekli: ›Kaj nameravate s tem služenjem?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'da boste rekli: ›To je klavna daritev pashe Gospodu, ki je v Egiptu šel mimo hiš Izraelovih otrok, ko je udaril Egipčane in rešil naše hiše.‹« In ljudstvo je sklonilo glavo ter oboževalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Izraelovi otroci so odšli in storili, kakor je Gospod zapovedal Mojzesu in Aronu, tako so storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Pripetilo se je, da je ob polnoči Gospod udaril vse prvorojeno v egiptovski deželi, od faraonovega prvorojenca, ki je sedel na njegovem prestolu, do ujetnikovega prvorojenca, ki je bil v grajski ječi in vse prvorojeno od živine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Faraon je ponoči vstal, on in vsi njegovi služabniki in vsi Egipčani in v Egiptu je bilo veliko vpitje, kajti ni bilo hiše, kjer ni bi bilo enega mrtvega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Ponoči je dal poklicati Mojzesa in Arona ter rekel: »Vstanite in odpravite se proč izmed mojega ljudstva, tako vidva kakor Izraelovi otroci in pojdite, služite Gospodu, kakor sta rekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Prav tako vzemite vaše trope in vaše črede, kakor sta rekla in izginite; in tudi mene blagoslovita.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Egipčani so pritiskali na ljudstvo, da bi jih lahko v naglici odposlali iz dežele, kajti rekli so: »Mi vsi bomo mrtvi ljudje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Ljudstvo je vzelo svoje testo, preden je bilo to vzhajano in svoje nečke, ki so bile povezane v njihovih oblačilih, na svoje rame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Izraelovi otroci so storili glede na Mojzesovo besedo in od Egipčanov so si izposodili dragocenosti iz srebra in dragocenosti iz zlata in oblačil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'In Gospod je dal ljudstvu naklonjenost v očeh Egipčanov, tako da so jim posodili takšne stvari, kot so jih zahtevali. In oplenili so Egipčane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, '§ Izraelovi otroci so potovali od Ramesésa do Sukóta, okoli šeststo tisoč pešcev, ki so bili možje, poleg otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Z njimi je odšla gor tudi mešana množica, tropi in črede, zelo veliko živine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Iz testa, ki so ga prinesli iz Egipta, so spekli nekvašeni kruh, kajti ni bil še vzhajan, ker so bili sunjeni iz Egipta in niso mogli ostati niti si zase niso pripravili nobenega živeža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Torej začasno bivanje Izraelovih otrok, ki so prebivali v Egiptu, je bilo štiristo trideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Ob koncu štiristo tridesetih let se je pripetilo, celo prav na isti dan se je pripetilo, da so vse Gospodove vojske odšle iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'To je noč, ki bo zelo obeleževana Gospodu, ker jih je privedel iz egiptovske dežele. To je tista Gospodova noč, ki jo bodo obeleževali vsi Izraelovi otroci v svojih rodovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Gospod je rekel Mojzesu in Aronu: »To je odredba pashe: ›Naj noben tujec od tega ne jé,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'toda vsakogar služabnik, ki je kupljen za denar, ko si ga obrezal, potem bo jedel od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Tuj človek in najeti služabnik ne bosta jedla od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Jedlo se ga bo v eni hiši. Nič od mesa ne boš nosil ven iz hiše niti ne boste prelomili njegove kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Vsa Izraelova skupnost se bo tega držala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Ko bo tujec začasno prebival s teboj in bo praznoval pasho Gospodu, naj bodo vsi njegovi moški obrezani in takrat pustite, da pride blizu in se tega drži, in on naj vam bo kakor nekdo, ki je rojen v deželi, kajti nobena neobrezana oseba ne bo jedla od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ena postava bo tistemu, ki je rojen doma in tujcu, ki začasno biva med vami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Tako so storili vsi Izraelovi otroci; kakor je Gospod zapovedal Mojzesu in Aronu, tako so storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Na prav isti dan se je pripetilo, da je Gospod privedel Izraelove otroke po njihovih vojskah iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '»Posvéti mi vse prvorojeno, karkoli odpre maternico med Izraelovimi otroki, tako od ljudi in od živali. To je moje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Mojzes je rekel ljudstvu: »Spominjajte se tega dne, na katerega ste prišli iz Egipta, iz hiše sužnosti; kajti z močjo roke vas je Gospod privedel iz tega kraja. Tam se ne bo jedlo nič kvašenega kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Ta dan ste prišli ven v mesecu abíbu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Zgodilo se bo, ko vas bo Gospod privedel v deželo Kánaancev, Hetejcev, Amoréjcev, Hivéjcev in Jebusejcev, ki jo je prisegel vašim očetom, da vam jo da, deželo, kjer tečeta mleko in med, da se boš v tem mesecu držal te službe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sedem dni boš jedel nekvašeni kruh in na sedmi dan bo praznik Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Nekvašeni kruh se bo jedel sedem dni in tam pri tebi naj ne bo videti nobenega kvašenega kruha niti ne bo kvasa s teboj v vseh tvojih četrtih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Tistega dne boš svojemu sinu pokazal, rekoč: › To je storjeno zaradi tega, kar mi je storil Gospod, ko sem izšel iz Egipta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'To ti bo za znamenje na tvoji roki in za spomin med tvojimi očmi, da bo lahko Gospodova postava v tvojih ustih, kajti z močno roko te je Gospod privedel iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Držal se boš torej te odredbe v njenem času iz leta v leto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Zgodilo se bo, ko te bo Gospod pripeljal v deželo Kánaancev, kakor je prisegel tebi in tvojim očetom in ti jo bo dal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'da boš oddvojil Gospodu vse, kar odpre maternico in vsak prvenec, ki pride iz živali, ki jo imaš; samci bodo Gospodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Vsakega prvenca osla pa boš odkupil z jagnjetom. Če pa ga ne boš odkupil, potem mu boš zlomil tilnik. Med svojimi otroki boš odkupil vsakega moškega prvorojenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Zgodilo se bo, ko te tvoj sin vpraša, v času, ki pride, rekoč: ›Kaj je to?‹ da mu boš rekel: ›Z močjo roke nas je Gospod privedel iz Egipta, iz hiše sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Pripetilo se je, ko nas je faraon komajda odpustil, da je Gospod usmrtil vse prvorojene v egiptovski deželi, tako prvorojene od človeka, kakor prvorojene od živali.‹ Zato žrtvujem Gospodu vse, kar odpre maternico in so samci. Toda vse prvorojene izmed svojih otrok odkupim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'To bo za simbol na tvoji roki in za načelek med tvojimi očmi, kajti z močjo roke nas je Gospod privedel iz Egipta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Pripetilo se je, ko je faraon ljudstvu pustil oditi, da jih Bog ni vodil po poti dežele Filistejcev, čeprav je bila ta blizu, kajti Bog je rekel: »Da se ne bi morda ljudstvo pokesalo, ko zagleda vojno in se vrnejo v Egipt,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, '§ ampak je Bog ljudstvo vodil naokoli, po poti divjine Rdečega morja in Izraelovi otroci so se postrojeni dvignili iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mojzes je s seboj vzel Jožefove kosti, kajti ta je strogo zaprisegel Izraelove otroke, rekoč: »Bog vas bo zagotovo obiskal; in vi boste s seboj odnesli moje kosti proč od tod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'In napotili so se na svoje potovanje iz Sukóta in se utaborili v Etámu, na robu divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'In Gospod je hodil podnevi pred njimi v oblačnem stebru, da jih vodi po poti, ponoči pa v ognjenem stebru, da jim daje svetlobo, da bi hodili podnevi in ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Izpred ljudstva ni vzel proč oblačnega stebra podnevi niti ognjenega stebra ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '»Govori Izraelovim otrokom, da se obrnejo in se utaborijo pred Pi Hahirótom, med Migdólom in morjem, nasproti Báal Cefónu. Pred njim se boste utaborili ob morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Kajti faraon bo o Izraelovih otrocih rekel: ›Zapletli so se v deželi, divjina jih je zaprla noter.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Jaz pa bom zakrknil faraonovo srce, da bo sledil za njimi in počaščen bom na faraonu in na vsej njegovi vojski, da bodo Egipčani lahko spoznali, da jaz sem Gospod.« In tako so storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Egiptovskemu kralju je bilo povedano, da je ljudstvo zbežalo. In srce faraona in njegovih služabnikov je bilo obrnjeno zoper ljudstvo in rekli so: »Zakaj smo storili to, da smo pustili Izraela oditi od služenja nam?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'In pripravil je svoj bojni voz in s seboj vzel svoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Vzel je šeststo izbranih bojnih voz in vse egiptovske bojne vozove in častnike nad vsakim izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Gospod je zakrknil srce faraonu, egiptovskemu kralju in ta je zasledoval Izraelove otroke. Izraelovi otroci pa so izšli z vzdignjeno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Toda Egipčani so jih zasledovali, vsi faraonovi konji in bojni vozovi in njegovi konjeniki in njegova vojska in jih dohiteli ob morju, utaborjene poleg Pi Hahiróta, pred Báal Cefónom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Ko se je faraon približal, so Izraelovi otroci povzdignili svoje oči in glej, Egipčani so korakali za njimi in bili so boleče prestrašeni in Izraelovi otroci so zavpili h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Mojzesu so rekli: »Ali si nas odpeljal proč, da umremo v divjini, ker ni bilo grobov v Egiptu? Zakaj si tako ravnal z nami, da si nas odvedel iz Egipta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Mar ni to beseda, ki smo ti jo povedali v Egiptu, rekoč: ›Pusti nas pri miru, da lahko služimo Egipčanom?‹ Kajti za nas bi bilo bolje, da služimo Egipčanom, kakor pa, da bi umrli v divjini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mojzes je ljudstvu rekel: »Ne bojte se, mirno stojte in glejte Gospodovo rešitev duš, ki vam jo bo danes pokazal, kajti Egipčane, ki ste jih videli danes, jih na veke ne boste več videli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Gospod se bo boril za vas in vi boste ohranili svoj mir.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Gospod je rekel Mojzesu: »Zakaj vpiješ k meni? Govori Izraelovim otrokom, da gredo naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Toda ti vzdigni svojo palico in iztegni svojo roko nad morje in ga razdeli in Izraelovi otroci bodo šli po suhih tleh skozi sredo morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Glej, zakrknil bom srca Egipčanom in oni jim bodo sledili in jaz si bom pridobil čast nad faraonom in nad vso njegovo vojsko, nad njegovimi bojnimi vozovi in nad njegovimi konjeniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Egipčani bodo vedeli, da jaz sem Gospod, ko sem si pridobil čast nad faraonom, nad njegovimi bojnimi vozovi in nad njegovimi konjeniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Božji angel, ki je šel pred Izraelovim taborom, se je odstranil in odšel za njimi, in oblačni steber je odšel izpred njihovih obrazov in stal za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, '§ Prišel je med tabor Egipčanov in tabor Izraela. Njim je bil oblak in tema, toda le-tem je dajal svetlobo ponoči, tako da vso noč eni niso prišli blizu k drugim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Mojzes je svojo roko iztegnil nad morje in Gospod je storil, da je morje vso tisto noč šlo nazaj z močnim vzhodnikom in naredilo morje kopno zemljo in vode so bile razdeljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'In Izraelovi otroci so šli v sredo morja po suhih tleh in vode so jim bile zid na njihovi desnici in na njihovi levici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Egipčani pa so jih zasledovali in šli noter za njimi v sredo morja, celo vsi faraonovi konji, njegovi bojni vozovi in njegovi konjeniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Pripetilo se je, da je ob jutranji straži Gospod skozi ognjen in oblačen steber pogledal na vojsko Egipčanov in prizadel vojsko Egipčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, '§ Snemal je kolesa njihovim bojnim vozovom, da so jih težko vozili. Tako da so Egipčani rekli: »Zbežimo pred obličjem Izraela, kajti Gospod se bori zanje zoper Egipčane.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Gospod je rekel Mojzesu: »Svojo roko iztegni nad morje, da lahko vode ponovno pridejo nad Egipčane, nad njihove bojne vozove in nad njihove konjenike.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, '§ Mojzes je svojo roko iztegnil nad morje in ko se je prikazalo jutro, se je morje vrnilo k svoji moči in Egipčani so bežali proti le-temu; in Gospod je Egipčane porazil v sredi morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Vode so se vrnile in pokrile bojne vozove, konjenike in vso faraonovo vojsko, ki je za njimi prišla v morje. Tam ni ostal niti eden izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Toda Izraelovi otroci so hodili po suhi zemlji v sredi morja. Vode so jim bile zid na njihovi desnici in na njihovi levici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Tako je Gospod tega dne rešil Izraela iz roke Egipčanov, in Izrael je videl Egipčane mrtve na morski obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Izrael je videl to veliko delo, ki ga je Gospod storil na Egipčanih, in ljudstvo se je balo Gospoda in verjelo Gospodu in njegovemu služabniku Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Potem so Mojzes in Izraelovi otroci peli Gospodu tole pesem in govorili, rekoč: »Prepeval bom Gospodu, kajti sijajno je zmagal. Konja in njegovega jezdeca je vrgel v morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Gospod je moja moč in pesem in postal je rešitev moje duše. On je moj Bog in pripravil mu bom prebivališče; Bog mojega očeta in poviševal ga bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Gospod je bojevnik. Gospod je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraonove vozove in njegovo vojsko je vrgel v morje. Tudi njegovi izbrani častniki so se utopili v Rdečem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Globine so jih pokrile. Na dno so potonili kakor kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tvoja desnica, oh Gospod, je postala veličastna v oblasti. Tvoja desnica, oh Gospod, je sovražnika razbila na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'V veličini svoje odličnosti si premagal tiste, ki so se vzdignili zoper tebe. Ti pošiljaš svoj bes, ki jih je použil kakor strnišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'S sunkom vetra tvojih nosnic so bile vode zbrane skupaj, poplave so stale pokončno kakor kup in globine so bile strjene v srcu morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Sovražnik je rekel: ›Zasledoval bom, dohitel bom, razdelil bom ukradeno blago. Moje poželenje bo zadovoljeno nad njimi. Izvlekel bom svoj meč, moja roka jih bo uničila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Zapihal si s svojim vetrom, morje jih je pokrilo. Potonili so kakor svinec v mogočnih vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kdo je podoben tebi, oh Gospod, med bogovi? Kdo je podoben tebi, veličasten v svetosti, strašen v hvalah, ki delaš čudeže?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Izteguješ svojo desnico, zemlja jih je požrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'V svojem usmiljenju si vodil svoje ljudstvo, ki si ga odkupil. V svoji moči si jih vodil k svojemu svetemu prebivališču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, '§ Ljudstvo bo slišalo in bo prestrašeno. Bridkost se bo polastila filistejskih prebivalcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Potem bodo edómski vojvode osupli; mogočni možje Moába, polastilo se jih bo trepetanje; vsi prebivalci Kánaana se bodo stopili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Strah in groza bosta padla nanje. Z veličino tvojega lakta bodo tako mirni kakor kamen, dokler tvoje ljudstvo ne gre mimo, oh Gospod, dokler ne gre mimo ljudstvo, ki si ga ti odkupil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Privedel jih boš noter in jih zasadil na gori svoje dediščine, na kraju, oh Gospod, ki si ga ti naredil zase, da v njem prebivaš, v Svetišču, oh Gospod, ki so ga tvoje roke osnovale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Gospod bo kraljeval na veke vekov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Kajti faraonov konj je šel noter v morje s svojimi bojnimi vozovi in s svojimi konjeniki in Gospod je nadnje ponovno privedel morske vode, toda Izraelovi otroci so šli po suhi zemlji sredi morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Mirjam, prerokinja, Aronova sestra, je v svojo roko vzela tamburin in vse ženske so za njo odšle ven s tamburini in s plesi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mirjam jim je odgovorila: »Prepevajte Gospodu, kajti sijajno je zmagal; konja in njegovega jezdeca je vrgel v morje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, '§ Tako je Mojzes privedel Izraela od Rdečega morja in šli so ven v divjino Šur, in šli so tri dni v divjino, pa niso našli nobene vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Ko so prišli do Mare, niso mogli piti od vodá Mare, kajti bile so grenke. Zato je bilo njeno ime imenovano Mara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Ljudstvo je godrnjalo zoper Mojzesa, rekoč: »Kaj bomo pili?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'In klical je h Gospodu in Gospod mu je pokazal les. Ko je le-tega vrgel v vode, so vode postale sladke. Tam je zanje naredil zakon in odredbo in tam jih je preizkusil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'in rekel: »Če boš pazljivo prisluhnil glasu Gospoda, svojega Boga in boš delal to, kar je pravilno v njegovem pogledu in boš prisluhnil njegovim zapovedim in se držal vseh njegovih zakonov, ne bom položil nate nobene od teh bolezni, ki sem jih privedel nad Egipčane, kajti jaz sem Gospod, ki te ozdravlja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'In prišli so do Elíma, kjer je bilo dvanajst vodnjakov vode in sedemdeset palm, in tam so se utaborili ob vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Odšli so na svoje potovanje od Elíma in vsa skupnost Izraelovih otrok je prišla v Sinsko divjino, ki je med Elímom in Sinajem, na petnajsti dan drugega meseca po njihovem odhodu iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Celotna skupnost Izraelovih otrok je v divjini godrnjala zoper Mojzesa in Arona');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'in Izraelovi otroci so jima rekli: »Bog daj, da bi umrli po Gospodovi roki v egiptovski deželi, ko smo sedeli pri loncih mesa in ko smo jedli kruha do sitega, kajti privedla sta nas v to divjino, da ta celoten zbor ubijeta z lakoto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Potem je Gospod rekel Mojzesu: »Glej, za vas bom z neba deževal kruh in ljudstvo bo šlo ven in vsak dan nabralo določeno mero, da jih lahko preizkusim, ali se bodo ravnali po moji postavi ali ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'In zgodilo se bo, da bodo na šesti dan pripravili to, kar so prinesli in tega bo dvakrat toliko, kolikor so dnevno nabrali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mojzes in Aron sta vsem Izraelovim otrokom rekla: »Zvečer, takrat boste vedeli, da vas je Gospod izpeljal iz egiptovske dežele');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'in zjutraj, potem boste videli Gospodovo slavo, kajti on posluša vaša mrmranja zoper Gospoda. Kaj pa sva midva, da mrmrate zoper naju?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Mojzes je rekel: » To se bo zgodilo, ko vam bo Gospod zvečer dal za jesti meso in zjutraj kruha do sitega, zakaj Gospod sliši vaša mrmranja, ki jih mrmrate zoper njega. Kaj pa sva midva? Vaša mrmranja niso zoper naju, temveč zoper Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Mojzes je spregovoril Aronu: »Povej vsej skupnosti Izraelovih otrok: ›Pridite bliže, pred Gospoda, kajti slišal je vaša mrmranja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Pripetilo se je, ko je Aron govoril celotni skupnosti Izraelovih otrok, da so pogledali proti divjini in glej, Gospodova slava se je prikazala v oblaku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '»Slišal sem mrmranja Izraelovih otrok. Govori jim, rekoč: ›Zvečer boste jedli meso in zjutraj boste nasičeni s kruhom in vedeli boste, da jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Pripetilo se je, da so se zvečer pojavile prepelice in pokrile tabor in zjutraj je rosa ležala naokoli vojske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Ko je rosa, ki je ležala, izparela, glej, na obličju divjine je ležala majhna okrogla stvar, tako majhna kakor slana na tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, '§ Ko so Izraelovi otroci to zagledali, so drug drugemu rekli: »To je mana.« Kajti niso vedeli, kaj je bilo to. Mojzes pa jim je rekel: »To je kruh, ki vam ga Gospod daje za jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'To je stvar, ki jo je Gospod zapovedal: ›Vsak mož naj od tega nabere glede na svoje prehranjevanje, gomer za vsakega človeka, glede na število vaših oseb; vzemite vsak mož za tiste, ki so v njegovih šotorih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Izraelovi otroci so storili tako in nabrali, nekateri več, drugi manj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Ko so to izmerili z gomerjem, kdor je nabral veliko, ni imel preveč in kdor je nabral malo, ni imel pomanjkanja. Vsak človek je nabral glede na svoje prehranjevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Mojzes je rekel: »Naj noben človek od tega ne pusti do jutra.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Vendar niso poslušali Mojzesa, temveč so nekateri izmed njih pustili od tega do jutra in zaredile so se ličinke ter smrad in Mojzes je bil nad njimi ogorčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'To so nabirali vsako jutro, vsak človek glede na svoje prehranjevanje. Ko pa je sonce postalo vroče, se je stopilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Pripetilo se je, da so na šesti dan nabrali dvakrat toliko kruha, dva gomerja za enega človeka, in prišli so vsi voditelji skupnosti ter povedali Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Rekel jim je: »To je to, kar je rekel Gospod: ›Jutri je počitek svetega šabata Gospodu. To, kar boste spekli, specite danes in zavrite to, kar boste vreli. To pa, kar preostane, vzemite iz uporabe, da bo obdržano do jutra.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'In to so vzeli iz uporabe do jutra, kakor je Mojzes zaukazal, in to ni zaudarjalo niti v tem ni bilo nobenih ličink.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Mojzes je rekel: »To jejte danes, kajti danes je šabat Gospodu. Danes tega ne boste našli na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Šest dni boste to nabirali, toda na sedmi dan, ki je šabat, ne bo ničesar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Pripetilo se je, da je nekaj ljudi izmed ljudstva na sedmi dan odšlo, da nabirajo, pa niso našli ničesar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Gospod je rekel Mojzesu: »Doklej boste odklanjali, da se držite mojih zapovedi in mojih postav?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Poglejte, zakaj Gospod vam je dal šabat, zato vam na šesti dan daje kruh dveh dni. Vsak človek naj ostane na svojem kraju, naj noben človek na sedmi dan ne gre iz svojega kraja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Tako je ljudstvo na sedmi dan počivalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Izraelova hiša je njeno ime imenovala Mana, in ta je bila podobna koriandrovemu semenu, bela, in njen okus je bil podoben vafljem, narejenim z medom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Mojzes je rekel: »To je stvar, ki jo je Gospod zapovedal: ›S tem napolnite gomer, da bo obdržano za vaše rodove, da bodo lahko videli kruh, s katerim sem vas hranil v divjini, ko sem vas izpeljal iz egiptovske dežele.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Mojzes je Aronu rekel: »Vzemi lonec in vanj stresi gomer, poln mane in ga položi pred Gospoda, da bo obdržan za vaše rodove.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Kakor je Gospod zapovedal Mojzesu, tako je Aron to položil pred Pričevanje, da bo obdržano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Izraelovi otroci so štirideset let jedli mano, dokler niso prišli v naseljeno deželo. Jedli so mano, dokler niso prišli do meja kánaanske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Torej gomer je desetina škafa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Vsa skupnost Izraelovih otrok je odpotovala iz Sinske divjine, po njihovih potovanjih, glede na Gospodovo zapoved in utaborili so se v Refidímu. Tam pa ni bilo nobene vode, da bi ljudstvo pilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Zakaj ljudstvo se je pričkalo z Mojzesom in govorilo: »Daj nam vode, da lahko pijemo.« Mojzes pa jim je rekel: »Zakaj se pričkate z menoj? Zakaj skušate Gospoda?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Ljudstvo pa je hlepelo po vodi in ljudstvo je mrmralo zoper Mojzesa ter reklo: »Zakaj je to, da si nas izpeljal iz Egipta, da z žejo ubiješ nas, naše otroke in našo živino?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mojzes je vpil h Gospodu, rekoč: »Kaj naj storim temu ljudstvu? Skoraj so pripravljeni, da me kamnajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Gospod je rekel Mojzesu: »Pojdi naprej pred ljudstvom in s seboj vzemi Izraelove starešine, in svojo palico, s katero si udaril reko, vzemi v svojo roko in pojdi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Glej, stal bom pred teboj, tam na skali na Horebu, ti pa boš udaril skalo in iz nje bo pritekla voda, da bo ljudstvo lahko pilo.« In Mojzes je tako storil v očeh Izraelovih starešin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Ime kraja je imenoval Masa in Meríba, zaradi pričkanja Izraelovih otrok in ker so skušali Gospoda, rekoč: »Je Gospod med nami ali ni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Potem je prišel Amálek in se z Izraelom bojeval v Refidímu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Mojzes je rekel Józuetu: »Izmed nas izberi može in pojdite ven in se bojujte z Amálekom. Jutri bom stal na vrhu hriba z Božjo palico v svoji roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Józue je storil tako, kakor mu je rekel Mojzes in se bojeval z Amálekom. Mojzes, Aron in Hur pa so odšli na vrh hriba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Pripetilo se je, ko je Mojzes držal svojo roko pokonci, da je prevladoval Izrael. Ko pa je svojo roko spustil, je prevladoval Amálek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Vendar pa sta bili Mojzesovi roki težki. Vzela sta kamen in ga položila pod njega in sedel je nanj. Aron in Hur pa sta opirala njegovi roki, eden na eni strani, drugi pa na drugi strani, in njegovi roki sta bili stabilni do sončnega zahoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'In Józue je z ostrino meča porazil Amáleka in njegovo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Gospod je rekel Mojzesu: »Zapiši to za spomin v knjigo in to ponovi v Józuetova ušesa, kajti jaz bom popolnoma izbrisal spomin na Amáleka izpod neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, '§ Mojzes je zgradil oltar in njegovo ime imenoval JAHVE–nisi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'kajti rekel je: »Ker je Gospod prisegel, da bo imel Gospod vojno z Amálekom od roda do roda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Ko je Jitro, midjánski duhovnik, Mojzesov tast, slišal o vsem, kar je Bog storil za Mojzesa in za svoje ljudstvo Izraela in da je Gospod Izraela privedel iz Egipta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'je potem Mojzesov tast Jitro vzel Mojzesovo ženo Cipóro, potem ko jo je ta poslal nazaj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'in njena dva sinova, od katerih je bilo enemu ime Geršóm; kajti rekel je: »Neznanec sem bil v tuji deželi,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'ime drugega pa je bilo Eliézer; kajti: »Bog mojega očeta,« je rekel, »je bil moja pomoč in me osvobodil pred faraonovim mečem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Mojzesov tast Jitro je prišel, z njegovima sinovoma in njegovo ženo, k Mojzesu v divjino, kjer je bil utaborjen pri gori Boga');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'in Mojzesu je rekel: »Jaz, tvoj tast Jitro, sem prišel k tebi in tvoja žena in njena dva sinova z njo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Mojzes je odšel ven, da sreča svojega tasta in se globoko priklonil ter ga poljubil. Drug drugega sta vprašala o njuni blaginji in prišla v šotor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mojzes je svojemu tastu povedal vse, kar je zaradi Izraela Gospod storil faraonu in Egipčanom in vse muke, ki so prišle nadnje na poti in kako jih je Gospod osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jitro se je razveselil zaradi vse dobrote, ki jo je Gospod storil Izraelu, ki ga je osvobodil iz roke Egipčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Jitro je rekel: »Blagoslovljen bodi Gospod, ki vas je osvobodil iz roke Egipčanov in iz roke faraona, ki je ljudstvo osvobodil izpod roke Egipčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Sedaj vem, da je Gospod večji od vseh bogov, kajti v stvari, v kateri so oni ponosno postopali, je bil on nad njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Mojzesov tast Jitro, je vzel žgalno daritev, klavne daritve za Boga in prišel je Aron ter vse Izraelove starešine, da z Mojzesovim tastom jedo kruh pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'In pripetilo se je naslednji dan, da se je Mojzes usedel, da sodi ljudstvu in ljudstvo je stalo pri Mojzesu od jutra do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Ko je Mojzesov tast videl vse to, kar je počel ljudstvu, je rekel: »Kaj je ta stvar, ki jo počneš ljudstvu? Zakaj ti sam sediš, vse ljudstvo pa stoji pri tebi od jutra do večera?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mojzes je svojemu tastu rekel: »Ker ljudstvo prihaja k meni, da povprašuje od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kadar imajo zadevo, pridejo k meni in jaz sodim med enim in drugim in jaz jim dam spoznavati zakone Boga in njegove postave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Mojzesov tast pa mu je rekel: »Stvar, ki jo počneš, ni dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Zagotovo se boš izčrpal, tako ti in to ljudstvo, ki je s teboj, kajti ta stvar je zate pretežka; ti tega nisi zmožen opravljati sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Prisluhni torej mojemu glasu, dal ti bom nasvet in Bog bo s teboj: ›Ti bodi za ljudstvo usmerjen k Bogu, da boš zadeve lahko prinašal k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Učil jih boš odredbe in postave in kazal jim boš pot, po kateri morajo hoditi in delo, ki ga morajo opraviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Poleg tega boš izmed vsega ljudstva priskrbel sposobne može, takšne, ki se bojijo Boga, može resnice, ki sovražijo pohlepnost. Nad njimi postavi takšne, da bodo vodje nad tisočimi in vodje nad stotimi, vodje nad petdesetimi in vodje nad desetimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Ti naj sodijo ljudstvu v vseh obdobjih in zgodilo se bo, da se bo vsaka velika zadeva prinesla predte, toda vsako majhno zadevo bodo sodili oni. Tako bo zate lažje, oni pa bodo breme nosili s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Če boš storil to stvar in ti Bog tako zapove, potem boš zmožen vzdržati in tudi vse to ljudstvo bo v miru hodilo k svojemu kraju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Tako je Mojzes prisluhnil glasu svojega tasta in storil vse, kar je ta rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Mojzes je izbral sposobne može iz vsega Izraela in jih naredil poglavarje nad ljudstvom, vodje nad tisočimi, vodje nad stotimi, vodje nad petdesetimi in vodje nad desetimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Sodili so ljudstvu v vseh obdobjih. Težje stvari so prinašali k Mojzesu, toda vsako majhno zadevo so sodili sami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'In Mojzes je pustil svojemu tastu oditi in ta je odšel svojo pot v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'V tretjem mesecu, ko so Izraelovi otroci odšli iz egiptovske dežele, istega dne, so prišli v Sinajsko divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Kajti odšli so iz Refidíma in prišli v sinajsko puščavo in se utaborili v divjini in tam je Izrael taboril pred goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mojzes je odšel gor k Bogu in Gospod je zaklical k njemu z gore, rekoč: »Tako boš rekel Jakobovi hiši in povedal Izraelovim otrokom:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '›Videli ste, kaj sem storil Egipčanom in kako sem vas nosil na orljih perutih in vas privedel k sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Zdaj torej, če boste zares poslušali moj glas in se držali moje zaveze, potem mi boste izvoljen zaklad nad vsemi ljudstvi, kajti vsa zemlja je moja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'vi pa mi boste kraljestvo duhovnikov in svet narod.‹ To so besede, ki jih boš govoril Izraelovim otrokom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mojzes je prišel ter dal poklicati starešine ljudstva in pred njihove obraze položil vse te besede, ki mu jih je Gospod zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Vse ljudstvo je skupaj odgovorilo ter reklo: »Vse, kar je Gospod govoril, bomo storili.« In Mojzes je besede ljudstva ponovil Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Gospod je rekel Mojzesu: »Glej, k tebi pridem v gostem oblaku, da bo ljudstvo lahko slišalo, ko govorim s teboj in ti verjelo na veke.« In Mojzes je besede ljudstva povedal Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Gospod je rekel Mojzesu: »Pojdi k ljudstvu in posvečuj jih danes in jutri in naj si operejo svoja oblačila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'in bodite pripravljeni za tretji dan, kajti tretji dan bo Gospod prišel dol, v očeh vsega ljudstva, na goro Sinaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Ti pa boš ljudstvu postavil meje naokoli, rekoč: ›Pazite se, da ne greste gor na goro ali se dotaknete njene meje. Kdorkoli se dotakne gore, bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Niti roka se ga ne bo dotaknila, temveč naj bo zagotovo kamnan ali prestreljen; bodisi bo to žival ali človek, naj ta ne živi. Ko zadoni trobljenje naj pridejo h gori.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mojzes je odšel dol z gore k ljudstvu in ljudstvo posvetil, in ti so si oprali svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Ljudstvu je rekel: »Bodite pripravljeni na tretji dan. Ne približujte se k svojim ženam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Na tretji dan se je zjutraj pripetilo, da so bila grmenja in bliski in na gori gost oblak in silno glasen zvok šofarja, tako da je vse ljudstvo, ki je bilo v taboru, trepetalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Mojzes je ljudstvo privedel iz tabora, da se sreča z Bogom. Stali so pri spodnjem delu gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Gora Sinaj je bila povsem v dimu, ker se je Gospod nanjo spustil v ognju in njen dim se je vzpenjal kakor dim iz talilne peči in celotna gora se je silno tresla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Ko je glas šofarja zategnjeno donel in postajal glasnejši in glasnejši, je Mojzes spregovoril in Bog mu je odgovoril z glasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Gospod je prišel dol na goro Sinaj, na vrh gore in Gospod je Mojzesa poklical gor na vrh gore in Mojzes je odšel gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Gospod je rekel Mojzesu: »Pojdi dol, naroči ljudstvu, da se ne bi prebili h Gospodu, da bi strmeli in se mnogi izmed njih pogubijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Naj se tudi duhovniki, ki pridejo bliže h Gospodu, posvétijo, da ne bi Gospod izbruhnil nad njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mojzes pa je rekel Gospodu: »Ljudstvo se ne more povzpeti na goro Sinaj, kajti zapovedal si nam, rekoč: ›Postavi meje okoli gore in jo posvéti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Gospod mu je rekel: »Proč, spusti se in prišel boš gor, ti in Aron s teboj. Toda duhovniki in ljudstvo naj se ne prebijejo, da pridejo h Gospodu, da ne bi nad njimi izbruhnil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Tako je Mojzes odšel dol k ljudstvu in jim spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Bog je spregovoril vse te besede, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '[1] »Jaz sem Gospod, tvoj Bog, ki sem te privedel iz egiptovske dežele, iz hiše sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, '[2] Pred menoj ne boš imel nobenih drugih bogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Sebi ne boš naredil nobene rezane podobe ali kakršnekoli podobnosti čemurkoli, kar je zgoraj na nebu ali kar je spodaj na zemlji ali kar je v vodi pod zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Ne boš se jim priklanjal niti jim ne boš služil, kajti jaz, Gospod, tvoj Bog, sem ljubosumen Bog, ki obiskujem krivičnost očetov na otrocih do tretjega in četrtega rodu tistih, ki me sovražijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'izkazujem pa usmiljenje tisočem tistih, ki me ljubijo in varujejo moje zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, '[3] Ne boš v prazno vzel imena Gospoda, svojega Boga; kajti Gospod ne bo držal brez krivde tistega, ki v prazno jemlje njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, '[4] Spominjaj se šabatnega dne, da ga ohraniš svetega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Šest dni se boš trudil in opravljal vse svoje delo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'toda sedmi dan je šabat Gospodu, tvojemu Bogu. Na [ta dan] ne boš opravljal nobenega dela, ne ti, niti tvoj sin, niti tvoja hči, [niti] tvoj sluga, niti tvoja dekla, niti tvoja živina, niti tvoj tujec, ki je znotraj tvojih velikih vrat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'kajti v šestih dneh je Gospod naredil nebo in zemljo, morje in vse, kar je v njih, sedmi dan pa je počival. Zato je Gospod blagoslovil šabatni dan in ga posvetil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, '[5] Spoštuj svojega očeta in svojo mater, da bodo tvoji dnevi lahko dolgi na zemlji, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, '[6] Ne boš ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, '[7] Ne boš zagrešil zakonolomstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, '[8] Ne boš kradel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, '[9] Ne boš prinašal krivega pričevanja zoper svojega bližnjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, '[10] Ne boš hlepel [po] hiši svojega bližnjega, ne boš hlepel [po] ženi svojega bližnjega, niti [po] njegovem slugi, niti [po] njegovi dekli, niti [po] njegovem volu, niti [po] njegovem oslu, niti [po] katerikoli stvari, ki je od tvojega bližnjega!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'In vse ljudstvo je videlo grmenja in bliske, zvok šofarja in kadečo goro. Ko je ljudstvo to videlo, so se odstranili in stali daleč stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Mojzesu pa so rekli: »Ti govori z nami, mi pa bomo poslušali, toda Bog naj z nami ne govori, da ne bi umrli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mojzes je ljudstvu rekel: »Ne bojte se, kajti Bog je prišel, da vas preizkusi in da je njegov strah lahko pred vašimi obrazi, da ne grešite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, '§ Ljudstvo je stalo daleč stran, Mojzes pa se je približal gosti temi, kjer je bil Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Gospod je rekel Mojzesu: »Tako boš rekel Izraelovim otrokom: ›Videli ste, da sem z vami govoril iz nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Poleg mene ne boste delali bogov iz srebra niti si ne boste delali bogov iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, '§ Naredil mi boš oltar iz zemlje in na njem boš žrtvoval svoje žgalne daritve in svoje mirovne daritve, svoje ovce in svoje vole. Na vseh krajih, kjer zapišem svoje ime, bom prišel k tebi in te blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Če mi hočeš narediti oltar iz kamna, ga ne boš zgradil iz klesanega kamna, kajti če svoje orodje dvigneš nanj, si ga oskrunil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Niti k mojemu oltarju ne boš šel gor po stopnicah, da na njih ne bo odkrita tvoja nagota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Torej to so sodbe, ki jih boš postavil prednje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Če kupiš hebrejskega služabnika, naj ti služi šest let. V sedmem letu pa naj odide prost, brez plačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Če je sam prišel, naj sam odide. Če je bil poročen, potem naj njegova žena odide z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Če mu je njegov gospodar dal ženo in mu je rodila sinove ali hčere, naj bodo žena in njeni otroci [od] njegovega gospodarja, on pa naj odide sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Če mu bo služabnik jasno rekel: ›Ljubim svojega gospodarja, svojo ženo in svoje otroke; ne bom odšel svoboden,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, '§ potem naj ga njegov gospodar privede k sodnikom. Prav tako naj ga privede k vratom ali k podboju in njegov gospodar naj njegovo uho prebode s šilom, on pa naj mu za vedno služi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Če človek proda svojo hčer, da postane dekla, naj ona ne odide, kakor storijo služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Če ne ugaja svojemu gospodarju, ki si jo je zaročil, tedaj naj bo odkupljena. Ne bo imel oblasti, da jo proda v tuj narod, glede na to, da je z njo ravnal varljivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Če jo je zaročil svojemu sinu, naj z njo postopa po načinu hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Če si vzame drugo ženo, naj njene hrane, njenega oblačila in njene zakonske dolžnosti ne zmanjša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Če ji ne stori teh treh stvari, potem naj ta odide ven prosta, brez denarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kdor udarja človeka, tako da umre, naj bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Če človek ne preži nanj, temveč ga Bog izroči v njegovo roko, potem bom določil kraj, kamor naj zbeži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Toda če pride človek prepotentno nad svojega bližnjega, da ga z zvijačo ubije, ga odvedi od mojega oltarja, da lahko umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kdor udarja svojega očeta ali svojo mater, naj bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kdor ugrabi človeka in ga prodaja ali če je le-ta najden v njegovi roki, naj bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Kdor preklinja svojega očeta ali svojo mater, naj bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Če se moža skupaj prepirata in je eden udaril drugega s kamnom ali s svojo pestjo, pa ta ne umre, temveč se drži svoje postelje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, '§ če ta ponovno vstane in hodi okoli na svoji palici, potem naj bo tisti, ki ga je udaril, oproščen. Samo plačal mu bo za izgubo njegovega časa in poskrbel bo, da bo temeljito ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Če človek udari svojega služabnika ali svojo služabnico s palico in le-ta pod njegovo roko umre, naj bo zagotovo kaznovan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Vendar če preživi dan ali dva, naj ne bo kaznovan, kajti on je njegov denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Če se moža prepirata in poškodujeta nosečnico, tako da njen sad odide od nje in ne sledi nobena škoda, naj bo ta zagotovo kaznovan glede na to, kakor mu naloži ženin soprog. Plača naj, kakor mu bodo določili sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Če sledi katerakoli nesreča, potem boš dal življenje za življenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'oko za oko, zob za zob, roko za roko, stopalo za stopalo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, '§ opeklino za opeklino, rano za rano, udarec z bičem za udarec z bičem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Če človek udari oko svojega služabnika ali oko svoje služabnice, da le-ta propade, naj ga pusti oditi svobodnega zaradi njegovega očesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Če svojemu slugi izbije zob ali zob svoji dekli, naj ga pusti oditi prostega zaradi njegovega zoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Če vol zabode moškega ali žensko, da umreta, potem naj bo vol zagotovo kamnan in njegovo meso naj se ne jé, toda lastnik vola naj bo oproščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Toda če je imel vol navado, da je s svojim rogom bodel v preteklem času in je bilo to pričevano njegovemu lastniku, pa ga ta ni držal zaprtega, temveč da je usmrtil moškega ali žensko, naj bo vol kamnan in tudi njegov lastnik naj bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Če mu bo naložena vsota denarja, potem naj da za odkupnino svojega življenja, karkoli mu bo naloženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Če je nabodel sina ali nabodel hčer, naj mu bo storjeno glede na to sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Če bo vol pobodel sluga ali deklo, naj njihovemu gospodarju da trideset šeklov srebra, vol pa naj bo kamnan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Če bo človek odprl jamo ali če bo človek izkopal jamo in je ne bo pokril in vanjo pade vol ali osel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'naj lastnik jame to dobro naredi in da denar lastniku le-teh; mrtva žival pa naj bo njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Če pa vol nekega človeka poškoduje drugega, da ta umre, potem naj prodajo živega vola in razdelijo denar od njega; in prav tako naj razdelijo mrtvega vola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ali če je bilo znano, da je imel vol navado v preteklem času bosti, pa ga njegov lastnik ni imel zaprtega, naj zagotovo plača vola za vola, mrtvi pa naj bo njegov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Če bo človek ukradel vola ali ovco in to zakolje ali proda, naj povrne pet volov za vola in štiri ovce za ovco.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Če je najden tat, da vlamlja in je udarjen, da umre, potem naj zanj ne bo prelite nobene krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Če je nad njim vstalo sonce, naj bo zanj prelita kri, kajti moral bi narediti popolno povračilo. Če nima ničesar, potem naj bo prodan za svojo tatvino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Če je tatvina v njegovi roki zagotovo najdena živa, bodisi je to vol ali osel ali ovca, naj povrne dvojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Če bo človek polju ali vinogradu povzročil, da bo požrto in bo vanj postavil svojo žival, pa se bo pasla na polju drugega človeka, naj povrne od najboljšega svojega lastnega polja in od najboljšega svojega lastnega vinograda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Če izbruhne ogenj in zajame trnje, tako da so s tem použite kopice žita ali stoječe žito ali polje, naj tisti, ki je zanetil ogenj, zagotovo naredi povračilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Če bo človek izročil svojemu bližnjemu v hrambo denar ali stvari, pa bo to ukradeno iz človekove hiše; če bo tat najden, naj plača dvojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, '§ Če tat ne bo najden, potem naj bo gospodar hiše priveden k sodnikom, da vidijo, ali je svojo roko položil na dobrine svojega bližnjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, '§ Kajti vse vrste prekrški, bodisi je to za vola, za osla, za ovco, za oblačilo ali za katerokoli vrsto izgubljene stvari, za katero drug zatrjuje, da je njegova, naj zadeva obeh strani pride pred sodnike. In kogar bodo sodniki obsodili, naj svojemu bližnjemu plača dvojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Če človek svojemu bližnjemu izroči osla ali vola ali ovco ali katerokoli žival v varstvo, pa ta pogine ali je ranjena ali odpeljana proč [in] noben človek tega ne vidi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'potem naj bo Gospodova prisega med njima obema, da svoje roke ni položil na dobrine svojega bližnjega. Njegov lastnik bo od tega sprejel, oni pa tega ne bo povrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Če je to od njega ukradeno, naj od tega lastniku naredi povračilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Če bo to raztrgano na koščke, potem naj to prinese kot pričevanje, on pa ne bo povrnil tega, kar je bilo raztrgano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Če si človek karkoli izposodi od svojega bližnjega in je to poškodovano ali pogine, pa njegov lastnik ni bil s tem, naj on to zagotovo povrne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Vendar, če je bil lastnik od tega z njim, naj on tega ne povrne. Če je bila najeta stvar, je ta prišla za njegovo najemnino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Če mož privabi devico, ki ni zaročena in leži z njo, naj jo zagotovo oskrbi z doto, da postane njegova žena');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Če njen oče popolnoma odklanja, da mu jo da, naj plača denar glede na doto devic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Ne boš trpel, da bi čarovnica živela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Kdorkoli leži z živaljo, naj bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kdor žrtvuje kateremukoli bogu, razen samo Gospodu, naj bo popolnoma uničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tujca ne boš niti dražil niti zatiral, kajti tujci ste bili v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Ne boste stiskali katerekoli vdove ali osirotelega otroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Če jih boste na kakršen koli način stiskali in oni kakorkoli kličejo k meni, bom zagotovo slišal njihov klic');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'in moj bes se bo razvnel in ubil vas bom z mečem; in vaše žene bodo vdove in vaši otroci sirote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Če komurkoli izmed mojega ljudstva, ki je poleg tebe ubog, posodiš denar, do njega ne bodi kakor oderuh niti nanj ne nalagaj obresti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Če sploh vzameš za jamstvo oblačilo svojega bližnjega, mu ga boš izročil do takrat, ko zahaja sonce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Kajti to je njegovo edino pokrivalo, to je njegovo oblačilo za njegovo kožo. V čem bo spal? In zgodilo se bo, ko kliče k meni, da bom slišal, kajti jaz sem milostljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Ne boš zasramoval bogov niti preklinjal vladarja svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, '§ Ne boš odlašal darovati prvin od svojih zrelih sadov in od svojih žganih pijač. Prvorojenega izmed svojih sinov boš dal meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Podobno boš storil s svojimi voli in s svojimi ovcami. Sedem dni naj bo ta s svojo materjo, na osmi dan pa ga boš dal meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Vi mi boste sveti ljudje niti ne boste jedli kakršnega koli mesa, ki je raztrgano od živali na polju; vrgli ga boste psom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Ne boš dvignil napačnega poročila. Svoje roke ne podaj z zlobnim, da bi bil nepravična priča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, '§ Ne boš sledil množici, da počneš zlo. Niti ne boš govoril v zadevi, da se ne nagneš za mnogimi, ki pačijo sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Niti ne boš podpiral reveža v njegovi zadevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Če srečaš vola svojega sovražnika ali njegovega osla zaiti, mu ga boš zagotovo ponovno privedel nazaj k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Če vidiš osla tistega, ki te sovraži, ležati pod svojim bremenom in odlašaš, da mu pomagaš, mu boš zagotovo z njim vred pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ne boš pačil sodbe ubogega v njegovi zadevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Drži se proč od napačne stvari. Nedolžnega in pravičnega ne ubij, kajti zlobnega ne bom opravičil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, '§ In ti ne boš prejel nobenega daru, kajti dar slepi modrega in izkrivlja besede pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, '§ Tudi ne boš zatiral tujca, kajti poznate srce tujca, glede na to, da ste bili tujci v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Šest let boš sejal svojo zemljo in zbiral njene sadove,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'toda sedmo leto jo boš pustil počivati in mirno ležati, da ubogi izmed tvojega ljudstva lahko jedo. Kar bodo pustili, naj pojedo živali polja. Na podoben način boš postopal s svojim vinogradom in s svojim oljčnim nasadom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Šest dni boš opravljal svoje delo, na sedmi dan pa boš počival, da bosta tvoj vol in tvoj osel lahko počivala in bosta sin tvoje pomočnice in tujec lahko osvežena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'V vseh stvareh, ki sem ti jih rekel, bodi preudaren. In ne omenjaj imena drugih bogov niti naj tega ne bo slišati iz tvojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trikrat v letu mi boš ohranjal praznovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Ohranjal boš praznik nekvašenega kruha (sedem dni boš jedel nekvašeni kruh, kakor sem ti zapovedal, v določenem času meseca abíba, kajti v njem si prišel iz Egipta in nihče se pred menoj ne bo prikazal prazen)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'in praznik žetve, prve sadove svojih trudov, ki si jih posejal na polju in praznik spravljanja, ki je ob koncu leta, ko si svoje trude pospravil s polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trikrat na leto naj se vsi tvoji možje prikažejo pred Gospodom Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Krvi moje klavne daritve ne boš žrtvoval z vzhajanim kruhom niti naj maščoba mojega darovanja ne ostane do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Prvine od prvih sadov svoje zemlje boš prinesel v hišo Gospoda, svojega Boga. Kozlička ne boš zavrel v mleku njegove matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Glej, pred teboj pošiljam Angela, da te varuje na poti in te privede na kraj, ki sem ga pripravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Pazi se ga in ubogaj njegov glas, ne izzivaj ga, kajti ne bo oprostil tvojih prestopkov, kajti moje ime je v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Toda če boš zares ubogal njegov glas in storil vse, kar ti govorim, potem bom sovražnik tvojih sovražnikov in nasprotnik tvojih nasprotnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Kajti moj Angel bo šel pred teboj in te privede k Amoréjcem, Hetejcem, Perizéjcem, Kánaancem, Hivéjcem in Jebusejcem, in jaz jih bom odrezal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Ne boš se priklanjal njihovim bogovom niti jim služil niti počel po njihovih delih, temveč jih boš popolnoma premagal in popolnoma zlomil njihove podobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Služili boste Gospodu, svojemu Bogu in on bo blagoslovil tvoj kruh in tvojo vodo, in iz tvoje srede bom odvzel bolezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, '§ V tvoji deželi nič ne bo zavrglo svojih mladih niti ne bo jalovo. Število tvojih dni bom izpolnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Pred teboj bom poslal svoj strah in uničil bom vsa ljudstva, h katerim boš prišel in vsem tvojim sovražnikom bom storil, da svoje hrbte obrnejo k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Pred teboj bom poslal sršene, ki bodo izpred tebe napodili Hivéjce, Kánaance in Hetejce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Izpred tebe jih ne bom pognal v enem letu, da ne bi zemlja postala zapuščena in bi se zoper tebe namnožile poljske zveri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Po malo in malo jih bom podil izpred tebe, dokler ne boš narasel in podedoval dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, '§ Tvoje meje bom postavil od Rdečega morja, celo do morja Filistejcev in od puščave do reke, kajti jaz bom prebivalce dežele izročil v tvojo roko, ti pa jih boš pognal pred seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Z njimi ne boš sklenil nobene zaveze niti z njihovimi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Naj ne prebivajo v tvoji deželi, da te ne bi pripravili grešiti zoper mene, kajti če boš služil njihovim bogovom, ti bodo le-ti zagotovo zanka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Mojzesu je rekel: »Pridite gor h Gospodu, ti in Aron, Nadáb in Abihú ter sedemdeset Izraelovih starešin in obožujte daleč stran.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Samo Mojzes pa bo prišel blizu Gospodu, toda oni naj ne pridejo blizu; niti ne bo ljudstvo z njim šlo gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mojzes je prišel in ljudstvu povedal vse Gospodove besede in vse sodbe, in vse ljudstvo je odgovorilo z enim glasom ter reklo: »Vse besede, ki jih je povedal Gospod, bomo izpolnjevali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Mojzes je zapisal vse Gospodove besede in vstal zgodaj zjutraj in pod hribom zgradil oltar in dvanajst stebrov, glede na dvanajst Izraelovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Poslal je mladeniče izmed Izraelovih otrok, ki so darovali žgalne daritve in žrtvovali mirovne daritve volov Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Mojzes je vzel polovico od krvi ter jo dal v umivalnike, polovico od krvi pa je poškropil na oltar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Vzel je knjigo zaveze in bral v občinstvu ljudstva, in rekli so: »Vse, kar je rekel Gospod, bomo izpolnjevali in bomo poslušni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mojzes je vzel kri in jo poškropil na ljudstvo ter rekel: »Poglejte kri zaveze, ki jo je Gospod z vami sklenil glede vseh teh besed.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Potem so šli gor Mojzes in Aron, Nadáb in Abihú ter sedemdeset izmed Izraelovih starešin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'in videli so Izraelovega Boga in pod njegovimi stopali je bilo kakor bi bilo to tlakovano delo iz kamna safirja in kakor bi bilo to nebeško telo v svoji jasnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Na plemiče Izraelovih otrok pa ni položil svoje roke; tudi oni so videli Boga in so jedli ter pili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Gospod je rekel Mojzesu: »Pridi gor k meni na goro in bodi tam, jaz pa ti bom dal kamniti plošči, postavo in zapovedi, ki sem jih zapisal, da jih boš lahko učil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Mojzes je vstal ter njegov strežnik Józue in Mojzes je šel gor na goro Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Starešinam pa je rekel: »Čakajte tukaj na naju, dokler ponovno ne prideva k vam. Glejte, Aron in Hur sta z vami. Če ima katerikoli človek za urediti kakršnekoli zadeve, naj pride k njima.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Mojzes je odšel gor na goro in goro je pokril oblak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Gospodova slava je ostala na gori Sinaj in oblak jo je pokrival šest dni. Sedmi dan pa je iz srede oblaka zaklical k Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Prizor Gospodove slave na vrhu gore je bil v očeh Izraelovih otrok podoben požirajočemu ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Mojzes je odšel v sredo oblaka in se povzpel na goro. Mojzes je bil na gori štirideset dni in štirideset noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '»Govori Izraelovim otrokom, da mi prinesejo daritev. Od vsakega človeka, ki to daje voljno, s svojim srcem, boste vzeli mojo daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'To je darovanje, ki ga boste jemali od njih: zlato, srebro, bron,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'modro, vijolično, škrlatno in tanko laneno platno, kozjo dlako,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, '§ rdeče barvane ovnove kože, jazbečeve kože, akacijev les,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'olje za svetlobo, dišave za mazilno olje, za dišeče kadilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'oniksove kamne in kamne, da bodo vdelani v efód in v naprsnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'In naj mi naredijo svetišče, da bom lahko prebival med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Glede na vse, kar sem ti pokazal, po vzorcu šotorskega svetišča in vzorcu vseh njegovih priprav, celo tako boste to naredili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Skrinjo bodo naredili iz akacijevega lesa. Dva komolca in pol bo njena dolžina, komolec in pol njena širina ter komolec in pol njena višina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Prevlekel jo boš s čistim zlatom; znotraj in zunaj jo boš prevlekel in na njej naokoli boš naredil krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Zanjo boš ulil štiri obroče iz zlata in jih namestil na njene štiri vogale. Dva obroča bosta na eni njeni strani, dva obroča pa na drugi njeni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Naredil boš drogova iz akacijevega lesa in ju prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Drogova boš položil v obroča pri obeh straneh skrinje, da bo skrinja lahko z njima prenašana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Drogova naj bosta v obročih skrinje. Naj ne bosta vzeta od nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'V skrinjo pa boš položil pričevanje, ki ti ga bom dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Naredil boš sedež milosti iz čistega zlata. Dva komolca in pol naj bo njegova dolžina ter komolec in pol njegova širina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Naredil boš dva keruba iz zlata, iz kovanega dela ju boš naredil, na dveh koncih sedeža milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Enega keruba naredi na enem koncu, drugega keruba pa na drugem koncu. Iz sedeža milosti boš naredil keruba na dveh njegovih koncih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Keruba naj svoji peruti iztegujeta na visoko, pokrivajoč sedež milosti s svojimi perutmi in njuna obraza naj gledata drug proti drugemu. Proti sedežu milosti naj bosta obraza kerubov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Sedež milosti boš položil zgoraj nad skrinjo, v skrinjo pa boš položil pričevanje, ki ti ga bom dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tam se bom srečeval s teboj in se iznad sedeža milosti posvetoval s teboj, izmed dveh kerubov, ki sta nad skrinjo pričevanja, izmed vseh stvari, ki jih bom dal tebi v zapoved Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Naredil boš tudi mizo iz akacijevega lesa. Dva komolca naj bo njena dolžina in komolec njena širina ter komolec in pol njena višina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Prekril jo boš s čistim zlatom in k temu naokoli naredil krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Naokoli ji boš naredil rob, za roko širok in k njenemu robu naokoli boš naredil zlato krono.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Zanjo boš naredil štiri zlate obroče iz zlata in obroče vstavil v štiri vogale, ki so na njenih štirih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Nasproti robu bodo obroči za prostor drogovoma, za prenašanje mize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Drogova boš naredil iz akacijevega lesa in ju prevlekel z zlatom, da bo z njima miza lahko prenašana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, '§ Naredil boš njene sklede in njene žlice in njene pokrove in njene skledice, da [jo] s tem pokriješ. Iz čistega zlata jih boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Na mizi boš pred menoj nenehno postavljal hlebe navzočnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Naredil boš svečnik iz čistega zlata. Iz kovanega dela bo svečnik narejen. Njegovo držalo, njegove veje, njegove skledice, njegovi popki in njegovi cvetovi bodo iz istega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Šest vej naj izhaja iz njegovih strani; tri veje iz svečnika iz ene strani in tri veje iz svečnika iz druge strani;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, '§ tri skledice, narejene podobne mandljem, s popkom in cvetom na eni veji; in tri skledice, narejene podobne mandljem, na drugi strani, s popkom in cvetom. Na takšen način na šestih vejah, ki izhajajo iz svečnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na svečniku naj bodo štiri skledice narejene podobne mandljem, z njihovimi popki in njihovimi cvetovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Tam bo popek pod dvema vejama iz istega in popek pod dvema vejama iz istega in popek pod dvema vejama iz istega, glede na šest vej, ki izhajajo iz svečnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Njihovi popki in njihove veje bodo iz istega. Vse to bo eno kovano delo iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Naredil boš sedem njegovih svetilk in te bodo osvetljevale njegove svetilke, da mu bodo lahko nasproti dajale svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Njegovi utrinjači in pladnji za utrinke naj bodo iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Iz talenta čistega zlata bo to naredil, z vsemi temi posodami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Glej, da jih narediš po njihovem vzorcu, ki ti je bil pokazan na gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Poleg tega boš naredil šotorsko svetišče z desetimi zavesami iz sukane tančice in modre in vijolične in škrlatne. S kerubi spretne izdelave jih boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Dolžina ene zavese naj bo osemindvajset komolcev in širina ene zavese štiri komolce. Vsaka izmed zaves bo imela eno mero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pet zaves bo spojeno skupaj druga k drugi, in drugih pet zaves bo spojenih skupaj druga k drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Naredil boš zanke iz modrega na robu prve zavese od zarobitve v spoju, in enako boš storil na najbolj oddaljenem delu druge zavese, na spoju druge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Petdeset zank boš naredil na eni zavesi in petdeset zank boš naredil na robu zavese, ki je na spoju druge, da bodo zanke lahko držale ena drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Naredil boš petdeset zaponk iz zlata in zavese spojil skupaj z zaponkami, in to bo eno šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Naredil boš zavese iz kozje dlake, da bodo pokrivalo nad šotorskim svetiščem. Enajst zaves boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Dolžina ene zavese bo trideset komolcev in širina ene zavese štiri komolce. Vseh enajst zaves bo ene mere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Pet zaves boš spojil posebej in šest zaves posebej in šesto zaveso boš prepognil v sprednjem delu šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Naredil boš petdeset zank na robu prve zavese, ki je skrajna na spoju in petdeset zank na robu zavese, ki spaja drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Naredil boš petdeset zaponk iz brona in zaponke položil v zanke in šotor spojil skupaj, da bo lahko eno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Ostanek, ki preostane od šotorskih zaves, polovica zavese, ki preostaja, bo visela preko zadnje strani šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Komolec na eni strani in komolec na drugi strani tega kar preostaja v dolžini zaves šotora, to bo viselo prek strani šotorskega svetišča na tej strani in na oni strani, da ga pokrije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, '§ Naredil boš pokrivalo za šotor iz rdeče barvanih ovnovih kož in gornje pokrivalo iz jazbečevih kož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Naredil boš pokonci stoječe deske za šotorsko svetišče iz akacijevega lesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Deset komolcev naj bo dolžina deske, komolec in pol pa naj bo širina ene deske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dva zatiča naj bosta na eni deski, urejena v vrstnem redu, drug proti drugemu; tako boš naredil za vse deske šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Naredil boš deske za šotorsko svetišče, dvajset desk na južni strani, proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Pod dvajsetimi deskami boš naredil štirideset podstavkov iz srebra; dva podstavka pod eno desko za njena dva zatiča in dva podstavka pod drugo desko za njena dva zatiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Za drugo stran šotorskega svetišča, na severni strani, bo dvajset desk');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'in njihovih štirideset podstavkov iz srebra; dva podstavka pod eno desko in dva podstavka pod drugo desko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Za strani šotorskega svetišča proti zahodu boš naredil šest desk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Dve deski boš naredil za vogala šotorskega svetišča na dveh straneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Spodaj bosta spojeni skupaj in skupaj bosta spojeni nad glavo v en obroč. Tako bo to za oba; tako bosta za dva vogala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Osem desk bo in njihovi podstavki iz srebra, šestnajst podstavkov; dva podstavka pod eno desko in dva podstavka pod drugo desko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Naredil boš zapahe iz akacijevega lesa; pet za deske ene strani šotorskega svetišča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'in pet zapahov za deske druge strani šotorskega svetišča in pet zapahov za deske strani šotorskega svetišča, za dve strani proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Srednji zapah v sredi desk naj sega od konca do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Deske boš prevlekel z zlatom in njene obroče naredil iz zlata za prostore za zapahe in zapahe boš prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Vzdignil boš šotorsko svetišče glede na ta način, ki ti je bil pokazan na gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Naredil boš zagrinjalo iz modre, vijolične, škrlatne in sukane tančice spretne izdelave; s kerubi bo to narejeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Obesil jo boš na štiri stebre iz akacijevega lesa, prevlečene z zlatom. Njihovi kavlji bodo iz zlata, na štirih podstavkih iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Zagrinjalo boš obesil pod zaponke, da boš lahko prinesel tja, znotraj zagrinjala, skrinjo pričevanja. Zagrinjalo vam bo razdelilo med svetim krajem in najsvetejšim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Sedež milosti boš položil na skrinjo pričevanja v najsvetejšem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Mizo boš postavil zunaj zagrinjala in svečnik nasproti mizi na južni strani šotorskega svetišča in mizo boš postavil na severno stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Naredil boš tanko preprogo za vrata šotora iz modre, vijolične, škrlatne in sukane tančice, izdelane z vezenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Za tanko preprogo boš naredil pet stebrov iz akacijevega lesa in jih prevlekel z zlatom in njihovi kavlji bodo iz zlata, in zanje boš ulil pet podstavkov iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Naredil boš oltar iz akacijevega lesa, pet komolcev dolg in pet komolcev širok. Oltar naj bo štirioglat. Njegova višina naj bo tri komolce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Iz istega boš naredil rogove na njegovih štirih vogalih. Njegovi rogovi bodo iz istega, prekril pa ga boš z bronom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Zanj boš naredil ponve, da sprejmejo pepel, lopate, umivalnike, kavlje za meso in ponve za žerjavico. Vse posode boš naredil iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Zanj boš naredil mrežasto rešetko iz brona in na mreži boš naredil štiri bronaste obroče na njenih štirih vogalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Položil jo boš spodaj, pod obod oltarja, da bo mreža lahko celo do srede oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Naredil boš drogova za oltar, drogova iz akacijevega lesa in ju prevlekel z bronom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Drogova naj bosta vstavljena v obroče in drogova naj bosta na dveh straneh oltarja, da se ga nosi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Votlega z deskami ga boš naredil; kakor ti je bilo pokazano na gori, tako naj ga napravijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Naredil boš dvor šotorskega svetišča; za južno stran, proti jugu, tam naj bodo tanke preproge za dvor iz sukane tančice, sto komolcev dolge za eno stran');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'in njenih dvajset stebrov in njihovih dvajset podstavkov naj bo iz brona. Kavlji stebrov in njihovi okrasni trakovi naj bodo iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Podobno naj bodo za severno stran po dolžini tanke preproge, sto komolcev dolge in njegovih dvajset stebrov in njihovih dvajset podstavkov iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Za širino dvora na zahodni strani naj bodo tanke preproge petdesetih komolcev; deset njihovih stebrov in deset njihovih podstavkov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Širina dvora na vzhodni strani, proti vzhodu, naj bo petdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Tanke preproge ene strani velikih vrat naj bo petnajst komolcev; trije njeni stebri in trije njihovi podstavki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Na drugi strani naj bodo tanke preproge petnajstih komolcev. Trije njeni stebri in trije njihovi podstavki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Za velika vrata dvora naj bo tanka preproga dvajsetih komolcev iz modre, vijolične, škrlatne in sukane tančice, izdelane z vezenjem; in njihovi stebri naj bodo štirje in štirje njihovi podstavki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Vsi stebri okoli dvora naj bodo okrašeni s srebrom. Njihovi kavlji naj bodo iz srebra, njihovi podstavki pa iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Dolžina dvora naj bo sto komolcev in širina vsepovsod petdeset in višina pet komolcev iz sukane tančice, njihovi podstavki pa iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Vse posode šotorskega svetišča v vsej njegovi službi in vsi njegovi količki in vsi količki dvora, naj bodo iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Izraelovim otrokom pa boš zapovedal, da ti prinesejo čistega olja, iz stolčenih oliv, za svetlobo, da bi svetilka vedno gorela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'V šotorskem svetišču skupnosti, zunaj zagrinjala, ki je pred pričevanjem, jo bodo Aron in njegovi sinovi urejali od večera do jutra pred Gospodom. To naj bo zakon na veke njihovim rodovom v imenu Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'K sebi si vzemi svojega brata Arona in njegove sinove z njim, izmed Izraelovih otrok, da mi bo lahko služil v duhovniški službi, torej Arona, Nadába, Abihúja, Eleazarja in Itamárja, Aronove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Naredil boš sveta oblačila za svojega brata Arona, za slavo in za lepoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Govoril boš vsem, ki so modrega srca, ki sem jih napolnil z duhom modrosti, da bodo lahko naredili Aronove obleke, da ga posvetijo, da mi bo lahko služil v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'To so obleke, ki jih bodo naredili: naprsnik, efód, svečano oblačilo in izvezen plašč, turban in pas. Naredili bodo sveta oblačila za tvojega brata Arona in njegove sinove, da mi bo lahko služil v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Vzeli bodo zlato, modro, vijolično, škrlatno in tanko laneno platno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Naredili bodo efód iz zlata, iz modre in iz vijolične, iz škrlatne in sukane tančice s spretno izdelavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Ta bo imel dva svoja obramna dela spojena pri dveh njegovih robovih; in tako bo to spojeno skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Skrbno narejen pas efóda, ki je na njem, bo iz istega, glede na njegovo delo. Celo iz zlate, iz modre, vijolične, škrlatne in sukane tančice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Vzel boš dva oniksova kamna in nanju vrezal imena Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Šest izmed njihovih imen na en kamen in drugih šest imen preostalih na drug kamen, glede na njihovo rojstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Z delom graverja v kamen, podobnemu gravuram pečata, boš dva kamna vgraviral z imeni Izraelovih otrok. Naredil ju boš, da bosta postavljena v ležišči iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Dva kamna boš položil na ramena efóda za kamna spomina Izraelovim otrokom, in Aron bo njihova imena nosil pred Gospodom na svojih dveh ramenih v spomin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Naredil boš ležišči iz zlata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'in dve verižici iz čistega zlata na koncih; iz spletenega dela ju boš naredil in spletene verižice boš pritrdil k ležiščema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Naprsnik sodbe boš naredil s spretno izdelavo; glede na delo efóda ga boš naredil; iz zlata, iz modre, iz vijolične, iz škrlatne in iz sukane tančice ga boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Ta naj bo štirioglat, prepognjen. Pedenj naj bo njegova dolžina in pedenj naj bo njegova širina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, '§ Na njem boš postavil postavitev kamnov, torej štiri vrste kamnov. Prva vrsta naj bo sardij, topaz in granat. To naj bo prva vrsta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, '§ Druga vrsta naj bo smaragd, safir in diamant.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Tretja vrsta hijacint, ahat in ametist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, '§ Četrta vrsta beril, oniks in jaspis. Vstavljeni naj bodo v zlato v njihovih obdanostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Kamni naj bodo z imeni Izraelovih otrok, dvanajst, glede na njihova imena, podobno gravuram pečata; vsak s svojim imenom naj bodo glede na dvanajst rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Na krajeh naprsnika boš naredil verižici iz spletenega dela, iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Na naprsniku boš naredil dva obročka iz zlata in dva obročka boš vstavil na dva konca naprsnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Dve spleteni verižici iz zlata boš vstavil v dva obročka, ki sta na krajeh naprsnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Druga dva konca dveh spletenih verižic boš pritrdil v dve ležišči in ju pripel na obramna dela efóda pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Naredil boš dva obročka iz zlata in ju položil na dva konca naprsnika v njegov rob, ki je na notranji strani efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Naredil boš dva druga obročka iz zlata in ju položil na dve strani pod efód, proti njegovemu prednjemu [delu], nasproti drugemu njegovemu spoju, nad skrbno narejenim pasom efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Naprsnik bodo z njegovimi obročki z modrim trakom privezali k obročkom efóda, da bo ta lahko nad skrbno narejenim pasom efóda in da naprsnik ne bo odvezan od efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Aron naj nosi imena Izraelovih otrok na naprsniku sodbe, na svojem srcu, ko gre v sveti kraj, v nenehen spomin pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Na naprsnik sodbe boš položil Urím in Tumím in ta dva bosta na Aronovem srcu, ko vstopa pred Gospoda in Aron naj sodbo Izraelovih otrok nenehno nosi na svojem srcu pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Naredil boš svečano oblačilo efóda, celotno iz modrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Na vrhu le-tega naj bo luknja v njegovi sredi. Naj ima vezenje iz spletenega dela naokoli njegove luknje, kakor če bi bila luknja brezrokavne verižne srajce, da ta ne bo raztrgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Spodaj, na njegovem obšivu, boš naredil granatna jabolka iz modre in iz vijolične in iz škrlata, naokoli njegovega obšiva; in zvončke iz zlata naokoli med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Zlat zvonček in granatno jabolko, zlat zvonček in granatno jabolko, na obšivu naokoli svečanega oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'In to naj bo na Aronu, da služi, in njegov zvok bo slišati, ko vstopa v sveti kraj pred Gospoda in ko prihaja ven, da ne umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Naredil boš tablico iz čistega zlata in nanjo vgraviral SVETO Gospodu, podobno gravuram pečata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Položil jo boš na moder trak, da bo ta lahko na turbanu; ta bo na sprednjem delu turbana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Ta bo na Aronovem čelu, da bo Aron lahko nosil krivičnost svetih stvari, ki jih bodo Izraelovi otroci posvečevali v vseh svojih svetih darilih, in ta naj bo vedno na njegovem čelu, da bodo lahko sprejeti pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Izvezel boš plašč iz tankega lanenega platna in naredil boš turban iz tankega lanenega platna in naredil boš pas iz vezenine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Za Aronove sinove boš naredil plašče in zanje boš naredil pasove in klobučke boš naredil zanje, za slavo in za lepoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Položil jih boš na svojega brata Arona in njegove sinove z njim. Mazilil jih boš in jih uméstil in posvétil, da mi bodo lahko služili v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Naredil jim boš kratke platnene hlače, da pokrijejo svojo nagoto. Segale bodo od ledij celo do stegna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'in bodo na Aronu in na njegovih sinovih, ko pridejo v šotorsko svetišče skupnosti ali ko pridejo blizu k oltarju, da služijo na svetem kraju, da ne nosijo krivičnosti in ne umrejo. To naj bo za vedno zakon njemu in njegovemu semenu za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'To je stvar, ki jim jo boš storil, da jih posvetiš, da mi opravljajo službo duhovnika. Vzemi enega mladega bikca in dva ovna brez pomanjkljivosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'nekvašen kruh in nekvašene kolače, umešane z oljem in nekvašene vaflje, pomazane z oljem; iz pšenične moke jih boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Položil jih boš v eno košaro in prinesel v košari, z bikcem in dvema ovnoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Arona in njegove sinove boš privedel k vratom šotorskega svetišča skupnosti in jih umil z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Vzel boš obleke in na Arona nadel plašč, svečano oblačilo efóda, efód in naprsnik ter ga opasal s skrbno narejenim pasom efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Na njegovo glavo boš položil turban in na turban boš položil sveto krono.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Potem boš vzel mazilno olje in ga izlil na njegovo glavo ter ga mazilil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Privedel boš njegove sinove in nanje nadel plašče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Opasal jih boš s pasovi, Arona in njegove sinove in nanje položil klobučke in duhovniška služba bo njihova po večnem zakonu, in uméstil boš Arona in njegove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Bikca boš dal privesti pred šotorsko svetišče skupnosti in Aron in njegovi sinovi bodo svoje roke položili bikcu na glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Bikca boš zaklal pred Gospodom, pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Vzel boš kri bikca in jo s svojim prstom pomazal na oltarne rogove in vso kri izlij poleg vznožja oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Vzel boš vso tolščo, ki pokriva drobovje, in opno, ki je nad jetri in dve ledvici in tolščo, ki je na njiju in jih sežgi na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Toda meso bikca, njegovo kožo in njegov iztrebek boš zunaj tabora sežgal z ognjem. To je daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Vzel boš tudi enega ovna in Aron in njegovi sinovi bodo svoje roke položili na ovnovo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Zaklal boš ovna in vzel boš njegovo kri in jo poškropil naokoli nad oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Ovna boš nasekal na kose in opral njegovo drobovje in njegove noge in jih položil k njegovim kosom in k njegovi glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Vsega ovna boš sežgal na oltarju. To je žgalna daritev Gospodu. To je prijeten vonj, ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'In vzel boš drugega ovna. Aron in njegovi sinovi bodo svoje roke položili na ovnovo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Potem boš ovna zaklal in vzel od njegove krvi in jo položil na konico Aronovega desnega ušesa in na konico desnega ušesa njegovih sinov in na palec njihove desne roke in na palec njihovega desnega stopala in kri boš poškropil naokoli po oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Vzel boš od krvi, ki je na oltarju in od mazilnega olja ter ga poškropil na Arona, na njegove obleke, na njegove sinove in na obleke njegovih sinov z njim, in posvečen bo on, njegove obleke, njegovi sinovi in z njim obleke njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Od ovna boš vzel tudi tolščo, tolsti rep in tolščo, ki pokriva drobovje, opno nad jetri, dve ledvici in tolščo, ki je na njima in desno pleče, kajti to je oven uméstitve,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'in en hleb kruha in en kolač oljnatega kruha in en vafelj iz košare nekvašenega kruha, ki je pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Vse boš položil v Aronove roke in v roke njegovih sinov, in majal jih boš za majalno daritev pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Sprejel jih boš iz njihovih rok in jih sežgal na oltarju za žgalno daritev, v prijeten vonj pred Gospodom. To je daritev, narejena z ognjem Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Vzel boš prsi ovna Aronove uméstitve in to majal za majalno daritev pred Gospodom. To bo tvoj delež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, '§ Prsi majalne daritve in pleče vzdigovalne daritve, ki je majano in ki je vzdignjeno, boš posvétil, od ovna uméstitve, torej od tega, kar je za Arona in od tega kar je za njegove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'To bo Aronovo in njegovih sinov od Izraelovih otrok po zakonu na veke, kajti to je vzdigovalna daritev. To bo vzdigovalna daritev od Izraelovih otrok, od darovanja njihovih mirovnih daritev, torej njihova vzdigovalna daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aronova sveta oblačila bodo [pripadala] njegovim sinovom za njim, da bodo maziljeni v njih in da bodo uméščeni v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'In da jih bo ta sin, ki je namesto njega duhovnik, oblačil sedem dni, ko prihaja v šotorsko svetišče skupnosti, da služi na svetem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Vzel boš ovna uméstitve in na svetem kraju zavrel njegovo meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Aron in njegovi sinovi bodo jedli meso ovna in kruh, ki je v košari, pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, '§ Jedli bodo te stvari, s katerimi je narejena sprava, da jih uméstijo in posvétijo. Toda tujec ne bo jedel od tega, ker so svete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Če bi karkoli, od mesa uméstitve ali od kruha, preostalo do jutra, potem boš preostanek sežgal z ognjem. To ne bo pojedeno, kajti to je sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tako boš storil Aronu in njegovim sinovim, glede na vse stvari, ki sem ti jih zapovedal. Sedem dni jih boš uméščal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Vsak dan boš daroval bikca za spravo za daritev za greh in očistil boš oltar, ko si zanj opravil spravo in mazilil ga boš, da ga posvétiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sedem dni boš delal spravo za oltar in ga posvečeval. To bo oltar najsvetejšega. Karkoli se dotakne oltarja, bo sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Torej to je to, kar boš daroval na oltarju. Dve jagnjeti prvega leta, nenehno dan za dnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Eno jagnje boš daroval zjutraj, drugo jagnje pa boš daroval zvečer,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'in z enim jagnjetom desetinko moke, pomešane s četrtinko vrča iztolčenega olja in četrtinko vrča vina za pitno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Drugo jagnje pa boš daroval zvečer in temu boš storil glede na jutranjo jedilno daritev in glede na to pitno daritev, za prijeten vonj, ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'To bo skozi vaše rodove nenehna žgalna daritev pri vratih šotorskega svetišča skupnosti, pred Gospodom, kjer te bom srečal, da ti tam govorim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Tam se bom srečal z Izraelovimi otroki in šotorsko svetišče bo posvečeno z mojo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Jaz bom šotorsko svetišče skupnosti in oltar posvétil, in jaz bom posvétil tako Arona, kakor njegove sinove, da mi služijo v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Jaz bom prebival med Izraelovi otroci in bom njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Spoznali bodo, da jaz sem Gospod, njihov Bog, ki jih je privedel ven iz egiptovske dežele, da lahko prebivam med njimi. Jaz sem Gospod, njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Naredil boš oltar, da na njem zažgeš kadilo. Iz akacijevega lesa ga boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Komolec bo njegova dolžina in komolec njegova širina; ta bo štirioglat. Dva komolca bo njegova višina. Njegovi rogovi naj bodo iz istega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Prevlekel ga boš s čistim zlatom, njegov vrh, njegove strani naokoli in njegove rogove in naokoli mu boš naredil krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'K njemu boš naredil dva zlata obroča pod njegovo krono, pri njegovih dveh vogalih, na njegovih dveh straneh boš to naredil. To bosta prostora za drogova, da ga z njima prenašajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Drogova boš naredil iz akacijevega lesa in ju prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Položil ga boš pred zagrinjalo, ki je pri skrinji pričevanja, pred sedež milosti, ki je nad pričevanjem, kjer se bom srečeval s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Aron bo na njem vsako jutro zažgal dišeče kadilo. Ko pripravlja svetilke, bo na njem zažgal kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Ko Aron zvečer prižge svetilke, bo na njem zažgal kadilo, neprestano kadilo pred Gospodom skozi vaše rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Na njem ne boste darovali nobenega tujega kadila, niti žgalne daritve, niti jedilne daritve, niti nanj ne boste izlili pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Aron bo enkrat letno opravil spravo na njegovih rogovih, s krvjo spravnih daritev za greh. Enkrat letno bo na njem opravil spravo skozi vaše rodove. To je najsvetejše Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '»Ko popišeš glave Izraelovih otrok, po njihovem številu, potem bodo dali, vsak človek, odkupnino za svojo dušo Gospodu, ko jih preštevaš; da med njimi ne bo nobene nadloge, ko jih ti preštevaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'To bodo dali, vsak, kdor preide med tiste, ki so prešteti, polovico šekla po svetiščnem šeklu (šekel je dvajset ger); polovica šekla bo dar Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Vsak, kdor preide med tiste, ki so prešteti, od dvajset let starih in navzgor, bo dal dar Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bogati ne bodo dali več in revni ne bodo dali manj kot polovico šekla, ko dajo dar Gospodu, da opravijo spravo za svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Vzel boš spravni denar Izraelovih otrok in ga določil za službo šotorskega svetišča skupnosti, da bo to lahko spomin Izraelovim otrokom pred Gospodom, da opravijo spravo za vaše duše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '»Naredil boš tudi [okrogel] bronast umivalnik in njegovo vznožje prav tako iz brona, da se s tem umivajo. To boš položil med šotorsko svetišče skupnosti in oltar in vanj boš dal vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Kajti Aron in njegovi sinovi bodo tam umivali svoje roke in svoja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Ko gredo v šotorsko svetišče skupnosti, se bodo umili z vodo, da ne umrejo; ali ko pridejo blizu k oltarju, da služijo, da sežgejo ognjeno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Tako bodo umivali svoje roke in svoja stopala, da ne umrejo. To bo zanje zakon na veke, torej njemu in njegovemu semenu skozi njihove rodove.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Poleg tega je Gospod spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '»K sebi vzemi tudi glavne dišave, od čiste mire petsto šeklov, od prijetnega cimeta polovico toliko, torej dvesto petdeset šeklov, od sladkega kolmeža dvesto petdeset šeklov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'od kasije petsto šeklov, po svetiščnem šeklu in od olivnega olja vrč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Naredil boš olje svetega mazila, mazilo zmešano po lekarnarski umetnosti. To bo sveto mazilno olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'S tem boš mazilil šotorsko svetišče skupnosti, skrinjo pričevanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'mizo in vse njene posode, svečnik in njegove posode, kadilni oltar,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'oltar žgalne daritve z vsemi njegovimi posodami ter [okrogel] umivalnik in njegovo vznožje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Posvétil jih boš, da bodo lahko najsvetejše. Karkoli se jih dotakne, bo sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Mazilil boš Arona in njegove sinove in jih posvéti, da mi bodo lahko služili v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Izraelovim otrokom boš govoril, rekoč: ›To mi bo sveto mazilno olje skozi vaše rodove.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Na človeško meso naj ne bo izlito niti ne boste naredili kateregakoli drugega po njegovi sestavi podobnega temu. To je sveto in to vam bo sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Kdorkoli zmeša karkoli podobnega temu, ali kdorkoli karkoli od tega položi na tujca, bo torej iztrebljen izmed svojega ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Gospod je rekel Mojzesu: »K sebi vzemi prijetne dišave, dišečo smolo, kadilno školjko in galban; te prijetne dišave s čistim kadilom. Od vsakega bo tam podobna teža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Naredil boš dišavo, dišečino po lekarnarski umetnosti, umešano skupaj, čisto in sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Nekaj od tega boš zelo drobno stolkel in to položil pred pričevanje v šotorskem svetišču skupnosti, kjer se bom srečeval s teboj. To ti bo najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Glede na dišavo, ki jo boš naredil, si jo sebi ne boste delali glede na njeno sestavo. Ta ti bo sveta za Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Kdorkoli bo naredil podobno temu, da jo voha, bo torej iztrebljen izmed svojega ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '»Poglej, po imenu sem poklical Becaléla, Urijájevega sina, Hurovega sina, iz Judovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Napolnil sem ga z Božjim duhom, v modrosti, v razumnosti, v znanju in v vseh vrstah rokodelstva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'da snuje spretna dela, da dela z zlatom, s srebrom, z bronom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'in v rezanju kamnov, da se jih vdela in v rezbarjenju lesa, da dela v vseh vrstah rokodelstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Glej, jaz sem dal z njim Oholiába, Ahisamáhovega sina, iz Danovega rodu, in v srca vseh tistih, ki so modrega srca, sem položil modrost, da bodo lahko naredili vse to, kar sem ti zapovedal:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'šotorsko svetišče skupnosti, skrinjo pričevanja, sedež milosti, ki je na njem, vso opremo šotorskega svetišča,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'mizo in njeno opremo, čisti svečnik z vso njegovo opremo, kadilni oltar,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'oltar žgalne daritve z vso njegovo opremo, [okrogel] umivalnik in njegovo vznožje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'službene obleke in sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'ter mazilno olje in dišeče kadilo za sveti kraj. Storili bodo glede na vse to, kar sem ti zapovedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '»Govori tudi Izraelovim otrokom, rekoč; ›Resnično, ohranjali boste moje šabate, kajti to je znamenje med menoj in vami skozi vaše rodove, da boste vi lahko vedeli, da jaz sem Gospod, ki vas posvečujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Zato boste ohranjali šabat, kajti ta vam je svet. Vsak kdor ga omadežuje, ta bo zagotovo usmrčen, kajti kdorkoli v njem dela kakršnokoli delo, ta duša bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Šest dni naj se opravlja delo, toda na sedmi je šabatni počitek, sveto Gospodu. Kdorkoli na šabatni dan počne kakršno koli delo, bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Zatorej bodo Izraelovi otroci ohranjali šabat, da šabat obeležujejo skozi njihove rodove za večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'To je znamenje med menoj in Izraelovimi otroki na veke, kajti v šestih dneh je Gospod naredil nebo in zemljo in na sedmi dan je počival in bil osvežen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Mojzesu je dal, ko je z njim končal posvetovanje na gori Sinaj, dve plošči pričevanja, kamniti plošči, popisani z Božjim prstom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Ko je ljudstvo videlo, da je Mojzes odlašal priti dol z gore, se je ljudstvo skupaj zbralo k Aronu in mu reklo: »Vstani, naredi nam bogove, ki bodo šli pred nami, kajti glede tega Mojzesa, človeka, ki nas je privedel iz egiptovske dežele, ne vemo kaj je nastalo iz njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aron jim je rekel: »Izdrite zlate uhane, ki so v ušesih vaših žena, vaših sinov in vaših hčera in jih prinesite k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Vse ljudstvo je izdrlo zlate uhane, ki so bili v njihovih ušesih in jih prineslo k Aronu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Ta jih je prejel iz njihove roke in to oblikoval z rezbarskim orodjem, potem ko je naredil ulito tele, in rekli so: »To so tvoji bogovi, oh Izrael, ki so te privedli iz egiptovske dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Ko je Aron to videl, je pred njim zgradil oltar in Aron je naredil razglas ter rekel: »Jutri je praznovanje Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Naslednji dan so zgodaj vstali, darovali žgalne daritve in prinesli mirovne daritve in ljudstvo se je usedlo, da jé in da pije in vstalo, da se zabava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Gospod je rekel Mojzesu: »Pojdi, stopi dol, kajti tvoje ljudstvo, ki si ga privedel iz egiptovske dežele, se je izpridilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Hitro so se obrnili stran iz poti, ki sem jim jo zapovedal. Naredili so si ulito tele, ga oboževali, mu žrtvovali in rekli: ›To so tvoji bogovi, oh Izrael, ki so te privedli gor iz egiptovske dežele.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Gospod je rekel Mojzesu: »Videl sem to ljudstvo in glej, to je trdovratno ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Zdaj me torej pusti samega, da se moj bes razvname zoper njih in da jih lahko použijem. Iz tebe pa bom naredil velik narod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mojzes je rotil Gospoda, svojega Boga in rekel: » Gospod, zakaj se tvoj bes razvnema zoper tvoje ljudstvo, ki si ga privedel iz egiptovske dežele z veliko močjo in z mogočno roko?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Zakaj bi Egipčani govorili in rekli: ›Zaradi zla jih je privedel ven, da jih ubije na gorah in da jih použije iz obličja zemlje?‹ Obrni se od svojega krutega besa in se pokesaj glede tega zla zoper svoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Spomni se Abrahama, Izaka in Izraela, svojih služabnikov, ki si jim prisegel pri samem sebi in jim rekel: ›Vaše seme bom pomnožil kakor zvezd neba in vso to deželo, o kateri sem govoril, bom dal tvojemu semenu in podedovali jo bodo na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Gospod se je pokesal glede zla, ki ga je mislil storiti svojemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mojzes se je obrnil in odšel dol z gore in v njegovi roki sta bili dve plošči pričevanja. Plošči sta bili popisani na obeh njunih straneh; na eni strani in na drugi sta bili popisani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Plošči sta bili Božje delo in pisanje je bilo pisanje od Boga, vgravirano na plošči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Ko je Józue slišal hrup ljudstva, medtem ko so kričali, je Mojzesu rekel: » Tam, v taboru, je vojni hrup.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Ta je rekel: » To ni glas tistih, ki vpijejo zaradi zmage niti to ni glas tistih, ki vpijejo, ker so bili premagani, temveč slišim hrup tistih, ki pojejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Takoj ko je prišel blizu tabora, se je pripetilo, da je zagledal tele in ples. Mojzesova jeza se je vnela, tabli je vrgel iz svojih rok ter ju zlomil pod goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Vzel je tele, ki so ga naredili, ga sežgal v ognju, ga zmlel v prah in ga posul nad vodo in Izraelove otroke primoral, da so pili od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Mojzes je Aronu rekel: »Kaj ti je storilo to ljudstvo, da si nadnje privedel tako velik greh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aron je rekel: »Ne dopusti, da se razvname jeza mojega gospoda. Ti poznaš ljudstvo, da so postavljeni v zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Kajti rekli so mi: ›Naredi nam bogove, ki bodo šli pred nami, kajti glede tega Mojzesa, človeka, ki nas je privedel iz egiptovske dežele, ne vemo kaj je nastalo iz njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Rekel sem jim: ›Kdorkoli ima kakršnokoli zlato, naj ga izdere.‹ Tako so ga dali meni. Potem sem ga vrgel v ogenj in izšlo je to tele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, '§ Ko je Mojzes videl, da je bilo ljudstvo nago, (kajti Aron jih je storil nage v njihovo sramoto med njihovimi sovražniki)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'potem je Mojzes stal v velikih vratih tabora in rekel: »Kdo je na Gospodovi strani? Naj pride k meni.« In k njemu so se zbrali vsi sinovi Lévijevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Rekel jim je: »Tako govori Gospod, Izraelov Bog: ›Vsak mož naj svoj meč pripaše k svoji strani in gre noter in ven, od velikih vrat do velikih vrat, skozi tabor in naj vsak mož ubije svojega brata in vsak mož svojega družabnika in vsak mož svojega bližnjega.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Otroci Lévijevcev so storili glede na Mojzesovo besedo in tam je ta dan izmed ljudstva padlo okoli tri tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Kajti Mojzes je rekel: »Uméstite se danes Gospodu, celo vsak mož za svojega sina in za svojega brata, da lahko ta dan nad vas podeli blagoslov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Naslednji dan se je pripetilo, da je Mojzes rekel ljudstvu: »Zagrešili ste velik greh. Sedaj bom šel gor h Gospodu, morda bom storil spravo za vaš greh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Mojzes se je vrnil h Gospodu ter rekel: »Oh, to ljudstvo je zagrešilo velik greh in si naredilo bogove iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Vendar sedaj, če hočeš odpusti njihov greh ― in če ne, me izbriši, prosim te, iz svoje knjige, ki si jo napisal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Gospod je rekel Mojzesu: »Kdorkoli je grešil zoper mene, tistega bom izbrisal iz svoje knjige.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Zato sedaj pojdi, vodi ljudstvo na kraj, o katerem sem ti govoril. Glej, moj Angel bo šel pred teboj. Kljub temu bom na dan, ko obiščem, obiskal njihov greh na njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Gospod je trpinčil ljudstvo, ker so naredili tele, ki ga je naredil Aron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Gospod je rekel Mojzesu: »Odpravi se in pojdi od tod gor, ti in ljudstvo, ki si ga privedel gor iz egiptovske dežele, v deželo, ki sem jo prisegel Abrahamu, Izaku in Jakobu, rekoč: ›Tvojemu semenu jo bom dal,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'jaz pa bom pred teboj poslal angela, in jaz bom napodil Kánaanca, Amoréjca in Hetejca in Perizéjca, Hivéjca in Jebusejca');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'v deželo, kjer tečeta mleko in med, kajti jaz ne bom šel gor v tvoji sredi, kajti trdovratno ljudstvo si, da te na poti ne použijem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Ko je ljudstvo slišalo te zle vesti, je žalovalo in noben človek si nase ni nadel ornamentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Kajti Gospod je rekel Mojzesu: »Reci Izraelovim otrokom: ›Vi ste trdovratno ljudstvo. V trenutku bom prišel v tvojo sredo in te použil, zato sedaj iz sebe odloži svoje ornamente, da lahko vem, kaj ti storiti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Izraelovi otroci so se pri gori Horeb ogolili svojih ornamentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mojzes je vzel šotorsko svetišče in ga postavil zunaj tabora, daleč od tabora ter ga imenoval Šotorsko svetišče skupnosti. In pripetilo se je, da kdorkoli je iskal Gospoda, je odšel k šotorskemu svetišču skupnosti, ki je bil zunaj tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Pripetilo se je, ko je Mojzes šel ven v šotorsko svetišče, da je vse ljudstvo vstalo in vsak mož je stal pri vratih svojega šotora in gledal za Mojzesom, dokler ta ni odšel v šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Ko je Mojzes vstopil v šotorsko svetišče, se je pripetilo, [da] se je spustil oblačen steber in stal pri vratih šotorskega svetišča in Gospod je govoril z Mojzesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Vse ljudstvo je videlo oblačen steber stati pri vratih šotorskega svetišča, in vse ljudstvo je vstalo in oboževalo, vsak mož pri vratih svojega šotora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Gospod je govoril Mojzesu iz obličja v obličje, kakor človek govori svojemu prijatelju. In ponovno se je napotil v tabor, toda njegov služabnik, Nunov sin Józue, mladenič, ni odšel iz šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Mojzes je rekel Gospodu: »Glej, praviš mi: ›Privedi to ljudstvo gor,‹ pa mi nisi dal spoznati koga hočeš poslati z menoj. Vendar si rekel: ›Poznam te po imenu in tudi milost si našel v mojih očeh.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Zdaj torej, prosim te, če sem našel milost v tvojih očeh, pokaži mi torej svojo pot, da te lahko spoznam, da lahko najdem milost v tvojih očeh. Preudari, da je ta narod tvoje ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'In on je rekel: »Moja prisotnost bo šla s teboj in jaz ti bom dal počitek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Rekel mu je: »Če tvoja prisotnost ne gre z menoj, nas ne odvedi tja gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Kajti v čem bo to znano tukaj, da smo jaz in tvoje ljudstvo našli milost v tvojih očeh? Mar ni to v tem, da hodiš z nami? Tako bomo ločeni, jaz in tvoje ljudstvo, od vseh ljudstev, ki so na obličju zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Gospod je rekel Mojzesu: »Storil bom tudi to stvar, ki si jo govoril, kajti našel si milost v mojih očeh in jaz te poznam po imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Ta je rekel: »Rotim te, pokaži mi svojo slavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'In on je rekel: »Vsej svoji dobroti bom storil iti pred teboj in razglašal bom Gospodovo ime pred teboj in milostljiv bom, komur hočem biti milostljiv in usmiljenje bom pokazal na tistem, na komer hočem pokazati usmiljenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Rekel je: »Ne moreš videti mojega obličja, kajti noben človek me ne bo videl in živel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Gospod je rekel: »Glej, tukaj je prostor pri meni in ti boš stopil na skalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Zgodilo se bo, medtem ko gre moja slava mimo, da te bom postavil v skalno pečino in s svojo roko te bom pokril, medtem ko grem mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'In odstranil bom svojo roko in videl boš moje zadnje dele, toda mojega obličja ne bo videti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Gospod je rekel Mojzesu: »Izsekaj si dve kamniti plošči, podobni prvima, in na ti plošči bom napisal besede, ki so bile na prvih ploščah, ki si ju razbil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Zjutraj bodi pripravljen in zjutraj pridi gor na goro Sinaj in se mi pokaži tam, na vrhu gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Noben človek ne bo prišel gor s teboj niti naj noben človek ne bo viden po vsej gori. Naj se niti tropi, niti črede ne pasejo pred to goro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'In izklesal je dve kamniti plošči, podobni prvima dvema. Mojzes je vstal zgodaj zjutraj in odšel na goro Sinaj, kakor mu je zapovedal Gospod in v svojo roko vzel dve kamniti plošči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Gospod se je spustil v oblaku in tam stal z njim in razglasil Gospodovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Gospod je šel mimo, pred njim in razglasil: » Gospod, Gospod Bog, usmiljen in milostljiv, potrpežljiv in obilen v dobroti in resnici,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'ki ohranja usmiljenje za tisoče, ki odpušča krivičnost, prestopek in greh in ki nikakor ne bo očistil krivega; ki obiskuje krivičnost očetov na otrocih in na otrok otrocih, do tretjega in četrtega rodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mojzes se je podvizal in svojo glavo sklonil proti zemlji ter oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Rekel je: »Če sem torej našel milost v tvojih očeh, oh Gospod, naj moj Gospod, prosim te, hodi med nami, kajti to je trdovratno ljudstvo. Odpusti našo krivičnost in naš greh in nas vzemi za svojo dediščino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'In on je rekel: »Glej, sklepam zavezo. Pred vsem tvojim ljudstvom bom delal čuda, kakršna še niso bila storjena po vsej zemlji niti v nobenem narodu. Vse ljudstvo, med katerim si, bo videlo Gospodovo delo, kajti to je strašna stvar, ki jo bom storil s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Obeležuj to, kar sem ti danes zapovedal. Glej, pred teboj napodim Amoréjca, Kánaanca, Hetejca, Perizéjca, Hivéjca in Jebusejca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Pazi nase, da ne bi sklenil zaveze s prebivalci dežele, v katero greš, da ti ne bi bili za zanko v tvoji sredi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'temveč boste uničili njihove oltarje, zlomili njihove podobe in posekali njihove ašere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'kajti ne boš oboževal nobenega drugega boga, kajti Gospod, čigar ime je Ljubosumni, je ljubosumen Bog,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'da ne bi sklenil zaveze s prebivalci dežele in bi se oni šli vlačugat s svojimi bogovi in bi žrtvovali svojim bogovom, in bi te nekdo povabil in bi ti jedel od njegove daritve,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'in bi jemal od njihovih hčera za svoje sinove in bi se njihove hčere šle vlačugat za njihovimi bogovi in bi primoral svoje sinove, da se gredo vlačugat za njihovimi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Sebi ne boš izdeloval nobenih ulitih bogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Obeleževal boš praznik nekvašenega kruha. Sedem dni boš jedel nekvašeni kruh, kot sem ti zapovedal, v času meseca abíba, kajti v mesecu abíbu si prišel iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Vse, kar odpre maternico, je moje. Vsak prvenec med tvojo živino, bodisi vol ali ovca, ki je samec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Toda prvenca od osla boš odkupil z jagnjetom. Če pa ga ne odkupiš, potem mu boš zlomil tilnik. Odkupil boš vse prvorojeno izmed svojih sinov. In nihče se ne bo prazen prikazal pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Šest dni boš delal, toda na sedmi dan boš počival; v času oranja in v času žetve boš počival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Obeleževal boš praznovanje tednov, od prvih sadov pšenične žetve in praznovanja spravljanja ob koncu leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trikrat na leto se bodo vsi vaši moški otroci prikazali pred Gospodom Bogom, Izraelovim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Kajti jaz bom pred teboj pregnal narode in razširil tvoje meje. Niti si noben človek ne bo poželel tvoje dežele, kadar boš šel trikrat v letu gor, da se prikažeš pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Krvi moje klavne daritve ne boš daroval s kvasom niti ne bo klavna daritev praznika pashe ostala do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Prvine od prvih sadov svoje zemlje boš prinesel v hišo Gospoda, svojega Boga. Kozlička ne boš kuhal v mleku njegove matere.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Gospod je rekel Mojzesu: »Zapiši te besede, kajti po pomenu teh besed sem sklenil zavezo s teboj in z Izraelom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'In tam je bil z Gospodom štirideset dni in štirideset noči; niti ni jedel kruha niti pil vode. In na tabli je zapisal besede te zaveze, deset zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Pripetilo se je, ko je Mojzes prišel dol z gore Sinaj, z dvema ploščama pričevanja v Mojzesovi roki, ko je prišel dol z gore, da Mojzes ni vedel, da je koža njegovega obraza sijala, medtem ko je govoril z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Ko so Aron in vsi Izraelovi otroci zagledali Mojzesa, glej, koža njegovega obraza je sijala in so se bali priti bliže k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mojzes jim je zaklical in Aron in vsi voditelji skupnosti so se vrnili k njemu, in Mojzes je govoril z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Potem so vsi Izraelovi otroci prišli bliže in v zapoved jim je dal vse, kar je Gospod govoril z njim na gori Sinaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Ko je Mojzes prenehal govoriti z njimi, si je na obraz dal zagrinjalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Toda ko je Mojzes vstopil pred Gospoda, da govori z njim, je odstranil zagrinjalo, dokler ni prišel ven. In prišel je ven in govoril Izraelovim otrokom to, kar mu je bilo zapovedano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Izraelovi otroci so videli Mojzesov obraz, da je Mojzesova koža sijala in Mojzes si je na svoj obraz ponovno namestil zagrinjalo, dokler ni vstopil, da govori z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Mojzes je zbral skupaj vso skupnost Izraelovih otrok ter jim rekel: »To so besede, ki jih je Gospod zapovedal, da naj bi jih vi delali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Šest dni naj bo delo opravljano, toda na sedmi dan naj vam bo sveti dan, šabatni počitek Gospodu. Kdorkoli v njem opravlja delo, bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Vsepovsod po svojih prebivališčih na šabatni dan ne boste prižigali nobenega ognja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mojzes je spregovoril vsej skupnosti Izraelovih otrok, rekoč: »To je stvar, ki jo je zapovedal Gospod, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '›Vzemite izmed vas daritev Gospodu. Kdorkoli je voljnega srca, naj jo prinese, daritev Gospodu: zlato, srebro, bron,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'modro, vijolično, škrlatno in tanko laneno platno, kozjo dlako,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, '§ rdeče barvane ovnove kože, jazbečeve kože, akacijev les,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'olje za svetlobo, dišave za mazilno olje in za dišeče kadilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'oniksove kamne in kamne, da se pripravijo za efód in za naprsnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Vsak, ki je izmed vas modrega srca, bo prišel in storil vse, kar je Gospod zapovedal:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'šotorsko svetišče, njegov šotor in njegovo pokrivalo, njegove zaponke in njegove deske, njegove zapahe, njegove stebre in njegove podstavke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'skrinjo in njena drogova s sedežem milosti in zagrinjalo pokrivala,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'mizo in njena drogova, vse njene posode in hlebe navzočnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'tudi svečnik za svetlobo in njegovo opremo in njegove svetilke z oljem za svetlobo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'in kadilni oltar in njegova drogova, mazilno olje in dišeče kadilo, tanko preprogo za vrata pri šotorskem vhodu šotorskega svetišča,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'oltar žgalne daritve z njegovo bronasto rešetko, njegova drogova in vse njegove posode, [okrogel] umivalnik in njegovo vznožje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'tanke preproge dvora, njegove stebre in njihove podstavke in tanko preprogo za vrata dvora,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'količke šotorskega svetišča, količke dvora in njihove vrvice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'službene obleke, da opravljajo službo na svetem kraju, sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Vsa skupnost Izraelovih otrok je odšla iz Mojzesove prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Prišli so, vsakdo, čigar srce ga je razvnelo in vsakdo, čigar duh ga je storil voljnega in prinesli so Gospodovo daritev h gradnji šotorskega svetišča skupnosti in za vso njegovo službo in za sveta oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Prišli so, tako moški kakor ženske, tako veliko kot jih je bilo voljnega srca in prinesli zapestnice, uhane, prstane, ogrlice, vse dragocenosti iz zlata. Vsak človek, ki je daroval, je daroval daritev zlata Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, '§ Vsak človek, pri katerem je bilo najdeno modro, vijolično, škrlatno in tanko laneno platno, kozja dlaka, rdeča koža ovnov in jazbečeve kože, jih je prinesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Vsak, kdor je daroval daritev srebra in brona, je prinesel Gospodovo daritev. Vsak človek, pri komer se je našel akacijev les za katerokoli delo službe, ga je prinesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Vse ženske, ki so bile modrega srca, so predle s svojimi rokami in prinesle to, kar so napredle, tako iz modrega, iz vijoličnega in iz škrlata in iz tankega lanenega platna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Vse ženske, ki jih je srce razvnelo v modrosti, so predle kozjo dlako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Voditelji so prinesli oniksove kamne in kamne, da se pripravijo za efód in za naprsnik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'dišavo in olje za svetlobo in za mazilno olje in za dišeče kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Izraelovi otroci so prinesli voljno daritev Gospodu, vsak moški in ženska, katerega srce jih je storilo voljne, da prinesejo za vse vrste dela, ki ga je Gospod zapovedal, da bo storjeno po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Mojzes je Izraelovim otrokom rekel: »Glejte, Gospod je po imenu poklical Becaléla, Urijájevega sina, Hurovega sina, iz Judovega rodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'in ga napolnil z Božjim duhom, v modrosti, v razumevanju, v znanju in v vseh vrstah rokodelstva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'in da snuje nenavadna dela, da dela v zlatu, v srebru, v bronu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'v rezanju kamnov, da se jih vdela in v rezbarjenju lesa, da naredi vsake vrste spretno delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'V njegovo srce je položil, da lahko poučuje, tako on in Oholiáb, Ahisamáhov sin, iz Danovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Napolnil ju je s srčno modrostjo, da opravljata vse vrste dela, od graverja do spretnega delavca in od tistega, ki izveze v modri, v vijolični, v škrlatni in v tankem lanenem platnu do tkalca, celó izmed teh, ki opravljajo katerokoli delo in izmed teh, ki snujejo spretno delo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Potem so Becalél in Oholiáb in vsak človek modrega srca, v katerega je Gospod položil modrost in razumevanje, da ve, kako delati vse vrste dela za službo svetišča, izvršili glede na vse, kakor je zapovedal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Mojzes je poklical Becaléla in Oholiába in vsakega človeka modrega srca, v katerega srce je Gospod položil modrost, torej vsakega, ki ga je razvnelo srce, da pride k delu, da ga opravi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'in od Mojzesa so prejeli vso daritev, ki so jo Izraelovi otroci prinesli za delo službe svetišča, da to istočasno opravijo. In k njemu so še vsako jutro prinašali prostovoljne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Prišli so vsi modri možje, ki so opravljali delo pri svetišču, vsak človek od svojega dela, ki so ga opravljali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'in spregovorili Mojzesu, rekoč: »Ljudstvo prinaša veliko več kakor dovolj za delo služenja, ki ga je Gospod zapovedal narediti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Mojzes je dal zapoved in naredili so, da je bila razglašena po taboru, rekoč: »Naj niti moški niti ženska ne opravlja več nobenega dela za darovanje svetišču.« Tako je bilo ljudstvo zadržano od prinašanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Kajti stvari, ki so jih imeli, je bilo zadosti za izvršitev vsega dela in še preveč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Vsak človek modrega srca med njimi, ki opravlja delo šotorskega svetišča, je naredil deset zaves iz sukane tančice, modre, vijolične in škrlatne. S kerubi spretne izdelave jih je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Dolžina ene zavese je bila osemindvajset komolcev in širina ene zavese štiri komolce. Zavese so bile vse ene velikosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Spojil je pet zaves eno k drugi in drugih pet zaves je spojil eno k drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Naredil je zanke iz modre na robu prve zavese od zarobitve v spoju. Podobno je naredil na zadnji strani druge zavese na spoju druge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Petdeset zank je naredil na eni zavesi in petdeset zank je naredil na robu zavese, ki je bila na spoju druge. Zanke so eno zaveso držale k drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Naredil je petdeset zaponk iz zlata in zavese spojil z zaponkami skupaj eno k drugi. Tako je postalo eno šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Naredil je zavese iz kozje dlake za šotor nad šotorskim svetiščem. Naredil je enajst zaves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Dolžina ene zavese je bila trideset komolcev in štiri komolce je bila širina ene zavese. Enajst zaves je bilo ene velikosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Spojil je pet zaves posebej in šest zaves posebej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Naredil je petdeset zank na zadnjem robu zavese na spoju in petdeset zank je naredil na robu zavese, ki spaja drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Naredil je petdeset zaponk iz brona, da šotor spoji skupaj, da bo ta lahko eno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Naredil je pokrivalo za šotor iz rdeče barvanih ovnovih kož in nad tem pokrivalo iz jazbečevih kož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Naredil je deske za šotorsko svetišče iz akacijevega lesa, stoječe pokonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Dolžina deske je bila deset komolcev in širina deske en komolec in pol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Ena deska je imela dva zatiča, enako oddaljena eden od drugega. Tako je naredil za vse deske šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Naredil je deske za šotorsko svetišče; dvajset desk za južno stran, proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Pod dvajsetimi deskami je naredil štirideset podstavkov iz srebra; dva podstavka pod eno desko za njena dva zatiča in dva podstavka pod drugo desko za njena dva zatiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Za drugo stran šotorskega svetišča, ki je proti severnemu vogalu, je naredil dvajset desk');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'in njihovih štirideset podstavkov iz srebra; dva podstavka pod eno desko in dva podstavka pod drugo desko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Za strani šotorskega svetišča proti zahodu je naredil šest desk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Dve deski je naredil za vogala šotorskega svetišča na dveh straneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Spojeni sta bili spodaj in skupaj spojeni pri njegovi glavi v en obroč. Tako je storil obema izmed njiju na obeh vogalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Bilo je osem desk in njihovih podstavkov je bilo šestnajst podstavkov iz srebra, pod vsako desko dva podstavka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Naredil je zapahe iz akacijevega lesa; pet za deske ene strani šotorskega svetišča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'in pet zapahov za deske druge strani šotorskega svetišča in pet zapahov za deske šotorskega svetišča proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Naredil je srednji zapah, da je segal skozi deske od enega konca k drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Deske je prevlekel z zlatom in njihove obroče naredil iz zlata, da bodo postavljeni za zapahe in zapahe je prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Naredil je zagrinjalo iz modre, vijolične, škrlatne in sukane tančice. S kerubi spretne izdelave jih je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'K temu je naredil štiri stebre iz akacijevega lesa in jih prevlekel z zlatom. Njihovi kavlji so bili iz zlata in zanje je ulil štiri podstavke iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Naredil je tanko preprogo za vrata šotorskega svetišča iz modre, vijolične, škrlatne in sukane tančice, iz vezenine;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'in njenih pet stebrov z njihovimi kavlji. Njihove kapitele in njihove okrasne trakove je prevlekel z zlatom, toda njihovih pet podstavkov je bilo iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Becalél je naredil skrinjo iz akacijevega lesa. Dva komolca in pol je bila njena dolžina, komolec in pol njena širina, komolec in pol njena višina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'in jo zunaj in znotraj prevlekel s čistim zlatom in ji naokoli naredil krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, '§ Zanjo je ulil štiri obroče iz zlata, da bi bili vstavljeni pri njenih štirih vogalih; celo dva obroča na eni njeni strani in dva obroča na drugi njeni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Drogova je položil v obroča pri straneh skrinje, za prenašanje skrinje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Naredil je sedež milosti iz čistega zlata. Dva komolca in pol je bila njegova dolžina ter komolec in pol njegova širina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Naredil je dva keruba iz zlata, naredil ju je skovana iz enega kosa, na dveh koncih sedeža milosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'enega keruba na koncu, na tej strani in drugega keruba na drugem koncu, na tisti strani. Iznad sedeža milosti je naredil keruba na dveh njegovih koncih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Keruba sta svoji peruti razprostirala navzgor in s svojimi perutmi pokrivala nad sedežem milosti, s svojima obrazoma drug proti drugemu; torej k sedežu milosti sta bila obraza kerubov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Naredil je mizo iz akacijevega lesa. Dva komolca je bila njena dolžina, komolec njena širina ter komolec in pol njena višina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Prevlekel jo je s čistim zlatom in k temu naokoli naredil krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'K temu je naokoli naredil tudi okvir za širino dlani in naredil krono iz zlata za njen okvir naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Zanjo je ulil štiri obroče iz zlata in jih dal na njene štiri vogale, ki so bili na njenih štirih nogah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Nasproti okvira so bili obroči, prostori za drogova, za prenašanje mize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom, za prenašanje mize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Naredil je posode, ki so bile na mizi, njene sklede, njene žlice, njene skledice in njena pokrivala, da jo z njimi pokrije, iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Naredil je svečnik iz čistega zlata. Iz kovanega dela je naredil svečnik; njegovo držalo in njegovo vejo, njegove skledice, njegove popke in njegove rože so bile iz istega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'In šest mladik, ki so izhajale iz njegovih strani; tri mladike iz svečnika iz ene njegove strani in tri mladike iz svečnika iz druge njegove strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tri skledice je naredil po videzu mandljev iz ene mladike, popek in rožo in tri skledice je naredil podobne mandljem na drugi mladiki, popek in rožo. Tako povsod po šestih mladikah, ki izhajajo iz svečnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Na svečniku so bile štiri skledice narejene podobne mandljem, njegovim popkom in njegovim cvetovom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'popek pod dvema mladikama iz istega in popek pod dvema mladikama iz istega in popek pod dvema mladikama iz istega, glede na šest mladik, izhajajočih iz njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Njihovi popki in njihove veje so bile iz istega. Vse to je bilo eno kovano delo iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Naredil je njegovih sedem svetilk in njegova utrinjala in njegove pladnje za utrinjala iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Iz talenta čistega zlata ga je naredil in vse njegove posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Naredil je kadilni oltar iz akacijevega lesa. Njegova dolžina je bila komolec in njegova širina komolec; bil je štirioglat in dva komolca je bila njegova višina; njegovi rogovi so bili iz istega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Prevlekel ga je s čistim zlatom, tako njegovo površino kot njegove strani naokoli in njegove rogove. Naokoli mu je naredil tudi krono iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Zanj je naredil dva obroča iz zlata pod njegovo krono, pri njegovih dveh vogalih, na njegovih straneh, da bodo prostori za drogova, da ga z njima prenašajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Naredil je sveto mazilno olje in čisto kadilo iz prijetnih dišav, glede na lekarnarjevo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Naredil je oltar žgalne daritve iz akacijevega lesa. Pet komolcev je bila njegova dolžina in pet komolcev njegova širina; bil je štirioglat in tri komolce je bila njegova višina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Naredil je njegove rogove na njegovih štirih vogalih; njegovi rogovi so bili iz istega, in prevlekel jih je z bronom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Naredil je vse oltarne posode, lonce, lopate, umivalnike in kavlje za meso in ponve za žerjavico. Vse njegove posode je naredil iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Za oltar je naredil bronasto mrežasto rešetko pod njegovim obodom, spodaj, v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Ulil je štiri obroče za štiri konce bronaste rešetke, da bodo prostori za drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Naredil je drogova iz akacijevega lesa in ju prevlekel z bronom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Drogova je položil v obroče na straneh oltarja, da ga z njima prenašajo; oltar je naredil votel, z deskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Naredil je [okrogel] bronast umivalnik in njegovo vznožje iz brona, iz zrcal ženskega zbora, ki so se zbirale pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Naredil je dvor. Na južni strani, proti jugu, so bile tanke preproge dvora iz sukane tančice, sto komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Njihovih stebrov je bilo dvajset in dvajset njihovih bronastih podstavkov; kavlji stebrov in njihovi okrasni trakovi so bili iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Za severno stran je bilo tankih preprog sto komolcev, njihovih stebrov je bilo dvajset in dvajset njihovih podstavkov iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Za zahodno stran so bile tanke preproge petdesetih komolcev, deset njihovih stebrov in deset njihovih podstavkov; kavlji stebrov in njihovi okrasni trakovi iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Za vzhodno stran, proti vzhodu, petdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Tankih preprog ene strani velikih vrat je bilo petnajst komolcev; njihovi trije stebri in njihovi trije podstavki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'In za drugo stran velikih vrat dvora, na tej roki in tisti roki, so bile tanke preproge petnajstih komolcev; trije njihovi stebri in trije njihovi podstavki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Vse tanke preproge dvora naokoli so bile iz sukane tančice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Podstavki za stebre so bili iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra in prevleka njihovih kapitelov iz srebra; in vsi stebri dvora so bili okrašeni s srebrom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Tanka preproga za velika dvorna vrata je bilo vezenje iz modre, vijolične, škrlatne in sukane tančice. Dvajset komolcev je bila dolžina in pet komolcev je bilo visoko po širini, primerljivo tankim preprogam dvora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Njihovi stebri so bili štirje in štirje njihovi podstavki iz brona; njihovi kavlji iz srebra in prevleka njihovih kapitelov in njihovih okrasnih trakov iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Vsi količki šotorskega svetišča in dvora naokoli so bili iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'To je seštevek šotorskega svetišča, torej šotorskega svetišča pričevanja, kakor je bilo prešteto glede na Mojzesovo zapoved, za službo Lévijevcev, po roki Itamárja, sina duhovnika Arona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'In Becalél, Urijájev sin, Hurov sin, iz Judovega rodu, je naredil vse, kar je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Z njim je bil Oholiáb, Ahisamáhov sin, iz Danovega rodu, graver, spreten delavec in vezalec v modri, vijolični, škrlatni in tankem lanenem platnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Vsega zlata, ki je bilo vključeno za delo v vsem delu svetega kraja, celo darovanega zlata, je bilo devetindvajset talentov in sedemsto trideset šeklov, po svetiščnem šeklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Srebra od tistih, ki so bili prešteti izmed skupnosti, je bilo sto talentov in tisoč sedemsto petinsedemdeset šeklov, po svetiščnem šeklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Pol šekla za vsakega človeka, to je polovica šekla, po svetiščnem šeklu, za vsakogar, ki je odšel, da bi bil preštet, od dvajsetih let starosti in naprej, za šeststo tri tisoč petsto petdeset mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Iz stotih talentov srebra so bili uliti podstavki svetišča in podstavki zagrinjala; sto podstavkov iz sto talentov, talent za podstavek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Iz tisoč sedemsto petinsedemdesetih šeklov je naredil kavlje za stebre in prevlekel njihove kapitele ter jih okrasil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Darovanega brona je bilo sedemdeset talentov in dva tisoč štiristo šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'In s tem je naredil podstavke k vratom šotorskega svetišča skupnosti, bronast oltar in zanj bronasto rešetko, vse oltarne posode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'podstavke dvora naokoli in podstavke velikih vrat dvora in vse količke šotorskega svetišča in vse količke dvora naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Iz modre, vijolične in škrlatne so naredili službene obleke, da opravljajo službo na svetem kraju in naredijo sveta oblačila za Arona; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Naredil je efód iz zlate, modre, vijolične, škrlatne in sukane tančice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Zlato so prekovali v tanke plošče in ga narezali v žice, da bi ga vdelali v modro, v vijolično, v škrlatno in v tanko laneno platno, s spretno izdelavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Za to so naredili obramna dela, da to spojijo skupaj; z dvema robovoma je bilo to spojeno skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Skrbno narejen pas njegovega efóda, ki je bil na njem, je bil iz istega, glede na njegovo delo; iz zlate, modre, vijolične, škrlatne in sukane tančice; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Izdelali so oniksova kamna, obdana z ležiščema iz zlata, vgravirana kakor so vgravirani pečati, z imeni Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Položil jih je na ramena efóda, da bodo kamni za spomin Izraelovim otrokom; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Naredil je naprsnik spretne izdelave, podoben efódovemu delu; iz zlate, modre, vijolične, škrlatne in sukane tančice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Bil je štirioglat; naprsnik so naredili prepognjen. Pedenj je bila njegova dolžina in pedenj njegova širina; bil je prepognjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Na njem so postavili štiri vrste kamnov. Prva vrsta je bil sardij, topaz in granat. To je bila prva vrsta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Druga vrsta smaragd, safir in diamant.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Tretja vrsta hijacint, ahat in ametist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Četrta vrsta beril, oniks in jaspis; bili so obdani v ležišča iz zlata v njihovih obdanostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Kamni so bili glede na imena Izraelovih otrok, dvanajst, glede na njihova imena, podobni gravuram pečata, vsak s svojim imenom, glede na dvanajst rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Na naprsniku so naredili verižici na krajih, iz spletenega dela, iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Naredili so dve ležišči iz zlata in dva zlata obročka in dva zlata obročka vstavili v dva konca naprsnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Vstavili so dve spleteni verižici iz zlata v dva obročka, na krajeh naprsnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Dva konca dveh spletenih verižic so privezali na dve ležišči in ju pritrdili na obramna dela efóda, pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Naredili so dva obročka iz zlata in ju položili na dva konca naprsnika, na njegov rob, ki je bil na notranji strani efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Naredili so dva druga zlata obročka in ju položili na dve strani pod efód, proti njegovi prednji strani, nasproti drugemu njegovemu spoju, nad skrbno narejenim pasom efóda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Naprsnik z njegovimi obročki so z modrim trakom privezali k obročkom efóda, da bi bil ta lahko nad skrbno narejenim pasom efóda in da se naprsnik ne bi odvezal od efóda; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Naredil je svečano oblačilo efóda iz spletenega dela, celega iz modre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Bila je luknja v sredi svečanega oblačila, kakor luknja brezrokavne verižne srajce s trakom naokoli luknje, da se ne raztrga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Na obšivih svečanega oblačila so naredili granatna jabolka iz modre, vijolične, škrlatne in sukane tančice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Naredili so zvončke iz čistega zlata in zvončke postavili med granatna jabolka, na obšivu svečanega oblačila, naokoli med granatnimi jabolki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'zvonček in granatno jabolko, zvonček in granatno jabolko naokoli obšiva svečanega oblačila za služenje v tem; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Naredili so plašče iz tankega lanenega platna iz spletenega dela, za Arona in za njegove sinove');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'in turban iz tankega lanenega platna in čedne klobučke iz tankega lanenega platna in kratke platnene hlače iz sukane tančice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'in pas iz sukane tančice in modre in vijolične in škrlatne, iz vezenine; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Naredili so ploščico svete krone iz čistega zlata in nanjo napisali pisanje, podobno gravuram pečata: »SVETO Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'K temu so privezali moder trak, da ga pričvrstijo visoko na turbanu; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tako je bilo vse delo šotorskega svetišča skupnosti končano. Izraelovi otroci so storili glede na vse, kar je Gospod zapovedal Mojzesu, tako so storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Šotorsko svetišče so prinesli k Mojzesu, šotor, vso njegovo opremo, njegove zaponke, njegove deske, njegove zapahe, njegove stebre, njegove podstavke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'pokrivalo rdeče barvanih ovnovih kož, pokrivalo iz jazbečevih kož, zagrinjalo pokrivala,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'skrinjo pričevanja, njena drogova, sedež milosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'mizo in vse njene posode in hlebe navzočnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'čisti svečnik z njegovimi svetilkami, celo s svetilkami, da so razvrščene in vse njegove posode in olje za svetlobo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'zlat oltar, mazilno olje in dišeče kadilo, tanko preprogo za vrata šotorskega svetišča,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'bronast oltar, njegovo rešetko iz brona, njegova drogova in vse njegove posode, [okrogel] umivalnik in njegovo vznožje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'tanko preprogo dvora, njegove stebre in njegove podstavke, tanko preprogo za velika dvorna vrata, njene vrvice in njene količke in vse posode službe šotorskega svetišča za shodni šotor,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'službene obleke, da opravljajo službo na svetem kraju in sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Glede na vse, kar je Gospod zapovedal Mojzesu, tako so Izraelovi otroci opravili vse delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Mojzes je pogledal na vse delo in glej, naredili so ga kakor je Gospod zapovedal, celo tako so ga naredili, in Mojzes jih je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '»Na prvi dan prvega meseca boš postavil šotorsko svetišče skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Vanj boš postavil skrinjo pričevanja in skrinjo pokril z zagrinjalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Prinesel boš mizo in uredil stvari, ki naj bi bile razvrščene na njej, in vanj boš prinesel svečnik ter prižgal njegove svetilke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Postavil boš oltar iz zlata za kadilo pred skrinjo pričevanja in k vratom šotorskega svetišča obesil tanko preprogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Postavil boš oltar žgalne daritve pred vrati šotorskega svetišča shodnega šotora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, '[Okrogel] umivalnik boš postavil med shodni šotor in oltar in vanj boš dal vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Napravil boš dvor naokoli in pri velikih vratih dvora obesil tanko preprogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Vzel boš mazilno olje in mazilil šotorsko svetišče in vse, kar je v njem in ga posvetil in vse njegove posode in to bo sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Mazilil boš oltar žgalne daritve in vse njegove posode in oltar posvéti. To bo oltar, najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Mazilil boš [okrogel] umivalnik in njegovo vznožje in ga posvétil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Arona in njegove sinove boš privedel k vratom šotorskega svetišča skupnosti in jih umil z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Na Arona boš nadel sveta oblačila in mazili ga in posvéti ga, da mi bo lahko služil v duhovniški službi«.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Privedel boš njegove sinove in jih oblekel s plašči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Mazilil jih boš, kakor si mazilil njihovega očeta, da mi bodo lahko služili v duhovniški službi, kajti njihovo maziljenje bo zagotovo večno duhovništvo skozi njihove rodove.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Tako je Mojzes storil. Glede na vse, kar mu je Gospod zapovedal, tako je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Pripetilo se je v prvem mesecu, v drugem letu, na prvi dan meseca, da je bilo šotorsko svetišče vzdignjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Mojzes je vzdignil šotorsko svetišče, privezal njegove podstavke, postavil njegove deske, vstavil njegove zapahe in vzdignil njegove stebre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'In šotor je razprostrl nad šotorskim svetiščem, in nad njim postavil pokrivalo šotora; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Vzel je pričevanje, ga položil v skrinjo, drogova namestil na skrinjo in na skrinjo položil sedež milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Skrinjo je prinesel v šotorsko svetišče in obesil zagrinjalo pokrivala ter pokril skrinjo pričevanja; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Mizo je položil v shodni šotor, proti severni strani šotorskega svetišča, zunaj zagrinjala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Na njej je urejeno položil kruh pred Gospodom; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Svečnik je postavil v shodni šotor, nasproti mizi, na strani šotorskega svetišča proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Pred Gospodom je prižgal svetilke; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Zlati oltar je postavil v shodnem šotoru pred zagrinjalom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'in na njem je zažgal dišeče kadilo; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Pri vratih šotorskega svetišča je obesil tanko preprogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Pri vratih šotorskega svetišča shodnega šotora je postavil oltar žgalne daritve in na njem daroval žgalno daritev in jedilno daritev; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Med shodni šotor in oltar je postavil [okrogel] umivalnik in vanj dal vodo, da se z njo umiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Mojzes, Aron in njegovi sinovi so tam umivali svoje roke in svoja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Ko so odhajali v shodni šotor in ko so prihajali bliže k oltarju, so se umili; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Dvor je uredil naokoli šotorskega svetišča in oltarja in obesil tanko preprogo velikih dvornih vrat. Tako je Mojzes končal delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Potem je oblak pokril shodni šotor in Gospodova slava je napolnila šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Mojzes pa ni bil zmožen vstopiti v shodni šotor, ker je na njem vztrajal oblak in Gospodova slava je napolnila šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Ko je bil oblak dvignjen iznad šotorskega svetišča, so Izraelovi otroci odšli naprej po vseh svojih poteh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'toda če oblak ni bil dvignjen, potem niso potovali do dneva, ko je bil dvignjen gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Kajti Gospodov oblak je bil nad šotorskim svetiščem podnevi, ogenj pa je bil na njem ponoči, v očeh vse Izraelove hiše, na vseh njihovih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Gospod je zaklical k Mojzesu in mu spregovoril iz šotorskega svetišča skupnosti, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '»Spregovori Izraelovim otrokom in jim reci: ›Če katerikoli človek izmed vas prinese dar Gospodu, boste prinesli svojo daritev izmed živine, od tropa in od črede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Če bo njegov dar žgalna daritev od črede, naj daruje samca brez pomanjkljivosti. Daroval ga bo iz svoje lastne prostovoljne volje pri vratih šotorskega svetišča skupnosti pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Svojo roko bo položil na glavo žgalne daritve in ta bo sprejeta zanj, da opravi spravo zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Bikca bo zaklal pred Gospodom in duhovniki, Aronovi sinovi, bodo prinesli kri in kri poškropili naokoli nad oltarjem, ki je pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Žgalno daritev bo odrl in jo razrezal na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Sinovi duhovnika Arona bodo na oltar položili ogenj in po vrsti na ogenj položili les.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Duhovniki, Aronovi sinovi, bodo položili dele, glavo in tolščo, po vrsti na les, ki je na ognju, ki je na oltarju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'toda njegovo drobovino in njegove noge bo umil v vodi. Duhovnik bo vse sežgal na oltarju, da bo žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Če bo njegov dar za žgalno daritev od tropov, namreč od ovc ali od koz, bo privedel samca brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Zaklal ga bo na severni strani oltarja pred Gospodom. Duhovniki, Aronovi sinovi, bodo njegovo kri poškropili naokoli nad oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Razrezal ga bo na koščke, z njegovo glavo in njegovo tolščo. Duhovnik jih bo po vrsti položil na les, ki je na ognju, ki je na oltarju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'toda drobovje in noge bo umil z vodo. Duhovnik bo vse to prinesel in to sežgal na oltarju. To je žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Če bo žgalna daritev za njegov dar Gospodu od perjadi, potem bo svojo daritev prinesel od grlic ali od mladih golobov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Duhovnik bo to prinesel na oltar in ji odščipnil vrat in jo sežgal na oltarju; in njena kri bo iztisnjena ob strani oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Njeno golšo bo odtrgal z njenimi peresi in jo odvrgel na vzhodnem delu, poleg oltarja, ob kraju za pepel');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'in nalomi jo s perutmi, toda ne bo je ločil narazen. Duhovnik bo to sežgal na oltarju, na lesu, ki je na ognju. To je žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '»›Ko bo kdorkoli daroval jedilno daritev Gospodu, bo njegov dar iz fine moke in na to bo izlil olje in položil kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'To bo prinesel Aronovim sinovom, duhovnikom. Iz od tega bo zajel prgišče moke in od olja, z vsem kadilom in duhovnik bo to sežgal na oltarju v spomin na to, da bo ognjena daritev, prijeten vonj Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Ostanek jedilne daritve bo od Arona in njegovih sinov. To je najsvetejša stvar Gospodovih daritev, narejenih z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Če prineseš dar jedilne daritve, spečen v peči, naj bodo to nekvašeni kolači iz fine moke, pomazani z oljem ali nekvašeni vaflji, pomazani z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Če bo tvoj dar jedilna daritev, spečena v ponvi, naj bo ta iz fine nekvašene moke, umešane z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Razdelil jo boš na koščke in nanjo izlil olje. To je jedilna daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Če bo tvoj dar jedilna daritev, spečena v tvoji ponvi za cvrtje, naj bo narejena iz fine moke z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Jedilno daritev, ki je narejena iz teh stvari, boš prinesel Gospodu in ko je ta izročena duhovniku, jo bo prinesel na oltar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Duhovnik bo vzel od jedilne daritve njegov spomin in tega bo sežgal na oltarju. To je ognjena daritev, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'To, kar je ostalo od jedilne daritve, bo od Arona in njegovih sinov. To je najsvetejša stvar Gospodovih daritev, narejenih z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nobena jedilna daritev, ki jo boste prinesli h Gospodu, naj ne bo pripravljena s kvasom, kajti nobenega kvasa niti nobenega medu ne boste sežgali pri vsaki Gospodovi daritvi, narejeni z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Kar se tiče daru prvih sadov, jih boste darovali Gospodu, toda ne bodo sežgani na oltarju za prijeten vonj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Vsak dar svoje jedilne daritve boš začinil s soljo; niti ne boš trpel, da bi sol zaveze tvojega Boga manjkala pri tvoji jedilni daritvi. Z vsemi svojimi darovi boš daroval sol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Če daruješ jedilno daritev svojih prvih sadov Gospodu, boš daroval za jedilno daritev svojih prvih sadov zeleno žitno klasje, posušeno ob ognju, torej žito, omlateno iz polnih klasov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Nanj boš izlil olje in nanj dal kadilo. To je jedilna daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Duhovnik bo sežgal spomin od tega, del od stolčenega žita in del od njegovega olja, z vsem njegovim kadilom. To je ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Če bo njegov dar darovanje mirovne daritve, če jo bo daroval od črede; bodisi je ta samec ali samica, jo bo daroval brez pomanjkljivosti pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Svojo roko bo položil na glavo njegovega daru in ga zaklal pri vratih šotorskega svetišča skupnosti. Aronovi sinovi, duhovniki, pa bodo kri poškropili naokoli po oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Daroval bo dar mirovne daritve, ognjeno daritev Gospodu; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'In obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, bo odstranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Aronovi sinovi bodo to sežgali na oltarju nad žgalno daritvijo, ki je na lesu, to je na ognju. To je ognjena daritev, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Če bo njegov dar za darovanje mirovne daritve Gospodu od tropa; samec ali samica, ga bo daroval brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Če daruje jagnje za njegov dar, potem ga bo daroval pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Svojo roko bo položil na glavo svojega daru in ga zaklal pred šotorskim svetiščem skupnosti, Aronovi sinovi pa bodo njegovo kri poškropili naokoli nad oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Daroval bo od žrtvovanja mirovne daritve, ognjeno daritev Gospodu; njegovo tolščo in celoten tolsti rep; odrezal ga bo tik ob hrbtenici; in tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'in obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama; to bo vzel stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Duhovnik bo to sežgal na oltarju. To to je hrana darovanja, ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Če bo njegov dar kozel, potem ga bo daroval pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Svojo roko bo položil na njegovo glavo in ga zaklal pred šotorskim svetiščem skupnosti, Aronovi sinovi pa bodo njegovo kri poškropili naokoli po oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Od tega bo daroval svoj dar, ognjeno daritev Gospodu; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'In obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, to bo vzeto proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Duhovnik jih bo sežgal na oltarju. To je hrana ognjene daritve za prijeten vonj. Vsa tolšča je Gospodova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'To bo večen zakon za vaše rodove po vseh vaših prebivališčih, da ne jeste niti tolšče niti krvi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '»Govori Izraelovim otrokom, rekoč: ›Če bo duša zaradi nevednosti grešila zoper katerekoli izmed Gospodovih zapovedi, glede stvari, ki se ne bi smele storiti, in bo storila zoper katerokoli izmed njih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'če duhovnik, ki je maziljen, stori greh glede na greh ljudstva, potem naj za svoj greh, ki ga je zagrešil, privede mladega bikca brez pomanjkljivosti Gospodu za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Bikca bo privedel k vratom šotorskega svetišča skupnosti pred Gospoda in svojo roko bo položil bikcu na glavo in pred Gospodom bo bikca zaklal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Duhovnik, ki je maziljen, bo vzel od krvi bikca in jo prinesel do šotorskega svetišča skupnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'in duhovnik bo svoj prst pomočil v kri in pred zagrinjalom svetišča kri sedemkrat poškropil pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Duhovnik bo nekaj krvi dal na rogove oltarja prijetnega vonja pred Gospodom, ki je v šotorskem svetišču skupnosti; in vso kri bikca bo izlil ob vznožju oltarja žgalne daritve, ki je ob vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Iz njega bo vzel vso tolščo bikca za daritev za greh; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'dve ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, to bo vzeto proč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'kot je bilo vzeto od bikca žrtvovanja mirovnih daritev. Duhovnik jih bo sežgal na oltarju žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'In kožo bikca in vse njegovo meso z njegovo glavo, z njegovimi nogami, njegovim drobovjem in njegovim iztrebkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Celo celotnega bikca bo odnesel naprej, zunaj tabora, na čist prostor, kjer je bil izsut pepel in ga z ognjem sežgal na lesu. Sežgan bo kjer je izsut pepel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Če celotna Izraelova skupnost greši zaradi nevednosti in bo stvar skrita pred očmi zbora in so storili nekaj zoper katerokoli izmed Gospodovih zapovedi glede stvari, ki ne bi smele biti storjene in so krivi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'ko je greh, ki so ga zagrešili zoper njega znan, potem bo skupnost darovala mladega bikca za greh in ga privedla pred šotorsko svetišče skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Starešine skupnosti bodo pred Gospodom svoje roke položili na glavo bikca in bikec bo zaklan pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Duhovnik, ki je maziljen, bo k šotorskemu svetišču skupnosti prinesel od krvi bikca');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'in duhovnik bo svoj prst pomočil v nekaj od krvi in jo sedemkrat poškropil pred Gospodom, torej pred zagrinjalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Nekaj krvi bo dal na rogove oltarja, ki je pred Gospodom, to je v šotorskem svetišču skupnosti in vso kri bo izlil ob vznožju oltarja žgalne daritve, ki je ob vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Iz njega bo vzel vso njegovo tolščo in jo sežgal na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Z bikcem bo storil kakor je storil z bikcem daritve za greh; tako bo storil s tem. In duhovnik bo zanje opravil spravo in to jim bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Bikca bo odnesel zunaj tabora in ga sežgal kakor je sežgal prvega bikca. To je daritev za greh za skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ko je voditelj grešil in storil nekaj zaradi nevednosti zoper katerokoli izmed zapovedi Gospoda, svojega Boga, glede stvari, ki naj ne bi bile storjene in je kriv,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'ali če njegov greh, v čemer je grešil, pride k njegovemu spoznanju; bo prinesel svoj dar, kozlička izmed koz, samca brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Svojo roko bo položil na glavo kozla in ga zaklal na kraju, kjer koljejo žgalno daritev pred Gospodom. To je daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Duhovnik bo s svojim prstom vzel od krvi daritve za greh in to dal na rogove oltarja žgalne daritve in njegovo kri bo izlil ob vznožju oltarja žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Vso njegovo tolščo bo sežgal na oltarju, kakor tolščo žrtvovanja mirovnih daritev. Duhovnik bo zanj opravil spravo, glede na njegov greh in ta mu bo odpuščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Če kdorkoli izmed preprostega ljudstva greši zaradi nevednosti, medtem ko stori nekaj zoper katerokoli izmed Gospodovih zapovedi, glede stvari, ki ne bi smele biti storjene in je kriv;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'ali če njegov greh, ki ga je zagrešil, pride v njegovo spoznanje; potem bo za svoj greh, ki ga je zagrešil, prinesel svoj dar, kozlička od koz, samico brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Svojo roko bo položil na glavo daritve za greh in na kraju žgalne daritve bo zaklal daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Duhovnik bo s prstom vzel od njegove krvi in to dal na rogove oltarja žgalne daritve in vso njegovo kri bo izlil ob vznožju oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Odvzel bo vso njegovo tolščo, kakor je odvzeta tolšča žrtvovanja mirovnih daritev, in duhovnik jo bo sežgal na oltarju v prijeten vonj Gospodu, in duhovnik bo zanj opravil spravo in to mu bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Če privede jagnje v dar za greh, bo prinesel samico, brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Svojo roko bo položil na glavo daritve za greh in jo na kraju, kjer koljejo žgalno daritev, zaklal v daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Duhovnik bo s svojim prstom vzel od krvi daritve za greh in to dal na rogove oltarja žgalne daritve in vso kri izlil ob vznožju oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Odvzel bo vso njeno tolščo, kakor je tolšča jagnjeta odvzeta od žrtvovanja mirovnih daritev, in duhovnik jih bo sežgal na oltarju, glede na daritve, narejene z ognjem Gospodu, in duhovnik bo opravil spravo za njegov greh, ki ga je zagrešil in ta mu bo odpuščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Če duša greši in sliši glas priseganja in je priča, bodisi da je to videla ali izvedela o tem; če tega ne izusti, potem bo nosila svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Ali če se duša dotakne katerekoli nečiste stvari, bodisi je to truplo nečiste živali ali truplo nečiste živine ali truplo nečistih plazečih bitij, in če je to skrito pred njim, bo tudi on nečist in kriv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Ali če se on dotakne nečistosti človeka, kakršnakoli nečistost je to, da se bo človek z njo omadeževal in je to skrito pred njim; potem bo kriv, ko izve o tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Ali če duša priseže, razglašujoč s svojimi ustnicami, da stori zlo ali da stori dobro, karkoli je to, kar bo človek s prisego razglasil in bo to skrito pred njim; ko izve o tem, potem bo kriv v eni izmed teh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Zgodilo se bo, ko bo kriv v eni izmed teh stvari, da bo priznal, da je v tej stvari grešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Za svoj greh, ki ga je zagrešil, bo prinesel Gospodu svojo daritev za prestopek, samico izmed tropa, jagnje ali kozlička izmed koz za daritev za greh; in duhovnik bo zanj opravil spravo glede njegovega greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Če pa ne bo zmožen prinesti jagnjeta, potem bo za svoj prekršek, ki ga je zagrešil, Gospodu prinesel dve grlici ali dva mlada goloba, enega za daritev za greh in drugega za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Prinesel ju bo duhovniku, ki bo najprej daroval to, kar je za daritev za greh in njegovo glavo bo odščipnil od vratu, toda tega ne bo ločil narazen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Poškropil bo od krvi daritve za greh na strani oltarja. Preostanek krvi pa bo iztisnil ob vznožju oltarja. To je daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Drugo pa bo daroval za žgalno daritev, glede na določen način in duhovnik bo zanj opravil spravo za njegov greh, ki ga je zagrešil in ta mu bo odpuščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Toda če ne bo zmožen prinesti dveh grlic ali dveh mladih golobov, potem naj tisti, ki je grešil, za svoj dar prinese deseti del škafa iz fine moke za daritev za greh; nanjo ne bo dal olja niti ne bo nanjo dal kakršnega koli kadila, kajti to je daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Potem bo to prinesel do duhovnika in duhovnik bo vzel prgišče tega, torej spomin od tega in to sežgal na oltarju, glede na daritve, narejene z ognjem Gospodu. To je daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Duhovnik bo zanj opravil spravo glede njegovega greha, ki ga je zagrešil v eni od teh [stvari] in ta mu bo odpuščen. Preostanek pa bo duhovnikov, kot jedilna daritev.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '»Če duša zagreši prekršek in greši zaradi nevednosti v Gospodovih svetih stvareh, potem bo za svoj prekršek iz tropa privedla ovna brez pomanjkljivosti Gospodu, s tvojo oceno po srebrnih šeklih, po svetiščnem šeklu, v daritev za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Odkupil se bo zaradi škode, ki jo je storil v sveti stvari in k temu bo dodal peti del in ga dal duhovniku. Duhovnik bo zanj opravil spravo z ovnom daritve za prekršek in to mu bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Če duša greši in zagreši katerokoli od teh stvari, ki so po Gospodovih zapovedih prepovedane, da se storijo; čeprav tega ni vedel, je vendarle kriv in bo nosil svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Iz tropa bo duhovniku privedel ovna brez pomanjkljivosti, s tvojo oceno, v daritev za prestopek in duhovnik bo zanj opravil spravo glede njegove nevednosti, v kateri je nevedno grešil in tega ni vedel in ta mu bo odpuščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'To je daritev za prestopek. Zagotovo se je prekršil zoper Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '»Če duša greši in zagreši prekršek zoper Gospoda in laže svojemu bližnjemu v tem, kar mu je bilo izročeno, da varuje, ali v družbi, ali v stvari, odvzeti z nasiljem, ali je zavedel svojega bližnjega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'ali je našel to, kar je bilo izgubljeno in glede tega laže in krivo prisega; v čemerkoli izmed vsega tega kar človek dela, v tem greši;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Potem se bo zgodilo, ker je grešil in je kriv, da bo povrnil to, kar je nasilno odvzel proč ali stvar, ki jo je varljivo pridobil ali to, kar mu je bilo izročeno, da varuje ali izgubljeno stvar, ki jo je našel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'ali vse to o čemer je krivo prisegel. To bo torej povrnil v glavnici in k temu bo dodal še petino in to dal tistemu, ki mu pripada, na dan svoje daritve za prekršek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'H Gospodu bo [prek] duhovnika privedel svojo daritev za prestopek, ovna brez pomanjkljivosti iz tropa, s tvojo oceno, v daritev za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Duhovnik bo zanj pred Gospodom opravil spravo in odpuščeno mu bo za karkoli od vsega, kar je storil v teh prekrških.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '»Zapovej Aronu in njegovim sinovom, rekoč: ›To je postava žgalne daritve: ›To je žgalna daritev, ker vso noč, do jutra, gori na oltarju in oltarni ogenj bo gorel v njej.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Duhovnik si bo nadel laneno obleko in kratke platnene hlače bo nadel na svoje meso in pobral pepel, ki ga je ogenj na oltarju použil z žgalno daritvijo in ga položil poleg oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Odložil bo svoje obleke in si nadel druge obleke in pepel odnesel zunaj tabora, na čist prostor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Ogenj na oltarju naj gori na njem; naj ne bo ugasnjen. Duhovnik naj na njem vsako jutro zažiga les in nanj po vrsti polaga žgalno daritev in na njem naj zažiga tolščo mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ogenj bo vedno gorel na oltarju; nikoli naj ne ugasne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'To je postava jedilne daritve. Aronovi sinovi jo bodo darovali pred Gospodom, pred oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Od tega bo vzel prgišče moke jedilne daritve in od olja in vse kadilo, ki je na jedilni daritvi in to bo na oltarju sežgal Gospodu v prijeten vonj, torej spomin na to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Preostanek pa bodo Aron in njegovi sinovi pojedli. Z nekvašenim kruhom bo pojedena na svetem prostoru. Na dvoru šotorskega svetišča skupnosti jo bodo pojedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ta ne bo pečena s kvasom. To sem jim dal za njihov delež mojih daritev, narejenih z ognjem; to je najsvetejše, kakor je daritev za greh in kakor daritev [za] prekršek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Vsi moški izmed Aronovih otrok bodo jedli od nje. To bo zakon na veke v vaših rodovih glede Gospodovih daritev, narejenih z ognjem; vsak, kdor se jih dotakne, bo svet.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '»To je dar Arona in njegovih sinov, ki ga bodo darovali Gospodu na dan, ko je maziljen: deseti del škafa fine moke za neprestano jedilno daritev, polovico od tega zjutraj in polovico od tega zvečer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'V ponvi naj bo pripravljena z oljem in ko je ocvrta, jo boš v njej prinesel in pečene koščke jedilne daritve boš daroval v prijeten vonj Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'To naj daruje duhovnik izmed njegovih sinov, ki je maziljen namesto njega. To je zakon na veke Gospodu; ta naj bo v celoti sežgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Kajti vsaka jedilna daritev za duhovnika naj bo v celoti sežgana. Le-ta naj ne bo pojedena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '»Govori Aronu in njegovim sinovom, rekoč: ›To je postava daritve za greh pred Gospodom. Na kraju, kjer je zaklana žgalna daritev, bo zaklana daritev za greh. To je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Jedel jo bo duhovnik, ki jo daruje za greh. Pojedena bo na svetem kraju, na dvoru šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Karkoli od tega se bo dotaknilo mesa, naj bo sveto, in ko je kri od te daritve poškropljena na kakršnokoli obleko, boš na svetem prostoru opral to, po čemer je bila poškropljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Toda lončena posoda, v kateri je skuhana, naj bo razbita, in če je skuhana v bronastem loncu, naj bo tako odrgnjena kakor pomita v vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Vsi moški izmed duhovnikov bodo jedli od tega. To je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Nobena daritev za greh, od katere je kakršnakoli kri prinesena v šotorsko svetišče skupnosti, da se z njo pobota na svetem kraju, naj ne bo pojedena. Ta naj bo sežgana v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Prav takšna je postava daritve za prestopek. To je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na mestu, kjer koljejo žgalno daritev, bodo zaklali daritev za prestopek in njeno kri bodo poškropili naokoli nad oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Od tega bo daroval vso njeno tolščo; tolsti rep in tolščo, ki pokriva drobovje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'dve ledvici in tolščo, ki je na njiju, ki je ob bokih in opno, ki je nad jetri, z dvema ledvicama, to bo vzel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Duhovnik jih bo sežgal na oltarju za daritev, ognjeno daritev Gospodu. To je daritev za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Vsak moški med duhovniki naj od tega jé. To naj bo pojedeno na svetem prostoru. To je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Kakor je daritev za greh, tako je daritev za prestopek. Zanju je ena postava. Duhovnik, ki s tem opravlja spravo, bo to imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Duhovnik, ki daruje žgalno daritev kateregakoli človeka, torej duhovnik, bo zase imel kožo žgalne daritve, ki jo je daroval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Vsa jedilna daritev, ki je spečena v peči in vse, kar je pripravljeno v ponvi za cvrtje in v ponvi, naj bo od duhovnika, ki jo daruje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Vsako jedilno daritev, pomešano z oljem in suho, naj imajo vsi Aronovi sinovi, eden toliko kakor drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'To je postava žrtvovanja mirovnih daritev, ki jih bo daroval Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Če jo daruje za zahvaljevanje, potem naj jo daruje z žrtvijo zahvaljevanja nekvašenih kolačev, umešanih z oljem in nekvašenih vafljev, pomazanih z oljem in ocvrtih kolačev, umešanih z oljem iz fine moke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Poleg kolačev bo za svoj dar daroval kvašen kruh z zahvalno žrtvijo njegovih mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Od tega naj daruje enega od celotnega daru za vzdigovalno daritev Gospodu in to naj bo od tistega duhovnika, ki škropi kri mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Meso žrtvovanja njegovih mirovnih daritev za zahvaljevanje naj bo pojedeno istega dne, kot je bilo darovano; nič od tega naj ne pusti do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Toda če je žrtvovanje njegove daritve prisega ali prostovoljno darovanje, naj bo to pojedeno istega dne, kot daruje svojo klavno daritev in tudi naslednji dan naj bo njen ostanek pojeden,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'toda preostanek mesa klavne daritve naj bo na tretji dan sežgan z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Če bo karkoli od mesa žrtvovanja njegovih mirovnih daritev pojedeno tretji dan, ne bo sprejeto niti ne bo pripisano tistemu, ki je to daroval. To bo ogabnost in duša, ki od tega jé, bo nosila svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Meso, ki se dotakne katerekoli nečiste stvari naj ne bo pojedeno; sežgano naj bo z ognjem. Kar se tiče mesa, vsi, ki so čisti, naj od tega jedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Toda duša, ki jé od mesa žrtvovanja mirovnih daritev, ki pripadajo Gospodu, ima na sebi svojo nečistost, celo ta duša naj bo iztrebljena iz svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Še več, duša, ki se bo dotaknila katerekoli nečiste stvari, kakor je nečistost človeka ali kakršnekoli nečiste živali ali kakšne gnusne nečiste stvari in jé od mesa žrtvovanja mirovnih daritev, ki pripadajo Gospodu, celo ta duša naj bo iztrebljena iz svojega ljudstva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '»Govori Izraelovim otrokom, rekoč: ›Vi ne boste jedli nobene vrste tolšče od vola, ovce ali koze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Tolšča živali, ki je sama od sebe poginila in tolšča od tega, kar so živali raztrgale, je lahko uporabljena na katerikoli drug način, toda vi od tega nikakor ne boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Kajti kdorkoli jé tolščo živali, od katerih ljudje darujejo ognjeno daritev Gospodu, celo duša, ki to jé, naj bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Še več, vi ne boste jedli nobene vrste krvi, bodisi od perjadi ali od živine, v kateremkoli izmed svojih prebivališč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Katerakoli duša, ki jé katerokoli vrsto krvi, celo ta duša naj bo iztrebljena iz svojega ljudstva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '»Govori Izraelovim otrokom, rekoč: ›Kdor daruje žrtvovanje svojih mirovnih daritev Gospodu, bo prinesel svoj dar Gospodu od žrtvovanja svojih mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Njegove lastne roke bodo prinesle Gospodove ognjene daritve, tolščo s prsmi. To bo prinesel, da bodo prsi lahko majane za majalno daritev pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Duhovnik naj tolščo sežge na oltarju, toda prsi naj bodo od Arona in njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Desno pleče boste dali duhovniku za vzdigovalno daritev, žrtvovanje svojih mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Tisti izmed Aronovih sinov, ki darujejo kri mirovnih daritev in tolščo, bodo imeli za svoj delež desno pleče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Kajti prsi majanja in pleče vzdigovanja sem vzel Izraelovim otrokom izmed žrtvovanja njihovih mirovnih daritev in jih za vedno z zakonom dal duhovniku Aronu in njegovim sinovom izmed Izraelovih otrok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'To je delež Aronovega maziljenja in maziljenja njegovih sinov izmed ognjenih Gospodovih daritev, na dan, ko jih je prinesel, da bi služil Gospodu v duhovniški službi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'ki ga je Gospod zapovedal, da bi jim bil dan od Izraelovih otrok, na dan, ko jih je mazilil, z zakonom na veke skozi njihove rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'To je postava žgalne daritve, jedilne daritve, daritve za greh, daritve za prestopek, uméstitvenih [daritev] in žrtvovanje mirovnih daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'ki jih je Gospod zapovedal Mojzesu na gori Sinaj, na dan, ko je Izraelovim otrokom zapovedal, naj svoje darove darujejo Gospodu v Sinajski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '»Vzemi Arona in z njim njegove sinove, obleke, mazilno olje, bikca za daritev za greh, dva ovna in košaro nekvašenega kruha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'in zberi skupaj ves zbor k vratom šotorskega svetišča skupnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mojzes je storil, kakor mu je Gospod zapovedal in zbor je bil zbran skupaj k vratom šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Mojzes je rekel skupnosti: »To je stvar, ki jo je Gospod zapovedal, da se stori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Mojzes je privedel Arona in njegove sinove ter jih umil z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Nadel mu je plašč, ga opasal s pasom, ga ogrnil s svečanim oblačilom, nanj položil efód in ga opasal s skrbno narejenim pasom efóda in ga s tem prevezal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Nanj je dal naprsnik. V naprsnik je položil tudi Urím in Tumím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Turban je položil na njegovo glavo; tudi na turban, torej na njegov sprednji del, je položil zlato ploščico, sveto krono; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Mojzes je vzel mazilno olje in mazilil šotorsko svetišče in vse, kar je bilo v njem in to posvetil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Od tega je sedemkrat poškropil po oltarju in mazilil oltar ter vse njegove posode, tako [okrogel] umivalnik kot njegovo vznožje, da jih posvéti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Na Aronovo glavo je izlil mazilno olje in ga mazilil, da ga posvéti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Mojzes je privedel Aronove sinove, nanje položil plašče, jih opasal s pasovi in nanje položil klobučke; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Privedel je bikca za daritev za greh. Aron in njegovi sinovi so svoje roke položili na glavo bikca daritve za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Zaklal ga je in Mojzes je vzel kri in jo s svojim prstom dal vsenaokrog na rogove oltarja in očistil oltar in kri izlil ob vznožju oltarja in ga posvetil, da bi na njem opravil pobotanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Vzel je vso tolščo, ki je bila na drobovju, opno nad jetri, dve ledvici, njuno tolščo in Mojzes je to sežgal na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Toda bikca, njegovo kožo, njegovo meso in njegov iztrebek je z ognjem sežgal zunaj tabora; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'In privedel je ovna za žgalno daritev, Aron in njegovi sinovi pa so svoje roke položili ovnu na glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Zaklal ga je in Mojzes je kri poškropil naokoli po oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Ovna je razrezal na koščke in Mojzes je sežgal glavo, koščke in tolščo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Drobovje in noge je opral v vodi in Mojzes je celotnega ovna sežgal na oltarju. To je bila žgalna daritev v prijeten vonj in ognjena daritev Gospodu; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Privedel je drugega ovna, ovna uméstitve, Aron in njegovi sinovi pa so svoje roke položili ovnu na glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'In on ga je zaklal. Mojzes je vzel od njegove krvi, jo pomazal na konico Aronovega desnega ušesa, na palec njegove desne roke in na palec njegovega desnega stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Privedel je Aronove sinove in Mojzes je dal od krvi na konico njihovih desnih ušes in na palce njihovih desnih rok in na palce njihovih desnih stopal; in Mojzes je kri poškropil naokoli po oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Vzel je tolščo, tolsti rep, vso tolščo, ki je bila na drobovju, opno nad jetri, dve ledvici in njuno tolščo ter desno pleče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Iz košare nekvašenega kruha, ki je bila pred Gospodom, je vzel en nekvašen kolač, kolač oljnatega kruha in en vafelj ter jih položil na tolščo in na desno pleče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Vse to je dal na Aronove roke in na roke Aronovih sinov in jih majal za majalno daritev pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Mojzes jih je vzel iz njihovih rok in jih sežgal na oltarju nad žgalno daritvijo. To so bile uméstitvene [daritve] za prijeten vonj. To je ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Mojzes je vzel prsi in jih majal za majalno daritev pred Gospodom, kajti od ovna uméstitve je bil to Mojzesov delež; kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Mojzes je vzel od mazilnega olja in od krvi, ki je bila na oltarju in to poškropil na Arona, na njegove obleke, na njegove sinove in na obleke njegovih sinov z njim; in posvetil je Arona, njegove obleke, njegove sinove in obleke njegovih sinov z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Mojzes je rekel Aronu in njegovim sinovim: »Meso skuhajte pri vratih šotorskega svetišča skupnosti. Tam ga pojejte s kruhom, ki je v košari uméstitvenih [daritev], kakor sem zapovedal, govoreč: ›Aron in njegovi sinovi bodo to jedli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'To, kar pa ostane od mesa in od kruha, boste sežgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Sedem dni ne boste šli od vrat šotorskega svetišča skupnosti, dokler dnevi vaše uméstitve ne bodo končani, kajti sedem dni vas bo uméščal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Kakor je storil ta dan, tako je Gospod zapovedal storiti, da za vas opravi spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Zato boste sedem dni, dan in noč, ostajali pri vratih šotorskega svetišča skupnosti in se boste držali Gospodovega naročila, da ne umrete, kajti tako mi je bilo zapovedano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Tako so Aron in njegovi sinovi storili vse stvari, ki jih je Gospod zapovedal po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Na osmi dan se je pripetilo, da je Mojzes poklical Arona, njegove sinove in Izraelove starešine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Aronu je rekel: »Vzemi si mlado tele za daritev za greh in ovna za žgalno daritev, brez pomanjkljivosti in ju daruj pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Izraelovim otrokom boš govoril, rekoč: ›Vzemite kozlička od koz za daritev za greh ter tele in jagnje, oba enoletna, brez pomanjkljivosti, za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Tudi bikca in ovna za mirovno daritev, da žrtvujete pred Gospodom in jedilno daritev umešano z oljem, kajti danes se vam bo prikazal Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Pred šotorsko svetišče skupnosti so privedli to, kar je Mojzes zapovedal, in vsa skupnost se je približala ter stala pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Mojzes je rekel: »To je stvar, ki jo je Gospod zapovedal, da naj bi jo storili; in prikazala se vam bo Gospodova slava.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Mojzes je rekel Aronu: »Pojdi k oltarju in daruj svojo daritev za greh in svojo žgalno daritev in opravi spravo zase in za ljudstvo in daruj dar ljudstva in opravi spravo zanje; kakor je zapovedal Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Aron je torej odšel k oltarju in zaklal tele za daritev za greh, ki je bilo zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Aronovi sinovi so k njemu prinesli kri, in svoj prst je pomočil v kri in jo dal na rogove oltarja in kri izlil ob vznožju oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Toda tolščo, ledvici in opno nad jetri daritve za greh je sežgal na oltarju, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Meso in kožo pa je sežgal z ognjem zunaj tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Zaklal je žgalno daritev in Aronovi sinovi so mu podali kri, ki jo je poškropil naokoli nad oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Podali so mu žgalno daritev, z njenimi kosi in glavo, in sežgal jih je na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Opral je drobovje in noge ter jih sežgal na žgalni daritvi, na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Prinesel je dar ljudstva in vzel kozla, ki je bil daritev za greh za ljudstvo in ga zaklal ter ga daroval za greh kakor prvega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Privedel je žgalno daritev in jo daroval glede na določen način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Prinesel je jedilno daritev in od nje vzel prgišče in to sežgal na oltarju poleg jutranje žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Za ljudstvo je zaklal tudi bikca in ovna za žrtvovanje mirovnih daritev, Aronovi sinovi pa so mu podali kri, ki jo je poškropil naokoli po oltarju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'in tolščo bikca in ovna, tolsti rep in to, kar pokriva drobovje, ledvici in opno nad jetri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Tolščo so položili na prsi in tolščo je sežgal na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Prsi in desno pleče je Aron majal za majalno daritev pred Gospodom; kakor je zapovedal Mojzes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Aron je svojo roko vzdignil proti ljudstvu in jih blagoslovil in prišel dol od darovanja daritve za greh, žgalne daritve in mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Mojzes in Aron sta odšla v šotorsko svetišče skupnosti in prišla ven ter blagoslovila ljudstvo in Gospodova slava se je prikazala vsemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Tam je prišel ogenj izpred Gospoda in na oltarju použil žgalno daritev in tolščo. Ko je vse ljudstvo to videlo, so zavpili in padli na svoje obraze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nadáb in Abihú, Aronova sinova, sta vsak izmed njiju vzela svojo kadilnico in vanju dala ogenj in nanju položila kadilo in pred Gospodom darovala tuj ogenj, katerega jim ni zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'In tam je izšel ogenj od Gospoda in ju použil in umrla sta pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Potem je Mojzes rekel Aronu: »To je to, kar je Gospod govoril, rekoč: ›Jaz bom posvečen v tistih, ki se mi približajo in pred vsem ljudstvom bom proslavljen.‹« In Aron je ohranil svoj mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mojzes je poklical Mišaéla in Elicafána, sinova Uziéla, ki je bil Aronov stric in jima rekel: »Pridita bliže, odnesita svoja brata izpred svetišča, ven iz tabora.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Tako sta se približala in ju v njunih plaščih odnesla ven iz tabora; kakor je rekel Mojzes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Mojzes je rekel Aronu ter Eleazarju in Itamárju, njegovima sinovoma: »Ne odkrijte svojih glav niti ne pretrgajte svojih oblačil, da ne bi umrli in da ne bi nad vse ljudstvo prišel bes, temveč naj vaši bratje, celotna Izraelova hiša objokujejo gorenje, ki ga je vžgal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ne boste šli ven izpred vrat šotorskega svetišča skupnosti, sicer boste umrli, kajti Gospodovo olje maziljenja je na vas.« In storili so glede na Mojzesovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Gospod je spregovoril Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '»Ne pij vina, niti močne pijače, ne ti, niti tvoji sinovi s teboj, ko greste v šotorsko svetišče skupnosti, da ne bi umrli. To naj bo zakon na veke skozi vaše rodove,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'da lahko postavite razliko med svetim in nesvetim in med nečistim in čistim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'da lahko Izraelove otroke učite vseh zakonov, ki jim jih je Gospod govoril po Mojzesovi roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mojzes je spregovoril Aronu ter Eleazarju in Itamárju, njegovima sinovoma, ki sta ostala: »Vzemite jedilno daritev, ki ostaja od Gospodovih daritev, narejenih z ognjem in jejte jo brez kvasa poleg oltarja, kajti to je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'To boste jedli na svetem prostoru, ker je določeno tebi in tvojim sinovom od Gospodovih žrtev, narejenih z ognjem, kajti tako sem zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Prsi majanja in pleče vzdigovanja boste jedli na čistem kraju; ti in tvoji sinovi in tvoje hčere s teboj, kajti določene so tebi in tvojim sinovom, ki so bile dane od žrtvovanja mirovnih daritev Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Pleče vzdigovanja in prsi majanja naj prinesejo z daritvami, narejenimi z ognjem tolšče, da majejo to za majalno daritev pred Gospodom. In ta bo tvoja in tvojih sinov s teboj, po zakonu na veke; kakor je zapovedal Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Mojzes je marljivo iskal kozla daritve za greh in glej, ta je bil sežgan in bil je jezen na Eleazarja in Itamárja, Aronova sinova, ki sta ostala živa, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '»Zakaj daritve za greh nista jedla na svetem prostoru, glede na to, da je to najsvetejše in Bog vama je dal, da nosita krivičnost skupnosti, da zanje opravita spravo pred Gospodom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Glejta, njegova kri ni bila privedena znotraj svetega kraja. Zares bi jo morala jesti na svetem kraju, kakor sem ukazal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Aron je rekel Mojzesu: »Glej, ta dan so darovali svojo daritev za greh in svojo žgalno daritev pred Gospodom, mene pa so doletele takšne stvari. Če bi danes jedel daritev za greh ali naj bi bila ta sprejeta v Gospodovih očeh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Ko je Mojzes to slišal, je bil zadovoljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč jima:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '»Govorita Izraelovim otrokom, rekoč: ›To so živali, ki jih boste jedli med vsemi živalmi, ki so na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Karkoli deli kopito in ima preklan parkelj in prežvekuje med živalmi, te boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Vendar izmed teh, ki prežvekujejo ali izmed teh, ki delijo kopito, ne boste jedli takšnih kot je kamela, ker prežvekuje, toda ne deli kopita; ta vam je nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Kunca, ker prežvekuje, toda ne deli kopita; ta vam je nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Zajca, ker prežvekuje, toda ne deli kopita; ta vam je nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Svinje, čeprav deli kopito in je s preklanim kopitom, vendar ne prežvekuje; ta vam je nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Od njihovega mesa ne boste jedli in njihovega trupla se ne boste dotikali; te so vam nečiste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Te boste jedli izmed vseh, ki so v vodah. Karkoli ima plavuti in luske v vodah, v morjih in v rekah, te boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Vse, kar nima plavuti in luske v morjih in rekah od vsega, kar se giblje v vodah in od česarkoli živega, kar je v vodah, te naj vam bodo ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Te naj vam bodo torej ogabnost. Od njihovega mesa ne boste jedli, temveč boste njihova trupla imeli za ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Karkoli v vodah nima plavuti niti lusk, to vam bo ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'In te so tiste, ki vam bodo ogabnost med perjadjo. Ne smejo se jesti, ogabnost so: orel, brkati ser, ribji orel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'jastreb, kragulj po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'vsak krokar po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, '§ sova, nočni sokol, kukavica, sokol po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'majhna sova, kormoran, velika sova,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'labod, pelikan, egiptovski jastreb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'štorklja, čaplja po svoji vrsti, smrdokavra in netopir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Vsa perjad, ki leze, hodeč po vseh štirih, vam bo ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Vendar od vsake leteče plazeče stvari, ki hodi po vseh štirih, ki ima noge nad svojimi stopali, da z njimi skače po zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Torej te izmed njih lahko jeste: letečo kobilico po svoji vrsti, plešasto kobilico po svoji vrsti, skakajočo kobilico po svoji vrsti in kobilico po svoji vrsti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Toda vse druge leteče plazeče stvari, ki imajo štiri nožice, vam bodo ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Zaradi teh boste nečisti. Kdorkoli izmed njih se dotakne trupla, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Kdorkoli mora nositi njihovo truplo, bo opral svoja oblačila in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Trupla vsake živali, ki deli kopito in ni s preklanim kopitom niti ne prežvekuje, so vam nečista. Vsak, kdor se jih dotika, bo nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Karkoli gre po svojih tacah med vsemi vrstami živali, ki gredo po vseh štirih, te so vam nečiste. Kdorkoli se dotika njihovega trupla, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Kdorkoli prenaša njihovo truplo, bo opral svoja oblačila in bo nečist do večera. Ta so vam nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Tudi te vam bodo nečiste izmed plazečih stvari, ki se plazijo po zemlji: podlasica, miš, želva po svoji vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'dihur, kameleon, kuščar, polž in krt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Te so vam nečiste izmed vseh, ki se plazijo; kdorkoli se jih dotakne, ko so mrtve, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Na karkoli katerakoli izmed njih, ko so mrtve, pade, bo to nečisto; bodisi je to kakršnakoli lesena posoda ali obleka ali koža ali vreča ali kakršnakoli posoda je ta, s katero je opravljeno kakršnokoli delo, mora biti postavljena v vodo in ta bo nečista do večera; tako bo očiščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Vsaka lončena posoda, v katero katerakoli izmed njih pade, karkoli je [že] v njej, bo to nečisto; in naj se razbije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Od vse hrane, ki se lahko jé, bo to, na kar pride takšna voda, nečisto. Vsa pijača, ki se lahko pije v vsaki takšni posodi, bo nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Vsaka stvar, na katero pade katerikoli del njihovega trupla, bo nečista, bodisi je to peč ali podstavna kamna za lonce, naj bodo zdrobljeni, kajti ti so nečisti in naj vam bodo nečisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Vendar bosta izvir ali vodnjak, v kateri je obilje vode, čista. Toda to, kar se dotakne njihovega trupla, bo nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Če katerikoli del njihovega trupla pade na katerokoli seme za sejanje, ki bo posejano, bo to čisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Toda če bo na seme prišla kakršnakoli voda in nanj pade katerikoli del njihovega trupla, vam bo to nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Če pogine katerakoli žival, od katere lahko jeste, bo tisti, ki se dotakne njenega trupla, nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Kdor jé od tega trupla, bo opral svoja oblačila in bo nečist do večera. Tudi tisti, ki nosi to truplo, bo opral svoja oblačila in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Vsaka plazeča stvar, ki se plazi po zemlji, bo ogabnost; ta naj se ne jé.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Karkoli gre po trebuhu in karkoli gre po vseh štirih ali karkoli ima več nožic med vsemi plazečimi stvarmi, ki se plazijo po zemlji, teh ne boste jedli, kajti ogabnost so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Sebe ne boste naredili gnusne s katerokoli plazečo stvarjo, ki se plazi, niti se z njimi ne boste naredili nečiste, da bi bili s tem omadeževani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Kajti jaz sem Gospod, vaš Bog. Sebe boste torej posvetili in boste sveti, kajti jaz sem svet, niti se ne boste omadeževali z nobeno vrsto plazeče stvari, ki se plazi po zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Kajti jaz sem Gospod, ki vas izpeljuje gor iz egiptovske dežele, da bi bil vaš Bog. Bodite torej sveti, kajti jaz sem svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'To je postava živali, perjadi in vsakega živega ustvarjenega bitja, ki se premika v vodah in vsakega živega ustvarjenega bitja, ki se plazi po zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'da naredi razliko med nečistim in čistim in med živaljo, ki se lahko jé in živaljo, ki se ne sme jesti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '»Govori Izraelovim otrokom, rekoč: ›Če je ženska spočela seme in rodila fantka, potem bo nečista sedem dni; nečista bo glede na dneve oddvojitve zaradi njene šibkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Na osmi dan naj bo meso njegove prednje kožice obrezano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Potem bo nadaljevala v krvi svojega očiščevanja triintrideset dni; ne bo se dotaknila nobene posvečene stvari niti prišla v svetišče, dokler se dnevi njenega očiščevanja ne bodo dopolnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Toda če rodi deklico, potem bo nečista dva tedna, kakor v svoji oddvojitvi, in v krvi svojega očiščevanja naj nadaljuje šestinšestdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Ko so dnevi njenega očiščenja dopolnjeni za sina ali za hčer, bo prinesla duhovniku, k vratom šotorskega svetišča skupnosti, enoletno jagnje za žgalno daritev in mladega goloba ali grlico za daritev za greh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'ki ga bo daroval pred Gospodom in zanjo opravil spravo; in očiščena bo pred virom svoje krvi. To je postava za tisto, ki je rodila fantka ali punčko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Če ni zmožna prinesti jagnjeta, potem naj prinese dve grlici ali dva mlada goloba; enega za žgalno daritev in drugega za daritev za greh. Duhovnik bo zanjo opravil spravo in bo čista.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '»Če bo imel kak človek na koži svojega mesa dvignjeno mesto, krasto ali svetlo pego in bo ta na koži njegovega mesa podobna nadlogi gobavosti, potem naj bo priveden k duhovniku Aronu ali k enemu izmed njegovih sinov, duhovnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Duhovnik bo pogledal na nadlogo na koži mesa. Ko je dlaka na nadlogi postala bela in je nadloga videti globlja kakor koža njegovega mesa, je to nadloga gobavosti. Duhovnik bo pogledal nanj in ga proglasil za nečistega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Če je svetla pega na koži njegovega mesa bela in na pogled ni globlja kakor koža in se njene dlake niso pobelile, potem naj duhovnik tistega, ki ima nadlogo, zapre za sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Duhovnik ga bo sedmi dan pregledal in glej, če nadloga v njegovem pogledu ostane in se nadloga ni razširila po koži, potem ga bo duhovnik zaprl še za nadaljnjih sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Duhovnik naj ga sedmi dan ponovno pregleda in glej, če bo nadloga nekako temna in se nadloga na koži ne širi, ga bo duhovnik proglasil za čistega. To je samo krasta. Opral bo svoja oblačila in bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Toda če se krasta precej razširi po koži, potem ko ga je za njegovo očiščenje videl duhovnik, naj ga duhovnik ponovno pregleda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'In če duhovnik vidi, da se krasta po koži širi, potem ga bo duhovnik proglasil za nečistega. To je gobavost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Kadar je nadloga gobavosti na človeku, potem bo ta priveden k duhovniku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'in duhovnik ga bo pregledal. Glej, če bo dvignjeno mesto na koži belo in če so dlake postale bele in je tam hitro divje meso na dvignjenem mestu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'je to stara gobavost na koži njegovega mesa in duhovnik ga bo proglasil za nečistega in ga ne bo zaprl, kajti on je nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Če gobavost izbruhne naokoli po koži in gobavost prekrije vso kožo tistega, ki ima nadlogo, od njegove glave, celo do njegovega stopala, kjerkoli duhovnik pogleda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'potem bo duhovnik preudaril. Glej, če je gobavost pokrila vse njegovo meso, bo tega, ki ima nadlogo, proglasil za čistega. Vse se je spremenilo v belo. Ta je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Toda ko se na njem pojavi divje meso, bo nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Duhovnik bo pregledal divje meso in ga proglasil, da je nečist, kajti divje meso je nečisto. To je gobavost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Ali če je divje meso ponovno spremenjeno v belo, bo prišel k duhovniku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'in duhovnik ga bo pregledal. Glej, če se je nadloga spremenila v belo, potem bo duhovnik tistega, ki ima nadlogo, proglasil za čistega. On je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Tudi meso, torej v koži na njem, v kateri je bila razjeda in je ozdravljeno');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'in je na mestu razjede belo vzdignjeno mesto ali svetla pega, bela in malce rdečkasta in je ta pokazana duhovniku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'in če bo, ko jo duhovnik pregleda, na videz nižja od kože in bo njena dlaka spremenjena v belo, ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti, ki je izbruhnila iz razjede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Toda če duhovnik to pogleda in glej, tam ni belih dlak in če ni nižje kakor koža, temveč je nekako temno, potem ga bo duhovnik zaprl za sedem dni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'in če se precej razširi po koži, potem ga bo duhovnik proglasil za nečistega. To je nadloga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Toda če svetla pega ostaja na svojem mestu in se ni razširila, je to vnetna razjeda in duhovnik ga bo proglasil za čistega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ali če je na koži kakršnokoli meso, na katerem je opeklina in ima divje meso te opekline belo svetlo pego, malce rdečkasto ali belo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'potem bo duhovnik pogledal na to. Glej, če se je dlaka na svetli pegi pobelila in je na videz globlja od kože, je to gobavost, ki je izbruhnila iz opekline. Zato ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Toda če duhovnik na to pogleda in glej, tam ni nobene bele dlake na svetli pegi in ta ni nižja kakor ostala koža, temveč je nekako temna, potem ga bo duhovnik zaprl za sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Duhovnik ga bo sedmi dan pogledal in če je to precej razširjeno po koži, potem ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Če pa svetla pega ostane na svojem mestu in se ne razširi po koži, temveč je ta nekako temna, je to dvignjeno mesto od opekline in duhovnik ga bo proglasil za čistega, kajti to je vnetje od opekline.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Če ima moški ali ženska nadlogo na glavi ali na bradi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'potem bo duhovnik pregledal nadlogo in glej, če je ta na videz globlja od kože in so tam v njej tanke rumene dlake, potem ga bo duhovnik proglasil za nečistega. To je luskavica, celo gobavost na glavi ali bradi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Če duhovnik pogleda na nadlogo luskavice in glej, če ta na videz ni globlja kakor koža in v njej ni črne dlake, potem bo duhovnik za sedem dni zaprl tistega, ki ima nadlogo luskavice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'in na sedmi dan bo duhovnik pogledal nadlogo. Glej, če se luskavica ne razširi in v njej ni rumene dlake in luskavica na videz ni globlja od kože,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'naj bo obrit, toda luskavica naj ne bo obrita, in duhovnik naj tistega, ki ima luskavico, zapre še za sedem dni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'in na sedmi dan bo duhovnik pogledal na luskavico. Glej, če se luskavica ni razširila po koži niti na videz ni globlja od kože, potem ga bo duhovnik proglasil za čistega in opral si bo svoja oblačila in bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Toda če se je luskavica po njegovem očiščevanju precej razširila po koži,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'potem naj duhovnik pogleda nanj. Glej, če se je luskavica razširila po koži, duhovnik ne bo iskal rumenih dlak; ta je nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Toda če luskavica na pogled miruje in tam niso zrasle črne dlake, potem je luskavica ozdravljena, ta je čist in duhovnik ga bo proglasil za čistega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Če imata moški ali ženska na koži svojega mesa svetle pege, torej bele svetle pege,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'potem bo duhovnik pogledal. Glej, če so svetle pege na koži njunega mesa temno bele, je to pegasta točka, ki raste na koži. Ta je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Moški, katerega lasje so odpadli iz njegove glave, je plešast; vendar je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Kdor ima svoje lase odpadle od dela njegove glave proti njegovemu obrazu, ta je čelno plešast; vendar je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Če je na plešasti glavi ali golem čelu bela rdečkasta pega, je to gobavost, ki je pognala na njegovi plešasti glavi ali na njegovem plešastem čelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Potem bo duhovnik pogledal nanj. Glej, če je vzdignjeno mesto na njegovi plešasti glavi ali na njegovem plešastem čelu belo rdečkasto, kakor se pojavlja gobavost na koži mesa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'je ta gobav moški, on je nečist. Duhovnik ga bo proglasil popolnoma nečistega; njegova nadloga je na njegovi glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Gobavec, na katerem je nadloga, naj ima pretrgana oblačila, golo glavo in svojo zgornjo ustnico naj pokriva in naj kliče: ›Nečist, nečist.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Vse dni, v katerih bo na njem nadloga, naj bo omadeževan; nečist je. Prebiva naj sam; zunaj tabora naj bo njegovo prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Tudi obleka, na kateri je nadloga gobavosti, bodisi je ta volnena ali lanena obleka;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'bodisi je ta na osnutku ali na votku; iz lanu ali iz volne; bodisi na usnju ali na katerikoli stvari, narejeni iz usnja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'in če je nadloga na obleki ali na usnju zelenkasta ali rdečkasta, bodisi na osnutku ali na votku, ali na čemurkoli iz usnja, je to nadloga gobavosti in pokazana bo duhovniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Duhovnik bo pogledal na nadlogo in za sedem dni zaprl to, kar ima nadlogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Sedmi dan naj pogleda na nadlogo. Če se je nadloga razširila po obleki, bodisi po osnutku ali po votku, ali na usnju ali na kateremkoli delu, narejenemu iz usnja, potem je nadloga nadležna gobavost; to je nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Zato bo sežgal to obleko, bodisi je to osnutek ali votek, na volni ali na lanu ali kakršnakoli usnjena stvar, na kateri je nadloga, kajti to je nadležna gobavost; to bo sežgano v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Če bo duhovnik pogledal in glej, nadloga ni razširjena na obleki, bodisi na osnutku ali na votku ali na kakršnikoli usnjeni stvari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'potem bo duhovnik zapovedal, da operejo stvar, na kateri je nadloga in jo bo zaprl še za sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Duhovnik bo pogledal na nadlogo, potem ko je umita. Glej, če nadloga ni spremenila svoje barve in se nadloga ni razširila, je to nečisto. To boš sežgal v ognju. To je notranja razjeda, bodisi je ta znotraj ali zunaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Če duhovnik pogleda in glej, nadloga je po umivanju nekoliko potemnela, potem jo bo iztrgal iz obleke ali iz usnja ali iz osnutka ali iz votka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Če se še vedno pojavlja na obleki, bodisi na osnutku ali na votku ali na čemerkoli iz usnja, je to razširjajoča se nadloga. To, na čemer je nadloga, boš sežgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Obleko, bodisi osnutek ali votek ali kakršna koli stvar iz usnja je to, jo boš umil. Če je nadloga odšla od njih, potem bo to drugič umito in bo čisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'To je postava nadloge gobavosti na obleki iz volne ali lanu, bodisi je na osnutku ali na votku ali na katerikoli stvari iz usnja, da se razglasi za čisto ali da se proglasi za nečisto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '»To bo postava za gobavca na dan njegovega očiščenja. Pripeljan bo k duhovniku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'in duhovnik bo šel naprej iz tabora in duhovnik bo pogledal in glej, če je na gobavcu nadloga gobavosti ozdravljena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'potem bo duhovnik zapovedal, da za tistega, ki naj bi bil očiščen, vzamejo dve ptici, živi in čisti, cedrov les, škrlat in izop,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'in duhovnik bo zapovedal, da bo ena izmed ptic zaklana v lončeni posodi nad tekočo vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Glede žive ptice, jo bo vzel s cedrovim lesom, škrlatom in izopom in jih bo skupaj z živo ptico pomočil v kri ptice, ki je bila zaklana nad tekočo vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'To bo sedemkrat poškropil na tistega, ki naj bi bil očiščen gobavosti in proglasil ga bo za čistega in živo ptico bo izpustil prosto na odprto polje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Ta, ki naj bo očiščen, bo opral svoja oblačila in obril vse dlake in se umil v vodi, da bo lahko čist. Potem bo prišel v tabor in sedem dni ostajal zunaj svojega šotora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Toda na sedmi dan, ko bo obril vse dlake s svoje glave, svoje brade in svojih obrvi, bo obril celo vso svojo dlako in v vodi bo opral svoja oblačila in tudi svoje meso bo umil in bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Na osmi dan bo vzel dva jagenjčka, samca brez pomanjkljivosti in eno jagnjico prvega leta, brez pomanjkljivosti in tri desetinke fine moke za jedilno daritev, pomešano z oljem in en vrček olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Duhovnik, ki ga očiščuje, bo pred Gospodom, pri vratih šotorskega svetišča skupnosti, predstavil človeka, ki naj bi bil očiščen in te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Duhovnik bo vzel enega jagenjčka, samca in ga daroval za daritev za greh in vrček olja ter ju majal pred Gospodom za majalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Jagnje bo zaklal na kraju, kjer bo zaklal daritev za greh in žgalno daritev, na svetem kraju, kajti daritev za greh je duhovnikova, kot tudi daritev za prestopek. To je najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Duhovnik bo vzel nekaj krvi daritve za prestopek in duhovnik jo bo dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Duhovnik bo vzel nekaj od vrčka olja in to izlil na dlan svoje leve roke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'in duhovnik bo svoj desni prst pomočil v olje, ki je v njegovi levi roki in olje bo s svojim prstom sedemkrat poškropil pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Preostanek olja, ki je v njegovi roki, bo duhovnik dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala, na kri daritve za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Ostanek olja, ki je v duhovnikovi roki pa naj izlije na glavo tistega, ki naj bo očiščen in duhovnik bo zanj opravil spravo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Duhovnik bo daroval daritev za greh in opravil spravo za tistega, ki naj bo očiščen svoje nečistosti in potem bo zaklal žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Duhovnik bo na oltarju daroval žgalno daritev in jedilno daritev, in duhovnik bo zanj opravil spravo in on bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Če pa je reven in ne more dobiti toliko, potem bo vzel eno jagnje za daritev za prestopek, da bo majano, da opravi spravo zanj in eno desetinko fine moke, umešane z oljem za jedilno daritev in vrček olja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'ter dve grlici ali dva mlada goloba, takšne, kot jih lahko dobi; ena bo za daritev za greh, druga pa za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Na osmi dan jih bo prinesel duhovniku za svoje očiščenje, k vratom šotorskega svetišča skupnosti pred Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Duhovnik bo vzel jagnje daritve za prestopek in vrček olja in duhovnik ju bo majal za majalno daritev pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Zaklal bo jagnje daritve za prekršek in duhovnik bo vzel nekaj od krvi daritve za prekršek in jo dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'in duhovnik bo nekaj olja izlil v dlan svoje leve roke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'in duhovnik bo s svojim desnim prstom nekaj olja, ki je v njegovi levi roki, sedemkrat poškropil pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Duhovnik bo dal od olja, ki je v njegovi roki, na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala, na mestu krvi daritve za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Preostanek olja, ki je v duhovnikovi roki, pa bo dal na glavo tistega, ki naj bo očiščen, da zanj opravi spravo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Daroval bo eno izmed grlic ali izmed mladih golobov, takega, kot ga lahko dobi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'torej takšnega, kot ga je zmožen dobiti, enega za daritev za greh in drugega za žgalno daritev, z jedilno daritvijo, in duhovnik bo za tistega, ki naj bo očiščen pred Gospodom, opravil spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'To je postava tistega, na katerem je nadloga gobavosti, čigar roka ni zmožna dobiti tega, kar pripada njegovemu očiščenju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '»Ko boste prišli v kánaansko deželo, ki sem vam jo dal za posest in položim nadlogo gobavosti v hišo dežele vaše posesti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'in kdor je lastnik hiše in pride in pove duhovniku, rekoč: ›Zdi se mi, da je tam v hiši, kakor bi bila nadloga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'potem bo duhovnik zapovedal, da izpraznijo hišo, preden duhovnik vstopi vanjo, da bi videl nadlogo, da ne bi vse, kar je v hiši, postalo nečisto in potem bo duhovnik vstopil, da pogleda hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Pogledal bo nadlogo in glej, če je nadloga na zidovih hiše, z ugreznjenimi mesti, zelenkastimi ali rdečimi, ki so na pogled nižja kakor zid,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'potem bo duhovnik šel ven iz hiše, k hišnim vratom in bo za sedem dni zaprl hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Duhovnik bo sedmi dan ponovno prišel in pogledal. Glej, če je nadloga razširjena po zidovih hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'potem bo duhovnik zapovedal, da odnesejo kamne, na katerih je nadloga in jih odvržejo na nečist kraj zunaj mesta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'hišo pa bo dal znotraj vso ostrgati in ostrgan prah bodo izsuli zunaj mesta na nečist kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Vzeli bodo druge kamne in jih položili na mesto tistih kamnov in vzel bo drugo malto in ometal hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Če nadloga ponovno pride in izbruhne v hiši, potem ko je kamne odvzel proč in potem, ko je ostrgal hišo in potem ko je ta ometana,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'potem bo prišel duhovnik in pogledal in glej, če se je nadloga razširila po hiši, je to nadležna gobavost v hiši. Ta je nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Porušil bo hišo, njene kamne, njen les in vso malto hiše in jih odnesel naprej, ven iz mesta, na nečist kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Poleg tega bo kdor gre v hišo, medtem ko je ta zaprta, nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Kdor leži v hiši, bo opral svoja oblačila in kdor jé v hiši, bo opral svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Če bo duhovnik vstopil in pogledal na to in glej, nadloga se ni razširila po hiši, potem ko je bila hiša ometana; potem bo duhovnik hišo proglasil za čisto, ker je nadloga ozdravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Da hišo očisti, bo vzel dve ptici, cedrov les, škrlat in izop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Eno izmed ptic bo zaklal v lončeni posodi nad tekočo vodo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'in vzel bo cedrov les, izop, škrlat in živo ptico ter jih pomočil v krvi zaklane ptice in v tekočo vodo in hišo sedemkrat poškropil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Hišo bo očistil s krvjo ptice, s tekočo vodo, z živo ptico, s cedrovim lesom, z izopom in škrlatom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'toda živo ptico bo izpustil ven iz mesta, na odprta polja in opravil spravo za hišo, in ta bo čista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'To je postava za vse vrste nadlog gobavosti in luskavice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'ter za gobavost obleke in hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'za oteklino, za krasto in za svetlo pego,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'da uči, kdaj je to nečisto in kdaj je to čisto. To je postava gobavosti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '»Govorita Izraelovim otrokom in jim recita: ›Kadar ima katerikoli moški tekoč izliv iz svojega mesa, je zaradi svojega izliva nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'To bo njegova nečistost v njegovem izlivu; bodisi iz njegovega mesa teče z njegovim izlivom, ali se v njegovem mesu ustavlja izliv, je to nečistost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Vsaka postelja, na kateri leži ta, ki ima izliv, je nečista, in vsaka stvar, na kateri on sedi, bo nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Kdorkoli se dotakne njegove postelje, naj opere svoja oblačila in se okopa v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Kdor sedi na katerikoli stvari, na kateri je sedel tisti, ki ima izliv, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Kdor se dotika mesa tistega, ki ima izliv, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Če tisti, ki ima izliv, pljune na tistega, ki je čist, potem bo ta opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Kdor osedla karkoli, na čemer jaha tisti, ki ima izliv, bo nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Kdorkoli se dotakne česarkoli, kar je bilo pod njim, bo nečist do večera, in kdor nosi katerokoli izmed teh stvari, naj opere svoja oblačila in se okopa v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Kogarkoli se dotakne tisti, ki ima izliv in si rok ni umil v vodi, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Lončena posoda, ki se je dotakne tisti, ki ima izliv, bo razbita; vsaka lesena posoda pa bo umita v vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'In ko se je ta, ki ima izliv, očistil svojega izliva, potem si bo štel sedem dni za svoje očiščevanje, opral svoja oblačila, svoje meso okopal v tekoči vodi in bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Osmi dan si bo vzel dve grlici ali dva mlada goloba in bo prišel pred Gospoda, k vratom šotorskega svetišča skupnosti in ju bo dal duhovniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Duhovnik ju bo daroval, enega za daritev za greh in drugega za žgalno daritev. Duhovnik bo pred Gospodom zaradi njegovega izliva zanj opravil spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Če iz kateregakoli moškega steče seme združenja, potem bo vse svoje meso umil v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Vsaka obleka in vsako usnje, na katerem je seme združenja, bo oprano v vodi in bo nečisto do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Tudi ženska, s katero moški leži s semenom združenja, se bosta oba okopala v vodi in bosta nečista do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Če ima ženska izliv in je njen izliv v njenem mesu kri, bo ločena posebej za sedem dni. Kdorkoli se je dotakne, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Vsaka stvar, na kateri ona v svoji oddvojitvi leži, bo nečista. Tudi vsaka stvar, na kateri ona sedi, bo nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Kdorkoli se dotakne njene postelje, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Kdorkoli se dotakne katerekoli stvari, na kateri je sedela, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'In če je to na njeni postelji ali na katerikoli stvari ona sedi, ko se je ta dotakne, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Če katerikoli moški sploh leži z njo in je njena nečistost nad njim, bo nečist sedem dni in vsa postelja, na kateri on leži, bo nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Če ima ženska vir njene krvi mnogo dni dlje od časa njene oddvojitve ali če ta teče preko časa njene oddvojitve; vseh dni izliva njene nečistosti bo kakor na dneve njene oddvojitve; ona bo nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Vsaka postelja, na kateri leži vse dni svojega izliva, ji bo kakor postelja oddvojitve in na čemerkoli ona sedi, bo nečisto, kakor nečistost njene oddvojitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Kdorkoli se dotika teh stvari bo nečist in bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Toda če bo očiščena svojega izliva, potem si bo štela sedem dni in potem bo čista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Na osmi dan si bo vzela dve grlici ali dva mlada goloba in ju prinesla k duhovniku, k vratom šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Duhovnik bo enega daroval za daritev za greh, drugega pa za žgalno daritev. Duhovnik bo zaradi izliva njene nečistosti zanjo opravil spravo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tako bodo Izraelove otroke oddvojili od njihove nečistosti, da v svoji nečistosti ne umrejo, ko omadežujejo moje šotorsko svetišče, ki je med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'To je postava za tistega, ki ima izliv in tistega, katerega seme gre od njega in je s tem omadeževan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'in o tisti, ki je bolna od svoje nečistosti in o tistem, ki ima izliv, od moškega ali od ženske in o tistem, ki leži s tisto, ki je nečista.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Gospod je spregovoril Mojzesu po smrti Aronovih dveh sinov, ko sta darovala pred Gospodom in umrla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'in Gospod je rekel Mojzesu: »Govori svojemu bratu Aronu, da ne pride ob vseh časih v sveti prostor znotraj zagrinjala, pred sedež milosti, ki je na skrinji, da ne umre, kajti jaz se bom v oblaku prikazal nad sedežem milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Tako bo Aron prišel na sveti kraj: z mladim bikcem za daritev za greh in ovnom za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Nadel si bo svet lanen plašč, na svojem mesu bo imel kratke platnene hlače, opasan bo z lanenim pasom in okrašen z lanenim turbanom. To so sveta oblačila, zato bo svoje meso umil v vodi in si jih tako nadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Od zbora Izraelovih otrok bo vzel dva kozlička od koz za daritev za greh in enega ovna za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Aron bo daroval svojega bikca daritve za greh, ki je zanj ter opravil spravo zase in za svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Vzel bo dva kozla in ju postavil pred Gospoda, pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Aron bo metal žrebe med dvema kozloma. En žreb za Gospoda, drugi žreb pa za ubežnega kozla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Aron bo privedel kozla, na katerega je padel Gospodov žreb in ga daroval za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Toda kozel, na katerega pade žreb, da bo ubežen kozel, bo živ postavljen pred Gospoda, da z njim opravi spravo in da ga za ubežnega kozla spusti v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Aron bo privedel bikca daritve za greh, ki je zanj in opravil spravo zase in za svojo hišo in zaklal bo bikca daritve za greh, ki je zanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'in izpred oltarja, pred Gospodom, bo vzel kadilnico, polno gorečega ognjenega oglja in svoji roki polni drobno zdrobljenega dišečega kadila in to bo prinesel znotraj zagrinjala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Kadilo bo položil na ogenj pred Gospodom, da oblak kadila lahko pokrije sedež milosti, ki je nad pričevanjem, da ne umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Vzel bo od krvi bikca in jo s svojim prstom poškropil nad sedežem milosti proti vzhodu. Pred sedežem milosti bo s svojim prstom sedemkrat poškropil kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Potem bo zaklal kozla daritve za greh, ki je za ljudstvo in njegovo kri prinesel znotraj zagrinjala in s to krvjo storil, kakor je storil s krvjo bikca in jo poškropil nad sedežem milosti in pred sedežem milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Zaradi nečistosti Izraelovih otrok in zaradi njihovih prestopkov v vseh njihovih grehih bo opravil spravo za svet kraj in tako bo storil za šotorsko svetišče skupnosti, ki ostaja med njimi v sredi njihove nečistosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Tam ne bo nobenega moža v šotorskem svetišču skupnosti, ko gre vanj, da opravi spravo na svetem kraju, dokler ne pride ven in je opravil spravo zase, za svojo družino in za vso Izraelovo skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Odšel bo ven, k oltarju, ki je pred Gospodom in opravil spravo zanj. Vzel bo od krvi bikca in od krvi kozla in to položil naokoli, na oltarne rogove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'S svojim prstom bo nanj sedemkrat poškropil od krvi, ga očistil in ga posvetil pred nečistostjo Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Ko zaključi očiščenje svetega kraja, šotorskega svetišča skupnosti in oltarja, bo privedel živega kozla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'in Aron bo obe svoji roki položil na glavo živega kozla in nad njim priznal vse krivičnosti Izraelovih otrok in vse njihove prestopke v vseh njihovih grehih, s tem, da jih položi na glavo kozla in ga po roki primernega moža pošlje proč, v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Kozel bo na sebi nosil vse njihove krivičnosti v nenaseljeno deželo in kozla bo spustil v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Aron bo prišel v šotorsko svetišče skupnosti in odložil lanene obleke, ki jih je oblekel, ko je odšel v sveti kraj in jih bo pustil tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Svoje meso bo z vodo umil na svetem kraju in si nadel svoje obleke in prišel naprej ter daroval svojo žgalno daritev, žgalno daritev za ljudstvo in opravil spravo zase in za ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Tolščo daritve za greh bo sežgal na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Tisti, ki je spustil kozla za ubežnega kozla, bo opral svoja oblačila in svoje meso umil v vodi in potem pride v tabor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Bikca daritve za greh in kozla daritve za greh, čigar kri je bila prinesena, da opravi spravo na svetem kraju, bo nekdo odnesel zunaj tabora, v ognju pa bodo sežgali njihove kože, njihovo meso in njihov iztrebek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Kdor jih zažiga bo opral svoja oblačila in svoje telo umil v vodi in potem bo prišel v tabor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'To bo med vami zakon na veke, da boste v sedmem mesecu, na deseti dan meseca, ponižali svoje duše in sploh ne boste počeli nobenega dela; naj bo to nekdo iz vaše lastne dežele ali tujec, ki začasno prebiva med vami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'kajti na ta dan bo duhovnik opravil spravo za vas, da vas očisti, da boste pred Gospodom lahko čisti pred vsemi svojimi grehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'To vam bo šabatni počitek in svoje duše boste strli, po zakonu na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Duhovnik, ki ga bo mazilil in ki ga bo uméstil, da služi v duhovniški službi na mestu njegovega očeta, bo opravil spravo in si nadel lanena oblačila, torej sveta oblačila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'in ta bo opravil spravo za sveto svetišče in ta bo opravil spravo za šotorsko svetišče skupnosti in za oltar in ta bo opravil spravo za duhovnike in za vse ljudstvo skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'To vam bodi večen zakon, da enkrat letno opravite spravo za Izraelove otroke, za vse njihove grehe.« In storil je, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '»Govori Aronu, njegovim sinovom in vsem Izraelovim otrokom ter jim reci: ›To je stvar, ki jo je Gospod zapovedal, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, '›Katerikoli človek bo tam iz Izraelove hiše, ki kolje vola ali jagnje ali kozo v taboru ali da to kolje izven tabora,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'pa tega ne prinaša k vratom šotorskega svetišča skupnosti, da daruje dar Gospodu pred Gospodovim šotorskim svetiščem, bo kri pripisana tistemu človeku. Prelil je kri, in ta mož bo iztrebljen izmed svojega ljudstva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'z namenom, da Izraelovi otroci lahko prinesejo svoje klavne daritve, ki jih darujejo na odprtem polju, torej, da jih lahko privedejo h Gospodu, k vratom šotorskega svetišča skupnosti, k duhovniku in jih darujejo za mirovna žrtvovanja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Duhovnik bo kri poškropil na Gospodov oltar pri vratih šotorskega svetišča skupnosti in tolščo sežgal v prijeten vonj Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, '§ Svojih klavnih daritev ne bodo več darovali hudičem, za katerimi so se odšli vlačugat. To jim bo zakon na veke skozi njihove rodove.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Rekel jim boš: ›Katerikoli mož bo iz Izraelove hiše ali od tujcev, ki začasno prebivajo med vami, ki darujejo žgalno daritev ali žrtvovanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'pa tega ne prinašajo k vratom šotorskega svetišča skupnosti, da to darujejo Gospodu; torej ta mož bo iztrebljen izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Katerikoli človek bo tam iz Izraelove hiše ali izmed tujcev, ki začasno prebivajo med vami, ki na kakršenkoli način jé kri, bom svoj obraz naravnal prav posebej proti tej duši, ki jé kri in ga iztrebil izmed njegovih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Kajti življenje mesa je v krvi in dal sem vam jo na oltarju, da opravite spravo za svoje duše, kajti kri je ta, ki opravlja spravo za dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Zato sem Izraelovim otrokom rekel: ›Nobena duša izmed vas ne bo jedla krvi niti ne bo noben tujec, ki začasno biva med vami, jedel krvi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Katerikoli mož bo izmed Izraelovih otrok ali od tujcev, ki začasno bivajo med vami, ki lovijo in ujamejo katerokoli žival ali perjad, ki se lahko jé, ta bo torej izlil njeno kri in jo pokril s prahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Kajti to je življenje vsega mesa, kri od tega je za njegovo življenje. Zatorej sem Izraelovim otrokom rekel: ›Na noben način ne boste jedli krvi od mesa, kajti življenje vsega mesa je njegova kri. Kdorkoli to jé, bo iztrebljen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Vsaka duša, ki jé to, kar je poginilo samo od sebe, ali to, kar je bilo raztrgano z zvermi, bodisi je to nekdo iz vaše lastne dežele ali tujec, bo tako opral svoja oblačila kakor se okopal v vodi in bo nečist do večera. Potem bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Toda če jih ne opere niti ne umije svojega mesa, potem bo nosil svojo krivičnost.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '»Govori Izraelovim otrokom in jim reci: ›Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ne boste delali po ravnanjih egiptovske dežele, v kateri ste prebivali, in po ravnanjih kánaanske dežele, kamor vas vodim, ne boste delali. Niti se ne boste ravnali po njihovih odredbah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Izvrševali boste moje sodbe in se držali mojih odredb, da v njih hodite. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Vi se boste torej držali mojih zakonov in mojih sodb, katere, če jih človek izvršuje, bo živel v njih. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nihče izmed vas se ne bo približal kateremukoli, ki mu je bližnji sorodnik, da odkrije njihovo nagoto. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Nagote svojega očeta ali nagote svoje matere ne boš odkril. Ona je tvoja mati; ne boš odkril njene nagote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Nagote žene svojega očeta ne boš odkril. To je nagota tvojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Nagote svoje sestre, hčere tvojega očeta ali hčere tvoje matere, bodisi je ona rojena doma ali rojena zunaj, torej njune nagote ne boš odkril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Nagote hčere svojega sina ali hčerine hčere, torej njune nagote ne boš odkril, kajti njuna je tvoja lastna nagota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Nagote hčere žene tvojega očeta, rojene tvojemu očetu; ona je tvoja sestra, ne boš odkril njene nagote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Ne boš odkril nagote sestre svojega očeta; ona je bližnja sorodnica tvojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Ne boš odkril nagote sestre svoje matere, kajti ona je bližnja sorodnica tvoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Ne boš odkril nagote brata svojega očeta, ne boš se približal njegovi ženi; ona je tvoja teta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Ne boš odkril nagote svoje snahe, ona je sinova žena; ne boš odkril njene nagote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Ne boš odkril nagote žene svojega brata. To je nagota tvojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Ne boš odkril nagote ženske in njene hčere niti ne boš vzel hčere njenega sina ali hčere njene hčere, da bi odkril njeno nagoto, kajti oni sta njeni bližnji sorodnici. To je zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Niti ne boš vzel žene k njeni sestri, da jo dražiš, da odkriješ njeno nagoto poleg druge v njenem času življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Prav tako se ne boš približal ženski, da odkriješ njeno nagoto, dokler je oddvojena zaradi svoje nečistosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Poleg tega ne boš meseno ležal z ženo svojega soseda, da bi se z njo omadeževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Nikomur izmed svojega semena ne boš dovolil iti skozi ogenj k Molohu niti ne boš oskrunil imena svojega Boga. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Ne boš ležal z moškimi kakor z ženskami. To je ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Niti ne boš ležal z nobeno živaljo, da s tem omadežuješ samega sebe niti ne bo nobena ženska stala pred živaljo, da leže dol k njej. To je zmešnjava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne omadežujte se z nobeno od teh stvari, kajti v vseh teh so omadeževani narodi, ki jih jaz preženem pred vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Zemlja je omadeževana, zato obiščem krivičnost le-te na njej in sama zemlja izbruha njene prebivalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Zato se boste držali mojih zakonov in mojih sodb in ne boste zagrešili nobene od teh ogabnosti; niti kdorkoli izmed vašega lastnega naroda niti katerikoli tujec, ki začasno biva med vami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(kajti vse te ogabnosti so storili ljudje dežele, ki so bili pred vami in dežela je omadeževana),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'da dežela tudi vas ne izpljune, ko ste jo omadeževali, kakor je izpljunila narode, ki so bili pred vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Kajti kdorkoli bo zagrešil katero izmed teh ogabnosti, celo duše, ki jih zagrešijo, bodo iztrebljene izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Zatorej se boste držali mojih odredb, da ne zagrešite kateregakoli izmed teh gnusnih običajev, ki so bili zagrešeni pred vami in da se ne omadežujete v tem. Jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '»Spregovori vsej skupnosti Izraelovih otrok in jim reci: ›Vi bodite sveti, kajti jaz, Gospod, vaš Bog, sem svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, '§ Bojte se vsak mož svoje matere in svojega očeta in se držite mojih šabat. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne obračajte se k malikom niti si ne delajte ulitih bogov. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Če darujete žrtvovanje mirovnih daritev Gospodu, jo darujte po lastni volji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Jejte jo isti dan, kot jo darujete in naslednji dan. Če pa kaj ostane do tretjega dne, naj bo to sežgano v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Če bo karkoli pojedeno na tretji dan, je to gnusno; to ne bo sprejeto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Zatorej bo vsakdo, ki to jé, nosil svojo krivičnost, ker je oskrunil posvečeno Gospodovo stvar in ta duša bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Ko žanješ žetev svoje dežele, ne požanji v celoti vogalov svojega polja niti ne zbiraj paberkovanja svoje žetve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Svojega vinograda [po trgatvi] ne boš paberkoval niti ne obiraj vsakega grozda svojega vinograda. Pusti jih za revnega in tujca. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ne kradite, niti ne ravnajte napačno, niti ne lažite drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Pri mojem imenu ne prisegajte lažnivo niti ne skrunite imena svojega Boga. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Svojega soseda ne goljufaj niti ga ne ropaj. Plačila tistega, ki je najet, naj ne ostanejo s teboj vso noč do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Ne preklinjaj gluhega niti ne polagaj kamna spotike pred slepega, temveč se boj svojega Boga. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Na sodbi ne stori nobene nepravičnosti. Ne spoštuj revne osebe niti ne časti mogočne osebe, temveč svojega bližnjega sodi v pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne hodi gor in dol med svojim ljudstvom kakor tožljivec niti ne stoj zoper kri svojega bližnjega. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'V svojem srcu ne sovraži svojega brata. Vsekakor pograjaj svojega bližnjega in ne trpi greha na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ne maščuj se niti ne goji nobene zamere zoper otroke svojega ljudstva, temveč ljubi svojega bližnjega kakor samega sebe. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Držite se mojih zakonov. Svoji živini ne dovoli, da se pari z različno vrsto. Svoje polje ne posej s pomešanim semenom niti naj nate ne pride obleka [hkrati] stkana iz lanu in volne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Kdorkoli meseno leži z žensko, ki je sužnjica, zaročena k soprogu in sploh ni odkupljena niti ji ni dana svoboda; ona naj bo bičana. Ne bosta usmrčena, ker ona ni bila svobodna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'On bo k vratom šotorskega svetišča skupnosti privedel svojo daritev za prestopek Gospodu, namreč ovna za daritev za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Duhovnik naj zanj pred Gospodom za njegov greh opravi spravo z ovnom daritve za prestopek, ki ga je storil, in greh, ki ga je storil, mu bo odpuščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Ko boste prišli v deželo in boste za hrano sadili vse vrste dreves, potem štejte njihov sad kot neobrezan. Tri leta vam bo ta kot neobrezan, ta naj ne bo pojeden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Toda v četrtem letu bo vse njegovo sadje sveto, da s tem hvali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'V petem letu boste jedli od njegovega sadja, da vam bo lahko obrodil svoj donos. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Nobene stvari ne jejte s krvjo niti ne izrekajte uroka niti ne obeležujte časov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ne zaoblite robov svojih glav niti ne kazite robov svoje brade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Na svojem mesu ne boste delali nobenih urezov za mrtve niti si nase ne vtisnite nobenih znamenj. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne onečasti svoje hčere, da ji ne povzročiš, da postane vlačuga, da ne bi dežela padla v vlačugarstvo in bi dežela postala polna zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Držite se mojih šabat in spoštujte moje svetišče. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne obračajte se k tem, ki imajo osebne duhove niti ne povprašujte za čarovniki, da vas ne omadežujejo. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Pred osivelo glavo vstani in spoštuj obraz starca in se boj svojega Boga. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Če tujec začasno prebiva s teboj v tvoji deželi, ga ne zatiraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Temveč naj ti bo tujec, ki prebiva s teboj, kakor nekdo rojen med vami in ljubi ga kakor samega sebe, kajti bili ste tujci v egiptovski deželi. Jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nobene nepravičnosti ne delajte pri sodbi, merilni palici, teži ali meri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Imejte pravične tehtnice, pravične uteži, pravičen škaf in pravičen vrč. Jaz sem Gospod, vaš Bog, ki sem vas privedel iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Zato upoštevajte vse moje zakone in vse moje sodbe ter jih izvršujte. Jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '»Ponovno, Izraelovim otrokom boš rekel: ›Kdorkoli je izmed Izraelovih otrok ali izmed tujcev, ki začasno prebivajo v Izraelu, da izroči karkoli od svojega semena Molohu; ta bo zagotovo usmrčen. Ljudstvo dežele naj ga kamna s kamni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Svoj obraz bom naravnal zoper tega človeka in ga iztrebil izmed njegovega ljudstva, ker je od svojega semena dal Molohu, da omadežuje moje svetišče in da oskruni moje sveto ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Če ljudstvo dežele kakorkoli skrije svoje oči pred možem, ko ta daje svoje seme Molohu in ga ne ubije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'potem bom svoj obraz naravnal zoper tega moža in zoper njegovo družino in izmed njegovega ljudstva odsekal njega in vse, ki se gredo vlačugat za njim, da bi zagrešili vlačugarstvo z Molohom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Duša, ki se obrača za takšnimi, ki imajo osebne duhove in za čarovniki, da se gredo vlačugat za njimi, zoper to dušo celo naravnam svoj obraz in ga bom odsekal izmed njegovega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Posvečujte se torej in bodite sveti, kajti jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Držali se boste mojih zakonov in jih izvrševali. Jaz sem Gospod, ki vas posvečujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kajti vsak, kdor preklinja svojega očeta ali svojo mater, bo zagotovo usmrčen. Preklinjal je svojega očeta ali svojo mater; njegova kri bo nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Moški, ki zagreši zakonolomstvo z ženo drugega moškega, torej ta, ki zagreši zakonolomstvo z ženo svojega bližnjega, zakonolomec in zakonolomka bosta zagotovo usmrčena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Moški, ki leži z ženo svojega očeta, je odkril očetovo nagoto. Oba bosta zagotovo usmrčena. Njuna kri bo nad njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Če moški leži s svojo snaho, bosta zagotovo oba usmrčena. Storila sta zmešnjavo. Njuna kri naj bo nad njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Če moški leži z moškim prav tako, kakor leži z žensko, sta oba zagrešila ogabnost. Zagotovo bosta oba usmrčena. Njuna kri bo nad njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Če moški vzame ženo in njeno mater, je to zlo. Sežgani bodo z ognjem, tako on in oni dve, da tam med vami ne bo zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Če moški leži z živaljo, bo zagotovo usmrčen, žival pa boste zaklali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Če se ženska približa h katerikoli živali in leže dol k njej, boš ubil žensko in žival. Obe bosta zagotovo usmrčeni. Njuna kri bo nad njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Če moški vzame svojo sestro, hčer svojega očeta ali hčer svoje matere in vidi njeno nagoto in ona vidi njegovo nagoto. To je zlobna stvar in oba bosta iztrebljena pred očmi svojega ljudstva. Odkril je nagoto svoje sestre. Nosil bo svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Če bo moški ležal z žensko, ki je bolna in bo odkril njeno nagoto, je odkril njen studenec in ona je odkrila studenec svoje krvi in oba izmed njiju bosta iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Ne boš odkril nagote sestre svoje matere niti sestre svojega očeta, kajti on odkriva svoje bližnje sorodstvo. Oba bosta nosila svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Če bo moški ležal z ženo svojega strica, odkriva nagoto svojega strica. Nosila bosta svoj greh; umrla bosta brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Če bo moški vzel ženo svojega brata, je to nečista stvar. Odkril je nagoto svojega brata; onadva bosta brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Vi se boste torej držali vseh mojih zakonov in vseh mojih sodb in jih izvrševali, da vas dežela, kamor vas privedem, da v njej prebivate, ne izpljune.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ne boste hodili po običajih naroda, ki sem ga pred vami izgnal, kajti zagrešili so vse te stvari in zato so se mi zagnusili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Toda vam sem rekel: ›Podedovali boste njihovo deželo in dal vam jo bom, da jo vzamete v last, deželo kjer tečeta mleko in med.‹ Jaz sem Gospod, vaš Bog, ki vas je oddvojil od drugih ljudstev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Zato boste postavili razliko med čistimi živalmi in nečistimi in med nečisto perjadjo in čisto, in svojih duš ne boste ognusili z živalmi ali s perjadjo ali s katerokoli vrsto žive stvari, ki se plazi po tleh, ki sem jo kot nečisto oddvojil od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Vi mi boste sveti, kajti jaz, Gospod, sem svet in sem vas oddvojil od drugih ljudstev, da bi bili moji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Moški ali ženska, ki ima osebnega duha ali da je čarovnik, bosta zagotovo usmrčena. Kamnajo naj ju s kamni. Njuna kri bo nad njima.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Gospod je rekel Mojzesu: »Govori duhovnikom, Aronovim sinovom in jim reci: ›Nihče naj ne bo omadeževan zaradi mrtvega med svojim ljudstvom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'toda za njegove sorodnike, ki so blizu njemu, to je za njegovo mater, za njegovega očeta, za njegovega sina, za njegovo hčer, za njegovega brata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'in za njegovo sestro devico, ki je blizu njemu, ki nima nobenega soproga; zaradi nje je lahko omadeževan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Toda ta, ki je poglavar med svojim ljudstvom, sebe ne bo omadeževal, da se oskruni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ne bodo delali pleše na svoji glavi, niti ne bodo brili robov svojih brad, niti si ne bodo delali nobenih urezov na mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sveti bodo svojemu Bogu in ne bodo oskrunili imena svojega Boga, kajti darujejo Gospodove daritve, narejene z ognjem in kruh njihovega Boga; zato bodo sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Naj ne vzamejo žene, ki je vlačuga ali oskrunjena niti naj ne vzamejo žene, odslovljene od njenega soproga, kajti on je svet svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Zato ga boš torej posvetil, kajti on daruje kruh tvojega Boga. Tebi bo svet, kajti jaz, Gospod, ki te posvečujem, sem svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Če pa se hči kateregakoli duhovnika oskruni z igranjem vlačuge, je oskrunila svojega očeta. Sežgana naj bo z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Kdor je véliki duhovnik med svojimi brati, na katerega glavo je bilo izlito mazilno olje in ki je uméščen, da si nadene obleke, ne bo odkril svoje glave niti pretrgal svojih oblačil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'niti ne bo šel h kateremukoli truplu niti se ne bo omadeževal zaradi svojega očeta ali zaradi svoje matere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'niti naj ne gre ven iz svetišča niti ne oskruni svetišča svojega Boga, kajti krona mazilnega olja njegovega Boga je na njem. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Ženo bo vzel v njenem devištvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Vdove ali ločene ženske ali oskrunjene ali pocestnice; teh ne bo vzel, temveč bo za ženo vzel devico iz svojega lastnega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Niti med svojim ljudstvom ne bo oskrunil svojega semena, kajti jaz, Gospod, ga posvečujem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '»Govori Aronu, rekoč: ›Kdorkoli je od tvojega semena v njihovih rodovih, ki ima kakršnokoli pomanjkljivost, naj se ne približa, da bi daroval kruh svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Kajti katerikoli človek je, ki ima pomanjkljivost, se ne bo približal. Slep človek ali hrom ali kdor ima ploščat nos ali katerokoli stvar odveč');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ali človek, ki ima zlomljeno nogo ali zlomljeno roko');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ali je grbast ali pritlikav ali, ki ima pomanjkljivost v svojem očesu ali je grintav ali krastav ali ima zmečkana moda;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'noben človek, ki ima iz semena duhovnika Arona pomanjkljivost, ne bo prišel blizu, da daruje Gospodove daritve narejene z ognjem. Ima pomanjkljivost; ta ne bo prišel blizu, da daruje kruh svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Jedel bo kruh svojega Boga, tako od najsvetejšega kakor od svetega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Samo ta ne bo šel noter za zagrinjalo niti prišel blizu k oltarju, ker ima pomanjkljivost, da ne oskruni mojih svetišč, kajti jaz, Gospod, jih posvečujem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Mojzes je to povedal Aronu, njegovim sinovom in vsem Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '»Govori Aronu in njegovim sinovom, da se ločijo od svetih stvari Izraelovih otrok in da ne oskrunijo mojega svetega imena v teh stvareh, ki jih posvetijo meni. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Reci jim: ›Kdorkoli je izmed vsega vašega semena med vašimi rodovi, ki hodi k svetim stvarem, ki jih Izraelovi otroci posvetijo Gospodu in ima na sebi svojo nečistost, bo ta duša iztrebljena izpred moje prisotnosti. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Katerikoli moški iz Aronovega semena je gobavec ali ima tekoč izliv, ta ne bo jedel od svetih stvari, dokler ne bo čist. In kdorkoli se dotakne kakršnekoli stvari, ki je nečista, pri mrtvem ali pri moškem, čigar seme gre od njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ali kdorkoli se dotika katerekoli plazeče stvari, s katero se lahko onečisti, ali človeka, od katerega lahko vzame nečistost, kakršnokoli nečistost ta ima;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'duša, ki se je dotaknila česarkoli takega, bo nečista do večera in ne bo jedla od svetih stvari, dokler svojega mesa ne umije z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Ko sonce zaide bo čist in potem bo jedel od svetih stvari, ker je to njegova hrana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Tega, kar pogine samo od sebe ali je raztrgano z zvermi, ne bo jedel, da samega sebe s tem omadežuje. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Držali se bodo torej moje odredbe, da ne bi za to nosili greha in torej umrli, če to oskrunijo. Jaz, Gospod, jih posvečujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Tam noben tujec ne bo jedel od svete stvari. Duhovnikov začasni prebivalec ali najet služabnik ne bosta jedla od svete stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Toda če duhovnik s svojim denarjem kupi katerokoli dušo, bo ta [duša] jedla od tega in kdor je rojen v njegovi hiši. Jedli bodo od njegove hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Če pa bo duhovnikova hči poročena k tujcu, ona ne bo jedla od daritev svetih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Toda če je duhovnikova hči vdova ali ločena in nima otrok in je vrnjena k hiši svojega očeta kakor v svoji mladosti, bo jedla od hrane svojega očeta, toda noben tujec ne bo jedel od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Če človek nevede jé od svete stvari, potem bo k temu dodal peti del in to bo s sveto stvarjo dal duhovniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Oni ne bodo oskrunili svetih stvari Izraelovih otrok, ki jih darujejo Gospodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'ali jim dopustili, da nosijo krivdo prestopka, kadar jedo njihove svete stvari, kajti jaz, Gospod, jih posvečujem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '»Govori Aronu, njegovim sinovom in vsem Izraelovim otrokom ter jim reci: ›Kdorkoli bo od Izraelove hiše ali od tujcev v Izraelu, ki bo svoj dar daroval za vse svoje zaobljube in za vse svoje prostovoljne daritve, ki jih bodo darovali Gospodu za žgalno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'bodo po lastni volji darovali samca brez pomanjkljivosti od goveda, od ovc ali od koz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Toda karkoli ima pomanjkljivost, tega ne boste darovali, kajti to za vas ne bo sprejemljivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Kdorkoli daruje žrtvovanje mirovnih daritev Gospodu, da izpolni svojo zaobljubo ali prostovoljno daritev v govedu ali ovcah, mora biti to popolno, da bi bilo sprejeto; na tem ne bo nobene pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Slepo ali zlomljeno ali pohabljeno ali kar ima rane, iz katerih se izceja ali grinto ali krasto, teh stvari ne boste darovali Gospodu niti od njih [ne boste] naredili daritve z ognjem na oltarju Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ali bikca ali jagnje, ki ima katerokoli stvar odvečno, ali karkoli manjkajočega v njegovih delih, to lahko daruješ za prostovoljno daritev, toda za zaobljubo to ne bo sprejeto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Gospodu ne boste darovali tega, kar je poškodovano ali zdrobljeno ali zlomljeno ali odrezano niti v svoji deželi ne boste opravili nobenega takšnega darovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Niti iz tujčeve roke ne boste darovali kruha svojega Boga, od kateregakoli izmed njih, ker je v njih njihova izprijenost in pomanjkljivost. Ti ne bodo sprejeti za vas.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '»Kadar je priveden bikec ali ovca ali koza, potem bo ta sedem dni pod materjo. Od osmega dne in naprej pa bo to sprejeto za ognjeno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Naj bo to krava ali ovca, ne boš na isti dan zaklal nje in njenega mladega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Ko boste darovali žrtev zahvaljevanja Gospodu, to darujte po lastni volji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Istega dne bo to pojedeno; ničesar od tega ne boste pustili do naslednjega dne. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Zato se boste držali mojih zapovedi in jih izpolnjevali. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Niti ne boste oskrunili mojega svetega imena, temveč bom jaz posvečen med Izraelovim otroci. Jaz sem Gospod, ki vas posvečuje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'ki vas je privedel ven iz egiptovske dežele, da bi bil vaš Bog. Jaz sem Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '»Govori Izraelovim otrokom in jim reci: › Glede Gospodovih praznovanj, ki jih boste razglašali, da bodo sveti sklici, torej ta so moja praznovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Šest dni naj bo delo opravljeno, toda sedmi dan je šabatni počitek, sveti sklic. Nanj ne boste opravljali nobenega dela. To je šabat Gospodu v vseh vaših prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'To so Gospodova praznovanja, torej sveti sklici, ki jih boste razglašali v določenih časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Na štirinajsti dan prvega meseca zvečer je Gospodova pasha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Na petnajsti dan istega meseca je praznik nekvašenega kruha Gospodu. Sedem dni morate jesti nekvašen kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Na prvi dan boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Temveč boste sedem dni darovali ognjeno daritev Gospodu. Na sedmi dan je sveti sklic; nobenega hlapčevskega dela ne boste opravljali.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '»Govori Izraelovim otrokom in jim reci: ›Ko boste prišli v deželo, ki vam jo dam in boste poželi njeno žetev, potem boste prinesli snop prvih sadov svoje žetve duhovniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Ta bo snop majal pred Gospodom, da bo sprejet za vas. Duhovnik ga bo majal naslednji dan po šabatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Ta dan, ko boste majali snop, boste darovali jagnje brez pomanjkljivosti, prvega leta, za žgalno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Jedilna daritev od tega bo dve desetinki fine moke, umešane z oljem, ognjena daritev v prijeten vonj Gospodu in jedilna daritev od tega bo četrtina vrča vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Vi pa ne boste jedli niti kruha niti popraženega zrnja niti zelenega žitnega klasja, do prav istega dne, ko svojemu Bogu prinesete dar. To bo zakon na veke skozi vaše rodove v vseh vaših prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Šteli si boste od naslednjega dne po šabatu, od dneva, ko ste prinesli snop majalne daritve; sedem šabat bo celota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Torej do naslednjega dne po sedmem šabatu boste šteli petdeset dni in darovali boste novo jedilno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Iz svojih prebivališč boste prinesli dva hleba majanja iz dveh desetink. Ta bosta iz fine moke; spečena bosta s kvasom. To so prvi sadovi Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'S kruhom boste darovali sedem enoletnih jagnjet brez pomanjkljivosti in enega mladega bikca in dva ovna. Ti bodo za žgalno daritev Gospodu, z njihovo jedilno daritvijo in njihovimi pitnimi daritvami, torej ognjeno daritvijo prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Potem boste žrtvovali enega kozlička od koz za daritev za greh in dve jagnjeti prvega leta za žrtvovanje mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Duhovnik jih bo majal s kruhom prvih sadov za majalno daritev pred Gospodom z dvema jagnjetoma. Ti bodo sveti Gospodu za duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Razglašali boste na prav isti dan, da vam bo to lahko sveti sklic. Nobenega hlapčevskega dela ne boste opravljali ta dan. To bo zakon na veke po vseh vaših prebivališčih skozi vaše rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Ko žanjete žetev svoje dežele, med žetvijo ne boš pobral vsega do robov svojega polja niti ne boš zbiral nobenih paberkovanj svoje žetve. Pustil jih boš revnemu in tujcu. Jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '»Govori Izraelovim otrokom, rekoč: ›V sedmem mesecu, na prvi dan meseca, boste imeli šabat, spomin trobljenja trobent, sveti sklic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nobenega hlapčevskega dela ne boste opravljali ta dan, temveč boste darovali ognjeno daritev Gospodu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '»Tudi na deseti dan tega sedmega meseca bo tam dan sprave. To vam bo sveti sklic; in ponižali boste svoje duše in darovali ognjeno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Na ta isti dan ne boste delali nobenega dela, kajti to je dan sprave, da opravite spravo za vas pred Gospodom, vašim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Kajti katerakoli duša bo ta, ki v tem istem dnevu ne bo ponižana, bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Katerakoli duša bo ta, ki na ta isti dan počne kakršnokoli delo, ista duša bo uničena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nobene vrste dela ne boste počeli. To bo zakon na veke skozi vaše rodove v vseh vaših prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'To vam bo šabatni počitek in ponižali boste svoje duše. Na deveti dan meseca zvečer, od večera do večera, boste praznovali svoj šabat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '»Govori Izraelovim otrokom, rekoč: ›Petnajsti dan sedmega meseca bo za sedem dni šotorski praznik Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Na prvi dan bo sveti sklic. Nobenega hlapčevskega dela ne boste opravljali ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sedem dni boste darovali ognjeno daritev Gospodu. Na osmi dan vam bo sveti sklic in darovali boste ognjeno daritev Gospodu. To je slovesen zbor in nobenega hlapčevskega dela ne boste opravljali ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'To so Gospodovi prazniki, ki jih boste razglašali, da bodo sveti sklici, da darujete daritev, narejeno z ognjem Gospodu, žgalno daritev in jedilno daritev, žrtvovanje in pitne daritve, vsako stvar na svoj dan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'poleg Gospodovih šabat in poleg vaših darov in poleg vseh vaših zaobljub in poleg vseh vaših prostovoljnih daritev, ki jih izročite Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Tudi na petnajsti dan sedmega meseca, ko se zberete v sadu dežele, boste sedem dni imeli praznovanje Gospodu. Na prvi dan bo šabat in na osmi dan bo šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Na prvi dan si boste vzeli veje čednih dreves, mladike palmovih dreves, veje debelih dreves in potočnih vrb; in sedem dni se boste veselili pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Sedem dni na leto boste ohranjali praznovanje Gospodu. To bo zakon na veke v vaših rodovih. To boste proslavljali v sedmem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sedem dni boste prebivali v šotorih; vsi, ki so rojeni Izraelci, bodo prebivali v šotorih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'da bodo vaši rodovi lahko vedeli, da sem Izraelovim otrokom dal prebivati v šotorih, ko sem jih privedel iz egiptovske dežele. Jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'In Mojzes je Izraelovim otrokom naznanil praznovanja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '»Zapovej Izraelovim otrokom, da ti prinesejo čistega olja iz stolčenih oliv za svetlobo, da bi svetilke nenehno gorele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Zunaj zagrinjala pričevanja, v šotorskem svetišču skupnosti, bo Aron to nenehno ukazoval od večera do jutra pred Gospodom. To bo zakon na veke v vaših rodovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Svetike bo nenehno oskrboval na čistem svečniku pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Vzel boš fino moko in iz nje spekel dvanajst kolačev. Dve desetinki bosta v enem kolaču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Postavil jih boš v dve vrsti, šest v vrsto, na čisto mizo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Nad vsako vrsto boš dal čisto kadilo, da bo ta lahko na kruhu za spomin, torej ognjena daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Vsak šabat ga bo nenehno postavljal v vrsto pred Gospodom, vzetega od Izraelovih otrok z večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'To bo Aronovo in od njegovih sinov in to bodo jedli na svetem prostoru, kajti to mu je najsvetejše od daritev Gospodu, narejenih z ognjem, z večnim zakonom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Sin Izraelke, katere oče je bil Egipčan, je odšel ven med Izraelove otroke in ta sin izraelske ženske in mož iz Izraela sta se skupaj prepirala v taboru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Sin Izraelke je izrekal bogokletje proti Gospodovemu imenu in preklinjal. Privedli so ga k Mojzesu. (In ime njegove matere je bilo Šelomíta, hči Dibríja, iz Danovega rodu.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Dali so ga pod stražo, da bi jim bil lahko pokazan Gospodov um.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '»Privedite tistega, ki je klel zunaj tabora, in naj vsi, ki so ga slišali, položijo roke na njegovo glavo in naj ga vsa skupnost kamna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Izraelovim otrokom boš govoril, rekoč: ›Kdorkoli preklinja svojega Boga, bo nosil svoj greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Kdor preklinja Gospodovo ime, bo zagotovo usmrčen in zagotovo ga bo vsa skupnost kamnala; tako tujca, kakor tistega, ki je rojen v deželi, ko preklinja Gospodovo ime, bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Kdor ubija kateregakoli človeka, bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Kdor ubije žival, bo to poplačal; žival za žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Če človek povzroči madež na svojem bližnjem; kakor je storil on, tako naj bo to storjeno njemu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'zlom za zlom, oko za oko, zob za zob. Kakor je on na človeku povzročil pomanjkljivost, tako naj bo njemu ponovno storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kdor ubije žival, bo to povrnil, kdor pa ubije človeka, bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Imeli boste eno vrsto postave, prav tako za tujca, kakor za nekoga iz svoje lastne dežele, kajti jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Mojzes je Izraelovim otrokom spregovoril, da naj tistega, ki je preklet, privedejo ven iz tabora in kamnajo s kamni. In Izraelovi otroci so storili tako, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Gospod je na gori Sinaj spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '»Govori Izraelovim otrokom in jim reci: ›Ko pridete v deželo, ki sem vam jo dal, potem bo dežela ohranjala šabat Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Šest let boš sejal svoje polje in šest let boš obrezoval svoj vinograd in zbiral njegov sad,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'toda v sedmem letu bo šabatni počitek deželi, šabat za Gospoda. Niti ne boš sejal svojega polja niti obrezal svojega vinograda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Tega, kar raste samo od sebe od tvoje žetve, ne boš požel niti nabiral grozdja iz svoje neobrezane trte, kajti to je za deželo leto počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Šabatni [pridelek] dežele bo zate hrana; zate, za tvojega služabnika, za tvojo služkinjo, za tvojega najetega služabnika in za tvojega tujca, ki začasno biva s teboj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'in ves njegov narast bo hrana za tvojo živino in za živali, ki so na tvoji zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Štel si boš sedem šabatnih let, sedemkrat sedem let; in obdobje sedmih šabatnih let ti bodi devetinštirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Potem bo šofar jubileja zadonel na deseti dan sedmega meseca. Na dan sprave boste naredili, da zvok šofarja zadoni po vsej vaši deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Posvetili boste petdeseto leto in razglasili svobodo po vsej deželi, vsem njenim prebivalcem. To vam bo jubilej, vi pa se boste vrnili vsak mož k svoji posesti in vrnili se boste vsak mož k svoji družini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Vam bo to petdeseto leto jubilej. Ne boste niti sejali niti želi tega, kar zraste samo od sebe niti nabirali grozdja v njem od vaše neobrezane trte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Kajti to je jubilej; ta vam bo svet. Jedli boste njegov donos iz polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'V letu tega jubileja se bo vsak človek vrnil k svoji posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Če kaj prodaš svojemu bližnjemu, ali kaj kupiš iz roke svojega bližnjega, ne boste zatirali drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Glede na število let po jubileju boš kupil od svojega bližnjega in glede na število let sadov ti bo prodal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Glede na množino let boš povečal njegovo ceno in glede na manjše število let boš zmanjšal njegovo ceno, kajti glede na število let sadov ti jo bo prodal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Zatorej ne boste zatirali drug drugega, temveč se boš bal svojega Boga, kajti jaz sem Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Zatorej boste izpolnjevali moje zakone in se držali mojih sodb in jih izvrševali, in v varnosti boste prebivali v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Dežela bo obrodila svoj sad in jedli boste svoje obilje in v njej varno prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'In če boste rekli: ›Kaj bomo jedli sedmo leto? Glej, ne bomo sejali niti zbrali v našem narastu,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'potem bom v šestem letu zapovedal nad vami svoj blagoslov in ta bo prinesel sad za tri leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Sejali boste osmo leto in še jedli od starih sadov do devetega leta, dokler ne pridejo njeni sadovi, boste jedli iz starih zalog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Dežela naj ne bo prodana na veke, kajti dežela je moja, kajti vi ste tujci in začasni prebivalci z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'In po vsej deželi svoje posesti boste zagotovili odkupitev za deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Če tvoj brat postane reven in je prodal nekaj od svoje posesti in če pride katerikoli njegov sorodnik, da to odkupi, potem bo odkupil to, kar je njegov brat prodal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Če mož nima nikogar, da to odkupi in je sam zmožen to odkupiti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'potem naj prešteje leta od njegove prodaje in povrne presežek človeku, ki mu jo je prodal, da se on lahko vrne v svojo posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Toda če mu on tega ne bo zmožen povrniti, potem bo to, kar je prodal, ostalo v roki tistega, ki je to kupil, do jubilejnega leta. Na jubilej bo odšlo in on se bo vrnil v svojo posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Če mož proda hišo za prebivanje v mestu z obzidjem, potem jo lahko odkupi znotraj celotnega leta potem, ko je bila ta prodana. Znotraj polnega leta jo lahko odkupi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Če pa ta ne bo odkupljena znotraj časa polnega leta, potem bo hiša, ki je v mestu z obzidjem, utrjena na veke tistemu, ki jo je kupil, skozi vse njegove rodove. Ta v jubileju ne bo odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Toda vaške hiše, ki naokoli nimajo obzidja, bodo štete kakor polja dežele. Lahko so odkupljene in na jubilej bodo odšle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Vendar lahko mesta Lévijevcev in hiše mest njihove posesti Lévijevci kadarkoli odkupijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Če človek kupi od Lévijevcev, potem bo hiša, ki je bila prodana in mesto njegove posesti, odšlo v jubilejnem letu, kajti hiše mest Lévijevcev so njihova posest med Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Toda polje predmestij njihovih mest ne more biti prodano, kajti to je njihova neprestana posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Če tvoj brat postane reven in je zaradi tebe propadel, potem ga boš razbremenil; da, čeprav je tujec ali začasni prebivalec, da bo lahko živel s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nobenih obresti ne vzemi od njega ali narasta, temveč se boj svojega Boga, da bo tvoj brat lahko živel s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Svojega denarja mu ne boš dal na obresti niti svojega živeža posodil za dobiček.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Jaz sem Gospod, vaš Bog, ki vas je privedel iz egiptovske dežele, da vam dam kánaansko deželo in, da bi bil vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Če tvoj brat, ki prebiva pri tebi, postane reven in ti je prodan, ga ne boš prisilil, da služi kakor služabnik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'temveč kakor najeti služabnik in kakor začasni prebivalec bo on s teboj in ti bo služil do jubilejnega leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Potem bo odšel od tebe tako on in njegovi otroci z njim in se bo vrnil k svoji lastni družini in se bo vrnil na posest svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Kajti oni so moji služabniki, ki sem jih privedel iz egiptovske dežele. Ne bodo prodani kakor tlačani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nad njim ne boš vladal s krutostjo, temveč se boš bal svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Tako tvoji služabniki in tvoje služabnice, ki jih boš imel, bodo izmed poganov, ki so naokoli vas; izmed njih si kupujte služabnike in služabnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Poleg tega izmed otrok tujcev, ki začasno prebivajo med vami, od njih boste kupovali in od njihovih družin, ki so z vami, ki so jih zaplodili v vaši deželi; in oni bodo vaša posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Vzeli jih boste kakor dediščino za svoje otroke za seboj, da jih podedujejo za posest; ti bodo vaši služabniki na veke, toda nad svojimi brati, Izraelovimi otroki, ne boste s krutostjo vladali drug nad drugim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Če začasni prebivalec ali tujec poleg tebe obogati, tvoj brat, ki prebiva ob njem pa obuboža in se proda tujcu ali začasnemu prebivalcu ob tebi ali rodu tujčeve družine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'potem, ko je ta prodan, je lahko ponovno odkupljen. Eden izmed njegovih bratov ga lahko odkupi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Odkupi ga lahko njegov stric ali sin njegovega strica ali kdorkoli, ki je blizu sorodstva njegovi družini, ga lahko odkupi, ali če je zmožen, se lahko odkupi sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Poračunal bo z njim, ki ga je kupil od leta, ko mu je bil prodan, do jubilejnega leta. Cena njegove prodaje bo glede na število let, glede na čas najetega služabnika bo ta z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Če je zadaj še veliko let, glede na njihovo [število], bo povrnil ceno svoje odkupitve od denarja, za katerega je bil kupljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Če bo preostalo le nekaj let do jubilejnega leta, potem bo z njim obračunal in glede na njegova leta mu bo povrnil ceno njegove odkupitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'In kakor letno najeti služabnik bo z njim, in drugi nad njim v tvojem pogledu ne bo vladal s krutostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Če pa ne bo odkupljen v teh letih, potem bo odšel v jubilejnem letu, tako on in njegovi otroci z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Kajti Izraelovi otroci so mi služabniki; oni so moji služabniki, ki sem jih privedel iz egiptovske dežele. Jaz sem Gospod, vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '»V svoji deželi si ne boste delali nobenih malikov niti rezanih podob, niti si dvigovali stoječe podobe, niti si postavljali kakršnekoli podobe iz kamna, da bi se priklanjali k njej, kajti jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Držali se boste mojih šabat in spoštovali moje svetišče. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Če se ravnate po mojih zakonih in se držite mojih zapovedi in jih izpolnjujete,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'potem vam bom dal dež v pravšnjem obdobju in dežela bo obrodila svoj donos in poljska drevesa bodo obrodila svoj sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Vaša mlatev bo segla do trgatve in trgatev bo segla do časa setve in jedli boste svoj kruh do sitega in varno prebivali v svoji deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'V deželi bom dal mir in ulegli se boste in nihče vas ne bo prestrašil, in odstranil bom zle zveri iz dežele niti skozi vašo deželo ne bo šel meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Pregnali boste svoje sovražnike in oni bodo pred vami padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pet izmed vas jih bo preganjalo sto in sto izmed vas bo desettisoče pognalo v beg in vaši sovražniki bodo pred vami padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Kajti ozrl se bom na vas in vas naredil rodovitne in vas namnožil in z vami vzpostavil svojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Jedli boste staro zalogo in staro boste zaradi nove prinesli naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Med vami bom postavil svoje šotorsko svetišče, in moja duša vas ne bo prezirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Med vami bom hodil in bom vaš Bog in vi boste moje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Jaz sem Gospod, vaš Bog, ki vas je privedel iz egiptovske dežele, da ne bi bili njihovi služabniki; in jaz sem zlomil vezi vašega jarma in storil, da hodite pokonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Toda če mi ne boste prisluhnili in ne boste izpolnjevali vseh teh zapovedi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'in če boste prezirali moje zakone ali če vaša duša prezira moje sodbe, tako da ne boste izpolnjevali vseh mojih zapovedi, temveč da prelamljate mojo zavezo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'bom tudi jaz to storil vam; čez vas bom določil celo strahoto in uničenje in gorečo vročico, ki bo použila oči in povzročila bridkost srca, in svoje seme boste sejali zaman, kajti pojedli ga bodo vaši sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Svoj obraz bom naravnal zoper vas in vi boste umorjeni pred svojimi sovražniki. Tisti, ki jih sovražite, bodo kraljevali nad vami in bežali boste, ko vas nihče ne zasleduje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'In če mi zaradi vsega tega še ne boste hoteli prisluhniti, potem vas bom zaradi vaših grehov sedemkrat bolj kaznoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Zlomil bom ponos vaše moči in vaše nebo bom naredil kakor železo in vašo zemljo kakor bron,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'in vaša moč bo porabljena v prazno, kajti vaša dežela ne bo obrodila svojega donosa niti drevesa dežele ne bodo obrodila svojega sadja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Če hodite nasprotno meni in mi ne boste prisluhnili, bom glede na vaše grehe nad vas privedel sedemkrat več nadlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Prav tako bom med vas poslal divje zveri, ki vas bodo oropale vaših otrok in vam uničile vašo živino in vas naredile maloštevilne, in vaše visoke poti bodo zapuščene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Če ne boste po meni poboljšani s temi stvarmi, temveč boste hodili nasprotno meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'potem bom tudi jaz hodil nasprotno vam in vas še sedemkrat kaznoval za vaše grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Nad vas bom privedel meč, ki bo maščeval spor moje zaveze, in ko boste zbrani skupaj znotraj svojih mest, bom med vas poslal kužno bolezen, vi pa boste izročeni v sovražnikovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'In ko zlomim oporo vašega kruha, bo deset žensk peklo vaš kruh v eni peči in vaš kruh vam bodo ponovno izročali po teži, in jedli boste, pa ne boste nasičeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Če mi zaradi vsega tega ne boste prisluhnili, temveč boste hodili nasprotno meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'potem bom tudi jaz v razjarjenosti hodil nasprotno vam, in jaz, celo jaz, vas bom sedemkrat kaznoval za vaše grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Jedli boste meso svojih sinov in meso svojih hčera boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Uničil bom vaše visoke kraje in posekal vaše podobe in vaša trupla vrgel na trupla vaših malikov in moja duša vas bo prezirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Vaša mesta bom opustošil in vaša svetišča privedel do uničenja in ne bom vonjal vonja vaših prijetnih dišav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Deželo bom privedel v opustošenje, in vaši sovražniki, ki v njej prebivajo, bodo osupli nad tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Razkropil vas bom med pogane in za vami bom izvlekel meč, in vaša dežela bo zapuščena in vaša mesta opustošena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Potem bo zemlja uživala vse svoje šabate, dokler ta leži zapuščena in ste vi v deželi svojih sovražnikov, torej takrat bo dežela počivala in uživala svoje šabate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Dokler ta leži zapuščena, bo počivala, ker ni počivala na vaše šabate, ko ste prebivali na njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Nad tiste, ki so izmed vas ostali živi, bom v deželi njihovih sovražnikov v njihova srca poslal slabotnost, in zvok majajočega lista jih bo pregnal; pobegnili bodo kakor bežanje pred mečem; padli bodo, ko jih nihče ne zasleduje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Padli bodo drug na drugega, kakor bi bilo to pred mečem, ko nihče ne zasleduje in nobene moči ne boste imeli, da obstanete pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Propadli boste med pogani in dežela vaših sovražnikov vas bo požrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Tisti, ki so ostali izmed vas, bodo hirali v svoji krivičnosti v deželah svojih sovražnikov in tudi v krivičnostih svojih očetov bodo hirali z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Če bodo priznali svojo krivičnost in krivičnost svojih očetov, s svojimi prestopki, ki so jih zagrešili zoper mene in da so tudi hodili nasprotno meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'in da sem tudi jaz hodil nasprotno njim in jih privedel v deželo njihovih sovražnikov; če bodo potem njihova neobrezana srca ponižana in oni potem sprejmejo kaznovanje svoje krivičnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'potem se bom spomnil svoje zaveze z Jakobom in tudi svoje zaveze z Izakom in tudi svoje zaveze z Abrahamom se bom spomnil, in spomnil se bom dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Tudi dežela bo od njih zapuščena in uživala bo svoje šabate, medtem ko brez njih leži zapuščena, oni pa bodo sprejeli kaznovanje svoje krivičnosti. Ker, celo ker so prezirali moje sodbe in ker je njihova duša prezirala moje zakone.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'In kljub vsemu temu, ko bodo v deželi svojih sovražnikov, jih ne bom zavrgel niti jih ne bom preziral, da bi jih popolnoma uničil in da bi prelomil svojo zavezo z njimi, kajti jaz sem Gospod, njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Temveč se bom zaradi njih spomnil zaveze njihovih prednikov, ki sem jih privedel iz egiptovske dežele pred očmi poganov, da bi bil lahko njihov Bog. Jaz sem Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'To so zakoni in sodbe ter postave, ki jih je po Mojzesovi roki Gospod sklenil med njim in Izraelovimi otroki na gori Sinaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '»Govori Izraelovim otrokom in jim reci: ›Kadar bo kak moški naredil edinstveno zaobljubo bodo osebe za Gospoda po tvoji oceni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Tvoja ocena bo od moških od dvajset let starosti, celo do šestdesetega leta starosti, bo tvoja ocena petdeset šeklov srebra, po svetiščnem šeklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Če bo to ženska, potem bo tvoja ocena trideset šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Če bo ta star od petih let do dvajsetih let starosti, potem bo tvoja ocena za moškega dvajset šeklov, za žensko pa deset šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Če bo ta star od meseca celo do petega leta starosti, potem bo tvoja ocena za moškega pet šeklov srebra, za žensko pa bo tvoja ocena tri šekle srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Če bo ta od šestdesetega leta starosti in navzgor; če bo to moški, potem bo tvoja ocena petnajst šeklov, za žensko pa deset šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Toda če je revnejši kakor tvoja ocena, potem se bo predstavil pred duhovnikom in duhovnik ga bo ocenil. Glede na svojo zmožnost, ki jo je zaobljubil, ga bo duhovnik ocenil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Če bo to žival, od česar mož privede dar Gospodu, bo vse kar katerikoli človek daje od takšnega Gospodu, sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Tega ne bo predrugačil niti spremenil, dobro za slabo ali slabo za dobro. Če bo ta sploh zamenjal žival za žival, potem postaneta ta in njena zamenjava sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Če bo to kakršnakoli nečista žival, od katere ne darujejo daru Gospodu, potem bo žival predstavil pred duhovnikom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'in duhovnik jo bo ocenil, naj bo ta dobra ali slaba. Kakor jo ti oceniš, ki si duhovnik, tako bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Toda če jo on sploh hoče odkupiti, potem bo tvoji oceni dodal peti del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Ko bo mož svojo hišo posvetil, da bo sveta Gospodu, potem jo bo duhovnik ocenil, bodisi je dobra ali slaba. Kakor bo duhovnik to ocenil, tako bo to stalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Če bo tisti, ki jo je posvetil, odkupil svojo hišo, potem bo k njej dodal peti del denarja tvoje ocene in ta bo njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Če bo mož posvetil Gospodu neki del od polja ali njegove posesti, potem bo tvoja ocena glede na njegovo seme. Tovor ječmenovega semena bo ocenjen za petdeset šeklov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Če svoje polje posveti od jubilejnega leta, glede na tvojo oceno, bo to stalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Toda če svoje polje posveti po jubileju, potem mu bo duhovnik računal denar glede na leta, ki preostanejo, celo do jubilejnega leta in to bo zmanjšano od tvoje ocene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Če bo tisti, ki je polje posvetil, le-tega na kakršenkoli način odkupil, potem bo k njemu dodal peti del od denarja tvoje ocene in to mu bo zajamčeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Če pa ne bo odkupil polja ali če je polje prodal drugemu možu, le-to ne bo več odkupljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Toda polje, ko gre le-to ven v jubileju, bo sveto Gospodu kakor posvečeno polje; njegova posest bo duhovnikova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Če mož posveti Gospodu polje, ki ga je kupil, ki ni izmed polj njegove posesti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'potem mu bo duhovnik računal vrednost tvoje ocene, torej na jubilejno leto. In on bo dal tvojo oceno na ta dan, kakor sveto stvar Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'V jubilejnem letu bo polje vrnil tistemu, od katerega je bilo to kupljeno, torej tistemu, ki mu je pripadala posest dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Vse tvoje ocene bodo glede na svetiščni šekel. Dvajset ger bo šekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Samo prvenca izmed živali, ki naj bi bil Gospodov prvenec, ne bo noben mož posvetil, bodisi je to vol ali ovca. To je Gospodovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Če pa je od nečiste živali, potem ga bo odkupil glede na tvojo oceno in bo dodal peti del od tega k temu. Ali če to ne bo odkupljeno, potem bo to prodano glede na tvojo oceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Vendar nobena posvečena stvar, ki jo mož posveti Gospodu od vsega kar ima, tako od človeka in živali in od polja njegove posesti, ne bo prodana ali odkupljena. Vsaka posvečena stvar je najsvetejša Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ničesar posvečenega, kar bo posvečeno od ljudi, ne bo odkupljeno, temveč bo zagotovo usmrčeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Vsa desetina dežele, bodisi od semena dežele ali sadu drevesa, je Gospodova. To je sveto Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Če mož sploh hoče odkupiti od svojih desetin, bo temu dodal svoj peti del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Glede desetine od tropa ali od črede, od česarkoli kar gre pod palico, desetina bo sveta Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Ne bo iskal, če je to dobro ali slabo niti tega ne bo zamenjal. Če pa to vendar zamenja, potem bosta tako to kakor njegova zamenjava, sveta; to ne bo odkupljeno.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'To so zapovedi, ki jih je Gospod zapovedal Mojzesu za Izraelove otroke na gori Sinaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Gospod je govoril Mojzesu v Sinajski divjini, v šotorskem svetišču skupnosti, na prvi dan drugega meseca, v drugem letu, potem ko so prišli iz egiptovske dežele, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '»Popišite glave vse skupnosti Izraelovih otrok, po njihovih družinah, po hiši njihovih očetov, s številom njihovih imen, vsakega moškega po njihovih glavah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'od dvajsetih let starosti in naprej, vse, ki so zmožni iti na vojsko v Izraelu. Ti in Aron jih preštejta po njihovih vojskah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'In s teboj bo tam mož iz vsakega rodu; vsak poglavar svoje očetovske hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'To so imena mož, ki bodo stali z vami. Iz Rubenovega rodu: Elicúr, Šedeúrjev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Iz Simeona: Šelumiél, Curišadájev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Iz Juda: Nahšón, Aminadábov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Iz Isahárja: Netanél, Cuárjev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Iz Zábulona: Eliáb, Helónov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Izmed Jožefovih otrok: iz Efrájima Elišamá, Amihúdov sin; iz Manáseja Gamliél, Pedacúrjev sin;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'iz Benjamina Abidán, Gideoníjev sin;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'iz Dana Ahiézer, Amišadájev sin;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'iz Aserja Pagiél, Ohránov sin;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'iz Gada Eljasáf, Deguélov sin;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'iz Neftálija Ahirá, Enánov sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ti so bili ugledni izmed skupnosti, princi iz rodov svojih očetov, glave tisočim v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mojzes in Aron sta vzela te može, ki so bili določeni po njihovih imenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Na prvi dan drugega meseca so zbrali vso skupnost in razglasili njihovo poreklo po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, po njihovih glavah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Kakor je Gospod zapovedal Mojzesu, tako jih je preštel v Sinajski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Otroke Rubena, Izraelovega najstarejšega sina, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, po njihovih glavah, vsakega moškega od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'tistih, ki so bili izmed njih prešteti, torej iz Rubenovega rodu, je bilo šestinštirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Od Simeonovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, tistih, ki so bili izmed njih prešteti, glede na število imen, po njihovih glavah, vsak moški od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'tistih, ki so bili izmed njih prešteti, torej iz Simeonovega rodu, je bilo devetinpetdeset tisoč tristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Od Gadovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'tistih, ki so bili izmed njih prešteti, torej iz Gadovega rodu, je bilo petinštirideset tisoč šeststo petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Od Judovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'tistih, ki so bili izmed njih prešteti, torej iz Judovega rodu, je bilo štiriinsedemdeset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Od Isahárjevih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'tistih, ki so bili izmed njih prešteti, torej iz Isahárjevega rodu, je bilo štiriinpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Od Zábulonovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'tistih, ki so bili izmed njih prešteti, torej iz Zábulonovega rodu, je bilo sedeminpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Od Jožefovih otrok, namreč od Efrájimovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'tistih, ki so bili izmed njih prešteti, torej iz Efrájimovega rodu, je bilo štirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Od Manásejevih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'tistih, ki so bili izmed njih prešteti, torej iz Manásejevega rodu, je bilo dvaintrideset tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Od Benjaminovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'tistih, ki so bili izmed njih prešteti, torej iz Benjaminovega rodu, je bilo petintrideset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Od Danovih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'tistih, ki so bili izmed njih prešteti, torej iz Danovega rodu, je bilo dvainšestdeset tisoč sedemsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Od Aserjevih otrok, po njihovih rodovih, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'tistih, ki so bili izmed njih prešteti, torej iz Aserjevega rodu je bilo enainštirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Od Neftálijevih otrok, skozi njihove rodove, po njihovih družinah, po hiši njihovih očetov, glede na število imen, od dvajsetih let starosti in naprej, vse, ki so bili zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'tistih, ki so bili izmed njih prešteti, torej iz Neftálijevega rodu, je bilo triinpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'To so tisti, ki so bili prešteti, ki so jih Mojzes, Aron in Izraelovi princi prešteli, ki jih je bilo dvanajst mož. Vsak je bil za hišo svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Tako je bilo vseh teh, ki so bili prešteti izmed Izraelovih otrok, po hiši njihovih očetov, od dvajsetih let starosti in naprej, vseh, ki so bili v Izraelu zmožni iti na vojsko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'torej vseh, ki so bili prešteti, je bilo šeststo tisoč in tri tisoč petsto petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Toda Lévijevci, po rodu njihovih očetov, niso bili šteti mednje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Kajti Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '»Samo rodu Lévijevcev ne boš preštel niti ne popiši njihovih glav izmed Izraelovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'temveč boš Lévijevce določil nad šotorskim svetiščem pričevanja in nad vsemi njegovimi posodami in nad vsemi stvarmi, ki temu pripadajo. Nosili bodo šotorsko svetišče in vse njegove posode in mu bodo služili in se utaborili okoli šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Ko se šotorsko svetišče odpravi naprej, ga bodo Lévijevci razdrli, in ko naj bi bilo šotorsko svetišče postavljeno, ga bodo Lévijevci postavili. Tujec, ki se približa, pa bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Izraelovi otroci bodo postavili svoje šotore, vsak mož pri svojem lastnem taboru in vsak mož pri svojem lastnem praporu, po svojih vojskah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Toda Lévijevci bodo taborili naokoli šotorskega svetišča pričevanja, da ne bo besa nad skupnostjo Izraelovih otrok in Lévijevci bodo zadolženi za šotorsko svetišče pričevanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Izraelovi otroci so storili glede na vse, kar je Gospod zapovedal Mojzesu, tako so storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '»Vsak mož izmed Izraelovih otrok se bo utaboril pri svojem lastnem praporu z znamenjem svoje očetne hiše. Taborili bodo daleč proč od šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Na vzhodni strani, proti sončnemu vzhodu, bodo taborili tisti od prapora Judovega tabora, po vseh svojih vojskah in Aminadábov sin Nahšón bo poveljnik Judovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo štiriinsedemdeset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Tisti, ki se utaborijo poleg njega bodo iz Isahárjevega rodu in Cuárjev sin Netanél bo poveljnik Isahárjevih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo štiriinpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Potem Zábulonov rod, in Helónov sin Eliáb bo poveljnik Zábulonovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo sedeminpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Vseh, ki so bili prešteti v Judovem taboru, je bilo sto šestinosemdeset tisoč štiristo, po njihovih vojskah. Ti bodo odpotovali prvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Na južni strani bo prapor Rubenovega tabora, glede na njihove vojske in poveljnik Rubenovih otrok bo Šedeúrjev sin Elicúr.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Njegove vojske in tistih, ki so bili prešteti, je bilo šestinštirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Tisti, ki taborijo poleg njega, bodo iz Simeonovega rodu in poveljnik Simeonovih otrok bo Curišadájev sin Šelumiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo devetinpetdeset tisoč tristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Potem Gadov rod in poveljnik Gadovih sinov bo Reguélov sin Eljasáf.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo petinštirideset tisoč šeststo petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Vseh, ki so bili v Rubenovem taboru prešteti po njihovih vojskah, je bilo sto enainpetdeset tisoč štiristo petdeset. Odpotovali bodo drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Potem se bo šotorsko svetišče skupnosti odpravilo naprej, s taborom Lévijevcev v sredi tabora. Kakor taborijo, tako se bodo odpravili naprej, vsak mož na svojem mestu, po svojih praporih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Na zahodni strani bo prapor Efrájimovega tabora glede na njihove vojske in poveljnik Efrájimovih sinov bo Amihúdov sin Elišamá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo štirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Poleg njega bo Manásejev rod in poveljnik Manásejevih otrok bo Pedacúrjev sin Gamliél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo dvaintrideset tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Potem Benjaminov rod in poveljnik Benjaminovih otrok bo Gideoníjev sin Abidán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo petintrideset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Vseh, ki so bili po njihovih vojskah prešteti iz Efrájimovega tabora, je bilo sto osem tisoč sto. Naprej bodo šli tretji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Prapor Danovega tabora bo na severni strani po njihovih vojskah in poveljnik Danovih otrok bo Amišadájev sin Ahiézer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo dvainšestdeset tisoč sedemsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Tisti, ki taborijo poleg njega, bodo iz Aserjevega rodu in poveljnik Aserjevih otrok bo Ohránov sin Pagiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo enainštirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Potem Neftálijev rod in poveljnik Neftálijevih otrok bo Enánov sin Ahirá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Njegove vojske in tistih, ki so bili izmed njih prešteti, je bilo triinpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Vseh tistih, ki so bili prešteti v Danovem taboru, je bilo sto sedeminpetdeset tisoč šeststo. Ti bodo s svojimi prapori šli zadnji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'To so tisti, ki so bili prešteti izmed Izraelovih otrok, po hiši njihovih očetov. Vseh tistih, ki so bili prešteti iz taborov, po njihovih vojskah, je bilo šeststo tri tisoč petsto petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Toda Lévijevci niso bili šteti med Izraelove otroke, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Izraelovi otroci so storili glede na vse, kar je Gospod zapovedal Mojzesu, tako so se utaborili po svojih praporih in tako so se odpravili, vsakdo po svojih družinah, glede na hišo njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Tudi to so rodovi Arona in Mojzesa na dan, ko je Gospod govoril z Mojzesom na gori Sinaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'To so imena Aronovih sinov: prvorojenec Nadáb in Abihú, Eleazar ter Itamár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'To so imena Aronovih sinov, duhovnikov, ki so bili maziljeni, ki jih je uméstil, da služijo v duhovniški službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadáb in Abihú sta umrla pred Gospodom, ko sta v Sinajski divjini, pred Gospodom, darovala tuj ogenj in nista imela nobenih otrok. Eleazar in Itamár pa sta služila v duhovniški službi v pogledu Arona, njunega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '»Lévijev rod privedi bliže in postavi jih pred duhovnika Arona, da mu bodo lahko služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Pazili bodo na njegovo zadolžitev in zadolžitev celotne skupnosti pred šotorskim svetiščem skupnosti, da opravljajo službo šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Pazili bodo na vse priprave šotorskega svetišča skupnosti in zadolžitev Izraelovih otrok, da opravljajo službo šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Lévijevce boš dal Aronu in njegovim sinovom. Oni so izmed Izraelovih otrok v celoti izročeni njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Določil boš Arona in njegova sinova in onadva bosta pazila na duhovniško službo, tujec pa, ki pride blizu, bo usmrčen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '»Glej, jaz sem vzel Lévijevce izmed Izraelovih otrok namesto vsega prvorojenega, kar odpre maternico med Izraelovimi otroki, zato bodo Lévijevci moji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'ker so vsi prvorojenci moji. Kajti na dan, ko sem udaril vse prvorojeno v egiptovski deželi, sem si posvetil vse prvorojeno v Izraelu, tako človeka kakor žival; moji bodo. Jaz sem Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Gospod je Mojzesu spregovoril v Sinajski divjini, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '»Preštej Lévijeve otroke po hiši njihovih očetov, po njihovih družinah; štel boš vsakega moškega, starega en mesec in več.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Mojzes jih je preštel glede na Gospodovo besedo, kakor mu je bilo zapovedano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'To so bili Lévijevi sinovi po njihovih imenih: Geršón, Kehát in Merarí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'To so imena Geršónovih sinov po njihovih družinah: Libni in Šimí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kehátovi sinovi po njihovih družinah: Amrám, Jichár, Hebrón in Uziél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Meraríjevi sinovi po njihovih družinah: Mahlí in Muší. To so družine Lévijevcev, glede na hišo njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Od Geršóna je bila družina Libníjevcev in družina Šimíjevcev. To so družine Geršónovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Tistih, ki so bili izmed njih prešteti, glede na število vseh moških, starih en mesec in več, torej tistih, ki so bili izmed njih prešteti, je bilo sedem tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Družine Geršónovcev bodo taborile za šotorskim svetiščem proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Poglavar očetove hiše Geršónovcev bo Eljasáf, Laélov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Zadolžitev Geršónovih sinov v šotorskem svetišču skupnosti bo šotorsko svetišče in šotor, njegovo pokrivalo, tanka preproga za vrata šotorskega svetišča skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'tanke preproge dvora, zavesa za vrata dvora, ki je ob šotorskem svetišču in naokoli ob oltarju in njene vrvice za vse vrste dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Od Keháta je bila družina Amrámovcev, družina Jichárovcev, družina Hebróncev in družina Uziélovcev; to so družine Kehátovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Število vseh moških, starih en mesec in več, je bilo osem tisoč šeststo, ki pazijo na zadolžitev svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Družine Kehátovih sinov bodo taborile na strani šotorskega svetišča proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Poglavar očetove hiše Kehátovih družin bo Uziélov sin Elicafán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Njihova zadolžitev bo skrinja, miza, svečnik, oltarji, posode svetišča, s katerimi služijo, tanka preproga in vse delo pri tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Eleazar, sin duhovnika Arona, bo vodja nad vodji Lévijevcev in imel bo nadzor nad tistimi, ki pazijo na zadolžitev svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Meraríja je bila družina Mahlíjevcev in družina Mušíjevcev; to so družine Meraríjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Tistih, ki so bili izmed njih prešteti, glede na število, vseh moških starih en mesec in več, je bilo šest tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Vodja hiše očetov Meraríjeve družine je bil Abihájilin sin Curiél; ti bodo taborili na strani šotorskega svetišča proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Pod oskrbo in zadolžitvijo Meraríjevih sinov bodo deske šotorskega svetišča, njegovi zapahi, njegovi stebri, njegovi podstavki in vse njegove posode in vse, kar služi k temu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'in stebri dvora naokoli, njihovi podstavki, njihovi količki in njihove vrvice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Toda tisti, ki so se utaborili pred šotorskim svetiščem proti vzhodu, torej pred šotorskim svetiščem skupnosti proti vzhodu, bodo Mojzes, Aron in njegovi sinovi, ki pazijo na zadolžitev svetišča, za službo Izraelovih otrok. Tujec, ki pride blizu, pa bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Vseh, ki so bili prešteti izmed Lévijevcev, ki sta jih Mojzes in Aron preštela na Gospodovo zapoved, po njihovih družinah, vseh moških starih en mesec in več, je bilo dvaindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Gospod je rekel Mojzesu: »Preštej vse prvorojene moške izmed Izraelovih otrok, stare en mesec in več in vzemi število njihovih imen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Zame boš vzel Lévijevce (Jaz sem Gospod) namesto vseh prvorojencev med Izraelovimi otroki in živino Lévijevcev namesto vseh prvencev izmed živine Izraelovih otrok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Mojzes jih je preštel, kakor mu je zapovedal Gospod, vse prvorojene med Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Vseh prvorojenih moških po številu imen, starih en mesec in več, izmed tistih, ki so bili izmed njih prešteti, je bilo dvaindvajset tisoč dvesto triinsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '»Vzemi Lévijevce namesto vseh prvorojencev med Izraelovimi otroki in živino Lévijevcev namesto njihove živine, in Lévijevci bodo moji. Jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Za tiste, ki naj bi bili odkupljeni izmed dvesto triinsedemdesetih prvorojencev Izraelovih otrok, ki jih je več kot Lévijevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'boš vzel pet šeklov po glavi, po svetiščnem šeklu jih boš vzel; (šekel je dvajset ger).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Denar, s katerim naj bo preostanek odkupljen, pa boš dal Aronu in njegovim sinovom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Mojzes je vzel odkupitveni denar od tistih, ki so preostali nad tistimi, ki so bili odkupljeni po Lévijevcih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od prvorojencev Izraelovih otrok je vzel denar: tisoč tristo petinšestdeset šeklov po svetiščnem šeklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Mojzes je denar od tistih, ki so bili odkupljeni, dal Aronu in njegovim sinovom, glede na Gospodovo besedo, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '»Popišita glave sinov Kehátovih sinov, izmed Lévijevih sinov, po njihovih družinah, po hišah njihovih očetov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'od tridesetega leta starosti in navzgor, celo do petdesetega leta starosti, vse, ki vstopijo v služenje, da opravljajo delo v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'To bo služba Kehátovih sinov v šotorskem svetišču skupnosti glede najsvetejših stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Ko se tabor odpravi naprej, bodo prišli Aron in njegovi sinovi in sneli zaslanjajoče zagrinjalo in z njim pokrili skrinjo pričevanja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'in nanjo bodo položili pokrivalo iz jazbečevih kož in nad tem bodo razgrnili pregrinjalo, v celoti iz modre in vanjo vstavili njena drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Na mizi hlebov navzočnosti bodo razprostrli pregrinjalo iz modre in nanjo položili sklede, žlice, skledice in pokrivala, da jih s tem pokrijejo, in na njej bo neprenehoma kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Nanjo bodo razprostrli pregrinjalo iz škrlata in isto pokrili s pokrivalom iz jazbečevih kož in vanjo vstavili njena drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Vzeli bodo pregrinjalo iz modrega in pokrili svečnik svetlobe in njegove svetilke, njegove utrinjače, njegove pladnje za utrinke in vse njegove oljne posode, s katerimi mu služijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'in z vsemi posodami ga bodo položili znotraj pokrivala iz jazbečevih kož in ga položili na nosila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Nad zlatim oltarjem bodo razprostrli modro pregrinjalo in ga pokrili s pokrivalom iz jazbečevih kož in vstavili njegova drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Vzeli bodo vse priprave služenja, s katerimi služijo v svetišču in jih položili v modro pregrinjalo in jih pokrili s pokrivalom iz jazbečevih kož in jih bodo dali na nosila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Iz oltarja bodo vzeli proč pepel in nanj razprostrli vijolično pregrinjalo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'in nanj bodo položili vse njegove posode, s katerimi služijo okrog njega, torej kadilnice, kavlje za meso, lopate, umivalnike, vse oltarne posode, in nanje bodo razprostrli pokrivalo iz jazbečevih kož in vstavili njegova drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Ko Aron in njegovi sinovi končajo s pokrivanjem svetišča in vseh posod svetišča, ko se bo tabor odpravil naprej, potem bodo prišli Kehátovi sinovi, da ga nosijo, toda ne bodo se dotaknili nobene svete stvari, da ne umrejo. Te stvari so breme Kehátovih sinov v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'K služenju Aronovega sina Eleazarja, duhovnika, spada olje za svetlobo, dišeče kadilo, dnevna jedilna daritev, mazilno olje in nadzor vsega svetišča in vsega, kar je v njem, v svetišču in v njegovih posodah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '»Ne odsekajta rodu družin Kehátovcev izmed Lévijevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'temveč jim tako storite, da bodo lahko živeli in ne umrli, ko se približajo najsvetejšim stvarem. Aron in njegovi sinovi bodo vstopili in določili vsakega k njegovi službi in k njegovemu bremenu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'toda ne bodo vstopili, da bi videli, ko se svete stvari pokrivajo, da ne umrejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '»Popiši tudi glave Geršónovih sinov, po hišah njihovih očetov, po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Preštel jih boš od tridesetega leta starosti in navzgor, do petdesetega leta starosti; vse, ki vstopijo, da opravijo služenje, da opravijo delo v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'To je služba družin Geršónovcev, da služijo in za bremena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Nosili bodo zavese šotorskega svetišča in šotorsko svetišče skupnosti, njegovo pokrivalo, pokrivalo iz jazbečevih kož, ki je nad njim, tanko preprogo za vrata šotorskega svetišča skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'tanke preproge dvora, tanko preprogo za vrata velikih vrat dvora, ki je pri šotorskem svetišču in pri oltarju naokoli, njihove vrvice in vse priprave njihove službe in vse, kar je narejeno zanje; tako bodo služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Po določitvi Arona in njegovih sinov bo vsa služba Geršónovih sinov v vseh njihovih bremenih in v vseh njihovih službah, in v stražo jim boste določili vsa njihova bremena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'To je služba družin Geršónovih sinov v šotorskem svetišču skupnosti in njihova straža bo pod roko Itamárja, sina duhovnika Arona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Kar se tiče Meraríjevih sinov, jih boš preštel po njihovih družinah, po hiši njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Preštel jih boš od tridesetega leta starosti in navzgor, torej do petdesetega leta starosti, vsakega, ki vstopa v službo, da opravlja delo šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'To je zadolžitev njihovega bremena, glede na vso njihovo službo v šotorskem svetišču skupnosti: deske šotorskega svetišča, njegove zapahe, njegove stebre, njegove podstavke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'stebre dvora naokoli, njegove podstavke, njegove količke, njihove vrvice z vsemi njihovimi pripravami in z vso njihovo službo, in po imenu boš določil priprave zadolžitve njihovega bremena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'To je služba družin Meraríjevih sinov, glede na vso njihovo službo v šotorskem svetišču skupnosti, pod roko Itamárja, sina duhovnika Arona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Mojzes, Aron in vodje skupnosti so prešteli sinove Kehátovcev po njihovih družinah in po hiši njihovih očetov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'od tridesetega leta starosti in navzgor, torej do petdesetega leta starosti, vsakega, ki vstopa v službo zaradi dela v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Tistih, ki so bili izmed njih prešteti, po njihovih družinah, je bilo dva tisoč sedemsto petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'To so bili tisti, ki so bili prešteti izmed družin Kehátovcev, vsi, ki lahko opravljajo službo v šotorskem svetišču skupnosti, ki sta jih Mojzes in Aron preštela glede na Gospodovo zapoved po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Tistih, ki so bili prešteti izmed Geršónovih sinov, po njihovih družinah in po hiši njihovih očetov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'od tridesetega leta starosti in navzgor, torej do petdesetega leta starosti, vsakega, ki vstopa v službo zaradi dela v šotorskem svetišču skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'torej tistih, ki so bili izmed njih prešteti, po njihovih družinah, po hiši njihovih očetov, je bilo dva tisoč šeststo trideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'To so tisti, ki so bili prešteti izmed družin Geršónovih sinov, izmed vseh, ki lahko opravljajo službo v šotorskem svetišču skupnosti, ki sta jih Mojzes in Aron preštela glede na Gospodovo zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Tistih, ki so bili prešteti izmed družin Meraríjevih sinov, po njihovih družinah, po hiši njihovih očetov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'od tridesetega leta starosti in navzgor, torej do petdesetega leta starosti, vsakega, ki vstopa v službo zaradi dela v šotorskem svetišču skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'torej tistih, ki so bili izmed njih prešteti, po njihovih družinah, je bilo tri tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'To so tisti, ki so bili prešteti izmed družin Meraríjevih sinov, ki sta jih Mojzes in Aron preštela glede na Gospodovo besedo, po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Vseh tistih, ki so bili prešteti izmed Lévijevcev, ki so jih Mojzes, Aron in Izraelovi vodje prešteli, po njihovih družinah in po hiši njihovih očetov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'od tridesetega leta starosti in navzgor, torej do petdesetega leta starosti, vsakega, ki je prišel, da opravlja službo služenja in službo bremena v šotorskem svetišču skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'torej tistih, ki so bili izmed njih prešteti, je bilo osem tisoč petsto osemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Glede na Gospodovo zapoved so bili prešteti po Mojzesovi roki, vsak glede na svojo službo in glede na svoje breme. Tako jih je preštel, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '»Zapovej Izraelovim otrokom, da naj iz tabora odstranijo vsakega gobavca in vsakega, ki ima izliv in vsakogar, ki je omadeževan z mrtvim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tako moškega in žensko boste poslali ven. Zunaj tabora jih boste poslali, da ne omadežujejo svojih taborov, v sredi katerih prebivam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Izraelovi otroci so tako storili in jih poslali ven, zunaj tabora. Kakor je Gospod spregovoril Mojzesu, tako so Izraelovi otroci storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '»Govori Izraelovim otrokom: ›Kadar bosta moški ali ženska zagrešila kakršenkoli greh, ki ga ljudje zagrešijo, da storita prestopek zoper Gospoda in da je oseba kriva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'potem bosta priznala svoj greh, ki sta ga storila. In svoj prestopek bo poplačal z glavnico in ji dodal peti del od tega in to bo dal tistemu, zoper katerega je kršil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Toda če človek nima nobenega sorodnika, da mu povrne prestopek, naj prestopek poplača Gospodu, celo duhovniku, poleg ovna sprave, s čimer bo zanj opravljena sprava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Vsaka daritev vseh svetih stvari Izraelovih otrok, ki jih prinesejo duhovniku, bo njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Vse človekove posvečene stvari bodo njegove; karkoli katerikoli človek daje duhovniku, to bo njegovo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '»Govorite Izraelovim otrokom in jim recite: ›Če žena kateregakoli moškega zaide proč in zoper njega zagreši prestopek');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'in moški z njo meseno leži in je to skrito pred očmi njenega soproga in je zadržano zaprto in je ona omadeževana in tam ni nobene priče zoper njo niti ona ni zasačena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'in pride nanj duh ljubosumnosti in je ljubosumen na svojo ženo in je ona omadeževana, ali če pride nanj duh ljubosumnosti in je ljubosumen na svojo ženo, pa ona ni omadeževana,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'potem bo moški svojo ženo privedel k duhovniku in zanjo prinesel dar, desetino škafa ječmenove moke. Na to ne bo izlil olja niti nanj ne bo položil kadila, kajti to je daritev ljubosumnosti, daritev spominjanja, da bi v spomin privedla krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Duhovnik jo bo privedel bliže in jo postavil pred Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Duhovnik bo vzel sveto vodo v lončeni posodi in od prahu, ki je na tleh šotorskega svetišča, bo duhovnik vzel in to dal v vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Duhovnik bo žensko postavil pred Gospoda in odkril glavo ženske in v njene roke dal daritev spominjanja, kar je daritev ljubosumja. Duhovnik bo imel v svoji roki grenko vodo, ki povzroča prekletstvo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'in duhovnik ji bo s prisego naročil ter ženski rekel: ›Če s teboj ni ležal noben moški in če nisi zašla v nečistost z drugim namesto svojega soproga, bodi čista pred to grenko vodo, ki povzroča prekletstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Toda če si zašla k drugemu namesto svojega soproga in če si omadeževana in je poleg tvojega soproga s teboj ležal nek moški,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'potem bo duhovnik žensko zaprisegel s prisego prekletstva in duhovnik bo ženski rekel: › Gospod naj te naredi za prekletstvo in prisego med tvojim ljudstvom, ko Gospod tvojemu stegnu stori, da zgnije in tvoj trebuh oteče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'in ta voda, ki povzroča prekletstvo, bo šla v tvojo notranjost, da tvojemu trebuhu povzroči, da oteče in tvojemu stegnu, da zgnije.‹ In ženska naj reče: ›Amen, amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Duhovnik bo ta prekletstva zapisal v knjigo in jih spral z grenko vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Žensko bo primoral, da pije grenko vodo, ki povzroča prekletstvo in voda, ki povzroča prekletstvo, bo vstopila vanjo in postala grenka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Potem bo duhovnik vzel daritev ljubosumnosti iz roke ženske in daritev bo majal pred Gospodom in jo daroval na oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Duhovnik bo vzel prgišče daritve, torej njen spomin in to sežgal na oltarju in potem bo ženski povzročil, da spije vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Ko jo je primoral piti vodo, potem se bo zgodilo, da če je omadeževana in je storila prestopek zoper svojega soproga, da bo voda, ki povzroča prekletstvo, vstopila vanjo in postala grenka in njen trebuh bo otekel in njeno stegno bo zgnilo, in ženska bo prekletstvo med svojim ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Če pa ženska ni omadeževana, temveč je čista, potem naj bo prosta in bo spočela seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'To je postava ljubosumnosti, ko žena zaide k drugemu namesto svojega soproga in je omadeževana');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ali kadar pride nadenj duh ljubosumnosti in je ljubosumen na svojo ženo in bo ženo postavil pred Gospoda in bo duhovnik nad njo izvršil vso to postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Potem bo mož brez krivde pred krivičnostjo, ta ženska pa bo nosila svojo krivičnost.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '»Govori Izraelovim otrokom in jim reci: ›Kadar se bosta mož ali ženska oddvojila, da zaobljubita zaobljubo nazirca, da se oddvojita Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'se bo on ločil od vina in močne pijače in ne bo pil vinskega kisa ali kisa močne pijače niti ne bo pil nobene žgane pijače iz grozdnih jagod niti ne bo jedel sočnih ali posušenih grozdnih jagod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Vse dni svoje oddvojitve ne bo jedel ničesar, kar je narejeno iz vinske trte, od pešk celo do lupine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Vse dni zaobljube svoje oddvojitve na njegovo glavo ne bo prišla britev. Dokler se ne dopolnijo dnevi, za katere se je oddvojil Gospodu, bo svet in bo lasne pramene svoje glave pustil rasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Vse dni, ko je oddvojen Gospodu, ne bo prišel k nobenemu truplu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Sebe ne bo omadeževal zaradi svojega očeta ali zaradi svoje matere ali zaradi svojega brata ali zaradi svoje sestre, ko ti umrejo; ker je na njegovi glavi posvetitev njegovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Vse dni svoje oddvojitve je svet Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Če katerikoli moški poleg njega nenadoma umre in je ta omadeževal glavo njegove posvetitve, potem bo svojo glavo obril na dan svojega očiščenja, na sedmi dan jo bo obril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Na osmi dan bo duhovniku, k vratom šotorskega svetišča skupnosti, prinesel dve grlici ali dva mlada goloba');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'in duhovnik bo enega daroval za daritev za greh, drugega pa za žgalno daritev in zanj opravil spravo, kajti ta je grešil pri mrtvem in ta isti dan bo njegovo glavo posvetil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Gospodu bo posvetil dneve svoje oddvojitve in prinesel bo enoletno jagnje za daritev za prestopek, toda dneve, ki so bili prej, bo izgubil, ker je bila njegova oddvojitev omadeževana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'To je postava nazirca, ko se dopolnijo dnevi njegove oddvojitve. Priveden bo k vratom šotorskega svetišča skupnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'in svoj dar bo daroval Gospodu: eno jagnje moškega spola prvega leta brez pomanjkljivosti za žgalno daritev, eno enoletno jagnjico brez pomanjkljivosti za daritev za greh, enega ovna brez pomanjkljivosti za mirovne daritve,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'košaro nekvašenega kruha, kolače iz fine moke, umešane z oljem in vaflje iz nekvašenega kruha, pomazane z oljem in njihovo jedilno daritev in njihove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Duhovnik jih bo prinesel pred Gospoda in daroval bo za njegovo daritev za greh in njegovo žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Daroval bo ovna za žrtvovanje mirovnih daritev Gospodu s košaro nekvašenega kruha. Duhovnik bo daroval tudi njegovo jedilno daritev in njegovo pitno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Nazirec bo pri vratih šotorskega svetišča skupnosti obril glavo svoje oddvojitve in vzel bo lase glave svoje oddvojitve in jih položil na ogenj, ki je pod žrtvovanjem mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Duhovnik bo vzel kuhano pleče ovna, en nevzhajan kolač iz košare in en nekvašen vafelj in položil jih bo na roke nazirca, potem ko so lasje njegove oddvojitve obriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Duhovnik jih bo majal za majalno daritev pred Gospodom. To je sveto za duhovnika, z majalnimi prsmi in plečem vzdigovanja. Nató lahko nazirec pije vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'To je postava nazirca, ki se je zaobljubil in od njegovega daru Gospodu za njegovo oddvojitev, poleg tega, kar bo njegova roka dosegla. Glede na zaobljubo, s katero se je zaobljubil, tako mora storiti glede na postavo svoje oddvojitve.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '»Govori Aronu in njegovim sinovom, rekoč: ›Na ta način boste blagoslavljali Izraelove otroke in jim govorili:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '› Gospod [naj] te blagoslovi in te varuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Gospod [naj] stori [da] njegovo obličje zasije nad teboj in ti bo milostljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Gospod [naj] dvigne svoje obličje nad teboj in ti da mir.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Moje ime bodo polagali na Izraelove otroke; in jaz jih bom blagoslovil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Pripetilo se je na dan, ko je Mojzes v celoti postavil šotorsko svetišče, ga mazilil, posvetil in vse njegove priprave, oltar in vse njegove posode in jih mazilil ter jih posvetil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da so Izraelovi princi, poglavarji hiše njihovih očetov, ki so bili princi rodov in so bili nad tistimi, ki so bili prešteti, darovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Svojo daritev so prinesli pred Gospoda: šest pokritih vozov in dvanajst volov; voz za dva izmed princev in za vsakogar vol. Privedli so jih pred šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '»Vzemi jih od njih, da bodo lahko opravljali službo šotorskega svetišča skupnosti, in dal jih boš Lévijevcem, vsakemu možu glede na njegovo službo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Mojzes je vzel vozove in vole ter jih dal Lévijevcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dva vozova in štiri vole je dal Geršónovim sinovom, glede na njihovo službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Štiri vozove in osem volov je dal Meraríjevim sinovom, glede na njihovo službo, pod roko Itamárja, sina duhovnika Arona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Toda Kehátovim sinovom ni dal ničesar, ker je bila služba svetišča, ki jim je pripadala, takšna, da naj bi nosili na svojih ramenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Princi so darovali za posvetitev oltarja na dan, ko je bil ta maziljen, torej princi so darovali svojo daritev pred oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Gospod je rekel Mojzesu: »Darovali bodo svojo daritev, vsak princ na svoj dan, za posvetitev oltarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Tisti, ki je svoj dar daroval prvi dan, je bil Aminadábov sin Nahšón iz Judovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Njegov dar je bil en srebrn pladenj, katerega teža je bila sto trideset šeklov, ena srebrna skleda sedemdesetih šeklov, po svetiščnem šeklu; oba sta bila polna fine moke, umešane z oljem za jedilno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'ena žlica iz desetih šeklov zlata, polna kadila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'en mlad bikec, en oven, eno jagnje prvega leta za žgalno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'en kozliček od koz za daritev za greh');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'in za žrtvovanje mirovnih daritev dva vola, pet ovnov, pet kozlov, pet jagnjet prvega leta. To je bila daritev Aminadábovega sina Nahšóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Drugi dan je daroval Cuárjev sin Netanél, Isahárjev princ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Za svoj dar je daroval en srebrn pladenj, njegova teža je bila sto trideset šeklov, ena srebrna skleda sedemdesetih šeklov, po svetiščnem šeklu; oba izmed njiju polna fine moke, umešane z oljem za jedilno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'ena žlica iz desetih šeklov zlata, polna kadila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'en mlad bikec, en oven, eno jagnje prvega leta za žgalno daritev,');
