INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Njegov dar je bil en srebrn pladenj, njegova teža je bila sto trideset šeklov, ena srebrna skleda sedemdesetih šeklov, po svetiščnem šeklu; oba izmed njiju polna fine moke, umešane z oljem za jedilno daritev,');
