INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Enajsti dan je daroval Ohránov sin Pagiél, princ Aserjevih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Njegov dar je bil en srebrn pladenj, njegova teža je bila sto trideset šeklov, ena srebrna skleda sedemdesetih šeklov, po svetiščnem šeklu; oba izmed njiju polna fine moke, umešane z oljem za jedilno daritev,');
