INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'en kozliček od koz za daritev za greh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'in za žrtvovanje mirovnih daritev dva vola, pet ovnov, pet kozlov, pet jagnjet prvega leta. To je bila daritev Ohránovega sina Pagiéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dvanajsti dan je daroval Enánov sin Ahirá, princ Neftálijevih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Njegov dar je bil en srebrn pladenj, njegova teža je bila sto trideset šeklov, ena srebrna skleda sedemdesetih šeklov, po svetiščnem šeklu; oba izmed njiju polna fine moke, umešane z oljem za jedilno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'ena žlica iz desetih šeklov zlata, polna kadila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'en mlad bikec, en oven, eno jagnje prvega leta za žgalno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'en kozliček od koz za daritev za greh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'in za žrtvovanje mirovnih daritev dva vola, pet ovnov, pet kozlov, pet jagnjet prvega leta. To je bila daritev Enánovega sina Ahirája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'To je bila posvetitev oltarja, na dan, ko je bil ta maziljen po Izraelovih princih: dvanajst pladnjev iz srebra, dvanajst srebrnih skled in dvanajst žlic iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Vsak pladenj iz srebra je tehtal sto trideset šeklov, vsaka skleda sedemdeset. Vse srebrne posode so tehtale dva tisoč štiristo šeklov, po svetiščnem šeklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Zlatih žlic je bilo dvanajst, polnih kadila, ki so tehtale po deset šeklov, po svetiščnem šeklu. Vsega zlata žlic je bilo sto dvajset šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Vseh volov za žgalno daritev je bilo dvanajst bikcev, dvanajst ovnov, dvanajst jagnjet prvega leta z njihovo jedilno daritvijo in dvanajst kozličkov od koz za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Vseh volov za žrtvovanje mirovnih daritev je bilo štiriindvajset in štirje bikci, šestdeset ovnov, šestdeset kozlov, šestdeset jagnjet prvega leta. To je bila posvetitev oltarja, potem ko je bil ta maziljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Ko je Mojzes odšel v šotorsko svetišče skupnosti, da govori z njim, potem je slišal glas nekoga, ki mu je govoril od sedeža milosti, ki je bil nad skrinjo pričevanja, izmed dveh kerubov; in ta mu je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '»Govori Aronu in mu reci: ›Ko prižigaš svetilke, bo sedem svetilk dajalo svetlobo nasproti svečniku.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Aron je storil tako. Prižgal je svetilke nasproti svečniku, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'To delo svečnika je bilo iz kovanega zlata, njegovo telo, do njegovih cvetov, je bilo kovano delo, glede na vzorec, ki ga je Gospod pokazal Mojzesu, tako je naredil svečnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '»Vzemi Lévijevce izmed Izraelovih otrok in jih očisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Tako jim boš storil, da jih očistiš: nanje poškropi vodo očiščevanja in naj obrijejo vse svoje meso in naj si operejo oblačila in se tako očistijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Potem naj vzamejo mladega bikca z njegovo jedilno daritvijo, torej fino moko, umešano z oljem in še enega mladega bikca boš vzel za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Lévijevce boš privedel pred šotorsko svetišče skupnosti in skupaj boš zbral celoten zbor Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Lévijevce boš privedel pred Gospoda in Izraelovi otroci bodo svoje roke položili na Lévijevce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Aron bo daroval Lévijevce pred Gospodom za daritev Izraelovih otrok, da bodo lahko opravljali Gospodovo službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Lévijevci bodo svoje roke položili na glave bikcev in enega boš daroval za daritev za greh, drugega pa za žgalno daritev Gospodu, da opraviš spravo za Lévijevce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Lévijevce boš postavil pred Arona in pred njegove sinove in jih daroval za daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Tako boš Lévijevce oddvojil izmed Izraelovih otrok in Lévijevci bodo moji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Potem bodo Lévijevci vstopili, da opravljajo službo šotorskega svetišča skupnosti in ti jih boš očistil in jih daroval kot dar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Kajti oni so v celoti dani meni izmed Izraelovih otrok namesto tistega, ki odpre vsako maternico, celo namesto prvorojenca izmed vseh Izraelovih otrok sem jih vzel k sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Kajti vsi prvorojenci izmed Izraelovih otrok so moji, tako človek in žival. Na dan, ko sem udaril vsakega prvorojenca v egiptovski deželi, sem jih posvetil zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Lévijevce sem vzel za vse prvorojence izmed Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Izmed Izraelovih otrok sem dal Lévijevce kakor darilo Aronu in njegovim otrokom, da opravljajo službo Izraelovih otrok v šotorskem svetišču skupnosti in da opravijo spravo za Izraelove otroke, da tam ne bo nadloge med Izraelovimi otroki, ko se Izraelovi otroci približajo svetišču.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Mojzes, Aron in vsa skupnost Izraelovih otrok so Lévijevcem storili glede na vse, kar je Gospod zapovedal Mojzesu glede Lévijevcev, tako so jim Izraelovi otroci storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Lévijevci so bili očiščeni in oprali so svoja oblačila in Aron jih je daroval kakor daritev pred Gospodom in Aron je zanje opravil spravo, da jih očisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Potem so Lévijevci vstopili, da opravljajo svojo službo v šotorskem svetišču skupnosti pred Aronom in pred njegovimi sinovi. Kakor je Gospod zapovedal Mojzesu glede Lévijevcev, tako so jim storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '»To je to, kar pripada Lévijevcem: od petindvajset let stari in starejši bodo vstopili, da čakajo na službo šotorskega svetišča skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'in od starosti petdesetih let bodo prenehali čakati na njegovo služenje in ne bodo več služili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'temveč bodo služili s svojimi brati v šotorskem svetišču skupnosti, da pazijo na zadolžitev in ne bodo opravljali služenja. Tako boš storil Lévijevcem glede njihove zadolžitve.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Gospod je spregovoril Mojzesu v Sinajski divjini, v prvem mesecu drugega leta, potem ko so prišli iz egiptovske dežele, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '»Naj Izraelovi otroci tudi pasho praznujejo ob njenem določenemu času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Na štirinajsti dan tega meseca, zvečer, jo boste praznovali ob določenem času, glede na vse njene zakone in glede na vse njene ceremonije, jo boste praznovali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'In Mojzes je govoril Izraelovim otrokom, da naj praznujejo pasho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Pasho so praznovali na štirinajsti dan prvega meseca zvečer v Sinajski divjini. Glede na vse, kar je Gospod zapovedal Mojzesu, tako so Izraelovi otroci storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Tam pa so bili neki možje, ki so se omadeževali pri človeškem truplu, da na ta dan niso mogli praznovati pashe in na ta dan so prišli pred Mojzesa in pred Arona');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'in ti možje so mu rekli: »Omadeževani smo s človeškim truplom. Zakaj smo zadržani, da ne moremo darovati Gospodove daritve ob določenem času med Izraelovimi otroki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mojzes jim je rekel: »Mirno stojte, jaz pa bom poslušal, kaj bo glede vas zapovedal Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '»Govori Izraelovim otrokom, rekoč: ›Če bo katerikoli moški izmed vas ali izmed vašega potomstva postal nečist zaradi razloga trupla, ali bo na potovanju daleč stran, bo vendar praznoval pasho Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Štirinajsti dan drugega meseca zvečer jo bodo praznovali in jo jedli z nekvašenim kruhom in grenkimi zelišči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Od tega ne bodo ničesar pustili do jutra niti zlomili nobene njegove kosti. Glede na vse odredbe pashe jo bodo praznovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Toda mož, ki je čist in ni na potovanju in se ogiba praznovati pasho, celo ista duša bo iztrebljena izmed svojega ljudstva. Ker ob določenem času ni prinesel daru Gospodu, bo ta mož nosil svoj greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Če bo tujec začasno prebival med vami in bo praznoval pasho Gospodu, bo tako storil glede na odredbe pashe in glede na njen določeni način. Imeli boste eno odredbo, tako za tujca kakor za tistega, ki je bil rojen v deželi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Na dan, ko je bilo šotorsko svetišče vzdignjeno, je oblak pokril šotorsko svetišče, namreč šotor pričevanja in zvečer je bilo nad šotorskim svetiščem kakor bi bil to videz ognja do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Vedno je bilo tako; oblak ga je pokrival podnevi in videz ognja ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Ko je bil oblak dvignjen od šotorskega svetišča, so za tem Izraelovi otroci odpotovali in na kraju, kjer je oblak obstal, tam so Izraelovi otroci postavili svoje šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Na Gospodovo zapoved so Izraelovi otroci odpotovali in na Gospodovo zapoved so se utaborili. Kolikor dolgo je oblak ostajal nad šotorskim svetiščem, so počivali v svojih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Ko se je oblak mnogo dni zadrževal nad šotorskim svetiščem, potem so Izraelovi otroci pazili na Gospodovo naročilo in niso odpotovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'In bilo je, ko je bil oblak malo dni nad šotorskim svetiščem; glede na Gospodovo zapoved, so ostajali v svojih šotorih in glede na Gospodovo zapoved so odpotovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'In bilo je, ko je oblak ostajal od večera celo do jutra in da se je oblak zjutraj dvignil, potem so odpotovali, bodisi je bilo to podnevi ali ponoči, ko se je oblak dvignil, so odpotovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Ali če je bilo to dva dni ali mesec ali leto, da je oblak ostajal nad šotorskim svetiščem, ostajajoč nad njim, so Izraelovi otroci ostali v svojih šotorih in niso odpotovali, toda ko je bil ta dvignjen, so odpotovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Na Gospodovo zapoved so počivali v šotorih in na Gospodovo zapoved so odpotovali; pazili so na Gospodovo naročilo, na Gospodovo zapoved, po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '»Naredi si dve srebrni trobenti. Iz celega kosa ju boš izdelal, da ju boste lahko uporabljali za sklic zbora in za potovanje taborov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Ko bodo z njima zatrobili, se bo ves zbor zbral k tebi pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Če bodo trobili samo z eno trobento, potem se bodo princi, ki so poglavarji tisočerih Izraelovih, skupaj zbrali k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Kadar zatrobite alarm, potem bodo tabori, ki taborijo na vzhodnih delih, odšli naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Kadar drugič zatrobite alarm, potem se bodo tabori, ki taborijo na južni strani, odpravili na svoje potovanje; zaradi njihovih potovanj bodo trobili alarm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Toda ko naj bi se skupnost zbrala skupaj, boste trobili, toda ne boste razglasili alarma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Aronovi sinovi, duhovniki, bodo trobili s trobentami in oni vam bodo za odredbo na veke skozi vaše rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Če greste v svoji deželi na vojno zoper sovražnika, ki vas zatira, potem boste s trobentami trobili alarm in Gospod, vaš Bog, se vas bo spomnil in rešeni boste pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Tudi na dan vašega veselja in na vaše slovesne dneve in ob začetkih mesecev boste s trobentami trobili nad svojimi žgalnimi daritvami in nad žrtvovanji svojih mirovnih daritev, da vam bodo za spomin pred vašim Bogom. Jaz sem Gospod, vaš Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Pripetilo se je na dvajseti dan drugega meseca, v drugem letu, da je bil oblak dvignjen iznad šotorskega svetišča pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Izraelovi otroci so se odpravili na svoja potovanja iz Sinajske divjine in oblak je obstal v Paránski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Prvič so se odpravili na svoje potovanje glede na Gospodovo zapoved, po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Prvi je odšel prapor tabora Judovih otrok, glede na njihove vojske in nad njegovo vojsko je bil Aminadábov sin Nahšón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Nad vojsko rodu Isahárjevih otrok je bil Cuárjev sin Netanél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Nad vojsko rodu Zábulonovih otrok je bil Helónov sin Eliáb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Šotorsko svetišče je bilo podrto, in Geršónovi sinovi in Meraríjevi sinovi so se odpravili naprej, noseč šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Prapor Rubenovega tabora se je odpravil naprej, glede na njihove vojske in nad njegovo vojsko je bil Šedeúrjev sin Elicúr.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Nad vojsko rodu Simeonovih otrok je bil Curišadájev sin Šelumiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Nad vojsko rodu Gadovih otrok je bil Deguélov sin Eljasáf.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Kehátovci so se odpravili naprej, noseč svetišče, drugi pa so postavili šotorsko svetišče preden so ti prišli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Prapor tabora Efrájimovih otrok se je odpravil naprej glede na njihove vojske in nad njegovo vojsko je bil Amihúdov sin Elišamá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Nad vojsko rodu Manásejevih otrok je bil Pedacúrjev sin Gamliél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Nad vojsko rodu Benjaminovih otrok je bil Gideoníjev sin Abidán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Prapor tabora Danovih otrok se je odpravil naprej, ki je bil zadnja straža vseh taborov po njihovih vojskah. In nad njegovo vojsko je bil Amišadájev sin Ahiézer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Nad vojsko rodu Aserjevih otrok je bil Ohránov sin Pagiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Nad vojsko rodu Neftálijevih otrok je bil Enánov sin Ahirá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Takšna so bila potovanja Izraelovih otrok glede na njihove vojske, ko so se odpravili naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Mojzes je rekel Hobábu, sinu Midjánca Reguéla, Mojzesovega tasta: »Potujemo proti kraju, o katerem je Gospod rekel: ›Jaz vam ga bom dal.‹ Pridi z nami in mi ti bomo storili dobro, kajti Gospod je dobro govoril glede Izraela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Ta pa mu je rekel: »Ne bom šel, temveč bom odšel k svoji lastni deželi in k svojemu sorodstvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Rekel je: »Ne zapusti nas, prosim te, ker veš kako naj taborimo v divjini in ti si nam lahko namesto oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'In zgodilo se bo, če greš z nami, da, zgodilo se bo, da kakršna bo Gospodova dobrota do nas, isto bomo mi storili tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Odpravili so se od Gospodove gore tri dni potovanja in skrinja Gospodove zaveze je šla pred njimi na tridnevno potovanje, da zanje poišče počivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Gospodov oblak je bil nad njimi podnevi, ko so odšli iz tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Kadar je skrinja krenila na pot, se je pripetilo, da je Mojzes rekel: »Vstani, Gospod in razkrope naj se tvoji sovražniki in tisti, ki te sovražijo, naj zbežijo pred teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Ko pa je ta počivala, je rekel: »Vrni se, oh Gospod, k mnogim Izraelovim tisočerim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Ko se je ljudstvo pritoževalo, je to razžalilo Gospoda, in Gospod je to slišal in njegova jeza je bila vžgana in med njimi je zagorel Gospodov ogenj in použil tiste, ki so bili na najbolj oddaljenih delih tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Ljudstvo je klicalo k Mojzesu in ko je Mojzes molil h Gospodu je bil ogenj pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Ime kraja je imenoval Tabêra, ker je med njimi gorel Gospodov ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Mešana množica, ki je bila med njimi, je čutila poželenje in tudi Izraelovi otroci so ponovno jokali ter rekli: »Kdo nam bo dal za jesti meso?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Spominjamo se rib, ki smo jih prosto jedli v Egiptu, kumaric, melon, pora, čebule in česna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Toda naša duša je sedaj izsušena. Tukaj, pred našimi očmi, sploh ni ničesar poleg mane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Mana je bila kakor koriandrovo seme in njena barva kakor barva bdelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Ljudstvo je šlo okoli in to nabiralo in mlelo v mlinih ali tolklo v možnarju in jo peklo v ponvah in iz nje delalo kolače in njen okus je bil kakor okus svežega olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Ko je ponoči na tabor padla rosa, je nanj padla mana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Potem je Mojzes slišal ljudstvo jokati po svojih družinah, vsakega moža pri vratih svojega šotora. Gospodova jeza je bila silno vžgana; tudi Mojzes je bil razžaljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Mojzes je rekel Gospodu: »Zakaj si prizadel svojega služabnika? In zakaj nisem našel naklonjenosti v tvojem pogledu, da name polagaš breme vsega tega ljudstva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Ali sem jaz spočel vse to ljudstvo? Mar sem jih rodil, da bi mi rekel: ›Nosi jih v svojem naročju, kakor skrbeč oče nosi doječega otroka, v deželo, ki si jo prisegel njihovim očetom?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Od kod naj bi imel meso, da ga dam vsemu temu ljudstvu? Kajti jokajo k meni, rekoč: ›Daj nam meso, da bomo lahko jedli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Vsega tega ljudstva nisem zmožen nositi sam, ker je to zame pretežko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Če tako postopaš z menoj, me ubij, prosim te, brez razmisleka, če sem našel naklonjenost v tvojih očeh in naj ne vidim svoje bednosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Gospod je rekel Mojzesu: »K meni zberi sedemdeset mož izmed Izraelovih starešin, ki jih poznaš, da so starešine ljudstva in častniki nad njimi; in privedi jih k šotorskemu svetišču skupnosti, da bodo tam lahko stali s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Jaz pa bom prišel dol in tam govoril s teboj. Vzel bom od duha, ki je nad teboj in položil ga bom nanje in s teboj bodo nosili breme ljudstva, da ga ne boš nosil sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Ljudstvu pa reci: ›Posvetite se za jutri in jedli boste meso, kajti jokali ste v Gospodova ušesa, rekoč: ›Kdo nam bo dal za jesti meso? Kajti z nami je bilo dobro v Egiptu,‹ zato vam bo Gospod dal meso in vi boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Ne boste jedli en dan, niti dva dni, niti pet dni, niti deset dni, niti dvajset dni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'temveč cel mesec, dokler to ne pride iz vaših nosnic in vam to postane gnusno, zato ker ste prezirali Gospoda, ki je med vami in ste jokali pred njim, rekoč: ›Zakaj smo prišli iz Egipta?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Mojzes je rekel: »Ljudstva, med katerim sem, je šeststo tisoč pešcev, ti pa si rekel: ›Jaz jim bom dal mesa, da bodo lahko jedli cel mesec.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Mar bodo tropi in črede umorjeni zaradi njih, da jim zadostijo? Mar se bodo vse morske ribe zanje zbrale skupaj, da jim zadostijo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Gospod je rekel Mojzesu: »Ali je Gospodova roka postala prekratka? Sedaj boš videl, če se ti bo moja beseda zgodila ali ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Mojzes je odšel ven in ljudstvu povedal Gospodove besede in zbral sedemdeset mož izmed starešin ljudstva in jih postavil naokoli šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Gospod je prišel dol v oblaku in mu spregovoril in vzel od duha, ki je bil nad njim in ga dal sedemdesetim starešinam. Pripetilo se je, ko je nad njimi počival duh, da so prerokovali in niso prenehali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Toda tam v taboru sta ostala dva izmed mož, ime enega je bilo Eldád in ime drugega Medád in duh je počival nad njima. Bila sta izmed tistih, ki so bili zapisani, toda nista odšla k šotorskemu svetišču, in prerokovala sta v taboru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Tam je pritekel mladenič in povedal Mojzesu ter rekel: »Eldád in Medád prerokujeta v taboru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Nunov sin Józue, Mojzesov služabnik, eden izmed njegovih mladeničev, je odgovoril in rekel: »Moj gospod Mojzes, prepovej jima.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mojzes mu je rekel: »Mar si zaradi mene ljubosumen? Da bi Bog dal, da bi bilo vse Gospodovo ljudstvo preroki in da bi Gospod nanje položil svojega duha!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Mojzes se je povzpel v tabor, on in starešine Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Od Gospoda je izšel veter in od morja prinesel prepelice in jih pustil pasti pri taboru, kakor bi bilo dan potovanja na tej strani in kakor bi bilo dan potovanja na oni strani, naokoli tabora in kakor bi jih bilo dva komolca visoko na obličju zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Ljudstvo je stalo pokonci ves ta dan in vso to noč in ves naslednji dan in zbiralo prepelice. Kdor je zbral najmanj je zbral deset tovorov. Razporedili so si jih povsod naokoli tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Medtem ko je bilo meso še vedno med njihovimi zobmi, preden je bilo prežvečeno, je bil Gospodov bes vžgan zoper ljudstvo in Gospod je ljudstvo udaril z zelo veliko nadlogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Ime tega kraja je imenoval Kibrot-Hattaava, ker so tam pokopali ljudstvo, ki je poželelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'In ljudstvo je odpotovalo od Kibrot-Hattaave do Haceróta in ostalo pri Hacerótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mirjam in Aron pa sta govorila zoper Mojzesa zaradi etiopske ženske, ki jo je poročil, kajti poročil je etiopsko žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Rekla sta: »Je Gospod resnično govoril samo po Mojzesu? Mar ni govoril tudi po nama?« In Gospod je to slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(Torej mož Mojzes je bil zelo krotak, nad vsemi ljudmi, ki so bili na obličju zemlje.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Gospod je nenadoma spregovoril Mojzesu, Aronu in Mirjam: »Vi trije, pridite ven k šotorskemu svetišču skupnosti.« In ti trije so prišli ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Gospod je prišel dol v oblačnem stebru in stopil k vratom šotorskega svetišča in poklical Arona in Mirjam, in oba sta prišla naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Rekel je: »Poslušajta torej moje besede: ›Če je med vami prerok, se mu bom jaz, Gospod, dal spoznati v videnju in mu govoril v sanjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Moj služabnik Mojzes pa ni tak, on je zvest v vsej moji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Z njim bom govoril od ust do ust, celó vidno, ne pa v skrivnostnih govorih, in gledal bo Gospodovo podobnost. Zakaj se torej nista bala govoriti proti mojemu služabniku Mojzesu?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Gospodova jeza je bila vneta zoper njiju in je odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Oblak je odšel od šotorskega svetišča in glej, Mirjam je postala gobava, bela kakor sneg. Aron pa je pogledal na Mirjam in glej, bila je gobava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Aron je rekel Mojzesu: »Ojoj, moj gospod, rotim te, ne položi greha na naju, v čemer sva storila nespametno in v čemer sva grešila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Naj ona ne bo kakor nekdo, [ki je] mrtev, katerega meso je na pol použito, ko prihaja iz maternice svoje matere.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Mojzes je klical h Gospodu, rekoč: »Ozdravi jo torej, oh Bog, rotim te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Gospod je rekel Mojzesu: »Če bi njen oče zgolj pljunil v njen obraz, ali ne bi bila sedem dni osramočena? Naj bo sedem dni zaprta izven tabora in potem naj bo ponovno sprejeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Mirjam je bila sedem dni zaprta izven tabora in ljudstvo se ni odpravilo, dokler Mirjam ni bila ponovno privedena nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Potem se je ljudstvo odpravilo iz Haceróta in se utaborilo v Paránski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '»Pošlji može, da bodo lahko preiskali kánaansko deželo, ki jo dajem Izraelovim otrokom. Iz vsakega rodu njihovih očetov boste poslali človeka, vsakega, ki je voditelj med njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Mojzes jih je po Gospodovi zapovedi poslal iz Paránske divjine; vsi tisti možje so bili poglavarji Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'To so bila njihova imena: iz Rubenovega rodu Zahúrjev sin Šamúa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'iz Simeonovega rodu Horíjev sin Šafát,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'iz Judovega rodu Jefunéjev sin Kaléb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'iz Isahárjevega rodu Jožefov sin Jigál,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'iz Efrájimovega rodu Nunov sin Hošéa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'iz Benjaminovega rodu Rafújev sin Paltí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, '§ iz Zábulonovega rodu Sodijev sin Gadiél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'iz Jožefovega rodu, namreč iz Manásejevega rodu Susíjev sin Gadí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'iz Danovega rodu Gemalíjev sin Amiél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'iz Aserjevega rodu Mihaelov sin Setúr,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'iz Neftálijevega rodu Vofsíjev sin Nahbí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'iz Gadovega rodu Mahíjev sin Geuél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'To so imena mož, ki jih je Mojzes poslal, da ogledajo deželo. Mojzes je Nunovega sina Hošéa imenoval Ješua.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Mojzes jih je poslal, da ogledajo kánaansko deželo in jim rekel: »Pojdite gor po tej poti proti jugu in pojdite gor na goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Oglejte si deželo, kakšna je in ljudstvo, ki prebiva v njej, če so močni ali šibki, maloštevilni ali številni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'in kakšna je dežela, ki v njej prebivajo, bodisi je ta dobra ali slaba, in kakšna mesta so, ki v njih prebivajo, ali so v šotorih ali v oporiščih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'in kakšna je dežela, ali je ta obilna ali revna, ali je tam les ali ne. In bodite odločnega poguma in prinesite sad dežele.« Torej bil je čas prvih sadov grozdja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Tako so odšli gor in preiskali deželo od Cinske divjine do Rehóba, kakor ljudje pridejo do Hamáta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Povzpeli so se pri jugu in prišli do Hebróna, kjer so bili Ahimán, Šešáj in Talmáj, Anákovi otroci. (Torej Hebrón je bil zgrajen sedem let pred Coanom v Egiptu.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Prišli so k Eškólskemu potoku in od tam odrezali vejo z enim šopom grozdja in nosili so jo med dvema na palici in prinesli so od granatovcev in od fig.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Kraj je bil imenovan potok Eškól zaradi šopa grozdja, ki so ga Izraelovi otroci odrezali od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'In po štiridesetih dneh so se vrnili iz preiskovanja dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Šli so in prišli k Mojzesu in Aronu in k vsej skupnosti Izraelovih otrok v Paránsko divjino, do Kadeša in jima nazaj prinesli besedo in vsej skupnosti in jim pokazali sad dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Povedali so mu in rekli: »Prišli smo do dežele, kamor nas pošiljaš in ta zagotovo teče z mlekom in medom, in to je njen sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Vendar je ljudstvo, ki prebiva v deželi močno in mesta so obzidana in zelo velika in poleg tega smo tam videli Anákove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalečani prebivajo v južni deželi; Hetejci, Jebusejci in Amoréjci prebivajo v gorah, Kánaanci pa prebivajo poleg morja in ob jordanski pokrajini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaléb je ljudstvo pomiril pred Mojzesom in rekel: »Brž pojdimo gor in jo zavzemimo, kajti zelo smo sposobni, da jo premagamo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Toda možje, ki so odšli z njim, so rekli: »Mi nismo zmožni oditi gor zoper ljudstvo, kajti oni so močnejši od nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Izraelovim otrokom so prinesli zlo poročilo o deželi, ki so jo preiskali, rekoč: »Dežela, skozi katero smo šli, da jo preiščemo, je dežela, ki požira svoje prebivalce. Vse ljudstvo, ki smo ga videli v njej, so možje velike postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Tam smo videli velikane, Anákove sinove, ki so izšli iz velikanov in v svojih očeh smo bili kakor kobilice in takšni smo bili v njihovem pogledu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Vsa skupnost je povzdignila svoj glas in zajokala in ljudstvo je to noč jokalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Vsi Izraelovi otroci so godrnjali zoper Mojzesa in zoper Arona in celotna skupnost jima je rekla: »Da bi Bog dal, da bi umrli v egiptovski deželi! Ali da bi Bog dal, da bi umrli v tej divjini!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Zakaj nas je Gospod privedel v to deželo, da pademo pod mečem, da bi bile naše žene in naši otroci plen? Ali ne bi bilo za nas bolje, da se vrnemo v Egipt?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Drug drugemu so rekli: »Postavimo si poveljnika in se vrnimo v Egipt.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Potem sta Mojzes in Aron padla na svoja obraza pred vsem zborom skupnosti Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Nunov sin Józue in Jefunéjev sin Kaléb, ki sta bila izmed tistih, ki sta preiskala deželo, sta pretrgala svoja oblačila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'in spregovorila vsej skupini Izraelovih otrok, rekoč: »Dežela, skozi katero sva šla, da jo preiščeva, je silno dobra dežela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Če se Gospod razveseljuje v nas, potem nas bo privedel v to deželo in nam jo izročil; deželo, v kateri tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Samo ne uprite se zoper Gospoda niti se ne bojte ljudstva dežele, kajti oni so za nas kruh. Njihova obramba je odšla od njih, Gospod pa je z nami. Ne bojte se jih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Toda vsa skupnost ju je zaukazala kamnati s kamni. In Gospodova slava se je prikazala v šotorskem svetišču skupnosti, pred vsemi Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Gospod je rekel Mojzesu: »Doklej me bo to ljudstvo še dražilo? Kako dolgo bo, preden mi bodo verovali zaradi vseh znamenj, ki sem jih prikazal med njimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Udaril jih bom s kužno boleznijo in jih razdedinil in iz tebe bom naredil večji narod ter mogočnejši, kakor so oni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Mojzes pa je Gospodu rekel: »Potem bodo Egipčani to slišali, (kajti v svoji moči si to ljudstvo privedel izmed njih)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'in bodo to povedali prebivalcem te dežele, kajti slišali so, da si ti Gospod med tem ljudstvom, da si ti Gospod, viden iz obličja v obličje in da tvoj oblak stoji nad njimi in da greš pred njimi, podnevi v oblačnem stebru, ponoči pa v ognjenem stebru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Torej če boš pobil vse to ljudstvo kakor enega človeka, potem bodo narodi, ki so slišali o tvojem slovesu, govorili, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '›Ker Gospod tega ljudstva ni mogel privesti v deželo, ki jim jo je prisegel, jih je zato umoril v divjini.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Sedaj te rotim, naj bo moč mojega Gospoda velika, glede na to, kakor si govoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '› Gospod je potrpežljiv in zelo usmiljen, ki odpušča krivičnost in prestopek in nikakor ne očisti krivega, ki obiskuje krivičnost očetov na otrocih do tretjega in četrtega rodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Odpusti, rotim te, krivičnost tega ljudstva, glede na veličino svojega usmiljenja in kakor si odpuščal temu ljudstvu, od Egipta, celo do sedaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Gospod je rekel: »Odpustil sem glede na tvojo besedo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'vendar kakor resnično jaz živim, bo vsa zemlja napolnjena z Gospodovo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Ker so vsi tisti ljudje, ki so videli mojo slavo in moje čudeže, ki sem jih storil v Egiptu in v divjini in so me skušali sedaj teh desetkrat in niso prisluhnili mojemu glasu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'zagotovo ne bodo videli dežele, ki sem jo prisegel njihovim očetom niti je ne bo videl nobeden izmed tistih, ki so me dražili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Toda ker je imel moj služabnik Kaléb, v sebi drugega duha in mi je popolnoma sledil, ga bom privedel v deželo, v katero je odšel, in njegovo seme jo bo vzelo v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, '(Torej Amálečani in Kánaanci so prebivali v dolini.) Jutri se obrnite in se odpravite v divjino, po poti Rdečega morja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '»Doklej bom še prenašal to zlo skupnost, ki godrnja zoper mene? Slišal sem mrmranja Izraelovih otrok, ki mrmrajo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Reci jim: › Kakor resnično jaz živim,‹ govori Gospod, ›kakor ste govorili v moja ušesa, tako bom jaz storil vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vaša trupla bodo padla v tej divjini in vsi, kar vas je bilo izmed vas preštetih, glede na vaše celotno število, od dvajset let stari in navzgor, ki ste godrnjali zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Zagotovo ne boste prišli v deželo, glede katere sem prisegel, da v njej prebivate, razen Jefunéjevega sina Kaléba in Nunovega sina Józueta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Toda vaše malčke, za katere ste rekli, da naj bi bili plen, te bom privedel noter in oni bodo spoznali deželo, ki ste jo vi prezirali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Toda kar se tiče vas, bodo vaša trupla padla v tej divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Vaši otroci se bodo štirideset let potikali po divjini in nosili vaša vlačugarstva, dokler ne bodo vaša trupla propadla v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Po številu dni, v katerih ste preiskovali deželo, torej štirideset dni, vsak dan za leto, boste nosili svoje krivičnosti, celó štirideset let in spoznali boste moj odmik od obljube.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Jaz, Gospod, sem rekel: ›Zagotovo bom tako storil vsej tej zli skupnosti, ki je skupaj zbrana zoper mene. V tej divjini bodo použiti in tam bodo umrli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Možje, ki jih je Mojzes poslal, da preiščejo deželo, ki so se vrnili in vso skupnost pripravili, da je mrmrala zoper njega s prinašanjem obrekovanja nad deželo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'celo ti možje, ki so nad deželo prinesli zlo poročilo, so zaradi kuge umrli pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Toda Nunov sin Józue in Jefunéjev sin Kaléb, ki sta bila izmed mož, ki so odšli, da preiščejo deželo, sta še vedno živela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Mojzes je te stvari povedal vsem Izraelovim otrokom in ljudstvo je silno žalovalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Vstali so zgodaj zjutraj in se povzpeli na vrh gore, rekoč: »Glej! Mi smo tukaj in šli bomo gor, na kraj, ki nam ga je Gospod obljubil, kajti grešili smo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mojzes je rekel: »Zakaj sedaj prestopate Gospodovo zapoved? Toda to ne bo uspelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne pojdite gor, kajti Gospoda ni med vami, da ne boste udarjeni pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Kajti Amalečani in Kánaanci so tam pred vami in vi boste padli pod mečem, ker ste obrnjeni proč od Gospoda, zato Gospod ne bo z vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Vendar pa so si predrznili, da gredo na vrh hriba. Vendar skrinja Gospodove zaveze in Mojzes nista odšla iz tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Potem so prišli dol Amálečani in Kánaanci, ki so prebivali na tem hribu in jih udarili ter porazili, celó do Horme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '»Spregovori Izraelovim otrokom in jim reci: ›Ko boste prišli v deželo svojih prebivališč, ki vam jo dajem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'in boste naredili daritev z ognjem Gospodu, žgalno daritev ali žrtvovanje z izpolnjevanjem zaobljube ali s prostovoljnim darovanjem ali na vaše slovesne praznike, da naredite prijeten vonj Gospodu, od črede ali od tropa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'potem bo tisti, ki daruje svoj dar Gospodu, prinesel jedilno daritev desetinke moke, umešane s četrtino vrča olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Pripravil boš četrtino vrča vina za pitno daritev, z žgalno daritvijo ali žrtvovanjem, za vsako jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Ali za ovna boš pripravil za jedilno daritev dve desetinki moke, umešane s tretjino vrča olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Za pitno daritev boš pripravil tretjino vrča vina, za prijeten vonj Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Ko pripravljaš bikca za žgalno daritev ali za klavno daritev v izpolnjevanju obljube ali mirovnih daritev Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'potem bo z bikcem jedilne daritve prinesel tri desetinke moke, umešane s polovico vrča olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Za pitno daritev boš prinesel polovico vrča vina, za ognjeno daritev, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tako bo to storjeno za enega bikca ali za enega ovna ali za jagnje ali kozlička.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Glede na število, ki ga boste pripravili, tako boste storili vsakemu glede na njihovo število.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Vsi, ki so rojeni iz dežele, bodo te stvari storili na ta način, z darovanjem ognjene daritve, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Če tujec začasno prebiva z vami ali kdorkoli je med vami v vaših rodovih in bo daroval ognjeno daritev prijetnega vonja Gospodu; kakor počnete vi, tako bo storil on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Ena odredba naj bo tako za vas iz skupnosti, kakor tudi za tujca, ki začasno biva z vami, odredba na veke za vaše rodove. Kakor ste vi, tako naj bo tujec pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Ena postava in en način bo za vas in za tujca, ki začasno biva z vami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '»Govori Izraelovim otrokom in jim reci: ›Ko pridete v deželo, kamor vas privedem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'potem bo, ko jeste od kruha dežele, da boste darovali vzdigovalno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Kolač svojega prvega testa boste darovali za vzdigovalno daritev. Kakor delate vzdigovalno daritev od mlatišča, tako boste to vzdignili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Od svojega prvega testa boste dali Gospodu vzdigovalno daritev v vaših rodovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Če pa zaidete in ne obeležujete vseh teh zapovedi, ki jih je Gospod govoril Mojzesu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'celó vse, kar vam je po Mojzesovi roki zapovedal Gospod, od dneva, ko je Gospod zapovedal Mojzesu in odslej med vašimi rodovi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'potem bo to, če bo storjeno z nevednostjo, brez védenja skupnosti, da bo vsa skupnost darovala enega mladega bikca za žgalno daritev, v prijeten vonj Gospodu, z njegovo jedilno daritvijo in njegovo pitno daritvijo, glede na določen način in enega kozlička od koz za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Duhovnik bo opravil spravo za vso skupnost Izraelovih otrok in to jim bo odpuščeno, kajti to je nevednost. Prinesli bodo svojo daritev, žrtvovanje, narejeno z ognjem Gospodu in njihovo daritev za greh pred Gospoda, za njihovo nevednost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'To bo odpuščeno vsem otrokom Izraelove skupnosti in tujcu, ki začasno biva med njimi, glede na to, da je bilo vse ljudstvo v nevednosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Če katerakoli duša greši zaradi nevednosti, potem bo privedel kozo prvega leta za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Duhovnik bo opravil spravo za dušo, ki nevedno greši, ko z nevednostjo greši pred Gospodom, da zanjo opravi spravo; in to ji bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Imeli boste eno postavo za tistega, ki greši zaradi nevednosti, tako za tistega, ki je rojen med Izraelovimi otroki, kot za tujca, ki začasno biva med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Toda duša, ki ravna prepotentno, ne glede na to, ali je rojena v deželi ali tujec, ta ista graja Gospoda; in ta duša bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Ker je prezirala Gospodovo besedo in prelomila njegovo zapoved, bo ta duša popolnoma iztrebljena; njegova krivičnost bo nad njim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Medtem ko so bili Izraelovi otroci v divjini, so našli moža, ki je na šabatni dan nabiral veje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Tisti, ki so ga našli nabirati veje, so ga privedli k Mojzesu in Aronu in k vsej skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Dali so ga pod stražo, ker ni bilo oznanjeno kaj naj bi mu bilo storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Gospod je rekel Mojzesu: »Mož bo zagotovo usmrčen. Vsa skupnost ga bo zunaj tabora kamnala s kamenjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'In vsa skupnost ga je odvedla zunaj tabora in ga kamnala s kamenjem in ta je umrl, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '»Govori Izraelovim otrokom in jim naroči, da si delajo rese na robovih svojih oblek skozi njihove rodove in da na rese robov dajejo moder trak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Ta vam bo za obrobo, da boste lahko pogledali nanjo in se spomnili vseh Gospodovih zapovedi in jih izvrševali, in da ne boste tavali za svojim lastnim srcem in za svojimi lastnimi očmi, za katerimi ste se vlačugali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'da se boste lahko spomnili in izpolnjevali vse moje zapovedi in boste sveti svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Jaz sem Gospod, vaš Bog, ki vas je privedel iz egiptovske dežele, da bi bil vaš Bog. Jaz sem Gospod, vaš Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Torej Korah, Jichárjev sin, Kehátov sin, Lévijev sin ter Datán in Abirám, Eliábova sinova in Peletov sin On izmed Rubenovih sinov, so vzeli može');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'in se vzdignili pred Mojzesom, z nekaterimi izmed Izraelovih otrok, dvesto petdesetimi princi skupnosti, slavnimi v zboru, možmi z ugledom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'in se skupaj zbrali zoper Mojzesa in zoper Arona ter jima rekli: »Preveč si jemljeta nase, glede na to, da je vsa skupnost sveta, vsakdo izmed njih, in da je Gospod med njimi. Zakaj se torej povzdigujeta nad Gospodovo skupnost?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Ko je Mojzes to slišal, je padel na svoj obraz');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'in govoril Korahu in vsej njegovi skupini, rekoč: »Celo jutri bo Gospod pokazal kdo so njegovi in kdo je svet; in povzročil mu bo, da pride bliže k njemu. Celo tistemu, ki ga je izbral, bo povzročil, da se približa k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Storite to: ›Vzemite kadilnice, Korah in vsa njegova skupina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'in jutri dajte vanje ogenj pred Gospodom in nanj položite kadilo. Zgodilo se bo, da bo mož, ki ga bo Gospod izbral, ta bo svet. Vi si preveč jemljete nase, vi Lévijevi sinovi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Mojzes je rekel Korahu: »Poslušajte, prosim vas, vi Lévijevi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ali se vam zdi le majhna stvar, da vas je Izraelov Bog ločil od Izraelove skupnosti, da vas privede bliže k sebi, da opravljate delo Gospodovega šotorskega svetišča in da stojite pred skupnostjo, da jim služite?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Privedel te je blizu k sebi in vse tvoje brate, Lévijeve sinove s teboj. Ali iščete tudi duhovništvo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Zaradi katerega vzroka sta tako ti in vsa tvoja skupina zbrana skupaj zoper Gospoda, in kaj je Aron, da mrmrate zoper njega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Mojzes je poslal, da pokliče Datána in Abiráma, Eliábova sinova, ki sta rekla: »Ne bova prišla gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Je to majhna stvar, da si nas privedel gor iz dežele, kjer tečeta mleko in med, da nas ubiješ v divjini, razen da se narediš princa nad nami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Še več, nisi nas privedel v deželo, kjer tečeta mleko in med ali nam dal dediščino polj in vinogradov. Ali boš iztaknil oči teh ljudi? Ne bomo prišli tja gor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Mojzes je bil zelo ogorčen in rekel Gospodu: »Ne spoštuj njihovih daritev. [Niti] enega osla nisem odvzel od njih niti nisem nič slabega storil enemu izmed njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Mojzes je rekel Korahu: »Bodite ti in vsa tvoja skupina jutri pred Gospodom, ti, oni in Aron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Vsak mož naj vzame svojo kadilnico in vanjo položi kadilo in prinesite jih pred Gospoda, vsak mož svojo kadilnico, dvesto petdeset kadilnic; tudi ti in Aron, vsak izmed vaju svojo kadilnico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Vzeli so vsak mož svojo kadilnico in vanje dali ogenj in nanj položili kadilo in z Mojzesom in Aronom stali v vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Korah je pri vratih šotorskega svetišča skupnosti zoper njiju zbral vso skupnost in Gospodova slava se je prikazala vsej skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '»Ločita se izmed te skupnosti, da jih lahko v hipu pokončam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Onadva pa sta padla na svoja obraza in rekla: »Oh Bog, Bog duhov vsega mesa, ali bo en človek grešil in boš ogorčen nad vso skupnostjo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '»Govori skupnosti, rekoč: ›Vzdignite se proč od bližine šotora Koraha, Datána in Abiráma.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Mojzes se je dvignil in odšel k Datánu in Abirámu, in Izraelove starešine so mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Spregovoril je skupnosti, rekoč: »Odidite, prosim vas, od šotorov teh zlobnežev in ne dotikajte se ničesar njihovega, da ne bi bili použiti v vseh njihovih grehih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Tako so se na vsaki strani umaknili od šotora Koraha, Datána in Abiráma. Datán in Abirám pa sta prišla ven in stala v vratih svojih šotorov s svojima ženama, svojimi sinovi in svojimi majhnimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Mojzes je rekel: »S tem boste spoznali, da me je poslal Gospod, da storim vsa ta dela, kajti nisem jih storil po svoji lastni pameti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Če ti možje umrejo običajne smrti vseh ljudi, ali če so obiskani po obiskanju vseh ljudi, potem me Gospod ni poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Toda če Gospod naredi novo stvar in zemlja odpre svoja usta in jih požre, z vsem, kar jim pripada in gredo hitro dol v jamo, potem boste razumeli, da so ti ljudje izzivali Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Pripetilo se je, ko je končal govorjenje vseh teh besed, da so se tla, ki so bila pod njimi, razklala narazen');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'in zemlja je odprla svoja usta in jih požrla in njihove hiše in vse ljudi, ki so pripadali Korahu in vse njihove dobrine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Oni in vsi, ki so pripadali k njim, so živi odšli dol v jamo, in zemlja se je zaprla nad njimi in izginili so iz skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Vsi Izraelci, ki so bili naokoli njih, so pobegnili ob njihovem kričanju, kajti rekli so: »Da ne bi zemlja požrla tudi nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'In prišel je ogenj od Gospoda in použil dvesto petdeset mož, ki so darovali kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '»Govori Eleazarju, sinu duhovnika Arona, da kadilnice pobere iz gorenja, ogenj pa iztrese daleč proč, kajti te so posvečene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Kadilnice teh grešnikov [ki so grešili] zoper svoje lastne duše, naj preoblikujejo v široke plošče za pokritje oltarja, kajti darovali so jih pred Gospodom, zato so posvečene in te bodo znamenje Izraelovim otrokom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Duhovnik Eleazar je vzel bronaste kadilnice, s katerimi so darovali tisti, ki so bili sežgani in preoblikovane so bile v široke plošče za pokritje oltarja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'da bodo spomin Izraelovim otrokom, da noben tujec, ki ni od Aronovega semena, ne pride blizu, da bi daroval Gospodu, da ne bo kakor Korah in kakor njegova skupina; kakor mu je po Mojzesovi roki rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Toda naslednji dan je vsa skupnost Izraelovih otrok mrmrala zoper Mojzesa in zoper Arona, rekoč: »Vidva sta ubila Gospodovo ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Pripetilo se je, ko je bila zoper Mojzesa in Arona zbrana skupnost, da so pogledali proti šotorskemu svetišču skupnosti in glej, pokrival ga je oblak in prikazala se je Gospodova slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'In Mojzes in Aron sta prišla pred šotorsko svetišče skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '»Vzdignita se proč izmed te skupnosti, da jih lahko v hipu použijem.« In onadva sta padla na svoja obraza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Mojzes je rekel Aronu: »Vzemi kadilnico, daj vanjo ogenj iz oltarja, nanj položi kadilo in hitro pojdi k skupnosti ter opravi spravo zanje, kajti od Gospoda je izšel bes. Začela se je kužna bolezen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Aron je vzel, kakor je Mojzes zapovedal in stekel na sredo skupnosti. In glej, kuga se je začela med ljudstvom. In nanjo je položil kadilo ter opravil spravo za ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Stal je med mrtvimi in živimi in kužna bolezen je obstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Torej tistih, ki so umrli od kužne bolezni, je bilo štirinajst tisoč sedemsto, poleg tistih, ki so umrli zaradi Korahove zadeve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'In Aron se je vrnil k Mojzesu, k vratom šotorskega svetišča skupnosti in kužna bolezen je obstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '»Govori Izraelovim otrokom in vzemi od vsakega izmed njih palico glede na hišo njihovih očetov, od vseh njihovih princev glede na hišo njihovih očetov, dvanajst palic. Ime vsakega moža zapiši na njegovo palico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Aronovo ime boš zapisal na Lévijevo palico, kajti ena palica bo za poglavarja hiše njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, '§ Položil jih boš v šotorsko svetišče skupnosti, pred pričevanje, kjer se bom srečal s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'In zgodilo se bo, da bo palica moža, ki ga bom jaz izbral, zacvetela in naredil bom, da pred menoj prenehajo mrmranja Izraelovih otrok, s čimer so mrmrali zoper vaju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Mojzes je spregovoril Izraelovim otrokom in vsak izmed njihovih princev mu je dal palico, za vsakega princa eno, glede na hiše njihovih očetov, torej dvanajst palic in Aronova palica je bila med njihovimi palicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Mojzes je palice položil pred Gospoda v šotorskem svetišču pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Pripetilo se je, da je naslednji dan Mojzes odšel v šotorsko svetišče pričevanja in glej, Aronova palica, za Lévijevo hišo, je vzbrstela, pognala brste, pokazala cvetove in obrodila mandlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Mojzes je vse palice prinesel izpred Gospoda k vsem Izraelovim otrokom. Pogledali so in vsak mož je vzel svojo palico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Gospod je rekel Mojzesu: »Aronovo palico ponovno prinesi pred pričevanje, da bo kot simbol ohranjena zoper upornike, in njihova mrmranja boš popolnoma odvzel od mene, da ne bodo pomrli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mojzes je storil tako. Kakor mu je Gospod zapovedal, tako je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Izraelovi otroci so govorili Mojzesu, rekoč: »Glej, umiramo, izginjamo, mi vsi izginjamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kdorkoli prihaja kakorkoli blizu Gospodovega šotorskega svetišča bo umrl. Mar bomo použiti z umirajočimi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Gospod je rekel Aronu: »Ti, tvoji sinovi in hiša tvojega očeta s teboj bodo nosili krivičnost svetišča. Ti in tvoji sinovi s teboj boste nosili krivičnost svojega duhovništva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Tudi svoje brate iz Lévijevega rodu, rodu svojega očeta, privedi s seboj, da bodo lahko pridruženi k tebi in ti služili, toda ti in tvoji sinovi s teboj boste služili pred šotorskim svetiščem pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Pazili bodo na tvojo zadolžitev in zadolžitev vsega šotorskega svetišča. Samo ne bodo se približali posodam svetišča in oltarju, da ne bi niti oni niti tudi vi ne umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Pridruženi bodo k tebi in pazili bodo na zadolžitev šotorskega svetišča skupnosti, za vso službo šotorskega svetišča. Tujec pa se vam ne bo približal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Pazili boste na zadolžitev svetišča in zadolžitev oltarja, da nad Izraelovimi otroki ne bo več besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Glejte, jaz sem vzel vaše brate, Lévijevce, izmed Izraelovih otrok. Vam so izročeni kakor darilo za Gospoda, da opravljajo službo šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Zato boste ti in tvoji sinovi s teboj, varovali svojo duhovniško službo za vsako oltarno stvar in znotraj zagrinjala; in vi boste služili. Duhovniško službo sem vam dal kakor službo darila. Tujec pa, ki pride blizu, bo usmrčen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Gospod je spregovoril Aronu: »Glej, dal sem ti tudi zadolžitev mojih vzdigovalnih daritev izmed vseh posvečenih stvari Izraelovih otrok. Tebi sem jih dal zaradi razloga maziljenja in tvojim sinovom, z odredbo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'To bodo tvoje najsvetejše stvari, ohranjene pred ognjem. Vsak njihov dar, vsaka njihova jedilna daritev in vsaka njihova daritev za greh in vsaka njihova daritev za prestopek, ki mi jih bodo povrnili, bo zate in za tvoje sinove najsvetejša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Na najsvetejšem kraju boš to jedel. Vsak moški bo to jedel. To ti bo sveto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'In to je tvoje; vzdigovalna daritev njihovega darila z vsemi majalnimi daritvami Izraelovih otrok. Dal sem jih tebi in tvojim sinovim in tvojim hčeram s teboj, po zakonu na veke; vsak, kdor je v tvoji hiši čist, bo jedel od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Najboljše od olja in najboljše od vina in od pšenice, njihove prve sadove, ki jih bodo darovali Gospodu, te sem dal tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'In karkoli je prvo zrelo v deželi, kar bodo prinesli Gospodu, bo tvoje; vsak, kdor je v tvoji hiši čist, bo jedel od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Vsaka posvečena stvar v Izraelu, naj bo tvoja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Vsaka stvar, ki odpre maternico v vsem mesu, ki ga prinašajo h Gospodu, naj bo to od ljudi ali živali, bo tvoja. Vendar zagotovo odkupi človeškega prvorojenca in odkupil boš prvence nečistih živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Tiste, ki naj bi bili odkupljeni, mesec dni stare, boš odkupil glede na svojo oceno, za denar petih šeklov, po svetiščnem šeklu, kar je dvajset ger.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Toda prvenca krave ali prvenca ovce ali prvenca koze ne boš odkupil; oni so sveti. Njihovo kri boš poškrôpil na oltar in njihovo tolščo boš sežgal za ognjeno daritev, v prijeten vonj Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Njihovo meso bo tvoje, kakor so tvoje majalne prsi in desno pleče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Vse vzdigovalne daritve svetih stvari, ki jih Izraelovi otroci darujejo Gospodu, sem dal tebi in tvojim sinovim in tvojim hčeram s teboj, po zakonu na veke. To je solna zaveza na veke pred Gospodom, tebi in tvojemu potomstvu s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Gospod je govoril Aronu: »Ne boš imel dediščine v svoji deželi niti ne boš imel nobenega deleža med njimi. Jaz sem tvoj delež in tvoja dediščina med Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Glej, Lévijevim otrokom sem dal za dediščino vse desetine v Izraelu, za njihovo službo, ki jo služijo, torej službo šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Niti se Izraelovi otroci odslej ne smejo približati šotorskemu svetišču skupnosti, da ne bi nosili greha in umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Temveč bodo Lévijevci opravljali službo šotorskega svetišča skupnosti in nosili bodo njihovo krivičnost. To bo zakon na veke skozi vaše rodove, da med Izraelovimi otroki ne bodo imeli nobene dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Toda desetine Izraelovih otrok, ki jih darujejo kakor vzdigovalno daritev Gospodu, sem dal v dediščino Lévijevcem. Zato sem jim rekel: ›Med Izraelovimi otroki ne bodo imeli nobene dediščine.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '»Tako spregovori Lévijevcem in jim povej: ›Kadar od Izraelovih otrok vzamete desetine, ki sem vam jih od njih dal za vašo dediščino, potem boste od tega darovali vzdigovalno daritev za Gospoda, celó deseti del desetine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'In ta vaša vzdigovalna daritev se vam bo štela kakor, da bi bilo žito iz mlatišča in kakor polnost vinske stiskalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tako boste tudi vi darovali vzdigovalno daritev Gospodu od vseh svojih desetin, ki jih prejmete od Izraelovih otrok in od tega boste dali Gospodovo vzdigovalno daritev duhovniku Aronu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Izmed vseh vaših darov bo vsak daroval vzdigovalno daritev Gospodu, od vsega najboljšega od tega, celó posvečen del od tega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Zato jim boš rekel: ›Ko ste vzdignili najboljše od tega, potem bo to šteto Lévijevcem kakor donos mlatišča in kakor donos vinske stiskalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'To boste jedli na vsakem kraju, vi in vaše družine, kajti to je vaša nagrada za vašo službo v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Zaradi tega ne boste nosili nobenega greha, ko ste vzdignili najboljše od tega. Niti ne boste oskrunili svetih stvari Izraelovih otrok, da ne umrjete.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Gospod je spregovoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '»To je odredba postave, ki jo je zapovedal Gospod, rekoč: ›Govorita Izraelovim otrokom, da vama privedejo rdečo telico brez madeža, na kateri ni nobene pomanjkljivosti in na katero nikoli ni prišel jarem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Izročili jo boste duhovniku Eleazarju, da jo odvede zunaj tabora in nekdo jo bo zaklal pred njegovim obrazom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Duhovnik Eleazar bo s svojim prstom vzel od njene krvi in sedemkrat poškropil neposredno pred šotorskim svetiščem skupnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'in nekdo bo telico sežgal v njegovem pogledu; njeno kožo, njeno meso in njeno kri bo sežgal z njenim iztrebkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Duhovnik bo vzel cedrov les, izop in škrlat in to vrgel v sredo goreče telice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Potem bo duhovnik opral svoja oblačila, svoje meso umil v vodi in potem bo prišel v tabor in duhovnik bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Kdor jo zažiga, bo svoja oblačila opral v vodi in svoje meso okopal v vodi in bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Človek, ki je čist, bo zbral pepel telice in ga položil zunaj tabora, na čisto mesto in tam bo hranjen za skupnost Izraelovih otrok, za vodo oddvojitve. To je očiščevanje za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Kdor zbira pepel telice, bo opral svoja oblačila in bo nečist do večera. To bo za Izraelove otroke in tujca, ki začasno prebiva med njimi, zakon na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kdor se dotika trupla kateregakoli človeka, bo sedem dni nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'S to [vodo] se bo očistil na tretji dan in na sedmi dan bo čist. Toda če se ne očisti tretji dan, potem sedmi dan ne bo čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kdorkoli se dotika trupla kateregakoli človeka, ki je mrtev in se ne očisti, omadežuje Gospodovo šotorsko svetišče, in ta duša bo iztrebljena iz Izraela. Ker voda oddvojitve ni bila poškropljena nad njim, bo nečist; njegova nečistost je še nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'To je postava, če človek umre v šotoru. Vse, kar pride v šotor in vse, kar je v šotoru, bo nečisto sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Vsaka odprta posoda, ki na sebi nima privezanega pokrivala, je nečista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Kdorkoli se dotakne tistega, ki je na odprtih poljih umorjen z mečem ali trupla ali človeške kosti, ali groba, bo sedem dni nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Za nečisto osebo bodo vzeli pepel sežgane telice očiščevanja za greh in tekoča voda bo vlita k temu v posodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Čista oseba bo vzela izop in ga pomočila v vodi in ga poškropila po šotoru in po vseh posodah in po osebah, ki so bile tam in na tistega, ki se je dotaknil kosti umorjenega,ali nekoga umorjenega, ali nekoga mrtvega ali groba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Čista oseba bo poškropila na nečisto na tretji dan in na sedmi dan. Na sedmi dan se bo mož očistil in opral svoja oblačila in se okopal v vodi in bo zvečer čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Toda mož, ki bo nečist in se ne bo očistil, ta duša bo iztrebljena izmed skupnosti, ker je omadeževal Gospodovo svetišče. Voda oddvojitve ni bila poškropljena nanj; ta je nečist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'To jim bo večen zakon, da kdor škropi vodo oddvojitve, bo opral svoja oblačila; in kdor se dotika vode oddvojitve, bo nečist do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Česarkoli se nečista oseba dotika, bo nečisto; in duša, ki se tega dotika, bo nečista do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Potem so prišli Izraelovi otroci, torej celotna skupnost, v puščavo Cin, v prvem mesecu, in ljudstvo je ostalo v Kadešu in Mirjam je tam umrla in bila tam pokopana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Tam pa ni bilo nobene vode za skupnost in skupaj so se zbrali zoper Mojzesa in zoper Arona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Ljudje so se pričkali z Mojzesom in govorili, rekoč: »Da bi Bog dal, da bi umrli, ko so naši bratje umrli pred Gospodom!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'In zakaj sta Gospodovo skupnost privedla gor v to divjino, da bi mi in naša živina v njej umrli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'In zakaj sta nas pripravila, da pridemo gor iz Egipta, da nas privedeta na ta zlobni kraj? To ni kraj semen ali fig ali vinskih trt ali granatnih jabolk niti ni tukaj nobene vode za pitje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mojzes in Aron sta od prisotnosti zbora odšla k vratom šotorskega svetišča skupnosti ter padla na svoja obraza in prikazala se jima je Gospodova slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '»Vzemi palico in ti in tvoj brat Aron zberita skupaj skupnost in pred njihovimi očmi spregovorita skali in ta bo dala svojo vodo in ti jim boš prinesel vodo iz skale. Tako boš dal piti zboru in njihovim živalim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Mojzes je vzel palico izpred Gospoda, kakor mu je zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Mojzes in Aron sta pred skalo zbrala skupnost in jim rekla: »Poslušajte sedaj, vi uporniki, ali vam moreva iz te skale izpeljati vodo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Mojzes je dvignil svojo roko in s svojo palico dvakrat udaril skalo in voda se je obilno prikazala in skupnost je pila in tudi njihove živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Gospod pa je spregovoril Mojzesu in Aronu: »Ker mi nista verovala, da bi me izkazala svetega v očeh Izraelovih otrok, zato te skupnosti ne bosta privedla v deželo, ki sem jim jo dal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'To je voda iz Meríbe; ker so se Izraelovi otroci prepirali z Gospodom in je bil on posvečen v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Mojzes je k edómskemu kralju poslal poslance iz Kadeša: »Tako govori tvoj brat Izrael: ›Ti poznaš vse muke, ki so nas doletele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Kako so naši očetje odšli dol v Egipt in smo dolgo časa prebivali v Egiptu; Egipčani pa so dražili nas in naše očete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'In ko smo klicali h Gospodu, je slišal naš glas in poslal angela in nas privedel iz egiptovske dežele. In glej, mi smo v Kadešu, v mestu na tvoji najbolj oddaljeni meji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Naj prečkamo, prosim te, skozi tvojo deželo. Ne bomo šli skozi polja ali skozi vinograde niti ne bomo pili vode iz vodnjakov. Šli bomo po kraljevi visoki poti, ne bomo se obrnili k desni roki niti ne k levi, dokler ne prečkamo tvojih meja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edóm pa mu je rekel: »Ne boš prečkal poleg mene, da ne bi jaz z mečem prišel zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Izraelovi otroci so mu rekli: »Šli bomo po visoki poti. In če jaz in moja živina pije od tvoje vode, potem bom plačal zanjo. Samo šel bom, ne da bi počel karkoli drugega bom šel skozi po svojih stopalih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Rekel je: »Ne boš šel skozi.« In Edóm je prišel ven zoper njega, z mnogo ljudstva in z močno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Tako je Edóm odklonil dati Izraelu prehod skozi njegovo mejo, zato se je Izrael obrnil proč od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Izraelovi otroci, torej celotna skupnost, so potovali od Kadeša in prišli na goro Hor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Gospod je govoril Mojzesu in Aronu na gori Hor, ob meji dežele Edóm, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '»Aron bo zbran k svojemu ljudstvu, kajti ne bo vstopil v deželo, ki sem jo dal Izraelovim otrokom, ker sta se uprla zoper mojo besedo pri vodi Meríbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Vzemi Arona in njegovega sina Eleazarja ter ju privedi gor na goro Hor');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'in sleci Arona iz njegovih oblačil in jih nadeni na njegovega sina Eleazarja. Aron pa bo zbran k svojim ljudem in bo tam umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mojzes je storil kakor je Gospod zapovedal in odšli so na goro Hor pred očmi vse skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Mojzes je slekel Arona iz njegovih oblačil in jih nadel na njegovega sina Eleazarja in Aron je tam umrl, na vrhu gore, in Mojzes in Eleazar sta prišla dol z gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Ko je vsa skupnost videla, da je bil Aron mrtev, so trideset dni žalovali za Aronom, celó vsa Izraelova hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Ko je kralj Arád, Kánaanec, ki je prebival na jugu, slišal govorico, da je Izrael prišel po poti oglednikov, potem se je bojeval zoper Izrael in nekatere izmed njih prijel kot jetnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Izrael se je zaobljubil Gospodu in rekel: »Če zares hočeš to ljudstvo izročiti v mojo roko, potem bom popolnoma uničil njihova mesta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Gospod je prisluhnil Izraelovemu glasu in izročil Kánaance, in popolnoma so jih uničili in njihova mesta in ime kraja je imenoval Horma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Odpotovali so z gore Hor po poti Rdečega morja, da obidejo deželo Edóm in duša ljudstva je zaradi poti zelo izgubila pogum.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Ljudstvo je govorilo zoper Boga in zoper Mojzesa: »Zakaj sta nas privedla gor iz Egipta, da umremo v divjini? Kajti tukaj ni kruha niti tukaj ni nobene vode in naši duši se gabi ta lahek kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Gospod pa je med ljudstvo poslal ognjene kače in te so pikale ljudstvo in mnogo Izraelovega ljudstva je umrlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Zato je ljudstvo prišlo k Mojzesu in reklo: »Grešili smo, kajti govorili smo zoper Gospoda in zoper tebe. Moli h Gospodu, da kače odvzame od nas.« In Mojzes je molil za ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Gospod je rekel Mojzesu: »Naredi si ognjeno kačo in jo obesi na kol, in zgodilo se bo, da vsak, kdor je pičen, ko pogleda nanjo, bo živel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Mojzes je naredil kačo iz brona in jo obesil na kol in pripetilo se je, da če je kateregakoli človeka pičila kača, ko je pogledal kačo iz brona, je živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Izraelovi otroci so se namerili naprej in se utaborili v Obótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'In odpotovali so iz Obóta in se utaborili pri Ijé Abarímu, v divjini, ki je pred Moábom, proti sončnemu vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Od tam so odrinili in se utaborili v dolini Zared.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Od tam so odrinili in se utaborili na drugi strani Arnóna, ki je v divjini, ki prihaja iz pokrajin Amoréjcev, kajti Arnón je Moábova meja med Moábom in Amoréjci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, '§ Zato je rečeno v knjigi Gospodovih vojn: »Kaj je storil v Rdečem morju in v potokih Arnóna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'in pri vodotoku potokov, ki gredo dol k prebivališču Ar in leži na Moábovi meji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'In od tam so odšli v Beêr, to je vodnjak, o katerem je Gospod govoril Mojzesu: »Zberi skupaj ljudstvo in jaz jim bom dal vodo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Potem je Izrael zapel to pesem: »Izviraj, o vodnjak. Pojte mu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Princi so kopáli vodnjak, kopáli so ga plemiči izmed ljudstva, po navodilih postavodajalca, s svojimi palicami.« In iz divjine so odšli k Matánu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'in od Matána v Nahaliél, in iz Nahaliéla v Bamót,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, '§ in iz Bamóta v dolino, ki je v moábski deželi, do vrha Pisge, ki gleda proti Ješimonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Izrael je poslal poslance k Sihónu, kralju Amoréjcev, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '»Pusti mi iti skozi tvojo deželo. Ne bomo se obrnili v polja ali v vinograde; ne bomo pili od vodá iz vodnjaka, temveč bomo šli vzdolž po kraljevi visoki poti, dokler ne bomo prešli tvojih mej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Sihón pa ni hotel trpeti, da gre Izrael skozi njegove meje, temveč je Sihón zbral vse ljudstvo in odšel ven zoper Izrael v divjino in prišel v Jahac in se bojeval zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Izrael pa ga je udaril z ostrino meča in vzel v last njegovo deželo od Arnóna do Jabóka, celo do Amónovih otrok, kajti meja Amónovih otrok je bila trdna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Izrael je zavzel vsa ta mesta in Izrael je prebival v vseh mestih Amoréjcev v Hešbónu in v vseh njegovih vaseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Kajti Hešbón je bil mesto amoréjskega kralja Sihóna, ki se je bojeval zoper prejšnjega moábskega kralja in je vso njegovo deželo vzel iz njegove roke, celo do Arnóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Zato tisti, ki govorijo v pregovorih, pravijo: »Pridite v Hešbón, naj bo Sihónovo mesto zgrajeno in pripravljeno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'kajti ogenj je odšel iz Hešbóna, plamen iz mesta Sihón. Ta je použil Ar Moáb in gospodarje visokih krajev Arnóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Gorje tebi, Moáb! Uničeno si, oh ljudstvo Kemoša. Svojim sinovom je dal, da pobegnejo in svoje hčere v ujetništvo Sihónu, kralju Amoréjcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Streljali smo nanje, Hešbón je uničen celo do Dibóna in opustošili smo jih celo do Nofa, ki sega do Médebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Tako je Izrael prebival v deželi Amoréjcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'In Mojzes je poslal, da ogledajo Jaazêr in zavzeli so njegove vasi in napodili Amoréjce, ki so bili tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'In obrnili so se ter odšli gor, po poti Bašána in bašánski kralj Og je odšel ven zoper njih, on in vse njegovo ljudstvo, da se bojujejo pri Edréi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Gospod je rekel Mojzesu: »Ne boj se ga, kajti izročil sem ga v tvojo roko in vse njegovo ljudstvo in njegovo deželo in storil mu boš, kakor si storil Sihónu, kralju Amoréjcev, ki je prebival pri Hešbónu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Tako so udarili njega, njegove sinove in vse njegovo ljudstvo, dokler nihče ni ostal živ, in njegovo deželo vzeli v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Izraelovi otroci so se namerili naprej in se utaborili na moábskih ravninah, na tej strani Jordana, pri Jerihi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Cipórjev sin Balák je videl vse, kar je Izrael storil Amoréjcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Moáb je bil boleče prestrašen ljudstva, ker jih je bilo mnogo in Moáb je bil zaskrbljen zaradi Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Moáb je rekel midjánskim starešinam: »Sedaj bo ta skupina polizala vse, ki so naokoli nas, kakor vol pomuli poljsko travo.« Cipórjev sin Balák je bil ob tistem času kralj Moábcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Poslal je torej poslance k Beórjevemu sinu Bileámu v Petór, ki je poleg reke dežele otrok njegovega ljudstva, da ga pokliče, rekoč: »Glej, tam je ljudstvo prišlo iz Egipta. Glej, pokrivajo obličje zemlje in prebivajo nasproti meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Pridi torej sedaj, prosim te, prekolni mi to ljudstvo, kajti oni so premogočni zame. Morda bom prevladal, da jih lahko udarimo in da jih lahko napodimo iz dežele, kajti vem, da kogar ti blagosloviš, je blagoslovljen in kogar ti prekolneš, je preklet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Moábske starešine in midjánske starešine so odrinili z nagradami vedeževanja v svoji roki in prišli k Bileámu in mu spregovorili Balákove besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'In ta jim je rekel: »To noč prenočite tukaj in ponovno vam bom prinesel besedo, kakor mi bo Gospod govoril,« in Moábovi princi so ostali z Bileámom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Bog je prišel k Bileámu in rekel: »Kakšni možje so tile s teboj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileám je rekel Bogu: »Cipórjev sin Balák, moábski kralj, je poslal k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '›Glej, tam je prišlo ljudstvo iz Egipta, ki pokriva obličje zemlje. Pridi sedaj, prekolni mi jih. Morda jih bom zmožen premagati in jih pognati ven.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Bog pa je rekel Bileámu: »Ne boš šel z njimi, ne boš preklel ljudstva, kajti blagoslovljeni so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Bileám je zjutraj vstal in Balákovim princem rekel: »Pojdite v svojo deželo, kajti Gospod mi odklanja dati dovoljenje, da grem z vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Moábski princi so vstali, odšli k Baláku in rekli: »Bileám odklanja, da pride z nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balák je ponovno poslal prince, več in častitljivejše od onih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Prišli so k Bileámu in mu rekli: »Tako govori Cipórjev sin Balák: ›Naj te ničesar, prosim te, ne ovira, da bi prišel k meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'kajti povišal te bom v zelo veliko čast in storil bom kakorkoli mi rečeš. Pridi torej, prosim te, prekolni mi to ljudstvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileám je odgovoril ter Balákovim služabnikom rekel: »Če bi mi Balák dal svojo hišo, polno srebra in zlata, ne morem iti preko besede od Gospoda, svojega Boga, da storim manj ali več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Zdaj torej, prosim vas, tudi vi ostanite tukaj to noč, da bom lahko vedel, kaj mi bo še povedal Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Bog je ponoči prišel k Bileámu ter mu rekel: »Če pridejo možje, da te pokličejo, vstani in pojdi z njimi, toda reci jim samo besedo, ki ti jo bom jaz rekel, to boš storil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Bileám je zjutraj vstal, osedlal svojo oslico in se odpravil k moábskim princem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Božja jeza je bila vžgana, ker je odšel in Gospodov angel je stal na poti za nasprotnika zoper njega. Torej jahal je na svoji oslici in dva njegova služabnika sta bila z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'In oslica je zagledala Gospodovega angela stati na poti in njegov meč je bil izvlečen v njegovi roki in oslica se je obrnila stran iz poti in odšla na polje. Bileám pa je udaril oslico, da jo obrne na pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Toda Gospodov angel je stal na stezi vinogradov, zid pa je bil na tej strani in zid na oni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Ko je oslica zagledala Gospodovega angela, se je pritisnila k zidu in Bileámovo stopalo zmečkala ob zid in ta jo je ponovno udaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Gospodov angel je šel naprej in stal na ozkem kraju, kjer ni bilo nobene poti, da bi se obrnil k desni roki ali k levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Ko je oslica zagledala Gospodovega angela, je pod Bileámom padla dol in Bileámova jeza je bila vžgana in oslico je udaril s palico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Gospod pa je oslici odprl usta in ta je Bileámu rekla: »Kaj sem ti storila, da si me že trikrat udaril?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileám je rekel oslici: »Ker si me zasmehovala. Če bi bil tukaj, v moji roki meč, bi te sedaj že ubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Oslica pa je Bileámu rekla: »Ali nisem tvoja oslica, na kateri si jahal, odkar sem bila tvoja, do današnjega dne? Sem imela kdaj navado, da ti tako storim?« Rekel je: »Ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Potem je Gospod Bileámu odprl oči in zagledal je Gospodovega angela, stoječega na poti in njegov meč je bil izvlečen v njegovi roki. Sklonil je svojo glavo in padel plosko na svoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Gospodov angel mu je rekel: »Zakaj si potem že trikrat udaril svojo oslico? Glej, odšel sem ven, da se ti zoperstavim, ker je tvoja pot sprevržena pred menoj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'oslica pa me je zagledala in se že trikrat obrnila od mene. Razen če se ne bi obrnila od mene, bi te sedaj torej zagotovo ubil, njo pa rešil živo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Bileám je rekel Gospodovemu angelu: »Grešil sem, kajti nisem vedel, da zoper mene stojiš na poti. Sedaj torej, če te je to razžalilo, se bom ponovno vrnil nazaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Gospodov angel je Bileámu rekel: »Pojdi z možmi, toda samo besedo, ki ti jo jaz govorim, to boš govoril.« Tako je Bileám odšel z Balákovimi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Ko je Balák slišal, da je Bileám prišel, je odšel ven, da ga pospremi v mesto Moáb, ki je na meji Arnóna, ki je skrajna pokrajina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Balák je rekel Bileámu: »Ali nisem iskreno poslal k tebi, da te pokličem? Čemu nisi prišel k meni? Mar te zares ne zmorem povišati k časti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bileám je rekel Baláku: »Glej, prišel sem k tebi. Imam zdaj sploh moč, da karkoli povem? Besedo, ki jo Bog polaga v moja usta, to bom govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Bileám je odšel z Balákom in prišla sta v Kirját Hucót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Balák je daroval vola in ovco in poslal k Bileámu in k princem, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Pripetilo se je naslednji dan, da je Balák vzel Bileáma in ga privedel gor na Báalov visok kraj, da bi od tam lahko videl skrajen del ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Bileám je rekel Baláku: »Tukaj mi zgradi sedem oltarjev in mi pripravi sedem volov ter sedem ovnov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balák je storil, kakor je Bileám govoril, in Balák in Bileám sta na vsakem oltarju darovala bikca in ovna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Bileám je rekel Baláku: »Stoj pri svoji žgalni daritvi, jaz pa bom šel. Morda bo prišel Gospod, da me sreča in karkoli mi pokaže, ti bom povedal.« In odšel je na visok kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Bog je srečal Bileáma in ta mu je rekel: »Pripravil sem sedem oltarjev in na vsakem oltarju sem daroval bikca in ovna.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Gospod je v Bileámova usta položil besedo ter rekel: »Vrni se k Baláku in tako boš govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Vrnil se je k njemu in glej, ta je stal poleg svoje žgalne daritve, on in vsi Moábovi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Vzel je njegovo prispodobo ter rekel: »Moábski kralj Balák me je privedel iz Aráma, iz vzhodnih gora, rekoč: ›Pridi, prekolni mi Jakoba in pridi izzivat Izraela.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kako naj prekolnem, kogar Bog ni preklel? Kako naj izzivam, kogar Gospod ni izzival?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Kajti od vrha skal ga vidim in od hribov ga gledam. Glej, ljudstvo bo prebivalo samo in ne bo šteto med narode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kdo lahko prešteje Jakobov prah in število četrtine Izraela? Naj umrem smrt pravičnega in naj bo moj zadnji konec podoben njegovemu!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Balák pa je rekel Bileámu: »Kaj si mi storil? Vzel sem te, da prekolneš moje sovražnike in glej, ti si jih vse skupaj blagoslovil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Ta je odgovoril in rekel: »Mar ne morem paziti, da govorim to, kar je Gospod položil v moja usta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balák mu je rekel: »Pridi, prosim te, z menoj na drug kraj, od koder jih lahko vidiš. Videl boš le njihov skrajni del, ne boš pa videl vseh, in od tam mi jih prekolni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Privedel ga je na polje Zofim, k vrhu Pisge in zgradil sedem oltarjev in na vsakem oltarju daroval bikca in ovna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Baláku je rekel: »Stoj tukaj pri svoji žgalni daritvi, medtem ko tam srečam Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Gospod je srečal Bileáma in v njegova usta položil besedo ter rekel: »Ponovno pojdi k Baláku in tako povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Ko je prišel k njemu, glej, je ta stal pri svoji žgalni daritvi in princi Moába z njim. In Balák mu je rekel: »Kaj je Gospod govoril?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Ta je vzel njegovo prispodobo ter rekel: »Vstani, Balák in poslušaj; prisluhni mi, ti, Cipórjev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bog ni človek, da bi lagal; niti človeški sin, da bi se moral kesati. Je rekel in tega ne bi storil? Je govoril in ali tega ne bi dobro naredil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Glej, prejel sem zapoved, da blagoslovim in on je blagoslovil in tega ne morem razveljaviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ni zagledal krivičnosti v Jakobu niti ni videl perverznosti v Izraelu. Gospod, njegov Bog, je z njim in krik kralja je med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bog jih je privedel iz Egipta; moč ima, kakor bi bila moč od samoroga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Zagotovo tam ni izrekanja uroka zoper Jakoba niti tam ni nobenega vedeževanja zoper Izraela. Glede na ta čas bo to rečeno o Jakobu in o Izraelu; ›Kaj je Bog storil!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Glej, ljudstvo bo vstalo kakor velik lev in se dvignilo kakor mlad lev. On se ne bo ulegel, dokler ne jé od plena in ne pije krvi umorjenega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Balák je rekel Bileámu: »Niti jih sploh ne preklinjaj niti jih sploh ne blagoslavljaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Toda Bileám je odgovoril in rekel Baláku: »Mar ti nisem rekel, rekoč: ›Vse, kar Gospod govori, to moram storiti?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balák je rekel Bileámu: »Pridi, prosim te, privedel te bom na drug kraj. Morda bo to ugajalo Bogu, da mi jih boš od tam preklel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, '§ In Balák je privedel Bileáma na vrh Peórja, ki gleda proti Ješimonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Bileám je rekel Baláku: »Tukaj mi zgradi sedem oltarjev in tukaj mi pripravi sedem bikcev in sedem ovnov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balák je storil kakor je Bileám rekel in na vsakem oltarju daroval bikca in ovna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Ko je Bileám videl, da je to ugajalo Gospodu, da blagoslovi Izraela, ni odšel kakor ob drugih časih, da išče za izrekanji urokov, temveč je svoj obraz nameril proti divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Bileám je povzdignil svoje oči in videl Izraela prebivati v svojih šotorih glede na svoje rodove in duh od Boga je prišel nadenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Vzel je njegovo prispodobo in rekel: »Bileám, Beórjev sin, je rekel in mož, katerega oči so odprte, je rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Rekel je tisti, ki je slišal besede od Boga, ki je videl vizijo Vsemogočnega pasti v videnje, toda svoje oči je imel odprte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kako ljubki so tvoji šotori, oh Jakob in tvoja šotorska svetišča, oh Izrael!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Kakor se doline širijo naprej, kakor vrtovi pri rečnem bregu, kakor drevesa aloje, ki jih je Gospod zasadil, in kakor cedrova drevesa poleg vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Vodo bo izlil iz svojih veder in njegovo seme bo na mnogih vodah in njegov kralj bo višji kakor Agág in njegovo kraljestvo bo povišano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bog ga je privedel iz Egipta; imel je, kakor bi bila moč samoroga. Pojedel bo narode svojih sovražnikov in njihove kosti bo zlomil in jih prebodel s svojimi puščicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Leži, ulegel se je kakor lev in kakor velik lev. Kdo ga bo razvnel? Blagoslovljen je, kdor te blagoslavlja in preklet je, kdor te preklinja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Balákova jeza je bila vžgana zoper Bileáma in svoji roki je udaril skupaj in Balák je rekel Bileámu: »Poklical sem te, da prekolneš moje sovražnike in glej, ti si jih vse skupaj trikrat blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Zato sedaj pobegni k svojemu kraju, Mislil sem te povišati k veliki časti; toda glej, Gospod te je zadržal pred častjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileám je rekel Baláku: »Mar nisem govoril tudi tvojim poslancem, ki si jih pošiljal k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '›Če bi mi Balák dal svojo hišo, polno srebra in zlata, ne morem preko Gospodove zapovedi, da storim ali dobro ali slabo iz svojega lastnega mišljenja, temveč bom govoril to, kar govori Gospod?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'In sedaj glej, grem k svojemu ljudstvu. Pridi torej in oznanil ti bom, kaj bo to ljudstvo storilo tvojemu ljudstvu v zadnjih dneh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Vzel je njegovo prispodobo in rekel: »Bileám, Beórjev sin, je rekel in mož, katerega oči so odprte, je rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, '›Rekel je ta, ki je slišal besede od Boga in poznal spoznanje Najvišjega, ki je videl videnje Vsemogočnega, padajoč v trans, toda z odprtimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Videl ga bom, toda ne sedaj. Gledal ga bom, toda ne [od] blizu. Prišla bo Zvezda iz Jakoba in Žezlo bo vstalo iz Izraela in udarilo bo Moábove vogale in uničilo vse Setove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edóm bo posest, tudi Seír bo posest za svoje sovražnike, Izrael pa bo delal junaško.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Iz Jakoba bo prišel tisti, ki bo imel gospostvo in uničil bo tistega, ki preostaja iz mesta.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Ko je pogledal na Amáleka, je vzel njegovo prispodobo ter rekel: »Amálek je bil prvi izmed narodov, toda njegov zadnji konec bo, da bo uničen na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Pogledal je na Kenéjce in vzel njegovo prispodobo ter rekel: »Trdno je tvoje bivališče in svoje gnezdo postavljaš v skalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Vendar bo Kenéjec opustošen, dokler te Asúr ne bo odvedel ujetega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Vzel je njegovo prispodobo in rekel: »Ojoj, kdo bo živel, ko Bog to dela!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Ladje bodo prišle iz pokrajin Kitéjcev in prizadele Asúr in Eber in tudi on bo uničen na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Bileám je vstal, odšel in se vrnil na svoj kraj in tudi Balák je odšel svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Izrael je prebival v Šitímu in ljudstvo se je začelo vlačugati z moábskimi hčerami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Ljudstvo so poklicali k žrtvovanjem njihovih bogov, in ljudstvo je jedlo in se priklonilo njihovim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Izrael se je pridružil Báal Peórju in Gospodova jeza je bila vžgana zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Gospod je rekel Mojzesu: »Vzemi vse poglavarje ljudstva in jih obesi pred Gospodom, nasproti soncu, da se bo kruta Gospodova jeza lahko odvrnila od Izraela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Mojzes je rekel Izraelovim sodnikom: »Vsak naj ubije svoje može, ki so bili pridruženi Báal Peórju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Glej, eden izmed Izraelovih otrok je prišel in k svojim bratom privedel midjánsko žensko pred očmi Mojzesa in pred očmi vse skupnosti Izraelovih otrok, ki so jokali pred vrati šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Ko je Pinhás, sin Eleazarja, sin duhovnika Arona, to videl, je vstal izmed skupnosti in v svojo roko vzel kopje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'in odšel za Izraelovim možem v šotor in oba izmed njiju prebodel, Izraelovega moškega in žensko je prebodel skozi njen trebuh. Tako je bila kuga ustavljena pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Teh, ki so v kugi umrli, je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '»Pinhás, sin Eleazarja, sin duhovnika Arona, je moj bes odvrnil proč od Izraelovih otrok, medtem ko je bil med njimi goreč zaradi mene, da ne bi jaz v svoji ljubosumnosti použil Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Zato reci: ›Glej, dam mu svojo zavezo miru');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'in imel jo bo in njegovo seme za njim, celó zavezo večnega duhovništva, ker je bil goreč za svojega Boga in opravil spravo za Izraelove otroke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Torej ime Izraelca, ki je bil umorjen, torej tistega, ki je bil umorjen z Midjánko, je bilo Salújev sin Zimrí, princ glavne hiše med Simeonovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Ime midjánske ženske, ki je bila umorjena, je bilo Kozbí, hči Cura. On je bil poglavar nad ljudstvom in vodja hiše v Midjánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '»Jezite Midjánce in jih udarite,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'kajti jezili so vas s svojimi zvijačami, s katerimi so vas preslepili v zadevi Peórja in v zadevi Kozbí, hčere midjánskega princa, njihove sestre, ki je bila umorjena na dan nadloge zaradi Peórja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Pripetilo se je po kugi, da je Gospod spregovoril Mojzesu in Eleazarju, sinu duhovnika Arona, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '»Popišite glave vse skupnosti Izraelovih otrok, od dvajsetih let starosti in naprej, po vseh njihovih očetnih hišah, vse, ki so v Izraelu zmožni, da gredo na vojno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Mojzes in duhovnik Eleazar sta z njimi spregovorila na moábskih ravninah, pri Jordanu, blizu Jerihe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '» Popišite glave ljudstva, od dvajsetih let starosti in naprej,« kakor je Gospod zapovedal Mojzesu in Izraelovim otrokom, ki so odšli iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, najstarejši Izraelov sin. Rubenovi otroci: Hénoh, iz katerega prihaja družina Hénohovcev, iz Palúja družina Palújevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Iz Hecróna družina Hecrónovcev, iz Karmíja družina Karmíjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'To so družine Rubenovcev in tistih, ki so bili izmed njih prešteti, je bilo triinštirideset tisoč sedemsto trideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Palújevi sinovi: Eliáb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Eliábovi sinovi: Nemuél, Datán in Abirám. To sta bila tista Datán in Abirám, ki sta bila slavna v skupnosti, ki sta se pričkala zoper Mojzesa in zoper Arona v Korahovi skupini, ko so se pričkali zoper Gospoda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'in zemlja je odprla svoja usta ter ju požrla skupaj s Korahom, ko je ta skupina umrla, ko je ogenj použil dvesto petdeset mož in postali so znamenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Vendar Korahovi otroci niso umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, '§ Simeonovi sinovi po njihovih družinah: iz Nemuéla družina Nemuélovcev, iz Jamina družina Jamínovcev, iz Jahína družina Jahínovcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'iz Zeraha družina Zerahovcev, iz Šaúla družina Šaúlovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'To so družine Simeoncev, dvaindvajset tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gadovi otroci po njihovih družinah: od Cefóna družina Cefónovcev, od Hagíja družina Hagíjevcev, od Šuníja družina Šuníjevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'od Ozníja družina Ozníjevcev, od Eríja družina Eríjevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'od Aróda družina Aródovcev, od Arelíja družina Arelíjcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'To so družine Gadovih otrok glede na tiste, ki so bili izmed njih prešteti, štirideset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Judova sinova sta bila Er in Onán, in Er in Onán sta umrla v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Judovi sinovi po njihovih družinah so bili: od Šelája družina Šelájevcev, od Pareca družina Parecovcev, od Zeraha družina Zerahovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Parecovi sinovi so bili: od Hecróna družina Hecrónovcev, od Hamúla družina Hamúlovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'To so Judove družine, glede na tiste, ki so bili izmed njih prešteti, šestinsedemdeset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Od Isahárjevih sinov po njihovih družinah: od Tolá družina Tolájevcev, od Puvá družina Puvájevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'od Jašúba družina Jašúbovcev, od Šimróna družina Šimrónovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'To so družine Isahárja, glede na tiste, ki so bili izmed njih prešteti, šestinsedemdeset tisoč tristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Od Zábulonovih sinov po njihovih družinah: od Sereda družina Seredovcev, od Elóna družina Elónovcev, od Jahleéla družina Jahleélovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'To so družine Zábulonovcev, glede na tiste, ki so bili izmed njih prešteti, šestdeset tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Jožefova sinova po svojih družinah sta bila Manáse in Efrájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Od Manásejevih sinov: od Mahírja družina Mahírjevcev in Mahír je zaplodil Gileáda. Iz Gileáda je izšla družina Gileádcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'To so Gileádovi sinovi: od Iezerja družina Iezerjevcev, od Heleka družina Helekovcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'in od Asriéla družina Asriélovcev in od Sihema družina Sihemcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'in od Šemidája družina Šemidájevcev in od Heferja družina Heferjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Celofhád, sin Heferja, pa ni imel sinov, temveč hčere in imena Celofhádovih hčera so bila Mahla, Noa, Hogla, Milka in Tirca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'To so Manásejeve družine in tistih, ki so bili izmed njih prešteti, dvainpetdeset tisoč sedemsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'To so Efrájimovi sinovi po njihovih družinah: od Šutélaha družina Šutélahovcev, od Beherja družina Beherjevcev, od Tahana družina Táhanovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'To so Šutélahovi sinovi: od Erána družina Eránovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'To so družine Efrájimovih sinov glede na tiste, ki so bili izmed njih prešteti, dvaintrideset tisoč petsto. To so Jožefovi sinovi po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjaminovi sinovi po njihovih družinah: od Bela družina Bélovcev, od Ašbéla družina Ašbélovcev, od Ahiráma družina Ahirámovcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'od Šufáma družina Šufámovcev, od Hufáma družina Hufámovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Belova sinova sta bila Ard in Naamán: od Arda družina Ardovcev in od Naamána družina Naamánovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'To so Benjaminovi sinovi po svojih družinah in tistih, ki so bili izmed njih prešteti, je bilo petinštirideset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'To so Danovi sinovi po svojih družinah: od Šuháma družina Šuhámovcev. To so Danove družine po svojih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Vseh družin Šuhámovcev, glede na tiste, ki so bili izmed njih prešteti, je bilo štiriinšestdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Od Aserjevih otrok po svojih družinah: od Jimnája družina Jimnájevcev, od Jišvíja družina Jišvíjevcev, od Berijá družina Berijájevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Berijájevi sinovi: od Heberja družina Heberjevcev, od Malkiéla družina Malkiélovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Ime Aserjeve hčere je bilo Sara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'To so družine Aserjevih sinov glede na tiste, ki so bili izmed njih prešteti, katerih je bilo triinpetdeset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Od Neftálijevih sinov po svojih družinah: od Jahceéla družina Jahceélovcev, od Guníja družina Guníjevcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'od Jecerja družina Jecerjevcev, od Šiléma družina Šilémovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'To so Neftálijeve družine glede na svoje družine. Tistih, ki so bili izmed njih prešteti, je bilo petinštirideset tisoč štiristo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ti so bili prešteti izmed Izraelovih otrok, šeststo en tisoč sedemsto trideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '»Tem bo dežela razdeljena v dediščino, glede na število imen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Mnogim boš dal več dediščine in maloštevilnim boš dal manj dediščine. Vsakomur bo njegova dediščina dana glede na tiste, ki jih je preštel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Vendar naj bo dežela razdeljena z žrebom. Dedujejo naj glede na imena rodov svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Njihova posest bo glede na žreb razdeljena med številne in maloštevilne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'To so tisti, ki so bili prešteti izmed Lévijevcev po njihovih družinah: iz Geršóna družina Geršónovcev, iz Keháta družina Kehátovcev, iz Meraríja družina Meraríjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'To so družine Lévijevcev: družina Libníjevcev, družina Hebróncev, družina Mahlíjevcev, družina Mušíjevcev, družina Kórahovcev. In Kehát je zaplodil Amráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Ime Amrámove žene je bilo Johébeda, Lévijeva hči, ki jo je njena mati rodila Leviju v Egiptu, in Amrámu je rodila Arona, Mojzesa in njuno sestro Mirjam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aronu so bili rojeni Nadáb, Abihú, Eleazar in Itamár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadáb in Abihú sta umrla, ko sta pred Gospodom darovala tuj ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Tistih, ki so bili izmed njih prešteti, je bilo triindvajset tisoč, vseh moških starih en mesec in več, kajti niso bili prešteti izmed Izraelovih otrok, ker jim ni bila dana dediščina med Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'To so tisti, ki sta jih preštela Mojzes in duhovnik Eleazar, ki sta Izraelove otroke preštela na moábskih ravninah pri Jordanu, blizu Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Toda med temi ni bilo moža izmed njih, ki ga Mojzes in duhovnik Aron ne bi preštela, ko so v Sinajski divjini šteli Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Kajti Gospod je o njih rekel: »Zagotovo bodo umrli v divjini.« In tam izmed njih ni ostalo nobenega moža razen Jefunéjevega sina Kaléba in Nunovega sina Józueta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Potem so prišle hčere Celofháda, sinú Heferja, sinú Gileáda, sinú Mahírja, sinú Manáseja, od družin Jožefovega sina Manáseja, in to so imena hčera: Mahla, Noa, Hogla, Milka in Tirca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Obstale so pred Mojzesom, pred duhovnikom Eleazarjem, pred princi in vso skupnostjo, pri vratih šotorskega svetišča skupnosti, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '»Naš oče je umrl v divjini in ni bil v skupini tistih, ki so se zbrali skupaj zoper Gospoda, v Korahovi skupini, temveč je umrl v svojem lastnem grehu in ni imel sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Zakaj bi bilo ime našega očeta odpravljeno od njegove družine, ker ni imel sina? Dajte nam torej posest med brati našega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mojzes je njihovo zadevo privedel pred Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '»Celofhádove hčere govorijo pravilno. Zagotovo jim boš dal posest dediščine med brati njihovih očetov in povzročil jim boš, da bo dediščina njihovega očeta prešla k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Izraelovim otrokom boš govoril, rekoč: ›Če mož umre in nima sina, potem boste njegovi dediščini povzročili, da preide na njegovo hčer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Če pa nima hčere, potem boste njegovo dediščino dali njegovim bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'In če nima bratov, potem boste njegovo dediščino dali bratom njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'In če njegov oče nima bratov, potem boste njegovo dediščino dali njegovemu sorodniku, ki je poleg njega, iz njegove družine in ta jo bo vzel v last in to bo Izraelovim otrokom zakon razsodbe,‹« kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Gospod je rekel Mojzesu: »Povzpni se gor na to goro Abarím in poglej deželo, ki sem jo dal Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Ko jo boš videl, boš tudi ti zbran k svojemu ljudstvu, kakor je bil zbran tvoj brat Aron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Kajti uprla ste se zoper mojo zapoved v Cinski puščavi, v prepiru skupnosti, da me izkažeta svetega pri vodi, pred njihovimi očmi, to je vodi iz Meríbe v Kadešu, v Cinski divjini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Mojzes je spregovoril Gospodu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '»Naj Gospod, Bog duhov vsega mesa, postavi moža nad skupnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'ki bo lahko odhajal pred njimi in ki bo lahko prihajal pred njimi in ki jih bo lahko vodil ven in ki jih bo lahko privedel noter, da Gospodova skupnost ne bo kakor ovce, ki nimajo pastirja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Gospod je rekel Mojzesu: »Vzemi si Nunovega sina Józueta, moža, v katerem je duh in svojo roko položi nanj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'in ga postavi pred duhovnika Eleazarja in pred vso skupnost in mu daj zadolžitev v njihovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Nekaj od svoje časti boš položil nanj, da bo vsa skupnost Izraelovih otrok lahko poslušna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Ta bo stal pred duhovnikom Eleazarjem, ki bo pred Gospodom zanj iskal nasvet po razsodbi urima. Na njegovo besedo bodo odhajali ven in na njegovo besedo bodo prihajali noter, tako on kot vsi Izraelovi otroci z njim, celo vsa skupnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mojzes je storil kakor mu je Gospod zapovedal. Vzel je Józueta in ga postavil pred duhovnika Eleazarja in pred vso skupnost');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'in svoji roki položil nanj in mu dal zadolžitev, kakor je Gospod zapovedal po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '»Zapovej Izraelovim otrokom in jim reci: ›Mojo daritev in moj kruh za moja žrtvovanja, narejena z ognjem, meni v prijeten vonj, boste obeleževali, da mi jih darujete v njihovem pravšnjem obdobju.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Rekel jim boš: ›To je ognjena daritev, ki jo boste darovali Gospodu: dve jagnjeti prvega leta, brez madeža, dan za dnem, za nenehno žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Eno jagnje boš daroval zjutraj in drugo jagnje boš daroval zvečer');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'in desetino škafa moke za jedilno daritev, pomešanega s četrtino vrča iztolčenega olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'To je nenehna žgalna daritev, ki je bila odrejena na gori Sinaj, za prijeten vonj, žrtvovanje, narejeno z ognjem, Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Njegova pitna daritev bo četrtina vrča za eno jagnje. Na svetem kraju boš povzročil, da bo močno vino izlito Gospodu za pitno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Drugo jagnje boš daroval zvečer. To boš daroval kakor jutranjo jedilno daritev in kakor njegovo pitno daritev, žrtvovanje, narejeno z ognjem, prijetnega vonja Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Na šabatni dan dve jagnjeti prvega leta, brez madeža in dve desetinki moke za jedilno daritev, umešano z oljem in njegovo pitno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'To je žgalna daritev vsakega šabata, poleg nenehne žgalne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Na začetku mesecev boste darovali žgalno daritev Gospodu: dva mlada bikca, enega ovna, sedem jagnjet prvega leta brez madeža,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'in tri desetinke moke za jedilno daritev, umešane z oljem za enega bikca, in dve desetinki moke za jedilno daritev, umešane z oljem, za enega ovna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'in več desetink moke, umešane z oljem za jedilno daritev enega jagnjeta, za žgalno daritev prijetnega vonja, žrtvovanje, narejeno z ognjem, Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Njihove pitne daritve bo polovica vrča vina za bikca in tretjina vrča za ovna in četrtina vrča za jagnje. To je žgalna daritev vsakega meseca za vse mesece leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Darovan bo en kozliček od koz za daritev za greh Gospodu, poleg nenehne žgalne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Na štirinajsti dan prvega meseca je Gospodova pasha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Na petnajsti dan tega meseca je praznovanje. Sedem dni se bo jedlo nekvašen kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Na prvi dan bo sveti sklic. Na ta dan ne boste počeli nobene vrste hlapčevskega dela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'temveč boste darovali žrtvovanje, narejeno z ognjem za žgalno daritev Gospodu: dva mlada bikca, enega ovna in sedem jagnjet prvega leta; ti vam bodo brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Njihova jedilna daritev bo moka, umešana z oljem: tri desetinke boste darovali za bikca in dve desetinki za ovna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'več desetink boš daroval za vsako jagnje, za vseh sedem jagnjet');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'in enega kozla za daritev za greh, da za vas opravi spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Te boste darovali poleg jutranje žgalne daritve, ki je za nenehno žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Na ta način boste darovali vsak dan, sedem dni, hrano žrtvovanja, narejeno z ognjem, prijetnega vonja Gospodu. To bo darovano poleg nenehne žgalne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Na sedmi dan boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Tudi na dan prvih sadov, ko prinesete Gospodu novo jedilno daritev, po preteku svojih tednov, boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'temveč boste darovali žgalno daritev v prijeten vonj Gospodu: dva mlada bikca, enega ovna, sedem jagnjet prvega leta');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'in njihovo jedilno daritev iz moke, umešane z oljem, tri desetinke za enega bikca, dve desetinki za enega ovna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'več desetink za eno jagnje, za sedem jagnjet');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'in enega kozlička od koz, da za vas opravi spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Darovali jih boste poleg nenehne žgalne daritve in njegove jedilne daritve (le-ti vam bodo brez pomanjkljivosti) in njihovih pitnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'V sedmem mesecu, na prvi dan meseca, boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali. To vam je dan trobentanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Darovali boste žgalno daritev v prijeten vonj Gospodu: enega mladega bikca, enega ovna in sedem jagnjet prvega leta brez pomanjkljivosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'in njihova jedilna daritev bo iz moke, umešane z oljem, tri desetinke za bikca in dve desetinki za ovna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'in ena desetinka za eno jagnje, za sedem jagnjet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'in enega kozlička od koz za daritev za greh, da za vas opravi spravo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'poleg mesečne žgalne daritve, njene jedilne daritve, dnevne žgalne daritve, njene jedilne daritve in njihovih pitnih daritev, glede na njihov način, za prijeten vonj, žrtvovanje, narejeno z ognjem, Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Na deseti dan sedmega meseca boste imeli sveti sklic in prizadeli boste svoje duše. Ta dan ne boste opravljali nobenega dela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'temveč boste darovali žgalno daritev Gospodu v prijeten vonj: enega mladega bikca, enega ovna in sedem jagnjet prvega leta, ki vam bodo brez pomanjkljivosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'in njihova jedilna daritev bo iz moke, umešane z oljem, tri desetinke za bikca in dve desetinki za enega ovna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'nekaj desetink za eno jagnje, za sedem jagnjet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'enega kozlička od koz za daritev za greh, poleg spravne daritve za greh in nenehne žgalne daritve in njegove jedilne daritve in njihovih pitnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Na petnajsti dan sedmega meseca boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali in sedem dni boste imeli praznovanje Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Darovali boste žgalno daritev, žrtvovanje, narejeno z ognjem, prijetnega vonja Gospodu: trinajst mladih bikcev, dva ovna in štirinajst jagnjet prvega leta; ti bodo brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Njihova jedilna daritev bo moka, umešana z oljem, tri desetinke vsakemu bikcu izmed trinajstih bikcev, dve desetinki vsakemu ovnu izmed dveh ovnov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'in nekaj desetink za vsako izmed štirinajstih jagnjet');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'in enega kozlička od koz za daritev za greh, poleg nenehne žgalne daritve, njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Na drugi dan boste darovali dvanajst mladih bikcev, dva ovna, štirinajst jagnjet prvega leta brez madeža,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'in njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'enega kozlička od koz za daritev za greh, poleg nenehne žgalne daritve in njegovih jedilnih daritev in njihovih pitnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Na tretji dan enajst bikcev, dva ovna, štirinajst jagnjet prvega leta brez pomanjkljivosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'in njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'enega kozla za daritev za greh, poleg nenehne žgalne daritve in njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Na četrti dan deset bikcev, dva ovna in štirinajst jagnjet prvega leta brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'enega kozlička od koz za daritev za greh, poleg nenehne žgalne daritve, njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Na peti dan devet bikcev, dva ovna in štirinajst jagnjet prvega leta brez madeža');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'in njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'enega kozla za daritev za greh, poleg nenehne žgalne daritve in njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Na šesti dan osem bikcev, dva ovna in štirinajst jagnjet prvega leta brez pomanjkljivosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'in njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'enega kozla za daritev za greh, poleg nenehne žgalne daritve, njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Na sedmi dan sedem bikcev, dva ovna in štirinajst jagnjet prvega leta brez pomanjkljivosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'in njihova jedilna daritev in njihove pitne daritve za bikce, za ovne in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'enega kozla za daritev za greh, poleg nenehne žgalne daritve, njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Na osmi dan boste imeli slovesen zbor. Nobenega hlapčevskega dela ne boste opravljali ta dan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'temveč boste žrtvovali žgalno daritev, žrtvovanje, narejeno z ognjem, prijetnega vonja Gospodu: enega bikca, enega ovna, sedem jagnjet prvega leta brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Njihova jedilna daritev in njihove pitne daritve za bikca, za ovna in za jagnjeta bodo glede na njihovo število, po načinu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'enega kozla za daritev za greh, poleg nenehne žgalne daritve in njegove jedilne daritve in njegove pitne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Te stvari boste storili Gospodu na svoje določene praznike, poleg svojih zaobljub in svojih prostovoljnih daritev za svoje žgalne daritve, jedilne daritve, pitne daritve in za svoje mirovne daritve.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Mojzes je Izraelovim otrokom povedal glede na vse, kar je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Mojzes je spregovoril poglavarjem rodov glede Izraelovih otrok, rekoč: »To je stvar, ki jo je Gospod zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Če se mož zaobljubi Gospodu zaobljubo ali priseže prisego, da svojo dušo zaveže z vezjo, ne bo prelomil svoje besede; storil bo glede na vse, kar je izšlo iz njegovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Če se tudi ženska zaobljubi Gospodu zaobljubo in se zaveže z vezjo, ko je v hiši svojega očeta, v svoji mladosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'in njen oče sliši njeno zaobljubo in njeno vez, s katero je zavezala svojo dušo in bo njen oče ob njej ohranil svoj mir, potem bodo vse njene zaobljube veljale in vsaka vez, s katero je zavezala svojo dušo, bo veljala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Toda če ji njen oče brani na dan, ko to sliši niti ena izmed njenih zaobljub ali izmed njenih vezi, s katerimi je zvezala svojo dušo, ne bo veljala in Gospod ji bo oprostil, ker ji je njen oče branil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Če pa je sploh imela soproga, ko se je zaobljubila ali izustila iz svojih ustnic, s čimer je zavezala svojo dušo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'in je njen soprog to slišal in je ob njej ohranil svoj mir na dan, ko je to slišal, potem bodo njene zaobljube veljale in njene vezi, s katerimi je zavezala svojo dušo, bodo veljale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Toda če ji njen soprog brani na dan, ko to sliši, potem bo naredil njeno zaobljubo, s katero se je zaobljubila in to, ki jo je izrekla s svojimi ustnicami, s katero je zavezala svojo dušo, brez učinka in Gospod ji bo oprostil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Toda vsaka zaobljuba vdove in tiste, ki je ločena, s katero so zavezale svoje duše, bo veljala zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Če se je zaobljubila v hiši svojega soproga ali je svojo dušo zavezala z vezjo prisege');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'in je njen soprog to slišal in ob njej ohranil svoj mir in ji ni branil, potem bodo vse njene zaobljube veljale in vsaka vez, s katero je zavezala svojo dušo, bo veljala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Toda če jih je njen soprog popolnoma izničil na dan, ko jih je slišal, potem karkoli je izšlo iz njenih ustnic glede njenih zaobljub ali glede vezi njene duše, ne bo veljalo. Njen soprog jih je izničil in Gospod ji bo oprostil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Vsako zaobljubo in vsako prisego, ki zadeva dušo, lahko njen soprog uveljavi ali izniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Toda če iz dneva v dan njen soprog ob njej povsem ohrani svoj mir, potem je vzpostavil vse njene zaobljube ali vse njene vezi, ki so na njej. Potrjuje jih, ker je ohranil svoj mir ob njej na dan, ko jih je slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Toda če jih bo na katerikoli način izničil, potem ko jih je slišal, potem bo nosil njeno krivičnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'To so zakoni, ki jih je Gospod zapovedal Mojzesu, med moškim in njegovo ženo, med očetom in njegovo hčerjo, ki je še v svoji mladosti, v hiši svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '»Maščuj se Midjáncem za Izraelove otroke, potem boš pridružen svojemu ljudstvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Mojzes je spregovoril ljudstvu, rekoč: »Oborožite nekatere izmed sebe za vojno in naj gredo zoper Midjánce in se maščujejo nad Midjánom za Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Po tisoč iz vsakega rodu, po vseh Izraelovih rodovih, boste poslali v vojno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Tako so bili izročeni iz tisočerih Izraelovih, po tisoč iz vsakega rodu, dvanajst tisoč oboroženih za vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Mojzes jih je poslal v vojno, tisoč iz vsakega rodu, njih in Pinhása, sina duhovnika Eleazarja, v vojno s svetimi pripravami in trobentami, da trobijo v njegovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Bojevali so se zoper Midjánce, kakor je Gospod zapovedal Mojzesu in vse moške usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Usmrtili so midjánske kralje, poleg drugih izmed tistih, ki so bili umorjeni, namreč Evíja, Rekema, Curja, Hura in Reba, pet midjánskih kraljev. Tudi Beórjevega sina Bileáma so umorili z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Izraelovi otroci so zajeli vse midjánske ženske in njihove malčke kot ujetnike in vzeli plen iz vseh njihovih mest in vse njihove trope in vse njihove dobrine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Z ognjem so požgali vsa njihova mesta, v katerih so prebivali, in vse njihove lepe gradove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Vzeli so vse blago in ves plen, tako od ljudi kakor od živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Ujetnike, plen in ukradeno blago so privedli k Mojzesu in duhovniku Eleazarju in k skupnosti Izraelovih otrok, k taboru na moábskih ravninah, ki so pri Jordanu, blizu Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Mojzes, duhovnik Eleazar in vsi princi skupnosti so odšli naprej, da jih srečajo zunaj tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mojzes je bil ogorčen nad častniki vojske, nad tisočniki in stotniki, ki so prišli iz bitke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Mojzes jim je rekel: »Ali ste vse ženske rešili žive?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Glejte, te so po Bileámovem nasvetu Izraelovim otrokom storile, da so v zadevi Peórja zagrešili prekršek zoper Gospoda in tam je bila kuga med Gospodovo skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Zdaj torej ubijte vsakega fanta izmed malčkov in ubijte vsako žensko, ki je spoznala moškega z ležanjem z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Toda vse deklice, ki niso spoznale moškega z ležanjem z njim, zase obdržite žive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Zunaj tabora ostanite sedem dni. Kdorkoli je ubil katerokoli osebo in kdorkoli se je dotaknil kateregakoli umorjenega, na tretji in na sedmi dan očistite oboje, sebe in svoje ujetnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Očistite vso svojo obleko in vse, kar je narejeno iz kož in vse delo iz kozje dlake in vse stvari, narejene iz lesa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Duhovnik Eleazar je rekel bojevnikom, ki so odšli v bitko: »To je odredba postave, ki jo je Gospod zapovedal Mojzesu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'samo zlato, srebro, bron, železo, kositer in svinec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'vsako stvar, ki lahko prenese ogenj, jo boste pripravili iti skozi ogenj in ta bo čista. Kljub temu bo ta očiščena z vodo oddvojitve. Vse, kar pa ne prenese ognja, boste vlekli skozi vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Na sedmi dan boste oprali svoja oblačila in boste čisti in potem se boste vrnili v tabor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '»Ti, duhovnik Eleazar in vodje očetov skupnosti popišite plen, ki je bil zajet, oboje, od ljudi in od živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Plen razdêli na dva dela: med tiste, ki so se vojskovali z njimi, ki so šli ven na bitko in med vso skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Dajatev davka Gospodu od bojevnikov, ki so šli v bitko: ena duša od petstotih, tako od oseb, kakor od goveda, od oslov in od ovc,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'to vzemi od njihove polovice in daj duhovniku Eleazarju za Gospodovo vzdigovalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Od polovice, [ki pripada] Izraelovim otrokom, boš vzel en delež od petdeset, od oseb, od goveda, od oslov in od tropov, od vseh vrst živali in jih daj Lévijevcem, ki skrbijo za Gospodovo šotorsko svetišče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Mojzes in duhovnik Eleazar sta storila, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Plena, ki je ostal od plena, ki so ga bojevniki zajeli, je bilo šeststo petinsedemdeset tisoč ovac,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'dvainsedemdeset tisoč govedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'enainšestdeset tisoč oslov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'dvaintrideset tisoč žensk, ki niso spoznale moškega z ležanjem z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Polovica, ki je bila delež tistih, ki so odšli na vojno, je bila po številu tristo sedemintrideset tisoč petsto ovac');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'in Gospodov davek od ovac je bil šeststo petinsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Goveda je bilo šestintrideset tisoč. Od tega je bil Gospodov davek dvainsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Oslov je bilo trideset tisoč petsto. Od tega je bil Gospodov davek enainšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Oseb je bilo šestnajst tisoč. Od tega je bil Gospodov davek dvaintrideset oseb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Mojzes je dal davek, ki je bil Gospodova vzdigovalna daritev, duhovniku Eleazarju, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Od polovice, [ki pripada] Izraelovim otrokom, ki jo je Mojzes oddvojil od tistih, ki so se bojevali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(torej polovice, ki je pripadala skupnosti, je bilo tristo sedemintrideset tisoč petsto ovac,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'šestintrideset tisoč govedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'trideset tisoč petsto oslov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'in šestnajst tisoč oseb),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'celo od polovice, [ki pripada] Izraelovim otrokom, je Mojzes vzel en delež od petdesetih, tako od ljudi kakor od živali in jih dal Lévijevcem, ki so skrbeli za Gospodovo šotorsko svetišče, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Častniki, ki so bili nad tisočnijami vojske, poveljniki nad tisočimi in poveljniki nad stotimi, so se približali Mojzesu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'in Mojzesu rekli: »Tvoji služabniki so prešteli bojevnike, ki so pod nami in ne manjka nihče izmed nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Mi smo torej prinesli dar za Gospoda, kar je vsak mož dobil dragocenosti iz zlata, verižice, zapestnice, prstane, uhane in ogrlice, da za naše duše opravijo spravo pred Gospodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Mojzes in duhovnik Eleazar sta od njih vzela zlato, torej vse izdelane dragocenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Vsega zlata daritve, ki so jo Gospodu darovali poveljniki nad tisočimi in poveljniki nad stotimi, je bilo šestnajst tisoč sedemsto petdeset šeklov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Kajti bojevniki so vzeli plen, vsak mož zase.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mojzes in duhovnik Eleazar sta vzela zlato od poveljnikov nad tisočimi in poveljnikov nad stotimi in ga prinesla v šotorsko svetišče skupnosti za spomin Izraelovim otrokom pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Torej Rubenovi in Gadovi otroci so imeli veliko množico živine in ko so zagledali deželo Jazêr in deželo Gileád, glej, [ta] kraj je bil kraj za živino,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'so Gadovi otroci in Rubenovi otroci prišli in spregovorili Mojzesu, duhovniku Eleazarju in princem skupnosti, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '»Atarót, Dibón, Jazêr, Nimra, Hešbón, Elalé, Sebma, Nebó in Beón');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'torej dežela, ki jo je Gospod udaril pred Izraelovo skupnostjo, je dežela živine in tvoji služabniki imajo živino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Zatorej so rekli: »Če smo našli milost v tvojem pogledu, naj bo ta dežela dana tvojim služabnikom za posest in ne odvedi nas čez Jordan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mojzes je Gadovim otrokom in Rubenovim otrokom rekel: »Mar bodo vaši bratje šli na vojno, vi pa boste tukaj sedeli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Zakaj odvračate srce Izraelovih otrok od tega, da bi šli čez, v deželo, ki jim jo je dal Gospod?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tako so storili vaši očetje, ko sem jih poslal iz Kadeš Barnée, da pogledajo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kajti ko so odšli gor, v dolino Eškól in videli deželo, so odvrnili srca Izraelovih otrok, da naj ne bi šli v deželo, ki jim jo je dal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Isti čas je bila vžgana Gospodova jeza in prisegel je, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '›Zagotovo ne bo nihče izmed mož, ki so prišli gor iz Egipta, od dvajset let starih in navzgor, videl dežele, ki sem jo prisegel Abrahamu, Izaku in Jakobu, ker mi niso popolnoma sledili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'razen Jefunéjevega sina Kaléba, Kenázovca in Nunovega sina Józueta, kajti onadva sta popolnoma sledila Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Gospodova jeza je bila vžgana zoper Izrael in primoral jih je, da so se štirideset let klatili po divjini, dokler ni bil použit ves rod, ki je počel zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'In glejte, vzdignjeni ste na mesta svojih očetov, zarod grešnikov, da še povečate Gospodovo kruto jezo zoper Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Kajti če se odvrnete od njega, jih bo ponovno pustil v divjini in vi boste uničili vse to ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Približali so se k njemu in rekli: »Tukaj bomo zgradili ovčje staje za svojo živino in mesta za svoje malčke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'toda mi sami bomo pohiteli, da gremo oboroženi pred Izraelovimi otroki, dokler jih ne privedemo na njihov kraj in naši malčki bodo zaradi prebivalcev dežele prebivali v utrjenih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Ne bomo se vrnili v svoje hiše, dokler vsak mož izmed Izraelovih otrok ne podeduje svoje dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Kajti ne bomo je podedovali s tistimi na tamkajšnji strani Jordana ali naprej, ker nam je naša dediščina pripadla na tej strani Jordana proti vzhodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mojzes jim je rekel: »Če boste storili to stvar, če boste šli oboroženi za vojno pred Gospodom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'in boste vsi izmed vas šli oboroženi čez Jordan pred Gospodom, dokler on pred seboj ne prežene svojih sovražnikov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'in bo dežela podvržena pred Gospodom, potem se boste vrnili in boste brez krivde pred Gospodom in pred Izraelom in ta dežela bo vaša posest pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Toda če ne boste tako storili, glejte, ste grešili zoper Gospoda in bodite prepričani, da vas bo vaš greh našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Zgradite vaša mesta za svoje malčke in staje za svoje ovce in storite to, kar je izšlo iz vaših ust.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Gadovi otroci in Rubenovi otroci so spregovorili Mojzesu, rekoč: »Tvoji služabniki bodo storili kakor moj gospod zapoveduje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Naši malčki, naše žene, naši tropi in vsa naša živina bo tam, v mestih Gileáda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'toda tvoji služabniki pojdejo preko, vsak mož oborožen za vojno pred Gospodom, da se bojuje, kakor pravi moj gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Tako je glede njih Mojzes zapovedal duhovniku Eleazarju, Nunovemu sinu Józuetu in vodjem očetov rodov Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Mojzes jim je rekel: »Če bodo Gadovi otroci in Rubenovi otroci z vami šli prek Jordana, vsak mož oborožen za boj, pred Gospodom in bo dežela podjarmljena pred vami, potem jim boste dali za posest deželo Gileád,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'toda če ne bodo z vami prečkali oboroženi, bodo imeli posesti med vami v kánaanski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Gadovi otroci in Rubenovi otroci so odgovorili, rekoč: »Kakor je Gospod rekel svojim služabnikom, tako bomo storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Prešli bomo oboroženi pred Gospodom v kánaansko deželo, da bo posest naše dediščine, na tej strani Jordana, lahko naša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Mojzes jim je dal, torej Gadovim otrokom, Rubenovim otrokom in polovici rodu Jožefovega sina Manáseja, kraljestvo amoréjskega kralja Sihóna in kraljestvo bašánskega kralja Oga, deželo z njenimi mesti v pokrajini, celo mesta dežele naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Gadovi otroci so zgradili Dibón, Atarót, Aroêr,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrót, Šofán, Jaazêr, Jogbóho,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bet Nimro Bet Harám, utrjena mesta in staje za ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubenovi otroci so zgradili Hešbón, Elalé, Kirjatájim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebó, Báal Meón (njihova imena so spremenili) in Sibmo, in dali druga imena mestom, ki so jih zgradili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Otroci Manásejevega sina Mahírja so odšli do Gileáda, ga zavzeli in razlastili Amoréjce, ki so bili v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Mojzes je dal Gileád Manásejevemu sinu Mahírju in ta je tam prebival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Manásejev sin Jaír je odšel in zavzel njihova majhna mesta in jih imenoval Havot Jaír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobah je odšel in zavzel Kenát in njegove vasi ter ga po svojem lastnem imenu imenoval Nobah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'To so potovanja Izraelovih otrok, ki so odšli naprej iz egiptovske dežele, s svojimi vojskami, pod Mojzesovo in Aronovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Mojzes je po Gospodovi zapovedi zapisal njihova odhajanja, glede na njihova potovanja, in to so njihova potovanja glede na njihova odhajanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'V prvem mesecu so se odpravili iz Ramesésa, na petnajsti dan prvega meseca. Naslednji dan po pashi so Izraelovi otroci odšli ven z dvignjeno roko pred očmi vseh Egipčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Kajti Egipčani so pokopali vse svoje prvorojence, ki jih je Gospod udaril med njimi. Tudi nad njihovimi bogovi je Gospod izvršil sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Izraelovi otroci so se odpravili iz Ramesésa in se utaborili v Sukótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Odrinili so iz Sukóta in se utaborili v Etámu, ki je na robu divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Odpravili so se iz Etáma in se ponovno obrnili k Pi Hahirótu, ki je pred Báal Cefónom in se utaborili pred Migdólom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Odrinili so izpred Pi Hahiróta in prešli skozi sredo morja v divjino in odšli na tridnevno potovanje v Etámsko divjino in se utaborili v Mari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Odpravili so se iz Mare in prišli v Elím in v Elímu je bilo dvanajst vodnih studencev in sedemdeset palmovih dreves in tam so se utaborili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Odpravili so se iz Elíma in se utaborili pri Rdečem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Odpravili so se od Rdečega morja in se utaborili v Sinski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Šli so na svoje potovanje iz Sinske divjine in se utaborili v Dofki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Odrinili so iz Dofke in se utaborili v Alúšu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Odpravili so se iz Alúša in se utaborili pri Refidímu, kjer ni bilo vode za ljudstvo, da pije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Odrinili so iz Refidíma in se utaborili v Sinajski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Odpravili so se iz Sinajske puščave in se utaborili pri Kibrot-Hattaavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Odpravili so se iz Kibrot-Hattaave in se utaborili pri Hacerótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Odpravili so se iz Haceróta in se utaborili v Ritmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Odpravili so se iz Ritme in se utaborili pri Rimón Perecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Odpotovali so iz Rimón Pereca in se utaborili v Libni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Odpravili so se iz Libne in se utaborili pri Risi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Odpotovali so iz Rise in se utaborili v Keheláti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Odšli so iz Keheláte in se utaborili na gori Šefer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Odpravili so se z gore Šefer in se utaborili v Harádi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Odpravili so se iz Haráde in se utaborili v Makhelótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Odpravili so se iz Makhelóta in se utaborili pri Tahatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Odpotovali so od Tahata in se utaborili pri Tarahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Odpravili so se od Taraha in se utaborili v Mitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Odšli so iz Mitke in se utaborili v Hašmóni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Odpotovali so iz Hašmóne in se utaborili pri Moserótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Odrinili so iz Moseróta in se utaborili v Bené Jaakánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Odpravili so se iz Bené Jaakána in se utaborili pri Hor Hagidgadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Odšli so iz Hor Hagidgada in se utaborili v Jotbáti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Odpravili so se iz Jotbáte in se utaborili pri Abróni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Odrinili so iz Abróne in se utaborili pri Ecjón Geberju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Odpravili so se iz Ecjón Geberja in se utaborili v Cinski divjini, ki je Kadeš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Odpravili so se iz Kadeša in se utaborili na gori Hor, na robu edómske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Duhovnik Aron je odšel gor na goro Hor, po Gospodovi zapovedi in tam, v štiridesetem letu, potem ko so Izraelovi otroci prišli iz egiptovske dežele, umrl, na prvi dan petega meseca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aron je bil star sto triindvajset let, ko je umrl na gori Hor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Kralj Arád, Kánaanec, ki je prebival na jugu kánaanske dežele, je slišal o prihajanju Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Odpravili so se z gore Hor in se utaborili v Calmóni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Odšli so iz Calmóne in se utaborili v Punónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Odšli so iz Punóna in se utaborili v Obótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Odšli so iz Obóta in se utaborili v Ijé Abarímu, na moábski meji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Odšli so iz Ijíma in se utaborili v Dibón Gadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Odpravili so se iz Dibón Gada in se utaborili v Almón Diblatájemi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Odpravili so se iz Almón Diblatájeme in se utaborili na gorovju Abaríma, pred Nebójem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Odrinili so z gorovja Abarím in se utaborili na moábskih ravninah pri Jordanu, blizu Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Utaborili so se pri Jordanu, od Bet Ješimóta celo do Abél Šitíma, na moábskih ravninah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'In Gospod je spregovoril Mojzesu na moábskih ravninah poleg Jordana, blizu Jerihe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '»Govori Izraelovim otrokom in jim reci: ›Ko prečkate Jordan, v kánaansko deželo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'potem boste izpred sebe napodili vse prebivalce dežele, uničili vse njihove slike, uničili vse njihove ulite podobe, popolnoma uničili vse njihove visoke kraje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'in razlastili boste prebivalce dežele in prebivali v njej, kajti dal sem vam deželo, da jo zavzamete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Deželo boste razdelili z žrebom za dediščino med svojimi družinami in številčnejšemu boste dali več dediščine in maloštevilnemu boste dali manj dediščine. Dediščina vsakogar bo na kraju, kjer pade njegov žreb. Dedovali boste glede na rodove svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Toda če izpred sebe ne boste napodili prebivalcev dežele, potem se bo zgodilo, da bodo tisti, ki jih boste izmed njih pustili, bodice v vaših očeh in trni v vaših bokih in vas bodo dražili v deželi, v kateri prebivate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Poleg tega se bo zgodilo, da vam bom storil, kakor sem mislil storiti njim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '»Zapovej Izraelovim otrokom in jim reci: ›Ko pridete v kánaansko deželo (to je deželo, ki vam bo pripadla v dediščino, torej kánaansko deželo z njenimi pokrajinami),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'potem bo tvoja južna četrt od Cinske divjine, vzdolž edómske pokrajine in vaša južna meja bo skrajna obala slanega morja proti vzhodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'in vaša meja se bo od juga obrnila k vzpetini Akrabím in šla do Cina in šla bo naprej od juga do Kadeš Barnée in šla naprej do Hacár Adárja in šla naprej k Acmónu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'in meja bo šla po ovinkih od Acmóna do egiptovske reke in izhodi te bodo pri morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Glede zahodne meje, za mejo boste torej imeli véliko morje. To bo vaša zahodna meja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'In to bo vaša severna meja: od vélikega morja si jo pokažite na goro Hor,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'od gore Hor boste vašo mejo pokazali do vstopa v Hamát in izhodi meje bodo pri Cedádu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'in meja bo šla naprej k Zifrónu in njeni izhodi bodi pri Hacár Enánu. To bo vaša severna meja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Vašo vzhodno mejo boste pokazali od Hacár Enána do Šefáma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'in pokrajina bo šla dol od Šefáma k Ribli na vzhodni strani Ajina in meja se bo spustila in segla bo do strani Kinéretskega morja proti vzhodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'in meja bo šla dol do Jordana in njeni izhodi bodo pri slanem morju. To bo vaša dežela z njenimi pokrajinami naokoli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Mojzes je Izraelovim otrokom zapovedal, rekoč: »To je dežela, ki jo boste podedovali z žrebom, ki jo je Gospod zapovedal dati devetim rodovom in polovici rodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'kajti rod Rubenovih otrok, glede na hišo njihovih očetov in rod Gadovih otrok, glede na hišo njihovih očetov, sta prejela svojo dediščino in polovica Manásejevega rodu je prejela svojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Dva rodova in pol rodu so že prejeli svojo dediščino na tej strani Jordana, blizu Jerihe, vzhodno proti sončnemu vzhodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '»To sta imeni mož, ki vam bosta razdelila deželo: duhovnik Eleazar in Nunov sin Józue.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Vzeli boste enega princa od vsakega rodu, da deželo razdelite po dediščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Imena mož so ta: iz Judovega rodu Kaléb, Jefunéjev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Iz rodu Simeonovih otrok Amihúdov sin Šemuél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Iz Benjaminovega rodu Kislónov sin Elidád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Princ rodu Danovih otrok, Joglíjev sin Bukí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Princ izmed Jožefovih otrok za rod Manásejevih otrok, Efódov sin Haniél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Princ iz rodu Efrájimovih otrok, Šiftánov sin Kemuél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Princ iz rodu Zábulonovih otrok, Parnáhov sin Elicafán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Princ iz rodu Isahárjevih otrok, Azánov sin Paltiél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Princ iz rodu Aserjevih otrok, Šelomíjev sin Ahihúd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Princ iz rodu Neftálijevih otrok Amihúdov sin Pedahél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'To so tisti, ki jim je Gospod zapovedal, da Izraelovim otrokom razdelijo dediščino v kánaanski deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Gospod je spregovoril Mojzesu na moábskih ravninah, poleg Jordana, blizu Jerihe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '»Zapovej Izraelovim otrokom, da dajo Lévijevcem dediščino njihovih posestnih mest, da prebivajo v njih. Lévijevcem boste dali tudi predmestja za mesta okoli njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Mesta bodo imeli, da prebivajo v njih, njihova predmestja pa bodo za njihovo živino, za njihove dobrine in za vse njihove živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Predmestja mest, ki jih boste dali Lévijevcem, bodo segala od mestnega obzidja navzven, tisoč komolcev naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Izmerili boste mesto od zunaj, na vzhodni strani dva tisoč komolcev, na južni strani dva tisoč komolcev, na zahodni strani dva tisoč komolcev in na severni strani dva tisoč komolcev, in mesto bo v sredi. To jim bodo predmestja mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Med mesti, ki jih boste dali Lévijevcem, bo tam šest mest za zatočišče, ki jih boste določili za ubijalca, da bo lahko pobegnil tja. In tem boste dodali dvainštirideset mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Tako bo vseh mest, ki jih boste dali Lévijevcem, oseminštirideset mest. Te boste dali z njihovimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Mesta, ki jih boste dali, bodo od posesti Izraelovih otrok, od tistih, ki imajo mnogo, boste dali mnogo, toda od tistih, ki imajo malo, boste dali malo. Vsak bo od svojih mest Lévijevcem dal glede na njegovo dediščino, ki jo deduje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Gospod je spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '»Govori Izraelovim otrokom in jim reci: ›Ko boste čez Jordan prešli v kánaansko deželo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'potem si boste določili mesta, da bodo za vas zavetna mesta, da tja lahko pobegne ubijalec, ki nenamerno ubije katerokoli osebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Ta vam bodo mesta za zatočišče pred maščevalcem, da ubijalec ne umre, dokler stoji pred skupnostjo v sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Od teh mest, ki jih boste dali, boste šest mest imeli za zatočišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Dali boste tri mesta na tej strani Jordana in tri mesta v kánaanski deželi, ki bodo zavetna mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Teh šest mest bo zatočišče, tako za Izraelove otroke in za tujca in za začasnega prebivalca med njimi, da vsak, kdor nenamerno ubije katerokoli osebo, lahko pobegne tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Če ga udari z železno pripravo, tako da ta umre, je morilec. Morilec bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Če ga udari z metom kamna, s katerim lahko umre in ta umre, je morilec. Morilec bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Ali če ga udari z ročnim orožjem iz lesa, s katerim ta lahko umre in ta umre, je morilec. Morilec bo zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Sam krvni maščevalec naj ubije morilca. Ko ga sreča, ga bo ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Toda če ga sune iz sovraštva ali se nanj zažene s prežanjem iz zasede, da ta umre,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ali ga v mržnji udari s svojo roko, da ta umre; kdor ga je udaril, bo zagotovo usmrčen, kajti morilec je. Krvni maščevalec naj morilca ubije, ko ga sreča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Toda če ga je nenadoma sunil brez mržnje ali je brez prežanja v zasedi nanj vrgel kakršnokoli stvar');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ali s kakršnimkoli kamnom, s katerim lahko človek umre, pa ga ni videl in ga je vrgel nanj, da umre in ni bil njegov sovražnik niti ni iskal njegove škode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'potem bo glede teh sodb skupnost sodila med ubijalcem in krvnim maščevalcem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'in skupnost bo ubijalca osvobodila iz roke krvnega maščevalca in skupnost ga bo vrnila v mesto njegovega zatočišča, kamor je pobegnil in ta bo ostal v njem do smrti vélikega duhovnika, ki je bil maziljen s svetim oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Toda če bo ubijalec kadarkoli prišel izven meje mesta svojega zatočišča, kamor je pobegnil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'in ga krvni maščevalec najde zunaj meje mesta njegovega zatočišča in krvni maščevalec ubije ubijalca, ne bo kriv krvi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'ker bi do smrti vélikega duhovnika moral ostati v mestu svojega zatočišča. Toda po smrti vélikega duhovnika se bo ubijalec lahko vrnil v deželo svoje posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Torej te stvari vam bodo za zakon sodbe skozi vaše rodove v vseh vaših prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Kdorkoli ubije katerokoli osebo, bo morilec usmrčen po ustih prič. Toda ena priča ne bo pričevala zoper katerokoli osebo, da bi ji povzročila, da ta umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Poleg tega ne boste sprejeli nobene odkupnine za življenje morilca, ki je kriv smrti, temveč bo ta zagotovo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Nobene odkupnine ne boste jemali za tistega, ki je pobegnil k mestu svojega zatočišča, da bi ta lahko ponovno prišel, da prebiva v deželi, do smrti duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Tako ne boste oskrunili dežele, v kateri ste, kajti kri omadežuje deželo in dežela ne more biti očiščena krvi, ki je v njej prelita, razen po krvi tistega, ki jo je prelil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Ne omadežujte torej dežele, ki jo boste poselili, v kateri prebivam, kajti jaz, Gospod, prebivam med Izraelovimi otroki.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Približali so se poglavarji očetov družin Gileádovih otrok, sinú Mahírja, sinú Manáseja, iz družin Jožefovih sinov in spregovorili pred Mojzesom in pred princi, poglavarji očetov Izraelovih otrok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'in rekli: » Gospod je zapovedal mojemu gospodu, naj Izraelovim otrokom da deželo za dediščino po žrebu in mojemu gospodu je bilo zapovedano od Gospoda, naj da dediščino našega brata Celofháda njegovim hčeram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Če bodo poročene h kateremukoli izmed sinov iz drugih rodov Izraelovih otrok, potem bo njihova dediščina vzeta od dediščine naših očetov in predana bo v dediščino rodu, kamor so sprejete. Tako bo to vzeto od žreba naše dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Ko bo jubilej Izraelovih otrok, potem bo njihova dediščina položena v dediščino rodu kamor so sprejete. Tako bo njihova dediščina odvzeta od dediščine rodu naših očetov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Mojzes je Izraelovim otrokom zapovedal glede na Gospodovo besedo, rekoč: »Rod Jožefovih sinov je dobro rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, '›To je stvar, ki jo je Gospod zapovedal glede Celofhádovih hčera, rekoč: ›Naj se poroče, s komer mislijo, da je najbolje, samo k družini rodu njihovega očeta se bodo poročile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Tako dediščina Izraelovih otrok ne bo prešla od roda k rodu, kajti vsak izmed Izraelovih otrok se bo držal k dediščini rodu svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Vsaka hči, ki ima v lasti dediščino v kateremkoli rodu Izraelovih otrok, bo žena enemu iz družine rodu njenega očeta, da bodo Izraelovi otroci lahko uživali vsak človek dediščino svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Niti dediščina ne bo prešla od enega rodu k drugemu rodu, temveč bo vsak izmed rodov Izraelovih otrok sebe držal k svoji lastni dediščini.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Celo kakor je Gospod zapovedal Mojzesu, tako so Celofhádove hčere storile,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'kajti Mahla, Tirca, Hogla, Milka in Noa, Celofhádove hčere, so se poročile k sinovom bratov njihovega očeta');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'in poročene so bile v družine sinov Manáseja, Jožefovega sina in njihova dediščina je ostala v rodu družine njihovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'To so zapovedi in sodbe, ki jih je Gospod po Mojzesovi roki zapovedal Izraelovim otrokom na moábskih ravninah pri Jordanu, blizu Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'To so besede, ki jih je Mojzes govoril vsemu Izraelu na tej strani Jordana, v divjini, na ravnini nasproti Rdečemu morju, med Paránom, Tofelom, Labánom, Hacerótom in Di Zahábom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, '(Tam je enajstdnevno potovanje od Horeba, po poti gorovja Seír do Kadeš Barnée.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'V štiridesetem letu, v enajstem mesecu, na prvi dan meseca, se je pripetilo, da je Mojzes spregovoril Izraelovim otrokom glede vsega, kar mu je Gospod dal njim v zapoved,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'potem, ko je umoril amoréjskega kralja Sihóna, ki je prebival v Hešbónu in bašánskega kralja Oga, ki je prebival pri Aštarótu v Edréiju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'na tej strani Jordana, v moábski deželi, je Mojzes začel oznanjati to postavo, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '» Gospod, naš Bog, nam je spregovoril na Horebu, rekoč: ›Dovolj dolgo ste prebivali na tej gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Obrnite se in pojdite na potovanje in pojdite h gori Amoréjcev in k vsem krajem blizu nje, na ravnini, na hribih, v dolini, na jugu in ob morski obali, k deželi Kánaancev in k Libanonu, k veliki reki, reki Evfrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Glejte, pred vas sem postavil deželo. Vstopite in vzemite v last deželo, ki jo je Gospod prisegel vašim očetom, Abrahamu, Izaku in Jakobu, da jo da njim in njihovemu semenu za njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Ob tistem času sem vam govoril, rekoč: ›Nisem vas zmožen nositi sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Gospod, vaš Bog, vas je pomnožil in glejte, vas je ta dan kakor zvezd neba zaradi množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '(Gospod, Bog vaših očetov, naj vas naredi tisočkrat toliko, kot vas je in vas blagoslovi, kot vam je obljubil!)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kako lahko jaz sam nosim vašo obremenitev, vaše breme in vaš prepir?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Vzemite si modre može, razumne in poznane med svojimi rodovi in jaz jih bom naredil voditelje nad vami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Odgovorili ste mi in rekli: ›Stvar, ki si jo govoril, je za nas dobra, da [jo] storimo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Tako sem vzel vodilne izmed vaših rodov, modre može in poznane in jih naredil poglavarje nad vami, tisočnike, stotnike, petdesetnike, desetnike in častnike med vašimi rodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Ob tistem času sem zadolžil vaše sodnike, rekoč: ›Prisluhnite pravdam med vašimi brati in pravično sodite med vsakim možem, njegovim bratom in tujcem, ki je z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Pri sodbi se ne boste ozirali na osebe; temveč boste prisluhnili tako majhnemu kakor velikemu. Ne boste se bali obličja človeka, kajti razsodba je Božja. Zadevo pa, ki je za vas pretežka, to prinesite k meni in ji bom prisluhnil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Ob tistem času sem vam zapovedal vse stvari, ki naj bi jih storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Ko smo odpotovali od Horeba, smo odšli skozi vso to veliko in strašno divjino, ki ste jo videli po poti gore Amoréjcev, kakor nam je Gospod, naš Bog, zapovedal, in prišli smo do Kadeš Barnée.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Rekel sem vam: ›Prišli ste h gori Amoréjcev, ki nam jo daje Gospod, naš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Glej, Gospod, tvoj Bog je predte postavil deželo. Pojdi gor in si jo vzemi v last, kakor ti je rekel Gospod, Bog tvojih očetov. Ne boj se niti ne izgubi poguma.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Približali ste si mi, vsak izmed vas in rekli: ›Pred nami bomo poslali može in preiskali bodo deželo in nam ponovno prinesli besedo, po kateri poti moramo iti gor in v katera mesta bomo prišli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Govor mi je ugajal, in izmed vas sem vzel dvanajst mož, enega iz rodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'in obrnili so se in odšli gor na goro in prišli v dolino Eškól in jo preiskali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'V svoje roke so vzeli od sadu dežele in to prinesli dol k nam in nam ponovno prinesli besedo ter rekli: › To je dobra dežela, ki nam jo daje Gospod, naš Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Vendar niste hoteli iti gor, temveč [ste se] uprli zoper zapoved Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'V svojih šotorih ste godrnjali in rekli: ›Zato, ker nas je Gospod sovražil, nas je privedel naprej, ven iz egiptovske dežele, da nas izroči v roke Amoréjcev, da nas uničijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kam naj gremo gor? Naši bratje so našemu srcu vzeli pogum, rekoč: ›Ljudstvo je večje in višje, kakor smo mi. Mesta so velika in ograjena do neba, in poleg tega smo tam videli Anákove sinove.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Potem sem vam rekel: ›Ne bodite zaprepadeni niti se jih ne bojte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Gospod, vaš Bog, ki gre pred vami, se bo boril za vas, glede na vse, kar je pred vašimi očmi za vas storil v Egiptu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'in v divjini, kjer si videl, kako te je nosil Gospod, tvoj Bog, kakor mož nosi svojega sina, na vsej poti, kamor ste odšli, dokler niste prišli na ta kraj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Vendar v tej stvari niste verovali Gospodu, svojemu Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'ki je pred vami odšel na pot, da vam poišče prostor, da na njem postavite svoje šotore, v ognju ponoči, da vam pokaže po kateri pot naj bi šli, in v oblaku podnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Gospod je slišal glas vaših besed in bil ogorčen ter prisegel, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '›Zagotovo ne bo nobeden izmed teh mož tega zlega rodu videl te dobre dežele, za katero sem prisegel, da jo dam vašim očetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'razen Jefunéjevega sina Kaléba; on jo bo videl in njemu bom dal deželo, po kateri je stopal in njegovim otrokom, ker je v celoti sledil Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Prav tako je bil Gospod zaradi vas jezen name, rekoč: ›Ti tudi ne boš vstopil vanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Toda Nunov sin Józue, ki stoji pred teboj, on bo vstopil tja. Ohrabri ga, kajti Izraelu bo povzročil, da jo podeduje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Poleg tega bodo vaši malčki, za katere ste rekli, da bi morali biti plen in vaši otroci, ki na ta dan niso imeli spoznanja med dobrim in zlom, oni bodo vstopili tja in njim jo bom dal in oni jo bodo vzeli v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Toda kar se tiče vas, se obrnite in pojdite na potovanje v divjino, po poti Rdečega morja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Potem ste mi odgovorili in rekli: ›Grešili smo zoper Gospoda, šli bomo gor in se borili, glede na vse, kar nam je zapovedal Gospod, naš Bog.‹ In ko ste si opasali vsak mož svoje bojno orožje, ste bili pripravljeni, da greste gor na hrib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Gospod mi je rekel: ›Reci jim: ›Ne pojdite gor niti se ne bojujte, kajti jaz nisem med vami, da ne bi bili udarjeni pred svojimi sovražniki.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Tako sem vam govoril, pa niste hoteli slišati, temveč [ste se] uprli zoper Gospodovo zapoved in prepotentno odšli na hrib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Amoréjci, ki prebivajo na tej gori, so prišli ven zoper vas in vas preganjali, kakor počnejo čebele in vas uničili v Seírju, celó do Horme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Vrnili ste se in jokali pred Gospodom, toda Gospod ni hotel prisluhniti vašemu glasu niti nagniti ušesa k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Tako ste mnogo dni ostali v Kadešu, glede na dneve, ko ste ostajali tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Potem smo se obrnili in šli na svoje potovanje v divjino, ob poti Rdečega morja, kakor mi je Gospod govoril in mnogo dni smo obkrožali gorovje Seír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'In Gospod mi je spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '›Dovolj dolgo ste obkrožali to goro, obrnite se proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Zapovej ljudstvu, rekoč: ›Šli boste skozi pokrajino svojih bratov, Ezavovih otrok, ki prebivajo v Seírju in oni se vas bodo bali, zato dobro pazite nase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Ne vmešavajte se vanje, kajti ne bom vam dal od njihove dežele, ne, niti za širino stopala ne, ker sem gorovje Seír izročil Ezavu za posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Od njih boste hrano kupovali za denar, da boste lahko jedli in od njih boste tudi vodo kupovali za denar, da boste lahko pili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Kajti Gospod, tvoj Bog, te je blagoslovil pri vseh delih tvoje roke. Pozna tvojo hojo skozi to veliko divjino. Teh štirideset let je bil Gospod, tvoj Bog, s teboj; nikakršnega pomanjkanja nisi trpel.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Ko smo šli mimo svojih bratov, Ezavovih otrok, ki so prebivali v Seírju, skozi pot ravnine od Eláta in od Ecjón Geberja, smo se obrnili in prešli po poti moábske divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Gospod mi je rekel: ›Moábcev ne spravi v tegobo niti se z njimi ne spoprimi v boju, kajti njihove dežele ti ne bom dal v last, ker sem Ar dal Lotovim otrokom za posest.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Emejci so v njej prebivali v preteklih časih, veliko, številno in visoko ljudstvo, kakor Anákovci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'ki so bili tudi prišteti med velikane, kakor Anákovci, toda Moábci so jih imenovali Emejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Tudi Horéjci so poprej prebivali v Seírju, toda Ezavovi otroci so jih pregnali, ko so jih uničili pred seboj in prebivali namesto njih, kakor je Izrael storil v deželi njihove posesti, ki jim jo je dal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '›Sedaj se vzdignite,‹ sem rekel ›in se odpravite čez potok Zered.‹ In šli smo preko potoka Zered.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Časa, v katerem smo prišli iz Kadeš Barnée, dokler nismo prešli preko potoka Zered, je bilo osemintrideset let, dokler ni pomrl ves rod bojevnikov izmed vojske, kakor jim je prisegel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Kajti zares je bila Gospodova roka zoper njih, da jih uniči izmed vojske, dokler niso bili použiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Tako se je pripetilo, ko so bili vsi bojevniki izmed ljudstva použiti in mrtvi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'da mi je Gospod spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '›Danes boš prešel skozi Ar, moábsko pokrajino');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'in ko prideš blizu, nasproti Amónovih otrok, jih ne spravi v tegobo niti se ne vmešavaj vanje, kajti od dežele Amónovih otrok ti ne bom dal nobene posesti, ker sem jo dal Lotovim otrokom za posest.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Tudi ta je bila šteta [za] deželo velikanov. Tam so v starih časih prebivali velikani. Amónci so jih imenovali Zamzuméjce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'veliko, številno in visoko ljudstvo, kakor Anákovci. Toda Gospod jih je uničil pred njimi in oni so jih nasledili in prebivali namesto njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'kakor je storil Ezavovim otrokom, ki so prebivali v Seírju, ko je pred njimi uničil Horéjce. Le-ti so jih nasledili in celo do tega dne prebivali namesto njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, '§ Avéjce, ki so prebivali v Haserimu, celó do Gaze, so Kaftorejci, ki so izšli iz Kaftorja, uničili in prebivali namesto njih.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '›Dvignite se, pojdite na potovanje in prečkajte reko Arnón. Glej, v tvojo roko sem izročil Amoréjca Sihóna, kralja v Hešbónu in njegovo deželo. Začnite jo jemati v last in se z njim spoprimite v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Danes bom začel pred teboj spuščati grozo in strah nad narode, ki so pod celotnim nebom, ki bodo slišali poročilo o tebi in bodo trepetali in bodo zaradi tebe v tesnobi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'In odposlal sem poslance iz divjine Kedemót k Sihónu, kralju v Hešbónu, z besedami miru, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '›Naj grem skozi tvojo deželo. Šel bom vzdolž visoke poti, ne bom se obrnil niti k desni roki niti k levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Hrano mi boš prodajal za denar, da bom lahko jedel in vodo mi [boš] dajal za denar, da bom lahko pil, samo na svojih stopalih bom šel skozi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, '(kakor so mi storili Ezavovi otroci, ki prebivajo v Seírju in Moábci, ki prebivajo v Aru), dokler ne bom šel čez Jordan v deželo, ki nam jo daje Gospod, naš Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Toda Sihón, kralj v Hešbónu, nam ni dovolil iti mimo njega, kajti Gospod, tvoj Bog, je zakrknil njegovega duha in njegovo srce naredil trdovratno, da bi ga lahko izročil v tvojo roko, kakor se kaže ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Gospod mi je rekel: ›Glej, pred teboj sem ti začel dajati Sihóna in njegovo deželo. Začni jo jemati v last, da boš lahko podedoval njegovo deželo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Potem je zoper nas prišel ven Sihón, on in njegovo ljudstvo, da se borijo pri Jahacu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Gospod, naš Bog, ga je pred nami izročil in udarili smo njega, njegove sinove in vse njegovo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Ob tistem času smo zavzeli vsa njegova mesta in popolnoma uničili moške, ženske in malčke iz vsakega mesta. Nobenega nismo pustili ostati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Samo živino smo si vzeli za plen in ukradeno blago mest, ki smo jih zavzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroêrja, ki je pri bregu reke Arnón in od mesta, ki je pri reki, celo do Gileáda, tam ni bilo niti enega mesta premočnega za nas. Gospod, naš Bog, jih je vsa izročil nam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Samo v deželo Amónovih otrok nisi prišel niti v noben kraj reke Jabók niti v gorska mesta niti v katerakoli, ki nam jih je Gospod, naš Bog, prepovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Potem smo se obrnili in odšli gor po poti do Bašána in bašánski kralj Og je prišel zoper nas, on in vse njegovo ljudstvo, da se bojuje pri Edréi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Gospod mi je rekel: ›Ne boj se ga, kajti jaz bom izročil njega, vse njegovo ljudstvo in njegovo deželo, v tvojo roko in ti mu boš storil, kakor si storil Sihónu, kralju Amoréjcev, ki je prebival pri Hešbónu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Tako je Gospod, naš Bog, v naše roke izročil tudi bašánskega kralja Oga in vse njegovo ljudstvo in udarjali smo ga, dokler mu nihče ni preostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Ob tistem času smo zavzeli vsa njegova mesta. Tam ni bilo mesta, ki ga ne bi vzeli od njih, šestdeset mest, celotno področje Argoba, Ogovo kraljestvo v Bašánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Vsa ta mesta so bila ograjena z visokimi zidovi, velikimi vrati in zapahi, poleg zelo veliko neobzidanih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Popolnoma smo jih uničili, kakor smo storili hešbónskemu kralju Sihónu. Popolnoma smo uničili moške, ženske in otroke vsakega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Toda vso živino in ukradeno blago mest smo si vzeli za plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Ob tistem času smo iz roke dveh kraljev Amoréjcev vzeli deželo, ki je bila na tej strani Jordana, od reke Arnón do gore Hermon');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Hermon, katero Sidónci imenujejo Sirjón, Amoréjci pa jo imenujejo Senír))');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'vsa mesta ravnine, ves Gileád in ves Bašán, do Salhe in Edréi, mesta Ogovega kraljestva v Bašánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Kajti samo bašánski kralj Og je preostal od preostanka velikanov. Glej, ogrodje njegove postelje je bilo posteljno ogrodje iz železa. Mar ni ta v Rabi Amónovih sinov? Devet komolcev je bila njena dolžina in štiri komolce njena širina, po moškem komolcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'To deželo, ki smo jo ob tistem času vzeli v last od Aroêrja, ki je ob reki Arnón in polovico gore Gileád in njena mesta, sem dal Rubenovcem in Gádovcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Preostanek Gileáda in ves Bašán, ki je Ogovo kraljestvo, sem dal polovici Manásejevega rodu in vse področje Argoba, z vsem Bašánom, ki je bil imenovan dežela velikanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaír, sin Manáseja, je zavzel vso Argobovo deželo do pokrajin Gešurja in Maahčánov, in imenoval jih je po svojem imenu Bašán Havot Jaír do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'In jaz sem Gileád izročil Mahírju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Rubenovcem in Gádovcem sem dal od Gileáda celo do reke Arnón, polovico doline in mejo celo do reke Jabók, ki je meja Amónovih otrok;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'tudi ravnino in Jordan in njegovo pokrajino od Kinéreta, celó do morja ravnine, celo slanega morja, vzhodno pod Ašdód-Pisgo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Ob tem času sem vam zapovedal, rekoč: › Gospod, vaš Bog, vam je to deželo dal v last. Čeznjo boste prešli oboroženi pred svojimi brati, Izraelovimi otroki, vsemi, ki so primerni za vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Toda vaše žene, vaši malčki in vaša živina (kajti vem, da imate mnogo živine), bodo ostali v vaših mestih, ki sem vam jih dal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'dokler Gospod ne da počitka vašim bratom, prav tako kakor vam in dokler tudi oni ne vzamejo v last dežele, ki jim jo je Gospod, vaš Bog, dal onkraj Jordana. In potem se boste vrnili, vsak mož k svoji posesti, ki sem vam jo dal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Ob tistem času sem Józuetu zapovedal, rekoč: ›Tvoje oči so videle vse, kar je Gospod, tvoj Bog, storil tema dvema kraljema. Tako bo Gospod storil vsem kraljestvom, ki jih vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne boste se jih bali, kajti za vas se bo boril Gospod, vaš Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Ob tistem času sem prosil Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '›Oh Gospod Bog, svojim služabnikom si začel kazati svojo veličino in svojo mogočno roko, kajti kakšen Bog je tam v nebesih ali na zemlji, ki lahko stori glede na tvoja dela in glede na tvojo moč?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Prosim te, naj grem preko in vidim dobro deželo, ki je onkraj Jordana, to dobro goro in Libanon.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Toda Gospod je bil zaradi vas ogorčen name in me ni hotel uslišati. Gospod mi je rekel: ›Naj ti to zadošča. Ne govori mi več o tej zadevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Povzpni se na vrh Pisge in povzdigni svoje oči proti proti zahodu, proti severu, proti jugu in proti vzhodu in glej to s svojimi očmi, kajti ne boš šel preko tega Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Toda zadolži Józueta, ga ohrabri in okrépi, kajti on bo pred tem ljudstvom šel preko in povzročil jim bo, da podedujejo deželo, ki jo boš videl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Tako smo ostali v dolini nasproti Bet Peórja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Zdaj torej prisluhni, oh Izrael, zakonom in sodbam, ki vas jih učim, da jih izpolnjujete, da boste lahko živeli, vstopili in vzeli v last deželo, ki vam jo daje Gospod, Bog vaših očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ne boste dodajali besedi, ki sem vam jo zapovedal niti ne boste zmanjševali česa od nje, da bi lahko ohranjali zapovedi Gospoda, svojega Boga, ki sem vam jih zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vaše oči so videle kaj je Gospod storil zaradi Báal Peórja. Zaradi vseh mož, ki so sledili Báal Peórju, jih je Gospod, tvoj Bog, uničil izmed vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Toda vi, ki ste se trdno držali Gospoda, svojega Boga, ste danes živi, vsakdo izmed vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Glejte, učil sem vas zakonov in sodb, celo kakor mi je Gospod, moj Bog, zapovedal, da naj bi storili v deželi, kamor greste, da jo vzamete v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Torej jih ohranjajte in izpolnjujte, kajti to je vaša modrost in vaše razumevanje v očeh narodov, ki bodo slišali vse te zakone in rekli: ›Zagotovo je ta véliki narod modro in razumevajoče ljudstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Kajti kateri narod je tam tako velik, ki ima Boga tako blizu, kakor je Gospod, naš Bog, v vseh stvareh, za katere kličemo k njemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'In kateri narod je tam tako velik, ki ima zakone in sodbe tako pravične, kot je vsa ta postava, ki jo danes postavljam pred vas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Samo pazi nase in marljivo varuj svojo dušo, da ne pozabiš stvari, ki so jih videle tvoje oči in da vse dni tvojega življenja ne odidejo od tvojega srca, temveč poučuj svoje sinove in svojih sinov sinove,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'posebej [o] dnevu, ko si stal pred Gospodom, svojim Bogom, na Horebu, ko mi je Gospod rekel: ›Zberi mi skupaj ljudstvo in pripravil jih bom slišati moje besede, da se me bodo lahko naučili bati vse dni, ki jih bodo živeli na zemlji in da bodo lahko učili svoje otroke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'In približali ste se ter stali pod goro in gora je gorela z ognjem do srede neba, s temo, oblaki in gosto temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Gospod vam je spregovoril iz srede ognja. Slišali ste glas besed, toda nobene podobnosti niste videli, samo glas ste slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Naznanil vam je svojo zavezo, ki vam jo je zapovedal, da jo opravljate, torej deset zapovedi, in napisal jih je na dve kamniti plošči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Gospod mi je ob tistem času zapovedal, da vas učim zakone in sodbe, da jih boste lahko izpolnjevali v deželi, kamor greste, da jo vzamete v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Zato torej dobro pazite nase, kajti nobene vrste podobnosti niste videli na dan, ko vam je Gospod govoril na Horebu iz srede ognja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'da se ne bi izpridili in si naredili rezane podobe, podobnost kakršnekoli postave, podobnost moškega ali ženske,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'podobnost katerekoli živali, ki je na zemlji, podobnost katerekoli krilate perjadi, ki leti po zraku,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'podobnost katerekoli stvari, ki se plazi po tleh, podobnost katerekoli ribe, ki je v vodah pod zemljo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'in da ne bi povzdignil svojih oči k nebu in ko zagledaš sonce, luno in zvezde, celó vso vojsko neba, da ne bi bil zapeljan, da jih obožuješ in jim služiš, ki jih je Gospod, tvoj Bog, razdelil vsem narodom pod celotnim nebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Toda Gospod vas je vzel in vas privedel naprej iz železne talilne peči, torej iz Egipta, da mu boste ljudstvo dediščine, kakor ste ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Nadalje je bil zaradi vas Gospod jezen nad menoj in prisegel, da naj ne bi šel preko Jordana in da naj ne bi vstopil v to dobro deželo, ki ti jo Gospod, tvoj Bog, daje v dediščino,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'temveč moram umreti v tej deželi, ne smem iti čez Jordan. Toda vi boste šli čez in tisto dobro deželo vzeli v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Pazite nase, da ne bi pozabili zaveze Gospoda, svojega Boga, ki jo je sklenil z vami in si naredili rezane podobe ali podobnost katerekoli stvari, ki ti jo je Gospod, tvoj Bog, prepovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Kajti Gospod, tvoj Bog, je požirajoč ogenj, celó ljubosumen Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Ko boš zaplodil otroke in otrok otroke in boste dolgo ostali v deželi in se boste izpridili in naredili rezano podobo ali podobnost katerikoli stvari in boste počeli zlo v očeh Gospoda, svojega Boga, da ga dražite k jezi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'pokličem nebo in zemljo, da ta dan pričujeta zoper vas, da boste kmalu popolnoma izginili iz dežele, v katero ste šli prek Jordana, da jo vzamete v last. Ne boste podaljšali svojih dni na njej, temveč boste popolnoma uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Gospod vas bo razkropil med narode in malo vas bo ostalo po številu med pogani, kamor vas bo vodil Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Tam boste služili bogovom, delu človeških rok, lesu in kamnu, ki niti ne vidita niti ne slišita, ne jesta niti ne vonjata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Toda če boš od tam iskal Gospoda, svojega Boga, ga boš našel, če ga iščeš z vsem svojim srcem in z vso svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Ko si v stiski in vse te stvari pridejo nadte, torej v zadnjih dneh, če se obrneš h Gospodu, svojemu Bogu in boš poslušen njegovemu glasu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '(kajti Gospod, tvoj Bog, je usmiljen Bog) te ne bo zapustil niti uničil niti pozabil zaveze tvojih očetov, ki jim jo je prisegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Kajti vprašaj sedaj o dneh, ki so minili, ki so bili pred teboj, od dneva, ko je Bog na zemlji ustvaril moža in vprašaj od ene strani neba do druge, ali je bila tam kakršna koli takšna stvar, kot je ta velika stvar, ali je bila slišati podobno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Mar je kdajkoli ljudstvo slišalo glas Boga govoriti iz srede ognja, kakor si slišal ti, in je živelo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Mar je Bog poskušal iti in si vzeti narod iz srede drugega naroda, s preizkušnjami, znamenji, čudeži, vojno, mogočno roko, z iztegnjenim laktom in z velikimi strahotami, glede na vse, kar je Gospod, vaš Bog, storil za vas v Egiptu, pred vašimi očmi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tebi je bilo pokazano, da bi lahko vedel, da Gospod, on je Bog. Tam ni nobenega drugega poleg njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Iz nebes ti je dal, da slišiš njegov glas, da bi te lahko poučil, in na zemlji ti je pokazal svoj velik ogenj in ti slišiš njegove besede iz srede ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Ker je vzljubil tvoje očete, zato je izbral tvoje seme za njimi in te privedel ven v njegovem pogledu, s svojo mogočno močjo iz Egipta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'da izpred tebe napodi narode, večje in mogočnejše kakor si ti, da te privede noter, da ti da njihovo deželo v dediščino, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Vedi torej danes in preudari to v svojem srcu, da Gospod, on je Bog, v nebesih zgoraj in na zemlji spodaj. Tam ni nobenega drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Ohranjal boš torej njegove zakone in njegove zapovedi, ki ti jih danes zapovedujem, da bo lahko šlo dobro s teboj in s tvojimi otroki za teboj in da lahko podaljšaš svoje dneve na zemlji, ki ti jo daje Gospod, tvoj Bog, na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Potem je Mojzes oddvojil tri mesta na tej strani Jordana proti sončnemu vzhodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'da bi ubijalec, ki bi nenamerno ubil svojega bližnjega in ga v preteklih časih ni sovražil, lahko pobegnil tja in da bežeč v eno izmed teh mest lahko ostane živ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Namreč Becer v divjini, na ravnini dežele Rubenovcev in Ramót v Gileádu od Gádovcev in Golán v Bašánu od Manásejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'To je postava, ki jo je Mojzes postavil pred Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'To so pričevanja, zakoni in sodbe, ki jih je Mojzes govoril Izraelovim otrokom, po tem, ko so izšli iz Egipta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'na tej strani Jordana, v dolini nasproti Bet Peórja, v deželi amoréjskega kralja Sihóna, ki je prebival v Hešbónu, ki so ga Mojzes in Izraelovi otroci udarili, potem ko so izšli iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Vzeli so v last njegovo deželo in deželo bašánskega kralja Oga, dveh kraljev Amoréjcev, ki sta bila na tej strani Jordana, proti sončnemu vzhodu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'od Aroêrja, ki je ob bregu reke Arnón, celo do gore Sion, ki je Hermon');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'in vso ravnino na tej strani Jordana proti vzhodu, celo do morja ravnine, pod izviri Pisge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Mojzes je sklical ves Izrael in jim rekel: »Poslušaj, oh Izrael, zakone in sodbe, ki jih ta dan govorim v vaša ušesa, da se jih lahko naučite in jih ohranjate in jih izvršujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Gospod, naš Bog, je z nami sklenil zavezo na Horebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Gospod te zaveze ni sklenil z našimi očeti, temveč z nami, torej nami, ki smo, vsi izmed nas, ta dan tukaj živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Gospod je s teboj govoril iz obličja v obličje, na gori, iz srede ognja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(ob tistem času sem stal med Gospodom in vami, da bi vam pokazal Gospodovo besedo, kajti vi ste se zaradi ognja bali in niste šli gor na goro), rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '[1] ›Jaz sem Gospod, tvoj Bog, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, '[2] Pred menoj ne boš imel nobenih drugih bogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Sebi ne boš naredil nobene rezane podobe ali kakršnekoli podobnosti katerekoli stvari, ki je v nebesih zgoraj ali ki je na zemlji spodaj ali ki je v vodah pod zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Ne boš se jim priklanjal niti jim služil, kajti jaz, Gospod, tvoj Bog, sem ljubosumen Bog, ki obiskujem krivičnost očetov na otrocih do tretjega in četrtega rodu teh, ki me sovražijo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'in izkazujem usmiljenje tisočim tistih, ki me ljubijo in varujejo moje zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, '[3] Ne boš v prazno vzel imena Gospoda, svojega Boga, kajti Gospod ne bo brez krivde držal tistega, ki v prazno jemlje njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, '[4] Varuj šabatni dan, da ga posvečuješ, kakor ti je zapovedal Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Šest dni se boš trudil in opravljal vse svoje delo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'toda sedmi dan je šabat Gospodu, tvojemu Bogu. Na [ta dan] ne boš opravljal nobenega dela, ne ti, niti tvoj sin, niti tvoja hči, niti tvoj sluga, niti tvoja dekla, niti tvoj vol, niti tvoj osel, niti nobena izmed tvoje živine, niti tvoj tujec, ki je znotraj tvojih velikih vrat, da lahko tvoj sluga in tvoja dekla počivata kakor ti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Spominjaj pa se, da si bil služabnik v egiptovski deželi in da te je Gospod, tvoj Bog, od tam privedel z mogočno roko in z iztegnjenim laktom. Zato ti je Gospod, tvoj Bog, zapovedal, da izvajaš šabatni dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, '[5] Spoštuj svojega očeta in svojo mater, kakor ti je zapovedal Gospod, tvoj Bog, da bodo tvoji dnevi lahko podaljšani in da ti bo dobro šlo v deželi, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, '[6] Ne boš ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, '[7] Niti ne boš zagrešil zakonolomstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, '[8] Niti ne boš kradel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, '[9] Niti ne boš pričal po krivem zoper svojega bližnjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, '[10] Niti si ne boš želel žene svojega bližnjega, niti ne boš hlepel [po] hiši svojega bližnjega, [po] njegovem polju ali [po] njegovem slugi ali [po] njegovi dekli, [po] njegovem volu ali [po] njegovem oslu ali [po] katerikoli stvari, ki je [od] tvojega bližnjega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Te besede je Gospod govoril vsemu zboru na gori, iz srede ognja, iz oblaka in iz goste teme, z močnim glasom. In ni več dodal. Napisal jih je na dve kamniti plošči in mi ju izročil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Pripetilo se je, ko ste iz srede teme zaslišali glas (kajti gora je gorela z ognjem), da ste se mi približali, celó vsi poglavarji vaših rodov in vaše starešine');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'in ste rekli: ›Glej, Gospod, naš Bog, nam je pokazal svojo slavo in svojo veličino in iz srede ognja smo slišali njegov glas. Ta dan smo videli, da Bog govori z možem in ta živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Zdaj torej zakaj naj bi umrli? Kajti ta velik ogenj nas bo použil. Če še naprej slišimo glas Gospoda, našega Boga, potem bomo umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Kajti kdo je tam od vsega mesa, ki je iz srede ognja slišal govoriti glas živega Boga, kakor smo mi in je živel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Ti pojdi blizu in prisluhni vsemu, kar bo rekel Gospod, naš Bog in spregovori nam vse, kar ti bo govoril Gospod, naš Bog in mi bomo temu prisluhnili in to storili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Gospod je slišal glas vaših besed, ko ste mi govorili in Gospod mi je rekel: ›Slišal sem glas besed tega ljudstva, ki so ti jih govorili. Dobro so povedali vse, kar so govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Oh, da bi bilo takšno srce v njih, da bi se me bali in se vedno držali vseh mojih zapovedi, da bi bilo lahko dobro z njimi in z njihovimi otroki na veke!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Pojdi, reci jim: ›Ponovno se vrnite v svoje šotore.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Toda kar se tebe tiče, ti ostani tukaj, poleg mene in govoril ti bom vse zapovedi, zakone in sodbe, ki jih boš učil, da jih bodo lahko izpolnjevali v deželi, ki sem jim jo dal, da jo vzamejo v last.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Obeleževali boste torej, da delate, kakor vam je zapovedal Gospod, vaš Bog. Ne boste se odvrnili vstran, ne k desni roki ne k levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Hodili boste po vseh poteh, ki vam jih je zapovedal Gospod, vaš Bog, da boste lahko živeli in da bo lahko dobro z vami in da boste lahko podaljšali svoje dni v deželi, ki jo boste vzeli v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Torej to so zapovedi, zakoni in sodbe, ki jih je Gospod, vaš Bog, zapovedal, da vas učim, da jih boste lahko izpolnjevali v deželi, kamor greste, da jo vzamete v last,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'da se boš lahko bal Gospoda, svojega Boga, da boš ohranjal vse njegove zakone in njegove zapovedi, ki sem ti jih zapovedal: ti, tvoj sin in sin tvojega sina, vse dni tvojega življenja in da bodo tvoji dnevi lahko podaljšani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Poslušaj torej, oh Izrael in obeležuj, da to storiš, da bo lahko dobro s teboj in da boš lahko mogočno povečan, kakor ti je obljubil Gospod, Bog tvojih očetov, v deželi, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Poslušaj, oh Izrael: › Gospod, naš Bog, je edini Gospod');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'in ljubil boš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo in z vso svojo močjo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'In te besede, ki sem ti jih danes zapovedal, bodo v tvojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'In ti jih boš marljivo učil svoje otroke in boš govoril o njih, ko sediš v svoji hiši, ko hodiš po poti, ko se uležeš in ko vstajaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Privezal si jih boš za znamenje na roko in te bodo kot načelek med tvojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Napisal jih boš na podboje svoje hiše in na svoja velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'In zgodilo se bo, ko te bo Gospod, tvoj Bog, privedel v deželo, ki jo je prisegel tvojim očetom, Abrahamu, Izaku in Jakobu, da ti da velika in čedna mesta, ki jih nisi zgradil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'in hiše, polne vseh dobrih stvari, ki jih nisi napolnil in izkopane vodnjake, ki jih nisi izkopal, vinograde in oljke, ki jih nisi zasadil; ko jih boš jedel in boš sit,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'potem se pazi, da ne pozabiš Gospoda, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Bal se boš Gospoda, svojega Boga in mu služil in prisegal pri njegovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne boste šli za drugimi bogovi, bogovi ljudstev, ki so naokoli vas');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(kajti Gospod, tvoj Bog, je med vami ljubosumen Bog), da ne bi bila zoper tebe vžgana jeza Gospoda, tvojega Boga in te uniči iz obličja zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ne boste skušali Gospoda, svojega Boga, kakor ste ga skušali v Masi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Marljivo boste varovali zapovedi Gospoda, svojega Boga, njegova pričevanja in njegove zakone, ki ti jih je zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Storil boš to, kar je prav in dobro v Gospodovih očeh, da bo lahko dobro s teboj in da lahko vstopiš in vzameš v last dobro deželo, ki jo je Gospod prisegel tvojim očetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'da pred teboj prežene vse tvoje sovražnike, kakor je govoril Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'In ko te tvoj sin sprašuje v času, ki pride, rekoč: ›Kaj pomenijo pričevanja, zakoni in sodbe, ki vam jih je zapovedal Gospod, naš Bog?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Potem boš svojemu sinu rekel: ›V Egiptu smo bili faraonovi sužnji in Gospod nas je z mogočno roko privedel iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Gospod je pred našimi očmi nad Egiptom, nad faraonom in nad vso njegovo hišo pokazal znamenja in čudeže, velika in boleča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'in nas odvedel od tam, da bi nas lahko privedel noter, da nam da deželo, ki jo je prisegel našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Gospod nam je zapovedal, da izvršujemo vse te zakone, da se vedno bojimo Gospoda, svojega Boga, za naše dobro, da nas lahko ohrani žive, kakor je to na ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'In to bo naša pravičnost, če obeležujemo vse te zapovedi pred Gospodom, svojim Bogom, kakor nam je zapovedal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Ko te bo Gospod, tvoj Bog, privedel v deželo, kamor greš, da jo vzameš v last in je pred teboj pregnal mnoge narode: Hetejce, Girgašéjce, Amoréjce, Kánaance, Perizéjce, Hivéjce in Jebusejce, sedem narodov, večje in mogočnejše kakor ti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'in ko jih bo Gospod, tvoj Bog, izročil pred teboj, jih boš udaril in popolnoma uničil. Nobene zaveze ne boš sklenil z njimi niti jim ne izkaži usmiljenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'niti z njimi ne boš sklepal porok. Svoje hčere ne boš dal njegovemu sinu niti njegove hčere ne boš vzel k svojemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Kajti tvojega sina bodo odvrnile od sledenja meni, da bi lahko služile drugim bogovom. Tako bo zoper tebe vžgana Gospodova jeza in te nenadoma uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Temveč boste tako postopali z njimi: uničili boste njihove oltarje in razbili njihove podobe in posekali njihove ašere in njihove rezane podobe sežgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Kajti ti si sveto ljudstvo Gospodu, svojemu Bogu. Gospod, tvoj Bog, te je izbral, da mu boš posebno ljudstvo, nad vsemi ljudstvi, ki so na obličju zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Gospod svoje ljubezni ni naravnal na vas niti vas ni izbral, ker ste bili številnejši kot katerokoli ljudstvo, kajti bilo vas je najmanj izmed vseh ljudstev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'temveč, ker vas je Gospod ljubil in ker je želel držati prisego, ki jo je prisegel vašim očetom, vas je Gospod izpeljal z mogočno roko in vas odkupil iz hiše sužnosti, iz roke faraona, egiptovskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Vedi torej, da Gospod, tvoj Bog, on je Bog, zvesti Bog, ki ohranja zavezo in usmiljenje s tistimi, ki ga ljubijo in ohranjajo njegove zapovedi tisočim rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Tistim pa, ki ga sovražijo, poplača k njihovemu obrazu, da jih uniči. Ne bo počasen do tistega, ki ga sovraži; poplačal mu bo v obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Torej boš varoval zapovedi, zakone in sodbe, ki sem ti jih ta dan zapovedal, da jih izvršuješ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Kjerkoli se bo to pripetilo, če prisluhnete tem sodbam in jih varujete in jih izpolnjujete, da ti bo Gospod, tvoj Bog, varoval zavezo in usmiljenje, ki ga je prisegel tvojim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Ljubil te bo, te blagoslavljal in te namnožil. Blagoslavljal bo tudi sad tvoje maternice in sad tvoje dežele, tvoje žito, tvoje vino in tvoje olje, narast tvojega goveda in trope tvojih ovc, v deželi, ki jo je prisegel tvojim očetom, da ti jo da.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Blagoslovljen boš nad vsemi ljudstvi. Med vami ne bo jalovega moškega ali ženske ali med vašo živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Gospod bo od tebe odvrnil vso bolezen in nobene izmed teh zlih egiptovskih bolezni, ki jih poznaš, ne bo položil nadte, temveč jih bo položil na vse tiste, ki te sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Použil boš vsa ljudstva, ki ti jih bo izročil Gospod, tvoj Bog. Tvoje oko nad njimi ne bo imelo nobenega usmiljenja. Niti ne boš služil njihovim bogovom, kajti to ti bo zanka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Če boš v svojem srcu rekel: ›Ti narodi so številnejši kakor jaz; kako jih lahko razlastim?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Ne boš se jih bal, temveč se boš dobro spomnil, kaj je Gospod, tvoj Bog, storil faraonu in vsemu Egiptu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'velike preizkušnje, ki so jih videle tvoje oči, znamenja, čudeže, mogočno roko in iztegnjen laket, s čimer te je izpeljal Gospod, tvoj Bog. Tako bo Gospod, tvoj Bog, storil vsem ljudstvom, ki se jih bojiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Poleg tega bo Gospod, tvoj Bog, mednje poslal sršene, dokler ne bodo tisti, ki so preostali in se skrivajo pred teboj, uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Pred njimi ne boš zgrožen, kajti Gospod, tvoj Bog, je med vami mogočen in strašen Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'In Gospod, tvoj Bog, bo te narode po malo in malo odstranil pred teboj. Ne boš jih mogel naenkrat použiti, da ne bi poljske zveri narasle nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, '§ Toda Gospod, tvoj Bog, jih bo izročil tebi in uničeval jih boš z mogočnim uničenjem, dokler ne bodo uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Njihove kralje bo izročil v tvojo roko in njihovo ime boš uničil izpod neba. Noben človek ne bo zmožen obstati pred teboj, dokler jih ne uničiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Rezane podobe njihovih bogov boste sežgali z ognjem. Ne boš hlepel po srebru ali zlatu, ki je na njih niti si ga ne vzemi k sebi, da ne bi bil v tem ujet, kajti to je ogabnost Gospodu, tvojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Niti v svojo hišo ne prinašaj gnusobe, da ne bi bil preklet, kakor je ona, temveč naj se ti skrajno gnusi in skrajno jo zaničuj, kajti to je prekleta stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Vse zapovedi, ki sem ti jih ta dan zapovedal, boste obeleževali, da jih izvršujete, da boste lahko živeli, se množili in vstopili in vzeli v last deželo, ki jo je Gospod prisegel vašim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Spomnil se boš celotne poti, po kateri te je Gospod, tvoj Bog, teh štirideset let vodil po divjini, da te poniža in te preizkusi, da spozna kaj je bilo v tvojem srcu, bodisi se boš držal njegovih zapovedi ali ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Ponižal te je in ti dopustil, da si bil lačen in te hranil z mano, ki je nisi poznal niti je niso poznali tvoji očetje, da bi ti on lahko dal spoznati, da človek ne živi samo od kruha, temveč človek živi od vsake besede, ki izhaja iz Gospodovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Teh štirideset let se tvoja obleka na tebi ni postarala niti tvoje stopalo ni oteklo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'V svojem srcu boš tudi preudaril, da kakor mož kara svojega sina, tako Gospod, tvoj Bog, kara tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Zatorej boš varoval zapovedi Gospoda, svojega Boga, da hodiš po njegovih poteh in da se ga bojiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Kajti Gospod, tvoj Bog, te vodi v dobro deželo, deželo vodnih potokov, studencev in globin, ki privrejo iz dolin in hribov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'deželo pšenice, ječmena, trt, figovih dreves in granatnih jabolk; deželo olivnega olja in medu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'deželo, v kateri boš jedel kruh brez pomanjkanja, v njej ti ne bo primanjkovalo nobene stvari; deželo, katere kamni so železo in iz katerih hribov lahko koplješ bron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Ko se naješ in si sit, potem boš blagoslovil Gospoda, svojega Boga, zaradi dobre dežele, ki ti jo je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Pazi se, da ne pozabiš Gospoda, svojega boga, da se ne bi držal njegovih zapovedi, njegovih sodb in njegovih zakonov, ki sem ti jih zapovedal ta dan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'da se ne bi, ko se naješ in si sit in si si zgradil ljubke hiše in prebival v njih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'in ko se tvoji tropi in tvoje črede pomnožijo in je pomnoženo tvoje srebro in tvoje zlato in je pomnoženo vse, kar imaš;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'tvoje srce ne povzdigne in pozabiš na Gospoda, svojega Boga, ki te je privedel iz egiptovske dežele, iz hiše sužnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'ki te je vodil skozi to veliko in strašno divjino, v kateri so bile ognjene kače, škorpijoni in suša, kjer ni bilo vode; ki ti je vodo privedel iz kremenčeve skale;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'ki te je v divjini hranil z mano, ki je tvoji očetje niso poznali, da bi te lahko ponižal in da bi te lahko preizkusil, da ti v tvojem zadnjem koncu stori dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'In ti bi rekel v svojem srcu: ›Moja moč in mogočnost moje roke mi je pridobila to premoženje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Ampak se boš spominjal Gospoda, svojega Boga, kajti on je ta, ki ti daje moč, da pridobiš premoženje, da lahko on vzpostavi svojo zavezo, ki jo je prisegel tvojim očetom, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Zgodilo pa se bo, če pozabite Gospoda, svojega Boga in hodite za drugimi bogovi in jim služite in jih obožujete, ta dan pričujem zoper vas, se boste zagotovo pogubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Kakor narodi, ki jih Gospod uničuje pred vašim obrazom, tako se boste pogubili, ker niste hoteli biti poslušni glasu Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Poslušaj, oh Izrael: ›Danes prečkaš Jordan, da vstopiš in vzameš v last narode, večje in močnejše kakor ti, velika mesta in ograjena do neba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'veliko in visoko ljudstvo, otroke Anákovcev, ki jih poznaš in o katerih si slišal reči: ›Kdo lahko stoji pred Anákovimi otroki!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Razumi torej ta dan, da je Gospod, tvoj Bog, tisti, ki gre preko pred teboj. Kakor požirajoč ogenj jih bo uničil in on jih bo privedel dol, pred tvoj obraz. Tako jih boš pognal ven in jih hitro uničil, kakor ti je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ne govori v svojem srcu, potem ko jih je Gospod, tvoj Bog, spodil izpred tebe, rekoč: ›Zaradi moje pravičnosti me je Gospod privedel, da vzamem v last to deželo,‹ temveč jih je zaradi zlobnosti teh narodov Gospod pognal izpred tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne greš, da zaradi svoje pravičnosti ali zaradi poštenosti svojega srca vzameš v last njihovo deželo, temveč zaradi zlobnosti teh narodov jih je Gospod, tvoj Bog, pognal izpred tebe in da lahko izpolni besedo, ki jo je Gospod prisegel tvojim očetom, Abrahamu, Izaku in Jakobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Razumi torej, da ti Gospod, tvoj Bog, te dobre zemlje ne daje v posest zaradi tvoje pravičnosti, kajti ti si trdovratno ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Zapomni si in ne pozabi, kako si v divjini do besa dražil Gospoda, svojega Boga. Od dneva, ko si odšel iz egiptovske dežele, dokler niste prišli na ta kraj, ste bili uporni zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Tudi na Horebu ste do besa izzivali Gospoda, tako da je bil Gospod nad vami jezen, da vas uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Ko sem odšel gor na goro, da prejmem kamniti plošči, torej plošči zaveze, ki jo je Gospod sklenil z vami, potem sem na gori ostal štirideset dni in štirideset noči niti nisem jedel kruha niti pil vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'In Gospod mi je izročil dve kamniti plošči, popisani z Božjim prstom. Na njima je bilo napisano glede na vse besede, ki jih je Gospod z vami govoril na gori, iz srede ognja, na dan zbora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Ob koncu štiridesetih dni in štiridesetih noči se je pripetilo, da mi je Gospod dal dve kamniti plošči, torej plošči zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Gospod mi je rekel: ›Vstani, hitro se spusti od tod, kajti tvoje ljudstvo, ki si jih privedel iz Egipta, se je izpridilo. Hitro so se obrnili proč iz poti, ki sem jim jo zapovedal. Naredili so si ulito podobo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Nadalje mi je Gospod spregovoril, rekoč: ›Videl sem to ljudstvo in glej, to je trdovratno ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Pusti me pri miru, da jih lahko uničim in njihovo ime izbrišem izpod neba. Iz tebe pa bom naredil narod, mogočnejši in večji kakor oni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Tako sem se obrnil in prišel dol z gore in gora je gorela z ognjem in dve tabli zaveze sta bili v mojih dveh rokah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Pogledal sem in glej, grešili ste zoper Gospoda, svojega Boga in si naredili ulito tele. Hitro ste se obrnili proč iz poti, ki vam jo je zapovedal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Vzel sem dve plošči in ju vrgel iz svojih dveh rok ter ju razbil pred vašimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'In padel sem dol pred Gospodom, kakor prvič, štirideset dni in štirideset noči. Niti nisem jedel kruha niti nisem pil vode zaradi vseh vaših grehov, ki ste jih z zlobnim početjem zagrešili v Gospodovih očeh, da ga izzivate k jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Kajti bal sem se jeze in silnega nezadovoljstva, s katerim je bil Gospod ogorčen zoper vas, da vas uniči. Toda Gospod mi je tudi ob tistem času prisluhnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Gospod je bil zelo jezen nad Aronom, da bi ga uničil, jaz pa sem isti čas molil za Arona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Vzel sem vaš greh, tele, ki ste ga naredili in ga sežgal z ognjem in ga poteptal in ga zelo drobno zmlel, dokler ni bil ta majhen kakor prah, in njegov prah sem vrgel v potok, ki se spušča z gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'In pri Tabêri, pri Masi in pri Kibrot-Hattaavi ste do besa izzivali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Podobno, ko vas je Gospod poslal iz Kadeš Barnée, rekoč: ›Pojdite gor in vzemite v last deželo, ki sem vam jo dal.‹ Potem ste se uprli zoper zapoved Gospoda, svojega Boga in mu niste verjeli niti niste prisluhnili njegovemu glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Od dneva, ko sem vas spoznal, ste bili uporni zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Tako sem padel dol pred Gospodom, štirideset dni in štirideset noči, kakor sem prvič padel dol, ker je Gospod rekel, da vas bo uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Molil sem torej h Gospodu in rekel: ›Oh Gospod Bog, ne uniči svojega ljudstva in svoje dediščine, ki si jo odkupil preko svoje veličine, ki si jo s svojo mogočno roko privedel iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Spomni se svojih služabnikov: Abrahama, Izaka in Jakoba. Ne glej na trmoglavost teh ljudi niti k njihovi zlobnosti niti k njihovemu grehu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'da ne bi dežela, od koder si nas privedel, rekla: ›Ker jih Gospod ni bil zmožen privesti v deželo, ki jim jo je obljubil in ker jih je sovražil, jih je privedel ven, da jih pobije v divjini.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Vendar so tvoje ljudstvo in tvoja dediščina, ki si jih izpeljal s svojo mogočno močjo in s svojim iztegnjenim laktom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Ob tistem času mi je Gospod rekel: ›Izsekaj si dve kamniti plošči, podobni prvima in pridi gor k meni na goro in si naredi skrinjo iz lesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Na tabli bom zapisal besede, ki so bile na prvih tablah, ki si ju razbil in položil ju boš v skrinjo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'In naredil sem skrinjo iz akacijevega lesa in izsekal dve kamniti plošči, podobni prvima in odšel gor na goro in v svoji roki sem imel dve tabli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Na tabli je zapisal deset zapovedi, glede na prvo pisanje, ki vam jih je Gospod govoril na gori iz srede ognja na dan zbora. In Gospod mi ju je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Obrnil sem se in prišel dol z gore in tabli položil v skrinjo, ki sem jo naredil, in tam sta, kakor mi je Gospod zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Izraelovi otroci so odšli na svoje potovanje od Beeróta Jaakánovih otrok v Mosêro. Tam je Aron umrl in tam je bil pokopan in namesto njega je v duhovniški službi služil njegov sin Eleazar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Od tam so odpotovali v Gidgád in iz Gidgáda v Jotbáto, deželo rek vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Ob tistem času je Gospod ločil Lévijev rod, da nosi skrinjo Gospodove zaveze, da stojijo pred Gospodom, da mu služijo in da blagoslavljajo v njegovem imenu, do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Zato Levi nima deleža niti dediščine s svojimi brati; Gospod je njegova dediščina, kakor mu je obljubil Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'In ostal sem na gori, kakor prvič, štirideset dni in štirideset noči in Gospod mi je prisluhnil tudi ob tistem času in Gospod te ni hotel uničiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Gospod mi je rekel: ›Vstani, odpravi se na svoje potovanje pred ljudstvom, da lahko vstopijo in vzamejo v last deželo, ki sem jo prisegel njihovim očetom, da jim jo dam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'In sedaj, Izrael, kaj Gospod, tvoj Bog, zahteva od tebe, razen, da se bojiš Gospoda, svojega Boga, da hodiš po vseh njegovih poteh, da ga ljubiš, da služiš Gospodu, svojemu Bogu, z vsem svojim srcem in z vso svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Da varuješ Gospodove zapovedi in njegove zakone, ki ti jih ta dan zapovedujem v tvoje dobro?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Glej, nebo in nebesa nebes so od Gospoda, tvojega Boga, tudi zemlja z vsem, kar je na njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Samo Gospod je imel zadovoljstvo v tvojih očetih, da jih vzljubi in izbral je njihovo seme za njimi, torej vas, izmed vseh ljudstev, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Obrežite torej prednjo kožico svojega srca in ne bodite več trdovratni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Kajti Gospod, vaš Bog, je Bog bogov in Gospod gospodov in véliki Bog, mogočen in strašen, ki se ne ozira na osebe niti ne sprejema nagrade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Izvaja sodbo sirote in vdove in ljubi tujca v tem, da mu daje hrano in oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Ljubite torej tujca, kajti tujci ste bili v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Bal se boš Gospoda, svojega Boga. Njemu boš služil in k njemu se boš trdno pridružil in prisegal pri njegovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'On je tvoja hvala in on je tvoj Bog, ki je zate storil te velike in strašne stvari, ki so jih videle tvoje oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tvoji očetje so odšli dol v Egipt s sedemdesetimi osebami in sedaj te je Gospod, tvoj Bog, naredil kakor zvezd neba zaradi množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Zato boš torej ljubil Gospoda, svojega Boga in dnevno ohranjal njegovo zadolžitev, njegove zakone, njegove sodbe in njegove zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'In vedi ta dan, kajti nisem govoril z otroki, ki niso vedeli in ki niso videli kaznovanja Gospoda, svojega Boga, njegove veličine, njegove mogočne roke, njegovega iztegnjenega lakta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'njegovih čudežev in njegovih dejanj, ki jih je v sredi Egipta storil faraonu, egiptovskemu kralju in vsej njegovi deželi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'in kaj je on storil egiptovski vojski, njihovim konjem in njihovim bojnim vozovom; kako je vodo Rdečega morja primoral, da jih preplavi, medtem ko so vas zasledovali in kako jih je Gospod uničil do današnjega dne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'in kaj vam je storil v divjini, dokler niste prišli na ta kraj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'in kaj je storil Datánu in Abirámu, sinovoma Rubenovega sina Eliába; kako je zemlja odprla svoja usta in požrla njiju, njune družine, njune šotore in vse njuno imetje, ki je bilo v njuni posesti, v sredi vsega Izraela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'toda vaše oči so videle vsa velika Gospodova dejanja, ki jih je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Zatorej boste ohranjali vse zapovedi, ki sem vam jih ta dan zapovedal, da boste lahko močni in vstopite in se polastite dežele, kamor greste, da jo vzamete v last');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'in da boste lahko podaljšali svoje dneve v deželi, ki jo je Gospod prisegel vašim očetom, da jo da njim in njihovemu semenu, deželo, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Kajti dežela, kamor vstopaš, da jo vzameš v last, ni kakor egiptovska dežela, od koder ste izšli, kjer si sejal svoje seme in jo s svojim stopalom namakal kakor zeliščni vrt,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'temveč je dežela, kamor greste, da jo vzamete v last, dežela hribov in dolin in pitne vode od dežja z neba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'dežela, za katero skrbi Gospod, tvoj Bog; oči Gospoda, tvojega Boga, so vedno na njej, od začetka leta, celó do konca leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'In zgodilo se bo, če boste marljivo prisluhnili mojim zapovedim, ki sem vam jih ta dan zapovedal, da ljubite Gospoda, svojega Boga in da mu služite z vsem svojim srcem in z vso svojo dušo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'da vam bom dal dežja vaši deželi v njegovem pravšnjem obdobju, prvi dež in pozni dež, da boš lahko zbral svoje žito in svoje vino in svoje olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'In poslal bom travo na tvoja polja za tvojo živino, da boš lahko jedel in bil sit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Pazite nase, da vaše srce ne bo zavedeno in se odvrnete in služite drugim bogovom in jih obožujete');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'in bi se potem zoper vas vžgal Gospodov bes in on zapre nebo, da tam ne bo dežja in da dežela ne obrodi svojega sadu in da se ne bi hitro pogubili iz dobre dežele, ki vam jo daje Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Zatorej boste te moje besede položili v svoje srce in v svojo dušo in si jih privezali za znamenje na roko, da bodo lahko kakor načelki med vašimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'In vi jih boste učili svoje otroke, govoreč o njih, ko sediš v svoji hiši in ko hodiš po poti, ko se uležeš in ko vstajaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Napisal jih boš na podboje svoje hiše in na svoja velika vrata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'da bodo vaši dnevi lahko pomnoženi in dnevi vaših otrok v deželi, ki jo je Gospod prisegel vašim očetom, da jim jo da, kakor dneve nebes na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Kajti če boste marljivo varovali vse te zapovedi, ki sem vam jih zapovedal, da jih storite, da ljubite Gospoda, svojega Boga, da hodite po vseh njegovih poteh in da se ga trdno držite,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'potem bo Gospod vse te narode izgnal izpred vas in vi se boste polastili večjih narodov in mogočnejših, kakor ste vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Vsak kraj, na katerega bodo stopili podplati vaših stopal, bo vaš; od divjine in Libanona, od reke, reke Evfrata, celo do najbolj oddaljenega morja bo vaša pokrajina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Tam noben človek ne bo mogel obstati pred vami, kajti Gospod, vaš Bog, bo položil strah pred vami in grozo nad vso deželo, po kateri boste stopali, kakor vam je rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Glejte, ta dan sem pred vas postavil blagoslov in prekletstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Blagoslov, če ubogate zapovedi Gospoda, svojega Boga, ki sem vam jih ta dan zapovedal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'in prekletstvo, če ne boste ubogali zapovedi Gospoda, svojega Boga, temveč se boste odvrnili iz poti, ki sem vam jo ta dan zapovedal, da greste za drugimi bogovi, ki jih niste poznali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'In zgodilo se bo, ko te bo Gospod, tvoj Bog, privedel v deželo, kamor greš, da jo vzameš v last, da boš položil blagoslov na goro Garizím in prekletstvo na goro Ebál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ali nista na drugi strani Jordana, ob poti, kjer sonce zahaja v kánaanski deželi, ki prebivajo v nerodovitni ravnini nasproti Gilgálu, poleg Moréjevih ravnin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Kajti šli boste čez Jordan, da vstopite, da vzamete v last deželo, ki vam jo daje Gospod, vaš Bog in vzeli jo boste v last in prebivali v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'In obeležili boste, da storite vse zakone in sodbe, ki sem jih ta dan postavil pred vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'To so zakoni in sodbe, ki jih boste obeležili, da jih počnete v deželi, ki ti jo daje Gospod, Bog vaših očetov, da jo vzamete v last, vse dni, ko živite na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vse kraje, na katerih so narodi, ki jih boste vzeli v last, služili svojim bogovom na visokih gorah, na hribih in pod vsakim zelenim drevesom, boste popolnoma uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Porušili boste njihove oltarje, zlomili njihove stebre, njihove ašere sežgali z ognjem, posekali boste rezane podobe njihovih bogov in njihova imena uničili iz tega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Tako ne boste storili Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Toda na kraj, ki ga bo Gospod, vaš Bog, izbral izmed vseh vaših rodov, da tam položi svoje ime, celó k njegovemu prebivališču boste sledili in tja boš prišel');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'in tja boste prinašali svoje žgalne daritve, svoje klavne daritve, svoje desetine, vzdigovalne daritve svoje roke, svoje zaobljube, svoje prostovoljne daritve in prvence od svojih čred in od svojih tropov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Tam boste jedli pred Gospodom, svojim Bogom in veselili se boste v vsem, k čemur položite svojo roko, vi in vaše družine, v čemer te je Gospod, tvoj Bog, blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ne boste počeli po vseh stvareh, ki jih mi ta dan delamo tukaj, vsak mož karkoli je pravilno v njegovih lastnih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Kajti doslej niste prišli k počitku in k dediščini, ki vam jo daje Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Toda ko greste čez Jordan in prebivate v deželi, ki vam jo daje Gospod, vaš Bog, da jo podedujete in ko vam daje počitek pred vsemi vašimi sovražniki naokoli, tako da varno prebivate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'potem bo tam kraj, ki ga bo Gospod, vaš Bog, izbral, da svojemu imenu povzroči, da prebiva tam. Tja boste prinesli vse, kar sem vam zapovedal: vaše žgalne daritve, vaše klavne daritve, vaše desetine, vzdigovalno daritev vaše roke in vso vašo izbiro zaobljub, ki ste jih zaobljubili Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'in veselili se boste pred Gospodom, vašim Bogom, vi in vaši sinovi, vaše hčere, služabniki, vaše dekle in Lévijevec, ki je znotraj tvojih velikih vrat, ker nima ne deleža, ne dediščine z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Pazi nase, da ne daruješ svojih žgalnih daritev na vsakem kraju, ki ga vidiš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'temveč na kraju, ki ga bo Gospod izbral v enem izmed tvojih rodov, tam boš daroval svoje žgalne daritve in tam boš počel vse, kar ti zapovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Vendar v vseh svojih velikih vratih lahko zakolješ in ješ meso, karkoli tvoja duša poželi, glede na blagoslov Gospoda, tvojega Boga, ki ti ga je dal. Nečisti in čisti lahko jé od tega, kakor od srnjaka in kakor od jelena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Samo krvi ne boste jedli; kakor vodo jo boste izlili na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Znotraj svojih velikih vrat ne smeš jesti desetine svojega žita ali svojega vina ali svojega olja ali prvencev svojih čred ali svojega tropa, niti česarkoli od svojih zaobljub, ki si jih zaobljubil, niti svojih prostovoljnih daritev ali vzdigovalne daritve svoje roke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'temveč jih moraš jesti pred Gospodom, svojim Bogom, na kraju, ki ga bo Gospod, tvoj Bog, izbral, ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla in Lévijevec, ki je znotraj tvojih velikih vrat, in veselil se boš pred Gospodom, svojim Bogom, v vsem, k čemur priložiš svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Pazi nase, da ne zapustiš Lévijevca tako dolgo, kot živiš na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Ko bo Gospod, tvoj Bog, povečal tvojo mejo, kakor ti je obljubil in boš rekel: ›Jedel bom meso,‹ ker tvoja duša hrepeni, da bi jedla meso; lahko ješ meso, karkoli tvoja duša poželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Če je kraj, ki ga je izbral Gospod, tvoj Bog, da tam položi svoje ime, predaleč od tebe, potem boš zaklal od svoje črede in od svojega tropa, ki ti ga je dal Gospod, kakor sem ti zapovedal in v svojih velikih vratih boš jedel karkoli tvoja duša poželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Celo kakor se pojesta srnjak in jelen, tako jih boš ti pojedel. Nečisti in čisti bosta enako jedla od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Samo bodi odločen, da ne ješ krvi, kajti kri je življenje in življenja ne smeš jesti z mesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Ne boš je jedel. Kakor vodo jo boš izlil na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Ne boš je jedel, da bo lahko dobro s teboj in s tvojimi otroki za teboj, ko boš delal to, kar je pravilno v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Samo svoje svete stvari, ki jih imaš in svoje zaobljube boš vzel in šel na kraj, ki ga bo Gospod izbral');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'in daroval boš svoje žgalne daritve, meso in kri, na oltarju Gospoda, svojega Boga. In kri tvojih klavnih daritev bo izlita na oltar Gospoda, tvojega Boga in jedel boš meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Obeležuj in poslušaj vse te besede, ki sem ti jih zapovedal, da bo lahko dobro s teboj in s tvojimi otroki za teboj na veke, ko delaš to, kar je dobro in pravilno v očeh Gospoda, tvojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Ko bo Gospod, tvoj Bog, izpred tebe uničil narode, kamor greš, da jih vzameš v last in jih zasedeš in prebivaš v njihovi deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'pazi nase, da ne boš ujet s tem, da jim slediš, potem ko so bili uničeni izpred tebe, in da ne povprašuješ po njihovih bogovih, rekoč: ›Kako so ti narodi služili svojim bogovom? Celo jaz bom počel podobno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ne boš tako počel Gospodu, svojemu Bogu, kajti vsako ogabnost Gospodu, ki jo on sovraži, so počeli svojim bogovom, kajti celo svoje sinove in svoje hčere so v ognju sežigali svojim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Katerokoli stvar ti zapovem, obeležuj, da jo storiš. K temu ne boš dodal niti od tega ne boš jemal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Če tam med vami vstane prerok ali sanjač sanj in ti daje znamenje ali čudež');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'in se znamenje ali čudež, o katerem ti je govoril zgodi, rekoč: ›Pojdimo za drugimi bogovi, ki jih nisi poznal in jim služimo,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'ne boš prisluhnil besedam tega preroka ali tega sanjača sanj, kajti Gospod, vaš Bog, vas preizkuša, da bi spoznal ali ljubite Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Hodili boste za Gospodom, svojim Bogom in se ga bali in varovali njegove zapovedi in ubogali njegov glas in mu boste služili in se trdno pridružili k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Tisti prerok ali tisti sanjač sanj pa bo usmrčen, zato ker je govoril, da vas odvrne od Gospoda, vašega Boga, ki vas je privedel iz egiptovske dežele in vas odkupil iz hiše sužnosti, da bi te sunil iz poti, ki ti jo je Gospod, tvoj Bog, zapovedal, da hodiš po njej. Tako boš zlo iztrebil proč iz svoje srede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Če te tvoj brat, sin tvoje matere ali tvoj sin ali tvoja hči ali žena tvojega naročja ali tvoj prijatelj, ki je kakor tvoja lastna duša, na skrivaj privabi, rekoč: ›Pojdimo in služimo drugim bogovom,‹ ki jih nisi poznal ne ti niti tvoji očetje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'namreč bogovom ljudstev, ki so naokoli tebe, blizu tebe ali daleč od tebe, od enega konca zemlje celo do drugega konca zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'se ne boš strinjal z njim, niti mu prisluhnil, niti se ga tvoje oko ne bo usmililo, niti ne boš prizanesel, niti mu ne boš prikrival,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'temveč ga boš zagotovo ubil. Tvoja roka bo prva nad njim, da ga položi v smrt in zatem roka vsega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Kamnal ga boš s kamni, da umre, ker je iskal, da te pahne proč od Gospoda, tvojega Boga, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'In ves Izrael bo slišal in se bal in nobene takšne zlobnosti, kot je ta, ne bo več storil med vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Če boš slišal reči v enem izmed svojih mest, ki ti jih je Gospod, tvoj Bog, dal, da prebivaš tam, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, '› Neki možje, Beliáovi otroci, so odšli ven izmed vas in zavedli prebivalce svojega mesta, rekoč: ›Pojdimo in služimo drugim bogovom,‹ ki jih niste poznali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Potem boš povprašal in naredil preiskavo in marljivo spraševal, in glej, če je to res in je stvar gotova, da je med vami narejena takšna ogabnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'potem boš prebivalce tega mesta zagotovo udaril z ostrino meča, ga skrajno uničil in vse, kar je v njem in njegovo živino, z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Ves njegov plen boš zbral na sredi njegove ulice in mesto popolnoma sežgal z ognjem in ves njegov plen, za Gospoda, svojega Boga, in le-to bo kup na veke; ne bo ponovno zgrajeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Tvoje roke se ne bo trdno pridružilo ničesar od preklete stvari, da se bo Gospod lahko odvrnil od okrutnosti svoje jeze in ti izkazal usmiljenje in imel sočutje nad teboj in te pomnožil, kakor je prisegel tvojim očetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'ko boš prisluhnil glasu Gospoda, svojega Boga, da varuješ vse njegove zapovedi, ki sem ti jih ta dan ukazal, da delaš to, kar je pravilno v očeh Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vi ste otroci Gospoda, svojega Boga. Ne boste se rezali niti naredili katerekoli plešavosti med svojimi očmi zaradi mrtvega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Kajti ti si sveto ljudstvo Gospoda, svojega Boga in Gospod te je izbral, da bi mu bil izvoljeno ljudstvo nad vsemi narodi, ki so na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Ne boš jedel kakršnekoli gnusne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'To so živali, ki jih boš jedel: vol, ovca, koza,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'jelen, srnjak, damjak, divja koza, antilopa, divji vol in gams.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Vsako žival, ki deli kopito in ima parklje razklane na dvoje in prežvekuje med živalmi, to boste jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Vendar teh ne boste jedli izmed teh, ki prežvekujejo ali izmed teh, ki delijo kopito, kot so kamela, zajec in kunec, kajti prežvekujejo, toda ne delijo kopita, zato so vam nečiste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'In svinjo, ker ta deli kopito, vendar ne prežvekuje, ta vam je nečista. Ne boste jedli od njihovega mesa niti se ne boste dotaknili njihovega mrtvega trupla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Te boste jedli od vsega, kar je v vodah: jedli boste vse, ki imajo plavuti in luske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Karkoli pa nima plavuti in lusk ne smete jesti, to vam je nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Jedli boste od vseh čistih ptic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Toda ti so tisti, od katerih ne boste jedli: orel, brkati ser, ribji orel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'črni škarnik, kragulj, jastreb po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'vsak krokar po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'sova, nočni sokol, kukavica, sokol po njegovi vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'majhna sova, velika sova, labod,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikan, egiptovski jastreb, kormoran,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'štorklja, čaplja po svoji vrsti, smrdokavra in netopir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Vsaka plazeča stvar, ki leti, vam je nečista, teh naj se ne jé.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Toda od vse čiste perjadi lahko jeste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Od nobene stvari, ki pogine sama od sebe, ne boste jedli. Dal jo boš tujcu, ki je v tvojih velikih vratih, da bo to lahko jedel, oziroma jo lahko prodaš neznancu, kajti ti si sveto ljudstvo Gospodu, svojemu Bogu. Kozlička ne boš kuhal v mleku njegove matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Resnično boš desetinil ves donos svojega semena, ki ti ga polje prinaša leto za letom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Pred Gospodom, svojim Bogom, na kraju, ki ga je on izbral, da tam namesti svoje ime, boš jedel desetino svojega žita, svojega vina, svojega olja in prvence svojih čred in svojih tropov, da se lahko naučiš vedno bati se Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Če pa je pot zate predolga, tako da tega ne moreš nesti, ali če je kraj, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi svoje ime, predaleč od tebe, ko te je Gospod, tvoj Bog, blagoslovil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'potem boš to spremenil v denar in denar povezal v svojo roko in boš šel na kraj, ki ga bo Gospod, tvoj Bog, izbral,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'in ti boš ta denar dal, za karkoli tvoja duša poželi. Za vole ali za ovce ali za vino ali za močno pijačo ali za karkoli, kar tvoja duša poželi in jedel boš tam pred Gospodom, svojim Bogom in veselil se boš ti in tvoja družina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'in Lévijevec, ki je znotraj tvojih velikih vrat. Ne boš ga zapustil, kajti on nima niti deleža niti dediščine s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Ob koncu treh let boš prinesel vso desetino svojega pridelka istega leta in to boš položil znotraj svojih velikih vrat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'in Lévijevec (ker nima niti deleža niti dediščine s teboj) in tujec, sirota in vdova, ki so znotraj tvojih velikih vrat, bodo prišli, jedli in bodo nasičeni, da te Gospod, tvoj Bog, lahko blagoslovi pri vsem delu tvoje roke, ki ga počneš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Ob koncu vsakih sedmih let boš naredil odpust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'To je način odpusta. Vsak upnik, ki posoja, mora svojemu bližnjemu to odpustiti. Tega ne bo terjal od svojega bližnjega ali od svojega brata, ker je to imenovano Gospodov odpust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Od tujca lahko to ponovno zahtevaš, toda kar je tvoje, s tvojim bratom, bo tvoja roka odpustila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'razen ko med vami ne bo nobenega revnega, kajti Gospod te bo silno blagoslovil v deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, da jo vzameš v last,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'samo če previdno prisluhneš glasu Gospoda, svojega Boga, da obeležuješ izpolnjevanje vseh teh zapovedi, ki sem ti jih ta dan zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Kajti Gospod, tvoj Bog, te blagoslavlja, kakor ti je obljubil in posojal boš mnogim narodom, toda ti si ne boš izposojal in kraljeval boš nad mnogimi narodi, toda oni ne bodo kraljevali nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Če je med vami revež enega izmed tvojih bratov znotraj katerihkoli izmed tvojih velikih vrat, v tvoji deželi, ki ti jo daje Gospod, tvoj Bog, ne boš zakrknil svojega srca niti svoje roke zaprl pred svojim revnim bratom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'temveč mu boš na široko odprl svojo roko in zagotovo mu boš posodil dovolj za njegovo potrebo, v tem, kar mu manjka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Pazi se, da ne bi bilo misli v tvojem zlobnem srcu, rekoč: ›Sedmo leto, leto odpusta, se približuje‹ in je tvoje oko zlobno zoper tvojega revnega brata in mu ničesar ne daš in on zoper tebe kliče h Gospodu in to ti bo greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Zagotovo mu boš dal in tvoje srce ne bo užaloščeno, ko mu daješ, zato ker te bo za to stvar Gospod, tvoj Bog, blagoslovil v vseh tvojih delih in v vsem, k čemur boš položil svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Kajti revni ne bo nikoli izginil iz dežele. Zatorej ti zapovedujem, rekoč: ›Svojo roko boš na široko odprl svojem bratu, svojemu revnemu in svojemu pomoči potrebnemu v svoji deželi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'In če ti bo prodan tvoj brat, Hebrejec ali Hebrejka in ti služi šest let, ga boš potem v sedmem letu od sebe pustil svobodnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'In ko ga svobodnega pošlješ od sebe, mu ne boš pustil, da gre proč prazen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Velikodušno ga boš opremil iz svojega tropa in iz svojega mlatišča in iz svoje vinske stiskalnice. Dal mu boš od tega, s čimer te je Gospod, tvoj Bog, blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Spomnil se boš, da si bil suženj v egiptovski deželi in Gospod, tvoj Bog, te je odkupil, zato ti danes zapovedujem to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Zgodilo se bo, če ti reče: ›Ne bom šel proč od tebe,‹ ker ljubi tebe in tvojo hišo, ker mu je dobro s teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'potem boš vzel šilo in ga na vratih prebodel skozi njegovo uho in on bo tvoj služabnik na veke. In prav tako boš podobno storil svoji dekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Ne bo se ti zdelo težko, ko ga svobodnega pošlješ proč od sebe, kajti vreden ti je bil dvojnega najetega služabnika, v tem, ko ti je služil šest let in Gospod, tvoj Bog, te bo blagoslovil v vsem, kar delaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Vse prvence, ki pridejo iz tvoje črede in iz tvojega tropa, boš posvetil Gospodu, svojemu Bogu. Nobenega dela ne boš opravljal s prvencem svojega bikca niti strigel prvenca svoje ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'To boš leto za letom jedel pred Gospodom, svojim Bogom, ti in tvoja družina, na kraju, ki ga bo Gospod izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'In če je na njem kakršnakoli pomanjkljivost kakor, če je hrom ali slep ali ima kakršnokoli bolezensko pomanjkljivost, ga ne boš žrtvoval Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Jedel ga boš znotraj svojih velikih vrat. Nečista in čista oseba ga bo jedla enako kakor srnjaka in kakor jelena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Samo njegove krvi ne boš jedel. Na tla jo boš izlil kakor vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Obeležujte mesec abíb in praznujte pasho Gospodu, svojemu Bogu, kajti v mesecu abíbu te je Gospod, tvoj Bog, ponoči privedel iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Torej boš žrtvoval pasho Gospodu, svojemu Bogu, od tropa in črede, na kraju, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Zraven ne boš jedel nobenega kvašenega kruha. Sedem dni boš zraven jedel nekvašen kruh, celo kruh stiske, kajti v naglici si prišel iz egiptovske dežele, da se vse dni svojega življenja lahko spominjaš dneva, ko si prišel ven iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'S teboj, v vseh tvojih pokrajinah, sedem dni ne bo videti nobenega kvašenega kruha niti naj tam ne ostane nobene stvari od mesa, ki ga žrtvuješ zvečer prvega dne, čez noč do jutra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Ne smeš žrtvovati pashe, ki ti jo daje Gospod, tvoj Bog, znotraj katerihkoli izmed tvojih velikih vrat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'temveč na kraju, ki ti ga bo Gospod, tvoj Bog, izbral, da tja postavi svoje ime, tam boš zvečer žrtvoval pasho ob sončnem zahodu, ob času, ko si prišel ven iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'To boš spekel in jedel na kraju, ki ga bo izbral Gospod, tvoj Bog. Zjutraj pa se boš obrnil in šel v svoje šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Šest dni boš jedel nekvašen kruh in na sedmi dan bo slovesen zbor Gospodu, tvojemu Bogu. V tem [dnevu] ne boš opravljal nobenega dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sedem tednov si boš štel, začni šteti sedem tednov od tistega časa, ko v žito začenjaš postavljati srp.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Praznik tednov Gospodu, svojemu Bogu, boš ohranjal z obiljem prostovoljne daritve svoje roke, ki jo boš dal Gospodu, svojemu Bogu, glede na to, kakor te je Gospod, tvoj Bog, blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Veselil se boš pred Gospodom, svojim Bogom, ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla, Lévijevec, ki je znotraj tvojih velikih vrat, in tujec, sirota ter vdova, ki so med vami, na mestu, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi svoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Spominjal se boš, da si bil suženj v Egiptu in obeleževal in izvajal boš vse te zakone.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Sedem dni boš obeleževal šotorski praznik, potem ko si spravil svoje žito in svoje vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Ob svojem prazniku se boš veselil ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla, Lévijevec in tujec, sirota ter vdova, ki so znotraj tvojih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sedem dni boš praznoval slovesen praznik Gospodu, svojemu Bogu, na mestu, ki ga bo Gospod izbral, ker te bo Gospod, tvoj Bog, blagoslovil pri vsem tvojem donosu in v vseh delih tvojih rok, zato se boš zagotovo veselil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trikrat letno se bodo vsi tvoji možje prikazali pred Gospodom, tvojim Bogom, na kraju, ki ga bo izbral. Na praznik nekvašenega kruha, na praznik tednov in na šotorski praznik. Pred Gospodom se ne bodo prikazali prazni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Vsak moški bo dal, kakor je zmožen, glede na blagoslov Gospoda, tvojega Boga, ki ti ga je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Znotraj vseh svojih velikih vratih si boš postavil sodnike in častnike, ki ti jih daje Gospod, tvoj Bog, po tvojih rodovih in ljudstvu bodo sodili s pravično sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Ne boš sprevračal sodbe, ne boš se oziral na osebe niti ne boš jemal daru, kajti dar zaslepljuje oči modrega in sprevrača besede pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Temu, kar je povsem pravično, boš sledil, da boš lahko živel in podedoval deželo, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Ne boš si sadil nasada kakršnihkoli dreves blizu oltarja Gospoda, svojega Boga, ki si ga boš naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Niti si ne boš postavljal kakršnekoli podobe; kar Gospod, tvoj Bog, sovraži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Gospodu, svojemu Bogu, ne boš žrtvoval nobenega bika ali ovce, na kateri je pomanjkljivost ali kakršnakoli slaba stvar, kajti to je ogabnost Gospodu, tvojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Če se med vami najdeta mož ali ženska, znotraj katerihkoli izmed tvojih velikih vrat, ki ti jih daje Gospod, tvoj Bog, ki sta storila zlobnost v očeh Gospoda, tvojega Boga, v tem, da sta prestopala njegovo zavezo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'in sta šla in služila drugim bogovom in jih oboževala ali sonce ali luno ali katerokoli vojsko neba, česar nisem zapovedal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'in ti je to povedano in si o tem slišal in marljivo poizvedoval in glej, če je resnično in je stvar gotova, da je v Izraelu narejena takšna ogabnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'potem boš tega moža ali to žensko, ki sta zagrešila to zlobno stvar, pripeljal naprej, k svojim velikim vratom, torej tistega moža ali tisto žensko in ju boš kamnal s kamni, dokler ne umreta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Po ustih dveh ali treh prič bo tisti, ki je vreden smrti, usmrčen, toda po ustih ene priče ne bo usmrčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Roke prič bodo prve nad njim, da ga usmrtijo in potem roke vsega ljudstva. Tako boš odstranil zlo izmed vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Če tam vstane zadeva, v sodbi zate pretežka, med krvjo in krvjo, med izgovorom in izgovorom, med udarcem in udarcem, ki so zadeve polemike znotraj tvojih velikih vrat, potem se boš vzdignil in se povzpel na kraj, ki ga bo Gospod, tvoj Bog, izbral');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'in prišel boš k duhovnikom Lévijevcem in k sodniku, ki bo v tistih dneh in povprašal in pokazali ti bodo razsodbo sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Storil boš glede na razsodbo, ki ti jo bodo pokazali tisti, iz tistega kraja, ki ga bo Gospod izbral in obeleževal boš, da storiš glede na vse, o čemer te obvestijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Storil boš glede na razsodbo postave, ki te jo bodo učili, in glede na sodbo, ki ti jo bodo povedali. Ne boš se odvrnil od obsodbe, ki ti jo bodo pokazali, ne na desno roko niti ne na levo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Mož pa, ki bo delal prepotentno in ne bo prisluhnil duhovniku, ki tam stoji, da služi pred Gospodom, tvojim Bogom ali sodniku, celo tisti mož bo umrl, in ti se boš iz Izraela znebil zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'In vse ljudstvo bo slišalo in se balo in ne bo več prepotentno ravnalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Ko prideš v deželo, ki ti jo daje Gospod, tvoj Bog in jo boš vzel v last in boš prebival v njej in boš rekel: ›Nad seboj si bom postavil kralja, kakor je pri vseh narodih naokoli mene,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'boš vsekakor za kralja nad seboj postavil tistega, ki ga bo izbral Gospod, tvoj Bog. Enega izmed svojih bratov boš postavil za kralja nad seboj. Nad seboj ne smeš postaviti tujca, ki ni tvoj brat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Toda ta si ne bo množil konj niti ljudstvu ne bo povzročil, da se vrne v Egipt, z namenom, da bi množil konje, ker kakor ti je Gospod rekel: ›Odslej se ne boš več vrnil po tisti poti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Niti si k sebi ne bo množil žená, da njegovega srca ne odvrnejo stran niti k sebi ne bo silno pomnožil srebra in zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'In zgodilo se bo, ko sedi na prestolu svojega kraljestva, da si bo zapisal prepis te postave v knjigo iz te, ki je pred duhovniki Lévijevci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'in ta bo z njim in iz nje bo bral vse dni svojega življenja, da se bo lahko učil bati se Gospoda, svojega Boga, da ohranja vse besede te postave in te zakone, da jih izvršuje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'da njegovo srce ne bo povzdignjeno nad njegove brate in da se ne obrne proč od zapovedi, k desni roki ali k levi, z namenom, da lahko podaljša svoje dni v svojem kraljestvu, on in njegovi otroci, v sredi Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Duhovniki Lévijevci in ves Lévijev rod ne bodo imeli niti deleža niti dediščine z Izraelom. Jedli bodo Gospodove daritve, narejene z ognjem in [od] njegove dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Zato ne bodo imeli dediščine med svojim brati. Gospod je njihova dediščina, kakor jim je rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'In to bo pripadlo duhovniku od ljudstva, od tistih, ki darujejo klavno daritev, bodisi je to vol ali ovca; in duhovniku bodo dali pleče, dve ličnici in vamp.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Tudi prve sadove svojega žita, svojega vina, svojega olja in prvo runo svojih ovc mu boš dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Kajti Gospod, tvoj Bog, ga je izbral izmed vseh tvojih rodov, da stoji, da služi v Gospodovem imenu, njemu in njegovim sinovom na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Če pride Lévijevec od katerihkoli izmed tvojih velikih vrat, ven iz vsega Izraela, kjer je začasno bival in pride z vso željo svojega uma na kraj, ki ga bo Gospod izbral,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'potem bo služil v imenu Gospoda, svojega Boga, kakor počno vsi njegovi bratje Lévijevci, ki stojijo tam pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Za jesti bodo imeli podobne obroke, poleg tega, kar pride od prodaje imetja njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Ko prideš v deželo, ki ti jo daje Gospod, tvoj Bog, se ne boš naučil ravnati po gnusobah teh narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Naj ne bo najti med vami nikogar, ki primora svojega sina ali svojo hčer, da gre skozi ogenj ali da uporablja vedeževanje ali astrologa ali uročevalca ali čarovnico');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'ali zaklinjevalca ali posvetovalca z osebnimi duhovi ali čarovnika ali rotilca duhov umrlih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Kajti vsi ti, ki počno te stvari, so gnusoba Gospodu in zaradi teh gnusob jih bo Gospod, tvoj Bog, pognal izpred tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Popoln boš z Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Kajti ti narodi, ki se jih boš polastil, so poslušali astrologe in vedeževalce, toda kar se tebe tiče, ti Gospod, tvoj Bog, ni dopustil, da tako počneš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Gospod, tvoj Bog, ti bo iz tvoje srede, izmed tvojih bratov, obudil Preroka, podobnega meni. Njemu boste prisluhnili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'glede na vse, kar si na Horebu želel od Gospoda, svojega Boga, na dan zbora, rekoč: ›Naj ne poslušam ponovno glasu Gospoda, svojega Boga niti naj ne vidim več tega velikega ognja, da ne umrem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Gospod mi je rekel: ›Dobro so govorili to, kar so govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Vzdignil jim bom preroka izmed njihovih bratov, podobnega tebi in svoje besede bom položil v njegova usta in govoril jim bo vse, kar mu bom zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'In zgodilo se bo, da kdorkoli ne bo prisluhnil mojim besedam, ki jih bo govoril v mojem imenu, bom to zahteval od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Toda prerok, ki si bo predrznil govoriti besedo v mojem imenu, ki mu je nisem zapovedal govoriti ali ki bo govoril v imenu drugih bogov, celo ta prerok bo umrl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'In če v svojem srcu rečeš: ›Kako bomo spoznali besedo, ki je Gospod ni govoril?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Kadar prerok spregovori v Gospodovem imenu, če stvar ne sledi niti se ne zgodi, to je stvar, ki je Gospod ni rekel, temveč je prerok to prepotentno govoril. Ne boš se ga bal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Kadar je Gospod, tvoj Bog, iztrebil narode, katerih deželo ti daje Gospod, tvoj Bog in jih naslediš, prebivaš v njihovih mestih in v njihovih hišah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'si boš v sredi svoje dežele, ki ti jo Gospod, tvoj Bog, daje v last, oddvojil tri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Pripravil si boš pot in na tri dele razdelil pokrajine svoje dežele, ki ti jo daje Gospod, tvoj Bog, da jo podeduješ, da lahko vsak ubijalec pobegne tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'In to je primer ubijalca, ki bo pobegnil tja, da bo lahko živel: ›Kdorkoli nevede ubije svojega bližnjega, ki ga v preteklem času ni sovražil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'kot ko gre mož s svojim bližnjim v gozd, da sekata les in njegova roka zamahne udarec s sekiro, da poseka drevo in glava zdrsne iz toporišča in pade na njegovega bližnjega, da ta umre, bo pobegnil v eno izmed teh mest in živel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'da ne bi krvni maščevalec zasledoval ubijalca, medtem ko je njegovo srce vroče in ga dohitel, ker je dolga pot in ga ubil medtem ko ta ni bil vreden smrti, ker ga v preteklem času ni sovražil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Zato ti zapovedujem, rekoč: ›Zase si boš oddvojil tri mesta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Če Gospod, tvoj Bog, poveča tvojo pokrajino, kakor je prisegel tvojim očetom in ti da vso deželo, ki jo je obljubil dati tvojim očetom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'če boš ohranjal vse te zapovedi, ki ti jih ta dan zapovedujem, da jih izvršuješ, da ljubiš Gospoda, svojega Boga in da vedno hodiš po njegovih poteh, potem si boš poleg teh treh dodal še tri mesta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'da nedolžna kri ne bo prelita v tvoji deželi, ki ti jo daje v dediščino Gospod, tvoj Bog in bi bila tako na tebi kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Toda če katerikoli mož sovraži svojega bližnjega in nanj preži v zasedi in se dvigne zoper njega in ga smrtno udari, da ta umre in pobegne v eno izmed teh mest,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'potem bodo starešine njegovega mesta poslali in ga dobili od tam in ga izročili v roko krvnega maščevalca, da bo ta lahko umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Tvoje oko se ga ne bo usmililo, temveč boš iz Izraela odstranil krivdo nedolžne krvi, da bo lahko dobro s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Ne boš odstranil mejnika svojega bližnjega, ki so ga od starih časov postavili v tvojo dediščino, ki jo boš podedoval v deželi, ki ti jo Gospod, tvoj Bog, daje v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ena priča se ne bo dvignila zoper človeka zaradi katerekoli krivičnosti ali zaradi kateregakoli greha, s katerimkoli grehom je grešil. Zadeva se bo potrdila pri ustih dveh prič ali pri ustih treh prič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Če kriva priča vstane zoper kateregakoli, da priča zoper njega to, kar je napačno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'potem bosta oba človeka, med katerima je polemika, stala pred Gospodom, pred duhovniki in sodniki, ki bodo v tistih dneh');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'in sodniki bodo naredili marljivo zasliševanje. Glej, če je priča kriva priča in je lažno pričevala zoper svojega brata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'potem mu boste storili kakor je sam mislil storiti svojemu bratu. Tako boste izmed sebe iztrebili zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Tisti, ki preostanejo, bodo slišali in se bali in odslej med vami ne bodo več zagrešili nobenega takšnega zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Tvoje oko se ne bo usmililo, temveč bo življenje šlo za življenje, oko za oko, zob za zob, roka za roko, stopalo za stopalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Ko greš ven na boj zoper svoje sovražnike in vidiš konje in bojne vozove in ljudstvo, številnejše od tebe, se jih ne boj, kajti Gospod, tvoj Bog, je s teboj, ki te je privedel gor iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'In zgodilo se bo, ko se približate k bitki, da bodo pristopili duhovniki in spregovorili ljudstvu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'ter jim rekli: ›Prisluhni, oh Izrael, danes se približujete bitki zoper svoje sovražnike. Naj vaša srca ne slabijo, ne bojte se in ne trepetajte, niti zaradi njih ne bodite prestrašeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'kajti Gospod, vaš Bog, je ta, ki gre z vami, da se za vas bori zoper vaše sovražnike, da vas reši.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Častniki bodo ljudstvu govorili, rekoč: ›Kateri mož je tam, ki je zgradil novo hišo in je ni posvetil? Naj ta gre in se vrne k svoji hiši, da v bitki ne umre in je ne posveti drug moški.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'In kateri mož je ta, ki je zasadil vinograd in še ni jedel od njega? Tudi ta naj gre in se vrne k svoji hiši, da v bitki ne umre in drug moški ne jé od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'In kateri mož je tam, ki je zaročil ženo in je še ni vzel? Naj gre in se vrne k svoji hiši, da v bitki ne umre in je ne vzame drug moški.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Častniki bodo naprej govorili ljudstvu in bodo rekli: ›Kateri moški je tam, ki je bojazljiv in boječ? Naj gre in se vrne k svoji hiši, da ne bo srce njegovih bratov oslabelo tako kakor njegovo srce.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Zgodilo se bo, ko bodo častniki končali govorjenje ljudstvu, da bodo postavili poveljnike vojsk, da vodijo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Ko prideš blizu mesta, da se boriš zoper njega, potem mu razglasi mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Zgodilo se bo, če ti ta naredi odgovor miru in ti odpre, potem se bo zgodilo, da ti bodo vsi ljudje, ki so najdeni notri, postali davkoplačevalci in ti bodo služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Če pa s teboj ne bo sklenilo miru, temveč se bo zoper tebe vojskovalo, potem ga boš oblegal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'in ko ga Gospod, tvoj Bog, izroči v tvoje roke, boš vsakega tamkajšnjega moškega udaril z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Toda ženske, malčke, živino in vse, kar je v mestu, torej ves njegov plen, boš vzel k sebi in jedel boš plen svojih sovražnikov, ki ti ga je dal Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tako boš storil vsem mestom, ki so zelo daleč od tebe, ki niso od mest teh narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Toda od mest teh ljudstev, ki ti jih Gospod, tvoj Bog, da za dediščino, ne boš ohranil živega ničesar, kar diha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'temveč jih boš popolnoma uničil, namreč Hetejce, Amoréjce, Kánaance, Perizéjce, Hivéjce in Jebusejce, kakor ti je zapovedal Gospod, tvoj Bog,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'da te ne naučijo delati po vseh svojih ogabnostih, ki so jih storili svojim bogovom. Tako bi grešili zoper Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Ko boš dolgo časa oblegal mesto in se vojskoval zoper njega, da ga zavzameš, ne boš uničil njegovih dreves s tem, da bi nadnje privedel sekiro, kajti od njih lahko ješ in ne boš jih posekal, da bi jih uporabil pri obleganju (kajti poljsko drevo je življenje človeku).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Uničil in posekal boš le drevesa, za katera veš, da niso drevesa za hrano. Zoper mesto, ki se bojuje s teboj, boš zgradil branike, dokler ne bo podjarmljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Če je nekdo najden ubit na polju, ki ti ga Gospod, tvoj Bog, daje v last, ležeč na polju in se ne ve kdo ga je umoril,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'potem bodo prišli tvoje starešine in tvoji sodniki in bodo izmerili [razdaljo] do mest, ki so naokoli tega, ki je umorjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Zgodilo se bo, da mesto, ki je bliže umorjenemu človeku, celo starešine tega mesta bodo vzeli telico, s katero še niso delali in ki še ni vlekla jarma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'in starešine tega mesta bodo telico privedli dol v valovito dolino, ki ni niti obdelana niti posejana in tam, v dolini, bodo telici zlomili vrat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'in duhovniki, sinovi Lévijevcev, se bodo približali, kajti njih je Gospod, tvoj Bog, izbral, da mu služijo in da blagoslavljajo v Gospodovem imenu, in po njihovi besedi bo vsaka polemika in vsak udarec preizkušen');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'in vse starešine tega mesta, ki je bliže umorjenemu človeku, si bodo roke umili nad telico, ki je obglavljena v dolini');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'in odgovorili bodo ter rekli: ›Naše roke niso prelile te krvi niti naše oči tega niso videle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Bodi usmiljen, oh Gospod, svojemu ljudstvu Izraelu, ki si ga odkupil in ne polagaj nedolžne krvi na svoje ljudstvo Izrael, ki je najbliže.‹ In kri jim bo odpuščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Tako boš izmed sebe odvzel krivdo nedolžne krvi, ko boš storil to, kar je pravilno v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Ko greš naprej v vojno zoper svoje sovražnike in ti jih Gospod, tvoj Bog, izroči v tvoje roke in si jih zajel kot ujetnike');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'in vidiš med ujetniki lepo žensko in imaš do nje poželenje, da bi jo imel za svojo ženo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'potem jo boš privedel domov, v svojo hišo. Ona si bo obrila svojo glavo in postrigla svoje nohte');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'in iz sebe bo odložila oblačila svojega ujetništva in ostala bo v tvoji hiši in cel mesec bo objokovala svojega očeta in svojo mater. Potem boš šel noter k njej in boš njen soprog in ona bo tvoja žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'In zgodilo se bo, če z njo ne boš imel veselja, potem jo boš pustil oditi kamor ona hoče. Toda, ker si jo ponižal, je nikakor ne boš prodal za denar, iz nje ne boš naredil trgovskega blaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Če ima mož dve ženi, eno ljubljeno in drugo osovraženo in sta mu rodili otroke, obe, ljubljena in osovražena in če je prvorojenec od tiste, ki je bila osovražena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'potem se bo zgodilo, ko daje svojim sinovom podedovati to, kar ima, da ne sme narediti sina ljubljene prvorojenca pred sinom osovražene, ki je zares prvorojenec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'temveč bo sina osovražene priznal za prvorojenca s tem, da mu da dvojni delež od vsega, kar ima, kajti on je začetek njegove moči; pravica prvorojenca je njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Če ima človek trmoglavega in upornega sina, ki noče ubogati glasu svojega očeta ali glasu svoje matere in ko sta ga karala, da ju noče poslušati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'potem naj ga njegov oče in njegova mati primeta in ga privedeta k starešinam njegovega mesta in k velikim vratom njegovega kraja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'in starešinam mesta bosta rekla: ›Ta najin sin je trmoglav in uporen, noče ubogati najinega glasu. Požeruh je in pijanec.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'In vsi ljudje iz njegovega mesta ga bodo kamnali s kamni, da ta umre. Tako boš zlo odstranil proč izmed vas in ves Izrael bo slišal in se bal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Če je moški zagrešil greh, vreden smrti, in bo usmrčen in ga obesiš na drevo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'naj njegovo truplo ne ostane vso noč na drevesu, temveč ga boš vsekakor tisti dan pokopal (kajti ta, ki je obešen, je preklet od Boga), da tvoja dežela, ki ti jo Gospod, tvoj Bog, daje za dediščino, ne bo omadeževana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Vola svojega brata ali njegovo ovco ne boš gledal zaiti in se skril pred njimi. V vsakem primeru jih boš ponovno privedel k svojemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Če tvoj brat ni blizu tebe ali če ga ne poznaš, potem jo boš privedel v svojo lastno hišo in ta bo s teboj, dokler je tvoj brat ne gre iskat in mu jo boš ponovno vrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Na podoben način boš storil z njegovim oslom in tako boš storil z njegovim oblačilom in z vsemi izgubljenimi stvarmi svojega brata, ki jih je izgubil in si jih našel, boš podobno storil. Ne smeš se skriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Osla svojega brata ali njegovega vola ne boš gledal pasti dol ob poti in se skril pred njima. Zagotovo mu boš pomagal, da jih ponovno dvigne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ženska ne bo nosila tega, kar pripada moškemu niti moški ne bo oblekel ženskega oblačila, kajti vsi, ki tako delajo, so ogabnost Gospodu, tvojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Če se ptičje gnezdo znajde pred teboj na poti, na kateremkoli drevesu ali na tleh, bodisi so mladiči ali jajca in mati sedi na mladičih ali na jajcih, ne boš vzel samice z mladiči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'temveč boš vsekakor pustil mater oditi in k sebi vzel mlade, da bo lahko dobro s teboj in da lahko podaljšaš svoje dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Ko gradiš novo hišo, potem boš naredil obzidek za svojo streho, da nad svojo hišo ne privedeš krvi, če katerikoli mož pade od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, '§ Svojega vinograda ne boš sejal z različnimi semeni, da ne bi bil sad tvojega semena, ki si ga posejal in sad vinograda omadeževan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Ne boš oral z volom in oslom skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Ne boš nosil obleke različnih vrst, kakor iz volne in lanu, skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Sebi boš naredil rese na štirih četrtinah svoje suknje, s katero se pokrivaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Če katerikoli moški vzame ženo in gre noter k njej in jo zasovraži');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'in da priložnost za opravljanje zoper njo in nadnjo privede zlo ime ter reče: ›Vzel sem to žensko in ko sem prišel k njej, je nisem našel device,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'potem bosta oče gospodične in njena mati vzela in k starešinam v mestnih velikih vratih prinesla znamenja devištva gospodične');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'in oče gospodične bo starešinam rekel: ›Svojo hčer sem dal temu možu za ženo, ta pa jo sovraži');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'in glejte, dal je priložnosti za opravljanje zoper njo, rekoč: ›Tvoje hčere nisem našel device.‹ Vendar so to znamenja devištva moje hčere.‹ In obleko bosta razgrnila pred starešinami mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'In starešine tega mesta bodo vzele tega moškega in ga kaznovale');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'in kaznovali ga bodo s sto šekli srebra in jih dali očetu gospodične, ker je nad Izraelovo devico privedel zlo ime in ona bo njegova žena vse svoje dni. Ne sme je odsloviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Toda če je ta stvar resnična in simboli devištva za gospodično niso bili najdeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'potem bo gospodično privedel ven k vratom hiše njenega očeta in ljudje iz njenega mesta jo bodo kamnali s kamni, da ta umre. Ker je storila neumnost v Izraelu, da igra vlačugo v hiši svojega očeta. Tako boš izmed vas odstranil zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Če je moški najden, da leži z žensko, poročeno s soprogom, potem bosta oba umrla, oba, tako moški, ki je ležal z žensko, in ženska. Tako boš zlo odstranil iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Če je gospodična, ki je devica, zaročena k soprogu in jo moški najde v mestu in leži z njo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'potem boš oba privedel ven, k velikim vratom tega mesta in kamnali ju boste s kamenjem, da umreta. Gospodično, ker ni kričala, kljub temu, da je bila v mestu in moškega, ker je ponižal ženo svojega bližnjega. Tako boš izmed sebe odstranil zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Toda če moški najde zaročeno gospodično na polju in jo moški prisili in leži z njo, potem naj umre samo moški, ki je ležal z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Toda gospodični ne boš ničesar storil. Tam, na gospodični, ni nobenega greha, vrednega smrti, kajti kakor ko se moški vzdiguje zoper svojega bližnjega in ga ubije, celo takšna je ta zadeva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'kajti našel jo je na polju in zaročena gospodična je vpila, pa ni bilo nikogar, da jo reši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Če moški najde gospodično, ki je devica, ki ni zaročena in jo prime in leži z njo in ju najdejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'tedaj naj moški, ki je ležal z njo, očetu od gospodične izroči petdeset šeklov srebra in ona bo njegova žena; ker jo je ponižal, je vse svoje dni ne sme odsloviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Mož ne bo vzel žene svojega očeta niti odkril krajca očetovega oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Kdor je ranjen v modih ali ima odrezan ud, ne bo vstopil v Gospodovo skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Mešanec ne bo vstopil v Gospodovo skupnost. Celo do njegovega desetega rodu ne bo vstopil v Gospodovo skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Amónec ali Moábec ne bosta vstopila v Gospodovo skupnost. Celo do njunega desetega rodu ne bosta vstopila v Gospodovo skupnost na veke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'ker vas niso srečali s kruhom in vodo na poti, ko ste izšli iz Egipta in ker so zoper tebe najeli Beórjevega sina Bileáma iz Petórja v Mezopotamiji, da te prekolne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Kljub temu Gospod, tvoj Bog, ni hotel prisluhniti Bileámu, temveč ti je Gospod, tvoj Bog, prekletstvo obrnil na blagoslov, ker te je Gospod, tvoj Bog, ljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Vse svoje dni na veke ne boš iskal njihovega miru niti njihovega uspevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Ne boš preziral Edómca, kajti on je tvoj brat. Ne boš preziral Egipčana, kajti tujec si bil v njegovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Otroci, ki so rojeni od njih, bodo v Gospodovo skupnost vstopili v svojem tretjem rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Ko gre vojska naprej, zoper tvoje sovražnike, potem se varuj pred vsako zlobno stvarjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Če je med vami kakršenkoli moški, ki ni čist zaradi razloga nečistosti, ki se mu pripeti ponoči, potem se bo ločil ven iz tabora, ne bo prišel znotraj tabora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Temveč bo tako, ko prihaja večer, da se bo umil z vodo, in ko sonce zaide, bo ponovno prišel v tabor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Imel boš tudi kraj zunaj tabora, kamor boš šel, da se oddvojiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Na svojem orožju boš imel lopatico in zgodilo se bo, ko se boš zunaj olajšal, boš s tem kopal in se obrnil nazaj in pokril to, kar pride od tebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'kajti Gospod, tvoj Bog, hodi v sredi tvojega tabora, da te reši in da pred teboj izroči tvoje sovražnike. Zato bo tvoj tabor svet, da on v tebi ne vidi nobene nečiste stvari in se ne odvrne od tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Služabnika, ki je pred svojim gospodarjem pobegnil k tebi, ne boš izročil njegovemu gospodarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Prebival bo s teboj, torej med vami, na tistem kraju, ki ga bo izbral, v enih izmed tvojih velikih vrat, kjer mu je najbolj všeč. Ne boš ga zatiral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Tam ne bo nobene vlačuge izmed Izraelovih hčera niti posvečenega vlačugarja med Izraelovimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ne boš prinesel najemnine vlačuge ali pasjega plačila v hišo Gospoda, svojega Boga, za kakršnokoli prisego, kajti celo oboje je ogabnost Gospodu, tvojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Svojemu bratu ne boš posojal za obresti; obresti od denarja, obresti od živeža, obresti od katerekoli stvari, ki je posojena za obresti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Tujcu lahko posodiš za obresti, toda svojemu bratu ne boš posojal za obresti, da te Gospod, tvoj Bog, lahko blagoslovi v vsem, česar se loti tvoja roka v deželi, kamor greš, da jo vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Ko boš zaobljubil zaobljubo Gospodu, svojemu Bogu, se ne boš obiral, da to plačaš, kajti Gospod, tvoj Bog, bo to zagotovo zahteval od tebe in to bi bil greh v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Toda če opustiš, da se zaobljubiš, potem v tebi ne bo greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'To, kar je odšlo iz tvojih ustnic, boš ohranjal in izvêdel, celó prostovoljno daritev, glede na to, kot si zaobljubil Gospodu, svojemu Bogu, kar si zaobljubil s svojimi usti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ko prideš v vinograd svojega bližnjega, potem lahko na svojo lastno željo do sitega ješ grozdje, toda nobenega ne boš položil v svojo posodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Ko prideš v stoječe žito svojega bližnjega, potem lahko s svojo roko trgaš klasje, toda s srpom ne boš zamahnil v stoječe žito svojega bližnjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Kadar si moški vzame ženo in jo poroči in se pripeti, da ona ne najde naklonjenosti v njegovih očeh, ker je v njej našel nekaj nečistega, potem naj ji napiše ločitveni list in ji ga da v roko in jo pošlje ven iz svoje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Ko je odšla iz njegove hiše, lahko gre in postane žena drugega moškega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Če jo zadnji mož sovraži in ji napiše ločitveni list in ji ga da v roko in jo pošlje ven iz svoje hiše, ali če zadnji soprog, ki jo je vzel, da bi bila njegova žena, umre,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'je njen prejšnji soprog, ki jo je poslal proč, ne sme ponovno vzeti, da bi bila njegova žena, potem ko je omadeževana, kajti to je ogabnost pred Gospodom in ti deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, ne boš povzročil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Ko si je mož vzel novo ženo, ne bo šel ven na vojno niti ne bo obremenjen s kakršnimkoli poslom, temveč bo eno leto doma svoboden in bo razveseljeval svojo ženo, ki jo je vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Noben človek ne bo za jamstvo vzel spodnji ali zgornji mlinski kamen, kajti za jamstvo jemlje človeško življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Če je mož najden, da krade kateregakoli izmed svojih bratov, Izraelovih otrok in iz njega dela trgovsko blago ali ga proda, potem bo ta tat umrl, in ti boš izmed vas iztrebil zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Pazi na nadlogo gobavosti, da marljivo obeležuješ in delaš glede na vse, kar te bodo Lévijevci učili. Kakor sem jim zapovedal tako boste vi obeleževali, da delate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Spominjaj se, kaj je Gospod, tvoj Bog, storil Mirjam na poti potem, ko ste izšli iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Kadar karkoli posodiš svojemu bratu, ne boš šel v njegovo hišo, da bi dobil svoje jamstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Stal boš zunaj in mož, ki si mu posodil, bo jamstvo prinesel ven k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Če je mož reven, ne boš spal z njegovim jamstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'V vsakem primeru mu boš ponovno izročil jamstvo, ko sonce zaide, da bo lahko spal v svojem lastnem oblačilu in te blagoslovil in to ti bo pravičnost pred Gospodom, tvojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Ne boš zatiral najetega služabnika, ki je reven in pomoči potreben, bodisi je od tvojih bratov ali od tvojih tujcev, ki so v tvoji deželi, znotraj tvojih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Na njegov dan mu boš dal njegovo najemnino niti ne bo sonce zašlo nad le-to, kajti on je reven in nanjo naravnava svoje srce, da ne bi zoper tebe klical h Gospodu in bi bil tebi to greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Očetje ne bodo usmrčeni zaradi otrok niti ne bodo otroci usmrčeni zaradi očetov. Vsak mož bo usmrčen za svoj greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Ne boš izkrivljal sodbe tujcu niti siroti niti za jamstvo ne jemlji vdovinega oblačila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'temveč se boš spominjal, da si bil suženj v Egiptu in Gospod, tvoj Bog, te je odkupil od tam. Zato ti zapovedujem, da to stvar storiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Ko na svojem polju požanješ svojo žetev in si snop pozabil na polju, ne boš ponovno šel, da ga vzameš. Ta bo za tujca, siroto in vdovo, da te Gospod, tvoj Bog, lahko blagoslovi pri vsem delu tvojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kadar klatiš svojo oljko, ne boš ponovno šel preko vej. To bo za tujca, siroto in vdovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kadar nabiraš grozdje iz svojega vinograda, ne boš kasneje paberkoval. To bo za tujca, siroto in vdovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Spominjal se boš, da si bil suženj v egiptovski deželi, zato ti zapovedujem, da to stvar storiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Če je polemika med ljudmi in pridejo na sodbo, da bi jim sodniki lahko sodili, potem bodo opravičili pravičnega in obsodili zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Zgodilo se bo, če bo zloben človek vreden, da bi bil pretepen, da mu bo sodnik povzročil, da se uleže in da bo z določenim številom udarcev pretepen pred njegovim obrazom, glede na njegovo krivdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Štirideset udarcev mu lahko naloži in ne več, da se ti tvoj brat ne bi zdel onečaščen, če bi prekoračil in ga pretepel z mnogimi udarci nad temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ne boš zavezal gobca volu, kadar mane žito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Če bratje prebivajo skupaj in eden izmed njih umre in nima otroka, se žena mrtvega ne bo poročila zunaj, s tujcem. Njen svak bo šel noter k njej in jo vzel k sebi za ženo in ji izpolnil dolžnost soprogovega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Zgodilo se bo, da bo prvorojenec, ki ga ona rodi, nasledil ime njegovega brata, ki je mrtev, da njegovo ime ne bo izbrisano iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Če pa mož ne mara vzeti svakinje, potem naj gre žena njegovega brata gor k velikim vratom do starešin in reče: ›Brat mojega soproga odklanja, da bi svojemu bratu vzdignil ime v Izraelu; noče izpolniti dolžnosti brata mojega soproga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Potem ga bodo starešine njegovega mesta poklicali in mu govorili. Če pa se temu zoperstavi in reče: ›Ne maram je vzeti,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'potem bo žena njegovega brata prišla k njemu v prisotnosti starešin in sezula njegov čevelj iz njegovega stopala in pljunila v njegov obraz in odgovorila ter rekla: ›Tako bo storjeno tistemu možu, ki noče graditi hiše svojega brata.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Njegovo ime bo v Izraelu imenovano: ›Hiša tistega, ki je sezut.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Kadar se možje skupaj prepirajo drug z drugim in se žena enega približa, da bi svojega soproga osvobodila iz roke tistega, ki ga udarja in iztegne svojo roko, da ga zgrabi za njegove genitalije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'potem boš odsekal njeno roko, tvoje oko se je ne bo usmililo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'V svoji torbi ne boš imel različnih uteži, velike in male.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'V svoji hiši ne boš imel različnih mer, velike in male.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Temveč boš imel popolno in pravično utež, popolno in pravično mero boš imel, da bodo tvoji dnevi lahko podaljšani v deželi, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Kajti vsi, ki počno takšne stvari, in vsi, ki počno nepravično, so ogabnost Gospodu, tvojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Spomni se kaj ti je po poti storil Amálek, ko ste izšli iz Egipta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kako te je srečal po poti in udaril najbolj zadnje od tebe, torej vse, kar je bilo slabotno za teboj, ko si bil ti slaboten in utrujen, on pa se ni bal Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Zato bo, ko ti bo Gospod, tvoj Bog, dal počitek pred vsemi tvojimi sovražniki naokoli, v deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, da jo vzameš v last, da boš izpod neba izbrisal spomin na Amáleka. Tega ne boš pozabil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Zgodilo se bo, ko prideš v deželo, ki ti jo v dediščino daje Gospod, tvoj Bog, in jo vzameš v last in v njej prebivaš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'da boš vzel od prvega izmed vseh sadov zemlje, ki jih boš prinesel iz svoje dežele, ki ti jo daje Gospod, tvoj Bog in boš to položil v košaro in boš šel na kraj, ki ga bo izbral Gospod, tvoj Bog, da tam postavi svoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Šel boš k duhovniku, ki bo v tistih dneh ter mu rekel: ›Ta dan izpovedujem Gospodu, tvojemu Bogu, da sem prišel v deželo, ki jo je Gospod prisegel našim očetom, da nam jo da.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Duhovnik bo iz tvoje roke vzel košaro in jo postavil dol pred oltar Gospoda, tvojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Govoril boš in pred Gospodom, svojim Bogom, rekel: ›Moj oče je bil Sirec, pripravljen, da umre in odšel je dol v Egipt in tam začasno prebival s peščico in tam postal narod, velik, mogočen in gosto naseljen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Egipčani pa so z nami postopali zlobno in nas prizadeli in na nas položili trdo suženjstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Ko smo klicali h Gospodu, Bogu svojih očetov, je Gospod slišal naš glas in pogledal na našo stisko in naš trud in naše zatiranje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'in Gospod nas je iz Egipta izpeljal z mogočno roko, z iztegnjenim laktom, z veliko strahoto, z znamenji in čudeži');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'in nas privedel na ta kraj in nam dal to deželo, celó deželo, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Sedaj glej, prinesel sem prve sadove dežele, ki si jo ti, oh Gospod, dal meni.‹ To boš postavil pred Gospoda, svojega Boga in oboževal boš pred Gospodom, svojim Bogom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'in veselil se boš v vsaki dobri stvari, ki jo je Gospod, tvoj Bog, dal tebi in tvoji hiši, ti in Lévijevec in tujec, ki je med vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Ko si končal desetinjenje vseh desetin svojega narasta v tretjem letu, ki je leto desetinjenja in si to dal Lévijevcu, tujcu, siroti in vdovi, da lahko jedo znotraj tvojih velikih vrat in so nasičeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'potem boš rekel pred Gospodom, svojim Bogom: ›Odnesel sem posvečene stvari iz svoje hiše in jih prav tako izročil Lévijevcu, tujcu, siroti in vdovi, glede na vse tvoje zapovedi, ki si mi jih zapovedal. Nisem prekršil tvojih zapovedi niti jih nisem pozabil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'V svojem žalovanju nisem jedel od tega, niti nisem vzel proč česarkoli za kakršnokoli nečisto uporabo, niti nisem dal karkoli od tega za mrtvega, temveč sem prisluhnil glasu Gospoda, svojega Boga in storil glede na vse, kar si mi zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Poglej navzdol iz svojega svetega prebivališča, iz nebes in blagoslovi svoje ljudstvo Izrael in deželo, ki si nam jo dal, kakor si prisegel našim očetom, deželo, kjer tečeta mleko in med.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Ta dan ti je Gospod, tvoj Bog, zapovedal, da izpolnjuješ te zakone in sodbe. Ti jih boš torej ohranjal in izvrševal z vsem svojim srcem in z vso svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Ta dan si govoril Gospodu, da bi bil tvoj Bog in da bi hodil po njegovih poteh, ohranjal njegove zakone, njegove zapovedi, njegove sodbe in da bi prisluhnil njegovemu glasu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'in Gospod ti je ta dan odgovoril, da bi bil njegovo izvoljeno ljudstvo, kakor ti je obljubil in da bi varoval vse njegove zapovedi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'in da bi te naredil višjega nad vsemi narodi, ki jih je naredil, v hvali, v imenu, v časti in da bi bil lahko sveto ljudstvo Gospodu, svojemu Bogu, kakor je govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Mojzes je z Izraelovimi starešinami ljudstvu zapovedal, rekoč: »Ohranjajte vse zapovedi, ki vam jih ta dan zapovedujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'In zgodilo se bo na dan, ko boste čez Jordan prečkali v deželo, ki ti jo daje Gospod, tvoj Bog, da si boš postavil velike kamne in jih pobelil z apnom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'in nanje boš zapisal vse besede te postave, ko si prečkal, da si lahko vstopil v deželo, ki ti jo daje Gospod, tvoj Bog, deželo, kjer tečeta mleko in med, kakor ti je obljubil Gospod, Bog tvojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Zatorej bo, ko boste odšli čez Jordan, da boste postavili te kamne, ki sem vam jih zapovedal ta dan, na gori Ebál in jih pobelili z apnom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Tam boš zgradil oltar Gospodu, svojemu Bogu, oltar iz kamnov. Nobenega železnega orodja ne boš dvignil nadnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Iz celih kamnov boš zgradil oltar Gospodu, svojemu Bogu in na njem boš daroval žgalne daritve Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Daroval boš mirovne daritve in tam boš jedel in se veselil pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Na kamne boš zelo jasno napisal vse besede te postave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Mojzes in duhovniki, Lévijevci, so vsemu Izraelu spregovorili, rekoč: »Pazi in prisluhni, oh Izrael. Ta dan si postal ljudstvo Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Ubogal boš torej glas Gospoda, svojega Boga in izvrševal njegove zapovedi in njegove zakone, ki ti jih ta dan zapovedujem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Mojzes je ta isti dan ljudstvu naročil, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '»Ti bodo stali na gori Garizím, da blagoslovijo ljudstvo, ko pridete čez Jordan: Simeon, Levi, Juda, Isahár, Jožef in Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'In ti bodo stali na gori Ebál, da preklinjajo: Ruben, Gad, Aser, Zábulon, Dan in Neftáli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Lévijevci bodo z močnim glasom govorili in rekli vsem Izraelovim možem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '›Preklet bodi mož, ki dela kakršnokoli rezano ali ulito podobo, ogabnost Gospodu, delo rok rokodelca in jo postavi na skrit kraj.‹ In vse ljudstvo bo odgovorilo in reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '›Preklet bodi kdor prezira svojega očeta ali svojo mater.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '›Preklet bodi, kdor odstranja mejnik svojega bližnjega.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '›Preklet bodi, kdor slepega pripravi, da zaide iz poti.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '›Preklet bodi, kdor izkrivlja sodbo tujca, sirote in vdove.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '›Preklet bodi, kdor leži z ženo svojega očeta, ker je odkril krajec očetovega oblačila.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '›Preklet bodi, kdor leži s katerokoli vrsto živali.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '›Preklet bodi, kdor leži s svojo sestro, hčerjo svojega očeta ali hčerjo svoje matere.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '›Preklet bodi, kdor leži s svojo taščo.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '›Preklet bodi, kdor na skrivnem udarja svojega bližnjega.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '›Preklet bodi, kdor jemlje nagrado, da ubije nedolžno osebo.‹ In vse ljudstvo bo reklo: ›Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '›Preklet bodi, kdor ne potrjuje vseh besed te postave, da bi jih izpolnjeval.‹ In vse ljudstvo bo reklo: ›Amen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Zgodilo se bo, če boš marljivo prisluhnil glasu Gospoda, svojega Boga, da obeležuješ in da izpolnjuješ vse njegove zapovedi, ki sem ti jih zapovedal ta dan, da te bo Gospod, tvoj Bog, postavil visoko, nad vse narode zemlje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'in vsi ti blagoslovi bodo prišli nadte in te dosegli, če boš prisluhnil glasu Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Blagoslovljen boš v mestu in blagoslovljen boš na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Blagoslovljen bo sad tvojega telesa in sad tvojih tal in sad tvoje živine, prireja tvojega goveda in tropov tvojih ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Blagoslovljena bo tvoja košara in tvoja shramba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Blagoslovljen boš, ko prihajaš in blagoslovljen boš, ko odhajaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Gospod bo tvojim sovražnikom, ki se dvignejo zoper tebe, povzročil da bodo udarjeni pred tvojim obrazom. Zoper tebe bodo prišli po eni poti, pred teboj bodo pobegnili po sedmih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Gospod bo zapovedal blagoslov nad teboj v tvojih skladiščih in vsemu temu, česar se loti tvoja roka, in blagoslovil te bo v deželi, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Gospod te bo utrdil sebi za sveto ljudstvo, kakor ti je prisegel, če boš ohranjal zapovedi Gospoda, svojega Boga in hodil po njegovih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Vse ljudstvo zemlje bo videlo, da si imenovan po Gospodovem imenu in se te bodo bali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Gospod te bo storil obilnega v dobrinah, v sadu tvojega telesa in v prireji tvoje živine in v sadu tvojih tal, v deželi, ki jo je Gospod prisegel tvojim očetom, da ti jo da.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Gospod ti bo odprl svojo dobro zakladnico, nebo, da daje dež tvoji deželi v svojem obdobju in da blagoslovi vse delo tvoje roke in posojal boš mnogim narodom, ti pa si ne boš izposojal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Gospod te bo naredil za glavo in ne za rep. Ti boš samo zgoraj in ne boš spodaj, če boš prisluhnil zapovedim Gospoda, svojega Boga, ki sem ti jih zapovedal ta dan, da jih obeležuješ in izpolnjuješ');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'in ne boš šel stran od katerekoli izmed besed, ki sem ti jih ta dan zapovedal, ne k desni roki ne k levi, da bi šel za drugimi bogovi, da jim služiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Temveč se bo zgodilo, če ne boš prisluhnil glasu Gospoda, svojega Boga, da obeležuješ izvrševati vse njegove zapovedi in njegove zakone, ki sem ti jih ta dan zapovedal, da bodo nadte prišla vsa ta prekletstva in te dohitela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Preklet boš v mestu in preklet boš na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Preklet bo tvoj koš in tvoja shramba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Preklet bo sad tvojega telesa in sad tvoje dežele, prirast tvojega goveda in tropov tvojih ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Preklet boš, ko prihajaš in preklet boš, ko odhajaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Gospod bo nadte poslal prekletstvo, draženje in grajo v vsem, česar se lotiš s svojo roko, da bi storil, dokler ne boš uničen in dokler hitro ne premineš; zaradi zlobnosti svojih dejanj, s katerimi si me zapustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Gospod bo storil, da se te bo trdno oklenila kužna bolezen, dokler te ne použije iz dežele, kamor greš, da jo vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Gospod te bo udaril s sušico, z vročino, z vnetjem in z izjemno vročico, z mečem, s kvarjenjem in s plesnijo; in preganjale te bodo, dokler ne premineš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Tvoje nebo, ki je nad tvojo glavo, bo bron in zemlja, ki je pod teboj, bo železo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Gospod bo dež tvoje dežele spremenil v prašek in prah. Z neba bo padal nadte, dokler ne boš uničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Gospod ti bo povzročil, da boš udarjen pred svojimi sovražniki. Po eni poti boš šel ven zoper njih in po sedmih poteh boš bežal pred njimi in odstranjen boš v vsa kraljestva zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Tvoje truplo bo hrana vsej perjadi neba in zemeljskim živalim in noben človek jih ne bo odganjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Gospod te bo udaril z egiptovskimi mehurji, s hemoroídi, s krasto in s srbečico, od katerih ne moreš biti ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Gospod te bo udaril z norostjo, slepoto in osuplostjo srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Opoldan boš tipal, kakor slepi tipa v temi in ne boš uspeval na svojih poteh in vselej boš samo zatiran in plenjen in noben človek te ne bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Zaročil boš žensko, z njo pa bo ležal drug moški. Zgradil boš hišo, pa ne boš prebival v njej. Zasadil boš vinograd, pa ne boš obiral njegovega grozdja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Tvoj vol bo zaklan pred tvojimi očmi, pa od njega ne boš jedel. Tvoj osel bo nasilno vzet izpred tvojega obraza, pa ne bo povrnjen k tebi. Tvoje ovce bodo dane tvojim sovražnikom in nikogar ne boš imel, da jih reši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tvoji sinovi in tvoje hčere bodo izročeni drugemu ljudstvu in tvoje oči bodo gledale in s hrepenenjem ves dan koprnele po njih, pa v tvoji roki ne bo nobene moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Sad tvoje dežele in vse tvoje trude bo narod, ki ga ne poznaš, požrl in ti boš vedno samo zatiran in zdrobljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Tako da boš besen zaradi prizora svojih oči, ki ga boš videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Gospod te bo v kolenih in v nogah udaril z bolečimi mehurji, ki ne morejo biti ozdravljeni, od podplata tvojega stopala do vrha tvoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Gospod in tvoj kralj, ki si ga boš postavil nadse, te bo privedel k narodu, ki ga nisi poznal niti ti niti tvoji očetje in tam boš služil drugim bogovom, lesu in kamnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Postal boš osuplost, pregovor in tarča posmeha med vsemi narodi, kamor te bo vodil Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Na polje boš nosil obilje semena, zbral pa ga boš le malo, kajti to bo požrla leteča kobilica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Sadil boš vinograde in jih obrezoval, toda niti ne boš pil od vina, niti nabiral grozdja, kajti ličinke jih bodo pojedle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Po vseh svojih pokrajinah boš imel oljke, toda sebe ne boš mazilil z oljem, ker bodo tvoje oljke odvrgle svoj sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Zaplodil boš sinove in hčere, toda ne boš jih užival, ker bodo šli v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Vsa tvoja drevesa in sad tvoje dežele bo požrla leteča kobilica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Tujec, ki je znotraj tebe, se bo zelo visoko povzpel nadte, ti pa se boš spustil zelo nizko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Posojal ti bo, ti pa njemu ne boš posojal. On bo glava, ti pa rep.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Poleg tega bodo nadte prišla vsa ta prekletstva in te zasledovala in dosegla, dokler ne boš uničen, ker nisi prisluhnil glasu Gospoda, svojega Boga, da ohranjaš njegove zapovedi in njegove zakone, ki ti jih je zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Ta bodo na tebi za znamenje in za čudo in nad tvojim semenom na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Ker zaradi obilja vseh stvari nisi služil Gospodu, svojemu Bogu, z radostjo in z veseljem srca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'zato boš služil svojim sovražnikom, ki jih bo Gospod poslal zoper tebe, v lakoti, v žeji, v nagoti in v pomanjkanju vseh stvari in na tvoj vrat bo položil železen jarem, dokler te ne uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Gospod bo zoper tebe od daleč privedel narod, od konca zemlje, tako naglo, kakor leti orel. Narod, katerega jezika ne boš razumel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'narod krutega obličja, ki se ne bo oziral na osebo starca niti mladim izkazoval naklonjenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Jedel bo sad tvoje živine in sad tvoje dežele, dokler ne boš uničen, ki ti tudi ne bo pustil niti žita, vina ali olja ali prirasta tvojega goveda ali tropov tvojih ovc, dokler te ne uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Oblegal te bo v vseh tvojih velikih vratih, dokler se tvoji visoki in mogočni utrjeni zidovi, v katere si zaupal, ne zrušijo po vsej tvoji deželi in oblegal te bo v vseh tvojih velikih vratih, po vsej tvoji deželi, ki ti jo je dal Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Jedel boš sad svojega lastnega telesa, meso svojih sinov in svojih hčera, ki ti jih je dal Gospod, tvoj Bog, ob obleganju in v tesnobi, s katero te bodo stiskali tvoji sovražniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'tako da bo oko moža, ki je med vami nežen in zelo prefinjen, hudobno proti svojemu bratu in proti ženi svojega naročja in proti preostanku svojih otrok, ki jih bo pustil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'tako da nikomur izmed njih ne bo dal mesa svojih otrok, ki jih bo jedel, ker mu ob obleganju in v tesnobi, s katero te bodo stiskali tvoji sovražniki in vznemirjali v vseh tvojih velikih vratih, ničesar ne bo preostalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Oko nežne in prefinjene ženske med vami, ki zaradi prefinjenosti in nežnosti ne bi niti poskusila postaviti podplata svojega stopala na tla, bo hudobno napram soprogu svojega naročja in napram svojemu sinu in napram svoji hčeri');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'in napram svojemu otročičku, ki pride ven izmed njenih stopal in napram svojim otrokom, ki jih bo nosila, kajti na skrivaj jih bo jedla zaradi pomanjkanja vseh stvari, ob obleganju in tesnobi, s katero te bo tvoj sovražnik stiskal znotraj tvojih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Če ne boš obeleževal, da storiš vse besede te postave, ki so zapisane v tej knjigi, da bi se lahko bal tega slavnega in strašnega imena, GOSPODA, SVOJEGA BOGA,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'tedaj bo Gospod naredil tvoje nadloge in nadloge tvojega semena težke, celó velike nadloge in dolgo trajajoče in boleče bolezni in dolgo trajajoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Poleg tega bo nadte privedel vse egiptovske bolezni, ki si se jih bal in te se te bodo trdno držale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Prav tako vsako bolezen in vsako nadlogo, ki ni zapisana v knjigi te postave, tudi te bo Gospod privedel nadte, dokler ne boš uničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Vas pa bo ostalo le malo po številu, medtem ko vas je bilo zaradi množice kakor zvezd neba, ker nisi hotel ubogati glasu Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Zgodilo se bo, da kakor se je Gospod nad vami veselil, da vam stori dobro in vas množi, tako se bo Gospod nad vami veselil, da vas uniči in da vas privede v nič in vi boste izruvani iz dežele, kamor greš, da jo vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Gospod te bo razkropil med vsa ljudstva, od enega konca zemlje, celo do drugega in tam boš služil drugim bogovom, ki jih nisi poznal ne ti ne tvoji očetje, celó lesu in kamnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Med tistimi narodi ne boš našel nobenega olajšanja niti podplat tvojega stopala ne bo imel počitka, temveč ti bo tam Gospod dal trepetajoče srce, pešajoče oči in umsko bolest');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'in tvoje življenje bo pred teboj viselo v dvomu in bal se boš podnevi in ponoči in nobene gotovosti svojega življenja ne boš imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Zjutraj boš rekel: »Da bi Bog dal, da bi bil večer!« In zvečer boš rekel: »Da bi Bog dal, da bi bilo jutro!« Zaradi strahu svojega srca, s katerim se boš bal, in zaradi pogleda svojih oči, ki ga boš gledal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Gospod te bo z ladjami ponovno privedel v Egipt, po poti, o kateri sem ti govoril: »Ne boš je več videl.« Tam boste prodani svojim sovražnikom za sužnje in sužnjice in noben mož vas ne bo kupil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'To so besede zaveze, ki jo je Gospod zapovedal Mojzesu, da jo z Izraelovimi otroki sklene v moábski deželi, poleg zaveze, ki jo je z njimi sklenil na Horebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Mojzes je klical vsemu Izraelu in jim rekel: »Videli ste vse, kar je Gospod storil pred vašimi očmi v egiptovski deželi faraonu in vsem njegovim služabnikom in vsej njegovi deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'velike preizkušnje, ki so jih videle tvoje oči, znamenja in tiste velike čudeže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Vendar vam Gospod do tega dne ni dal srca, da zaznate, oči, da vidite in ušesa, da slišite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Jaz sem vas štirideset let vodil po divjini. Vaša oblačila se na vas niso postarala in tvoj čevelj na tvojem stopalu se ni postaral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Niste jedli kruha niti pili vina ali močne pijače, da bi lahko spoznali, da jaz sem Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'In ko ste prišli na ta kraj, sta Sihón, kralj v Hešbónu in bašánski kralj Og, prišla ven zoper nas v bitko in mi smo ju udarili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Zavzeli smo njuno deželo in jo izročili v dediščino Rubenovcem, Gádovcem in polovici Manásejevega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Varujte torej besede te zaveze in jih izvršujte, da boste lahko uspevali v vsem svojem delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vsi izmed vas ta dan stojite pred Gospodom, vašim Bogom: vaši poveljniki vaših rodov, vaše starešine in vaši častniki, z vsemi Izraelovimi možmi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'vaši malčki, vaše žene in tvoj tujec, ki je v tvojem taboru, od sekalca tvojega lesa, do prinašalca tvoje vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'da bi vstopil v zavezo z Gospodom, svojim Bogom in v njegovo prisego, ki jo je Gospod, tvoj Bog, ta dan sklenil s teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'da bi te ta dan lahko osnoval za svoje ljudstvo in da bi ti bil on lahko Bog, kakor ti je rekel in kakor je prisegel tvojim očetom, Abrahamu, Izaku in Jakobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Niti te zaveze in te prisege ne sklepam samo s teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'temveč s tistim, ki ta dan stoji tukaj z nami pred Gospodom, svojim Bogom in tudi s tistim, ki ga ta dan ni tukaj z nami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, '(kajti veste, kako smo prebivali v egiptovski deželi in kako smo prišli skozi narode, mimo katerih ste šli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'in ste videli njihove ogabnosti in njihove malike, les in kamen, srebro in zlato, ki so bili med njimi)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'da ne bi bilo med vami moža ali ženske ali družine ali rodu, katerega srce se ta dan obrača od Gospoda, našega Boga, da gre in služi bogovom teh narodov, da ne bi bilo med vami korenine, ki obrodi žolč in pelin');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'in zgodi se, ko sliši besede tega prekletstva, da se blagoslovi v svojem srcu, rekoč: ›Imel bom mir, čeprav hodim v zamisli svojega srca, da žeji dodajam pijanost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Gospod mu ne bo prizanesel, temveč se bosta potem Gospodova jeza in njegova ljubosumnost kadili zoper tega človeka in vsa prekletstva, ki so zapisana v tej knjigi, bodo legla nanj in Gospod bo njegovo ime izbrisal izpod neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Gospod ga bo izmed vseh Izraelovih rodov oddvojil v zlo, glede na vsa prekletstva zaveze, ki so zapisana v tej knjigi postave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'tako da bodo rekli prihajajočemu rodu tvojih otrok, ki bodo vstali za vami in tujcu, ki bo prišel iz daljne dežele, ko bodo videli nadloge te dežele in bolezni, ki jih je Gospod položil nanjo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'in da je njegova celotna dežela žveplo, sol in gorenje, da ta ni posejana niti ne vzbrsti niti nobena trava ne raste na njej, kakor razdejanje Sódome, Gomóre, Adme in Cebojíma, ki jih je Gospod uničil v svoji jezi in v svojem besu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Celo vsi narodi bodo rekli: ›Zakaj je Gospod tako storil tej deželi? Kaj pomeni gorenje te velike jeze?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Potem bodo možje rekli: ›Ker so zapustili zavezo Gospoda, Boga svojih očetov, ki jo je z njimi sklenil, ko jih je privedel ven iz egiptovske dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'kajti šli so in služili drugim bogovom in jih oboževali, bogovom, ki jih niso poznali in ki jim jih on ni dal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'in Gospodova jeza je bila vžgana zoper to deželo, da nadnjo privede vsa prekletstva, ki so zapisana v tej knjigi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Gospod jih je v jezi izkoreninil iz njihove dežele, v besu, v velikem ogorčenju in jih vrgel v drugo deželo, kakor je to ta dan.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Skrivne stvari pripadajo Gospodu, našemu Bogu, toda tiste stvari, ki so razodete, pripadajo nam in našim otrokom na veke, da lahko storimo vse besede te postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Zgodilo se bo, ko vse te stvari pridejo nadte, blagoslov in prekletstvo, ki sem ga postavil predte in si jih boš priklical v um med vsemi narodi, kamor te je Gospod, tvoj Bog, pregnal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'in se boš vrnil h Gospodu, svojemu Bogu in ubogal njegov glas glede na vse, kar sem ti ta dan zapovedal, tebi in tvojim otrokom, z vsem svojim srcem in z vso svojo dušo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'da bo potem Gospod, tvoj Bog, obrnil tvoje ujetništvo in imel sočutje nad teboj, in te bo vrnil in zbral od vseh narodov, kamor te je Gospod, tvoj Bog, razkropil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Če bo kdorkoli izmed tvojih izgnan do skrajnih delov neba, te bo od tam zbral Gospod, tvoj Bog in te privedel od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Gospod, tvoj Bog, te bo privedel v deželo, ki so jo tvoji očetje vzeli v last in vzel jo boš v last in storil ti bo dobro in te bolj pomnožil kot tvoje očete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Gospod, tvoj Bog, bo obrezal tvoje srce in srce tvojega semena, da ljubiš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo, da boš lahko živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Gospod, tvoj Bog, bo vsa ta prekletstva položil na tvoje sovražnike in na tiste, ki te sovražijo, ki so te preganjali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Vrnil se boš in ubogal Gospodov glas in izpolnjeval vse njegove zapovedi, ki sem ti jih ta dan zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'In Gospod, tvoj Bog, te bo storil obilnega v vsakem delu tvoje roke, v sadu tvojega telesa, v prireji tvoje živine in v sadu tvoje dežele, tebi v dobro, kajti Gospod se bo, tebi v dobro, ponovno veselil nad teboj, kakor se je veselil nad tvojimi očeti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'če boš prisluhnil glasu Gospoda, svojega Boga, da ohranjaš njegove zapovedi in njegove zakone, ki so zapisani v knjigi te postave in če se obrneš h Gospodu, svojemu Bogu, z vsem svojim srcem in z vso svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Kajti ta zapoved, ki sem ti jo ta dan zapovedal, ta ni skrita pred teboj niti ni daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Ta ni v nebesih, da bi lahko rekel: ›Kdo bo za nas šel gor do nebes in jo privede k nam, da bi jo lahko slišali in izpolnjevali?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Niti to ni prek morja, da bi lahko rekel: ›Kdo bo za nas šel čez morje in jo privede k nam, da bi jo lahko slišali in izpolnjevali?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Temveč je beseda zelo blizu tebe, v tvojih ustih in v tvojem srcu, da jo lahko izpolniš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Poglej, predte sem ta dan postavil življenje in dobro ter smrt in zlo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'v tem, da sem ti ta dan zapovedal, da ljubiš Gospoda, svojega Boga, da hodiš po njegovih poteh in varuješ njegove zapovedi, njegove zakone in njegove sodbe, da boš lahko živel in se množil in Gospod, tvoj Bog, te bo blagoslovil v deželi, kamor greš, da jo vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Toda če se tvoje srce odvrne, tako da ne boš prisluhnil, temveč boš odveden proč in slavil druge bogove in jim služil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'ti ta dan naznanjam, da se boš zagotovo pogubil in da ne boš podaljšal svojih dni v deželi, kamor greš čez Jordan, da jo vzameš v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Danes kličem nebo in zemljo za pričo zoper tebe, da sem predte postavil življenje in smrt, blagoslov in prekletstvo. Zato izberi življenje, da boš lahko živel tako ti kakor tvoje seme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'da lahko ljubiš Gospoda, svojega Boga in da lahko ubogaš njegov glas in da se lahko trdno pridružiš k njemu, kajti on je tvoje življenje in dolžina tvojih dni, da boš lahko prebival v deželi, ki jo je Gospod prisegel tvojim očetom, Abrahamu, Izaku in Jakobu, da jim jo da.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Mojzes je odšel in te besede spregovoril vsemu Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Rekel jim je: »Jaz sem ta dan star sto dvajset let. Ne morem več hoditi ven in vstopati noter. Tudi Gospod mi je rekel: ›Ti ne boš šel preko tega Jordana.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Gospod, tvoj Bog, bo šel preko pred teboj in on bo izpred tebe uničil te narode in ti jih boš vzel v last in Józue, on bo šel preko pred teboj, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Gospod jim bo storil kakor je storil Sihónu in Ogu, kraljema Amoréjcev in njuni deželi, ki ju je uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Gospod ju bo izročil pred tvoj obraz, da jima boš lahko storil glede na vse zapovedi, ki sem ti jih zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Bodi močan in odločnega poguma, ne boj se niti se jih ne plaši, kajti Gospod, tvoj Bog, on je ta, ki gre s teboj; ne bo te razočaral niti te ne bo zapustil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Mojzes je zaklical k Józuetu in mu pred očmi vsega Izraela rekel: »Bodi močan in odločnega poguma, kajti s tem ljudstvom moraš iti v deželo, ki jo je Gospod prisegel njihovim očetom, da jim jo da; in ti jim boš povzročil, da jo podedujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Gospod, on je ta, ki gre pred teboj. S teboj bo, ne bo te razočaral niti te ne bo zapustil. Ne boj se niti ne bodi zaprepaden.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Mojzes je zapisal to postavo in jo izročil duhovnikom, sinovom Lévijevcev, ki so nosili skrinjo Gospodove zaveze, in vsem Izraelovim starešinam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mojzes jim je zapovedal, rekoč: »Ob koncu vsakih sedmih let, na slovesno leto odpusta, na šotorski praznik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'ko pride ves Izrael, da se prikaže pred Gospodom, tvojim Bogom, na kraju, ki ga bo on izbral, boš to postavo bral pred vsem Izraelom v njihovo uho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Skupaj zberi ljudstvo, može, žene, otroke in svojega tujca, ki je znotraj tvojih velikih vratih, da lahko slišijo in da se lahko naučijo in se bojijo Gospoda, svojega Boga in obeležujejo, da storijo vse besede te postave');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'in da njihovi otroci, ki niso poznali ničesar, lahko slišijo in se naučijo bati se Gospoda, svojega Boga, tako dolgo kot vi živite v deželi, kamor greste prek Jordana, da jo vzamete v last.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Gospod je rekel Mojzesu: »Glej, približujejo se tvoji dnevi, ko moraš umreti. Pokliči Józueta in se postavita v šotorskem svetišču skupnosti, da mu lahko dam naročilo.« Mojzes in Józue sta odšla in se postavila v šotorskem svetišču skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Gospod se je prikazal v šotorskem svetišču, v oblačnem stebru in oblačni steber je stal nad vrati šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Gospod je rekel Mojzesu: »Glej, zaspal boš s svojimi očeti in to ljudstvo se bo vzdignilo in se šlo vlačugat za bogovi tujcev dežele, v katero gredo, da bi bili med njimi in zapustili me bodo in prelomili mojo zavezo, ki sem jo sklenil z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Potem bo na tisti dan moja jeza vneta zoper njih in zapustil jih bom in svoj obraz bom skril pred njimi in použiti bodo in številna zla in težave jih bodo zadele, tako da bodo na tisti dan rekli: ›Ali niso nad nas prišla ta zla, ker med nami ni našega Boga?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Na tisti dan bom zagotovo skril svoj obraz zaradi vseh hudobij, ki jih bodo naredili v tem, da so se obrnili k drugim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Zdaj si torej zapišite to pesem in jo učite Izraelove otroke. Položite jo v njihova usta, da bo ta pesem lahko priča zame zoper Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Kajti ko jih bom privedel v deželo, ki sem jo prisegel njihovim očetom, kjer tečeta mleko in med in bodo jedli in se nasitili in postali debeli, potem se bodo obrnili k drugim bogovom in jim služili in me izzivali in prelomili mojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Zgodilo se bo, ko jih bodo doletela mnoga zla in stiske, da bo ta pesem pričala zoper njih kakor priča, kajti ta ne bo pozabljena iz ust njihovega semena, kajti jaz poznam njihove zamisli, s katerimi hodijo naokoli, celo sedaj, preden sem jih privedel v deželo, ki sem jim jo prisegel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Zato je Mojzes isti dan napisal to pesem in jo učil Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Nunovemu sinu Józuetu je dal zadolžitev in rekel: »Bodi močan in odločnega poguma, kajti ti boš Izraelove otroke privedel v deželo, ki sem jim jo prisegel in jaz bom s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Pripetilo se je, ko je Mojzes končal s pisanjem besed te postave v knjigo, dokler niso bile dokončane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'da je Mojzes zapovedal Lévijevcem, ki so nosili skrinjo Gospodove zaveze, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '»Vzemite to knjigo postave in jo postavite v stran skrinje zaveze Gospoda, svojega Boga, da bo ta lahko tam za pričo zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Kajti poznam tvoj upor in tvoj trdi vrat. Glej, medtem ko sem z vami ta dan še živ, ste bili uporni zoper Gospoda in koliko bolj po moji smrti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Zberite k meni vse starešine svojih rodov in svoje častnike, da lahko te besede govorim v njihova ušesa in kličem nebo in zemljo, da pričata zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Kajti vem, da se boste po moji smrti popolnoma izpridili in odvrnili od poti, ki sem vam jo zapovedal in zlo vas bo zadelo v zadnjih dneh, ker boste počeli zlo v Gospodovih očeh, da ga dražite k jezi skozi dela svojih rok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Mojzes je na ušesa vse Izraelove skupnosti govoril besede te pesmi, dokler se niso končale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '»Pazljivo prisluhni, oh ti nebo, jaz pa bom govoril in sliši, oh zemlja, besede mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Moj nauk bo kapljal kakor dež, moj govor bo rosil kakor rosa, kakor dežek na nežno zelišče in kakor nalivi na travo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'ker bom razglašal Gospodovo ime. Veličino pripišite našemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'On je Skala, njegovo delo je popolno, kajti vse njegove poti so sodba. Bog resnice in brez krivičnosti, pravičen in iskren je on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Izpridili so se, njihov madež ni madež njegovih otrok. Sprevržen in sprijen rod so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Ali tako poplačate Gospodu, oh nespametno in ne-modro ljudstvo? Mar ni on tvoj oče, ki te je kupil? Mar te ni on naredil in te postavil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Spomnite se dni od davnine, preudarite leta mnogih rodov. Vprašajte svojega očeta in vam bo pokazal, svoje starešine in ti bodo povedali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Ko je Najvišji narodom razdelil njihovo dediščino, ko je ločil Adamove sinove, je ljudstvu postavil meje, glede na število Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Kajti Gospodov delež je njegovo ljudstvo; Jakob je žreb njegove dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Našel ga je v zapuščeni deželi in v opustošeni, tuleči divjini. Vodil ga je naokrog, poučeval ga je, ga varoval kakor punčico svojega očesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Kakor orlica spodbuja svoje gnezdo, frfota nad svojimi mladiči, široko razširja svoje peruti, jih jemlje in nosi na svojih perutih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'tako ga je Gospod sam vodil in tam z njim ni bilo tujega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Dal mu je jahati na visokih krajih zemlje, da bi lahko jedel donos od polj in storil mu je, da sesa med iz skale in olje iz kremenčeve skale,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'maslo goveda in mleko ovc, s tolščo jagnjet in ovni bašánske pasme in koze, z najbogatejšo notranjostjo zrna in pil si čisto kri grozdnih jagod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Toda Ješurún se je odebelil in brcal. Postal si debel, postal si gost, pokrit si z maščobo. Potem je zapustil Boga, ki ga je naredil in preziral Skalo rešitve svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'S tujimi bogovi so ga dražili do ljubosumnosti, z ogabnostmi so ga izzivali k jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Žrtvovali so hudičem, ne pa Bogu, bogovom, ki jih niso poznali, novim bogovom, ki so se na novo pojavili, ki se jih vaši očetje niso bali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Nisi mislil na Skalo, ki te je spočela in pozabil si Boga, ki te je oblikoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Ko je Gospod to videl, jih je zaničeval, ker so ga njegovi sinovi in njegove hčere jezili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Rekel je: ›Svoj obraz bom skril pred njimi. Videl bom kakšen bo njihov konec, kajti zelo kljubovalen rod so, otroci, v katerih ni vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ganili so me do ljubosumja s tem, kar ni Bog; s svojimi ničevostmi so me izzivali k jezi. Do ljubosumja jih bom ganil s tistimi, ki niso ljudstvo; k jezi jih bom izzival z nespametnim narodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Kajti v moji jezi je vžgan ogenj in gorel bo do najnižjega pekla in použil bo zemljo z njenim narastom in vžgal bo temelje gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Nanje bom nakopičil vragolije, nanje bom poslal svoje puščice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Izčrpani bodo z lakoto in požrti z gorečo vročino in z grenkim uničenjem. Nadnje bom poslal tudi zobe zveri, s strupom kač, [ki se plazijo po] prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Meč zunaj in strahota znotraj bo uničila tako mladeniča kot devico, tudi dojenčka z možem sivih las.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Rekel sem: ›Razkropil jih bom v kote in storil bom, da spomin nanje zbledi med ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Mar ni bilo, da sem se bal sovražnikovega besa, da se ne bi njihovi nasprotniki čudno obnašali in da ne bi rekli: ›Naša roka je visoko in Gospod ni storil vsega tega.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Kajti oni so narod brez preudarnosti niti ni nobenega razumevanja v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Oh, da bi bili modri, da bi to razumeli, da bi preudarili svoj zadnji konec!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kako naj jih eden prežene tisoč in dva pripravita deset tisoč, da bežijo, razen, da jih je njihova Skala prodala in jih je Gospod izročil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Kajti njihova skala ni kakor naša Skala, celo sami naši sovražniki so sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Kajti njihova trta je iz sódomske trte in iz gomórskih polj. Njihovo grozdje je grozdje žolča, njihovi grozdi so grenki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Njihovo vino je strup zmajev in krut strup kober.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Mar ni to prihranjeno v shrambi z menoj in zapečateno med mojimi zakladi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Meni pripada maščevanje in povračilo. Njihovo stopalo bo zdrsnilo ob pravem času, kajti dan njihove katastrofe je pri roki in stvari, ki bodo prišle nadnje, hitijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Kajti Gospod bo sodil svoje ljudstvo in se pokesal zaradi svojih služabnikov, ko vidi, da je njihova moč odšla in tam ni nikogar zaprtega ali preostalega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Rekel bo: ›Kje so njihovi bogovi, njihova skala, v katero so zaupali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'ki so jedli tolščo svojih klavnih daritev in pili vino svojih pitnih daritev? Naj vstanejo in vam pomagajo in bodo vaša zaščita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Poglej sedaj, da sem jaz, celó jaz sam in tukaj ni boga z menoj. Jaz ubijam in jaz oživljam; jaz ranim in jaz ozdravljam. Niti tam ni nobenega, ki lahko osvobodi iz moje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Kajti svojo roko dvignem do neba in rečem: ›Jaz živim na veke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Če nabrusim svoj lesketajoči meč in moja roka zgrabi sodbo, bom povrnil maščevanje svojim sovražnikom in nagradil tiste, ki me sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Svoje puščice bom opijanil s krvjo in moj meč bo žrl meso in to s krvjo umorjenih in ujetnikov, od začetka maščevanj nad sovražnikom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Veselite se, oh vi narodi, z njegovim ljudstvom, kajti maščeval bo kri svojih služabnikov in povrnil bo maščevanje svojim nasprotnikom in usmiljen bo do svoje dežele in do svojega ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Mojzes je prišel in vse besede te pesmi spregovoril v ušesa ljudstva, on in Nunov sin Hošéa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Mojzes je končal govorjenje vseh teh besed vsemu Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Rekel jim je: »Nastavite svoja srca k vsem besedam, ki jih ta dan pričujem med vami, ki jih boste zapovedali svojim otrokom, da jih obeležujejo, da jih storijo, vse besede te postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Kajti to za vas ni prazna stvar, ker to je vaše življenje in zaradi te stvari boste podaljšali svoje dni v deželi, kamor greste čez Jordan, da jo vzamete v last.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Gospod je ta isti dan spregovoril Mojzesu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '»Povzpni se na to gorovje Abarím, na goro Nebó, ki je v deželi Moáb, ki je nasproti Jerihe in poglej kánaansko deželo, ki jo dajem Izraelovim otrokom v posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Umri na gori, kamor se povzpneš in bodi zbran k svojemu ljudstvu, kakor je tvoj brat Aron umrl na gori Hor in je bil zbran k svojemu ljudstvu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'ker sta grešila zoper mene med Izraelovimi otroki pri vodah Meríba [v] Kadešu, v Cinski divjini, ker me nista izkazala svetega v sredi Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Vendar boš deželo videl pred seboj, toda ne boš šel tja, v deželo, ki sem jo dal Izraelovim otrokom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'To je blagoslov, s katerim je Mojzes, Božji mož, pred svojo smrtjo blagoslovil Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Rekel je: » Gospod je prišel s Sinaja in se iz Seírja dvignil k njim. On sije z gore Parán in prišel je z deset tisoči svetih. Iz njegove desnice je šla zanje ognjena postava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Da, ljubil je ljudstvo. Vsi njegovi sveti so v tvoji roki in usedli so se pri tvojih stopalih; vsak bo prejel od tvojih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mojzes nam je zapovedal postavo, torej dediščino Jakobove skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'In on je bil kralj v Ješurúnu, ko so se zbrali skupaj poglavarji ljudstva in so bili Izraelovi rodovi zbrani skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Naj Ruben živi in ne umre in naj njegovih mož ne bo malo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'To je blagoslov za Juda. Rekel je: »Prisluhni, Gospod, Judovemu glasu in privedi ga k svojemu ljudstvu. Naj mu njegove roke zadoščajo in ti mu bodi pomoč pred njegovimi sovražniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'O Léviju je rekel: » Naj bosta tvoj Tumím in tvoj Urím s tvojim svetim, ki si ga preizkusil pri Masi in s katerim si se prepiral pri vodah Meríbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'ki je svojemu očetu in svoji materi rekel: ›Nisem ga videl.‹ Niti ni priznal svojih bratov niti spoznal svojih lastnih otrok, kajti obeležili so tvojo besedo in se držali tvoje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Jakoba bodo učili tvojih sodb in Izraela tvoje postave. Pred teboj bodo postavili kadilo in celotno žgalno daritev na tvoj oltar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Blagoslovi Gospod njegovo imetje in sprejmi delo njegovih rok. Skozi ledja udari tiste, ki vstajajo zoper njega in izmed tistih, ki ga sovražijo, da ne vstanejo ponovno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'In o Benjaminu je rekel: »Ljubljen od Gospoda bo varno prebival pri njem in Gospod ga bo ves dan pokrival in prebival bo med njegovimi rameni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'O Jožefu je rekel: »Njegova dežela naj bo blagoslovljena od Gospoda, za dragocene stvari z neba in za roso in za globino, ki leži spodaj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'in za dragoceno sadje, porojeno s soncem in za dragocene stvari, navržene z luno');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'in za vodilne stvari starodavnih gora in za dragocene stvari trajnih hribov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'in za dragocene stvari zemlje in njene polnosti in za dobro voljo tistega, ki je prebival v grmu. Naj nad Jožefovo glavo pride blagoslov in na vrh glave tistega, ki je bil ločen od svojih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Njegova slava je podobna prvencu njegovega bikca in njegovi rogovi so podobni rogovom samorogov. Z njimi bo suval ljudstvo skupaj h koncem zemlje, in oni so Efrájimovi deset tisoči in oni so Manásejevi deset tisoči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'O Zábulonu je rekel: »Veseli se Zábulon v svojem odhajanju in Isahár v svojih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Ljudstvo bosta klicala h gori. Tam bodo darovali klavne daritve pravičnosti, kajti sesali bodo od obilja morij in od zakladov, skritih v pesku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'O Gadu je rekel: »Blagoslovljen bodi, kdor povečuje Gad. Ta prebiva kakor lev in trga laket s têmenom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Prvi del si je priskrbel zase, ker je bil tam, v deležu postavodajalca, dokončan; in prišel je s poglavarji ljudstva, izvršil je Gospodovo pravičnost in njegove sodbe z Izraelom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'O Danu je rekel: »Dan je levji mladič. Poskakoval bo iz Bašána.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'O Neftáliju je rekel: »Oh Neftáli, nasičen z naklonjenostjo in poln Gospodovega blagoslova. Ti poseduj zahod in jug.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'O Aserju je rekel: »Aser naj bo blagoslovljen z otroki. Sprejemljiv naj bo svojim bratom in naj svoje stopalo omoči v olju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Tvoji čevlji bodo železo in bron in kakor tvoji dnevi, takšna bo tvoja moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nobenega ni podobnega Ješurúnovemu Bogu, ki jaha na nebesih v tvojo pomoč in v svoji odličnosti na nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Večen Bog je tvoje zatočišče in spodaj so večne roke in on bo izpred tebe sunil sovražnika in rekel bo: ›Uniči jih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Potem bo Izrael sam prebival na varnem. Jakobov studenec bo na deželi žita in vina; tudi njegovo nebo bo kapljalo roso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Srečen si ti, oh Izrael. Kdo je tebi podoben, oh ljudstvo, rešeno po Gospodu, ščitu tvoje pomoči in kdo je meč tvoje odličnosti! In tvoji sovražniki ti bodo najdeni kot lažnivci, in teptal jih boš na njihovih visokih krajih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Mojzes se je iz moábskih ravnin dvignil na goro Nebó, k vrhu Pisge, ki je nasproti Jerihe. In Gospod mu je pokazal vso deželo Gileád, do Dana');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'in ves Neftáli, Efrájimovo in Manásejevo deželo in vso Judovo deželo, do skrajnega morja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'in jug in ravnino jerihonske doline, mesto palmovih dreves, do Coarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Gospod mu je rekel: »To je dežela, ki sem jo prisegel Abrahamu, Izaku in Jakobu, rekoč: ›Dal jo bom tvojemu semenu.‹ Dal sem ti, da jo vidiš s svojimi očmi, toda ne boš šel tja preko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Tako je Gospodov služabnik Mojzes umrl tam v moábski deželi, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Pokopal ga je v dolini, v moábski deželi nasproti Bet Peórja, toda noben človek ne pozna njegovega mavzoleja do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mojzes je bil star sto dvajset let, ko je umrl. Njegovo oko ni bilo zatemnjeno niti se njegova naravna sila ni zmanjšala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Izraelovi otroci so na moábskih ravninah trideset dni jokali za Mojzesom; tako so bili dnevi jokanja in žalovanja za Mojzesom končani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Nunov sin Józue pa je bil poln duha modrosti, kajti Mojzes je nanj položil svoji roki in Izraelovi otroci so mu prisluhnili in storili, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'In od takrat v Izraelu ni vstal prerok, podoben Mojzesu, ki ga je Gospod poznal iz obličja v obličje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'v vseh znamenjih in čudežih, ki mu jih je Gospod poslal, da jih v egiptovski deželi stori faraonu in vsem njegovim služabnikom in vsej njegovi deželi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'in v vsej tisti mogočni roki in vsej veliki strahoti, ki jo je Mojzes pokazal pred očmi vsega Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Torej po smrti Mojzesa, Gospodovega služabnika, se je pripetilo, da je Gospod spregovoril Nunovemu sinu Józuetu, Mojzesovemu služabniku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '»Moj služabnik Mojzes je mrtev. Sedaj torej vstani, pojdi čez ta Jordan, ti in vse to ljudstvo, v deželo, ki jo dajem njim, torej Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Vsak kraj, na katerega bo stopil podplat tvojega stopala, to sem ti dal, kakor sem rekel Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od divjine in tega Libanona, celo do velike reke, reke Evfrat, vso deželo Hetejcev in do velikega morja proti zahajanju sonca, bo vaša pokrajina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Tam noben mož ne bo zmožen obstati pred teboj vse dni tvojega življenja. Kakor sem bil z Mojzesom, tako bom s teboj. Ne bom te razočaral niti te ne bom zapustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Bodi močan in odločnega poguma, kajti temu ljudstvu boš v dediščino razdelil deželo, za katero sem prisegel njihovim očetom, da jim jo dam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Samo močan bodi in zelo pogumen, da boš lahko obeležil, da storiš glede na vso postavo, ki ti jo je moj služabnik Mojzes zapovedal. Ne obrni se od nje ne k desni roki ne k levi, da boš lahko uspeval kamorkoli greš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Ta knjiga postave ne bo odšla od tvojih ust, temveč boš o njej premišljeval podnevi in ponoči, da boš lahko obeležil, da storiš glede na vse to, kar je zapisano v njej, kajti takrat boš naredil svojo pot uspešno in takrat boš imel dober uspeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Mar ti nisem jaz zapovedal? Bodi močan in odločnega poguma. Ne bodi prestrašen niti ne bodi zaprepaden, kajti Gospod, tvoj Bog, je s teboj, kamorkoli greš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Potem je Józue zapovedal častnikom ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '»Preidite skozi vojsko in zapovejte ljudstvu, rekoč: ›Pripravite svoj živež, kajti v treh dneh boste šli preko tega Jordana, da vstopite, da vzamete v last deželo, ki vam jo daje Gospod, vaš Bog, da jo vzamete v last.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rubenovcem in Gádovcem in polovici Manásejevega rodu pa je Józue spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '»Spomnite se besede, ki vam jo je zapovedal Gospodov služabnik Mojzes, rekoč: › Gospod, vaš Bog, vam je dal počitek in vam je dal to deželo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vaše žene, vaši malčki in vaša živina bodo ostali v deželi, ki vam jo je dal Mojzes na tej strani Jordana, toda vi boste pred vašimi brati prečkali oboroženi, vsi močni junaški možje in jim pomagali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'dokler Gospod ne da vašim bratom počitek, kakor ga je dal vam in tudi oni ne vzamejo v last dežele, ki jim jo daje Gospod, vaš Bog. Potem se boste vrnili v deželo svoje posesti in jo uživali, ki vam jo je dal Gospodov služabnik Mojzes na tej strani Jordana, proti sončnemu vzhodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Józuetu so odgovorili, rekoč: »Vse, kar nam zapoveduješ, bomo storili in kamor nas pošlješ, bomo šli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Glede na to, kakor smo Mojzesu prisluhnili v vseh stvareh, tako bomo prisluhnili tebi. Samo Gospod, tvoj Bog, naj bo s teboj, kakor je bil z Mojzesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Kdorkoli je ta, ki se upre zoper tvojo zapoved in ne bo prisluhnil tvojim besedam v vsem, kar mu zapoveš, bo usmrčen. Samo močan bodi in odločnega poguma.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Nunov sin Józue je iz Šitíma na skrivaj poslal ogledovat dva moža, rekoč: »Pojdita, poglejta deželo, celo Jeriho.« Odšla sta ter prišla v hišo pocestnice, po imenu Rahába in tam prenočila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Kralju Jerihe je bilo povedano, rekoč: »Glej, nocoj sta prišla sèm moža izmed Izraelovih otrok, da preiščeta deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Kralj Jerihe je poslal k Rahábi, rekoč: »Privedi naprej moža, ki sta prišla k tebi, ki sta vstopila v tvojo hišo, kajti prišla sta, da bi preiskala vso deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Ženska je vzela dva moža ter ju skrila in rekla tako: »K meni sta prišla moža, toda nisem vedela od kod sta bila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Pripetilo se je okoli časa zapiranja velikih vrat, ko je bilo temno, da sta moža odšla ven. Kam sta moža odšla, ne vem. Hitro ju zasledujte, kajti dohiteli ju boste.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Toda ona ju je privedla gor na streho hiše in ju skrila s stebli lana, ki jih je razvrstila po strehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Možje so ju zasledovali po poti k Jordanu, k prehodom in takoj, ko so tisti, ki so ju zasledovali, odšli ven, so zaprli velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Preden sta se ulegla, je prišla k njima na streho');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'in možema rekla: »Vem, da vam je Gospod dal to deželo in da je vaša strahota padla na nas in da vsi prebivalci dežele zaradi vas slabijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Kajti slišali smo, kako je Gospod za vas posušil vode Rdečega morja, ko ste prišli iz Egipta, in kaj ste storili dvema kraljema Amoréjcev, ki sta bila na drugi strani Jordana, Sihónu in Ogu, ki ste jih popolnoma uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Takoj, ko smo slišali te stvari, so se naša srca stopila niti tam zaradi vas ni ostalo nič več poguma v kateremkoli človeku, kajti Gospod, vaš Bog, on je Bog v nebesih zgoraj in na zemlji spodaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Zdaj torej, prosim vaju, prisezita mi pri Gospodu, ker sem vama izkazala prijaznost, da bosta tudi vidva izkazala prijaznost hiši mojega očeta in mi dala zanesljivo znamenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'In da boste mojega očeta rešili živega in mojo mater, moje brate, moje sestre in vse, kar imajo in naša življenja osvobodili pred smrtjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Moža sta ji odgovorila: »Najina življenja za vaša, če ne izustiš te naše stvari. Zgodilo se bo, ko nam Gospod da deželo, da bomo s teboj postopali prijazno in zvesto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Potem ju je po vrvi spustila skozi okno, kajti njena hiša je bila na mestnem obzidju in prebivala je na obzidju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Rekla jima je: »Spravita se do gore, da vaju ne bi srečali zasledovalci in tam se skrivajta tri dni, dokler se zasledovalci ne vrnejo in potem lahko gresta svojo pot.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Moža sta ji rekla: »Midva bova brez krivde glede te tvoje prisege, s katero si naju prisegla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Glej, ko pridemo v deželo, boš to škrlatno vrv privezala na okno, skozi katero si naju spustila dol in domov k sebi boš privedla svojega očeta, svojo mater, svoje brate in vso družino svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'In zgodilo se bo, da kdorkoli bo šel ven skozi vrata tvoje hiše na ulico, bo njegova kri na njegovi glavi, midva pa bova brez krivde. In kdorkoli bo s teboj v hiši, njegova kri bo na najini glavi, če bo katerakoli roka nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Če izustiš to našo stvar, potem bova prosta tvoje prisege, s katero si naju primorala priseči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Rekla je: »Glede na vajine besede, tako naj bo to.« Poslala ju je proč in sta odšla in na okno je privezala škrlatno vrv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Odšla sta in prišla h gori ter tam ostala tri dni, dokler se zasledovalci niso vrnili. Zasledovalci so ju iskali po vsej poti, toda niso ju našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Tako sta se oba moža vrnila in spustila z gore, šla čez in prišla k Nunovemu sinu Józuetu in mu povedala vse stvari, ki so se jima pripetile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Józuetu sta rekla: »Resnično, Gospod je v naše roke izročil vso deželo, kajti celo vsi prebivalci dežele zaradi nas slabijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Józue je zgodaj zjutraj vstal in odpravili so se iz Šitíma ter prišli k Jordanu, on in vsi Izraelovi otroci in tam so prenočili, preden so šli čez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Po treh dneh se je pripetilo, da so častniki šli skozi vojsko');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'in zapovedali ljudstvu, rekoč: »Ko zagledate skrinjo zaveze Gospoda, svojega Boga in duhovnike in Lévijevce, ki jo nosijo, potem se boste odpravili iz svojega kraja in šli za njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Vendar naj bo med vami in njo prazen prostor, okoli dva tisoč komolcev po meri. Ne pridite bliže k njej, da boste lahko poznali pot, po kateri morate iti, kajti poprej še niste šli po tej poti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Józue je rekel ljudstvu: »Posvetite se, kajti jutri bo Gospod med vami delal čudeže.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Duhovnikom je Józue spregovoril, rekoč: »Dvignite skrinjo zaveze in pojdite čez pred ljudstvom.« In dvignili so skrinjo zaveze in odšli pred ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Gospod je rekel Józuetu: »Ta dan te bom začel poveličevati pred očmi vsega Izraela, da bodo lahko vedeli, da kakor sem bil z Mojzesom, tako bom s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Duhovnikom, ki nosijo skrinjo zaveze, boš zapovedal, rekoč: ›Ko pridete k robu jordanske vode, boste mirno stali v Jordanu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Izraelovim otrokom je Józue rekel: »Pridite sèm in prisluhnite besedam Gospoda, svojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Józue je rekel: »S tem boste spoznali, da je med vami živi Bog in da bo on čisto gotovo pred vami napodil Kánaance, Hetejce, Hivéjce, Perizéjce, Girgašéjce, Amoréjce in Jebusejce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Glejte, skrinja zaveze Gospoda vse zemlje, gre preko, pred vami, v Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Zdaj torej vzemite dvanajst mož izmed Izraelovih rodov, iz vsakega rodu moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Zgodilo se bo, takoj ko bodo podplati stopal duhovnikov, ki nosijo skrinjo Gospoda, Gospoda vse zemlje, počivali v vodah Jordana, da bodo vode Jordana odrezane od vod, ki prihajajo dol od zgoraj in bodo stale na kupu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'In pripetilo se je, ko se je ljudstvo odpravilo od svojih šotorov, da gredo čez Jordan, in so duhovniki pred ljudstvom nosili skrinjo zaveze');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'in ko so tisti, ki so nosili skrinjo, prišli k Jordanu in so bila stopala duhovnikov, ki so nosili skrinjo, omočena v rob vode (kajti Jordan ves čas žetve preplavlja vse svoje bregove),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'da so vode, ki so prihajale dol od zgoraj, stale in se vzdignile na kup, zelo daleč od mesta Adám, ki je poleg Caretána. Tiste, ki so prihajale dol k morju ravnine, torej slanemu morju, so odtekle in bile odrezane in ljudstvo je šlo čez prav nasproti Jerihi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Duhovniki, ki so nosili skrinjo Gospodove zaveze, so trdno stali na suhih tleh v sredi Jordana in vsi Izraelci so šli čez po suhih tleh, dokler ni vse ljudstvo šlo čez Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Pripetilo se je, ko je vse ljudstvo dokončalo prehod čez Jordan, da je Gospod spregovoril Józuetu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '»Vzemi dvanajst mož izmed ljudstva, iz vsakega rodu moža');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'in jim zapovej, rekoč: ›Iz srede Jordana, iz kraja, kjer so trdno stala stopala duhovnikov, vzemite dvanajst kamnov in odnesli jih boste s seboj prek [Jordana] in jih pustili na kraju za nastanitev, kjer boste to noč prenočili.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Potem je Józue poklical dvanajst mož, ki jih je postavil izmed Izraelovih otrok, iz vsakega rodu moža');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'in Józue jim je rekel: »Pojdite čez pred skrinjo Gospoda, svojega Boga, v sredo Jordana in vsak izmed vas naj na svojo ramo vzame kamen, glede na število rodov Izraelovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'da bo to lahko znamenje med vami, da ko vaši otroci vprašajo svoje starše, v času, ki pride, rekoč: ›Kaj mislite s temi kamni?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Potem jim boste odgovorili: ›Da so bile vode Jordana odrezane pred skrinjo Gospodove zaveze. Ko je ta šla čez Jordan, so bile jordanske vode odsekane in ti kamni bodo Izraelovim otrokom v spomin na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Izraelovi otroci so storili, kakor je Józue zapovedal in iz srede Jordana vzeli dvanajst kamnov, kakor je Gospod govoril Józuetu, glede na število rodov Izraelovih otrok in jih s seboj odnesli preko [Jordana] na kraj, kjer so prenočili in tam so jih odložili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Józue je dvanajst kamnov postavil v sredo Jordana, na kraj, kjer so stala stopala duhovnikov, ki so nosili skrinjo zaveze in tam so do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Kajti duhovniki, ki so nosili skrinjo, so stali v sredi Jordana, dokler ni bila končana vsaka stvar, ki jo je Gospod zapovedal Józuetu, da spregovori ljudstvu, glede na vse, kar je Mojzes zapovedal Józuetu in ljudstvo je pohitelo in šlo čez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Pripetilo se je, ko je vse ljudstvo dokončalo prehod čez [Jordan], da je šla čez skrinja in duhovniki v prisotnosti ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu so oboroženi šli čez pred Izraelovimi otroki, kakor jim je govoril Mojzes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Okoli štirideset tisoč pripravljenih za vojno je šlo čez pred Gospodom v bitko k ravninam Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Na ta dan je Gospod poveličal Józueta v očeh vsega Izraela in oni so se ga bali, kakor so se bali Mojzesa, vse dni njegovega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Gospod je spregovoril Józuetu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '»Zapovej duhovnikom, ki nosijo skrinjo pričevanja, da pridejo gor, ven iz Jordana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Józue je torej zapovedal duhovnikom, rekoč: »Pridite gor iz Jordana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Pripetilo se je, ko so duhovniki, ki so nosili skrinjo Gospodove zaveze, prišli gor iz srede Jordana in so bili podplati duhovniških stopal dvignjeni na suho zemljo, da so se vode Jordana vrnile na svoj kraj in stekle čez vse svoje bregove, kakor so počele poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'In ljudstvo je prišlo gor iz Jordana na deseti dan prvega meseca ter se utaborilo v Gilgálu, na vzhodni meji Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Tistih dvanajst kamnov, ki so jih vzeli iz Jordana, je Józue postavil v Gilgálu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Izraelovim otrokom je spregovoril, rekoč: »Ko bodo vaši otroci vprašali svoje očete, v času, ki pride, rekoč: ›Kaj pomenijo ti kamni?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Potem boste svojim otrokom dali vedeti, rekoč: ›Izrael je po suhih tleh prešel preko tega Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Kajti Gospod, vaš Bog, je izpred vas posušil vode Jordana, dokler niste prešli čez, kakor je Gospod, vaš Bog, storil Rdečemu morju, ki ga je posušil pred nami, dokler nismo prešli čez,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'da bi vsa ljudstva zemlje lahko poznala Gospodovo roko, da je ta mogočna, da se boste lahko na veke bali Gospoda, svojega Boga.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Pripetilo se je, ko so vsi kralji Amoréjcev, ki so bili na zahodni strani Jordana in vsi kralji Kánaancev, ki so bili poleg morja, slišali, da je Gospod izpred Izraelovih otrok posušil vode Jordana, dokler nismo prešli čez, da se je njihovo srce stopilo niti ni bilo več tam v njih duha zaradi Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Ob tistem času je Gospod rekel Józuetu: »Naredi si ostre nože in ponovno, drugič, obreži Izraelove otroke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Józue si je naredil ostre nože in Izraelove otroke obrezal na hribu prednjih kožic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'In to je razlog, zakaj je Józue obrezal. Vse ljudstvo, ki je prišlo iz Egipta, kar jih je bilo moških, torej vsi bojevniki, so umrli po poti v divjini, potem ko so prišli iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Torej vse ljudstvo, ki je izšlo, je bilo obrezano. Toda vsega ljudstva, ki je bilo rojeno po poti v divjini, ko so izšli iz Egipta, njih niso obrezali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Kajti Izraelovi otroci so štirideset let hodili po divjini, dokler ni bilo vse ljudstvo, ki so bili bojevniki, ki so prišli iz Egipta, použito, ker niso ubogali Gospodovega glasu, katerim je Gospod prisegel, da jim ne bo pokazal dežele, ki jo je Gospod prisegel njihovim očetom, da nam jo bo dal, deželo, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Njihove otroke, ki jih je dvignil namesto njih, te je Józue obrezal, kajti bili so neobrezani, ker jih po poti niso obrezali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Pripetilo se je, ko so naredili obrezo vsega ljudstva, da so ostali na svojih prostorih v taboru, dokler niso okrevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Gospod je rekel Józuetu: »Danes sem od tebe odvalil egiptovsko grajo.« Zaradi tega se ime kraja imenuje Gilgál do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Izraelovi otroci so se utaborili v Gilgálu in na štirinajsti dan meseca zvečer praznovali pasho na ravninah Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Naslednji dan po pashi so jedli od starega žita dežele, nekvašene kolače in praženo žito, na prav isti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Mana je prenehala naslednji dan, potem ko so jedli od starega žita dežele niti Izraelovi otroci niso imeli več mane, temveč so tisto leto jedli od sadov kánaanske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Pripetilo se je, ko je bil Józue pri Jerihi, da je povzdignil svoje oči in pogledal in glej, nasproti njega je stal mož z izvlečenim mečem v svoji roki. Józue je odšel k njemu ter mu rekel: » Ali si za nas ali za naše nasprotnike?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Odgovoril je: »Ne, temveč kot poveljnik Gospodove vojske; sedaj sem prišel.« Józue je padel na svoj obraz k zemlji in oboževal ter mu rekel: »Kaj pravi moj gospod svojemu služabniku?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Poveljnik Gospodove vojske je Józuetu rekel: »Sezuj svoj čevelj s svojega stopala, kajti kraj, na katerem stojiš, je svet.« In Józue je storil tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Torej Jeriha je bila strogo zaprta zaradi Izraelovih otrok. Nihče ni odšel ven in nihče ni prišel noter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Gospod je rekel Józuetu: »Poglej, v tvojo roko sem izročil Jeriho in njenega kralja in močne junaške može.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Obdali boste mesto, vsi vi bojevniki in enkrat obhodili mesto. Tako boste počeli šest dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Sedem duhovnikov bo pred skrinjo nosilo sedem šofarjev iz ovnovih rogov, in sedmi dan boste sedemkrat obkrožili mesto in duhovniki bodo zatrobili s šofarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'In zgodilo se bo, da ko bodo z ovnovim rogom naredili dolgo trobljenje in ko zaslišite zvok šofarja, naj vse ljudstvo zavpije z velikim krikom in mestno obzidje bo plosko padlo dol in ljudstvo se bo povzpelo, vsak človek naravnost pred seboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Nunov sin Józue je poklical duhovnike ter jim rekel: »Vzdignite skrinjo zaveze in sedem duhovnikov naj pred Gospodovo skrinjo nosi sedem šofarjev iz ovnovih rogov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Ljudstvu pa je rekel: »Pojdite naprej in obkrožite mesto in naj tisti, ki je oborožen, gre naprej pred Gospodovo skrinjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Pripetilo se je, ko je Józue govoril ljudstvu, da je sedem duhovnikov, nosečih sedem šofarjev iz ovnovih rogov, šlo naprej pred Gospodom in trobilo s šofarji in skrinja Gospodove zaveze jim je sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Oboroženi možje so šli pred duhovniki, ki so trobili na šofarje in zadnja straža je prišla za skrinjo. Duhovniki pa so hodili in trobili s šofarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Józue je zapovedal ljudstvu, rekoč: »Ne boste kričali niti naredili nobenega hrupa z vašim glasom niti ne bo nobena beseda izšla iz vaših ust do dneva, ko vam zapovem kričati; potem boste kričali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Tako je Gospodova skrinja obkrožila mesto, ga enkrat obhodila in prišli so v tabor in prenočili v taboru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Józue je vstal zgodaj zjutraj in duhovniki so dvignili Gospodovo skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Sedem duhovnikov, ki so pred Gospodovo skrinjo nosili sedem šofarjev iz ovnovih rogov, je nenehno hodilo naprej in trobilo s šofarji in oboroženi možje so šli pred njimi, toda zadnja straža je prišla za Gospodovo skrinjo, duhovniki hodeč naprej in trobeč s šofarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Drugi dan so enkrat obkrožili mesto in se vrnili v tabor. Tako so počeli šest dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Na sedmi dan se je pripetilo, da so vstali zgodaj, ob jutranjem svitanju in na isti način sedemkrat obkrožili mesto. Samo ta dan so mesto obkrožili sedemkrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Pripetilo se je sedmič, ko so duhovniki zatrobili s šofarji, da je Józue rekel ljudstvu: »Kričite, kajti Gospod vam je dal mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Mesto bo prekleto Gospodu, celó to in vse, kar je v njem. Samo pocestnica Rahába bo živela, ona in vsi, ki so z njo v hiši, ker je skrila poslanca, ki smo ju poslali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Vi pa se zagotovo zadržite pred prekleto stvarjo, da se ne bi naredili preklete, ko vzamete od preklete stvari in naredite tabor Izraelcev prekletstvo in ga vznemirite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Toda vse srebro, zlato in posode iz brona in železa so posvečeni Gospodu. Pridejo naj v Gospodovo zakladnico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tako je ljudstvo zakričalo, ko so duhovniki zatrobili s šofarji in pripetilo se je, ko je ljudstvo zaslišalo zvok šofarja in je ljudstvo zavpilo z velikim krikom, da je obzidje plosko padlo dol, tako da je ljudstvo odšlo gor v mesto, vsak mož naravnost pred seboj in zavzeli so mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Popolnoma so uničili vse, kar je bilo v mestu, tako moškega kakor žensko, mladega, starega, vola, ovco in osla, z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Toda Józue je rekel dvema možema, ki sta ogledovala deželo: »Pojdita v hišo pocestnice in od tam privedita žensko in vse, kar ima, kakor sta ji prisegla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Mladeniča, ki sta bila oglednika, sta vstopila in privedla ven Rahábo, njenega očeta, njeno mater, njene brate in vse, kar je imela in ven sta privedla vse njeno sorodstvo in jih pustila zunaj tabora Izraelcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Mesto pa so požgali z ognjem in vse, kar je bilo v njem. Samo srebro, zlato in posode iz brona in iz železa, so dali v zakladnico Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Józue je rešil pocestnico Rahábo živo in družino njenega očeta in vse, kar je imela. V Izraelu prebiva do današnjega dne, ker je skrila poslanca, ki ju je Józue poslal, da ogledata Jeriho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Ob tistem času jih je Józue zaprisegel, rekoč: »Preklet bodi mož pred Gospodom, ki dvigne in pozida to mesto Jeriho. Njen temelj bo položil v svojem prvorojencu in v njegovem najmlajšem sinu bo postavil njena velika vrata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Tako je bil Gospod z Józuetom in njegova slava je bila razglašena po vsej deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Toda Izraelovi otroci so zagrešili prekršek v prekleti stvari, kajti Ahán, sin Karmíja, sin Zabdíja, sin Zeraha, iz Judovega rodu, je vzel od preklete stvari in Gospodova jeza je bila vžgana zoper Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Józue je poslal može iz Jerihe v Aj, ki je poleg Bet Avena, na vzhodni strani Betela in jim spregovoril, rekoč: »Pojdite gor in poglejte deželo.« Možje so odšli gor in pogledali Aj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Vrnili so se k Józuetu in mu rekli: »Naj ne gre gor vse ljudstvo; temveč naj gre gor okoli dva ali tri tisoč mož in naj udarijo Aj; in ne primoraj vsega ljudstva, da se trudi tja, kajti le malo jih je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Tako jih je odšlo tja gor izmed ljudstva okoli tri tisoč mož, in ti so pobegnili pred možmi iz Aja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Možje iz Aja so jih izmed njih udarili šestintrideset mož, kajti pregnali so jih izpred velikih vrat, celó do Šebaríma in jih udarili pri hitenju dol, zato so se srca ljudstva stopila in postala kakor voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Józue je pred Gospodovo skrinjo raztrgal svoja oblačila in padel na svoj obraz k zemlji do večera, on in Izraelove starešine in na svoje glave so si posuli prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Józue je rekel: »Ojoj, oh Gospod Bog, čemu si to ljudstvo sploh privedel čez Jordan, da nas izročiš v roko Amoréjcev, da nas uničijo? Bog daj, da bi bili zadovoljni in prebivali na drugi strani Jordana!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Oh Gospod, kaj naj rečem, ko Izrael obrača svoje hrbte pred svojimi sovražniki!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kajti Kánaanci in vsi prebivalci dežele bodo slišali o tem in nas bodo obkrožili naokoli in naše ime iztrebili z zemlje in kaj boš storil svojemu velikemu imenu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Gospod je rekel Józuetu: »Dvigni se, zakaj tako ležiš na svojem obrazu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael je grešil in prav tako so prekršili mojo zavezo, ki sem jim jo zapovedal, kajti vzeli so si celó od preklete stvari in tudi kradli in tudi prikrivali so in to so si postavili celó med svoje stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Zato Izraelovi otroci niso mogli obstati pred svojimi sovražniki, temveč so obrnili svoje hrbte pred svojimi sovražniki, ker so bili prekleti. Niti jaz ne bom več z vami, razen če ne uničite prekletega izmed vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Vstani, posvéti ljudstvo in reci: ›Posvetite se za jutrišnji dan,‹ kajti tako govori Gospod, Izraelov Bog: ›V vaši sredi je prekleta stvar, oh Izrael. Ne moreš stati pred svojimi sovražniki, dokler izmed sebe ne odstranite preklete stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Zato boste zjutraj privedeni glede na svoje rodove. In zgodilo se bo, da bo rod, ki ga Gospod vzame, prišel glede na njegove družine, in družina, ki jo bo Gospod vzel, bo prišla po svojih gospodinjstvih, in gospodinjstvo, ki ga bo Gospod vzel, bo prišlo mož za možem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Zgodilo se bo, da kdor je vzet s prekleto stvarjo, bo sežgan z ognjem, on in vse, kar ima, ker je prekršil Gospodovo zavezo in ker je izvršil neumnost v Izraelu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Tako je Józue zgodaj zjutraj vstal in Izraela privedel po njihovih rodovih in izbran je bil Judov rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Privedel je Judovo družino in izbrana je bila Zerahova družina. Privedel je družino Zerahovcev, moškega za moškim in izbran je bil Zabdí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Privedel je njegovo gospodinjstvo, moškega za moškim in izbran je bil Ahán, sin Karmíja, sin Zabdíja, sin Zeraha, iz Judovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Józue je rekel Ahánu: »Moj sin, izkaži, prosim te, slavo Gospodu, Izraelovemu Bogu in mu naredi priznanje in povej mi torej, kaj si storil. Tega ne skrivaj pred menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Ahán je odgovoril Józuetu in rekel: »Zares, grešil sem zoper Gospoda, Izraelovega Boga in tako in tako sem storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Ko sem med pleni zagledal lepo babilonsko obleko in dvesto šeklov srebra in klin iz zlata, težak petdeset šeklov, potem sem zahlepel [po] njih in jih vzel. Glej, skriti so v zemlji, v sredi mojega šotora in srebro pod tem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Tako je Józue poslal poslanca in stekla sta v šotor in glej, to je bilo skrito v njegovem šotoru in srebro pod tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Vzeli so jih iz srede šotora in jih prinesli k Józuetu in k vsem Izraelovim otrokom in jih položili pred Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Józue in ves Izrael z njim, je vzel Zerahovega sina Ahána, srebro, obleko, klin iz zlata, njegove sinove, njegove hčere, njegove vole, njegove osle, njegove ovce, njegov šotor in vse, kar je imel in odvedli so jih v dolino Ahór.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Józue je rekel: »Zakaj si nas spravil v težave? Gospod te bo ta dan spravil v težave.« In ves Izrael ga je kamnal s kamni in jih sežgal z ognjem, potem ko so jih kamnali s kamni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Nad njim so dvignili velik kup kamenja do tega dne. Tako se je Gospod obrnil od okrutnosti svoje jeze. Zato je bilo ime tega kraja imenovano Dolina Ahór do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Gospod je rekel Józuetu: »Ne boj se niti ne bodi zaprepaden. S seboj vzemi vse bojno ljudstvo in se dvigni, pojdi gor do Aja. Glej, v tvojo roko sem izročil ajskega kralja, njegovo ljudstvo, njegovo mesto in njegovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Aju in njegovemu kralju boš storil, kakor si storil Jerihi in njenemu kralju. Samo njegov plen in njegovo živino si boste zaplenili. Zadaj za mestom si postavi zasedo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Tako je Józue vstal in vse bojno ljudstvo, da gredo gor zoper Aj. Józue je izbral trideset tisoč močnih junaških mož in jih ponoči odposlal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Zapovedal jim je, rekoč: »Glejte, prežali boste v zasedi zoper mesto, torej za mestom. Ne pojdite zelo daleč od mesta, temveč vsi bodite pripravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Jaz in vse ljudstvo, ki je z menoj, se bomo približali mestu in zgodilo se bo, ko bodo prišli ven zoper nas, kakor prvič, da bomo pobegnili pred njimi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, '(kajti prišli bodo ven za nami), dokler jih ne bomo pritegnili iz mesta, kajti rekli bodo: ›Pred nami bežijo, kakor prvič.‹ Zato bomo pobegnili pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Potem boste vstali iz zasede in se polastili mesta, kajti Gospod, vaš Bog, ga bo izročil v vašo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Zgodilo se bo, ko boste zavzeli mesto, da boste požgali mesto. Glede na Gospodovo zapoved boste storili. Poglejte, zapovedal sem vam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Józue jih je torej poslal naprej in odšli so, da ležijo v zasedi in ostanejo med Betelom in Ajem, na zahodni strani Aja. Toda Józue je to noč prenočil med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Józue je vstal zgodaj zjutraj, preštel ljudstvo in odšel gor, on in Izraelovi starešine, pred ljudstvo Aja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Vse ljudstvo, celo bojno ljudstvo, ki je bilo z njim, je odšlo gor, se približalo, prišlo pred mesto in se utaborilo na severni strani Aja. Torej tam je bila dolina med njimi in Ajem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Vzel je okoli pet tisoč mož in jih postavil, da ležijo v zasedi med Betelom in Ajem, na zahodni strani mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Ko so postavili ljudstvo, torej vso vojsko, ki je bila na severu mesta in svoje prežavce v zasedi na zahodni strani mesta, je to noč Józue odšel v sredo doline.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Ko je kralj Aja to videl, se je pripetilo, da so pohiteli in zgodaj vstali in možje iz mesta so odšli ven zoper Izraela, da se bojujejo, on in vse njegovo ljudstvo, ob določenem času pred ravnino. Toda ni vedel, da so bili za mestom zoper njega prežavci v zasedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Józue in ves Izrael so se pretvarjali kakor bi bili poraženi pred njimi in pobegnili po poti divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Vse ljudstvo, ki je bilo v Aju, je bilo sklicano skupaj, da jih zasledujejo. Zasledovali so Józueta in bili so pritegnjeni proč iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'V Aju ali v Betelu ni ostal niti mož, ki ne bi odšel ven za Izraelom in mesto so pustili odprto in sledili za Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Gospod je rekel Józuetu: »Iztegni sulico, ki je v tvoji roki, zoper Aj, kajti jaz ga bom dal v tvojo roko.« Józue je zoper mesto iztegnil sulico, ki jo je imel v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Zaseda je hitro vstala iz svojega kraja in stekli so takoj, ko je iztegnil svojo roko. Vstopili so v mesto, ga zavzeli, pohiteli in mesto zažgali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Ko so možje iz Aja pogledali za seboj, so videli in glej, dim iz mesta se je dvigoval proti nebu in niso imeli moči, da pobegnejo to pot ali tisto pot. Ljudstvo, ki je bežalo k divjini, se je obrnilo nazaj proti zasledovalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Ko je Józue in ves Izrael videl, da je zaseda zavzela mesto in da se iz mesta dviguje dim, potem so se ponovno obrnili in usmrtili može iz Aja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'In drugi so izšli iz mesta zoper njih. Tako so bili v sredi Izraela, nekateri na tej strani in nekateri na oni strani in udarili so jih tako, da nobenega izmed njih niso pustili ostati ali pobegniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Kralja Aja so prijeli živega in ga privedli pred Józueta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Ko je Izrael naredil konec pobijanju vseh prebivalcev Aja na polju, v divjini, kjer so jih zasledovali in ko so vsi padli pod ostrino meča, dokler niso bili použiti, se je pripetilo, da so se vsi Izraelci vrnili v Aj in ga udarili z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Bilo je tako, da je bilo vseh, ki so ta dan padli, tako mož in žensk, dvanajst tisoč, torej vsi možje iz Aja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Kajti Józue svoje roke, s katero je iztegnil sulico, ni potegnil nazaj, dokler ni popolnoma uničil vseh prebivalcev Aja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Samo živino in ukradeno blago iz mesta si je Izrael vzel za plen, glede na Gospodovo besedo, ki jo je zapovedal Józuetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Józue je požgal Aj in ga naredil kup na veke, opustošenje do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Ajskega kralja je obesil na drevo do večera in takoj, ko je sonce zašlo, je Józue zapovedal, da njegovo truplo vzamejo dol iz drevesa in ga odvržejo pri vhodu velikih vrat mesta in nad njim naložijo velik kup kamenja, ki ostaja do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Potem je Józue zgradil oltar Gospodu, Izraelovemu Bogu, na gori Ebál,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'kakor je Gospodov služabnik Mojzes zapovedal Izraelovim otrokom, kakor je to zapisano v knjigi Mojzesove postave, oltar iz celih kamnov, nad katere noben človek ni dvignil nobenega železa in na njem so darovali žgalne daritve Gospodu in žrtvovali mirovne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Na kamne je napisal prepis iz Mojzesove postave, ki jo je napisal v prisotnosti Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Ves Izrael, njihove starešine, častniki in njihovi sodniki, so stali na tej strani skrinje in na oni strani, pred duhovniki Lévijevci, ki so nosili skrinjo Gospodove zaveze, kakor tudi tujec, kakor ta, ki je bil rojen med njimi. Polovica izmed njih nasproti gore Garizím in polovica izmed njih nasproti gore Ebál, kakor je Gospodov služabnik Mojzes prej zapovedal, da bodo blagoslovili izraelsko ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Potem je bral vse besede iz postave, blagoslove in prekletstva, glede na vse, kar je zapisano v knjigi postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Ni bilo besede od vsega, kar je Mojzes zapovedal, česar Józue ni prebral pred vso Izraelovo skupnostjo, z ženskami, malčki in tujci, ki so bili seznanjeni med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Pripetilo se je, ko so vsi kralji, ki so bili na tej strani Jordana, na hribih, v dolinah in po vseh pokrajinah vélikega morja nasproti Libanonu, Hetejci, Amoréjci, Kánaanci, Perizéjci, Hivéjci in Jebusejci, slišali o tem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'da so se zbrali skupaj, da se soglasno bojujejo z Józuetom in z Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Ko so prebivalci Gibeóna slišali, kaj je Józue storil Jerihi in Aju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'so prebrisano storili in odšli ter se naredili kakor, da so bili predstavniki in na svoje osle dali stare vreče in vinske mehove, stare in raztrgane ter jih povezali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'in stare čevlje, zakrpane na njihovih stopalih in stare obleke na njih in ves kruh njihove popotnice je bil suh in drobljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Odšli so k Józuetu v tabor pri Gilgálu, in rekli njemu in Izraelovim možem: »Prišli smo iz daljne dežele, zdaj torej sklenite zavezo z nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Možje iz Izraela so rekli Hivéjcem: »Morda prebivate med nami in kako naj sklenemo zavezo z vami?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Ti so Józuetu rekli: »Mi smo tvoji služabniki.« Józue jim je rekel: »Kdo ste? In od kod ste prišli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Rekli so mu: »Iz zelo oddaljene dežele so prišli tvoji služabniki zaradi imena Gospoda, tvojega Boga, kajti slišali smo sloves o njem in vse, kar je storil v Egiptu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'in vse, kar je storil dvema kraljema Amoréjcev, ki sta bila onkraj Jordana, hešbónskemu kralju Sihónu in bašánskemu kralju Ogu, ki je bil pri Aštarótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Zato so nam naši starešine in vsi prebivalci dežele govorili, rekoč: ›S seboj vzemite živež za potovanje in pojdite, da jih srečate in jim recite: ›Mi smo vaši služabniki, zato zdaj sklenite zavezo z nami.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ta naš kruh smo vzeli še vročega za našo popotnico iz naših hiš na dan, ko smo šli, da gremo k vam, toda sedaj, glejte, je ta suh in drobljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Ti vinski mehovi, ki smo jih napolnili, so bili novi, in glejte, raztrgani so. Te naše obleke in naši čevlji so postali stari zaradi razloga zelo dolgega potovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Možje so vzeli od njihovega živeža, niso pa vprašali za nasvet pri Gospodovih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Józue je z njimi sklenil mir in z njimi sklenil zavezo, da jih pusti žive, in princi skupnosti so jim prisegli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Pripetilo pa se je ob koncu treh dni, potem ko so z njimi sklenili zavezo, da so slišali, da so bili njihovi sosedje in da so prebivali med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Izraelovi otroci so odpotovali in na tretji dan prišli v njihova mesta. Torej njihova mesta so bila Gibeón, Kefíra, Beerót in Kirját Jearím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Izraelovi otroci jih niso udarili, ker so jim princi skupnosti prisegli pri Gospodu, Izraelovemu Bogu. In vsa skupnost je godrnjala zoper prince.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Toda vsi princi so vsej skupnosti rekli: »Prisegli smo jim pri Gospodu, Izraelovem Bogu. Sedaj se jih torej ne smemo dotakniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'To jim bomo storili. Celo žive jih bomo pustili, da ne bi bil nad nami bes zaradi prisege, ki smo jim jo prisegli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Princi so jim rekli: »Naj živijo, toda naj bodo drvarji in prinašalci vode vsej skupnosti,« kakor so jim princi obljubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Józue jih je dal poklicati in jim spregovoril, rekoč: »Zakaj ste nas preslepili, rekoč: ›Mi smo zelo daleč od vas,‹ ko prebivate med nami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Zdaj ste torej prekleti in nihče izmed vas naj ne bo prost pred tem, da bi bili sužnji, drvarji in prinašalci vode za hišo mojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Józuetu so odgovorili in rekli: »Ker je bilo tvojim služabnikom zagotovo povedano to, kako je Gospod, tvoj Bog, zapovedal svojemu služabniku Mojzesu, da vam da vso deželo in da pred seboj uničite vse prebivalce dežele, zato smo bili zaradi vas boleče prestrašeni za svoja življenja in smo storili to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'In sedaj glej, mi smo v tvoji roki. Kakor se ti zdi dobro in pravilno, da nam storiš, stôri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Tako jim je storil in jih osvobodil iz roke Izraelovih otrok, da jih niso pobili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Józue jih je ta dan naredil za drvarje in prinašalce vode za skupnost in za Gospodov oltar, celo do tega dne, na kraju, ki bi ga izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Pripetilo se je torej, ko je jeruzalemski kralj Adoní Cedek slišal, kako je Józue zavzel Aj in ga popolnoma uničil; kakor je storil Jerihi in njenemu kralju, tako je storil Aju in njegovemu kralju; in kako so prebivalci Gibeóna sklenili mir z Izraelom in so bili med njimi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'da so se silno bali, ker je bil Gibeón veliko mesto, kakor eno izmed kraljevskih mest in ker je bil večji kakor Aj in vsi njihovi možje so bili mogočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Zato je jeruzalemski kralj Adoní Cedek poslal k Hohámu, kralju v Hebrónu in Pirámu, kralju v Jarmútu in Jafíju, kralju v Lahíšu in Debírju, kralju v Eglónu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '»Pridite gor k meni in mi pomagajte, da bomo lahko udarili Gibeón, kajti ta je sklenil mir z Józuetom in z Izraelovimi otroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Zato se je pet kraljev izmed Amoréjcev, kralj iz Jeruzalema, kralj iz Hebróna, kralj iz Jarmúta, kralj iz Lahíša in kralj iz Eglóna, zbralo skupaj in odšlo gor, oni in vse njihove vojske in se utaborili pred Gibeónom in začeli vojno zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Možje iz Gibeóna so poslali k Józuetu, v tabor pri Gilgálu, rekoč: »Ne odtegni svoje roke od svojih služabnikov. Hitro pridi gor k nam in nas reši in nam pomagaj, kajti vsi kralji Amoréjcev, ki prebivajo po gorah, so skupaj zbrani zoper nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Tako se je Józue vzpel iz Gilgála, on in vse bojno ljudstvo z njim in vsi močni junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Gospod je rekel Józuetu: »Ne boj se jih, kajti izročil sem jih v tvojo roko. Niti mož izmed njih ne bo obstal pred teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Józue je torej nenadoma prišel k njim in vso noč so hodili gor od Gilgála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Gospod jih je porazil pred Izraelom ter jih pri Gibeónu usmrtil z velikim pobojem in jih zasledoval na poti, ki gre gor do Bet Horóna in jih udarjal do Azéke in proti Makédi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Ko so bežali izpred Izraela in so bili pri spuščanju dol k Bet Horónu, se je pripetilo, da je Gospod z neba nanje metal velike kamne do Azéke in so umrli. Bilo jih je več, ki so umrli od kamnite toče, kakor tistih, ki so jih Izraelovi otroci usmrtili z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Potem je Józue spregovoril Gospodu na dan, ko je pred Izraelovimi otroki Gospod izročil Amoréjce in rekel pred očmi Izraela: »Sonce, ti stoj mirno nad Gibeónom in ti luna v dolini Ajalón.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Sonce je stalo mirno in luna je obstala, dokler se ljudstvo ni maščevalo nad svojimi sovražniki. Mar ni to zapisano v Jasherjevi knjigi? Tako je sonce mirno stalo na sredi neba in približno cel dan ni pohitelo, da bi zašlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Pred tem niti za tem ni bilo takšnega dne, da bi Gospod prisluhnil glasu moža, kajti Gospod se je bojeval za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Józue se je vrnil in ves Izrael z njim, k taboru pri Gilgálu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Toda teh pet kraljev je pobegnilo in se skrilo v votlini pri Makédi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'To je bilo povedano Józuetu, rekoč: »Pet kraljev je najdenih skritih v votlini pri Makédi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Józue je rekel: »Na odprtino votline zavalite velike kamne in poleg postavite može, da jih varujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ne stojte, temveč sledite za svojimi sovražniki in udarite najbolj zadnje izmed njih. Ne trpite, da vstopijo v svoja mesta, kajti Gospod, vaš Bog, jih je izročil v vašo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Pripetilo se je, ko so Józue in Izraelovi otroci z zelo velikim pokolom, dokler niso bili použiti, naredili konec njihovemu pobijanju, da je preostanek, ki je preostal izmed njih, vstopil v utrjena mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'In vse ljudstvo se je v miru vrnilo k taboru, k Józuetu, pri Makédi. Nihče ni svojega jezika premaknil zoper kateregakoli izmed Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Potem je Józue rekel: »Odprite odprtino votline in teh pet kraljev privedite k meni, ven iz votline.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Storili so tako in iz votline so k njemu privedli teh pet kraljev, kralja iz Jeruzalema, kralja iz Hebróna, kralja iz Jarmúta, kralja iz Lahíša in kralja iz Eglóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Ko so te kralje privedli k Józuetu, se je pripetilo, da je Józue dal poklicati vse Izraelove može in rekel poveljnikom bojevnikov, ki so odšli z njim: »Pridite bliže, položite svoja stopala na vratove teh kraljev.« Približali so se in svoja stopala položili na njihove vratove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Józue jim je rekel: »Ne bojte se niti ne bodite zaprepadeni, bodite močni in odločnega poguma, kajti tako bo Gospod storil vsem vašim sovražnikom, zoper katere se borite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potem jih je Józue udaril, jih usmrtil in jih obesil na pet dreves; in do večera so viseli na drevesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Ob času zahajanja sonca pa se je pripetilo, da je Józue zapovedal in so jih sneli iz dreves in jih vrgli v votlino, v kateri so bili skriti in na ustje votline so položili velike kamne, ki ostajajo do točno tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Ta dan je Józue zavzel Makédo in jo udaril z ostrino meča in njenega kralja je popolnoma uničil, njih in vse duše, ki so bile tam. Nikogar ni pustil ostati. Kralju v Makédi pa je storil, kakor je storil kralju v Jerihi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Potem je Józue in ves Izrael z njim, prešel od Makéde v Libno in se boril zoper Libno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Tudi njo je Gospod izročil in njenega kralja, v Izraelovo roko. Udaril jo je z ostrino meča in vse duše, ki so bile v njej. Nikogar ni pustil preostati v njej, toda njenemu kralju je storil, kakor je storil kralju Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Józue in ves Izrael z njim, je prešel od Libne do Lahíša in se utaboril zoper njega in se boril zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Gospod je Lahíš izročil v Izraelovo roko, ki so ga zavzeli na drugi dan in ga udaril z ostrino meča in vse duše, ki so bile tam, glede na vse, kar je storil Libni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Potem je prišel gor Horám, kralj v Gezerju, da pomaga Lahíšu, in Józue je udaril njega in njegovo ljudstvo, dokler nikogar ni pustil preostati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Iz Lahíša je Józue prešel do Eglóna in ves Izrael z njim in utaborili so se zoper njega in se borili zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Zavzeli so ga na ta dan in ga udarili z ostrino meča in vse duše, ki so bile tam, je ta dan popolnoma uničil, glede na vse, kar je storil Lahíšu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Józue in ves Izrael z njim, je odšel gor od Eglóna, do Hebróna in so se borili zoper njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'ga zavzeli in udarili z ostrino meča in njihovega kralja in vsa njihova mesta in vse duše, ki so bile v njem. Nikogar ni pustil preostati, glede na vse, kar je storil Eglónu, temveč ga je popolnoma uničil in vse duše, ki so bile v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Józue se je vrnil in ves Izrael z njim, do Debírja in se boril zoper njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'in ga zavzel in njegovega kralja in vsa njegova mesta. Udarili so jih z ostrino meča in popolnoma uničili vse duše, ki so bile v njem. Nikogar ni pustil preostati. Kakor je storil Hebrónu, tako je storil Debírju in njegovemu kralju, kakor je storil tudi Libni in njenemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Tako je Józue udaril vso hribovito deželo, južno [deželo], [deželo] dolin, izvirov in vse njihove kralje. Ničesar ni pustil preostati, temveč je popolnoma uničil vse, kar je dihalo, kakor je zapovedal Gospod, Izraelov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Józue jih je udarjal od Kadeš Barnée, celo do Gaze in vso Gošensko pokrajino, celo do Gibeóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Vse te kralje in njihove dežele je Józue zavzel naenkrat, ker se je Gospod, Izraelov Bog, boril za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'In Józue se je vrnil in ves Izrael z njim, v tabor h Gilgálu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Pripetilo se je, ko je Jabín, kralj iz Hacórja, slišal te stvari, da je poslal k Jobábu, kralju Madóna in h kralju Šimróna in h kralju Ahšáfa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'in h kraljem, ki so bili na severu gora in na ravninah južno od Kinérota in v dolino in na meje Dora na zahodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'in h Kánaancem na vzhodu in na zahodu in k Amoréjcem in k Hetejcem in k Perizéjcem in k Jebusejcem po gorah in k Hivéjcem pod Hermonom v deželi Micpa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'In odšli so ven, oni in vse njihove vojske z njimi, mnogo ljudstva, po številu celo kakor peska, ki je na morski obali, s konji in zelo mnogimi bojnimi vozovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Ko so se vsi ti kralji srečali skupaj, so prišli in se skupaj utaborili pri vodah Meróma, da se borijo zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Gospod je rekel Józuetu: »Ne bodi prestrašen zaradi njih, kajti jutri ob tem času jih bom vse umorjene izročil pred Izraela. Njihovim konjem boš prerezal Ahilove tetive in njihove bojne vozove sežgal z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Tako je zoper njih nenadoma prišel Józue in vse bojno ljudstvo z njim pri vodah Meróa in padli so nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Gospod jih je izročil v roko Izraela, ki jih je udaril in pregnal do vélikega Sidóna in do Misrefót Majima in vzhodno k dolini Micpe in udarjali so jih, dokler niso pustili nikogar preostati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Józue jim je storil, kakor mu je Gospod zaukazal. Njihovim konjem je prerezal Ahilove tetive in njihove bojne vozove zažgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Józue se je ob tistem času obrnil nazaj in zavzel Hacór in njihovega kralja udaril z mečem, kajti Hacór je bil prej poglavar vseh tistih kraljestev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Vse duše, ki so bile v njem, so udarili z ostrino meča; popolnoma so jih uničili, tam ni ostal nihče, da diha. In Hacór je požgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Vsa mesta tistih kraljev in vse kralje izmed njih je Józue zajel in jih udaril z ostrino meča in jih popolnoma uničil, kakor je zapovedal Gospodov služabnik Mojzes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Toda kar se tiče mest, ki so mirovala v svoji moči, pa Izrael ni požgal nobenega izmed njih, razen samo Hacór; ki ga je požgal Józue.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Ves plen teh mest in živino so si Izraelovi otroci vzeli za plen, toda vsakega človeka so udarili z ostrino meča, dokler jih niso uničili niti niso pustili nobenega da diha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Kakor je Gospod zapovedal svojemu služabniku Mojzesu, tako je Mojzes zapovedal Józuetu in tako je storil Józue. Ničesar ni pustil nenarejenega, od vsega, kar je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tako je Józue zavzel vso tisto deželo, hribe in vso južno deželo, vso deželo Gošen, dolino in ravnino, Izraelovo goro in dolino te iste,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'torej od gore Halak, ki gre gor k Seírju, celo do Báal Gada v libanonski dolini pod goro Hermon. Zajel je vse njihove kralje, jih udaril in usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Józue je dolgo časa bojeval vojno z vsemi tistimi kralji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Tam ni bilo mesta, ki bi z Izraelovimi otroki sklenilo mir, razen Hivéjcev, prebivalcev Gibeóna. Vse druge so zavzeli v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Kajti to je bilo od Gospoda, da zakrkne njihova srca, da bi prišli v boj zoper Izrael, da bi jih lahko popolnoma uničil in da ne bi imeli naklonjenosti, temveč da bi jih lahko uničil, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Ob tistem času je prišel Józue in iztrebil Anákovce z gora, iz Hebróna, iz Debírja, iz Anába, iz vseh Judovih gora in iz vseh Izraelovih gora. Józue jih je popolnoma uničil z njihovimi mesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nobeden izmed Anákovcev ni ostal v deželi Izraelovih otrok. Ostali so samo v Gazi, Gatu in v Ašdódu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tako je Józue zavzel celotno deželo, glede na vse, kar je Gospod rekel Mojzesu, in Józue jo je dal za dediščino Izraelu, glede na njihove oddelke po njihovih rodovih. In dežela je počivala pred vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Torej to so kralji dežele, ki so jo Izraelovi otroci udarili in njihovo deželo vzeli v last na drugi strani Jordana, proti sončnemu vzhodu, od reke Arnón, do gore Hermon in vso ravnino na vzhodu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'amoréjski kralj Sihón, ki je prebival v Hešbónu in vladal od Aroêrja, ki je na bregu reke Arnón in od sredine reke in od polovice Gileáda, celo do reke Jabók, kar je meja Amónovih otrok;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'in od ravnine do Kinérotskega morja na vzhodu in do ravninskega morja, torej slanega morja na vzhodu, pot do Bet Ješimóta in od juga pod Ašdód-Pisgo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, '§ Pokrajina bašánskega kralja Oga, ki je bila od preostanka velikanov, ki so prebivali pri Aštarótu in pri Edréi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'in je kraljeval na gori Hermon, v Salhi in po vsem Bašánu, do meje Gešuréjcev in Maahčánov in polovice Gileáda, meje Sihóna, kralja v Hešbónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Te so udarili Gospodov služabnik Mojzes in Izraelovi otroci. Gospodov služabnik Mojzes jo je dal v posest Rubenovcem in Gádovcem in polovici Manásejevega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Ti so kralji dežele, ki so jo Józue in Izraelovi otroci udarili na tej strani Jordana na zahodu, od Báal Gada, v dolini Libanon, celo do gore Halak, ki gre gor k Seírju, ki jo je Józue izročil Izraelovim rodovom za posest, glede na njihove oddelke;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'po gorah, po dolinah, po ravninah, po izvirih, po divjini in po južni deželi: Hetejce, Amoréjce in Kánaance, Perizéjce, Hivéjce in Jebusejce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Kralj Jerihe, eden; kralj Aja, ki je poleg Betela, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'kralj Jeruzalema, eden; kralj Hebróna, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'kralj Jarmúta, eden; kralj Lahíša, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'kralj Eglóna, eden; kralj Gezerja, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'kralj Debírja, eden; kralj Gederja, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'kralj Horme, eden; kralj Aráda, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'kralj Libne, eden; kralj Aduláma, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'kralj Makéde, eden; kralj Betela, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'kralj Tapúaha, eden; kralj Heferja, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'kralj Aféka, eden; kralj Lašaróna, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'kralj Madóna, eden; kralj Hacórja, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'kralj Šimrón Meróna, eden; kralj Ahšáfe, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'kralj Taanáha, eden; kralj Megíde, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'kralj Kedeša, eden; kralj Jokneáma pri Karmelu, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'kralj Dora na Dorovi pokrajini, eden; kralj narodov Gilgála, eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'kralj Tirce, eden; vseh kraljev enaintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Torej Józue je bil star in zvrhan v letih in Gospod mu je rekel: »Star si in zvrhan v letih in tam ostaja še zelo veliko dežele, da bi bila posedena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'To je dežela, ki je še ostala: vse meje Filistejcev in ves Gešur,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'od Šihórja, ki je pred Egiptom, celo do mej severno od Ekróna, ki je štet h Kánaancem; pet filistejskih knezov: Gazejci, Ašdódci, Aškelónci, Gitéjci in Ekrónci; tudi Avéjci;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'od juga, vsa dežela Kánaancev in Mara, ki je poleg Sidóncev, do Aféka, do meja Amoréjcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'in dežela Gebálcev in ves Libanon proti sončnemu vzhodu, od Báal Gada pod goro Hermon do vstopa v Hamát.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Vse prebivalce hribovite dežele, od Libanona do Misrefót Majima in vse Sidónce bom jaz napodil izpred Izraelovih otrok. Samo razdeli jo z žrebom Izraelcem v dediščino, kakor sem ti zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Zdaj torej razdeli to deželo za dediščino vsem devetim rodovom in polovici Manásejevega rodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 's katerimi so Rubenovci in Gádovci prejeli svojo dediščino, ki jim jo je dal Mojzes, onkraj Jordana proti vzhodu, torej kakor jim je dal Gospodov služabnik Mojzes:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'od Aroêrja, ki je na bregu reke Arnón in mesta, ki je na sredi reke in vso ravnino Médebo do Dibóna;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'in vsa mesta amoréjskega kralja Sihóna, ki je kraljeval v Hešbónu, do meje Amónovih otrok;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Gileád in mejo Gešuréjcev in Maahčánov in vse gore Hermona in ves Bašán, do Salhe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, '§ vse Ogovo kraljestvo v Bašánu, ki je kraljeval v Aštarótu in v Edréi, ki je ostalo od preostanka velikanov, kajti te je Mojzes udaril in jih vrgel ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Kljub temu Izraelovi otroci niso pregnali Gešuréjcev niti Maahčánov, temveč Gešuréjci in Maahčáni prebivajo med Izraelci do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Samo Lévijevemu rodu ni dal nobene dediščine. Daritve Gospoda, Izraelovega Boga, narejene z ognjem, so njihova dediščina, kakor jim je rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mojzes je dal rodu Rubenovih otrok dediščino glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Njihova pokrajina je bila od Aroêrja, ki je na bregu reke Arnón in mesto, ki je na sredi reke in vsa ravnina pri Médebi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hešbón in vsa njegova mesta, ki so na ravnini; Dibón in Bamót Báal in Bet Báal Meón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahac, Kedemót, Mefáat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjatájim, Sibmo in Ceret Šahar na gori doline,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bet Peór, Ašdód-Pisgo, Bet Ješimót');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'in vsa mesta ravnine in vse kraljestvo amoréjskega kralja Sihóna, ki je kraljeval v Hešbónu, ki ga je Mojzes udaril z midjánskimi princi Evíjem, Rekemom, Curjem, Hurom in Rebom, ki so bili sihónski vojvode, prebivajoči v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Tudi Beórjevega sina Bileáma, napovedovalca usode, so Izraelovi otroci ubili z mečem med tistimi, ki so jih umorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Meja Rubenovih otrok je bil Jordan in njegova meja. To je bila dediščina Rubenovih otrok po njihovih družinah, mestih in njihovih vaseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Mojzes je dediščino izročil Gadovemu rodu, torej Gadovim otrokom, glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Njihova pokrajina je bila Jazêr in vsa mesta Gileáda in polovica dežele Amónovih otrok, do Aroêrja, ki je pred Rabo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'in od Hešbóna do Ramát Micpéja in Betoníma in od Mahanájima do meje Debírja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'v dolini pa Beth–aram, Bet Nimra, Sukót in Cafón, preostanek kraljestva hešbónskega kralja Sihóna, Jordan in njegova meja, celó do roba Kinéretskega morja na drugi strani Jordana proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'To je dediščina Gadovih otrok po njihovih družinah, mestih in njihovih vaseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mojzes je dal dediščino polovici Manásejevega rodu. To je bila posest polovice rodu Manásejevih otrok po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Njihovo ozemlje je bilo od Mahanájima, ves Bašán, celotno kraljestvo bašánskega kralja Oga in vsa Jaírova mesta, ki so v Bašánu, šestdeset mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Polovica Gileáda, Aštarót in Edréi, mesta Ogovega kraljestva v Bašánu, so pripadla otrokom Mahírja, Manásejevega sina, celo do polovice Mahírjevih otrok po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'To so dežele, ki jih je Mojzes razdelil v dediščino na moábskih planjavah, na drugi strani Jordana, pri Jerihi, proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Toda Lévijevemu rodu Mojzes ni dal nobene dediščine. Gospod, Izraelov Bog, je bil njihova dediščina, kakor jim je rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'To so dežele, ki so jih Izraelovi otroci podedovali v kánaanski deželi, ki so jim jo duhovnik Eleazar, Nunov sin Józue in poglavarji očetov rodov Izraelovih otrok razdelili v dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Njihova dediščina je bila po žrebu, kakor je Gospod zapovedal po Mojzesovi roki, za devet rodov in za polovico rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Kajti Mojzes je na drugi strani Jordana dal dediščino dvema rodovoma in polovici rodu, toda Lévijevcem med njimi ni dal nobene dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Kajti od Jožefovih otrok sta bila dva rodova, Manáse in Efrájim. Zato v deželi niso dali nobenega deleža Lévijevcem, razen mest, da prebivajo v njih, z njihovimi predmestji za njihovo živino in za njihovo imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Kakor je Gospod zapovedal Mojzesu, tako so Izraelovi otroci storili in razdelili so deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Potem so Judovi otroci prišli k Józuetu v Gilgál in Jefunéjev sin Kaléb, Kenázovec, mu je rekel: »Ti poznaš stvar, ki jo je Gospod rekel Božjemu možu Mojzesu glede mene in tebe v Kadeš Barnéi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Štirideset let mi je bilo, ko me je Gospodov služabnik Mojzes poslal iz Kadeš Barnée, da ogledam deželo in ponovno sem mu prinesel besedo, kakor je bila ta v mojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Kljub temu so moji bratje, ki so z menoj odšli gor, ljudstvu stopili srce, toda jaz sem v celoti sledil Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Mojzes je na ta dan prisegel, rekoč: ›Zagotovo bo dežela, ki si jo pomendral s svojimi stopali, tvoja dediščina in tvojih otrok na veke, ker si v celoti sledil Gospodu, mojemu Bogu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Sedaj, glej, Gospod me je obdržal živega, kakor je rekel, teh petinštirideset let, celo odkar je Gospod spregovoril to besedo Mojzesu, medtem ko so Izraelovi otroci tavali po divjini. Sedaj glej, jaz sem danes star petinosemdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Še danes sem tako močan, kakor sem bil na dan, ko me je poslal Mojzes. Kakršna je bila moja moč takrat, celo takšna je moja moč za vojno zdaj, tako za odhajanje kakor za prihajanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Zdaj mi torej daj to goro, o kateri je Gospod govoril na tisti dan, kajti na tisti dan si slišal kako so bili tam Anákovci in da so bila mesta velika in ograjena. Če bo tako, da bo Gospod z menoj, potem jih bom zmožen pognati ven, kakor je rekel Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Józue ga je blagoslovil in Jefunéjevemu sinu Kalébu v dediščino izročil Hebrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Hebrón je torej postal dediščina Jefunéjevega sina Kaléba, Kenázovca, do tega dne, zato ker je v celoti sledil Gospodu, Izraelovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Ime Hebróna je bilo prej Kirját Arba; ta Arbá je bil velik mož med Anákovci. In dežela je imela počitek pred vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'To je bil torej žreb rodu Judovih otrok po njihovih družinah, celó do meje Edóma. Divjina Cin proti jugu je bila najskrajnejši del južne pokrajine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Njihova južna meja je bila od obale slanega morja, od zaliva, ki gleda proti jugu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'in ta je šla ven k južni strani Maleh-Akrabíma in šla vzdolž Cina in se dvignila na južno stran do Kadeš Barnée in šla vzdolž Hecróna in se dvignila do Adárja in po ovinkih šla do Karkoja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Od tam je ta šla proti Acmónu in šla ven k egiptovski reki in izhodi te pokrajine so bili pri morju. To bo vaša južna pokrajina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Vzhodna meja je bila slano morje, celó do konca Jordana. In njihova meja na severni četrtini je bila od morskega zaliva pri najbolj oddaljenem delu Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Meja se je dvignila k Bet Hogli in šla vzdolž ob severu Bet Arábe in meja se je dvignila do kamna Rubenovega sina Bohana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Meja se je iz doline Ahór dvignila proti Debírju in tako proti severu, zroč proti Gilgálu, to je preden se vzpneš k Adumímu, ki je na južni strani reke. Meja je šla proti vodam En Šemeša in njihovi izhodi so bili pri En Rogelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, '§ Meja se je dvignila pri dolini sina Hinómovega k južni strani Jebusejcev; isti je Jeruzalem. Meja se je dvignila k vrhu gore, ki leži pred Hinómovo dolino proti zahodu, ki je pri koncu doline velikanov proti severu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'in meja je bila potegnjena od vrha hriba k vodnemu studencu Neftóaha in šla ven k mestom gore Efróna in meja je bila potegnjena k Baáli, ki je Kirját Jearím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Meja je od Baále zavila proti zahodu, na gorovje Seír in šla vzdolž, do pobočja gore Jearím, ki je Kesalón, na severno stran in se spustila dol k Bet Šemešu in šla naprej do Timne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Meja je šla ven k severni strani Ekróna in meja je bila potegnjena k Šikarónu in šla vzdolž do gore Baálo in šla ven k Jabneéli; in izhodi meje so bili pri morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Zahodna meja je bila do velikega morja in njegove pokrajine. To je pokrajina Judovih otrok naokoli, glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Jefunéjevemu sinu Kalébu je dal delež med Judovimi otroki, glede na Gospodovo zapoved Józuetu, torej mesto Arba, Anákovega očeta, ki je mesto Hebrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaléb je od tam pregnal tri Anákove sinove: Šešája, Ahimána in Talmája, Anákove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Od tam je odšel gor k prebivalcem Debírja. Ime Debírja je bilo prej Kirját Sefer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Kaléb je rekel: »Kdor udari Kirját Sefer in ga zavzame, njemu bom dal svojo hčer Ahso za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Zavzel ga je Kenázov sin Otniél, Kalébov brat in dal mu je svojo hčer Ahso za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Pripetilo se je, ko je prišla k njemu, da ga je primorala, da prosi od svojega očeta polje in razjahala je svojega osla in Kaléb ji je rekel: »Kaj hočeš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Ta je odgovorila: »Daj mi blagoslov, kajti dal si mi južno deželo; daj mi tudi vodne izvire.« In dal ji je gornje izvire in spodnje izvire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'To je dediščina rodu Judovih otrok glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Najbolj oddaljena mesta rodu Judovih otrok proti pokrajini Edóm, proti jugu, so bila: Kabceél, Eder, Jagúr,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimón, Adáda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedeš, Hacór, Jitnán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif, Telem, Bealót,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hacór, Hadáta, Kerijót in Hecrón, ki je Hacór,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amám, Šemaá, Moládaj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hacár Gada, Hešmón, Bet Pelet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hacár Šuál, Beeršéba, Bizjótja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baála, Ijím, Ecem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolád, Kesíl, Horma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ciklág, Madmaná, Sansána,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaót, Šilhím, Ajin in Rimón. Vseh mest je devetindvajset, z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In v dolini Eštaól, Cora, Ašna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanóah, En Ganím, Tapúah, Enájim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmút, Adulám, Sohó, Azéka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Šaarájim, Aditájim, Gedêra in Gederotaim, štirinajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Cenán, Hadáša, Migdál Gad,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilán, Micpa, Jokteél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lahíš, Bockát, Eglón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabón, Lahmás, Kitlíš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederót, Bet Dagón, Naáma in Makéda; šestnajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Ašán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftáh, Ašna, Necíb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keíla, Ahzíb in Marešá; devet mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekrón z njegovimi mesti in njegovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Od Ekróna, celo do morja, vse kar leži blizu Ašdóda, z njegovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Ašdód z njegovimi mesti in njegovimi vasmi, Gaza s svojimi mesti in svojimi vasmi, do egiptovske reke in vélikega morja in njegove meje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Na gorah: Šamír, Jatír, Sohó,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Dana, Kirját Sana, ki je Debír,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anáb, Eštemóa, Aním,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gošen, Holón in Gilo, enajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Aráb, Dumá, Ešán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janúm, Bet Tapúah, Aféka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirját Arba, ki je Hebrón in Ciór, devet mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maón, Karmel, Zif, Juta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezreél, Jokdeám, Zanóah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gíbei in Timna, deset mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhúl, Bet Cur, Gedór,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarát, Bet Anót in Eltekón, šest mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirját Báal, ki je Kirját Jearím in Raba, dve mesti z njunimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'V divjini Bet Arába, Midín, Seháha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibšán, Solno mesto in En Gedi, šest mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Kar se tiče Jebusejcev, prebivalcev Jeruzalema, jih Judovi otroki niso mogli pognati ven, temveč so Jebusejci prebivali z Judovimi otroki pri Jeruzalemu do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Žreb Jožefovih otrok je padel od Jordana pri Jerihi, do vode Jerihe na vzhodu, k divjini, ki gre gor od Jerihe, čez goro Betel');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'in gre iz Betela v Luz in gre vzdolž do meja Arkičanov k Atarótu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'in se spusti zahodno, k pokrajini Jaflétovcev, do pokrajine spodnjega Bet Horóna in do Gezerja in njeni izhodi so pri morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Tako sta Jožefova otroka, Manáse in Efrájim, vzela svojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Meja Efrájimovih sinov, glede na njihove družine, je bila takšna, torej meja njihove dediščine na vzhodni strani je bil Atrót Adár, do gornjega Bet Horóna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'in meja je šla ven proti morju v Mihmetát na severni strani in meja je šla naokoli proti vzhodu v Taanát Šilo in šla poleg njega na vzhodu do Janóaha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'in se spustila od Janóaha k Atarótu in k Naári in prišla k Jerihi in izšla pri Jordanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Meja je potekala od Tapúaha proti zahodu, k reki Kano in njeni izhodi so bili pri morju. To je dediščina rodu Efrájimovih otrok po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Oddvojena mesta za Efrájimove otroke so bila med dediščino Manásejevih otrok, vsa mesta z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Niso pa pregnali Kánaancev, ki so prebivali v Gezerju, temveč so Kánaanci prebivali med Efrájimci do današnjega dne in služili podvrženi plačevanju davka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Tam je bil tudi žreb za Manásejev rod, kajti on je bil Jožefov prvorojenec. Namreč zaradi Manásejevega prvorojenca Mahírja, Gileádovega očeta, ker je bil bojevnik, zato je imel Gileád in Bašán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Tam je bil tudi žreb za preostanek Manásejevih otrok po njihovih družinah za otroke Abiézerja in za otroke Heleka in za otroke Asriéla in za otroke Sihema in za otroke Heferja in za otroke Šemidája. To so bili dečki Manáseja, Jožefovega sina po njihovih družinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Toda Celofhád, sin Heferja, sin Gileáda, sin Mahírja, sin Manáseja, ni imel sinov, temveč hčere. To so imena njegovih hčera: Mahla, Noa, Hogla, Milka in Tirca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Prišle so blizu, pred duhovnika Eleazarja in pred Nunovega sina Józueta in pred prince, rekoč: » Gospod je zapovedal Mojzesu, da nam daste dediščino med našimi brati.« Zato jim je glede na Gospodovo zapoved dal dediščino med brati njihovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Tam je padlo deset deležev Manáseju, poleg gileádske in bašánske dežele, ki sta bili na drugi strani Jordana,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'kajti Manásejeve hčere so imele dediščino med njegovimi sinovi. Preostanek Manásejevih sinov pa je imel deželo Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Manásejeva pokrajina je bila od Aserja do Mihmetáta, ki leži pred Sihemom. Meja je potekala vzdolž desne roke do prebivalcev En Tapúaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Torej Manáse je imel deželo Tapúah, toda Tapúah na Manásejevi meji je pripadal Efrájimovim otrokom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'in pokrajina se je spustila k reki Kano, južno od reke; ta Efrájimova mesta so med Manásejevimi mesti. Tudi Manásejeve pokrajine so bile na severni strani reke in njihovi izhodi so bili pri morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Proti jugu je bilo Efrájimovo in proti severu je bilo Manásejevo in morje je njegova meja in na severu sta se srečala v Aserju in na vzhodu v Isahárju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Manáse je imel v Isahárju in v Aserju Bet Šeán in njegova mesta, Jibleám in njegova mesta, prebivalce Dora in njegova mesta, prebivalce En Dora in njegova mesta, prebivalce Taanáha in njegova mesta in prebivalce Megída ter njegova mesta, torej tri dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Vendar Manásejevi otroci niso mogli napoditi prebivalcev teh mest, temveč so v tej deželi hoteli prebivati Kánaanci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Vendar se je pripetilo, ko so Izraelovi otroci postali močni, da so Kánaance podvrgli davku, toda niso jih popolnoma pognali ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Jožefovi otroci so spregovorili Józuetu, rekoč: »Zakaj si mi dal, da podedujem samo en žreb in en delež, glede na to, da sem veliko ljudstvo, ker me je Gospod doslej blagoslavljal?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Józue jim je odgovoril: »Če si veliko ljudstvo, potem se dvigni v gozdnato deželo in tam posekaj zase, v deželi Perizéjcev in velikanov, če je gora Efrájim zate preozka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Jožefovi otroci so rekli: »Hrib ni dovolj za nas in vsi Kánaanci, ki prebivajo v dolinski deželi, imajo vozove iz železa, tako tisti, ki so iz Bet Šeána in njegovih mest in tisti, ki so iz doline Jezreél.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Józue je spregovoril Jožefovi hiši, torej Efrájimu in Manáseju, rekoč: »Ti si veliko ljudstvo in imaš veliko moč. Ne boš imel samo enega deleža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Toda gora bo tvoja, kajti to je les in ti ga boš posekal in dohodek od tega bo tvoj, kajti napodil boš Kánaance, čeprav imajo železne vozove in čeprav so močni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Celotna skupnost Izraelovih otrok se je zbrala skupaj pri Šilu in tam postavila šotorsko svetišče skupnosti. In dežela je bila podjarmljena pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Tam je med Izraelovimi otroki ostalo sedem rodov, ki še niso prejeli svoje dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Józue je rekel Izraelovim otrokom: »Doklej se obirate, da greste, da vzamete v last deželo, ki vam jo je dal Gospod, Bog vaših očetov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Dajte izmed sebe tri može za vsak rod in poslal jih bom in vstali bodo in šli skozi deželo in jo opisali glede na njihovo dediščino in ponovno bodo prišli k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'To bodo razdelili na sedem delov. Juda bo ostal v svojih pokrajinah na jugu in Jožefova hiša bo ostala v svojih pokrajinah na severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vi boste torej opisali deželo v sedmih delih in opis prinesli sèm k meni, da lahko mečem žrebe za vas tukaj pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Toda Lévijevci nimajo deleža med vami, kajti Gospodovo duhovništvo je njihova dediščina. Gad, Ruben in polovica Manásejevega rodu so prejeli svojo dediščino onkraj Jordana, na vzhodu, ki jim jo je dal Gospodov služabnik Mojzes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Možje so vstali ter odšli stran in Józue jim je naročil, da gredo, da opišejo deželo, rekoč: »Pojdite in hodite skozi deželo in jo opišite in ponovno pridite k meni, da bom tukaj v Šilu za vas lahko vrgel žrebe pred Gospodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Možje so odšli in šli skozi deželo in jo v knjigi opisali po mestih v sedmih delih in ponovno prišli k Józuetu, k vojski pri Šilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Józue je zanje v Šilu metal žrebe pred Gospodom in tam je Józue Izraelovim otrokom razdelil deželo glede na njihove oddelke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Žreb rodu Benjaminovih otrok je prišel gor glede na njihove družine in pokrajina njihovega žreba je prišla naprej med Judovimi otroki in Jožefovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Njihova meja na severni strani je bila od Jordana in meja je šla gor k strani Jerihe na severni strani in se dvigala skozi gore proti zahodu in njeni izhodi so bili pri divjini Bet Aven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Meja je od tam šla preko, proti Luzu, k strani Luza, ki je Betel, proti jugu in meja se je spustila k Atrót Adárju, blizu hriba, ki leži na južni strani spodnjega Bet Horóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Meja je bila potegnjena od tam in obdala vogal morja proti jugu, od hriba, ki leži pred Bet Horónom proti jugu in njihovi izhodi so bili pri Kirját Báalu, ki je Kirját Jearím, mesto Judovih otrok. To je bila zahodna četrtina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Južna četrtina je bila od konca Kirját Jearíma in meja se je nadaljevala na zahod in izšla pri izviru vodá Neftóaha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'in meja se je spustila k vznožju gore, ki leži pred dolino sina Hinómovega in ki je v dolini velikanov na severu in se spustila k Hinómovi dolini, k strani Jebúsa na jugu in se spustila k En Rogelu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'in potegnjena je bila od severa in šla naprej k En Šemešu in šla naprej proti Gelilótu, ki je nasproti vzpona k Adumímu in se spustila h kamnu Rubenovega sina Bohana');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'in šla naprej proti strani nasproti Arábi proti severu in se spustila k Arábi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Meja je šla vzdolž strani Bet Hogle proti severu in izhodi meje so bili pri severnem zalivu slanega morja, pri južnem koncu Jordana. To je bila južna pokrajina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordan je bil njegova meja na vzhodni strani. To je bila dediščina Benjaminovih otrok, po njihovih pokrajinah naokoli, glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Torej mesta rodov Benjaminovih otrok glede na njihove družine so bila Jeriha, Bet Hogla, dolina Kecíc,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bet Arába, Cemarájim, Betel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avím, Para, Ofrá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefár Amoní, Ofní in Gaba, dvanajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeón, Rama, Beerót,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Micpa, Kefíra, Moca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeél, Tarála,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Cela, Elef, Jebús, kar je Jeruzalem, Gíbea in Kirját, štirinajst mest z njihovimi vasmi. To je dediščina Benjaminovih otrok glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Drugi žreb je prišel naprej k Simeonu, torej za rod Simeonovih otrok glede na njihove družine in njihova dediščina je bila znotraj dediščine Judovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'V svoji dediščini so imeli Beeršébo, ali Šebo in Moladáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hacár Šuál, Baálo, Ecem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolád, Betúl, Hormo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ciklág, Bet Markabót, Hacár Susa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bet Lebaót in Šaruhén, trinajst mest in njihove vasi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ajin, Rimón, Eter in Ašán, štiri mesta in njihove vasi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Vse vasi, ki so bile naokoli teh mest do Baalát Beêra, južnega Ramáta. To je dediščina rodu Simeonovih otrok glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Od deleža Judovih otrok je bila dediščina Simeonovih otrok, kajti delež Judovih otrok je bil zanje prevelik, zato so imeli Simeonovi otroci dediščino znotraj njihove dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Tretji žreb je prišel za Zábulonove otroke glede na njihove družine in meja njihove dediščine je bila do Sarída.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Njihova meja se je dvignila proti morju in Maráli in segla do Dabéšeta in segla do reke, ki je pred Jokneámom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'in se obrnila od Saríde vzhodno proti vzhajanju sonca, k meji Kislót Tabora in potem je šla ven do Daberáta in šla gor k Jafíji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'in od tam je šla vzdolž, na vzhodu do Gat Heferja k Et Kacínu in šla ven k Rimón-metoarju do Nea');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'in meja ga je obdala na severni strani do Hanatóna. Njeni izhodi so v dolini Jiftáh El.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Katát, Nahalál, Šimrón, Jidála in Betlehem, dvanajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'To je dediščina Zábulonovih otrok glede na njihove družine, ta mesta z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Četrti žreb je izšel za Isahárja, za Isahárjeve otroke glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Njihova meja je bila proti Jezreélu, Kesulótu, Šunému,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafarájimu, Šiónu, Anaharátu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabítu, Kišjónu, Ebecu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remetu, En Ganímu, En Hadu, Bet Pacécu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'in pokrajina sega do Tabora, Šahacúma in Bet Šemeša. Izhodi njihove meje so bili pri Jordanu, šestnajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'To je dediščina rodu Isahárjevih otrok glede na njihove družine, mesta in njihove vasi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Peti žreb je izšel za rod Aserjevih otrok glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Njihova meja je bila Helkát, Halí, Beten, Ahšáf,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alaméleh, Amád in Mišál in sega do Karmela proti zahodu in do Šihór Libnáta');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'in se obrača proti sončnemu vzhodu do Bet Dagóna in seže do Zábulona in k dolini Jiftáh El, proti severni strani Bet Emeka in Negiéla in gre ven na levi roki do Kabúla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, '§ Hebróna, Rehóba, Hamóna in Kane, celo k velikemu Sidónu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'in potem se pokrajina obrne k Rami in k močnemu mestu Tir in pokrajina se obrne k Hosi. Njeni izhodi so pri morju od pokrajine do Ahzíba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Tudi Uma, Afék in Rehób, dvaindvajset mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'To je dediščina rodu Aserjevih otrok glede na njihove družine, ta mesta z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Šesti žreb je izšel za Neftálijeve otroke, torej za Neftálijeve otroke glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, '§ Njihova pokrajina je bila od Helefa in Alóna do Caananíma in Adame, Nekeba in Jabneéla k Lakú in njeni izhodi so bili pri Jordanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Potem se pokrajina obrne proti zahodu k Aznót Taboru in od tam gre k Hukóku in sega do Zábulona na južni strani in do Aserja na zahodni strani in do Juda nad Jordanom proti sončnemu vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Utrjena mesta so Cidím, Cer, Hamát, Rakát, Kinéret,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adáma, Rama, Hacór,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedeš, Edréi, En Hacór,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jirón, Migdál El, Horém, Bet Anát in Bet Šemeš. Devetnajst mest z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'To je dediščina rodu Neftálijevih otrok glede na njihove družine, mesta in njihove vasi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'In sedmi žreb je izšel za rod Danovih otrok glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Pokrajina njihove dediščine je bila Cora, Eštaól, Ir Šemeš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Šaalbím, Ajalón, Jitla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elón, Timna, Ekrón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteké, Gibetón, Baalát,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehúd, Bené Berák, Gat Rimón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, '§ Me Jarkón in Rakon z mejo pred Jafo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Pokrajina Danovih otrok je zanje izpadla premajhna, zato so Danovi otroci odšli gor, da se bojujejo zoper Lešem, ga zavzeli, ga udarili z ostrino meča, ga vzeli v last in tam prebivali in Lešem imenovali Dan, po imenu njihovega očeta Dana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'To je dediščina rodu Danovih otrok glede na njihove družine, ta mesta z njihovimi vasmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Ko so naredili konec razdeljevanju dežele za dediščino po njihovih pokrajinah, so Izraelovi otroci dali med njimi dediščino Nunovemu sinu Józuetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Glede na Gospodovo besedo so mu dali mesto, ki ga je prosil, torej Timnát Sêrah na gori Efrájim in zgradil je mesto ter tam prebival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'To so dediščine, ki so jih duhovnik Eleazar, Nunov sin Józue in poglavarji očetov rodov Izraelovih otrok v Šilu z žrebom razdelili v dediščino pred Gospodom, pri vratih šotorskega svetišča skupnosti. Tako so naredili konec razdeljevanju dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Gospod je spregovoril tudi Józuetu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '»Govori Izraelovim otrokom, rekoč: ›Izločite si zavetna mesta, o katerih sem ti govoril po Mojzesovi roki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'da ubijalec, ki nenamerno in nevede ubije katerokoli osebo, lahko pobegne tja in ta bodo vaše zatočišče pred krvnim maščevalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Ko bo tisti, ki pobegne v eno izmed teh mest, stal pri vhodu velikih vrat mesta in bo svojo zadevo oznanil v ušesa starešin tega mesta, ga bodo vzeli k sebi v mesto in mu dali prostor, da bo lahko prebival med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Če ga krvni maščevalec zasleduje, potem ubijalca ne bodo izročili v njegovo roko, ker je nevede udaril svojega bližnjega in ga predtem ni sovražil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Prebival bo v tem mestu, dokler ne bo stal pred skupnostjo za sodbo in do smrti vélikega duhovnika, ki bo v tistih dneh. Potem se bo ubijalec vrnil in prišel v svoje lastno mesto in v svojo lastno hišo v mesto, iz katerega je pobegnil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Določili so Kedeš v Galileji, na gori Neftáli in Sihem na gori Efrájim in Kirját Arbo, ki je Hebrón, na Judovi gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Na drugi strani Jordana, pri Jerihi, proti vzhodu, so v divjini, na ravnini, določili Becer od Rubenovega rodu in Ramót v Gileádu od Gadovega rodu in Golán v Bašánu od Manásejevega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'To so bila mesta, določena za vse Izraelove otroke in za tujca, ki začasno biva med njimi, da kdorkoli nenamerno ubije katerokoli osebo, lahko pobegne tja in ne umre po roki krvnega maščevalca, dokler ta stoji pred skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Potem so se približali poglavarji očetov Lévijevcev k duhovniku Eleazarju in k Nunovemu sinu Józuetu in k poglavarjem očetov rodov Izraelovih otrok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'in jim govorili pri Šilu v kánaanski deželi, rekoč: » Gospod je po Mojzesovi roki zapovedal, da nam daste mesta, da prebivamo v [njih], z njihovimi predmestji, za našo živino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Izraelovi otroci so na Gospodovo zapoved dali Lévijevcem od svoje dediščine ta mesta in njihova predmestja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Žreb je izšel za družine Kehátovcev in otroci duhovnika Arona, ki so bili izmed Lévijevcev, so imeli po žrebu od Judovega rodu, od Simeonovega rodu in od Benjaminovega rodu trinajst mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Preostali Kehátovi otroci so imeli po žrebu deset mest od družin iz Efrájimovega rodu, iz Danovega rodu in iz polovice Manásejevega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Geršónovi otroci so imeli po žrebu trinajst mest od Isahárjevega rodu, od Aserjevega rodu, od Neftálijevega rodu in od polovice Manásejevega rodu v Bašánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Meraríjevi otroci po njihovih družinah so imeli dvanajst mest od Rubenovega rodu, od Gadovega rodu in od Zábulonovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Izraelovi otroci so po žrebu dali Lévijevcem ta mesta z njihovimi predmestji, kakor je Gospod zapovedal po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Ta mesta so dali od Judovega rodu in od Simeonovega rodu, ta mesta, ki so tukaj omenjena po imenu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'ki so jih imeli Aronovi otroci, ki so iz družine Kehátovcev, ki so bili izmed Lévijevih otrok, kajti njihov je bil prvi žreb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Dali so jim mesto Arbá od Anákovega očeta; to mesto je Hebrón na hriboviti Judovi deželi, s predmestji okoli njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Toda polja mesta in njegove vasi so dali Jefunéjevemu sinu Kalébu za njegovo posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Tako so dali otrokom duhovnika Arona Hebrón z njegovimi predmestji, da bi bil zavetno mesto za ubijalca in Libno z njenimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatír z njegovimi predmestji, Eštemóa z njenimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holón z njegovimi predmestji, Debír z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ajin z njegovimi predmestji, Juto z njenimi predmestji in Bet Šemeš z njegovimi predmestji; devet mest od teh dveh rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Iz Benjaminovega rodu Gibeón z njegovimi predmestji, Gebo z njenimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatót z njegovimi predmestji in Almon z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Vseh mest Aronovih otrok, duhovnikov, je bilo trinajst mest z njihovimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Družine Kehátovih otrok, Lévijevci, ki so ostali izmed Kehátovih otrok, celo oni so imeli mesta od svojega žreba od Efrájimovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Kajti dali so jim Sihem z njegovimi predmestji na gori Efrájim, da bo zavetno mesto za ubijalca, Gezer z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibcájim z njegovimi predmestji in Bet Horón z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Od Danovega rodu, Elteké z njegovimi predmestji, Gibetón z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalón z njegovimi predmestji in Gat Rimón z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Od polovice Manásejevega rodu Taanáh z njegovimi predmestji in Gat Rimón z njegovimi predmestji; dve mesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Vseh mest je bilo deset, z njihovimi predmestji za družine Kehátovih otrok, ki so preostali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Geršónovim otrokom iz družin Lévijevcev, iz druge polovice rodu Manáseja, so dali Golán v Bašánu z njegovimi predmestji, da bo zavetno mesto za ubijalca in Beastero z njenimi predmestji; dve mesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Iz Isahárjevega rodu Kišón z njegovimi predmestji, Daberát z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmút z njegovimi predmestji in En Ganím z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Iz Aserjevega rodu Mišál z njegovimi predmestji, Abdón z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkát z njegovimi predmestji in Rehób z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Iz Neftálijevega rodu Kedeš v Galileji z njegovimi predmestji, da bo zavetno mesto za ubijalca, Hamót Dor z njegovimi predmestji in Kartán z njegovimi predmestji; tri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Vseh mest Geršónovcev, glede na njihove družine, je bilo trinajst mest z njihovimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Družinam Meraríjevih otrok, preostanku Lévijevcev iz Zábulonovega rodu, Jokneám z njegovimi predmestji, Kartán z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimno z njenimi predmestji in Nahalál z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Iz Rubenovega rodu Becer z njegovimi predmestji, Jahac z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemót z njegovimi predmestji in Mefáat z njegovimi predmestji; štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Iz Gadovega rodu Ramót v Gileádu z njegovimi predmestji, da bo zavetno mesto za ubijalca, Mahanájim z njegovimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hešbón z njegovimi predmestji in Jazêr z njegovimi predmestji; skupaj štiri mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Tako je bilo vseh mest za Meraríjeve otroke po njihovih družinah, ki so bili preostanek družin Lévijevcev, po njihovem žrebu, dvanajst mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Vseh mest Lévijevcev, znotraj posesti Izraelovih otrok je bilo oseminštirideset mest z njihovimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Ta mesta so bila vsako s svojimi predmestji naokoli njih; tako so bila vsa ta mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Gospod je dal Izraelu vso deželo, ki jo je prisegel, da jo da njihovim očetom in vzeli so jo v last in v njej prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Gospod jim je dal počitek naokoli, glede na vse, kar je prisegel njihovim očetom in pred njimi ni obstal niti mož izmed vseh njihovih sovražnikov; Gospod je vse njihove sovražnike izročil v njihovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Tam ni manjkala nobena dobra stvar, ki jo je Gospod govoril Izraelovi hiši; vse so se izpolnile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Potem je Józue poklical Rubenovce, Gádovce in polovico Manásejevega rodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'ter jim rekel: »Držali ste se vsega, kar vam je Gospodov služabnik Mojzes zapovedal in moj glas ste ubogali v vsem, kar sem vam zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Te mnoge dni do tega dne niste zapustili svojih bratov, temveč ste skrbeli za zapoved Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Sedaj je Gospod, vaš Bog, dal počitek vašim bratom, kakor jim je obljubil, zato se sedaj vrnite in se odpravite v svoje šotore in v deželo svoje posesti, ki vam jo je dal Gospodov služabnik Mojzes na drugi strani Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Toda marljivo pazite, da izpolnite zapoved in postavo, ki vam jo je zapovedal Gospodov služabnik Mojzes, da ljubite Gospoda, svojega Boga in da hodite po vseh njegovih poteh in se držite njegovih zapovedi in da se mu trdno pridružite in mu služite z vsem svojim srcem in z vso svojo dušo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Tako jih je Józue blagoslovil in jih poslal proč; in odšli so k svojim šotorom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Torej eni polovici Manásejevega rodu je Mojzes dal posest v Bašánu, toda drugi njegovi polovici je Józue dal [posest] med njihovimi brati na tej strani Jordana proti zahodu. Ko je Józue tudi njih poslal proč, v njihove šotore, tedaj jih je blagoslovil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'in jim govoril, rekoč: »V svoje šotore se vrnite z mnogimi bogastvi in z zelo veliko živine, s srebrom in z zlatom, z bronom in z železom in z zelo mnogimi oblačili. Plen svojih sovražnikov razdelite s svojimi brati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Rubenovi otroci in Gadovi otroci in polovica Manásejevega rodu se je vrnila in odpotovala od Izraelovih otrok iz Šila, ki je v kánaanski deželi, da gredo v deželo Gileád, k zemlji njihove posesti, ki so jo vzeli v last, glede na Gospodovo besedo, po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Ko so prišli k mejam Jordana, ki so v kánaanski deželi, so Rubenovi otroci in Gadovi otroci in polovica Manásejevega rodu tam zgradili oltar pri Jordanu, na pogled velik oltar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Izraelovi otroci so slišali reči: »Glejte, Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu so zgradili oltar nasproti kánaanski deželi, na mejah Jordana, ob prehodu Izraelovih otrok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Ko so Izraelovi otroci slišali o tem, se je celotna skupnost Izraelovih otrok skupaj zbrala pri Šilu, da gredo gor, da se vojskujejo proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Izraelovi otroci so k Rubenovim otrokom, h Gadovim otrokom in k polovici Manásejevega rodu v deželo Gileád poslali Pinhása, sina duhovnika Eleazarja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'in z njim deset princev, iz vsake vodilne hiše princa, po vseh Izraelovih rodovih in vsak je bil poglavar svoje očetovske hiše med tisočerimi Izraelovimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Prišli so k Rubenovim otrokom, h Gadovim otrokom in k polovici Manásejevega rodu, v deželo Gileád in z njimi govorili, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '»Tako govori celotna Gospodova skupnost: ›Kakšen prekršek je to, kar ste zagrešili zoper Izraelovega Boga, da se ta dan odvračate od sledenja Gospodu, v tem, da ste si zgradili oltar, da bi se ta dan lahko uprli zoper Gospoda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Mar je krivičnost Peórja premajhna za nas, od katere do tega dne nismo očiščeni, čeprav je bila nadloga v Gospodovi skupnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'temveč da ste se ta dan morali odvrniti od sledenja Gospodu? Zgodilo se bo, glede na to, da ste se ta dan uprli zoper Gospoda, da bo jutri ogorčen nad celotno Izraelovo skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Vendar če je dežela vaše posesti nečista, potem prečkajte v deželo Gospodove posesti, v kateri prebiva Gospodovo šotorsko svetišče in vzemite posest med nami, toda ne uprite se zoper Gospoda niti se ne uprite zoper nas v tem, da si gradite oltar poleg oltarja Gospoda, našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Mar ni Zerahov sin Ahán zagrešil prekršek v prekleti stvari in je bes padel na vso Izraelovo skupnost? In ta mož v svoji krivičnosti ni umrl sam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Potem so Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu odgovorili in rekli poglavarjem tisočerih Izraelovih:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '» Gospod, Bog bogov, Gospod, Bog bogov, on ve in Izrael bo vedel. Če je to v uporu ali če je v prestopku zoper Gospoda (ta dan nas ne reši),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'da smo si zgradili oltar, da se obrnemo od sledenja Gospodu, ali če na njem darujemo žgalno daritev ali jedilno daritev ali če na njem žrtvujejo mirovne daritve, naj sam Gospod to zahteva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'in če nismo tega raje storili zaradi strahu pred to stvarjo, rekoč: ›V času, ki pride, bodo vaši otroci lahko govorili našim otrokom, rekoč: ›Kaj imate z Gospodom, Izraelovim Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Kajti Gospod je naredil Jordan za mejo med nami in vami, vi Rubenovi otroci in Gadovi otroci, vi nimate deleža v Gospodu.‹‹ Tako bodo vaši otroci naredili našim otrokom, da se prenehajo bati Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Zato smo rekli: ›Pripravimo se, da si zgradimo oltar, ne za žgalno daritev niti za klavno daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'temveč, da bo ta lahko priča med nami in vami in našimi rodovi za nami, da bomo lahko pred njim opravljali Gospodovo službo s svojimi žgalnimi daritvami, svojimi klavnimi daritvami in s svojimi mirovnimi daritvami,‹ da v času, ki pride, vaši otroci ne bodo mogli reči našim otrokom: ›Vi nimate deleža v Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Zato smo rekli, da bo tako, ko bodo tako rekli nam ali našim rodovom, v času, ki pride, da bomo lahko ponovno rekli: ›Glejte vzorec Gospodovega oltarja, ki so ga naredili naši očetje, niti za žgalne daritve, niti za klavne daritve, temveč je ta priča med vami in nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Bog ne daj, da bi se uprli zoper Gospoda in se ta dan obrnili od sledenja Gospodu, da zgradimo oltar za žgalne daritve, za jedilne daritve ali za klavne daritve, poleg oltarja Gospoda, našega Boga, ki je pred njegovim šotorskim svetiščem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Ko so duhovnik Pinhás in princi skupnosti in poglavarji tisočerih Izraelovih, ki so bili z njim, slišali besede, ki so jih Rubenovi otroci, Gadovi otroci in Manásejevi otroci govorili, jim je to ugajalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'In Pinhás, sin duhovnika Eleazarja, je rekel Rubenovim otrokom, Gadovim otrokom in Manásejevim otrokom: »Ta dan smo zaznali, da je med nami Gospod, zato ker tega prekrška niste zagrešili zoper Gospoda. Sedaj ste Izraelove otroke osvobodili iz Gospodove roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Pinhás, sin duhovnika Eleazarja in princi so se vrnili od Rubenovih otrok in od Gadovih otrok iz dežele Gileád v kánaansko deželo, k Izraelovim otrokom in jim ponovno prinesli besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Stvar je ugajala Izraelovim otrokom in Izraelovi otroci so blagoslovili Boga in niso nameravali iti gor zoper njih v bitko, da bi uničili deželo, v kateri so prebivali otroci Rubena in Gada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Rubenovi otroci in Gadovi otroci pa so oltar imenovali Ed, kajti ta bo priča med nami, da Gospod je Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Pripetilo se je, dolgo časa po tem, ko je Gospod dal počitek Izraelu pred vsemi njegovimi sovražniki naokoli, da je Józue postal star in zvrhan v starosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Józue je dal poklicati ves Izrael in po njihove starešine, po njihove poglavarje, po njihove sodnike, po njihove častnike ter jim rekel: »Star sem in zvrhan v starosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Videli ste vse, kar je Gospod, vaš Bog, zaradi vas storil vsem tem narodom, kajti Gospod, vaš Bog, je ta, ki se je boril za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Glejte, z žrebom sem vam razdelil vse te narode, ki preostajajo, da bodo dediščina za vaše rodove, od Jordana, z vsemi narodi, ki sem jih iztrebil, celo do vélikega morja proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Gospod, vaš Bog, jih bo pregnal izpred vas in jih pognal iz vašega pogleda in vi boste vzeli v last njihovo deželo, kakor vam je Gospod, vaš Bog, obljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Bodite torej zelo pogumni, da se držite in da storite vse, kar je zapisano v knjigi Mojzesove postave, da se ne obrnete vstran od tam ne k desni roki ne k levi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'da ne pridete med te narode, te, ki preostajajo med vami, niti ne omenjajte imena njihovih bogov, niti ne povzročajte, da prisegate pri njih, niti jim ne služite, niti se jim ne priklanjajte,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'temveč se trdno pridružite Gospodu, svojemu Bogu, kakor ste storili ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Kajti Gospod je izpred vas pregnal velike in močne narode, toda glede vas, noben človek ni mogel obstati pred vami do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'En mož med vami jih bo pregnal tisoč, kajti Gospod, vaš Bog, on je ta, ki se bori za vas, kakor vam je obljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Pazite torej nase, da ljubite Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Sicer če boste na kakršenkoli način šli nazaj in se trdno pridružili preostanku teh narodov, torej tem, ki preostajajo med vami in boste z njimi sklepali poroke in šli noter k njim in oni k vam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'zagotovo vedite, da Gospod, vaš Bog, izpred vas ne bo več pregnal nobenega izmed teh narodov, temveč vam bodo zanke, pasti in nadloge na vaših straneh in trni v vaših očeh, dokler ne izginete iz te dobre dežele, ki vam jo je dal Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Glejte, ta dan grem pot vse zemlje in vi veste v vseh svojih srcih in v vseh svojih dušah, da se ni izjalovila niti ena od vseh dobrih stvari, ki jih je Gospod, vaš Bog, govoril glede vas. Vse so se vam zgodile in niti ena stvar od tega se ni izjalovila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Zato se bo zgodilo, da kakor vse dobre stvari, ki so prišle nad vas, ki vam jih je Gospod, vaš Bog, obljubil, tako bo Gospod nad vas privedel vse zle stvari, dokler vas ne uniči iz te dobre dežele, ki vam jo je dal Gospod, vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ko ste prekršili zavezo Gospoda, svojega Boga, ki vam jo je zapovedal in šli ter služili drugim bogovom in se jim priklanjali, potem bo zoper vas vžgana Gospodova jeza in hitro boste izginili iz dobre dežele, ki vam jo je dal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Józue je vse Izraelove rodove zbral v Sihem in dal poklicati po Izraelove starešine, po njihove poglavarje, po njihove sodnike in po njihove častnike in postavili so se pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Józue je vsemu ljudstvu rekel: »Tako govori Gospod, Izraelov Bog: ›Vaši očetje so v starih časih prebivali na drugi strani vèleréke, torej Terah, Abrahamov oče in Nahórjev oče in služili drugim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Vzel sem vašega očeta Abrahama iz druge strani vèleréke in ga vodil skozi vso kánaansko deželo in pomnožil njegovo seme in mu dal Izaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Izaku sem dal Jakoba in Ezava. Ezavu sem dal gorovje Seír, da ga vzame v last, toda Jakob in njegovi otroci so odšli dol v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Poslal sem tudi Mojzesa in Arona in Egipt udaril z nadlogami, glede na to, kar sem storil med njimi in potem sem vas privedel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Vaše očete sem privedel iz Egipta in prišli ste k morju. Egipčani so vaše očete zasledovali z bojnimi vozovi in konjeniki do Rdečega morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Ko so klicali h Gospodu, je med vas in Egipčane postavil temo in nadnje privedel morje in jih pokril. Vaše oči so videle, kar sem storil v Egiptu in v divjini ste prebivali dolgo obdobje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Privedel sem vas v deželo Amoréjcev, ki so prebivali na drugi strani Jordana. Borili so se z vami in izročil sem jih v vašo roko, da bi lahko vzeli v last njihovo deželo in uničil sem jih izpred vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Potem je Balák, Cipórjev sin, moábski kralj, vstal in se bojeval zoper Izrael in poslal ter poklical Beórjevega sina Bileáma, da vas prekolne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'toda nisem hotel prisluhniti Bileámu, zato vas je mirno blagoslovil. Tako sem vas osvobodil iz njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Odšli ste čez Jordan in prišli do Jerihe. Zoper vas so se borili možje iz Jerihe [in] Amoréjci, Perizéjci, Kánaanci, Hetejci, Girgašéjci, Hivéjci in Jebusejci in izročil sem jih v vašo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Pred vami sem poslal sršena, ki jih je pregnal izpred vas, celó dva kralja Amoréjcev, toda ne s tvojim mečem niti ne s tvojim lokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Dal sem vam deželo, za katero se niste trudili in mesta, ki jih niste zgradili, in vi prebivate v njih in jeste od vinogradov in oljčnih nasadov, ki jih niste sadili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Zdaj se torej bojte Gospoda in mu služite v iskrenosti in resnici in odstranite bogove, ki so jim služili vaši očetje na drugi strani vèleréke in v Egiptu in služite Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Če pa se vam to zdi zlo, da služite Gospodu, ta dan izberite komu boste služili: ali bogovom, ki so jim služili vaši očetje, ki so bili na drugi strani vèleréke, ali bogovom Amoréjcev, v čigar deželi prebivate. Toda kar se tiče mene in moje hiše, mi bomo služili Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Ljudstvo je odgovorilo in reklo: »Bog ne daj, da bi zapustili Gospoda, da služimo drugim bogovom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'kajti Gospod, naš Bog, on je ta, ki je nas in naše očete privedel gor iz egiptovske dežele, iz hiše sužnosti in ki je storil ta velika znamenja v našem pogledu in nas varoval po vsej poti, po kateri smo šli, in med vsem ljudstvom, skozi katero smo šli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Gospod je izpred nas pregnal vse ljudstvo, celo Amoréjce, ki prebivajo v deželi. Zato bomo tudi služili Gospodu, kajti on je naš Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Józue je rekel ljudstvu: »Ne morete služiti Gospodu, kajti on je svet Bog; ljubosumen Bog je; ne bo odpustil vaših prestopkov niti vaših grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Če zapustite Gospoda in služite tujim bogovom, potem se bo obrnil in vas prizadel in vas použil, potem ko vam je storil dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Ljudstvo je Józuetu reklo: »Ne, temveč bomo služili Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Józue je ljudstvu rekel: »Vi ste priče zoper vas same, da ste izbrali Gospoda, da mu služite.« Rekli so: » Mi smo priče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '»Zdaj torej odstranite,« je rekel, »tuje bogove, ki so med vami in svoje srce nagnite h Gospodu, Izraelovemu Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Ljudstvo je Józuetu reklo: » Gospodu, našemu Bogu, bomo služili in njegov glas bomo ubogali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Tako je Józue tega dne sklenil zavezo z ljudstvom in jim postavil zakon in odredbo v Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Józue je te besede zapisal v knjigo Božje postave in vzel velik kamen in ga tam postavil pod hrast, ki je bil poleg Gospodovega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Józue je vsemu ljudstvu rekel: »Glejte, ta kamen nam bo priča, kajti ta je slišal vse Gospodove besede, ki nam jih je govoril. Ta vam bo zato priča, da ne bi zatajili svojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Tako je Józue ljudstvu pustil oditi, vsakemu možu v svojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Po vseh teh stvareh se je pripetilo, da je Nunov sin Józue, Gospodov služabnik, umrl, star sto deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Pokopali so ga na meji njegove dediščine, v Timnát Serahu, ki je na gori Efrájim, na severni strani Gáaševega hriba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Izrael je služil Gospodu vse Józuetove dni in vse dni starešin, ki so preživeli Józueta in ki so poznali vsa Gospodova dela, ki jih je storil za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Jožefove kosti, ki so jih Izraelovi otroci prinesli gor iz Egipta, so pokopali v Sihemu, na parceli zemlje, ki jo je Jakob kupil od sinov Hamórja, Sihemovega očeta, za sto koščkov srebra in ta je postala dediščina Jožefovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Aronov sin Eleazar je umrl in pokopali so ga na hribu, ki pripada njegovemu sinu Pinhásu, ki mu je bil dan na gori Efrájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Torej po Józuetovi smrti se je pripetilo, da so Izraelovi otroci vprašali Gospoda, rekoč: »Kdo bo za nas najprej šel gor zoper Kánaance, da se bori zoper njih?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Gospod je rekel: »Juda bo šel gor. Glejte, deželo sem izročil v njegovo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Juda je svojemu bratu Simeonu rekel: »Pridi gor z menoj v moj žreb, da se bova lahko borila zoper Kánaance in prav tako bom tudi jaz šel s teboj v tvoj žreb.« Tako je Simeon odšel z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juda je odšel gor in Gospod je Kánaance in Perizéjce izročil v njuno roko in izmed njih sta v Bezeku usmrtila deset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'V Bezeku sta našla Adoní Bezeka in se borila zoper njega ter usmrtila Kánaance in Perizéjce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Toda Adoní Bezek je pobegnil in sledila sta za njim, ga ujela ter odsekala njegova palca in velika prsta na njegovih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Adoní Bezek je rekel: »Sedemdeset kraljev, ki imajo odsekane svoje palce in svoje palce na stopalih, je svojo hrano pobiralo pod mojo mizo. Kakor sem jaz storil, tako mi je Bog poplačal.« In odvedla sta ga v Jeruzalem in tam je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Torej Judovi otroci so se borili zoper Jeruzalem, ga zavzeli, udarili z ostrino meča in zažgali mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potem so Judovi otroci odšli dol, da se borijo zoper Kánaance, ki prebivajo na gori, na jugu in v dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Juda je odšel zoper Kánaance, ki prebivajo v Hebrónu (torej ime Hebróna je bilo prej Kirját Arba) in usmrtili so Šešája, Ahimána in Talmája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Od tam je odšel zoper prebivalce Debírja. Ime Debírja pa je bilo prej Kirját Sefer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Kaléb je rekel: »Kdor udari Kirját Sefer in ga zavzame, njemu bom dal svojo hčer Ahso za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Zavzel ga je Kenázov sin Otniél, Kalébov mlajši brat in dal mu je svojo hčer Ahso za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Ko je prišla k njemu se je pripetilo, da ga je primorala, da prosi od svojega očeta polje in razjahala je svojega osla in Kaléb ji je rekel: »Kaj hočeš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Rekla mu je: »Daj mi blagoslov, kajti dal si mi južno deželo; daj mi tudi vodne izvire.« In Kaléb ji je dal gornje izvire in spodnje izvire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Otroci Kenéjca, Mojzesovega tasta, so z Judovimi otroki odšli gor iz mesta palmovih dreves v Judovo divjino, ki leži na jugu Aráda in odšli so ter prebivali med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Juda je odšel s svojim bratom Simeonom in usmrtili so Kánaance, ki naseljujejo Cefát in ga popolnoma uničili. Ime mesta se je imenovalo Horma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juda je zavzel tudi Gazo z njenimi pokrajinami, Aškelón z njegovimi pokrajinami in Ekrón z njegovimi pokrajinami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Gospod je bil z Judom in napodil je prebivalce gore, toda ni mogel napoditi prebivalcev doline, ker so imeli železne vozove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Hebrón so dali Kalébu, kakor je rekel Mojzes, in od tam je izgnal tri Anákove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Benjaminovi otroci pa niso napodili Jebusejcev, ki so naseljevali Jeruzalem, temveč Jebusejci prebivajo z Benjaminovimi otroki v Jeruzalemu do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Jožefova hiša, tudi oni so se dvignili zoper Betel in Gospod je bil z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Jožefova hiša je poslala, da razišče Betel. (Torej ime mesta je bilo prej Luz.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Ogledniki so videli moža priti iz mesta in mu rekli: »Pokaži nam, prosimo te, vhod v mesto, mi pa ti bomo izkazali usmiljenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Ko jim je ta pokazal vhod v mesto, potem so mesto udarili z ostrino meča, toda spustili so moža in vso njegovo družino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Mož je odšel v deželo Hetejcev, zgradil mesto in njegovo ime imenoval Luz, kar je njegovo ime do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Niti Manáse ni napodil prebivalcev Bet Šeána in njegovih mest, niti Taanáha in njegovih mest, niti prebivalcev Dora in njegovih mest, niti prebivalcev Jibleáma in njegovih mest, niti prebivalcev Megída in njenih mest, temveč so Kánaanci hoteli prebivati v tej deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Pripetilo se je, ko je bil Izrael močan, da so Kánaance podvrgli davku, niso pa jih popolnoma pognali ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Niti ni Efrájim napodil Kánaancev, ki prebivajo v Gezerju, temveč Kánaanci prebivajo med njimi v Gezerju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Niti ni Zábulon napodil prebivalcev Kitróna niti prebivalcev Nahalóla, temveč so Kánaanci prebivali med njimi in postali so davkoplačevalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Niti ni Aser napodil prebivalcev Aka, niti prebivalcev Sidóna, niti Ahalaba, niti Ahzíba, niti Helbe, niti Aféke, niti Rehóba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'temveč so Aserjevci prebivali med Kánaanci, prebivalci dežele, kajti niso jih pognali ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Niti ni Neftáli napodil prebivalcev Bet Šemeša niti prebivalcev Bet Anáta, temveč je prebival med Kánaanci, prebivalci dežele. Kljub temu so jim prebivalci Bet Šemeša in Bet Anáta postali davkoplačevalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amoréjci pa so Danove otroke potisnili na goro, kajti niso jim hoteli pustiti, da pridejo dol k dolini,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'temveč so Amoréjci hoteli prebivati na gori Heres v Ajalónu in v Šaalbímu. Vendar je roka Jožefove hiše prevladala, tako da so postali davkoplačevalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Pokrajina Amoréjcev je bila od vzpona k Akrabímu, od skale in navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Gospodov angel je prišel gor od Gilgála k Bohímu in rekel: »Primoral sem vas iti gor, ven iz Egipta in vas privedel v deželo, ki sem jo prisegel vašim očetom. Rekel sem: ›Nikoli ne bom prelomil svoje zaveze z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'In vi ne boste sklenili nobene zaveze s prebivalci te dežele; zrušili boste njihove oltarje.‹ Toda niste ubogali mojega glasu. Zakaj ste to storili?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Zato sem tudi rekel: ›Ne bom jih pognal izpred vas, temveč vam bodo kakor trni na vaših straneh in njihovi bogovi vam bodo zanka.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Pripetilo se je, ko je Gospodov angel te besede povedal vsem Izraelovim otrokom, da je ljudstvo povzdignilo svoj glas in zajokalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Ime tega kraja so imenovali Bohím in tam so darovali Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Ko je Józue pustil ljudstvu oditi, so Izraelovi otroci odšli, vsak mož v svojo dediščino, da deželo vzamejo v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Ljudstvo je služilo Gospodu vse Józuetove dni in vse dni starešin, ki so preživeli Józueta, ki so videli vsa velika Gospodova dela, ki jih je storil za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Nunov sin Józue, Gospodov služabnik, je umrl, star sto deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Pokopali so ga na meji njegove dediščine, v Timnát Heresu, na gori Efrájim, na severni strani Gáaševega hriba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Tudi ves ta rod je bil zbran k svojim očetom in tam je za njimi vstal drug rod, ki ni poznal Gospoda niti še ne del, ki jih je ta storil za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Izraelovi otroci so počeli zlo v Gospodovih očeh in služili Báalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Zapustili so Gospoda, Boga svojih očetov, ki jih je privedel iz egiptovske dežele in sledili drugim bogovom, bogovom ljudstev, ki so bili okoli njih, se jim priklanjali in Gospoda izzivali k jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Zapustili so Gospoda in služili Báalu in Astarti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Gospodova jeza je bila vroča zoper Izrael in izročil jih je v roke plenilcev, ki so jih oplenili in jih prodal v roke njihovih sovražnikov naokoli, tako da ne bi mogli več obstati pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Kamorkoli so odšli, je bila zoper njih Gospodova roka za zlo, kakor je Gospod rekel in kakor jim je Gospod prisegel. Bili so silno stiskani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Kljub temu je Gospod dvignil sodnike, ki so jih osvobajali iz roke tistih, ki so jih plenili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Vendar niso hoteli prisluhniti svojim sodnikom, temveč so se odšli vlačugat za drugimi bogovi in se jim priklanjali. Hitro so se obrnili iz poti, po kateri so hodili njihovi očetje z uboganjem Gospodovih zapovedi, toda oni niso tako storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Ko jim je Gospod dvignil sodnike, potem je bil Gospod s sodnikom in jih vse sodnikove dni osvobajal iz roke njihovih sovražnikov, kajti to je pokesalo Gospoda zaradi njihovega stokanja, zaradi razloga tistih, ki so jih zatirali in jih slabili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Pripetilo pa se je, ko je bil sodnik mrtev, da so se vrnili in se izpridili bolj kakor njihovi očetje v sledenju drugim bogovom, da jim služijo in se jim priklanjajo. Niso odnehali od svojih lastnih početij niti od svoje trmoglave poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Gospodova jeza je bila vroča zoper Izrael in rekel je: »Zato, ker je to ljudstvo prekršilo mojo zavezo, ki sem jo zapovedal njihovim očetom in niso prisluhnili mojemu glasu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'odslej tudi jaz pred njimi ne bom podil kateregakoli izmed narodov, ki jih je pustil Józue, ko je umrl,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'da bom lahko po njih preizkusil Izraela, če se bodo držali Gospodove poti, da hodijo po njej, kakor so se je držali njihovi očetje ali ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Zato je Gospod pustil tiste narode, ne da bi jih naglo pognal ven niti jih ni izročil v Józuetovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Torej to so narodi, ki jih je pustil Gospod, da z njimi preizkusi Izraela, torej tiste iz Izraela, ki niso poznali vseh kánaanskih vojn,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'samo da bi rodovi Izraelovih otrok lahko vedeli, da jih naučijo vojne, vsaj tiste, ki prej niso ničesar vedeli o tem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'namreč pet filistejskih knezov in vse Kánaance, Sidónce in Hivéjce, ki so prebivali na gori Libanon, od gore Báal Hermon, do vhoda v Hamát.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Bili so, da z njimi preizkusi Izraela, da spozna, ali bodo prisluhnili Gospodovim zapovedim, ki jih je po Mojzesovi roki zapovedal njihovim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Izraelovi otroci so prebivali med Kánaanci, Hetejci, Amoréjci, Perizéjci, Hivéjci in Jebusejci');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'in jemali so njihove hčere, da so postale njihove žene in svoje hčere so dajali njihovim sinovom in služili njihovim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Izraelovi otroci so počeli zlo v Gospodovih očeh in pozabili Gospoda, svojega Boga in služili Báalom in ašeram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Zato je bila Gospodova jeza vroča zoper Izrael in jih je prodal v roko Kušán Rišatájima, kralja Mezopotamije in Izraelovi otroci so osem let služili Kušán Rišatájimu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Ko so Izraelovi otroci vpili h Gospodu, je Gospod Izraelovim otrokom dvignil osvoboditelja, ki jih je osvobodil, Kenázovega sina Otniéla, Kalébovega mlajšega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Gospodov Duh je prišel nadenj in sodil je Izraelu in odšel ven na vojsko in Gospod je izročil Kušán Rišatájima, kralja Mezopotamije, v njegovo roko in njegova roka je prevladala zoper Kušán Rišatájima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Dežela je imela štirideset let počitek in Kenázov sin Otniél je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Izraelovi otroci pa so ponovno počeli zlo v Gospodovih očeh in Gospod je zoper Izraela okrepil moábskega kralja Eglóna, ker so počeli zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'K sebi je zbral otroke Amóna in Amáleka ter odšel in udaril Izrael in v last vzel mesto palmovih dreves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Tako so Izraelovi otroci osemnajst let služili moábskemu kralju Eglónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Toda ko so Izraelovi otroci klicali h Gospodu, jim je Gospod dvignil osvoboditelja, Gerájevega sina Ehúda, Benjaminovca, moža, ki je bil levičen in po njem so Izraelovi otroci poslali darilo moábskemu kralju Eglónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Toda Ehúd si je naredil bodalo, ki je imelo dve ostrini, komolec dolgo in opasal si ga je pod oblačilo, na svoje desno stegno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'In prinesel je darilo moábskemu kralju Eglónu. Eglón pa je bil zelo debel mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Ko je končal s ponujanjem darila, je ljudstvo, ki je nosilo darilo, odposlal proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Toda on sam se je ponovno obrnil od klesancev, ki so bili pri Gilgálu in rekel: »Zate imam skrivno naročilo, oh kralj.« Ta je rekel: »Molči.« In vsi, ki so stali pri njem, so odšli od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Ehúd je prišel k njemu in ta je sedel v poletni dvorani, ki jo je imel samo zase. Ehúd je rekel: »Zate imam sporočilo od Boga.« In ta je vstal iz svojega sedeža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Ehúd je svojo levo roko iztegnil naprej, vzel bodalo s svojega desnega stegna in ga zabodel v njegov trebuh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, '§ Tudi ročaj je šel noter za rezilom in maščoba se je zaprla na rezilu, tako da bodala ni mogel izvleči iz njegovega trebuha in ven je prišla umazanija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Potem je Ehúd šel naprej skozi preddverje ter za seboj zaprl vrata dvorane in jih zaklenil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Ko je odšel ven, so prišli njegovi služabniki in glej, ko so videli, da so bila vrata dvorane zaklenjena, so rekli: »Zagotovo v svoji poletni sobi pokriva svoja stopala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Obotavljali so se, dokler jih ni postalo sram in glej, vrat dvorane ni odprl. Zato so vzeli ključ in jih odprli in glej, njihov gospod je mrtev ležal na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehúd pa je pobegnil, medtem ko so se zadrževali in šel onkraj klesancev in pobegnil v Seíro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Pripetilo se je, ko je prišel, da je na gori Efrájim zatrobil na šofar in Izraelovi otroci so se z njim spustili z gore in on [sam] je bil pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Rekel jim je: »Sledite za menoj, kajti Gospod je vaše sovražnike Moábce izročil v vašo roko.« Odšli so dol za njim in zavzeli jordanske prehode proti Moábu in nobenemu človeku niso pustili iti čez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Ob tistem času so iz Moába usmrtili okoli deset tisoč mož, vse krepke in vse junaške može; in tam ni utekel niti [en] človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Tako je bil tisti dan Moáb podjarmljen pod Izraelovo roko. In dežela je imela osemdeset let počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Za njim je bil Anátov sin Šamgár, ki je z volovsko palico z bodico izmed Filistejcev usmrtil šeststo mož. Tudi on je osvobodil Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Ko je bil Ehúd mrtev, so Izraelovi otroci ponovno počeli zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Gospod jih je prodal v roko kánaanskega kralja Jabína, ki je kraljeval v Hacórju, katerega poveljnik vojske je bil Siserá, ki je prebival v Haróšetu poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Izraelovi otroci so vpili h Gospodu, kajti imel je devetsto bojnih vozov iz železa in dvajset let je mogočno zatiral Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Ob tistem času je Izraelu sodila prerokinja Debóra, Lapidótova žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Prebivala je pod Debórinim palmovim drevesom med Ramo in Betelom, na gori Efrájim in Izraelovi otroci so prihajali gor k njej za sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Poslala je in poklicala Abinóamovega sina Baráka iz Kedeš-Neftálija in mu rekla: »Ali ni Gospod, Izraelov Bog, zapovedal, rekoč: ›Pojdi in odpravi se proti gori Tabor in s seboj vzemi deset tisoč mož izmed Neftálijevih otrok in Zábulonovih otrok?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'K tebi, k reki Kišón, bom pritegnila Siserája, poveljnika Jabínove vojske, z njegovimi bojnimi vozovi in njegovo množico in izročila ga bom v tvojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barák ji je rekel: »Če boš šla z menoj, potem bom šel, če pa ne boš šla z menoj, potem ne bom šel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Rekla je: »Zagotovo bom šla s teboj, vendar potovanje, na katero greš, ne bo v tvojo čast, kajti Gospod bo Siserája prodal v roko ženske.« Debóra je vstala in z Barákom odšla v Kedeš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Barák je v Kedeš poklical Zábulona in Neftálija in ta je odšel gor z deset tisoč možmi ob svojih stopalih in Debóra je z njim odšla gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Torej Kenéjec Heber, ki je bil izmed otrok Mojzesovega tasta Hobába, se je oddvojil od Kenéjcev in si svoj šotor postavil na ravnini Caananím, ki je pri Kedešu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Siseráju so naznanili, da je Abinóamov sin Barák odšel gor h gori Tabor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Siserá je zbral skupaj vse svoje bojne vozove, devetsto železnih bojnih vozov in vse ljudstvo, ki je bilo z njim, od Haróšeta poganov do reke Kišón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debóra je rekla Baráku: »Vstani, kajti to je dan, na katerega je Gospod izročil Siserája v tvojo roko. Ali ni Gospod šel ven pred teboj?« Tako je Barák odšel dol z gore Tabor in deset tisoč mož za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Gospod je pred Barákom z ostrino meča porazil Siserája, vse njegove bojne vozove in vso njegovo vojsko, tako da se je Siserá spustil iz svojega bojnega voza in pobegnil na svojih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Toda Barák je zasledoval bojne vozove in vojsko do Haróšeta poganov in vsa Siserájeva vojska je padla na ostrino meča in niti mož ni preostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Vendar je Siserá na svojih stopalih pobegnil proč k šotoru Jaéle, žene Kenéjca Heberja, kajti mir je bil med Jabínom, kraljem Hacórja in hišo Kenéjca Heberja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jaéla je odšla ven, da sreča Siserája ter mu rekla: »Zavij noter, moj gospod, zavij noter k meni. Ne boj se.« Ko je zavil noter, k njej v šotor, ga je pokrila z ogrinjalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Rekel ji je: »Daj mi, prosim te, piti malo vode, kajti žejen sem.« Odprla je meh mleka, mu dala piti in ga pokrila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Ponovno ji je rekel: »Stoj v vratih šotora in zgodilo se bo, ko pride katerikoli mož in od tebe poizveduje in reče: ›Ali je tam kakšen mož,‹ da boš rekla: ›Ne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Potem je Heberjeva žena Jaéla vzela šotorski klin in v svojo roko vzela kladivo in po tiho odšla k njemu in klin zabila v njegova sènca in ga pritrdila k tlom, kajti trdno je zaspal in bil je izmučen. Tako je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Glej, ko je Barák zasledoval Siserája, je Jaéla prišla ven, da ga sreča ter mu rekla: »Pridi in pokazala ti bom moža, ki ga iščeš.« Ko je vstopil v njen šotor, glej, Siserá je ležal mrtev in klin je bil v njegovih sèncih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tako je Bog na ta dan pred Izraelovimi otroki podjarmil kánaanskega kralja Jabína.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Roka Izraelovih otrok je uspevala in prevladala zoper kánaanskega kralja Jabína, dokler niso uničili kánaanskega kralja Jabína.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Potem sta Debóra in Abinóamov sin Barák tisti dan zapela, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '»Hvalite Gospoda za maščevanje Izraela, ko se je ljudstvo voljno darovalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Poslušajte, oh vi kralji, pazljivo prisluhnite, oh vi princi. Jaz, celó jaz, bom prepevala Gospodu. Prepevala bom hvalo Gospodu, Izraelovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Gospod, ko si šel iz Seírja, ko si korakal ven iz edómskega polja, je zemlja trepetala in nebo je kapljalo, tudi oblaki so kapljali vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Gore so se topile pred Gospodom, celó tisti Sinaj pred Gospodom, Izraelovim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'V dneh Anátovega sina Šamgárja, v dneh Jaéle, so bile glavne ceste prazne in popotniki so hodili po stranskih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Prebivalci vasi so prenehali, prenehali so v Izraelu, dokler nisem vstala jaz, Debóra, ki sem vstala, mati v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, '§ Izbrali so nove bogove. Potem je bila vojna v velikih vratih. Ali sta bila ščit ali sulica videna med štiridesetimi tisoči v Izraelu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Moje srce je [nagnjeno] k Izraelovim voditeljem, ki so se voljno darovali med ljudstvom. Blagoslavljajte Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Govorite, vi, ki jahate na belih oslih, vi, ki sedite na sodbi in hodite po poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Tisti, ki so bili osvobojeni pred hrupom lokostrelcev na krajih zajemanj vode, bodo tam ponavljali Gospodova pravična dejanja, celó pravična dejanja do prebivalcev njegovih vasi v Izraelu. Potem bo Gospodovo ljudstvo šlo dol k velikim vratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Prebudi se, prebudi se, Debóra. Prebudi se, prebudi se, izusti pesem. Vstani Barák in vodí svoje ujeto ujetništvo, ti, Abinóamov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Potem je naredil tistega, ki preostane, da ima gospostvo nad plemiči izmed ljudstva. Gospod me je naredil, da imam gospostvo nad mogočnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Iz Efrájima je bila tam korenina tistih zoper Amáleka. Za teboj, Benjamin, med tvojim ljudstvom. Iz Mahírja so prišli dol voditelji in iz Zábulona tisti, ki vlečejo pisalo pisca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Isahárjevi princi so bili z Debóro, celo Isahár in tudi Barák. Peš je bil poslan v dolino. Zaradi Rubenovih oddelkov so bile velike misli srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Zakaj ostajaš med ovčjimi stajami, da poslušaš blejanje tropov? Zaradi Rubenovih oddelkov so bila velika preiskovanja srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileád je prebival onkraj Jordana in zakaj je Dan ostal v ladjah? Aser je nadaljeval na morski obali in prebival v svojih vrzelih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zábulon in Neftáli sta bila ljudstvi, ki sta izpostavili svoja življenja smrti na visokih krajih polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Kralji so prišli in se bojevali, potem so se pri vodah Megída v Taanáhu bojevali kánaanski kralji; nobenega dobička od denarja niso vzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vojskovali so se z neba. Zvezde na svojih orbitah so se bojevale zoper Siserája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Reka Kišón jih je odplavila, ta starodavna reka, reka Kišón. Oh moja duša, pomendrala si moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Potem so bila konjska kopita zlomljena zaradi razloga drvenj, drvenj njihovih mogočnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '›Prekolnite Meróz,‹ je rekel Gospodov angel, grenko prekolnite njegove prebivalce, ker niso prišli na pomoč Gospodu, na pomoč Gospodu zoper mogočnega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Blagoslovljena nad ženami naj bo Jaéla, žena Kenéjca Heberja, blagoslovljena nad ženami naj bo v šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Prosil je vode in dala mu je mleko. V gosposki skledi je prinesla maslo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Svojo roko je iztegnila h klinu in svojo desnico k delavčevemu kladivu in s kladivom je udarila Siserája, zdrobila mu je glavo, ko jo je predrla in udarila skozi njegova sènca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Ob njenih stopalih se je upognil, padel je, ulegel se je. Ob njenih stopalih se je upognil, padel je. Kjer se je upognil, tam je mrtev padel dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Siserájeva mati je pogledala skozi okno in zaklicala skozi mrežo: ›Zakaj se njegov bojni voz tako dolgo mudi? Zakaj se mudijo kolesa njegovih bojnih vozov?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Njene modre gospe so ji odgovorile, da, sebi je vrnila odgovor:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '›Ali niso pohiteli? Ali niso razdelili plena; vsakemu možu gospodično ali dve. Siseráju plen številnih barv, plen številnih barv vezenine, številnih barv vezenine na obeh straneh, primerne za vratove tistih, ki jemljejo plen?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tako naj vsi tvoji sovražniki propadejo, oh Gospod, toda naj bodo tisti, ki ga ljubijo, kakor sonce, ko vzide v svoji moči.« In dežela je imela štirideset let počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Izraelovi otroci so v Gospodovih očeh počeli zlo in Gospod jih je [za] sedem let izročil v roko Midjáncev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Roka Midjáncev je prevladala zoper Izraela in zaradi Midjáncev so si Izraelovi otroci naredili jame, ki so v gorah, votline in oporišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Bilo je tako, ko je Izrael sejal, da so prišli gor Midjánci, Amalečani in otroci vzhoda, celó ti so prišli gor zoper njih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'in se utaborili zoper njih in uničili donos zemlje, dokler ne prideš do Gaze in za Izrael niso pustili nobene oskrbe, niti ovce, niti vola, niti osla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Kajti gor so prišli s svojo živino in svojimi šotori in prišli so kakor kobilice zaradi množice, kajti tako njih kakor njihovih kamel je bilo brez števila in vstopili so v deželo, da jo uničijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Zaradi Midjáncev je bil Izrael silno obubožan in Izraelovi otroci so klicali h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Pripetilo se je, ko so zaradi Midjáncev Izraelovi otroci klicali h Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'da je Gospod k Izraelovim otrokom poslal preroka, ki jim je rekel: »Tako govori Gospod, Izraelov Bog: ›Privedel sem vas gor iz Egipta, vas izpeljal iz hiše sužnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'vas osvobodil iz roke Egipčanov in iz roke vseh, ki so vas zatirali in jih pregnal izpred vas in vam dal njihovo deželo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'ter vam rekel: ›Jaz sem Gospod, vaš Bog. Ne bojte se bogov Amoréjcev, v katerih deželi prebivate.‹ Toda niste ubogali mojega glasu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Prišel je Gospodov angel in sedel pod hrast, ki je bil v Ofri, ki je pripadal Abiézerjevcu Joášu. Njegov sin Gideón je pri vinski stiskalnici mlatil pšenico, da jo skrije pred Midjánci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Prikazal se mu je Gospodov angel ter mu rekel: » Gospod je s teboj, mogočen, hraber mož.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideón mu je rekel: »Oh moj Gospod, če je z nami Gospod, zakaj nas je potem vse to doletelo? In kje so vsi njegovi čudeži, o katerih so nam povedali naši očetje, rekoč. ›Ali nas ni Gospod privedel gor iz Egipta? Toda sedaj nas je Gospod zapustil in nas izročil v roke Midjáncev.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Gospod je pogledal nanj in rekel: »Pojdi v tej svoji moči in ti boš Izraela rešil iz roke Midjáncev. Ali te nisem jaz poslal?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Rekel mu je: »Oh moj Gospod, s čim bom rešil Izraela? Glej, moja družina je revna v Manáseju in jaz sem najmanjši v očetovi hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Gospod mu je rekel: »Zagotovo bom jaz s teboj in Midjánce boš udaril kakor en mož.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Ta mu je rekel: »Če sem torej našel milost v tvojem pogledu, potem mi pokaži znamenje, da ti govoriš z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Ne odidi od tod, prosim te, dokler ne pridem k tebi in prinesem svoje darilo in ga postavim predte.« Rekel je: »Ostal bom, dokler ponovno ne prideš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideón je vstopil in pripravil kozlička in nekvašene kolače iz škafa moke. Meso je položil v košaro, juho v lonec in to prinesel ven k njemu pod hrast in to ponudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Angel od Boga mu je rekel: »Vzemi meso in nekvašene kolače ter jih položi na to skalo in izlij juho.« In tako je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Potem je Gospodov angel iztegnil konec palice, ki je bila v njegovi roki in se dotaknil mesa in nekvašenih kolačev. In iz skale se je dvignil ogenj in použil meso ter nekvašene kolače. Potem je Gospodov angel odšel iz njegovega pogleda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Ko je Gideón zaznal, da je bil to Gospodov angel, je Gideón rekel: »Ojoj, oh Gospod Bog! Ker sem videl Gospodovega angela iz obličja v obličje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Gospod mu je rekel: »Mir ti bodi, ne boj se. Ne boš umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Potem je Gideón tam zgradil oltar Gospodu in ga imenoval Jahve–šalom. Do današnjega dne je ta še vedno v Ofri Abiézerjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Pripetilo se je isto noč, da mu je Gospod rekel: »Vzemi mladega bikca od svojega očeta, celo drugega bikca starosti sedmih let in zruši Báalov oltar, ki ga ima tvoj oče in posekaj ašero, ki je poleg njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'in zgradi oltar Gospodu, svojemu Bogu, na vrhu te skale, na določenem kraju in vzemi drugega bikca in daruj žgalno daritev z lesom ašere, ki jo boš posekal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Potem je Gideón vzel deset mož izmed svojih služabnikov in storil, kakor mu je Gospod rekel. Bilo je tako, ker se je bal očetove družine in mož mesta, da tega ni mogel storiti podnevi, da je to storil ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Ko so možje mesta zgodaj zjutraj vstali, glej, Báalov oltar je bil podrt in ašera, ki je bila poleg njega, je bila posekana in drugi bikec je bil darovan na oltarju, ki je bil zgrajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Drug drugemu so rekli: »Kdo je storil to stvar?« Ko so poizvedovali in spraševali, so rekli: »To stvar je storil Joášev sin Gideón.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Potem so možje iz mesta Joášu rekli: »Privedi svojega sina ven, da bo lahko umrl, ker je podrl Báalov oltar in ker je posekal ašero, ki je bila poleg njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joáš je rekel vsem, ki so stali zoper njega: »Mar se boste potegovali za Báala? Ali ga boste vi rešili? Kdor se bo potegoval zanj, naj bo usmrčen, medtem ko je še jutro. Če je on bog, naj se poteguje sam zase, ker je nekdo podrl njegov oltar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Zato ga je na ta dan imenoval Jerubáal, rekoč: »Naj Báal navaja dokaze zoper njega, ker je zrušil njegov oltar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Potem so se skupaj zbrali vsi Midjánci, Amálečani in otroci vzhoda, odšli preko in se utaborili v dolini Jezreél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Toda Gospodov Duh je prišel nad Gideóna in ta je zatrobil na šofar in Abiézer je bil zbran za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Poslal je poslance po vsem Manáseju, ki je bil tudi zbran za njim. Poslal je poslance k Aserju, k Zábulonu in k Neftáliju in prišli so gor, da jih srečajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Gideón je rekel Bogu: »Če hočeš po moji roki rešiti Izraela, kakor si rekel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'glej, bom na tla položil ovčje runo in če bo rosa samo na runu in bo vsa zemlja poleg suha, potem bom vedel, da hočeš po moji roki rešiti Izraela, kakor si rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'In bilo je tako, kajti naslednji dan je zgodaj vstal in iz runa iztisnil roso, polno skledico vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Gideón je rekel Bogu: »Tvoja jeza naj se ne vname zoper mene in govoril bom samo še tokrat. Naj dokažem, prosim te, samo še tokrat z runom. Naj bo sedaj suho samo na runu, po vsej zemlji pa naj bo rosa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Bog je to noč storil tako, kajti bilo je suho samo na runu, rosa pa je bila po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Potem je Jerubáal, ki je Gideón in vse ljudstvo, ki je bilo z njim, vstalo zgodaj in se utaborilo poleg vodnjaka Haród, tako da je bila vojska Midjáncev na njihovi severni strani, v dolini pri Moréjevem hribu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Gospod je rekel Gideónu: »Ljudstva, ki je s teboj, je zame preveč, da bi Midjánce izročil v njihove roke, da se ne bi Izrael poveličeval zoper mene, rekoč: ›Moja lastna roka me je rešila.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Zdaj torej pojdi, razglasi v ušesa ljudstva, rekoč: ›Kdorkoli je boječ in se boji, naj se vrne in zgodaj odide z gore Gileád.‹« In tam se jih je izmed ljudstva vrnilo dvaindvajset tisoč, ostalo pa jih je deset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Gospod je rekel Gideónu: »Ljudstva je še preveč. Privedi jih dol k vodi in tam ti jih bom preizkusil.« Zgodilo se bo, da o komer ti rečem: ›Ta bo šel s teboj,‹ bo ta isti šel s teboj; in o komer ti rečem: ›Ta ne bo šel s teboj,‹ ta isti ne bo šel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Tako je ljudstvo privedel dol k vodi in Gospod je rekel Gideónu: »Kdorkoli s svojim jezikom sreba vodo, kakor sreba pes, tega boš postavil poleg sebe, podobno vsakega, ki poklekne dol na svoja kolena, da bi pil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Število tistih, ki so srebali s pristavljanjem svoje roke k svojim ustom, je bilo tristo mož, toda vsi drugi izmed ljudstva so se upognili na svoja kolena, da pijejo vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Gospod je rekel Gideónu: »S tristo možmi, ki so srebali, vas bom rešil in Midjánce izročil v tvojo roko. Vse preostalo ljudstvo pa naj gre vsak mož k svojemu kraju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Tako je ljudstvo v svojo roko vzelo živež in svoje šofarje, ves preostanek Izraela pa je vsakega moža poslal k svojemu šotoru in obdržal tistih tristo mož. Midjánska vojska pa je bila pod njim v dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Iste noči se je pripetilo, da mu je Gospod rekel: »Vstani, spusti se k vojski, kajti izročil sem jo v tvojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Toda če se bojiš iti dol, pojdi dol k vojski s svojim služabnikom Purájem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Slišal boš kaj govorijo. Potem se bodo tvoje roke okrepile, da greš dol k vojski.« Potem je s svojim služabnikom Purájem odšel dol k zunanjim izmed oboroženih mož, ki so bili v vojski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midjánci in Amalečani in vsi otroci vzhoda pa so ležali povprek po dolini, zaradi množice podobni kobilicam in njihovih kamel je bilo zaradi množice brez števila, kakor peska ob morski obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Ko je Gideón prišel, glej, je bil tam mož, ki je svojemu tovarišu povedal sanje ter rekel: »Glej, sanjal sem sanje in glej, kolač ječmenovega kruha se je privalil v midjánsko vojsko, prišel k šotoru in ga udaril, da je ta padel in ga prevrnil, da je ležal postrani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Njegov tovariš je odgovoril in rekel: »To ni nič drugega kakor meč Gideóna, Joáševega sina, moža iz Izraela, kajti v njegovo roko je Bog izročil Midjánce in vso vojsko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Bilo je tako, ko je Gideón slišal pripovedovanje sanj in njeno razlago, da je oboževal, se vrnil v Izraelovo vojsko in rekel: »Vstanite, kajti Gospod je v vašo roko izročil midjánsko vojsko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Tristo mož je razdelil na tri skupine in v roko vsakega moža položil šofar s praznimi lončenimi vrči in svetilkami znotraj vrčev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Rekel jim je: »Glejte mene in storite podobno. In glejte, ko pridem k robu tabora, se bo zgodilo, da kakor storim jaz, boste tako storili tudi vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Ko zatrobim s šofarjem, jaz in vsi tisti, ki so z menoj, potem tudi vi zatrobite s šofarji na vsaki strani tabora in recite: › Meč od Gospoda in od Gideóna.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Tako so Gideón in sto mož, ki so bili z njim, prišli k robu tabora na začetku srednje straže in imeli so ravno sveže postavljeno stražo. Zatrobili so na šofarje in razbili lončene vrče, ki so bili v njihovih rokah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Tri skupine so trobile na šofarje in razbile lončene vrče in držale svetilke v svojih levicah in šofarje v svojih desnicah, da z njimi trobijo in kričali: »Meč od Gospoda in od Gideóna.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Stali so vsak mož na svojem mestu okoli tabora in vsa vojska je stekla, kričala in pobegnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Tristo [jih] je trobilo na šofarje in Gospod je torej po vsej vojski naravnal meč vsakega moža zoper svojega tovariša in vojska je pobegnila do Bet Šite v Cerédi in do meje Abél Mehóle, do Tabáta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Izraelovi možje so se zbrali skupaj iz Neftálija, iz Aserja, iz vsega Manáseja in zasledovali Midjánce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gideón je poslal poslance po vsej gori Efrájim, rekoč: »Pridite dol zoper Midjánce in pred njimi zasedite vode do Bet Bare in Jordana.« Potem so se vsi Efrájimovi možje zbrali skupaj in zasedli vode do Bet Bare in Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Zajeli so dva princa izmed Midjáncev, Oréba in Zeéba. Oréba so usmrtili na Orébovi skali, Zeéba pa so usmrtili na Zeébovi vinski stiskalnici in zasledovali Midjánce ter glavi Oréba in Zeéba prinesli Gideónu, na drugo stran Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Možje iz Efrájima so mu rekli: »Zakaj si nam tako služil, da nas nisi poklical, ko si odhajal, da bi se bojeval z Midjánci?« In ostro so se pričkali z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Rekel jim je: »Kaj sem torej storil v primerjavi z vami? Mar ni Efrájimovo paberkovanje boljše kakor Abiézerjeva trgatev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Bog je v vaše roke izročil midjánska princa, Oréba in Zeéba. Kaj sem bil jaz zmožen storiti v primerjavi z vami?« Potem ko jim je to rekel, se je njihova jeza zoper njega zmanjšala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Gideón je prišel do Jordana ter ga prečkal, on in tristo mož, ki so bili z njim, slabotni, vendar so jih zasledovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Možem iz Sukóta je rekel: »Dajte, prosim vas, hlebe kruha ljudstvu, ki mi sledi, kajti oslabeli so in jaz zasledujem midjánska kralja Zebaha in Calmunája.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Princi iz Sukóta so rekli: » Mar so roke Zebaha in Calmunája sedaj v tvoji roki, da bi tvoji vojski dali kruha?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideón je rekel: »Torej ko Gospod Zebaha in Calmunája izroči v mojo roko, potem bom vaše meso raztrgal s trnjem iz divjine in z osatom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Od tam je odšel gor do Penuéla in jim podobno govoril. Ljudje iz Penuéla so mu odgovorili podobno kot ljudje iz Sukóta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Govoril je tudi ljudem iz Penuéla, rekoč: »Ko ponovno pridem v miru, bom porušil ta stolp.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Torej Zebah in Calmunáj sta bila v Karkórju in njune vojske z njima, okoli petnajst tisoč mož, vsi, ki so preostali od vseh vojsk otrok vzhoda, kajti tam je padlo sto dvajset tisoč mož, ki so izdirali meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideón je odšel gor po poti tistih, ki so prebivali v šotorih vzhodno od Nobaha in Jogbóhe in udaril vojsko, kajti vojska je bila brezskrbna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Ko sta Zebah in Calmunáj pobegnila, ju je zasledoval in zajel dva midjánska kralja, Zebaha in Calmunája ter porazil vso vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Joášev sin Gideón se je vrnil iz bitke, preden je vzšlo sonce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Ujel je mladeniča izmed ljudi iz Sukóta in od njega poizvedel in ta mu je opisal prince iz Sukóta in njihove starešine, celó sedeminsedemdeset mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Prišel je k možem iz Sukóta in rekel: »Glejte Zebaha in Calmunája, s katerima ste me ošteli, rekoč: ›Mar so roke Zebaha in Calmunája sedaj v tvoji roki, da naj bi dali kruha tvojim možem, ki so izmučeni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Zgrabil je mestne starešine in trnje iz divjine in osat ter z njimi učil može iz Sukóta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Podrl je stolp v Penuélu in usmrtil može iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Potem je Zebahu in Calmunáju rekel: »Kakšne vrste možje so bili tisti, ki sta jih usmrtila pri Taboru?« Odgovorila sta: »Takšni so bili, kot si ti. Vsakdo je bil podoben kraljevemu otroku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Rekel je: » Bili so moji bratje, celó sinovi moje matere. Kakor živi Gospod, če bi jih rešila žive, vaju ne bi ubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Svojemu prvorojencu Jeterju je rekel: »Vstani in ju ubij.« Toda mladostnik ni izvlekel svojega meča, kajti bal se je, ker je bil še mladostnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Potem sta Zebah in Calmunáj rekla: »Vstani ti in padi na naju, kajti kakršen je mož, takšna je njegova moč.« Gideón je vstal in usmrtil Zebaha in Calmunája in odvzel ornamente, ki so bili na vratovih njunih kamel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Potem so možje iz Izraela rekli Gideónu: »Ti vladaj nad nami, oba, ti in tvoj sin in tudi sin tvojega sina, kajti osvobodil si nas iz roke Midjáncev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Gideón jim je rekel: »Jaz ne bom vladal nad vami niti ne bo moj sin vladal nad vami. Gospod bo vladal nad vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gideón jim je rekel: »Od vas bi želel prošnjo, da bi mi dal vsak mož uhane od svojega plena.« (Kajti imeli so zlate uhane, ker so bili Izmaelci.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Odgovorili so: »Voljno jih bomo dali.« Razširili so obleko in nanjo je vsak mož vrgel uhane od svojega plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Teža zlatih uhanov, ki jih je zahteval, je bila tisoč sedemsto šeklov zlata, poleg ornamentov in obeskov za ušesa in škrlatnega oblačila, ki je bil na midjánskih kraljih in poleg verižic, ki so bile okoli vratov njihovih kamel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideón je iz njih naredil efód in ga dal v svoje mesto, v Ofro. Ves Izrael se je odšel tja vlačugat za njim. Ta stvar je postala zanka Gideónu in njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Tako je bil Midján podjarmljen pred Izraelovimi otroki, tako da niso več vzdignili svojih glav. In dežela je bila v Gideónovih dneh v spokojnosti štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Joášev sin Jerubáal je odšel in prebival v svoji lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideón je imel sedemdeset sinov, rojenih od njegovega telesa, kajti imel je mnogo žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Njegova priležnica, ki je bila v Sihemu, mu je prav tako rodila sina, čigar ime je imenoval Abiméleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Joášev sin Gideón je umrl v dobri visoki starosti in bil pokopan v mavzoleju njegovega očeta Joáša v Ofri Abiézerjevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Takoj, ko je bil Gideón mrtev, se je pripetilo, da so se Izraelovi otroci ponovno obrnili in se šli vlačugat za Báali in si naredili Baal-berita za svojega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Izraelovi otroci se niso spominjali Gospoda, svojega Boga, ki jih je osvobodil iz rok vseh njihovih sovražnikov na vsaki strani');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'niti niso izkazali prijaznosti Jerubáalovi hiši, namreč Gideónu, glede na vso dobroto, ki jo je izkazal Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Jerubáalov sin Abiméleh je šel do Sihema, do bratov svoje matere in se z njimi posvetoval in z vso družino hiše očeta svoje matere, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '»Govorite, prosim vas, na ušesa vsem sihemskim gospodarjem: ›Ali je za vas bolje, da vsi Jerubáalovi sinovi, katerih je sedemdeset oseb, kraljujejo nad vami ali da nad vami kraljuje eden? Spomnite se tudi, da sem jaz vaša kost in vaše meso.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Bratje njegove matere so vse te besede o njem govorili v ušesa vseh sihemskih gospodarjev in njihova srca nagnili, da sledijo Abimélehu, kajti rekli so: »On je naš brat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Iz hiše Baal-berita so mu dali sedemdeset koščkov srebra, s katerimi je Abiméleh najel prazno-glave in nepomembne osebe, ki so mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Odšel je v hišo svojega očeta pri Ofri in na enem kamnu usmrtil svoje brate, Jerubáalove sinove, ki jih je bilo sedemdeset oseb. Kljub temu pa je ostal najmlajši Jerubáalov sin Jotám, kajti ta se je skril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Vsi sihemski gospodarji so se zbrali skupaj in vsa Milójeva hiša in odšli ter Abiméleha postavili za kralja pri ravninskem stebru, ki je bil v Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Ko so to povedali Jotámu, je ta odšel in se postavil na vrhu gore Garizím, povzdignil svoj glas, zavpil in jim rekel: »Prisluhnite mi, vi sihemski gospodarji, da bo Bog lahko prisluhnil vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Drevesa so šla naprej ob času, da mazilijo kralja nad seboj in rekla so oljki: ›Kraljuj nad nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Toda oljka jim je rekla: ›Mar naj zapustim svojo mastnost, s katero po meni častijo Boga in človeka in grem, da bi bila povišana nad drevesa?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Drevesa so rekla figovemu drevesu: ›Ti pridi in kraljuj nad nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Toda figovo drevo jim je reklo: ›Mar naj zapustim svojo sladkost in svoj dober sad in grem, da bi bilo povišano nad drevesa?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Potem so drevesa rekla trti: ›Ti pridi in kraljuj nad nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Trta pa jim je rekla: ›Mar naj zapustim svoje vino, ki razveseljuje Boga in človeka in grem, da naj bi bila povišana nad drevesa?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Potem so vsa drevesa rekla trnovemu grmu: ›Ti pridi in kraljuj nad nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Trnov grm je rekel drevesom: ›Če me resnično mazilite za kralja nad seboj, potem pridite in svoje zaupanje položite v mojo senco, in če ne, naj ogenj pride iz trnovega grma in použije libanonske cedre.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Zdaj torej, če ste storili resnično in iskreno v tem, da ste si postavili Abiméleha za kralja in če ste dobro postopali z Jerubáalom in njegovo hišo in mu storili glede na ravnanje njegovih rok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(kajti moj oče se je bojeval za vas in v ospredju tvegal svoje življenje in vas osvobodil iz roke Midjáncev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'in ste ta dan vstali zoper hišo mojega očeta in umorili njegove sinove, sedemdeset oseb na enem kamnu in postavili Abiméleha, sina njegove dekle, za kralja nad sihemskimi gospodarji, ker je vaš brat).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Če ste torej ta dan resnično in iskreno postopali z Jerubáalom in njegovo hišo, potem se veselite z Abimélehom in naj se tudi on veseli z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Toda če ne, naj ogenj pride od Abiméleha in pogoltne sihemske gospodarje in Milójevo hišo. In ogenj naj pride od sihemskih gospodarjev in od Milójeve hiše in požre Abiméleha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Jotám je stekel proč, pobegnil in odšel v Beêr in tam prebival zaradi strahu pred svojim bratom Abimélehom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Ko je Abiméleh tri leta kraljeval nad Izraelom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'je potem Bog med Abiméleha in sihemske gospodarje poslal zlega duha in sihemski gospodarji so zahrbtno postopali z Abimélehom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'da bi ta krutost, storjena sedemdesetim Jerubáalovim sinovom lahko prišla in bi bila njihova kri položena na njihovega brata Abiméleha, ki jih je umoril in na sihemske gospodarje, ki so mu pomagali pri morjenju njegovih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Sihemski gospodarji so zanj postavili prežavce v zasedi na vrhu gora in ti so oropali vse, ki so mimo njih prišli po tej poti, in to je bilo povedano Abimélehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Ebedov sin Gáal je prišel s svojimi brati in odšel preko v Sihem in sihemski gospodarji so svoje zaupanje položili vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Odšli so ven na polja in obrali svoje vinograde in tlačili grozdje in se veselili in odšli v hišo svojega boga, jedli, pili in preklinjali Abiméleha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Ebedov sin Gáal je rekel: »Kdo je Abiméleh in kdo je Sihem, da bi mu služili? Mar ni on Jerubáalov sin? In Zebúl njegov častnik? Služite možem Sihemovega očeta Hamórja, kajti zakaj bi mi služili njemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Bog daj, da bi bilo to ljudstvo pod mojo roko! Potem bi odstranil Abiméleha.« In Abimélehu je rekel: »Okrepi svojo vojsko in pridi ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Ko je Zebúl, vladar mesta, slišal besede Ebedovega sina Gáala, je bila njegova jeza vžgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Na skrivnem je poslal poslance k Abimélehu, rekoč: »Glej, Ebedov sin Gáal in njegovi bratje so prišli v Sihem in glej, zoper tebe utrjujejo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Zdaj se torej dvigni ponoči ti in ljudstvo, ki je s teboj in na polju prežite v zasedi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'in zgodilo se bo, da zjutraj, takoj ko bo sonce vzšlo, da boš zgodaj vstal in se nameril na mesto. In glej, ko bodo on in ljudstvo, ki je z njim, prišli ven zoper tebe, potem jim boš lahko storil kakor boš našel priložnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Abiméleh je ponoči vstal in vse ljudstvo, ki je bilo z njim in so v štirih skupinah prežali zoper Sihem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Ebedov sin Gáal je odšel ven in stal v vhodu velikih vrat mesta. Abiméleh in ljudstvo, ki je bilo z njim, pa je vstalo od prežanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Ko je Gáal zagledal ljudstvo, je rekel Zebúlu: »Glej, tam prihaja ljudstvo dol iz vrha gorovja.« Zebúl mu je rekel: »Senco gorovja vidiš, kakor bi bili možje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gáal je ponovno spregovoril in rekel: »Vidiš, tam prihaja dol ljudstvo po sredi dežele in druga skupina prihaja vzdolž ravnine Maonim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Potem mu je Zebúl rekel: »Kje so sedaj tvoja usta, s katerimi praviš: ›Kdo je Abiméleh, da bi mu služili?‹ Mar ni to ljudstvo, ki si ga preziral? Pojdi sedaj ven, prosim te in se bori z njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gáal je odšel ven pred sihemskimi gospodarji in se boril z Abimélehom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Abiméleh ga je pregnal in ta je pobegnil pred njim in mnogi so bili zrušeni in ranjeni, celó do vhoda velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abiméleh je prebival pri Arúmi, Zebúl pa je vrgel ven Gáala in njegove brate, da ne bi prebivali v Sihemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Naslednji dan se je pripetilo, da je ljudstvo odšlo ven na polje in povedali so Abimélehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Ta je vzel ljudstvo in jih razdelil v tri skupine. Na polju so prežali v zasedi in glej, ljudstvo je prišlo ven iz mesta. Vstal je zoper njih in jih udaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abiméleh in skupina, ki je bila z njim, je pohitela naprej in stala na vhodu velikih vrat mesta in dve drugi skupini sta stekli nad vse ljudstvo, ki je bilo na poljih in jih usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abiméleh se je ves tisti dan boril zoper mesto, zavzel mesto, usmrtil ljudstvo, ki je bilo v njem, premagal mesto in ga potresel s soljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, '§ Ko so vsi gospodarji sihemskega stolpa to slišali, so vstopili v trdnjavo hiše boga Berita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'To je bilo povedano Abimélehu, da so bili vsi gospodarji sihemskega stolpa zbrani skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Abiméleh se je povzpel na goro Calmón, on in vse ljudstvo, ki je bilo z njim in Abiméleh je v svojo roko vzel sekiro, odsekal vejo iz dreves, jo vzel in jo položil na svojo ramo in rekel ljudstvu, ki je bilo z njim: »Kar ste videli storiti mene, pohitite in storite, kakor sem storil jaz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Podobno je vse ljudstvo odsekalo vsak svojo vejo, sledilo Abimélehu, jih položili k trdnjavi in zažgali trdnjavo nad njimi. Tako da so umrli tudi vsi ljudje iz sihemskega stolpa, okoli tisoč mož in žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potem je Abiméleh odšel v Tebéc, se utaboril zoper Tebéc in ga zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Toda tam, znotraj mesta, je bil močan stolp in tja so pobegnili vsi možje in žene in vsi iz mesta in ga za seboj zaprli in se spravili na vrh stolpa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abiméleh je prišel k stolpu, se boril zoper njega in se približal vratom stolpa, da bi ga zažgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Neka ženska je kos mlinskega kamna vrgla na Abimélehovo glavo in razbila njegovo lobanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Potem je naglo zaklical k mladeniču, svojemu nosilcu bojne opreme in mu rekel: »Izvleci svoj meč in me usmrti, da ne bodo ljudje o meni rekli: ›Ubila ga je ženska.‹« In njegov mladenič ga je prebodel in ta je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Ko so možje iz Izraela videli, da je bil Abiméleh mrtev, so odšli vsak mož na svoj kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tako je Bog povrnil Abimélehovo zlobnost, ki jo je storil svojemu očetu z umorom svojih sedemdesetih bratov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'in vse zlo sihemskih ljudi je Bog povrnil na njihove glave in nadnje je prišlo prekletstvo Jerubáalovega sina Jotáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Za Abimélehom je vstal Tolá, sin Puvája, sinú Dodója, mož iz Isahárja, da brani Izrael. Prebival je v Šamíru, na gori Efrájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Izraelu je sodil triindvajset let in umrl ter bil pokopan v Šamíru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Za njim je vstal Gileádec Jaír in Izraelu sodil dvaindvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Imel je trideset sinov, ki so jahali na tridesetih osličjih žrebetih in imeli so trideset mest, ki se imenujejo Havot Jaír do tega dne, ki so v deželi Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jaír je umrl in bil pokopan v Kamónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Izraelovi otroci pa so v Gospodovih očeh ponovno počeli zlo in služili Báalom, Astarti, bogovom Sirije, bogovom Sidóna, bogovom Moába, bogovom Amónovih otrok in bogovom Filistejcev in zapustili so Gospoda in mu niso služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Gospodova jeza je bila vroča zoper Izrael in prodal jih je v roke Filistejcev in v roke Amónovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Tisto leto so tlačili in zatirali Izraelove otroke; osemnajst let, vse Izraelove otroke, ki so bili na drugi strani Jordana, v deželi Amoréjcev, ki je v Gileádu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Poleg tega so Amónovi otroci prečkali Jordan, da se borijo tudi zoper Juda, zoper Benjamina in zoper Efrájimovo hišo, tako, da je bil Izrael silno stiskan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Izraelovi otroci so vpili h Gospodu, rekoč: »Grešili smo zoper tebe, zato ker smo zapustili svojega Boga in služili tudi Báalom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Gospod je Izraelovim otrokom rekel: » Mar vas nisem osvobodil pred Egipčani in pred Amoréjci, pred Amónovimi otroki in pred Filistejci?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Tudi Sidónci, Amalečani in Maonci so vas zatirali in klicali ste k meni in osvobodil sem vas iz njihove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Vendar ste me zapustili in služili drugim bogovom, zato vas ne bom več osvobajal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Pojdite in jokajte k bogovom, ki ste jih izbrali. Naj vas oni osvobodijo v času vaše stiske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Izraelovi otroci so rekli Gospodu: »Grešili smo. Stôri nam, karkoli se ti zdi dobro. Prosimo te, samo osvobodi nas ta dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Izmed sebe so odstranili tuje bogove in služili Gospodu. Njegova duša je bila užaloščena zaradi Izraelove bede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Potem so bili Amónovi otroci zbrani skupaj in se utaborili v Gileádu. Izraelovi otroci pa so se zbrali skupaj in se utaborili v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Ljudstvo in gileádski princi so drug drugemu rekli: »Kateri mož je ta, ki se bo začel boriti zoper Amónove otroke? Ta bo poglavar nad vsemi prebivalci Gileáda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Torej Gileádec Jefte je bil mogočen hraber človek in bil je sin pocestnice; in Gileád je zaplodil Jefteja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Gileádova žena mu je rodila sinove in sinovi njegove žene so zrasli in pregnali Jefteja ter mu rekli: »Ne boš dedoval v hiši našega očeta, kajti ti si sin tuje ženske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Potem je Jefte pobegnil pred svojimi brati in prebival v deželi Tob. Tam pa so bili k Jefteju zbrani praznoglavi možje in z njim odšli ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'In pripetilo se je tekom časa, da so Amónovi otroci začeli vojno zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Bilo je tako, da ko so Amónovi otroci začeli vojno zoper Izrael, so starešine iz Gileáda odšli, da Jefteja pripeljejo iz dežele Tob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Jefteju so rekli: »Pridi in bodi naš poveljnik, da se bomo lahko borili z Amónovimi otroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Jefte je rekel starešinam iz Gileáda: »Ali me niste sovražili in pregnali iz hiše mojega očeta? Zakaj ste prišli k meni sedaj, ko ste v stiski?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Starešine iz Gileáda so Jefteju rekli: »Zato se sedaj ponovno obračamo k tebi, da boš lahko šel z nami in se boril zoper Amónove otroke in boš naš poglavar nad vsemi prebivalci Gileáda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefte je rekel starešinam iz Gileáda: »Če me ponovno privedete domov, da se borim zoper Amónove otroke in jih Gospod izroči pred menoj, ali bom vaš poglavar?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Starešine iz Gileáda so rekli Jefteju: » Gospod bodi priča med nami, če ne storimo tako glede na tvoje besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Potem je Jefte odšel s starešinami iz Gileáda in ljudstvo ga je postavilo za poglavarja in poveljnika nad njimi in Jefte je vse svoje besede izrekel pred Gospodom v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Jefte je poslal poslance h kralju Amónovih otrok, rekoč: »Kaj imaš z menoj, da si prišel zoper mene, da se boriš v moji deželi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Kralj Amónovih otrok je Jeftejevim poslancem odgovoril: »Ker je Izrael odvzel mojo deželo, ko so prišli gor iz Egipta, od Arnóna, celo do Jabóka in do Jordana. Sedaj torej ponovno miroljubno povrni te dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jefte je ponovno poslal poslance h kralju Amónovih otrok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'in mu rekel: »Tako govori Jefte: ›Izrael ni odvzel moábske dežele niti dežele Amónovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'temveč ko je Izrael prišel gor iz Egipta in skozi divjino hodil do Rdečega morja in prišel do Kadeša,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'potem je Izrael poslal poslance k edómskemu kralju, rekoč: ›Pusti mi, prosim te, iti skozi tvojo deželo.‹ Toda edómski kralj temu ni hotel prisluhniti. In na podoben način so poslali k moábskemu kralju. Toda ta ni hotel privoliti in Izrael je ostal v Kadešu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Potem so šli vzdolž skozi divjino in obkrožili edómsko deželo in moábsko deželo in prišli pri vzhodni strani moábske dežele in se utaborili na drugi strani Arnóna, toda niso prišli znotraj moábske meje, kajti Arnón je bil moábska meja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Izrael je poslal poslance k Sihónu, kralju Amoréjcev, hešbónskemu kralju. Izrael mu je rekel: ›Naj gremo, prosim te, skozi tvojo deželo na svoj kraj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Toda Sihón ni zaupal Izraelu, da gre skozi njegovo pokrajino, temveč je Sihón zbral skupaj vse svoje ljudstvo, se utaboril v Jahacu in se boril zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Gospod, Izraelov Bog, je Sihóna in vse njegovo ljudstvo izročil v roko Izraelcev in ti so jih udarili. Tako je Izrael vzel v last vso deželo Amoréjcev, prebivalcev tiste dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'V last so vzeli vse pokrajine Amoréjcev, od Arnóna, celo do Jabóka in od divjine, celo do Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Tako je torej Gospod, Izraelov Bog, Amoréjce razlastil izpred svojega ljudstva Izraela in ti naj bi to vzel v last?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Ali ne boš vzel v last tega, kar ti tvoj bog Kemoš daje v last? Tako kogarkoli bo Gospod, naš Bog, napodil izpred nas, te bomo vzeli v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'In sedaj ali si ti kakorkoli boljši kakor Balák, Cipórjev sin, moábski kralj? Ali se je on kdaj prepiral zoper Izrael, ali se je kdaj boril zoper njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'medtem ko je Izrael tristo let prebival v Hešbónu in njegovih mestih, v Aroêrju in njegovih mestih in v vseh mestih, ki so vzdolž ob pokrajinah Arnóna? Zakaj jih torej niste povrnili znotraj tega časa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Zato nisem grešil zoper tebe, temveč mi ti delaš krivico, da se vojskuješ zoper mene. Gospod, Sodnik, naj bo danes sodnik med Izraelovi otroci in Amónovimi otroci.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Vendar kralj Amónovih otrok ni prisluhnil Jeftejevim besedam, ki mu jih je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Potem je Gospodov Duh prišel nad Jefteja in ta je prečkal Gileád in Manáse in šel čez Micpo v Gileádu in iz Micpe v Gileádu prečkal k Amónovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Jefte je prisegel zaobljubo Gospodu in rekel: »Če mi boš čisto gotovo izročil Amónove sinove v moje roke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'potem se bo zgodilo, da kdorkoli pride naprej od vrat moje hiše, da bi me srečal, ko se v miru vrnem od Amónovih otrok, bo zagotovo Gospodov in daroval ga bom za žgalno daritev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Tako je Jefte prešel preko k Amónovim otrokom, da se bori zoper njih in Gospod jih je izročil v njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Udaril jih je od Aroêrja, celo dokler ne prideš v Minít, celó dvajset mest in do ravnine vinogradov, z zelo velikim pokolom. Tako so bili Amónovi otroci podjarmljeni pred Izraelovimi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Jefte je prišel v Micpo, k svoji hiši in glej, njegova hči je prišla ven, da ga sreča s tamburini in s plesi. Ona pa je bila njegov edini otrok. Poleg nje ni imel niti sina niti hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Pripetilo se je, ko jo je zagledal, da je pretrgal svoja oblačila in rekel: »Ojoj, moja hči! Zelo si me potrla in ti si ena izmed tistih, ki me vznemirjajo, kajti svoja usta sem odprl h Gospodu in se ne morem obrniti nazaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Rekla mu je: »Moj oče, če si svoja usta odprl h Gospodu, mi stori glede na to, kar je prišlo iz tvojih ust, kakor se je Gospod zate maščeval na tvojih sovražnikih, na Amónovih otrocih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Svojemu očetu je rekla: »Naj mi bo storjena ta stvar. Dva meseca me pusti samo, da lahko grem gor in dol po gorah in objokujem svoje devištvo, jaz in moje prijateljice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Rekel je: »Pojdi.« In za dva meseca jo je poslal proč in odšla je s svojimi družabnicami ter po gorah objokovala svoje devištvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Pripetilo se je ob koncu dveh mesecev, da se je vrnila k svojemu očetu, ki je z njo storil glede na svojo zaobljubo, ki jo je prisegel. Nobenega moškega ni spoznala. In to je bil zakon v Izraelu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'da so Izraelove hčere vsako leto odšle, da štiri dni v letu objokujejo hčer Gileádca Jefteja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Možje iz Efrájima so se zbrali skupaj in odšli proti severu in rekli Jefteju: »Zakaj prehajaš preko, da se boriš zoper Amónove otroke, nas pa nisi poklical, da gremo s teboj? Nad teboj bomo tvojo hišo požgali z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jefte jim je rekel: »Jaz in moje ljudstvo smo bili v velikem boju z Amónovimi otroki in ko sem vas poklical, me niste osvobodili iz njihovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Ko sem videl, da me niste osvobodili, sem svoje življenje vzel v svoje roke in šel preko, proti Amónovim otrokom in Gospod jih je izročil v mojo roko. Zakaj ste torej vi ta dan prišli gor do mene, da se borite zoper mene?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Potem je Jefte zbral skupaj vse gileádske može in se bojeval z Efrájimom in gileádski možje so udarili Efrájim, ker so rekli: »Vi Gileádčani ste ubežniki iz Efrájima med Efrájimci in Manásejci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Gileádčani so pred Efrájimci zavzeli jordanske prehode. In bilo je tako, da ko so tisti Efrájimci, ki so pobegnili, rekli: »Naj grem preko,« da so mu gileádski možje rekli: » Ali si Efrájimec?« Če je rekel: »Ne,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'potem so mu rekli: »Reci sedaj Šibólet« in je rekel »Sibólet,« kajti tega ni mogel pravilno naglasiti. Potem so ga prijeli in usmrtil pri jordanskih prehodih in tam jih je ob tistem času izmed Efrájimcev padlo dvainštirideset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jefte je Izraelu sodil šest let. Potem je Gileádčan Jefte umrl in bil pokopan v enem izmed mest Gileáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Za njim je Izraelu sodil Ibcán iz Betlehema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Ta je imel trideset sinov in trideset hčera, ki jih je poslal naokrog in za svoje sinove je vzel trideset hčera od drugod. Izraelu je sodil sedem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Potem je Ibcán umrl in je bil pokopan pri Betlehemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Za njim je Izraelu sodil Zábulonec Elón. Izraelu je sodil deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Zábulonec Elón je umrl in je bil pokopan v Ajalónu, v deželi Zábulon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Za njim je Izraelu sodil Abdón, sin Piratónca Hiléla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ta je imel štirideset sinov in trideset nečakov, ki so jahali na sedemdesetih osličjih žrebetih. Izraelu je sodil osem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Abdón, sin Piratónca Hiléla, je umrl in je bil pokopan v Piratónu, v deželi Efrájim, na gori Amalečanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Izraelovi otroci so ponovno počeli zlo v Gospodovih očeh in Gospod jih je za štirideset let izročil v roko Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Tam pa je bil nek mož iz Core, iz družine Danovcev, katerega ime je bilo Manóah. Njegova žena pa je bila jalova in ni rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Gospodov angel se je prikazal ženski in ji rekel: »Glej torej, jalova si in ne rojevaš, toda spočela boš in rodila sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Zdaj se torej pazi, prosim te in ne pij ne vina ne močne pijače in ne jej nobene nečiste stvari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'kajti glej, spočela boš in rodila sina in nobena britev ne bo prišla na njegovo glavo, kajti otrok bo od maternice nazirec Bogu in on bo začel Izraela osvobajati iz roke Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Potem je ženska prišla in svojemu soprogu povedala, rekoč: »Božji mož je prišel k meni in njegovo obličje je bilo podobno obličju Božjega angela, zelo strašno. Toda nisem ga vprašala, od kje je bil niti mi ni povedal svojega imena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'toda rekel mi je: ›Glej, spočela boš in rodila sina. Sedaj ne pij ne vina niti močne pijače, tudi ne jej nobene nečiste stvari, kajti otrok bo od maternice nazirec Bogu do dneva svoje smrti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Potem je Manóah rotil Gospoda in rekel: »Oh moj Gospod, naj Božji mož, ki si ga poslal, ponovno pride k nama in naju pouči, kaj bova storila otroku, ki bo rojen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Bog je prisluhnil Manóahovemu glasu in Božji angel je ponovno prišel k ženski, medtem ko je sedela na polju, toda njen soprog Manóah ni bil z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Ženska je pohitela, stekla in pokazala svojemu soprogu ter mu rekla: »Glej, mož se mi je prikazal, ki je prišel k meni oni dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manóah je vstal in odšel za svojo ženo in prišel k možu ter mu rekel: » Ali si ti mož, ki govoriš ženski?« Rekel je: »Jaz sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Manóah je rekel: »Sedaj naj se tvoje besede zgodijo. Kako naj določiva otroku in kako mu bova storila?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Gospodov angel je Manóahu rekel: »Pred vsem, kar sem rekel ženski, naj se ona pazi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ne sme jesti nobene stvari, ki prihaja od vina, niti naj ne pije vina ali močne pijače, niti naj ne jé nobene nečiste stvari; vsega, kar sem ji zapovedal, naj se drži.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manóah je rekel Gospodovemu angelu: »Prosim te, naj te zadrživa, dokler zate ne bova pripravila kozlička.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Gospodov angel je Manóahu rekel: »Čeprav me zadržiš, ne bom jedel od vajinega kruha. Če pa hočeš darovati žgalno daritev, jo moraš darovati Gospodu.« Kajti Manóah ni vedel, da je bil to Gospodov angel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Manóah je Gospodovemu angelu rekel: »Kakšno je tvoje ime, potem ko se izpolnijo tvoje besede, da ti lahko izkaževa čast?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Gospodov angel mu je rekel: »Zakaj sprašuješ po mojem imenu, glede na to, da je to skrivnost?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Tako je Manóah vzel kozliča z jedilno daritvijo in ga na skali daroval Gospodu in angel je čudežno storil in Manóah in njegova žena sta to videla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Kajti pripetilo se je, ko se je plamen iz oltarja povzpel proti nebu, da se je Gospodov angel dvignil v oltarnem plamenu. Manóah in njegova žena sta pogledala na to in padla na svoja obraza k tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Toda Gospodov angel se ni več prikazal Manóahu in njegovi ženi. Potem je Manóah vedel, da je bil to Gospodov angel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Manóah je svoji ženi rekel: »Midva bova zagotovo umrla, ker sva videla Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Toda njegova žena mu je rekla: »Če bi Gospodu ugajalo, da naju ubije, ne bi pri najinih rokah sprejel žgalne daritve in jedilne daritve, niti nama ne bi pokazal vseh teh stvari, niti nama ob tem času ne bi povedal takšnih stvari, kot so te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Ženska je rodila sina in njegovo ime imenovala Samson. In otrok je rastel in Gospod ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'In Gospodov Duh ga je občasno začel spodbujati v Danovem taboru, med Coro in Eštaólom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Samson je odšel dol v Timno in v Timni zagledal žensko izmed filistejskih hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Prišel je gor in svojemu očetu in svoji materi povedal ter rekel: »V Timni sem videl žensko izmed filistejskih hčera. Sedaj mi jo torej vzemita za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Potem sta mu njegov oče in njegova mati rekla: » Ali tam ni nobene ženske med hčerami tvojih bratov ali med vsem mojim ljudstvom, da greš, da si vzameš ženo izmed neobrezanih Filistejcev?« Samson je rekel svojemu očetu: »Njo mi vzemi, kajti ta mi ugaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Toda njegov oče in njegova mati nista vedela, da je bilo to od Gospoda, da je iskal priložnost zoper Filistejce, kajti ob tistem času so imeli Filistejci gospostvo nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Potem so Samson, njegov oče in njegova mati odšli dol v Timno in prišli do timnatskih vinogradov in glej, proti njemu je zarjovel mlad lev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Gospodov Duh je mogočno prišel nadenj in raztrgal ga je, kakor bi raztrgal kozliča in ničesar ni imel v svoji roki, toda svojemu očetu ali svoji materi ni povedal, kaj je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Odšel je dol in govoril z žensko in Samsonu je ugajala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Čez nekaj časa se je vrnil, da jo vzame in zavil je stran, da pogleda levje truplo in glej, tam je bil roj čebel in med v levjem truplu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Od tega je vzel v svoje roke in jedoč šel naprej in prišel k svojemu očetu in materi ter jima dal in onadva sta jedla. Toda ni jima povedal, da je med vzel iz levjega trupla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Tako je njegov oče odšel dol k ženski in Samson je tam priredil zabavo, kajti tako so imeli mladeniči navado delati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Pripetilo se je, ko so ga zagledali, da so privedli trideset družabnikov, da bi bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Samson jim je rekel: »Sedaj vam bom zastavil uganko. Če mi jo lahko v sedmih dneh praznovanja zagotovo razodenete in jo odkrijete, potem vam bom dal trideset rjuh in trideset zamenjav oblek,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'toda če mi je ne morete oznaniti, potem mi boste vi dali trideset rjuh in trideset zamenjav oblek.« Rekli so mu: »Zastavi svojo uganko, da jo bomo lahko slišali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Rekel jim je: »Iz jedca je prišla hrana in iz močnega je izšla sladkost.« In v treh dneh niso mogli pojasniti uganke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Pripetilo se je na sedmi dan, da so Samsonovi ženi rekli: »Premami svojega soproga, da nam lahko oznani uganko, sicer bomo tebe in hišo tvojega očeta zažgali z ognjem. Ali ste nas poklicali, da vzamete kar imamo? Mar ni tako?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Samsonova žena je jokala pred njim ter rekla: »Ti me le sovražiš in me ne ljubiš. Otrokom mojega ljudstva si zastavil uganko, meni pa je nisi povedal.« Rekel ji je: »Glej, nisem je povedal svojemu očetu niti svoji materi in jo bom povedal tebi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Pred njim je jokala sedem dni, dokler je trajala njihova zabava in pripetilo se je na sedmi dan, da ji je povedal, ker je boleče pritiskala nanj in uganko je povedala otrokom svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Možje iz mesta so mu sedmi dan, preden je sonce zašlo, rekli: »Kaj je slajše od meda? In kaj je močnejše kakor lev?« Rekel jim je: »Če ne bi orali z mojo telico, ne bi odkrili moje uganke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'In Gospodov Duh je prišel nadenj in odšel je dol v Aškelón in izmed njih usmrtil trideset mož, vzel njihov plen in dal zamenjavo oblačil tistim, ki so pojasnili uganko. Njegova jeza je bila vžgana in odšel je gor do hiše svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Toda Samsonova žena je bila dana njegovemu družabniku, ki ga je uporabil kakor svojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Toda pripetilo se je čez nekaj časa, ob času pšenične žetve, da je Samson s kozličem obiskal svojo ženo in rekel: »Šel bom noter k svoji ženi v sobo.« Toda njen oče mu ni dovolil vstopiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Njen oče je rekel: »Resnično sem mislil, da si jo popolnoma zasovražil, zato sem jo dal tvojemu družabniku. Mar ni njena mlajša sestra boljša od nje? Vzemi njo, prosim te, namesto nje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Samson je glede njih rekel: »Sedaj bom bolj brez krivde kakor Filistejci, čeprav jim storim zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Samson je odšel in ujel tristo lisic in vzel kose tlečega lesa in obrnil rep k repu in kos tlečega lesa položil v sredo med dva repa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Ko je kose tlečega lesa zažgal, jih je spustil v stoječe žito Filistejcev in zažgal tako snope, kot tudi stoječe žito, z vinogradi in oljkami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Potem so Filistejci rekli: »Kdo je to storil?« Odgovorili so: »Samson, zet Timnčana, ker je ta vzel njegovo ženo in jo dal njegovemu družabniku.« In Filistejci so prišli gor in z ognjem zažgali njo in njenega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Samson jim je rekel: »Čeprav ste to storili, se vam bom vendarle maščeval in potem bom odnehal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Udaril jih je, golen in stegno, z velikim pokolom in odšel dol ter prebival na vrhu skale Etám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Potem so Filistejci odšli gor, se utaborili v Judu in se razširili v Lehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Možje iz Juda so rekli: »Zakaj ste prišli gor zoper nas?« Odgovorili so: »Gor smo prišli, da zvežemo Samsona, da mu storimo, kakor je on storil nam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Potem je tri tisoč mož iz Juda odšlo na vrh skale Etám in reklo Samsonu: »Mar ne veš, da so Filistejci vladarji nad nami? Kaj je to, kar si nam storil?« Rekel jim je: »Kakor so storili meni, tako sem jaz storil njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Rekli so mu: »Prišli smo dol, da te zvežemo, da te lahko izročimo v roko Filistejcev.« Samson jim je rekel: »Prisezite mi, da vi sami ne boste padli name.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Odgovorili so mu, rekoč: »Ne, temveč te bomo trdno zvezali in te izročili v njihovo roko, toda mi te zagotovo ne bomo ubili.« Zvezali so ga z dvema novima vrvema in ga od skale privedli gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Ko je prišel v Lehi, so Filistejci zavpili zoper njega in nadenj je mogočno prišel Gospodov Duh in vrvi, ki so bile na njegovih laktih, so postale kakor lan, ki je bil zažgan z ognjem in njegove vezi so se sprostile iz njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Našel je novo oslovsko čeljustnico, iztegnil svojo roko, jo vzel in z njo usmrtil tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Samson je rekel: »Z oslovsko čeljustnico, kupi na kupe, z oslovsko čeljustjo sem umoril tisoč mož.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Ko je končal z govorjenjem, se je pripetilo, da je iz svoje roke odvrgel čeljustnico in ta kraj imenoval Ramát Lehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Bil pa je silno žejen in klical h Gospodu ter rekel: »Ti si dal to veliko osvoboditev v roko svojega služabnika in sedaj ali naj umrem od žeje in padem v roko neobrezancev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, '§ Toda Bog je razklal votel kraj, ki je bil v Čestjustnici in iz njega je pritekla voda. Ko jo je pil, je njegov duh ponovno prišel in bil je oživljen. Zato je njegovo ime imenoval En Koré, ki je v Lehiju, do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'V dneh Filistejcev je Izraelu sodil dvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Potem je Samson odšel v Gazo in tam videl pocestnico in šel noter k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'To je bilo povedano prebivalcem Gaze, rekoč: »Samson je prišel sèm.« Obkolili so ga in vso noč prežali nanj v velikih vratih mesta in vso noč so mirovali, rekoč: »Zjutraj, ko je dan, ga bomo umorili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Samson je ležal do polnoči, ob polnoči pa je vstal, vzel vrata velikih vrat mesta in dva podboja in z njimi odšel proč, zapah in vse in si jih naložil na svoje rame in jih odnesel gor na vrh hriba, ki je pred Hebrónom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Potem se je pripetilo, da je ljubil žensko v dolini Sorék, ki ji je bilo ime Dalíla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Filistejski knezi so prišli gor k njej in ji rekli: »Premami ga in poglej kje tiči njegova velika moč in s kakšnimi sredstvi bi lahko prevladali zoper njega, da bi ga lahko zvezali, da ga oslabimo, mi pa ti bomo dali, vsak izmed nas, tisoč sto koščkov srebra.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Dalíla je rekla Samsonu: »Povej mi, prosim te, kje leži tvoja velika moč in s čim bi bil lahko zvezan, da se te oslabi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Samson ji je rekel: »Če me zvežejo s sedmimi zelenimi vrvmi, ki niso bile nikoli posušene, potem bom slaboten in bom kakor drug človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Potem so filistejski knezi gor k njej prinesli sedem zelenih vrvi, ki niso bile posušene in ona ga je z njimi zvezala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Torej tam so v zasedi prežali možje, ki so z njo ostajali v sobi. Rekla mu je: »Filistejci nadte Samson.« Potrgal je vrvi, kakor se pretrga nit prediva, ko se dotakne ognja. Tako njegova moč ni bila poznana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Dalíla je rekla Samsonu: »Glej, zasmehoval si me in mi govoril laži. Sedaj mi povej, prosim te, s čim bi bil lahko zvezan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Rekel ji je: »Če bi me trdno zvezali z novimi vrvmi, ki niso bile nikoli uporabljene, potem bi bil šibek in bi bil kakor drug človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Zato je Dalíla vzela nove vrvi, ga z njimi zvezala in mu rekla: »Filistejci nadte Samson.« In tam so bili prežavci v zasedi, ki so ostajali v sobi. In potrgal jih je iz svojih rok kakor nit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Dalíla je rekla Samsonu: »Doklej si me zasmehoval in mi govoril laži. Povej mi s čim naj bi bil zvezan.« Rekel ji je: »Če stkeš sedem pramenov moje glave s tkalčjim osnutkom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'In pritrdila ga je z iglo in mu rekla: »Filistejci nadte Samson.« Prebudil se je iz svojega spanja in odšel s tkalsko iglo in s tkalčjim osnutkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Rekla mu je: »Kako lahko rečeš: ›Ljubim te,‹ ko tvoje srce ni z menoj?« Že trikrat si me zasmehoval in mi nisi povedal, v čem leži tvoja velika moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Ko ga je dnevno pritiskala s svojimi besedami in ga silila, tako da je bila njegova duša vznemirjena do smrti, se je pripetilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'da ji je izpovedal vse svoje srce in ji rekel: »Britev ni prišla na mojo glavo, kajti bil sem nazirec Bogu od maternice svoje matere. Če bom obrit, potem bo moja moč odšla od mene in postanem slaboten in bom podoben kateremukoli drugemu človeku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Ko je Dalíla videla, da ji je izpovedal vse svoje srce, je poslala in dala poklicati filistejske kneze, rekoč: »Pridite tokrat gor, kajti razodel mi je vse svoje srce.« Potem so gor k njej prišli gospodarji Filistejcev in v svoji roki prinesli denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Pripravila ga je, da je zaspal na njenih kolenih in dala poklicati moža, da mu iz njegove glave odstriže sedem pramenov in ga začela poniževati in njegova moč je odšla od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Rekla je: »Filistejci nadte Samson.« Prebudil se je iz svojega spanja in rekel: »Šel bom ven kakor ob drugih časih poprej in se stresel.« Ni pa vedel, da je Gospod odšel od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Toda Filistejci so ga prijeli in iztaknili njegove oči in ga privedli dol v Gazo in ga zvezali z bronastimi okovi in mlel je v jetnišnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Vendar so potem, ko je bil ostrižen, lasje njegove glave začeli ponovno rasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Potem so se filistejski knezi zbrali skupaj, da svojemu bogu Dagónu darujejo veliko klavno daritev in da se veselijo, kajti rekli so: »Naš bog je v našo roko izročil našega sovražnika Samsona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Ko ga je ljudstvo zagledalo, so hvalili svojega boga, kajti rekli so: »Naš bog je v naše roke izročil našega sovražnika in uničevalca naše dežele, ki je umoril številne izmed nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Pripetilo pa se je, ko so bila njihova srca vesela, da so rekli: »Pokličite Samsona, da nam bo lahko naredil zabavo.« Iz jetnišnice so dali poklicati Samsona in naredil jim je zabavo. Postavili so ga med stebre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Samson pa je rekel dečku, ki ga je držal za roko: »Dopusti mi, da lahko čutim stebre, na katerih stoji hiša, da se lahko naslonim nanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Torej hiša je bila polna mož in žena in vsi filistejski knezi so bili tam in tam je bilo na strehi okoli tri tisoč mož in žena, ki so gledali, medtem ko jih je Samson zabaval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Samson pa je zaklical h Gospodu in rekel: »Oh Gospod Bog, spomni se me, prosim te in okrepi me, prosim te, samo [še] tokrat, oh Bog, da se bom lahko takoj maščeval Filistejcem za svoji dve očesi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Samson se je oklenil dveh srednjih nosilnih stebrov, na katerih, je slonela hiša, na enega s svojo desnico in na drugega s svojo levico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Samson je rekel: »Naj umrem s Filistejci.« Z vso svojo močjo se je sklonil in hiša je padla na kneze in na vse ljudstvo, ki je bilo v njej. Tako je bilo mrtvih, ki jih je usmrtil ob svoji smrti, več kakor tistih, ki jih je usmrtil v svojem življenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Potem so njegovi bratje in vsa hiša njegovega očeta prišli dol, ga vzeli in ga prinesli gor ter ga pokopali med Coro in Eštaólom, na grobišču njegovega očeta Manóaha. Izraelu je sodil dvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Tam je bil mož z gore Efrájim, katerega ime je bilo Miha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Ta je rekel svoji materi: »Tisoč sto šeklov srebra, ki so bili vzeti od tebe, glede katerih si preklinjala in glede katerih si govorila tudi v moja ušesa, glej, srebro je z menoj. Jaz sem ga vzel.« Njegova mati je rekla: »Blagoslovljen bodi od Gospoda, moj sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Ko je svoji materi povrnil tisoč sto šeklov srebra, je njegova mati rekla: »Srebro sem v celoti posvetila Gospodu, od svoje roke za svojega sina, da se naredi rezana podoba in ulita podoba. Sedaj ti ga bom torej povrnila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Vendar je denar vrnil svoji materi in njegova mati je vzela dvesto šeklov srebra in jih dala livarju, ki je iz njih naredil rezano podobo in ulito podobo in bili sta v Mihovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Mož Miha je imel hišo bogov in naredil efód in družinskega malika in uméstil enega izmed svojih sinov, ki je postal njegov duhovnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'V tistih dneh ni bilo kralja v Izraelu, temveč je vsak človek počel to, kar je bilo pravilno v njegovih lastnih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Tam je bil mladenič iz Judovega Betlehema, iz Judove družine, ki je bil Lévijevec in se je mudil tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Človek je odrinil iz mesta, iz Judovega Betlehema, da začasno prebiva, kjer bi lahko našel prostor in ko je potoval, je prišel do gore Efrájim, k Mihovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Miha mu je rekel: »Od kod prihajaš?« Odgovoril mu je: »Jaz sem Lévijevec iz Judovega Betlehema in grem, da začasno prebivam tam, kjer bom lahko našel prostor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Miha mu je rekel: »Prebivaj z menoj in bodi mi oče in duhovnik, jaz pa ti bom ob letu dajal deset šeklov srebra in opremo oblačila in živež.« Tako je Lévijevec vstopil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Lévijevec je bil zadovoljen, da prebiva z možem in mladenič mu je bil kakor eden izmed njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Miha je uméstil Lévijevca in mladenič je postal njegov duhovnik in bil je v Mihovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Potem je Miha rekel: »Sedaj vem, da mi bo Gospod storil dobro, glede na to, da imam Lévijevca za svojega duhovnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'V tistih dneh ni bilo kralja v Izraelu in v tistih dneh si je rod Danovcev iskal dediščino, da v njej prebiva, kajti do tistega dne jim vsa njihova dediščina ni pripadla med Izraelovimi rodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Danovi otroci so izmed svojih družin poslali pet moških iz svojih pokrajin, junaške može iz Core in iz Eštaóla, da hodijo vzdolž dežele in da jo preiščejo. Rekli so jim: »Pojdite, oglejte deželo.« Ko so le-ti prišli do gore Efrájim, k Mihovi hiši, so se tam nastanili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Ko so bili pri Mihovi hiši, so prepoznali glas mladeniča, Lévijevca. Obrnili so se tja in mu rekli: »Kdo te je privedel sèm? Kaj delaš na tem kraju? In kaj imaš tukaj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Odgovoril jim je: »Tako in tako je Miha postopal z menoj, me najel in sem njegov duhovnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Rekli so mu: »Prosimo te, vprašaj za nasvet od Boga, da bomo lahko vedeli katera izmed naših poti, po kateri gremo, bo uspešna.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Duhovnik jim je rekel: »Pojdite v miru. Vaša pot, po kateri greste, je pred Gospodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Potem je pet mož odpotovalo in prišlo k Láješu in videlo ljudstvo, ki je bilo tam, kako so brezskrbno prebivali po navadi Sidóncev, tiho in varno. Tam v deželi ni bilo naseljencev, da bi jih lahko v kakršnikoli stvari osramotili. Bili so daleč od Sidóncev in z nikomer niso imeli nič opraviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Prišli so k svojim bratom do Core in Eštaóla in njihovi bratje so jim rekli: »Kaj pravite?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Odgovorili so: »Vstanite, da bomo lahko šli gor zoper njih, kajti videli smo deželo in glejte, ta je zelo dobra. In vi ste mirni? Ne bodite leni, da bi šli in vstopili, da vzamete deželo v last.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Ko greste, boste prišli k varnemu ljudstvu in k veliki deželi, kajti Bog jo je dal v vaše roke. Prostor, kjer ni pomanjkanja česarkoli, kar je na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Od tod je odšla družina Danovcev na svojo pot, iz Core in iz Eštaóla, šeststo mož, opasanih z bojnim orožjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Odšli so gor in se utaborili v Kirját Jearímu v Judu. Zato so ta kraj imenovali Mahané Dan do današnjega dne. Glej ta je poleg Kirját Jearíma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Od tam so prešli h gori Efrájim in prišli do Mihove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Potem je pet mož, ki so odšli, da ogledajo deželo Láješ, odgovorilo in reklo svojim bratom: »Ali veste, da so v teh hišah efód, družinski malik, rezana podoba in ulita podoba? Sedaj torej preudarite kaj vam je storiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Obrnili so se tja in prišli do hiše mladeniča, Lévijevca, torej k Mihovi hiši in ga pozdravili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Šeststo mož, opasanih s svojimi bojnimi orožji, ki so bili izmed Danovih otrok, pa je stalo pri vhodu velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Pet mož, ki so šli, da ogledajo deželo, je odšlo gor in vstopili so tja in vzeli rezano podobo, efód, družinskega malika in ulito podobo. Duhovnik pa je stal na vhodu velikih vrat s šeststotimi možmi, ki so bili opasani z bojnim orožjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Ti so odšli v Mihovo hišo in prinesli izrezljano podobo, efód, družinskega malika in ulito podobo. Potem jim je duhovnik rekel: »Kaj počnete?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Rekli so mu: »Molči, svojo roko položi na svoja usta in pojdi z nami in nam bodi oče in duhovnik. Ali je zate bolje biti duhovnik hiši enega človeka ali da postaneš duhovnik rodu in družini v Izraelu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Duhovnikovo srce je bilo veselo in vzel je efód, družinskega malika, rezano podobo in odšel v sredo ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Tako so se obrnili in odšli ter predse postavili malčke, živino in vozove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'In ko so bili dobro pot od Mihove hiše, so se ljudje, ki so bili v hišah blizu Mihove hiše, zbrali skupaj in dohiteli Danove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Klicali so k Danovim otrokom. Ti pa so obrnili svoje obraze in Mihu rekli: »Kaj te pesti, da prihajaš s takšnim spremstvom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Odgovoril je: »Odvzeli ste moje bogove, ki sem jih naredil in duhovnika ter odšli proč. In kaj še imam? Kaj je to, da mi pravite: ›Kaj te pesti?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Danovi otroci so mu rekli: »Tvojega glasu naj ne bo slišati med nami, da ne bi jezni ljudje stekli nadte in bi izgubil svoje življenje, z življenji svoje družine.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Danovi otroci so odšli svojo pot. Ko je Miha videl, da so bili premočni zanj, se je obrnil in se vrnil nazaj k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Vzeli so stvari, ki jih je naredil Miha in duhovnika, ki ga je imel in prišli k Láješu, k ljudstvu, ki je bilo tiho in varno. Udarili so jih z ostrino meča in mesto zažgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Tam ni bilo nobenega osvoboditelja, ker je bilo daleč od Sidóna in niso imeli opravka s kakršnimkoli človekom. To je bilo v dolini, ki leži pri Bet Rehóbu. In zgradili so mesto ter prebivali v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Ime mesta so imenovali Dan, po imenu njihovega očeta Dana, ki je bil rojen Izraelu, vendar je bilo ime mesta najprej Láješ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Danovi otroci so postavili rezano podobo in Jonatan, sin Geršóma, sinú Manáseja, on in njegovi sinovi so bili duhovniki Danovemu rodu do dneva ujetništva dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Postavili so si Mihovo rezano podobo, ki jo je naredil ves ta čas, ko je bila Božja hiša v Šilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Pripetilo se je v tistih dneh, ko ni bilo kralja v Izraelu, da je bil tam nek Lévijevec, [ki je] začasno prebival na pobočju gore Efrájim, ki si je vzel priležnico iz Judovega Betlehema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Njegova priležnica je zoper njega igrala vlačugo in odšla proč od njega, v hišo svojega očeta v Judovem Betlehemu in bila tam cele štiri mesece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Njen soprog je vstal in odšel za njo, da ji prijateljsko govori in da jo ponovno privede. S seboj je imel svojega služabnika in nekaj oslov in privedla ga je v hišo svojega očeta. Ko ga je oče od gospodične zagledal, se je razveselil, da ga je srečal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Njegov tast, oče od gospodične, ga je zadržal in z njimi je ostal tri dni. Tako so jedli in pili ter tam prenočevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Pripetilo se je na četrti dan, ko so zgodaj zjutraj vstali, da se je dvignil, da odide. Oče od gospodične pa je svojemu zetu rekel: »Potolaži svoje srce z grižljajem kruha in potem pojdi svojo pot.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Oba skupaj sta se usedla, jedla in pila, kajti oče od gospodične je možu rekel: »Privoli, prosim te in ostani vso noč in naj bo tvoje srce veselo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Ko je mož vstal, da odide, mu je tast prigovarjal, zato je tam ponovno prenočil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Vstal je zgodaj zjutraj, peti dan, da odide in oče od gospodične je rekel: »Potolaži svoje srce, prosim te.« Ostala sta do popoldneva in oba sta jedla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Ko je mož vstal, da odide, on, njegova priležnica in njegov služabnik, mu je tast, oče od gospodične, rekel: »Glej, sedaj se dan približuje večeru. Prosim te, ostani vso noč. Glej, dan gre h koncu, prenočuj tukaj, da bo tvoje srce lahko veselo in naslednji dan zgodaj pojdi na svojo pot, da boš lahko šel domov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Toda mož to noč ni hotel ostati, temveč je vstal, odšel in prišel nasproti Jebúsa, ki je Jeruzalem in tam sta bila z njim dva osedlana osla in tudi njegova priležnica je bila z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'In ko so bili pri Jebúsu, je bil dan že davno porabljen in služabnik je rekel svojemu gospodarju: »Pridi, prosim te in obrniva se v to mesto Jebusejcev in prenočiva v njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Njegov gospodar pa mu je rekel: »Ne bomo zavili vstran, sèm v to mesto tujca, ki ni izmed Izraelovih otrok; prešli bomo do Gíbee.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Svojemu služabniku je rekel: »Pridi in približajmo se enemu izmed teh mest, da vso noč prenočimo v Gíbei ali v Rami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Šli so naprej svojo pot in sonce je zašlo nad njimi, ko so bili pri Gíbei, ki pripada Benjaminu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Obrnili so se tja, da vstopijo in prenočijo v Gíbei. Ko so vstopili, se je usedel na mestno ulico, kajti tam ni bilo nobenega človeka, ki bi jih vzel v svojo hišo, da prenočijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Glej, zvečer je prišel starec od svojega dela zunaj na polju, ki je bil prav tako z gore Efrájim in je začasno prebival v Gíbei. Toda možje kraja so bili Benjaminovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Ko je povzdignil svoje oči, je na mestni ulici zagledal popotnika in starec je rekel: »Kam greš? In od kod prihajaš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Ta mu je odgovoril: »Mi smo prešli iz Judovega Betlehema proti pobočju gore Efrájim. Od tam sem in odšel sem k Judovemu Betlehemu, toda sedaj grem h Gospodovi hiši. Tukaj pa ni nobenega moža, ki bi me sprejel v hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Vendar je tukaj tako slama in krma za naša osla in tukaj je kruh in vino zame in za mojo pomočnico in za mladeniča, ki je s tvojimi služabniki. Tukaj ni potrebe po nobeni stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Starec je rekel: »Mir bodi s teboj. Kakorkoli, pusti vse svoje potrebe počivati na meni, samo ne prenočuj na ulici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Tako ga je odvedel v svojo hišo in dal krmo k oslom. Umili so svoja stopala, jedli in pili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Torej ko so razveseljevali svoja srca, glej, so možje iz mesta, neki Beliálovi sinovi, naokoli obkrožili hišo in udarjali na vrata ter hišnemu gospodarju, starcu, spregovorili, rekoč: »Privedi moškega, ki je prišel v tvojo hišo, da ga lahko spoznamo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Mož, hišni gospodar, je odšel ven k njim ter jim rekel: »Ne, moji bratje, ne, prosim vas, ne storite tako zlobno, glede na to, da je ta mož prišel v mojo hišo, ne storite te neumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Glejte, tukaj je moja hči, devica in njegova priležnica. Njiju bom torej privedel ven in ju ponižajte ter z njima storite kar se vam zdi dobro, toda temu možu ne storite tako ogabne stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Toda možje mu niso hoteli prisluhniti. Tako je mož vzel svojo priležnico in jo privedel k njim. Spoznali so jo in jo zlorabljali vso noč do jutra. Ko pa se je dan začel svitati, so jo pustili oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Potem je ob jutranjem svitanju ženska prišla in padla dol pri vratih moževe hiše, kjer je bil njen gospodar, dokler ni bilo svetlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Njen gospodar je zjutraj vstal, odprl vrata hiše in odšel ven, da gre svojo pot. In glej, ženska, njegova priležnica, je bila zvrnjena dol pri hišnih vratih in njene roke so bile na pragu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Rekel ji je: »Vstani in pojdimo.« Toda ni se odzvala. Potem jo je mož vzel gor na osla in mož se je dvignil ter se spravil k svojemu kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Ko je prišel v svojo hišo, je vzel nož in ga položil na svojo priležnico in jo razdelil na dvanajst kosov, skupaj z njenimi kostmi in jo poslal po vseh Izraelovih pokrajinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'In bilo je tako, da so vsi, ki so to videli, rekli: »Takšnega dejanja ni bilo storjenega niti videnega od dneva, ko so Izraelovi otroci prišli gor iz egiptovske dežele, do današnjega dne. Preudarite o tem, sprejmite nasvet in govorite svojim umom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Potem so vsi Izraelovi otroci odšli ven in skupnost je bila zbrana skupaj kakor en mož, od Dana, celo do Beeršébe, z gileádsko deželo, h Gospodu v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Vodje izmed vsega ljudstva, torej izmed vseh Izraelovih rodov, so se predstavili v zboru Božjega ljudstva, štiristo tisoč pešcev, ki so izdirali meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(Torej Benjaminovi otroci so slišali, da so Izraelovi otroci odšli gor do Micpe.) Potem so Izraelovi otroci rekli: »Povej nam, kako je bila ta zlobnost?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Lévijevec, soprog ženske, ki je bila umorjena, je odgovoril in rekel: »Prišel sem v Gíbeo, ki pripada Benjaminu, jaz in moja priležnica, da prenočiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Možje iz Gíbee pa so vstali zoper mene in ponoči obdali hišo naokoli mene in me mislili umoriti. Mojo priležnico pa so posilili, da je mrtva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Vzel sem svojo priležnico, jo razsekal na kose in jo razposlal po vsej deželi Izraelove dediščine, kajti v Izraelu so zagrešili nespodobnost in neumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Glejte, vi vsi ste Izraelovi otroci, dajte tukaj svojo besedo in nasvet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Vse ljudstvo je vstalo kakor en mož, rekoč: »Nobeden izmed nas ne bo šel k svojemu šotoru niti se nobeden izmed nas ne bo obrnil v svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Toda sedaj bo to stvar, ki jo bomo storili Gíbei. Šli bomo gor po žrebu zoper njo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'in vzeli bomo po vseh Izraelovih rodovih deset mož izmed sto in sto izmed tisoč in tisoč izmed deset tisoč, da prinesejo živež za ljudstvo, da bodo lahko delali, ko pridejo v Benjaminovo Gíbeo, glede na vso neumnost, ki so jo oni storili v Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Tako so bili vsi Izraelovi možje, zbrani zoper mesto, povezani skupaj kakor en mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Izraelovi rodovi so poslali može skozi ves Benjaminov rod, rekoč: »Kakšna zlobnost je ta, ki je bila storjena med vami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Zdaj nam torej izročite može, Beliálove otroke, ki so v Gíbei, da jih lahko usmrtimo in iz Izraela odstranimo zlo.« Toda Benjaminovi otroci niso hoteli prisluhniti glasu njihovih bratov, Izraelovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'temveč so se Benjaminovi otroci zbrali skupaj iz vseh mest v Gíbeo, da gredo ven, da se bojujejo zoper Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Benjaminovi otroci so bili ob tistem času prešteti iz mest, šestindvajset tisoč mož, ki so izdirali meč, poleg prebivalcev Gíbee, katerih je bilo preštetih sedemsto izbranih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Med vsem tem ljudstvom je bilo tam sedemsto izbranih mož, ki so bili levični. Vsak je lahko metal kamne za las natančno in ni zgrešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Mož iz Izraela, poleg Benjamina, je bilo preštetih štiristo tisoč mož, ki so izdirali meč. Vsi ti so bili bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Izraelovi otroci so vstali in odšli gor h Gospodovi hiši in vprašali za nasvet od Boga ter rekli: »Kdo izmed nas bo prvi šel gor v bitko zoper Benjaminove otroke?« Gospod je rekel: »Juda bo prvi šel gor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Izraelovi otroci so zjutraj vstali in se utaborili zoper Gíbeo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Izraelovi možje so odšli ven, da se bojujejo zoper Benjamina. Izraelovi možje so se razvrstili, da se bojujejo zoper te v Gíbei.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Benjaminovi otroci so prišli ven iz Gíbee in izmed Izraelcev ta dan do tal uničili dvaindvajset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Ljudstvo Izraelovih mož se je ohrabrilo in svojo bitko ponovno razvrstilo na kraju, kjer so se razvrstili prvi dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, '(Izraelovi otroci so odšli gor in do večera jokali pred Gospodom in prosili Gospoda za nasvet, rekoč: »Ali naj grem ponovno gor v bitko zoper otroke Benjamina, svojega brata?« Gospod je rekel: »Pojdite gor zoper njih.«)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Izraelovi otroci so se drugi dan približali zoper Benjaminove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Benjamin je drugi dan odšel naprej, ven iz Gíbee, zoper njih in izmed Izraelovih otrok do tal ponovno uničil osemnajst tisoč mož. Vsi ti so izdirali meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Potem so vsi Izraelovi otroci in vse ljudstvo odšli gor in prišli k Božji hiši, jokali in tam sedeli pred Gospodom in se ta dan postili do večera in pred Gospodom darovali žgalne daritve in mirovne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Izraelovi otroci so poizvedeli od Gospoda (kajti skrinja Božje zaveze je bila v tistih dneh tam');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'in Pinhás, sin Eleazarja, sinú Arona, je v tistih dneh stal pred njo), rekoč: »Ali naj grem ponovno ven v bitko zoper otroke Benjamina, svojega brata ali naj odneham?« Gospod je rekel: »Pojdi gor, kajti jutri ti jih bom izročil v roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Izrael je okoli Gíbee postavil prežavce v zasedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Izraelovi otroci so na tretji dan odšli gor zoper Benjaminove otroke in se kakor poprej razvrstili zoper Gíbeo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Benjaminovi otroci so odšli ven zoper ljudstvo in bili so odvlečeni od mesta in začeli udarjati izmed ljudstva in ubili trideset mož iz Izraela, kakor poprej na glavnih cestah, od katerih gre ena gor k Božji hiši, druga pa h Gíbei na polje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Benjaminovi otroci so rekli: »Udarjeni so pred nami kakor poprej.« Toda Izraelovi otroci so rekli: »Bežimo in jih od mesta potegnimo h glavnim cestam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Vsi Izraelovi možje so se dvignili iz svojega kraja in se razvrstili pri Báal Tamari. Izraelovi prežavci v zasedi pa so prišli naprej iz svojih krajev, torej iz travnikov Gíbee.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Tam je prišlo zoper Gíbeo deset tisoč izbranih mož iz vsega Izraela in bitka je bila huda. Toda niso vedeli, da je bilo zlo blizu njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Gospod je udaril Benjamina pred Izraelom in Izraelovi otroci so izmed Benjaminovcev ta dan uničili petindvajset tisoč in sto mož. Vsi ti so izdirali meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Tako so Benjaminovi otroci videli, da so bili udarjeni, kajti možje iz Izraela so dali prostor Benjaminovcem, ker so zaupali v prežavce v zasedi, ki so jih postavili poleg Gíbee.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Prežalci v zasedi so pohiteli in navalili na Gíbeo in prežavci v zasedi so šli vzdolž in vse mesto udarili z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Torej tam je bilo določeno znamenje med Izraelovimi možmi in prežavci v zasedi, da naj bi naredili velik plamen z dimom, ki se vzdiguje iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Ko so se Izraelovi možje obrnili v bitko, je Benjamin začel udarjati in izmed Izraelovih mož ubil okoli trideset oseb, kajti rekli so: »Zagotovo so udarjeni pred nami kakor v prvi bitki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Toda ko se je plamen s stebrom dima začel dvigovati iz mesta, so Benjaminovci pogledali za seboj in glej, plamen mesta se je vzdigoval k nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Ko so se Izraelovi možje ponovno obrnili, so bili možje Benjamina osupli, kajti videli so, da je nadnje prišlo zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Zato so svoje hrbte obrnili pred Izraelovimi možmi na pot divjine, toda bitka jih je dohitela in tiste, ki so prišli iz mest, so uničili v njihovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Tako so naokoli obkolili Benjaminovce in jih preganjali in jih z lahkoto pomendrali nasproti Gíbei, proti sončnemu vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Tam je iz Benjamina padlo osemnajst tisoč mož. Vsi ti so bili junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'In obrnili so se in pobegnili proti divjini, k Rimónovi skali. In od njih so zbrali po glavnih cestah pet tisoč mož in trdo so jih zasledovati do Gidóma in jih izmed njih usmrtili dva tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Tako, da je bilo vseh, ki so ta dan padli iz Benjamina, petindvajset tisoč mož, ki so izdirali meč. Vsi ti so bili junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Toda šeststo mož se je obrnilo in pobegnilo v divjino, k Rimónovi skali in v Rimónovi skali so ostali štiri mesece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Izraelovi možje so se ponovno obrnili nad Benjaminove otroke in jih udarili z ostrino meča, kakor tudi može iz vsakega mesta, tako žival in vse, kar je prišlo k roki. Prav tako so požgali vsa mesta, h katerim so prišli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Torej možje iz Izraela so v Micpi prisegli, rekoč: »Nihče izmed nas svoje hčere ne bo dal Benjaminu za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Ljudstvo je prišlo k Božji hiši in tam so ostali do večera pred Bogom in povzdignili svoje glasove in bridko jokali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'in rekli: »Oh Gospod, Izraelov Bog, zakaj se je to zgodilo v Izraelu, da danes manjka en rod v Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Pripetilo se je naslednji dan, da je ljudstvo zgodaj vstalo, tam zgradilo oltar in darovalo žgalne daritve in mirovne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Izraelovi otroci so rekli: »Kdo je tam med vsemi Izraelovimi rodovi, ki s skupnostjo ni prišel gor h Gospodu?« Kajti sklenili so veliko prisego glede tistega, ki ne pride gor h Gospodu v Micpo, rekoč: »Ta bo zagotovo usmrčen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Izraelovim otrokom je bilo žal zaradi Benjamina, njihovega brata in rekli so: »Ta dan je iz Izraela iztrebljen en rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Kako bomo storili zaradi žena za tiste, ki so ostali, glede na to, da smo pri Gospodu prisegli, da jim ne bomo dali izmed svojih hčera za žene?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Rekli so: »Kateri izmed Izraelovih rodov je, ki ni prišel v Micpo h Gospodu?« Glej, iz Jabéš Gileáda ni nihče prišel v tabor k zboru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Kajti ljudstvo je bilo prešteto in glej, tam ni bilo nobenega prebivalca iz Jabéš Gileáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Skupnost je tja poslala dvanajst tisoč mož izmed najhrabrejših in jim zapovedala, rekoč: »Pojdite in udarite prebivalce Jabéš Gileáda z ostrino meča, z ženskami in otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'To je stvar, ki jo boste storili: ›Popolnoma boste uničili vsakega moškega in vsako žensko, ki je ležala z moškim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Med prebivalci Jabéš Gileáda so našli štiristo mladih devic, ki nobenega moškega niso spoznale z ležanjem s katerimkoli moškim. Privedli so jih v tabor do Šila, ki je v kánaanski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Celotna skupnost je poslala nekatere, da govorijo Benjaminovim otrokom, ki so bili v Rimónovi skali in da miroljubno kličejo k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Ob tistem času je ponovno prišel Benjamin in izročili so jim žene, ki so jih žive rešili izmed žensk Jabéš Gileáda in vendar jim to ni zadoščalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Ljudstvo se je pokesalo zaradi Benjamina, zato ker je Gospod naredil vrzel v Izraelovih rodovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Potem so starešine skupnosti rekli: »Kako bomo storili glede žena za tiste, ki ostanejo, glede na to, da so ženske uničene iz Benjamina?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Rekli so: » Mora biti dediščina za tiste, ki pobegnejo iz Benjamina, da iz Izraela ne bo uničen rod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Vendar jim ne moremo dati žene izmed svojih hčera, kajti Izraelovi otroci so prisegli, rekoč: »Preklet bodi, kdor daje ženo Benjaminu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Potem so rekli: »Glej, tam je letno Gospodovo praznovanje v Šilu, na kraju, ki je na severni strani Betela, na vzhodni strani glavne ceste, ki gre gor od Betela do Sihema in na vzhodni strani Lebóne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Zato so Benjaminovim otrokom zapovedali, rekoč: »Pojdite in prežite v zasedi v vinogradih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Glejte in opazujte, če hčere iz Šila pridejo ven, da plešejo v plesih, potem pridite iz vinogradov in zgrabite vsak mož svojo ženo izmed hčera v Šilu in pojdite v Benjaminovo deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Zgodilo se bo, da ko pridejo k nam njihovi očetje ali njihovi bratje, da se pritožujejo, jim bomo rekli: »Bodite jim naklonjeni zaradi nas, ker v vojni nismo prihranili vsakemu možu svoje žene, kajti ob tistem času jim jih vi niste dali, tako ste sedaj krivi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Benjaminovi otroci so tako storili in si vzeli žene, glede na njihovo število izmed tistih, ki so plesale, ki so jih ujeli in odšli ter se vrnili v svojo dediščino in popravili mesta in prebivali v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Ob tem času so Izraelovi otroci odšli od tam, vsak mož k svojemu rodu in k svoji družini in odšli so od tam, vsak mož k svoji dediščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'V tistih dneh ni bilo kralja v Izraelu. Vsak mož je počel to, kar je bilo pravilno v njegovih lastnih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Pripetilo se je torej v dneh, ko so vladali sodniki, da je bila v deželi lakota. In nek mož iz Judovega Betlehema je odšel, da začasno prebiva v moábski deželi, on in njegova žena in njegova dva sinova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Ime moža je bilo Eliméleh, ime njegove žene pa Naomí in ime njegovih dveh sinov Mahlón in Kiljón, Efrátejci iz Judovega Betlehema. Prišli so v moábsko deželo in tam ostali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Naomín soprog Eliméleh je umrl in bila je zapuščena in njena dva sinova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'In vzela sta si ženi izmed moábskih žensk. Ime ene je bilo Orpa, ime druge pa je bilo Ruta. In tam so prebivali okoli deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Tudi Mahlón in Kiljón, oba izmed njiju, sta umrla. In ženska je bila zapuščena od svojih dveh sinov in od svojega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Potem je vstala s svojima snahama, da bi se lahko vrnila iz moábske dežele, kajti v moábski deželi je slišala, kako je Gospod obiskal svoje ljudstvo, ko jim je dajal kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Zato je odšla iz kraja, kjer je bila in njeni dve snahi z njo in odšle so na pot, da se vrnejo v Judovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Naomí je svojima dvema snahama rekla: »Pojdita, vrnita se vsaka k hiši svoje matere. Gospod naj prijazno postopa z vama, kakor sta vidve postopali z mrtvima in z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Gospod naj vama zagotovi, da bosta lahko našli počitek, vsaka izmed vaju, v hiši svojega soproga.« Potem ju je poljubila. Oni pa sta povzdignili svoj glas in zajokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Rekli sta ji: »Zagotovo se bova s teboj vrnili k tvojemu ljudstvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Naomí je rekla: »Obrnita se, moji hčeri. Čemu hočeta iti z menoj? Mar je v moji maternici vendar še kaj sinov, da bi bili vajini soprogi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Ponovno se obrnita, moji hčeri, pojdita svojo pot, kajti prestara sem, da bi imela soproga. Če bi rekla, imam upanje, če bi tudi nocoj imela soproga in bi mu tudi rodila sinove,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'bi se zadrževali zanju dokler ne bi odrasla? Bi ostali zanju, da ne bi imeli soprogov? Ne, moji hčeri, kajti to me zelo žalosti zaradi vaju, da se je Gospodova roka iztegnila zoper mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Povzdignili sta glas in ponovno zajokali. Orpa je poljubila svojo taščo, toda Ruta se je trdno pridružila k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Rekla je: »Glej, tvoja svakinja je odšla nazaj k svojemu ljudstvu in k svojim bogovom. Vrni se za svojo svakinjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruta pa je rekla: »Ne zahtevaj, da te zapustim ali da se vrnem od sledenja za teboj, kajti kamor greš ti, bom šla jaz. In kjer ti prenočuješ, bom prenočevala jaz. Tvoje ljudstvo bo moje ljudstvo in tvoj Bog [bo] moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kjer ti umreš, bom umrla jaz in tam bom pokopana. Gospod naj mi tako stori in še več, če bi karkoli razen smrti, ločilo tebe in mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Ko je videla, da je bila neomajnega mišljenja, da gre z njo, potem je opustila, da ji prigovarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Tako sta obe odšli, dokler nista prišli v Betlehem. Pripetilo se je, ko sta prišli v Betlehem, da je bilo vse mesto vznemirjeno glede njiju in rekli so: » Ali ni to Naomí?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Odgovorila jim je: »Ne imenujte me Naomí, imenujte me Mara, kajti Vsemogočni je zelo grenko postopal z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Odšla sem polna, Gospod pa me je ponovno privedel domov prazno. Zakaj me torej imenujete Naomí, glede na to, da je Gospod pričeval zoper mene in me je Vsemogočni prizadel?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Tako se je Naomí vrnila in z njo njena snaha Moábka Ruta, ki sta se vrnili iz moábske dežele. V Betlehem sta prišli ob začetku ječmenove žetve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Naomí je imela sorodnika svojega soproga, mogočnega človeka premoženja, iz Elimélehove družine. Njegovo ime je bilo Boaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Moábka Ruta je rekla Naomí: »Naj grem torej na polje in paberkujem žitno klasje za tistim, v čigar očeh bom našla milost.« In rekla ji je: »Pojdi, moja hči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Odšla je in prišla ter za žanjci paberkovala na polju in sreča se ji je posvetila na delu polja, ki je pripadal Boazu, ki je bil Elimélehov sorodnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Glej, Boaz je prišel iz Betlehema in rekel žanjcem: » Gospod naj bo z vami.« Odgovorili so mu: » Gospod te blagoslovi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Potem je Boaz rekel svojemu služabniku, ki je bil postavljen nad žanjce: »Čigava gospodična je to?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Služabnik, ki je bil postavljen nad žanjce, je odgovoril in rekel: »To je moábska gospodična, ki je prišla z Naomí nazaj iz moábske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Rekla je: ›Prosim vas, naj med snopi paberkujem za žanjci.‹ Tako je prišla in nadaljevala celo od jutra do sedaj, da se je le malo mudila v hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Potem je Boaz rekel Ruti: »Ali ne slišiš, moja hči? Ne pojdi paberkovat na drugo polje niti ne pojdi od tod, temveč ostani tukaj blizu mojih dekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Naj bodo tvoje oči na polju, ki ga žanjejo in pojdi za njimi. Mar nisem mladeniče zadolžil, da se te ne bodo dotaknili? In ko si žejna, pojdi k posodam in pij od tega, kar so mladeniči zajeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Potem je padla na svoj obraz in se priklonila do tal in mu rekla: »Zakaj sem našla milost v tvojih očeh, da si se zmenil zame, glede na to, da sem tujka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz je odgovoril in ji rekel: »V polnosti mi je bilo prikazano vse, kar si storila svoji tašči, odkar je tvoj soprog umrl in kako si zapustila svojega očeta, svojo mater in svojo rojstno deželo in si prišla k ljudstvu, ki ga poprej nisi poznala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Gospod naj ti povrne tvoje delo in polna nagrada naj ti bo dana od Gospoda, Izraelovega Boga, pod čigar peruti si prišla, da zaupaš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Potem je rekla: »Naj najdem naklonjenost v tvojem pogledu, moj gospod. Ker si me potolažil in ker si prijazno govoril s svojo pomočnico, čeprav nisem niti kakor ena izmed tvojih pomočnic.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Boaz ji je rekel: »Ob času kosila pridi sèm in jej od kruha in pomakaj svoj košček v kis.« Usedla se je poleg žanjcev in on ji je podal opraženo zrnje in jedla je in bila nasičena in še je ostalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Ko se je dvignila, da paberkuje, je Boaz svojim mladeničem zapovedal, rekoč: »Naj paberkuje celo med snopi in ne grajajte je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Naj prav tako namenoma zanjo pade nekaj prgišč in pustite jih, da jih bo lahko pobrala in ne oštejte je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Tako je na polju paberkovala celo do večera in otepla to, kar je nabrala in tega je bilo približno škaf ječmena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'In to je vzdignila ter odšla v mesto. Njena tašča je videla, kaj je nabrala in prinesla je in ji dala to, kar je shranila, potem ko je bila nasičena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Njena tašča ji je rekla: »Kje si danes paberkovala? Kje si delala? Blagoslovljen naj bo tisti, ki se je zmenil zate.« Svoji tašči je pokazala, s kom je delala in rekla: »Ime človeka, s katerim sem danes delala, je Boaz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Naomí je rekla svoji snahi: »Blagoslovljen naj bo od Gospoda on, ki ni opustil svoje prijaznosti do živih in do mrtvih.« Naomí ji je rekla: »Mož nama je bližnji sorodnik, eden izmed najinih najožjih sorodnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Moábka Ruta je rekla: »Rekel mi je tudi: ›Trdno se boš držala mojih mladeničev, dokler ne zaključijo vse moje žetve.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naomí je rekla svoji snahi Ruti: »Dobro je, moja hči, da greš ven z njegovimi deklami, da te ne srečajo na nobenem drugem polju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Tako se je trdno držala Boazovih dekel, da paberkuje do konca ječmenove žetve in pšenične žetve in prebivala je s svojo taščo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Potem ji je njena tašča Naomí rekla: »Moja hči, mar ne bom iskala počitka zate, da bo lahko dobro s teboj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Torej ali ni Boaz iz našega sorodstva, s čigar deklami si bila? Glej on nocoj veja ječmen na mlatišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Umij se torej in se mazili in nase nadeni svoje oblačilo in pojdi dol do mlatišča. Toda ne daj se spoznati možu, dokler se ne bo najedel in napil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Zgodilo se bo, da ko se uleže, da si boš zapomnila prostor, kjer bo legel in vstopila boš in odkrila njegova stopala in se ulegla in on ti bo povedal kaj boš storila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Rekla ji je: »Vse, kar mi govoriš, bom storila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Odšla je dol k mlatišču in storila glede na vse, kar ji je njena tašča zaukazala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Ko je Boaz jedel in pil in je bilo njegovo srce veselo, je odšel, da se uleže pri koncu kupa žita in ona je po tiho prišla in odkrila njegova stopala in se ulegla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Pripetilo se je ob polnoči, da je bil mož prestrašen in se obrnil in glej, ženska leži pri njegovih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Rekel je: »Kdo si?« Odgovorila je: »Jaz sem Ruta, tvoja pomočnica. Razširi torej krajec svoje obleke nad svojo pomočnico, kajti ti si bližnji sorodnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Rekel je: »Blagoslovljena bodi od Gospoda, moja hči, kajti izkazala si več prijaznosti v zadnjem koncu kakor poprej v tem, da ne slediš za mladeniči, bodisi revnimi ali bogatimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Sedaj, moja hči, ne boj se. Storil ti bom vse, kar zahtevaš, kajti vse mesto mojega ljudstva ve, da si vrla ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Sedaj je to resnica, da sem tvoj bližnji sorodnik, vendar obstaja sorodnik, ki je bližji kakor jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Ostani to noč in zjutraj bo, da če ti bo on izpolnil delež sorodnika, dobro. Naj on stori sorodniški delež, toda če ti on ne bo storil sorodniškega deleža, potem ti bom jaz storil sorodniški delež, kakor živi Gospod. Lezi do jutra.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'In pri njegovih stopalih je ležala do jutra. Vstala je, preden je kdo lahko prepoznal drugega. Rekel je: »Naj se ne izve, da je na mlatišče prišla ženska.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Prav tako je rekel: »Prinesi zagrinjalo, ki ga imaš na sebi in ga drži.« Ko ga je držala, ji je odmeril šest meric ječmena in ga naložil nanjo in odšla je v mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Ko je prišla k svoji tašči, je ta rekla: »Kdo si, moja hči?« In povedala ji je vse, kar ji je storil mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Rekla ji je: »Dal mi je teh šest meric ječmena, kajti rekel mi je: ›Ne pojdi prazna k svoji tašči.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Potem ji je ona rekla: »Mirno sedi, moja hči, dokler ne izveš, kako se bo stvar obrnila, kajti mož ne bo počival, dokler danes ne dokonča te stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Potem je Boaz odšel k velikim vratom in se tam usedel in glej, sorodnik, o katerem je Boaz govoril, je prišel mimo, kateremu je rekel: »Hej, ti oné! Kreni sem in sedi tukaj.« In ta je krenil tja ter se usedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Vzel je deset mož izmed starešin mesta ter rekel: »Sedite tukaj.« In oni so se usedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Sorodniku je rekel: »Naomí, ki je ponovno prišla iz moábske dežele, prodaja posest dežele, ki je bila od najinega brata Eliméleha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'in mislil sem, da ti oznanim, rekoč: ›Kupi to pred prebivalci in pred starešinami mojega ljudstva. Če hočeš to odkupiti, to odkupi, toda če ti tega nočeš odkupiti, potem mi povej, da bom lahko vedel, kajti poleg tebe ni nikogar, da to odkupi, jaz pa sem za teboj.‹« In ta je rekel: » To bom odkupil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Potem je Boaz rekel: »Tisti dan, ko kupiš polje iz Naomíne roke, moraš to kupiti tudi od Moábke Rute, žene umrlega, da obudiš ime mrtvega na njegovi dediščini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Sorodnik je rekel: » Tega ne morem odkupiti zase, da ne bi oškodoval svoje lastne dediščine. Ti odkupi mojo pravico k sebi, kajti jaz tega ne morem odkupiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Torej to je bil običaj v prejšnjem času v Izraelu, glede odkupitve in glede zamenjave, za potrditev vseh stvari. Človek je sezul svoj čevelj in tega dal svojemu bližnjemu in to je bilo pričevanje v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Zato je sorodnik Boazu rekel: » To si kupi zase.« Tako je sezul svoj čevelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Boaz je rekel starešinam in vsemu ljudstvu: »Vi ste priče ta dan, da sem kupil vse, kar je bilo Elimélehovo in vse, kar je bilo Mahlónovo in Kiljónovo iz Naomíne roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Poleg tega sem kupil Moábko Ruto, Mahlónovo ženo, da postane moja žena, da obudim ime mrtvega na njegovi dediščini, da ime mrtvega ne bo iztrebljeno izmed njegovih bratov in od velikih vrat tega kraja. Vi ste priče ta dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Vse ljudstvo, ki je bilo v velikih vratih, in starešine, so rekli: » Mi smo priče. Gospod naj naredi žensko, ki je prišla v tvojo hišo, kakor Rahelo in kakor Lejo, ki sta zgradili Izraelovo hišo. Ti pa delaj plemenito v Efráti in bodi slaven v Betlehemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Tvoja hiša naj bo podobna Parecovi hiši, katerega je Tamara rodila Judu, od semena, ki ti ga bo Gospod dal od te mlade ženske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Tako je Boaz vzel Ruto in bila je njegova žena in ko je šel noter k njej, ji je Gospod dal spočetje in rodila je sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Ženske so rekle Naomí: »Blagoslovljen bodi Gospod, ki te ta dan ni pustil brez sorodnika, da bo njegovo ime lahko slavno v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'On ti bo obnovitelj tvojega življenja in hranitelj tvoje starosti, kajti rodila ga je tvoja snaha, ki te ima rada, ki ti je boljša kakor sedem sinov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Naomí je vzela otroka in ga položila v svoje naročje in mu postala pestunja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Ženske, njene sosede, so mu dale ime, rekoč: »Naomí je rojen sin« in njegovo ime so imenovale Obéd. On je oče Davidovega očeta Jeseja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Torej to so Parecovi rodovi: Parec je zaplodil Hecróna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hecrón je zaplodil Rama, Ram je zaplodil Aminadába,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadáb je zaplodil Nahšóna, Nahšón je zaplodil Salmóna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmón je zaplodil Boaza, Boaz je zaplodil Obéda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obéd je zaplodil Jeseja in Jese je zaplodil Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Torej tam je bil nek mož iz Ramatájim Cofíma, z gore Efrájim in njegovo ime je bilo Elkaná, sin Jeroháma, sinú Elihúja, sinú Tohuja, sinú Cufa, Efrátejec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Ta je imel dve ženi. Ime ene je bilo Ana in ime druge Penína. Penína je imela otroke, toda Ana ni imela otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Ta mož je vsako leto šel gor iz svojega mesta, da obožuje in žrtvuje Gospodu nad bojevniki v Šilu. In dva Élijeva sinova, Hofní in Pinhás, Gospodova duhovnika, sta bila tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Ko je bil čas, da Elkaná daruje, je dal deleže svoji ženi Peníni in vsem njenim sinovom in njenim hčeram,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'toda Ani je dal vreden delež, kajti Ano je ljubil. Toda Gospod je zaprl njeno maternico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Njena nasprotnica jo je boleče dražila, da bi jo razburila, ker je Gospod zaprl njeno maternico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Ko je tako delala leto za letom, ko je šla gor do Gospodove hiše, jo je tako razdražila; zato je jokala in ni jedla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Potem ji je njen soprog Elkaná rekel: »Ana, zakaj jokaš? Zakaj ne ješ? Zakaj je tvoje srce užaloščeno? Ali ti nisem boljši kakor deset sinov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Tako je Ana vstala, potem ko so v Šilu pojedli in popili. Torej duhovnik Éli je sedel na sedežu pri podboju Gospodovega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Ona pa je bila v grenkobi duše in molila h Gospodu in bridko jokala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Zaobljubila je zaobljubo in rekla: »Oh Gospod nad bojevniki, če zares hočeš pogledati na stisko svoje pomočnice in se me spomniš in ne pozabiš svoje pomočnice, temveč hočeš svoji pomočnici dati fantka, potem ga bom izročila Gospodu [za] vse dni njegovega življenja in britev ne bo prišla na njegovo glavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Pripetilo se je, ko je nadaljevala moleč pred Gospodom, da je Éli opazil njena usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Torej Ana, ona je govorila v svojem srcu, premikale pa so se samo njene ustnice, toda njenega glasu ni bilo slišati. Zato je Éli mislil, da je bila pijana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Éli ji je rekel: »Doklej boš pijana? Odloži svoje vino od sebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Ana je odgovorila in rekla: »Ne, moj gospod, jaz sem ženska žalostnega duha. Niti nisem pila vina niti močne pijače, temveč sem svojo dušo izlila pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, '§ Svoje pomočnice ne štej za Beliálovo hčer, kajti iz obilja svoje pritožbe in žalosti sem doslej govorila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Potem je Éli odgovoril in rekel: »Pojdi v miru in Izraelov Bog ti zagotovi prošnjo, ki si jo prosila od njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Rekla je: »Naj tvoja pomočnica najde milost v tvojem pogledu.« Tako je ženska odšla svojo pot in jedla in njeno obličje ni bilo več žalostno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Vstali so zgodaj zjutraj in oboževali pred Gospodom in se vrnili in prišli k svoji hiši v Ramo. Elkaná je spoznal svojo ženo Ano in Gospod se jo je spomnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Zato se je pripetilo, ko je prišel čas, potem ko je Ana spočela, da je rodila sina in njegovo ime je imenovala Samuel, rekoč: »Ker sem ga prosila od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Mož Elkaná in vsa njegova hiša, so odšli gor, da darujejo Gospodu letno klavno daritev in svojo zaobljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Toda Ana ni odšla gor, kajti svojemu soprogu je rekla: » Ne bom šla gor, dokler ne bo otrok odstavljen in tedaj ga bom privedla, da se prikaže pred Gospodom in tam ostane za vedno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Njen soprog Elkaná ji je rekel: »Stôri, kar se ti zdi dobro. Ostani, dokler ga ne odstaviš. Samo Gospod [naj] uveljavi svojo besedo.« Tako je ženska ostala in dojila svojega sina, dokler ga ni odstavila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Ko ga je odstavila, ga je s seboj vzela gor, s tremi bikci, enim škafom moke in mehom vina ter ga privedla v Gospodovo hišo v Šilo. Otrok pa je bil mlad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Usmrtili so bikca in otroka privedli k Éliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Rekla je: »Oh moj gospod, kakor živi tvoja duša, moj gospod, jaz sem ženska, ki je stala tukaj pri tebi, moleč h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Za tega otroka sem molila in Gospod mi je izpolnil prošnjo, ki sem jo prosila od njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'zato sem ga tudi posodila Gospodu. Kakor dolgo živi, bo posojen Gospodu.« In tam je oboževal Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Ana je molila in rekla: »Moje srce se razveseljuje v Gospodu, moj rog je povišan v Gospodu. Moja usta so povečana nad mojimi sovražniki, ker se veselim v tvoji rešitvi duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nihče ni svet kakor Gospod, kajti nikogar ni poleg tebe. Niti ni nobene skale, podobne našemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne govorite več tako silno ponosno, naj aroganca ne pride iz vaših ust, kajti Gospod je Bog spoznanja in pri njem so tehtana dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Loki mogočnih mož so zlomljeni in tisti, ki so se spotaknili, so opasani z močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Tisti, ki so bili siti, so se dali v najem zaradi kruha; tisti, ki so bili lačni, so oslabeli, tako, da je jalova rodila sedmero in tista, ki ima mnogo otrok, je postala slabotna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Gospod ubija in oživlja. Privede dol do groba in privede gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Gospod dela revne in dela bogate, ponižuje in povzdiguje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Revnega vzdiguje iz prahu in berača povzdiguje iz gnojišča, da ju posadi med prince in jima stori, da podedujeta prestol slave, kajti stebri zemlje so Gospodovi in nanje je postavil zemeljski [krog].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Varoval bo stopala svojih svetih in zlobni bodo tiho v temi, kajti noben človek ne bo prevladal z močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Gospodovi nasprotniki bodo zlomljeni na koščke. Iz nebes bo zagrmel nad njimi. Gospod bo sodil konce zemlje; moč bo dal svojemu kralju in povišal rog svojega maziljenca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elkaná je odšel v Ramo, k svoji hiši. Otrok pa je služil Gospodu pred duhovnikom Élijem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Torej Élijeva sinova sta bila Beliálova sinova; onadva nista poznala Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'In običaj duhovnikov z ljudstvom je bil, da ko je katerikoli mož daroval klavno daritev, je prišel duhovnikov služabnik, medtem ko je meso vrelo, s kavljem za meso, s tremi zobmi, v svoji roki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'in to zabodel v ponev ali kotliček ali kotel ali lonec; vse, kar so kavlji za meso prinesli gor, je duhovnik vzel zase. Tako sta počela v Šilu vsem Izraelcem, ki so prihajali tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Tudi preden so sežgali tolščo, je prišel duhovnikov služabnik in rekel možu, ki je daroval: »Izroči meso za pečenje duhovniku, kajti od tebe ne bo imel kuhanega mesa, temveč surovega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Če pa bi mu katerikoli moški rekel: »Naj ne izpustijo, da sedaj zažgejo tolščo, potem pa vzemi, kolikor si želi tvoja duša;« Potem bi mu odgovoril: » Ne, temveč mi boš to dal sedaj. Če pa ne, bom to vzel s silo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Zato je bil greh mladeničev zelo velik pred Gospodom, kajti moža sta prezirala Gospodovo daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Toda Samuel je služil pred Gospodom, ko je bil še otrok, opasan z lanenim efódom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Poleg tega mu je mati iz leta v leto izdelala majhen plašč in ga prinesla k njemu, ko je prišla gor s svojim soprogom, da daruje letno klavno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Éli je blagoslovil Elkaná in njegovo ženo ter rekel: » Gospod ti daj seme od te ženske, zaradi posojila, ki je posojen Gospodu.« In odšli so na svoj dom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Gospod je obiskal Ano, tako da je spočela in rodila [še] tri sinove in dve hčeri. Otrok Samuel pa je rasel pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Torej Éli je bil zelo star in slišal vse, kar sta njegova sinova počela vsemu Izraelu in kako sta ležala z ženskami, ki so se zbirale pri vratih šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Rekel jima je: »Zakaj počneta takšne stvari? Kajti od vsega ljudstva slišim o vajinih zlih postopanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne, moja sinova, kajti to ni dober glas, ki ga slišim. Vidva povzročata Gospodovemu ljudstvu, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Če en mož greši zoper drugega, ga bo sodil sodnik, toda če mož greši zoper Gospoda, kdo bo posredoval zanj.« Vendar nista prisluhnila glasu svojega očeta, ker ju je Gospod hotel ubiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Otrok Samuel pa je rasel in bil je v naklonjenosti tako z Gospodom kakor tudi z ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'K Éliju je prišel Božji mož ter mu rekel: »Tako govori Gospod: ›Ali sem se očitno prikazal hiši tvojega očeta, ko so bili v Egiptu, v faraonovi hiši?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'In ali sem ga izbral izmed vseh Izraelovih rodov, da bo moj duhovnik, da daruje na mojem oltarju, da zažiga kadilo, da nosi efód pred menoj? In ali sem dal hiši tvojega očeta vse daritve, narejene z ognjem, Izraelovih otrok?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Zakaj brcate ob mojo klavno daritev in ob mojo daritev, ki sem jo zapovedal v svojem prebivališču in svoja sinova bolj častiš kakor mene, da ste se odebelili z glavnimi izmed vseh daritev Izraela, mojega ljudstva?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Zato govori Gospod, Izraelov Bog: ›Zares sem rekel, da naj bi tvoja hiša in hiša tvojega očeta hodili pred menoj na veke.‹ Toda sedaj govori Gospod: ›To bodi daleč od mene, kajti tiste, ki spoštujejo mene, bom jaz spoštoval in tisti, ki me prezirajo, bodo prezirani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Glej, pridejo dnevi, ko bom odsekal tvoj laket in laket hiše tvojega očeta, da v tvoji hiši ne bo starca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, '§ In ti boš videl sovražnika v mojem prebivališču v vsem bogastvu, ki ga bo Bog dal Izraelu, in v tvoji hiši na veke ne bo starca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Moški od tebe, ki ga ne bom odsekal izpred svojega oltarja, bo [preostal], da použije tvoje oči in da žalosti tvoje srce in ves narast tvoje hiše bo umrl v cvetu njihove starosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'To ti bo znamenje, ki bo prišlo nad tvoja dva sinova, na Hofníja in Pinhása; v enem dnevu bosta oba izmed njiju umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Jaz pa si bom dvignil zvestega duhovnika, ki bo delal glede na to, kar je v mojem srcu in v mojem umu in zgradil mu bom zanesljivo hišo; in ta bo hodil pred mojim maziljencem na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Zgodilo se bo, da bo vsak, kdor preostane v tvoji hiši, prišel in klečeplazil k njemu za košček srebra in grižljaj kruha in rekel bo: ›Postavi me, prosim te, v eno izmed duhovniških služb, da bom lahko jedel kos kruha.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Otrok Samuel pa je pred Élijem služil Gospodu. V tistih dneh je bila Gospodova beseda dragocena; ni bilo odprtega videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Pripetilo se je ob tistem času, ko se je Éli ulegel na svojem mestu in so njegove oči začenjale temneti, da ni mogel videti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Preden se je ugasnila Božja svetilka v Gospodovem templju, kjer je bila Božja skrinja in se je Samuel ulegel k spanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'je Gospod poklical Samuela in ta je odgovoril: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Stekel je k Éliju in rekel: »Tukaj sem, kajti klical si me.« Ta pa je rekel: »Nisem klical, ponovno se ulezi.« In odšel je in se ulegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Gospod je ponovno poklical: »Samuel.« Samuel je vstal in odšel k Éliju ter rekel: »Tukaj sem, kajti klical si me.« Ta je odgovoril: »Nisem klical, moj sin, ponovno se ulezi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Torej Samuel še ni poznal Gospoda niti mu Gospodova beseda še ni bila razodeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Gospod je ponovno, tretjič, poklical Samuela. Ta je vstal, šel k Éliju in rekel: »Tukaj sem, kajti klical si me.« In Éli je zaznal, da je otroka klical Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Zato je Éli rekel Samuelu: »Pojdi, ulezi se in zgodilo se bo, če te pokliče, da boš rekel: ›Govori, Gospod, kajti tvoj služabnik posluša.‹« Tako je Samuel odšel in se ulegel na svojem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Gospod je prišel in obstal ter poklical kakor ob drugih časih: »Samuel, Samuel.« Potem je Samuel odgovoril: »Govori; kajti tvoj služabnik posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Gospod je rekel Samuelu: »Glej, storil bom stvar v Izraelu, ob kateri bo v obeh ušesih vsakega, ki to sliši, zvenelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Na tisti dan bom zoper Élija izpolnil vse stvari, ki sem jih govoril glede njegove hiše. Ko pričnem, bom naredil tudi konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Kajti povedal sem mu, da bom na veke sodil njegovo hišo zaradi krivičnosti, ki jo on vé, ker sta se njegova sinova naredila nizkotna, on pa jima ni preprečil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Zato sem prisegel Élijevi hiši, da krivičnost Élijeve hiše na veke ne bo očiščena niti s klavno daritvijo niti z darovanjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel je ležal do jutra in odprl vrata Gospodove hiše. Samuel pa se je Éliju bal razodeti videnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Potem je Éli poklical Samuela in rekel: »Samuel, moj sin.« Ta je odgovoril: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Rekel je: »Kaj je stvar, ki ti jo je Gospod povedal? Prosim te, da mi je ne prikriješ. Bog naj ti tako stori in tudi več, če pred menoj skriješ katerokoli stvar od vseh stvari, ki ti jih je povedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel mu je povedal vsak delček in ničesar ni skril pred njim. On pa je rekel: »To je Gospod. Naj stori, kar se mu zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel je rasel in Gospod je bil z njim in nobene izmed njegovih besed ni pustil pasti na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Ves Izrael, od Dana, celo do Beeršébe, je vedel, da je bil Samuel utrjen, da bi bil Gospodov prerok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Gospod se je ponovno prikazoval v Šilu, kajti Gospod se je v Šilu razodeval Samuelu po Gospodovi besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Beseda od Samuela je prišla k vsemu Izraelu. Torej Izrael je odšel ven zoper Filistejce, da se bojujejo in utaborili so se poleg Eben Ezerja. Filistejci pa so se utaborili v Aféku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Filistejci so se razporedili zoper Izraela in ko so se pridružili bitki, je bil Izrael udarjen pred Filistejci in usmrtili so izmed vojske na polju okoli štiri tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Ko je ljudstvo prišlo v tabor, so starešine Izraela rekli: »Zakaj nas je Gospod danes udaril pred Filistejci? Skrinjo Gospodove zaveze prinesimo iz Šila k sebi, da ko ta pride med nas, nas ta lahko reši iz roke naših sovražnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Tako je ljudstvo poslalo v Šilo, da bi od tam lahko prinesli skrinjo zaveze Gospoda nad bojevniki, ki prebiva med kerubi, in Élijeva dva sinova, Hofní in Pinhás, sta bila tam s skrinjo Božje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Ko je v tabor prišla skrinja Gospodove zaveze, je ves Izrael vriskal z močnim vriskom, tako da je zemlja ponovno zadonela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Ko so Filistejci slišali hrup vriska, so rekli: »Kaj pomeni hrup tega močnega vriska v taboru Hebrejcev?« Razumeli so, da je v tabor prišla Gospodova skrinja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Filistejci so bili prestrašeni, kajti rekli so: »Bog je prišel v tabor.« Rekli so: »Gorje nam! Kajti poprej še ni bilo takšne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Gorje nam! Kdo nas bo rešil iz roke teh mogočnih Bogov? To so Bogovi, ki so v divjini udarili Egipčane z vsemi nadlogami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Bodite močni in obnašajte se kakor možje, oh vi Filistejci, da ne bomo služabniki Hebrejcem, kakor so bili oni vam. Obnašajte se kakor možje in se borite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Filistejci so se borili in Izrael je bil udarjen in zbežali so vsak mož v svoj šotor, in bil je zelo velik pokol, kajti v Izraelu je padlo trideset tisoč pešcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Božja skrinja je bila vzeta in Élijeva dva sinova, Hofní in Pinhás, sta bila ubita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Mož iz Benjamina pa je stekel iz vojske in še isti dan prišel v Šilo s pretrganimi oblačili in prstjo na svoji glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Ko je prišel, glej, je Éli sedel na sedežu in gledal ob poti, kajti njegovo srce je trepetalo za Božjo skrinjo. Ko je mož prišel v mesto in to povedal, je celotno mesto zavpilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Ko je Éli slišal hrup vpitja, je rekel: »Kaj pomeni zvok tega nemira?« Mož je v naglici prišel in povedal Éliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Torej Éli je bil star osemindevetdeset let in njegove oči so bile zatemnjene, da ni mogel videti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Mož je rekel Éliju: »Jaz sem tisti, ki je prišel iz vojske in danes sem pobegnil iz vojske.« On pa je rekel: »Kaj je tam storjeno, moj sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Poslanec je odgovoril in rekel: »Izrael je pobegnil pred Filistejci in tam je bil prav tako velik pokol med ljudstvom in tudi tvoja sinova, Hofní in Pinhás sta mrtva in Božja skrinja je vzeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Pripetilo se je, ko je omenil Božjo skrinjo, da je padel nazaj s stola ob strani velikih vrat in njegov vrat se je zlomil in je umrl, kajti bil je starec in težak. Izraelu je sodil štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Njegova snaha, Pinhásova soproga, je bila z otrokom, blizu časa poroda. Ko je slišala novice, da je bila Božja skrinja vzeta in da sta bila njen tast in njen mož mrtva, se je sklonila in bila v porodnih mukah, kajti njene bolečine so prišle nadnjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Okoli časa njene smrti so ji ženske, ki so stale ob njej, rekle: »Ne boj se, kajti rodila si sina.« Toda ona ni odgovorila niti se na to ni ozirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Otroka je imenovala Ikabód, rekoč: »Slava je odšla od Izraela,« ker je bila Božja skrinja vzeta in zaradi njenega tasta in njenega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Rekla je: »Slava je odšla od Izraela, kajti Božja skrinja je vzeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Filistejci so vzeli Božjo skrinjo in jo iz Eben Ezerja prinesli v Ašdód.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Ko so Filistejci vzeli Božjo skrinjo, so jo prinesli v Dagónovo hišo in jo postavili poleg Dagóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Ko so tisti iz Ašdóda naslednji dan zgodaj vstali, glej, Dagón je bil zvrnjen dol k zemlji, na svoj obraz, pred Gospodovo skrinjo. In prijeli so Dagóna in ga ponovno postavili na njegovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Ko so naslednji dan zgodaj zjutraj vstali, glej, Dagón je bil zvrnjen na svojem obrazu na tleh pred Gospodovo skrinjo, in Dagónova glava in obe dlani njegovih rok so bili odsekani na pragu. Samo Dagónov trup mu je preostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Zato niti Dagónovi duhovniki niti kdorkoli, ki pride v Dagónovo hišo, do današnjega dne, ne stopajo na Dagónov prag v Ašdódu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Toda Gospodova roka je bila težka nad tistimi iz Ašdóda in uničeval jih je in jih udaril s hemoroídi, torej Ašdód in njegova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Ko so možje iz Ašdóda videli, da je bilo tako, so rekli: »Skrinja Izraelovega Boga naj ne ostane z nami, kajti njegova roka je boleče nad nami in nad našim bogom Dagónom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Zato so poslali in k sebi zbrali vse filistejske kneze ter rekli: »Kaj naj storimo s skrinjo Izraelovega Boga?« Odgovorili so: »Naj bo skrinja Izraelovega Boga prenesena v Gat.« In tja so prenesli skrinjo Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'To je bilo tako, da potem, ko so jo odnesli, je bila Gospodova roka zoper mesto z zelo velikim uničenjem in udaril je može iz mesta, tako male, kakor velike in imeli so hemoroíde v svojih skritih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Zato so Božjo skrinjo poslali v Ekrón. Pripetilo se je, ko je Božja skrinja prišla v Ekrón, da so Ekrónci zavpili, rekoč: »K nam so privedli skrinjo Izraelovega Boga, da ubije nas in naše ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Tako so poslali in zbrali skupaj vse filistejske kneze in rekli: »Pošljite proč skrinjo Izraelovega Boga in naj ponovno gre na svoj kraj, da ne ubije nas in našega ljudstva,« kajti tam je bilo v vsem mestu smrtonosno uničenje. Božja roka je bila tam zelo težka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Možje, ki niso umrli, so bili udarjeni s hemoroídi in krik mesta je šel gor do neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Gospodova skrinja je bila v filistejski deželi sedem mesecev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Filistejci so dali poklicati duhovnike in vedeževalce, rekoč: »Kaj naj storimo z Gospodovo skrinjo? Povejte nam, s čim naj jo pošljemo na njen kraj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Rekli so: »Če odpošljete skrinjo Izraelovega Boga, je ne pošljite prazne; temveč mu na vsak način vrnite daritev za prestopek. Potem boste ozdravljeni in znano vam bo zakaj njegova roka ni odstranjena od vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Potem so rekli: »Kakšna naj bo daritev za prestopek, ki mu jo bomo vrnili?« Odgovorili so: »Pet zlatih hemoroídov in pet zlatih miši, glede na število filistejskih knezov, kajti ena nadloga je bila na vas vseh in na vaših gospodarjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Zato boste naredili podobe vaših tvorov in podobe vaših miši, ki uničujejo deželo in dali boste slavo Izraelovemu Bogu. Morda bo olajšal svojo roko iznad vas in iznad vaših bogov in iznad vaše dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Zakaj bi torej zakrknili svoja srca, kakor so Egipčani in faraon zakrknili svoja srca? Ko je izvrstno delal med njimi, ali niso pustili ljudstva iti in so odpotovali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Zdaj torej naredite nov voz in vzemite dve doječi kravi, na kateri jarem ni prišel in kravi privežite k vozu, njuna telička pa od njiju odvedite domov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'in vzemite Gospodovo skrinjo in jo položite na voz in položite dragocenosti iz zlata, ki mu jih vračate za daritev za prestopek, v skrinjico ob njeni strani in pošljite jo proč, da bo ta lahko odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Glejte, če gre ta gor po poti svojega lastnega območja v Bet Šemeš, potem nam je on storil to veliko zlo, toda če ne, potem bomo vedeli, da to ni njegova roka, ki nas je udarila; to je bilo naključje, ki se nam je pripetilo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Ljudje so tako storili. Vzeli so dve doječi kravi ter ju privezali k vozu, njuni teleti pa zaprli doma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Gospodovo skrinjo so položili na voz in skrinjico z mišmi iz zlata in podobami svojih hemoroídov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Kravi sta šli naravnost na pot Bet Šemeša in šli sta vzdolž glavne ceste, mukajoč, medtem ko sta hodili in nista se obračali vstran ne na desno roko ne na levo in filistejski knezi so šli za njima do meje Bet Šemeša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Tisti iz Bet Šemeša so v dolini želi svojo pšenično žetev in povzdignili so svoje oči in zagledali skrinjo in se razveselili, da jo vidijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Voz je prišel na polje Bétšémeščana Jošúa in obstal tam, kjer je bil velik kamen in nacepili so les od voza in kravi darovali v žgalno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Lévijevci so sneli Gospodovo skrinjo in skrinjico, ki je bila z njo, v kateri so bile dragocenosti iz zlata in ju položili na velik kamen in možje iz Bet Šemeša so isti dan Gospodu darovali žgalne daritve in žrtvovali klavne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Ko je pet filistejskih knezov to videlo, so se istega dne vrnili v Ekrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'To pa so zlati hemoroídi, ki so jih Filistejci vrnili Gospodu za daritev za prestopek: enega za Ašdód, enega za Gazo, enega za Aškelón, enega za Gat, enega za Ekrón;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'in zlate miši glede na število vseh filistejskih mest, pripadajočih petim knezom, tako utrjenih mest kakor podeželskih vasi, celo do velikega Abelovega kamna, na katerega so položili Gospodovo skrinjo; katerega kamen ostaja na polju Bétšémeščana Jošúa do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, '§ Udaril pa je može iz Bet Šemeša, ker so gledali v Gospodovo skrinjo, torej izmed ljudstva je udaril petdeset tisoč in sedemdeset mož in ljudstvo je žalovalo, ker je Gospod z velikim pokolom udaril mnoge izmed ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Možje iz Bet Šemeša so rekli: »Kdo je zmožen stati pred tem svetim Gospodom Bogom? In h komu naj gre gor od nas?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Poslali so poslance k prebivalcem Kirját Jearíma, rekoč: »Filistejci so ponovno privedli Gospodovo skrinjo. Pridite dol in jo prenesite gor k sebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Možje iz Kirját Jearíma so prišli in prenesli gor Gospodovo skrinjo in jo prinesli v Abinadábovo hišo na hribu in posvetili njegovega sina Eleazarja, da varuje Gospodovo skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Pripetilo se je, medtem ko je skrinja prebivala v Kirját Jearímu, da je bil čas dolg, kajti to je bilo dvajset let. Vsa Izraelova hiša je žalovala za Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Samuel je govoril vsej Izraelovi hiši, rekoč: »Če se z vsemi svojimi srci vrnete h Gospodu, potem izmed sebe odstranite tuje bogove in Astarto in pripravite svoja srca h Gospodu in samo njemu služite. On vas bo osvobodil iz roke Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Potem so Izraelovi otroci odstranili Báale in Astarto in služili samo Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Samuel je rekel: »Zberite ves Izrael v Micpi in jaz bom za vas molil h Gospodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Zbrali so se skupaj v Micpi, zajeli vodo in jo izlili pred Gospodom in se postili na ta dan in tam rekli: »Grešili smo zoper Gospoda.« In Samuel je sodil Izraelove otroke v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Ko so Filistejci slišali, da so se Izraelovi otroci zbrali skupaj k Micpi, so filistejski knezi odšli gor zoper Izrael. Ko so Izraelovi otroci to slišali, so se bali Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Izraelovi otroci so rekli Samuelu: »Ne odnehaj klicati h Gospodu, našemu Bogu za nas, da nas bo rešil iz roke Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel je vzel sesajoče jagnje in ga v celoti daroval v žgalno daritev Gospodu. Samuel je klical h Gospodu za Izrael in Gospod ga je slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Medtem ko je Samuel daroval žgalno daritev, so se približali Filistejci, da se bojujejo zoper Izrael, toda Gospod je na ta dan z velikim gromom zagrmel nad Filistejci in jih porazil in udarjeni so bili pred Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Možje iz Izraela so odšli ven iz Micpe in zasledovali Filistejce in jih udarjali, dokler niso prišli pod Bet Kar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Potem je Samuel vzel kamen in ga postavil med Micpo in Jašén in njegovo ime imenoval Eben Ezer, rekoč: »Doslej nam je Gospod pomagal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tako so bili Filistejci podjarmljeni in niso več prišli v območje Izraela in Gospodova roka je bila zoper Filistejce vse Samuelove dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Mesta, ki so jih Filistejci vzeli od Izraela, so bila povrnjena Izraelu, od Ekróna, celo do Gata in njihova območja je Izrael osvobodil iz rok Filistejcev. In bil je mir med Izraelom in Amoréjci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel je sodil Izraelu vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Iz leta v leto je odšel na obhod do Betela in Gilgála in Micpe in na vseh teh krajih sodil Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Njegova vrnitev je bila v Ramo, kajti tam je bila njegova hiša in tam je sodil Izraelu in tam je zgradil oltar Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Pripetilo se je, ko je bil Samuel star, da je svoja sinova postavil za sodnika nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Torej ime njegovega prvorojenca je bilo Joél in ime njegovega drugega Abíja. Bila sta sodnika v Beeršébi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Njegova sinova pa nista hodila po njegovih poteh, temveč sta se obrnila stran za dobičkom in jemala podkupnine in izkrivljala sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Potem so se vse starešine Izraela zbrali skupaj in prišli k Samuelu v Ramo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'in mu rekli: »Glej, star si in tvoja sinova ne hodita po tvojih poteh. Sedaj nam postavi kralja, da nas sodi, kakor [imajo] vsi narodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Toda stvar je razžalila Samuela, ko so rekli: »Daj nam kralja, da nas sodi.« Samuel je molil h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Gospod je rekel Samuelu: »Prisluhni glasu ljudstva v vsem, kar ti rečejo, kajti niso zavrnili tebe, temveč so zavrnili mene, da ne bi kraljeval nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Glede na vsa dela, ki so jih storili od dne, ko sem jih privedel gor iz Egipta, celo do tega dne, s čimer so zapustili mene in služili drugim bogovom, tako delajo tudi tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Zdaj torej prisluhni njihovemu glasu, vendar jih slovesno posvari in jim pokaži navade kralja, ki bo kraljeval nad njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Samuel je ljudstvu, ki je od njega zahtevalo kralja, povedal vse Gospodove besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Rekel je: »To bo navada kralja, ki bo kraljeval nad vami: ›Vzel bo vaše sinove in jih določil zase, za svoje bojne vozove in da bodo njegovi konjeniki in nekateri bodo tekli pred njegovimi bojnimi vozovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Določil si bo tisočnike in poveljnike nad petdesetimi in postavil jih bo, da orjejo njegovo zemljo, da žanjejo njegovo žetev, da izdelajo njegova bojna orodja in orodja njegovih bojnih vozov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Vzel bo vaše hčere, da bodo izdelovalke dišečin in da bodo kuharice in pekarice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Vzel bo vaša polja in vaše vinograde in vaše oljčne nasade, celó najboljše izmed njih in jih dal svojim služabnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Vzel bo desetino od vašega semena in od vaših vinogradov in dal svojim častnikom in svojim služabnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Vzel bo vaše služabnike, vaše dekle, vaše najčednejše mladeniče, vaše osle in jih postavil k svojemu delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Vzel bo desetino od vaših ovc in vi boste njegovi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Vpili boste na ta dan zaradi svojega kralja, ki si ga boste izbrali, Gospod pa vas na ta dan ne bo slišal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Kljub temu je ljudstvo odklonilo, da uboga Samuelov glas in rekli so: »Ne, temveč bomo imeli kralja nad seboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'da bomo tudi mi lahko podobni vsem narodom in da nam bo naš kralj lahko sodil in bo pred nami šel ven in bojeval naše boje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Samuel je slišal vse besede ljudstva in jih ponovil v Gospodova ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Gospod je Samuelu rekel: »Prisluhni njihovemu glasu in postavi jim kralja.« Samuel je rekel Izraelovim možem: »Pojdite vsak mož v svoje mesto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Torej tam je bil mož iz Benjamina, katerega ime je bilo Kiš, sin Abiéla, sinú Cerórja, sinú Behoráta, sinú Afíaha, Benjaminovec, mogočen človek moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Imel je sina, čigar ime je bilo Savel, izbranega in čednega mladeniča in med Izraelovimi otroki ni bilo čednejše osebe kakor on. Od njegovih ramen in navzgor je bil višji kakor katerikoli izmed ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Oslice Savlovega očeta Kiša so se izgubile. Kiš je rekel svojemu sinu Savlu: »Vzemi torej s seboj enega izmed služabnikov in vstani, pojdi iskat oslice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Prečkal je goro Efrájim in šel skozi deželo Šalíša, toda nista jih našla. Potem sta šla skozi deželo Šaalím in tam jih ni bilo. Šel je skozi deželo Benjaminovcev, toda nista jih našla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'In ko sta prišla do dežele Cuf, je Savel rekel svojemu služabniku, ki je bil z njim: »Pridi in se vrniva, da ne bi moj oče prenehal skrbeti za oslice in bi mislil na naju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Rekel mu je: »Glej torej, v tem mestu je Božji mož in ta je častitljiv mož. Vse, kar reče, se zagotovo zgodi. Pojdiva sedaj tja, morda nama on lahko pokaže pot, po kateri naj greva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Potem je Savel rekel svojemu služabniku: »Toda glej, če greva, kaj bova prinesla možu? Kajti kruh v najinih posodah je pošel in ni darila, da bi ga prinesla Božjemu možu. Kaj imava?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Služabnik je ponovno odgovoril Savlu in rekel: »Glej, tukaj pri roki imam četrtinko šekla srebra. To bom dal Božjemu možu, da nama pove najino pot.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Poprej je v Izraelu mož, ko je šel, da poizveduje od Boga, govoril tako: »Pridite in pojdimo k vidcu,« kajti kdor je sedaj imenovan prerok, je bil poprej imenovan videc.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Potem je Savel rekel svojemu služabniku: »Dobro rečeno. Pridi, pojdiva.« Tako sta šla v mesto, kjer je bil Božji mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'In ko sta šla gor, po hribu do mesta, sta našla mladenke, ki so prihajale ven, da zajamejo vodo in rekla sta jim: »Je tukaj videc?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Odgovorile so jima in rekle: »Je, glejta, pred vama je. Sedaj pohitita, kajti danes je prišel v mesto, kajti danes je klavna daritev ljudstva na visokem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Takoj ko prideta v mesto, ga bosta nemudoma našla, preden gre gor na visok kraj, da jé, kajti ljudstvo ne bo jedlo, dokler on ne pride, ker on blagoslovi klavno daritev in potem tisti, ki so povabljeni, jedo. Sedaj torej pojdita gor, kajti približno ta čas ga bosta našla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Šla sta gor v mesto in ko sta prišla v mesto, glej, je Samuel prihajal ven proti njima, da bi šel gor na visok kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Torej Gospod je Samuelu na uho povedal, dan poprej, preden je Savel prišel, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '»Jutri okrog tega časa ti bom poslal moža iz Benjaminove dežele in ti ga boš mazilil, da bo poveljnik nad mojim ljudstvom Izraelom, da bo lahko rešil moje ljudstvo iz roke Filistejcev, kajti jaz sem pogledal na svoje ljudstvo, ker je njihov krik prišel k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Ko je Samuel zagledal Savla, mu je Gospod rekel: »Glej mož, o katerem sem ti govoril! Ta isti bo kraljeval nad mojim ljudstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Potem se je Savel približal k Samuelu v velikih vratih in rekel: »Povej mi, prosim te, kje je vidčeva hiša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel je odgovoril Savlu in rekel: »Jaz sem videc. Pojdi gor pred menoj na visok kraj, kajti danes boš jedel z menoj, jutri pa te bom pustil oditi in povedal ti bom vse, kar je v tvojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Glede oslic, ki so bile izgubljene pred tremi dnevi, ne naravnaj svojih misli nanje, kajti najdene so. Na kom je vse hrepenenje Izraela? Ali ni na tebi in na vsej hiši tvojega očeta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Savel je odgovoril in rekel: » Ali nisem Benjaminovec, od najmanjšega izmed Izraelovih rodov? In moja družina najmanjša izmed vseh družin Benjaminovega rodu? Zakaj mi potem tako govoriš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel je vzel Savla in njegovega služabnika ter ju privedel v dvorano in ju primoral sesti na najvišje mesto med tistimi, ki so bili povabljeni, katerih je bilo približno trideset oseb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Samuel je rekel kuharju: »Prinesi delež, ki sem ti ga dal, od katerega sem ti rekel: ›Postavi to poleg sebe.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kuhar je vzel pleče in tisto, kar je bilo na njem in to postavil pred Savla. Samuel je rekel: »Glej to, kar je preostalo! Postavi to predse in jej, kajti za ta čas je bilo prihranjeno zate, odkar sem rekel: ›Povabil sem ljudstvo.‹« Tako je Savel tisti dan jedel s Samuelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Ko sta prišla dol iz visokega kraja v mesto, se je Samuel s Savlom posvetoval na vrhu hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Zgodaj so vstali in pripetilo se je ob svitanju dneva, da je Samuel poklical Savla na vrhu hiše, rekoč: »Vstani, da te lahko odpošljem.« Savel je vstal in odšla sta ven, oba izmed njiju, on in Samuel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'In ko sta se spuščala dol, do konca mesta, je Samuel rekel Savlu: »Zapovej služabniku, da gre naprej pred nama (in ta je šel naprej), toda ti malce postoj, da ti lahko pokažem besedo od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Potem je Samuel vzel stekleničko olja in jo izlil na njegovo glavo ter ga poljubil in rekel: » Ali ni to zato, ker te je Gospod mazilil, da bi bil poveljnik nad njegovo dediščino?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Ko danes odideš od mene, potem boš našel dva moža ob Rahelinem mavzoleju, na meji Benjamina, ob Celcáhu; in rekla ti bosta: ›Oslice, ki si jih šel iskat, so najdene in glej, tvoj oče je zapustil skrb nad oslicami in se žalosti zaradi tebe, rekoč: ›Kaj naj storim za svojega sina?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Potem boš šel naprej od tam in prišel boš do ravnine Tabor in tam boš srečal tri može, ki gredo gor k Bogu v Betel. Eden bo nosil tri kozličke, drugi bo nosil tri hlebe kruha in drugi bo nosil vinski meh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Pozdravili te bodo in ti dali dva hleba kruha, ki ju boš sprejel iz njihovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potem boš prišel do Božjega hriba, kjer je garnizija Filistejcev in zgodilo se bo, ko prideš tja do mesta, da boš srečal skupino prerokov prihajati dol iz visokega kraja, s plunko, bobničem, piščaljo in harfo pred njimi, in oni bodo prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Gospodov Duh bo prišel nadte in prerokoval boš z njimi in spremenjen boš v drugega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Naj bo, ko pridejo k tebi ta znamenja, da storiš, kakor se ti ponuja priložnost, kajti Bog je s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Šel boš dol pred menoj v Gilgál, in glej, prišel bom dol k tebi, da darujem žgalne daritve in da žrtvujem žrtvovanje mirovnih daritev. Sedem dni boš čakal, dokler ne pridem k tebi in ti pokažem, kaj boš storil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Bilo je tako, da ko je obrnil hrbet, da bi odšel od Samuela, mu je Bog dal drugo srce in vsa ta znamenja so se zgodila tisti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Ko so prišli tja do hriba, glej, ga je srečala skupina prerokov in Božji Duh je prišel nadenj in prerokoval je med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Pripetilo se je, ko so vsi, ki so ga poznali od prej, videli, da je, glej, prerokoval med preroki, potem je ljudstvo reklo drug drugemu: »Kaj je to, kar je prišlo h Kiševemu sinu? Ali je tudi Savel med preroki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Nekdo iz istega kraja je odgovoril in rekel: »Toda kdo je njihov oče?« Zato je postal pregovor: »Ali je tudi Savel med preroki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Ko je nehal prerokovati, je prišel na visok kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Savlov stric je rekel njemu in njegovemu služabniku: »Kam sta odšla?« Rekel je: »Iskat oslice. Ko pa sva videla, da jih ni bilo nikjer, sva šla k Samuelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Savlov stric je rekel: »Povej mi, prosim te, kaj ti je Samuel rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Savel je svojemu stricu rekel: »Pojasnil nama je, da so bile oslice najdene.« Toda o zadevi kraljestva, o kateri je govoril Samuel, mu ni povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel je skupaj sklical ljudstvo h Gospodu v Micpo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'in Izraelovim otrokom rekel: »Tako govori Gospod, Izraelov Bog: ›Izraela sem privedel iz Egipta in vas osvobodil iz roke Egipčanov in iz roke vseh kraljestev in od teh, ki so vas zatirali,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'vi pa ste ta dan zavrnili svojega Boga, ki vas je sam rešil vseh vaših nasprotnikov in vaših stisk in ste mu rekli: › Ne, temveč nad nami postavi kralja.‹ Sedaj se torej predstavite pred Gospodom po vaših rodovih in po vaših tisočih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Ko je Samuel vsem Izraelovim rodovom velel, da se približajo, je bil izbran Benjaminov rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Ko je Benjaminovemu rodu velel, da pride bliže po svojih družinah, je bila izbrana Matríjeva družina in izbran je bil Kišev sin Savel. Ko pa so ga iskali, ga niso mogli najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Zato so naprej povpraševali od Gospoda, ali bi mož še moral priti tja. Gospod je odgovoril: »Glejte, skril se je med stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Stekli so in ga vzeli od tam. Ko je stal med ljudstvom, je bil višji kakor katerikoli izmed ljudstva, od njegovih ramen navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Samuel je vsemu ljudstvu rekel: »Vidite koga je Gospod izbral, da tu ni podobnega njemu izmed vsega ljudstva?« Vse ljudstvo je zavpilo in reklo: »Živel kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Potem je Samuel ljudstvu povedal o načinu kraljestva in to zapisal v knjigo ter jo položil pred Gospoda. In Samuel je vse ljudstvo poslal proč, vsakega k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Tudi Savel je odšel domov v Gíbeo in z njim je šla četa mož, čigar src se je Bog dotaknil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Toda Beliálovi otroci so rekli: »Kako nas bo ta človek rešil?« Prezirali so ga in mu niso prinesli daril. Toda on je ohranil svoj mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Potem je prišel gor Amónec Naháš in se utaboril zoper Jabéš Gileád. Vsi možje Jabéša so rekli Nahášu: »Skleni zavezo z nami in mi ti bomo služili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Amónec Naháš jim je odgovoril: »Pod tem pogojem bom sklenil zavezo z vami, da vam lahko iztaknem vsa vaša desna očesa in to položim za grajo nad ves Izrael.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Starešine iz Jabéša so mu rekli: »Daj nam sedem dni predaha, da lahko odpošljemo poslance v vse Izraelove pokrajine, in potem, če ne bo nobenega človeka, da nas reši, bomo prišli ven k tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Potem sta poslanca prišla v Savlovo Gíbeo in v ušesa ljudstva povedala novice in vse ljudstvo je povzdignilo svoje glasove ter zajokalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Glej, Savel je prišel za čredo iz polja in Savel je rekel: »Kaj pesti ljudstvo, da jokajo?« Povedali so mu novice od ljudi iz Jabéša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Božji Duh je prišel nad Savla, ko je slišal tiste novice in njegova jeza je bila silno vneta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Snel je jarem iz volov in ju razsekal na koščke in le-te poslal po vseh Izraelovih pokrajinah, po rokah poslancev, rekoč: »Kdorkoli ne pride naprej za Savlom in Samuelom, bo tako storjeno njegovim volom.« Gospodov strah je padel na ljudstvo in prišli so ven soglasno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Ko jih je preštel v Bezeku, je bilo Izraelovih otrok tristo tisoč in Judovih mož trideset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Poslancem, ki so prišli, so povedali: »Tako boste rekli možem iz Jabéš Gileáda: ›Jutri, ob času, ko sonce postane vroče, boste imeli pomoč.‹« Poslanci so prišli in to pokazali možem iz Jabéša in bili so veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Zato so možje iz Jabéša rekli: »Jutri bomo prišli ven k vam in z nami boste lahko storili vse, kar se vam zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Naslednjega dne je bilo to tako, da je Savel ljudstvo razvrstil v tri skupine in prišli so v sredo vojske ob jutranji straži in usmrtili Amónce do dnevne vročine. Pripetilo se je, da so bili tisti, ki so preostali, razkropljeni, tako da niti dva izmed njih nista ostala skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Ljudstvo je reklo Samuelu: »Kdo je tisti, ki je rekel: ›Ali bo Savel kraljeval nad nami?‹ Privedite može, da jih lahko usmrtimo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Savel je rekel: »Danes ne bo usmrčen noben mož, kajti danes je Gospod izvêdel rešitev duš v Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Potem je Samuel rekel ljudstvu: »Pridite in pojdimo v Gilgál in tam obnovimo kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Vse ljudstvo je odšlo v Gilgál in tam, v Gilgálu, so postavili Savla za kralja pred Gospodom in tam so žrtvovali žrtvovanje mirovnih daritev pred Gospodom in tam so se Savel in vsi Izraelovi možje silno veselili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel je rekel vsemu Izraelu: »Glejte, prisluhnil sem vašemu glasu v vsem, kar ste mi rekli in postavil sem kralja nad vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'In sedaj glejte, kralj hodi pred vami. Jaz pa sem starec in sivolas in glejte, moja sinova sta z vami. Hodil sem pred vami od svojega otroštva, do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Glejte, tukaj sem. Pričujte zoper mene pred Gospodom in pred njegovim maziljencem. Čigavega vola sem vzel? Ali čigavega osla sem vzel? Ali sem koga ogoljufal? Koga sem zatiral? Ali iz čigave roke sem sprejel kakršnokoli podkupnino, da bi mi s tem zaslepil oči? In povrnil vam bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Rekli so: »Nisi nas ogoljufal niti nas nisi zatiral niti nisi vzel karkoli iz roke kateregakoli moža.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Rekel jim je: » Gospod je priča zoper vas in njegov maziljenec je priča ta dan, da v moji roki niste našli ničesar.« Odgovorili so: » On je priča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel je ljudstvu rekel: » Gospod je ta, ki je določil Mojzesa in Arona in ki je vaše očete privedel gor iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Zdaj torej mirno stojte, da se bom lahko pravdal z vami pred Gospodom o vseh pravičnih dejanjih Gospoda, ki jih je storil vam in vašim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Ko je Jakob prišel v Egipt in so vaši očetje klicali h Gospodu, potem jim je Gospod poslal Mojzesa in Arona, ki sta vaše očete privedla ven iz Egipta in jim dala prebivati na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Ko pa so pozabili Gospoda, svojega Boga, jih je prodal v roko Siserája, poveljnika Hacórjeve vojske in v roko Filistejcev in v roko moábskega kralja in so se borili zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Klicali so h Gospodu in rekli: ›Grešili smo, ker smo zapustili Gospoda in smo služili Báalom in Astarti. Toda sedaj nas osvobodi iz roke naših sovražnikov in mi ti bomo služili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Gospod je poslal Jerubáala, Bedána, Jefteja in Samuela in vas osvobodil iz roke vaših sovražnikov na vsaki strani in vi ste varno prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Ko pa ste videli, da je proti vam prišel Naháš, kralj Amónovih otrok, ste mi rekli: ›Ne, temveč bo kralj kraljeval nad nami.‹ Ko je bil Gospod, vaš Bog, vaš kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Zdaj torej glejte kralja, ki ste ga izbrali in ki ste si ga želeli! In glejte, Gospod je postavil kralja nad vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Če se boste bali Gospoda in mu služili in ubogali njegov glas in se ne boste uprli zoper Gospodovo zapoved, potem boste tako vi kot vaš kralj, ki kraljuje nad vami, še naprej sledili Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Toda če ne boste ubogali glasu Gospoda, temveč se boste uprli zoper Gospodovo zapoved, potem bo Gospodova roka zoper vas, kakor je bila zoper vaše očete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Zdaj torej stojte in vidite to veliko stvar, ki jo bo Gospod storil pred vašimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Mar ni danes pšenična žetev? Klical bom h Gospodu in poslal bo grmenje in dež, da boste lahko zaznali in videli, da je vaša zlobnost velika, ki ste jo storili v Gospodovih očeh, v tem, da ste si zahtevali kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Tako je Samuel zaklical h Gospodu in Gospod je ta dan poslal grmenje in dež, in vse ljudstvo se je silno balo Gospoda in Samuela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Vse ljudstvo je reklo Samuelu: »Moli za svoje služabnike h Gospodu, svojemu Bogu, da ne umremo, kajti vsem svojim grehom smo dodali to zlo, da smo si zahtevali kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel je ljudstvu rekel: »Ne bojte se. Storili ste vso to zlobnost, vendar se ne obrnite stran od sledenja Gospodu, temveč z vsem svojim srcem služite Gospodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'in ne obrnite se stran, kajti potem bi šli za praznimi stvarmi, ki ne morejo koristiti niti osvoboditi, kajti prazne so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Kajti Gospod ne bo zapustil svojega ljudstva zaradi svojega veličastnega imena, ker je Gospodu ugajalo, da vas naredi za svoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Poleg tega, kar se mene tiče, Bog ne daj, da bi grešil zoper Gospoda v [tem], da bi prenehal moliti za vas, temveč vas bom učil dobro in pravilno pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Samo bojte se Gospoda in mu služite v resnici, z vsem svojim srcem, kajti preudarite kako velike stvari je storil za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Toda če boste še vedno počeli zlobno, boste použiti, tako vi kakor vaš kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Savel je kraljeval eno leto in ko je nad Izraelom kraljeval dve leti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'si je Savel izbral tri tisoč mož iz Izraela, od katerih jih je bilo dva tisoč s Savlom v Mihmášu in na gori Betel, tisoč pa jih je bilo z Jonatanom v Benjaminovi Gíbei, preostanek ljudstva pa je poslal vsakega moža k svojemu šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jonatan je udaril garnizijo Filistejcev, ki je bila v Gebi in Filistejci so slišali o tem. Savel pa je zatrobil na šofar po vsej deželi, rekoč: »Naj Hebrejci slišijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Ves Izrael je slišal govoriti, da je Savel udaril garnizijo Filistejcev in da je bil tudi Izrael v ogabnost Filistejcem. In ljudstvo je bilo sklicano skupaj za Savlom v Gilgál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Filistejci so se zbrali skupaj, da se bojujejo z Izraelom, trideset tisoč bojnih vozov, šest tisoč konjenikov in ljudstva v obilju, kakor je peska na morski obali. Prišli so gor in se utaborili v Mihmášu, vzhodno od Bet Avena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Ko so možje iz Izraela videli, da so bili v škripcu (kajti ljudje so bili zelo stiskani), potem so se ljudje skrili v votlinah, v goščavah, v skalah, na visokih krajih in v jamah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Nekateri izmed Hebrejcev so odšli preko Jordana k deželi Gada in Gileáda. Glede Savla, on je bil še vedno v Gilgálu in vse ljudstvo mu je trepetajoč sledilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Zadrževal se je sedem dni, glede na določeni čas, ki ga je Samuel določil. Toda Samuel ni prišel v Gilgál, ljudstvo pa je bilo razkropljeno od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Savel je rekel: »Prinesite sèm k meni žgalno daritev in mirovne daritve.« In daroval je žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Pripetilo se je, da takoj, ko je končal daritev žgalne daritve, glej, je prišel Samuel. Savel je odšel ven, da ga sreča, da bi ga lahko pozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel je rekel: »Kaj si storil?« Savel je rekel: »Ker sem videl, da je bilo ljudstvo razkropljeno proč od mene in da ti nisi prišel v določenih dneh in da so se Filistejci zbrali skupaj pri Mihmášu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'sem zato rekel: ›Filistejci bodo sedaj prišli nadme dol v Gilgál, jaz pa nisem naredil ponižne prošnje h Gospodu.‹ Zato sem se prisilil in daroval žgalno daritev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel je rekel Savlu: »Storil si nespametno. Nisi se držal zapovedi Gospoda, svojega Boga, ki ti jo je zapovedal, kajti sedaj bi Gospod na veke utrdil tvoje kraljestvo nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Toda sedaj tvoje kraljestvo ne bo trajalo. Gospod si je poiskal moža po svojem lastnem srcu in Gospod mu je zapovedal, da bi bil poveljnik nad njegovim ljudstvom, ker se ti nisi držal tega, kar ti je Gospod zapovedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Samuel je vstal in se iz Gilgála povzpel v Benjaminovo Gíbeo. Savel je preštel ljudstvo, ki je bilo prisotno z njim, približno šeststo mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Savel, njegov sin Jonatan in ljudstvo, ki je bilo prisotno z njima, je ostalo v Benjaminovi Gíbei, toda Filistejci so taborili v Mihmášu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Iz tabora Filistejcev so prišli plenilci v treh skupinah. Ena skupina se je obrnila k poti, ki vodi v Ofro, v deželo Šuál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Druga skupina se je obrnila k poti do Bet Horóna. [Še] druga skupina se je obrnila k poti meje, ki je obrnjena k dolini Cebojím, proti divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Torej po vsej Izraelovi deželi ni bilo najti kovača, kajti Filistejci so rekli: »Da si ne bi Hebrejci naredili mečev ali sulic,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'temveč so vsi Izraelci hodili dol k Filistejcem, da si nabrusijo vsak mož svoj nož pri plugu, svoje črtalo pluga, svojo sekiro in svojo motiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, '§ Vendar so imeli pilo za motike, za črtala plugov, za vile, za sekire in da naostrijo palice z bodico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Tako se je na dan bitke pripetilo, da ni bilo najti niti meča niti sulice v roki kateregakoli izmed ljudstva, ki so bili s Savlom in Jonatanom. Toda najti ju je bilo pri Savlu in njegovem sinu Jonatanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Garnizija Filistejcev je odšla ven k prehodu Mihmáša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Pripetilo se je torej na dan, ko je Savlov sin Jonatan rekel mladeniču, ki je nosil njegovo bojno opremo: »Pridi in pojdiva preko, k filistejski garniziji, ki je na drugi strani.« Toda ni povedal svojemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Savel je sedel na najbolj oddaljenem delu Gíbee, pod granatovcem, ki je v Migrónu in ljudstva, ki je bilo z njim, je bilo približno šeststo mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Ahíja, sin Ahitúba, Ikabódov brat, sinú Pinhása, sinú Élija, Gospodovega duhovnika v Šilu, je nosil efód. Ljudstvo pa ni vedelo, da je Jonatan odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Med prehodi, ob katerih je Jonatan iskal, da bi šel preko k filistejski garniziji, je bila ostra skala na eni strani in ostra skala na drugi strani. Ime ene je bilo Bocéc, ime druge pa Sene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Sprednji del ene je bil obrnjen proti severu, nasproti Mihmášu in druge proti jugu, nasproti Gíbei.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jonatan je rekel mladeniču, ki je nosil njegovo bojno opremo: »Pridi in pojdiva preko, h garniziji teh neobrezancev. Morda bo Gospod delal za naju, kajti ni omejitve Gospodu, da reši po mnogih ali po peščici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Njegov nosilec bojne opreme mu je rekel: »Stori vse, kar je v tvojem srcu. Obrni se, glej, jaz sem s teboj glede na tvoje srce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Potem je Jonatan rekel: »Glej, šla bova preko, k tem možem in se jim bova odkrila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Če nama rečejo: ›Ostanita, dokler ne pridemo do vaju,‹ potem bova mirno stala na svojem kraju in ne bova šla gor k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Toda če rečejo tako: ›Pridita gor k nam,‹ potem bova šla gor, kajti Gospod jih je izročil v najino roko in to nama bo za znamenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Oba izmed njiju sta se odkrila garniziji Filistejcev. Filistejci so rekli: »Poglejte, Hebrejci prihajajo iz lukenj, kamor so se skrili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Možje iz garnizije so Jonatanu in njegovemu nosilcu bojne opreme odgovorili ter rekli: »Pridita gor k nam in pokazali vama bomo stvar.« Jonatan je rekel svojemu nosilcu bojne opreme: »Pridi gor za menoj, kajti Gospod jih je izročil v Izraelovo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonatan je plezal gor po svojih rokah in po svojih stopalih in njegov nosilec bojne opreme za njim in padali so pred Jonatanom. Njegov nosilec bojne opreme pa jih je pobijal za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Ta prvi pokol, ki sta ga naredila Jonatan in njegov nosilec bojne opreme, je zajel okrog dvajset mož, kakor bi bilo znotraj pol orala dežele, ki bi jo lahko preoral jarem volov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'V vojski na polju in med vsem ljudstvom je bilo trepetanje. Garnizija in plenilci, tudi oni so trepetali in zemlja se je tresla. Tako je bilo zelo veliko trepetanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Savlovi stražarji v Benjaminovi Gíbei so pogledali in glej, množica se je razblinila in nadaljevali so s podiranjem drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Potem je Savel rekel ljudstvu, ki je bilo z njim: »Preštejte torej in poglejte, kdo je odšel od nas.« Ko so prešteli, glej, Jonatan in njegov nosilec bojne opreme nista bila tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Savel je rekel Ahíju: »Prinesi sèm Božjo skrinjo.« Kajti Božja skrinja je bila ob tistem času z Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Pripetilo se je, medtem ko je Savel govoril z duhovnikom, da se je hrup, ki je bil v vojski Filistejcev, nadaljeval in naraščal in Savel je rekel duhovniku: »Umakni svojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Savel ter vse ljudstvo, ki je bilo z njim, so se zbrali skupaj in prišli k bitki. Glej, meč vsakega moža je bil proti njegovemu tovarišu in tam je bila zelo velika zmeda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Pa tudi Hebrejci, ki so bili pred tem časom s Filistejci, ki so iz okoliške dežele odšli z njimi gor v tabor, celo ti so se prav tako obrnili, da bi bili z Izraelci, ki so bili s Savlom in Jonatanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Podobno so tudi vsi Izraelovi možje, ki so se skrili na gori Efrájim, ko so slišali, da so Filistejci zbežali, celo oni so sledili tik za njimi v bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Tako je Gospod tisti dan rešil Izraela. Bitka je prešla preko k Bet Avenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Izraelovi možje so bili ta dan užaloščeni, kajti Savel je ljudstvo zaprisegel, rekoč: »Preklet naj bo mož, ki poje kakršnokoli hrano do večera, da bom lahko maščevan na svojih sovražnikih.« Tako nihče izmed ljudstva ni pokusil nobene hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Vsi tisti iz dežele so prišli do gozda in tam je bil na tleh med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Ko je ljudstvo prišlo v gozd, glej, je kapljal med, toda noben mož ni iztegnil svoje roke k svojim ustom, kajti ljudstvo se je balo prisege.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Toda Jonatan ni slišal, ko je njegov oče ljudstvo obremenil s prisego. Zato je iztegnil konec palice, ki je bila v njegovi roki in jo omočil v satovju in svojo roko nesel k ustom in njegove oči so bile razsvetljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Potem je odgovoril eden izmed ljudstva in rekel: »Tvoj oče je s prisego strogo obremenil ljudstvo, rekoč: ›Preklet bodi človek, ki danes poje kakršnokoli hrano.‹« In ljudstvo je bilo slabotno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Potem je Jonatan rekel: »Moj oče je vznemiril deželo. Poglej, prosim te, kako so bile moje oči razsvetljene, ker sem okusil malo od tega medu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Kako mnogo bolj, če bi morda ljudstvo danes prosto jedlo od plena svojih sovražnikov, ki so ga našli? Kajti ali ne bi bil sedaj veliko večji pokol med Filistejci?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Ta dan so udarili Filistejce od Mihmáša do Ajalóna, ljudstvo pa je bilo zelo slabotno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'In ljudstvo se je vrglo na plen in vzelo ovce, vole in teleta in zaklali so jih na tleh. Ljudstvo jih je jedlo s krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Potem so povedali Savlu, rekoč: »Glej, ljudstvo greši zoper Gospoda v tem, da jedo s krvjo.« Rekel je: »Pregrešili ste se. Zavalite k meni ta dan velik kamen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Savel je rekel: »Razpršite se med ljudstvo in jim recite: ›Privedite mi sèm vsak človek svojega vola in vsak človek svojo ovco in zakoljite jih tukaj in jejte in ne grešite zoper Gospoda, v tem, da bi jedli s krvjo.‹« Vse ljudstvo je to noč privedlo, vsak človek svojega vola s seboj in so jih tam zaklali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Savel je zgradil oltar Gospodu. Ta isti je bil prvi oltar, ki ga je zgradil Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Savel je rekel: »Pojdimo ponoči dol za Filistejci in jih plenimo do jutranje svetlobe in ne pustimo nobenega moža od njih.« Rekli so: »Stôri, karkoli se ti zdi dobro.« Potem je rekel duhovniku: »Približajmo se sèm k Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Savel je vprašal za nasvet od Boga: »Ali naj grem dol za Filistejci? Ali jih boš izročil v Izraelovo roko?« Toda tisti dan mu ni odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Savel je rekel: »Približajte se sèm, vsi vodje ljudstva in vedite in poglejte, v čem je bil ta greh ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Kajti kakor živi Gospod, ki rešuje Izrael, čeprav bi bil ta na mojem sinu Jonatanu, bo on zagotovo umrl.« Toda tam ni bilo moža izmed ljudstva, da bi mu odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Potem je vsemu Izraelu rekel: »Vi bodite na eni strani, jaz in moj sin Jonatan pa bova na drugi strani.« Ljudstvo je Savlu reklo: »Stori, kar se ti zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Zato je Savel rekel Gospodu, Izraelovemu Bogu: »Daj popoln žreb.« Zajeta sta bila Savel in Jonatan, toda ljudstvo je bilo izločeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Savel je rekel: »Vrzite žrebe med menoj in mojim sinom Jonatanom.« In izbran je bil Jonatan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Potem je Savel rekel Jonatanu: »Povej mi kaj si storil.« Jonatan mu je povedal in rekel: »Samo pokusil sem malo medu s koncem palice, ki je bila v moji roki in glej, moram umreti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Savel je odgovoril: »Bog stori tako in še več, kajti zagotovo boš umrl, Jonatan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Ljudstvo pa je reklo Savlu: »Ali naj Jonatan umre, ki je izvršil to veliko rešitev duš v Izraelu? Bog ne daj. Kakor Gospod živi, ne bo niti en las iz njegove glave padel na tla, kajti ta dan je delal z Bogom.« Tako je ljudstvo rešilo Jonatana, da ni umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Potem je Savel odšel gor od sledenja Filistejcem in Filistejci so odšli k svojemu lastnemu kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Tako je Savel vzel kraljestvo nad Izraelom in se boril zoper vse svoje sovražnike na vsaki strani, zoper Moáb, zoper Amónove otroke, zoper Edóm, zoper kralje Cobe in zoper Filistejce in h komurkoli se je obrnil, jim je povzročal skrbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Zbral je vojsko, udaril Amalečane in Izraela osvobodil iz rok tistih, ki so jih plenili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Torej Savlovi sinovi so bili Jonatan, Jišví in Malkišúa. Imena njegovih dveh hčera sta bili: ime prvorojene Merába in ime mlajše Mihála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Ime Savlove žene je bilo Ahinóam, Ahimáacova hči. Ime poveljnika njegove vojske je bilo Abnêr, sin Savlovega strica Nera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, '§ Kiš je bil Savlov oče in Abnêrjev oče Ner je bil Abiélov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'In tam je bila silna vojna zoper Filistejce vse Savlove dni in ko je Savel zagledal kateregakoli močnega moža ali kateregakoli hrabrega moža, ga je vzel k sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel je tudi rekel Savlu: » Gospod me je poslal, da te mazilim, da bi bil kralj nad njegovim ljudstvom, nad Izraelom. Sedaj torej prisluhni glasu Gospodovih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tako govori Gospod nad bojevniki: ›Spomnim se tega, kar je Amálek storil Izraelu, kako je prežal nanj na poti, ko je prišel gor iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Sedaj pojdi in udari Amáleka in popolnoma uniči vse, kar imajo in ne prizanesi jim, temveč ubij tako moškega kakor žensko, otroka in dojenčka, vola in ovco, kamelo in osla.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Savel je ljudstvo zbral skupaj in jih preštel v Telaímu, dvesto tisoč pešcev in deset tisoč mož iz Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Savel je prišel do mesta Amálečanov in prežal v dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Savel je Kenéjcem rekel: »Pojdite, odidite dol izmed Amálečanov, da vas ne bi uničil z njimi, kajti izkazali ste prijaznost vsem Izraelovim otrokom, ko so prišli gor iz Egipta.« Tako so Kenéjci odšli izmed Amalečanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Savel je udaril Amalečane od Havíle, dokler ne prideš do Šura, ki je nasproti Egiptu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Agága, kralja Amalečanov, je zajel živega in z ostrino meča popolnoma uničil vse ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Toda Savel in ljudstvo je prizaneslo Agágu in najboljšemu od ovc, od volov, od pitancev in jagnjet in vsega, kar je bilo dobro in niso jih želeli popolnoma uničiti. Toda vsako stvar, ki je bila ničvredna in zavrnjena, to so popolnoma uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Potem je prišla Gospodova beseda Samuelu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '»To me je pokesalo, da sem postavil Savla, da bi bil kralj, kajti obrnil se je nazaj od sledenja meni in ni izvršil mojih zapovedi.« To je užalostilo Samuela in ta je vso noč klical h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Ko je Samuel zgodaj vstal, da bi zjutraj srečal Savla, je bilo Samuelu povedano, rekoč: »Savel je prišel v Karmel in glej, postavil si je kraj in potem je šel naokrog, šel naprej in odšel dol do Gilgála.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Samuel je prišel k Savlu in Savel mu je rekel: »Blagoslovljen bodi od Gospoda. Izpolnil sem Gospodovo zapoved.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel pa je rekel: »Kaj potem pomeni to blejanje ovc v mojih ušesih in mukanje volov, ki ga slišim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Savel je rekel: »Privedli so jih od Amalečanov, kajti ljudstvo je prizaneslo najboljšim izmed ovc in izmed volov, da žrtvujejo Gospodu, tvojemu Bogu, preostalo pa smo popolnoma uničili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Potem je Samuel rekel Savlu: »Ostani in povedal ti bom kaj mi je to noč povedal Gospod.« In rekel mu je: »Povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel je rekel: »Ko si bil majhen v svojem lastnem pogledu, ali nisi bil narejen za poglavarja Izraelovim rodovom in te je Gospod mazilil za kralja nad Izraelom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Gospod te je poslal na pot in rekel: ›Pojdi in popolnoma uniči grešnike Amalečane in se bori proti njim, dokler ne bodo použiti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Zakaj potem nisi ubogal Gospodovega glasu, temveč si se vrgel na plen in storil zlo v Gospodovih očeh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Savel je rekel Samuelu: »Da, ubogal sem Gospodov glas in sem šel na pot, na katero me je poslal Gospod in privedel sem Agága, kralja Amalečanov in popolnoma sem uničil Amálečane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Toda ljudstvo je vzelo od plena, ovce in vole, glavne izmed stvari, ki naj bi bile popolnoma uničene, da žrtvujejo Gospodu, tvojemu Bogu v Gilgálu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel je rekel: »Ali ima Gospod tako veliko zadovoljstvo v žgalnih daritvah in klavnih daritvah, kot v ubogljivosti Gospodovemu glasu? Glej, ubogati je bolje kot klavna daritev in poslušati [bolje] kot tolšča ovnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Kajti upor je kakor greh čaranja in trmoglavost je kakor krivičnost in malikovanje. Ker si zavrnil Gospodovo besedo, je tudi on zavrnil tebe, da bi bil kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Savel je rekel Samuelu: »Grešil sem, kajti prekršil sem Gospodovo zapoved in tvoje besede, ker sem se bal ljudstva in ubogal njihov glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Zdaj torej, prosim te, odpusti moj greh in se ponovno obrni z menoj, da lahko obožujem Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel pa je rekel Savlu: »Ne bom se vrnil s teboj, kajti zavrnil si Gospodovo besedo in Gospod je zavrnil tebe, da bi bil kralj nad Izraelom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Medtem ko se je Samuel obrnil naokoli, da gre proč, je zgrabil krajec njegovega plašča in ga odtrgal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Samuel pa mu je rekel: » Gospod je ta dan odtrgal Izraelovo kraljestvo od tebe in ga izročil tvojemu bližnjemu, ki je boljši kakor ti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Tudi Močni Izraelov ne bo lagal niti se kesal, kajti on ni človek, da bi se kesal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Potem je rekel: »Grešil sem. Vendar me sedaj počasti, prosim te, pred starešinami mojega ljudstva in pred Izraelom in se ponovno obrni z menoj, da bom lahko oboževal Gospoda, tvojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Tako se je Samuel ponovno obrnil za Savlom, in Savel je oboževal Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Potem je Samuel rekel: »Privedite sèm k meni Agága, kralja Amalečanov.« Agág je prefinjeno prišel k njemu. In Agág je rekel: »Zagotovo je grenkoba smrti minila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel je rekel: »Kakor je tvoj meč naredil ženske brez otrok, tako bo tvoja mati brez otroka med ženskami.« In Samuel je Agága razsekal na koščke pred Gospodom v Gilgálu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potem je Samuel odšel v Ramo, Savel pa je odšel gor, do svoje hiše, v Savlovo Gíbeo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel ni več prišel, da bi videl Savla, do dneva svoje smrti, vendar je Samuel žaloval za Savlom. In Gospod se je pokesal, da je Savla postavil [za] kralja nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Gospod je rekel Samuelu: »Doklej boš žaloval za Savlom, glede na to, da sem ga zavrnil od kraljevanja nad Izraelom? Napolni svoj rog z oljem in pojdi, poslal te bom k Betlehemcu Jeseju, kajti med njegovimi sinovi sem si priskrbel kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel je rekel: »Kako lahko grem? Če Savel to sliši, me bo ubil.« Gospod je rekel: »Vzemi s seboj telico in reci: ›Prišel sem, da žrtvujem Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'H klavni daritvi pokliči Jeseja, jaz pa ti bom pokazal kaj boš storil in mazilil mi boš tistega, ki ti ga imenujem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel je storil to, kar je Gospod govoril in prišel v Betlehem. Starešine mesta pa so trepetali ob njegovem prihodu in rekli: »Ali prihajaš miroljubno?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Rekel je: »Miroljubno. Prišel sem, da darujem Gospodu. Posvetite se in pridite z menoj h klavni daritvi.« In Jeseja in njegove sinove je posvetil ter jih poklical k daritvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Pripetilo se je, ko so prišli, da je pogledal na Eliába in rekel: »Zagotovo je Gospodov maziljenec pred njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Toda Gospod je rekel Samuelu: »Ne glej na njegovo obličje ali na višino njegove postave, ker sem ga odklonil, kajti GOSPOD ne vidi, kakor vidi človek; kajti človek gleda na zunanji videz, toda Gospod gleda na srce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Potem je Jese poklical Abinadába in ga primoral, da gre pred Samuela. In ta je rekel: »Niti tega Gospod ni izbral.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Potem je Jese primoral Šamája, da gre mimo. Rekel je: »Niti Gospod ni izbral tega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Ponovno, Jese je primoral sedem svojih sinov, da gredo mimo pred Samuelom. Samuel je rekel Jeseju: » Gospod ni izbral teh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Samuel je rekel Jeseju: »Ali so tukaj vsi tvoji otroci?« Rekel je: »Ostaja še najmlajši in glej, on varuje ovce.« Samuel je rekel Jeseju: »Pošlji in privedi ga, kajti ne bomo sedli dol, dokler on ne pride sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Poslal je in ga privedel noter. Torej bil je rdečkast in hkrati lepega obličja in čeden na pogled. In Gospod je rekel: »Vstani, mazili ga, kajti to je on.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Potem je Samuel vzel rog olja in ga mazilil v sredi njegovih bratov. Gospodov Duh je prišel na Davida od tega dne dalje. Tako je Samuel vstal in odšel v Ramo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Vendar pa je Gospodov Duh odšel od Savla in zli duh od Gospoda ga je nadlegoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Savlovi služabniki so mu rekli: »Glej torej, nadleguje te zli duh od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Naj naš gospod sedaj zapove svojim služabnikom, ki so pred teboj, da poiščejo človeka, ki je spreten igralec na harfo. Zgodilo se bo, ko bo nad teboj zli duh od Boga, da bo igral s svojo roko, tebi pa bo dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Savel je svojim služabnikom rekel: »Priskrbite mi torej človeka, ki lahko dobro igra in ga privedite k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Potem je eden izmed služabnikov odgovoril in rekel: »Glej, videl sem sina Betlehemca Jeseja, ki je spreten v igranju, močan, hraber mož, bojevnik, razsoden v zadevah in ljubke osebnosti in Gospod je z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Zato je Savel poslal poslance k Jeseju in rekel: »Pošlji mi svojega sina Davida, ki je z ovcami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Jese je vzel osla, obloženega s kruhom, vinski meh, kozlička in jih po svojem sinu Davidu poslal k Savlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'David je prišel k Savlu in stal pred njim in on ga je silno vzljubil in postal je njegov nosilec bojne opreme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Savel je poslal k Jeseju, rekoč: »Pusti Davida, prosim te, stati pred menoj, kajti našel je naklonjenost v mojem pogledu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Pripetilo se je, ko je bil zli duh od Boga nad Savlom, da je David vzel harfo in igral s svojo roko. Tako je bil Savel osvežen in bilo mu je dobro in zli duh je odšel od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Torej Filistejci so zbrali skupaj svoje vojske za boj in zbrani so bili skupaj pri Sohóju, ki pripada Judu in se utaborili med Sohójem in Azéko, v Efes Damímu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Savel in Izraelovi možje so bili zbrani skupaj in se utaborili poleg doline Elá in se postrojili v boj zoper Filistejce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistejci so stali na gori na eni strani, Izrael pa je stal na gori na drugi strani in med njimi je bila dolina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Iz tabora Filistejcev je prišel šampion iz Gata, po imenu Goljat, katerega višina je bila šest komolcev in pedenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Na svoji glavi je imel čelado iz brona in oborožen je bil z verižnim plaščem. Teža plašča je bila pet tisoč šeklov brona');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Na svojih nogah je imel bronaste golenice in okrogel ščit iz brona med svojimi rameni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Palica njegove sulice je bila podobna tkalčevemu brunu in vrh njegove sulice je tehtal šeststo šeklov železa in nekdo, ki je nosil ščit, je šel pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Stal je in klical Izraelovim vojskam ter jim rekel: »Zakaj ste prišli ven, da se postrojite za boj? Mar nisem jaz Filistejec, vi pa Savlovi služabniki? Izberite zase moža in naj pride dol k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Če se je zmožen bojevati z menoj in me ubiti, potem bomo mi vaši služabniki, toda če prevladam zoper njega in ga ubijem, potem boste vi naši služabniki in nam služili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Filistejec je rekel: »Danes izzivam Izraelove vojske. Dajte mi človeka, da se lahko skupaj bojujeva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Ko so Savel in ves Izrael slišali te Filistejčeve besede, so bili zaprepadeni in silno prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Torej David je bil sin tega Efratejca iz Judovega Betlehema, katerega ime je bilo Jese. Ta je imel osem sinov. V Savlovih dneh je mož odšel med može za starca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Trije najstarejši Jesejevi sinovi so odšli in Savlu sledili v bitko. Imena njegovih treh sinov, ki so šli v bitko, so bila Eliáb, prvorojenec in poleg njega Abinadáb in tretji Šamá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David je bil najmlajši in trije starejši so sledili Savlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Toda David je šel in se vrnil od Savla, da pri Betlehemu pase ovce svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Filistejec se je približal zjutraj in zvečer in se nastavljal štirideset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Jese je svojemu sinu Davidu rekel: »Vzemi sedaj za svoje brate škaf tega praženega zrnja in teh deset hlebov ter steci v tabor k svojim bratom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'in teh deset sirov odnesi k poveljniku njihove tisočnije in poglej, kako se imajo tvoji bratje in vzemi njihovo jamstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Torej Savel in oni in vsi Izraelovi možje so bili v dolini Elá, boreč se s Filistejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'David je vstal zgodaj zjutraj in pustil ovce s čuvajem in vzel ter odšel, kakor mu je Jese zapovedal. Prišel je k okopu, medtem ko je šla vojska naprej v boj in zavpila za boj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Kajti Izrael in Filistejci so se postrojili v bitko, vojska zoper vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David je pustil svoj voz v roki čuvaja voza, stekel v vojsko, prišel in pozdravil svoje brate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Medtem ko je govoril z njimi, glej, je prišel šampion, Filistejec iz Gata, po imenu Goljat, iz vojske Filistejcev in govoril glede na te iste besede in David jih je slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Ko so vsi Izraelovi možje videli moža, so zbežali pred njim in bili so boleče prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Možje iz Izraela so rekli: »Ali ste videli tega moža, ki je prišel gor? Zagotovo je prišel gor, da Izraela izpostavi sramotenju. Zgodilo se bo, da bo moža, ki ga ubije, kralj obogatil z velikimi bogastvi in dal mu bo svojo hčer in osvobodil hišo njegovega očeta v Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'David je spregovoril možem, ki so stali poleg njega, rekoč: »Kaj bo storjeno možu, ki ubije tega Filistejca in odvzame grajo od Izraela? Kajti kdo je ta neobrezani Filistejec, da bi izpostavljal sramotenju vojske živega Boga?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Ljudstvo mu je odgovorilo na ta način, rekoč: »Tako bo storjeno možu, ki ga ubije.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Njegov najstarejši brat Eliáb pa je slišal, ko je govoril možem. Eliábova jeza je bila vžgana zoper Davida in rekel je: »Zakaj si prišel sèm dol? In s kom si pustil tistih nekaj ovc v divjini? Poznam tvojo ošabnost in porednost tvojega srca, kajti prišel si dol, da bi lahko videl bitko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David je rekel: »Kaj sem torej storil? Mar ni tam razlog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Od njega se je obrnil k drugemu in mu govoril na isti način, ljudstvo pa mu je ponovno odgovorilo po prejšnjem načinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Ko so bile slišane besede, ki jih je govoril David, so jih ponovili pred Savlom. In ta je poslal ponj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'David je rekel Savlu: »Naj srce nobenega človeka ne upade zaradi njega. Tvoj služabnik bo šel in se boril s tem Filistejcem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Savel je rekel Davidu: »Ti nisi zmožen iti zoper tega Filistejca, da se boriš z njim, kajti ti si še mladostnik, on pa je bojevnik od svoje mladosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'David je rekel Savlu: »Tvoj služabnik je pasel ovce svojega očeta in prišel je lev in medved in vzel jagnje iz tropa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Odšel sem ven za njim, ga udaril in to osvobodil iz njegovih ust. Ko se je dvignil zoper mene, sem ga ujel za njegovo grivo, ga udaril in usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Tvoj služabnik je usmrtil tako leva kakor medveda in ta neobrezani Filistejec bo kakor eden izmed njiju, glede na to, da je izzival vojske živega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Poleg tega je David rekel: » Gospod, ki me je osvobodil iz levje šape in iz medvedje šape, on me bo osvobodil iz roke tega Filistejca.« In Savel je rekel Davidu: »Pojdi in Gospod bodi s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Savel je Davida oborožil s svojo bojno opremo in mu na glavo nadel bronasto čelado. Prav tako ga je oborožil z verižnim plaščem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'David je opasal svoj meč na svojo bojno opremo in poskušal oditi, kajti tega ni preizkusil. David je rekel Savlu: »Ne morem iti s tem, kajti teh [stvari] nisem preizkusil.« In David jih je odložil iz sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Vzel je svojo palico v svojo roko in si izbral pet gladkih kamnov iz potoka in jih položil v pastirsko torbo, ki jo je imel, celo v malho in njegova prača je bila v njegovi roki in približal se je Filistejcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Filistejec je prišel in se približal Davidu in mož, ki je nosil ščit, je šel pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Ko je Filistejec pogledal naokoli in zagledal Davida, ga je preziral, kajti bil je šele mladostnik, rdečkast in lepega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Filistejec je Davidu rekel: » Sem mar pes, da prihajaš k meni s palicami?« Filistejec je Davida preklel pri svojih bogovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Filistejec je rekel Davidu: »Pridi k meni in tvoje meso bom izročil perjadi neba in živalim polja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Potem je David rekel Filistejcu: »Ti prihajaš k meni z mečem, s sulico in s ščitom, toda jaz prihajam k tebi v imenu Gospoda nad bojevniki, Boga Izraelovih vojsk, ki si ga izpostavljal sramotenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Ta dan te bo Gospod izročil v mojo roko in udaril te bom in tvojo glavo vzel iz tebe in trupla vojske Filistejcev bom ta dan izročil zračni perjadi in divjim zverem zemlje, da bo vsa zemlja lahko vedela, da je Bog v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Ves ta zbor bo vedel, da Gospod ne rešuje z mečem in sulico, kajti boj je Gospodov in on vas bo izročil v naše roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Pripetilo se je, ko je Filistejec vstal in prišel ter se približal, da sreča Davida, da je David pohitel in stekel proti vojski, da sreča Filistejca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'David je svojo roko položil v svojo torbo, od tam vzel kamen, ga zalučal in udaril Filistejca v njegovo čelo, da je kamen potonil v njegovo čelo in ta je padel na svoj obraz k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tako je David prevladal nad Filistejcem s pračo in s kamnom in Filistejca udaril in ubil, pa vendar v Davidovi roki ni bilo meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Zato je David stekel in obstal nad Filistejcem, vzel njegov meč, ga izvlekel iz njegove nožnice, ga ubil in z njim odsekal njegovo glavo. Ko so Filistejci videli, da je bil njihov šampion mrtev, so pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Možje iz Izraela in možje iz Juda so vstali, zavpili in zasledovali Filistejce, dokler ne prideš do doline in k velikim vratom Ekróna. Ranjeni izmed Filistejcev so padali dol po poti k Šaarájimu, celo do Gata in do Ekróna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Izraelovi otroci so se vrnili iz preganjanja za Filistejci in oplenili njihove šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David je vzel glavo Filistejca in jo prinesel v Jeruzalem, toda njegovo bojno opremo je odložil v svoj šotor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Ko je Savel zagledal Davida iti naprej zoper Filistejca, je rekel Abnêrju, poveljniku vojske: »Abnêr, čigav sin je ta mladostnik?« Abnêr je rekel: » Kakor živi tvoja duša, oh kralj, ne morem povedati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Kralj je rekel: »Poizvedi, čigav sin je ta najstnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Ko se je David vrnil iz uboja Filistejca, ga je Abnêr vzel in privedel pred Savla, s Filistejčevo glavo v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Savel mu je rekel: »Čigav sin si ti, ti mladenič?« David je odgovoril: »Jaz sem sin tvojega služabnika Betlehemca Jeseja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Pripetilo se je, ko je končal pogovor s Savlom, da se je Jonatanova duša povezala z Davidovo dušo in Jonatan ga je vzljubil kakor svojo lastno dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Savel ga je ta dan vzel in mu ni več dovolil iti domov, k hiši svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Potem sta Jonatan in David sklenila zavezo, ker ga je vzljubil kakor svojo lastno dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Jonatan si je slekel vrhnje oblačilo, ki je bilo na njem in ga dal Davidu, in svoja oblačila, celo do svojega meča, svojega loka in svojega pasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, '§ David je odšel ven, kamor ga je poslal Savel in se modro vedel. Savel ga je postavil nad bojevnike in sprejet je bil pred očmi vsega ljudstva in tudi pred očmi Savlovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Pripetilo se je, medtem ko so prišli, ko se je David vrnil iz pokola Filistejca, da so prišle ženske ven iz vseh Izraelovih mest, pojoč in plešoč, da srečajo kralja Savla z bobniči, z radostjo in z glasbenimi instrumenti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Ženske so odgovarjale druga drugi, medtem ko so igrale in govorile: »Savel je umoril svoje tisoče, David pa svoje deset tisoče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Savel je bil zelo ogorčen in [to] govorjenje mu ni ugajalo in je rekel: »Davidu so pripisale deset tisoče, meni pa so pripisale samo tisoče. Kaj ima lahko več kakor kraljestvo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Savel je od tistega dne dalje Davida opazoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, '§ Pripetilo se je naslednji dan, da je nad Savla prišel zli duh od Boga in je prerokoval v sredi hiše. David pa je igral s svojo roko kakor ob drugih časih. V Savlovi roki pa je bilo kopje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Savel je zalučal kopje, kajti rekel je: » S tem bom Davida udaril celo k zidu.« David pa se je dvakrat izognil njegovi prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Savel se je bal Davida, ker je bil Gospod z njim, od Savla pa je odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Zato ga je Savel odstranil od sebe in ga postavil za poveljnika nad tisočimi in odhajal in prihajal je pred ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'David se je na vseh svojih poteh obnašal modro in Gospod je bil z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Zato se ga je Savel, ko je videl, da se je obnašal zelo modro, bal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Toda ves Izrael in Juda je ljubil Davida, zato ker je odhajal in prihajal pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Savel je rekel Davidu: »Glej mojo starejšo hči Merábo, njo ti bom dal za ženo, samo hraber bodi zame in bojuj Gospodove boje.« Kajti Savel je rekel: »Naj moja roka ne bo nad njim, temveč naj bo nad njim roka Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David je rekel Savlu: »Kdo sem jaz? In kaj je moje življenje ali družina mojega očeta v Izraelu, da bi bil kraljev zet?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Toda pripetilo se je ob času, ko naj bi bila Savlova hči Merába dana Davidu, da je bila dana za ženo Mehólčanu Adriélu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Savlova hči Mihála je ljubila Davida in povedali so Savlu in stvar mu je ugajala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Savel je rekel: »Dal mu jo bom, da mu bo lahko za zanko in da bo roka Filistejcev lahko zoper njega.« Zato je Savel rekel Davidu: »Danes boš moj zet z eno od dveh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Savel je zapovedal svojim služabnikom, rekoč: »Na skrivaj se pogovarjajte z Davidom in recite: ›Glej, kralj se razveseljuje v tebi in vsi njegovi služabniki te ljubijo. Sedaj torej postani kraljev zet.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Savlovi služabniki so te besede govorili na Davidova ušesa. David je rekel: »Ali se vam zdi to lahka stvar postati kraljev zet, glede na to, da sem revež in preziran?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Savlovi služabniki so mu povedali, rekoč: »David je govoril na ta način.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Savel je rekel: »Tako boste rekli Davidu: ›Kralj ne želi nobene dote, temveč sto prednjih kožic Filistejcev, da bi bil maščevan nad kraljevimi sovražniki.‹« Toda Savel je mislil, da bi Davidu povzročil pasti po roki Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Ko so njegovi služabniki te besede povedali Davidu, je Davidu ugajalo, da bi bil kraljev zet in dnevi še niso pretekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Zato je David vstal in odšel, on in njegovi možje in izmed Filistejcev so usmrtili dvesto mož. David je prinesel njihove prednje kožice in v polnem številu so jih izročili kralju, da bi postal kraljev zet. In Savel mu je dal svojo hčer Mihálo za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Savel je videl in spoznal, da je bil Gospod z Davidom in da ga je Savlova hči Mihála ljubila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Savel pa se je še bolj bal Davida in Savel je dnevno postajal Davidov sovražnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, '§ Potem so princi Filistejcev odšli naprej in pripetilo se je, potem ko so šli naprej, da se je David obnašal bolj modro kakor vsi Savlovi služabniki, tako da je bilo njegovo ime zelo cenjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Savel je spregovoril svojemu sinu Jonatanu in vsem svojim služabnikom, da naj ubijejo Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Toda Savlov sin Jonatan se je zelo veselil v Davidu, in Jonatan je povedal Davidu, rekoč: »Moj oče Savel si prizadeva, da te ubije. Sedaj torej, prosim te, pazi nase do jutra in ostani na skritem mestu in se skrij,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'jaz pa bom šel ven in stal poleg svojega očeta na polju, kjer si ti in se bom s svojim očetom posvetoval o tebi in kar vidim, to ti bom povedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jonatan je svojemu očetu Savlu govoril dobro o Davidu in mu rekel: »Naj kralj ne greši zoper svojega služabnika, zoper Davida, ker on ni grešil zoper tebe in ker so bila njegova dela do tebe zelo dobra,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'kajti ali ni svojega življenja položil v svojo roko in usmrtil Filistejca in je Gospod izvršil veliko rešitev duš za ves Izrael. Ti si to videl in si se veselil. Zakaj potem hočeš grešiti zoper nedolžno kri, da bi Davida ubil brez razloga?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Savel je prisluhnil Jonatanovemu glasu in Savel je prisegel: » Kakor živi Gospod, on ne bo umorjen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Jonatan je poklical Davida in Jonatan mu je pokazal vse te stvari. Jonatan je Davida privedel k Savlu in bil je v njegovi prisotnosti, kakor v preteklih časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Tam je bila ponovno vojna in David je odšel ven in se boril s Filistejci in jih usmrtil z velikim pokolom in oni so zbežali od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Zli duh od Gospoda je bil nad Savlom, ko je sedel v svoji hiši, s svojim kopjem v svoji roki in David je igral s svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Savel si je prizadeval, da s kopjem udari Davida, celo k zidu, toda ta se je izmuznil iz Savlove prisotnosti in kopje je zapičil v zid, David pa je zbežal in tisto noč pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Savel je tudi k Davidovi hiši poslal poslance, da ga stražijo in da ga zjutraj ubijejo. In Davidova žena Mihála mu je povedala, rekoč: »Če nocoj ne rešiš svojega življenja, boš jutri umorjen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Tako je Mihála Davida spustila navzdol skozi okno in odšel je, bežal ter pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Mihála pa je vzela kip in ga položila na posteljo in za njegov vzglavnik položila blazino iz kozje dlake in to pokrila z obleko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Ko je Savel poslal poslance, da primejo Davida, je rekla: »Bolan je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Savel je ponovno poslal poslance, da vidijo Davida, rekoč: »Privedite ga gor k meni v postelji, da ga bom lahko ubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Ko so poslanci vstopili, glej, je bil v postelji kip, z blazino iz kozje dlake za njegov vzglavnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Savel je rekel Miháli: »Zakaj si me tako zavedla in mojega sovražnika poslala proč, da je pobegnil?« Mihála je Savlu odgovorila: »Rekel mi je: ›Pusti me oditi; čemu bi te ubil?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Tako je David bežal, pobegnil in prišel k Samuelu v Ramo ter mu povedal vse, kar mu je Savel storil. In on in Samuel sta odšla ter prebivala v Najótu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'To je bilo povedano Savlu, rekoč, poglej: »David je pri Najótu v Rami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Savel je poslal poslance, da primejo Davida. Ko pa so ti zagledali skupino prerokov, ki je prerokovala in Samuela stati kot določenega nad njimi, je bil Božji Duh nad Savlovimi poslanci in tudi oni so prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Ko je bilo to povedano Savlu, je poslal druge poslance in tudi ti so prerokovali. In Savel je ponovno, tretjič, poslal poslance in tudi ti so prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Potem je tudi sam odšel v Ramo in prišel k velikemu vodnjaku, ki je v Sehuju. Vprašal je in rekel: »Kje sta Samuel in David?« Nekdo je rekel: »Glej, onadva sta pri Najótu v Rami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'In odšel je tja k Najótu v Ramo in Božji Duh je bil tudi nad njim in šel je naprej in prerokoval, dokler ni prišel k Najótu v Ramo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Tudi on je slekel svoja oblačila in na podoben način prerokoval pred Samuelom in ves ta dan in vso noč ležal gol. Zato pravijo: » Ali je tudi Savel med preroki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David je pobegnil iz Najóta v Rami in prišel ter pred Jonatanom rekel: »Kaj sem storil? Kaj je moja krivda? Kakšen je moj greh pred tvojim očetom, da mi streže po življenju?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Rekel mu je: »Bog ne daj. Ne boš umrl. Glej, moj oče ne bo storil ničesar, ali velikega ali malega, razen, da mi bo to pokazal. Zakaj bi moj oče to stvar skril pred menoj? To ni tako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'David je poleg tega prisegel in rekel: »Tvoj oče zagotovo ve, da sem našel milost v tvojih očeh.« Rekel je: »Naj Jonatan tega ne izve, da ne bi bil užaloščen, toda resnično, kakor živi Gospod in kakor živi tvoja duša, je samo korak med menoj in smrtjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Potem je Jonatan rekel Davidu: »Karkoli želi tvoja duša, celo to bom storil zate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David je Jonatanu rekel: »Glej, jutri je mlaj in jaz naj ne bi manjkal sedeti s kraljem pri mizi. Toda pusti mi oditi, da se lahko skrijem na polju do tretjega dne zvečer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Če me tvoj oče sploh pogreši, potem reci: ›David je iskreno prosil oditi od mene, da lahko teče v svoje mesto Betlehem, kajti tam je letna klavna daritev za vso družino.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Če reče tako: › To je dobro,‹ bo tvoj služabnik imel mir. Toda če bo zelo ogorčen, potem bodi prepričan, da je po njem določeno zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Zato boš prijazno postopal s svojim služabnikom, kajti svojega služabnika si privedel v Gospodovo zavezo s seboj. Vendar če bo v meni krivičnost, me sam ubij, kajti zakaj bi me privedel k svojemu očetu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonatan je rekel: »To bodi daleč od tebe, kajti če zagotovo izvem, da je bilo po mojem očetu določeno zlo, da pride nadte, mar ti ne bi potem tega povedal?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Potem je David rekel Jonatanu: »Kdo mi bo povedal? Ali kaj če ti tvoj oče odgovori surovo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan je rekel Davidu: »Pridi in pojdiva ven na polje.« In oba izmed njiju sta odšla na polje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Jonatan je rekel Davidu: »Oh Gospod, Izraelov Bog, ko bom kadarkoli slišal svojega očeta, jutri ali tretji dan in glej, če bo dobro do Davida in potem ne pošljem k tebi in ti tega ne pokažem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Gospod stori tako in mnogo več Jonatanu. Toda če to ugaja mojemu očetu, da ti stori zlo, potem ti bom to pokazal in te poslal proč, da boš lahko šel v miru, in Gospod bodi s teboj, kakor je bil z mojim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Dokler še živim ne boš samo meni izkazoval Gospodove prijaznosti, da ne umrem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'temveč tudi svoje prijaznosti ne boš odsekal od moje hiše na veke. Ne, niti ko je Gospod odsekal Davidove sovražnike, vsakega iz obličja zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Tako je Jonatan sklenil zavezo z Davidovo hišo, rekoč: »Naj Gospod to celo zahteva pri roki Davidovih sovražnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Jonatan je Davidu dal, da je ponovno prisegel, ker ga je ljubil, kajti ljubil ga je, kakor je ljubil svojo lastno dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Potem je Jonatan rekel Davidu: »Jutri je mlaj in ti boš pogrešan, ker bo tvoj sedež prazen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Ko boš tri dni ostal, potem boš hitro šel dol in prišel h kraju, kjer si se skril, ko je bilo opravilo v roki in ostal boš pri kamnu Ezelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Jaz pa bom izstrelil tri puščice na tej strani, kakor če streljam v tarčo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Glej, poslal bom dečka, rekoč: ›Pojdi, najdi puščice.‹ Če bom dečku izrecno rekel: ›Glej, puščice so na tej tvoji strani, vzemi jih,‹ potem pridi, kajti tam je zate mir in nobene škode, kakor Gospod živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Toda če mladeniču rečem tako: ›Glej, puščice so onstran tebe,‹ pojdi svojo pot, kajti Gospod te pošilja proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Glede zadeve, o kateri sva govorila, glej, Gospod bodi med menoj in teboj na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Tako se je David skril na polju. Ko je prišel mlaj, se je kralj usedel, da jé hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kralj je sedel na svojem sedežu, kakor ob drugih časih, torej sedežu pri zidu in Jonatan je vstal in Abnêr je sedel pri Savlovi strani, Davidovo mesto pa je bilo prazno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Kljub temu Savel ta dan ni spregovoril nobene stvari, kajti mislil je: »Nekaj se mu je pripetilo, ni čist. Zagotovo ni čist.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Pripetilo se je naslednji dan, ki je bil drugi dan meseca, da je bil Davidov prostor prazen. Savel je rekel svojemu sinu Jonatanu: »Zakaj ne prihaja Jesejev sin k jedi niti včeraj niti danes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonatan je odgovoril Savlu: »David me je iskreno prosil za dovoljenje, da gre v Betlehem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Rekel je: ›Pusti me oditi, prosim te, kajti naša družina ima klavno daritev v mestu in moj brat mi je zapovedal, naj bom tam in sedaj, če sem našel naklonjenost v tvojih očeh, mi pusti oditi, prosim te in videti svoje brate.‹ Zato ne prihaja h kraljevi mizi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Potem je bila Savlova jeza vžgana zoper Jonatana in mu je rekel: »Ti, sin sprevržene uporne ženske, mar ne vem, da si si izbral Jesejevega sina v svojo lastno zmedo in k zmedi nagote svoje matere?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Kajti dokler Jesejev sin živi na zemlji, ne boš utrjen niti tvoje kraljestvo. Zato sedaj pošlji in mi ga pripelji, kajti zagotovo bo umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonatan je svojemu očetu Savlu odgovoril in mu rekel: »Zakaj naj bi bil umorjen? Kaj je storil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Savel je vanj vrgel kopje, da ga pobije, po čemer je Jonatan vedel, da je bilo od njegovega očeta odločeno, da Davida usmrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Tako je Jonatan v siloviti jezi vstal od mize in drugi dan meseca ni jedel nobene hrane, kajti užaloščen je bil zaradi Davida, ker mu je oče storil sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Pripetilo se je zjutraj, da je Jonatan odšel na polje ob času, dogovorjenem z Davidom in majhen deček z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Svojemu dečku je rekel: »Steci, poišči sedaj puščice, ki jih izstrelim.« In medtem ko je deček stekel, je izstrelil puščico preko njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Ko je deček prišel na mesto puščice, ki jo je Jonatan izstrelil, je Jonatan zaklical za dečkom in rekel: » Ali ni puščica onstran tebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Jonatan je zaklical za dečkom: »Podvizaj se, pohiti, ne stoj.« Jonatanov deček je zbral puščice in prišel k svojemu gospodarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Toda deček ni vedel nobene stvari. Samo Jonatan in David sta poznala zadevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Jonatan je izročil svoje strelno orožje svojemu dečku in mu rekel: »Pojdi, odnesi jih v mesto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'In brž ko je deček odšel, se je David dvignil iz kraja proti jugu in padel na svoj obraz na tla in se trikrat priklonil. Drug drugega sta poljubila in jokala drug z drugim, dokler David ni prevladal [v joku].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Jonatan je rekel Davidu: »Pojdi v miru, kakor sva oba izmed naju prisegla v Gospodovem imenu, rekoč: ›GOSPOD bodi med menoj in teboj in med mojim semenom in tvojim semenom na veke.‹« In vstal je ter odpotoval, Jonatan pa je odšel v mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Potem je David prišel v Nob, k duhovniku Ahimélehu in Ahiméleh se je bal ob srečanju z Davidom in mu je rekel: »Zakaj si sam in ni nikogar s teboj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David je rekel duhovniku Ahimélehu: »Kralj mi je zapovedal opravilo in mi rekel: ›Naj noben človek ne izve karkoli o opravilu, s katerim te pošiljam in kaj sem ti zapovedal in svoje služabnike sem določil na takšen in takšen kraj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Zdaj torej kaj je pod tvojo roko? Daj mi pet hlebov kruha v roko ali kar je prisotnega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Duhovnik je Davidu odgovoril in rekel: » Tam ni običajnega kruha pod mojo roko, temveč je posvečen kruh, če so se vsaj mladeniči zadržali pred ženskami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, '§ David je odgovoril duhovniku in mu rekel: »Resnično so bile ženske zadržane pred nami te tri dni, odkar sem prišel ven in posode mladeničev so svete in kruh je nekako običajen, da, kot bi bil ta dan posvečen v posodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Tako mu je duhovnik dal posvečenega kruha, kajti tam ni bilo kruha, razen hleba navzočnosti, kar je bilo vzeto izpred Gospoda, da se položi vroč kruh na dan, ko je bil ta vzet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Torej nek mož izmed Savlovih služabnikov se je ta dan zadrževal tam pred Gospodom in njegovo ime je bilo Doég, Edómec, glavni izmed črednikov, ki so pripadali Savlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'David je rekel Ahimélehu: »In ali ni tukaj pod tvojo roko sulica ali meč? Kajti s seboj nisem prinesel niti svojega meča niti svojih orožij, ker je kraljev posel zahteval naglico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Duhovnik je rekel: »Meč Filistejca Goljata, ki si ga umoril v dolini Elá, glej, ta je tukaj, za efódom zavit v oblačilo. Če hočeš vzeti tega, ga vzemi, kajti nobenega drugega ni, razen tega tukaj.« David je rekel: »Nobenega ni podobnega temu; daj mi ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'David se je vzdignil in tisti dan iz strahu pred Savlom pobegnil in šel k Ahíšu, kralju v Gatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Ahíševi služabniki so mu rekli: » Ali ni to David, kralj dežele? Ali niso prepevale druga drugi o njem v plesih, rekoč: ›Savel je umoril svoje tisoče, David pa svoje deset tisoče?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'David si je te besede položil v svoje srce in se boleče bal Ahíša, kralja iz Gata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Pred njimi je spremenil svoje obnašanje in v njihovih rokah se je hlinil zmešanega in praskal po vhodih velikih vrat in si svojo slino pustil izlivati na svojo brado.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Potem je Ahíš rekel svojim služabnikom: »Glejte no! Vidite, človek je zmešan. Zakaj ste ga torej privedli k meni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Mar potrebujem zmešanih ljudi, da ste pripeljali tega pajdaša, da igra norca v moji prisotnosti? Ali naj ta pajdaš pride v mojo hišo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David je torej odpotoval od tam in pobegnil v votlino Adulám. Ko so njegovi bratje in vsa hiša njegovega očeta to slišali, so odšli dol, tja k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'K njemu so se zbrali skupaj vsak, kdor je bil v stiski in vsak, kdor je bil v dolgu in vsak, kdor je bil nezadovoljen; in postal je poveljnik nad njimi in tam je bilo z njim okoli štiristo mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'David je od tam odšel v moábsko Micpo in moabskemu kralju rekel: »Naj moj oče in moja mati, prosim te, prideta naprej in bosta s teboj, dokler ne izvem kaj bo Bog storil zame.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'In privedel ju je pred moábskega kralja in prebivala sta z njim ves čas, ko je bil David v utrjenem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Prerok Gad je rekel Davidu: »Ne prebivaj v utrjenem kraju. Odidi in pojdi v Judovo deželo.« Potem je David odrinil in prišel v gozd Heret.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Ko je Savel slišal, da so odkrili Davida in može, ki so bili z njim (torej Savel je prebival v Gíbei, pod drevesom v Rami, s svojo sulico v svoji roki in vsi njegovi služabniki so stali okoli njega),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'je potem Savel rekel svojim služabnikom, ki so stali okoli njega: »Poslušajte torej, vi Benjaminovci, ali bo Jesejev sin vsakemu izmed vas dal polja in vinograde in vas vse postavil za poveljnike nad tisočimi in poveljnike nad stotimi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'da ste se vsi izmed vas zarotili zoper mene in tam ni nikogar, ki mi kaže, da je moj sin sklenil dogovor z Jesejevim sinom in tam ni nikogar izmed vas, ki mu je žal zame ali mi kaže, da je moj sin zoper mene razvnel mojega služabnika, da preži v zasedi, kakor ta dan?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Potem je odgovoril Edómec Doég, ki je bil postavljen nad Savlove služabnike in rekel: »Videl sem Jesejevega sina prihajati v Nob, k Ahitúbovemu sinu Ahimélehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Ta je od Gospoda povprašal zanj in dal mu je živež in dal mu je meč Filistejca Goljata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Potem je kralj poslal, da pokliče duhovnika Ahiméleha, Ahitúbovega sina in vso hišo njegovega očeta, duhovnike, ki so bili v Nobu in vsi izmed njih so prišli h kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Savel je rekel: »Poslušaj sedaj ti, Ahitúbov sin.« Ta je odgovoril: »Tukaj sem, moj gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Savel mu je rekel: »Zakaj sta se zarotila zoper mene, ti in Jesejev sin, v tem, da si mu dal kruha in meč in si od Boga poizvedel zanj, da bi on vstal zoper mene, da preži v zasedi kakor na ta dan?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Potem je Ahiméleh odgovoril kralju in rekel: »Kdo je tako zvest med vsemi tvojimi služabniki kakor David, ki je kraljev zet in gre ob tvojem ukazu in je častitljiv v tvoji hiši?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Ali sem takrat začel poizvedovati od Boga zanj? To bodi daleč od mene. Naj kralj ne pripiše kakršnekoli stvari svojemu služabniku niti vsej hiši mojega očeta, kajti tvoj služabnik ni vedel nič od vsega tega, manj ali več.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Kralj je rekel: »Zagotovo boš umrl, Ahiméleh, ti in vsa hiša tvojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Kralj je rekel pešcem, ki so stali okoli njega: »Obrnite se in ubijte Gospodove duhovnike, ker je tudi njihova roka z Davidom in ker so vedeli, ko je on pobegnil, pa mi tega niso pokazali.« Toda kraljevi služabniki niso hoteli iztegniti svoje roke, da pade na Gospodove duhovnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Kralj je rekel Doégu: »Ti se obrni in padi nad duhovnike.« In Edómec Doég se je obrnil in padel nad duhovnike in jih na ta dan usmrtil petinosemdeset oseb, ki so nosili lanen efód.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Nob, mesto duhovnikov, je udaril z ostrino meča, tako moške kakor ženske, otroke in dojenčke, vole, osle in ovce, z ostrino meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Eden izmed Ahimélehovih sinov, Ahitúbov sin, imenovan Abjatár, pa je ušel in pobegnil za Davidom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Abjatár je pokazal Davidu, da je Savel umoril Gospodove duhovnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'David je rekel Abjatárju: »Vedel sem to ta dan, ko je bil tam Edómec Doég, da bo zagotovo povedal Savlu. Povzročil sem smrt vseh oseb hiše tvojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Ostani z menoj, ne boj se, kajti kdor streže po mojem življenju, streže po tvojem življenju. Toda z menoj boš na varnem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Potem so povedali Davidu, rekoč: »Glej, Filistejci se bojujejo zoper Keílo in ropajo mlatišča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Zato je David poizvedel od Gospoda, rekoč: »Ali naj grem in udarim te Filistejce?« Gospod je rekel Davidu: »Pojdi in udari Filistejce in reši Keílo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Davidovi ljudje so mu rekli: »Glej, bojimo se tukaj v Judu. Koliko bolj potem, če pridemo v Keílo zoper vojske Filistejcev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Potem je David ponovno poizvedel od Gospoda. In Gospod mu je odgovoril ter rekel: »Vstani, pojdi dol v Keílo, kajti jaz bom Filistejce izročil v tvojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Tako so David in njegovi ljudje odšli v Keílo in se borili s Filistejci in odvedli njihovo živino in jih udarili z velikim pokolom. Tako je David rešil prebivalce Keíle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Pripetilo se je, ko je Ahimélehov sin Abjatár pobegnil k Davidu v Keílo, da je ta prišel dol z efódom v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Savlu je bilo povedano to, da je David prišel v Keílo. Savel je rekel: »Bog ga je izročil v mojo roko, kajti z vstopom v mesto, ki ima velika vrata in zapahe, je zaprt noter.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Savel je vse ljudstvo sklical skupaj k vojni, da gredo dol v Keílo, da oblegajo Davida in njegove može.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'David pa je vedel, da je Savel zoper njega skrivno izvajal vragolijo in duhovniku Abjatárju je rekel: »Prinesi sèm efód.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Potem je David rekel: »Oh Gospod, Izraelov Bog, tvoj služabnik je zagotovo slišal, da Savel išče, da bi prišel v Keílo, da zaradi mene uniči mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Ali me bodo možje iz Keíle izročili v njegovo roko? Ali bo Savel prišel dol, kakor je tvoj služabnik slišal? Oh Gospod, Izraelov Bog, rotim te, povej svojemu služabniku.« Gospod je rekel: »Prišel bo dol.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Potem je David rekel: »Ali bodo možje iz Keíle izročili mene in moje ljudi v Savlovo roko?« Gospod je rekel: »Izročili te bodo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Potem so David in njegovi možje, ki jih je bilo okoli šeststo, vstali in odrinili iz Keíle in odšli, kamor so lahko šli. To je bilo povedano Savlu, da je David pobegnil iz Keíle in ta je opustil, da gre naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David je prebival v divjini, v oporiščih in ostal na gori, v divjini Zif. Savel ga je vsak dan iskal, toda Bog ga ni izročil v njegovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David je videl, da je Savel prišel ven, da bi stregel po njegovem življenju in David je bil v Zifski divjini, v gozdu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Savlov sin Jonatan je vstal in odšel k Davidu v gozd in okrepil njegovo roko v Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Rekel mu je: »Ne boj se, kajti roka mojega očeta Savla te ne bo našla. Ti boš kralj nad Izraelom in jaz bom poleg tebe in to tudi moj oče Savel ve.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Onadva sta sklenila zavezo pred Gospodom in David je ostal v gozdu, Jonatan pa je odšel k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, '§ Potem so prišli gor Zífovci k Savlu v Gíbeo, rekoč: »Ali se ne skriva David z nami v oporiščih v gozdu, na hribu Hahíla, ki je na jugu Ješimona?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Zdaj torej, oh kralj, pridi dol glede na vso željo svoje duše, da prideš dol in naš del bo, da ga izročimo v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Savel je rekel: »Blagoslovljeni bodite od Gospoda, kajti do mene imate sočutje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Pojdite, prosim vas, še pripravite in spoznajte in poglejte na njegov kraj, kjer je njegovo shajališče in kdo ga je videl tam, kajti povedano mi je, da postopa zelo premeteno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Glejte torej in vzemite spoznanje o vseh skrivnih krajih, kjer se sam skriva in ponovno pridite k meni z gotovostjo in jaz bom šel z vami in zgodilo se bo, če bo v deželi, da ga bom poiskal med vsemi Judovimi tisočimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, '§ Vstali so in pred Savlom odšli v Zif, toda David in njegovi ljudje so bili v Maónski divjini, na ravnini, južno od Ješimona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Tudi Savel in njegovi ljudje so odšli, da ga iščejo. Davidu so povedali, zato je prišel dol v skalo in ostal v Maónski divjini. Ko je Savel to slišal, je zasledoval Davida v Maónski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Savel je šel po tej strani gore, David in njegovi ljudje pa po oni strani gore. David se je podvizal, da odide zaradi strahu pred Savlom, kajti Savel in njegovi ljudje so obkolili Davida in njegove može okrog in okrog, da jih zgrabijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Toda k Savlu je prišel poslanec, rekoč: »Pohiti in pridi, kajti Filistejci so vdrli v deželo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Zato se je Savel vrnil od zasledovanja za Davidom in odšel zoper Filistejce. Zato so ta kraj imenovali Sela-hamah-lekot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'David se je dvignil od tam in prebival v oporiščih pri En Gediju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Pripetilo se je, ko se je Savel vrnil iz zasledovanja Filistejcev, da mu je bilo povedano, rekoč: »Glej, David je v divjini En Gedi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Potem je Savel vzel tri tisoč izbranih mož iz vsega Izraela in odšel, da poišče Davida in njegove ljudi na skalah divjih koz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Ob poti je prišel k stajam za ovce, kjer je bila votlina in Savel je šel noter, da pokrije svoja stopala. David in njegovi možje pa so ostajali ob straneh votline.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Davidovi možje so mu rekli: »Glej, dan, o katerem ti je rekel Gospod: ›Glej, tvojega sovražnika bom izročil v tvojo roko, da mu boš lahko storil, kakor se ti zdi dobro.‹« Potem je David vstal in na skrivnem odsekal krajec Savlovega svečanega oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Pripetilo se je potem, da ga je Davidovo srce udarilo, ker je odsekal krajec Savlovega oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Svojim možem je rekel: » Gospod ne daj, da bi storil tako stvar svojemu gospodarju, Gospodovemu maziljencu, da iztegnem svojo roko zoper njega, ker je maziljen od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Tako je David s temi besedami zadržal svoje služabnike in jim ni pustil, da vstanejo zoper Savla. Toda Savel je vstal iz votline in odšel na svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Potem je tudi David vstal in šel ven iz votline in zaklical za Savlom, rekoč: »Moj gospod kralj.« Ko je Savel pogledal za seboj, se je David sklonil s svojim obrazom k zemlji in se priklonil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'David je rekel Savlu: »Zakaj poslušaš besede ljudi, govoreč: ›Glej, David išče tvoje zlo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Glej, ta dan so tvoje oči videle, kako te je Gospod v votlini izročil v mojo roko. Nekateri so mi zaukazali, naj te usmrtim, toda moje oko ti je prizaneslo. Rekel sem: ›Ne bom iztegnil svoje roke zoper svojega gospoda, kajti on je Gospodov maziljenec.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Poleg tega, moj oče, glej, da, poglej krajec svojega svečanega oblačila v moji roki, kajti v tem, da sem odsekal krajec tvojega svečanega oblačila in te nisem usmrtil, vedi in vidi, da v moji roki ni niti zla niti prestopka in nisem grešil zoper tebe, vendar ti loviš mojo dušo, da jo vzameš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Gospod sodi med menoj in teboj in Gospod naj me maščuje nad teboj, toda moja roka ne bo nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Kakor pravi pregovor starcev: ›Zlobnost izvira od zlobnih,‹ toda moja roka ne bo nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Za kom je Izraelov kralj prišel ven? Za kom tečeš? Za mrtvim psom, za bolho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Gospod naj bo torej sodnik in sodi med menoj in teboj in gleda in zagovarja mojo pravdo in me osvobodi iz tvoje roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Pripetilo se je, ko je David Savlu prenehal govoriti te besede, da je Savel rekel: » Ali je to tvoj glas, moj sin David?« Savel je povzdignil svoj glas in zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Davidu je rekel: »Pravičnejši si kakor jaz, kajti nagradil si mi dobro, medtem ko sem ti jaz nagradil zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Danes si pokazal, kako dobro si ravnal z menoj, ker ko me je Gospod izročil v tvojo roko, me nisi ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Kajti če človek najde svojega sovražnika ali ga bo pustil sproščeno oditi? Zato [naj] te Gospod dobro nagradi za to, kar si mi ta dan storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Sedaj glej, dobro vem, da boš zagotovo postal kralj in da bo Izraelovo kraljestvo utrjeno v tvoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Prisezi mi torej sedaj pri Gospodu, da ne boš iztrebil mojega semena za menoj in da ne boš uničil mojega imena iz hiše mojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'David je prisegel Savlu. Savel je odšel domov, toda David in njegovi možje so se povzpeli na utrjen kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Samuel je umrl in vsi Izraelci so se zbrali skupaj, ga objokovali in ga pokopali v njegovi hiši v Rami. In David je vstal ter odšel dol k Paránski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Tam je bil mož v Maónu, katerega posesti so bile v Karmelu. Mož je bil zelo velik in imel je tri tisoč ovc in tisoč koz, in svoje ovce je strigel v Karmelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Torej moževo ime je bilo Nabál in ime njegove žene Abigájila. Bila je ženska dobrega razumevanja in krasnega obličja, toda mož je bil skopušen in hudoben v svojih dejanjih. Bil je iz Kalébove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'David je v divjini slišal, da je Nabál strigel svoje ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'David je poslal ven deset mladeničev in David je mladeničem rekel: »Povzpnite se gor do Karmela in pojdite k Nabálu ter ga pozdravite v mojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Tako boste rekli njemu, ki živi v uspevanju: ›Mir bodi tako tebi in mir bodi tvoji hiši in mir bodi vsemu, kar imaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Sedaj sem slišal, da si imel strižce. Torej tvoji pastirji, ki so bili z nami, jih nismo poškodovali niti jim ni ničesar zmanjkalo, vse dokler so bili v Karmelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Vprašaj svoje mladeniče in ti bodo pokazali. Zato naj tvoji mladeniči najdejo naklonjenost v tvojih očeh, kajti prišli smo na dober dan. Daj, prosim te, karkoli pride k tvoji roki, svojim služabnikom in svojemu sinu Davidu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Ko so Davidovi mladeniči prišli, so v Davidovem imenu govorili Nabálu glede na vse te besede in prenehali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabál je odgovoril Davidovim služabnikom in rekel: »Kdo je David? Kdo je Jesejev sin? Današnje dni je mnogo služabnikov, ki se odtrgajo, vsak mož od svojega gospodarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Mar naj torej vzamem svoj kruh, svojo vodo in svoje meso, ki sem ga zaklal za svoje strižce in ga dam možem, za katere ne vem, od kod so?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Tako so Davidovi mladeniči obrnili svojo pot in ponovno odšli in prišli ter mu povedali vse te besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'David je svojim možem rekel: »Opašite vsak mož svoj meč.« Opasali so vsak mož svoj meč in tudi David je opasal svoj meč in tam se je dvignilo za Davidom okoli štiristo mož. Dvesto pa jih je ostalo pri stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Toda eden izmed mladeničev je povedal Nabálovi ženi Abigájili, rekoč: »Glej, David je iz divjine poslal poslance, da pozdravijo našega gospodarja, on pa se jim je posmehoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Toda možje so bili zelo dobri do nas in nismo bili poškodovani niti nismo pogrešali nobene stvari, dokler smo bili seznanjeni z njimi, ko smo bili na poljih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Bili so nam zid, tako podnevi kakor ponoči, ves čas smo bili z njimi, čuvajoč ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Zdaj torej vedi in preudari, kaj boš storila, kajti zlo je določeno zoper našega gospodarja in zoper vso njegovo družino, kajti on je tak Beliálov sin, da človek ne more govoriti z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Potem se je Abigájila podvizala in vzela dvesto hlebov, dva vinska meha, pet pripravljenih ovc, pet mer opraženega žita, sto grozdov rozin in dvesto figovih kolačev in jih položila na osle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Svojim služabnikom je rekla: »Pojdite naprej pred menoj. Glejte, jaz pridem za vami.« Toda svojemu soprogu Nabálu ni povedala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'To je bilo tako, medtem ko je jahala na oslu, da je prišla dol ob zavetju hriba in glej, David in njegovi možje so prihajali dol, nasproti njej in jih je srečala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Torej David je rekel: »Zagotovo sem v divjini zaman varoval vse, kar je imel ta pajdaš, tako da ni zmanjkalo ničesar od vsega, kar je pripadalo njemu, on pa mi je povrnil zlo za dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, '§ Tako in še več naj tudi Bog stori Davidovim sovražnikom, če do jutranje svetlobe pustim od vsega, kar pripada njemu, karkoli, kar lula proti zidu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Ko je Abigájila zagledala Davida, je pohitela in razbremenila osla in pred Davidom padla na svoj obraz in se priklonila do tal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'in padla ob njegovih stopalih ter rekla: »Nad menoj, moj gospod, nad menoj naj bo ta krivičnost. Naj tvoja pomočnica, prosim te, govori v tvoji pozornosti in poslušaj besede svoje pomočnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Naj se moj gospod, prosim te, ne ozira na tega Beliálovega moža, celó Nabála, kajti kakor je njegovo ime, takšen je on; Nabál je njegovo ime in bedaštvo je z njim, toda jaz, tvoja pomočnica, nisem videla mladeničev svojega gospoda, ki si jih poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Zdaj torej, moj gospod, kakor živi Gospod in kakor živi tvoja duša, glede na to, da te je Gospod zadržal pred tem, da bi prihajal prelit kri in pred tem, da bi se maščeval s svojo lastno roko, naj bodo torej tvoji sovražniki in tisti, ki iščejo zlo mojemu gospodu, kakor Nabál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Naj bo sedaj ta blagoslov, ki ga je tvoja pomočnica prinesla mojemu gospodu, dan mladeničem, ki sledijo mojemu gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Prosim te, odpusti prekršek svoje pomočnice, kajti Gospod bo zagotovo naredil mojemu gospodu zanesljivo hišo, ker moj gospod bojuje Gospodove bitke in vse tvoje dni zlo ni bilo najdeno v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Vendar se je vzdignil človek, da te preganja in da išče tvojo dušo, toda duša mojega gospoda bo zvezana v svežnju življenja z Gospodom, tvojim Bogom. Duše tvojih sovražnikov, njih bo zalučal ven kakor iz srede prače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'In zgodilo se bo, ko bo Gospod storil mojemu gospodu glede na vse dobro, kar je govoril glede tebe in te določil vladarja nad Izraelom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'da to ne bo žalost tebi niti prizadeto srce mojemu gospodu ali da si brez vzroka prelil kri ali da se je moj gospod sam maščeval, temveč ko bo Gospod dobro postopal z mojim gospodom, takrat se spomni svoje pomočnice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'David je rekel Abigájili: »Blagoslovljen bodi Gospod, Izraelov Bog, ki te je ta dan poslal, da me srečaš');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'in blagoslovljen bodi tvoj nasvet in blagoslovljena bodi ti, ki si me ta dan zadržala pred prihajanjem, da prelijem kri in pred maščevanjem sebe s svojo lastno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, '§ Kajti zagotovo, kakor Gospod, Izraelov Bog, živi, ki me je zadržal pred tem, da ti škodujem, razen če ne bi pohitela in prišla, da me srečaš, zagotovo ne bi do jutranje svetlobe Nabálu ostalo karkoli, kar lula proti zidu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Tako je David iz njene roke prejel to, kar mu je prinesla in ji rekel: »Pojdi gor v miru k svoji hiši. Glej, prisluhnil sem tvojemu glasu in sprejel tvojo osebo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Abigájila je prišla k Nabálu in glej, v svoji hiši je imel zabavo, kakor kraljevo zabavo. Nabálovo srce je bilo veselo znotraj njega, kajti bil je zelo pijan. Zato mu ni ničesar povedala, manj ali več, do jutranje svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Toda zjutraj se je pripetilo, ko je vino odšlo iz Nabála in mu je njegova žena povedala te stvari, da je njegovo srce znotraj njega umrlo in je postal kakor kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Pripetilo se je okoli deset dni kasneje, da je Gospod udaril Nabála, da je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Ko je David slišal, da je bil Nabál mrtev, je rekel: »Blagoslovljen bodi Gospod, ki je zagovarjal zadevo moje graje pred Nabálovo roko in je svojega služabnika obvaroval pred zlom, kajti Gospod je Nabálovo zlobnost povrnil na njegovo lastno glavo.« In David je poslal in se posvetoval z Abigájilo, da si jo vzame k sebi za ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Ko so Davidovi služabniki prišli k Abigájili v Karmel, so ji spregovorili, rekoč: »David nas je poslal k tebi, da te vzame k sebi za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Vzdignila se je, se priklonila na svoj obraz k zemlji in rekla: »Glej, naj bo tvoja pomočnica služabnica, da umiva stopala služabnikov mojega gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Abigájila je pohitela, vstala ter jahala na oslu s petimi svojimi gospodičnami, ki so šle za njo in odšla je za Davidovimi poslanci ter postala njegova žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David je vzel tudi Ahinóam iz Jezreéla in obe izmed njiju sta bili njegovi ženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Toda Savel je dal svojo hčer Mihálo, Davidovo ženo, Paltíju, Lajiševemu sinu, ki je bil iz Galíma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, '§ Zífovci so prišli k Savlu v Gíbeo, rekoč: »Ali se David ne skriva na hribu Hahíla, ki je pred Ješimonom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Potem se je Savel dvignil in odšel dol k Zifski divjini in s seboj je imel tri tisoč izbranih mož iz Izraela, da Davida poiščejo v Zifski divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, '§ Savel je taboril na hribu Hahíla, ki je ob poti pred Ješimonom. Toda David je prebival v divjini in videl je, da je Savel prišel za njim v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'David je torej odposlal oglednike in razumel, da je Savel zagotovo prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'David je vstal in prišel na kraj, kjer se je Savel utaboril in David je opazoval kraj, kjer sta se ulegla Savel in Abnêr, Nerov sin, poveljnik njegove vojske. Savel pa je ležal v okopu in ljudstvo je taborilo okoli njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Potem je David odgovoril in rekel Hetejcu Ahimélehu in Cerújinemu sinu Abišáju, Joábovemu bratu, rekoč: »Kdo bo odšel z menoj dol, k Savlu v tabor?« Abišáj je rekel: »Jaz bom odšel dol s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Tako sta David in Abišáj prišla ponoči k ljudstvu in glej, Savel je speč ležal znotraj okopa in njegova sulica zapičena v tla pri njegovem vzglavniku, toda Abnêr in ljudstvo so ležali naokoli njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Potem je Abišáj rekel Davidu: »Bog je ta dan izročil tvoje sovražnike v tvojo roko. Zdaj naj ga torej udarim, prosim te, s sulico celo k zemlji in ne bom ga udaril drugič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'David je rekel Abišáju: »Ne uniči ga, kajti kdo lahko iztegne svojo roko zoper Gospodovega maziljenca in je brez krivde?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'David je nadalje rekel: » Kakor Gospod živi, Gospod ga bo udaril, ali bo prišel njegov dan, da umre, ali [pa] se bo spustil v bitko in umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Gospod me obvaruj, da bi iztegnil svojo roko zoper Gospodovega maziljenca, toda, prosim te, vzemi sedaj sulico, ki je pri njegovem vzglavniku in vrč vode ter odidiva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Tako je David vzel sulico in vrč vode izpred Savlovega vzglavnika in spravila sta se proč in noben človek tega ni videl niti ni tega spoznal niti se zbudil, kajti vsi so zaspali, ker je nanje padlo globoko spanje od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Potem je David šel preko, na drugo stran in stal na vrhu oddaljenega hriba. Med njimi je bil velik prostor');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'in David je zaklical ljudstvu in Nerovemu sinu Abnêrju, rekoč: »Ne odgovarjaš, Abnêr?« Potem je Abnêr odgovoril in rekel: »Kdo si ti, ki kličeš h kralju?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'David je rekel Abnêrju: » Mar nisi ti hraber mož? In kdo je v Izraelu podoben tebi? Zakaj potem nisi varoval svojega gospoda kralja? Kajti tja je prišel nekdo izmed ljudstva, da uniči tvojega gospoda kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ta stvar, ki si jo storil, ni dobra. Kakor živi Gospod, vredni ste umreti, ker niste varovali svojega gospodarja, Gospodovega maziljenca. In sedaj poglej, kje je kraljeva sulica in vrč vode, ki je bil pri njegovem vzglavniku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Savel je prepoznal Davidov glas in rekel: » Ali je to tvoj glas, moj sin David?« David je rekel: » To je moj glas, moj gospod, oh kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Rekel je: »Zakaj moj gospod tako zasleduje svojega služabnika? Kaj sem storil? Ali kakšno zlo je v moji roki?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Zdaj te torej prosim, naj moj gospod kralj posluša besede svojega služabnika. Če te je Gospod razvnel zoper mene, naj sprejme daritev, toda če so to človeški otroci, naj bodo prekleti pred Gospodom, kajti danes so me pognali ven, pred ostajanjem v Gospodovi dediščini, rekoč: ›Pojdi, služi drugim bogovom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Zdaj naj torej moja kri ne pade na tla pred Gospodovim obrazom, kajti Izraelov kralj je prišel ven, da išče bolho, kakor ko nekdo lovi jerebico v gorah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Potem je Savel rekel: »Grešil sem. Vrni se, moj sin David, kajti ne bom ti več škodil, ker je bila ta dan moja duša dragocena v tvojih očeh. Glej igral sem bedaka in se silno motil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David je odgovoril in rekel: »Poglej kraljevo sulico! In naj nekdo izmed mladeničev pride čez ter jo vzame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Gospod [naj] vsakemu možu povrne njegovo pravičnost in njegovo zvestobo, kajti Gospod te je ta dan izročil v mojo roko, toda svoje roke nisem hotel iztegniti zoper Gospodovega maziljenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Glej, kakor je bilo tvoje življenje ta dan zelo cenjeno v mojih očeh, tako naj bo moje življenje zelo cenjeno v Gospodovih očeh in naj me osvobodi iz vse stiske.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Potem je Savel rekel Davidu: »Blagoslovljen bodi ti, moj sin David. Delal boš oboje, velike stvari in vendar boš tudi prevladal.« Tako je David odšel na svojo pot in Savel se je vrnil na svoj kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David je v svojem srcu rekel: »Sedaj bom nekega dne umrl po Savlovi roki. Zame ni nič boljšega, kakor da bi hitro pobegnil v deželo Filistejcev in Savel bo obupal nad menoj, da me še išče v kateremkoli območju Izraela. Tako bom pobegnil iz njegove roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David se je dvignil in šel preko s šeststo možmi, ki so bili z njim, k Ahíšu, Maóhovemu sinu, kralju Gata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'David je prebival z Ahíšem v Gatu, on in njegovi možje, vsak mož s svojo družino, David s svojima dvema ženama, Jezreélko Ahinóam in Karmelčanko Abigájilo, Nabálovo ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'To je bilo povedano Savlu, da je David pobegnil v Gat in ni ga več ponovno iskal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David je rekel Ahíšu: »Če sem torej našel milost v tvojih očeh, naj mi dajo prostor v nekem mestu v deželi, da bom tam lahko prebival, kajti zakaj bi tvoj služabnik prebival s teboj v kraljevem mestu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Potem mu je Ahíš ta dan izročil Ciklág. Zato Ciklág pripada Judovim kraljem do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Časa, ko je David prebival v deželi Filistejcev, je bil polno leto in štiri mesece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David in njegovi možje so odšli gor in vdrli h Gešuréjcem, Girzéjcem in Amalečanom, kajti ti narodi so bili od davnine prebivalci dežele, kakor greš v Šur, celo v egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'David je udaril deželo in ni pustil živega niti moškega niti ženske in odvedel ovce, vole, osle, kamele, obleke in se vrnil in prišel k Ahíšu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Ahíš je rekel: »Kam ste danes vpadli?« David je rekel: »Zoper južni Juda in zoper jug Jerahmeélovcev in zoper jug Kenéjcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'David ni rešil živega niti moškega niti ženske, da prinesejo novice v Gat, rekoč: »Da ne bi povedali o nas, rekoč: ›Tako je storil David in takšen bo njegov način, vse dokler on prebiva v deželi Filistejcev.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Ahíš je verjel Davidu, rekoč: »Svojemu ljudstvu Izraelu je storil, da ga popolnoma prezira, zato bo on moj služabnik na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Pripetilo se je v tistih dneh, da so Filistejci zbrali skupaj svojo vojsko za bojevanje, da se borijo z Izraelom. In Ahíš je rekel Davidu: »Zagotovo vedi, da boš šel z menoj ven v bitko, ti in tvoji možje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David je rekel Ahíšu: »Zagotovo boš vedel, kaj lahko tvoj služabnik stori.« Ahíš je rekel Davidu: »Zato te bom na veke naredil za varuha svoje glave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Torej Samuel je bil mrtev in ves Izrael ga je objokoval in pokopali so ga v Rami, celo v njegovem lastnem mestu. In Savel je iz dežele odstranil tiste, ki so imeli osebne duhove in čarovnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Filistejci so se zbrali skupaj in prišli ter se utaborili v Šunému, in Savel je zbral skupaj ves Izrael in utaborili so se v Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Ko je Savel videl vojsko Filistejcev, je bil prestrašen in njegovo srce je silno trepetalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Ko je Savel poizvedel od Gospoda, mu Gospod ni odgovoril, niti po sanjah, niti po urimu, niti po prerokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Potem je Savel rekel svojim služabnikom: »Poiščite mi žensko, ki ima osebnega duha, da lahko grem k njej in jo povprašam.« Njegov služabnik mu je rekel: »Glej, v En Doru je ženska, ki ima osebnega duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Savel se je preoblekel in si nadel drugo oblačilo in odšel ter dva moža z njim in ponoči so prišli k ženski. Rekel je: »Prosim te, vedežuj mi po osebnem duhu in katerega ti bom imenoval, mi ga privedi gor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Ženska mu je rekla: »Glej, ti veš, kaj je storil Savel, kako je iz dežele iztrebil tiste, ki imajo osebne duhove in čarovnike. Zakaj mi potem polagaš zanko za moje življenje, da mi povzročiš, da umrem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Savel ji je prisegel pri Gospodu, rekoč: » Kakor živi Gospod, se ti za to stvar ne bo pripetila nobena kazen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Potem je ženska rekla: »Koga naj privedem k tebi?« Rekel je: »Privedi mi gor Samuela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Ko je ženska zagledala Samuela, je zavpila z močnim glasom. Ženska je spregovorila Savlu, rekoč: »Zakaj si me zavedel? Kajti ti si Savel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Kralj ji je rekel: »Ne boj se, kajti kaj si videla?« Ženska je rekla Savlu: »Videla sem bogove vzpenjati se iz zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Rekel ji je: »Kakšne oblike je?« Rekla je: »Starec prihaja gor in pokrit je z ogrinjalom.« Savel je zaznal, da je bil to Samuel in se s svojim obrazom sklonil do tal in se priklonil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel je rekel Savlu: »Zakaj si me vznemiril, da me privedeš gor?« Savel je odgovoril: »Zelo sem zaskrbljen, kajti Filistejci se bojujejo zoper mene, Bog pa je odšel od mene in mi nič več ne odgovarja niti po prerokih niti po sanjah. Zato sem te poklical, da mi lahko daš vedeti, kaj naj storim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Potem je Samuel rekel: »Zakaj potem sprašuješ mene, glede na to, da je Gospod odšel od tebe in je postal tvoj sovražnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Gospod mu je storil, kakor je govoril po meni, kajti Gospod je iztrgal kraljestvo iz tvoje roke in ga dal tvojemu bližnjemu, torej Davidu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'ker ne ubogaš Gospodovega glasu niti ne izvršuješ njegovega krutega besa nad Amálekom, zato ti je Gospod ta dan storil to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Poleg tega bo Gospod tudi Izrael s teboj izročil v roko Filistejcev. Jutri boste ti in tvoji sinovi z menoj. Tudi izraelsko vojsko bo Gospod izročil v roko Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Potem je Savel takoj padel po vsej dolžini na zemljo in bil je boleče prestrašen zaradi Samuelovih besed in v njem ni bilo moči, kajti ves dan ni jedel kruha niti vso noč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Ženska je prišla k Savlu in videla, da je bil silno vznemirjen in mu rekla: »Glej, tvoja pomočnica je ubogala tvoj glas in svoje življenje sem položila v svojo roko in prisluhnila tvojim besedam, ki si mi jih spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Zdaj torej, prosim te, tudi ti prisluhni glasu svoje pomočnice in naj predte postavim grižljaj kruha in jej, da boš lahko imel moč, ko greš na svojo pot.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Vendar je odklonil in rekel: »Ne bom jedel.« Toda njegovi služabniki so ga, skupaj z žensko, primorali in prisluhnil je njihovemu glasu. Tako je vstal iz tal in sedel na posteljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Ženska je imela v hiši rejeno tele. Pohitela je, ga zaklala, vzela moko in jo zgnetla ter iz nje spekla nekvašen kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'In to je prinesla pred Savla in pred njegove služabnike in ti so jedli. Potem so vstali in tisto noč odšli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistejci so torej vse svoje vojske zbrali skupaj k Aféku, Izraelci pa so se utaborili pri studencu, ki je v Jezreélu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Knezi izmed Filistejcev so šli mimo po stotnijah in po tisočnijah, toda David in njegovi možje so šli mimo v zadnji straži z Ahíšem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Potem so princi Filistejcev rekli: »Kaj počnejo tukaj ti Hebrejci?« Ahíš je rekel princem Filistejcev: » Ali ni to David, služabnik Savla, Izraelovega kralja, ki je bil z menoj te dni ali ta leta in v njem nisem našel nobenega madeža, odkar je pripadel k meni, do tega dne?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Filistejski princi pa so bili ogorčeni nad njim in filistejski princi so mu rekli: »Primoraj tega pajdaša, da se vrne, da bo lahko ponovno šel na svoj kraj, ki si mu ga določil in naj ne gre z nami dol v bitko, da nam v bitki ne bi bil nasprotnik, kajti s čim se bo prikupil svojemu gospodarju? Ali naj to ne bi bilo z glavami teh ljudi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ali ni to David, o katerem so druga drugi pele v plesih, rekoč: »Savel je usmrtil svoje tisoče, David pa svoje deset tisoče?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Potem je Ahíš poklical Davida in mu rekel: »Zagotovo, kakor Gospod živi, si bil pošten in tvoje odhajanje in tvoje prihajanje z menoj v vojsko je dobro v mojem pogledu, kajti nisem našel zla v tebi od dneva tvojega prihoda k meni, do tega dne, pa vendar ti knezi niso naklonjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Zato se sedaj vrni in pojdi v miru, da ne razžališ filistejskih knezov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David je rekel Ahíšu: »Toda kaj sem storil? Kaj si našel na svojem služabniku, dokler sem bil s teboj, do tega dne, da se ne smem iti bojevat zoper sovražnike svojega gospoda kralja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Ahíš je odgovoril in Davidu rekel: »Vem, da si dober v mojih očeh, kakor Božji angel. Vendar so princi Filistejcev rekli: ›Ta ne bo šel z nami gor v bitko.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Zato sedaj vstani zgodaj zjutraj s služabniki svojega gospoda, ki so prišli s teboj in takoj, ko boste zgodaj zjutraj pokonci in imeli svetlobo, odidite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Tako so David in njegovi možje zgodaj zjutraj vstali, da odrinejo, da se vrnejo v deželo Filistejcev. Filistejci pa so šli gor k Jezreélu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Pripetilo se je, ko so David in njegovi možje na tretji dan prišli v Ciklág, da so Amalečani napadli jug in Ciklág in udarili Ciklág ter ga požgali z ognjem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'in ženske, ki so bile v njem, so zajeli [kot] ujetnice. Nobene niso usmrtili niti velike niti male, temveč so jih odvedli proč in odšli na svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Tako so David in njegovi možje prišli k mestu in glej, to je bilo požgano z ognjem. Njihove žene, njihovi sinovi in njihove hčere pa so bili zajeti [kot] ujetniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Potem so David in ljudstvo, ki je bilo z njim, povzdignili svoje glasove in jokali, dokler niso imeli več moči za jokanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'In dve Davidovi ženi sta bili zajeti [kot] ujetnici, Jezreélka Ahinóam in Abigájila, žena Karmelčana Nabála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'David je bil silno zaskrbljen, kajti ljudstvo je govorilo o njegovem kamnanju, ker so bile duše vseh ljudi užaloščene, vsak mož zaradi svojih sinov in zaradi svojih hčera, toda David se je ohrabril v Gospodu, svojem Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'David je duhovniku Abjatárju rekel: »Ahimélehov sin, prosim te, prinesi mi sèm efód.« In Abjatár je tja, k Davidu, prinesel efód.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'David je poizvedel pri Gospodu, rekoč: »Ali naj sledim za tem krdelom? Ali jih bom dohitel?« Odgovoril mu je: »Zasleduj, kajti zagotovo jih boš dohitel in čisto gotovo vse povrnil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Tako je David odšel, on in šeststo mož, ki so bili z njim in prišli so k potoku Besór, kjer so ostali tisti, ki so ostali zadaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Toda David je zasledoval, on in štiristo mož, kajti dvesto jih je ostalo zadaj, ki so bili tako slabotni, da niso mogli prečkati potoka Besór.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Na polju so našli Egipčana, ga privedli k Davidu, mu dali kruha in je jedel in primorali so ga piti vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dali so mu košček figove kepe in dva grozda rozin. Ko je pojedel, je njegov duh ponovno prišel k njemu, kajti tri dni in tri noči ni jedel nobenega kruha niti ni pil nobene vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David mu je rekel: »Komu pripadaš? In od kod si?« Rekel je: »Jaz sem mladenič iz Egipta, služabnik Amálečana in moj gospodar me je pustil, ker sem se pred tremi dnevi počutil bolnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Naredili smo invazijo nad jug Keretéjcev in nad območja, ki pripadajo Judu in nad jug Kaléba in Ciklág smo požgali z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David mu je rekel: »Ali me lahko privedeš dol k tej skupini?« Rekel je: »Prisezi mi pri Bogu, da me ne boš niti ubil niti me ne boš izročil rokam mojega gospodarja in jaz te bom odvedel dol k tej skupini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Ko ga je privedel dol, glej, bili so razširjeni nad vso zemljo, jedli, pili in plesali zaradi velikega plena, ki so ga vzeli iz filistejske dežele in iz Judove dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'David jih je udarjal od večerne polteme do naslednjega dne in niti mož izmed njih ni pobegnil razen štiristo mladeničev, ki so jahali na kamelah in pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'David je povrnil vse, kar so Amalečani odvedli proč in David je rešil svoji dve ženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Ničesar jim ni manjkalo, niti malega, niti velikega, niti sinov, niti hčera, niti plena, niti nobene stvari, ki so jim jih vzeli. Vse je David povrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David je vzel vse trope in črede, ki so jih gnali pred tisto drugo živino in rekli so: »To je Davidov plen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'David je prišel k dvestotim možem, ki so bili tako slabotni, da niso mogli slediti Davidu, ki so jih primorali, da ostanejo pri potoku Besórju in odšli so naprej, da srečajo Davida in da srečajo ljudstvo, ki je bilo z njim in ko se je David približal ljudstvu, jih je pozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Potem so odgovorili vsi zlobneži in Beliálovi možje izmed tistih, ki so odšli z Davidom in rekli: »Ker niso odšli z nami, jim ne bomo dali od plena, ki smo ga povrnili, razen vsakemu možu svojo ženo in svoje otroke, da jih bodo lahko odvedli proč in odšli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Potem je David rekel: »Ne boste tako storili, moji bratje, s tem, kar nam je Gospod dal, ki nas je zaščitil in v naše roke izročil skupino, ki je prišla zoper nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kajti kdo vam bo prisluhnil v tej zadevi? Temveč kakor je njegov del tistemu, ki gre dol v bitko, tako bo njegov del tistemu, ki ostane pri stvareh. Enako si bosta razdelila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'In tako je bilo od tega dne naprej, da je to naredil [za] zakon in odredbo za Izraela do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Ko je David prišel v Ciklág, je od plena poslal Judovim starešinam, torej svojim prijateljem, rekoč: »Glejte darilo za vas od plena Gospodovih sovražnikov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'tistim, ki so bili v Betelu in tistim, ki so bili v južnem Ramátu in tistim, ki so bili v Jatírju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'in tistim, ki so bili v Aroêrju in tistim, ki so bili v Sifmótu in tistim, ki so bili v Eštemói');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'in tistim, ki so bili v Rahálu in tistim, ki so bili v mestih Jerahmeélovcev in tistim, ki so bili v mestih Kenéjcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'in tistim, ki so bili v Hormi in tistim, ki so bili v Bor Ašánu in tistim, ki so bili v Atáhu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'in tistim, ki so bili v Hebrónu in k vsem krajem, kjer so se bili sam David in njegovi možje vajeni preganjati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Torej Filistejci so se borili zoper Izrael in Izraelci so pobegnili pred Filistejci in padli dol, umorjeni na gori Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Filistejci so tesno sledili Savlu in njegovim sinovom in Filistejci so usmrtili Jonatana, Abinadába in Malkišúa, Savlove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Bitka je postala huda zoper Savla in lokostrelci so ga zadeli; in bil je hudo ranjen od lokostrelcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Potem je Savel rekel svojemu nosilcu bojne opreme: »Izvleci svoj meč in me prebodi z njim; da ne bi prišli ti neobrezanci in me prebodli in me zlorabili.« Vendar njegov nosilec bojne opreme ni hotel, kajti bil je hudo prestrašen. Zato je Savel vzel meč in padel nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Ko je njegov nosilec bojne opreme videl, da je bil Savel mrtev, je tudi sam prav tako padel na svoj meč in umrl z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tako so ta isti dan skupaj umrli Savel, njegovi trije sinovi, njegov nosilec bojne opreme in vsi njegovi možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Ko so Izraelovi možje, ki so bili na drugi strani doline in tisti, ki so bili na drugi strani Jordana, videli, da so Izraelovi možje pobegnili in da so bili Savel in njegovi sinovi mrtvi, so zapustili mesta in pobegnili in Filistejci so prišli ter prebivali v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Pripetilo se je naslednji dan, ko so prišli Filistejci, da oropajo umorjene, da so našli Savla in njegove tri sinove padle na gori Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Odsekali so njegovo glavo, slekli njegovo bojno opremo in poslali naokoli, v deželo Filistejcev, da to razglasijo v hiši njihovih malikov in med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Njegovo bojno opremo so položili v hišo Astarte. Njegovo telo pa so pritrdili na obzidje Bet Šeána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Ko so prebivalci Jabéš Gileáda slišali o tem, kar so Filistejci storili Savlu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'so se vsi hrabri možje vzdignili in hodili vso noč in vzeli Savlovo telo in telesa njegovih sinov z obzidja Bet Šeána in prišli v Jabéš ter jih tam sežgali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'In vzeli so njihove kosti in jih pokopali pod drevesom pri Jabéšu in se postili sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Pripetilo se je torej, po Savlovi smrti, ko se je David vrnil iz pokola Amalečanov in je David dva dni prebival v Ciklágu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'in tretji dan se je zgodilo celo, da je, glej, mož prišel iz tabora od Savla s svojimi pretrganimi oblačili in zemlja je bila na njegovi glavi. In bilo je tako, ko je prišel k Davidu, da je padel k tlom in se globoko priklonil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David mu je rekel: »Od kod prihajaš?« Rekel mu je: »Pobegnil sem iz tabora Izraelcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David mu je rekel: »Kako je šla zadeva? Prosim te, povej mi.« Odgovoril je: »Da je ljudstvo pobegnilo iz bitke in tudi številni izmed ljudstva so padli in so mrtvi in tudi Savel in njegov sin Jonatan sta mrtva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David je rekel mladeniču, ki mu je povedal: »Kako veš, da sta Savel in njegov sin Jonatan mrtva?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Mladenič, ki mu je povedal, je rekel: »Kakor sem se naključno znašel na gori Gilbói, glej, Savel se je naslanjal na svojo sulico in glej, bojni vozovi in konjeniki so tesno sledili za njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Ko je pogledal za seboj, me je videl in me poklical k sebi. Odgovoril sem: »Tukaj sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Rekel mi je: »Kdo si?« Odgovoril sem mu: »Amálečan sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Ponovno mi je rekel: »Stoj, prosim te, nad menoj in me ubij, kajti tesnoba je prišla nadme, ker je moje življenje še celo v meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Tako sem stopil k njemu in ga usmrtil, ker sem bil prepričan, da potem, ko je padel, ne bi mogel živeti in vzel sem krono, ki je bila na njegovi glavi ter zapestnico, ki je bila na njegovem laktu ter ju prinesel sèm k svojemu gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Potem je David prijel svoja oblačila in jih raztrgal in prav tako vsi možje, ki so bili z njim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'in žalovali so, jokali in se do večera postili za Savlom in za njegovim sinom Jonatanom in za Gospodovim ljudstvom in za Izraelovo hišo, ker so padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'David je rekel mladeniču, ki mu je povedal: »Od kod si?« Odgovoril je: »Jaz sem sin tujca, Amálečana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David mu je rekel: »Kako se nisi bal iztegniti svoje roke, da uničiš Gospodovega maziljenca?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'David je poklical enega izmed mladeničev ter rekel: »Približaj se in padi nanj.« In ta ga je udaril, da je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'David mu je rekel: »Tvoja kri bodi na tvoji glavi, kajti tvoja usta so pričala zoper tebe, rekoč: ›Umoril sem Gospodovega maziljenca.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'David je s tem žalovanjem žaloval nad Savlom in nad njegovim sinom Jonatanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(Prav tako je zaukazal, naj Judove otroke učijo uporabo loka. Glej, to je napisano v Jasherjevi knjigi.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '»Izraelova lepota je umorjena na tvojih visokih krajih. Kako so padli mogočni!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne povejte tega v Gatu, ne razglašajte tega na Aškelónskih ulicah, da se ne bi filistejske hčere veselile, da ne bi hčere neobrezancev slavile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ve gore Gilbóe, naj tam ne bo nobene rose niti naj tam ne bo dežja nad vami niti nobenih polj za darovanja, kajti ščit mogočnega je podlo odvržen, Savlov ščit, kakor če ne bi bil maziljen z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Od krvi pobitih, od maščobe mogočnih, se Jonatanov lok ni obrnil nazaj in Savlov meč se ni vrnil prazen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Savel in Jonatan sta bila očarljiva in prijetna v svojih življenjih in v svoji smrti nista bila ločena. Hitrejša sta bila kakor orli, močnejša sta bila kakor levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Ve hčere izraelske, jokajte nad Savlom, ki vas je oblekel v škrlat, z drugimi nasladami, ki je na vaše obleke nadel ornamente iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kako so mogočni padli v sredi bitke! Oh Jonatan, umorjen si bil na svojih visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Žalosten sem zaradi tebe, moj brat Jonatan. Zelo prijeten si mi bil. Tvoja ljubezen do mene je bila čudovita, presegajoča ljubezen žensk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kako so mogočni padli in so uničena bojna orožja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Pripetilo se je po tem, da je David poizvedel od Gospoda, rekoč: »Ali naj grem gor v katerokoli izmed Judovih mest?« Gospod mu je rekel: »Pojdi gor.« David mu je rekel: »Kam naj grem gor?« Rekel je: »V Hebrón.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Tako je David odšel tja gor in tudi dve njegovi ženi: Jezreélka Ahinóam in Abigájila, žena Karmélčana Nabála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Njegove može, ki so bili z njim, je David privedel gor, vsakega moža s svojo družino in prebivali so v mestih Hebróna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Možje iz Juda so prišli in tam mazilili Davida [za] kralja nad Judovo hišo. In povedali so Davidu, rekoč: » Da so bili možje iz Jabéš Gileáda tisti, ki so pokopali Savla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'David je poslal poslance k ljudem iz Jabéš Gileáda ter jim rekel: »Blagoslovljeni bodite od Gospoda, da ste izkazali to prijaznost našemu gospodu Savlu in ga pokopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Sedaj naj vam Gospod izkaže prijaznost in resnico in tudi jaz vam bom poplačal to prijaznost, ker ste storili to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Zato naj bodo sedaj vaše roke okrepljene in bodite hrabri, kajti vaš gospodar Savel je mrtev in tudi Judova hiša me je mazilila [za] kralja nad seboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Toda Nerov sin Abnêr, poveljnik Savlove vojske, je vzel Savlovega sina Iš Bošeta, in ga privedel preko, v Mahanájim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'in ga postavil [za] kralja nad Gileádom, nad Ašhúrci, nad Jezreélom, nad Efrájimom, nad Benjaminom in nad vsem Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Savlov sin Iš Bošet je bil star štirideset let, ko je začel kraljevati nad Izraelom in kraljeval je dve leti. Toda Judova hiša je sledila Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'In časa, ko je bil David kralj v Hebrónu, nad Judovo hišo, je bilo sedem let in šest mesecev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'In Nerov sin Abnêr in služabniki Savlovega sina Iš Bošeta so iz Mahanájima odšli v Gibeón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'In Cerújin sin Joáb in Davidovi služabniki so odšli ven in se srečali pri Gibeónskem ribniku in se usedli, eni na eni strani ribnika, drugi pa na drugi strani ribnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Abnêr je rekel Joábu: »Naj mladeniči sedaj vstanejo in igrajo pred nami.« Joáb je rekel: »Naj vstanejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Potem so se tam vzdignili in odšli čez, po številu dvanajst iz Benjamina, ki je pripadal Iš Bošetovemu sinu Savlu in dvanajst izmed Davidovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Vsak je zgrabil drugega za glavo in svoj meč porinil v njegovo stran. Tako so skupaj padli dol, zato je bil ta kraj imenovan Helkat-hazurim, ki je v Gibeónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Tam je bila ta dan zelo huda bitka in Abnêr je bil poražen in Izraelovi možje, pred Davidovimi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Bili so trije Cerújini sinovi: Joáb, Abišáj in Asaél. Asaél je bil kakor svetloba stopala, kakor divja srna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Asaél je zasledoval Abnêrja in ko je šel, se ni obrnil ne k desni roki niti ne k levi od zasledovanja Abnêrja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Potem je Abnêr pogledal za seboj in rekel: » Ali si ti Asaél?« Odgovoril je: »Jaz sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abnêr mu je rekel: »Obrni se vstran k svoji desni roki ali k svoji levi in primi enega izmed mladeničev in si vzemi njegovo bojno opremo.« Toda Asaél se ni hotel obrniti od sledenja za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abnêr je ponovno rekel Asaélu: »Obrni se stran od sledenja za menoj. Zakaj bi te udaril k tlom? Kako bi potem svoj obraz dvignil k tvojemu bratu Joábu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Vendar je ta odklonil, da se obrne vstran. Zato ga je Abnêr z zadnjim delom sulice udaril pod petim rebrom, da je sulica pogledala ven za njim; in tam je padel dol in umrl na istem kraju. Pripetilo se je, da kolikor jih je prišlo na kraj, kjer je Asaél padel dol in umrl, da so mirno stali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Tudi Joáb in Abišáj sta zasledovala Abnêrja. Sonce je zašlo, ko sta prišla k hribu Ame, ki leži pred Giahom, ob poti Gibeónske divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Benjaminovi otroci so se zbrali skupaj za Abnêrjem in postali eno krdelo in stali na vrhu hriba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Potem je Abnêr zaklical Joábu in rekel: »Mar bo meč požiral na veke? Ali ne veš, da bo v zadnjem koncu to grenkoba? Doklej bo torej, preden boš svojemu ljudstvu naročil, naj se vrne od zasledovanja svojih bratov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joáb je rekel: » Kakor živi Bog, če ne bi spregovoril, bi potem zjutraj ljudstvo zagotovo odšlo gor, vsakdo od sledenja svojemu bratu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Tako je Joáb zatrobil na šofar in vse ljudstvo je mirno stalo in ni več zasledovalo Izraela niti se niso več bojevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abnêr in njegovi možje so vso to noč hodili skozi ravnino in prečkali Jordan in šli skozi ves Bitrón in prišli do Mahanájima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joáb se je vrnil od zasledovanja Abnêrja in ko je vse ljudstvo zbral skupaj, je od Davidovih služabnikov manjkalo devetnajst mož in Asaél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Toda Davidovi služabniki so udarili Benjaminove in Abnêrjeve može, tako da je umrlo tristo šestdeset mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Pobrali so Asaéla in ga pokopali v mavzoleju njegovega očeta, ki je bil v Betlehemu. Joáb in njegovi možje pa so vso noč hodili ter ob svitu prišli v Hebrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Torej tam je bila dolga vojna med Savlovo hišo in Davidovo hišo, toda David je postajal močnejši in močnejši, Savlova hiša pa je postajala šibkejša in šibkejša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Davidu so se v Hebrónu rodili sinovi. Njegov prvorojenec je bil Amnón; od Jezreélke Ahinóam;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'in njegov drugi Kiláb od Abigájile, žene Karmelčana Nabála in tretji Absalom, sin Maáhe, hčere gešurskega kralja Talmája;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'in četrti Adoníja, Hagítin sin; in peti Šefatjá, sin Abitále;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'in šesti Jitreám od Davidove žene Egle. Ti so bili rojeni Davidu v Hebrónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Pripetilo se je, medtem ko je bila vojna med Savlovo hišo in Davidovo hišo, da je Abnêr sebe naredil močnega za Savlovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Savel je imel priležnico, ki ji je bilo ime Ricpa, Ajájeva hči in Iš Bošet je rekel Abnêrju: »Zakaj si odšel k priležnici mojega očeta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Potem je bil Abnêr zelo ogorčen zaradi besed Iš Bošeta in je rekel: » Mar sem pasja glava, ko ta dan zoper Juda izkazujem prijaznost hiši tvojega očeta Savla, njegovim bratom in njegovim prijateljem in te nisem izročil v Davidovo roko, da me danes obsojaš s krivdo glede te ženske?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Tako stori Bog Abnêrju in še več, razen če, kakor je Gospod prisegel Davidu, celo tako jaz storim njemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'da se kraljestvo prestavi od Savlove hiše in da postavi Davidov prestol čez Izraela in čez Juda, od Dana, celo do Beeršébe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'In ni mogel Abnêrju ponovno odgovoriti besede, ker se ga je bal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Abnêr pa je v svojem imenu poslal poslance k Davidu, rekoč: »Čigava je ta dežela?« Rekoč tudi: »Skleni zavezo z menoj in glej, moja roka bo s teboj, da k tebi privedem ves Izrael.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Rekel je: »Dobro. Jaz bom sklenil zavezo s teboj, toda od tebe zahtevam eno stvar, to je: ›Ne boš videl mojega obraza, razen če mi najprej ne pripelješ Savlove hčere Mihále, ko prideš, da vidiš moj obraz.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'David je poslal poslance k Savlovemu sinu Iš Bošetu, rekoč: »Izroči mi mojo ženo Mihálo, ki sem si jo zaročil za sto prednjih kožic Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Iš Bošet je poslal in jo vzel od njenega soproga, torej od Lajiševega sina Paltíela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Njen soprog je odšel skupaj z njo, jokajoč za njo, do Bahuríma. Potem mu je Abnêr rekel: »Pojdi, vrni se.« In se je vrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abnêr je imel pogovor z Izraelovimi starešinami, rekoč: »V preteklih časih ste iskali za Davidom, da bi bil kralj nad vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Sedaj torej to storite, kajti Gospod je govoril o Davidu, rekoč: ›Po roki svojega služabnika Davida bom rešil svoje ljudstvo Izraela iz roke Filistejcev in iz roke vseh njihovih sovražnikov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abnêr je govoril tudi na ušesa Benjamina in Abnêr je odšel, da govori tudi na Davidova ušesa v Hebrónu. Vse to se je zdelo dobro Izraelu in to se je zdelo dobro celotni Benjaminovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Tako je Abnêr prišel k Davidu v Hebrón in z njim dvajset mož. David je naredil zabavo za Abnêrja in može, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abnêr je rekel Davidu: »Vstal bom in šel in ves Izrael bom zbral k svojemu gospodu kralju, da bodo lahko s teboj sklenili zavezo in da boš lahko kraljeval nad vsem, kar si tvoje srce želi.« David je poslal Abnêrja proč in ta je odšel v miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Glej, Davidovi služabniki in Joáb so prišli iz zasledovanja krdela in s seboj prinesli velik plen, toda Abnêr ni bil z Davidom v Hebrónu, kajti poslal ga je proč in ta je odšel v miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Ko so prišli Joáb in vsa vojska, ki je bila z njim, so Joábu povedali, rekoč: »Nerov sin Abnêr je prišel h kralju in ta ga je poslal proč in je odšel v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Potem je Joáb prišel h kralju in rekel: »Kaj si storil? Glej, Abnêr je prišel k tebi. Zakaj je to, da si ga poslal proč in je on popolnoma izginil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Ti poznaš Nerovega sina Abnêrja, da je prišel, da te zavede in da spozna tvoja odhajanja in tvoja prihajanja in da spozna vse, kar delaš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Ko je Joáb prišel od Davida, je za Abnêrjem poslal poslance, ki so ga ponovno privedli od vodnjaka Sire. Toda David tega ni vedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Ko se je Abnêr vrnil v Hebrón, ga je Joáb vzel na stran, v velika vrata, da bi tiho govoril z njim in ga tam udaril pod petim rebrom, da je umrl zaradi krvi njegovega brata Asaéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Potem ko je David to slišal, je rekel: »Jaz in moje kraljestvo sva brez krivde pred Gospodom na veke pred krvjo Nerovega sina Abnêrja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Ta naj počiva na Joábovi glavi in na vsej hiši njegovega očeta in naj iz Joábove hiše ne zmanjka tistega, ki ima izliv ali je gobavec ali se naslanja na palico ali pada na meč ali mu primanjkuje kruha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Tako sta Joáb in njegov brat Abišáj umorila Abnêrja, ker je ubil njunega brata Asaéla v bitki pri Gibeónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'David je rekel Joábu in vsemu ljudstvu, ki je bilo z njim: »Pretrgajte svoja oblačila in se opašite z vrečevino in žalujte pred Abnêrjem.« In sam kralj David je sledil mrtvaškemu odru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Abnêrja so pokopali v Hebrónu. Kralj je povzdignil svoj glas in jokal nad Abnêrjevim grobom in vse ljudstvo je jokalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Kralj je žaloval nad Abnêrjem in rekel: »Je Abnêr umrl, kakor umira bedak?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tvoje roke niso bile zvezane niti tvoja stopala, vklenjena v okove. Kakor mož pada pred zlobneži, tako padaš ti.« In vse ljudstvo je ponovno jokalo nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Ko je vse ljudstvo prišlo, da povzročijo Davidu, da jé hrano, medtem ko je bil še dan, je David prisegel, rekoč: »Tako naj mi Bog stori in še več, če okusim kruh ali karkoli drugega, dokler sonce ne zaide.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Vse ljudstvo je to opazilo in to jim je ugajalo, kakor karkoli je kralj storil, je vsemu ljudstvu ugajalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Kajti vse ljudstvo in ves Izrael je ta dan razumelo, da to ni bilo od kralja, da umori Nerovega sina Abnêrja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Kralj je rekel svojim služabnikom: »Ali ne veste, da je ta dan tukaj v Izraelu padel princ in velik mož?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Jaz sem ta dan šibek, čeprav maziljen kralj in ti možje, Cerújini sinovi, so pretežki zame. Gospod bo hudodelca nagradil glede na njegovo zlobnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Ko je Savlov sin slišal, da je bil Abnêr mrtev v Hebrónu, so bile njegove roke slabotne in vsi Izraelci so bili zaskrbljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Savlov sin je imel dva moža, ki sta bila poveljnika čet. Ime enega je bilo Baaná in ime drugega Reháb, sinova Rimóna, Beeróčana, izmed Benjaminovih otrok (kajti tudi Beerót je bil štet k Benjaminu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'in Beeróčani so pobegnili v Gitájim in bili tam začasni prebivalci do tega dne.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Savlov sin Jonatan je imel sina, ki je bil hrom od svojih stopal. Pet let je bil star, ko so prišle iz Jezreéla novice o Savlu in Jonatanu in njegova dojilja ga je vzela in pobegnila. Pripetilo pa se je, medtem ko je hitela, da pobegne, da je padel in postal hrom. Njegovo ime je bilo Mefibóšet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Sinova Beeróčana Rimóna, Reháb in Baaná sta odšla in prišla okoli dnevne vročine v hišo Iš Bošeta, ki je opoldan ležal na postelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Prišla sta tja, v sredo hiše, kakor bi hotela vzeti pšenico. Udarila sta ga pod peto rebro in Reháb in njegov brat Baaná sta pobegnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Kajti ko sta prišla v hišo, je ležal na svoji postelji, v svoji spalnici in udarila sta ga in ga usmrtila in obglavila in vzela njegovo glavo in vso noč bežala čez ravnino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Glavo Iš Bošeta sta prinesla k Davidu v Hebrón in rekla kralju: »Glej, glava Savlovega sina Iš Bošeta, tvojega sovražnika, ki je iskal tvoje življenje in Gospod je ta dan maščeval mojega gospoda kralja nad Savlom in njegovim semenom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'David pa je odgovoril Rehábu in njegovemu bratu Baanáju, sinovoma Beeróčana Rimóna ter jima rekel: » Kakor živi Gospod, ki je mojo dušo odkupil od vseh nasprotnikov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'ko mi je nekdo povedal, rekoč: ›Glej, Savel je mrtev,‹ misleč, da je prinesel dobre novice, sem ga prijel in ga usmrtil v Ciklágu. Mislil je, da mu bom dal nagrado za njegove novice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Koliko mnogo bolj, ko sta zlobneža umorila pravično osebo v njegovi lastni hiši, na njegovi postelji? Mar ne bom torej sedaj zahteval njegovo kri iz vajine roke in vaju vzel proč z zemlje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'David je svojim mladeničem zapovedal in so ju ubili ter odsekali njuni roki in njuna stopala in ju obesili gor nad ribnik v Hebrónu. Toda vzeli so glavo Iš Bošeta in jo pokopali v Abnêrjevem mavzoleju v Hebrónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Potem so vsi Izraelovi rodovi prišli k Davidu v Hebrón in spregovorili, rekoč: »Glej, mi smo tvoja kost in tvoje meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Tudi v preteklem času, ko je bil Savel kralj nad nami, si bil ti tisti, ki nas je vodil ven in privedel v Izrael in Gospod ti je rekel: ›Ti boš pasel moje ljudstvo Izrael in ti boš poveljnik nad Izraelom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tako so vsi Izraelovi starešine prišli h kralju v Hebrón in kralj David je z njimi v Hebrónu sklenil zavezo pred Gospodom in Davida so mazilili [za] kralja nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David je bil star trideset let, ko je začel kraljevati in kraljeval je štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'V Hebrónu je nad Judom kraljeval sedem let in šest mesecev, v Jeruzalemu pa je triintrideset let kraljeval nad vsem Izraelom in Judom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, '§ Kralj in njegovi možje so odšli v Jeruzalem k Jebusejcem, prebivalcem dežele, ki so Davidu spregovorili, rekoč: »Razen če ne odstraniš slepih in hromih, ne boš vstopil sèm,« misleč, [da] David ne more priti tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Kljub temu je David zavzel oporišče Sion. Isto je Davidovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'David je na ta dan rekel: »Kdorkoli se spravi gor do jarka in udari Jebusejce in hrome in slepe, ki jih Davidova duša sovraži, ta bo voditelj in poveljnik.« Zatorej so rekli: »Slepi in hromi ne bodo prišli v hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Tako je David prebival v utrdbi in jo imenoval Davidovo mesto. In David je gradil naokoli od Milója in znotraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'David je odšel naprej in postal velik in Gospod, Bog nad bojevniki, je bil z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Tirski kralj Hirám je poslal poslance k Davidu in cedrova drevesa, tesarje in zidarje in ti so Davidu zgradili hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'David je zaznal, da ga je Gospod utrdil za kralja nad Izraelom in da je njegovo kraljestvo povišal zaradi svojega ljudstva Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'In David si je vzel [še] več priležnic in žená iz Jeruzalema, potem ko je prišel iz Hebróna in tam so se Davidu rodili še sinovi in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'To so imena izmed tistih, ki so mu bili rojeni v Jeruzalemu: Šamúa, Šobáb, Natán, Salomon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'tudi Jibhár, Elišúa, Nefeg, Jafíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elišamá, Eljadá in Elifálet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Toda ko so Filistejci slišali, da so Davida mazilili [za] kralja nad Izraelom, so vsi Filistejci prišli gor, da poiščejo Davida in David je slišal o tem in odšel dol k utrjenemu kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Tudi Filistejci so prišli in se razkropili v dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'David je poizvedel od Gospoda, rekoč: »Naj grem gor k Filistejcem? Jih boš izročil v mojo roko?« Gospod je rekel Davidu: »Pojdi gor, kajti nedvomno bom Filistejce izročil v tvojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'David je prišel do Báal Peracíma in David jih je tam udaril ter rekel: » Gospod je kakor prodor vodá izbruhnil na moje sovražnike pred menoj.« Zato je ime tega kraja imenoval Báal Peracím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, '§ In oni so tam pustili svoje podobe, David in njegovi možje pa so jih sežgali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'In Filistejci so ponovno prišli gor in se razkropili v dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Ko je David poizvedel od Gospoda, je rekel: »Ne boš šel gor, temveč za njimi postavi zasedo in pridi nadnje nasproti murvinim drevesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'In naj bo, ko zaslišiš šum hoje v vrhu murvinih dreves, da se boš potem podvizal, kajti takrat bo Gospod šel ven pred teboj, da udari vojsko Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David je storil tako, kakor mu je Gospod zapovedal in udarjal Filistejce od Gebe, dokler ne prideš do Gazerja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'David je ponovno zbral skupaj vse izbrane može iz Izraela, trideset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'In David je vstal in z vsem ljudstvom, ki je bilo z njim, odšel od Baále Judove, da od tam prinese gor Božjo skrinjo, katere ime je imenovano po imenu Gospoda nad bojevniki, ki prebiva med kerubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Božjo skrinjo so postavili na nov voz in jo privedli iz Abinadábove hiše, ki je bila v Gíbei. Abinadábova sinova Uzá in Ahjó pa sta gnala nov voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Prinesli so jo iz Abinadábove hiše, ki je bila v Gíbei, spremljajoč Božjo skrinjo in Ahjó je šel pred skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David in vsa Izraelova hiša pa so igrali pred Gospodom na vse vrste glasbil, narejenih iz cipresovega lesa, celo na harfe, na plunke, na tamburine, na kornéte in na cimbale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'In ko so prišli do Nahónovega mlatišča, je Uzá iztegnil svojo roko k Božji skrinji in jo prijel, kajti voli so jo tresli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Gospodova jeza je bila vžgana zoper Uzája in Bog ga je tam udaril zaradi njegove napake; in tam je umrl, ob Božji skrinji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'David je bil razžaljen, ker je Gospod naredil vrzel nad Uzájem, in ime tega mesta je imenoval Perec Uzá do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'David se je tisti dan zbal Gospoda in rekel: »Kako bo Gospodova skrinja prišla k meni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Tako David Gospodove skrinje ni hotel prestaviti k sebi v Davidovo mesto, temveč jo je David odvedel vstran, v hišo Gitéjca Obéd Edóma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'In Gospodova skrinja je tri mesece ostala v hiši Gitéjca Obéd Edóma in Gospod je blagoslovil Obéd Edóma in vso njegovo družino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'To je bilo sporočeno kralju Davidu, rekoč: » Gospod je zaradi Božje skrinje blagoslovil hišo Obéd Edóma in vse, kar mu pripada.« Tako je David šel in z veseljem prinesel gor Božjo skrinjo iz hiše Obéd Edóma v Davidovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'In bilo je tako, da ko so tisti, ki so nosili Gospodovo skrinjo, naredili šest korakov, je žrtvoval vole in pitance.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'David je z vso svojo močjo plesal pred Gospodom in David je bil opasan z lanenim efódom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tako so David in vsa Izraelova hiša z vriskanjem in z zvokom šofarja Gospodovo skrinjo prinesli gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Ko je Gospodova skrinja prišla v Davidovo mesto, je Savlova hči Mihála pogledala skozi okno in videla kralja Davida skakati in plesati pred Gospodom in ga prezirala v svojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'In prinesli so Gospodovo skrinjo in jo postavili na njen kraj, v sredo šotorskega svetišča, ki ga je David razpel zanjo in David je pred Gospodom daroval žgalne daritve in mirovne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Takoj, ko je David prenehal darovati žgalne daritve in mirovne daritve, je v imenu Gospoda nad bojevniki blagoslovil ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Med vse ljudstvo je razdelil, celó med celotno Izraelovo množico, tako ženskam kakor moškim, vsakomur kolač kruha, dober kos mesa in flaškon vina. Tako je vse ljudstvo odšlo vsak k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Potem se je David vrnil, da blagoslovi svojo družino. Savlova hči Mihála pa je prišla ven, da sreča Davida in rekla: »Kako veličasten je bil danes Izraelov kralj, ki se je danes razkril pred očmi pomočnic svojih služabnikov, kakor se brezsramno razkriva nekdo izmed nadutih pajdašev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'David je rekel Miháli: » To je bilo pred Gospodom, ki me je izbral pred tvojim očetom in pred vso njegovo hišo, da me določi [za] vladarja nad Gospodovim ljudstvom, nad Izraelom. Zato bom igral pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'In še bolj se bom pomanjšal kakor to in bom ponižen v svojem lastnem pogledu. Glede dekel pa, o katerih si govorila, od njih bom imel spoštovanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Zato Savlova hči Mihála ni imela nobenega otroka do dneva svoje smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Pripetilo se je, ko je kralj sedel v svoji hiši in mu je vsenaokrog Gospod dal počitek, od vseh njegovih sovražnikov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'da je kralj rekel preroku Natánu: »Poglej torej, jaz prebivam v cedrovi hiši, toda Božja skrinja prebiva znotraj zaves.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Natán je rekel kralju: »Pojdi, stori vse, kar je v tvojem srcu, kajti Gospod je s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'To noč pa se je pripetilo, da je beseda od Gospoda prišla Natánu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '»Pojdi in povej mojemu služabniku Davidu: ›Tako govori Gospod: ›Mar mi boš zgradil hišo, da prebivam v njej?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Medtem ko nisem prebival v katerikoli hiši od časa, ko sem Izraelove otroke privedel iz Egipta, celo do tega dne, temveč sem hodil v šotoru in v šotorskem svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Na vseh krajih, kjer sem hodil z vsemi Izraelovimi otroki, sem mar govoril besedo s katerimkoli izmed Izraelovih rodov, ki sem jim zapovedal, naj pasejo moje ljudstvo Izraela, rekoč: ›Zakaj mi ne zgradite cedrove hiše?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Sedaj boš torej tako rekel mojemu služabniku Davidu: ›Tako govori Gospod nad bojevniki: ›Vzel sem te iz ovčje staje, od sledenja za ovcami, da bi bil vladar nad mojim ljudstvom, nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'In bil sem s teboj kamorkoli si šel in odsekal sem vse tvoje sovražnike izpred tvojega pogleda in naredil sem ti veliko ime, podobno imenu velikih mož, ki so na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Poleg tega bom določil kraj za svoje ljudstvo Izrael in jih zasadil, da bodo lahko prebivali na svojem lastnem kraju in se ne bodo več selili; niti jih otroci zlobnosti ne bodo več stiskali kakor poprej');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'in kot že od časa, ko sem sodnikom zapovedal, naj bodo nad mojim ljudstvom Izraelom in sem ti dal, da počivaš pred vsemi svojimi sovražniki.‹ In Gospod ti tudi govori, da ti bo naredil hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Ko bodo tvoji dnevi izpolnjeni in boš zaspal s svojimi očeti, bom postavil tvoje seme za teboj, ki bo izšlo iz tvoje notranjosti in jaz bom osnoval njegovo kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On bo zgradil hišo mojemu imenu in jaz bom na veke osnoval prestol njegovega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Jaz bom njegov oče in on bo moj sin. Če stori krivičnost, ga bom karal s človeško šibo in z udarci človeških otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'toda moje usmiljenje ne bo odšlo proč od njega, kakor sem ga vzel od Savla, ki sem ga odstranil pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Tvoja hiša in tvoje kraljestvo bo pred teboj osnovano na veke. Tvoj prestol bo osnovan na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Glede na vse te besede in glede na vse to videnje, tako je Natán govoril Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Potem je vstopil kralj David in se usedel pred Gospodom ter rekel: »Kdo sem jaz, oh Gospod Bog? In kaj je moja hiša, da si me privedel do tu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'In to je bila še majhna stvar v tvojem pogledu, oh Gospod Bog, toda govoril si tudi o hiši tvojega služabnika za oddaljeni čas, ki pride. Ali je to človeški način, oh Gospod Bog?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Kaj ti še lahko reče David? Kajti ti, Gospod Bog, poznaš svojega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Zaradi svojih besed in glede na svoje lastno srce si storil vse te velike stvari, da pripraviš svojega služabnika, da jih pozna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Zakaj ti si velik, oh Gospod Bog, kajti nikogar ni podobnega tebi niti ni nobenega Boga poleg tebe, glede na vse, kar smo slišali z svojimi ušesi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'In kateri narod na zemlji je podoben tvojemu ljudstvu, celó podoben Izraelu, ki ga je Bog odšel odkupit za svoje ljudstvo in da mu naredi ime in da za vas stori velike stvari in strašne, za tvojo deželo, pred tvojim ljudstvom, ki si ga iz Egipta odkupil k sebi, pred narodi in njihovimi bogovi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Kajti ti si si potrdil svoje ljudstvo Izrael, da ti bo ljudstvo na veke, in ti, Gospod, si postal njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Sedaj, oh Gospod Bog, beseda, ki si jo spregovoril glede svojega služabnika in glede svoje hiše, utrdi jo na veke in stôri, kakor si rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Tvoje ime naj bo poveličano na veke, rekoč: › Gospod nad bojevniki je Bog nad Izraelom in hiša tvojega služabnika Davida naj bo osnovana pred teboj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Kajti ti, oh Gospod nad bojevniki, Izraelov Bog, si razodel svojemu služabniku, rekoč: ›Zgradil ti bom hišo.‹ Zato je tvoj služabnik odkril v svojem srcu, da k tebi moli to molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'In sedaj, oh Gospod Bog, ti si ta Bog in tvoje besede so resnične in svojemu služabniku si obljubil to dobroto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'zato naj ti sedaj ugaja, da blagosloviš hišo svojega služabnika, da bo ta lahko na veke trajala pred teboj, kajti ti, oh Gospod Bog, si to govoril in s tvojim blagoslovom naj bo hiša tvojega služabnika blagoslovljena na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Po tem se je pripetilo, da je David udaril Filistejce in jih podjarmil. David je vzel Meteg–amo iz roke Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Udaril je Moábce in jih premeril z vrvico, [medtem ko] jih je vrgel na tla. Celo z dvema vrvicama je premeril, da jih usmrti in z eno polno vrvico, da jih ohrani žive. Tako so Moábci postali Davidovi služabniki in prinašali darila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David je udaril tudi Rehóbovega sina Hadadézerja, kralja iz Cobe, ko je odšel, da obnovi svojo mejo pri reki Evfratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David je od njega vzel tisoč bojnih voz, sedemsto konjenikov in dvajset tisoč pešcev in David je prerezal Ahilove tetive vsem konjem bojnih vozov, toda izmed njih jih je prihranil za sto bojnih vozov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Ko so prišli Sirci iz Damaska, da okrepijo Hadadézerja, kralja iz Cobe, je David izmed Sircev usmrtil dvaindvajset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Potem je David postavil garnizije v Siriji, v Damasku in Sirci so postali Davidovi služabniki in prinašali darila. In Gospod je varoval Davida kamorkoli je odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'David je vzel ščite iz zlata, ki so bili na Hadadézerjevih služabnikih in jih prinesel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Iz Betaha in iz Berotája, Hadadézerjevih mest, je kralj David vzel silno veliko brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Ko je Toí, kralj Hamáta, slišal, da je David udaril vso Hadadézerjevo vojsko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'potem je Toí poslal h kralju Davidu svojega sina Joráma, da ga pozdravi in da ga blagoslovi, ker se je bojeval zoper Hadadézerja in ga udaril, kajti Hadadézer je imel vojne s Toíjem. In Jorám je s seboj prinesel posode iz srebra, posode iz zlata in posode iz brona,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'ki jih je tudi kralj David posvetil Gospodu, skupaj s srebrom in zlatom, ki ga je posvetil od vseh narodov, ki jih je podjarmil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'od Sirije in od Moába in od Amónovih otrok in od Filistejcev in od Amáleka in od Hadadézerjevega plena, Rehóbovega sina, kralja Cobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David si je pridobil ime, ko se je vrnil iz udarjanja Sircev v solni dolini, ki jih je bilo osemnajst tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Postavil je garnizije v Edómu, po vsem Edómu je postavil garnizije in vsi tisti iz Edóma so postali Davidovi služabniki. In Gospod je varoval Davida kamorkoli je šel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'David je kraljeval nad vsem Izraelom in David je izvajal sodbo in pravico vsemu svojemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Cerújin sin Joáb je bil nad vojsko, Ahilúdov sin Józafat je bil letopisec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Ahitúbov sin Cadók in Abjatárjev sin Ahiméleh sta bila duhovnika, Serajá je bil pisar,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Jojadájev sin Benajá je bil tako nad Keretéjci in Péletovci, Davidovi sinovi pa so bili glavni vladarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'David je rekel: »Je še kakšen, ki je preostal od Savlove hiše, da mu lahko zaradi Jonatana izkažem prijaznost?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Bil pa je iz Savlove hiše služabnik, katerega ime je bilo Cibá. Ko so ga poklicali k Davidu, mu je kralj rekel: » Si ti Cibá?« Rekel je: » On je tvoj služabnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Kralj je rekel: » Mar ni nikogar več iz Savlove hiše, da mu lahko izkažem Božjo prijaznost?« Cibá je kralju rekel: »Jonatan ima še sina, ki je hrom na svojih stopalih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kralj mu je rekel: »Kje se nahaja?« Cibá je rekel kralju: »Glej, v hiši Amiélovega sina Mahírja v Lo Dabárju je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Potem je kralj David poslal in ga privedel iz hiše Amiélovega sina Mahírja, iz Lo Dabárja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Torej ko je Mefibóšet, sin Jonatana, Savlovega sina, prišel k Davidu, je padel na svoj obraz in ga počastil. David je rekel: »Mefibóšet.« Odgovoril je: »Glej, tvoj služabnik!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David mu je rekel: »Ne boj se, kajti zagotovo ti bom izkazal prijaznost zaradi tvojega očeta Jonatana in jaz ti bom obnovil vso deželo tvojega očeta Savla in pri moji mizi boš nenehno jedel kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Priklonil se je in rekel: »Kaj je tvoj služabnik, da bi pogledal na takšnega mrtvega psa, kot sem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Potem je kralj poklical Savlovega služabnika Cibája in mu rekel: »Sinu tvojega gospodarja sem izročil vse, kar je pripadalo Savlu in vsej njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Torej ti in tvoji sinovi in tvoji služabniki, boste zanj obdelovali deželo in ti boš prinesel sadove, da bo sin tvojega gospodarja lahko imel hrano za jesti. Toda Mefibóšet, sin tvojega gospodarja, bo vedno jedel kruh pri moji mizi.« Torej Cibá je imel petnajst sinov in dvajset služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Potem je Cibá rekel kralju: »Glede na vse, kar je moj gospod kralj zapovedal svojemu služabniku, tako bo tvoj služabnik storil. Kar se tiče Mefibóšeta,« je rekel kralj, »on bo jedel pri moji mizi, kakor nekdo izmed kraljevih sinov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefibóšet pa je imel mladega sina, katerega ime je bilo Miha. In vsi, ki so prebivali v Cibájajevi hiši, so bili služabniki Mefibóšetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Tako je Mefibóšet prebival v Jeruzalemu, kajti nenehno je jedel pri kraljevi mizi, bil pa je hrom na obeh svojih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Potem se je pripetilo, da je umrl kralj Amónovih otrok in namesto njega je zakraljeval njegov sin Hanún.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Potem je David rekel: »Prijaznost bom izkazal Naháševemu sinu Hanúnu, kot je njegov oče izkazal prijaznost meni.« In David je poslal, da ga potolaži po roki svojih služabnikov, zaradi njegovega očeta. In Davidovi služabniki so prišli v deželo Amónovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Princi Amónovih otrok pa so rekli svojemu gospodarju Hanúnu: »Misliš, da David spoštuje tvojega očeta, da je k tebi poslal tolažnike? Ali ni David raje svojih služabnikov poslal k tebi, da bi preiskal mesto, vohunil in da ga zruši?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Zato je Hanún vzel Davidove služabnike, jim pobril eno polovico njihovih brad in njihove obleke odrezal po sredi, celó do njihovih zadnjic in jih poslal proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Ko so to povedali Davidu, je poslal, da jih sreča, ker so bili možje silno osramočeni. Kralj je rekel: »Ostanite pri Jerihi, dokler vam brade ne zrastejo in potem se vrnite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Ko so Amónovi otroci videli, da so se usmradili pred Davidom, so Amónovi otroci poslali in najeli Sirce iz Bet Rehóba, Sirce iz Cobe, dvajset tisoč pešcev in od kralja Maáhe tisoč mož in iz Toba dvanajst tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Ko je David slišal o tem, je poslal Joába in vso vojsko mogočnih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Amónovi otroci so prišli ven in se postrojili v bitko ob vhodu velikih vrat. Sirci iz Cobe, iz Rehóba, Toba in Maáhe pa so bili posebej na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Ko je Joáb videl, da je bilo čelo bitke zoper njega spredaj in zadaj, je izbral izmed vseh izbranih Izraelovih mož in jih postrojil zoper Sirce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Preostanek ljudstva pa je izročil v roko svojega brata Abišája, da bi jih lahko postrojil zoper Amónove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Rekel je: »Če bodo Sirci zame premočni, potem boš ti pomagal meni, toda če bodo Amónovi otroci premočni zate, potem bom prišel in ti pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Bodi odločnega poguma in bodimo možje za naše ljudstvo in za mesta našega Boga, Gospod pa naj stori to, kar se mu zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Joáb se je približal in ljudstvo, ki je bilo z njim, k bitki zoper Sirce in ti so pobegnili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Ko so Amónovi otroci videli, da so Sirci pobegnili, potem so tudi sami pobegnili pred Abišájem in vstopili v mesto. Tako se je Joáb vrnil od Amónovih otrok in prišel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Ko so Sirci videli, da so bili udarjeni pred Izraelom, so se zbrali skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Hadarézer je poslal in privedel ven Sirce, ki so bili onkraj reke in prišli so do Heláma in Šobáh, poveljnik Hadarézerjeve vojske, je šel pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Ko je bilo to povedano Davidu, je zbral skupaj ves Izrael in prečkal Jordan ter prišel k Helámu. Sirci pa so se postrojili zoper Davida in se borili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'In Sirci so pobegnili pred Izraelom, in David je usmrtil sedemsto mož sirskih bojnih vozov in štirideset tisoč konjenikov in udaril Šobáha, poveljnika njihove vojske, ki je tam umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Ko so vsi kralji, ki so bili Hadarézerjevi služabniki, videli, da so bili udarjeni pred Izraelom, so z Izraelom sklenili mir in jim služili. Tako so se Sirci bali, da bi še pomagali Amónovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Pripetilo se je, potem ko je minilo leto, ob času, ko gredo kralji na bitko, da je David poslal Joába in z njim svoje služabnike in ves Izrael in uničili so Amónove otroke in oblegali Rabo. Toda David se je še vedno zadrževal v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Ob večernem času se je pripetilo, da se je David dvignil iz svoje postelje in hodil po strehi kraljeve hiše in s strehe je videl žensko, ki se je umivala in ženska je bila na pogled zelo krasna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'David je poslal in poizvedel za žensko. Nekdo je rekel: » Mar ni to Batšéba, Eliámova hči, žena Hetejca Urijája?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'David je poslal poslance in jo vzel. Vstopila je k njemu in ležal je z njo, kajti očiščena je bila od svoje nečistosti in vrnila se je v svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Ženska je spočela in poslala in povedala Davidu ter rekla: »Jaz sem z otrokom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'David je poslal k Joábu, rekoč: »Pošlji mi Hetejca Urijája.« In Joáb je poslal Urijája k Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Ko je Urijá prišel k njemu, je David od njega zahteval, kako je šlo Joábu in kako je šlo ljudstvu in kako je uspevala vojna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'David je Urijáju rekel: »Pojdi dol k svoji hiši in si umij stopala.« Urijá je odšel iz kraljeve hiše in sledilo mu je darilo kraljeve jedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Toda Urijá je spal pri vratih kraljeve hiše z vsemi služabniki svojega gospoda in ni odšel dol k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Ko so Davidu povedali, rekoč: »Urijá ni odšel dol k svoji hiši,« je David rekel Urijáju: »Ali ne prihajaš iz svojega potovanja? Zakaj potem nisi šel dol k svoji hiši?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Urijá je Davidu rekel: »Skrinja, Izrael in Juda prebivajo v šotorih in moj gospod Joáb in služabniki mojega gospoda so utaborjeni na odprtih poljih; ali bom jaz potem šel v svojo hišo, da jem, da pijem in da ležim s svojo ženo? Kakor ti živiš in kakor živi tvoja duša, ne bom storil te stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'In David je rekel Urijáju: »Ostani tukaj tudi danes, jutri pa ti bom pustil oditi.« Tako je Urijá ostal v Jeruzalemu ta dan in naslednji dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Ko ga je David poklical, je pred njim jedel in pil in ga je opijanil in zvečer je odšel ven, da bi s služabniki svojega gospoda legel na svojo posteljo, toda ni šel dol k svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Zjutraj pa se je zgodilo, da je David napisal pismo Joábu in to poslal po Urijájevi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'V pismu je napisal, rekoč: »Postavite Urijája na sprednji del najbolj vroče bitke in se umaknite od njega, da bo lahko udarjen in umre.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Pripetilo se je, ko je Joáb opazoval mesto, da je Urijája določil na kraj, kjer je vedel, da so bili hrabri možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Možje iz mesta so odšli ven in se borili z Joábom in tam so padli nekateri izmed ljudstva, izmed Davidovih služabnikov in tudi Hetejec Urijá je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Potem je Joáb poslal in Davidu povedal vse stvari glede vojne');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'in naročil poslancu, rekoč: »Ko boš končal s sporočanjem stvari kralju glede vojne');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'in če bo tako, da se bo vzdignil kraljevi bes in ti reče: ›Zakaj ste se približali tako blizu mesta, ko ste se bojevali? Mar niste vedeli, da bodo streljali iz obzidja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kdo je udaril Jerubéšetovega sina Abiméleha? Ali ni ženska iz obzidja vrgla nanj kos mlinskega kamna, da je umrl v Tebécu? Zakaj ste se približali obzidju?‹ Potem reci: ›Tudi tvoj služabnik Hetejec Urijá je mrtev.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Tako je poslanec odšel in prišel in pokazal Davidu vse, za kar ga je Joáb poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Poslanec je Davidu rekel: »Ljudje so zagotovo prevladali zoper nas in prišli ven, k nam na polje in mi smo bili nad njimi celo do vhoda velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'In strelci so streljali iz obzidja na tvoje služabnike; in nekateri izmed kraljevih služabnikov so mrtvi in tudi tvoj služabnik Hetejec Urijá je mrtev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Potem je David rekel poslancu: »Tako boš rekel Joábu: ›Ne dopusti, da te ta stvar razžali, kajti meč požre enega kakor drugega. Svojo bitko zoper mesto naredi močnejšo in ga premagaj. Ohrabri ga.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Ko je Urijájeva žena slišala, da je bil njen soprog Urijá mrtev, je žalovala za svojim soprogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Ko je žalovanje minilo, je David poslal in jo privedel k svoji hiši in postala je njegova žena in mu rodila sina. Toda stvar, ki jo je David storil, je razžalila Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Gospod je k Davidu poslal Natána. Ta je prišel k njemu in mu rekel: »Bila sta dva moža v enem mestu; eden bogat, drugi pa reven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bogat človek je imel silno mnogo tropov in čred,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'toda reven človek ni imel ničesar, razen ene majhne ovčje jagnjice, ki jo je kupil in jo preživljal. Ta je zrasla skupaj z njim in z njegovimi otroki; jedla je od njegove lastne hrane, pila iz njegove lastne čaše, ležala v njegovem naročju in mu je bila kakor hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'K bogatašu pa je prišel popotnik in žal mu je bilo vzeti od svojega lastnega tropa in od svoje lastne črede, da pripravi za popotnika, ki je prišel k njemu, temveč je vzel reveževo jagnje in to pripravil za človeka, ki je prišel k njemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Davidova jeza je bila silno vžgana zoper tega moža in Natánu je rekel: » Kakor Gospod živi, mož, ki je storil to stvar, bo zagotovo umrl');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'in četverno bo povrnil jagnje, ker je storil to stvar in ker ni imel usmiljenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Natán je rekel Davidu: »Ti si ta človek. Tako govori Gospod, Izraelov Bog: ›Mazilil sem te [za] kralja nad Izraelom in te osvobodil iz Savlove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Dal sem ti hišo tvojega gospodarja in v tvoje naročje žene tvojega gospodarja in dal sem ti Izraelovo in Judovo hišo. Če bi bilo to premalo, bi ti dodal še več takšnih in takšnih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Zakaj si preziral Gospodovo zapoved, da si storil zlo v njegovem pogledu? Hetejca Urijája si ubil z mečem in njegovo ženo vzel, da postane tvoja žena, njega pa si umoril z mečem Amónovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Zdaj torej meč ne bo nikoli odšel od tvoje hiše, ker si me preziral in si vzel ženo Hetejca Urijája, da bi bila tvoja žena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tako govori Gospod: ›Glej, zoper tebe bom vzdignil zlo iz tvoje lastne hiše in pred tvojimi očmi bom vzel tvoje žene in jih dal tvojemu bližnjemu in ta bo ležal s tvojimi ženami v pogledu tega sonca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Kajti ti si to delal naskrivaj, toda jaz bom to stvar storil pred vsem Izraelom in pred soncem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'David je rekel Natánu: »Grešil sem zoper Gospoda.« Natán je rekel Davidu: » Gospod je tudi odstranil tvoj greh; ne boš umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Vendar ker si s tem dejanjem dal Gospodovim sovražnikom veliko priložnost, da izrekajo bogokletje, bo tudi otrok, ki ti je rojen, zagotovo umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'In Natán je odšel od njegove hiše. Gospod pa je udaril otroka, ki ga je Urijájeva žena rodila Davidu in ta je bil zelo bolan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'David je zato rotil Boga za otroka in David se je postil in vstopil ter vso noč ležal na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Starešine njegove hiše so vstali in odšli k njemu, da ga vzdignejo z zemlje, toda ni hotel niti ni z njimi jedel kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Pripetilo se je na sedmi dan, da je otrok umrl. Davidovi služabniki pa so se mu bali povedati, da je bil otrok mrtev, kajti rekli so: »Glej, medtem ko je bil otrok še živ, smo mu govorili, pa ni hotel poslušati našega glasu. Kako bo torej žalostil samega sebe, če mu povemo, da je otrok mrtev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Toda ko je David videl, da so njegovi služabniki šepetali, je David zaznal, da je bil otrok mrtev. Zato je David rekel svojim služabnikom: »Je otrok mrtev?« Rekli so: »Mrtev je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Potem se je David vzdignil z zemlje, se umil, mazilil, zamenjal svojo obleko, prišel v Gospodovo hišo in oboževal. Potem je prišel v svojo lastno hišo; in ko je zahteval, so predenj postavili kruh in je jedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Potem so mu njegovi služabniki rekli: »Kakšna stvar je ta, ki si jo storil? Postil si se in jokal zaradi otroka, medtem ko je bil živ, toda ko je bil otrok mrtev, si vstal in jedel kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Rekel je: »Medtem ko je bil otrok še živ, sem se postil in jokal, kajti rekel sem: ›Kdo lahko pove, ali mi bo Bog milostljiv, da bo otrok lahko živel?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Toda sedaj je mrtev, zakaj bi se torej postil? Ali ga lahko ponovno privedem nazaj? Jaz bom šel k njemu, toda on se ne bo vrnil k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'David je potolažil svojo ženo Batšébo in šel noter k njej in ležal z njo in rodila je sina in njegovo ime je imenoval Salomon. In Gospod ga je ljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'In poslal je po roki preroka Natána in ta je njegovo ime imenoval Jedidjá, zaradi Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joáb se je boril zoper Rabo Amónovih sinov in zavzel kraljevo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Joáb je poslal poslance k Davidu in rekel: »Boril sem se zoper Rabo in zavzel mesto vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Zdaj torej zberi skupaj preostanek ljudstva in se utabôri zoper mesto in ga zavzemi, da ne bi jaz zavzel mesta in bi se ta imenoval po mojem imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'In David je vse ljudstvo zbral skupaj in odšel v Rabo in se bojeval zoper njo ter jo zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Vzel je krono njihovega kralja iz njegove glave, katere teža je bila talent zlata z dragocenimi kamni in ta je bila postavljena na Davidovo glavo. In iz mesta je prinesel plena v velikem obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Privedel je ljudstvo, ki je bilo tam in jih postavil pod žage, pod brane iz železa, pod sekire iz železa in jih primoral, da gredo skozi opekarsko peč. Tako je storil vsem mestom Amónovih otrok. Tako se je David in vse ljudstvo vrnilo v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Pripetilo se je po tem, da je Davidov sin Absalom imel lepo sestro, ki ji je bilo ime Tamara in Davidov sin Amnón, jo je vzljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnón je bil tako obupan, da je zaradi svoje sestre Tamare zbolel, kajti bila je devica in Amnón si je mislil, da je zanj težko, da ji stori kakršno koli stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Toda Amnón je imel prijatelja, katerega ime je bilo Jonadáb, sin Šimája, Davidovega brata. Jonadáb pa je bil zelo premeten človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Ta mu je rekel: »Zakaj si ti, ki si kraljev sin, iz dneva v dan slabotnejši? Ali mi ne boš povedal?« Amnón mu je rekel: »Ljubim Tamaro, sestro svojega brata Absaloma.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadáb mu je rekel: »Ulezi se na svojo posteljo in se naredi bolnega in ko pride tvoj oče, da te pogleda, mu reci: ›Prosim te, naj pride moja sestra Tamara in mi da jesti in pripravi hrano v mojem pogledu, da bom to lahko videl in to pojedel pri njeni roki.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Tako se je Amnón ulegel in se naredil bolnega in ko je kralj prišel, da ga pogleda, je Amnón rekel kralju: »Prosim te, naj pride moja sestra Tamara in mi pripravi nekaj kolačev v mojem pogledu, da bom lahko jedel pri njeni roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Potem je David poslal domov k Tamari, rekoč: »Pojdi sedaj k hiši svojega brata Amnóna in mu pripravi hrano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tako je Tamara odšla k hiši svojega brata Amnóna in ta je ležal. Vzela je moko in jo zgnetla in naredila kolače v njegovem pogledu in kolače spekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Vzela je ponev in jih iztresla pred njim, toda odklonil je jesti. Amnón je rekel: »Odstranite od mene vse može.« In vsi možje so odšli od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Amnón je rekel Tamari: »Prinesi hrano v sobo, da bom lahko jedel iz tvoje roke.« Tamara je vzela kolače, ki jih je naredila in jih prinesla v sobo k svojemu bratu Amnónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Ko jih je prinesla k njemu, da jé, jo je prijel in ji rekel: »Pridi, lezi z menoj, moja sestra.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Odgovorila mu je: »Ne, moj brat, ne sili me, kajti nobena takšna stvar se ne bi smela storiti v Izraelu. Ne stôri te neumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'In jaz, kam naj grem s svojo sramoto? Kar pa se tebe tiče, boš kakor nekdo izmed bedakov v Izraelu. Sedaj torej, prosim te, spregovori kralju, kajti on me ne bo zadržal pred teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Vendar ni hotel prisluhniti njenemu glasu, temveč ker je bil močnejši kakor ona, jo je prisilil in ležal z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Potem jo je Amnón skrajno zasovražil, tako da je bilo sovraštvo, s katerim jo je zasovražil, večje kakor ljubezen, s katero jo je ljubil. In Amnón ji je rekel: »Vstani, izgini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Rekla mu je: »Ni razloga. To zlo, da me pošiljaš proč, je večje kakor drugo, ki si mi ga storil.« Toda ni ji hotel prisluhniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Potem je poklical svojega služabnika, ki mu je služil in rekel: »Postavi sedaj to žensko stran od mene in zapahni vrata za njo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Na sebi je imela obleko iz številnih barv, kajti s takšnim svečanim oblačilom so bile oblečene kraljeve hčere, ki so bile device. Potem jo je njegov služabnik odvedel ven in za njo zapahnil vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tamara pa si je na svojo glavo dala pepel in pretrgala obleko iz številnih barv, ki je bila na njej in svojo roko položila na svojo glavo ter jokajoč odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Njen brat Absalom ji je rekel: »Ali je bil tvoj brat Amnón s teboj? Toda sedaj molči, moja sestra. On je tvoj brat. Ne oziraj se na to stvar.« Tako je Tamara ostala zapuščena v hiši svojega brata Absaloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Toda ko je kralj David slišal o vseh teh stvareh, je bil zelo ogorčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalom ni spregovoril svojemu bratu Amnónu niti dobro niti slabo, kajti Absalom je sovražil Amnóna, ker je posilil njegovo sestro Tamaro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Pripetilo se je po dveh polnih letih, da je imel Absalom strižce ovc v Báal Hacórju, ki je poleg Efrájima in Absalom je povabil vse kraljeve sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalom je prišel h kralju ter rekel: »Glej torej, tvoj služabnik ima strižce ovc, naj kralj, rotim te in njegovi služabniki gredo s tvojim služabnikom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Kralj je rekel Absalomu: »Ne, moj sin, naj ne gremo sedaj vsi, da ti ne bi bili v breme.« Silil ga je, vendar ni želel iti, temveč ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Potem je Absalom rekel: »Če ne, prosim te, naj gre z nami moj brat Amnón.« Kralj mu je rekel: »Čemu bi on šel s teboj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Toda Absalom ga je silil, da je pustil Amnóna in vse kraljeve sinove iti z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Torej Absalom je svojim služabnikom ukazal, rekoč: »Zapomnite si torej kdaj bo Amnónovo srce veselo z vinom in ko vam rečem: ›Udarite Amnóna;‹ tedaj ga ubijte, ne bojte se; ali vam nisem jaz ukazal? Bodite pogumni in bodite hrabri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Absalomovi služabniki so storili Amnónu, kakor je Absalom zapovedal. Potem so vsi kraljevi sinovi vstali in vsak mož se je povzpel na svojo mulo ter pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Pripetilo se je, ko so bili na poti, da so prišle k Davidu novice, rekoč: »Absalom je umoril vse kraljeve sinove in niti eden izmed njih ni preostal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Potem je kralj vstal in raztrgal svoje obleke in legel na zemljo in vsi njegovi služabniki so stali poleg s svojimi pretrganimi oblačili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Jonadáb, sin Davidovega brata Šimája, je odgovoril ter rekel: »Naj moj gospod ne domneva, da so umorili vse mladeniče, kraljeve sinove, kajti samo Amnón je mrtev, kajti z Absalomovo določitvijo je bilo to določeno od dneva, ko je posilil njegovo sestro Tamaro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Zdaj torej naj si moj gospod kralj te stvari ne vzame k srcu, da misli, da so vsi kraljevi sinovi mrtvi, kajti samo Amnón je mrtev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Toda Absalom je pobegnil. In mladenič, ki je bil na straži, je povzdignil svoje oči in pogledal in glej, precej ljudi je prihajajo po poti od pobočja hriba za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Jonadáb je rekel kralju: »Glej, kraljevi sinovi prihajajo. Kakor je tvoj služabnik rekel, tako je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Pripetilo se je, takoj ko je končal govorjenje, glej, da so prišli kraljevi sinovi in povzdignili svoj glas ter zajokali in tudi kralj in vsi njegovi služabniki so zelo bridko jokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Toda Absalom je pobegnil in odšel k Talmáju, Amihúdovemu sinu, kralju v Gešurju. David pa je vsak dan žaloval za svojim sinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Tako je Absalom pobegnil in odšel v Gešur in tam je bil tri leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Duša kralja Davida pa je hrepenela, da gre k Absalomu, kajti potolažen je bil glede Amnóna, glede na to, da je bil on mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Torej Cerújin sin Joáb je zaznal, da je bilo kraljevo srce [nagnjeno] k Absalomu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Joáb je poslal v Tekóo in od tam privedel modro žensko ter ji rekel: »Prosim te, hlini se, da si žalovalka in sedaj si nadeni žalovalno obleko in se ne mazili z oljem, temveč bodi kakor ženska, ki je dolgo časa žalovala za mrtvim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'in pojdi h kralju in mu govori na ta način.« Tako je Joáb položil besede v njena usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Ko je ženska iz Tekóe govorila kralju, je padla na svoj obraz do tal in se globoko priklonila ter rekla: »Pomagaj, oh kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kralj ji je rekel: »Kaj te pesti?« Odgovorila je: »Res sem vdova in moj soprog je mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Tvoja pomočnica je imela dva sinova in skupaj sta se prepirala na polju in tam ni bilo nobenega, da ju loči, temveč je eden udaril drugega in ga usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Glej, celotna družina je vstala zoper tvojo pomočnico in rekli so: ›Izroči tega, ki je usmrtil svojega brata, da ga bomo lahko ubili za življenje njegovega brata, ki ga je usmrtil in tudi dediča bomo uničili.‹ Tako bodo pogasili moj ogorek, ki je ostal in mojemu soprogu ne bodo pustili niti imena niti ostanka na tej zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kralj je rekel ženski: »Pojdi k svoji hiši in glede tebe dal bom zadolžitev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Ženska iz Tekóe je rekla kralju: »Moj gospod, oh kralj, krivičnost bodi na meni in na hiši mojega očeta, kralj in njegov prestol pa naj bosta brez krivde.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Kralj je rekel: »Kdorkoli ti karkoli reče, ga privedi k meni in ne bo se te več dotaknil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Potem je rekla: »Prosim te, naj se kralj spomni Gospoda, svojega Boga, da ti nočeš trpeti, da krvni maščevalci še naprej uničujejo, da ne bi uničili mojega sina.« Rekel je: »Kakor Gospod živi niti en las tvojega sina ne bo padel k zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Potem je ženska rekla: »Naj tvoja pomočnica, prosim te, spregovori eno besedo mojemu gospodu kralju.« In ta je rekel: »Povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Ženska je rekla: »Zakaj si potem mislil storiti takšno stvar zoper Božje ljudstvo? Kajti kralj govori to stvar kakor nekdo, ki je pomanjkljiv, v tem, da kralj ne privede ponovno domov svojega pregnanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Kajti mi moramo umreti in smo kakor voda, razlita na tla, ki ne more biti ponovno zbrana niti Bog ne upošteva nobene osebe, vendar snuje način, da njegov pregnani ne bo izključen od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Zdaj torej, ko sem prišla, da o tej stvari govorim mojemu gospodu kralju, je to zato, ker me je ljudstvo prestrašilo. Tvoja pomočnica je rekla: ›Spregovorila bom torej kralju. Lahko se zgodi, da bo kralj izpolnil zahtevo svoje pomočnice.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Kajti kralj bo slišal, da svojo pomočnico osvobodi iz roke človeka, ki hoče skupaj uničiti tako mene in mojega sina iz Božje dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Potem je tvoja pomočnica rekla Gospodu: ›Beseda mojega gospoda kralja bo sedaj tolažilna, kajti kakor angel od Boga, tako je moj gospod kralj, da razlikuje dobro in slabo, zato bo Gospod, tvoj Bog, s teboj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Potem je kralj ženski odgovoril in rekel: »Ne skrivaj pred menoj, prosim te, stvari, ki jo bom vprašal.« Ženska je rekla: »Naj moj gospod kralj sedaj spregovori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kralj je rekel: » Mar ni v vsem tem s teboj Joábova roka?« Ženska je odgovorila ter rekla: » Kakor živi tvoja duša, moj gospod kralj, nihče se ne more izogniti ne na desno ne na levo od tega, kar je moj gospod kralj govoril, kajti tvoj služabnik Joáb mi je zaukazal in on je položil vse te besede v usta tvoje pomočnice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'da privleče na dan to obliko govora, je tvoj služabnik Joáb storil to stvar. In moj gospod je moder, glede na modrost Božjega angela, da ve vse stvari, ki so na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Kralj je rekel Joábu: »Glej torej, jaz sem storil to stvar, zato pojdi, ponovno privedi mladeniča Absaloma.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Joáb je padel k tlom, na svoj obraz, se upognil in zahvalil kralju in Joáb je rekel: »Danes tvoj služabnik vé, da sem našel milost v tvojem pogledu, moj gospod, oh kralj, v tem, da je kralj izpolnil zahtevo svojega služabnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Tako je Joáb vstal in odšel v Gešur in Absaloma privedel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Kralj je rekel: »Naj se obrne k svoji lastni hiši in naj ne vidi mojega obraza.« Tako se je Absalom vrnil k svoji lastni hiši in ni videl kraljevega obraza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Toda v vsem Izraelu ni bilo nikogar, da bi bil tako zelo hvaljen zaradi svoje lepote kakor Absalom. Od podplata svojega stopala, celo do krone njegove glave, ni bilo na njem nobenega madeža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'In ko je ostrigel svojo glavo (kajti ob koncu vsakega leta si jo je ostrigel, ker so bili lasje na njem težki, zato jo je ostrigel) si je stehtal lase svoje glave, dvesto šeklov po kraljevi teži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Absalomu so se tam rodili trije sinovi in ena hči, ki ji je bilo ime Tamara. Bila je ženska lepega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Tako je Absalom dve polni leti prebival v Jeruzalemu in ni videl kraljevega obraza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Zato je Absalom poslal po Joába, da ga pošlje h kralju, toda ta ni hotel priti k njemu in ko je drugič ponovno poslal, ta ni hotel priti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Zato je rekel svojim služabnikom: »Glejte, Joábovo polje je v bližini mojega in tam ima ječmen. Pojdite in ga požgite.« In Absalomovi služabniki so zažgali polje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Potem je Joáb vstal in prišel k Absalomu v njegovo hišo ter mu rekel: »Zakaj so tvoji služabniki zažgali moje polje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom je odgovoril Joábu: »Glej, poslal sem k tebi, rekoč: ›Pridi sèm, da te lahko pošljem h kralju, da rečem: ›Zakaj sem prišel iz Gešurja?‹‹ Zame bi bilo dobro, da bi bil še vedno tam. Sedaj mi torej pusti videti kraljev obraz in če bo kakršnakoli krivičnost v meni, naj me ubije.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Tako je Joáb prišel h kralju in mu povedal in ko je dal poklicati Absaloma, je ta prišel h kralju in se pred kraljem priklonil na svoj obraz do tal in kralj je poljubil Absaloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Pripetilo se je po tem, da si je Absalom pripravil vozove, konje in petdeset mož, da so tekli pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Absalom je vstajal zgodaj in stal poleg poti velikih vrat in to je bilo tako, da ko je katerikoli človek imel polemiko, je prišel h kralju za sodbo, potem mu je Absalom zaklical in rekel: »Iz katerega mesta si?« In ta je rekel: »Tvoj služabnik je iz enega izmed Izraelovih rodov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Absalom mu je rekel: »Poglej, tvoje zadeve so dobre in pravilne; toda tam ni nobenega človeka, poslanega od kralja, da te sliši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Poleg tega je Absalom rekel: »Oh da bi mene postavili za sodnika v deželi, da bi vsak človek, ki ima kakršnokoli tožbo ali zadevo, lahko prišel k meni in bi mu jaz storil pravico!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'In to je bilo tako, da ko je katerikoli moški prišel blizu k njemu, da se mu globoko prikloni, je svojo roko iztegnil naprej, ga prijel in ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Na ta način je Absalom počel vsemu Izraelu, ki so hodili h kralju po sodbo. Tako je Absalom kradel srca Izraelovih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Pripetilo se je po štiridesetih letih, da je Absalom rekel kralju: »Prosim te, naj grem in izpolnim svojo zaobljubo, ki sem jo zaobljubil Gospodu v Hebrónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Kajti tvoj služabnik se je zaobljubil, medtem ko je prebival pri Gešurju v Siriji, rekoč: ›Če me bo Gospod zares ponovno privedel v Jeruzalem, potem bom služil Gospodu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kralj mu je rekel: »Pojdi v miru.« Tako je vstal in odšel v Hebrón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Toda Absalom je poslal oglednike po vseh Izraelovih rodovih, rekoč: »Takoj ko zaslišite zvok šofarja, potem boste rekli: ›Absalom kraljuje v Hebrónu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Z Absalomom je iz Jeruzalema odšlo dvesto mož, ki so bili poklicani. Odšli pa so v svoji toposti in niso vedeli nobene stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absalom je poslal po Gilčana Ahitófela, Davidovega svetovalca, iz njegovega mesta, torej iz Gila, medtem ko je daroval klavne daritve. In zarota je bila močna, kajti ljudstvo je nenehno naraščalo z Absalomom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'K Davidu je prišel poslanec, rekoč: »Srca Izraelovih mož sledijo Absalomu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'David je rekel vsem svojim služabnikom, ki so bili z njim pri Jeruzalemu: »Vstanimo in pobegnimo, kajti sicer ne bomo pobegnili pred Absalomom. Pohitimo, da nas ne bi nenadoma dohitel in nad nas privedel zla in mesto udaril z ostrino meča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kraljevi služabniki so rekli kralju: »Glej, tvoji služabniki so pripravljeni storiti, karkoli bo moj gospod kralj določil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Kralj je odšel naprej in vsa njegova družina za njim. Kralj pa je pustil deset žensk, ki so bile priležnice, da varujejo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Kralj je odšel naprej in vse ljudstvo za njim in se mudil na kraju, ki je bil daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Vsi njegovi služabniki so šli poleg njega in vsi Keretéjci in vsi Péletovci in vsi Gitéjci, šeststo mož, ki so prišli za njim iz Gata, so prečkali pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Potem je kralj rekel Gitéjcu Itáju: »Čemu greš tudi ti z nami? Vrni se na svoj kraj in prebivaj s kraljem, kajti tujec si in tudi izgnanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Glede na to, da si prišel šele včeraj, ali naj te ta dan pripravim hoditi z nami gor in dol? Ker grem, kamor lahko, se vrni in svoje brate vzemi nazaj. Usmiljenje in resnica naj bosta s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Itáj je odgovoril kralju in rekel: » Kakor živi Gospod in kakor živi moj gospod kralj, zagotovo, na kateremkoli kraju bo moj gospod kralj, bodisi v smrti ali življenju, celo tam bo tudi tvoj služabnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David je rekel Itáju: »Pojdi in prečkaj.« Gitéjec Itáj je šel čez in vsi njegovi možje in vsi malčki, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'In vsa dežela je jokala z močnim glasom in vse ljudstvo je šlo čez. Tudi sam kralj je šel čez potok Kidron in vse ljudstvo je šlo čez, proti poti divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Glej, tudi Cadók in vsi Lévijevci so bili z njim, nesoč skrinjo Božje zaveze in odložili so Božjo skrinjo. Abjatár je odšel gor, dokler ni vse ljudstvo šlo iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Kralj je Cadóku rekel: »Božjo skrinjo odnesite nazaj v mesto. Če bom našel naklonjenost v Gospodovih očeh, me bo ponovno privedel in mi pokazal oboje, to in njeno prebivališče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'toda če reče tako: ›Nimam veselja v tebi;‹ glej, tukaj sem, naj mi stori, kakor se mu zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Kralj je tudi rekel duhovniku Cadóku: » Mar nisi ti videc? V miru se vrni v mesto in tvoja dva sinova s teboj, tvoj sin Ahimáac in Jonatan, Abjatárjev sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Glejte, mudil se bom na ravnini divjine, dokler ne bo prišla od vas beseda, da me potrdite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Torej Cadók in Abjatár sta Božjo skrinjo ponovno odnesla v Jeruzalem in ostala sta tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David je odšel gor po pobočju Oljske gore in jokal, ko se je vzpenjal in svojo glavo je imel pokrito in hodil je bos. Vse ljudstvo, ki je bilo z njim, je vsak pokril svojo glavo in hodili so gor in jokali, medtem ko so hodili gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'In nekdo je povedal Davidu, rekoč: »Ahitófel je z Absalomom med zarotniki.« David je rekel: »Oh Gospod, prosim te, obrni Ahitófelov nasvet v norost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Pripetilo se je, da ko je David prišel na vrh gore, kjer je oboževal Boga, glej, je prišel Arkéjec Hušáj, da ga sreča, s svojim pretrganim plaščem in zemljo na svoji glavi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'ki mu je David rekel: »Če greš z menoj naprej, potem mi boš v breme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'toda če se vrneš k mestu in rečeš Absalomu: ›Jaz bom tvoj služabnik, oh kralj, kakor sem bil doslej služabnik tvojega očeta, tako bom sedaj tudi tvoj služabnik,‹ potem boš lahko zame premagal Ahitófelov nasvet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'In ali nisi tam z duhovnikoma Cadókom in Abjatárjem? Zato naj bo, da kakršnokoli stvar boš slišal iz kraljeve hiše, boš to povedal duhovnikoma Cadóku in Abjatárju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Glej, onadva imata tam s seboj svoja dva sinova, Cadókovega sina Ahimáaca in Abjatárjevega sina Jonatana. Po njima boste poslali k meni vsako stvar, ki jo lahko slišite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Tako je Davidov prijatelj Hušáj prišel v mesto in Absalom je prišel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Ko je David ravno prešel vrh hriba, glej, ga je srečal Mefibóšetov služabnik Cibá, s parom osedlanih oslov in na njih dvesto hlebov kruha, sto grozdov rozin, sto poletnih sadov in vinski meh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Kralj je rekel Cibáju: »Kaj nameravaš s tem?« Cibá je rekel: »Ti osli so za kraljevo družino, da jaha na njih. Kruh in poletno sadje za mladeniče, da jedo, in vino, da tisti, ki so v divjini oslabeli, lahko pijejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kralj je rekel: »In kje je sin tvojega gospodarja?« Cibá je rekel kralju: »Glej, on ostaja v Jeruzalemu, kajti rekel je: ›Danes mi bo Izraelova hiša obnovila kraljestvo mojega očeta.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Potem je kralj rekel Cibáju: »Glej, tvoje je vse, kar pripada Mefibóšetu.« Cibá je rekel: »Ponižno te rotim, da lahko najdem milost v tvojem pogledu, moj gospod, oh kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Ko je kralj David prišel v Bahurím, glej, je od tam prišel mož iz družine Savlove hiše, katerega ime je bilo Šimí, Gerájev sin. Prišel je naprej in nenehno preklinjal, medtem ko je prihajal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'V Davida in v vse služabnike kralja Davida je lučal kamne in vse ljudstvo in vsi mogočni možje so bili na njegovi desni roki in na njegovi levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Tako je govoril Šimí, ko je preklinjal: »Pridi ven, pridi ven, ti, krvoločen človek in ti, Beliálov človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Gospod je povrnil nad teboj vso kri Savlove hiše, namesto katerega si zakraljeval in Gospod je kraljestvo izročil v roko tvojega sina Absaloma. Glej, ujet si v svoji vragoliji, ker si krvoločen človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Potem je Cerújin sin Abišáj rekel kralju: »Zakaj bi ta mrtvi pes preklinjal mojega gospoda kralja? Naj grem preko, prosim te in snamem njegovo glavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Kralj pa je rekel: »Kaj imam z vama, Cerújina sinova? Tako naj preklinja, ker mu je Gospod rekel: ›Preklinjaj Davida.‹ Kdo bo potem rekel: ›Čemu si tako storil?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'David je rekel Abišáju in vsem svojim služabnikom: »Glejte, moj sin, ki je prišel iz moje notranjosti, mi streže po življenju. Kako mnogo bolj lahko sedaj to stori ta Benjaminovec? Pustite ga na miru in naj preklinja, kajti Gospod mu je zaukazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Morda bo Gospod pogledal na mojo stisko in da mi bo Gospod poplačal dobro za njegovo preklinjanje ta dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Medtem ko so David in njegovi možje šli po poti, je Šimí hodil vzdolž, na drugi strani hriba, nasproti njemu in preklinjal, medtem ko je hodil in lučal kamne vanj in metal prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Kralj in vse ljudstvo, ki so bili z njim, so prišli izmučeni in se tam osvežili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom in vse ljudstvo Izraelovih mož pa so prišli v Jeruzalem in Ahitófel z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Pripetilo se je, ko je Davidov prijatelj Arkéjec Hušáj prišel k Absalomu, da je Hušáj rekel Absalomu: »Živel kralj, živel kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom je rekel Hušáju: » Ali je to tvoja prijaznost do tvojega prijatelja? Zakaj nisi šel s svojim prijateljem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Hušáj je rekel Absalomu: »Ne, temveč katerega Gospod in to ljudstvo in vsi Izraelovi možje izberejo, njegov bom in z njim bom ostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'In ponovno, komu naj bi služil? Ali naj ne bi služil v prisotnosti njegovega sina? Kakor sem služil v prisotnosti tvojega očeta, tako bom v tvoji prisotnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Potem je Absalom rekel Ahitófelu: »Dajte nasvet med vami, kaj naj storimo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitófel je rekel Absalomu: »Pojdi noter v priležnice svojega očeta, ki jih je pustil, da varujejo hišo in ves Izrael bo slišal, da si preziran od svojega očeta. Potem bodo močne roke vseh, ki so s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Tako so Absalomu razprostrli šotor na vrhu hiše in Absalom je šel v priležnice svojega očeta pred očmi vsega Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Nasvet Ahitófela, ki je v tistih dneh svetoval, je bil, kakor če bi človek poizvedoval pri Božjem oraklju, tako so bili vsi Ahitófelovi nasveti tako z Davidom kakor z Absalomom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Poleg tega je Ahitófel rekel Absalomu. »Naj sedaj izberem dvanajst tisoč mož in vstal bom in to noč zasledoval Davida');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'in prišel bom nadenj, medtem ko je izmučen in slabotnih rok in ga prestrašil. Vse ljudstvo, ki je z njim, bo pobegnilo, udaril pa bom samo kralja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'in vse ljudstvo bom privedel nazaj k tebi. Mož, ki ga iščeš, je kakor, če se vsi vrnejo; tako bo vse ljudstvo v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Beseda je dobro ugajala Absalomu in vsem Izraelovim starešinam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Potem je Absalom rekel: »Pokličite sedaj tudi Arkéjca Hušája in naj slišimo tudi, kaj pravi on.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Ko je Hušáj prišel k Absalomu, mu je Absalom spregovoril, rekoč: »Ahitófel je govoril na ta način. Ali naj storimo po njegovem govoru? Če ne, ti spregovori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Hušáj je rekel Absalomu: »Nasvet, ki ti ga je tokrat dal Ahitófel, ni dober.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Kajti,« je rekel Hušáj, »poznaš svojega očeta in njegove može, da so mogočni možje in v svojih mislih komaj čakajo, kakor medvedka, oropana svojih mladičev, na polju. In tvoj oče je bojevnik in ne bo prenočeval z ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Glej, sedaj je skrit v neki jami ali na nekem drugem kraju. In zgodilo se bo, ko bodo na začetku nekateri izmed njih premagani, da kdorkoli to sliši, bo rekel: ›Tam je pokol med ljudstvom, ki sledijo Absalomu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Tudi tisti, ki je hraber, katerega srce je kakor srce leva, se bo popolnoma stopil, kajti ves Izrael ve, da je tvoj oče mogočen človek in tisti, ki so z njim, so hrabri možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Zato svetujem, da se ves Izrael nasploh zbere k tebi, od Dana, celo do Beeršébe, kakor je peska, ki je pri morju zaradi množice in da greš ti osebno v bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Tako bomo prišli nadenj na nekem kraju, kjer bo najden in posvetili bomo nanj, kakor rosa pada na tla in od njega in od vseh mož, ki so z njim, tam ne bo nihče ostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Poleg tega, če bo odšel v mesto, potem bo ves Izrael do tega mesta prinesel vrvi in potegnili ga bomo v reko, dokler ne bo tam najden niti en majhen kamen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Absalom in vsi možje iz Izraela so rekli: »Nasvet Arkéjca Hušája je boljši kakor nasvet Ahitófela.« Kajti Gospod je določil, da porazi dober Ahitófelov nasvet, z namenom, da bo Gospod lahko privedel zlo nad Absaloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Potem je Hušáj rekel Cadóku in duhovniku Abjatárju: »Tako in tako je Ahitófel svetoval Absalomu in starešinam Izraela, in tako in tako sem svetoval jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Zdaj torej hitro pošlji in povej Davidu, rekoč: ›To noč ne prenočuj na ravninah divjine, temveč naglo prečkaj, da te ne bi kralj požrl in vse ljudstvo, ki je z njim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Torej Jonatan in Ahimáac sta ostala v En Rogelu, kajti nista smela biti videna, da pridete v mesto. In deklina je odšla in jima povedala. Odšla sta ter povedala kralju Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Kljub temu ju je videl deček in povedal Absalomu. Toda oba izmed njiju sta hitro odšla proč in prišla k hiši človeka v Bahurímu, ki je na svojem dvorišču imela vodnjak, kamor sta se spustila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Ženska je vzela [pokrivalo] in pokrivalo razprostrla čez ustje vodnjaka in nanj raztresla zmleto žito in stvar ni bila znana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Ko so Absalomovi služabniki prišli v hišo k ženski, so rekli: »Kje sta Ahimáac in Jonatan?« Ženska jim je rekla: »Odšla sta čez vodni potok.« Ko pa so ju iskali in ju niso mogli najti, so se vrnili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Pripetilo se je, potem ko so odšli, da sta prišla ven iz vodnjaka in odšla in kralju Davidu povedala in Davidu rekla: »Vstani in hitro prečkaj vodo, kajti Ahitófel je tako svetoval zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Potem je David vstal in vse ljudstvo, ki je bilo z njim in so prečkali Jordan. Do jutranje svetlobe ni manjkal niti eden izmed teh, ki so prečkali Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Ko je Ahitófel videl, da njegov nasvet ni bil sleden, je osedlal svojega osla, vstal in se spravil domov k svoji hiši, k svojemu mestu in svojo družino postavil v red in samega sebe obesil in umrl in bil pokopan v mavzoleju svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Potem je David prišel v Mahanájim. Absalom pa je prečkal Jordan, on in vsi možje iz Izraela z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Absalom je namesto Joába za poveljnika vojske postavil Amasája. Ta Amasá je bil sin moža, katerega ime je bilo Itra, Izraelec, ki je odšel noter k Naháševi hčeri Abigájili, sestri Joábove matere Cerúje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Tako so Izrael in Absalom taborili v deželi Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Pripetilo se je, ko je David prišel v Mahanájim, da so Nahášev sin Šobí, iz Rabe Amónovih otrok in Amiélov sin Mahír iz Lo Dabárja in Gileádec Barziláj iz Roglíma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'prinesli postelje, umivalnike, lončene posode ter pšenico, ječmen, moko, praženo zrnje, fižol, lečo, posušene stročnice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'med, maslo, ovce in kravji sir za Davida in za ljudstvo, ki je bilo z njim, da jedo, kajti rekli so: »Ljudstvo je lačno, izmučeno in žejno v divjini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David je preštel ljudstvo, ki je bilo z njim in nadnje postavil poveljnike nad tisočimi in poveljnike nad stotimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'David je poslal naprej tretjino izmed ljudstva pod Joábovo roko in tretjino pod roko Abišája, Cerújinega sina, Joábovega brata in tretjino pod roko Gitéjca Itája. Kralj je rekel ljudstvu: »Tudi sam bom zagotovo šel z vami naprej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Toda ljudstvo je odgovorilo: »Ne boš šel naprej, kajti če mi pobegnemo, jim ne bo mar za nas. Niti, če nas polovica umre, jim ne bo mar za nas. Toda ti si sedaj vreden deset tisoč nas. Zato je sedaj bolje, da nas okrepiš iz mesta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Kralj jim je rekel: »Storil bom, kar se vam zdi najbolje.« Kralj je stal ob strani velikih vrat, vse ljudstvo pa je prišlo ven po stotih in po tisočih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Kralj je zapovedal Joábu, Abišáju in Itáju, rekoč: »Zaradi mene nežno postopajte z mladeničem, torej z Absalomom.« Vse ljudstvo je slišalo, ko je kralj vsem poveljnikom dal zadolžitev glede Absaloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Tako je ljudstvo odšlo ven na polje zoper Izrael. In bitka je bila v Efrájimskem gozdu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'kjer je bilo izraelsko ljudstvo pobito pred Davidovimi služabniki in tam je bil ta dan velik pokol dvajsetih tisočev mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Kajti tam je bila bitka razpršena preko obličja vse dežele. In gozd je ta dan požrl več ljudstva, kakor jih je požrl meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Absalom je srečal Davidove služabnike. In Absalom je jahal na muli in mula je šla pod debelimi vejami velikega hrasta in njegova glava se je ujela v hrast in vzet je bil gor med nebo in zemljo. Mula, ki je bila pod njim, pa je odšla proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Nek mož je to videl in povedal Joábu ter rekel: »Glej, videl sem Absaloma, visečega na hrastu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Joáb je rekel možu, ki mu je povedal: »Glej, videl si ga in zakaj ga nisi tam udaril k tlom? In jaz bi ti dal deset šeklov srebra in pas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mož je rekel Joábu: »Čeprav bi v svojo roko prejel tisoč šeklov srebra, vendar svoje roke ne bi iztegnil zoper kraljevega sina, kajti slišali smo, da je kralj zadolžil tebe, Abišája in Itája, rekoč: ›Pazite, da se nihče ne dotakne mladeniča Absaloma.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Sicer bi storil hinavstvo zoper svoje lastno življenje, kajti nobena stvar ni skrita pred kraljem in ti sam bi se postavil zoper mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Potem je Joáb rekel: »Ne morem se tako muditi s teboj.« V svojo roko je vzel tri puščice in jih zabodel skozi Absalomovo srce, medtem ko je bil še živ v sredi hrasta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Deset mladeničev, ki so nosili Joábovo bojno opremo, je obdalo Absaloma in ga usmrtilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Joáb je zatrobil s šofarjem in ljudstvo se je vrnilo od zasledovanja za Izraelom, kajti Joáb je zadržal ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Vzeli so Absaloma, ga vrgli v veliko jamo v gozdu in nanj položili zelo velik kup kamenja in ves Izrael je zbežal, vsak k svojemu šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, '§ Torej Absalom si je [še] v svojem življenju vzel in si postavil steber, ki je v kraljevi dolini, kajti rekel je: »Nobenega sina nimam, da ohrani moje ime v spominu.« Steber je poimenoval po svojem lastnem imenu in tako se imenuje do današnjega dne, Absalomov kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Potem je Cadókov sin Ahimáac rekel: »Naj sedaj stečem in kralju prinesem novice, kako se je Gospod maščeval nad njegovimi sovražniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joáb mu je rekel: »Danes ne boš nosil novic, temveč boš novice nosil drug dan. Toda danes ne boš nosil nobenih novic, ker je kraljev sin mrtev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Potem je Joáb rekel Kušíju: »Pojdi, povej kralju, kar si videl.« Kuší se je priklonil Joábu in stekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Potem je Cadókov sin Ahimáac ponovno rekel Joábu: »Toda kakorkoli, prosim te, naj tudi jaz prav tako stečem za Kušíjem.« Joáb pa je rekel: »Čemu bi tekel, moj sin, glede na to, da nimaš pripravljenih novic?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '»Toda kakorkoli,« je rekel, »naj stečem.« Rekel mu je: »Steci.« Potem je Ahimáac stekel po poti ravnine in prehitel Kušíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David je sedel med dvemi velikimi vrati. Stražar pa je šel gor do strehe nad velikimi vrati k obzidju in povzdignil svoje oči in pogledal in glej, mož je tekel sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Stražar je zaklical in povedal kralju. Kralj je rekel: »Če je sam, so novice v njegovih ustih.« Hitro je prišel in se približal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Stražar je zagledal teči drugega moža in stražar je zaklical vratarju ter rekel: »Glej, drug človek teče sam.« Kralj je rekel: »Tudi ta prinaša novice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Stražar je rekel: »Mislim, da je tek sprednjega podoben teku Cadókovega sina Ahimáaca.« Kralj je rekel: »Dober človek je in prihaja z dobrimi novicami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimáac je zaklical in kralju rekel: »Vse je dobro.« S svojim obrazom je padel dol na zemljo pred kraljem in rekel: »Blagoslovljen bodi Gospod, tvoj Bog, ki je izročil ljudi, ki so svojo roko dvignili zoper mojega gospoda kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Kralj je rekel: »Ali je mladenič Absalom varen?« Ahimáac je odgovoril: »Ko je Joáb poslal kraljevega služabnika in mene, tvojega služabnika, sem videl velik hrup, toda nisem vedel, kaj je to bilo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kralj mu je rekel: »Obrni se vstran in stoj tukaj.« Obrnil se je vstran in mirno stal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'In glej, prišel je Kuší. Kuší je rekel: »Novice, moj gospod kralj, kajti Gospod te je ta dan maščeval pred vsemi tistimi, ki so se vzdignili zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kralj je rekel Kušíju: »Je mladenič Absalom varen?« Kuší je odgovoril: »Sovražniki mojega gospoda kralja in vsi, ki se vzdignejo zoper tebe, da ti škodijo, naj bodo, kakor je ta mladenič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Kralj je bil zelo pretresen in odšel gor v sobo nad velikimi vrati in jokal. Medtem ko je šel, je tako govoril: »Oh moj sin Absalom, moj sin, moj sin Absalom! Da bi Bog dal, da bi jaz umrl zate, oh Absalom, moj sin, moj sin!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'To je bilo povedano Joábu: »Glej, kralj joka in žaluje za Absalomom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Zmaga tega dne je bila obrnjena v žalovanje vsemu ljudstvu, kajti ljudstvo je tisti dan slišalo govoriti, kako je bil kralj užaloščen zaradi svojega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Ljudstvo se je tisti dan skrivoma spravilo v mesto, kakor se ljudstvo, ki je osramočeno, odplazi, ko v boju zbeži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Toda kralj je pokril svoj obraz in kralj je jokal z močnim glasom: »Oh moj sin Absalom, oh Absalom, moj sin, moj sin!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Joáb je prišel v hišo h kralju in rekel: »Ta dan si osramotil obraze vseh svojih služabnikov, ki so ta dan rešili tvoje življenje in življenja tvojih sinov in tvojih hčera in življenja tvojih soprog in življenja tvojih priležnic,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'v tem, da ti ljubiš svoje sovražnike in sovražiš svoje prijatelje. Kajti ta dan si oznanil, da se ne oziraš niti na prince niti na služabnike, kajti ta dan zaznavam, da če bi Absalom živel in bi ta dan mi vsi umrli, potem bi ti to dobro ugajalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Zdaj torej vstani, pojdi naprej in tolažilno govori svojim služabnikom, kajti prisegam pri Gospodu, če ne greš naprej, to noč nobeden ne bo ostal s teboj in huje ti bo kakor vse zlo, ki te je zadelo od tvoje mladosti do sedaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Potem je kralj vstal in se usedel pri velikih vratih. In vsemu ljudstvu so povedali, rekoč: »Glejte, kralj sedi pri velikih vratih.« Vse ljudstvo je prišlo pred kralja, kajti Izrael je zbežal vsak mož k svojemu šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Vse ljudstvo je bilo nesložno po vseh Izraelovih rodovih, rekoč: »Kralj nas je rešil iz roke naših sovražnikov in nas osvobodil iz roke Filistejcev; sedaj pa je zaradi Absaloma pobegnil iz dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absalom, ki smo ga mazilili nad seboj, je mrtev v bitki. Zdaj torej, zakaj ne spregovorite besedo o privedbi kralja nazaj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Kralj David je poslal k duhovnikoma Cadóku in Abjatárju, rekoč: »Govorita Judovim starešinam, rekoč: ›Zakaj ste zadnji, da bi privedli kralja nazaj v njegovo hišo, glede na to, da je govor vsega Izraela prišel do kralja, celó k njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vi ste moji bratje, vi ste moje kosti in moje meso. Zakaj ste potem zadnji, da kralja pripeljete nazaj?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'In Amasáju recite: › Ali nisi ti od moje kosti in od mojega mesa? Bog naj mi tako stori in še več, če ne boš nenehno pred menoj poveljnik vojske na Joábovem položaju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'In nagnil je srce vseh Judovih mož, celo kakor srce enega človeka, tako da so kralju poslali to besedo: »Vrni se ti in vsi tvoji služabniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Tako se je kralj vrnil in prišel k Jordanu. In Juda je prišel v Gilgál, da gre, da sreča kralja, da spremi kralja čez Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'In Šimí, Gerájev sin, Benjaminovec, ki je bil iz Bahuríma, je pohitel in prišel dol z Judovimi možmi, da sreča kralja Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Tam je bilo z njim tisoč mož iz Benjamina in Cibá, služabnik Savlove hiše in njegovih petnajst sinov in njegovih dvajset služabnikov z njim in pred kraljem so šli čez Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Tam je šla čez rečna ladja, da prenese čez kraljevo družino in da stori, kar se mu je zdelo dobro. Gerájev sin Šimí pa je padel dol pred kraljem, ko je ta hotel iti čez Jordan');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'in kralju rekel: »Naj moj gospod krivičnosti ne pripiše meni niti se ne spominjaj tega, kar je tvoj služabnik sprevrženo storil tistega dne, ko je moj gospod kralj odšel iz Jeruzalema, da bi si to kralj vzel k srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Kajti tvoj služabnik ve, da sem grešil. Glej, zato sem ta dan prvi prišel iz vse Jožefove hiše, da grem dol, da srečam svojega gospoda kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Toda Cerújin sin Abišáj je odgovoril in rekel: »Ali ne bo Šimí usmrčen zaradi tega, ker je preklinjal Gospodovega maziljenca?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'David pa je rekel: »Kaj imam z vama, vidva, Cerújina sinova, da bi mi bila ta dan nasprotnika? Ali naj bo ta dan kdorkoli usmrčen v Izraelu? Kajti ali ne vem, da sem ta dan kralj nad Izraelom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Zato je kralj rekel Šimíju: »Ne boš umrl.« In kralj mu je prisegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Savlov sin Mefibóšet je prišel dol, da sreča kralja in niti ni obul svojih stopal, niti ni postrigel svoje brade, niti ni umil svojih oblačil od dneva, ko je kralj odpotoval, do dneva, ko je ponovno prišel v miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Pripetilo se je, ko je prišel v Jeruzalem, da sreča kralja, da mu je kralj rekel: »Zakaj nisi šel z menoj, Mefibóšet?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Ta je odgovoril: »Moj gospod, oh kralj, moj služabnik me je zavedel, kajti tvoj služabnik je rekel: ›Osedlal si bom osla, da bom lahko jahal na njem in šel h kralju, ker je tvoj služabnik hrom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'In ta je obrekoval tvojega služabnika mojemu gospodu kralju, toda moj gospod kralj je kakor angel od Boga. Stôri torej, kar je dobro v tvojih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Kajti vsi iz hiše mojega očeta so bili le kot mrtvi možje pred mojim gospodom kraljem, vendar si svojega služabnika postavil med tiste, ki so jedli pri tvoji lastni mizi. Kakšno pravico imam torej, da še kakorkoli kličem h kralju?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Kralj mu je rekel: »Zakaj še govoriš o svojih zadevah? Rekel sem: ›Ti in Cibá si razdelita deželo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Mefibóšet je rekel kralju: »Da, naj on vzame vse, potem ko se je moj gospod kralj v miru ponovno vrnil v svojo lastno hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Gileádec Barziláj je prišel dol iz Roglíma in s kraljem odšel čez Jordan, da ga spremi čez Jordan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Torej Barziláj je bil zelo ostarel mož, star celó osemdeset let. Kralju je priskrbel oskrbo, medtem ko je ta ležal pri Mahanájimu, kajti bil je zelo izjemen človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Kralj je rekel Barziláju: »Z menoj pridi čez in hranil te bom v Jeruzalemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Barziláj pa je kralju rekel: »Doklej bom še živel, da bi s kraljem šel gor v Jeruzalem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Ta dan sem star osemdeset let in ali lahko razločim med dobrim in zlom? Ali lahko tvoj služabnik okuša, kar jem ali kar pijem? Ali še lahko slišim glas prepevajočih mož in prepevajočih žensk? Zakaj bi bil torej tvoj služabnik še breme mojemu gospodu kralju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Tvoj služabnik bo s kraljem šel krajšo pot čez Jordan. Zakaj bi me kralj poplačal s takšno nagrado?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Naj se tvoj služabnik, prosim te, obrne nazaj, da lahko umrem v svojem lastnem mestu in pokopan bom poleg groba svojega očeta in svoje matere. Toda poglej svojega služabnika Kimháma. Naj gre on preko z mojim gospodom kraljem in stôri mu, kakor se ti zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Kralj je odgovoril: »Kimhám bo z menoj šel preko in storil mu bom to, kar se ti zdi dobro in karkoli boš zahteval od mene, to bom storil zate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'In vse ljudstvo je šlo čez Jordan. Ko je kralj prišel čez, je kralj poljubil Barzilája in ga blagoslovil, in ta se je vrnil na svoj lasten kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Potem je kralj odšel naprej h Gilgálu in Kimhám je z njim odšel naprej in vse Judovo ljudstvo je spremilo kralja in tudi polovica Izraelovega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Glej, vsi Izraelovi možje so prišli h kralju in kralju rekli: »Zakaj so te naši bratje, Judovi možje, ukradli in privedli kralja, njegovo družino in vse Davidove može z njim, čez Jordan?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'In vsi možje iz Juda so Izraelovim možem odgovorili: »Ker nam je kralj bližnji sorodnik. Zakaj ste potem jezni zaradi te zadeve? Ali smo sploh jedli na kraljeve stroške? Ali nam je dal kakršnokoli darilo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Izraelovi možje so odgovorili Judovim možem in rekli: »V kralju imamo deset delov in mi imamo več pravice do Davida kakor vi. Čemu nas potem prezirate, da naš nasvet ne bi bil prvi v tem, da smo svojega kralja privedli nazaj?« In besede mož iz Juda so bile trše kakor besede mož iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Zgodilo se je, da je bil tam Beliálov mož, katerega ime je bilo Ševá, Bihríjev sin, Benjaminovec. Ta je zatrobil na šofar in rekel: »Mi nimamo deleža v Davidu niti nimamo dediščine v Jesejevem sinu. Vsak mož k svojim šotorom, oh Izrael.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Tako je vsak mož iz Izraela odšel gor izza Davida in sledil Bihríjevem sinu Ševáju; toda Judovi možje, od Jordana, celo do Jeruzalema, so se trdno pridružili njihovemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'David je prišel k svoji hiši v Jeruzalemu in kralj je vzel deset žensk, svojih priležnic, ki jih je pustil, da varujejo hišo in jih zaprl v ječo in jih hranil, toda ni šel noter k njim. Tako so bile zaprte do dneva svoje smrti, živeče v vdovstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Potem je kralj rekel Amasáju: »V treh dneh mi zberi može iz Juda in ti bodi tu prisoten.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Tako je Amasá odšel, da zbere Judove može, toda zadržal se je dlje kakor postavljen čas, ki mu je bil določen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'David je rekel Abišáju: »Sedaj nam bo Bihríjev sin Ševá storil več škode, kakor jo je storil Absalom. Vzemi služabnike svojega gospoda in ga zasleduj, da si ne pridobi utrjenih mest in nam pobegne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Tam so odšli ven za njim Joábovi možje, Keretéjci, Péletovci in vsi mogočni možje. Odšli so iz Jeruzalema, da zasledujejo Bihríjevega sina Ševája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Ko so bili pri velikem kamnu, ki je v Gibeónu, je Amasá šel pred njimi. Joábova obleka, ki jo je oblekel, je bila opasana k njemu in na njej pas s pritrjenim mečem na svojih ledjih, v svoji nožnici in ko je šel naprej, je ta padel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Joáb je rekel Amasáju: » Ali si pri zdravju, moj brat?« Joáb je z desnico prijel Amasája za brado, da ga poljubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Toda Amasá ni pazil na meč, ki je bil v Joábovi roki. Tako ga je z njim udaril v peto rebro in njegovo notranjost prelil na tla in ni ga ponovno udaril in je umrl. Tako sta Joáb in njegov brat Abišáj zasledovala Bihríjevega sina Ševája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Eden izmed Joábovih mož je stal poleg njega ter rekel: »Kdor je naklonjen Joábu in kdor je za Davida, ta naj gre za Joábom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasá se je valjal v krvi na sredi glavne ceste. In ko je mož videl, da je vse ljudstvo obstalo, je Amasája odstranil z glavne ceste na polje in nanj vrgel oblačilo, ko je videl, da je vsak, kdor je prišel mimo, mirno obstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Ko je bil odstranjen z glavne ceste, je vse ljudstvo odšlo naprej za Joábom, da zasledujejo Bihríjevega sina Ševája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ta je šel skozi vse Izraelove rodove do Abéle in do Bet Maáhe in do vseh Bihríjevcev in zbrani so bili skupaj ter šli tudi za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Prišli so in ga oblegali v Abél Bet Maáhi in nasuli so nasip zoper mesto in le-ta je stal v jarku. In vse ljudstvo, ki je bilo z Joábom, je uničevalo obzidje, da ga zrušijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Potem je modra ženska iz mesta zaklicala: »Poslušajte, poslušajte. Recite, prosim vas, Joábu: ›Pridi blizu sèm, da lahko govorim s teboj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Ko je ta prišel bliže k njej, je ženska rekla: » Ali si ti Joáb?« Odgovoril je: »Jaz sem.« Potem mu je rekla: »Poslušaj besede svoje pomočnice.« Odgovoril je: »Poslušam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Potem je spregovorila, rekoč: »V starih časih so bili navajeni govoriti, rekoč: ›Zagotovo bodo vprašali za nasvet v Abélu,‹ in tako so končali zadevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Jaz sem ena izmed tistih, ki so v Izraelu mirni in zvesti, ti pa si prizadevaš, da uničiš mesto in mater v Izraelu. Zakaj hočeš pogoltniti Gospodovo dediščino?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joáb je odgovoril in rekel: »Daleč bodi to, daleč bodi to od mene, da bi pogoltnil ali uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Zadeva ni takšna, temveč človek z gore Efrájim, po imenu Bihríjev sin Ševá, je vzdignil svojo roko zoper kralja, celó zoper Davida. Samo njega izročite in odšel bom od mesta.« Ženska je rekla Joábu: »Glej, njegova glava ti bo vržena čez obzidje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Potem je ženska, v svoji modrosti, odšla k vsemu ljudstvu. Odsekali so glavo Bihríjevega sina Ševája in jo vrgli ven k Joábu. Ta je zatrobil na šofar in umaknili so se od mesta, vsak mož k svojemu šotoru. In Joáb se je vrnil h kralju v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Torej Joáb je bil nad vso Izraelovo vojsko. Jojadájev sin Benajá je bil nad Keretéjci in nad Péletovci;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adorám je bil nad davkom; Ahilúdov sin Józafat je bil letopisec;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Ševá je bil pisar; Cadók in Abjatár sta bila duhovnika;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'in tudi Jaírovec Irá je bil glavni častnik pri Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'V Davidovih dneh je bila takrat tam tri leta lakota, leto za letom. David je poizvedel od Gospoda. In Gospod je odgovoril: » To je zaradi Savla in zaradi njegove krvoločne hiše, ker je pobil Gibeónce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Kralj je poklical Gibeónce in jim rekel; (torej Gibeónci niso bili izmed Izraelovih otrok, temveč od ostanka Amoréjcev in Izraelovi otroci so jim prisegli. Savel pa si je prizadeval, da jih v svoji gorečnosti do Izraelovih otrok in Juda, pokonča.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Zato je David rekel Gibeóncem: »Kaj naj storim za vas? S čim naj storim spravo, da boste lahko blagoslovili Gospodovo dediščino?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeónci so mu rekli: »Nočemo imeti niti Savlovega srebra, niti zlata, niti njegovih hiš, niti ne boš za nas nikogar ubil v Izraelu.« Rekel je: »Kar boste rekli, to bom storil za vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Kralju so odgovorili: »Od človeka, ki nas je použil in ki je snoval zoper nas, da bi bili mi uničeni od preostanka v vseh Izraelovih pokrajinah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'naj nam bo izročenih sedem mož izmed njegovih sinov in obesili jih bomo Gospodu v Savlovi Gíbei, ki ga je Gospod izbral.« Kralj je rekel: »Dal jih bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Toda kralj je prizanesel Mefibóšetu, sinu Savlovega sina Jonatana, zaradi Gospodove prisege, ki je bila med njima, med Davidom in Savlovim sinom Jonatanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Temveč je kralj vzel dva sinova Ajájeve hčere Ricpe, ki jih je rodila Savlu, Armoníja in Mefibóšeta in pet sinov Savlove hčere Mihále, ki jih je vzgojila za Adriéla, sina Mehólčana Barzilája');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'in izročil jih je v roke Gibeóncem in obesili so jih na hribu pred Gospodom. Vseh sedem je skupaj padlo in bili so usmrčeni v dneh žetve, v prvih dneh, v začetku ječmenove žetve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Ajájeva hči Ricpa pa je vzela vrečevino in jo razgrinjala na skali od začetka žetve, dokler nanje ni kapljala voda z neba in ni pustila niti pticam neba, da na njih počivajo podnevi niti živalim polja ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'To je bilo povedano Davidu, kaj je storila Savlova priležnica, Ajájeva hči Ricpa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'David je odšel in vzel Savlove kosti in kosti njegovega sina Jonatana od ljudi iz Jabéš Gileáda, ki so jih ukradli iz ulice Bet Šeána, kjer so jih Filistejci obesili, ko so Filistejci umorili Savla na Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Od tam je prinesel gor kosti Savla in kosti njegovega sina Jonatana in zbrali so [tudi] kosti tistih, ki so bili obešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Kosti Savla in njegovega sina Jonatana so pokopali v Celi, v Benjaminovi deželi, v mavzoleju njegovega očeta Kiša in izpolnili so vse, kar je kralj zapovedal. Potem se je dal Bog izprositi za deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Poleg tega so Filistejci ponovno imeli vojno z Izraelom in David je šel dol in njegovi služabniki z njim in borili so se zoper Filistejce, David pa je postal slaboten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, '§ Jišbí Benób, ki je bil izmed sinov velikana, čigar sulica je tehtala tristo šeklov brona v teži, je bil opasan z novim mečem, misleč, da bo umoril Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Toda Cerújin sin Abišáj mu je pomagal, udaril Filistejca in ga ubil. Potem so mu Davidovi možje prisegli, rekoč: »Ne boš več šel z nami v bitko, da ne pogasiš Izraelove svetlobe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, '§ Pripetilo se je po tem, da je bila ponovno bitka s Filistejci pri Gobu. Takrat je Hušán Sibeháj ubil Safa, ki je bil izmed sinov velikana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'In tam je bila ponovno bitka s Filistejci v Gobu, kjer je Elhanán, sin Betlehemca Jaaré Orgíma, usmrtil brata Gitéjca Goljata, katerega palica njegove sulice je bila podobna tkalčevemu brunu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, '§ In tam je bila spet bitka v Gatu, kjer je bil mož visoke postave, ki je imel na vsaki roki šest prstov in na vsakem stopalu šest prstov, štiriindvajset po številu, in tudi on je bil rojen velikanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ko je izzival Izraela, ga je Jonatan, sin Davidovega brata Šimája, usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, '§ Ti štirje so bili rojeni velikanu v Gatu in padli so po Davidovi roki in po roki njegovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'David je Gospodu spregovoril besede te pesmi na dan, ko ga je Gospod osvobodil iz roke vseh njegovih sovražnikov in iz Savlove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Rekel je: » Gospod je moja skala in moja trdnjava in moj osvoboditelj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bog moje skale; vanj bom zaupal. On je moj ščit in rog rešitve moje duše, moj visoki stolp in moje zatočišče, moj rešitelj; ti me rešuješ pred nasiljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Klical bom h Gospodu, ki je vreden, da je hvaljen. Tako bom rešen pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Ko so me obdali valovi smrti, so me preplašile poplave brezbožnih ljudi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'bridkosti pekla so me obkrožile, zanke smrti so me ovirale;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'v svoji stiski sem klical h Gospodu in jokal k svojemu Bogu. Iz svojega svetišča je slišal moj glas in moj jok je vstopil v njegova ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Potem se je zemlja stresla in vztrepetala, temelji neba so se premaknili in stresli, ker je bil ogorčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Iz njegovih nosnic se je dvignil dim in ogenj iz njegovih ust je požiral. Z njim so bili vžgani ogorki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Upognil je tudi nebo in prišel dol in tema je bila pod njegovimi stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Jahal je na kerubu in letel. Viden je bil na perutih vetra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Vsenaokrog sebe je naredil paviljone teme, temne vode in goste oblake neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od bleščave pred njim so bili vžgani ognjeni ogorki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Gospod je zagrmel iz nebes in Najvišji je izustil svoj glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Odposlal je puščice in jih razkropil; bliskanje in jih porazil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Prikazale so se morske struge, temelji zemeljskega [kroga] so bili odkriti ob Gospodovem karanju, ob puhu sape iz njegovih nosnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Poslal je od zgoraj, vzel me je, potegnil me je iz mnogih vodá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'osvobodil me je pred mojim močnim sovražnikom in pred tistimi, ki so me sovražili, kajti zame so bili premočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ovirali so me na dan moje katastrofe, toda Gospod je bil moja opora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Prav tako me je privedel na velik kraj. Osvobodil me je, ker se je razveseljeval v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Gospod me je nagradil glede na mojo pravičnost. Poplačal mi je glede na čistost mojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Kajti držal sem se Gospodovih poti in se nisem zlobno oddvojil od svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Kajti vse njegove sodbe so bile pred menoj, in glede njegovih zakonov, se nisem ločil od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Pred njim sem bil tudi iskren in se zadržal pred svojo krivičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Zatorej mi je Gospod poplačal glede na mojo pravičnost; glede na mojo čistost v njegovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Z usmiljenim se boš pokazal usmiljenega in s poštenim človekom se boš pokazal poštenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'S čistim se boš pokazal čistega in s kljubovalnim se boš pokazal neokusnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Stiskano ljudstvo boš rešil, toda tvoje oči so na ošabnih, da jih lahko privedeš dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Kajti ti si moja svetilka, oh Gospod in Gospod bo razsvetlil mojo temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Kajti s teboj sem tekel skozi krdelo, s svojim Bogom sem preskočil zid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Glede Boga, njegova pot je popolna; Gospodova beseda je preizkušena. On je ščit vsem tistim, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Kajti kdo je Bog, razen Gospoda? In kdo je skala, razen našega Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bog je moja sila in moč in mojo pot dela popolno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Moje noge dela podobne nogam košut in me postavlja na moje visoke kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, '§ Moje roke uči bojevanja, tako, da je jeklen lok zlomljen z mojimi lakti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Dal si mi tudi ščit tvoje rešitve duše in tvoja blagost me je naredila velikega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Povečal si moje korake pod menoj, tako, da moja stopala niso zdrsnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Zasledoval sem svoje sovražnike in jih uničil in se nisem ponovno obrnil, dokler jih nisem použil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Použil sem jih in jih ranil, da niso mogli vstati. Da, padli so pod mojimi stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Kajti opasal si me z močjo za boj. Tiste, ki se vzdigujejo zoper mene, si podjarmil pod menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Dal si mi tudi vratove mojih sovražnikov, da lahko uničim tiste, ki me sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Pogledali so, toda nikogar ni bilo, da reši; celó h Gospodu, toda ni jim odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Potem sem jih zdrobil v zemeljski prah, pohodil sem jih kakor ulično blato in jih raztresel naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Osvobodil si me tudi pred prepiri mojega ljudstva, ohranil si me, da bi bil poglavar poganom. Ljudstvo, ki ga nisem poznal, mi bo služilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Tujci se mi bodo podredili; takoj ko slišijo, mi bodo poslušni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Tujci bodo bledeli in prestrašeni bodo iz svojih zaprtih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Gospod živi in blagoslovljena bodi moja skala in povišan bodi Bog skale rešitve moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'To je Bog, ki me maščuje in ki ljudstvo prinaša podme');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'in ki me pelje naprej pred mojimi sovražniki. Prav tako si me dvignil na visoko, nad tiste, ki so vstali zoper mene. Osvobodil si me pred nasilnežem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Zato se ti bom zahvaljeval, oh Gospod, med pogani in prepeval bom hvalnice tvojemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'On je stolp rešitve duš za svojega kralja in izkazuje usmiljenje svojemu maziljencu Davidu in njegovemu semenu na vékomaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Torej to so zadnje Davidove besede. Jesejev sin David je rekel in mož, ki je bil vzdignjen na visoko, maziljenec Jakobovega Boga in prijeten Izraelov psalmist, je rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '» Gospodov Duh je govoril po meni in njegova beseda je bila na mojem jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Izraelov Bog je rekel: ›Izraelova skala mi je spregovorila: ›Kdor vlada nad ljudmi, mora biti pravičen, vladajoč v strahu Božjem.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'In on bo kakor svetloba jutra, ko vzhaja sonce, celó brezoblačno jutro, kakor nežna trava, ki poganja iz zemlje, s čistim sijanjem po dežju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Čeprav moja hiša ni takšna z Bogom, vendar je z menoj sklenil večno zavezo, urejeno v vseh stvareh in zanesljivo. Kajti to je vsa moja rešitev duše in vsa moja želja, čeprav ji on ne daje rasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Toda Beliálovi sinovi bodo vsi izmed njih kakor zavrženo trnje, ker ne morejo biti prijeti z rokami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'toda človek, ki se jih bo dotaknil, mora biti ograjen z železom in palico sulice, in na istem kraju bodo popolnoma požgani z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'To so imena mogočnih mož, ki jih je imel David: Tahkemoníjec, ki je sedel na sedežu, glavni izmed poveljnikov; enak je bil Ezničan Adino. Svojo sulico je vzdignil proti osemstotim, ki jih je enkrat pobil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Za njim je bil Eleazar, sin Dodója, Ahóahovca, z Davidom eden izmed treh mogočnih mož, ko so izzivali Filistejce, ki so bili tam skupaj zbrani za boj in Izraelovi možje so odšli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Ta je vstal in udarjal Filistejce, dokler njegova roka ni bila izmučena in se je njegova roka trdno oklenila meča in Gospod je tisti dan izvršil veliko zmago in ljudstvo se je vrnilo za njim, [vendar] samo da plenijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Za njim je bil Šamá, sin Hararéjca Agaja. Filistejci so bili skupaj zbrani v krdelo, kjer je bil kos polja poln leče in ljudstvo je pobegnilo pred Filistejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Toda on je stal na sredi polja in ga obranil in pobil Filistejce, in Gospod je izvršil veliko zmago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Trije izmed tridesetih vodij so odšli dol in prišli k Davidu v času žetve, k votlini Adulám, in krdelo Filistejcev je taborilo v dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David je bil takrat v utrdbi in garnizija Filistejcev je bila takrat v Betlehemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'David je hrepenel in rekel: »Oh, da bi mi nekdo dal piti od vode betlehemskega vodnjaka, ki je pri velikih vratih!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Trije mogočni možje so predrli vojsko Filistejcev in zajeli vodo iz betlehemskega vodnjaka, ki je bil pri velikih vratih in jo vzeli ter jo prinesli k Davidu, pa vendar ni hotel piti od nje, temveč jo je izlil Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Rekel je: »Daleč naj bo od mene, oh Gospod, da bi to storil. Mar ni to kri mož, ki so šli v nevarnosti za svoja življenja?« Zato tega ni hotel piti. Te stvari so storili ti trije mogočni možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abišáj, Joábov brat, Cerújin sin, je bil vodja med tremi. Svojo sulico je dvignil proti tristotim in jih pobil in imel je ime med tremi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Mar ni bil on najbolj častitljiv izmed treh? Zato je bil njihov poveljnik, vendar prvih treh ni dosegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Jojadájev sin Benajá, sin hrabrega moža iz Kabceéla, ki je storil mnogo dejanj, je usmrtil dva, levom podobna moža iz Moába. Odšel je tudi dol in ubil leva v sredi jame v času snega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ubil je Egipčana, čednega moža. Egipčan je imel v svoji roki sulico, toda dol k njemu je šel s palico in iztrgal sulico iz Egipčanove roke in ga ubil z njegovo lastno sulico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Te stvari je storil Jojadájev sin Benajá in imel je ime med tremi mogočnimi možmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Bil je častitljivejši od tridesetih, vendar prvih treh ni dosegel. In David ga je postavil nad svojo stražo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Joábov brat Asaél je bil eden izmed tridesetih: Dodójev sin Elhanán iz Betlehema,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Haródec Šamá, Haródec Eliká,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Paltičan Helec, Irá, sin Tekójčana Ikéša,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Anatóčan Abiézer, Hušán Mebunáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Ahóahovec Calmón, Netófčan Mahráj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, sin Netófčana Baanája, Ribájev sin Itáj iz Gíbee Benjaminovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Piratónec Benajá, Hidáj iz Gáaševih potokov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Arbatéjec Abialbón, Barhuméjec Azmávet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Šaalbónec Eljahbá, izmed Jašénovih sinov Jonatan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Hararéjec Šamá, Ahiám, sin Hararéjca Šarárja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifélet, sin Ahasbája, sin Maahčána, Eliám, sin Gilčana Ahitófela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Karmélčan Hecrai, Arbéjec Paarai,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Natánov sin Jigál iz Cobe, Gádovec Baní,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Amónec Celek, Beeróčan Nahráj, nosilec bojne opreme Cerújinega sina Joába,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Jéterjevec Irá, Jéterjevec Garéb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Hetejec Urijá; skupaj sedemintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'In ponovno je bila vžgana Gospodova jeza zoper Izrael in zoper njih je napeljal Davida, da reče: »Pojdite, preštejte Izraela in Juda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Kajti kralj je rekel Joábu, poveljniku vojske, ki je bila z njim: »Pojdite sedaj skozi vse Izraelove rodove, od Dana, celo do Beeršébe in preštejte ljudstvo, da bom lahko vedel število ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joáb pa je rekel kralju: »Torej Gospod, tvoj Bog, [naj] doda ljudstvu, kolikokrat že, stokratno in da bodo oči mojega gospoda kralja lahko to videle, toda zakaj se moj gospod kralj razveseljuje v tej stvari?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Vendar je kraljeva beseda prevladala zoper Joába in zoper poveljnike vojske. In Joáb in poveljniki vojske so odšli izpred kraljeve prisotnosti, da preštejejo Izraelsko ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Prečkali so Jordan in se utaborili v Aroêrju, na desni strani mesta, ki leži v sredi reke Gad in proti Jazêrju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Potem so prišli v Gileád in v deželo Tahtím Hodší; in prišli so v Dan Jáan in okoli k Sidónu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'in prišli so k močnemu oporišču Tir in k vsem mestom Hivéjcev in Kánaancev in odšli so ven k južnemu Judu, celó do Beeršébe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Torej ko so šli skozi vso deželo, so ob koncu devetih mesecev in dvajsetih dni prišli v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Joáb je kralju izročil vsoto števila ljudstva. Tam je bilo v Izraelu osemsto tisoč hrabrih mož, ki so izdirali meč in Judovih mož je bilo petsto tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Davidovo srce pa ga je udarilo, potem ko je imel ljudstvo prešteto. David je rekel Gospodu: »Silno sem grešil v tem, kar sem storil in sedaj te rotim, oh Gospod, odvzemi krivičnost svojega služabnika, kajti postopal sem zelo nespametno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Kajti ko je bil David zjutraj pokonci, je k Davidovemu vidcu, preroku Gadu, prišla beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '»Pojdi in reci Davidu: ›Tako govori Gospod, ponujam ti tri stvari. Izberi eno izmed njih, da ti jo lahko storim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Tako je Gad prišel k Davidu in mu povedal ter mu rekel: »Ali naj pride k tebi, v tvojo deželo, sedem let lakote? Ali hočeš tri mesece bežati pred svojimi sovražniki, medtem ko te zasledujejo? Ali, da bo v tvoji deželi tridnevna kužna bolezen? Sedaj se posvetuj in glej, kakšen odgovor naj vrnem tistemu, ki me je poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David je Gadu rekel: »V veliki stiski sem. Naj torej pademo v Gospodovo roko, kajti njegova usmiljenja so velika in naj ne padem v roko človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Tako je Gospod nad Izrael poslal kužno bolezen od jutra celo do določenega časa in tam je umrlo izmed ljudstva, od Dana, celo do Beeršébe, sedemdeset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Ko je angel svojo roko iztegnil nad Jeruzalem, da ga uniči, se je Gospod pokesal od zla in rekel angelu, ki je uničeval ljudstvo: »Dovolj je. Zadrži sedaj svojo roko.« Gospodov angel pa je bil pri kraju mlatišča Jebusejca Arávna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'David je spregovoril Gospodu, ko je videl angela, ki je udaril ljudstvo in rekel: »Glej! Grešil sem, storil sem zlobno. Toda te ovce, kaj so storile? Naj bo tvoja roka, prosim te, zoper mene in zoper hišo mojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Gad je ta dan prišel k Davidu in mu rekel: »Pojdi gor, zgradi oltar Gospodu na mlatišču Jebusejca Arávna.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'David je, glede na Gadovo izjavo, odšel gor, kakor je Gospod ukazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Arávna je pogledal in zagledal kralja ter njegove služabnike prihajati proti njemu. Arávna je odšel ven in se upognil pred kraljem na svoj obraz k tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Arávna je rekel: »Čemu je moj gospod kralj prišel k svojemu služabniku?« David je rekel: »Da od tebe kupim mlatišče, da zgradim oltar Gospodu, da bo kuga lahko ustavljena pred ljudstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arávna je rekel Davidu: »Naj moj gospod kralj vzame in daruje, kar se mu zdi dobro. Glej, tukaj so voli za žgalno daritev in mlatilne priprave in druge volovske priprave za drva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Vse te stvari je Arávna, kakor kralj, dal kralju. In Arávna je rekel kralju: » Gospod, tvoj Bog, [naj] te sprejme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Kralj pa je Arávnu rekel: »Ne; temveč bom to zagotovo kupil od tebe za ceno. Niti ne bom daroval žgalne daritve Gospodu, svojemu Bogu od tega, kar me nič ne stane.« Tako je David kupil mlatišče in vole za petdeset šeklov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'David je tam zgradil oltar Gospodu in daroval žgalne daritve in mirovne daritve. Tako je bil Gospod izprošen za deželo in kuga se je ustavila pred Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Torej kralj David je bil zelo star in zvrhan v letih in pokrivali so ga z oblačili, toda ni se mogel ogreti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Zato so mu njegovi služabniki rekli: »Naj bo za mojega gospoda kralja poiskana mlada devica in naj ta stoji pred kraljem in naj ga neguje in naj leži v tvojem naročju, da se moj gospod kralj lahko ogreje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Tako so po vseh Izraelovih pokrajinah iskali za lepo gospodično in našli Šunémko Abišágo in jo privedli h kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Gospodična je bila zelo lepa, negovala je kralja in mu služila, toda kralj je ni spoznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Potem se je Hagítin sin Adoníja povišal, rekoč: »Jaz bom kralj,« in si pripravil bojne vozove, konjenike in petdeset mož, da tečejo pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Njegov oče pa ga nikoli ni razžalil v tem, da bi rekel: »Čemu si tako storil?« In ta je bil tudi zelo čeden mož in njegova mati ga je rodila za Absalomom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Ta se je posvetoval s Cerújinim sinom Joábom in z duhovnikom Abjatárjem in sledeč Adoníju sta mu pomagala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Toda duhovnik Cadók, Jojadájev sin Benajá, prerok Natán, Šimí, Reí in mogočni možje, ki so pripadali Davidu, niso bili z Adoníjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adoníja je pri kamnu Zohélet, ki je pri En Rogelu, zaklal ovce, vole in pitano živino ter poklical vse svoje brate, kraljeve sinove in vse Judove ljudi, kraljeve služabnike,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'toda preroka Natána, Benajá, mogočnih mož in svojega brata Salomona ni poklical.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Zato je Natán spregovoril Salomonovi materi Batšébi, rekoč: »Mar nisi slišala, da Hagítin sin Adoníja kraljuje, naš gospod David pa tega ne ve?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Zdaj torej pridi, prosim te, naj ti dam nasvet, da boš lahko rešila svoje lastno življenje in življenje svojega sina Salomona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Pojdi in vstopi h kralju Davidu ter mu reci: ›Mar nisi ti, moj gospod, oh kralj, prisegel pri svoji pomočnici, rekoč: ›Zagotovo bo tvoj sin Salomon kraljeval za menoj in bo sedel na mojem prestolu? Zakaj potem kraljuje Adoníja?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Glej, medtem ko boš še tam govorila s kraljem, bom tudi jaz vstopil za teboj in potrdil tvoje besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Batšéba je odšla h kralju v sobo. Kralj pa je bil zelo star in Šunémka Abišága je služila kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Batšéba se je upognila in se globoko priklonila. Kralj je rekel: »Kaj želiš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Rekla mu je: »Moj gospod, pri Gospodu, svojem Bogu, si prisegel svoji pomočnici, rekoč: ›Tvoj sin Salomon bo zagotovo kraljeval za menoj in bo sedel na mojem prestolu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Sedaj glej, kraljuje Adoníja in sedaj, moj gospod kralj, ti tega ne veš, [namreč]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'zaklal je vole, pitano živino in ovc v obilju ter sklical vse kraljeve sinove, duhovnika Abjatárja in poveljnika vojske Joába, toda tvojega služabnika Salomona ni poklical.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Ti pa, moj gospod, oh kralj, oči celotnega Izraela so na tebi, da bi jim ti povedal, kdo bo sedel na prestolu mojega gospoda kralja za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Sicer se bo zgodilo, ko bo moj gospod kralj zaspal s svojimi očeti, da bova jaz in moj sin Salomon šteta [za] prestopnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Glej, medtem ko je še govorila s kraljem, je vstopil tudi prerok Natán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Kralju so povedali, rekoč: »Glej, prerok Natán.« Ko je ta vstopil pred kralja, se je pred kraljem upognil s svojim obrazom do tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Natán je rekel: »Moj gospod, oh kralj, ali si rekel: ›Adoníja bo kraljeval za menoj in on bo sedel na mojem prestolu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Kajti ta dan je odšel dol in v obilju zaklal vole, rejeno živino in ovce ter sklical vse kraljeve sinove, poveljnike vojske in duhovnika Abjatárja; in glej, jedo in pijejo pred njim ter govorijo: ›Živel kralj Adoníja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Toda mene, celó mene, tvojega služabnika, duhovnika Cadóka, Jojadájevega sina Benajá in tvojega služabnika Salomona ni poklical.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ali je ta stvar storjena s strani mojega gospoda kralja in je nisi pokazal svojemu služabniku, kdo naj bi sedel na prestolu mojega gospoda kralja za njim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Potem je kralj David odgovoril in rekel: »Pokličite mi Batšébo.« Prišla je v kraljevo prisotnost in obstala pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Kralj je prisegel in rekel: » Kakor Gospod živi, ki je mojo dušo odkupil iz vse tesnobe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'celo kakor sem ti prisegel pri Gospodu, Izraelovem Bogu, rekoč: ›Zagotovo bo tvoj sin Salomon kraljeval za menoj in on bo namesto mene sedel na mojem prestolu, celo tako bom zagotovo storil ta dan.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Potem se je Batšéba s svojim obrazom pripognila do zemlje, počastila kralja in rekla: »Naj moj gospod kralj David živi na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Kralj David je rekel: »Pokliči mi duhovnika Cadóka, preroka Natána in Jojadájevega sina Benajá.« In prišli so pred kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Kralj jim je tudi rekel: »S seboj vzemite služabnike svojega gospoda in naredite, da moj sin Salomon jezdi na moji lastni muli in ga privedite dol do Gihona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Duhovnik Cadók in prerok Natán naj ga tam mazilita za kralja nad Izraelom in zatrobite s šofarjem ter recite: ›Živel kralj Salomon.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Potem boste za njim prišli gor, da bo lahko prišel in sedel na moj prestol, kajti on bo kralj namesto mene. Določil sem ga, da bo vladar nad Izraelom in nad Judom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Jojadájev sin Benajá je kralju odgovoril in rekel: »Amen. Tudi Gospod, Bog mojega gospoda kralja, tako pravi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Kakor je bil Gospod z mojim gospodom kraljem, celo tako naj bo s Salomonom in njegov prestol naj naredi večjega od mojega gospoda, kralja Davida.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Tako so duhovnik Cadók, prerok Natán in Jojadájev sin Benajá, Keretéjci in Péletovci odšli dol in dali Salomonu, da je jahal na muli kralja Davida in ga privedli h Gihonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Duhovnik Cadók je iz šotorskega svetišča vzel rog olja in mazilil Salomona. Zatrobili so na šofar in vse ljudstvo je reklo: »Živel kralj Salomon.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Vse ljudstvo je prišlo za njim gor in ljudstvo je piskalo s piščalmi in se razveseljevalo z veliko radostjo, tako da se je zemlja od njihovega glasu trgala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Adoníja in vsi gostje, ki so bili z njim, ko so to slišali, so nehali jesti. Ko je Joáb zaslišal zvok šofarja, je rekel: »Čemu je ta hrup iz mesta, [kot bi bila] vstaja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Medtem ko je še govoril, glej, je prišel Jonatan, sin duhovnika Abjatárja in Adoníja mu je rekel: »Vstopi, kajti hraber mož si in prinašaš dobre novice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonatan je odgovoril in Adoníju rekel: »Resnično, naš gospod, kralj David, je Salomona postavil za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'In kralj je z njim poslal duhovnika Cadóka, preroka Natána, Jojadájevega sina Benajá, Keretéjce in Péletovce in dali so mu, da je jahal na kraljevi muli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Duhovnik Cadók in prerok Natán sta ga mazilila za kralja pri Gihonu in od tam so prišli gor, veseleč se, tako da je mesto ponovno odzvanjalo. To je hrup, ki ste ga slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'In Salomon tudi sedi na prestolu kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Še več, kraljevi služabniki so prišli, da blagoslovijo našega gospoda, kralja Davida, rekoč: ›Bog naj Salomonovo ime naredi boljše od tvojega imena in naj njegov prestol naredi večji kakor tvoj prestol.‹ In kralj se je na postelji globoko priklonil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Tudi tako je kralj rekel: ›Blagoslovljen bodi Gospod, Izraelov Bog, ki je danes dal nekomu sedeti na mojem prestolu in moje oči celo to vidijo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Vsi gostje, ki so bili z Adoníjem, so bili prestrašeni in vzdignili so se ter odšli, vsak mož svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adoníja pa se je bal zaradi Salomona, se vzdignil, odšel in se oprijel oltarnih rogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'To je bilo povedano Salomonu, rekoč: »Glej, Adoníja se boji kralja Salomona, kajti glej, oprijel se je oltarnih rogov, rekoč: ›Naj mi ta dan kralj Salomon priseže, da svojega služabnika ne bo usmrtil z mečem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomon je rekel: »Če se bo izkazal vrednega moža, ne bo niti las od njega padel na zemljo, toda če bo v njem najdena zlobnost, bo umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Tako je kralj Salomon poslal in privedli so ga dol od oltarja. In prišel je ter se priklonil kralju Salomonu in Salomon mu je rekel: »Pojdi k svoji hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Torej Davidovi dnevi so se približali, da naj bi umrl in svojemu sinu Salomonu je naročil, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '»Jaz grem pot vse zemlje. Bodi torej močan in se izkaži moža');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'in ohrani naročilo Gospoda, svojega Boga, da hodiš po njegovih poteh, da ohranjaš njegove zakone, njegove zapovedi, njegove sodbe in njegova pričevanja, kakor je zapisano v Mojzesovi postavi, da boš lahko uspeval v vsem, kar delaš in kamorkoli se obrneš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'da bo Gospod lahko nadaljeval svojo besedo, ki jo je govoril glede mene, rekoč: ›Če tvoji otroci pazijo na svojo pot, da hodijo pred menoj v resnici, z vsem svojim srcem in z vso svojo dušo, tebi ne bo odrezan,‹ je rekel, ›noben mož na Izraelovem prestolu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Poleg tega tudi veš, kaj mi je storil Cerújin sin Joáb in kaj je storil dvema poveljnikoma Izraelove vojske, Nerovemu sinu Abnêrju in Jeterjevemu sinu Amasáju, ki ju je ubil in vojno kri prelil v miru in vojno kri položil na svoj pas, ki je bil okrog njegovih ledij in na njegove čevlje, ki so bili na njegovih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Stori torej glede na svojo modrost in ne dopusti, da bi njegova osivela glava šla v miru dol v podzemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Toda izkazuj prijaznost sinovom Gileádca Barzilája in naj bodo izmed tistih, ki jedo pri tvoji mizi, kajti tako so prišli k meni, ko sem pobegnil zaradi tvojega brata Absaloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Glej, s seboj imaš Šimíja, Gerájevega sina, Benjaminovca iz Bahuríma, ki me je preklinjal z bolečim prekletstvom na dan, ko sem odšel v Mahanájim, toda prišel je dol, da me sreča pri Jordanu in prisegel sem mu pri Gospodu, rekoč: ›Ne bom te usmrtil z mečem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Zdaj ga torej ne imej brez krivde, kajti moder človek si in veš, kaj mu moraš storiti, temveč njegovo osivelo glavo s krvjo privedi dol k podzemlju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Tako je David zaspal s svojimi očeti in bil pokopan v Davidovem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Dni, ko je David kraljeval nad Izraelom, je bilo štirideset let. Sedem let je kraljeval v Hebrónu, triintrideset let pa je kraljeval v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Potem se je Salomon usedel na prestol svojega očeta Davida in njegovo kraljestvo je bilo silno utrjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Hagítin sin Adoníja je prišel k Salomonovi materi Batšébi. Rekla je: »Prihajaš miroljubno?« Rekel je: »Miroljubno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Poleg tega je rekel: »Nekaj ti imam povedati.« Rekla je: »Povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Rekel je: »Veš, da je bilo kraljestvo moje in da je ves Izrael svoje obraze naravnal name, da naj bi jaz kraljeval, vendar se je kraljestvo zaobrnilo in postalo bratovo, kajti njegovo je bilo od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Sedaj od tebe prosim eno prošnjo, ne zavrni me.« Rekla mu je: »Povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Rekel je: »Spregovori, prosim te, kralju Salomonu (kajti ne bo ti rekel ne), da mi da za ženo Šunémko Abišágo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Batšéba je rekla: »Dobro, zate bom govorila kralju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Batšéba je torej šla h kralju Salomonu, da mu govori za Adoníja. Kralj je vstal, da jo sreča in se ji priklonil, se usedel na svoj prestol in dal postaviti sedež za kraljevo mater in usedla se je na njegovo desnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Potem je rekla: »Od tebe želim eno majhno prošnjo, prosim te, ne reci mi ne.« Kralj ji je rekel: »Vprašaj, moja mati, kajti jaz ti ne bom rekel ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Rekla je: »Naj bo Šunémka Abišága dana tvojemu bratu Adoníju za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Kralj Salomon je odgovoril svoji materi in rekel: »Zakaj prosiš za Adoníja Šunémko Abišágo? Prosi zanj tudi kraljestvo, kajti on je moj starejši brat; celo zanj in za duhovnika Abjatárja in za Cerújinega sina Joába.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Potem je kralj Salomon prisegel pri Gospodu, rekoč: »Bog naj mi tako stori in še več, če ni Adoníja te besede spregovoril zoper svoje lastno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Zdaj torej kakor živi Gospod, ki me je utrdil in me postavil na prestol mojega očeta Davida in ki mi je naredil hišo, kakor je obljubil, bo ta dan Adoníja usmrčen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Kralj Salomon je poslal po roko Jojadájevega sina Benajá in ta je padel nanj, da je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Duhovniku Abjatárju pa je kralj rekel: »Pojdi v Anatót, k svojim lastnim poljem, kajti vreden si smrti, toda tokrat te ne bom usmrtil, ker pred mojim očetom Davidom nosiš skrinjo Gospoda Boga in ker si bil prizadet v vsem, s čimer je bil prizadet moj oče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Tako je Salomon vrgel ven Abjatárja, da ne bi bil duhovnik Gospodu, da je lahko izpolnil Gospodovo besedo, ki jo je govoril glede Élijeve hiše v Šilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Potem so do Joába prišle novice, kajti Joáb se je obrnil za Adoníjem, čeprav se ni obrnil za Absalomom. Joáb je pobegnil h Gospodovemu šotorskemu svetišču in se oprijel oltarnih rogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'To je bilo povedano kralju Salomonu, da je Joáb pobegnil v Gospodovo šotorsko svetišče in glej, pri oltarju je. Potem je Salomon poslal Jojadájevega sina Benajá, rekoč: »Pojdi, padi nanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benajá je prišel v Gospodovo šotorsko svetišče ter mu rekel: »Tako govori kralj: ›Pridi naprej.‹« Rekel je: »Ne, temveč bom tukaj umrl.« Benajá je kralju ponovno prinesel besedo, rekoč: »Tako je rekel Joáb in tako mi je odgovoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kralj mu je rekel: »Stôri, kakor je rekel, padi nanj in ga pokoplji, da boš lahko od mene in od hiše mojega očeta odvzel nedolžno kri, ki jo je prelil Joáb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Gospod bo njegovo kri povrnil na njegovo lastno glavo, ker je padel na dva moža, pravičnejša in boljša kakor on in ju umoril z mečem, moj oče David pa ni vedel o tem, namreč Nerovega sina Abnêrja, poveljnika Izraelove vojske in Jeterjevega sina Amasája, poveljnika Judove vojske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Njuna kri se bo torej povrnila na Joábovo glavo in na glavo njegovega semena na veke, toda nad Davidom, nad njegovim semenom, nad njegovo hišo in nad njegovim prestolom bo mir na veke od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Tako je Jojadájev sin Benajá odšel gor, padel nanj, ga usmrtil in pokopan je bil v svoji lastni hiši v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Na njegovo mesto, čez vojsko, je kralj postavil Jojadájevega sina Benajá, na Abjatárjevo mesto pa je kralj postavil duhovnika Cadóka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Kralj je poslal in poklical Šimíja ter mu rekel: »Zgradi si hišo v Jeruzalemu in tam prebivaj in ne hodi kamorkoli od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Kajti tako bo, da na dan, ko pojdeš ven in preideš potok Kidron, boš zagotovo vedel, da boš zagotovo umrl. Tvoja kri bo na tvoji lastni glavi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Šimí je rekel kralju: »Ta beseda je dobra, kakor je rekel moj gospod kralj, tako bo tvoj služabnik storil.« In Šimí je mnogo dni prebival v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Pripetilo pa se je ob koncu treh let, da sta dva izmed Šimíjevih služabnikov pobegnila k Maahájevemu sinu Ahíšu, kralju iz Gata. Šimíju so povedali, rekoč: »Glej, tvoja služabnika sta v Gatu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Šimí je vstal, osedlal svojega osla in šel v Gat, k Ahíšu, da poišče svoja služabnika. Šimí je odšel in svoja služabnika privedel iz Gata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'To je bilo povedano Salomonu, da je Šimí iz Jeruzalema odšel v Gat in ponovno prišel nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Kralj je poslal in dal poklicati Šimíja ter mu rekel: »Mar te nisem primoral, da prisežeš pri Gospodu in ti izpričal, rekoč: ›Zagotovo vedi, na dan, ko greš ven in hodiš kakorkoli naokoli, da boš zagotovo umrl?‹ In rekel si mi: ›Beseda, ki sem jo slišal, je dobra.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Zakaj se potem nisi držal Gospodove prisege in zapovedi, ki sem ti jo naročil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Kralj je poleg tega Šimíju rekel: »Ti poznaš vso zlobnost, ki je znana tvojemu srcu, ki si jo storil mojemu očetu Davidu, zato bo Gospod tvojo zlobnost povrnil na tvojo lastno glavo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'in kralj Salomon bo blagoslovljen in Davidov prestol bo pred Gospodom utrjen na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Tako je kralj zapovedal Jojadájevemu sinu Benajáju, ki je odšel ven in padel nanj, da je ta umrl. In kraljestvo je bilo utrjeno v Salomonovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Salomon je sklenil svaštvo s faraonom, egiptovskim kraljem in vzel faraonovo hčer ter jo privedel v Davidovo mesto, dokler ni končal gradnje svoje lastne hiše, Gospodove hiše in obzidja okoli Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Vendar pa je ljudstvo žrtvovalo na visokih krajih, ker do tistih dni ni bilo zgrajene hiše Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomon je ljubil Gospoda, hodeč po zakonih svojega očeta Davida, vendar je žrtvoval in zažigal kadilo na visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Kralj je odšel do Gibeóna, da tam žrtvuje, kajti to je bil ugleden visok kraj [in] na tistem oltarju je Salomon daroval tisoč žgalnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'V Gibeónu se je Gospod v sanjah ponoči prikazal Salomonu in Bog je rekel: »Prosi, kaj naj ti dam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomon je rekel: »Svojemu služabniku, mojemu očetu Davidu, si izkazal veliko milost, kakor je hodil pred teboj v resnici, v pravičnosti in v iskrenosti srca s teboj in si zanj ohranil to veliko prijaznost, da si mu dal sina, da sedi na njegovem prestolu, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Sedaj, oh Gospod, moj Bog, svojega služabnika si naredil kralja namesto mojega očeta Davida. Jaz pa sem samo majhen otrok. Ne vem kako odhajati ali prihajati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Tvoj služabnik je v sredi tvojega ljudstva, ki si ga izbral, velikega ljudstva, ki zaradi množice ne more biti niti našteto niti prešteto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Daj torej svojemu služabniku razumevajoče srce, da sodi tvoje ljudstvo, da bom lahko razločeval med dobrim in slabim, kajti kdo je zmožen soditi to tvoje tako veliko ljudstvo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Govor je ugajal Gospodu, da je Salomon prosil to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Bog mu je rekel: »Ker si prosil to stvar in zase nisi prosil dolgega življenja, niti zase nisi prosil bogastev, niti nisi prosil za življenja svojih sovražnikov, temveč si zase prosil razumevanje, da razsojaš sodbo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'glej, storil sem glede na tvoje besede, glej, dal sem ti modrost in razumevajoče srce, tako da pred teboj ni bilo nikogar podobnega tebi niti za teboj ne bo vstal nihče podoben tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Dal sem ti tudi to, česar nisi prosil, tako bogastva kakor čast, tako da vse tvoje dni med kralji ne bo nobenega kralja podobnega tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Če boš hodil po mojih poteh, da varuješ moje zakone in moje zapovedi, kakor je hodil tvoj oče David, potem bom podaljšal tvoje dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Salomon se je prebudil in glej, to so bile sanje. Prišel je v Jeruzalem, stopil pred skrinjo Gospodove zaveze in daroval žgalne daritve, mirovne daritve in vsem svojim služabnikom priredil gostijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Potem sta prišli h kralju dve ženski, ki sta bili pocestnici in obstali pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Ena ženska je rekla: »Oh moj gospod, jaz in ta ženska stanujeva v eni hiši in rodila sem otroka, z njo v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Tretji dan pa se je pripetilo, potem ko sem rodila, da je tudi ta ženska rodila in bili sva skupaj. Z nama v hiši ni bilo nobenega tujca, razen naju dveh v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Otrok te ženske pa je ponoči umrl, ker ga je prekrila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Ona pa je opolnoči vstala in mojega sina vzela od mene, medtem ko je tvoja pomočnica spala in si ga položila v svoje naročje, svojega mrtvega pa je položila v moje naročje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Ko sem zjutraj vstala, da podojim svojega otroka, glej, je bil ta mrtev. Toda ko sem to zjutraj preudarjala, glej, to ni bil moj sin, ki sem ga rodila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Druga ženska pa je rekla: »Ne, temveč živi je moj sin, mrtvi pa je tvoj sin.« Ta pa je rekla: »Ne, temveč mrtvi je tvoj sin, živi pa je moj sin.« Tako sta govorili pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Potem je kralj rekel: »Ena pravi: ›Ta je moj sin, ki živi, tvoj sin pa je mrtev.‹ Druga pa pravi: ›Ne, temveč je mrtvi tvoj sin, moj sin pa živi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Kralj je rekel: »Prinesite mi meč.« Meč so prinesli pred kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Kralj je rekel: »Živega otroka razdelite na pol in polovico dajte eni, polovico pa drugi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Potem je kralju spregovorila ženska, od katere je bil živi otrok, kajti njena notranjost je hrepenela za svojim sinom in rekla: »Oh moj gospod, izročite ji živega otroka in nikakor ga ne ubijte.« Druga pa je rekla: »Naj ne bo niti moj niti tvoj, temveč ga razdelite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Potem je kralj odgovoril in rekel: »Njej dajte živega otroka in ga nikakor ne ubijte. Ona je njegova mati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Ves Izrael je slišal o sodbi, ki jo je kralj razsodil in bali so se kralja, kajti videli so, da je bila v njem Božja modrost, da razsoja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Tako je bil kralj Salomon kralj nad vsem Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'To so bili princi, ki jih je imel: Azarjá, sin duhovnika Cadóka;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Šišájeva sinova Elihóref in Ahíja, pisarja; Ahilúdov sin Józafat, letopisec;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Jojadájev sin Benajá je bil nad vojsko; Cadók in Abjatár sta bila duhovnika;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Natánov sin Azarjá, je bil nad častniki; Natánov sin Zabúd je bil glavni častnik in kraljev prijatelj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahišár je bil nad družino in Abdájev sin Adonirám je bil nad davkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomon je imel dvanajst častnikov nad vsem Izraelom, ki so zagotavljali živež za kralja in njegovo družino. Vsak človek je v svojem mesecu leta pripravljal preskrbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'To so njihova imena: Hurov sin na gori Efrájim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekerjev sin v Makácu, Šaalbímu, Bet Šemešu in Elón Bet Hanánu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Hesedov sin v Arubótu – njemu je pripadal Sohó in vsa Heferjeva dežela;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadábov sin v vseh področjih Dora, ki je imel za ženo Salomonovo hčer Tafáto;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Ahilúdov sin Baaná – njemu so pripadali Taanáh, Megída in ves Bet Šeán, ki je pri Caretánu pod Jezreélom, od Bet Šeána do Abél Mehóle, celó do kraja, ki je onkraj Jokneáma;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Geberjev sin v Ramót Gileádu – njemu so pripadala mesta Manásejevega sina Jaíra, ki so v Gileádu, njemu je pripadalo tudi območje Argóba, ki je v Bašánu, šestdeset velikih mest z obzidji in bronastimi zapahi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Idójev sin Ahinadáb je imel Mahanájim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimáac je bil v Neftáliju, za ženo je vzel tudi Salomonovo hčer Basemáto;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Hušájev sin Baaná je bil v Aserju in v Alótu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Parúahov sin Józafat v Isahárju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Elájev sin Šimí v Benjaminu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Uríjev sin Geber je bil v deželi Gileád, v deželi amoréjskega kralja Sihóna in bašánskega kralja Oga in ta je bil edini častnik, ki je bil v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda in Izrael sta bila številna, tako obilna, kakor je peska ob morju; jedli so, pili in se veselili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Salomon je kraljeval nad vsemi kraljestvi od reke do filistejske dežele in do egiptovske meje. Prinašali so darila in vse dni svojega življenja služili Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Salomonova preskrba za en dan je bila trideset mer fine moke, šestdeset mer moke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'deset rejenih volov, dvajset volov s pašnikov in sto ovc, poleg jelenov, srnjakov, damjakov in pitane perjadi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Kajti imel je gospostvo nad vsem področjem na tej strani reke, od Tifsáha celo do Gaze, nad vsemi kralji na tej strani reke, in imel je mir na vseh straneh okoli sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Juda in Izrael sta prebivala varno, vsak mož pod svojo trto in pod svojim figovim drevesom, od Dana, celo do Beeršébe, vse Salomonove dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Salomon je imel štirideset tisoč konjskih boksov za svoje bojne vozove in dvanajst tisoč konjenikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Ti častniki so zagotavljali živež za kralja Salomona in za vse, ki so prišli k Salomonovi mizi, vsak mož v svojem mesecu. Ničesar jim ni primanjkovalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Tudi ječmen in slamo za konje in [enogrbe] velblode so prinašali na kraj, kjer so bili častniki, vsak moški glede na svojo zadolžitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Bog je dal Salomonu modrost in razumevanje, silno mnogo in širino srca, celo kakor je peska, ki je na morski obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Salomonova modrost je presegala modrost vseh otrok vzhodne dežele in vso modrost Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Kajti bil je modrejši od vseh ljudi; od Ezráhovca Etána in Mahólovih sinov, Hemána, Kalkóla in Dardá in njegov sloves je bil v vseh narodih naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Izrekel je tri tisoč pregovorov in njegovih pesmi je bilo tisoč in pet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Govoril je o drevesih, od cedrovega drevesa, ki je na Libanonu, celo do izopa, ki poganja iz zidu. Govoril je tudi o živini, o perjadi, o plazečih stvareh in o ribah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'In tja so prihajali iz vseh ljudstev, da poslušajo Salomonovo modrost, od vseh zemeljskih kraljev, ki so slišali o njegovi modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Tirski kralj Hirám je svoje služabnike poslal k Salomonu, kajti slišal je, da so ga mazilili [za] kralja namesto njegovega očeta, kajti Hirám je bil vedno Davidov oboževalec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomon je poslal k Hirámu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '»Ti veš, da moj oče David ni mogel zgraditi hiše imenu Gospoda, svojega Boga, zaradi vojn, ki so bile okoli njega na vsaki strani, dokler jih ni Gospod položil pod podplate njegovih stopal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Toda sedaj mi je Gospod, moj Bog, dal počitek na vsaki strani, tako da ni niti nasprotnika niti zlih dogodkov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Glej, namenil sem se zgraditi hišo imenu Gospoda, svojega Boga, kakor je Gospod spregovoril mojemu očetu Davidu, rekoč: ›Tvoj sin, ki ga bom namesto tebe postavil na tvoj prestol, on bo zgradil hišo mojemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Zdaj torej zapovej, da mi iz Libanona posekajo cedrova drevesa in moji služabniki bodo s tvojimi služabniki in dal ti bom plačilo za tvoje služabnike, glede na vse, kar mi boš določil; kajti veš, da med nami ni nobenega, ki tako vešče seka les kot Sidónci.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Ko je Hirám slišal Salomonove besede, se je pripetilo, da se je silno razveselil in rekel: »Blagoslovljen bodi ta dan Gospod, ki je Davidu dal modrega sina nad tem velikim ljudstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'In Hirám je poslal k Salomonu, rekoč: »Preudaril sem stvari, zaradi katerih pošiljaš k meni in izpolnil bom vso tvojo željo glede cedrovega lesa in glede cipresovega lesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Moji služabniki ga bodo spravljali dol iz Libanona do morja in po morju ga bom spravljal v splavih na mesto, ki mi ga boš določil in povzročim jim, da bodo tam razvezani in jih boš sprejel, ti pa boš izpolnil mojo željo, da mi daješ hrano za mojo družino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Tako je Hirám dajal Salomonu cedrov les in cipresov les glede na vse njegove želje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomon je dajal Hirámu dvajset tisoč mer pšenice za hrano njegovi družini in dvajset mer čistega olja. Tako je Salomon dajal Hirámu leto za letom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Gospod je dal Salomonu modrost, kakor mu je obljubil in bil je mir med Hirámom in Salomonom in onadva sta sklenila zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Kralj Salomon je zbral dajatev obveznega dela iz vsega Izraela, in dajatev obveznega dela je bila trideset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Pošiljal jih je k Libanonu, deset tisoč na mesec, v izmenah. En mesec so bili na Libanonu in dva meseca doma. Adonirám pa je bil nad dajatvijo obveznega dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Salomon jih je imel sedemdeset tisoč, ki so nosili bremena in osemdeset tisoč sekalcev v gorah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'poleg glavnih Salomonovih častnikov, ki so bili nad delom, tri tisoč tristo, ki so vladali nad ljudstvom, ki je opravljalo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Kralj je zapovedal in prinesli so velike kamne, drage kamne, klesane kamne, da hiši položijo temelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Salomonovi graditelji, Hirámovi graditelji in kamnoseki so jih klesali. Tako so pripravili les in kamne, da zgradijo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Pripetilo se je v štiristo osemdesetem letu, potem ko so Izraelovi otroci izšli iz egiptovske dežele, v četrtem letu Salomonovega kraljevanja nad Izraelom, v mesecu zivu, ki je drugi mesec, da je začel graditi Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Dolžina hiše, ki jo je kralj Salomon gradil za Gospoda, je bila šestdeset komolcev, njena širina dvajset komolcev in njena višina trideset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Dolžina preddverja pred hišnim templjem je bila dvajset komolcev, glede na širino hiše in deset komolcev je bila njegova širina pred hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, '§ Za hišo je naredil okna ozkih luči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Ob zidu hiše naokoli je zgradil sobe, ob zidovih hiše naokoli, tako od templja in od oraklja. Naredil je sobe naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Najnižja soba je bila pet komolcev široka, srednja je bila šest komolcev široka in tretja je bila sedem komolcev široka, kajti zunaj, v zidu hiše je naokoli naredil ozke opore, da bruna ne bi bila pritrjena v zidove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Hiša, ko je bila ta v gradnji, je bila grajena iz pripravljenega kamna, preden je bil ta pripeljan tja, tako da tam v hiši ni bilo slišati niti kladiva niti sekire niti nobenega orodja iz železa, ko je bila ta v gradnji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Vrata za srednjo sobo so bila na desni strani hiše. Gor so šli po zavitih stopnicah v srednjo sobo in iz srednje sobe v tretjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Tako je gradil hišo in jo dokončal in hišo pokril z bruni in cedrovimi deskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Potem je zgradil sobe ob vsej hiši, pet komolcev visoke in na hišo so bile pritrjene s cedrovim lesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Gospodova beseda je prišla Salomonu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '» Glede te hiše, ki jo gradiš, če se boš ravnal po mojih zakonih in izvajal moje sodbe in varoval vse moje zapovedi, da se ravnaš po njih, potem bom s teboj izvršil svojo besedo, ki sem jo govoril tvojemu očetu Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Prebival bom med Izraelovimi otroki in ne bom zapustil svojega ljudstva Izraela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Tako je Salomon zgradil hišo in jo dokončal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Zidove hiše znotraj je obložil s cedrovimi deskami, tako tla hiše kakor zidove stropa. In znotraj jih je pokril z lesom in tla hiše pokril s cipresovimi deskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Obložil je dvajset komolcev na straneh hiše, tako tla kakor stene s cedrovimi deskami. Zanjo jih je torej zgradil znotraj, torej za orakelj, torej za najsvetejši kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Hiša, to je tempelj pred njo, je bila dolga štirideset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Cedrovina hiše znotraj je bila izrezljana s popki in odprtimi cvetovi. Vse je bilo iz cedrovine; nobenega kamna ni bilo videti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Orakelj je pripravil znotraj v hiši, da tja postavi Gospodovo skrinjo zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Orakelj v sprednjem delu je bil dvajset komolcev po dolžini in dvajset komolcev po širini in dvajset komolcev po njegovi višini. Prevlekel ga je s čistim zlatom in tako je pokril oltar, ki je bil iz cedrovine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Tako je Salomon hišo prevlekel s čistim zlatom. Pred orakljem je naredil prehode z verižicami iz zlata in to prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Celotno hišo je prevlekel z zlatom, dokler ni dokončal vse hiše. Prav tako je celoten oltar, ki je bil poleg oraklja, prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Znotraj oraklja je naredil dva keruba iz oljkovega lesa, vsakega deset komolcev visokega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Pet komolcev je merila ena kerubova perut in pet komolcev je bila druga kerubova perut. Od zadnjega dela ene peruti do zadnjega dela druge je bilo deset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Drugi kerub je meril deset komolcev. Oba keruba sta bila ene mere in ene velikosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Višina enega keruba je bila deset komolcev in takšna je bila ta od drugega keruba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Keruba je postavil znotraj notranje hiše. Peruti kerubov so se razprostirala tako, da se je perut enega dotaknila ene stene in perut drugega keruba se je dotaknila druge stene in njuni peruti sta se dotikali druga druge v sredi hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Keruba je prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Vse hišne stene naokoli je izrezljal z izrezljanimi figurami kerubov, palmovih dreves in odprtih cvetov, znotraj in zunaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Tla hiše je prevlekel z zlatom, znotraj in zunaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Za vhod oraklja je naredil vrata iz oljkovega lesa. Vratna preklada in podboja sta bila petino zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Tudi dve vrati sta bili iz oljkovega lesa in nanju je izrezljal rezljanja kerubov, palmovih dreves in odprtih cvetov in jih prevlekel z zlatom in zlato razširil nad keruba in nad palmova drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Tako je tudi za tempeljska vrata naredil podboje iz oljkovega lesa, četrtino zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Dve vrati sta bili iz cipresovega lesa. Dve vratnici enih vrat sta bili pregibni in dve vratnici drugih vrat sta bili pregibni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Nanje je izrezljal kerube, palmova drevesa in odprte cvetove. Prevlekel jih z zlatom, ki se je prilegal izrezljanemu delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Notranji dvor je zgradil s tremi vrstami klesanega kamna in vrsto cedrovih brun.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'V četrtem letu, v mesecu zivu, je bil položen temelj Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'V enajstem letu, v mesecu bulu, ki je osmi mesec, je bila hiša dokončana v vseh njenih delih in glede na ves njen videz. Tako je bila v gradnji sedem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Toda Salomon je svojo lastno hišo gradil trinajst let in dokončal vso svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Zgradil je tudi hišo libanonskega gozda; njena dolžina je bila sto komolcev, njena širina petdeset komolcev in njena višina trideset komolcev, na štirih vrstah cedrovih stebrov, s cedrovimi bruni na stebrih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Ta je bila pokrita s cedrovino zgoraj na brunih, ki so ležala na petinštiridesetih stebrih, [po] petnajst v vrsti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Tam so bila okna v treh vrstah in svetloba je bila nasproti svetlobi v treh vrstah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Vsa vrata in podboji so bili štirioglati, z okni in svetloba je bila nasproti svetlobi v treh vrstah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Naredil je preddverje iz stebrov. Njegova dolžina je bila petdeset komolcev in njegova širina trideset komolcev. Preddverje je bilo pred njimi; in drugi stebri in debela bruna so bila pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Potem je naredil preddverje za prestol, kjer bi lahko sodil, celó preddverje sodbe. To je bilo prekrito s cedrovino od ene strani tal do druge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Hiša, v kateri je prebival, je imela drug dvor znotraj preddverja, ki je bilo iz podobnega dela. Salomon je naredil tudi hišo za faraonovo hčer, ki si jo je vzel za ženo, podobno temu preddverju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Vse te so bile iz dragih kamnov, glede na mere klesanih kamnov, žagane z žagami, zunaj in znotraj, celo od temelja do napušča in tako na zunanji strani proti velikemu dvoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Temelj je bil iz dragih kamnov, celo velikih kamnov, kamnov desetih komolcev in kamnov osmih komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Zgoraj so bili dragi kamni, po meri klesanih kamnov in cedrovina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Velik dvor naokoli je bil s tremi vrstami klesanih kamnov in vrsto cedrovih brun, tako za notranji dvor Gospodove hiše in za preddverje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Kralj Salomon je poslal in Hiráma pripeljal iz Tira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Bil je vdovin sin iz Neftálijevega rodu, njegov oče pa je bil mož iz Tira, delavec v bronu. Napolnjen je bil z modrostjo, razumevanjem in spretnostjo, da opravlja vsa dela z bronom. Prišel je h kralju Salomonu in opravil vse njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Kajti vlil je dva stebra iz brona, vsakega po osemnajst komolcev visokega in vrvica dvanajstih komolcev je naokoli obdajala vsakega izmed njiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Naredil je dva kapitela iz vlitega brona, da ju postavi na vrhova stebrov. Višina enega kapitela je bila pet komolcev in višina drugega kapitela je bila pet komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'In mreže iz narejenih zank in spleten verižni del za kapitele, ki so bili na vrhu stebrov; sedem za en kapitel in sedem za drug kapitel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Naredil je stebre in dve vrsti naokoli na eni mreži, da z granatnimi jabolki pokrije kapitele, ki so bili na vrhu. Tako je storil tudi za drugi kapitel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Kapitela, ki sta bila na vrhu stebrov v preddverju, sta bila iz lilijastega dela, štiri komolce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Kapitela na dveh stebrih sta imela granatna jabolka tudi zgoraj, nasproti vdolbini, ki je bila pri mreži. Granatnih jabolk je bilo dvesto v vrstah naokoli na drugem kapitelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Stebra je postavil v preddverju templja. Postavil je desni steber in ga imenoval Jahín, in postavil je levi steber ter njegovo ime imenoval Boaz');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Na vrhu stebrov je bilo lilijasto delo. Tako je bilo delo stebrov dokončano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Naredil je ulito morje, deset komolcev od enega robu, do drugega. To je bilo naokoli okroglo in njegova višina je bila pet komolcev. Vrvica tridesetih komolcev ga je obkrožila naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Pod njegovim robom naokoli so bili popki, ki so ga obdajali, deset na komolec, ki so naokoli obdajali morje. Popki so bili uliti v dveh vrstah, ko je bilo to ulito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'To je stalo na dvanajstih volih; trije so gledali proti severu, trije so gledali proti zahodu, trije so gledali proti jugu in trije so gledali proti vzhodu. Morje je bilo postavljeno zgoraj na njih in vsi njihovi zadnji deli so bili [obrnjeni] navznoter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'To je bilo za širino roke debelo in njegov rob je bil izdelan kakor rob čaše, s cvetovi lilij. Vseboval je dva tisoč čebrov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Naredil je deset podstavkov iz brona; štiri komolce je bila dolžina enega podstavka, štiri komolce je bila njegova širina in tri komolce njegova višina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Delo podstavkov je bilo na ta način: imeli so robove in robovi so bili med ploskvami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Na robovih, ki so bili med ploskvami, so bili levi, voli in kerubi. Na ploskvah je bil zgoraj podstavek in spodaj pod levi in voli so bili nekateri dodatki, narejeni iz tankega dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Vsak podstavek je imel štiri bronasta kolesa in bronaste osi. Njegovi štirje vogali so imeli opornike. Pod [okroglim] umivalnikom so bili oporniki uliti, pri strani vsakega dodatka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Odprtina le-tega znotraj kapitela in nad njim je bila komolec, toda odprtina le-tega je bila okrogla po delu podstavka, komolec in pol. Prav tako so bili na njegovi odprtini reliefi s svojimi robovi, štirioglati, neokrogli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Pod robovi so bila štiri kolesa in držaji koles so bili pritrjeni k podstavku. Višina kolesa je bila komolec in pol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Delo koles je bilo podobno delu kolesa bojnega voza. Njihovi držaji, njihova platišča, njihove napere in njihova pesta so bila vsa ulita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Bili so štirje oporniki k štirim vogalom enega podstavka in oporniki so bili del samega podstavka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Na vrhu podstavka je bil zaokrožen krog, pol komolca visok in na vrhu podstavka so bile njegove ploskve in njegovi robovi iz istega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Kajti na oseh ploskev in na njegovih robovih je izrezljal kerube, leve in palmova drevesa, glede na razmerja vsakega in dodatke naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Na ta način je naredil deset podstavkov. Vsi izmed njih so imeli en ulitek, eno mero in eno velikost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Potem je naredil deset [okroglih] bronastih umivalnikov. En [okrogel] umivalnik je vseboval štirideset čebrov. In vsak [okrogel] umivalnik je imel štiri komolce in na vsakem izmed desetih podstavkov en [okrogel] umivalnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Pet podstavkov je postavil na desno stran hiše in pet na levo stran hiše. Morje je postavil na desno stran hiše, proti vzhodu, nasproti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hirám je naredil [okrogle] umivalnike, lopate in umivalnike. Tako je Hirám naredil konec vseh del, ki jih je kralj Salomon storil za Gospodovo hišo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'dva stebra; dve skledi iz kapitelov, ki sta bili na vrhu dveh stebrov; dve mreži, da pokrijeta dve skledi kapitelov, ki sta bili na vrhu stebrov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'štiristo granatnih jabolk za dve mreži, celó dve vrsti granatnih jabolk za eno mrežo, da pokrijejo dve skledi kapitelov, ki sta bili na stebrih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'deset podstavkov; deset [okroglih] umivalnikov na podstavkih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'eno morje in dvanajst volov pod morjem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'lonce; lopate in umivalnike. Vse te posode, ki jih je Hirám naredil kralju Salomonu za Gospodovo hišo, so bile iz svetlega brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Na jordanski ravnini jih je kralj ulil, na ilovnati zemlji med Sukótom in Caretánom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Salomon je pustil vse posode nestehtane, ker jih je bilo silno mnogo. Niti niso ugotovili teže brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomon je naredil vse posode, ki so pripadale Gospodovi hiši: zlat oltar in zlato mizo, na kateri je bil hleb navzočnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'svečnike iz čistega zlata, pet na desni strani in pet na levi, pred orakljem, s cvetovi, svetilkami in utrinjači iz zlata;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'sklede; utrinjala; umivalnike; žlice; kadilnice iz čistega zlata in tečaje iz zlata, tako za vrata notranje hiše najsvetejšega kraja in za vrata hiše, namreč od templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tako je bilo dokončano vse delo, ki ga je kralj Salomon naredil za Gospodovo hišo. Salomon je prinesel noter stvari, ki jih je posvetil njegov oče David, torej srebro, zlato in posode je položil med zaklade Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Potem je Salomon zbral Izraelove starešine in vse poglavarje rodov, vodilne izmed očetov Izraelovih otrok, h kralju Salomonu v Jeruzalem, da bi lahko prinesli gor skrinjo Gospodove zaveze iz Davidovega mesta, ki je Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Vsi možje iz Izraela so se na praznik zbrali h kralju Salomonu, v mesecu etanímu, ki je sedmi mesec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Prišli so vsi Izraelovi starešine in duhovniki so dvignili skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Gor so prinesli Gospodovo skrinjo, šotorsko svetišče skupnosti shoda in vse svete posode, ki so bile v šotorskem svetišču, celo te so duhovniki in Lévijevci prinesli gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Kralj Salomon in vsa Izraelova skupnost, ki je bila zbrana k njemu, so bili z njim pred skrinjo. Žrtvovali so ovce in vole, ki se jih zaradi množice ni dalo ne povedati ne prešteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Duhovniki so skrinjo Gospodove zaveze prinesli na njeno mesto, v hišni orakelj, k najsvetejšemu kraju, celo pod peruti kerubov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Kajti keruba sta svoji dve peruti razprostirala nad prostorom skrinje in keruba sta od zgoraj pokrivala skrinjo in njena drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Drogova so izvlekli, da sta se konca drogov videla iz svetega kraja pred orakljem, odzunaj pa nista bila vidna in tam sta do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'V skrinji ni bilo ničesar razen dveh kamnitih plošč, ki ju je Mojzes položil tja pri Horebu, ko je Gospod sklenil zavezo z Izraelovi otroci, ko so prišli iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Pripetilo se je, ko so duhovniki prišli ven iz svetega kraja, da je oblak napolnil Gospodovo hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'tako da duhovniki zaradi oblaka niso mogli stati, da bi služili, kajti Gospodova slava je napolnila Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Potem je spregovoril Salomon: » Gospod je rekel, da bo prebival v gosti temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Zagotovo sem ti zgradil hišo, da prebivaš v njej, ustaljen kraj zate, da v njem prebivaš na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Kralj je obrnil svoj obraz naokrog in blagoslovil vso Izraelovo skupnost (in vsa Izraelova skupnost je stala)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'in rekel je: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je s svojimi usti spregovoril mojemu očetu Davidu in je to izpolnil s svojo roko, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '›Od dneva, ko sem svoje ljudstvo Izraela privedel ven iz Egipta, nisem izbral nobenega mesta izmed vseh Izraelovih rodov, da bi zgradil hišo, da bi bilo v njej lahko moje ime, temveč sem izbral Davida, da bo nad mojim ljudstvom Izraelom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'To je bilo na srcu mojega očeta Davida, da zgradi hišo za ime Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Gospod je rekel mojemu očetu Davidu: ›Medtem ko je bilo to v tvojem srcu, da zgradiš hišo mojemu imenu, si storil dobro, da je bilo to v tvojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Vendar pa hiše ne boš gradil ti, temveč tvoj sin, ki bo izšel iz tvojih ledij, on bo zgradil hišo mojemu imenu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Gospod je izpolnil svojo besedo, ki jo je govoril in dvignjen sem bil na položaj svojega očeta Davida in sedim na Izraelovem prestolu, kakor je obljubil Gospod in zgradil sem hišo za ime Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Tam sem pripravil prostor za skrinjo, v kateri je Gospodova zaveza, ki jo je on sklenil z našimi očeti, ko jih je privedel ven iz egiptovske dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Salomon je stal pred Gospodovim oltarjem v prisotnosti vse Izraelove skupnosti in svoji roki razširil proti nebu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'in rekel: » Gospod, Izraelov Bog, ni Boga, podobnega tebi, na nebu zgoraj ali na zemlji spodaj, ki ohranjaš zavezo in usmiljenje s svojimi služabniki, ki z vsem svojim srcem hodijo pred teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'ki si svojemu služabniku Davidu, mojemu očetu, ohranil to, kar si mu obljubil. Govoril si s svojimi usti in si to tudi izpolnil s svojo roko, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Zato zdaj Gospod, Izraelov Bog, ohrani s svojim služabnikom Davidom, mojim očetom, to, kar si mu obljubil, rekoč: ›Ne bo ti zmanjkalo moža v mojem pogledu, da bi sedel na Izraelovem prestolu; samo da tvoji otroci pazijo na svojo pot, da hodijo pred menoj, kakor si ti hodil pred menoj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Sedaj, oh Izraelov Bog, naj bo tvoja beseda, prosim te, resnična, ki si jo govoril svojemu služabniku, mojemu očetu Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Toda ali bo Bog zares prebival na zemlji? Glej, nebo in nebesa nebes te ne morejo obseči, kako veliko manj ta hiša, ki sem jo zgradil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Vendar se ozri na molitev svojega služabnika in k njegovi ponižni prošnji, oh Gospod, moj Bog, da prisluhneš klicu in molitvi, ki jo ta dan tvoj služabnik moli pred teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'da bodo tvoje oči lahko ponoči in podnevi odprte proti tej hiši, torej proti kraju, o katerem si rekel: ›Moje ime bo tam,‹ da boš lahko prisluhnil molitvi, ki jo bo tvoj služabnik naredil k temu kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Prisluhni ponižni prošnji svojega služabnika in svojega ljudstva Izraela, ko bodo molili k temu kraju. Pozorno poslušaj v nebesih, svojem prebivališču. In ko si pozorno slišal, odpusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Če se katerikoli človek prekrši zoper svojega bližnjega in je nanj položena prisega, da mu povzroči, da priseže in prisega pride pred tvoj oltar v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'potem pozorno poslušaj v nebesih, ukrepaj in sodi svoja služabnika, obsodi zlobnega, da privedeš njegovo pot na njegovo glavo in opraviči pravičnega, da mu daš glede na njegovo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Ko bo tvoje ljudstvo Izrael udarjeno pred sovražnikom, ker so grešili zoper tebe in se bo ponovno obrnilo k tebi, priznalo tvoje ime, molilo in naredilo ponižno prošnjo k tebi v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'potem pozorno poslušaj v nebesih in odpusti greh svojega ljudstva Izraela in jih ponovno privedi v deželo, ki jo daješ njihovim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Ko je nebo zaprto in ni dežja, ker so grešili zoper tebe; če molijo k temu kraju in priznajo tvoje ime in se obrnejo od svojega greha, ko si jih ti prizadel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'potem pozorno poslušaj v nebesih in odpusti greh svojih služabnikov in svojega ljudstva Izraela, da jih naučiš dobro pot, po kateri naj bi hodili in jim daš dež na svojo deželo, ki si jo dal svojemu ljudstvu v dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Če bo v deželi lakota, če bo kužna bolezen, kvarjenje, plesen, leteča kobilica ali če bo tam gosenica; če jih njihov sovražnik oblega v deželi njihovih mest, kakršnakoli nadloga, kakršnakoli bolezen bo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'kakršnokoli molitev in ponižno prošnjo bo naredil katerikoli človek ali vse tvoje ljudstvo Izrael, ki bo spoznal, vsak mož nadlogo svojega lastnega srca in bo svoje roke razširil proti tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'potem pozorno poslušaj v nebesih, svojem prebivališču, odpusti, ukrepaj in daj vsakemu možu glede na njegove poti, čigar srce poznaš (kajti ti, celó le ti, poznaš srca vseh človeških otrok),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'da se te bodo lahko bali vse dni, ki jih živijo v deželi, ki si jo dal našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Poleg tega glede tujca, ki ni iz tvojega ljudstva Izraela, temveč zaradi tvojega imena prihaja iz daljne dežele');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(kajti slišali bodo o tvojem velikem imenu, o tvoji močni roki in o tvojem iztegnjenem laktu), ko bo prišel in molil k tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'pozorno poslušaj v nebesih, svojem bivališču in ukrepaj glede na vse, za kar bo tujec klical k tebi, da bo vse ljudstvo zemlje lahko spoznalo tvoje ime, da se te boji, kakor to dela tvoje ljudstvo Izrael in da bodo lahko vedeli, da je ta hiša, ki sem jo zgradil, imenovana po tvojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Če gre tvoje ljudstvo ven na bitko zoper svojega sovražnika, kamorkoli jih boš poslal in bodo molili h Gospodu, k mestu, ki si ga ti izbral in k hiši, ki sem jo zgradil za tvoje ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'potem pozorno poslušaj v nebesih njihovo molitev, njihovo ponižno prošnjo in obravnavaj njihov primer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Če grešijo zoper tebe (kajti tam ni človeka, ki ne greši) in si jezen nanje in jih izročiš sovražniku, tako da jih odvedejo ujetnike v deželo sovražnika, daleč ali blizu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'vendar če si bodo premislili v deželi, kamor so bili odvedeni ujeti in se pokesajo in naredijo ponižno prošnjo k tebi, v deželi tistih, ki so jih odvedli ujete, rekoč: ›Grešili smo in storili pokvarjeno, zagrešili smo zlobnost‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'in se tako vrnejo k tebi z vsem svojim srcem in z vso svojo dušo v deželi svojih sovražnikov, ki so jih odvedli ujete in molijo k tebi, k svoji deželi, ki si jo dal njihovim očetom, mestu, ki si ga ti izbral in hiši, ki sem jo zgradil za tvoje ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'potem pozorno poslušaj njihovo molitev in njihovo ponižno prošnjo v nebesih, svojem prebivališču in obravnavaj njihov primer');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'in odpusti svojemu ljudstvu, ker so grešili zoper tebe in vse njihove prestopke, s katerimi so se prekršili zoper tebe in jim daj sočutje pred tistimi, ki so jih odvedli ujete, da bodo lahko imeli sočutje do njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'kajti oni so tvoje ljudstvo in tvoja dediščina, ki si jo privedel iz Egipta, iz srede železne talilne peči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'da bodo tvoje oči lahko odprte k ponižni prošnji tvojega služabnika in k ponižni prošnji tvojega ljudstva Izraela, da jim prisluhneš v vsem, v čemer kličejo k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Kajti oddvojil si jih izmed vsega zemeljskega ljudstva, da bi bili tvoja dediščina, kakor si govoril po roki svojega služabnika Mojzesa, ko si naše očete privedel iz Egipta, oh Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Bilo je tako, ko je Salomon nehal moliti vso to molitev in ponižno prošnjo h Gospodu, da je vstal izpred Gospodovega oltarja od klečanja na svojih kolenih, s svojima rokama, razširjenima k nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Vstal je in z močnim glasom blagoslovil vso Izraelovo skupnost, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '»Blagoslovljen bodi Gospod, ki je svojemu ljudstvu Izraelu dal počitek, glede na vse, kar je obljubil. Niti ena beseda ni manjkala od vse njegove dobre obljube, ki jo je obljubil po roki svojega služabnika Mojzesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Gospod, naš Bog, naj bo z nami, kakor je bil z našimi očeti. Naj nas ne pusti niti naj nas ne zapusti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'da bo lahko naša srca nagnil k sebi, da hodimo po vseh njegovih poteh in da ohranjamo vse njegove zapovedi, njegove zakone in njegove sodbe, ki jih je zapovedal našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Naj bodo te moje besede, s katerimi sem naredil ponižno prošnjo pred Gospodom, blizu Gospodu, našemu Bogu, podnevi in ponoči, da ohrani zadevo svojega služabnika in zadevo svojega ljudstva Izraela ob vseh časih, kakor bo stvar zahtevala,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'da bo vse ljudstvo zemlje lahko vedelo, da Gospod je Bog in da tam ni nobenega drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Naj bo vaše srce torej popolno z Gospodom, našim Bogom, da se ravna po njegovih zakonih in da ohranja njegove zapovedi, kakor je ta dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Kralj in ves Izrael z njim je daroval klavno daritev pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Salomon je daroval žrtvovanje mirovnih daritev, ki jih je daroval Gospodu, dvaindvajset tisoč volov in sto dvajset tisoč ovc. Tako so kralj in vsi Izraelovi otroci posvetili Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Istega dne je kralj posvetil sredino dvora, ki je bila pred Gospodovo hišo, kajti tam je daroval žgalne daritve, jedilne daritve in tolščo mirovnih daritev, ker je bil bronast oltar, ki je bil pred Gospodom, premajhen, da sprejme žgalne daritve, jedilne daritve in tolščo mirovnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Ob tistem času je Salomon priredil praznovanje in ves Izrael z njim, velika skupnost, od vhoda v Hamát do egiptovske reke, pred Gospodom, svojim Bogom, sedem dni in sedem dni, torej štirinajst dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Na osmi dan je ljudstvo odposlal proč in blagoslovili so kralja in radostni in veselega srca zaradi vse dobrote, ki jo je Gospod storil za svojega služabnika Davida in za svoje ljudstvo Izrael, odšli k svojim šotorom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Pripetilo se je, ko je Salomon dokončal gradnjo Gospodove hiše, kraljeve hiše in vsega, kar je Salomon želel, kar mu je ugajalo storiti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'da se je Gospod drugič prikazal Salomonu, kakor se mu je prikazal pri Gibeónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Gospod mu je rekel: »Slišal sem tvojo molitev in tvojo ponižno prošnjo, ki si jo storil pred menoj. Jaz sem posvetil to hišo, ki si jo zgradil, da tja na veke postavim svoje ime in moje oči in moje srce bodo neprestano tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Če boš hodil pred menoj, kakor je hodil tvoj oče David, v neokrnjenosti srca in v poštenosti, da storiš glede na vse, kar sem ti zapovedal in da boš ohranjal moje zakone in moje sodbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'potem bom na veke utrdil prestol tvojega kraljestva nad Izraelom, kakor sem obljubil tvojemu očetu Davidu, rekoč: ›Ne bo ti manjkal mož na Izraelovem prestolu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Toda če se boste obrnili od sledenja meni, vi ali vaši otroci in ne boste ohranjali mojih zapovedi in mojih zakonov, ki sem jih postavil pred vas, temveč boste šli in služili drugim bogovom in jih oboževali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'potem bom Izraela odsekal iz dežele, ki sem jim jo dal in to hišo, ki sem jo posvetil za svoje ime, bom vrgel iz svojega pogleda in Izrael bo med vsemi ljudstvi pregovor in tarča posmeha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'In ob tej hiši, ki je visoka, bo vsak, kdor gre mimo nje, osupel in bo sikal. Rekli bodo: ›Zakaj je Gospod tako storil tej deželi in tej hiši?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Odgovorili bodo: ›Ker so zapustili Gospoda, svojega Boga, ki je njihove očete privedel ven iz egiptovske dežele in so se oprijeli drugih bogov, jih oboževali in jim služili, zato je Gospod nadnje privedel vse to zlo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Pripetilo se je ob koncu dvajsetih let, ko je Salomon zgradil dve hiši, Gospodovo hišo in kraljevo hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(torej tirski kralj Hirám je Salomona opremil s cedrovim lesom, cipresovim lesom in z zlatom, glede na vso njegovo željo) da je nató kralj Salomon Hirámu dal dvajset mest v galilejski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Hirám je prišel iz Tira, da bi videl mesta, ki mu jih je Salomon dal. Le-ta pa mu niso ugajala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Rekel je: »Kakšna so ta mesta, ki si mi jih dal, moj brat?« Imenoval jih je dežela Kabúl do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hirám je poslal h kralju sto dvajset talentov zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'In to je razlog dajatve obveznega dela, ki ga je dvignil kralj Salomon, da zgradi Gospodovo hišo, svojo lastno hišo, Miló, jeruzalemsko obzidje, Hacór, Megído in Gezer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Kajti faraon, egiptovski kralj, je odšel gor, zavzel Gezer, ga požgal z ognjem in umoril Kánaance, ki so prebivali v mestu in ga dal za darilo svoji hčeri, Salomonovi ženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomon je zgradil Gezer, spodnji Bet Horón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalát, Tadmór v divjini, v deželi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'in vsa skladiščna mesta, ki jih je imel Salomon in mesta za njegove bojne vozove in mesta za njegove konjenike in to, kar je Salomon želel, da zgradi v Jeruzalemu, na Libanonu in po vsej deželi svojega gospostva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Na vse ljudstvo, ki je preostalo od Amoréjcev, Hetejcev, Perizéjcev, Hivéjcev in Jebusejcev, ki niso bili od Izraelovih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'na njihove otroke, ki so za njimi preostali v deželi, ki jih Izraelovi otroci niso mogli popolnoma uničiti, je Salomon naložil dajatev davka prisilnega dela do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Toda izmed Izraelovih otrok Salomon ni naredil nobenega sužnja, temveč so bili bojevniki, njegovi služabniki, njegovi princi, njegovi poveljniki, vodje njegovih bojnih voz in njegovi konjeniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Ti so bili glavni častniki, ki so bili nad Salomonovim delom, petsto petdeset, ki so nadzorovali ljudstvo, ki je opravljalo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Toda faraonova hči je prišla gor iz Davidovega mesta k svoji hiši, ki jo je Salomon zgradil zanjo. Potem je zgradil Miló.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Trikrat na leto je Salomon daroval žgalne daritve in mirovne daritve na oltarju, ki ga je zgradil Gospodu in zažgal je kadilo na oltarju, ki je bil pred Gospodom. Tako je dokončal hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, '§ Kralj Salomon je naredil floto ladij v Ecjón Geberju, ki je poleg Elota, na obali Rdečega morja, v edómski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Hirám je s Salomonovimi služabniki poslal v floto svoje služabnike, pomorščake, ki so imeli znanje o morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Prišli so do Ofírja in od tam vzeli zlato, štiristo dvajset talentov in to prinesli h kralju Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Ko je kraljica iz Sabe slišala o Salomonovem slovesu glede Gospodovega imena, je prišla, da ga preizkusi s težkimi vprašanji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Prišla je v Jeruzalem z zelo velikim spremstvom, s kamelami, ki so nosile dišave, zelo veliko zlata in [z] dragocenimi kamni. Ko je prišla k Salomonu, se je z njim posvetovala o vsem, kar je bilo na njenem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomon ji je povedal [odgovore na] vsa njena vprašanja. Ničesar ni bilo skritega pred kraljem, kar ji ne bi povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Ko je kraljica iz Sabe videla vso Salomonovo modrost in hišo, ki jo je zgradil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'hrano njegove mize, sedenje njegovih služabnikov in položaj njegovih strežnikov, njihovo obleko, njegove dvorne točaje in njegovo vzpenjanje, s katerim je odšel gor h Gospodovi hiši, v njej ni bilo več duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Rekla je kralju: »Poročilo, ki sem ga slišala v svoji lastni deželi, o tvojih dejanjih in o tvoji modrosti, je bilo resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Vendar nisem verjela besedam, dokler nisem prišla in so moje oči to videle. Glej, niti polovice mi niso povedali. Tvoja modrost in uspevanje presega sloves, ki sem ga slišala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Srečni so tvoji možje, srečni so ti tvoji služabniki, ki nenehno stojijo pred teboj in ki slišijo tvojo modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Blagoslovljen bodi Gospod, tvoj Bog, ki se je razveseljeval v tebi, da te je posadil na Izraelov prestol. Ker je Gospod na veke ljubil Izraela, zato te je postavil za kralja, da izvajaš sodbo in pravico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Kralju je izročila sto dvajset talentov zlata in od dišav zelo veliko zalogo in dragocene kamne. Tja ni prišlo več takšno obilje dišav kakor te, ki jih je kraljica iz Sabe dala kralju Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Prav tako je Hirámova mornarica, ki je iz Ofírja pripeljala zlato, iz Ofírja pripeljala veliko obilje sandalovine in dragocenih kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Kralj je iz sandalovine naredil stebre za Gospodovo hišo in za kraljevo hišo, tudi harfe in plunke za pevce. Do tega dne tja ni prišlo nobene takšne sandalovine niti jih niso videli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Kralj Salomon je kraljici iz Sabe izročil vse njene želje, karkoli je prosila, poleg tega, kar ji je Salomon dal od svoje kraljeve radodarnosti. Tako se je obrnila in odšla v svojo lastno deželo, ona in njeni služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Torej teža zlata, ki je v enem letu prišla k Salomonu, je bila šeststo šestinšestdeset talentov zlata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'poleg tega kar je imel od trgovcev, od preprodaje trgovcev z dišavami, od vseh kraljev iz Arabije in od voditeljev dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Kralj Salomon je naredil dvesto okroglih ščitov iz kovanega zlata. Šeststo šeklov zlata je šlo k enemu okroglemu ščitu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Naredil je tristo ščitov iz kovanega zlata. Tri funte zlata je šlo za en ščit. Kralj jih je postavil v hiši libanonskega gozda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Poleg tega je kralj naredil velik prestol iz slonovine in ga prevlekel z najboljšim zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Prestol je imel šest stopnic in vrh prestola je bil zadaj okrogel. Na vsaki strani prestola sta bili naslonjali za roke in dva leva sta stala poleg naslonjal za roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Dvanajst levov je stalo na eni strani in na drugi, na šestih stopnicah. Kaj podobnega ni bilo narejenega v nobenem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Vse Salomonove posode za pitje so bile iz zlata in vse posode hiše libanonskega gozda so bile iz čistega zlata, nobena ni bila iz srebra. V Salomonovih dneh le-to ni veljalo za nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Kajti kralj je imel na morju taršíško mornarico s Hirámovo mornarico. Enkrat na tri leta je prišla mornarica iz Taršíša noseč zlato, srebro, slonovino, opice in pave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tako je kralj Salomon zaradi bogastva in zaradi modrosti prekosil vse zemeljske kralje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Vsa zemlja je iskala Salomona, da sliši njegovo modrost, ki jo je Bog položil v njegovo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Vsak mož je prinesel svoje darilo, posode iz srebra, posode iz zlata, obleke, bojno opremo, dišave, konje, mule in to leto za letom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomon je zbral skupaj bojne vozove in konjenike. Imel je tisoč štiristo bojnih voz in dvanajst tisoč konjenikov, ki jih je usmeril v mesta za bojne vozove in s kraljem v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Kralj je storil, da je bilo v Jeruzalemu zaradi obilja srebra kakor kamnov in storil, da je bilo ceder kakor egiptovskih smokev, ki so v dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, '§ Salomon je imel konje, privedene iz Egipta in laneno prejo. Kraljevi trgovci so laneno prejo prejeli za ceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Bojni voz je prišel gor in se iz Egipta pripeljal za šeststo šeklov srebra, konj pa [za] sto petdeset. Tako so jih za vse hetejske kralje in za sirske kralje privedli ven z njihovimi sredstvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Toda kralj Salomon je ljubil mnoge tuje žene, skupaj s faraonovo hčerjo, ženske iz Moába, Amónke, Edómke, Sidónke in Hetejke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'od narodov glede katerih je Gospod Izraelovim otrokom rekel: »Ne boste vstopili k njim niti oni ne smejo vstopiti k vam, kajti zagotovo bodo vaše srce odvrnili za svojimi bogovi.« Salomon se je v ljubezni trdno pridružil k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Imel je sedemsto žená, princese in tristo priležnic in njegove žene so odvrnile njegovo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Kajti zgodilo se je, ko je bil Salomon star, da so njegove žene njegovo srce odvrnile za drugimi bogovi in njegovo srce ni bilo popolno z Gospodom, njegovim Bogom, kot je bilo srce njegovega očeta Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Kajti Salomon je šel za Astarto, boginjo Sidóncev in za Milkómom, gnusobo Amóncev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Salomon je počel zlo v Gospodovih očeh in ni popolnoma šel za Gospodom, kakor je delal njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Potem je Salomon zgradil visok kraj za Kemoša, gnusobo Moábcev, na hribu, ki je pred Jeruzalemom in za Moloha, ogabnost Amónovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Podobno je storil za vse svoje tuje žene, ki so zažigale kadilo in žrtvovale svojim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Gospod pa je bil jezen nad Salomonom, ker je bilo njegovo srce odvrnjeno od Gospoda, Izraelovega Boga, ki se mu je dvakrat prikazal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'in mu je glede te stvari zapovedal, da naj ne gre za drugimi bogovi. Toda tega, kar mu je Gospod zapovedal, ni ohranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Zato je Gospod Salomonu rekel: »Ker si to storil in nisi obvaroval moje zaveze in mojih zakonov, ki sem ti jih zapovedal, ti bom zagotovo iztrgal kraljestvo in ga dal tvojemu služabniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Vendar zaradi tvojega očeta Davida tega ne bom storil v tvojih dneh, temveč ga bom iztrgal iz roke tvojega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Toda ne bom odtrgal vsega kraljestva, temveč bom en rod dal tvojemu sinu zaradi Davida, svojega služabnika in zaradi Jeruzalema, ki sem ga izbral.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Gospod je Salomonu razvnel nasprotnika, Edómca Hadáda. Ta je bil iz kraljevega semena v Edómu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Kajti pripetilo se je, ko je bil David v Edómu in je Joáb, poveljnik vojske, odšel gor, da pokoplje umorjene, potem ko je udaril vsakega moškega v Edómu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(kajti šest mesecev je Joáb ostal tam z vsem Izraelom, dokler ni iztrebil vsakega moškega v Edómu),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'da je Hadád pobegnil, on in z njim nekateri Edómci, služabniki njegovega očeta, da gredo v Egipt; Hadád je bil še majhen otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Vstali so iz Midjána in prišli v Parán in s seboj so vzeli može iz Parána ter prišli v Egipt, k faraonu, egiptovskemu kralju, ki mu je dal hišo, mu določil živež in mu dal deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadád je našel veliko naklonjenost v faraonovih očeh, tako da mu je dal za ženo sestro svoje lastne žene, sestro kraljice Tahpenése.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Tahpenésina sestra mu je rodila Genubáta, njegovega sina, ki ga je Tahpenésa vzgajala v faraonovi hiši in Genubát je bil v faraonovi hiši med faraonovimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Ko je Hadád v Egiptu slišal, da je David zaspal s svojimi očeti in da je bil Joáb, poveljnik vojske, mrtev, je Hadád rekel faraonu: »Pusti me oditi, da lahko grem k svoji lastni deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Potem mu je faraon rekel: »Toda kaj ti je manjkalo z menoj, glej, da si prizadevaš, da greš v svojo lastno deželo?« Odgovoril je: »Nič, vendar me vseeno pusti oditi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Bog pa mu je razvnel drugega nasprotnika, Eljadájevega sina Rezóna, ki je pobegnil pred svojim gospodom Hadadézerjem, kraljem iz Cobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'K sebi je zbral može in postal poveljnik nad četo, ko je David usmrtil tiste iz Cobe in odšli so v Damask, tam prebivali in kraljevali v Damasku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Vse Salomonove dni je bil nasprotnik Izraelu, poleg vragolije, ki jo je storil Hadád. Preziral je Izrael in kraljeval nad Sirijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jerobeám, Nebátov sin, Efratejec iz Ceréde, Salomonov služabnik (katerega materino ime je bilo Cerúja, vdova), celo on je dvignil svojo roko zoper kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'To je bil razlog, da je svojo roko dvignil zoper kralja. Salomon je zgradil Miló in popravil vrzeli mesta svojega očeta Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Mož Jerobeám je bil mogočen, hraber človek in Salomon, ko je videl, da je bil mladenič podjeten, ga je postavil za vladarja nad vso zadolžitvijo Jožefove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Pripetilo se je ob tistem času, ko je Jerobeám odšel iz Jeruzalema, da ga je na poti našel prerok Šilčan Ahíja, in ta se je odel z novo obleko in onadva sta bila sama na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Ahíja je zgrabil novo obleko, ki je bila na njem in jo raztrgal na dvanajst kosov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'in rekel Jerobeámu: »Vzemi si deset kosov, kajti tako govori Gospod, Izraelov Bog: ›Glej, iztrgal bom kraljestvo iz Salomonove roke in tebi bom dal deset rodov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(toda on bo imel en rod zaradi mojega služabnika Davida in zaradi Jeruzalema, mesta, ki sem ga izbral izmed vseh Izraelovih rodov),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'zato ker so me zapustili in oboževali Astarto, boginjo Sidóncev, Kemoša, boga Moábcev in Milkóma, boga Amónovih otrok in niso hodili po mojih poteh, da delajo to, kar je pravilno v mojih očeh in da ohranjajo moje zakone in moje sodbe, kakor je počel njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Vendar iz njegove roke ne bom vzel celotnega kraljestva, temveč ga bom zaradi Davida, svojega služabnika, ki sem ga izbral, naredil za princa vse dni njegovega življenja, ker je ohranjal moje zapovedi in moje zakone,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'toda kraljestvo bom vzel iz roke njegovega sina in ga dal tebi, celó deset rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Njegovemu sinu pa bom dal en rod, da bo David, moj služabnik, lahko vedno imel luč pred menoj v Jeruzalemu, mestu, ki sem ga izbral, da tam postavim svoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Vzel te bom in kraljeval boš glede na vse, kar želi tvoja duša in boš kralj nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Zgodilo se bo, če boš prisluhnil vsemu, kar ti zapovem in boš hodil po mojih poteh in delal to, kar je pravilno v mojih očeh, da se držiš mojih zakonov in mojih zapovedi, kakor se je moj služabnik David, da bom jaz s teboj in ti bom zgradil zanesljivo hišo, kakor sem jo zgradil za Davida, Izraela pa bom izročil tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Zaradi tega bom prizadel Davidovo seme, toda ne na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomon je torej iskal, da ubije Jerobeáma. Jerobeám pa je vstal in pobegnil v Egipt, k egiptovskemu kralju Šišáku in v Egiptu je bil do Salomonove smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Ostala Salomonova dela in vse, kar je storil in njegova modrost, mar niso zapisana v knjigi Salomonovih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Časa, ko je Salomon v Jeruzalemu kraljeval nad vsem Izraelom, je bilo štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Salomon je zaspal s svojimi očeti in bil pokopan v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Rehabám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rehabám je odšel v Sihem, kajti ves Izrael je prišel v Sihem, da ga postavijo za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Pripetilo se je, ko je Nebátov sin Jerobeám, ki je bil še v Egiptu, slišal o tem (kajti pobegnil je izpred prisotnosti kralja Salomona in je Jerobeám prebival v Egiptu),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'da so poslali in ga poklicali. Jerobeám in vsa Izraelova skupnost pa je prišla in spregovorila Rehabámu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '»Tvoj oče je naš jarem naredil boleč. Sedaj torej olajšaj bolečo službo svojega očeta in njegov težek jarem, ki ga je položil na nas in mi ti bomo služili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Rekel jim je: »Odidite še za tri dni, potem ponovno pridite k meni.« In ljudstvo je odšlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Kralj Rehabám se je posvetoval s starci, ki so stali pred njegovim očetom Salomonom, medtem ko je še živel in rekel: »Kako svetujete, da lahko odgovorim temu ljudstvu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Odgovorili so mu, rekoč: »Če hočeš biti ta dan služabnik temu ljudstvu in jim hočeš služiti in jim odgovoriti in jim govoriti dobre besede, potem bodo tvoji služabniki na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Toda zapustil je nasvet starcev, ki so mu ga dali in se posvetoval z mladeniči, ki so odrasli z njim in ki so stali pred njim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'in jim rekel: »Kakšen nasvet dajete vi, da lahko odgovorimo temu ljudstvu, ki mi je govorilo, rekoč: ›Naredi jarem, ki ga je tvoj oče položil nad nas, lažji?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Mladeniči, ki so zrasli z njim, so mu govorili, rekoč: »Tako boš govoril temu ljudstvu, ki ti je govorilo, rekoč: ›Tvoj oče je naš jarem naredil težek, toda ti nam ga olajšaj;‹ tako jim boš rekel: ›Moj mali prst bo debelejši kakor očetova ledja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Kakor vam je moj oče naložil težek jarem, bom sedaj dodal vašemu jarmu. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Tako je Jerobeám in vse ljudstvo tretji dan prišlo k Rehabámu, kakor je kralj določil, rekoč: »Ponovno pridite k meni tretji dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Kralj je ljudstvu surovo odgovoril in zapustil nasvet starcev, ki so mu ga dali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Spregovoril jim je glede na nasvet mladeničev, rekoč: »Moj oče je vaš jarem naredil težek, jaz pa bom vašemu jarmu dodal. Moj oče vas je kaznoval tudi z biči, toda jaz vas bom kaznoval s škorpijoni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Zatorej kralj ni prisluhnil ljudstvu, kajti stvar je bila od Gospoda, da je lahko izpolnil svojo besedo, ki jo je Gospod po Šilčanu Ahíju govoril Nebátovemu sinu Jerobeámu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Torej ko je ves Izrael videl, da jim kralj ni prisluhnil, je ljudstvo odgovorilo kralju, rekoč: »Kakšen delež imamo v Davidu? Niti nimamo dediščine v Jesejevem sinu. K svojim šotorom, oh Izrael. Sedaj poglej k svoji lastni hiši, David.« Tako je Izrael odšel v svoje šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Toda kar se tiče Izraelovih otrok, ki so prebivali v Judovih mestih, je nad njimi kraljeval Rehabám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Potem je kralj Rehabám poslal Adoráma, ki je bil nad davkom in ves Izrael ga je kamnal s kamni, da je umrl. Zato je kralj Rehabám pohitel, da se spravi k svojemu bojnemu vozu, da pobegne v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tako se je Izrael uprl zoper Davidovo hišo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Pripetilo se je, ko je ves Izrael slišal, da je Jerobeám ponovno prišel, da so poslali in ga poklicali k skupnosti in ga postavili za kralja nad vsem Izraelom. Tam ni bilo nikogar, ki je sledil Davidovi hiši, razen samo Judovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Ko je Rehabám prišel v Jeruzalem, je zbral vso Judovo hišo, z Benjaminovim rodom, sto osemdeset tisoč izbranih mož, ki so bili bojevniki, da se bojujejo zoper Izraelovo hišo, da kraljestvo ponovno privedejo k Salomonovemu sinu Rehabámu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Toda beseda od Boga je prišla k Šemajáju, Božjemu možu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '»Govori Salomonovemu sinu Rehabámu, Judovemu kralju in vsej Judovi in Benjaminovi hiši in preostanku ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '›Tako govori Gospod: ›Ne boste šli gor niti se ne boste borili zoper vaše brate, Izraelove otroke. Vsak mož naj se vrne k svoji hiši, kajti ta stvar je od mene.‹« Prisluhnili so torej Gospodovi besedi in se vrnili, da odidejo, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Potem je Jerobeám na gori Efrájim zgradil Sihem in tam prebival in odšel od tam ter zgradil Penuél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jerobeám je v svojem srcu rekel: »Sedaj se bo kraljestvo vrnilo k Davidovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Če gre to ljudstvo gor, da opravi klavno daritev v Gospodovi hiši, v Jeruzalemu, potem se bo srce tega ljudstva ponovno obrnilo k njihovemu gospodu, k Judovemu kralju Rehabámu, mene pa bodo ubili in ponovno odšli k Judovemu kralju Rehabámu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Nakar se je kralj posvetoval in naredil dve teleti iz zlata ter jim rekel: »To je za vas preveč, da greste gor v Jeruzalem. Poglejte svoje bogove, oh Izrael, ki so te privedli gor iz egiptovske dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Eno je postavil v Betelu, drugo pa v Danu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Ta stvar je postala greh, kajti ljudstvo je odšlo, da bi oboževalo pred enim, celó k Danu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Naredil je hišo visokih krajev in iz najnižjih izmed ljudstva naredil duhovnike, ki niso bili izmed Lévijevih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jerobeám je odredil praznovanje v osmem mesecu, na petnajsti dan meseca, podobno prazniku, ki je v Judu in daroval na oltarju. Tako je storil v Betelu, žrtvoval je teletoma, ki ju je naredil in v Betelu je postavil duhovnike visokih krajev, ki jih je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Tako je daroval na oltarju, ki ga je naredil v Betelu, na petnajsti dan osmega meseca, celó v mesecu, ki ga je zasnoval iz svojega lastnega srca in odredil praznovanje Izraelovim otrokom in daroval na oltarju in zažgal kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Glej, iz Juda je prišel Božji mož po Gospodovi besedi do Betela in Jerobeám je stal pri oltarju, da zažge kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Zaklical je zoper oltar v Gospodovi besedi in rekel: »Oh oltar, oltar, tako govori Gospod: ›Glej, otrok bo rojen Davidovi hiši, po imenu Jošíja in na tebi bo daroval duhovnike visokih krajev, ki zažigajo kadilo na tebi in človeške kosti bodo žgane na tebi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'In isti dan je dal znamenje, rekoč: »To je znamenje, ki ga je Gospod govoril: ›Glej, oltar bo razpočen in pepel, ki je na njem, se bo izsul.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Pripetilo se je, da ko je kralj Jerobeám slišal izjavo Božjega moža, ki je zaklical proti oltarju v Betelu, da je svojo roko iztegnil od oltarja, rekoč: »Primite ga.« Njegova roka, ki jo je iztegnil proti njemu, pa se je posušila, tako da je ni mogel povleči nazaj k sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Tudi oltar je bil razpočen in pepel razsut z oltarja, glede na znamenje, ki ga je Božji mož dal po Gospodovi besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Kralj je Božjemu možu odgovoril in rekel: »Prosi sedaj obličje Gospoda, svojega Boga in moli zame, da bo moja roka lahko ponovno povrnjena k meni.« Božji mož je rotil Gospoda in kraljeva roka je bila ponovno povrnjena k njemu in postala, kakor je bila ta poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Kralj je Božjemu možu rekel: »Pridi z menoj domov, osveži se in dal ti bom nagrado.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Božji mož je kralju odgovoril: »Če mi daš polovico svoje hiše, ne bom šel s teboj niti na tem kraju ne bom jedel kruha niti pil vode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Kajti tako mi je bilo naročeno po Gospodovi besedi, rekoč: »Ne jej kruha, niti ne pij vode, niti se ne obračaj ponovno po isti poti, po kateri si prišel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Tako je odšel po drugi poti in se ni vrnil po poti, po kateri je prišel v Betel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Torej v Betelu je prebival star prerok. Njegovi sinovi so prišli in mu povedali vsa dela, ki jih je tisti dan Božji mož storil v Betelu. Tudi besede, ki jih je govoril kralju, so povedali svojemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Njihov oče jim je rekel: »Po kateri poti je odšel?« Kajti njegovi sinovi so videli po kateri poti je odšel Božji mož, ki je prišel iz Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Svojim sinovom je rekel: »Osedlajte mi osla.« Tako so mu osedlali osla, in jahal je na njem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'in odšel za Božjim možem in ga našel sedeti pod hrastom. Rekel mu je: » Ali si ti Božji mož, ki je prišel iz Juda?« Ta je rekel: »Jaz sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Potem mu je rekel: »Pridi z menoj domov in jej kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Ta pa je rekel: »Ne smem se vrniti s teboj, niti vstopiti s teboj, niti na tem kraju ne bom jedel kruha niti pil vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'kajti po Gospodovi besedi mi je bilo rečeno: ›Ti tam ne boš jedel niti kruha niti pil vode niti se ne boš ponovno obrnil, da bi šel po poti, po kateri si prišel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Rekel mu je: »Tudi jaz sem prerok, kot si ti in angel mi je po Gospodovi besedi govoril, rekoč: ›Privedi ga s seboj nazaj v svojo hišo, da bo lahko jedel kruh in pil vodo.‹« Toda lagal mu je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Tako je z njim odšel nazaj in v njegovi hiši jedel kruh in pil vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Pripetilo se je, ko sta sedela pri mizi, da je Gospodova beseda prišla preroku, ki ga je privedel nazaj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'in Božjemu možu, ki je prišel iz Juda, je zaklical, rekoč: »Tako govori Gospod: ›Ker nisi ubogal Gospodovih ust in se nisi držal Gospodove zapovedi, ki ti jo je Gospod, tvoj Bog, zapovedal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'temveč si prišel nazaj in si na tem kraju jedel kruh in pil vodo, o čemer ti je Gospod rekel: ›Ne jej kruha in ne pij nobene vode,‹ tvoje truplo ne bo prišlo v mavzolej tvojih očetov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Pripetilo se je, ko je pojedel kruh in potem ko je popil, da je zanj osedlal osla, namreč za preroka, ki ga je privedel nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Ko je ta odšel, ga je na poti srečal lev in ga usmrtil. Njegovo truplo je bilo vrženo na pot in poleg njega je stal osel, [in] tudi lev je stal poleg trupla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Glej, ljudje so hodili mimo in videli truplo, vrženo na pot in leva, stoječega poleg trupla in prišli so in to povedali v mestu, kjer je živel stari prerok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Ko je prerok, ki ga je privedel nazaj iz poti, slišal o tem, je rekel: »To je Božji mož, ki je bil neposlušen Gospodovi besedi. Zato ga je Gospod izročil levu, ki ga je raztrgal in umoril glede na Gospodovo besedo, ki mu jo je govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Svojim sinovom je spregovoril, rekoč: »Osedlajte mi osla.« In osedlali so mu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Odšel je in na poti našel njegovo truplo ter osla in leva stati poleg trupla. Lev ni pojedel trupla niti raztrgal osla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Prerok je pobral truplo Božjega moža, ga položil na osla in ga privedel nazaj, in stari prerok je prišel v mesto, da žaluje in da ga pokoplje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Njegovo truplo je položil v svoj grob in žalovali so nad njim, rekoč: »Ojoj, moj brat!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Pripetilo se je, potem ko ga je pokopal, da je govoril svojim sinovom, rekoč: »Ko umrem, potem me pokopljite v mavzoleju, v katerem je pokopan Božji mož. Moje kosti položite poleg njegovih kosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'kajti beseda, ki jo je klical po Gospodovi besedi zoper oltar v Betelu in zoper vse hiše visokih krajev, ki so v mestih Samarije, se bo zagotovo zgodila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Po tej stvari se Jerobeám ni odvrnil iz svoje zle poti, temveč je ponovno naredil najnižje izmed ljudi za duhovnike na visokih krajih. Kogarkoli je hotel, je uméstil in ta je postal eden izmed duhovnikov visokih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Ta stvar je postala greh Jerobeámovi hiši, celo, da jo odseka in da jo uniči iz obličja zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Ob tistem času je Jerobeámov sin Abíja zbolel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Jerobeám je rekel svoji ženi: »Vstani, prosim te in se preobleci, da te ne bodo spoznali, da si Jerobeámova žena in pojdi v Šilo. Glej, tam je prerok Ahíja, ki mi je povedal, da naj bi bil jaz kralj nad tem ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'S seboj vzemi deset hlebov, kolačke in vrč medu in pojdi k njemu. Povedal ti bo, kaj bo z otrokom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Jerobeámova žena je tako storila, vstala, odšla v Šilo in prišla k Ahijevi hiši. Toda Ahíja je ni mogel videti, kajti njegove oči so zaradi starosti otemnele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Gospod je rekel Ahiju: »Glej, prihaja Jerobeámova žena, da od tebe prosi stvar za svojega sina, kajti on je bolan. Tako in tako ji boš rekel, kajti tako bo, ko bo vstopila, da se bo pretvarjala, da je druga ženska.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'To je bilo tako, da ko je Ahíja zaslišal glas njenih stopal, ko je vstopila pri vratih, je rekel: »Vstopi, ti Jerobeámova žena; zakaj se pretvarjaš, da si druga? Kajti k tebi sem poslan s težkimi novicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Pojdi, povej Jerobeámu: ›Tako govori Gospod, Izraelov Bog: ›Ker sem te povišal izmed ljudstva in te naredil princa nad svojim ljudstvom Izraelom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'in kraljestvo odtrgal od Davidove hiše in ga dal tebi; pa vendar ti nisi bil kakor moj služabnik David, ki je ohranjal moje zapovedi in ki mi je sledil z vsem svojim srcem, da počne samo to, kar je bilo pravilno v mojih očeh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'temveč si storil zlo bolj kot vsi, ki so bili pred teboj, kajti odšel si in si naredil druge bogove in ulite podobe, da me dražiš do jeze in si me vrgel za svoj hrbet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Zato glej, jaz bom nad Jerobeámovo hišo privedel zlo in od Jerobeáma bom iztrebil tistega, ki lula proti zidu in tistega, ki je zaprt in je ostal v Izraelu in odvzel bom preostanek Jerobeámove hiše, kakor človek odvaža gnoj, dokler ta ves ne izgine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Tistega, ki bo od Jerobeámovih umrl v mestu, bodo žrli psi. Tistega pa, ki umre na polju, bo žrla perjad neba, kajti Gospod je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Vstani torej, pojdi k svoji lastni hiši in ko tvoja stopala vstopijo v mesto, bo otrok umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Ves Izrael bo žaloval za njim in ga pokopal, kajti on bo edini izmed Jerobeámovih prišel do groba, ker se je v Jerobeámovi hiši v njem našla neka dobra stvar do Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Poleg tega si bo Gospod dvignil kralja nad Izraelom, ki bo tisti dan iztrebil Jerobeámovo hišo. Toda kaj? Celo sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Kajti Gospod bo udaril Izraela, kakor se trst maje v vodi in Izraela bo izkoreninil iz te dobre dežele, ki jo je dal njihovim očetom in razkropil jih bo preko reke, ker so si naredili svoje ašere, izzivajoč Gospoda do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Izraela se bo odrekel zaradi grehov Jerobeáma, ki je storil greh in ki je Izraela pripravil, da greši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Jerobeámova žena je vstala, odšla in prišla v Tirco in ko je prišla k pragu vrat, je otrok umrl');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'in pokopali so ga in ves Izrael je žaloval za njim, glede na Gospodovo besedo, ki jo je govoril po roki svojega služabnika, preroka Ahíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Ostala Jerobeámova dela, kako se je vojskoval in kako je kraljeval, glej, ta so zapisana v kroniški knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Dni, ko je Jerobeám kraljeval, je bilo dvaindvajset let in zaspal je s svojimi očeti in namesto njega je zakraljeval njegov sin Nadáb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Salomonov sin Rehabám je kraljeval v Judu. Rehabám je bil star enainštirideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval sedemnajst let, mestu, ki ga je Gospod izbral izmed vseh Izraelovih rodov, da tam postavi svoje ime. Ime njegove matere je bilo Amónka Naáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Juda je počel zlo v Gospodovih očeh in s svojimi grehi, ki so jih zagrešili, so ga dražili do ljubosumnosti, nad vsem, kar so počeli njihovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Kajti zgradili so si tudi visoke kraje, podobe in ašere na vsakem visokem hribu in pod vsakim zelenim drevesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'V deželi so bili tudi posvečeni vlačugarji in ti so počeli glede na vse ogabnosti narodov, ki jih je Gospod pregnal pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Pripetilo se je v petem letu kralja Rehabáma, da je egiptovski kralj Šišák prišel gor nad Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Odnesel je zaklade Gospodove hiše in zaklade kraljeve hiše, celo vse je odnesel. Odnesel je vse zlate ščite, ki jih je Salomon naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Kralj Rehabám je namesto njih naredil bronaste ščite in jih predal v roke vodje straže, ki je varoval vrata kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'To je bilo tako, kadar je kralj odšel v Gospodovo hišo, da jih je straža nosila in jih [potem] ponovno odnesla v stražarnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Torej preostala izmed Rehabámovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Med Rehabámom in Jerobeámom pa je bila vse njune dni vojna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Rehabám je zaspal s svojimi očeti in bil s svojimi očeti pokopan v Davidovem mestu. Ime njegove matere je bilo Amónka Naáma. Namesto njega je zakraljeval njegov sin Abíjam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Torej v osemnajstem letu kralja Jerobeáma, Nebátovega sina, je nad Judom zakraljeval Abíjam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tri leta je kraljeval v Jeruzalemu. Ime njegove matere je bilo Maáha, Abišalómova hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Hodil je v vseh grehih svojega očeta, ki jih je ta storil pred njim in njegovo srce ni bilo popolno z Gospodom, njegovim Bogom, kakor je bilo srce njegovega očeta Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Kljub temu mu je zaradi Davida Gospod, njegov Bog, dal svetilko v Jeruzalemu, da za seboj postavi svojega sina in da vzpostavi Jeruzalem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'ker je David delal to, kar je bilo prav v Gospodovih očeh in se vse dni svojega življenja ni obrnil stran od katerekoli stvari, ki mu jo je zapovedal, razen samo v zadevi Hetejca Urijája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Med Rehabámom in Jerobeámom pa je bila vojna vse dni njegovega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Torej preostala izmed Abíjamovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev? In bila je vojna med Abíjamom in Jerobeámom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Abíjam je zaspal s svojimi očeti in pokopali so ga v Davidovem mestu. Namesto njega je zakraljeval njegov sin Asá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'V dvajsetem letu Izraelovega kralja Jerobeáma, je nad Judom zakraljeval Asá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'V Jeruzalemu je kraljeval enainštirideset let. Ime njegove matere je bilo Maáha, Abišalómova hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asá je delal to, kar je bilo pravilno v Gospodovih očeh, kakor je delal njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Iz dežele je odpravil posvečene vlačugarje in odstranil vse malike, ki so jih naredili njegovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Tudi svojo mater Maáho, celo njo je odstranil, da bi bila kraljica, ker si je v ašeri naredila malika. Asá je uničil njenega malika in ga zažgal pri potoku Kidronu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Toda visokih krajev ni odstranil. Kljub temu je bilo Asájevo srce, vse dni njegovega življenja, popolno z Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'V Gospodovo hišo je prinesel stvari, ki jih je njegov oče posvetil in stvari, ki jih je sam posvetil, srebro, zlato in posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Med Asájem in Izraelovim kraljem Bašájem pa je bila vse njune dni vojna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Izraelov kralj Bašá je odšel gor zoper Juda in zgradil Ramo, da Judovemu kralju Asáju ne bi pustil iti ven ali priti noter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Potem je Asá vzel vse srebro in zlato, ki je ostalo v zakladnicah Gospodove hiše in zakladnicah kraljeve hiše in jih izročil v roko svojih služabnikov. Kralj Asá pa jih je poslal k Ben Hadádu, Tabrimónovemu sinu, Hezjónovemu sinu, kralju Sirije, ki je prebival pri Damasku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '»Zaveza je med menoj in teboj in med mojim očetom in tvojim očetom. Glej, k tebi sem poslal dar iz srebra in zlata. Pridi in prelomi svojo zavezo z Izraelovim kraljem Bašájem, da bo lahko odšel od mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Tako je Ben Hadád prisluhnil kralju Asáju in poslal poveljnike vojsk, ki jih je imel, zoper Izraelova mesta in udaril Ijón, Dan, Abél Bet Maáho in ves Kinéret, z vso Neftálijevo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Pripetilo se je, ko je Bašá slišal o tem, da je prenehal z gradnjo Rame in prebival v Tirci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Potem je kralj Asá po vsej Judeji naredil razglas. Nihče ni bil izvzet. Vzeli so kamne iz Rame in les, s katerim je Bašá gradil in kralj Asá je z njim gradil Gebo Benjamin in Micpo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Preostala izmed vseh Asájevih dejanj in vsa njegova moč in vse, kar je storil in mesta, ki jih je zgradil, mar niso zapisana v kroniški knjigi Judovih kraljev? Kljub temu je bil v času svoje visoke starosti bolan na svojih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Asá je zaspal s svojimi očeti in s svojimi očeti je bil pokopan v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Józafat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Jerobeámov sin Nadáb je začel kraljevati nad Izraelom v drugem letu Judovega kralja Asája in nad Izraelom je kraljeval dve leti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Počel je zlo v Gospodovih očeh in hodil po poti svojega očeta in v njegovem grehu, s katerim je Izraela primoral, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Zoper njega se je zarotil Ahíjev sin Bašá iz Isahárjeve hiše in Bašá ga ja udaril pri Gibetónu, ki pripada Filistejcem, kajti Nadáb in ves Izrael sta oblegala Gibetón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Celo v tretjem letu Judovega kralja Asája ga je Bašá ubil in zakraljeval namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Pripetilo se je, ko je zakraljeval, da je udaril vso Jerobeámovo hišo. Jerobeámu ni pustil nikogar, ki diha, dokler ga ni pokončal, glede na Gospodovo izjavo, ki jo je govoril po svojem služabniku, Šilčanu Ahíju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'zaradi Jerobeámovih grehov, ki jih je ta zagrešil in ki so Izraela pripravili grešiti s svojim izzivanjem, s katerim so Gospoda, Izraelovega Boga, izzivali do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Torej preostala izmed Nadábovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Med Asájem in Izraelovim kraljem Bašájem je bila vse njune dni vojna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'V tretjem letu Judovega kralja Asája je nad Izraelom v Tirci začel kraljevati Ahíjev sin Bašá, štiriindvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Počel je zlo v Gospodovih očeh in hodil po Jerobeámovi poti in v njegovem grehu, s katerim je Izraela primoral, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Potem je Gospodova beseda prišla Hananíjevemu sinu Jehúju zoper Bašája, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '»Ker kakor sem te povišal iz prahu in te naredil princa nad mojim ljudstvom Izraelom in si hodil po Jerobeámovi poti in primoral moje ljudstvo Izraela, da greši, da me z njihovimi grehi dražiš do jeze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'glej, bom odvzel potomstvo Bašája in potomstvo njegove hiše in tvojo hišo bom naredil podobno hiši Nebátovega sina Jerobeáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Tistega, ki od Bašája umre v mestu, bo jedel pes, tistega pa, ki od njegovih umre na poljih, bo žrla perjad neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Torej preostala izmed Bašájevih del in vse, kar je storil in njegova moč, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Tako je Bašá zaspal s svojimi očeti in je bil pokopan v Tirci. Namesto njega je zakraljeval njegov sin Elá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Prav tako je po roki Hananíjevega sina Jehúja prišla Gospodova beseda zoper Bašája in zoper njegovo hišo, celo za vse zlo, ki ga je storil v Gospodovih očeh, v draženju do jeze z deli njegovih rok, ker je bil podoben Jerobeámovi hiši in ker ga je ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'V šestindvajsetem letu Judovega kralja Asája, je nad Izraelom v Tirci [za] dve leti začel kraljevati Bašájev sin Elá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Njegov služabnik Zimrí, poveljnik polovice njegovih bojnih vozov, se je zoper njega zarotil, medtem ko je bil ta v Tirci in se do pijanosti napil v hiši Arcája, oskrbnika njegove hiše v Tirci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimrí je vstopil, ga udaril in ubil v sedemindvajsetem letu Judovega kralja Asája in zakraljeval namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Ko je začel kraljevati, se je pripetilo, da je takoj, ko je sedel na svoj prestol, usmrtil vso Bašájevo hišo. Ni mu pustil niti enega, ki lula proti zidu niti od njegove žlahte niti od njegovih prijateljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Tako je Zimrí uničil vso Bašájevo hišo glede na Gospodovo besedo, ki jo je govoril zoper Bašája po preroku Jehúju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'zaradi vseh Bašájevih grehov in grehov njegovega sina Elája, s katerimi sta grešila in s katerimi sta Izraela pripravila, da greši v draženju Gospoda, Izraelovega Boga, do jeze s svojimi ničevostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Torej preostala izmed Elájevih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'V sedemindvajsetem letu Judovega kralja Asája je Zimrí sedem dni kraljeval v Tirci. Ljudstvo pa je bilo utaborjeno zoper Gibetón, ki je pripadal Filistejcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Ljudstvo, ki je bilo utaborjeno, je slišalo reči: »Zimrí je koval zaroto in tudi umoril kralja.« Zato je ves Izrael ta dan v taboru postavil Omrija, poveljnika vojske, [za] kralja nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Omri se je dvignil iz Gibetóna in ves Izrael z njim in oblegali so Tirco.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Pripetilo se je, ko je Zimrí videl, da je bilo mesto zavzeto, da je odšel v palačo kraljeve hiše in kraljevo hišo nad seboj zažgal z ognjem in umrl');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'zaradi svojih grehov, ki jih je zagrešil v početju zla v Gospodovih očeh, s hojo po Jerobeámovi poti in v svojem grehu, ki ga je storil, da je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Torej preostala izmed Zimríjevih del in njegova izdaja, ki jo je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Potem je bilo Izraelovo ljudstvo razdeljeno na dva dela. Polovica ljudstva je sledila Ginátovemu sinu Tibníju, da ga postavi za kralja, polovica pa je sledila Omriju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Toda ljudstvo, ki je sledilo Omriju, je prevladalo zoper ljudstvo, ki je sledilo Ginátovemu sinu Tibníju. Tako je Tibní umrl, Omri pa zakraljeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'V enaintridesetem letu Judovega kralja Asája je nad Izraelom začel kraljevati Omri, dvanajst let. Šest let je kraljeval v Tirci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Od Šemerja je za dvajset talentov srebra kupil hrib Samarijo in gradil na hribu in ime mesta, ki ga je zgradil, je poimenoval Samarija, po Šemerjevemu imenu, lastniku hriba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Toda Omri je počel zlo v Gospodovih očeh in počel huje kakor vsi, ki so bili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Kajti hodil je po vsej poti Nebátovega sina Jerobeáma in v njegovem grehu, s katerim je Izraela pripravil, da greši, da s svojimi ničevostmi do jeze draži Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Torej preostala izmed Omrijevih dejanj, ki jih je storil in njegova moč, ki jo je pokazal, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Tako je Omri zaspal s svojimi očeti in bil pokopan v Samariji. Namesto njega je zakraljeval njegov sin Aháb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'V osemintridesetem letu Judovega kralja Asája je nad Izraelom začel kraljevati Omrijev sin Aháb in Omrijev sin Aháb je nad Izraelom v Samariji kraljeval dvaindvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Omrijev sin Aháb je počel zlo v Gospodovih očeh, bolj kakor vsi, ki so bili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Pripetilo se je, kakor če je bila to zanj lahka stvar, da hodi v grehih Nebátovega sina Jerobeáma, da je za ženo vzel Jezabelo, hčer Etbáala, kralja Sidóncev in odšel, služil Báalu in ga oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'V Báalovi hiši je postavil oltar za Báala, ki ga je zgradil v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Aháb je naredil ašero in Aháb je storil več kakor vsi Izraelovi kralji, ki so bili pred njim, da draži k jezi Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'V njegovih dneh je Hiél Betelčan zidal Jeriho. Njen temelj je položil v svojem prvorojencu Abirámu in njena velika vrata je postavil v svojem najmlajšem sinu Segúbu, glede na besedo od Gospoda, ki jo je spregovoril po Nunovemu sinu Józuetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Tišbéjec Elija, ki je bil izmed prebivalcev Gileáda, je rekel Ahábu: » Kakor živi Gospod, Izraelov Bog, pred katerim stojim, tukaj ta leta ne bo niti rose niti dežja, razen glede na mojo besedo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Gospodova beseda je prišla k njemu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '»Pojdi od tod in se obrni proti vzhodu in se skrij pri potoku Kerítu, ki je pred Jordanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Zgodilo se bo, da boš pil iz potoka, krokarjem pa sem zapovedal, da te tam hranijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Tako je odšel in storil glede na Gospodovo besedo, kajti odšel je in prebival pri potoku Kerítu, ki je pred Jordanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Krokarji so mu prinašali kruh in meso zjutraj ter kruh in meso zvečer, pil pa je iz potoka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Čez nekaj časa se je pripetilo, da je potok usahnil, ker v deželi ni bilo dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'K njemu je prišla beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '»Vstani, pojdi v Zarepto, ki pripada Sidónu in prebivaj tam. Glej, tamkajšnji vdovi sem zapovedal, da te podpira.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Tako je vstal in odšel v Zarepto. Ko je prišel k velikim vratom mesta, glej, je bila tam ženska vdova, ki je nabirala veje. Zaklical je k njej ter ji rekel: »Prinesi mi, prosim te, malo vode v posodi, da lahko pijem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Ko je šla, da bi to prinesla, je zaklical k njej in rekel: »Prinesi mi, prosim te, grižljaj kruha v svoji roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Rekla je: » Kakor Gospod, tvoj Bog, živi, nimam kolača, temveč prgišče moke v sodčku in malo olja v vrču in glej, nabiram dve palici, da lahko grem in to pripravim zase in za svojega sina, da bova to lahko pojedla in umrla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elija ji je rekel: »Ne boj se. Pojdi in stôri, kakor si rekla. Toda od tega najprej meni naredi majhen kolač in mi ga prinesi, potem pa naredi zase in za svojega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Kajti tako govori Gospod, Izraelov Bog: ›Sodček z moko ne bo pošel niti v vrču ne bo zmanjkalo olja do dneva, ko Gospod pošlje dež na zemljo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Odšla je in storila glede na Elijevo izjavo. Ona, on in njena hiša so jedli mnogo dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'In sodček z moko ni pošel niti olja v vrču ni zmanjkalo, glede na Gospodovo besedo, ki jo je govoril po Eliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Po teh stvareh se je pripetilo, da se je sin ženske, gospodarice hiše, počutil bolnega, in njegova slabost je bila tako huda, da v njem ni ostalo nobenega diha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Eliju je rekla: »Kaj imam s teboj, oh ti Božji mož? Ali si prišel k meni, da mi prikličeš moj greh v spomin in da ubiješ mojega sina?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Rekel ji je: »Daj mi svojega sina.« Vzel ga je iz njenega naročja in ga odnesel gor na podstrešje, kjer je prebival in ga položil na svojo lastno posteljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Klical je h Gospodu in rekel: »Oh Gospod, moj Bog, mar si zlo privedel tudi nad to vdovo, pri kateri se mudim, s pokončanjem njenega sina?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Trikrat se je raztegnil nad otrokom, klical h Gospodu in rekel: »Oh Gospod, moj Bog, prosim te, naj se duša tega otroka ponovno vrne vanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Gospod je uslišal Elijev glas in otrokova duša se je ponovno vrnila vanj in je oživel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Elija je vzel otroka, ga privedel dol iz sobe v hišo in ga izročil njegovi materi. Elija je rekel: »Poglej, tvoj sin živi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Ženska je rekla Eliju: »Po tem sedaj vem, da si Božji mož in da je Gospodova beseda v tvojih ustih resnična.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Po mnogih dneh se je pripetilo, da je Gospodova beseda prišla k Eliju v tretjem letu, rekoč: »Pojdi, pokaži se Ahábu in jaz bom na zemljo poslal dež.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Elija je odšel, da se pokaže Ahábu. Tam v Samariji pa je bila huda lakota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Aháb je poklical Obadjá, ki je bil voditelj njegove hiše. (Torej Obadjá se je silno bal Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Kajti to je bilo tako, ko je Jezabela iztrebila Gospodove preroke, da je Obadjá vzel sto prerokov in jih po petdeset skril v votlino in jih hranil s kruhom in vodo.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Aháb je rekel Obadjáju: »Pojdi v deželo, k vodnim studencem in k vsem potokom. Morda bomo lahko našli travo, da rešimo konje in mule žive, da ne izgubimo vseh živali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Tako sta si razdelila deželo, da gresta skoznjo. Aháb je sam odšel eno pot, Obadjá pa je odšel drugo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Ko je bil Obadjá na poti, glej, ga je srečal Elija. Ta ga je spoznal in padel na svoj obraz ter rekel: » Ali si ti, moj gospod Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Odgovoril mu je: »Jaz sem. Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Rekel je: »Kaj sem grešil, da hočeš svojega služabnika izročiti v Ahábovo roko, da me ubije?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Kakor živi Gospod, tvoj Bog, ni ne naroda ne kraljestva, kamor moj gospodar ni poslal, da te poiščejo. In ko so rekli: › Njega ni tukaj,‹ je od kraljestva in naroda vzel prisego, da te niso našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'In sedaj praviš: ›Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Takoj, ko odidem od tebe, se bo zgodilo, da te bo Gospodov Duh odnesel ne vem kam. Ko pridem in povem Ahábu in te ne bo mogel najti, bo tako, da me bo ubil. Vendar se jaz, tvoj služabnik, od svoje mladosti bojim Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Mar ni bilo povedano mojemu gospodu kaj sem storil, ko je Jezabela usmrtila Gospodove preroke, kako sem skril sto mož, Gospodovih prerokov, po petdeset v votlino in jih hranil s kruhom in vodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Sedaj pa praviš: ›Pojdi, povej svojemu gospodarju: ›Glej, Elija je tukaj ‹ in me bo ubil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elija je rekel: » Kakor živi Gospod nad bojevniki, pred katerim stojim, se mu bom danes zagotovo pokazal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Tako je Obadjá odšel, da sreča Ahába in povedal mu je. Aháb je odšel, da sreča Elija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Pripetilo se je, ko je Aháb zagledal Elija, da mu je Aháb rekel: » Si ti ta, ki nadleguje Izraela?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'In ta je odgovoril: »Nisem jaz nadlegoval Izraela, temveč ti in hiša tvojega očeta v tem, da ste zapustili Gospodove zapovedi, ti pa si sledil Báalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Zdaj torej pošlji in zberi k meni ves Izrael na goro Karmel in štiristo petdeset Báalovih prerokov in štiristo Ašerinih prerokov, ki jedo za Jezabelino mizo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Tako je Aháb poslal k vsem Izraelovim otrokom in preroke skupaj zbral h gori Karmel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Elija je prišel k vsemu ljudstvu in rekel: »Doklej omahujete med dvema možnostma? Če Gospod je Bog, sledite njemu, toda če je Báal, potem sledite njemu.« Ljudstvo pa mu ni odgovorilo niti besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Potem je Elija rekel ljudstvu: »Jaz, celó samo jaz sem ostal Gospodov prerok, toda Báalovih prerokov je štiristo petdeset mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Naj nam torej dajo dva bikca in naj si enega bikca izberejo zase, ga razrežejo na koščke in ga položijo na les in pod njim ne podtaknejo ognja, jaz pa bom pripravil drugega bikca in ga položil na les in pod njim ne podtaknem ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Kličite k imenu svojih bogov, jaz pa bom klical h Gospodovemu imenu. Bog, ki odgovarja z ognjem, naj bo on Bog.« Vse ljudstvo je odgovorilo in reklo: »To je dobro rečeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, '§ Elija je Báalovim prerokom rekel: »Izberite si enega bikca zase in tega pripravite najprej, kajti vas je mnogo, in kličite ime svojih bogov, toda spodaj ne podnetite ognja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Vzeli so bikca, ki jim je bil dan in ga pripravili in od jutra do poldneva klicali k Báalovemu imenu, rekoč: »Oh Báal, usliši nas.« Toda ni bilo nobenega glasu niti nikogar, da bi odgovoril. In poskakovali so na oltarju, ki je bil narejen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Pripetilo se je opoldan, da jih je Elija zasmehoval in rekel: »Glasno vpijte, kajti on je bog; ali klepeta ali zalezuje ali je na potovanju ali morda spi in mora biti prebujen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Glasno so vpili in se po svoji navadi rezali z noži in nožiči, dokler ni po njih lila kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Pripetilo se je, ko je sredina dneva minila in so prerokovali do časa darovanja večerne daritve, da tam ni bilo, niti glasu niti odgovora, niti nikogar, ki bi upošteval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Elija je rekel vsemu ljudstvu: »Pridite bliže k meni.« In vse ljudstvo je prišlo bliže k njemu. Popravil je Gospodov oltar, ki je bil razrušen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elija je vzel dvanajst kamnov, glede na število rodov Jakobovih sinov, ki mu je prišla Gospodova beseda, rekoč: »Izrael bo tvoje ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'S kamni je v Gospodovem imenu zgradil oltar, in okoli oltarja naredil jarek, tako velik, da bi lahko vseboval dve meri semen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Les je postavil v red in bikca razsekal na koščke, ga položil na les in rekel: »Napolnite štiri sodčke z vodo in jih izlijte na žgalno daritev in na les.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Rekel je: » To storite drugič.« In to so storili drugič. Rekel je: » To storite tretjič.« In to so storili tretjič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Voda je tekla naokoli oltarja in tudi jarek je napolnil z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Ob času darovanja večerne daritve se je pripetilo, da se je približal prerok Elija in rekel: » Gospod, Bog Abrahama, Izaka in Izraela, naj bo to znano ta dan, da si ti Bog v Izraelu in da sem jaz tvoj služabnik in da sem vse te stvari storil na tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Prisluhni mi, oh Gospod, prisluhni mi, da bo to ljudstvo lahko vedelo, da si ti Gospod Bog in da si ti njihova srca ponovno obrnil nazaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Potem je padel Gospodov ogenj in použil žgalno daritev, les, kamne, prah in polizal vodo, ki je bila v jarku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Ko je vse ljudstvo to videlo, so padli na svoje obraze in rekli: » Gospod, on je Bog; Gospod, on je Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elija jim je rekel: »Primite Báalove preroke, naj nobeden izmed njih ne pobegne.« Prijeli so jih in Elija jih je odvedel dol k potoku Kišónu in jih tam usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elija je rekel Ahábu: »Vstani, jej in pij, kajti tam je zvok obilja dežja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Tako je Aháb odšel gor, da jé in da pije. Elija pa je odšel gor, na vrh Karmela in se vrgel dol na zemljo in svoj obraz dal med svoja kolena');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'in svojemu služabniku rekel: »Pojdi sedaj gor, glej proti morju.« In ta je odšel gor, pogledal in rekel: » Tam ni nič.« Rekel je: »Pojdi ponovno, sedemkrat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Pripetilo se je sedmič, da je rekel: »Glej, tam vstaja iz morja majhen oblak, podoben človeški roki.« Rekel je: »Pojdi gor in reci Ahábu: ›Pripravi svoj bojni voz in se spusti dol, da te ne ustavi dež.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'V vmesnem času se je pripetilo, da je bilo nebo črno z oblaki in vetrom in tam je bil velik dež. Aháb je jahal in šel v Jezreél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Gospodova roka pa je bila na Eliju. Opasal je svoja ledja in pred Ahábom tekel k vhodu v Jezreél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Aháb je Jezabeli povedal vse, kar je storil Elija in poleg tega, kako je z mečem umoril vse preroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Potem je Jezabela k Eliju poslala poslanca, rekoč: »Tako naj mi storijo bogovi in tudi več, če ne bom jutri okrog tega časa naredila tvojega življenja kakor življenja enega izmed teh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Ko je to videl, je vstal in hodil za svoje življenje in prišel v Beeršébo, ki pripada Judu in tam pustil svojega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Toda on sam je odšel pot enega dne v divjino in prišel ter se usedel pod brinovo drevo. In zase je zahteval, da bi lahko umrl in rekel: »Dovolj je. Sedaj, oh Gospod, vzemi moje življenje, kajti nisem boljši kakor moji očetje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Ko se je ulegel in pod brinovim drevesom zaspal, glej, takrat se ga je dotaknil angel in mu rekel: »Vstani in jej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Pogledal je in glej, tam je bil kolač, pečen na ogorkih in vrč vode pri njegovi glavi. Jedel je in pil ter ponovno legel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Gospodov angel je ponovno prišel, drugič, se ga dotaknil in rekel: »Vstani in jej, kajti potovanje je preveliko zate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Vstal je, jedel, pil in hodil v moči te hrane štirideset dni in štirideset noči do Božje gore Horeb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'In prišel tja v votlino ter tam prenočil. Glej, k njemu je prišla beseda od Gospoda in on mu je rekel: »Kaj delaš tukaj, Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Rekel je: »Bil sem zelo goreč za Gospoda, Boga nad bojevniki, kajti Izraelovi otroci so zapustili tvojo zavezo, zrušili tvoje oltarje in z mečem pomorili tvoje preroke, in jaz, celó samo jaz sem ostal in strežejo mi po življenju, da bi mi ga vzeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'In on je rekel: »Pojdi naprej in stoj na gori pred Gospodom.« Glej, Gospod je šel mimo in velik, močan veter je trgal gore in skale drobil na koščke pred Gospodom, toda Gospoda ni bilo v vetru. In za vetrom potres, toda Gospoda ni bilo v potresu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'In za potresom ogenj, toda Gospod ni bil v ognju. In za ognjem tih, majhen glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Bilo je tako, ko je Elija to slišal, da je svoj obraz zavil v svoje ogrinjalo in odšel ven in stal na vhodu votline. Glej, tam je prišel k njemu glas in rekel: »Kaj delaš tukaj, Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Rekel je: »Bil sem zelo goreč za Gospoda, Boga nad bojevniki, ker so Izraelovi otroci zapustili tvojo zavezo, zrušili tvoje oltarje in z mečem pomorili tvoje preroke. Jaz, celó samo jaz sem ostal in strežejo mi po življenju, da bi mi ga vzeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Gospod mu je rekel: »Pojdi, vrni se po svoji poti k divjini Damaska in ko prideš, mazili Hazaéla, da postane kralj nad Sirijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Nimšíjevega sina Jehúja pa boš mazilil, da bo kralj nad Izraelom. Šafátovega sina Elizeja, iz Abél Mehóle, pa boš mazili, da bo prerok namesto tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Zgodilo se bo, da tisti, ki pobegne Hazaélovemu meču, ga bo ubil Jehú. Tistega, ki pobegne pred Jehújevim mečem, pa bo ubil Elizej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Vendar sem si jih pustil v Izraelu sedem tisoč, vsa kolena, ki se niso upognila Báalu in vsaka usta, ki ga niso poljubila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Tako je odpotoval od tam in našel Šafátovega sina Elizeja, ki je oral z dvanajstimi volovskimi jarmi pred seboj in on je bil z dvanajstim. Elija je šel mimo njega in svoje ogrinjalo vrgel nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Ta je pustil vole in stekel za Elijem ter rekel: »Pusti me, prosim te, poljubiti svojega očeta in svojo mater in potem ti bom sledil.« Rekel mu je: »Pojdi ponovno nazaj, kajti kaj sem ti storil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Vrnil se je nazaj od njega, vzel volovski jarem, jih usmrtil in njihovo meso skuhal z volovskimi pripravami in dal ljudstvu in so jedli. Potem je vstal, odšel za Elijem in mu služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Sirski kralj Ben Hadád je zbral skupaj vso svojo vojsko, in tam je bilo z njim dvaintrideset kraljev, konji in bojni vozovi. Odšel je gor, oblegal Samarijo in se vojskoval zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'V mesto je poslal poslance, k Izraelovemu kralju Ahábu in mu rekel: »Tako govori Ben Hadád:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, '›Tvoje srebro in tvoje zlato je moje. Tudi tvoje žene in tvoji otroci, celó najčednejši, so moji.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Izraelov kralj je odgovoril in rekel: »Moj gospod, oh kralj, glede na tvoj govor: ›Jaz sem tvoj in vse kar imam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Poslanci so ponovno prišli in rekli: »Tako govori Ben Hadád, rekoč: ›Čeprav sem poslal k tebi, rekoč: ›Izročil mi boš svoje srebro, svoje zlato, svoje žene in svoje otroke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'bom vendar naslednji dan, okrog tega časa, k tebi poslal svoje služabnike in preiskali bodo tvojo hišo in hiše tvojih služabnikov, in zgodilo se bo, da karkoli je prijetno v tvojih očeh, da bodo to položili v svojo roko in to odnesli proč.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Potem je Izraelov kralj poklical vse starešine dežele in rekel: »Spoznajte, prosim vas in poglejte, kako ta mož išče vragolijo, kajti k meni je poslal po moje žene, po moje otroke, po moje srebro in po moje zlato, pa mu nisem odrekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Vse starešine in vse ljudstvo mu je reklo: »Ne prisluhni mu niti ne privoli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Zatorej je Ben Hadádovim poslancem rekel: »Mojemu gospodu kralju povejte: ›Vse, po kar si prvič poslal k svojemu služabniku, bom storil, toda te stvari ne morem storiti.‹« Poslanci so odšli in mu ponovno prinesli besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Ben Hadád je poslal k njemu in rekel: »Bogovi naj mi tako storijo in še več, če bo prah Samarije zadoščal za prgišča vsega ljudstva, ki mi sledi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Izraelov kralj je odgovoril in rekel: »Povej mu: ›Naj se tisti, ki si opasuje opremo, ne baha kakor, da jo je že odložil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Pripetilo se je, ko je Ben Hadád slišal to sporočilo, medtem ko je pil on in kralji v paviljonih, da je rekel svojim služabnikom: »Postrojite se v vrsto.« In postavili so se v vrsto zoper mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Glej, tam je h kralju Ahábu prišel prerok iz Izraela, rekoč: »Tako govori Gospod: ›Ali si videl vso to veliko množico? Glej, ta dan jo bom izročil v tvojo roko, in ti boš vedel, da sem jaz Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Aháb je rekel: »Po kom?« Rekel je: »Tako govori Gospod: › Celó po mladeničih princev provinc.‹« Potem je rekel: »Kdo bo ukazoval bitki?« Odgovoril je: »Ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Potem je preštel mladeniče princev provinc in bilo jih je dvesto dvaintrideset. Za njimi je preštel vse ljudstvo, celo vse Izraelove otroke, bilo [jih je] sedem tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Ven so odšli opoldan. Toda Ben Hadád se je v paviljonih opijal do pijanosti, on in kralji, dvaintrideset kraljev, ki so mu pomagali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Mladeniči princev provinc so prvi odšli ven in Ben Hadád je poslal ven in povedali so mu, rekoč: »Tam so prišli možje iz Samarije.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Rekel je: »Če so prišli ven za mir, jih ujemite žive, ali če so prišli ven za vojno, jih ujemite žive.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Tako so ti mladeniči princev provinc prišli ven iz mesta in vojska, ki jim je sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Usmrtili so vsak svojega moža in Sirci so zbežali, Izrael pa jih je zasledoval in sirski kralj Ben Hadád je s konjeniki pobegnil na konju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Izraelov kralj je odšel ven in udaril konje in vozove in Sirce usmrtil z velikim pokolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Prerok je prišel k Izraelovemu kralju in mu rekel: »Pojdi, okrepi se in se ozri in poglej kaj počneš, kajti ob vrnitvi leta bo kralj iz Sirije ponovno prišel gor zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Služabniki kralja iz Sirije so mu rekli: »Njihovi bogovi so bogovi hribov, zato so bili močnejši kakor mi, toda naj se borimo zoper njih na ravnini in bomo zagotovo močnejši kakor oni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Stôri to stvar. Kralje vzemi proč, vsakega moža iz svojega kraja in namesto njih postavi poveljnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Naštej si vojsko, podobno vojski, ki si jo izgubil, konja za konja in bojni voz za bojni voz, in mi se bomo borili zoper njih na ravnini in bomo zagotovo močnejši kakor oni.« Prisluhnil je njihovemu glasu in tako storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Pripetilo se je ob vrnitvi leta, da je Ben Hadád preštel Sirce in odšel gor v Afék, da se bori zoper Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Izraelovi otroci so bili prešteti in so bili vsi prisotni in odšli zoper njih. Izraelovi otroci so se utaborili pred njimi kakor dva majhna tropa kozličkov, toda Sirci so napolnili deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Prišel je Božji mož in spregovoril Izraelovemu kralju ter rekel: »Tako govori Gospod: ›Ker so Sirci rekli: › Gospod je Bog hribov, toda on ni Bog dolin, zato bom vso to veliko množico izročil v tvojo roko in spoznali boste, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Sedem dni so taborili eden nasproti drugemu. In bilo je tako, da so se na sedmi dan spoprijeli in Izraelovi otroci so v enem dnevu izmed Sircev usmrtili sto tisoč pešcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Toda ostali so pobegnili v Afék, v mesto in tam je obzidje padlo na sedemindvajset tisoč mož, ki so ostali. Ben Hadád pa je pobegnil in prišel v mesto, v notranjo sobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Njegovi služabniki so mu rekli: »Glej sedaj, slišali smo, da so kralji Izraelove hiše usmiljeni kralji. Pusti nam, prosimo te, da opašemo vrečevino okoli svojih ledij in vrvi na svoje glave in pojdimo ven k Izraelovemu kralju. Morda bo rešil tvoje življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Tako so na svoja ledja opasali vrečevino, na svoje glave položili vrvi in prišli k Izraelovemu kralju ter rekli: »Tvoj služabnik Ben Hadád govori: ›Prosim te, pusti me živega.‹« Rekel je: »Je še živ? On je moj brat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Torej možje so marljivo opazovali ali bo katerakoli stvar prišla od njega in jo hitro zgrabili ter rekli: »Tvoj brat Ben Hadád.« Potem je rekel: »Pojdite, privedite ga.« Potem je Ben Hadád prišel naravnost k njemu in dal mu je, da je prišel gor v bojni voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ben Hadád mu je rekel: »Mesta, ki jih je moj oče vzel od tvojega očeta, bom povrnil in zase si boš naredil ulice v Damasku, kakor jih je moj oče naredil v Samariji.« Potem je Aháb rekel: »S to zavezo te bom poslal proč.« Tako je z njim sklenil zavezo in ga poslal proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Nek mož, izmed preroških sinov, je rekel svojemu bližnjemu po Gospodovi besedi: »Udari me, prosim te.« Človek pa je odklonil, da bi ga udaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Potem mu je rekel: »Ker nisi ubogal Gospodovega glasu, glej, te bo takoj, ko odideš od mene, ubil lev.« In takoj, ko je odšel od njega, ga je našel lev in ga usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Potem je našel drugega moža in rekel: »Udari me, prosim te.« Mož ga je udaril, tako da ga je pri udarjanju ranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Tako je prerok odšel in ob poti čakal na kralja in se preoblekel, s pepelom na svojem obrazu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Ko je kralj šel mimo, je ta vpil h kralju in rekel: »Tvoj služabnik je odšel ven v sredo bitke in glej, mož se je obrnil vstran in mi privedel moža ter rekel: ›Varuj tega moža. Če bo na kakršenkoli način ta izginil, potem bo tvoje življenje za njegovo življenje ali pa boš plačal talent srebra.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Medtem ko je bil tvoj služabnik zaposlen tukaj in tam, je oni odšel.« Izraelov kralj mu je rekel: »Takšna bo tvoja sodba; ti si jo odločil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, '§ Pohitel je in si iz svojega obraza obrisal pepel in Izraelov kralj ga je prepoznal, da je bil izmed prerokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'In ta mu je rekel: »Tako govori Gospod: ›Ker si iz svoje roke izpustil moža, ki sem ga določil za popolno uničenje, zato bo šlo tvoje življenje za njegovo življenje in tvoje ljudstvo za njegovo ljudstvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Izraelov kralj je odšel k svoji hiši hud in nezadovoljen ter prišel v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Po teh stvareh se je pripetilo, da je imel Jezreélec Nabót vinograd, ki je bil v Jezreélu, čisto pri palači samarijskega kralja Ahába.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Aháb je spregovoril Nabótu, rekoč: »Daj mi svoj vinograd, da ga bom lahko imel za zeliščni vrt, ker je ta čisto pri moji hiši, jaz pa ti bom zanj dal boljši vinograd, kakor je ta. Ali pa, če se ti zdi dobro, ti bom dal njegovo vrednost v denarju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nabót je rekel Ahábu: » Gospod me obvaruj, da bi ti dal dediščino svojih očetov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Aháb je prišel v svojo hišo zlovoljen in jezen, zaradi besede, ki mu jo je govoril Jezreélec Nabót, kajti rekel je: »Ne bom ti dal dediščine svojih očetov.« Ulegel se je na svojo posteljo in svoj obraz obrnil stran in ni hotel jesti kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Toda njegova žena Jezabela je prišla k njemu in mu rekla: »Zakaj je tvoj duh tako žalosten, da ne ješ kruha?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Rekel ji je: »Ker sem govoril Jezreélcu Nabótu in mu rekel: ›Daj mi svoj vinograd za denar. Ali, če ti ugaja, ti bom zanj dal drug vinograd. Pa je odgovoril: ›Ne bom ti dal svojega vinograda.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Njegova žena Jezabela mu je rekla: »Mar ne vladaš sedaj ti Izraelovemu kraljestvu? Vstani in jej kruh in naj bo tvoje srce veselo. Jaz ti bom dala vinograd Jezreélca Nabóta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Tako je v Ahábovem imenu napisala pisma in jih zapečatila z njegovim pečatom in pisma poslala k starešinam in k plemičem, ki so bili v njenem mestu in prebivali z Nabótom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'V pismih je napisala, rekoč: »Razglasite post in Nabóta postavite visoko med ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Predenj postavite dva moža, Beliálova sinova, da pričujeta zoper njega, rekoč: ›Preklinjal si Boga in kralja.‹ Potem ga odvedite ven in ga kamnajte, da bo lahko umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Ljudje iz njegovega mesta, torej starešine in plemiči, ki so bili prebivalci v njegovem mestu, so storili, kakor jim je poslala Jezabela in kakor je bilo to zapisano v pismih, ki jih je poslala k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Razglasili so post in Nabóta postavili na visoko med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Vstopila sta dva moža, Beliálova otroka in se usedla pred njim. Beliálova moža sta v prisotnosti ljudstva pričevala zoper njega, torej zoper Nabóta, rekoč: »Nabót je preklinjal Boga in kralja.« Potem so ga odvedli ven iz mesta in kamnali s kamni, da je ta umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Potem so poslali k Jezabeli, rekoč: »Nabót je kamnan in je mrtev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Pripetilo se je, ko je Jezabela slišala, da je bil Nabót kamnan in je bil mrtev, da je Jezabela rekla Ahábu: »Vstani, vzemi posest vinograda Jezreélca Nabóta, ki ti jo je odklonil dati za denar, kajti Nabót ni živ, temveč mrtev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Ko je Aháb slišal, da je bil Nabót mrtev, se je pripetilo, da je Aháb vstal, da gre dol v vinograd Jezreélca Nabóta, da ga vzame v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Gospodova beseda je prišla Tišbéjcu Eliju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '»Vstani, pojdi dol, da srečaš Izraelovega kralja Ahába, ki je v Samariji. Glej, on je v Nabótovem vinogradu, kamor je odšel dol, da ga vzame v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, '§ Spregovoril mu boš, rekoč: ›Tako govori Gospod: ›Ali si ubil in tudi vzel v last?‹ Spregovoril mu boš, rekoč: ›Tako govori Gospod: ›Na kraju, kjer so psi lizali Nabótovo kri, bodo psi lizali tvojo kri, celo tvojo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Aháb je rekel Eliju: »Ali si me našel, oh moj sovražnik?« Ta je odgovoril: »Našel sem te, ker si se prodal, da počneš zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Glej, nadte bom privedel zlo in ti odvedel tvoje potomstvo in od Ahába bom iztrebil karkoli, kar lula proti zidu in tistega, ki je zaprt in je ostal v Izraelu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'in tvojo hišo bom naredil podobno hiši Nebátovega sina Jerobeáma in podobno hiši Ahíjevega sina Bašája, zaradi izzivanja, s katerim ste me dražili do jeze in Izraela pripravili, da greši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, '§ Gospod je spregovoril tudi o Jezabeli, rekoč: »Psi bodo žrli Jezabelo pri jezreélskem zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Kdor od Ahába umre v mestu, ga bodo žrli psi. Tistega, ki umre na polju, pa bo žrla perjad neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Toda nikogar ni bilo podobnega Ahábu, ki bi se prodal, da počne zlobnost v Gospodovih očeh, katerega je razvnela njegova žena Jezabela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Zelo gnusno je počel v sledenju malikom, glede na vse stvari, kakor so storili Amoréjci, ki jih je Gospod pregnal pred Izraelovimi otroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Ko je Aháb slišal te besede, se je pripetilo, da je pretrgal svoja oblačila in si na svoje meso nadel vrečevino, se postil, ležal v vrečevini in tiho hodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Gospodova beseda je prišla k Tišbéjcu Eliju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '»Ali vidiš, kako se je Aháb ponižal pred menoj? Ker se ponižuje pred menoj, zla ne bom privedel v njegovih dneh, temveč bom v dneh njegovega sina nad njegovo hišo privedel zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Tri leta so nadaljevali brez vojne med Sirijo in Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'V tretjem letu pa se je pripetilo, da je Judov kralj Józafat prišel dol k Izraelovemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Izraelov kralj je rekel svojim služabnikom: »Ali veste, da je Ramót v Gileádu naš, in mi bomo mirni in ga ne bomo vzeli iz roke sirskega kralja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Józafatu je rekel: »Hočeš z menoj iti v bitko k Ramót Gileádu?« Józafat je Izraelovemu kralju rekel: »Jaz sem, kakor si ti, moje ljudstvo kakor tvoje ljudstvo, moji konji kakor tvoji konji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Józafat je Izraelovemu kralju rekel: »Prosim te, danes poizvedi pri besedi od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Potem je Izraelov kralj zbral skupaj preroke, okoli štiristo mož in jim rekel: »Ali naj grem zoper Ramót Gileád v bitko ali naj to opustim?« Rekli so: »Pojdi gor, kajti Gospod ga bo izročil v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Józafat je rekel: » Ali tukaj ni več Gospodovega preroka, da bi lahko poizvedeli od njega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Izraelov kralj je rekel Józafatu: » Tukaj je še en mož, Jimlájev sin Miha, po katerem bi lahko poizvedeli od Gospoda. Toda sovražim ga, kajti glede mene ni dobro prerokoval, temveč zlo.« Józafat je rekel: »Naj kralj ne govori tako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Potem je Izraelov kralj poklical častnika in rekel: »Podvizaj sem Jimlájevega sina Miha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Izraelov kralj in Judov kralj Józafat sta sedela vsak na svojem prestolu, oblečena sta imela svoja svečana oblačila, na odprtem prostoru, pri vhodu velikih vrat Samarije in vsi preroki so prerokovali pred njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Cidkijá, Kenaanájev sin, si je naredil rogove iz železa in rekel: »Tako govori Gospod. ›S temi boš bodel Sirce, dokler jih ne boš použil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Vsi preroki so prerokovali tako, rekoč: »Pojdi gor k Ramót Gileádu in bodi uspešen, kajti Gospod ga bo izročil v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Poslanec, ki je odšel, da pokliče Miha, mu je spregovoril, rekoč: »Glej torej, besede prerokov kralju soglasno razglašajo dobro. Naj bo tvoja beseda, prosim te, kakor beseda enega izmed njih in govori to, kar je dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Miha pa je rekel: » Kakor živi Gospod, kar mi Gospod reče, to bom govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Tako je prišel h kralju in kralj mu je rekel: »Miha ali naj gremo zoper Ramót Gileád, da se bojujemo ali naj opustimo?« Ta mu je odgovoril: »Pojdi in bodi uspešen, kajti Gospod ga bo izročil v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Kralj pa mu je rekel: »Kolikokrat te bom zaklinjal, da mi ne poveš ničesar razen tega, kar je resnično v Gospodovem imenu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'In ta je rekel: »Videl sem vsega Izraela razkropljenega na hribih kakor ovce, ki nimajo pastirja. Gospod je rekel: ›Ti nimajo gospodarja. Naj se v miru vrnejo, vsak mož k svoji hiši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Izraelov kralj je rekel Józafatu: »Ali ti nisem rekel, da glede mene ne bo prerokoval nobene dobre stvari, temveč zlo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Rekel je: »Poslušaj torej Gospodovo besedo: ›Videl sem Gospoda sedeti na njegovem prestolu in vso nebeško vojsko stati pri njem, na njegovi desnici in na njegovi levici.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Gospod je rekel: ›Kdo bo pregovoril Ahába, da bo lahko šel gor in padel pri Ramót Gileádu?‹ Nekdo je rekel na ta način, drugi pa na drug način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tam pa je prišel naprej duh in obstal pred Gospodom ter rekel: ›Jaz ga bom prepričal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Gospod mu je rekel: ›S čim?‹ Rekel je: ›Šel bom naprej in bom lažniv duh v ustih vseh njegovih prerokov.‹ Rekel je: ›Ti ga boš prepričal in tudi prevladal. Pojdi naprej in stori tako.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Zdaj torej glej, Gospod je položil lažnivega duha v usta vseh teh tvojih prerokov in Gospod je glede tebe govoril zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Toda Kenaanájev sin Cidkijá je prišel bliže in Miha udaril po licu ter rekel: »Katero pot je Gospodov Duh odšel od mene, da govori tebi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Miha je rekel: »Glej, videl boš tisti dan, ko boš šel v najnotranjejšo sobo, da se skriješ.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Izraelov kralj je rekel: »Vzemi Miha in ga odvedi nazaj k Amónu, voditelju mesta in h kraljevemu sinu Joášu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'ter reci: ›Tako govori kralj: ›Postavita tegale v ječo in ga hranita s kruhom stiske in z vodo stiske, dokler ne pridem v miru.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Miha je rekel: »Če se sploh vrneš v miru, Gospod ni govoril po meni.« In rekel je: »Prisluhni, oh ljudstvo, vsakdo izmed vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Tako sta Izraelov kralj in Judov kralj Józafat odšla gor k Ramót Gileádu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Izraelov kralj je rekel Józafatu: »Jaz se bom zamaskiral in vstopil v bitko, toda ti si nadeni svoja svečana oblačila.« Izraelov kralj se je zamaskiral in odšel v bitko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Toda sirski kralj je zapovedal svojim dvaintridesetim poveljnikom, ki so poveljevali nad njegovimi bojnimi vozovi, rekoč: »Ne borite se niti z majhnim niti z velikim, razen samo z Izraelovim kraljem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Pripetilo se je, ko so poveljniki bojnih vozov zagledali Józafata, da so rekli: »To je zagotovo Izraelov kralj.« Obrnili so se vstran, da se bojujejo zoper njega. Józafat pa je zavpil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Pripetilo se je, ko so poveljniki bojnih vozov zaznali, da to ni bil Izraelov kralj, da so se obrnili od zasledovanja za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Nek mož pa je preprosto napel lok in Izraelovega kralja zadel med člene prsnega oklepa. Zato je vozniku svojega bojnega voza rekel: »Obrni svojo roko in me odvedi ven iz bojišča, kajti ranjen sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Bitka je ta dan narasla in kralj je ostal pokonci na svojem bojnem vozu zoper Sirce in zvečer umrl. Kri iz rane je tekla na sredo bojnega voza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Okoli sončnega zahoda je po vsej vojski šel razglas, rekoč: »Vsak mož k svojemu mestu in vsak mož k svoji lastni deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Tako je kralj umrl in bil priveden v Samarijo in kralja so pokopali v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'V samarijskem ribniku je nekdo umival bojni voz in psi so lizali njegovo kri in umili so njegovo bojno opremo, glede na Gospodovo besedo, ki jo je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Torej preostala izmed Ahábovih dejanj in vse, kar je storil in slonokoščena hiša, ki jo je naredil in vsa mesta, ki jih je zgradil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Tako je Aháb zaspal s svojimi očeti in namesto njega je zakraljeval njegov sin Ahazjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'V četrtem letu Izraelovega kralja Ahába je nad Judom začel kraljevati Asájev sin Józafat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Józafat je bil star petintrideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval petindvajset let. Ime njegove matere je bilo Azúba, Šilhíjeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Hodil je po vseh poteh svojega očeta Asája. Ni se obrnil vstran od tega; delal je to, kar je bilo pravilno v Gospodovih očeh. Kljub temu visoki kraji niso bili odstranjeni, kajti ljudstvo je na visokih krajih še vedno darovalo in zažigalo kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Józafat je z Izraelovim kraljem sklenil mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Torej preostala izmed Józafatovih dejanj in njegova moč, ki jo je pokazal in kako se je bojeval, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Preostanek posvečenih vlačugarjev, ki so preostali v dneh njegovega očeta Asája, je izgnal iz dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Potem ni bilo kralja v Edómu. Namestnik je bil kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Józafat je naredil taršíške ladje, da gredo do Ofírja po zlato. Toda niso odšli, kajti ladje so se razbile pri Ecjón Geberju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Potem je Ahábov sin Ahazjá Józafatu rekel: »Naj moji služabniki gredo s tvojimi služabniki na ladje.« Józafat pa ni hotel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Józafat je zaspal s svojimi očeti in je bil pokopan s svojimi očeti v mestu svojega očeta Davida. Namesto njega je zakraljeval njegov sin Jehorám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Ahábov sin Ahazjá je začel kraljevati nad Izraelom v Samariji v sedemnajstem letu Judovega kralja Józafata in nad Izraelom je kraljeval dve leti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Počel je zlo v Gospodovih očeh in hodil po poti svojega očeta, po poti svoje matere in po poti Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'kajti služil je Báalu, ga oboževal in do jeze dražil Gospoda, Izraelovega Boga, glede na vse, kar je počel njegov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Potem se je, po Ahábovi smrti, Moáb uprl zoper Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ahazjá je padel dol skozi mrežo v svoji gornji sobi, ki je bila v Samariji in je bil bolan. Poslal je poslance in jim rekel: »Pojdite, poizvedite od Báal Zebúba, boga v Ekrónu, ali si bom opomogel od te bolezni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Toda Gospodov angel je rekel Tišbéjcu Eliju: »Vstani, pojdi gor, da srečaš poslance samarijskega kralja in jim reci: › Mar ni zato, ker ni Boga v Izraelu, da greste povpraševat ekrónskega boga Báal Zebúba?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Zdaj torej tako govori Gospod: ›Ne boš prišel dol iz svoje postelje, na katero si zlezel, temveč boš zagotovo umrl.‹« In Elija je odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Ko so se poslanci obrnili nazaj k njemu, jim je rekel: »Zakaj ste se torej obrnili nazaj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Rekli so mu: »Vzdignil se je mož, da nas sreča in nam rekel: ›Pojdite, ponovno se obrnite h kralju, ki vas je poslal in mu recite: ›Tako govori Gospod: › Mar ni zato, ker ni Boga v Izraelu, da pošiljaš povpraševat ekrónskega boga Báal Zebúba?‹ Zato ne boš prišel dol iz svoje postelje, na katero si zlezel, temveč boš zagotovo umrl.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Rekel jim je: »Kakšne vrste mož je bil ta, ki se je vzdignil, da vas sreča in vam je povedal te besede?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Odgovorili so mu: » Bil je kosmat človek in z usnjenim pasom opasan okoli ledij.« Rekel je: »To je Tišbéjec Elija.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Potem je kralj poslal k njemu petdesetnika z njegovimi petdesetimi. Ta je odšel gor k njemu, in glej, sedel je na vrhu hriba. Nagovoril ga je: »Božji mož, kralj je rekel: ›Pridi dol.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elija je odgovoril in petdesetniku rekel: »Če sem Božji mož, potem naj dol z neba pride ogenj in použije tebe in tvojih petdeset.« Dol z neba je prišel ogenj in použil njega in njegovih petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Ponovno je k njemu poslal drugega petdesetnika z njegovimi petdesetimi. Ta je odgovoril in mu rekel: »Oh Božji mož, tako je rekel kralj: ›Pridi hitro dol.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elija je odgovoril in jim rekel: »Če sem Božji mož, naj dol z neba pride ogenj in použije tebe in tvojih petdeset.« In ogenj od Boga je prišel z neba in použil njega in njegovih petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Ponovno je poslal tretjega petdesetnika z njegovimi petdesetimi. Tretji petdesetnik je odšel gor, prišel in pred Elijem padel na kolena, ga rotil in mu rekel: »Oh Božji mož, prosim te, naj bodo moje življenje in življenja teh petdesetih tvojih služabnikov dragocena v tvojih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Glej, prišel je ogenj dol z neba in sežgal dva poveljnika prejšnjih petdesetih z njunimi petdesetimi. Zatorej naj bo moje življenje sedaj dragoceno v tvojih očeh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Gospodov angel je rekel Eliju: »Z njim pojdi dol. Ne boj se ga.« In vstal je in z njim odšel dol h kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Rekel mu je: »Tako govori Gospod: ›Ker kakor si poslal poslance, da poizvejo od ekrónskega boga Báal Zebúba, mar ni to zato, ker ni Boga v Izraelu, da bi povprašal po njegovi besedi? Zato ne boš prišel dol iz postelje, na katero si zlezel, temveč boš zagotovo umrl.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Tako je umrl glede na Gospodovo besedo, ki jo je Elija govoril. Namesto njega je zakraljeval Jehorám, v drugem letu Józafatovega sina Jehoráma, Judovega kralja, ker ni imel sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Torej preostala izmed Ahazjájevih dejanj, ki jih je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Pripetilo se je, ko je Gospod hotel Elija z vrtinčastim vetrom vzeti gor v nebo, da je Elija z Elizejem odšel iz Gilgála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Elija je rekel Elizeju: »Ostani tukaj, prosim te, kajti Gospod me je poslal v Betel.« Elizej pa mu je rekel: » Kakor Gospod živi in kakor živi tvoja duša, te ne bom zapustil.« Tako sta odšla dol do Betela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Sinovi prerokov, ki so bili pri Betelu, so prišli naprej k Elizeju in mu rekli: »Ali veš, da bo Gospod danes odvzel tvojega gospodarja iznad tvoje glave?« Ta je rekel: »Da, vem to; molčite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elija mu je rekel: »Elizej, ostani tukaj, prosim te, kajti Gospod me je poslal v Jeriho.« Ta pa je rekel: » Kakor Gospod živi in kakor živi tvoja duša, te ne bom zapustil.« Tako sta prišla do Jerihe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Sinovi prerokov, ki so bili pri Jerihi, so prišli k Elizeju in mu rekli: »Ali veš, da bo Gospod danes odvzel tvojega gospodarja iznad tvoje glave?« Ta pa je odgovoril: »Da, vem to; molčite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Elija mu je rekel: »Ostani, prosim te, tukaj, kajti Gospod me je poslal k Jordanu.« Ta pa je rekel: » Kakor Gospod živi in kakor živi tvoja duša, te ne bom zapustil.« In oba sta šla naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Petdeset mož izmed sinov prerokov je šlo in stali so, da gledajo od daleč, onadva pa sta stala ob Jordanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Elija je vzel svoje ogrinjalo, ga zvil skupaj, udaril vode in razdelile so se sèm ter tja, tako da sta oba šla preko po suhih tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Pripetilo se je, ko sta šla čez, da je Elija rekel Elizeju: »Prosi, kaj naj storim zate, preden bom vzet od tebe.« Elizej je rekel: »Prosim te, naj bo nad menoj dvojen delež tvojega duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Rekel je: »Prosil si težko stvar. Vendar če me boš videl, ko bom vzet od tebe, se ti bo zgodilo, toda če ne, ne bo tako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Pripetilo se je, ko sta še vedno šla naprej in se pogovarjala, da se je, glej, tam prikazal ognjen bojni voz in ognjeni konji in ju ločili narazen in Elija se je z vrtinčastim vetrom dvignil v nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elizej je to videl in klical: »Moj oče, moj oče, Izraelov bojni voz in njegovi konjeniki.« In nič več ga ni videl. Zgrabil je svoja lastna oblačila in jih pretrgal na dva kosa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Pobral je tudi Elijevo ogrinjalo, ki je padlo iz njega, odšel nazaj in obstal pri bregu Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Vzel je Elijevo ogrinjalo, ki je padlo iz njega, udaril vode in rekel: »Kje je Gospod, Elijev Bog?« Ko je tudi on udaril vode, so se razdelile sèm ter tja in Elizej je šel preko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Ko so ga sinovi prerokov, ki so opazovali pri Jerihi, zagledali, so rekli: »Elijev duh počiva na Elizeju.« Prišli so, da ga srečajo in se do tal priklonili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Rekli so mu: »Glej torej, s tvojimi služabniki bo petdeset močnih mož. Naj odidejo, prosimo te in poiščejo tvojega gospodarja, da ga ni morda gor vzel Gospodov Duh in ga vrgel na kako goro ali v kako dolino.« Rekel je: »Ne pošiljajte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ko so mu prigovarjali, dokler ni bil osramočen, je rekel: »Pošljite.« Zato so poslali petdeset mož in iskali tri dni, toda niso ga našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Ko so ponovno prišli k njemu (kajti mudil se je pri Jerihi), jim je rekel: »Ali vam nisem rekel: ›Ne pojdite?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Ljudje iz mesta so Elizeju rekli: »Glej, prosim te, lega tega mesta je prijetna, kakor vidi moj gospod, toda voda je slaba in tla jalova.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Rekel je: »Prinesite mi nov vrč in vanj dajte sol.« In prinesli so ga k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Šel je naprej, k izviru vodá in vanj vrgel sol ter rekel: »Tako govori Gospod: ›Ozdravil sem te vode, od tod ne bo nič več smrti ali jalove dežele.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Tako so bile vode ozdravljene do tega dne, glede na Elizejevo besedo, ki jo je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Od tam je odšel gor k Betelu in ko je šel gor po poti, so prišli iz mesta majhni otroci, ga zasmehovali in mu rekli: »Pojdi gor, plešec; pojdi gor, plešec.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Ta se je obrnil nazaj, pogledal nanje in jih preklel v Gospodovem imenu. In iz gozda sta prišli dve medvedki ter izmed njih raztrgali dvainštirideset otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Od tam je odšel na goro Karmel in od tam se je vrnil v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Torej Ahábov sin Jehorám je začel kraljevati nad Izraelom, v Samariji, v osemnajstem letu Judovega kralja Józafata in kraljeval je dvanajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Počel je zlo v Gospodovih očeh, toda ne kakor njegov oče in kakor njegova mati, kajti odstranil je Báalovo podobo, ki jo je naredil njegov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Kljub temu se je trdno držal grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši; ni odšel od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Moábski kralj Meša je bil lastnik ovc in je Izraelovemu kralju dajal sto tisoč jagnjet in sto tisoč ovnov, [skupaj] z volno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Toda pripetilo se je, ko je bil Aháb mrtev, da se je moábski kralj uprl zoper Izraelovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Kralj Jehorám je istočasno odšel iz Samarije in preštel ves Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Odšel je in poslal k Judovemu kralju Józafatu, rekoč: »Moábski kralj se je uprl zoper mene. Ali hočeš iti z menoj v bitko zoper Moáb?« Rekel je: »Šel bom gor. Jaz sem, kakor si ti, moje ljudstvo je kakor tvoje ljudstvo in moji konji kakor tvoji konji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Rekel je: »Po kateri poti bomo šli gor?« Odgovoril je: »Po poti skozi edómsko divjino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Tako so Izraelov kralj, Judov kralj in edómski kralj odšli in zaokrožili sedemdnevno potovanje in tam ni bilo vode za vojsko in živino, ki jim je sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Kralj Izraela je rekel: »Gorje, da je te tri kralje Gospod poklical skupaj, da jih izroči v roko Moába!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Toda Józafat je rekel: » Mar ni tukaj Gospodovega preroka, da bi po njem lahko poizvedel od Gospoda?« Eden izmed služabnikov Izraelovega kralja je odgovoril in rekel: »Tukaj je Šafátov sin Elizej, ki je izlival vodo na Elijeve roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Józafat je rekel: »Z njim je Gospodova beseda.« Tako so Izraelov kralj, Józafat in edómski kralj odšli dol k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Elizej je rekel Izraelovemu kralju: »Kaj imam s teboj? Spravi se k prerokom svojega očeta in k prerokom svoje matere.« Izraelov kralj pa mu je rekel: »Ne, kajti Gospod je te tri kralje sklical skupaj, da jih izroči v roko Moába.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elizej je rekel: » Kakor živi Gospod nad bojevniki, pred katerim stojim, zagotovo, če se ne bi oziral na prisotnost Judovega kralja Józafata, ne bi pogledal proti tebi niti te ne bi videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Toda sedaj mi privedi glasbenika, ki igra na strune.« In pripetilo se je, ko je glasbenik igral, da je nadenj prišla Gospodova roka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Rekel je: »Tako govori Gospod: ›To dolino naredite polno jarkov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Kajti tako govori Gospod: ›Ne boste videli vetra niti ne boste videli dežja, vendar bo ta dolina napolnjena z vodo, da boste lahko pili, tako vi, vaše govedo in vaše živali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'To pa je le majhna stvar v Gospodovih očeh. Tudi Moábce bo izročil v vašo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Udarili boste vsako utrjeno mesto in vsako izbrano mesto in posekali vsako dobro drevo in zamašili vse vodnjake in vsak dober kraj dežele oškodovali s kamni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Pripetilo se je zjutraj, ko je bila darovana jedilna daritev, glej, da je prišla voda po poti iz Edóma in dežela je bila napolnjena z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Ko so vsi Moábci slišali, da so prišli gor kralji, da se bojujejo zoper njih, so zbrali vse, ki so si bili zmožni nadeti bojno opremo in starejše in so se razpostavili na meji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Vstali so zgodaj zjutraj in sonce je sijalo na vodo in Moábci so vodo na drugi strani videli tako rdečo kakor kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Rekli so: »To je kri. Kralji so zagotovo umorjeni in so udarili drug drugega. Sedaj torej Moáb, k plenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Ko pa so prišli k taboru Izraelcev, so se Izraelci dvignili in udarili Moábce, tako da so le-ti pred njimi pobegnili. Toda šli so naprej in pobijali Moábce, celo v njihovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Podirali so mesta in na vsak dober kos dežele je vsak mož vrgel svoj kamen in napolnili so jo in zamašili so vse vodnjake in podrli vsa dobra drevesa, samo v Kir Heresu so pustili njegovo kamenje, vendar so okrog njega šli pračarji in ga udarili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Ko je moábski kralj videl, da je bila bitka zanj prehuda, je s seboj vzel sedemsto mož, ki so izdirali meče, da se prebijejo k edómskemu kralju. Toda niso mogli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Potem je vzel svojega najstarejšega sina, ki naj bi zakraljeval namesto njega in ga na obzidju daroval v žgalno daritev. In tam je bilo veliko ogorčenje zoper Izrael in odšli so od njega in se vrnili k svoji lastni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Torej tam je neka ženska, izmed žena preroških sinov, zaklicala k Elizeju, rekoč: »Tvoj služabnik, moj soprog, je mrtev, in ti veš, da se je tvoj služabnik bal Gospoda in prišel je upnik, da bi si moja dva sinova k sebi vzel za sužnja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elizej ji je rekel: »Kaj naj storim zate? Povej mi, kaj imaš v hiši?« Rekla je: »Tvoja pomočnica nima v hiši ničesar razen lonca olja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Potem je rekel: »Pojdi, izposodi si posode od vseh svojih sosed, prazne posode. Ne izposodi si jih malo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Ko vstopiš noter, boš za seboj in za svojima sinovoma zaprla vrata in izlivala v vse tiste posode in tisto, ki je polna, boš postavila na stran.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Tako je odšla od njega in za seboj in za svojima sinovoma, ki sta k njej prinesla posode, zaprla vrata in ona je izlivala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Pripetilo se je, ko so bile posode polne, da je svojemu sinu rekla: »Še mi prinesi posodo.« Rekel ji je: »Nobene posode ni več.« In olje se je ustavilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Potem je prišla in povedala Božjemu možu. Rekel je: »Pojdi, prodaj olje in poplačaj svoj dolg in od preostanka živite ti in tvoja otroka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Zgodilo se je na nek dan, da je Elizej odšel v Šuném, kjer je bila plemenita ženska; in ta ga je primorala, da jé kruh. In to je bilo tako, da tako pogosto, kot je šel mimo, se je obrnil tja, da bi jedel kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Svojemu soprogu je rekla: »Glej torej, zaznavam, da je to sveti Božji mož, ki nenehno hodi mimo nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Narediva majhno sobo, prosim te, na zidu in tam zanj postavimo posteljo, mizo, stolček in svečnik. In zgodilo se bo, ko prihaja k nam, da se bo obrnil tja noter.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Zgodilo se je na nek dan, da je prišel tja, se obrnil v sobo in se tam ulegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Svojemu služabniku Gehazíju je rekel: »Pokliči to Šunémko.« Ko jo je ta poklical, je obstala pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Rekel mu je: »Sedaj ji povej: ›Glej, hitela si za naju z vso to skrbjo. Kaj naj bo storjeno zate? Ali naj zate govorim kralju ali poveljniku vojske?‹« Odgovorila je: »Prebivam med svojim lastnim ljudstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Rekel je: »Kaj naj bo potem storjeno zanjo?« Gehazí je odgovoril: »Resnično, ona nima otroka in njen soprog je star.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Rekel je: »Pokliči jo.« Ko jo je poklical, je obstala med vrati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Rekel je: »Okoli tega obdobja, glede na čas življenja, boš objemala sina.« Rekla je: »Ne, moj gospod, Božji mož, ne laži svoji pomočnici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Ženska je spočela in rodila sina v tistem obdobju, ki ji ga je Elizej povedal, glede na čas življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Ko je otrok postal večji, se je nekega dne zgodilo, da je odšel ven k svojemu očetu, k žanjcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Svojemu očetu je rekel: »Moja glava, moja glava.« In ta je rekel mladeniču: »Odnesi ga k njegovi materi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Ko ga je ta vzel in ga privedel k njegovi materi, je do opoldneva sedel na njenih kolenih, potem pa je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Vzdignila se je, ga položila na posteljo Božjega moža, zaprla vrata za njim in odšla ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Poklicala je k svojemu soprogu in rekla: »Pošlji mi, prosim te, enega izmed mladeničev in enega izmed oslov, da lahko stečem k Božjemu možu in ponovno pridem nazaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Rekel je: »Čemu hočeš iti k njemu danes? Ni niti mlaj niti šabat.« Rekla je: » To bo dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Potem je osedlala osla in svojemu mladeniču rekla: »Požêni in pojdi naprej. Svojega jahanja ne upočasnjuj zaradi mene, razen če ti ne zapovem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Tako je odšla in prišla k Božjemu možu na goro Karmel. Pripetilo se je, ko jo je Božji mož od daleč zagledal, da je svojemu služabniku Gehazíju rekel: »Glej, tam je ta Šunémka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Steci sedaj, prosim te, da jo srečaš in ji reci: › Ali je dobro s teboj? Ali je dobro s tvojim soprogom? Ali je dobro z otrokom?‹« Odgovorila je: »Dobro je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Ko pa je prišla k Božjemu možu na hrib, se je oklenila njegovih stopal. Toda Gehazí se je približal, da jo pahne proč. Božji mož pa je rekel: »Pusti jo; kajti njena duša je zagrenjena znotraj nje in Gospod je to skril pred menoj in mi ni povedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Potem je rekla: »Ali sem si jaz želela sina od svojega gospoda?« Ali nisem rekla: »Ne zavajaj me?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Potem je rekel Gehazíju: »Opaši svoja ledja in v svojo roko vzemi mojo palico in pojdi svojo pot. Če srečaš kateregakoli človeka, ga ne pozdravi in če kdorkoli pozdravi tebe, mu ravno tako ne odgovori, in mojo palico položi na otrokov obraz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Otrokova mati je rekla: » Kakor Gospod živi in kakor tvoja duša živi, te ne bom zapustila.« Vstal je in ji sledil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazí je šel pred njima in palico položil na otrokov obraz, toda ni bilo niti glasu niti uslišanja. Zatorej je ponovno odšel, da ga sreča in mu povedal, rekoč: »Otrok se ni prebudil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Ko je Elizej prišel v hišo, glej, je bil otrok mrtev in položen na njegovo posteljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Vstopil je torej in zaprl vrata za njima ter molil h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Povzpel se je in legel na otroka ter svoja usta položil na njegova usta in svoje oči na njegove oči in svoje roke na njegove roke. Raztegnil se je nad otrokom in otrokovo meso se je ogrelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Potem se je vrnil in po hiši hodil sem ter tja, se povzpel in sebe raztegnil nad njim. Otrok je sedemkrat kihnil in otrok je odprl svoje oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Poklical je Gehazíja in rekel: »Pokliči to Šunémko.« Tako jo je poklical. Ko je vstopila k njemu, je rekel: »Vzemi svojega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Potem je vstopila, padla k njegovim stopalom, se priklonila do tal, vzela svojega sina in odšla ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elizej je ponovno prišel v Gilgál. Tam pa je bilo v deželi pomanjkanje. Sinovi prerokov so sedeli pred njim. Svojemu služabniku je rekel: »Pristavi velik lonec in za sinove prerokov zavri juho.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Nekdo je odšel na polje, da nabere zelišča in našel divjo trto in od nje nabral polno naročje divjih buč in prišel in jih zrezal v lonec juhe, kajti niso jih poznali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Tako so nalili, da bi možje jedli. Pripetilo pa se je, ko so jedli juho, da so zavpili in rekli: »Oh ti Božji mož, smrt je v loncu.« In tega niso mogli jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Toda rekel je: »Torej prinesite moko.« Vrgel jo je v lonec in rekel: »Nalij za ljudstvo, da bodo lahko jedli.« In v loncu ni bilo nič škodljivega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Prišel je mož iz Báal Šalíša in Božjemu možu prinesel kruh od prvih sadov, dvajset ječmenovih hlebov in polno žitno klasje v luščinah. Rekel je: »Dajte ljudstvu, da bodo lahko jedli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Njegov strežnik pa je rekel: »Kaj, mar naj bi to postavil pred sto mož?« Ponovno je rekel: »Daj ljudstvu, da bodo lahko jedli, kajti tako govori Gospod: › Od tega bodo jedli in še bo ostalo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Tako je to postavil prednje in so jedli in od tega pustili, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Torej Naamán, poveljnik vojske sirskega kralja, je bil plemenit mož pri svojem gospodarju in častitljiv, ker je po njem Gospod dal Siriji osvoboditev. Bil je tudi mogočen mož v hrabrosti, toda bil je gobavec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Sirci so hodili ven po skupinah in iz izraelske dežele odvedli ujetnico, malo deklico; in ta je čakala na Naamánovo ženo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Svoji gospodarici je rekla: »Da bi Bog dal, da bi bil moj gospodar s prerokom, ki je v Samariji! Kajti on bi odvzel njegovo gobavost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Nekdo je vstopil in to povedal svojemu gospodarju, rekoč: »Tako in tako je govorila služabnica, ki je iz Izraelove dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Kralj Sirije je rekel: »Odpravi se, pojdi, jaz pa bom poslal pismo Izraelovemu kralju.« Odpotoval je in s seboj vzel deset talentov srebra, šest tisoč koščkov zlata in deset zamenjav oblačil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Izraelovemu kralju je prinesel pismo, rekoč: »Sedaj, ko je to pismo prišlo k tebi, glej, sem z njim poslal k tebi svojega služabnika Naamána, da mu lahko odvzameš njegovo gobavost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Pripetilo se je, ko je Izraelov kralj prebral pismo, da je pretrgal svoja oblačila in rekel: » Sem jaz Bog, da ubijem in oživim, da je ta človek poslal k meni, da možu odvzamem njegovo gobavost? Zatorej preudarite, prosim vas in glejte, kako zoper mene išče spor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Bilo je tako, ko je Božji mož Elizej slišal, da je Izraelov kralj pretrgal svoja oblačila, da je poslal h kralju, rekoč: »Zakaj si pretrgal svoja oblačila? Naj torej pride k meni in vedel bo, da je v Izraelu prerok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Tako je Naamán prišel s svojimi konji in s svojim bojnim vozom in obstal pri vratih Elizejeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elizej pa je k njemu poslal poslanca, rekoč: »Pojdi in se sedemkrat umij v Jordanu in tvoje meso bo ponovno prišlo k tebi in boš čist.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Toda Naaman je bil ogorčen in odšel ter rekel: »Glej, mislil sem: ›Zagotovo bo prišel ven k meni, obstal in klical k imenu Gospoda, svojega Boga in s svojo roko udaril nad mestom in odvzel gobavost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Mar nista Abána in Parpár, reki v Damasku, boljši kakor vse Izraelove vode? Ali se ne bi mogel umiti v njima in bi bil čist?« Tako se je obrnil in v besu odšel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Njegovi služabniki so prišli blizu, mu spregovorili in rekli: »Moj oče, če bi ti prerok naročil, da storiš neko veliko stvar, ali ne bi ti tega storil? Koliko bolj potem, ko ti je rekel: ›Umij se in bodi čist?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Potem je odšel dol, se sedemkrat potopil v Jordanu, glede na izrek Božjega moža in njegovo meso je ponovno prišlo kakor meso majhnega otroka in bil je čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Vrnil se je k Božjemu možu, on in vsa njegova skupina in prišel ter obstal pred njim in rekel: »Glej, sedaj vem, da ni Boga na vsej zemlji, razen v Izraelu. Sedaj torej, prosim te, vzemi blagoslov od svojega služabnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Toda on je rekel: » Kakor živi Gospod, pred katerim stojim, ne bom ničesar sprejel.« Silil ga je, da to vzame; toda zavrnil je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Naamán je rekel: »Ali ne bo, prosim te, dano tvojemu služabniku, tovor prsti za dve muli? Kajti tvoj služabnik odslej ne bo daroval niti žgalne daritve niti klavne daritve drugim bogovom, razen Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'V tej stvari pa naj Gospod odpusti svojemu služabniku, da ko gre moj gospodar v Rimónovo hišo, da tam obožuje in se naslanja na mojo roko in se priklonim v Rimónovi hiši. Ko se priklonim v Rimónovi hiši, naj Gospod v tej stvari odpusti svojemu služabniku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Rekel mu je: »Pojdi v miru.« Tako je odšel od njega del poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Toda Gehazí, služabnik Božjega moža Elizeja, je rekel: »Glej, moj gospodar je prizanesel temu Sircu Naamánu v tem, da iz njegovih rok ni sprejel tega, kar je prinesel. Toda kakor živi Gospod bom stekel za njim in od njega nekaj vzel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Tako je Gehazí sledil Naamánu. Ko ga je Naamán videl teči za seboj, je upočasnil bojni voz, da ga sreča in rekel: » Ali je vse dobro?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Ta je rekel: »Vse je dobro. Moj gospodar me je poslal, rekoč: ›Glej, celo sedaj sta prišla k meni z gore Efrájim dva mladeniča izmed preroških sinov. Daj jima, prosim te, talent srebra in dve menjavi oblačil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naamán je rekel: »Bodi zadovoljen, vzemi dva talenta.« Silil ga je in dva talenta srebra povezal v dve vreči, z dvema menjavama oblačil in jih položil na dva izmed svojih služabnikov in nosila sta jih pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Ko je prišel k stolpu, jih je vzel iz njune roke in jih shranil v hiši, moža pa je pustil oditi in sta odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Toda sam je vstopil in obstal pred svojim gospodarjem. Elizej mu je rekel: »Od kod prihajaš, Gehazí?« Rekel je: »Tvoj služabnik ni šel nikamor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Rekel mu je: »Mar ni moje srce odšlo s teboj, ko se je mož ponovno obrnil nazaj iz svojega bojnega voza, da te sreča? Mar je čas, da prejemaš denar, da prejemaš obleke, oljčne nasade, vinograde, ovce, vole, služabnike in dekle?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Zato se bo Naamánova gobavost trdno prijela tebe in tvojega semena na veke.« In izpred njegove prisotnosti je odšel gobav, tako bel kakor sneg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Sinovi prerokov so Elizeju rekli: »Glej torej, kraj, kjer prebivamo s teboj, je za nas preveč utesnjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Naj gremo, prosimo te, k Jordanu in si od tam vsak mož vzame bruno in si tam zgradimo kraj, kjer bomo lahko prebivali.« Odgovoril je: »Pojdite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Nekdo je rekel: »Bodi zadovoljen, prosim te in pojdi s svojimi služabniki.« Odgovoril je: »Šel bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Tako je šel z njimi. In ko so prišli k Jordanu, so sekali les.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Toda ko je nekdo podiral drevo, je glava sekire padla v vodo in zavpil je ter rekel: »Ojoj, gospod! Kajti bila je izposojena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Božji mož je rekel: »Kam je padla?« Ta mu je pokazal kraj. In odsekal je palico ter jo vrgel tja in železo je zaplavalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Zato je rekel: »Vzemi to k sebi.« In iztegnil je svojo roko in jo vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Potem se je sirski kralj vojskoval zoper Izraela in se posvetoval s svojimi služabniki, rekoč: »Na tem in tem kraju bo moj tabor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Božji mož pa je k Izraelovemu kralju poslal, rekoč: »Pazi, da ne greš mimo tega kraja, kajti tja dol so prišli Sirci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Izraelov kralj je poslal h kraju, o katerem mu je povedal Božji mož, ga o njem posvaril in tam se je rešil, ne samo enkrat ali dvakrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Zato je bilo srce sirskega kralja zaradi te stvari boleče vznemirjeno. Poklical je svoje služabnike in jim rekel: »Ali mi ne boste pokazali, kdo izmed nas je za Izraelovega kralja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Nekdo izmed njegovih služabnikov je rekel: »Nihče, moj gospod, oh kralj, temveč prerok Elizej, ki je v Izraelu, govori Izraelovemu kralju besede, ki jih ti govoriš v svoji spalnici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Rekel je: »Pojdi in poglej, kje je, da bom lahko poslal in ga zgrabil.« Bilo mu je povedano, rekoč: »Glej, on je v Dotánu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Zato je tja poslal konje, bojne vozove in veliko vojsko. Prišli so ponoči in obkolili mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Ko je služabnik Božjega moža zgodaj vstal in odšel naprej, glej, vojska je obkolila mesto, tako s konji kakor bojnimi vozovi. Njegov služabnik mu je rekel: »Ojoj, moj gospod! Kaj bomo storili?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Odgovoril je: »Ne boj se, kajti tistih, ki so z nami, je več kakor tistih, ki so z njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Elizej je molil in rekel: » Gospod, prosim te, odpri njegove oči, da bo lahko videl.« Gospod je odprl oči mladeniča in ta je videl in glej, gora je bila polna konj in ognjenih bojnih voz naokoli Elizeja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Ko so prišli dol k njemu, je Elizej molil h Gospodu in rekel: »Udari to ljudstvo, prosim te, s slepoto.« In udaril jih je s slepoto glede na Elizejevo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elizej jim je rekel: »To ni pot niti ni to mesto. Sledite mi in privedel vas bom k človeku, ki ga iščete.« Toda odvedel jih je v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Ko so prišli v Samarijo, se je pripetilo, da je Elizej rekel: » Gospod, odpri oči teh mož, da bodo lahko videli.« In Gospod je odprl njihove oči in so videli in glej, bili so sredi Samarije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Ko jih je Izraelov kralj videl, je rekel Elizeju: »Moj oče, ali naj jih udarim? Ali naj jih udarim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Ta pa je odgovoril: »Ne boš jih udaril. Mar bi udaril tiste, ki si jih odvedel ujete s svojim mečem in s svojim lokom? Prednje postavi kruh in vodo, da bodo lahko jedli in pili in šli k svojemu gospodarju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Zanje je pripravil veliko preskrbo in ko so pojedli in popili, jih je poslal proč in odšli so k svojemu gospodarju. Tako čete iz Sirije niso nič več prihajale v deželo Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Po tem se je pripetilo, da je sirski kralj Ben Hadád zbral vso svojo vojsko, odšel gor in oblegal Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, '§ Tam v Samariji pa je bila velika lakota. Glej, oblegali so jo, dokler ni bila oslovska glava prodana za osemdeset koščkov srebra in četrtinka kaba golobjega iztrebka za pet koščkov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Medtem ko se je Izraelov kralj sprehajal po obzidju, je k njemu zavpila ženska, rekoč: »Pomagaj, moj gospod, oh kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Ta ji je rekel: »Če ti Gospod ne pomaga, od kod naj ti jaz pomagam? Iz skednja ali iz vinske stiskalnice?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Kralj ji je rekel: »Kaj te pesti?« Odgovorila je: »Ta ženska mi je rekla: ›Daj svojega sina, da ga bomo lahko danes pojedli, mojega sina pa bomo pojedli jutri.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Tako smo skuhali mojega sina in ga pojedli. Naslednji dan pa sem ji rekla: »Daj svojega sina, da ga bomo lahko pojedli.« Ona pa je svojega sina skrila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Pripetilo se je, ko je kralj slišal besede ženske, da je pretrgal svoja oblačila. Prek obzidja je šel mimo in ljudstvo je gledalo in glej, na svojem telesu je imel spodaj vrečevino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Potem je rekel: »Bog naj mi stori tako in še več, če bo glava Šafátovega sina Elizeja, ta dan obstala na njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Toda Elizej je sedel v svoji hiši in starešine so sedeli z njim. In kralj je izpred sebe poslal moža, toda malo preden je poslanec prišel k njemu, je starešinam rekel: »Ali vidite, kako je ta sin morilca poslal, da mi vzame mojo glavo? Poglejte, ko pride poslanec, zaprite vrata in ga trdno držite pri vratih. Mar ni zvok stopal njegovega gospodarja za njim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, '§ Medtem ko je še govoril z njimi, glej, je dol k njemu prišel poslanec in rekel: »Glej to zlo je od Gospoda. Zakaj bi še čakal na Gospoda?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Potem je Elizej rekel: »Poslušaj besedo od Gospoda: ›Tako govori Gospod: ›Jutri okoli tega časa bo v velikih vratih Samarije mera fine moke prodajana za šekel in dve meri ječmena za šekel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Potem je gospod, na čigar roko se je kralj naslanjal, odgovoril Božjemu možu in rekel: »Glej, če bi Gospod naredil okna na nebu, mar bi se to lahko zgodilo?« On pa je rekel: »Glej, to boš videl s svojimi lastnimi očmi, toda od tega ne boš jedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Ob vhodu velikih vrat so bili štirje gobavci in drug drugemu so rekli: »Čemu tukaj sedimo, dokler ne umremo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Če rečemo: ›Vstopili bomo v mesto, potem je lakota v mestu in bomo tam umrli. Če pa mirno sedimo tukaj, bomo tudi umrli. Sedaj torej pridite in padimo v vojsko Sircev. Če nas rešijo žive, bomo živeli, če pa nas ubijejo, bomo samo umrli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'V poltemi so se dvignili, da gredo v tabor Sircev. Ko so prišli k najbolj oddaljenemu delu tabora Sircev, glej, tam ni bilo nobenega moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Kajti Gospod je vojski Sircev storil, da slišijo hrup bojnih vozov in hrup konjev, celó hrup velike vojske in drug drugemu so rekli: »Glejte, Izraelov kralj je zoper nas najel kralje Hetejcev in kralje Egipčanov, da pridejo nad nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Zato so vstali in v poltemi zbežali in pustili svoje šotore, svoje konje in svoje osle, celo tabor, kakor je bil in pobegnili za svoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Ko so ti gobavci prišli k najbolj oddaljenemu delu tabora, so odšli v en šotor in jedli, pili in od tam odnesli srebro, zlato in oblačilo ter odšli in to skrili in ponovno prišli ter vstopili v drug šotor in tudi od tam odnesli in odšli ter to skrili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Potem so drug drugemu rekli: »Ne delamo dobro. Ta dan je dan dobrih novic, mi pa molčimo. Če nadaljujemo do jutranje svetlobe, bo nad nas prišla neka vragolija. Sedaj torej pridite, da bomo lahko šli in povedali kraljevi družini.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Tako so prišli in zaklicali vratarju mesta. Povedali so jim, rekoč: »Prišli smo k taboru Sircev in glejte, tam ni bilo nobenega moža niti človeškega glasu, temveč privezani konji, privezani osli in šotori, kakor so bili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Poklical je vratarje in to so povedali znotraj kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Kralj je ponoči vstal in svojim služabnikom rekel: »Sedaj vam bom pokazal, kaj so nam storili Sirci. Vedo, da smo lačni, zato so odšli iz tabora, da se skrijejo na polju, rekoč: ›Ko pridejo iz mesta, jih bomo žive ujeli in pridemo v mesto.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Eden izmed njegovih služabnikov je odgovoril in rekel: »Naj nekateri vzamejo, prosim te, pet izmed konjev, ki so še, ki so ostali v mestu (glej, oni so kakor vsa Izraelova množica, ki je ostala v njem. Glej, pravim, oni so celo kakor vsa množica Izraelcev, ki so použiti) in pošljimo ter poglejmo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Vzeli so torej dva bojna voza [s] konji in kralj je poslal za sirsko vojsko, rekoč: »Pojdite in poglejte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Za njimi so odšli do Jordana in glej, vsa pot je bila polna oblek in posod, ki so jih Sirci v svoji naglici odvrgli. Poslanci so se vrnili in povedali kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Ljudstvo je odšlo ven in oplenilo šotore Sircev. Tako je bila mera fine moke prodajana za šekel in dve meri ječmena za šekel, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kralj je določil gospoda, na čigar roko se je naslanjal, da je zadolžen za velika vrata, ljudstvo pa ga je v velikih vratih pomendralo in je umrl, kakor je rekel Božji mož, ki je govoril, ko je dol k njemu prišel kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Pripetilo se je, kakor je Božji mož govoril kralju, rekoč: »Dve meri ječmena za šekel in mera fine moke za šekel bosta jutri okrog tega časa v velikih vratih Samarije.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Tisti gospod je Božjemu možu odgovoril in rekel: »Sedaj glej, če bi Gospod naredil okna na nebu, mar bi se to lahko zgodilo?« In ta je rekel: »Glej, to boš videl s svojimi lastnimi očmi, toda od tega ne boš jedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'In tako ga je to doletelo, kajti ljudstvo ga je pomendralo v velikih vratih in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Potem je Elizej spregovoril ženski, katerega sina je obudil v življenje, rekoč: »Vstani in pojdi, ti in tvoja družina in začasno prebivaj kjerkoli lahko prebivaš, kajti Gospod je poklical lakoto in ta bo tudi prišla nad deželo [za] sedem let.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Ženska je vstala in storila po besedi Božjega moža in šla s svojo družino in sedem let začasno prebivala v filistejski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Ob koncu sedmih let se je pripetilo, da se je ženska vrnila iz filistejske dežele in šla naprej, da kliče h kralju za svojo hišo in za svoje polje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Kralj je govoril z Gehazíjem, služabnikom Božjega moža, rekoč: »Povej mi, prosim te, vse velike stvari, ki jih je storil Elizej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Pripetilo se je, medtem ko je kralju pripovedoval, kako je truplo oživil v življenje, glej, da je ženska, čigar sina je oživil v življenje, klicala h kralju za svojo hišo in svoje polje. Gehazí je rekel: »Moj gospod, oh kralj, to je ženska in to je njen sin, ki ga je Elizej oživil v življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Ko je kralj žensko vprašal, mu je povedala. Tako ji je kralj določil nekega častnika, rekoč: »Povrni vse, kar je bilo njeno in vse sadove polja, od dneva, ko je zapustila deželo, celo do sedaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elizej je prišel v Damask in sirski kralj Ben Hadád je bil bolan in povedano mu je bilo, rekoč: »Božji mož je prišel sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Kralj je rekel Hazaélu: »V svojo roko vzemi darilo in pojdi, srečaj Božjega moža in pri njem poizvedi od Gospoda, rekoč: ›Ali bom okreval od te bolezni?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Tako je Hazaél odšel, da ga sreča in s seboj vzel darilo, celo vsako dobro stvar iz Damaska, breme za štirideset kamel in prišel, obstal pred njim ter rekel: »Tvoj sin, sirski kralj Ben Hadád, me je poslal k tebi, rekoč: ›Ali bom okreval od te bolezni?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elizej mu je rekel: »Pojdi, reci mu: ›Ti zagotovo lahko okrevaš,‹ vendar mi je Gospod pokazal, da bo zagotovo umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Trdno je naravnal svoje obličje, dokler ni pobledel in Božji mož je zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Hazaél je rekel: »Zakaj joka moj gospod?« In ta je odgovoril: »Ker poznam zlo, ki ga boš storil Izraelovim otrokom. Njihova oporišča boš požgal, njihove mladeniče boš pobil z mečem, raztreščil njihove otroke in razparal njihove nosečnice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hazaél je rekel: »Toda ali je tvoj služabnik pes, da bi storil to veliko stvar?« Elizej je odgovoril: » Gospod mi je pokazal, da boš postal kralj nad Sirijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Tako je odšel od Elizeja in prišel k svojemu gospodarju, ki mu je rekel: »Kaj ti je Elizej povedal?« Odgovoril je: »Povedal mi je, da boš zagotovo okreval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Naslednji dan pa se je pripetilo, da je vzel debelo cunjo, jo namočil v vodi in jo razprostrl na njegov obraz, tako da je umrl in namesto njega je zakraljeval Hazaél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'V petem letu Joráma, sina Izraelovega kralja Ahába, takrat je bil Józafat Judov kralj, je začel kraljevati Jehorám, sin Judovega kralja Józafata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Dvaintrideset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval osem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Hodil je po poti Izraelovih kraljev, kakor je počela Ahábova hiša, kajti Ahábova hči je bila njegova žena. Počel je zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Vendar Gospod ni hotel uničiti Juda zaradi svojega služabnika Davida, kakor mu je obljubil, da bo vedno dal svetlobo njemu in njegovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'V njegovih dneh se je Edóm spuntal izpod Judove roke in si nad seboj postavil kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Tako je Jorám odšel v Caír in vsi njegovi bojni vozovi z njim in vstal je ponoči in udaril Edómce, ki so ga obdali naokoli in poveljnike bojnih vozov. In ljudstvo je pobegnilo v svoje šotore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Vendar se je Edóm spuntal izpod Judove roke do današnjega dne. Potem se je ob istem času spuntala Libna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Ostala Jorámova dela in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Jorám je zaspal s svojimi očeti in je bil s svojimi očeti pokopan v Davidovem mestu in namesto njega je zakraljeval njegov sin Ahazjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'V dvanajstem letu Joráma, sina Izraelovega kralja Ahába, je začel kraljevati Ahazjá, sin Judovega kralja Jehoráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ahazjá je bil star dvaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval eno leto. Ime njegove matere je bilo Ataljá, hči Izraelovega kralja Omrija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Hodil je po poti Ahábove hiše in počel zlo v Gospodovih očeh, kakor je počela Ahábova hiša, kajti bil je zet Ahabove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Z Ahábovim sinom Jorámom je odšel na vojno zoper sirskega kralja Hazaéla v Ramót Gileád in Sirci so ranili Joráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Kralj Jorám je odšel nazaj, da bi bil v Jezreélu ozdravljen ran, ki so mu jih zadali Sirci pri Rami, ko se je boril zoper sirskega kralja Hazaéla. In Ahazjá, sin Judovega kralja Jehoráma, je odšel dol, da pogleda Ahábovega sina Joráma v Jezreélu, ker je bil bolan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Prerok Elizej je poklical enega izmed preroških otrok in mu rekel: »Opaši svoja ledja, v svojo roko vzemi to stekleničko olja in pojdi v Ramót Gileád');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'in ko prideš tja, tam poglej za Jehújem, sinom Józafata, Nimšíjevim sinom in vstopi in naj vstane izmed svojih bratov in ga odvedi v notranjo sobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Potem vzemi stekleničko olja, ga izlij na njegovo glavo in reci: ›Tako govori Gospod: ›Mazilil sem te za kralja nad Izraelom.‹‹ Potem odpri vrata, zbeži in ne obotavljaj se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Tako je mladenič, mladi mož prerok, odšel do Ramót Gileáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Ko je prišel, glej, so poveljniki vojske sedeli in rekel je: »Naročilo imam zate, oh poveljnik.« Jehú je rekel: »Za katerega izmed nas vseh?« Rekel je: »Zate, oh poveljnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Ta je vstal in odšel v hišo in na njegovo glavo je izlil olje ter mu rekel: »Tako govori Gospod, Izraelov Bog: ›Mazilil sem te za kralja nad Gospodovim ljudstvom, celó nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Udaril boš hišo svojega gospodarja Ahába, da lahko maščujem kri svojih služabnikov prerokov in kri vseh Gospodovih služabnikov pri Jezabelini roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Kajti celotna Ahábova hiša bo uničena in od Ahába bom iztrebil tistega, ki lula proti zidu in tistega, ki je zaprt in je ostal v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Ahábovo hišo bom naredil podobno hiši Nebátovega sina Jerobeáma in podobno hiši Ahíjevega sina Bašája');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'in psi bodo pojedli Jezabelo na jezreélskem deležu in nikogar ne bo, da bi jo pokopal.‹« In odprl je vrata ter zbežal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Potem je Jehú prišel k služabnikom svojega gospoda in nekdo mu je rekel: » Ali je vse dobro? Zakaj je ta nori človek prišel k tebi?« Rekel jim je: »Poznate moža in njegovo govorjenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Rekli so: » To je laž. Povej nam torej.« Rekel je: »Tako in tako mi je rekel, rekoč: ›Tako govori Gospod: ›Mazili sem te za kralja nad Izraelom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Potem so pohiteli in vsak mož je vzel svojo obleko in jo položil pod njega na vrhu stopnic in zatrobili so s šofarji, rekoč: »Jehú je kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tako je Jehú, Józafatov sin, Nimšíjev sin, koval zaroto zoper Joráma. (Torej Jorám se je zadrževal v Ramót Gileádu, on in ves Izrael, zaradi sirskega kralja Hazaéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Toda kralj Jorám se je vrnil, da bi bil v Jezreélu ozdravljen ran, ki so mu jih zadali Sirci, ko se je bojeval s sirskim kraljem Hazaélom.) Jehú je rekel: »Če tako mislite, potem naj nihče ne gre naprej niti naj ne zbeži iz mesta, da bi šel to povedat v Jezreél.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Tako je Jehú jahal na bojnem vozu in odšel v Jezreél, kajti tam je ležal Jorám. In Judov kralj Ahazjá je prišel dol, da vidi Joráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Tam je stal stražar na stolpu v Jezreélu in ogledoval Jehújevo skupino, medtem ko je prihajala in rekel: »Vidim skupino.« Jorám je rekel: »Vzemi konjenika in ga pošlji, da jih sreča in naj reče: › Ali je mir?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Tako je nekdo odšel na konjskem hrbtu, da ga sreča in rekel: »Tako govori kralj: › Je to mir?‹« Jehú je rekel: »Kaj imaš opraviti z mirom? Obrni se za menoj.« Stražar je povedal, rekoč: »Poslanec je prišel do njih, toda ne vrača se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Potem je poslal ven drugega, na konjskem hrbtu, ki je prišel k njim in rekel: »Tako govori kralj: › Ali je mir?‹« Jehú je odgovoril: »Kaj imaš opraviti z mirom? Obrni se za menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Stražar je povedal, rekoč: »Prišel je celo k njim, toda ne vrača se in vožnja je podobna vožnji Nimšíjevega sina Jehúja, kajti divje vozi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Jorám je rekel: »Pripravite.« In njegov bojni voz je bil pripravljen. Izraelov kralj Jorám in Judov kralj Ahazjá sta odšla ven, vsak na svojem bojnem vozu in odšla sta ven zoper Jehúja in ga srečala na deležu Jezreélca Nabóta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Pripetilo se je, ko je Jorám zagledal Jehúja, da je rekel: » Ali je mir, Jehú?« Odgovoril je: »Kakšen mir, dokler je tako mnogo vlačugarstev in čaranj tvoje matere Jezabele?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Jorám je obrnil svoji roki, pobegnil in rekel Ahazjáju: » To je izdaja, oh Ahazjá.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jehú je z vso svojo močjo napel lok in zadel Jehoráma med lopatici in puščica je izšla pri njegovem srcu in zgrudil se je na svoj bojni voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Potem je Jehú rekel svojemu poveljniku Bidkárju: »Poberi ga in vrzi ga na delež polja Jezreélca Nabóta, kajti spomni se, kako je Gospod nanj položil to breme, ko sva jaz in ti skupaj jahala za njegovim očetom Ahábom:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '›Zagotovo sem včeraj videl Nabótovo kri in kri njegovih sinov, govori Gospod, in jaz te bom poplačal na tem deležu, govori Gospod.‹ Sedaj ga torej vzemi in vrzi na kos zemlje, glede na Gospodovo besedo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Toda ko je Judov kralj Ahazjá to videl, je zbežal po poti vrtne hiše. Jehú je sledil za njim in rekel: »Udarite tudi njega na bojnem vozu.« Storili so tako ob vzponu na Gur, ki je poleg Jibleáma. In pobegnil je v Megído ter tam umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Njegovi služabniki so ga na bojnem vozu prenesli v Jeruzalem in ga pokopali v njegovem mavzoleju, z njegovimi očeti, v Davidovem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'V enajstem letu Ahábovega sina Joráma je nad Judom začel kraljevati Ahazjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Ko je Jehú prišel v Jezreél, je Jezabela slišala o tem in si naličila svoj obraz, okrasila svojo glavo in pogledala skozi okno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Ko je Jehú vstopil pri velikih vratih, je rekla: » Ali je imel Zimrí, ki je usmrtil svojega gospodarja, mir?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Svoj obraz je povzdignil proti oknu in rekel: »Kdo je na moji strani? Kdo?« K njemu so pogledali dva ali trije evnuhi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Rekel je: »Vrzite jo dol.« Tako so jo vrgli dol in nekaj njene krvi je poškropilo zid in konje; in pomendral jo je pod stopalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Ko je vstopil, je jedel, pil in rekel: »Pojdite, poglejte sedaj to prekleto žensko in jo pokopljite, kajti kraljeva hči je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Odšli so, da jo pokopljejo, toda niso našli od nje več kot lobanjo, stopala in dlani njenih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Zato so ponovno prišli in mu povedali. Rekel je: »To je beseda od Gospoda, ki jo je govoril po svojem služabniku, Tišbéjcu Eliju, rekoč: ›V Jezreélovem deležu bodo psi jedli Jezabelino meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'In Jezabelino truplo bo kakor iztrebek na obličju polja v Jezreélovem deležu, tako da ne bodo rekli: ›To je Jezabela.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Aháb je imel v Samariji sedemdeset sinov. Jehú je napisal pisma in jih poslal v Samarijo k vladarjem Jezreéla, k starešinam in tistim, ki so vzgajali Ahábove otroke, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '»Torej takoj, ko to pismo pride k vam, glede na to, da so sinovi vašega gospodarja z vami in so tam z vami bojni vozovi in konji, tudi utrjeno mesto in bojna oprema,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'izberite najboljšega in najprimernejšega izmed sinov svojega gospodarja in ga postavite na prestol njegovega očeta in se borite za hišo svojega gospodarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Toda silno so se bali in rekli: »Glej, dva kralja nista obstala pred njim, kako bomo torej obstali mi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'In ta, ki je bil nad hišo in ta, ki je bil nad mestom, tudi starešine in vzgojitelji otrok, so poslali k Jehúju, rekoč: »Tvoji služabniki smo in storili bomo vse, kar nam boš naročil. Ne bomo postavili nobenega kralja. Stôri to, kar je dobro v tvojih očeh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Potem jim je drugič napisal pismo, rekoč: »Če ste moji in če boste prisluhnili mojemu glasu, vzemite glave mož sinov svojega gospodarja in do jutri ob tem času pridite k meni v Jezreél.« Torej kraljevi sinovi, ki jih je bilo sedemdeset oseb, so bili z mestnimi velikaši, ki so jih vzgajali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Pripetilo se je, ko je pismo prišlo do njih, da so vzeli kraljeve sinove in usmrtili sedemdeset oseb in njihove glave dali v košare in mu jih poslali v Jezreél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Tja je prišel poslanec in mu povedal, rekoč: »Prinesli so glave kraljevih sinov.« Rekel je: »Do jutra jih naložite na dva kupa ob vhodu v velika vrata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Zjutraj se je pripetilo, da je odšel ven, obstal in vsemu ljudstvu rekel: » Bodite pravični. Glejte, koval sem zaroto zoper svojega gospodarja in ga usmrtil, toda kdo je usmrtil vse te?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Vedite torej, da ne bo padlo na zemljo ničesar od Gospodove besede, ki jo je Gospod govoril glede Ahábove hiše, kajti Gospod je storil to, kar je govoril po svojem služabniku Eliju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Tako je Jehú usmrtil vse, kar je od Ahábove hiše ostalo v Jezreélu, vse njegove velikaše, njegovo žlahto in njegove duhovnike, dokler mu ni preostal niti eden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Vstal je, odšel in prišel v Samarijo. In ko je bil pri strižni hiši ob poti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'se je Jehú srečal z brati Judovega kralja Ahazjája in rekel: »Kdo ste?« Odgovorili so: »Mi smo Ahazjájevi bratje in gremo dol, da pozdravimo kraljeve otroke in otroke kraljice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Rekel je: »Zgrabite jih žive.« Zgrabili so jih žive in jih usmrtili pri jami strižne hiše, celó dvainštirideset mož. Niti ni pustil nobenega izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Ko je odpotoval od tam, je naletel na Rehábovega sina Jonadába, ki je prihajal, da se sreča z njim. Pozdravil ga je in mu rekel: »Je tvoje srce iskreno, kakor je moje srce s tvojim srcem?« Jonadáb je odgovoril: »Je.« »Če je tako, mi podaj svojo roko.« Podal mu je svojo roko in vzel ga je gor k sebi na bojni voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Rekel je: »Pridi z menoj in poglej mojo gorečnost za Gospoda.« Tako so ga primorali, da se pelje na njegovem bojnem vozu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Ko je prišel v Samarijo, je usmrtil vse, ki so Ahábu preostali v Samariji, dokler jih ni uničil, glede na Gospodovo besedo, ki jo je govoril Eliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Jehú je vse ljudstvo zbral skupaj in jim rekel: »Aháb je malo služil Báalu, toda Jehú mu bo bolj služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Zdaj torej pokličite k meni vse Báalove preroke, vse njegove služabnike in vse njegove duhovnike. Naj nihče ne manjka, kajti imam veliko klavno daritev, da jo opravim Báalu. Kdorkoli bo manjkal, ta ne bo živel.« Toda Jehú je to storil v premetenosti, z namenom, da bi lahko uničil Báalove oboževalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehú je rekel: »Razglasite slovesen zbor za Báala.« In to so razglasili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jehú je poslal po vsem Izraelu in prišli so vsi Báalovi oboževalci, tako da ni ostalo nobenega človeka, ki ne bi prišel. Prišli so v Báalovo hišo in Báalova hiša je bila polna od enega konca do drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Tistemu, ki je bil nad oblačilnico, je rekel: »Prinesi talarje za vse Báalove oboževalce.« In prinesel jim je talarje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Jehú in Rehábov sin Jonadáb sta odšla v Báalovo hišo in Báalovim oboževalcem rekla: »Preiščite in poglejte, da ni tukaj z vami kakega Gospodovega služabnika, temveč samo Báalovi oboževalci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Ko so vstopili, da darujejo klavne daritve in žgalne daritve, je Jehú zunaj določil osemdeset mož in rekel: » Če katerikoli izmed mož, ki sem jih privedel v vaše roke, pobegne, kdor mu pusti oditi, bo njegovo življenje za življenje od tistega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Pripetilo se je, takoj ko je končal z darovanjem žgalne daritve, da je Jehú rekel straži in poveljnikom: »Vstopite in jih pobijte; naj nihče ne pride naprej.« In udarili so jih z ostrino meča. Straža in poveljniki so jih vrgli ven in odšli v mesto Báalove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, '§ Iz Báalove hiše so prinesli podobe in jih sežgali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Porušili so Báalovo podobo, zrušili Báalovo hišo in jo naredili za straniščno hišo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Tako je Jehú uničil Báala iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Vendar se od grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši, Jehú ni odvrnil od sledenja za njimi, namreč zlatih telet, ki sta bila v Betelu in v Danu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Gospod je rekel Jehúju: »Ker si storil dobro v izvrševanju tega, kar je pravilno v mojih očeh in si Ahábovi hiši storil glede na vse, kar je bilo na mojem srcu, bodo tvoji otroci četrtega rodu sedeli na Izraelovem prestolu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Toda Jehú ni pazil, da bi se z vsem srcem ravnal po postavi Gospoda, Izraelovega Boga, kajti ni se oddvojil od Jerobeámovih grehov, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'V tistih dneh je Gospod začel obsekavati Izraela in Hazaél jih je udaril po vseh Izraelovih pokrajinah;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'od Jordana proti vzhodu, vso deželo Gileád, Gádovce, Rubenovce in Manásejce, od Aroêrja, ki je pri reki Arnón, celo Gileád in Bašán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Torej preostala izmed Jehújevih dejanj in vse, kar je storil in vsa njegova moč, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Jehú je zaspal s svojimi očeti in pokopali so ga v Samariji. Namesto njega je zakraljeval njegov sin Joaház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Časa, ko je Jehú kraljeval nad Izraelom, v Samariji, je bilo osemindvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Ko je Ahazjájeva mati Ataljá videla, da je njen sin mrtev, je vstala in uničila vse kraljevo seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Toda Jošéba, hči kralja Joráma, Ahazjájeva [pol] sestra, je vzela Ahazjájevega sina Joáša in ga ukradla izmed kraljevih sinov, ki so bili umorjeni in ju pred Ataljo skrila v spalnici, njega in njegovo dojiljo, tako da ni bil umorjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Šest let je bil skrit v Gospodovi hiši. In Ataljá je kraljevala nad deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Sedmo leto pa je Jojadá poslal in zbral vladarje nad stotimi, s poveljniki straže in jih privedel k sebi v Gospodovo hišo in z njimi sklenil zavezo in od njih v Gospodovi hiši vzel prisego in jim pokazal kraljevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Zapovedal jim je, rekoč: »To je stvar, ki jo boste storili. Tretjina izmed vas, ki vstopate na šabat, boste torej čuvaji straže kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Tretjina bo pri Surskih velikih vratih in tretjina pri velikih vratih zadaj za stražo. Tako boste stražili hišo, da ta ne bo vlomljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Dva dela izmed vas vseh, ki greste na šabat naprej, celo ti bodo stražili Gospodovo hišo okoli kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Obdali boste kralja, vsak človek s svojim orožjem v svoji roki in kdor pride v doseg, naj bo umorjen in bodite s kraljem, ko ta odhaja in ko prihaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Poveljniki nad stotimi so storili glede na vse stvari, ki jih je duhovnik Jojadá zapovedal in vzeli so vsak mož svoje može, ki naj bi vstopili na šabat, s tistimi, ki naj bi šli ven na šabat in prišli k duhovniku Jojadáju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Poveljnikom nad stotimi je duhovnik izročil puščice in ščite kralja Davida, ki so bili v Gospodovem templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Straža je stala, vsak mož s svojim orožjem v svoji roki, okoli kralja, od desnega vogala templja, do levega vogala templja, vzdolž poleg oltarja in templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Naprej je pripeljal kraljevega sina, nanj nadel krono, mu dal pričevanje in postavili so ga [za] kralja in ga mazilili. Ploskali so s svojimi rokami in govorili: »Živel kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Ko je Ataljá slišala hrup straže in ljudstva, je prišla k ljudstvu v Gospodov tempelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Ko je pogledala, glej, je kralj stal ob stebru, kakor je bila navada in princi s trobentami poleg kralja in vse ljudstvo dežele se je veselilo in trobilo s trobentami, Ataljá pa je pretrgala svoja oblačila in zakričala: »Izdaja, izdaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Toda duhovnik Jojadá je zapovedal poveljnikom nad stotimi, častnikom vojske in jim rekel: »Med vrstami jo odpeljite ven iz hiše in tistega, ki ji sledi, ubijte z mečem. Kajti duhovnik je rekel: ›Naj ne bo umorjena v Gospodovi hiši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Nanjo so položili roke in odšla je po poti, po kateri konji pridejo v kraljevo hišo in tam je bila umorjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Jojadá je sklenil zavezo med Gospodom, kraljem in ljudstvom, da bodo Gospodovo ljudstvo, med kraljem in tudi med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Vse ljudstvo dežele je vstopilo v Báalovo hišo in jo porušilo. Njegove oltarje in njegove podobe so temeljito zlomili na koščke in pred oltarjem usmrtili Báalovega duhovnika Matána. In duhovnik je določil častnike nad Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Vzel je vladarje nad stotimi, poveljnike, stražo in vse ljudstvo dežele in kralja so privedli dol od Gospodove hiše in po poti stražarskih velikih vrat prišli h kraljevi hiši. In usedel se je na prestol kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Vse ljudstvo dežele se je veselilo in mesto je bilo pomirjeno, Ataljo pa so usmrtili z mečem poleg kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joáš je bil star sedem let, ko je začel kraljevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'V sedmem letu Jehúja je Joáš začel kraljevati in v Jeruzalemu je kraljeval štirideset let. Ime njegove matere je bilo Cibjá iz Beeršébe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Joáš je delal to, kar je bilo pravilno v Gospodovih očeh, vse svoje dni, ko ga je duhovnik Jojadá poučeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Toda visoki kraji niso bili odstranjeni. Ljudstvo je še vedno žrtvovalo in zažigalo kadilo na visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Joáš je rekel duhovnikom: »Ves denar od posvečenih stvari, ki je prinesen v Gospodovo hišo, celó denar vsakega, ki gre na račun, denar, ki je določen vsakemu možu in ves denar, ki pride v srce katerega človeka, da ga prinese v Gospodovo hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'naj ga duhovniki vzamejo k sebi, vsak človek od svojega znanca in naj popravijo vrzeli hiše, kjerkoli bi se našla kakršnakoli vrzel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Toda bilo je tako, da v triindvajsetem letu kralja Joáša, duhovniki niso popravili vrzeli hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Potem je dal kralj Joáš poklicati duhovnika Jojadája in druge duhovnike ter jim rekel: »Zakaj ne popravite vrzeli hiše? Sedaj torej ne sprejemajte več denarja od svojega znanca, temveč ga izročite za vrzeli hiše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Duhovniki so privolili, da od ljudstva ne sprejmejo nič več denarja niti za popravilo hišnih vrzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Toda duhovnik Jojadá je vzel zaboj, v njegov pokrov izvrtal luknjo in ga postavil poleg oltarja, na desni strani, ko nekdo prihaja h Gospodovi hiši in duhovniki, ki varujejo vrata, so vanj polagali ves denar, ki je bil prinesen v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Bilo je tako, ko so videli, da je bilo v zaboju veliko denarja, sta prišla gor kraljev pisar in véliki duhovnik ter ga spravila v torbe in preštela denar, ki je bil najden v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Denar sta izročila, kakor jima je bilo rečeno, v roke tistih, ki so opravljali delo, ki so nadzorovali Gospodovo hišo in ga izročila tesarjem in graditeljem, ki so delali na Gospodovi hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'zidarjem in kamnosekom, da kupijo lesa in klesanega kamna, da popravijo vrzeli Gospodove hiše in za vse, kar se je porabilo za hišo, da jo popravijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Vendar za Gospodovo hišo niso bile izdelane skledice iz srebra, utrinjala, umivalniki, trobente in vsakršne posode iz zlata ali posode iz srebra, od denarja, ki je bil prinesen v Gospodovo hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'temveč so ga dali delavcem in z njim popravljali Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Poleg tega niso delali obračuna z možmi, v čigar roko so izročili denar, da bi bil podeljen delavcem, kajti postopali so zvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Denar za prekršek in denar za greh ni bil prinesen v Gospodovo hišo. Ta je pripadal duhovnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Potem je sirski kralj Hazaél odšel gor, se boril zoper Gat, ga zavzel in Hazaél je svoj obraz nameril, da gre gor do Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Judov kralj Joáš je vzel vse posvečene stvari, ki so jih Józafat, Jehorám in Ahazjá, njegovi očetje, Judovi kralji, posvetili in svoje lastne posvečene stvari in vse zlato, ki je bilo najdeno v zakladnicah Gospodove hiše in v kraljevi hiši in to poslal sirskemu kralju Hazaélu in ta je odšel proč od Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Ostala Joaševa dela in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Njegova služabnika pa sta vstala, skovala zaroto in Joáša usmrtila v Milójevi hiši, ki gre dol do Sila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Kajti njegova služabnika Šimátin sin Jozakarja in Šomêrjev sin Jozabád sta ga udarila in je umrl. Pokopali so ga z njegovimi očeti v Davidovem mestu in namesto njega je zakraljeval njegov sin Amacjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'V triindvajsetem letu Joáša, Ahazjájevega sina, Judovega kralja, je nad Izraelom, v Samariji, začel kraljevati Jehújev sin Joaház in kraljeval je sedemnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Počel je to, kar je bilo zlo v Gospodovih očeh in sledil grehom Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši; od tega se ni odvrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Gospodova jeza je bila vžgana zoper Izrael in vse njihove dni jih je izročil v roko sirskega kralja Hazaéla in v roko Hazaélovega sina Ben Hadáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Joaház je iskal Gospoda in Gospod mu je prisluhnil, kajti videl je zatiranje Izraela, ker jih je zatiral sirski kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(In Gospod je dal Izraelu rešitelja, tako da so odšli izpod roke Sircev in Izraelovi otroci so prebivali v svojih šotorih kakor poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Vendar se niso odvrnili od grehov Jerobeámove hiše, ki je Izraela primoral grešiti, temveč so hodili v njih in ašere so ostale tudi v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Niti ni pustil od ljudstva Joaházu [nikogar] razen petdesetih konjenikov, desetih bojnih voz in deset tisoč pešcev, kajti sirski kralj jih je uničil in jih z mlatenjem naredil podobne prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Torej preostala izmed Joaházovih dejanj in vse, kar je storil in njegova moč, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Joaház je zaspal s svojimi očeti in pokopali so ga v Samariji in namesto njega je zakraljeval njegov sin Jehoáš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'V sedemintridesetem letu Judovega kralja Joáša je nad Izraelom v Samariji začel kraljevati Joaházov sin Jehoáš in kraljeval je šestnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Počel je to, kar je bilo zlo v Gospodovih očeh. Ni se oddvojil od vseh grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši, temveč je hodil v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Ostala Jehoáševa dela in vse, kar je storil in njegova moč, s katero se je boril zoper Judovega kralja Amacjája, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Jehoáš je zaspal s svojimi očeti in Jerobeám je sédel na njegov prestol in Jehoáš je bil z Izraelovimi kralji pokopan v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Torej Elizej je postal bolan od svoje bolezni, od katere je [tudi] umrl. Izraelov kralj Jehoáš je prišel dol k njemu, jokal nad njegovim obrazom in rekel: »Oh moj oče, moj oče, Izraelov bojni voz in njegovi konjeniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elizej mu je rekel: »Vzemi lok in puščice.« In vzel si je lok in puščice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Izraelovemu kralju je rekel: »Svojo roko položi na lok.« Svojo roko je položil nanj in Elizej je svoje roke položil na kraljeve roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Rekel je: »Odpri okno proti vzhodu.« Odprl ga je. Potem je Elizej rekel: »Streljaj.« In je izstrelil. Rekel je: »Puščica Gospodove osvoboditve in puščica osvoboditve od Sirije, kajti Sirce boš udaril v Aféku, dokler jih ne boš použil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Rekel je: »Vzemi puščice.« Vzel jih je. Izraelovemu kralju je rekel: »Udarjaj ob tla.« Ta je trikrat udaril in obstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Božji mož je bil nad njim ogorčen in rekel: »Udariti bi moral petkrat ali šestkrat, potem bi Sirijo udarjal, dokler je ne bi použil, medtem ko boš sedaj Sirijo udaril samo trikrat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elizej je umrl in so ga pokopali. In v začetku leta so v deželo vdrle čete Moábcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Pripetilo se je, ko so [nekega] moža pokopavali, glej, da so zagledali četo mož in moža odvrgli v Elizejev mavzolej. Ko je bil mož spuščen dol in se dotaknil Elizejevih kosti, je oživel in stopil na svoja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Toda sirski kralj Hazaél je vse Joaházove dni zatiral Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Gospod pa jim je bil milostljiv in imel sočutje do njih in spoštovanje do njih zaradi svoje zaveze z Abrahamom, Izakom in Jakobom in jih ni želel uničiti niti jih še ni vrgel izpred svoje prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Tako je sirski kralj Hazaél umrl in namesto njega je zakraljeval njegov sin Ben Hadád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Joaházov sin Jehoáš je mesta ponovno vzel iz rok Hazaélovega sina Ben Hadáda, ki jih je ta z vojno vzel iz roke njegovega očeta Joaháza. Jehoáš ga je trikrat premagal in povrnil Izraelova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'V drugem letu Jehoáša, Joaházovega sina, Izraelovega kralja, je zakraljeval Amacjá, sin Judovega kralja Joáša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Petindvajset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval devetindvajset let. Ime njegove matere je bilo Joadána iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, vendar ne tako kakor njegov oče David. Delal je glede na vse stvari, kakor jih je delal njegov oče Joáš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Vendar visoki kraji niso bili odstranjeni. Ljudstvo je na visokih krajih še vedno žrtvovalo in zažigalo kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Takoj, ko je bilo kraljestvo v njegovi roki potrjeno, se je pripetilo, da je umoril svoja služabnika, ki sta umorila kralja, njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Toda otrok morilcev ni usmrtil, glede na to, kakor je pisano v knjigi Mojzesove postave, v kateri je Gospod zapovedal, rekoč: »Očetje ne bodo usmrčeni zaradi otrok niti ne bodo otroci usmrčeni zaradi očetov, temveč bo vsak človek usmrčen zaradi svojega lastnega greha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Izmed Edóma jih je v solni dolini usmrtil deset tisoč in v vojni zavzel Selo in njeno ime imenoval Jokteél do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Potem je Amacjá poslal poslance k Jehoášu, sinu Joaháza, sinu Jehúja, Izraelovega kralja, rekoč: »Pridite, drug drugemu poglejmo v obraz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Izraelov kralj Jehoáš je poslal k Judovemu kralju Amacjáju, rekoč: »Osat, ki je bil na Libanonu, je poslal k cedri, ki je bila na Libanonu, rekoč: ›Daj svojo hčer mojemu sinu za ženo,‹ pa je tam mimo šla divja zver, ki je bila na Libanonu in pomendrala osat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Zares si udaril Edóma in tvoje srce te je povzdignilo. Uživaj v tem in ostani doma, kajti zakaj bi se vmešaval v svojo bolečino, da bi padel ti in Juda s teboj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Toda Amacjá ni hotel poslušati. Zato je Izraelov kralj Jehoáš odšel gor in on in Judov kralj Amacjá sta si drug drugemu pogledala v obraz pri Bet Šemešu, ki pripada Judu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Juda je bil premagan pred Izraelom in pobegnili so vsak mož k svojim šotorom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Izraelov kralj Jehoáš je ujel Judovega kralja Amacjája, sina Joáša, sina Ahazjája, pri Bet Šemešu, prišel v Jeruzalem in porušil jeruzalemsko obzidje od Efrájimskih velikih vrat do Vogalnih velikih vrat, štiristo komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Vzel je vse zlato, srebro in vse posode, ki so se našle v Gospodovi hiši, v zakladnicah kraljeve hiše in talce ter se vrnil v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Torej ostala izmed Jehoáševih dejanj, ki jih je storil, njegova moč in kako se je boril z Judovim kraljem Amacjájem, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Jehoáš je zaspal s svojimi očeti in z Izraelovimi kralji je bil pokopan v Samariji in namesto njega je zakraljeval njegov sin Jerobeám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Judov kralj Amacjá, Joášev sin, je po smrti Jehoáša, Izraelovega kralja, Joaházovega sina, živel petnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Ostala Amacjájeva dela, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Torej zoper njega so v Jeruzalemu skovali zaroto in pobegnil je v Lahíš, toda za njim so poslali v Lahíš in ga tam usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Prinesli so ga na konjih in pokopan je bil s svojimi očeti v Jeruzalemu, v Davidovem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Vse Judovo ljudstvo je vzelo Azarjája, ki je bil star šestnajst let in ga postavilo [za] kralja namesto njegovega očeta Amacjája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Zgradil je Elát in ga povrnil Judu, potem je kralj zaspal s svojimi očeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'V petnajstem letu Judovega kralja Amacjája, Joáševega sina, je v Samariji začel kraljevati Jerobeám, Jehoášev sin, Izraelov kralj in kraljeval je enainštirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Počel je to, kar je bilo zlo v Gospodovih očeh. Ni se oddvojil od vseh grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Povrnil je Izraelovo pokrajino od vstopa v Hamát do morja ravnine, glede na besedo od Gospoda, Izraelovega Boga, ki jo je govoril po roki svojega služabnika Jona, Amitájevega sina, preroka, ki je bil iz Gat Heferja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, '§ Kajti Gospod je videl Izraelovo stisko, da je bila ta zelo grenka, kajti tam ni bilo nobenega zaprtega, niti nobeden ni ostal, niti ni bilo pomočnika za Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Gospod ni rekel, da bo Izraelovo ime izbrisal izpod neba, temveč jih je rešil po roki Jehoáševega sina Jerobeáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Torej preostala izmed Jerobeámovih dejanj in vse, kar je storil in njegova moč, kako se je bojeval in kako je za Izrael obnovil Damask in Hamát, ki je pripadal Judu, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jerobeám je zaspal s svojimi očeti, z Izraelovimi kralji in namesto njega je zakraljeval njegov sin Zaharija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'V sedemindvajsetem letu Izraelovega kralja Jerobeáma je začel kraljevati Azarjá, sin Judovega kralja Amacjája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Šestnajst let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval dvainpetdeset let. Ime njegove matere je bilo Jehólja iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse, kar je delal njegov oče Amacjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'razen, da niso bili odstranjeni visoki kraji. Ljudstvo je na visokih krajih še vedno žrtvovalo in zažigalo kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Gospod je udaril kralja, tako da je bil gobavec do dneva svoje smrti in prebival v posebni hiši. Kraljev sin Jotám pa je bil nad hišo in sodil ljudstvu dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Ostala Azarjájeva dela in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Tako je Azarjá zaspal s svojimi očeti in v Davidovem mestu so ga pokopali z njegovimi očeti in namesto njega je zakraljeval njegov sin Jotám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'V osemintridesetem letu Judovega kralja Azarjá je Jerobeámov sin Zaharija šest mesecev kraljeval nad Izraelom v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Počel je to, kar je bilo zlo v Gospodovih očeh, kakor so počeli njegovi očetje. Ni se oddvojil od grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Jabéšov sin Šalúm se je zoper njega zarotil, ga udaril vpričo ljudstva, ga usmrtil in zakraljeval namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Ostala Zaharijeva dela, glej, zapisana so v kroniški knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'To je bila beseda od Gospoda, ki jo je govoril Jehúju, rekoč: »Tvoji sinovi bodo sedeli na Izraelovem prestolu do četrtega rodu.« In tako se je zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Jabéšov sin Šalúm je začel kraljevati v devetintridesetem letu Judovega kralja Uzíjaha, in cel mesec je kraljeval v Samariji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Kajti Gadíjev sin Menahém je iz Tirce odšel gor, prišel v Samarijo in v Samariji udaril Jabéševega sina Šalúma, ga umoril in zakraljeval namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Ostala Šalúmova dela in njegova zarota, ki jo je storil, glej, zapisana so v kroniški knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Potem je Menahém udaril Tifsáha in vse, ki so bili v njem in njegove pokrajine od Tirce, ker se niso odprli k njemu, zato ga je udaril, in vse ženske, ki so bile v njem, ki so bile z otrokom, je razparal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'V devetintridesetem letu Judovega kralja Azarjája je nad Izraelom začel kraljevati Gadíjev sin Menahém in v Samariji je kraljeval deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Počel je to, kar je bilo zlo v Gospodovih očeh. Vse svoje dni se ni oddvojil od grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Zoper deželo je prišel asirski kralj Pul in Menahém je dal Pulu tisoč talentov srebra, da bi bila njegova roka lahko z njim, da potrdi kraljestvo v njegovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Menahém je od Izraela zahteval denar od vseh mogočnih mož obilja, od vsakega moža petdeset šeklov srebra, da jih dá asirskemu kralju. Tako se je kralj Asirije obrnil nazaj in ni ostal v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Ostala Menahémova dela in vse, kar je storil, mar niso zapisana v kroniški knjigi Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menahém je zaspal s svojimi očeti in namesto njega je zakraljeval njegov sin Pekahjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'V petdesetem letu Judovega kralja Azarjája je nad Izraelom v Samariji začel kraljevati Menahémov sin Pekahjá in kraljeval je dve leti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Počel je to, kar je bilo zlo v Gospodovih očeh; ni se oddvojil od grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Toda njegov poveljnik, Remaljájev sin Pékah, se je zarotil zoper njega in ga udaril v Samariji, v palači kraljeve hiše z Argóbom in Arjéjem in z njim petdeset mož izmed Gileádcev, ga ubil in zakraljeval namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Ostala Pekahjájeva dela in vse, kar je storil, glej, ta so zapisana v kroniški knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'V dvainpetdesetem letu Judovega kralja Azarjá je nad Izraelom v Samariji začel kraljevati Remaljájev sin Pékah in kraljeval je dvajset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Počel je to, kar je bilo zlo v Gospodovih očeh. Ni se oddvojil od grehov Nebátovega sina Jerobeáma, ki je Izraela pripravil, da greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'V dneh Izraelovega kralja Pékaha je prišel asirski kralj Tiglát Piléser in zavzel Ijón, Abél Bet Maáho, Janóah, Kedeš, Hacór, Gileád in Galilejo, vso Neftálijevo deželo in jih ujete odvedel v Asirijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Elájev sin Hošéa se je zarotil zoper Remaljájevega sina Pékaha, ga udaril, usmrtil in namesto njega zakraljeval v dvajsetem letu Uzíjahovega sina Jotáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Ostala Pékahova dela in vse, kar je storil, glej, ta so zapisana v kroniški knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'V drugem letu Remaljájevega sina Pékaha, Izraelovega kralja, je začel kraljevati Jotám, sin Judovega kralja Uzíjaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Petindvajset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let. Ime njegove matere je bilo Jerúša, Cadókova hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Delal je, kar je bilo pravilno v Gospodovih očeh. Storil je glede na vse, kar je storil njegov oče Uzíjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Vendar visoki kraji niso bili odstranjeni. Ljudstvo je še vedno žrtvovalo in na visokih krajih zažigalo kadilo. Zgradil je višja velika vrata Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Torej preostala izmed Jotámovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'V tistih dneh je Gospod zoper Juda začel pošiljati sirskega kralja Recína in Remaljájevega sina Pékaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Jotám je zaspal s svojimi očeti in bil s svojimi očeti pokopan v mestu svojega očeta Davida in namesto njega je zakraljeval njegov sin Aház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'V sedemnajstem letu Remaljájevega sina Pékaha je začel kraljevati Aház, sin Judovega kralja Jotáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Dvajset let je bil Aház star, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let in ni počel tega, kar je bilo pravilno v očeh Gospoda, njegovega Boga, kakor njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Temveč je hodil po poti Izraelovih kraljev, da, in svojemu sinu storil, da gre skozi ogenj, glede na ogabnosti poganov, ki jih je Gospod pregnal izpred Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Žrtvoval je in zažigal kadilo na visokih krajih, na hribih in pod vsakim zelenim drevesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Potem sta sirski kralj Recín in Izraelov kralj, Remaljájev sin Pékah, prišla gor v Jeruzalem, da se vojskujeta in oblegala Aháza, toda nista ga mogla premagati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Ob tistem času je sirski kralj Recín Elát povrnil Siriji, Jude pa pregnal iz Eláta in Sirci so prišli v Elát in tam prebivajo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Tako je Aház poslal poslance k asirskemu kralju Tiglát Piléserju, rekoč: »Jaz sem tvoj služabnik in tvoj sin. Pridi gor in me reši iz roke sirskega kralja in iz roke Izraelovega kralja, ki sta se vzdignila zoper mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Aház je vzel srebro in zlato, ki je bilo najdeno v Gospodovi hiši in v zakladnicah kraljeve hiše in to poslal kot dar asirskemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Asirski kralj mu je prisluhnil, kajti asirski kralj je odšel gor zoper Damask, ga zavzel in njegovo ljudstvo odvedel ujeto v Kir in usmrtil Recína.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Kralj Aház je odšel k Damasku, da sreča asirskega kralja Tiglát Piléserja in zagledal oltar, ki je bil pri Damasku in kralj Aház je duhovniku Urijáju poslal videz oltarja in njegov vzorec glede na vso njegovo izdelavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Duhovnik Urijá je zgradil oltar glede na vse, kar je kralj Aház poslal iz Damaska. Tako ga je duhovnik Urijá naredil, preden je kralj Aház prišel iz Damaska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Ko je kralj prišel iz Damaska, je kralj zagledal oltar. Kralj se je približal oltarju in daroval na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Zažgal je svojo žgalno daritev, svojo jedilno daritev, izlil svojo pitno daritev in poškropil kri svojih mirovnih daritev na oltar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Privedel je tudi bronast oltar, ki je bil pred Gospodom od sprednjega dela hiše, izmed oltarja in Gospodove hiše ter ga postavil na severno stran oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Kralj Aház je zapovedal duhovniku Urijáju, rekoč: »Na vélikem oltarju zažigaj jutranjo žgalno daritev, večerno jedilno daritev, kraljevo žgalno daritev, njegovo jedilno daritev z žgalno daritvijo vsega ljudstva dežele in njihovo jedilno daritvijo, njihovimi pitnimi daritvami in nanj poškropi vso kri žgalne daritve in vso kri klavne daritve, bronasti oltar pa mi bo, da z njim poizvedujem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Tako je storil duhovnik Urijá, glede na vse, kar je kralj Aház zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kralj Aház je odsekal robove podstavkov in [okrogel] umivalnik odstranil iz njih. Morje je snel iz bronastih volov, ki so bili pod njim in ga položil na tlak iz kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Stebrišče za šabat, ki so ga zgradili v hiši in kraljevi vhod zunaj, je zaradi asirskega kralja obrnil od Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Torej preostala izmed Aházovih dejanj, ki jih je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Aház je zaspal s svojimi očeti in s svojimi očeti je bil pokopan v Davidovem mestu. Namesto njega je zakraljeval njegov sin Ezekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'V dvanajstem letu Judovega kralja Aháza je v Samariji nad Izraelom začel kraljevati Elájev sin Hošéa [za] devet let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Počel je to, kar je bilo zlo v Gospodovih očeh, toda ne kakor Izraelovi kralji, ki so bili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Zoper njega je prišel gor asirski kralj Salmanasar in Hošéa je postal njegov služabnik in mu izročil darila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Asirski kralj je pri Hošéu našel zaroto, kajti ta je poslal poslance k egiptovskemu kralju Soju in ni prinesel nobenega darila k asirskemu kralju, kakor je počel leto za letom, zato ga je asirski kralj zaprl in ga zvezal v ječi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Potem je asirski kralj prišel gor skozi vso deželo, se dvignil do Samarije in jo tri leta oblegal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'V devetem letu kralja Hošéa, je asirski kralj zavzel Samarijo in Izraela odvedel proč v Asirijo ter jih nastanil v Haláhu in Habórju, pri reki Gozán in v mestih Medijcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Kajti bilo je tako, da so Izraelovi otroci grešili zoper Gospoda, svojega Boga, ki jih je privedel gor iz egiptovske dežele, izpod roke faraona, egiptovskega kralja in so se bali drugih bogov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'in hodili po zakonih poganov, ki jih je Gospod pregnal izpred Izraelovih otrok in [po poganskih navadah] Izraelovih kraljev, ki so si jih naredili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Izraelovi otroci so zoper Gospoda, svojega Boga, naskrivaj počeli te stvari, ki niso bile pravilne in si gradili visoke kraje po vseh svojih mestih, od stražarskega stolpa do utrjenega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Postavljali so si podobe in ašere na vsakem visokem hribu in pod vsakim zelenim drevesom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'in tam zažigali kadilo na vseh visokih krajih, kakor so počeli pogani, ki jih je Gospod odvedel izpred njih in počeli zlobne stvari, da Gospoda izzivajo k jezi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'kajti služili so malikom, o katerih jim je Gospod rekel: »Vi ne boste počeli te stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Vendar je Gospod pričeval zoper Izraela in zoper Juda po vseh prerokih in po vseh vidcih, rekoč: »Obrnite se od svojih zlobnih poti in se držite mojih zapovedi in mojih zakonov, glede na vso postavo, ki sem jo zapovedal vašim očetom in ki sem jo poslal k vam po mojih služabnikih prerokih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Vendar niso hoteli poslušati, temveč so otrdili svoje vratove, podobno vratovom svojih očetov, da niso verovali v Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Zavrnili so njegove zakone in njegovo zavezo, ki jo je sklenil z njihovimi očeti in njegova pričevanja, ki jih je pričeval zoper njih. Sledili so ničevosti, postali prazni in odšli za pogani, ki so bili naokoli njih, glede katerih jim je Gospod naročil, da naj ne bi počeli kakor oni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Zapustili so vse zapovedi Gospoda, svojega Boga in si naredili ulite podobe, celó dve teleti, naredili ašero, oboževali vso vojsko neba in služili Báalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Svojim sinovom in svojim hčeram so povzročali, da gredo skozi ogenj in uporabljali so vedeževanje, izrekanje urokov in se prodajali, da počno zlo v Gospodovih očeh, da ga izzivajo do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Zato je bil Gospod zelo jezen nad Izraelom in jih odstranil iz svojega pogleda. Tam ni ostal nihče razen samo Judov rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Tudi Juda se ni držal zapovedi Gospoda, svojega Boga, temveč je hodil po Izraelovih zakonih, ki so jih naredili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Gospod je zavrnil vse Izraelovo seme, jih prizadel in jih izročil v roko plenilcev, dokler jih ni pognal izpred svojega pogleda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Kajti Izraela je odtrgal od Davidove hiše in Nebátovega sina Jerobeáma so postavili za kralja. Jerobeám je Izraela pregnal od sledenja Gospodu in jih primoral, da zagrešijo velik greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Kajti Izraelovi otroci so hodili v vseh Jerobeámovih grehih, ki jih je ta storil; niso se odvrnili od njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'dokler ni Gospod Izraela odstranil izpred svojega pogleda, kakor je govoril po vseh svojih služabnikih prerokih. Tako je bil Izrael odveden proč iz svoje lastne dežele, v Asirijo, do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Asirski kralj pa je privedel može iz Babilona, iz Kute, iz Avája, iz Hamáta in iz Sefarvájima ter jih namesto Izraelovih otrok postavil v mesta Samarije. Samarijo so vzeli v last in prebivali v njenih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Na začetku njihovega prebivanja je bilo tam tako, da se niso bali Gospoda, zato je Gospod mednje poslal leve, ki so usmrtili nekatere izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Zato so asirskemu kralju govorili, rekoč: »Narodi, ki si jih odstranil in postavil v samarijska mesta, ne poznajo sodbe Boga dežele, zato je mednje poslal leve in glej, ti jih pobijajo, ker ne poznajo sodbe Boga dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Potem je asirski kralj zapovedal, rekoč: »Odvedite tja enega izmed duhovnikov, ki ste jih privedli od tam in naj gredo in prebivajo tam in naj jih nauči sodbe Boga dežele.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Potem je eden izmed duhovnikov, ki so ga odvedli iz Samarije, prišel in prebival v Betelu ter jih učil, kako naj bi se bali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Vendar je vsak narod izdelal svoje lastne bogove in jih postavil v hiše visokih krajev, ki so jih naredili Samarijani, vsak narod v svoja mesta, v katerih so prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Možje iz Babilona so naredili Sukót Benót, možje iz Kute so naredili Nergála, možje iz Hamáta so naredili Ašimája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Avéjci so naredili Nibháza in Tartáka, Sefarvéjci pa so svoje otroke v ognju sežigali Adramélehu in Anamélehu, sefarvájimskima bogovoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Tako so se bali Gospoda in si postavili najnižje izmed njih za duhovnike visokih krajev, ki so zanje žrtvovali v hišah visokih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Bali so se Gospoda in služili svojim lastnim bogovom po običaju narodov, od katerih so jih odvedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Do tega dne počnejo po prejšnjih navadah. Ne bojijo se Gospoda niti ne delajo po njihovih zakonih ali po njihovih odredbah ali po postavi in zapovedi, ki jo je Gospod zapovedal Jakobovim otrokom, ki jih je imenoval Izrael,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 's katerimi je Gospod sklenil zavezo in jim naročil, rekoč: »Vi se ne boste bali drugih bogov, niti se jim ne boste priklanjali, niti jim služili, niti jim žrtvovali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'temveč Gospoda, ki vas je privedel gor iz egiptovske dežele z veliko močjo in z iztegnjenim laktom, njega se boste bali in njega boste oboževali in njemu boste žrtvovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Zakone, predpise, odredbe in zapoved, ki vam jo je zapisal, boste obeleževali, da jih izvajate na vékomaj in ne boste se bali drugih bogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Zaveze, ki sem jo sklenil z vami, ne boste pozabili niti se ne boste bali drugih bogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Temveč se boste bali Gospoda, svojega Boga in on vas bo osvobodil iz roke vseh vaših sovražnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Vendar niso prisluhnili, temveč so počeli po svoji prejšnji navadi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tako so se ti narodi bali Gospoda in služili svojim rezanim podobam, tako njihovi otroci in otroci njihovih otrok, kakor so počeli njihovi očetje, tako počnejo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Pripetilo se je torej v tretjem letu Hošéa, Elájevega sina, Izraelovega kralja, da je začel kraljevati Ezekíja, Aházov sin, Judov kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Petindvajset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval devetindvajset let. Ime njegove matere je bilo Abí, Zaharijeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse, kar je storil njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Odstranil je visoke kraje, zlomil podobe, posekal ašere in na koščke zdrobil bronasto kačo, ki jo je naredil Mojzes, kajti v tistih dneh so ji Izraelovi otroci zažigali kadilo in jo imenoval Nehuštán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Zaupal je v Gospoda, Izraelovega Boga, tako da za njim ni bilo nikogar podobnega njemu med vsemi Judovimi kralji niti nikogar, ki bi bil pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Kajti pridružil se je h Gospodu in se ni oddvojil od sledenju njemu, temveč se je držal njegovih zapovedi, ki jih je Gospod zapovedal Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Gospod je bil z njim in uspeval je kamorkoli je odšel in uprl se je zoper asirskega kralja in mu ni služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Udaril je Filistejce, celó do Gaze in njenih meja, od stražarskega stolpa, do utrjenega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Pripetilo se je v četrtem letu kralja Ezekíja, kar je bilo sedmo leto Hošéa, Elájevega sina, Izraelovega kralja, da je asirski kralj Salmanasar prišel gor zoper Samarijo in jo oblegal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Ob koncu treh let so jo zavzeli, torej v šestem letu Ezekíja, to je v devetem letu Izraelovega kralja Hošéa je bila Samarija zavzeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Asirski kralj je Izraela odvedel v Asirijo in jih naselil v Haláhu in Habórju, pri reki Gozán in v mestih Medijcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'ker niso ubogali glasu Gospoda, svojega Boga, temveč so prestopili njegovo zavezo in vse, kar je zapovedal Gospodov služabnik Mojzes, pa jih niso hoteli slišati niti jih izpolnjevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Torej v štirinajstem letu kralja Ezekíja je asirski kralj Senaherib prišel gor zoper vsa utrjena Judova mesta in jih zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Judov kralj Ezekíja je poslal k asirskemu kralju v Lahíš, rekoč: »Grešil sem, obrni se od mene. To, kar polagaš name, bom nosil.« Asirski kralj je Judovemu kralju Ezekíju določil tristo talentov srebra in trideset talentov zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Ezekíja mu je dal vse srebro, ki je bilo najdeno v Gospodovi hiši in v zakladnicah kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Ob tistem času je Ezekíja odluščil zlato iz vrat Gospodovega templja in iz stebrov, ki jih je prevlekel Judov kralj Ezekíja in to dal kralju Asirije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Kralj Asirije je iz Lahíša poslal Tartana, Rabsarísa in Rabšakéja h kralju Ezekíju z veliko vojsko zoper Jeruzalem. Odšli so gor in prišli k Jeruzalemu. In ko so prišli gor, so prišli in obstali pri cevi gornjega ribnika, ki je na glavni cesti pralčevega polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Ko so zaklicali h kralju, je ven k njim prišel Hilkijájev sin Eljakím, ki je bil nad družino, pisar Šebná in Asáfov sin Joáh, letopisec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Rabšaké jim je rekel: »Govorite torej Ezekíju: ›Tako govori veliki kralj, kralj Asirije: ›Kakšno zaupanje je to, v katero zaupaš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Ti praviš (toda to so samo prazne besede): › Imam nasvet in moč za vojno. Komu odslej zaupaš, da si se uprl zoper mene?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Torej glej, ti zaupaš v palico iz poškodovanega trsta, v Egipt, na katerega, če se človek nasloni, se bo ta zadrl v njegovo roko in jo prebodel. Tako je faraon, egiptovski kralj, vsem tem, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Toda če mi rečete: ›Zaupamo v Gospoda, svojega Boga,‹ mar ni to on, katerega visoke kraje in katerega oltarje je Ezekíja odstranil ter rekel Judu in Jeruzalemu: ›Pred tem oltarjem boste oboževali v Jeruzalemu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Zdaj torej, prosim te, daj jamstva mojemu gospodu, asirskemu kralju, jaz pa ti bom izročil dva tisoč konjev, če boš na svoji strani zmožen nanje postaviti jezdece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kako potem hočeš odvrniti obraz enega poveljnika izmed najmanjših služabnikov mojega gospodarja in svoje zaupanje položiti v Egipt zaradi bojnih vozov in konjenikov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Sem mar brez Gospoda prišel gor zoper ta kraj, da ga uničim? Gospod mi je rekel: ›Pojdi gor zoper to deželo in jo uniči.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Potem so Hilkijájev sin Eljakím, Šebná in Joáh rekli Rabšakéju: »Govori, prosimo te, tvojim služabnikom v sirskem jeziku, kajti mi ga razumemo in ne govori z nami v judovskem jeziku v ušesa ljudstva, ki so na obzidju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Toda Rabšaké jim je rekel: »Ali me ni moj gospodar poslal k tvojemu gospodarju in k tebi, da govorim te besede? Ali me ni poslal k možem, ki sedijo na obzidju, da bodo lahko s teboj jedli svoj iztrebek in pili svoj seč?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Potem je Rabšaké vstal, z močnim glasom zaklical v hebrejskem jeziku in spregovoril, rekoč: »Poslušajte besedo velikega kralja, kralja Asirije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'tako govori kralj: ›Ne dopustite, da vas Ezekíja zavede, kajti ne bo sposoben, da vas osvobodi iz njegove roke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'niti naj vam Ezekíja ne da zaupati v Gospoda, rekoč: › Gospod nas bo zagotovo osvobodil in to mesto ne bo izročeno v roko asirskega kralja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Ne prisluhnite Ezekíju, kajti tako govori kralj Asirije: ›Sklenite dogovor z menoj z darilom in pridite ven k meni in potem jejte vsak mož od svoje lastne trte in vsak mož od svojega figovega drevesa in vsak naj pije vodo iz svojega vodnega zbiralnika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'dokler ne pridem in vas vzamem proč v deželo, podobno vaši lastni deželi, deželo žita in vina, deželo kruha in vinogradov, deželo olivnega olja in medu, da boste lahko živeli in ne umrli in ne prisluhnite Ezekíju, ko vas pregovarja, rekoč: › Gospod nas bo osvobodil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Mar so katerikoli izmed bogov narodov mogli svojo deželo rešiti iz roke asirskega kralja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kje so bogovi Hamáta in Arpáda? Kje so bogovi Sefarvájima, Hene in Avája? Mar so Samarijo osvobodili iz moje roke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kdo so tisti izmed vseh bogov dežel, ki so svojo deželo rešili iz moje roke, da bi Gospod rešil Jeruzalem iz moje roke?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Toda ljudstvo je molčalo in mu ni odgovorilo [niti] besede, kajti kraljeva zapoved je bila, rekoč: »Ne odgovarjajte mu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Potem so prišli Hilkijájev sin Eljakím, ki je bil nad družino, pisar Šebná in Asáfov sin Joáh, letopisec, k Ezekíju s svojimi pretrganimi oblačili in mu povedali Rabšakéjeve besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Pripetilo se je, ko je kralj Ezekíja to slišal, da je pretrgal svoja oblačila, se pokril z vrečevino in odšel v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Poslal je Eljakíma, ki je bil nad družino, pisarja Šebná in starešine izmed duhovnikov, pokrite z vrečevino, k preroku Izaiju, Amócovemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Rekli so mu: »Tako govori Ezekíja: ›Ta dan je dan nevšečnosti, grajanja in bogokletja, kajti otroci so prišli do rojstva, pa ni moči, da se rodijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Morda bo Gospod, tvoj Bog, slišal vse besede Rabšakéja, ki ga je njegov gospodar, asirski kralj, poslal, da graja živega Boga in bo grajal besede, ki jih je slišal Gospod, tvoj Bog. Zatorej dvigni svojo molitev za preostanek, ki je ostal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Tako so služabniki kralja Ezekíja prišli k Izaiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Izaija jim je rekel: »Tako boste rekli svojemu gospodarju: ›Tako govori Gospod: ›Ne boj se besed, ki si jih slišal, s katerimi so služabniki asirskega kralja proti meni izrekali bogokletje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Glej, nadenj bom poslal sunek [duha] in slišal bo govorico in se vrne v svojo lastno deželo. Povzročil mu bom, da v svoji lastni deželi pade pod mečem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Tako se je Rabšaké vrnil in našel asirskega kralja, vojskujočega se zoper Libno, kajti slišal je, da je ta odšel iz Lahíša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Ko je slišal o etiopskem kralju Tirháku govoriti: »Glej, prišel je ven, da se bojuje zoper tebe,« je ponovno poslal poslance k Ezekíju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '»Tako boste govorili Judovemu kralju Ezekíju, rekoč: ›Naj te tvoj Bog, v katerega zaupaš, ne zavaja, rekoč: ›Jeruzalem ne bo izročen v roko asirskega kralja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Glej, slišal si kaj so asirski kralji storili vsem deželam z njihovim popolnim uničenjem. In ti boš rešen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Mar so bogovi narodov rešili tiste, ki so jih moji očetje uničili; kakor Gozána, Harána, Recefa in otroke Edena, ki so bili v Telasárju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kje je kralj Hamáta, kralj Arpáda in kralj mesta Sefarvájima, Hene in Avája?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'In Ezekíja je prejel pismo iz roke poslancev ter ga prebral. Ezekíja je odšel gor v Gospodovo hišo in ga razgrnil pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Ezekíja je molil pred Gospodom in rekel: »Oh Gospod, Izraelov Bog, ki prebivaš med kerubi, ti si Bog, celó samo ti vsem zemeljskim kraljestvom. Ti si naredil nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Gospod, nagni svoje uho in prisluhni, odpri, Gospod, svoje oči. Poglej in poslušaj besede Senaheriba, ki ga je poslal, da graja živega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Resnično Gospod, sirski kralji so uničili narode in njihove dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'njihove bogove so vrgli v ogenj, kajti le-ti niso bili bogovi, temveč delo človeških rok, les in kamen. Zato so jih uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Zdaj torej, oh Gospod, naš Bog, rotim te, reši nas iz njegove roke, da bodo vsa kraljestva zemlje lahko vedela, da si ti Gospod Bog, celó samo ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Potem je Amócov sin Izaija, poslal k Ezekíju, rekoč: »Tako govori Gospod, Izraelov Bog: › To, kar si molil k meni zoper asirskega kralja Senaheriba, sem slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'To je beseda, ki jo je glede njega govoril Gospod: ›Devica, sionska hči me je prezirala in se smejala do norčevanja, jeruzalemska hči je s svojo glavo zmajevala nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Koga si grajal in zoper mene izrekal bogokletje? In zoper koga si povišal svoj glas in svoje oči povzdignil na visoko? Celó zoper Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'S svojimi poslanci si grajal Gospoda in rekel: ›Z množico svojih bojnih voz sem prišel gor na višine gora, k pobočjem Libanona in posekal bom njegova visoka cedrova drevesa in njegov izbran cipresov les in vstopil bom v taborišča njegovih meja in v gozd njegovega Karmela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Kopál sem, pil tuje vode in s podplatom svojega stopala sem posušil vse reke obleganih krajev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Mar nisi slišal dolgo nazaj kako sem to storil in od starodavnih časov, da sem to oblikoval? Ali sem sedaj privedel, da se zgodi, da bi ti opustošil utrjena mesta v kupe razvalin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Zato so bili njihovi prebivalci majhne moči. Bili so zaprepadeni in zbegani. Bili so kakor trava polja in kakor zeleno zelišče, kakor trava na hišnih strehah in kakor ožgano žito preden zraste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Toda poznam tvoje prebivališče, tvoj izhod, tvoj prihod in tvoje besnenje zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Ker je tvoje besnenje zoper mene in je tvoj hrup prišel gor v moja ušesa, zato bom zataknil kavelj v tvoj nos in svojo brzdo med tvoje ustnice in obrnil te bom nazaj po poti, po kateri si prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'To ti bo znamenje: ›To leto boste jedli takšne stvari, ki same zrasejo, v drugem letu pa to, kar zraste iz istega. V tretjem letu pa sejte, žanjite, zasajajte vinograde in jejte njegove sadove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Preostanek, ki je pobegnil iz Judove hiše, se bo še enkrat ukoreninil navzdol in prinašal sad navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Kajti iz Jeruzalema bo izšel preostanek in z gore Sion tisti, ki pobegnejo. Gorečnost Gospoda nad bojevniki bo to storila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Zato tako govori Gospod glede asirskega kralja: ›Ne bo prišel v to mesto, niti tja ne bo izstrelil puščice, niti ne bo predenj prišel s ščitom, niti ne bo zoper njega nasul okopov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Po poti, po kateri je prišel, po isti se bo vrnil in ne bo prišel v to mesto,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, '›Kajti branil bom to mesto, da ga rešim zaradi sebe in zaradi svojega služabnika Davida.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Tisto noč se je pripetilo, da je Gospodov angel odšel ven in v taboru Asircev udaril sto petinosemdeset tisoč [mož]. Ko so zgodaj zjutraj vstali, glej, vsi so bili mrtva trupla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Tako je asirski kralj Senaherib odpotoval, odšel, se vrnil in prebival v Ninivah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Pripetilo se je, ko je oboževal v hiši svojega boga Nisróha, da sta ga njegova sinova Adraméleh in Sarécer udarila z mečem in pobegnila v deželo Armenijo. Namesto njega je zakraljeval njegov sin Asarhadón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'V tistih dneh je bil Ezekíja na smrt bolan. K njemu je prišel prerok Izaija, Amócov sin in mu rekel: »Tako govori Gospod: ›Uredi svojo hišo, kajti umrl boš, ne pa živel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Potem je on svoj obraz obrnil k steni in molil h Gospodu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '»Rotim te, oh Gospod, spomni se sedaj, kako sem pred teboj hodil v resnici, s popolnim srcem in storil sem to, kar je dobro v tvojih očeh.« In Ezekíja je bridko zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Pripetilo se je, še preden je Izaija odšel ven na srednji dvor, da je k njemu prišla beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '»Ponovno se obrni in povej Ezekíju, poveljniku mojega ljudstva: ›Tako govori Gospod, Bog tvojega očeta Davida: ›Slišal sem tvojo molitev in videl sem tvoje solze. Glej, ozdravil te bom. Na tretji dan boš odšel gor v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Tvojim dnevom bom dodal petnajst let in tebe ter to mesto osvobodil iz roke asirskega kralja in to mesto bom branil zaradi sebe in zaradi svojega služabnika Davida.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Izaija je rekel: »Vzemite kepo fig.« Vzeli so jo in jo položili na gnojno bulo in si je opomogel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ezekíja je rekel Izaiju: »Kakšno bo znamenje, da me bo Gospod ozdravil in da bom tretji dan šel gor v Gospodovo hišo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Izaija je rekel: »To znamenje boš imel od Gospoda, da bo Gospod storil stvar, ki jo je govoril. Ali naj gre senca deset stopinj naprej ali deset stopinj nazaj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezekíja je odgovoril: »Lahka stvar je za senco, da gre deset stopinj navzdol. Ne, temveč naj se senca vrne za deset stopinj nazaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Prerok Izaija je klical h Gospodu in ta je senco privedel deset stopinj nazaj, po kateri se je spustila na Aházovi sončni uri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Ob tistem času je Baladánov sin Berodáh Baladán, kralj Babilona, poslal Ezekíju pisma in darilo, kajti slišal je, da je bil Ezekíja bolan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezekíja jim je prisluhnil in jim razkazal vso hišo svojih dragocenih stvari: srebro, zlato, dišave, dragoceno mazilo, vso hišo svoje bojne opreme in vse, kar se je našlo v njegovih zakladnicah. Nič ni bilo v njegovi hiši niti v vsem njegovem gospostvu, kar jim Ezekíja ni razkazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Tedaj je prišel prerok Izaija h kralju Ezekíju in mu rekel: »Kaj so rekli ti možje? In od kod so prišli k tebi?« Ezekíja je rekel: »Prišli so iz daljne dežele, celó iz Babilona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Rekel je: »Kaj so videli v tvoji hiši?« Ezekíja je odgovoril: »Videli so vse stvari, ki so v moji hiši. Ničesar ni med mojimi zakladi, česar jim ne bi razkazal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Izaija je rekel Ezekíju: »Poslušaj Gospodovo besedo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, '›Glej, pridejo dnevi, ko bo vse, kar je v tvoji hiši, in to, kar so tvoji očetje prihranili v shrambi do tega dne, odneseno v Babilon. Nič ne bo ostalo,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, '›Odvedli bodo izmed tvojih sinov, ki bodo izšli iz tebe, ki jih boš zaplodil in bodo evnuhi v palači babilonskega kralja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Potem je Ezekíja rekel Izaiju: »Dobra je Gospodova beseda, ki si mi jo govoril.« Rekel je: » Ali ni dobro, če bosta v mojih dneh mir in resnica?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ostala Ezekíjeva dela in vsa njegova moč in kako je naredil bazen in kanal in privedel vodo v mesto, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Ezekíja je zaspal s svojimi očeti in namesto njega je zakraljeval njegov sin Manáse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manáse je bil star dvanajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval petinpetdeset let. Ime njegove matere je bilo Hefcí Bah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Počel je to, kar je bilo zlo v Gospodovih očeh, po ogabnostih poganov, ki jih je Gospod pregnal pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Kajti ponovno je zgradil visoke kraje, ki jih je njegov oče Ezekíja uničil, vzdignil oltarje za Báala in naredil ašero, kakor je storil Izraelov kralj Aháb, in oboževal vso vojsko neba in jim služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Zgradil je oltarje v Gospodovi hiši, o kateri je Gospod rekel: »V Jeruzalemu bom postavil svoje ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Zgradil je oltarje za vso vojsko neba na dveh dvorih Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Svojega sina je primoral iti skozi ogenj, obeleževal čase, uporabljal izrekanje urokov, postopal z osebnimi duhovi in čarovniki. Počel je mnogo zlobnosti v Gospodovih očeh, da ga je izzival do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Postavil je rezano podobo ašere, ki jo je naredil v hiši, o kateri je Gospod rekel Davidu in njegovemu sinu Salomonu: »V tej hiši in v Jeruzalemu, ki sem ga izbral izmed vseh Izraelovih rodov, bom svoje ime postavil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Niti ne bom več storil, da se stopala Izraela premaknejo iz dežele, ki sem jo dal njihovim očetom, samo če bodo obeleževali, da storijo glede na vse, kar sem jim zapovedal in glede na vso postavo, ki jim jo je zapovedal moj služabnik Mojzes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Vendar niso prisluhnili in Manáse jih je zapeljal, da so storili več zla, kakor so ga storili narodi, ki jih je Gospod uničil pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Gospod je govoril po svojih služabnikih prerokih, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '»Ker je Judov kralj Manáse storil te ogabnosti in je zlobno počel, nad vsem, kar so počeli Amoréjci, ki so bili pred njim, in tudi Juda je pripravil, da greši z njegovimi maliki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'zato tako govori Gospod, Izraelov Bog: ›Glej, nad Jeruzalem in Juda prinašam takšno zlo, da kdorkoli bo slišal o tem, mu bo zvenelo [v] obeh njegovih ušesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Nad Jeruzalemom bom iztegnil vrvico Samarije in grezilo Ahábove hiše. Jeruzalem bom izbrisal, kakor človek obriše posodo, obriše jo in jo obrne narobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Zapustil bom ostanek svoje dediščine, izročil jih bom v roko njihovih sovražnikov. Postali bodo plen in ukradeno blago vsem svojim sovražnikom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'ker so počeli to, kar je bilo zlo v mojem pogledu in izzivali so me do jeze od dne, ko so njihovi očetje prišli iz Egipta, celo do tega dne.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Poleg tega je Manáse prelil veliko nedolžne krvi, dokler ni Jeruzalema napolnil od enega konca do drugega, poleg njegovega greha, s katerim je Judu storil, da je grešil s početjem tega, kar je bilo zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Torej preostala izmed Manásejevih dejanj in vse, kar je storil in njegov greh, ki ga je zagrešil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Manáse je zaspal s svojimi očeti in pokopan je bil na vrtu svoje lastne hiše, na Uzájevem vrtu. Namesto njega je zakraljeval njegov sin Amón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amón je bil star dvaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval dve leti. Ime njegove matere je bilo Mešulémeta, hči Harúca iz Jotbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Počel je to, kar je bilo zlo v Gospodovih očeh, kakor je počel njegov oče Manáse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Hodil je po vsej poti, po kateri je hodil njegov oče, služil malikom, ki jim je služil njegov oče in jih oboževal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'ter zapustil Gospoda, Boga svojih očetov in ni hodil po Gospodovi poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Amónovi služabniki so se zarotili zoper njega in kralja usmrtili v njegovi lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Ljudstvo dežele je usmrtilo vse tiste, ki so se zarotili zoper kralja Amóna in ljudstvo dežele je namesto njega postavilo za kralja njegovega sina Jošíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Torej preostala izmed Amónovih dejanj, ki jih storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Pokopan je bil v svojem mavzoleju v Uzájevem vrtu in namesto njega je zakraljeval njegov sin Jošíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Jošíja je bil star osem let, ko je začel kraljevati in v Jeruzalemu je kraljeval enaintrideset let. Ime njegove matere je bilo Jedída, hči Adajája iz Bockáta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Delal je to, kar je bilo pravilno v Gospodovih očeh in hodil po vsej poti svojega očeta Davida in se ni obrnil vstran k desni roki ali k levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'V osemnajstem letu kralja Jošíja se je pripetilo, da je kralj poslal Šafána, Acaljájevega sina, Mešulámovega sina, pisarja, h Gospodovi hiši, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '»Pojdi gor k vélikemu duhovniku Hilkijáju, da bo lahko preštel srebro, ki je bilo prineseno v Gospodovo hišo, ki so ga čuvaji vrat zbrali od ljudstva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'in naj ga izročijo v roko izvajalcem dela, ki imajo nadzor nad Gospodovo hišo, in naj ga dajo izvajalcem dela, ki je v Gospodovi hiši, da popravijo vrzeli hiše;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'tesarjem, graditeljem in zidarjem, da kupijo lesa in klesanega kamna, da popravijo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Vendar ni bilo z njimi narejenega nobenega obračuna o denarju, ki je bil izročen v njihovo roko, ker so zvesto postopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Véliki duhovnik Hilkijá je pisarju Šafánu rekel: »V Gospodovi hiši sem našel knjigo postave.« Hilkijá je knjigo izročil Šafánu in ta jo je prebral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Pisar Šafán je prišel h kralju in kralju ponovno prinesel besedo ter rekel: »Tvoji služabniki so zbrali denar, ki je bil najden v hiši in ga izročili v roko tistih, ki opravljajo delo, ki imajo nadzor nad Gospodovo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Pisar Šafán je kralju pokazal, rekoč: »Duhovnik Hilkijá mi je izročil knjigo.« In Šafán jo je bral pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Pripetilo se je, ko je kralj slišal besede iz knjige postave, da je pretrgal svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Kralj je ukazal duhovniku Hilkijáju, Šafánovemu sinu Ahikámu, Ahbórju, sinu Mihajá, pisarju Šafánu in kraljevemu služabniku Asajáju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '»Pojdite, poizvedite od Gospoda zame in za ljudstvo in za vsega Juda glede besed te knjige, ki je najdena, kajti velik je Gospodov bes, ki je vžgan zoper nas, ker naši očetje niso prisluhnili besedam te knjige, da bi storili glede na vse, kar je napisano glede nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Tako so duhovnik Hilkijá, Ahikám, Ahbór, Šafán in Asajá odšli k prerokinji Huldi, ženi Šalúma, Tikvájevega sina, Harhásovega sina, varuha garderobe (torej prebivala je v Jeruzalemu, v drugem okraju) in se posvetovali z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Rekla jim je: »Tako govori Gospod, Izraelov Bog: ›Povejte možu, ki vas je poslal k meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'tako govori Gospod: ›Glejte, nad ta kraj in nad njegove prebivalce bom privedel zlo, celó vse besede knjige, ki jo je bral Judov kralj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'ker so zapustili mene in zažigali kadilo drugim bogovom, da bi me lahko izzivali k jezi z vsemi deli svojih rok. Zato bo moj bes vnet zoper ta kraj in ne bo pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Toda Judovemu kralju, ki vas je poslal, da povprašate od Gospoda, boste rekli tako: ›Tako govori Gospod, Izraelov Bog: › Glede besed, ki si jih slišal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'ker je bilo tvoje srce nežno in si se ponižal pred Gospodom, ko si slišal kaj sem govoril zoper ta kraj in zoper njegove prebivalce, da naj bi postali opustošenje in prekletstvo in si pretrgal svoja oblačila in jokal pred menoj, sem te tudi jaz uslišal, govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Glej torej, zbral te bom k tvojim očetom in v miru boš zbran v svoj grob in tvoje oči ne bodo videle vsega zla, ki ga bom privedel na ta kraj.‹« In kralju so ponovno prinesli besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Kralj je poslal in k njemu so zbrali vse starešine iz Juda in iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Kralj je šel gor v Gospodovo hišo in vsi Judovi možje in vsi prebivalci Jeruzalema z njim, duhovniki, preroki, vse ljudstvo, tako mali kakor veliki, in v njihova ušesa je bral vse besede knjige zaveze, ki je bila najdena v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Kralj je stal pri stebru in sklenil zavezo pred Gospodom, da hodijo za Gospodom in se držijo njegovih zapovedi, njegovih pričevanj in njegovih zakonov z vsem svojim srcem in vso svojo dušo, da izpolnjujejo besede te zaveze, ki so bile zapisane v tej knjigi. In vse ljudstvo je pristopilo k zavezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Kralj je zapovedal vélikemu duhovniku Hilkijáju, duhovnikom drugega reda in čuvajem vrat, da iz Gospodovega templja prinesejo vse posode, ki so bile narejene za Báala, za ašero in za vso vojsko neba, in sežgal jih je zunaj Jeruzalema, na poljih Kidrona in njihov pepel odnesel v Betel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Odstavil je malikovalske duhovnike, ki so jih Judovi kralji določili, da zažigajo kadilo na visokih krajih po Judovih mestih in v krajih naokoli Jeruzalema. Tudi tiste, ki so zažigali kadilo Báalu, soncu, luni, planetom in vsej vojski neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Iz Gospodove hiše je prinesel ašero, ven iz Jeruzalema, do potoka Kidron in jo sežgal pri potoku Kidronu in jo zdrobil v droben prah in njen prah vrgel na grobove otrok ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Porušil je hiše posvečenih vlačugarjev, ki so bile pri Gospodovi hiši, kjer so ženske tkale tanke preproge za ašero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Vse duhovnike je privedel iz Judovih mest in omadeževal visoke kraje, kjer so duhovniki zažigali kadilo od Gebe do Beeršébe in porušil visoke kraje velikih vrat, ki so bile pri vhodu velikih vrat mestnega voditelja Józueta, ki so bila na moževi levici pri velikih vratih mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Vendar duhovniki visokih krajev niso prišli gor h Gospodovemu oltarju v Jeruzalemu, temveč so med svojimi brati jedli nekvašen kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'In omadeževal je Tofet, ki je v dolini Hinómovih otrok, da noben človek ne bi mogel pripraviti svojega sina ali svoje hčere, da gre skozi ogenj k Molohu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Odstranil je konje, ki so jih Judovi kralji podarili soncu ob vhodu v Gospodovo hišo, poleg sobe Netán Meleha, glavnega dvornega upravitelja, ki je bila v predmestjih in sončne bojne vozove sežgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Oltarje, ki so bili na vrhu gornje Aházove sobe, ki so jih naredili Judovi kralji, in oltarje, ki jih je naredil Manáse v dveh dvorih Gospodove hiše, je kralj porušil, jih odstranil od tam in njihov prah vrgel v potok Kidron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Visoke kraje, ki so bili pred Jeruzalemom, ki so bili na desni roki gore izprijenosti, ki jo je Salomon zgradil za Astarto, ogabnost Sidóncev in za Kemoša, ogabnost Moábcev in za Milkóma, gnusobo Amónovih otrok, je kralj omadeževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Podobe je zlomil na koščke, posekal ašere in njihove kraje napolnil s človeškimi kostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Poleg tega oltar, ki je bil pri Betelu in visok kraj, ki ga je naredil Nebátov sin Jerobeám, ki je Izraela primoral grešiti, tako oltar kot visok kraj je porušil, požgal visok kraj, ga zdrobil v prah in sežgal ašero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Ko se je Jošíja obrnil, je ogledal mavzoleje, ki so bili na gori, poslal in iz mavzolejev vzel kosti in jih sežgal na oltarju, ga oskrunil, glede na Gospodovo besedo, ki jo je razglasil Božji mož, ki je razglasil te besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Potem je rekel: »Kakšen steber je to, kar vidim?« Ljudje iz mesta so mu rekli: » To je mavzolej Božjega moža, ki je prišel iz Juda in razglasil te stvari, ki si jih storil zoper betelski oltar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Rekel je: »Pustite ga pri miru. Naj noben človek ne premakne njegovih kosti.« Tako so pustili pri miru njegove kosti, s kostmi preroka, ki je prišel iz Samarije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Tudi vse hiše visokih krajev, ki so bile v samarijskih mestih, ki so jih naredili Izraelovi kralji, da bi Gospoda izzivali k jezi, je Jošíja odstranil in jim storil glede na vsa dejanja, ki jih je storil v Betelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Vse duhovnike visokih krajev, ki so bili tam, je usmrtil na oltarjih in na njih sežgal človeške kosti in se vrnil v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Kralj je vsemu ljudstvu zapovedal, rekoč: »Praznujte pasho Gospodu, svojemu Bogu, kakor je to zapisano v knjigi te zaveze.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Zagotovo tam ni bilo takšne pashe od dni sodnikov, ki so sodili Izraelu, niti v vseh dneh Izraelovih kraljev, niti Judovih kraljev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'kot [je bila ta] v osemnajstem letu kralja Jošíja, v katerem se je praznovala ta pasha Gospodu v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Poleg tega je Jošíja odstranil delavce z osebnimi duhovi, čarovnike, podobe, malike in vse ogabnosti, ki so bile ogledane v Judovi deželi in v Jeruzalemu, da bi lahko izpolnil besede postave, ki so bile zapisane v knjigi, ki jo je duhovnik Hilkijá našel v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Pred njim ni bilo nobenega kralja, ki bi bil podoben njemu, ki bi se z vsem svojim srcem obrnil h Gospodu, z vso svojo dušo in z vso svojo močjo, glede na vso Mojzesovo postavo niti za njim ni vstal nihče, ki bi mu bil podoben.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Vendar Gospod ni odvrnil okrutnosti svojega velikega besa, s čimer je bila vneta njegova velika jeza zoper Juda zaradi vseh izzivanj, s katerimi ga je izzival Manáse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Gospod je rekel: »Prav tako bom iz svojega pogleda odstranil Juda, kakor sem odstranil Izraela in zavrgel bom to mesto Jeruzalem, ki sem ga izbral in hišo, o kateri sem rekel: ›Tam bo moje ime.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Torej preostala izmed Jošíjevih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'V njegovih dneh je faraon Neho, egiptovski kralj, odšel gor zoper asirskega kralja, k reki Evfrat, in kralj Jošíja je odšel zoper njega, in ko ga je [faraon] zagledal ga je usmrtil pri Megídu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Njegovi služabniki so ga na bojnem vozu odnesli mrtvega od Megíde, ga prinesli v Jeruzalem in ga pokopali v njegovem lastnem mavzoleju. Ljudstvo dežele pa je vzelo Jošíjevega sina Joaháza, ga mazililo in ga postavilo [za] kralja namesto njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joaház je bil star triindvajset let, ko je začel kraljevati, in v Jeruzalemu je kraljeval tri mesece. Ime njegove matere je bilo Hamutála, hči Jeremija iz Libne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Počel je to, kar je bilo zlo v Gospodovih očeh, glede na vse, kar so počeli njegovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Faraon Neho ga je vklenil v Ribli, v Hamovi deželi, da ne bi mogel kraljevati v Jeruzalemu in deželo je podvrgel davku stotih talentov srebra in talenta zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Faraon Neho je postavil Jošíjevega sina Eljakíma za kralja namesto njegovega očeta Jošíja in njegovo ime spremenil v Jojakím in odstranil Joaháza. Ta je prišel v Egipt in tam umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Jojakím je dal faraonu srebro in zlato, toda obdavčil je deželo, da izroča denar glede na faraonovo zapoved. Od ljudstva dežele je zahteval srebro in zlato, od vsakogar glede na njegovo obdavčitev, da to izroči faraonu Nehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojakím je bil petindvajset let star, ko je začel kraljevati in v Jeruzalemu je kraljeval enajst let. Ime njegove matere je bilo Zebúda; hči Pedajája iz Rume.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Počel je to, kar je bilo zlo v Gospodovih očeh, glede na vse, kar so počeli njegovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'V njegovih dneh je prišel gor babilonski kralj Nebukadnezar in Jojakím je [za] tri leta postal njegov služabnik. Potem se je obrnil in se uprl zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Gospod je zoper njega poslal čete Kaldejcev, čete Sircev, čete Moábcev, čete Amónovih sinov in jih poslal zoper Juda, da ga uničijo, glede na Gospodovo besedo, ki jo je govoril po svojih služabnikih prerokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Zagotovo je to prišlo nad Juda na Gospodovo zapoved, da jih odstrani iz svojega pogleda zaradi Manásejevih grehov, glede na vse, kar je storil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'in tudi zaradi nedolžne krvi, ki jo je prelil. Kajti Jeruzalem je napolnil z nedolžno krvjo, ki je Gospod ni hotel odpustiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Torej preostala izmed Jojakímovih dejanj in vse, kar je storil, mar niso zapisana v kroniški knjigi Judovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Tako je Jojakím zaspal s svojimi očeti, in namesto njega je zakraljeval njegov sin Jojahín.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Egiptovski kralj ni nič več ponovno prišel iz svoje dežele, kajti babilonski kralj je zavzel od egiptovske reke do reke Evfrat, vse, kar je pripadalo egiptovskemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jojahín je bil star osemnajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval tri mesece. Ime njegove matere je bilo Nehúšta; hči Elnatána iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Počel je to, kar je bilo zlo v Gospodovih očeh, glede na vse, kar je počel njegov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Ob tistem času so služabniki babilonskega kralja Nebukadnezarja prišli gor zoper Jeruzalem in mesto je bilo oblegano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Babilonski kralj Nebukadnezar je prišel zoper mesto in njegovi služabniki so ga oblegali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Judov kralj Jojahín, je odšel ven k babilonskemu kralju, on, njegova mati, njegovi služabniki, njegovi princi in njegovi častniki in babilonski kralj ga je vzel v osmem letu svojega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Od tam je odnesel vse zaklade iz Gospodove hiše in zaklade iz kraljeve hiše in zdrobil na koščke vse posode iz zlata, ki jih je Izraelov kralj Salomon naredil v Gospodovem templju, kakor je rekel Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Proč je odvedel ves Jeruzalem, vse njegove prince in vse močne junaške može, celó deset tisoč ujetnikov in vse rokodelce in kovače. Nihče ni preostal, razen najrevnejše sorte ljudstva dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'V Babilon je odvedel Jojahína, kraljevo mater, kraljeve žene, njegove častnike in mogočne iz dežele; te je iz Jeruzalema odvedel v ujetništvo v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Vse mogočne može, celó sedem tisoč in tisoč rokodelcev in kovačev, vse, ki so bili močni in zmožni za vojno, celo te je babilonski kralj ujete privedel v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Babilonski kralj je namesto njega postavil Matanjája, brata njegovega očeta in njegovo ime spremenil v Sedekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sedekíja je bil star enaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval enajst let. Ime njegove matere je bilo Hamutála, hči Jeremija iz Libne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Počel je to, kar je bilo zlo v Gospodovih očeh, glede na vse, kar je počel Jojakím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Kajti zaradi Gospodove jeze se je to pripetilo v Jeruzalemu in Judu, dokler jih ni zavrgel izpred svoje prisotnosti, da se je Sedekíja uprl zoper babilonskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'V devetem letu njegovega kraljevanja, v desetem mesecu, na deseti dan meseca se je pripetilo, da je prišel babilonski kralj Nebukadnezar, on in vsa njegova vojska, zoper Jeruzalem in so se utaborili zoper njega in vsenaokrog so zoper njega zgradili bojne stolpe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'In mesto je bilo oblegano do enajstega leta kralja Sedekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Na deveti dan četrtega meseca je lakota prevladala v mestu in tam ni bilo kruha za ljudstvo dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Mesto je bilo predrto in vsi bojevniki so ponoči zbežali po poti velikih vrat med dvema zidovoma, kar je ob kraljevem vrtu (Kaldejci so bili zoper mesto vsenaokoli) in kralj je odšel po poti proti ravnini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Kaldejska vojska je zasledovala kralja in ga dohitela na ravninah Jerihe in vsa njegova vojska se je razbežala proč od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Tako so vzeli kralja in ga privedli gor k babilonskemu kralju v Riblo in nad njim izrekli sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Pred njegovimi očmi so usmrtili Sedekíjeve sinove in Sedekíju iztaknili oči, ga zvezali z okovi iz brona in ga odvedli v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'V petem mesecu, na sedmi dan meseca, kar je devetnajsto leto babilonskega kralja Nebukadnezarja, je prišel Nebuzaradán, poveljnik straže, služabnik babilonskega kralja, do Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Požgal je Gospodovo hišo, kraljevo hišo, vse jeruzalemske hiše in hišo vsakega velikega človeka je požgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'In vsa vojska Kaldejcev, ki je bila s poveljnikom straže, je naokoli porušila jeruzalemske zidove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Torej ostanek ljudstva, ki so ostali v mestu in ubežnike, ki so s preostankom množice pobegnili proč k babilonskemu kralju, je Nebuzaradán, poveljnik straže, odvedel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Toda poveljnik straže je pustil revne iz dežele, da bi bili obrezovalci trte in poljedelci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Bronasta stebra, ki sta bila v Gospodovi hiši, podstavke in bronasto morje, ki je bilo v Gospodovi hiši, so Kaldejci razbili na koščke in bron od tega odnesli v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Lonce, lopate, utrinjala, žlice in vse posode iz brona, s katerimi so služili, so odnesli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Ponve za žerjavico, skledice in takšne stvari, ki so bile zlate v zlatu in srebrne v srebru, je poveljnik straže odnesel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Dva stebra, eno morje in podstavke, ki jih je Salomon naredil za Gospodovo hišo. Brona vseh teh posod je bilo brez teže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Višina enega stebra je bila osemnajst komolcev in kapitel na njem je bil iz brona. Višina kapitela tri komolce, in spleteno delo in granatna jabolka na kapitelu naokoli vsa iz brona. Podobno tem je imel drugi steber s pletenim delom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Poveljnik straže je vzel Serajája, vélikega duhovnika in Cefanjája, drugega duhovnika in tri čuvaje vrat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'in iz mesta je vzel častnika, ki je bil postavljen nad bojevniki in pet mož izmed tistih, ki so bili v kraljevi prisotnosti, ki so bili najdeni v mestu in glavnega pisarja vojske, ki je nabiral ljudstvo dežele in šestdeset mož izmed ljudstva dežele, ki so bili najdeni v mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nebuzaradán, poveljnik straže, je te vzel in jih privedel k babilonskemu kralju v Riblo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'in babilonski kralj jih je udaril in jih usmrtil v Ribli, v Hamátovi deželi. Tako je bil Juda odveden proč iz svoje dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Glede ljudstva, ki je preostalo v Judovi deželi, ki jih je babilonski kralj Nebukadnezar pustil, celo nad njimi je postavil Gedaljája, sina Ahikáma, sina Šafána, vladarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Ko so vsi poveljniki vojsk, oni in njihovi možje, slišali, da je babilonski kralj postavil Gedaljája za voditelja, so prišli h Gedaljáju v Micpo. Celo Netanjájev sin Jišmaél, Karéahov sin Johanán, Serajá, sin Tanhúmeta Netófčana in Maahčánov sin Jaazanjá, oni in njihovi možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedaljá je prisegel njim in njihovim možem ter jim rekel: »Ne bojte se biti služabniki Kaldejcem. Prebivajte v deželi in služite babilonskemu kralju in z vami bo dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Toda pripetilo se je v sedmem mesecu, da je prišel Jišmaél, Netanjájev sin, Elišamájev sin, iz kraljevega semena in deset mož z njim in udaril Gedaljája, da je umrl in Jude in Kaldejce, ki so bili z njim v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Vse ljudstvo, tako mali kakor veliki in poveljniki vojsk, so vstali in prišli v Egipt, kajti bali so se Kaldejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Pripetilo se je v sedemintridesetem letu ujetništva Judovega kralja Jojahína, v dvanajstem mesecu, na sedemindvajseti dan meseca, da je babilonski kralj Evíl Merodáh, v letu, ko je začel kraljevati, povzdignil glavo Judovega kralja Jojahína iz ječe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'in prijazno govoril z njim in njegov prestol postavil nad prestol kraljev, ki so bili z njim v Babilonu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'in zamenjal njegove jetniške obleke in on je nenehno jedel kruh pred njim, vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Njegova renta mu je bila dana od kralja, nenehna renta, dnevna mera za vsak dan, vse dni njegovega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enóš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenán, Mahalalél, Jered,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoh, Matuzalem, Lameh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noe, Sem, Ham in Jafet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Jafetovi sinovi: Gomer, Magóg, Madáj, Javán, Tubál, Mešeh in Tirás.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Gomerjevi sinovi: Aškenáz, Rifát in Togarmá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, '§ Javánovi sinovi: Elišá, Taršíš, Kitéjec in Dodanim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hamovi sinovi: Kuš, Micrájim, Put in Kánaan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Kuševi sinovi: Sebá, Havilá, Sabtá, Ramá in Sabtehá. Ramájeva sinova: Šebá in Dedán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kuš je zaplodil Nimróda. Ta je začel postajati mogočen na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Micrájim je zaplodil Ludima, Anamima, Lehabima, Nafthima,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrusima, Kasluhima (iz katerega so izvirali Filistejci) in Kaftoréjca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kánaan je zaplodil svojega prvorojenca Sidóna in Heta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'tudi Jebusejca, Amoréjca, Girgašéjca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hivéjca, Arkéjca, Sinéjca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvádejca, Cemaréjca in Hamatéjca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Semovi sinovi: Elám, Asúr, Arpahšád, Lud, Arám, Uc, Hul, Geter in Mešeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpahšád je zaplodil Šelá in Šelá je zaplodil Eberja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eberju sta bila rojena dva sinova. Ime prvega je bilo Peleg, ker je bila v njegovih dneh zemlja razdeljena. Ime njegovega brata je bilo Joktán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktán je zaplodil Almodáda, Šelefa, Hacarmáveta, Jeraha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'tudi Hadoráma, Uzála, Diklá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebála, Abimaéla, Šebája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofírja, Havilá in Jobába. Vsi ti so bili Joktánovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpahšád, Šelá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serúg, Nahór, Terah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram; isti je Abraham.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Abrahamovi sinovi: Izak in Izmael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'To so njihovi rodovi: Izmaelov prvorojenec Nebajót, potem Kedár, Adbeél, Mibsám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mišmá, Dumá, Masá, Hadád, Temá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetúr, Nafíš in Kedma. To so Izmaelovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Torej sinovi Abrahamove priležnice Ketúre: rodila je Zimrána, Jokšána, Medána, Midjána, Jišbáka in Šuaha. Jokšánova sinova sta: Šebá in Dedán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Midjánovi sinovi: Efá, Efer, Henoh, Abidá in Eldaá. Vsi ti so Ketúrini sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham je zaplodil Izaka. Izakova sinova: Ezav in Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Ezavovi sinovi: Elifáz, Reguél, Jeúš, Jalám in Korah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifázovi sinovi: Temán, Omár, Cefi, Gatám, Kenáz, Timná in Amálek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguélovi sinovi: Nahat, Zerah, Šamá in Mizá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seírjevi sinovi: Lotán, Šobál, Cibón, Aná, Dišón, Ecer in Dišán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotánovi sinovi: Horí, Homám; in Timna je bila Lotánova sestra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Šobálovi sinovi: Alián, Manáhat, Ebál, Šefí, in Onám. Cibónovi sinovi: Ajá in Aná.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, '§ Anájevi sinovi: Dišón. Dišónovi sinovi: Amrám, Ešbán, Jitrán in Kerán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Ecerjevi sinovi: Bilhán, Zaaván in Jakan. Dišánovi sinovi: Uc in Arán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Torej ti so kralji, ki so kraljevali v edomski deželi, preden je katerikoli kralj kraljeval nad Izraelovi otroci: Beórjev sin Bela; in ime njegovega mesta je bilo Dinhába.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Ko je bil Bela mrtev, je namesto njega zakraljeval Jobáb, Zerahov sin iz Bocre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Ko je bil Jobáb mrtev, je namesto njega zakraljeval Hušám, iz dežele Temáncev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Ko je bil Hušám mrtev, je namesto njega zakraljeval Hadád, Bedádov sin, ki je na moábskem polju udaril Midján, in ime tega mesta je bilo Avít.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Ko je bil Hadád mrtev, je namesto njega zakraljeval Samlá iz Masréke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Ko je bil Samlá mrtev, je namesto njega zakraljeval Šaúl iz Rehobóta pri reki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Ko je bil Šaúl mrtev, je namesto njega zakraljeval Ahbórjev sin Báal Hanán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Ko je bil Báal Hanán mrtev, je namesto njega zakraljeval Hadád, in ime njegovega mesta je bilo Pagú; in ime njegove žene je bilo Mehetabéla, hči Me Zahábove hčere Matréde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Tudi Hadád je umrl. Edómski vojvode so bili: vojvoda Timná, vojvoda Aliá, vojvoda Jetét,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'vojvoda Oholibáma, vojvoda Elá, vojvoda Pinón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'vojvoda Kenáz, vojvoda Temán, vojvoda Mibcár,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'vojvoda Magdiél in vojvoda Irám. To so edómski vojvode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'To so Izraelovi sinovi: Ruben, Simeon, Levi, Juda, Isahár, Zábulon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Jožef, Benjamin, Neftáli, Gad in Aser.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Judovi sinovi: Er, Onán in Šelá; ki so mu bili trije rojeni od kánaanske hčere Šue. Judov prvorojenec Er pa je bil zloben v Gospodovih očeh; in ga je usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Njegova snaha Tamara mu je rodila Pareca in Zeraha. Vseh Judovih sinov je bilo pet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Parecova sinova: Hecrón in Hamúl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Zerahovi sinovi: Zimrí, Etán, Hemán, Kalkól in Dardá. Vseh skupaj pet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Karmíjevi sinovi: Ahár, povzročevalec težav Izraelu, ki se je prekršil s prekleto stvarjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Etánovi sinovi: Azarjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Tudi sinovi Hecróna, ki so mu bili rojeni: Jerahmeél, Ram, in Kelubaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram je zaplodil Aminadába in Aminadáb je zaplodil Nahšóna, princa Judovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahšón je zaplodil Salmóna in Salmón je zaplodil Boaza');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'in Boaz je zaplodil Obéda in Obéd je zaplodil Jeseja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'in Jese je zaplodil prvorojenca Eliába in drugega Abinadába in tretjega Šimá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'četrtega Netanéla, petega Radája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'šestega Ocema, sedmega Davida;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'katerega sestri sta bili Cerúja in Abigájila. Cerújini sinovi: Abišáj, Joáb in Asaél, trije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigájila je rodila Amasá; in Amasájev oče je bil Izmaelec Jeter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Hecrónov sin Kaléb je zaplodil otroke od Azúbe, svoje žene in od Jerióte. Njeni sinovi so tile: Ješer, Šobáb in Ardón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Ko je bila Azúba mrtva, je Kaléb k sebi vzel Efráto, ki mu je rodila Hura.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur je zaplodil Uríja in Uríja je zaplodil Becaléla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potem je Hecrón šel v hčer Mahírja, očeta Gileáda, ki jo je poročil, ko je bil star šestdeset let in rodila mu je Segúba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segúb je zaplodil Jaíra, ki je imel triindvajset mest v deželi Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Od njih je vzel Gešur in Arám z Jaírovimi mesti, s Kenátom in njegovimi mesti, celó šestdeset mest. Vsi ti so pripadali sinovom Mahírja, Gileádovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, '§ Potem ko je bil Hecrón v Kaléb-efrati mrtev, mu je Hecrónova žena Abíja rodila Ašhúra, očeta Tekóe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Sinovi Hecrónovega prvorojenca Jerahmeéla so bili: prvorojenec Ram, Buná, Oren, Ocem in Ahíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerahmeél je imel še drugo ženo, ki ji je bilo ime Atára; bila je Onámova mati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Sinovi Jerahmeélovega prvorojenca Rama so bili: Máac, Jamín in Eker.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Onámova sinova sta bila: Šamáj in Jadá. In Šamájeva sinova: Nadáb in Abišúr.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Ime Abišúrjeve žene je bilo Abihájila in rodila mu je Ahbána in Molída.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadábova sinova: Seled in Apájim, toda Seled je umrl brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Apájimovi sinovi: Jiší. Jišíjev sin: Šešán. Šešánovi otroci: Ahláj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Sinova Šamájevega brata Jadája: Jeter in Jonatan: in Jeter je umrl brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Jonatanova sinova: Pelet in Zazá. To so bili Jerahmeélovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Torej Šešán ni imel sinov, temveč hčere. Šešán je imel služabnika, Egipčana, katerega ime je bilo Jarhá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Šešán je dal svojo hčer svojemu služabniku Jarháju za ženo in rodila mu je Atája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Atáj je zaplodil Natána in Natán je zaplodil Zabáda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'in Zabád je zaplodil Eflála in Eflál je zaplodil Obéda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'in Obéd je zaplodil Jehúja in Jehú je zaplodil Azarjája');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'in Azarjá je zaplodil Heleca in Helec je zaplodil Elasája');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'in Elasáj je zaplodil Sismája in Sismáj je zaplodil Šalúma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'in Šalúm je zaplodil Jekamjája in Jekamjáj je zaplodil Elišamája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Torej sinovi Jerahmeélovega brata Kaléba so bili njegov prvorojenec Meša, ki je bil oče Zifov; in sinovi Marešá, očeta Hebróna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebrónovi sinovi: Korah, Tapúah, Rekem in Šemaá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Šemaá je zaplodil Rahama, Jorkoámovega očeta in Rekem je zaplodil Šamája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Šamájev sin je bil Maón, in Maón je bil Bet Curov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Kalébova priležnica Efá je rodila Harána, Mocája in Gazéza; in Harán je zaplodil Gazéza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Jahdájevi sinovi so: Regem, Jotám, Gešán, Pelet, Efá in Šáaf.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Kalébova priležnica Maáha je rodila Šeberja in Tirhanája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Rodila je tudi Šáafa, očeta Madmanája, Ševája, očeta Mahbenája in očeta Gíbee: in Kalébova hči je bila Ahsa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'To so bili sinovi Hurovega sina Kaléba, Efrátinega prvorojenca: Šobál, oče Kirját Jearíma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salmón, oče Betlehema, Haríf, oče Bet Gadêrja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Šobál, oče Kirját Jearíma, je imel sinove: Haroe in polovica Manáhatovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Družine Kirját Jearíma: Jéterjevci, Putéjci, Šuméjci in Mišraíti; iz katerih so izšli Corčani in Eštaólci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salmónovi sinovi: Betlehem, Netófčani, Atrót, Joábova hiša in polovica Manáhatovcev in Zorovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Družine pisarjev, ki so prebivale pri Jabécu: Tiratéjci, Šimatéjci in Suhéjci. Ti so Kenéjci, ki so prišli iz Hamáta, očeta Rehábove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Torej to so bili Davidovi sinovi, ki so se mu rodili v Hebrónu: prvorojenec Amnón od Jezreélke Ahinóam; drugi Daniel od Karmelčanke Abigájile;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'tretji Absalom, sin Maáhe, hčere gešurskega kralja Talmája; četrti Adoníja, sin Hagíte;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'peti Šefatjá od Abitále; šesti Jitreám od njegove žene Egle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Teh šest se mu je rodilo v Hebrónu in tam je kraljeval sedem let in šest mesecev. V Jeruzalemu pa je kraljeval triintrideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ti so se mu rodili v Jeruzalemu: Šimá, Šobáb, Natán in Salomon, štirje od Batšúe, Amiélove hčere;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'tudi Jibhár, Elišamá, Elifélet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nefeg, Jafíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elišamá, Eljadá in Elifélet, devet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'To so bili vsi Davidovi sinovi, poleg sinov priležnic in njihove sestre Tamare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomonov sin je bil Rehabám, njegov sin Abíja, njegov sin Asá, njegov sin Józafat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'njegov sin Jorám, njegov sin Ahazjá, njegov sin Joáš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'njegov sin Amacjá, njegov sin Azarjá, njegov sin Jotám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'njegov sin Aház, njegov sin Ezekíja, njegov sin Manáse,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'njegov sin Amón in njegov sin Jošíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Jošíjevi sinovi so bili: prvorojenec Johanán, drugi Jojakím, tretji Sedekíja in četrti Šalúm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Jojakímova sinova: njegov sin Jehoníja in njegov sin Sedekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Jehoníjevi sinovi: Asír, njegov sin Šaltiél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'tudi Malkirám, Pedajá, Šenacár, Jekamjá, Hošamá in Nedabjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedajájeva sinova sta bila Zerubabél in Šimí. Zerubabélovi sinovi: Mešulám, Hananjá, njuna sestra Šelomíta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Hašubá, Ohel, Berehjá, Hasadjá in Jušáb Hesed, pet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, '§ Hananjájeva sinova: Pelatjája in Ješajá. Refajájevi sinovi, Arnánovi sinovi, Obadjájevi sinovi, Šehanjájevi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Šehanjájevi sinovi: Šemajá; in Šemajájevi sinovi: Hatúš, Jigál, Baríah, Nearjá in Šafát, šest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearjájevi sinovi: Eljoenáj, Ezekíja in Azrikám, trije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoenájevi sinovi so bili: Hodavjá, Eljašíb, Pelajá, Akúb, Johanán, Delajá in Ananí, sedem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Judovi sinovi: Parec, Hecrón, Karmí, Hur in Šobál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reajá, sin Šobála, je zaplodil Jahata. Jahat je zaplodil Ahumája in Lahada. To so družine Corčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ti so bili od očeta Etáma: Jezreél, Jišmá in Jidbáš in ime njihove sestre je bilo Haclelpóni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Penuél, oče Gedórja in Ecer, oče Hušája. To so sinovi Hura, Efrátinega prvorojenca, očeta Betlehema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ašhúr, oče Tekóe, je imel dve ženi, Helo in Naáro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naára mu je rodila Ahuzáma, Heferja, Timníja in Ahaštaríja. Ti so bili Naárini sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Sinovi Hele so bili Ceret, Cohar in Etnán.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Koc je zaplodil Anúba in Cobebá in družine Harúmovega sina Aharhéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabéc je bil bolj častitljiv kakor njegovi bratje in njegova mati je njegovo ime imenovala Jabéc, rekoč: »Ker sem ga rodila z bridkostjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jabéc je klical k Izraelovemu Bogu, rekoč: »Oh da bi me ti resnično blagoslovil in povečal moj kraj in da bi bila tvoja roka lahko z menoj in da bi me varoval pred zlom, da me ta ne bi žalostil!« In Bog mu je zagotovil to, kar je zahteval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kelúb, brat Šuaha, je zaplodil Mehírja, ki je bil oče Eštóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eštón je zaplodil Betrafá, Paséaha in Tehiná, očeta Ir Naháša. To so možje iz Rehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kenázova sinova: Otniél in Serajá. Otniélovi sinovi: Hatát.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotáj je zaplodil Ofrá. Serajá je zaplodil Joába, očeta doline Ge Haraším, kajti bili so rokodelci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Sinovi Jefunéjevega sina Kaléba: Iru, Elá in Náam. Elájevi sinovi: celo Kenáz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehalelélovi sinovi: Zif, Zifá, Tirjá in Asarél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Sinovi Ezra so bili: Jeter, Mered, Efer in Jalón. In ona je rodila Mirjáma, Šamája in Jišbáha, očeta Eštemóa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, '§ Njegova žena Jehudija je rodila Jereda, Gedórjevega očeta in Heberja, Sohójevega očeta in Jekutiéla, Zanóahovega očeta. Vsi ti so sinovi faraonove hčere Bitije, ki jo vzel Mered.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Sinova njegove žene Hodijáje, Nahamove sestre, Keílin oče Garmít in Maahčán Eštemóa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, '§ Šimónovi sinovi so bili Amnón, Riná, Ben-Hanán in Tilón. Jišíjeva sinova sta bila Zohét in Ben Zohét.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Sinovi Judovega sina Šelája so bili Er, Lehájev oče in Ladá, Marešájev oče in družine iz hiše tistih, ki so izdelovali tanko laneno platno, iz hiše Ašbéa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, '§ in Jokím, možje iz Kozébe, Joáš in Saráf, ki so imeli gospostvo v Moábu in Jashubi–lehemu. In to so starodavne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, '§ Ti so bili lončarji in tisti, ki so prebivali med sadikami in ograjami. Tam so zaradi svojega dela prebivali s kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeonovi sinovi so bili Nemuél, Jamín, Jaríb, Zerah in Šaúl;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'njegov sin Šalúm, njegov sin Mibsám, njegov sin Mišmá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Mišmájevi sinovi: njegov sin Hamuél, njegov sin Zakúr in njegov sin Šimí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Šimí je imel šestnajst sinov in šest hčera, toda njegovi bratje niso imeli veliko otrok niti se vse njihove družine niso množile, kakor Judovi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Prebivali so pri Beeršébi, Moládi, Hacár Šuálu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'pri Bilhi, pri Ecemu, pri Toladu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'pri Betuélu, pri Hormi, pri Ciklágu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'pri Bet Markabótu, pri Hacár Susímu, pri Bet Biríju in pri Šaarájimu. To so bila njihova mesta do Davidovega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, '§ Njihove vasi so bile Etám, Ajin, Rimón, Tohen in Ašán, pet mest');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'in vse njihove vasi, ki so bile naokoli istih mest, do Báala. To so bila njihova prebivališča in njihov rodovnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Mešobáb, Jamléh, Amacjájev sin Jošá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joél, Jehú, sin Jošibjája, sin Serajája, sin Asiéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenáj, Jaakóba, Ješohája, Asajá, Adiél, Jesimiél, Benajá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Zizá, sin Šifíja, sinú Alóna, sinú Jedajája, sinú Šimríja, sinú Šemajája;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'ti, omenjeni po svojih imenih, so bili princi v svojih družinah in hiše njihovih očetov so se silno povečale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Šli so k vhodu Gedórja, celó do vzhodne strani doline, da poiščejo pašnik za svoje trope.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Našli so obilen in dober pašnik in dežela je bila prostrana, tiha in mirna, kajti tisti iz Hama so tam prebivali od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'In tisti, zapisani po imenu, so prišli v dneh Judovega kralja Ezekíja in udarili njihove šotore in prebivališča, ki so bila najdena tam in jih popolnoma uničili do današnjega dne in prebivali so namesto njih, ker je bil tam pašnik za njihove trope.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Nekateri izmed njih, celo izmed Simeonovih sinov, petsto mož, so odšli na gorovje Seír, za svoje poveljnike pa so imeli Pelatjája, Nearjá, Refajá, Uziéla, Jišíjeve sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Udarili so preostanek Amalečanov, ki so pobegnili in tam prebivajo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Torej sinovi Izraelovega prvorojenca Rubena, (kajti on je bil prvorojenec; toda, ker je omadeževal posteljo svojega očeta, je bila njegova pravica prvorojenstva dana sinovoma Izraelovega sina Jožefa; in rodovnik ni štet po pravici prvorojenstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Kajti Juda je prevladal nad svojimi brati in od njega je prišel glavni vladar; toda pravica prvorojenstva je bila Jožefova.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Sinovi, pravim, od Izraelovega prvorojenca Rubena so bili: Hénoh, Palú, Hecrón in Karmí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joélovi sinovi: njegov sin Šemajá, njegov sin Gog, njegov sin Šimí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'njegov sin Miha, njegov sin Reajá, njegov sin Báal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'njegov sin Beerá, ki ga je asirski kralj Tiglát Pilnéser, odvedel ujetega. On je bil princ Rubenovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Njegovi bratje po njihovih družinah, ko je bil preštet rodovnik njihovih rodov, so bili vodja Jeiél, Zeharjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, sin Azáza, sinú Šemaá, sinú Joéla, ki je prebival v Aroêrju, celo do Nebója in Báal Meóna;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'in proti vzhodu je naseljeval do vstopa v divjino, od reke Evfrat, ker je bila njihova živina pomnožena v deželi Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'V Savlovih dneh so se bojevali s Hagríjevci, ki so padli po njihovi roki in prebivali so v njihovih šotorih po vsej vzhodni deželi Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gadovi otroci so prebivali nasproti njih, v deželi Bašán do Salhe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'vodja Joél, naslednji Šafám, Janáj in Šafát v Bašánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Njihovi bratje iz hiše njihovih očetov so bili: Mihael, Mešulám, Šeba, Joráj, Jakán, Ziá in Heber, sedem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ti so otroci Abihájila, sinú Huríja, sinú Jaróaha, sinú Gileáda, sinú Mihaela, sinú Ješišája, sinú Jahdója, Buzovega sina;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahí, sin Abdiéla, Guníjevega sina, vodja hiše njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Prebivali so v Gileádu, v Bašánu in v njihovih mestih in v vseh predmestjih Šaróna, na njihovih mejah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Vsi ti so bili šteti po rodovnikih v dneh Judovega kralja Jotáma in v dneh Izraelovega kralja Jerobeáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Sinovi Rubena, Gádovcev in polovice Manásejevega rodu izmed hrabrih mož, mož zmožnih, da nosijo ščit in meč in da streljajo z lokom in veščih v vojni, je bilo štiriinštirideset tisoč sedemsto šestdeset, ki so odšli ven na vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Bojevali so se s Hagríjevci, z Jetúrjem, Nafíšem in Nodábom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Pomagano jim je bilo zoper njih in Hagríjevci so bili izročeni v njihovo roko in vsi tisti, ki so bili z njimi; kajti v bitki so vpili k Bogu in izprošen je bil od njih, ker so svoje zaupanje položili vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Odvzeli so njihovo živino; od njihovih kamel petdeset tisoč in od ovc dvesto petdeset tisoč in od oslov dva tisoč in od ljudi sto tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Kajti tam je padlo mnogo umorjenih, ker je bila vojna od Boga. In namesto njih so tam prebivali do ujetništva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Otroci polovice Manásejevega rodu so prebivali v deželi. Množili so se od Bašána do Báal Hermona in Senírja in do gore Hermon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Ti so bili poglavarji hiše njihovih očetov, celo Efer, Jiší, Eliél, Azriél, Jeremija, Hodavijá in Jahdiél, močni junaški možje, slavni možje in poglavarji hiše njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Pregrešili so se zoper Boga svojih očetov in se odšli vlačugat za bogovi ljudstva dežele, ki jih je Bog uničil pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Izraelov Bog pa je razvnel duha asirskega kralja Pula in duha asirskega kralja Tiglát Pilnéserja in ta jih je odvedel proč, celo Rubenovce, Gádovce in polovico Manásejevega rodu in jih privedel v Haláh, Habór, Haro in k reki Gozán do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Lévijevi sinovi: Geršón, Kehát in Merarí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Amrámovi otroci: Aron, Mojzes in Mirjam. Tudi Aronovi sinovi: Nadáb, Abihú, Eleazar in Itamár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar je zaplodil Pinhása, Pinhás je zaplodil Abišúa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'in Abišúa je zaplodil Bukíja in Bukí je zaplodil Uzíja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'in Uzí je zaplodil Zerahjá in Zerahjá je zaplodil Merajóta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajót je zaplodil Amarjá in Amarjá je zaplodil Ahitúba');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'in Ahitúb je zaplodil Cadóka in Cadók je zaplodil Ahimáaca');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'in Ahimáac je zaplodil Azarjája in Azarjá je zaplodil Johanána');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'in Johanán je zaplodil Azarjá (on je ta, ki je opravljal duhovniško službo v templju, ki ga je Salomon zgradil v Jeruzalemu);');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarjá je zaplodil Amarjá in Amarjá je zaplodil Ahitúba');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'in Ahitúb je zaplodil Cadóka in Cadók je zaplodil Šalúma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'in Šalúm je zaplodil Hilkijá in Hilkijá je zaplodil Azarjá');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'in Azarjá je zaplodil Serajája in Serajá je zaplodil Jocadáka');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'in Jocadák je odšel v ujetništvo, ko je Gospod po Nebukadnezarjevi roki odvedel Juda in Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Lévijevi sinovi: Geršóm, Kehát in Merarí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'To sta imeni Geršómovih sinov: Libni in Šimí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Kehátovi sinovi so bili: Amrám, Jichár, Hebrón in Uziél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Meraríjeva sinova: Mahlí in Muší. To so družine Lévijevcev glede na njihove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Od Geršóma: njegov sin Libni, njegov sin Jahat, njegov sin Zimá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'njegov sin Joáh, njegov sin Idó, njegov sin Zerah in njegov sin Jeatraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Kehátovi sinovi: njegov sin Aminadáb, njegov sin Korah, njegov sin Asír,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'njegov sin Elkaná, njegov sin Abiasáf, njegov sin Asír,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'njegov sin Tahat, njegov sin Uriél, njegov sin Uzíjah in njegov sin Šaúl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Elkanájeva sinova: Amasáj in Ahimót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Glede Elkaná, Elkanájevi sinovi: njegov sin Cuf, njegov sin Nahat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'njegov sin Eliáb, njegov sin Jerohám in njegov sin Elkaná.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Samuelova sinova: prvorojenec Vašni in Abíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Meraríjevi sinovi: Mahlí, njegov sin Libni, njegov sin Šimí, njegov sin Uzá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'njegov sin Šimá, njegov sin Hagijá in njegov sin Asajá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'To so tisti, ki jih je David postavil nad službo pesmi v Gospodovi hiši, potem ko je skrinja imela počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Služili so pred prebivališčem šotorskega svetišča skupnosti s petjem, dokler ni Salomon zgradil Gospodove hiše v Jeruzalemu; potem so čakali na svojo službo glede na svoj red.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ti so tisti, ki so čakali s svojimi otroci. Izmed sinov Kehátovcev: pevec Hemán, sin Joéla, sinú Šemuéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'sinú Elkanája, sinú Jeroháma, sinú Eliéla, sinú Tohuja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'sinú Cufa, sinú Elkanája, sinú Mahata, sinú Amasája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'sinú Elkaná, sinú Joéla, sinú Azarjá, sinú Cefanjája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'sinú Tahata, sinú Asírja, sinú Abiasáfa, sinú Koraha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'sinú Jichárja, sinú Keháta, sinú Izraelovega sina Lévija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Njegov brat Asáf, ki je stal na njegovi desnici, celo Asáf, sin Berehjája, sinú Šimája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'sinú Mihaela, sinú Baasejája, sinú Malkijája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'sinú Etníja, sinú Zeraha, sinú Adajá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'sinú Etána, sinú Zimája, sinú Šimíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'sinú Jahata, sinú Geršóma, Lévijevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Njihovi bratje, Meraríjevi sinovi so stali na levi roki: Etán, sin Kišijá, sinú Abdíja, sinú Malúha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'sinú Hašabjája, sinú Amacjá, sinú Hilkijája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'sinú Amcíja, sinú Baníja, sinú Šemerja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'sinú Mahlíja, sinú Mušíja, sinú Meraríja, Lévijevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Tudi njihovi bratje Lévijevci so bili določeni k vsem vrstam služb šotorskega svetišča Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Toda Aron in njegovi sinovi so darovali na oltarju žgalne daritve in na kadilnem oltarju in bili so določeni za vse delo najsvetejšega prostora in da opravljajo spravo za Izrael, glede na vse, kar je zapovedal Božji služabnik Mojzes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'To so Aronovi sinovi: njegov sin Eleazar, njegov sin Pinhás, njegov sin Abišúa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'njegov sin Bukí, njegov sin Uzí, njegov sin Zerahjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'njegov sin Merajót, njegov sin Amarjá, njegov sin Ahitúb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'njegov sin Cadók in njegov sin Ahimáac.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Torej to so njihova bivališča po vseh njihovih gradovih in njihovih pokrajinah od Aronovih sinov, od družin Kehátovcev; kajti žreb je bil njihov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Dali so jim Hebrón v Judovi deželi in njegova predmestja okoli njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Toda polja od mesta in njegove vasi so dali Jefunéjevemu sinu Kalébu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Aronovim sinovom so dali Judova mesta, namreč Hebrón, mesto zatočišča, Libno s svojimi predmestji, Jatír, Eštemóa s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilón s svojimi predmestji, Debír s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Ašán s svojimi predmestji in Bet Šemeš s svojimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Od Benjaminovega rodu: Geba s svojimi predmestji, Alémet s svojimi predmestji in Anatót s svojimi predmestji. Vseh njihovih mest po njihovih družinah je bilo trinajst mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Kehátovim sinovom, ki so ostali od družine tega rodu, so bila z žrebom dana mesta polovice rodu, namreč od polovice Manásejevega rodu, deset mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Geršómovim sinovom po njihovih družinah od Isahárjevega rodu, od Aserjevega rodu, od Neftálijevega rodu in od Manásejevega rodu v Bašánu, trinajst mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Meraríjevim sinovim je bilo z žrebom dano, po vseh njihovih družinah, od Rubenovega rodu, od Gadovega rodu in od Zábulonovega rodu dvanajst mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Izraelovi otroci so dali Lévijevcem ta mesta z njihovimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Z žrebom so od rodu Judovih otrok, od rodu Simeonovih otrok in od rodu Benjaminovih otrok dali ta mesta, ki so imenovana po njihovih imenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Preostanek družin Kehátovih sinov je dobil mesta svojih pokrajin od Efrájimovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Od zavetnih mest so jim dali Sihem na gori Efrájim z njegovimi predmestji; dali so tudi Gezer s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeám s svojimi predmestji, Bet Horón s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalón s svojimi predmestji in Gat Rimón s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'od polovice Manásejevega rodu: Anêr s svojimi predmestji, Bileam s svojimi predmestji za družino preostanka Kehátovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Geršómovim sinovom je bilo dano od družine polovice Manásejevega rodu Golán v Bašánu s svojimi predmestji in Aštarót s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'od Isahárjevega rodu: Kedeš s svojimi predmestji, Daberát s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramót s svojimi predmestji in Anem s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'od Aserjevega rodu: Mišál s svojimi predmestji, Abdón s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukok s svojimi predmestji in Rehób s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'od Neftálijevega rodu: Kedeš v Galileji s svojimi predmestji, Hamón s svojimi predmestji in Kirjatájim s svojimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Preostanku Meraríjevih otrok je bilo dano od Zábulonovega rodu: Rimón s svojimi predmestji in Tabor s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'in na drugi strani Jordana, pri Jerihi na vzhodni strani Jordana jim je bilo dano od Rubenovega rodu: Becer v divjini s svojimi predmestji, Jahac s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'tudi Kedemót s svojimi predmestji in Mefáat s svojimi predmestji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'od Gadovega rodu: Ramót v Gileádu s svojimi predmestji, Mahanájim s svojimi predmestji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hešbón s svojimi predmestji in Jazêr s svojimi predmestji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Torej Isahárjevi sinovi so bili: Tolá, Puvá, Jašúb in Šimrón, štirje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Tolájevi sinovi: Uzí, Refajá, Jeriél, Jahmáj, Jibsám in Šemuél, poglavarji hiše njihovega očeta, namreč od Tolája. Bili so hrabri mogočni možje v svojih rodovih, katerih število je bilo v Davidovih dneh dvaindvajset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Uzíjevi sinovi: Jizrahjá; in Jizrahjájevi sinovi: Mihael, Obadjá, Joél in Jišijá, pet. Vsi izmed njih vodilni možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Z njimi, po njihovih rodovih, po hiši njihovih očetov, so bile čete vojakov za vojno, šestintrideset tisoč mož, kajti imeli so veliko žena in sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Njihovi bratje med vsemi Isahárjevimi družinami so bili hrabri mogočni možje, prešteti po vseh njihovih rodovnikih, sedeminosemdeset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjaminovi sinovi: Bela, Beher in Jediaél, trije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Belovi sinovi: Ecbón, Uzí, Uziél, Jerimót in Ir, pet; poglavarji hiše njihovih očetov, močni junaški možje; prešteti so bili po njihovih rodovnikih, dvaindvajset tisoč štiriintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Beherjevi sinovi: Zemirá, Joáš, Eliézer, Eljoenáj, Omri, Jerimót, Abíja, Anatót in Alémet. Vsi ti so Beherjevi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Njihovo število po njihovih rodovnikih, po njihovih rodovih, poglavarjev hiš njihovih očetov, močnih junaških mož, je bilo dvajset tisoč dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Tudi Jediaélovi sinovi: Bilhán. Bilhánovi sinovi: Jeúš, Benjamin, Ehúd, Kenaaná, Zetán, Taršíš in Ahišáhar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Vseh teh Jediaélovih sinov, po poglavarjih njihovih očetov, močnih junaških mož, je bilo sedemnajst tisoč dvesto vojakov, primernih, da gredo ven na vojsko in bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Tudi Šupím in Hupím, Irova otroka in Huším, Ahêrjevi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Neftálijevi sinovi: Jahaciél, Guní, Jecer in Šalúm, Bilhini sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manásejevi sinovi: Asriél, ki mu je rodila (toda njegova arámska priležnica je rodila Mahírja, Gileádovega očeta;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'in Mahír je vzel za ženo sestro Hupíma in Šupíma, čigar sestri je bilo ime Maáha) in ime drugemu je bilo Celofhád; in Celofhád je imel hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Mahírjeva žena Maáha je rodila sina in njegovo ime imenovala Pereš; in ime njegovega brata je bilo Šereš; njegova sinova pa sta bila Ulám in Rekem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Ulámovi sinovi: Bedán. To so bili sinovi Gileáda, sinú Mahírja, Manásejevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Njegova sestra Moléheta je rodila Išhóda, Abiézeja in Mahlája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Šemidájevi sinovi so bili: Ahján, Šehem, Likhí in Aniám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Efrájimovi sinovi: Šutélah, njegov sin Bered, njegov sin Tahat, njegov sin Eladá in njegov sin Tahat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'njegov sin Zabád, njegov sin Šutélah, Ecer in Elád, ki so jih usmrtil možje iz Gata, ki so bili rojeni v tej deželi, ker so prišli dol, da odvzamejo njihovo živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Njihov oče Efrájim je mnogo dni žaloval in prišli so njegovi bratje, da ga tolažijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Ko je odšel k svoji ženi, je spočela, rodila sina in njegovo ime je imenoval Berijá, ker je z njegovo hišo šlo slabo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, '(Njegova hči je bila Šeêra, ki je zgradila spodnji in zgornji Bet Horón ter Uzén Šeêro.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Refah je bil njegov sin, tudi Rešef in njegov sin Telah in njegov sin Tahan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'njegov sin Ladán, njegov sin Amihúd, njegov sin Elišamá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'njegov sin Non in njegov sin Ješua.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Njihove posesti in prebivališča so bila Betel in njegova mesta, proti vzhodu Naára, proti zahodu Gezer s svojimi mesti; tudi Sihem in njegova mesta, do Gaze in njenih mest;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'in pri mejah Manásejevih otrok, Bet Šeán in njegova mesta, Taanáh in njegova mesta, Megída in njegova mesta ter Dor in njegova mesta. V teh so prebivali otroci Izraelovega sina Jožefa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Aserjevi sinovi: Jimnáh, Jišvá, Jišví, Berijá in njihova sestra Sêraha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berijájeva sinova: Heber in Malkiél, ki je Birzájitov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber je zaplodil Jafléta, Šomerja, Hotáma in njihovo sestro Šuo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Jaflétovi sinovi: Pasáh, Bimhál in Ašvát. To so Jaflétovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Šemerjevi sinovi: Ahí, Rohgá, Hubá in Arám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Sinovi njegovega brata Heléma: Cofah, Jimná, Šeleš in Amál.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Cofahovi sinovi: Suah, Harnéfer, Šuál, Berí, Jimrá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Becer, Hod, Šamá, Šilšá, Jitrán in Beerá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jeterjevi sinovi: Jefuné, Pispá in Ará.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ulájevi sinovi: Aráh, Haniél in Ricjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Vsi ti so bili Aserjevi otroci, poglavarji njihovih očetnih hiš, izbrani in močni junaški možje, vodje princev. Število tistih, ki so bili po rodovniku zmožni za vojno in bitko, je bilo šestindvajset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Torej Benjamin je zaplodil svojega prvorojenca Bela, drugega Ašbéla in tretjega Ahráha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'četrtega Nohá in petega Rafá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Belovi sinovi so bili: Adár, Gerá, Abihúd,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abišúa, Naamán, Ahóah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gerá, Šefufán in Hurám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Ti so Ehúdovi sinovi. To so poglavarji očetov prebivalcev Gebe in odpeljali so jih v Manáhat:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naamán, Ahíja in Gerá, le-ta jih je pregnal in zaplodil Uzá in Ahihúda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Šaharájim je zaplodil otroke v moábski deželi, potem ko ju je poslal proč; Hušíma in Baára sta bili njegovi ženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Svoji ženi Hódeši je zaplodil Jobába, Cibjá, Meša, Malkáma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeúca, Sahejá in Mirmá. To so bili njegovi sinovi, poglavarji očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'S Hušímo je zaplodil Abitúba in Elpáala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpáalovi sinovi: Eber, Mišám in Šamed, ki je zgradil Onó in Lod z njegovimi mesti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'tudi Berijá in Šemaá, ki sta bila poglavarja očetov izmed prebivalcev Ajalóna, ki sta pregnala prebivalce Gata:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Ahjó, Šašák, Jeremót,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadjá, Arád, Ader,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mihael, Jišpá in Johá, Berijájevi sinovi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'in Zebadjá, Mešulám, Hizkí, Heber,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'tudi Jišmeráj, Jizlijá, Jobáb, Elpáalovi sinovi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'in Jakím, Zihrí, Zabdí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienáj, Celetáj, Eliél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adajáj, Berajá in Šimrát, Šimíjevi sinovi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'in Jišpán, Eber, Eliél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdón, Zihrí, Hanán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananjá, Elám, Antotijá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdejá in Penuél, Šašákovi sinovi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'in Šamšeráj, Šeharjá, Ataljá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaarešjá, Elijá in Zihrí, Jerohámovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'To so bili poglavarji izmed očetov, po svojih rodovih, vodilni možje. Ti so prebivali v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Pri Gibeónu je prebival oče Gibeóncev, čigar ženi je bilo ime Maáha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Njegov prvorojenec Abdón, Cur, Kiš, Báal, Nadáb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedór, Ahjó in Zeher.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklót je zaplodil Šimája. Tudi ti so s svojimi brati prebivali nasproti njih v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner je zaplodil Kiša, Kiš je zaplodil Savla, Savel je zaplodil Jonatana, Malkišúa, Abinadába in Ešbáala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonatanov sin je bil Meríb Báal in Meríb Báal je zaplodil Miha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Mihovi sinovi so bili Pitón, Meleh, Taréa in Aház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Aház je zaplodil Jeoadája; in Jeoadá je zaplodil Alémeta, Azmáveta in Zimríja; Zimrí je zaplodil Mocá');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'in Mocá je zaplodil Binája; njegov sin je bil Rafája, njegov sin Elasáj, njegov sin Acél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Acél je imel šest sinov, katerih imena so ta: Azrikám, Bohrú, Jišmaél, Šearjá, Obadjá in Hanán. Vsi ti so bili Acélovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Sinovi njegovega brata Ešeka so bili njegov prvorojenec Ulám, drugi Jeúš in tretji Elifélet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Ulámovi sinovi so bili močni junaški možje, lokostrelci in imel je mnogo sinov in vnukov, sto petdeset. Vsi ti so Benjaminovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Tako je bil ves Izrael preštet po rodovnikih. Glej, zapisani so bili v knjigo Izraelovih in Judovih kraljev; [tisti] ki so bili odvedeni v Babilon zaradi svojega prestopka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Torej prvi prebivalci, ki so prebivali na svojih posestvih, v svojih mestih, so bili Izraelci, duhovniki, Lévijevci in Netinimci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'V Jeruzalemu so od Judovih, Benjaminovih, Efrájimovih otrok in Manáseja prebivali:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utáj, sin Amihúda, sinú Omrija, sinú Imríja, Baníjevega sina, izmed otrok Judovega sina Pareca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Izmed Šilčanov: prvorojenec Asajá in njegovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Izmed Zerahovih sinov: Jeuél in njihovi bratje, šeststo devetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Izmed Benjaminovih sinov: Salú, sin Mešuláma, sinú Hodavijá, Senuájevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Jerohámov sin Jibnejá in Elá, sin Uzíja, Mihríjevega sina in Mešulám, sin Šefatjája, sinú Reguéla, Jibnijájevega sina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'in njihovi bratje, glede na svoje rodove, devetsto šestinpetdeset. Vsi ti možje so bili vodje očetov v hiši svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Izmed duhovnikov: Jedajája, Jojaríb, Jahín,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarjá, sin Hilkijá, sinú Mešuláma, sinú Cadóka, sinú Merajóta, Ahitúbovega sina, poveljnika Božje hiše;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'in Adajá, sin Jeroháma, sinú Pašhúrja, Malkijájevega sina in Masáj, sin Adiéla, sinú Jahzêraja, sinú Mešuláma, sinú Mešilemóta, Imêrjevega sina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'ter njihovi bratje, poglavarji hiše svojih očetov, tisoč sedemsto šestdeset, zelo sposobni možje za službo Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Izmed Lévijevcev: Šemajá, sin Hašuba, sinú Azrikáma, sinú Hašabjája izmed Meraríjevih sinov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakár, Hereš, Galál, Matanjá, sin Miha, sinú Zihríja, Asáfovega sina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadjá, sin Šemajája, sinú Galála, Jedutúnovega sina in Berehjá, sin Asája, Elkanájevega sina, ki je prebival v vaseh Netófčanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Vratarji so bili Šalúm, Akúb, Talmón, Ahimán in njihovi bratje; Šalúm je bil vodja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'ki so do takrat čakali pri kraljevih velikih vratih proti vzhodu; bili so vratarji v družbi Lévijevih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Šalúm, sin Koréja, sinú Abiasáfa, Kórahovega sina in njegovi bratje iz hiše njegovega očeta, Kórahovci, so bili nad delom službe, čuvaji velikih vrat šotorskega svetišča. Njihovi očetje, nad Gospodovo vojsko, pa so bili čuvaji vhoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Eleazarjev sin Pinhás je bil v preteklem času vladar nad njimi in Gospod je bil z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Mešelemjájev sin Zeharjá je bil vratar vrat šotorskega svetišča skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Vseh teh, ki so bili izbrani, da bodo vratarji v velikih vratih, je bilo dvesto dvanajst. Ti so bili prešteti po svojem rodovniku v svojih vaseh, ki sta jih David in videc Samuel odredila v njihovo določeno službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Tako so oni in njihovi otroci imeli nadzor velikih vrat Gospodove hiše, namreč hiše šotorskega svetišča, po stražah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'V štirih četrtinah so bili vratarji, proti vzhodu, zahodu, severu in jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Njihovi bratje, ki so bili v svojih vaseh naj bi z njimi prihajali po sedmih dneh, od časa do časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Kajti ti Lévijevci, štirje glavni vratarji, so bili v svoji določeni službi in so bili nad sobami in zakladnicami Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Prenočevali so naokoli Božje hiše, ker je bila nad njimi zadolžitev in njim je pripadalo vsakodnevno jutranje odpiranje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Nekateri izmed njih so imeli zadolžitev strežniških posod, da bi jih prinašali noter in ven po številu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Tudi nekateri izmed njih so bili določeni, da nadzirajo posode, vse svetiščne priprave, fino moko, vino, olje, dišave in kadila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Nekateri izmed sinov duhovnikov so iz dišav izdelovali mazilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matitjá, eden izmed Lévijevcev, ki je bil prvorojenec Kórahovca Šalúma, je imel določeno službo nad stvarmi, ki so bile narejene v ponvah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Ostali izmed njihovih bratov, izmed Kehátovih sinov, so bili nad hlebi navzočnosti, da so jih pripravljali vsak šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'To so pevci, glavni izmed Lévijevih očetov, ki so prosti ostali v sobah, kajti pri tem delu so bili zaposleni dan in noč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ti glavni Lévijevi očetje so bili vodje po svojih rodovih; ti so prebivali pri Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'V Gibeónu je prebival Jehiél, oče Gibeóncev, čigar ženi je bilo ime Maáha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'in njegov prvorojenec Abdón, potem Cur, Kiš, Báal, Ner, Nadáb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedór, Ahjó, Zeharjá in Miklót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklót je zaplodil Šimá. In tudi ti so prebivali s svojimi brati pri Jeruzalemu, nasproti svojih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner je zaplodil Kiša, Kiš je zaplodil Savla, Savel je zaplodil Jonatana, Malkišúa, Abinadába in Ešbáala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonatanov sin je bil Meríb Báal, in Meríb Báal je zaplodil Miha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Mihovi sinovi so bili Pitón, Meleh, Tahréa in Aház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Aház je zaplodil Jara in Jara je zaplodil Alémeta, Azmáveta in Zimríja in Zimrí je zaplodil Mocá');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'in Mocá je zaplodil Binája, njegov sin Refajá, njegov sin Elasáj, njegov sin Acél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Acél je imel šest sinov, katerih imena so ta: Azrikám, Bohrú, Jišmaél, Šearjá, Obadjá in Hanán; ti so bili Acélovi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Torej Filistejci so se borili zoper Izrael, in Izraelovi možje so pobegnili pred Filistejci in umorjeni popadali na gori Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Filistejci so zasledovali Savla in njegove sinove; in Filistejci so usmrtili Jonatana, Abinadába in Malkišúa, Savlove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Bitka je postala huda zoper Savla in lokostrelci so ga zadeli in bil je ranjen od lokostrelcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Potem je Savel rekel svojemu nosilcu bojne opreme: »Izvleci svoj meč in me prebodi z njim; da ne bi prišli ti neobrezanci in me zlorabili.« Njegov nosilec bojne opreme pa ni hotel, kajti bil je hudo prestrašen. Tako je Savel vzel meč in se vrgel nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Ko je njegov nosilec bojne opreme videl, da je bil Savel mrtev, se je tudi sam prav tako vrgel na meč in umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tako je umrl Savel in njegovi trije sinovi in vsa njegova hiša je skupaj umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Ko so vsi možje iz Izraela, ki so bili v dolini, videli, da so oni pobegnili in da so bili Savel in njegovi sinovi mrtvi, potem so zapustili svoja mesta in pobegnili, in prišli so Filistejci ter prebivali v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Pripetilo se je naslednji dan, ko so prišli Filistejci, da oropajo umorjene, da so našli Savla in njegove sinove padle na gori Gilbói.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Ko so ga slekli do golega, so vzeli njegovo glavo, njegovo bojno opremo in [to] poslali naokoli po deželi Filistejcev, da odnesejo novice njihovim malikom in ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Njegovo bojno opremo so položili v hišo svojih bogov, njegovo glavo pa so pritrdili v Dagónovem templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Ko so vsi Jabéš Gileádovci slišali vse, kar so Filistejci storili Savlu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'so vstali vsi hrabri možje in odnesli Savlovo truplo in trupla njegovih sinov ter jih prinesli v Jabéš in njihove kosti pokopali pod hrastom v Jabéšu in se postili sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Tako je Savel umrl zaradi svojega prestopka, ki ga je zagrešil zoper Gospoda, torej zoper Gospodovo besedo, ki se je ni držal in je tudi spraševal za nasvet nekoga, ki je imel hišnega duha, da poizve o tem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'ni pa poizvedel od Gospoda, zato ga je ta usmrtil in kraljestvo obrnil k Jesejevemu sinu Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Potem se je ves Izrael zbral skupaj k Davidu v Hebrón, rekoč: »Glej, mi smo tvoja kost in tvoje meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Poleg tega si bil ti ta v preteklem času, ko je bil Savel kralj, ki si nas vodil ven in privedel v Izrael, in Gospod, tvoj Bog, ti je rekel: ›Ti boš pasel moje ljudstvo Izraela in ti boš vladar nad mojim ljudstvom Izraelom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Zato so vsi Izraelovi starešine prišli h kralju v Hebrón in David je v Hebrónu z njimi sklenil zavezo pred Gospodom; in mazilili so Davida za kralja nad Izraelom, glede na besedo od Gospoda po Samuelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'David in ves Izrael so odšli k Jeruzalemu, ki je Jebús, kjer so bili prebivalci dežele Jebusejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Prebivalci Jebúsa so rekli Davidu: »Ne boš prišel sèm.« Kljub temu je David zavzel sionski grad, ki je Davidovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'David je rekel: »Kdorkoli prvi udari Jebusejce bo vodja in poveljnik.« Tako je Cerújin sin Joáb prvi odšel gor in je bil vodja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'David je prebival v gradu, zato so ga imenovali Davidovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Okoli je zgradil mesto, celo od Milója naokoli, Joáb pa je popravil preostanek mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Tako je David postajal večji in večji, kajti Gospod nad bojevniki je bil z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Tudi ti so vodje izmed mogočnih mož, ki jih je imel David, ki so se z njim okrepili v njegovem kraljestvu in z vsem Izraelom, da ga postavijo za kralja, glede na Gospodovo besedo, ki je zadevala Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'To pa je število mogočnih mož, ki jih je imel David: Hahmoníjec Jašobám, vodja poveljnikov; svojo sulico je dvignil zoper tristo [in] po njem [so bili] naenkrat umorjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Za njim je bil Eleazar, sin Dodója, Ahóahovca, ki je bil eden izmed treh mogočnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Z Davidom je bil pri Pas Damínu in tam so se Filistejci skupaj zbrali za bitko, kjer je bil kos zemljišča poln ječmena; in ljudstvo je pobegnilo pred Filistejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Postavila sta se na sredo tega kosa zemljišča, ga osvobodila in usmrtila Filistejce in Gospod jih je rešil z veliko rešitvijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Torej trije izmed tridesetih poveljnikov so odšli dol k skali, k Davidu, v votlino Adulám, vojska Filistejcev pa se je utaborila v dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David je bil takrat v utrjenem kraju, garnizija Filistejcev pa je bila tedaj pri Betlehemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'David je zahrepenel in rekel: »Oh da bi mi nekdo dal piti vode iz betlehemskega vodnjaka, ki je pri velikih vratih!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'In trije so se prebili skozi vojsko Filistejcev in zajeli vodo iz betlehemskega vodnjaka, ki je bil pri velikih vratih, jo vzeli in jo prinesli k Davidu, toda David je ni hotel piti, temveč jo je izlil Gospodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'in rekel: »Bog ne daj, da bi storil to stvar. Mar naj bi pil kri teh mož, ki so svoja življenja postavili v nevarnost? Kajti s tveganjem za svoja življenja so jo prinesli.« Zato je ni hotel piti. Te stvari so storili ti trije mogočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Joábov brat Abišáj je bil vodja izmed treh. Ker je svojo sulico dvignil proti tristotim, jih usmrtil in imel ime med tremi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Izmed treh je bil častitljivejši kakor dva, kajti bil je njihov poveljnik, vendar prvih treh ni dosegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Jojadájev sin Benajá, sin hrabrega moža iz Kabceéla, ki je storil mnogo dejanj; usmrtil je dva levu podobna moža iz Moába; prav tako je odšel dol in ubil leva v jami na snežen dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ubil je Egipčana, moža visoke postave, pet komolcev visokega. V Egipčanovi roki je bila sulica, podobna tkalčevemu brunu in ta je s palico odšel dol k njemu, iz Egipčanove roke iztrgal sulico in ga usmrtil z njegovo lastno sulico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Te stvari je storil Jojadájev sin Benajá in imel je ime med tremi najmogočnejšimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Glej, bil je častitljiv med tridesetimi, toda ni dosegel prvih treh in David ga je postavil čez svojo stražo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Hrabri možje izmed vojsk so bili tudi: Joábov brat Asaél, Dodójev sin Elhanán iz Betlehema,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Harórec Šamót, Péletovec Helec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Irá, sin Tekójčana Ikéša, Anatóčan Abiézer,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Hušán Sibeháj, Ahóahovec Iláj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Netófčan Mahráj, Baanájev sin Heled, Netófčan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ribájev sin Itáj iz Gíbee, ki pripada Benjaminovim otrokom, Piratónec Benajá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huráj iz Gáaševih potokov, Arbatéjec Abiél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Baharuméjec Azmávet, Šaalbónec Eljahbá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'sinovi Guníjevca Hašéna; Jonatan, sin Hararéjca Šagéja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiám, sin Hararéjca Sahárja, Urov sin Elifál,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Meheréjec Hefer, Péletovec Ahíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Karmélčan Hecró, Ezbájev sin Naaráj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Natánov brat Joél, Hagríjev sin Mibhár,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Amónec Celek, Beeróčan Nahráj, nosilec bojne opreme Cerújinega sina Joába,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Jéterjevec Irá, Jéterjevec Garéb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Hetejec Urijá, Ahlájev sin Zabád,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adiná, sin Rubenovca Šizája, poveljnik Rubenovcev in trideseterica z njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Maahájev sin Hanán, Mitnéjec Józafat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Aštaróčan Uzíja, Šamá in Jehiél, sinova Aroêrčana Hotáma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Šimríjev sin Jediaél in njegov brat Ticéjec Johá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Mahavéjec Eliél, Elnáamova sinova Jeribáj in Jošavjá, Moábec Jitmá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliél, Obéd in Jaasiél Mecobaján.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Torej ti so tisti, ki so prišli k Davidu v Ciklág, medtem ko se je še vedno skrival zaradi Kiševega sina Savla in bili so med mogočnimi možmi, pomočniki vojne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Oboroženi so bili z loki in uporabljali so lahko tako desno kakor levo roko v metanju kamnov in streljanju puščic iz loka, celó Savlovi bratje iz Benjamina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Vodja je bil Ahiézer, potem Joáš, sinova Gíbejčana Šemaája, Jeziél in Pelet, Azmávetova sinova, Berahá, Anatóčan Jehú,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Gibeónec Jišmajá, mogočen mož med tridesetimi in nad tridesetimi: Jeremija, Jahaziél, Johanán, Géderčan Jozabád,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzáj, Jerimót, Bealjá, Šemarjá, Harúfčan Šefatjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkaná, Jišijá, Azarél, Joézer, Jašobám, Kórahovci ter');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joelá in Zebadjá, Jerohámova sinova iz Gedórja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Izmed Gádovcev so se k Davidu, v utrjen kraj, v divjini, ločili mogočni možje in možje vojne, primerni za boj, ki so lahko ravnali s ščitom in sulico, katerih obrazi so bili podobni obrazom levov in so bili tako nagli kakor srne po gorah:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'prvi Ecer, drugi Obadjá, tretji Eliáb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'četrti Mišmaná, peti Jeremija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'šesti Atáj, sedmi Eliél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'osmi Johanán, deveti Elzabád,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'deseti Jeremija in enajsti Mahbanáj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ti so bili Gadovi sinovi, poveljniki vojske; eden izmed najmanjših je bil nad stotimi in največji nad tisočimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ti so tisti, ki so šli čez Jordan v prvem mesecu, ko je ta poplavil vse svoje bregove, in zapodili so v beg vse tiste iz dolin, tako proti vzhodu kot proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'In prišli so izmed Benjaminovih in Judovih otrok k utrjenemu kraju, k Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'David je odšel ven, da jih sreča, jim odgovoril in jim rekel: »Če boste miroljubno prišli k meni, da mi pomagate, se bo moje srce povezalo k vam, toda če boste prišli, da me izdate mojim sovražnikom, ker ni krivice v mojih rokah, [naj] Bog naših očetov pogleda na to in to ošteje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Potem je duh prišel nad Amasája, ki je bil vodja poveljnikov in rekel je: »Tvoji smo David in na tvoji strani, Jesejev sin. Mir, mir bodi tebi in mir bodi tvojim pomočnikom, kajti tvoj Bog ti pomaga.« Potem jih je David sprejel in jih postavil za poveljnike čete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Tam so nekateri prešli od Manáseja k Davidu, ko je s Filistejci prišel zoper Savla, da se bojuje, toda oni jim niso pomagali, kajti filistejski knezi so ga po premisleku poslali proč, rekoč: »Prešel bo k svojemu gospodarju Savlu, da ogrozi naše glave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Medtem ko je šel v Ciklág, so od Manáseja k njemu prestopili Adnáh, Jozabád, Jediaél, Mihael, Jozabád, Elihú in Celetáj, poveljniki tisočih, ki so bili iz Manáseja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Davidu so pomagali zoper krdelo roparjev, kajti vsi so bili močni junaški možje in bili so poveljniki v vojski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Kajti ob tistem času so dan za dnem prihajali k Davidu, da mu pomagajo, dokler to ni bila velika vojska, podobna Božji vojski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'To so števila čet, ki so bile oborožene za vojno in so prišle k Davidu v Hebrón, da Savlovo kraljestvo obrnejo k njemu, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Judovih otrok, ki so nosili ščit in sulico, je bilo šest tisoč osemsto oboroženih za vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Izmed Simeonovih otrok, močnih junaških mož za vojno, sedem tisoč sto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Izmed Lévijevih otrok štiri tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Jojadá je bil voditelj Aroncev in z njim jih je bilo tri tisoč sedemsto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'in Cadók, silno junaški mladenič in dvaindvajset poveljnikov iz hiše njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Izmed Benjaminovih otrok, Savlovega sorodstva, tri tisoč, kajti do zdaj je večina izmed njih držala stražo Savlove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Izmed Efrájimovih sinov dvajset tisoč osemsto mogočnih mož, močnih junaških mož, slovečih v hiši svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Izmed polovice Manásejevega rodu osemnajst tisoč [tistih], ki so bili določeni po imenu, da pridejo in postavijo Davida za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Izmed Isahárjevih otrok, ki so bili možje, ki so imeli razumevanje časov, da vedo, kaj mora Izrael storiti. Njihovih poglavarjev je bilo dvesto, in vsi njihovi bratje so bili pod njihovim poveljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Od Zábulona tisti, ki so šli naprej v bitko, izkušeni v vojni, z vsemi vojnimi pripomočki, petdeset tisoč, ki so lahko obdržali položaj; ti niso bili razdeljenega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Od Neftálija tisoč poveljnikov in z njimi sedemintrideset tisoč s ščitom in sulico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Izmed Danovcev, izkušenih v vojni, osemindvajset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Od Aserja tistih, ki so šli naprej v bitko, izkušenih v vojni, štirideset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Na drugi strani Jordana, od Rubenovcev, Gádovcev in od polovice Manásejevega rodu, z vsemi vrstami vojnih priprav za bitko, sto dvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Vsi ti bojevniki, ki so lahko obdržali položaj, so s popolnim srcem prišli v Hebrón, da postavijo Davida za kralja nad vsem Izraelom, in tudi vsi preostali iz Izraela so bili enega srca, da postavijo Davida za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Tam so bili z Davidom tri dni, jedli so in pili, kajti njihovi bratje so pripravili zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Poleg tega so tisti, ki so bili blizu njih, celó Isahár, Zábulon in Neftáli, prinesli kruha na oslih, na kamelah, na mulah in na volih ter živež, moko, skupaj stisnjene fige in rozine, vino, olje, vole in obilje ovc, kajti radost je bila v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David se je posvetoval s poveljniki nad tisočimi in nad stotimi in z vsakim voditeljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'David je vsej Izraelovi skupnosti rekel: »Če se vam to zdi dobro in je to od Gospoda, našega Boga, pošljimo vsem našim bratom naokoli, ki so ostali v vsej Izraelovi deželi in z njimi tudi duhovnikom in Lévijevcem, ki so v njihovih mestih in predmestjih, da se bodo lahko zbrali k nam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'in ponovno privedimo k sebi skrinjo našega Boga, kajti v Savlovih dneh nismo povpraševali po njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Vsa skupnost je rekla, da bodo tako storili, kajti stvar je bila pravilna v očeh vsega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Tako je David zbral skupaj ves Izrael, od egiptovskega Šihórja, celo do vstopa v Hamát, da Božjo skrinjo privede iz Kirját Jearíma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'David se je dvignil in ves Izrael v Baálo, to je v Kirját Jearím, ki pripada Judu, da od tam privede Božjo skrinjo Gospoda, ki prebiva med kerubi, katerega ime je imenovano na njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Božjo skrinjo so odpeljali na novem vozu iz Abinadábove hiše. Uzá in Ahjó pa sta gnala voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'David in ves Izrael so igrali pred Bogom z vso svojo močjo, s petjem, harfami, plunkami, tamburini, cimbalami in trobentami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Ko so prišli na Kidónovo mlatišče, je Uzá iztegnil svojo roko, da pridrži skrinjo, kajti voli so se spotaknili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Gospodova jeza je bila vžgana zoper Uzá in ga je udaril, ker je svojo roko položil k skrinji in tam je umrl pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'David je bil razžaljen, ker je Gospod naredil vrzel nad Uzájem, zato je ta kraj do tega dne imenovan Perec Uzá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'David se je tisti dan bal Boga, rekoč: »Kako naj Božjo skrinjo pripeljem k sebi domov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Tako David skrinje ni pripeljal k sebi domov, v Davidovo mesto, temveč jo je odnesel stran, v hišo Gitéjca Obéd Edóma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Božja skrinja je ostala tri mesece z družino Obéd Edóma v njegovi hiši. Gospod je blagoslovil hišo Obéd Edóma in vse, kar je ta imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Torej kralj Hirám iz Tira je poslal poslance k Davidu in cedrov les z zidarji in tesarji, da mu zgradijo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'David je zaznal, da ga je Gospod potrdil za kralja nad Izraelom, kajti njegovo kraljestvo je bilo visoko povzdignjeno zaradi njegovega ljudstva Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'David si je v Jeruzalemu vzel več žena in David je zaplodil več sinov in hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Torej to so imena njegovih otrok, ki jih je imel v Jeruzalemu: Šamúa, Šobáb, Natán, Salomon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhár, Elišúa, Elpélet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogah, Nefeg, Jafíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elišamá, Beeljadá in Elifálet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Ko so Filistejci slišali, da je bil David maziljen za kralja nad vsem Izraelom, so vsi Filistejci odšli gor, da poiščejo Davida. David pa je slišal o tem in odšel ven zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Filistejci so prišli in se razporedili po dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'David je poizvedel od Boga, rekoč: »Ali naj grem gor zoper Filistejce? Ali jih boš izročil v mojo roko?« Gospod mu je rekel: »Pojdi gor, kajti izročil jih bom v tvojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Tako so prišli gor v Báal Peracím in David jih je tam udaril. Potem je David rekel: »Bog je po moji roki pridrl nad moje sovražnike, kakor izbruhnejo vode,« zato so ime tega kraja imenovali Báal Peracím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Ko so tam pustili svoje bogove, je David dal zapoved in sežgali so jih v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Filistejci pa so se ponovno razporedili po dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Zato je David ponovno poizvedel od Boga in Bog mu je rekel: »Ne pojdi gor za njimi. Obrni se proč od njih in pridi nadnje nasproti murvinih dreves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Zgodilo se bo, ko boš zaslišal zvok hoje po vrhovih murvinih dreves, da boš tedaj odšel ven na bitko, kajti Bog je šel naprej pred teboj, da udari vojsko Filistejcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David je torej storil, kakor mu je Bog zapovedal in udarili so vojsko Filistejcev od Gibeóna, celo do Gazerja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Davidova slava se je razširila po vseh deželah in Gospod je nad vse narode privedel strah pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'David si je v Davidovem mestu zgradil hiše in pripravil kraj za Božjo skrinjo in zanjo razpel šotor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Potem je David rekel: »Božje skrinje ne bi smel nositi nihče razen Lévijevcev, kajti njih je Gospod izbral, da nosijo Božjo skrinjo in da mu služijo na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'David je skupaj zbral ves Izrael v Jeruzalemu, da prinese gor Gospodovo skrinjo na kraj, ki ga je pripravil zanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David je zbral Aronove otroke in Lévijevce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Izmed Kehátovih sinov vodja Uriéla in sto dvajset njegovih bratov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'izmed Meraríjevih sinov vodja Asajája in dvesto dvajset njegovih bratov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'izmed Geršómovih sinov vodja Joéla in sto trideset njegovih bratov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'izmed Elicafánovih sinov vodja Šemajá in dvesto njegovih bratov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'izmed Hebrónovih sinov vodja Eliéla in osemdeset njegovih bratov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'izmed Uziélovih sinov vodja Aminadába in sto dvanajst njegovih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'David je dal poklicati Cadóka, duhovnika Abjatárja in Lévijevce Uriéla, Asajá, Joéla, Šemajá, Eliéla in Aminadába');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'ter jim rekel: »Vi ste vodje očetov Lévijevcev. Posvetite se tako vi kakor vaši bratje, da boste lahko prinesli gor skrinjo Gospoda, Izraelovega Boga, na kraj, ki sem ga pripravil zanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Kajti ker tega niste najprej storili, je Gospod, naš Bog, nad nami naredil vrzel, ker ga nismo iskali po predpisanem redu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Tako so se duhovniki in Lévijevci posvetili, da prinesejo gor skrinjo Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Lévijevi otroci so na svojih ramenih nosili Božjo skrinjo z njenima drogovoma v njej, kakor je zapovedal Mojzes, glede na Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'David je spregovoril vodju Lévijevcev, da določi svoje brate, da bodo pevci z glasbenimi instrumenti, plunkami, harfami in cimbalami, z dvigovanjem zvenečega radostnega glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Tako so Lévijevci določili Joélovega sina Hemána in izmed njegovih bratov Berehjájevega sina Asáfa in izmed Meraríjevih sinov, njihovih bratov, Kušajájevega sina Etána');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, '§ in z njimi njihove brate druge stopnje: Zeharjája, Bena, Jaaziéla, Šemiramóta, Jehiéla, Uníja, Eliába, Benajája, Maasejája, Matitjája, Elifeléhuja, Miknejája, Obéd Edóma in Jeiéla, vratarje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Tako so bili pevci Hemán, Asáf in Etán določeni, da igrajo na cimbale iz brona,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zeharjá, Jaaziél, Šemiramót, Jehiél, Uní, Eliáb, Maasejá in Benajá s plunkami na sopran,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'in Matitjá, Elifeléhu, Miknejá, Obéd Edóm, Jeiél in Azazjá s harfami v oktavi, da vodijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanjá, vodja Lévijevcev, je bil za pesem. Poučil je glede pesmi, ker je bil vešč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berehjá in Elkaná sta bila vratarja za skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Duhovniki Šebanjá, Józafat, Netanél, Amasáj, Zeharjá, Benajá in Eliézer so s trobentami trobili pred Božjo skrinjo; Obéd Edóm in Jehijá pa sta bila vratarja za skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Tako so David, Izraelove starešine in tisočniki odšli, da iz hiše Obéd Edóma z radostjo prinesejo gor Gospodovo skrinjo zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Pripetilo se je, ko je Bog pomagal Lévijevcem, da so nosili skrinjo Gospodove zaveze, da so darovali sedem bikcev in sedem ovnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David je bil oblečen s svečanim oblačilom iz tankega lanenega platna in vsi Lévijevci, ki so nosili skrinjo, pevci in Kenanjá, mojster pesmi s pevci; tudi David je imel na sebi efód iz lana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Tako je ves Izrael prinesel gor Gospodovo skrinjo zaveze z vriskanjem, z zvokom kornéta, s trobentami, cimbalami in igrali so s plunkami in harfami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Pripetilo se je, medtem ko je Gospodova skrinja prišla v Davidovo mesto, da je Savlova hči Mihála, zroč skozi okno, videla kralja Davida plesati in igrati in ga v svojem srcu prezirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Tako so prinesli Božjo skrinjo in jo postavili na sredo šotora, ki ga je kralj David postavil zanjo ter pred Bogom darovali žgalne daritve in mirovne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Ko je David končal žrtvovanje žgalnih daritev in mirovnih daritev, je v Gospodovem imenu blagoslovil ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Vsakemu iz Izraela, tako moškemu kakor ženski, vsakemu je razdelil hleb kruha, dober kos mesa in flaškon vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Nekatere izmed Lévijevcev je določil, da služijo pred Gospodovo skrinjo in da se spominjajo, se zahvaljujejo in hvalijo Gospoda, Izraelovega Boga:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'vodja Asáfa in poleg njega Zeharjá, Jeiéla, Šemiramóta, Jehiéla, Matitjája, Eliába, Benajája in Obéd Edóma; in Jeiéla s plunkami in harfami, toda Asáf je igral na cimbale;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'tudi duhovnika Benajája in Jahaziéla s trobentami nenehno pred skrinjo Božje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Potem je na ta dan David prvič izročil ta psalm v roko Asáfa in njegovih bratov, da se zahvalijo Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Zahvaljujte se Gospodu, kličite njegovo ime, med ljudstvom razglašajte njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Prepevajte mu, prepevajte mu psalme, govorite o vseh njegovih čudovitih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Ponašajte se z njegovim svetim imenom. Naj se veseli srce tistih, ki iščejo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Iščite Gospoda in njegovo moč, neprenehoma iščite njegov obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Spominjajte se njegovih čudovitih del, ki jih je storil, njegovih čudežev in sodb njegovih ust;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'oh vi seme Izraela, njegovega služabnika, vi Jakobovi otroci, njegovi izbranci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On je Gospod, naš Bog, njegove sodbe so po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Vedno se zavedajte njegove zaveze, besede, katero je zapovedal tisočim rodovom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'celo zaveze, ki jo je sklenil z Abrahamom in njegove prisege Izaku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'in isto je potrdil Jakobu za zakon in Izraelu za večno zavezo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'rekoč: »Tebi bom dal kánaansko deželo, žreb vaše dediščine,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'ko vas je bilo le malo, celo peščica in tujci v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Ko so hodili od naroda k narodu in od enega kraljestva k drugemu ljudstvu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'nobenemu človeku ni pustil, da jim stori krivico; da, zaradi njih je grajal kralje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'rekoč: »Ne dotikajte se mojih maziljencev in mojim prerokom ne delajte hudega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Poj Gospodu, vsa zemlja, iz dneva v dan naznanjaj njegovo rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Oznanjajte njegovo slavo med pogani, njegova čudovita dela med vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, '§ Kajti velik je Gospod in silno naj bo hvaljen. Njega se je treba bati nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Kajti vsi bogovi ljudstva so maliki, toda Gospod je naredil nebesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Slava in čast sta v njegovi prisotnosti, moč in veselje sta na njegovem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Dajajte Gospodu, ve sorodstva ljudstev, dajajte Gospodu slavo in moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Dajajte Gospodu slavo, primerno njegovemu imenu, prinesite daritev in pridite predenj. Obožujte Gospoda v lepoti svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Boj se pred njim, vsa zemlja. Tudi zemeljski [krog] bo trden, ki ne bo omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Naj bodo nebesa vesela in naj se zemlja veseli, in ljudje naj govorijo med narodi: » Gospod kraljuje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Naj buči morje in njegova polnost. Naj se polja veselijo in vse, kar je na njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Potem bodo gozdna drevesa prepevala ob Gospodovi prisotnosti, ker on prihaja, da sodi zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Oh zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja za vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Recite: »Reši nas, oh Bog rešitve naših duš, zberi nas skupaj in nas osvobodi pred pogani, da se bomo lahko zahvaljevali tvojemu svetemu imenu in slavili v tvoji hvali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Blagoslovljen bodi Gospod, Izraelov Bog na veke vekov.« In vse ljudstvo je reklo: »Amen« in hvalilo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Tako je tam, pred skrinjo Gospodove zaveze, pustil Asáfa in njegove brate, da nenehno služijo pred skrinjo, kakor je zahtevalo vsakodnevno delo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'in Obéd Edóma z oseminšestdesetimi njihovimi brati; tudi Jedutúnovega sina Obéd Edóma in Hosája, da bosta vratarja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'in duhovnika Cadóka in njegove brate duhovnike pred Gospodovim šotorskim svetiščem na visokem kraju, ki je bil pri Gibeónu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'da darujejo žgalne daritve Gospodu na oltarju, nenehne žgalne daritve, jutranje in večerne in da storijo glede na vse, kar je pisano v Gospodovi postavi, ki jo je zapovedal Izraelu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'in z njimi Hemána, Jedutúna in druge, ki so bili izbrani, ki so bili določeni po imenu, da se zahvaljujejo Gospodu, ker njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'in z njimi Hemána in Jedutúna s trobentami in cimbalami za tiste, da bi igrali in z Božjimi glasbenimi instrumenti. Jedutúnovi sinovi pa so bili vratarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'In vse ljudstvo je odšlo vsak človek k svoji hiši, in David se je vrnil, da blagoslovi svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Pripetilo se je torej, medtem ko je David sedel v svoji hiši, da je David rekel preroku Natánu: »Glej, jaz prebivam v cedrovi hiši, toda skrinja Gospodove zaveze ostaja pod zavesami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Potem je Natán rekel Davidu: »Stôri vse, kar je v tvojem srcu, kajti Bog je s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Iste noči se je pripetilo, da je Božja beseda prišla k Natánu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '»Pojdi in povej mojemu služabniku Davidu: ›Tako govori Gospod: ›Ti mi ne boš gradil hiše, da prebivam v njej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'kajti nisem prebival v hiši od dne, ko sem Izraela privedel gor, do današnjega dne, temveč sem šel od šotora k šotoru in od enega šotorskega svetišča k drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Kjerkoli sem hodil z vsem Izraelom, sem mar spregovoril besedo kateremukoli izmed Izraelovih sodnikov, ki sem jim zapovedal, da pasejo moje ljudstvo, rekoč: ›Zakaj mi niste zgradili cedrove hiše?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Zdaj boš torej tako povedal mojemu služabniku Davidu: ›Tako govori Gospod nad bojevniki: ›Vzel sem te iz staje za ovce, celó od sledenja ovcam, da bi bil vladar nad mojim ljudstvom Izraelom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'in s teboj sem bil kjerkoli si hodil in pred teboj sem iztrebil vse tvoje sovražnike in ti naredil ime, podobno imenu velikih mož, ki so na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Prav tako bom določil kraj za svoje ljudstvo Izrael in jih zasadil in bodo prebivali na svojem kraju in ne bodo več seljeni niti jih ne bodo več pustošili otroci zlobnosti kakor poprej');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'in odkar sem zapovedal sodnikom, naj bodo nad mojim ljudstvom Izraelom. Poleg tega bom podjarmil vse tvoje sovražnike. Nadalje ti povem še, da ti bo Gospod zgradil hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Zgodilo se bo, ko bodo tvoji dnevi pretekli, da moraš oditi, da boš s svojimi očeti, da bom obudil tvoje seme za teboj, ki bo izmed tvojih sinov in jaz bom utrdil njegovo kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Zgradil mi bo hišo in njegov prestol bom utrdil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Jaz bom njegov oče in on bo moj sin. Svoje milosti ne bom odvzel od njega, kakor sem jo odvzel tistemu, ki je bil pred teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'temveč ga bom postavil v svoji hiši in v svojem kraljestvu na veke in njegov prestol bo utrjen na vékomaj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Glede na vse te besede in glede na vse to videnje, tako je Natán govoril Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Kralj David je prišel in se usedel pred Gospodom ter rekel: »Kdo sem jaz, oh Gospod Bog in kaj je moja hiša, da si me privedel sèm?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Vendar je bila to majhna stvar v tvojih očeh, oh Bog, kajti govoril si tudi o hiši svojega služabnika za oddaljeni čas, ki pride in si se ozrl name glede na stan človeka visoke stopnje, oh Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Kaj ti lahko David še govori glede časti tvojega služabnika? Kajti poznaš svojega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Oh Gospod, zaradi svojega služabnika in glede na svoje lastno srce, si storil vso to veličino v tem, da si dal spoznati vse te velike stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Oh Gospod, nobenega ni podobnega tebi niti ni nobenega Boga poleg tebe, glede na vse, kar smo slišali s svojimi ušesi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Kateri narod na zemlji je podoben tvojemu ljudstvu Izraelu, ki ga je Bog šel odkupit, da postane njegovo lastno ljudstvo, da si si naredil ime veličine in strašnosti s pregonom narodov izpred svojega ljudstva, ki si ga odkupil iz Egipta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Kajti svojemu ljudstvu Izraelu si storil, da bo tvoje lastno ljudstvo na veke; in ti, Gospod, postajaš njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Zato sedaj, Gospod, naj bo stvar, ki si jo govoril glede svojega služabnika in glede njegove hiše, utrjena na veke in stôri, kakor si rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Naj bo to celo utrjeno, da bo tvoje ime lahko poveličano na veke, rekoč: › Gospod nad bojevniki je Izraelov Bog, celó Bog Izraelu‹ in naj bo hiša tvojega služabnika Davida utrjena pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Kajti ti, oh moj Bog, si povedal svojemu služabniku, da mu hočeš zgraditi hišo, zato je tvoj služabnik v svojem srcu našel, da moli pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'In sedaj, Gospod, ti si Bog in to dobroto si obljubil svojemu služabniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Zdaj naj ti torej to ugaja, da blagosloviš hišo svojega služabnika, da bo ta lahko pred teboj na veke, kajti ti blagoslavljaš, oh Gospod in to bo blagoslovljeno na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Torej po tem se je pripetilo, da je David udaril Filistejce in jih podjarmil in iz roke Filistejcev vzel Gat in njegova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Udaril je Moáb in Moábci so postali Davidovi služabniki in prinašali darila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David je udaril Hadarézerja, kralja Cobe v Hamátu, medtem ko je šel, da si utrdi svoje gospostvo pri reki Evfratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'David mu je vzel tisoč bojnih vozov in sedem tisoč konjenikov in dvajset tisoč pešcev. David je tudi prerezal Ahilove tetive vsem konjem bojnega voza, toda izmed njih je prihranil sto bojnih vozov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Ko so Sirci iz Damaska prišli pomagat Hadarézerju, kralju iz Cobe, je David med Sirci usmrtil dvaindvajset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Potem je David v sirskem Damasku postavil garnizije in Sirci so postali Davidovi služabniki in prinašali darila. Tako je Gospod varoval Davida kamorkoli je šel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'David je vzel ščite iz zlata, ki so bili na Hadarézerjevih služabnikih in jih prinesel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Podobno je iz Tibháta in iz Kuna, Hadarézerjevih mest, David prinesel zelo veliko brona, s katerim je Salomon naredil bronasto morje, stebra in bronaste posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Torej ko je kralj Tov iz Hamáta slišal kako je David udaril vso vojsko Hadarézerja, kralja iz Cobe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'je poslal svojega sina Hadoráma h kralju Davidu, da poizve o njegovi blaginji in da mu čestita, ker se je boril zoper Hadarézerja in ga udaril (kajti Hadarézer je bil v vojni s Tovjem) in z njim vse vrste posod iz zlata, srebra in brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Tudi te je kralj David posvetil Gospodu, s srebrom in zlatom, ki ga je prinesel iz vseh teh narodov: iz Edóma, Moába, od Amónovih otrok, od Filistejcev in od Amáleka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, '§ Poleg tega je Cerújin sin Abišáj, usmrtil osemnajst tisoč Edómcev v slani dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Postavil je garnizije v Edómu in vsi Edómci so postali Davidovi služabniki. Tako je Gospod varoval Davida kamorkoli je šel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Tako je David kraljeval nad vsem Izraelom in izvrševal sodbo ter pravico med vsem svojim ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Cerújin sin Joáb je bil nad vojsko in Ahilúdov sin Józafat [je bil] letopisec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Ahitúbov sin Cadók in Abjatárjev sin Abiméleh sta bila duhovnika, Šavšá pa je bil pisar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Jojadájev sin Benajá je bil nad Keretéjci in Péletovci, Davidovi sinovi pa so bili vodje okoli kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Torej po tem se je pripetilo, da je umrl Naháš, kralj Amónovih otrok in namesto njega je zakraljeval njegov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'David je rekel: »Izkazal bom prijaznost Naháševemu sinu Hanúnu, ker je njegov oče izkazal prijaznost meni.« In David je poslal poslance, da ga potolažijo glede njegovega očeta. Tako so Davidovi služabniki prišli v deželo Amónovih otrok k Hanúnu, da ga potolažijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Toda princi Amónovih otrok so Hanúnu rekli: »Misliš, da je David spoštoval tvojega očeta, da ti je poslal tolažnike? Mar niso njegovi služabniki prišli k tebi, da preiščejo, preobrnejo in si ogledajo deželo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Zato je Hanún prijel Davidove služabnike, jih obril in njihove obleke odrezal po sredi, tik poleg njihovih zadnjic in jih odposlal proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Potem so nekateri odšli in Davidu povedali, kako so bili možje postreženi. In poslal je, da jih sreča, kajti možje so bili silno osramočeni. Kralj je rekel: »Ostanite pri Jerihi, dokler vam brade ne zrastejo, potem se vrnite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Ko so Amónovi otroci videli, da so Davidu postali zoprni, so Hanún in Amónovi otroci poslali tisoč talentov srebra, da si iz Mezopotamije, iz sirske Maáhe in Cobe najamejo bojne vozove in konjenike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Tako so najeli dvaintrideset tisoč bojnih vozov, kralja Maáhe in njegovo ljudstvo, ki so prišli in se utaborili pred Médebo. In Amónovi otroci so se zbrali skupaj iz svojih mest in prišli na bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Ko je David slišal o tem, je poslal Joába in vso vojsko mogočnih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Amónovi otroci so prišli ven in se pred velikimi vrati mesta postrojili v bitko. Kralji, ki so prišli, pa so bili posebej na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Torej ko je Joáb videl, da je bila bitka zoper njega postavljena spredaj in zadaj, je izmed vseh izbral izbrane Izraelove in jih postrojil zoper Sirce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Preostanek ljudstva pa je izročil v roko svojega brata Abišája, in ti so se postrojili zoper Amónove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Rekel je: »Če bodo Sirci zame premočni, potem mi boš ti pomagal, toda če bodo Amónovi otroci premočni zate, potem bom jaz pomagal tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Bodi odločnega poguma in se junaško obnašajva za naše ljudstvo in za mesta našega Boga. Gospod pa naj stori to, kar je dobro v njegovem pogledu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Tako se je Joáb in ljudstvo, ki je bilo z njim, približalo pred Sirce k bitki, ti pa so pobegnili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Ko so Amónovi otroci videli, da so Sirci pobegnili, so tudi sami pobegnili pred njegovim bratom Abišájem in vstopili v mesto. Potem je Joáb prišel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Ko pa so Sirci videli, da so bili pred Izraelom poraženi, so poslali poslance in pripeljali Sirce, ki so bili onkraj reke; in Šopáh, poveljnik Hadarézerjeve vojske, je šel pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'To je bilo povedano Davidu in ta je zbral ves Izrael, prečkal Jordan in prišel nadnje in se postrojil v bitko zoper njih. Torej, ko se je David postrojil v bitko zoper Sirce, so se ti bojevali z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Toda Sirci so zbežali pred Izraelom in David jih je izmed Sircev usmrtil sedem tisoč mož, ki so se bojevali na bojnih vozovih in štirideset tisoč pešcev in ubil poveljnika vojske Šopáha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Ko so Hadarézerjevi služabniki videli, da so bili pred Izraelom poraženi, so z Davidom sklenili mir in postali njegovi služabniki; niti Sirci niso hoteli več pomagati Amónovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Pripetilo se je, potem ko je minilo leto, ob času, ko gredo kralji na bitko, da je Joáb vodil moč vojske in opustošil deželo Amónovih otrok in prišel ter oblegal Rabo. Toda David je ostal v Jeruzalemu. In Joáb je udaril Rabo ter jo uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'David je snel krono njihovega kralja iz njegove glave in spoznal, da tehta talent zlata in v njej so bili dragoceni kamni, in ta je bila postavljena na Davidovo glavo. In iz mesta je prinesel tudi silno mnogo plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, '§ Ljudstvo, ki je bilo v njem, je privedel ven in jih razsekal z žagami, branami iz železa in sekirami. Celo tako je David postopal z vsemi mesti Amónovih otrok. In David in vse ljudstvo se je vrnilo v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Pripetilo se je za tem, da se je vzdignila vojna s Filistejci pri Gezerju. Takrat je Hušán Sibeháj usmrtil Sipája, ki je bil izmed otrok velikana; in bili so podjarmljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Ponovno je bila vojna s Filistejci. Jaírov sin Elhanán je usmrtil Lahmíja, brata Gitéjca Goljata, katerega kopjišče je bilo podobno tkalčevemu brunu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Ponovno je bila vojna pri Gatu, kjer je bil mož visoke postave, katerega prstov in palcev je bilo štiriindvajset, šest na vsaki roki in šest na vsakem stopalu in tudi ta je bil sin velikana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Toda ko je izzival Izraela, ga je Jonatan, Šimájajev sin, Davidov brat, usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ti so bili rojeni velikanu v Gatu in padli so po Davidovi roki in po roki njegovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satan je vstal zoper Izraela in spodbudil Davida, da prešteje Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'In David je rekel Joábu ter voditeljem ljudstva: »Pojdite, preštejte Izraela od Beeršéba celo do Dana in njihovo število prinesite k meni, da ga bom lahko vedel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joáb je odgovoril: » Gospod naj naredi svoje ljudstvo stokrat tako številno, kot jih je, toda moj gospod kralj, ali niso vsi služabniki mojega gospoda? Zakaj potem moj gospod zahteva to stvar? Zakaj bo on razlog prekrška Izraelu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Kljub temu je kraljeva beseda prevladala proti Joábovi. Zato je Joáb odpotoval, šel skozi ves Izrael in prišel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Joáb je Davidu izročil vsoto ljudstva. In vseh iz Izraela je bilo milijon sto tisoč, ki so izdirali meč, in Juda je bilo štiristo sedemdeset tisoč mož, ki so izdirali meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Toda Lévijevce in Benjamina pa ni prištel mednje, kajti kraljeva beseda je bila Joábu gnusna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Bog pa je bil razžaljen s to stvarjo, zato je udaril Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'David je rekel Bogu: »Silno sem grešil, ker sem storil to stvar. Toda zdaj te rotim, odstrani krivičnost svojega služabnika, kajti storil sem zelo nespametno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Gospod je spregovoril Davidovemu vidcu Gadu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '»Pojdi in povej Davidu, rekoč: ›Tako govori Gospod: ›Ponujam ti tri stvari. Izberi eno izmed njih, da ti jo bom lahko storil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Tako je Gad prišel k Davidu in mu rekel: »Tako govori Gospod: ›Izberi si');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'ali tri leta lakote, ali tri mesece uničenja pred svojimi sovražniki, medtem ko te dohiteva meč tvojih sovražnikov, ali tri dni Gospodovega meča, celo kužne bolezni v deželi in uničevanje od Gospodovega angela po vseh Izraelovih pokrajinah. Sedaj si torej svetuj, kakšno besedo naj ponovno prinesem tistemu, ki me je poslal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David je rekel Gadu: »V veliki stiski sem. Naj torej padem v Gospodovo roko, kajti zelo velika so njegova usmiljenja, toda naj ne padem v roko človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Tako je Gospod nad Izrael poslal kužno bolezen in izmed Izraela je padlo sedemdeset tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Bog je poslal angela k Jeruzalemu, da ga uniči. Medtem ko je ta uničeval, je Gospod opazoval, se pokesal od zla in rekel angelu, ki je uničeval: »Dovolj je, zadrži sedaj svojo roko.« In Gospodov angel je stal pri mlatišču Jebusejca Ornana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David je povzdignil svoje oči in zagledal Gospodovega angela stati med zemljo in nebom, ki je imel v svoji roki izvlečen meč, iztegnjen nad Jeruzalemom. Potem so David in starešine Izraela, ki so bili oblečeni v vrečevino, padli na svoje obraze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'David pa je rekel Bogu: » Ali nisem to jaz, ki sem zapovedal, da se ljudstvo prešteje? Celo jaz sem ta, ki je grešil in zares storil zlo. Toda kar se tiče teh ovc, kaj so te storile? Naj bo tvoja roka, prosim te, oh Gospod, moj Bog, na meni in na hiši mojega očeta, toda ne na tvojem ljudstvu, da bi bili trpinčeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Potem je Gospodov angel zapovedal Gadu, da reče Davidu, naj gre David gor in postavi oltar Gospodu na mlatišču Jebusejca Ornana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'David je na Gadovo besedo, ki jo je govoril v Gospodovem imenu, odšel gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Ornan pa se je obrnil in zagledal angela in njegovi štirje sinovi so se z njim vred skrili. Torej Ornan je mlatil pšenico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Ko je David prišel k Ornanu, je Ornan pogledal in zagledal Davida in šel ven iz mlatišča in se pripognil k Davidu s svojim obrazom do tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Potem je David rekel Ornanu: »Zagotovi mi prostor tega mlatišča, da bom na njem lahko zgradil oltar Gospodu. Zagotovil mi ga boš za polno ceno, da bo nadloga lahko ustavljena pred ljudstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan je rekel Davidu: »Vzemi to k sebi in naj moj gospod kralj stori to, kar je dobro v njegovih očeh. Glej, dam ti tudi vola za žgalne daritve, mlatilne priprave za les in pšenico za jedilno daritev; vse to dam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Kralj David je rekel Ornanu: »Ne, temveč bom to resnično kupil za polno ceno, kajti ne bom vzel tega, kar je tvoje, za Gospoda niti žgalne daritve daroval brez stroška.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Tako je David dal Ornanu za prostor šeststo šeklov zlata po teži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'David je tam zgradil oltar Gospodu in daroval žgalne daritve in mirovne daritve in klical h Gospodu in ta mu je iz nebes odgovoril z ognjem na oltar žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Gospod je zapovedal angelu in ta je svoj meč ponovno vtaknil v svojo nožnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'V tistem času, ko je David videl, da mu je Gospod odgovoril na mlatišču Jebusejca Ornana, potem je tam žrtvoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Kajti Gospodovo šotorsko svetišče, ki ga je Mojzes naredil v divjini in oltar žgalne daritve sta bila v tem obdobju na visokem kraju pri Gibeónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Toda David ni mogel iti predenj, da bi povprašal od Boga, kajti bal se je zaradi meča Gospodovega angela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Potem je David rekel: »To je hiša Gospoda Boga in to je oltar žgalne daritve za Izraela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'David je zapovedal, da zberejo skupaj tujce, ki so bili v Izraelovi deželi in postavil je zidarje, da izklesajo kamne, da zgradijo Božjo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'David je pripravil železa v obilju za žeblje za duri velikih vrat in za vezi in brona v obilju, brez teže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Tudi cedrovih dreves v obilju, kajti Sidónci in tisti iz Tira so Davidu prinesli veliko cedrovega lesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'David je rekel: »Moj sin Salomon je mlad in nežen, hiša, ki naj se zgradi za Gospoda, pa mora biti silno prekrasna od slovesa in od slave po vseh deželah, zato bom torej naredil priprave zanjo.« Tako je David pred svojo smrtjo [vsega] obilno pripravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Potem je dal poklicati svojega sina Salomona in ga zadolžil, da zgradi hišo za Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'David je rekel Salomonu: »Moj sin, kar se mene tiče, je bilo v mojih mislih, da zgradim hišo imenu Gospoda, svojega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'toda k meni je prišla Gospodova beseda, rekoč: ›Obilno si prelival kri in storil velike vojne. Ne boš gradil hiše mojemu imenu, ker si v mojem pogledu na zemlji prelil mnogo krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Glej, rojen ti bo sin, ki bo mož počitka in dal mu bom počitek pred vsemi njegovimi sovražniki naokoli, kajti njegovo ime bo Salomon in jaz bom v njegovih dneh Izraelu dal mir in spokojnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Zgradil bo hišo za moje ime in on bo moj sin in jaz bom njegov oče in jaz bom vzpostavil prestol njegovega kraljestva nad Izraelom na veke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Sedaj moj sin, Gospod naj bo s teboj in bodi uspešen in zgradi hišo Gospoda, svojega Boga, kakor je govoril o tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Samo Gospod naj ti da modrost in razumevanje in te zadolži glede Izraela, da se boš lahko držal postave Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Potem boš uspel, če paziš, da izpolnjuješ zakone in sodbe, ki jih je Gospod zapovedal Mojzesu glede Izraela. Bodi močan in odločnega poguma. Ne boj se niti ne bodi zaprepaden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Torej glej, v svoji stiski sem za Gospodovo hišo pripravil sto tisoč talentov zlata in milijon talentov srebra, brona in železa pa brez teže, kajti tega je v obilju. Tudi les in kamenje sem pripravil in ti lahko k temu dodaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Poleg tega je tam s teboj delavcev v obilju, kamnosekov in obdelovalcev kamna in lesa, in vseh vrst spretnih mož za vsako vrsto dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Zlatu, srebru, bronu in železu ni števila. Vstani torej in delaj in Gospod naj bo s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'David je tudi vsem Izraelovim princem zapovedal, da pomagajo njegovemu sinu Salomonu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '» Mar ni z vami Gospod, vaš Bog? In ali vam ni dal počitka na vsaki strani? Kajti prebivalce dežele je izročil v mojo roko in dežela je podjarmljena pred Gospodom in pred njegovim ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Pripravite torej svoje srce in svojo dušo, da iščete Gospoda, svojega Boga. Vstanite torej in zgradite svetišče Gospodu Bogu, da se prinese skrinja Gospodove zaveze in svete Božje posode v hišo, ki naj bo zgrajena Gospodovemu imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Torej ko je bil David star in izpolnjen z dnevi, je nad Izraelom postavil svojega sina Salomona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Ta je zbral skupaj vse Izraelove prince, z duhovniki in Lévijevci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Torej Lévijevci so bili prešteti od starosti tridesetih let in navzgor. Njihovo število po njihovih glavah, oseb, je bilo osemintrideset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '»Izmed katerih je bilo štiriindvajset tisoč, da vodijo delo Gospodove hiše, šest tisoč pa je bilo častnikov in sodnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Poleg tega je bilo štiri tisoč vratarjev in štiri tisoč jih je hvalilo Gospoda z glasbili, ki sem jih naredil,« je rekel David, »da s temi hvalijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David jih je razdelil v skupine med Lévijeve sinove, namreč Geršóna, Keháta in Meraríja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Izmed Geršónovcev sta bila Ladán in Šimí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ladánovi sinovi: vodja je bil Jehiél, Zetám in Joél, trije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Šimíjevi sinovi: Šelomít, Haziél in Harán, trije. To so bili vodje Ladánovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Šimíjevi sinovi so bili: Jahat, Ziná, Jeúš in Berijá. Ti štirje so bili Šimíjevi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat je bil vodja, Zizá pa drugi, toda Jeúš in Berijá nista imela veliko sinov, zato sta bila v enem štetju, glede na hišo svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél, štirje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrámova sinova: Aron in Mojzes. Aron je bil odbran, da posvečuje najsvetejše stvari, on in njegovi sinovi na veke, da zažigajo kadilo pred Gospodom, da mu služijo in da v njegovem imenu blagoslavljajo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Torej glede Mojzesa, Božjega moža, njegovi sinovi so bili imenovani po Lévijevemu rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mojzesova sinova sta bila Geršóm in Eliézer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Od Geršómovih sinov je bil vodja Šebuél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliézerjevi sinovi so bili vodja Rehabjá. Eliézer pa ni imel nobenih drugih sinov, toda Rehabjájevih sinov je bilo zelo mnogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Izmed Jichárjevih sinov: vodja Šelomít.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Izmed Hebrónovih sinov: prvi Jerijá, drugi Amarjá, tretji Jahaziél in četrti Jekamám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Uziélova sinova: prvi Miha in drugi Jišijá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Meraríjeva sinova: Mahlí in Muší. Mahlíjeva sinova: Eleazar in Kiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar pa je umrl in ni imel sinov, temveč hčere in vzeli so jih njihovi bratje, Kiševi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Mušíjevi sinovi: Mahlí, Eder in Jeremót, trije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'To so bili Lévijevi sinovi po hiši svojih očetov, torej vodje očetov, kakor so bili prešteti po številu imen njihovih glav, ki so opravljali delo službe Gospodove hiše, od starosti dvajsetih let in navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Kajti David je rekel: » Gospod, Izraelov Bog, je svojemu ljudstvu dal počitek, da bi na veke lahko prebivali v Jeruzalemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'in tudi Lévijevcem; ne bodo več nosili šotorskega svetišča niti nobene njegove posode za njegovo službo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Kajti po zadnjih Davidovih besedah so bili Lévijevci prešteti od dvajsetih let starosti in naprej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'ker je bila njihova služba, da čakajo na Aronove sinove za službo Gospodovi hiši, na dvorih in v sobah in v očiščevanju vseh svetih stvari in delu službe Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Tako za hleb navzočnosti kakor za fino moko, za jedilno daritev in za nekvašene kolače in za tisto, kar je spečeno na ponvi in za to, kar je ocvrto in za vse vrste mer in velikosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'in da vsako jutro stojijo, da se zahvaljujejo in hvalijo Gospoda in prav tako zvečer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'In da vse žgalne daritve darujejo Gospodu na šabate, na mlaje in na določene praznike, po številu, glede na ukaz, ki jim je zapovedan, nenehno pred Gospodom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'in da naj se držijo zadolžitve šotorskega svetišča skupnosti in zadolžitve svetega kraja in zadolžitve Aronovih sinov, svojih bratov, v službi Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Torej to so oddelki Aronovih sinov. Aronovi sinovi: Nadáb, Abihú, Eleazar in Itamár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Toda Nadáb in Abihú sta umrla pred njunim očetom in nista imela otrok, zato sta duhovniško službo opravljala Eleazar in Itamár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'David jih je razdelil, tako Cadóka izmed Eleazarjevih sinov kot Ahiméleha izmed Itamárjevih sinov, glede na njihovo opravilo v njihovi službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Med Eleazarjevimi sinovi pa se je našlo več vodilnih mož kakor med Itamárjevimi sinovi; in tako so bili razdeljeni. Med Eleazarjevimi sinovi je bilo šestnajst vodilnih mož iz hiše njihovih očetov in osem med Itamárjevimi sinovi, glede na hišo njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Tako so bili razdeljeni z žrebom, ena vrsta z drugo; za upravitelje svetišča in upravitelje Božje hiše so bili izmed Eleazarjevih sinov in izmed Itamárjevih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Netanélov sin Šemajá, pisar, eden izmed Lévijevcev, jih je popisal pred kraljem, princi, duhovnikom Cadókom in Abjatárjevim sinom Ahimélehom in pred vodji očetov duhovnikov in Lévijevcev. Ena glavna družina je bila vzeta za Eleazarja in ena je bila vzeta za Itamárja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Torej prvi žreb je izšel za Jojaríba, drugi za Jedajája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'tretji za Haríma, četrti za Seoríma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'peti za Malkijája, šesti za Mijamína,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'sedmi za Koca, osmi za Abíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'deveti za Ješúa, deseti za Šehanjája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'enajsti za Eljašíba, dvanajsti za Jakíma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'trinajsti za Hupája, štirinajsti za Ješebába,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'petnajsti za Bilgája, šestnajsti za Imêrja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'sedemnajsti za Hezírja, osemnajsti za Hapicéca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'devetnajsti za Petahjája, dvajseti za Jehezkéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'enaindvajseti za Jahína, dvaindvajseti za Gamúla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'triindvajseti za Delajája, štiriindvajseti za Maazjája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'To so bili njihovi vrstni redi v njihovi službi, da pridejo v Gospodovo hišo, glede na njihov način, pod njihovim očetom Aronom, kakor mu je zapovedal Gospod, Izraelov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Preostali izmed Lévijevih sinov so bili tile: izmed Amrámovih sinov Šubaél, izmed Šubaélovih sinov Jehdejá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Glede Rehabjá, izmed sinov Rehabjá je bil prvi Jišijá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Izmed Jichárovcev Šelomot, izmed Šelomotovih sinov Jahat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Hebrónovi sinovi: prvi Jerijá, drugi Amarjá, tretji Jahaziél in četrti Jekamám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Izmed Uziélovih sinov Miha, izmed Mihovih sinov Šamír.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Mihov brat je bil Jišijá, izmed Jišijájevih sinov Zeharjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, '§ Meraríjevi sinovi so bili Mahlí in Muší. Jaazijájevi sinovi: Beno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, '§ Merarijevi sinovi po Jaazijáju: Beno, Šohám, Zahúr in Ibri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Iz Mahlíja je prišel Eleazar, ki ni imel sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Glede Kiša: Kišev sin je bil Jerahmeél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Tudi Mušíjevi sinovi: Mahlí, Eder in Jerimót. To so bili sinovi Lévijevcev po hiši njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Tudi ti so metali žrebe nasproti svojih bratov, Aronovih sinov, v prisotnosti kralja Davida, Cadóka, Ahiméleha in vodje očetov duhovnikov in Lévijevcev, celo glavnim očetom nasproti njihovim mlajšim bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Poleg tega so David in poveljniki vojske oddvojili k službi od Asáfovih, Hemánovih in Jedutúnovih sinov, ki naj bi prerokovali s harfami, s plunkami in s cimbalami. Število delavcev glede na njihovo službo je bilo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'izmed Asáfovih sinov Zahúr, Jožef, Netanjá in Asaréla, Asáfovi sinovi pod Asáfovo roko, ki so prerokovali glede na kraljev ukaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, '§ Od Jedutúna: Jedutúnovi sinovi Gedaljá, Cerí, Ješajá, Hašabjá, Matitjá, šest, pod rokami njihovega očeta Jedutúna, ki so prerokovali s harfo, da se zahvaljujejo in hvalijo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Od Hemána: Hemánovi sinovi Bukijá, Matanjá, Uziél, Šebuél, Jerimót, Hananjá, Hananí, Eliát, Gidálti, Romámti Ezer, Jošbekáša, Malóti, Hotír in Mahaziót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Vsi ti so bili sinovi kraljevega vidca Hemána v Božjih besedah, da dvigujejo rog. In Bog je dal Hemánu štirinajst sinov in tri hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Vsi ti so bili pod rokami njihovega očeta za pesem v Gospodovi hiši s cimbalami, plunkami in harfami, za službo Božje hiše, glede na kraljev ukaz Asáfu, Jedutúnu in Hemánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Tako je bilo njihovo število, z njihovimi brati, ki so bili poučeni v Gospodovih pesmih, celó vseh, ki so bili spretni, dvesto oseminosemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Metali so žrebe, stražo do straže, tako majhen kakor velik, učitelj kakor učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Torej prvi žreb je prišel za Asáfa k Jožefu; drugi Gedaljáju, katerih je bilo z njegovimi brati in sinovi dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'tretji Zahúrju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'četrti Izriju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'peti Netanjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'šesti Bukijáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'sedmi Jesarelu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'osmi Ješajáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'deveti Matanjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'deseti Šimíju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'enajsti Azarélu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'dvanajsti Hašabjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'trinajsti Šubaélu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'štirinajsti Matitjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'petnajsti Jeremótu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'šestnajsti Hananjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'sedemnajsti Jošbekášaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'osemnajsti Hananíju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'devetnajsti Malótiju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'dvajseti Eliátaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'enaindvajseti Hotírju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'dvaindvajseti Gidáltiju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'triindvajseti Mahaziótaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'štiriindvajseti Romámti Ezerju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Glede na oddelke vratarjev je bil od Kórahovcev Mešelemjá, sin Koréja izmed Asáfovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Mešelemjájevi sinovi so bili prvorojenec Zeharjá, drugi Jediaél, tretji Zebadjá, četrti Jatniél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'peti Elám, šesti Johanán, sedmi Eljoenáj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Poleg tega so bili Obéd Edómovi sinovi prvorojenec Šemajá, drugi Jozabád, tretji Joáh, četrti Sahár, peti Netanél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'šesti Amiél, sedmi Isahár in osmi Peuletáj, kajti Bog ga je blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Tudi njegovemu sinu Šemajáju so bili rojeni sinovi, ki so vladali po hiši svojih očetov, kajti bili so močni junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Šemajájevi sinovi: Otní, Refaél, Obéd, Elzabád, katerega bratje so bili močni možje, Elihú in Semahjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Vseh teh izmed Obéd Edómovih sinov in njihovih bratov, sposobnih mož za službo je bilo dvainšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Mešelemjá je imel sinove in brate, močne može, osemnajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Tudi Hosá, izmed Meraríjevih otrok, je imel sinove: vodja Šimrí, (kajti čeprav ni bil prvorojenec, ga je vendar njegov oče naredil za vodjo)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'drugi Hilkijá, tretji Tebaljá, četrti Zeharjá. Vseh sinov Hosájevih bratov je bilo trinajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Med temi so bili oddelki vratarjev, celó med vodilnimi možmi so imeli straže, da služijo eden nasproti drugemu v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Metali so žrebe, tako majhni kakor veliki, glede na hišo njihovih očetov, za vsaka velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Žreb proti vzhodu je zadel Šelemjája. Potem so metali žrebe za Zeharjá, njegovega sina, modrega svetovalca in njegov žreb je izšel proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Za Obéd Edóma in za njegove sinove od Asupimove hiše proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Šupímu in Hosáju je žreb izšel proti zahodu z velikimi vrati Šaléheta, pri tlakovani pešpoti vzpona, straža proti straži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Proti vzhodu je bilo šest Lévijevcev, štirje na dan proti severu, štirje na dan proti jugu in proti Asupimu dva in dva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, '§ Pri Parbarju proti zahodu, štirje pri tlakovani pešpoti in dva pri Parbarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'To so oddelki vratarjev med Koréjevimi sinovi in med Meraríjevimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Izmed Lévijevcev je bil Ahíja nad zakladnicami Božje hiše in nad zakladnicami posvečenih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Glede Ladánovih sinov: sinovi Geršónca Ladána, poglavarji očetov, celó od Geršónca Ladána, je bil Jehielí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jehielíjeva sinova: Zetám in njegov brat Joél, ki sta bila nad zakladnicami Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Izmed Amrámovcev, Jichárovcev, Hebróncev in Uziélovcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'je bil Šebuél, Geršómov sin, Mojzesov sin, vladar nad zakladnicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Njegovi bratje po Eliézerju: njegov sin Rehabjá, njegov sin Ješajá, njegov sin Jorám, njegov sin Zihrí in njegov sin Šelomít.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ta Šelomít in njegovi bratje so bili nad vsemi zakladnicami posvečenih stvari, ki so jih kralj David, vodje očetov, tisočniki, stotniki in poveljniki vojske posvetili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Od plenov, dobljenih v bitkah, so jih posvetili za vzdrževanje Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'In vse, kar so videc Samuel, Kišev sin Savel, Nerov sin Abnêr in Cerújin sin Joáb posvetili in kdorkoli je posvetil katerokoli stvar, so bile te pod roko Šelomíta in njegovih bratov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Izmed Jichárovcev so bili Kenanjá in njegovi sinovi za zunanja opravila nad Izraelom, za častnike in sodnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'In izmed Hebróncev Hašabjá in njegovi bratje, junaški možje, tisoč sedemsto, so bili častniki med tistimi iz Izraela na tej strani Jordana proti zahodu v vseh Gospodovih opravilih in v kraljevi službi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Med Hebrónovci je bil vodja Jerijá, torej med Hebrónovci glede na rodove svojih očetov. V štiridesetem letu Davidovega kraljevanja so jih iskali in med njimi so našli močne junaške može pri Jazêr Gileádu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Njegovih bratov, junaških mož, je bilo dva tisoč in sedemsto vodij očetov, ki jih je David postavil [za] vladarje nad Rubenovci, Gádovci in polovico Manásejevega rodu, za vsako zadevo glede Boga in kraljevih zadev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Torej Izraelovi otroci po njihovem številu, namreč vodja očetov poveljnikov nad tisočimi in nad stotimi in njihovi častniki, ki so služili kralju v vsaki zadevi oddelkov, ki so prihajali in odhajali mesec za mesecem, vse mesece leta; od vsakega oddelka jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad prvo skupino za prvi mesec je bil Zabdiélov sin Jašobám in v njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Izmed Perecovih otrok je bil vodja vseh poveljnikov vojske za prvi mesec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Nad skupino drugega meseca je bil Ahóahovec Dodáj in iz njegove skupine je bil tudi vladar Miklót. Tudi v njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Tretji poveljnik vojske za tretji mesec je bil Benajá, sin Jojadája, vélikega duhovnika in v njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'To je ta Benajá, ki je bil mogočen med tridesetimi in nad tridesetimi. V njegovi skupini je bil njegov sin Amizabád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Četrti poveljnik za četrti mesec je bil Joábov brat Asaél in za njim njegov sin Zebadjá. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Peti poveljnik za peti mesec je bil Zêrahovec Šamhút. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Šesti poveljnik za šesti mesec je bil Irá, sin Tekójčana Ikéša. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Sedmi poveljnik za sedmi mesec je bil Péletovec Helec, izmed Efrájimovih otrok. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmi poveljnik za osmi mesec je bil Hušán Sibeháj izmed Zerahovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Deveti poveljnik za deveti mesec je bil Abiézer Anatotčan izmed Benjaminovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Deseti poveljnik za deseti mesec je bil Netófčan Mahráj izmed Zerahovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Enajsti poveljnik za enajsti mesec je bil Piratónec Benajá izmed Efrájimovih otrok. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dvanajsti poveljnik za dvanajsti mesec je bil Netófčan Heldáj iz Otniéla. V njegovi skupini jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Nadalje je bil nad Izraelovimi rodovi vladar Rubenovcev Zihríjev sin Eliézer; izmed Simeoncev Maahájev sin Šefatjá;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'izmed Lévijevcev Kemuélov sin Hašabjá; izmed Aroncev Cadók;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'izmed Judovcev Elihú, eden izmed Davidovih bratov; izmed Isahárjevcev Mihaelov sin Omri;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'izmed Zábulonovcev Obadjájev sin Jišmajá; izmed Neftálijevcev Azriélov sin Jerimót;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'izmed Efrájimovih otrok Azazjájev sin Hošéa; izmed polovice Manásejevega rodu Pedajájev sin Joél;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'izmed polovice Manásejevega rodu v Gileádu Zaharijev sin Idó; izmed Benjaminovcev Abnêrjev sin Jaasiél;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'izmed Danovcev Jerohámov sin Azarél. Ti so bili princi Izraelovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Toda David ni preštel tistih, ki so bili stari dvajset let in mlajših, ker je Gospod rekel, da bo on pomnožil Izraela kakor zvezd neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Cerújin sin Joáb je začel šteti, toda ni končal, ker je zaradi tega padel bes zoper Izraela. Niti število ni bilo vpisano v poročilo kronik kralja Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Nad kraljevimi zakladnicami je bil Adiélov sin Azmávet. Nad skladišči, na poljih, v mestih, vaseh in gradovih je bil Uzíjahov sin Jehonatan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Nad tistimi, ki so opravljali poljsko delo obdelovanja zemlje, je bil Kelúbov sin Ezrí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Nad vinogradi je bil Ramatejec Šimí. Nad donosom vinogradov za vinske kleti je bil Šefámec Zabdí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nad oljkami in egiptovskimi smokvami, ki so bile na nizkih ravnicah, je bil Géderčan Báal Hanán. Nad shrambami olja je bil Joáš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Nad čredami, ki so se pasle v Šarónu, je bil Šarónec Šitráj. Nad čredami, ki so bile v dolinah, je bil Adlájev sin Šafát.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Nad kamelami je bil tudi Izmaelec Obíl. Nad osli je bil Meronočán Jehdejá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Nad tropi je bil Hagríjevec Jazíz. Vsi ti so bili vladarji imetja, ki je bilo od kralja Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Tudi Davidov stric Jonatan je bil svetovalec, moder mož in pisar. In Hahmoníjev sin Jehiél je bil s kraljevimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitófel je bil kraljev svetovalec in Arkéjec Hušáj je bil kraljev družabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Za Ahitófelom sta bila Benajájev sin Jojadá in Abjatár. General kraljeve vojske pa je bil Joáb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'David je zbral vse Izraelove prince, prince rodov in poveljnike skupin, ki so služili kralju po skupini in poveljnike nad tisočimi, poveljnike nad stotimi in oskrbnike nad vsem imetjem in posestjo kralja in njegovih sinov, s častniki in z mogočnimi možmi in z vsemi hrabrimi možmi v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Potem je kralj David stopil na svoja stopala in rekel: »Poslušajte me, moji bratje in moje ljudstvo: › Kar se mene tiče, sem imel v svojem srcu, da zgradim hišo počitka za skrinjo Gospodove zaveze in za pručko našega Boga in sem pripravil za gradnjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'toda Bog mi je rekel: ›Ne boš gradil hiše mojemu imenu, ker si bil bojevnik in si prelival kri.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Vendar je Gospod, Izraelov Bog, mene izbral pred vso hišo mojega očeta, da bi bil na veke kralj nad Izraelom, kajti Juda je izbral, da bi bil vladar; in od Judove hiše, hišo mojega očeta; in med sinovi mojega očeta sem mu bil všeč, da me je postavil za kralja nad vsem Izraelom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'in izmed vseh mojih sinov (kajti Gospod mi je dal mnogo sinov), je izbral mojega sina Salomona, da sedi na prestolu Gospodovega kraljestva nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Rekel mi je: ›Tvoj sin Salomon bo zgradil mojo hišo in moje dvore, kajti izbral sem ga, da bo moj sin in jaz bom njegov oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Poleg tega bom na veke utrdil njegovo kraljestvo, če bo stalno izpolnjeval moje zapovedi in moje sodbe, kakor ta dan.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Zdaj se torej pred očmi vsega Izraela, Gospodove skupnosti in v občinstvu našega Boga, držite in iščite vse zapovedi Gospoda, svojega Boga, da boste lahko posedli to dobro deželo in jo pustili za dediščino svojim otrokom za seboj na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Ti pa, moj sin Salomon, spoznaj Boga svojega očeta in mu služi s popolnim srcem in z voljnim umom, kajti Gospod preiskuje vsa srca in razume vse miselne zamisli. Če ga boš iskal, ga boš našel, toda če ga zapustiš, te bo on zavrgel na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Pazi torej, kajti Gospod te je izbral, da zgradiš hišo za svetišče. Bodi močan in to stôri.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Potem je David svojemu sinu Salomonu dal vzorec preddverja, njegovih hiš, njegovih zakladnic, njegovih gornjih sob, njegovih notranjih dvoran in kraja sedeža milosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'vzorec vsega, kar je imel po duhu glede dvorov Gospodove hiše in vseh sob naokoli, zakladnic Božje hiše in zakladnic posvečenih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Tudi za skupine duhovnikov in Lévijevcev in za vse delo službe Gospodove hiše in za vse posode službe v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Dal je zlata po teži za stvari iz zlata, za vse priprave vseh vrst službe; tudi srebra za vse priprave iz srebra po teži, za vse priprave vsake vrste službe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Celo težo za svečnike iz zlata in za njihove svetilke iz zlata po teži za vsak svečnik in za njihove svetilke. In za svečnike iz srebra po teži, tako za svečnik in tudi za njihove svetilke, glede na uporabo vsakega svečnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Po teži je dal zlata za mize hlebov navzočnosti za vsako mizo in podobno zlata za mize iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Tudi čistega zlata za kavlje za meso, skledice in čaše. Za zlate umivalnike je dal zlata po teži za vsak umivalnik; in podobno srebra, po teži za vsak umivalnik iz srebra;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Za kadilni oltar prečiščeno zlato po teži in zlata za vzorec bojnega voza kerubov, ki razprostirata svoje peruti in pokrivata skrinjo Gospodove zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '»Vse to,« je rekel David, »mi je Gospod dal razumeti v pisanju po svoji roki nad menoj, torej vsa dela tega vzorca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'David je rekel svojemu sinu Salomonu: »Bodi močan in odločnega poguma in stôri to. Ne boj se niti ne bodi zaprepaden, kajti Gospod Bog, celó moj Bog, bo s teboj. Ne bo te razočaral niti te ne bo zapustil, dokler ne dokončaš vsega dela za službo Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Glej, skupine duhovnikov in Lévijevcev, celo oni bodo s teboj za vso službo Božje hiše, in tam bo s teboj za vse vrste rokodelstva vsak voljan vešč mož, za vse vrste del. Tudi princi in vse ljudstvo bo popolno ob tvoji zapovedi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Nadalje je kralj David vsej skupnosti rekel: »Moj sin Salomon, ki ga je izbral sam Bog, je še mlad in nežen, delo pa je veliko, kajti palača ni za človeka, temveč za Gospoda Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Sedaj sem z vso svojo močjo pripravil za hišo svojega Boga zlata za stvari, narejene iz zlata, srebra za stvari iz srebra, brona za stvari iz brona, železa za stvari iz železa, lesa za stvari iz lesa, oniksove kamne in kamne za vdelavo, lesketajoče kamne iz različnih barv in vse vrste dragocenih kamnov in marmornih kamnov v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Povrh vsega, ker sem svojo naklonjenost naravnal k hiši svojega Boga, sem dal od svojih lastnih dobrin, od zlata in srebra, ki sem ga dal k hiši svojega Boga, poleg vsega, kar sem pripravil za sveto hišo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'celó tri tisoč talentov zlata, od zlata iz Ofírja in sedem tisoč talentov prečiščenega srebra, da se z njim prekrije stene hiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Zlata za stvari iz zlata, srebra za stvari iz srebra in za vsako vrsto dela storjenega z rokodelčevimi rokami. In kdo bo potem ta dan voljan uméstiti svojo službo Gospodu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Potem so vodje očetov in princev iz Izraelovega rodu in poveljniki nad tisočimi in nad stotimi, z voditelji kraljevega dela, prostovoljno darovali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'in dali za službo Božje hiše od zlata pet tisoč talentov in deset tisoč darejkov, od srebra deset tisoč talentov, od brona osemnajst tisoč talentov in sto tisoč talentov železa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Tisti, pri katerih so bili najdeni dragoceni kamni, so jih dali v zakladnico Gospodove hiše po roki Geršónca Jehiéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Potem se je ljudstvo veselilo, za to, kar so voljno darovali, ker so s popolnim srcem voljno darovali Gospodu. Tudi kralj David se je veselil z veliko radostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Zato je David blagoslovil Gospoda pred vso skupnostjo in David je rekel: »Blagoslovljen bodi ti, Gospod, Bog Izraela, našega očeta, na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tvoja, oh Gospod, je veličina, oblast, slava, zmaga in veličastvo, kajti vse, kar je v nebesih in na zemlji, je tvoje. Tvoje je kraljestvo, oh Gospod in ti si kakor glava povišan nad vse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Bogastvo in čast, oboje prihaja od tebe in ti kraljuješ nad vsem in v tvoji roki je oblast in moč in v tvoji roki je to, da narediš veliko in da daš moč vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Zdaj torej, naš Bog, se ti zahvaljujemo in hvalimo tvoje veličastno ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Toda kdo sem jaz in kaj je moje ljudstvo, da bi bili zmožni darovati tako voljno na takšen način? Kajti vse stvari prihajajo od tebe in od tvojega lastnega smo dali tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Kajti mi smo tujci pred teboj in začasni prebivalci, kakor so bili vsi naši očetje. Naši dnevi na zemlji so kakor senca in nobenega ni, ki bi ostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Oh Gospod, naš Bog, vsa ta zaloga, ki smo jo pripravili, da ti zgradimo hišo za tvoje sveto ime, prihaja iz tvoje roke in vse je tvoje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Tudi jaz vem, moj Bog, da ti preizkušaš srce in imaš veselje v iskrenosti. Kar se mene tiče, sem v iskrenosti svojega srca voljno daroval vse te stvari in sedaj sem z radostjo videl tvoje ljudstvo, ki je tukaj prisotno, da ti voljno daruje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Oh Gospod, Bog Abrahama, Izaka in Izraela, naših očetov, varuj to na veke v zamisli misli srca svojega ljudstva in si pripravi njihovo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Mojemu sinu Salomonu daj popolno srce, da varuje tvoje zapovedi, tvoja pričevanja in tvoje zakone in da stori vse te stvari in da zgradi palačo, za katero sem naredil preskrbo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'David je vsej skupnosti rekel: »Sedaj blagoslovite Gospoda, svojega Boga.« In vsa skupnost je blagoslovila Gospoda, Boga svojih očetov, sklonila svoje glave in oboževala Gospoda in kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Žrtvovali so klavne daritve Gospodu in darovali so žgalne daritve Gospodu naslednji dan po tem dnevu, celó tisoč bikcev, tisoč ovnov in tisoč jagnjet, z njihovimi pitnimi daritvami in v obilju klavnih daritev za ves Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Z velikim veseljem so na ta dan jedli in pili pred Gospodom. Kralja Salomona, Davidovega sina, so drugič postavili za kralja, ga mazilili Gospodu za glavnega voditelja, Cadóka pa za duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Potem se je Salomon usedel na Gospodov prestol kakor kralj namesto svojega očeta Davida in uspeval in ves Izrael ga je ubogal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Vsi princi in mogočni možje in tudi vsi sinovi kralja Davida so se podredili kralju Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Gospod je silno poveličal Salomona v očeh vsega Izraela in mu podelil takšno kraljevo veličastvo, kakršno ni bilo v Izraelu na nobenem kralju pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Tako je Jesejev sin David kraljeval nad vsem Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Časa, ko je kraljeval nad Izraelom, je bilo štirideset let. Sedem let je kraljeval v Hebrónu, triintrideset let pa je kraljeval v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Umrl je v dobri visoki starosti, izpolnjen z dnevi, bogastvi in častjo. Namesto njega je zakraljeval njegov sin Salomon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Torej dejanja kralja Davida, prva in zadnja, glej, ta so zapisana v knjigi vidca Samuela, v knjigi preroka Natána in v knjigi vidca Gada,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'z vsem njegovim vladanjem in njegovo močjo in časi, ki so prešli nad njim in nad Izraelom in nad vsemi kraljestvi dežel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Davidov sin Salomon je bil okrepljen v svojem kraljestvu in Gospod, njegov Bog, je bil z njim in ga silno poveličal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Potem je Salomon spregovoril vsemu Izraelu, poveljnikom nad tisočimi, nad stotimi, sodnikom, vsakemu voditelju v vsem Izraelu in glavnim izmed očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Tako je Salomon in vsa skupnost z njim, odšla k visokemu kraju, ki je bil pri Gibeónu, kajti tam je bilo šotorsko svetišče skupnosti Boga, ki ga je Gospodov služabnik Mojzes naredil v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Toda Božjo skrinjo je David prenesel gor iz Kirját Jearíma na kraj, ki ga je David pripravil zanjo, kajti zanjo je razpel šotor pri Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Poleg tega je bronast oltar, ki ga je naredil Becalél, Urijájev sin, Hurov sin, postavil pred Gospodovo šotorsko svetišče. Salomon in skupnost so povpraševali k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Salomon je odšel tja gor k bronastemu oltarju pred Gospoda, ki je bil pri šotorskem svetišču skupnosti in na njem daroval tisoč žgalnih daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'V tej noči se je Bog prikazal Salomonu in mu rekel: »Prosi, kaj naj ti dam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomon je Bogu rekel: »Veliko usmiljenje si pokazal mojemu očetu Davidu in mene si postavil, da kraljujem namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Sedaj, oh Gospod Bog, naj bo utrjena tvoja obljuba mojemu očetu Davidu, kajti naredil si me za kralja nad ljudstvom, po množici podobnega zemeljskemu prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Daj mi torej modrost in znanje, da lahko grem ven in stopim pred ljudstvo, kajti kdo lahko sodi to tvoje ljudstvo, ki je tako veliko?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Bog je rekel Salomonu: »Ker je bilo to na tvojem srcu in nisi prosil bogastev, premoženja ali časti, niti življenja svojih sovražnikov, niti nisi prosil dolgega življenja, temveč si zase prosil modrost in znanje, da lahko sodiš mojemu ljudstvu, nad katerim sem te postavil za kralja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'sta ti modrost in znanje zagotovljena, jaz pa ti bom dal bogastva, premoženje in čast, takšno, kakršne nihče izmed kraljev, ki so bili pred teboj, ni imel niti ne bo nobeden za teboj imel podobne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Potem je Salomon prišel iz svojega potovanja k visokemu kraju, izpred šotorskega svetišča skupnosti, ki je bil pri Gibeónu, v Jeruzalem in kraljeval nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomon je zbral bojne vozove in konjenike. Imel je tisoč štiristo bojnih vozov in dvanajst tisoč konjenikov, ki jih je namestil v mestih za bojne vozove in s kraljem v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Kralj je storil, [da je bilo] srebra in zlata v Jeruzalemu zaradi obilja tako veliko, kakor kamenja in cedrova drevesa je naredil [tako številna] kakor je egiptovskih smokev, ki so v dolini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Salomon je imel konje, privedene iz Egipta in laneno prejo. Kraljevi trgovci so laneno prejo prejeli za ceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Poslali so in iz Egipta pripeljali bojni voz za šeststo šeklov srebra in konja za sto petdeset in tako so privedli konje za vse kralje Hetejcev in za sirske kralje, po njihovih namenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Salomon se je odločil, da zgradi hišo za Gospodovo ime in hišo za svoje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Salomon je naročil sedemdeset tisoč možem, da nosijo bremena in osemdeset tisočim, da sekajo na gori in tri tisoč šeststotim, da jih nadzorujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Salomon je poslal k tirskemu kralju Hurámu, rekoč: »Kakor si ti postopal z mojim očetom Davidom in si mu poslal cedre, da mu zgradijo hišo, da prebiva v njej, celo tako postopaj z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Glej, gradim hišo imenu Gospoda, svojega Boga, da mu jo posvetim in da pred njim zažigam dišeče kadilo in za neprestane hlebe navzočnosti, za žgalne daritve zjutraj in zvečer, na šabate, na mlaje in na slovesne praznike Gospoda, našega Boga. To je odredba za Izraela na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Hiša, ki jo gradim, je velika, kajti velik je naš Bog nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Toda kdo mu je zmožen zgraditi hišo, glede na to, da ga nebo in nebesa nebes ne morejo obseči? Kdo sem potem jaz, da bi mu zgradil hišo, razen da pred njim zažigam daritev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Pošlji mi torej sedaj človeka, spretnega za delo v zlatu, v srebru, v bronu, v železu, v vijolični, v karmezinu in modri in da lahko vešče rezbari z veščimi možmi, ki so z menoj v Judeji in v Jeruzalemu, ki jih je priskrbel moj oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Pošlji mi tudi cedrovino, cipresovino in sandalovino iz Libanona, kajti vem, da tvoji služabniki lahko vešče sekajo les na Libanonu in glej, moji služabniki bodo s tvojimi služabniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'celo, da mi pripravijo lesa v obilju, kajti hiša, ki jo nameravam zgraditi, bo čudovito velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Glej, tvojim služabnikom, sekalcem, ki sekajo les, bom dajal dvajset tisoč mer zmlete pšenice, dvajset tisoč mer ječmena, dvajset tisoč čebrov vina in dvajset tisoč čebrov olja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Potem je tirski kralj Hurám odgovoril v pisanju, ki ga je poslal Salomonu: ›Ker Gospod ljubi svoje ljudstvo, te je naredil kralja nad njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Poleg tega je Hurám rekel: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je naredil nebo in zemljo, ki je kralju Davidu dal modrega sina, opremljenega z razumnostjo in razumevanjem, da lahko gradi hišo za Gospoda in hišo za svoje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, '§ Sedaj pošiljam spretnega moža, opremljenega z razumevanjem, od mojega očeta Huráma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'sina ženske izmed Danovih hčera, njegov oče pa je bil človek iz Tira, vešč, da dela v zlatu, srebru, bronu, železu, kamnu, lesu, vijoličnem, modrem, tankem lanenem platnu in v karmezinu. Tudi da gravira vsako vrsto graviranja in da spozna vsako napravo, ki bo postavljena k njemu, s tvojimi spretnimi ljudmi in s spretnimi ljudmi mojega gospoda Davida, tvojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Zdaj naj torej pšenico, ječmen in vino, o katerem je govoril moj gospod, pošlje svojim služabnikom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'mi pa bomo sekali les iz Libanona, kolikor ga boš potreboval in ga k tebi spravili na splavih po morju v Jopo, ti pa ga boš odpeljal gor v Jeruzalem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Salomon je preštel vse tujce, ki so bili v deželi Izrael, po štetju, s katerim jih je preštel njegov oče David in najdenih je bilo sto triinpetdeset tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Sedemdeset tisoč izmed njih je postavil, da bodo nosilci bremen in osemdeset tisoč, da bodo sekalci na gori in tri tisoč šeststo nadzornikov, da ljudstvu pripravljajo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Potem je Salomon začel graditi Gospodovo hišo v Jeruzalemu na gori Moríja, kjer se je Gospod prikazal njegovemu očetu Davidu, na kraju, ki ga je David pripravil – na mlatišču Jebusejca Ornana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Začel je graditi drugi dan drugega meseca v četrtem letu svojega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Torej to so stvari, v katerih je bil Salomon poučen za gradnjo Božje hiše. Dolžina po komolcih, po prvi meri, je bila šestdeset komolcev in širina dvajset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Preddverje, ki je bilo pred hišo, dolžina tega je bila glede na širino hiše, dvajset komolcev in višina je bila sto dvajset. Znotraj je bila prevlečena s čistim zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Večjo hišo je obložil s cipresovino, jo prevlekel s čistim zlatom in na njej oblikoval palmova drevesa in verižice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Hišo je zaradi lepote olepšal z dragocenimi kamni in zlato je bilo zlato iz Parvájima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Z zlatom je prevlekel tudi hišo, bruna, podboje, njihove zidove in njihova vrata in na stene je vrezal kerube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Naredil je najsvetejšo hišo, katere dolžina je bila glede na širino hiše, dvajset komolcev in njena širina dvajset komolcev in prevlekel jo je s čistim zlatom, kar znese šeststo talentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Teža žebljev je bila petdeset šeklov zlata. In gornje sobe je prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'V najsvetejši hiši je naredil dva keruba iz rezbarskega dela in ju prevlekel z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Peruti kerubov so bile dolge dvajset komolcev. Ena perut enega keruba je imela pet komolcev, segajoč do stene hiše in druga perut je prav tako imela pet komolcev, segajoč do peruti drugega keruba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Ena perut drugega keruba je imela pet komolcev in je segala do stene hiše in druga perut je tudi imela pet komolcev in se dotikala peruti drugega keruba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Peruti teh kerubov so se [v širino] razprostirala dvajset komolcev. Stala sta na njunih stopalih in njuna obraza sta bila [obrnjena] navznoter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Naredil je zagrinjalo iz modre, vijolične, karmezina in tankega lanenega platna ter na njem oblikoval kerube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Prav tako je pred hišo naredil dva stebra, visoka petintrideset komolcev in kapitel, ki je bil na vrhu vsakega izmed njih, je meril pet komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Naredil je verižice kakor v oraklju in jih pritrdil na glave stebrov in naredil sto granatnih jabolk ter jih pritrdil na verižice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Pred templjem je vzdignil stebra, enega na desnici, drugega pa na levici. Ime tega na desnici je imenoval Jahín, ime tistega na levici pa Boaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Poleg tega je naredil oltar iz brona, dvajset komolcev dolg, dvajset komolcev širok in deset komolcev visok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Prav tako je naredil ulito morje desetih komolcev od roba do roba, okroglo naokoli in pet komolcev je bila njegova višina in vrvica tridesetih komolcev ga je obdajala naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Pod tem je bila podobnost volov, ki so ga obdajali naokoli. Deset na komolec, obdajajoč morje naokoli. Dve vrsti volov sta bili uliti, ko je bilo to ulito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Stalo je na dvanajstih volih, trije so gledali proti severu, trije so gledali proti zahodu, trije so gledali proti jugu in trije so gledali proti vzhodu. Morje je bilo postavljeno zgoraj nad njimi in vsi njihovi zadnji deli so bili [obrnjeni] navznoter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Njegova debelina je bila širina dlani in njegov rob, podoben robu čaše, s cvetovi lilij in ta je sprejel in držal tri tisoč čebrov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Naredil je tudi deset [okroglih] umivalnikov in pet jih je položil na levo roko, pet pa na desno, da so se umivali v njih. Takšne stvari, kot so jih darovali za žgalno daritev, so umivali v njih, toda morje je bilo, da so se v njem umivali duhovniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Naredil je deset svečnikov iz zlata glede na njihovo obliko in jih postavil v templju, pet na desni roki in pet na levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Naredil je tudi deset miz in jih postavil v templju, pet na desni strani in pet na levi. Naredil je sto umivalnikov iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Nadalje je naredil dvor duhovnikov in velik dvor in vrata za dvor in jih prevlekel z bronom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Morje je postavil na desni strani vzhodnega konca, nasproti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Hurám je naredil lonce, lopate in umivalnike. Hurám je končal delo, ki ga je imel za opraviti za kralja Salomona za Božjo hišo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'namreč dva stebra in zaobljena glaviča in kapitele, ki so bili na vrhu dveh stebrov; dve mreži, da pokrijeta dva zaobljena glaviča kapitelov, ki so bili na vrhu stebrov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'štiristo granatnih jabolk na dveh mrežah; dve vrsti granatnih jabolk na vsakem vencu, da pokrijeta dva zaobljena glaviča kapitelov, ki sta bila na stebrih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Naredil je tudi podstavke in na podstavkih je naredil [okrogle] umivalnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Eno morje in dvanajst volov pod njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Tudi lonce, lopate, kavlje za meso in vse njihove priprave je Hirám, njegov oče, pripravil za kralja Salomona za Gospodovo hišo iz svetlega brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Na jordanski ravnini jih je kralj ulil, v ilovnati zemlji med Sukótom in Cerédo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Tako je Salomon naredil vseh teh posod v velikem obilju, kajti teže brona niso mogli ugotoviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomon je naredil vse te posode, ki so bile za Božjo hišo, tudi zlati oltar in mize, na katerih so bili postavljeni hlebi navzočnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'poleg tega svečnike s svojimi svetilkami, ki naj bi po navadi gorele pred orakljem iz čistega zlata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'cvetove, svetilke in utrinjače, narejene iz zlata in to popolnega zlata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'utrinjala, umivalnike, žlice in kadilnice iz čistega zlata. Vhod hiše, njegova notranja vrata za najsvetejši prostor in vrata hiše templja, so bila iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Tako je bilo vse delo, ki ga je Salomon naredil za Gospodovo hišo, končano. Salomon je prinesel noter vse stvari, ki jih je njegov oče David posvetil: srebro, zlato in vse priprave je položil med zaklade Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Potem je Salomon zbral Izraelove starešine in vse poglavarje rodov, vodilne izmed očetov Izraelovih otrok v Jeruzalem, da prenesejo gor skrinjo Gospodove zaveze iz Davidovega mesta, ki je Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Zato so se vsi možje iz Izraela zbrali skupaj h kralju na prazniku, ki je bil v sedmem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Prišli so vsi starešine Izraela in Lévijevci so dvignili skrinjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Skrinjo so prinesli gor, šotorsko svetišče skupnosti in vse svete posode, ki so bile v šotorskem svetišču, te so duhovniki in Lévijevci prinesli gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Tudi kralj Salomon in vsa Izraelova skupnost, ki so bili zbrani k njemu pred skrinjo, so žrtvovali ovce in vole, ki jih zaradi množice ni bilo mogoče prešteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Duhovniki so prinesli skrinjo Gospodove zaveze na njen kraj, k oraklju hiše, v najsvetejši kraj, celo pod peruti kerubov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Kajti keruba sta svoje peruti razširjala nad prostorom skrinje in keruba sta od zgoraj pokrivala skrinjo in njena drogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Iz skrinje so izvlekli drogova, da sta bila konca drogov vidna od skrinje pred orakljem, toda od zunaj nista bila vidna. In tam je to do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'V skrinji ni bilo ničesar razen dveh tabel, ki ju je Mojzes položil vanjo pri Horebu, ko je Gospod sklenil zavezo z Izraelovimi otroki, ko so prišli iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'In pripetilo se je, ko so duhovniki prišli iz svetega kraja (kajti vsi duhovniki, ki so bili prisotni, so bili posvečeni in takrat niso potem čakali po skupini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Tudi Lévijevci, ki so bili pevci, vsi izmed njih od Asáfa, Hemána in Jedutúna, z njihovimi sinovi in njihovimi brati, ki so bili oblečeni v belo platno ter imeli cimbale, plunke in harfe, so stali na vzhodnem koncu oltarja in z njimi sto dvajset duhovnikov, ki so trobili s trobentami.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Zgodilo se je celo, ko so bili trobentači in pevci kakor eno, da naredijo en zvok, da se ga sliši v hvaljenju in zahvaljevanju Gospodu, in ko so povzdignili svoj glas s trobentami, cimbalami in glasbenimi instrumenti ter hvalili Gospoda, rekoč: »Ker je dober, kajti njegovo usmiljenje traja večno,« da je bila potem hiša, napolnjena z oblakom, torej Gospodova hiša,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'tako da duhovniki zaradi oblaka niso mogli stati, da bi služili, kajti Gospodova slava je napolnila Božjo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Potem je Salomon rekel: » Gospod je rekel, da bo prebival v gosti temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Toda jaz sem zate zgradil hišo prebivališča in prostor za tvoje prebivanje na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Kralj je obrnil svoj obraz in blagoslovil celotno Izraelovo skupnost in celotna Izraelova skupnost je stala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Rekel je: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je s svojimi rokami izpolnil to, kar je s svojimi usti govoril mojemu očetu Davidu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '›Od dneva, ko sem svoje ljudstvo privedel iz egiptovske dežele, nisem izbral nobenega mesta med vsemi Izraelovimi rodovi, da bi v njem zgradil hišo, da bi bilo tam lahko moje ime niti nisem izbral nobenega človeka, da bi bil vladar nad mojim ljudstvom Izraelom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'toda izbral sem Jeruzalem, da bo tam lahko moje ime in izbral sem Davida, da bo nad mojim ljudstvom Izraelom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Torej, to je bilo na srcu mojega očeta Davida, da zgradi hišo za ime Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Toda Gospod je mojemu očetu Davidu rekel: ›Ker je bilo to na tvojem srcu, da zgradiš hišo za moje ime, si storil dobro v tem, da je bilo to na tvojem srcu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'vendar hiše ne boš gradil ti, temveč tvoj sin, ki bo izšel iz tvojih ledij, on bo zgradil hišo za moje ime.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Gospod je torej izpolnil svojo besedo, ki jo je govoril, kajti vzdignjen sem na mesto svojega očeta Davida in postavljen sem na Izraelov prestol, kakor je obljubil Gospod in zgradil sem hišo za ime Gospoda, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Vanjo sem položil skrinjo, v kateri je Gospodova zaveza, ki jo je sklenil z Izraelovimi otroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Stal je pred Gospodovim oltarjem v prisotnosti vse Izraelove skupnosti in razprostrl svoji roki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'kajti Salomon je naredil bronast oder, pet komolcev dolg, pet komolcev širok in tri komolce visok ter ga postavil v sredo dvora. Na njem je stal in pokleknil na svoja kolena pred vso Izraelovo skupnostjo in svoji roki razprostrl proti nebu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'in rekel: »Oh Gospod, Izraelov Bog, tebi ni podobnega Boga ne v nebesih, ne na zemlji, ki se držiš zaveze in izkazuješ usmiljenje svojim služabnikom, ki z vsemi svojimi srci hodijo pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ti, ki si ohranil svojemu služabniku Davidu, mojemu očetu, to, kar si mu obljubil in govoriš s svojimi usti in si to izpolnil s svojo roko, kakor je to danes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Zdaj torej, oh Gospod, Izraelov Bog, ohrani svojemu služabniku Davidu, mojemu očetu, to, kar si mu obljubil, rekoč: ›Ne bo ti zmanjkalo moža v mojem pogledu, da sedi na Izraelovem prestolu, vendar tako, da bodo tvoji otroci pazili na svojo pot, da hodijo po moji postavi, kakor si ti hodil pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Sedaj torej, oh Gospod, Izraelov Bog, naj bo tvoja beseda, ki si jo govoril svojemu služabniku Davidu, podprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Toda mar bo Bog zagotovo prebival z ljudmi na zemlji? Glej, nebo in nebesa nebes te ne morejo vsebovati, kako veliko manj ta hiša, ki sem jo zgradil!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Ozri se na molitev svojega služabnika in k njegovi ponižni prošnji, oh Gospod, moj Bog, da prisluhneš joku in molitvi, ki jo tvoj služabnik moli pred teboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'da bodo tvoje oči lahko odprte nad to hišo podnevi in ponoči, na kraju, o katerem si rekel, da boš tam položil svoje ime, da prisluhneš molitvi, ki jo tvoj služabnik moli proti temu kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Prisluhni torej ponižnim prošnjam svojega služabnika in svojega ljudstva Izraela, ki jih bodo naredili proti temu kraju. Poslušaj iz svojega prebivališča, celó iz nebes in ko slišiš, odpusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Če človek greši zoper svojega bližnjega in je prisega položena nanj, ki ga primora priseči in prisega pride pred tvoj oltar v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'potem poslušaj iz nebes, stori in sodi [med] svojima služabnikoma s povračilom zlobnemu, tako da položiš njegovo pot na njegovo lastno glavo in opravičiš pravičnega, tako da mu daš glede na njegovo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Če bo tvoje ljudstvo Izrael poraženo pred sovražnikom, ker so grešili zoper tebe in se bo vrnilo ter priznalo tvoje ime in molilo in naredilo ponižno prošnjo pred teboj v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'tedaj prisluhni iz nebes in odpusti greh svojega ljudstva Izraela ter jih ponovno privedi v deželo, ki si jo dal njim in njihovim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Ko je nebo zaprto in ni dežja, ker so grešili zoper tebe; vendar če molijo proti temu kraju in priznajo tvoje ime in se odvrnejo od svojega greha, ko si jih prizadel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'potem poslušaj iz nebes in odpusti greh svojih služabnikov in svojega ljudstva Izraela, ko si jih učil dobre poti, po kateri naj bi hodili in pošlji dež na svojo deželo, ki si jo dal svojemu ljudstvu za dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Če bo v deželi pomanjkanje, kužna bolezen, če bo kvarjenje ali plesen, leteče kobilice ali gosenice, če jih njihovi sovražniki oblegajo v mestih njihove dežele, kakršenkoli udarec ali kakršnakoli bolezen bo tam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'potem kakršnakoli molitev ali kakršnakoli ponižna prošnja bo narejena od kateregakoli človeka ali od vsega tvojega ljudstva Izraela, ko bo vsak spoznal svoj lastni udarec in svojo lastno bolečino in bo razprostrl svoji roki v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'tedaj prisluhni iz nebes, svojega prebivališča, odpusti in povrni vsakemu človeku glede na njegove lastne poti, katerega srce ti poznaš (kajti samo ti poznaš srca človeških otrok),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'da se te bodo lahko bali, da hodijo po tvojih poteh tako dolgo, dokler živijo v deželi, ki si jo dal našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Poleg tega glede tujca, ki ni iz tvojega ljudstva Izraela, temveč je prišel iz daljne dežele zaradi tvojega velikega imena, tvoje mogočne roke in tvojega iztegnjenega lakta; če pridejo in molijo v tej hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'tedaj prisluhni iz nebes, celó iz svojega prebivališča in stôri glede na vse, za kar tujec kliče k tebi, da bo vse ljudstvo zemlje poznalo tvoje ime in se te balo kakor tvoje ljudstvo Izrael in bo lahko vedelo, da je ta hiša, ki sem jo zgradil, imenovana po tvojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Če gre tvoje ljudstvo na vojno zoper svoje sovražnike po poti, po kateri jih boš poslal in molijo k tebi obrnjeni k temu mestu, ki si ga izbral in k hiši, ki sem jo zgradil za tvoje ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'tedaj prisluhni iz nebes njihovi molitvi in njihovim ponižnim prošnjam ter obravnavaj njihov primer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Če grešijo zoper tebe (kajti nobenega človeka ni, ki ne greši) in si jezen nad njimi in jih izročiš pred njihove sovražnike in jih oni ujete odvedejo v deželo daleč proč ali blizu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'vendar če si premislijo v deželi, kamor so odvedeni ujetniki in se obrnejo in molijo k tebi v deželi svojega ujetništva, rekoč: ›Grešili smo, napačno smo storili in počeli zlobno;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'če se vrnejo k tebi z vsem svojim srcem in z vso svojo dušo, v deželi svojega ujetništva, kamor so jih odvedli ujete in molijo k njihovi deželi, ki si jo dal njihovim očetom in k mestu, ki si ga izbral in k hiši, ki sem jo zgradil za tvoje ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'tedaj prisluhni iz nebes, celó iz svojega prebivališča, njihovi molitvi in njihovim ponižnim prošnjam in obravnavaj njihov primer in odpusti svojemu ljudstvu, ki je grešilo zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Sedaj, moj Bog, naj bodo, rotim te, tvoje oči odprte in naj bodo tvoja ušesa pozorna na molitev, ki je narejena na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Sedaj torej vzdigni se, oh Gospod Bog, v svoje počivališče, ti in skrinja tvoje moči. Naj bodo tvoji duhovniki, oh Gospod Bog, oblečeni z rešitvijo duš in naj se tvoji sveti veselijo v dobroti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Oh Gospod Bog, svojega obraza ne obrni od svojega maziljenca. Spomni se usmiljenj svojega služabnika Davida.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Torej ko je Salomon molitvi naredil konec, je z neba prišel ogenj in použil žgalno daritev in klavne daritve in Gospodova slava je napolnila hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Duhovniki niso mogli vstopiti v Gospodovo hišo, ker je Gospodova slava napolnila Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Ko so vsi Izraelovi otroci videli, kako je ogenj prišel dol in Gospodova slava na hišo, so se s svojimi obrazi priklonili do tal na tlak in oboževali ter hvalili Gospoda, rekoč: »Ker je dober, kajti njegovo usmiljenje traja večno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Potem so kralj in vse ljudstvo darovali klavne daritve pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Kralj Salomon je daroval klavno daritev dvaindvajsetih tisočev volov in sto dvanajst tisočev ovc. Tako sta kralj in vse ljudstvo posvetila Božjo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Duhovniki so čakali na svoje službe. Tudi Lévijevci z Gospodovimi glasbenimi instrumenti. Izdelal jih je kralj David, da hvali Gospoda, kajti njegovo usmiljenje traja večno. Ko je David hvalil ob njihovem služenju in so duhovniki pred njimi trobili s trobentami, je ves Izrael stal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Poleg tega je Salomon posvetil sredino dvora, ki je bil pred Gospodovo hišo, kajti tam je daroval žgalne daritve in tolščo mirovnih daritev, ker bronast oltar, ki ga je Salomon naredil, ni zmogel sprejeti žgalnih daritev, jedilnih daritev in tolšče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Prav tako je ob tem času Salomon praznik praznoval sedem dni in ves Izrael z njim, zelo velik shod, od vstopa v Hamát do egiptovske reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Na osmi dan so naredili slovesen zbor, kajti sedem dni so praznovali posvetitev oltarja in sedem dni so praznovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Na triindvajseti dan sedmega meseca je ljudstvo poslal proč, v njihove šotore, vesele in razigrane v srcu, zaradi dobrote, ki jo je Gospod pokazal Davidu, Salomonu in njegovemu ljudstvu Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tako je Salomon končal Gospodovo hišo in kraljevo hišo in vse, kar je prišlo v Salomonovo srce, da naredi v Gospodovi hiši in v svoji lastni hiši, je uspešno izvršil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Gospod se je Salomonu prikazal ponoči in mu rekel: »Slišal sem tvojo molitev in ta kraj sem izbral zase, za hišo klavne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Če zaprem nebo, da ne bo dežja ali če zapovem kobilicam, da požrejo deželo ali če med svoje ljudstvo pošljem kužno bolezen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'če se bo moje ljudstvo, ki je imenovano po mojem imenu, ponižalo, molilo, iskalo moj obraz in se odvrnilo od svojih zlobnih poti, takrat bom prisluhnil iz nebes, odpustil njihov greh in ozdravil njihovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Sedaj bodo moje oči odprte in moja ušesa pozorna na molitev, ki je narejena na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Kajti sedaj sem izbral in posvetil to hišo, da bo moje ime lahko tam na veke. Moje oči in moje srce bodo neprestano tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Kar se tiče tebe, če hočeš hoditi pred menoj, kakor je hodil tvoj oče David in storiti glede na vse, kar sem ti zapovedal in boš obeleževal moje zakone in moje sodbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'tedaj bom utrdil prestol tvojega kraljestva, glede na to, kakor sem se zavezal s tvojim očetom Davidom, rekoč: ›Ne bo ti manjkal mož, da bi bil vladar v Izraelu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Toda če se odvrnete in zapustite moje zakone in moje zapovedi, ki sem jih postavil pred vas in boste šli ter služili drugim bogovom in jih oboževali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'potem jih bom s koreninami izpulil iz svoje dežele, ki sem jim jo dal in to hišo, ki sem jo posvetil za svoje ime, bom vrgel iz svojega pogleda in jo naredil, da bo pregovor in tarča posmeha med vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Ta hiša, ki je visoka, bo osuplost vsakemu, ki gre mimo nje, tako da bo rekel: ›Zakaj je Gospod tako storil tej deželi in tej hiši?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'To bo odgovor: ›Ker so zapustili Gospoda, Boga svojih očetov, ki jih je privedel ven iz egiptovske dežele in se prijeli drugih bogov, jih oboževali in jim služili. Zato je nanje privedel vse to zlo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Pripetilo se je ob koncu dvajsetih let, v katerih je Salomon zgradil Gospodovo hišo in svojo lastno hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'da je mesta, ki jih je Hurám povrnil Salomonu, Salomon pozidal in Izraelovim otrokom velel, da prebivajo tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Salomon je odšel v Hamát Cobo in prevladal zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Zgradil je Tadmór v divjini in vsa skladiščna mesta, ki jih je zgradil v Hamátu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Zgradil je tudi zgornji Bet Horón in spodnji Bet Horón, utrjeni mesti, z obzidji, velikimi vrati in zapahi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'ter Baalát in vsa skladiščna mesta, ki jih je imel Salomon in vsa mesta bojnih vozov in mesta konjenikov in vse, kar je Salomon želel zgraditi v Jeruzalemu, na Libanonu in po vsej deželi svojega gospostva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Glede vsega ljudstva, ki je preostalo od Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev, ki niso bili iz Izraela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'temveč od njihovih otrok, ki so za njimi ostali v deželi, katerih Izraelovi otroci niso ugonobili, te je Salomon primoral, da plačujejo davek do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Toda izmed Izraelovih otrok Salomon ni naredil nobenega služabnika za svoje delo, temveč so bili bojevniki, vodje poveljnikov, poveljniki njegovih bojnih vozov in konjeniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Ti so bili vodje častnikov kralja Salomona, celó dvesto petdeset, ki so nadzorovali ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Salomon je iz Davidovega mesta privedel gor faraonovo hčer v hišo, ki jo je zgradil zanjo, kajti rekel je: »Moja žena ne bo prebivala v hiši Izraelovega kralja Davida, ker so prostori, kamor je prišla Gospodova skrinja, sveti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Potem je Salomon daroval žgalne daritve Gospodu, na Gospodovem oltarju, ki ga je zgradil pred preddverjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'celo po določeni meri so vsak dan darovali glede na Mojzesovo zapoved na šabate, na mlaje, na slovesne praznike, trikrat letno, torej na praznik nekvašenega kruha, na praznik tednov in na šotorski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Glede na red svojega očeta Davida je določil skupine duhovnikov k njihovi službi in Lévijevce k njihovim zadolžitvam, da hvalijo in služijo pred duhovniki, kakor je zahtevala dolžnost vsakega dne. Tudi vratarje po njihovih skupinah pri vsakih velikih vratih, kajti tako je zapovedal David, Božji mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Niso se odvrnili od kraljeve zapovedi glede katerekoli zadeve duhovnikov in Lévijevcev ali glede zakladnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Torej vse Salomonovo delo je bilo pripravljeno do dneva [položitve] temelja Gospodove hiše in dokler ta ni bila dokončana. Tako je bila Gospodova hiša popolna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Potem je Salomon odšel v Ecjón Geber in v Elot pri morski obali v edómski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Hurám mu je po roki svojih služabnikov poslal ladje in služabnike, ki so imeli znanje o morju, in ti so s Salomonovimi služabniki odšli v Ofír in od tam vzeli štiristo petdeset talentov zlata ter jih prinesli kralju Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Ko je kraljica iz Sabe slišala o Salomonovi slavi, je prišla v Jeruzalem, da Salomona preizkusi s težkimi vprašanji, z zelo veliko skupino in kamelami, ki so nosile dišave, zlata v obilju in dragocene kamne. Ko je prišla k Salomonu, se je z njim posvetovala o vsem, kar je bilo na njenem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Salomon ji je odgovoril [na] vsa njena vprašanja. Ničesar ni bilo skrito pred Salomonom, česar ji ne bi povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Ko je kraljica iz Sabe videla Salomonovo modrost in hišo, ki jo je zgradil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'hrano njegove mize, sedenje njegovih služabnikov, položaj njegovih služabnikov in njihovo obleko; tudi njegove dvorne točaje in njihovo obleko in njegov vzpon, s katerim je odšel gor v Gospodovo hišo, tam ni bilo več duha v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Kralju je rekla: » To je bilo resnično poročilo, ki sem ga slišala v svoji lastni deželi o tvojih dejanjih in o tvoji modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Vendar nisem verjela njihovim besedam, dokler nisem prišla in so moje oči to videle. Glej, ni mi bilo povedano niti o eni polovici veličine tvoje modrosti, kajti presegaš slavo, ki sem jo slišala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Srečni so tvoji možje in srečni so ti tvoji služabniki, ki nenehno stojijo pred teboj in poslušajo tvojo modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Blagoslovljen bodi Gospod, tvoj Bog, ki se je razveseljeval v tebi, da te postavi na svoj prestol, da bi bil kralj za Gospoda, tvojega Boga. Ker je tvoj Bog ljubil Izrael, da jih utrdi na veke, te je zato postavil [za] kralja nad njimi, da izvajaš sodbo in pravico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Kralju je izročila sto dvajset talentov zlata, veliko obilje dišav in dragocene kamne. Niti ni bilo tam nobenih takšnih dišav, kot jih je kraljica iz Sabe izročila kralju Salomonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Hurámovi služabniki in Salomonovi služabniki, ki so pripeljali zlato iz Ofírja, so pripeljali tudi sandalovino in dragocene kamne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Kralj je iz sandalovine naredil terase h Gospodovi hiši in h kraljevi palači in harfe ter plunke za pevce. Ničesar takšnega ni bilo prej videti v Judovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Kralj Salomon je kraljici iz Sabe izročil vse njene želje, karkoli je prosila, poleg tega, kar je prinesla h kralju. Tako se je obrnila in odšla proč k svoji lastni deželi, ona in njeni služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Torej teža zlata, ki je prišla k Salomonu v enem letu, je bila šeststo šestinšestdeset talentov zlata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'poleg tega, kar so prinašali krošnjarji in trgovci. Vsi kralji Arabije in voditelji dežele so Salomonu prinašali zlato in srebro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Kralj Salomon je naredil dvesto okroglih ščitov iz kovanega zlata. Šeststo šeklov iz kovanega zlata je šlo k enemu okroglemu ščitu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Tristo ščitov je naredil iz kovanega zlata. Tristo šeklov zlata je šlo za en ščit. Kralj jih je postavil v hiši libanonskega gozda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Poleg tega je kralj naredil velik prestol iz slonovine in ga prevlekel s čistim zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'K prestolu je bilo šest stopnic, s pručko iz zlata, ki so bile pritrjene k prestolu in opori [za roke] na vsaki strani prostora za sedenje in dva leva, stoječa pri oporah [za roke].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Dvanajst levov je stalo tam na eni strani in na drugi, na šestih stopnicah. Ničesar podobnega ni bilo narejenega v nobenem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Vse posode za pitje kralja Salomona so bile iz zlata in vse posode hiše libanonskega gozda so bile iz čistega zlata. Nobena ni bila iz srebra, le-to ni bilo nič cenjeno v Salomonovih dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Kajti kraljeve ladje so odplule v Taršíš s Hurámovimi služabniki. Enkrat na vsaka tri leta so prišle ladje iz Taršíša, ki so pripeljale zlato, srebro, slonovino, opice in pave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Kralj Salomon je presegal vse zemeljske kralje v bogastvih in modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Vsi kralji zemlje so iskali Salomonovo prisotnost, da slišijo njegovo modrost, ki jo je Bog položil v njegovo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Prinašali so mu vsak človek svoje darilo, posode iz srebra, posode iz zlata, oblačila, vprege, dišave, konje in mule, mero leto za letom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomon je imel štiri tisoč boksov za konje in bojne vozove in dvanajst tisoč konjenikov, ki jih je namestil v mestih za bojne vozove in s kraljem v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Kraljeval je nad vsemi kralji od reke celo do dežele Filistejcev in do meje Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Kralj je naredil srebra v Jeruzalemu kakor kamnov in cedrovih dreves je naredil [toliko] kakor egiptovskih smokev, ki jih je na nizkih ravnicah v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'K Salomonu so vodili konje iz Egipta in iz vseh dežel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Torej preostala izmed Salomonovih dejanj, prva in zadnja, mar niso zapisana v knjigi preroka Natána in v prerokovanju Šilčana Ahíja in v videnjih vidca Idója zoper Nebátovega sina Jerobeáma?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomon je v Jeruzalemu nad Izraelom kraljeval štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Salomon je zaspal s svojimi očeti in je bil pokopan v mestu svojega očeta Davida in namesto njega je zakraljeval njegov sin Rehabám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabám je odšel v Sihem, kajti v Sihem je prišel ves Izrael, da ga postavijo za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Pripetilo se je, ko je Nebátov sin Jerobeám, ki je bil v Egiptu, kamor je pobegnil pred prisotnostjo kralja Salomona, to slišal, da se je Jerobeám vrnil iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Poslali so in ga poklicali. Tako je Jerobeám in ves Izrael prišel in govoril Rehabámu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '»Tvoj oče je naredil naš jarem boleč. Sedaj torej nekako olajšaj boleče hlapčevstvo svojega očeta in njegov težki jarem, ki ga je nadel na nas in mi ti bomo služili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Rekel jim je: »Pridite ponovno k meni po treh dneh.« In ljudstvo je odšlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Kralj Rehabám se je posvetoval s starci, ki so stali pred njegovim očetom Salomonom, medtem ko je ta še živel, rekoč: »Kakšen nasvet mi dajete, da temu ljudstvu vrnem odgovor?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Spregovorili so mu, rekoč: »Če boš prijazen do tega ljudstva, jim ugajal in jim govoril dobre besede, bodo tvoji služabniki na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Toda zapustil je nasvet, ki so mu ga dali starci in se posvetoval z mladeniči, ki so bili vzgojeni z njim, ki so stali pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Rekel jim je: »Kakšen nasvet mi daste, da lahko vrnemo odgovor temu ljudstvu, ki mi je govorilo, rekoč: ›Nekoliko olajšaj jarem, ki ga je tvoj oče položil na nas?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Mladeniči, ki so bili vzgojeni z njim, so mu spregovorili, rekoč: »Tako boš odgovoril ljudstvu, ki ti je spregovorilo, rekoč: ›Tvoj oče je naš jarem naredil težek, toda ti nam ga nekako olajšaj;‹ tako jim boš rekel: ›Moj mali prst bo debelejši kakor ledja mojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Kajti kakor je moj oče na vas položil težek jarem, bom jaz vašemu jarmu še dodal. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Tako so Jerobeám in vse ljudstvo na tretji dan prišli k Rehabámu, kakor je kralj zaukazal, rekoč: »Ponovno pridite k meni na tretji dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Kralj jim je surovo odgovoril in kralj Rehabám je zapustil nasvet starcev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'ter jim odgovoril glede na nasvet mladeničev, rekoč: »Moj oče je vaš jarem naredil težek, toda jaz bom k temu dodal. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Tako kralj ni prisluhnil ljudstvu, kajti razlog je bil od Boga, da je Gospod lahko izpolnil svojo besedo, ki jo je po roki Šilčana Ahíja govoril Nebátovemu sinu Jerobeámu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Ko je ves Izrael videl, da jim kralj ni hotel prisluhniti, je ljudstvo kralju odgovorilo, rekoč: »Kakšen delež imamo v Davidu? Nobene dediščine nimamo v Jesejevem sinu. Vsak mož k svojim šotorom, oh Izrael. In sedaj, David, glej k svoji lastni hiši.« Tako je ves Izrael odšel k svojim šotorom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Toda kar se tiče Izraelovih otrok, ki so prebivali v Judovih mestih, je nad njimi kraljeval Rehabám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Potem je kralj Rehabám poslal Hadoráma, ki je bil nad davkom, Izraelovi otroci pa so ga kamnali s kamni, da je umrl. Toda kralj Rehabám je pohitel, da se spravi gor na svoj bojni voz, da pobegne v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'In Izrael se upira zoper Davidovo hišo do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Ko je Rehabám prišel v Jeruzalem, je iz Judove in Benjaminove hiše zbral sto osemdeset tisoč izbranih mož, ki so bili bojevniki, da se borijo zoper Izrael, da bi kraljestvo lahko ponovno privedli k Rehabámu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Toda beseda od Gospoda je prišla Božjemu možu Šemajáju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '»Govori Rehabámu, Salomonovemu sinu, Judovemu kralju in vsemu Izraelu v Judu in Benjaminu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '›Tako govori Gospod: ›Ne boste šli gor niti se ne boste borili zoper svoje brate. Vsak mož naj se vrne k svoji hiši, kajti ta stvar je storjena od mene.‹« Ubogali so Gospodove besede in se vrnili pred [tem, da bi] šli zoper Jerobeáma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Rehabám je prebival v Jeruzalemu in gradil mesta za obrambo v Judu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Zgradil je celo Bethlehem, Etám, Tekóo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bet Cur, Sohóm, Adulám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Marešo, Zif,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adorájim, Lahíš, Azéko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Coro, Ajalón in Hebrón, ki so v Judu in v Benjaminu utrjena mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Utrdil je oporišča in vanje postavil poveljnike in zaloge živeža, olja in vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'V vsako posamezno mesto je postavil ščite in sulice ter jih naredil silno močne, [ker je] imel Juda in Benjamin na svoji strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Duhovniki in Lévijevci, ki so bili po vsem Izraelu, so zahajali k njemu iz vseh svojih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Kajti Lévijevci so zapustili svoja predmestja in svojo lastnino ter prišli k Judu in Jeruzalemu, kajti Jerobeám in njegovi sinovi so jih zavrgli pred izvrševanjem duhovniške službe Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Odredil si je duhovnike za visoke kraje, za hudiče in za teleti, ki ju je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Za njimi so iz vseh Izraelovih rodov [prišli] tisti, ki so svoja srca naravnali, da iščejo Gospoda Boga. Iz Izraela so prišli v Jeruzalem, da darujejo Gospodu, Bogu svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Tako so tri leta krepili Judovo kraljestvo in Salomonovega sina Rehabáma naredili močnega, kajti tri leta so hodili po Davidovi in Salomonovi poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, '§ Rehabám si je za ženo vzel Mahaláto, hčer Davidovega sina Jerimóta in Abihájilo, hčer Jesejevega sina Eliába,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'ki sta mu rodila otroke: Jeúša, Šemarjája in Zaháma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Za njo je vzel Absalomovo hčer Maáho, ki mu je rodila Abíja, Atája, Zizá in Šelomíta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rehabám je ljubil Absalomovo hčer Maáho bolj, kot vse svoje žene in svoje priležnice, (kajti vzel je osemnajst žena in šestdeset priležnic ter zaplodil osemindvajset sinov in šestdeset hčerá.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Rehabám je postavil Maáhinega sina Abíja, da bo vladar med svojimi brati, kajti mislil je, da ga postavi za kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Modro je ravnal in vse svoje otroke razpršil po vseh Judovih in Benjaminovih deželah, do vsakega utrjenega mesta in dal jim je živeža v obilju. In želel je mnogo žená.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Pripetilo se je, ko je Rehabám utrdil kraljestvo in se okrepil, da je zapustil Gospodovo postavo in ves Izrael z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Pripetilo se je, da je v petem letu kralja Rehabáma egiptovski kralj Šišák prišel gor zoper Jeruzalem, ker so se pregrešili zoper Gospoda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 's tisoč dvesto bojnimi vozovi in šestdeset tisoč konjeniki. Ljudstva, ki so prišli z njim iz Egipta, je bilo brez števila: Libijci, Súkijci in Etiopci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Zavzel je utrjena mesta, ki pripadajo Judu in prišel do Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Potem je prišel prerok Šemajá k Rehabámu in k Judovim princem, ki so bili zaradi Šišáka zbrani skupaj v Jeruzalemu ter jim rekel: ›Tako govori Gospod: ›Vi ste zapustili mene in zato sem tudi jaz vas prepustil v Šišákovo roko.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Nakar so se Izraelovi princi in kralj ponižali ter rekli: » Gospod je pravičen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Ko je Gospod videl, da so se ponižali, je beseda od Gospoda prišla k Šemajáju, rekoč: »Oni so se ponižali, zato jih ne bom uničil, temveč jim bom zagotovil nekaj osvoboditve, in moj bes ne bo izlit na Jeruzalem po Šišákovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Kljub temu bodo njegovi služabniki, da bodo lahko spoznali moje služenje in služenje kraljestvom dežel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Tako je egiptovski kralj Šišák prišel gor nad Jeruzalem in odnesel zaklade Gospodove hiše in zaklade kraljeve hiše. Vse je vzel. Odnesel je tudi ščite iz zlata, ki jih je naredil Salomon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Namesto teh je kralj Rehabám naredil ščite iz brona in jih predal v roke poveljnika straže, ki je varoval vhod kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Ko je kralj vstopil v Gospodovo hišo, je prišla straža ter jih nosila in jih [potem] ponovno prinesla v stražarnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Ko se je ponižal, se je Gospodov bes odvrnil od njega, da ga ne bi povsem uničil. Tudi v Judu so stvari šle dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Tako se je kralj Rehabám okrepil v Jeruzalemu in kraljeval, kajti Rehabám je bil star enainštirideset let, ko je začel kraljevati in sedemnajst let je kraljeval v Jeruzalemu, mestu, ki ga je Gospod izbral izmed vseh Izraelovih rodov, da tam postavi svoje ime. Ime njegove matere je bilo Naáma, Amónka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Počel je zlo, ker svojega srca ni pripravil, da išče Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Torej dejanja Rehabáma, prva in zadnja, mar niso zapisana v knjigi preroka Šemajája in vidca Idója glede rodovnikov? In nenehno so bile vojne med Rehabámom in Jerobeámom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Rehabám je zaspal s svojimi očeti in pokopan je bil v Davidovem mestu. Namesto njega je zakraljeval njegov sin Abíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Torej v osemnajstem letu kralja Jerobeáma, je nad Judom začel kraljevati Abíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tri leta je kraljeval v Jeruzalemu. Ime njegove matere je bilo Mihajá, Uriélova hči iz Gíbee. In bila je vojna med Abíjem in Jerobeámom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abíja se je postrojil z vojsko hrabrih bojevnikov, celó štiristo tisoč izbranih mož. Tudi Jerobeám se je postrojil zoper njega z osemsto tisoč izbranimi možmi, ki so bili močni junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abíja je stal na gori Cemarájim, ki je na gori Efrájim in rekel: »Poslušaj me, ti Jerobeám in ves Izrael,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'ne veste, da je Gospod, Izraelov Bog, dal kraljestvo nad Izraelom Davidu na veke, celó njemu in njegovim sinovom s solno zavezo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Vendar je Nebátov sin Jerobeám, služabnik Davidovega sina Salomona, vstal in se uprl zoper svojega gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'In k njemu so bili zbrani praznoglavi možje, Beliálovi otroci in so se okrepili zoper Salomonovega sina Rehabáma, ko je bil Rehabám mlad in nežnega srca in se jim ni mogel zoperstaviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'In sedaj se vi mislite zoperstaviti Gospodovemu kraljestvu v roki Davidovih sinov. Vas je velika množica in tam sta z vami zlati teleti, katera vam je Jerobeám naredil za bogova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Mar niste vrgli ven Gospodove duhovnike, Aronove sinove in Lévijevce in ste si naredili duhovnike po načinu narodov drugih dežel? Tako da kdorkoli prihaja, da sebe umésti z mladim bikcem in sedmimi ovni, isti lahko postane duhovnik tistim, ki so ne-bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Toda kar se nas tiče, je Gospod naš Bog in mi ga nismo zapustili, in duhovniki, ki služijo Gospodu, so Aronovi sinovi in Lévijevci čakajo na svoj posel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Vsako jutro in vsak večer Gospodu zažigajo žgalne daritve in dišeče kadilo. Tudi hlebe navzočnosti postavljajo na čisto mizo in zlati svečnik z njegovimi svetilkami prižigajo vsak večer. Kajti mi se držimo naročila Gospoda, našega Boga, toda vi ste ga zapustili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Glejte, sam Bog je z nami za našega poveljnika in njegovi duhovniki z donenjem trobent, da zoper vas zatrobijo alarm. Oh Izraelovi otroci, ne borite se zoper Gospoda, Boga svojih očetov, kajti ne boste uspeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Toda Jerobeám je velel zasedi, da pride naokrog za njimi. Tako so bili pred Judom in zaseda je bila za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Ko je Juda pogledal nazaj, glej, bitka je bila spredaj in zadaj. Zavpili so h Gospodu in duhovniki so zatrobili s trobentami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Potem so možje iz Juda zakričali in ko so možje iz Juda zakričali, se je pripetilo, da je Bog udaril Jerobeáma in ves Izrael pred Abíjem in Judom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Izraelovi otroci so pobegnili pred Judom in Bog jih je izročil v njihovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abíja in njegovo ljudstvo jih je umorilo z velikim pokolom. Tako so tam padli umorjeni Izraelci, petsto tisoč izbranih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Tako so bili Izraelovi otroci ob tistem času podjarmljeni, Judovi otroci pa so prevladali, ker so se zanašali na Gospoda, Boga svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abíja je zasledoval Jerobeáma in od njega vzel mesta: Betel z njegovimi mesti, Ješáno z njenimi mesti in Efrón z njegovimi mesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Niti ni Jerobeám ponovno obnovil moči v Abíjevih dneh, in Gospod ga je udaril in je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Toda Abíja je postal mogočen in poročil štirinajst žena ter zaplodil dvaindvajset sinov in šestnajst hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Ostala Abíjeva dela, njegove poti in njegove besede so zapisane v zgodbi preroka Idója.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Tako je Abíja zaspal s svojimi očeti in pokopali so ga v Davidovem mestu. Namesto njega je zakraljeval njegov sin Asá. V njegovih dneh je bila dežela mirna deset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asá je počel to, kar je bilo dobro in pravilno v očeh Gospoda, njegovega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'kajti odstranil je oltarje tujih bogov, visoke kraje, porušil podobe in posekal ašere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Judu je zapovedal, naj išče Gospoda, Boga njihovih očetov in naj izpolnjuje postavo in zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Prav tako je iz vseh Judovih mest odstranil visoke kraje in podobe in kraljestvo je bilo pred njim mirno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'V Judu je zgradil utrjena mesta, kajti dežela je imela počitek in v tistih letih ni imel nobene vojne, ker mu je Gospod dal počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Zato je Judu rekel: »Gradimo ta mesta in okrog njih postavimo obzidja, stolpe, velika vrata in zapahe, medtem ko je dežela še pred nami, ker smo iskali Gospoda, svojega Boga. Iskali smo ga in on nam je dal počitek na vsaki strani.« Tako so gradili in bili uspešni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Asá je imel vojsko mož, ki so nosili okrogle ščite in sulice, iz Juda tristo tisoč in iz Benjamina, ki so nosili ščite in napenjali loke, dvesto osemdeset tisoč. Vsi ti so bili močni junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Zoper njih je prišel Etiopijec Zerah z milijonsko vojsko in tristo bojnimi vozmi in prišel do Mareše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Potem je Asá odšel ven zoper njega in postrojil so se v dolini Cefáti pri Mareši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Asá je klical h Gospodu, svojemu Bogu in rekel: » Gospod, to zate ni nič, da pomagaš, bodisi z mnogimi ali s tistimi, ki nimajo moči. Pomagaj nam, oh Gospod, naš Bog, kajti nate se zanašamo in v tvojem imenu gremo zoper to množico. Oh Gospod, ti si naš Bog, naj človek ne prevlada zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Tako je Gospod udaril Etiopijce pred Asájem in pred Judom in Etiopijci so pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asá in ljudstvo, ki je bilo z njim, so jih preganjali do Gerárja in Etiopijci so bili premagani, da si niso več opomogli, kajti bili so uničeni pred Gospodom in njegovo vojsko in odnesli so zelo veliko plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Udarili so vsa mesta naokoli Gerárja, kajti Gospodov strah je prišel nanje. Oplenili so vsa mesta, kajti v njih je bilo silno veliko plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Udarili so tudi šotore živine in odvedli proč ovc in kamel v obilju ter se vrnili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Božji Duh je prišel nad Odédovega sina Azarjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Ta je odšel ven, da sreča Asája in mu rekel: »Prisluhni mi, Asá, ves Juda in Benjamin. Gospod je z vami, dokler ste vi z njim in če ga iščete, se vam bo dal najti, toda če ga zapustite, bo on zapustil vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Torej dolgo časa je bil Izrael brez resničnega Boga, brez duhovnika, ki bi učil in brez postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Toda ko so se v svoji stiski obrnili h Gospodu, Izraelovemu Bogu in ga iskali, se jim je dal najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'V tistih časih ni bilo miru tistemu, ki je odšel ven niti tistemu, ki je vstopil, temveč so bile velike nevšečnosti nad vsemi prebivalci dežel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Narod je bil uničen od naroda in mesto od mesta, kajti Bog jih je jezil z vsemi nadlogami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Bodite torej močni in vaše roke naj ne bodo šibke, kajti vaše delo bo nagrajeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Ko je Asá slišal te besede in prerokbo preroka Odéda, se je opogumil in odstranil gnusne malike iz vse Judove in Benjaminove dežele in iz mest, ki jih je vzel z gore Efrájim in obnovil Gospodov oltar, ki je bil pred Gospodovim preddverjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Zbral je ves Juda in Benjamin in z njimi tujce iz Efrájima, Manáseja in Simeona, kajti iz Izraela so se v obilju zatekali k njemu, ko so videli, da je bil Gospod, njegov Bog, z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Tako so se zbrali skupaj pri Jeruzalemu, v tretjem mesecu, v petnajstem letu Asájevega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Isti čas so darovali Gospodu od plena, ki so ga privedli, sedemsto volov in sedemsto ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Vstopili so v zavezo, da iščejo Gospoda, Boga svojih očetov, z vsem svojim srcem in z vso svojo dušo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'da kdorkoli ne bi iskal Gospoda, Izraelovega Boga, bi bil usmrčen, bodisi majhen ali velik, moški ali ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'In prisegli so Gospodu z močnim glasom, vriskanjem, s trobentami in kornéti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Ves Juda se je veselil ob prisegi, kajti prisegli so z vsem svojim srcem in ga iskali z vso svojo željo in on se jim je dal najti. In Gospod jim je dal počitek naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Tudi glede Maáhe, matere kralja Asája, jo je ta odstranil, da bi bila kraljica, ker si je naredila malika v ašeri. Asá je posekal njenega malika, ga poteptal in ga zažgal pri potoku Kidron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Toda visoki kraji niso bili odvzeti iz Izraela. Kljub temu je bilo Asájevo srce vse njegove dni popolno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'V Božjo hišo je prinesel stvari, ki jih je njegov oče posvetil in te, ki jih je sam posvetil: srebro, zlato in posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'In nobene vojne ni bilo več do petintridesetega leta Asájevega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'V šestintridesetem letu Asájevega kraljevanja je zoper Juda prišel Izraelov kralj Bašá in gradil Ramo z namenom, da nikomer ne bi dovolil iti ven ali priti noter k Judovemu kralju Asáju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Potem je Asá prinesel ven srebro in zlato iz zakladnic Gospodove hiše in kraljeve hiše ter poslal k sirskemu kralju Ben Hadádu, ki je prebival v Damasku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '»Zaveza je med menoj in teboj, kakor je bila med mojim očetom in tvojim očetom. Glej, poslal sem ti srebro in zlato; pojdi in prelomi svojo zavezo z Izraelovim kraljem Bašájem, da lahko odide od mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Ben Hadád je prisluhnil kralju Asáju in poslal poveljnike svoje vojske zoper Izraelova mesta in udarili so Ijón, Dan, Abél Majim in vsa Neftálijeva skladiščna mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Pripetilo se je, ko je Bašá to slišal, da je prenehal graditi Ramo in opustil svoje delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Potem je kralj Asá vzel vsega Juda in odnesli so proč kamenje iz Rame in njen les, s katerim je Bašá gradil; s tem je gradil Gebo in Micpo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Ob tistem času je k Judovemu kralju Asáju prišel videc Hananí in mu rekel: »Ker si se zanašal na sirskega kralja in se nisi zanesel na Gospoda, svojega Boga, zato je vojska sirskega kralja pobegnila iz tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Mar niso bili Etiopijci in Libijci ogromna vojska z mnogimi bojnimi vozovi in konjeniki? Vendar ker si se zanesel na Gospoda, jih je izročil v tvojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Kajti Gospodove oči tekajo sem ter tja po vsej celotni zemlji, da se izkaže močnega v korist tistih, katerih srce je popolno do njega. V tem si storil nespametno, zato boš od sedaj naprej imel vojne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Potem je bil Asá ogorčen nad vidcem in ga vrgel v jetnišnico, kajti zaradi te stvari je bil ogorčen nanj. In Asá je isti čas zatiral nekatere izmed ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Glej, dejanja Asája, prva in zadnja, glej, ta so zapisana v knjigi Judovih in Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Asá je bil v devetintridesetem letu svojega kraljevanja bolan na svojih stopalih, dokler ni bila njegova bolezen silno velika, vendar se v svoji bolezni ni obrnil h Gospodu, temveč k zdravnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Asá je zaspal s svojimi očeti in umrl v enainštiridesetem letu svojega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Pokopali so ga v njegovih lastnih mavzolejih, ki si jih je naredil zase v Davidovem mestu in ga položili v posteljo, ki je bila napolnjena s prijetnimi dišavami in različnimi vrstami dišav, pripravljenih po lekarnarski umetnosti. Zanj so naredili zelo velik sežig [dišav].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Namesto njega je zakraljeval njegov sin Józafat in se okrepil zoper Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Namestil je sile v vsa utrjena Judova mesta in postavil garnizije v Judovi deželi in v Efrájimovih mestih, ki jih je zavzel njegov oče Asá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Gospod je bil z Józafatom, ker je hodil po prvih poteh svojega očeta Davida in ni iskal Báalov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'temveč je sledil Gospodu, Bogu svojega očeta in hodil po njegovih zapovedih in ne po Izraelovih ravnanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Zato je Gospod utrdil kraljestvo v njegovi roki. Ves Juda je Józafatu prinesel darila in imel je bogastva, čast in obilje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Njegovo srce je bilo vzdignjeno na Gospodovih poteh. Poleg tega je iz Juda odstranil visoke kraje in ašere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Tudi v tretjem letu svojega kraljevanja je poslal k svojim princem, torej k Ben Hajilu, k Obadjáju, k Zeharjáju, k Netanélu in k Mihajáju, da bi učili po Judovih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Z njimi je poslal Lévijevce, torej Šemajája, Netanjája, Zebadjája, Asaéla, Šemiramóta, Jehonatana, Adoníja, Tobija, Tob Adoníja, Lévijevce in z njimi duhovnika Elišamája in Jehoráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Učili so v Judu in s seboj so imeli knjigo Gospodove postave in šli so naokoli po vseh Judovih mestih in učili ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Gospodov strah je padel na vsa kraljestva dežel, ki so bile naokoli Juda, tako da zoper Józafata niso bojevali nobene vojne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Tudi nekateri izmed Filistejcev so Józafatu prinesli darila in davek srebra. Arabci so mu privedli trope, sedem tisoč sedemsto ovnov in sedem tisoč sedemsto kozlov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Józafat je postal silno velik in v Judu je zgradil gradove in skladiščna mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Po Judovih mestih je imel mnogo posla. In v Jeruzalemu so bili bojevniki, močni junaški možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'To so njihova števila glede na hišo njihovih očetov. Iz Juda poveljniki nad tisočimi: vodja Adnáh in z njim tristo tisoč močnih junaških mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Poleg njega je bil poveljnik Johanán in z njim dvesto osemdeset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Poleg njega je bil Zihríjev sin Amasjá, ki se je voljno daroval Gospodu in z njim dvesto tisoč močnih junaških mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Od Benjamina Eljadá, mogočen hraber mož in z njim dvesto tisoč z lokom in ščitom oboroženih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Poleg njega je bil Jozabád in z njim sto osemdeset tisoč pripravljenih za vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ti so čakali na kralja, poleg tistih, ki jih je kralj namestil v utrjenih mestih po vsem Judu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Torej Józafat je imel bogastev in časti v obilju in sklenil svaštvo z Ahábom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Po nekaj letih je odšel dol k Ahábu v Samarijo. Aháb je zanj in za ljudstvo, ki ga je imel s seboj, v obilju zaklal ovce in vole in pregovoril ga je, da gre z njim gor v Ramót Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Izraelov kralj Aháb je rekel Judovemu kralju Józafatu: »Hočeš iti z menoj v Ramót Gileád?« Ta mu je odgovoril: »Jaz sem, kakor si ti in moje ljudstvo kakor tvoje ljudstvo, in mi bomo s teboj v vojni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Józafat je Izraelovemu kralju rekel: »Poizvedi, prosim te, danes pri Gospodovi besedi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Zato je Izraelov kralj izmed prerokov skupaj zbral štiristo mož in jim rekel: »Ali naj gremo v Ramót Gileád, da se bojujemo ali naj [to] opustim?« Rekli so: »Pojdi gor, kajti Bog ga bo izročil v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Toda Józafat je rekel: » Ali tukaj poleg ni Gospodovega preroka, da bi lahko poizvedeli od njega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Izraelov kralj je Józafatu rekel: » Je še en mož, pri katerem bi lahko povprašali Gospoda, toda jaz ga sovražim, kajti nikoli mi ne prerokuje dobro, temveč vedno hudo. Ta isti je Jimlájev sin Miha.« Józafat je rekel: »Naj kralj ne govori tako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Izraelov kralj je dal poklicati enega izmed svojih častnikov in rekel: »Pojdi hitro po Jimlájevega sina Miha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Izraelov kralj in Judov kralj Józafat sta sedela, vsak izmed njiju na svojem prestolu, oblečena v njuna svečana oblačila in sedela na odprtem kraju pri vhodu velikih vrat Samarije, vsi preroki pa so prerokovali pred njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Kenaanájev sin Cidkijá si je naredil rogove iz železa in rekel: »Tako govori Gospod: ›S temi boš porinil Sirijo, dokler ne bodo použiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Vsi preroki so prerokovali tako, rekoč: »Pojdi gor v Ramót Gileád in uspevaj, kajti Gospod ga bo izročil v kraljevo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Poslanec, ki je odšel, da pokliče Miha, mu je spregovoril, rekoč: »Glej, besede prerokov soglasno kralju razglašajo dobro. Naj bo torej tvoja beseda, prosim te, kakor ena izmed njihovih in govori dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Miha je rekel: » Kakor živi Gospod, kar reče moj Bog, to bom govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Ko je prišel h kralju, mu je kralj rekel: »Miha, ali naj gremo gor v Ramót Gileád, da se bojujemo ali naj [to] opustim?« Ta je rekel: »Pojdite gor in uspevajte in izročeni bodo v vašo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Kralj mu je rekel: »Kolikokrat te bom zaklinjal, da mi ne poveš ničesar, razen resnice, v Gospodovem imenu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Potem je rekel: »Videl sem vsega Izraela razkropljenega po gorah kakor ovce, ki nimajo pastirja in Gospod je rekel: ›Ti nimajo gospodarja, naj se torej vrnejo v miru, vsak mož k svoji hiši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Izraelov kralj je Józafatu rekel: »Ali ti nisem rekel, da mi ne bo prerokoval dobro, temveč zlo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Ponovno je rekel: »Zato poslušajte besedo od Gospoda: ›Videl sem Gospoda sedeti na svojem prestolu in vso nebeško vojsko stati na njegovi desni roki in na njegovi levi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Gospod je rekel: ›Kdo bo premamil Izraelovega kralj Ahába, da gre lahko gor in pade pri Ramót Gileádu?‹ Eden je odgovoril na ta način, drugi je odgovoril na ta način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tedaj je šel naprej duh in obstal pred Gospodom ter rekel: ›Jaz ga bom premamil.‹ Gospod mu je rekel: ›S čim?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Rekel je: ›Šel bom ven in bom lažniv duh v ustih vseh njegovih prerokov.‹ In Gospod je rekel: ›Ti ga boš premamil in ti ga boš tudi pregovoril. Pojdi ven in stôri tako.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Zdaj torej glejte, Gospod je položil lažnivega duha v usta teh tvojih prerokov in Gospod je zoper tebe govoril zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Potem je Kenaanájev sin Cidkijá prišel bliže in udaril Miha po licu ter rekel: »Katero pot je odšel Gospodov duh od mene, da govori tebi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Miha je rekel: »Glej, videl boš ta dan, ko boš šel v notranjo sobo, da se skriješ.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Potem je Izraelov kralj rekel: »Vzemite Miha in ga odvedite nazaj k Amónu, voditelju mesta in h kraljevemu sinu Joášu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'ter recite: ›Tako govori kralj: ›Tega pajdaša postavita v ječo in ga hranita s kruhom stiske in z vodo stiske, dokler se ne vrnem v miru.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Miha je rekel: »Če se zagotovo vrneš v miru, potem po meni ni govoril Gospod.« Rekel je [še]: »Prisluhnite vsa ve ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Tako sta Izraelov kralj in Judov kralj Józafat odšla gor do Ramót Gileáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Izraelov kralj je Józafatu rekel: »Preoblekel se bom in šel v bitko, toda ti si nadeni svoja svečana oblačila.« Tako se je Izraelov kralj preoblekel in odšla sta na bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Torej sirski kralj je zapovedal poveljnikom bojnih vozov, ki so bili z njim, rekoč: »Ne borite se z malim ali velikim, razen samo z Izraelovim kraljem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Pripetilo se je, ko so poveljniki bojnih vozov zagledali Józafata, da so rekli: »Ta je Izraelov kralj.« Zato so ga obdali, da se bojujejo, toda Józafat je zavpil in Gospod mu je pomagal in Bog jih je spodbodel, da odidejo od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kajti pripetilo se je, da ko so poveljniki bojnih vozov zaznali, da to ni bil Izraelov kralj, so se ponovno obrnili nazaj od zasledovanja [za] njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Nek mož pa je preprosto napel lok in Izraelovega kralja zadel med člene prsnega oklepa. Zato je vozniku svojega bojnega voza rekel: »Obrni svojo roko, da me lahko odvedeš iz vojske, kajti ranjen sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Bitka je ta dan narasla, vendar je Izraelov kralj sam stal pokonci na svojem bojnem vozu zoper Sirce do večera, okoli časa zahajanja sonca pa je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Judov kralj Józafat pa se je v miru vrnil k svoji hiši v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Hananíjev sin Jehú, videc, je odšel ven, da ga sreča in kralju Józafatu rekel: »Ali naj bi pomagal brezbožnikom in ljubil tiste, ki sovražijo Gospoda? Zato je izpred Gospoda na tebi bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Kljub temu so v tebi najdene dobre stvari v tem, da si iz dežele odvzel ašere in si svoje srce pripravil, da išče Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Józafat je prebival v Jeruzalemu. In odšel je ponovno ven skozi ljudstvo od Beeršébe do gore Efrájim in jih vodil nazaj h Gospodu, Bogu njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Postavil je sodnike vsepovsod po deželi, po vseh utrjenih Judovih mestih, mestu za mestom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'in sodnikom rekel: »Pazite, kaj počnete, kajti ne sodite za človeka, temveč za Gospoda, ki je z vami v sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Zatorej naj bo sedaj nad vami Gospodov strah. Pazite in to storite, kajti z Gospodom, svojim Bogom, ni krivičnosti, niti oziranja na osebe, niti sprejemanja darov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Poleg tega je v Jeruzalemu Józafat postavil od Lévijevcev in od duhovnikov in od vodij Izraelovih očetov za Gospodovo sodbo in za oporekanja, ko so se vrnili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Zadolžil jih je, rekoč: »To boste delali v Gospodovem strahu, zvesto in s popolnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Kakršnakoli zadeva bo prišla k vam od vaših bratov, ki prebivajo v svojih mestih, med krvjo in krvjo, med postavo in zapovedjo, zakoni in sodbami, jih boste torej opozorili, da ne prestopajo zoper Gospoda in tako [ne] pride bes nad vas in nad vaše brate. To delajte in se ne boste pregrešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Glejte, véliki duhovnik Amarjá je nad vami v vseh Gospodovih zadevah in Jišmaélov sin Zebadjá, vladar Judove hiše, za vse kraljeve zadeve. Prav tako bodo Lévijevci častniki pred vami. Postopajte pogumno in Gospod bo z dobrim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Po tem se je tudi pripetilo, da so Moábovi otroci, Amónovi otroci in z njimi drugi, poleg Amóncev, prišli zoper Józafata, da se vojskujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Potem so prišli nekateri, ki so Józafatu rekli: »Velika množica prihaja zoper tebe, iz druge strani morja, na to stran Sirije. Glej, oni so v Hacecón Tamáru, ki je En Gedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Józafat se je zbal in se pripravil, da išče Gospoda in je po vsem Judu razglasil post.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Juda se je zbral skupaj, da prosi pomoč od Gospoda. Celo iz vseh Judovih mest so prišli, da iščejo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Józafat je stal v skupnosti Judovcev in Jeruzalemcev, v Gospodovi hiši, pred novim dvorom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'in rekel: »Oh Gospod, Bog naših očetov, ali nisi ti Bog v nebesih? In ali ne vladaš nad vsemi kraljestvi poganov? In ali ni v tvoji roki oblast in moč, tako da se ti nihče ne more zoperstaviti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Mar nisi ti naš Bog, ki si napodil prebivalce te dežele pred svojim ljudstvom Izraelom in jo daješ potomcem svojega prijatelja Abrahama na veke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'In oni prebivajo v njej in so ti v njej zgradili svetišče za tvoje ime, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '›Če zlo prihaja nad nas kakor meč, sodba ali kužna bolezen ali lakota, mi stojimo pred to hišo in v tvoji prisotnosti (kajti tvoje ime je v tej hiši) in kličemo k tebi v svoji stiski, potem boš slišal in pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'In sedaj glej, Amónovi in Moábovi otroci in gorovje Seír, za katere nisi hotel, da jih Izraelci napadejo, ko so prišli iz egiptovske dežele, temveč so se obrnili od njih in jih niso uničili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'glej pravim, kako so nas nagradili, da pridejo, da nas vržejo ven iz tvoje posesti, ki si nam jo ti dal, da jo podedujemo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Oh naš Bog, mar jih ne boš sodil? Kajti nobene moči nimamo zoper to veliko skupino, ki prihaja zoper nas niti ne vemo, kaj storiti, temveč so naše oči na tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Ves Juda je stal pred Gospodom s svojimi malčki, svojimi ženami in svojimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Potem je nad Jahaziéla, sina Zeharjája, sina Benajája, sina Jeiéla, sina Matanjája, Lévijevca izmed Asáfovih sinov, prišel Duh od Gospoda v sredo skupnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'in rekel je: »Prisluhnite, ves Juda in prebivalci Jeruzalema in ti, kralj Józafat: ›Tako vam govori Gospod: ›Ne bojte se niti ne bodite zaprepadeni zaradi te velike množice, kajti bitka ni vaša, temveč Božja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Jutri pojdite dol zoper njih. Glejte, prišli bodo pri pečini Cic in našli jih boste na koncu potoka, pred jeruélsko divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'V tej bitki se vam ne bo treba bojevati. Razpostavite se, stojte mirno in glejte rešitev duš Gospoda z vami, oh Juda in Jeruzalem. Ne bojte se niti ne bodite zaprepadeni. Jutri pojdite ven zoper njih, kajti Gospod bo z vami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Józafat je sklonil svojo glavo s svojim obrazom do tal in ves Juda in prebivalci Jeruzalema so padli pred Gospodom in oboževali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Lévijevci izmed otrok Kehátovcev in izmed Kórahovcev so vstali, da hvalijo Gospoda, Izraelovega Boga, s silno močnim glasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Zgodaj zjutraj so vstali ter odšli naprej v divjino Tekóe in ko so šli naprej se je Józafat ustavil in rekel: »Poslušajte me, oh Juda in vi, prebivalci Jeruzalema. Verjemite v Gospoda, svojega Boga, tako boste utrjeni; verjemite prerokom, tako boste uspeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Ko se je posvetoval z ljudstvom, je določil pevce za Gospoda in ki naj bi hvalili lepoto svetosti, medtem ko bodo šli ven pred vojsko in govorili: »Hvalite Gospoda, kajti njegovo usmiljenje vztraja na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Ko so začeli peti in hvaliti, je Gospod pripravil zasede zoper otroke Amóna, Moába in gorovje Seír, ki so prišli zoper Juda; in bili so udarjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Kajti otroci Amóna in Moába so se dvignili zoper prebivalce gorovja Seír, da jih popolnoma pobijejo in uničijo. In ko so prebivalcem Seíra storili konec, je vsakdo pomagal uničiti drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Ko je Juda prišel proti stražnemu stolpu v divjini, so pogledali k množici in glej, bili so trupla, padla na zemljo in nihče ni pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Ko je Józafat in njegovo ljudstvo prišlo, da od njih poberejo plen, so med njimi našli v obilju tako bogastev s trupli, kakor dragocene dragulje, ki so jih pobrali zase, več kakor so lahko nesli in tam so bili tri dni pri pobiranju plena, toliko ga je bilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Na četrti dan so se zbrali skupaj v dolini Berahá, kajti tam so blagoslovili Gospoda. Zato je bilo ime tega kraja imenovano dolina Berahá do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Potem so se vrnili, vsak človek iz Juda in Jeruzalema in Józafat na njihovem čelu, da gredo ponovno z radostjo v Jeruzalem, kajti Gospod jim je storil, da se veselijo nad svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'V Jeruzalem so prišli s plunkami, harfami in trobentami h Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Božji strah je bil na vseh kraljestvih tistih dežel, ko so slišali, da se je Gospod boril zoper Izraelove sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Tako je bilo Józafatovo kraljestvo mirno, kajti njegov Bog mu je naokoli dal počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Józafat je kraljeval nad Judom. Petintrideset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval petindvajset let. Ime njegove matere je bilo Azúba, Šilhíjeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Hodil je po poti svojega očeta Asája in se ni oddvojil od nje in delal je to, kar je bilo pravilno v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Vendar visoki kraji niso bili odstranjeni, kajti do takrat ljudstvo svojih src še ni pripravilo k Bogu njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Torej preostala izmed Józafatovih dejanj, prva in zadnja, glej, ta so zapisana v knjigi Hananijevega sina Jehúja, ki je omenjen v knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Potem je Judov kralj Józafat sebe pridružil Izraelovemu kralju Ahazjáju, ki je počel zelo zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Pridružil se mu je, da izdelata ladje, da bi plule v Taršíš in ladje so izdelali v Ecjón Geberju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Potem je Dodavájev sin Eliézer iz Maréše prerokoval zoper Józafata, rekoč: »Ker si se pridružil Ahazjáju, je Gospod zlomil tvoja dela.« In ladje so bile razbite, da niso mogle pluti v Taršíš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Torej Józafat je zaspal s svojimi očeti in bil s svojimi očeti pokopan v Davidovem mestu. Namesto njega je zakraljeval njegov sin Jehorám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Ta je imel brate, Józafatove sinove: Azarjája, Jehiéla, Zeharjája, Azarjája, Mihaela in Šefatjája. Vsi ti so bili sinovi Izraelovega kralja Józafata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Njihov oče jim je dal veliko daril iz srebra in iz zlata in dragocenih stvari, z utrjenimi mesti v Judu, toda kraljestvo je dal Jehorámu, ker je bil prvorojenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Torej ko je bil Jehorám dvignjen h kraljestvu svojega očeta, se je okrepil in vse svoje brate usmrtil z mečem in tudi številne izmed Izraelovih princev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Jehorám je bil star dvaintrideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval osem let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Hodil je po poti Izraelovih kraljev, podobno kakor je storila Ahábova hiša, kajti za ženo je imel Ahábovo hčer. Počel je to, kar je bilo zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Vendar Gospod ni hotel uničiti Davidove hiše zaradi zaveze, ki jo je sklenil z Davidom in kakor je obljubil, da da luč njemu in njegovim sinovom na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'V njegovih dneh so se Edómci spuntali izpod Judovega gospostva in si postavili kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Potem je Jehorám s svojimi princi odšel naprej in vsi njegovi bojni vozovi z njim. Ponoči je vstal in udaril Edomce, ki so obkolili njega in stotnike bojnih vozov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Tako so se Edómci spuntali izpod Judove roke do današnjega dne. Isti čas se je tudi Libna spuntala izpod njegove roke, ker je zapustil Gospoda, Boga svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Poleg tega je postavil visoke kraje po Judovih gorah in prebivalcem Jeruzalema storil, da zagrešijo prešuštvovanje in k temu zapeljal Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'In k njemu je prišlo pisanje preroka Elija, rekoč: ›Tako govori Gospod, Bog tvojega očeta Davida: ›Ker nisi hodil po poteh svojega očeta Józafata niti po poteh Judovega kralja Asája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'temveč si hodil po poti Izraelovih kraljev in si pripravil Juda in prebivalce Jeruzalema, da se vlačugajo, podobno vlačugarstvom Ahábove hiše in si tudi umoril svoje brate od hiše svojega očeta, ki so bili boljši kakor ti sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Glej, z veliko nadlogo bo Gospod udaril tvoje ljudstvo, tvoje otroke, tvoje žene in vse tvoje dobrine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'ti pa boš imel veliko slabost z boleznijo svoje notranjosti, dokler tvoja notranjost ne zleze ven zaradi razloga bolezni dan za dnem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Poleg tega je Gospod zoper Jehoráma razvnel duha Filistejcev in Arabcev, ki so bili blizu Etiopijcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Ti so prišli gor v Juda in vdrli vanj in odnesli vse imetje, ki je bilo najdeno v kraljevi hiši in tudi njegove sinove in njegove žene, tako da mu ni ostal sin razen Joaháza, najmlajšega izmed njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Po vsem tem ga je Gospod udaril v njegovi notranjosti z neozdravljivo boleznijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Pripetilo se je tekom časa, po koncu dveh let, da je njegova notranjost zlezla ven zaradi razloga njegove slabosti. Tako je umrl od hudih bolezni. Njegovo ljudstvo zanj ni naredilo nobenega sežiga [dišav], podobnega sežigu njegovim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Dvaintrideset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval osem let in odšel, brez da bi ga želeli. Vendar so ga pokopali v Davidovem mestu, toda ne v kraljevih mavzolejih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Prebivalci Jeruzalema so namesto njega za kralja postavili njegovega najmlajšega sina Ahazjája, kajti četa mož, ki je prišla z Arabci k taboru, je umorila vse starejše. Tako je zakraljeval Ahazjá, sin Judovega kralja Jehoráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ahazjá je bil star dvainštirideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval eno leto. Ime njegove matere je bilo Ataljá, Omrijeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Tudi on je hodil po poteh Ahábove hiše, kajti njegova mati je bila njegova svetovalka, da počne zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Zaradi česar je počel zlo v Gospodovih očeh, kakor Ahábova hiša, kajti bili so njegovi svetovalci po smrti njegovega očeta, njemu v uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Hodil je tudi po njihovem nasvetu in odšel z Ahábovim sinom Jehorámom, Izraelovim kraljem, da se vojskuje zoper sirskega kralja Hazaéla pri Ramót Gileádu. Sirci pa so udarili Joráma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Vrnil se je, da bi bil ozdravljen v Jezreélu, zaradi ran, ki so mu bile zadane pri Rami, ko se je boril s sirskim kraljem Hazaélom. In Azarjá, Jehorámov sin, Judov kralj, je odšel dol, da pogleda Ahábovega sina Jehoráma pri Jezreélu, ker je bil bolan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'To je bilo od Boga, da je prišlo k Ahazjáju uničenje, da je šel k Jehorámu, kajti ko je prišel, je z Jehorámom odšel ven zoper Nimšíjevega sina Jehúja, ki ga je Gospod mazilil, da iztrebi Ahábovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Pripetilo se je, da ko je Jehú izvrševal sodbo nad Ahábovo hišo in našel Judove prince in sinove Ahazjájevih bratov, da služijo Ahazjáju, jih je usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Iskal je Ahazjá, in ujeli so ga (kajti skrit je bil v Samariji) ter ga privedli k Jehúju. Ko so ga umorili, so ga pokopali: »Ker,« so rekli, »on je Józafatov sin, ki je z vsem svojim srcem iskal Gospoda.« Tako Ahazjájeva hiša ni imela moči, da kraljestvo obdrži mirno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Toda ko je Ahazjájeva mati Ataljá videla, da je bil njen sin mrtev, je vstala in uničila vse kraljeve potomce Judove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Toda kraljeva hči Jošébah je vzela Ahazjájevega sina Joáša in ga ukradla izmed kraljevih sinov, ki so bili umorjeni in postavila njega ter njegovo dojiljo v spalnico. Tako ga je Jošébah, hči kralja Jehoráma, žena duhovnika Jojadája (kajti bila je Ahazjájeva sestra) skrila pred Ataljo, tako da ga ta ni usmrtila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Šest let je bil z njimi skrit v Božji hiši, Ataljá pa je kraljevala nad deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'V sedmem letu se je Jojadá okrepil in vzel poveljnike nad stotimi: Jerohámovega sina Azarjája, Johanánovega sina Jišmaéla, Obédovega sina Azarjája, Adajájevega sina Maasejája in Zihríjevega sina Elišafáta v zavezo z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Ti so šli naokoli po Judu in zbrali Lévijevce iz vseh Judovih mest in vodje Izraelovih očetov ter prišli v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Vsa skupnost je sklenila zavezo s kraljem v Božji hiši. Rekel jim je: »Glejte, kraljev sin bo kraljeval, kakor je Gospod rekel o Davidovih sinovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'To je stvar, ki jo boste storili: ›Tretjina izmed vas, ki vstopi na šabat, od duhovnikov in od Lévijevcev, boste vratarji vrat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'tretjina bo pri kraljevi hiši in tretjina pri temeljnih velikih vratih, vse ljudstvo pa bo na dvorih Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Toda nihče naj ne pride v Gospodovo hišo, razen duhovnikov in tistih, ki služijo od Lévijevcev; oni bodo vstopili, kajti oni so sveti, toda vse ljudstvo bo Gospodova straža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Lévijevci bodo naokoli obdali kralja, vsak mož s svojim orožjem v svoji roki in kdorkoli drug pride v hišo, bo usmrčen, toda vi bodite s kraljem, ko vstopa in ko gre ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Tako so Lévijevci in ves Juda storili glede na vse stvari, ki jih je duhovnik Jojadá zapovedal ter vzeli vsak mož svoje može, ki so vstopali na šabat, s tistimi, ki so na šabat odhajali ven, kajti duhovnik Jojadá ni odpustil skupin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Poleg tega je duhovnik Jojadá poveljnikom izročil stotine sulic, oklepe in ščite, ki so bili [od] kralja Davida, ki so bili v Božji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Postavil je vse ljudstvo, vsakega moža s svojim orožjem v svoji roki, od desne strani templja, do leve strani templja, vzdolž oltarja in templja, naokoli kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Potem so privedli ven kraljevega sina in nanj položili krono in mu izročili pričevanje ter ga postavili [za] kralja. Jojadá in njegovi sinovi so ga mazilili ter rekli: »Živel kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Torej ko je Ataljá zaslišala hrup ljudstva teči in slaviti kralja, je prišla k ljudstvu v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Pogledala je in glej, kralj je stal pri svojem stebru ob vhodu in princi ter trobente poleg kralja. Vse ljudstvo dežele se je veselilo in trobilo s trobentami, tudi pevci z glasbenimi instrumenti in tisti, ki so učili peti hvalo. Potem je Ataljá pretrgala svoja oblačila in rekla: »Izdaja, izdaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Potem je duhovnik Jojadá privedel ven poveljnike nad stotimi, ki so bili postavljeni nad vojsko in jim rekel: »Odpeljite jo iz dosega in kdorkoli ji sledi, naj bo umorjen z mečem. Kajti duhovnik je rekel: ›Ne umorite je v Gospodovi hiši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Tako so nanjo položili roke in ko je prišla do vhoda velikih konjskih vrat, ob kraljevi hiši, so jo tam usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Jojadá je sklenil zavezo med seboj, med vsem ljudstvom in med kraljem, da bi bili Gospodovo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Potem je vse ljudstvo odšlo k Báalovi hiši, jo porušilo, razbilo njene oltarje in njene podobe na koščke in pred oltarji usmrtilo Báalovega duhovnika Matána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Jojadá je določil tudi službe Gospodove hiše po roki Lévijevih duhovnikov, ki jih je David porazdelil v Gospodovi hiši, da darujejo Gospodove žgalne daritve, kakor je to zapisano v Mojzesovi postavi, z razveseljevanjem in prepevanjem, kakor je bilo to odrejeno po Davidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Postavil je vratarje pri velikih vratih Gospodove hiše, da nihče, ki je bil nečist v katerikoli stvari, ne bi vstopil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Vzel je poveljnike izmed stotih, plemiče in voditelje izmed ljudstva in vse ljudstvo dežele ter kralja privedel dol iz Gospodove hiše in prišli so skozi velika vrata v kraljevo hišo ter kralja postavili na prestol kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Vse ljudstvo dežele se je veselilo in mesto je bil mirno, potem ko so Ataljo umorili z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joáš je bil star sedem let, ko je začel kraljevati in v Jeruzalemu je kraljeval štirideset let. Ime njegove matere je bilo Cibja iz Beeršébe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joáš je delal to, kar je bilo pravilno v Gospodovih očeh, vse dni duhovnika Jojadája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Jojadá je zanj vzel dve ženi in zaplodil je sinove in hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Za tem se je pripetilo, da je imel Joáš na srcu, da popravi Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Skupaj je zbral duhovnike in Lévijevce ter jim rekel: »Pojdite ven v Judova mesta in od vsega Izraela zbirajte denar za popravilo hiše svojega Boga iz leta v leto in glejte, da pohitrite zadevo. Vendar Lévijevci niso pohiteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Kralj je dal poklicati vodja Jojadája ter mu rekel: »Zakaj nisi od Lévijevcev zahteval, da iz Juda in Jeruzalema prinašajo nabirko, glede na zapoved Mojzesa, Gospodovega služabnika in iz Izraelove skupnosti za šotorsko svetišče pričevanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Kajti sinovi te zlobne ženske Atalje so razbili Božjo hišo in tudi vse posvečene stvari Gospodove hiše so podelili Báalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Na kraljevo zapoved so naredili zaboj in ga postavili zunaj pri velikih vratih Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Naredili so razglas po vsem Judu in Jeruzalemu, naj prinašajo Gospodu nabirko, ki jo je Božji služabnik Mojzes naložil Izraelu v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Vsi princi in vse ljudstvo se je veselilo, prinašalo in metalo v zaboj, dokler niso končali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Torej pripetilo se je, da kadar je bil zaboj po roki Lévijevcev prinesen v kraljevo pisarno in ko so videli, da je bilo v njem veliko denarja, sta prišla kraljevi pisar in častnik vélikega duhovnika ter izpraznila zaboj in ga vzela ter ga ponovno odnesla na njegov kraj. Tako so delali dan za dnem in zbrali denarja v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Kralj in Jojadá sta ga dajala tistim, ki so opravljali delo službe Gospodove hiše ter najemala zidarje in tesarje, da obnovijo Gospodovo hišo in tudi tiste, ki so kovali železo in bron, da popravijo Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Tako so delavci delali in delo dovršili in Božjo hišo so postavili v njeno stanje in jo utrdili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Ko so jo končali, so preostanek denarja prinesli pred kralja in Jojadája, s čimer so bile narejene posode za Gospodovo hišo, torej posode za služenje in da z njimi darujejo ter žlice in posode iz zlata in srebra. In nenehno so darovali žgalne daritve v Gospodovi hiši, vse Jojadájeve dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Toda Jojadá se je postaral in ko je umrl, je bil izpolnjen z dnevi in ko je umrl, je bil star sto trideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Pokopali so ga med kralji v Davidovem mestu, ker je delal dobro v Izraelu, tako za Boga kot za svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Torej po smrti Jojadája so prišli Judovi princi in se globoko priklonili kralju. Potem jim je kralj prisluhnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Zapustili so hišo Gospoda, Boga svojih očetov in služili ašeram in malikom in zaradi tega njihovega prekrška je prišel bes nad Juda in Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Vendar jim je pošiljal preroke, da jih ponovno privedejo h Gospodu in ti so pričevali zoper njih, toda oni jim niso hoteli prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'In Božji Duh je prišel nad Zeharjá, sina duhovnika Jojadája, ki je stal nad ljudstvom ter jim rekel: »Tako govori Bog: ›Zakaj prestopate Gospodove zapovedi, da ne morete uspevati? Ker ste zapustili Gospoda, je tudi on zapustil vas.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Oni pa so se zarotili zoper njega in ga na kraljevo zapoved kamnali s kamni na dvoru Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Tako se kralj Joáš ni spomnil prijaznosti, ki mu jo je storil njegov oče Jojadá, temveč je usmrtil njegovega sina. In ko je ta umiral, je rekel: » Gospod glej na to in to zahtevaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Pripetilo se je ob koncu leta, da je zoper njega prišla sirska vojska. Prišli so do Juda in Jeruzalema in izmed ljudstva uničili vse prince ljudstva in ves njihov plen poslali h kralju v Damask.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Kajti vojska Sircev je prišla z majhno skupino mož in Gospod je v njihovo roko izročil zelo veliko množico, ker so zapustili Gospoda, Boga svojih očetov. Tako so izvršili sodbo nad Joášem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Ko so odšli od njega (kajti zapustili so ga v velikih boleznih), so se njegovi lastni služabniki zarotili zoper njega zaradi krvi sinov duhovnika Jojadája in ga usmrtili na njegovi postelji in je umrl. Pokopali so ga v Davidovem mestu, toda niso ga pokopali v mavzolejih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'To sta tista [dva], ki sta se zarotila zoper njega: Zabád, sin Amónke Šimáte in Jozabád, sin Moábke Šimrite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Torej glede njegovih sinov in veličine bremen, položenih nadenj in obnove Božje hiše, glej, ta so zapisana v zgodbi knjige kraljev. In namesto njega je zakraljeval njegov sin Amacjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amacjá je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval devetindvajset let. Ime njegove matere je bilo Joadána iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, toda ne s popolnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Pripetilo se je torej, ko mu je bilo kraljestvo utrjeno, da je usmrtil svoja služabnika, ki sta ubila kralja, njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Toda njunih otrok ni usmrtil, temveč je storil, kakor je to zapisano v postavi Mojzesove knjige, kjer je Gospod zapovedal, rekoč: ›Očetje ne bodo umrli zaradi otrok niti ne bodo otroci umrli zaradi očetov, temveč bo vsak človek umrl zaradi svojega lastnega greha.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Poleg tega je Amacjá zbral skupaj Juda in jih postavil za tisočnike in stotnike, glede na hiše njihovih očetov, po vsem Judu in Benjaminu. Preštel jih je od starosti dvajset let navzgor in jih našel tristo tisoč izbranih mož, zmožnih iti na vojno, ki so lahko zgrabili sulico in ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Najel je tudi sto tisoč močnih junaških mož iz Izraela za sto talentov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Toda tam je prišel k njemu Božji mož, rekoč: »Oh kralj, naj Izraelova vojska ne gre s teboj, kajti Gospod ni z Izraelom, namreč z vsemi Efrájimovi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Toda če ti hočeš iti, stori to, bodi močan za bitko. Bog ti bo storil, da padeš pred sovražnikom, kajti Bog ima moč, da pomaga in da podere.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amacjá je rekel Božjemu možu: »Toda kaj naj storimo zaradi stotih talentov, ki sem jih dal Izraelovi vojski?« Božji mož je odgovoril: » Gospod ti je zmožen dati veliko več kakor to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Potem jih je Amacjá ločil, namreč vojsko, ki je prišla k njemu iz Efrájima, da gre ponovno domov. Zato je bila njihova jeza silno vžgana zoper Juda in domov so se vrnili v veliki jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amacjá se je okrepil in vodil svoje ljudstvo in odšel v solno dolino in jih izmed Seírovih otrok pobil deset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Drugih deset tisoč pa so Judovi otroci pustili žive, jih odvedli ujete in jih privedli na vrh skale ter jih vrgli dol iz vrha skale, da so bili razbiti na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Toda vojaki vojske, ki jih je Amacjá poslal nazaj, da ne bi šli z njim na bitko, so vpadli na Judova mesta od Samarije celo do Bet Horóna in pobili tri tisoč izmed njih in zajeli veliko plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Pripetilo se je torej, potem ko je Amacjá prišel od pokola Edómcev, da je prinesel bogove Seírjevih otrok in jih postavil, da bodo njegovi bogovi, se priklanjal pred njimi in jim zažigal kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Zato je bila Gospodova jeza vžgana zoper Amacjá in mu je poslal preroka, ki mu je rekel: »Zakaj si iskal za bogovi ljudstva, ki niso mogli rešiti svoje lastno ljudstvo iz tvoje roke?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Pripetilo se je, ko je govoril z njim, da mu je kralj rekel: »Mar si postavljen za kraljevega svetovalca? Odnehaj. Zakaj bi bil udarjen?« Potem je prerok odnehal in rekel: »Vem, da je Bog določil, da te uniči, ker si to storil in nisi prisluhnil mojemu nasvetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Potem je Judov kralj Amacjá sprejel nasvet in poslal k Jehoášu, Joaházovemu sinu, Jehújevemu sinu, Izraelovemu kralju, rekoč: »Pridi, poglejva drug drugemu v obraz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Izraelov kralj Jehoáš pa je poslal k Judovemu kralju Amacjáju, rekoč: »Osat, ki je bil na Libanonu, je poslal k cedri, ki je bila na Libanonu, rekoč: ›Daj svojo hčer mojemu sinu za ženo.‹ In tam mimo je šla divja zver, ki je bila na Libanonu in pomendrala osat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Ti praviš: ›Glej, udaril si Edómce in tvoje srce te je povzdignilo do bahanja. Ostani torej doma, zakaj bi se vmešaval v svojo bolečino, da bi padel, celó ti in Juda s teboj?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Toda Amacjá ni hotel slišati, kajti to je prišlo od Boga, da bi jih on lahko izročil v roko njihovih sovražnikov, ker so iskali za edómskimi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Tako je Izraelov kralj Jehoáš odšel gor in videla sta drug drugega v obraz, tako on in Judov kralj Amacjá, pri Bet Šemešu, ki pripada Judu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Juda je bil na slabšem pred Izraelom in pobegnili so vsak mož k svojemu šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Izraelov kralj Jehoáš je prijel Judovega kralja Amacjá, Joáševega sina, Joaházovega sina pri Bet Šemešu in ga privedel v Jeruzalem in porušil jeruzalemsko obzidje od Efrájimovih velikih vrat do vogalnih velikih vrat, štiristo komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Vzel je vse zlato, srebro in vse posode, ki so bile najdene v Božji hiši z Obéd Edómom in zaklade kraljeve hiše, tudi talce in se vrnil v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Joášev sin Amacjá, kralj Juda, je po smrti Izraelovega kralja, Joaházovega sina Jehoáša, živel petnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Torej preostala izmed Amacjájevih dejanj, prva in zadnja, glej, mar niso zapisana v knjigi Judovih in Izraelovih kraljev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Torej po času, ko se je Amacjá odvrnil od sledenja Gospodu, so v Jeruzalemu zoper njega skovali zaroto; on pa je pobegnil v Lahíš. Toda poslali so za njim v Lahíš in ga tam usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Pripeljali so ga na konjih in ga pokopali z njegovimi očeti v Judovem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Potem je vse Judovo ljudstvo vzelo Uzíjaha, ki je bil star šestnajst let in ga postavilo [za] kralja namesto njegovega očeta Amacjája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Pozidal je Elot in ga povrnil Judu, nató je kralj zaspal s svojimi očeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uzíjah je bil star šestnajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval dvainpetdeset let. Ime njegove matere je bilo Jehólja iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse, kar je delal njegov oče Amacjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Iskal je Boga v dneh Zeharjá, ki je imel razumevanje Božjih videnj. Dokler je iskal Gospoda, mu je Bog naredil, da uspeva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Odšel je naprej in se boril zoper Filistejce in porušil obzidje v Gatu, obzidje v Jabnéju, obzidje v Ašdódu ter zgradil mesta okoli Ašdóda in med Filistejci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Bog mu je pomagal zoper Filistejce in zoper Arabce, ki prebivajo v Gur Báalu in [zoper] Meunéjce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Amónci so izročali darila Uzíjahu in njegovo ime se je razširilo celó do vhoda v Egipt, kajti silno se je okrepil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Poleg tega je Uzíjah zgradil stolpe v Jeruzalemu, pri vogalnih velikih vratih, pri dolinskih velikih vratih in ob vogalu obzidja in jih utrdil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Prav tako je zgradil stolpe v puščavi in izkopal mnogo vodnjakov, kajti imel je mnogo živine tako v spodnji deželi kakor na ravninah. Tudi poljedelce in obrezovalce vinske trte v gorah in na Karmelu, kajti ljubil je poljedelstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Poleg tega je imel Uzíjah vojsko vojskujočih mož, ki so šli ven, da se vojskujejo po četah, glede na število, po roki pisarja Jeiéla in vladarja Maasejája, pod roko Hananjája, enega izmed kraljevih poveljnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Celotno število vodij očetov močnih junaških mož je bilo dva tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Pod njihovo roko je bila vojska, tristo sedem tisoč petsto mož, ki so se bojevali z mogočno močjo, da pomagajo kralju zoper sovražnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzíjah je zanje po vsej vojski pripravil ščite, sulice, čelade, brezrokavne verižne srajce, loke in prače, da mečejo kamne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'V Jeruzalemu je naredil stroje, ki so jih izumili spretni ljudje, da bi bili na stolpih in na branikih, da streljajo puščice in poleg tega velike kamne. Njegovo ime se je razširilo daleč naokoli, kajti bilo mu je čudovito pomagano, dokler je bil močan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Toda ko je bil močan, je bilo njegovo srce povzdignjeno k njegovemu uničenju, kajti pregrešil se je zoper Gospoda, svojega Boga in odšel v Gospodov tempelj, da na kadilnem oltarju zažge kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Duhovnik Azarjá je vstopil za njim in z njim osemdeset Gospodovih duhovnikov, ki so bili hrabri možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Zoperstavili so se kralju Uzíjahu in mu rekli: » To ne pripada tebi, Uzíjah, da zažigaš kadilo Gospodu, temveč duhovnikom, Aronovim sinovom, ki so posvečeni, da zažigajo kadilo. Odidi ven iz svetišča, kajti grešil si niti ti to ne bo v tvojo slavo pred Gospodom Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Potem je bil Uzíjah ogorčen in v svoji roki je imel kadilnico, da zažiga kadilo. Medtem ko je bil besen nad duhovniki, je celo vstala gobavost na njegovem čelu, pred duhovniki v Gospodovi hiši, poleg kadilnega oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Véliki duhovnik Azarjá in vsi duhovniki so pogledali nanj in glej, bil je gobav na svojem čelu in sunili so ga proč od tam; da, tudi sam je pohitel, da odide, ker ga je Gospod udaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Kralj Uzíjah je bil gobavec do dneva svoje smrti in prebival v posebni hiši, [ker je] bil gobavec, kajti bil je odrezan od Gospodove hiše in njegov sin Jotám je bil nad kraljevo hišo, sodeč ljudstvu dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Torej preostala izmed Uzíjahovih dejanj, prva in zadnja, je zapisal prerok Izaija, Amócov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Tako je Uzíjah zaspal s svojimi očeti in z njegovimi očeti so ga pokopali na pogrebnem polju, ki je pripadalo kraljem, kajti rekli so: »On je gobavec.« Namesto njega je zakraljeval njegov sin Jotám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotám je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let. Ime njegove matere je bilo Jerúša, Cadókova hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse to, kar je delal njegov oče Uzíjah. Vendar ni vstopil v Gospodov tempelj. Ljudstvo pa je še počelo izprijeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Zgradil je visoka velika vrata Gospodove hiše in na obzidju Ofele je mnogo gradil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Poleg tega je zgradil mesta v Judovih gorah in v gozdovih je zgradil gradove in stolpe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Boril se je tudi s kraljem Amóncev in prevladal zoper njih. Amónovi otroci so mu isto leto dali sto talentov srebra, sto tisoč mer pšenice in deset tisoč [mer] ječmena. Toliko so mu Amónovi otroci plačali tako drugo leto kakor tretje leto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Tako je Jotám postal mogočen, ker je pripravil svoje poti pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Torej preostala izmed Jotámovih dejanj in vse njegove vojne in njegove poti, glej, zapisane so v knjigi Izraelovih in Judovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Star je bil petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Jotám je zaspal s svojimi očeti in pokopali so ga v Davidovem mestu in namesto njega je zakraljeval njegov sin Aház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Aház je bil star dvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let, toda ni delal tega, kar je bilo pravilno v Gospodovih očeh, kakor njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Kajti hodil je po poteh Izraelovih kraljev in prav tako je naredil ulite podobe za Báale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Poleg tega je zažigal kadilo v dolini Hinómovega sina in svoje otroke sežigal v ognju, po ogabnostih poganov, ki jih je Gospod pregnal pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Tudi daroval je in zažigal kadilo na visokih krajih, na hribih in pod vsakim zelenim drevesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Zato ga je Gospod, njegov Bog, izročil v roko sirskega kralja in udarili so ga in izmed njih odvedli veliko množico ujetnikov in jih privedli v Damask. Izročen je bil tudi v roko Izraelovega kralja, ki ga je udaril z velikim pokolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Kajti Remaljájev sin Pékah jih je v Judu v enem dnevu ubil sto dvajset tisoč, ki so bili vsi hrabri možje, ker so zapustili Gospoda, Boga svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Zihrí, mogočen mož iz Efrájima, je usmrtil kraljevega sina Maasejája, voditelja hiše Azrikáma in Elkanája, ki je bil poleg kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Izraelovi otroci so odvedli ujetnike izmed njihovih bratov, dvesto tisoč žensk, sinov in hčera ter od njih odvzeli tudi mnogo plena in plen prinesli v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Toda tam je bil Gospodov prerok, katerega ime je bilo Odéd in ta je šel ven pred vojsko, ki je prišla do Samarije ter jim rekel: »Glejte, ker je bil Gospod, Bog vaših očetov, besen na Juda, jih je izročil v vašo roko in vi ste jih umorili v besnenju, ki sega do nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'In sedaj ste se namenili, da obdržite Judove in jeruzalemske otroke, podrejene sebi za sužnje in sužnjice. Toda ali niso z vami, celo z vami, grehi zoper Gospoda, vašega Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Sedaj me torej poslušajte in ponovno osvobodite ujetnike, ki ste jih zajeli izmed svojih bratov, kajti nad vami je ogorčen Gospodov bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Potem so nekateri izmed poglavarjev Efrájimovih otrok, Johanánov sin Azarjá, Mešilemótov sin Berehjá, Šalúmov sin Hizkijá in Hadlájev sin Amasá vstali zoper tiste, ki so prišli iz vojne');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'ter jim rekli: »Ujetnikov ne boste privedli sèm, kajti kakor smo že grešili zoper Gospoda, ste se vi namenili, da dodate še več k našim grehom in k našemu prestopku, kajti naš prestopek je velik in zoper Izraela je ogorčen bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Tako so oboroženi možje pustili ujetnike in plen pred princi in pred vso skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Možje, ki so bili določeni po imenu, so vstali, vzeli ujetnike in s plenom oblekli vse, ki so bili med njimi nagi, jih odeli, obuli, jim dali jesti in piti ter jih mazilili in vse slabotne med njimi odvedli na oslih ter jih privedli do Jerihe, mesta palmovih dreves, do njihovih bratov. Potem so se vrnili v Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Ob tistem času je kralj Aház poslal k asirskim kraljem, da mu pomagajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Kajti Edómci so ponovno prišli in udarili Juda in odvedli ujetnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Filistejci so vdrli tudi v mesta spodnje dežele in jug Juda in zavzeli Bet Šemeš, Ajalón, Gederót, Sohó in njegove vasi, Timno z njenimi vasmi, tudi Gimzó in njegove vasi in tam prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Kajti Gospod je ponižal Juda zaradi Izraelovega kralja Aháza, kajti ta je slekel Juda in se hudo pregrešil zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'K njemu je prišel asirski kralj Tiglát Pilnéser in ga stiskal, toda ni ga okrepil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Kajti Aház je odvzel delež iz Gospodove hiše in iz kraljeve hiše in od princev in to dal asirskemu kralju, toda ta mu ni pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'V času svoje stiske je še bolj grešil zoper Gospoda. To je ta kralj Aház.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Kajti žrtvoval je bogovom Damaska, ki so ga udarili in rekel: »Ker so jim pomagali bogovi sirskih kraljev, zato bom žrtvoval njim, da bi mi lahko pomagali.« Toda oni so bili propad njemu in vsemu Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Aház je zbral skupaj posode iz Božje hiše, razbil na koščke posode iz Božje hiše in zaprl vrata Gospodove hiše ter si naredil oltarje na vsakem jeruzalemskem vogalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'V vsakem posameznem Judovem mestu je postavil visoke kraje, da zažigajo kadilo drugim bogovom in do jeze dražijo Gospoda, Boga svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Torej ostala njegova dela in vse njegove poti, prve in zadnje, glej, zapisane so v knjigi Judovih in Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Aház je zaspal s svojimi očeti in pokopali so ga v mestu, torej v Jeruzalemu. Toda niso ga prinesli v mavzoleje Izraelovih kraljev. Namesto njega je zakraljeval njegov sin Ezekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezekíja je začel vladati, ko je bil star petindvajset let in v Jeruzalemu je vladal devetindvajset let. Ime njegove matere je bilo Abíja, Zeharjájeva hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Delal je, kar je bilo pravilno v Gospodovih očeh, glede na vse to, kar je storil njegov oče David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'V prvem letu svojega vladanja, v prvem mesecu, je odprl vrata Gospodove hiše in jih popravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Pripeljal je duhovnike in Lévijevce ter jih skupaj zbral na vzhodni ulici');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'ter jim rekel: »Poslušajte me, vi Lévijevci, sedaj se posvetite in posvetite hišo Gospoda, Boga svojih očetov in odnesite umazanost iz svetega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Kajti naši očetje so grešili in naredili to, kar je bilo zlo v očeh Gospoda, našega Boga, ga zapustili in svoje obraze obrnili proč od Gospodovega prebivališča in obrnili svoje hrbte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Prav tako so zaprli vrata preddverja in ugasili svetilke in niso zažigali kadila niti darovali žgalnih daritev Izraelovemu Bogu na svetem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Zato je bil Gospodov bes nad Judom in Jeruzalemom in izročil jih je v težavo, osuplost in posmeh, kakor vidite s svojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Kajti, glejte, naši očetje so padli pod mečem, naši sinovi, naše hčere in naše žene so zaradi tega v ujetništvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Sedaj je na mojem srcu, da sklenem zavezo z Gospodom, Izraelovim Bogom, da se njegov kruti bes lahko odvrne od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Moji sinovi, ne bodite sedaj nemarni, kajti Gospod vas je izbral, da stojite pred njim, da mu služite in da bi mu služili in zažigali kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Potem so vstali Lévijevci: Amasájev sin Mahat in Azarjájev sin Joél izmed sinov Kehátovcev; izmed Meraríjevih sinov Abdíjev sin Kiš in Jehalelélov sin Azarjá; izmed Geršóncev Zimájev sin Joáh in Joáhov sin Eden;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'izmed Elicafánovih sinov Šimríj in Jeiél; izmed Asáfovih sinov Zeharjá in Matanjá;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'izmed Hemánovih sinov Jehiél in Šimí in izmed Jedutúnovih sinov Šemajája in Uziél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Zbrali so svoje brate, se posvetili in prišli glede na kraljevo zapoved, po Gospodovih besedah, da očistijo Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Duhovniki so odšli v notranji del Gospodove hiše, da jo očistijo in ven prinesejo vso nečistost, ki jo najdejo v Gospodovem templju, na dvoru Gospodove hiše. In Lévijevci so to vzeli, da to odnesejo ven, v potok Kidron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Torej posvečevati so začeli na prvi dan prvega meseca in na osmi dan meseca so prišli do Gospodovega preddverja. Tako so v osmih dneh posvetili Gospodovo hišo in na šestnajsti dan prvega meseca so dokončali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Potem so odšli h kralju Ezekíju in rekli: »Očistili smo vso Gospodovo hišo in oltar žgalne daritve, z vsemi njegovimi posodami in mizo hlebov navzočnosti, z vsemi njenimi posodami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Poleg tega smo pripravili in posvetili vse posode, ki jih je kralj Aház ob svojem kraljevanju v svojem prestopku zavrgel. Glej, pred Gospodovim oltarjem so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Potem se je kralj Ezekíja zgodaj dvignil in zbral voditelje mesta ter odšel gor h Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Privedli so sedem bikcev, sedem ovnov, sedem jagnjet in sedem kozlov za daritev za greh za kraljestvo, za svetišče in za Juda. Duhovnikom, Aronovim sinovom, je zapovedal, da jih darujejo na Gospodovem oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Tako so zaklali bikce in duhovniki so prestregli kri in jo poškropili na oltar. Tudi ko so zaklali ovne, so na oltar poškropili kri. Zaklali so tudi jagnjeta in na oltar poškropili kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Pred kralja in skupnost so privedli kozle za daritev za greh in ti so svoje roke položili nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Duhovniki so jih zaklali in naredili pobotanje z njihovo krvjo na oltarju, da opravijo odkupitev za ves Izrael, kajti kralj je zapovedal, da naj bo za ves Izrael narejena žgalna daritev in daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'V Gospodovi hiši je postavil Lévijevce s cimbalami, plunkami in harfami, glede na Davidovo zapoved in [glede na zapoved] Gada, kraljevega vidca in preroka Natána, kajti taka je bila Gospodova zapoved po njegovih prerokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Lévijevci so stali z Davidovimi glasbili in duhovniki s trobentami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ezekíja je zapovedal, da na oltarju darujejo žgalno daritev. Ko se je žgalna daritev začela, se je začela tudi Gospodova pesem s trobentami in z glasbili, ki jih je določil Izraelov kralj David.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Vsa skupnost je oboževala in pevci so peli in trobentači so trobili. In vse to se je nadaljevalo, dokler ni bila dokončana žgalna daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Ko so prenehali z daritvijo, so se kralj in vsi tisti, ki so bili prisotni z njim, priklonili in oboževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Poleg tega so kralj Ezekíja in princi zapovedali Lévijevcem, da prepevajo hvalo Gospodu z besedami Davida in vidca Asáfa. In z veseljem so peli hvalnice, sklonili svoje glave in oboževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Potem je Ezekíja odgovoril in rekel: »Sedaj ste se uméstili Gospodu, pridite bliže in prinesite klavne daritve in zahvalne daritve v Gospodovo hišo.« In skupnost je prinesla klavne daritve in zahvalne daritve in toliko, kot jih je bilo voljnega srca, žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Število žgalnih daritev, ki jih je prinesla skupnost, je bilo sedemdeset bikcev, sto ovnov in dvesto jagnjet. Vsi ti so bili za žgalno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Posvečenih stvari je bilo šeststo volov in tri tisoč ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Toda duhovnikov je bilo premalo, tako da niso mogli odreti vseh žgalnih daritev, zato so jim pomagali njihovi bratje Lévijevci, dokler ni bilo delo končano in dokler se niso posvetili drugi duhovniki, kajti Lévijevci so bili bolj iskreni v srcu, da se posvetijo, kakor duhovniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Tudi žgalnih daritev je bilo v obilju, s tolščo mirovnih daritev in pitnih daritev za vsako žgalno daritev. Tako je bila služba Gospodove hiše urejena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Ezekíja se je veselil in vse ljudstvo, da je Bog pripravil ljudstvo, kajti stvar je bila storjena nenadoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Ezekíja je poslal k vsemu Izraelu in Judu in napisal tudi pisma Efrájimu in Manáseju, da naj pridejo h Gospodovi hiši v Jeruzalemu, da praznujejo pasho Gospodu, Izraelovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kajti kralj je sprejel nasvet in njegovi princi in vsa skupnost v Jeruzalemu, da v drugem mesecu praznujejo pasho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Kajti niso je mogli imeti ob tistem času, ker se duhovniki niso zadosti posvetili niti se ljudstvo ni zbralo skupaj k Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Stvar je ugajala kralju in vsej skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Tako so potrdili odlok, da ga razglasijo po vsem Izraelu, od Beeršébe, celo do Dana, da bi prišli praznovat pasho Gospodu, Izraelovemu Bogu, v Jeruzalemu, kajti že dolgo časa tega niso storili na takšen način, kot je bilo to napisano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Tako so tekači odšli s pismi kralja in njegovih princev po vsem Izraelu in Judu in glede na kraljevo zapoved, rekoč: »Vi, Izraelovi otroci, se ponovno obrnite h Gospodu, Bogu Abrahama, Izaka in Izraela in on se bo obrnil k preostanku izmed vas, ki ste pobegnili iz roke asirskih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Vi pa ne bodite podobni svojim očetom in svojim bratim, ki so grešili zoper Gospoda, Boga svojih očetov, ki jih je zato izročil v opustošenje, kakor vidite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Torej ne bodite trdovratni, kakor so bili vaši očetje, temveč se uklonite Gospodu in vstopite v njegovo svetišče, ki ga je posvetil na veke, in služite Gospodu, svojemu Bogu, da se okrutnost njegovega besa lahko odvrne od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Kajti če se ponovno obrnete h Gospodu, bodo vaši bratje in vaši otroci našli sočutje pred tistimi, ki jih vodijo ujete, tako da se bodo ponovno vrnili v to deželo, kajti Gospod, vaš Bog, je usmiljen in milostljiv in svojega obraza ne bo odvrnil od vas, če se vi vrnete k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Tako je pošta šla od mesta do mesta po vsej deželi, od Efrájima in Manáseja, celo do Zábulona, toda smejali so se jim do norčevanja in jih zasmehovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Kljub temu so se številni izmed Aserja, Manáseja in Zábulona ponižali in prišli v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Tudi v Judu je bila Božja roka, da jim da eno srce, da po Gospodovi besedi storijo zapoved kralja in princev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'V Jeruzalemu se je zbralo mnogo ljudstva, zelo velika skupnost, da bi v drugem mesecu praznovali praznik nekvašenega kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Vzdignili so se in odnesli oltarje, ki so bili v Jeruzalemu in vse kadilne oltarje so odnesli proč in jih vrgli v potok Kidron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Potem so na štirinajsti dan drugega meseca zaklali pasho. Duhovniki in Lévijevci so bili osramočeni in se posvetili in prinesli so žgalne daritve v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Stali so na svojem mestu, po njihovem običaju, glede na postavo Mojzesa, Božjega moža. Duhovniki so poškropili kri, ki so jo prejeli iz rok Lévijevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Kajti v skupnosti so bili številni, ki niso bili posvečeni, zato so bili Lévijevci zadolženi za zakol pashe za vsakogar, ki ni bil čist, da jih posvetijo Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Kajti množica ljudstva, celó številni izmed Efrájima, Manáseja, Isahárja in Zábulona se niso očistili, vendar so jedli pasho drugače, kot je bilo napisano. Toda Ezekíja je molil zanje, rekoč: »Dobri Gospod naj odpusti vsakomur,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'ki pripravlja svoje srce, da išče Boga, Gospoda Boga svojih očetov, čeprav ni očiščen glede na očiščevanje svetišča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Gospod je prisluhnil Ezekíju ter ozdravil ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Izraelovi otroci, ki so bili prisotni v Jeruzalemu, so z velikim veseljem sedem dni imeli praznik nekvašenega kruha. Lévijevci in duhovniki so dan za dnem hvalili Gospoda, pojoč Gospodu z glasnimi glasbili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ezekíja je tolažilno govoril vsem Lévijevcem, ki so učili dobrega Gospodovega spoznanja. Jedli so vseh sedem prazničnih dni, žrtvovali mirovne daritve in delali priznanje Gospodu, Bogu svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Celoten zbor se je posvetoval, da praznuje [še] drugih sedem dni. In z veseljem so praznovali [še] drugih sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Kajti Judov kralj Ezekíja je dal skupnosti tisoč bikcev in sedem tisoč ovc, in princi so dali skupnosti tisoč bikcev in deset tisoč ovc. In veliko število duhovnikov se je posvetilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Vsa Judova skupnost, z duhovniki in Lévijevci in ves zbor, ki je prišel iz Izraela in tujci, ki so prišli iz Izraelove dežele in tisti, ki so prebivali v Judu, so se veselili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Tako je bila v Jeruzalemu velika radost, kajti od časa Salomona, Davidovega sina, Izraelovega kralja, ni bilo v Jeruzalemu ničesar podobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Potem so duhovniki, Lévijevci, vstali, blagoslovili ljudstvo in njihov glas je bil slišan in njihova molitev je prišla gor do njegovega svetega prebivališča, celó do nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Torej, ko je bilo vse to končano, je ves Izrael, ki je bil prisoten, odšel ven v Judova mesta in na koščke so razbili podobe, posekali ašere, podrli visoke kraje in oltarje iz vsega Juda in Benjamina, tudi v Efrájimu in Manáseju, dokler niso vseh uničili do konca. Potem so se vsi Izraelovi otroci vrnili, vsak mož k svoji posesti, v svoja lastna mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezekíja je določil skupine duhovnikov in Lévijevce po njihovih skupinah, vsakega moža glede na njegovo službo, duhovnike in Lévijevce, da služijo za žgalne daritve in za mirovne daritve, da se zahvaljujejo in da hvalijo v velikih vratih Gospodovih šotorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Določil je tudi kraljev delež njegovega imetja za žgalne daritve, namreč za jutranje in večerne žgalne daritve, za šabatne žgalne daritve, za mlaje in za določene praznike, kakor je to zapisano v Gospodovi postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Poleg tega je zapovedal ljudstvu, ki je prebivalo v Jeruzalemu, naj dajo delež duhovnikom in Lévijevcem, da bi bili lahko ohrabreni v Gospodovi postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Takoj, ko je bila zapoved razglašena, so Izraelovi otroci v obilju prinašali prvih sadov od žita, vina, olja, meda in od vsega donosa iz polja. Desetino od vseh stvari so prinašali v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Glede otrok iz Izraela in Juda, ki so prebivali v Judovih mestih, so tudi oni privedli desetino od volov in ovc in desetino od svetih stvari, ki so bile posvečene Gospodu, njihovemu Bogu in jih nalagali po kupih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'V tretjem mesecu so začeli polagati temelj kupom in jih dokončali v sedmem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Ko so Ezekíja in princi prišli in videli kupe, so blagoslovili Gospoda in njegovo ljudstvo Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Potem je Ezekíja z duhovniki in Lévijevci spraševal glede teh kupov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Véliki duhovnik Azarjá iz Cadókove hiše mu je odgovoril in rekel: »Odkar je ljudstvo začelo prinašati daritve v Gospodovo hišo, smo imeli dovolj za jesti in obilje je preostalo, kajti Gospod je blagoslovil svoje ljudstvo in to, kar je ostalo, je ta velika zaloga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Potem je Ezekíja zapovedal, da pripravijo sobe v Gospodovi hiši in pripravili so jih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'in vanje so zvesto prinašali daritve, desetine in posvečene stvari, nad katerimi je bil poveljnik, Lévijevec Konanjá in njegov brat Šimí je bil naslednji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jehiél, Azazjá, Nahat, Asaél, Jerimót, Jozabád, Eliél, Jismahjá, Mahat in Benajá so bili nadzorniki pod roko Konanjája in njegovega brata Šimíja na zapoved kralja Ezekíja in Azarjája, poveljnika Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Koré, sin Lévijevca Jimnáha, vratar proti vzhodu, je bil nad prostovoljnimi daritvami Bogu, da razdeljuje daritve Gospodu in najsvetejše stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Poleg njega so bili Eden, Minjamín, Ješúa, Šemajá, Amarjá in Šehanjá v mestih duhovnikov, v svoji določeni službi, da dajo svojim bratom po skupinah, tako velikim kakor malim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'poleg njihovega rodovnika moških, starih od treh let in navzgor, celó vsak, kdor vstopa v Gospodovo hišo, njegov dnevni delež za njihovo službo po njihovih zadolžitvah, glede na njihove skupine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Tako rodovnikom duhovnikov po hiši njihovih očetov kot Lévijevcem od dvajsetih let starosti in navzgor po njihovih zadolžitvah, po njihovih skupinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'In rodovnikom vseh njihovih malčkov, njihovih žen, njihovih sinov in njihovih hčera po vsej skupnosti, kajti v njihovi določeni službi so se posvetili v svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Tudi od sinov duhovnika Arona, ki so bili na poljih predmestij njihovih mest v vsakem posameznem mestu, možje, ki so bili določeni po imenu, da dajo deleže vsem moškim med duhovniki in vsem, ki so bili po rodovnikih prešteti med Lévijevci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Tako je storil Ezekíja po vsem Judu in delal to, kar je bilo dobro, pravilno in resnično pred Gospodom, svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'V vsakem delu, ki ga je začel v službi Božje hiše, v postavi in v zapovedih, da išče svojega Boga, je to počel z vsem svojim srcem in uspeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po teh stvareh in ustanovitvi tega je prišel asirski kralj Senaherib, vstopil v Juda, se utaboril zoper utrjena mesta in mislil, da jih osvoji zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Ko je Ezekíja videl, da je Senaherib prišel in da se je namenil, da se bojuje zoper Jeruzalem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'se je posvetoval s svojimi princi in svojimi mogočnimi možmi, da zamaši vodne studence, ki so bili zunaj mesta, in ti so mu pomagali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Tako je bilo tam skupaj zbranih veliko ljudi, ki so zamašili vse studence in potok, ki je tekel čez sredo dežele, rekoč: »Zakaj bi prišli asirski kralji in našli mnogo vode?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Prav tako se je okrepil in pozidal vse obzidje, ki je bil porušeno in ga dvignil k stolpom in drugi zid zunaj in popravil Miló v Davidovem mestu ter naredil puščic in ščitov v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Nad ljudstvom je postavil vojne poveljnike in jih zbral skupaj k sebi na ulici velikih vrat mesta in jim tolažilno govoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '»Bodite močni in pogumni, ne bodite prestrašeni niti zaprepadeni zaradi asirskega kralja niti zaradi vse množice, ki je z njim, kajti z nami jih je več kakor z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Z njim je mesen laket, toda z nami je Gospod, naš Bog, da nam pomaga in da bori naše bitke.« In ljudstvo se je opiralo na besede Judovega kralja Ezekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Za tem je asirski kralj Senaherib poslal svoje služabnike v Jeruzalem, (toda on sam je oblegal Lahíš in vsa njegova moč z njim) k Judovemu kralju Ezekíju in vsemu Judu, ki so bili v Jeruzalemu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '»Tako govori asirski kralj Senaherib: ›Komu zaupate, da ostajate v obleganem Jeruzalemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Mar vas Ezekija ne prepričuje, da bi se prepustili smrti zaradi lakote in žeje, rekoč: › Gospod, naš Bog, nas bo osvobodil iz roke asirskega kralja?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Mar ni isti Ezekíja odstranil njegove visoke kraje in njegove oltarje ter zapovedal Judu in Jeruzalemu, rekoč: ›Oboževali boste pred enim oltarjem in na njem zažigali kadilo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ne veste, kaj smo jaz in moji očetje storili vsem ljudstvom drugih dežel? Mar so bili bogovi narodov tistih dežel kakorkoli zmožni svoje dežele osvoboditi iz moje roke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kdo je bil tam med vsemi bogovi tistih narodov, ki so jih moji očetje popolnoma uničili, ki bi lahko osvobodil svoje ljudstvo iz moje roke, da bi vas bil vaš Bog zmožen osvoboditi iz moje roke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Zdaj torej naj vas Ezekíja ne zavede niti pregovori o tej zadevi niti mu še ne verjemite, kajti noben bog iz kateregakoli naroda ali kraljestva ni bil zmožen osvoboditi svojega ljudstva iz moje roke in iz roke mojih očetov. Kako veliko manj vas bo vaš Bog osvobodil iz moje roke?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Njegovi služabniki so še bolj govorili zoper Gospoda Boga in zoper njegovega služabnika Ezekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Napisal je tudi pisma, da udriha po Gospodu, Izraelovemu Bogu in da govori zoper njega, rekoč: »Kakor bogovi narodov drugih dežel niso osvobodili svojih ljudstev iz moje roke, tako Ezekíjev Bog ne bo osvobodil svojega ljudstva iz moje roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Potem so z močnim glasom zaklicali v Judovskem jeziku jeruzalemskemu ljudstvu, ki so bili na obzidju, da jih prestrašijo in da jih vznemirijo, da bi lahko zavzeli mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Govorili so zoper jeruzalemskega Boga kakor zoper bogove ljudstev zemlje, ki so bili delo človeških rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Zaradi tega razloga sta kralj Ezekíja in prerok Izaija, Amócov sin, molila in klicala k nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'In Gospod je poslal angela, ki je usmrtil vse močne junaške može ter voditelje in poveljnike v taboru asirskega kralja. Tako se je ta z osramočenim obrazom vrnil k svoji lastni deželi. Ko pa je prišel v hišo svojega boga, sta ga tam z mečem usmrtila tista [dva], ki sta prišla iz njegovih lastnih ledij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tako je Gospod rešil Ezekíja in prebivalce Jeruzalema iz roke asirskega kralja Senaheriba in iz roke vseh drugih ter jih usmerjal na vsaki strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Mnogi so Gospodu prinašali darila v Jeruzalem in darila Judovemu kralju Ezekíju, tako da je bil od takrat naprej poveličan v očeh vseh narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'V tistih dneh je bil Ezekíja na smrt bolan in molil h Gospodu in ta mu je spregovoril ter mu dal znamenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Toda Ezekíja ni povrnil glede na korist, izkazano njemu, kajti njegovo srce je bilo povzdignjeno. Zato je bil bes nad njim, nad Judom in [nad] Jeruzalemom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Vendar se je Ezekíja ponižal zaradi ošabnosti svojega srca, tako on kakor prebivalci Jeruzalema, tako da v Ezekíjevih dneh Gospodov bes ni prišel nadnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ezekíja je imel silno veliko bogastev in časti. Naredil si je zakladnice za srebro, zlato, dragocene kamne, dišave, ščite in za vse vrste prijetnih dragocenosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'tudi skladišča za donos od žita, vina in olja in hleve za vse vrste živali in staje za trope.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Poleg tega si je priskrbel mesta, posesti tropov in čred v obilju, kajti Bog mu je dal zelo veliko imetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ta isti Ezekíja je tudi ustavil gornji vodni tok Gihona in ga privedel naravnost dol k zahodni strani Davidovega mesta. Ezekíja je uspeval v vseh svojih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Vendar ga je v zadevi predstavnikov babilonskih princev, ki so poslali k njemu, da povprašajo o čudežu, ki je bil storjen v deželi, Bog zapustil, da ga preizkusi, da bi lahko spoznal vse, kar je bilo v njegovem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Torej preostala izmed Ezekíjevih dejanj in njegova dobrota, glej, zapisana so v videnju preroka Amócovega sina Izaija ter v knjigi Judovih in Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ezekíja je zaspal s svojimi očeti in pokopali so ga v glavnem izmed mavzolejev Davidovih sinov. Ves Juda in prebivalci Jeruzalema so mu ob njegovi smrti izkazali čast. Namesto njega je zakraljeval njegov sin Manáse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manáse je bil star dvanajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval petinpetdeset let,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'toda počel je to, kar je bilo zlo v Gospodovih očeh, podobno ogabnostim poganov, ki jih je Gospod pregnal pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Kajti ponovno je zgradil visoke kraje, ki jih je njegov oče Ezekíja porušil, vzdignil Báalove oltarje, naredil ašere in oboževal vso vojsko neba ter jim služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Prav tako je zgradil oltarje v Gospodovi hiši, o kateri je Gospod rekel: »V Jeruzalemu bo moje ime na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Zgradil je oltarje za vso vojsko neba v dveh dvorih Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Svoje otroke je izročil, da gredo skozi ogenj v dolini sina Hinómovega. Obeleževal je tudi čase, uporabljal izrekanje urokov, uporabljal čarovništvo in postopal z osebnim duhom in s čarovniki. Storil je mnogo zla v Gospodovih očeh, da ga izziva do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Postavil je izrezljano podobo, malika, ki ga je naredil v Božji hiši, o kateri je Bog rekel Davidu in njegovemu sinu Salomonu: »V tej hiši, v Jeruzalemu, ki sem jo izbral pred vsemi Izraelovimi rodovi, bom svoje ime postavil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Niti ne bom več odstranil Izraelovega stopala iz dežele, ki sem jo določil za vaše očete, tako da bodo pazili, da storijo vse, kar sem jim zapovedal, glede na celotno postavo, zakone in odredbe po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Tako je Manáse storil Judu in prebivalcem Jeruzalema, da zaidejo in da počnejo huje kakor pogani, ki jih je Gospod uničil pred Izraelovimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Gospod je spregovoril Manáseju in njegovemu ljudstvu, toda niso hoteli prisluhniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Zato je Gospod nadnje privedel poveljnike vojske asirskega kralja, ki so Manáseja zajeli med trnjem in ga zvezali z okovi ter ga odvedli v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Ko je bil v stiski, je iskal Gospoda, svojega Boga in se silno ponižal pred Bogom svojih očetov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'in molil k njemu in izprošen je bil od njega in slišal je njegovo ponižno prošnjo in ga ponovno privedel k Jeruzalemu, v njegovo kraljestvo. Potem je Manáse spoznal, da je bil Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Torej po tem je zgradil zid zunaj Davidovega mesta, na zahodni strani Gihona, v dolini, celo pri vhodu velikih ribjih vrat in obdal Ofel ter ga dvignil na zelo veliko višino in vojne poveljnike postavil v vsa utrjena Judova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Odstranil je tuje bogove in malike iz Gospodove hiše in vse oltarje, ki jih je zgradil na gori Gospodove hiše in v Jeruzalemu ter jih vrgel iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Popravil je Gospodov oltar in na njem žrtvoval mirovne daritve in zahvalne daritve in Judu zapovedal, da služi Gospodu, Izraelovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Kljub temu je ljudstvo še vedno darovalo na visokih krajih, vendar samo Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Torej preostala izmed Manásejevih dejanj, njegova molitev k njegovemu Bogu in besede vidcev, ki so mu govorili v imenu Gospoda, Izraelovega Boga, glej, ta so zapisana v knjigi Izraelovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Tudi njegova molitev in kako je bil Bog izprošen od njega, ves njegov greh, njegov prekršek in kraji, na katerih si je zgradil visoke kraje ter postavil ašere in rezane podobe, preden je bil ponižan. Glej, ta so zapisana med izreki vidcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Tako je Manáse zaspal s svojimi očeti in pokopali so ga v njegovi lastni hiši. Namesto njega je zakraljeval njegov sin Amón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amón je bil star dvaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval dve leti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Toda počel je to, kar je bilo zlo v Gospodovih očeh, kakor je počel njegov oče Manáse, kajti Amón je žrtvoval vsem izrezljanim podobam, ki jih je naredil njegov oče Manáse in jim služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Ni se ponižal pred Gospodom, kakor se je ponižal njegov oče Manáse, temveč je Amón bolj in bolj grešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'In njegovi služabniki so se zarotili zoper njega in ga usmrtili v njegovi lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Toda ljudstvo dežele je usmrtilo vse tiste, ki so se zarotili zoper kralja Amóna in ljudstvo dežele je postavilo njegovega sina Jošíja za kralja namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Jošíja je bil star osem let, ko je začel kraljevati in v Jeruzalemu je kraljeval enaintrideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Delal je to, kar je bilo pravilno v Gospodovih očeh in hodil po poteh svojega očeta Davida in se ni nagnil niti k desni roki niti k levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Kajti v osmem letu svojega kraljevanja, ko je bil še mlad, je začel iskati Boga svojega očeta Davida in v dvanajstem letu je začel čistiti Juda in Jeruzalem pred visokimi kraji, ašerami, izrezljanimi podobami in ulitimi podobami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'V njegovi prisotnosti so porušili Báalove oltarje in podobe, ki so bile visoko nad njimi, je posekal. Ašere, izrezljane podobe in ulite podobe je zdrobil na koščke in iz njih naredil prah in ga raztresel po grobovih tistih, ki so jim žrtvovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Kosti duhovnikov je sežgal na njihovih oltarjih ter očistil Juda in Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Tako je storil v mestih Manáseja, Efrájima in Simeona, celo do Neftálija, z njihovimi motikami naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Ko je porušil oltarje in ašere in je rezane podobe poteptal v prah in posekal vse malike po vsej izraelski deželi, se je vrnil v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Torej v osemnajstem letu njegovega kraljevanja, ko je očistil deželo in hišo, je poslal Acaljájevega sina Šafána, voditelja mesta Maasejája in Joaházovega sina letopisca Joáha, da popravi hišo Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Ko so prišli k vélikemu duhovniku Hilkijáju so izročili denar, ki je bil prinesen v Božjo hišo, ki so ga zbrali Lévijevci, ki so varovali vrata, iz roke Manáseja, Efrájima in vsega Izraelovega preostanka in od vsega Juda in Benjamina in se vrnili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Položili so ga v roko delavcev, ki so imeli nadzor nad Gospodovo hišo in ga izročili delavcem, ki so delali v Gospodovi hiši, da hišo popravijo in izboljšajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Izročila sta ga celo rokodelcem in graditeljem, da kupijo klesan kamen, les za vezi in da tlakujejo hiše, ki so jih Judovi kralji uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Možje so zvesto opravljali delo in njihovi nadzorniki so bili Jahat in Obadjá, Lévijevca izmed Meraríjevih sinov; Zeharjá in Mešulám izmed Kehátovih sinov, da bi ga nadzirali in drugi izmed Lévijevcev, vsi, ki so vešči glasbenih instrumentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Bili so tudi nad nosilci bremen in bili so nadzorniki vseh teh, ki so na kakršen koli način opravljali delo. Izmed Lévijevcev so bili pisarji, častniki in vratarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Ko so jemali ven denar, ki je bil prinesen v Gospodovo hišo, je duhovnik Hilkijá našel knjigo Gospodove postave, ki je bila dana po Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Hilkijá je odgovoril in pisarju Šafánu rekel: »V Gospodovi hiši sem našel knjigo postave.« In Hilkijá je knjigo izročil Šafánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Šafán je knjigo odnesel h kralju in [poleg tega] kralju prinesel besedo, rekoč: »Vse, kar je bilo poverjeno tvojim služabnikom, so to storili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Skupaj so zbrali denar, ki je bil najden v Gospodovi hiši ter ga izročili v roko nadzornikov in delavcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Potem je pisar Šafán povedal kralju, rekoč: »Duhovnik Hilkijá mi je izročil knjigo.« In Šafán jo je bral pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Zgodilo se je, ko je kralj slišal besede postave, da je pretrgal svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Kralj je ukazal Hilkijáju, Šafánovemu sinu Ahikámu, Mihajájevemu sinu Abdónu, pisarju Šafánu in kraljevemu služabniku Asajáju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '»Pojdite, vprašajte Gospoda zame in za tiste, ki so preostali v Izraelu in Judu, glede besed knjige, ki se je našla, kajti velik je Gospodov bes, ki je izlit na nas, ker se naši očetje niso držali Gospodove besede, da bi delali po vsem, kar je napisano v tej knjigi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Hilkijá in tisti, ki jih je kralj določil, so odšli k prerokinji Huldi, ženi Šalúma, Tikvájevega sina, Hasrájevega sina, varuha garderobe (torej prebivala je v Jeruzalemu, v drugem okraju) in ji prav tako govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Odgovorila jim je: »Tako govori Gospod, Izraelov Bog: ›Povejte človeku, ki vas je poslal k meni:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, '›Tako govori Gospod: ›Glejte, zlo bom privedel nad ta kraj in nad njegove prebivalce, celó vsa prekletstva, ki so zapisana v knjigi, ki so jo brali pred Judovim kraljem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'ker so me zapustili in zažigali kadilo drugim bogovom, da bi me lahko dražili do jeze z vsemi deli svojih rok, zato bo moj bes izlit na ta kraj in ne bo pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Kar se tiče Judovega kralja, ki vas je poslal, da poizveste od Gospoda, mu boste rekli takole: ›Tako govori Gospod, Izraelov Bog, glede besed, ki si jih slišal:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, '›Ker je bilo tvoje srce nežno in si se ponižal pred Bogom, ko si slišal njegove besede zoper to mesto in zoper njegove prebivalce in se ponižuješ pred menoj in si pretrgal svoja oblačila in jokal pred menoj; celo tudi jaz sem te slišal,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, '›Glej, zbral te bom k tvojim očetom in v miru boš zbran k svojemu grobu niti tvoje oči ne bodo videle vsega zla, ki ga bom privedel nad ta kraj in nad prebivalce istega.‹« Tako so kralju ponovno prinesli besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Potem je kralj poslal in zbral skupaj vse starešine iz Juda in Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Kraj je odšel gor v Gospodovo hišo in vsi Judovi možje, prebivalci Jeruzalema, duhovniki, Lévijevci in vse ljudstvo, veliki in mali, in na njihova ušesa je bral vse besede knjige zaveze, ki se je našla v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Kralj je stal na svojem mestu in sklenil zavezo pred Gospodom, da hodi za Gospodom in da se drži njegovih zapovedi, njegovih pričevanj in njegovih zapovedi z vsem svojim srcem in z vso svojo dušo, da izpolni besede zaveze, ki so zapisane v tej knjigi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Vsem, ki so bili prisotni v Jeruzalemu in Benjaminu, je velel, da pristopijo k temu. Prebivalci Jeruzalema so storili glede na zavezo Boga, Boga svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Jošíja je odvzel vse ogabnosti iz vseh dežel, ki so pripadale Izraelovim otrokom in pripravil vse, ki so bili prisotni v Izraelu, da služijo, torej da služijo Gospodu, svojemu Bogu. In vse svoje dni se niso odvrnili od sledenja Gospodu, Bogu svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Poleg tega je Jošíja praznoval pasho Gospodu v Jeruzalemu. Na štirinajsti dan prvega meseca so zaklali pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Postavil je duhovnike po njihovih zadolžitvah in jih ohrabril, da služijo v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Lévijevcem, ki so učili ves Izrael, ki so bili sveti Gospodu, je rekel: »Sveto skrinjo postavite v hišo, ki jo je zgradil Salomon, Davidov sin, Izraelov kralj. Ta naj ne bo breme na vaših ramah. Služite torej Gospodu, svojemu Bogu in njegovemu ljudstvu Izraelu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'in pripravite se po hišah svojih očetov, po svojih skupinah glede na pisanje Izraelovega kralja Davida in glede na pisanje njegovega sina Salomona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Stojte na svetem kraju, glede na razdelitve družin očetov, vaših bratov [od] ljudstva, in glede na razdelitev družin Lévijevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Tako zakoljite pashalno jagnje, se posvetite in pripravite svoje brate, da bodo lahko storili glede na Gospodovo besedo, po Mojzesovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Jošíja je dal ljudstvu od tropa jagnjeta in kozličke, vse za pashalne daritve, za vse, ki so bili prisotni, do številke trideset tisoč in tri tisoč bikcev. To je bilo od kraljevega imetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Njegovi princi so voljno dali ljudstvu, duhovnikom in Lévijevcem. Hilkijá, Zeharjá in Jehiél, voditelji Božje hiše, so dali duhovnikom za pashalne daritve dva tisoč in šeststo [glav] majhne živine in tristo volov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Tudi Konanjá, Šemajá in Netanél, njegovi bratje in Hašabjá, Jeiél in Jozabád, vodje Lévijevcev, so dali Lévijevcem za pashalne daritve pet tisoč [glav] majhne živine in petsto volov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Tako je bila služba pripravljena in duhovniki so stali na svojem kraju in Lévijevci po svojih skupinah, glede na kraljevo zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Zaklali so pashalno jagnje in duhovniki so poškropili kri iz njihovih rok, Lévijevci pa so jih odrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Odstranili so žgalne daritve, da bi jih lahko dali glede na oddelke družin ljudstva, da darujejo Gospodu, kakor je to zapisano v Mojzesovi knjigi. In tako so storili z voli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Pashalno jagnje so pekli z ognjem, glede na odredbo. Toda ostale svete daritve so kuhali v loncih, v kotlih in v ponvah in jih naglo razdelili med vse ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Potem so pripravili zase in za duhovnike, ker so bili duhovniki, Aronovi sinovi, zaposleni pri darovanju žgalnih daritev in tolšče do noči, zato so Lévijevci pripravili zase in za duhovnike, Aronove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Pevci, Asáfovi sinovi, so bili na svojem mestu, glede na zapoved Davida, Asáfa, Hemána in kraljevega vidca Jedutúna. Vratarji so čakali pri vsakih velikih vratih. Niso mogli oditi od svoje službe, kajti njihovi bratje Lévijevci so pripravljali zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tako je bila vsa Gospodova služba pripravljena isti dan, da praznujejo pasho in da darujejo žgalne daritve na Gospodovem oltarju, glede na zapoved kralja Jošíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Izraelovi otroci, ki so bili prisotni, so ob tistem času sedem dni praznovali pasho in praznik nekvašenega kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Nobene pashe ni bilo podobne tej, ki so jo praznovali v Izraelu, od dni preroka Samuela niti niso vsi Izraelovi kralji praznovali takšne pashe, kot so jo praznovali Jošíja, duhovniki, Lévijevci in ves Juda, Izrael in prebivalci Jeruzalema, ki so bili prisotni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'V osemnajstem letu kraljevanja Jošíja so praznovali to pasho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Po vsem tem, ko je Jošíja pripravil tempelj, je prišel gor iz Egipta kralj Nehu, da se bojuje zoper Kárkemiš pri Evfratu. Jošíja je odšel ven zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Toda ta je k njemu poslal predstavnike, rekoč: »Kaj imam opraviti s teboj, Judov kralj? Danes nisem prišel zoper tebe, temveč zoper hišo, s katero imam vojno, kajti Bog mi je zapovedal, da pohitim. Zadrži se pred vmešavanjem z Bogom, ki je z menoj, da te on ne uniči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Kljub temu Jošíja svojega obraza ni hotel obrniti od njega, temveč se je preoblekel, da bi se lahko boril z njim in ni prisluhnil besedam Nehuja iz Božjih ust in je šel, da se bojuje v dolini Megído.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Lokostrelci pa so zadeli kralja Jošíja in kralj je rekel svojim služabnikom: »Odpeljite me proč, kajti hudo sem ranjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Njegovi služabniki so ga torej vzeli iz tega bojnega voza in ga položili na drug bojni voz, ki ga je imel. Privedli so ga v Jeruzalem in umrl je in bil pokopan v enem izmed mavzolejev svojih očetov. Ves Juda in Jeruzalem je žaloval za Jošíjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremija je žaloval za Jošíjem in vsi pevci in pevke so do tega dne v svojih žalostinkah govorili o Jošíju in jih naredili za odredbo v Izraelu. Glej, zapisane so v žalostinkah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Torej preostala izmed Jošíjevih dejanj in njegova dobrota, glede na to, kar je bilo napisano v Gospodovi postavi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'in njegova dejanja, prva in zadnja, glej, zapisana so v knjigi Izraelovih in Judovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Potem je ljudstvo dežele vzelo Jošíjevega sina Joaháza in ga v Jeruzalemu postavilo [za] kralja namesto njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joaház je bil star triindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval tri mesece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Egiptovski kralj ga je odstavil v Jeruzalemu in deželo obsodil na sto talentov srebra in talent zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Egiptovski kralj je postavil njegovega brata Eljakíma [za] kralja nad Judom in Jeruzalemom ter njegovo ime spremenil v Jojakím. Neho je vzel njegovega brata Joaháza in ga odvedel v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jojakím je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljevati enajst let. Počel je to, kar je bilo zlo v očeh Gospoda, njegovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Zoper njega je prišel gor babilonski kralj Nebukadnezar in ga zvezal v okove, da ga odvede v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nebukadnezar je v Babilon odnesel tudi posode Gospodove hiše in jih postavil v svoj tempelj v Babilonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Torej preostala izmed Jojakímovih dejanj in njegove ogabnosti, ki jih je storil in to, kar je bilo najdeno v njem, glej, ta so zapisana v knjigi Izraelovih in Judovih kraljev, in namesto njega je zakraljeval njegov sin Jojahín.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jojahín je bil star osem let, ko je začel kraljevati in v Jeruzalemu je kraljeval tri mesece in deset dni. Počel je to, kar je bilo zlo v Gospodovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Ko je minilo leto, je kralj Nebukadnezar poslal in ga privedel v Babilon, s čudovitimi posodami Gospodove hiše in je njegovega brata Sedekíja postavil [za] kralja nad Judom in Jeruzalemom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sedekíja je bil star enaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval enajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Počel je to, kar je bilo zlo v očeh Gospoda, njegovega Boga in se ni ponižal pred prerokom Jeremijem, ki je govoril iz Gospodovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Uprl se je tudi zoper kralja Nebukadnezarja, ki ga je pripravil, da priseže pri Bogu. Toda otrdil je svoj vrat in zakrknil svoje srce pred obrnitvijo h Gospodu, Izraelovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Poleg tega so se vse vodje izmed duhovnikov in ljudstva zelo pregrešili za vsemi ogabnostmi poganov in oskrunili Gospodovo hišo, ki jo je posvetil v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Gospod, Bog njihovih očetov je pošiljal k njim po svojih poslancih, zgodaj vstajal in pošiljal, ker je imel sočutje do njegovega ljudstva in do njegovih prebivališč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Toda zasmehovali so Božje poslance, prezirali njegove besede in zlorabljali njegove preroke, dokler ni zoper njegovo ljudstvo vstal Gospodov bes, dokler tam ni bilo zdravila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Zato je nadnje privedel kralja Kaldejcev, ki je njihove mladeniče usmrtil z mečem v hiši njihovega svetišča in ni imel sočutja nad mladeničem ali mladenko, starcem ali tistim, ki je sklonjen zaradi starosti; vse jih je izročil v njegovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Vse posode Božje hiše, velike in majhne, zaklade Gospodove hiše in kraljeve zaklade in [zaklade] njegovih princev; vse te je prinesel v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Zažgali so Božjo hišo, porušili jeruzalemsko obzidje, vse palače požgali z ognjem in uničili vse njegove čudovite posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Tiste, ki so pobegnili pred mečem, je odvedel v Babilon, kjer so bili služabniki njemu in njegovim sinovom do kraljevanja perzijskega kraljestva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'da izpolni Gospodovo besedo po Jeremijevih ustih, dokler se dežela ne naužije svojih šabat, kajti dokler leži zapuščena, praznuje šabate, da izpolni sedemdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Torej v prvem letu perzijskega kralja Kira, da bi se Gospodova beseda, govorjena po ustih Jeremija, lahko dovršila, je Gospod razvnel duha perzijskega kralja Kira, da je naredil razglas po vsem svojem kraljestvu in ga položil tudi v pisanje, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '»Tako govori Kir, kralj Perzije: ›Vsa kraljestva zemlje je Gospod, Bog nebes, izročil meni in zadolžil me je, da mu zgradim hišo v Jeruzalemu, ki je v Judeji. Kdo je tukaj med vami izmed vsega njegovega ljudstva? Gospod, njegov Bog naj bo z njim in naj ta gre gor.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Torej v prvem letu perzijskega kralja Kira, da se je lahko izpolnila Gospodova beseda po Jeremijevih ustih, je Gospod razvnel duha perzijskega kralja Kira, da je naredil razglas po vsem svojem kraljestvu in ga položil tudi v pisanje, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '»Tako govori perzijski kralj Kir: › Gospod, Bog nebes, mi je izročil vsa kraljestva zemlje in me zadolžil, da mu zgradim hišo v Jeruzalemu, ki je v Judeji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kdo je tam med vami izmed vsega njegovega ljudstva? Njegov Bog bo z njim in ta naj gre gor v Jeruzalem, ki je v Judeji in zgradi hišo Gospodu, Izraelovemu Bogu (on je Bog), ki je v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Kdorkoli pa ostaja na kateremkoli kraju, kjer začasno biva, naj mu možje iz njegovega kraja pomagajo s srebrom, z zlatom, z dobrinami in z živalmi, poleg prostovoljnih daritev za Božjo hišo, ki je v Jeruzalemu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Potem so vstali vodja očetov Juda in Benjamina, duhovniki in Lévijevci, z vsemi tistimi, ki jih je dvignil Božji duh, da gredo gor gradit Gospodovo hišo, ki je v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Vsi, ki so bili okoli njih, so svoje roke okrepili s posodami iz srebra, z zlatom, z dobrinami in z živalmi in z dragocenimi stvarmi, poleg vsega, kar so prostovoljno darovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Tudi kralj Kir je prinesel posode iz Gospodove hiše, ki jih je Nebukadnezar prinesel iz Jeruzalema in jih postavil v hišo svojih bogov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'celo tiste je perzijski kralj Kir prinesel naprej po roki zakladnika Mitridáta in jih odštel Judovemu princu Šešbacárju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'To je njihovo število: trideset velikih pladnjev iz zlata, tisoč velikih pladnjev iz srebra, devetindvajset nožev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'trideset umivalnikov iz zlata, srebrnih umivalnikov druge vrste štiristo deset in tisoč drugih posod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Vseh posod iz zlata in iz srebra je bilo pet tisoč štiristo. Vse te je Šešbacár prinesel gor s tistimi iz ujetništva, ki so bili iz Babilona privedeni gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Torej to so otroci iz province, ki se je dvignila iz ujetništva, izmed tistih, ki so bili odvedeni proč, ki jih je babilonski kralj Nebukadnezar odvedel v Babilon in so ponovno prišli v Jeruzalem in Judejo, vsak v svoje mesto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'ki so prišli z Zerubabélom: Ješúa, Nehemija, Serajá, Reelajá, Mordohaj, Bilšán, Mispar, Bigváj, Rehúm in Baaná. Število mož Izraelovega ljudstva:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paróševih otrok dva tisoč sto dvainsedemdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Šefatjájevih otrok tristo dvainsedemdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Aráhovih otrok sedemsto petinsedemdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahat Moábovih otrok, od otrok Ješúa in Joába, dva tisoč osemsto dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elámovih otrok tisoč dvesto štiriinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Zatújevih otrok devetsto petinštirideset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Zakájevih otrok sedemsto šestdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Baníjevih, otrok šeststo dvainštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebájevih otrok šeststo triindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Azgádovih otrok tisoč dvesto dvaindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikámovih otrok šeststo šestinšestdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvájevih otrok dva tisoč šestinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adínovih otrok štiristo štiriinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Atêrjevih otrok, od Ezekíja, osemindevetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Becájevih otrok tristo triindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jorájevih otrok sto dvanajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hašúmovih otrok dvesto triindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibárjevih otrok petindevetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'otrok iz Betlehema sto triindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'mož iz Netófe šestinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'mož iz Anatóta sto osemindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'otrok iz Azmáveta dvainštirideset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'otrok iz Kirját Aríma, Kefíre in Beeróta sedemsto triinštirideset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'otrok iz Rame in Gabe šeststo enaindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'mož iz Mihmása sto dvaindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'mož iz Betela in Aja dvesto triindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'otrok iz Nebója dvainpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'otrok iz Magbíša sto šestinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'otrok iz drugega Eláma tisoč dvesto štiriinpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'otrok iz Haríma tristo dvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'otrok iz Loda, Hadída in Onója sedemsto petindvajset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'otrok iz Jerihe tristo petinštirideset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'otrok iz Senaája tri tisoč šeststo trideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Duhovniki: Jedajájevi otroci iz Ješúove hiše devetsto triinsedemdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Imêrjevih otrok tisoč dvainpetdeset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pašhúrjevih otrok tisoč dvesto sedeminštirideset;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Harímovih otrok tisoč sedemnajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Lévijevci: otroci Ješúa in Kadmiéla, od Hodavijájevih otrok štiriinsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Pevci: Asáfovih otrok sto osemindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Otroci vratarjev: Šalúmovi otroci, Atêrjevi otroci, Talmónovi otroci, Akúbovi otroci, Hatitájevi otroci, Šobájevi otroci, vseh sto devetintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, '§ Netinimci: Cihájevi otroci, Hasufájevi otroci, Tabaótovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Kerósovi otroci, Siáhovi, otroci, Padónovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebanájevi otroci, Hagabájevi otroci, Akúbovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagábovi otroci, Salmájevi otroci, Hanánovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Gidélovi otroci, Gaharjevi otroci, Reajájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Recínovi otroci, Nekodájevi otroci, Gazámovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Uzájevi otroci, Paséahovi otroci, Besájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnájevi otroci, otroci Meunéjcev, otroci Nefuséjcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbúkovi otroci, Hakufájevi otroci, Harhúrjevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Baclútovi otroci, Mehidájevi otroci, Haršájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkósovi otroci, Siserájevi otroci, Temahovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Necíahovi otroci, Hatifájevi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Otroci Salomonovih služabnikov: Sotájevi otroci, Soféretovi otroci, Perudájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaaláhjevi otroci, Darkónovi otroci, Gidélovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Šefatjájevi otroci, Hatílovi otroci, Pohêret Cebájimovi otroci, Amíjevi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, '§ Vseh Netinimcev in otrok Salomonovih služabnikov je bilo tristo dvaindevetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'In to so bili tisti, ki so odšli gor iz Tel Melaha, Tel Harše, Kerúba, Adana in Imêrja, toda niso mogli pokazati hiše svojega očeta in svojega semena, če so bili iz Izraela:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delajájevi otroci, Tobijevi otroci, Nekodájevi otroci, šeststo dvainpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Izmed otrok duhovnikov: Habajájevi otroci, Kocovi otroci, otroci Barzilája; ki si je vzel ženo izmed hčera Gileádca Barzilája in je bil imenovan po njihovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ti so iskali svoj seznam med tistimi, ki so bili prešteti po rodovniku, toda niso bili najdeni, zato so bili le-ti, kakor omadeževani, odstranjeni od duhovništva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, '§ In Tirsata jim je rekel, da naj ne jedo od najsvetejših stvari, dokler ne vstane duhovnik z Urímom in Tumímom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Celotne skupnosti je bilo skupaj dvainštirideset tisoč tristo šestdeset,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'poleg njihovih služabnikov in njihovih služabnic, od katerih jih je bilo tam sedem tisoč tristo sedemintrideset. Tam je bilo med njimi dvesto pevcev in pevk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Njihovih konjev je bilo sedemsto šestintrideset, njihovih mul dvesto petinštirideset,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'njihovih kamel štiristo petintrideset in njihovih oslov šest tisoč sedemsto dvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Nekateri izmed vodij očetov so, ko so prišli v Gospodovo hišo, ki je v Jeruzalemu, prostovoljno darovali za Božjo hišo, da se ta postavi na njenem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Po svoji zmožnosti so v delovni sklad darovali enainšestdeset tisoč darejkov zlata, pet tisoč funtov srebra in sto duhovniških oblačil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Tako so duhovniki, Lévijevci, nekateri izmed ljudstva, pevci, vratarji in Netinimci prebivali v svojih mestih in ves Izrael v svojih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Ko je prišel sedmi mesec in so bili Izraelovi otroci v mestih, se je ljudstvo kakor en človek zbralo skupaj v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Potem je vstal Jocadákov sin Ješúa in njegovi bratje duhovniki in Šealtiélov sin Zerubabél in njegovi bratje in zgradili so oltar Izraelovemu Bogu, da na njem darujejo žgalne daritve, kakor je to zapisano v postavi Mojzesa, Božjega moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Nad njegovimi podnožji so postavili oltar, kajti strah je bil nad njimi zaradi ljudstva tistih dežel. Na njem so darovali žgalne daritve Gospodu, torej žgalne daritve zjutraj in zvečer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Imeli so tudi šotorski praznik, kakor je ta zapisan in darovali so dnevne žgalne daritve po številu, glede na navado, kakor je zahtevala vsakodnevna dolžnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Potem so darovali nenehno žgalno daritev, tako na mlaje in ob vseh določenih Gospodovih praznikih, [tisti], ki so bili posvečeni in od vsakega, ki je voljno daroval prostovoljno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Od prvega dne sedmega meseca so začeli darovati žgalne daritve Gospodu. Toda temelj Gospodovega templja še ni bil položen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Denar so dajali tudi zidarjem in tesarjem; in hrano, pijačo in olje tistim iz Sidóna in tistim iz Tira, da iz Libanona pripeljejo cedrova drevesa k morju pri Jopi, glede na dovoljenje, ki so ga imeli od perzijskega kralja Kira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Torej v drugem letu svojega prihoda k Božji hiši v Jeruzalemu, v drugem mesecu, so začeli Šealtiélov sin Zerubabél, Jocadákov sin Ješúa in preostanek izmed njihovih bratov duhovnikov in Lévijevcev in vsi tisti, ki so prišli iz ujetništva v Jeruzalem in določili so Lévijevce, od dvajset let stare in navzgor, da poženejo delo Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Potem so skupaj vstali Ješúa, s svojimi sinovi in svojimi brati, Kadmiél in njegovi sinovi, Judovi sinovi, da postavijo delavce v Božji hiši, Henadádove sinove z njihovimi sinovi in njihovimi brati Lévijevci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Ko so graditelji položili temelj Gospodovemu templju, so postavili duhovnike v njihovi obleki s trobentami in Lévijevce, Asáfove sinove, s cimbalami, da hvalijo Gospoda, po odredbi Izraelovega kralja Davida.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Peli so skupaj po skupini v slavljenju in zahvaljevanju Gospodu, ker je dober, kajti njegovo usmiljenje do Izraela traja večno. In vse ljudstvo je vriskalo z močnim vzklikanjem, ko so hvalili Gospoda, ker je bil položen temelj Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Vendar pa so mnogi izmed duhovnikov in Lévijevcev in vodij očetov, ki so bili starodavni ljudje, ki so videli prvo hišo, ko so bili temelji te hiše položeni pred njihovimi očmi, jokali z močnim glasom in mnogi so zaradi radosti na glas vzklikali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'tako da ljudstvo ni moglo razločiti glasu radostnega vzklikanja od glasu jokanja ljudstva, kajti ljudstvo je vzklikalo z glasnim vriskom in zvok je bilo slišati daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Torej, ko so Judovi in Benjaminovi nasprotniki slišali, da so otroci iz ujetništva gradili tempelj Gospodu, Izraelovemu Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'so potem prišli k Zerubabélu in k vodjem očetov ter jim rekli: »Naj gradimo z vami, kajti iščemo vašega Boga, kakor ga iščete vi. Darujemo mu od dni asirskega kralja Asarhadóna, ki nas je privedel sèm gor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Toda Zerubabél, Ješúa in drugi izmed vodij Izraelovih očetov, so jim rekli: »Ničesar nimate z nami, da gradite hišo našemu Bogu, temveč bomo mi sami gradili Gospodu, Izraelovemu Bogu, kakor nam je zapovedal perzijski kralj Kir.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Potem je ljudstvo dežele slabilo roke Judovega ljudstva in jim oteževalo gradnjo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'in zoper njih so najeli svetovalce, da onemogočajo njihov namen vse dni perzijskega kralja Kira, celo do kraljevanja perzijskega kralja Dareja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'In v kraljevanju Ahasvérja, na začetku njegovega kraljevanja, so mu napisali obtožbo zoper prebivalce Juda in Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'V dneh Artakserksa so Bišlám, Mitridát, Tabeél in ostali njihovi družabniki, pisali Artakserksu, kralju Perzije. Pisanje pisma je bilo napisano v sirskem jeziku in pojasnjeno v sirskem jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Kancler Rehúm in pisar Šimšáj sta kralju Artakserksu napisala pismo zoper Jeruzalem na ta način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, '§ Potem so napisali kancler Rehúm, pisar Šimšáj in ostali njegovi družabniki, Dinaji, Afarsatkaji, Tarpelaji, Afarsaji, Arkovci, Babilonci, Susančani, Dehaji in Elámci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'in preostanek narodov, ki jih je veliki in plemeniti Asenapár privedel čez in nastanil v mestih Samarije in preostanek, ki so na tej strani reke in itd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'To je prepis pisma, ki so ga poslali k njemu, torej kralju Artakserksu: ›Tvoji služabniki, ljudje na tej strani reke itd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'To bodi znano kralju, da Judje, ki so od tebe prišli k nam v Jeruzalem, gradijo uporno in slabo mesto in postavili so njegove zidove in povezali temelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'To bodi sedaj znano kralju, da če bo to mesto zgrajeno in zidovi ponovno postavljeni, potem ne bodo plačevali pristojbine, davka in carine in tako boš oškodoval prihodke kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Torej ker imamo vzdrževanje od kraljeve palače in to ni primerno za nas, da vidimo kraljevo nečast, smo zato poslali in potrdili kralju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'da bo lahko narejena preiskava v knjigi zapisov tvojih očetov. Tako boš našel v knjigi zapisov in spoznal, da je to mesto uporno mesto in škodljivo za kralje in province in da so snovali vstaje znotraj davnih časov, zaradi katerega razloga je bilo to mesto uničeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Potrjujemo kralju, da če bo to mesto ponovno zgrajeno in njegovi zidovi postavljeni, to pomeni, da ne boš imel nobenega deleža na tej strani reke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Potem je kralj poslal odgovor kanclerju Rehúmu, pisarju Šimšáju in ostalim njegovim družabnikom, ki prebivajo v Samariji in k drugim preko reke: ›Mir itd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Pismo, ki ste nam ga poslali, je bilo razločno prebrano pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Zapovedal sem in narejena je bila preiskava in najdeno je, da je to mesto od starih časov snovalo upor zoper kralje in da sta v njem narejena vstaja in upor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Mogočni kralji so bili tudi nad Jeruzalemom, ki je vladal nad vsemi deželami onkraj reke in njim so plačevali pristojbino, davek in carino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Izdajte sedaj zapoved, da ti možje prenehajo in da to mesto ne bo zgrajeno, dokler od mene ne bo izdana druga zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Pazite sedaj, da vam to ne spodleti. Zakaj bi škoda rasla na škodo kraljev?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Torej ko je bil prepis Artakserksovega pisma prebran pred Rehúmom, pisarjem Šimšájem in njihovimi družabniki, so v naglici odšli gor v Jeruzalem k Judom in jih s silo in močjo pripravili, da odnehajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Potem je prenehalo delo Božje hiše, ki je v Jeruzalemu. Tako je prenehalo do drugega leta kraljevanja perzijskega kralja Dareja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Potem sta preroka, prerok Agej in Zaharija, Idójev sin, prerokovala Judom, ki so bili v Judeji in Jeruzalemu, v imenu Izraelovega Boga, celó njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Potem sta vstala Šealtiélov sin Zerubabél in Jocadákov sin Ješúa in začela graditi Božjo hišo, ki je v Jeruzalemu in z njima so bili Božji preroki, ki so jima pomagali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Ob istem času je prišel k njim Tatenáj, voditelj na tej strani reke in Šetár Boznáj in njihovi družabniki in so jim rekli tako: »Kdo vam je zapovedal, da zgradite to hišo in da postavite to obzidje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Potem smo jih vprašali na ta način: »Kako je ime možem, ki delajo to zgradbo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Toda oko njihovega Boga je bilo nad Judovimi starešinami, da jim niso mogli storiti, da odnehajo, dokler zadeva ni prišla k Dareju. In potem so glede te zadeve po pismu vrnili odgovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, '§ Prepis pisma, ki so ga Tatenáj, voditelj na tej strani reke in Šetár Boznáj in njegovi družabniki Afarsahejci, ki so bili na tej strani reke, poslali kralju Dareju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Poslali so mu pismo, v katerem je bilo napisano takole: ›Kralju Dareju, ves mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Bodi to znano kralju, da smo šli v judejsko provinco, k hiši vélikega Boga, ki je zgrajena z velikimi kamni in tramove polagajo v zidove in to delo hitro napreduje in uspeva v njihovih rokah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Potem smo vprašali te starešine in jim rekli tako: ›Kdo vam je zapovedal, da gradite to hišo in da postavite te zidove?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Vprašali smo jih tudi za njihova imena, da ti potrdimo, da lahko napišemo imena mož, ki so bili glavni izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'In tako so nam vrnili odgovor, rekoč: ›Mi smo služabniki Boga nebes in zemlje in gradimo hišo, ki je bila zgrajena teh mnogo let nazaj, ki jo je veliki Izraelov kralj zgradil in postavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Toda potem ko so naši očetje dražili Boga nebes do besa, jih je dal v roko babilonskega kralja Nebukadnezarja, Kaldejca, ki je uničil to hišo in ljudstvo odvedel proč v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Toda v prvem letu babilonskega kralja Kira je isti kralj Kir izdal odlok, da se gradi ta Božja hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Tudi posode iz zlata in srebra iz Božje hiše, ki jih je Nebukadnezar vzel iz templja, ki je bil v Jeruzalemu in jih prenesel v babilonski tempelj, te je kralj Kir vzel iz babilonskega templja in izročene so bile nekomu, katerega ime je bilo Šešbacár, ki ga je postavil za voditelja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'in mu rekel: ›Vzemi te posode, pojdi, odnesi jih v tempelj, ki je v Jeruzalemu in naj bo Božja hiša zgrajena na svojem mestu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Potem je prišel isti Šešbacár in položil temelj Božji hiši, ki je v Jeruzalemu in od tega časa celo do sedaj je ta v gradnji in še ni dokončana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Zdaj torej, če se to zdi dobro kralju, naj se preišče v kraljevi zakladni hiši, ki je tam v Babilonu, če je to tako, da je bil izdan odlok kralja Kira, da se zgradi to Božjo hišo v Jeruzalemu in naj nam kralj pošlje svojo voljo glede te zadeve.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Potem je kralj Darej izdal odlok in narejena je bila preiskava v hiši zvitkov, kjer so bili v Babilonu shranjeni zakladi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, '§ In tam pri Ahmeti, v palači, ki je v provinci Medijcev, je bil najden zvitek in v njem je bil tako zapisan zapis:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '›V prvem letu kralja Kira je isti kralj Kir izdal odlok glede Božje hiše v Jeruzalemu: ›Naj bo hiša zgrajena, kraj, kjer so darovali daritve in naj bodo njeni temelji trdno položeni. Njena višina [naj bo] šestdeset in njena širina šestdeset komolcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 's tremi vrstami velikih kamnov in vrsto iz novih tramov in stroški naj bodo poravnani iz kraljeve hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Tudi zlate in srebrne posode Božje hiše, ki jih je Nebukadnezar vzel iz templja, ki je v Jeruzalemu in jih prenesel v Babilon, naj bodo povrnjene in ponovno prinesene v tempelj, ki je v Jeruzalemu, vsako na svoj kraj in [naj] jih prinesejo v Božjo hišo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '§ ›Sedaj torej Tatenáj, voditelj onkraj reke, Šetár Boznáj in vaši družabniki, Afarsahejci, ki so onkraj reke, bodite daleč od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Pustite delo te Božje hiše. Naj voditelj Judov in starešine Judov zgradijo to Božjo hišo na njenem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Poleg tega izdajam odlok, kaj boste naredili starešinam teh Judov za zgradbo te Božje hiše, da bodo od kraljevih dobrin, celó od davka onkraj reke, nemudoma izplačani stroški tem možem, da ne bodo ovirani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'In to, kar potrebujejo, tako mlade bikce kakor ovne in jagnjeta za žgalne daritve Bogu nebes, pšenico, sol, vino in olje, glede na določilo duhovnikov, ki so v Jeruzalemu, naj jim bo to čisto gotovo dano dan za dnem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'da bodo lahko darovali žrtvovanje prijetnih vonjav Bogu nebes in molili za življenje kralja in njegovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Prav tako sem izdal odlok, da kdorkoli bo predrugačil to besedo, naj bo tram izvlečen dol iz njegove hiše in naj bo postavljen pokonci; naj bo tisti obešen nanj in naj bo zaradi tega njegova hiša narejena za gnojišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'In Bog, ki je svojemu imenu storil, da prebiva tam, naj uniči vse kralje in ljudstvo, ki bo svojo roko položilo, da spremenijo in uničijo to Božjo hišo, ki je v Jeruzalemu. Jaz, Darej, sem zapovedal ta odlok. Naj bo hitro uresničen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Potem so Tatenáj, voditelj na tej strani reke, Šetár Boznáj in njihovi družabniki tako hitro storili glede na to, kar je kralj Darej poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Starešine Judov so gradili in uspevali po prerokovanju prerokov Ageja in Idójevega sina Zaharija. Gradili so in to končali glede na zapoved Izraelovega Boga in glede zapovedi Kira, Dareja in Artakserksa, kralja Perzije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Ta hiša je bila končana na tretji dan meseca adárja, ki je bil v šestem letu kraljevanja kralja Dareja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Izraelovi otroci, duhovniki, Lévijevci in preostanek otrok iz ujetništva, so z radostjo praznovali posvetitev te Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Pri posvetitvi te Božje hiše so darovali sto bikcev, dvesto ovnov, štiristo jagnjet. In za daritev za greh za ves Izrael dvanajst kozlov, glede na število Izraelovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Postavili so duhovnike v svojih oddelkih in Lévijevce po svojih skupinah za Božjo službo, ki je v Jeruzalemu, kakor je to zapisano v Mojzesovi knjigi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Otroci iz ujetništva so praznovali pasho na štirinajsti dan prvega meseca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Kajti duhovniki in Lévijevci so bili skupaj posvečeni, vsi izmed njih so bili čisti in zaklali so pashalno jagnje za vse otroke iz ujetništva in za njihove brate duhovnike in zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Izraelovi otroci, ki so ponovno prišli iz ujetništva in vsi tisti, ki so se ločili pred umazanostjo poganov dežele, da iščejo Gospoda, Izraelovega Boga, so jedli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'in z radostjo so sedem dni praznovali praznik nekvašenega kruha, kajti Gospod jih je naredil radostne in obrnil srce asirskega kralja k njim, da okrepi njihove roke v delu pri Božji hiši Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Torej po teh stvareh, v kraljevanju perzijskega kralja Artakserksa, je Ezra, sin Serajája, sinú Azarjája, sinú Hilkijája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'sinú Šalúma, sinú Cadóka, sinú Ahitúba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'sinú Amarjája, sinú Azarjája, sinú Merajóta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'sinú Zerahjája, sinú Uzíja, sinú Bukíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'sinú Abišúa, sinú Pinhása, sinú Eleazarja, sinú Arona, vélikega duhovnika;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'ta Ezra odšel gor iz Babilona. Ta je bil vešč pisar v Mojzesovi postavi, ki jo je dal Gospod, Izraelov Bog. In kralj mu je zagotovil vse njegove zahteve, glede na roko Gospoda, njegovega Boga, nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'In tam so šli gor nekateri izmed Izraelovih otrok in izmed duhovnikov, Lévijevcev, pevcev, vratarjev in Netinimcev v Jeruzalem, v sedmem letu kralja Artakserksa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'V petem mesecu je ta prišel v Jeruzalem, kar je bilo v sedmem letu kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Kajti na prvi dan prvega meseca je začel iti gor iz Babilona, in na prvi dan petega meseca je prišel v Jeruzalem, glede na dobro roko njegovega Boga nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Kajti Ezra je pripravil svoje srce, da išče Gospodovo postavo in da jo izpolnjuje in da v Izraelu uči zakone in sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Torej to je kopija pisma, ki ga je kralj Artakserks izročil Ezru, duhovniku, pisarju, celó pisarju besed Gospodovih zapovedi in njegovih zakonov Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '›Artakserks, kralj kraljev, duhovniku Ezru, pisarju postave Boga iz nebes, popoln mir itd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Izdajam odlok, da vsi izmed Izraelovega ljudstva in izmed njegovih duhovnikov in Lévijevcev v mojem območju, ki so voljni po svoji lastni svobodni volji, da gredo gor v Jeruzalem, gredo s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Ker si poslan od kralja in od njegovih sedmih svetovalcev, da poizveš glede Juda in Jeruzalema, glede na postavo svojega Boga, ki je v tvoji roki');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'in da odneseš srebro in zlato, ki so ga kralj in njegovi svetovalci velikodušno darovali Izraelovemu Bogu, katerega prebivališče je v Jeruzalemu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'in vse srebro in zlato, ki ga lahko najdeš po vsej babilonski provinci s prostovoljnimi daritvami ljudstva in duhovnikov, prostovoljno darovanega za hišo njihovega Boga, ki je v Jeruzalemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'da boš s tem denarjem lahko naglo kupil bikce, ovne, jagnjeta, z njihovimi jedilnimi daritvami in njihovimi pitnimi daritvami in jih daroval na oltarju hiše svojega Boga, ki je v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'In karkoli se bo zdelo dobro tebi in tvojim bratom, da storite s preostankom srebra in zlata, to storite po volji svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Tudi posode, ki so ti dane za službo hiše svojega Boga, te izroči pred Bogom Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Karkoli več bo treba za hišo tvojega Boga, kar boš imel priložnost dati, daj to iz kraljeve zakladne hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Jaz, torej jaz, kralj Artakserks, izdajam odlok vsem zakladnikom, ki so onkraj reke, da karkoli bo duhovnik Ezra, pisar postave nebeškega Boga, zahteval od vas, naj bo to naglo storjeno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'do sto talentov srebra in do sto mer pšenice in do sto čebrov vina in do sto kadi olja, soli pa brez predpisa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Karkoli je zapovedano od Boga iz nebes, naj bo to marljivo storjeno za hišo Boga iz nebes, kajti zakaj bi bil bes zoper kraljestvo kralja in njegovih sinov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, '§ Prav tako vam potrjujemo, da glede kateregakoli izmed duhovnikov in Lévijevcev, pevcev, vratarjev, Netinimcev ali služabnikov te Božje hiše, to ne bo zakonito, da bi nanje naložili pristojbino, davek in carino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ti pa Ezra, po modrosti svojega Boga, ki je v tvoji roki, postavi oblastnike in sodnike, ki bodo lahko sodili vse ljudstvo, ki je onkraj reke [Evfrat], vse takšne, ki poznajo zakone tvojega Boga; in učite tiste, ki jih ne poznajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Kdorkoli pa ne bo izpolnjeval postave tvojega Boga in kraljeve postave, naj bo nad njim naglo izvršena sodba, bodisi je to s smrtjo ali izgnanstvom ali zaplembo dobrin ali z ujetništvom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Blagoslovljen bodi Gospod, Bog naših očetov, ki je takšno stvar, kot je ta, položil na kraljevo srce, da olepša Gospodovo hišo, ki je v Jeruzalemu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'in mi razširil usmiljenje pred kraljem in njegovimi svetovalci in pred vsemi mogočnimi kraljevimi princi. In okrepljen sem bil, ko je bila roka Gospoda, mojega Boga, nad menoj in iz Izraela sem zbral skupaj vodilne može, da gredo gor z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Ti so torej vodje njihovih očetov in to je rodovnik tistih, ki so z menoj odšli gor iz Babilona, v kraljevanju kralja Artakserksa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Od Pinhásovih sinov Geršóm. Od Itamárjevih sinov Daniel. Od Davidovih sinov Hatúš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Od Šehanjájevih sinov, od Paróševih sinov Zeharjá, in z njim je bilo po rodovniku preštetih sto petdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Od Pahat Moábovih sinov Eljoenáj, Zerahjájev sin in z njim dvesto moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Od Šehanjájevih sinov Jahaziélov sin in z njim tristo moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Tudi od Adínovih sinov Jonatanov sin Ebed in z njim petdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Od Elámovih sinov Ataljájin sin Ješajá in z njim sedemdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Od Šefatjájevih sinov Mihaelov sin Zebadjá in z njim osemdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Od Joábovih sinov Jehiélov sin Obadjá in z njim dvesto osemnajst moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Od Šelomítovih sinov Josifjájev sin in z njim sto šestdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Od Bebájevih sinov Bebájev sin Zeharjá in z njim osemindvajset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Od Azgádovih sinov Katánov sin Johanán in z njim sto deset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Od zadnjih sinov Adonikáma, katerih imena so ta: Elifélet, Jeiél, Šemajá in z njimi šestdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Tudi od Bigvájevih sinov Utáj in Zabúd in z njima sedemdeset moških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Zbral sem jih skupaj k reki, ki teče proti Ahaváju in tam smo tri dni ostali v šotorih in opazoval sem ljudstvo in duhovnike, pa tam nisem našel nobenega izmed Lévijevih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Potem sem poslal po Eliézerja, po Ariéla, po Šemajája, po Elnatána, po Jaríba, po Elnatána, po Natána, po Zeharjá in po Mešuláma, vodilne može. Tudi po Jojaríba in po Elnatána, razumna moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Poslal sem jih z zapovedjo k Idóju, vodju pri kraju Kasífja in povedal sem jim, kaj naj rečejo Idóju in njegovim bratom Netinimcem na kraju Kasífja, da naj bi k nam privedli služabnike za hišo našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Z dobro roko našega Boga nad nami so nam privedli razumnega moža izmed Mahlíjevih sinov, sinú Lévijevega, sinú Izraelovega in Šerebjá z njegovimi sinovi in njegovimi brati, osemnajst;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'in Hašabjá in z njim Ješajá izmed Meraríjevih sinov, njegove brate in njegove sinove, dvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, '§ Tudi od Netinimcev, ki so jih David in princi določili za službo Lévijevcem, dvesto in dvajset Netinimcev. Vsi izmed njih so bili določeni po imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Potem sem tam, pri reki Ahavá, razglasil post, da bi se lahko užalostili pred našim Bogom, da od njega iščemo pravo pot za sebe in za svoje malčke in za vse svoje imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Kajti sram me je bilo, da od kralja zahtevam četo vojakov in konjenikov, da nam pomagajo zoper sovražnika na poti, ker smo kralju govorili, rekoč: »Roka našega Boga je za dobro nad vsemi tistimi, ki ga iščejo, toda njegova moč in njegov bes sta proti vsem tem, ki ga zapustijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Tako smo se postili in glede tega iskali svojega Boga in on je bil izprošen od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Potem sem ločil dvanajst izmed vodij duhovnikov: Šerebjája, Hašabjája in deset od njihovih bratov z njimi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'in jim odtehtal srebro, zlato in posode, celó daritev hiše našega Boga, ki so jih kralj, njegovi svetovalci, njegovi poveljniki in ves tam prisoten Izrael, darovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'V njihove roke sem celo odtehtal šeststo petdeset talentov srebra in sto talentov srebrnih posod in sto talentov zlata,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'tudi dvajset umivalnikov iz zlata za tisoč darejkov in dve posodi iz finega bakra, dragoceni kakor zlato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Rekel sem jim: »Vi ste sveti Gospodu. Tudi posode so svete in srebro in zlato sta prostovoljno darovana Gospodu, Bogu vaših očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Pazite in varujte jih, dokler jih ne stehtamo pred vodji duhovnikov in Lévijevcev in vodji Izraelovih očetov v Jeruzalemu, v sobah Gospodove hiše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Tako so duhovniki in Lévijevci vzeli težo srebra, zlata in posod, da jih prinesejo v Jeruzalem, v hišo našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Potem smo se na dvanajsti dan prvega meseca odpravili od reke Ahavá, da gremo v Jeruzalem in roka našega Boga je bila nad nami in osvobodil nas je iz roke sovražnika in takih, ki ob poti prežijo v zasedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'In prišli smo v Jeruzalem ter tam ostali tri dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Torej na četrti dan so bile po roki Urijájevega sina Meremóta, duhovnika, srebro, zlato in posode stehtane v hiši našega Boga in z njim je bil Pinhásov sin Eleazar in z njim sta bila Lévijevca Ješúov sin Jozabád in Binújev sin Noádja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'po številu in po teži vsake in vsa teža je bila ob tistem času zapisana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Tudi otroci tistih, ki so bili odvedeni proč, ki so prišli iz ujetništva, so darovali žgalne daritve Izraelovemu Bogu: dvanajst bikcev za ves Izrael, šestindevetdeset ovnov, sedeminsedemdeset jagnjet, dvanajst kozlov za daritev za greh. Vse to je bila žgalna daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Kraljeva naročila so izročili kraljevim poročnikom in voditeljem na tej strani reke in ti so podpirali ljudstvo in Božjo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Torej ko so bile te stvari narejene, so prišli k meni princi, rekoč: »Izraelsko ljudstvo, duhovniki in Lévijevci se [še] niso oddvojili od ljudstva dežel. Počnejo glede na njihove ogabnosti, celó [ogabnosti] Kánaancev, Hetejcev, Perizéjcev, Jebusejcev, Amóncev, Moábcev, Egipčanov in Amoréjcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Kajti vzeli so izmed njihovih hčera zase in za svoje sinove, tako da se je sveto seme pomešalo z ljudstvom teh dežel. Da, roka princev in vladarjev je bila vodilna v tem prekršku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Ko sem slišal to stvar, sem pretrgal svoje ogrinjalo in svoj plašč in si pulil lase svoje glave in iz svoje brade ter se osupel usedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Potem so bili zbrani k meni vsi, ki so trepetali ob besedah Izraelovega Boga zaradi prestopka tistih, ki so bili odvedeni proč; in osupel sem sedel do večerne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ob večerni daritvi pa sem se dvignil od svoje potrtosti in s svojo pretrgano obleko in ogrinjalom padel na svoja kolena in razprostrl svoje roke h Gospodu, svojemu Bogu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'in rekel: »Oh moj Bog, osramočen sem in zardevam, da bi dvignil svoj obraz k tebi, moj Bog. Kajti naše krivičnosti so narasle nad našo glavo in naš prestopek je zrasel do nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Od dni svojih očetov smo bili v velikem prekršku do tega dne in zaradi svojih krivičnosti smo bili mi, naši kralji in naši duhovniki izročeni v roko kraljev dežel, meču, ujetništvu, plenu in zmedenosti obraza, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Sedaj je bila za kratek čas milost pokazana od Gospoda, svojega Boga, da nam pusti ostanek, da pobegne in da nam da klin na njegovem svetem prostoru, da nam naš Bog lahko razsvetli naše oči in nam da majhno poživitev v naše suženjstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Kajti bili smo sužnji, vendar nas Bog v našem suženjstvu ni zapustil, temveč je k nam razširil usmiljenje v očeh perzijskih kraljev, da nam da poživitev, da postavimo hišo našega Boga, da popravimo njena opustošenja in da nam da zid v Judu in v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'In sedaj, oh naš Bog, kaj bomo rekli po tem? Kajti zapustili smo tvoje zapovedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'ki si nam jih zapovedal po svojih služabnikih prerokih, rekoč: ›Dežela, v katero greste, da jo posedete, je nečista dežela z nečistostjo ljudstva dežel, z njihovimi ogabnostmi, ki so jih napolnili od enega konca do drugega s svojo nečistostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Zdaj torej ne dajajte svojih hčera njihovim sinovom niti ne jemljite njihovih hčera [za] svoje sinove niti ne iščite njihovega miru ali njihovega premoženja na veke, da boste lahko močni in jedli dobro od dežele in jo zapustili v dediščino svojim otrokom na veke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Po vsem tem, kar je prišlo nad nas zaradi naših zlih dejanj in zaradi našega velikega prekrška, glede na to, da nas je naš Bog manj kaznoval, kakor zaslužijo naše krivičnosti in nam dal takšno osvoboditev, kakor je ta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'ali naj bi ponovno prelomili tvoje zapovedi in se pridružili v sorodstvo z ljudstvom teh ogabnosti? Mar ne boš jezen na nas, dokler nas ne použiješ, tako da tukaj ne bi bilo ne ostanka niti pobeglih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Oh Gospod, Izraelov Bog, ti si pravičen, kajti mi ostajamo, čeprav pobegli, kakor je to ta dan. Glej, mi smo pred teboj v svojih prestopkih, kajti zaradi tega ne moremo stati pred teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Torej ko je Ezra molil in ko je priznaval, jokal in se metal dol pred Božjo hišo, se je tam k njemu iz Izraela zbrala zelo velika skupnost mož, žena in otrok, kajti ljudstvo je zelo hudo jokalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Jehiélov sin Šehanjája, eden izmed Elámovih sinov, je odgovoril in Ezru rekel: »Pregrešili smo se zoper svojega Boga in si jemali tuje žene izmed ljudstva dežele, vendar je sedaj v Izraelu upanje glede te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Sedaj torej sklenimo zavezo s svojim Bogom, da odslovimo vse žene in tiste, ki so se rodili od njih, glede na nasvet mojega gospoda in tistih, ki trepetajo ob zapovedi našega Boga. In to naj bo storjeno glede na postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Vstani, kajti ta zadeva pripada tebi. Tudi mi bomo s teboj. Bodi odločnega poguma in to naredi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Potem je Ezra vstal in pripravil vodilne duhovnike, Lévijevce in ves Izrael, da prisežejo, da bodo storili glede na to besedo. In so prisegli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Potem je Ezra vstal izpred Božje hiše in odšel v sobo Eljašíbovega sina Johanána. Ko je prišel tja, ni jedel kruha niti pil vode, kajti žaloval je zaradi prestopka tistih, ki so bili odvedeni proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Naredili so razglas po vsej Judeji in Jeruzalemu, vsem otrokom iz ujetništva, da naj se skupaj zberejo v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'In da kdorkoli ne bo hotel priti v treh dneh, glede na nasvet princev in starešin, bo vse njegovo imetje zaseženo in on sam oddvojen od skupnosti tistih, ki so bili odvedeni proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Potem so se v treh dneh vsi možje iz Juda in Benjamina zbrali skupaj v Jeruzalemu. To je bil deveti mesec, na dvanajsti dan meseca, in vse ljudstvo je sedelo na ulici Božje hiše in trepetalo zaradi te zadeve in zaradi velikega dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Duhovnik Ezra je vstal in jim rekel: »Pregrešili ste se in si vzeli tuje ženske, da povečate Izraelov prekršek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Zdaj torej naredite priznanje Gospodu, Bogu svojih očetov in storite njegovo voljo in se ločite od ljudstva dežele in od tujih žena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Potem je vsa skupnost odgovorila in z močnim glasom rekla: »Kakor si rekel, tako moramo storiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Toda ljudstva je mnogo in to je čas obilnega dežja in mi nismo zmožni stati zunaj niti to ni delo enega dne ali dveh, kajti mnogo nas je, ki smo se pregrešili v tej stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Naj sedaj naši voditelji vse skupnosti vstanejo in naj vsi, ki so si v naših mestih vzeli tuje žene, pridejo ob določenih časih in z njimi starešine iz vsakega mesta in njihovi sodniki, dokler kruti bes našega Boga zaradi te zadeve ne bo odvrnjen od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Samo Asaélov sin Jonatan in Tikvájev sin Jahzejá sta bila zaposlena okoli te zadeve. Mešulám in Lévijevec Šabetáj pa sta jima pomagala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Otroci ujetništva so storili tako. Duhovnik Ezra z nekaterimi vodilnimi očeti, po hiši njihovih očetov in vsi izmed njih po njihovih imenih, so se oddvojili in se usedli na prvi dan desetega meseca, da preiščejo zadevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'In z vsemi možmi, ki so si vzeli tuje žene, so zaključili do prvega dne prvega meseca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Med sinovi duhovnikov so bili najdeni, da so si vzeli tuje žene, namreč od Ješúvovih sinov Jocadákov sin in njegovi bratje Maasejá, Eliézer, Jaríb in Gedaljá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Dali so svoje roke, da bodo odslovili svoje žene in ker so bili krivi, so darovali ovna od tropa za svoj prekršek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Izmed Imêrjevih sinov Hananí in Zebadjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Izmed Harímovih sinov Maasejá, Elija, Šemajá, Jehiél in Uzíjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Izmed Pašhúrjevih sinov Eljoenáj, Maasejá, Jišmaél, Netanél, Jozabád in Elasá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Tudi izmed Lévijevcev: Jozabád, Šimí, Kelajá (isti je Kelitá), Petahjá, Juda in Eliézer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Tudi izmed pevcev Eljašíb in izmed vratarjev Šalúm, Telem in Urí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Poleg tega od Izraela izmed Paróševih sinov Ramjá, Malkijá, Mijamín, Eleazar, Malkijá in Benajá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Izmed Elámovih sinov Matanjá, Zeharjá, Jehiél, Abdí, Jeremót in Elijá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Izmed Zatújevih sinov Eljoenáj, Eljašíb, Matanjá, Jeremót, Zabád in Azizá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Tudi izmed Bebájevih sinov Johanán, Hananjá, Zabáj in Atláj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Izmed Baníjevih sinov Mešulám, Malúh, Adajá, Jašúb, Šeál in Ramót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Izmed Pahat Moábovih sinov Adná, Kelál, Benajá, Maasejá, Matanjá, Becalél, Binúj in Manáse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'In izmed Harímovih sinov Eliézer, Jišijá, Malkijá, Šemajá, Šimón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malúh in Šemarjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Izmed Hašúmovih sinov Matenáj, Matatá, Zabád, Elifélet, Jeremáj, Manáse in Šimí.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Izmed Baníjevih sinov Maadáj, Amrám, Uél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benajá, Bedjá, Keluhí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanjá, Meremót, Eljašíb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanjá, Matenáj, Jaasáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Baní, Binúj, Šimí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Šelemjá, Natána, Adajá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Mahnadbáj, Šašáj, Šaráj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarél, Šelemjá, Šemarjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Šalúm, Amarjá in Jožef.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Izmed Nebójevih sinov Jeiél, Matitjá, Zabád, Zebiná, Jadáj, Joél in Benajá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Vsi ti so si vzeli tuje žene in nekateri izmed njih so imeli žene, s katerimi so imeli otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Besede Nehemija, Hahaljájevega sina. Pripetilo se je v mesecu kislévu, v dvajsetem letu, medtem ko sem bil v palači Suze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'da je prišel Hananí, eden izmed mojih bratov, on in nekateri možje iz Juda. Vprašal sem jih glede Judov, ki so pobegnili, ki so preostali od ujetništva in glede Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Rekli so mi: »Ostanek, ki je ostal od ujetništva, tam v provinci, je v veliki stiski in graji. Prav tako je porušeno jeruzalemsko obzidje in njegova velika vrata so požgana z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'In pripetilo se je, ko sem slišal te besede, da sem se usedel, jokal in žaloval določene dni in se postil ter molil pred Bogom nebes');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'in rekel: »Rotim te, oh Gospod Bog nebes, veliki in strašni Bog, ki ohranja zavezo in usmiljenje za tiste, ki ga ljubijo in obeležujejo njegove zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Naj bo tvoje uho sedaj pozorno in tvoje oči odprte, da boš lahko slišal molitev svojega služabnika, ki jo sedaj molim pred teboj podnevi in ponoči zaradi tvojih služabnikov, Izraelovih otrok in priznavam grehe Izraelovih otrok, ki smo jih zagrešili zoper tebe. Tako jaz, kakor hiša mojega očeta smo grešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Zoper tebe smo postopali zelo izprijeno in se nismo držali zapovedi niti zakonov niti sodb, ki si jih zapovedal svojemu služabniku Mojzesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Spomni se, rotim te, besede, ki jo zapoveduješ svojemu služabniku Mojzesu, rekoč: › Če grešite, vas bom razkropil na tuje, med narode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Toda če se obrnete k meni in se držite mojih zapovedi in jih izpolnjujete, čeprav bi bili izmed vas vrženi v najbolj oddaljen del neba, jih bom vendar zbral od tam in jih privedel na kraj, ki sem ga izbral, da tam postavim svoje ime.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Torej ti so tvoji služabniki in tvoje ljudstvo, ki si jih odkupil s svojo veliko oblastjo in s svojo močno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Oh Gospod, rotim te, naj bo sedaj tvoje uho pozorno k molitvi tvojega služabnika in k molitvi tvojih služabnikov, ki se želijo bati tvojega imena. Prosim te, naredi svojega služabnika ta dan uspešnega in zagotovi mu usmiljenje pred očmi tega človeka.« Kajti bil sem kraljevi dvorni točaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Pripetilo se je v mesecu nisánu, v dvanajstem letu kralja Artakserksa, da je bilo pred njim vino. Vzel sem vino in ga izročil kralju. Torej poprej v njegovi prisotnosti nisem bil žalosten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Zato mi je kralj rekel: »Zakaj je tvoje obličje žalostno, ker vidim, da nisi bolan? To ni nič drugega kakor bridkost srca.« Potem sem bil zelo boleče prestrašen');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'in rekel kralju: »Naj kralj živi na veke. Zakaj naj bi moje obličje ne bilo žalostno, ko [pa] mesto, kraj mavzolejev mojih očetov, leži opustošeno in so njegova velika vrata použita z ognjem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Potem mi je kralj odgovoril: »Za kaj delaš zahtevo?« Tako sem molil k Bogu nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Kralju sem rekel: »Če kralju ugaja in je tvoj služabnik našel naklonjenost v tvojem pogledu, da bi me hotel poslati v Judejo, v mesto mavzolejev mojih očetov, da ga lahko zgradim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Kralj mi je rekel (tudi kraljica je sedela ob njem): »Kako dolgo bo trajalo tvoje potovanje? In kdaj se boš vrnil?« Tako je kralju ugajalo, da me pošlje, in določil sem mu čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Poleg tega sem kralju rekel: »Če to ugaja kralju, naj mi bodo dana pisma, za voditelje onkraj reke, da me lahko pošljejo preko, dokler ne pridem v Judejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'in pismo Asáfu, čuvaju kraljevega gozda, da mi bo lahko dal les, da naredim bruna za velika vrata palače, ki so spadala k hiši in za mestno obzidje in za hišo, v katero bom vstopil.« In kralj mi je zagotovil, glede na dobro roko mojega Boga nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Potem sem prišel k voditeljem preko reke in jim dal kraljeva pisma. Torej kralj je z menoj poslal vojne poveljnike in konjenike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Ko sta Sanbalát Horónčan in služabnik Tobija, Amónec, slišala o tem, ju je to silno užalostilo, da je tja prišel človek, da išče blaginjo Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Tako sem prišel v Jeruzalem in bil tam tri dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Vstal sem ponoči, jaz in nekaj malega mož z menoj. Niti nisem nobenemu možu povedal, kaj je Bog položil na moje srce, da storim pri Jeruzalemu. Niti ni bila z menoj nobena žival, razen živali, na kateri sem jahal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Ponoči sem odšel ven pri Dolinskih velikih vratih, celo pred zmajevim vodnjakom in do gnojne odprtine in ogledal sem si jeruzalemske zidove, ki so bili porušeni in njegova velika vrata, ki so bila použita z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Potem sem odšel naprej do velikih studenčnih vrat in do kraljevega ribnika, toda tam ni bilo prostora za žival, ki je bila pod menoj, da gre mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Potem sem ponoči odšel gor, poleg potoka in gledal obzidje in se obrnil nazaj in vstopil pri velikih dolinskih vratih in tako sem se vrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Vladarji niso vedeli, kam sem odšel ali kaj sem storil, niti do tega trenutka tega še nisem povedal Judom, niti duhovnikom, niti plemičem, niti vladarjem, niti preostalim, ki so opravljali delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Potem sem jim rekel: »Vi vidite stisko, v kateri smo, kako Jeruzalem leži opustošen in so njegova velika vrata požgana z ognjem. Pridite in gradimo jeruzalemsko obzidje, da ne bomo več v grajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Potem sem jim povedal o roki svojega Boga, ki je bila dobra nad menoj, kot tudi kraljeve besede, ki mi jih je govoril. Rekli so: »Vzdignimo se in gradimo.« Tako so okrepili svoje roke za to dobro delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Toda ko so Sanbalát Horónčan in služabnik Tobija, Amónec in Arabec Gešem to slišali, so se smejali do norčevanja, nas prezirali in rekli: »Kaj je ta stvar, ki jo počnete. Ali se hočete upreti zoper kralja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Potem sem jim odgovoril in jim rekel: »Bog nebes, on nas bo naredil uspešne, zato bomo mi, njegovi služabniki, vstali in gradili. Toda vi nimate deleža niti pravice niti spomina v Jeruzalemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Potem je vstal Eljašíb, véliki duhovnik, s svojimi brati duhovniki in zgradili so Ovčja velika vrata. Posvetili so jih in vstavili vrata, celo do stolpa Mea so to posvetili, do Hananélovega stolpa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Poleg njega so gradili možje iz Jerihe. Poleg njih je gradil Imríjev sin Zahúr.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Toda Ribja velika vrata so gradili Senaájevi sinovi, ki so tudi položili njena bruna in postavili njena vrata, njene ključavnice in njene zapahe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Poleg njih je popravljal Meremót, Urijájev sin, Kocov sin. Poleg njih je popravljal Mešulám, Berehjájev sin, Mešezabélov sin. In poleg njih Baanájev sin Cadók.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Poleg njih so popravljali Tekójčani, toda njihovi plemiči svojih vratov niso pristavili k delu njihovega Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Poleg tega sta Stara velika vrata popravljala Jojadá, sin Paséaha in Mešulám, Besodjájev sin. Položila sta njena bruna in postavila njena vrata in njene ključavnice in njene zapahe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Poleg njiju so popravljali Gibeónec Melatjá in Meronočán Jadón, možje iz Gibeóna in iz Micpe, do prestola voditelja na tej strani reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Poleg njega je popravljal Uziél, Harhajájev sin izmed zlatarjev. Poleg njega je popravljal tudi Hananjá, sin enega izmed lekarnarjev in Jeruzalem so utrdili do širokega zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Poleg njih je popravljal Hurov sin Refajá, vladar polovice Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Poleg njega je popravljal Harumáfov sin Jedajája, celo nasproti svoje hiše. Poleg njega je popravljal Hašabnejájev sin Hatúš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Harímov sin Malkijája in Pahat Moábov sin Hašúb sta popravljala drug kos in stolp talilne peči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Poleg njega je popravljal Lohéšev sin Šalúm, vladar polovice Jeruzalema, on in njegove hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dolinska velika vrata so popravljali Hanún in prebivalci Zanóaha. Zgradili so jih in postavili njena vrata, njene ključavnice in njene zapahe in tisoč komolcev na obzidju do Gnojnih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Toda Gnojna velika vrata je popravljal Rehábov sin Malkijáj, vladar dela Bet Kerema. Zgradil jih je, postavil njena vrata, njene ključavnice in njene zapahe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Toda Studenčna velika vrata je popravljal Kolhozéjev sin Šalún, vladar dela Micpe. On je to zgradil, pokril in postavil njena vrata, njene ključavnice in njene zapahe in zid ribnika Síloa, poleg kraljevega vrta in do stopnic, ki gredo dol od Davidovega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za njim je popravljal Azbúkov sin Nehemija, vladar polovice Bet Cura, do kraja nasproti Davidovih mavzolejev in do ribnika, ki je bil narejen in do hiše mogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za njim so popravljali Lévijevci, Baníjev sin Rehúm. Poleg njega je na svojem delu popravljal Hašabjá, vladar polovice Keíle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za njim so popravljali njihovi bratje, Henadádov sin Bavaj, vladar polovice Keíle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Poleg njega je popravljal Ješúajev sin Ecer, vladar Micpe, drug del nasproti vzpona do orožarne, ob [delu, kjer se] zid obrne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za njim je Zabájev sin Baruh vneto popravljal drugi kos, od [dela, kjer se] zid obrne, do vrat hiše vélikega duhovnika Eljašíba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za njim je drug del popravljal Meremót, Urijájev sin, Kocov sin, od vrat Eljašíbove hiše, celo do konca Eljašíbove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Za njim so popravljali duhovniki, možje ravnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za njim sta nasproti njuni hiši popravljala Benjamin in Hašúb. Za njima je ob njegovi hiši popravljal Azarjá, Maasejájev sin, sin Ananjája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za njim je popravljal Henadádov sin Binúj, drug del od Azarjájeve hiše do [dela, kjer se] zid obrne, celo do vogala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Uzájev sin Palál nasproti [dela, kjer se] zid obrne in stolpa, ki se nahaja zunaj kraljeve velike hiše, ki je bila ob dvorišču ječe. Za njim Paróšev sin Pedajá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Poleg tega so Netinimci prebivali v Ofelu, do kraja nasproti Vodnih velikih vrat proti vzhodu in stolpa, ki se nahaja zunaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za njimi so Tekójčani popravljali drug del, nasproti velikemu stolpu, ki leži zunaj, celo do ofelskega obzidja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od zgoraj, iznad Konjskih velikih vrat so popravljali duhovniki, vsak nasproti svoji hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za njimi je popravljal Imêrjev sin Cadók nasproti svoji hiši. Za njim je popravljal tudi Šehanjájev sin Šemajá, čuvaj Vzhodnih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za njim je drug del popravljal Šelemjájev sin Hananjá in Hanún, šesti Caláfov sin. Za njim je popravljal Berehjájev sin Mešulám nasproti svoje sobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za njim je popravljal zlatarjev sin Malkijá do kraja Netinimcev in trgovcev, nasproti velikih vrat Mifkada in do vzpona vogala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Med vzponom vogala, do Ovčjih velikih vrat, so popravljali zlatarji in trgovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Toda pripetilo se je, da ko je Sanbalát slišal, da smo gradili zid, da je bil besen in polastilo se ga je veliko ogorčenje in zasmehoval je Jude.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, '§ Pred svojimi brati in vojsko Samarije je spregovoril ter rekel: »Kaj počno ti slabotni Judje? Mar se bodo utrdili?? Mar bodo žrtvovali? Mar bodo končali v [enem] dnevu? Mar bodo oživili kamne iz kupov smeti, ki so požgane?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Torej Amónec Tobija je bil ob njem in rekel: »Celo to, kar so zgradili, če gre gor lisjak, bo torej porušil njihov kamniti zid.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Prisluhni, oh naš Bog, kajti mi smo prezirani. Obrni njihovo grajo na njihovo lastno glavo in jih daj za plen v deželi ujetništva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'in ne pokrij njihove krivičnosti in naj njihov greh ne bo izbrisan izpred tebe, kajti do jeze so te izzivali pred graditelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Tako smo gradili obzidje in vse obzidje je bilo združeno skupaj do njegove polovice, kajti ljudstvo je imelo um, da dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Toda pripetilo se je, da ko so Sanbalát, Tobija, Arabci, Amónci in Ašdódčani slišali, da so bili zidovi Jeruzalema postavljeni in da so se vrzeli začele zapolnjevati, potem so bili zelo besni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'in vsi skupaj so skovali zaroto, da pridejo in se borijo zoper Jeruzalem in da to ovirajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Kljub temu smo naredili svojo molitev k svojemu Bogu in podnevi ter ponoči zaradi njih postavili stražo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Juda je rekel: »Moč nosilcev bremen je oslabela in tam je veliko smeti, tako, da nismo zmožni graditi obzidja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Naši nasprotniki pa so rekli: »Ne bodo vedeli niti videli, dokler ne pridemo v sredo mednje in jih pobijemo in povzročimo, da delo preneha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Pripetilo pa se je, ko so prišli Judje, ki so prebivali poleg njih, da so nam desetkrat rekli: »Iz vseh krajev, od koder se boste vrnili k nam, bodo oni nad vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Zato sem postavil na nižjih mestih za obzidjem in na višjih mestih, sem celo postavil ljudstvo po njihovih družinah, z njihovimi meči, njihovimi sulicami in njihovimi loki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Pogledal sem, vstal in rekel plemičem, vladarjem in ostalemu ljudstvu: »Ne bojte se jih. Spominjajte se Gospoda, ki je velik in strašen in borite se za svoje brate, svoje sinove in svoje hčere, svoje žene in svoje hiše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Pripetilo se je, ko so naši sovražniki slišali, da nam je bilo to znano in je Bog njihovo namero privedel v nič, da smo se vsi izmed nas vrnili k obzidju, vsak k svojemu delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Pripetilo se je od tega časa naprej, da je polovica mojih služabnikov delala na delu, druga polovica pa je držala sulice, ščite, loke in brezrokavne verižne srajce in vladarji so bili zadaj za vso Judovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Tisti, ki so gradili na obzidju in tisti, ki so nosili bremena, s tistimi, ki so prenašali, vsak je z eno roko opravljal delo, z drugo roko pa je držal orožje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Kajti graditelji so gradili tako, da je imel vsakdo svoj meč opasan ob svoji strani. Tisti, ki je trobil na šofar, pa je bil poleg mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Rekel sem plemičem, vladarjem in ostalemu ljudstvu: »Delo je veliko in obsežno, mi pa smo na obzidju ločeni, eden daleč od drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Na katerem mestu torej zaslišite glas šofarja, krenite tja k nam. Naš Bog se bo boril za nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Tako smo se trudili na delu. Polovica izmed njih je sulice držala od jutranjega vzhoda do pojavitve zvezd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Prav tako sem ljudstvu istočasno rekel: »Naj vsak s svojim služabnikom prenočuje znotraj Jeruzalema, da nam bodo ponoči lahko straža in se trudili podnevi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, '§ Tako niti jaz, niti moji bratje, niti moji služabniki, niti ljudje na straži, ki so mi sledili, nihče izmed nas ni odložil svojih oblačil, razen, da jih je vsak slekel za pranje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Tam je bilo veliko vpitje ljudstva in njihovih žena zoper njihove brate Jude.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Kajti tam so bili, ki so rekli: »Nas, naših sinov in naših hčera je mnogo. Zato zanje zbiramo žito, da bomo lahko jedli in živeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Tam so bili tudi nekateri, ki so rekli: »Zaradi pomanjkanja smo zastavili svoje dežele, vinograde in hiše, da bi lahko kupili žito.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Tam so bili tudi, ki so rekli: »Izposodili smo si denar za kraljevi davek in to [za ceno] naših dežel in vinogradov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Vendar je sedaj naše meso kakor meso naših bratov, naši otroci kakor njihovi otroci. Glej, svoje sinove prinašamo v sužnost in svoje hčere, da bodo služabnice in nekatere izmed naših hčera so že privedene v sužnost. Niti to ni v naši moči, da jih odkupimo, kajti drugi možje imajo naše dežele in vinograde.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Bil sem zelo jezen, ko sem slišal njihovo vpitje in te besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Potem sem se posvetoval s seboj in oštel plemiče in vladarje ter jim rekel: »Vi terjate obresti, vsakdo od svojega brata.« In zoper njih sem postavil velik zbor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Rekel sem jim: »Po svoji zmožnosti smo odkupili svoje brate Jude, ki so bili prodani poganom. Vi pa boste celo prodajali svoje brate? Ali naj bi bili oni prodani nam?« Potem so ohranili svoj mir in nič niso našli, da bi odgovorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Prav tako sem rekel: »To ni dobro, kar delate. Ali ne bi morali hoditi v strahu našega Boga zaradi graje poganov, naših sovražnikov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Tudi jaz in moji bratje in moji služabniki bi lahko od njih terjali denar in žito. Prosim vas, prenehajmo s tem oderuštvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Povrnite jim, prosim vas, celo ta dan, njihove dežele, njihove vinograde, njihove oljčne nasade in njihove hiše, tudi stoti del denarja in od žita, vina in olja, ki ste jih vzeli od njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Potem so rekli: »Povrnili jim bomo in ničesar ne bomo zahtevali od njih. Storili bomo tako, kakor praviš.« Potem sem poklical duhovnike in od njih vzel prisego, da bi storili glede na to obljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Prav tako sem stresel svoje naročje in rekel: »Tako naj Bog iztrese vsakega človeka iz njegove hiše in od njegovega truda, ki ne izpolni te obljube, celo tako bo iztresen in izpraznjen.« In vsa skupnost je rekla: »Amen« in hvalili so Gospoda. In ljudstvo je storilo glede na to obljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Poleg tega od časa, ko sem bil določen, da bi bil njihov voditelj v Judovi deželi, od dvajsetega leta, celo do dvaintridesetega leta kralja Artakserksa, to je dvanajst let, jaz in moji bratje nismo jedli kruha od voditelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Toda prejšnji voditelji, ki so bili pred menoj, so bili v breme ljudstvu in so od njih jemali kruh in vino, poleg štiridesetih šeklov srebra. Da, celo njihovi služabniki so vladali nad ljudstvom. Toda zaradi Božjega strahu jaz nisem tako storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Da, prav tako sem nadaljeval pri delu tega obzidja niti nismo kupili nobene zemlje in vsi moji služabniki so bili zbrani tja k delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Poleg tega jih je bilo pri moji mizi sto petdeset izmed Judov in vladarjev, poleg tistih, ki so prišli k nam izmed poganov, ki so okoli nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Torej tega, kar je bilo dnevno pripravljeno zame, je bilo: en vol in šest izbranih ovc. Tudi perjad je bila pripravljena zame in enkrat na deset dni izbor vseh vrst vina. Vendar za vse to nisem zahteval kruha od voditelja, ker je bilo suženjstvo težko nad tem ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Misli name, moj Bog, za dobro, glede na vse, kar sem storil za to ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Pripetilo se je torej, ko so Sanbalát, Tobija, Arabec Gešem in ostali izmed naših sovražnikov slišali, da sem zgradil obzidje in da v njem ni ostalo nobene vrzeli (čeprav ob tistem času nisem postavil duri na velika vrata)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'da sta Sanbalát in Gešem poslala k meni, rekoč: »Pridi, skupaj se srečajmo v eni izmed vasi, na ravnini Onó.« Toda mislila sta mi storiti vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'K njima sem poslal poslance, rekoč: »Jaz opravljam veliko delo, tako da ne morem priti dol. Zakaj bi delo prenehalo, medtem ko ga zapustim in pridem dol k vama?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Vendar sta štirikrat poslala k meni na ta način, jaz pa sem jima odgovoril na isti način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Potem je Sanbalát petič k meni poslal svojega služabnika na podoben način, z odprtim pismom v svoji roki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'v katerem je bilo zapisano: »Med pogani se govori in Gašmu pravi to, da se ti in Judje mislite upreti, kajti zaradi tega razloga gradiš obzidje, da bi lahko postal njihov kralj, glede na te besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Določil si tudi preroke, da o tebi oznanjajo v Jeruzalemu, rekoč: › Tam je kralj v Judu.‹ In sedaj bo to sporočeno kralju, glede teh besed. Pridite torej sedaj in skupaj sprejmimo nasvet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Potem sem poslal k njemu, rekoč: »Tukaj se niso storile nobene takšne stvari, kot ti praviš, temveč si jih hlinil iz svojega lastnega srca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Kajti oni vsi so nas prestrašili, rekoč: »Njihove roke bodo oslabele od dela, da to ne bo končano.« Sedaj torej, oh Bog, okrepi moje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Zatem sem prišel v hišo Šemajája, sinú Delajája, sinú Mehetabéla, ki je bil zaprt. Rekel je: »Skupaj se srečajva v hiši Boga, znotraj templja in zapriva vrata templja, kajti prišli bodo, da te ubijejo. Da, ponoči bodo prišli, da te ubijejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Rekel sem: »Ali naj bi takšen človek, kakor sem jaz, bežal? In kdo je tam, ki bi kakor sem jaz, šel v tempelj, da reši svoje življenje? Ne bom šel noter.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Glej, zaznal sem, da ga ni poslal Bog, temveč, da je to prerokbo proglasil zoper mene, kajti najela sta ga Tobija in Sanbalát.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Zato je bil najet, da bi bil jaz prestrašen in tako storil in grešil in da bi lahko imela stvar za hudobno poročilo, da bi me lahko grajala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Moj Bog, misli na Tobija in Sanbaláta glede na ta njuna dela in na prerokinjo Noádjo in ostale preroke, ki so me hoteli postaviti v strah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Tako je bilo obzidje končano petindvajseti dan meseca elúla, v dvainpetdesetih dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Pripetilo se je, da ko so vsi naši sovražniki slišali o tem in so vsi pogani, ki so bili okoli nas, videli te stvari, so bili zelo potrti v svojih lastnih očeh, kajti zaznali so, da je bilo to delo izvršeno od našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Poleg tega so v tistih dneh Judovi plemiči poslali mnogo pisem Tobiju in pisma od Tobija so prihajala k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Kajti v Judu so bili mnogi, ki so mu prisegli, ker je bil zet Aráhovega sina Šehanjája in njegov sin Johanán je vzel hčer Berehjájevega sina Mešuláma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Pred menoj so poročali tudi njegova dobra dejanja in mu izrekli moje besede. In Tobija je pošiljal pisma, da me postavi v strah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Pripetilo se je torej, ko je bilo obzidje zgrajeno in sem postavil vrata in so bili določeni vratarji, pevci in Lévijevci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'da sem dal svojemu bratu Hananíju in Hananjáju, vladarju palače, zadolžitev nad Jeruzalemom, kajti ta je bil zvest mož in bolj kot mnogi se je bal Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Rekel sem jima: »Naj velika vrata Jeruzalema ne bodo odprta, dokler ne bo sonce vroče. Medtem ko stojijo poleg, naj vrata zaprejo in jih zapahnejo. Določite straže izmed prebivalcev Jeruzalema, vsakogar na svojo stražo in vsakdo naj bo nasproti svoji hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Torej mesto je bilo prostrano in veliko. Toda ljudstva v njem je bilo malo in hiše niso bile zgrajene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Moj Bog je na moje srce položil, da zberem skupaj plemiče, vladarje in ljudstvo, da bi bili lahko prešteti po rodovniku. Našel sem seznam rodovnika izmed tistih, ki so prišli najprej gor in v njem našel zapisano:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, '›To so otroci province, ki je šla gor iz ujetništva, od tistih, ki so bili odvedeni, ki jih je odvedel babilonski kralj Nebukadnezar in so ponovno prišli v Jeruzalem in v Judejo, vsak v svoje mesto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'ki so prišli z Zerubabélom, Ješúom, Nehemijem, Azarjájem, Raamjájem, Nahamánijem, Mordohajem, Bilšánom, Mispéretom, Bigvájem, Nehumom in Baanájem. Število, pravim, izmed mož Izraelovega ljudstva je bilo tole:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paróševih otrok dva tisoč sto dvainsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Šefatjájevih otrok tristo dvainsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Aráhovih otrok šeststo dvainpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahat Moábovih otrok, od otrok Ješúa in Joába, dva tisoč osemsto in osemnajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elámovih otrok tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Zatújevih otrok osemsto petinštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Zakájevih otrok sedemsto šestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binújevih otrok šeststo oseminštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebájevih otrok šeststo osemindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Azgádovih otrok dva tisoč tristo dvaindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikámovih otrok šeststo sedeminšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvájevih otrok dva tisoč sedeminšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adínovih otrok šeststo petinpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Atêrjevih otrok, od Ezekíja, osemindevetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hašúmovih otrok tristo osemindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Becájevih otrok tristo štiriindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Harífovih otrok sto dvanajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeónovih otrok petindevetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Mož iz Betlehema in Netófe sto oseminosemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Mož iz Anatóta sto osemindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Mož iz Bet Azmáveta dvainštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Mož iz Kirját Jearíma, Kefíre in Beeróta sedemsto triinštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Mož iz Rame in Gebe šeststo enaindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mož iz Mihmása sto dvaindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Mož iz Betela in Aja sto triindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Mož iz drugega Nebója dvainpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Otrok iz drugega Eláma tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harímovih otrok tristo dvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jerihovih otrok tristo petinštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Otrok iz Loda, Hadída in Onója sedemsto enaindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Otrok iz Senaája tri tisoč devetsto trideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Duhovniki: Jedajájevih otrok iz Ješúove hiše devetsto triinsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Imêrjevih otrok tisoč dvainpetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pašhúrjevih otrok tisoč dvesto sedeminštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harímovih otrok tisoč sedemnajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Lévijevci: Ješúovih otrok, od Kadmiéla in Hodavjájevih otrok štiriinsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Pevci: Asáfovih otrok sto oseminštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vratarji: Šalúmovih otrok, Atêrjevih otrok, Talmónovih otrok, Akúbovih otrok, Hatitájevih otrok in Šobájevih otrok sto osemintrideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinimci: Cihájevi otroci, Hasufájevi otroci, Tabaótovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Kerósovi otroci, Siájevi otroci, Padónovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebanájevi otroci, Hagabájevi otroci, Salmájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hanánovi otroci, Gidélovi otroci, Gaharjevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reajájevi otroci, Recínovi otroci, Nekodájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gazámovi otroci, Uzájevi otroci, Paséahovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besájevi otroci, Meunimovi otroci, Nefiséjevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbúkovi otroci, Hakufájevi otroci, Harhúrjevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Baclitovi otroci, Mehidájevi otroci, Haršájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkósovi otroci, Siserájevi otroci, Temahovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Necíahovi otroci in Hatifájevi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Otroci Salomonovih služabnikov: Sotájevi otroci, Soféretovi otroci, Peridájevi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaalájevi otroci, Darkónovi otroci, Gidélovi otroci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Šefatjájevi otroci, Hatílovi otroci, Pohêret Cebájimovi otroci in Amónovi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Vseh Netinimcev in otrok Salomonovih služabnikov, je bilo tristo dvaindevetdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'In ti so bili tisti, ki so tudi odšli gor iz Tel Melaha, Tel Hareše, Kerúba, Adóna in Imêrja. Toda niso mogli pokazati hiše svojega očeta niti svojega semena, če so bili iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delajájevih otrok, Tobijevih otrok, Nekodájevih otrok šeststo dvainštirideset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Izmed duhovnikov: Habajájevi otroci, Kocovi otroci in otroci Barzilája, ki je vzel eno izmed hčera Gileádca Barzilája za ženo in je bil imenovan po njihovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ti so iskali svoj seznam med tistimi, ki so bili prešteti po rodovniku, toda ta ni bil najden. Zato so bili kakor onesnaženi, odstranjeni od duhovništva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, '§ Tirsata jim je rekel, da naj ne jedo od najsvetejših stvari, dokler tam ne vstane duhovnik z urimom in tumimom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Celotne skupnosti skupaj je bilo dvainštirideset tisoč tristo šestdeset,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'poleg njihovih slug in njihovih dekel, od katerih jih je bilo tam sedem tisoč tristo sedemintrideset. Imeli so dvesto petinštirideset pevcev in pevk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Njihovih konj sedemsto šestintrideset, njihovih mul dvesto petinštirideset,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'njihovih kamel štiristo petintrideset in šest tisoč sedemsto dvajset oslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Nekateri izmed vodij očetov so darovali k delu. Tirsata je dal v zaklad tisoč darejkov zlata, petdeset umivalnikov in petsto trideset duhovniških oblačil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Nekateri izmed vodij očetov so dali v zaklad za delo dvajset tisoč darejkov zlata in dva tisoč dvesto funtov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Tega, kar je dalo ostalo ljudstvo, je bilo dvajset tisoč darejkov zlata, dva tisoč funtov srebra in sedeminšestdeset duhovniških oblačil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Tako so duhovniki, Lévijevci, vratarji, pevci, nekateri izmed ljudstva, Netinimci in ves Izrael prebivali v svojih mestih. Ko je prišel sedmi mesec, so bili Izraelovi otroci v svojih mestih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Vse ljudstvo se je zbralo skupaj kakor en mož na ulici, ki je bila pred vodnimi velikimi vrati in spregovorili so pisarju Ezru, da prinese knjigo Mojzesove postave, ki jo je Gospod zapovedal Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Duhovnik Ezra je na prvi dan sedmega meseca postavo prinesel pred skupnost tako mož kakor žena in vseh tistih, ki so lahko slišali z razumevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Bral je tam pred ulico, ki je bila pred vodnimi velikimi vrati od jutra do sredine dneva, pred možmi in ženami in tistimi, ki so lahko razumeli. Ušesa vsega ljudstva so bila pozorna na knjigo postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Pisar Ezra je stal na leseni prižnici, ki so jo naredili za ta namen. Poleg njega so na njegovi desni roki stali: Matitjá, Šemaá, Anajá, Urijá, Hilkijá in Maasejá, na njegovi levi roki pa: Pedajá, Mišaél, Malkijá, Hašúm, Hašbadána, Zeharjá in Mešulám.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, '§ Ezra je odprl knjigo v pogledu vsega ljudstva (kajti on je bil nad vsem ljudstvom); in ko jo je odprl, je vse ljudstvo vstalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Ezra je blagoslovil Gospoda, vélikega Boga. In vse ljudstvo je z dviganjem svojih rok odgovarjalo: »Amen, amen.« In sklonili so svoje glave ter oboževali Gospoda s svojimi obrazi k tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Tudi Ješúa, Baní, Šerebjá, Jamín, Akúb, Šabetáj, Hodijá, Maasejá, Kelitá, Azarjá, Jozabád, Hanán, Pelajá in Lévijevci so storili ljudstvu, da je razumelo postavo in ljudstvo je stalo na svojem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Tako so razločno brali v knjigi Božje postave in dali pomen in jim storili, da razumejo branje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Nehemija, ki je Tirsata in pisar Ezra, duhovnik in Lévijevci, ki so učili ljudstvo, so vsemu ljudstvu rekli: »Ta dan je svet Gospodu, svojemu Bogu; ne žalujte niti ne jokajte.« Kajti vse ljudstvo je jokalo, ko so slišali besede postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Potem jim je rekel: »Pojdite svojo pot, jejte tolščo, pijte sladko in pošljite deleže tistim, za katere ni ničesar pripravljenega, kajti ta dan je svet našemu Gospodu. Niti ne bodite žalostni, kajti Gospodova radost je vaša moč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Tako so Lévijevci umirili vse ljudstvo, rekoč: »Ohranite svoj mir, kajti dan je svet. Niti ne bodite užaloščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'In vse ljudstvo je odšlo svojo pot, da jedo in da pijejo in da pošljejo deleže in da naredijo veliko veselje, ker so razumeli besede, ki so jim bile naznanjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Na drugi dan so bili zbrani skupaj vodje očetov izmed vsega ljudstva, duhovniki in Lévijevci, k pisarju Ezru, celo da razumejo besede iz postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'In našli so zapisano v postavi, ki jo je Gospod zapovedal po Mojzesu, da naj bi Izraelovi otroci na praznik sedmega meseca prebivali v šotorih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'in da naj bi objavili in razglasili po vseh svojih mestih in v Jeruzalemu, rekoč: »Pojdite naprej na goro in naberite oljčne mladike, borove mladike, mirtine mladike, mladike palm in mladike debelih dreves, da naredite šotore, kakor je to pisano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Tako je ljudstvo šlo naprej in jih prineslo in si naredilo šotore, vsak na strehi svoje hiše, na svojih dvorih, na dvorih Božje hiše, na ulici Vodnih velikih vrat in na ulici Efrájimovih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Vsa skupnost izmed teh, ki so ponovno prišli iz ujetništva, si je naredila šotore in sedela pod šotori, kajti od dni Nunovega sina Ješúa do tega dne Izraelovi otroci niso tako storili. In tam je bilo zelo veliko veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Tudi dan za dnem, od prvega dne do zadnjega dne, je bral v knjigi Božje postave. Praznovanje so imeli sedem dni, na osmi dan pa je bil slovesen zbor, glede na običaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Torej na štiriindvajseti dan tega meseca so se Izraelovi otroci zbrali s postom in z vrečevinami in prstjo na sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Izraelovo seme se je ločilo od vseh tujcev in stali so ter priznavali svoje grehe in krivičnosti svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Vstali so na svojem kraju in brali v knjigi postave Gospoda, svojega Boga, eno četrtino dneva. Drugo četrtino pa so priznavali in oboževali Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Tedaj so vstali na stopnicah izmed Lévijevcev: Ješúa, Baní, Kadmiél, Šebanjá, Buní, Šerebjá, Baní in Kenáni in z močnim glasom vpili h Gospodu, svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Potem so Lévijevci Ješúa, Kadmiél, Baní, Hašabnejá, Šerebjá, Hodijá, Šebanjá in Petahjá rekli: »Vstanite in blagoslavljajte Gospoda, svojega Boga, na veke vekov in blagoslovljeno bodi tvoje veličastno ime, ki je vzvišeno nad vsem blagoslavljanjem in hvalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ti, celó ti sam si Gospod. Naredil si nebo in nebesa nebes, z vso njihovo vojsko, zemljo in vse stvari, ki so na njej, morja in vse, kar je v njih in ti jih vse ohranjaš in nebeška vojska te obožuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ti si Gospod Bog, ki je izbral Abrama in ga privedel naprej iz Ura Kaldejcev in si mu dal ime Abraham.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Njegovo srce si pred seboj našel zvesto in z njim si sklenil zavezo, da daš deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Jebusejcev in Girgašéjcev, da jo daš, pravim, njegovemu semenu in izvršil si svoje besede, kajti pravičen si.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Videl si stisko naših očetov v Egiptu in prisluhnil njihovemu vpitju pri Rdečem morju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'in pokazal si znamenja in čudeže na faraonu in na vseh njegovih služabnikih in na vsemu ljudstvu njegove dežele, kajti ti veš, da so ponosno postopali zoper njih. Tako si si pridobil ime, kakor je to ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Pred njimi si razdelil morje, tako da so šli skozi sredo morja po suhi deželi. Njihove preganjalce si vrgel v globine kakor kamen v sredo mogočnih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Poleg tega si jih podnevi vodil z oblačnim stebrom in ponoči z ognjenim stebrom, da bi jim dal svetlobo na poti, po kateri naj bi šli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Ti si tudi prihajal dol na goro Sinaj in govoril z njimi iz nebes in jim dajal prave sodbe in resnične postave, dobre zakone in zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Dal si jim spoznati svoj sveti šabat in jim zapovedal predpise, zakone in postave, po roki svojega služabnika Mojzesa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'in dajal si jim kruh iz nebes za njihovo lakoto in zanje si za njihovo žejo privedel vodo iz skale in jim obljubljal, da naj bi šli in vzeli v last deželo, ki si jim jo prisegel, da jim jo daš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Toda oni in naši očetje so ponosno postopali in otrdili svoje vratove in niso prisluhnili tvojim zapovedim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'in odklonili so ubogati niti niso razmišljali o tvojih čudežih, ki si jih storil med njimi, temveč so otrdili svoje vratove in v svojem uporu so določili poveljnika, da se vrnejo k svojemu suženjstvu. Toda ti si Bog, pripravljen odpustiti, milostljiv in usmiljen, počasen za jezo in velike prijaznosti in jih nisi zapustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Da, ko so si naredili ulito tele in rekli: »To je tvoj Bog, ki te je privedel iz Egipta,« in počeli so veliko izzivanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'jih vendar ti v svojih mnogoterih usmiljenih nisi zapustil v divjini. Podnevi oblačen steber ni odšel od njih, da jih vodi po poti niti ognjeni steber ponoči, da jim kaže svetlobo in pot, po kateri naj bi šli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Dajal si jim tudi svojega dobrega duha, da jih pouči in pred njihovimi usti nisi zadržal mane in za njihovo žejo si jim dajal vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Da, štirideset let si jih podpiral v divjini, tako da jim ničesar ni manjkalo. Njihova oblačila se niso postarala in njihova stopala niso otekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Poleg tega si jim dajal kraljestva in narode in razdelil si jih po pokrajinah. Tako so vzeli v last deželo Sihón, deželo hešbónskega kralja in deželo bašánskega kralja Oga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Tudi njihove otroke si pomnožil kakor zvezd na nebu in jih privedel v deželo, glede katere si njihovim očetom obljubil, da naj bi šli vanjo, da jo vzamejo v last.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Tako so otroci šli v deželo, jo vzeli v last in ti si pred njimi podjarmil prebivalce dežele, Kánaance in jih dal v njihove roke, z njihovimi kralji in ljudstvom dežele, da so lahko z njimi storili, kakor so hoteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Zavzeli so utrjena mesta in tolsto deželo in vzeli v last hiše, polne vseh dobrin, izkopane vodnjake, vinograde, oljčne nasade in sadnih dreves v obilju. Tako so jedli, bili nasičeni, se odebelili in se razveseljevali v tvoji veliki dobroti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Kljub temu so bili neposlušni in so se uprli zoper tebe in tvojo postavo vrgli za svoje hrbte in usmrtili tvoje preroke, ki so pričevali zoper njih, da jih obrnejo k tebi in naredili so velika izzivanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Zato si jih izročil v roko njihovih sovražnikov, ki so jih stiskali. V času svoje stiske, ko so klicali k tebi, si jih uslišal iz nebes in glede na svoja mnogotera usmiljenja si jim dal rešitelje, ki so jih rešili iz roke njihovih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Toda potem, ko so imeli počitek, so pred teboj ponovno storili zlo. Zato si jih pustil v roki njihovih sovražnikov, tako da so imeli gospostvo nad njimi. Vendar ko so se vrnili in klicali k tebi, si jih slišal iz nebes in mnogokrat si jih osvobodil glede na svoja usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'In ti pričuješ zoper njih, da bi jih lahko ponovno privedel k svoji postavi. Vendar so ponosno postopali in niso prisluhnili tvojim zapovedim, temveč so grešili zoper tvoje sodbe (katere, če jih človek izpolnjuje, bo živel v njih) in umaknili ramo in otrdili svoj vrat in niso hoteli prisluhniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Vendar si jih mnogo let prenašal in zoper njih pričeval po svojem duhu v svojih prerokih, vendar niso hoteli pazljivo prisluhniti. Zato si jih dajal v roko ljudstvu dežel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Vendar jih zaradi svojih velikih usmiljenj nisi popolnoma použil niti zapustil, kajti ti si usmiljen in milostljiv Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Zdaj torej, naš Bog, velik, mogočen in strašen Bog, ki ohranjaš zavezo in usmiljenje, naj se vsa stiska, ki je prišla nad nas, na naše kralje, na naše prince, na naše duhovnike, na naše očete in na vse tvoje ljudstvo, od časa asirskih kraljev do današnjega dne, ne zdi majhna pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Vendar si ti pravičen v vsem, kar si privedel nad nas, kajti storil si pravilno, toda mi smo storili zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Niti se naši kralji, naši princi, naši duhovniki, niti naši očetje, niso držali tvoje postave, niti niso prisluhnili tvojim zapovedim in tvojim pričevanjem, s katerimi si pričeval zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Kajti niso služili tebi v svojem kraljestvu in v tvoji veliki dobroti, ki jim jo daješ v veliki in obilni deželi, ki jo postavljaš prednje niti se niso odvrnili od svojih zlobnih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Glej, mi smo ta dan služabniki in glede dežele, ki si jo dal našim očetom, da jemo njen sad in njeno dobro, glej, mi smo služabniki v njej');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'in ta rojeva mnogo donosa kraljem, ki si jih zaradi naših grehov postavil nad nas. Prav tako imajo po njihovem užitku gospostvo nad našimi telesi in nad našo živino in mi smo v veliki stiski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Zaradi vsega tega delamo zanesljivo zavezo in jo zapisujemo in naši princi, Lévijevci in duhovniki, jo pečatijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, '§ Torej tisti, ki so pečatili, so bili: Nehemija, Hahaljájev sin Tirsata, Sedekíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, '§ Serajá, Azarjá, Jeremija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pašhúr, Amarjá, Malkijá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hatúš, Šebanjá, Malúh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harím, Meremót, Obadjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginetón, Baruh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mešulám, Abíja, Mijamín,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazjá, Bilgáj, Šemajá. Ti so bili duhovniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Lévijevci: tako Azanjájev sin Ješúa, Binúj izmed Henadádovih sinov, Kadmiél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'kakor njihovi bratje: Šebanjá, Hodijá, Kelitá, Pelajá, Hanán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miha, Rehób, Hašabjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zahúr, Šerebjá, Šebanjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodijá, Baní, Benínu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Vodje ljudstva: Paróš, Pahat Moáb, Elám, Zatú, Baní,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Buní, Azgád, Bebáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adoníja, Bigváj, Adín,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Atêr, Ezekíja, Azúr,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodijá, Hašúm, Becáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Haríf, Anatót, Nebáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpiáš, Mešulám, Hezír,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mešezabél, Cadók, Jadúa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatjá, Hanán, Anajá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hošéa, Hananjá, Hašúb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Lohéš, Pilhá, Šobék,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehúm, Hašabná, Maasejá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahíja, Hanán, Anán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malúh, Harím in Baaná.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Preostanek ljudstva, duhovniki, Lévijevci, vratarji, pevci, Netinimci in vsi, ki so se ločili od ljudstva dežel k postavi Boga, njihove žene, njihovi sinovi in njihove hčere, vsak, ki je imel spoznanje in imel razumevanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'so se pridružili k svojim bratom, svojim plemičem in vstopili v prekletstvo in prisego, da se ravnajo po Božji postavi, ki je bila dana po Mojzesu, Božjemu služabniku in da obeležujejo in delajo vse zapovedi Gospoda, našega Gospoda, njegove sodbe in njegove zakone,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'in da mi ne bi dajali svojih hčera ljudstvu dežele niti jemali njihovih hčera za naše sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Če ljudstvo dežele prinese blago ali kakršen koli živež na šabatni dan, da prodaja, da mi tega ne bomo kupovali od njih na šabat ali na sveti dan in da bomo pustili sedmo leto in izterjavo vsakega dolga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Prav tako smo naredili odredbe za sebe, da se letno obremenimo s tretjino šekla za službo hiše svojega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'za hlebe navzočnosti in za nenehno jedilno daritev in za nenehno žgalno daritev od šabat, od mlajev, za določene praznike, za svete stvari in za daritve za greh, da se naredi odkupitev za Izrael in za vse delo hiše svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Vrgli smo žrebe med duhovniki, Lévijevci in ljudstvom za dar lesa, da bi ga prinašali v hišo svojega Boga, glede na hiše naših očetov, ob določenih časih, leto za letom, da [ga] zažigamo na oltarju Gospoda, svojega Boga, kakor je to zapisano v postavi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'in da prinašamo prve sadove svojih tal in prve sadove vsega sadja od vseh dreves, leto za letom, v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Tudi prvorojenca naših sinov in naše živine, kakor je to zapisano v postavi in prvence naših čred in naših tropov, da jih privedemo k hiši svojega Boga, k duhovnikom, ki služijo v hiši našega Boga');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'In da naj bi prinesli prve sadove našega testa in naših daritev in sad vseh vrst dreves, od vina in od olja, k duhovnikom, k sobam hiše našega Boga in desetine naših tal k Lévijevcem, da bodo isti Lévijevci lahko imeli desetine v vseh mestih našega posevka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Duhovnik, Aronov sin, bo z Lévijevci, ko bodo Lévijevci prejemali desetine in Lévijevci bodo prinesli gor desetino od desetin k hiši našega Boga, k sobam, v zakladno hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Kajti Izraelovi otroci in Lévijevi otroci bodo prinašali daritev žita, od novega vina in olja, v sobe, kjer so posode svetišča in duhovniki, ki služijo in vratarji in pevci. Ne bomo zapustili hiše svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Voditelji ljudstva so prebivali pri Jeruzalemu. Ostali ljudje pa so prav tako metali žrebe, da privedejo enega izmed desetih, da prebiva v Jeruzalemu, svetemu mestu in devet delov, da prebivajo v drugih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Ljudstvo je blagoslovilo vse može, ki so se voljno ponudili, da prebivajo v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Torej ti so vodje province, ki so prebivali v Jeruzalemu. Toda v judejskih mestih je vsak prebival na svoji posesti v svojih mestih, namreč Izrael, duhovniki, Lévijevci, Netinimci in otroci Salomonovih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'V Jeruzalemu so prebivali nekateri izmed Judovih otrok in izmed Benjaminovih otrok. Izmed Judovih otrok: Atajá, sin Uzíjaha, sinú Zeharjá, sinú Amarjá, sinú Šefatjá, sinú Mahalaléla, izmed Perecovih otrok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'in Maasejája, sin Baruha, sinú Kolhozéja, sinú Hazajája, sinú Adajája, sinú Jojaríba, sinú Zeharjá, sinú Šilčana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Vseh Perecovih sinov, ki so prebivali v Jeruzalemu, je bilo štiristo oseminšestdeset hrabrih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'To so Benjaminovi sinovi: Salú, sin Mešuláma, sinú Joéda, sinú Pedajá, sinú Kolajája, sinú Maasejája, sinú Itiéla, sinú Ješajája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'In za njim Gabáj, Saláj, devetsto osemindvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Zihríjev sin Joél je bil njihov nadzornik, Senuájev sin Juda pa je bil drugi nad mestom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Od duhovnikov: Jojaríbov sin Jedajá, Jahín.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Serajá, sin Hilkijája, sinú Mešuláma, sinú Cadóka, sinú Merajóta, sinú Ahitúba, je bil poveljnik Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Njihovih bratov, ki so opravljali delo hiše, je bilo osemsto dvaindvajset. Adajá, sin Jeroháma, sinú Pelaljája, sinú Amcíja, sinú Zeharjá, sinú Pašhúrja, Malkijájevega sina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'in njegovi bratje, vodje očetov, dvesto dvainštirideset. Amašsáj, sin Azaréla, sinú Ahzája, sinú Mešilemóta, sinú Imêrja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'in njihovi bratje, močni junaški možje, sto osemindvajset. Njihov nadzornik je bil Zabdiél, sin enega izmed velikih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Tudi izmed Lévijevcev: Šemajá, sin Hašúba, sinú Azrikáma, sinú Hašabjája, sinú Buníja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Šabetáj ter Jozabád izmed vodij Lévijevcev sta imela nadzor nad zunanjim poslom Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Matanjá, sin Miha, sinú Zabdíja, sinú Asáfa, je bil glavni, da prične zahvaljevanje v molitvi. Bakbukjá, drugi med njegovimi brati in Abdá, sin Šamúaja, sinú Galála, sinú Jedutúna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Vseh Lévijevcev v svetem mestu je bilo dvesto štiriinosemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Poleg tega vratarji: Akúb, Talmón in njuni bratje, ki so varovali velika vrata, jih je bilo sto dvainsedemdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Preostanek Izraela, od duhovnikov in Lévijevcev, je bil v vseh Judovih mestih, vsak v svoji dediščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Toda Netinimci so prebivali v Ofelu. Cihá in Gišpá pa sta bila nad Netinimci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Nadzornik Lévijevcev v Jeruzalemu je bil tudi Uzí, sin Baníja, sinú Hašabjája, sinú Matanjája, sinú Miha. Izmed Asáfovih sinov so bili pevci nad poslom Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Kajti to je bila kraljeva zapoved glede njih, da naj bo določen delež za pevce, kar jim je pripadalo za vsak dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petahjá, sin Mešezabéla, izmed otrok Judovega sina Zeraha je bil pri kraljevi roki v vseh zadevah glede ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Glede vasi, z njihovimi polji, so nekateri izmed Judovih otrok prebivali pri Kirját Arbi in v njenih vaseh, pri Dibónu in v njegovih vaseh, pri Kabceélu in v njegovih vaseh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'pri Ješúi, pri Moládi, pri Bet Peletu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'pri Hacár Šuál in pri Beeršébi in v njenih vaseh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'pri Ciklágu, pri Mehóni in v njegovih vaseh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'pri En Rimónu, pri Cori, pri Jarmútu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanóahu, Adulámu in v njihovih vaseh, pri Lahíšu in njegovih poljih, pri Azéki in v njenih vaseh. In prebivali so od Beeršébe, do doline Hinóm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Tudi otroci Benjamina iz Gebe so prebivali pri Mihmášu, Aji, Betelu in v njihovih vaseh');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'in pri Anatótu, Nobu, Ananjáju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hacórju, Rami, Gitájimu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadídu, Cebojímu, Nebalátu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lodu in Onóju, dolini rokodelcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Izmed Lévijevcev so bili oddelki v Judu in v Benjaminu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Torej to so duhovniki in Lévijevci, ki so prišli gor z Zerubabélom, Šealtiélovim sinom in Ješúom: Serajá, Jeremija, Ezra,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarjá, Malúh, Hatúš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Šehanjá, Rehúm, Meremót,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Idó, Ginetó, Abíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamín, Maadjá, Bilgá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Šemajá, Jojaríb, Jedajája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salú, Amók, Hilkijá, Jedajája. Ti so bili vodje duhovnikov in njihovih bratov v dneh Ješúa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Poleg tega Lévijevci: Ješúa, Binúj, Kadmiél, Šerebjá, Juda in Matanjá, ki je bil nad zahvaljevanjem, on in njegovi bratje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Tudi Bakbukjá in Uní, njihova brata, sta bila njim nasproti na stražah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Ješúa je zaplodil Jojakíma, Jojakím je zaplodil tudi Eljašíba, Eljašíb je zaplodil Jojadá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojadá je zaplodil Jonatana in Jonatan je zaplodil Jadúa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'V dneh Jojakíma so bili duhovniki, vodja očetov: od Serajáma Merajá, od Jeremija Hananjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'od Ezra Mešulám, od Amarjá Johanán,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'od Melicuja Jonatan, od Šebanjá Jožef,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'od Haríma Adná, od Merajóta Helkáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'od Idója Zaharija, od Ginetóna Mešulám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'od Abíja Zihrí, od Minjamína, od Moadjája Piltáj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'od Bilgája Šamúa, od Šemajája Jehonatan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'in od Jojaríba Matenáj, od Jedajája Uzí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'od Salája Kaláj, od Amóka Eber,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'od Hilkijá Hašabjá, od Jedajája, Netanél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Lévijevci v dneh Eljašíba, Jojadája, Johanána in Jadúa so bili zabeleženi vodje očetov, tudi duhovniki, do kraljevanja Perzijca Dareja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Lévijevi sinovi, vodje očetov so bili zapisani v kroniški knjigi, celo do dni Eljašíbovega sina Johanána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Vodje Lévijevcev: Hašabjá, Šerebjá in Kadmiélov sin Ješúa z njihovimi brati nasproti njih, da hvalijo in da se zahvaljujejo, glede na zapoved Davida, Božjega moža, straža nasproti straži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanjá in Bakbukjá, Obadjá, Mešulám, Talmón, Akúb so bili vratarji, ki so varovali stražo pri pragovih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ti so bili v dneh Jojakíma, sina Ješúa, sinú Jocadákovega in v dneh voditelja Nehemija in preroka Ezra, pisarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Ob posvetitvi jeruzalemskega obzidja so iskali Lévijevce iz vseh njihovih krajev, da jih privedejo v Jeruzalem, da ohranjajo posvetitev z veseljem, tako z zahvaljevanjem kakor s petjem, s cimbalami, plunkami in harfami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Sinovi pevcev so se zbrali skupaj, tako iz ravne dežele okoli Jeruzalema kakor iz vasi Netófčanov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'tudi iz hiše Gilgála in iz gebskih in azmávetskih polj, kajti pevcem so zgradili vasi okoli Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Duhovniki in Lévijevci so očistili sebe, očistili ljudstvo in velika vrata ter obzidje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Potem sem na obzidje privedel Judove prince in določil dve veliki skupini tistih, ki so dajali zahvalo, od katerih je ena odšla na desno roko, po obzidju, h Gnojnim velikim vratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Za njimi je odšel Hošajá in polovica Judovih princev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Azarjá, Ezra, Mešulám,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Šemajá in Jeremija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Nekateri izmed duhovnikovih sinov s trobentami, namreč Zeharjá, sin Jonatana, sinú Šemajá, sinú Matanjá, sinú Mihajája, sinú Zahúrja, sinú Asáfa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'in njegovi bratje: Šemajá, Azarél, Milaláj, Gilaláj, Maáj, Netanél, Juda in Hananí z glasbenimi instrumenti Davida, Božjega moža in pisar Ezra pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Pri Studenčnih velikih vratih, ki so bila nasproti njim, so se po stopnicah Davidovega mesta povzpeli ob vzponu obzidja, nad Davidovo hišo, celo do Vodnih velikih vrat proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Druga skupina izmed tistih, ki so dajali zahvalo, pa je šla nasproti njim in jaz za njimi in polovica ljudstva na zidu od onstran stolpa talilnih peči, celo do širokega zidu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'in nad Efrájimovimi velikimi vrati, nad Starimi velikimi vrati, nad Ribjimi velikimi vrati in [mimo] stolpa Hananéla in stolpa Mea, torej do Ovčjih velikih vrat in so mirno obstali pri Jetniških velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Tako sta stali dve skupini izmed tistih, ki so dajali zahvalo v Božji hiši ter jaz in polovica vladarjev z menoj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'in duhovniki: Eljakím, Maasejája, Minjamín, Mihajá, Eljoenáj, Zeharjá in Hananjá s trobentami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'ter Maasejája, Šemajá, Eleazar, Uzí, Johanán, Malkijája, Elám in Ecer. Pevci so glasno peli z Jizrahjájem, njihovim nadzornikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Ta dan so darovali tudi veliko klavnih daritev in se veselili, kajti Bog jih je pripravil, da se veselijo z veliko radostjo. Tudi žene in otroci so se veselili, tako da je bilo veselje iz Jeruzalema slišati celo od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Ob tistem času so bili nekateri določeni nad sobe za zaklade, za daritve, za prve sadove in za desetine, da zberejo vanje iz mestnih polj deleže od postave za duhovnike in Lévijevce, kajti Juda se je veselil zaradi duhovnikov in Lévijevcev, ki so čakali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Tako pevci kakor vratarji so varovali službo svojega Boga in službo očiščevanja, glede na zapoved Davida in njegovega sina Salomona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Kajti v dneh Davida in Asáfa, so bili tam od davnine vodje pevcev s pesmimi hvaljenja in zahvaljevanja Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ves Izrael je v dneh Zerubabéla in v dneh Nehemija dal deleže pevcem in vratarjem, vsak dan njegov delež. Svete stvari pa so posvetili Lévijevcem in Lévijevci so jih posvetili Aronovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Na ta dan so brali Mojzesovo knjigo v občinstvu ljudstva in v njej je bilo najdeno zapisano, da naj Amónec in Moábec na veke ne bi prišla v Božjo skupnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'ker niso srečali Izraelovih otrok s kruhom in vodo, temveč so zoper njih najeli Bileáma, da bi jih preklel. Vendar je naš Bog prekletstvo obrnil na blagoslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Pripetilo se je torej, ko so slišali postavo, da so se od Izraela ločile vse mešane množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Pred tem je bil duhovnik Eljašíb, ki je imel nadzor nad sobo hiše našega Boga, zbližan k Tobiju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'in zanj pripravil veliko sobo, kjer so vnaprej položili jedilne daritve, kadilo, posode, desetine od žita, novega vina in olja, kar je bilo zapovedano, da naj bo dano Lévijevcem, pevcem in vratarjem ter darove duhovnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Toda v vsem tem času nisem bil v Jeruzalemu, kajti v dvaintridesetem letu babilonskega kralja Artakserksa sem prišel h kralju in po določenih dneh sem od kralja prejel dovoljenje za odhod');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'in prišel sem v Jeruzalem in razumel zlo, ki ga je Eljašíb storil Tobiju, s tem, da mu je pripravil sobo na dvorih Božje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'To me je boleče užalostilo, zato sem iz sobe vrgel ven vse Tobijeve gospodinjske stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Potem sem zapovedal in očistili so sobe. Tja sem ponovno prinesel posode iz Božje hiše, z jedilno daritvijo in kadilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Zaznal sem, da jim niso bili dani deleži Lévijevcev, kajti Lévijevci in pevci, ki so opravljali delo, so pobegnili vsak k svojemu polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Potem sem se pričkal s poveljniki in rekel: »Zakaj je Božja hiša zapuščena?« Zbral sem jih skupaj in jih postavil na njihov kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Potem je ves Juda prinesel desetino od žita, novega vina in olja v zakladnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Postavil sem zakladnike nad zakladnicami: duhovnika Šelemjája, pisarja Cadóka in izmed Lévijevcev Pedajá. Poleg njih je bil Hanán, sin Zahúrja, sinú Matanjá, kajti bili so šteti zveste in njihova služba je bila, da razdeljujejo svojim bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, '»Spomni se me, oh moj Bog, glede tega in ne izbriši mojih dobrih dejanj, ki sem jih storil za hišo svojega Boga in za njene službe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'V tistih dneh sem na šabat videl v Judu nekatere tlačiti vinske stiskalnice, prinašati snope in natovarjati osle kakor tudi vino, grozdje, fige in vse vrste bremen, ki so jih na šabatni dan prinesli v Jeruzalem. Pričeval sem zoper njih na dan, na katerega so prodajali živež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tam notri so prebivali tudi možje iz Tira, ki so prinašali ribe in vse vrste blaga in na šabatni dan prodajali Judovim otrokom in v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Potem sem se pričkal z Judovimi plemiči in jim rekel: »Kakšno zlo je to, ki ga delate in oskrunjate šabatni dan?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Mar niso tako počeli vaši očetje in ali ni naš Bog privedel vsega tega zla nad nas in nad to mesto? Vendar nad Izrael prinašate več besa z oskrunitvijo šabata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Pripetilo se je, ko so jeruzalemska velika vrata pred šabat pričenjala temneti, da sem zapovedal, naj se velika vrata zapro in jih zadolžil, da naj ne bodo odprta, dokler ne mine šabat in nekatere izmed svojih služabnikov sem postavil pri velikih vratih, da na šabatni dan ne bi bilo noter privedeno nobeno breme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Tako so trgovci in prodajalci vseh vrst blaga enkrat ali dvakrat prenočili zunaj Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Potem sem pričeval zoper njih in jim rekel: »Zakaj prenočujete okoli obzidja? Če boste ponovno storili tako, bom svoje roke položil na vas.« Od tistega časa naprej niso več prihajali na šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Lévijevcem sem zapovedal, da naj se očistijo in da naj pridejo in varujejo velika vrata, da posvetijo šabatni dan. »Spomni se me, oh moj Bog, tudi glede tega in prizanesi mi glede na veličino svojega usmiljenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'V tistih dneh sem videl tudi Jude, ki so poročili žene iz Ašdóda, iz Amóna in iz Moába');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'in njihovi otroci so govorili pol v ašdódskem jeziku in niso mogli govoriti judovskega jezika, temveč glede na jezik vsakega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Pričkal sem se z njimi in jih preklel in udaril nekatere izmed njih, izpulil njihove lase in jih primoral, da so prisegli pri Bogu, rekoč: »Svojih hčera ne boste dajali njihovim sinovom niti ne boste jemali njihovih hčera za svoje sinove ali zase.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Mar ni Salomon, Izraelov kralj, grešil s temi stvarmi? Pa vendar med mnogimi narodi ni bilo nobenega kralja, podobnega njemu, ki je bil ljubljen od svojega Boga in ga je Bog postavil [za] kralja nad vsem Izraelom. Kljub temu so celo njemu tuje žene povzročile, da je grešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Mar naj potem prisluhnemo vam, da bi delali vso to veliko zlo, da grešimo zoper svojega Boga v poročanju tujih žena?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Eden izmed sinov Jojadája, sin vélikega duhovnika Eljašíba, je bil zet Horónca Sanbaláta, zato sem ga pregnal od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, '»Spomni se jih, oh moj Bog, ker so omadeževali duhovništvo in zavezo duhovništva in Lévijevcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Tako sem jih očistil vseh tujcev in določil straže duhovnikov in Lévijevcev, vsakega pri svojem poslu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'in za dar lesa, ob določenih časih in za prve sadove. »Spominjaj se me, oh moj Bog, za vselej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Pripetilo se je torej v dneh kralja Ahasvérja (to je Ahasvérja, ki je kraljeval od Indije celo do Etiopije, nad sto sedemindvajsetimi provincami),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'da je v tistih dneh, ko je Kralj Ahasvér sedel na prestolu svojega kraljestva, ki je bilo v palači Suze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'v tretjem letu njegovega kraljevanja, priredil gostijo vsem svojim princem in svojim služabnikom; moči Perzije in Medije, plemičem in princem provinc, ki so bili pred njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'ko jim je mnogo dni kazal bogastva svojega veličastnega kraljestva in čast svojega odličnega veličanstva, celó sto osemdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Ko so ti dnevi minili, je kralj priredil gostijo vsemu ljudstvu, ki je bilo prisotno v palači Suze, tako velikim kakor malim, sedem dni na dvoru vrta kraljeve palače,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'kjer so bile bele, zelene in modre tanke preproge, pritrjene z vrvicami iz tankega lanenega platna in vijolične, k srebrnim obročem in stebrom iz marmorja. Postelje so bile iz zlata in srebra, na tlaku iz rdečega, modrega, belega in črnega marmorja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Dajali so jim piti iz zlatih posod (posode so bile različne ena od druge) in kraljevega vina v obilju, glede na kraljevo razkošje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Pitje je bilo glede na postavo. Nihče ni silil, kajti tako je kralj določil vsem častnikom njegove hiše, da naj storijo glede na užitek vsakega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Prav tako je kraljica Vaští pripravila gostijo za ženske v kraljevi hiši, ki je pripadala Kralju Ahasvérju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Na sedmi dan, ko je bilo kraljevo srce veselo od vina, je ukazal Mehumánu, Bizetáju, Harbonáju, Bigtáju, Abagtáju, Zetárju in Karkásu, sedmim glavnim dvornim upraviteljem, ki so služili v prisotnosti Kralja Ahasvérja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'da privedejo kraljico Vaští s kraljevo krono pred kralja, da ljudstvu in princem pokaže njeno lepoto, kajti bila je lepa na pogled.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Toda kraljica Vaští je odklonila, da pride na kraljevo zapoved po njegovih glavnih dvornih upraviteljih. Zato je bil kralj zelo ogorčen in njegova jeza je gorela v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Potem je kralj rekel modrim možem, ki so poznali čase (Kajti tak je bil kraljev običaj do vseh teh, ki so poznali postavo in sodbo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'in takoj poleg njega so bili Karšenáj, Šetár, Admát, Taršíš, Meres, Marsenáj in Memuhán, sedem princev iz Perzije in Medije, ki so videli kraljevo obličje in ki so prvi sedeli v kraljestvu.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '»Kaj naj storimo kraljici Vaští, glede na postavo, ker po glavnih dvornih upraviteljih ni izpolnila zapovedi Kralja Ahasvérja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Memuhán je pred kraljem in princi odgovoril: »Kraljica Vaští ni storila narobe samo kralju, temveč tudi vsem princem in vsemu ljudstvu, ki so po vseh provincah Kralja Ahasvérja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Kajti to dejanje kraljice bo prišlo povsod do vseh žensk, tako da bodo v svojih očeh prezirale svoje soproge, ko bo to sporočeno: ›Kralj Ahasvér je zapovedal kraljici Vaští, da bi bila privedena predenj, toda ni prišla.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Podobno bodo gospe iz Perzije in Medije, ki so slišale o kraljičinem dejanju, ta dan rekle vsem kraljevim princem. Tako bo vstalo preveč zaničevanja in besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Če to ugaja kralju, naj gre od njega kraljeva zapoved in naj bo ta zapisana med postave Perzijcev in Medijcev, da ta ne bo predrugačena: ›Da Vaští ne pride več pred Kralja Ahasvérja. Kralj pa naj njen kraljevi stan izroči drugi, ki je boljša kakor ona.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Ko bo kraljevi odlok, ki ga bo izdal, razglašen po vsem njegovem kraljestvu (kajti to je veliko), bodo vse žene dale svojim soprogom spoštovanje, tako malim, kakor velikim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Govor je ugajal kralju in princem in kralj je storil glede na Memuhánovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Kajti poslal je pisma v vse kraljeve province, v vsako provinco glede na njeno pisavo in vsakemu ljudstvu glede na njihov jezik, da bi vsak mož vladal v svoji lastni hiši in da bi bilo to razglašeno glede na jezik vsakega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Po teh stvareh, ko je bil bes Kralja Ahasvérja pomirjen, se je spomnil Vaští in kar je storila in kaj je bilo odrejeno zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Potem so mu kraljevi služabniki, ki so mu služili, rekli: »Naj bodo za kralja poiskane lepe mlade device.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Kralj naj določi častnike po vseh provincah svojega kraljestva, da lahko zberejo skupaj vse lepe mlade device v palačo Suze, v žensko hišo, pod oskrbo Hege, kraljevega glavnega upravitelja, čuvaja žensk in naj jim bodo dane njihove stvari za očiščevanje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'in naj bo dekle, ki ugaja kralju, kraljica namesto Vaští.« Stvar je kralju ugajala in tako je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Torej v palači Suze je bil nek Jud, katerega ime je bilo Mordohaj, sin Jaíra, sinú Šimíja, sinú Kiša, Benjaminovec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'ki je bil iz Jeruzalema odveden z ujetništvom, ki so bili odvedeni z Jehoníjem, Judovim kraljem, ki ga je babilonski kralj Nebukadnezar odvedel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Vzgajal je Hadáso, to je Estero, hčer svojega strica, kajti ni imela niti očeta niti matere, deklica pa je bila lepa in krasna, ki si jo je Mordohaj, ko sta bila njen oče in mati mrtva, vzel za svojo lastno hčer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Tako se je pripetilo, ko se je slišala kraljeva zapoved in njegov odlok in ko je bilo mnogo deklet skupaj zbranih v palači Suze, k oskrbi Hegája, da je bila tudi Estera privedena v kraljevo hišo, v oskrbo Hegája, čuvaja žensk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Dekle mu je ugajalo in od njega doseglo naklonjenost. Naglo ji je dal njene stvari za očiščenje, s takšnimi stvarmi, kakor so ji pripadale in sedem služabnic, ki so bile primerne, da so ji bile izročene iz kraljeve hiše, ter njo in njene deklice privedel v najboljši prostor ženske hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Estera pa ni prikazala svojega ljudstva niti svojega sorodstva, kajti Mordohaj ji je naročil, da naj tega ne prikaže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Mordohaj pa je vsak dan hodil pred dvor ženske hiše, da izve, kako se Estera počuti in kaj bo postalo iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Torej, ko je prišla za vsako deklico vrsta, da gre h Kralju Ahasvérju, potem ko je bila dvanajst mesecev, glede na določen način za ženske (kajti tako so bili dnevi njihovih očiščevanj dovršeni, namreč šest mesecev z oljem iz mire in šest mesecev s prijetnimi dišavami in z drugimi stvarmi za očiščevanje žensk),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'potem je vsako dekle tako prišlo h kralju. Karkoli si je želela, ji je bilo dano, da gre z njo iz ženske hiše v kraljevo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Zvečer je odšla, naslednji dan pa se je vrnila v drugo žensko hišo, k oskrbi Šaašgáza, kraljevega glavnega upravitelja, ki je čuval priležnice. Ni več prišla h kralju, razen če se je kralj razveseljeval v njej in da je bila poklicana po imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Torej ko je bila vrsta na Esteri, hčeri Abihájila, Mordohajevega strica, ki si jo je vzel za svojo hčer, je prišla, da gre noter h kralju. Ničesar ni zahtevala, razen kar je Hegáj, kraljevi glavni upravitelj, čuvaj žensk, določil. In Estera je dosegla naklonjenost v očeh vseh tistih, ki so pogledali nanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Tako je bila Estera odpeljana h Kralju Ahasvérju, v njegovo kraljevo hišo, v desetem mesecu, ki je mesec tébet, v sedmem letu njegovega vladanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Kralj pa je ljubil Estero nad vsemi ženskami in dosegla je milost in naklonjenost v njegovem pogledu, bolj kot vse device, tako da je kraljevo krono postavil na njeno glavo in jo naredil kraljico namesto Vaští.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Takrat je kralj naredil veliko praznovanje vsem svojim princem in svojim služabnikom, celó Esterin praznik. Provincam je naredil razbremenitev in dal darove glede na kraljevo razkošje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Ko so drugič zbirali device skupaj, takrat je Mordohaj sedel pri kraljevih velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Estera še ni prikazala svojega sorodstva niti svojega ljudstva, kakor ji je Mordohaj naročil, kajti Estera je izvršila Mordohajevo zapoved, podobno kakor, ko je bila vzgajana pri njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'V tistih dneh, medtem ko je Mordohaj sedel pri kraljevih velikih vratih, sta bila dva izmed glavnih dvornih upraviteljev, Bigtáj in Tereš, izmed tistih, ki sta varovala vrata, ogorčena in iskala, da položita roko na Kralja Ahasvérja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Stvar pa je bila odkrita Mordohaju, ki je to povedal kraljici Esteri in Estera je v Mordohajevem imenu o tem potrdila kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Ko je bilo o tej zadevi opravljeno zasliševanje, je bilo to razkrito, zato sta bila oba obešena na drevo. To je bilo pred kraljem zapisano v kroniško knjigo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po teh stvareh je Kralj Ahasvér povišal Hamána, Hamedátovega sina, Agágovca in ga napredoval in njegov sedež postavil nad vse prince, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Vsi kraljevi služabniki, ki so bili pri kraljevih velikih vratih, so se priklonili in častili Hamána, kajti kralj je glede njega tako zapovedal. Mordohaj pa se ni priklonil niti ga ni častil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Potem so kraljevi služabniki, ki so bili pri kraljevih velikih vratih, Mordohaju rekli: »Zakaj prestopaš kraljevo zapoved?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Pripetilo se je torej, ko so mu dnevno govorili in jim ni prisluhnil, da so povedali Hamánu, da vidijo, ali bodo Mordohajeve zadeve obstale, kajti povedal jim je, da je bil Jud.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Ko je Hamán videl, da se Mordohaj ni priklonil niti ga ni častil, potem je bil Hamán poln besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Zdelo se mu je v posmeh, da položi roke samo na Mordohaja, kajti pokazali so mu Mordohajevo ljudstvo. Zato je Hamán iskal, da uniči vse Jude, ki so bili po celotnem Ahasvérjevem kraljestvu, torej Mordohajevo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'V prvem mesecu, ki je mesec nisán, v dvanajstem letu kralja Ahasvérja, so metali pur, kar je žreb, pred Hamánom iz dneva v dan in iz meseca v mesec, do dvanajstega meseca, ki je mesec adár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Hamán je rekel Kralju Ahasvérju: »Tam je neko ljudstvo, razkropljeno naokoli in razpršeno med ljudstvom po vseh provincah tvojega kraljestva. Njihove postave so različne od vsega ljudstva niti se ne držijo kraljevih postav. Zatorej to ni za kraljevo korist, da jih trpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Če to ugaja kralju, naj bo to zapisano, da bodo lahko uničeni, jaz pa bom plačal deset tisoč talentov srebra rokam tistih, ki so zadolženi za to delo, da to prinesejo v kraljeve zakladnice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Kralj je iz svoje roke snel svoj prstan ter ga dal Hamedátovemu sinu Hamánu, Agágovcu, sovražniku Judov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Kralj je rekel Hamánu: »Srebro ti je dano, tudi ljudstvo, da storiš z njimi, kakor se ti zdi dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Potem so bili na trinajsti dan prvega meseca poklicani kraljevi pisarji in bilo je napisano glede na vse, kar je Hamán ukazal kraljevim poročnikom in voditeljem, ki so bili nad vsako provinco in vladarjem vsakega ljudstva vsake province, glede na njihovo pisavo in vsakemu ljudstvu glede na njihov jezik. V imenu kralja Ahasvérja je bilo napisano in zapečateno s kraljevim prstanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Pisma so bila po slih poslana v vse kraljeve province, da uničijo, ubijejo in pogubijo vse Jude, tako mlade kakor stare, majhne otroke in ženske, na en dan, torej na trinajsti dan dvanajstega meseca, ki je mesec adár in da si njihov dobiček vzamejo za plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Prepis pisanja za zapoved, ki naj bo predana v vsako provinco, je bilo razglašeno vsem ljudstvom, da bodo pripravljeni za ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Sli so odšli ven, podvizani s kraljevo zapovedjo in odlok je bil izdan v palači Suze. Kralj in Hamán pa sta se usedla, da pijeta, mesto Suze pa je bilo zbegano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Ko je Mordohaj zaznal vse, kar je bilo storjeno, je Mordohaj raztrgal svoja oblačila in si nadel vrečevino s pepelom in odšel ven v sredo mesta ter vpil z glasnim in grenkim glasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Prišel je celo pred kraljeva velika vrata, kajti nihče ne more vstopiti v kraljeva velika vrata, oblečen z vrečevino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'V vsaki provinci, kamor sta prišla kraljeva zapoved in njegov odlok, je bilo med Judi veliko žalovanje, post, jokanje in tarnanje in mnogi so ležali v vrečevini in pepelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Tako so Esterine služabnice in njeni glavni dvorni upravitelji prišli in ji to povedali. Potem je bila kraljica silno užaloščena. Poslala je oblačilo, da obleče Mordohaja in da odstrani njegovo vrečevino proč iz njega, toda on tega ni sprejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Potem je Estera poklicala po Hatáha, enega izmed kraljevih glavnih dvornih upraviteljev, ki je bil določen, da ji služi in mu dala zapoved za Mordohaja, da izve kaj je bilo to in zakaj je bilo to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Tako je Hatáh odšel k Mordohaju, na mestno ulico, ki je bila pred kraljevimi velikimi vrati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Mordohaj mu je povedal o vsem, kar se mu je zgodilo in o vsoti denarja, ki ga je Hamán obljubil plačati v kraljeve zakladnice za Jude, da jih uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Dal mu je tudi kopijo pisanja odloka, ki je bil izdan v [mestu] Suze, da jih uniči, da ga pokaže Esteri in da ji to oznani in da jo zadolži, da naj bi šla h kralju, da mu izroči ponižno prošnjo in da pred njim sporoči zahtevo za svoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Hatáh je prišel in Esteri povedal Mordohajeve besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Estera je Hatáhu ponovno spregovorila in mu dala zapoved za Mordohaja:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '»Vsi kraljevi služabniki in ljudstvo kraljevih provinc vedo, da kdorkoli, ki ni poklican, bodisi moški ali ženska, pride h kralju na notranji dvor, je zanj ena postava, da ga usmrté, razen tistega, proti kateremu bo kralj iztegnil zlato žezlo, da bo lahko živel. Toda jaz nisem bila poklicana, da pridem h kralju teh trideset dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Esterine besede so povedali Mordohaju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Potem je Mordohaj zapovedal odgovoriti Esteri: »Ne misli si, da boš ti v kraljevi hiši ušla bolj kakor vsi Judje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Kajti če ob tem času povsem ohranjaš svoj mir, potem bo povečanje in osvoboditev vstalo k Judom iz drugega kraja, toda ti in hiša tvojega očeta boste uničeni. Kdo ve, ali nisi prišla do kraljestva zaradi tega časa, kakor je ta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Potem jim je Estera zaukazala vrniti Mordohaju ta odgovor:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '»Pojdi, zberi skupaj vse Jude, ki so prisotni v [mestu] Suze in se postite zame in tri dni niti ne jejte niti ne pijte, ne ponoči ne podnevi. Tudi jaz in moje dekle se bomo prav tako postile in tako bom šla noter h kralju, kar ni glede na postavo, in če umrem, umrem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Tako je Mordohaj odšel svojo pot in storil glede na vse to, kar mu je Estera zapovedala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Pripetilo se je torej na tretji dan, da si je Estera nadela svojo kraljevsko obleko in stopila na notranji dvor kraljeve hiše, nasproti kraljevi hiši in kralj je sedel na svojem kraljevem prestolu, v kraljevi hiši, nasproti velikim vratom hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'In bilo je tako, da ko je kralj zagledal kraljico Estero stati na dvoru, je ta dosegla naklonjenost v njegovem pogledu. Kralj je proti Esteri iztegnil zlato žezlo, ki je bilo v njegovi roki. Tako se je Estera približala in se dotaknila vrha žezla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Potem ji je kralj rekel: »Kaj hočeš, kraljica Estera? Kakšna je tvoja prošnja? Dano ti bo celo do polovice kraljestva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Estera je odgovorila: »Če se to zdi kralju dobro, naj kralj in Hamán prideta danes na gostijo, ki sem jo pripravila zanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Potem je kralj rekel: »Pripravite Hamána, da se podviza, da bo lahko storil, kakor je rekla Estera.« Tako sta kralj in Hamán prišla na gostijo, ki jo je pripravila Estera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Kralj je pri vinski gostiji Esteri rekel: »Kaj je tvoja prošnja? Ta ti bo zagotovljena. Kaj je tvoja zahteva? Celo do polovice kraljestva ti bo izpolnjena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Potem je Estera odgovorila in rekla: »Moja prošnja in moja zahteva je,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'če sem našla naklonjenost v kraljevih očeh in če to ugaja kralju, da zagotovi mojo prošnjo in da izvede mojo zahtevo, naj kralj in Hamán prideta na gostijo, ki jo bom pripravila zanju, jutri pa bom storila, kakor je rekel kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Potem je Hamán tega dne odšel radosten in z veselim srcem. Toda, ko je Hamán pri kraljevih velikih vratih zagledal Mordohaja, ki ni vstal niti se zaradi njega ni premaknil, je bil poln ogorčenja zoper Mordohaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Vendar se je Hamán zadržal. Ko pa je prišel domov, je poslal in dal poklicati po svoje prijatelje in svojo ženo Zêrešo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Hamán jim je govoril o slavi svojih bogastev in množici svojih otrok in vseh stvareh, s katerimi ga je kralj povišal in kako ga je napredoval nad prince in kraljeve služabnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Poleg tega je Hamán rekel: »Da, kraljica Estera nobenemu drugemu ni dovolila vstopiti s kraljem na gostijo, ki jo je pripravila, razen meni in tudi jutri sem s kraljem povabljen k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Vendar mi vse to nič ne koristi, dokler vidim Juda Mordohaja sedeti pri kraljevih velikih vratih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Potem so mu njegova žena Zêreša in vsi njegovi prijatelji rekli: »Naj bodo narejene petdeset komolcev visoke vislice in jutri spregovori kralju, da bo Mordohaj lahko obešen nanje. Potem pojdi vesel s kraljem na gostijo.« Stvar je ugajala Hamánu in velel je, da se naredijo vislice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'To noč kralj ni mogel spati in zapovedal je, da prinesejo knjigo kroniških zapisov in brani so bili pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Najdeno je bilo zapisano, da je Mordohaj povedal o Bigtánu in Terešu, o dveh izmed glavnih dvornih upraviteljev, čuvajema vrat, ki sta iskala, da položita roko na Kralja Ahasvérja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Kralj je rekel: »Kakšna čast in dostojanstvo sta bila zaradi tega storjena Mordohaju?« Potem so kraljevi služabniki, ki so mu služili, rekli: »Nič ni bilo storjeno zanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Kralj je rekel: »Kdo je na dvoru?« Torej Hamán je prišel na zunanji dvor kraljeve hiše, da spregovori kralju, da Mordohaja obesi na vislice, ki jih je pripravil zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Kraljevi služabniki pa so mu rekli: »Glej, Hamán stoji na dvoru.« Kralj je rekel: »Naj vstopi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Tako je Hamán vstopil. Kralj mu je rekel: »Kaj naj bo storjeno človeku, ki se ga kralj razveseljuje, da ga počasti?« Torej Hamán je v svojem srcu mislil: ›Koga bi se kralj veselil, da ga počasti, bolj kakor mene?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Hamán je odgovoril kralju: »Za človeka, ki se ga kralj razveseljuje, da ga počasti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'naj bo prinesena kraljevska obleka, ki jo kralj uporablja za nošnjo in konj, na katerem jaha kralj in kraljeva krona, ki je postavljena na njegovi glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Ta obleka in konj naj bosta izročena roki enega izmed kraljevih najplemenitejših princev, da bodo lahko s tem oblekli človeka, ki se ga kralj razveseljuje počastiti in naj ga na konjskem hrbtu povedejo po mestni ulici in pred njim razglašajo: ›Tako bo to storjeno človeku, ki se ga kralj razveseljuje, da ga počasti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Potem je kralj rekel Hamánu: »Podvizaj se in vzemi obleko in konja, kakor si rekel in celo tako stori Judu Mordohaju, ki sedi pri kraljevih velikih vratih. Naj ničesar ne manjka od vsega, kar si govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Potem je Hamán vzel obleko in konja ter oblekel Mordohaja in ga na konjskem hrbtu povedel po mestni ulici in pred njim razglašal: »Tako bo storjeno človeku, ki se ga kralj razveseljuje, da ga počasti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'In Mordohaj je ponovno prišel h kraljevim velikim vratom. Hamán pa je žalujoč hitel k svoji hiši in svojo glavo je imel zakrito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Hamán je povedal svoji ženi Zêreši in vsem svojim prijateljem, vsako stvar, ki ga je doletela. Potem so mu njegovi modri možje in njegova žena Zêreša rekli: »Če je Mordohaj iz rodu Judov, pred katerim si začel padati, ne boš prevladal zoper njega, temveč boš zagotovo padel pred njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Medtem ko so še govorili z njim, so prišli kraljevi glavni dvorni upravitelji in hiteli, da Hamána privedejo na gostijo, ki jo je pripravila Estera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Tako sta kralj in Hamán prišla na gostijo s kraljico Estero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Kralj je drugi dan na vinski gostiji Esteri ponovno rekel: »Kaj je tvoja prošnja, kraljica Estera? Ta ti bo zagotovljena. Kaj je tvoja zahteva? Ta bo izpolnjena, celó do polovice kraljestva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Takrat je kraljica Estera odgovorila in rekla: »Če sem našla naklonjenost v tvojem pogledu, oh kralj in če to ugaja kralju, naj mi bo na mojo prošnjo dano moje življenje in moje ljudstvo na mojo zahtevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Kajti prodani smo, jaz in moje ljudstvo, da bi bili uničeni, da bi bili umorjeni in da umremo. Če pa bi bili prodani za sužnje in sužnjice, bi zadržala svoj jezik, čeprav sovražnik ne bi mogel izravnati kraljeve škode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Potem je Kralj Ahasvér odgovoril in kraljici Esteri rekel: »Kdo je tisti in kje je, da si v svojem srcu drzne dovoliti, da tako stori?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Estera pa je rekla: »Nasprotnik in sovražnik je ta zlobni Hamán.« Potem je bil Hamán prestrašen pred kraljem in kraljico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Kralj je vstal od vinske gostije in v svojem besu odšel v vrt palače. Hamán pa je vstal, da bi pri kraljici Esteri zaprosil za svoje življenje, kajti videl je, da je bilo pri kralju zoper njega določeno zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Potem se je kralj z vrta palače vrnil v prostor vinske gostije, Hamán pa je bil zrušen na postelji, na kateri je bila Estera. Potem je kralj rekel: »Ali bo tudi v hiši, pred menoj, posilil kraljico?« Brž ko je beseda odšla iz kraljevih ust, so pokrili Hamánov obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Harbonáj, eden izmed glavnih dvornih upraviteljev je pred kraljem rekel: »Glej, tudi vislice, petdeset komolcev visoke, ki jih je Hamán pripravil za Mordohaja, ki je dobro govoril za kralja, stojijo v Hamánovi hiši.« Potem je kralj rekel: »Obesite ga nanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Tako so Hamána obesili na vislice, ki jih je pripravil za Mordohaja. Potem je bil kraljev bes pomirjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Na ta dan je dal Kralj Ahasvér hišo Hamána, sovražnika Judov, kraljici Esteri. Mordohaj pa je prišel pred kralja, kajti Estera je povedala, kaj ji je bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Kralj je snel svoj prstan, ki ga je vzel od Hamána in ga dal Mordohaju. Estera pa je Mordohaja postavila nad Hamánovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Estera je ponovno spregovorila pred kraljem in padla dol pri njegovih stopalih in ga s solzami rotila, da odstrani vragolijo Hamána, Agágovca in njegov naklep, ki ga je zasnoval zoper Jude.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Potem je kralj proti Esteri iztegnil zlato žezlo. Tako je Estera vstala in stala pred kraljem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'in rekla: »Če kralju ugaja in če sem našla naklonjenost v njegovem pogledu in se zdi stvar pravilna pred kraljem in sem prijetna v njegovih očeh, naj bo zapisano, da se razveljavijo pisma, ki jih je zasnoval Hamán, Hamedátov sin, Agágovec, katera je napisal, da uničijo Jude, ki so po vseh kraljevih provincah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Kajti kako lahko prenašam gledanje zla, ki bo prišlo k mojemu ljudstvu? Ali kako lahko prenašam gledanje uničenja mojega sorodstva?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Tedaj je kralj Ahasvér rekel kraljici Esteri in Judu Mordohaju: »Glejta, Esteri sem dal hišo Hamána, njega pa so obesili na vislice, ker je svojo roko položil na Jude.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Tudi za Jude napišita, kakor vama to ugaja, v kraljevem imenu in to zapečatita s kraljevim prstanom, kajti pisanja, ki je napisano v kraljevem imenu in zapečateno s kraljevim pečatom, noben človek ne more razveljaviti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Potem so bili poklicani kraljevi pisarji, ob tistem času, v tretjem mesecu, ki je mesec siván, na njegov triindvajseti dan in to je bilo napisano glede na vse, kar je Mordohaj zapovedal Judom, poročnikom, namestnikom in vladarjem provinc, ki so od Indije do Etiopije, sto sedemindvajsetim provincam, vsaki provinci glede na njihovo pisanje in vsakemu ljudstvu glede na njihov jezik in Judom glede na njihovo pisanje in glede na njihov jezik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Napisal je v imenu Kralja Ahasvérja in to zapečatil s kraljevim prstanom in pisma poslal po slih na konjskem hrbtu in jahačih na mulah, kamelah in mladih [enogrbih] velblodih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'V teh je kralj zagotovil Judom, ki so bili v vsakem mestu, da se zberejo skupaj in da stojijo za svoje življenje, da uničijo, da ubijejo in da povzročijo, da umre vsa moč ljudstva in province, ki bi jih hotela napasti, tako malčke kakor ženske in da njihov dobiček vzamejo za plen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'na en dan po vseh provincah Kralja Ahasvérja, namreč na trinajsti dan dvanajstega meseca, ki je mesec adár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Kopija pisanja za zapoved, ki naj bi bila dana v vsako provinco, je bila razglašena vsemu ljudstvu in da naj bodo Judje pripravljeni za ta dan, da se maščujejo na svojih sovražnikih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Tako so sli, ki so jahali na mulah in kamelah, odšli ven, podvizani in pritisnjeni s kraljevo zapovedjo. In odlok je bil izdan pri palači Suze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mordohaj je odšel izpred prisotnosti kralja v kraljevski obleki iz modre in bele in z veliko krono iz zlata in z obleko iz tankega lanenega platna in vijolične, mesto Suze pa se je veselilo in bilo veselo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Judje so imeli svetlobo, veselje, radost in čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'V vsaki provinci in v vsakem mestu, kamor sta prišla kraljeva zapoved in njegov odlok, so imeli Judje radost in veselje, praznovanje in dober dan. In mnogi izmed ljudstva dežele so postali Judje, kajti strah pred Judi je padel nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Torej v dvanajstem mesecu, ki je mesec adár, na trinajsti dan istega, ko sta se kraljeva zapoved in njegov odlok približala izvršitvi, na dan, ko so sovražniki Judov upali, da bodo imeli oblast nad njimi (čeprav je bilo to obrnjeno ravno nasprotno, da so Judje vladali nad tistimi, ki so jih sovražili),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'so se Judje zbrali skupaj v svojih mestih, po vseh provincah kralja Ahasvérja, da položijo roko na tiste, ki so iskali njihovo bolečino in noben človek se jim ni mogel zoperstaviti, kajti strah pred njimi je padel na vse ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Vsi vladarji provinc, poročniki, namestniki in kraljevi častniki, so pomagali Judom, ker je nanje padel strah pred Mordohajem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Kajti Mordohaj je bil velik v kraljevi hiši in njegova slava je šla po vseh provincah, kajti ta mož Mordohaj je postajal večji in večji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Tako so Judje vse svoje sovražnike udarili z udarcem meča, pokolom in uničenjem. Tistim pa, ki so jih sovražili, so storili, kar so hoteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'V palači Suze so Judje usmrtili in uničili petsto mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Paršandáta, Dalfóna, Aspáta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poráta, Adaljája, Aridáta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmášta, Arisája, Aridája, Jezáta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'deset sinov Hamedátovega sina Hamána, sovražnika Judov, so usmrtili, toda na plen niso položili svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Na ta dan je bilo število tistih, ki so bili umorjeni v palači Suze, privedeno pred kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Kralj je kraljici Esteri rekel: »Judje so umorili in uničili petsto mož v palači Suze in deset Hamánovih sinov. Kaj so storili v preostalih kraljevih provincah? Torej kaj je tvoja prošnja? In ta ti bo zagotovljena. Ali kaj je tvoja nadaljnja zahteva? In ta bo storjena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Potem je Estera rekla: »Če to ugaja kralju, naj bo to zagotovljeno Judom, ki so v [mestu] Suze, da prav tako storijo jutri, glede na odlok današnjega dne in naj bo Hamánovih deset sinov obešenih na vislice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Kralj je zapovedal, da naj bo tako storjeno. Odlok je bil izdan v [mestu] Suze in obesili so Hamánovih deset sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Kajti Judje, ki so bili v [mestu] Suze, so se zbrali skupaj tudi na štirinajsti dan meseca adárja in v [mestu] Suze usmrtili tristo mož. Toda na plen niso položili svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Tudi drugi Judje, ki so bili v kraljevih provincah, so se zbrali skupaj in stali za svoja življenja in imeli počitek pred svojimi nasprotniki in jih izmed svojih sovražnikov usmrtili petinsedemdeset tisoč, toda svojih rok niso položili na plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Na trinajsti dan meseca adárja in na štirinajsti dan istega so počivali in to naredili za dan praznovanja in veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Toda Judje, ki so bili v [mestu] Suze zbrani skupaj na njegov trinajsti dan in na njegov štirinajsti in na petnajsti dan istega, so počivali in to naredili za dan praznovanja in veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Zato so Judje po vaseh, ki prebivajo v mestih brez obzidja, naredili štirinajsti dan meseca adárja za dan veselja in praznovanja in dober dan in pošiljanja deležev drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mordohaj je napisal te stvari in poslal pisma vsem Judom, ki so bili po vseh provincah Kralja Ahasvérja, tako bližnjim kakor daljnim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'da to utrdi med njimi, da naj letno ohranjajo štirinajsti dan meseca adárja in petnajsti dan istega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'kakor dneva, na katera so Judje počivali pred svojimi sovražniki in mesec, ki je bil obrnjen k njim, od bridkosti v radost in od žalovanja v dober dan, da si bodo lahko pripravili dneve praznovanja in radosti in pošiljanja deležev drug drugemu in daril ubogim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Judje so se lotili, da storijo, kakor so začeli in kakor jim je Mordohaj zapisal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'ker je Hamán, Hamedátov sin, Agágovec, sovražnik vseh Judov, zoper Jude zasnoval, da jih uniči in vrgel pur, to je žreb, da jih ugonobi in da jih uniči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'toda ko je Estera prišla pred kralja, je ta s pismi zapovedal, da naj se njegov zlobni naklep, ki ga je zasnoval zoper Jude, vrne na njegovo lastno glavo in da naj bodo on in njegovi sinovi obešeni na vislice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Zato so ta dneva imenovali purim, po imenu pur. Zato so – po vseh besedah tega pisma in od tega, kar so videli glede te zadeve in kar je prišlo k njim –');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Judje odredili in vzeli nase in na svoje potomstvo in na vse tiste, ki so se jim pridružili, tako da to ne bi prešlo, da bodo vsako leto ta dva dneva ohranjali glede na njihovo pisanje in glede na njihov določeni čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'In da se bodo teh [dveh] dni spominjali in držali skozi vse rodove, vsaka družina, vsaka provinca in vsako mesto in da ta dneva purima med Judi ne bi prešla niti spomin nanju ne izgine od njihovega potomstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Potem je kraljica Estera, hči Abihájila in Juda Mordohaja, z vso oblastjo napisala, da potrjuje to drugo pismo o purimu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'In poslal je pisma vsem Judom, v sto sedemindvajset provinc Ahasvérjevega kraljestva, z besedami miru in resnice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'da potrdi ta [dva] dneva purima, na njun določeni čas, glede na to, kakor sta jima Jud Mordohaj in kraljica Estera predpisala in kakor so odredili zase in za svoje potomstvo zadeve posta in njihovega joka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Esterin odlok je potrdil te stvari o purimu in to je bilo zapisano v knjigo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Kralj Ahasvér je naložil davek deželi in morskim otokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Vsa dejanja njegove oblasti, njegove moči in razglas Mordohajeve veličine, kamor ga je kralj napredoval, mar niso zapisana v kroniški knjigi kraljev Medije in Perzije?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Kajti Jud Mordohaj je bil drugi za kraljem Ahasvérjem in velik med Judi in sprejet od množice svojih bratov, prizadevajoč si za blagostanje svojega ljudstva in govoril je mir vsemu svojemu semenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Bil je mož v deželi Uc, katerega ime je bilo Job, in ta mož je bil popoln in iskren in nekdo, ki se je bal Boga in se ogibal zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Tam se mu je rodilo sedem sinov in tri hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Njegovo imetje je bilo tudi sedem tisoč ovc, tri tisoč kamel, petsto jarmov volov, petsto oslic in zelo velika družina, tako da je bil ta človek največji izmed vseh mož vzhoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Njegovi sinovi so šli in praznovali v svojih hišah vsak svoj dan. Poslali so in dali poklicati svoje tri sestre, da jedo in pijejo z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Bilo je tako, da ko so se dnevi njihovega praznovanja iztekli, je Job poslal, jih posvečeval in vstajal zgodaj zjutraj ter daroval žgalne daritve glede na število njih vseh, kajti Job je rekel: »Morda so moji sinovi grešili in v svojih srcih prekleli Boga.« Tako je Job nenehno delal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Bil je torej dan, ko so prišli Božji sinovi, da se pokažejo pred Gospodom in tudi Satan je prišel med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Gospod je rekel Satanu: »Od kod prihajaš?« Nató je Satan odgovoril Gospodu in rekel: »Od potikanja sem ter tja po zemlji in od hoje gor in dol po njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Gospod je rekel Satanu: »Si kaj preudaril [o] mojem služabniku Jobu, ker na zemlji ni nikogar podobnega njemu; popoln in pošten človek je, ki se boji Boga in se ogiblje zla?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Potem je Satan odgovoril Gospodu in rekel: »Mar se Job zastonj boji Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Mar nisi ti naredil ograje okoli njega, okoli njegove hiše in okoli vsega, kar ima na vsaki strani? Blagoslovil si delo njegovih rok in njegovo imetje se je povečalo v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Toda iztegni sedaj svojo roko in se dotakni vsega, kar ima in preklinjal te bo v tvoj obraz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Gospod je rekel Satanu: »Glej, vse, kar ima, je v tvoji oblasti, samo nanj ne iztegni svoje roke.« Tako je Satan odšel izpred Gospodove prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Bil je dan, ko so njegovi sinovi in njegove hčere jedli in pili vino v hiši njihovega najstarejšega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'K Jobu je prišel poslanec in rekel: »Voli so orali in osli so se pasli poleg njih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'in Sabejci so padli nadnje ter jih odvlekli proč. Da, z ostrino meča so umorili služabnike in samo jaz sam sem pobegnil, da ti povem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Medtem ko je še govoril, je prišel še drugi in rekel: »Ogenj od Boga je padel z neba in sežgal ovce in služabnike, jih použil in samo jaz sam sem pobegnil, da ti povem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Medtem ko je še govoril, je prišel še drugi in rekel: »Kaldejci so postavili tri čete in vpadli na kamele in jih odvedli proč. Da, in z ostrino meča umorili služabnike in samo jaz sam sem pobegnil, da ti povem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Medtem ko je še govoril, je prišel še drugi in rekel: »Tvoji sinovi in tvoje hčere so jedli in pili vino v hiši njihovega najstarejšega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Glej, iz divjine je prihrumel mogočen veter in udaril štiri vogale hiše in ta je padla na mladeniče in ti so mrtvi. Samo jaz sam sem pobegnil, da ti povem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Potem je Job vstal, raztrgal svoje ogrinjalo, obril svojo glavo, padel dol na tla in oboževal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'ter rekel: »Nag sem prišel iz maternice svoje matere in nag se bom vrnil tja. Gospod je dal in Gospod je vzel. Blagoslovljeno bodi Gospodovo ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'V vsem tem Job ni grešil niti ni nespametno obdolžil Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Ponovno je bil dan, ko so prišli Božji sinovi, da se predstavijo pred Gospodom in tudi Satan je prišel med njimi, da se predstavi pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Gospod je rekel Satanu: »Od kod prihajaš?« Satan je Gospodu odgovoril in rekel: »Od potikanja sem ter tja po zemlji in od hoje gor in dol po njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Gospod je rekel Satanu: »Si preudaril [o] mojem služabniku Jobu, da tam ni nikogar podobnega njemu na zemlji? Popoln in iskren človek je, nekdo, ki se boji Boga in se ogiblje zla. Še vedno se trdno drži svoje neokrnjenosti, čeprav me spodbujaš zoper njega, da bi ga uničil brez razloga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satan je Gospodu odgovoril in rekel: »Kožo za kožo, da, vse, kar človek ima, bo dal za svoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Toda iztegni sedaj svojo roko in se dotakni njegove kosti in njegovega mesa in preklel te bo v tvoj obraz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Gospod je rekel Satanu: »Glej, on je v tvoji roki, toda ohrani njegovo življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Tako je Satan odšel izpred Gospodove prisotnosti in Joba udaril s hudimi tvori od podplata njegovega stopala do njegovega temena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Ta si je vzel črepinjo, se strgal z njo in se usedel med pepel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Potem mu je njegova žena rekla: »Mar še vedno ohranjaš svojo neokrnjenost? Prekolni Boga in umri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Toda rekel ji je: »Govoriš kot govori ena izmed nespametnih žensk. Kaj? Dobro smo sprejeli iz Božje roke, pa ne bi sprejeli hudega?« V vsem tem Job s svojimi ustnicami ni grešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Torej ko so Jobovi trije prijatelji slišali o vsem tem zlu, ki je prišlo nadenj, so prišli, vsak iz svojega lastnega kraja: Elifáz Temánec, Bildád Suhéjec in Cofár Naámčan, kajti skupaj so se dogovorili, da pridejo in da žalujejo z njim in da ga tolažijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Ko pa so od daleč povzdignili svoje oči in ga niso spoznali, so povzdignili svoj glas ter zajokali. Vsak izmed njih je pretrgal svoje ogrinjalo in proti nebu so potresli prah na svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Tako so sedeli z njim na tleh sedem dni in sedem noči in nihče mu ni spregovoril niti besede, kajti videli so, da je bila njegova žalost zelo velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Po tem je Job odprl svoja usta in preklel svoj dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Job je spregovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '»Naj izgine dan, na katerega sem bil rojen in noč, v kateri je bilo rečeno: ›Tukaj je spočet fantek.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Naj bo ta dan tema. Naj ga Bog od zgoraj ne upošteva niti naj svetloba ne sije nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Naj ga tema in smrtna senca omadežujeta. Naj oblak prebiva nad njim. Naj ga straši črnina dneva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Glede tiste noči naj se je polasti tema. Naj ta ne bo pridružena dnevom leta, naj ta ne pride v število mesecev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Glej, naj bo ta noč osamljena, naj noben radosten glas ne pride vanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, '§ Naj jo prekolnejo tisti, ki preklinjajo dan, ki so pripravljeni dvigniti svoje žalovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Naj bodo zvezde njene polteme temne; naj oprezujejo za svetlobo, toda nimajo nobene niti naj ne zagledajo jutranjega svitanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'ker ta ni zaprla vrat maternice moje matere niti pred mojimi očmi ni skrila bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Čemu nisem umrl v maternici? Zakaj nisem izročil duha, ko sem prišel iz trebuha?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Zakaj sem bil [vzet na] kolena? Ali zakaj [na] prsi, da bi sesal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Kajti sedaj bi mirno ležal in bi bil tiho; spal bi. Potem bi počival');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 's kralji in svetovalci zemlje, ki so zapuščene kraje gradili zase,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'ali s princi, ki so imeli zlato, ki so svoje hiše napolnjevali s srebrom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'ali ne bi bil kakor prezgodnji porod, kakor otročiči, ki nikoli niso videli svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tam zlobni odnehajo od nadlegovanja in tam bodo izmučeni pri počitku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Tam jetniki počivajo skupaj. Oni ne poslušajo glasu zatiralca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Majhni in veliki so tam in služabnik je prost pred svojim gospodarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, '§ Zakaj je svetloba dana tistemu, ki je v bedi in življenje zagrenjenemu v duši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'ki hrepeni po smrti, toda ta ne prihaja in koplje za njo bolj kakor za skritimi zakladi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'ki se silno razveseljujejo in so veseli, ko lahko najdejo grob?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Zakaj je svetloba dana možu, čigar pot je skrita in katerega je Bog ogradil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Kajti moje vzdihovanje prihaja preden jem in moja rjovenja so izlita ven kakor vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Kajti stvar, ki sem se je silno bal, je prišla nadme in to, česar sem se bal, je prišlo k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Nisem bil na varnem niti nisem imel počitka niti nisem bil tiho, vendar je težava prišla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Potem je Elifáz Temánec odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '» Če se poskušamo posvetovati s teboj, ali boš užaloščen? Toda kdo se lahko vzdrži pred govorjenjem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Glej, mnoge si poučeval in okrepil si šibke roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tvoje besede so podpirale tistega, ki je padal in krepil si slabotna kolena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Toda sedaj je to prišlo nadte in ti slabiš; dotika se te in si zaskrbljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Mar ni to tvoj strah, tvoje zaupanje, tvoje upanje in poštenost tvojih poti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Spomni se, prosim te, kdo se je kdajkoli pogubil, pa je bil nedolžen? Ali kje so bili pravični odsekani?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Celo kakor sem jaz videl, tisti, ki orjejo krivičnost in sejejo zlobnost, isto [tudi] požanjejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Z Božjim udarcem umrejo in z dihom njegovih nosnic so použiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Rjovenje leva, glas krutega leva in zobje mladih levov so zlomljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Star lev gine zaradi pomanjkanja plena, mladiči arogantnega leva pa so razkropljeni naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Torej stvar je bila na skrivnem privedena k meni in moje uho je nekaj tega sprejelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'V mislih od nočnih videnj, ko na človeka pade globoko spanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'je strah prišel nadme in trepetanje, kar je vsem mojim kostem povzročilo, da so se tresle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Potem je duh zdrsnil mimo mojega obraza, dlake mojega mesa so se naježile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Ta je mirno stal, toda nisem mogel razločiti njegove oblike. Podoba je bila pred mojimi očmi, tam je bila tišina in zaslišal sem glas, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '›Ali bo smrten človek pravičnejši kakor Bog? Ali bo človek čistejši kakor njegov stvarnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, '§ Glej, nobenega zaupanja ne polaga v svoje služabnike in njegovi angeli so zadolženi z neumnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Kako veliko manj v tiste, ki prebivajo v ilnatih hišah, katerih temelj je prah, ki so zdrobljene pred moljem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Uničeni so od jutra do večera, pogubljajo se na veke, ne da bi se kdorkoli oziral na to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Mar ni njihova odličnost, ki je v njih, odšla proč? Umirajo, celo brez modrosti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '»Sedaj kliči, če bo tam kdorkoli, ki ti bo odgovoril. H kateremu izmed svetih se boš obrnil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, '§ Kajti bes ubija nespametnega človeka in zavist ubija neumnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Videl sem nespametnega, da se ukoreninja, toda nenadoma sem preklel njegovo prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Njegovi otroci so daleč od varnosti in zdrobljeni so pri velikih vratih niti tam ni nikogar, da jih osvobodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, '§ Katerega žetev pojedo lačni in jo pobirajo celo iz trnja in ropar požira njihovo imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Čeprav stiska ne prihaja iz prahu niti težava ne poganja iz tal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, '§ vendar je človek rojen za stisko, kakor iskrice letijo navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Iskal bi Boga in Bogu bi izročil svojo zadevo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'ki dela velike stvari in nedoumljive, čudovite stvari brez števila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'ki daje dež na zemljo in vode pošilja na polja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'da tiste, ki so nizki, postavi visoko; da bi tisti, ki žalujejo, lahko bili povišani do varnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'On razočara naklepe prebrisanega, tako da njihove roke ne morejo opravljati svoje podjetnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Modre jemlje v njihovi prebrisanosti in nasvet kljubovalnega je naglo izvršen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Srečajo se s temo podnevi in tipajo opoldan kakor ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Toda on rešuje ubogega pred mečem, pred njihovimi usti in pred roko mogočnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Tako ima ubogi upanje in krivičnost ustavlja svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Glej, srečen je človek, ki ga Bog graja, zatorej ne preziraj karanja Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Kajti on dela rane in jih povezuje, on ranja in njegove roke ozdravljajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Osvobodil te bo v šestih težavah. Da, v sedmi se te nobeno zlo ne bo dotaknilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'V lakoti te bo odkupil pred smrtjo in v vojni pred močjo meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Skrit boš pred bičanjem jezika niti se ne boš bal uničenja, kadar to prihaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Ob uničenju in lakoti se boš smejal niti se ne boš bal zemeljskih zveri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Kajti v zavezi boš s kamni polja in poljske zveri bodo v miru s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Vedel boš, da bo tvoj šotor v miru in obiskal boš svoje prebivališče in ne boš grešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Vedel boš tudi, da bo tvojega semena veliko in tvojega potomstva kakor trave zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'K svojemu grobu boš prišel v polni starosti, podobno kakor kopica žita prihaja v svojem obdobju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Glej to, mi smo to preiskali, tako je to. Poslušaj to in spoznaj to v svoje dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Toda Job je odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '»Oh, da bi bila moja žalost temeljito stehtana in moja katastrofa skupaj položena na tehtnico!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Kajti sedaj bi bila ta težja kakor morski pesek. Zato so moje besede požrte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Kajti puščice Vsemogočnega so znotraj mene, njihov strup vpija mojega duha. Strahote od Boga se postrojujejo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Mar divji osel riga, kadar jé travo? Mar muka vol nad svojo krmo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Mar se lahko to, kar je neokusno, jé brez soli? Ali je sploh kaj okusa v jajčnem beljaku?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Stvari, ki se jih moja duša ni hotela dotikati, so kakor moja hrana žalosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oh, da bi lahko imel svojo zahtevo in da bi mi Bog zagotovil stvar, po kateri hrepenim!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Celo da bi to ugajalo Bogu, da me uniči, da bi popustil svojo roko in me odrezal!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Potem bi vendar imel tolažbo; da, otrdil bi se v bridkosti. Naj mi ne prizanese, kajti nisem prikrival besed Svetega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Kaj je moja moč, da bi upal? Kaj je moj konec, da bi podaljšal svoje življenje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Mar je moja moč moč kamnov? Ali je moje meso iz brona?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Mar ni moja pomoč v meni? In ali je modrost popolnoma pregnana od mene?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Tistemu, ki peša, naj bi bilo izkazano usmiljenje od njegovega prijatelja, toda on zapušča strah Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Moji bratje so varljivo postopali kakor potok in kakor tok potokov so prešli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'ki so potemneli zaradi razloga ledu in na katerih je skrit sneg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Kadar se ogrejejo, izginejo. Ko je vroče, so použiti iz svojega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Steze njihove poti so obrnjene stran; gredo v nič in izginejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Krdela iz Temá so gledala, skupine iz Sabe so čakale nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Zbegani so bili, ker so upali. Prišli so tja in bili osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Kajti sedaj ste nič, vidite moje zavračanje in ste prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Mar sem rekel: ›Prinesite k meni?‹ ali ›Dajte mi nagrado iz svojega imetja?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'ali: ›Osvobodite me pred sovražnikovo roko?‹ ali ›Odkupite med pred roko mogočnega?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Účite me in držal bom svoj jezik in dajte mi razumeti, kje sem se motil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kako prepričljive so prave besede! Toda kaj vaše razpravljanje ošteva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Mar si domišljate, da grajate besede in govore tistega, ki je obupan, ki so kakor veter?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Da, vi nadvladate osirotelega in kopljete jamo za svojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Zdaj torej bodite zadovoljni. Poglejte name, kajti to vam je očitno, če lažem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Vrnite se, prosim vas, naj to ne bo krivičnost. Da, ponovno se vrnite, moja pravičnost je v tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Mar je na mojem jeziku krivičnost? Ne more moj okus razločevati sprevrženih stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Mar ni določen čas za človeka na zemlji? Mar niso njegovi dnevi prav tako podobni najemnikovim dnevom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Kakor si služabnik iskreno želi sence in kakor najemnik gleda za nagrado svojega dela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'tako sem prisiljen, da posedujem mesece ničnosti in naporne noči so mi določene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Ko se uležem, rečem: ›Kdaj bom vstal in bo noč minila? Poln sem premetavanja sem ter tja do jutranjega svitanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Moje meso je pokrito z ličinkami in grudami prahu; moja koža je razpokana in postala je gnusna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Moji dnevi so bolj nagli kakor tkalski čolniček in preživeti so brez upanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Oh, spomnite se, da je moje življenje veter. Moje oko ne bo več videlo dobrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Oko tistega, ki me je videlo, me ne bo več videlo. Tvoje oči so na meni, mene pa ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, '§ Kakor je oblak použit in izginil proč, tako kdor gre dol h grobu, ne bo več prišel gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Ne bo se več vrnil k svojemu domu niti ga njegov kraj ne bo več poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Zato ne bom zadrževal svojih ust; govoril bom v tesnobi svojega duha, pritoževal se bom v grenkobi svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, '§ Mar sem morje ali kit, da ti postavljaš stražo nad menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Ko rečem: ›Moja postelja me bo tolažila, moje ležišče bo lajšalo mojo pritožbo,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'takrat me ti strašiš s sanjami in me prek videnj spravljaš v grozo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'tako da moja duša raje izbira dušenje in smrt, kakor pa moje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'To se mi gabi. Ne bi hotel živeti večno. Pustite me samega, kajti moji dnevi so ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Kaj je človek, da bi ga ti poveličeval? In da bi svoje srce naravnal nanj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Da bi ga ti obiskoval vsako jutro in ga preizkušal vsak trenutek?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Kako dolgo ne boš odšel od mene niti me ne boš pustil samega, dokler ne pogoltnem svoje sline?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Grešil sem. Kaj ti bom storil, oh ti, varuh ljudi? Zakaj si me postavil kakor znamenje zoper tebe, tako da sem breme samemu sebi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Zakaj ne odpustiš mojega prestopka in ne odvzameš moje krivičnosti? Kajti sedaj bom spal v prahu in iskal me boš zjutraj, toda mene ne bo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Potem je odgovoril Bildád Suhéjec in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '»Doklej boš govoril te stvari? In kako dolgo bodo besede iz tvojih ust podobne močnemu vetru?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Mar Bog izkrivlja sodbo? Mar Vsemogočni izkrivlja pravico?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Če so tvoji otroci grešili zoper njega in jih je zavrgel zaradi njihovega prestopka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'če hočeš zgodaj iskati Boga in narediti ponižno prošnjo Vsemogočnemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'če bi bil ti čist in pravičen, bi se on sedaj zaradi tebe zagotovo prebudil in prebivališče tvoje pravičnosti naredil uspešno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Čeprav je bil tvoj začetek majhen, bi vendar tvoj zadnji konec silno narasel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Kajti poizvedi, prosim te, o prejšnjem času in se pripravi, da preiskuješ o njihovih očetih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(kajti mi smo samo od včeraj in ne vemo nič, ker so naši dnevi na zemlji senca).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Mar te ne bodo poučili in ti povedali in izustili besed iz svojega srca?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Mar lahko loček zraste brez blata? Mar lahko perunika raste brez vode?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Medtem ko je še v svojem zelenju in ni odtrgana, ovene pred katerimkoli drugim zeliščem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Takšne so steze vseh, ki pozabljajo Boga in upanje hinavca bo propadlo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'katerega upanje bo odrezano, katerega trdno upanje bo pajkova mreža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Naslonil se bo na svojo hišo, toda ta ne bo obstala; trdno jo bo držal, toda ta ne bo zdržala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Zelen je pred soncem in njegova veja poganja v njegovem vrtu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Njegove korenine so ovite okoli kupa in strmi na kraj kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Če ga uniči iz svojega kraja, potem ga bo ta zatajil, rekoč: ›Nisem te videl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Glej, to je radost njegove poti in iz zemlje bodo pognali drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Glej, Bog ne bo zavrnil popolnega moža niti ne bo pomagal hudodelcem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'dokler tvojih ust ne napolni s smehom in tvojih ustnic z radostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Tisti, ki te sovražijo, bodo oblečeni s sramoto in bivališče zlobnega bo prišlo v nič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Potem je Job odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '»Vem, to je tako res. Toda kako bi človek mogel biti pravičen z Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Če se hoče pričkati z njim, mu ne more odgovoriti eno od tisočih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'On je moder v srcu in mogočen v moči; kdo se je utrdil zoper njega in je uspel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Ki odstranja gore in ne vedo, ki jih prevrača v svoji jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Ki trese zemljo iz njenega kraja in njeni stebri trepetajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Ki zapoveduje soncu in ta ne vzhaja in pečati zvezde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Ki sam razprostira nebo in stopa po valovih morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Ki dela Arktur, Orion, Gostosevce in južne sobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Ki dela velike stvari neodkrite, da, in čudeže brez števila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Glej! Hodi poleg mene, jaz pa ga ne vidim; gre tudi naprej, toda jaz ga ne zaznavam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Glej, odvzema, kdo ga lahko ovira? Kdo mu bo rekel: ›Kaj delaš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Če Bog ne bo umaknil svoje jeze, se ponosni pomočniki sklonijo pod njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Kako mnogo manj bi mu jaz mogel odgovoriti in izbrati svoje besede, da razpravljam z njim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Kateremu, čeprav bi bil pravičen, vendar ne bi mogel odgovoriti, temveč bi naredil ponižno prošnjo svojemu sodniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Če sem klical in mi je odgovoril, vendar ne bi verjel, da je prisluhnil mojemu glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Kajti lomi me z viharjem in brez razloga množi moje rane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Ne bo mi pustil, da zajamem sapo, temveč me napolnjuje z grenkobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Če govorim o moči, glej, on je močan, če pa o sodbi, kdo mi bo določil čas zagovarjanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Če jaz sebe opravičim, me bodo moja lastna usta obsodila. Če rečem: ›Jaz sem popoln,‹ se bo izkazalo, da sem sprevržen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Čeprav bi bil popoln, vendar ne bi poznal svoje duše; preziral bi svoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'To je ena stvar, zato sem rekel to: ›On uničuje popolnega in zlobnega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Če nadloga nenadoma ubije, se bo posmehoval ob sojenju nedolžnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Zemlja je dana v roko zlobnega. On zakriva obličja njenih sodnikov. Če ne, kje in kdo je on?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Torej moji dnevi so hitrejši kakor tekač. Odletijo proč, ničesar dobrega ne vidijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Minili so kakor nagle ladje, kakor orel, ki hiti k plenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Če rečem: ›Pozabil bom svojo pritožbo, prenehal bom s svojo potrtostjo in se potolažil,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'se bojim vseh svojih bridkosti, vem, da me ne boš imel za nedolžnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Če sem zloben, zakaj se potem trudim zaman?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Če se umijem s snežnico in svoje roke naredim čiste kot še nikoli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'me boš vendar pahnil v jarek in moja lastna oblačila me bodo prezirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Kajti on ni človek, kakor sem jaz, da bi mu odgovoril in bi skupaj prišla na sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Niti ni tukaj kakršnegakoli razsodnika med nama, da bi lahko svojo roko položil na naju oba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Naj svojo palico vzame od mene in naj me njegov strah ne straši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Potem bi govoril in se ga ne bi bal, toda z menoj ni tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Moji duši se gnusi moje življenje. Svojo pritožbo bom pustil nad seboj; govoril bom v grenkobi svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Bogu bom rekel: ›Ne obsodi me. Razloži mi, zakaj se pričkaš z menoj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Mar ti je dobro, da bi zatiral, da bi preziral delo svojih rok in bi sijal nad nasvetom zlobnega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Imaš mesene oči? Mar vidiš, kakor vidi človek?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'So tvoji dnevi kakor dnevi človeka? So tvoja leta kakor človeški dnevi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'da poizveduješ za mojo krivičnostjo in preiskuješ za mojim grehom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ti veš, da nisem zloben in nikogar ni, ki lahko osvobodi iz tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tvoje roke so me naredile in me oblikovale skupaj na vsaki strani, vendar si me uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Spomni se, rotim te, da si me naredil kakor ilo, ti pa me hočeš ponovno privesti v prah?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Mar me nisi iztočil kakor mleko in me strdil kakor sir?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Oblekel si me s kožo in mesom in me obdal s kostmi in kitami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Zagotovil si mi življenje in naklonjenost in tvoje obiskovanje je ohranilo mojega duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Te stvari si skril v svojem srcu, vem, da je to s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Če grešim, potem me zaznamuješ in me ne boš oprostil pred mojo krivičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Če bi bil zloben, gorje meni. Če bi bil pravičen kljub temu ne bi dvignil svoje glave. Poln zmedenosti sem, zato poglej mojo stisko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, '§ kajti ta narašča. Loviš me kakor krut lev in se ponovno kažeš čudovitega nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Zoper mene obnavljaš svoje pričevanje in nad menoj povečuješ svoje ogorčenje. Spremembe in vojna so zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Zakaj si me potem privedel ven iz maternice? Oh, da bi izročil duha in me nobeno oko ne bi videlo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Bil bi kakor, če me ne bi bilo, od maternice bi bil odnesen v grob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Mar ni mojih dni malo? Odnehaj torej in me pusti samega, da se malo potolažim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'preden grem, od koder se ne bom vrnil, celó v deželo teme in smrtne sence,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'deželo teme kakor tema sama in smrtne sence, brez kakršnegakoli reda in kjer je svetloba kakor tema.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Potem je odgovoril Cofár Naámčan in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '»Mar ne bo množica besed odgovorjena? Mar naj bo mož, poln govora, opravičen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Mar naj tvoje laži naredijo možem, da molčijo? In ko zasmehuješ, ali te noben človek ne bo osramotil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Kajti rekel si: ›Moj nauk je čist in jaz sem čist v tvojih očeh.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Toda oh, da bi Bog spregovoril in zoper tebe odprl svoje ustnice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'in da bi ti pokazal skrivnosti modrosti, da so dvojne temu kar je! Vedi torej, da Bog od tebe terja manj, kakor zasluži tvoja krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Mar lahko z iskanjem najdeš Boga? Mar lahko do popolnosti spoznaš Vsemogočnega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'To je tako visoko kakor nebo. Kaj lahko storiš? Globlje kakor pekel. Kaj lahko spoznaš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, '§ Njegova mera je daljša kakor zemlja in širša kakor morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Če odseka in zapre, ali zbere skupaj, kdo ga potem lahko ovira?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Kajti pozna praznoglave ljudi. Tudi zlobnost vidi. Mar ne bo potem tega preudaril?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Kajti praznoglav človek bi bil moder, čeprav bi bil človek rojen kakor žrebe divjega osla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Če pripraviš svoje srce in svoje roke iztegneš k njemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'če je krivičnost v tvoji roki, jo odloži daleč proč in naj zlobnost ne prebiva v tvojih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Kajti potem boš povzdignil svoj obraz brez madeža. Da, neomajen boš in se ne boš bal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'ker boš pozabil svojo bedo in se je boš spominjal kakor vode, ki tečejo mimo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'in tvoja starost bo jasnejša kakor opoldan; svetil boš naprej, ti boš kakor jutro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Ti boš varen, ker je upanje. Da, kopal boš okoli sebe in svoj počitek si boš vzel v varnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, '§ Tudi ulegel se boš in nihče te ne bo strašil. Da, mnogi te bodo obžalovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Toda oči zlobnih bodo odpovedale in ne bodo pobegnili in njihovo upanje bo kakor izročitev duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Job je odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '»Brez dvoma ste vi samo ljudje in modrost bo umrla z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Toda jaz imam razumevanje prav tako kakor vi. Nisem slabši od vas. Da, kdo ne pozna takšnih stvari, kakor so te?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Jaz sem kakor nekdo, zasmehovan od svojega bližnjega, ki kliče k Bogu in ta mu odgovarja. Pravičen človek je zasmehovan do norčevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, '§ Kdor je pripravljen, da zdrsne s svojimi stopali, je kakor svetilka, prezirana v mislih tistega, ki je ohol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Šotori roparjev uspevajo in tisti, ki izzivajo Boga, so varni; v katerih roko Bog obilno prinaša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Toda vprašaj sedaj živali in te bodo poučile in perjad neba in ti bodo povedale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Ali govori zemlji in te bo poučila in morske ribe ti bodo oznanile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kdo v vsem tem ne spoznava, da je to naredila Gospodova roka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'V čigar roki je duša vsake žive stvari in dih vsega človeštva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Mar uho ne preizkuša besed? In usta ne okusijo njegove hrane?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'S starcem je modrost, in v dolžini dni razumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Z njim je modrost in moč, on ima nasvet in razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Glej, on poruši in to ne more biti ponovno zgrajeno. On zapre človeka in ne more biti odpiranja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Glej, on zadržuje vode in se posušijo. On jih prav tako pošilja ven in razrijejo zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Z njim je moč in modrost; prevarani in slepar sta njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Svetovalce odvede oplenjene in sodnike dela bedake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Kraljem razvezuje vez in njihova ledja opasuje s pasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, '§ Prince odvede oplenjene in podira močne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Odstranja govor zanesljivih in odvzema razumnost ostarelih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Na prince izliva zaničevanje in slabi moč močnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Odkriva globoke stvari teme in na svetlobo prinaša smrtno senco.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Povečuje narode in jih uničuje. Razširja narode in jih ponovno vodi v suženjstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Odvzema srce vodjem ljudstva zemlje in jim povzroča, da tavajo v divjini, kjer ni poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Tipajo v temi brez svetlobe in on jim povzroča, da se opotekajo kakor pijan človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Glej, moje oko je vse to videlo, moje uho je to slišalo in razumelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Kar veste vi, isto vem tudi jaz. Nisem slabši od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Zagotovo bi govoril Vsemogočnemu in želim si, da bi razpravljal z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Toda vi ste ponarejevalci laži, vi vsi ste zdravniki brez vrednosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Oh, da bi vsi skupaj molčali! To bi bila vaša modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Poslušajte torej moje zagovarjanje in prisluhnite prošnjam mojih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Mar boste zlobno govorili za Boga? In varljivo govorili zanj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Mar boste sprejeli njegovo osebo? Mar se boste potegovali za Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Ali je dobro, da bi vas on preiskal? Ali kakor en človek zasmehuje drugega ali tako vi zasmehujete njega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Zagotovo vas bo grajal, če naskrivaj sprejemate osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Mar vas ne bo njegova odličnost prestrašila? In njegova groza padla na vas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vaši spomini so podobni pepelu, vaša telesa ilovnatim telesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Molčite, pustite me samega, da lahko govorim in naj pride name kar hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Čemu jemljem svoje meso v svoje zobe in svoje življenje polagam v svojo roko?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Čeprav me ubije, bom jaz vendar zaupal vanj; toda svoje lastne poti bom ohranil pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'On bo tudi rešitev moje duše, kajti hinavec ne bo prišel predenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Marljivo prisluhnite mojemu govoru in moji izjavi s svojimi ušesi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Glejte torej, zapovedal sem svojo stvar; vem, da bom opravičen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kdo je tisti, ki se bo pravdal z menoj? Kajti sedaj, če zadržim svoj jezik, bom izročil duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Samo ne storite mi dveh stvari, potem se ne bom skril pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Umakni svojo roko daleč od mene in naj me tvoja groza ne stori prestrašenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Potem kliči in jaz ti bom odgovoril. Ali naj jaz govorim in ti mi odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Kako številne so moje krivičnosti in grehi? Naredi mi, da spoznam svoj prestopek in svoj greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Zakaj skrivaš svoj obraz in me šteješ za svojega sovražnika?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Hočeš zlomiti list, gnan sem ter tja? Hočeš zasledovati suho strnišče?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Kajti zoper mene pišeš grenke stvari in me delaš, da posedujem krivičnosti svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Moja stopala polagaš v klade in ozko gledaš na vse moje steze. Odtis postavljaš na pete mojih stopal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'In on, kakor razpadajoča stvar, požira kakor obleko, ki je pojedena od molja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Človek, ki je rojen iz ženske, je malo-dneven in poln težav,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'poganja kakor cvet in je odtrgan, odleti tudi kakor senca in ne nadaljuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Mar odpiraš svoje oči nad takšnim in me s seboj vodiš na sodbo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kdo lahko privede čisto stvar iz nečiste? Niti en.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Ker so njegovi dnevi določeni, je število njegovih mesecev s teboj; ti si določil njegove meje, ki jih ne more prestopiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Obrni se od njega, da lahko počiva, dokler svojega dneva ne bo dovršil kakor najemnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Kajti upanje je za drevo, če je posekano, da bo ponovno pognalo in da njegove nežne veje ne bodo odnehale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Čeprav se njegova korenina v zemlji postara in njegov štor umre v zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'vendar preko vonja vode vzbrsti in požene veje kakor rastlina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Toda človek umre in obleži. Da, človek izroči duha in kje je?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Kakor vode izhlapevajo iz morja in se poplava izsušuje in posuši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'tako se človek uleže in ne vstane. Dokler ne bo več neba, se ne bodo prebudili niti ne bodo dvignjeni iz svojega spanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Oh, da bi me hotel skriti v grob, da bi me varoval na skrivnem, dokler tvoj bes ne mine, da bi mi določil določeni čas in me spomnil!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Če človek umre, mar bo ponovno živel? Vse dni svojega določenega časa bom čakal, dokler ne pride moja sprememba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Klical boš in jaz ti bom odgovoril; imel boš željo po delu svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Kajti sedaj šteješ moje korake. Mar ne paziš nad mojim grehom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Moj prestopek je zapečaten v mošnji in ti zašiješ mojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Zagotovo padajoča gora pride v nič in skala je odstranjena iz svojega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Vode brusijo kamne. Ti izpiraš stvari, ki rastejo ven iz zemeljskega prahu in ti uničuješ upanje človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Na veke prevladuješ zoper njega in on premine. Spreminjaš njegovo obličje in ga pošiljaš proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Njegovi sinovi so prišli v čast in on tega ne ve. Ponižani so, toda tega ne zaznava o njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Toda njegovo meso na njem bo imelo bolečino in njegova duša znotraj njega bo žalovala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Potem je odgovoril Elifáz Temánec in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '»Mar naj moder človek izreka prazno znanje in svoj trebuh napolnjuje z vzhodnikom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Mar naj razpravlja z nekoristnim govorjenjem? Ali z govori, s katerimi ne more storiti ničesar dobrega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Da, ti zametuješ strah in zadržuješ molitev pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Kajti tvoja usta izrekajo tvojo krivičnost in ti izbiraš jezik prebrisanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Tvoja lastna usta te obsojajo in ne jaz. Da, tvoje lastne ustnice pričujejo zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Mar si ti prvi človek, ki je bil rojen? Ali si bil narejen pred hribi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Mar si slišal Božjo skrivnost? In ali sebi zadržuješ modrost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Kaj ti veš, kar mi ne vemo? Kaj razumeš, česar ni v nas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Z nami so sivolasi in zelo stari možje, precej starejši od tvojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, '§ Ali so Božje tolažbe zate majhne? Je s teboj kakršnakoli skrita stvar?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Zakaj te tvoje srce odnaša? In ob čem tvoje oči mežikajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'da svojega duha obračaš zoper Boga in takšnim besedam dopuščaš iziti iz svojih ust?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kaj je človek, da bi bil čist? In ta, ki je rojen iz ženske, da bi bil pravičen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Glej, zaupanja ne polaga v svoje svete. Da, nebo ni čisto v njegovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Kako mnogo bolj gnusen in umazan je človek, ki pije krivičnost kakor vodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Pokazal ti bom, poslušaj me. To, kar sem videl, bom oznanil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'To, kar so modri možje povedali od svojih očetov in tega niso skrili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'katerim samim je bila dana zemlja in noben tujec ni šel med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Zloben človek se muči z bolečino vse svoje dni in število let je skrito zatiralcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Grozen zvok je v njegovih ušesih. V uspevanju bo nadenj prišel uničevalec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Ne verjame, da se bo vrnil iz teme in meč čaka nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Naokoli tava za kruhom, rekoč: ›Kje je?‹ Ve, da je ob njegovi roki pripravljen dan teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Stiska in tesnoba ga bosta preplašili. Prevladali bosta zoper njega kakor kralj, pripravljen na bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Kajti svojo roko izteguje zoper Boga in se krepi zoper Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'On steče nadenj, celó na njegov vrat, na debele izbokline njegovih ščitov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'ker svoj obraz pokriva s svojo mastnostjo in na svojih ledjih nabira sloje tolšče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Prebiva v zapuščenih mestih in hišah, ki jih noben človek ne naseljuje, ki so pripravljene, da postanejo ruševine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Ne bo bogat, niti se ne bo njegovo imetje nadaljevalo, niti svoje popolnosti na zemlji ne bo podaljšal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Iz teme ne bo odšel. Plamen bo posušil njegove mladike in z dihom svojih ust bo odšel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Kdor je zaveden naj ne zaupa v ničnost, kajti ničnost bo njegovo povračilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Dovršeno bo pred njegovim časom in njegova veja ne bo zelena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Svoje nezrelo grozdje bo otresel kakor trta in svoj cvet bo odvrgel kakor oljka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Kajti skupnost hinavcev bo zapuščena in ogenj bo použil šotore podkupovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Spočenjajo vragolijo in rodijo ničnost in njihov trebuh pripravlja prevaro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Potem je Job odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '»Slišal sem mnoge takšne stvari. Vi vsi ste bedni tolažniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Mar bodo besede ničnosti imele konec? Ali kaj te opogumlja, da odgovarjaš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Tudi jaz bi lahko govoril, kakor delate vi. Če bi bila vaša duša namesto moje duše, bi lahko kopičil besede zoper vas in z glavo zmajeval nad vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Toda jaz bi vas želel okrepiti s svojimi usti in premikanje mojih ustnic bi omililo vašo žalost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Čeprav govorim, moja žalost ni zmanjšana in čeprav potrpim, koliko sem olajšan?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Toda sedaj me je naredil izmučenega. Vso mojo skupino si naredil zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Napolnil si me z gubami, ki so priča zoper mene. Moja pustost vstaja v meni in pričuje v moj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Trga me v svojem besu ta, ki me sovraži. Nad menoj škripa s svojimi zobmi. Moj sovražnik svoje oči ostri nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'S svojimi usti so zevali vame. Grajalno so me udarili na lice. Skupaj so se zbrali zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Bog me je izročil brezbožnim in me predal v roke zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Bil sem sproščen, toda razlomil me je. Prijel me je tudi za moj vrat in me stresel na koščke in me postavil za svoje znamenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Njegovi lokostrelci so me obdali naokoli, on mojo notranjost cepi narazen in ne prizanaša; moj žolč izliva na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Lomi me z vrzeljo nad vrzeljo, nadme teče kakor velikan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Sešil sem vrečevino na svoji koži in svoj rog omadeževal v prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Moj obraz je zapacan od joka in na mojih vekah je smrtna senca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'ne zaradi kakršnekoli nepravičnosti na mojih rokah. Tudi moja molitev je čista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Oh zemlja, ne pokrij moje krvi in naj moj jok nima prostora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Tudi sedaj, glej, moja priča je v nebesih in moje pričevanje je na višini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Moji prijatelji me zasmehujejo, toda moje oko izliva solze k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Oh, da bi se nekdo lahko potegoval za človeka pri Bogu, kakor se človek poteguje za svojega bližnjega!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Ko pride nekaj let, potem bom šel pot, od koder se ne bom vrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Moj dih je pokvarjen, moji dnevi so izumrli, zame so pripravljeni grobovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Mar niso tukaj z menoj zasmehovalci? Mar moje oko ne vztraja v njihovem izzivanju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Sedaj se ulezi, postavi me v poroštvo s seboj. Kdo je ta, ki bo udaril roki z menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Kajti njihovo srce si skril pred razumevanjem, zato jih ne boš povišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kdor svojim prijateljem govori prilizovanja, bodo pešale celo oči njegovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Naredil me je tudi za tarčo posmeha med ljudstvom in poprej sem bil kakor bobnič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Tudi moje oko je zatemnjeno zaradi bridkosti in vsi moji udi so kakor senca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Pošteni možje bodo osupli ob tem in nedolžni se bo razvnel zoper hinavca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, '§ Tudi pravični se bo držal svoje poti, kdor pa ima čiste roke, bo močnejši in močnejši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Toda kar se tiče vas vseh, ali se vrnete in torej greste, kajti med vami ne morem najti enega modrega moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Moji dnevi so minili, moji nameni so zlomljeni, celó misli mojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noč spreminjajo v dan, svetloba je kratka zaradi teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Če čakam, je moja hiša grob; svojo posteljo sem postlal v temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Trohnenju sem rekel: ›Ti si moj oče,‹ ličinki: › Ti si moja mati in moja sestra.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kje je sedaj moje upanje? Glede mojega upanja, kdo ga bo videl?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Šli bodo dol k zapahom jame, ko je naš skupni počitek v prahu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Potem je odgovoril Bildád Suhéjec in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '»Kako dolgo bo, preden boste naredili konec besedam? Premislite in potem bomo govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Zakaj smo šteti kakor živali in smatrani podle v vašem pogledu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'V svoji jezi trga samega sebe. Mar bo zemlja zapuščena zaradi tebe? Mar bo skala odstranjena iz svojega kraja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Da, svetloba zlobnega bo ugasnjena in iskrica njegovega ognja ne bo sijala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Svetloba bo tema v njegovem šotoru in njegova sveča bo ugasnjena z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Koraki njegove moči bodo omejeni in njegov lastni nasvet ga bo vrgel dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Kajti s svojim lastnim stopalom je vržen v mrežo in hodi po zanki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Past ga bo prijela za peto in ropar bo prevladal zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Zanka je položena zanj na tleh in pasti zanj na poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Strahote ga bodo prestrašile na vsaki strani in ga pognale k njegovim stopalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Njegova moč bo oslabljena zaradi lakote in uničenje bo pripravljeno ob njegovi strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Požrlo bo moč njegove kože. Celó prvorojenec smrti bo požrl njegovo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Njegovo zaupanje bo izkoreninjeno iz njegovega šotora in to ga bo privedlo h kralju strahot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Prebivalo bo v njegovem šotoru, ker ta ni njegov. Žveplo bo raztreseno nad njegovim prebivališčem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Njegove korenine bodo posušene spodaj in zgoraj bo njegova veja odsekana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Spomin nanj bo izginil z zemlje in nobenega imena ne bo imel na ulici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Iz svetlobe bo pognan v temo in pregnan bo iz zemeljskega [kroga].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Med svojim ljudstvom ne bo imel niti sina niti nečaka niti nobenega preživelega v svojih prebivališčih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Tisti, ki pridejo za njim, bodo osupli ob njegovem dnevu, kakor so bili zgroženi tisti, ki so šli poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Zagotovo, takšna so prebivališča zlobnih in to je kraj tistega, ki ne pozna Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Potem je Job odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '»Doklej boste mučili mojo dušo in me z besedami lomili na koščke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Teh desetkrat ste me grajali. Ni vas sram, da se mi delate tujce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Če je res to, da sem zašel, moja zmota ostaja z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Če se boste zares povzdigovali zoper mene in zoper mene obsojali moj očitek,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'vedite torej, da me je Bog zrušil in me obdal s svojo mrežo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Glej, kričim o krivici, toda nisem slišan; na glas vpijem, toda tam ni sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Ogradil je mojo stezo, da ne morem mimo in postavil je temo na moje poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Oropal me je moje slave in odvzel krono iz moje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Uničil me je na vsaki strani in odšel sem. Moje upanje je odstranil kakor drevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Prav tako je zoper mene vžgal svoj bes in me šteje kakor enega izmed svojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Njegova krdela so prišla skupaj in dvignila njihovo pot zoper mene in se utaborila naokoli mojega šotora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Moje brate je postavil daleč od mene in moji znanci so se resnično odtujili od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Moja žlahta je odpovedala in moji zaupni prijatelji so me pozabili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Tisti, ki prebivajo v moji hiši in moje služabnice me imajo za tujca. Neznanec sem v njihovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Poklical sem svojega služabnika, pa mi ni dal nobenega odgovora. Prosil sem ga s svojimi usti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Moj dih je tuj moji ženi, čeprav sem prosil zaradi otrok svojega lastnega telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Da, mladi otroci so me prezirali. Vzdignil sem se in oni so govorili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Vsem svojim bližnjim prijateljem sem se gnusil. Tisti, ki sem jih imel rad, so se obrnili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Moje kosti se lepijo na mojo kožo in na moje meso in pobegnil sem s kožo med svojimi zobmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Imejte usmiljenje z menoj, imejte usmiljenje z menoj, oh vi, moji prijatelji, kajti Božja roka se me je dotaknila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Čemu me preganjate kakor Bog in niste nasičeni z mojim mesom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oh da bi bile moje besede sedaj zapisane! Oh, da bi bile natisnjene v knjigi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Da bi bile vgravirane z železnim peresom in svincem v skalo na veke!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Kajti jaz vem, da moj odkupitelj živi in da bo na zadnji dan stal nad zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Čeprav po moji koži črvi uničijo to telo, bom vendar v svojem mesu videl Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'ki ga bom videl zase in moje oči bodo gledale in ne drug, čeprav je moja notranjost použita znotraj mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Toda vi bi morali reči: ›Zakaj ga preganjamo,‹ glede na to, da je korenina zadeve najdena v meni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Bojte se meča, kajti bes prinaša kaznovanja meča, da boste lahko vedeli, da je sodba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Potem je odgovoril Cofár Naámčan in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '»Zato mi moje misli povzročajo, da odgovorim in zaradi tega hitim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Slišal sem preverjanje svoje graje in duh mojega razumevanja mi povzroča, da odgovorim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Mar ne veš tega od davnine, odkar je bil človek postavljen na zemljo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'da je zmagoslavje zlobnega kratko, radost hinavca pa le za trenutek?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Čeprav se njegova odličnost vzpenja do neba in njegova glava sega do oblakov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'se bo vendarle pogubil za vedno, kot njegov lastni iztrebek. Tisti, ki so ga videli, bodo rekli: ›Kje je?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Odletel bo proč kakor sanje in ne bo ga najti. Da, pregnan bo kakor nočno videnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Tudi oko, ki ga je videlo, ga ne bo več videlo niti ga njegov kraj ne bo več gledal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Njegovi otroci bodo iskali, da ugodijo revnemu in njegove roke bodo obnovile njihove dobrine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Njegove kosti so polne greha iz njegove mladosti, ki se bodo ulegle z njim v prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Čeprav je zlobnost sladka v njegovih ustih, čeprav to skriva pod svojim jezikom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'čeprav temu prizanaša in tega ne zapusti, temveč to mirno drži znotraj svojih ust,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'je vendar njegova hrana v njegovi notranjosti spremenjena, to je žolč kober znotraj njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Pogoltnil je bogastva in ponovno jih bo izbljuval. Bog jih bo izvrgel iz njegovega trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Sesal bo strup kober, gadov jezik ga bo ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Ne bo videl rek, poplav, potokov iz meda in masla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'To, za kar se je trudil, bo povrnil in tega ne bo pogoltnil. Glede na njegovo imetje bo povračilo in v tem se ne bo veselil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Ker je zatiral in zapustil ubogega, ker je nasilno odvzel hišo, ki je ni zgradil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'zagotovo ne bo čutil spokojnosti v svojem trebuhu, ne bo rešil od tega, kar si je želel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Ničesar ne bo ostalo od njegove hrane, zato noben človek ne bo gledal za njegovimi dobrinami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'V polnosti svoje zadostnosti bo v stiskah; vsaka roka zlobnega bo prišla nadenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Ko si namerava napolniti svoj trebuh, bo Bog nadenj vrgel razjarjenost svojega besa in ta bo deževala nadenj, medtem ko jé.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Pobegnil bo pred železnim orožjem in lok iz jekla ga bo prebodel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Ta je izvlečen in prihaja iz telesa. Da, lesketajoč meč prihaja iz njegovega žolča; strahote so nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Vsa tema bo skrita v njegovih skritih krajih. Ogenj, ki se ni razgorel, ga bo požrl; slabo bo šlo s tistim, ki je ostal v njegovem šotoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Nebesa bodo razodela njegovo krivičnost in zemlja se bo dvignila zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Donos njegove hiše bo odšel in njegove dobrine bodo odtekle na dan njegovega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'To je delež zlobnemu človeku od Boga in od Boga določena mu dediščina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Toda Job je odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '»Marljivo prisluhnite mojemu govoru in to naj bodo vaše tolažbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Pustite mi, da lahko govorim in potem, ko bom govoril, zasmehujte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Kar se mene tiče ali je moja pritožba proti človeku? In če bi bilo tako, zakaj naj potem moj duh ne bi bil nemiren?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Poglejte me in bodite osupli in svojo roko položite na svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Celo kadar se spomnim, sem prestrašen in trepetanje se oprijemlje mojega mesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Zakaj zlobni živijo, postanejo stari in so mogočni v moči?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Njihovo seme je z njimi utrjeno v njihovem pogledu in njihovo potomstvo pred njihovimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Njihove hiše so varne pred strahom niti nad njimi ni Božje palice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Njihov bik plodi in ne odpove; njihova krava povrže in ne zavrže svojega teleta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Svoje malčke pošiljajo kakor trop in njihovi otroci plešejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Vzamejo tamburin in harfo in se veselijo ob zvoku piščali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Svoje dni preživijo v obilju in v trenutku gredo dol v grob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Zato Bogu rečejo: ›Odidi od nas, kajti mi ne želimo spoznanja tvojih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kaj je Vsemogočni, da bi mu služili? In kakšno korist bi imeli, če molimo k njemu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Glej, njihovo dobro ni v njihovi roki; nasvet zlobnega je daleč od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Kako pogosto je sveča zlobnih ugasnjena! In kako pogosto nanje prihaja njihovo uničenje! Bog v svoji jezi deli bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'So kakor strnišče pred vetrom in kakor pleve, ki jih vihar odnaša proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Bog kopiči njegovo krivičnost za njegove otroke. Nagrajuje ga in on bo to vedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Njegove oči bodo videle njegovo uničenje in pil bo od besa Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Kajti kakšen užitek ima on v njegovi hiši za njim, ko je število njegovih mesecev na sredi prekinjeno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Mar bo kdorkoli Boga učil spoznanja? Ker on sodi tiste, ki so visoko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Nekdo umre v svoji polni moči, v celoti spokojen in tiho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Njegove prsi so polne mleka in njegove kosti so navlažene z mozgom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Drugi pa umira v grenkobi svoje duše in nikoli ne jé z užitkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Podobno se bodo ulegli v prah in ličinke jih bodo pokrile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Glej, poznam vaše misli in naklepe, ki ste jih krivično domišljali zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Kajti pravite: »Kje je prinčeva hiša? Kje so bivališča zlobnih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Mar jih niste prosili, da gredo po poti? Ali poznate njihove simbole,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'da je zlobni prihranjen za dan uničenja? Privedeni bodo k dnevu besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kdo bo njegovo pot oznanil njegovemu obrazu? Kdo mu bo poplačal, kar je storil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Vendar bo priveden h grobu in ostal bo v gomili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Grude iz doline mu bodo sladke in vsak človek bo priveden za njim, kakor so tam brezštevilni pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kako me potem zaman tolažite, glede na to, da v vaših odgovorih ostaja neresnica?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Potem je Elifáz Temánec odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '»Je lahko človek koristen Bogu kakor, je tisti, ki je moder, koristen samemu sebi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Mar je kakršenkoli užitek za Vsemogočnega, da si ti pravičen? Ali je to zanj dobiček, da delaš svoje poti popolne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Ali te bo grajal zaradi strahu pred teboj? Ali bo vstopil s teboj na sodbo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Mar ni tvoja zlobnost velika? In tvoje krivičnosti neskončne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Kajti zaman si vzel jamstvo od svojega brata in nagim slekel njihova oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Nisi dal vode izmučenemu, da pije in pred lačnim si zadržal kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Toda kar se tiče mogočnega človeka. Imel je deželo in častitljiv človek je prebival v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Vdove si odposlal prazne in lakti osirotelih so bili zlomljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Zato so zanke naokoli tebe in nenaden strah te nadleguje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'ali tema, ki je ne moreš videti in pokriva te obilje vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Mar ni Bog na nebeški višavi? Glej višino zvezd, kako visoko so!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'In ti praviš: ›Kako Bog vé? Mar lahko sodi skozi temen oblak?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Debeli oblaki so mu pokrivalo, da ne vidi in on hodi v nebeškem krogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Si označil staro pot, ki so jo pomendrali zlobneži?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Ki so bili posekani izven časa, katerih temelj je bil preplavljen s poplavo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'ki so Bogu rekli: ›Odidi od nas.‹ Kaj lahko stori zanje Vsemogočni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Vendar je njihove hiše napolnil z dobrimi stvarmi, toda nasvet zlobnega je daleč od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Pravični to vidijo in so veseli in nedolžni se jim smejijo do norčevanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '[rekoč]: »Glej, naše imetje ni uničeno, toda njihov ostanek použiva ogenj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Seznani se torej z njim in bodi miren in tako bo k tebi prišlo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Sprejmi, prosim te, postavo iz njegovih ust in njegove besede položi v svoje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Če se vrneš k Vsemogočnemu, boš izgrajen, krivičnost boš odstranil daleč od svojih šotorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Potem boš kopičil zlato kakor prah in ofírsko zlato kakor kamne iz potokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Da, Vsemogočni bo tvoja obramba in imel boš obilico srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Kajti takrat boš imel svoje zadovoljstvo v Vsemogočnem in svoj obraz boš dvignil k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Svojo molitev boš naredil k njemu in on te bo slišal in izpolnil boš svoje zaobljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Ti boš tudi odredil stvar in ta ti bo utrjena in svetloba bo sijala nad tvojimi potmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Kadar so možje ponižani, potem boš rekel: › Tam je povzdigovanje,‹ in on bo rešil ponižno osebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Osvobodil bo otok nedolžnega in ta je osvobojen s čistostjo tvojih rok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Potem je Job odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '»Celó do danes je moja pritožba grenka, moj udarec je težji kakor moje stokanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oh, da bi vedel, kje ga lahko najdem! Da bi lahko prišel celó k njegovemu sedežu!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Svojo zadevo bi razporedil pred njim in svoja usta zapolnil z argumenti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Poznal bi besede, ki bi mi jih odgovoril in razumel kaj bi mi rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Mar bo navajal dokaze zoper mene s svojo veliko močjo? Ne, temveč bi vame položil moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tam se lahko pravični prereka z njim; tako bi bil na veke osvobojen pred svojim sodnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Glej, grem naprej, toda ni ga tam; in nazaj, toda ne morem ga zaznati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Na levico, kjer dela, toda ne morem ga gledati. Skrije se na desnici, da ga ne morem videti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Toda pozna pot, ki se je držim. Ko me preizkuša, bom izšel kakor zlato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Moje stopalo se je držalo njegovih korakov, njegove poti sem se držal in nisem skrenil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Niti nisem odstopil od zapovedi njegovih ustnic. Besede iz njegovih ust sem cenil bolj kakor svojo potrebno hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Toda on je enega mišljenja in kdo ga lahko odvrne? In kar njegova duša želi, celo to počne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Kajti opravlja stvar, ki je določena zame in mnogo takšnih stvari je z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Zato sem vznemirjen ob njegovi prisotnosti. Ko preudarim, se ga bojim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Kajti Bog mehča moje srce in Vsemogočni me vznemirja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'ker nisem bil odsekan pred temo niti ni teme pokril pred mojim obrazom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Zakaj, videč, da časi niso skriti pred Vsemogočnim, tisti, ki ga ne poznajo, vidijo njegove dni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Nekateri odstranjujejo mejnike, na silo odvedejo trope in se hranijo z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Odvedli so osla osirotelemu, vdovinega vola so vzeli za jamstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Pomoči potrebnega odvrnejo iz poti. Revni na zemlji se skupaj skrivajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Glej, kakor divji osli v puščavi gredo naprej k svojemu delu; ob zori se dvigajo za plenom. Divjina zanje in za njihove otroke obrodi hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Žanjejo vsak svoje žito na polju, in zbirajo trgatev zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nagim povzročajo, da prenočujejo brez oblačil, da v mrazu nimajo nobenega pokrivala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Mokri so od nalivov z gora in se oklepajo skale v želji po zatočišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Siroto trgajo od prsi in jemljejo jamstvo revnemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Povzročajo mu, da hodi nag, brez obleke in jemljejo snop pred lačnim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'ki dela olje znotraj njihovih zidov in mendra njihove vinske stiskalnice in trpi žejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Iz mesta stokajo ljudje in duša ranjenega vpije, vendar Bog nanje ne polaga nespametnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Oni so izmed tistih, ki se upirajo svetlobi. Ne poznajo njenih poti niti ne ostajajo na njenih stezah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Morilec vstaja s svetlobo, ubija uboge in pomoči potrebne in v noči je kakor tat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Tudi oko zakonolomca čaka na mrak, rekoč: ›Nobeno oko me ne bo videlo‹ in skriva svoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'V temi kopljejo skozi hiše, ki so si jih označili podnevi; oni ne poznajo svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Kajti jutro jim je celo kakor senca smrti. Če jih kdo prepozna, so v strahotah smrtne sence.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Nagel je kakor vode. Njihov delež je preklet na zemlji. Ne gleda poti v vinograde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Suša in vročina použijeta snežne vode; tako grob tiste, ki so grešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Maternica ga bo pozabila, ličinka se bo medéno hranila na njem. Ne bo se ga več spominjalo in zlobnost bo zlomljena kakor drevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Z jalovo, ki ne rojeva, postopa hudobno in ne dela dobrega vdovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, '§ S svojo močjo priteguje tudi mogočne. On vstaja in noben človek ni prepričan v življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Čeprav mu je dano, da bi bil na varnem, kjer počiva, so vendar njegove oči na njihovih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Povišani so za malo časa, toda izginejo in so ponižani. Vzeti so iz poti kakor vsi drugi in odsekani kakor vrhovi žitnega klasja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Če ne bi bilo to sedaj tako, kdo me bo naredil za lažnivca in moj govor naredil brez vrednosti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Potem je odgovoril Bildád Suhéjec in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '»Gospostvo in strah sta z njim, on dela mir na svojih visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Mar obstaja kakršnokoli število njegovih vojsk? Nad kom ne vstaja njegova svetloba?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kako je potem človek lahko opravičen pred Bogom? Ali kako je lahko čist tisti, ki je rojen iz ženske?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Poglej celo k luni in ta ne sije. Da, zvezde niso čiste v njegovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Kako veliko manj človek, ki je ličinka? In sin človekov, ki je črv?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Toda Job je odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '»Kako si pomagal tistemu, ki je brez moči? Kako rešuješ laket, ki nima moči?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kako si svetoval tistemu, ki nima modrosti? Kako si obilno oznanil stvar, kakor je ta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komu si izrekal besede? Čigav duh je prišel od tebe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Mrtve stvari so oblikovane pod vodami in njihovi prebivalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Pekel je nag pred njim in uničenje nima pokrivala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Sever izteguje nad praznim krajem in zemljo obeša na nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Vode povezuje v svoje debele oblake in pod njimi se oblak ne pretrga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Zadržuje obličje svojega prestola in svoj oblak razprostira nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, '§ Vode je obdal z vezmi, dokler dan in noč ne prideta do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Stebri nebes trepetajo in so osupli ob njegovem opominu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, '§ On s svojo močjo razdeljuje morje in s svojim razumevanjem udarja po ponosnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, '§ S svojim duhom je okrasil nebo; njegova roka je oblikovala sprijeno kačo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Glej! To so delčki njegovih poti. Toda kako majhen delček je slišati o njem? Toda kdo lahko razume grom njegove moči?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Poleg tega je Job nadaljeval svojo prispodobo in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '» Kakor Bog živi, ki je odvzel mojo sodbo in Vsemogočni, ki je nadlegoval mojo dušo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'ves čas je moj dih v meni in Božji duh je v mojih nosnicah;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'moje ustnice ne bodo govorile zlobnosti niti moj jezik ne bo izrekel prevare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Bog ne daj, da bi vas opravičil. Dokler ne umrem, svoje neokrnjenosti ne bom odstranil od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Svojo pravičnost trdno držim in je ne bom izpustil. Moje srce me ne bo grajalo, tako dolgo, dokler živim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Naj bo moj sovražnik kakor zlobnež in kdor se dviguje zoper mene kakor nepravičnež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, '§ Kajti kaj je upanje hinavca, čeprav on pleni, medtem ko Bog odvzema njegovo dušo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Mar bo Bog slišal njegov jok, ko nadenj pride stiska?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Mar se bo razveseljeval v Vsemogočnem? Mar bo vedno klical k Bogu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Učil te bom z Božjo roko. Tega, kar je z Vsemogočnim, ne bom prikrival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Glejte, vi vsi ste to videli, zakaj ste potem vsi skupaj tako prazni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'To je delež zlobnega moža z Bogom in dediščina zatiralcev, ki jo bodo prejeli od Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Če bodo njegovi otroci pomnoženi, je to za meč in njegovo potomstvo ne bo nasičeno s kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Tisti, ki preostanejo od njega, bodo pokopani v smrt in njegove vdove ne bodo jokale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Čeprav kopiči srebra kakor prahu in si pripravlja oblačila kakor iz ila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'to lahko pripravlja, toda pravični si bo to nadel in nedolžni bo razdelil srebro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Svojo hišo gradi kakor molj in kakor šotor, ki ga postavlja čuvaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bogataš se bo ulegel, toda ne bo zbran, odpira svoje oči in ga ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Strahote ga zgrabijo kakor vode, vihar ga ukrade v noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Vzhodnik ga odnaša proč in on odhaja; kakor vihar ga vrže iz njegovega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Kajti Bog bo vrgel nanj in ne bo prizanesel, želel bo pobegniti iz njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Ljudje bodo s svojimi rokami ploskali nad njim in ga izžvižgali iz njegovega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Zagotovo obstaja žila za srebro in prostor za zlato, kjer ju prečiščujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Železo je vzeto iz zemlje in bron je staljen iz kamna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'On postavlja konec temi in preiskuje vso popolnost: kamne iz teme in smrtno senco.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, '§ Poplava izbruhne ven, proč od prebivalca, celo vode, pozabljene od stopala. Posušene so, odtekle so proč od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Glede zemlje, iz nje prihaja kruh, in pod njo je obrnjeno, kakor bi bil ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Njeni kamni so mesto za safirje in ta ima zlati prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Je steza, ki je nobena perjad ne pozna in ki je jastrebovo oko ni videlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Levji mladiči je niso pomendrali niti krut lev ni šel mimo nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Svojo roko izteguje nad skalo, gore prevrača pri koreninah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Reke vrezuje med skalami in njegovo oko vidi vsako dragoceno stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Poplave zvezuje pred poplavljanjem in stvar, ki je skrita, prinaša na svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Toda kje se bo našla modrost? In kje je kraj razumevanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Človek ne ve za njeno vrednost niti je ni najti v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Globina pravi: ›V meni je ni.‹ Morje pravi: ›Ta ni z menoj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Ni je moč dobiti za zlato niti ne bo srebro odtehtano za njeno vrednost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Ta ne more biti primerjana z zlatom iz Ofírja, z dragocenim oniksom ali safirjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Zlato in kristal ji ne moreta biti enaka in njena zamenjava ne bo za dragocenosti iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Nobene omembe ne bo narejene o koralah ali o biserih, kajti cena modrosti je nad rubini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topaz iz Etiopije ji ne bo enak niti ne bo ovrednotena s čistim zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Od kod potem prihaja modrost? In kje je kraj razumnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Videti je, da je skrita pred očmi vseh živih in prikrita pred zračno perjadjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Uničenje in smrt pravita: ›O njeni slavi sva slišala s svojimi ušesi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Bog razume njeno pot in on pozna njen kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Kajti gleda do koncev zemlje in vidi pod celotnim nebom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'ko naredi težo za vetrove in vode odmerja z mero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Ko je naredil odlok za dež in pot za bliskanje groma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'potem jo je videl in jo oznanja. Pripravlja jo, da, in razpoznava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Človeku pa pravi: ›Glej, strah Gospodov, to je modrost; in oditi od zla je razumevanje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Poleg tega je Job nadaljeval svojo prispodobo in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '»Oh, da bi bil kakor v preteklih mesecih, kakor v dneh, ko me je Bog varoval,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'ko je njegova sveča svetila nad mojo glavo in ko sem z njegovo svetlobo hodil skozi temo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'kakor sem bil v dneh svoje mladosti, ko je bila Božja skrivnost na mojem šotoru,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'ko je bil Vsemogočni še z menoj, ko so bili moji otroci okoli mene,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'ko sem svoje korake umival z maslom in mi je skala izlivala reke olja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'ko sem šel ven k velikim vratom skozi mesto, ko sem svoj sedež pripravil na ulici!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Mladeniči so me videli in se skrili in ostareli so se vzdignili in stali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Princi so zadržali govorjenje in na svoja usta položili svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Plemiči so molčali in njihov jezik se je prilepil na nebo njihovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Ko me je uho zaslišalo, potem me je blagoslovilo in ko me je oko zagledalo, mi je dalo pričevanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'ker sem osvobodil reveža, ki je jokal in osirotelega in tistega, ki ni imel nikogar, da mu pomaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Blagoslov tistega, ki je bil pripravljen, da umre, je prišel nadme. Vdovinemu srcu sem storil, da prepeva od radosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Nadel sem si pravičnost in ta me je oblekla. Moja sodba je bila kakor svečano oblačilo in diadem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Bil sem oči slepemu in stopala hromemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Bil sem oče revnemu in zadevo, ki je nisem poznal, sem preiskal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Zlomil sem čeljusti zlobnemu in izpulil plen iz njegovih zob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Potem sem rekel: ›Umrl bom v svojem gnezdu in svoje dneve bom pomnožil kakor pesek.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Moja korenina je bila razprostrta pri vodah in rosa je vso noč ležala na moji mladiki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Moja slava je bila sveža v meni in moj lok je bil obnovljen v moji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Možje so mi prisluhnili, čakali in molčali ob mojem nasvetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po mojih besedah niso ponovno spregovorili in moj govor je rosil nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Name so čakali kakor na dež in svoja usta so široko odprli kakor za pozni dež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Če sem se jim smejal, temu niso verjeli. Svetlobe mojega obličja niso zavrgli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Izbral sem njihovo pot in sedel [kot] vodja in prebival kakor kralj v vojski, kakor nekdo, ki tolaži žalovalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Toda sedaj me imajo tisti, ki so mlajši od mene, v posmeh, katerih očete bi preziral, da jih postavim s psi svojega tropa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Da, kako naj mi moč njihovih rok koristi, zrelost je odšla od njih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Zaradi potrebe in lakote so bili osamljeni. Bežijo v divjino, v prejšnjem času zapuščeno in opustošeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Ki sekajo egiptovsko špinačo pri grmih in brinove korenine so njihova hrana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Pregnani so bili izmed ljudi (za njimi so vpili kakor za tatom),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'da prebivajo v pečinah dolin, v zemeljskih votlinah in v skalah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Med grmovjem so rigali, pod koprivami so bili zbrani skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Bili so otroci bedakov, da, otroci nizkotnih mož, bili so zlobnejši kakor zemlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Sedaj sem njihova pesem, da, jaz sem njihova tarča posmeha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Prezirajo me, bežijo daleč od mene in ne prizanašajo mi pljunka v moj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Ker je odvezal mojo vrvico in me prizadel, so tudi oni popustili uzdo pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Na moji desni roki vstaja mladina. Moja stopala odrivajo in zoper mene so dvignili poti svojega uničenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Škodujejo moji stezi, postavili so mojo katastrofo, nobenega pomočnika nimajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, '§ Prišli so nadme kakor [skozi] široko vrzel vodá. V opustošenju so se zgrnili nadme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Strahote so se zgrnile nadme. Mojo dušo zasledujejo kakor veter in moja blaginja mineva kakor oblak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Sedaj je moja duša izlita nadme, polastili so se me dnevi stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Moje kosti so prebodene v meni v nočnem obdobju in moje kite nimajo počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Z veliko silo moje bolezni je moja obleka spremenjena; naokoli me veže kakor ovratnik mojega plašča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Vrgel me je v blato in postal sem podoben prahu in pepelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Kličem k tebi, ti pa me ne slišiš. Vstanem, ti pa se ne oziraš name.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Do mene si postal krut; s svojo močno roko se nastrojuješ zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Vzdiguješ me k vetru, povzročaš mi, da jaham na njem in raztapljaš moje imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Kajti vem, da me boš privedel k smrti in k hiši, določeni za vse živeče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Vendar svoje roke ne bo iztegnil h grobu, čeprav v svojem uničenju kričijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Mar nisem jokal zaradi tistega, ki je bil v stiski? Mar ni moja duša žalovala za ubogim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Ko sem gledal za dobrim, potem je prišlo k meni zlo. Ko pa sem pričakoval svetlobo, je prišla tema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Moja notranjost vre in ne počiva. Dnevi stiske so me ovirali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Odšel sem žalujoč brez sonca. Vstal sem in klical v skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Brat sem zmajem in družabnik sovam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Moja koža na meni je črna in moje kosti gorijo zaradi vročine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Tudi moja harfa je obrnjena v žalovanje in moja piščal v glas tistih, ki jokajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Sklenil sem zavezo s svojimi očmi. Zakaj naj bi potem mislil na devico?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Kajti kakšen delež od Boga je od zgoraj? In kakšna dediščina od Vsemogočnega od zgoraj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Mar ni uničenje za zlobne? In posebna kazen za delavce krivičnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Mar on ne vidi mojih poti in šteje vse moje korake?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Če sem hodil z ničnostjo ali če je moje stopalo hitelo k prevari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'naj bom stehtan na pravilni tehtnici, da Bog lahko spozna mojo neokrnjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Če se je moj korak obrnil iz poti in je moje srce hodilo za mojimi očmi in če se je kakršenkoli madež prilepil na moje roke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'potem naj jaz sejem in naj drug jé. Da, naj bo moje potomstvo izkoreninjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Če je bilo moje srce zavedeno z žensko, ali če sem prežal pri vratih svojega soseda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'potem naj moja žena melje drugemu in naj se drugi sklanjajo nadnjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Kajti to je grozoten zločin. Da, to je krivičnost, ki naj se kaznuje s sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Kajti to je ogenj, ki použiva v uničenje in bi izkoreninil ves moj donos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Če sem preziral zadevo svojega sluga ali svoje dekle, ko so se pričkali z menoj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'kaj bom potem storil, ko se dvigne Bog? In ko on obiskuje, kaj naj mu odgovorim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Mar ni on, ki me je naredil v maternici, naredil njega? Ali naju ni eden oblikoval v maternici?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Če sem uboge zadržal pred njihovo željo, ali očem vdove storil, da opešajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'ali sem sam pojedel svoj grižljaj in osiroteli ni jedel od njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(kajti od moje mladosti je bil vzgajan z menoj kakor z očetom in usmerjal sem jo od maternice svoje matere),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'če sem gledal kogarkoli giniti zaradi pomanjkanja obleke ali kateregakoli revnega brez pokrivala,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'če me njegova ledja niso blagoslovila in če ni bil ogret z runom moje ovce;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'če sem povzdignil svojo roko zoper osirotelega, ko sem videl svojo pomoč v velikih vratih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'potem naj moj laket pade od moje lopatice in moj laket [naj] bo odlomljen od kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Kajti uničenje od Boga mi je bilo strahota in zaradi razloga njegovega visočanstva ne bi mogel zdržati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Če sem zlato naredil za svoje upanje ali sem čistemu zlatu rekel: › Ti si moje zaupanje,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'če sem se veselil, ker je bilo moje premoženje veliko in ker je moja roka veliko pridobila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'če sem pogledal sonce, ko je sijalo ali luno hoditi v sijaju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'in je bilo moje srce skrivno premamljeno, oziroma so moja usta poljubila mojo roko?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Tudi to bi bila krivičnost, da bi bil kaznovan od sodnika, kajti jaz bi zanikal Boga, ki je zgoraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Če sem se veselil ob uničenju tistega, ki me je sovražil ali sem se povzdignil, ko ga je našlo zlo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'niti svojim ustom nisem dopustil, da grešijo z želenjem prekletstva njegovi duši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Če možje mojega šotora niso rekli: ›Oh, da bi imeli njegovo meso! Ne moremo biti zadovoljni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Tujec ni prenočeval na ulici, temveč sem svoja vrata odprl popotniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Če sem svoje prestopke pokril kakor Adam, s skrivanjem svoje krivičnosti v svojem naročju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'ali sem se bal velike množice, ali me straši zaničevanje družin, da sem molčal in nisem šel izpred vrat?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oh, da bi me nekdo poslušal! Glej, moja želja je, da bi mi Vsemogočni odgovoril in da bi moj nasprotnik napisal knjigo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Zagotovo bi to vzel na svojo ramo in si to privezal kot krono.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Prikazal bi mu število mojih korakov. Kakor princ bi šel blizu k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Če moja dežela joka zoper mene ali da se njene brazde podobno pritožujejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'če sem brez denarja pojedel njene sadove ali sem njenim lastnikom povzročil, da izgubijo svoje življenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'naj osat raste namesto pšenice in smrdljiv plevel namesto ječmena.« Jobove besede so končane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Tako so ti trije možje prenehali odgovarjati Jobu, ker je bil pravičen v svojih lastnih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Potem je bil vžgan bes Elihúja, Barahélovega sina, Buzéjca iz Rámovega rodu. Njegov bes je bil vžgan zoper Joba, ker je sebe bolj opravičeval kakor Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Tudi zoper njegove tri prijatelje je bil vžgan njegov bes, ker niso našli nobenega odgovora, pa so vendar obsodili Joba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Torej Elihú je čakal, dokler Job ni spregovoril, ker so bili starejši kakor on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Ko je Elihú videl, da ni bilo nobenega odgovora v ustih teh treh mož, je bil potem vžgan njegov bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Elihú, Barahélov sin, Buzéjec, je odgovoril in rekel: »Jaz sem mlad, vi pa ste zelo stari, zato sem bil prestrašen in se vam nisem drznil pokazati svojega mnenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Rekel sem: ›Dnevi naj bi spregovorili in množica let naj bi učila modrost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Toda v človeku je duh. Navdih Vsemogočnega jim daje razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Veliki možje niso vedno modri niti ostareli ne razumejo sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Zato sem rekel: ›Prisluhnite mi. Tudi jaz bom pokazal svoje mnenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Glejte, čakal sem na vaše besede, prisluhnil sem vašim razlogom, medtem ko ste iskali, kaj bi rekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Da, prisluhnil sem vam in glejte nikogar izmed vas ni bilo, da prepriča Joba ali da odgovori njegovim besedam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'da ne bi rekli: ›Pridobili smo modrost. Bog ga suva dol, ne človek.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Torej svojih besed ni usmeril zoper mene niti mu ne bom odgovoril z vašimi govori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Bili so osupli, niso več odgovarjali. Prenehali so govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Ko sem čakal (kajti niso govorili, temveč mirno stali in niso več odgovarjali),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'sem rekel: »Tudi jaz bom odgovoril svoj del, tudi jaz bom pokazal svoje mišljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Kajti poln sem stvari, duh znotraj mene me sili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Glejte, moj trebuh je kakor vino, ki nima oddušnika. Pripravljeno je, da poči kakor novi mehovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Govoril bom, da bom lahko osvežen. Odprl bom svoje ustnice in odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Ne pustite mi, prosim vas, sprejeti obličja kateregakoli moža niti mi ne pustite, da dajem laskave nazive človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Kajti ne znam dajati laskavih nazivov. Če bi tako počel, bi me moj stvarnik hitro odvedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Zatorej Job, prosim te, prisluhni mojim govorom in prisluhni vsem mojim besedam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Glej, sedaj sem odprl svoja usta, moj jezik je spregovoril v mojih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Moje besede bodo iz iskrenosti mojega srca in moje ustnice bodo jasno izgovarjale spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Božji Duh me je naredil in dih Vsemogočnega mi je dal življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Če mi lahko odgovoriš, uredi svoje besede pred menoj. Vstani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Glej, jaz sem glede na tvojo željo namesto Boga. Tudi jaz sem oblikovan iz ila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Glej, moja strahota te ne bo prestrašila niti ne bo moja roka težka na tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Zagotovo si govoril v mojem slišanju in slišal sem glas tvojih besed, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '›Čist sem, brez prestopka, nedolžen sem niti v meni ni krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Glej, zoper mene najde priložnosti, šteje me za svojega sovražnika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'moja stopala polaga v klade, zaznamuje vse moje steze.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Glej, v tem nisi pravičen. Odgovoril ti bom, da je Bog večji kakor človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Zakaj se prepiraš zoper njega? Kajti on ne daje računa o katerikoli izmed svojih zadev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Kajti Bog govori enkrat, da, dvakrat, vendar človek tega na zazna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'V sanjah in v videnju ponoči, ko na ljudi pade globoko spanje, v dremanjih na postelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Takrat on odpira ljudem ušesa in pečati njihovo poučevanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'da bi lahko odvrnil človeka od njegovega namena in pred človekom skril ponos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Njegovo dušo zadržuje pred jamo in njegovo življenje pred pogubo z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Okaran je tudi z bolečino na svoji postelji in množica njegovih kosti z močno bolečino,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'tako da njegovo življenje prezira kruh in njegova duša okusno hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Njegovo meso je použito, da ga ni moč videti in njegove kosti, ki jih ni bilo videti, štrlijo ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Da, njegova duša se približuje grobu in njegovo življenje k uničevalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Če bo z njim poslanec, tolmač, eden med tisočimi, da pokaže človeku njegovo poštenost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'potem mu je on milostljiv in pravi: ›Osvobodi ga pred pogrezanjem dol k jami. Našel sem odkupnino.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Njegovo meso bo mladostnejše kakor otrokovo. Vrnil se bo k dnem svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Molil bo k Bogu in mu bo naklonjen in z radostjo bo videl njegov obraz, kajti človeku bo povrnil njegovo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'On pogleda na ljudi in če kdorkoli reče: ›Grešil sem in izkrivljal to, kar je bilo pravilno, pa mi to ni koristilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'bo njegovo dušo osvobodil pred pogrezanjem v jamo in njegovo življenje bo videlo svetlobo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Glej, vse te stvari Bog pogosto dela s človekom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'da njegovo dušo privede nazaj iz jame, da bi bil razsvetljen s svetlobo živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Dobro pazi, oh Job, prisluhni mi. Umolkni in jaz bom govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Če mi imaš karkoli reči, mi odgovori. Govori, kajti želim te opravičiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Če ne, mi prisluhni. Umolkni in učil te bom modrosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Nadalje je Elihú odgovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '»Poslušajte moje besede, oh vi modri možje. Pazljivo mi prisluhnite vi, ki imate spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Kajti uho preizkuša besede, kakor usta okušajo hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Izberimo si sodbo. Naj med seboj spoznamo, kaj je dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Kajti Job je rekel: ›Jaz sem pravičen in Bog je odvzel mojo sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Mar naj bi lagal zoper svojo pravico? Moja rana je nezaceljiva, brez prestopka.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kateri človek je podoben Jobu, ki norčevanje pije kakor vodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Ki gre v družbo z delavci krivičnosti in hodi z zlobneži?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Kajti rekel je: ›Nič ne koristi človeku, da bi se razveseljeval z Bogom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Zato mi prisluhnite vi, možje razumevanja. Daleč naj bo od Boga, da bi počel zlobnost in od Vsemogočnega, da bi zagrešil krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Kajti delo človeka bo povrnil k sebi in vsakemu človeku povzroči, da najde glede na njegove poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Da, Bog zagotovo ne bo počel zlobno niti Vsemogočni ne bo izkrivil sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kdo mu je dal zadolžitev nad zemljo? Ali kdo je postavil celoten zemeljski [krog]?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Če svoje srce naravna na človeka, če k sebi zbere njegovega duha in njegov dih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'bo vse meso skupaj umrlo in človek se bo ponovno vrnil v prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Če imaš sedaj razumevanje, poslušaj to, prisluhni glasu mojih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Mar bo torej vladal tisti, ki sovraži pravico? Boš obsodil tistega, ki je najbolj pravičen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Mar je primerno kralju reči: › Ti si zloben?‹ In princem: › Vi ste brezbožni?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Kako veliko manj tistemu, ki ne sprejema oseb od princev niti se ne ozira na bogatega bolj kakor na ubogega? Kajti vsi ti so delo njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'V trenutku bodo umrli in ljudstvo bo zaskrbljeno ob polnoči in preminilo. Mogočen bo odvzet brez roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Kajti njegove oči so na človekovih poteh in vidi vsa njegova ravnanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ni teme niti smrtne sence, kjer bi se lahko skrili delavci krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Kajti na človeka ne bo položil več kakor pravico, da bi ta vstopil na sodbo z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Na koščke bo razbil mogočne može brez števila in druge postavil namesto njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Torej pozna njihova dela in jih prevrača v noči, tako da so uničena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Udarja jih kakor zlobneže v odprtem pogledu drugih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'ker so se obrnili proč od njega in niso hoteli preudariti nobene izmed njegovih poti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'tako da so vpitju ubogega povzročili, da pride k njemu in on sliši vpitje prizadetega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Ko daje spokojnost, kdo potem lahko dela težavo? In ko skrije svoj obraz, kdo ga potem lahko gleda? Bodisi je to storjeno zoper narod ali samo zoper človeka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'da hinavec ne kraljuje, da ne bi bilo ljudstvo ujeto v zanko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Zagotovo je primerno, da bi bilo Bogu rečeno: ›Nosil sem kaznovanje, ne bom več napačno počel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Tega, česar ne vidim, me uči. Če sem storil krivičnost, je ne bom več počel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Mar bo to glede na tvoj um? On bo to poplačal, bodisi ali odkloniš ali izbereš, in ne jaz. Zato govori, kar veš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Naj mi možje razumevanja povedo in naj mi moder mož prisluhne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Job je govoril brez spoznanja in njegove besede so bile brez modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Moja želja je, da bi bil Job lahko preizkušen do konca zaradi svojih odgovorov zlobnežem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Kajti svojemu grehu dodaja upor, s svojimi rokami ploska med nami in svoje besede pomnožuje zoper Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihú je poleg tega spregovoril in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '»Mar misliš, da je to pravilno, da govoriš: ›Moja pravičnost je večja kakor Božja?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Kajti praviš: ›Kakšna prednost ti bo to?‹ in ›Kakšno korist bom imel, če bom očiščen pred svojim grehom?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Odgovoril ti bom in tvojim družabnikom s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Poglej v nebo in glej. Ogleduj oblake, ki so višje kakor ti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Če grešiš, kaj delaš zoper njega? Ali če so tvoji prestopki pomnoženi, kaj mu delaš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Če si pravičen, kaj mu daješ? Ali kaj on prejema iz tvoje roke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Tvoja zlobnost lahko prizadene človeka, kakor si ti in tvoja pravičnost lahko koristi človeškemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Zaradi množice zatiranj povzročajo zatiranim, da kričijo. Vpijejo zaradi lakta mogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Toda nihče ne pravi: ›Kje je Bog, moj stvarnik, ki daje pesmi ponoči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'ki nas uči več kakor zemeljske živali in nas dela modrejše kakor perjad neba?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tam vpijejo, toda nihče ne daje odgovora zaradi ponosa zlobnežev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Bog zagotovo ne bo slišal prazne reči niti se Vsemogočni na to ne bo oziral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Čeprav praviš, da ga ne boš videl, je vendar sodba pred njim, zato zaupaj vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Toda sedaj, ker to ni tako, je obiskal v svoji jezi, vendar on tega v veliki skrajnosti ne pozna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Job zato svoja usta zaman odpira. Besede množi brez spoznanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihú je tudi nadaljeval in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '»Dovoli mi malo in pokazal ti bom, da bom še govoril za Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Svoje spoznanje bom prinesel od daleč in pravičnost pripisal svojemu Stvarniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Kajti zares moje besede ne bodo napačne. On, ki je popoln v spoznanju, je s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Glej, Bog je mogočen in ne prezira nikogar. Mogočen je v moči in modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Ne varuje življenja zlobnih, temveč daje pravico ubogim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Svojih oči ne umakne od pravičnih, temveč so oni s kralji na prestolu. Da, utrjuje jih na veke in so povišani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'In če bodo zvezani v okove in držani v vrveh stiske,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'tedaj jim kaže njihovo delo in njihove prestopke, ki so jih presegli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Tudi njihovo uho odpira k disciplini in zapoveduje, da se vrnejo od krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Če ga ubogajo in mu služijo, bodo svoje dni preživeli v uspevanju in svoja leta v užitkih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Toda če ne ubogajo, se bodo pogubili pod mečem in umrli bodo brez spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Toda hinavci v srcu kopičijo bes. Ne vpijejo, ko jih zvezuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Umrejo v mladosti in njihovo življenje je med nečistimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Revnega osvobaja v njegovi stiski in njihova ušesa odpira v zatiranju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Celo tako bi te odstranil iz tesnega na prostran kraj, kjer ni omejenosti in to, kar naj bi bilo postavljeno na tvojo mizo, bi bilo polno tolšče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Toda izpolnil si sodbo zlobnega. Sodba in pravica te bosta zgrabili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Ker je bes, pazi, da te ne bi odvzel s svojim udarcem. Potem te velika odkupnina ne more osvoboditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Bo cenil tvoja bogastva? Ne niti zlata niti vseh sil moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne želi si noči, ko so ljudje iztrebljeni iz svojega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Pazi, ne oziraj se na krivičnost, kajti to si izbral raje kakor stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Glej, Bog s svojo močjo povišuje. Kdo poučuje kakor on?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kdo se mu je pridružil na njegovi poti? Ali kdo lahko reče: ›Počel si krivičnost?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Spomni se, da poveličuješ njegovo delo, ki ga ljudje gledajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Vsak človek ga lahko vidi. Človek ga lahko gleda od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Glej, Bog je velik in mi ga ne poznamo niti število njegovih let ne more biti preiskano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Kajti kapljice vode dela majhne. Dež izliva glede na njegovo meglico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'katero oblaki kapljajo in obilno rosijo na človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Mar prav tako lahko kdorkoli razume razširjanje oblakov ali zvok njegovega šotora?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Glej, svojo svetlobo razširja nanje in pokriva dna morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Kajti z njimi sodi ljudstvu, hrano daje v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, '§ Z oblaki pokriva svetlobo in ji zapoveduje, naj ne sveti z oblakom, ki prihaja vmes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Njegov hrup govori o tem, tudi živina glede meglice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Tudi ob tem moje srce trepeta in je premaknjeno iz svojega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Pozorno prisluhnite hrupu njegovega glasu in zvoku, ki gre iz njegovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Tega usmerja pod celotnim nebom in svoje bliskanje do koncev zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Za tem rjovi glas. Grmi z glasom svoje odličnosti in ne bo jih zadržal, ko se zasliši njegov glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bog s svojim glasom čudovito grmi. Dela velike stvari, ki jih ne moremo doumeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Kajti snegu pravi: ›Bodi na zemlji,‹ podobno majhnemu dežju in velikemu dežju njegove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Pečati roko vsakega človeka, da bi vsi ljudje lahko poznali njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Potem gredo živali v brloge in ostanejo na svojih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Iz juga prihaja vrtinčast veter in mraz iz severa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Z dihom Boga je dana zmrzal in širina vodá je omejena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Tudi z namakanjem obtežuje debel oblak. Razpršuje svoj svetli oblak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Ta je obrnjen ob njegovih nasvetih, da lahko naredijo karkoli jim zapoveduje na obličju zemeljskega [kroga] na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Povzroča mu, da pride, bodisi za grajanje ali za njegovo deželo ali za usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Prisluhni temu, oh Job. Stoj mirno in preudari čudovita Božja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Ali veš, kdaj jih je Bog razporedil in svetlobi svojega oblaka velel, da zasije?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Mar poznaš izravnavanja oblakov, čudovita dela njega, ki je popoln v spoznanju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Kako so tvoje obleke tople, ko z južnim vetrom umiri zemljo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ali si ti z njim razprostrl nebo, ki je močno in kakor staljeno zrcalo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Pouči nas, kaj mu bomo rekli, kajti svojega govora ne moremo urediti zaradi teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Mar mu bo povedano, da jaz govorim? Če človek govori, bo zagotovo požrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Sedaj ljudje ne vidimo svetle svetlobe, ki je v oblakih, toda veter gre mimo in jih očisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Lepo vreme prihaja iz severa. Z Bogom je strašno veličanstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Glede Vsemogočnega, ne moremo ga srečati. Odličen je v moči, v sodbi in v obilici pravice. Ne bo prizadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Ljudje se ga zato bojijo. Ne ozira se na nobenega od tistih, ki so modrega srca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Potem je Gospod Jobu odgovoril iz vrtinčastega vetra in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '»Kdo je ta, ki zatemnjuje nasvet z besedami brez spoznanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Opaši sedaj svoja ledja kakor mož, kajti od tebe bom zahteval in ti mi odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kje si bil, ko sem položil temelje zemlji? Razglasi, če imaš razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kdo je položil njene mere, če veš? Ali kdo je na njej razprostrl [merilno] vrvico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Na čem so njeni temelji pritrjeni?? Ali kdo je položil njen vogalni kamen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'ko so jutranje zvezde skupaj prepevale in so vsi Božji sinovi vriskali od radosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Ali kdo je morje zaprl z vrati, ko je to izbruhnilo, kakor če bi to izšlo iz maternice?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Ko sem oblak naredil [za] njegovo oblačilo in gosto temo kot plenice zanj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'in sem zanj zdrobil svoj določen kraj ter postavil zapahe in vrata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'in rekel: ›Do sem boš šel in nič dlje. Tukaj bodo tvoji ponosni valovi ustavljeni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Ali si zapovedal jutru, odkar so tvoji dnevi in svitanju storil, da pozna svoje mesto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'da bi lahko zgrabil konce zemlje, da bi bili zlobni lahko streseni iz nje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Ta je spremenjena kakor ilo pod pečatom, in oni stojijo kakor oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Pred zlobnimi je njihova svetloba zadržana in visok laket bo zlomljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Si vstopil v morske izvire? Ali si hodil v iskanju globin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'So ti bila odprta velika vrata smrti? Ali si videl vrata smrtne sence?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Si zaznal širino zemlje? Razglasi, če veš vse to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Kje je pot, kjer prebiva svetloba? In glede teme, kje je njen kraj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'da bi jo odvedel do njene meje in da bi spoznal steze k njeni hiši?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Mar veš to, ker si bil takrat rojen? Ali ker je število tvojih dni veliko?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Si vstopil v zakladnice snega? Si mar videl zakladnice toče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'ki sem jih prihranil za čas stiske, za dan bitke in vojne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Po kateri poti je svetloba razdeljena, ki vzhodnik razkropi po zemlji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kdo je razdelil vodni tok za poplavljanje voda ali pot za bliskanje groma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'da mu povzroči, da dežuje na zemljo, kjer ni nobenega moža, na divjino, kjer ni nobenega človeka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'da zadovolji zapuščena in opustošena tla in povzroči, da brsti nežnega zelišča vzbrstijo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Ima dež očeta? Ali kdo je zaplodil rosne kaplje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Iz čigave maternice je prišel led? In slana z neba, kdo jo je zaplodil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Vode so skrite kakor s kamnom in obličje globine je zamrznjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Lahko združiš prijetne vplive Gostosevcev ali razvežeš čete Oriona?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Lahko privedeš ozvezdje v svojem obdobju? Lahko usmerjaš Arkturja z njegovimi sinovi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Ali poznaš odredbe neba? Lahko vzpostaviš njihovo gospostvo na zemlji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Mar lahko dvigneš svoj glas k oblakom, da te lahko pokrije obilje voda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Mar lahko pošlješ bliske, da lahko gredo in ti rečejo: »Tukaj smo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kdo je v notranje dele položil modrost? Ali kdo je dal srcu razumevanje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kdo lahko v modrosti prešteje oblake? Ali kdo lahko zadržuje mehove neba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'ko se prah strjuje in se grude trdno sprimejo skupaj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Mar boš lovil plen za leva? Ali tešil apetit mladim levom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'ko ležijo v svojih brlogih in ostajajo v skrivališču, da prežijo v zasedi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kdo krokarju pripravlja njegovo hrano? Ko njegovi mladiči kličejo k Bogu, se potikajo zaradi pomanjkanja hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Poznaš čas, ko divje skalne koze kotijo? Mar lahko zaznamuješ kdaj košute povržejo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Mar lahko šteješ mesece, ki so jih dopolnile? Ali poznaš čas, ko kotijo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Sklonijo se in skotijo svoje mlade, odvržejo svoje bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Njihovi mladiči so v dobri naklonjenosti, rastejo z žitom, gredo naprej in se ne vrnejo k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kdo je divjega osla izpustil na prostost? Ali kdo je odvezal vezi divjega osla?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Čigar hišo sem naredil divjino in jalovo deželo njegova prebivališča?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Zasmehuje mestno množico niti se ne ozira na vpitje voznika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Razpon gora je njegov pašnik in preiskuje za vsako zeleno stvarjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Mar ti bo samorog voljan služiti, ali ostane pri tvojih jaslih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Ali lahko s svojim jermenom zvežeš samoroga v brazdo? Ali bo za teboj branal doline?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Mu boš zaupal, ker je njegova moč velika? Ali boš svoje trdo delo prepustil njemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Mu boš verjel, da bo tvoje seme pripeljal domov in ga zbral v tvoj skedenj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Daješ pavom čedne peruti? Ali peruti in peresa noju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Ki zapušča svoja jajca na zemlji in jih ogreva v prahu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'in pozablja, da jih stopalo lahko zdrobi ali da jih divja žival lahko stre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Trda je do svojih malih, kakor da ne bi bili njeni. Brez strahu je, da je njeno trdo delo zaman,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'ker ji je Bog odrekel modrost niti ji ni podelil razumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Ko se dvigne visoko, zasmehuje konja in njegovega jezdeca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Si ti dal konju moč? Si ti njegov vrat oblekel z grivo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, '§ Ga lahko narediš prestrašenega kakor kobilico? Slava njegovih nosnic je strašna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Grebe v dolini in se veseli v svoji moči. Gre naprej, da sreča oborožene ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Zasmehuje strah in ni zgrožen niti se pred mečem ne obrača nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Tul za puščice rožlja ob njem, lesketajoča sulica in ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Tla požira z okrutnostjo in besom. Niti ne verjame, da je to zvok šofarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Med šofarji hrže: ›Hi, hi‹ in od daleč voha bitko, grmenje poveljnikov in bojni krik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Mar sokol leti po svoji modrosti in svoje peruti razpenja proti jugu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Mar se orlica vzpenja ob tvoji zapovedi in svoje gnezdo dela na višini?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Prebiva in ostaja na skali, na skalni pečini in trdnem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Od tam si išče plen in njene oči zrejo daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Tudi njeni mladiči srkajo kri. In kjer so umorjeni, tam je ona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Poleg tega je Gospod odgovoril Jobu in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '»Mar ga bo tisti, ki se prička z Vsemogočnim, poučeval? Kdor graja Boga, naj mu to odgovori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Potem je Job odgovoril Gospodu in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '»Glej, nepomemben sem, kaj naj ti odgovorim? Svojo roko bom položil na svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Enkrat sem govoril, toda ne bom odgovoril. Da, dvakrat, vendar ne bom nadaljeval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Potem je Gospod iz vrtinčastega vetra odgovoril Jobu in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '»Opaši sedaj svoja ledja kakor mož. Zahteval bom od tebe in ti mi razglasi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Hočeš tudi mojo sodbo razveljaviti? Me hočeš obsoditi, da bi bil ti lahko pravičen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Ali imaš laket kakor Bog? Ali lahko zagrmiš z glasom kakor on?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Odeni se sedaj z veličanstvom in odličnostjo in odeni se s slavo in lepoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Izlij bes svoje jeze. Glej vsakogar, ki je ponosen in ga ponižaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Poglej na vsakogar, ki je ponosen in ga ponižaj in zlobne pomendraj na njihovem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Skupaj jih skrij v prah in njihove obraze obveži na skrivnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Potem ti bom tudi jaz priznal, da te tvoja lastna desnica lahko reši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Glej torej behemota, ki sem ga naredil s teboj; muli travo kakor vol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Glej torej, njegova moč je v njegovih ledjih in njegova sila je v kiti njegovega trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Svoj rep premika kakor cedra. Kite njegovih kamnov so ovite skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Njegove kosti so kakor trdi koščki iz brona, njegove kosti so podobne železnim zapahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Ta je vodja Božjih poti. Kdor ga je naredil lahko stori, da se mu približa njegov meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Zagotovo mu gore prinašajo hrano, kjer se igrajo vse poljske živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Leži pod senčnimi drevesi, v skrivališču trstja in močvirij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Senčna drevesa ga pokrivajo s svojo senco, naokoli ga obdajajo potočne vrbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Glej, pije reko in ne hiti; zaupa, da lahko Jordan posrka v svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Ujame ga s svojimi očmi. Njegov nos prebada skozi zanke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Zmoreš s kavljem izvleči leviatána? Ali njegov jezik z vrvico, ki jo spuščaš dol?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Ali lahko zatakneš kavelj v njegov nos? Ali njegovo čeljust prebodeš z [ribiško] ostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Mar ti bo delal mnoge ponižne prošnje? Ti bo govoril nežne besede?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Bo sklenil zavezo s teboj? Ga boš vzel za služabnika na veke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Se boš igral z njim kakor s ptico? Ali ga hočeš zvezati za svoje dekle?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Ali bodo družabniki iz njega naredili gostijo? Ga bodo razdelili med trgovce?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Lahko njegovo kožo napolniš z bodečimi žicami? Ali njegovo glavo z ribjimi sulicami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Svojo roko položi nanj, spomni se bitke, ne stori tega ponovno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Glej, njegovo upanje je zaman. Ali ne bo nekdo vržen dol, celo ko ga zagleda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Nihče ni tako pogumen, da bi si ga drznil razvneti. Kdo je potem zmožen stati pred menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kdo mi je preprečil, da bi mu poplačal? Karkoli je pod celotnim nebom, je moje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Ne bom prikril njegovih delov, niti njegove moči, niti njegovega lepega razmerja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kdo lahko odkrije obraz njegove obleke? Ali kdo lahko pride k njemu, s svojo dvojno uzdo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Kdo lahko odpre vrata njegovega obraza? Njegovi zobje na vsaki strani so strašni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Njegove luske so njegov ponos, skupaj spete kakor z ozkim pečatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Ena je blizu druge, da zrak ne more priti mednju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Združene so druga z drugo, držijo se skupaj, da ne morejo biti ločene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Ob njegovem kihanju sije svetloba in njegove oči so podobne jutranjim vekam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Iz njegovih ust izhajajo plameni in iskre se sipljejo ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Iz njegovih nosnic gre dim kakor iz vrelega lonca ali kotla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Njegov dih prižge ogorke in plamen izhaja iz njegovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'V njegovem vratu ostaja moč in bridkost je pred njim spremenjena v radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Luskine njegovega mesa so združene skupaj. V sebi so trdne, ne morejo se omajati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Njegovo srce je čvrsto kakor kamen. Da, tako trdo kakor košček spodnjega mlinskega kamna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Ko se vzdiguje, so mogočni prestrašeni. Zaradi zlomov se očiščujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Meč tistega, ki seže proti njemu, ne more obstati, niti sulica, niti puščica, niti brezrokavna verižna srajca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Železo ceni kakor slamo in bron kakor trohnel les.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Puščica ga ne more spraviti v beg. Kamni iz prače so mu spremenjeni v strnišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Puščice so štete kakor strnišče. Smeji se ob tresenju sulice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Ostro kamenje je pod njim. Po blatu razširja ostre koničaste stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Globinam napravlja, da vrejo kakor lonec. Morje dela podobno loncu mazila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'On dela stezo, da sije za njim. Nekdo bi mislil, da bo globina osivela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Na zemlji ni njemu podobnega, ki je narejen brez strahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Gleda vse visoke stvari. Kralj je nad vsemi ponosnimi otroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Potem je Job odgovoril Gospodu in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '§ »Vem, da lahko narediš vsako stvar in da nobena misel ne more biti zadržana pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kdo je tisti, ki skriva nasvet brez spoznanja? Torej sem rekel, da ne razumem. Stvari zame prečudovite, ki jih nisem poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Prisluhni, rotim te in bom govoril. Zahteval bom od tebe in oznani mi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, '§ Slišal sem o tebi po poslušanju svojega ušesa. Toda sedaj te vidi moje oko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Torej preziram samega sebe in se kesam v prahu in pepelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'To je bilo tako, da je potem, ko je Gospod te besede govoril Jobu, Gospod rekel Elifázu Temáncu: »Moj bes je vnet zoper tebe in zoper tvoja dva prijatelja, kajti o meni niste govorili stvari, ki je pravilna, kakor je [govoril] moj služabnik Job.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Zatorej si vzemite k sebi sedem bikcev in sedem ovnov in pojdite k mojemu služabniku Jobu in zase darujte žgalno daritev, moj služabnik Job pa bo molil za vas, kajti njega bom sprejel, da ne bom z vami postopal po vaši neumnosti, v tem, da niste govorili o meni besede, ki je pravilna, kakor moj služabnik Job.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Tako so Elifáz Temánec, Bildád Suhéjec in Cofár Naámčan odšli in storili glede na to, kakor jim je Gospod zapovedal, Gospod pa je sprejel Joba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Gospod je obrnil Jobovo ujetništvo, ko je molil za svoje prijatelje. Gospod je dal Jobu tudi dvakrat toliko, kot je imel poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Potem so prišli k njemu vsi njegovi bratje in vse njegove sestre in vsi, ki so bili poprej izmed njegovih znancev in so v njegovi hiši z njim jedli kruh. Sočustvovali so in ga tolažili glede vsega zla, ki ga je Gospod privedel nadenj. Prav tako mu je vsak človek dal kos denarja in vsakdo uhan iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Tako je Gospod bolj blagoslovil Jobov poznejši konec kakor njegov začetek, kajti imel je štirinajst tisoč ovc, šest tisoč kamel, tisoč jarmov volov in tisoč oslic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Imel je tudi sedem sinov in tri hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Ime prve je imenoval Golobica, ime druge Dišavka in ime tretje Lepotica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Po vsej deželi ni bilo najti tako lepih žensk kakor Jobove hčere in njihov oče jim je dal dediščino med njihovimi brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Potem je Job živel sto štirideset let in videl svoje sinove in svojih sinov sinove, celó štiri rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Tako je Job umrl, star in izpolnjen z dnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Blagoslovljen je človek, ki ne hodi po nasvetu brezbožnih niti ne stoji na poti grešnikov niti ne poseda na sedežu posmehljivcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Temveč je njegovo veselje v Gospodovi postavi in o njegovi postavi premišljuje podnevi in ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'On bo kakor drevo, posajeno ob rekah vodá, ki prinaša svoj sad ob svojem času. Prav tako njegovo listje ne bo ovenelo in karkoli dela, bo uspelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Brezbožni niso takšni, temveč so kakor pleve, ki jih veter odnaša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Zato brezbožni ne bodo obstali na sodbi niti grešniki v skupnosti pravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Kajti Gospod pozna pot pravičnih, toda pot brezbožnih bo izginila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Zakaj besnijo pogani in ljudstvo domišlja prazno stvar?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Kralji zemlje so se usmerili in vladarji se skupaj posvetujejo zoper Gospoda in zoper njegovega maziljenca, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '»Pretrgajmo njihove vezi in odvrzimo njihove vrvi od sebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Tisti, ki sedi v nebesih, se bo smejal. Gospod jih bo imel v posmeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Potem jim bo govoril v svojem besu in jih nadlegoval v svojem bridkem nezadovoljstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '»Vendarle sem jaz postavil svojega kralja na svoji sveti gori Sion.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Oznanil bom odlok. Gospod mi je rekel: »Ti si moj Sin. Ta dan sem te rodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Zahtevaj od mene in dal ti bom pogane za tvojo dediščino in najbolj oddaljene kraje zemlje za tvojo posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Zdrobil jih boš z železno palico, raztreščil jih boš na koščke kakor lončarjevo posodo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Zatorej bodite sedaj modri, oh vi kralji. Dajte se poučiti, vi sodniki zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Gospodu služite s strahom in veselite se s trepetanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, '§ Poljubite Sina, da ne bi bil jezen in ne izginete iz poti, ko je njegov bes le malo razvnet. Blagoslovljeni so vsi, ki svoje upanje položijo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Davidov psalm, ko je bežal pred svojim sinom Absalomom. Gospod, kako so se okrepili ti, ki me vznemirjajo! Številni so tisti, ki se vzdigujejo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Mnogo jih je, ki pravijo o moji duši: »Zanj ni pomoči pri Bogu.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Toda ti, oh Gospod, si zame ščit, moja slava in tisti, ki mi dviguje mojo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'S svojim glasom sem jokal h Gospodu in slišal me je iz svoje svete gore. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Zleknil sem se in spal, prebudil sem se, kajti Gospod me je podpiral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ne bom se bal deset tisočev ljudi, ki so se okrog in okrog usmerili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Vstani, oh Gospod, reši me, oh moj Bog. Kajti vse moje sovražnike si udaril po čeljusti, razbil si zobe brezbožnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Rešitev duše pripada Gospodu. Nad tvojim ljudstvom je tvoj blagoslov. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Vodji glasbenikov na Neginot, Davidov psalm. Poslušaj me, kadar kličem, oh Bog moje pravičnosti. Osvobodil si me, ko sem bil v stiski, usmili se me in usliši mojo molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Oh vi človeški sinovi, doklej boste mojo slavo spreminjali v sramoto? Kako dolgo boste ljubili prazne reči in iskali laž? Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Toda vedite, da je Gospod zase oddvojil tistega, ki je bogaboječ. Gospod bo slišal, kadar kličem k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, '§ Stoj v strahospoštovanju in ne greši. Na svoji postelji se posvetuj s svojim lastnim srcem in miruj. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Daruj klavne daritve pravičnosti in svoje trdno upanje položi v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Mnogi so, ki pravijo: »Kdo nam bo pokazal karkoli dobrega?« Gospod, dvigni nad nami svetlobo svojega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'V moje srce si položil veselje, več kot v času, ko je naraslo njihovo žito in njihovo vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'V miru se bom ulegel in spal. Kajti samo ti, Gospod, mi daješ prebivati na varnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Vodji glasbenikov na piščali, Davidov psalm. Pazljivo prisluhni mojim besedam, oh Gospod, preudari moje premišljevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Prisluhni glasu mojega klica, moj Kralj in moj Bog. Kajti k tebi bom molil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Zjutraj boš slišal moj glas, oh Gospod, zjutraj bom svojo molitev usmeril k tebi in pogledal bom kvišku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Kajti ti nisi Bog, ki ima veselje v zlobnosti. Niti zlo ne bo prebivalo s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Nespametni ne bo obstal v tvojem pogledu. Ti sovražiš vse delavce krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Uničil boš te, ki govorijo laž. Gospodu se bodo gnusili krvoločni in varljivi ljudje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Toda kar se mene tiče, bom prišel v tvojo hišo v mnoštvu tvojega usmiljenja. In v tvojem strahu bom oboževal k tvojemu svetemu templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Vodi me, oh Gospod, v svoji pravičnosti, zaradi mojih sovražnikov, svojo pot izravnaj pred mojim obrazom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Kajti v njihovih ustih ni zvestobe, njihov notranji del je sama zlobnost, njihovo grlo je odprt mavzolej, laskajo s svojim jezikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Uniči jih, oh Bog, naj padejo po svojih lastnih nasvetih, izženi jih v množico njihovih prestopkov, kajti uprli so se zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Vendar pa naj se veselijo vsi tisti, ki svoje trdno upanje polagajo vate. Naj vedno vzklikajo od veselja, ker jih ti braniš. Naj se tudi tisti, ki ljubijo tvoje ime, radostijo v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Kajti ti, Gospod, boš blagoslovil pravičnega, kakor s ščitom ga hočeš obdati z naklonjenostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Vodji glasbenikov na Neginot, v oktavi, Davidov psalm. Oh Gospod, ne oštevaj me v svoji jezi niti me ne karaj v svojem silnem nezadovoljstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Usmili se me, oh Gospod, kajti slaboten sem. Oh Gospod, ozdravi me, kajti moje kosti so nadlegovane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Moja duša je prav tako boleče nadlegovana. Toda ti, oh Gospod, doklej?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, '§ Vrni se, oh Gospod, osvobodi mojo dušo. Oh reši me zaradi svojega usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Kajti v smrti ni spomina nate. Kdo se ti bo zahvaljeval v grobu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Izmučen sem zaradi svojega stokanja, vso noč močim svojo posteljo, svoje ležišče zalivam s svojimi solzami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, '§ Moje oko je iztrošeno zaradi žalosti, ostareva zaradi vseh mojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Ločite se od mene, vsi vi delavci krivičnosti, kajti Gospod je slišal glas mojega jokanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Gospod je uslišal mojo ponižno prošnjo, Gospod bo sprejel mojo molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Naj bodo osramočeni vsi moji sovražniki in boleče nadlegovani. Naj se vrnejo in naj bodo nenadoma osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Davidov Šigajon, ki ga je pel Gospodu glede besed Benjaminovca Kuša. Oh Gospod, moj Bog, vate polagam svoje trdno upanje. Reši me pred vsemi temi, ki me preganjajo in me osvobodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Da ne bi moje duše razkosali kakor lev, ki jo raztrga na koščke, medtem ko ni nobenega, da osvobodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Oh Gospod, moj Bog, če sem to storil, če je krivičnost v mojih rokah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'če sem z zlom nagradil tistega, ki je bil z menoj v miru (da, osvobodil sem tistega, ki je brez vzroka moj sovražnik),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'naj sovražnik preganja mojo dušo in jo vzame; da, naj moje življenje pomendra na zemlji in mojo čast položi v prah. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Vstani, oh Gospod, v svoji jezi, vzdigni se zaradi besa mojih sovražnikov. Prebudi se zame k sodbi, ki si jo zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Tako te bo obdajala skupnost ljudstva. Zaradi njih se torej vrni na višavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Gospod bo sodil ljudstvo. Sodi me, oh Gospod, glede na mojo pravičnost in glede na mojo neokrnjenost, ki je v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, '§ O naj zlobnost zlobnih pride h koncu; toda utrdi pravičnega. Kajti pravičnim Bog preizkuša srca in notranjosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Moja obramba je od Boga, ki rešuje iskrene v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bog sodi pravičnega in Bog je vsak dan jezen na zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Če se ta ne spreobrne, bo nabrusil svoj meč, upognil je svoj lok in ga pripravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, '§ Prav tako je zanj pripravil orodja smrti, svoje puščice je določil zoper preganjalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Glej, muči se s krivičnostjo in spočel je vragolijo in obrodil neresnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Naredil je jamo in jo izkopal in padel v jarek, ki ga je naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Njegova vragolija se bo vrnila na njegovo lastno glavo in njegovo nasilno delovanje bo prišlo na njegovo lastno tême.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Hvalil bom Gospoda glede na njegovo pravičnost. Prepeval bom hvalo imenu Gospoda najvišjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Vodji glasbenikov na Gitít, Davidov psalm. Oh Gospod, naš Gospod, kako odlično je tvoje ime na vsej zemlji! Ki si svojo slavo postavil nad nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Iz ust otročičev in dojenčkov si zaradi svojih sovražnikov odredil moč, da bi lahko utišal sovražnika in maščevalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Ko opazujem tvoje nebo, delo tvojih prstov, luno in zvezde, ki si jih odredil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'kaj je človek, da misliš nanj? In človeški sin, da ga obiskuješ?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Kajti naredil si ga malo nižjega kot angele in ga okronal s slavo in častjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Naredil si, da ima gospostvo nad deli tvojih rok; vse stvari si položil pod njegova stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Vse ovce in vole, da in poljske živali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'zračno perjad in ribe morja in karkoli se giblje skozi morske steze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Oh Gospod, naš Gospod, kako odlično je tvoje ime na vsej zemlji!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Vodji glasbenikov na Mut labbén, Davidov psalm. Hvalil te bom, oh Gospod, z vsem svojim srcem, naznanil bom vsa tvoja čudovita dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Vesel bom in se radoval v tebi. Prepeval bom hvalo tvojemu imenu, oh ti Najvišji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ko so moji sovražniki odbiti, bodo ob tvoji prisotnosti padli in se pogubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Kajti ohranjal si mojo pravico in mojo pravdo, posedèn si na prestolu, pravično razsojaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Oštel si pogane, uničil zlobne, njihovo ime si iztrebil na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Oh ti sovražnik, uničenja so prišla k večnemu koncu. Uničil si mesta, njihov spomin je bil z njimi pogubljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Toda Gospod bo ostal na veke. Svoj prestol je pripravil za sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Zemeljski [krog] bo sodil v pravičnosti, ljudstvu bo razsojal sodbo v poštenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Gospod bo prav tako zatočišče za zatirane, zatočišče v časih stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Tisti, ki poznajo tvoje ime, bodo svoje trdno upanje položili vate, kajti ti, Gospod, nisi zapustil teh, ki te iščejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Prepevajte hvalnice Gospodu, ki prebiva na Sionu. Med ljudstvom oznanjajte njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Spominja se jih, ko zaslišuje zaradi krvi. Ne pozablja klica ponižnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Usmili se me, oh Gospod, preudari mojo stisko, ki jo trpim od tistih, ki me sovražijo, ti, ki me povzdiguješ izpred velikih vrat smrti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'da bom pri velikih vratih hčere sionske lahko naznanjal vso tvojo hvalo. Veselil se bom v tvoji rešitvi duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Pogani so se pogreznili v jamo, ki so jo naredili. V mrežo, ki so jo skrili, je ujeto njihovo lastno stopalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Gospod je znan po sodbi, ki jo izvršuje. Zlobni je ujet v dela svojih lastnih rok. Higajon. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, '§ Zlobni bodo napoteni v pekel in vsi narodi, ki pozabljajo Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Kajti pomoči potreben ne bo vedno pozabljen. Pričakovanje ubogega na veke ne bo izginilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Vstani, oh Gospod, naj ne prevlada človek. Naj bodo pogani sojeni v tvojem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Postavi jih v strah, oh Gospod, da bodo narodi lahko spoznali, da so sami zgolj ljudje. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Zakaj stojiš daleč stran, oh Gospod? Zakaj se skrivaš v časih stiske?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Zlobni v svojem ponosu preganjajo revnega. Naj se ujamejo v naklepe, ki so si jih domislili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Kajti zlobni se baha z željo svojega srca in blagoslavlja pohlepnega, ki ga Gospod prezira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Zlobni zaradi ponosa svojega obličja ne bo povpraševal po Bogu. V vseh njegovih mislih ni Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Njegove poti so vedno boleče, tvoje sodbe so daleč zgoraj izven njegovega pogleda. Glede na vse njegove sovražnike on puha nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'V svojem srcu je rekel: »Ne bom omajan, kajti nikoli ne bom v nadlogi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Njegova usta so polna preklinjanj, prevare in sleparstva. Pod njegovim jezikom je vragolija in prazne reči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Sedi v skrivališčih vasi. Na skrivnih krajih mori nedolžnega. Njegove oči so na skrivaj naravnane zoper revnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Na skrivnem preži kakor lev v svojem brlogu. Leži na preži, da ujame revnega. Revnega ujame, ko ga vleče v svojo mrežo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Klečeplazi in se ponižuje, da lahko revni pade po njegovih močnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'V svojem srcu je rekel: »Bog je pozabil. Skriva svoj obraz, tega nikoli ne bo videl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Vstani, oh Gospod, oh Bog, dvigni svojo roko. Ne pozabi ponižnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, '§ Zakaj zlobni zaničuje Boga? V svojem srcu je rekel: »Ti tega ne boš zahteval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'To si videl, kajti gledaš vragolijo in zlobnost, da to poplačaš s svojo roko. Revni se ti izroča, pomočnik si osirotelemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zlomi laket zlobnemu in zlemu človeku. Preiskuj njegovo zlobnost, dokler je ne najdeš več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Gospod je Kralj na veke vekov. Pogani so izginili iz njegove dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Gospod, slišal si hrepenenje ponižnih. Pripravil boš njihovo srce, svojemu ušesu boš povzročil, da sliši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'da razsodiš osirotelega in zatiranega, da človek iz zemlje ne more več zatirati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Vodji glasbenikov, Davidov psalm. Svoje trdno upanje polagam v Gospoda. Kako pravite moji duši: »Béži kakor ptica k svoji gori?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Kajti glej, zlobni upogibajo svoj lok, svojo puščico pripravljajo na tetivo, da bi lahko na skrivaj streljali na iskrenega v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Če so temelji razrušeni, kaj lahko stori pravični?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Gospod je v svojem svetem templju, Gospodov prestol je na nebu. Njegove oči gledajo, njegove veke preizkušajo človeške otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Gospod preizkuša pravičnega. Toda zlobnega in tistega, ki ljubi nasilje, sovraži njegova duša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Na zlobne bo deževal pasti, ogenj, žveplo in strašen vihar. To bo delež njihove skodelice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Kajti pravičen Gospod ljubi pravičnost, njegovo obličje gleda iskrenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Vodji glasbenikov na oktavo, Davidov psalm. Pomagaj, Gospod, kajti bogaboječi človek izginja, kajti zvesti izmed človeških otrok slabi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Prazne reči govorijo vsak s svojim bližnjim. Govorijo z laskavimi ustnicami in dvoličnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Gospod bo iztrebil vse laskave ustnice in jezik, ki govori ponosne stvari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'ki so rekli: »S svojim jezikom bomo prevladali, naše ustnice so naša last. Kdo je gospodar nad nami?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '»Zaradi zatiranja siromašnega, zaradi vzdihovanja pomoči potrebnega se bom sedaj vzdignil,« govori Gospod, »postavil ga bom na varno pred tistim, ki se napihuje nad njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Gospodove besede so čiste besede; kakor srebro, preizkušeno v zemljini talilni peči, sedemkrat prečiščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, '§ Ti jih boš varoval, oh Gospod, pred tem rodom jih boš ohranil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Zlobni hodijo na vsaki strani, ko so najnizkotnejši ljudje povišani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Vodji glasbenikov, Davidov psalm. Doklej me boš pozabljal, oh Gospod? Na veke? Doklej boš svoj obraz skrival pred menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Doklej se bom posvetoval v svoji duši, imel vsak dan bridkost v svojem srcu? Doklej se bo moj sovražnik poviševal nad menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Preudari in poslušaj me, oh Gospod, moj Bog. Razsvetli moje oči, da ne zaspim spanja smrti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'da ne bi moj sovražnik rekel: »Prevladal sem proti njemu« in da se tisti, ki me mučijo, ne veselijo, ko sem omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Toda jaz sem zaupal v tvoje usmiljenje; moje srce se bo veselilo v tvoji rešitvi duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Prepeval bom Gospodu, ker je radodarno ravnal z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Vodji glasbenikov, Davidov psalm. Bedak je rekel v svojem srcu: »Ni Boga.« Izprijeni so, počeli so gnusna dela, nikogar ni, ki dela dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Gospod je pogledal dol z neba na človeške otroke, da vidi, ali obstaja kdorkoli, ki je razumel in išče Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Vsi so odšli vstran, vsi skupaj so postali pokvarjeni. Nikogar ni, ki dela dobro, ne, niti enega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Mar vsi delavci krivičnosti nimajo spoznanja? Ki žro moje ljudstvo, kakor jedo kruh, pa ne kličejo h Gospodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Bili so v velikem strahu, kajti Bog je z rodom pravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Sramotili ste nasvet siromašnega, zato ker je Gospod njegovo pribežališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oh, da bi Izraelova rešitev duš prišla iz Siona! Ko Gospod privede nazaj ujete svojega ljudstva, se bo Jakob veselil in Izrael bo vesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Davidov psalm. Gospod, kdo bo prebival v tvojem šotorskem svetišču? Kdo bo prebival na tvoji sveti gori?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Kdor živi pošteno in dela pravično in v svojem srcu govori resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Kdor ne opravlja s svojim jezikom niti ne dela zla svojemu bližnjemu niti ne sprejema graje zoper svojega bližnjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'V čigar očeh je podla oseba zaničevana, toda počasti tiste, ki se bojijo Gospoda. Ki prisega v svojo lastno škodo in se ne premisli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Kdor ne izdaja svojega denarja za obresti niti ne sprejema nagrade zoper nedolžnega. Kdor dela te stvari, nikoli ne bo omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Davidov miktám. Varuj me, oh Bog, kajti vate polagam svoje trdno upanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'O moja duša, Gospodu si rekla: »Ti si moj Gospod. Moja dobrota se ne razteza do tebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'temveč k svetim, ki so na zemlji in k odličnim, v katerih je vse moje zadovoljstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Njihove bridkosti se bodo pomnožile, ki hitijo za drugim bogom. Njihovih krvavih pitnih daritev ne bom daroval niti njihovih imen ne bom jemal na svoje ustnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Gospod je delež moje dediščine in moje skodelice. Ti ohranjaš mojo usodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Vrvice so mi padle na prijetnih krajih; da, lepo dediščino imam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Blagoslavljal bom Gospoda, ki mi je dal nasvet. Moja notranjost me prav tako poučuje v nočnih obdobjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Vedno sem pred seboj postavljal Gospoda; ker je pri moji desnici, ne bom omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Zato je moje srce veselo in moja slava se razveseljuje; tudi moje meso bo počivalo v upanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Kajti moje duše ne boš pustil v peklu niti ne boš trpel, da bi tvoj Sveti videl trohnobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Pokazal mi boš stezo življenja. V tvoji prisotnosti je polnost radosti, pri tvoji desnici so zadovoljstva na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Davidova molitev. Usliši iskrenega, oh Gospod, bodi pozoren na moj klic, pazljivo prisluhni moji molitvi, ki ne prihaja iz hlinjenih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Naj moja razsodba pride iz tvoje prisotnosti, naj tvoje oči gledajo stvari, ki so pravične.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Preizkusil si moje srce, obiskal si me ponoči, preizkusil si me, pa ničesar nisi našel; odločen sem, da moja usta ne bodo grešila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Kar se tiče človeških del, sem se po besedi tvojih ustnic varoval pred stezami uničevalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Podpiraj mojo smer življenja po tvojih stezah, da moje stopinje ne zdrsnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Klical sem k tebi, kajti uslišal me boš, oh Bog. Nagni k meni svoje uho in usliši moj govor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Pokaži svojo čudovito ljubečo skrbnost, oh ti, ki s svojo desnico rešuješ tiste, ki svoje trdno upanje polagajo vate pred tistimi, ki se vzdigujejo proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Varuj me kakor zenico očesa, skrij me pod senco svojih peruti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'pred zlobnimi, ki me zatirajo, pred mojimi smrtnimi sovražniki, ki me obdajajo naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Zajeti so v svojo lastno maščobo. S svojimi usti govorijo ponosno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Sedaj so nas obdali na naših korakih. Svoje oči so naravnali in pripognili k zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'kakor lev, ki je pohlepen po svojem plenu in kakor bi bil mlad lev, ki preži na skrivnih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Vzdigni se, oh Gospod, razočaraj ga, vrzi ga dol. Osvobodi mojo dušo pred zlobnim, kar je tvoj meč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'pred ljudmi, ki so tvoja roka, oh Gospod, pred ljudmi sveta, ki imajo svoj delež v tem življenju in katerih trebuh napolnjuješ s svojim skritim zakladom. Polni so otrok in preostanek svojega imetja zapustijo svojim otročičem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Kar se mene tiče, bom v pravičnosti gledal tvoj obraz. Ko se zbudim, bom nasičen s tvojo podobnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Vodji glasbenikov, Psalm Davida, Gospodovega služabnika, ki je Gospodu govoril besede te pesmi na dan, ko ga je Gospod osvobodil iz roke vseh njegovih sovražnikov in iz Savlove roke. Rekel je: Ljubil te bom, oh Gospod, moja moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Gospod je moja skala, moja trdnjava in moj osvoboditelj, moj Bog, moja moč, v katero bom zaupal, moj ščit in rog rešitve moje duše in moj visoki stolp.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Klical bom h Gospodu, ki je vreden, da je hvaljen. Tako bom rešen pred svojimi sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Obdale so me bridkosti smrti in poplave brezbožnih ljudi so me prestrašile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Obkrožile so me bridkosti pekla. Zanke smrti so me ovirale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'V svoji stiski sem klical h Gospodu in jokal k svojemu Bogu. Iz svojega templja je slišal moj glas in moj jok je prišel predenj, celó v njegova ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Potem se je zemlja stresla in zatrepetala, tudi temelji gora so se premaknili in bili streseni, ker je bil ogorčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Iz njegovih nosnic je izšel dim in ogenj iz njegovih ust je požiral. Ogorki so bili prižgani z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Uklonil je tudi nebo in prišel dol. Tema je bila pod njegovimi stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Jezdil je na kerubu in letel. Da, letel je na perutih vetra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Temo je naredil [za] svoj skriti kraj, njegov paviljon okoli njega so bile temne vode in gosti oblaki neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Ob sijaju, ki je bil pred njim, so šli mimo njegovi gosti oblaki, zrna toče in ognjeno oglje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Gospod je tudi zagrmel v nebesih in Najvišji je dal svoj glas, zrna toče in ognjeno oglje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Da, poslal je svoje puščice in jih razkropil in izstrelil bliske ter jih porazil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Potem so bila vidna rečna korita in temelji zemeljskega [kroga] so bili odkriti ob tvojem oštevanju, oh Gospod, ob pišu diha iz tvojih nosnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Poslal je od zgoraj, me vzel, me potegnil iz mnogih voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Osvobodil me je pred mojim močnim sovražnikom in pred temi, ki so me sovražili, kajti zame so bili premočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Ovirali so me na dan moje katastrofe. Toda Gospod je bil moja opora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Privedel me je tudi na velik kraj, osvobodil me je, ker se je razveseljeval v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Gospod me je nagradil glede na mojo pravičnost, glede na čistost mojih rok mi je poplačal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Kajti obdržal sem Gospodove poti in se nisem zlobno oddvojil od svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Kajti vse njegove sodbe so bile pred menoj in njegovih zakonov nisem odvrnil od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Pred njim sem bil tudi pošten in se varoval pred svojo krivičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Zaradi tega mi je Gospod poplačal glede na mojo pravičnost, glede na čistost mojih rok v svojem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Z usmiljenim se boš pokazal usmiljenega, s poštenim človekom se boš pokazal poštenega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 's čistim se boš pokazal čistega in s kljubovalnim se boš pokazal kljubovalnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Kajti rešil boš stiskano ljudstvo, toda ponižal boš vzvišene poglede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Kajti prižgal boš mojo svečo. Gospod, moj Bog, bo razsvetlil mojo temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Kajti s teboj sem tekel skozi krdelo in s svojim Bogom sem preskočil zid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Glede Boga, njegova pot je popolna. Gospodova beseda je preizkušena; on je ščit vsem, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Kajti kdo je Bog, razen Gospoda? Ali kdo je skala, razen našega Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Bog je ta, ki me opasuje z močjo in moje poti dela popolne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Moja stopala dela podobna stopalom košute in me postavlja na moja visoka mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, '§ Úči moje roke za vojno, tako da je jeklen lok zlomljen z mojimi lakti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Dal si mi tudi ščit tvoje rešitve duše in tvoja desnica me podpira in tvoja blagost me je naredila velikega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Pod menoj si razširil moje korake, da moja stopala niso zdrsnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Zasledoval sem svoje sovražnike in jih dohitevam. Niti se nisem ponovno obrnil, dokler niso bili uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Ranil sem jih, da niso mogli vstati. Padli so pod moja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Kajti opasal si me z močjo za boj. Podjarmil si mi tiste, ki vstajajo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Prav tako si mi dal vratove mojih sovražnikov, da lahko uničim te, ki me sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Vpili so, toda nikogar ni bilo, da jih reši, celó h Gospodu, toda ni jim odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Potem sem jih mlatil, majhne kakor prah pred vetrom. Spodil sem jih kakor nesnago na ulicah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Osvobodil si me pred človeškimi prepiri in me naredil za poglavarja poganom. Ljudstvo, ki ga nisem poznal, mi bo služilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Takoj, ko bodo zaslišali o meni, me bodo ubogali. Tujci se mi bodo podredili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Tujci bodo bledeli in prestrašeni bodo iz svojih ograjenih prostorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Gospod živi in blagoslovljena bodi moja skala in vzvišen naj bo Bog rešitve moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'To je Bog, ki me maščuje in ljudstva podjarmlja pod menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Osvobaja me pred mojimi sovražniki. Da, dviguješ me nad tiste, ki se dvigujejo zoper mene. Osvobodil si me pred nasilnežem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Zatorej se ti bom zahvaljeval med pogani, oh Gospod in prepeval hvalnice tvojemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Svojemu kralju on daje veliko osvoboditev in izkazuje usmiljenje svojemu maziljencu Davidu in njegovemu semenu na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Vodji glasbenikov, Davidov psalm. Nebo oznanja Božjo slavo in nebesni svod prikazuje delo njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Dan dnevu izreka govor in noč noči prikazuje znanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ni ne govora, ne jezika, kjer ni slišati njihovega glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Njihov stih gre po vsej zemlji in njihove besede do konca zemeljskega [kroga]. Vanje je postavil šotorsko svetišče za sonce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'ki je kakor ženin, ki prihaja iz svoje sobe in se razveseljuje kakor močan mož, da teče tek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Njegovo prihajanje je od konca neba in njegov obhod do njegovih koncev. Nič ni skrito pred njegovo vročino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Gospodova postava je popolna, spreobrača dušo. Gospodovo pričevanje je zanesljivo, preprostega dela modrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Gospodova pravila so pravilna, razveseljujejo srce. Gospodova zapoved je čista in razsvetljuje oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Gospodov strah je čist, ostaja na veke. Gospodove sodbe so resnične in vse skupaj pravične.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Bolj si jih je želeti kakor zlata, da, kakor mnogo čistega zlata. Slajše so tudi kakor med in satovje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Poleg tega je tvoj služabnik posvarjen po njih. In v njihovem izpolnjevanju je velika nagrada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Kdo lahko razume njegove zmote? Očisti me pred skrivnimi krivdami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Svojega služabnika zadrži tudi pred prevzetnimi grehi; naj nimajo gospostva nad menoj. Potem bom lahko pošten in bom nedolžen pred velikim prestopkom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Naj bodo besede mojih ust in premišljevanje mojega srca sprejemljive v tvojem pogledu, oh Gospod, moja moč in moj odkupitelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Vodji glasbenikov, Davidov psalm. Gospod te sliši na dan stiske, ime Jakobovega Boga te brani,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'pošlje ti pomoč iz svetišča in te okrepi s Siona,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'spominja se vseh tvojih daritev in sprejema tvojo žgalno daritev. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Usliši te glede na tvoje lastno srce in izpolni vso tvojo namero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Veselili se bomo v tvoji rešitvi duše in svoje prapore bomo postavili v imenu svojega Boga. Gospod izpolnjuje vse tvoje prošnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Sedaj vem, da Gospod rešuje svojega maziljenca; iz svojih svetih nebes ga bo uslišal z rešujočo močjo svoje desnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nekateri zaupajo v bojne vozove, nekateri pa v konje, toda mi se bomo spominjali imena Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Oni so ponižani in padli, toda mi vstanemo in stojimo pokončno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Reši, Gospod. Naj nas sliši kralj, ko kličemo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Vodji glasbenikov, Davidov psalm. Kralj se bo veselil v tvoji moči, oh Gospod in kako silno se bo radoval v tvoji rešitvi duše!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Dal si mu željo njegovega srca in nisi zadržal prošnje njegovih ustnic. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Kajti vodiš ga z blagoslovi dobrote. Na njegovo glavo postavljaš krono iz čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Prosil te je življenja in ti mu ga daješ, celó dolžino dni na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Njegova slava v tvoji rešitvi duše je velika. Čast in veličanstvo si položil nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Kajti naredil si ga najbolj blagoslovljenega na veke. S svojim obličjem si ga storil silno veselega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Kajti kralj zaupa v Gospoda in zaradi usmiljenja Najvišjega ne bo omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Tvoja roka bo zalotila vse tvoje sovražnike. Tvoja desnica bo zalotila tiste, ki te sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'V času svoje jeze jih boš naredil kakor ognjeno peč. Gospod jih bo v svoji jezi pogoltnil in ogenj jih bo požrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Njihov sad boš uničil z zemlje in njihovo seme izmed človeških otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Kajti zoper tebe so načrtovali zlo. Domislili so si poguben naklep, ki ga niso mogli izpolniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Zato boš storil, da bodo obrnili svoj hrbet, ko boš pripravil svoje puščice na tetive proti njihovim obrazom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Bodi vzvišen, Gospod, v svoji lastni moči. Tako bomo opevali in hvalili tvojo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Vodji glasbenikov na Košuta zore, Davidov psalm. Moj Bog, moj Bog, zakaj si me zapustil? Zakaj si tako daleč proč od pomoči meni in od besed mojega vpitja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Oh moj Bog, jokam podnevi, toda ti me ne uslišiš in v nočnem času in nisem tiho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Toda ti si svet, oh ti, ki naseljuješ Izraelove hvalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Naši očetje so zaupali vate. Zaupali so in si jih osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Klicali so k tebi in so bili osvobojeni. Zaupali so vate in niso bili zbegani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Toda jaz sem [škrlatni] črv in ne mož; graja ljudem in preziran od ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Vsi, ki me vidijo, se mi smejijo do norčevanja. Namrdnejo ustnico [in] zmajujejo z glavo, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '»Zaupal je v Gospoda, da ga bo osvobodil. Naj ga reši, glede na to, da se je razveseljeval v njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Toda ti si ta, ki me je potegnil iz maternice. Oblikoval si mi zaupanje, ko sem bil na prsih svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Iz maternice sem bil vržen nate. Ti si moj Bog od trebuha moje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Ne bodi daleč od mene, kajti stiska je blizu, kajti nikogar ni, da pomaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Obdalo me je mnogo bikov. Močni bašánski biki so me obdali naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'S svojimi gobci so zevali vame, kakor ropa željan in rjoveč lev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Izlit sem kakor voda in vse moje kosti so izpahnjene. Moje srce je podobno vosku, stopljeno je v sredi moje notranjosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Moja moč je izsušena kakor črepinja in moj jezik se lepi k mojim čeljustim in ti si me privedel v smrtni prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Kajti psi so me obdali. Zajel me je zbor zlobnih. Prebodli so moje roke in moja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Vse svoje kosti lahko razločim. Oni pa gledajo in strmijo vame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Moje obleke si razdeljujejo med seboj in za mojo suknjo so metali žrebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Toda ti, oh Gospod, ne bodi daleč od mene. Oh moja moč, hiti, da mi pomagaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Osvobodi mojo dušo pred mečem, mojo ljubljeno pred močjo psa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Reši me pred levjimi usti, kajti uslišal si me pred rogovi samorogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Tvoje ime bom oznanjal svojim bratom. Na sredi skupnosti te bom hvalil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vi, ki se bojite Gospoda, hvalite ga, vsi vi, seme Jakobovo, proslavite ga, in bojte se ga, vsi vi, seme Izraelovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Kajti ni zaničeval niti preziral stiske stiskanih niti svojega obraza ni skrival pred njim; toda ko je klical k njemu, je slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Moja hvala v veliki skupnosti bo o tebi. Svoje zaobljube bom izpolnil pred tistimi, ki se ga bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Krotki bodo jedli in bodo nasičeni. Hvalili bodo Gospoda [tisti], ki ga iščejo. Vaše srce bo živelo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Vsi konci zemlje se bodo spomnili in obrnili h Gospodu in vsa sorodstva narodov bodo oboževala pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Kajti kraljestvo je Gospodovo in on je voditelj med narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Vsi tisti, ki so na zemlji obilni, bodo jedli in oboževali. Vsi tisti, ki gredo dol v prah, se bodo poklonili pred njim, svoje lastne duše pa nihče ne more ohraniti žive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Seme mu bo služilo; to bo šteto h Gospodu za rod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Prišli bodo in oznanjali bodo njegovo pravičnost ljudem, ki bodo rojeni, da je on to storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Davidov psalm. Gospod je moj pastir, ne bom trpel pomanjkanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Napravlja mi, da se zleknem na zelenih pašnikih. Vodi me ob mirnih vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Mojo dušo obnavlja. Zaradi svojega imena me vodi po stezah pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, '§ Da, čeprav hodim skozi dolino smrtne sence, se ne bom bal nobenega zla, kajti ti si z menoj; tvoja šiba in tvoja opora me tolažita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Pred menoj pripravljaš mizo, v prisotnosti mojih sovražnikov. Mojo glavo maziliš z oljem, moja čaša prekipeva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Zagotovo me bosta dobrota in usmiljenje spremljali vse dni mojega življenja, in v Gospodovi hiši bom prebival na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Davidov psalm. Zemlja je Gospodova in njena polnost, zemeljski [krog] in tisti, ki prebivajo na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Kajti utemeljil ga je na morjih in ga osnoval na tokovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kdo se bo povzpel na Gospodovo goro? Ali kdo bo stal na njegovem svetem prostoru?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Kdor ima čiste roke in nedolžno srce, kdor svoje duše ni povzdignil k praznim rečem niti ni varljivo prisegel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Prejel bo blagoslov od Gospoda in pravičnost od Boga rešitve svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'To je rod tistih, ki ga iščejo, ki iščejo tvoje obličje, oh Jakob. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Vzdignite svoje glave, oh ve velika vrata in bodite dvignjene, ve večna vrata, in vstopil bo Kralj slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kdo je to, Kralj slave? Gospod, močan in mogočen, Gospod, mogočen v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Vzdignite svoje glave, oh ve velika vrata, celó dvignite jih, ve večna vrata in vstopil bo Kralj slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kdo je ta Kralj slave? Gospod nad bojevniki, on je Kralj slave. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Davidov psalm. K tebi, oh Gospod, vzdigujem svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Oh moj Bog, jaz zaupam vate. Naj ne bom osramočen, naj moji sovražniki ne slavijo zmage nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Da, naj ne bo osramočen nihče, ki čaka nate. Naj bodo osramočeni, ki se pregrešijo brez razloga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Pokaži mi svoje poti, oh Gospod, úči me svojih stezá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Vodi me v svoji resnici in me úči, kajti ti si Bog rešitve moje duše, nate čakam ves dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Spomni se, oh Gospod, svojih nežnih usmiljenj in svojih ljubečih skrbnosti, kajti bile so vedno, od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Ne spominjaj se grehov moje mladosti niti mojih prestopkov. Glede na svoje usmiljenje se me spominjaj zaradi svoje dobrote, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Dober in pošten je Gospod, zato bo grešnike učil na poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Krotke bo usmerjal na sodbo in krotke bo učil svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Vse Gospodove steze so usmiljenje in resnica do teh, ki se držijo njegove zaveze in njegovih pričevanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Zaradi svojega imena, oh Gospod, odpusti mojo krivičnost, kajti ta je velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kakšen človek je ta, ki se boji Gospoda? Njega bo on učil na poti, ki jo bo on izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Njegova duša bo prebivala sproščeno in njegovo seme bo podedovalo zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Gospodova skrivnost je s tistimi, ki se ga bojijo in pokazal jim bo svojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Moje oči so vedno v smeri Gospoda, kajti moja stopala bo on potegnil iz mreže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Obrni se k meni in se me usmili, kajti zapuščen sem in prizadet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Težave mojega srca so se povečale. O, osvobodi me iz moje stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Poglej na mojo žalost in mojo bolečino in odpusti vse moje grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Preudari moje sovražnike, kajti mnogo jih je in sovražijo me s krutim sovraštvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Oh varuj mojo dušo in me osvobodi. Naj ne bom osramočen, kajti svoje zaupanje polagam vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Naj me ohranjata neokrnjenost in poštenost, kajti jaz čakam nate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Odkupi Izraela, oh Bog, iz vseh njegovih težav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Davidov psalm. Sodi me, oh Gospod, kajti hodil sem v svoji neokrnjenosti. Zaupal sem tudi v Gospoda, zato ne bom zdrsnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Preišči me, oh Gospod in preizkusi me; preizkusi mojo notranjost in moje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Kajti tvoja ljubeča skrbnost je pred mojimi očmi in hodil sem v tvoji resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nisem se usedal z domišljavimi osebami niti ne bom vstopal s hinavci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Sovražil sem skupnost hudodelcev in z zlobnimi ne bom sedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'V nedolžnosti si bom umival roke; tako bom hodil okoli tvojega oltarja, oh Gospod,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'da bom lahko razglašal z glasom zahvaljevanja in pripovedoval o vseh tvojih čudovitih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Gospod, ljubil sem prebivališče tvoje hiše in kraj, kjer prebiva tvoja čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Ne zbiraj moje duše z grešniki niti mojega življenja s krvoločnimi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'V čigar rokah je vragolija, njihova desnica pa je polna podkupnin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Toda kar se mene tiče, jaz bom hodil v svoji neokrnjenosti. Odkupi me in bodi mi usmiljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Moje stopalo stoji na ravnem kraju. V skupnostih bom blagoslavljal Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Davidov psalm. Gospod je moja svetloba in rešitev moje duše, koga bi se bal? Gospod je moč mojega življenja; pred kom bom prestrašen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Kadar so prišli nadme zlobni, celó moji sovražniki in moji nasprotniki, da požro moje meso, so se spotaknili in padli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Čeprav bi se zoper mene utaborila vojska, se moje srce ne bo balo. Četudi bi se zoper mene dvignila vojna, bom jaz pri tem zaupljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eno stvar sem želel od Gospoda, to hočem doseči, da bom lahko prebival v Gospodovi hiši vse dni svojega življenja, da zrem Gospodovo lepoto in da poizvedujem v njegovem templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Kajti v času stiske me bo skril v svojem paviljonu. Skril me bo v skrivnosti svojega šotorskega svetišča, postavil me bo na skalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Sedaj bo moja glava povzdignjena nad moje sovražnike okoli mene, zato bom v njegovem šotorskem svetišču daroval žrtvovanje radosti; pel bom, da, prepeval bom hvalnice Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Poslušaj, oh Gospod, ko kličem s svojim glasom. Tudi nad menoj imej usmiljenje in mi odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, '§ Ko praviš: »Iščite moje obličje,« ti je moje srce reklo: »Tvoje obličje, Gospod, bom iskal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne skrivaj svojega obličja daleč od mene, svojega služabnika ne odslovi v jezi. Bil si moja pomoč; ne zapusti me niti se me ne odpovej, oh Bog rešitve moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Ko me moj oče in moja mati zapustita, potem me bo Gospod pobral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Úči me svoje poti, oh Gospod in vodi me po ravni stezi, zaradi mojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne izroči me volji mojih sovražnikov, kajti krive priče so vstale zoper mene in takšni, ki izdihujejo krutost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, '§ Oslabel sem, razen če sem veroval, da vidim Gospodovo dobroto v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Čakaj na Gospoda, bodi odločnega poguma in okrepil bo tvoje srce. Čakaj, pravim, na Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Davidov psalm. K tebi hočem klicati, oh Gospod, moja skala, ne bodi molčeč do mene, da ne bi, če boš do mene molčeč, postal podoben tem, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Prisluhni glasu mojih ponižnih prošenj, ko kličem k tebi, ko svoje roke dvigujem k tvojemu svetemu oraklju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne odtegni me proč z zlobnimi in z delavci krivičnosti, ki svojim bližnjim govorijo mir, toda v njihovih srcih je vragolija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Daj jim glede na njihova dejanja in glede na zlobnost njihovih prizadevanj. Daj jim po delu njihovih rok, povrni jim njihovo plačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Ker ne upoštevajo Gospodovih del niti delovanja njegovih rok, jih bo uničil in jih ne bo zgradil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Blagoslovljen bodi Gospod, ker je uslišal glas mojih ponižnih prošenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Gospod je moja moč in moj ščit, moje srce je zaupalo vanj in pomagano mi je. Zato se moje srce silno razveseljuje in s svojo pesmijo ga bom hvalil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Gospod je njihova moč in on je rešilna moč svojemu maziljencu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Reši svoje ljudstvo in blagoslavljaj svojo dediščino, tudi pasi jih in dvigni jih na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Davidov psalm. § Dajajte Gospodu, oh vi mogočni, dajajte Gospodu slavo in moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Dajajte Gospodu slavo, primerno njegovemu imenu, obožujte Gospoda v lepoti svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Glas Gospodov je nad vodami. Bog slave grmi. Gospod je nad mnogimi vodami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Glas Gospodov je močan, glas Gospodov je poln veličanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Glas Gospodov lomi cedre, da, Gospod lomi libanonske cedre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, '§ Dela jih tudi, da poskakujejo kakor tele, Libanon in Sirjón kakor mlad samorog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Glas Gospodov razdeljuje plamene ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Glas Gospodov trese divjino, Gospod trese kadéško divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Glas Gospodov dela košutam, da povržejo in odkriva gozdove. V njegovem templju vsakdo govori o njegovi slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Gospod sedi na potopu, da, Gospod sedi, Kralj na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Gospod bo dal svojemu ljudstvu moč, Gospod bo svoje ljudstvo blagoslovil z mirom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psalm in pesem ob posvetítvi Davidove hiše. Povzdigoval te bom, oh Gospod, kajti dvignil si me in nisi storil, da se moji nasprotniki veselijo nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Oh Gospod, moj Bog, klical sem k tebi in ti si me ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Oh Gospod, mojo dušo si privedel iz groba. Ohranil si me živega, da ne bi šel dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Prepevajte Gospodu, oh vi njegovi sveti in zahvaljujte se ob spominu njegove svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Kajti njegova jeza ostaja samo trenutek, v njegovi naklonjenosti je življenje. Jokanje lahko vztraja za [eno] noč, toda radost prihaja zjutraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'V svojem uspevanju sem rekel: »Nikoli ne bom omajan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Gospod, po svoji naklonjenosti si storil, da moja gora trdno stoji. Skril si svoje obličje in sem bil zaskrbljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'K tebi sem klical, oh Gospod in h Gospodu sem naredil ponižno prošnjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '»Kakšna korist je v moji krvi, ko pojdem dol v jamo? Mar te bo hvalil prah? Bo ta oznanjal tvojo resnico?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Prisluhni, oh Gospod in usmili se me. Gospod, bodi moj pomočnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Ti si zame obrnil moje žalovanje v ples. Odložil si mojo vrečevino in me opasal z veseljem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'z namenom, da lahko moja slava tebi poje hvalnico in ne bo molčeča. Oh Gospod, moj Bog, zahvaljeval se ti bom na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Vodji glasbenikov, Davidov psalm. Vate, oh Gospod, polagam svoje trdno upanje; naj ne bom nikoli osramočen, osvobodi me v svoji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Nagni k meni svoje uho, naglo me osvobodi. Bodi moja čvrsta skala, za hišo obrambe, da me rešiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Kajti ti si moja skala in moja trdnjava, zato me vôdi zaradi svojega imena in me usmerjaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Potegni me iz mreže, ki so jo na skrivnem položili zame, kajti ti si moja moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'V tvojo roko izročam svojega duha. Odkupil si me, oh Gospod, Bog resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Sovražil sem tiste, ki se ozirajo za lažnivimi ničevostmi, toda jaz zaupam v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Vesel bom in se radoval v tvojem usmiljenju, kajti preudaril si mojo težavo, v stiskah si spoznal mojo dušo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'in me nisi zaprl v roko mojega sovražnika. Moja stopala si postavil na velik prostor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Usmili se me, oh Gospod, kajti v stiski sem. Moje oko je použito z žalostjo, da, moja duša in moj trebuh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Kajti moje življenje je iztrošeno z žalostjo in moja leta z vzdihovanjem. Moja moč slabi zaradi moje krivičnosti in moje kosti so použite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Bil sem graja med vsemi svojimi sovražniki, toda še posebej med svojimi bližnjimi in strah svojim znancem. Tisti, ki so me videli zunaj, so pobegnili pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Pozabljen sem, kakor je mrtev človek hitro pozabljen iz uma. Podoben sem razbiti posodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Kajti slišal sem obrekovanje mnogih. Strah je bil na vsaki strani. Medtem ko so se skupaj posvetovali zoper mene, so snovali, da vzamejo moje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Toda jaz sem zaupal vate, oh Gospod. Rekel sem: »Ti si moj Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Moji časi so v tvoji roki. Osvobodi me pred roko mojih sovražnikov in pred tistimi, ki me preganjajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Stôri, da tvoj obraz zasije nad tvojim služabnikom. Reši me zaradi svojega usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Naj ne bom osramočen, oh Gospod, kajti klical sem k tebi. Naj bodo zlobni osramočeni in naj bodo molče v grobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Naj bodo utišane lažnive ustnice, ki ponosno in zaničljivo govorijo boleče stvari zoper pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'O, kako velika je tvoja dobrota, ki si jo prihranil za tiste, ki se te bojijo, ki si jo izvršil tistim, ki zaupajo vate pred človeškimi sinovi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Pred ponosom ljudi jih boš skril v zatišju svoje prisotnosti. Pred prepirom jezikov jih boš skrivaj varoval v paviljonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Blagoslovljen bodi Gospod, kajti pokazal mi je svojo čudovito prijaznost v utrjenem mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Kajti v svoji naglici sem rekel: »Iztrebljen sem izpred tvojih oči.« Vendar si slišal glas mojih ponižnih prošenj, ko sem klical k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Oh ljubite Gospoda, vsi vi njegovi sveti, kajti Gospod ohranja zveste in obilno nagrajuje tistega, ki ravna ponosno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, '§ Bodite odločnega poguma in vaša srca bo okrepil vsem vam, ki upate v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Davidov psalm, pouk. Blagoslovljen je tisti, čigar prestopek je oproščen, čigar greh je pokrit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Blagoslovljen je človek, ki mu Gospod ne pripisuje krivičnosti in v čigar duhu ni zvijače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Ko sem molčal, so se moje kosti postarale zaradi mojega kričanja ves dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Kajti dan in noč je bila tvoja roka težka nad menoj. Moja vlažnost je obrnjena v poletno sušo. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Priznal sem ti svoj greh in svoje krivičnosti nisem prikrival. Rekel sem: »Svoje prestopke bom priznal Gospodu,« in ti odpuščaš krivičnost mojega greha. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Kajti tako bo k tebi molil vsak, kdor je bogaboječ, v času, ko se daješ najti. Zagotovo mu v poplavah velikih vodá oni ne bodo prišli blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Ti si moje skrivališče, ohranil me boš pred stisko, naokoli me boš obdal s pesmimi osvoboditve. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Poučil te bom in te učil na poti, po kateri boš šel. Usmerjal te bom s svojim očesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne bodite kakor konj ali kakor mula, ki nimata razumevanja, čigar gobca se mora držati z žvalo in uzdo, da se ti ne približata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Mnoge bridkosti bodo zlobnemu, toda kdor zaupa v Gospoda, ga bo obdajalo usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Bodite veseli v Gospodu in veselite se, vi pravični. Vzklikajte od veselja vsi vi, ki ste iskreni v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Veselite se v Gospodu, oh vi pravični, kajti hvala je ljubka iskrenim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Hvalite Gospoda s harfo, prepevajte mu s plunko in glasbilom desetih strun.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Prepevajte mu novo pesem, igrajte vešče z glasnim zvokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Kajti Gospodova beseda je pravilna in vsa njegova dela so narejena v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'On ljubi pravičnost in sodbo. Zemlja je polna Gospodove dobrote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Nebo je bilo narejeno z Gospodovo besedo in vsa njegova vojska z dihom njegovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Morske vode zbira skupaj kakor kup, globine shranjuje v skladiščih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Naj se vsa zemlja boji Gospoda. Naj vsi prebivalci zemeljskega [kroga] stojijo v strahospoštovanju pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Kajti spregovoril je in bilo je narejeno, zapovedal je in je trdno stalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Gospod uničuje namere poganov. Načrte ljudstva dela brez učinka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Gospodove namere ostanejo večno, misli njegovega srca vsem rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Blagoslovljen je narod, čigar Bog je Gospod in ljudstvo, ki ga je izbral za svojo lastno dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Gospod gleda z neba, ogleduje vse človeške sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Iz kraja svojega prebivališča gleda na vse prebivalce zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Prav tako oblikuje njihova srca, preudarja vsa njihova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Noben kralj ni rešen z množičnostjo vojske, mogočen človek ni osvobojen z veliko močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Konj je jalova stvar za varnost niti s svojo veliko močjo ne bo nikogar osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Glej, Gospodovo oko je nad temi, ki se ga bojijo, nad temi, ki upajo v njegovo usmiljenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'da njihovo dušo osvobodi pred smrtjo in da jih v lakoti ohrani žive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Naša duša čaka na Gospoda, on je naša pomoč in naš ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Kajti naše srce se bo veselilo v njem, ker smo zaupali v njegovo sveto ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Naj bo tvoje usmiljenje na nas, oh Gospod, prav tako kakor mi zaupamo vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Davidov psalm, ko je spremenil svoje obnašanje pred Abimélehom; ki ga je spodil in je odšel. Ob vseh časih bom blagoslavljal Gospoda, njegova hvala bo nenehno na mojih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Moja duša bo storila svoje bahanje v Gospodu. Ponižni bodo o tem slišali in bodo veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Oh poveličujte z menoj Gospoda in skupaj poveličujmo njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Iskal sem Gospoda in me je uslišal ter me osvobodil pred vsemi mojimi strahovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Pogledali so k njemu in bili ožarjeni in njihovi obrazi niso bili osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ta revež je zajokal in Gospod ga je uslišal ter ga rešil pred vsemi njegovimi težavami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Gospodov angel tabori okoli teh, ki se ga bojijo in jih osvobaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Oh okusite in vidite, da je Gospod dober. Blagoslovljen je človek, ki zaupa vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Oh bojte se Gospoda, vi njegovi sveti, kajti nič ne manjka tem, ki se ga bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Mladim levom primanjkuje in trpijo lakoto, toda tistim, ki iščejo Gospoda, ne bo manjkala nobena dobra stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Pridite, otroci, prisluhnite mi. Strahu Gospodovega vas bom učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kakšen človek je tisti, ki želi življenje in ljubi mnoge dneve, da bi lahko videl dobro?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Zadržuj svoj jezik pred zlom in svoje ustnice od govorjenja zvijače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Odidi od zla in delaj dobro, išči mir in ga zasleduj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Gospodove oči so na pravičnih in njegova ušesa so odprta k njihovemu klicanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Gospodovo obličje je zoper te, ki delajo zlo, da z zemlje iztrebi spomin na njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Pravični kličejo in Gospod uslišuje ter jih osvobaja iz vseh njihovih stisk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Gospod je blizu tem, ki so zlomljenega srca in rešuje takšne, ki so skesanega duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Mnoge so stiske pravičnega, toda Gospod ga osvobaja iz njih vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Varuje vse njegove kosti niti ena izmed njih ni zlomljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Zlo bo pokončalo zlobnega in tisti, ki sovražijo pravične, bodo zapuščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Gospod odkupuje dušo svojih služabnikov in nobeden od teh, ki zaupajo vanj, ne bo zapuščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Davidov psalm. Zagovarjaj mojo pravdo, oh Gospod, s temi, ki se prepirajo z menoj. Bori se zoper te, ki se borijo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Zgrabi za ščit in majhen ščit ter se dvigni v mojo pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Izvleci tudi sulico in zapri pot zoper tiste, ki me preganjajo. Moji duši reci: »Jaz sem rešitev tvoje duše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Naj bodo zbegani in osramočeni tisti, ki strežejo po moji duši. Naj bodo obrnjeni nazaj in privedeni v zmedenost tisti, ki snujejo mojo bolečino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Naj bodo kakor pleve pred vetrom. Naj jih preganja Gospodov angel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Naj bo njihova pot temna in spolzka in naj jih preganja Gospodov angel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Kajti brez razloga so svojo mrežo skrili zame v jamo, ki so jo brez razloga izkopali za mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Naj nadenj nenadoma pride uničenje in naj ga ujame njegova mreža, ki jo je nastavil, naj pade v točno takšno uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Moja duša pa bo radostna v Gospodu, veselila se bo v njegovi rešitvi duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Vse moje kosti bodo rekle: » Gospod, kdo je podoben tebi, ki osvobajaš reveža pred tistim, ki je zanj premočan, da, reveža in pomoči potrebnega pred tistim, ki ga pleni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Vstale so krive priče, k moji obtožnici so položili stvari, ki jih nisem poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Nagradili so me [z] zlom za dobro, do plenjenja moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Toda kar se mene tiče, ko so bili bolni, so bila moja oblačila vrečevina. Svojo dušo sem ponižal s postom in moja molitev se je vrnila v mojo lastno notranjost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Vêdel sem se, kakor da je bil on moj prijatelj ali brat. Močno sem se sklonil kakor nekdo, ki žaluje za svojo materjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Toda v moji nadlogi so se veselili in se zbirali skupaj. Da, podleži so se zbirali zoper mene, pa tega nisem vedel, trgali so me in niso odnehali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 's hinavskimi zasmehovalci so na pojedinah s svojimi zobmi škripali nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Gospod, doklej boš gledal? Mojo dušo reši pred njihovimi uničenji, mojo ljubljeno pred levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Zahvaljeval se ti bom v veliki skupnosti. Hvalil te bom med mnogimi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Naj se tisti, ki so moji sovražniki, ne veselijo krivično nad menoj niti naj ne mežikajo z očesom tisti, ki me sovražijo brez razloga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Kajti ne govorijo miru, temveč snujejo varljive zadeve zoper tiste, ki so v deželi mirni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Da, svoja usta so široko odprli proti meni in rekli: »Aha, aha, naše oko je to videlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'To si videl, oh Gospod. Ne molči. Oh Gospod, ne bodi daleč od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Razvnemi se in prebudi se na mojo sodbo, celó za mojo zadevo, moj Bog in moj Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Sodi me, oh Gospod, moj Bog, glede na tvojo pravičnost in naj se ne veselijo nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Naj ne pravijo v svojih srcih: »Ah, tako smo to želeli.« Naj ne pravijo: »Požrli smo ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Naj bodo osramočeni in skupaj privedeni v zmedenost tisti, ki se veselijo ob moji bolečini. Naj bodo tisti, ki se poveličujejo zoper mene, oblečeni z nečastjo in sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Naj tisti, ki podpirajo mojo pravično zadevo, vzklikajo od veselja in bodo veseli. Da, naj nenehno govorijo: »Naj bo poveličan Gospod, ki ima veselje v uspevanju svojega služabnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Moj jezik pa bo ves dan govoril o tvoji pravičnosti in o tvoji hvali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Vodji glasbenikov, psalm Davida, Gospodovega služabnika. § Prestopek zlobnega znotraj mojega srca pravi, da pred njegovimi očmi ni Božjega strahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Kajti v svojih lastnih očeh si laska, dokler se ne najde njegova krivičnost, da je vreden sovraštva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Besede iz njegovih ust so krivičnost in prevara. Prenehal je biti moder in delati dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Na svoji postelji snuje vragolijo, postavlja se na pot, ki ni dobra, zla ne prezira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Tvoje usmiljenje, oh Gospod, je v nebesih; in tvoja zvestoba sega do oblakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Tvoja pravičnost je podobna velikim goram, tvoje sodbe so zelo globokoumne. Oh Gospod, ti ohranjaš človeka in žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Kako odlična je tvoja ljubeča skrbnost, oh Bog! Zato človeški otroci svoje trdno upanje polagajo pod senco tvojih peruti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Obilno bodo nasičeni z obiljem tvoje hiše in primoral jih boš piti iz reke svojih radosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Kajti s teboj je studenec življenja, v tvoji svetlobi bomo videli svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Oh nadaljuj svoje ljubeče skrbnosti tem, ki te poznajo, in svojo pravičnost do iskrenih v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Naj proti meni ne pride stopalo ponosnega in naj me roka zlobnega ne odstrani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Tam so padli delavci krivičnosti. Podrti so in ne bodo mogli vstati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Davidov psalm. Ne razburjaj se zaradi hudodelnikov niti ne bodi nevoščljiv proti delavcem krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Kajti hitro bodo posekani kakor trava in ovenijo kakor zeleno zelišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Zaupaj v Gospoda in delaj dobro, tako boš prebival v deželi in boš resnično nahranjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'V Gospodu se tudi razveseljuj in dal ti bo želje tvojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Svojo pot izroči Gospodu, vanj tudi zaupaj in bo to napravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'In tvojo pravičnost bo razjasnil kakor svetlobo in tvojo sodbo kakor poldan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Počivaj v Gospodu in potrpežljivo čakaj nanj. Ne razburjaj se zaradi tistega, ki na svoji poti uspeva, zaradi človeka, ki povzroči, da se zgodijo zlobni naklepi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Odnehaj z jezo in zapusti bes. Ne razburjaj se na kakršenkoli način, da bi delal zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Kajti hudodelci bodo iztrebljeni, toda tisti, ki čakajo na Gospoda, bodo podedovali zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Kajti še kratek čas in zlobnega ne bo. Da, marljivo boš preudaril njegov kraj in ga ne bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Toda krotki bodo podedovali zemljo in razveseljevali se bodo v obilju miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Zlobni spletkari zoper pravičnega in proti njemu škripa s svojimi zobmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Gospod se mu bo posmehoval, kajti vidi, da prihaja njegov dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Zlobni so izvlekli meč in napeli svoj lok, da podrejo revnega in pomoči potrebnega in da pobijejo tiste, ki so iskrenega vedênja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Njihov meč bo predrl njihovo lastno srce in njihovi loki bodo zlomljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Nekaj, kar ima pravičen človek, je bolje kakor bogastva mnogih zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Kajti lakti zlobnih bodo zlomljeni, toda Gospod podpira pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Gospod pozna dneve iskrenih in njihova dediščina bo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'V hudem času ne bodo osramočeni in v dneh lakote bodo nasičeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Toda zlobni bodo propadli in Gospodovi sovražniki bodo kakor tolšča jagnjet. Použiti bodo, použiti bodo v dimu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Zlobni si izposoja, pa ne vrača, toda pravični izkazuje usmiljenje in daje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Kajti tisti, ki bodo od njega blagoslovljeni, bodo podedovali zemljo. Tisti, ki bodo od njega prekleti, pa bodo iztrebljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Koraki dobrega moža so odrejeni po Gospodu in on se razveseljuje v njegovi poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Čeprav pade, ne bo popolnoma podrt, kajti Gospod ga podpira s svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Bil sem mlad, sedaj pa sem star, vendar nisem videl pravičnega zapuščenega niti njegove potomce prosjačiti kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Vedno je usmiljen in posoja in njegovo seme je blagoslovljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odidi od zla in delaj dobro in prebivaj na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Kajti Gospod ljubi sodbo in ne zapušča svojih svetih; ohranjeni so za vedno, toda seme hudobnega bo iztrebljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Pravični bo podedoval deželo in za vedno prebival v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Usta pravičnega govorijo modrost in njegov jezik govori o sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Postava njegovega Boga je v njegovem srcu niti eden izmed njegovih korakov ne bo zdrsnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Zlobni opazuje pravičnega in išče, da ga pokonča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Gospod ga ne bo prepustil v njegovo roko niti ga ne bo obsodil, ko je sojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Čakaj na Gospoda, drži se njegove poti in povišal te bo, da podeduješ deželo. Ko so zlobni iztrebljeni, boš ti to videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Videl sem zlobnega v veliki moči in razprostirati se kakor zeleno lovorjevo drevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Vendar je preminil in glej, ni ga bilo. Da, iskal sem ga, toda ni ga bilo najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, '§ Zapomni si popolnega človeka in glej iskrenega, kajti konec tega človeka je mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Toda prestopniki bodo skupaj uničeni in konec zlobnih bo iztrebljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Toda rešitev duš pravičnih je od Gospoda, on je njihova moč v času stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Gospod jim bo pomagal in jih osvobodil. Osvobodil jih bo pred zlobnim in jih rešil, ker oni zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Davidov psalm, da privede v spomin. Oh Gospod, ne oštevaj me v svojem besu niti me ne karaj v svojem silnem nezadovoljstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Kajti tvoje puščice trdno tičijo v meni in tvoja roka me boleče pritiska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Zaradi tvoje jeze na mojem mesu ni zdravja niti ni v mojih kosteh zaradi mojega greha nobenega počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Kajti moje krivičnosti so presegle mojo glavo, kakor težko breme so zame pretežke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Moje rane zaudarjajo in so okužene zaradi moje nespametnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Zaskrbljen sem, silno sem sklonjen, ves dan hodim in žalujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Kajti moja ledja so napolnjena z gnusno boleznijo in zdravja ni na mojem mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Slaboten sem in boleče zlomljen, vpil sem zaradi nemira v svojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Gospod, pred teboj je vse moje hrepenenje in moje stokanje ni skrito pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Moje srce trepeta, moja moč me zapušča. Glede svetlobe mojih oči, je tudi ta odšla od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Moji ljubi in moji prijatelji stojijo daleč stran od moje rane in moji sorodniki stojijo daleč stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Tudi tisti, ki mi strežejo po življenju, zame postavljajo zanke in tisti, ki iščejo mojo bolečino, govorijo pogubne stvari in si ves dan domišljajo prevare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Toda jaz, kakor gluh človek, nisem slišal in bil sem nem človek, ki ne odpira svojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Tako sem bil človek, ki ne sliši in v čigar ustih ni opominov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Kajti vate zaupam, oh Gospod, ti boš uslišal, oh Gospod, moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Kajti rekel sem: » Usliši me, da se ne bi sicer veselili nad menoj. Ko moje stopalo zdrsuje, se poveličujejo proti meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Kajti pripravljen sem, da se zaustavim in moja bridkost je nenehno pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Kajti oznanil bom svojo krivičnost, žalosten bom zaradi svojega greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Toda moji sovražniki so živi in oni so močni, in tisti, ki me krivično sovražijo, so pomnoženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Tudi tisti, ki vračajo zlo za dobro, so moji nasprotniki, ker sledim stvari, ki je dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Ne zapusti me, oh Gospod. Oh moj Bog, ne bodi daleč od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Podvizaj se, da mi pomagaš, oh Gospod, rešitev moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Vodji glasbenikov, torej Jedutúnu, Davidov psalm. Rekel sem: »Pazil bom na svoje poti, da ne bom grešil s svojim jezikom. Ko bo zlobni pred menoj, bom svoja usta držal z uzdo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Bil sem nem s tišino, molčal sem, celó pred dobrim in moja bridkost je bila razvneta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Moje srce je bilo vroče znotraj mene, medtem ko sem razglabljal, je zagorel ogenj, potem sem spregovoril s svojim jezikom:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '» Gospod, daj mi spoznati moj konec in mero mojih dni, kolikšna je, da lahko spoznam, kako slaboten sem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Glej, moje dneve si naredil kakor dlan in moja starost je kakor nič pred teboj. Resnično, vsak človek v svojem najboljšem stanju je povsem ničevost.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Zagotovo vsak človek hodi v prazni podobi, zagotovo so zaman vznemirjeni. Kopiči bogastva, pa ne ve, kdo jih bo pobral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'In sedaj, Gospod, kaj [naj] pričakujem? Moje upanje je v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Osvobodi me pred vsemi mojimi prestopki. Ne naredi me [za] grajo nespametnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Bil sem nem, svojih ust nisem odprl, ker si ti to storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Umakni svoj udarec proč od mene. Použit sem z zamahom tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Kadar za krivičnost z grajanjem korigiraš človeka, storiš, da njegova lepota shira kakor molj. Zagotovo je vsak človek ničevost. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Usliši mojo molitev, oh Gospod in pazljivo prisluhni mojemu vpitju; ob mojih solzah ne molči. Kajti jaz sem tujec s teboj in začasni prebivalec, kakor so bili vsi moji očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Oh prizanesi mi, da lahko obnovim moč, preden grem naprej in ne bom več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Vodji glasbenikov. Davidov psalm. Potrpežljivo sem čakal na Gospoda in on se je nagnil k meni ter slišal moj klic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Privedel me je tudi iz strašne jame, ven iz blatnega ila in moja stopala je postavil na skalo in utrdil moje korake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'V moja usta je položil novo pesem, celó hvalo našemu Bogu. Mnogi bodo to videli ter se bali in bodo zaupali v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Blagoslovljen je tisti človek, ki svoje trdno upanje postavlja [v] Gospoda in ne spoštuje ponosnega niti takšnega, ki odvrača k lažem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Mnoga, oh Gospod, moj Bog, so tvoja čudovita dela, ki si jih storil in tvoje misli, ki so do nas, ne morejo biti po vrsti izračunane k tebi. Če želim oznaniti in govoriti o njih, jih je več, kakor jih je mogoče prešteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Klavne daritve in darovanja si nisi zaželel, odprl si mi ušesa. Žgalne daritve in daritve za greh nisi zahteval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Potem sem rekel: »Glej! Prihajam. V zvezku knjige je zapisano o meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'veselim se, da izpolnim tvojo voljo, oh moj Bog. Da, tvoja postava je znotraj mojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Oznanjal sem pravičnost v veliki skupnosti. Glej, svojih ustnic nisem zadrževal, oh Gospod, ti veš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Tvoje pravičnosti nisem skrival v svojem srcu; oznanjal sem tvojo zvestobo in tvojo rešitev duše. Tvoje ljubeče skrbnosti in tvoje resnice nisem prikrival pred veliko skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Svojih nežnih usmiljenj ne zadržuj pred menoj, oh Gospod. Naj me nenehno varujeta tvoja ljubeča skrbnost in tvoja resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Kajti obkrožila so me brezštevilna zla, polastile so se me moje krivičnosti, tako da nisem zmožen pogledati kvišku. Več jih je kakor las moje glave, zato mi peša srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Bodi vesel, oh Gospod, da me osvobodiš. Oh Gospod, podvizaj se, da mi pomagaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Naj bodo hkrati osramočeni in zbegani, ki strežejo po moji duši, da jo uničijo. Naj bodo odgnani nazaj in osramočeni tisti, ki mi želijo zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Naj bodo zapuščeni, za nagrado njihove sramote, ki mi pravijo: ›Aha, aha.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Naj se vsi tisti, ki te iščejo, razveselijo in bodo veseli v tebi. Naj tisti, ki ljubijo tvojo rešitev duše, nenehno govorijo: ›Poveličan bodi, Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Toda jaz sem ubog in pomoči potreben, vendarle Gospod misli name. Ti si moja pomoč in moj osvoboditelj; ne mudi se, oh moj Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Vodji glasbenikov, Davidov psalm. Blagoslovljen je, kdor misli na ubogega. Gospod ga bo osvobodil v času stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Gospod ga bo varoval in ga ohranil živega in blagoslovljen bo na zemlji in ti ga nočeš izročiti volji njegovih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Gospod ga bo okrepil na postelji slabljenja. Zamenjal boš vso njegovo posteljo v njegovi bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Rekel sem: » Gospod, bodi mi usmiljen. Ozdravi mojo dušo, kajti grešil sem zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Moji sovražniki zlobno govorijo o meni: »Kdaj bo umrl in njegovo ime izgine?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Če pride, da me vidi, govori prazne reči. Njegovo srce k sebi zbira krivičnost; ko hodi proč od bivališča, to pripoveduje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Vsi, ki me sovražijo, skupaj šepetajo zoper mene, zoper mene snujejo mojo bolečino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Zla bolezen, pravijo, se ga trdno drži, in sedaj, ko leži, ne bo več vstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Da, moj lastni zaupni prijatelj, v katerega sem zaupal, ki je jedel od mojega kruha, je dvignil svojo peto zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Toda ti, oh Gospod, mi bodi usmiljen in me dvigni, da jim lahko poplačam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Po tem spoznam, da me ti podpiraš, ker moj sovražnik ne slavi zmage nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Kar se mene tiče, me podpiraš v moji neokrnjenosti in me postavljaš pred svoje obličje na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Blagoslovljen bodi Gospod, Izraelov Bog, od večnosti in do večnosti. Amen in Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Vodji glasbenikov, pouk za Korahove sinove. Kakor jelen hlepi za vodnimi potoki, tako moja duša hrepeni po tebi oh Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Mojo dušo žeja po Bogu, po živem Bogu. Kdaj bom prišel in se pojavil pred Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Moje solze so mi bile hrana dan in noč, medtem ko mi nenehno pravijo: »Kje je tvoj Bog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Ko se spominjam teh besed, v sebi izlivam svojo dušo, kajti odšel sem z množico, z njimi sem šel k Božji hiši, z glasom radosti in hvale, z množico, ki je praznovala sveti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Zakaj si potrta, oh moja duša? In zakaj si vznemirjena v meni? Upaj v Boga, kajti še ga bom hvalil zaradi pomoči njegovega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Oh moj Bog, moja duša je v meni potrta, zatorej se te spominjam iz jordanske in hermonske dežele, s hriba Micár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Brezno kliče breznu ob zvoku tvojih vodnih tornadov. Vsi tvoji valovi in tvoji veliki valovi so šli čezme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Vendar bo Gospod podnevi zapovedal svoji ljubeči skrbnosti in ponoči bo njegova pesem z menoj in moja molitev k Bogu mojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Rekel bom Bogu, svoji skali: »Zakaj si me pozabil? Zakaj hodim in žalujem zaradi sovražnikovega zatiranja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Kakor z mečem v moje kosti me grajajo moji sovražniki, medtem ko mi vsak dan pravijo: »Kje je tvoj Bog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Zakaj si potrta, oh moja duša? In zakaj si vznemirjena znotraj mene? Upaj v Boga, kajti še bom hvalil njega, ki je zdravje mojega obličja in moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Sodi me, oh Bog in zagovarjaj mojo pravdo proti brezbožnemu narodu. Oh osvobodi me pred varljivim in nepravičnim človekom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Kajti ti si Bog moje moči. Zakaj me zavračaš? Zakaj hodim in žalujem zaradi sovražnikovega zatiranja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Oh pošlji svojo svetlobo in svojo resnico, naj me vodita; naj me privedeta k tvoji sveti gori in k tvojim šotorskim svetiščem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Potem bom stopil k Božjemu oltarju, k Bogu moje silne radosti; da, na harfo te bom hvalil, oh Bog, moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Zakaj si potrta, oh moja duša? In zakaj si vznemirjena znotraj mene? Upaj v Boga, kajti še bom hvalil njega, ki je zdravje mojega obličja in moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Vodji glasbenikov za Korahove sinove. Pouk. S svojimi ušesi smo slišali, oh Bog, naši očetje so nam povedali, kakšno delo si storil v njihovih dneh, v davnih časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Kako si s svojo roko napodil pogane in naselil njih; kako si prizadel ljudstvo in jih pregnal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Kajti dežele niso prejeli v posest s svojim lastnim mečem niti jih ni rešil njihov lastni laket, temveč tvoja desnica in tvoj laket in svetloba tvojega obličja, ker imaš do njih naklonjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Ti si moj Kralj, oh Bog, zapovej osvoboditve za Jakoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'S teboj bomo podrli svoje sovražnike. S tvojim imenom bomo pomendrali te, ki se dvigujejo zoper nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Kajti ne bom zaupal v svoj lok niti me ne bo rešil moj meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Toda ti si nas rešil pred našimi sovražniki in osramotil tiste, ki so nas sovražili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Z Bogom se bahamo ves dan in tvoje ime hvalimo na veke. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Toda ti si nas zavrgel in nas izročil v sramoto, in z našimi vojskami ne greš naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Delaš nas, da se pred sovražnikom obračamo nazaj, in tisti, ki nas sovražijo, plenijo zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Izročil si nas kakor ovce, določene za hrano in razkropil si nas med pogane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Zastonj prodajaš svoje ljudstvo in svojega bogastva ne povečuješ z njihovo ceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Delaš nas [za] grajo našim sosedom, norčevanje in posmeh tem, ki so okoli nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Delaš nas [za] tarčo posmeha med pogani, zmajevanje z glavo med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Moja zmedenost je nenehno pred menoj in pokrila me je sramota mojega obraza');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'zaradi glasu tistega, ki me graja in preklinja zaradi sovražnika in maščevalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Vse to je prišlo nad nas, vendar te nismo pozabili niti s tvojo zavezo nismo ravnali napačno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Naše srce se ni obrnilo niti se naši koraki niso nagnili s tvoje poti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, '§ čeprav si nas boleče zlomil na kraju zmajev in nas pokril s smrtno senco.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Če smo pozabili ime svojega Boga ali iztegnili roke k tujemu bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'mar Bog tega ne bo razpoznal? Kajti on pozna skrivnosti srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Da, zaradi tebe smo pobijani ves dan, imajo nas kakor ovce za zakol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Zbudi se, zakaj spiš, oh Gospod? Vstani, ne zavrzi nas za vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Zakaj skrivaš svoj obraz in pozabljaš našo stisko in naše zatiranje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Kajti naša duša je sklonjena v prah, naš trebuh se lepi na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Vstani za našo pomoč in nas odkupi zaradi svojih usmiljenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Vodji glasbenikov na Lilijo, za Korahove sinove, pouk, pesem o ljubeznih. Moje srce narekuje dobro stvar, govorim o zadevah, ki sem jih storil glede kralja, moj jezik je pero veščega pisca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Pravičnejši si od človeških otrok, na tvoje ustnice je izlita milost, zato te je Bog blagoslovil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Ob svoje stegno opaši svoj meč, oh najbolj mogočni, s svojo slavo in svojim veličanstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'V svojem veličanstvu uspešno jahaj zaradi resnice, krotkosti in pravičnosti, in tvoja desnica te bo učila strašnih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, '§ Tvoje puščice so ostre v srcu kraljevih sovražnikov, s čimer ljudstvo pade pod teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Tvoj prestol, oh Bog, je na veke vekov, žezlo tvojega kraljestva je žezlo pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Ljubiš pravičnost in sovražiš zlobnost, zato te je Bog, tvoj Bog, mazilil z oljem veselja nad tvojimi tovariši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, '§ Vse tvoje obleke dišijo po miri in aloji ter kasiji iz slonokoščenih palač, s čimer so te storili veselega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Kraljeve hčere so bile med tvojimi častitljivimi ženskami. Na tvoji desnici je stala kraljica v zlatu iz Ofírja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Prisluhni, oh hči in preudari ter nagni svoje uho, pozabi tudi svoje lastno ljudstvo in hišo svojega očeta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'tako bo kralj silno hrepenel [po] tvoji lepoti, kajti on je tvoj Gospod in obožuj ga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Tirska hči bo tam z darilom; celó bogati izmed ljudstva bodo milo prosili tvoje naklonjenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Kraljeva hči je vsa veličastna v notranjosti. Njeno oblačilo je iz vézenega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'H kralju bo privedena v oblačilu iz vezenine. Device, njene družabnice, ki ji sledijo, bodo privedene k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Privedene bodo z veseljem in radovanjem, vstopile bodo v kraljevo palačo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Namesto tvojih očetov bodo tvoji otroci, ki jih lahko storiš [za] prince po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Tvojemu imenu bom storil, da se [ga] bo spominjalo v vseh rodovih, zato te bo ljudstvo hvalilo na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Vodji glasbenikov za Korahove sinove, pesem za sopran. Bog je naše zatočišče in moč, v stiski zelo navzoča pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Zato se ne bomo bali, četudi se bo zemlja odstranila in četudi bodo gore odnesene v sredo morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Četudi njegove vode bučijo in so vzburkane, četudi se z naraščanjem le-teh tresejo gore. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Tam je reka, katere vodni tokovi bodo razveselili Božje mesto, sveti kraj šotorskih svetišč Najvišjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Bog je v njegovi sredi, le-to ne bo omajano. Bog mu bo pomagal in to prav zgodaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Pogani so besneli, kraljestva so bila premaknjena. Izustil je svoj glas, zemlja se je stopila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Gospod nad bojevniki je z nami, Bog Jakobov je naše zatočišče. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Pridite, glejte Gospodova dela, kakšna opustošenja je storil na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Vojnam dela, da se končajo do konca zemlje, lomi lok in sulico preseka na dvoje, bojni voz zažiga v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Bodite mirni in védite, da sem jaz Bog. Povišan bom med pogani, povišan bom na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Gospod nad bojevniki je z nami, Bog Jakobov je naše zatočišče. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Vodji glasbenikov, psalm za Korahove sinove. Oh ploskajte [s] svojimi rokami, vsa ljudstva, vzklikajte Bogu z glasom zmagoslavja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Kajti Gospod, najvišji, je strašen, on je veliki Kralj nad vso zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Ljudstva bo podjarmil pod nas in narode pod naša stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Izbral nam bo našo dediščino, odličnost Jakoba, ki ga je ljubil. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Bog se je dvignil z vzklikom, Gospod z zvokom šofarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Prepevajte hvalnice Bogu, prepevajte hvalnice. Prepevajte hvalnice našemu Kralju, prepevajte hvalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Kajti Bog je Kralj vse zemlje. Prepevajte hvalnice z razumevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Bog kraljuje nad pogani. Bog sedi na prestolu svoje svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Princi ljudstva so se zbrali skupaj, celó ljudstvo Abrahamovega Boga, kajti ščiti zemlje pripadajo Bogu, on je silno vzvišen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Pesem in psalm za Korahove sinove. Velik je Gospod in silno bodi hvaljen v mestu našega Boga, na gori njegove svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Lepa zaradi lege, radost celotne zemlje, je gora Sion na straneh severa, mesto vélikega Kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Bog je v njenih palačah razpoznan za zatočišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Kajti, glej, kralji so bili zbrani, skupaj so šli mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Videli so to in tako so se čudili; bili so vznemirjeni in odhiteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Tam sta jih prevzela strah in bolečina kakor žensko v porodnih mukah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Z vzhodnikom lomiš ladje iz Taršíša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Kakor smo slišali, tako smo videli v mestu Gospoda nad bojevniki, v mestu svojega Boga. Bog ga bo utrdil na veke. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Premišljevali smo o tvoji ljubeči skrbnosti, oh Bog, v sredi tvojega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Glede na tvoje ime, oh Bog, taka je tvoja hvala do koncev zemlje. Tvoja desnica je polna pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Naj se gora Sion veseli, naj bodo Judove hčere radostne zaradi tvojih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Hodite okoli Siona in ga obhodite, štejte njegove stolpe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Dobro označite njegove branike, opazujte njegove palače, da boste to lahko pripovedovali naslednjemu rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, '§ Kajti ta Bog je naš Bog na veke vekov. On bo naš vodnik celó do smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Vodji glasbenikov, psalm za Korahove sinove. Poslušajte to, vsa ve ljudstva, pazljivo prisluhnite, vsi vi prebivalci sveta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, '§ tako nizki kakor visoki, bogati in revni skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Moja usta bodo govorila o modrosti in premišljevanje mojega srca bo o spoznanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Svoje uho bom nagnil k prispodobi. Svoje mračne izjave bom razkrival na harfi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, '§ Zakaj naj bi se bal v dneh zla, ko me bo obdala krivičnost mojih petá?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Tisti, ki zaupajo v svoje premoženje in se bahajo z množino svojih bogastev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'nihče izmed njih ne more odkupiti svojega brata na kakršenkoli način niti Bogu dati odkupnine zanj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(kajti odkupitev njihove duše je dragocena in primanjkuje na veke),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'da naj bi mirno živel na veke in ne videl trohnobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Kajti vidi, da modri možje umrejo, prav tako se pogubita bedak in brutalna oseba in svoje premoženje zapustita drugim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Njihova notranja misel je, da bodo svoje hiše ohranili na veke in svoja bivališča za vse rodove; svoja zemljišča imenujejo po svojih imenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Kljub temu človek, ki je v časti, ne ostane; podoben je živalim, ki poginejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Ta njihova pot je njihova neumnost, vendar njihovo potomstvo odobrava njihove izjave. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, '§ Kakor ovce so položeni v grob; z njimi se bo hranila smrt in iskreni bodo zjutraj imeli nad njimi oblast in njihova lepota bo požrta v grobu, proč od njihovega bivanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Toda Bog bo mojo dušo odkupil iz oblasti groba, kajti sprejel me bo. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ne boj se, kadar nekdo bogatí, ko se slava njegove hiše množí,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'kajti ko umre, ne bo ničesar odnesel. Njegova slava se ne bo spustila za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Čeprav je, medtem ko je živel, blagoslavljal svojo dušo – ljudje te bodo hvalili, ko delaš dobro sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Šel bo k rodu svojih očetov; oni nikoli ne bodo videli svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Človek, ki je v časti, pa ne spoznava, je podoben živalim, ki poginejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Asáfov psalm. Mogočen Bog, celó Gospod, je spregovoril in poklical zemljo od sončnega vzhoda do njegovega zahoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'S Siona, popolne lepote, je zasijal Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Naš Bog bo prišel in ne bo molčal. Ogenj bo požiral pred njim in okoli njega bo zelo viharno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Klical bo k nebesom od zgoraj in k zemlji, da bo lahko sodil svoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '»Zberite k meni moje svete, tiste, ki so z žrtvijo sklenili zavezo z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Nebesa bodo oznanjala njegovo pravičnost, kajti sam Bog je sodnik. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '»Poslušaj, oh moje ljudstvo in govoril bom, oh Izrael in pričeval bom zoper tebe. Jaz sem Bog, celó tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Ne bom te grajal zaradi tvojih klavnih daritev ali tvojih žgalnih daritev, da so bile nenehno pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Iz tvoje hiše ne bom vzel nobenega bikca niti kozlov iz tvojih staj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Kajti vsaka gozdna žival je moja in živina na tisočêrih hribih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Poznam vso gorsko perjad in divje poljske živali so moje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Če bi bil lačen, ti ne bi povedal, kajti zemeljski [krog] je moj in njegova polnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Mar bom jedel meso bikov ali pil kri koz?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Bogu daruj zahvaljevanje in svoje zaobljube izpolni Najvišjemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Obrni se k meni v dnevu stiske, osvobodil te bom in ti me boš proslavil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Toda zlobnemu Bog govori: »Kaj delaš, da oznanjaš moje zakone ali da v svoja usta jemlješ mojo zavezo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Ker sovražiš poučevanje in moje besede zavračaš za seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Ko vidiš tatu, se strinjaš z njim in si postal soudeleženec z zakonolomci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Svoja usta izročaš v zlo in tvoj jezik snuje prevaro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Sediš in govoriš zoper svojega brata, obrekuješ sina svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Te stvari si storil, jaz pa sem molčal. Mislil si, da sem bil povsem takšen kakor ti. Toda grajal te bom in jih v vrsti postavil pred tvoje oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Torej preudarite to, vi, ki pozabljate Boga, da vas ne bom raztrgal na koščke in nikogar ne bo, da osvobodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kdorkoli daruje hvalo, me poveličuje in tistemu, ki pravilno ureja svoje vedênje, bom pokazal Božjo rešitev duše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Vodji glasbenikov, Davidov psalm, ko je šel k njemu prerok Natán, po tistem, ko se je ukvarjal z Batšébo. Usmili se me, oh Bog, glede na svojo ljubečo skrbnost, glede na množino svojih nežnih usmiljenj izbriši moje prestopke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Temeljito me operi moje krivičnosti in me očisti mojega greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Kajti priznavam svoje prestopke in moj greh je vedno pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Zoper tebe, tebe samega, sem grešil in storil to zlo v tvojem pogledu, da bi bil ti lahko opravičen, kadar spregovoriš in bil čist, kadar sodiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Glej, oblikovan sem bil v krivičnosti in v grehu me je spočela moja mati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Glej, želiš resnico v notranjih delih in na skritem delu mi boš storil, da spoznam modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Očisti me z izopom in bom čist. Umij me in bom bolj bel kakor sneg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Daj mi slišati radost in veselje, da se kosti, ki si jih zlomil, lahko veselijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Svoj obraz skrij pred mojimi grehi in izbriši vse moje krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, '§ Ustvari v meni čisto srce, oh Bog, in prenovi pravega duha v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Ne zavrzi me izpred svoje prisotnosti in svojega svetega duha ne vzemi od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Obnovi mi radost svoje rešitve duše in s svojim voljnim duhom me podpiraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Potem bom prestopnike učil tvojih poti in grešniki bodo spreobrnjeni k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Osvobodi me pred krivdo prelitja krvi, oh Bog, ti Bog rešitve moje duše in moj jezik bo na glas prepeval o tvoji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Oh Gospod, odpri moje ustnice in moja usta bodo naznanila tvojo hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Kajti ne želiš si klavne daritve, sicer bi ti jo dal. Ne razveseljuješ se v žgalni daritvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Božje klavne daritve so zlomljen duh. Zlomljenega in skesanega srca, oh Bog, ne boš preziral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Po svoji dobri volji stôri dobro Sionu, pozidaj jeruzalemske zidove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Potem boš zadovoljen s klavnimi daritvami pravičnosti, z žgalno daritvijo in popolno žgalno daritvijo. Potem bodo na tvojem oltarju darovali bikce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Vodji glasbenikov, pouk, Davidov psalm, ko je Edómec Doég prišel in povedal Savlu ter mu rekel: »David je prišel v Ahimélehovo hišo.« Zakaj se bahaš z vragolijo, oh mogočen človek? Božja dobrota vztraja nenehno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Tvoj jezik snuje vragolije, kakor ostra britev, ki dela varljivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Bolj ljubiš zlo kakor dobro in laganje bolj kakor govoriti pravičnost. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Ljubiš vse lakomne besede, oh ti varljiv jezik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Bog te bo prav tako uničil za vedno, odvedel te bo stran in izpulil iz tvojega prebivališča in izkoreninil iz dežele živih. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Tudi pravični bodo videli in se bali ter se mu posmehovali:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '»Glej! To je človek, ki ni storil Boga [za] svojo moč, temveč je zaupal v obilje svojega bogastva in se okrepil v svoji zlobnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Toda jaz sem podoben zeleni oljki v Božji hiši. V Božje usmiljenje zaupam na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Hvalil te bom na veke, ker si ti to storil in čakal bom na tvoje ime, kajti to je dobro pred tvojimi svetimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Vodji glasbenikov na Mahalat. Pouk. Davidov psalm. Bedak je rekel v svojem srcu: »Ni Boga.« Izprijeni so in storili so gnusno krivičnost, nikogar ni, ki dela dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Bog je pogledal z neba na človeške otroke, da vidi, če so bili katerikoli, ki so razumeli, ki so iskali Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Vsak izmed njih se je vrnil. Vsi skupaj so postali umazani; nikogar ni, ki dela dobro, ne, niti enega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Mar delavci krivičnosti nimajo spoznanja? Kdo požira moje ljudstvo, kakor jedo kruh, niso [pa] klicali k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'V velikem strahu so bili tam, kjer ni bilo strahu, kajti Bog je razkropil kosti tistega, ki tabori zoper tebe; položil si jih v sramoto, ker jih je Bog preziral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Oh, da bi prišla iz Siona Izraelova rešitev duš! Ko Bog privede nazaj ujetništvo svojega ljudstva, se bo Jakob veselil in Izrael bo vesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Vodji glasbenikov na Neginot, pouk, Davidov psalm, ko so prišli Zífovci in rekli Savlu: »Ali se David ne skriva z nami?« Reši me, oh Bog, po svojem imenu in sodi me s svojo močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Usliši mojo molitev, oh Bog, pazljivo prisluhni besedam mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Kajti zoper mene so vstali tujci in zatiralci strežejo po moji duši; pred seboj si niso postavili Boga. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Glej, Bog je moj pomočnik. Gospod je s tistimi, ki podpirajo mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Mojim sovražnikom bo povrnil zlo, odreži jih v svoji resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Velikodušno ti bom daroval, hvalil bom tvoje ime, oh Gospod, kajti to je dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Kajti osvobodil me je iz vseh težav in moje oko je videlo njegovo željo na mojih sovražnikih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Vodji glasbenikov na Neginot, pouk, Davidov psalm. Pazljivo prisluhni moji molitvi, oh Bog in ne skrij se pred mojo ponižno prošnjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Prisluhni mi in me usliši. V svoji pritožbi žalujem in zganjam hrup');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'zaradi glasu sovražnika, zaradi zatiranja zlobnega, kajti name mečejo krivičnost in z besom me sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Moje srce znotraj mene je boleče zaskrbljeno in strahote smrti so padle name.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Strah in trepet sta prišla name in groza me je preplavila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Rekel sem: »Oh da bi imel peruti kakor golobica! Kajti potem bi odletel proč in bi bil miren.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Glej, potem bi odtaval daleč proč in ostal v divjini. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Pospešil bi svoj pobeg pred vetrovnim viharjem in neurjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Uniči, oh Gospod in razdeli njihove jezike, kajti videl sem nasilje in prepir v mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dan in noč hodijo okrog po njegovih zidovih. Tudi vragolija in bridkost sta v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Zlobnost je v njegovi sredi. Prevara in zvijača ne odideta iz njegovih ulic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Kajti ni bil sovražnik, ki me je grajal, potem bi to lahko prenesel. Niti ni bil, kdor me je sovražil, ki se je poveličal zoper mene, potem bi se skril pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Toda bil si ti, človek, moj vrstnik, moj vodnik in moj znanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Skupaj sva imela prijetno namero in družno hodila v Božjo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Naj se jih polasti smrt in naj hitro gredo dol v pekel, kajti zlobnost je v njihovih bivališčih in med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Kar se mene tiče, bom klical k Bogu in Gospod me bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Zvečer, zjutraj in opoldan bom molil in glasno vpil. Slišal bo moj glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, '§ V miru je osvobodil mojo dušo pred bitko, ki je bila zoper mene, kajti mnogo jih je bilo z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Bog bo slišal in jih prizadel, celó on, ki ostaja od davnine. Sela. Ker nimajo sprememb, zato se ne bojijo Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Svoje roke je iztegnil zoper tiste, ki so v miru z njim; prelomil je svojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Besede iz njegovih ust so bile bolj gladke kakor maslo, toda v njegovem srcu je bila vojna. Njegove besede so bile mehkejše kakor olje, čeprav so bile izvlečeni meči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Svoje breme vrzi na Gospoda in on te bo podpiral. Nikoli ne bo dopustil, da bi bil pravični omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Toda ti, oh Bog, jih boš zrušil v jamo uničenja. Krvoločni in varljivi ljudje ne bodo preživeli polovice svojih dni, jaz pa bom zaupal vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Vodji glasbenikov na tiho golobico v daljnih krajih, Davidov miktám, ko so ga Filistejci prijeli v Gatu. Bodi mi usmiljen, oh Bog, kajti človek me hoče požreti, borben je, dnevno me zatira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Moji sovražniki me hočejo vsak dan požreti, kajti mnogo jih je, ki se borijo zoper mene, oh ti Najvišji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Kadar sem prestrašen, bom zaupal vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'V Bogu bom hvalil njegovo besedo, v Boga sem položil svoje trdno upanje; ne bom se bal, kaj mi more storiti meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Vsak dan pačijo moje besede. Vse njihove misli so zoper mene za zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Zbirajo se skupaj, skrivajo se, gledajo moje korake, ko čakajo na mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, '§ Ali bodo pobegnili s krivičnostjo? V svoji jezi potri ljudstva, oh Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Ti pripoveduješ o mojih tavanjih. Moje solze si polagaš v svoj meh. Mar niso v tvoji knjigi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Ko kličem k tebi, potem se bodo moji sovražniki obrnili proč. To vem, kajti Bog je zame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'V Bogu bom hvalil njegovo besedo. V Gospodu bom hvalil njegovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'V Boga sem položil svoje trdno upanje; ne bom se bal, kaj mi lahko stori človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tvoje zaobljube so nad menoj, oh Bog, povrnil ti bom hvalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Kajti mojo dušo si osvobodil pred smrtjo. Mar mojih stopal ne boš osvobodil pred padcem, da lahko hodim pred Bogom v svetlobi živih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Vodji glasbenikov, ne uničuj. Davidov miktám, ko je pred Savlom pobegnil v votlino. Bodi mi usmiljen, oh Bog, bodi mi usmiljen, kajti moja duša zaupa vate. Da, v senci tvojih peruti si bom pripravil svoje zatočišče, dokler te katastrofe ne bodo minile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Klical bom k Bogu najvišjemu, k Bogu, ki zame opravlja vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Poslal bo z neba in me rešil pred grajo tistega, ki me hoče požreti. Sela. Bog bo poslal svoje usmiljenje in svojo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, '§ Moja duša je med levi in ležim celó med tistimi, ki so vneti z ognjem, celó človeškimi sinovi, katerih zobje so sulice in puščice ter njihov jezik oster meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Bodi povišan, oh Bog, nad nebo, naj bo tvoja slava nad vso zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Pripravili so mrežo za moje korake, moja duša je sklonjena. Zame so pred menoj izkopali jamo in v katere sredo so sami padli. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Moje srce je trdno, oh Bog, moje srce je trdno. Prepeval bom in dajal hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Zbudi se kvišku, moja slava, zbudita se plunka in harfa. Jaz sam se bom prebudil zgodaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Hvalil te bom, oh Gospod, med ljudstvom, prepeval ti bom med narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Kajti tvoje usmiljenje je veliko do neba in tvoja resnica do oblakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Bodi povišan, oh Bog, nad nebo. Naj bo tvoja slava nad vso zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Vodji glasbenikov, ne uničuj. Davidov miktám. Ali zares govorite pravičnost, oh skupnost? Ali sodite iskreno, oh vi človeški sinovi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Da, v srcu počnete zlobnost, na zemlji presojate nasilje svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Zlobni so odtujeni od maternice. Proč odidejo takoj, ko so rojeni, govoreč laži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Njihov strup je podoben kačjemu strupu. Podobni so gluhemu gadu, ki si maši svoje uho,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'ki ne bo prisluhnil glasu krotilcev, ki nikoli ne kroti tako oprezno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Oh Bog, polomi jim njihove zobe v njihovih ustih. Mladim levom izruj velik zob, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, '§ Naj se stopijo kakor vode, ki nenehno tečejo. Ko on napenja svoj lok, da izstreli svoje puščice, naj bodo kakor razrezani na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Kakor polž, ki se stopi, naj premine vsak izmed njih. Kakor preran porod ženske, da oni ne morejo videti sonca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, '§ Preden lahko vaši lonci začutijo trnje, jih bo odvedel proč kakor z vrtinčastim vetrom, tako žive kakor v svojem besu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Pravični se bo veselil, ko vidi maščevanje. Svoja stopala si bo umil v krvi zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Tako da bo človek rekel: »Resnično je nagrada za pravičnega. Resnično, on je Bog, ki sodi na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Vodji glasbenikov. Ne uničuj. Davidov miktám, ko je Savel poslal in so stražili hišo, da ga ubijejo. Osvobodi me pred mojimi sovražniki, oh moj Bog. Brani me pred tistimi, ki se dvigujejo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Osvobodi me pred delavci krivičnosti in reši me pred krvoločnimi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Kajti, glej, za mojo dušo prežijo v zasedi, mogočni so se zbrali zoper mene; ne zaradi mojega prestopka niti ne zaradi mojega greha, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Brez moje krivde tečejo in se pripravljajo. Zbudi se, da mi pomagaš in glej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ti torej, oh Gospod Bog nad bojevniki, Izraelov Bog, zbudi se, da obiščeš vse pogane. Z nobenim zlobnim prestopnikom ne bodi usmiljen. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Vračajo se zvečer, zganjajo hrup kakor pes in krožijo po mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Glej, s svojimi usti bruhajo, meči so na njihovih ustnicah, kajti pravijo: »Kdo sliši?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Toda ti, oh Gospod, se jim boš posmehoval, vse pogane boš imel v posmeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Zaradi njegove moči bom čakal nate, kajti Bog je moja obramba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Bog mojega usmiljenja me bo vodil. Bog mi bo dal videti mojo željo na mojih sovražnikih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Ne ubij jih, da ne bi moje ljudstvo pozabilo. Razkropi jih s svojo močjo in zlomi jih, oh Gospod, naš ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Zaradi greha njihovih ust in besed njihovih ustnic naj bodo celó prijeti v svojem ponosu in za preklinjanje in laži, katere govorijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Použij jih v besu, použij jih, da jih ne bo in naj spoznajo, da Bog vlada v Jakobu do koncev zemlje. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Zvečer naj se vrnejo in naj zganjajo hrup kakor pes ter krožijo po mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Naj se potikajo gor in dol za hrano in godrnjajo, če ne bodo nasičeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Toda jaz bom prepeval o tvoji moči, da, zjutraj bom na glas prepeval o tvojem usmiljenju, kajti ti si bil moja obramba in zatočišče na dan moje stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Tebi, oh moja moč, bom prepeval, kajti Bog je moja obramba in Bog mojega usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Vodji glasbenikov na Lilija pričevanja. Davidov miktám, za poučevanje; ko se je bojeval z Aramejci iz Mezopotamije in z Aramejci iz Cobe, ko se je Joáb vrnil in udaril Edómce v solni dolini, dvanajst tisoč mož. Oh Bog, zavrgel si nas, razkropil si nas, razžaljen si bil; oh, ponovno se obrni k nam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Storil si, da zemlja trepeta, zlomil si jo; zaceli njene vrzeli, kajti trese se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Svojemu ljudstvu si pokazal težke stvari. Storil si nam, da pijemo vino osuplosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, '§ Tem, ki se te bojijo, si dal prapor, da bi bil ta lahko dvignjen zaradi resnice. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Da bodo tvoji ljubljeni lahko osvobojeni, reši s svojo desnico in me usliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Bog je spregovoril v svoji svetosti: »Veselil se bom, razdelil bom Sihem in odmeril Sukótsko dolino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Gileád je moj in Manáse je moj; tudi Efrájim je moč moje glave, Juda je moj postavodajalec,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moáb je moj lonec za pranje, nad Edóm bom vrgel svoj čevelj; Filisteja zmaguj zaradi mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kdo me bo privedel v utrjeno mesto? Kdo me bo vodil v Edóm?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Mar ne ti, oh Bog, ki si nas zavrgel? In ti, oh Bog, ki nisi odšel z našimi vojskami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Daj nam pomoč iz stiske, kajti prazna je človeška pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Zaradi Boga bomo delali hrabro, kajti on je ta, ki bo pomendral naše sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Vodji glasbenikov na Neginot, Davidov psalm. Sliši moj klic, oh Bog, prisluhni moji molitvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Od konca zemlje bom klical k tebi, ko je moje srce preplavljeno. Vôdi me k skali, ki je višja kakor jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Kajti zame si bil zatočišče in močna trdnjava pred sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'V tvojem šotorskem svetišču bom ostal na veke. Zaupal bom v skrivališče tvojih peruti. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Kajti ti, oh Bog, si uslišal moje zaobljube; dal si mi dediščino tistih, ki se bojijo tvojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Kralju boš podaljšal življenje in njegova leta kakor mnoge rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Pred Bogom bo on ostal na veke. O pripravi usmiljenje in resnico, ki ga lahko varuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Tako bom na veke prepeval hvalo tvojemu imenu, da bom lahko dnevno opravljal svoje zaobljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Vodji glasbenikov, Jedutúnu, Davidov psalm. Resnično, moja duša čaka na Boga, od njega prihaja rešitev moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Samo on je moja skala in rešitev moje duše, on je moja obramba, ne bom silno omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Doklej boste zoper človeka domišljali vragolijo? Vsi izmed vas boste umorjeni, kakor usločen zid boste in kakor majajoča se ograja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Samo posvetujejo se, da ga vržejo dol od njegove odličnosti, veselijo se v lažeh, blagoslavljajo s svojimi usti, toda navznoter preklinjajo. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Moja duša, čakaj samo na Boga, kajti moje pričakovanje je od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Samo on je moja skala in rešitev moje duše. On je moja obramba, ne bom omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'V Bogu je rešitev moje duše in moja slava. Skala moje moči in moje zatočišče je v Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Ob vseh časih zaupajte vanj, ve ljudstva, svoje srce izlijte pred njim. Bog je za nas zatočišče. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, '§ Ljudje nizkega položaja so zagotovo ničevost in ljudje visokega položaja so laž. Položeni na tehtnico so vsi skupaj lažji kakor ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ne zaupaj v zatiranje in ne postani prazen v ropu. Če bogastva narastejo, svojega srca ne naveži nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Bog je spregovoril enkrat, to sem slišal dvakrat, da oblast pripada Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Tudi tebi, oh Gospod, pripada usmiljenje, kajti vsakemu človeku povračaš glede na njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Davidov psalm, ko je bil v Judovi divjini. Oh Bog, ti si moj Bog, zgodaj te bom iskal. Mojo dušo žeja po tebi, moje meso hrepeni po tebi v suhi in žejni deželi, kjer ni vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'da bi videl tvojo oblast in tvojo slavo, tako kot sem te videl v svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Ker je tvoja ljubeča skrbnost boljša kot življenje, te bodo moje ustnice hvalile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Tako te bom blagoslavljal, medtem ko živim, svoje roke bom vzdigoval v tvojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Moja duša bo nasičena kakor z mozgom in tolščo in moja usta te bodo hvalila z radostnimi ustnicami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'ko se te spominjam na svoji postelji in o tebi premišljujem v nočnih stražah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Ker si bil ti moja pomoč, zato se bom veselil v senci tvojih peruti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Moja duša trdno sledi tebi; tvoja desnica me podpira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Toda tisti, ki iščejo mojo dušo, da bi jo uničili, bodo šli v globočine zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Padli bodo pod mečem; delež bodo za lisice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Toda kralj se bo veselil v Bogu, vsak, kdor prisega z njim, bo v tem užival, toda usta teh, ki govorijo laži, bodo zamašena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Vodji glasbenikov. Davidov psalm. Poslušaj moj glas, oh Bog, v moji molitvi, varuj moje življenje strahu pred sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Skrij me pred skrivnim načrtom hudobnih, pred vstajo delavcev krivičnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'ki brusijo svoj jezik kakor meč in upogibajo svoje loke, da bi streljali svoje puščice, celó grenke besede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'da bi lahko na skrivnem streljali na popolnega. Nenadoma streljajo nanj in se ne bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Med seboj se hrabrijo v zli zadevi. Na skrivaj se posvetujejo o nastavljanju zank; pravijo: »Kdo jih bo videl?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Preiskujejo krivičnosti, dovršijo marljivo iskanje. Notranja misel vsakogar izmed njih in srce, oboje je globoko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Toda Bog bo nanje streljal s puščico, nenadoma bodo ranjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Tako bodo dosegli, da bo njihov lastni jezik padel nanje. Vsi, ki jih vidijo, bodo zbežali stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Vsi ljudje se bodo bali in bodo oznanjali Božje delo, kajti o njegovem dejanju bodo modro preudarjali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Pravični bodo veseli v Gospodu in bodo zaupali vanj in vsi iskreni v srcu bodo ponosni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Vodji glasbenikov, psalm in Davidova pesem. Hvala čaka nate, oh Bog, na Sionu. Tebi bo opravljena zaobljuba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Oh ti, ki slišiš molitev, k tebi bo prišlo vse meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Krivičnosti so prevladale zoper mene. Glede naših prestopkov, jih boš ti očistil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Blagoslovljen je človek, ki ga ti izbereš in povzročaš, da se približa k tebi, da bi lahko prebival v tvojih dvorih. Nasičeni bomo z dobroto tvoje hiše, celó tvojega svetega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'S strašnimi stvarmi nam boš odgovoril v pravičnosti, oh Bog, rešitev naših duš, ki si zaupanje vseh koncev zemlje in tistih, ki so daleč stran na morju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'ki s svojo močjo trdno postavljaš gore, opasan si z močjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'ki umirjaš šumenje morij, šumenje njih valov in hrup ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Tudi tisti, ki prebivajo v najbolj oddaljenih delih, se bojijo ob tvojih simbolih. Izhajanju jutra in večera povzročaš, da se veselita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Obiskuješ zemljo in jo namakaš. Z Božjo reko, ki je polna vode, jo silno bogatiš. Potem ko si zanjo tako poskrbel, jim pripravljaš žito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Obilno namakaš njene gorske grebene, poravnavaš njene brazde, z nalivi jo mehčaš, blagoslavljaš njeno brstenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Leto kronaš s svojo dobroto in tvoje steze kapljajo maščobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Kapljajo na pašnike divjine in majhni hribi se veselijo na vsaki strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Pašniki so oblečeni s tropi, tudi doline so pokrite z žitom, vzklikajo od veselja, tudi prepevajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Vodji glasbenikov. Pesem ali psalm. Naredite radosten glas Bogu, vse ve dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'pojte čast njegovemu imenu, njegovo hvalo naredite veličastno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, '§ Recite Bogu: »Kako strašen si v svojih delih! Zaradi veličine tvoje moči se ti bodo podredili tvoji sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Vsa zemlja te bo oboževala in ti prepevala, prepevali bodo k tvojemu imenu.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Pridite in glejte dela Boga. Strašen je v svojem delovanju do človeških otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Morje je spremenil v kopno zemljo. Skozi rečni tok so šli peš, tam smo se veselili v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'S svojo močjo vlada na veke, njegove oči opazujejo narode; naj se uporni ne povišujejo. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Oh blagoslavljajte našega Boga, ve ljudstva in storite, da se sliši glas njegove hvale,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'ki našo dušo drži pri življenju in ne pusti, da bi bila naša stopala premaknjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Kajti ti, oh Bog, si nas potrdil, preizkusil si nas, kakor je preizkušeno srebro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Privedel si nas v mrežo, na naša ledja polagaš stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Ljudem si storil, da jahajo nad našimi glavami. Šli smo skozi ogenj in skozi vodo, toda ti si nas privedel v premožen kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'V tvojo hišo bom šel z žgalnimi daritvami, izpolnil ti bom svoje zaobljube,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'ki so jih izrekle moje ustnice in spregovorila moja usta, ko sem bil v stiski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Daroval ti bom žgalne daritve pitancev s kadilom ovnov, daroval ti bom bikce s kozli. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Pridite in prisluhnite vsi vi, ki se bojite Boga in oznanil vam bom, kaj je storil za mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'K njemu sem klical s svojimi usti in povzdignjen je bil z mojim jezikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Če v svojem srcu upoštevam krivičnost, me Gospod ne bo uslišal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'toda Bog me je resnično uslišal, prisluhnil je glasu moje molitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Blagoslovljen bodi Bog, ki ni odklonil moje molitve niti svojega usmiljenja od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Vodji glasbenikov na Neginot, psalm ali pesem. Bog nam bodi usmiljen in nas blagoslovi in pripravi svoj obraz, da sveti na nas. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Da se tvoja pot lahko spozna na zemlji, tvoje rešilno zdravje med vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Naj te hvali ljudstvo, oh Bog, naj te hvalijo vsa ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Oh naj bodo narodi veseli in prepevajo zaradi veselja, kajti pravično boš sodil ljudstvo in upravljal narode na zemlji. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Naj te hvali ljudstvo, oh Bog, naj te hvalijo vsa ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, '§ Potem bo zemlja obrodila svoj donos in Bog, celó naš lastni Bog, nas bo blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Bog nas bo blagoslovil in bali se ga bodo vsi konci zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Vodji glasbenikov, psalm ali Davidova pesem. § Naj vstane Bog, naj bodo njegovi sovražniki razkropljeni. Naj tudi tisti, ki ga sovražijo, bežijo pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Kakor je pregnan dim, tako jih preženi. Kakor se vosek stopi pred ognjem, tako naj bodo zlobni pogubljeni pred prisotnostjo Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, '§ Toda pravični naj bodo veseli, naj se veselijo pred Bogom. Da, naj se silno veselijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, '§ Prepevajte Bogu, prepevajte hvalnice njegovemu imenu. Povzdigujte njega, ki jaha po nebesih s svojim imenom Jah in se veselite pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Oče osirotelim in sodnik vdovam je Bog v svojem svetem prebivališču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Bog osamljene postavlja v družine, osvobaja tiste, ki so zvezani z verigami, toda uporni prebivajo v suhi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Oh Bog, ko si šel naprej pred svojim ljudstvom, ko si korakal skozi divjino, Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'se je zemlja tresla, tudi nebo je kapljalo ob prisotnosti Boga. Celó sam Sinaj je bil premaknjen ob prisotnosti Boga, Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Ti, oh Bog, si poslal obilen dež, s čimer si potrdil svojo dediščino, ko je bila izmučena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Tvoja skupnost je prebivala tam. Ti, oh Bog, si od svoje dobrote pripravil za uboge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, '§ Gospod je dal besedo. Velika je bila skupina teh, ki so jo razglašali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, '§ Kralji vojská so naglo zbežali; tista pa, ki je ostala doma, je razdelila plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, '§ Čeprav si ležala med lonci, boš vendar kakor peruti golobice, [ki sta] pokriti s srebrom in njena peresa z rumenim zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Ko je Vsemogočni v njej razkropil kralje, je bilo belo kakor sneg na Calmónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, '§ Božja gora je kakor bašánska gora, visoka gora kakor bašánska gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Zakaj poskakujete, ve visoke gore? To je gora, na kateri želi prebivati Bog; da, Gospod bo na njej prebival na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, '§ Božjih bojnih vozov je dvajset tisoč, celó tisoči angelov. Gospod je med njimi kakor na Sinaju, na svetem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, '§ Ti si se dvignil na visoko, vodil si ujeto ujetništvo. Prejel si darila za ljudi, da, tudi za uporne, da bi med njimi lahko prebival Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Blagoslovljen bodi Gospod, ki nas dnevno zalaga s koristmi, celó Bog rešitve naše duše. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Kdor je naš Bog, je Bog rešitve duše in Bogu, Gospodu, pripadajo izhodi pred smrtjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Toda Bog bo ranil glavo svojih sovražnikov in lasato tême tistega, ki nenehno hodi v svojih prekrških.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Gospod je rekel: »Ponovno bom privedel iz Bašána, ponovno bom svoje ljudstvo privedel iz morskih globin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'da bo tvoje stopalo lahko pomočeno v krvi tvojih sovražnikov in jezik tvojih psov v istem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Videli so tvoje sprevode, oh Bog, celó sprevode mojega Boga, mojega Kralja, v svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Pevci so šli spredaj, igralci na glasbila so sledili zadaj, med njimi so bile gospodične, ki so igrale s tamburini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Blagoslavljajte Boga v skupnostih, celó Gospoda, iz Izraelovega studenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tam je majhen Benjamin z njihovim vladarjem, Judovi princi in njihov zbor, Zábulonovi princi in Neftálijevi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Tvoj Bog je zapovedal tvojo moč. Ojačaj, oh Bog, to, kar si izvršil za nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Zaradi tvojega templja pri Jeruzalemu ti bodo kralji prinašali darila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Oštej skupino suličarjev, množico bikov s teleti ljudstva, dokler vsakdo sebe ne podredi s koščki srebra. Razkropi ljudstvo, ki se razveseljuje v vojni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Princi bodo prišli iz Egipta, Etiopija bo svoje roke kmalu iztegnila k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Prepevajte Bogu, ve, zemeljska kraljestva, oh prepevajte hvalnice Gospodu, Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Njemu, ki jaha po nebes nebesih, ki so bila od davnine; glej, poslal je svoj glas in to mogočen glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Moč pripišite Bogu. Njegova odličnost je nad Izraelom in njegova moč je v oblakih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Oh Bog, ti si strašen iz svojih svetih prostorov. Izraelov Bog je ta, ki daje svojemu ljudstvu moč in oblast. Blagoslovljen bodi Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Vodji glasbenikov na Lilijo, Davidov psalm. Reši me, oh Bog, kajti vode vstopajo v mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Tonem v globoko blato, kjer ni stojišča. Prišel sem v globoke vode, kjer me preplavljajo poplave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Naveličan sem svojega joka, moje grlo je suho, moje oči pešajo, ko čakam na svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Tistih, ki me sovražijo brez razloga, je več kakor las moje glave. Tisti, ki me hočejo uničiti, so moji krivični sovražniki, mogočni so. Potem sem povrnil to, česar nisem vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Oh Bog, ti poznaš mojo nespametnost in moji grehi niso skriti pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Naj tisti, ki čakajo nate, oh Gospod Bog nad bojevniki, ne bodo osramočeni zaradi mene. Naj tisti, ki te iščejo, ne bodo zbegani zaradi mene, oh Izraelov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Ker zaradi tebe prenašam grajo, je moj obraz pokrila sramota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Postal sem tujec svojim bratom in neznanec otrokom svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Kajti gorečnost za tvojo hišo me je použila in graje teh, ki so te grajali, so padle name.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Ko sem jokal in svojo dušo karal s postom, je bilo to za mojo grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Tudi vrečevino sem si naredil za svojo obleko in postal sem jim v pregovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Tisti, ki sedijo v velikih vratih, govorijo zoper mene in bil sem pesem pijancem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Toda, kar se mene tiče, je moja molitev k tebi, oh Gospod, ob sprejemljivem času. Oh Bog, v množici svojih usmiljenj me usliši, v resnici tvoje rešitve duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Osvobodi me iz blata in ne pusti me utoniti. Naj bom osvobojen pred temi, ki me sovražijo in ven iz velikih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Naj me ne preplavi voda niti naj me ne požre globina in jama naj ne zapre svojih ust nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Usliši me, oh Gospod, kajti tvoja ljubeča skrbnost je dobra. Obrni se k meni glede na množino svojih nežnih usmiljenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Svojega obraza ne skrij pred svojim služabnikom, kajti v stiski sem. Naglo me usliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Približaj se moji duši in odkupi jo. Osvobodi me zaradi mojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Spoznal si mojo grajo in mojo sramoto ter mojo nečast. Moji nasprotniki so vsi pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Graja je zlomila moje srce in poln sem potrtosti. Pričakoval sem kakega, da se usmili, toda ni bilo nobenega; in tolažnikov, toda nisem našel nobenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Za jed so mi dali tudi žolč in v moji žeji so mi dali piti kis.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Njihova miza naj pred njimi postane zanka, in to, kar naj bi bilo za njihovo blaginjo, naj postane past.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Naj njihove oči otemnijo, da ne vidijo in njihovim ledjem stôri, da se nenehno tresejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Nanje izlij svoje ogorčenje in naj jih zgrabi tvoja srdita jeza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Naj bo njihovo prebivališče zapuščeno in naj nihče ne prebiva v njihovih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Kajti preganjajo tistega, ki si ga ti udaril in govorijo v žalost tistih, ki si jih ranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Njihovi krivičnosti dodaj krivičnost, in naj ne pridejo v tvojo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Naj bodo izbrisani iz knjige življenja in ne bodo zapisani s pravičnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Toda jaz sem ubog in žalosten. Naj me tvoja rešitev duše, oh Bog, postavi visoko gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'S pesmijo bom hvalil Božje ime in ga poveličeval z zahvaljevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'To bo tudi bolj ugajalo Gospodu kakor vol ali bikec, ki ima roge in kopita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Ponižni bo to videl in bil vesel in vaše srce, ki išče Boga, bo živelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Kajti Gospod posluša uboge in ne prezira svojih jetnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Naj ga hvalita nebo in zemlja, morja in vsaka stvar, ki se giblje v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Kajti Bog bo rešil Sion in pozidal Judova mesta, da bodo lahko tam prebivali in to imeli v posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Tudi seme njegovih služabnikov bo to podedovalo in tisti, ki ljubijo njegovo ime, bodo prebivali v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Vodji glasbenikov, Davidov psalm, da privede v spomin. Podvizaj se, oh Bog, da me osvobodiš; podvizaj se, da mi pomagaš, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Naj bodo osramočeni in zbegani [tisti], ki strežejo po moji duši. Naj bodo obrnjeni nazaj in postavljeni v zmedenost, ki želijo mojo bolečino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Naj bodo za nagrado svojega sramotenja obrnjeni nazaj, ki pravijo: »Aha, aha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Naj se vsi tisti, ki te iščejo, veselijo in bodo veseli v tebi. Naj tisti, ki ljubijo tvojo rešitev duše, nenehno govorijo: »Naj bo Bog poveličan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Toda jaz sem ubog in pomoči potreben. Podvizaj se k meni, oh Bog. Ti si moja pomoč in moj osvoboditelj; oh Gospod, ne mudi se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Vate, oh Gospod, polagam svoje trdno upanje. Naj ne bom nikoli postavljen v zadrego.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Osvobodi me v svoji pravičnosti in mi povzroči, da pobegnem. Nagni k meni svoje uho in me reši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Bodi moje močno prebivališče, kamor se bom lahko nenehno zatekal. Dal si zapoved, da me rešiš, kajti ti si moja skala in moja trdnjava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Osvobodi me, oh moj Bog, iz roke zlobnega, iz roke nepravičnega in krutega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Kajti ti si moje upanje, oh Gospod Bog, ti si moje trdno zaupanje od moje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'S teboj sem bil podpiran od maternice. Ti si tisti, ki me je vzel iz notranjosti moje matere. O tebi bo nenehno moja hvala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Mnogim sem kakor čudež, toda ti si moje močno zatočišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Naj bodo moja usta napolnjena s tvojo hvalo in s tvojo častjo ves dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne zavrzi me v času visoke starosti, ne zapusti me, ko oslabi moja moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Kajti moji sovražniki govorijo zoper mene in tisti, ki prežijo na mojo dušo, se skupaj posvetujejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'rekoč: »Bog ga je zapustil. Preganjajte in zgrabite ga, kajti nikogar ni, da ga osvobodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Oh Bog, ne bodi daleč od mene. O moj Bog, podvizaj se zaradi moje pomoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Naj bodo zbegani in uničeni tisti, ki so nasprotniki moji duši; naj bodo pokriti z grajo in nečastjo tisti, ki iščejo mojo bolečino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Toda jaz bom nenehno upal in še bolj in bolj te bom hvalil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Moja usta bodo naznanjala tvojo pravičnost in tvojo rešitev duše ves dan, kajti ne poznam njihovih števil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Šel bom v moči Gospoda Boga. Omenjal bom tvojo pravičnost, namreč samo tvojo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Oh Bog, učil si me od moje mladosti in doslej sem oznanjal tvoja čudovita dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Tudi sedaj, ko sem star in sivolas, oh Bog, me ne zapusti, dokler ne pokažem tvoje moči temu rodu in tvojo oblast vsakemu, ki bo prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Tudi tvoja pravičnost, oh Bog, je zelo visoka, ki si storil velike stvari. Oh Bog, kdo ti je podoben!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Ti, ki si mi pokazal velike in boleče stiske, me boš ponovno oživil in ponovno privedel gor iz globin zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Povečal boš mojo veličino in me tolažil na vsaki strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Prav tako te bom hvalil s plunko, celó tvojo resnico, oh moj Bog. Tebi bom prepeval s harfo, oh ti, Sveti Izraelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Moje ustnice se bodo silno veselile, kadar ti prepevam in moja duša, ki si jo odkupil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Tudi moj jezik bo ves dan govoril o tvoji pravičnosti, kajti zbegani so, ker so privedeni v sramoto [tisti], ki iščejo mojo bolečino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Psalm za Salomona. Daj kralju svoje sodbe, oh Bog in svojo pravičnost kraljevemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Tvoje ljudstvo bo sodil s pravičnostjo in tvoje uboge s sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Gore bodo ljudstvu prinesle mir in majhni hribi po pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Sodil bo uboge izmed ljudstva, rešil bo otroke pomoči potrebnih, zatiralca pa bo razbil na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Bali se te bodo, dokler ostajata sonce in luna, skozi vse rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Prišel bo dol kakor dež na pokošeno travo, kakor nalivi, ki namakajo zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'V njegovih dneh bo pravični cvetel in obilje miru tako dolgo, kot ostaja luna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Imel bo tudi gospostvo od morja do morja in od reke do koncev zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Tisti, ki prebivajo v divjini, se bodo poklonili pred njim, njegovi sovražniki pa bodo lizali prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Kralji iz Taršíša in z otokov bodo prinašali darila. Kralji iz Sabe in Sebe bodo ponujali darove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Da, vsi kralji bodo padli dol pred njim. Služili mu bodo vsi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Kajti osvobodil bo pomoči potrebnega, ko vpije; tudi ubogega in tistega, ki nima pomočnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Prizanesel bo ubogemu in pomoči potrebnemu in rešil duše pomoči potrebnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Njihove duše bo odkupil pred prevaro in nasiljem, in njihova kri bo dragocena v njegovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Živel bo in njemu bo dano od zlata iz Sabe. Zanj bo narejena tudi nenehna molitev in dnevno bo hvaljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, '§ Prgišče žita bo na zemlji do vrhov gorá. Njen sad se bo tresel kakor Libanon in tisti iz mesta bodo cveteli kakor zemeljska trava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Njegovo ime bo ostalo na veke. Njegovo ime se bo razširjalo, dokler [bo] sonce in ljudje bodo blagoslovljeni v njem. Vsi narodi ga bodo imenovali blagoslovljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Blagoslovljen bodi Gospod Bog, Izraelov Bog, ki edini dela čudovite stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Blagoslovljeno bodi njegovo veličastno ime na veke in vsa zemlja naj bo napolnjena z njegovo slavo. Amen in Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Molitve Davida, Jesejevega sina, so končane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Asáfov psalm. Resnično, Bog je dober do Izraela, torej tistim, ki so čistega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Toda kar se mene tiče, so moja stopala skoraj odšla, moji koraki so malodane spodrsnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Kajti bil sem nevoščljiv nad nespametnimi, ko sem videl uspevanje zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Kajti v njihovi smrti ni vezi, vendar je njihova moč trdna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Niso v stiski, kakor drugi ljudje niti niso trpinčeni kakor drugi ljudje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Zato jih ošabnost obdaja naokoli kakor veriga, nasilje jih pokriva kakor obleka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Njihove oči izstopajo z mastnostjo. Imajo več, kot si lahko želi srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Izprijeni so in glede zatiranja govorijo zlobno, govorijo vzvišeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, '§ Svoja usta postavljajo zoper nebesa in njihov jezik hodi po zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Zato se njegovo ljudstvo vrača sèm in iztisnjene so jim polne čaše vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Pravijo: »Kako Bog ve? In ali je znanje v Najvišjem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Glej, to so brezbožni, ki uspevajo v svetu, povečujejo se v bogastvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Resnično sem zaman očistil svoje srce in svoje roke umil v nedolžnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Kajti ves dan sem bil trpinčen in kaznovan vsako jutro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Če rečem: »Govoril bom na ta način,« glej, bi se pregrešil zoper rod tvojih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Ko sem premišljeval, da to spoznam, je bilo zame preveč boleče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'dokler nisem odšel v Božje svetišče, potem sem razumel njihov konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Zagotovo si jih postavil na spolzke kraje, podiraš jih v uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kako so v hipu privedeni v opustošenje! Popolnoma so použiti s strahotami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Kakor sanje, ko se nekdo zbudi; tako boš, oh Gospod, ko se zbudiš, preziral njihovo podobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Tako je bilo moje srce užaloščeno in v svoji notranjosti sem bil zboden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Tako nespameten sem bil in neveden. Pred teboj sem bil kakor žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Kljub temu sem nenehno s teboj. Prijel si me za mojo desnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Usmerjal me boš s svojim nasvetom in potem me sprejmi v slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Koga imam v nebesih razen tebe? In nikogar ni na zemlji, ki si ga želim poleg tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Moje meso in moje srce odpovedujeta, toda Bog je moč mojega srca in moj delež na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Kajti glej, tisti, ki so daleč od tebe, se bodo pogubili. Uničil si vse tiste, ki z vlačuganjem gredo od tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Toda zame je dobro, da se približam Bogu. Svoje trdno upanje sem položil v Gospoda Boga, da bom lahko oznanjal vsa tvoja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Asáfov pouk. Oh Bog, zakaj nas zavračaš za vedno? Zakaj se tvoja jeza kadi proti ovcam tvoje paše?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Spomni se svoje skupnosti, ki si jo odkupil od davnine, palico svoje dediščine, ki si jo odkupil, to goro Sion, kjer prebivaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Dvigni svoja stopala k neprestanim opustošenjem, celó vsemu kar je sovražnik zlobnega storil v svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tvoji sovražniki rjovijo v sredi tvojih skupnosti, svoje zastave so postavili za znamenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, '§ Človek je bil slaven, če je nad debela drevesa dvigoval sekire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Toda sedaj so s sekirami in kladivi takoj zlomili rezljano delo le-tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ogenj so vrgli v tvoje svetišče, s podrtjem do tal so omadeževali bivališče tvojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'V svojih srcih so rekli: »Skupaj jih uničimo.« V deželi so požgali vse Božje sinagoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Ne vidimo svojih znamenj. Nobenega preroka ni več niti tukaj med nami ni nobenega, ki ve doklej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Oh Bog, doklej bo nasprotnik grajal? Mar bo sovražnik na veke preklinjal tvoje ime?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Zakaj umikaš svojo roko, celó svojo desnico? Iztrgaj jo iz svojega naročja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Kajti Bog je moj Kralj od davnine, ki dela rešitev duš v sredi zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'S svojo močjo si razdelil morje. Razbijaš glave zmajem v vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Razbijaš glave leviatána na koščke in ga daješ, da postane hrana ljudstvu, ki prebiva v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, '§ Združil si studenec in morje, osušuješ mogočne reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, '§ Dan je tvoj, tudi noč je tvoja, pripravil si svetlobo in sonce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Določil si vse meje zemlje. Naredil si poletje in zimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Spomni se, da je sovražnik grajal, oh Gospod in da je nespametno ljudstvo izrekalo bogokletje proti tvojemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Oh ne izročaj duše svoje grlice množici zlobnih. Ne pozabi skupnosti svojih ubogih na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, '§ Ozri se k zavezi, kajti temni kraji zemlje so polni prebivališč krutosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Oh naj se zatirani ne vrne osramočen. Naj ubog in pomoči potreben hvalita tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Vstani, oh Bog, zagovarjaj svojo lastno pravdo. Spomni se, kako te nespameten človek dnevno graja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Ne pozabi glasu svojih sovražnikov. Hrup teh, ki vstajajo zoper tebe, se nenehno povečuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Vodji glasbenikov, ne uničuj, psalm ali Asáfova pesem. Tebi, oh Bog, dajemo zahvaljevanje, tebi dajemo zahvaljevanje, kajti tvoja čudovita dela oznanjajo, da je tvoje ime blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Ko bom sprejel skupnost, bom sodil iskreno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Zemlja in vsi njeni prebivalci se raztapljajo, jaz podpiram njene stebre. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Bedakom sem rekel: »Ne ravnajte nespametno« in zlobnim: »Ne dvigajte roga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Svojega roga ne dvigajte visoko gor. Ne govorite s trdim vratom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Kajti povišanje ne prihaja niti od vzhoda niti od zahoda niti od juga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Toda Bog je sodnik, odstavlja enega in postavlja drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Kajti v Gospodovi roki je čaša in vino je rdeče, polno mešanice; in izliva iz istega, toda te droži bodo vsi zlobneži zemlje izželi in jih popili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Toda jaz bom razglašal na veke, prepeval bom hvalnice Jakobovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Tudi vse rogove zlobnih bom odrezal; toda rogovi pravičnih bodo povišani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Vodji glasbenikov na Neginot, psalm ali Asáfova pesem. V Judu je Bog poznan. Njegovo ime v Izraelu je veliko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Tudi v Salemu je njegovo šotorsko svetišče in njegovo bivališče na Sionu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tam je prelomil puščice loka, ščit, meč in bitko. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Ti si veličastnejši in odličnejši kakor gore plena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Arogantni so oplenjeni, spali so svoje spanje. Nihče izmed mogočnih mož ni našel svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Ob tvojem oštevanju, Bog Jakobov, sta tako bojni voz, kakor konj vržena v smrtno spanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ti, celó tebe se je bati in kdo lahko stoji v tvojem pogledu, kadar si jezen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Povzročil si, da se z neba sliši sodba; zemlja se je zbala in postala tiha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'ko je k sodbi vstal Bog, da reši vse krotke na zemlji. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Zagotovo te bo hvalil človeški bes. Ostanek besa boš ti obrzdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Zaobljubi se in plačaj Gospodu, svojemu Bogu. Naj vsi tisti, ki so okoli njega, prinesejo darila tistemu, ki bi se ga morali bati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Odrezal bo duha princev. Strašen je do zemeljskih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Vodji glasbenikov, Jedutúnu, Asáfov psalm. S svojim glasom sem klical k Bogu, celó s svojim glasom k Bogu in mi je prisluhnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, '§ Na dan svoje stiske sem iskal Gospoda. Moja vnetja so se gnojila ponoči in niso odnehala. Moja duša je odklanjala, da bi bila potolažena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Spomnil sem se Boga in bil vznemirjen. Pritoževal sem se in moj duh je bil nadvladan. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Moje oči držiš budne. Tako sem vznemirjen, da ne morem govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Preudarjal sem [o] dneh iz davnine, letih starodavnih časov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Spominjam se svoje pesmi ponoči. Posvetujem se s svojim lastnim srcem in moj duh je storil marljivo preiskavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '›Ali bo Gospod za vedno zavračal ali ne bo več naklonjen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Je njegovo usmiljenje popolnoma odšlo za vedno? Ali njegova obljuba odpove na vékomaj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Je Bog pozabil biti milostljiv? Ali je v jezi zaprl svoja nežna usmiljenja?‹ Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Rekel sem: »To je moja šibkost, toda spominjal se bom let desnice Najvišjega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Spominjal se bom Gospodovih del. Zagotovo se bom spominjal tvojih čudežev od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Premišljeval bom tudi o vsem tvojem delu in govoril o tvojih dejanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Tvoja pot, oh Bog, je v svetišču. Kdo je tako velik Bog kakor naš Bog?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ti si Bog, ki dela čudeže. Med ljudstvom si oznanil svojo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'S svojim laktom si odkupil svoje ljudstvo, Jakobove in Jožefove sinove. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Vode so te videle, oh Bog, vode so te videle, bile so prestrašene. Tudi globine so bile vznemirjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Oblaki so izlivali vodo, nebo je pošiljalo zvok, tudi tvoje puščice so šle daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Zvok tvojega groma je bil na nebu, bliski so razsvetljevali zemeljski [krog], zemlja je trepetala in se tresla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Tvoja pot je na morju in tvoja steza v velikih vodah in tvoje stopinje niso znane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Svoje ljudstvo vodiš kakor trop z Mojzesovo in Aronovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Asáfov pouk. Pazljivo prisluhni, oh moje ljudstvo, k moji postavi, nagni svoja ušesa k besedam iz mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Svoja usta bom odprl v prispodobi, izrekel bom temne govore od davnine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'ki smo jih slišali in poznali in so nam jih naši očetje povedali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Ne bomo jih skrili pred njihovimi otroki, prikazujoč prihajajočemu rodu Gospodove hvalnice in njegovo moč ter njegova čudovita dela, ki jih je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Kajti osnoval je pričevanje v Jakobu in določil postavo v Izraelu, ki jo je zapovedal našim očetom, da bi jo lahko naredili znano svojim otrokom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'da bi jih prihajajoči rod lahko spoznal, celó otroci, ki naj bi bili rojeni, ki naj bi vstali in jih oznanili svojim otrokom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'da bi svoje upanje lahko usmerili v Boga in ne bi pozabili Božjih del, temveč bi se držali njegovih zapovedi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'in bi ne bili kakor njihovi očetje, trmoglav in uporen rod, rod, ki svojega srca ni pravilno postavil in čigar duh z Bogom ni bil neomajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efrájimovi otroci, ki so bili oboroženi in nosili loke, so se na dan bitke obrnili nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Niso ohranjali Božje zaveze in odklanjali so se ravnati po njegovi postavi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'in pozabili so njegova dela in njegove čudeže, ki jim jih je pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Čudovite stvari je storil v očeh njihovih očetov v egiptovski deželi, na polju Coana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Razdelil je morje, jih pripravil, da so prešli skozenj in storil je, da so vode stale kakor kup.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Tudi podnevi jih je vodil z oblakom in vso noč z ognjeno svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Razklal je skale v divjini in jim dal piti kakor iz velikih globin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Tudi vodne tokove je privedel iz skale in storil, da so vode tekle kakor reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'V divjini pa so še bolj grešili zoper njega z izzivanjem Najvišjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'V svojem srcu so skušali Boga z zahtevanjem jedi za svoje poželenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Da, govorili so zoper Boga; rekli so: »Ali Bog lahko oskrbi mizo v divjini?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Glej, udaril je skalo, da so pridrle vode in vodotoki so preplavili, ali lahko da tudi kruh? Ali za svoje ljudstvo lahko priskrbi meso?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Torej Gospod je to slišal in je bil ogorčen, tako je bil zoper Jakoba vžgan ogenj in tudi jeza je prišla zoper Izrael,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'ker niso verovali v Boga in niso zaupali v njegovo rešitev duš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'čeprav je zapovedal oblakom od zgoraj in odprl vrata nebes');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'in je nanje deževal mano za jed ter jim dajal od nebeškega žita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Človek je jedel hrano angelov. Poslal jim je mesa do sitosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Vzhodniku je velel, da zapiha na nebu in s svojo močjo je privedel južni veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Prav tako je nanje deževal meso kakor prah in operjeno perjad podobno kakor morski pesek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Dopustil jim je pasti v sredo njihovega tabora, okoli njihovih prebivališč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Tako so jedli in bili popolnoma nasičeni, kajti izročil jim je njihovo lastno željo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'niso bili odvrnjeni od svoje želje. Vendar ko je bila njihova jed še v njihovih ustih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, '§ je nadnje prišel Božji bes in pokončal najdebelejše izmed njih in z udarcem zrušil izbrane Izraelove ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Kajti vsi ti so še vedno grešili in niso verovali zaradi njegovih čudovitih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Zato je njihove dneve použil v ničevosti in njihova leta v muki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Ko jih je ubijal, potem so ga iskali in vrnili so se ter zgodaj poizvedovali za Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Spomnili so se, da je bil Bog njihova skala in vzvišeni Bog njihov odkupitelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Kljub temu so se mu prilizovali s svojimi usti in mu lagali s svojimi jeziki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Kajti njihovo srce ni bilo popolnoma z njim niti niso bili neomajni v njegovi zavezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Toda on, ki je poln sočutja, je odpustil njihovo krivičnost in jih ni uničil. Da, svojo jezo je pogosto obrnil proč in ni razvnel vsega svojega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Kajti spomnil se je, da so bili samo meso, veter, ki premine in ne prihaja ponovno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kako pogosto so ga dražili v divjini in ga žalostili v puščavi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, '§ Da, obrnili so se nazaj in skušali Boga in omejevali Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Niso se spomnili njegove roke niti dneva, ko jih je osvobodil pred sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Kako je v Egiptu izvršil svoja znamenja in svoje čudeže na polju Coana');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'in njihove reke spremenil v kri in njihove potoke, da niso mogli piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Mednje je poslal številne vrste muh, ki so jih požirale in žabe, ki so jih uničevale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Tudi njihov prirastek je dal gosenici in njihov trud leteči kobilici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Njihove trte je uničil s točo in njihove egiptovske smokve z zmrzaljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Tudi njihovo živino je predal toči in njihove trope vročim strelam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, '§ S pošiljanjem zlih angelov mednje je nanje vrgel okrutnost svoje jeze, bes, ogorčenost in stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Pripravil je pot svoji jezi, njihovi duši ni prizanesel pred smrtjo, temveč je njihovo življenje odstopil kužni bolezni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'in udaril vsakega prvorojenca v Egiptu, njihovo glavno moč v Hamovih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Toda svojemu lastnemu ljudstvu je storil, da gredo naprej kakor ovce in po divjini jih je usmerjal kakor trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Vodil jih je varno, tako da se niso bali, toda njihove sovražnike je preplavilo morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Privedel jih je do meje svojega svetišča, celo k tej gori, ki jo je pridobila njegova desnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Pred njimi je spodil tudi pogane in jim z mejno črto razdelil dediščino in Izraelovim rodovom storil, da prebivajo v svojih šotorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Kljub temu so skušali in dražili najvišjega Boga in se niso držali njegovih pričevanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'temveč so se obrnili nazaj in postopali nezvesto kakor njihovi očetje. Obrnjeni so bili na stran kakor varljiv lok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Kajti s svojimi visokimi mesti so ga dražili do jeze in s svojimi rezanimi podobami so ga pripravili do ljubosumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Ko je Bog to slišal, je bil ogorčen in silno preziral Izraela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'tako da je zapustil bivališče v Šilu, šotorsko svetišče, ki ga je postavil med ljudmi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'in svojo moč izročil v ujetništvo in svojo slavo v sovražnikovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Svoje ljudstvo je izročil meču in ogorčen je bil nad svojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ogenj je použil njihove mladeniče in njihove mladenke niso bile omožene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Njihovi duhovniki so padli pod mečem in njihove vdove niso pripravile objokovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Potem se je Gospod prebudil kakor iz spanja in kakor mogočen človek, ki vzklika zaradi vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Svoje sovražnike je udaril v njihove zadnje dele. Postavil jih je v neprestano grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Poleg tega je odklonil Jožefovo šotorsko svetišče in ni izbral Efrájimovega rodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'temveč je izbral Judov rod, goro Sion, ki jo je ljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Svoje svetišče je zgradil kakor visoke palače, kakor zemljo, ki jo je utrdil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Poleg tega je izbral svojega služabnika Davida in ga vzel od ovčjih staj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, '§ Od sledenja brejim ovcam z mladiči ga je privedel, da pase Jakoba, njegovo ljudstvo in Izraela, njegovo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Tako jih je hranil glede na neokrnjenost svojega srca in jih usmerjal s spretnostjo svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Asáfov psalm. Oh Bog, pogani so prišli v tvojo dediščino, omadeževali so tvoj sveti tempelj, Jeruzalem so razbili na kupe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Trupla tvojih služabnikov so izročili, da so hrana perjadi neba, meso tvojih svetih za zemeljske živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Njihovo kri so kakor vodo prelivali naokoli Jeruzalema, in nikogar ni bilo, da jih pokoplje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Postali smo graja našim sosedom, norčevanje in posmeh tem, ki so okoli nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Doklej, Gospod? Hočeš biti jezen na veke? Ali bo tvoja ljubosumnost gorela kakor ogenj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Svoj bes izlij nad pogane, ki te ne spoznavajo in nad kraljestva, ki ne kličejo tvojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Kajti požrli so Jakoba in opustošili njegovo prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'O ne spominjaj se zoper nas prejšnjih krivičnosti. Naj nas tvoja nežna usmiljenja naglo vodijo, kajti mi smo zelo ponižani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Pomagaj nam, oh Bog rešitve naše duše, zaradi slave svojega imena in osvobodi nas in naše grehe očisti proč zaradi svojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Zakaj bi pogani rekli: »Kje je njihov Bog?« Naj bo z maščevanjem krvi tvojih služabnikov, ki je prelita, on spoznan med pogani v našem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Naj pride predte jetnikovo vzdihovanje; glede na veličino svoje moči ohrani tiste, ki so določeni, da umro');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'in povrni našim sosedom njihovo grajo sedemkratno v njihovo naročje, s katero so te grajali, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Tako ti bomo mi, tvoje ljudstvo in ovce tvojega pašnika, dajali zahvalo na veke. Tvojo hvalo bomo naznanjali vsem rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Vodji glasbenikov na Lilijo pričevanja, Asáfov psalm. Pazljivo prisluhni, Pastir Izraela, ti, ki vodiš Jožefa kakor trop, ti, ki prebivaš med keruboma, zasij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Pred Efrájimom, Benjaminom in Manásejem razvnemi svojo moč ter pridi in nas reši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Ponovno nas spreobrni, oh Bog in svojemu obrazu povzroči, da zasije in mi bomo rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Oh Gospod, Bog nad bojevniki, doklej boš jezen proti molitvi svojega ljudstva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Hraniš jih s kruhom solza in jim daješ, da v veliki meri pijejo solze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Delaš nas prepir našim sosedom in naši sovražniki se smejijo med seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Ponovno nas spreobrni, oh Bog nad bojevniki in svojemu obrazu povzroči, da zasije in mi bomo rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Iz Egipta si privedel trto, spodil si pogane in jo zasadil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Pred njo si pripravil prostor in ji povzročil, da je napravila globoko korenino in napolnila zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Hribi so bili pokriti z njeno senco in njene veje so bile podobne čednim cedram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Njene veje je poslala v morje in njene mladike v reko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Zakaj si ti potem podrl njene ograje, tako da jo smukajo vsi, ki gredo mimo po poti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Merjasec iz gozda jo pustoši in poljska žival jo požira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Vrni se, rotimo te, oh Bog nad bojevniki, poglej dol z neba in glej in obišči to trto');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'in vinograd, ki ga je zasadila tvoja desnica in mladiko, ki si jo zaradi sebe naredil močno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Požgana je z ognjem, posekana je. Oni se pogubljajo ob graji tvojega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Naj bo tvoja roka nad človekom tvoje desnice, nad sinom človekovim, ki si ga storil močnega zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Tako od tebe ne bomo odšli nazaj. Oživi nas in mi bomo klicali tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Ponovno nas spreobrni, oh Gospod Bog nad bojevniki, svojemu obrazu povzroči, da zasije in mi bomo rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Vodji glasbenikov na Gitít, Asáfov psalm. Glasno prepevajte Bogu, naši môči, naredite radosten glas Jakobovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Vzemite psalm in prinesite sèm tamburin, prijetno harfo s plunko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Trobite na šofar ob mlaju, ob določenem času na naš slovesni praznični dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Kajti to je bil zakon za Izraela in postava Jakobovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'To je odredil v Jožefu za pričevanje, ko je šel ven skozi egiptovsko deželo, kjer sem slišal jezik, ki ga nisem razumel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '»Njegovo ramo sem odstranil od bremena, njegove roke so bile osvobojene pred lonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Ti kličeš v stiski in jaz sem te osvobodil, odgovoril sem ti na skrivnem kraju groma. Jaz sem te preizkusil pri vodah Meríbe. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Poslušaj, oh moje ljudstvo, pričeval ti bom, oh Izrael, če bi mi hotel prisluhniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'V tebi naj ne bo tujega boga niti ne boš oboževal nobenega tujega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Jaz sem Gospod, tvoj Bog, ki te je privedel iz egiptovske dežele. Široko odpri svoja usta in napolnil jih bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Toda moje ljudstvo noče prisluhniti mojemu glasu in Izrael noče ničesar od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Tako sem jih izročil njihovim lastnim srčnim željam in živeli so po svojih lastnih nasvetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Oh, da bi mi moje ljudstvo prisluhnilo in bi Izrael hodil po mojih poteh!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Kmalu bi podjarmil njihove sovražnike in svojo roko obrnil zoper njihove nasprotnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Gospodovi sovražniki bi se morali podvreči pod njega, pa bi se njihov čas ohranil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Hranil bi jih tudi z najodličnejšo pšenico in z medom iz skale bi te nasitil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Asáfov psalm. Bog stoji v skupnosti mogočnih, sodi med bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '»Doklej boste nepravično sodili in sprejemali zunanjost zlobnih? Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Branite revne in osirotele, ravnajte pravično prizadetim in pomoči potrebnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Osvobodite uboge in pomoči potrebne, odstranite jih iz roke zlobnih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ne vedo niti ne bodo razumeli, hodijo v temi. Vsi temelji zemlje so izven naravnega reda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Rekel sem: »Vi ste bogovi in vsi izmed vas ste otroci Najvišjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Vendar boste umrli kakor ljudje in padli kakor kdo izmed princev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Vstani, oh Bog, sodi zemljo, kajti ti boš podedoval vse narode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Pesem ali Asáfov psalm. Ne bodi tiho, oh Bog. Ne molči in ne bodi molčeč, oh Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Kajti glej, tvoji sovražniki pripravljajo upor in tisti, ki te sovražijo, so povzdignili glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Zoper tvoje ljudstvo so sprejeli prebrisan nasvet in se posvetovali zoper tvoje skrite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Rekli so: »Pridimo in odrežimo jih od tega, da so narod, da Izraelovo ime ne bo več v spominu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Kajti skupaj so se soglasno posvetovali, združeni so zoper tebe:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Edómova šotorska svetišča in Izmaelci; Moábovci in Hagárovci;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebál, Amón in Amálek; Filistejci s prebivalci Tira;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'pridružen jim je tudi Asúr. Pomagali so Lotovim sinovom. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Stôri jim kakor Midjáncem, kakor Siseráju, kakor Jabínu pri potoku Kišón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'ki so bili pokončani pri En Doru. Postali so kakor gnoj za zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Naredite njihove plemiče kakor Oréba in kakor Zeéba. Da, vse njihove prince kot Zebaha in kot Calmunája,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'ki so rekli: »Vzemimo si Božje hiše v posest.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Oh moj Bog, naredi jih kot pleve, kakor strnišče pred vetrom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Kakor ogenj požiga gozd in kakor plamen zažiga gore,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'tako jih preganjaj s svojim neurjem in s svojim viharjem jih naredi prestrašene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Njihove obraze napolni s sramoto, da bodo lahko iskali tvoje ime, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Naj bodo zasramovani in zbegani na veke; da, naj bodo osramočeni in [naj] se pogubijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, '§ da bodo ljudje lahko vedeli, da si ti, čigar ime samó je Jahve, najvišji nad vso zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Vodji glasbenikov na Gitít, psalm za Korahove sinove. Kako ljubka so tvoja šotorska svetišča, oh Gospod nad bojevniki!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Moja duša hrepeni, da, celó slabi zaradi Gospodovih dvorov. Moje srce in moje meso vpijeta za živim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Da, vrabec najde dom in lastovka gnezdo zase, kjer lahko položi svoje mladiče, celó tvoje oltarje, oh Gospod nad bojevniki, moj Kralj in moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Blagoslovljeni so tisti, ki prebivajo v tvoji hiši. Oni te bodo nenehno slavili. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Blagoslovljen je človek, čigar moč je v tebi, v čigar srcu so njihove poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Kateri hodijo skozi dolino Baka jo oblikujejo [v] studenec; tudi dež napolnjuje tolmune.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Hodijo iz moči v moč, vsak izmed njih se na Sionu prikaže pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Oh Gospod Bog nad bojevniki, usliši mojo molitev, pazljivo prisluhni, oh Bog Jakobov. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Glej, oh Bog, naš ščit in poglej na obraz svojega maziljenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Kajti en dan v tvojih dvorih je boljši kakor tisoč. Raje bi bil vratar v hiši svojega Boga, kakor da bi prebival v šotorih zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Kajti Gospod Bog je sonce in ščit. Gospod bo dal milost in slavo. Nobene dobre stvari ne bo zadržal pred tistimi, ki hodijo iskreno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Oh Gospod nad bojevniki, blagoslovljen je mož, ki zaupa vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Vodji glasbenikov, psalm za Korahove sinove. Gospod, naklonjen si bil svoji deželi, nazaj si privedel Jakobovo ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Odpustil si krivičnost svojega ljudstva, pokril si vse njihove grehe. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Odstranil si ves svoj bes. Sebe si odvrnil od okrutnosti svoje jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Spreobrni nas, oh Bog rešitve naše duše in svoji jezi do nas povzroči, da preneha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Hočeš biti večno jezen na nas? Hočeš svojo jezo raztegniti na vse rodove?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Ali nas ne boš ponovno oživil, da se tvoje ljudstvo lahko veseli v tebi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Pokaži nam svoje usmiljenje, oh Gospod in zagotovi nam svojo rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Slišal bom kaj bo Bog, Gospod, govoril, kajti svojemu ljudstvu in svojim svetim bo govoril mir, toda oni naj se ne obrnejo ponovno k neumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Zagotovo je njegova rešitev duš blizu tistim, ki se ga bojijo, da bo v naši deželi lahko prebivala slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Usmiljenje in resnica sta se skupaj srečala, pravičnost in mir sta poljubila drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Resnica bo izvirala iz zemlje in pravičnost bo gledala dol z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Da, Gospod bo dal to, kar je dobro in naša dežela bo obrodila svoj donos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Pravičnost bo hodila pred njim in nas postavila na pot njegovih korakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Davidova molitev. Nagni svoje uho, oh Gospod, prisluhni mi, ker sem ubog in pomoči potreben.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Varuj mojo dušo, ker sem svet. Oh ti moj Bog, reši svojega služabnika, ki zaupa vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Bodi mi usmiljen, oh Gospod, kajti vsak dan kličem k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Razveseli dušo svojega služabnika, kajti k tebi, oh Gospod, dvigujem svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Kajti ti, Gospod, si dober in pripravljen odpustiti in obilen v usmiljenju k vsem tem, ki kličejo k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Pazljivo prisluhni, oh Gospod, moji molitvi in pazi na glas mojih ponižnih prošenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Na dan svoje stiske bom klical k tebi, kajti ti mi boš odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Med bogovi ni nikogar podobnega tebi, oh Gospod; niti ni nobenih del, podobnih tvojim delom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Vsi narodi, ki si jih naredil, bodo prišli in oboževali pred teboj, oh Gospod in proslavili bodo tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Kajti ti si velik in delaš čudovite stvari. Samo ti si Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Úči me svojo pot, oh Gospod, hodil bom v tvoji resnici; zedini moje srce, da se bo balo tvojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Hvalil te bom, oh Gospod, moj Bog, z vsem svojim srcem in tvoje ime bom proslavljal na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, '§ Kajti veliko je tvoje usmiljenje do mene in mojo dušo si osvobodil pred najglobljim peklom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, '§ Oh Bog, ponosni so vstali zoper mene in zbori nasilnih ljudi so stregli po moji duši, niso pa tebe postavili pred sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Toda ti, oh Gospod, si Bog, poln sočutja in milostljiv, potrpežljiv in obilen v milosti in resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Oh obrni se k meni in se me usmili, daj svojo moč svojemu služabniku in reši sina svoje pomočnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Pokaži mi znamenje za dobro, da bodo tisti, ki me sovražijo, lahko to videli in bili osramočeni, ker si mi ti, Gospod, pomagal in me tolažil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Psalm ali pesem za Korahove sinove. Njegov temelj je na svetih gorah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Gospod bolj ljubi sionska velika vrata kakor vsa Jakobova prebivališča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Veličastne stvari se govorijo o tebi, oh Božje mesto. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Tistim, ki me poznajo, bom omenjal Rahab in Babilon; glej Filisteja in Tir z Etiopijo; ta človek je bil rojen tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'In o Sionu bo rečeno: »Ta in ta človek je bil rojen v njem in sam najvišji ga bo utrdil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Ko vpisuje ljudstvo, bo Gospod štel, da je bil ta človek rojen tam. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, '§ Prav tako bodo tam tako pevci kakor igralci na glasbila. Vsi moji izviri so v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Pesem ali psalm za Korahove sinove. Vodju glasbenikov na lutnjo za odgovor. Pouk Ezráhovca Hemána. Oh Gospod Bog, rešitev moje duše, pred teboj sem klical dan in noč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Naj moja molitev pride predte, svoje uho nagni k mojemu klicu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'kajti moja duša je polna stisk in moje življenje se bliža grobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Prištet sem s tistimi, ki gredo dol v jamo. Sem kakor človek, ki nima moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Svoboden med mrtvimi, kakor umorjeni, ki ležijo v grobu, ki se jih ne spominjaš več in so iztrebljeni iz tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Položil si me v najglobljo jamo, v temo, v globine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Tvoj bes trdno leži na meni in prizadel si me z vsemi svojimi valovi. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Mojega znanca si postavil daleč od mene, njim si me naredil [za] ogabnost; zaprt sem in ne morem priti ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Moje oko žaluje zaradi stiske; Gospod, vsak dan sem klical k tebi, svoje roke sem iztegoval k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Hočeš mrtvim pokazati čudeže? Mar bodo mrtvi vstali in te hvalili? Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Bo tvoja ljubeča skrbnost oznanjena v grobu? Ali tvoja zvestoba v propadu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Bodo tvoji čudeži spoznani v temi? In tvoja pravičnost v deželi pozabljivosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Toda jaz sem klical k tebi, oh Gospod in zjutraj te bo moja molitev prestregla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Gospod, zakaj zavračaš mojo dušo? Zakaj skrivaš svoj obraz pred menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Prizadet sem in od svoje mladosti pripravljen umreti; medtem ko trpim tvoje strahote, sem raztresen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Tvoj kruti bes gre prek mene, tvoje strahote so me uničile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Vsak dan so prišli okoli mene kakor voda, skupaj so me obkrožali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Ljubega in prijatelja si postavil daleč od mene in mojega znanca v temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Pouk Ezráhovca Etána. O Gospodovih milostih bom prepeval na veke, s svojimi usti bom vsem rodovom razglašal tvojo zvestobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Kajti rekel sem: »Usmiljenje bo zgrajeno na veke, svojo zvestobo boš utrdil v samih nebesih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'S svojim izbranim sem sklenil zavezo, prisegel sem Davidu, svojemu služabniku:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '»Tvoje seme bom utrdil na veke in tvoj prestol zgradil za vse rodove.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Nebesa bodo hvalila tvoje čudeže, oh Gospod, tudi tvojo zvestobo v skupnosti svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Kajti kdo na nebu bi bil lahko primerjan z Gospodom? Kdo izmed sinov mogočnega bi bil lahko podoben Gospodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Boga se je silno bati v zboru svetih in spoštujejo ga vsi tisti, ki so okoli njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Oh Gospod Bog nad bojevniki, kdo je močan Gospod, podoben tebi ali tvoji zvestobi naokoli tebe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ti vladaš besnenju morja; ko njegovi valovi vstanejo, jih ti umirjaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Zlomil si Rahaba na koščke, kakor nekoga, ki je umorjen, s svojim močnim laktom si razkropil svoje sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Nebo je tvoje, tudi zemlja je tvoja; kar se tiče zemeljskega [kroga] in njegove polnosti, si jih ti utemeljil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Sever in jug, ti si ju ustvaril; Tabor in Hermon se bosta veselila v tvojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Ti imaš mogočen laket, močna je tvoja roka in visoka je tvoja desnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Pravičnost in sodba sta prebivališče tvojega prestola, usmiljenje in resnica bosta šla pred tvojim obličjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Blagoslovljeno je ljudstvo, ki pozna radosten zvok. Hodili bodo, oh Gospod, v svetlobi tvojega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'V tvojem imenu se bodo veselili ves dan in v tvoji pravičnosti bodo povišani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Kajti ti si slava njihove moči in v tvoji naklonjenosti bo naš rog povišan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, '§ Kajti Gospod je naša obramba in Sveti Izraelov je naš kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Potem svojemu svetemu spregovoriš v videnju in rečeš: »Položil sem pomoč na nekoga, ki je mogočen, povišal sem enega izbranega izmed ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Našel sem Davida, svojega služabnika; s svojim svetim oljem sem ga mazilil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Z njim bo moja roka utrjena; tudi moj laket ga bo krepil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Sovražnik se ne bo maščeval nad njim niti ga sin zlobnosti [ne bo] prizadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Njegove sovražnike bom premagal pred njegovim obrazom in nadlegoval tiste, ki ga sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Toda z njim bosta moja zvestoba in moje usmiljenje in v mojem imenu bo povišan njegov rog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Njegovo roko bom postavil tudi na morje in njegovo desnico na reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Klical bo k meni: ›Ti si moj oče, moj Bog in skala rešitve moje duše.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Prav tako mu bom dal svojega prvorojenca, višje kakor kralje zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Svoje usmiljenje bom zanj ohranil na vékomaj in moja zaveza bo trdno stala z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Tudi njegovemu semenu bom storil, da ostane na veke in njegov prestol kakor nebeški dnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Če njegovi otroci zapustijo mojo postavo in ne hodijo po mojih sodbah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'če prelomijo moje zakone in se ne držijo mojih zapovedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'potem bom s palico obiskal njihov prestopek in njihovo krivičnost z bičanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Vendar pa svoje ljubeče skrbnosti ne bom popolnoma odvzel od njega niti svoji zvestobi [ne bom] pustil, da se izneveri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Svoje zaveze ne bom prelomil niti predrugačil stvari, ki je odšla iz mojih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Enkrat sem prisegel pri svoji svetosti, da Davidu ne bom lagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Njegovo seme bo ostalo na veke in njegov prestol kakor sonce pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Kakor luna bo utrjen na veke in kakor zvesta priča na nebu.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Toda ti si zavrgel in prezrl, ogorčen si bil s svojim maziljencem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Razveljavil si zavezo svojega služabnika. Njegovo krono si oskrunil in jo vrgel na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Porušil si vse njegove ograje; njegova oporišča si privedel do propada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Vsi mimoidoči ga plenijo. Graja je svojim sosedom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Dvignil si desnico njegovih nasprotnikov; vsem njegovim sovražnikom si storil, da se veselijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Obrnil si tudi ostrino njegovega meča in ga nisi naredil, da se zoperstavi v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Njegovi slavi si storil, da preneha in njegov prestol si vrgel na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Dneve njegove mladosti si skrajšal. Pokril si ga s sramoto. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Doklej, Gospod? Se hočeš skrivati na veke? Bo tvoj bes gorel kakor ogenj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Spomni se, kako kratek je moj čas. Zakaj si vse ljudi naredil zaman?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kateri človek je, kdor živi in ne bo videl smrti? Ali bo svojo dušo osvobodil pred roko groba? Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Gospod, kje so tvoje prejšnje ljubeče skrbnosti, katere v svoji resnici prisegaš Davidu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Spomni se, Gospod, graje svojih služabnikov; kako v svojih prsih nosim grajo vseh mogočnih ljudi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 's čimer so grajali tvoji sovražniki, oh Gospod, s čimer so grajali stopinje tvojega maziljenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Blagoslovljen bodi Gospod na vékomaj. Amen in Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Molitev Božjega moža Mojzesa. Gospod, ti si bil naše bivališče za vse rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Preden so bile rojene gore, oziroma kadarkoli si oblikoval zemljo in zemeljski [krog], celo od večnosti do večnosti, si ti Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Človeka obračaš k uničenju in praviš: »Vrnite se, vi človeški otroci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Kajti tisoč let v tvojem pogledu je samo kakor včerajšnji dan, ki je minil in kakor straža v noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Odnašaš jih proč kakor s poplavo; oni so kakor spanec. Zjutraj so podobni travi, ki raste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, '§ Zjutraj cveti in raste, zvečer je odrezana in ovene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Kajti použiti smo s tvojo jezo in s tvojim besom smo zbegani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Predse si postavil naše krivičnosti, naše skrite grehe v svetlobo svojega obličja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Kajti vsi naši dnevi so minili v tvojem besu. Svoja leta smo preživeli kakor zgodbo, ki je povedana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Dni naših let je sedemdeset let in če jih je zaradi razloga moči osemdeset let, je vendarle njihova moč trud in bridkost, kajti to je kmalu odrezano in mi odletimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kdo pozna moč tvoje jeze? Celó glede na tvoj strah, tak je tvoj bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Zaradi tega nas uči šteti naše dneve, da bomo svoja srca lahko posvetili modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Vrni se, oh Gospod, doklej? To naj te pokesa glede tvojih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Oh zgodaj nas nasiti s svojim usmiljenjem, da se bomo lahko veselili in bomo veseli vse naše dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Stôri nas vesele glede na dneve, v katerih si nas prizadel in leta, v katerih smo videli zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Naj se tvoje delo pokaže tvojim služabnikom in tvoja slava njihovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Nad nami pa naj bo lepota Gospoda, našega Boga. Utrdi delo naših rok nad nami; da, delo naših rok, utrdi ga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Kdor prebiva na skrivnem kraju Najvišjega, bo ostal pod senco Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Rekel bom o Gospodu: » On je moje zatočišče in moja trdnjava; moj Bog, vanj bom zaupal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Zagotovo te bo osvobodil pred ptičarjevo zanko in pred ogabno kužno boleznijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Pokril te bo s svojim perjem in pod njegovimi perutmi boš zaupal. Njegova resnica bo tvoj ščit in oklep.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Ne boš se bal zaradi strahote ponoči niti zaradi puščice, ki leti podnevi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'niti zaradi kužne bolezni, ki hodi v temi niti zaradi uničenja, ki pustoši opoldan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Tisoč jih bo padlo na tvoji strani in deset tisoč na tvoji desnici, toda tebi se to ne bo približalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Samo s svojimi očmi boš gledal in videl nagrado zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ker si naredil Gospoda, ki je moje zatočišče, celó Najvišjega, [za] svoje prebivališče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'te nobeno zlo ne zadene niti nobena nadloga ne bo prišla blizu tvojega prebivališča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Kajti svojim angelom bo zapovedal nad teboj, da te varujejo na vseh tvojih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Nosili te bodo na svojih rokah, da ne bi svojega stopala treščil ob kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Stopal boš na leva in gada; mladega leva in zmaja boš pomendral pod stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Ker je svojo ljubezen naravnal name, zato ga bom osvobodil. Postavil ga bom visoko, ker je spoznal moje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Klical bo k meni in odgovoril mu bom. Z njim bom v stiski, osvobodil ga bom in mu izkazal čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Zadovoljil ga bom z dolgim življenjem in mu pokazal svojo rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalm ali pesem za šabatni dan. Dobra stvar se je zahvaljevati Gospodu in prepevati hvalnice tvojemu imenu, oh Najvišji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'zjutraj naznanjati tvojo ljubečo skrbnost in tvojo zvestobo vsako noč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'na glasbilo desetih strun in na plunko, na harfo s slovesnim zvokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Kajti ti, Gospod, si me zaradi svojega delovanja naredil veselega; v delih tvojih rok bom slavil zmago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Oh Gospod, kako velika so tvoja dela! In tvoje misli so zelo globoke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Brutalnež ne spozna niti tega ne razume bedak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Ko zlobni poganja kakor trava in ko vsi delavci krivičnosti uspevajo, je to, da bodo uničeni na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Toda ti, Gospod, si najvišji na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Kajti glej, tvoji sovražniki, oh Gospod, kajti glej, tvoji sovražniki bodo izginili; vsi delavci krivičnosti bodo razkropljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Toda moj rog boš povišal kakor samorogov rog; maziljen bom s svežim oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Tudi moje oko bo videlo mojo željo na mojih sovražnikih in moja ušesa bodo slišala mojo željo glede zlobnih, ki vstajajo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Pravični bo uspeval kakor palmovo drevo, rasel bo kakor cedra na Libanonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Tisti, ki bodo vsajeni v Gospodovi hiši, bodo cveteli na Božjih dvorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Še v visoki starosti bodo prinašali sad; obilni bodo in uspešni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'da pokažejo, da je Gospod pošten. On je moja skala in nepravičnosti ni v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Gospod kraljuje, oblečen je z veličanstvom; Gospod je oblečen z močjo, s katero se je opasal. Tudi zemeljski [krog] je utrdil, da ne more biti omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Tvoj prestol je utrjen od davnine. Ti si od večnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Reke so se dvignile, oh Gospod, reke so povzdignile svoj glas, reke so dvignile svoje valove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Gospod na višavi je mogočnejši kakor glas mnogih vodá, da, kakor mogočni valovi morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tvoja pričevanja so zelo zanesljiva. Svetost se spodobi tvoji hiši, oh Gospod, na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Oh Gospod Bog, ki mu pripada maščevanje, oh Bog, ki mu pripada maščevanje, pokaži se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Dvigni se, ti sodnik zemlje; povrni nagrado ponosnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Gospod, doklej bodo zlobni, doklej bodo zlobni slavili zmago?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Kako dolgo bodo izgovarjali in govorili trde stvari in se bahali vsi delavci krivičnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Tvoje ljudstvo razbijajo na koščke, oh Gospod in prizadevajo tvojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Ubijajo vdovo in tujca in morijo osirotele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Vendar pravijo: » Gospod nas ne bo videl niti Bog Jakobov tega ne bo upošteval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Razumite, vi brutalni izmed ljudstva, in vi bedaki, kdaj boste modri?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Kdor je zasadil uho, da ne bi slišal? Kdor je oblikoval oko, da ne bi videl?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Kdor kaznuje pogane, da ne bi grajal? Kdor uči človeka spoznanja, da ne bi vedel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Gospod pozna človekove misli, da so le-te ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Blagoslovljen je človek, ki ga karaš, oh Gospod in ga učiš iz svoje postave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'da mu lahko daš počitek od dni nadloge, dokler ni izkopana jama za zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Kajti Gospod ne bo zavrgel svojega ljudstva niti ne bo zapustil svoje dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Toda sodba se bo vrnila k pravičnosti in vsi iskreni v srcu ji bodo sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kdo se bo zame dvignil zoper hudodelce? Ali kdo bo zame vstal zoper delavce krivičnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Če Gospod ne bi bil moja pomoč, bi moja duša skoraj prebivala v tišini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Ko sem rekel: »Moje stopalo zdrsuje, me je podpiralo tvoje usmiljenje, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'V množici mojih misli znotraj mene tvoje tolažbe razveseljujejo mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Mar bo prestol krivičnosti, ki z uzakonitvijo snuje vragolijo, imel družbo s teboj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Skupaj se zbirajo zoper dušo pravičnega in obsojajo nedolžno kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Toda Gospod je moja obramba in moj Bog je skala mojega zatočišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Nadnje bo privedel njihovo lastno krivičnost in odsekal jih bo v njihovi lastni zlobnosti; da, Gospod, naš Bog, jih bo odsekal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Oh pridite, zapojmo Gospodu. Naredimo radosten glas skali rešitve naše duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Pridimo pred njegovo prisotnost z zahvaljevanjem in s psalmi mu naredimo radosten zvok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Kajti Gospod je velik Bog in velik Kralj nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'V njegovi roki so globoki kraji zemlje; tudi moč hribov je njegova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Morje je njegovo in on ga je naredil in njegove roke so oblikovale kopno zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Oh pridite, naj obožujemo in se priklonimo; pokleknimo pred Gospodom, našim stvarnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Kajti on je naš Bog in mi smo ljudstvo njegovega pašnika in ovce njegove roke. Če boste danes zaslišali njegov glas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'ne zakrknite svojega srca kakor z izzivanjem in kakor na dan preizkušnje v divjini,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'ko so me vaši očetje skušali, me preizkušali in gledali moje delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Dolgih štirideset let sem s tem rodom skupaj žaloval in rekel: »To je ljudstvo, ki se moti v svojem srcu in niso spoznali mojih poti,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'ki sem jim v svojem besu prisegel, da ne bodo vstopili v moj počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Oh pojte Gospodu novo pesem, pojte Gospodu, vsa zemlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Prepevajte Gospodu, blagoslavljajte njegovo ime; iz dneva v dan naznanjajte njegovo rešitev duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Oznanjajte njegovo slavo med pogani, njegove čudeže med vsemi ljudstvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Kajti Gospod je velik in silno bodi hvaljen; njega se je treba bati nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Kajti vsi bogovi narodov so maliki, toda Gospod je naredil nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Čast in veličanstvo sta pred njim; moč in lepota sta v njegovem svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Dajajte Gospodu, oh sorodstva ljudstev, dajajte Gospodu slavo in moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Dajajte Gospodu slavo, primerno njegovemu imenu; prinesite daritev in pridite v njegove dvore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Oh obožujte Gospoda v lepoti svetosti. Trepetaj pred njim, vsa zemlja!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Govorite med pogani, da Gospod kraljuje. Tudi zemeljski [krog] bo utrjen, da ne bo omajan. Ljudstva bo sodil pravično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Naj se nebo veseli in naj bo zemlja vesela; naj morje buči in njegova polnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Naj bo polje radostno in vse, kar je tam. Potem se bodo vsa gozdna drevesa veselila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'pred Gospodom, kajti on prihaja, kajti on prihaja, da sodi zemljo. S pravičnostjo bo sodil zemeljski [krog] in ljudstva s svojo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Gospod kraljuje, naj se zemlja veseli, naj bo množica otokov vesela le-tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Oblaki in tema so okoli njega. Pravičnost in sodba sta prebivališče njegovega prestola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Ogenj gre pred njim in naokrog požiga njegove sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Njegovi bliski so razsvetlili zemeljski [krog]; zemlja je videla in trepetala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Hribi so se ob Gospodovi prisotnosti topili kakor vosek, ob prisotnosti Gospoda celotne zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Nebesa oznanjujejo njegovo pravičnost in vsa ljudstva vidijo njegovo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Zbegani so vsi tisti, ki služijo rezanim podobam, ki se bahajo z maliki; obožujte ga, vsi vi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion je slišal in je bil vesel in judovske hčere so se veselile zaradi tvojih sodb, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Kajti ti, Gospod, si dvignjen nad vso zemljo. Zelo si vzvišen nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vi, ki ljubite Gospoda, sovražite zlo. On varuje duše svojih svetih; osvobaja jih iz roke zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Svetloba je posejana za pravičnega in veselje za iskrenega v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Veselite se v Gospodu, vi pravični in zahvaljujte se pri spominjanju njegove svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalm. Oh zapojte Gospodu novo pesem, kajti storil je čudovite stvari. Njegova desnica in njegov sveti laket sta mu pridobila zmago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Gospod je razglasil svojo rešitev duš; svojo pravičnost je javno pokazal v očeh poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Spomnil se je svojega usmiljenja in svoje resnice do Izraelove hiše. Vsi konci zemlje so videli rešitev duš našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Naredite radosten glas Gospodu, vsa zemlja. Naredite glasen zvok in veselite se in pojte hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Prepevajte Gospodu s harfo; s harfo in glasom psalma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'S trobentami in zvokom kornéta naredite radosten glas pred Gospodom, Kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Naj buči morje in njegova polnost, zemeljski [krog] in tisti, ki prebivajo na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Naj reke ploskajo [z] rokami; hkrati naj bodo hribi radostni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'pred Gospodom, kajti on prihaja, da sodi zemljo. S pravičnostjo bo sodil zemeljski [krog] in ljudstva z nepristranskostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Gospod kraljuje; naj ljudstva trepetajo. On sedi med kerubi; naj bo zemlja omajana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Gospod je velik na Sionu; visoko je nad vsemi ljudstvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Naj hvalijo tvoje veliko in strašno ime, kajti sveto je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Kraljeva moč ljubi tudi sodbo. Ti utrjuješ nepristranskost, izvršuješ sodbo in pravičnost v Jakobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Povišujte Gospoda, našega Boga in obožujte pri njegovi pručki, kajti on je svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojzes in Aron med njegovimi duhovniki in Samuel med tistimi, ki kličejo njegovo ime; klicali so Gospoda in jim je odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Govoril jim je v oblačnem stebru; držali so se njegovih pričevanj in odredbe, ki jim jo je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Ti jim odgovarjaš, oh Gospod, naš Bog. Bil si jim Bog, ki odpušča, čeprav se maščuješ njihovim domiselnostim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Povišujte Gospoda, našega Boga in obožujte ga pri njegovi sveti gori, kajti Gospod, naš Bog, je svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psalm hvaljenja. Naredite radosten glas Gospodu, vse ve dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Služite Gospodu z veseljem. Pred njegovo prisotnost pridite s petjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, '§ Védite, da Gospod je Bog. On je tisti, ki nas je ustvaril in ne mi sami; mi smo njegovo ljudstvo in ovce njegovega pašnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Vstopite v njegova velika vrata z zahvaljevanjem in v njegove dvore s hvalo. Bodite mu hvaležni in blagoslavljate njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Kajti Gospod je dober, njegovo usmiljenje je večno in njegova resnica traja vsem rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Davidov psalm. Pel bom o usmiljenju in sodbi; tebi, oh Gospod, bom pel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Vêdel se bom modro na popolni poti. O kdaj boš prišel k meni? Znotraj svoje hiše bom hodil s popolnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Pred svoje oči ne bom postavil nobene zlobne stvari. Sovražim delo tistih, ki se odvračajo; to se me ne bo držalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Kljubovalno srce bo odšlo od mene; ne bom poznal zlobne osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Kdorkoli tajno obrekuje svojega bližnjega, tistega bom iztrebil. Tistega, ki ima vzvišen pogled in ponosno srce, ne bom trpel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Moje oči bodo na zvestih v deželi, da bodo lahko prebivali z menoj. Kdor hodi po popolni poti, ta mi bo služil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Kdor dela prevaro, ne bo prebival znotraj moje hiše. Kdor govori laži, se ne bo zadrževal v mojem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Vse zlobne v deželi bom zgodaj uničil, da bom lahko iz Gospodovega mesta iztrebil vse zlobne storilce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Molitev prizadetega, ko je premagan in svojo pritožbo izliva pred Gospodom. Usliši mojo molitev, oh Gospod in moje vpitje naj pride do tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Svojega obraza ne skrivaj pred menoj na dan, ko sem v stiski; nagni k meni svoje uho. Na dan, ko kličem, mi naglo odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Kajti moji dnevi so použiti kakor dim in moje kosti so sežgane kakor ognjišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Moje srce je prizadeto in ovenelo kakor trava, tako da pozabljam jesti svoj kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Zaradi glasu mojega stokanja se moje kosti lepijo na mojo kožo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Podoben sem pelikanu iz divjine; podoben sem sovi v puščavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Bedim in sem kakor vrabec sam na strehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Moji sovražniki me ves dan grajajo in tisti, ki so besni name, prisegajo zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Kajti pepel sem jedel kakor kruh in svojo pijačo sem mešal z jokom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'zaradi tvojega ogorčenja in tvojega besa, kajti vzdignil si me in me vrgel dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Moji dnevi so kakor senca, ki se zmanjšuje in izsušen sem kakor trava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Toda ti, oh Gospod, boš ostal na veke in tvoj spomin vsem rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Vstal boš in imel usmiljenje do Siona, kajti čas, da mu [izkažeš] naklonjenost, da, določeni čas je prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Kajti tvoji služabniki uživajo v njegovih kamnih in so naklonjeni njegovemu prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Tako se bodo pogani bali Gospodovega imena in vsi kralji zemlje tvoje slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Ko bo Gospod zgradil Sion, se bo prikazal v svoji slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Upošteval bo molitev revežev in ne bo preziral njihove molitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'To bo zapisano za prihajajoči rod; in ljudstvo, ki bo ustvarjeno, bo hvalilo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Kajti on je pogledal dol iz višine svojega svetišča, z nebes je Gospod pogledal zemljo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'da usliši stokanje jetnika, da osvobodi tiste, ki so določeni za smrt,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'da oznani Gospodovo ime na Sionu in njegovo hvalo v Jeruzalemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'ko se zberejo skupaj ljudstva in kraljestva, da služijo Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Oslabil je mojo moč na poti, skrajšal je moje dneve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Rekel sem: »Oh moj Bog, ne odstrani me v sredi mojih dni; tvoja leta so skozi vse rodove.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Od davnine si položil temelj zemlji in nebo je delo tvojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ta [dva] bosta izginila, toda ti boš ostal. Da, vsa se bosta postarala kakor obleka; zamenjal ju boš kakor suknjo in bosta zamenjani,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'toda ti si isti in tvoja leta ne bodo imela konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Otroci tvojih služabnikov bodo nadaljevali in njihovo seme bo utrjeno pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Davidov psalm. Blagoslavljaj Gospoda, oh moja duša, in vse, kar je znotraj mene, blagoslavljaj njegovo sveto ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Blagoslavljaj Gospoda, oh moja duša in ne pozabi vseh dejanj njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'ki odpušča vse tvoje krivičnosti, ki ozdravlja vse tvoje bolezni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'ki odkupuje tvoje življenje pred uničenjem, ki te krona z ljubečo skrbnostjo in nežnimi usmiljenji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'ki tvoja usta nasičuje z dobrimi stvarmi, tako da se tvoja mladost obnavlja kakor orlova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Gospod izvršuje pravičnost in sodbo za vse, ki so zatirani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Svoje poti je dal spoznati Mojzesu, svoja dela Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Gospod je usmiljen in milostljiv, počasen za jezo in obilen v usmiljenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ne bo se vedno pričkal niti svoje jeze ne bo držal na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Z nami ni ravnal po naših grehih niti nas ni nagrajeval glede na naše krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Kajti kakor je nebo visoko nad zemljo, tako veliko je njegovo usmiljenje do tistih, ki se ga bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Kolikor daleč je vzhod od zahoda, tako daleč odstranja naše prestopke od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Kakor se oče usmili svojih otrok, tako se Gospod usmili teh, ki se ga bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Kajti pozna naš sestav; spominja se, da smo prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Glede človeka, so njegovi dnevi kakor trava; kakor cvetica polja, tako cveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Kajti čeznjo gre veter in izgine in njen kraj je ne bo več poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Toda Gospodovo usmiljenje je od večnosti do večnosti na tistih, ki se ga bojijo in njegova pravičnost do otrok otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'tistim, ki se držijo njegove zaveze in tistim, ki se spominjajo njegovih zapovedi, da jih izpolnjujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Gospod je pripravil svoj prestol v nebesih in njegovo kraljestvo vlada nad vsemi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Blagoslavljajte Gospoda, vi njegovi angeli, ki se odlikujete v moči, ki izpolnjujete njegove zapovedi s poslušanjem glasu njegove besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Blagoslavljajte Gospoda, vse ve njegove vojske, vi njegovi služabniki, ki izpolnjujete njegovo željo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Blagoslavljajte Gospoda, vsa njegova dela na vseh krajih njegovega gospostva. Blagoslavljaj Gospoda, oh moja duša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Blagoslavljaj Gospoda, oh moja duša. Oh Gospod, moj Bog, ti si tako velik, oblečen si s častjo in veličanstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Ki se pokrivaš s svetlobo kakor z obleko, ki razteguješ nebo kakor zaveso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Ki polagaš bruna svojih sob v vodah, ki delaš oblake [za] svoj bojni voz, ki hodiš na perutih vetra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, '§ Ki svoje angele delaš za duhove, svoje služabnike za goreč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Ki polagaš temelje zemlji, da na veke ne bo odstranjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Pokrivaš jo z globinami kakor z obleko; vode stojijo nad gorami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Ob tvojem oštevanju so zbežale, ob glasu tvojega groma so odhitele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, '§ Gredo gor po gorah, gredo dol po dolinah, na kraj, ki si ga ti osnoval zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Postavil si mejo, da je ne morejo prečkati, da se ponovno ne obrnejo in ne pokrijejo zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'On izvire pošilja v doline, ki tečejo med hribi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Dajejo piti vsaki poljski živali, divji osli si gasijo žejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Poleg njih bo perjad neba, ki žvrgoli med mladikami, imela svoje prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Iz svojih sob namaka hribe; zemlja je nasičena s sadom tvojih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Travi povzroča, da raste za živino in zelišče za služenje človeku, da lahko obrodi hrano iz zemlje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'in vino, da razveseljuje človekovo srce in olje, da njegovemu obrazu stori, da zasveti in kruh, ki utrjuje človekovo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Gospodova drevesa so polna soka, libanonske cedre, ki jih je posadil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'kjer si ptice pletejo svoja gnezda; glede štorklje, so ciprese njena hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Visoki hribi so zatočišče za divje koze in skale za kunce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Luno je določil za obdobja, sonce pozna svoje zahajanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Delaš temo in je noč, ko vse gozdne živali lazijo naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Mladi levi rjovejo za svojim plenom in iščejo svojo hrano od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Sonce vzhaja, zberejo se skupaj in se zleknejo v svoje brloge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Človek hodi naprej k svojemu delu in k svojemu trudu do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Oh Gospod, kako mnogotera so tvoja dela! V modrosti si jih vsa naredil; zemlja je polna tvojih bogastev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Tako je to veliko in široko morje, v katerem so brezštevilne plazeče stvari, tako majhne kakor velike živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Tam se vozijo ladje, tam je ta leviatán, ki si ga naredil, da se igra v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Vsi ti čakajo nate, da jim lahko daš njihovo hrano v pravšnjem obdobju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'To jim daješ, pobirajo; odpiraš svojo roko, nasičujejo se z dobrim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Skrivaš svoj obraz, preplašijo se; jemlješ njihov dih, poginejo in se vrnejo k svojemu prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Svojega duha pošiljaš naprej, ustvarjeni so; in obnavljaš obličje zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Gospodova slava bo vztrajala na veke. Gospod se bo veselil v svojih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Gleda na zemljo in ta se trese; dotika se hribov in se kadijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Dokler živim, bom prepeval Gospodu; dokler imam svoj obstoj, bom prepeval hvalo svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Moje premišljevanje o njem bo prijetno; veselil se bom v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Naj bodo grešniki použiti z zemlje in naj zlobnega ne bo več. Blagoslavljaj Gospoda, oh moja duša. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Oh zahvaljujte se Gospodu, kličite njegovo ime; med ljudstvom razglašajte njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Prepevajte mu, prepevajte mu psalme, govorite o vseh njegovih čudovitih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Ponašajte se z njegovim svetim imenom; naj se razveseljuje srce tistih, ki iščejo Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Iščite Gospoda in njegovo moč; vselej iščite njegov obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Spominjajte se njegovih čudovitih del, ki jih je storil, njegovih čudežev in sodb njegovih ust,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'oh, vi seme Abrahama, njegovega služabnika, vi otroci Jakoba, njegovega izbranca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'On je Gospod, naš Bog; njegove sodbe so po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Na veke se spominja svoje zaveze, besede, ki jo je zapovedal tisočêrim rodovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Katero zavezo je sklenil z Abrahamom in svojo prisego Izaku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'in isto potrdil Jakobu za zakon in Izraelu za večno zavezo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'rekoč: »Tebi bom dal kánaansko deželo, žreb vaše dediščine,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'ko jih je bilo po številu le malo ljudi, da, zelo malo in tujci v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Ko so hodili od enega naroda k drugemu, od enega kraljestva k drugemu ljudstvu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'nobenemu človeku ni pustil, da jim stori krivico; da, zaradi njih je grajal kralje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'rekoč: »Ne dotikajte se mojih maziljencev in mojim prerokom ne delajte hudega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Poleg tega je nad deželo poklical lakoto; zlomil je celotno oporo kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Pred njimi je poslal človeka, celó Jožefa, ki je bil prodan za služabnika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'katerega stopala so poškodovali z okovi, položen je bil v železo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'do časa, ko je prišla njegova beseda; Gospodova beseda ga je prečistila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Kralj je poslal in ga izpustil, celó vladar ljudstva in ga osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Postavil ga je [za] gospodarja svoje hiše in vladarja vsega svojega imetja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'da po svoji mili volji zveže njegove prince in njegove senatorje uči modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Tudi Izrael je prišel v Egipt in Jakob je začasno prebival v Hamovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Silno je pomnožil svoje ljudstvo in jih naredil močnejše kakor njihove sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Njihovo srce je obrnil, da sovraži njegovo ljudstvo, da premeteno postopa z njegovimi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Poslal je svojega služabnika Mojzesa in Arona, ki ga je izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Prikazovala sta njegova znamenja med njimi in čudeže v Hamovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, '§ Poslal je temo in jo naredil temačno in nista se uprla zoper njegovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Njihove vode je spremenil v kri in njihove ribe usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Njihova dežela je po sobah njihovih kraljev porodila žab v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Rekel je in prišle so različne vrste muh in uši po vseh njihovih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Dal jim je točo za dež in ognjen ogenj po njihovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Udaril je tudi njihove trte in njihova figova drevesa in zlomil drevesa njihovih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Spregovoril je in prišle so leteče kobilice in gosenice in to brez števila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'pojedle so vsa njihova zelišča po celotni deželi in požrle sad njihovih tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Udaril je tudi vse prvorojence v njihovi deželi, vodilne izmed vse njihove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Izpeljal jih je tudi s srebrom in zlatom, in med njihovimi rodovi ni bilo niti ene slabotne osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egipt je bil vesel, ko so odšli, kajti strah pred njimi je padel nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Razprostrl je oblak za pokrivalo in ogenj, da daje svetlobo v noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Ljudje so prosili in privedel je prepelice ter jih nasičeval z nebeškim kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Odprl je skalo in pridrle so vode, po suhih krajih so tekle kakor reka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Kajti spomnil se je svoje svete obljube in Abrahama, svojega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Svoje ljudstvo je izpeljal z radostjo in svoje izvoljene z veseljem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'in jim dal dežele poganov in podedovali so trud ljudstev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'da bi se lahko držali njegovih zakonov in obeleževali njegove postave. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Hvalite Gospoda. O zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kdo lahko izreče mogočna Gospodova dela? Kdo lahko naznanja vso njegovo hvalo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Blagoslovljeni so tisti, ki se držijo sodbe in tisti, ki ob vseh časih ravna pravično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Spomni se me, oh Gospod, z naklonjenostjo, ki jo prinašaš svojemu ljudstvu. Oh obišči me s svojo rešitvijo duše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'da lahko vidim dobro tvojega izbranca, da se lahko veselim v veselju tvojega naroda, da se lahko ponašam s tvojo dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Grešili smo s svojimi očeti, zagrešili smo krivičnost, ravnali smo zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Naši očetje v Egiptu niso razumeli tvojih čudežev, niso se spominjali množice tvojih milosti, temveč so ga dražili pri morju, celó pri Rdečem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Pa vendar jih je rešil zaradi svojega imena, da je lahko storil, da se spozna njegova mogočna moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Oštel je tudi Rdeče morje in le-to se je posušilo, tako jih je vodil skozi globine kakor skozi divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Rešil jih je iz roke tistega, ki jih je sovražil in jih odkupil iz sovražnikove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Vode so pokrile njihove sovražnike; niti eden izmed njih ni preostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Potem so verjeli njegovim besedam; peli so njegovo hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Kmalu so pozabili njegova dela, niso čakali na njegov nasvet,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'temveč so silno hrepeneli v divjini in skušali Boga v puščavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, '§ Dal jim je njihovo zahtevo, toda poslal je pustost v njihove duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Zavidali so tudi Mojzesu v taboru in Aronu, Gospodovemu svetemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Zemlja se je odprla in požrla Datána in pokrila Abirámovo druščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'V njuni druščini pa je bil vžgan ogenj, plamen je požgal zlobne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Naredili so tele na Horebu in oboževali ulito podobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Tako so svojo slavo zamenjali v podobnost vola, ki jé travo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Pozabili so Boga, svojega rešitelja, ki je v Egiptu storil velike stvari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'čudovita dela v Hamovi deželi in strašne stvari pri Rdečem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Zato je rekel, da jih bo uničil, če ne bi njegov izbranec Mojzes stal pred njim v vrzeli, da odvrne njegov bes, da jih ne bi uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Da, prezirali so prijetno deželo, niso verovali njegovi besedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'temveč so godrnjali v svojih šotorih in niso prisluhnili Gospodovemu glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Zato je dvignil svojo roko zoper njih, da jih zruši v divjini,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'da uniči njihovo seme tudi med narodi in da jih razkropi po deželah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Pridružili so se tudi k Báal Peórju in jedli žrtvovanje mrtvim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Tako so ga s svojimi domiselnostmi dražili do jeze, in mednje je vdrla nadloga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Potem se je dvignil Pinhás in izvršil sodbo in tako se je nadloga zaustavila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'To mu je bilo šteto v pravičnost, vsem rodovom na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Jezili so ga tudi pri vodah prepira, tako da se je zaradi njih za Mojzesa slabo izteklo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'ker so dražili njegovega duha, tako da je s svojimi ustnicami nepremišljeno govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Niso pokončali narodov, glede katerih jim je Gospod zapovedal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'temveč so bili pomešani med pogane in se naučili njihovih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Služili so svojim malikom, ki so bili zanje past.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Da, svoje sinove in svoje hčere so žrtvovali hudičem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'in prelivali nedolžno kri, celó kri svojih sinov in svojih hčera, ki so jih žrtvovali kánaanskim malikom, in dežela je bila oskrunjena s krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Tako so bili omadeževani s svojimi lastnimi deli in se šli vlačuganje s svojo lastno domiselnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Zato je bil zoper njegovo ljudstvo vžgan Gospodov bes, do take mere, da je preziral svojo lastno dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Izročil jih je v roko poganov in tisti, ki so jih sovražili, so vladali nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Tudi njihovi sovražniki so jih zatirali in privedeni so bili v podjarmljenje, pod njihovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Mnogokrat jih je osvobodil, toda dražili so ga s svojo namero in bili so ponižani zaradi svoje krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Vendar ko je slišal njihovo vpitje, se je ozrl na njihovo stisko');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'in zanje se je spomnil svoje zaveze in se pokesal glede na množico svojih usmiljenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Pripravil jim je tudi usmiljenje pred vsemi tistimi, ki so jih odvedli ujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Reši nas, oh Gospod, naš Bog in zberi nas izmed poganov, da se zahvaljujemo tvojemu svetemu imenu in da zmagujemo v tvojem hvaljenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Blagoslovljen bodi Gospod, Izraelov Bog, od večnosti do večnosti in vse ljudstvo naj reče: »Amen. Hvalite Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Oh zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Tako naj govorijo Gospodovi odkupljenci, ki jih je odkupil iz sovražnikove roke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'in jih zbral iz dežel, od vzhoda in od zahoda, od severa in od juga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Tavali so po divjini, po osamljeni poti; nobenega mesta niso našli, da prebivajo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Lačni in žejni, njihova duša je oslabela v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Potem so v svoji stiski klicali h Gospodu in jih je osvobodil iz njihovih tegob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Vodil jih je naprej po pravi poti, da lahko gredo v mesto prebivanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Oh, da bi ljudje hvalili Gospoda zaradi njegove dobrote in zaradi njegovih čudovitih del človeškim otrokom!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Kajti on nasičuje hrepenečo dušo in lačno dušo napolnjuje z dobroto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Tem, ki so sedeli v temi in smrtni senci in bili zvezani v stiski in železu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'ker so se uprli zoper Božjo besedo in zaničevali namero Najvišjega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'je zato njihovo srce ponižal s trudom; padli so dol in nikogar ni bilo, da pomaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Potem so v svoji stiski klicali h Gospodu in rešil jih je iz njihovih tegob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Privedel jih je iz teme in smrtne sence in pretrgal njihove vezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Oh, da bi ljudje hvalili Gospoda zaradi njegove dobrote in zaradi njegovih čudovitih del človeškim otrokom!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Kajti zlomil je velika vrata iz brona in presekal železne zapahe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Bedaki, zaradi svojega prestopka in zaradi svojih krivičnosti so prizadeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Njihova duša prezira vse vrste hrane in približujejo se velikim vratom smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Potem v svoji stiski kličejo h Gospodu in on jih rešuje iz njihovih tegob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Poslal je svojo besedo, jih ozdravil in jih osvobodil pred njihovimi uničenji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Oh, da bi ljudje hvalili Gospoda za njegovo dobroto in za njegova čudovita dela človeškim otrokom!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Naj žrtvujejo klavne daritve zahvaljevanja in z veseljem oznanjajo njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Tisti, ki gredo dol k morju na ladjah, da trgujejo po velikih vodah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'tisti vidijo Gospodova dela in njegove čudeže v globini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Kajti on ukazuje in vzdiguje viharni veter, ki dviguje valove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Le-ti se vzpenjajo k nebu, ponovno gredo dol h globinam. Njihova duša je zmehčana zaradi stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Opotekajo se sem ter tja in omahujejo kakor pijan človek in ne vedo več kaj storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Potem v svoji stiski kličejo h Gospodu in jih izpeljuje iz njihovih tegob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Vihar spreminja v tišino, tako da so njegovi valovi mirni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Potem so veseli, ker so mirni; tako jih privede v njihovo želeno pristanišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Oh, da bi ljudje hvalili Gospoda za njegovo dobroto in za njegova čudovita dela človeškim otrokom!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Naj ga povišujejo tudi v skupnosti ljudstva in ga hvalijo v zboru starešin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Reke spreminja v divjino in vodne izvire v suha tla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'rodovitno deželo v jalovost zaradi zlobnosti tistih, ki prebivajo v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Divjino spreminja v stoječo vodo in suha tla v vodne izvire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Tam daje lačnim, da prebivajo, da lahko postavijo mesto za prebivališče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'posejejo polja in zasadijo vinograde, ki lahko obrodijo sadove rasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Tudi blagoslavlja jih, tako da so silno pomnoženi in ne prenaša, [da] se njihova živina zmanjšuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Ponovno, pomanjšani so in ponižani zaradi zatiranja, stiske in bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Zaničevanje izliva na prince in jim povzroča, da se klatijo po divjini, kjer ni poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Vendar ubogega postavlja na visoko pred stisko in mu pripravlja družine kakor trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Pravični bo to videl in se veselil; vsa krivičnost pa bo ustavila svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kdorkoli je moder in bo obeleževal te stvari, celó oni bodo razumeli Gospodovo ljubečo skrbnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Pesem ali Davidov psalm. Oh Bog, moje srce je trdno; prepeval bom in dajal hvalo, celó s svojo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, '§ Zbudita se, plunka in harfa; jaz sam se bom zgodaj prebudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Hvalil te bom, oh Gospod, med ljudstvi in prepeval ti bom hvale med narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Kajti tvoje usmiljenje je veliko nad nebom in tvoja resnica sega do oblakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Bodi povišan, oh Bog, nad nebo in tvoja slava nad vso zemljo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'da so tvoji ljubljeni lahko osvobojeni; reši s svojo desnico in mi odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Bog je spregovoril v svoji svetosti: »Veselil se bom in razdelil bom Sihem in odmeril Sukótsko dolino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gileád je moj, Manáse je moj, tudi Efrájim je moč moje glave, Juda je moj postavodajalec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moáb je moj lonec za pranje, nad Edóm bom vrgel svoj čevelj, nad Filistejo bom slavil zmago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kdo me bo privedel v utrjeno mesto? Kdo me bo vodil v Edóm?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Mar ne boš ti, oh Bog, ki si nas zavrgel? Ali ne boš ti, oh Bog, šel naprej z našimi vojskami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Daj nam pomoč iz stiske, kajti zaman je človeška pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Z Bogom bomo delali hrabro, kajti on je ta, ki bo pomendral naše sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Vodji glasbenikov. Davidov psalm. Ne molči, oh Bog moje hvale,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'kajti usta zlobnih in usta varljivcev so odprta proti meni; zoper mene so govorili z lažnivim jezikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Obkrožili so me tudi z besedami sovraštva in brez razloga so se borili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Zaradi moje ljubezni so moji nasprotniki, toda sebe izročam molitvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Nagradili so me [z] zlom za dobro in sovražijo me zaradi moje ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, '§ Nad njim postavi zlobnega človeka in naj Satan stoji na njegovi desnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Ko bo sojen, naj bo obsojen in njegova molitev naj postane greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Njegovih dni naj bo malo; in drug naj prevzame njegovo službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Naj bodo njegovi otroci brez očeta in njegova žena vdova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Naj bodo njegovi otroci nenehno potepuhi in [naj] beračijo. Svoj kruh naj iščejo tudi izven svojih zapuščenih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Naj izsiljevalec zgrabi vse, kar ima in tujci naj oplenijo njegov trud.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Naj ne bo nikogar, da mu nakloni usmiljenje; niti naj ne bo nikogar, da podpre njegove osirotele otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Njegovo potomstvo naj bo iztrebljeno, in v naslednjem rodu naj bo njihovo ime izbrisano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Naj krivičnost njegovih očetov ne bo pozabljena pri Gospodu in greh njegove matere naj ne bo izbrisan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Naj bodo nenehno pred Gospodom, da bi spomin nanje lahko odrezal z zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Zato ker se ni spomnil, da pokaže usmiljenje, temveč je preganjal ubogega in pomoči potrebnega moža, da mogoče celó ubije potrtega v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Kakor je ljubil prekletstvo, tako naj le-to pride nadenj. Kakor se ni razveseljeval v blagoslavljanju, tako naj bo le-to daleč od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Kakor se je oblačil s prekletstvom, podobno kakor s svojo obleko, tako naj le-to pride v njegovo notranjost kakor voda in kakor olje v njegove kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Naj bo to kakor obleka, ki ga pokriva in namesto pasu, s katerim je nenehno opasan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Naj bo to nagrada mojim nasprotnikom od Gospoda in tistim, ki govorijo zlo zoper mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Toda ti delaj zame, oh Bog, Gospod, zaradi svojega imena; osvobodi me, ker je tvoje usmiljenje dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Kajti jaz sem ubog in pomoči potreben in moje srce je ranjeno znotraj mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Odhajal sem kakor senca, ko se ta zmanjšuje; kakor leteča kobilica sem premetavan sem ter tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Moja kolena so šibka zaradi posta in mojemu mesu manjka mastnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Postal sem jim tudi graja; ko so pogledali name, so stresali svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Pomagaj mi, oh Gospod, moj Bog, oh reši me glede na svoje usmiljenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'da bodo lahko vedeli, da je to tvoja roka, da si ti, Gospod, to storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Naj preklinjajo, toda ti blagoslavljaj. Ko vstanejo, naj bodo osramočeni, toda tvoj služabnik naj se veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Naj bodo moji nasprotniki oblečeni s sramoto in naj se kakor z ogrinjalom pokrijejo s svojo lastno zmedenostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'S svojimi usti bom silno hvalil Gospoda; da, hvalil ga bom med množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Kajti stal bo ob desnici ubogega, da ga reši pred tistimi, ki obsojajo njegovo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Davidov psalm. Gospod je rekel mojemu Gospodu: »Sédi na mojo desnico, dokler ne naredim tvojih sovražnikov [za] tvojo pručko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Gospod bo s Siona poslal palico tvoje moči; vladaj v sredi svojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Tvoje ljudstvo bo voljno na dan tvoje moči, v krasotah svetosti od maternice jutra; ti imaš roso svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Gospod je prisegel in se ne bo kesal: »Ti si duhovnik na veke po Melkízedekovem redu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Gospod na tvoji desnici bo na dan svojega besa udaril čez kralje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Sodil bo med pogani, kraje bo napolnil s trupli, ranil bo glave nad mnogimi deželami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Na poti bo pil iz potoka, zato bo dvignil glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Hvalíte Gospoda. Hvalil bom Gospoda z vsem svojim celotnim srcem, v zboru poštenih in v skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Gospodova dela so velika, preiskovana od vseh tistih, ki imajo veselje v tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Njegovo delo je častitljivo in veličastno, in njegova pravičnost traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Storil je svoja čudovita dela, da se ne pozabijo. Gospod je milostljiv in poln sočutja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Dal je hrano tistim, ki se ga bojijo; vedno se bo zavedal svoje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Svojemu ljudstvu je pokazal moč svojih del, da jim lahko da dediščino poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Dela njegovih rok so resnica in sodba; vse njegove zapovedi so zanesljive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Trdno stojijo na veke vekov, narejene so v resnici in poštenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Svojemu ljudstvu je poslal odkupitev, na veke je zapovedal svojo zavezo. Sveto in spoštovano je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Strah Gospodov je začetek modrosti. Dobro razumevanje imajo vsi tisti, ki izpolnjujejo njegove zapovedi. Njegova hvala traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Hvalite Gospoda. Blagoslovljen je človek, ki se boji Gospoda, ki se silno razveseljuje v njegovih zapovedih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Njegovo seme na zemlji bo mogočno; rod iskrenih bo blagoslovljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Premoženje in bogastva bodo v njegovi hiši in njegova pravičnost traja za vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Iskrenemu v temi vstaja svetloba; milostljiv je, poln sočutja in pravičen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dober človek kaže naklonjenost in posoja; svoje zadeve bo usmerjal s preudarnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Zagotovo ne bo omajan na veke, pravični bo v večnem spominu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Ne bo se bal zlih sporočil; njegovo srce je trdno, zaupa v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Njegovo srce je utrjeno, ne bo se bal, dokler ne opazi svoje želje na svojih sovražnikih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Razdelil je, dal je ubogim; njegova pravičnost traja za vedno; njegov rog bo povišan s častjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Zlobni bo to videl in bo užaloščen, škripal bo s svojimi zobmi in pešal. Želja zlobnega bo izginila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Hvalite Gospoda. Hvalite, oh vi Gospodovi služabniki, hvalite Gospodovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Blagoslovljeno bodi Gospodovo ime od tega časa dalje in na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od sončnega vzhoda do zahajanja istega naj se hvali Gospodovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Gospod je visoko nad vsemi narodi in njegova slava nad nebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kdo je podoben Gospodu, našemu Bogu, ki prebiva na višavi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'ki sebe ponižuje, da gleda stvari, ki so na nebu in na zemlji!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Iz prahu dviguje ubogega in iz gnojišča vzdiguje pomoči potrebnega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'da ga lahko postavi s princi, celó s princi svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Jalovi ženski daje, da varuje hišo in da je radostna mati otrok. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Ko je Izrael odšel iz Egipta, hiša Jakobova od ljudi tujega jezika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'je bil Juda njegovo svetišče in Izrael njegovo gospostvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Morje je to videlo in pobegnilo; Jordan je bil gnan nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Gore so poskakovale kakor ovni in majhni hribi kakor jagnjeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Kaj ti je bilo, oh ti morje, da bežiš? Ti Jordan, da si bil gnan nazaj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Ve gore, da ste poskakovale kakor ovni in vi majhni hribi kakor jagnjeta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Trepetaj, ti zemlja, ob Gospodovi prisotnosti, ob prisotnosti Jakobovega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'ki je skalo spremenil v stoječo vodo, kremen v studenec vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne nam, oh Gospod, ne nam, temveč daj slavo svojemu imenu zaradi svojega usmiljenja in zaradi svoje resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Zakaj bi pogani govorili: »Kje je sedaj njihov Bog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Toda naš Bog je v nebesih; storil je, karkoli mu ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Njihovi maliki so srebro in zlato, delo človeških rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Imajo usta, toda ne govorijo; imajo oči, toda ne vidijo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'imajo ušesa, toda ne slišijo; imajo nosove, toda ne duhajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'imajo roke, toda ne prijemajo; imajo stopala, toda ne hodijo niti ne govorijo skozi svoje grlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Tisti, ki jih delajo, so jim podobni, tako je vsak, kdor zaupa vanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Oh Izrael, zaupaj v Gospoda; on je njihova pomoč in njihov ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Oh hiša Aronova, zaupaj v Gospoda; on je njihova pomoč in njihov ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vi, ki se bojite Gospoda, zaupajte v Gospoda; on je njihova pomoč in njihov ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Gospod se nas zaveda; on nas bo blagoslovil, blagoslovil bo Izraelovo hišo, blagoslovil bo Aronovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Blagoslovil bo tiste, ki se bojijo Gospoda, tako male kakor velike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Gospod vas bo bolj in bolj povečeval, vas in vaše otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Vi ste blagoslovljeni od Gospoda, ki je naredil nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Nebesa, celó nebesa so Gospodova, toda zemljo je dal človeškim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Mrtvi ne hvalijo Gospoda niti kdorkoli, ki gre dol v tišino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Toda mi bomo blagoslavljali Gospoda od tega časa dalje in na vékomaj. Hvalíte Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Ljubim Gospoda, ker je slišal moj glas in moje ponižne prošnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Ker je k meni nagnil svoje uho, zato bom klical k njemu, dokler živim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Obdale so me bridkosti smrti in bolečine pekla so me prijele; spoznal sem stisko in bridkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Potem sem klical h Gospodovemu imenu: »Oh Gospod, rotim te, osvobodi mojo dušo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Milostljiv je Gospod in pravičen; da, naš Bog je usmiljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Gospod varuje preprostega; ponižan sem bil in pomagal mi je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Vrni se k svojemu počitku, oh moja duša, kajti Gospod radodarno postopa s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Kajti mojo dušo si osvobodil pred smrtjo, moje oči pred solzami in moja stopala pred padcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Hodil bom pred Gospodom v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Verujem, zato sem rekel: »Bil sem silno prizadet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'V svoji naglici sem rekel: »Vsi ljudje so lažnivci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kaj naj bi vrnil Gospodu za vse njegove koristi do mene?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Vzel bom čašo rešitve duše in klical h Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Svoje zaobljube bom izpolnil Gospodu sedaj, v prisotnosti vsega njegovega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Dragocena je v Gospodovih očeh smrt njegovih svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Oh Gospod, zares sem tvoj služabnik; tvoj služabnik sem in sin tvoje pomočnice; ti si odvezal moje vezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Daroval ti bom žrtev zahvaljevanja in klical bom h Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Svoje zaobljube bom izpolnil Gospodu sedaj, v prisotnosti vsega njegovega ljudstva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'na dvorih Gospodove hiše, v tvoji sredi, oh Jeruzalem. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Oh hvalite Gospoda, vsi vi narodi, hvalite ga, vsa ve ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Kajti velika je njegova usmiljena prijaznost do nas in Gospodova resnica traja večno. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Oh zahvaljujte se Gospodu, ker je dober, ker njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Naj sedaj reče Izrael, da njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Naj sedaj reče Aronova hiša, da njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Naj sedaj rečejo tisti, ki se bojijo Gospoda, da njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'V tegobi sem klical h Gospodu; Gospod mi je odgovoril in me postavil na velik kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Gospod je na moji strani; ne bom se bal, kaj mi more storiti človek?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Gospod jemlje moj delež s tistimi, ki mi pomagajo, zato bom videl svojo željo na tistih, ki me sovražijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Bolje je zaupati v Gospoda, kakor zaupanje polagati v človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Bolje je zaupati v Gospoda, kakor zaupanje polagati v prince.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Vsi narodi so me obkrožili, toda uničil jih bom v Gospodovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Obkrožili so me; da, obkrožili so me, toda uničil jih bom v Gospodovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Obkrožili so me kakor čebele; pogašeni so kakor ogenj iz trnja, kajti uničil jih bom v Gospodovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Kruto si me sunil, da bi lahko padel, toda Gospod mi je pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Gospod je moja moč in pesem in postal je rešitev moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Glas veselja in rešitve duš je v šotorskih svetiščih pravičnih; Gospodova desnica dela hrabro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Gospodova desnica je vzvišena, Gospodova desnica dela hrabro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ne bom umrl, temveč živel in oznanjal Gospodova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Gospod me je boleče okaral, toda ni me izročil smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Odprite mi velika vrata pravičnosti; šel bom vanje in bom hvalil Gospoda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'ta Gospodova velika vrata, v katera bodo vstopali pravični.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Hvalil te bom, kajti slišal si me in postal si rešitev moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kamen, ki so ga graditelji odklonili, je postal glava vogalnemu kamnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'To je Gospodovo delo, to je čudovito v naših očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'To je dan, ki ga je naredil Gospod; veselili se bomo in bili veseli v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Reši sedaj, rotim te, oh Gospod. Oh Gospod, rotim te, pošlji uspevanje sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Blagoslovljen bodi, kdor prihaja v Gospodovem imenu. Blagoslavljamo vas iz Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Bog je Gospod, ki nam je pokazal svetlobo. Žrtev povežite z vrvmi, celó k oltarnim rogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Ti si moj Bog in tebe bom hvalil; ti si moj Bog, poviševal te bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Oh zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'ALEF א Blagoslovljeni so neomadeževani na poti, ki hodijo v Gospodovi postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Blagoslovljeni so tisti, ki ohranjajo njegova pričevanja in ki ga iščejo z vsem srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Tudi ne počno krivičnosti; hodijo po njegovih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Ti si nam ukazal, da se marljivo držimo tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oh, da bi bile moje poti usmerjene, da se držim tvojih zakonov!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Potem ne bom osramočen, ko se oziram k vsem tvojim zapovedim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Hvalil te bom z iskrenostjo srca, ko se bom učil tvojih pravičnih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Držal se bom tvojih zakonov; o ne zapusti me popolnoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'BET ב S čim naj mladenič očisti svojo pot? S tem, da je pozoren nanjo, glede na tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'S svojim celotnim srcem te iščem; o ne pusti me oddaljiti se od tvojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Tvojo besedo sem skril v svoje srce, da ne bi grešil zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Blagoslovljen si ti, oh Gospod; úči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'S svojimi ustnicami sem oznanjal vse sodbe tvojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Veselil sem se na poti tvojih pričevanj, toliko kakor v vseh tvojih bogastvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Premišljeval bom o tvojih predpisih in se oziral k tvojim potem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Razveseljeval se bom v tvojih zakonih. Ne bom pozabil tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'GIMEL ג Radodarno ravnaj s svojim služabnikom, da bom lahko živel in se držal tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Odpri moje oči, da bom lahko gledal čudovite besede iz tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jaz sem tujec na zemlji; svojih zapovedi ne skrivaj pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Moja duša slabi zaradi hrepenenja, ki ga ima ob vseh časih do tvojih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Oštel si ponosne, ki so prekleti, ki zaidejo od tvojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Odstrani od mene grajo in zaničevanje, kajti držal sem se tvojih pričevanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Tudi princi so sedeli in govorili zoper mene, toda tvoj služabnik je premišljeval o tvojih zakonih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Tvoja pričevanja so tudi moje veselje in moji svetovalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'DALET ד Moja duša se lepi na prah, oživi me glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Oznanil sem svoje poti in ti si me slišal; úči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Daj mi razumeti pot tvojih predpisov; tako bom govoril o tvojih čudovitih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Moja duša se topi zaradi potrtosti; okrepi me glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Od mene odstrani lažnivo pot in mi milostno podéli svojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Izbral sem pot resnice, tvoje sodbe sem položil pred seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Prijel sem se tvojih pričevanj, oh Gospod; ne izroči me v sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Tekel bom pot tvojih zapovedi, ko boš razširil moje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'HE ה Úči me, oh Gospod, pot tvojih zakonov in tega se bom držal do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Daj mi razumevanje in bom čuval tvojo postavo; da, obeleževal jo bom s svojim celotnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Stôri mi, da grem po stezi tvojih zapovedi, kajti v tem se razveseljujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nagni moje srce k tvojim pričevanjem, ne pa k pohlepnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odvrni moje oči od gledanja praznih reči in oživi me na svoji poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Utrdi svojo besedo svojemu služabniku, ki je vdan tvojemu strahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Odvrni mojo grajo, ki se je bojim, kajti tvoje sodbe so dobre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Glej, hrepenel sem za tvojimi predpisi. Oživi me v svoji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'VAV ו Naj tvoja usmiljenja pridejo tudi k meni, oh Gospod, celó tvoja rešitev duše, glede na tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Tako bom imel kaj odgovoriti tistemu, ki me graja, kajti zaupam v tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Besede resnice pa ne vzemi popolnoma iz mojih ust, kajti [potrpežljivo] sem upal v tvoje sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Tako se bom nenehno držal tvoje postave, na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Hodil bom na prostosti, kajti iščem tvoje predpise.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Tudi pred kralji bom govoril o tvojih pričevanjih in ne bom osramočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Razveseljeval se bom v tvojih zapovedih, ki sem jih vzljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Tudi svoje roke bom dvignil k tvojim zapovedim, ki sem jih vzljubil in premišljeval bom o tvojih zakonih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'ZAJIN ז Spomni se besede svojemu služabniku, na osnovi katere si mi storil, da upam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'To je moja tolažba v moji stiski, kajti tvoja beseda me je oživila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Ponosni so me imeli silno v posmeh, vendar se nisem nagnil od tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Spomnil sem se tvojih sodb od davnine, oh Gospod in se potolažil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Polastila se me je groza zaradi zlobnih, ki zapuščajo tvojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tvoji zakoni so bili moje pesmi v hiši mojega popotovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Ponoči sem se spominjal tvojega imena, oh Gospod in se držal tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'To sem imel, ker sem se držal tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'HET ח »Ti si moj delež, oh Gospod.« Rekel sem, da bom ohranjal tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'S svojim celotnim srcem sem milo prosil tvojo naklonjenost; bodi mi usmiljen glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Mislil sem na svoje poti in svoja stopala sem obrnil k tvojim pričevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Podvizal sem se in nisem odlašal, da se držim tvojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, '§ Vezi zlobnih so me oropale, toda nisem pozabil tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Opolnoči bom vstajal, da se ti zahvaljujem zaradi tvojih pravičnih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Jaz sem družabnik vseh teh, ki se te bojijo in teh, ki se držijo tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Zemlja, oh Gospod, je polna tvojega usmiljenja; úči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'TET ט Dobro si storil s svojim služabnikom, oh Gospod, glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Úči me dobre sodbe in spoznanja, kajti veroval sem tvojim zapovedim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Preden sem bil užaloščen, sem zašel, toda sedaj sem se držal tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Ti si dober in delaš dobro; úči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Ponosni so zoper mene kovali laž, toda tvojih predpisov se bom držal s svojim celotnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Njihovo srce je tako rejeno kakor mast, toda jaz se razveseljujem v tvoji postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Dobro je zame, da sem bil užaloščen, da se lahko učim tvojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Postava tvojih ust mi je boljša kakor tisoči zlata in srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'JOD י Tvoje roke so me naredile in me oblikovale; daj mi razumevanje, da se lahko učim tvojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Tisti, ki se te bojijo, bodo veseli, ko me vidijo, kajti upal sem v tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Vem, oh Gospod, da so tvoje sodbe pravične in da si me ti v zvestobi užalostil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Prosim te, naj bo tvoja usmiljena prijaznost za mojo tolažbo, glede na svojo besedo svojemu služabniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Naj tvoja nežna usmiljenja pridejo k meni, da bom lahko živel, kajti tvoja postava je moja naslada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Naj bodo ponosni osramočeni, kajti brez razloga so sprevrženo ravnali z menoj, toda jaz bom premišljeval o tvojih predpisih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Naj se tisti, ki se te bojijo, obrnejo k meni in tisti, ki so spoznali tvoja pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Naj bo moje srce brez graje v tvojih zakonih, da ne bom osramočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'KAF כ Moja duša slabi zaradi tvoje rešitve duše, toda jaz upam v tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Moje oči pešajo zaradi tvoje besede, rekoč: »Kdaj me boš potolažil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Kajti postal sem podoben mehu v dimu, vendar ne pozabljam tvojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Koliko je dni tvojega služabnika? Kdaj boš izvršil sodbo na tistih, ki me preganjajo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Ponosni, ki niso po tvoji postavi, so zame kopáli jame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Vse tvoje zapovedi so zanesljive; po krivem me preganjajo, pomagaj mi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Na zemlji so me skoraj požrli, toda jaz nisem zapustil tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Oživi me po svoji ljubeči skrbnosti, tako se bom držal pričevanja tvojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'LAMED ל Na veke, oh Gospod, je tvoja beseda utrjena na nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Tvoja zvestoba je za vse rodove; utrdil si zemljo in ta ostaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Danes nadaljujejo glede na tvoje odredbe, kajti vsi so tvoji služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Če ne bi bila tvoja postava moje naslade, potem bi v svoji stiski propadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nikoli ne bom pozabil tvojih predpisov, kajti oživil si me.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Jaz sem tvoj, reši me, kajti iskal sem tvoje predpise.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Zlobni so čakali name, da me uničijo, toda jaz bom preudarjal tvoja pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Videl sem konec vse popolnosti, toda tvoja zapoved je silno široka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'MEM מ Oh kako ljubim tvojo postavo! Ona je ves dan moje premišljevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Zaradi svojih zapovedi si me naredil modrejšega od mojih sovražnikov, kajti one so vedno z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Imam več razumevanja kakor vsi moji učitelji, kajti tvoja pričevanja so moje premišljevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Razumem več kakor starci, ker se držim tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Svoja stopala sem zadržal pred vsako zlo potjo, da bi lahko obdržal tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Nisem odšel od tvojih sodb, kajti ti si me učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kako sladke so tvoje besede mojemu okusu! Da, slajše kakor med mojim ustom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Skozi tvoje predpise prejemam razumevanje, zato sovražim vsako napačno pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'NUN נ Tvoja beseda je svetilka mojim stopalom in svetloba moji stezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Prisegel sem in to bom opravil, da se bom držal tvojih pravičnih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Zelo sem užaloščen. Oživi me, oh Gospod, glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Rotim te, sprejmi prostovoljne daritve mojih ust, oh Gospod in uči me svojih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Moja duša je nenehno v moji roki, vendar ne pozabljam tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Zlobni so zame položili zanko, vendar nisem zašel od tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tvoja pričevanja sem vzel kot dediščino na veke, kajti ta so veselje mojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Svoje srce sem nagnil, da vedno izpolnjujem tvoje zakone, celo do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'SAMEH ס Sovražim prazne misli, toda ljubim tvojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Ti si moje skrivališče in moj ščit; upam v tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Odidite od mene, vi hudodelci, kajti držal se bom zapovedi svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Podpiraj me glede na svojo besedo, da bom lahko živel in zaradi svojega upanja naj ne bom osramočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Dvigni me in bom varen in nenehno se bom oziral k tvojim zakonom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Pomendral si vse tiste, ki so zašli od tvojih zakonov, kajti njihova prevara je neresnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Vse zlobneže zemlje daješ na stran kakor žlindro, zato ljubim tvoja pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Moje meso trepeta zaradi strahu pred teboj in bojim se tvojih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'AJIN ע Storil sem sodbo in pravico; ne prepusti me mojim zatiralcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Bodi pôrok za svojega služabnika v dobro; naj me ponosni ne zatirajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Moje oči pešajo zaradi tvoje rešitve duše in zaradi besede tvoje pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'S svojim služabnikom postopaj glede na svoje usmiljenje in uči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Jaz sem tvoj služabnik; daj mi razumevanje, da bom lahko spoznal tvoja pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Čas je zate, Gospod, da delaš, kajti razveljavili so tvojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Zato ljubim tvoje zapovedi bolj kakor zlato, da, bolj kakor čisto zlato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Zatorej spoštujem vse tvoje predpise glede vseh stvari, da so pravilni; in sovražim vsako napačno pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'PE פ Tvoja pričevanja so čudovita, zatorej se jih moja duša drži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Vstop tvojih besed daje svetlobo, to daje razumevanje preprostemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Odprl sem svoja usta in trepetal, kajti hrepenel sem za tvojimi zapovedmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Poglej name in bodi mi usmiljen, kakor ravnaš s tistimi, ki ljubijo tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Odredi moje korake po svoji besedi in nobena krivičnost naj nima gospostva nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Osvobodi me pred človeškim zatiranjem; tako se bom držal tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Stôri, da tvoj obraz sveti nad tvojim služabnikom in úči me svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Reke vodá iztekajo [iz] mojih oči, ker se ne držijo tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'TSADE צ Pravičen si ti, oh Gospod in tvoje sodbe so iskrene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tvoja pričevanja, ki si jih zapovedal, so iskrena in zelo zanesljiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Moja gorečnost me je použila, ker so moji sovražniki pozabili tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Tvoja beseda je zelo čista, zato jo tvoj služabnik ljubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Majhen sem in preziran, vendar ne pozabljam tvojih predpisov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Tvoja pravičnost je večna pravičnost in tvoja postava je resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Stiska in tesnoba sta se me polastili, vendar so tvoje zapovedi moje naslade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Pravičnost tvojih pričevanj je večna; daje mi razumevanje in jaz bom živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'KOF ק Klical sem z vsem svojim celotnim srcem; usliši me, oh Gospod, držal se bom tvojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Klical sem k tebi; reši me in držal se bom tvojih pričevanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Slutil sem svitanje jutra in klical; upal sem v tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Moje oči so slutile nočne straže, da bi lahko premišljeval v tvoji besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Prisluhni mojemu glasu glede na svojo ljubečo skrbnost, oh Gospod; oživi me glede na svojo sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Približali so se tisti, ki sledijo vragoliji; daleč so od tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Ti si blizu, oh Gospod, in vse tvoje zapovedi so resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Glede tvojih pričevanj sem spoznal od davnine, da si jih ti utemeljil na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'REŠ ר Preudari mojo stisko in me osvobodi, kajti jaz ne pozabljam tvoje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Zagovarjaj mojo pravdo in me osvobodi; oživi me glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Rešitev duš je daleč od zlobnih, kajti oni ne iščejo tvojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Velika so tvoja nežna usmiljenja, oh Gospod; oživi me glede na tvoje sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mnogo je mojih preganjalcev in mojih sovražnikov, vendar se ne nagnem od tvojih pričevanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Zagledal sem prestopnike in bil užaloščen, ker se niso držali tvoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Preudari kako ljubim tvoje predpise; oživi me, oh Gospod, glede na svojo ljubečo skrbnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Tvoja beseda je resnična od začetka in vsaka od tvojih pravičnih sodb traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'ŠIN ש Princi so me preganjali brez vzroka, toda moje srce stoji v strahospoštovanju pred tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Veselim se ob tvoji besedi kakor nekdo, ki najde velik plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Sovražim in preziram lažnivost, toda ljubim tvojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sedemkrat dnevno te hvalim zaradi tvojih pravičnih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, '§ Velik mir imajo tisti, ki ljubijo tvojo postavo in nič jih ne bo prizadelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Gospod, upal sem na tvojo rešitev duše in storil tvoje zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Moja duša je obdržala tvoja pričevanja in silno jih ljubim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Držal sem se tvojih predpisov in tvojih pričevanj, kajti vse moje poti so pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'TAV ת Naj moj klic pride blizu predte, oh Gospod; daj mi razumevanje glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Naj moja ponižna prošnja pride predte; osvobodi me glede na svojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Moje ustnice bodo izgovarjale hvalo, ko si me učil svojih zakonov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Moj jezik bo govoril o tvoji besedi, kajti vse tvoje zapovedi so pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Tvoja roka naj mi pomaga, kajti izbral sem tvoje predpise.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Hrepenel sem za tvojo rešitvijo duše, oh Gospod in tvoja postava je moja naslada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Naj moja duša živi in te bo hvalila in naj mi tvoje sodbe pomagajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Zašel sem kakor izgubljena ovca; išči svojega služabnika, kajti jaz ne pozabljam tvojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Pesem stopajočega vzpenjanja. V svoji tegobi sem klical h Gospodu in me je slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Osvobodi mojo dušo, oh Gospod, pred lažnivimi ustnicami in pred varljivim jezikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Kaj ti bo dano? Ali kaj ti bo storjeno, ti varljiv jezik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, '§ Ostre puščice mogočnega z brinovo žerjavico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Gorje meni, da se mudim v Mešehu, da prebivam v kedárskih šotorih!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Moja duša je dolgo prebivala s tistim, ki sovraži mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Jaz sem za mir, toda ko govorim, so oni za vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Pesem stopajočega vzpenjanja. Svoje oči bom povzdignil h goram, od koder prihaja moja pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Moja pomoč prihaja od Gospoda, ki je naredil nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Ne bo trpel, da bi bilo tvoje stopalo premaknjeno. On, ki te varuje, ne bo dremal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Glej, kdor varuje Izraela, ne bo niti dremal niti spal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Gospod je tvoj čuvaj; Gospod je tvoja senca na tvoji desnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Sonce te ne bo udarilo podnevi niti luna ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Gospod te bo varoval pred vsem zlom; varoval bo tvojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Gospod bo ohranil tvoje odhajanje in tvoje prihajanje od tega časa dalje in na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Davidova pesem stopajočega vzpenjanja. Bil sem vesel, ko so mi rekli: »Pojdimo v Gospodovo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Naša stopala bodo stala znotraj tvojih velikih vrat, oh Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzalem je zgrajen kakor mesto, ki je stisnjeno skupaj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'kamor se vzpenjajo rodovi, Gospodovi rodovi, v pričevanje Izraelu, da dajejo zahvalo Gospodovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Kajti tam so postavljeni sodni prestoli, prestoli Davidove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, '§ Mólite za mir v Jeruzalemu. Tisti, ki te ljubijo, bodo uspevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Mir bodi znotraj tvojih zidov in uspevanje v tvojih palačah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Zaradi mojih bratov in zaradi družabnikov bom torej rekel: »Mir bodi znotraj tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Zaradi hiše Gospoda, našega Boga, bom iskal tvoje dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Pesem stopajočega vzpenjanja. K tebi povzdigujem svoje oči, oh ti, ki prebivaš v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Glej, kakor oči služabnikov gledajo k roki svojih gospodarjev in kakor oči dekle k roki svoje gospodarice, tako naše oči čakajo na Gospoda, našega Boga, dokler se nas ne usmili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Usmili se nas, oh Gospod, usmili se nas, kajti silno smo nasičeni z zaničevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Naša duša je silno nasičena s preziranjem tistih, ki so ošabni in z zaničevanjem ponosnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Davidova pesem stopajočega vzpenjanja. Če ne bi bil Gospod, ki je bil na naši strani, lahko sedaj reče Izrael,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'če ne bi bil Gospod, ki je bil na naši strani, ko so ljudje vstali zoper nas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'tedaj [bi] nas žive požrli, ko je bil njihov bes vžgan zoper nas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'tedaj [bi] nas vode preplavile, vodni tok [bi] tekel preko naše duše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'tedaj [bi] vode ponosa tekle preko naše duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Blagoslovljen [bodi] Gospod, ki nas ni izročil njihovim zobem kakor plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Naša duša je kakor ptica ušla iz zanke ptičarjev; zanka je pretrgana in mi smo ušli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Naša pomoč je v imenu Gospodovem, ki je naredil nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Pesem stopajočega vzpenjanja. Tisti, ki zaupajo v Gospoda, bodo kakor gora Sion, ki ne more biti odstranjena, temveč ostaja na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Kakor so gore naokoli Jeruzalema, tako je Gospod naokoli svojega ljudstva od tega časa naprej, celo za vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Kajti palica zlobnih ne bo počivala na deležu pravičnih, da ne bi pravični svojih rok iztegnili h krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Delaj dobro, oh Gospod, tistim, ki so dobri in tistim, ki so iskreni v svojih srcih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, '§ Glede takšnih, ki zavijajo na svoje sprijene poti, jih bo Gospod odvedel z delavci krivičnosti, toda nad Izraelom bo mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Pesem stopajočega vzpenjanja. Ko je Gospod ponovno obrnil ujetništvo Siona, smo bili podobni tem, ki sanjajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tedaj so bila naša usta napolnjena s smehom in naš jezik s petjem. Tedaj so med pogani govorili: » Gospod je zanje storil velike stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Gospod je za nas storil velike stvari, česar smo veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, '§ Ponovno obrni naše ujetništvo, oh Gospod, kakor vodotoke na jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Tisti, ki sejejo s solzami, bodo želi z veseljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Kdor hodi naprej in joka in prinaša dragoceno seme, bo brez dvoma ponovno prišel z veseljem, nesoč svoje snope s seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Pesem stopajočega vzpenjanja za Salomona. Razen če Gospod ne zida hiše, se zaman trudijo, ki jo gradijo. Razen če Gospod ne varuje mesta, stražar le zaman bedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Zaman je zate, da vstajaš zgodaj, da hodiš pozno spat, da ješ kruh bridkosti, kajti tako on svojim ljubljenim daje spanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Glej! Otroci so dediščina od Gospoda in sad maternice je njegova nagrada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Kakor so puščice v roki mogočnega človeka, tako so otroci mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Srečen je človek, ki jih ima poln tul; ne bodo osramočeni, temveč bodo govorili s sovražniki pri velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Pesem stopajočega vzpenjanja. Blagoslovljen je vsak, kdor se boji Gospoda, ki hodi po njegovih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Kajti jedel boš trud svojih rok, srečen boš in s teboj bo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Tvoja žena bo kakor rodovitna trta ob straneh tvoje hiše; tvoji otroci kakor oljčne sadike naokrog tvoje mize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Glej, tako bo blagoslovljen mož, ki se boji Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, '§ Gospod naj te blagoslovi iz Siona in gledal boš dobro Jeruzalema vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, '§ Da, videl boš svojih otrok otroke in mir nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Pesem stopajočega vzpenjanja. Pogosto so me prizadeli od moje mladosti, naj sedaj reče Izrael,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'pogosto so me prizadeli od moje mladosti, vendar niso prevladali zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Orači so orali na mojem hrbtu; svoje brazde so naredili dolge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Gospod je pravičen; razsekal je vrvi zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Naj bodo zbegani in obrnjeni nazaj vsi, ki sovražijo Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Naj bodo kakor trava na hišnih strehah, ki ovene preden zraste,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 's čimer kosec ne napolni svoje roke niti kdor veže snope svojega naročja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, '[Naj] niti tisti, ki gredo mimo, ne rečejo: »Nad vami naj bo Gospodov blagoslov. Blagoslavljamo vas v Gospodovem imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Pesem stopajočega vzpenjanja. Iz globin sem klical k tebi, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Gospod, usliši moj glas. Naj bodo tvoja ušesa pozorna na glas mojih ponižnih prošenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Če si boš ti, Gospod, zaznamoval krivičnosti, oh Gospod, kdo bo vzdržal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Toda s teboj je odpuščanje, da bi se te lahko bali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, '§ Čakam na Gospoda, moja duša čaka in v njegovo besedo zaupam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Moja duša čaka na Gospoda bolj kakor tisti, ki stražijo na jutro, pravim, bolj kakor tisti, ki stražijo na jutro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Naj Izrael upa v Gospoda, kajti z Gospodom je usmiljenje in z njim je obilna odkupitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'On bo Izraela odkupil pred vsemi njegovimi krivičnostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Davidova pesem stopajočega vzpenjanja. Gospod, moje srce ni ošabno niti moje oči vzvišene niti se ne ukvarjam z velikimi zadevami ali s stvarmi zame previsokimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Zagotovo sem se lepo obnašal in se umiril, kakor otrok, ki je odstavljen od svoje matere; moja duša je celo kakor odstavljen otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Naj Izrael upa v Gospoda od tega časa naprej in na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Pesem stopajočega vzpenjanja. Gospod, spomni se Davida in vseh njegovih stisk,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'kako je prisegel Gospodu in se zaobljubil mogočnemu Jakobovemu Bogu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '»Zagotovo ne bom prišel v šotorsko svetišče svoje hiše niti šel gor v svojo posteljo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'svojim očem ne bom dal spanja ali dremanja svojim vekam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'dokler ne najdem kraja za Gospoda, prebivališča za mogočnega Jakobovega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, '§ Glej, slišali smo o tem v Efráti, našli smo to na gozdnih poljih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Šli bomo v njegova šotorska svetišča, oboževali bomo ob njegovi pručki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Vstani, oh Gospod, v svoj počitek, ti in skrinja tvoje moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Naj bodo tvoji duhovniki oblečeni s pravičnostjo in tvoji sveti naj vzklikajo od veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Zaradi svojega služabnika Davida ne obrni obličja proč od svojega maziljenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Gospod je Davidu prisegel z resnico; ne bo se odvrnil od nje: »Od sadu tvojega telesa bom postavil na tvoj prestol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Če se bodo tvoji otroci držali moje zaveze in mojega pričevanja, ki jih ga bom jaz učil, bodo tudi njihovi otroci sedeli na tvojem prestolu na vékomaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Kajti Gospod je izbral Sion; zaželel si ga je za svoje prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '»To je moj počitek na veke; tu bom prebival, ker sem si ga zaželel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Obilno bom blagoslavljal njegovo preskrbo, njegove uboge bom nasičeval s kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Prav tako bom njegove duhovnike oblekel z rešitvijo duš in njegovi sveti bodo glasno vzklikali od veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tam bom storil Davidovemu rogu, da vzbrsti; odredil sem svetilko za svojega maziljenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Njegove sovražnike bom oblekel s sramoto, toda na njem samem bo cvetela njegova krona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Davidova pesem stopajočega vzpenjanja. Glej, kako dobro in kako prijetno je za brate, da prebivajo skupaj v slogi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'To je podobno dragocenemu mazilu na glavi, ki teče navzdol na brado, celó Aronovo brado, ki gre dol h krajcem njegovih oblek;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'kakor rosa iz Hermona in kakor rosa, ki se je spustila na goro Sion; kajti tam je Gospod zapovedal blagoslov, celó življenje na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Pesem stopajočega vzpenjanja. Glejte, blagoslavljajte Gospoda, vsi vi Gospodovi služabniki, ki ponoči stojite v hiši Gospodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Dvignite svoje roke v svetišču in blagoslavljajte Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Gospod, ki je naredil nebo in zemljo, [naj] te blagoslovi iz Siona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Hvalite Gospoda. Hvalite Gospodovo ime, hvalite ga, oh vi Gospodovi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Vi, ki stojite v hiši Gospodovi, na dvorih hiše našega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'hvalite Gospoda, kajti Gospod je dober; prepevajte hvalnice njegovemu imenu, kajti to je prijetno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Kajti Gospod si je izbral Jakoba in Izraela za svoj izvoljeni zaklad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Kajti jaz vem, da je Gospod velik in da je naš Gospod nad vsemi bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Karkoli je Gospodu ugajalo, to je storil v nebesih, na zemlji, v morjih in vseh globokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Meglicam povzroča, da se dvigujejo od koncev zemlje, bliske dela za dež, veter prinaša iz svojih zakladnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Ki je udaril egiptovske prvorojence, tako od človeka kakor [od] živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Ki je poslal simbole in čudeže v tvojo sredo, oh Egipt, na faraona in na vse njegove služabnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Ki je udaril velike narode in usmrtil mogočne kralje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'amoréjskega kralja Sihóna, bašánskega kralja Oga in vsa kánaanska kraljestva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'in njihovo deželo dal za dediščino, dediščino Izraelu, svojemu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Tvoje ime, oh Gospod, traja večno in tvoj spomin, oh Gospod, skozi vse rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, '§ Kajti Gospod bo sodil svoje ljudstvo in se bo pokesal glede svojih služabnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Maliki poganov so srebro in zlato, delo človeških rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Imajo usta, toda ne govorijo, imajo oči, toda ne vidijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'imajo ušesa, toda ne slišijo niti v njihovih ustih ni kakršnegakoli diha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Tisti, ki so jih naredili, so jim podobni; tako je vsak, kdor zaupa vanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Blagoslavljajte Gospoda, oh hiša Izraelova. Blagoslavljajte Gospoda, oh hiša Aronova,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'blagoslavljajte Gospoda, oh hiša Lévijeva. Vi, ki se bojite Gospoda, blagoslavljajte Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Blagoslovljen bodi Gospod s Siona, ki prebiva v Jeruzalemu. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Oh zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Oh zahvaljujte se Bogu bogov, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Oh zahvaljujte se Gospodu gospodov, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Njemu, ki sam dela velike čudeže, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Njemu, ki je z modrostjo ustvaril nebo, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Njemu, ki je zemljo razpel nad vodami, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Njemu, ki je naredil velike luči, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'sonce, da vlada podnevi, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'luno in zvezde, da vladajo ponoči, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Njemu, ki je udaril Egipt na njegovih prvorojencih, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'in Izraela izpeljal izmed njih, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'z močno roko in z iztegnjenim laktom, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Njemu, ki je razdelil Rdeče morje na [dva] dela, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'in naredil Izraelu, da gre skozi njegovo sredo, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'toda porazil faraona in njegovo vojsko v Rdeče morje, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Njemu, ki je vodil svoje ljudstvo skozi divjino, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Njemu, ki je udaril velike kralje, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'in usmrtil slavne kralje, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'amoréjskega kralja Sihóna, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'in bašánskega kralja Oga, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'in njihovo deželo dal za dediščino, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'celó dediščino Izraelu, njegovemu služabniku, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Ki se nas je spomnil v našem nizkem stanu, kajti njegovo usmiljenje traja večno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'in nas odkupil pred našimi sovražniki, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Ki daje hrano vsemu mesu, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Oh zahvaljujte se Bogu nebes, kajti njegovo usmiljenje traja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Ob babilonskih rekah, tam smo se usedli; da, jokali smo, ko smo se spominjali Siona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Svoje harfe smo obesili na vrbe v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Kajti tam so tisti, ki so nas odvedli proč ujete, od nas zahtevali pesem in tisti, ki so nas opustošili, so od nas zahtevali veselje, rekoč: »Zapojte nam eno izmed sionskih pesmi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kako naj bi v tuji deželi peli Gospodovo pesem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Če jaz pozabim tebe, oh Jeruzalem, naj moja desnica pozabi svojo spretnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Če se te jaz ne spomnim, naj se moj jezik prilepi k nebu mojih ust, če ne povišam Jeruzalema nad svojo glavno radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Spomni se, oh Gospod, na Jeruzalemov dan otrok Edóma, ki so rekli: »Izbrišite ga, izbrišite ga, celo do njegovih temeljev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, '§ Oh hči babilonska, ki boš uničena, srečen bo tisti, ki te poplača, kakor si nam ti služila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Srečen bo tisti, ki zgrabi in trešči tvoje malčke ob kamne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davidov psalm. § Hvalil te bom s svojim celotnim srcem; pred bogovi ti bom prepeval hvalnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Oboževal te bom pred tvojim svetim templjem in tvoje ime hvalil zaradi tvoje ljubeče skrbnosti in zaradi tvoje resnice, kajti svojo besedo si poveličal nad vse svoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Na dan, ko sem klical, mi odgovarjaš in me v moji duši krepiš z močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Vsi kralji zemlje te bodo hvalili, oh Gospod, ko slišijo besede iz tvojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Da, prepevali bodo na Gospodovih poteh, kajti velika je Gospodova slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Čeprav je Gospod vzvišen, vendar ima spoštovanje do nizkega, toda ponosnega spozna od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Čeprav hodim sredi stiske, me boš ti poživil. Zoper bes mojih sovražnikov boš iztegnil svojo roko in tvoja desnica me bo rešila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Gospod bo dovršil to, kar zadeva mene. Tvoje usmiljenje, oh Gospod, vztraja večno; ne zapusti del svojih lastnih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Vodji glasbenikov, Davidov psalm. Oh Gospod, preiskal si me in me spoznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Poznaš moje sedanje in moje vstajanje, moje misli razumeš daleč stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Obdajaš mojo pot in moje leganje in seznanjen si z vsemi mojimi potmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Kajti besede ni na mojem jeziku, toda, glej, oh Gospod, ti jo popolnoma poznaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Obdajaš me zadaj in spredaj in name polagaš svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Takšno spoznanje je prečudovito zame, visoko je, ne morem ga doseči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kam naj grem pred tvojim duhom? Ali kam naj pobegnem pred tvojo prisotnostjo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, '§ Če se povzpnem v nebesa, si tam; če si svojo posteljo pripravim v peklu, glej, si tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Če vzamem peruti jutra in prebivam v najbolj oddaljenih krajih morja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'celo tam me bo tvoja roka vodila in tvoja desnica me bo držala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Če rečem: »Zagotovo me bo pokrila tema, celo noč bo svetloba okoli mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Da, tema se ne skriva pred teboj, toda noč sije kakor dan; tema in svetloba, obe sta ti podobni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, '§ Kajti v last si si vzel mojo notranjost, pokril si me v maternici moje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Hvalil te bom, kajti jaz sem strašljivo in izvrstno narejen. Čudovita so tvoja dela in to moja duša resnično dobro ve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Moja snov ni bila skrita pred teboj, ko sem bil narejen na skrivnem in nenavadno izdelan v najnižjih delih zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tvoje oči so videle mojo snov, čeprav je bila nepopolna in v tvoji knjigi so bili zapisani vsi moji udje, ki so bili oblikovani v vztrajanju, medtem ko ni bilo še nobenega izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Kako dragocene so mi tudi tvoje misli, oh Bog! Kako velik je njihov seštevek!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Če bi jih preštel, jih je po številu več kakor peska. Ko se zbudim, sem še vedno s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, '§ Zagotovo boš ubil zlobnega, oh Bog, zato odidite od mene, vi krvoločni ljudje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, '§ Kajti zlobno govorijo zoper tebe in tvoji sovražniki zaman jemljejo tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Ali ne sovražim tistih, oh Gospod, ki sovražijo tebe? Mar nisem užaloščen s tistimi, ki se dvigujejo zoper tebe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Sovražim jih s popolnim sovraštvom, štejem jih [za] svoje sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Preišči me, oh Bog in spoznaj moje srce; preizkusi me in spoznaj moje misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Poglej ali je v meni kakršnakoli zlobna pot in vodi me po večni poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Vodji glasbenikov, Davidov psalm. Osvobodi me, oh Gospod, pred zlobnežem, varuj me pred nasilnežem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'ki si v svojem srcu domišljajo vragolije; nenehno so zbrani skupaj za vojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Svoje jezike so naostrili kakor kača, gadji strup je pod njihovimi ustnicami. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Varuj me, oh Gospod, pred rokami zlobnih, ohrani me pred nasilnežem, ki se je namenil, da zruši moja ravnanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Ponosni so zame prikrili zanko in vrvi, ob poti so razprostrli mrežo, zame so nastavili pasti. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Gospodu sem rekel: »Ti si moj Bog, usliši glas mojih ponižnih prošenj, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Oh Bog, Gospod, moč rešitve moje duše, mojo glavo si pokril na dan bitke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Ne usliši, oh Gospod, želja zlobnih, nadalje ne njihovega zlobnega naklepa, da se ne bi poviševali.« Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Glede glave tistih, ki me obdajajo, naj jih pokrije vragolija njihovih lastnih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Naj nanje padajo goreči ogorki, naj bodo vrženi v ogenj, v globoke jame, da ne vstanejo ponovno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Naj obrekovalec ne bo utrjen na zemlji, zlo naj lovi nasilneža, da ga premaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Vem, da bo Gospod podpiral zadevo prizadetega in pravico ubogega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Zagotovo se bodo pravični zahvaljevali tvojemu imenu; iskreni bodo prebivali v tvoji prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Davidov psalm. Gospod, k tebi kličem, pohiti k meni; pazljivo prisluhni mojemu glasu, ko kličem k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Naj bo moja molitev postavljena pred teboj kakor kadilo in dvigovanje mojih rok kakor večerno žrtvovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Postavi stražo, oh Gospod, pred moja usta; čuvaj vrata mojih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Mojega srca ne nagni h kakršnikoli zli stvari, da izvajam dela z ljudmi, ki počnejo krivičnost; in naj ne jem od njihovih slaščic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, '§ Naj me pravični udari, to bo prijaznost in naj me graja; to bo odlično olje, ki ne bo zlomilo moje glave, ker bo vendar v njihovih katastrofah tudi moja molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, '§ Kadar so njihovi sodniki premagani na kamnitih krajih, bodo slišali moje besede, kajti prijetne so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Naše kosti so razkropljene ob ustih groba, kakor kadar nekdo seka in cepi les na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Toda moje oči so k tebi, oh Bog, Gospod; v tebi je moje trdno upanje, moje duše ne pusti zapuščene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Varuj me pred zankami, ki so jih položili zame in [pred] pastmi delavcev krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Naj zlobni padejo v svoje lastne mreže, medtem ko jaz istočasno pobegnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Davidov pouk, molitev, ko je bil v votlini. S svojim glasom sem klical h Gospodu, s svojim glasom sem storil svojo ponižno prošnjo h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Svojo pritožbo sem izlil pred njim, pred njim sem pokazal svojo stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Ko je bil moj duh znotraj mene nadvladan, tedaj ti poznaš mojo pot. Na stezi, po kateri sem hodil, so zame na skrivnem postavili zanko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Pogledal sem na svojo desnico in zagledal, toda ni bilo človeka, ki bi me poznal. Zatočišče se mi je izneverilo, noben človek ni skrbel za mojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Klical sem k tebi, oh Gospod. Rekel sem: »Ti si moje zatočišče in moj delež v deželi živih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Prisluhni mojemu joku, kajti zelo sem ponižan. Osvobodi me pred mojimi preganjalci, kajti močnejši so od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Privedi mojo dušo iz ječe, da bom lahko hvalil tvoje ime. Pravični me bodo obdali, kajti radodarno boš postopal z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Davidov psalm. Usliši mojo molitev, oh Gospod, pazljivo prisluhni mojim ponižnim prošnjam; odgovori mi v svoji zvestobi in v svoji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Ne vstopi na sodbo s svojim služabnikom, kajti v tvojem pogledu noben živeč človek ne bo opravičen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Kajti sovražnik je preganjal mojo dušo, moje življenje je z udarcem zrušil k tlom; pripravil me je, da prebivam v temi, kakor tisti, ki so bili dolgo mrtvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Zato je moj duh nadvladan znotraj mene, moje srce znotraj mene je zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Spominjam se dni iz davnine, premišljujem o vseh tvojih delih, razglabljam o delu tvojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Svoje roke iztegujem k tebi; mojo dušo žeja po tebi kakor žejno deželo. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Naglo me usliši, oh Gospod, moj duh slabi. Svojega obraza ne skrivaj pred menoj, da ne bi bil podoben tem, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Povzroči mi, da zjutraj slišim tvojo ljubečo skrbnost, kajti vate zaupam. Povzroči mi, da spoznam pot, po kateri naj hodim, kajti svojo dušo dvigujem k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Osvobodi me, oh Gospod, pred mojimi sovražniki. K tebi zbežim, da me skriješ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Úči me izpolnjevati tvojo voljo, kajti ti si moj Bog. Tvoj duh je dober, vodi me v deželo iskrenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Oživi me, oh Gospod, zaradi svojega imena; zaradi svoje pravičnosti mojo dušo privedi iz stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Zaradi svojega usmiljenja iztrebi moje sovražnike in uniči vse tiste, ki prizadevajo mojo dušo, kajti jaz sem tvoj služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Davidov psalm. Blagoslovljen bodi Gospod, moja moč, ki uči moje roke za vojno in moje prste za boj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'moja dobrota in moja trdnjava, moj visoki stolp in moj osvoboditelj, moj ščit in tisti, v katerega zaupam, ki moje ljudstvo podjarmlja pod mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Gospod, kaj je človek, da ti jemlješ spoznanje o njem! Ali človeški sin, da delaš obračun o njem!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Človek je podoben ničevosti, njegovi dnevi so kakor senca, ki mineva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Upogni svoje nebo, oh Gospod in pridi dol, dotakni se gora in se bodo kadile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Vrzi bliskanje in jih razkropi; izstreli svoje puščice in jih uniči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Pošlji svojo roko od zgoraj, odstrani me in osvobodi me iz velikih vodá, pred roko tujih otrok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'čigar usta govorijo prazne reči in je njihova desnica desnica neresnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Zapel ti bom novo pesem, oh Bog, na plunko in glasbilo desetih strun ti bom prepeval hvalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'On je, ki kraljem daje rešitev duš, ki osvobaja Davida, svojega služabnika, pred škodljivim mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Reši me in osvobodi me pred roko tujih otrok, katerih usta govorijo prazne reči in je njihova desnica desnica neresnice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'da bodo naši sinovi lahko kakor sadike odrasle v svoji mladosti, da bodo naše hčere kakor vogalni kamni, pološčeni po podobnosti palače,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'da bodo naše kašče lahko polne, nudeč vse vrste zalog, da lahko naše ovce na naših ulicah skotijo tisoče in deset tisoče,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'da bodo naši voli lahko močni za delo, da ne bo vloma niti izginjanja, da na naših ulicah ne bo pritoževanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Srečno je tisto ljudstvo, ki je v takšni zadevi, da, srečno je tisto ljudstvo, čigar Bog je Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Davidov psalm hvalnice. Povzdigoval te bom, moj Bog, oh kralj in tvoje ime bom blagoslavljal na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Vsak dan te bom blagoslavljal in tvoje ime bom hvalil na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Velik je Gospod in silno bodi hvaljen in njegova veličina je nedoumljiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'En rod bo hvalil tvoja dela drugemu in bo oznanjal tvoja mogočna dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Govoril bom o veličastni časti tvojega veličanstva in o tvojih čudovitih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Ljudje bodo govorili o moči tvojih strašnih dejanj; in jaz bom oznanjal tvojo veličino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Obilno bodo izrekli spomin o tvoji veliki dobroti in prepevali bodo o tvoji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gospod je milostljiv in poln sočutja, počasen za jezo in zelo usmiljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Gospod je dober do vseh in njegova nežna usmiljenja so nad vsemi njegovimi deli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Hvalila te bodo vsa tvoja dela, oh Gospod in tvoji sveti te bodo blagoslavljali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Pogovarjali se bodo o slavi tvojega kraljestva in govorili o tvoji moči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'da razglašajo njegova mogočna dela človeškim sinovom in slavno veličanstvo njegovega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Tvoje kraljestvo je večno kraljestvo in tvoje gospostvo traja skozi vse rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Gospod podpira vse, ki padejo in dviguje vse tiste, ki so sklonjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Oči vseh čakajo nate in ti jim daješ njihovo hrano v pravšnjem obdobju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Odpiraš svojo roko in zadovoljuješ željo vsake žive stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Gospod je pravičen na vseh svojih poteh in svet v vseh svojih delih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Gospod je blizu vsem tem, ki kličejo k njemu, vsem, ki k njemu kličejo v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Izpolnil bo željo tistih, ki se ga bojijo. Slišal bo tudi njihov jok in jih bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Gospod varuje vse tiste, ki ga ljubijo, toda vse zlobne bo uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Moja usta bodo govorila Gospodovo hvalo in vse meso naj blagoslavlja njegovo sveto ime na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Hvalite Gospoda. Hvali Gospoda, oh moja duša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Medtem ko živim, bom hvalil Gospoda; medtem ko imam kakršen koli obstoj, bom prepeval hvalnice svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Svojega trdnega upanja ne polagaj v prince niti v človeškega sina, v katerem ni pomoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Njegov dih gre dalje, vrača se k svoji zemlji; na ta isti dan propadejo njegove misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Srečen je tisti, ki ima za svojo pomoč Jakobovega Boga, katerega upanje je v Gospodu, njegovemu Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'ki je naredil nebo in zemljo, morje in vse, kar je tam notri, ki na veke ohranja resnico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'ki izvršuje sodbo za zatiranega, ki daje hrano lačnemu. Gospod osvobaja jetnike,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Gospod slepim odpira oči, Gospod dviguje tiste, ki so sklonjeni, Gospod ljubi pravične,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Gospod varuje tujce in podpira osirotelega in vdovo, toda pot zlobnih postavlja na glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Gospod bo kraljeval na veke, celó tvoj Bog, oh Sion, vsem rodovom. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Hvalite Gospoda, kajti dobro je peti hvalnice našemu Bogu, kajti to je prijetno in hvala je ljubka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Gospod je zgradil Jeruzalem; skupaj zbira Izraelove pregnance.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Ozdravlja potrte v srcu in povezuje njihove rane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Šteje število zvezd, vse jih kliče po njihovih imenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Velik je naš Gospod in zelo močan, njegovo razumevanje je neskončno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Gospod dviguje krotke; zlobne podira k tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Pojte Gospodu z zahvaljevanjem, našemu Bogu pojte hvalo na harfo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'ki nebo pokriva z oblaki, ki za zemljo pripravlja dež, ki daje travi, da raste po gorah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'On daje živali njeno hrano in mladim krokarjem, ki kličejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ne razveseljuje se v moči konja. Ne veseli se človeških nog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Gospod se veseli tistih, ki se ga bojijo, tistih, ki upajo v njegovo usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Hvali Gospoda, oh Jeruzalem, hvali svojega Boga, oh Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Kajti utrjuje zapahe tvojih velikih vrat, tvoje otroke je blagoslovil znotraj tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Na tvojih mejah daje mir in te nasičuje z najodličnejšo pšenico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Svojo zapoved pošilja na zemljo; njegova beseda teče zelo naglo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Sneg daje kakor volno, slano razsiplje kakor pepel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Svoj led meče kakor koščke; kdo lahko obstane pred njegovim mrazom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Razpošilja svojo besedo in jih topi; svojemu vetru povzroča, da piha in vodam, [da] tečejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Svojo besedo kaže Jakobu, svoje zakone in svoje sodbe Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Z nobenim narodom ni tako postopal in glede njegovih sodb, jih oni niso spoznali. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Hvalite Gospoda. Hvalite Gospoda iz nebes, hvalite ga na višavah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Hvalite ga, vsi njegovi angeli, hvalite ga, vse njegove vojske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Hvalita ga, sonce in luna, hvalite ga vse ve zvezdne luči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Hvalite ga, ve nebes nebesa in ve vode, ki ste nad nebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Naj hvalijo Gospodovo ime, kajti ukazal je in bili so ustvarjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Tudi njih je utrdil na veke vekov; naredil je odlok, ki ne bo minil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Hvalite Gospoda z zemlje, vi zmaji in vse globine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'ogenj in toča, sneg in meglica, viharni veter, izpolnjujoč njegovo besedo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'gore in vsi hribi, rodovitna drevesa in vse cedre,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'živali in vsa živina, plazeče stvari in leteča perjad,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'kralji zemlje in vsi ljudje, princi in vsi zemeljski sodniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'tako mladeniči kakor mladenke, starci in otroci;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'naj hvalijo Gospodovo ime, kajti njegovo ime samó je odlično; njegova slava je nad zemljo in nebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Povišuje tudi rog svojega ljudstva, hvalo vseh njegovih svetih, celó Izraelovih otrok, ljudstva blizu njemu. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Hvalite Gospoda. Zapojte Gospodu novo pesem in njegovo hvalo v skupnosti svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Naj se Izrael veseli v njem, ki ga je naredil, naj bodo sionski otroci radostni v svojem Kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Naj s plesom hvalijo njegovo ime; naj mu prepevajo hvalnice s tamburinom in harfo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Kajti Gospod se veseli v svojem ljudstvu; krotke bo okrasil z rešitvijo duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Naj bodo sveti radostni v slavi, naj na glas prepevajo na svojih posteljah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Naj bodo na njihovih ustih visoke Božje hvalnice in v njihovi roki dvorezen meč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'da izvršijo maščevanje nad pogani in kaznovanja nad ljudstvi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'da njihove kralje zvežejo z verigami in njihove plemiče z železnimi okovi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'da nad njimi izvršijo napisano sodbo. To čast imajo vsi sveti. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Hvalite Gospoda, hvalite Boga v njegovem svetišču, hvalite ga na nebesnem svodu njegove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Hvalite ga za njegova mogočna dela, hvalite ga glede na njegovo odlično veličino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Hvalite ga z zvokom šofarja, hvalite ga s plunko in harfo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Hvalite ga s tamburinom in plesom, hvalite ga z glasbili na strune in piščali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Hvalite ga na glasne cimbale, hvalite ga na visoko zveneče cimbale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Naj vsaka stvar, ki diha, hvali Gospoda. Hvalite Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Pregovori Salomona, Davidovega sina, Izraelovega kralja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'da bi spoznali modrost in poučevanje, da bi zaznali besede razumevanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'da bi sprejeli poučevanje modrosti, pravice, sodbe in nepristranskost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'da bi dali premetenost preprostemu, mladeniču spoznanje in preudarnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Moder človek bo slišal in bo povečal učenje in razumen človek se bo dokopal k modrim nasvetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'da bo razumel pregovor in razlago, besede modrih in njihove temne izreke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Strah Gospodov je začetek spoznanja, toda bedaki prezirajo modrost in poučevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Moj sin, prisluhni poučevanju svojega očeta in ne zapusti postave svoje matere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'kajti ona bosta ornament milosti tvoji glavi in verižici okoli tvojega vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Moj sin, če te grešniki privabljajo, ne privoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Če rečejo: »Pridi z nami, v zasedi prežimo na kri, brez razloga se tajno pritajimo za nedolžnega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'požrimo jih žive kakor grob in cele, kakor tiste, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Našli bomo vse dragoceno imetje, svoje hiše bomo napolnili z ukradenim blagom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Svoj žreb vrzi med nas, vsi imejmo eno mošnjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Moj sin, ne hodi z njimi na pot, svoje stopalo zadrži pred njihovo stezo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'kajti njihova stopala tečejo k zlu in hitijo, da prelijejo kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Zagotovo je zaman razprostrta mreža v očeh katerekoli ptice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'In oni prežijo v zasedi na svojo lastno kri, tajno se pritajijo za svoja lastna življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, '§ Takšne so poti vsakega, ki je pohlepen dobička, ki odvzema življenje svojim lastnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Modrost kliče zunaj, svoj glas izreka na ulicah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'kliče na glavnem kraju vrveža, v odprtinah velikih vrat, v mestu izreka svoje besede, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '»Doklej boste, vi topi, ljubili topost? In se posmehljivci razveseljevali v svojem posmehovanju in bedaki sovražili spoznanje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Obrnite se na moj opomin. Glejte, na vas bom izlila svojega duha, razglašala vam bom svoje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Ker sem klicala, pa ste odklonili, iztegovala sem svojo roko, pa noben človek ni upošteval,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'temveč ste zaničevali vse moje svetovanje in niste hoteli mojega opomina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'se bom tudi jaz smejala ob vaši katastrofi, zasmehovala bom, ko pride vaš strah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'ko prihaja vaš strah kakor opustošenje in vaše uničenje kakor vrtinčast veter, ko nad vas prihajata tegoba in tesnoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tedaj se bodo obračali name, toda ne bom jim odgovorila, iskali me bodo zgodaj, toda ne bodo me našli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'ker so sovražili spoznanje in niso izbrali strahu Gospodovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ničesar niso hoteli od mojega nasveta. Prezirali so vsak moj opomin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Zato bodo jedli od sadu svoje lastne poti in napolnjeni bodo s svojimi lastnimi naklepi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, '§ Kajti odvračanje od preprostosti jih bo ubilo in uspevanje bedakov jih bo uničilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Toda kdorkoli me posluša, bo varno prebival in bo miren pred strahom zla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Moj sin, če boš sprejel moje besede in moje zapovedi skril s seboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'tako da boš svoje uho nagnil k modrosti in svoje srce usmeril k razumevanju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'da, če kličeš za spoznanjem in svoj glas dvigaš za razumevanjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'če jo iščeš kakor srebro in preiskuješ za njo kakor za skritimi zakladi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'potem boš razumel Gospodov strah in našel spoznanje Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Kajti Gospod daje modrost. Iz njegovih ust prihajata spoznanje in razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, '§ Zdravo modrost shranjuje za pravičnega, on je majhen ščit tem, ki hodijo pošteno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Čuva steze sodbe in varuje pot svojih svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Potem boš razumel pravičnost, sodbo in nepristranskost, da, vsako dobro stezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Kadar v tvoje srce vstopa modrost in je spoznanje prijetno tvoji duši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'te bo varovala preudarnost, razumevanje te bo ohranilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'da te osvobodi pred potjo zlega človeka. Pred človekom, ki govori kljubovalne stvari,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'ki zapušča steze poštenosti, da hodi po poteh teme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'ki se veseli, da počne zlo in se razveseljuje v kljubovalnosti zlobnih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'katerega poti so sprijene, oni pa kljubujejo na svojih stezah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Da te osvobodi pred tujo žensko, celó pred tujko, ki laska s svojimi besedami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'ki se odpoveduje vodniku svoje mladosti in pozablja zavezo svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Kajti njena hiša se nagiba k smrti in njene steze k mrtvim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Nihče, ki gre k njej, se ne vrne ponovno niti se ne oprime stezá življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Da boš lahko hodil po poti dobrih ljudi in se držal stezá pravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Kajti iskreni bodo prebivali v deželi in popolni bodo preostali v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Toda zlobni bodo iztrebljeni z zemlje in prestopniki bodo izkoreninjeni iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Moj sin, ne pozabi moje postave, temveč naj tvoje srce ohrani moje zapovedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'kajti dolžino dni in dolgo življenje in mir bodo dodale k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Usmiljenje in resnica naj te ne zapustita; priveži si ju okoli svojega vratu, zapiši si ju na tablico svojega srca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'tako boš našel naklonjenost in dobro razumevanje v očeh Boga in človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Zaupaj v Gospoda z vsem svojim srcem in ne zanašaj se na svoje lastno razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Na vseh svojih poteh ga priznavaj in usmerjal bo tvoje steze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne bodi moder v svojih lastnih očeh. Boj se Gospoda in odidi od zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'To bo zdravje tvojemu popku in mozeg tvojim kostem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Časti Gospoda s svojim imetjem in s prvimi sadovi vsega svojega donosa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'tako bodo tvoji skednji napolnjeni z obiljem in tvoje stiskalnice bodo izbruhnile z novim vinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Moj sin, ne preziraj Gospodovega karanja niti ne bodi naveličan njegovega grajanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Kajti katerega Gospod ljubi, on graja, celo kakor oče sina, v katerem se razveseljuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Srečen je človek, ki odkriva modrost in človek, ki pridobiva razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Kajti njeno trgovsko blago je boljše kakor trgovsko blago iz srebra in njen dobiček boljši od čistega zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Dragocenejša je od rubinov, in vse stvari, ki si jih lahko želiš, se ne morejo primerjati z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Dolžina dni je v njeni desnici in v njeni levici bogastva in čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Njene poti so poti prijetnosti in vse njene steze so mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Je drevo življenja tistim, ki se je oprimejo in srečen je vsak, ki jo ohranja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Gospod je z modrostjo utemeljil zemljo, z razumevanjem je utrdil nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, '§ Z njegovim spoznanjem so izbruhnile globine in oblaki kapljajo roso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Moj sin, naj ti dve ne odideta od tvojih oči; ohrani zdravo modrost in preudarnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'tako bosta življenje tvoji duši in milost tvojemu vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Potem boš na svoji stezi hodil varno in tvoje stopalo se ne bo spotikalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Ko se uležeš, ne boš prestrašen; da, ulegel se boš in tvoje spanje bo sladko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne bodi prestrašen od nenadnega strahu niti od opustošenja zlobnih, kadar to prihaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Kajti Gospod bo tvoje zaupanje in tvoja stopala bo varoval pred odvzemom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne zadržuj dobrega pred tistimi, ki jim je to primerno, kadar je v moči tvoje roke, da to storiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne reci svojemu bližnjemu: »Pojdi, ponovno pridi in jutri ti bom dal,« če imaš to pri sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne snuj zla zoper svojega soseda, glede na to, da varno prebiva poleg tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Ne prepiraj se brez razloga s človekom, če ti ni ničesar hudega storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne zavidaj zatiralcu in ne izberi nobenih njegovih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, '§ Kajti kljubovalnež je ogabnost Gospodu, toda njegova skrivnost je s pravičnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Gospodovo prekletstvo je v hiši zlobnega, toda blagoslavlja prebivališče pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Zagotovo zasmehuje posmehljivce, toda milost daje ponižnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Modri bo podedoval slavo, toda napredovanje bedakov bo sramota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Prisluhnite, vi otroci, poučevanju očeta in pazite, da spoznate razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Kajti dajem vam dober nauk, ne zapustite moje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Kajti jaz sem bil sin svojega očeta, nežen in edini ljubljen v očeh svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Tudi učil me je in mi rekel: »Tvoje srce naj ohrani moje besede. Drži se mojih zapovedi in živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Pridobivaj modrost, pridobivaj razumevanje, tega ne pozabi niti se ne nagni od besed iz mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne zapusti je, pa te bo varovala; ljubi jo, pa te bo čuvala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Modrost je glavna stvar, zato pridobivaj modrost in z vsem svojim dobičkom pridobivaj razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Poveličuj jo, pa te bo povišala, prinesla ti bo čast, ko jo boš objemal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Tvoji glavi bo dala ornament milosti, izročila ti bo krono slave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Prisluhni, oh moj sin in sprejmi moje izreke in mnogo bo let tvojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Učil sem te na poti modrosti, vodil sem te po pravih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Kadar greš, tvoje stopinje ne bodo utesnjene in kadar tečeš, se ne boš spotaknil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Trdno se oprimi poučevanja, naj ona ne odide. Obdrži jo, kajti ona je tvoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Ne stopaj na pot zlobnih in ne hodi po stezi zlobnih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Izogibaj se je, ne hodi mimo nje in obrni se od nje ter pojdi proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Kajti oni ne spijo, razen če niso storili vragolije in njihovo spanje je odvzeto, razen če nekomu ne povzročijo, da pade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Kajti jedo kruh zlobnosti in pijejo vino nasilja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Toda steza pravičnih je kakor svetlikajoča svetloba, ki bolj in bolj sije do popolnega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Pot zlobnih je kakor tema; ne vedo ob kaj se spotaknejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Moj sin, prisluhni mojim besedam, svoje uho nagni k mojim izrekom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Naj le-ti ne odidejo od tvojih oči, obdrži jih v sredi svojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Kajti življenje so tistim, ki jih najdejo in zdravje vsemu njihovemu mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Svoje srce varuj z vso marljivostjo, kajti iz njega so zadeve življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Kljubovalna usta daj od sebe in sprevržene ustnice odloži daleč stran od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Tvoje oči naj gledajo naravnost in tvoje veke naj gledajo neposredno pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Preudari stezo svojih stopal in vse tvoje poti naj bodo utrjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ne obrni se ne k desni roki niti ne k levi, svoje stopalo odstrani od zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Moj sin, prisluhni moji modrosti in svoje uho pripogni k mojemu razumevanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'da boš lahko upošteval preudarnost in da bodo tvoje ustnice lahko obvarovale spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Kajti ustnice tuje ženske kapljajo kakor satovje in njena usta so bolj prilizljiva kakor olje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'toda njen konec je grenek kakor pelin, oster kakor dvorezen meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Njena stopala gredo dol k smrti, njeni koraki se prijemljejo pekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Da ne bi preudarjal steze življenja, njene poti so premične, da jih ti ne moreš spoznati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Zato mi torej prisluhnite, oh vi otroci in ne odidite od besed mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Svojo pot odstrani daleč od nje in ne pridi blizu vrat njene hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'da ne bi svoje časti dal drugim in svojih let krutemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'da ne bi bili tujci nasičeni s tvojim premoženjem in bi bili tvoji napori v hiši tujca');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'in boš končno žaloval, ko bo tvoje meso in tvoje telo iztrošeno');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'in rečeš: »Kako sem sovražil poučevanje in je moje srce preziralo opomin');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'in nisem ubogal glasu svojih učiteljev niti svojega ušesa nagnil k tem, ki so me poučevali!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Bil sem skoraj v vsem zlu v sredi skupnosti in zbora.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pij vode iz svojega lastnega vodnega zbiralnika in tekoče vode iz svojega lastnega izvira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Naj bodo tvoji studenci razpršeni naokoli in reke vodá po ulicah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Naj bodo samo tvoji lastni in ne s teboj [tudi] tujčevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Naj bo tvoj studenec blagoslovljen in razveseljuj se z ženo svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, '§ Ona naj bo kakor ljubeča košuta in prijetna srna. Naj te njene prsi zadovoljijo ob vseh časih in vedno bodi očaran z njeno ljubeznijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, '§ Zakaj hočeš biti ti, moj sin, očaran s tujo žensko in objemati naročje tujke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Kajti človekove poti so pred Gospodovimi očmi in on preudarja vsa njegova ravnanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Njegove lastne krivičnosti bodo zlobnega vzele k sebi in držan bo z vrvmi svojih grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Umrl bo brez poučevanja in v veličini svoje neumnosti bo zašel na stranpot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Moj sin, če si pôrok za svojega prijatelja, če si udaril svojo roko s tujcem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, '§ si ulovljen z besedami svojih ust, si vzet z besedami svojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Sedaj stôri to, moj sin in se osvobodi, ko si prišel v roko svojega prijatelja. Pojdi, ponižaj se in prepričaj svojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Ne daj spanja svojim očem niti dremanja svojim vekam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Osvobodi se kakor srna pred lovčevo roko in kakor ptica pred ptičarjevo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Pojdi k mravlji, ti lenuh, preudari njene poti in bodi moder,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'ki nima ne vodnika, ne nadzornika ali ne vladarja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'svojo hrano si pripravlja poleti in svojo hrano zbira na žetvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Doklej boš spal, oh lenuh? Kdaj boš vstal iz svojega spanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Še malo spanja, malo dremanja, malo prekrižanih rok za spanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'tako bo tvoja revščina prišla kakor nekdo, ki se klati in tvoje pomanjkanje kakor oborožen človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Nespodobna oseba, zloben človek, ki hodi s kljubovalnimi usti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, '§ mežika s svojimi očmi, govori s svojimi stopali, uči s svojimi prsti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, '§ Kljubovalnost je v njegovem srcu, nenehno snuje vragolijo, seje neenotnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Zato bo njegova katastrofa prišla nenadoma, nenadoma bo zlomljen brez zdravila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Teh šest stvari sovraži Gospod; da, sedem mu jih je ogabnost:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'ponosen pogled, lažniv jezik in roke, ki prelijejo nedolžno kri,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'srce, ki snuje zlobne zamisli, stopala, ki so nagla v teku k vragoliji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'kriva priča, ki govori laži in kdor seje neenotnost med brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Moj sin, drži se zapovedi svojega očeta in ne zapusti postave svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Nenehno si ju privezuj na svoje srce in zavezuj si ju okoli svojega vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kadar greš, te bo vodila, kadar spiš, te bo obvarovala in kadar se zbudiš, se bo pogovarjala s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Kajti zapoved je svetilka; in postava je svetloba in graje poučevanja so pot življenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'da te obvarujejo pred zlo žensko, pred priliznjenim jezikom tuje ženske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'V svojem srcu si ne požêli njene lepote niti naj te ona ne ujame s svojimi vekami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, '§ Kajti s pomočjo vlačugarske ženske je mož priveden do koščka kruha in zakonolomka bo lovila dragoceno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Mar lahko človek vzame ogenj v svoje naročje in njegova oblačila ne bodo ožgana?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Mar lahko kdo hodi po žerjavici in njegova stopala ne bodo opečena?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tako kdor hodi k ženi svojega soseda, kdorkoli se je dotika, ne bo nedolžen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Ljudje ne prezirajo tatu, če krade, da zadovolji svojo dušo, kadar je lačen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'toda če je najden, naj povrne sedemkratno; izročil bo vse imetje svoje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Toda kdorkoli z žensko zagreši zakonolomstvo, nima razumevanja. Tisti, ki to počne, uničuje svojo lastno dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Prejel bo rano in nečast in njegova graja ne bo izbrisana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Kajti ljubosumje je bes moškega, zato ne bo prizanesel na dan maščevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ne bo se ozrl na kakršnokoli odkupnino niti ne bo zadovoljen počival, čeprav mu daješ mnogo daril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Moj sin, drži se mojih besed in moje zapovedi shrani s seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Ohranjaj moje zapovedi in živi in mojo postavo [ohranjaj] kakor punčico svojega očesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Priveži si jih na svoje prste, zapiši jih na tablo svojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Modrosti reci: »Ti si moja sestra« in razumevanje imenuj svojo sorodnico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'da te lahko obvarujejo pred tujo žensko, pred tujko, ki laska s svojimi besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Kajti pri oknu svoje hiše sem pogledal skozi oknico');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'in zagledal med preprostimi, razpoznal sem med mladostniki mladeniča brez razumevanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'ki gre po ulici v bližini njenega vogala in šel je [na] pot k njeni hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'v poltemi, zvečer, v črnini temne noči');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'in glej, tam ga je srečala ženska z okrasom pocestnice in premetenega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, '(Ona je glasna in trmoglava, njena stopala ne ostanejo v njeni hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'sedaj je zunaj, sedaj na ulicah in preži na vsakem vogalu.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Tako ga je ujela in poljubila in mu s predrznim obrazom rekla:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '»S seboj imam mirovne daritve, danes sem izpolnila svoje zaobljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Zato sem prišla, da se srečam s teboj, da marljivo iščem tvoj obraz in sem te našla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Svojo posteljo sem odela s pokrivali iz tapiserije, z rezbarskimi deli, s tankim lanenim platnom iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Svojo posteljo sem odišavila z miro, alojo in cimetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, '§ Pridi, vzemiva si najino nasičevanje ljubezni do jutra, tolaživa se z ljubeznimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Kajti moža ni doma, odšel je [na] dolgo potovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'S seboj je vzel torbo denarja in domov bo prišel na določen dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Z mnogo njenega vljudnega govorjenja je storila, da je popustil, z laskanjem svojih ustnic ga je prisilila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Nemudoma gre za njo, kakor gre vol v klanje ali kakor bedak h grajanju živine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, '§ dokler puščica ne prodre skozi njegova jetra, kakor ptica hiti k zanki in ne spozna, da je to za njegovo življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Zato mi sedaj prisluhnite, oh vi otroci in bodite pozorni na besede iz mojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Naj se tvoje srce na nagne k njenim potem, ne zaidi na njene steze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, '§ Kajti ona je vrgla dol mnogo ranjenih, da, mnogo močnih mož je bilo umorjenih po njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, '§ Njena hiša je pot v pekel, spuščajoča se k celicam smrti....');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Mar ne kliče modrost? In razumevanje [ne] dviguje svojega glasu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Stoji na vrhu visokih krajev, ob poti, na krajih steza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Kliče pri velikih vratih, pri mestnem vhodu, pri vstopanju, pri vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Vam, oh možje, kličem in moj glas je k človeškim sinovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Oh vi preprosti, razumite modrost, in vi bedaki, bodite razumevajočega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Poslušajte, kajti govorila bom o odličnih stvareh in odpiranje mojih ustnic bodo prave stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Kajti moja usta bodo govorila resnico, zlobnost pa je mojim ustnicam ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Vse besede mojih ust so v pravičnosti, v njih ni ničesar kljubovalnega ali sprevrženega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'So čisto preproste tistemu, ki razume in pravilne tem, ki najdejo spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Sprejmite moje poučevanje in ne srebra in spoznanje raje kakor izbrano zlato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, '§ Kajti modrost je boljša kakor rubini in vse stvari, ki se lahko želijo, se ne morejo primerjati k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Jaz, modrost, prebivam z razumnostjo, odkrivam spoznanje razumnih domiselnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, '§ Gospodov strah je sovražiti zlo. Ponos, aroganco, zlobno pot in kljubovalna usta sovražim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, '§ Nasvet je moj in zdrava modrost. Jaz sem razumevanje, jaz imam moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Po meni kraljujejo kralji in princi odrejajo pravico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Po meni vladajo princi in plemiči, celó vsi zemeljski sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ljubim tiste, ki me ljubijo in tisti, ki me iščejo zgodaj, me bodo našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bogastva in čast sta z menoj; da, trajna bogastva in pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, '§ Moj sad je boljši kakor zlato; da, kakor čisto zlato in moje poplačilo kakor izbrano srebro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, '§ Vodim po poti pravičnosti, po sredi stezá sodbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, '§ da lahko povzročim tistim, ki me ljubijo, da podedujejo imetje in jaz bom napolnila njihove zaklade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Gospod me je imel v lasti od začetka svoje poti, pred svojimi deli od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Bila sem postavljena od večnosti, od začetka ali preden je bila zemlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ko tam ni bilo globin, sem bila rojena, ko tam ni bilo studencev, obilnih z vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Preden so bile gore nameščene, pred hribi sem bila rojena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, '§ medtem ko še ni naredil zemlje niti polj niti najvišjega dela iz prahu sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, '§ Ko je pripravljal nebo, sem bila tam, ko je postavil obod na obličju globine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'ko je zgoraj osnoval oblake, ko je utrdil studence globin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'ko je morju dal svoj odlok, da vode ne bodo prekoračile njegove zapovedi, ko je določil temelje zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'tedaj sem bila poleg njega, kakor nekdo vzgojen z njim in dnevno sem bila njegovo veselje, vedno radostna pred njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'radostna na naseljivem delu njegovega zemeljskega [kroga] in moja veselja so bila s človeškimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Zdaj mi torej prisluhnite, oh vi otroci, kajti blagoslovljeni so tisti, ki se drže mojih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Poslušajte poučevanje, bodite modri in tega ne zavrnite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Blagoslovljen je človek, ki me posluša, ki dnevno bedi pri mojih velikih vratih, ki čaka pri podbojih mojih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Kajti kdor me najde, najde življenje in dosegel bo naklonjenost od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, '§ Toda kdor zoper mene greši, škodi svoji lastni duši. Vsi tisti, ki me sovražijo, ljubijo smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Modrost je zgradila svojo hišo, izklesala je svojih sedem stebrov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'pobila je svoje živali, zmešala je svoje vino, prav tako je pripravila svojo mizo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Poslala je svoje dekle. Na najvišjih krajih mesta kliče:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '»Kdorkoli je preprost, naj vstopi sèm.« Glede tistega, ki hoče razumevanje, mu reče:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '»Pridi, jej od mojega kruha in pij od vina, ki sem ga namešala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, '§ Zapusti nespametne in živi in pojdi po poti razumevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, '§ Kdor graja posmehljivca, samemu sebi pridobiva sramoto in kdor ošteje zlobnega človeka, sebi pridobiva madež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne grajaj posmehljivca, da te ne zasovraži. Oštej modrega človeka, in te bo ljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Daj poučevanje modremu človeku in bo še modrejši, pouči pravičnega človeka in pomnožil se bo v znanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, '§ Strah Gospodov je začetek modrosti, in spoznanje svetega je razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Kajti po meni bodo tvoji dnevi pomnoženi in leta tvojega življenja ti bodo narasla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Če si moder, boš moder zase, toda če se posmehuješ, boš to sam trpel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Nespametna ženska je kričava. Naivna je in ničesar ne ve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Kajti sedi pri vratih svoje hiše, na sedežu, na visokih krajih mesta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, '§ da kliče mimoidoče, ki gredo naravnost na svojih poteh:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '»Kdorkoli je preprost, naj vstopi sèm.« Glede tistega, ki hoče razumevanje, mu pravi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '»Ukradene vode so sladke in kruh, pojeden na skrivnem, je prijeten.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, '§ Toda ta ne spozna, da so tam mrtvi in da so njeni gostje v globinah pekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salomonovi pregovori. Moder sin dela očeta srečnega, toda nespameten sin je potrtost svoji materi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Zakladi zlobnosti nič ne koristijo, toda pravičnost osvobaja pred smrtjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, '§ Gospod ne bo trpel, da duša pravičnega izstrada, toda odvrže imetje zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Reven postaja tisti, ki ravna s počasno roko, toda roka marljivega dela bogastvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kdor zbira poleti, je moder sin, toda kdor ob žetvi spi, je sin, ki povzroča sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Blagoslovi so na glavi pravičnega, toda nasilje pokriva usta zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Spomin na pravičnega je blagoslovljen, toda ime zlobnega bo strohnelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Moder v srcu bo sprejel zapovedi, toda žlobudrav bedak bo padel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kdor hodi pošteno, hodi varno; toda kdor svoje poti izkrivlja, bo razpoznan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kdor zavija z očesom, povzroča bridkost, toda žlobudrav bedak bo padel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Usta pravičnega človeka so izvir življenja, toda nasilje pokriva usta zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Sovraštvo razvnema prepire, toda ljubezen pokriva vse grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Na ustnicah tistega, ki ima razumevanje, je najti modrost, toda palica je za hrbet tistega, ki je brez razumevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Modri ljudje kopičijo spoznanje, toda usta nespametnega so blizu uničenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, '§ Bogataševo premoženje je njegovo močno mesto. Uničenje revnih je njihova revščina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Trud pravičnega se nagiba k življenju, sad zlobnega h grehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Tisti, ki se drži poučevanja, je na poti življenja, toda kdor odklanja opomin, se moti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, '§ Kdor z lažnivimi ustnicami skriva sovraštvo in kdor izreka obrekovanje, je bedak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'V množici besed ne manjka greha, toda kdor zadržuje svoje ustnice, je moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Jezik pravičnega je kakor izbrano srebro, srce zlobnega je malo vredno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Ustnice pravičnega hranijo mnoge, toda bedaki umrejo zaradi pomanjkanja modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, '§ Gospodov blagoslov, ta bogatí in s tem on ne dodaja nobene bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'To je kakor zabava bedaku, da počne vragolijo, toda razumevajoč človek ima modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Strah zlobnega bo prišel nanj, toda želja pravičnega bo zagotovljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Kakor mine vrtinčast veter, tako zlobnega ni več, toda pravični je večen temelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Kakor kis zobem in kakor dim očem, tako je lenuh tistim, ki ga pošljejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Strah Gospodov podaljšuje dneve, toda leta zlobnega bodo skrajšana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Upanje pravičnega bo veselje, toda pričakovanje zlobnega bo propadlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Gospodova pot je moč iskrenemu, toda uničenje bo za delavce krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, '§ Pravični ne bo nikoli odstranjen, toda zloben ne bo poselil zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Usta pravičnega prinašajo modrost, toda kljubovalen jezik bo odrezan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Ustnice pravičnega vedo, kaj je sprejemljivo, toda usta zlobnega govorijo kljubovalnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Netočna tehtnica je ogabnost Gospodu, toda pravično tehtanje je njegovo veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, '§ Ko prihaja ponos, zatem prihaja sramota, toda s ponižnim je modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, '§ Neokrnjenost iskrenih jih bo usmerjala, toda perverznost prestopnikov jih bo uničila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Bogastva ne koristijo na dan besa, toda pravičnost osvobaja pred smrtjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Pravičnost popolnega bo vodila njegovo pot, toda zlobni bo padel po svoji lastni zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Pravičnost iskrenega jih bo osvobodila, toda prestopniki bodo prevarani v svoji lastni porednosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Kadar zloben človek umre, bo njegovo pričakovanje propadlo, in upanje nepravičnih ljudi propada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, '§ Pravični je osvobojen iz stiske, zlobni pa prihaja namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Hinavec s svojimi usti uničuje svojega bližnjega, toda zaradi spoznanja bo pravični osvobojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Kadar gre dobro pravičnim, se mesto razveseljuje; kadar zlobni propadajo, pa je vriskanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Z blagoslovom iskrenega je mesto povišano, toda premagano je z usti zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Kdor je brez modrosti, prezira svojega bližnjega, toda razumevajoč človek ohranja svoj mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Tožljivec razodeva skrivnosti, toda kdor je zvestega duha, prikriva zadevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Kjer ni nasveta, ljudstvo pada, toda v množici svetovalcev je varnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Kdor je pôrok za tujca, se bo kesal za to in kdor sovraži poroštvo, je zanesljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Milostljiva ženska ohranja čast, močni ljudje ohranjajo bogastva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, '§ Usmiljen človek dela dobro svoji lastni duši, toda kdor je krut, nadleguje svoje lastno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Zlobnež počne varljivo delo, toda tistemu, ki seje pravičnost, bo plačilo zanesljivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Kakor se pravičnost nagiba k življenju, tako kdor zasleduje zlo, to zasleduje do svoje lastne smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Tisti, ki so kljubovalnega srca, so ogabnost Gospodu, toda tisti, ki so na svoji poti iskreni, so njegovo veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, '§ Čeprav se roka rokuje z roko, zlobni ne bodo nekaznovani, toda seme pravičnih bo osvobojeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Kakor dragocenost iz zlata v svinjskem rilcu, tako je lepa ženska brez preudarnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Želja pravičnega je samo dobro, toda pričakovanje zlobnega je bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Tam je, ki razsipa in še povečuje in tam je, ki zadržuje več, kot je primerno, toda to nagiba k revščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Velikodušna duša bo postala premožna in kdor napaja, bo tudi sam napojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kdor zadržuje žito, ga bo ljudstvo preklelo, toda blagoslov bo na glavi tistega, ki ga prodaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kdor marljivo išče dobro, dosega naklonjenost, toda kdor išče vragolijo, bo ta prišla k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kdor zaupa v svoja bogastva, bo padel, toda pravični bo cvetel kakor mladika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kdor nadleguje svojo lastno hišo, bo podedoval veter in bedak bo služabnik modremu v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Sad pravičnega je drevo življenja in kdor pridobiva duše, je moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Glej, pravični bo poplačan v zemlji, koliko bolj zlobni in grešnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kdorkoli ljubi poučevanje, ljubi spoznanje, toda kdor sovraži opomin, je brutalen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, '§ Dober človek doseže naklonjenost od Gospoda, toda človek zlobnih naklepov bo obsojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Človek ne bo uveljavljen z zlobnostjo, toda korenina pravičnih ne bo omajana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Vrla ženska je krona svojemu soprogu, toda tista, ki sramoti, je gniloba v njegovih kosteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, '§ Misli pravičnih so pravilne, toda nasveti zlobnih so prevara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Besede zlobnih so prežanje v zasedi na kri, toda usta iskrenih jih bodo osvobodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Zlobni so premagani in jih ni, toda hiša pravičnega bo stala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Človek bo priporočen glede na svojo modrost, toda kdor je sprevrženega srca, bo preziran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, '§ Kdor je preziran, pa ima služabnika, je boljši kakor tisti, ki časti samega sebe, pa nima kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Pravičen človek se ozira na življenje svoje živali, toda nežna usmiljenja zlobnih so kruta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kdor obdeluje svojo zemljo, bo nasičen s kruhom, toda kdor sledi praznim osebam, je brez razumevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Zlobni želi mrežo zlobnih ljudi, toda korenina pravičnih rojeva sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Zlobni je ujet s prestopkom svojih ustnic, toda pravični bo prišel iz stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Človek bo nasičen z dobrim po sadu svojih ust in poplačilo človeških rok mu bo vrnjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Bedakova pot je v njegovih lastnih očeh pravilna, toda kdor prisluhne nasvetu, je moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Bedakov bes je takoj znan, toda razsoden človek prikriva sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kdor govori resnico, naznanja pravičnost, toda kriva priča prevaro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Tam je, ki govori kakor prebadanje z mečem, toda jezik modrega je zdravje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Ustnica resnice bo utrjena za vedno, toda lažniv jezik je samo za trenutek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Prevara je v srcu tistih, ki si domišljajo zlo, toda svetovalcem miru je radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nobeno zlo se ne bo zgodilo pravičnemu, toda zlobni bodo napolnjeni z vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Lažnive ustnice so ogabnost Gospodu, toda tisti, ki se vedejo odkrito, so njegovo veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Razsoden človek prikriva spoznanje, toda srce bedakov razglaša nespametnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Roka marljivega bo vladala, toda leni bo podvržen plačevanju davka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Potrtost v človekovem srcu ga dela sklonjenega, toda dobra beseda ga dela veselega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, '§ Pravični je odličnejši od svojega soseda, toda pot zlobnih jih zapeljuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, '§ Len človek ne peče tega, kar je ujel na lovu, toda imetje marljivega človeka je dragoceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na poti pravičnosti je življenje in na tej poti ni smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Moder sin posluša poučevanje svojega očeta, toda posmehljivec ne posluša oštevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Človek bo jedel dobro po sadu svojih ust, toda duša prestopnikov bo jedla nasilje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kdor varuje svoja usta, varuje svoje življenje, toda kdor široko odpira svoje ustnice, bo imel uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, '§ Lenuhova duša želi, pa nima ničesar, toda duša marljivega bo postala obilna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Pravičen človek sovraži laganje, toda zloben človek je gnusen in prihaja v sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Pravičnost varuje tistega, ki je na poti iskren, toda zlobnost ruši grešnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Tam je, ki se dela bogatega, vendar nima ničesar, tam je, ki se dela ubogega, vendar ima velika bogastva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Odkupnina človekovega življenja so njegova bogastva, toda ubogi ne slišijo oštevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Svetloba pravičnega razveseljuje, toda svetilka zlobnega bo ugasnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, '§ Samo s ponosom pride spor, toda z dobrim svetovanjem je modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, '§ Premoženje, pridobljeno z ničevostjo, bo zmanjšano, toda kdor zbira s trudom, ga bo povečal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, '§ Upanje, ki se prelaga, dela srce bolno, toda ko prihaja želja, je to drevo življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, '§ Kdorkoli prezira besedo, bo uničen, toda kdor se boji zapovedi, bo nagrajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Postava modrega je studenec življenja, da odide od zank smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Dobro razumevanje daje naklonjenost, toda pot prestopnikov je težka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, '§ Vsak razsodni človek se ukvarja s spoznanjem, toda bedak izpostavlja svojo neumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Zloben poslanec pada v vragolijo, toda zvest predstavnik je zdravje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Revščina in sramota bosta tistemu, ki odklanja poučevanje, toda kdor upošteva opomin, bo spoštovan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Izpolnjena želja je duši sladka, toda bedakom je to ogabnost, da odidejo od zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kdor hodi z modrimi ljudmi, bo moder, toda skupina bedakov bo uničena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, '§ Zlo preganja grešnike, toda dobro bo pravičnim poplačano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dober človek zapušča dediščino otrokom svojih otrok, premoženje grešnika pa je prihranjeno za pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, '§ Mnogo hrane je v oranju zemlje ubogih, toda tam je, kar je uničeno zaradi pomanjkanja sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kdor prizanaša svoji šibi, sovraži svojega sina, toda kdor ga ljubi, ga zgodaj kara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Pravični jé do zadovoljitve svoje duše, toda trebuh zlobnega bo čutil pomanjkanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Vsaka modra ženska gradi svojo hišo, toda nespametna jo ruši s svojimi rokami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kdor hodi v svoji poštenosti, se boji Gospoda, toda kdor je sprevržen na svojih poteh, ga prezira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'V ustih nespametnih je šiba ponosa, toda ustnice modrih jih bodo varovale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Kjer ni volov, so jasli čiste, toda mnogo povečanje je z volovsko močjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Zvesta priča ne bo lagala, toda kriva priča bo izrekala laži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Posmehljivec išče modrost, pa je ne najde, toda spoznanje je lahko tistemu, ki razume.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Pojdi izpred prisotnosti nespametnega človeka, kadar v njem ne zaznavaš ustnic spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Modrost razsodnega je razumeti svojo pot, toda neumnost bedakov je prevara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, '§ Bedaki se posmehujejo ob grehu, toda med pravičnimi je naklonjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, '§ Srce pozna svojo lastno grenkobo in tujec se ne vmešava s svojo radostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Hiša zlobnega bo zrušena, toda šotor iskrenega bo cvetel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Obstaja pot, ki se zdi človeku prava, toda njen konec so poti smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, '§ Celo v smehu je srce žalostno in konec tega veselja je potrtost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Odpadnik v srcu bo nasičen s svojimi lastnimi potmi, dober človek pa bo zadovoljen sam od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Naivnež verjame vsaki besedi, toda razsoden človek dobro pazi na svojo hojo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Moder človek se boji in se oddaljuje od zla, toda bedak besni in je samozavesten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, '§ Kdor je hitro jezen, se vede nespametno, človek zlobnih naklepov pa je osovražen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Naivneži podedujejo neumnost, toda razsodni so kronani s spoznanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Zlobni se priklanjajo pred dobrimi in zlobni pri velikih vratih pravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Ubogi je osovražen celo od svojega lastnega soseda, toda bogati ima mnogo prijateljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, '§ Kdor prezira svojega soseda, greši, toda kdor ima usmiljenje do ubogega, je srečen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, '§ Mar se ne motijo tisti, ki snujejo zlo? Toda usmiljenje in resnica bosta tem, ki snujejo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'V vsem trudu je korist, toda govorjenje ustnic se nagiba samo k ubožnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Krona modrih so njihova bogastva, toda nespametnost bedakov je neumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, '§ Poštena priča osvobaja duše, toda varljiva priča govori laži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'V strahu Gospodovem je močno zaupanje in njegovi otroci bodo imeli kraj zatočišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Strah Gospodov je studenec življenja, da se odide od zank smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'V množici ljudstva je kraljeva čast, toda v pomanjkanju ljudstva je uničenje princa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Kdor je počasen za bes, ima veliko razumevanja, toda kdor je naglega duha, povišuje neumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Zdravo srce je življenje mesu, toda zavist gniloba kostem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kdor zatira ubogega, graja njegovega Stvarnika, toda kdor ga časti, ima usmiljenje do ubogih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, '§ Zlobni je v svoji zlobnosti odpeljan proč, toda pravični ima upanje v svoji smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, '§ Modrost počiva v srcu tistega, ki ima razumevanje, toda tisti, ki je v sredi bedakov, je spoznan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Pravičnost povišuje narod, toda greh je očitek kateremukoli ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Kraljeva naklonjenost je k modremu služabniku, toda njegov bes je zoper tistega, ki povzroča sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Mil odgovor bes obrača stran, toda boleče besede razvnamejo jezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Jezik modrega pravilno uporablja spoznanje, toda usta bedakov izlivajo nespametnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Gospodove oči so na vsakem kraju, opazujejo zlo in dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Zdrav jezik je drevo življenja, toda perverznost v njem je vrzel v duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Bedak prezira poučevanje svojega očeta, toda kdor upošteva opomin, je razsoden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, '§ V hiši pravičnega je velik zaklad, toda v poplačilih zlobnega je težava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, '§ Ustnice modrega razpršujejo znanje, toda srce nespametnega ne dela tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Klavna daritev zlobnega je Gospodu ogabnost, toda molitev iskrenega je njegovo veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Pot zlobnega je Gospodu ogabnost, toda ljubi tistega, ki sledi pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, '§ Grajanje je nadležno tistemu, ki zapušča pot, in kdor sovraži opomin, bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, '§ Pekel in uničenje sta pred Gospodom, koliko bolj potem srca človeških otrok?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Posmehljivec nima rad tistega, ki ga graja niti ne bo šel k modremu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Veselo srce dela vedro obličje, toda s srčno bridkostjo je duh zlomljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Srce tistega, ki ima razumevanje, išče spoznanje, toda usta bedakov se hranijo na nespametnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Vsi dnevi prizadetega so zli, toda kdor je veselega srca ima nenehno praznovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, '§ Bolje je malo s strahom Gospodovim, kakor velik zaklad in težave s tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Boljša je zelenjavna večerja, kjer je ljubezen, kakor tolst vol in s tem sovraštvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Srdit človek razvnema prepir, toda kdor je počasen za jezo, pomirja prepir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Pot lenega človeka je kakor trnova ograja, toda pot pravičnega je narejena preprosto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Moder sin razveseljuje očeta, toda nespameten človek prezira svojo mater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Neumnost je radost tistemu, ki je oropan modrosti, toda razumevajoč človek živi pošteno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Brez nasveta so nameni razočarani, toda v množici svetovalcev so uveljavljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Človek ima radost z odgovorom svojih ust in beseda, izgovorjena v pravšnjem obdobju, kako dobro je to!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Pot življenja je modremu zgoraj, da lahko odide od pekla spodaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Gospod bo uničil hišo ponosnega, toda uveljavil bo vdovino mejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Misli zlobnega so Gospodu ogabnost, toda besede čistega so prijetne besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, '§ Kdor je pohlepen dobička, nadleguje svojo lastno hišo, toda kdor sovraži darila, bo živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Srce pravičnega razmišlja, da odgovori, toda usta zlobnega izlivajo zle stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Gospod je daleč od zlobnega, toda sliši molitev pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Svetloba oči razveseljuje srce in dober glas dela kosti debele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Uho, ki posluša opomin življenja, ostaja med modrimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kdor odklanja poučevanje, prezira svojo lastno dušo, toda kdor posluša opomin, pridobiva razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Strah Gospodov je poučevanje modrosti in pred častjo je ponižnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, '§ Priprave srca v človeku in odgovor z jezika sta od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Vse človekove poti so čiste v njegovih lastnih očeh, toda Gospod tehta duhove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Svoja dela izroči Gospodu in tvoje misli bodo uspele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, '§ Gospod je vse stvari naredil zase, da, celo zlobne za dan zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, '§ Kdorkoli, ki je v srcu ponosen, je ogabnost Gospodu. Čeprav se roka rokuje z roko, on ne bo nekaznovan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, '§ Z usmiljenjem in resnico je krivičnost očiščena in s strahom pred Gospodom ljudje odidejo od zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Kadar človekove poti ugajajo Gospodu, on celo njegove sovražnike pripravi, da so v miru z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Boljše je malo s pravičnostjo, kakor velika poplačila brez pravice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Človekovo srce snuje svojo pot, toda Gospod usmerja njegove korake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Božanska razsodba je na kraljevih ustnicah, njegova usta ne grešijo na sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Pravična utež in tehtnica sta Gospodovi, vse uteži iz torbe so njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Zagrešiti zlobnost je kraljem ogabnost, kajti prestol je utrjen s pravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Pravične ustnice so kraljem veselje in ljubijo tistega, ki govori resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kraljev bes je kakor poslanci smrti, toda moder človek ga bo pomiril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'V svetlobi kraljevega obličja je življenje in njegova naklonjenost je kakor oblak poznega dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Kako mnogo bolje je pridobiti modrost kakor zlato! In toliko bolje izbrati pridobivanje razumevanja kakor srebro!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Glavna cesta iskrenega je, da odide od zla, kdor varuje svojo pot, ohranja svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Ponos gre pred uničenjem in ošaben duh pred padcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Bolje je biti ponižnega duha s ponižnimi, kakor deliti plen s ponosnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kdor modro ravna z zadevo, bo našel dobro in kdorkoli zaupa v Gospoda, je srečen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Moder v srcu bo imenovan razsoden in ljubkost ustnic povečuje znanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Razumevanje je vrelec življenja tistemu, ki ga ima, toda poučevanje bedakov je neumnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Srce modrega poučuje njegova usta in dodaja učenje njegovim ustnicam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Prijetne besede so kakor satovje, sladke duši in zdravje kostem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Je pot, ki se zdi človeku pravilna, toda njen konec so poti smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Kdor se trudi, se trudi zase, kajti njegova usta to od njega nujno potrebujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Brezbožen človek koplje zlo in na njegovih ustnicah je kakor goreč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Kljubovalen človek seje prepir in opravljivec razdvaja glavne prijatelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Nasilnež privablja svojega soseda in ga vodi na pot, ki ni dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Zapira svoje oči, da si izmišlja kljubovalne reči, premikanje njegovih ustnic prinaša zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Osivela glava je krona slave, če je ta najdena na poti pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Kdor je počasen za jezo, je boljši kakor mogočen in kdor vlada svojemu duhu kakor tisti, ki zavzema mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Žreb je vržen v naročje, toda njegova celotna razporeditev je od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Boljši je suh košček in z njim spokojnost, kakor hiša polna klavnih daritev s prepirom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Moder služabnik bo imel vladarstvo nad sinom, ki povzroča sramoto in bo imel delež dediščine med brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Talilni lonec je za srebro in talilna peč za zlato, toda Gospod preizkuša srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Zloben storilec daje prednost nepravim ustnicam in lažnivec pazljivo prisluhne nespodobnemu jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kdorkoli zasmehuje ubogega, graja njegovega Stvarnika in kdor je ob katastrofah vesel, ne bo nekaznovan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Otrok otroci so krona starcem in slava otrok so njihovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Odličen govor se ne spodobi bedaku, veliko manj lažnive ustnice princu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Darilo je kakor dragocen kamen v očeh tistega, ki ga ima, kamor ga obrača, to uspeva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kdor taji prestopek, išče ljubezni, toda kdor ponavlja zadevo, ločuje prave prijatelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Opomin bolj prodira v modrega kakor sto udarcev z bičem v bedaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Hudoben človek išče samo upor, zato bo zoper njega poslan krut poslanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Naj medvedka, oropana svojih mladičev, sreča človeka, raje kakor bedak v svoji neumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kdorkoli nagrajuje zlo za dobro, se zlo ne bo ločilo od njegove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Začetek prepira je kakor kadar nekdo izpušča vodo, zato prenehaj s sporom, preden se vmešaš vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kdor opravičuje zlobnega in kdor obsoja pravičnega, celo oba sta Gospodu ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, '§ Zakaj je denarna vsota v bedakovi roki, da pridobi modrost, glede na to, da on nima srca za to?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Prijatelj ljubi ob vseh časih in brat je rojen za stisko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Človek brez razumevanja udarja v roke in postaja pôrok v prisotnosti svojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kdor ljubi prestopek, ta ljubi prepir in kdor povišuje svoja velika vrata, išče uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Kdor ima kljubovalno srce, ne najde dobrega in kdor ima sprevržen jezik, pada v vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kdor zaplodi bedaka, to počne v svojo bridkost in oče bedaka nima radosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Veselo srce dela dobro, podobno kot zdravilo, toda zlomljen duh suši kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Zloben človek iz naročja izvleče darilo, da izkrivlja poti sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Modrost je pred tistim, ki ima razumevanje, toda oči bedaka so na koncih zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Nespameten sin je žalost svojemu očetu in grenkoba njej, ki ga je rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Tudi kaznovati pravičnega ni dobro niti udariti prince zaradi nepristranskosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kdor ima spoznanje, prizanaša svojim besedam in razumevajoč človek je iz odličnega duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Celo bedak, ko molči, velja kot moder in kdor zapira svoje ustnice, je cenjen kot razumevajoč človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, '§ Preko želje človek, ki je samega sebe oddvojil, išče in se vmešava z vso modrostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, '§ Bedak nima veselja v razumevanju, temveč da njegovo srce lahko odkrije samo sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Kadar prihaja zlobni, potem prihaja tudi zaničevanje in s sramoto graja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Besede iz človekovih ust so kakor globoke vode in vrelec modrosti kakor tekoč potok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ni dobro sprejeti osebo zlobnega, da pravičnega zruši na sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Bedakove ustnice vstopajo v spor in njegova usta kličejo za udarci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Bedakova usta so njegovo uničenje in njegove ustnice so zanka njegovi duši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Besede tožljivca so kakor rane in gredo navzdol v najnotranjejše dele trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Tudi tisti, ki je len v svojem delu, je brat tistemu, ki je velik kvarilec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Gospodovo ime je močan stolp, pravični priteče vanj in je varen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, '§ Bogataševo premoženje je njegovo močno mesto in kakor visoko obzidje v njegovi lastni domišljavosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Pred uničenjem je človekovo srce ošabno in pred častjo je ponižnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kdor odgovarja zadevo, preden jo sliši, mu je to neumnost in sramota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Človekov duh bo podpiral njegovo šibkost, toda kdo lahko prenaša ranjenega duha?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Srce razsodnega pridobiva spoznanje, uho modrega pa išče spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Človekovo darilo zanj pripravlja prostor in ga prinaša pred velike ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Kdor je prvi v svoji lastni zadevi, je videti pravičen, toda prihaja njegov sosed in ga preiskuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Žreb povzroča sporom, da se ustavijo in razdeljuje med mogočnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Užaljenega brata je težje pridobiti kakor močno mesto in njihovi spori so podobni grajskim zapahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Človekov trebuh bo potešen s sadom svojih ust in nasičen bo z donosom svojih ustnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Smrt in življenje sta v oblasti jezika in tisti, ki ga ljubijo, bodo jedli od njegovega sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kdorkoli najde ženo, najde dobro stvar in dosega naklonjenost od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Ubogi uporablja rotenja, toda bogataš odgovarja surovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Človek, ki ima prijatelje, se mora kazati prijatelja in obstaja prijatelj, ki se drži bližje kakor brat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Boljši je ubogi, ki hodi v svoji neokrnjenosti, kakor kdor je sprevržen v svojih ustnicah in je bedak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Tudi, da bi bila duša brez spoznanja, to ni dobro in kdor hiti s svojimi stopali, greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Človekova nespametnost izkrivlja njegovo pot in njegovo srce se razburja zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Premoženje dela mnoge prijatelje, toda reven je ločen od svojega soseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Kriva priča ne bo nekaznovana in kdor govori laži, ne bo pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Mnogi bodo milo prosili naklonjenosti od princev in vsak človek je prijatelj tistemu, ki daje darila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Ubogega sovražijo vsi njegovi bratje, koliko bolj gredo njegovi prijatelji daleč od njega? Zasleduje jih z besedami, vendar mu manjkajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kdor pridobiva modrost, ljubi svojo lastno dušo, kdor ohranja razumevanje, bo našel dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Kriva priča ne bo nekaznovana in kdor govori laži, bo propadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Veselje ni spodobno za bedaka, veliko manj za služabnika, da vlada nad princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Človekova preudarnost odlaša njegovo jezo in to je njegova slava, da gre čez prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kraljev bes je kakor rjovenje leva, toda njegova naklonjenost je kakor rosa na travo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Nespameten sin je katastrofa svojega očeta in ženini spori so nenehno kapljanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Hiša in bogastva so dediščina od očetov, razsodna žena pa je od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenoba meče v globoko spanje, brezdelna duša pa bo trpela lakoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kdor varuje zapoved, varuje svojo lastno dušo, toda kdor prezira njegove poti, bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kdor ima do revnega sočutje, posoja Gospodu in kar je dal, mu bo on poplačal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Karaj svojega sina, dokler je upanje in naj tvoja duša ne prizanaša zaradi njegovega joka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Človek velikega besa bo trpel kaznovanje, kajti če ga osvobodiš, boš vendarle moral to ponovno storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Prisluhni nasvetu in sprejmi poučevanje, da boš lahko moder v svojem zadnjem koncu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Mnogo naklepov je v človekovem srcu, vendarle [je] Gospodova namera, ki bo obstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Človekova želja je njegova prijaznost in reven človek je boljši kakor lažnivec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Strah Gospodov se nagiba k življenju in kdor ga ima, bo ostal nasičen, ne bo obiskan z zlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Len človek skriva svojo roko v svojem naročju in jo bo komaj ponovno ponesel k svojim ustom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Udari posmehljivca in preprosti se bo čuval in grajaj nekoga, ki ima razumevanje in bo razumel spoznanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Kdor slabi svojega očeta in preganja svojo mater, je sin, ki povzroča sramoto in prinaša grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Nehaj, moj sin, poslušati pouk, ki povzroča, da zaideš od besed spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Brezbožna priča zasmehuje sodbo in usta zlobnega požirajo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Sodbe so pripravljene za posmehljivce in udarci z bičem za hrbte bedakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Vino je zasmehovalec, močna pijača je huda in kdorkoli je s tem zaveden, ni moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Kraljev strah je kakor rjovenje leva; kdorkoli ga draži do jeze, greši zoper svojo lastno dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Za človeka je čast, da odneha od prepira, toda vsak bedak se bo vmešaval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Lenuh ne bo oral zaradi razloga mraza, zatorej bo prosil v času žetve in ničesar ne bo imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Nasvet v človekovem srcu je podoben globoki vodi, toda razumevajoč človek ga bo izvlekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, '§ Večina ljudi bo vsakemu razglašala svojo lastno dobroto, toda kdo lahko najde zvestega človeka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Pravičen človek hodi v svoji neokrnjenosti, njegovi otroci so blagoslovljeni za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Kralj, ki sedi na sodnem prestolu, s svojimi očmi vse zlo razkropi proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kdo lahko reče: »Svoje srce sem očistil, čist sem pred svojim grehom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Neenake uteži in neenake mere, oboji so Gospodu podobna ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Celo otrok je spoznan po svojih dejanjih, če so njegova dela čista in če so ta pravilna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Uho, ki sliši in oko, ki vidi, celo oboje je naredil Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Ne ljubi spanja, da ne bi prišel v revščino, odpri svoje oči in nasičen boš s kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '» To je ničvredno, to je ničvredno,« pravi kupec, toda ko je odšel svojo pot, potem se baha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Je zlato in množica rubinov, toda ustnice spoznanja so dragocen dragulj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, '§ Vzemi obleko tistega, ki je pôrok za tujca in vzemi jamstvo od njega za tujo žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Kruh prevare je sladek človeku, toda njegova usta bodo potem napolnjena z gramozom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Vsak namen je utrjen s posvetovanjem in vojskuješ se z dobrim nasvetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kdor gre naokrog kakor tožljivec, razodeva skrivnosti, zato se ne vmešavaj s tistim, ki laska s svojimi ustnicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kdorkoli preklinja svojega očeta ali svojo mater, bo njegova svetilka ugasnjena v zatemnjeno temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Dediščina je lahko v začetku naglo pridobljena, toda njen konec ne bo blagoslovljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne reci: »Jaz bom poplačal zlo,« temveč čakaj na Gospoda in rešil te bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Različne uteži so ogabnost Gospodu in varljiva tehtnica ni dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Človekovi opravki so od Gospoda, kako lahko potem človek razume svojo lastno pot?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Zanka je človeku, ki požira to, kar je sveto in da po zaobljubah dela poizvedovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Moder kralj razkropi zlobne in nadnje prinaša kolo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Človeški duh je Gospodova sveča, ki preiskuje vse notranje dele trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Usmiljenje in resnica ohranjata kralja in njegov prestol drži pokonci usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Slava mladeničev je njihova moč, lepota starcev pa je siva glava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Modrica od rane očiščuje zlo, tako storijo udarci biča notranjim delom trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kraljevo srce je v Gospodovi roki, kakor vodne reke, obrača ga kamor hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Vsaka človekova pot je pravilna v njegovih lastnih očeh, toda Gospod preudarja srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Izvajati pravičnost in sodbo je Gospodu bolj sprejemljivo kakor klavna daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Vzvišen pogled in ponosno srce in oranje zlobnih je greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Misli marljivega se nagibajo samo k obilju, toda od vsakega, ki je nagel, samo za pomanjkanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Pridobivanje zakladov z lažnivim jezikom je ničevost, premetavana sem ter tja, od tistih, ki iščejo smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Ropanje zlobnih jih bo uničilo, ker so odklonili izvrševati sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Človekova pot je kljubovalna in nenavadna, toda glede čistega, njegovo delo je pravilno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Bolje je prebivati v kotu hišne strehe kakor s prepirljivo žensko v prostrani hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Duša zlobnega želi zlo; njegov sosed v njegovih očeh ne najde naklonjenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Kadar je posmehljivec kaznovan, preprosti postane moder in kadar je moder poučen, prejema znanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Pravičen človek modro preudarja hišo zlobnega, toda Bog ruši zlobne zaradi njihove zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kdorkoli maši svoja ušesa ob joku ubogega, bo tudi sam jokal, toda ne bo uslišan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Darilo na skrivnem pomirja jezo, nagrada v naročje pa močan bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Pravičnim je veselje izvrševati sodbo, toda uničenje bo za delavce krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Človek, ki tava izven poti razumevanja, bo ostal v skupnosti mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Kdor ljubi užitek, bo revež, kdor ljubi vino in olje, ne bo bogat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Zlobni bo odkupnina za pravičnega in prestopnik za poštenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Bolje je prebivati v divjini kakor s prepirljivo in jezno žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Je zaželen zaklad in olje v prebivališču modrega, toda nespameten človek ga zapravlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kdor si prizadeva za pravičnostjo in usmiljenjem, najde življenje, pravičnost in čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, '§ Moder človek zmanjšuje mesto mogočnega in podira moč zaupanja iz tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kdorkoli zadržuje svoja usta in svoj jezik, svojo dušo zadržuje pred težavami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Ponosen in ošaben posmehljivec je njegovo ime, kdor ravna v ponosnem besu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Želja lenega, ga ubija, kajti njegove roke odklanjajo delati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'On lakomno hlepi čez ves dan, toda pravični daje in ne skopari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Klavna daritev zlobnega je ogabnost, koliko bolj, ko to prinaša z zlobnim umom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Kriva priča bo propadla, toda človek, ki posluša, nenehno govori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Zloben človek otrdi svoj obraz, toda kar se tiče poštenega, on uravnava svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ne obstaja niti modrost niti razumevanje niti namera zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Konj je pripravljen za dan bitke, toda rešitev je od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Dobro ime je bolje izbrati kakor velika bogastva in ljubečo naklonjenost raje kakor srebro in zlato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bogati in revni se srečajo skupaj; Gospod je stvarnik njih vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Razsoden človek sluti zlo in se skrije, toda naivneži gredo dalje in so kaznovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'S ponižnostjo in strahom Gospodovim so bogastva, čast in življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Trnje in zanke so na poti kljubovalnega; kdor varuje svojo dušo, bo daleč od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Vzgajaj otroka na poti, po kateri bi moral iti, in ko je star, z nje ne bo zašel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bogati vlada nad revnim in dolžnik je služabnik upniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kdor seje krivičnost, bo žel prazne reči in šiba njegove jeze bo prenehala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Kdor ima radodarno oko, bo blagoslovljen, kajti od svojega kruha daje revnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Spôdi posmehljivca in spor bo šel ven, da, spor in graja se bosta končala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kdor ljubi neoporečnost srca, bo zaradi milosti njegovih ustnic kralj njegov prijatelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Gospodove oči varujejo spoznanje in on ruši besede prestopnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Len človek pravi: »Zunaj je lev, umorjen bom na ulicah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Usta tujih žensk so globoka jama, kdor je preziran od Gospoda, bo padel vanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Nespametnost je vezana na otrokovo srce, toda svarilna šiba jo bo odgnala daleč od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, '§ Kdor stiska ubogega, da narastejo njegova bogastva in kdor daje bogatim, bosta zagotovo prišla v potrebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nagni svoje uho in prisluhni besedam modrega in svoje srce usmeri k mojemu spoznanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Kajti to je prijetna stvar, če jih varuješ znotraj sebe, poleg tega bodo pristojale na tvoje ustnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Da bo tvoje trdno upanje lahko v Gospodu, sem ti to dal spoznati ta dan, celo tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, '§ Mar ti nisem napisal odličnih stvari v nasvetih in spoznanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'da ti lahko dam spoznati zagotovost besed resnice, da boš lahko odgovoril besede resnice tistim, ki so poslani k tebi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne ropaj revnega, ker je reven, niti ne stiskaj prizadetega v velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Kajti Gospod bo zagovarjal njihovo pravdo in oplenil duše tistih, ki jih plenijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne sklepaj prijateljstva z jeznim človekom in z besnim človekom naj ne bi šel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'da se ne bi naučil njegovih poti in svoji duši pridobil zanko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne bodi nekdo izmed tistih, ki udarijo v roko ali izmed tistih, ki so pôroki za dolgove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Če nimaš ničesar za plačati, zakaj bi izpod tebe vzel tvojo posteljo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne odstranjuj starodavnega mejnika, ki so ga postavili tvoji očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Vidiš marljivega človeka v svojem poklicu? Stal bo pred kralji, ne bo stal pred navadnimi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kadar sedeš, da ješ z vladarjem, marljivo preudari, kaj je pred teboj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'in si nastavi nož na vrat, če si požrešen človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne bodi željan njegovih slaščic, kajti le-te so varljiva hrana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne trudi se biti bogat, odnehaj od svoje lastne modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Hočeš postaviti svoje oči na tisto, česar ni? Kajti bogastva sebi zagotovo delajo peruti; odletijo proč kakor orel proti nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne jej kruha tistega, ki ima zlobno oko niti si ne želi njegovih okusnih jedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, '§ kajti kakor misli v svojem srcu, takšen je: »Jej in pij,« ti pravi, toda njegovo srce ni s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Košček, ki si ga pojedel, boš izbljuval in izgubil svoje sladke besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Ne govori v ušesa bedaka, kajti preziral bo modrost tvojih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne odstrani starega mejnika in ne vstopaj na polja osirotelih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'kajti njihov odkupitelj je mogočen, zoper tebe bo zagovarjal njihovo pravdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Svoje srce usmeri k poučevanju in svoja ušesa k besedam spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ne zadržuj grajanja pred otrokom, kajti če ga udariš s šibo, ne bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Udaril ga boš s šibo, njegovo dušo pa boš rešil pred peklom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Moj sin, če bo tvoje srce modro, se bo moje srce veselilo, celo moje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Da, moja notranjost se bo veselila, ko tvoje ustnice govorijo prave besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Naj tvoje srce ne zavida grešnikom, temveč sam bodi ves dan v strahu Gospodovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Kajti zagotovo je konec, in tvoje pričakovanje ne bo odrezano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Prisluhni, ti, moj sin in bodi moder in svoje srce usmerjaj na poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne bodi med vinskimi bratci, med upornimi jedci mesa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'kajti pijanec in požeruh bosta prišla k revščini, in zaspanost bo človeka oblekla s cunjami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Prisluhni svojemu očetu, ki te je zaplodil in ne preziraj svoje matere, ko je stara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kupi resnico in je ne prodaj, tudi modrost, poučevanje in razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Oče pravičnega se bo silno veselil in kdor je zaplodil modrega otroka, bo zaradi njega imel veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Tvoj oče in tvoja mati bosta vesela in tista, ki te je nosila, se bo veselila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Moj sin, daj mi svoje srce in naj tvoje oči opazujejo moje poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Kajti vlačuga je globok jarek; in tuja ženska je tesna jama.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Prav tako preži, kakor za plenom in povečuje prestopnike med možmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kdo ima gorje? Kdo ima bridkost? Kdo ima spore? Kdo ima blebetanje? Kdo ima rane brez razloga? Kdo ima rdečino oči?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Tisti, ki se dolgo zadržujejo pri vinu; gredo, da iščejo mešano vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne glej na vino, kadar je rdeče, kadar daje svojo barvo v čaši, ko jo pravilno primakneš k sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Nazadnje udari kakor kača in piči kakor gad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Tvoje oči bodo zagledale tujo žensko in tvoje srce bo izreklo sprevržene stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Da, ti boš kakor tisti, ki se uleže na sredo morja ali kakor kdor leži na vrhu jambora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '»Udarili so me,« boš rekel in »nisem bil bolan, pretepli so me, pa tega nisem čutil, kdaj se bom prebudil? Ponovno ga bom poiskal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne bodi nevoščljiv zlobnim niti si ne želi biti z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Kajti njihovo srce razmišlja uničenje in njihove ustnice govorijo o vragoliji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Z modrostjo je hiša zgrajena in z razumevanjem je utrjena');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'in po spoznanju bodo sobe napolnjene z vsemi dragocenimi in prijetnimi bogastvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Moder človek je močan, da, človek spoznanja povečuje moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Kajti po modrem nasvetu boš vojskoval svojo vojno, in v množici svetovalcev je varnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Modrost je za bedaka previsoka, on svojih ust ne odpira v velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kdor snuje delati zlo, bo imenovan [za] pogubno osebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Misel nespametnosti je greh in posmehljivec je ogabnost ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Če na dan nadloge slabiš, je tvoja moč majhna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Če opustiš osvoboditi tiste, ki so potegnjeni v smrt in tiste, ki so pripravljeni, da bodo umorjeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'če rečeš: »Glej, tega nismo vedeli,« mar ne bo tisti, ki preudarja srce, to premislil? In tisti, ki varuje tvojo dušo, mar tega ne ve? Mar ne bo vsakemu človeku povrnil glede na njegova dela?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Moj sin, jej med, ker je dober in satovje, ki je sladko tvojemu okusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Takšno bo spoznanje modrosti tvoji duši, ko jo najdeš, potem bo nagrada in tvoje pričakovanje ne bo prekinjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Ne preži v zasedi, oh zlobni človek, zoper prebivanje pravičnega, ne pokvari njegovega počivališča,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'kajti pravičen človek pade sedemkrat in ponovno vstane, toda zlobni bo padel v vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Ne veseli se, kadar tvoj sovražnik pada in naj tvoje srce ne bo veselo, ko se spotika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'da ne bi tega videl Gospod in ga to razžali in svoj bes odvrne od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne razburjaj se zaradi hudobnih ljudi niti ne bodi nevoščljiv na zlobne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'kajti nobene nagrade ne bo za hudobnega človeka, sveča zlobnih bo ugasnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, '§ Moj sin, boj se Gospoda in kralja in nič ne imej s tistimi, ki so nagnjeni k spremembi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'kajti njihova katastrofa bo nenadoma vstala in kdo pozna njihov propad?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Tudi te stvari pripadajo modremu. Ni se dobro ozirati na osebe na sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kdor zlobnemu pravi: »Ti si pravičen,« njega bo ljudstvo preklinjalo, narodi ga bodo prezirali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'toda tistim, ki ga oštevajo, bo veselje in nadnje bo prišel dober blagoslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Vsak človek bo poljubil ustnice tistega, ki daje pravilen odgovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Pripravi svoje delo zunaj in pripravi, [da] ti ustreza na polju in potem zgradi svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne bodi brez razloga priča zoper svojega bližnjega in s svojimi ustnicami ne zavajaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne reci: »Tako mu bom storil, kakor je on storil meni. Človeku bom povrnil glede na njegovo delo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Šel sem mimo polja lenega in mimo vinograda človeka brez razumevanja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'in glej, vse je bilo preraslo s trnjem in koprive so pokrile njegovo obličje in njegov kamniti zid je bil porušen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Potem sem videl in to dobro preudaril, pogledal sem na to in prejel poučevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Še malo spanja, malo dremanja, malo prekrižanih rok za spanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'tako bo tvoja revščina prišla kakor nekdo, ki se klati in tvoja potreba kakor oborožen človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Tudi to so Salomonovi pregovori, ki so jih na čisto prepisali možje Ezekíja, Judovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Prikrivati stvar je Bogu slava, toda kraljeva čast je, da zadevo preišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Nebes v višino in zemlje v globino in srce kraljev se ne da raziskati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Odstrani žlindro od srebra in izšla bo posoda za zlatarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Odstrani zlobnega izpred kralja, pa bo njegov prestol utrjen v pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne postavi se v prisotnost kralja in ne stoj na kraju vélikih ljudi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'kajti bolje je, da ti je rečeno: »Pridi sèm gor,« kakor, da boš postavljen nižje v prisotnosti princa, ki so ga tvoje oči videle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne pojdi naglo naprej, da se pričkaš, sicer ne bi vedel kaj storiti na koncu le-tega, ko te tvoj sosed osramoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Svojo zadevo razpravljaj s svojim sosedom in skrivnosti ne razkrij drugemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'da te ne bi, kdor to sliši, osramotil in se tvoja razvpitost ne odvrne proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Beseda, primerno izgovorjena, je podobna jabolkom iz zlata na slikah iz srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Kakor uhan iz zlata in ornament iz čistega zlata, takšen je moder grajavec nad poslušnim ušesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kakor hlad snega v času žetve, tako je zvest poslanec tistim, ki so ga poslali, kajti osvežuje dušo svojih gospodarjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Kdorkoli se baha z lažnim darom, je podoben oblakom in vetru brez dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Z dolgotrajnim prizanašanjem je princ pregovorjen in blag jezik lomi kost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Si našel med? Jej [ga] toliko, kolikor ti je potrebno, da ne bi bil nasičen z njim in ga izbljuval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Svoje stopalo umakni od hiše svojega soseda, da se te ne bi naveličal in te tako zasovražil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Človek, ki prinaša krivo pričevanje zoper svojega soseda, je macola, meč in ostra puščica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Zaupanje v nezvestega človeka v času stiske je podobno zlomljenemu zobu in izpahnjenemu stopalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, '§ Kakor kdor odvzema obleko v hladnem vremenu in kakor kis na soliter, tak je kdor prepeva pesmi potrtemu srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Če je tvoj sovražnik lačen, mu daj jesti kruha in če je žejen, mu daj piti vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'kajti kopičil boš ognjeno oglje na njegovo glavo in Gospod te bo nagradil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, '§ Severni veter odnaša dež; tako jezno obličje počne obrekljivemu jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Bolje je prebivati v kotu hišne strehe, kakor s prepirljivo žensko in v prostrani hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kakor hladne vode žejni duši, takšne so dobre novice iz daljne dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Pravičen človek, padajoč pred zlobnim, je kakor skaljen studenec in pokvarjen izvir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Ni dobro jesti veliko medu. Tako za ljudi to ni slava, da iščejo svojo lastno slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Kdor nima prevlade nad svojim lastnim duhom je podoben mestu, ki je porušeno in brez zidov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Kakor sneg poleti in kakor dež ob času žetve, tako se čast ne poda bedaku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kakor ptica s potepanjem, kakor lastovka z letenjem, tako prekletstvo brez razloga ne bo prišlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Bič za konja, uzda za osla in palica za hrbet bedaka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Bedaku ne odgovori glede na njegovo neumnost, da ne bi bil tudi ti podoben njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odgovori bedaku glede na njegovo neumnost, da on ne bi bil moder v svoji lastni domišljavosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Kdor pošilja sporočilo po roki bedaka, si odseka stopala in pije škodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Nogi hromega nista enaki; takšna je prispodoba v ustih bedakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Kakor kdor poveže kamen v pračo, tak je, kdor daje čast bedaku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kakor gre trn v roko pijanca, taka je prispodoba v ustih bedakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Velik Bog, ki je ustvaril vse stvari, nagrajuje tako bedaka kakor prestopnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kakor se pes vrača k svojemu izbljuvku, tako se bedak vrača k svoji neumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Ali vidiš modrega človeka v njegovi lastni domišljavosti? Več upanja je za bedaka kakor zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Len človek pravi: » Tam je lev na poti, lev je na ulicah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Kakor se vrata obračajo na svojih tečajih, tako se leni na svoji postelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Leni skriva svojo roko v svojem naročju, žalosti ga, da jo ponovno prinese k svojim ustom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Lenuh je modrejši v svoji lastni domišljavosti, kakor sedem mož, ki lahko izkažejo razlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kdor gre mimo in se vmešava v prepir, ki mu ne pripada, je podoben tistemu, ki psa zgrabi za ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Kakor zmešan človek, ki meče kose tlečega lesa, puščice in smrt,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'tak je človek, ki zavaja svojega bližnjega in pravi: »Ali nisem na zabavi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Kjer ni nobenega lesa, tam ogenj poide. Tako, kjer ni tožljivca, prepir preneha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Kakor je oglje za vročo žerjavico in drva za ogenj, tako je prepirljiv človek za podžiganje prepira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Besede tožljivca so kakor rane in gredo navzdol v najnotranjejše dele trebuha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Goreče ustnice in zlobno srce sta podobna črepinji, pokriti s srebrovo žlindro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Kdor sovraži, prikriva s svojimi ustnicami in znotraj sebe shranjuje prevaro;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'kadar govori lepo, mu ne verjemi, kajti sedem ogabnosti je v njegovem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Čigar sovraštvo je pokrito s prevaro, bo njegova zlobnost razkazana pred celotno skupnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kdorkoli koplje jamo, bo padel vanjo, in kdor vali kamen, se bo le-ta vrnil nadenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Lažniv jezik sovraži tiste, ki so prizadeti z njim in prilizovanje ust dela propad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne bahaj se z naslednjim dnem; kajti ne veš, kakšen dan se lahko rodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Naj te hvali drug človek in ne tvoja lastna usta, tujec in ne tvoje lastne ustnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Kamen je težak in pesek ima težo, toda bedakov bes je težji kakor oba skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Bes je krut in jeza je nezaslišana, toda kdo je zmožen obstati pred zavistjo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Odprto oštevanje je boljše kakor skrita ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Zveste so rane od prijatelja, toda poljubi sovražnika so varljivi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Siti duši se satovje gabi, toda lačni duši je vsaka grenka stvar sladka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kakor ptica, ki se oddaljuje od svojega gnezda, tako je človek, ki se oddaljuje od svojega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Mazilo in dišava razveseljujeta srce, tako počne sladkost človekovega prijatelja s srčnim nasvetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Svojega lastnega prijatelja in prijatelja svojega očeta ne zapusti niti na dan svoje katastrofe ne pojdi v hišo svojega brata, kajti boljši je sosed, ki je blizu, kakor brat daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Moj sin, bodi moder in razveseli moje srce, da lahko odgovorim tistemu, ki me graja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Razsoden človek sluti zlo in se skrije, toda naivneži gredo dalje in so kaznovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Vzemi obleko tistega, ki je pôrok za tujca in vzemi njegovo jamstvo za tujo žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Kdor z močnim glasom blagoslavlja svojega prijatelja, vzdigujoč ga zgodaj zjutraj, se mu bo to štelo [v] prekletstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Nenehno kapljanje na zelo deževen dan in prepirljiva ženska sta si podobna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kdorkoli jo skriva, skriva veter in mazilo svoje desnice, ki izdaja samo sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Železo ostri železo; tako človek ostri obličje svojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kdorkoli varuje figovo drevo, bo jedel njegov sad, tako bo spoštovan, kdor čaka na svojega gospodarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Kakor v vodi obraz odzdravlja obrazu, tako srce človeka k človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Pekel in uničenje nikdar nista polna, tako človekove oči nikoli niso nasičene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Kakor je talilni lonec za srebro in talilna peč za zlato, tak je človek do svoje hvale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Čeprav bi bedaka s tolkačem stolkel v stopi med pšenico, vendarle njegova nespametnost ne bo odšla od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Bodi marljiv, da spoznaš stanje svojih tropov in dobro glej k svojim čredam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Kajti bogastva niso na veke in mar se krona prenaša vsakemu rodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Seno je odneseno, prikaže se nežna trava in gorska zelišča se zberejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Jagnjeta so za tvoje oblačilo in kozli so nagrada polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Imel boš dovolj kozjega mleka za svojo hrano, za hrano svoje družine in za vzdrževanje svojih dekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Zlobni zbežijo, kadar jih noben človek ne preganja, toda pravični so pogumni kakor lev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Zaradi prestopka dežele so številni njeni princi, toda s človekom razumevanja in spoznanja bo njihova država podaljšana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Revež, ki zatira ubogega, je podoben pometajočemu dežju, ki ne zapušča nobene hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Tisti, ki zapuščajo postavo, hvalijo zlobne, toda tisti, ki se držijo postave, se z njimi pričkajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Hudobneži ne razumejo sodbe, toda tisti, ki iščejo Gospoda, razumejo vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Boljši je ubogi, ki hodi v svoji poštenosti, kakor kdor je sprevržen na svojih poteh, četudi je bogat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kdorkoli ohranja postavo, je moder sin, toda kdor je družabnik upornih ljudi, svojega očeta spravlja v sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kdor z obrestmi in nepravičnim zaslužkom povečuje svoje imetje, ga bo zbiral za tistega, ki bo pomiloval ubogega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kdor svoje uho obrača stran od poslušanja postave, bo celo njegova molitev ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kdorkoli pravičnemu povzroči, da zaide na zlo pot, bo tudi sam padel v svojo lastno jamo, toda pošteni bodo imeli v posesti dobre stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Bogataš je moder v svoji lastni domišljavosti, toda revni, ki ima razumevanje, ga preiskuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kadar se pravični ljudje razveseljujejo, je velika slava, toda kadar vstanejo zlobni, je človek skrit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kdor prikriva svoje grehe, ne bo uspešen, toda kdorkoli jih priznava in se jim odreka, bo imel usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Srečen je človek, ki se vedno boji, toda kdor svoje srce zakrkne, bo padel v vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Kakor rjoveč lev in pohajkujoč medved, tak je zloben vladar nad ubogim ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Princ, ki mu manjka razumevanja, je prav tako velik zatiralec, toda kdor sovraži pohlepnost, bo podaljšal svoje dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Človek, ki počne nasilje krvi kateregakoli človeka, bo zbežal v jamo; naj ga noben človek ne zadržuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kdorkoli živi pošteno, bo rešen, toda kdor je na svojih poteh sprevržen, bo naenkrat padel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kdor obdeluje svojo zemljo, bo imel obilo kruha, toda kdor sledi ničevim osebam, bo imel dosti revščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Zvest človek bo obilen z blagoslovi, toda kdor hiti biti bogat, ne bo nedolžen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Ozirati se na osebe ni dobro, kajti za košček kruha se bo ta človek pregrešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Kdor hiti biti bogat, ima hudobno oko in ne upošteva, da bo nadenj prišla revščina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kdor graja človeka, bo kasneje našel večjo naklonjenost, kakor kdor laska z jezikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kdorkoli krade svojemu očetu ali svoji materi in pravi: » To ni prestopek,« isti je družabnik uničevalcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Kdor je ponosnega srca, razvnema prepir, toda kdor svoje trdno upanje polaga v Gospoda, bo narastel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kdor zaupa v svoje lastno srce, je bedak, toda kdorkoli hodi modro, bo osvobojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kdor daje ubogemu, ne bo trpel pomanjkanja, toda kdor zagrinja svoje oči, bo mnogim [v] kletev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kadar zlobni vstajajo, se ljudje skrivajo, toda kadar oni izginejo, pravični narastejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Tisti, ki je pogosto grajan, otrjuje svoj vrat; nenadoma bo uničen in to brez rešitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Kadar so pravični na oblasti, se ljudstvo veseli, toda kadar zlobni rojevajo pravila, ljudstvo žaluje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Kdorkoli ljubi modrost, razveseljuje svojega očeta, toda kdor se zadržuje s pocestnicami, zapravlja svoje imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Kralj s sodbo vzpostavlja deželo, toda kdor sprejema darila, jo prevrača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Človek, ki laska svojemu bližnjemu, razpenja mrežo za njegova stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'V prestopku hudobneža je zanka, toda pravični prepeva in se veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Pravični preudarja stvar ubogega, toda zlobni se na to ne ozira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Posmehljivci mesto privedejo v zanko, toda modri možje odvrnejo bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Če se moder človek prička z nespametnim človekom, bodisi besni ali se smeje, tam ni počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Krvoločnež sovraži poštenega, toda pravični išče njegovo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, '§ Bedak izreka vse svoje mišljenje, toda moder človek ga zadrži za pozneje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Če vladar prisluhne lažem, so vsi njegovi služabniki zlobni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Ubog in varljiv človek se skupaj srečata; Gospod razsvetljuje oči obeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Kralju, ki zvesto sodi ubogega, bo njegov prestol utrjen na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Palica in opomin dajeta modrost, toda otrok, prepuščen samemu sebi, svoji materi prinaša sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Kadar so zlobni pomnoženi, narašča prestopek, toda pravični bodo videli njihov padec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Grajaj svojega sina in dal ti bo počitek; da, tvoji duši bo dal veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Kjer ni videnja ljudstvo propada, toda kdor se drži postave, je srečen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Služabnik ne bo grajan z besedami; kajti čeprav razume, ne bo odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Vidiš človeka, ki je nagel v svojih besedah? Več upanja je za bedaka kakor zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, '§ Kdor svojega služabnika od otroških let prefinjeno vzgaja, mu bo končno postal njegov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Jezen človek razvnema prepir, besen človek pa je obilen v prestopku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Človekov ponos ga bo ponižal, toda spoštovanje bo podpiralo ponižnega v duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kdorkoli je družabnik s tatom, sovraži svojo lastno dušo; sliši preklinjanje, pa tega ne razkriva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Strah pred človekom prinaša zanko, toda kdorkoli svoje trdno upanje polaga v Gospoda, bo varen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Mnogi iščejo vladarjevo naklonjenost, toda sodba vsakega človeka prihaja od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Nepravičen človek je ogabnost pravičnemu in kdor je na svoji poti pošten, je ogabnost zlobnemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Besede Jakéjevega sina Agúrja, celó prerokba. Človek je govoril Itiélu, celo Itiélu in Ukálu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Zagotovo sem bolj brutalen kakor katerikoli človek in nimam človeškega razumevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Niti se nisem učil modrosti niti imel spoznanja o svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kdo se je povzpel v nebo ali se spustil? Kdo je zbral veter v svoje pesti? Kdo je vode omejil v obleko? Kdo je utrdil vse konce zemlje? Kakšno je njegovo ime in kakšno je ime njegovega sina, če lahko poveš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Vsaka Božja beseda je čista, on je ščit vsem tem, ki svoje trdno upanje polagajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Ne dodajaj njegovim besedam, da te ne graja in bi bil spoznan za lažnivca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Dve stvari sem zahteval od tebe, ne odrekaj mi ju, preden umrem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'ničnost in laži odstrani daleč od mene, ne dajaj mi niti revščine niti bogastev, hrani me s hrano zame primerno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'da ne bi bil sit in te utajil in rekel: »Kdo je Gospod?« Ali, da ne bi bil reven in kradel in zaman vzel imena svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Služabnika ne zatoži njegovemu gospodarju, da te ne bi ta preklel in bi bil ti spoznan [za] krivega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Je rod, ki preklinja svojega očeta in ne blagoslavlja svoje matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Je rod, ki je čist v svojih lastnih očeh, vendar ni umit pred svojimi umazanostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Je rod, oh kako vzvišene so njihove oči! In njihove veke povzdignjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Je rod, katerih zobje so kakor meči in zobje njihove čeljusti kakor noži, da požro uboge z zemlje in pomoči potrebne izmed ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijavka ima dve hčeri, kričeč: »Daj, daj.« So tri stvari, ki niso nikoli nasičene, da, štiri stvari ne rečejo: »Dovolj je «:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'grob in jalova maternica; zemlja, ki ni nasičena z vodo; in ogenj, ki ne govori: »Dovolj je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, ki zasmehuje svojega očeta in prezira pokoravanje svoji materi, bodo izkljuvali dolinski krokarji in mladi orli ga bodo pojedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Tri stvari so, ki so mi prečudovite, da, štiri, ki jih ne poznam:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'pot orla na nebu; pot kače na skali; pot ladje na sredini morja; in pot človeka z dekletom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Podobna je pot zakonolomne ženske; jé in si obriše svoja usta ter reče: »Nobene zlobnosti nisem storila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Zaradi treh stvari je zemlja vznemirjena in zaradi štirih kar ne more prenesti:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'zaradi služabnika, kadar kraljuje; in bedaka, kadar je nasičen s hrano;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'zaradi zoprne ženske, kadar je poročena; in pomočnice, ki je dedinja svoje gospodarice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Štiri stvari so, ki so majhne na zemlji, toda le-te so silno modre:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'mravlje niso močno ljudstvo, vendar svojo hrano pripravljajo poleti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'kunci so samo slaboten narod, vendar si svoje hiše naredijo v skalah;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'leteče kobilice nimajo kralja, pa vendar gredo vse izmed njih s trumami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'pajkovka grabi s svojimi rokami in je v kraljevih palačah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Tri stvari so, ki dobro hodijo, da, štiri so ljubke v hoji:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'lev, ki je najmočnejši med zvermi in se ne obrača proč zaradi kogarkoli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '§ hrt; in tudi kozel; in kralj, zoper katerega ni vstaje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Če si nespametno storil s povzdigovanjem samega sebe, ali če snuješ zlo, položi svojo roko na svoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, '§ Zagotovo stepanje mleka prinaša maslo in močno stiskanje nosu prinaša kri, tako pospeševanje besa prinaša prepir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Besede kralja Lemuéla, prerokba, katero ga je učila njegova mati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Kaj, moj sin? In kaj, sin moje maternice? In kaj, sin mojih zaobljub?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Svoje moči ne daj ženski niti svojih poti tistim, ki uničujejo kralje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'To ni za kralje, oh Lemuél, to ni za kralje, da pijejo vino niti za prince močna pijača,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'da ne bi pili in pozabili postave in izkrivili sodbo kateregakoli izmed prizadetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Močno pijačo daj tistemu, ki je pripravljen, da propade in vino tistim, ki so potrtih src.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Naj pije in pozabi svojo revščino in se nič več ne spominja svoje bede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Odpri svoja usta za nemega v imenu vseh takšnih, ki so določeni k uničenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Odpri svoja usta, sodi pravično in zagovarjaj pravdo ubogega in pomoči potrebnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Kdo lahko najde vrlo žensko? Kajti njena vrednost je daleč nad rubini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Srce njenega soproga varno zaupa vanjo, tako da ne bo imel nobene potrebe po plenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Delala mu bo dobro in ne zla vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Išče volno in lan in voljno dela s svojimi rokami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Podobna je trgovčevim ladjam, svojo hrano prinaša od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Tudi vstaja, ko je še noč in daje hrano svoji družini ter obrok svojim deklam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Prouči polje in ga kupuje; s sadom svojih rok zasadi vinograd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Svoja ledja opasuje z močjo in utrjuje svoje lakte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Zaznava, da je njeno trgovanje dobro, njena sveča ponoči ne ugasne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Svoje roke polaga k vretenu in njene roke držijo preslico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Svojo roko izteguje k ubogemu; da, svoji roki izteguje pomoči potrebnemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ne boji se snega za svojo družino, kajti vsa njena družina je oblečena s škrlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Sama izdeluje pokrivala iz tapiserije, njeno oblačilo sta svila in škrlat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Njen soprog je poznan v velikih vratih, ko sedi med starešinami dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Ona izdeluje tanko laneno platno in ga prodaja in pasove dostavlja trgovcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Moč in spoštovanje sta njeno oblačilo in veselila se bo v času, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Svoja usta odpira z modrostjo in na njenem jeziku je postava prijaznosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Dobro gleda na poti svoje družine in ne jé kruha brezdelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Njeni otroci vstanejo in jo kličejo blagoslovljena, tudi njen soprog in jo hvali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Mnoge hčere so storile krepostno, toda ti jih prekašaš vse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Naklonjenost je varljiva in lepota je prazna, toda ženska, ki se boji Gospoda, bo hvaljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dajte ji od sadu njenih rok in naj jo njena lastna dela hvalijo v velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Besede Pridigarja, Davidovega sina, kralja v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, '»Ničevost ničevosti,« pravi Pridigar, »ničevost ničevosti; vse je ničevost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Kakšno korist ima človek od vsega svojega truda, ki se ga loteva pod soncem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'En rod mineva in drug rod prihaja, toda zemlja ostaja na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Tudi sonce vzhaja in sonce gre dol in hiti k svojemu kraju, kjer vstaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Veter gre proti jugu in se obrača k severu, nenehno se vrti naokoli in veter se ponovno vrača, glede na svoje kroge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, '§ Vse reke tečejo v morje, vendar morje ni polno; na kraj, od koder reke prihajajo, tja se ponovno vrnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Vse stvari so polne truda, človek tega ne more izreči. Oko ni nasičeno z gledanjem niti uho nasičeno s poslušanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Stvar, ki je bila, to je ta, ki bo in to, kar je storjeno, je to, kar bo storjeno, in pod soncem ni nobene nove stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Ali je katerakoli stvar, o čemer bi bilo lahko rečeno: »Glej, to je novo? To je bilo že od starih časov, ki so bili pred nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ni spominjanja o prejšnjih stvareh niti ne bo kakršnegakoli spominjanja o stvareh, ki pridejo s tistimi, ki bodo prišle potem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Jaz, Pridigar, sem bil kralj nad Izraelom v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Izročil sem svoje srce, da išče in preiskuje z modrostjo glede vseh stvari, ki so storjene pod nebom. To bolečo muko je Bog izročil človeškim sinovom, da bi bili vežbani s tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Videl sem vsa dela, ki so storjena pod soncem in glej, vse je ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'To, kar je skrivljeno, ne more biti izravnano; in to, kar je pomanjkljivo, ne more biti prešteto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Posvetoval sem se s svojim lastnim srcem, rekoč: »Glej! Prišel sem k velikemu premoženju in prejel sem več modrosti kakor vsi tisti, ki so bili pred menoj v Jeruzalemu. Da, moje srce je imelo sijajno izkušnjo modrosti in spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Izročil sem svoje srce, da spoznam modrost in da spoznam norost in neumnost. Zaznal sem, da je tudi to draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Kajti v mnogi modrosti je mnogo žalosti in kdor povečuje spoznanje, povečuje bridkost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'V svojem srcu sem rekel: »Pojdi sedaj, preizkusil te bom z veseljem, zato uživaj zadovoljstvo.« Glej, tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'O smehu sem rekel: » To je zmešano.« O veselju: »Kaj to počne?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'V svojem srcu sem iskal, da se izročim vinu in vendar sem seznanjal svoje srce z modrostjo in se poprijel neumnosti, dokler ne bi videl, kaj je bilo to dobro za človeške sinove, kar naj bi storili pod nebom vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Naredil sem si velika dela. Zgradil sem si hiše, si zasadil vinograde,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'naredil sem si vrtove in sadovnjake in vanje sem zasadil vse vrste sadnih dreves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Naredil sem si vodne tolmune, da z njimi namakam gozd, ki rojeva drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Pridobil sem si služabnike in dekle in imel služabnike rojene v moji hiši. Prav tako sem imel veliko posesti z veliko in malo živine, povrh vsega kar je bilo v Jeruzalemu pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Zbral sem si tudi srebro in zlato in izvoljen zaklad od kraljev in od provinc. Dobil sem si pevce in pevke in radosti človeških sinov, kakor glasbene instrumente in to od vseh vrst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Tako sem bil velik in narasel bolj kakor vsi, ki so bili pred menoj v Jeruzalemu. Tudi moja modrost je ostala z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Karkoli so si moje oči želele, jim tega nisem preprečil, svojega srca nisem zadržal pred nobeno radostjo, kajti moje srce se je veselilo v vsem mojem trudu in to je bil moj delež vsega mojega truda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Potem sem pogledal na vsa dela, ki sta jih moji roki izvršili in na trud, ki sem se ga trudil delati. Glej, vse je bilo ničevost in draženje duha in ni bilo koristi pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Obrnil sem se, da bi gledal modrost, norost in neumnost, kajti kaj lahko stori človek, ki prihaja za kraljem? Celó to, kar je bilo že narejeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Potem sem videl, da modrost prekaša neumnost, kolikor svetloba prekaša temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Oči modrega človeka so v njegovi glavi, toda bedak hodi v temi. Zaznal pa sem tudi, da se vsem tem dogaja en dogodek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Potem sem v svojem srcu rekel: »Kakor se dogaja bedaku, tako se dogaja celo meni in zakaj sem bil potem modrejši?« Nato sem rekel v svojem srcu, da je tudi to ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Kajti na veke ni spomina na modrega bolj kakor na bedaka. Glede na to, da kar je sedaj, bo v dneh, ki bodo prišli, vse pozabljeno. In kako umira moder človek? Kakor bedak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Zato sem zasovražil življenje, ker mi je delo, ki je opravljeno pod soncem, mučno, kajti vse je ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Da, zasovražil sem ves svoj trud, ki sem se ga lotil pod soncem, ker naj bi ga zapustil človeku, ki bo za menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Kdo ve, ali bo moder človek ali bedak? Vendar bo imel oblast nad vsem mojim trudom, v čemer sem se trudil in v čemer sem se pokazal modrega pod soncem. Tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Zato sem odšel naokrog, da svojemu srcu povzročim, da obupuje od vsega truda, ki sem ga prijel pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Kajti je človek, čigar trud je v modrosti, v spoznanju in v nepristranskosti, vendar bo človeku, ki se ni trudil s tem, to zapustil za njegov delež. Tudi to je ničevost in veliko zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Kajti kaj ima človek od vsega svojega truda in od draženja svojega srca, v čemer se je trudil pod soncem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Kajti vsi njegovi dnevi so bridkosti in njegova muka žalost, da, njegovo srce si ponoči ne vzame počitka. Tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Nič ni boljšega za človeka, kakor da naj bi jedel in pil ter da naj bi svojo dušo pripravil uživati dobro v svojem trudu. Tudi to sem videl, da je bilo to iz Božje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Kajti kdo lahko jé ali kdo lahko hiti k temu bolj kakor jaz?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Kajti Bog daje človeku, ki je dober v njegovem pogledu, modrost, spoznanje in radost, toda grešniku daje muko, da zbira in kopiči, da bi lahko dal tistemu, ki je dober pred Bogom. Tudi to je ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Za vsako stvar je obdobje in čas za vsak namen pod nebom:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'čas, da si rojen in čas za smrt, čas za sajenje in čas za ruvanje tega, kar je vsajeno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'čas za ubijanje in čas za zdravljenje, čas za rušenje in čas za gradnjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'čas za jokanje in čas za smejanje, čas za žalovanje in čas za ples,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'čas za odmetavanje kamnov in čas za zbiranje kamnov, čas za objemanje in čas za zadržanje pred objemanjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'čas za pridobivanje in čas za izgubljanje, in čas za hranjenje in čas za odmetavanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'čas za paranje in čas za šivanje, čas za molčanje in čas za govorjenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'čas za ljubezen in čas za sovraštvo, čas vojne in čas miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kakšno korist ima kdor dela v tem, v čemer se trudi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Videl sem muko, ki jo Bog daje človeškim sinovom, da bi bili vežbani v tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, '§ Vsako stvar je naredil krasno ob svojem času. Prav tako je v njihovo srce postavil svet, tako da noben človek ne more spoznati dela, ki ga Bog dela od začetka do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Vem, da ni dobrega v njih, temveč za človeka, da se veseli in da v svojem življenju dela dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Prav tako, da naj bi vsak človek jedel, pil in užival dobro od vsega svojega truda, to je darilo od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Vem, da karkoli Bog dela, bo to za vedno. Nič ne more biti k temu dodano niti karkoli od tega odvzeto. Bog to dela, da naj bi se ljudje bali pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'To, kar je bilo, je sedaj in to, kar naj bi bilo, je že bilo in Bog zahteva to, kar je minilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Poleg tega sem pod soncem videl kraj sodbe, da je bila tam zlobnost in kraj pravičnosti, da je bila tam krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'V svojem srcu sem rekel: ›Bog bo sodil pravičnega in zlobnega, kajti tam je čas za vsak namen in za vsako delo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'V svojem srcu sem rekel glede stanja človeških sinov, da bi se jim Bog lahko pokazal in da bi lahko videli, da so oni sami živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Kajti to, kar zadene človeške sinove, zadene živali, celo ena stvar jih zadene; kakor umre eden, tako umre drugi, da, vsi imajo en dih, tako da človek nima nobene premoči nad živaljo, kajti vse je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Vsi gredo k enemu kraju, vsi so iz prahu in vsi se ponovno spremenijo v prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kdo pozna človekovega duha, ki gre navzgor in duha živali, ki gre navzdol k zemlji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Zatorej zaznavam, da ni ničesar boljšega, kakor da naj bi se človek veselil v svojih lastnih delih, kajti to je njegov delež, kajti kdo ga bo privedel, da vidi kaj bo za njim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Tako sem se vrnil in preudaril vsa zatiranja, ki so storjena pod soncem in gledal solze tistih, ki so bili zatirani in niso imeli tolažnika in je bila moč na strani njihovih zatiralcev, toda niso imeli nobenega tolažnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Zatorej sem bolj hvalil mrtve, ki so že mrtvi, kakor živeče, ki so še živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Da, kakor oni oboji je boljši tisti, ki še ni bil, ki še ni videl zlobnega dela, ki je storjeno pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Ponovno, preudaril sem vso muko in vsako pravilno delo, da zaradi tega človeku zavidajo njegovi sosedi. Tudi to je ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Bedak drži prekrižane roke in jé svoje lastno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Boljše je prgišče s spokojnostjo, kakor obe roki napolnjeni z muko in draženjem duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Potem sem se vrnil in videl ničevost pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Tam je nekdo sam in ni drugega, da, nima niti otroka niti brata, vendar ni konca vsemu njegovemu trudu, niti njegovo oko ni nasičeno z bogastvi, niti ne pravi: »Za koga se trudim in svoji duši kratim dobro?« Tudi to je ničevost, da, to je boleča muka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Dva sta boljša kakor eden, zato ker imata dobro nagrado za svoj trud.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Kajti če padeta, bo vsak dvignil svojega tovariša; toda gorje tistemu, ki je sam, ko pade, kajti nima drugega, da mu pomaga pokonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Ponovno, če dva ležita skupaj, potem imata toploto, toda kako se lahko nekdo ogreje sam?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'In če eden zoper njega prevlada, se mu bosta zoperstavila dva in trojna vrvica ni hitro pretrgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Boljši je ubog in moder otrok, kakor star in nespameten kralj, ki noče biti več opomnjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Kajti on prihaja iz ječe, da vlada, medtem ko tisti, ki je prav tako rojen v njegovem kraljestvu, postaja ubog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Preudaril sem vse živeče, ki hodijo pod soncem, z drugim otrokom, ki bo vstal namesto njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Ni konca vsemu ljudstvu, celó vseh, ki so bili pred njimi. Tudi tisti, ki pridejo potem, se ne bodo veselili v njem. Zagotovo je tudi to ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Varuj svoje stopalo, ko greš k Božji hiši in bodi bolj pripravljen prisluhniti kakor izročiti klavno daritev bedakov, kajti ne preudarjajo, da počnejo zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ne bodi prenagljen s svojimi usti in tvoje srce naj ne bo hitro, da izreče katerokoli stvar pred Bogom, kajti Bog je v nebesih, ti pa na zemlji, zato naj bo tvojih besed malo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Kajti sanje prihajajo po množici zadev in bedakov glas je razpoznan z množico besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Kadar prisegaš zaobljubo Bogu, ne odlašaj, da jo izpolniš, kajti on nima zadovoljstva v bedakih. Izpolni to, kar si se zaobljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Bolje je to, da ne prisežeš, kakor da prisežeš zaobljubo, pa ne izpolniš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, '§ Ne dopusti svojim ustom, da bi tvojemu mesu povzročila, da greši niti pred angelom ne povej, da je bila pomota. Zakaj bi bil Bog ob tvojem glasu jezen in bi uničil delo tvojih rok?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Kajti v množici sanj in mnogih besedah so tudi številne ničevosti, toda boj se Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Če vidiš v provinci zatirati ubogega in nasilne prevračati sodbo in pravico, se ne čudi ob zadevi, kajti kdor je višji kakor najvišji, upošteva; in obstaja višji kakor oni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Poleg tega je donos zemlje za vse; sam kralj je postrežen s poljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kdor ljubi srebro, ne bo potešen s srebrom niti kdor ljubi obilje, z donosom; tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Kadar se dobrine povečujejo, so povečane, da se pojejo; kakšno dobro je njegovim lastnikom, razen da jih gledajo s svojimi očmi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Spanje delovnega človeka je sladko, bodisi jé malo ali veliko, toda obilje bogastva mu ne bo pustilo spati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Je boleče zlo, ki sem ga videl pod soncem, namreč bogastva, varovana za njihove lastnike v njihovo škodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Toda ta bogastva izginejo po zli zadevi. Zaplodil je sina, pa v njegovi roki ni ničesar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Kakor je nag prišel iz maternice svoje matere, se bo vrnil kakor je prišel in ničesar ne bo vzel od svojega truda, kar bi v svoji roki lahko odnesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Tudi to je boleče zlo, da v vseh točkah, kakor je prišel, bo tako odšel; in kakšno korist ima tisti, ki se je trudil za veter?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, '§ Prav tako vse svoje dni jé v temi in ima mnogo bridkosti in besa s svojo slabostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Glej to, kar sem videl. Dobro in ljubko je za nekoga jesti, piti in uživati dobro od vsega svojega truda, ki se ga loteva pod soncem vse dni svojega življenja, ki mu jih daje Bog, kajti to je njegov delež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Tudi vsakemu človeku, ki mu Bog daje bogastva in premoženje, mu daje moč, da od tega jé in da vzame svoj delež in se veseli v svojem trudu; to je darilo od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Kajti dni svojega življenja se ne bo dosti spominjal, ker mu Bog odgovarja v radosti njegovega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Je zlo, ki sem ga videl pod soncem in to je pogosto med ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Človek, ki mu je Bog dal bogastva, premoženje in čast, tako da za svojo dušo ne potrebuje ničesar od vsega, kar si želi, pa mu vendar Bog ne daje moči, da od tega jé, temveč to jé tujec. To je ničevost in to je zla bolezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Če človek zaplodi sto otrok in živi mnogo let, tako da je dni njegovih let mnogo in njegova duša ne bo nasičena z dobrinami in tudi da nima pogreba, pravim, da je prezgodaj rojeni boljši kakor on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Kajti vstopa z ničevostjo in odhaja v temi in njegovo ime bo prekrito s temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Poleg tega ni videl sonca niti ni poznal nobene stvari; ta ima več počitka kakor drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Da, čeprav je bilo rečeno, da živi dvakrat tisoč let, vendar ni videl dobrega; mar ne gredo vsi na en kraj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Vse človekovo delo je za njegova usta, pa vendar apetit ni potešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Kajti kaj ima modri več kakor bedak? Kaj ima ubogi, da zna hoditi pred živečimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Boljši je pogled oči kakor tavanje poželenja. Tudi to je ničevost in draženje duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'To, kar je bilo, je že imenovano in je znano, da je to človek; niti se ne more pričkati s tistim, ki je mogočnejši kakor on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Ker je tukaj mnogo stvari, ki povečujejo ničevost, kaj je človek boljši?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Kajti kdo ve kaj je boljše za človeka v tem življenju, vse dni njegovega praznega življenja, ki jih preživlja kakor senca? Kajti kdo lahko človeku pove kaj bo za njim pod soncem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Dobro ime je boljše kakor dragoceno mazilo in dan smrti [je boljši] kakor dan rojstva nekoga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Bolje je iti v hišo žalujočega, kakor iti v hišo pojedine, kajti to je konec vseh ljudi; in živi si bodo to položili k srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Bridkost je boljša kot smeh, kajti z žalostjo obličja je srce postalo boljše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Srce modrega je v hiši žalovanja, toda srce bedakov je v hiši veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Bolje je poslušati oštevanje modrega, kakor za človeka poslušati pesem bedakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Kajti kakor je prasketanje trnja pod loncem, tak je smeh bedaka. Tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Zatiranje modrega zagotovo dela besnega in podkupnina uničuje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Boljši je konec stvari kakor njen začetek, in potrpežljivi v duhu je boljši kakor ponosni v duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, '§ V svojem duhu ne bodi nagel, da bi bil jezen, kajti jeza počiva v naročju bedakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne reci: »Kaj je razlog, da so bili prejšnji dnevi boljši kakor tile?« Kajti glede tega nisi modro poizvedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Modrost je dobra z dediščino; in z njo je korist tistim, ki gledajo sonce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Kajti modrost je obramba in denar je obramba, toda odličnost spoznanja je, da modrost daje življenje tem, ki jo imajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Preudari Gospodovo delo, kajti kdo lahko izravna to, kar je on skrivil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Na dan uspevanja bodi radosten, toda na dan nadloge preudari; tudi Bog je postavil enega nasproti drugemu, z namenom, da človek ne bi ničesar našel za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Vse stvari sem videl v dneh svoje ničevosti. Je pravičen človek, ki propada v svoji pravičnosti in je zloben človek, ki v svoji zlobnosti podaljšuje svoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne bodi preko mere pravičen niti se ne delaj preveč modrega. Zakaj bi samega sebe uničil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne bodi preveč zloben niti ne bodi nespameten. Zakaj bi umrl pred svojim časom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Dobro je, da bi to zgrabil, da, tudi pred tem ne umikaj svoje roke, kajti kdor se boji Boga, bo izmed vseh prišel naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Modrost krepi modrega bolj kakor deset silnih mož, ki so v mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Kajti na zemlji ni pravičnega človeka, ki dela dobro in ne greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Prav tako se ne oziraj na vse besede, ki so izgovorjene, da ne bi slišal svojega služabnika [kako] te preklinja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'kajti pogosto tudi tvoje lastno srce ve, da si ti sam podobno preklinjal druge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Vse to sem preizkusil z modrostjo. Rekel sem: »Moder bom,« toda to je bilo daleč od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'To, kar je daleč proč in presegajoče globoko, kdo to lahko spozna?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Svoje srce sem posvetil védenju in preiskovanju in iskanju modrosti in razlogu za stvari in da spoznam zlobnost neumnosti, celo nespametnost in norost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Našel sem grenkejše kakor smrt, žensko, čigar srce so pasti in mreže in njene roke kakor trakovi. Kdorkoli ugaja Bogu, bo zbežal pred njo, toda grešnik bo vzet po njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, '»Glej, to sem našel,« pravi pridigar, naštevajoč enega za drugim, da spozna razlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Kar vendar moja duša išče, toda ne najdem. Našel sem enega med tisočimi, toda ženske med vsemi tistimi nisem našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Glej, samo to sem našel, da je Bog človeka naredil poštenega, toda oni so iskali mnoge domiselnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kdo je kakor moder človek? In kdo pozna pomen stvari? Človekova modrost pripravi njegov obraz, da zasveti in srčnost njegovega obraza bo spremenjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Svetujem ti, da obdržiš kraljevo zapoved in da upoštevaš Božjo prisego.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne bodi nagel, da greš izven njegovega pogleda. Ne stoj v zli stvari, kajti on počne karkoli mu ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Kjer je kraljeva beseda, tam je moč, in kdo mu lahko reče: »Kaj počneš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kdorkoli se drži zapovedi, ne bo čutil nobene zle stvari in srce modrega človeka razlikuje tako čas kakor sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Ker za vsak namen je čas in sodba, zato je človeška beda velika nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Kajti on ne ve, tega kar bo, kajti kdo mu lahko pove kdaj bo to?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Nobenega človeka ni, da ima moč nad duhom, da obdrži duha niti nima moči na dan smrti in v tej vojni ni nobene poravnave niti zlobnost ne bo osvobodila tistih, ki so ji izročeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Vse to sem videl in svoje srce posvetil vsakemu delu, ki je storjeno pod soncem. Je čas, v katerem en človek vlada nad drugim v svojo lastno škodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Tako sem videl zlobne pokopane, ki so prišli in odšli iz kraja svetih in so bili pozabljeni v mestu, kjer so tako počeli. Tudi to je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Ker obsodba zoper zlo delo ni izvršena naglo, zato je srce človeških sinov v njih popolnoma naravnano, da počno zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Čeprav grešnik tisočkrat stori zlo in bodo njegovi dnevi podaljšani, vendar zagotovo vem, da bo dobro s tistimi, ki se bojijo Boga, ki se bojijo pred njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'toda z zlobnim ne bo dobro niti ne bo podaljšal svojih dni, ki so kakor senca, ker se pred Bogom ne boji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Je ničevost, ki je storjena na zemlji; da so pravični ljudje, ki se jim dogaja glede na delo zlobnih; ponovno, so zlobni ljudje, ki se jim dogaja glede na delo pravičnih. Rekel sem, da je tudi to ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Potem sem priporočal veselje, ker človek pod soncem nima boljše stvari, kot da jé in da pije in da je vesel, kajti to bo ostalo z njim od njegovega truda [vse] dni njegovega življenja, ki mu ga Bog daje pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Ko sem usmeril svoje srce, da spoznam modrost in da vidim opravilo, ki je storjeno na zemlji (kajti tam je ta, ki niti podnevi niti ponoči s svojimi očmi ne vidi spanja),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'sem potem zagledal vsa Božja dela, da človek ne more spoznati dela, ki je storjeno pod soncem. Ker čeprav se človek trudi to spoznati, vendar tega ne bo našel. Da, nadalje, čeprav moder človek misli, da to pozna, vendar tega ne bo zmožen najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Kajti vse to sem preudaril v svojem srcu, celo da vse to oznanim, da so pravični in modri in njihova dela v roki Boga. Noben človek ne spozna bodisi ljubezni ali sovraštva po vsem, kar je pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Vse stvari pridejo podobno k vsem: je en dogodek pravičnemu in zlobnemu; dobremu, čistemu in nečistemu; tistemu, ki daruje in tistemu, ki ne daruje; kakor je dobri, tako je grešnik; in kdor prisega, kakor tisti, ki se prisege boji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'To je zlo med vsemi stvarmi, ki so storjene pod soncem, da je en dogodek za vse. Da, tudi srce človeških sinov je polno zla in dokler živijo je v njihovih srcih norost, potem pa gredo k smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Kajti za tistega, ki je pridružen k vsem živim, je upanje, kajti živ pes je boljši kakor mrtev lev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Kajti živi vedo, da bodo umrli, toda mrtvi ne vedo ničesar niti nimajo več nobene nagrade, kajti spomin nanje je pozabljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Prav tako je njihova ljubezen, njihovo sovraštvo in njihova zavist sedaj izginila niti nimajo več deleža na veke v katerikoli stvari, ki je storjena pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Pojdi svojo pot, svoj kruh jej z radostjo in svoje vino pij z veselim srcem, kajti Bog sedaj sprejema tvoja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Naj bodo tvoje obleke vedno bele in tvoji glavi naj ne manjka mazila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Živi radostno, z ženo, ki jo ljubiš, vse dni življenja svoje ničevosti, ki ti je dana pod soncem vse dni tvoje ničevosti, kajti to je tvoj delež v tem življenju in v tvojem trudu, ki se ga lotevaš pod soncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Karkoli tvoja roka najde, da stori, to stôri z vso svojo močjo, kajti v grobu, kamor greš, ni dela, niti naklepa, niti spoznanja, niti modrosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Vrnil sem se in videl pod soncem, da tek ni za nagle, niti bitka za močne, niti kruh za modre, niti bogastva za ljudi spoznanja, niti celo naklonjenost veščim ljudem, temveč se čas in priložnost dogajata njim vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Kajti tudi človek ne pozna svojega časa. Kakor ribe, ki so ujete v zlo mrežo in kakor ptice, ki so ujete v zanko, tako so človeški sinovi ujeti v zlobnem času, ko le-ta nenadoma pade nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Tudi to modrost sem videl pod soncem in ta se mi je zdela velika:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'bilo je majhno mesto in znotraj njega malo ljudi in zoper njega je prišel velik kralj, ga oblegal in zoper njega zgradil velike branike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Torej v njem je bil najden reven, moder človek in on je s svojo modrostjo osvobodil mesto, vendar se noben človek ni spominjal tega ubogega moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Potem sem rekel: »Modrost je boljša kakor moč; kljub temu je modrost revnega moža prezirana in njegove besede niso slišane.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Besede modrih ljudi se bolj slišijo v tišini kakor vpitje tistega, ki vlada med bedaki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Modrost je boljša kakor bojna orožja, toda en grešnik uničuje mnogo dobrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Mrtve muhe lekarnarjevemu mazilu povzročijo, da od sebe širi smrdljiv vonj; tako je majhna neumnost tistemu, ki ima sloves zaradi modrosti in časti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Srce modrega človeka je pri njegovi desnici, toda bedakovo srce pri njegovi levici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Da, tudi kadar kdor je bedak, hodi po poti, ga njegova modrost izneverja in vsakemu govori, da je bedak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Če vladarjev duh vstane zoper tebe, ne zapusti svojega mesta, kajti ustrežljivost pomirja velike prestopke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Je zlo, ki sem ga videl pod soncem, kakor pomota, ki izvira od vladarja:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'neumnost je postavljena na visoko dostojanstvo, bogati pa sedijo na nizkem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Videl sem služabnike na konjih, prince pa hoditi kakor služabniki po tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kdor koplje jamo, bo padel vanjo, kdorkoli pa lomi ograjo, ga bo pičila kača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kdorkoli odstranja kamne, bo z njimi poškodovan in kdor cepi drva, bo s tem izpostavljen nevarnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Če je železo topo in ne nabrusi ostrine, potem mora vložiti več moči; toda modrost je koristna, da usmerja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Zagotovo bo kača pičila brez izrekanja uroka in blebetavec ni boljši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Besede iz ust modrega moža so milostljive, toda ustnice bedaka bodo samega sebe pogoltnile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Začetek besed iz njegovih ust je nespametnost, konec njegovega govora pa je pogubna norost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Tudi bedak je poln besed. Človek ne more povedati kaj bo, in kaj bo za njim, kdo mu lahko pove?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Trud nespametnih izčrpava vsakogar izmed njih, ker ne ve kako iti do mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Gorje tebi, oh dežela, kadar je tvoj kralj otrok in tvoji princi jedo zjutraj!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Blagoslovljena si ti, oh dežela, kadar je tvoj kralj sin plemičev in tvoji princi jedo v pravšnjem obdobju, za moč in ne za pijanost!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Z veliko lenobe zgradba propada in zaradi brezdelja rok kaplja skozi hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Praznovanje je narejeno za smeh in vino dela vesele, toda denar odgovarja vsem stvarem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ne preklinjaj kralja niti v svojih mislih in ne preklinjaj bogatega v svoji spalnici, kajti zračna ptica bo odnesla glas in kar ima peruti, bo povedalo zadevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Svoj kruh vrzi na vode, kajti našel ga boš po mnogih dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Daj delež sedmim in tudi osmemu, kajti ne veš kakšno zlo bo na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Če so oblaki polni dežja, se izlijejo na zemljo, in če drevo pade proti jugu ali proti severu, na kraj, kamor drevo pade, tam bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kdor opazuje veter, ne bo sejal in kdor se ozira na oblake, ne bo žel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Kakor ne veš kakšna je pot duha niti kako rastejo kosti v maternici tiste, ki je z otrokom; tako ne poznaš del Boga, ki dela vse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Zjutraj sej svoje seme in zvečer ne zadržuj svoje roke, kajti ne veš, ali bo uspevalo to ali ono, ali pa bosta oba enako dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Resnično, svetloba je prijazna in prijetna stvar je za oči, da gledajo sonce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'toda če človek živi mnogo let in se veseli v njih vseh, naj se vendar spomni dni teme, kajti mnogo jih bo. Vse, kar prihaja, je ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Razveseli se, oh mladenič, v svoji mladosti in naj te tvoje srce spodbuja v dneh tvoje mladosti in hodi po poteh svojega srca in za pogledom svojih oči; toda vedi, da te bo Bog zaradi vseh teh stvari privedel v obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Zatorej od svojega srca odstrani bridkost in odloži zlo od svojega mesa, kajti otroštvo in mladost sta ničevost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Spomni se torej svojega Stvarnika v dneh svoje mladosti, ko niso prišli zli dnevi niti se niso približala leta, ko boš rekel: »V njih nimam veselja,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'dokler sonce ali svetloba ali luna ali zvezde ne bodo otemnele niti se oblaki vrnili za dežjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'na dan, ko bodo čuvaji hiše trepetali in se bodo močni možje sklonili in mlinarji odnehajo, ker jih je malo in tisti, ki gledajo skozi okna, postanejo zatemnjeni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'in bodo vrata po ulicah zaprta, ko je glas mletja nizek in bo vstal ob ptičjem glasu in bodo ponižane vse hčere petja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'tudi ko jih bo strah tega, kar je visoko in bodo strahovi na poti in bo mandljevec cvetel in bo kobilica breme in bo hrepenenje izneverilo; ker človek odhaja k svojemu dolgemu domu in žalovalci gredo po ulicah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ali preden se srebrna vrvica odveže ali zlomi zlata skledica ali lončen vrč razbije ob studencu ali zlomi kolo pri vodnem zbiralniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Potem se bo prah vrnil k zemlji, kakor je bil; in duh se bo vrnil k Bogu, ki ga je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, '»Ničevost ničevosti,« pravi pridigar, »vse je ničevost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'In poleg tega, ker je bil pridigar moder, še vedno uči ljudstvo spoznanja. Da, pazil je, poiskal in uredil mnogo pregovorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Pridigar je iskal, da odkrije sprejemljive besede in to, kar je bilo napisano, je bilo iskreno, celó besede resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Besede modrih so kakor palice z bodicami in kakor žeblji, pritrjeni s pomočjo gospodarjev zborov, ki so izročeni od enega pastirja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Nadalje, moj sin, bodi opomnjen s temi. Pisanju mnogih knjig ni konca in mnogo učenja je utrujenost telesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Prisluhnimo zaključku celotne zadeve: »Boj se Boga in se drži njegovih zapovedi, kajti to je vsa človekova dolžnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Kajti Bog bo vsako delo privedel na sodbo, z vsako skrivno stvarjo, bodisi je ta dobra, bodisi je ta slaba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Pesem pesmi, ki je Salomonova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Naj me poljublja s poljubi svojih ust, kajti tvoja ljubezen je boljša kakor vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Zaradi vonja tvojih dobrih mazil je tvoje ime kakor izlito mazilo, zato te ljubijo device.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Povleci me, me bomo tekle za teboj. Kralj me je privedel v svoje sobe; me bomo vesele in se veselile v tebi, me se bomo spominjale tvoje ljubezni bolj kakor vina. Poštene te ljubijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Črna sem, toda ljubka, oh ve hčere jeruzalemske, kakor kedárski šotori, kakor Salomonove zavese.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne glejte name, ker sem počrnela, ker je name pogledalo sonce. Otroci moje matere so bili jezni name, postavili so me za varuhinjo vinogradov, toda svojega lastnega vinograda nisem varovala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Povej mi, oh ti, ki ga ljubi moja duša, kje paseš, kje daješ svojemu tropu, da počiva opoldan; kajti zakaj bi bila jaz kakor nekdo, ki se obrača vstran ob tropih tvojih družabnikov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Če ne veš, oh najlepša med ženami, pojdi svojo pot naprej ob stopinjah tropa in pasi svoje kozličke poleg pastirskih šotorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Primerjal sem te, oh moja ljubezen, s skupino konj v faraonovih bojnih vozovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tvoja lica so ljubka z nizi draguljev, tvoj vrat z verižicami iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Naredile ti bomo zlate robove s srebrnimi kroglicami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Medtem ko kralj sedi pri svoji mizi, moja narda oddaja svoj vonj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Moj srčno ljubljeni mi je sveženj mire, vso noč bo ležal med mojimi prsmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Moj ljubljeni mi je kakor skupina kan v engedijskih vinogradih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Glej, lepa si, moja ljubezen, glej, lepa si, imaš oči golobice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Glej, lep si, moj ljubljeni, da, prijeten. Tudi najina postelja je zelena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Bruna najine hiše so cedre in najini trami v ostrešju iz cipresovine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jaz sem vrtnica Šaróna in dolinska lilija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Kakor lilija med trnjem, tako je moja ljubezen med hčerami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Kakor jablana med gozdnimi drevesi, tak je moj ljubljeni med sinovi. Z velikim veseljem sem se usedla pod njeno senco in njen sad je bil sladek mojemu okusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Privedel me je v hišo gostije in njegov prapor nad menoj je bila ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Potešite me s flaškoni, tolažite me z jabolki, kajti jaz sem bolna od ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Njegova leva roka je pod mojo glavo in njegova desnica me objema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Naročam vam, oh ve hčere jeruzalemske, pri srnah in pri poljskih košutah, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Glas mojega ljubljenega! Glej, prihaja, skače na gorah, poskakuje po hribih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Moj ljubljeni je podoben srni ali mlademu jelenu. Glej, stoji za našim zidom, gleda pri oknih, kaže se skozi mrežo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Moj ljubljeni je spregovoril in mi rekel: »Vstani, moja ljubezen, moja lepotica in odleti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Kajti glej, zima je minila, dež je mimo in je izginil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Cvetlice se pojavljajo na zemlji, prišel je čas petja ptic in glas grlice se sliši v naši deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'figovo drevo poganja svoje zelene fige in trte z nežnim grozdjem dajejo dober vonj. Vstani, moja ljubezen, moja lepotica in odleti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Oh moja golobica, ki si v skalnih razpokah, na skrivnih krajih stopnic, naj vidim tvoje obličje, naj slišim tvoj glas, kajti tvoj glas je prijeten in tvoje obličje je ljubko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Ujemite nama lisice, majhne lisice, ki plenijo trte, kajti najine trte imajo nežno grozdje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Moj ljubljeni je moj in jaz sem njegova, on pase med lilijami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Dokler se ne zdani in sence [ne] odletijo, se obrni, moj ljubljeni in bodi podoben srni ali mlademu jelenu na gorah Beterja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Ponoči sem na svoji postelji iskala njega, ki ga ljubi moja duša; iskala sem ga, toda nisem ga našla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Sedaj se bom dvignila in šla okoli mesta, po ulicah in po širokih poteh bom iskala njega, ki ga ljubi moja duša. Iskala sem ga, toda nisem ga našla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Stražarji, ki hodijo po mestu, so me našli, ki sem jim rekla: »Ali ste videli njega, ki ga ljubi moja duša?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Ni bilo dolgo, ko sem odšla od njih, vendar sem našla tistega, ki ga ljubi moja duša. Prijela sem ga in ga nisem hotela izpustiti, dokler ga nisem privedla v hišo svoje matere in v sobo nje, ki me je spočela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Naročam vam, oh hčere jeruzalemske, pri srnah in pri poljskih košutah, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kdo je ta, ki prihaja iz divjine, podobna stebrom dima, odišavljena z miro in kadilom, z vsemi trgovčevimi praški?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Poglej njegovo posteljo, ki je Salomonova. Šestdeset hrabrih mož je okoli nje, izmed Izraelovih hrabrih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Vsi držijo meče, izkušeni so v vojni; vsak človek ima svoj meč na svojem stegnu zaradi strahu ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Kralj Salomon si je naredil bojni voz iz libanonskega lesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Njegove stebre je naredil iz srebra, njegovo dno iz zlata, njegovo pokrivalo iz škrlata, njegova sreda je bila tlakovana z ljubeznijo do jeruzalemskih hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Pojdite ven, oh hčere sionske in glejte kralja Salomona s krono, s katero ga je na dan njegovih zarok kronala njegova mati in na dan veselja njegovega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Glej lepotica si, moja ljubezen, glej, lepotica si. Znotraj svojih pramenov imaš oči golobice. Tvoji lasje so kakor trop koz, ki se pojavljajo z gore Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Tvoji zobje so podobni tropu ovc, ki so gladko ostrižene, ki so prišle gor iz kopanja, od katerih vsaka rodi dvojčke in med njimi ni nobene jalove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Tvoje ustnice so podobne škrlatnemu sukancu in tvoj govor je ljubek. Tvoja sènca so podobna koščku granatnega jabolka znotraj tvojih pramenov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, '§ Tvoj vrat je podoben Davidovemu stolpu, zgrajenemu za orožarno, na katerem visi tisoč majhnih ščitov, vsi ščiti mogočnih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Tvoji dve dojki sta podobni dvema mladima srnama, ki sta dvojčici, ki se paseta med lilijami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Dokler se ne zdani in sence ne odletijo, se bom spravila do gore mire in k hribu kadila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Popolnoma si lepotica, moja ljubezen, madeža ni na tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Pridi z menoj iz Libanona, moja nevesta, z menoj iz Libanona. Poglej iz vrha Amáne, iz vrha Senírja in Hermona, iz levjih brlogov, z gora leopardov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Očarala si moje srce, moja sestra, moja nevesta; z enim izmed svojih očes si očarala moje srce, z eno verižico svojega vratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kako poštena je tvoja ljubezen, moja sestra, moja nevesta! Kako mnogo boljša je tvoja ljubezen kakor vino! In vonj tvojih mazil kakor vse dišave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tvoje ustnice, oh moja nevesta, kapljajo kakor satovje. Med in mleko sta pod tvojim jezikom in vonj tvojih oblek je podoben vonju Libanona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Obdan vrt je moja sestra, moja nevesta, zaprt izvir, zapečaten studenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tvoje rastline so sadovnjak granatnih jabolk s prijetnimi sadovi; kana z nardo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'narda in žafran; kolmež in cimet, z vsemi kadilnimi drevesi; mira in aloja z vsemi vodilnimi dišavami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'vrtni studenec, vodnjak živih vodá in vodotoki iz Libanona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Zbudi se, oh severni veter in pridi jug. Pihaj na moj vrt, da bodo njegove dišave lahko iztekale. Naj moj ljubljeni pride v svoj vrt in jé svoje prijetno sadje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Prišel sem v svoj vrt, moja sestra, moja nevesta. Nabral sem svojo miro s svojo dišavo, pojedel sem svoje satovje s svojim medom, popil sem svoje vino s svojim mlekom. Jejta, oh prijatelja, pijta, da, obilno pijta, oh ljubljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Spim, toda moje srce bedi. To je glas mojega ljubljenega, ki trka, rekoč: »Odpri mi, moja sestra, moja ljubezen, moja golobica, moja neomadeževana, kajti moja glava je napolnjena z roso in moji prameni z nočnimi kapljami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Slekla sem svoj plašč, kako naj ga oblečem? Umila sem svoja stopala, kako naj jih omadežujem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Moj ljubljeni je svojo roko položil pri lini od vrat in moja notranjost je bila spodbujena zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Vstala sem, da odprem svojemu ljubljenemu in moje roke so kapljale z miro in moji prsti s sladko dišečo miro na ročaje zapaha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Odprla sem svojemu ljubljenemu, toda moj ljubljeni se je umaknil in izginil. Moji duši ni zadostovalo, ko je govoril. Iskala sem ga, toda nisem ga mogla najti; klicala sem ga, toda ni mi dal odgovora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Stražarji, ki so šli okoli mesta, so me našli, udarili so me, ranili so me. Čuvaji obzidja so mi odvzeli moje zagrinjalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Naročam vam, oh hčere jeruzalemske, če najdete mojega ljubljenega, da mu poveste, da sem bolna od ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Kaj je tvoj ljubljeni več kakor drug ljubljeni, oh najlepša med ženami? Kaj je tvoj ljubljeni več kakor drug ljubljeni, da nas ti tako bremeniš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Moj ljubljeni je bel in rdečkast, vodilen med deset tisoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Njegova glava je kakor najbolj čisto zlato, njegovi prameni so košati in črni kakor krokar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Njegove oči so kakor oči golobice pri rekah vodá, umite z mlekom in primerno postavljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Njegova lica so kakor postelja iz dišav, kakor dišeče cvetlice. Njegove ustnice [so] podobne lilijam, ki kapljajo sladko dišečo miro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Njegove roke so kakor niz zlatih prstanov napolnjene z berilom. Njegov trebuh je kakor svetla slonovina, prevlečena s safirji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Njegove noge so kakor marmorni stebri, postavljeni na podstavke iz čistega zlata. Njegovo obličje je kakor Libanon, odlično kakor cedre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Njegova usta so najbolj sladka. Da, on je povsem očarljiv. To je moj ljubljeni in to je moj prijatelj. Oh hčere jeruzalemske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kam je odšel tvoj ljubljeni, oh najlepša med ženami? Kam se je tvoj ljubljeni obrnil? Da ga bomo lahko iskale s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Moj ljubljeni je odšel dol v svoj vrt, k posteljam iz dišav, da pase na vrtovih in da nabira lilije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Jaz sem svojega ljubljenega in moj ljubljeni je moj; med lilijami pase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Krasna si, oh moja ljubezen, kakor Tirca, ljubka kakor Jeruzalem, strašna kakor vojska s prapori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Svoje oči odvrni od mene, kajti prevzele so me. Tvoji lasje so kakor trop koz, ki se pojavljajo iz Gileáda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Tvoji zobje so kakor trop ovc, ki gredo gor s kopanja, od katerih vsaka rojeva dvojčke in med njimi ni niti ene jalove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Kakor košček granatnega jabolka so tvoja sènca znotraj tvojih pramenov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Šestdeset je kraljic in osemdeset priležnic in devic brez števila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Moja golobica, moja neomadeževana je le ena, je samo ena od svoje matere, je izbranka nje, ki jo je rodila. Hčere so jo videle in jo blagoslovile, da, kraljice in priležnice in so jo hvalile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kdo je tista, ki gleda kakor jutro, lepa kakor luna, čista kakor sonce in strašna kakor vojska s prapori?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Odšla sem dol v orehov vrt, da vidim sadove doline in da vidim, če trta cveti in granatna jabolka brste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, '§ Preden sem se zavedla, me je moja duša naredila podobno Aminadábovim bojnim vozovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '§ Vrni se, vrni se, oh Šulámka, vrni se, vrni se, da te lahko pogledamo. Kaj boste videli na Šulámki? Kot bi bila to skupina dveh vojsk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Kako krasna so tvoja stopala s čevlji, oh prinčeva hči! Sklepi tvojih stegen so podobni draguljem, delo rok spretnega delavca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, '§ Tvoj popek je podoben okrogli čašici, ki noče žgane pijače. Tvoj trebuh je podoben kupu pšenice, obsutemu z lilijami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Tvoji dve dojki sta podobni dvema mladima srnama, ki sta dvojčici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Tvoj vrat je kakor stolp iz slonovine, tvoje oči [so] podobne ribnikom v Hešbónu, pri Batrabímskih velikih vratih. Tvoj nos je kakor libanonski stolp, ki gleda proti Damasku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Tvoja glava na tebi je podobna Karmelu in lasje tvoje glave [so] podobni škrlatu; kralj je zadržan v galerijah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Kako lepa in kako prijetna si ti, oh ljubezen, za naslade!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ta tvoja postava je podobna palmovemu drevesu in tvoje prsi grozdom grozdja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Rekel sem: »Šel bom gor k palmovemu drevesu, zgrabil bom njegove veje. Sedaj bodo tudi tvoje prsi kakor grozdi vinske trte in vonj tvojega nosu podoben jabolkom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, '§ in nebo tvojih ust podobno najboljšemu vinu za mojega ljubljenega, ki gre medéno dol, povzročujoč ustnicam tistih, ki spijo, da spregovorijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Jaz sem svojega ljubljenega in njegovo hrepenenje je po meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Pridi, moj ljubljeni, pojdiva na polje, prenočujva v vaseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Vstaniva zgodaj k vinogradom, poglejva, ali trta cveti, ali se pojavlja nežno grozdje in granatna jabolka brste. Tam ti bom dala svoje ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Nadliščki dajejo vonj in pri naših velikih vratih so vse vrste prijetnih sadov, novi in stari, ki sem jih oskrbela zate, oh moj ljubljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Oh, da bi bil kakor moj brat, ki je sesal prsi moje matere! Ko bi te našla zunaj, bi te poljubila, da, ne bi bila prezirana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Vodila bi te in te privedla v hišo svoje matere, ki bi me poučila. Povzročila bi ti, da piješ dišeč vinski sok mojih granatnih jabolk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Njegova leva roka bi bila pod mojo glavo in njegova desnica bi me objela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Naročam vam, oh hčere jeruzalemske, da ne razvnamete niti ne zbudite moje ljubezni, dokler njemu ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kdo je ta, ki prihaja iz divjine, naslonjena na svojega ljubljenega? Dvignil sem te pod jablano; tam te je rodila tvoja mati, tam te je rodila, ki te je nosila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, '§ Postavi me kakor pečat na svoje srce, kakor pečat na svoj laket, kajti ljubezen je močna kakor smrt, ljubosumje je kruto kakor grob. Njegovi ogorki so ognjeno oglje, ki ima najbolj silovit plamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Mnogo vodá ne more pogasiti ljubezni niti je poplave ne morejo potopiti. Če bi človek vse imetje svoje hiše dal za ljubezen, bi bil popolnoma zaničevan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Imamo majhno sestro in ona nima prsi. Kaj bomo storili za svojo sestro na dan, ko jo bodo snubili?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Če bo zid, bomo na njej zgradili srebrno palačo in če bo vrata, jo bomo obdali s cedrovimi deskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Jaz sem zid in moje prsi kakor stolpa. Potem sem bila v njegovih očeh kakor nekdo, ki je našel naklonjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomon je imel vinograd v Báal Hamónu; vinograd je dal v najem čuvajem. Vsak naj bi za njegov sad prinesel tisoč koščkov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Moj vinograd, ki je moj, je pred menoj. Ti, oh Salomon, moraš imeti tisoč, tisti, ki varujejo sad od njega, pa dvesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ti, ki prebivaš v vrtovih, družabniki prisluhnejo tvojemu glasu; pripravi me, da ga slišim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Podvizaj se, moj ljubljeni in bodi podoben srni ali mlademu jelenu na gorah dišav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Videnje Amócovega sina Izaija, ki ga je videl glede Juda in Jeruzalema v dneh Uzíjaha, Jotáma, Aháza in Ezekíja, Judovih kraljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Prisluhnite, oh nebesa in pazljivo prisluhni, oh zemlja, kajti Gospod je spregovoril: »Hranil in vzgojil sem otroke, oni pa so se uprli zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Vol pozna svojega lastnika in osel jasli svojega gospodarja, toda Izrael ne pozna, moje ljudstvo ne preudari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ah, grešen narod, ljudstvo, obloženo s krivičnostjo, seme hudodelcev, otroci, ki so izprijenci. Zapustili so Gospoda, izzivali so Svetega Izraelovega k jezi, odvrnili so se nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Zakaj naj bi bili še udarjani? Spuntali se boste bolj in bolj. Celotna glava je bolna in celotno srce slabi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od podplata stopala celo do glave ni zdravja na njem, temveč rane, modrice in gnojne rane; te niso bile zaprte niti obvezane niti ublažene z mazilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Vaša dežela je zapuščena, vaša mesta so požgana z ognjem. Vaša dežela, tujci jo požirajo v vaši prisotnosti in ta je zapuščena, kakor premagana s tujci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Hči sionska je ostala kakor koča v vinogradu, kakor lopa na kumaričnem vrtu, kakor oblegano mesto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Razen, če nam Gospod nad bojevniki ne bi pustil zelo majhnega ostanka, bi bili kakor Sódoma in podobni bi bili Gomóri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Poslušajte Gospodovo besedo, vi sódomski vladarji, pazljivo prisluhnite postavi našega Boga, ljudstvo gomórsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, '»Za kakšen namen mi je množica vaših klavnih daritev?« govori Gospod: »Sit sem žgalnih daritev ovnov in tolšče pitanih živali in ne razveseljujem se v krvi bikcev ali jagnjet ali kozlov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Ko prihajate, da se pojavite pred menoj, kdo je to zahteval iz vaše roke, da teptate moje dvore?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne prinašajte več praznih daritev; kadilo mi je ogabnost. Mlajev in šabat, sklicevanja zborov ne morem prenašati; to je krivičnost, celo slovesno srečanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vaše mlaje in vaše določene praznike sovraži moja duša. Le-ti so mi obremenitev, naveličal sem se jih prenašati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Ko svoje roke iztezate naprej, bom pred vami skril svoje oči. Da, ko opravljate številne molitve, ne bom poslušal. Vaše roke so polne krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Umijte se, očistite se. Odstranite zlo svojih dejanj izpred mojih oči, prenehajte početi zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Naučite se delati dobro, iščite sodbo, olajšajte zatirane, sodite osirotele, potegujte se za vdovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Pridite torej in skupaj preudarimo,« govori Gospod, »čeprav bi bili vaši grehi kakor škrlat, bodo tako beli kakor sneg; čeprav bi bili rdeči, podobni škrlatnemu [črvu], bodo kakor volna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Če boste voljni in poslušni, boste jedli dobro od dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Toda če odklonite in se uprete, boste požrti z mečem, kajti Gospodova usta so to govorila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Kako je zvesto mesto postalo pocestnica! Bila je polna sodbe, pravičnost je bila nastanjena v njej, toda sedaj morilci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Tvoje srebro je postalo žlindra, tvoje vino pomešano z vodo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'tvoji princi so uporni in družabniki tatov. Vsakdo izmed njih ljubi darila in sledi podkupninam. Osirotelega ne branijo niti pravda vdov ne pride k njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Zato govori Gospod, Gospod nad bojevniki, Mogočni Izraelov: »Ah, žal mi bo mojih nasprotnikov in maščeval se bom nad svojimi sovražniki');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'in svojo roko bom obrnil nadte in z lugom temeljito očistil proč tvojo žlindro in odvzel ves tvoj kositer');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'in povrnil bom tvoje sodnike kakor poprej in tvoje svetovalce, kakor na začetku. Potem boš imenovana: ›Mesto pravičnosti, zvesto mesto.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion bo odkupljen s sodbo in njegovi spreobrnjenci s pravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Uničenje prestopnikov in grešnikov bo hkratno in tisti, ki zapustijo Gospoda, bodo použiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Kajti sramovali se bodo hrastov, ki ste jih želeli in zbegani boste zaradi vrtov, ki ste jih izbrali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Kajti vi boste kakor hrast, čigar list oveni in kakor vrt, ki nima vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Močni bo kakor predivo in njegov izdelovalec kakor iskra in skupaj bosta sežgana in nihče ju ne bo pogasil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Beseda, ki jo je Izaija, Amócov sin, videl glede Juda in Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Zgodilo se bo v poslednjih dneh, da bo gora Gospodove hiše osnovana na vrhu gora in povišana bo nad hribe. In vsi narodi se bodo stekali k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Mnogo ljudstva bo šlo in reklo: »Pridite in pojdimo gor na Gospodovo goro, k hiši Jakobovega Boga. Učil nas bo svojih poti in hodili bomo po njegovih stezah, kajti iz Siona bo izšla postava in Gospodova beseda iz Jeruzalema.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Sodil bo med narodi, oštel bo mnoga ljudstva. Svoje meče bodo prekovali v lemeže in svoje sulice v obrezovalne kavlje. Narod ne bo vzdignil meča zoper narod niti se ne bodo več učili bojevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Oh Jakobova hiša, pridite in hodímo v Gospodovi svetlobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Zatorej si zapustil svoje ljudstvo, Jakobovo hišo, ker so bili izpolnjeni od vzhoda in so napovedovalci usode kakor Filistejci in sebi ugajajo v otrocih tujcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Njihova dežela je polna srebra in zlata niti tam ni konca njihovih zakladov. Njihova dežela je polna konj niti tam ni konca njihovih bojnih voz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Njihova dežela je polna malikov, obožujejo delo svojih lastnih rok, to, kar so naredili njihovi lastni prsti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Zloben človek se priklanja in velik človek se ponižuje, zato jim ne odpusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Vstopi v skalo in se skrij v prahu zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Človekovi vzvišeni pogledi bodo ponižani in oholost ljudi bo upognjena in sam Gospod bo na ta dan povišan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Kajti dan Gospoda nad bojevniki bo nad vsakim, ki je ponosen in vzvišen in nad vsakim, ki je povzdignjen, in ta bo ponižan;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'in nad vsemi libanonskimi cedrami, ki so visoke in povzdignjene in nad vsemi bašánskimi hrasti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'in nad vsemi visokimi gorami in nad vsemi hribi, ki so povzdignjeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'in nad vsakim visokim stolpom in nad vsakim utrjenim zidom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, '§ in na vseh ladjah iz Taršíša in na vseh prijetnih slikah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Nadutost človeka bo upognjena in oholost ljudi bo ponižana. Samo Gospod bo povišan na ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Malike bo popolnoma odpravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Šli bodo v skalne luknje in v zemeljske votline zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva, ko se on vzdiguje, da strašno strese zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Na tisti dan bo človek vrgel svoje malike iz srebra in svoje malike iz zlata, ki so si jih naredili, vsakdo za oboževanje, krtom in netopirjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'da bo šel v skalne razpoke in na vrhove razdrapanih skal, zaradi strahu pred Gospodom in zaradi slave njegovega veličanstva, ko se bo vzdigoval, da strašno strese zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Odvrnite se od človeka, katerega dih je v njegovih nosnicah, kajti v čem je ta cenjen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Kajti glej, Gospod, Gospod nad bojevniki, jemlje proč od Jeruzalema in od Juda, podporo in palico, celotno podporo kruha in celotno podporo vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'mogočnega človeka in bojevnika, sodnika in preroka, razsodnega in starca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'petdesetnika, častitljivega človeka, svetovalca, spretnega rokodelca in zgovornega govornika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Otroke jim bom dal za prince in otročiči bodo vladali nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Ljudstvo bo zatirano, eden od drugega in vsakdo od svojega soseda; otrok se bo ponosno vedel zoper starca in nizek zoper častitljivega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Ko bo človek zgrabil svojega brata iz hiše svojega očeta, rekoč: »Oblačilo imaš, bodi naš vladar in naj bo ta razvalina pod tvojo roko,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'na tisti dan bo ta prisegel, rekoč: »Ne bom ranocelnik, kajti v moji hiši ni niti kruha niti obleke. Ne postavljajte me za vladarja ljudstvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Kajti Jeruzalem je razrušen in Juda je padel, ker so njihov jezik in njihova početja zoper Gospoda, da izzivajo oči njegove slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Prikaz njihovega obličja pričuje zoper njih, ne skrivajo svojega greha, razglašajo ga kakor Sódoma. Gorje njihovi duši! Kajti nagradili so se z zlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Recite pravičnemu, da bo dobro z njim; kajti jedli bodo sad svojih dejanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Gorje zlobnemu! Z njim bo slabo, kajti dana mu bo nagrada njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Kar se tiče mojega ljudstva, so njihovi zatiralci otroci, vladajo pa jim ženske. Oh moje ljudstvo, tisti, ki te vodijo, ti povzročajo, da se motiš in uničujejo pot tvojih steza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Gospod vstaja, da bi se pravdal in stoji, da bi sodil ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Gospod bo stopil na sodbo s starci svojega ljudstva in njegovimi princi, kajti požrli ste vinograd; plen ubogih je v vaših hišah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, '›Kaj nameravate, da lomite moje ljudstvo na koščke in meljete obraze revnih?‹ govori Gospod Bog nad vojskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Poleg tega Gospod govori: ›Ker so hčere sionske ošabne in hodijo z vratovi, iztegnjenimi naprej in poltenimi očmi, hodijo in drobijo medtem ko gredo in zvončkljajo s svojimi stopali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'zato bo Gospod s krasto udaril tême sionskih hčera in Gospod bo odkril njihove skrite dele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Na tisti dan bo Gospod odvzel pogumnost njihovih zvončkljajočih ornamentov okoli njihovih stopal in njihove čepice in njihove okrogle rute, podobne luni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'verižice, zapestnice, šale,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'klobučke, ornamente nog, naglavne trakove, ogrlice, uhane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'prstane, nosne dragocenosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'zamenljive ogrinjalne kostime, plašče, plete, torbice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'zrcala, tanko laneno platno, kapuce in zagrinjala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Zgodilo se bo, da bo namesto prijetnega vonja tam zaudarjanje, namesto pasu vrv, namesto pričeske plešavost, namesto životca opasovanje vrečevine in opeklina namesto lepote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tvoji možje bodo padli pod mečem in tvoji mogočni v vojni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Njena velika vrata bodo žalovala in tulila in ona bo zapuščena sedela na tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Na ta dan bo sedem žensk prijelo enega moškega, rekoč: »Jedle bomo svoj kruh in nosile svoje obleke; samo dovoli nam biti klicane po tvojem imenu, da odvzameš našo grajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Na tisti dan bo Gospodova mladika krasna in veličastna in sad zemlje bo odličen in ljubek za tiste, ki so pobegnili iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Zgodilo se bo, da bo tisti, ki je ostal na Sionu in ki ostaja v Jeruzalemu, imenovan svet, celó vsak, kdor je zapisan med živimi v Jeruzalemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'ko bo Gospod izmil umazanijo sionskih hčera in očistil kri [prestolnice] Jeruzalem iz njene srede, z duhom sodbe in z duhom gorenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'In Gospod bo nad vsakim prebivališčem gore Sion in nad njenimi zbori ustvaril oblak in dim podnevi in svetlikanje plamenečega ognja ponoči, kajti nad vso slavo bo obramba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Tam bo šotorsko svetišče za senco podnevi pred vročino, za prostor zatočišča in za skrivališče pred viharjem in dežjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Torej bom svojemu srčno ljubljenemu zapel pesem o mojem ljubljenem, glede njegovega vinograda. Moj srčno ljubljeni ima vinograd na zelo plodnem hribu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'in ogradil ga je in pobral ven njegove kamne, ga zasadil z izbrano trto, v njegovi sredi zgradil stolp in v njem naredil tudi vinsko stiskalnico in gledal, da bi ta obrodil grozdje, pa je obrodil divje grozdje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'In sedaj, oh prebivalci Jeruzalema in možje iz Juda, sodite, prosim vas, med menoj in mojim vinogradom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Kaj bi bilo lahko več storjeno za moj vinograd, česar nisem storil v njem? Čemu je ta, ko sem gledal, da bi obrodil grozdje, obrodil divje grozdje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Sedaj pojdi, povedal ti bom, kaj bom storil svojemu vinogradu. Odstranil bom njegovo ograjo in ta bo požrt in porušil bom njegovo obzidje in ta bo pomendran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Opustošil ga bom. Ne bo obrezan niti prekopan, temveč bosta tam rasla osat in trnje. Tudi oblakom bom zapovedal, da nanj ne dežujejo več dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Kajti vinograd Gospoda nad bojevniki je Izraelova hiša in Judovi možje so njegov prijetni nasad. Iskal je sodbo, toda glej, zatiranje, za pravičnostjo, toda glej, jok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Gorje tistim, ki priključujejo hišo k hiši, ki postavljajo polje k polju, dokler ni več prostora, da bi bili lahko oni sami nameščeni na sredi zemlje!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'V moja ušesa je Gospod nad bojevniki rekel: »Resnično, mnogo hiš bo zapuščenih, celó velike in lepe, brez prebivalca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Da, deset oralov vinograda bo obrodilo en čeber in seme enega tovora bo obrodilo škaf.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Gorje tistim, ki vstajajo zgodaj zjutraj, da lahko sledijo močni pijači; to nadaljujejo do večera, dokler jih vino ne vname!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Harfa, lira, bobnič, piščal in vino so na njihovih praznovanjih; toda ne ozirajo se na Gospodovo delo niti ne preudarijo delovanja njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Zato je moje ljudstvo odšlo v ujetništvo, ker nimajo spoznanja. Njihovi častitljivi možje so izstradani in njihova množica izsušena z žejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Zato se bo pekel povečal in svoja usta odprl brez mere. Njihova slava, njihova množica, njihov pomp in kdor se razveseljuje, se bo pogreznil vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Zloben človek bo priveden dol, mogočen človek bo ponižan in oči vzvišenih bodo ponižane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'toda Gospod nad bojevniki bo povišan na sodbi in Bog, ki je svet, bo posvečen v pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Potem se bodo jagnjeta pasla po svoji navadi in opustošene kraje debelih bodo pojedli tujci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Gorje tistim, ki krivičnost vlečejo z vrvmi ničnosti in greh vlečejo, kakor bi bilo z garami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'ki pravijo: ›Naj pohiti in pospeši svoje delo, da bomo to lahko videli in naj se nasvet Svetega Izraelovega približa in pride, da bomo to lahko vedeli!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Gorje tistim, ki imenujejo zlo dobro in dobro zlo, ki postavljajo temo za svetlobo in svetlobo za temo, ki postavljajo grenko za sladko in sladko za grenko!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Gorje tistim, ki so modri v svojih lastnih očeh in razsodni v svojem lastnem pogledu!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Gorje tistim, ki so mogočni, da pijejo vino in možje moči, da mešajo močno pijačo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'ki za nagrado opravičijo zlobne in pravičnost pravičnega odvzamejo od njega!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Zatorej kakor ogenj požira strnišče in plamen použiva pleve, tako bo njihova korenina kakor gniloba in njihov cvet se bo dvigal gor kakor prah, ker so odvrgli postavo Gospoda nad bojevniki in prezirali besedo Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Zato je Gospodova jeza vžgana zoper njegovo ljudstvo in svojo roko je iztegnil zoper njih in jih udaril in hribi so trepetali in njihova trupla so bila raztrgana na sredi ulic. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Dvignil bo zastavo narodom iz daljave in požvižgal jim bo od konca zemlje. Glej, naglo bodo prišli s hitrostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Nihče izmed njih ne bo izmučen niti se ne bo spotaknil; nihče ne bo dremal, niti spal, niti pas njihovih ledij ne bo popuščen, niti jermen njihovih čevljev pretrgan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Katerih puščice so ostre in vsi njihovi loki napeti, kopita njihovih konj bodo šteta kakor kremen in njihova kolesa kakor vrtinčast veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Njihovo rjovenje bo podobno levu, rjoveli bodo kakor mladi levi. Da, rjoveli bodo, zgrabili plen in ga varno odnesli proč in nihče ga ne bo osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Na ta dan bodo besneli zoper njih, kakor besni morje in če nekdo pogleda na deželo, zagleda temo in bridkost in svetloba otemni v njegovem nebu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'V letu, ko je kralj Uzíjah umrl, sem videl tudi Gospoda sedeti na prestolu, visokega in dvignjenega in njegova vlečka je napolnila tempelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Nad njim so stali serafi. Vsak je imel šest peruti. Z dvema je pokril svoj obraz in z dvema je pokril svoja stopala in z dvema je letel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Eden je vzklikal drugemu in govoril: »Svet, svet, svet je Gospod nad bojevniki. Celotna zemlja je polna njegove slave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Podboji vrat so se premaknili ob glasu tistega, ki je vpil in hiša je bila napolnjena z dimom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Potem sem rekel: »Gorje meni! Kajti onemel sem, ker sem človek nečistih ustnic in prebivam v sredi ljudstva nečistih ustnic, kajti moje oči so videle kralja, Gospoda nad bojevniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Potem je priletel k meni eden izmed serafov, ki je imel v svoji roki žerjavico, ki jo je s kleščami vzel od oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'To je položil na moja usta in rekel: »Glej, to se je dotaknilo tvojih ustnic in tvoja krivičnost je odvzeta proč in tvoj greh je očiščen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Slišal sem tudi glas od Gospoda, rekoč: »Koga naj pošljem in kdo bo šel za nas?« Potem sem rekel: »Tukaj sem, pošlji mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Rekel je: »Pojdi in povej temu ljudstvu: ›Resnično, poslušajte, toda ne razumite in resnično glejte, pa ne zaznajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Naredi srce tega ljudstva debelo in njihova ušesa naredi težka in zapri njihove oči, da ne bi videli s svojimi očmi in [ne bi] slišali s svojimi ušesi in [ne bi] razumeli s svojim srcem in ne bi bili spreobrnjeni in ne bi bili ozdravljeni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Tedaj sem rekel: »Gospod, doklej?« Odgovoril je: »Dokler ne bodo mesta opustošena, brez prebivalca in hiše brez človeka in ne bo dežela popolnoma zapuščena');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'in Gospod je ljudi odstranil daleč proč in tam bo veliko zapuščanja v sredi dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Toda vendar bo v njej desetina in ta se bo vrnila in bo požrta; kakor terebinta in kakor hrast, katerega snov je v njiju, ko odvržeta svoje listje, tako bo sveto seme snov le-tega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Pripetilo se je v dneh Aháza, Jotámovega sina, Uzíjahovega sina, Judovega kralja, da sta Recín, sirski kralj in Pékah, Remaljájev sin, Izraelov kralj, odšla gor proti Jeruzalemu, da se bojujeta zoper njega, toda nista mogla prevladati zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Davidovi hiši je bilo povedano, rekoč: »Sirija je združena z Efrájimom.« Njegovo srce je vztrepetalo in srce njegovega ljudstva, kakor gozdna drevesa trepetajo v vetru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Potem je Gospod rekel Izaiju: »Pojdi sedaj naprej, da srečaš Aháza, ti in tvoj sin Šeár Jašúb, pri koncu kanala zgornjega ribnika, na glavni cesti pralčevega polja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'in mu reci: ›Pazi se in bodi tiho. Ne boj se niti naj ti srce ne peša zaradi dveh repov teh kadečih kosov tlečega lesa, zaradi krute Recínove jeze s Sirijo in [zaradi] Remaljájevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Ker so Sirija, Efrájim in Remaljájev sin sprejeli hudoben nasvet zoper tebe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '›Pojdimo gor zoper Juda in ga razjezimo in si v njem naredimo vrzel zase in v njegovi sredi postavimo kralja, celó Tabeálovega sina,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'tako govori Gospod Bog: ›To ne bo obstalo niti se to ne bo zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Kajti glava Sirije je Damask in glava Damaska je Recín. V petinšestdesetih letih bo Efrájim zlomljen, da ne bo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Glava Efrájima je Samarija in glava Samarije je Remaljájev sin. Če ne boste verjeli, zagotovo ne boste utrjeni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Poleg tega je Gospod ponovno spregovoril Aházu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '»Izprosi si znamenje od Gospoda, svojega Boga, prosi ga ali v globini ali na višini zgoraj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Toda Aház je rekel: »Ne bom prosil niti ne bom skušal Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'In ta je rekel: »Poslušajte sedaj, oh Davidova hiša: › Ali je za vas malenkost, da izmučite ljudi, toda ali hočete izmučiti tudi mojega Boga?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, '§ Zato vam bo sam Gospod dal znamenje: ›Glejte, devica bo spočela, rodila sina in njegovo ime bo klicala Emanuel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Maslo in med bo jedel, da bo znal odkloniti zlo in izbrati dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Kajti preden bo otrok znal odkloniti zlo in izbrati dobro, bo dežela, ki jo preziraš, postala zapuščena od obeh njunih kraljev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Gospod bo nadte in nad tvoje ljudstvo in nad hišo tvojega očeta privedel dneve, ki niso prišli od dni, ko je Efrájim odšel od Juda, celó asirskega kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Na tisti dan se bo zgodilo, da bo Gospod požvižgal muhi, ki je na najbolj oddaljenem delu egiptovskih rek in čebeli, ki je v asirski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Prišle bodo in vse izmed njih bodo počivale po zapuščenih dolinah, v skalnih jamah, na vsem trnju in po vsem grmovju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Na isti dan bo Gospod obril z britvico, ki je najeta, namreč, s tistimi preko reke, z asirskim kraljem, glavo in dlake stopal in ta bo použila tudi brado.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Na tisti dan se bo zgodilo, da bo človek redil mlado kravo in dve ovci');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'in zgodilo se bo zaradi oblice mleka, ki ga bodo dajale, da bo jedel maslo. Kajti maslo in med bo jedel vsakdo, ki je ostal v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Na tisti dan se bo zgodilo, da bo vsak kraj, kjer je bilo tisoč trt kakor tisoč malih srebrnih kovancev, ta celó za osat in trnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'S puščicami in loki bodo tja prišli možje, ker bo vsa dežela postala osat in trnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Po vseh hribih, ki bodo okopani z motiko, nanje ne bo prišel strah pred osatom in trnjem, temveč bo to za odpošiljanje volov in za teptanje manjše živine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Poleg tega mi je Gospod rekel: »Vzemi si velik zvitek in vanj zapiši s človeškim pisalom glede Mahér Šalál Haš Baza.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'K sebi sem vzel zvesti priči, da zabeležita: duhovnika Urijá in Jeberehjájevega sina Zeharjá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Odšel sem k prerokinji in spočela je ter rodila sina. Potem mi je Gospod rekel: »Njegovo ime kliči Mahér Šalál Haš Baz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Kajti preden bo imel otrok spoznanje, da kliče: ›Moj oče in moja mati,‹ bodo bogastva Damaska in plen Samarije odvzeti pred asirskim kraljem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Gospod mi je prav tako ponovno spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '»Ker kakor to ljudstvo odklanja síloaške vode, ki mirno tečejo in se veselijo v Recínu in Remaljájevemu sinu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'zdaj torej, glej, Gospod prinaša nadnje vode iz reke, močne in številne, celó asirskega kralja in vso njegovo slavo in prestopil bo vse njegove kanale in prestopil vse njegove bregove');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'in šel bo skozi Juda, preplavil bo in šel preko, segel bo celó do vratu in razprostirajoč svoje peruti bo napolnil širino tvoje dežele, oh Emanuel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Povežite se med seboj, oh ve ljudstva in razbiti boste na koščke in pazljivo prisluhnite, vsi vi iz daljnih dežel, opašite se in zlomljeni boste na koščke, opašite se in zlomljeni boste na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Skupaj se posvetujte in to se bo izjalovilo, govorite besedo, pa ta ne bo obstala, kajti Bog je z nami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Kajti Gospod mi je tako govoril z močno roko in me učil, da naj ne hodim po poti tega ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '»Ne reci: ›Zarota,‹ vsem tistim, ki jim bo to ljudstvo reklo: ›Zarota,‹ niti se ne bojte njihovega strahu niti ne bodi prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Posvečujte Gospoda nad bojevniki samega in naj bo on vaš strah in naj bo on vaša groza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'On vam bo svetišče, toda za kamen spotike in za skalo pohujšanja obema Izraelovima hišama, za past in za zanko prebivalcem Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Številni izmed njih se bodo spotaknili, padli, zlomljeni bodo, ujeti v zanko in zajeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Poveži pričevanje, zapečati postavo med mojimi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Čakal bom na Gospoda, ki svoj obraz skriva pred Jakobovo hišo in iskal ga bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Glejte, jaz in otroci, ki mi jih je dal Gospod, smo za znamenja in za čudeže v Izraelu od Gospoda nad bojevniki, ki prebiva na gori Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Ko ti bodo rekli: »Obrni se k tem, ki imajo osebne duhove in k čarovnikom, ki čivkajo in ki mrmrajo. Mar naj ne bi ljudstvo iskalo svojega Boga? Za žive k mrtvim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'K postavi in k pričevanju. Če ne govorijo glede na to besedo, je to zato, ker v njih ni svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Šli bodo skozi to, silno ogorčeni in lačni. In zgodilo se bo, da ko bodo lačni, da se bodo v jezi razburili in preklinjali svojega kralja, svojega Boga in gledali navzgor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Pogledali bodo na zemljo in glej stiska in tema, temačnost tesnobe in gnani bodo v temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Kljub temu temačnost ne bo takšna, kot je bila v njenem draženju, ko je najprej blago stiskal deželo Zábulon in deželo Neftáli in jo je potem bolj boleče stiskal ob poti morja, onkraj Jordana, v poganski Galileji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Ljudstvo, ki je hodilo v temi, je zagledalo veliko svetlobo. Na tiste, ki prebivajo v deželi smrtne sence, je posvetila svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Pomnožil si narod in nisi povečal radosti. Radostijo se pred teboj, v skladu z radostjo ob žetvi in kakor se ljudje veselijo, ko delijo plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Kajti zlomil si jarem njegovega bremena in palico njegovega ramena, palico njegovega zatiralca, kakor na dan Midjána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Kajti vsaka bitka bojevnika je z zmedenim hrupom in oblekami, povaljanimi v krvi, toda ta bo z gorenjem in gorivom ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Kajti nam je rojen otrok, nam je dan sin in oblast bo na njegovem ramenu in njegovo ime bo imenovano Čudoviti, Svetovalec, Mogočni Bog, Večni Oče, Princ miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Povečanju njegovega vladarstva in miru ne bo konca nad Davidovem prestolom in nad njegovim kraljestvom, da to odredi in da to osnuje s sodbo in s pravico od tega časa naprej, celo na veke. Gorečnost Gospoda nad bojevniki bo to izvršila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Gospod je poslal besedo Jakobu in jo vžgal nad Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Vse ljudstvo bo vedelo, celó Efrájim in prebivalec Samarije, ki v ponosu in arogantnosti srca govorijo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '»Opeke so padle, toda mi bomo gradili s klesanimi kamni. Egiptovske smokve so posekane, toda mi jih bomo zamenjali s cedrami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Zato bo Gospod zoper njega postavil Recínove nasprotnike in skupaj združil njegove sovražnike,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'spredaj Sirce in zadaj Filistejce in Izrael bodo požrli z odprtimi usti. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Kajti ljudstvo se ne obrača k tistemu, ki jih udarja niti ne iščejo Gospoda nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Zato bo Gospod v enem dnevu iz Izraela iztrebil glavo in rep, palmovo vejo in ločje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Starec in častitljiv, ta je glava, prerok pa, ki uči laži, ta je rep.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Kajti voditelji tega ljudstva jim povzročajo, da se motijo in tisti, ki so vodeni od njih, so uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Zato Gospod ne bo imel nobene radosti v njihovih mladeničih niti ne bo imel usmiljenja do njihovih sirot in vdov, kajti vsakdo je hinavec in hudodelec in vsaka usta govorijo neumnost. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Kajti zlobnost gori kakor ogenj. Ta bo požrl osat in trnje in vnel gozdne goščave in vzdignili se bodo kakor vzdigovanje dima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Preko besa Gospoda nad bojevniki je dežela zatemnjena in ljudstvo bo kakor gorivo ognju. Noben človek ne bo prizanesel svojemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Hlastal bo na desnici in bo lačen, jedel bo na levici, pa ne bodo nasičeni. Vsak človek bo jedel meso svojega lastnega lakta:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manáse Efrájima in Efrájim Manáseja in skupaj bosta zoper Juda. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Gorje tistim, ki razglašajo krivične odloke in ki pišejo muko, ki so jo predpisali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'da odvrnejo pomoči potrebnega stran od sodbe in da odvzamejo pravico od revnega izmed mojega ljudstva, da bi bile lahko vdove njihov plen in da lahko oropajo osirotelega!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Kaj boste storili na dan obiskanja in v opustošenju, ki bo prišlo od daleč? H komu boste pobegnili po pomoč? In kje boste pustili svojo slavo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Brez mene se bodo sklonili pod ujetniki in padli bodo pod umorjenimi. Zaradi vsega tega njegova jeza ni odvrnjena, temveč je njegova roka še vedno iztegnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Oh Asirec, šiba moje jeze in palica v njihovi roki je moje ogorčenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Poslal ga bom zoper hinavski narod in zoper ljudstvo mojega besa mu bom dal zadolžitev, da vzame ukradeno blago, da vzame plen in da jih potepta kakor ulično blato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Vendar on ne meni tako niti njegovo srce ne misli tako, temveč je na njegovem srcu to, da uniči in iztrebi ne malo narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Kajti on pravi: » Mar niso moji princi vsi skupaj kralji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Mar ni Kalne kakor Kárkemiš? Mar ni Hamát kakor Arpád? Mar ni Samarija kakor Damask?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Kakor je moja roka našla kraljestva malikov in katerih rezane podobe so nadkriljevale te iz Jeruzalema in iz Samarije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'mar ne bom, kakor sem storil Samariji in njenim malikom, tako storil Jeruzalemu in njegovim malikom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Kjerkoli se bo to pripetilo, da ko Gospod opravi svoje celotno delo na gori Sion in v Jeruzalemu, bom kaznoval sad arogantnega srca asirskega kralja in slavo njegovih vzvišenih pogledov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Ker pravi: › To sem storil z močjo svoje dlani in s svojo modrostjo, ker sem razsoden. Ljudstvu sem odstranil meje in oropal njihove zaklade in kakor hraber človek ponižal prebivalce');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'in moja roka je našla kakor gnezdo bogastva ljudstev; in kakor nekdo zbira jajca, ki so ostala, sem jaz zbral vso zemljo in nikogar ni bilo, ki bi zganil perut ali odprl usta ali začivkal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Mar se bo sekira bahala pred tistim, ki z njo seka? Mar se bo žaga poveličevala pred tistim, ki jo vleče? Kakor če bi se palica tresla pred tistim, ki jo vzdiguje, ali kakor če bi se palica sama vzdigovala, kakor če ne bi bila les.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Zato bo Gospod, Gospod nad bojevniki, med njegove rejene poslal pustost in pod njegovo slavo bo vžgal gorenje, podobno gorenju ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Izraelova svetloba bo za ogenj in njegov Sveti za plamen in ta bo gorel in v enem dnevu bo pogoltnil njegovo trnje in njegove osate');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, '§ in použil bo slavo njegovega gozda in njegovega rodovitnega polja, tako dušo kakor telo in oni bodo kakor kadar nosilec prapora slabi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Preostanka dreves njegovega gozda bo malo, da jih lahko otrok zapiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Na tisti dan se bo zgodilo, da se Izraelov ostanek in tisti, ki so pobegnili od Jakobove hiše, ne bodo več ponovno naslanjali nanj, ki jih je udaril, temveč se bodo v resnici naslanjali na Gospoda, Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Preostanek se bo vrnil, celó Jakobov preostanek, k mogočnemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Kajti čeprav bo tvojega ljudstva Izraela kakor morskega peska, se bo vendar ostanek izmed njih vrnil. Odrejeno uničenje bo preplavljeno s pravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Kajti Gospod Bog nad bojevniki bo naredil uničenje, celo določeno, v sredi vse dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Zato tako govori Gospod Bog nad bojevniki: ›Oh moje ljudstvo, ki prebivaš na Sionu, ne boj se Asirca. Udaril te bo s palico in svojo palico bo vzdignil zoper tebe po načinu Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Kajti še zelo kratek čas in ogorčenje bo prenehalo in moja jeza v njihovem uničenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Gospod nad bojevniki bo zanj razvnel bič, glede na pokol Midjána, pri Orébovi skali in kakor je bila njegova palica nad morjem, tako jo bo vzdignil po načinu Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Na tisti dan se bo zgodilo, da bo njegovo breme vzeto iz tvoje rame in njegov jarem iz tvojega vratu in jarem bo uničen zaradi maziljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Prišel je v Ajo, prešel je do Migróna, pri Mihmášu je shranil svoje vozove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Šli so preko prelaza. Pri Gebi so se nastanili, Rama je prestrašena, Savlova Gíbea je zbežala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Povzdigni svoj glas, oh hči galímska. Povzroči mu, da bo ta slišan do Láješa, oh ubogi Anatót.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madménah je odstranjen, prebivalci Gebíma so se zbrali skupaj, da pobegnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Ta dan bo ostal pri Nobu. Svojo roko bo stresel zoper goro hčere sionske, jeruzalemski hrib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Glej, Gospod, Gospod nad bojevniki, bo vejo obrezal s strahoto in tisti z visoko postavo bodo posekani in ošabni bodo ponižani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Z železom bo posekal gozdne goščave in Libanon bo padel po mogočnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Palica bo pognala iz Jesejevega debla in Poganjek bo zrastel iz njegovih korenin');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'in Gospodov duh bo počival nad njim, duh modrosti in razumevanja, duh nasveta in moči, duh spoznanja in strahu Gospodovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Naredil ga bo hitrega razumevanja v strahu Gospodovem in ne bo sodil po pogledu svojih oči niti grajal po slišanju svojih ušes,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'temveč bo s pravičnostjo sodil revne in odločal z nepristranskostjo krotkim na zemlji in zemljo bo udaril s palico svojih ust in z dihom svojih ustnic bo pokončal zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Pravičnost bo pas njegovih ledij in zvestoba pas njegovih notranjosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Tudi volk bo prebival z jagnjetom in leopard se bo zleknil z otrokom. Tele, mlad lev in pitanček skupaj in vodil jih bo majhen otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Krava in medvedka se bosta pasli, njuni mladiči se bodo skupaj ulegli in lev bo jedel slamo kakor vol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Doječ otrok se bo igral na kobrini luknji in odstavljen otrok bo svojo roko položil na brlog strupene kače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ne bodo ne škodovali, ne uničevali na vsej moji sveti gori, kajti zemlja bo polna Gospodovega spoznanja, kakor vode pokrivajo morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Na ta dan bo Jesejeva korenina, ki bo stala kakor zastava ljudstvu; njo bodo pogani iskali in njegov počitek bo veličasten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Na tisti dan se bo zgodilo, da bo Gospod ponovno, drugič, naravnal svojo roko, da obnovi preostanek svojega ljudstva, ki bo preostal od Asirije, od Egipta, od Patrósa, od Kuša, od Eláma, od Šinárja, od Hamáta in od morskih otokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Postavil bo zastavo za narode in zbral Izraelove pregnance in skupaj bo zbral razkropljene od Juda iz štirih koncev zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Tudi Efrájimova zavist bo odšla in Judovi nasprotniki bodo iztrebljeni. Efrájim ne bo zavidal Judu in Juda ne bo nadlegoval Efrájima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Temveč bodo leteli na ramenih Filistejcev proti zahodu. Skupaj bodo oplenili tiste iz vzhoda, svojo roko bodo položili na Edóm in Moáb in Amónovi otroci jih bodo ubogali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, '§ Gospod bo popolnoma uničil jezik egiptovskega morja in s svojim mogočnim vetrom bo stresel svojo roko nad reko in udaril jo bo v sedem vodotokov in ljudem omogočil, da jih bodo prešli v sandalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Tam bo glavna cesta za preostanek njegovega ljudstva, ki bo preostalo od Asirije, kakor je bila za Izrael na dan, ko je prišel gor iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Na ta dan boš rekel: »Oh Gospod, hvalil te bom. Čeprav si bil jezen name, je tvoja jeza odvrnjena in me ti tolažiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Glej, Bog je rešitev moje duše. Zaupal bom in ne bom prestrašen, kajti Gospod Jahve je moja moč in moja pesem; prav tako je postal rešitev moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Zatorej boste z radostjo zajemali vodo iz vodnjakov rešitve duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Na ta dan boste rekli: »Hvalimo Gospoda, kličimo njegovo ime, med ljudstvom razglašajmo njegova dela, omenjajmo, da je njegovo ime povišano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Prepevajmo Gospodu, kajti storil je odlične stvari. To je znano po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Zavriskaj in zavpij, ti prebivalec Siona, kajti velik je Sveti Izraelov v tvoji sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Breme Babilona, ki ga je videl Izaija, Amócov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Dvignite prapor na visoki gori, povzdignite jim glas, mahajte z roko, da lahko vstopijo v velika vrata plemičev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Svojim posvečenim sem zapovedal, zaradi moje jeze sem poklical tudi moje mogočne, celó tiste, ki se razveseljujejo v mojem visočanstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Hrup množice po gorah kakor od številnega ljudstva, bučen hrup kraljestev narodov, zbranih skupaj. Gospod nad bojevniki pregleduje vojsko za bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Prihajajo iz daljne dežele, od konca neba, celó Gospod in orožja njegovega ogorčenja, da uničijo celotno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Tulite, kajti Gospodov dan je pri roki, ta bo prišel kakor uničenje od Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Zato bodo vse roke oslabele in srce vsakega človeka se bo stopilo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'in bali se bodo. Ostre bolečine in bridkosti se jih bodo polastile. V bolečinah bodo kakor ženska, ki je v porodnih mukah. Osupli bodo drug nad drugim, njihovi obrazi bodo kakor plameni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Glej, prihaja Gospodov dan, krut, z besom in silovito jezo, da naredi deželo opustošeno in njene grešnike bo pokončal iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Kajti zvezde neba in njegova ozvezdja ne bodo dajala svoje svetlobe. Sonce bo otemnelo v svojem vzhajanju in luna svoji svetlobi ne bo povzročila, da sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Zemeljski [krog] bom kaznoval zaradi njihovega zla in zlobne zaradi njihove krivičnosti in povzročil bom, da se aroganca ponosnih konča in ponižal bom oholost strašnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Človeka bom naredil dragocenejšega kakor čisto zlato, celo človeka kakor zlat klin iz Ofírja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Zato bom stresel nebo in zemlja se bo odmaknila iz svojega mesta, v besu Gospoda nad bojevniki in na dan njegove krute jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'In bo kakor preganjana srna in kakor ovca, ki je nihče ne ujame. Obrnili se bodo vsak človek k svojemu lastnemu ljudstvu in vsak bo bežal v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Vsak, kdor je najden, bo preboden in vsak, kdor jim je pridružen, bo padel pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Tudi njihovi otroci bodo razbiti na koščke pred njihovimi očmi, njihove hiše bodo oplenjene in njihove žene posiljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Glej, zoper njih bom razvnel Medijce, ki se ne bodo ozirali na srebro in glede zlata, v njem se ne bodo razveseljevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Tudi njihovi loki bodo mladeniče raztreščili na koščke in ne bodo imeli usmiljenja do sadu maternice; njihovo oko ne bo prizaneslo otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Babilon, slava kraljestev, lepota kaldejske odličnosti, bo kakor, ko je Bog razdejal Sódomo in Gomóro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Ta ne bo nikoli naseljen niti se ne bo prebivalo v njem od roda do roda, niti tam Arabec ne bo postavil šotora, niti tam pastirji ne bodo postavljali svojih staj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Temveč bodo tam ležale divje puščavske živali in njihove hiše bodo polne otožnih živih ustvarjenih bitij in sove bodo prebivale tam in kozjenogi bodo tam plesali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Divje živali z otokov bodo klicale v njihovih zapuščenih hišah in zmaji v njihovih prijetnih palačah in njen čas je blizu, da pride in njeni dnevi ne bodo podaljšani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Kajti Gospod bo imel usmiljenje do Jakoba in bo še izbral Izrael in jih postavil v njihovo lastno deželo, in tujci bodo združeni z njimi in se bodo trdno pridružili Jakobovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Ljudstvo jih bo vzelo in jih privedlo na njihov kraj. Izraelova hiša jih bo vzela v last v Gospodovi deželi za služabnice in pomočnice. Odvedli jih bodo ujete tisti, katerih ujetniki so bili in vladali bodo nad svojimi zatiralci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Na ta dan se bo zgodilo, ko ti bo Gospod dal počitek pred tvojo bridkostjo, pred tvojim strahom in pred trdim suženjstvom, s čimer si bil primoran, da služiš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'da boš vzel ta pregovor zoper babilonskega kralja in rekel: »Kako je zatiralec končal! Zlato mesto je končalo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Gospod je zlomil palico zlobnih in žezlo vladarjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Tisti, ki je v besu udaril ljudstvo z nenehnim udarcem, tisti, ki je narodom vladal v jezi, je preganjan in nihče ne zadržuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Celotna zemlja je pri počitku in mirna. Oni izbruhnejo v petje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Da, ciprese se razveseljujejo ob tebi in libanonske cedre, rekoč: ›Odkar si položen dol, noben sekalec ni prišel zoper nas.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Pekel od spodaj vztrepetava zaradi tebe, da te sreča ob tvojem prihodu. Zaradi tebe razvnema mrtve, celó vse zemeljske vodje, iz njihovih prestolov je dvignil vse kralje narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Vsi ti bodo govorili in ti rekli: ›Si tudi ti postal slaboten kakor mi? Si postal podoben nam?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Tvoj pomp je priveden dol h grobu in zvok tvojih lir. Ličinka se razteguje pod teboj in ličinke te pokrivajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, '§ Kako si padel z neba, oh Lucifer, sin jutra! Kako si posekan na tla, ki si narode slabil!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Ker si rekel v svojem srcu: ›Vzpel se bom v nebesa, svoj prestol bom povzdignil nad Božje zvezde. Tudi na gori skupnosti bom sedel, na obronkih severa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'nad višine oblakov se bom dvignil, podoben bom Najvišjemu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Vendar boš priveden dol v pekel, na obronke jame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Tisti, ki te vidijo, te bodo natančno ogledovali in preudarjali, rekoč: ›Mar je to mož, ki je počel, da je zemlja trepetala, ki je pretresal kraljestva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'ki je naredil zemeljski [krog] kakor divjino in uničil njegova mesta, ki ni odprl hiše svojih ujetnikov?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Vsi kralji narodov, celó vsi izmed njih, ležijo v slavi, vsak v svoji lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Ti pa si izvržen iz svojega groba, kakor gnusna mladika in kakor oblačilo tistih, ki so umorjeni, prebodeni z mečem, ki gredo dol k jamskim kamnom, kakor truplo, pomendrano pod stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Ne boš pridružen z njimi pri pokopu, ker si uničil svojo deželo in umoril svoje ljudstvo. Seme hudodelcev nikoli ne bo ugledno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Pripravite pokol za njegove otroke zaradi krivičnosti njihovih očetov, da ne vstanejo niti ne vzamejo v last dežele niti ne napolnijo obličja zemeljskega [kroga] z mesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Kajti dvignil se bom proti njim,‹ govori Gospod nad bojevniki ›in iztrebil iz Babilona ime in ostanek, sina in nečaka,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '›Prav tako ga bom naredil posest za bobnarico in vodne tolmune in pometel ga bom z metlo uničenja,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Gospod nad bojevniki je prisegel, rekoč: ›Zagotovo, kakor sem si zamislil, tako se bo zgodilo in kakor sem se namenil, tako bo ostalo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'da bom v svoji deželi zlomil Asirca in na svojih gorah ga bom pomendral pod stopalom. Potem bo njegov jarem odšel od njih in njegovo breme bo odšlo iz njihovih ramen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'To je namen, ki je namenjen nad celotno zemljo, in to je roka, ki je iztegnjena nad vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Kajti Gospod nad bojevniki se je namenil in kdo bo to razveljavil? Njegova roka je iztegnjena in kdo jo bo zavrnil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'To breme je bilo v letu, ko je kralj Aház umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne razveseli se ti, celotna Filisteja, ker je palica tistega, ki te je udaril, zlomljena, kajti iz kačje korenine bo prišla strupena kača in njen sad bo ognjena leteča kača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Prvorojenec revnega bo nahranjen in pomoči potreben se bo ulegel v varnosti in z lakoto bom ubil tvojo korenino, on pa bo pokončal tvoj preostanek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Tulite, oh velika vrata, jokaj, oh mesto, ti, celotna Palestina si raztopljena, kajti iz severa bo prišel dim in nihče ne bo sam v svojih določenih časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Kaj bo nekdo potem odgovoril poslancem naroda? Da je Gospod ustanovil Sion in revni izmed njegovega ljudstva bodo zaupali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Breme Moába. Ker je ponoči Ar Moáb opustošen in priveden v tišino, ker je ponoči Kir Moáb opustošen in priveden v tišino;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, '§ odšel je gor do Bajita in do Dibóna, visoka kraja, da bi jokal. Moáb bo tulil nad Nebójem in nad Médebo, na vseh njihovih glavah bo plešavost in vsaka brada bo odrezana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Na njihovih ulicah se bodo opasovali z vrečevino, na vrhovih njihovih hiš in na njihovih ulicah bo vsakdo tulil, obilno jokajoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hešbón bo vpil in Elalé. Njun glas bo slišati celó do Jahaca, zato bodo oboroženi moábski vojaki zavpili, njegovo življenje mu bo mučno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Moje srce bo vpilo zaradi Moába, njegovi ubežniki bodo bežali do Coarja, telica starosti treh let, kajti ob vzpenjanju Luhíta bodo jokajoč šli gor, kajti na poti Horonájima bodo vzdignili krik pogube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Kajti vode Nimríma bodo zapuščene, kajti seno je propadlo, trava je posušena, tam ni nobene zelene stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Zato bodo obilje, ki so ga dobili in to, kar so nakopičili, odnesli proč k vrbovemu potoku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Kajti vpitje je šlo naokoli Moábovih mej, njihovo tuljenje do Eglájima in njihovo tuljenje do Beêr Elíma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Kajti vode Dimóna bodo polne krvi, kajti privedel bom več nad Dimón, leve nad tiste, ki pobegnejo iz Moába in nad preostanek dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Pošljite jagnje k vladarju dežele iz Sele k divjini, h gori hčere sionske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Kajti zgodilo se bo, da kakor je tavajoč ptič vržen iz gnezda, tako bodo moábske hčere pri prehodih Arnóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Posvetuj se, izvrši sodbo, svojo senco naredi kakor noč v sredi opoldneva, skrij pregnance, ne izdaj tistega, ki tava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Naj moji pregnanci prebivajo s teboj, Moáb. Bodi jim skrivališče pred obličjem plenilca. Izsiljevalec je pri koncu, plenilec pojenjuje, kajti zatiralci so použiti iz dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'V usmiljenju bo prestol postavljen in sedel bo na njem v resnici, v Davidovem šotorskem svetišču, sodeč, iščoč sodbe in pospešujoč pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Slišali smo o Moábovem ponosu; zelo je ponosen, celó o njegovi oholosti in njegovem ponosu in njegovem besu, toda njegove laži ne bodo takšne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Zato bo Moáb tulil za Moábom, vsi bodo tulili, kajti temelji Kir Heresa bodo žalovali; zagotovo so udarjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Kajti hešbónska polja pešajo in vino iz Sibme. Gospodarji poganov so zlomili njegove glavne sadike, prišli so celó do Jazêrja, tavali so skozi divjino. Njegovi poganjki se iztezajo, odšli so preko morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Zato bom z jokom objokoval sibmansko trto iz Jazêrja. Namakal te bom s svojimi solzami, oh Hešbón in Elaléja, zaradi vpitja za tvojimi poletnimi sadovi in ker je tvoja žetev propadla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Veselje je odvzeto in radost iz obilnega polja in v vinogradih ne bo prepevanja niti ne bo vriskanja niti tam ne bo vpitja. Tlačitelji ne bodo tlačili nobenega vina v svojih stiskalnicah; njihovemu vriskanju ob trgatvi sem naredil, da odneha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Zato bo moja notranjost zvenela kakor harfa za Moábom in moji notranji deli za Kir Heresom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'In zgodilo se bo, ko bo videno, da je Moáb izmučen na visokih krajih, da bo prišel k svojemu svetišču, da moli, toda ne bo prevladal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'To je beseda, ki jo je od tistega časa Gospod govoril glede Moába.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Toda sedaj je Gospod govoril, rekoč: »Znotraj treh let, kakor so najemnikova leta in Moábova slava bo zaničevana z vso tisto veliko množico in preostanek bo zelo majhen in slaboten.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Breme Damaska: »Glej, Damask je odvzet od tega, da je mesto in bo kup razvalin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Mesta Aroêrja so zapuščena. Ta bodo za trope, ki bodo legli in nihče jih ne bo strašil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Trdnjava bo prav tako prenehala od Efrájima in kraljestvo od Damaska in preostanek iz Sirije. Oni bodo kakor slava Izraelovih otrok,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, '»Na tisti dan se bo zgodilo, da se bo Jakobova slava stanjšala in mastnost njegovega mesa bo shujšala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'To bo kakor ko žanjec zbira žito in s svojim laktom žanje klasje, in to bo kakor tisti, ki zbira klasje v dolini Rafájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Vendar bodo v njem ostali paberkovalni grozdi, kakor tresenje oljke, dve ali tri jagode na vrhu najvišje veje, štiri ali pet na njenih zunanjih rodovitnih mladikah,« govori Gospod, Izraelov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Na tisti dan bo človek gledal k svojemu Stvarniku in njegove oči bodo imele spoštovanje do Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Ne bo gledal k oltarjem, delu svojih rok niti ne bo spoštoval tega, kar so naredili njegovi prsti ali ašer ali podob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Na tisti dan bodo njegova utrjena mesta kakor zapuščena veja in najvišja mladika, ki so jo pustili zaradi Izraelovih otrok in tam bo opustošenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Ker si pozabil Boga rešitve svoje duše in se nisi spominjal skale svoje moči, zato boš sadil prijetne rastline in jih cepil s tujimi cepljenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Podnevi boš svoji rastlini naredil, da zraste in zjutraj boš svojemu semenu naredil, da cveti, toda žetev bo kup na dan žalosti in obupne bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Gorje množici številnih ljudi, ki zganjajo hrup, podoben hrupu morij in vrvežu narodov, ki delajo vrvež, podoben vrvežu mogočnih vodá!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Narodi bodo hiteli kakor besnenje mnogih vodá, toda Bog jih bo ukoril in pobegnili bodo daleč proč in pregnani bodo kakor pleve gora pred vetrom in kakor kotaleča se stvar pred vrtinčastim vetrom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Glej, ob večernem času stiska in pred jutrom ga ni. To je delež tistih, ki nas plenijo in žreb tistih, ki nas ropajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Gorje deželi, zasenčeni s perutmi, ki je onkraj etiopskih rek,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, '§ ki pošilja predstavnike po morju, celo v posodah iz ločja na vodah, rekoč: »Pojdite, vi nagli poslanci, k narodu, razkropljenemu in razgaljenemu, k ljudstvu, strašnemu od njihovega začetka do zdaj; narodu razdeljenemu in pomendranemu, katerega deželo so oplenile reke!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vsi vi naseljenci zemeljskega [kroga] in prebivalci na zemlji, glejte, ko dviguje zastavo na gorah in ko zatrobi na šofar, prisluhnite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Kajti tako mi je rekel Gospod: ›Vzel si bom počitek in preudaril bom v svojem bivališču, kakor sončna vročina na rastlinah in kakor oblak rose v vročini žetve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, '§ Kajti pred žetvijo, ko je brst popoln in kislo grozdje dozoreva v cvetu, bo z obdelovalnimi kavlji odrezal tako poganjke, kakor odvzel in odrezal mladike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Skupaj bodo prepuščeni perjadi gora in zemeljskim živalim, in perjad bo na njih preživela čas žetve in vse zemeljske živali bodo prezimovale na njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'V tistem času bo prineseno darilo Gospodu nad bojevniki, od ljudstva, razkropljenega in razgaljenega in od ljudstva, ki je strašno od svojega začetka do sedaj, naroda, ki je razdeljen in pomendran pod stopalom, katerega deželo so oplenile reke, do kraja imena Gospoda nad bojevniki, gore Sion.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Breme Egipta. Glej, Gospod jaha na naglem oblaku in prišel bo v Egipt in egiptovski maliki bodo drhteli ob njegovi prisotnosti in srce Egipta se bo stopilo v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, '»Egipčane bom naravnal zoper Egipčane in bojevali se bodo vsak zoper svojega brata in vsak zoper svojega soseda, mesto zoper mesto in kraljestvo zoper kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Egiptovski duh bo odpovedal v njihovi sredi in uničil bom njihov nasvet in iskali bodo k malikom in h krotilcem in k tistim, ki imajo osebne duhove in k čarovnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Egipčane bom predal v roko krutega gospodarja in silovit kralj bo vladal nad njimi,« govori Gospod, Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Vode iz morja se bodo posušile in reke bodo zapuščene in posušene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Reke bodo obrnili daleč proč in obrambni jarki bodo izpraznjeni ter posušeni. Trstje in rogoz bo ovenelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, '§ Papirno trstje pri potokih, pri ustju potokov in vsaka posejana stvar ob potokih bo ovenela, bo odgnana in ne bo je več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Tudi ribiči bodo žalovali in vsi tisti, ki mečejo trnek v potoke, bodo žalovali in tisti, ki razširjajo mreže nad vodami, bodo pešali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Poleg tega bodo zbegani tisti, ki delajo s tankim lanom in tisti, ki tkejo mreže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, '§ Zlomljeni bodo v svojih namenih vsi, ki delajo zapornice in ribnike za ribe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Zagotovo so princi Coana bedaki, nasvet modrih faraonovih svetovalcev je postal brutalen. Kako pravite faraonu: »Jaz sem sin modrega, sin starodavnih kraljev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kje so tisti? Kje so tvoji modri možje? In naj ti sedaj povedo in naj vedo kaj je Gospod nad bojevniki namenil nad Egiptom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Princi Coana so postali bedaki, princi Nofa so zavedeni, zapeljali so tudi Egipt, celó tiste, ki so opora njegovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Gospod je v njihovo sredo pomešal sprevrženega duha in Egiptu so storili, da se moti v vsakem svojem delu, kakor se pijan mož opoteka v svojem bruhanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Niti tam ne bo nobenega dela za Egipt, ki bi ga glava ali rep, palmova veja ali ločje lahko opravili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Na tisti dan bo Egipt podoben ženski in bo prestrašen in bal se bo zaradi tresenja roke Gospoda nad bojevniki, ki jo trese nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Judova dežela bo strahota Egiptu. Vsak, kdor jo omenja, bo v sebi prestrašen zaradi namena Gospoda nad bojevniki, ki ga je določil zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, '§ Na tisti dan bo pet mest v egiptovski deželi govorilo kánaanski jezik in prisegalo pri Gospodu nad bojevniki; eno bo imenovano Mesto uničenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Na tisti dan bo tam oltar Gospodu v sredi egiptovske dežele in steber Gospodu pri njegovi meji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Ta bo za znamenje in za pričevanje Gospodu nad bojevniki v egiptovski deželi, kajti klicali bodo h Gospodu zaradi zatiralcev in poslal jim bo rešitelja in mogočnega in ta jih bo osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Gospod bo znan Egiptu in Egipčani bodo na tisti dan poznali Gospoda in opravljali klavno daritev in darovanje. Da, prisegali bodo prisego h Gospodu in jo izvedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Gospod bo udaril Egipt. Udaril ga bo in ozdravil in vrnili se bodo celó h Gospodu in izprošen bo od njih in jih bo ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Na tisti dan bo tam glavna cesta iz Egipta v Asirijo in Asirec bo prišel v Egipt in Egipčan v Asirijo in Egipčani bodo služili z Asirci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Na tisti dan bo Izrael tretji z Egiptom in Asirijo, celó blagoslov v sredi dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'ki ga bo Gospod nad bojevniki blagoslovil, rekoč: »Blagoslovljen bodi Egipt, moje ljudstvo in Asirija, delo mojih rok in Izrael, moja dediščina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, '§ V letu, ko je Tartan prišel v Ašdód (ko ga je asirski kralj Sargon poslal) in se boril zoper Ašdód in ga zavzel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'ob istem času je spregovoril Gospod po Izaiju, Amócovemu sinu, rekoč: »Pojdi in odveži vrečevino s svojih ledij in sezuj si čevelj s svojega stopala.« In storil je tako, hodeč nag in bos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Gospod je rekel: »Podobno kot moj služabnik Izaija tri leta hodi nag in bos za znamenje in čudo nad Egiptom in nad Etiopijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'tako bo asirski kralj odvedel Egipčane ujetnike in Etiopijce ujetnike, mlade in stare, nage in bose, celo z njihovimi nepokritimi zadnjicami, v egiptovsko sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Bali se bodo in osramočeni bodo od Etiopije, njihovega pričakovanja in od Egipta, njihove slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Prebivalec tega otoka bo na tisti dan rekel: ›Glej, takšno je naše pričakovanje, kamor smo pobegnili po pomoč, da bi bili osvobojeni pred asirskim kraljem in kako bomo pobegnili?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Breme puščave morja. Kakor gredo skozi vrtinčasti vetrovi na jugu, tako ta prihaja iz puščave, iz strašne dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Mučno videnje mi je naznanjeno, zahrbtnež postopa zahrbtno in plenilec pleni. Pojdi gor, oh Elám. Oblegaj, oh Medija. Vsemu njihovemu vzdihovanju sem storil, da preneha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Zato so moja ledja napolnjena z bolečino. Polastile so se me ostre bolečine kakor ostre bolečine ženske, ki je v porodnih mukah. Sklonjen sem bil ob poslušanju tega, ob gledanju tega sem bil zaprepaden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Moje srce trepeta, grozljivost me je preplašila. Noč mojega užitka mi je obrnil v strah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Pripravite mizo, stražite v stražnem stolpu, jejte, pijte. Vstanite, vi princi in pomazilite ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Kajti tako mi je rekel Gospod: »Pojdi, postavi stražarja, naj razglasi, kar vidi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Ta je zagledal bojni voz z nekaj konjeniki, voz z osli in voz s kamelami in marljivo prisluhnil z mnogo pozornosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'ter zavpil: »Lev. ›Moj Gospod, nenehno stojim na stražnem stolpu podnevi in na svojo stražo sem postavljen cele noči');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'in glej, sem prihaja bojni voz z možmi, z nekaj konjeniki.‹« Odgovoril je in rekel: »Babilon je padel, padel je in vse rezane podobe njegovih bogov je zdrobil na tla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Oh moja mlatev in žito mojih tal. To, kar sem slišal od Gospoda nad bojevniki, Izraelovega Boga, sem vam naznanil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Breme o Dumi. Kliče me iz Seírja: »Stražar, kaj je glede noči? Stražar, kaj je glede noči?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Stražar je rekel: »Prihaja jutro in tudi noč. Če hočete poizvedeti, poizvejte. Vrnite se, pridite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Breme nad Arabijo. V arabskem gozdu boste prenočevale, oh ve, potujoče skupine Dedánovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Prebivalci dežele Temá so prinesli vodo tistemu, ki je bil žejen. Tistega, ki je bežal, so prestregli s svojim kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Kajti pobegnili so pred meči, pred izvlečenim mečem, pred napetim lokom in pred bolečino vojne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Kajti tako mi je rekel Gospod: »Znotraj leta, glede na najemnikova leta in vsa slava Kedárja bo padla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Preostanek izmed števila lokostrelcev, močni možje izmed kedárskih otrok, bodo zmanjšani,« kajti Gospod, Izraelov Bog, je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Breme doline videnj. Kaj te sedaj pesti, da si v celoti odšel gor k hišnim streham?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Ti, ki si poln razgrajanja, hrupno mesto, radostno mesto. Tvoji umorjeni možje niso umorjeni z mečem niti niso umrli v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Vsi tvoji vladarji so skupaj pobegnili. Zvezani so z lokostrelci. Vsi, ki so najdeni v tebi, so zvezani skupaj, ki so pobegnili od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Zatorej sem rekel: »Poglejte proč od mene, grenko bom jokal, ne trudite se, da bi me potolažili zaradi plenjenja hčere mojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Kajti to je dan stiske, mendranja in zmedenosti od Gospoda Boga nad bojevniki v dolini videnja, podiranja zidov in vpitja h goram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elám je nosil tul z bojnimi vozovi mož in konjeniki in Kir je odkril ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'In zgodilo se bo, da bodo tvoje izbrane doline polne vozov in konjeniki se bodo postrojili pri velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Odkril je Judovo pokrivalo in na tisti dan si pogledal k bojni opremi gozdne hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Videli ste tudi vrzeli Davidovega mesta, da jih je mnogo in zbrali ste skupaj vode spodnjega ribnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Prešteli ste jeruzalemske hiše in porušili hiše, da utrdite obzidje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Naredili ste tudi jarek med dvema zidovoma za vodo iz starega ribnika, toda niste pogledali k njegovemu izdelovalcu niti niste imeli spoštovanja do tistega, ki ga je dolgo nazaj oblikoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Na tisti dan je Gospod Bog nad bojevniki klical k jokanju, žalovanju, k plešavosti in k opasovanju z vrečevino');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'in glej, radost in veselje, klanje volov in ubijanje ovc, žrtje mesa in pitja vina. Jejmo in pijmo, kajti jutri bomo umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'To je bilo razodeto v moja ušesa po Gospodu nad bojevniki: »Zagotovo ta krivičnost ne bo očiščena od vas, dokler ne umrete,« govori Gospod Bog nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tako govori Gospod Bog nad bojevniki: »Pojdi, stopi k temu zakladniku, celó k Šebnáju, ki je nad hišo in reci:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '›Kaj imaš tukaj? In koga imaš tukaj, da si si tukaj izklesal mavzolej kakor kdor si kleše mavzolej na višavi in ki zase vrezuje prebivališče v skali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Glej, Gospod te bo odvedel proč z mogočnim ujetništvom in zagotovo te bo pokril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Zagotovo se bo nasilno obrnil in te zalučal kakor žogo v veliko deželo. Tam boš umrl in tam bodo vozovi tvoje slave sramota hiši tvojega gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, '»Odgnal te bom iz tvojega položaja in iz tvojega mesta te bo zvrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Na tisti dan se bo zgodilo, da bom poklical svojega služabnika Eljakíma, Hilkijájevega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Oblekel ga bom s tvojim svečanim oblačilom, ga ojačal s tvojim pasom in tvojo vlado bom izročil v njegovo roko in on bo oče jeruzalemskim prebivalcem in Judovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Ključ Davidove hiše bom položil na njegovo ramo; tako bo odprl in nihče ne bo zaprl; in zaprl bo in nihče ne bo odprl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Pritrdil ga bom kakor žebelj na zanesljivo mesto in on bo za veličasten prestol hiši svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Nanj bodo obesili vso slavo hiše njegovega očeta, potomstvo in pregnance, vse posode majhne količine, od čašastih posod, celo do vseh posod iz usnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Na ta dan,« govori Gospod nad bojevniki, »bo žebelj, ki je bil pritrjen na zanesljivem kraju, odstranjen, posekan in pade; in breme, ki je bilo na njem, bo odsekano,« kajti Gospod je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Breme [naselbine] Tir. Tulite, ve ladje iz Taršíša, kajti ta je opustošena, tako da tam ni nobene hiše niti vhoda vanjo; od dežele Kitéjcev jim je razodeto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Bodite mirni, vi prebivalci otoka, vi, ki so jih sidónski trgovci, ki prečkajo morje, na novo napolnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Ob velikih vodah je seme Šihórja, žetev reke, njeno poplačilo in ona je dobiček narodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Bodi osramočen, oh Sidón, kajti morje je spregovorilo, celó moč morja, rekoč: »Ne mučim se, niti ne rojevam otrok, niti ne negujem mladeničev, niti ne vzgajam devic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Kakor ob poročilu glede Egipta, tako bodo boleče zaskrbljeni ob poročilu iz [naselbine] Tir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Prepeljite se v Taršíš; tulite, vi prebivalci otoka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ali je to vaše radostno mesto, katerega starodavnost je od starodavnih dni? Njegova lastna stopala ga bodo odnesla daleč, da začasno biva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kdo je sprejel ta nasvet zoper [naselbino] Tir, obkrožujoče mesto, čigar trgovci so princi, čigar preprodajalci so častitljivi [ljudje] zemlje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Gospod nad bojevniki je to namenil, da omadežuje ponos vse slave in da privede v zaničevanje vse častitljive [ljudi] zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, '§ Prečkaj skozi svojo deželo kakor reka, oh taršíška hči. Tam ni več nobene moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Svojo roko je iztegnil nad morje, stresel je kraljestva. Gospod je izdal zapoved zoper trgovsko mesto, da uniči njegova močna oporišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Rekel je: »Ne boš se več razveseljevala, oh ti zatirana devica, hči sidónska. Vstani, prečkaj h Kitéjcem; tudi tam ne boš imela počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Glej, dežela Kaldejcev; tega ljudstva ni bilo, dokler ga ni Asirec osnoval za tiste, ki prebivajo v divjini. Postavili so njegove stolpe, vzdignili so njegove palače; in privedel ga je do ruševin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Tulite ve ladje iz Taršíša, kajti vaša moč je opustošena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Na tisti dan se bo zgodilo, da bo [naselbina] Tir pozabljena sedemdeset let, glede na dneve enega kralja. Po koncu sedemdesetih let bo [naselbina] Tir pela kakor pocestnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Vzemi harfo, pojdi okoli mesta, ti pocestnica, ki si bila pozabljena; naredi prijetno melodijo, poj mnoge pesmi, da se te bodo lahko spomnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Po koncu sedemdesetih let se bo zgodilo, da bo Gospod obiskal [naselbino] Tir in se obrnil k njenemu plačilu in zagrešila bo prešuštvovanje, z vsemi kraljestvi sveta, na obličju zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Njeno trgovsko blago in njena nagrada bosta sveta Gospodu. To ne bo več shranjeno niti kopičeno, kajti njen trgovski dobiček bo za tiste, ki prebivajo pred Gospodom, da bodo zadostno jedli in za trpežno oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Glej, Gospod prazni zemljo in jo pustoši in jo prevrača in razpršuje njene prebivalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Zgodilo se bo, kakor z ljudstvom, tako z duhovnikom; kakor s služabnikom, tako z njegovim gospodarjem; kakor s služabnico, tako z njeno gospodarico; kakor s kupcem, tako s prodajalcem; kakor s tistim, ki posoja, tako z izposojevalcem; kakor z jemalcem obresti, tako s tistim, ki mu daje obresti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Dežela bo popolnoma izpraznjena in popolnoma oplenjena, kajti Gospod je spregovoril to besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Zemlja žaluje in bledi, zemeljski [krog] peša in bledi, ošabno ljudstvo zemlje peša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Tudi zemlja je omadeževana pod njenimi prebivalci, ker so prekršili postave, spremenili odredbo, prelomili večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Zato je prekletstvo požrlo zemljo in tisti, ki prebivajo na njej, so zapuščeni. Zato so prebivalci zemlje požgani in ostalo je le malo mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Novo vino žaluje, trta peša, vsi veselo–srčni vzdihujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Veselje bobničev pojenjuje, hrup tistih, ki se veselijo, se končuje, radost harfe pojenjuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Vina ne bodo pili s pesmijo; močna pijača bo grenka tistim, ki jo pijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Mesto zmešnjave je zlomljeno. Vsaka hiša je zaprta, da noben človek ne more vstopiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Tam je na ulicah jokanje zaradi vina; vsa radost je otemnela, veselje dežele je odšlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'V mestu je ostalo opustošenje in velika vrata so udarjena z uničenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Ko bo tako v sredi dežele med ljudstvom, bo tam kakor otresanje oljke in kakor paberkovanje grozdov, ko je trgatev končana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Povzdignili bodo svoj glas, peli bodo zaradi Gospodovega veličanstva, glasno bodo klicali od morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Zatorej proslavljajte Gospoda v ognjih, celó ime Gospoda, Izraelovega Boga, na morskih otokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od skrajnih delov zemlje smo slišali pesmi, celó slavo k pravičnemu. Toda rekel sem: »Moja pustost, moja pustost, gorje meni! Zahrbtneži so postopali zahrbtno; da, zahrbtneži so postopali zelo zahrbtno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Strah, jama in zanka so nad teboj, oh prebivalec zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Zgodilo se bo, da kdor pobegne pred hrupom strahu, bo padel v jamo; in kdor prihaja gor iz srede jame, bo ujet v zanko, kajti okna od zgoraj so odprta in temelji zemlje se tresejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Zemlja je popolnoma razrušena, zemlja je čisto raztopljena, zemlja je silno premaknjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Zemlja se bo opotekala sem ter tja kakor pijanec in odstranjena bo kakor koča in njen prestopek bo težak nad njo in ta bo padla in ne bo ponovno vstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Na tisti dan se bo zgodilo, da bo Gospod kaznoval vojsko vzvišenih, ki so na višavi in zemeljske kralje na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, '§ Zbrani bodo skupaj, kakor so jetniki zbrani v jami in zaprti bodo v ječi in po mnogih dneh bodo obiskani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Potem bo luna zbegana in sonce osramočeno, ko bo Gospod nad bojevniki veličastno kraljeval na gori Sion in v Jeruzalemu in pred njegovimi starci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Oh Gospod, ti si moj Bog; poviševal te bom, hvalil bom tvoje ime, kajti storil si čudovite stvari; tvoji nasveti od davnine so zvestoba in resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Kajti iz mesta si naredil kup; iz obrambnega mesta razvalino, da palača tujcev ni več mesto; ta ne bo nikoli zgrajena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Zato te bo močno ljudstvo proslavljalo in mesto strašnih narodov se te bo balo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Kajti bil si moč revnim, moč pomoči potrebnim v njihovi tegobi, zatočišče pred viharjem, senca pred vročino, ko je udar strahovitežev kakor vihar proti zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Hrup tujcev boš ponižal kakor vročino na suhem kraju, celó vročino s senco oblaka; mladika strahovitežev bo ponižana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Na tej gori bo Gospod nad bojevniki vsem ljudstvom pripravil praznovanje mastnih stvari, praznovanje vin na drožeh, mastnih stvari, polnih mozga, dobro prečiščenih, dolgo hranjenih vin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Na tej gori bo uničil obličje zagrinjala, vrženega nad vsa ljudstva in zagrinjalo, ki je razprostrto nad vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'V zmagi bo pogoltnil smrt. Gospod Bog bo obrisal solze iz vseh obrazov in sramoto svojega ljudstva bo vzel proč iz vse zemlje, kajti Gospod je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Na ta dan bo rečeno: »Glejte! To je naš Bog; čakali smo nanj in on nas bo rešil. To je Gospod; čakali smo nanj, veseli bomo in se razveseljevali v njegovi rešitvi duše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Kajti na tej gori bo počivala Gospodova roka in Moáb bo pomendran pod njim, celo kakor je slama pomendrana za gnojišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Svoje roke bo razširil v njihovi sredi, kakor kdor plava razširja svoje roke za plavanje. Njihov ponos bo ponižal skupaj s pleni njihovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Trdnjavo visoke utrdbe tvojega obzidja bo ponižal, nizko položil in privedel k tlom, celó k prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Na tisti dan bo ta pesem prepevana v Judovi deželi: »Imamo močno mesto; rešitev duše bo Bog določil za zidove in branike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Odprite velika vrata, da bo pravičen narod, ki varuje resnico, lahko vstopil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Ohranil ga boš v popolnem miru, čigar um se zadržuje na tebi, ker on zaupa vate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Zaupajte v Gospoda na veke, kajti v Gospodu Jahveju je večna moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Kajti on poniža tiste, ki prebivajo na višavi; vzvišeno mesto, polaga ga nizko, polaga ga nizko, celó k tlom; prinaša ga celo k prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Stopalo ga bo pomendralo, celó stopalo revnega in koraki pomoči potrebnih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Pot pravičnih je poštenost. Ti, najpokončnejši, tehtaš stezo pravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Da, na poti tvojih sodb, oh Gospod, smo čakali nate; hrepenenje naše duše je k tvojemu imenu in k spominu nate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'S svojo dušo sem te želel ponoči; da, s svojim duhom znotraj sebe te bom iskal zgodaj, kajti ko so tvoje sodbe na zemlji, se bodo prebivalci zemeljskega [kroga] učili pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Naj bo naklonjenost pokazana zlobnemu, vendar se ne bo naučil pravičnosti. V deželi poštenosti bo ravnal nepravično in ne bo gledal Gospodovega veličanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Gospod, kadar je tvoja roka dvignjena, ne bodo videli. Toda videli bodo in bodo osramočeni zaradi svoje zavisti nad ljudstvom; da, požrl jih bo ogenj tvojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Gospod, ti nam hočeš določiti mir, kajti naredil si tudi vsa naša dela v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Oh Gospod, naš Bog, drugi gospodarji poleg tebe so imeli gospostvo nad nami, toda samo po tebi bomo naredili omembo tvojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Mrtvi so, ne bodo živeli; preminuli so, ne bodo vstali. Zato si jih obiskal, uničil in storil, da ves spomin nanje izgine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Povečal si narod, oh Gospod, ti si povečal narod. Proslavljen si. Odstranil si ga daleč, k vsem koncem zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Gospod, v stiski so te obiskali, izlili so molitev, ko je bilo nad njimi tvoje karanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Kakor je nosečnica, ko se približuje čas njenega poroda, v bolečini in vpije v svojih ostrih bolečinah, tako smo bili mi v tvojem pogledu, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Bili smo z otrokom, bili smo v bolečini, tako smo, kakor bi rodili veter; na zemlji nismo dosegli nobene osvoboditve; niti prebivalci zemeljskega [kroga] niso padli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Tvoji mrtvi možje bodo živeli, skupaj z mojim truplom bodo vstali. Zbudite se in pojte, vi, ki prebivate v prahu, kajti tvoja rosa je kakor rosa zelišč in zemlja bo izvrgla mrtve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Pridite, moje ljudstvo, vstopite v svoje sobe in zaprite svoja vrata naokoli sebe. Skrijte se, kakor bi bilo za kratek trenutek, dokler ne bo ogorčenje minilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Kajti, glejte, Gospod prihaja iz svojega kraja, da kaznuje prebivalce zemlje zaradi njihove krivičnosti. Tudi zemlja bo razkrila svojo kri in ne bo več pokrivala svojih umorjenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Na tisti dan bo Gospod s svojim bridkim, velikim in močnim mečem kaznoval leviatána in ostro kačo, celó leviatána, to sprijeno kačo in pokončal bo zmaja, ki je v morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Na tisti dan ji pojte: »Vinograd rdečega vina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Jaz, Gospod, ga varujem; vsak trenutek ga bom zalival. Da ga ne bi kdorkoli poškodoval, ga bom varoval noč in dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Razjarjenosti ni v meni. Kdo bi zoper mene v bitki postavil osat in trnje? Šel bi skoznje, skupaj bi jih požgal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ali pa naj se oprime moje moči, da lahko sklene mir z menoj in sklenil bo mir z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Tistim, ki pridejo iz Jakoba, bo povzročil, da se ukoreninijo. Izrael bo cvetel, brstel in obličje zemeljskega [kroga] bo napolnil s sadom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Mar ga je udaril, kakor je on udaril tiste, ki so ga udarili? Mar je umorjen glede na pokol tistih, ki so umorjeni po njem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Po meri, ko ta poganja naprej, boš razpravljal z njim. On ustavlja njegov oster veter na dan vzhodnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Torej s tem bo Jakobova krivičnost očiščena in to je ves sad, da odvzame njegov greh, ko vse oltarne kamne naredi kakor apnenčaste kamne, ki so raztreščeni narazen; ašere in podobe ne bodo obstale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Vendar bo obrambno mesto opustelo in prebivališče zapuščeno in opuščeno kakor divjina. Tam se bo paslo tele in tam se bo uleglo in použilo njegove mladike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Ko njegove veje ovenijo, bodo odlomljene. Prišle bodo ženske in jih zažgale. Kajti to je ljudstvo brez razumevanja, zato tisti, ki jih je naredil, ne bo imel usmiljenja do njih in kdor jih je oblikoval, jim ne bo izkazal nobene naklonjenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Na tisti dan se bo zgodilo, da bo Gospod otepal od rečnega kanala do egiptovskega vodotoka in zbrani boste drug za drugim, oh vi, Izraelovi otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Na tisti dan se bo zgodilo, da bo zatrobljeno na velik šofar in prišli bodo, ki so bili pripravljeni, da se pogubijo v asirski deželi in [ki so bili] pregnanci v egiptovski deželi in oboževali bodo Gospoda na sveti gori pri Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Gorje kroni ponosa, efrájimskim pijancem, katerih veličastna lepota je odcvetena roža, ki je na čelu obilnih dolin tistih, ki so premagani z vinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Glej, Gospod ima mogočnega in močnega, ki bo kakor neurje s točo in uničujoč vihar, kakor poplava mogočnih vodá, ki preplavljajo, z roko vrgel dol k zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Krona ponosa, efrájimski pijanci, bodo pomendrani pod stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Veličastna lepota, ki je na čelu obilne doline, bo veneča roža in kakor zgodnji sad pred poletjem; ko ga tisti, ki pogleda nanj, vidi, ga pojé, medtem ko je še v njegovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Na tisti dan bo Gospod nad bojevniki za krono slave in za diadem lepote preostanku svojega ljudstva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'in za duha sodbe tistemu, ki sedi na sodbi in za moč tistim, ki bitko odvračajo k velikim vratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Vendar so tudi oni zašli zaradi vina in zaradi močne pijače so omahnili iz poti; duhovnik in prerok sta zašla zaradi močne pijače, pogoltnjena sta od vina, zaradi močne pijače sta omahnila iz poti; motita se v videnju, spotikata se v sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Kajti vse mize so polne izbljuvkov in umazanosti, tako da tam ni čistega prostora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Koga bo učil spoznanja? In koga bo pripravil, da razume nauk? Tiste, ki so odstavljeni od mleka in odtegnjeni od prsi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Kajti predpis mora biti na predpis, predpis na predpis; ukaz na ukaz, ukaz na ukaz; malo tukaj in malo tam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'kajti z jecljajočimi ustnicami in drugim jezikom bo govoril temu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Katerim je rekel: »To je počitek, s katerim lahko izmučenemu storite, da počiva in to je osvežitev.« Vendar niso hoteli poslušati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Toda Gospodova beseda jim je bila predpis na predpis, predpis na predpis; ukaz na ukaz, ukaz na ukaz; malo tukaj in malo tam; da lahko gredo, padejo vznak, se zlomijo, se ulovijo in ujamejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Zato poslušajte Gospodovo besedo, vi posmehljivci, ki vladate temu ljudstvu, ki je v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Ker ste rekli: »Sklenili smo zavezo s smrtjo in s peklom smo v dogovoru. Ko bo šel skozi poplavljajoč bič, ta ne bo prišel k nam, kajti laži smo naredili za svoje zatočišče in pod neresnico smo se skrili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Zato tako govori Gospod Bog: »Glej, na Sionu polagam za temelj kamen, preizkušen kamen, dragocen vogalni kamen, postavljen temelj. Kdor veruje, ne bo vznemirjeno hitel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Tudi sodbo bom položil k merilu in pravičnost h grezilu in toča bo pomedla zatočišče laži in vode bodo preplavile skrivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Vaša zaveza s smrtjo bo razveljavljena in vaš dogovor s peklom ne bo obstal; ko bo skozi šel preplavljajoč bič, potem boste z njim pomendrani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Od časa, ko gre ta naprej, vas bo zgrabil, kajti jutro za jutrom bo ta prehajal, podnevi in ponoči. To bo samo draženje, da razume poročilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Kajti postelja je krajša, kakor se človek lahko iztegne na njej in pokrivalo ožje, kakor se lahko zavije vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Kajti Gospod se bo dvignil kakor na gori Peracím, ogorčen bo kakor v dolini Gibeón, da lahko opravi svoje delo, svoje čudno delo in privede, da se njegovo dejanje zgodi, njegovo čudno dejanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Zdaj torej ne bodite zasmehovalci, da ne bi vaše vezi postale močne, kajti od Gospoda Boga nad bojevniki sem slišal uničenje, celo določeno nad celotno zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Pazljivo prisluhnite in poslušajte moj glas, prisluhnite in poslušajte moj govor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Mar orač orje ves dan, da bi sejal? Ali odpira in brana svojo zemljo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Ko je njeno površino izravnal, mar ne meče naokoli pire, raztrosi kumino in meče noter glavno pšenico in določen ječmen in piriko na njihov prostor?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Kajti njegov Bog ga navaja k preudarnosti in ga uči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Kajti pira ni mlatena z mlatilno pripravo niti kolo voza obračano nad kumino, temveč je pira otepana s palico in kumina s šibo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, '§ Krušno žito je zmleto, ker ga nikoli ne bo mlatil niti lomil s kolesom svojega voza niti ga poškodoval s konjeniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Tudi to prihaja od Gospoda nad bojevniki, ki je čudovit v nasvetu in odličen v delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, '§ Gorje Ariélu, Ariélu, mestu, kjer je prebival David! Dodajte letu leto; naj ubijejo žrtve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Vendar bom Ariél spravil v tegobo in tam bo potrtost in bridkost in ta mi bo kakor Ariél.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Utaboril se bom naokoli zoper tebe in zoper tebe bom položil obleganje z nasipom in zoper tebe bom dvignil utrdbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Ponižan boš in govoril boš iz zemlje in tvoj govor iz prahu bo znižan in tvoj glas bo kakor od nekoga, ki ima osebnega duha iz zemlje in tvoj govor bo šepetal iz prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Poleg tega bo množica tvojih tujcev podobna drobnemu prahu in množica strahovitežev bo kakor pleve, ki mineva. Da, to bo v trenutku, nenadoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Od Gospoda nad bojevniki boš obiskan z gromom in s potresom in z velikim hrupom, z viharjem, neurjem in plamenom požirajočega ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Množica vseh narodov, ki se bori zoper Ariél, celo vsi, ki se borijo proti njemu in njegovemu oporišču in ki ga stiskajo, bodo kakor sanje nočnega videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'To bo torej kakor kadar lačen človek sanja in glej, on jé; toda zbuja se, njegova duša pa je prazna. Ali kakor kadar žejen človek sanja in glej pije; toda zbudi se in glej, je oslabel, njegova duša pa ima apetit. Takšna bo množica vseh narodov, ki se borijo zoper goro Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Ustavite se in se čudite, strmite in glejte. Pijani so, toda ne zaradi vina; omahujejo, toda ne zaradi močne pijače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Kajti Gospod je na vas izlil duha globokega spanja in zaprl vaše oči. Preroke in vaše vladarje, vidce je pokril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Videnje vsega vam je postalo kakor besede knjige, ki je zapečatena, ki jo ljudje izročijo nekomu, ki je učen, rekoč: ›Beri to, prosim te.‹ Ta pa pravi: ›Ne morem, kajti zapečatena je.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'In knjiga je izročena tistemu, ki ni učen, rekoč: ›Beri to, prosim te.‹ In ta pravi: ›Nisem učen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Zato je Gospod rekel: »Ker se mi to ljudstvo približuje s svojimi usti in me časti s svojimi ustnicami, toda svoje srce so odstranili daleč proč od mene in je njihov strah proti meni naučen s človeškimi predpisi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'zato, glej, nadaljeval bom, da storim čudovito delo med tem ljudstvom, celó čudovito delo in čudo, kajti modrost njihovih modrih mož bo izginila in razumevanje njihovih preudarnih mož bo skrito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Gorje tistim, ki globoko iščejo, da skrijejo svoj naklep pred Gospodom in so njihova dela v temi in govorijo: »Kdo nas vidi? In kdo nas pozna?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Zagotovo bo vaše sprevračanje stvari na glavo veljalo kakor lončarjevo ilo. Mar bo delo reklo o tistem, ki ga je naredil: »Ta me ni naredil?« Mar bo oblikovana stvar rekla o tistem, ki jo je oblikoval: »Ta nima razumevanja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Mar ni le še malo in Libanon bo spremenjen v rodovitno polje in rodovitno polje bo veljalo kakor gozd?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Na ta dan bodo gluhi slišali besede iz knjige in oči slepega bodo videle iz nejasnosti in iz teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Tudi krotki bodo povečali svojo radost v Gospodu in revni med možmi se bodo razveseljevali v Svetem Izraelovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Kajti strahovitež je priveden v nič in posmehljivec je použit in vsi tisti, ki so pozorni na krivičnost, so iztrebljeni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'ki človeka delajo za prestopnika zaradi besede in polagajo zanko za tistega, ki graja pri velikih vratih in pravičnega odvračajo zaradi ničnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Zato tako govori Gospod, ki je odkupil Abrahama, glede Jakobove hiše: »Jakob sedaj ne bo osramočen niti njegov obraz sedaj ne bo obledel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Temveč ko vidi svoje otroke, delo mojih rok v svoji sredi, bodo posvetili moje ime in posvetili Svetega Jakobovega in se bodo bali Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Tudi tisti, ki so se motili v duhu, bodo prišli k razumevanju in tisti, ki so godrnjali, se bodo naučili nauka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '»Gorje upornim otrokom,« govori Gospod, »ki jemljejo nasvet, toda ne od mene in ki se pokrivajo s pokrivalom, toda ne od mojega duha, da lahko grehu dodajo greh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'ki hodijo, da bi šli dol v Egipt, pa niso vprašali pri mojih ustih, da se ojačajo v faraonovi moči in da zaupajo v egiptovsko senco!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Zato bo faraonova moč vaša sramota in zaupanje v egiptovsko senco vaša zmeda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Kajti njegovi princi so bili pri Coanu in njegovi predstavniki so prišli do Hanésa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Vsi so bili osramočeni od ljudstva, ki jim ni moglo koristiti niti jim biti v pomoč niti dobiček, temveč sramota in tudi graja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, '§ Breme živali juga. V deželo stiske in tesnobe, od koder je prišel mlad in star lev, gad in strupena leteča kača, bodo svoja bogastva odnesli na ramenih mladih oslov in svoje zaklade na kameljih grbah k ljudstvu, ki jim ne bo koristilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Kajti Egipčani bodo pomagali v prazno in zaman, zato sem glede tega klical: ›Njihova moč mora prenehati.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Torej pojdite, zapišite to pred njimi na tablo in zabeležite v knjigo, da bo lahko za čas, ki pride na veke vekov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'da je to uporno ljudstvo, lažnivi otroci, otroci, ki nočejo poslušati Gospodove postave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'ki vidcem pravijo: ›Ne vidite‹ in prerokom: ›Ne prerokujte nam pravilnih stvari, govorite nam laskave stvari, prerokujte prevare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Spravite se iz poti, odvrnite se iz steze, Svetemu Izraelovemu naredite, da odide izpred nas.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Zatorej tako govori Sveti Izraelov: »Ker prezirate to besedo in zaupate v zatiranje in perverznost in ostajate na njej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'zato vam bo ta krivičnost kakor vrzel, pripravljena, da pade, naraščajoča iz visokega obzidja, katerega zlom pride nenadoma, v trenutku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Zlomil ga bo kakor lomljenje lončarjeve posode, ki je zdrobljena na koščke. Ne bo prizanesel, tako da tam, v lomljenju le-tega, ne bo najti črepinje, da bi vzel ogenj iz ognjišča ali da bi s tem zajel vodo iz vrča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Kajti tako govori Gospod Bog, Sveti Izraelov: »›V vračanju in počivanju boste rešeni; v spokojnosti in zaupanju bo vaša moč,‹ pa niste hoteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Temveč ste rekli: ›Ne, kajti bežali bomo na konjih;‹ zatorej boste bežali. ›Jahali bomo na naglih;‹ zato bodo tisti, ki vas preganjajo, nagli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tisoč jih bo bežalo ob graji enega; ob graji petih boste bežali, dokler ne boste ostali kakor drog na vrhu gore in kakor zastava na hribu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Zato bo Gospod čakal, da vam bo lahko milostljiv in zato bo povzdignjen, da bo lahko imel usmiljenje do vas, kajti Gospod je Bog sodbe. Blagoslovljeni so vsi tisti, ki čakajo nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Kajti ljudstvo bo prebivalo na Sionu, pri Jeruzalemu. Ne boš več jokal. Zelo ti bo milostljiv ob glasu tvojega klica; ko ga bo zaslišal, ti bo odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Čeprav ti Gospod daje kruh nadloge in vodo stiske, vendar tvoji učitelji ne bodo več odstranjeni v kot, temveč bodo tvoje oči videle tvoje učitelje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'in tvoja ušesa bodo slišala za teboj besedo, rekoč: »To je pot, po njej hodite,« ko se obrnete k desnici in ko se obrnete k levici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Omadeževali boste tudi pokrivalo svojih rezanih podob iz srebra in ornament svojih ulitih podob iz zlata. Vrgel jih boš proč kakor menstrualno krpo; temu boš rekel: »Pojdi ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Potem bo dal dež tvojemu semenu, da boš z njim posejal tla in kruh od donosa zemlje in to bo debelo in obilno. Na ta dan se bo tvoja živina pasla na velikih pašnikih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Prav tako bodo voli in mladi osli, ki obdelujejo zemljišče, jedli čisto krmo, ki je bila prevejana z lopato in z vejálnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Tam bodo na vsaki visoki gori in na vsakem visokem hribu reke in potoki vodá, na dan velikega pokola, ko bodo padli stolpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Poleg tega bo svetloba lune kakor svetloba sonca in svetloba sonca bo sedemkratna, kakor svetloba sedmih dni, na dan, ko Gospod obveže vrzel svojega ljudstva in ozdravi udarec njihove rane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Glej, ime Gospoda prihaja od daleč, goreč z njegovo jezo in njegovo breme je težko. Njegove ustnice so polne ogorčenja in njegov jezik kakor požirajoč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Njegov dih bo kakor preplavljajoč vodotok segel do sredine vratu, da narode preseje s sitom ničnosti in tam bo brzda v čeljustih ljudstva, ki jim bo povzročala, da se opotekajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Imeli boste pesem, kakor v noči, ko se praznuje sveta slovesnost; in veselje srca, kakor ko gre nekdo s piščaljo, da pride na Gospodovo goro, k Mogočnemu Izraelovemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Gospod bo svojemu veličastnemu glasu povzročil, da bo slišan in pokazal bo spuščanje svojega lakta, z ogorčenjem svoje jeze in s plamenom požirajočega ognja, z razprševanjem, neurjem in zrni toče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Kajti preko Gospodovega glasu bo Asirec, ki je udaril s palico, potolčen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Na vsakem kraju, kjer bo prešla osnovana palica, ki jo bo Gospod položil nanj, bo to z bobniči in harfami, in v bitkah vihtenja se bo boril z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Kajti Tofet je odrejen od davnine; da, za kralja je pripravljen; naredil ga je globokega in velikega. Njegova grmada je ogenj in veliko lesa. Gospodov dih ga vname kakor tok žvepla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Gorje tistim, ki gredo dol v Egipt po pomoč in se zanašajo na konje in zaupajo v bojne vozove, zato ker so številni in na konjenike, ker so zelo močni, toda ne gledajo k Svetemu Izraelovemu niti ne iščejo Gospoda!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Vendar je on tudi moder in privedel bo zlo in svojih besed ne bo poklical nazaj, temveč se bo vzdignil zoper hišo hudodelcev in zoper pomoč tistih, ki počno krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Torej Egipčani so ljudje in ne Bog in njihovi konji meso in ne duh. Ko bo Gospod iztegnil svojo roko, bosta padla oba, tako tisti, ki pomaga in komur je pomagano, padla bosta in vsem skupaj bo spodletelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Kajti tako mi je govoril Gospod: »Podobno kakor lev in mlad lev rjoveta na svoj plen, ko je zoper njega sklicana množica pastirjev, se on ne bo bal njihovega glasu niti se Gospod nad bojevniki ne bo ponižal zaradi njihovega hrupa. Tako bo Gospod nad bojevniki prišel dol, da se bori za goro Sion in za njen hrib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Kakor leteče ptice, tako bo Gospod nad bojevniki branil [prestolnico] Jeruzalem; z obrambo jo bo tudi osvobodil in s prehajanjem čeznjo jo bo ohranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Obrnite se k njemu, od katerega so se Izraelovi otroci globoko spuntali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Kajti na ta dan bo vsak človek zavrgel svoje malike iz srebra in svoje malike iz zlata, ki so vam jih v greh naredile vaše lastne roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Takrat bo Asirec padel pod mečem, ne od mogočnega človeka; in meč, ne od zlobnega človeka, ga bo požiral. Toda pobegnil bo pred mečem in njegovi mladeniči bodo poraženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Zaradi strahu bo prešel k svojemu oporišču in njegovi princi se bodo bali zastave,« govori Gospod, čigar ogenj je na Sionu in njegova talilna peč v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Glej, kralj bo kraljeval v pravičnosti in princi bodo vladali na sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Človek bo kakor skrivališče pred vetrom in zatočišče pred neurjem, kakor reke vodá na suhem kraju, kakor senca velike skale na izmučeni zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Oči tistih, ki vidijo, ne bodo zatemnjene in ušesa tistih, ki slišijo, bodo prisluhnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Tudi srce prenagljenega bo razumelo spoznanje in jezik jecljavih bo pripravljen razločno govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Podla oseba se ne bo več imenovala velikodušna niti [za] skopuha ne bo rečeno, da je radodaren.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Kajti podla oseba bo govorila podlost in srce le-te hoče početi krivičnost, da izvaja hinavščino in da izreka napačno zoper Gospoda, da izprazni dušo lačnega in pijači žejnega povzroči, da odpove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Tudi orodja skopušnega so zla. On snuje zlobne naklepe, da ubogega uniči z lažnivimi besedami, celo ko pomoči potreben pravilno govori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Toda velikodušen snuje velikodušne stvari in z velikodušnimi stvarmi bo obstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Vstanite, ve ženske, ki ste ošabne, prisluhnite mojemu glasu. Ve brezskrbne hčere, pazljivo prisluhnite mojemu govoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Mnogo dni in let boste zaskrbljene, ve brezskrbne ženske, kajti trgatev se bo izjalovila, obiranje ne bo prišlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Trepetajte, ve ženske, ki ste ošabne; bodite zaskrbljene, ve brezskrbne. Slecite se in se razgalite in opašite si vrečevino na svoja ledja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, '§ Žalovale bodo zaradi seskov, zaradi prijetnih polj, zaradi rodovitne trte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Nad deželo mojega ljudstva bo prišlo trnje in osat, da, nad vse hiše radosti v radostnem mestu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'ker bodo palače zapuščene, množica mesta bo opuščena, utrdbe in stolpi bodo za brloge na veke, radost divjih oslov, pašnik tropov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'dokler nad nas ne bo izlit duh iz višave in bo divjina rodovitno polje in rodovitno polje bo šteto za gozd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Potem bo sodba prebivala v divjini in pravičnost ostane na rodovitnem polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Delo pravičnosti bo mir in učinek pravičnosti spokojnost in gotovost na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Moje ljudstvo bo prebivalo v mirnem okolju in v zanesljivih prebivališčih in v tihih počivališčih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'ko se bo usula toča, prihajajoča na gozd in bo mesto nizko, na nizkem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Blagoslovljeni ste vi, ki sejete poleg vseh vodá, ki tja pošiljate kopita vola in osla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Gorje tebi, ki pleniš, pa nisi bil oplenjen in postopaš zahrbtno, oni pa niso zahrbtno postopali s teboj! Ko boš prenehal pleniti, potem boš oplenjen in ko boš naredil konec zahrbtnemu postopanju, potem bodo zahrbtno postopali s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Oh Gospod, bodi nam milostljiv, pričakovali smo te. Vsako jutro bodi njihov laket, tudi naša rešitev duše v času stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Ob hrupu upora je ljudstvo pobegnilo, ob tvojem vzdigovanju so bili narodi razkropljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Vaš plen bo zbran kakor zbiranje gosenice, kakor tekanje leteče kobilice sem ter tja bo on tekel nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Gospod je povišan, kajti prebiva na višavi. Sion je napolnil s sodbo in pravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Modrost in spoznanje bosta stabilnost tvojih časov in moč rešitve duše. Gospodov strah je njegov zaklad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Glej, njihovi hrabri bodo zunaj vreščali. Predstavniki miru bodo grenko jokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Glavne ceste ležijo zapuščene, popotnik peša. Prelomil je zavezo, preziral mesta, ne ozira se na nobenega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Zemlja žaluje in peša. Libanon je osramočen in posekan. Šarón je podoben divjini in Bašán ter Karmel otresata svoje sadove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, '»Sedaj bom vstal,« govori Gospod, »sedaj bom povišan, sedaj se bom dvignil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Spočeli boste pleve, rodili boste strnišče. Vaš dih vas bo pogoltnil kakor ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Ljudstvo bo kakor gorenje žganega apna, kakor posekano trnje bodo sežgani v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Prisluhnite vi, ki ste daleč proč, kaj sem storil in vi, ki ste blizu, priznajte mojo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Grešniki na Sionu so prestrašeni, grozljivost je presenetila hinavce. Kdo izmed nas bo bival s požirajočim ognjem? Kdo izmed nas bo bival z večnimi gorenji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Kdor hodi pravično in govori iskreno, kdor prezira dobiček zatiranj, ki otresa svoji roki pred tem, da bi držal podkupnine, ki si ušesa zatiska pred poslušanjem o krvi in zatiska svoje oči pred gledanjem zla;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'ta bo prebival na višavi. Njegov prostor obrambe bodo skalna oporišča. Dan mu bo kruh, njegove vode bodo zanesljive.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tvoje oči bodo videle kralja v njegovi lepoti. Gledale bodo deželo, ki je zelo daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Tvoje srce bo premišljevalo strahoto. Kje je pisar? Kje je prejemnik? Kje je tisti, ki je štel stolpe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Ne boš videl krutega ljudstva, ljudstva globljega govora, kakor ga lahko zaznaš, jecljajočega jezika, ki ga ne moreš razumeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Poglej na Sion, mesto naših slovesnosti. Tvoje oči bodo videle Jeruzalem, tiho prebivališče, šotor, ki ne bo porušen; niti eden izmed njegovih klinov ne bo nikoli odstranjen niti nobena izmed njegovih vrvi pretrgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Toda tam nam bo veličasten Gospod kraj širokih rek in vodotokov, kamor ne bo plula galeja z vesli niti čedna ladja ne bo plula mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Kajti Gospod je naš sodnik, Gospod je naš zakonodajalec, Gospod je naš kralj, on nas bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tvoja ladijska oprema je odvezana; ne morejo dobro ojačati jambora, ne morejo razpeti jadra. Potem je plen velikega ukradenega blaga razdeljen; hromi pobira plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Prebivalec ne bo rekel: »Bolan sem.« Ljudstvu, ki tam prebiva, bo odpuščena njihova krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Pridite bliže, vi narodi, da slišite in prisluhnite ve ljudstva. Naj zemlja sliši in vsi, ki so na njej, zemeljski [krog] in vse stvari, ki pridejo iz njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Kajti ogorčenje od Gospoda je nad vsemi narodi in njegova razjarjenost nad vsemi njihovimi vojskami. Popolnoma jih je uničil, izročil jih je v klanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Tudi njihovi umorjeni bodo vrženi ven in njihov smrad bo prišel iz njihovih trupel in gore bodo stopljene z njihovo krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Vse vojske neba bodo razpadle in nebo bo zvito skupaj kakor zvitek pergamenta. Vse njihove vojske bodo padle, kakor list pade s trte in kakor figa pade iz figovega drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Kajti moj meč bo potešen na nebu. Glejte, ta bo prišel dol nad Edóm in nad ljudstvo mojega prekletstva, k sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Gospodov meč je poln krvi, zamaščen s tolščo in s krvjo jagnjet in koz, s tolščo ledvic ovnov, kajti Gospod ima klavno daritev v Bocri in velik pokol v edómski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Samorogi bodo z njimi prišli dol in bikci z biki in njihova dežela bo namočena s krvjo in njihov prah zamaščen z mastnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Kajti to je dan Gospodovega maščevanja in leto povračil zaradi Sionove pravde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Njegovi vodotoki bodo spremenjeni v smolo, njegov prah v žveplo in njegova dežela bo postala goreča smola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Ta ne bo pogašena ne ponoči ne podnevi; njen dim se bo dvigoval na veke. Od roda do roda bo ležala opustošena; nihče ne bo šel skoznjo na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Toda kormoran in bobnarica jo bosta vzela v last; tudi sova in krokar bosta v njej prebivala. Nadnjo bo razširil vrvico zmede in kamne praznine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Njene plemenite bodo poklicali h kraljestvu, toda tam ne bo nikogar in vsi njeni princi bodo nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Trnje bo pognalo v njenih palačah, koprive in trnovo grmovje v njenih trdnjavah, in ta bo prebivališče zmajem in dvor za sove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Divje živali iz puščave se bodo prav tako srečale z divjimi živalmi z otoka in kozjenog bo klical svojemu tovarišu; tudi skovir bo tam počival in zase našel mesto počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tam si bo velika sova naredila svoje gnezdo, polegla, izvalila in [jih] zbrala pod svojo senco. Tam bodo zbrani tudi jastrebi, vsak s svojo družico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Poiščite si iz Gospodove knjige in berite. Nobeden izmed teh ne bo manjkal, nobeden ne bo pogrešal svoje družice, kajti moja usta so to zapovedala in njegov duh jih je zbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Zanje je vrgel žreb in njegova roka jim je to razdelila po vrvici. Vzeli jo bodo v last na veke, od roda do roda bodo prebivali v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Divjina in samoten kraj bosta vesela zaradi njih in puščava se bo razveseljevala in cvetela kakor vrtnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ta bo obilno cvetela in se razveseljevala, celo z radostjo in petjem. Dana ji bo slava Libanona, odličnost Karmela in Šaróna. Gledali bodo Gospodovo slavo in odličnost našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Ojačajte šibke roke in okrepite slabotna kolena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Recite tistim, ki so boječega srca: »Bodite močni, ne bojte se. Glejte, vaš Bog bo prišel z maščevanjem, celó Bog s povračilom; prišel bo in vas rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Potem bodo oči slepega odprte in ušesa gluhega bodo odmašena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Potem bo hromi človek poskakoval kakor jelen in jezik nemega bo pel, kajti v divjini bodo izbruhnile vode in vodotoki v puščavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Izsušena tla bodo postala ribnik in žejna dežela izviri vodá. V prebivališču zmajev, kjer vsak leži, bo trava s trstjem in ločjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Tam bo glavna cesta in pot in ta bo imenovana ›Pot svetosti;‹ nečisti ne bo šel preko nje, temveč bo ta zanje same. Popotniki, čeprav bedaki, ne bodo zgrešili na njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Tam ne bo nobenega leva niti katerakoli sestradana zver ne bo šla nanjo, tam je ne bo najti; temveč bodo tam hodili odkupljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Vrnili se bodo Gospodovi odkupljenci in prišli k Sionu s pesmimi in večno radostjo na svojih glavah. Dosegli bodo radost in veselje, bridkost in vzdihovanje pa bosta zbežala proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Pripetilo se je torej v štirinajstem letu kralja Ezekíja, da je asirski kralj Senaherib prišel gor zoper vsa obrambna Judova mesta in jih zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Asirski kralj je poslal Rabšakéja iz Lahíša v Jeruzalem h kralju Ezekíju z veliko vojsko. In ta se je ustavil pri kanalu gornjega ribnika, na glavni cesti pralčevega polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Potem so prišli k njemu Hilkijájev sin Eljakím, ki je bil nad hišo, pisar Šebná in Asáfov sin Joáh, letopisec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Rabšaké jim je rekel: »Povejte torej Ezekíju: ›Tako govori veliki kralj, kralj Asirije: ›Kakšno zaupanje je to, v katero zaupaš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Jaz pravim, ti govoriš (toda to so samo prazne besede) imam nasvet in moč za vojno. Torej komu zaupaš, da si se uprl zoper mene?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Glej, zanašaš se na palico tega zlomljenega trsta, na Egipt, na katerega, če se človek naslanja, se bo zadrl v njegovo roko in jo prebodel. Tako je faraon, egiptovski kralj, vsem, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Toda če mi rečeš: ›Mi zaupamo v Gospoda, svojega Boga.‹ Mar ni to tisti, katerega visoke kraje in katerega oltarje je Ezekíja odvzel ter Judu in Jeruzalemu rekel: ›Oboževali boste pred tem oltarjem?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Zdaj torej daj jamstva, prosim te, mojemu gospodarju, asirskemu kralju, jaz pa ti bom dal dva tisoč konjev, če boš na svoji strani nanje zmožen postaviti jezdece.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kako boš potem odvrnil obličje enega poveljnika, izmed najmanjših služabnikov mojega gospodarja in svoje upanje položil v Egipt zaradi bojnih vozov in konjenikov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Sem mar sedaj brez Gospoda prišel gor zoper to deželo, da jo uničim? Gospod mi je rekel: ›Pojdi gor zoper to deželo in jo uniči.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Nato so Eljakím, Šebná in Joáh rekli Rabšakéju: »Govori, prosimo te, svojim služabnikom v sirskem jeziku, kajti razumemo ga in ne govori nam v judovskem jeziku v ušesa ljudstva, ki je na obzidju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Toda Rabšaké je rekel: »Me je mar moj gospodar poslal k tvojemu gospodarju in k tebi, da ti govorim te besede? Mar me ni poslal k možem, ki sedijo na obzidju, da bodo lahko jedli svoj lastni iztrebek in z vami pili svoj lastni seč?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Potem se je Rabšaké ustopil in z močnim glasom zaklical v judovskem jeziku in rekel: »Poslušajte besede velikega kralja, asirskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tako govori kralj: ›Ne dopustite, da vas Ezekíja zavede, kajti ne bo vas mogel osvoboditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Niti naj vas Ezekíja ne primora zaupati v Gospoda, rekoč: › Gospod nas bo zagotovo osvobodil, to mesto ne bo izročeno v roko asirskega kralja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Ne prisluhnite Ezekíju, kajti tako govori kralj Asirije: › Z darilom sklenite dogovor z menoj in pridite ven k meni in jejte vsak od svoje trte in vsak od svojega figovega drevesa in pijte vode, vsak iz svojega lastnega vodnega zbiralnika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'dokler ne pridem in vas ne vzamem proč v deželo, podobno vaši lastni deželi, deželo žita in vina, deželo kruha in vinogradov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Pazite, da vas Ezekíja ne prepriča, rekoč: › Gospod nas bo osvobodil.‹ Mar je katerikoli izmed bogov narodov svojo deželo osvobodil iz roke asirskega kralja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kje so bogovi Hamáta in Arpáda? Kje so bogovi Sefarvájima? Mar so le-ti Samarijo osvobodili iz moje roke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kdo so tisti izmed vseh bogov teh dežel, ki so svojo deželo osvobodili iz moje roke, da bi Gospod Jeruzalem osvobodil iz moje roke?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Toda molčali so in mu niso odgovorili niti besede, kajti kraljeva zapoved je bila, rekoč: »Ne odgovarjajte mu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Potem so prišli Hilkijájev sin Eljakím, ki je bil nad družino, pisar Šebná in Asáfov sin Joáh, letopisec, k Ezekíju s svojimi pretrganimi oblačili in mu povedali Rabšakéjeve besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Pripetilo se je, ko je kralj Ezekíja to slišal, da je pretrgal svoja oblačila, se pokril z vrečevino in odšel v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Poslal je Eljakíma, ki je bil nad družino, pisarja Šebná in starešine duhovnikov, pokrite z vrečevino, k preroku Izaiju, Amócovemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Rekli so mu: »Tako govori Ezekíja: ›Ta dan je dan stiske, graje in bogokletja, kajti otroci so prišli do rojstva in tam ni moči za porod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Morda bo Gospod, tvoj Bog, slišal besede Rabšakéja, ki ga je poslal asirski kralj, njegov gospodar, da kara živega Boga in bo pograjal besede, ki jih je slišal Gospod, tvoj Bog. Zatorej dvigni svojo molitev za ostanek, ki je ostal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Tako so služabniki kralja Ezekíja prišli k Izaiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Izaija jim je rekel: »Tako boste rekli svojemu gospodarju: ›Tako govori Gospod: ›Ne boj se besed, ki si jih slišal, s katerimi so služabniki asirskega kralja proti meni izrekali bogokletje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Glej, nanj bom poslal sunek [duha] in slišal bo govorico in se vrnil v svojo lastno deželo in povzročil mu bom, da v svoji lastni deželi pade pod mečem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Tako se je Rabšaké vrnil in našel asirskega kralja, vojskujočega se zoper Libno, kajti slišal je, da je odpotoval iz Lahíša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Slišal je reči glede Tirháka, kralja Etiopije: »Prišel je naprej, da se vojskuje s teboj.« In ko je ta to slišal, je poslal poslance k Ezekíju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '»Tako govorite Judovemu kralju Ezekíju, rekoč: ›Ne dopusti, da te tvoj Bog, v katerega zaupaš, zavede, rekoč: ›Jeruzalem ne bo izročen v roko asirskega kralja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Glej, slišal si, kaj so asirski kralji storili vsem deželam z njihovim popolnim uničenjem, pa boš ti osvobojen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Mar so bogovi narodov osvobodili tiste, ki so jih moji očetje uničili, kakor Gozána, Harána, Recefa in otroke Edena, ki so bili v Telasárju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kje je kralj Hamáta, kralj Arpáda in kralj mesta Sefarvájima, Hene in Avája?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Ezekíja je prejel pismo iz roke poslancev ter ga prebral in Ezekíja je odšel gor v Gospodovo hišo in ga razprostrl pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'In Ezekíja je molil h Gospodu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '»Oh Gospod nad bojevniki, Izraelov Bog, ki prebivaš med kerubi, ti si Bog, celó ti sam, izmed vseh kraljestev zemlje. Ti si naredil nebo in zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nagni svoje uho, oh Gospod in prisluhni; odpri svoje oči, oh Gospod in glej in poslušaj vse besede Senaheriba, ki jih je poslal, da graja živega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Resnično, Gospod, asirski kralji so opustošili vse narode in njihove dežele');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'in njihove bogove vrgli v ogenj, kajti to niso bili bogovi, temveč delo človeških rok, les in kamen, zato so jih uničili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Zdaj torej, oh Gospod, naš Bog, reši nas pred njegovo roko, da bodo vsa kraljestva zemlje lahko vedela, da si ti Gospod, celó samo ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Potem je Izaija, Amócov sin, poslal k Ezekíju, rekoč: »Tako govori Gospod, Izraelov Bog: ›Kakor si molil k meni zoper asirskega kralja Senaheriba;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'to je beseda, ki jo je Gospod spregovoril glede njega: ›Devica, sionska hči, te je prezirala in se ti smejala do zaničevanja, jeruzalemska hči je nad teboj zmajevala z glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Koga si grajal in proti komu si izrekal bogokletje? Zoper koga si povišal svoj glas in svoje oči povzdignil na višavo? Celó zoper Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'S svojimi služabniki si grajal Gospoda in rekel: ›Z množico svojih bojnih vozov sem prišel gor do višin gora, k pobočjem Libanona in posekal bom njegove visoke cedre in izbrane ciprese in vstopil bom v višino njegove meje in gozd njegovega Karmela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Kopál sem in pil vodo in s podplatom svojega stopala sem posušil vse reke obleganih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Mar nisi že dolgo nazaj slišal, kako sem to storil in od starodavnih časov, da sem to oblikoval? Sedaj sem privedel, da se je to zgodilo, da bi moral položiti opustela obrambna mesta v kupe ruševin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Zato so bili njihovi prebivalci majhne moči, bili so zaprepadeni in zbegani. Bili so kakor trava polja in kakor zeleno zelišče, kakor trava na hišnih strehah in kakor ožgano žito, preden zraste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Toda jaz poznam tvoje prebivališče, tvoje odhajanje, tvoje prihajanje in tvoj bes zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ker je tvoj bes zoper mene in je tvoj hrup prišel gor v moja ušesa, zato bom zataknil svoj kavelj v tvoj nos in svojo brzdo med tvoje ustnice in te obrnil nazaj po poti, po kateri si prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'To ti bo znamenje: › To leto boste jedli kar zraste samo od sebe in drugo leto to, kar požene od istega, v tretjem letu pa sejte, žanjite, sadite vinograde in jejte od njihovega sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Preostanek od Judove hiše, ki je pobegnil, se bo ponovno ukoreninil navzdol in navzgor obrodil sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Kajti iz Jeruzalema bo izšel preostanek in tisti, ki pobegnejo z gore Sion. Gorečnost Gospoda nad bojevniki bo to storila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Zato tako govori Gospod glede asirskega kralja: ›Ta ne bo prišel v to mesto, niti tja ne bo izstrelil puščice, niti predenj ne bo prišel s ščiti, niti zoper njega ne bo nasul okopa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Po poti, po kateri je prišel, po isti se bo vrnil in ne bo prišel v to mesto,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '›Kajti jaz bom branil to mesto, da ga rešim zaradi sebe in zaradi svojega služabnika Davida.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Potem je odšel naprej Gospodov angel in jih v taboru Asircev udaril sto petinosemdeset tisoč. Ko so zgodaj zjutraj vstali, glej, oni vsi so bili mrtva trupla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Tako je asirski kralj Senaherib odpotoval, odšel, se vrnil in prebival v Ninivah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Pripetilo se je, ko je oboževal v hiši svojega boga Nisróha, da sta ga njegova sinova Adraméleh in Sarécer udarila z mečem in pobegnila v deželo Armenijo in namesto njega je zakraljeval njegov sin Asarhadón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'V tistih dneh je bil Ezekíja na smrt bolan. Amócov sin, prerok Izaija, je prišel k njemu ter mu rekel: »Tako govori Gospod: ›Postavi svojo hišo v red, kajti umrl boš in ne živel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Potem je Ezekíja svoj obraz obrnil k steni, molil h Gospodu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'in rekel: »Spomni se sedaj, oh Gospod, rotim te, kako sem hodil pred teboj v resnici in s popolnim srcem in delal to, kar je dobro v tvojem pogledu.« In Ezekíja je bridko zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Potem je prišla Gospodova beseda k Izaiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '»Pojdi in povej Ezekíju: ›Tako govori Gospod, Bog tvojega očeta Davida: ›Slišal sem tvojo molitev, videl sem tvoje solze. Glej, tvojim dnevom bom dodal petnajst let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Tebe in to mesto bom osvobodil iz roke asirskega kralja in jaz bom branil to mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'To ti bo znamenje od Gospoda, da bo Gospod storil to stvar, ki jo je govoril:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, '›Glej, senco stopinj, ki se je na Aházovi sončni uri spustila, bom ponovno privedel deset stopinj nazaj.‹« Tako se je sonce vrnilo [za] deset stopinj, po stopinjah, po katerih se je spustilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Pisanje Judovega kralja Ezekíja, ko je bil bolan in je okreval od svoje bolezni:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '»Rekel sem o preostanku svojih dni: ›Šel bom do velikih vrat groba. Prikrajšan sem preostanka svojih let.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Rekel sem: ›Ne bom videl Gospoda, celó Gospoda, v deželi živih. Ne bom več gledal človeka s prebivalci sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, '§ Moja starost je odšla in od mene je odstranjena kakor pastirski šotor. Kakor tkalec sem odrezal svoje življenje. Odrezal me bo z mučno boleznijo. Od dneva, celo do noči boš naredil moj konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Štel sem do jutra, da bo, tako kakor lev, zlomil vse moje kosti. Od dneva, celó do noči boš iz mene naredil konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Kakor žerjav ali lastovka, tako sem žvrgolel. Žaloval sem kakor golobica. Moje oči pešajo z gledanjem navzgor. Oh Gospod, zatiran sem, zavzemi se zame.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Kaj naj rečem? On mi je tako govoril in sam je to storil. Vsa svoja leta bom mirno hodil v grenkobi svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Oh Gospod, po teh stvareh ljudje živijo in v vseh teh stvareh je življenje mojega duha. Tako me boš obnovil in me pripravil, da živim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Glej, za mir sem imel veliko grenkobo, toda ti si v ljubezni do moje duše le-to osvobodil iz jame izprijenosti, kajti vse moje grehe si vrgel za svoj hrbet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Kajti grob te ne more hvaliti, smrt te ne more proslavljati. Tisti, ki gredo dol v jamo, ne morejo upati na tvojo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Živeči, živeči, ta te bo hvalil, kakor danes počnem jaz. Oče bo otrokom dal spoznati tvojo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Gospod je bil pripravljen, da me reši. Zato bomo peli moje pesmi, na glasbila na strune, vse dni našega življenja v hiši Gospodovi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Kajti Izaija je rekel: »Naj vzamejo kepo fig in jo položijo za pomirjevalo na vnetje in okreval bo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ezekíja je tudi rekel: »Kaj je znamenje, da bom šel gor, h Gospodovi hiši?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Ob tistem času je babilonski kralj Merodáh Baladán poslal Ezekíju pisma in darilo, kajti slišal je, da je bil bolan in je okreval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Ezekíja jih je bil vesel in jim razkazal hišo svojih dragocenih stvari: srebro, zlato, dišave, dragoceno mazilo in vso hišo svoje orožarne in vsega, kar se je našlo v njegovih zakladnicah. Ničesar ni bilo v njegovi hiši niti v vsem njegovem gospostvu, česar jim Ezekíja ni razkazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Potem je prerok Izaija prišel h kralju Ezekíju in mu rekel: »Kaj so rekli ti možje? In od kod so prišli k tebi?« Ezekíja je rekel: »K meni so prišli iz daljne dežele, celó iz Babilona.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Potem je rekel: »Kaj so videli v tvoji hiši?« Ezekíja je odgovoril: »Videli so vse, kar je v moji hiši. Ničesar ni med mojimi zakladi, česar jim ne bi pokazal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Potem Izaija reče Ezekíju: »Poslušaj besedo Gospoda nad bojevniki:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, '›Glej, prihajajo dnevi, da bo vse, kar je v tvoji hiši in to, kar so tvoji očetje prihranili v shrambi do tega dne, odneseno v Babilon. Nič ne bo ostalo,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, '›In izmed tvojih sinov, ki bodo izšli iz tebe, ki jih boš zaplodil, jih bodo odvedli proč in bodo evnuhi v palači babilonskega kralja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Potem je Ezekíja rekel Izaiju: »Dobra je Gospodova beseda, ki si jo povedal.« Poleg tega je rekel: »Kajti mir in resnica bosta v mojih dneh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '»Tolažite, tolažite moje ljudstvo,« govori vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '»Govorite tolažilno [prestolnici] Jeruzalem in kličite k njej, da je njeno bojevanje dovršeno, da je njena krivičnost odpuščena, kajti iz Gospodove roke je prejela dvojno za vse svoje grehe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Glas tistega, ki vpije v divjini: »Pripravite Gospodovo pot, v puščavi izravnajte glavno cesto za našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Vsaka dolina naj bo povišana in vsaka gora in hrib naj bosta znižana in skrivljeno naj bo izravnano in gorski grebeni ravnina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'in Gospodova slava se bo razodela in vse meso jo bo hkrati videlo, kajti Gospodova usta so to govorila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Glas je rekel: »Vpij.« Rekel je: »Kaj naj vpijem?« »Vse meso je trava in vsa njegova ljubkost je kakor cvetica polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Trava se suši, cvet veni, ker nanjo piha Gospodov duh. Zagotovo je ljudstvo trava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Trava se suši, cvet veni, toda beseda našega Boga bo obstala na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Oh Sion, ki prinašaš dobre novice, pojdi gor na visoko goro. Oh Jeruzalem, ki prinašaš dobre novice, povzdigni svoj glas z močjo. Povzdigni ga, ne boj se, govóri Judovim mestom: »Glejte, vaš Bog!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Glejte, Gospod Bog bo prišel z močno roko in njegov laket bo vladal zanj. Glejte, njegova nagrada je z njim in njegovo delo pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Svoj trop bo pasel kakor pastir. Jagnjeta bo zbral s svojim laktom in jih nosil v svojem naročju in nežno vodil tiste, ki so z mladiči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kdo je izmeril vode z dlanjo svoje roke, s pednjem premeril nebo, doumel prah zemlje po meri in odtehtal gore na vagah in hribe na tehtnici?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kdo je usmerjal Gospodovega Duha ali je bil njegov svetovalec in ga učil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'S kom se je posvetoval in kdo ga je poučeval in ga učil na stezi sodbe in ga učil spoznanja in mu pokazal pot razumevanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Glej, narodi so kakor kapljica iz vedra in šteti so kakor majhen prah na tehtnici. Glej, otoke dviguje kakor zelo majhno stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Libanon ni zadosten za gorenje niti njegove živali ne zadoščajo za žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Vsi narodi pred njim so kakor nič in zanj so vsi šteti manj kot nič in ničnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Komu hočete potem primerjati Boga? Ali kakšno podobnost hočete primerjati k njemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Delavec tali rezano podobo, zlatar jo prevleče z zlatom in uliva srebrne verižice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kdor je tako obubožan, da nima daritve, izbira drevo, ki ne bo trohnelo, zanj išče spretnega delavca, da pripravi rezano podobo, ki ne bo omajana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Mar niste vedeli? Mar niste slišali? Mar vam ni bilo to povedano od začetka? Mar niste razumeli od temeljev zemlje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'On je, ki sedi nad zemeljskim krogom, njegovi prebivalci pa so kakor kobilice, ki razprostira nebesa kakor zaveso in jih razširja kakor šotor za prebivanje v njem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'ki prince daje v nič, sodnike zemlje dela kakor ničnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Da, ne bodo posajeni, da, ne bodo posejani. Da, njihova klada se ne bo zakoreninila v zemlji in nanje bo tudi pihal in se bodo izsušili in vrtinčast veter jih bo odnesel kakor slamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '»H komu me boste potem primerjali ali [komu] bom enak?« govori Sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Povzdignite svoje oči na visoko in glejte, kdo je ustvaril te stvari, ki njihovo vojsko vodi ven po številu. Vse jih kliče po imenih z veličino svoje moči, ker je močan v moči; niti ena ne manjka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Zakaj praviš, oh Jakob in govoriš, oh Izrael: »Moja pot je skrita pred Gospodom in moja sodba je šla mimo mojega Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Mar nisi spoznal? Mar nisi slišal, da večen Bog, Gospod, Stvarnik koncev zemlje, ne slabi niti ni izmučen? Njegovega razumevanja ni možno preiskati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Silo daje slabotnim in tistim, ki nimajo moči, povečuje moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Celo mladostniki bodo oslabeli in bodo izmučeni in mladeniči bodo popolnoma padli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'toda tisti, ki čakajo na Gospoda, bodo obnavljali svojo moč, vzpenjali se bodo s perutmi kakor orli, tekli bodo in ne bodo izmučeni in hodili bodo in ne oslabeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Molčite pred menoj, oh otoki in naj ljudstvo obnavlja svojo moč. Naj pridejo bliže, potem jim pustite govoriti. Pridimo blizu skupaj k sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kdo je dvignil pravičnega človeka od vzhoda in ga poklical k svojemu stopalu, dal predenj narode in ga naredil, [da] vlada nad kralji? Izročil jih je kakor prah njegovemu meču in kakor slamo gnano k njegovemu loku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Zasledoval jih je in varno prešel; celó po poti, [po] kateri [še] ni šel s svojimi stopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kdo je delal in to storil, kličoč rodove od začetka? Jaz, Gospod, prvi in s poslednjimi; jaz sem ta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Otoki so to videli in se bali; konci zemlje so bili prestrašeni, se približali in prišli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Pomagali so vsak svojemu sosedu in vsak je svojemu bratu rekel: »Bodi odločnega poguma.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Tako je tesar hrabril zlatarja in kdor gladi s kladivom, tistega, ki udarja nakovalo, rekoč: »Ta je pripravljen za spajanje« in ga pritrdil z žeblji, da ta ne bi bil premaknjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Toda ti, Izrael, si moj služabnik, Jakob, ki sem ga izbral, seme Abrahama, mojega prijatelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Ti, ki sem te vzel od koncev zemlje in te poklical od njihovih glavnih mož in ti rekel: »Ti si moj služabnik, izbral sem te in te nisem zavrgel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Ne boj se, kajti jaz sem s teboj. Ne bodi potrt, kajti jaz sem tvoj Bog. Okrepil te bom, da, jaz ti bom pomagal, da, podpiral te bom z desnico svoje pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Glej, vsi tisti, ki so bili ogorčeni zoper tebe, bodo osramočeni in zbegani. Oni bodo kakor nič in tisti, ki se prepirajo s teboj, bodo propadli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Iskal jih boš in jih ne boš našel, celó tiste, ki so se pričkali s teboj. Tisti, ki se vojskujejo zoper tebe, bodo kakor nič in kakor stvar ničnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Kajti jaz, Gospod, tvoj Bog, bom držal tvojo desnico, rekoč ti: »Ne boj se, jaz ti bom pomagal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne boj se, ti ličinka Jakob in vi, Izraelovi možje, pomagal ti bom, govori Gospod in tvoj odkupitelj, Sveti Izraelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Glej, naredil te bom [za] novo ostro mlatilno pripravo z zobmi. Mlatil boš gore, jih razdrobil in hribe boš naredil kakor pleve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Vejál jih boš in veter jih bo odnesel proč in vrtinčast veter jih bo razkropil, ti pa se boš razveseljeval v Gospodu in slavil boš v Svetem Izraelovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Kadar ubogi in pomoči potrebni iščejo vode in je tam ni in njihov jezik odpoveduje zaradi žeje, jih bom jaz, Gospod, uslišal in jaz, Izraelov Bog, jih ne bom zapustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Odprl bom reke na visokih krajih in studence v sredi dolin. Divjino bom spremenil [v] vodni ribnik in suho deželo [v] izvire voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'V divjini bom zasadil cedro, akacijevo drevo, mirto in olivno drevo; v puščavi bom skupaj posadil cipreso, bor in pušpan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'da bodo lahko videli, spoznali, preudarili in skupaj razumeli, da je to storila Gospodova roka in Sveti Izraelov je to ustvaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Prinesite svojo pravdo,‹ govori Gospod; ›prinesite naprej svoje močne razloge, govori Kralj Jakobov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Naj jih prinesejo naprej in nam pokažejo kaj se bo zgodilo. Naj nam pokažejo prejšnje stvari, kakršne so, da jih lahko preudarimo in spoznamo njihov zadnji konec; ali nam oznanite stvari, ki pridejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Pokažite stvari, ki bodo odslej, da bomo lahko vedeli, da ste vi bogovi. Da, delajte dobro ali delajte zlo, da bomo lahko zaprepadeni in to skupaj gledali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Glejte, vi ste od ničnosti in vaše delo je ničevo; ogabnost je, kdor vas izbere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Dvignil sem nekoga iz severa in bo prišel. Od sončnega vzhoda bo klical moje ime in prišel bo nad prince kakor nad malto in kakor lončar gnete ilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kdo je razglasil od začetka, da bi mi lahko vedeli? In poprej, da bi lahko rekli: » On je pravičen?« Da, tam ni nikogar, ki kaže; da, tam ni nikogar, ki razglaša; da, tam ni nikogar, ki sliši vaše besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Prvi bo rekel Sionu: »Poglej, poglej jih.« In Jeruzalemu bom dal nekoga, ki prinaša dobre novice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Kajti gledal sem in tam ni bilo človeka, celo med njimi in tam ni bilo svetovalca, da bi lahko, ko sem jih povprašal, odgovoril besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Glej, vsi so ničnost, njihova dela so nič. Njihove ulite podobe so veter in zmešnjava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Glej, moj služabnik, ki ga podpiram; moj izvoljeni, v katerem se moja duša razveseljuje; svojega duha sem položil nanj. Oznanil bo sodbo poganom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Ne bo vpil, niti povzdignil [glasu], niti svojemu glasu ne bo povzročil, da bi bil slišan na ulici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Poškodovanega trsta ne bo zlomil in kadečega stenja ne bo ugasnil. Sodbo bo privedel k resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Ne bo opešal niti ne bo izgubil poguma, dokler ne postavi sodbe na zemlji in otoki bodo čakali na njegovo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tako govori Gospod Bog, ki je ustvaril nebesa in jih razpel; ki je razprostrl zemljo in to, kar prihaja iz nje; on, ki daje dih ljudstvu na njej in duha tem, ki hodijo po njej:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '»Jaz, Gospod, sem te poklical v pravičnosti in držal bom tvojo roko in te varoval in dam te za zavezo ljudstvu, za svetlobo poganom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'da odpreš slepe oči, da privedeš jetnike iz ječe in te, ki sedijo v temi, ven iz jetnišnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Jaz sem Gospod. To je moje ime in svoje slave ne bom dal drugemu niti svoje hvale rezanim podobam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Glej, prejšnje stvari so se zgodile in razglašam nove stvari. Preden vzbrstijo ti povem o njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Zapojte Gospodu novo pesem in njegovo hvalo s konca zemlje, vi, ki greste dol do morja in vse, kar je v njem, otoki in njegovi prebivalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Naj divjina in njena mesta dvignejo svoj glas, vasi, ki jih naseljuje Kedár. Naj skalni prebivalci pojejo, naj zavpijejo z vrhov gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Naj dajo slavo Gospodu in razglašajo njegovo hvalo na otokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Gospod bo šel naprej kakor mogočen mož, ljubosumnost bo razvnel kakor bojevnik. Vpil bo, da, rjovel, prevladal bo zoper svoje sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, '»Dolgo časa sem zadrževal svoj mir, bil sem tiho in se zadrževal. Sedaj [pa] bom vpil kakor ženska v porodnih mukah; hkrati bom uničil in požrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Opustošil bom gore in hribe in posušil vsa njihova zelišča in reke bom naredil otoke in posušil bom ribnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Privedel bom slepe po poti, ki je niso poznali, vodil jih bom po stezah, ki jih niso poznali. Temo pred njimi bom naredil svetlobo in skrivljene stvari ravne. Te stvari jim bom storil in ne bom jih zapustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Obrnjeni bodo nazaj, silno bodo osramočeni tisti, ki zaupajo v rezane podobe, ki ulitim podobam pravijo: ›Vi ste naši bogovi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Poslušajte, vi gluhi, in glejte, vi slepi, da boste lahko videli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kdo je slep, razen mojega služabnika? Ali gluh kakor moj poslanec, ki sem ga poslal? Kdo je slep, kakor kdor je popoln in slep kakor Gospodov služabnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Gleda mnoge stvari, toda ti jih ne obeležuješ; odpira ušesa, toda on ne sliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Gospod je zelo zadovoljen zaradi svoje pravičnosti; poveličeval bo postavo in jo naredil častitljivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Toda to je ljudstvo, oropano in oplenjeno; vsi izmed njih so ujeti v luknje in skriti v jetnišnicah. Za plen so in nihče ne osvobaja; za ukradeno blago in nihče ne reče: ›Povrni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kdo izmed vas bo temu pazljivo prisluhnil? Kdo bo prisluhnil in slišal za čas, ki pride?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kdo je Jakoba izročil v plen in Izraela roparjem? Mar ne Gospod, on, zoper katerega smo grešili? Kajti niso želeli hoditi po njegovih poteh niti niso bili poslušni njegovi postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Zato je nanj izlil razjarjenost svoje jeze in moč bitke. To ga je vžgalo vsenaokoli, vendar ni vedel. To ga je žgalo, vendar si tega ni vzel k srcu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Toda sedaj tako govori Gospod, ki te je ustvaril, oh Jakob in tisti, ki te je oblikoval, oh Izrael: »Ne boj se, kajti odkupil sem te, poklical sem te s tvojim imenom, moj si.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Ko hodiš skozi vode, bom s teboj in skozi reke, te ne bodo preplavile. Ko hodiš skozi ogenj, ne boš ožgan niti se plamen ne bo vnel na tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Kajti jaz sem Gospod, tvoj Bog, Sveti Izraelov, tvoj Odrešenik. Egipt sem dal za tvojo odkupnino, Etiopijo in Sebo zate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Ker si bil dragocen v mojem pogledu, bil si častitljiv in jaz sem te ljubil. Zato bom zate dal ljudi in ljudstva za tvoje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne boj se, kajti jaz sem s teboj. Tvoje seme bom privedel od vzhoda in te zbral od zahoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Severu bom rekel: ›Izroči‹ in jugu: ›Ne zadržuj.‹ Moje sinove privedi od daleč in moje hčere od koncev zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'celó vsakega, ki je klican z mojim imenom, kajti jaz sem ga ustvaril za svojo slavo, jaz sem ga oblikoval; da, jaz sem ga naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Privedi slepo ljudstvo, ki ima oči in gluhe, ki imajo ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Naj bodo vsi narodi zbrani skupaj in naj bo ljudstvo zbrano. Kdo izmed njih lahko to razglasi in nam pokaže prejšnje stvari? Naj privedejo naprej svoje priče, da bodo lahko opravičeni. Ali naj slišijo in rečejo: › To je resnica.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vi ste moje priče,‹ govori Gospod in moj služabnik, ki sem ga izbral, da me boste lahko poznali in mi verjeli in razumeli, da jaz sem ta. Pred menoj ni bil oblikovan noben Bog niti ne bo za menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Jaz, celó jaz sem Gospod in poleg mene ni rešitelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Razglasil sem, rešil in pokazal, ko med vami ni bilo nobenega tujega boga. Zato ste vi moje priče,‹ govori Gospod, ›da jaz sem Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Da, preden je bil dan, jaz sem in nobenega ni, ki lahko osvobodi iz moje roke. Delal bom in kdo bo to dopustil?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tako govori Gospod, vaš odkupitelj, Sveti Izraelov: ›Zaradi vas sem poslal v Babilon in ponižal vse njihove plemiče in Kaldejce, katerih vpitje je na ladjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Jaz sem Gospod, vaš Sveti, stvarnik Izraela, vaš Kralj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tako govori Gospod, ki dela pot v morju in stezo v mogočnih vodah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'ki privede naprej bojni voz in konja, vojsko in moč; skupaj se bodo ulegli, ne bodo vstali. Izumrli so, pogašeni so kakor predivo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne spominjajte se prejšnjih stvari niti ne preudarjajte stvari od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Glejte, storil bom novo stvar. Sedaj bo ta vzbrstela; mar tega ne boste spoznali? Naredil bom celo pot v divjini in reke v puščavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Divja žival polja me bo spoštovala, zmaji in sove, ker dam vode v divjino in reke v puščavo, da dam piti svojemu ljudstvu, svojim izbranim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'To ljudstvo sem oblikoval zase, naznanjali bodo mojo hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Toda ti nisi klical k meni, oh Jakob, temveč si se me naveličal, oh Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nisi mi privedel majhne živine od svojih žgalnih daritev niti me nisi častil s svojimi klavnimi daritvami. Nisem ti storil, da služiš z daritvijo niti te nisem mučil s kadilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Z denarjem mi nisi kupil nobenega sladkornega trsta niti me nisi nasičeval s tolščo svojih klavnih daritev, temveč si me s svojimi grehi primoral, da služim; izmučil si me s svojimi krivičnostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Jaz, celó jaz, sem tisti, ki zaradi sebe izbrisujem tvoje prestopke in se ne bom spominjal tvojih grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Spomni me, skupaj se pravdajva. Ti razglasi, da boš lahko opravičen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Tvoj prvi oče je grešil in tvoji učitelji so se pregrešili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Zato sem oskrunil prince svetišča in dal Jakoba v prekletstvo in Izraela v graje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Vendar sedaj poslušaj, oh Jakob, moj služabnik in Izrael, ki sem ga izbral:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, '»Tako govori Gospod, ki te je naredil in te oblikoval iz maternice, ki ti bo pomagal: ›Ne boj se, oh Jakob, moj služabnik in ti Ješurún, ki sem ga izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Kajti vodo bom izlil na tistega, ki je žejen in poplave na suha tla. Svojega duha bom izlil na tvoje seme in svoj blagoslov na tvoje potomstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Pognali bodo kakor med travo, kakor vrbe ob vodnih tokovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Nekdo bo rekel: ›Jaz sem Gospodov,‹ drugi se bo imenoval po Jakobovem imenu, drugi se bo s svojo roko podpisal Gospodu in se poimenoval po imenu Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tako govori Gospod, Izraelov Kralj in njegov odkupitelj, Gospod nad bojevniki: ›Jaz sem prvi in jaz sem zadnji in poleg mene ni Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Kdo bo klical kakor jaz in bo to razglasil in bo to uredil zame, odkar sem določil starodavno ljudstvo? Stvari, ki prihajajo in bodo prišle, naj jim jih oni pokažejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ne bojte se niti ne bodite prestrašeni. Mar ti nisem povedal od tistega časa in ti to razglasil? Vi ste celo moje priče. Mar je Bog razen mene? Da, tam ni Boga, jaz ne poznam nobenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Tisti, ki delajo rezano podobo, so vsi izmed njih ničnost in njihove izvrstne stvari ne bodo koristile in oni so svoje lastne priče; ne vidijo niti ne vedo, da bi jih bilo sram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kdo je oblikoval boga ali ulil rezano podobo, ki ni koristna za nič?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Glej, vsi njegovi tovariši bodo osramočeni in delavci, oni so izmed ljudi. Naj bodo vsi zbrani skupaj, naj vstanejo; vendar se bodo bali in skupaj bodo osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kovač s kleščami dela tako v oglju, kakor ga oblikuje s kladivi in ga izdeluje z močjo svojih laktov. Da, lačen je in njegova moč peša. Ne pije vode in je slaboten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Lesorezec izteza svoje merilo, označuje s črtalom, oblikuje z dleti in ga začrtuje s šestilom in ga dela po podobi človeka, glede na človeško lepoto, da bi ta lahko ostal v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Poseka si cedre in jemlje cipreso in hrast, ki si jih je okrepil med gozdnimi drevesi, zasadi veliki jesen in dež ga neguje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Potem bo to za človeka, da zakuri, kajti vzel bo od tega in se ogrel; da, to vžge in speče kruh; da, naredi boga in ga obožuje; izdela rezano podobo in pada dol k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Del od tega zakuri v ognju, z delom od tega jé meso, speče pečenko in je nasičen. Da, ogreje se in reče: ›Aha, topel sem, videl sem ogenj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Od preostanka pa si izdela boga, celó svojo rezano podobo, pada dol k njej in jo obožuje in moli k njej ter pravi: ›Osvobodi me, kajti ti si moj bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Niso spoznali niti razumeli, kajti zaprl je njihove oči, da ne morejo videti in njihova srca, da ne morejo razumeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'In nihče ne preudari v svojem srcu niti tam ni spoznanja niti razumevanja, da reče: ›Del tega sem spekel v ognju; da, na njegovi žerjavici sem spekel tudi kruh, spekel sem meso in ga pojedel in njegov preostanek bom naredil [za] ogabnost? Ali bom padal dol k štoru?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Hrani se s pepelom, zavedeno srce ga je obrnilo vstran, da ne more osvoboditi svoje duše niti reči: › Mar ni laž v moji desnici?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Spomni se tega, oh Jakob in Izrael, kajti ti si moj služabnik. Jaz sem te oblikoval, ti si moj služabnik. Oh Izrael, ne bom te pozabil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Tvoje prestopke sem izbrisal kakor gost oblak in kakor oblak tvoje grehe. Vrni se k meni, kajti jaz sem te odkupil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Pojte, oh ve nebesa, kajti Gospod je to storil. Vpijte globočine zemlje. Izbruhnite v petje, ve gore, oh gozd in vsako drevo v njem, kajti Gospod je odkupil Jakoba in se proslavil v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tako govori Gospod, tvoj odkupitelj in on, ki te je oblikoval iz maternice, jaz sem Gospod, ki delam vse stvari, ki sam razprostiram nebo, ki sam na široko razširjam zemljo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'ki onemogočam simbole lažnivcev in vedeževalce delam besne; ki modre može obračam nazaj in njihovo znanje delam nespametno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'ki potrjujem besedo svojega služabnika in izvajam nasvet svojih poslancev; ki [prestolnici] Jeruzalemu pravim: ›Naseljena boš‹ in Judovim mestom: ›Zgrajena boste‹ in jaz bom vzdignil njihove razpadle kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Ki pravim globini: ›Bodi suha‹ in posušil bom tvoje reke;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'ki pravim o Kiru: › On je moj pastir‹ in izvršil bo vse moje zadovoljstvo. Celo Jeruzalemu govorim: ›Zgrajen boš;‹ in templju: ›Tvoj temelj bo položen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Tako govori Gospod svojemu maziljencu Kiru, čigar desnico sem prijel, da bi pred njim podjarmil narode in odpasal bom ledja kraljev, da pred njim odprem dvoje opuščenih velikih vrat in velika vrata ne bodo zaprta:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, '»Jaz bom šel pred teboj in naredil skrivljene kraje ravne, bronasta velika vrata bom razbil na koščke in železne zapahe presekal na dvoje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Dal ti bom zaklade teme in skrita bogastva skrivnih krajev, da boš lahko vedel, da sem jaz, Gospod, ki te kličem s tvojim imenom, Izraelov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Zaradi Jakoba, mojega služabnika in Izraela, mojega izvoljenega, sem te celó poklical po tvojem imenu. Imenoval sem te, čeprav me nisi poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Jaz sem Gospod in nobenega drugega ni, ni Boga poleg mene. Opasal sem te, čeprav me nisi poznal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'da bi lahko vedeli od sončnega vzhoda in od zahoda, da ni nikogar poleg mene. Jaz sem Gospod in nobenega drugega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Jaz oblikujem svetlobo in ustvarjam temo, sklepam mir in ustvarjam zlo. Jaz, Gospod, delam vse te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Kapljajte, ve nebesa od zgoraj in naj nebo izlije pravičnost. Naj se zemlja odpre in naj rodi rešitev duš in naj skupaj požene pravičnost; jaz, Gospod, sem to ustvaril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Gorje tistemu, ki se prepira s svojim Stvarnikom! Naj se črepinja prička s črepinjami zemlje. Mar bo ilo reklo tistemu, ki ga oblikuje: »Kaj delaš?« Ali tvoje delo: »On nima rok?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Gorje tistemu, ki pravi svojemu očetu: »Čemu si zaplodil?« Ali ženski: »Kaj si rodila?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tako govori Gospod, Sveti Izraelov in njegov Stvarnik: »Vprašajte me o stvareh, ki pridejo, glede mojih sinov in glede dela mojih rok mi zapovejte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Naredil sem zemljo in na njej ustvaril človeka. Jaz, celó moje roke so razprostrle nebo in zapovedal sem vsej njegovi vojski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Dvignil sem ga v pravičnosti in jaz bom usmerjal vse njegove poti. Zgradil bo moje mesto in izpustil bo moje ujetnike, ne za ceno niti [ne za] nagrado,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tako govori Gospod: »Trud Egipta in trgovanje Etiopije in Sabejcev, postavnih mož, bo prišlo k tebi in oni bodo tvoji. Prišli bodo za teboj, v verigah bodo prišli in padli dol k tebi, ponižno te bodo prosili, rekoč: ›Zagotovo je Bog v tebi in tam ni nikogar drugega, tam ni Boga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Resnično, ti si Bog, ki samega sebe skrivaš, oh Izraelov Bog, Odrešenik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Osramočeni bodo in tudi zbegani, vsi izmed njih. Skupaj bodo šli v zmešnjavo, ki so izdelovalci malikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Toda Izrael bo rešen v Gospodu z večno rešitvijo duš. Ne boste osramočeni niti zbegani, od veka do veka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Kajti tako govori Gospod, ki je ustvaril nebo; sam Bog, ki je oblikoval zemljo in jo naredil, osnoval jo je, ni je ustvaril zaman, oblikoval jo je, da bi bila naseljena. Jaz sem Gospod in nobenega drugega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nisem govoril na skrivnem, na temnem kraju zemlje. Jakobovemu semenu nisem rekel: ›Zaman me iščite.‹ Jaz, Gospod, govorim pravičnost, razglašam stvari, ki so pravilne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Zberite se in pridite, približajte se skupaj, vi, ki ste pobegnili narodom. Nimajo spoznanja, ki postavljajo les svojih rezanih podob in molijo k bogu, ki ne more rešiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Povejte in privedite jih blizu; da, naj se skupaj posvetujejo. Kdo je to razglasil od starodavnega časa? Kdo je to povedal od tistega časa? Mar nisem jaz, Gospod? In nobenega drugega Boga ni poleg mene, pravičnega Boga in Odrešenika, nobenega ni poleg mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Poglejte k meni in bodite rešeni, vsi konci zemlje, kajti jaz sem Bog in nobenega drugega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Prisegel sem sam pri sebi, beseda je izšla iz mojih ust v pravičnosti in se ne bo vrnila: ›Da se bo k meni priklonilo vsako koleno, vsak jezik bo prisegel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Zagotovo bo nekdo rekel: ›V Gospodu imam pravičnost in moč.‹ Celó k njemu bodo prišli ljudje in vsi tisti, ki so ogorčeni zoper njega, bodo osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'V Gospodu bo vse seme Izraela opravičeno in bo slavilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel se je upognil dol, Nebó se sklanja, njihovi maliki so bili na živalih in na živini. Vaši vozovi so bili težko obloženi, breme so vsaki izmučeni živini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Sklonili so se, skupaj so se upognili, niso mogli osvoboditi bremena, temveč so sami šli v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Prisluhnite mi, oh hiša Jakobova in ves ostanek Izraelove hiše, ki vas nosim od trebuha, ki ste nošeni od maternice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Celó do vaše visoke starosti jaz sem in celó do osivelih las vas bom prenašal. Jaz sem naredil, jaz bom vzdignil, celó jaz bom nosil in vas osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'S kom me boste primerjali in me naredili enakega in me primerjali, da bi bila lahko podobna?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Iz torbe iztresajo zlato in na tehtnici tehtajo srebro in najemajo zlatarja in ta ga naredi boga. Padajo dol, da, obožujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Vzdignejo ga na ramo, prenašajo ga in ga postavljajo na njegov prostor in ta stoji, iz svojega prostora se ne bo odstranil. Da, nekdo bo vpil k njemu, vendar mu ne more odgovoriti niti ga rešiti iz njegove stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Spomnite se tega in bodite možje. Ponovno premislite, oh vi, prestopniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Spominjajte se prejšnjih stvari od davnine, kajti jaz sem Bog in ni nikogar drugega, jaz sem Bog in nobenega ni podobnega meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'konec razglašam od začetka in od starodavnih časov stvari, ki še niso storjene, rekoč: ›Moj nasvet bo obstal in storil bom vse, kar mi ugaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Ptico roparico kličem od vzhoda, moža, ki izvršuje mojo namero iz daljne dežele. Da, jaz sem to govoril, jaz bom tudi privedel, da se zgodi, to sem namenil in to bom tudi storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Prisluhnite mi, vi arogantni, ki ste daleč od pravičnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'svojo pravičnost privedem blizu; ta ne bo daleč stran in moja rešitev duš ne bo mudila. Rešitev duš bom postavil na Sion zaradi Izraela, svoje slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Pridi dol in se usedi v prah, oh devica, hči babilonska. Sedi na tla; ni prestola, oh hči Kaldejcev, kajti ne boš več imenovana nežna in prefinjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Vzemi mlinske kamne in melji moko. Odkrij svoja zagrinjala, razgali nogo, odkrij stegno, prebredi reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, '§ Tvoja nagota bo odkrita, da, tvoja sramota bo vidna. Maščeval se bom in ne bom te srečal kakor človek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Glede našega odkupitelja, Gospod nad bojevniki je njegovo ime, Sveti Izraelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sedi tiho in pojdi v temo, oh hči Kaldejcev, kajti ne boš več imenovana: ›Gospa kraljestev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Ogorčen sem bil nad svojim ljudstvom, umazal sem svojo dediščino in jih predal v tvojo roko. Nobenega usmiljenja jim nisi pokazala, na starce si zelo težko položila svoj jarem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'In ti praviš: ›Jaz bom gospa na veke.‹ Tako, da si teh stvari nisi vzela k srcu niti se nisi spomnila zadnjega konca tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Zato poslušaj sedaj to, ti, ki si predana užitkom, ki brezskrbno prebivaš, ki v svojem srcu praviš: ›Jaz sem in nihče drug poleg mene; ne bom sedela kakor vdova niti ne bom poznala izgube otrok.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Toda ti dve stvari bosta prišli k tebi v trenutku, v enem dnevu, izguba otrok in vdovstvo. Nadte bodo prišli v svoji popolnosti zaradi množice tvojih čarodejstev in zaradi silnega obilja tvojih izrekanj urokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Kajti zaupala si v svojo zlobnost. Rekla si: ›Nihče me ne vidi.‹ Tvoja modrost in tvoje znanje te je sprevrglo in v svojem srcu si rekla: ›Jaz sem in nihče drug poleg mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Zato bo nadte prišlo zlo; ne boš vedela od kod vstaja in nate bo padla vragolija; ne boš je sposobna odložiti in opustošenje bo nenadoma prišlo nadte, ki ga ne boš poznala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Postavi se sedaj s svojimi izrekanji urokov in z množico svojih čarodejstev, s katerimi si se trudila od svoje mladosti, če ti bo to lahko koristilo, če boš lahko prevladala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Izmučena si v množici svojih nasvetov. Naj sedaj astrologi, zvezdogledi in mesečni napovedovalci vstanejo in te rešijo pred temi stvarmi, ki bodo prišle nadte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Glej, so kakor strnišče, ogenj jih bo sežgal, ne bodo se osvobodili iz oblasti plamena. Tam ne bo žerjavice, da bi se ob njej ogreli niti ognja, da bi pred njim sedeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Takšni ti bodo tisti, s katerimi si se trudila, celó tvoji trgovci od tvoje mladosti. Tavali bodo vsakdo k svoji četrti, nihče te ne bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Poslušajte to, oh hiša Jakobova, ki ste imenovani z imenom Izrael in ste izšli iz Judovih vodá, ki prisegate pri Gospodovem imenu in omenjate Izraelovega Boga, vendar ne v resnici niti ne v pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Kajti imenujejo se po svetem mestu in se naslanjajo na Izraelovega Boga; Gospod nad bojevniki je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Razglasil sem prejšnje stvari od začetka in izšle so iz mojih ust in pokazal sem jih; nenadoma sem jih naredil in zgodile so se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Ker sem vedel, da si trdovratna in je tvoj vrat železna kita in tvoja obrv bron,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'sem ti to celo od začetka razglasil; preden se je zgodilo, sem ti to pokazal, da ne bi rekla: ›Moj malik jih je naredil, moja rezana podoba in moja ulita podoba jim je zapovedala.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Slišal si, videl si vse to in ali ne boš tega razglasil? Od tega časa sem ti pokazal nove stvari, celo skrite stvari in ti jih nisi poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Sedaj so ustvarjene in ne od začetka; celo pred dnevom, ko jih nisi slišal, da ne bi rekel: »Glej, poznal sem jih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Da, ne slišiš; da, ne poznaš; da, od tistega časa, ko tvoje uho ni bilo odprto, kajti vedel sem, da boš postopal zelo zahrbtno in si bil od maternice imenovan prestopnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Zaradi svojega imena bom odložil svojo jezo in zaradi svoje hvale se bom zadržal, da te ne odsekam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Glej, prečistil sem te, toda ne s srebrom; izbral sem te v talilni peči stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Zaradi sebe, celó zaradi sebe, bom to storil, kajti kako bi bilo moje ime umazano? In svoje slave ne bom dal drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Prisluhni mi, oh Jakob in Izrael, moj poklicani; jaz sem; jaz sem prvi, jaz sem tudi zadnji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Moja roka je tudi položila temelj zemlji in moja desnica je razpela nebo. Ko kličem k njima, skupaj vstaneta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Vsi vi, zberite se in poslušajte; kdo izmed njih je razglasil te stvari? Gospod ga je ljubil. Storil bo, kar mu ugaja nad Babilonom in njegov laket bo na Kaldejcih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Jaz, celó jaz, sem govoril. Da, poklical sem ga. Privedel sem ga in svojo pot bo naredil uspešno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Pridite blizu k meni, poslušajte to; od začetka nisem govoril na skrivnem; od časa, ko je to bilo, tam jaz sem. In sedaj me je poslal Gospod Bog in njegov Duh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tako govori Gospod, tvoj Odkupitelj, Sveti Izraelov: »Jaz sem Gospod, tvoj Bog, ki te učim, da boš imel koristi, ki te vodim po poti, po kateri naj bi šel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Oh, da bi prisluhnil mojim zapovedim! Potem bi bil tvoj mir kakor reka in tvoja pravičnost kakor morski valovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Tudi tvojega semena bi bilo kakor peska in potomstvo tvoje notranjosti podobno njegovemu gramozu; njegovo ime ne bi bilo odrezano niti uničeno izpred mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Pojdite naprej iz Babilona, pobegnite od Kaldejcev, z glasom petja razglasite, povejte to, izustite to celó do konca zemlje. Recite: › Gospod je odkupil svojega služabnika Jakoba.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Niso bili žejni, ko jih je vodil skozi puščave. Zanje je vodam veleval, da tečejo iz skale. Razklal je tudi skalo in iz nje so pridrle vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Tam ni miru,« govori Gospod, »zlobnemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Poslušajte me, oh otoki in prisluhnite, ve ljudstva od daleč. Gospod me je poklical iz maternice, od notranjosti moje matere je naredil omembo mojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Moja usta je naredil kakor oster meč; v senco svoje roke me je skril in me naredil zglajeno puščico; v svojem tulu me je skril');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'in mi rekel: »Ti si moj služabnik, oh Izrael, v katerem bom proslavljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Potem sem rekel: »V prazno sem se trudil, svojo moč sem porabil zaman in v prazno. Vendar je zagotovo moja sodba z Gospodom in moje delo z mojim Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, '»In sedaj,« govori Gospod, ki me je oblikoval od maternice, da bi bil njegov služabnik, da Jakoba ponovno privedem k njemu: »Čeprav Izrael ne bi bil zbran, bom vendar veličasten v Gospodovih očeh in moj Bog bo moja moč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Rekel je: »To je lahka stvar, da bi bil moj služabnik, da vzdigneš Jakobove rodove in da obnoviš Izraelove ohranjene. Prav tako te bom dal za svetlobo poganom, da boš lahko moja rešitev duš do konca zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tako govori Gospod, Izraelov Odkupitelj in njegov Sveti tistemu, ki ga človek prezira, tistemu, ki ga narod zaničuje, služabniku vladarjev: ›Kralji bodo videli in vstali, tudi princi bodo oboževali zaradi Gospoda, ki je zvest in Svetega Izraelovega in on bo izbral tebe.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tako govori Gospod: »Ob sprejemljivem času sem te uslišal in na dan rešitve duše sem ti pomagal in ohranil te bom in te dal za zavezo ljudstvu, da povzdigneš deželo, da povzročiš, da podedujejo zapuščene dediščine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'da boš lahko ujetnikom rekel: ›Pojdite naprej;‹ tistim, ki so v temi: ›Pokažite se.‹ Pasli bodo po poteh in njihovi pašniki bodo na vseh visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ne bodo niti lačni niti žejni, niti jih ne bosta udarila, niti vročina, niti sonce, kajti on, ki ima usmiljenje do njih, jih bo vodil, celo pri vodnih izvirih jih bo usmerjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Vse svoje gore bom naredil pot in moje glavne ceste bodo povišane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Glej, ti bodo prišli od daleč in glej, ti od severa in od zahoda in ti iz dežele Siním.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Prepevaj, oh nebo in bodi radostna, oh zemlja in izbruhnite v petje, oh gore. Kajti Gospod je potolažil svoje ljudstvo in usmiljen bo do svojih trpečih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Toda Sion je rekel: » Gospod me je zapustil in moj Gospod me je pozabil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Mar lahko ženska pozabi svojega doječega otroka, da ne bi imela sočutja do sina svoje maternice? Da, one lahko pozabijo, vendar jaz ne bom pozabil tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Glej, vrezal sem te na dlani svojih rok, tvoja obzidja so nenehno pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tvoji otroci se bodo podvizali, tvoji uničevalci in tisti, ki so te naredili opustošeno, bodo šli od tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Dvigni svoje oči naokoli in poglej. Vsi ti se zbirajo skupaj in prihajajo k tebi. Kakor jaz živim,‹ govori Gospod, ›zanesljivo se boš oblekla z njimi vsemi, kakor z ornamentom in si jih privezala nase, kakor stori nevesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Kajti tvoji opustošeni in tvoji zapuščeni kraji in dežela tvojega uničenja bo sedaj torej preozka zaradi prebivalcev in tisti, ki so te pogoltnili, bodo daleč proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Otroci, ki jih boš imela, potem ko si izgubila druge, bodo v tvoja ušesa ponovno govorili: ›Kraj je preozek zame. Daj mi prostor, da bom lahko prebival.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Potem boš v svojem srcu rekla: ›Kdo mi je te rodil, glede na to, da sem izgubila svoje otroke in sem zapuščena, ujetnica in se selim sem ter tja? In kdo je te vzgojil? Glej, sama sem ostala, kje so bili tile?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, '§ Tako govori Gospod Bog: »Glej, svojo roko bom dvignil k poganom in svoj prapor postavil k ljudstvu in tvoje sinove bodo privedli na njihovih rokah in tvoje hčere bodo nošene na njihovih ramah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Kralji bodo tvoji negovalni očetje in njihove kraljice tvoje negovalne matere. S svojim obrazom se bodo priklonili k tebi proti zemlji in lizali prah tvojih stopal in vedela boš, da jaz sem Gospod, kajti tisti, ki čakajo name, ne bodo osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Mar bo plen vzet od mogočnega, mar bo pravično ujetništvo osvobojeno?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Toda tako govori Gospod: »Celo ujetniki mogočnega bodo odvzeti in plen strašnega bo osvobojen, kajti jaz se bom spoprijel s tistim, ki se spoprijema s teboj in jaz bom rešil tvoje otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Z njihovim lastnim mesom bom hranil tiste, ki te zatirajo in pijani bodo s svojo lastno krvjo kakor s sladkim vinom in vse meso bo vedelo, da jaz sem Gospod, tvoj Odrešenik in tvoj Odkupitelj, Mogočni Jakobov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tako govori Gospod: »Kje je ločitveni list vaše matere, ki sem jo odslovil? Ali kateri izmed mojih upnikov je ta, h kateremu sem vas prodal? Glejte, zaradi svojih krivičnosti ste se sami prodali in zaradi vaših prestopkov je vaša mati odslovljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Zakaj ni bilo človeka, ko sem prišel? Ko sem klical ni bilo nobenega, da odgovori? Mar je moja roka precej skrajšana, da ne more odkupiti? Mar nimam moči, da osvobodim? Glejte, ob svoji graji posušim morje, reke naredim za divjino. Njihove ribe zaudarjajo, ker tam ni vode in poginjajo zaradi žeje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Jaz obláčim nebo s črnino in vrečevino delam [za] njihovo pokrivalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Gospod Bog mi je dal jezik učenega, da bi vedel kako ob pravem času govoriti besedo tistemu, ki je izmučen. Zbuja [me] jutro za jutrom, on zbuja moje uho, da slišim kakor učeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Gospod Bog mi je odprl moje uho in nisem bil uporen, niti se nisem odvrnil nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Svoj hrbet sem dal tistim, ki so me udarjali in svoja lica tistim, ki so mi pulili brado. Svojega obraza nisem skril pred sramoto in pljuvanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Kajti Gospod Bog mi bo pomagal, zato ne bom zbegan. Zato sem svoj obraz naravnal kakor kremen in vem, da ne bom osramočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Blizu je ta, ki me opravičuje. Kdo se bo spoprijel z menoj? Stopiva skupaj. Kdo je moj nasprotnik? Naj pride bliže k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Glej, Gospod Bog mi bo pomagal; kdo je tisti, ki me bo obsojal? Glej, vsi se bodo postarali kakor obleka, molj jih bo požrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kdo je med vami, ki se boji Gospoda, ki uboga glas svojega služabnika, ki hodi v temi in nima svetlobe? Naj zaupa v Gospodovo ime in se naslanja na svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Glejte, vsi vi, ki prižigate ogenj, ki se naokrog obdajate z iskrami. Hodite v svetlobi svojega ognja in v iskrah, ki ste jih vžgali. To boste imeli od moje roke; ulegli se boste v bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Prisluhnite mi, vi, ki sledite pravičnosti, vi, ki iščete Gospoda. Glejte na skalo, iz katere ste izklesani in k luknji jame, iz katere ste izkopani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Poglejte na Abrahama, svojega očeta in na Saro, ki vas je rodila. Kajti poklical sem ga samega, ga blagoslovil in namnožil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Kajti Gospod bo tolažil Sion, tolažil bo vse njegove opustošene kraje in njegovo divjino bo naredil podobno Edenu in njegovo puščavo podobno Gospodovemu vrtu. V njem bo najti radost in veselje, zahvaljevanje in glas melodije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Prisluhni mi, moje ljudstvo; pazljivo mi prisluhni, oh moj narod. Kajti postava bo izšla od mene in svojo sodbo bom naredil, da počiva za svetlobo ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Moja pravičnost je blizu, moja rešitev duš je odšla naprej in moji lakti bodo sodili ljudstvo; otoki bodo čakali name in v moj laket bodo zaupali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Povzdignite svoje oči k nebu in poglejte dol na zemljo spodaj, kajti nebo bo izginilo proč kakor dim in zemlja se bo postarala kakor obleka in tisti, ki prebivajo na njej, bodo umrli na podoben način, toda moja rešitev duš bo večna in moja pravičnost ne bo odpravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Prisluhnite mi vi, ki poznate pravičnost, ljudstvo, v čigar srcu je moja postava. Ne bojte se graje ljudi niti ne bodite prestrašeni ob njihovih zasramovanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Kajti molj jih bo pojedel kakor obleko in ličinka jih bo pojedla kakor volno, toda moja pravičnost bo na veke in moja rešitev duš od roda do roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Zbudi se, zbudi se, nadeni si moč, oh Gospodov laket. Zbudi se kakor v starodavnih dneh in rodovih od davnine. Mar nisi ti tisti, ki je posekal Rahaba in ranil zmaja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Mar nisi ti tisti, ki je osušil morje, vode velike globine, ki je globine morja spremenil v pot za odkupljene, da so prešli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Zato se bodo Gospodovi odkupljenci vrnili in s petjem prišli na Sion in večna radost bo na njihovi glavi. Dosegli bodo veselje in radost, bridkost in žalovanje pa bosta pobegnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Jaz, celó jaz sem ta, ki vas tolaži. Kdo si ti, da bi se bal človeka, ki bo umrl in človeškega sina, ki bo narejen kot trava,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'pozabljaš pa Gospoda, svojega stvarnika, ki je razprostrl nebo in položil temelje zemlji in si se nenehno vsak dan bal zaradi razjarjenosti zatiralca, kakor če bi bil ta pripravljen, da uniči? In kje je zatiralčeva razjarjenost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Ujeti popotnik hiti, da bi bil lahko izpuščen in da ne bi umrl v jami niti da njegovega kruha ne bi zmanjkalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Toda jaz sem Gospod, tvoj Bog, ki je razdelil morje, katerega valovi rjovijo: » Gospod nad bojevniki je njegovo ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Svoje besede sem položil v tvoja usta in te zakril v senco svoje roke, da lahko zasadim nebo in položim temelje zemlji in rečem Sionu: ›Ti si moje ljudstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Zbudi se, zbudi se, vstani, oh [prestolnica] Jeruzalem, ki si pila pri Gospodovi roki čašo njegove razjarjenosti. Pila si droži iz čaše trepetanja in jih posrebala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Nikogar ni, da jo usmerja med vsemi sinovi, ki jih je rodila niti ni nikogar izmed njenih sinov, ki jih je vzgojila, da jo prime za roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Ti dve stvari sta prišli nadte; komu bo žal zate? Opustošenje, poguba, lakota in meč. Po kom te bom potolažil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tvoji sinovi so oslabeli, ležijo na vrhu vseh ulic, kakor divji bik v mreži. Polni so Gospodove razjarjenosti, graje tvojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Zato poslušaj sedaj to, ti trpeča in pijana, toda ne z vinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Tako govori tvoj Gospod, Gospod in tvoj Bog, ki se poteguje za stvar svojega ljudstva: »Glej, iz tvoje roke sem vzel čašo trepetanja, celó droži iz čaše svoje razjarjenosti. Ne boš je več ponovno pila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'temveč jo bom položil v roko tistih, ki te stiskajo, ki so tvoji duši rekli: ›Skloni se, da lahko gremo preko‹ in svoje telo si položila kakor tla in kakor ulico tistim, ki so šli preko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Prebudi se, prebudi se, nadeni svojo moč, oh Sion, nadeni svoje krasne obleke, oh [prestolnica] Jeruzalem, sveto mesto, kajti odslej vate ne bo več vstopil neobrezani in nečisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otresi si prah, vstani in usedi se, oh [prestolnica] Jeruzalem, odveži si vezi iz svojega vratu, oh ujeta hči sionska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Kajti tako govori Gospod: ›Prodali ste se za nič in odkupljeni boste brez denarja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Kajti tako govori Gospod Bog: ›Moje ljudstvo je poprej šlo dol v Egipt, da začasno prebiva tam in Asirec jih je zatiral brez vzroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Sedaj torej, kaj imam tukaj,‹ govori Gospod, ›da je moje ljudstvo vzeto proč za nič? Tisti, ki vladajo nad njimi, jim povzročajo, da tulijo,‹ govori Gospod ›in moje ime je nenehno vsak dan preklinjano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Zato bo moje ljudstvo spoznalo moje ime, zato bodo na tisti dan vedeli, da jaz sem tisti, ki govori. Glejte, jaz sem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kako lepa so na gorah stopala tistega, ki prinaša dobre novice, ki objavlja mir, ki prinaša dobre novice o dobrem, ki objavlja rešitev duš, ki Sionu pravi: ›Tvoj Bog kraljuje!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Tvoji stražarji bodo povzdignili glas, z glasom bodo skupaj peli, kajti videli bodo iz oči v oči, ko bo Gospod ponovno privedel Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Izbruhnite v radost, skupaj prepevajte, vi opustošeni kraji [prestolnice] Jeruzalem, kajti Gospod je potolažil svoje ljudstvo, odkupil je [prestolnico] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Gospod je svoj sveti laket razgalil v očeh vseh narodov in vsi konci zemlje bodo videli rešitev duš našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Odidite, odidite, pojdite ven od tod, ne dotikajte se nobene nečiste stvari, pojdite ven iz njene srede, bodite čisti vi, ki nosite Gospodove posode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Kajti ven ne boste šli z naglico niti s pobegom, kajti Gospod bo šel pred vami in Izraelov Bog bo vaša zadnja straža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Glejte, moj služabnik bo ravnal razsodno, povzdignjen bo, povišan in bo zelo visok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Kakor so bili mnogi osupli nad teboj. Njegov videz je bil tako iznakažen, bolj kakor [od] kateregakoli človeka in njegova oblika bolj kakor od človeških sinov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'tako bo poškropil mnoge narode; kralji bodo zaprli svoja usta pred njim. Kajti to, kar jim ni bilo povedano, bodo videli, in česar niso slišali, bodo preudarjali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kdo je veroval našemu poročilu? In komu se je razodel Gospodov laket?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Kajti pred njim bo pognal kakor nežna rastlina in kakor korenina iz suhih tal. Nima oblike niti ljubkosti in ko ga bomo videli, ni lepote, da bi ga želeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Preziran je in zavrnjen od ljudi, mož bridkosti in seznanjen z žalostjo in mi smo, kakor bi skrili svoje obraze pred njim; bil je preziran, mi pa ga nismo cenili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Zagotovo je nosil naše žalosti in prenašal naše bridkosti, vendar smo ga imeli [za] zadetega, udarjenega od Boga in trpečega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Toda ranjen je bil zaradi naših prestopkov, poškodovan je bil zaradi naših krivičnosti. Kazen za naš mir je bila na njem in z njegovimi udarci z bičem smo ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Vsi smo zašli kakor ovce, obrnili smo se vsak k svoji lastni poti in Gospod je nanj položil krivičnost nas vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Bil je zatiran in trpel, vendar ni odprl svojih ust. Priveden je kakor jagnje h klanju in kakor je ovca pred svojimi strižci nema, tako on ne odpre svojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Vzet je bil iz ječe in iz sodbe in kdo bo razglasil njegov rod? Kajti odrezan je bil iz dežele živih, zaradi prestopka mojega ljudstva je bil udarjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Njegov grob v njegovi smrti mu je določil z zlobnimi in z bogatimi, čeprav ni storil nobenega nasilja niti ni bilo nobene prevare v njegovih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, '§ Vendar je Gospodu ugajalo, da ga rani; položil ga je v žalost. Ko boš naredil njegovo dušo v daritev za greh, bo videl svoje seme, podaljšal bo svoje dni in Gospodovo zadovoljstvo bo uspevalo v njegovi roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, '§ Videl bo muko svoje duše in bo zadovoljen. S svojim spoznanjem bo moj pravični služabnik opravičil mnoge, kajti nosil bo njihove krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Zato mu bom razdelil delež z velikimi in plen bo razdelil z močnimi, zato ker je svojo dušo izlil do smrti in prištet je bil med prestopnike; nosil je greh mnogih in opravil posredovanje za prestopnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, '»Zapoj, oh jalova, ti, ki nisi nosila, izbruhni v petje in glasno zavpij, ti, ki se nisi mučila z otrokom, kajti več je otrok zapuščene kakor otrok poročene žene,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Povečaj kraj svojega šotora in naj razprostrejo zagrinjala tvojih prebivališč. Ne šparaj, podaljšaj svoje vrvi in ojačaj svoje kline,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'kajti izbruhnila boš na desno roko in na levo in tvoje seme bo podedovalo pogane in naredila boš, da bodo opustela mesta naseljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne boj se, kajti ne boš osramočena niti ne bodi zbegana, kajti ne prideš v sramoto, kajti pozabila boš sramoto svoje mladosti in ne boš se več spominjala graje svojega vdovstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Kajti tvoj Stvarnik je tvoj soprog, Gospod nad bojevniki je njegovo ime in tvoj Odkupitelj Sveti Izraelov; imenovali ga bodo Bog celotne zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Kajti Gospod te je poklical kakor žensko, zapuščeno in užaloščeno v duhu in ženo mladosti, ko si bila zavržena,« govori tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '»Kajti za kratek trenutek sem te zapustil, toda z velikimi usmiljenji te bom zbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Z malce besa sem za trenutek skril svoj obraz pred teboj, toda z večno prijaznostjo bom imel usmiljenje nad teboj,« govori Gospod, tvoj Odkupitelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '»Kajti to mi je kakor so bile Noetove vode, kajti kakor sem prisegel, da Noetove vode ne bodo več šle preko zemlje, tako sem prisegel, da ne bom ogorčen nad teboj niti te ne bom več oštel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Kajti gore se bodo umaknile in hribi bodo odstranjeni, toda moja prijaznost ne bo odšla od tebe niti zaveza mojega miru ne bo odstranjena,« govori Gospod, ki ima usmiljenje do tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '»Oh ti trpeča, premetavana z viharjem in nepotolažena, glej, tvoje kamne bom položil z lepimi barvami in tvoje temelje bom položil s safirji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Tvoja okna bom naredil iz ahata in tvoja velika vrata iz granata in vse tvoje meje iz prijetnih kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Vsi tvoji otroci bodo poučevani od Gospoda in velik bo mir tvojih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'V pravičnosti boš utrjena, daleč boš od zatiranja, kajti ne boš se bala in [daleč boš] od strahote, kajti ta se ti ne bo približala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, '§ Glej, zagotovo se bodo zbrali skupaj, toda to ni od mene. Kdorkoli se bo skupaj zbral proti tebi, bo padel zaradi tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Glej, jaz sem ustvaril kovača, ki v ognju razpihuje ogorke in ki prinaša orodje za svoje delo in jaz sem ustvaril kvarilca, da uničuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nobeno orožje, ki je oblikovano zoper tebe, ne bo uspelo in vsak jezik, ki se bo na sodbi dvignil zoper tebe, boš obsodila. To je dediščina Gospodovih služabnikov in njihova pravičnost je od mene,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Hej, vsi, ki ste žejni, pridite k vodam in tisti, ki nimate denarja; pridite, kupite in jejte; da, pridite, kupite vino in mleko, brez denarja in brez cene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Zakaj trošite denar za to, kar ni kruh? In svoj trud za to, kar ne nasičuje? Marljivo mi prisluhnite in jejte to, kar je dobro in naj se vaša duša razveseljuje v obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nagnite svoje uho in pridite k meni. Prisluhnite in vaša duša bo živela in z vami bom sklenil večno zavezo, celó zanesljive Davidove milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Glej, izročil sem ga za pričo ljudstvu, voditelja in poveljnika ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Glej, poklical boš narod, ki ga nisi poznal in narodi, ki te niso poznali, bodo tekli k tebi zaradi Gospoda, tvojega Boga in zaradi Svetega Izraelovega, ker te je proslavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Iščite Gospoda, dokler se daje najti, kličite k njemu, dokler je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Naj zlobni zapusti svojo pot in nepravičen človek svoje misli in naj se vrne h Gospodu in se ga bo usmilil; in k našemu Bogu, kajti obilno bo odpustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Kajti moje misli niso vaše misli niti vaše poti niso moje poti,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '»Kajti kakor je nebo višje od zemlje, tako so moje poti višje od vaših poti in moje misli višje od vaših misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Kajti kakor dež prihaja dol in sneg z neba in se ne vrača tja, temveč zaliva zemljo in jo pripravlja, da poganja in brsti, da lahko da seme sejalcu in kruh jedcu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'tako bo moja beseda, ki gre ven iz mojih ust. Le-ta se k meni ne bo vrnila prazna, temveč bo le-ta dovršila to, kar mi ugaja in uspela v stvari, h kateri sem jo poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Kajti ven boste odšli z radostjo in vodeni boste z mirom. Gore in hribi bodo izbruhnili pred vami s petjem in vsa poljska drevesa bodo ploskala s svojimi rokami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Namesto trnja bo zrasla cipresa in namesto osata bo pognalo mirtino drevo in to bo Gospodu v ime in za večno znamenje, ki ne bo iztrebljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tako govori Gospod: »Varujte sodbo in ravnajte pravično, kajti moja rešitev duš je blizu, da pride in moja pravičnost, da se razodene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Blagoslovljen je človek, ki to počne in človeški sin, ki se tega oprime, ki varuje šabat pred omadeževanjem in zadržuje svojo roko pred početjem kakršnega koli zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Niti ne pusti sinu tujca, ki se je pridružil Gospodu, govoriti, rekoč: › Gospod me je popolnoma ločil od svojega ljudstva.‹ Niti naj evnuh ne reče: ›Glej, jaz sem suho drevo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Kajti tako govori Gospod evnuhom, ki se držijo mojih šabat in izbirajo stvari, ki mi ugajajo in se držijo moje zaveze;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'celo njim bom dal, v svoji hiši in znotraj svojih zidov, prostor in ime, boljše kakor od sinov in hčera. Dal jim bom večno ime, ki ne bo iztrebljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Tudi sinove tujca, ki se pridružijo Gospodu, da bi mu služili in da bi ljubili Gospodovo ime, da bi bili njegovi služabniki, vsak, kdor ohranja šabat pred tem, da bi ga omadeževal in se drži moje zaveze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'celó pripeljal jih bom na svojo sveto goro in jih razveselil v svoji hiši molitve. Njihove žgalne daritve in njihove klavne daritve bodo sprejete na mojem oltarju, kajti moja hiša se bo imenovala hiša molitve za vsa ljudstva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Gospod Bog, ki zbira Izraelove pregnance, govori: »Še bom zbral k njemu druge, poleg tistih, ki so zbrani k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Vse ve poljske živali, pridite, da požrete, da, vse ve živali v gozdu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Njegovi stražarji so slepi. Vsi so nevedni, vsi so nemi psi, ne morejo lajati; spijo, legajo, radi dremajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Da, pohlepni psi so, ki nikoli ne morejo imeti dovolj in pastirji, ki ne morejo razumeti. Vsi gledajo na svojo lastno pot, vsak za svojim dobičkom, od svoje meje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Pridite, pravijo: ›Šel bom po vino in nalili se bomo z močno pijačo in jutrišnji dan bo kakor ta dan in mnogo obilnejši.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Pravični propada in nihče si tega ne jemlje k srcu. Usmiljeni ljudje so odvzeti, nihče ne preudarja, da je pravični odvzet pred zlom, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Vstopil bo v mir. Počivali bodo v svojih posteljah, vsakdo, ki hodi v svoji poštenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Toda približajte se sèm, vi sinovi čarodejk, seme zakonolomca in vlačuge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Zoper koga se zabavate? Zoper koga širite usta in iztezate jezik? Mar niste otroci prestopka, seme neresnice,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'ki se vnemate z maliki pod vsakim zelenim drevesom, ki koljete otroke v dolinah pod skalnimi pečinami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Med gladkimi kamni vodotoka je tvoj delež; ti, ti so tvoj žreb. Celo njim si izlivala pitno daritev, darovala si jedilno daritev. Mar naj prejmem tolažbo v teh?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na vzvišeni in visoki gori si si postavila svojo posteljo, celo tja gor odhajaš, da daruješ klavno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Tudi za vrati in podboji si postavila svoj spomin, kajti odkrila si se drugemu kot meni in odšla gor. Razširila si svojo posteljo in sklenila zavezo z njimi; ljubila si njihovo posteljo, kjer si jo videla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, '§ Odhajaš h kralju z mazilom, množila si svoje dišave, svoje poslance si poslala daleč in sebe si ponižala celo do pekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Izmučena si v veličini svojih poti, vendar ne praviš: ›Tam ni upanja.‹ Našla si življenje svoje roke, zato nisi bila užaloščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Pred kom si bila prestrašena ali si se bala, da si lagala in se nisi spomnila mene niti si tega nisi vzela k srcu? Mar nisem molčal celo od davnine in se me ne bojiš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Razglašal bom tvojo pravičnost in tvoja dela, kajti ne bodo ti koristila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Ko vpiješ, naj te tvoje trume rešijo; toda veter jih bo vse odnesel proč, ničevost jih bo vzela. Toda tisti, ki svoje trdno upanje polaga vame, bo vzel v last deželo in podedoval mojo sveto goro');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'in rekel bo: ›Nasujte, nasujte, pripravite pot, vzemite kamen spotike iz poti mojega ljudstva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Kajti tako govori Visoki in Vzvišeni, ki naseljuje večnost, čigar ime je Sveti: ›Prebivam na visokem in svetem kraju, pa tudi s tistim, ki je skesanega in ponižnega duha, da oživim duha ponižnega in da oživim srce skesanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Kajti ne bom se prepiral na veke niti ne bom vedno besen, kajti duh bi opešal pred menoj in duše, ki sem jih naredil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Zaradi krivičnosti njegove pohlepnosti sem bil besen in ga udaril. Skril sem se in bil besen, on pa je kljubovalno odšel po poti svojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Videl sem njegove poti in ozdravil ga bom. Prav tako ga bom vodil in obnovil tolažbe njemu in njegovim žalovalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Jaz ustvarjam sad ustnic: ›Mir, mir tistemu, ki je daleč proč in tistemu, ki je blizu,‹ govori Gospod ›in jaz ga bom ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Toda zlobni so kot razburkano morje, kadar ne more počivati, katerega vode bljuvajo blato in umazanijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Tam ni miru,‹ govori moj Bog, ›zlobnemu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Vpij naglas, ne brzdaj se, svoj glas povzdigni kakor šofar in mojemu ljudstvu pokaži njihov prestopek in Jakobovi hiši njihove grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Vendar me dnevno iščejo in se veselijo spoznati moje poti kakor narod, ki je ravnal pravično in ni zapustil odredbe svojega Boga. Sprašujejo me odredbe o pravici, razveseljujejo se v približevanju Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '›Zakaj smo se postili,‹ pravijo ›ti pa ne vidiš? Zakaj smo mučili svojo dušo, ti pa se za to ne meniš?‹ Glejte, na dan svojega posta si najdete užitek in priganjate vse svoje delavce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Glejte, postite se za prepir in razpravljanje in da udarjate s pestjo zlobnosti. Ne boste se postili, kakor delate ta dan, da bi svojemu glasu dali, da se sliši na višavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Mar je to takšen post, ki sem ga izbral? Dan za človeka, da muči svojo dušo? Ali je to, da skloni svojo glavo kakor ločje in pod seboj razširja vrečevino in pepel? Mar boš to imenoval post in sprejemljiv dan Gospodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Mar ni to post, ki sem ga izbral? Da razvežeš vezi zlobnosti, da odstraniš težka bremena in da izpustiš zatirane prosto oditi in da zlomiš vsak jarem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Mar ni to, da deliš svoj kruh lačnemu in da privedeš revne, ki so izobčeni, k svoji hiši? Ko vidiš nagega, da ga pokriješ in da se ne skrivaš pred svojim lastnim mesom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, '§ Potem bo tvoja svetloba izbruhnila kakor jutro in tvoje zdravje bo naglo vzbrstelo in tvoja pravičnost bo šla pred teboj, Gospodova slava bo tvoja zadnja straža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Potem boš klical in Gospod bo odgovoril; vpil boš in rekel bo: ›Tukaj sem.‹ Če odstraniš jarem iz svoje srede, kazanje s prstom in govorjenje ničnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, '§ in če svojo dušo iztezaš k lačnemu in zadovoljiš trpečo dušo, potem bo v nejasnosti vstala tvoja svetloba in tvoja tema bo kakor poldan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Gospod te bo nenehno usmerjal in tvojo dušo zadovoljil v suši in tvoje kosti odebelil. In ti boš kakor namakan vrt in podoben boš vodnemu izviru, katerega vode ne usahnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Tisti, ki bodo od tebe, bodo gradili stare opustošene kraje. Vzdignil boš temelje mnogih rodov in imenovan boš: ›Popravljavec vrzeli, obnovitelj steza za prebivanje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Če odvrneš svoje stopalo pred šabat, pred tem, da počneš svoje zadovoljstvo na moj sveti dan in imenuješ šabat veselje, [dan] svet Gospodu, častitljiv in ga boš častil in ne izvajal svojih lastnih poti niti iskal svojega lastnega zadovoljstva niti govoril svojih lastnih besed,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'potem se boš veselil v Gospodu in povzročil ti bom, da jezdiš na visokih krajih zemlje in te hranil z dediščino svojega očeta Jakoba, kajti Gospodova usta so to govorila.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Glej, Gospodova roka ni skrajšana, da ne more rešiti niti njegovo uho zamašeno, da ne more slišati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'temveč so vaše krivičnosti ločile med vami in vašim Bogom in vaši grehi so skrili njegov obraz pred vami, da ne bi slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Kajti vaše roke so omadeževane s krvjo in vaši prsti s krivičnostjo, vaše ustnice so govorile laži, vaš jezik je mrmral perverznost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nihče ne kliče za pravico niti se kdorkoli ne poteguje za resnico. Zaupajo v ničnost in govorijo laži, spočnejo vragolijo in obrodijo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Valijo jajca strupene kače in tkejo pajkovo mrežo. Kdor od njihovih jajc jé, umira in to, kar je zdrobljeno, se izvali v gada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Njihove mreže ne bodo postale obleke niti se ne bodo pokrili s svojimi deli. Njihova dela so dela krivičnosti in dejanje nasilja je v njihovih rokah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Njihova stopala tečejo k zlu in hitijo, da prelijejo nedolžno kri. Njihove misli so misli krivičnosti; pustošenje in uničenje sta na njihovih stezah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Poti miru ne poznajo in na njihovih poteh ni sodbe. Naredili so si sprijene steze. Kdorkoli tam hodi, ne bo poznal miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Zato je sodba daleč od nas niti nas pravica ne doseže. Čakamo na svetlobo, toda glej, nejasnost; na sijaj, toda hodimo v temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Tipamo za zidom kakor slepi in tipamo, kakor ne bi imeli oči. Spotikamo se opoldan kakor ponoči, na zapuščenih krajih smo kakor mrtvi možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Vsi rjovemo kakor medvedje in boleče žalujemo kakor golobice. Pričakujemo sodbo, toda ni je; rešitev duš, toda ta je daleč od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Kajti naši prestopki so pomnoženi pred teboj in naši grehi pričujejo zoper nas. Naši prestopki so z nami in glede naših krivičnosti, mi jih poznamo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'prestopanje in laganje zoper Gospoda in odhajanje proč od našega Boga, govorjenje zatiranja in punta, spočenjanje in izgovarjanje besed neresnice iz srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Sodba je odvrnjena nazaj in pravica stoji daleč proč, kajti resnica je padla na ulici in nepristranskost ne more vstopiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Da, resnica peša in tisti, ki odhaja od zla, se izpostavlja za plen in Gospod je to videl in to ga je razžalilo, da ni bilo sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Videl je, da ni bilo nobenega človeka in se čudil, da ni bilo nobenega posredovalca, zato mu je njegov laket prinesel rešitev duše in njegova pravičnost ga je podpirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Kajti nadel si je pravičnost kakor prsni oklep in na svojo glavo čelado rešitve duš in za oblačila si je nadel obleke maščevanja in z gorečnostjo je bil odet kakor z ogrinjalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Glede na njihova dejanja bo primerno poplačal: razjarjenost svojim nasprotnikom, povračilo svojim sovražnikom, otokom bo poplačal povračilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, '§ Tako se bodo bali Gospodovega imena od zahoda in njegove slave od sončnega vzhoda. Ko bo sovražnik vstopil kot povodenj, bo Gospodov duh dvignil prapor zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Odkupitelj bo prišel na Sion in k tistim, ki se obračajo od prestopka v Jakobu,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '›Kar se tiče mene, to je moja zaveza z njimi,‹ govori Gospod: ›Moj duh, ki je na tebi in moje besede, ki sem ti jih položil v tvoja usta, ne bodo odšle iz tvojih ust niti iz ust tvojega semena niti iz ust semena tvojega semena,‹ govori Gospod, ›od tega časa naprej in na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Vstani, zasij, kajti tvoja svetloba je prišla in Gospodova slava je vstala nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Kajti glej, tema bo prekrila zemljo in velika tema ljudstva, toda Gospod bo vstal nad teboj in njegova slava bo vidna na tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Pogani bodo prišli k tvoji svetlobi in kralji k siju tvojega vzhajanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Dvigni svoje oči naokoli in poglej. Vsi se zbirajo skupaj, prihajajo k tebi. Tvoji sinovi bodo prišli od daleč in tvoje hčere bodo negovane ob tvoji strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Takrat boš videla in tekla skupaj in tvoje srce se bo balo in bo povečano, ker bo obilje morja obrnjeno k tebi, sile poganov bodo prišle k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Pokrila te bo množica kamel, [enogrbi] velblodi iz Midjána in Efe, vsi tisti iz Sabe bodo prišli. Prinesli bodo zlato in kadilo in naznanjali bodo Gospodove hvalnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Vsi kedárski tropi bodo zbrani skupaj k tebi, Nebajótovi ovni ti bodo služili. Na moj oltar bodo prišli s sprejetjem in jaz bom proslavil hišo svoje slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kdo so ti, ki letijo kakor oblak in kakor golobice k svojim oknom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Otoki bodo zagotovo čakali name in spredaj ladje iz Taršíša, da privedejo tvoje sinove od daleč, njihovo srebro in njihovo zlato z njimi, k imenu Gospoda, tvojega Boga in k Svetemu Izraelovemu, ker te je proslavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Sinovi tujcev bodo zgradili tvoja obzidja in njihovi kralji ti bodo služili, kajti v svojem besu sem te udaril, toda v svoji naklonjenosti sem imel usmiljenje nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Zato bodo tvoja velika vrata nenehno odprta; ne podnevi ne ponoči ne bodo zaprta, da ti bodo ljudje lahko prinašali sile poganov in da bodo lahko privedeni njihovi kralji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Kajti narod in kraljestvo, ki ti ne bo služilo, bo propadlo; da, ti narodi bodo popolnoma opustošeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Slava Libanona bo prišla k tebi, cipresa, bor in pušpan skupaj, da olepšajo kraj mojega svetišča in kraj svojih stopal bom naredil veličasten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Tudi sinovi tistih, ki so te prizadeli, bodo prišli, upogibajoč se k tebi in vsi, ki so te prezirali, se bodo priklonili pri podplatih tvojih stopal in imenovali te bodo: › Gospodovo mesto, Sion Svetega Izraelovega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Kakor si bila zapuščena in osovražena, tako da noben človek ni šel skozi tebe, te bom naredil za večno odličnost, radost mnogih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Prav tako boš sesala mleko poganov in sesala prsi kraljev in vedela boš, da sem jaz, Gospod, tvoj Odrešenik in tvoj Odkupitelj, Mogočni Jakobov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Za bron bom prinesel zlato in za železo bom prinesel srebro in za les bron in za kamne železo. Prav tako bom postavil [za] tvoje častnike mir in tvoje priganjače pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nasilja ne bo več slišati v tvoji deželi niti pustošenja niti uničenja znotraj tvojih meja, temveč boš svoja obzidja imenovala Odrešenje in svoja velika vrata Hvala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Sonce ne bo več tvoja svetloba podnevi niti ti za sijaj luna ne bo dajala svetlobe, temveč ti bo Gospod večna svetloba in tvoj Bog tvoja slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Tvoje sonce ne bo več zašlo niti se tvoja luna ne bo umaknila, kajti Gospod bo tvoja večna svetloba in dnevi tvojega žalovanja bodo končani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Prav tako tvoje ljudstvo – vsi bodo pravični. Podedovali bodo deželo na veke, mladiko mojega sajenja, delo mojih rok, da bom lahko proslavljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Najmanjši bo postal tisoč in malček mogočen narod. Jaz, Gospod, bom to pospešil ob svojem času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duh Gospoda Boga je nad menoj, ker me je Gospod mazilil, da oznanjam dobre novice krotkim, poslal me je, da povežem potrte v srcu, da razglasim svobodo ujetnikom in odprtje ječe tem, ki so zvezani,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'da razglasim sprejemljivo leto Gospodovo in dan maščevanja našega Boga, da potolažim vse tiste, ki žalujejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, '§ da določim tem, ki žalujejo na Sionu, da jim dam lepoto namesto pepela, olje veselja namesto žalovanja, obleko hvale namesto duha potrtosti, da se bodo lahko imenovali drevesa pravičnosti, Gospodov nasad, da bo on lahko proslavljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Zgradili bodo stare opustošenosti, dvignili bodo prejšnja opustošenja in popravili bodo opustošena mesta, zapuščenosti mnogih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Tujci bodo stali in pasli vaše trope in sinovi neznanca bodo vaši orači in vaši obrezovalci trte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Toda vi boste imenovani Gospodovi duhovniki. Ljudje vas bodo klicali Služabniki našega Boga. Jedli boste bogastva poganov in v njihovi slavi se boste bahali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Zaradi vaše sramote boste imeli dvojno in zaradi nečasti se bodo veselili v svojem deležu, zato bodo v svoji deželi posedovali dvojno, njim bo v večno radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Kajti jaz, Gospod, ljubim sodbo, sovražim naropano za žgalno daritev in njihovo delo bom vodil v resnici in z njimi bom sklenil večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Njihovo seme bo znano med pogani in njihovo potomstvo med ljudstvom. Vsi, ki jih vidijo, jim bodo priznali, da so seme, ki ga je Gospod blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Silno se bom razveseljeval v Gospodu, moja duša bo radostna v mojem Bogu, kajti oblekel me je z oblačili rešitve duše, pokril me je s svečanim oblačilom pravičnosti, kakor ženin sebe odene z okrasjem in kakor nevesta sebe okrasi s svojimi dragocenostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Kajti kakor zemlja prinaša svoj brst in kakor vrt povzroča stvarem, ki so posejane vanj, da poženejo, tako bo Gospod Bog povzročil pravičnosti in hvali, da poženeta pred vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Zaradi Siona ne bom molčal in zaradi Jeruzalema ne bom počival, dokler njegova pravičnost ne gre naprej kakor sijaj in njegova rešitev duš kakor svetilka, ki gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Pogani bodo videli tvojo pravičnost in vsi kralji tvojo slavo in imenovana boš z novim imenom, ki ga bodo poimenovala Gospodova usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Krona slave boš v Gospodovi roki in kraljevski diadem v roki svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Ne boš več imenovana Zapuščena niti ne bo tvoja dežela imenovana Opustošena, temveč se boš imenovala Hefziba in tvoja dežela Beula. Kajti Gospod se razveseljuje v tebi in tvoja dežela bo omožena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Kajti kakor mladenič poroči devico, tako se bodo tvoji sinovi poročili s teboj in kakor se ženin razveseljuje nad nevesto, tako se bo tvoj Bog veselil nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Postavil sem stražarje na tvoja obzidja, oh Jeruzalem, ki niti podnevi niti ponoči ne bodo nikoli mirovali. Vi, ki omenjate Gospoda, ne molčite');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'in njemu ne dajajte nobenega počitka, dokler ne osnuje in dokler ne naredi [prestolnice] Jeruzalem [za] hvalo na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Gospod je prisegel pri svoji desnici in pri laktu svoje moči: »Zagotovo ne bom več dajal tvojega žita, da bi bil hrana tvojim sovražnikom in sinovi tujca ne bo pili tvojega vina, za katerega si se trudila,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'temveč tisti, ki so ga nabrali, ga bodo jedli in hvalili Gospoda in tisti, ki so ga zbrali skupaj, ga bodo pili na dvorih moje svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Pojdite skozi, pojdite skozi velika vrata, pripravite pot ljudstvu, nasujte, nasujte glavno cesto, poberite kamne, dvignite prapor za ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Glejte, Gospod je razglasil do konca sveta: »Sionski hčeri recite: ›Glej tvoja rešitev duš prihaja, glej, njegova nagrada je z njim in njegovo delo pred njim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Klicali jih bodo Sveto ljudstvo, Odkupljeni od Gospoda in ti boš imenovana ›Poiskana,‹ ›Mesto, ki ni zapuščeno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, '»Kdo je ta, ki prihaja iz Edóma, s pobarvanimi oblekami iz Bocre? Ta, ki je veličasten v svojem oblačilu, potujoč v veličini svoje moči?« »Jaz, ki govorim v pravičnosti, močan, da rešim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, '»Zakaj si rdeč v svojem oblačilu in so tvoje obleke podobne tistemu, ki tlači v vinski kadi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Sam sem tlačil vinsko stiskalnico in izmed ljudstva ni bilo nikogar z menoj, kajti jaz jih bom pomendral v svoji jezi in jih poteptal v svoji razjarjenosti in njihova kri bo poškropljena na moje obleke in omadeževal si bom vse svoje oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Kajti dan maščevanja je v mojem srcu in leto mojih odkupljenih je prišlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Pogledal sem in nikogar ni bilo, da pomaga in čudil sem se, da ni bilo nikogar, da podpre. Zato mi je moj lastni laket prinesel rešitev duše in moja razjarjenost me je podpirala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'V svoji jezi bom pomendral ljudstvo in jih opijanil v svoji razjarjenosti in njihovo moč bom privedel dol do zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Omenil bom Gospodove ljubeče skrbnosti in Gospodove hvalnice, glede na vse, kar je Gospod podelil na nas in veliko dobroto do Izraelove hiše, ki jo je podelil nanje, glede na njegova usmiljenja in glede na množino njegovih ljubečih skrbnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Kajti rekel je: »Zagotovo so moje ljudstvo, otroci, ki ne bodo lagali.« Tako je bil njihov Odrešenik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'V vsej njihovi stiski je bil stiskan in angel njegove prisotnosti jih je rešil. V svoji ljubezni in svojem usmiljenju jih je odkupil in nosil jih je in prenašal vse dni davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Toda uprli so se in jezili njegovega Svetega Duha, zato se je obrnil, da bi bil njihov sovražnik in se boril proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Potem se je spomnil dni davnine, Mojzesa in njegovega ljudstva, rekoč: »Kje je tisti, ki jih je s pastirjem svojega tropa privedel iz morja? Kje je tisti, ki je znotraj njega položil svojega Svetega Duha?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Ki jih je vodil z Mojzesovo desnico, svojim veličastnim laktom, razdeljujoč vode pred njimi, da si naredi večno ime?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Ki jih je vodil skozi globino kakor konja v divjini, da se ne bi spotaknili?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Kakor gre žival dol v dolino, mu je Gospodov Duh naklonil, da počiva. Tako si vodil svoje ljudstvo, da si narediš veličastno ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Poglej dol iz nebes in glej iz prebivališča svoje svetosti in svoje slave. Kje je tvoja gorečnost in tvoja moč, odzvanjanje tvoje notranjosti in tvoja usmiljenja do mene? Ali so zadržana?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Nedvomno si ti naš oče, čeprav je Abraham neveden o nas in nas Izrael ne prizna. Ti, oh Gospod, si naš oče, naš odkupitelj; tvoje ime je od vekomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Oh Gospod, zakaj si nam povzročil, da zaidemo s tvojih poti in si naše srce zakrknil pred tvojim strahom? Vrni se zaradi svojih služabnikov, rodov svoje dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Ljudstvo tvoje svetosti ga je imelo v lasti le kratek čas. Naši nasprotniki so pomendrali tvoje svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Mi smo tvoji. Nikoli nisi vladal nad njimi; niso bili imenovani s tvojim imenom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Oh, da bi pretrgal nebo, da bi prišel dol, da bi gore lahko tekle ob tvoji prisotnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'kakor ko topilni ogenj žge, ogenj povzroča vodam, da vrejo, da tvoje ime naredi znano tvojim nasprotnikom, da bodo narodi lahko trepetali ob tvoji prisotnosti!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Ko si delal strašne stvari, ki jih nismo pričakovali, si prišel dol, gore so tekle ob tvoji prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Kajti od začetka sveta ljudje niso slišali niti z ušesom zaznali niti ni oko videlo, oh Bog, razen tebe, kaj je on pripravil za tistega, ki čaka nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Ti srečaš tistega, ki se razveseljuje in dela pravično, tiste, ki se te spominjajo na tvojih poteh. Glej, besen si, kajti mi smo grešili. V tistih je vztrajanje in mi bomo rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Toda mi vsi smo kakor nečista stvar in vse naše pravičnosti so kakor umazane cunje in mi vsi venemo kakor list in naše krivičnosti so nas kakor veter odnesle proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Nikogar ni, ki kliče k tvojemu imenu, ki se razvnema, da bi se te oprijel. Kajti svoj obraz si skril pred nami in nas použil zaradi naših krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Toda sedaj, oh Gospod, si ti naš oče. Mi smo ilo in ti naš lončar in mi vsi smo delo tvojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Ne bodi zelo boleče ogorčen, oh Gospod niti se ne spominjaj krivičnosti na veke. Glej, preišči, rotimo te, mi vsi smo tvoje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Tvoja sveta mesta so divjina, Sion je divjina, Jeruzalem opustošenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Naša sveta in naša krasna hiša, kjer so te naši očetje hvalili, je požgana z ognjem in vse naše prijetne stvari so opustošene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Mar se boš zadrževal zaradi teh stvari, oh Gospod? Mar boš molčal in nas zelo boleče prizadel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Poiskan sem od tistih, ki niso spraševali po meni; najden sem od tistih, ki me niso iskali: »Rekel sem: ›Glejte me, glejte me,‹« narodu, ki ni bil klican po mojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Svoje roke sem ves dan razprostiral k upornemu ljudstvu, ki hodi po poti, ki ni bila dobra, po svojih lastnih mislih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'in ljudstvu, ki me nenehno draži do jeze v moj obraz, ki žrtvuje na vrtovih in zažiga kadilo na oltarjih iz opek,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'ki se zadržuje med grobovi in prenočuje v spomenikih, ki jé svinjsko meso in juha iz gnusnih stvari je v njihovih posodah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'ki pravijo: »Stoj zase, ne približaj se mi, kajti bolj svet sem kakor ti.« Ti so dim v mojem nosu, ogenj, ki ves dan gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Glej, to je zapisano pred menoj. Ne bom molčal, temveč bom poplačal, celo poplačal v njihovo naročje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'vaše krivičnosti in krivičnosti vaših očetov skupaj,‹ govori Gospod, ›ki so zažigali kadilo na gorah in zoper mene izrekali bogokletje na hribih, zato bom njihovo prejšnje delo odmeril v njihovo naročje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tako govori Gospod: ›Kakor je novo vino najti v grozdu in nekdo pravi: ›Ne uniči ga, kajti blagoslov je v njem,‹ tako bom jaz storil zaradi svojih služabnikov, da jih ne bi vse uničil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Privedel bom seme iz Jakoba in iz Juda dediča svojih gora in moj izvoljeni bo to podedoval in moji služabniki bodo tam prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Šarón bo staja tropov in dolina Ahór kraj za črede, da se uležejo, za moje ljudstvo, ki me je iskalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, '§ Toda vi ste tisti, ki zapuščate Gospoda, ki pozabljate mojo sveto goro, ki pripravljate mizo za to krdelo in ki pripravljate pitno daritev temu številu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Zato vas bom štel k meču in vsi se boste priklonili za zakol, ker ko sem klical niste odgovorili, ko sem govoril niste slišali, temveč ste počeli zlo pred mojimi očmi in izbirali to, v čemer se nisem razveseljeval.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Zato tako govori Gospod Bog: ›Glejte, moji služabniki bodo jedli, toda vi boste lačni. Glejte, moji služabniki bodo pili, toda vi boste žejni. Glejte, moji služabniki se bodo veselili, toda vi boste osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Glejte, moji služabniki bodo prepevali zaradi srčne radosti, toda vi boste vpili zaradi bridkosti srca in tulili zaradi draženja duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Svoje ime boste pustili za prekletstvo mojim izbranim, kajti Gospod Bog te bo ubil in svoje služabnike klical z drugim imenom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, '§ da se bo tisti, ki se blagoslavlja na zemlji, blagoslavljal v Bogu resnice in kdor prisega na zemlji, bo prisegal pri Bogu resnice, kajti prejšnje težave so pozabljene in ker so skrite pred mojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Kajti glej, ustvarim novo nebo in novo zemljo in prejšnjega se ne bo spominjalo niti ne bo prišlo v misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Toda bodite veseli in se na veke veselite tega, kar ustvarim. Kajti glejte, [prestolnico] Jeruzalem ustvarim za razveseljevanje in njeno ljudstvo za radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Razveseljeval se bom v [prestolnici] Jeruzalem in se veselil v svojem ljudstvu. Glasu jokanja ne bo več slišati v njej niti glasu vpitja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Tam ne bo več otročička po dnevih niti starca, ki ne bi izpolnil svojih dni, kajti otrok bo umrl star sto let, toda grešnik, ki bo star sto let, bo preklet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Gradili bodo hiše in jih poselili in posadili bodo vinograde ter jedli od njihovega sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ne bodo gradili in drug naselil, ne bodo sadili in drug jedel, kajti kakor so dnevi drevesa, so dnevi mojega ljudstva in moji izvoljeni bodo dolgo uživali delo svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ne bodo se trudili zaman niti rojevali za težavo, kajti oni so seme blagoslovljenih od Gospoda in njihovo potomstvo z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'In zgodilo se bo, da bom odgovarjal, preden bodo klicali in medtem ko še govorijo, bom usliševal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Volk in jagnje se bosta skupaj pasla, lev bo jedel slamo kakor bikec in prah bo hrana kači. Ne bodo škodovali niti uničevali na vsej moji sveti gori,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, '»Tako govori Gospod: ›Nebo je moj prestol in zemlja je moja pručka. Kje je hiša, ki mi jo gradite? In kje je kraj mojega počitka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Kajti vse te stvari je naredila moja roka in vse te stvari so bile,‹ govori Gospod, ›toda gledal bom k temu človeku, celó k njemu, ki je reven in skesanega duha in trepeta ob moji besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Kdor kolje vola, je kakor če usmrti človeka; kdor žrtvuje jagnje, kakor če odseka pasji vrat; kdor daruje daritev kakor, če bi daroval svinjsko kri; kdor sežiga kadilo, kakor če bi blagoslovil malika. Da, izbrali so si svoje lastne poti in njihova duša se razveseljuje v njihovih ogabnostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Tudi jaz bom izbral njihove zablode in nanje privedel njihove strahove, ker ko sem klical nihče ni odgovoril, ko sem govoril niso poslušali, temveč so pred mojimi očmi počeli zlo in izbirali tisto, v čemer se nisem veselil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Poslušajte Gospodovo besedo vi, ki trepetate ob njegovi besedi: ›Vaši bratje, ki so vas sovražili, ki so vas metali ven zaradi mojega imena, so rekli: ›Naj bo Gospod proslavljen.‹ Toda pojavil se bo v vašo radost, oni pa bodo osramočeni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Glas hrupa iz mesta, glas iz templja, glas Gospoda, ki vrača povračilo svojim sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Preden je bila v porodnih mukah, je rodila, preden je prišla njena bolečina, je rodila fantka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kdo je slišal takšno stvar? Kdo je videl takšne stvari? Mar bo zemlja primorana, da rodi v enem dnevu? Ali bo narod hkrati rojen? Kajti takoj, ko je bila [hči] sionska v porodnih mukah, je rodila svoje otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Mar bom privedel do rojstva in ne bom povzročil, da rodi?‹ govori Gospod: ›Mar bom povzročil, da rodi in zaprl maternico?‹ govori tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Veselite se s [prestolnico] Jeruzalem in bodite veseli z njo, vsi vi, ki jo ljubite. Veselite se zaradi radosti z njo, vsi vi, ki žalujete nad njo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'da boste lahko sesali in boste nasičeni s prsi njenih tolažb, da boste srkali in boste veseli z obiljem njene slave,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'kajti tako govori Gospod: ›Glejte, mir bom iztegnil k njej kakor reko in slavo poganov kakor tekoč vodotok. Potem boste sesali, nošeni boste na njenih straneh in ujčkani na njenih kolenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Kakor nekdo, ki ga njegova mati tolaži, tako bom jaz potolažil vas in v Jeruzalemu boste potolaženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Ko to zagledate, se bo vaše srce veselilo in vaše kosti bodo cvetele kakor zelišče in Gospodova roka bo poznana njegovim služabnikom in njegovo ogorčenje proti njegovim sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Kajti glej, Gospod bo prišel z ognjem in s svojimi bojnimi vozovi kakor z vrtinčastim vetrom, da povrne svojo jezo z razjarjenostjo in svoje oštevanje s plameni ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Kajti z ognjem in s svojim mečem se bo Gospod pravdal z vsem mesom in mnogo bo umorjenih od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Tisti, ki se posvetijo in se očistijo na vrtovih za enim drevesom na sredi, jedoč svinjsko meso, ogabnost in miš, bodo skupaj použiti,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Kajti poznam njihova dela in njihove misli. Zgodilo se bo, da bom zbral vse narode in jezike in prišli bodo in videli mojo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Med njimi bom postavil znamenje in poslal bom tiste, ki izmed njih pobegnejo k narodom, k Taršíšu, Pulu in Ludu, ki napenjajo lok, k Tubálu in Javánu, k oddaljenim otokom, ki niso slišali mojega slovesa niti niso videli moje slave in mojo slavo bodo razglašali med pogani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'K moji sveti gori Jeruzalem bodo privedli vse vaše brate v dar Gospodu iz vseh narodov na konjih, bojnih vozovih, nosilnicah, na mulah in na hitrih živalih,‹ govori Gospod, ›kakor Izraelovi otroci prinesejo daritev v čisti posodi v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Tudi od njih [jih] bom vzel za duhovnike in za Lévijevce,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, '›Kajti kakor bosta novo nebo in nova zemlja, ki ju bom naredil, ostala pred menoj,‹ govori Gospod, ›tako bo ostalo vaše seme in vaše ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'In zgodilo se bo, da bo od enega do drugega mlaja in od enega do drugega šabata, prišlo vse meso, da obožuje pred menoj,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, '›Šli bodo naprej in gledali na trupla ljudi, ki so se pregrešili zoper mene, kajti njihov črv ne bo umrl niti njihov ogenj ne bo pogašen in gnus bodo vsemu mesu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Beseda Jeremija, Hilkijájevega sina, izmed duhovnikov, ki so bili v Anatótu v Benjaminovi deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'kateremu je prišla Gospodova beseda v dneh Jošíja, Amónovega sina, Judovega kralja, v trinajstem letu njegovega kraljevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Ta je prišla tudi v dneh Jojakíma, Jošíjevega sina, Judovega kralja, do konca enajstega leta Sedekíja, Jošíjevega sina, Judovega kralja, do preselitve jeruzalemskega ujetništva v petem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Potem je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '»Preden sem te oblikoval v trebuhu, sem te poznal. Preden si prišel iz maternice, sem te posvetil in te odredil [za] preroka narodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Potem sem rekel: »Jaz, ah Gospod Bog! Glej, ne morem govoriti, kajti jaz sem otrok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Toda Gospod mi je rekel: »Ne govori: ›Jaz sem otrok,‹ kajti šel boš k vsem, h katerim te bom poslal in karkoli ti zapovem, boš govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne boj se njihovih obrazov, kajti jaz sem s teboj, da te rešujem,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Potem je Gospod iztegnil svojo roko in se dotaknil mojih ust. Gospod mi je rekel: »Glej, svoje besede sem položil v tvoja usta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Glej, ta dan sem te postavil nad narode in nad kraljestva, da izkoreniniš, da podiraš, da uničiš, da zrušiš, da zgradiš in da sadiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Poleg tega je prišla k meni Gospodova beseda, rekoč: »Jeremija, kaj vidiš?« Rekel sem: »Vidim palico mandljevca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Potem mi je Gospod rekel: »Dobro si videl, kajti pospešil bom svojo besedo, da jo izvršim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Gospodova beseda je drugič prišla k meni, rekoč: »Kaj vidiš?« Rekel sem: »Vidim lonec, v katerem vre in njegova stran je proti severu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Potem mi je Gospod rekel: »Iz severa bo izbruhnilo zlo nad vse prebivalce dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Kajti, glej, poklical bom vse družine kraljestev iz severa,« govori Gospod »in prišli bodo in postavili bodo vsak svoj prestol ob vhodu velikih vrat [prestolnice] Jeruzalem in zoper vse njene zidove naokoli in zoper vsa Judova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Izrekel bom svoje sodbe zoper njih glede vseh njihovih zlobnosti, ki se dotikajo vseh svojih zlobnosti, ki so me zapustili in zažigali kadilo drugim bogovom ter oboževali dela svojih lastnih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Opaši si torej svoja ledja in vstani ter jim spregovori vse, kar sem ti zapovedal. Ne bodi zaprepaden ob njihovih obrazih, da te ne bi zbegal pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Kajti glej, ta dan sem te naredil za obrambno mesto, železen steber in bronaste zidove zoper celotno deželo, zoper Judove kralje, zoper njegove prince in zoper njegove duhovnike in zoper ljudstvo dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Borili se bodo zoper tebe, toda ne bodo prevladali zoper tebe, kajti jaz sem s teboj,« govori Gospod, »da te osvobodim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Poleg tega mi je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '»Pojdi in jokaj v ušesa [prestolnice] Jeruzalem, rekoč: ›Tako govori Gospod: ›Spominjam se tebe, prijaznosti tvoje mladosti, ljubezni tvojih zaročencev, ko si šla za menoj v divjino, v deželo, ki ni bila posejana.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Izrael je bil svetost Gospodu in prvi sadovi njegovega donosa. Vse, ki ga požirajo, bo jezil; zlo bo prišlo nadnje,‹« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Poslušajte besedo od Gospoda, oh Jakobova hiša in vse družine Izraelove hiše:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, '»Tako govori Gospod: ›Kakšno krivičnost so vaši očetje našli v meni, da so odšli daleč od mene in hodili za ničevostjo in postali ničevost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Niti niso rekli: ›Kje je Gospod, ki nas je privedel gor iz egiptovske dežele, ki nas je vodil skozi divjino, skozi deželo puščav in jam, skozi deželo suše in smrtne sence, skozi deželo, skozi katero noben človek ne gre in kjer noben človek ne prebiva?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Privedel sem vas v obilno deželo, da jeste njen sad in njeno dobroto, toda ko ste vstopili, ste omadeževali mojo deželo in mojo dediščino naredili ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Duhovniki niso rekli: ›Kje je Gospod?‹ Tisti, ki so se ukvarjali s postavo, me niso poznali. Tudi pastirji so se pregrešili zoper mene in preroki so prerokovali pri Báalu in hodili za stvarmi, ki ne storijo koristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Zato se bom še pravdal z vami,‹ govori Gospod ›in z vašimi otrok otroki se bom pravdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Kajti šel bom čez otoke Kitéjcev in videl in poslal v Kedár in marljivo preudaril in videl, če je tam takšna stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Je narod spremenil svoje bogove, ki vendar niso bogovi? Toda moje ljudstvo je zamenjalo svojo slavo za to, kar ne koristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Bodite osupla, oh ve nebesa, ob tem in bodite strašno prestrašena, bodite zelo zapuščena,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '›Kajti moje ljudstvo je zagrešilo dve hudobiji; zapustili so mene, studenec živih vodá in si izklesali vodne zbiralnike, razpokane vodne zbiralnike, ki ne morejo držati vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ali je Izrael služabnik? Ali je doma rojeni suženj? Zakaj je oplenjen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Mladi levi so rjoveli nanj in vpili. Njegovo deželo so naredili opustošeno. Njegova mesta so požgana, brez prebivalcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Tudi otroci Nofa in Tahpanhésa so zlomili krono tvoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Ali si nisi tega priskrbela k sebi v tem, da si zapustila Gospoda, svojega Boga, ko te je vodil po poti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'In sedaj, kaj imaš opraviti na egiptovski poti, da piješ vode iz Sihorja? Ali kaj imaš opraviti na asirski poti, da piješ vode iz reke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Tvoja lastna zlobnost te bo grajala in tvoja zdrknjenja nazaj te bodo opominjala. Vedi torej in vidi, da je to huda stvar in grenka, da si zapustila Gospoda, svojega Boga in da mojega strahu ni v tebi,‹ govori Gospod, Bog nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, '§ ›Kajti od starih časov sem prelomil tvoj jarem in raztrgal tvoje vezi; ti pa praviš: ›Jaz ne bom grešila;‹ ko tavaš na vsakem visokem hribu in tavaš pod vsakim zelenim drevesom in igraš vlačugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Vendar sem te zasadil [kot] plemenito trto, popolnoma pravo seme. Kako si se mi potem obrnila v degenerirano sadiko tuje trte?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Kajti čeprav se umivaš s solitrom in si jemlješ precej mila, je vendar tvoja krivičnost zaznamovana pred menoj,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kako lahko rečeš: ›Nisem onesnažena, nisem odšla za Báali?‹ Poglej svojo pot v dolini, spoznaj, kaj si storila. Ti si hitri [enogrbi] velblod, ki prečka svoje poti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'divja oslica, vajena divjine, ki voha veter po svojem zadovoljstvu; kdo jo ob njeni priložnosti lahko odvrne proč? Vsi tisti, ki jo iščejo, se ne bodo izmučili; v njenem mesecu jo bodo našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Zadrži svoje stopalo pred bosostjo in svoje grlo pred žejo. Toda ti praviš: ›Tam ni upanja. Ne, kajti ljubila sem tujce in za njimi bom šla.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Kakor je tat osramočen, ko je najden, tako je osramočena Izraelova hiša; oni, njihovi kralji, njihovi princi, njihovi duhovniki in njihovi preroki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'rekoč lesu: ›Ti si moj oče;‹ in skali: ›Ti si me rodila.‹ Kajti obrnili so mi svoj hrbet in ne svojega obraza. Toda v času njihove stiske bodo rekli: ›Vstani in nas reši.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Toda kje so tvoji bogovi, ki si jih naredila? Naj vstanejo, če te lahko rešijo v času tvoje stiske, kajti glede na število tvojih mest so tvoji bogovi, oh Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Zakaj se hočete pravdati z menoj? Vsi vi ste se pregrešili zoper mene,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, '›V prazno sem udaril vaše otroke; nobenega grajanja niso prejeli. Vaš lastni meč je požrl vaše preroke kakor uničujoč lev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Oh rod, poglejte Gospodovo besedo. Ali sem bil Izraelu divjina? Dežela teme? Zakaj pravi moje ljudstvo: ›Mi smo gospodje, nič več ne bomo prišli k tebi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Mar lahko devica pozabi svoje ornamente ali nevesta svoj okras? Vendar me moje ljudstvo pozablja brez števila dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Zakaj krajšaš svojo pot, da iščeš ljubezen? Zato si tudi zlobne učila svojih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Tudi v krajcih tvojega oblačila je najdena kri duš ubogih nedolžnih. Nisem je našel s skrivnim iskanjem, temveč na vseh teh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Vendar praviš: ›Ker sem nedolžna, se bo njegova jeza zagotovo obrnila od mene.‹ Glej, jaz se bom pravdal s teboj, ker praviš: ›Nisem grešila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Zakaj toliko hodiš sem ter tja, da bi spremenila svojo pot? Tudi ti boš osramočena od Egipta, kakor si bila osramočena od Asirije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Da, šla boš naprej od njega, s svojimi rokami na svoji glavi, kajti Gospod je zavrnil tvoje zaupnosti in ne boš uspela v njih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Pravijo: »Če človek odpusti svojo ženo in gre ona od njega in postane od nekega drugega moškega, ali se bo on ponovno vrnil k njej? Ali ne bi bila ta dežela silno oskrunjena? Ti pa si igrala pocestnico z mnogimi ljubimci; vendar se ponovno vrni k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '»Povzdigni svoje oči k visokim krajem in poglej, kje vse nisi bila poležena z [njimi]. Na poteh si sedela zanje, kakor Arabec v divjini in deželo si oskrunila s svojimi vlačugarstvi in svojo zlobnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Zato so bili nalivi zadržani in ni bilo poznega dežja; in ti imaš vlačugino čelo; odklonila si, da bi bila osramočena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Mar ne boš od tega časa klicala k meni: ›Moj oče, ti si vodič od moje mladosti?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Ali bo svojo jezo hranil na veke? Ali jo bo držal do konca? Glej, govoril si in storil hude stvari, kot ti lahko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Gospod mi je tudi rekel v dneh kralja Jošíja: »Ali si videl to, kar je storila odpadnica Izrael? Odhajala je na vsako visoko goro in pod vsako zeleno drevo in tam igrala pocestnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Potem ko je storila vse te stvari, sem rekel: ›Obrni se k meni.‹ Toda ni se vrnila. In njena verolomna sestra Juda je to videla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Videl sem, ko sem jo zaradi vseh vzrokov, s čimer je odpadnica Izrael zagrešila zakonolomstvo, odslovil in ji dal ločitveni list, se njena verolomna sestra Juda kljub temu ni bala, temveč je tudi ona odšla in prav tako igrala pocestnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Pripetilo se je skozi lahkomiselnost njenega vlačugarstva, da je omadeževala deželo in zagrešila zakonolomstvo s skalami in z lesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Vendar se zaradi vsega tega njena verolomna sestra Juda ni obrnila k meni z vsem svojim srcem, temveč hlinjeno,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Gospod mi je rekel: »Odpadnica Izrael se je bolj opravičila kakor verolomna Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Pojdi in razglasi te besede proti severu in reci: ›Vrni se, ti odpadnica Izrael,‹ govori Gospod › in svoji jezi ne bom povzročil, da pade na vas, kajti jaz sem usmiljen,‹ govori Gospod, › in jeze ne bom držal na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Samo priznaj svojo krivičnost, da si se pregrešila zoper Gospoda, svojega Boga in si svoje poti razkropila k tujcem pod vsakim zelenim drevesom in nisi ubogala mojega glasu,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, '›Obrnite se, odpadli otroci,‹ govori Gospod. ›Kajti jaz sem poročen z vami. Vzel vas bom enega iz mesta in dva iz družine in vas privedel k Sionu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Dal vam bom pastirje po svojem srcu, ki vas bodo hranili z znanjem in razumevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Zgodilo se bo, ko boste pomnoženi in povečani v deželi, v tistih dneh,‹ govori Gospod, ›ne bodo več rekli: ›Skrinja Gospodove zaveze.‹ Niti to ne bo prišlo na misel, niti se tega ne bodo spomnili, niti je ne bodo obiskali, niti to ne bo več storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Ob tistem času bodo [prestolnico] Jeruzalem imenovali Gospodov prestol. Vsi narodi bodo zbrani k njej, k imenu Gospoda, k [prestolnici] Jeruzalem. Niti ne bodo več hodili po zamisli svojih zlih src.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'V tistih dneh bo Judova hiša hodila z Izraelovo hišo in skupaj bodo prišli iz severne dežele k deželi, ki sem jo dal v dediščino vašim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Toda rekel sem: ›Kako te bom postavil med otroke in ti dal prijetno deželo, čedno dediščino vojske narodov?‹ Rekel sem: ›Klicala me boš: ›Moj oče‹ in ne boš se odvrnila od mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Zagotovo, kakor žena zahrbtno odide od svojega soproga, tako ste zahrbtno ravnali z menoj, oh hiša Izraelova,‹ govori Gospod');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, '›Glas je bil slišan na visokih krajih, jokanje in ponižne prošnje Izraelovih otrok, kajti izkrivili so svojo pot in pozabili Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Vrnite se, vi odpadli otroci in ozdravil bom vaša odvračanja.‹« »Glej, mi prihajamo k tebi, kajti ti si Gospod, naš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Resnično, zaman je upati na rešitev duše s hribov in od množice gora. Zares, v Gospodu, našem Bogu, je Izraelova rešitev duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Kajti sramota je od naše mladosti požrla trud naših očetov; njihove trope in njihove črede, njihove sinove in njihove hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Uležemo se v svoji sramoti in naša zmešnjava nas pokriva, kajti grešili smo zoper Gospoda, svojega Boga, mi in naši očetje, od svoje mladosti, celo do današnjega dne in nismo ubogali glasu Gospoda, svojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '»Če se hočeš vrniti, oh Izrael,« govori Gospod, »se vrni k meni. Če hočeš odstraniti svoje ogabnosti izpred mojega pogleda, potem ne boš odtaval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Prisegel boš: › Gospod živi v resnici in sodbi in v pravičnosti‹« in narodi se bodo blagoslavljali v njem in v njem bodo slavili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Kajti tako govori Gospod Judovim možem in Jeruzalemu: »Pobranajte svoja neposejana tla in ne sejte med trnjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obrežite se Gospodu in odstranite prednje kožice svojega srca, vi, Judovi možje in prebivalci Jeruzalema, da ne bi moja razjarjenost prišla kakor ogenj in tako požgala, da nihče ne more pogasiti – zaradi hudobije vaših ravnanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Razglasite v Judu in objavite v [prestolnici] Jeruzalem in recite: ›Zatrobite na šofar v deželi.‹ Kličite, zberite se skupaj in recite: ›Zberite se skupaj in pojdimo v obrambna mesta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Postavite prapor proti Sionu. Umaknite se, ne ostanite, kajti jaz bom privedel hudo iz severa in veliko uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lev je prišel iz svoje goščave in uničevalec poganov je na svoji poti; odšel je iz svojega kraja, da tvojo deželo naredi zapuščeno in tvoja mesta bodo opustošena, brez prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Zaradi tega se opašite z vrečevino, žalujte in tulite, kajti kruta Gospodova jeza ni odvrnjena od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Zgodilo se bo na ta dan,« govori Gospod, » da bo srce kralja in srce princev oslabelo in duhovniki bodo osupli in preroki se bodo spraševali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Potem sem rekel: »Ah, Gospod Bog! Zagotovo si zelo prevaral to ljudstvo in Jeruzalem, rekoč: ›Imeli boste mir,‹ medtem ko meč sega do duše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Ob tistem času bo rečeno temu ljudstvu in [prestolnici] Jeruzalem: »Suh veter visokih krajev v divjini proti hčeri mojega ljudstva, ne da preveja niti da očisti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'celó poln veter iz tistih krajev bo prišel k meni. Sedaj bom tudi jaz izrekel obsodbo zoper njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Glej, prišel bo gor kakor oblaki in njegovi bojni vozovi bodo kakor vrtinčast veter. Njegovi konji so bolj nagli kakor orli. Gorje nam! Kajti oplenjeni smo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, '»Oh [prestolnica] Jeruzalem, umij svoje srce pred zlobnostjo, da boš lahko rešena. Doklej bodo tvoje prazne misli prenočevale znotraj tebe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Kajti glas razglaša od Dana in objavlja stisko od gore Efrájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Dajte omenjati narodom, glejte, objavite zoper [prestolnico] Jeruzalem, da stražarji prihajajo iz daljne dežele in objavite njihov glas zoper Judova mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Kakor čuvaji polja so oni zoper njo vsenaokrog, zato ker je bila uporna zoper mene,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, '»Tvoja pot in tvoja početja so ti povzročila te stvari; to je tvoja zlobnost, ker je ta grenka, ker ta sega v tvoje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, '§ Moja notranjost, moja notranjost! Zaskrbljen sem prav v svojem srcu; moje srce dela v meni hrup; ne morem ohraniti miru, ker si slišala, oh moja duša, zvok šofarja, alarm vojne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Uničenje na uničenje je razkričano, kajti celotna dežela je oplenjena. Moji šotori so nenadoma oplenjeni in moje zavese v trenutku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Doklej bom videl prapor in slišal zvok šofarja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Kajti moje ljudstvo je nespametno, niso me spoznali; neumni otroci so in nobenega razumevanja nimajo. Modri so, da počno hudo, toda za početje dobrega nimajo spoznanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Pogledal sem zemljo in glej, ta je bila brez oblike ter prazna; in [na] nebo, pa ni imelo nobene svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Pogledal sem gore in glej, trepetale so in vsi hribi so se rahlo gibali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Pogledal sem in glej, tam ni bilo nobenega človeka in vse nebeške ptice so odletele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Pogledal sem in glej, rodoviten kraj je bila divjina in vsa njegova mesta so bila zrušena ob Gospodovi prisotnosti in z njegovo kruto jezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Kajti tako je rekel Gospod: »Celotna dežela bo zapuščena, vendar ne bom naredil popolnega konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Zaradi tega bo zemlja žalovala in nebo nad [njo] bo črno. Ker sem to govoril, sem to namenil in se ne bom kesal niti se ne bom obrnil nazaj od tega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Celotno mesto bo pobegnilo zaradi zvoka konjenikov in lokostrelcev; šli bodo v goščave in plezali na skale. Vsako mesto bo zapuščeno in ni človeka, da tam prebiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Ko si oplenjena, kaj boš storila? Čeprav se oblačiš s temno rdečo, čeprav se krasiš z ornamenti iz zlata, čeprav si obrobljaš svoj obraz z ličenjem, se boš zaman naredila lepo; tvoji ljubimci te bodo prezirali, stregli ti bodo po življenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Kajti slišal sem glas ženske kakor v porodnih bolečinah in tesnobo kakor od tiste, ki rojeva svojega prvega otroka, glas sionske hčere, ki se objokuje, ki razširja svoji roki, rekoč: »Gorje mi sedaj! Kajti moja duša je izmučena zaradi morilcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, '»Tecite sem ter tja skozi ulice [prestolnice] Jeruzalem in glejte sedaj in vedite in iščite na njenih širokih krajih, če lahko najdete človeka, če je tam kdorkoli, ki izvršuje sodbo, ki išče resnico in jaz bom to oprostil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Čeprav govorijo: › Gospod živi,‹ zagotovo lažno prisegajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Oh Gospod, ali niso tvoje oči [stabilno] na resnici? Udaril si jih, toda niso žalovali; použil si jih, toda odklonili so, da sprejmejo grajanje. Svoje obraze so otrdili bolj kakor skala; odklonili so, da se vrnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Zato sem rekel: »Ti so zagotovo ubogi; nespametni so, kajti ne poznajo Gospodove poti niti sodbe njihovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Spravil se bom do velikih mož in jim govoril, kajti poznali so Gospodovo pot in sodbo svojega Boga.« Toda ti so povsem zlomili jarem in razpočili vezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Zatorej jih bo ubil lev iz gozda in večerni volk jih bo oplenil, leopard bo stražil nad njihovimi mesti. Vsak, kdor gre od tam, bo raztrgan na koščke, ker so njihovi prestopki številni in njihova odpadanja so se povečala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kako naj ti oprostim za to? Tvoji otroci so me zapustili in prisegali pri tistih, ki niso bogovi. Ko sem jih hranil do polnosti, so oni potem zagrešili zakonolomstvo in se s krdeli zbirali v hišah pocestnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Bili so kakor zjutraj nahranjeni konji. Vsakdo je hrzal za ženo svojega soseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Mar [jih] ne bom obiskal zaradi teh stvari?‹ govori Gospod: ›Mar se ne bo moja duša maščevala na takšnem narodu, kot je ta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, '§ Pojdite gor na njene zidove in uničujte, toda ne naredite popolnega konca. Odvzemite njene obzidke, kajti le-ti niso Gospodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Kajti Izraelova hiša in Judova hiša sta zelo zahrbtno postopali zoper mene,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Skrivali so Gospoda in rekli: › To ni on; niti hudo ne bo prišlo nad nas; niti ne bomo videli meča niti lakote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Preroki bodo postali veter in besede ni v njih. Tako jim bo storjeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Zato tako govori Gospod Bog nad bojevniki: »Ker ste govorili to besedo, glej, bom naredil svojo besedo v tvojih ustih ogenj in to ljudstvo les in ta jih bo použil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Glej! Nadte bom od daleč privedel narod, oh hiša Izraelova,« govori Gospod, »to je mogočen narod, to je starodaven narod, narod, čigar jezika ne poznaš niti ne razumeš kaj pravijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Njihov tul za puščice je kakor odprt mavzolej, vsi so mogočni možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Pojedli bodo tvojo žetev in tvoj kruh, ki naj bi ga jedli tvoji sinovi in tvoje hčere. Pojedli bodo tvoje trope in tvoje črede. Pojedli bodo tvoje trte in tvoja figova drevesa. Z mečem bodo izčrpali tvoja utrjena mesta, v katera zaupate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Kljub temu v tistih dneh,« govori Gospod, »z vami ne bom naredil popolnega konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Zgodilo se bo, ko boste rekli: ›Zakaj nam Gospod, naš Bog, počne vse te stvari?‹ Potem jim boš odgovoril: ›Podobno kakor ste vi zapustili mene in služili tujim bogovom v svoji deželi, tako boste služili tujcem v deželi, ki ni vaša.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Razglasite to v Jakobovi hiši in objavite to v Judu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '›Poslušajte sedaj to, oh nespametno ljudstvo in brez razumevanja; ki imate oči, pa ne vidite; ki imate ušesa, pa ne slišite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Mar se me ne bojite?‹ govori Gospod. ›Ali ne boste trepetali ob moji prisotnosti, ko sem položil pesek za mejo morju z večnim odlokom, da ta ne more preiti? Čeprav se njegovi valovi premetavajo, vendar ne morejo prevladati; čeprav rjovijo, vendar ne morejo preiti preko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Toda to ljudstvo ima puntarsko in uporno srce; spuntali so se in odšli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Niti ne pravijo v svojem srcu: ›Sedaj se bojmo Gospoda, svojega Boga, ki daje dež, tako zgodnji kakor pozni, v svojem obdobju. Prihranja nam tedne, določene za žetev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vaše krivičnosti so te stvari obrnile proč in vaši grehi so pred vami zadržali dobre stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Kajti med mojim ljudstvom so najdeni zlobni možje. Prežijo v zasedi kakor tisti, ki nastavljajo pasti; oni nastavijo past, ujamejo ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Kakor je kletka polna ptic, tako so njihove hiše polne prevare. Zato so postali veliki in obogateli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Postali so debeli, sijejo. Da, presegajo dejanja zlobnih. Ne sodijo primera sirot, vendar uspevajo in pravici pomoči potrebnih ne sodijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Mar ne bom obiskal zaradi teh stvari?‹ govori Gospod: ›Ali ne bo moja duša maščevana na takem narodu, kot je ta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Čudovita in strašna stvar je zagrešena v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Preroki prerokujejo napačno in duhovniki vladajo s svojimi sredstvi. Moje ljudstvo ima rado to tako. Kaj pa boste storili ob koncu tega?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, '»Oh vi, Benjaminovi otroci, zberite se, da zbežite iz srede Jeruzalema in trobite na šofar v Tekói in postavite znamenje ognja v Bet Keremu. Kajti zlo se pojavlja iz severa in veliko uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, '§ Hčer sionsko sem primerjal z ljubko in prefinjeno žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Pastirji s svojimi tropi bodo prišli k njej, svoje šotore bodo postavili naokoli nje, vsak bo pasel na svojem kraju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '»Pripravite vojno zoper njo. Vstanimo in gremo gor opoldan. Gorje nam! Kajti dan mineva, kajti sence večera so podaljšane.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, '»Vstanimo in gremo gor ponoči in uničimo njene palače.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Kajti tako je rekel Gospod nad bojevniki: »Posekajte drevesa in nasujte nasip zoper [prestolnico] Jeruzalem. To je mesto, ki bo obiskano; ona je celotno zatiranje v njeni sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Kakor studenec bruha svoje vode, tako ona bruha svojo zlobnost. Nasilje in plen je slišati v njej; žalost in rane so nenehno pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Bodi poučena, oh [prestolnica] Jeruzalem, da ne bi moja duša odšla od tebe; da te ne bi naredil zapuščeno, deželo, ki ni naseljena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tako govori Gospod nad bojevniki: »Temeljito bodo paberkovali Izraelov preostanek kakor trto. Svojo roko obrni nazaj kakor obiralci grozdja v košare.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Komu naj govorim in dam svarilo, da bi lahko slišali? Glej, njihovo uho je neobrezano in ne morejo prisluhniti. Glej, Gospodova beseda jim je graja; v njej nimajo veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Zato sem poln Gospodove razjarjenosti; izmučen sem z zadrževanjem. Izlil jo bom ven na otroke naokoli in skupaj na zbor mladeničev, kajti vzet bo celo soprog z ženo, ostarel s tistim, ki je izpolnjen z dnevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Njihove hiše bodo obrnjene k drugim, skupaj z njihovimi polji in ženami, kajti svojo roko bom iztegnil nad prebivalce dežele,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, '»Kajti od najmanjših izmed njih, celo do največjih izmed njih, je vsak predan pohlepu, in od preroka, celo do duhovnika, vsak krivo postopa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Kajti površno so ozdravili rano hčere mojega ljudstva, rekoč: ›Mir, mir,‹ ko tam ni miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Mar so bili osramočeni, ko so zagrešili ogabnost? Ne, sploh niso bili osramočeni niti niso mogli zardeti. Zato bodo padli med tistimi, ki padajo. Ob času, ko jih obiščem, bodo vrženi dol,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Tako govori Gospod: »Ustavite se na poteh in glejte ter vprašajte za starimi stezami, kje je dobra pot, hodite po njej in našli boste počitek svojim dušam.« Rekli pa so: »Mi ne bomo hodili po njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Prav tako sem nad vami postavil stražarje, rekoč: »Prisluhnite zvoku šofarja.« Toda rekli so: »Ne bomo prisluhnili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Zato poslušajte, vi narodi in vedite, oh skupnost, kaj je med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Poslušaj, oh zemlja. Glej, nad to ljudstvo bom privedel zlo, celó sad njihovih misli, ker niso prisluhnili mojim besedam niti moji postavi, temveč so jo zavrnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'S kakšnim namenom prihaja k meni kadilo iz Sabe in prijeten trst iz daljne dežele? Vaše žgalne daritve mi niso sprejemljive niti mi vaše klavne daritve niso prijetne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Zato tako govori Gospod: »Glej, pred to ljudstvo bom položil kamne spotike in očetje in sinovi bodo skupaj padli nanje; sosed in njegov prijatelj se bosta pogubila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tako govori Gospod: »Glej, ljudstvo prihaja iz severne dežele in velik narod bo dvignjen od zemljinih strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Prijeli bodo lok in sulico; kruti so in nimajo usmiljenja; njihov glas rjovi kakor morje; in jahajo na konjih, postavljeni v vrste kakor možje za vojno zoper tebe, oh sionska hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, '»Slišali smo o njihovi slavi. Naše roke so oslabele. Tesnoba se nas je polastila in bolečina kakor žensko v porodnih mukah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne pojdi naprej na polje niti ne hodi po poti, kajti sovražnikov meč in strah sta na vsaki strani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Oh hči mojega ljudstva, opaši se z vrečevino in se valjaj v pepelu. Naredi si žalovanje kakor za edinim sinom, najbolj grenko žalovanje, kajti plenilec bo nenadoma prišel nad nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Postavil sem te za stolp in trdnjavo med svojim ljudstvom, da lahko spoznaš in preizkusiš njihovo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Vsi so nadležni puntarji, hodijo z obrekovalci. Bron so in železo, vsi so izprijenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Mehovi so požgani, svinec je použit z ognjem; livar zaman tali, kajti zlobni niso izločeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Ljudje jih bodo imenovali zavrženo srebro, ker jih je Gospod zavrnil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '»Stopi v velika vrata Gospodove hiše in razglasi to besedo in reci: ›Poslušajte Gospodovo besedo, vsi vi iz Juda, ki vstopate pri teh velikih vratih, da obožujete Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tako govori Gospod nad bojevniki, Izraelov Bog: ›Poboljšajte svoje poti in svoja dejanja in jaz vam bom povzročil, da prebivate na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne zaupajte v lažnive besede, rekoč: › Gospodov tempelj,‹ › Gospodov tempelj,‹ › Gospodov tempelj so ti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Kajti če temeljito poboljšate svoje poti in svoja dejanja, če temeljito izvršite sodbo med človekom in njegovim sosedom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'če ne zatirate tujca, sirote, vdove, in na tem kraju ne prelivate nedolžne krvi niti v svojo škodo ne hodite za drugimi bogovi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'potem vam bom povzročil, da prebivate na tem kraju, v deželi, ki sem jo dal vašim očetom na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Glejte, zaupate v lažnive besede, ki ne morejo koristiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Ali boste kradli, morili, počeli zakonolomstvo, krivo prisegali, zažigali kadilo Báalu in hodili za drugimi bogovi, ki jih ne poznate');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'in prišli ter stali pred menoj v tej hiši, ki je imenovana z mojim imenom in rekli: »Rešeni smo, da bi počeli vse te ogabnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ali je ta hiša, ki je imenovana z mojim imenom, v vaših očeh postala brlog roparjev? Glejte, celo jaz sem to videl,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, '»Toda pojdite sedaj k mojemu kraju, ki je bil v Šilu, kjer sem najprej postavil svoje ime in poglejte, kaj sem mu storil zaradi zlobnosti svojega ljudstva Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'In sedaj, ker ste storili vsa ta dejanja,« govori Gospod »in sem vam govoril, vas zgodaj vzdigoval in govoril, toda niste slišali; in vas klical, toda niste odgovorili;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'zato bom tej hiši, ki je imenovana z mojim imenom, v katerega zaupate in kraju, ki sem ga dal vam in vašim očetom, storil kakor sem storil Šilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Zavrgel vas bom iz svojega pogleda, kakor sem zavrgel vse vaše brate, celó celotno Efrájimovo seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Zato ne moli za to ljudstvo, niti ne povzdiguj klica, niti molitve zanje, niti ne posreduj k meni, kajti jaz te ne bom poslušal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Mar ne vidiš, kaj počno v Judovih mestih in na ulicah [prestolnice] Jeruzalem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Otroci nabirajo les, očetje netijo ogenj in ženske gnetejo svoje testo, da naredijo kolače kraljici neba in da izlivajo pitne daritve k drugim bogovom, da bi me lahko dražili k jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Mar me dražijo do jeze?« govori Gospod: » Mar ne dražijo sami sebe, do zmešnjave njihovih lastnih obrazov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Zato tako govori Gospod Bog: »Glej, moja jeza in moja razjarjenost bo izlita na tem kraju, na človeka, na žival, na drevesa polja in na sad tal; ta bo gorela in ne bo pogašena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tako govori Gospod nad bojevniki, Izraelov Bog: »Položite svoje žgalne daritve k svojim klavnim daritvam in jejte meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Kajti nisem govoril vašim očetom niti jim nisem zapovedal na dan, ko sem jih privedel iz egiptovske dežele, glede žgalnih daritev ali klavnih daritev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'toda ukazal sem jim to stvar, rekoč: ›Ubogajte moj glas in jaz bom vaš Bog in vi boste moje ljudstvo; hodite po vseh poteh, ki sem vam jih zapovedal, da vam bo lahko dobro.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Toda niso prisluhnili niti nagnili svojega ušesa, temveč so hodili po nasvetih in po zamislih svojega zlega srca in odšli nazaj in ne naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Od dneva, ko so vaši očetje izšli iz egiptovske dežele, do tega dne, sem vam celo pošiljal vse svoje služabnike preroke, dnevno sem jih zgodaj vzdigoval in pošiljal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Vendar mi niso prisluhnili niti nagnili svojega ušesa, temveč so otrdili svoj vrat. Ravnali so huje kakor njihovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Zato jim boš govoril vse te besede, toda ne bodo ti prisluhnili. Tudi klical boš k njim, toda ne bodo ti odgovorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, '§ Toda rekel jim boš: ›To je narod, ki ne uboga glasu Gospoda, svojega Boga niti ne prejema grajanja. Resnica je izginila in je iztrebljena iz njihovih ust.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ostriži svoje lase, oh [prestolnica] Jeruzalem in jih odvrzi proč in povzemi žalostinko na visokih krajih, kajti Gospod je zavrnil in zapustil rod svojega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Kajti Judovi otroci so storili zlo v mojem pogledu,« govori Gospod. »Svoje ogabnosti so postavili v hiši, ki se imenuje z mojim imenom, da jo oskrunijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Zgradili so visoke kraje Tofeta, ki je v dolini sina Hinómovega, da svoje sinove in svoje hčere sežigajo v ognju, kar jim nisem zapovedal niti ni prišlo v moje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Zato, glej, prihajajo dnevi,« govori Gospod, »da ta ne bo več imenovan Tofet niti dolina sina Hinómovega, temveč dolina klanja, kajti v Tofetu bodo pokopavali, dokler tam ne bo več prostora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Trupla tega ljudstva bodo meso za perjad neba in zemeljske zveri in nihče jih ne bo podil proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Potem bom povzročil, da od Judovih mest in od ulic [prestolnice] Jeruzalem preneha glas smeha, glas veselja, glas ženina in glas neveste, kajti dežela bo zapuščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '»Ob tistem času,« govori Gospod, »bodo prinesli iz njihovih grobov kosti Judovega kralja, kosti njegovih princev, kosti duhovnikov, kosti prerokov in kosti prebivalcev [prestolnice] Jeruzalem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'in raztrosili jih bodo pred soncem, luno in vso vojsko neba, ki so jih ljubili, ki so jim služili, za katerimi so hodili, ki so jih iskali in ki so jih oboževali; ne bodo zbrane niti pokopane, le-te bodo za gnoj na obličju zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Ves preostanek tistih, ki ostanejo od te zlobne družine, ki ostanejo v vseh krajih, kamor sem jih pognal, bodo raje izbrali smrt kakor življenje,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Poleg tega jim boš rekel: ›Tako govori Gospod: ›Ali bodo padli in ne vstali? Ali se bo obrnil proč in ne vrnil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Zakaj je potem to ljudstvo iz [prestolnice] Jeruzalem zdrknilo nazaj z neprestanim odpadom? Trdno se držijo prevare, zavračajo, da bi se vrnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Prisluhnil sem in slišal, toda niso pravilno govorili. Noben človek se ni pokesal od svoje zlobnosti, rekoč: ›Kaj sem storil?‹ Vsak se je obrnil k svoji smeri, kakor konj hiti v bitko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Da, štorklja na nebu pozna svoje določene čase, grlica, žerjav in lastovka obeležujejo čas svojega prihajanja, toda moje ljudstvo ne pozna Gospodove sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kako pravite: ›Modri smo in z nami je Gospodova postava?‹ Glej, zagotovo jo je on naredil zaman, pisalo pisarjev je zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Modri možje so osramočeni, zaprepadeni in ujeti. Glej, zavrnili so Gospodovo besedo in kakšna modrost je v njih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Zato bom njihove žene dal drugim in njihova polja tistim, ki jih bodo podedovali. Kajti vsak, od najmanjšega celo do največjega, se nagiba k pohlepu, od preroka celo do duhovnika, vsak postopa napačno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Kajti površno so ozdravili rano hčere mojega ljudstva, rekoč: ›Mir, mir,‹ ko tam ni miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Mar so bili osramočeni, ko so zagrešili ogabnost? Ne, sploh niso bili osramočeni niti niso mogli zardeti. Zato bodo padli med tistimi, ki padajo. V času njihovega obiskanja bodo vrženi dol,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, '§ ›Zagotovo jih bom použil,‹ govori Gospod: › tam ne bo grozdja na trti niti fig na figovem drevesu in list bo ovenel; in stvari, ki sem jim jih dal, bodo šle proč od njih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Zakaj mirno sedimo? Zberite se in dajmo, vstopimo v obrambna mesta in tam bodimo tiho, kajti Gospod, naš Bog, nas je položil v molk in nam dal za piti vodo iz žolča, ker smo grešili zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Iskali smo mir, toda nič dobrega ni prišlo, in na čas zdravja, pa glej težava!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, '»Prhanje njihovih konj je bilo slišati od Dana. Celotna zemlja je trepetala ob zvoku rezgetanja njegovih močnih, kajti prišli so in požrli deželo in vse, kar je v njej; mesto in tiste, ki prebivajo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Kajti glejte, jaz bom med vas poslal kače, strupene kače, ki ne bodo očarane in te vas bodo pikale,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Ko bi se želel tolažiti zoper bridkost, je moje srce oslabelo v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Glej, glas vpitja hčere mojega ljudstva zaradi tistih, ki prebivajo v daljni deželi: › Mar ni Gospoda na Sionu? Ali ni njen kralj v njej?‹ Zakaj so me do jeze dražili s svojimi rezanimi podobami in s tujimi ničevostmi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Žetev je mimo, poletje je končano, mi pa nismo rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Zaradi zloma hčere mojega ljudstva sem zlomljen, črn sem, osuplost se me je polastila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Mar ni balzama v Gileádu, ali tam ni nobenega zdravnika? Zakaj potem zdravje hčere mojega ljudstva ni povrnjeno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oh, da bi bila moja glava vode in moje oči studenec solza, da bi lahko dan in noč jokal zaradi umorjenih hčera svojega ljudstva!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Oh, da bi imel v divjini kraj za nastanitev popotnikov; da bi lahko zapustil svoje ljudstvo in odšel od njih! Kajti vsi so zakonolomci, zbor zahrbtnih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Svoje jezike krivijo za laži kakor svoj lok, toda niso hrabri za resnico na zemlji. Kajti napredujejo od zla k zlu, mene pa ne poznajo,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, '›Vsakdo naj se pazi svojega soseda in ne zaupajte v kateregakoli brata, kajti vsak brat bo popolnoma izpodrinjen in vsak sosed bo hodil z obrekovalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Zavajali bodo vsak svojega soseda in ne bodo govorili resnice. Svoj jezik so naučili, da govori laži in izmučili so se s početjem krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tvoje prebivališče je v sredi prevare, zaradi prevare so odklonili, da me spoznajo,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Zato tako govori Gospod nad bojevniki: ›Glej, stopil jih bom in jih preizkusil. Kajti kako naj bi delal za hčer svojega ljudstva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Njihov jezik je kakor izstreljena puščica; ta govori prevaro. Nekdo s svojimi usti govori miroljubno svojemu sosedu, toda v srcu preži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ali jih ne bom obiskal zaradi teh stvari?‹ govori Gospod. ›Mar se ne bo moja duša maščevala na takšnem narodu, kot je ta?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Zaradi gora bom povzdignil jokanje in tarnanje in zaradi prebivališč divjine žalovanje, ker so požgani, tako da nihče ne more iti skozi njih; niti ljudje ne morejo slišati glasu živine. Tako perjad neba kakor živali polja so pobegnile, odšle so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, '[Prestolnico] Jeruzalem bom naredil kupe in brlog zmajev. Judova mesta bom naredil zapuščena, brez prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kdo je moder človek, da lahko to razume? Kdo je tisti, kateremu so Gospodova usta govorila, da lahko to oznani, čemu dežela propada in je požgana kakor divjina, da nihče ne gre skoznjo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Gospod govori: ›Ker so zapustili mojo postavo, ki sem jo postavil prednje in niso ubogali mojega glasu niti hodili v tem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'temveč so hodili po zamisli svojega lastnega srca in za Báali, kar so jih naučili njihovi očetje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Zato tako govori Gospod nad bojevniki, Izraelov Bog: ›Glej, hranil jih bom, celó to ljudstvo, s pelinom in piti jim bom dajal vodo iz žolča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Razkropil jih bom tudi med pogane, ki jih niso poznali niti oni niti njihovi očetje. Za njimi bom poslal meč, dokler jih ne použijem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tako govori Gospod nad bojevniki: ›Preudarite in pokličite žalovalke, da bi lahko prišle in pošljite po spretne ženske, da bi lahko prišle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Podvizajo naj se in povzamejo tarnanje za nas, da bodo naše oči lahko tekle s solzami in naše veke brizgale z vodami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Kajti glas tarnanja je slišati iz Siona: ›Kako smo oplenjeni! Silno smo zbegani, ker smo zapustili deželo, ker so nas naša prebivališča izvrgla.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Vendar poslušajte Gospodovo besedo, oh ve ženske in naj vaše uho prejme besedo iz njegovih ust in svoje hčere učite tarnanja in vsaka svojo sosedo objokovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Kajti smrt se je povzpela skozi naša okna in vstopila v naše palače, da iztrebi otroke od zunaj in mladeniče iz ulic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, '»Govori: ›Tako govori Gospod: ›Celo trupla ljudi bodo padala kakor gnoj na odprtem polju in kakor prgišče za žanjcem in nihče jih ne bo zbral.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tako govori Gospod: ›Ne dopusti, da moder človek slavi v svoji modrosti niti naj mogočen človek ne slavi v svoji moči, naj bogat človek ne slavi v svojih bogastvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Temveč naj tisti, ki slavi, slavi v tem, da me razume in spoznava, da jaz sem Gospod, ki izvajam ljubečo skrbnost, sodbo in pravičnost na zemlji. Kajti v teh stvareh se veselim,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, '›Glej, dnevi prihajajo,‹ govori Gospod, ›da bom kaznoval vse tiste, ki so obrezani, z neobrezanimi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egipt, Juda, Edóm, Amónove otroke, Moáb in vse, ki so na skrajnih vogalih, ki prebivajo v divjini, kajti vsi ti narodi so neobrezani in vse Izraelove hiše so v srcu neobrezane.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Prisluhnite besedi, ki vam jo govori Gospod, oh hiša Izraelova:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, '»Tako govori Gospod: ›Ne uči se poti poganov in ne bodi zaprepaden ob znamenjih z neba, kajti pogani so zaprepadeni ob njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Kajti običaji ljudstva so prazni, kajti nekdo s sekiro poseka drevo iz gozda, delo delavčevih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Okrasijo ga s srebrom in zlatom; pritrdijo ga z žeblji in kladivi, da se ne premika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Pokončni so kakor palmovo drevo, toda ne govorijo. Morajo jih nositi, ker ne morejo hoditi. Ne bojte se jih, kajti ne morejo storiti zla niti ni v njih, da delajo dobro.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Ker ne obstaja nihče podoben tebi, oh Gospod; ti si velik in tvoje ime je veliko v moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kdo se te ne bi bal, oh kralj narodov? Kajti tebi to pripada, glede na to, da med vsemi modrimi možmi narodov in med vsemi njihovimi kraljestvi, ni tam nikogar podobnega tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Toda oni so vsi skupaj brutalni in nespametni. Kos lesa je nauk ničevosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, '§ Srebro, sploščeno na ploščice, je prineseno iz Taršíša in zlato iz Ufáza, delo delavca in iz rok livarja. Modra in vijolična so njihova oblačila. Vsa so delo spretnih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Toda Gospod je resničen Bog, on je živi Bog in večen kralj. Ob njegovem besu bo zemlja trepetala in narodi ne bodo zmožni prenesti njegovega ogorčenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Tako jim boste govorili: › Celó bogovi, ki niso naredili neba in zemlje, bodo izginili z zemlje in izpod tega neba.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'S svojo močjo je naredil zemljo, s svojo modrostjo je osnoval zemeljski [krog] in s svojo preudarnostjo razprostrl nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kadar izusti svoj glas, je tam množica vodá v nebesih in meglicam povzroča, da se dvigujejo od koncev zemlje; on dela bliskanje z dežjem in iz svojih zakladnic prinaša veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Vsak človek je v svojem spoznanju brutalen. Vsak livar je zbegan z rezano podobo, kajti njegova ulita podoba je neresnica in tam ni diha v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Ničevost so in delo zmot. V času njihovega obiskanja bodo izginili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Jakobov delež ni podoben njihovemu, kajti on je tvorec vseh stvari; in Izrael je palica njegove dediščine. Gospod nad bojevniki je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Zberi svoje blago iz dežele, oh prebivalec iz trdnjave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Kajti tako govori Gospod: ›Glej, naenkrat bom izvrgel prebivalce dežele in jih spravil v tegobo, da bodo lahko našli, [da je] to tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Gorje mi za mojo poškodbo! Moja rana je boleča. Toda rekel sem: »Resnično, to je žalost in jaz jo moram nositi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Moje šotorsko svetišče je oplenjeno in vse moje vrvi so pretrgane, moji otroci so odšli od mene in jih ni, nikogar ni, da bi še razpenjal moj šotor in da bi postavljal moje zavese.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Kajti pastirji so postali brutalni in niso iskali Gospoda, zato ne bodo uspeli in vsi njihovi tropi bodo razkropljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Glej, hrup objave je prišel in veliko razburjenje iz severne dežele, da bi Judova mesta naredil opustošena in brlog zmajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Oh Gospod, vem, da človekova pot ni v njem samem, tega ni v človeku, ki hodi, da usmerja svoje korake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Oh Gospod, grajaj me, toda s sodbo; ne v svoji jezi, da me ne bi privedel v nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Svojo razjarjenost izlij na pogane, ki te ne poznajo in na družine, ki ne kličejo k tvojemu imenu, kajti pojedli so Jakoba in ga požrli in ga pogoltnili ter njegovo prebivališče naredili zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Beseda, ki je prišla k Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '»Poslušaj besede te zaveze in govori možem iz Juda in prebivalcem [prestolnice] Jeruzalem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'in jim reci: ›Tako govori Gospod, Izraelov Bog: ›Preklet bodi mož, ki ne uboga besed te zaveze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'ki sem jo zapovedal vašim očetom na dan, ko sem jih izpeljal iz egiptovske dežele, iz železne talilne peči, rekoč: ›Ubogajte moj glas in jih izvršujte, glede na vse, kar vam zapovedujem. Tako boste moje ljudstvo in jaz bom vaš Bog,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'da bom lahko izpolnil prisego, ki sem jo prisegel vašim očetom, da jim dam deželo, kjer tečeta mleko in med, kakor je to ta dan.‹« Potem sem odgovoril in rekel: »Tako naj bo, oh Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Potem mi je Gospod rekel: »Razglasi vse te besede po Judovih mestih in ulicah Jeruzalema, rekoč: ›Poslušajte besede te zaveze in jih izpolnjujte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Kajti iskreno sem izpričal vašim očetom na dan, ko sem jih privedel gor iz egiptovske dežele, celó do današnjega dne, [jih] zgodaj vzdigoval in izjavljal, rekoč: ›Ubogajte moj glas.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Vendar niso ubogali niti nagnili svojega ušesa, temveč so vsi hodili v zamisli svojega zlega srca. Zato bom nanje privedel vse besede te zaveze, ki sem jim jo zapovedal izpolnjevati, toda oni jih niso izpolnjevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Gospod mi je rekel: »Zarota je najdena med Judovimi možmi in med prebivalci Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Obrnili so se nazaj h krivičnostim svojih pradedov, ki so odklanjali poslušati moje besede; in šli za drugimi bogovi, da jim služijo. Izraelova hiša in Judova hiša sta prelomili mojo zavezo, ki sem jo sklenil z njihovimi očeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Zato tako govori Gospod: ›Glej, nanje bom privedel zlo, ki mu ne bodo mogli pobegniti. Čeprav bodo klicali k meni, jim ne bom prisluhnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Potem bodo Judova mesta in prebivalci Jeruzalema šli in klicali k bogovom, katerim darujejo kadilo. Toda sploh jih ne bodo rešili v času njihove stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Kajti glede na število tvojih mest so bili tvoji bogovi, oh Juda; in glede na število ulic [prestolnice] Jeruzalem ste postavili oltarje tisti sramotni stvari, celó oltarje, da zažigate kadilo Báalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Zatorej ne moli za to ljudstvo niti ne povzdiguj vpitja ali molitve zanje, kajti jaz jih ne bom poslušal ob času, ko zaradi svoje stiske vpijejo k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Kaj ima moj ljubljeni za početi v moji hiši, ko vidi, da je ona izvrševala nespodobnost s številnimi in je sveto meso odšlo od tebe? Ko počneš zlo, potem se razveseljuješ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Gospod je tvoje ime imenoval: ›Zelena oljka, čeden in lep sad.‹ Z zvokom velikega hrupa je na njej vžgal ogenj in njene mladike so polomljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Kajti Gospod nad bojevniki, ki te je zasadil, je zoper tebe proglasil zlo, zaradi zla Izraelove hiše in Judove hiše, ki so ga storili zoper sebe, da bi me dražili do jeze v darovanju kadila Báalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Gospod mi je dal spoznanje o tem in jaz sem to spoznal; takrat si mi kazal njihova dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Toda jaz sem bil podoben jagnjetu ali volu, ki je priveden h klanju in nisem vedel, da so zoper mene snovali naklepe, rekoč: »Uničimo drevo skupaj z njegovim sadom in odsekajmo ga iz dežele živih, da se njegovega imena ne bo več spominjalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Toda, oh Gospod nad bojevniki, ki sodiš pravično, ki preizkušaš notranjost in srce, naj vidim tvoje maščevanje na njih, kajti tebi sem razodel svoj primer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, '»Zato tako govori Gospod o možeh iz Anatóta, ki ti strežejo po življenju, rekoč: ›Ne prerokuj v Gospodovem imenu, da ne umreš po naši roki.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Zato tako govori Gospod nad bojevniki: ›Glej, kaznoval jih bom; mladenič bo umrl pod mečem, njihovi sinovi in njihove hčere bodo umrli od lakote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Tam ne bo nobenega ostanka izmed njih, kajti nad ljudi iz Anatóta bom privedel zlo, celó leto njihovega obiskanja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Pravičen si ti, oh Gospod, ko se pravdam s teboj, vendar mi pusti govoriti s teboj o tvojih sodbah: »Zakaj pot zlobnih uspeva? Zakaj so srečni vsi tisti, ki postopajo zelo zahrbtno?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Zasadil si jih, da, zakoreninili so se, rastejo, da, prinašajo sad. Blizu si v njihovih ustih in daleč od njihovih notranjosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Toda ti, oh Gospod, me poznaš, videl si me in preizkusil si moje srce do tebe. Potegni jih ven kakor ovce za klanje in jih pripravi za dan klanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Doklej bo dežela žalovala in zelišča vsakega polja venela zaradi zlobnosti tistih, ki prebivajo v njej? Živali so použite in ptice, ker so rekli: »Ne bo videl našega zadnjega konca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '»Če si tekel s pešci in če so te utrudili, kako lahko potem tekmuješ s konji? In če so te utrudili v deželi miru, v kateri zaupaš, kako boš potem storil v naraščanju Jordana?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Kajti celo tvoji bratje in hiša tvojega očeta, celo oni so zahrbtno postopali s teboj; da, za teboj so poklicali množico. Ne verjemi jim, čeprav ti govorijo lepe besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Zapustil sem svojo hišo, zavrgel svojo dediščino, srčno ljubljeno svoje duše sem predal v roko njenih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Moja dediščina mi je kakor lev v gozdu; ta vpije proti meni, zatorej sem jo zasovražil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Moja dediščina mi je kakor lisasta ptica, ptice naokoli so zoper njo. Pridite, zberite se vse ve zveri polja, pridite žret.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Mnogo pastirjev je uničilo moj vinograd, moj delež so pomendrali pod stopalom, moj prijeten delež so naredili zapuščeno divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Naredili so jo zapuščeno in zapuščena je žalovala k meni; celotna dežela je zapuščena, ker si noben človek tega ne jemlje k srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Plenilci so skozi divjino prišli na vse visoke kraje, kajti Gospodov meč bo požiral od enega konca dežele celo do drugega konca dežele; nobeno meso ne bo imelo miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Sejali so pšenico, toda želi bodo trnje; položili so se v bolečino, toda ne bo jim koristilo. Sram jih bo tvojih poplačil, zaradi krute Gospodove jeze.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tako govori Gospod zoper vse moje hudobne sosede, ki se dotikajo dediščine, za katero sem svojemu ljudstvu Izraelu dal, da jo podeduje: »Glej, izruval jih bom iz njihove dežele in Judovo hišo bom izruval izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Potem ko jih bom izruval, se bo zgodilo, da se bom vrnil in imel sočutje z njimi in jih bom ponovno privedel, vsakega človeka k njegovi dediščini in vsakega človeka k njegovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'In zgodilo se bo, če se bodo marljivo učili poti mojega ljudstva, da bodo prisegali pri mojem imenu: › Gospod živi,‹ kakor so oni učili moje ljudstvo, da prisega pri Báalu, potem bodo pozidani v sredi mojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Toda če ne bodo ubogali, bom popolnoma izruval in uničil ta narod,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tako mi govori Gospod: »Pojdi in si priskrbi lanen pas in ga daj na svoja ledja, v vodo pa ga ne daj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Tako sem dobil pas glede na Gospodovo besedo in si ga nadel na ledja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Gospodova beseda je drugič prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '»Vzemi pas, ki si ga dobil, ki je na tvojih ledjih in vstani, pojdi k Evfratu in ga tam skrij v skalno luknjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Tako sem odšel in ga skril pri Evfratu, kakor mi je Gospod zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Po mnogih dneh se je pripetilo, da mi je Gospod rekel: »Vstani, pojdi k Evfratu in vzemi od tam pas, ki sem ti ga tam zapovedal skriti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Potem sem odšel k Evfratu in kopál ter vzel pas iz kraja, kjer sem ga skril. Glej, pas je bil iznakažen, ni bil koristen za nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Potem je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '»Tako govori Gospod: ›Na ta način bom oškodoval Judov ponos in velik ponos Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'To zlo ljudstvo, ki zavrača poslušati moje besede, ki hodijo v zamisli svojega srca in hodijo za drugimi bogovi, da jim služijo in da jih obožujejo, bodo torej kakor ta pas, ki ni dober za nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Kajti kakor se pas trdno drži moževih ledij, tako sem storil, da se me trdno drži celotna Izraelova hiša in celotna Judova hiša,‹ govori Gospod, ›da mi bodo lahko za ljudstvo, za ime, za hvalo in za slavo. Toda nočejo slišati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Zato jim boš govoril to besedo: ›Tako govori Gospod, Izraelov Bog: ›Vsak meh bo napolnjen z vinom.‹ Rekli ti bodo: ›Mar ne vemo zagotovo, da bo vsak meh napolnjen z vinom?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Potem jim boš rekel: ›Tako govori Gospod: ›Glejte, s pijanostjo bom napolnil vse prebivalce te dežele, celo kralje, ki sedijo na Davidovem prestolu, duhovnike, preroke in vse prebivalce [prestolnice] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Treščil jih bom enega ob drugega, celo očete in sinove skupaj,‹ govori Gospod. ›Ne bom se usmilil niti prizanašal niti imel usmiljenja, temveč jih uničim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Poslušajte in pazljivo prisluhnite. Ne bodite ponosni, kajti Gospod je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dajte slavo Gospodu, svojemu Bogu, preden povzroči temo in preden se vaša stopala spotaknejo na temnih gorah in medtem ko gledate za svetlobo, jo obrne v smrtno senco in jo naredi [za] veliko temo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Toda če tega ne boste poslušali, bo moja duša jokala na skrivnih krajih zaradi vašega ponosa. Moje oko bo hudo jokalo in teklo s solzami, ker je bil Gospodov trop ujet odveden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, '»Reci kralju in kraljici: ›Ponižajta se, usedita se, kajti vajine kneževine bodo propadle, celó krona vajine slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Južna mesta bodo zaprta in nihče jih ne bo odprl. Ves Juda bo odveden v ujetništvo, v celoti bo odveden v ujetništvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Povzdigni svoje oči in poglej tiste, ki prihajajo iz severa. Kje je trop, ki ti je bil dan, tvoj krasen trop?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Kaj boš rekla, ko te bo kaznoval? Kajti učila si jih, da so poveljniki in kakor vodja nad teboj. Ali te ne bodo zajele bolesti kakor žensko v porodnih mukah?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Če rečeš v svojem srcu: ›Zakaj so prišle nadme te stvari?‹ Zaradi veličine tvoje krivičnosti so odkriti krajci tvojih oblačil in tvoje pete so razgaljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Mar lahko Etiopijec spremeni svojo kožo ali leopard svoje lise? Potem bi lahko tudi vi delali dobro, ki ste navajeni, da delate zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Zato jih bom razkropil kakor strnišče, ki ga odnaša veter iz divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'To je tvoj žreb, delež tvojih zmožnosti od mene,‹ govori Gospod; ›ker si me pozabila in zaupala v neresnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Zato bom odkril krajce tvojih oblačil nad tvojim obrazom, da se lahko prikaže tvoja sramota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Videl sem tvoja zakonolomstva in tvoja rezgetanja, nespodobnost tvojega vlačugarstva in tvoje ogabnosti na hribih polj. Gorje ti, oh [prestolnica] Jeruzalem! Mar ne boš očiščena? Kdaj bo to enkrat prišlo?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Beseda Gospodova, ki je prišla Jeremiju glede pomanjkanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda žaluje in njegova velika vrata pešajo; črna so do tal; in krik [prestolnice] Jeruzalem se je vzdignil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Vsi njeni plemiči so poslali svoje malčke k vodam. Prišli so k jamam, pa niso našli nobene vode; s svojimi praznimi posodami so se vrnili; bili so osramočeni in zbegani in si pokrili svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, '§ Ker so tla razpokana, kajti ni bilo dežja na zemljo, so bili orači osramočeni, pokrili so si svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Da, tudi košuta je povrgla na polju in to zapustila, ker tam ni bilo nobene trave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Divji osli so stali na visokih krajih, vohali so veter kakor zmaji; njihove oči so odpovedale, ker tam ni bilo nobene trave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Oh Gospod, čeprav naše krivičnosti pričajo zoper nas, stori to zaradi svojega imena, kajti naša zdrknjenja nazaj so številna; grešili smo zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Oh Izraelovo upanje, njegov rešitelj v času stiske, zakaj bi bil kakor tujec v deželi in kakor popotnik, ki se obrača vstran, da ostane čez noč?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Zakaj bi bil kakor osupel človek, kakor mogočen človek, ki ne more rešiti? Vendar si ti, oh Gospod, v naši sredi in mi smo imenovani po tvojem imenu; ne zapusti nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tako govori Gospod temu ljudstvu: »Tako so ljubili tavanje, svojih stopal niso zadržali, zato jih Gospod ne sprejema. Sedaj se bo spomnil njihove krivičnosti in obiskal njihove grehe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Potem mi je Gospod rekel: »Ne moli za to ljudstvo za njihovo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Ko se postijo, ne bom slišal njihovega vpitja; in ko darujejo žgalno daritev in daritev, jih ne bom sprejel. Temveč jih bom použil z mečem, lakoto in kužno boleznijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Potem sem rekel: »Ah, Gospod Bog! Glej, preroki jim pravijo: ›Ne boste videli meča niti ne boste imeli lakote. Temveč vam bom na tem kraju dal zagotovljen mir.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Nato mi je Gospod rekel: »›Preroki v mojem imenu prerokujejo laži. Jaz jih nisem poslal niti jim zapovedal niti jim nisem govoril. Prerokujejo vam lažnivo videnje, vedeževanje, prazno stvar in prevaro svojega srca.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Zato tako govori Gospod glede prerokov, ki prerokujejo v mojem imenu in jih jaz nisem poslal in vendar pravijo: ›Meča in lakote ne bo v tej deželi.‹ Z mečem in lakoto bodo ti preroki použiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Ljudstvo, ki mu prerokujejo, bo zaradi lakote in meča vrženo ven na ulice [prestolnice] Jeruzalem. Nikogar ne bodo imeli, da bi jih pokopal, njih, njihove žene niti njihove sinove niti njihove hčere, kajti nanje bom izlil njihovo zlobnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Zato jim boš rekel to besedo: ›Naj iz mojih oči tečejo solze ponoči in podnevi in naj ne prenehajo, kajti devica, hči mojega ljudstva je zlomljena z veliko vrzeljo, z zelo bolečim udarcem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Če grem naprej na polje, potem glej, umorjeni z mečem! Če vstopim v mesto, potem glej, tisti, ki so bolni od lakote! Da, prerok in duhovnik gresta naokrog v deželo, ki je ne poznata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Mar si popolnoma zavrnil Juda? Ali se je tvoji duši gnusil Sion? Zakaj si nas udaril in tam ni ozdravljenja za nas? Iskali smo mir, pa tam ni nič dobrega; in čas ozdravljenja, pa glej, stiska!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Priznavamo, oh Gospod, našo zlobnost in krivičnost naših očetov, kajti grešili smo zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Ne preziraj nas zaradi svojega imena, ne osramoti prestola svoje slave. Spomni se, ne prelomi svoje zaveze z nami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Je katerakoli izmed ničevosti poganov, ki lahko povzroči dež? Lahko nebo da nalive? Mar nisi ti, oh Gospod, naš Bog? Zato bomo čakali nate, ker si ti naredil vse te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Potem mi je Gospod rekel: »Čeprav bi pred menoj stala Mojzes in Samuel, vendar moj um ne bi mogel biti k temu ljudstvu. Vrzi jih iz mojega pogleda in naj gredo naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Zgodilo se bo, če ti rečejo: ›Kam naj gremo naprej?‹ Potem jim boš rekel: ›Tako govori Gospod: ›Tisti, ki ste za smrt, k smrti; tisti, ki ste za meč, k meču; tisti, ki ste za lakoto, k lakoti in tisti, ki ste za ujetništvo, k ujetništvu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Nad njimi bom določil štiri vrste,‹ govori Gospod: ›meč, da ubija in pse, da trgajo ter perjad neba in zemeljske živali, da požirajo in uničujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, '§ Povzročil jim bom, da bodo odstranjeni v vsa kraljestva zemlje, zaradi Manáseja, sina Ezekíja, Judovega kralja, za to, kar je storil v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Kajti kdo bo imel usmiljenje nad teboj, oh [prestolnica] Jeruzalem? Kdo te bo obžaloval? Kdo bo šel vstran, da te vpraša, kako si?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Zapustila si me,‹ govori Gospod, ›umaknila si se nazaj. Zato bom zoper tebe iztegnil svojo roko in te uničil; izmučen sem od kesanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Vejál jih bom z vejálnikom v velikih vratih dežele; oropal jih bom otrok, uničil bom svoje ljudstvo, ker se niso vrnili iz svojih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Njihove vdove so mi [številčno] narasle nad peskom morja. Zoper mater mladeničev sem nadnje opoldan privedel plenitelja. Storil sem mu, da je nenadoma padel nanjo in strahote so padle nad mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Tista, ki jih je rodila sedem, peša. Izročila je duha. Njeno sonce je zašlo, medtem ko je bil še dan. Bila je osramočena in zmedena. Preostanek izmed njih bom izročil meču pred njihovimi sovražniki,‹« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '»Gorje meni, moja mati, da si me rodila, človeka prepira in človeka spora celotni zemlji! Niti nisem posojal za obresti niti mi ljudje niso posojali za obresti, vendar me vsakdo izmed njih preklinja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, '§ Gospod je rekel: »Resnično, dobro bo s tvojim preostankom. Resnično, povzročil bom, da bo sovražnik dobro ravnal s teboj v času zla in v času stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Se bo železo zlomilo, severno železo in jeklo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Tvoje imetje in tvoje zaklade bom izročil v plen brez cene in to za vse tvoje grehe, celo v vseh tvojih mejah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Storil ti bom, da v deželo, ki je ne poznaš, preideš s svojimi sovražniki. Kajti ogenj je vnet v moji jezi, ki bo gorel na vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Oh Gospod, ti veš. Spomni se me in me obišči in me maščuj nad mojimi preganjalci. V svoji potrpežljivosti me ne odvzemi proč. Vedi, da sem zaradi tebe trpel grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Tvoje besede so bile najdene in sem jih jedel, in tvoja beseda mi je bila radost in veselje mojega srca, kajti imenovan sem po tvojem imenu, oh Gospod, Bog nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nisem sedel v zboru zasmehovalcev niti se nisem razveseljeval; sam sem sedel zaradi tvoje roke, kajti napolnil si me z ogorčenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Zakaj je moja bolečina neprestana in moja rana, ki odklanja biti ozdravljena, nezaceljiva? Ali mi hočete biti vsi skupaj kakor lažnivec in kakor vode, ki odpovedo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Zato tako govori Gospod: »Če se spreobrneš, potem te bom ponovno privedel in boš stal pred menoj. Če odvzameš dragoceno iz hudobnega, boš kakor moja usta. Oni naj se vrnejo k tebi, toda ti se ne vrni k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Temu ljudstvu te bom naredil za ograjen bronast zid. Borili se bodo zoper tebe, toda ne bodo prevladali zoper tebe, kajti jaz sem s teboj, da te rešim in da te osvobodim,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '›Rešil te bom iz roke zlobnih in odkupil te bom iz roke strašnih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Gospodova beseda je prav tako prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '»Ne boš si vzel žene niti na tem kraju ne boš imel sinov ali hčera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Kajti tako govori Gospod glede sinov in glede hčera, ki so rojeni na tem kraju in glede njihovih mater, ki so jih nosile in glede njihovih očetov, ki so jih zaplodili v tej deželi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '›Umrli bodo bolečih smrti; ne bodo objokovani niti ne bodo pokopani, temveč bodo kakor gnoj na obličju zemlje; z mečem in lakoto bodo použiti in njihova trupla bodo hrana za perjad neba in za živali na polju.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Kajti tako govori Gospod: ›Ne vstopi v hišo žalovanja niti ne pojdi, da žaluješ niti da jih objokuješ, kajti svoj mir sem odvzel od tega ljudstva,‹ govori Gospod, › celó ljubečo skrbnost in usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Tako veliki, kakor majhni bodo umirali v tej deželi. Ne bodo pokopani, niti ljudje ne bodo žalovali za njimi, niti se rezali, niti se ne bodo zaradi njih naredili plešaste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, '§ Niti se zanje ljudje ne bodo trgali v žalovanju, da bi jih tolažili zaradi mrtvih; niti jim ljudje ne bodo dali čaše tolažbe, da bi pili za njihovega očeta ali za njihovo mater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Prav tako ne boš šel v hišo praznovanja, da sediš z njimi, da bi jedel in pil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: ›Glej, povzročil bom, da iz tega kraja, v vaših očeh in v vaših dneh, izgine glas smeha, glas veselja, glas ženina in glas neveste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'In zgodilo se bo, ko boš temu ljudstvu pokazal vse te besede in ti bodo rekli: ›Zakaj je Gospod proglasil vso to veliko zlo zoper nas? Ali kaj je naša krivda? Ali kakšen je naš greh, ki smo ga zagrešili zoper Gospoda, svojega Boga?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Potem jim boš rekel: ›Zato, ker so me vaši očetje zapustili,‹ govori Gospod ›in so hodili za drugimi bogovi, jim služili in jih oboževali, mene pa zapustili in se niso držali moje postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Vi pa ste storili slabše kakor vaši očetje. Kajti glejte, hodite vsakdo za zamislijo svojega zlobnega srca, da mi ne bi prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Zato vas bom vrgel iz te dežele v deželo, ki je ne poznate niti vi niti vaši očetje in tam boste podnevi in ponoči služili drugim bogovom, kjer vam ne bom pokazal nobene naklonjenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Zato glejte, prihajajo dnevi,‹ govori Gospod, ›da ne bo več rečeno: › Gospod živi, ki je privedel Izraelove otroke gor iz egiptovske dežele,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'temveč: › Gospod živi, ki je Izraelove otroke privedel iz severne dežele in iz vseh dežel, kamor jih je pregnal,‹ in ponovno jih bom privedel v njihovo deželo, ki sem jo dal njihovim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Glej, poslal bom po mnogo ribičev,‹ govori Gospod ›in lovili jih bodo in za njimi bom poslal mnogo lovcev in lovili jih bodo iz vsake gore in iz vsakega hriba in iz skalnih lukenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Kajti moje oči so na vseh njihovih poteh, niso skrite pred mojim obrazom niti njihova krivičnost ni skrita pred mojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Najprej bom dvojno poplačal njihovo krivičnost in njihov greh zato, ker so omadeževali mojo deželo, mojo dediščino so napolnili s trupli svojih ostudnih in gnusnih stvari.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Oh Gospod, moja moč, moja trdnjava in moje zatočišče v dnevu stiske, pogani bodo prišli k tebi od koncev zemlje in bodo rekli: »Zagotovo so naši očetje podedovali laži, ničevost in stvari, v katerih ni koristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Ali si bo človek delal bogove in le-ti niso bogovi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '»Zato, glej, tokrat bom povzročil, da bodo vedeli. Povzročil jim bom, da bodo spoznali mojo roko in mojo moč in vedeli bodo, da je moje ime Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '»Judov greh je zapisan z železnim peresom in z diamantno konico. Ta je vrezan na ploščo njihovega srca in na rogove njihovih oltarjev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'medtem ko se njihovi otroci spominjajo njihovih oltarjev in njihovih ašer pri zelenih drevesih na visokih hribih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, '§ Oh moja gora na polju, tvoje imetje in vse tvoje zaklade bom izročil v plen in tvoje visoke kraje zaradi greha, po vseh tvojih mejah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Ti pa, celo ti sam, boš odpravljen od svoje dediščine, ki sem ti jo dal in povzročil ti bom, da služiš svojim sovražnikom v deželi, ki je ne poznaš, kajti zanetili ste ogenj v moji jezi, ki bo gorel na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tako govori Gospod: »Preklet bodi človek, ki zaupa v moža in postavlja osebo [za] svoj laket in katerega srce odhaja od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Kajti podoben bo brinu v puščavi in ne bo videl, ko prihaja dobro, temveč bo naselil izsušene kraje v divjini, v slani in nenaseljeni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Blagoslovljen je človek, ki zaupa v Gospoda in čigar upanje je v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Kajti on bo kakor drevo, posajeno ob vodah in ki razširja svoje korenine ob reki in ne bo videlo, ko prihaja vročina, temveč bo njegovo listje zeleno; v sušnem letu ne bo zaskrbljeno niti ne bo prenehalo rojevati sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Srce je varljivo nad vsemi stvarmi in obupno zlobno. Kdo ga lahko spozna?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Jaz, Gospod, preiskujem srce, jaz preizkušam notranjost, celó da vsakemu človeku dam glede na njegove poti in glede na sad njegovih dejanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Kakor jerebica sedi na jajcih, ki jih ni znesla, tako tisti, ki pridobiva bogastva, pa ne po pravici, jih bo zapustil v sredi svojih dni in ob svojem koncu bo bedak.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Veličasten visok prestol od začetka je prostor našega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Oh Gospod, Izraelovo upanje, vsi, ki te zapustijo, bodo osramočeni in tisti, ki odidejo od mene, bodo zapisani v zemljo, ker so zapustili Gospoda, studenec živih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Ozdravi me, oh Gospod in jaz bom ozdravljen, reši me in jaz bom rešen, kajti ti si moja hvala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Glej, pravijo mi: »Kje je beseda od Gospoda? Naj ta sedaj pride.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Kar se mene tiče, nisem hitel pred tem, da bi bil pastir, da ti sledim. Niti si nisem želel dneva, polnega gorja; ti veš. To, kar je prišlo iz mojih ustnic, je bilo pred teboj pravilno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne bodi mi strahota. Ti si moje upanje v dnevu zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Naj bodo zbegani [tisti], ki me preganjajo, toda jaz naj ne bom zbegan. Naj bodo zaprepadeni, toda jaz naj ne bom zaprepaden. Nanje privedi dan zla in jih uniči z dvojnim uničenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tako mi je rekel Gospod: »Pojdi in stoj v velikih vratih otrok ljudstva, pri katerih Judovi kralji vstopajo in pri katerih gredo ven in v vseh jeruzalemskih velikih vratih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'in jim reci: ›Poslušajte Gospodovo besedo, vi Judovi kralji in ves Juda in vsi prebivalci Jeruzalema, ki vstopate pri teh velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tako govori Gospod: ›Pazite nase in na šabatni dan ne prenašajte nobenega bremena niti tega ne prinašajte noter pri jeruzalemskih velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Niti ne prinašajte bremena iz svojih hiš na šabatni dan niti ne počnite nobenega dela, temveč posvečujte šabatni dan, kakor sem zapovedal vašim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Toda niso ubogali niti niso nagnili svojega ušesa, temveč so otrdili svoj vrat, da ne bi niti slišali niti prejeli poučevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'In zgodilo se bo, če mi boste marljivo prisluhnili,‹ govori Gospod, ›da ne prinašate nobenega bremena skozi velika vrata tega mesta na šabatni dan, temveč posvečujete šabatni dan, da v tem [dnevu] ne delate nobenega dela,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'potem bodo tam, v velika vrata tega mesta, vstopali kralji in princi, sedeč na Davidovem prestolu, jahajoč na bojnih vozovih in konjih, oni in njihovi princi, Judovi možje in prebivalci Jeruzalema; in to mesto bo ostalo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Prišli bodo iz Judovih mest in iz krajev okoli Jeruzalema in iz Benjaminove dežele in ravnine in z gora in iz juga, prinašajoč žgalne daritve, klavne daritve, jedilne daritve in kadilo ter prinašajoč daritve hvale v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Toda če mi ne boste prisluhnili, da posvečujete šabatni dan in da ne nosite bremena, celo ko vstopate pri jeruzalemskih velikih vratih na šabatni dan, potem bom zanetil ogenj v njegovih velikih vratih in ta bo požrl jeruzalemske palače in ne bo pogašen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '»Vstani in pojdi dol k lončarjevi hiši in tam ti bom povzročil, da boš slišal moje besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Potem sem odšel dol k lončarjevi hiši in glej, izdeloval je delo na kolesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Posoda, ki jo je naredil iz ila je bila iznakažena v lončarjevi roki. Tako je še enkrat naredil drugo posodo, kakor se je lončarju zdelo dobro, da jo naredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Potem je k meni prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '»Oh Izraelova hiša, mar ne morem narediti z vami kakor ta lončar?« govori Gospod. »Glejte, kakor je ilo v lončarjevi roki, tako ste vi v moji roki, oh Izraelova hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'V kakšnem trenutku bom govoril glede naroda in glede kraljestva, da ga izruvam, poderem in uničim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Če [pa] se ta narod, zoper katerega sem proglasil, obrne od svojega zla, se bom pokesal od zla, ki sem jim ga mislil storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'V kakšnem trenutku bom govoril glede naroda in glede kraljestva, da ga zgradim in zasadim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Če [pa] dela zlo v mojem pogledu, da ne uboga mojega glasu, potem se bom pokesal dobrega, s katerim sem rekel, da bi jim koristil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Zdaj torej pojdi, govori Judovim možem in prebivalcem Jeruzalema, rekoč: ›Tako govori Gospod; ›Glejte, zoper vas oblikujem zlo in zoper vas naklepam naklep. Torej se vrnite, vsakdo iz svoje hudobne poti in naredite svoje poti in svoja dejanja dobra.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Rekli so: »Tam ni nobenega upanja, temveč bomo hodili po svojih lastnih naklepih in vsakdo izmed nas bo počel zamisel svojega zlega srca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Zato tako govori Gospod: »Vprašajte torej med pogani, kdo je slišal takšne stvari. Izraelova devica je storila zelo strašno stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Mar bo človek zapustil libanonski sneg, ki prihaja iz poljske skale? Mar bodo hladne tekoče vode, ki prihajajo iz drugega kraja, zapuščene?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Ker me je moje ljudstvo pozabilo so zažigali kadilo ničnostim in le-ti so jim storili, da se spotikajo na svojih poteh od starodavnih steza, da hodijo po stezah, na poti, ki ni nasuta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'da naredijo svojo deželo zapuščeno in neprestan posmeh; vsak, kdor gre tam mimo, bo osupel in bo zmajeval z glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Pred sovražnikom jih bom razkropil kakor z vzhodnim vetrom; pokazal jim bom hrbet in ne obraza, na dan njihove katastrofe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Potem so rekli: »Pridite in naklepajmo naklepe zoper Jeremija; kajti postava ne bo izginila od duhovnika, niti nasvet od modrega, niti beseda od preroka. Pridite in udarimo ga z jezikom in ne dajmo pozornosti katerikoli izmed njegovih besed.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Nakloni mi pozornost, oh Gospod in prisluhni glasu tistih, ki se pričkajo z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Mar bo zlo poplačilo za dobro? Kajti izkopali so jamo za mojo dušo. Spomni se, da sem stal pred teboj, da govorim dobro zanje in da odvrnem tvoj bes od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Zato njihove otroke izroči lakoti in njihovo kri izlij s silo meča; in naj bodo njihove žene oropane svojih otrok in bodo vdove; in naj bodo njihovi možje usmrčeni; naj bodo njihovi mladeniči v bitki umorjeni z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Naj bo krik slišan od njihovih hiš, ko boš nadnje nenadoma privedel krdelo, kajti izkopali so jamo, da bi me ujeli in skrili pasti za moja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Vendar, Gospod, ti poznaš vse njihove namere zoper mene, da me ubijejo. Ne odpusti njihove krivičnosti niti njihovega greha ne izbriši pred svojim pogledom, temveč naj bodo zrušeni pred teboj; tako postopaj z njimi v času svoje jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tako govori Gospod: »Pojdi in dobi si lončarjev vrč in vzemi od starcev izmed ljudstva in od starcev izmed duhovnikov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'in pojdi naprej v dolino sina Hinómovega, ki je pri vhodu vzhodnih velikih vrat in tam razglasi besede, ki ti jih bom povedal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'in reci: ›Poslušajte besedo od Gospoda, oh Judovi kralji in prebivalci Jeruzalema: ›Tako govori Gospod nad bojevniki, Izraelov Bog: ›Glejte, privedel bom zlo nad ta kraj, kdorkoli bo slišal o njem, mu bo v ušesih zvenelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Ker so me zapustili in odtujili ta kraj in na njem zažigali kadilo drugim bogovom, ki jih niti oni niti njihovi očetje niti Judovi kralji niso poznali in so ta kraj napolnili s krvjo nedolžnih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'zgradili so tudi Báalove visoke kraje, da svoje sinove sežigajo z ognjem za žgalne daritve Báalu, kar jim nisem zapovedal niti tega nisem govoril niti mi to ni prišlo na um.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Zato, glejte, pridejo dnevi,‹ govori Gospod, ›ko ta kraj ne bo več imenovan Tofet niti Dolina sina Hinómovega, temveč Dolina pokola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Nasvet Juda in Jeruzalema bom na tem kraju naredil prazen in povzročil jim bom, da padejo pod mečem pred svojimi sovražniki in po rokah tistih, ki jim strežejo po življenju. Njihova trupla bom izročil, da bodo hrana perjadi neba in zemeljskim zverem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'To mesto bom naredil zapuščeno in sikanje. Vsak, kdor bo šel mimo, bo osupel in sikal zaradi vseh njegovih nadlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Povzročil jim bom, da jedo meso svojih sinov in meso svojih hčera in vsak bo jedel meso svojega prijatelja, v obleganju in strogosti, s katero jih bodo stisnili njihovi sovražniki in tisti, ki jim strežejo po življenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Potem boš razbil vrč pred očmi mož, ki gredo s teboj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'in jim boš rekel: ›Tako govori Gospod nad bojevniki: ›Celo tako bom zlomil to ljudstvo in to mesto, kakor nekdo razbija lončarjevo posodo, da ne more biti narejena ponovno cela. Pokopavali jih bodo v Tofetu, dokler ne bo nobenega prostora za pokop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tako bom storil temu kraju,‹ govori Gospod ›in njegovim prebivalcem in to mesto bom naredil celó kot Tofet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Hiše Jeruzalema in hiše Judovih kraljev bodo omadeževane kakor kraj Tofet, zaradi vseh hiš, na čigar strehah so zažigali kadilo vsej vojski neba in izlivali pitne daritve drugim bogovom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Potem je iz Tofeta prišel Jeremija, kamor ga je poslal Gospod, da prerokuje. Stopil je na dvor Gospodove hiše in vsemu ljudstvu rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '»Tako govori Gospod nad bojevniki, Izraelov Bog: ›Glejte, nad to mesto in nad vse njegove kraje bom privedel vse zlo, ki sem ga proglasil zoper njega, ker so otrdili svoje vratove, da ne bi slišali mojih besed.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Torej Pašhúr, Imêrjev sin, duhovnik, ki je bil tudi glavni voditelj v Gospodovi hiši, je slišal, da je Jeremija prerokoval te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Potem je Pašhúr udaril preroka Jeremija in ga vtaknil v klade, ki so bile pri Benjaminovih visokih velikih vratih, ki so bila pri Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Naslednji dan se je pripetilo, da je Pašhúr privedel Jeremija iz klad. Potem mu je Jeremija rekel: » Gospod tvojega imena ne imenuje Pašhúr, temveč Magor misabib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Kajti tako govori Gospod: ›Glej, naredil te bom sebi in vsem tvojim prijateljem za strahoto. Ti bodo padli pod mečem svojih sovražnikov in tvoje oči bodo to gledale in celotnega Juda bom izročil v roko babilonskega kralja in ta jih bo odvedel ujete v Babilon in jih umoril z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Poleg tega bom izročil vso moč tega mesta, vse njegove trude, vse njegove dragocene stvari in vse zaklade Judovih kraljev bom dal v roko njihovih sovražnikov, ki jih bodo oplenili, jih vzeli in jih odnesli v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ti, Pašhúr in vsi, ki prebivate v tvoji hiši, boste šli v ujetništvo. Prišel boš v Babilon in tam boš umrl in tam boš pokopan, ti in vsi tvoji prijatelji, katerim si prerokoval laži.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Oh Gospod, zavedel si me in bil sem zaveden. Močnejši si kakor jaz in si prevladal. Vsak dan sem v posmeh, vsakdo me zasmehuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Kajti odkar sem govoril, sem vpil, razglašal nasilje in plen, ker mi je bila Gospodova beseda vsak dan narejena [v] grajo in posmeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Potem sem rekel: »Ne bom ga omenjal niti ne bom več govoril v njegovem imenu.« Toda njegova beseda je bila v mojem srcu kakor goreč ogenj, zaprta v mojih kosteh, jaz pa sem bil izmučen od prizanašanja in nisem mogel ostati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Kajti slišal sem psovanje mnogih, strah na vsaki strani. »Ovadite,« so rekli »in ovadili bomo.« Vsi moji znanci so opazovali moje oklevanje, rekoč: »Morda bo premamljen in bomo prevladali zoper njega in svoje maščevanje bomo izvedli nad njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Toda Gospod je z menoj kakor mogočen strahovitež. Zato se bodo moji preganjalci spotaknili in ne bodo prevladali. Silno bodo osramočeni, kajti ne bodo uspeli. Njihova večna zmeda ne bo nikoli pozabljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Toda, oh Gospod nad bojevniki, ki preizkušaš pravične in vidiš notranjosti in srce, naj vidim tvoje maščevanje na njih, kajti tebi sem odprl svojo pravdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Prepevajte Gospodu, hvalite Gospoda, kajti dušo ubogega je osvobodil pred roko hudodelcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Preklet bodi dan, na katerega sem bil rojen. Naj ne bo blagoslovljen dan, na katerega me je moja mati rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Preklet bodi človek, ki je prinesel novice mojemu očetu, rekoč: »Fantek se ti je rodil,« in ga tako naredil zelo veselega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Naj bo ta človek kakor mesta, ki jih je Gospod razdejal in se ni pokesal. Naj sliši jok zjutraj in vriskanje opoldan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'ker me ni usmrtil od maternice; ali da bi bila moja mati moj grob in njena maternica vedno obilna z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Zakaj sem prišel ven iz maternice, da vidim trud in bridkost, da bi bili moji dnevi použiti s sramoto?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, ko je kralj Sedekíja k njemu poslal Malkijájevega sina Pašhúrja in duhovnika Cefanjája, Maasejájevega sina, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '»Poizvedi, prosim te za nas od Gospoda, kajti babilonski kralj Nebukadnezar pripravlja vojno zoper nas; če bo tako, da bo Gospod postopal z nami glede na vsa njegova čudovita dela, da bo ta lahko odšel od nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Potem jim je Jeremija rekel: »Tako boste rekli Sedekíju:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, '›Tako govori Gospod, Izraelov Bog: ›Glejte, nazaj bom obrnil bojna orožja, ki so v vaših rokah, s katerimi se borite zoper babilonskega kralja in zoper Kaldejce, ki vas oblegajo zunaj obzidij in jih zbral v sredi tega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Jaz sam se bom z iztegnjeno roko boril proti vam in z močnim laktom, celó v jezi in v razjarjenosti in v velikem besu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Udaril bom prebivalce tega mesta, tako ljudi in živali. Umrli bodo od velike kužne bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Potem,‹ govori Gospod, ›bom izročil Judovega kralja Sedekíja in njegove služabnike in ljudstvo in tiste, ki so preostali v tem mestu od kužne bolezni, od meča in od lakote, v roko babilonskega kralja Nebukadnezarja in v roko njihovih sovražnikov in v roko tistih, ki jim strežejo po življenju in ta jih bo udaril z ostrino meča; ne bo jim prizanesel niti ne bo imel sočutja niti usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Temu ljudstvu boš rekel: ›Tako govori Gospod: ›Glejte, pred vas sem postavil pot življenja in pot smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Kdor ostaja v tem mestu, bo umrl pod mečem, od lakote in od kužne bolezni. Toda kdor gre ven in pobegne h Kaldejcem, ki vas oblegajo, bo živel in mu bo njegovo življenje za plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Kajti svoj obraz sem naravnal zoper to mesto v zlo in ne v dobro,‹ govori Gospod; ›le-to bo dano v roko babilonskega kralja in požgal ga bo z ognjem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Glede hiše Judovega kralja reci: ›Poslušajte Gospodovo besedo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, '›Oh Davidova hiša,‹ tako govori Gospod: ›Izvršujte sodbo zjutraj in osvobodite tega, ki je oplenjen, iz roke zatiralca, da ne bi moja razjarjenost odšla ven kakor ogenj in gorela, da tega nihče ne more pogasiti zaradi zla vaših početij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Glej, jaz sem zoper tebe, oh prebivalec doline in skala ravnine,‹ govori Gospod, ›ki praviš: ›Kdo bo prišel dol zoper nas? Ali kdo bo vstopil v naša prebivališča?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Toda kaznoval vas bom glede na sad vaših dejanj,‹ govori Gospod ›in jaz bom vnel ogenj v njegovem gozdu in ta bo požrl vse stvari naokoli njega.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tako govori Gospod: »Pojdi dol k hiši Judovega kralja in tam spregovori to besedo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'in reci: ›Poslušaj besedo od Gospoda, oh Judov kralj, ki sediš na Davidovem prestolu, ti in tvoji služabniki in tvoje ljudstvo, ki vstopate pri teh velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tako govori Gospod: ›Izvršujte sodbo in pravičnost ter oplenjenega osvobodite iz roke zatiralca. Ne delajte napačno, ne delajte nasilja tujcu [niti] osirotelemu niti vdovi niti ne prelivajte nedolžne krvi na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Kajti če zares storite to stvar, potem bodo tam, pri velikih vratih te hiše, vstopali kralji, sedeči na Davidovem prestolu, jahajoči na bojnih vozovih in na konjih, on, njegovi služabniki in njegovo ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Toda če ne boste poslušali teh besed, prisežem pri sebi,‹ govori Gospod, ›da bo ta hiša postala opustošenje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Kajti tako govori Gospod kraljevi hiši Juda: ›Ti si mi Gileád in glava Libanona, vendar te bom zagotovo spremenil [v] divjino in mesta, ki niso naseljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Zoper tebe bom pripravil uničevalce, vsakogar s svojimi orožji. Posekali bodo tvoje izbrane cedre in jih vrgli v ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Številni narodi bodo šli mimo tega mesta in vsak človek bo rekel svojemu sosedu: ›Zakaj je Gospod tako storil temu velikemu mestu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Potem bodo odgovorili: ›Ker so zapustili zavezo Gospoda, svojega Boga in oboževali druge bogove ter jim služili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne jokajte za mrtvim niti ga ne objokujte, temveč boleče jokajte za tistim, ki gre proč, kajti ne bo se več vrnil niti ne bo videl svoje domače dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Kajti tako govori Gospod glede Jošíjevega sina Šalúma, Judovega kralja, ki je zakraljeval namesto svojega očeta Jošíja, ki je odšel iz tega kraja: ›Tja se ne bo več vrnil,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'temveč bo umrl na kraju, kamor so ga odvedli v ujetništvo in ne bo več videl te dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Gorje tistemu, ki svojo hišo gradi z nepravičnostjo in svoje sobe s krivico; ki brez plačil uporablja pomoč svojega soseda in mu ne daje za njegovo delo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'ki pravi: ›Zgradil si bom široko hišo in velike sobe‹ in si izreže okna; in ta je obložena s cedrovino in pobarvana z živo rdečo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Mar boš kraljeval, ker se zapiraš s cedrovino? Mar ni tvoj oče jedel, pil, izvajal sodbo in pravico in je bilo potem dobro z njim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Sodil je primer revnega in pomoči potrebnega; tedaj je bilo dobro z njim. Ali ni bilo to poznati mene?‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Toda tvoje oči in tvoje srce sta zgolj za tvojo pohlepnost, za prelivanje nedolžne krvi, za zatiranje in za nasilje, da ga počneš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Zato tako govori Gospod glede Jojakíma, Jošíjevega sina, Judovega kralja: ›Ne bodo žalovali za njim, rekoč: ›Ah, moj brat!‹ ali ›Ah, sestra.‹ Ne bodo žalovali za njim, rekoč: ›Ah, gospod!‹ ali ›Ah, njegova slava!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Pokopan bo s pokopom osla, povlečen in vržen bo naprej onkraj velikih vrat [prestolnice] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, '§ Pojdi gor na Libanon in jokaj; povzdigni svoj glas v Bašánu in jokaj iz prehodov, kajti vsi tvoji ljubimci so uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Govoril sem ti v tvojem uspevanju, toda praviš: ›Ne bom poslušala.‹ To je bil tvoj način od tvoje mladosti, da ne ubogaš mojega glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Veter bo pojedel vse tvoje pastirje in tvoji ljubimci bodo šli v ujetništvo. Potem boš zagotovo osramočena in zbegana zaradi vse svoje zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Oh prebivalec Libanona, ki delaš svoje gnezdo na cedrah, kako pomilovanja vreden boš, ko pridejo nadte ostre bolečine, bolečina kakor ženski v porodnih mukah!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Kakor jaz živim,‹ govori Gospod ›čeprav bi bil Konija, sin Jojahína, Judovega kralja, za pečat na moji desnici, bi te vendar od tam izruval');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'in te izročil v roko tistih, ki ti strežejo po življenju in v roko tistih, katerih obraza se bojiš, celo v roko babilonskega kralja Nebukadnezarja in v roko Kaldejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Vrgel te bom ven in tvojo mater, ki te je nosila, v drugo deželo, kjer nista bila rojena, in tam bosta umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Toda v deželo, kamor se želita vrniti, tja se ne bosta vrnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ali je ta mož Konija preziran, polomljen malik? Ali je on posoda, v kateri ni zadovoljstva? Zakaj so izvrženi, on in njegovo seme in so vrženi v deželo, ki je ne poznajo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Oh zemlja, zemlja, zemlja, poslušaj Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tako govori Gospod: ›Zapiši tega moža brez otrok, moža, ki ne bo uspeval v svojih dneh, kajti noben mož iz njegovega semena ne bo uspeval, sedeč na Davidovem prestolu in ne bo več vladal v Judu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '»›Gorje pastirjem, ki uničujejo in razganjajo ovce mojega pašnika!‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Zato tako govori Gospod, Izraelov Bog, zoper pastirje, ki pasejo moje ljudstvo: ›Razkropili ste moj trop in jih odgnali proč in jih niste obiskovali. Glejte, na vas bom obiskal zlo vaših dejanj,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Zbral bom preostanek svojega tropa iz vseh dežel, kamor sem jih pognal in ponovno jih bom privedel k njihovim stajam; in bodo plodne in se množile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Postavil bom pastirje nad njimi, ki jih bodo pasli, in ne bodo se več bale niti bile prestrašene niti ne bodo trpele pomanjkanja,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, '›Glej, prihajajo dnevi,‹ govori Gospod ›ko bom Davidu vzdignil pravično Mladiko in Kralj bo vladal in uspeval in na zemlji bo izvajal sodbo in pravico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'V njegovih dneh bo Juda rešen in Izrael bo varno prebival. To je njegovo ime, s katerim bo imenovan: GOSPOD, NAŠA PRAVIČNOST.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Zato, glejte, prihajajo dnevi,‹ govori Gospod, ›ko ne bodo več rekli: › Gospod živi, ki je Izraelove otroke privedel gor iz egiptovske dežele,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'temveč › Gospod živi, ki jih je privedel gor in ki je vodil seme Izraelove hiše iz severne dežele in iz vseh dežel, kamor sem jih pognal; in prebivali bodo v svoji lastni deželi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Moje srce znotraj mene je zlomljeno zaradi prerokov, vse moje kosti se tresejo. Podoben sem pijanemu človeku in podoben človeku, ki ga je vino premagalo, zaradi Gospoda in zaradi besed njegove svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, '»Kajti dežela je polna zakonolomcev, kajti zaradi priseganja dežela žaluje. Prijetni kraji divjine so se posušili in njihova smer je zlo in njihova moč ni prava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Kajti tako prerok kakor duhovnik sta oskrunjena; da, v svoji hiši sem našel njuno zlobnost,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Zato jim bo njihova pot kakor spolzke poti v temi, pognani bodo naprej in padli na njej, kajti zlo bom privedel nadnje, celó leto njihovega obiskanja,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Videl sem nespametnost pri samarijskih prerokih. Prerokovali so pri Báalu in mojemu ljudstvu Izraelu povzročili, da zaide na kriva pota.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Tudi pri jeruzalemskih prerokih sem videl strašno stvar: zagrešujejo zakonolomstvo in hodijo v lažeh. Prav tako krepijo roke hudodelcem, da se nihče ne vrne od svoje zlobnosti. Vsi so mi kakor Sódoma in njeni prebivalci kakor Gomóra.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Zato tako govori Gospod nad bojevniki glede prerokov: »Glej, hranil jih bom s pelinom in jih pripravil piti vodo iz žolča, kajti od jeruzalemskih prerokov je izšla oskrunjenost po vsej deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tako govori Gospod nad bojevniki: »Ne poslušajte besed prerokov, ki vam prerokujejo. Delajo vas domišljave, govorijo videnje iz svojega lastnega srca in ne iz Gospodovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Tem, ki me prezirajo, nenehno pravijo: ›GOSPOD je rekel: ›Imeli boste mir;‹‹ in vsakomur, ki hodi po zamisli svojega lastnega srca, pravijo: ›Nobeno zlo ne bo prišlo nad vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Kajti kdo je stal na posvetovanju pri Gospodu in zaznal ter slišal njegovo besedo? Kdo je opazil njegovo besedo in jo slišal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Glej, vrtinčast veter od Gospoda je v razjarjenosti šel naprej, celo bridek vrtinčast veter; ta bo bridko padel na glavo zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Jeza od Gospoda se ne bo vrnila, dokler ne izvrši in dokler ne izvede misli njegovega srca. V zadnjih dneh boste to popolno preudarili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Teh prerokov nisem pošiljal, vendar tečejo; nisem jim govoril, vendar so prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Toda če bi stali na mojem posvetu in storili mojemu ljudstvu, da sliši moje besede, potem bi jih obrnili iz njihovih zlih poti in od zla njihovih početij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Ali sem jaz Bog pri roki,« govori Gospod »in ne Bog daleč proč?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Ali se lahko kdo skrije na skrivnih krajih, da bi ga jaz ne videl?« govori Gospod. »Mar ne napolnjujem neba in zemlje?« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, '»Slišal sem kaj so rekli preroki, ki v mojem imenu prerokujejo laži, rekoč: ›Sanjalo se mi je, sanjalo se mi je.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Doklej bo to v srcu prerokov, ki prerokujejo laži? Da, oni so preroki prevare svojega lastnega srca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'ki mislijo, da bi mojemu ljudstvu povzročili, da pozabi moje ime s svojimi sanjami, ki jih oni govorijo vsak mož svojemu sosedu, kakor so njihovi očetje pozabili moje ime zaradi Báala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prerok, ki ima sanje, naj ta pripoveduje sanje in kdor ima mojo besedo, naj zvesto govori mojo besedo. Kaj je plevel v primerjavi s pšenico?« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, '» Mar ni moja beseda kakor ogenj?« govori Gospod, »in kakor kladivo, ki razbija skalo na koščke?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Zato glej, jaz sem zoper preroke,« govori Gospod, »ki kradejo moje besede, vsakdo od svojega soseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Glej, jaz sem zoper preroke,« govori Gospod, »ki uporabljajo svoje jezike in govorijo: ›On pravi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, '§ Glej, jaz sem zoper tiste, ki prerokujejo lažne sanje,« govori Gospod » in jih pripovedujejo in mojemu ljudstvu povzročajo, da s svojimi lažmi in s svojo lahkomiselnostjo zaide s svojih poti, vendar jih nisem jaz poslal niti jim zapovedal, zato sploh ne bodo koristili temu ljudstvu,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, '»In ko te bo to ljudstvo ali prerok ali duhovnik, vprašalo, rekoč: ›Kaj je breme od Gospoda?‹ jim boš potem rekel: ›Kakšno breme? Jaz vas bom celo zapustil,‹« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, '»In kar se tiče preroka, duhovnika in ljudstva, ki bodo rekli: ›Breme od Gospoda,‹ jaz bom celo kaznoval tistega moža in njegovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Tako boste govorili vsak svojemu sosedu in vsak svojemu bratu: ›Kaj je Gospod odgovoril?‹ in ›Kaj je Gospod govoril?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Gospodovega bremena pa ne boste več omenjali, kajti vsakogar beseda bo njegovo breme, kajti sprevračali ste besede živega Boga, Gospoda nad bojevniki, našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tako boš govoril preroku: ›Kaj ti je Gospod odgovoril?‹ in ›Kaj je rekel Gospod?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Toda ker pravite: ›Breme od Gospoda;‹« zato tako govori Gospod, »Ker pravite to besedo: ›Breme od Gospoda ‹ in sem jaz poslal k vam, rekoč: ›Ne boste rekli: ›Breme od Gospoda;‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'zato glejte, jaz, celo jaz, vas bom popolnoma pozabil in zapustil vas in mesto, ki sem ga dal vam in vašim očetom in vas vrgel iz svoje prisotnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'in nad vas bom privedel večno grajo in neprestano sramoto, ki ne bo pozabljena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Gospod mi je pokazal in glej, dve košari fig sta bili postavljeni pred Gospodovim templjem, potem ko je babilonski kralj Nebukadnezar odvedel ujetništvo Jehoníja, sina Jojakíma, Judovega kralja in Judove prince s tesarji in kovači iz Jeruzalema in jih privedel v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Ena košara je imela zelo dobre fige, celó kakor fige, ki so najprej zrele, druga košara pa je imela zelo nespodobne fige, ki se niso mogle jesti, tako slabe so bile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Potem mi je Gospod rekel: »Kaj vidiš Jeremija?« Rekel sem: »Fige, dobre fige, zelo dobre in slabe ter zelo slabe, ki ne morejo biti pojedene, tako slabe so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '»Tako govori Gospod, Izraelov Bog: ›Podobno kot te dobre fige, tako bom priznal tiste, ki so odvedeni v ujetništvo od Juda, ki sem jih poslal ven iz tega kraja, v deželo Kaldejcev, v njihovo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Kajti svoje oči bom naravnal nanje v dobro in jih ponovno privedel v to deželo. Pozidal jih bom in jih ne podiral, jih sadil in ne ruval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Dal jim bom srce, da me spoznajo, da jaz sem Gospod. In oni bodo moje ljudstvo in jaz bom njihov Bog, kajti k meni se bodo vrnili s svojim celotnim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Kakor slabe fige, ki se ne morejo jesti, tako so slabe;‹ zagotovo tako govori Gospod: ›Tako bom izročil Judovega kralja Sedekíja, njegove prince in Jeruzalemov preostanek, ki preostane v tej deželi in tiste, ki prebivajo v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Izročil jih bom, da bodo odstranjeni v vsa zemeljska kraljestva, v njihovo škodo, da bodo graja in pregovor, zbadljivka in prekletstvo, na vseh krajih, kamor jih bom pognal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Mednje bom poslal meč, lakoto in kužno bolezen, dokler ne bodo použiti iz dežele, ki sem jo dal njim in njihovim očetom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Beseda, ki je prišla Jeremiju glede vsega Judovega ljudstva, v četrtem letu Jojakíma, Jošíjevega sina, Judovega kralja, kar je bilo prvo leto babilonskega kralja Nebukadnezarja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'ki jo je prerok Jeremija govoril vsemu Judovemu ljudstvu in vsem prebivalcem Jeruzalema, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, '»Od trinajstega leta Jošíja, Amónovega sina, Judovega kralja, celo do današnjega dne, to je triindvajsetega leta, je prišla k meni Gospodova beseda in govoril sem vam, vzdigujoč se zgodaj in govoril; toda niste prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Gospod je pošiljal k vam vse svoje služabnike preroke, vzdigujoč jih zgodaj in jih pošiljal; toda niste prisluhnil niti nagnili svojega ušesa, da bi prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Rekli so: ›Sedaj se ponovno obrnite, vsakdo iz svoje zle poti in od hudobije svojih dejanj in prebivajte v deželi, ki jo je Gospod dal vam in vašim očetom na veke vekov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'in ne hodite za drugimi bogovi, da jim služite in da jih obožujete in ne dražite me do jeze z deli svojih rok, in vam ne bom storil nobene škode.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Vendar mi niste prisluhnili,‹ govori Gospod; ›da bi me lahko dražili do jeze z deli svojih rok v svojo lastno škodo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Zato tako govori Gospod nad bojevniki: ›Ker niste poslušali mojih besed,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'glejte, poslal bom in vzel vse družine iz severa,‹ govori Gospod ›in babilonskega kralja Nebukadnezarja, mojega služabnika in privedel jih bom zoper to deželo in zoper njene prebivalce in zoper vse te narode naokoli in popolnoma jih bom uničil in jih naredil osuplost in posmeh in neprestana opustošenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Poleg tega bom od njih odvzel glas smeha in glas veselja, glas ženina in glas neveste, zvok mlinskih kamnov in svetlobo sveče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'In ta celotna dežela bo opustošenje in osuplost; in ti narodi bodo sedemdeset let služili babilonskemu kralju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Ko pa se dopolni sedemdeset let, se bo zgodilo, da bom kaznoval babilonskega kralja in ta narod,‹ govori Gospod, ›zaradi njihove krivičnosti in deželo Kaldejcev in naredil jo bom za neprestana opustošenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Nad to deželo bom privedel vse svoje besede, ki sem jih proglasil zoper njo, celó vse, kar je zapisano v tej knjigi, ki jo je Jeremija prerokoval zoper vse narode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Kajti tudi številni narodi in veliki kralji izmed njih jim bodo služili. Poplačal jim bom glede na njihova dejanja in glede na dela njihovih lastnih rok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Kajti tako mi govori Gospod, Izraelov Bog: »Vzemi vinsko čašo te razjarjenosti pri moji roki in vsem narodom, h katerim te pošiljam, povzroči, da jo pijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Pili bodo in bodo omajani in zmešani zaradi meča, ki ga bom poslal mednje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Potem sem vzel čašo pri Gospodovi roki in vsem narodom, h katerim me je Gospod poslal, sem dal, da pijejo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'namreč Jeruzalemu in Judovim mestom, njihovim kraljem in njihovim princem, da jih naredim za opustošenje, osuplost, posmeh in prekletstvo; kakor je to ta dan;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'faraonu, egiptovskemu kralju, njegovim služabnikom, njegovim princem in vsemu njegovemu ljudstvu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'vsemu pomešanemu ljudstvu in vsem kraljem dežele Uc, vsem kraljem dežele Filistejcev, Aškelónu, Gazi, Ekrónu, preostanku iz Ašdóda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edómu, Moábu in Amónovim sinovom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'vsem tirskim kraljem, vsem sidónskim kraljem in kraljem otokov, ki so onstran morja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, '§ Dedánu, Temáju, Buzu in vsem, ki so na skrajnih vogalih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'in vsem kraljem Arabije in vsem kraljem pomešanega ljudstva, ki prebivajo v puščavi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'in vsem kraljem v Zimríju in vsem kraljem v Elámu in vsem kraljem v Mediji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'in vsem kraljem na severu, daleč in blizu, enega z drugim in vsem kraljestvom sveta, ki so na obličju zemlje; in kralj Šešáha bo pil za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Zatorej jim boš rekel: »Tako govori Gospod nad bojevniki, Izraelov Bog: ›Pijte, bodite pijani, bljuvajte, padite in ne vstanite več zaradi meča, ki ga bom poslal med vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'In zgodilo se bo, če odklonijo vzeti čašo iz tvoje roke, da pijejo, potem jim boš rekel: ›Tako govori Gospod nad bojevniki: ›Zagotovo boste pili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Kajti, glejte, začenjam prinašati zlo na mesto, ki je imenovano z mojim imenom in ali naj bi bili vi popolnoma nekaznovani? Ne boste nekaznovani, kajti poklical bom meč nad vse prebivalce zemlje,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Zato prerokuj zoper njih vse te besede in jim reci: › Gospod bo rjovel iz višine in izustil svoj glas iz svojega svetega prebivališča; mogočno bo rjovel nad svojim prebivališčem; zavpil bo kakor tisti, ki tlači grozdje, zoper vse prebivalce zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Hrup bo prišel celó do koncev zemlje, kajti Gospod ima pravdo z narodi, pravdal se bo z vsem mesom; te, ki so zlobni, bo izročil meču,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tako govori Gospod nad bojevniki: ›Glej, zlo bo šlo naprej od naroda do naroda in od zemeljskih obal se bo dvignil velik vrtinčast veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Umorjeni od Gospoda bodo na ta dan od enega konca zemlje do drugega konca zemlje. Ne bodo objokovani niti zbrani niti pokopani; za gnoj bodo na tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Tulite pastirji in jokajte; valjajte se v pepelu vodje tropa, kajti dnevi vašega klanja in vaših razpršenosti so dovršeni; padli boste kakor prijetna posoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Pastirji ne bodo imeli nobene poti, da bežijo niti glavni od tropa, da pobegnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Slišati bo glas vpitja pastirjev in tuljenje vodje tropa, kajti Gospod je oplenil njihov pašnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Miroljubna prebivališča so posekana zaradi Gospodove krute jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Zapustil je svoje skrivališče kakor lev, kajti njihova dežela je zapuščena zaradi okrutnosti zatiralca in zaradi njegove krute jeze.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Na začetku kraljevanja Jojakíma, Jošíjevega sina, Judovega kralja, je prišla ta beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, '»Tako govori Gospod: ›Stoj na dvoru Gospodove hiše in govori vsem Judovim mestom, ki pridejo oboževat v Gospodovo hišo, vse besede, ki sem ti jih zapovedal, da jim jih govoriš; ne zmanjšaj niti besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Če bo tako, bodo prisluhnili in se obrnili, vsak človek iz svoje zle poti, da se lahko pokesam od zla, ki sem jim ga namenil storiti zaradi zla njihovih početij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Rekel jim boš: ›Tako govori Gospod: ›Če mi ne boste prisluhnili, da se ravnate po moji postavi, ki sem jo postavil pred vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'da prisluhnete besedam mojih služabnikov prerokov, ki sem jih pošiljal k vam; zgodaj sem jih vzdigoval in jih pošiljal, toda niste prisluhnili;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'potem bom to hišo naredil podobno Šilu in to mesto naredil prekletstvo vsem narodom zemlje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Tako so duhovniki, preroki in vse ljudstvo slišali Jeremija govoriti te besede v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Pripetilo se je torej, ko je Jeremija končal govorjenje vsega, kar mu je Gospod zapovedal, da govori vsemu ljudstvu, da so ga duhovniki in preroki in vse ljudstvo zgrabili, rekoč: »Zagotovo boš umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Zakaj si prerokoval v Gospodovem imenu, rekoč: ›Ta hiša bo podobna Šilu in to mesto bo zapuščeno, brez prebivalca?‹« In vse ljudstvo je bilo zbrano zoper Jeremija v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Ko so Judovi princi slišali te stvari, potem so prišli gor iz kraljeve hiše h Gospodovi hiši in se usedli pri vhodu novih velikih vrat Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Potem so duhovniki in preroki spregovorili princem in vsemu ljudstvu, rekoč: »Ta mož je vreden, da umre, kajti prerokoval je zoper to mesto, kakor ste slišali s svojimi ušesi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Potem je Jeremija spregovoril vsem princem in vsemu ljudstvu, rekoč: » Gospod me je poslal, da prerokujem zoper to hišo in zoper to mesto vse besede, ki ste jih slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Zato sedaj poboljšajte svoje poti in svoja dejanja in ubogajte glas Gospoda, svojega Boga, in Gospod se bo pokesal od zla, ki ga je proglasil zoper vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Poglejte, kar se mene tiče, jaz sem v vaši roki. Z menoj storite kakor se vam zdi dobro in primerno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Toda zagotovo vedite, da če me boste usmrtili, boste zagotovo privedli nedolžno kri nadse, nad to mesto in nad njegove prebivalce, kajti resnično me je k vam poslal Gospod, da v vaša ušesa govorim vse te besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Potem so princi in vse ljudstvo rekli duhovnikom in prerokom: »Ta mož ni vreden, da umre, kajti govoril nam je v imenu Gospoda, našega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Potem so vstali nekateri izmed starešin dežele in spregovorili vsemu zboru ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '»Mihej Moréšečan je prerokoval v dneh Ezekíja, Judovega kralja in govoril vsemu Judovemu ljudstvu, rekoč: ›Tako govori Gospod nad bojevniki: ›Sion bo preoran kakor polje in Jeruzalem bo spremenjen v razvaline in gora hiše kakor visoki kraji gozda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Ali ga je Judov kralj Ezekíja in ves Juda sploh dal usmrtiti? Mar se ni bal Gospoda in rotil Gospoda in se je Gospod pokesal zla, ki ga je proglasil zoper njih? Tako bi lahko prihranili veliko zlo zoper naše duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Tam pa je bil tudi človek, ki je prerokoval v Gospodovem imenu, Urijá, sin Šemajája iz Kirját Jearíma, ki je prerokoval zoper to mesto in zoper to deželo, glede na vse Jeremijeve besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Ko je kralj Jojakím, z vsemi svojimi mogočnimi možmi in vsemi princi, slišal njegove besede, je kralj iskal, da ga usmrti. Toda ko je Urijá to slišal, je bil prestrašen in pobegnil ter odšel v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Kralj Jojakím pa je poslal može v Egipt, in sicer Ahbórjevega sina Elnatána in nekatere može z njim v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Ti so Urijá spravili iz Egipta in ga privedli h kralju Jojakímu, ki ga je usmrtil z mečem in njegovo truplo vrgel v grobove preprostega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Kljub temu je bila roka Šafánovega sina Ahikáma z Jeremijem, da ga ne bi predali v roko ljudstva, da ga usmrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Na začetku kraljevanja Jojakíma, Jošíjevega sina, Judovega kralja, je prišla Jeremiju ta beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, '»Tako mi govori Gospod: ›Naredi si vezi in jarme in si jih položi na svoj vrat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'in jih pošlji edómskemu kralju, moábskemu kralju, amónskemu kralju, tirskemu kralju in k sidónskemu kralju, po roki poslancev, ki so prišli v Jeruzalem k Judovemu kralju Sedekíju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'in jim zapovej, da rečejo svojim gospodarjem: ›Tako govori Gospod nad bojevniki, Izraelov Bog: ›Tako boste rekli svojim gospodarjem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, '›Jaz sem naredil zemljo, človeka in živali, ki so na zemlji, s svojo veliko močjo in s svojim razširjenim laktom in izročil sem jo, komur se je meni zdelo primerno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Sedaj sem vse te dežele dal v roko svojega služabnika, babilonskega kralja Nebukadnezarja in tudi živali polja sem mu izročil, da mu služijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, '§ Vsi narodi bodo služili njemu, njegovemu sinu in sinu njegovega sina, dokler ne pride pravi čas njegove dežele, potem pa ga bodo zasužnjili mnogi narodi in veliki kralji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'In zgodilo se bo, da narodi in kraljestva, ki ne bodo služili istemu babilonskemu kralju Nebukadnezarju in ki svojega vratu ne bodo položili pod jarem babilonskega kralja, da bom ta narod kaznoval,‹ govori Gospod, ›z mečem in z lakoto in s kužno boleznijo, dokler jih ne použijem s svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Zato ne prisluhnite niti svojim prerokom, niti vedeževalcem, niti sanjačem, niti uročevalcem, niti svojim čarodejem, ki vam govorijo, rekoč: ›Ne boste služili babilonskemu kralju,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'kajti prerokujejo vam laž, da bi vas odstranili daleč od vaše dežele; in da bi vas jaz izgnal in bi se vi pogubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Toda narodi, ki svoj vrat privedejo pod jarem babilonskega kralja in mu služijo, tiste bom pustil ostati mirne v njihovi lastni deželi,‹ govori Gospod; ›in obdelovali jo bodo in prebivali v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Tudi Judovemu kralju Sedekíju sem spregovoril glede na vse te besede, rekoč: ›Privedi vaše vratove pod jarem babilonskega kralja in služite njemu in njegovemu ljudstvu in živite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Zakaj bi umirali ti in tvoje ljudstvo, pod mečem, z lakoto in kužno boleznijo, kakor je Gospod govoril zoper narod, ki ne bo služil babilonskemu kralju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Zato ne prisluhnite besedam prerokov, ki vam govorijo, rekoč: ›Ne boste služili babilonskemu kralju,‹ kajti laž vam prerokujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Kajti jaz jih nisem poslal,‹ govori Gospod, ›vendar v mojem imenu prerokujejo laž; da bi vas jaz lahko izgnal ven in bi se pogubili, vi in preroki, ki vam prerokujejo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Govoril sem tudi duhovnikom in vsemu temu ljudstvu, rekoč: »Tako govori Gospod: ›Ne prisluhnite besedam svojih prerokov, ki vam prerokujejo, rekoč: ›Glejte, posode Gospodove hiše bodo sedaj v kratkem ponovno privedene nazaj iz Babilona,‹ kajti prerokujejo vam laž.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne prisluhnite jim. Služite babilonskemu kralju in živite. Zakaj bi bilo to mesto opustošeno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Toda če bi bili preroki in bi bila Gospodova beseda z njimi, naj sedaj naredijo posredovanje h Gospodu nad bojevniki, da posode, ki so ostale v Gospodovi hiši in v hiši Judovega kralja in v Jeruzalemu, ne gredo v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Kajti tako govori Gospod nad bojevniki glede stebrov, glede morja, glede podnožij in glede preostanka posod, ki preostajajo v tem mestu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'ki jih babilonski kralj Nebukadnezar ni vzel, ko je odvedel proč v ujetništvo Jehoníja, Jojakímovega sina, Judovega kralja, iz Jeruzalema v Babilon in vse plemiče iz Juda in Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Da, tako govori Gospod nad bojevniki, Izraelov Bog, glede posod, ki so ostale v Gospodovi hiši in v hiši Judovega in jeruzalemskega kralja:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'odnesene bodo v Babilon in tam bodo do dneva, ko jih obiščem,‹ govori Gospod, ›potem jih bom privedel gor in jih ponovno vrnil na ta kraj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Pripetilo se je isto leto, v začetku kraljevanja Judovega kralja Sedekíja, v četrtem letu in v petem mesecu, da mi je spregovoril Hananjá, sin preroka Azúrja, ki je bil iz Gibeóna, v Gospodovi hiši, v prisotnosti duhovnikov in vsega ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '»Tako govori Gospod nad bojevniki, Izraelov Bog, rekoč: ›Zlomil sem jarem babilonskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'V dveh letih bom ponovno na ta kraj privedel vse posode Gospodove hiše, ki jih je babilonski kralj Nebukadnezar vzel iz tega kraja in jih odnesel v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Ponovno bom na ta kraj privedel Jehoníja, sina Jojakíma, Judovega kralja, z vsemi Judovimi ujetniki, ki so šli v Babilon,‹ govori Gospod, ›kajti jaz bom zlomil jarem babilonskega kralja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Potem je prerok Jeremija rekel preroku Hananjáju, v prisotnosti duhovnikov in v prisotnosti vsega ljudstva, ki je stalo v Gospodovi hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'celo prerok Jeremija je rekel: »Amen. Gospod naj tako stori. Gospod naj izpolni tvoje besede, ki si jih prerokoval, da ponovno privede posode Gospodove hiše in vse, kar je odvedeno ujeto, iz Babilona na ta kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Kljub temu poslušaj sedaj te besede, ki jih govorim v tvoja ušesa in v ušesa vsega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Preroki, ki so bili pred menoj in pred teboj od davnine, so prerokovali tako zoper mnoge dežele kakor zoper velika kraljestva, o vojni in o zlu in o kužni bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Prerok, ki prerokuje o miru, ko se bo zgodila prerokova beseda, potem bo prerok znan, da ga je resnično poslal Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Potem je prerok Hananjá snel jarem iz vratu preroka Jeremija in ga zlomil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Hananjá je spregovoril v prisotnosti vsega ljudstva, rekoč: »Tako govori Gospod: ›Celo tako bom zlomil jarem babilonskega kralja Nebukadnezarja iz vratu vseh narodov, v času dveh polnih let.‹« In prerok Jeremija je odšel svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Potem je Gospodova beseda prišla preroku Jeremiju, potem ko je prerok Hananjá zlomil jarem iz vratu preroka Jeremija, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '»Pojdi in povej Hananjáju, rekoč: ›Tako govori Gospod: ›Zlomil si lesene jarme, toda zanje boš naredil železne jarme.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: ›Železen jarem sem položil na vrat vseh teh narodov, da bodo lahko služili babilonskemu kralju Nebukadnezarju; in služili mu bodo in dal sem mu tudi poljske živali.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Potem je prerok Jeremija rekel preroku Hananjáju: »Prisluhni sedaj Hananjá: › Gospod te ni poslal, temveč ti zavajaš to ljudstvo, da zaupa v laž.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Zato tako govori Gospod: ›Glej, vrgel te bom iz obličja zemlje. To leto boš umrl, ker si učil upor zoper Gospoda.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Tako je prerok Hananjá to isto leto umrl, v sedmem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Torej to so besede pisma, ki ga je prerok Jeremija poslal iz Jeruzalema preostanku starešin, ki so bili odvedeni ujeti, duhovnikom, prerokom in vsem ljudstvu, ki jih je Nebukadnezar ujete odvedel iz Jeruzalema v Babilon');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(potem so bili kralj Jehoníja, kraljica, evnuhi, princi iz Juda in Jeruzalema ter tesarji in kovači odvedeni iz Jeruzalema)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'po roki Šafánovega sina Elasá in Hilkijájevega sina Gemarjá (katera je Judov kralj Sedekíja poslal v Babilon k babilonskemu kralju Nebukadnezarju), rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '»Tako govori Gospod nad bojevniki, Izraelov Bog, vsem, ki so odvedeni ujeti, ki sem jim povzročil, da so odvedeni proč iz Jeruzalema v Babilon:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '›Zgradite si hiše in prebivajte v njih, zasajajte vrtove in jejte njihov sad,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'jemljite si žene in zaplodite sinove ter hčere, in vzemite žene za svoje sinove in svoje hčere dajte soprogom, da bodo lahko rodile sinove in hčere, da boste tam lahko povečani in ne zmanjšani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Iščite mir mestu, kamor sem vam povzročil, da ste bili odvedeni ujeti in zanj molite h Gospodu, kajti v njegovem miru boste vi imeli mir.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: »Naj vas vaši preroki in vaši vedeževalci, ki so v vaši sredi, ne zavajajo, niti ne prisluhnite svojim sanjam, ki ste jim povzročili, da so sanjane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Kajti lažno vam prerokujejo v mojem imenu. Nisem jih poslal,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Kajti tako govori Gospod: »Da vas bom po tem, ko bo v Babilonu dovršenih sedemdeset let, obiskal in izvêdel svojo dobro besedo napram vam, v tem, da povzročim, da se vrnete na ta kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Kajti poznam misli, ki jih mislim napram vam,« govori Gospod, »misli miru in ne zla, da vam dam pričakovan konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Takrat boste klicali k meni in boste šli in molili k meni in vam bom prisluhnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Iskali me boste in me našli, ko me boste iskali z vsem svojim srcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Dal se vam bom najti,« govori Gospod, »in vaše ujetništvo bom odvrnil proč in zbral vas bom izmed vseh narodov in iz vseh krajev, kamor sem vas pregnal,« govori Gospod, »in jaz vas bom ponovno privedel na kraj, od koder sem vam povzročil, da ste bili odvedeni ujeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Ker ste rekli: › Gospod nam je v Babilonu vzdignil preroke;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'vedite, da tako govori Gospod o kralju, ki sedi na Davidovem prestolu in o vsemu ljudstvu, ki prebiva v tem mestu in o vaših bratih, ki niso šli z vami naprej v ujetništvo;«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'tako govori Gospod nad bojevniki: »Poglejte, nadnje bom poslal meč, lakoto in kužno bolezen in naredil jih bom kot ogabne fige, ki se ne morejo pojesti, ker so tako zle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Preganjal jih bom z mečem, z lakoto in s kužno boleznijo in izročil jih bom, da bodo odstranjeni k vsem kraljestvom zemlje, da bodo prekletstvo, osuplost, posmeh in graja med vsemi narodi, kamor sem jih pregnal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'ker niso prisluhnili mojim besedam,« govori Gospod, »ki sem jim jih pošiljal po svojih služabnikih prerokih, jih zgodaj vzdigoval in pošiljal; toda vi niste hoteli poslušati,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, '»Poslušajte torej besedo od Gospoda, vsi vi iz ujetništva, ki sem vas poslal iz Jeruzalema v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tako govori Gospod nad bojevniki, Izraelov Bog o Kolajájevemu sinu Ahábu, in o Maasejájevemu sinu Sedekíju, ki vam prerokujeta laž v mojem imenu: ›Glejte, izročil ju bom v roko babilonskega kralja Nebukadnezarja in ta ju bo ubil pred vašimi očmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Od njiju bo vse Judovo ujetništvo, ki je v Babilonu, povzelo prekletstvo, rekoč: › Gospod naj ti stori kakor Sedekíju in kakor Ahábu, ki ju je babilonski kralj pekel na ognju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'ker sta zagrešila podlost v Izraelu in zagrešila zakonolomstvo z ženami svojih sosedov in v mojem imenu govorila lažnive besede, ki jima jih nisem zapovedal. Celo vedel sem in sem priča,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, '› Tako boš tudi ti govoril Šemajáju Nehelaméjcu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '›Tako govori Gospod nad bojevniki, Izraelov Bog, rekoč: ›Ker si v svojem imenu poslal pisma vsemu ljudstvu, ki so v Jeruzalemu in k duhovniku Cefanjáju, Maasejájevemu sinu in vsem duhovnikom, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '› Gospod te je postavil za duhovnika namesto duhovnika Jojadája, da bi bili častniki v Gospodovi hiši, za vsakega človeka, ki je zmešan in se dela preroka, da ga bi vtaknil v ječo in v klade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Zdaj torej, zakaj nisi grajal Jeremija iz Anatóta, ki se vam dela prerok?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Kajti zato je poslal k nam v Babilon, rekoč: ›To ujetništvo je dolgo. Zgradite si hiše in prebivajte v njih, zasadite vrtove in jejte sad od njih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Duhovnik Cefanjá je to pismo prebral v ušesa preroka Jeremija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Potem je prišla Gospodova beseda Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '»Pošlji k vsem tem iz ujetništva, rekoč: ›Tako govori Gospod glede Šemajája Nehelaméjca: ›Zato, ker je ta Šemajá prerokoval zoper vas, pa ga nisem poslal jaz in vam je storil, da zaupate v laž,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'zato tako govori Gospod: ›Glejte, kaznoval bom Šemajája Nehelaméjca in njegovo seme. Ne bo imel človeka, da prebiva med tem ljudstvom; niti ne bo gledal dobrega, ki ga bom storil za svoje ljudstvo,‹ govori Gospod; ›ker je učil upor zoper Gospoda.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '»Tako govori Gospod, Izraelov Bog, rekoč: ›V knjigo si zapiši vse besede, ki sem ti jih govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Kajti glej, prihajajo dnevi,‹ govori Gospod, ›da bom ponovno privedel ujetništvo svojega ljudstva Izraela in Juda,‹ govori Gospod ›in povzročil jim bom, da se vrnejo v deželo, ki sem jo dal njihovim očetom in oni jo bodo vzeli v last.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'To so besede, ki jih je Gospod govoril glede Izraela in glede Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Kajti tako govori Gospod: »Slišali smo glas trepetanja, strahu in ne miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Vprašajte torej in poglejte, ali je mož v porodnih mukah z otrokom? Zakaj vidim vsakega moža s svojimi rokami na svojih ledjih, kakor žensko v porodnih mukah in so vsi obrazi postali bledi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ojoj! Kajti ta dan je velik, tako da mu ni nobeden podoben. To je celo čas Jakobove stiske, toda rešen bo iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Kajti to se bo zgodilo na ta dan,« govori Gospod nad bojevniki, » da bom zlomil njegov jarem s tvojega vratu in raztrgal tvoje vezi in tujcem ne bo več sužnjeval,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'temveč bodo služili Gospodu, svojemu Bogu in Davidu, svojemu kralju, ki jim ga bom vzdignil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Zato se ne boj, oh moj služabnik Jakob,‹ govori Gospod; ›niti ne bodi zaprepaden, oh Izrael, kajti, glej, rešil te bom od daleč in tvoje seme iz dežele njihovega ujetništva. Jakob se bo vrnil in bo v miru in bo tiho in nihče ga ne bo prestrašil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Kajti jaz sem s teboj,‹ govori Gospod, ›da te rešim. Čeprav naredim poln konec vsem narodom, kamor sem te razkropil, vendar iz tebe ne bom naredil polnega konca, temveč te bom grajal po meri in te ne bom pustil povsem nekaznovanega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Kajti tako govori Gospod: ›Tvoja poškodba je nezaceljiva in tvoja rana je boleča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nobenega ni, da zagovarja tvoj primer, da bi bil lahko obvezan. Nobenih zdravilnih zdravil nimaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Vsi tvoji ljubimci so te pozabili. Ne iščejo te; kajti ranil sem te z rano sovražnika, s kaznovanjem krutega, zaradi množice tvojih krivičnosti, ker so tvoji grehi narasli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Zakaj vpiješ zaradi svoje stiske? Tvoja bridkost je neozdravljiva zaradi množice tvoje krivičnosti. Ker so tvoji grehi narasli, sem ti jaz storil te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Zatorej bodo vsi, ki te požirajo, požrti, in vsi tvoji nasprotniki, vsak izmed njih, bodo šli v ujetništvo, in tisti, ki te plenijo, bodo plen in vse to ukradeno blago na tebi bom dal za plen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Kajti jaz ti bom obnovil zdravje in jaz te bom ozdravil tvojih ran,‹ govori Gospod, ›ker so te imenovali Izobčenec, rekoč: ›To je Sion, ki ga noben človek ne išče.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tako govori Gospod: ›Glej, ponovno bom privedel ujetništvo Jakobovih šotorov in se usmilil njegovih bivališč, in mesto bo zgrajeno na svojem lastnem kupu in palača bo ostala po svoji lastni navadi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Iz njih bo izšlo zahvaljevanje in glas tistih, ki se veselijo. Pomnožil jih bom in ne bo jih malo; prav tako jih bom proslavil in ne bodo majhni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Tudi njihovi otroci bodo kakor poprej in njihova skupnost bo utrjena pred menoj, kaznoval pa bom vse, ki jih zatirajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, '§ Njihovi plemiči bodo izmed njih in njihov voditelj bo izšel iz njihove srede. Povzročil mu bom, da se približa in pristopil bo k meni, kajti kdo je ta, ki daje svojemu srcu jamstvo, da se mi približa?‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, '›Vi boste moje ljudstvo in jaz bom vaš Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Glej, vrtinčast veter od Gospoda gre naprej z razjarjenostjo, nenehen vrtinčast veter; boleče bo padel na glavo zlobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Gospodova kruta jeza se ne bo vrnila, dokler ne bo tega storil in dokler ne izpolni namene svojega srca. V zadnjih dneh boste to preudarili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '»›Isti čas,‹ govori Gospod, ›bom jaz Bog vsem Izraelovim družinam in oni bodo moje ljudstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tako govori Gospod: ›Ljudstvo, ki je preostalo od meča, je našlo milost v divjini; celó Izrael, ko sem odšel, da mu povzročim, da počiva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Gospod se mi je prikazal od davnine, rekoč: »Da, ljubil sem te z večno ljubeznijo, zato sem te pritegnil z ljubečo skrbnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ponovno te bom zgradil in boš zgrajena, oh devica Izraelova. Ponovno boš okrašena s svojimi bobniči in šla naprej na plese tistih, ki se veselijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Še boš sadila trte na gorah Samarije. Sadilci bodo sadili in jih bodo jedli kakor običajne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Kajti dan bo, da bodo stražarji na gori Efrájim klicali: ›Vstanite in pojdimo gor na Sion h Gospodu, svojemu Bogu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Kajti tako govori Gospod: ›Prepevajte z veseljem zaradi Jakoba in vzklikajte med vodjem narodov. Razglašajte, hvalite in recite: ›Oh Gospod, reši svoje ljudstvo, Izraelov ostanek.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Glej, privedel jih bom iz severne dežele in jih skupaj zbral iz obal zemlje in z njimi slepe ter hrome, skupaj nosečnico in tisto, ki je v porodnih mukah skupaj z otrokom, velika skupina se bo vrnila tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Prišli bodo z jokanjem in s ponižnimi prošnjami jih bom vodil. Povzročil jim bom, da hodijo po ravni poti ob rekah vodá, na kateri se ne bodo spotaknili, kajti jaz sem oče Izraelu in Efrájim je moj prvorojenec.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Poslušajte Gospodovo besedo: ›Oh vi narodi‹ in razglasite jo na oddaljenih otokih ter recite: ›Kdor je razkropil Izraela, ga bo zbral in ga varoval, kakor pastir stori svojemu tropu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Kajti Gospod je odkupil Jakoba in ga izpustil proti odkupnini iz roke tistega, ki je bil močnejši od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Zato bodo prišli in prepevali na višini Siona in skupaj bodo tekli h Gospodovi dobroti zaradi pšenice, zaradi vina, zaradi olja in zaradi mladičev izmed tropa in od črede. Njihova duša bo kakor namakan vrt in sploh ne bodo več žalovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Potem se bo devica veselila na plesu, tako mladeniči in stari skupaj, kajti njihovo žalovanje bom obrnil v radost in jaz jih bom potolažil in jim dal, da se veselijo od njihove bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Dušo duhovnikov bom nasitil z obiljem in moje ljudstvo bo nasičeno z mojo dobroto,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tako govori Gospod: ›Glas je bil slišan v Rami, žalovanje in grenko jokanje. Rahela, jokajoč za svojimi otroki, je odklanjala biti potolažena zaradi svojih otrok, ker jih ni bilo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tako govori Gospod: ›Svoj glas zadrži pred jokanjem in svoje oči pred solzami, kajti tvoje delo bo nagrajeno,‹ govori Gospod ›in ponovno bodo prišli iz sovražnikove dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Upanje je v tvojem koncu,‹ govori Gospod, ›da bodo tvoji otroci ponovno prišli k svoji lastni meji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Zagotovo sem slišal Efrájima tako žalovati: ›Kaznoval si me in bil sem kaznovan, kakor bikec nenavajen jarma. Obrni me in bom obrnjen, kajti ti si Gospod, moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Zagotovo sem se pokesal, potem ko sem bil obrnjen; in potem ko sem bil poučen, sem udaril na svoje stegno. Osramočen sem bil, da, celo zbegan, ker sem nosil grajo svoje mladosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ali je Efrájim moj dragi sin? Je on prijeten otrok? Kajti odkar sem govoril zoper njega, se ga še vedno iskreno spominjam, zato je moja notranjost zaskrbljena zanj; zagotovo se ga bom usmilil,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Postavi kažipote, naredi si visoke kupe. Svoje srce naravnaj proti glavni cesti, poti, po kateri si hodila. Ponovno se obrni, oh devica Izraelova, ponovno se obrni k tem svojim mestom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Doklej boš hodila okoli, oh ti odpadla hči? Kajti Gospod je ustvaril novo stvar na zemlji: »Ženska bo obdajala moškega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tako govori Gospod nad bojevniki, Izraelov Bog: »›Še bodo uporabljali ta govor v Judovi deželi in njenih mestih, ko bom ponovno privedel njihovo ujetništvo;‹ Gospod [naj] te blagoslovi, oh prebivališče pravice in gora svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'In tam bodo skupaj prebivali v samem Judu in v vseh njihovih mestih, poljedelci in tisti, ki gredo naprej s tropi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Kajti nasitil sem izmučeno dušo in na novo napolnil vsako žalostno dušo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ob tem sem se prebudil in pogledal, in spanje mi je bilo sladko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, '»›Glej, prihajajo dnevi,‹ govori Gospod, ›da bom Izraelovo hišo in Judovo hišo posejal s človeškim semenom in s semenom živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'In zgodilo se bo, da kakor sem stražil nad njimi, da izrujem, da zlomim, da zrušim, da uničim in da prizadenem, tako bom stražil nad njimi, da gradim in da sadim,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'V tistih dneh ne bodo več rekli: ›Očetje so jedli kisel grozd, zobje otrok pa so skominasti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Temveč bo vsak umrl zaradi svoje lastne krivičnosti. Vsak človek, ki jé kisel grozd, bodo njegovi zobje skominasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Glej, prihajajo dnevi,‹ govori Gospod, ›da bom sklenil novo zavezo z Izraelovo hišo in z Judovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Ne glede na zavezo, ki sem jo sklenil z njihovimi očeti na dan, ko sem jih prijel za roko, da jih privedem ven iz egiptovske dežele. Tisto mojo zavezo so prelomili, čeprav sem jim bil soprog,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Toda to bo zaveza, ki jo bom sklenil z Izraelovo hišo: ›Po tistih dneh,‹ govori Gospod, ›bom svojo postavo položil v njihove notranje dele in jo zapisal v njihova srca in bom njihov Bog in oni bodo moje ljudstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Ne bodo več učili vsak svojega soseda in vsak svojega brata, rekoč: ›Spoznajte Gospoda,‹ kajti vsi me bodo poznali, od najmanjšega izmed njih, do največjega izmed njih,‹ govori Gospod, ›kajti odpustil bom njihovo krivičnost in njihovega greha se ne bom več spominjal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tako govori Gospod, ki daje sonce za svetlobo podnevi in odredbe o luni in zvezdah za svetlobo ponoči, ki razdeljuje morje, ko njegovi valovi rjovijo; Gospod nad bojevniki je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '›Če te odredbe odidejo izpred mene,‹ govori Gospod, › potem bo tudi Izraelovo seme prenehalo biti narod pred menoj na veke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tako govori Gospod: ›Če se lahko izmeri nebo zgoraj in se raziščejo temelji zemlje spodaj, bom prav tako zavrgel Izraelovo seme zaradi vsega tega, kar so storili,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, '›Glej, prihajajo dnevi,‹ govori Gospod, ›da bo mesto zgrajeno Gospodu, od Hananélovega stolpa do vogalnih velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Merilna vrvica bo šla še naprej, vodila bo na hrib Garéb in ga obkrožila do Goe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'In celotna dolina trupel in pepela in vsa polja do potoka Kidrona, do vogala konjskih velikih vrat proti vzhodu, bodo sveta Gospodu; ta ne bo več izruvana niti razrušena na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, v desetem letu Judovega kralja Sedekíja, kar je bilo osemnajsto leto Nebukadnezarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Kajti takrat je kralj babilonske vojske oblegal Jeruzalem in prerok Jeremija je bil zaprt na dvorišču ječe, ki je bila v hiši Judovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Kajti Judov kralj Sedekíja ga je zaprl, rekoč: »Zakaj prerokuješ in praviš: ›Tako govori Gospod, ›Glejte, to mesto bom izročil v roko babilonskega kralja in on ga bo zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Judov kralj Sedekíja ne bo pobegnil iz roke Kaldejcev, temveč bo zagotovo izročen v roko babilonskega kralja in bo z njim govoril od ust do ust in njegove oči bodo gledale njegove oči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'in on bo vodil Sedekíja v Babilon in tam bo, dokler ga ne obiščem,‹ govori Gospod. ›Čeprav se borite s Kaldejci, ne boste uspeli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Jeremija je rekel: »K meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, '›Glej, Hanamél, sin tvojega strica Šalúma, bo prišel k tebi, rekoč: ›Kupi si moje polje, ki je v Anatótu, kajti pravica odkupitve je tvoja, da ga kupiš.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Tako je Hanamél, sin mojega strica, prišel k meni na dvorišče ječe, glede na Gospodovo besedo in mi rekel: »Kupi moje polje, prosim te, ki je v Anatótu, ki je v Benjaminovi deželi, kajti pravica dediščine je tvoja in odkupitev je tvoja; kupi ga zase.« Potem sem vedel, da je bila to Gospodova beseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Polje sem kupil od Hanaméla, sina mojega strica, ki je bil v Anatótu in mu odtehtal denar, celó sedemnajst šeklov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Podpisal sem dokaz, ga zapečatil, vzel priče in mu na tehtnici odtehtal denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Tako sem vzel dokaz o nakupu, tako tistega, ki je bil zapečaten glede na postavo in običaj in tistega, ki je bil odprt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Dokaz o nakupu sem dal Nerijájevemu sinu Baruhu, Maasejájevemu sinu, pred očmi Hanaméla, sina mojega strica in v prisotnosti prič, ki so podpisali knjigo o nakupu pred vsemi Judi, ki so sedeli na dvorišču ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Vpričo njih sem Baruhu naročil, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '»Tako govori Gospod nad bojevniki, Izraelov Bog: ›Vzemi te dokaze, ta dokaz o nakupu, oba, [tega], ki je zapečaten in ta dokaz, ki je odprt, in ju daj v lončeno posodo, da se bosta lahko ohranila mnogo dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: ›V tej deželi boste ponovno imeli v lasti hiše, polja in vinograde.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Torej ko sem dokaz o nakupu izročil Nerijájevemu sinu Baruhu, sem molil h Gospodu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '»Ah, Gospod Bog! Glej, naredil si nebo in zemljo s svojo veliko močjo in iztegnjenim laktom in zate ni nič pretežko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Ti izkazuješ ljubečo skrbnost tisočim in poplačaš krivičnost očetov v naročje njihovih otrok za njimi. Veliki, Mogočni Bog, Gospod nad bojevniki je njegovo ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'velik v nasvetu in mogočen v delu, kajti tvoje oči so odprte na vseh poteh človeških sinov, da daš vsakemu glede na njegove poti in glede na sad njegovih ravnanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'ki si postavil znamenja in čudeže v egiptovski deželi, celó do današnjega dne in v Izraelu in med drugimi ljudmi, in si si naredil ime, kakor na ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Svoje ljudstvo Izrael si izpeljal iz egiptovske dežele, z znamenji in s čudeži, z močno roko, z iztegnjenim laktom in z veliko strahoto');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'in jim dal to deželo, ki si jo prisegel njihovim očetom, da jim jo daš, deželo, kjer tečeta mleko in med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Vstopili so vanjo in jo vzeli v last, toda niso ubogali tvojega glasu niti hodili po tvoji postavi. Od vsega, kar si jim zapovedal storiti, niso storili ničesar. Zato si storil, da pride nadnje vse to zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Glej okope, prišli so v mesto, da ga zavzamejo; in mesto je izročeno v roko Kaldejcem, ki se borijo zoper njega zaradi meča, zaradi lakote in zaradi kužne bolezni in kar si govoril, se je zgodilo; in glej, ti to vidiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Ti, oh Gospod Bog, si mi rekel: ›Kupi si polje za denar in vzemi priče, kajti mesto je izročeno v roko Kaldejcem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Potem je prišla beseda od Gospoda Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '»›Glej, jaz sem Gospod, Bog vsega mesa, ali je zame katerakoli stvar pretežka?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Zato tako govori Gospod: ›Glej, to mesto bom izročil v roko Kaldejcev in v roko babilonskega kralja Nebukadnezarja in ta ga bo zavzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Kaldejci, ki se borijo zoper to mesto, bodo prišli in vžgali ogenj nad tem mestom in ga zažgali, s hišami, na katerih strehah so darovali kadilo Báalu in izlivali pitne daritve drugim bogovom, da me dražijo do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Kajti Izraelovi otroci in Judovi otroci so od svoje mladosti pred menoj počeli zgolj zlo, kajti Izraelovi otroci so me z deli svojih rok samo dražili do jeze,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, '›Kajti to mesto mi je bilo kakor izzivanje moje jeze in moje razjarjenosti od dneva, ko so ga zgradili, celo do današnjega dne, da bi ga odstranil izpred svojega obraza,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'zaradi vsega zla Izraelovih otrok in Judovih otrok, ki so ga storili, da me dražijo k jezi, oni, njihovi kralji, njihovi princi, njihovi duhovniki, njihovi preroki, Judovi možje in prebivalci Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obrnili so mi hrbet in ne obraza, čeprav sem jih učil, zgodaj vzdigoval in jih učil, vendar niso prisluhnili, da bi sprejeli poučevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Temveč so v hišo, ki je imenovana z mojim imenom, postavili svoje ogabnosti, da jo omadežujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Zgradili so visoke kraje Báalu, ki so v dolini sina Hinómovega, da svojim sinovom in svojim hčeram povzročijo, da gredo skozi ogenj k Molohu; kar jim nisem zapovedal niti mi ni prišlo na misel, da storijo to ogabnost, da Judu povzročijo, da greši.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Sedaj torej tako govori Gospod, Izraelov Bog, glede tega mesta, o katerem pravite: ›Izročen bo v roko babilonskega kralja, z mečem, z lakoto in s kužno boleznijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Glejte, zbral jih bom iz vseh dežel, kamor sem jih pognal v svoji jezi, v svoji razjarjenosti in v velikem besu; in ponovno jih bom privedel na ta kraj in povzročil jim bom, da varno prebivajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Oni bodo moje ljudstvo in jaz bom njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Dal jim bom eno srce in eno pot, da se me bodo lahko bali na veke, v dobro njim in njihovim otrokom za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Z njimi bom sklenil večno zavezo, da se ne bom odvrnil proč od njih, da jim delam dobro; toda svoj strah bom položil v njihova srca, da ne bodo odšli od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Da, razveseljeval se bom nad njimi, da jim delam dobro in v tej deželi jih bom zagotovo sadil s svojim celotnim srcem in s svojo celotno dušo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Kajti tako govori Gospod: ›Kakor sem privedel vse to veliko zlo nad to ljudstvo, tako bom nadnje privedel vse dobro, ki sem jim ga obljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Polja se bodo kupovala v tej deželi, o kateri pravite: › Ta je zapuščena, brez človeka ali živali; ta je izročena v roko Kaldejcem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Ljudje bodo polja kupovali za denar, podpisovali dokaze, jih pečatili in jemali priče v Benjaminovi deželi in v krajih okoli Jeruzalema, v Judovih mestih, gorskih mestih, dolinskih mestih in v mestih na jugu, kajti jaz bom njihovemu ujetništvu povzročil, da se vrne,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Poleg tega je beseda od Gospoda drugič prišla Jeremiju, medtem ko je bil še zaprt na dvorišču ječe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '»Tako govori Gospod, ki to dela, Gospod, ki je to oblikoval, da to osnuje, Gospod je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, '›Kliči k meni in ti bom odgovoril in ti pokazal velike in mogočne stvari, ki jih ne poznaš.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Kajti tako govori Gospod, Izraelov Bog, glede hiš tega mesta in glede hiš Judovih kraljev, ki so zrušene z okopi in z mečem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, '›Prišli so, da se borijo s Kaldejci, toda to je, da jih napolnijo s trupli mož, ki sem jih umoril v svoji jezi in v svoji razjarjenosti in svoj obraz sem zaradi vse zlobnosti skril pred tem mestom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Glej, privedel bom zdravje in zdravilo, jih ozdravil in jim razodel obilje miru in resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Povzročil bom Judovemu ujetništvu in Izraelovemu ujetništvu, da se vrnejo in jih bom zgradil kakor poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Očistil jih bom pred vso njihovo krivičnostjo, s katero so grešili zoper mene, in oprostil jim bom vse njihove krivičnosti, s katerimi so grešili in s katerimi so se pregrešili zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'To mi bo ime radosti, hvala in čast pred vsemi narodi zemlje, ki bodo slišali vse dobro, ki jim ga storim. Bali se bodo in trepetali zaradi vse dobrote in zaradi vsega uspevanja, ki sem ga priskrbel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tako govori Gospod: ›Ponovno se bo na tem kraju, za katerega pravite, [da] bo zapuščen, brez človeka in brez živali, torej v Judovih mestih in na ulicah Jeruzalema, ki so zapuščene, brez človeka in brez naseljenca in brez živali, slišal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'glas radosti in glas veselja, glas ženina in glas neveste, glas tistih, ki bodo rekli: ›Hvalite Gospoda nad bojevniki, kajti Gospod je dober, kajti njegovo usmiljenje vztraja na veke,‹ in od teh, ki bodo prinašali žrtev hvale v Gospodovo hišo. Kajti povzročil bom vrnitev ujetništva dežele, kakor na začetku,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tako govori Gospod nad bojevniki: ›Ponovno bo na tem kraju, ki je zapuščen, brez človeka in brez živali in v vseh njegovih mestih, prebivališče pastirjev, ki bodo svojim tropom povzročali, da se uležejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'V gorskih mestih, v dolinskih mestih, v mestih na jugu, v Benjaminovi deželi, v krajih okoli Jeruzalema in v Judovih mestih bodo tropi ponovno prehajali pod rokama tistega, ki jih prešteva,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, '›Glej, prihajajo dnevi,‹ govori Gospod, ›da bom izpolnil to dobro stvar, ki sem jo obljubil Izraelovi hiši in Judovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'V tistih dneh in v tistem času, bom povzročil, da Davidu zraste Mladika pravičnosti, in on bo izvršil sodbo in pravičnost v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'V tistih dneh bo Juda rešen in [prestolnica] Jeruzalem bo varno prebivala, in to je ime, s katerim bo imenovana: › Gospod, naša pravičnost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Kajti tako govori Gospod: ›Davidu nikoli ne bo manjkalo moža, da sedi na prestolu Izraelove hiše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'niti ne bo duhovnikom Lévijevcem manjkal mož pred menoj, da daruje žgalne daritve in da vžiga jedilne daritve in da opravlja nenehno klavno daritev.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Gospodova beseda je prišla Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '»Tako govori Gospod: ›Če lahko prelomite mojo zavezo dneva in mojo zavezo noči in da ne bo več dneva in noči v njunem obdobju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'potem bo lahko tudi moja zaveza z Davidom, mojim služabnikom, prelomljena, da ne bi imel sina, da kraljuje na njegovem prestolu, in z duhovniki Lévijevci, mojimi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Kakor vojska neba ne more biti prešteta niti morski pesek izmerjen, tako bom pomnožil seme Davida, svojega služabnika in Lévijevce, ki mi služijo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Poleg tega je Gospodova beseda prišla Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '»Mar ne preudarjaš tega, kar je to ljudstvo govorilo, rekoč: ›Dve družini, ki ju je Gospod izbral, je celó zavrgel?‹ Tako so prezirali moje ljudstvo, da ne bi bilo več narod pred njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tako govori Gospod: ›Če ne bi bilo moje zaveze z dnevom in nočjo in če ne bi določil odredb o nebu in zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'potem bom zavrgel Jakobovo seme in Davida, svojega služabnika, tako da ne bom vzel nobenega iz njegovega semena, da bi bili vladarji nad semenom Abrahama, Izaka in Jakoba, kajti njihovemu ujetništvu bom povzročil, da se vrnejo in se jih bom usmilil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, ko se je babilonski kralj Nebukadnezar, vsa njegova vojska, vsa zemeljska kraljestva njegovega gospostva in vse ljudstvo borilo zoper [prestolnico] Jeruzalem in zoper vsa njena mesta, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '»Tako govori Gospod, Izraelov Bog: ›Pojdi in govori Judovemu kralju Sedekíju in mu povej: ›Tako govori Gospod: ›Glej, to mesto bom izročil v roko babilonskega kralja in ta ga bo požgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ti ne boš pobegnil iz njegove roke, temveč boš zagotovo zajet in izročen v njegovo roko, in tvoje oči bodo gledale oči babilonskega kralja in ta bo govoril s teboj od ust do ust in šel boš v Babilon.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Vendar poslušaj besedo od Gospoda, oh Judov kralj Sedekíja: »Tako govori Gospod o tebi: ›Ne boš umrl pod mečem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'temveč boš umrl v miru, in s sežigi [dišav] tvojim očetom, prejšnjim kraljem, ki so bili pred teboj; tako bodo sežgali dišave zate; in oni te bodo objokovali, rekoč: ›Ah, gospod!‹ Kajti jaz sem proglasil besedo,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Potem je prerok Jeremija vse te besede govoril Judovemu kralju Sedekíju v Jeruzalemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'ko se je vojska babilonskega kralja borila zoper Jeruzalem in zoper vsa Judova mesta, ki so ostala, zoper Lahíš in zoper Azéko, kajti ta obrambna mesta so preostala od Judovih mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'To je beseda, ki je prišla Jeremiju od Gospoda, potem ko je kralj Sedekíja sklenil zavezo z vsem ljudstvom, ki je bilo v Jeruzalemu, da jim razglasi svobodo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'da naj bi vsak človek pustil svojega sluga in vsak človek svojo deklo, ki je Hebrejec ali Hebrejka, oditi prosto, da naj ne bi bil nihče postrežen od njih, torej od svojega brata Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Torej ko so vsi princi in vse ljudstvo, ki je vstopilo v zavezo, slišalo, da naj bi vsak pustil svojega sluga in vsakdo svojo deklo oditi prosto, da naj si nihče izmed njih ne pusti več streč od njih, potem so ubogali in jim pustili oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Toda potem so se obrnili nazaj in veleli služabnikom in pomočnicam, ki so jih pustili oditi proste, da se vrnejo in jih privedli v podjarmljenje za služabnike in za pomočnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Zato je Gospodova beseda prišla k Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '»Tako govori Gospod, Izraelov Bog: ›Zavezo sem sklenil z vašimi očeti na dan, ko sem jih izpeljal iz egiptovske dežele, iz hiše sužnosti, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '›Ob koncu sedmih let pustite oditi vsak mož svojega brata Hebrejca, ki ti je bil prodan; in ko ti je služil šest let, ga boš pustil od sebe oditi prostega.‹ Toda vaši očetje mi niso prisluhnili niti nagnili svojega ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'In sedaj ste bili obrnjeni in storili pravilno v mojem pogledu v razglašanju svobode vsak človek svojemu sosedu; in pred menoj ste sklenili zavezo v hiši, ki je imenovana z mojim imenom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Toda obrnili ste se in oskrunili moje ime in veleli vsak človek svojemu služabniku in vsak mož svoji pomočnici, ki jih ste na njihovo zadovoljstvo spustili na svobodo, da se vrnejo in jih privedli v podjarmljenje, da so vam za služabnike in pomočnice.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Zato tako govori Gospod: ›Niste mi prisluhnili v razglašanju svobode, vsak človek svojemu bratu in vsak človek svojemu sosedu. Glejte, razglašam vam svobodo,‹ govori Gospod, ›meču, kužni bolezni in lakoti, in storil vam bom, da boste odstranjeni v vsa kraljestva zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'In jaz bom dal ljudi, ki so prestopali mojo zavezo, ki niso izpolnjevali besed zaveze, ki so jo sklenili pred menoj, ko so tele preklali na polovico in šli med njegovima deloma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Judove prince in jeruzalemske prince, evnuhe in duhovnike in vse ljudstvo dežele, ki so šli med deloma teleta;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'jaz jih bom celo izročil v roko njihovih sovražnikov in v roko tistih, ki jim strežejo po življenju. Njihova trupla bodo za hrano perjadi neba in zemeljskim živalim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Judovega kralja Sedekíja in njegove prince bom izročil v roko njihovih sovražnikov in v roko tistih, ki jim strežejo po življenju in v roko kralja babilonske vojske, ki so šli gor od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Glej, zapovedal bom,‹ govori Gospod ›in jim povzročil, da se vrnejo k temu mestu; in bojevali se bodo zoper njega, ga zavzeli in ga požgali z ognjem in jaz bom Judova mesta naredil opustošenje brez prebivalca.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Beseda, ki je prišla Jeremiju od Gospoda v dneh Jojakíma, Jošíjevega sina, Judovega kralja, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '»Pojdi v hišo Rehábovcev in jim govori in jih privedi v Gospodovo hišo, v eno izmed sob in jim daj piti vino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Potem sem vzel Jaazanjá, Jeremijevega sina, sina Habacinjájevega in njegove brate in vse njegove sinove in celotno hišo Rehábovcev;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'in jih privedel v Gospodovo hišo, v sobo sinov Hanána, Jigdaljájevega sina, Božjega moža, ki je bila pri sobi princev, ki je bila nad sobo Šalúmovega sina Maasejája, čuvaja vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Pred sinove hiše Rehábovcev sem postavil vrče, polne vina in čaše ter jim rekel: »Pijte vino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Toda rekli so: »Nobenega vina ne bomo pili, kajti Jonadáb, sin Rehába, naš oče, nam je zapovedal, rekoč: ›Nobenega vina ne boste pili niti vi niti vaši sinovi na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Niti ne boste gradili hiše, niti sejali semena, niti sadili vinograda, niti imeli karkoli, temveč boste vse svoje dni prebivali v šotorih, da boste lahko mnogo dni živeli v deželi, kjer ste tujci.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Tako smo ubogali glas Rehábovega sina Jonadába, našega očeta, v vsem, kar nam je določil, da vse naše dni ne pijemo nobenega vina, ne mi, ne naše žene, ne naši sinovi, niti naše hčere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'niti da si ne gradimo hiš, da bi prebivali v njih, niti nimamo vinograda, niti polja, niti semena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'temveč smo prebivali v šotorih in ubogali in storili glede na vse, kar nam je naš oče Jonadáb zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Toda pripetilo se je, ko je babilonski kralj Nebukadnezar prišel gor v to deželo, da smo rekli: ›Pridimo in pojdimo v Jeruzalem zaradi strahu pred vojsko Kaldejcev in zaradi strahu pred sirsko vojsko‹ in tako prebivajmo pri Jeruzalemu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Potem je prišla beseda od Gospoda Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '»Tako govori Gospod nad bojevniki, Izraelov Bog: ›Pojdite in povejte ljudem Juda in prebivalcem Jeruzalema: ›Ali ne boste sprejeli poučevanja, da prisluhnete mojim besedam?‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, '›Besede Rehábovega sina Jonadába, ki jih je zapovedal svojim sinovom, naj ne pijejo vina, se izvršujejo, kajti do današnjega dne ne pijejo, temveč ubogajo zapoved svojega očeta. Vendar sem vam jaz govoril, vzdigujoč zgodaj in govoreč, toda niste mi prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'K vam sem pošiljal tudi vse svoje služabnike preroke, vzdigujoče zgodaj in jih pošiljal, rekoč: ›Vrnite se sedaj, vsakdo ali vsak človek iz svoje zle poti in poboljšajte svoja dejanja in ne pojdite za drugimi bogovi, da jim služite in boste prebivali v deželi, ki sem jo dal vam in vašim očetom.‹ Toda niste nagnili svojega ušesa niti mi niste prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ker so sinovi Rehábovega sina Jonadába izvajali zapoved svojega očeta, ki jim jo je zapovedal, toda to ljudstvo mi ni prisluhnilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'zato tako govori Gospod, Bog nad bojevniki, Izraelov Bog: ›Glejte, privedel bom nad Juda in nad vse prebivalce Jeruzalema, vse zlo, ki sem ga proglasil zoper njih, ker sem jim govoril, toda niso slišali, in klical k njim, toda niso odgovorili.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Jeremija je hiši Rehábovcev rekel: »Tako govori Gospod nad bojevniki, Izraelov Bog: ›Ker ste ubogali zapoved Jonadába, svojega očeta in se držali vseh njegovih predpisov in storili glede na vse, kar vam je zapovedal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'zato tako govori Gospod nad bojevniki, Izraelov Bog: ›Rehábovemu sinu Jonadábu ne bo manjkal moški, da bi stal pred menoj na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Pripetilo se je v četrtem letu Jojakíma, Jošíjevega sina, Judovega kralja, da je ta beseda prišla Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '»Vzemi zvitek knjige in zapiši vanjo vse besede, ki sem ti jih govoril zoper Izrael in zoper Juda in zoper vse narode, od dneva, ko sem ti spregovoril, od Jošíjevih dni, celo do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Morda bo Judova hiša prisluhnila vsemu zlu, ki jim ga nameravam storiti, da se bodo lahko vrnili vsak človek iz svoje zle poti, da bi lahko odpustil njihovo krivičnost in njihov greh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Potem je Jeremija poklical Nerijájevega sina Baruha in Baruh je iz Jeremijevih ust zapisal vse besede od Gospoda, ki mu jih je povedal, v zvitek knjige.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Jeremija je zapovedal Baruhu, rekoč: »Jaz sem zaprt; ne morem iti v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Zato pojdi ti in beri iz zvitka, ki si ga zapisal iz mojih ust, besede od Gospoda v ušesa ljudstva, v Gospodovi hiši, na dan posta, in bral jih boš tudi v ušesa vsega Juda, ki pride iz njihovih mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Morda bodo predstavili svojo ponižno prošnjo pred Gospodom in se bodo vrnili vsak iz svoje zle poti, kajti velika je jeza in razjarjenost, ki jo je Gospod proglasil zoper to ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Nerijájev sin Baruh je storil glede na vse, kar mu je prerok Jeremija zapovedal, ko je iz knjige bral besede od Gospoda v Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Pripetilo se je v petem letu Jojakíma, Jošíjevega sina, Judovega kralja, v devetem mesecu, da so razglasili post pred Gospodom vsemu ljudstvu v Jeruzalemu in vsemu ljudstvu, ki je iz Judovih mest prišlo v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Potem je Baruh v knjigi bral Jeremijeve besede v Gospodovi hiši, v sobi Gemarjája, Šafánovega sina, pisarja, na višjem dvoru, ob vhodu novih velikih vrat Gospodove hiše, v ušesa vsega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Ko je Mihajá, sin Gemarjája, sin Šafána, iz knjige slišal vse Gospodove besede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, '§ je potem odšel dol v kraljevo hišo, v pisarjevo sobo. Glej, vsi princi so sedeli tam, celó pisar Elišamá in Šemajájev sin Delajája in Ahbórjev sin Elnatána, Šafánov sin Gemarjá in Hananjájev sin Sedekíja in vsi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Potem jim je Mihajá naznanil vse besede, ki jih je slišal, ko je Baruh bral knjigo v ušesa ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Zatorej so vsi princi k Baruhu poslali Jehudíja, sina Netanjája, sina Šelemjája, sina Kušíja, rekoč: »V svojo roko vzemi zvitek, ki si ga prebral v ušesa ljudstva in pridi.« Tako je Nerijájev sin Baruh vzel zvitek v svojo roko in prišel k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Rekli so mu: »Usedi se sedaj in preberi to v naša ušesa.« Tako je Baruh to prebral v njihova ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Pripetilo se je torej, ko so slišali vse besede, da so bili prestrašeni, tako eni kakor drugi in rekli Baruhu: »Zagotovo bomo o vseh teh besedah povedali kralju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Baruha pa so vprašali, rekoč: »Sedaj nam povej: ›Kako si zapisal vse te besede pri njegovih ustih?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Potem jim je Baruh odgovoril: »On mi je vse te besede proglasil s svojimi usti, jaz pa sem jih s črnilom zapisal v knjigo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Potem so princi rekli Baruhu: »Pojdi, skrij se, ti in Jeremija. Naj noben človek ne ve, kje sta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Vstopili so h kralju na dvor, toda zvitek so položili v sobo pisarja Elišamá in vse besede povedali kralju v ušesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Tako je kralj poslal Jehudíja, da prinese zvitek in ta ga je vzel iz sobe pisarja Elišamája. In Jehudí ga je prebral v ušesa kralja in v ušesa vseh princev, ki so stali poleg kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Torej kralj je sedel v zimski hiši, v devetem mesecu in tam je bil ogenj, ki je pred njim gorel na ognjišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Pripetilo se je, da ko je Jehudí prebral tri ali štiri stolpce, je on to odrezal z nožkom in to vrgel v ogenj, ki je bil na ognjišču, dokler ni bil ves zvitek použit v ognju, ki je bil na ognjišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Vendar niso bili prestrašeni, niti pretrgali svojih oblek niti kralj, niti katerikoli izmed njegovih služabnikov, ki so slišali vse te besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Kljub temu so Elnatán, Delajá in Gemarjá posredovali h kralju, da ne bi zažgal zvitka, toda ni jih hotel poslušati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, '§ Toda kralj je zapovedal Jerahmeélu, sinu Hameleha in Serajáju, sinu Azriéla in Šelemjájevemu sinu Abdeélu, da primejo pisarja Baruha in preroka Jeremija, toda Gospod ju je skril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Potem je Jeremiju prišla beseda od Gospoda, potem ko je kralj sežgal zvitek in besede, ki jih je Baruh zapisal pri Jeremijevih ustih, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '»Ponovno si vzemi drug zvitek in nanj zapiši vse prejšnje besede, ki so bile na prvem zvitku, ki ga je Judov kralj Jojakím sežgal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Judovemu kralju Jojakímu pa boš rekel: ›Tako govori Gospod: ›Ti si sežgal ta zvitek, rekoč: ›Zakaj si pisal tja noter, rekoč: ›Babilonski kralj bo zagotovo prišel in uničil to deželo in bo povzročil, da sta od tam odvzeta človek in žival?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Zato tako govori Gospod o Judovem kralju Jojakímu: ›Nikogar ne bo imel, da sedi na Davidovem prestolu, in njegovo truplo bo vrženo ven, podnevi v vročino in ponoči v zmrzal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Kaznoval ga bom, njegovo seme in njegove služabnike zaradi njihove krivičnosti in jaz bom privedel nadnje, nad prebivalce Jeruzalema in nad Judove može, vse zlo, ki sem ga proglasil zoper njih; toda niso mi prisluhnili.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Potem je Jeremija vzel drug zvitek in ga izročil pisarju Baruhu, Nerijájevemu sinu, ki je iz Jeremijevih ust nanj zapisal vse besede iz knjige, ki jo je Judov kralj Jojakím sežgal v ognju. Poleg teh so jim bile dodane mnoge druge podobne besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Kralj Sedekíja, sin Jošíja, je zakraljeval namesto Jojakímovega sina Konija, ki ga je babilonski kralj Nebukadnezar postavil za kralja v Judovi deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Toda niti on niti njegovi služabniki niti ljudstvo dežele ni prisluhnilo Gospodovim besedam, ki jih je govoril po preroku Jeremiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Kralj Sedekíja je poslal Šelemjájevega sina Juhála in duhovnika Cefanjája, Maasejájevega sina, k preroku Jeremiju, rekoč: »Moli za nas sedaj h Gospodu, našemu Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Torej Jeremija je prihajal in odhajal ven med ljudstvom, kajti niso ga vtaknili v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Potem je faraonova vojska prišla iz Egipta. Ko so Kaldejci, ki so oblegali Jeruzalem, slišali novice o njih, so se umaknili od Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Potem je prišla beseda od Gospoda preroku Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '»Tako govori Gospod, Izraelov Bog: ›Tako boš rekel Judovemu kralju, ki te je poslal k meni, da poizveduješ od mene: ›Glej, faraonova vojska, ki je prišla naprej, da vam pomaga, se bo vrnila v Egipt, v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Kaldejci pa bodo ponovno prišli in se borili zoper to mesto, ga zavzeli in požgali z ognjem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tako govori Gospod: ›Ne zavajajte same sebe, rekoč: ›Kaldejci bodo zagotovo odšli od nas,‹ kajti ne bodo odšli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Kajti čeprav bi udarili celotno vojsko Kaldejcev, ki se bori zoper vas in bi tam med njimi preostali samo ranjeni možje, bi se vendar vzdignili vsak človek v svojem šotoru in to mesto požgali z ognjem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Pripetilo se je, ko je bila vojska Kaldejcev odrezana izpred Jeruzalema zaradi strahu pred faraonovo vojsko, da');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, '§ je potem Jeremija odšel naprej iz Jeruzalema, da gre v Benjaminovo deželo, da bi se oddvojil tja, v sredo ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Ko je bil v velikih vratih Benjamina, je bil tam poveljnik straže, katerega ime je bilo Jirijá, sin Šelemjája, sin Hananjá, in ta je prijel preroka Jeremija, rekoč: »Ti bežiš stran h Kaldejcem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Potem je Jeremija rekel: » To je napačno. Jaz ne bežim h Kaldejcem.« Toda ta mu ni prisluhnil. Tako je Jirijá prijel Jeremija in ga privedel k princem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Zakaj princi so bili ogorčeni nad Jeremijem, ga udarili in ga vtaknili v ječo, v hišo pisarja Jonatana, kajti le-to so naredili za ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Ko je Jeremija vstopil v jetniško jamo in v kabine, je Jeremija tam ostal mnogo dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Potem je kralj Sedekíja poslal in ga potegnil ven. Kralj ga je na skrivnem vprašal v svoji hiši in rekel: »Ali je kakršnakoli beseda od Gospoda?« Jeremija je rekel: »Je, kajti,« je rekel, »izročen boš v roko babilonskega kralja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Poleg tega je Jeremija rekel kralju Sedekíju: »Kaj sem se pregrešil zoper tebe ali zoper tvoje služabnike ali zoper to ljudstvo, da ste me vtaknili v ječo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kje so sedaj vaši preroki, ki so vam prerokovali, rekoč: ›Babilonski kralj ne bo prišel zoper vas niti zoper to deželo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Zatorej poslušaj sedaj, prosim te, oh moj gospod kralj. Naj bo moja ponižna prošnja, prosim te, sprejeta pred teboj, da mi ne povzročiš, da se vrnem k hiši pisarja Jonatana, da tam ne umrem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Potem je kralj Sedekíja zapovedal, da naj Jeremija pošljejo na dvorišče ječe in da mu dnevno dajejo kos kruha iz pekarske ulice, dokler ne bi bil ves kruh v mestu porabljen. Tako je Jeremija ostal na dvorišču ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Potem so Matánov sin Šefatjá, Pašhúrjev sin Gedaljá, Šelemjájev sin Juhál in Malkijájajev sin Pašhúr slišali besede, ki jih je Jeremija govoril vsemu ljudstvu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '»Tako govori Gospod: ›Kdor preostaja v tem mestu, bo umrl pod mečem, z lakoto in s kužno boleznijo, toda kdor gre naprej h Kaldejcem, bo živel, kajti svoje življenje bo imel za plen in bo živel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tako govori Gospod: ›To mesto bo zagotovo izročeno v roko kralja babilonske vojske, ki ga bo zavzel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Zato so princi rekli kralju: »Rotimo te, naj bo ta človek usmrčen, kajti on tako slabi roke bojevnikov, ki preostajajo v tem mestu in roke vsega ljudstva, ko jim govori takšne besede, kajti ta človek ne išče blaginje tega ljudstva, temveč škodo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Potem je kralj Sedekíja rekel: »Glejte, v vaši roki je, kajti kralj ni tisti, ki lahko stori kakršnokoli stvar zoper vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, '§ Potem so prijeli Jeremija in ga vrgli v odprtino jame Malkijája, sina Hameleha, ki je bila na dvorišču ječe in Jeremija so spustili dol z vrvmi. Tam v jami pa ni bilo vode, ampak blato. Tako se je Jeremija pogreznil v blato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Torej ko je Ebed Meleh, Etiopijec, eden izmed evnuhov, ki je bil v kraljevi hiši, slišal, da so Jeremija vtaknili v jamo; kralj je takrat sedel v Benjaminovih velikih vratih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'je Ebed Meleh odšel naprej iz kraljeve hiše in kralju spregovoril, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '»Moj gospod kralj, ti možje so storili zlo v vsem, kar so storili preroku Jeremiju, ki so ga vrgli v jamo, in verjetno bo umrl zaradi lakote na kraju, kjer je, kajti v mestu ni več kruha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Potem je kralj ukazal Etiopijcu Ebed Melehu, rekoč: »Vzemi od tod trideset mož s seboj in dvigni preroka Jeremija iz jame, preden umre.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Tako je Ebed Meleh s seboj vzel može in odšel v kraljevo hišo pod zakladnico in od tam vzel stara zakrpana oblačila in stare cunje ter jih z vrvmi spustil dol v jamo k Jeremiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Etiopijec Ebed Meleh je rekel Jeremiju: »Deni si ta stara zakrpana oblačila in stare cunje pod svoja ramena pod vrvi.« Jeremija je tako storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Tako so Jeremija potegnili gor z vrvmi in ga vzeli iz jame in Jeremija je ostal na dvorišču ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Potem je kralj Sedekíja poslal in vzel preroka Jeremija k sebi v tretji vhod, ki je v Gospodovi hiši. Kralj je rekel Jeremiju: »Vprašal te bom stvar, ničesar ne prikrij pred menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Potem je Jeremija rekel Sedekíju: »Če ti to razglasim, mar me ne boš zagotovo usmrtil? In če ti dam nasvet, mar mi boš prisluhnil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Tako je kralj Sedekíja na skrivnem prisegel Jeremiju, rekoč: » Kakor živi Gospod, ki nam je naredil to dušo, te ne bom usmrtil niti te ne bom dal v roko teh mož, ki ti strežejo po življenju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Potem je Jeremija rekel Sedekíju: »Tako govori Gospod, Bog nad bojevniki, Izraelov Bog: ›Če boš zagotovo šel naprej k princem babilonskega kralja, potem bo tvoja duša živela in to mesto ne bo sežgano z ognjem in živel boš ti in tvoja hiša,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'toda če ne boš šel naprej k princem babilonskega kralja, potem bo to mesto dano v roke Kaldejcem in požgali ga bodo z ognjem in ne boš pobegnil iz njihove roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Kralj Sedekíja pa je rekel Jeremiju: »Bojim se Judov, ki so prebegnili h Kaldejcem, da me ne bi izročili v njihovo roko in bi se mi posmehovali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Toda Jeremija je rekel: »Ne bodo te izročili. Ubogaj, rotim te, glas Gospoda, ki ti ga govorim. Tako bo dobro s teboj in tvoja duša bo živela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Toda če zavrneš iti naprej, je to beseda, ki mi jo je pokazal Gospod:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, '›Glej, vse ženske, ki so preostale v hiši Judovega kralja, bodo privedene k princem babilonskega kralja in te ženske bode rekle: ›Tvoji prijatelji so te zavedli in prevladali zoper tebe. Tvoja stopala so pogreznjena v blato in oni so se umaknili nazaj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Tako bodo privedli ven vse tvoje žene in tvoje otroke h Kaldejcem in ne boš ušel iz njihove roke, temveč boš zajet z roko babilonskega kralja in povzročil boš, da bo to mesto sežgano z ognjem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Potem je Sedekíja rekel Jeremiju: »Naj noben človek ne izve o teh besedah in ne boš umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Toda če princi slišijo, da sem govoril s teboj in pridejo k tebi in ti rečejo: ›Razglasi nam sedaj, kaj si rekel kralju, ne skrivaj tega pred nami in ne bomo te usmrtili; in tudi kaj je kralj rekel tebi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Potem jim boš rekel: ›Svojo ponižno prošnjo sem predstavil pred kraljem, da mi ne bi povzročil, da se vrnem v Jonatanovo hišo, da bi tam umrl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Potem so prišli vsi princi k Jeremiju in ga vprašali in ta jim je povedal glede na vse te besede, ki jih je kralj zapovedal. Tako so prenehali govoriti z njim, kajti zadeva ni bila zaznana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Tako je Jeremija prebival na dvorišču ječe do dne, ko je bil Jeruzalem zavzet. Bil je tam, ko je bil Jeruzalem zavzet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'V devetem letu Judovega kralja Sedekíja, v desetem mesecu, je prišel babilonski kralj Nebukadnezar in vsa njegova vojska, zoper Jeruzalem in ga oblegal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'In v enajstem letu Sedekíja, v četrtem mesecu, devetega dne meseca, je bilo mesto predrto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, '§ Vsi princi babilonskega kralja so vstopili in sedli v srednja velika vrata, celó Nergál Sarécer, Samgár Nebú, Sar Sehím, Rab-saris, Nergál Sarécer, Rab–mag, z vsem preostankom princev babilonskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, '§ Pripetilo se je, da ko so jih Judov kralj Sedekíja in vsi bojevniki zagledali, potem so zbežali in odšli naprej iz mesta ponoči po poti kraljevega vrta, ob velikih vratih med obema zidovoma, in odšel je ven po poti ravnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Toda kaldejska vojska jih je zasledovala in Sedekíja dohitela na ravninah Jerihe. Ko so ga prijeli, so ga privedli gor k babilonskemu kralju Nebukadnezarju v Riblo, v Hamátovo deželo, kjer je ta podal razsodbo nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Potem je babilonski kralj usmrtil Sedekíjeve sinove v Ribli, pred njegovimi očmi. Prav tako je babilonski kraj usmrtil vse Judove plemiče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Poleg tega je iztaknil Sedekíjeve oči in ga zvezal z verigami, da ga odvede v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Kaldejci so požgali kraljevo hišo in hiše ljudi z ognjem in porušili zidove Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Potem je Nebuzaradán, poveljnik straže odvedel ujetništvo v Babilon, preostanek ljudstva, ki je ostal v mestu in tiste, ki so pobegnili proč, ki so prebegnili k njemu, s preostankom ljudstva, ki je preostalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Toda Nebuzaradán, poveljnik straže je pustil revne izmed ljudstva, ki niso imeli ničesar, v Judovi deželi in jim obenem dal vinograde in polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Torej babilonski kralj Nebukadnezar je dal naročilo glede Jeremija Nebuzaradánu, poveljniku straže, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '»Vzemi ga in dobro glej nanj in ne stori mu ničesar hudega, temveč mu stori celo tako, kakor ti bo rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Tako je poslal Nebuzaradána, poveljnika straže, Nebušazbána, Rab-sarisa, Nergál Sarécerja, Rab-maga in vse kralje babilonskih princev;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'celo oni so poslali in vzeli Jeremija z dvorišča ječe ter ga predali Gedaljáju, sinu Ahikáma, sinu Šafána, da bi ga odvedel domov. Tako je prebival med ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Torej beseda od Gospoda je prišla Jeremiju, medtem ko je bil zaprt na dvorišču ječe, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '»Pojdi in spregovori Etiopijcu Ebed Melehu, rekoč: ›Tako govori Gospod nad bojevniki, Izraelov Bog: ›Glej, svoje besede bom privedel nad to mesto v zlo in ne v dobro in le-te bodo na ta dan dovršene pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Toda tebe bom na ta dan osvobodil,‹ govori Gospod: ›in ne boš izročen v roko mož, ki se jih bojiš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Kajti jaz te bom zagotovo osvobodil in ne boš padel pod mečem, temveč ti bo tvoje življenje za plen, ker si svoje zaupanje položil vame,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, potem ko ga je Nebuzaradán, poveljnik straže, pustil oditi iz Rame, ko ga je vzel zvezanega z verigami, izmed vseh tistih, ki so bili odvedeni ujeti iz Jeruzalema in Juda v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Poveljnik straže je vzel Jeremija in mu rekel: » Gospod, tvoj Bog, je proglasil to zlo nad tem krajem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Torej Gospod je to privedel in storil glede na to, kakor je rekel, ker ste grešili zoper Gospoda in niste ubogali njegovega glasu, zato je nad vas prišla ta stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Sedaj glej, danes sem ti razvezal verige, ki so bile na tvoji roki. Če se ti zdi dobro, da prideš z menoj v Babilon, dopusti, in jaz bom naklonjeno gledal nate. Toda če se ti zdi slabo, da prideš z menoj v Babilon, se ogni. Glej, vsa dežela je pred teboj. Kamor se ti zdi dobro in primerno zate, da greš, tja pojdi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Torej, medtem ko še ni odšel nazaj, je rekel: »Prav tako pojdi nazaj h Gedaljáju, Ahikámovemu sinu, Šafánovemu sinu, ki ga je babilonski kralj naredil voditelja nad Judovimi mesti in prebivaj z njim med ljudstvom, ali pa pojdi kamorkoli se ti zdi primerno, da greš.« Tako mu je poveljnik straže izročil živež in nagrado ter ga pustil oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Potem je Jeremija odšel k Ahikámovemu sinu Gedaljáju v Micpo, in prebival z njim med ljudstvom, ki je ostalo v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Torej, ko so vsi poveljniki sil, ki so bile na poljih, torej oni in njihovi možje, slišali, da je babilonski kralj postavil Gedaljájevega sina Ahikáma za voditelja v deželi in mu izročil može, ženske, otroke in od revnih iz dežele, izmed teh, ki niso bili odvedeni v ujetništvo v Babilon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'potem so prišli h Gedaljáju v Micpo, celo Netanjájev sin Jišmaél, Johanán in Jonatan, Karéahova sinova in Tanhúmetov sin Serajá in sinovi Efája Netófčana in Jaazanjá, sin Maahčána, oni in njihovi možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Gedaljá, sin Ahikáma, Šafánov sin, je prisegel njim in njihovim možem, rekoč: »Ne bojte se služiti Kaldejcem. Prebivajte v deželi in služite babilonskemu kralju in bo dobro z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Kar se mene tiče, glejte, prebival bom v Micpi, da služim Kaldejcem, ki bodo prišli k nam, toda vi zbirajte vino, poletno sadje in olje ter jih dajajte v svoje posode in prebivajte v svojih mestih, ki ste jih vzeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Podobno, ko so vsi Judje, ki so bili v Moábu in med Amónci in v Edómu in ki so bili v vseh deželah, slišali, da je babilonski kralj pustil Judu ostanek in da je nad njimi postavil Gedaljája, sina Ahikáma, sina Šafána;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'so se celo vsi Judje vrnili iz vseh krajev, kamor so bili pognani ter prišli v Judovo deželo, h Gedaljáju v Micpo in zbrali zelo veliko vina in poletnega sadja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Poleg tega so Karéahov sin Johanán in vsi poveljniki sil, ki so bili na poljih, prišli h Gedaljáju v Micpo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'in mu rekli: »Ali zagotovo veš, da je Baalís, kralj Amóncev, poslal Netanjájevega sina Jišmaéla, da te ubije?« Toda Ahikámov sin Gedaljá jim ni verjel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Potem je Karéahov sin Johanán na skrivnem spregovoril Gedaljáju v Micpi: »Pusti me, prosim te in ubil bom Netanjájevega sina Jišmaéla in noben človek tega ne bo vedel. Čemu naj bi te ta ubil, da bi se vsi Judi, ki so zbrani k tebi, razkropili in preostanek Juda propade?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Toda Ahikámov sin Gedaljá je rekel Karéahovemu sinu Johanánu: »Ne boš storil te stvari, kajti napačno govoriš o Jišmaélu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Pripetilo se je torej v sedmem mesecu, da je Netanjájev sin Jišmaél, sin Elišamá, iz kraljevega semena in kraljevi princi, celo deset mož z njim, prišlo k Ahikámovemu sinu Gedaljáju v Micpo; in tam so skupaj jedli kruh v Micpi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Potem se je dvignil Netanjájev sin Jišmaél in deset mož, ki so bili z njim in z mečem udarili Gedaljája, sina Ahikáma, sina Šafána in ga usmrtili, ki ga je babilonski kralj naredil voditelja nad deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Jišmaél je usmrtil tudi vse Jude, ki so bili z njim, torej z Gedaljájem pri Micpi in Kaldejce, ki so bili najdeni tam in bojevnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Drugega dne se je pripetilo, potem ko je umoril Gedaljája in noben človek tega ni vedel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'da so tja prišli nekateri iz Sihema, iz Šila in iz Samarije, celó osemdeset mož, ki so imeli svoje brade obrite, svoja oblačila pretrgana in razpraskani, z daritvami in kadilom v svoji roki, da jih prinesejo h Gospodovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Netanjájev sin Jišmaél je odšel naprej iz Micpe, da jih sreča, jokajoč vso pot, medtem ko je šel. Pripetilo se je, ko jih je srečal, da jim je rekel: »Pridite k Ahikámovemu sinu Gedaljáju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Bilo je tako, da ko so prišli v sredo mesta, da jih je Netanjájev sin Jišmaél usmrtil in jih vrgel v sredo jame, on in možje, ki so bili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Toda med njimi je bilo najdenih deset mož, ki so Jišmaélu rekli: »Ne ubij nas, kajti zaklade imamo na polju, od pšenice, od ječmena, od olja in od medu.« Tako je potrpel in jih ni ubil med njihovimi brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Torej jama, kamor je Jišmaél vrgel vsa trupla mož, ki jih je umoril zaradi Gedaljája, je bila tista, ki jo je kralj Asá naredil zaradi strahu pred Bašájem, Izraelovim kraljem, in Netanjájev sin Jišmaél jo je napolnil s tistimi, ki so bili umorjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Potem je Jišmaél odvedel proč ujetništvo, ves preostanek ljudstva, ki so bili v Micpi, celó kraljeve hčere in vse ljudstvo, ki je ostalo v Micpi, ki jih je Nebuzaradán, poveljnik straže, predal Ahikámovemu sinu Gedaljáju in Netanjájev sin Jišmaél jih je ujete odvedel in odšel, da bi prešel k Amóncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Toda ko so Karéahov sin Johanán in vsi poveljniki sil, ki so bili z njim, slišali o vsem zlu, ki ga je storil Netanjájev sin Jišmaél,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'so potem vzeli vse može in odšli, da se bojujejo z Netanjájevim sinom Jišmaélom in ga našli pri velikih vodah, ki so v Gibeónu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Pripetilo se je torej, da ko je vse ljudstvo, ki je bilo z Jišmaélom, videlo Karéahovega sina Johanána in vse poveljnike sil, ki so bili z njim, da so bili potem veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Tako se je vse ljudstvo, ki ga je Jišmaél odvedel proč ujete iz Micpe, obrnilo okrog in se vrnilo in šlo h Karéahovemu sinu Johanánu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Toda Netanjájev sin Jišmaél je od Johanána pobegnil z osmimi možmi in odšel k Amóncem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Potem so Karéahov sin Johanán in vsi poveljniki sil, ki so bili z njim, vzeli ves preostanek ljudstva, ki jih je povrnil od Netanjájevega sina Jišmaéla iz Micpe, potem, ko je umoril Ahikámovega sina Gedaljája, celó mogočne bojevnike, ženske, otroke in evnuhe, ki jih je ponovno privedel iz Gibeóna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Odrinili so in prebivali v prebivališču Kimhám, ki je pri Betlehemu, da gredo, da vstopijo v Egipt');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'zaradi Kaldejcev, kajti bali so se jih, ker je Netanjájev sin Jišmaél umoril Ahikámovega sina Gedaljája, ki ga je babilonski kralj postavil za voditelja v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Potem so se vsi poveljniki sil, Karéahov sin Johanán, Hošajájev sin Jaazanjá in vse ljudstvo, od najmanjših celo do največjih, približali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'in rekli preroku Jeremiju: »Rotimo te, naj bo naša ponižna prošnja sprejeta pred teboj in prosi za nas h Gospodu, svojemu Bogu, celó za ves ta preostanek; (kajti nas je ostalo samo malo od mnogih, kakor nas tvoje oči gledajo),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'da nam Gospod, tvoj Bog, lahko pokaže pot, po kateri lahko hodimo in stvar, ki jo lahko delamo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Potem jim je prerok Jeremija rekel: »Slišal sem vas. Glejte, molil bom za vas h Gospodu, svojemu Bogu, glede vaših besed, in zgodilo se bo, da katerokoli stvar vam bo Gospod odgovoril, vam bom to oznanil. Ničesar ne bom zadržal pred vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Potem so rekli Jeremiju: » Gospod bodi resnična in zvesta priča med nami, če ne storimo celo glede vseh stvari, zaradi katerih te je Gospod, tvoj Bog, poslal k nam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Bodisi je to dobro ali če je to zlo, ubogali bomo glas Gospoda, svojega Boga, h kateremu smo te poslali, da bo lahko dobro z nami, ko ubogamo glas Gospoda, svojega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Po desetih dneh se je pripetilo, da je beseda od Gospoda prišla k Jeremiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Potem je poklical Karéahovega sina Johanána in vse poveljnike sil, ki so bili z njim in vse ljudstvo, od najmanjšega, celo do največjega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'in jim rekel: »Tako govori Gospod, Izraelov Bog, h kateremu ste me poslali, da pred njim predložim vašo ponižno prošnjo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, '›Če boste mirno ostali v tej deželi, potem vas bom gradil in vas ne bom podiral, sadil vas bom in vas ne bom ruval, kajti pokesal sem se zla, ki sem vam ga storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne bojte se babilonskega kralja, ki se ga bojite. Ne bojte se ga,‹ govori Gospod. ›kajti jaz sem z vami, da vas rešim in da vas osvobodim iz njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Pokazal vam bom usmiljenja, da bo lahko imel usmiljenje nad vami in vam povzroči, da se vrnete k svoji lastni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Toda če rečete: ›Ne bomo prebivali v tej deželi niti ne bomo ubogali glasu Gospoda, tvojega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'rekoč: ›Ne, temveč bomo šli v egiptovsko deželo, kjer ne bomo videli nobene vojne niti slišali zvoka šofarja niti ne imeli lakote kruha in bomo tam prebivali.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Sedaj torej poslušajte Gospodovo besedo, vi, Judov ostanek: ›Tako govori Gospod nad bojevniki, Izraelov Bog: ›Če v celoti naravnate svoje obraze, da vstopite v Egipt in greste, da začasno prebivate tam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'potem se bo zgodilo, da vas bo meč, ki ste se ga bali, tam, v egiptovski deželi, dohitel in lakota, ki ste se je bali, bo tesno sledila za vami tja v Egipt, in tam boste umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Tako bo z vsemi ljudmi, ki bodo svoje obraze naravnali, da gredo v Egipt, da začasno prebivajo tam. Umrli bodo pod mečem, od lakote, od kužne bolezni in nihče izmed njih ne bo preostal ali pobegnil pred zlom, ki ga bom privedel nadnje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: ›Kakor je bila moja jeza in moja razjarjenost izlita nad prebivalce Jeruzalema, tako bo moja razjarjenost izlita nad vas, ko boste vstopili v Egipt, in vi boste preziranje, osuplost, prekletstvo in graja; in ne boste več videli tega kraja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Gospod je glede vas rekel: »Oh vi, Judov preostanek: ›Ne pojdite v Egipt. Zagotovo vedite, da sem vas ta dan opomnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Kajti pretvarjali ste se v svojih srcih, ko ste me poslali h Gospodu, svojemu Bogu, rekoč: ›Moli za nas h Gospodu, našemu Bogu in glede na vse to, kar ti bo Gospod, naš Bog, rekel, tako nam razglasi in bomo to storili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Sedaj sem vam ta dan to razglasil, toda vi niste ubogali glasu Gospoda, svojega Boga niti nobene stvari, za katero me je poslal k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Zdaj torej zagotovo vedite, da boste umrli pod mečem, od lakote in od kužne bolezni na kraju, kamor želite iti in začasno prebivati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Pripetilo se je, da ko je Jeremija končal govorjenje vsemu ljudstvu vse besede Gospoda, njihovega Boga, za katere ga je Gospod, njihov Bog, poslal k njim, celó vse te besede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'so potem spregovorili Hošajájev sin Azarjá, Karéahov sin Johanán in vsi ponosni možje, rekoč Jeremiju: »Napačno govoriš. Gospod, naš Bog, te ni poslal, da rečeš: ›Ne pojdite v Egipt, da začasno prebivate tam,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'temveč te je Nerijájev sin Baruh naravnal zoper nas, da nas izročiš v roko Kaldejcev, da bi nas oni lahko usmrtili in nas odvedli ujetnike v Babilon.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Tako Karéahov sin Johanán, vsi poveljniki sil in vse ljudstvo niso ubogali glasu Gospoda, da prebivajo v Judovi deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'temveč so Karéahov sin Johanán in vsi poveljniki sil vzeli ves Judov preostanek, ki se je vrnil iz vseh narodov, kamor so bili pognani, da prebivajo v Judovi deželi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'celó može, ženske, otroke, kraljeve hčere in vsako osebo, ki jih je Nebuzaradán, poveljnik straže, pustil z Gedaljájem, sinom Ahikáma, sinom Šafána in prerokom Jeremijem in Nerijájevim sinom Baruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Tako so prišli v egiptovsko deželo, kajti niso ubogali glasu Gospoda. Tako so prišli celó v Tahpanhés.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Potem je prišla beseda od Gospoda Jeremiju v Tahpanhésu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '»V svojo roko vzemi velike kamne in jih skrij v ilo v opekarsko peč, ki je pri vhodu faraonove hiše v Tahpanhésu, pred očmi Judovih mož');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'in jim reci: ›Tako govori Gospod nad bojevniki, Izraelov Bog: ›Glejte, poslal bom in vzel babilonskega kralja Nebukadnezarja, svojega služabnika in njegov prestol bom postavil na teh kamnih, ki sem jih skril; in on bo nad njimi razpel svoj kraljevi paviljon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'In ko pride, bo udaril egiptovsko deželo in izročil tiste, ki so za smrt, k smrti; in tiste, ki so za ujetništvo, k ujetništvu; in tiste, ki so za meč, k meču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, '§ In jaz bom prižgal ogenj v hišah egiptovskih bogov in on jih bo sežgal in jih odvedel proč ujetnike; in odel se bo z egiptovsko deželo, kakor si pastir nadene svojo obleko; in od tod bo šel naprej v miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Zlomil bo tudi podobe Bet Šemeša, ki je v egiptovski deželi; in hiše egipčanskih bogov bo sežgal z ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Beseda, ki je prišla Jeremiju glede vseh Judov, ki prebivajo v egiptovski deželi, ki prebivajo v Migdólu, v Tahpanhésu, v Nofu in v deželi Patrós, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '»Tako govori Gospod nad bojevniki, Izraelov Bog: ›Videli ste vse zlo, ki sem ga privedel nad Jeruzalem in nad vsa Judova mesta, in glejte, ta dan so ta opustošenje in noben človek ne prebiva tam');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'zaradi njihove zlobnosti, ki so jo zagrešili, da me dražijo do jeze v tem, da so odšli zažigat kadilo in da služijo drugim bogovom, ki jih niso poznali niti oni, da, niti vaši očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Vendar sem vam pošiljal vse svoje služabnike preroke, vzdigujoče zgodaj in jih pošiljal, rekoč: ›O ne storite te gnusne stvari, ki jo sovražim.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Toda niso prisluhnili niti nagnili svojega ušesa, da se odvrnejo od svoje zlobnosti, da ne bi zažigali kadila drugim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Zato sta bila moj bes in moja jeza izlita naprej in vžgana v Judovih mestih in na ulicah Jeruzalema; in ta so opustošena in zapuščena kakor ta dan.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Zaradi tega sedaj tako govori Gospod, Bog nad bojevniki, Izraelov Bog: ›Zakaj ste zagrešili to veliko zlo zoper svoje duše, da izmed sebe iztrebite moškega in žensko, otroka in dojenčka, ven iz Juda, da nikogar ne pustite, da preostane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'V čem ste me dražili do besa z deli svojih rok, zažigajoč kadilo drugim bogovom v egiptovski deželi, kamor ste odšli, da prebivate, da se lahko sami odrežete in da ste lahko prekletstvo in graja med vsemi narodi zemlje?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Mar ste pozabili zlobnost svojih očetov, zlobnost Judovih kraljev, zlobnost njihovih žena, svojo lastno zlobnost in zlobnost svojih žena, ki so jo zagrešili v Judovi deželi in na ulicah Jeruzalema?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Niso se ponižali celó do tega dne, niti se niso bali, niti hodili po moji postavi, niti po mojih zakonih, ki sem jih postavil pred vas in vaše očete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Zato tako govori Gospod nad bojevniki, Izraelov Bog: ›Glejte, svoj obraz bom naravnal zoper vas za zlo in da iztrebim vsega Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Vzel bom preostanek Juda, ki so svoje obraze naravnali, da gredo v egiptovsko deželo, da začasno prebivajo tam in vsi bodo použiti in padli v egiptovski deželi; torej použiti bodo z mečem in z lakoto. Umrli bodo, od najmanjših celo do največjih, z mečem in z lakoto, in bodo preziranje in osuplost, prekletstvo in graja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Kajti kaznoval bom tiste, ki prebivajo v egiptovski deželi, kakor sem kaznoval Jeruzalem, z mečem, z lakoto in s kužno boleznijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'tako da ne bo nihče izmed Judovega preostanka, ki so odšli v egiptovsko deželo, da začasno prebivajo tam, ušel ali preostal, da bi se vrnil v Judovo deželo, h kateri so imeli željo, da se vrnejo, da prebivajo tam. Kajti nihče se ne bo vrnil, razen tistih, ki bodo pobegnili.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Potem so vsi možje, ki so vedeli, da so njihove žene zažigale kadilo drugim bogovom in vse ženske, ki so stale poleg, velika množica, celo vse ljudstvo, ki prebiva v egiptovski deželi, v Patrósu, odgovorili Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '» Glede na besedo, ki si nam jo govoril v imenu Gospoda, ti ne bomo prisluhnili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'temveč bomo zagotovo počeli katerokoli stvar, izhajajočo iz naših lastnih ust, da zažigamo kadilo kraljici neba in da ji izlivamo pitne daritve, kakor smo počeli mi in naši očetje, naši kralji in naši princi v Judovih mestih in na ulicah Jeruzalema, kajti tedaj smo imeli obilico živeža in smo bili dobro in nismo videli zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Toda odkar smo prenehali zažigati kadilo kraljici neba in ji izlivati pitne daritve, smo bili v potrebi vseh stvari in smo použiti z mečem in z lakoto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, '»In ko smo zažigale kadilo kraljici neba in ji izlivale pitne daritve, mar smo ji naredile kolačke, da jo obožujemo in ji izlivale pitne daritve, brez naših moških?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Potem je Jeremija rekel vsemu ljudstvu, moškim in ženskam in vsemu ljudstvu, ki mu je dalo ta odgovor, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '»Kadilo, ki ste ga zažigali po Judovih mestih in po ulicah Jeruzalema, vi in vaši očetje, vaši kralji, vaši princi in ljudstvo dežele, ali se jih ni Gospod spomnil in ali to ni prišlo v njegov um?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Tako da Gospod ni mogel več trpeti zaradi zla vaših početij in zaradi ogabnosti, ki ste jih zagrešili; zato je vaša dežela opustošenje, osuplost in prekletstvo, brez prebivalca, kakor na ta dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Ker ste zažigali kadilo in ker ste grešili zoper Gospoda in niste ubogali Gospodovega glasu, niti hodili po njegovi postavi, niti po njegovih zakonih, niti po njegovih pričevanjih, zato se vam je zgodilo to zlo, kakor na ta dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Poleg tega je Jeremija rekel vsemu ljudstvu in vsem ženskam: »Poslušajte besedo od Gospoda, ves Juda, ki ste v egiptovski deželi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, '›Tako govori Gospod nad bojevniki, Izraelov Bog, rekoč: ›Vi in vaše žene ste tako govorili s svojimi usti in s svojo roko izpolnili, rekoč: ›Zagotovo bomo izvajali svoje zaobljube, ki smo se jih zaobljubili, da zažigamo kadilo kraljici neba in da ji izlivamo pitne daritve.‹ Zagotovo boste dokončali svoje zaobljube in zagotovo boste izvedli svoje zaobljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Zato poslušajte besedo od Gospoda, ves Juda, ki prebiva v egiptovski deželi: ›Glejte, prisegel sem pri svojem velikem imenu,‹ govori Gospod, ›da moje ime ne bo več imenovano v ustih kateregakoli moškega iz Juda in po vsej egiptovski deželi, rekoč: ›Gospod Bog živi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Glej, bedel bom nad njimi za zlo in ne za dobro; in vsi Judovi možje, ki so v egiptovski deželi, bodo použiti z mečem in z lakoto, dokler jih ne bo konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Vendar se bo malo število, ki pobegne meču, vrnilo iz egiptovske dežele v Judovo deželo in ves preostanek Juda, ki so odšli v egiptovsko deželo, da tam začasno prebiva, bo vedel čigave besede bodo obstale, moje ali njihove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'To vam bo znamenje,‹ govori Gospod, ›da vas bom kaznoval na tem kraju, da boste lahko vedeli, da bodo moje besede zagotovo obstale zoper vas v zlo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Tako govori Gospod: ›Glejte, izročil bom faraona Hofrája, egiptovskega kralja, v roko njegovih sovražnikov in v roko tistih, ki strežejo po njegovem življenju, kakor sem Judovega kralja Sedekíja izročil v roko babilonskega kralja Nebukadnezarja, njegovega sovražnika in ki je stregel po njegovem življenju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Beseda, ki jo je prerok Jeremija spregovoril Nerijájevemu sinu Baruhu, ko je zapisal te besede v knjigo pri Jeremijevih ustih, v četrtem letu Jojakíma, Jošíjevega sina, Judovega kralja, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '»Tako govori Gospod, Izraelov Bog, tebi, oh Baruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Rekel si: ›Gorje mi sedaj! Kajti Gospod je dodal žalost k moji bridkosti; oslabel sem v svojem vzdihovanju in ne najdem počitka.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tako mu boš rekel: › Gospod tako govori: ›Glej, to, kar sem zgradil, bom porušil in to, kar sem zasadil, bom izruval, celo to celotno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'In ti zase iščeš velike stvari? Ne išči jih, kajti glej, privedel bom zlo nad vse meso,‹ govori Gospod, ›toda tvoje življenje ti bom dal za plen v vseh krajih, kamor greš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Beseda od Gospoda, ki je prišla preroku Jeremiju zoper pogane;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'zoper Egipt, zoper vojsko faraona Nehota, egiptovskega kralja, ki je bil pri reki Evfratu v Kárkemišu, ki ga je babilonski kralj Nebukadnezar udaril v četrtem letu Jojakíma, Jošíjevega sina, Judovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '»›Pripravite majhen ščit in ščit ter se približajte boju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Vprezite konje in vstanite, vi konjeniki in postavite se s svojimi čeladami; zgladite sulice in si nadenite oklepe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Zakaj sem jih videl zaprepadene in obrnjene nazaj? In njihovi mogočni so potolčeni in so naglo zbežali in niso gledali nazaj, kajti strah je bil naokoli,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '›Ne dopusti, da hitri izgine niti da mogočni človek pobegne; opotekali se bodo in padali proti severu, pri reki Evfratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kdo je ta, ki prihaja gor kakor poplava, katerega vode se premikajo kakor reke?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egipt se vzdiguje kakor poplava in njegove vode se premikajo kakor reke; in pravi: ›Šel bom gor in pokril zemljo, uničil bom mesto in njegove prebivalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Pridite gor, vi konji; in besnite, vi bojni vozovi in naj mogočni možje pridejo naprej. Etiopijci in Libijci, ki prijemajo ščit; in Ludéjci, ki prijemajo in napenjajo lok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Kajti to je dan Gospoda Boga nad bojevniki, dan maščevanja, da se lahko maščuje svojim nasprotnikom in meč bo požiral in ta bo nasičen in opijanjen z njihovo krvjo, kajti Gospod Bog nad bojevniki ima klavno daritev v severni deželi, pri reki Evfratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Pojdi gor v Gileád in vzemi balzam, oh devica, egiptovska hči. Zaman boš uporabljala mnoga zdravila, kajti ne boš ozdravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Narodi so slišali o tvoji sramoti in tvoje vpitje je napolnilo deželo, kajti mogočen človek se je spotaknil zoper mogočnega in oba skupaj sta padla.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Beseda, ki jo je Gospod spregovoril preroku Jeremiju, kako bo babilonski kralj Nebukadnezar prišel in udaril egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '›Oznanite v Egiptu, razglasite v Migdólu, razglasite v Nofu in v Tahpanhésu, recite: ›Stoj trdno in se pripravi, kajti meč bo požiral okoli tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Zakaj so tvoji hrabri možje pometeni proč? Niso obstali, ker jih je Gospod pognal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Mnoge je pripravil, da padejo, da, eden je padel na drugega. Rekli so: ›Vstanimo in ponovno pojdimo k svojemu ljudstvu in k deželi svojega rojstva, proč od zatiralskega meča.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Tam so vpili: ›Faraon, egiptovski kralj, je samo hrup; zamudil je določeni čas.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, '› Kakor jaz živim,‹ govori Kralj, čigar ime je Gospod nad bojevniki: ›Zagotovo, kakor je Tabor med gorami in kakor Karmel pri morju, tako bo on prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Oh ti hči, prebivajoča v Egiptu, oskrbi se, da greš v ujetništvo, kajti Nof bo opustošen in zapuščen, brez prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egipt je podoben zelo lepi telici, toda uničenje prihaja; to prihaja iz severa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Prav tako so njegovi najeti možje v njegovi sredi podobni pitanim bikcem; kajti obrnjeni so tudi nazaj in skupaj so pobegnili proč; niso obstali, ker je nadnje prišel dan njihove katastrofe in čas njihovega obiskanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Njihov glas bo šel kakor kača; kajti korakali bodo z vojsko in zoper njega bodo prišli s sekirami kakor drvarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Posekali bodo njegov gozd,‹ govori Gospod, ›čeprav ta ne more biti preiskan, ker jih je več kakor kobilic in so brezštevilni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Egiptovska hči bo zbegana; izročena bo v roko severnega ljudstva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Gospod nad bojevniki, Izraelov Bog, pravi: ›Glejte, kaznoval bom množico iz Noja in faraona in Egipt z njihovimi bogovi in njihovimi kralji, celo faraona in vse tiste, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Izročil jih bom v roko tistih, ki jim strežejo po življenju, v roko babilonskega kralja Nebukadnezarja in v roko njegovih služabnikov. Potem bo ta naseljen kakor v dneh davnine,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, '›Vendar se ne boj, oh moj služabnik Jakob in ne bodi zaprepaden, oh Izrael, kajti glej, rešil te bom od daleč in tvoje seme iz dežele njihovega ujetništva. Jakob se bo vrnil in bo počival in bo sproščen in nihče ga ne bo naredil prestrašenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ne boj se, Jakob, moj služabnik,‹ govori Gospod, ›kajti jaz sem s teboj, kajti naredil bom popoln konec vseh narodov, kamor sem te pognal. Toda iz tebe ne bom naredil popolnega konca, temveč te bom grajal po meri; vendar te ne bom pustil v celoti nekaznovanega.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Beseda od Gospoda, ki je prišla preroku Jeremiju zoper Filistejce, preden je faraon udaril Gazo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, '»Tako govori Gospod: ›Glej, vode se dvigujejo iz severa in bodo preplavljajoča poplava in bodo poplavile deželo in vse, kar je v njej; mesto in tiste, ki prebivajo v njem. Potem bodo ljudje jokali in vsi prebivalci dežele bodo tulili');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'ob hrupu topotanja kopit njegovih močnih konj, ob drvenju njegovih bojnih voz in ob hrumenju njegovih koles. Očetje ne bodo gledali nazaj k svojim otrokom zaradi slabotnosti rok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'zaradi dneva, ki prihaja, da opleni vse Filistejce in da iztrebi iz Tira in Sidóna vsakega pomočnika, ki preostaja, kajti Gospod bo oplenil Filistejce, ostanek dežele Kaftor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Plešavost je prišla nad Gazo; Aškelón je iztrebljen s preostankom njihove doline. Doklej boš zarezoval samega sebe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Oh ti, Gospodov meč, kako dolgo bo trajalo, preden boš tiho? Spravi se v svojo nožnico, počivaj in bodi miren.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Kako je lahko tiho, glede na to, da mu je Gospod dal naročilo zoper Aškelón in zoper morsko obalo? Tam ga je on določil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, '§ Zoper Moáb tako govori Gospod nad bojevniki, Izraelov Bog: »Gorje Nebóju! Kajti ta je oplenjen. Kirjatájim je zbegan in zavzet. Misgab je zbegan in zaprepaden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moábove hvale ne bo več. V Hešbónu so snovali zlo zoper njega; pridimo in iztrebimo ga pred tem, da bi bil narod. Tudi ti boš iztrebljen, o Madmén; meč te bo preganjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Glas vpitja bo iz Horonájima, plenjenje in veliko uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moáb je uničen; njegovi malčki so storili, da se je slišal jok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Kajti ob vzpenjanju Luhíta se bo vzdigovalo nenehno jokanje, kajti ob spuščanju Horonájima so sovražniki slišali krik pogube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, '§ Pobegnite, rešite svoja življenja in bodite podobni brinu v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Kajti ker si zaupal v svoja dela in svoje zaklade, boš tudi ti zajet. Kemoš bo šel naprej v ujetništvo skupaj s svojimi duhovniki in svojimi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Plenilec bo prišel nad vsako mesto in nobeno mesto ne bo uteklo. Tudi dolina bo propadla in ravnina bo uničena, kakor je govoril Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Daj peruti Moábu, da bo lahko pobegnil in ušel, kajti njegova mesta bodo zapuščena, brez kogarkoli, da bi v njih prebival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Preklet bodi, kdor dela Gospodovo delo varljivo in preklet bodi, kdor svoj meč zadržuje od krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moáb je bil sproščen od svoje mladosti in se ustalil na svojih drožeh in ni bil izpraznjen iz posode v posodo niti ni šel v ujetništvo. Zato bo njegov okus ostal v njem in njegova vonjava ni spremenjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, '§ Zato, glej, prihajajo dnevi,‹ govori Gospod, ›ko bom k njemu poslal postopače, ki mu bodo povzročili, da se potepa in izpraznili bodo njegove posode in počili njihove mehove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Moáb se bo sramoval Kemoša, kakor se je Izraelova hiša sramovala Betela, njihovega zaupanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kako pravite: ›Mi smo mogočni in močni možje za vojno?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, '§ Moáb je oplenjen in odšel gor iz svojih mest in njegovi izbrani mladeniči so odšli dol k pokolu,‹ govori Kralj, katerega ime je Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Blizu je Moábova katastrofa, da pride in njegova stiska silno hiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Vsi vi, ki ste okoli njega, žalujte za njim; in vsi vi, ki poznate njegovo ime, recite; ›Kako je močna opora zlomljena in krasna palica!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Ti hči, ki poseljuješ Dibón, pridi dol iz svoje slave in sédi v žeji; kajti plenilec Moába bo prišel nadte in ta bo uničil tvoja oporišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Oh prebivalec Aroêrja, stoj ob poti in oprezaj; in vprašaj tistega, ki beži in tisto, ki pobegne ter reci: ›Kaj se je zgodilo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moáb je zbegan, kajti zlomljen je. Tulite in vpijte. Povejte v Arnónu, da je Moáb oplenjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Sodba je prišla nad ravno deželo; nad Holón, nad Jahac, nad Mefáat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'nad Dibón, nad Nebó, nad Bet Diblatájim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'nad Kirjatájim, nad Bet Gamúl, nad Bet Meón,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'nad Kerijót, nad Bocro in nad vsa mesta moábske dežele, daljna ali bližnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Moábov rog je odsekan in njegov laket je zlomljen,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, '›Opijanite ga, kajti poveličal se je zoper Gospoda. Tudi Moáb se bo valjal v svojem izbljuvku in tudi on bo v posmeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, '§ Mar vam ni bil Izrael v posmeh? Je bil najden med tatovi? Kajti odkar govoriš o njem, poskakuješ od veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Oh vi, ki prebivate v Moábu, zapustite mesta in prebivajte na skali in bodite podobni golobici, ki dela svoje gnezdo na straneh ustja luknje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Slišali smo ponos Moába (on je silno ponosen), njegovo nadutost, njegovo aroganco, njegov ponos in oholost njegovega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Poznam njegov bes,‹ govori Gospod; ›toda to ne bo tako; njegove laži na to ne bodo tako vplivale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Zato bom tulil zaradi Moába in vpil zaradi vsega Moába; moje srce bo žalovalo zaradi mož iz Kir Hêresa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Oh sibmanska trta, jokal bom za teboj z jokanjem Jazêrja. Tvoje rastline so odšle prek morja, segle so celó k jazêrskemu morju. Plenilec je padel na tvoje poletne sadove in na tvojo trgatev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Radost in veselje sta vzeta iz obilnega polja moábske dežele. Trti sem velel, da odpove pred vinskimi stiskalnicami. Nihče ne bo mendral z vriskanjem; njihovo vriskanje ne bo vriskanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, '§ Od krika Hešbóna, celó do Elaléja in celó do Jahaca so izgovarjali svoj glas, od Coarja celó do Horonájima, kakor triletna telica, kajti tudi nimrímske vode bodo zapuščene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Poleg tega bom povzročil, da odneha v Moábu,‹ govori Gospod, ›kdor daruje na visokih krajih in kdor zažiga kadilo svojim bogovom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Zato bo moje srce ihtelo kakor piščali za Moábom in moje srce bo ihtelo kakor piščali za možmi Kir Hêresa, ker so bogastva, ki jih je pridobil, izginila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Kajti vsaka glava bo plešasta in vsaka brada pristrižena. Na vseh rokah bodo vrezi in na ledjih vrečevina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Tam bo splošno žalovanje na vseh hišnih strehah Moába in na njegovih ulicah, kajti zlomil sem Moáb kakor posodo, v kateri ni zadovoljstva,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Tulili bodo, rekoč: »Kako je ta zlomljen! Kako je Moáb s sramoto obrnil hrbet! Tako bo Moáb v posmeh in zaprepadenost vsem okoli njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Kajti tako govori Gospod: ›Glej, letel bo kot orel in svoje peruti bo širil nad Moábom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijót je zavzet, oporišča so presenečena in srca mogočnih mož v Moábu bodo na ta dan kakor srce ženske v njenih ostrih bolečinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Moáb bo uničen pred tem, da bi bil ljudstvo, ker se je poveličeval zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Strah, jama in zanka bodo nad teboj, oh prebivalec Moába,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, '›Kdor beži pred strahom, bo padel v jamo, in kdor vstaja iz jame, bo zajet v zanko, kajti jaz bom to privedel nadenj, celó nad Moáb, leto njihovega obiskanja,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, '›Tisti, ki so zbežali, so stali pod hešbónsko senco zaradi sile. Toda ogenj bo izšel iz Hešbóna, plamen iz srede Sihóna in použil bo Moábov kot in tême upornih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Gorje tebi, oh Moáb! Ljudstvo Kemoša se pogublja, kajti tvoji sinovi so zajeti [kot] ujetniki in tvoje hčere [kot] ujetnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Vendar bom v zadnjih dneh ponovno privedel Moábovo ujetništvo,‹ govori Gospod. ›Tako daleč je sodba od Moába.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Glede Amóncev tako govori Gospod: »Mar Izrael nima sinov? Mar nima dediča? Zakaj potem njihovi kralji podedujejo Gad in njegovo ljudstvo prebiva v njegovih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Zatorej, glejte, pridejo dnevi,‹ govori Gospod, ›ko bom povzročil alarm vojne, da se bo slišal v Rabi Amóncev in ta bo zapuščen kup in njene hčere bodo požgane z ognjem. Potem bo Izrael dedič tistim, ki so bili njegovi dediči,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Tuli, oh Hešbón, kajti Aj je oplenjen. Jokajte ve Rabine hčere, opašite se z vrečevino; objokujte in tecite sem ter tja pri ograjah; kajti njihov kralj bo šel v ujetništvo skupaj z njegovimi duhovniki in njegovimi princi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Zakaj se ponašaš z dolinami, tvoji tekoči dolini, oh odpadla hči, ki si zaupala v svoje zaklade, rekoč: ›Kdo bo prišel k meni?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Glej, nadte bom privedel strah,‹ govori Gospod Bog nad bojevniki, ›od vseh teh, ki bodo okoli tebe. Izgnani boste, vsak človek naravnost naprej in nihče ne bo zbral tistega, ki tava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Potem bom ponovno privedel ujetništvo Amónovih otrok,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Glede Edóma tako govori Gospod nad bojevniki: › Mar v Temánu ni več modrosti? Je nasvet izginil pred razsodnim? Je njihova modrost izginila?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Pobegnite, obrnite se nazaj, prebivajte globoko, oh prebivalci Dedána; kajti nadenj bom privedel Ezavovo katastrofo, čas, ko ga bom obiskal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Če pridejo k tebi obiralci grozdja, ali ne bodo pustili nekaj paberkovalnih grozdov? Če tatovi ponoči, bodo uničevali, dokler ne bodo imeli dovolj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Toda jaz sem naredil Ezava razgaljenega, jaz sem odkril njegove skrite kraje in se ne bo mogel skriti. Njegovo seme je oplenjeno in njegovih bratov, njegovih sosedov in njega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Pusti svoje osirotele otroke, jaz jih bom ohranil žive; in tvoje vdove naj zaupajo vame.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Kajti tako govori Gospod: ›Glej, tisti, katerih sodba ni bila, da pijejo iz čaše, so zagotovo pijani; in ali si ti tisti, ki naj bi odšel čisto nekaznovan? Ne boš odšel nekaznovan, temveč boš zagotovo pil od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Kajti prisegel sem sam pri sebi,‹ govori Gospod, ›da bo Bocra postala opustošenje, graja, opustošenost in prekletstvo in vsa njena mesta bodo neprestane opustošenosti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Slišal sem govorico od Gospoda in predstavnik je poslan k poganom, rekoč: »Zberite se skupaj in pridite zoper njo in se vzdignite k bitki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '›Kajti glej, naredil te bom majhnega med pogani in preziranega med ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Tvoja strašnost te je zavedla in ponos tvojega srca, oh ti, ki prebivaš v skalnih razpokah, ki držiš višino hriba. Čeprav bi si svoje gnezdo naredil tako visoko kakor orel, te bom od tam privedel dol,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, '›Tudi Edóm bo opustošenje. Vsak, kdor gre mimo, bo osupel in sikal bo nad vsemi njegovimi nadlogami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Kakor v razdejanju Sódome in Gomóre in njunih sosednjih mest,‹ govori Gospod, ›noben človek ne bo vzdržal tam niti človeški sin ne bo prebival v tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Glej, vzpel se bo kakor lev iz naraščanja Jordana zoper prebivališče močnega. Toda naredil bom, da bo nenadoma pobegnil pred njo. In kdo je izbran mož, da bi ga lahko določil nad njo? Kajti kdo je podoben meni? In kdo mi bo določil čas? In kdo je tisti pastir, ki bo stal pred menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Zato prisluhnite Gospodovemu nasvetu, ki ga je svetoval zoper Edóm; in njegove namene, ki jih je namenil zoper prebivalce Temána: ›Zagotovo jih bo najmanjši iz tropa izvlekel ven. Zagotovo bo naredil njihova prebivališča opustela z njimi [vred].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Zemlja je stresena ob hrupu njihovega padca, ob hrupu njihovega krika, ki ga je bilo slišati na Rdečem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Glej, prišel bo gor in letel kakor orel in svoji peruti razširil nad Bocro in na ta dan bo srce mogočnih mož iz Edóma kakor srce ženske v njenih ostrih bolečinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Glede Damaska. Hamát je zbegan in Arpád, kajti slišala sta zle novice. Boječa sta. Tam je bridkost na morju; ta ne more biti utišana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damask je postal slaboten in se obrača, da pobegne in strah se ga je polastil. Tesnoba in bridkosti so ga prevzele kakor žensko v porodnih mukah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kako mesto hvale ni zapuščeno, mesto moje radosti!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Zato bodo njegovi mladeniči padli na njegovih ulicah in vsi bojevniki bodo iztrebljeni na ta dan,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, '›Zanetil bom ogenj v zidu Damaska in ta bo použil palače Ben Hadáda.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, '§ Glede Kedárja in glede Hacórjevih kraljestev, ki jih bo babilonski kralj Nebukadnezar udaril, tako govori Gospod: ›Vstanite, pojdite gor v Kedár in oplenite može vzhoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Njihove šotore in njihove trope bodo odvzeli. K sebi bodo vzeli njihove zavese in vse njihove posode in njihove kamele; in vpili jim bodo: ›Strah je na vsaki strani.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Pobegnite, odpravite se daleč proč, prebivajte globoko, oh vi prebivalci Hacórja,‹ govori Gospod; ›kajti babilonski kralj Nebukadnezar je zoper vas sprejel nasvet in je zoper vas spočel namen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Vstani, spravi se gor k premožnemu narodu, ki prebiva brez skrbi,‹ govori Gospod, ›ki nima niti velikih vrat niti zapahov, ki prebiva sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'In njihove kamele bodo plen in množica njihove živine plen, in razkropil jih bom na vse vetrove, tiste, ki so na skrajnih vogalih; in jaz bom privedel njihovo katastrofo od vseh njihovih strani,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Hacór bo prebivališče za zmaje in opustošenje na veke. Tam ne bo prebival noben človek niti noben človeški sin ne prebiva v njem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Beseda od Gospoda, ki je prišla preroku Jeremiju zoper Elám v začetku kraljevanja Judovega kralja Sedekíja, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '»Tako govori Gospod nad bojevniki: ›Glej, jaz bom zlomil Elámov lok, njihovo glavno moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Nad Elám bom privedel štiri vetrove iz štirih četrtin neba in razkropil jih bom proti vsem tem vetrovom; in tam ne bo nobenega naroda, kamor ne bi prišli pregnanci Eláma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Kajti Elámu bom povzročil, da bo zaprepaden pred svojimi sovražniki in pred tistimi, ki jim strežejo po življenju, in nanje bom privedel zlo, celó svojo kruto jezo,‹ govori Gospod: ›in za njimi bom poslal meč, dokler jih ne bom použil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Svoj prestol bom postavil v Elámu in od tam bom uničil kralja in prince,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, '›Toda to se bo zgodilo v zadnjih dneh, da bom ponovno privedel ujetništvo Eláma,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Beseda, ki jo je Gospod govoril zoper Babilon in zoper deželo Kaldejcev po preroku Jeremiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Razglašajte med narodi in objavite in postavite prapor; objavite in ne prikrivajte. Recite: ›Babilon je zajet, Bel je zbegan, Merodáh je zlomljen na koščke; njegovi maliki so zbegani, njegove podobe so zlomljene na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Kajti iz severa prihaja narod zoper njega, ki bo njegovo deželo naredil zapuščeno in nihče ne bo prebival tam. Odstranjeni bodo, odšli bodo, tako človek kakor žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'V tistih dneh in v tistem času,‹ govori Gospod, ›bodo prišli Izraelovi otroci, oni in Judovi otroci skupaj, šli bodo in jokali. Šli bodo in iskali Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Povpraševali bodo o poti na Sion, s svojimi obrazi tja, rekoč: ›Pridite, pridružimo se Gospodu z večno zavezo, ki ne bo pozabljena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Moje ljudstvo so bile izgubljene ovce. Njihovi pastirji so jim povzročili, da zaidejo, obrnili so jih proč na gore. Tavali so od gore do hriba, pozabili so svoj kraj počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Vsi, ki so jih našli, so jih požrli, in njihovi nasprotniki so rekli: ›Ne delamo prestopka, ker so grešili zoper Gospoda, prebivališče pravice, celo Gospoda, upanje njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Odstranite se iz srede Babilona in pojdite naprej, ven iz dežele Kaldejcev in bodite kakor kozli pred tropi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Kajti glejte, vzdignil se bom in povzročim, da pride proti Babilonu zbor velikih narodov iz severne dežele, in postrojili se bodo zoper njega; od tam bo zavzet. Njihove puščice bodo kakor od mogočnega, izkušenega človeka; nihče se ne bo vračal zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'In Kaldeja bo plen; vsi, ki jo plenijo, bodo nasičeni,‹ ›govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, '§ ›Ker ste bili veseli, ker ste se razveseljevali, oh vi uničevalci moje dediščine, ker ste postali debeli kakor telica ob travi in mukate kakor biki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'vaša mati bo silno zbegana; tista, ki vas je nosila, bo osramočena. Glejte, najbolj zadnji izmed narodov bodo divjina, suha dežela in puščava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Zaradi Gospodovega besa ta ne bo naseljena, temveč bo v celoti zapuščena. Vsak, kdor gre mimo Babilona, bo osupel in sikal bo ob vseh njegovih nadlogah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Postrojite se naokrog zoper Babilon. Vsi vi, ki upogibate lok, streljajte nanj. Ne varčujte puščic, kajti grešil je zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Vpijte zoper njega vsenaokrog. Dal je svojo roko. Njegovi temelji so padli, njegovi zidovi so zrušeni, kajti to je maščevanje od Gospoda. Maščujte se nad njim, kajti kakor je storil on, storite njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Iztrebi sejalca iz Babilona in tistega, ki ravna s srpom ob času žetve. Zaradi strahu pred zatiralskim mečem se bodo obrnili vsakdo k svojemu ljudstvu in bežali bodo vsakdo k svoji lastni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Izrael je razkropljena ovca; levi so jo odgnali proč. Najprej jo je požrl kralj Asirije in nazadnje je ta babilonski kralj Nebukadnezar zlomil njene kosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Zato tako govori Gospod nad bojevniki, Izraelov Bog: ›Glej, kaznoval bom babilonskega kralja in njegovo deželo, kakor sem kaznoval asirskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Izrael bom ponovno privedel k njegovemu prebivališču in pasel se bo na Karmelu in Bašánu in njegova duša bo nasičena na gori Efrájim in Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'V tistih dneh in v tistem času,‹ govori Gospod, ›bo iskana krivičnost Izraela, tam pa ne bo nobene; in Judovi grehi in le-ti ne bodo najdeni, kajti jaz bom oprostil tiste, ki sem jih prihranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, '§ Pojdi gor zoper deželo Meratájim, celó zoper njo in zoper prebivalce Pekóda. Pustoši in popolnoma uniči za njimi,‹ govori Gospod ›in stori glede na vse, kar sem ti zapovedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Zvok bitke in velikega uničenja je v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kako je kladivo celotne zemlje razklano in zlomljeno! Kako je Babilon postal opustošenje med narodi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Zate sem položil zanko in ti si prav tako zajet, oh Babilon in se nisi zavedal. Najden si in prav tako ujet, ker si se prepiral zoper Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Gospod je odprl svojo orožarno in privedel orožja svojega ogorčenja, kajti to je delo od Gospoda Boga nad bojevniki v deželi Kaldejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Pridite zoper njega od skrajne meje, odprite njegova skladišča. Nagrmadite ga kakor kupe in ga popolnoma uničite. Nič naj ne ostane od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Zakoljite vse njegove bikce; naj gredo dol k zakolu. Gorje jim! Kajti prišel je njihov dan, čas njihovega obiskanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Glas tistih, ki bežijo in pobegnejo iz babilonske dežele, da razglasijo na Sionu maščevanje Gospoda, našega Boga, maščevanje njegovega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Skliči skupaj lokostrelce zoper Babilon in vse, ki upogibajo lok, utabori se zoper njega vsenaokrog; naj nihče od njega ne pobegne. Poplačajte mu glede na njegovo delo; glede na vse, kar je storil, storite vi njemu; kajti ponosen je bil zoper Gospoda, zoper Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Zato bodo njegovi mladeniči padli na ulicah in vsi njegovi bojevniki bodo na tisti dan odrezani,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '›Glej, jaz sem zoper tebe, oh ti, najponosnejši, govori Gospod Bog nad bojevniki, kajti tvoj dan je prišel, čas, da te obiščem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Najponosnejši se bo spotaknil in padel in nihče ga ne bo dvignil. Prižgal bom ogenj v njegovih mestih in ta bo požrl vse naokoli njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tako govori Gospod nad bojevniki: ›Izraelovi otroci in Judovi otroci so bili skupaj zatirani, in vsi, ki so jih vzeli [za] ujetnike, so jih trdno držali; odklonili so, da jih izpustijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Njihov Odkupitelj je močan; Gospod nad bojevniki je njegovo ime. Temeljito bo zagovarjal njihovo pravdo, da bi lahko dal počitek deželi in vznemiril babilonske prebivalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Meč je nad Kaldejci,‹ govori Gospod ›in nad prebivalci Babilona in nad njegovimi princi in nad njegovimi modrimi možmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Meč je na lažnivcih; in oni bodo nori. Meč je nad njegovimi mogočnimi možmi; in oni bodo zaprepadeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Meč je nad njihovimi konji in nad njihovimi bojnimi vozovi in nad vsemi pomešanimi ljudstvi, ki so v njegovi sredi; in postali bodo kakor ženske. Meč je nad njegovimi zakladi; in oni bodo oropani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Suša je nad njegovimi vodami; in posušene bodo, kajti to je dežela rezanih podob in oni so usekani na svoje malike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Zato bodo tam živele divje živali iz puščave z divjimi živalmi z otokov in sove bodo prebivale tam, in ta ne bo več naseljen na veke; niti ne bo od roda do roda naseljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Kakor je Bog razdejal Sódomo in Gomóro in njuna sosednja mesta,‹ govori Gospod; › tako noben človek ne bo ostajal tam niti človeški sin ne bo prebival tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Glej, ljudstvo bo prišlo iz severa in velik narod in številni kralji bodo vzdignjeni od obal zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Držali bodo lok in sulico. Kruti so in ne bodo pokazali usmiljenja. Njihov glas bo rjovel kakor morje in jahali bodo na konjih, vsakdo postrojen, kakor mož k bitki, zoper tebe, oh babilonska hči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Babilonski kralj je slišal poročilo o njih in njegovi roki sta oslabeli. Tesnoba se ga je polastila in ostre bolečine, kakor žensko v porodnih mukah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, '§ Glej, prišel bo gor kakor lev iz naraščanja Jordana k prebivališču močnega, toda storil bom, da bodo nenadoma pobegnili proč pred njim. In kdo je izbran mož, da bi ga lahko določil čezenj? Kajti kdo je podoben meni? In kdo mi bo določil čas? In kdo je tisti pastir, ki bo stal pred menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Zato prisluhnite Gospodovemu nasvetu, ki ga je sprejel zoper Babilon; in njegovim namenom, ki jih je namenil zoper deželo Kaldejcev: ›Zagotovo bodo najmanjše izmed tropa potegnili ven. Zagotovo bo njihovo prebivališče naredil zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Ob hrupu zajetja Babilona je zemlja stresena in krik je slišati med narodi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tako govori Gospod: »Glej, vzdignil se bom zoper Babilon in zoper tiste, ki prebivajo v njihovi sredi, ki se vzdigujejo zoper mene, rušilni veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'V Babilon bom poslal prepihovalce, ki ga bodo prevejáli in izpraznili bodo njegovo deželo, kajti v dnevu stiske bodo zoper njega naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Zoper tistega, ki napenja, naj lokostrelec napne svoj lok in zoper tistega, ki se dviguje v svojem oklepu in ne prizanašajte njegovim mladeničem. Popolnoma uničite vso njegovo vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Tako bodo umorjeni padli v deželi Kaldejcev in tisti, ki so prebodeni, na njegovih ulicah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, '§ Kajti Izrael ni bil pozabljen niti Juda od svojega Boga, od Gospoda nad bojevniki; čeprav je bila njihova dežela napolnjena z grehom zoper Svetega Izraelovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Bežite iz srede Babilona in osvobodite vsakdo svojo dušo. Ne bodite odrezani v njegovi krivičnosti, kajti to je čas Gospodovega maščevanja; on mu bo povrnil povračilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babilon je bil zlata čaša v Gospodovi roki, ki je vso zemljo opijanil. Narodi so pili od njegovega vina; zato so narodi besni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Babilon je nenadoma padel in bil uničen. Tulite za njim; vzemite balzam za njegovo bolečino, če bo tako, da bi bil lahko ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Ozdravili bi Babilon, toda ta ni ozdravljen. Zapustite ga in naj gremo vsak v svojo lastno deželo, kajti njegova sodba sega do nebes in povzdignjen je gor, celó do neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Gospod je privedel našo pravičnost. Pridite, razglasimo na Sionu delo Gospoda, našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Puščice naredi svetle; zberi ščite. Gospod je vzdignil duha medijskih kraljev, kajti njegov naklep je zoper Babilon, da ga uniči, kajti to je to maščevanje od Gospoda, maščevanje od njegovega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Postavi prapor na zidove Babilona, okrepi stražo, postavi stražarje, pripravi zasede, kajti Gospod je tako zasnoval in storil to, kar je govoril, zoper prebivalce Babilona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Oh ti, ki prebivaš nad mnogimi vodami, obilen v zakladih, tvoj konec je prišel in mera tvoje pohlepnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Gospod nad bojevniki je prisegel pri samem sebi, rekoč: »Zagotovo te bom napolnil z ljudmi kakor z gosenicami; in vzdignili bodo krik zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Zemljo je naredil s svojo močjo, zemeljski [krog] je utrdil s svojo modrostjo in nebesa razprostrl s svojo razumnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kadar on izusti svoj glas, je na nebu množica vodá; in on povzroča meglicam, da se vzdignejo od koncev zemlje. On dela bliske z dežjem in prinaša veter iz svojih zakladnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Vsak mož je s svojim spoznanjem brutalen, vsak livar je osramočen z rezano podobo, kajti njegova ulita podoba je neresnica in ni diha v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Te so ničevosti, delo zmot. V času njihovega obiskanja bodo izginile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Jakobov delež ni enak njihovemu; kajti on je tvorec vseh stvari, in Izrael je palica njegove dediščine. Gospod nad bojevniki je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Ti si moja bojna sekira in bojna orožja, kajti s teboj bom narode razbil na koščke in s teboj bom uničil kraljestva;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'in s teboj bom razbil na koščke konja in njegovega jezdeca; in s teboj bom razbil na koščke bojni voz in njegovega voznika;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 's teboj bom razbil na koščke moškega in žensko; in s teboj bom razbil na koščke starega in mladega; in s teboj bom razbil na koščke mladeniča in deklo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'prav tako bom s teboj razbil na koščke pastirja in njegov trop; in s teboj bom razbil na koščke poljedelca in njegov jarem volov; in s teboj bom razbil na koščke poveljnike in vladarje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'In povrnil bom Babilonu in vsem prebivalcem Kaldeje vse njihovo zlo, ki so ga storili na Sionu v vašem pogledu,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, '›Glej, jaz sem zoper tebe, oh uničujoča gora,‹ govori Gospod, ›ki uničuješ vso zemljo. Svojo roko bom iztegnil nadte in te zvalil dol iz skal in te naredil požgano goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'In ne bodo vzeli od tebe kamna za temeljni kamen niti kamna za temelje; temveč boš zapuščena na veke,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Postavite prapor v deželi, zatrobite na šofar med narodi, pripravite narode zoper njega, skličite skupaj zoper njega kraljestva Ararát, Miní in Aškenáz; določite poveljnika zoper njega; naredite konjem, da pridejo gor kakor dlakave gosenice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Pripravite zoper njega narode s kralji iz Medije, njihove poveljnike, vse njihove vladarje in vso deželo njegovega gospostva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'In dežela bo trepetala in tarnala, kajti vsak Gospodov namen zoper Babilon se bo izpolnil, da stori babilonsko deželo opustošenje brez prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Mogočni babilonski možje so se prenehali bojevati, ostali so v svojih utrdbah. Njihova moč je odpovedala; postali so kakor ženske. Požgali so njegova bivališča; njegovi zapahi so zlomljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'En tekač bo tekel, da sreča drugega in en poslanec, da sreča drugega, da pokaže babilonskemu kralju, da je njegovo mesto zavzeto na enem koncu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'in da so prehodi osvojeni in trstje so požgali z ognjem in bojevniki so zgroženi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Kajti tako govori Gospod nad bojevniki, Izraelov Bog: ›Babilonska hči je podobna mlatišču, čas je, da jo mlatijo, vendar še malo in čas njene žetve bo prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Babilonski kralj Nebukadnezar me je požrl, zdrobil me je, naredil me je za prazno posodo, požrl me je kakor zmaj, svoj trebuh je napolnil z mojimi posladki, vrgel me je ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, '›Nasilje, storjeno meni in mojemu mesu, naj bo nad Babilonom;‹ bo rekel prebivalec Siona in moja kri nad prebivalci Kaldeje, bo rekla [prestolnica] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Zato tako govori Gospod: ›Glej, jaz bom zagovarjal tvojo pravdo in se zate maščeval; posušil bom njegovo morje in posušil njegove izvire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'In Babilon bo spremenjen v razvaline, bivališče za zmaje, osuplost in posmeh, brez prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Skupaj bodo rjoveli kakor levi. Kričali bodo kakor levji mladiči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'V njihovi vročini bom naredil njihove praznike in jaz jih bom opijanil, da se bodo lahko veselili in zaspali nenehno spanje in se ne bodo zbudili,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, '›Privedel jih bom dol kakor jagnjeta h klanju, kakor ovne s kozli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kako je Šešáh zajet! In kako je hvala celotne zemlje presenečena! Kako je Babilon postal osuplost med narodi!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Morje se je vzdignilo nad Babilon. Pokrit je z množico njegovih valov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Njegova mesta so opustošenje, suha dežela in divjina, dežela, v kateri noben človek ne prebiva niti katerikoli človeški sin tam ne gre skozi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'V Babilonu bom kaznoval Bela in iz njegovih ust bom osvobodil to, kar je požrl. Narodi se ne bodo več stekali k njemu. Da, babilonsko obzidje bo padlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Moje ljudstvo, pojdite ven iz njegove srede in osvobodite vsak človek svojo dušo pred kruto Gospodovo jezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'In da ne bi vaše srce oslabelo in se boste bali zaradi govorice, ki jo bo slišati v deželi; govorica, bo tako prišla v enem letu in potem bo v drugem letu prišla govorica in nasilje v deželi, vladar zoper vladarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Zatorej glejte, prihajajo dnevi, ko bom naredil sodbo nad rezanimi podobami Babilona in njegova celotna dežela bo zbegana in vsi njegovi umorjeni bodo padli v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Potem bodo nebo in zemlja in vse, kar je na njej, peli zaradi Babilona, kajti plenilci bodo prišli k njemu iz severa,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, '›Kakor je Babilon storil umorjenim iz Izraela, da padejo, tako bodo pri Babilonu padli umorjeni iz vse zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Vi, ki ste pobegnili meču, pojdite proč, ne stojte pri miru. Spomnite se Gospoda od daleč in Jeruzalem naj pride v vaše misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Zbegani smo, ker smo slišali grajo. Sramota je pokrila naše obraze, kajti tujci so prišli v svetišča Gospodove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Zato, glejte, prihajajo dnevi,‹ govori Gospod, da bom naredil sodbo nad njegovimi rezanimi podobami, in po vsej njegovi deželi bodo ranjeni stokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Čeprav bi se Babilon povzpel do neba in četudi bi utrdil višino svoje moči, vendar bodo od mene prišli k njemu plenitelji,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Zvok krika prihaja iz Babilona in velika poguba od dežele Kaldejcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'ker je Gospod oplenil Babilon in iz njega uničil močan glas; ko njegovi valovi rjovijo kakor velike vode, je izusten hrup njihovega glasu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'ker je plenilec prišel nadenj, celó nad Babilon in so njegovi mogočni možje zajeti, vsak izmed njihovih lokov je zlomljen, kajti Gospod Bog povračil bo zagotovo poplačal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Opijanil bom njegove prince, njegove modre može, njegove poveljnike, njegove vladarje ter njegove mogočne može in spali bodo neprestano spanje in ne bodo se zbudili,‹ govori kralj, katerega ime je Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tako govori Gospod nad bojevniki: ›Široki zidovi Babilona bodo popolnoma porušeni in njegova visoka velika vrata bodo sežgana z ognjem; in ljudstvo se bo zaman trudilo in narod v ognju in izmučeni bodo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, '§ Beseda, ki jo je prerok Jeremija zapovedal Serajáju, Nerijájevemu sinu, Maasejájevemu sinu, ko je s Sedekíjem, Judovim kraljem, odšel v Babilon, v četrtem letu njegovega kraljevanja. In ta Serajá je bil tih princ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Tako je Jeremija zapisal v knjigo vse zlo, ki naj bi prišlo nad Babilon, celó vse te besede, ki so zapisane zoper Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Jeremija je rekel Serajáju: »Ko prideš v Babilon in boš videl in boš bral vse te besede;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'potem boš rekel: »Oh Gospod, ti si govoril zoper ta kraj, da ga odrežeš, da nihče ne bo ostal v njem niti človek niti žival, temveč da bo ta zapuščen na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'In zgodilo se bo, ko narediš konec branju te knjige, da boš k njej privezal kamen in jo vrgel v sredo Evfrata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'in rekel boš: ›Tako bo Babilon potonil in ne bo se vzdignil od zla, ki ga bom privedel nadenj in izmučeni bodo.‹« Do tu so Jeremijeve besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sedekíja je bil star enaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval enajst let. Ime njegove matere je bilo Hamutála, hči Jeremija iz Libne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Počel je to, kar je bilo zlo v Gospodovih očeh, glede na vse, kar je storil Jojakím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Kajti zaradi Gospodove jeze se je to zgodilo v Jeruzalemu in v Judu, dokler jih ni zavrgel izpred svoje prisotnosti, da se je Sedekíja uprl zoper babilonskega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Pripetilo se je v devetem letu njegovega kraljevanja, v desetem mesecu, na deseti dan meseca, da je prišel babilonski kralj Nebukadnezar, on in vsa njegova vojska, zoper [prestolnico] Jeruzalem in se utaboril zoper njo in zoper njo naokoli zgradil trdnjave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Tako je bilo mesto oblegano do enajstega leta kralja Sedekíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'In v četrtem mesecu, na deveti dan meseca, je bila huda lakota v mestu, tako da ni bilo kruha za ljudstvo dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Potem je bilo mesto predrto in vsi bojevniki so pobegnili in ponoči odšli ven iz mesta, po poti velikih vrat med dvema zidovoma, kar je bilo poleg kraljevega vrta; (torej Kaldejci so bili pri mestu naokoli) in odšli so po poti ravnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Toda vojska Kaldejcev je zasledovala kralja in Sedekíja dohitela na ravninah Jerihe; in vsa njegova vojska je bila razkropljena od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Potem so prijeli kralja in ga odvedli gor k babilonskemu kralju v Riblo, v deželo Hamát; kjer je izrekel sodbo nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Babilonski kralj je Sedekíjeve sinove usmrtil pred njegovimi očmi. Usmrtil je tudi vse Judove prince v Ribli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Potem je iztaknil Sedekíjeve oči; in babilonski kralj ga je zvezal v verige in ga odvedel v Babilon in ga vtaknil v ječo do dneva njegove smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Torej v petem mesecu, na deseti dan meseca, kar je bilo devetnajsto leto babilonskega kralja Nebukadnezarja je prišel Nebuzaradán, poveljnik straže, ki je služil babilonskemu kralju, v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Požgal je Gospodovo hišo, kraljevo hišo, vse jeruzalemske hiše in vse hiše velikih mož je požgal z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Vsa vojska Kaldejcev, ki je bila s poveljnikom straže, je porušila vse zidove naokoli Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Potem je Nebuzaradán, poveljnik straže, odvedel proč ujetništvo, nekatere izmed revnega ljudstva in preostanek ljudstva, ki je ostalo v mestu in tiste, ki so pobegnili proč, ki so pobegnili k babilonskemu kralju in preostanek množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Toda Nebuzaradán, poveljnik straže, je pustil nekatere izmed revnih dežele za obrezovalce trte in za poljedelce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Tudi stebre iz brona, ki so bili v Gospodovi hiši in podnožja in bronasto morje, ki je bilo v Gospodovi hiši, so Kaldejci zlomili in ves bron od tega odnesli v Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Tudi kotle in lopate in utrinjala in skledice in žlice in vse posode iz brona, s katerimi so služili, so vzeli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'In umivalnike in ponve za žerjavico in skledice in kotle in svečnike in žlice in čaše; to, kar je bilo iz zlata, v zlatu in to, kar je bilo iz srebra, v srebru, je vzel proč poveljnik straže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Dva stebra, eno morje in dvanajst bronastih bikov, ki so bili pod podnožji, ki jih je kralj Salomon naredil v Gospodovi hiši: brona vseh teh posod je bilo brez teže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'In glede stebrov, višina enega stebra je bila osemnajst komolcev; in obdajal ga je okrasni trak dvanajstih komolcev; in njegova debelina je bila štiri prste; bil je votel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Na njem je bil kapitel iz brona; in višina enega kapitela je bila pet komolcev, z mrežo in granatnimi jabolki naokoli na kapitelih, vsi iz brona. Tudi drugi steber in granatna jabolka so bili podobni tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'In tam je bilo šestindevetdeset granatnih jabolk na eni strani; in vseh granatnih jabolk na mreži je bilo sto naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'In poveljnik straže je vzel vélikega duhovnika Serajája in drugega duhovnika Cefanjája in tri čuvaje vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Iz mesta je vzel tudi evnuha, ki je bil zadolžen za bojevnike in sedem mož izmed njih, ki so bili blizu kraljevi osebi, ki so bili najdeni v mestu; in glavnega pisarja vojske, ki je nabiral ljudstvo dežele; in šestdeset mož izmed ljudstva dežele, ki so bili najdeni v sredi mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Tako jih je Nebuzaradán, poveljnik straže, vzel in jih privedel k babilonskemu kralju v Riblo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Babilonski kralj jih je udaril in jih usmrtil v Ribli, v deželi Hamát. Tako je bil Juda ujet odveden proč iz svoje lastne dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'To je ljudstvo, ki ga je Nebukadnezar odvedel proč ujete: v sedmem letu tri tisoč triindvajset Judov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'v osemnajstem letu Nebukadnezarja je iz Jeruzalema odvedel zajetih osemsto dvaintrideset oseb;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'v triindvajsetem letu Nebukadnezarja je Nebuzaradán, poveljnik straže, odvedel proč judovske ujetnike, sedemsto petinštirideset oseb. Vseh oseb je bilo štiri tisoč šeststo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Pripetilo se je v sedemintridesetem letu ujetništva Judovega kralja Jojahína, v dvanajstem mesecu, na petindvajseti dan meseca, da je babilonski kralj Evíl Merodáh v prvem letu svojega kraljevanja povzdignil glavo Judovega kralja Jojahína in ga privedel iz ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Prijazno je govoril z njim in njegov prestol postavil nad prestole kraljev, ki so bili z njim v Babilonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Spremenil je njegove jetniške obleke in nenehno je jedel kruh pred njim, vse dni svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Glede njegove prehrane mu je bil od babilonskega kralja dan nenehen delež hrane, vsak dan obrok do dneva njegove smrti, vse dni njegovega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kako mesto sedi osamljeno, ki je bilo polno ljudstva! Kako je ona postala kakor vdova! Ona, ki je bila velika med narodi in princesa med provincami, kako je postala podvržena davku!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Bridko joka ponoči in njene solze so na njenih licih. Med vsemi svojimi ljubimci nima nikogar, da jo potolaži. Vsi njeni prijatelji so zahrbtno postopali z njo, postali so njeni sovražniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda je odšel v ujetništvo zaradi stiske in zaradi velikega hlapčevstva. Prebiva med pogani, ne najde nobenega počitka. Vsi njegovi preganjalci so ga dohiteli med ožinami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Poti [na] Sion žalujejo, ker ni nihče prišel k slovesnim praznikom. Vsa njena velika vrata so zapuščena. Njeni duhovniki vzdihujejo, njene device so užaloščene in sama je v grenkobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Njeni nasprotniki so vodilni, njeni sovražniki uspevajo; kajti Gospod jo je prizadel zaradi množice njenih prestopkov. Njeni otroci so odšli v ujetništvo pred sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Od sionske hčere je odšla vsa njena lepota. Njeni princi so postali podobni jelenom, ki ne najdejo pašnika in odšli so brez moči pred zasledovalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'V dneh svoje stiske in svojih bed se je [prestolnica] Jeruzalem spomnila vseh svojih prijetnih stvari, ki jih je imela v dneh davnine, ko je njeno ljudstvo padlo v roko sovražnika in ji nihče ni pomagal. Nasprotniki so jo videli in jo zasmehovali pri njenih šabatih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, '[Prestolnica] Jeruzalem je bridko grešila, zato je odstranjena. Vsi, ki so jo častili, jo prezirajo, ker so videli njeno nagoto. Da, ona vzdihuje in se obrača nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Njena umazanost je v krajcih njenih oblačil; ne spominja se svojega zadnjega konca, zato se je čudovito spustila. Nobenega tolažnika ni imela. Oh Gospod, glej mojo stisko, kajti sovražnik se je poveličal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Nasprotnik je svojo roko razprostrl nad vse njene prijetne stvari, kajti videla je, da so pogani vstopili v njeno svetišče, katerim si zapovedal, da naj ne vstopijo v tvojo skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Vse njeno ljudstvo vzdihuje, iščejo kruh; svoje prijetne stvari so dali za hrano, da podprejo dušo. Glej, oh Gospod in preudari, kajti postala sem ničvredna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Ali vam ni to nič, vsi vi, ki greste mimo? Glejte in vidite, če je tam kakršnakoli bridkost podobna moji bridkosti, ki mi je storjena, s katero me je Gospod prizadel na dan svoje krute jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Od zgoraj je poslal ogenj v moje kosti in ta je prevladal zoper njih. Razprostrl je mrežo za moja stopala, obrnil me je nazaj. Naredil me je zapuščeno in ves dan slabim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Jarem mojih prestopkov je zvezan z njegovo roko. Oviti so in prišli so gor nad moj vrat. Moji moči je storil, da odpove, Gospod me je izročil v njihove roke, pred katerimi se nisem zmožen dvigniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Gospod je pod stopalom pomendral vse moje mogočne može v moji sredi. Zoper mene je sklical zbor, da zdrobi moje mladeniče. Gospod je pomendral devico, Judovo hčer, kakor v vinski stiskalnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Zaradi teh stvari jokam. Moje oko, moje oko teče dol z vodo, ker je tolažnik, ki naj bi razbremenil mojo dušo, daleč od mene. Moji otroci so zapuščeni, ker je sovražnik prevladal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sion razširja svoje roke in tam ni nikogar, da jo potolaži. Gospod je zapovedal glede Jakoba, da naj bi bili njegovi nasprotniki naokoli njega. [Prestolnica] Jeruzalem je med njimi kakor ženska, ki ima menstruacijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Gospod je pravičen, kajti uprla sem se zoper njegovo zapoved. Poslušajte, prosim vas, vsa ljudstva in glejte mojo bridkost. Moje device in moji mladeniči so odšli v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Poklicala sem svoje ljubimce, toda oni so me zavedli. Moji duhovniki in moje starešine so v mestu izročili duha, medtem ko so iskali svojo hrano, da podprejo svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Glej, oh Gospod, kajti v tegobi sem. Moja notranjost je nemirna; moje srce je obrnjeno znotraj mene; kajti neposlušno sem se uprla. Zunaj ropa meč, doma je kakor smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Slišali so, da sem zavzdihnila. Tam ni nikogar, da me potolaži. Vsi moji sovražniki so slišali o moji stiski; veseli so, da si to storil. Privedel boš dan, ki si ga poklical in oni bodo podobni meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Naj vsa njihova zlobnost pride predte, in stori jim, kakor si storil meni, zaradi vseh mojih prestopkov, kajti mojih vzdihov je mnogo in moje srce je oslabelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kako je Gospod v svoji jezi pokril sionsko hčer z oblakom in vrgel dol z neba na zemljo Izraelovo lepoto in se ni spominjal svoje pručke na dan svoje jeze!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Gospod je požrl vsa Jakobova prebivališča in se ni usmilil. V svojem besu je zrušil oporišča Judove hčere; privedel jih je dol do tal. Oskrunil je kraljestvo in njegove prince.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'V svoji kruti jezi je odrezal ves Izraelov rog. Svojo desnico je umaknil izpred sovražnika in zoper Jakoba je gorel plameneč ogenj, ki požira vsenaokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Svoj lok je upognil kakor sovražnik. S svojo desnico je stal kakor nasprotnik in usmrtil vse, ki so bili prijetni za oko v šotorskem svetišču sionske hčere. Svojo razjarjenost je izlil kakor ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Gospod je bil kakor sovražnik. Požrl je Izraela, požrl je vse njegove palače. Uničil je vsa njegova oporišča in v Judovi hčeri je povečal žalovanje in objokovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Nasilno je odvzel svoje šotorsko svetišče, kakor če bi bil ta od vrta. Uničil je njegove kraje zborovanja. Gospod je storil, da se slovesni prazniki in šabate pozabijo v Sionu in v ogorčenju svoje jeze je preziral kralja in duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Gospod je zavrgel svoj oltar, preziral svoje svetišče, zidove svoje palače je predal v roko sovražnika; v Gospodovi hiši so vzdignili hrup kakor na dan slovesnega praznika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Gospod se je namenil, da uniči obzidje sionske hčere. Iztegnil je vrvico, svoje roke ni umaknil pred uničevanjem. Zato je naredil obrambni zid in obzidje za žalovanje; skupaj so slabeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Njena velika vrata so se pogreznila v tla; uničeni in zlomljeni so njeni zapahi. Njen kralj in njeni princi so med pogani. Postave ni več, tudi njeni preroki ne najdejo videnja od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Starešine hčere sionske sedijo na tleh in molčijo. Na svoje glave so metali prah. Opasali so se z vrečevino. Device [prestolnice] Jeruzalem svoje glave povešajo k tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Moje oči pešajo s solzami, moja notranjost je vznemirjena, moja jetra so izlita na zemljo zaradi uničenja hčere mojega ljudstva; ker so otroci in dojenčki omedlevali na ulicah mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Svojim materam pravijo: »Kje sta žito in vino?« ko so omedlevali kakor ranjeni na ulicah mesta, ko so bile njihove duše izlite v naročje njihovih mater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kakšno stvar bom vzel, da pričuje zate? S kakšno stvarjo te bom primerjal, oh hči [prestolnice] Jeruzalem? Kaj bom enačil s teboj, da bi te lahko potolažil, oh devica, hči sionska, kajti tvoja vrzel je velika kakor morje. Kdo te lahko ozdravi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tvoji preroki so zate videli prazne in bedaste stvari in niso odkrili tvoje krivičnosti, da odvrnejo tvoje ujetništvo, temveč so zate videli napačna bremena in razloge izgnanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Vsi, ki gredo mimo, s svojimi rokami ploskajo nad teboj, sikajo in s svojimi glavami zmajujejo ob jeruzalemski hčeri, rekoč: »Ali je to mesto, ki ga ljudje imenujejo Popolnost lepote, Radost celotne zemlje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Vsi tvoji sovražniki so odprli svoja usta zoper tebe. Sikajo in škripajo z zobmi. Pravijo: »Požrli smo jo. Zagotovo, to je dan, ki smo se ga veselili; našli smo, videli smo to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Gospod je storil to, kar je načrtoval. Izpolnil je svojo besedo, ki jo je zapovedal od dni davnine. Zrušil je in se ni usmilil in tvojemu sovražniku je dal, da se veseli nad teboj, vzdignil je rog tvojih nasprotnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Njihovo srce je klicalo h Gospodu, oh obzidje hčere sionske, naj solze tečejo kakor reka, podnevi in ponoči. Ne daj si počitka, naj punčica tvojega očesa ne preneha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Vstani, zavpij ponoči. Ob začetku straž izlij svoje srce kakor vodo pred Gospodovim obrazom. Dvigni svoje roke k njemu zaradi življenja svojih mladih otrok, ki slabijo zaradi lakote na vrhu vsake ulice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Glej, oh Gospod in preudari, komu si to storil. Mar bodo ženske jedle svoj sad, otroke pedenj dolge? Mar bosta duhovnik in prerok umorjena v Gospodovem svetišču?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Mladi in stari ležijo po tleh na ulicah. Moje device in moji mladeniči so padli pod mečem; umoril si jih na dan svoje jeze, pobil si jih in se nisi usmilil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Poklical si kakor na slovesen dan moje strahote naokoli, tako da na dan Gospodove jeze nihče ni pobegnil niti preostal. Tiste, ki sem jih povil in vzgojil, je použil moj sovražnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Jaz sem človek, ki je videl stisko s palico njegovega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Vodil me je in me privedel v temo, toda ne v svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Zagotovo je obrnjen zoper mene; svojo roko je obračal zoper mene ves dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Postaral je moje meso in mojo kožo, zlomil je moje kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Zidal je zoper mene in me obdal z žolčem in muko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Postavil me je v temne kraje, kakor tiste, ki so mrtvi od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Ogradil me je naokoli, da ne morem priti ven. Mojo verigo je naredil težko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Tudi ko jokam in vpijem, on ustavlja mojo molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Moje steze je obdal s klesanim kamnom, moje poti je storil sprijene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Bil mi je kakor medved, ki preži v zasedi in kakor lev na skrivnih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Moje poti je obrnil vstran in me raztrgal. Naredil me je zapuščenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Upognil je svoj lok in me postavil kakor tarčo za puščico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Puščicam svojega tula je storil, da vstopijo v mojo notranjost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Bil sem v posmeh vsemu svojemu ljudstvu in ves dan njihova pesem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Nasičeval me je z grenkobo, opijanjal me je s pelinom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Prav tako je moje zobe zlomil z ostrimi kamni, pokril me je s pepelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Mojo dušo si odstranil daleč stran od miru. Pozabil sem uspevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Rekel sem: »Moja moč in moje upanje je izginilo od Gospoda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'spominjajoč se moje stiske in moje bede, pelina in žolča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Moja duša jih ima še vedno v spominu in je ponižana v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'To si ponovno kličem v svoj um, zato imam upanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'To je od Gospodovih milosti, da nismo použiti, ker njegova sočutja ne odnehajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Ta so nova vsako jutro. Velika je tvoja zvestoba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Gospod je moj delež, pravi moja duša, zato bom upal vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Gospod je dober vsem tistim, ki čakajo nanj; duši, ki ga išče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Dobro je, da bi človek upal in tiho čakal na Gospodovo rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Dobro je za človeka, da nosi jarem v svoji mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Sedi sam in molči, ker ga je nosil na sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Svoja usta polaga v prah, morda bi bilo lahko še upanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Svoje lice daje tistemu, ki ga udarja, napolnjen je z grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Kajti Gospod ne bo zavrgel na veke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'toda čeprav je povzročil žalost, bo vendar imel sočutje glede na množico svojih usmiljenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Kajti on ni voljan prizadeti niti užalostiti človeških otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Da bi pod svojimi stopali zdrobil vse jetnike zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'da bi odvrnil človekovo pravico pred obrazom Najvišjega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'da človeka spodkoplje v njegovi pravdi, [tega] Gospod ne odobrava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kdo je tisti, ki pravi in se to zgodi, ko Gospod tega ne zapove?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Iz ust Najvišjega ne izhaja zlo in dobro?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Zakaj se živeči človek pritožuje, človek zaradi kaznovanja svojih grehov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Preiščimo in preizkusimo svoje poti in se ponovno obrnimo h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Vzdignimo svoja srca s svojimi rokami k Bogu v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Pregrešili smo se in uprli. Ti nisi oprostil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Pokril si [nas] s svojo jezo in nas preganjal. Umoril si, nisi se usmilil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Pokril si se z oblakom, da naša molitev ne bi šla skozi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Naredil si nas kakor izvržek in zavrnitev v sredi ljudstev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Vsi naši sovražniki so odprli svoja usta zoper nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Strah in zanka sta prišla nad nas, opustošenje in uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Moje oko teče navzdol z rekami voda, zaradi uničenja hčere mojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Moje oko se izliva in ne preneha, brez kakršnegakoli predaha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'dokler Gospod ne pogleda dol in ne pogleda iz nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Moje oko prizadeva moje srce, zaradi vseh hčera mojega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Moji sovražniki so me boleče preganjali kakor ptico, brez vzroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Moje življenje so odsekali v grajski ječi in name vrgli kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Vode so mi tekle čez glavo; potem sem rekel: »Odsekan sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Klical sem k tvojemu imenu, oh Gospod, iz globine grajske ječe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Slišal si moj glas. Ne skrivaj svojega ušesa ob mojem dihanju, ob mojem klicu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Priteguješ me na dan, ko sem klical k tebi. Ti praviš: »Ne boj se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Oh Gospod, zagovarjal si pravde moje duše, odkupil si moje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Oh Gospod, videl si mojo krivico. Ti sodi mojo pravdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Videl si vse njihovo maščevanje in vse njihove zamisli zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Slišal si njihovo grajo, oh Gospod in vse njihove zamisli zoper mene;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'ustnice tistih, ki se vzdigujejo zoper mene in njihovo premišljevanje zoper mene ves dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Glej, njihovo usedanje in njihovo vzdigovanje; jaz sem njihova glasba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Vrni jim povračilo, oh Gospod, glede na delo njihovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Daj jim bridkost srca, svoje prekletstvo nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Preganjaj jih in jih uniči v jezi izpod Gospodovih nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kako je zlato postalo zatemnjeno! Kako se je najbolj čisto zlato spremenilo! Kamni svetišča so izliti na vrhu vsake ulice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Dragoceni sionski sinovi, primerljivi čistemu zlatu, kako so cenjeni, kakor lončeni vrči, delo lončarjevih rok!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Celo morske pošasti iztegnejo prsi, dajejo piti svojim mladičem. Hči mojega ljudstva je postala kruta, podobna nojem v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Jezik doječega otroka se zaradi žeje lepi na nebo njegovih ust. Mladi otroci prosijo kruha, pa jim ga noben človek ne nalomi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Tisti, ki so se prefinjeno hranili, so zapuščeni na ulicah. Tisti, ki so bili vzgojeni v škrlatu, objemajo gnojišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Kajti kazen krivičnosti hčere mojega ljudstva je večja kakor kazen za greh Sódome, ki je bila v hipu zrušena in nobene roke se je niso dotaknile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Njeni nazirci so bili čistejši od snega, bolj so bili beli kakor mleko, po telesu so bili bolj rdečkasti kakor rubini, njihova gladkost je bila [podobna] safirju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Njihov videz je bolj črn kakor oglje; na ulicah niso prepoznavni. Njihova koža se lepi na njihove kosti; izsušena je, postala je kakor palica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Tisti, ki so umorjeni z mečem, so boljši kakor tisti, ki so umorjeni z lakoto, kajti ti hirajo, zadeti zaradi potrebe po poljskem sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Roke sočutnih žensk so kuhale svoje lastne otroke. Bili so njihova hrana v uničenju hčere mojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Gospod je dovršil svojo razjarjenost; izlil je svojo kruto jezo in prižgal ogenj na Sionu in ta je požrl njegove temelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Kralji zemlje in vsi prebivalci zemeljskega [kroga] niso hoteli verjeti, da bosta nasprotnik in sovražnik vstopila v velika vrata Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Zaradi grehov njenih prerokov in krivičnosti njenih duhovnikov, ki so prelivali kri pravičnih v njeni sredi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'klatili so se kakor slepi možje po ulicah, oskrunili so se s krvjo, tako da se možje niso mogli dotakniti njihovih oblek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Klicali so jim: »Odidite; to je nečisto; odidite, odidite, ne dotikajte se.« Ko so pobegnili in se potikali so med pogani govorili: »Nič več ne bodo začasno prebivali tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Gospodova jeza jih je razdelila; ne bo se več oziral nanje. Niso spoštovali oseb duhovnikov, niso bili naklonjeni starešinam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Kar se tiče nas, so naše oči doslej odpovedovale zaradi naše prazne pomoči. V svojem oprezanju smo oprezali za narodom, ki nas ni mogel rešiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Lovijo naše korake, da ne moremo iti na svoje ulice. Naš konec je blizu, naši dnevi so izpolnjeni, kajti naš konec je prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Naši preganjalci so hitrejši kakor orli neba. Zasledovali so nas po gorah, na nas so prežali v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Dih naših nosnic, Gospodov maziljenec, je bil odveden v njihove jame, o katerem smo rekli: »Pod njegovo senco bomo živeli med pogani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Razveseljuj se in bodi vesela, oh edómska hči, ki prebivaš v deželi Uc; prav tako bo čaša prešla k tebi. Opijanjena boš in razgalila se boš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Kazen tvoje krivičnosti je dovršena, oh hči sionska; nič več te ne bo odvedel v ujetništvo. Obiskal bo tvojo krivičnost, oh hči edómska; odkril bo tvoje grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Spomni se, oh Gospod, kaj je prišlo nad nas. Preudari in poglej našo grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Naša dediščina je obrnjena k tujcem, naše hiše k neznancem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Sirote smo in brez očeta, naše matere so kakor vdove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Svojo vodo smo pili za denar; naš les nam je prodan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Naši vratovi so pod preganjanjem. Trudimo se, pa nimamo počitka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Roko smo izročili k Egipčanom in k Asircem, da bi bili nasičeni s kruhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Naši očetje so grešili in jih ni in mi smo nosili njihove krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Služabniki so vladali nad nami. Nikogar ni, da bi nas osvobodil iz njihove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Svoj kruh smo prinašali z nevarnostjo za svoja življenja, zaradi meča iz divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Naša koža je bila črna kakor peč zaradi strašne lakote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Posiljevali so ženske na Sionu in device v Judovih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Z njihovo roko so obesili prince. Obrazi starešin niso bili spoštovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Zajeli so mladeniče, da meljejo in otroci so padali pod lesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starešine so odšli od velikih vrat, mladeniči od svoje glasbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Veselje našega srca je prenehalo, naš ples je obrnjen v žalovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Krona je padla iz naše glave. Gorje nam, da smo grešili!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Zaradi tega peša naše srce, zaradi teh stvari so zatemnjene naše oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Zaradi gore Sion, ki je zapuščena, lisice hodijo po njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ti, oh Gospod, ostajaš na veke, tvoj prestol od roda do roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Zakaj nas pozabljaš na veke in nas zapuščaš za tako dolgo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Obrni nas k sebi, oh Gospod in mi bomo obrnjeni; obnovi naše dni kakor od davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Toda popolnoma si nas zavrgel. Zelo si ogorčen zoper nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Pripetilo se je torej v tridesetem letu, v četrtem mesecu, na peti dan meseca, ko sem bil med ujetniki pri reki Kebár, da so se odprla nebesa in zagledal sem Božja videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Na peti dan meseca, kar je bilo peto leto ujetništva kralja Jojahína,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'je prišla Gospodova beseda izrecno k duhovniku Ezekielu, Buzijevemu sinu, v deželi Kaldejcev, pri reki Kebár in tam je bila nad njim Gospodova roka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Pogledal sem in glej, vrtinčast veter je prišel iz severa, velik oblak in ogenj ga je obsegal in okoli njega je bil sijaj in iz njegove srede kakor jantarjeva barva ven iz srede ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Prav tako je iz njegove srede prišla podobnost štirih živih ustvarjenih bitij. In to je bil njihov videz; imela so podobnost človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Vsako je imelo štiri obraze in vsako je imelo štiri peruti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Njihova stopala so bila ravna stopala in podplat njihovih stopal je bil podoben telečjemu kopitu, in lesketala so se podobno barvi zloščenega brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Pod svojimi perutmi, na svojih štirih straneh, so imela človeške roke in ta štiri so imela svoje obraze in svoje peruti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Njihove peruti so bile pridružene druga k drugi; niso se obračala, ko so hodila; šla so vsaka naravnost naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Kar zadeva podobnost njihovih obrazov, ta štiri so imela človeški obraz in obraz leva na desni strani in ta štiri so imela obraz vola na levi strani; ta štiri so imela tudi obraz orla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Takšni so bili njihovi obrazi. Njihove peruti so bile iztegnjene navzgor; dve peruti vsakega sta bili pridruženi druga k drugi, dve pa sta pokrivali njihova telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Hodila so vsako naravnost naprej. Kamor naj bi šel duh, [tja] so šla, in niso se obračala, ko so hodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Kar se tiče podobnosti živih ustvarjenih bitij, je bil njihov videz podoben gorečemu ognjenemu oglju in podoben videzu svetilk. Ta je šel gor in dol med živimi ustvarjenimi bitji in ogenj je bil svetel in iz ognja se je dvigovalo bliskanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Živa ustvarjena bitja so tekala in se vračala kakor videz bliska strele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Medtem ko sem gledal živa ustvarjena bitja, sem na zemlji zagledal eno kolo poleg živih ustvarjenih bitij, z njegovimi štirimi obrazi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, '§ Videz koles in njihovo delo je bilo podobno barvi berila. Ta štiri so imela eno podobnost, in njihov videz in njihovo delo je bilo, kakor bi bilo kolo v sredi kolesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Ko so hodila, so hodila na svoje štiri strani, in ko so hodila, se niso obračala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Kar se tiče njihovih platišč, so bila tako visoka, da so bila grozna, in njihova platišča so bila polna oči naokoli teh štirih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Ko so živa ustvarjena bitja hodila, so poleg njih šla kolesa. In ko so bila živa ustvarjena bitja dvignjena z zemlje, so bila dvignjena kolesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kamor naj bi šel duh, so šla, tja naj bi šel njihov duh, in kolesa so bila dvignjena nasproti njih, kajti v kolesih je bil duh živega ustvarjenega bitja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Ko so tista šla, so šla ta; in ko so tista stala, so stala ta; in ko so bila tista dvignjena z zemlje, so bila kolesa dvignjena nasproti njih, kajti v kolesih je bil duh živega ustvarjenega bitja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Podobnost nebesnega svoda nad glavami živega ustvarjenega bitja je bila kakor barva strašnega kristala, razprostrtega zgoraj, nad njihovimi glavami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, '§ Pod nebesnim svodom so bile njihove peruti ravne druga proti drugi. Vsako je imelo dve, ki sta pokrili na tej strani in vsako je imelo dve, ki sta pokrili na oni strani njihovih teles.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'In ko so hodila, sem slišal šum njihovih peruti, podoben hrumenju velikih vodá, kakor glas Vsemogočnega, glas govora kakor hrup vojske. Ko so stala, so svoje peruti povesila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, '§ Bil je glas izpod nebesnega svoda, ki je bil nad njihovimi glavami, ko so stala in spustila svoje peruti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Nad nebesnim svodom, ki je bil nad njihovimi glavami, je bila podobnost prestola, kakor videz kamna safira. Na podobnosti prestola je bila podobnost kakor videz človeka nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Videl sem kakor barvo jantarja, kakor videz ognja okrog in okrog znotraj njega, od videza njegovih ledij navzgor in celo od videza njegovih ledij navzdol sem videl, kakor bi bil videz ognja in ta je imel sijaj vsenaokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Kakor videz mavrice, ki je na oblaku na deževen dan, takšen je bil videz sijaja naokoli. To je bil videz podobnosti Gospodove slave. Ko sem to zagledal, sem padel na svoj obraz in slišal glas nekoga, ki je spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Rekel mi je: »Človeški sin, vstani na svoja stopala in spregovoril ti bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Ko mi je spregovoril, je vame vstopil duh in me postavil na moja stopala, da sem slišal tistega, ki mi je spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Rekel mi je: »Človeški sin, pošiljam te k Izraelovim otrokom, k upornemu narodu, ki se je uprl zoper mene. Oni in njihovi očetje so se pregrešili zoper mene, celó do točno tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Kajti predrzni otroci so in trdega srca in jaz te pošljem k njim, ti pa jim boš rekel: ›Tako govori Gospod Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'In oni, bodisi bodo slišali, bodisi se bodo zadržali (kajti uporna hiša so), bodo vendar vedeli, da je bil med njimi prerok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ti pa, človeški sin, se jih ne boj niti se ne boj njihovih besed, čeprav bodo s teboj osat in trnje in prebivaš med škorpijoni. Ne boj se njihovih besed niti ne bodi zaprepaden ob njihovih pogledih, čeprav so uporna hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Govoril jim boš moje besede, bodisi bodo slišali, bodisi se bodo zadržali, kajti najbolj uporni so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Toda ti, človeški sin, poslušaj, kaj ti povem: ›Ne bodi uporen kakor ta uporna hiša. Odpri svoja usta in pojej, kar ti dajem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Ko sem pogledal, glej, je bila k meni poslana roka, in glej, zvitek knjige je bil v njej');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'in razprostrl ga je pred menoj. Popisan je bil znotraj in zunaj in na njem so bile zapisane žalostinke, žalovanja in gorje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Poleg tega mi je rekel: »Človeški sin, jej, kar najdeš. Pojej ta zvitek in pojdi, govori Izraelovi hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Tako sem odprl svoja usta in dal mi je, da sem pojedel ta zvitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Rekel mi je: »Človeški sin, stôri svojemu trebuhu, da jé in svojo notranjost napolni s tem zvitkom, ki ti ga dajem.« Potem sem to pojedel in v mojih ustih je bil zaradi sladkosti kakor med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Rekel mi je: »Človeški sin, pojdi, stopi k Izraelovi hiši in jim govori z mojimi besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Kajti nisi poslan k ljudstvu tujega govora in trdega jezika, temveč k Izraelovi hiši,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ne k mnogim ljudstvom tujega govora in trdega jezika, katerih besed ne moreš razumeti. Zagotovo, če bi te poslal k njim, bi ti prisluhnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Toda Izraelova hiša ti ne bo hotela prisluhniti, kajti nočejo mi prisluhniti, kajti vsa Izraelova hiša je predrzna in trdosrčna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Glej, tvoj obraz sem otrdil zoper njihove obraze in tvoje čelo zoper njihova čela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Kakor je diamant trši kakor kremen, [tako] sem naredil tvoje čelo. Ne boj se jih niti ne bodi zaprepaden ob njihovih pogledih, kajti uporna hiša so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Poleg tega mi je rekel: »Človeški sin, vse moje besede, ki ti jih bom govoril, sprejmi v svoje srce in poslušaj s svojimi ušesi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Pojdi, stopi k tistim iz ujetništva, k otrokom svojega ljudstva in jim govori ter jim povej: ›Tako govori Gospod Bog, bodisi bodo poslušali ali bodisi se bodo zadržali.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Potem me je duh vzel gor in za seboj sem zaslišal glas velikega hitenja, rekoč: »Blagoslovljena bodi Gospodova slava iz njegovega kraja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Slišal sem tudi šum peruti živih ustvarjenih bitij, ki so se dotikala druga druge in hrup koles nasproti njih in šum velikega hitenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Tako me je duh dvignil in me odnesel in šel sem v grenkobi, v vročici svojega duha, toda Gospodova roka je bila močna nad menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Potem sem prišel k tistim iz ujetništva pri Tel Abíbu, ki prebivajo pri reki Kebár in se usedel, kjer so sedeli in osupel ostal tam med njimi sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Pripetilo se je ob koncu sedmih dni, da je k meni prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '»Človeški sin, naredil sem te stražarja Izraelovi hiši, zato poslušaj besedo pri mojih ustih in jim daj svarilo od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Ko rečem zlobnemu: ›Gotovo boš umrl,‹ pa mu ne daješ svarila niti ne govoriš, da zlobnega posvariš pred njegovo zlobno potjo, da bi rešil njegovo življenje, bo ta isti zlobni človek umrl v svoji krivičnosti, toda njegovo kri bom zahteval iz tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, '§ Vendar če posvariš zlobnega, pa se ta ne odvrne od svoje zlobnosti niti od svoje zlobne poti, bo umrl v svoji krivičnosti, toda ti si osvobodil svojo dušo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Ponovno: »Kadar se pravičen človek odvrne od svoje pravičnosti in zagreši krivičnost in predenj položim kamen spotike, bo umrl; ker mu nisi dal svarila, bo umrl v svojem grehu in njegove pravičnosti, ki jo je storil, se ne bo spominjalo, temveč bom njegovo kri zahteval iz tvoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Vendar če posvariš pravičnega človeka, da pravični ne greši in ta ne greši, bo zagotovo živel, ker je posvarjen; tudi ti si osvobodil svojo dušo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Tam je bila nad menoj Gospodova roka in rekel mi je: »Vstani, pojdi naprej na ravnino in tam bom govoril s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Potem sem vstal in odšel naprej na ravnino. Glej, tam je stala Gospodova slava kakor slava, ki sem jo videl pri reki Kebár, in padel sem na svoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Potem je vame vstopil duh in me postavil na moja stopala in spregovoril z menoj ter mi rekel: »Pojdi, zapri se znotraj svoje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Toda ti, oh človeški sin, glej, nate bodo dali vezi in te zvezali z njimi in ne boš šel ven mednje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'jaz pa bom tvoj jezik prilepil k nebu tvojih ust, da boš nem in jim ne boš grajavec, kajti uporna hiša so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Toda ko jaz spregovorim s teboj, bom odprl tvoja usta in ti jim boš rekel: ›Tako govori Gospod Bog: ›Kdor posluša, naj sliši, in kdor se zadrži, naj se zadržuje, kajti uporna hiša so.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '»Tudi ti, človeški sin, si vzemi opeko in jo položi pred seboj in na njej upodobi mesto, celó [prestolnico] Jeruzalem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'in postavi obleganje zoper njo in zgradi utrdbo zoper njo in nasuj nasip zoper njo. Postavi tudi tabor zoper njo in naokoli zoper njo razpostavi oblegovalne ovne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Poleg tega si vzemi železno ponev in jo postavi za železen zid med seboj in mestom, in naravnaj svoj obraz zoper njo in ta bo oblegana, ti pa boš postavil oblegovanje zoper njo. To bo znamenje Izraelovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Lezi tudi na svojo levo stran in nanjo položi krivičnost Izraelove hiše. Glede na število dni, ko boš ležal na tej, boš nosil njihovo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Kajti nate sem položil leta njihove krivičnosti, glede na število dni, tristo devetdeset dni. Tako boš nosil krivičnost Izraelove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Ko jih dopolniš, ponovno lezi na svojo desno stran in štirideset dni boš nosil krivičnost Judove hiše. Določil sem ti vsak dan za leto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Zato boš svoj obraz naravnal proti obleganju [prestolnice] Jeruzalem in tvoj laket bo odkrit in prerokoval boš zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Glej, nate bom položil vezi in ne boš se obrnil iz ene strani na drugo, dokler ne dokončaš dni svojega obleganja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'K sebi vzemi tudi pšenico, ječmen, fižol, lečo, proso in piro ter jih stresi v eno posodo in iz tega zamesi kruh; glede na število dni, ki jih boš preležal na svoji strani, tristo devetdeset dni boš jedel od tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Tvoja hrana, ki jo boš jedel, bo po teži, dvajset šeklov na dan. Od časa do časa jo boš jedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Tudi vodo boš pil po meri, šesti del vrča. Od časa do časa [jo] boš pil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, '§ To boš jedel kakor ječmenove kolače in to boš spekel z iztrebkom, ki prihaja iz človeka, v njihovem pogledu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Gospod je rekel: »Celo tako bodo Izraelovi otroci jedli svoj omadeževani kruh med pogani, kamor jih bom pognal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Potem sem rekel: »Ah, Gospod Bog! Glej, moja duša ni bila oskrunjena, kajti od svoje mladosti, celo do sedaj, nisem jedel od tega, kar samo umre ali je raztrgano na koščke; niti v moja usta ni prišlo gnusno meso.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Potem mi je rekel: »Glej! Dajem ti kravji iztrebek za človeški iztrebek in svoj kruh boš pripravil s tem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Poleg tega mi je rekel: »Človeški sin, glej, zlomil bom oporo kruha v [prestolnici] Jeruzalem. Kruh bodo jedli po teži in s skrbnostjo in vodo bodo pili po meri in z osuplostjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'da jim bo lahko primanjkovalo kruha in vode in bodo osupli eden z drugim in shirali zaradi svoje krivičnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '»Ti pa, človeški sin, si vzemi oster nož, vzemi si brivčevo britev in ji povzroči, da gre čez tvojo glavo in po tvoji bradi. Potem si vzemi tehtnico, da stehtaš in razdeliš lase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Z ognjem boš sežgal tretjino v sredi mesta, ko se dopolnijo dnevi obleganja. Vzel boš tretjino in okoli nje udarjal z nožem. Tretjino boš raztrosil v vetru, jaz pa bom za njimi izvlekel meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Od teh boš vzel malo po številu in jih povezal v krajce svojega oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Potem ponovno vzemi od teh in jih vrzi v sredo ognja in jih sežgi v ognju, kajti od teh bo prišel ogenj v vso Izraelovo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tako govori Gospod Bog: »To je [prestolnica] Jeruzalem. Postavil sem jo v sredo narodov in dežel, ki so naokoli nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Moje sodbe je spremenila v zlobnost bolj kakor narodi in moje zakone bolj kakor dežele, ki so okoli nje, kajti zavrnili so moje sodbe in moje zakone; niso hodili v njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, '§ Zato tako govori Gospod Bog: »Ker ste se pomnožili bolj kakor narodi, ki so okoli vas in niste hodili po mojih zakonih niti se niste držali mojih sodb niti niste delali glede na sodbe narodov, ki so naokoli vas,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'zato tako govori Gospod Bog: »Glej jaz, celo jaz, sem zoper tebe in v tvoji sredi bom izvršil sodbe pred očmi narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'V tebi bom storil to, česar nisem storil in ne bom več storil temu podobnega, zaradi vseh tvojih ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Zato bodo v tvoji sredi očetje jedli sinove in sinovi bodo jedli svoje očete. Izvršil bom sodbe v tebi in tvoj celotni preostanek bom razkropil na vse vetrove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Zato, kakor jaz živim,« govori Gospod Bog, »zagotovo, ker si moje svetišče omadeževala z vsemi svojimi ostudnimi stvarmi in z vsemi svojimi ogabnostmi, zato bom tudi jaz tebe zmanjšal; niti moje oko ne bo prizaneslo, niti ne bom imel nobenega usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Tvoja tretjina bo umrla s kužno boleznijo in z lakoto bodo použiti v tvoji sredi. Tretjina bo padla pod mečem naokoli tebe, tretjino pa bom razkropil na vse vetrove in za njimi bom izvlekel meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Tako bo moja jeza dovršena in svoji razjarjenosti bom povzročil, da počiva nad njimi, jaz pa bom potolažen. Oni pa bodo vedeli, da sem jaz, Gospod, to govoril v svoji gorečnosti, ko sem svojo razjarjenost dovršil v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Poleg tega te bom naredil opustošenje in grajo med narodi, ki so naokoli tebe, pred očmi vseh, ki hodijo mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Tako bo to graja in zbadljivka, poučevanje in osuplost narodom, ki so naokoli tebe, ko bom v tebi izvršil sodbe v jezi, v razjarjenosti in v besnih ukorih. Jaz, Gospod, sem to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Ko bom nanje poslal zle puščice lakote, ki bodo za njihovo uničenje in ki jih bom poslal, da vas uničijo; in jaz bom razširil lakoto nad vami in zlomil vašo oporo kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, '§ Tako bom nad vas poslal lakoto in zle živali in te te bodo oropale in kužna bolezen in kri bosta šla skozte in nadte bom privedel meč. Jaz, Gospod, sem to govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'K meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '»Človeški sin, naravnaj svoj obraz proti Izraelovim goram in prerokuj zoper njih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'in reci: ›Ve Izraelove gore, poslušajte besedo Gospoda Boga: ›Tako govori Gospod Bog goram in hribom, rekam in dolinam: ›Glejte jaz, celó jaz, bom nad vas privedel meč in uničil bom vaše visoke kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Vaši oltarji bodo zapuščeni in vaši kipi bodo razbiti, in jaz bom vrgel dol vaše umorjene ljudi pred vaše malike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Mrtva trupla Izraelovih otrok bom položil pred njihove malike in vaše kosti bom raztrosil okoli vaših oltarjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'V vseh vaših bivališčih bodo mesta opustošena in visoki kraji bodo zapuščeni, da bodo vaši oltarji lahko opustošeni in zapuščeni in bodo vaši maliki lahko razbiti in prenehali [obstajati] in bodo vaše podobe lahko posekane in bodo vaša dela lahko odpravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Umorjeni bodo padli v vaši sredi in spoznali boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Vendar bom pustil ostanek, da boste lahko imeli nekatere, ki bodo pobegnili meču med narodi, ko boste razkropljeni po deželah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, '§ Tisti izmed vas, ki pobegnejo, se me bodo spomnili med narodi, kamor bodo odvedeni ujetniki, kajti zlomljen sem z njihovim vlačugarskim srcem, ki je odšlo od mene in z njihovimi očmi, ki se gredo vlačugat za njihovimi maliki in gnusili se bodo samim sebi zaradi zla, ki so ga zagrešili pri vseh svojih ogabnostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'In spoznali bodo, da jaz sem Gospod in da nisem zaman rekel, da jim bom storil to zlo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tako govori Gospod Bog: »Udari s svojo roko in zatopotaj s svojim stopalom ob tla ter reci: ›Ojoj za vse zle ogabnosti Izraelove hiše! Kajti padli bodo pod mečem, od lakote in kužne bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, '§ Kdor je daleč, bo umrl od kužne bolezni, in kdor je blizu, bo padel pod mečem, in kdor preostaja in je oblegan, bo umrl od lakote. Tako bom nad njimi dovršil svojo razjarjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Potem boste vedeli, da jaz sem Gospod, ko bodo njihovi pobiti ljudje [ležali] med njihovimi maliki, naokoli njihovih oltarjev, na vsakem visokem hribu, po vseh vrhovih gora in pod vsakim zelenim drevesom in pod vsakim debelim hrastom, [na] kraju, kjer so vsem svojim malikom darovali prijetno dišavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, '§ Tako bom svojo roko iztegnil nadnje in njihovo deželo naredil zapuščeno, da, bolj zapuščeno kakor divjino proti Dibli, v vseh njihovih prebivališčih, in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '§ »Tudi ti, človeški sin, tako govori Gospod Bog Izraelovi deželi: ›Konec, konec je prišel nad štiri vogale dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Sedaj je nadte prišel konec in nadte bom poslal svojo jezo in sodil te bom glede na tvoje poti in na tebi bom poplačal vse tvoje ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Moje oko ti ne bo prizaneslo niti ne bom imel usmiljenja, temveč bom na tebi poplačal tvoje poti in tvoje ogabnosti bodo v tvoji sredi in spoznali boste, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, '§ Tako govori Gospod Bog: ›Zlo, samo zlo, glej, je prišlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, '§ Konec je prišel, prišel je konec. Ta opreza za teboj, glej, ta je prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, '§ Jutro je prišlo k tebi, oh ti, ki prebivaš v deželi. Čas je prišel, dan stiske je blizu, ne pa ponovno oglašanje gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nate bom sedaj v kratkem izlil svojo razjarjenost in dovršil svojo jezo nad teboj. Sodil te bom glede na tvoje poti in poplačal ti bom za vse tvoje ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, '§ Moje oko ne bo prizaneslo niti ne bom imel usmiljenja. Poplačal ti bom glede na tvoje poti in tvoje ogabnosti, ki so sredi tebe in spoznali boste, da jaz sem Gospod, ki udarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, '§ Glej dan, glej, prišel je. Jutro je prešlo, palica je zacvetela, ponos je vzbrstel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Nasilje se vzdiguje v palico zlobnosti. Nihče izmed njih ne bo preostal, niti od njihove množice, niti od ničesar, kar je njihovega; niti za njimi ne bo tarnanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Čas je prišel, dan se približuje. Naj se kupec ne veseli niti naj prodajalec ne žaluje, kajti bes je nad vso njegovo množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, '§ Kajti prodajalec se ne bo vrnil k temu, kar je prodano, čeprav bi bili še živi, kajti videnje je glede vse njegove množice, ki se ne bo vrnila; niti se ne bo kdorkoli okrepil v krivičnosti svojega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Zatrobili so na trobento, celo da bi se vsi pripravili, toda nihče ne gre v bitko, kajti moj bes je nad vso njihovo množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Meč je zunaj, znotraj pa kužna bolezen in lakota. Kdor je na polju, bo umrl z mečem, kdor pa je v mestu, ga bosta požrla lakota in kužna bolezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Toda tisti izmed njih, ki pobegnejo, bodo pobegnili in bodo na gorah kakor dolinske golobice, vsi izmed njih žalujoči, vsakdo zaradi svoje krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Vse roke bodo slabotne in vsa kolena bodo šibka kakor voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Prav tako se bodo opasali z vrečevino in groza jih bo pokrila. Sramota bo na vseh obrazih in plešavost na vseh njihovih glavah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, '§ Svoje srebro bodo vrgli na ulice in njihovo zlato bo odstranjeno. Njihovo srebro in njihovo zlato jih ne bo moglo rešiti na dan Gospodovega besa. Ne bodo zadovoljili svojih duš niti napolnili svojih notranjosti, ker je le-to kamen spotike njihovi krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, '§ Kar se tiče lepote njegovega ornamenta, ga je postavil v veličanstvu, toda v njem so oni naredili podobe svojih ogabnosti in svojih ostudnih stvari, zatorej sem ga postavil daleč od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'In dal sem ga v roke tujcem za plen in zlobnežem zemlje za ukradeno blago in oni ga bodo oskrunili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Tudi svoj obraz bom obrnil proč od njih in oskrunili bodo moj skrivni kraj, kajti roparji bodo vstopili vanj in ga omadeževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, '§ Naredi verigo, kajti dežela je polna krvoločnih zločinov in mesto je polno nasilja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Zatorej bom privedel najslabše izmed poganov in njihove hiše bodo vzeli v last. Prav tako bom storil, da bo pomp močnega prenehal in njihovi sveti kraji bodo omadeževani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Prihaja uničenje in iskali bodo miru, pa ga ne bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, '§ Vragolija bo prišla na vragolijo in govorica na govorico, potem bodo iskali videnje od preroka, toda postava bo izginila od duhovnika in nasvet od starcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kralj bo žaloval in princ bo oblečen z opustošenjem in roke ljudstva dežele bodo trepetale. Jaz jim bom storil po njihovi poti in glede na njihove zasluge jih bom sodil, in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Pripetilo se je v šestem letu, v šestem mesecu, na peti dan meseca, ko sem sedèl v svoji hiši in so starešine Juda sedeli pred menoj, da je tam name padla roka Gospoda Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, '§ Potem sem pogledal in glej, podoba kakor videz ognja. Od videza njenih ledij, celó navzdol, ogenj; in od njenih ledij, celó navzgor, kakor videz sijaja, kot barva jantarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Iztegnil je obliko roke in me prijel za koder moje glave, in duh me je dvignil med zemljo in nebo in me v Božjih videnjih privedel k Jeruzalemu, k durim notranjih velikih vrat, ki gledajo proti severu, kjer je bil sedež podobe ljubosumnosti, ki izziva k ljubosumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Glej, tam je bila slava Izraelovega Boga, glede na videnje, ki sem ga videl na ravnini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Potem mi je rekel: »Človeški sin, povzdigni sedaj svoje oči proti severu.« Tako sem povzdignil svoje oči proti severu in glej proti severu, pri velikih vratih oltarja, ta podoba ljubosumnosti na vhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, '§ Nadalje mi je rekel: »Človeški sin, ali vidiš, kaj počno? Celó velike ogabnosti, ki jih Izraelova hiša grešno počenja tukaj, da bi jaz moral oditi daleč proč od svojega svetišča? Toda ponovno se obrni in videl boš večje ogabnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Privedel me je k dvornim vratom in ko sem pogledal, glej, luknja v zidu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Potem mi je rekel: »Človeški sin, koplji sedaj v steno.« In ko sem kopál v steno, sem zagledal vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'In rekel mi je: »Vstopi in poglej zlobne ogabnosti, ki jih tukaj počno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Tako sem vstopil in videl; in glej, vsakršne oblike plazečih stvari in gnusnih zveri in vseh malikov Izraelove hiše, upodobljenih po steni naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'In tam je pred njimi stalo sedemdeset mož, izmed starcev Izraelove hiše in v njihovi sredi je stal Jaazanjá, sin Šafána. Z vsakim moškim je bila v njegovi roki njegova kadilnica; in gost oblak kadila se je dvigal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Potem mi je rekel: »Človeški sin, ali si videl kaj starci Izraelove hiše počno v temi, vsak mož v sobah svojih podob? Kajti pravijo: › Gospod nas ne vidi; Gospod je zapustil zemljo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, '§ Prav tako mi je rekel: »Ponovno se obrni in videl boš večje ogabnosti, ki jih počno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Potem me je privedel k durim velikih vrat Gospodove hiše, ki so bila proti severu; in glej, tam so sedele ženske, jokajoče za Tamúzom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, '§ Potem mi je rekel: »Ali si videl to, oh človeški sin? Ponovno se obrni in videl boš večje ogabnosti, kot so te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'In privedel me je na notranji dvor Gospodove hiše in glej, pri vratih Gospodovega templja, med preddverjem in oltarjem, je bilo okoli petindvajset mož, s svojimi hrbti proti Gospodovemu templju in svojimi obrazi proti vzhodu; in oboževali so sonce proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, '§ Potem mi je rekel: »Si videl to, oh človeški sin? Ali je lahka stvar za Judovo hišo, da zagrešijo ogabnosti, ki jih tukaj zagrešujejo? Kajti deželo so napolnili z nasiljem in vrnili so se, da me izzivajo k jezi. In glej, vejico dajejo pod svoj nos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Zatorej bom tudi jaz postopal v razjarjenosti. Moje oko ne bo prizanašalo niti ne bom imel usmiljenja, in četudi jokajo z močnim glasom v moja ušesa, jih vendar ne bom slišal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Zaklical je tudi z močnim glasom v moja ušesa, rekoč: »Povzročite tistim, ki imajo zadolžitev nad mestom, da se približajo, celo vsak človek s svojim uničevalnim orožjem v svoji roki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'In glej, šest mož je prišlo po poti višjih velikih vrat, ki ležijo proti severu in vsak mož s pokončevalnim orožjem v svoji roki; in en mož izmed njih je bil oblečen z lanenim platnom, s pisarskim rogom, s črnilom ob njegovi strani in vstopili so in obstali poleg bronastega oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'In slava Izraelovega Boga je odšla gor od keruba, nad katerim je bila, k hišnemu pragu. In zaklical je k možu, oblečenim z lanenim platnom, ki je imel pisarski rog s črnilom ob njegovi strani;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, '§ in Gospod mu je rekel: »Pojdi skozi sredino mesta, skozi sredo [prestolnice] Jeruzalem in postavi znamenje na čela ljudi, ki vzdihujejo in ki jokajo zaradi vseh ogabnosti, ki se počno v njeni sredi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Drugim pa je rekel v mojem slišanju: »Pojdite za njim skozi mesto in udarite. Naj vaše oko ne prizanaša niti ne imejte usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, '§ Popolnoma pobijte stare in mlade, tako device kakor majhne otroke in ženske, toda ne pridite blizu nobenemu človeku, na katerem je znamenje; in začnite pri mojem svetišču.« Potem so začeli pri starodavnih možeh, ki so bili pred hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Rekel jim je: »Omadežujte hišo in napolnite dvore z umorjenimi. Pojdite naprej.« In odšli so naprej in morili v mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'In pripetilo se je, medtem ko so jih pobijali in sem ostal sam, da sem padel na svoj obraz in jokal ter rekel: »Ah, Gospod Bog! Ali boš ves Izraelov preostanek uničil v izlivanju svoje razjarjenosti nad [prestolnico] Jeruzalem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Potem mi je rekel: »Krivičnost Izraelove in Judove hiše je silno velika in dežela je polna krvi in mesto polno perverznosti, kajti pravijo: › Gospod je zapustil zemljo in Gospod ne vidi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'In tudi kar se mene tiče, moje oko ne bo prizaneslo niti ne bom imel usmiljenja, temveč bom njihovo pot poplačal na njihovi glavi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'In glej, mož, oblečen z lanenim platnom, ki je imel ob svoji strani pisarski rog s črnilom, je poročal zadevo, rekoč: »Storil sem, kakor si mi zapovedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Potem sem pogledal in glej, na nebesnem svodu, ki je bil nad glavo kerubov, tam se je nad njimi prikazal kakor kamen safir, kakor videz podobnosti prestola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'In spregovoril je človeku, oblečenemu z lanenim platnom in rekel: »Vstopi med kolesa, celó pod keruba in svojo roko napolni z ognjenim ogljem izmed kerubov in jih raztresi nad mestom.« In vstopil je pred mojim pogledom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Torej kerubi so stali na desni strani hiše, ko je mož vstopil; in oblak je napolnil notranji dvor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, '§ Potem se je Gospodova slava vzdignila od keruba in stala nad hišnim pragom hiše; in hiša je bila napolnjena z oblakom in dvor je bil poln sijaja Gospodove slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'In zvok kerubovih peruti je bilo slišati celó k zunanjemu dvoru, kakor glas Vsemogočnega Boga, ko spregovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'In pripetilo se je, da ko je zapovedal možu, oblečenemu z lanenim platnom, rekoč: »Vzemi ogenj izmed koles, izmed kerubov;« potem je ta vstopil in stal poleg koles.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'In en kerub je svojo roko iztegnil izmed kerubov k ognju, ki je bil med kerubi in vzel od njega in to položil v roke tistega, ki je bil oblečen z lanenim platnom; ki je to vzel in odšel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'In pri kerubih se je prikazala oblika človeške roke pod njihovimi perutmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, '§ In ko sem pogledal, glej, štiri kolesa ob kerubih, eno kolo pri enem kerubu in drugo kolo pri drugem kerubu in videz koles je bil kakor barva kamna berila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'In glede njihovih videzov, so ti štirje imeli eno podobnost, kakor če bi bilo kolo v sredi kolesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, '§ Ko so odšla, so odšla na svoje štiri strani; ko so odšla, se niso obračala, toda sledila so h kraju, kamor je pogledala glava; ko so odšla, se niso obračala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'In njihovo celotno telo in njihovi hrbti in njihove roke in njihove peruti in kolesa so bili naokoli polni oči, celó kolesa, ki so jih ta štiri imela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Glede koles, jim je bilo klicano v mojem slišanju: »Oh kolo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, '§ In vsako je imelo štiri obraze: prvi obraz je bil obraz keruba, drugi obraz je bil obraz človeka, tretji obraz leva in četrti obraz orla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'In kerubi so bili dvignjeni. To je živo ustvarjeno bitje, ki sem ga videl pri reki Kebár.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'In ko so hodili kerubi, so ob njih šla kolesa, in ko so kerubi dvignili svoje peruti, da se povzpnejo z zemlje, se tudi ista kolesa niso odvrnila od njihove bližine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Ko so se ustavili, so se ta ustavila; in ko so se dvignili, so se tudi ta sama dvignila, kajti duh živega ustvarjenega bitja je bil v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Potem je Gospodova slava odšla od hišnega praga in obstala nad kerubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'In kerubi so dvignili svoje peruti in se v mojem pogledu vzpeli z zemlje; ko so odšli, so bila tudi kolesa poleg njih in vsako je stalo pri vratih vzhodnih velikih vrat Gospodove hiše in slava Izraelovega Boga je bila zgoraj nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'To je živo ustvarjeno bitje, ki sem ga videl pod Izraelovim Bogom, poleg reke Kebár; in vedel sem, da so bili to kerubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Vsak je imel po štiri obraze in vsak štiri peruti; in podobnost človeških rok je bila pod njihovimi perutmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'In podobnost njihovih obrazov so bili isti obrazi, ki sem jih videl poleg reke Kebár, njihovi videzi in oni sami. Vsak je hodil naravnost naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Poleg tega me je duh dvignil navzgor in me privedel k vzhodnim velikim vratom Gospodove hiše, ki so gledala proti vzhodu. Glej, pri vratih velikih vrat sem zagledal petindvajset mož; med njimi sem videl Jaazanjá, Azúrjevega sina in Pelatjája, Benajájevega sina, princa ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Potem mi je rekel: »Človeški sin, to so možje, ki snujejo vragolijo in dajejo zloben nasvet v tem mestu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'ki pravijo: › To ni blizu; dajmo, gradimo hiše; to mesto je kotel in mi smo meso.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Zato prerokuj zoper njih, prerokuj, oh človeški sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'In Gospodov Duh je padel name ter mi rekel: »Govori: ›Tako govori Gospod: ›Tako ste rekli, oh Izraelova hiša; kajti poznam besede, ki pridejo v vaš um, vsako izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Pomnožili ste svoje umorjene v tem mestu in njegove ulice ste napolnili z umorjenimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Zato tako govori Gospod Bog: ›Vaši umorjeni, ki ste jih položili v njegovi sredi, oni so meso in to mesto je kotel, toda jaz vas bom privedel iz njegove srede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Bali ste se meča; pa bom nad vas privedel meč,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, '›Privedel vas bom iz njegove srede in vas izročil v roke tujcem in med vami bom izvršil sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Pod mečem boste padli; sodil vas bom na Izraelovi meji, in spoznali boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'To mesto ne bo vaš kotel niti ne boste meso v njegovi sredi; temveč vas bom jaz sodil na Izraelovi meji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'in spoznali boste, da jaz sem Gospod, kajti niste živeli po mojih zakonih niti izvrševali mojih sodb, temveč ste počeli po navadah poganov, ki so naokoli vas.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'In pripetilo se je, ko sem prerokoval, da je Benajájev sin Pelatjája umrl. Potem sem padel na svoj obraz in jokal z močnim glasom ter rekel: »Ah, Gospod Bog! Ali hočeš narediti popoln konec Izraelovemu preostanku?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '»Človeški sin, tvoji bratje, celó tvoji bratje, možje tvojega sorodstva in vsa celotna Izraelova hiša, ali so oni tisti, ki so jim prebivalci [prestolnice] Jeruzalem rekli: ›Spravite se daleč od Gospoda. Nam je dana ta dežela v posest.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Zato reci: ›Tako govori Gospod Bog: ›Čeprav sem jih vrgel daleč proč med pogane in čeprav sem jih razkropil med dežele, vendar jim bom kakor majhno svetišče v deželah, v katere bodo prišli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Zato reci: ›Tako govori Gospod Bog: ›Jaz vas bom celo zbral izmed ljudstev in vas zbral izmed dežel, kamor ste bili razkropljeni in jaz vam bom dal Izraelovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'In prišli bodo tja in od tam bodo odvzeli vse njene ostudne stvari in vse njene ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Dal jim bom eno srce in znotraj vas bom položil novega duha; in odvzel bom kamnito srce iz njihovega mesa in jim dal meseno srce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'da se bodo lahko ravnali po mojih zakonih in se držali mojih odredb in jih izvajali in bodo moje ljudstvo in jaz bom njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Toda glede tistih, čigar srce hodi za srcem njihovih ostudnih stvari in njihovih ogabnosti, bom njihovo pot poplačal na njihovih lastnih glavah,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Potem so kerubi dvignili svoje peruti in kolesa poleg njih; in slava Izraelovega Boga je bila zgoraj nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'In Gospodova slava se je vzdignila iz srede mesta in se ustavila nad goro, ki je na vzhodni strani mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Potem me je duh vzel gor in me v videnju, po Božjem Duhu, privedel v Kaldejo, k tem iz ujetništva. Tako se je videnje, ki sem ga videl, dvignilo od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Potem sem tistim iz ujetništva, spregovoril vse stvari, ki mi jih je Gospod pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Prav tako je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '»Človeški sin, prebivaš v sredi uporne hiše, ki imajo oči, da vidijo, pa ne vidijo; imajo ušesa, da slišijo, pa ne slišijo, kajti uporna hiša so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Zato, človeški sin, si pripravi stvari za selitev in se preseli podnevi, v njihovem pogledu; in preselil se boš iz svojega kraja na drug kraj, v njihovem pogledu. Morda bodo to preudarili, kajti uporna hiša so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Potem boš podnevi prinesel svoje stvari, v njihovem pogledu, kakor stvari za selitev, in zvečer boš šel naprej, v njihovem pogledu, kakor tisti, ki gredo naprej v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Prekoplji se skozi steno, v njihovem pogledu in tam odnesi ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'V njihovem pogledu boš to nosil na svojih ramenih in to boš prenašal naprej v mraku. Pokril si boš svoj obraz, da ne vidiš tal, kajti postavil sem te za znamenje Izraelovi hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'In storil sem tako, kakor mi je bilo zapovedano. Podnevi sem prinesel svoje stvari, kakor stvari za v ujetništvo, zvečer pa sem se s svojo roko prekopál skozi zid; to sem prinesel naprej v mraku in to sem nosil na svojem ramenu, v njihovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'In zjutraj mi je prišla beseda od Gospoda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '»Človeški sin, ali ti ni Izraelova hiša, uporna hiša, rekla: ›Kaj delaš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, '§ Povej jim: ›Tako govori Gospod Bog: ›To breme zadeva princa v [prestolnici] Jeruzalem in vso Izraelovo hišo, ki so med njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Reci: ›Jaz sem vaše znamenje. Kakor sem jaz storil, tako bo storjeno njim. Odselili se bodo in odšli v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, '§ In princ, ki je med njimi, bo v mraku nosil na svojem ramenu in bo šel naprej. Prekopali bodo skozi zid, da bi tamkaj nosili ven skozi steno. Pokril si bo svoj obraz, da s svojimi očmi ne bo videl tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Tudi svojo mrežo bom razširil nad njim in zajet bo v mojo zanko, in privedel ga bom v Babilon, v deželo Kaldejcev; vendar je ne bo videl, čeprav bo tam umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'In vse, ki so okoli njega, da mu pomagajo, bom razkropil proti vsakemu vetru in vse njegove čete; in za njimi bom izvlekel meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'In spoznali bodo, da jaz sem Gospod, ko jih bom razkropil med narode in jih razpršil v dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Toda izločil bom peščico ljudi izmed njih pred mečem, pred lakoto in kužno boleznijo; da bodo med pogani, kamor pridejo, lahko razglasili vse svoje ogabnosti; in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '»Človeški sin, svoj kruh jej z drgetanjem in svojo vodo pij s trepetanjem in previdnostjo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'in povej ljudstvu dežele: ›Tako govori Gospod Bog o prebivalcih [prestolnice] Jeruzalem in o Izraelovi deželi: ›Svoj kruh bodo jedli s previdnostjo in svojo vodo pili z osuplostjo, da bo njihova dežela lahko zapuščena od vseh, ki so v njej, zaradi nasilja vseh tistih, ki prebivajo v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'In mesta, ki so naseljena, bodo opustošena in dežela bo zapuščena; in spoznali boste, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '»Človeški sin, kakšen je ta pregovor, ki ga imate v Izraelovi deželi, rekoč: ›Dnevi so podaljšani in vsako videnje odpove?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, '§ Povej jim torej: ›Tako govori Gospod Bog: ›Temu pregovoru bom storil, da preneha in ne bodo ga več uporabljali kot pregovor v Izraelu; temveč jim reci: ›Blizu so dnevi in učinek vsakega videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Kajti nobenih praznih videnj ne bo več niti laskajočih vedeževanj znotraj Izraelove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Kajti jaz sem Gospod. Jaz bom govoril in beseda, ki jo bom govoril, se bo izpolnila; ta se ne bo več odlagala, kajti v vaših dneh, oh uporna hiša, bom rekel besedo in jo izpolnil, govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '»Človeški sin, glej, tisti iz Izraelove hiše pravijo: ›Videnje, ki ga on vidi, je za mnoge dni, ki pridejo in prerokuje o časih, ki so še daleč.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Zato jim reci: ›Tako govori Gospod Bog: ›Nobena izmed mojih besed se ne bo več odlagala, temveč se bo beseda, ki sem jo govoril, izpolnila,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '»Človeški sin, prerokuj zoper Izraelove preroke, ki prerokujejo in reci tem, ki prerokujejo iz svojih lastnih src: ›Poslušajte Gospodovo besedo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, '›Tako govori Gospod Bog: ›Gorje nespametnim prerokom, ki sledijo svojemu lastnemu duhu in ničesar niso videli!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Oh Izrael, tvoji preroki so podobni lisicam v puščavah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Vi niste odšli gor v razpoke niti niste postavili ograje za Izraelovo hišo, da obstane v bitki na Gospodov dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Videli so ničnost in lažniva vedeževanja, rekoč: › Gospod govori,‹ pa jih Gospod ni poslal. In druge so pripravili, da upajo, da bi potrdili besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Mar niste videli praznega videnja in ali niste govorili lažnivega vedeževanja, medtem ko govorite: › To govori Gospod;‹ čeprav nisem govoril?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Zato tako govori Gospod Bog: ›Ker ste govorili prazne reči in videli laži, zato, glejte, jaz sem zoper vas,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, '§ ›In moja roka bo na prerokih, ki vidijo prazne reči in ki vedežujejo laži. Ne bodo v zboru mojega ljudstva niti ne bodo zapisani v zapisu Izraelove hiše niti ne bodo vstopili v Izraelovo deželo, in spoznali boste, da jaz sem Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Zato, celo zato so zapeljali moje ljudstvo, rekoč: ›Mir;‹ pa tam ni bilo miru; in nekdo je zgradil zid in glej, drugi so ga ometali z neutrjeno malto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, '§ Recite tistim, ki ga ometujejo z neutrjeno malto, da bo ta padel. Preplavljajoč naliv bo; oh, velika zrna toče bodo padala; in viharni veter ga bo razklal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Glejte, ko pade zid, ali vam ne bo rečeno: ›Kje je zmazek, s katerim ste ga namazali?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, '§ Zato tako govori Gospod Bog: ›V svoji razjarjenosti ga bom celo razklal z viharnim vetrom; in tam bo preplavljajoč naliv v moji jezi in velika zrna toče v moji razjarjenosti, da ga použijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Tako bom porušil zid, ki ste ga ometali z neutrjeno malto in ga porušim do tal, tako da bodo odkriti njegovi temelji in ta bo padel, vi pa boste použiti v njegovi sredi in spoznali boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Tako bom dovršil svoj bes nad zidom in nad temi, ki so ga ometali z neutrjeno malto in vam bom rekel: ›Zidu ni več niti tistih, ki so ga ometali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'namreč Izraelovih prerokov, ki prerokujejo glede [prestolnice] Jeruzalem in ki zanjo vidijo videnja miru, pa tam ni miru,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, '›Prav tako ti, človeški sin, naravnaj svoj obraz zoper hčere svojega ljudstva, ki prerokujejo iz svojih lastnih src; in prerokuj zoper njih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, '§ ter reci: ›Tako govori Gospod Bog: ›Gorje ženskam, ki šivajo blazine k vsem odprtinam za rokave in izdelujejo naglavne rute na glavi vsake postave, da bi lovile duše! Hočete loviti duše mojega ljudstva in ali boste duše, ki prihajajo k vam, rešile žive?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, '§ In ali me hočete oskruniti med mojim ljudstvom za prgišča ječmena in za koščke kruha, da ubijate duše, ki naj ne bi umrle in da rešujete duše žive, ki naj ne bi živele, z vašim laganjem mojemu ljudstvu, ki posluša vaše laži?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Zato tako govori Gospod Bog: ›Glejte, jaz sem zoper vaše blazine, s katerimi ste tam lovile duše, da jih pripravite leteti in iztrgal jih bom iz vaših rok in jaz bom pustil dušam oditi, celó dušam, ki jih vi lovite, da jih pripravite leteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Tudi vse naglavne rute bom raztrgal in osvobodil svoje ljudstvo iz vaše roke in nič več ne bodo v vaši roki, da bi jih lovile; in spoznale boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, '§ Ker ste z lažmi užalostile srce pravičnega, ki ga nisem užalostil; in okrepile roke zlobnega, da se ta ne bi vrnil iz svoje zlobne poti, [s tem] da ste mu obljubljale življenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, '§ zato ne boste več videle praznih reči niti božanskih vedeževanj, kajti jaz bom osvobodil svoje ljudstvo iz vaše roke, in spoznale boste, da jaz sem Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Potem so prišli k meni nekateri izmed Izraelovih starešin in se usedli pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '§ »Človeški sin, ti možje so si v srcih postavljali malike in so si pred svoj obraz postavljali kamen spotike svoje krivičnosti; ali naj bi me oni potem sploh spraševali?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Zato jim govori in jim povej: »Tako govori Gospod Bog: ›Vsak mož iz Izraelove hiše, ki si v svojem srcu postavlja malike in pred svoj obraz polaga kamen spotike svoje krivičnosti in prihaja k preroku; jaz, Gospod, bom odgovoril tistemu, ki prihaja, glede na množico njegovih malikov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'da bi Izraelovo hišo lahko ujel v njihovem lastnem srcu, ker so se zaradi svojih malikov vsi odtujili od mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: ›Pokesajte se in odvrnite se od svojih malikov; odvrnite svoje obraze od vseh svojih ogabnosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Kajti vsakomur izmed Izraelove hiše, ali izmed tujca, ki začasno biva v Izraelu, ki se ločuje od mene in si v svojem srcu postavlja svoje malike in polaga kamen spotike svoje krivičnosti pred svoj obraz in prihaja k preroku, da bi od njega povprašal glede mene, mu bom jaz, Gospod, sam odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Svoj obraz bom naravnal zoper tega moža in naredil ga bom za znamenje in pregovor in odrezal ga bom iz srede svojega ljudstva; in spoznali boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Če pa je prerok zaveden, ko je govoril besedo, sem jaz, Gospod, zavedel tega preroka in jaz bom iztegnil svojo roko nanj in ga uničim iz srede svojega ljudstva Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Nosila bosta kazen svoje krivičnosti. Kazen preroka bo celo kakor kazen tistega, ki poizveduje k njemu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'da Izraelova hiša ne bo več zašla od mene niti ne bo več oskrunjena z vsemi svojimi prestopki; temveč da bodo lahko moje ljudstvo in bom jaz lahko njihov Bog, govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Gospodova beseda je prišla ponovno k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '»Človeški sin, kadar dežela greši zoper mene z mučnimi prekršitvami, takrat bom nadnjo iztegnil svojo roko in zlomil bom njeno oporo kruha in nadnjo bom poslal lakoto in iz nje bom iztrebil človeka in žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, '§ Čeprav bi bili v njej ti trije možje: Noe, Daniel in Job, bi s svojo pravičnostjo rešili zgolj svoje lastne duše,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '§ ›Če povzročim ogabnim živalim, da gredo skozi deželo, jo oplenijo tako, da je ta zapuščena, da zaradi živali noben človek ne bo mogel iti skoznjo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'čeprav bi bili ti trije možje v njej, kakor jaz živim,‹ govori Gospod Bog, ›ne bodo osvobodili niti sinov niti hčera; samo oni sami bodo osvobojeni, toda dežela bo zapuščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ali če privedem meč nad to deželo in rečem: ›Meč, pojdi skozi to deželo;‹ tako, da iz nje iztrebim ljudi in živali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, '§ čeprav bi bili ti trije možje v njej, kakor jaz živim,‹ govori Gospod Bog, ›ne bi osvobodili niti sinov niti hčera; samo oni sami bi bili osvobojeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ali če pošljem v to deželo kužno bolezen in če nanjo v krvi izlijem svojo razjarjenost, da iztrebim iz nje človeka in žival;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, '§ čeprav bi bili v njej Noe, Daniel in Job, kakor jaz živim,‹ govori Gospod Bog, ›ne bi osvobodili niti sinov niti hčera, temveč bodo po svoji pravičnosti osvobodili zgolj svoje lastne duše.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Kajti tako govori Gospod Bog: ›Koliko bolj, ko pošljem svoje štiri boleče sodbe nad Jeruzalem: meč, lakoto in ogabno zver in kužno bolezen, da iztrebim iz nje ljudi in živali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, '§ In vendar, glejte, bo tam ostal ostanek, ki bo izpeljan, tako sinov kakor hčera. Glejte, prišli bodo k vam in videli boste njihovo pot in njihova dejanja in potolaženi boste glede zla, ki sem ga privedel nad Jeruzalem, celó glede vsega, kar sem privedel nadenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'In potolažili vas bodo, ko boste videli njihove poti in njihova dejanja, in spoznali boste, da nisem brez vzroka storil vsega, kar sem storil v njem,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '»Človeški sin: ›Kaj je trta boljša kakor katerokoli drevo ali kakor mladika, ki je med gozdnimi drevesi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Mar bo vzet njen les, da bi opravljal katerokoli delo? Ali bodo možje od nje vzeli klin, da bi nanj obesili katerokoli posodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Glej, vržena je v ogenj za gorivo. Ogenj pogoltne oba njena konca in njena sreda je ožgana. Ali je primerna za kakršnokoli delo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Glej, ko je bila cela, ni bila primerna za nobeno delo. Kako veliko manj bo vendar ta primerna za kakršnokoli delo, ko jo je požrl ogenj in je ožgana?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Zato tako govori Gospod Bog: ›Kakor je trta med gozdnimi drevesi, ki sem jo izročil ognju za gorivo, tako bom izročil prebivalce Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Svoj obraz bom naravnal zoper njih. Šli bodo iz enega ognja, pa jih bo pogoltnil drug ogenj. In spoznali boste, da jaz sem Gospod, ko svoj obraz naravnam zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Deželo bom naredil zapuščeno, ker so zagrešili prekršek,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '»Človeški sin, povzroči [prestolnici] Jeruzalem, da spozna svoje ogabnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'in reci: ›Tako govori Gospod Bog [prestolnici] Jeruzalem: ›Tvoj rod in tvoje rojstvo je iz kánaanske dežele; tvoj oče je bil Amoréjec, tvoja mati pa Hetejka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Glede tvojega rojstva, na dan, ko si bila rojena, tvoj popek ni bil odrezan niti nisi bila umita v vodi, da ti omehča [kožo]; sploh nisi bila odrgnjena s soljo niti povita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Niti se te nobeno oko ni usmililo, da bi ti storilo karkoli od tega, da bi imelo do tebe sočutje; temveč si bila vržena na odprto polje, do gnusenja glede tvoje osebe, na dan, ko si bila rojena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'In ko sem šel mimo tebe in te videl oskrunjeno v svoji krvi, sem ti rekel, ko si bila v svoji krvi: ›Živi;‹ da, rekel sem ti, ko si bila v svoji krvi: ›Živi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, '§ Dal sem ti, da si se namnožila kakor brstje polja in povečala si se in postala velika in prišla k odličnim ornamentom. Tvoje prsi so se oblikovale in tvoji lasje so zrasli, medtem ko si bila naga in gola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Torej, ko sem šel mimo tebe in pogledal nate, glej, tvoj čas je bil čas ljubezni. Razširil sem krajec svojega oblačila nad teboj in pokril tvojo nagoto. Da, prisegel sem ti in vstopil v zavezo s teboj,‹ govori Gospod Bog ›in postala si moja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Potem sem te umil z vodo; da, temeljito sem izmil tvojo kri iz tebe in te mazilil z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Oblekel sem te tudi z izvezenim delom in ti obul jazbečevo kožo in te naokoli opasal s tankim lanenim platnom in te ogrnil s svilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Odel sem te tudi z ornamenti in na tvoje roke sem nataknil zapestnice in verižico na tvoj vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, '§ Položil sem dragulj na tvoje čelo in uhane v tvoja ušesa in krasno krono na tvojo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Tako si bila odeta z zlatom in srebrom, in tvoje oblačilo je bilo iz tankega lanenega platna, svile in izvezenega dela. Jedla si fino moko, med in olje. Bila si silno krasna in uspevala si v kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Tvoj ugled je zaradi tvoje lepote odšel naprej med pogane, kajti ta je bila popolna zaradi moje ljubkosti, ki sem jo položil nadte,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, '›Toda zaupala si v svojo lastno lepoto in igrala pocestnico zaradi svojega ugleda in svoje prešuštvovanje si izlila na vsakega, ki je šel mimo; njegovo je bilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Vzela si od svojih oblek in svoje visoke kraje si odela s številnimi barvami in na njih igrala pocestnico. Podobne stvari ne bodo prišle niti to ne bo tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Vzela si tudi svoje lepe dragocenosti od mojega zlata in od mojega srebra, ki sem ti jih dal in si si naredila moške podobe in z njimi zagrešila vlačugarstvo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'in jemala si svoje izvezene obleke in jih pokrivala in prednje si postavljala moje olje in moje kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Tudi moja hrana, ki sem ti jo dal, fina moka, olje in med, s katero sem te hranil, celo to si postavljala prednje v prijeten vonj. In tako je to bilo,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, '›Poleg tega si jemala svoje sinove in svoje hčere, ki si mi jih rodila in te si jim žrtvovala, da bi bili požrti. Je to izmed tvojih vlačugarstev majhna zadeva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'da si morila moje otroke in jim jih izročala, da gredo zanje skozi ogenj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'In v vseh svojih ogabnostih in svojih vlačugarstvih se nisi spomnila dni svoje mladosti, ko si bila naga in gola in si bila oskrunjena v svoji krvi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'In pripetilo se je po vseh tvojih zlobnostih (gorje, gorje tebi!‹ govori Gospod Bog),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'da si si zgradila tudi eminenten kraj in si si naredila visok kraj na vsaki ulici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Visok kraj si si zgradila na vsakem začetku poti in storila si, da je bila tvoja lepota prezirana in svoja stopala si razprla vsakemu, ki je šel mimo in pomnožila si svoja vlačugarstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Prav tako si zagrešila prešuštvovanje z Egipčani, svojimi sosedi velikega uda in svoja vlačugarstva si povečala, da bi me dražila do jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Glej, zato sem nad teboj iztegnil svojo roko in zmanjšal tvojo vsakdanjo hrano in te izročil volji tistih, ki te sovražijo, hčeram Filistejcev, ki se sramujejo tvojih nespodobnih poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Vlačugo si igrala tudi z Asirci, ker si bila nenasitna; da, z njimi si igrala pocestnico, pa vendar nisi mogla biti potešena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Poleg tega si pomnožila svoje prešuštvovanje v kánaanski deželi do Kaldeje; in vendar nisi bila potešena s tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Kako šibko je tvoje srce,‹ govori Gospod Bog, ›glede na to, da počneš vse te stvari, delo gospodovalne vlačugarske ženske;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'v tem, da si gradiš svoje eminentne kraje na začetku vsake poti in si delaš svoje visoke kraje na vsaki ulici; in nisi bila kot pocestnica, v tem, da preziraš plačilo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'temveč kakor žena, ki zagreši zakonolomstvo, ki jemlje tujce namesto svojega soproga!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Oni dajejo darila vsem vlačugam, toda ti daješ svoja darila vsem svojim ljubimcem in jih najemaš, da lahko pridejo k tebi na vsaki strani zaradi tvojega vlačugarstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'In v tvojem vlačugarstvu je v tebi nasprotje od drugih žensk, da zagrešiš vlačugarstva, medtem ko ti nihče ne sledi, in pri tem ti daješ nagrado, tebi pa ni dana nobena nagrada, zato si nasprotje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Zatorej, oh pocestnica, poslušaj besedo od Gospoda:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, '›Tako govori Gospod Bog: ›Ker je bila tvoja umazanost izlita in tvoja nagota odkrita zaradi tvojega vlačugarstva s tvojimi ljubimci in z vsemi maliki tvojih ogabnosti in s krvjo tvojih otrok, ki si jim jih dala;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'glej, zato bom zbral vse tvoje ljubimce, s katerimi si uživala in vse tiste, ki si jih ljubila, z vsemi tistimi, ki si jih sovražila; jaz jih bom celo zbral naokoli tebe zoper tebe in jim odkril tvojo nagoto, da bodo lahko videli vso tvojo nagoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Sodil te bom, kakor so sojene ženske, ki prelomijo zakonsko zvezo in prelijejo kri; in dal ti bom kri v razjarjenosti in ljubosumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Prav tako te bom izročil v njihovo roko in zrušili bodo tvoj eminenten kraj in zlomili tvoje visoke kraje. Slekli te bodo tudi iz tvojih oblačil in vzeli tvoje lepe dragocenosti in te pustili nago in golo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Prav tako bodo zoper tebe privedli skupino in te bodo kamnali s kamni in te prebodli s svojimi meči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Tvoje hiše bodo požgali z ognjem in izvršili sodbe nad teboj v očeh mnogih žensk. Povzročil ti bom, da prenehaš z igranjem pocestnice in tudi nobenega plačila ne boš več dajala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Tako bom svoji razjarjenosti zoper tebe naredil, da počiva in moja ljubosumnost bo odšla od tebe in bom miren in ne bom več jezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Ker se nisi spomnila dni svoje mladosti, temveč si me razburjala v vseh teh stvareh; glej, zato bom tudi jaz poplačal tvojo pot na tvoji glavi,‹ govori Gospod Bog: ›in ne boš zagrešila te nespodobnosti nad vsemi svojimi ogabnostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Glej, vsak, kdor uporablja pregovore, bo ta pregovor uporabil zoper tebe, govoreč: ›Kakršna je mati, takšna je njena hči.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, '§ Ti si hči svoje matere, ki prezira svojega soproga in svoje otroke; in ti si sestra svojih sestrá, ki so prezirale svoje soproge in svoje otroke. Tvoja mati je bila Hetejka in tvoj oče Amoréjec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, '§ Tvoja starejša sestra je Samarija, ona in njene hčere, ki prebivajo na tvoji levici. Tvoja mlajša sestra, ki prebiva pri tvoji desnici, je Sódoma in njene hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Vendar nisi hodila po njihovih poteh niti storila po njihovih ogabnostih. Temveč kot bi bila to malenkost, si bila bolj izprijena kakor one na vseh svojih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Kakor jaz živim,‹ govori Gospod Bog, ›niti tvoja sestra Sódoma niti njene hčere niso počele, kakor si storila ti in tvoje hčere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Glej, to je bila krivičnost tvoje sestre Sódome, ponos, polnost kruha, obilje brezdelja v njej in v njenih hčerah niti ni krepila roke ubogega in pomoči potrebnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Bile so ošabne in zagrešile ogabnost pred menoj, zato sem jih vzel proč, kakor se mi je videlo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Niti ni Samarija zagrešila polovice tvojih grehov, temveč si pomnožila svoje ogabnosti bolj kakor oni [dve] in opravičila si svoji sestri v vseh svojih ogabnostih, ki si jih storila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Tudi ti, ki si sodila svoji sestri, nosi svojo lastno sramoto za svoje grehe, ki si jih zagrešila bolj gnusno kakor oni [dve]. Oni sta pravičnejši kakor ti. Da, tudi ti bodi zbegana in nosi svojo sramoto v tem, da si opravičila svoji sestri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, '§ Ko bom ponovno privedel njihovo ujetništvo, ujetništvo Sódome in njenih hčera in ujetništvo Samarije in njenih hčera, takrat bom ponovno privedel ujetništvo tvojih ujetnikov v njihovi sredi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'da boš lahko nosila svojo lastno sramoto in boš lahko zbegana v vsem, kar si storila, v tem, da si jima tolažba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Ko se bodo tvoje sestre, Sódoma in njene hčere, vrnile k svojemu prejšnjemu stanju in se bodo Samarija in njene hčere vrnile k svojemu prejšnjemu stanju, takrat se boste ti in tvoje hčere vrnile k svojemu prejšnjemu stanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Kajti tvoja sestra Sódoma ni bila omenjena s tvojimi usti na dan tvojega ponosa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'preden je bila odkrita tvoja zlobnost, kakor ob času, ko so te grajale sirske hčere in vsi tisti, ki so okrog nje, hčere Filistejcev, ki te prezirajo vsenaokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Nosila si svojo nespodobnost in svoje ogabnosti,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, '§ Kajti tako govori Gospod Bog: ›S teboj bom postopal celo kakor si ti storila, ki si prezirala prisego v prelamljanju zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Kljub temu se bom spomnil svoje zaveze s teboj v dneh tvoje mladosti in osnoval ti bom večno zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, '§ Potem se boš spomnila svojih poti in boš osramočena, ko boš sprejela svoje sestre, svoje starejše in svoje mlajše, in dal ti jih bom za hčere, toda ne s tvojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'S teboj bom utrdil svojo zavezo in vedela boš, da jaz sem Gospod,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'da se lahko spomniš in boš zbegana in zaradi svoje sramote nikoli več ne boš odprla svojih ust, ko bom pomirjen proti tebi za vse, kar si storila,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'K meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '»Človeški sin, zastavi uganko in Izraelovi hiši spregovori prispodobo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'in reci: ›Tako govori Gospod Bog: ›Velik orel, z velikimi perutmi, z dolgimi krili, polnimi peres, ki ima različne barve, je prišel k Libanonu in vzel najvišjo cedrovo mladiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Odstrigel je vrh njenih mladih vej in ga prenesel v deželo preprodajanja; postavil ga je v mestu trgovcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Prav tako je vzel od semena dežele in ga zasadil na rodovitno polje. Namestil ga je ob velikih vodah in ga postavil kakor drevo vrbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'To je raslo in postalo razraščajoča se trta nizke rasti, čigar mladike so se obrnile proti njemu in njene korenine so bile pod njim. Tako je postala trta in obrodila mladike in poganjala vejice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, '§ Tam je bil tudi drug velik orel, z velikimi perutmi in mnogimi peresi. In glej, ta trta je svoje korenine upognila proti njemu in svoje mladike poganjala proti njemu, da bi jo ta lahko zalival pri brazdah njenega nasada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Zasajena je bila v dobri zemlji, ob velikih vodah, da bi lahko pognala mladike in da bi lahko obrodila sad, da bi bila lahko čedna trta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Reci: ›Tako govori Gospod Bog: ›Ali bo ta uspevala? Ali ji ne bo izruval njenih korenin in odrezal njen sad, da ovene? Ovenela bo pri vseh listih njenega izvira, celo brez velike moči ali mnogih ljudstev, da bi jo izruvali pri njenih koreninah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Da, glej, ko je vsajena, ali bo uspevala? Ali ne bo popolnoma ovenela, ko se je dotakne vzhodnik? Ovenela bo na brazdah, kjer je zrasla.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '»Reci torej uporni hiši: ›Mar ne veste kaj pomenijo te stvari?‹ Povej jim: ›Glejte, babilonski kralj je prišel v [prestolnico] Jeruzalem in zajel njenega kralja in njene prince in jih s seboj odvedel v Babilon');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'in zajel od kraljevega semena in z njim sklenil zavezo in od njega vzel prisego. Prav tako je zajel mogočneže dežele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'da bi bilo kraljestvo lahko ponižano, da se ne bi povzdigovalo, temveč da bi z ohranjanjem njegove zaveze lahko obstalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Toda ta se je uprl zoper njega s pošiljanjem svojih predstavnikov v Egipt, da bi mu lahko dali konje in veliko ljudstva. Ali bo uspel? Ali bo pobegnil ta, ki dela takšne stvari? Mar bo prelomil zavezo in bo osvobojen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo bo na kraju, kjer prebiva kralj, ki ga je postavil [za] kralja, čigar prisego je preziral in čigar zavezo je prelomil, celó pri njem bo umrl v sredi Babilona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Niti ne bo faraon s svojo mogočno vojsko in svojim velikim spremstvom delal zanj v vojni, s postavljanjem okopov in gradnjo trdnjav, da iztrebi mnogo oseb,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'ker je preziral prisego s prelamljanjem zaveze, ko je, glej, dal svojo roko in [vendar] storil vse te stvari; ne bo pobegnil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Zato tako govori Gospod Bog: › Kakor jaz živim, zagotovo bo meni dano prisego, ki jo je preziral in mojo zavezo, ki jo je prelomil, celo to bom poplačal na njegovi lastni glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Svojo mrežo bom razširil nad njim in ujet bo v mojo zanko in privedel ga bom v Babilon in tam se bom z njim pravdal zaradi njegovega prekrška, ki ga je prekršil zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Vsi njegovi ubežniki, z vsemi njegovimi četami, bodo padli pod mečem, tisti pa, ki preostanejo, bodo razkropljeni proti vsem vetrovom. In vedeli boste, da sem jaz, Gospod, to govoril.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tako govori Gospod Bog: ›Prav tako bom vzel od najvišje mladike na visoki cedri in jo bom posadil; od vrha njenih mladih vejic bom odstrigel eno nežno in jo zasadil na visoki in eminentni gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Na gori Izraelove višine jo bom zasadil in pognala bo veje in obrodila sad in postane čedna cedra. Pod njo bo prebivala vsa perjad od vsakega krila; v senci njenih mladik bodo prebivale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, '§ Vsa drevesa polja bodo vedela, da sem jaz, Gospod, ponižal visoko drevo, povišal nizko drevo, posušil zeleno drevo in suhemu drevesu storil, da cveti. Jaz, Gospod, sem govoril in sem to storil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '»Kaj mislite, da uporabljate ta pregovor glede Izraelove dežele, rekoč: ›Očetje so jedli kislo grozdje, zobje otrok pa so skominasti?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Kakor jaz živim,‹ govori Gospod Bog, ›nič več ne boste imeli priložnosti, da v Izraelu uporabljate ta pregovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Glejte, vse duše so moje; kakor očetova duša, tako je tudi sinova duša moja. Duša, ki greši, ta bo umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Toda če je človek pravičen in dela to, kar je zakonito in pravilno');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'in ni jedel po gorah, niti ni svojih oči povzdigoval k malikom Izraelove hiše, niti ni omadeževal žene svojega soseda, niti ni prišel blizu ženski, ki ima menstruacijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'in ni nikogar zatiral, temveč je dolžniku povrnil njegovo jamstvo, ni nikogar oplenil z nasiljem, svoj kruh dajal lačnemu in nagega pokrival z obleko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'ta, ki ni dajal za obresti, niti ni jemal nobenega dobička, ki je svojo roko umikal pred krivičnostjo, izvrševal pošteno sodbo med možem in možem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'hodil po mojih zakonih in se držal mojih sodb, da pravilno postopa; ta je pravičen, zagotovo bo živel,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, '›Če zaplodi sina ta, ki je ropar, prelivalec krvi in ki dela podobno katerikoli izmed teh stvari');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'in ki ne dela katerokoli izmed teh dolžnosti, temveč je celo jedel po gorah in omadeževal ženo svojega soseda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'zatiral revnega in pomoči potrebnega, plenil z nasiljem, ni povračal jamstva in svoje oči povzdigoval k malikom, zagrešil ogabnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, '§ dajal za obresti in jemal donos. Ali bo potem živel? Ta ne bo živel. Počenjal je vse te ogabnosti; zagotovo bo umrl; njegova kri bo na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Torej glej, če zaplodi sina, ki vidi vse grehe svojega očeta, ki jih je storil in preudarja in ne dela temu podobno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'da ni jedel po gorah niti svojih oči ni povzdigoval k malikom Izraelove hiše, ni omadeževal žene svojega soseda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'niti nobenega ni zatiral, ni zadrževal jamstva niti ni plenil z nasiljem, temveč je svoj kruh dajal lačnemu in nagega pokrival z obleko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'ki je zadrževal svoje roke pred [zatiranjem] revnega, ki ni prejemal obresti niti donosa, [ki je] izvrševal moje sodbe, hodil po mojih zakonih; ta ne bo umrl zaradi krivičnosti svojega očeta; zagotovo bo živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Kar se tiče njegovega očeta, ker je kruto zatiral, svojega brata plenil z nasiljem in med svojim ljudstvom počel to kar ni dobro, glej, celo ta bo umrl v svoji krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Vendar vi pravite: ›Zakaj? Ali sin ne nosi očetove krivičnosti? Kadar je sin storil, kar je zakonito in pravilno in se je držal vseh mojih zakonov in jih izvršil, bo zagotovo živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Duša, ki greši, ta bo umrla. Sin ne bo nosil očetove krivičnosti niti ne bo oče nosil sinove krivičnosti. Pravičnost pravičnega bo na njem in zlobnost zlobnega bo na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Toda če se bo zlobni obrnil od vseh svojih grehov, ki jih je zagrešil in se držal vseh mojih zakonov in storil to, kar je zakonito in pravilno, bo zagotovo živel, ne bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, '§ Vsi njegovi prestopki, ki jih je zagrešil, mu ne bodo omenjeni. V svoji pravičnosti, ki jo je storil, bo živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Ali imam sploh kakšno zadovoljstvo, da bi zlobni umrl?‹ govori Gospod Bog: › in ne, da bi se vrnil iz svojih poti in živel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, '§ Toda ko se pravični obrne proč od svoje pravičnosti in zagreši krivičnost in počne glede na vse ogabnosti, ki jih počne zloben človek, ali bo živel? Vsa njegova pravičnost, ki jo je storil, ne bo omenjena. V svojem prekršku, ki ga je prekršil in v svojem grehu, ki ga je zagrešil, v njima bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Vendar vi pravite: ›Gospodova pot ni primerna.‹ Poslušaj sedaj, oh Izraelova hiša; mar moja pot ni primerna? Ali niso vaše poti neprimerne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Ko se pravičen človek obrne proč od svoje pravičnosti in zagreši krivičnost in umira v njiju; zaradi svoje krivičnosti, ki jo je storil, bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, '§ Ponovno, kadar se zloben človek obrne proč od svoje zlobnosti, ki jo je zagrešil in dela to, kar je zakonito in pravilno, bo svojo dušo rešil živo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ker preudarja in se odvrača proč od vseh svojih prestopkov, ki jih je zagrešil, bo zagotovo živel, ne bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, '§ Vendar Izraelova hiša pravi: ›Gospodova pot ni primerna.‹ Oh Izraelova hiša, mar moje poti niso primerne? Ali niso vaše poti neprimerne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, '§ Zatorej vas bom sodil, oh Izraelova hiša, vsakogar glede na njegove poti,‹ govori Gospod Bog. Pokesajte se in se obrnite od vseh svojih prestopkov; tako krivičnost ne bo vaš propad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Od sebe odvrzite vse svoje prestopke, s katerimi ste se pregrešili in si naredite novo srce in novega duha, kajti zakaj hočete umreti, oh hiša Izraelova?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, '§ Kajti jaz nimam nobenega zadovoljstva v smrti tistega, ki umira,‹ govori Gospod Bog: ›zatorej se obrnite in živite.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '›Poleg tega vzdigni žalostinko za Izraelovimi princi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'in reci: ›Kaj je tvoja mati? Levinja. Ulegla se je med levi, svoje mladiče je hranila med mladimi levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Vzgojila je enega izmed svojih mladičev. Ta je postal mlad lev in se naučil loviti plen; ta je žrl ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Tudi narodi so slišali o njem; ujel se je v njihovo jamo in z verigami so ga odvedli v egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, '§ Torej ko je videla, da je čakala in je bilo njeno upanje izgubljeno, potem je vzela še enega izmed svojih mladičev in ga naredila za mladega leva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'In hodil je gor in dol med levi in postal mlad lev in se naučil loviti plen in žreti ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, '§ In poznal je njihove zapuščene palače in pustošil njihova mesta; in dežela je bila zapuščena in njena polnost s hrupom njegovega rjovenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Potem so se narodi od provinc na vsaki strani naravnali zoper njega in nad njim razprostrli svojo mrežo. Ujet je bil v njihovo jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'In dali so ga pod stražo, v verige in ga privedli k babilonskemu kralju. Privedli so ga v utrdbe, da njegovega glasu ne bi bilo več slišati na Izraelovih gorah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Tvoja mati je podobna trti v tvoji krvi, zasajena pri vodah. Bila je rodovitna in polna mladik zaradi razloga mnogih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Imela je močne palice za žezla tistih, ki so vladali in njena postava je bila povišana med debelimi mladikami in v svoji višini se je pojavila z množico svojih mladik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Toda izruvana je bila v razjarjenosti, vržena je bila na tla in vzhodnik je posušil njen sad. Njene močne palice so bile polomljene in so ovenele, ogenj jih je použil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'In sedaj je zasajena v divjini, v suhih in žejnih tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'In ogenj je izšel iz palice njenih mladik, ki je požrl njen sad, tako da ni imela nobene močne palice, ki bi bila žezlo za vladanje. To je žalostinka in bo za žalostinko.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'In pripetilo se je v sedmem letu, v petem mesecu, deseti dan meseca, da so določeni izmed Izraelovih starešin prišli, da bi povpraševali od Gospoda in se usedli pred menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Potem je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '»Človeški sin, govori Izraelovim starešinam in jim reci: ›Tako govori Gospod Bog: ›Ali ste prišli, da povprašujete od mene? Kakor jaz živim,‹ govori Gospod Bog, ›nočem biti povpraševan od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Ali jih hočeš soditi, človeški sin, ali jih hočeš soditi? Povzroči jim, da spoznajo ogabnosti njihovih očetov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'in jim reci: ›Tako govori Gospod Bog: ›Na dan, ko sem izbral Izraela in dvignil svojo roko k semenu Jakobove hiše in se jim dal spoznati v egiptovski deželi, ko sem vzdignil svojo roko k njim, rekoč: ›Jaz sem Gospod, vaš Bog;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'na dan, ko sem vzdignil svojo roko k njim, da jih privedem iz egiptovske dežele v deželo, ki sem jo odkril zanje, tekočo z mlekom in medom, ki je slava vseh dežel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Potem sem jim rekel: ›Vsak mož naj odvrže ogabnosti svojih oči in ne omadežujte se z egiptovskimi maliki.‹ Jaz sem Gospod, vaš Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, '›Toda uprli so se zoper mene in me niso hoteli poslušati. Noben mož ni odvrgel ogabnosti svojih oči niti niso zapustili egiptovskih malikov. Tedaj sem rekel: ›Nanje bom izlil svojo razjarjenost, da dovršim svojo jezo zoper njih v sredi egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Toda ravnal sem zaradi svojega imena, da to ne bi bilo oskrunjeno pred pogani, med katerimi so bili, v čigar pogledu sem se jim dal spoznati v tem, da sem jih privedel iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Zatorej sem jim velel, da gredo iz egiptovske dežele in jih privedel v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'In dal sem jim svoje zakone in jim pokazal svoje sodbe, katere, če jih človek izpolnjuje, bo torej živel v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Poleg tega sem jim dal tudi svoje šabate, da bodo znamenje med menoj in njimi, da bodo lahko vedeli, da jaz sem Gospod, ki jih posvečujem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Toda Izraelova hiša se je uprla zoper mene v divjini. Niso hodili po mojih zakonih in prezirali so moje sodbe, katere, če jih človek izpolnjuje, bo torej živel v njih; in moje šabate so silno oskrunili. Potem sem rekel: ›V divjini bom nadnje izlil svojo razjarjenost, da jih použije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Toda ravnal sem zaradi svojega imena, da le-to ne bi bilo oskrunjeno pred pogani, v katerem pogledu sem jih privedel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Vendar sem prav tako vzdignil svojo roko k njim v divjini, da jih ne bom privedel v deželo, ki sem jim jo dal, tekočo z mlekom in medom, katera je slava vseh dežel;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'zato ker so prezirali moje sodbe in niso hodili po mojih zakonih, temveč so oskrunili moje šabate, kajti njihovo srce je šlo za njihovimi maliki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Kljub temu jim je moje oko prizaneslo pred tem, da bi jih uničil niti jim v divjini nisem storil konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Temveč sem njihovim otrokom v divjini rekel: ›Ne hodite po zakonih svojih očetov niti ne obeležujte njihovih sodb niti se ne omadežujte z njihovimi maliki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Jaz sem Gospod, vaš Bog; ravnajte se po mojih zakonih in držite se mojih sodb in jih izvršujte;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'in posvečujte moje šabate; in te bodo znamenje med menoj in vami, da boste lahko vedeli, da jaz sem Gospod, vaš Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Vendar so se otroci uprli zoper mene. Niso se ravnali po mojih zakonih niti se niso ravnali po mojih sodbah, da bi jih izpolnjevali, katere, če človek izpolnjuje, bo torej živel po njih; oskrunjali so moje šabate. Potem sem rekel: ›Nadnje bom izlil svojo razjarjenost, da dovršim svojo jezo zoper njih v divjini.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Kljub temu sem umaknil svojo roko in zaradi svojega imena storil, da le-to ne bi bilo oskrunjeno pred očmi poganov, v čigar očeh sem jih izpeljal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'V divjini sem prav tako svojo roko vzdignil k njim, da bi jih razkropil med pogane in jih razpršil skozi dežele;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'ker niso izvrševali mojih sodb, temveč so prezirali moje zakone in skrunili moje šabate in njihove oči so bile za maliki njihovih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, '§ Zatorej sem jim prav tako izročil zakone, ki niso bili dobri in sodbe, po katerih naj ne bi živeli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'in oskrunil sem jih v njihovih lastnih darovih, s tem, da so počeli, da gre skozi ogenj vse, kar odpre maternico, da bi jih lahko naredil zapuščene, z namenom, da bi lahko vedeli, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Zatorej, človeški sin, govori Izraelovi hiši in jim reci: ›Tako govori Gospod Bog: ›Vendar so vaši očetje proti meni izrekali bogokletje v tem, da so zagrešili prekršek zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Kajti ko sem jih privedel v deželo, za katero sem vzdignil svojo roko, da jim jo dam, takrat so videli vsak visok hrib in vsa debela drevesa in tam so darovali svoje klavne daritve in tam so predstavljali izzivanje svojega daru. Tam so tudi naredili svoje prijetne dišave in tam so izlivali svoje pitne daritve.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Potem sem jim rekel: ›Kaj je visok kraj, kamor greste?‹ In njegovo ime je imenovano Bama do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: ›Ali ste oskrunjeni po načinu svojih očetov? In grešite vlačugarstvo po njihovih ogabnostih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Kajti ko darujete svoje darove, ko svojim sinovom povzročate, da gredo skozi ogenj, same sebe oskrunjate z vsemi svojimi maliki, celo do današnjega dne. In ali naj bom povpraševan od vas, oh Izraelova hiša? Kakor jaz živim,‹ govori Gospod Bog, ›nočem biti povpraševan od vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'In to, kar prihaja v vaše misli, sploh ne bo, da pravite: ›Mi bomo kakor pogani, kakor družine dežel, da služimo lesu in kamnu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, '› Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo bom z mogočno roko in z iztegnjenim laktom in z izlito razjarjenostjo vladal nad vami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'in vas izpeljem izmed ljudstva in vas zberem iz dežel, po katerih ste razkropljeni, z mogočno roko, z iztegnjenim laktom in z izlito razjarjenostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'In jaz vas bom privedel v divjino ljudstev in tam se bom pravdal z vami iz obličja v obličje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Podobno kakor sem se pravdal z vašimi očeti v divjini egiptovske dežele, tako se bom pravdal z vami,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, '›In povzročil vam bom, da boste šli pod palico in privedel vas bom v vez zaveze');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'in izmed vas bom očistil upornike in tiste, ki so odpadli zoper mene. Izpeljal jih bom iz dežele, kjer začasno prebivajo in ne bodo vstopili v Izraelovo deželo in spoznali boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, '§ Glede vas, oh Izraelova hiša,‹ tako govori Gospod Bog: ›Pojdite, služite vsak svojim malikom in tudi v prihodnje, če mi nočete prisluhniti. Toda ne skrunite več mojega svetega imena s svojimi darovi in svojimi maliki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Kajti na moji sveti gori, na gori Izraelove višine,‹ govori Gospod Bog, ›tam mi bo [služila] vsa Izraelova hiša, vsi izmed njih v deželi mi [bodo] služili. Tam jih bom sprejel in tam bom zahteval vaše daritve in prve sadove vaših daritev, z vsemi vašimi svetimi stvarmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Sprejel vas bom z vašim prijetnim vonjem, ko vas odvedem izmed ljudstev in vas zberem iz dežel, kamor ste bili razkropljeni; in jaz bom posvečen v vas pred pogani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'In vedeli boste, da jaz sem Gospod, ko vas bom privedel v Izraelovo deželo, v deželo, za katero sem vzdignil svojo roko, da jo dam vašim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'In tam se boste spomnili svojih poti in vseh svojih dejanj, s katerimi ste bili omadeževani; in gnusili se boste samim sebi, v svojem lastnem pogledu, zaradi vseh svojih hudobij, ki ste jih storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'In spoznali boste, da jaz sem Gospod, ko z vami postopam zaradi svojega imena, ne glede na vaše zlobne poti niti ne glede na vaša izprijena početja, oh vi, hiša Izraelova,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '»Človeški sin, naravnaj svoj obraz proti jugu in svojo besedo spusti proti jugu in prerokuj zoper gozd južnega polja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'in reci južnemu gozdu: ›Poslušaj Gospodovo besedo: ›Tako govori Gospod Bog: ›Glej, v tebi bom zanetil ogenj in ta bo v tebi pogoltnil vsako zeleno drevo in vsako suho drevo. Plameneč ogenj ne bo pogašen in vsi obrazi, od juga do severa, bodo v njem ožgani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'In vse meso bo videlo, da sem ga zanetil jaz, Gospod. Ta ne bo pogašen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Potem sem rekel: »Ah, Gospod Bog! O meni pravijo: ›Mar on ne govori prispodob?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '»Človeški sin, naravnaj svoj obraz proti Jeruzalemu in spusti svojo besedo proti svetim krajem in prerokuj zoper Izraelovo deželo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'in reci Izraelovi deželi: ›Tako govori Gospod: ›Glej, jaz sem zoper tebe in izvlekel bom svoj meč iz nožnice in iz tebe bom iztrebil pravičnega in zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Ker bom iz tebe iztrebil pravičnega in zlobnega, bo zato moj meč šel iz nožnice zoper vse meso od juga do severa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'da bo lahko vse meso vedelo, da sem jaz, Gospod, izvlekel svoj meč iz nožnice. Ta se ne bo več vrnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Zdihuj torej, ti, človeški sin, s trganjem svojih ledij; in z grenkim vzdihom pred njihovimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'In zgodilo se bo, ko ti bodo rekli: ›Zakaj vzdihuješ?‹ da boš odgovoril: ›Zaradi novic, ker le-te prihajajo.‹ In vsako srce se bo stopilo in vse roke bodo slabotne in vsak duh bo medlel in vsa kolena bodo šibka kakor voda. Glej, to prihaja in se bo zgodilo,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '»Človeški sin, prerokuj in reci: ›Tako govori Gospod: ›Reci: ›Meč, meč je nabrušen in tudi zglajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Nabrušen je, da naredi boleč pokol; zglajen je, da se lahko lesketa. Naj bi se mi potem razveseljevali? Ta zaničuje palico mojega sina kakor vsako drevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'In on ga je dal zgladiti, da bi lahko z njim rokoval. Ta meč je nabrušen in zglajen, da ga da v roko ubijalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Jokaj in tuli, človeški sin, kajti ta bo nad mojim ljudstvom, ta bo nad Izraelovimi princi. Strahote zaradi meča bodo nad mojim ljudstvom. Udari torej na svoje stegno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Ker je to preizkušnja in kaj če meč zaničuje celo palico? To ne bo več,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '›Ti torej, človeški sin, prerokuj in zaploskaj s svojima rokama in naj bo meč tretjič podvojen, meč umorjenih. To je meč velikih ljudi, ki so umorjeni, ki vstopa v njihove skrivne sobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Konico meča sem naravnal zoper vsa njihova velika vrata, da bo njihovo srce lahko slabelo in [bodo] njihovi propadi pomnoženi. Ah! Narejen je [da se] lesketa, zavit je za pokol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Pojdi eno pot ali drugo, ali na desno ali na levo, kamor je naravnan tvoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Tudi jaz bom plosknil s svojima rokama in bom umiril svojo razjarjenost. Jaz, Gospod, sem to govoril.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '»Tudi ti, človeški sin, si določi dve poti, da bo lahko prišel meč babilonskega kralja. Obe bosta izšli iz ene dežele in izberi kraj, izberi ga ob začetku poti v mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Določi pot, da lahko pride meč v Rabo Amóncev in v Juda in zaščiteno [prestolnico] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Kajti babilonski kralj je stal pri razpotju poti, ob začetku dveh poti, da uporabi vedeževanje. Svoje puščice je posvetlil, posvetoval se je z družinskimi maliki, gledal je v jetra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Pri njegovi desni roki je bilo vedeževanje za [prestolnico] Jeruzalem, da določi častnike, da odpre usta v pokol, da povzdigne glas s kričanjem, da določi oblegovalne ovne proti velikim vratom, da nasuje nasip in da zgradi utrdbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'In to jim bo kakor napačno vedeževanje v njihovem pogledu, tistim, ki so prisegli prisege, toda v spomin bo priklical krivičnost, da bodo lahko zajeti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Zato tako govori Gospod Bog: ›Ker ste storili, da se bo spominjalo vaše krivičnosti v tem, da so vaši prestopki odkriti, tako da se pri vseh vaših dejanjih pojavijo vaši grehi; ker jaz pravim, da ste prišli v spomin, boste zajeti z roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'In ti, oskrunjen, zloben Izraelov princ, katerega dan je prišel, ko se krivičnosti naredi konec,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'tako govori Gospod Bog: ›Odstrani diadem in snemi krono. To ne bo [več] isto. Povišaj tistega, ki je nizek in ponižaj tistega, ki je visok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Jaz bom to preobrnil, preobrnil, preobrnil in tega ne bo nič več, dokler ne pride tisti, katerega pravica je to in njemu jo bom izročil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ti pa, človeški sin, prerokuj in reci: ›Tako govori Gospod Bog glede Amóncev in glede njihove graje; celo reci: ›Meč, meč je izvlečen. Za pokol je zglajen, da použiva zaradi lesketanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Medtem ko zate vidijo ničnost, medtem ko ti vedežujejo laž, da te privedejo nad vratove tistih, ki so umorjeni izmed zlobnih, katerih dan je prišel, ko bo njihova krivičnost končana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Ali mu bom povzročil, da se vrne v svojo nožnico? Sodil te bom na kraju, kjer si bil ustvarjen, v deželi tvojega rojstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'In nate bom izlil svoje ogorčenje in zoper tebe bom pihal v ognju svojega besa in te izročil v roko brutalnežev in veščih, da uničujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Ti boš za gorivo ognju; tvoja kri bo v sredi dežele; ne bo se te več spominjalo, kajti jaz, Gospod, sem to govoril.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '»Torej, človeški sin, ali boš sodil, ali boš sodil krvoločno mesto? Da, pokazal mu boš vse njegove ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Potem reci: ›Tako govori Gospod Bog: ›Mesto v svoji sredi preliva kri, da lahko pride njegov čas in zoper sebe izdeluje malike, da se omadežuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Postalo si krivo v svoji krvi, ki si jo prelilo; in omadeževalo si se s svojimi maliki, ki si jih naredilo; in svojim dnevom si povzročilo, da so se približali in prišlo si celó k svojim letom. Zato sem te naredil za grajo poganom in zasmeh vsem deželam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Tisti, ki so blizu in tisti, ki so daleč od tebe, te bodo zasmehovali, ki so neslavni in precej nadležni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Glej, Izraelovi princi, vsak je bil v tebi k njihovi moči, da preliva kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'V tebi so prezirali očeta in mater. V tvoji sredi so z zatiranjem postopali s tujcem. V tebi so nadlegovali osirotelega in vdovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Preziralo si moje svete stvari in oskrunilo moje šabate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'V tebi so ljudje, ki prenašajo govorice, da prelijejo kri; in v tebi jedo po gorah. V tvoji sredi zagrešujejo nespodobnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'V tebi so odkrili nagoto svojih očetov. V tebi so ponižali tisto, ki je bila oddvojena zaradi oskrunitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'In nekdo je zagrešil ogabnost z ženo svojega soseda; in drugi je opolzko omadeževal svojo snaho; in drugi je v tebi ponižal svojo sestro, hčer svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'V tebi so jemali darila, da prelijejo kri. Jemalo si obresti in donos in z izsiljevanjem si lakomno pridobivalo od svojih sosedov in si me pozabilo,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, '›Glej, zato sem udaril svojo roko ob tvoj nepošten dobiček, ki si ga naredilo in pri tvoji krvi, ki je bila v tvoji sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Ali tvoje srce lahko prenese, ali so tvoje roke lahko močne v dneh, ko bom obračunal s teboj? Jaz, Gospod sem to govoril in bom to storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'In razkropil te bom med pogane in te razpršil v dežele in iz tebe použil tvojo umazanost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'In vzelo boš svojo dediščino v sebi, pred očmi poganov in vedelo boš, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '»Človeški sin, Izraelova hiša mi je postala žlindra. Vsi so bron, kositer, železo in svinec v sredi talilne peči; so celó srebrova žlindra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Zato tako govori Gospod Bog: ›Ker ste vsi postali žlindra, glejte, zato vas bom zbral v sredi [prestolnice] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Kakor oni zbirajo srebro in bron in železo in svinec in kositer v sredi talilne peči, da nanjo pihajo ogenj, da to raztalijo; tako vas bom jaz zbral v svoji jezi in svoji razjarjenosti in vas bom pustil tam in vas raztalil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Da, zbral vas bom in pihal nad vas v ognju svojega besa in vi boste raztaljeni v njeni sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Kakor je srebro raztaljeno v sredi talilne peči, tako boste raztaljeni v njeni sredi in spoznali boste, da sem jaz, Gospod, nad vas izlil svojo razjarjenost.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '»Človeški sin, reci ji: ›Ti si dežela, ki ni očiščena niti ni nanjo deževalo na dan ogorčenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Tam je zarota njenih prerokov v njeni sredi, podobna rjovenju leva, željnega plena. Požrli so duše, vzeli so zaklad in dragocene stvari; v njeni sredi so naredili mnogo vdov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Njeni duhovniki so prekršili mojo postavo in oskrunili moje svete stvari. Niso pokazali nobene razlike med svetim in oskrunjenim niti niso pokazali razlike med nečistim in čistim in svoje oči so skrili pred mojimi šabati in jaz sem med njimi oskrunjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Njeni princi v njeni sredi so podobni volkovom, željnim plena, da prelijejo kri in da uničijo duše, da pridobijo nepošten dobiček.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'In njeni preroki so jih ometali z neutrjeno malto, gledoč ničnost in vedeževali so jim laži, rekoč: ›Tako govori Gospod Bog,‹ ko Gospod ni govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Ljudstvo dežele je uporabljalo zatiranje in izvajalo rop in jezilo revne in pomoči potrebne; da, krivično so zatirali tujca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'In iskal sem človeka med njimi, ki bi naredil ograjo in stal v razpoki pred menoj za deželo, da je ne bi uničil, toda nikogar nisem našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Zato sem nadnje izlil svoje ogorčenje; použil sem jih z ognjem svojega besa. Njihovo lastno pot sem poplačal na njihovih glavah,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '»Človeški sin, bili sta dve ženski, hčeri ene matere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, '§ Zagrešili sta vlačugarstva v Egiptu, v svoji mladosti sta zagrešili vlačugarstva. Tam so bile njune prsi stiskane, tam so poškodovali seske njunega devištva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Njuni imeni sta bili: Ohóla, starejša in njena sestra Oholíba. Bili sta moji in rodili sta sinove in hčere. Taki sta bili njuni imeni: Samarija je Ohóla, [prestolnica] Jeruzalem pa Oholíba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ohóla je igrala pocestnico, ko je bila moja in nora je bila na svoje ljubimce, na Asirce, svoje sosede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'ki so bili oblečeni z modro, častnike in vladarje, vse izmed njih privlačne mladeniče, konjenike, jahajoče na konjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Tako je z njimi zagrešila svoja vlačugarstva, z vsemi tistimi, ki so bili izbrani možje Asirije in z vsemi, na katere je bila nora, z vsemi njihovimi maliki, s katerimi se je omadeževala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Niti ni zapustila svojih vlačugarstev, prinesenih iz Egipta, kajti v njeni mladosti so ležali z njo in poškodovali prsi njenega devištva in nanjo izlili svoja vlačugarstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Zatorej sem jo izročil v roko njenih ljubimcev, v roko Asircev, na katere je bila nora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ti so odkrili njeno nagoto. Vzeli so njene sinove in njene hčere in jo usmrtili z mečem in postala je slavna med ženskami, kajti izvršili so sodbo nad njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'In ko je njena sestra Oholíba to videla, je bila bolj izprijena v svoji neobrzdani ljubezni kakor ona in v svojih vlačugarstvih bolj kakor njena sestra v njenih vlačugarstvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Nora je bila na Asirce, svoje sosede, častnike in vladarje, najbolj krasno oblečene, konjenike, jahajoče na konjih, vse izmed njih privlačne mladeniče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Potem sem videl, da je bila omadeževana, da sta obe šli eno pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'In povečala je svoja vlačugarstva, kajti ko je zagledala može, upodobljene na zidu, podobe Kaldejcev, upodobljene z živo rdečo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'opasane s pasovi na svojih ledjih, z izjemnim okrasom na svojih glavah, vse izmed njih na pogled prince, po načinu Babiloncev iz Kaldeje, dežele njihovega rojstva;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'takoj ko jih je s svojimi očmi zagledala, je bila nora nanje in k njim poslala poslance v Kaldejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'In Babilonci so prišli k njej v posteljo ljubezni in jo omadeževali s svojim vlačugarstvom in bila je onesnažena z njimi in njen um se je odtujil od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Tako je odkrila svoja vlačugarstva in odkrila svojo nagoto. Potem se je moj um odtujil od nje, podobno kakor je bil moj um odtujen od njene sestre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Vendar je svoja vlačugarstva pomnožila s spominjanjem na dni svoje mladosti, v katerih je igrala pocestnico v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Kajti nora je bila na svoje nezakonite ljubimce, katerih meso je kakor meso oslov in katerih izliv je podoben izlivu konjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tako si klicala v spomin nespodobnost svoje mladosti, v poškodovanju tvojih seskov s strani Egipčanov, zaradi tvojih mladostnih prsi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Zato, oh Oholíba,‹ tako govori Gospod Bog: ›Glej, zoper tebe bom obudil tvoje ljubimce, od katerih se je odtujil tvoj um in na vsaki strani jih bom privedel zoper tebe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babilonce in vse Kaldejce, Pekód in Šoo in Koo in vse Asirce z njimi, vse izmed njih privlačne mladeniče, častnike in vladarje, velike gospode in ugledne, vse izmed njih jahajoče na konjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'In prišli bodo zoper tebe z bojnimi vozovi, vozovi in kolesi in z zborom ljudstva, ki bo naokoli nastavilo zoper tebe majhen ščit in ščit in čelado. Prednje bom postavil sodbo in sodili te bodo glede na svoje sodbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'In zoper tebe bom naravnal svojo ljubosumnost in besno bodo postopali s teboj. Odvzeli ti bodo tvoj nos in tvoja ušesa; in tvoj preostanek bo padel pod mečem. Odvzeli bodo tvoje sinove in tvoje hčere; in tvoj preostanek bo požrt z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Tudi slekli te bodo iz tvojih oblačil in ti odvzeli tvoje lepe dragocenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Tako bom tvoji nespodobnosti storil, da izgine od tebe in tvojemu vlačugarstvu, privedenemu iz egiptovske dežele, da svojih oči ne boš dvignila k njim niti se ne boš več spominjala Egipta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Kajti tako govori Gospod Bog: ›Glej, izročil te bom v roko tistih, ki jih sovražiš, v roko tistih, od katerih se je tvoj um odtujil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'S teboj bodo postopali sovražno in ves tvoj trud bodo odvedli in pustili te bodo nago in boso. Odkrita bo nagota tvojih vlačugarstev, tako tvoja nespodobnost kot tvoja vlačugarstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Jaz ti bom storil te stvari, ker si vlačugarsko odšla za pogani in ker si oskrunjena z njihovimi maliki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Hodila si po poti svoje sestre; zato bom njeno čašo dal v tvojo roko.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tako govori Gospod Bog: ›Pila boš iz čaše svoje sestre, globoke in velike. Zasmehovana boš do norčevanja in v posmeh; ta mnogo drži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Napolnjena boš s pijanostjo in bridkostjo, s čašo osuplosti in opustošenja, s čašo tvoje sestre Samarije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'To boš celo pila in to izsesala in zlomila boš njene črepinje in iztrgala svoje lastne prsi, kajti jaz sem to govoril,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Zato tako govori Gospod Bog: ›Ker si me pozabila in me vrgla za svoj hrbet, zatorej tudi ti nosi svoje nespodobnosti in svoja vlačugarstva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Gospod mi je poleg tega rekel: »Človeški sin, hočeš soditi Ohólo in Oholíbo? Da, razglasi jima njune ogabnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'da sta zagrešili zakonolomstvo in je kri na njunih rokah in s svojimi maliki sta zagrešili zakonolomstvo in tudi svojim sinovom, ki sta mi jih rodili, sta storili, da so zanju prešli skozi ogenj, da jih je požrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Poleg tega sta mi storili še to: v istem dnevu sta omadeževali moje svetišče in oskrunili moje šabate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Kajti ko sta svoje otroke morili svojim malikom, potem sta istega dne prišli v moje svetišče, da ga oskrunita; in glej, tako sta počeli v sredi moje hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'In nadalje, da sta poslali po može, da pridejo od daleč, h katerim je bil poslan poslanec; in glej, prišli so, za katere si se umivala in ličila svoje oči in se odevala z ornamenti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Sedela si na imenitni postelji in miza je pripravljena pred njo, na katero si postavljala moje kadilo in moje olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, '§ In glas brezskrbne množice je bil z njo, in z običajnimi možmi so bili privedeni Sabejci iz divjine, ki si na svoje roke natikajo zapestnice in krasne krone na svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Potem sem rekel njej, ki je bila stara v zakonolomstvih: ›Ali bodo sedaj zagrešili vlačugarstva z njo in ona z njimi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Vendar so odšli noter k njej, kakor gredo v žensko, ki igra pocestnico, tako so šli noter v Ohólo in v Oholíbo, nespodobni ženski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Pravični možje pa ju bodo sodili po načinu zakonolomk in po načinu žensk, ki prelivajo kri, ker sta zakonolomki in je kri na njunih rokah.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Kajti tako govori Gospod Bog: ›Nadnju bom privedel skupino in izročil ju bom, da bosta odstranjeni in oplenjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'In skupina ju bo kamnala s kamni in razmesarila s svojimi meči; ubili bodo njune sinove in njune hčere, njune hiše pa bodo požgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Tako bom nespodobnosti storil, da izgine iz dežele, da bodo lahko vse ženske poučene, da ne počnejo po vajini nespodobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, '§ In vajino nespodobnost bodo poplačali na vama in nosili bosta grehe svojih malikov, in spoznali bosta, da jaz sem Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'V devetem letu, v desetem mesecu, na deseti dan meseca je ponovno prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '»Človeški sin, zapiši si ime dneva, celó tega istega dne. Babilonski kralj se je ta isti dan nameril zoper [prestolnico] Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'In izreci prispodobo uporni hiši ter jim reci: ›Tako govori Gospod Bog: ›Pristavi lonec, pristavi ga in prav tako vanj nalij vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Zberi vanj kose, celó vsak dober kos, stegno in pleče; napolni ga z izbranimi kostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Vzemi izbrano od tropa in pod njim prav tako sežgi kosti in naredi, da bo dobro vrelo in v njem naj prevrejo njegove kosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Zato tako govori Gospod Bog: ›Gorje krvoločnemu mestu, loncu, čigar plast umazanije je v njem in katerega plast umazanije ni odšla od njega! Prinesi to ven, kos za kosom; naj noben žreb ne pade na to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Kajti njena kri je v njeni sredi; postavljala jo je na vrh skale; ni je izlivala na tla, da jo pokrije s prahom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'da bi lahko povzročila razjarjenosti, da pride gor, da se maščuje; njeno kri sem postavil na vrh skale, da ne bi bila pokrita.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Zato tako govori Gospod Bog: ›Gorje krvoločnemu mestu! Naredil bom celo grmado za velik ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Nakopičite les, zanetite ogenj, použijte meso in ga dobro začinite in naj bodo kosti sežgane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Potem ga praznega postavite na ognjeno oglje, da njegov bron lahko razbeli in lahko zagori in da bo njegova umazanost lahko v njem stopljena, da bo plast umazanije v njem lahko použita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Samo sebe je izmučila z lažmi in njena velika plast umazanije ni šla ven iz nje. Njena plast umazanije bo v ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'V tvoji umazanosti je nespodobnost. Ker sem te očistil, ti pa nisi bila očiščena, ne boš več očiščena svoje umazanosti, dokler svoji razjarjenosti ne storim, da počiva na tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, '§ Jaz, Gospod, sem to govoril. To se bo zgodilo in jaz bom to storil; ne bom šel nazaj niti ne bom prizanašal niti se ne bom kesal; glede na tvoje poti in glede na tvoja početja te bodo sodili,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Prav tako je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '»Človeški sin, glej, z udarcem vzamem od tebe željo tvojih oči. Vendar ne boš žaloval niti jokal niti tvoje solze ne bodo tekle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Zadrži se jokanja, nobenega žalovanja za mrtvimi ne opravljaj, nad svojo glavo si zaveži ruto in nadeni si svoje čevlje na svoja stopala in ne pokrivaj svojih ustnic in ne jej kruha od ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Tako sem ljudstvu govoril zjutraj, zvečer pa je moja žena umrla; in zjutraj sem storil, kakor mi je bilo ukazano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'In ljudstvo mi je reklo: »Ali nam ne boš povedal kaj so nam te stvari, da jih tako počneš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Potem sem jim odgovoril: »K meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, '›Govori Izraelovi hiši: ›Tako govori Gospod Bog: ›Glejte, oskrunil bom svoje svetišče, odličnost vaše moči, željo vaših oči in to, kar vaša duša pomiluje; in vaši sinovi in vaše hčere, ki ste jih pustili, bodo padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'In storili boste, kakor sem jaz storil: ne boste pokrili svojih ustnic niti jedli kruha od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'In vaše rute bodo na vaših glavah in vaši čevlji na vaših stopalih. Ne boste niti žalovali niti jokali; temveč boste hirali zaradi svojih krivičnosti in žalovali drug proti drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Tako vam je Ezekiel znamenje: glede na vse, kar je storil, boste vi storili. In ko to pride, boste spoznali, da jaz sem Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Tudi ti, človeški sin, ali ne bo to na dan, ko jim odvzamem njihovo moč, radost njihove slave, željo njihovih oči in to, na kar so naravnali svoje ume, njihove sinove in njihove hčere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'da bo tisti, ki pobegne na ta dan, prišel k tebi, da ti povzroči, da to slišiš s svojimi lastnimi ušesi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Na tisti dan se bodo tvoja usta odprla k tistemu, ki je pobegnil in govoril boš in ne boš več nem. Ti jim boš znamenje. In spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '»Človeški sin, naravnaj svoj obraz proti Amóncem in prerokuj zoper njih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'in reci Amóncem: ›Poslušajte besedo Gospoda Boga. Tako govori Gospod Bog, ker praviš: ›Aha, zoper moje svetišče, ko je bilo oskrunjeno; in zoper Izraelovo deželo, ko je bila zapuščena; in zoper Judovo hišo, ko so odšli v ujetništvo;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'glej, zatorej te bom izročil možem vzhoda za posest in v tebi si bodo postavili svoje palače in svoja prebivališča bodo naredili v tebi. Jedli bodo tvoj sad in pili bodo tvoje mleko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'In jaz bom Rabo naredil hlev za kamele in Amónce kraj ležišča za trope, in spoznali boste, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Kajti tako govori Gospod Bog: ›Ker si ploskal s svojima rokama in topotal s stopali in se razveseljeval v srcu z vsem svojim prezirom zoper Izraelovo deželo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'glej, zato bom nadte iztegnil svojo roko in te izročil v plen poganom; in jaz te bom odrezal izmed ljudstev in ti povzročil, da izgineš iz dežel. Uničil te bom, in vedel boš, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tako govori Gospod Bog: ›Zato ker Moáb in Seír govorita: ›Glej, Judova hiša je podobna vsem poganom;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'zatorej, glej, odprl bom Moábov bok od mest, od njegovih mest, ki so na njegovih mejah, slavo dežele: Bet Ješimót, Báal Meón in Kirjatájim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'do mož vzhoda z Amónci [vred] in jih dal v posest, da se Amóncev ne bo spominjalo med narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'In izvršil bom sodbe nad Moábom; in spoznali bodo, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tako govori Gospod Bog: ›Zato ker je Edóm zoper Judovo hišo ravnal z maščevanjem in [jih] silno užalil in se maščeval nad njimi;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'zato tako govori Gospod Bog: ›Tudi jaz bom svojo roko iztegnil nad Edóm in iz njega bom iztrebil moža in žival; in opustošil ga bom od Temána; in tisti iz Dedána bodo padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'In svoje maščevanje bom položil nad Edóm po roki svojega ljudstva Izraela, in v Edómu bodo storili glede na mojo jezo in glede na mojo razjarjenost; in spoznali bodo moje maščevanje,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tako govori Gospod Bog: ›Ker so Filistejci postopali z maščevanjem in so se maščevali s krutim srcem, da ga uničijo zaradi starega sovraštva;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'zato tako govori Gospod Bog: ›Glej, svojo roko bom iztegnil nad Filistejce in iztrebil bom Keretéjce in uničil bom preostanek morske obale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'In nad njimi bom izvršil veliko maščevanje z besnimi grajami; in spoznali bodo, da jaz sem Gospod, ko bom nanje položil svoje maščevanje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'In pripetilo se je v enajstem letu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '»Človeški sin, zato ker je Tir zoper [prestolnico] Jeruzalem rekel: ›Aha, zlomljena je tista, ki je bila velika vrata ljudstvom, obrnjena je k meni: ›Na novo bom napolnjena,‹ sedaj je opustošena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Zato tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Tir in povzročil bom, da bodo zoper tebe prišli številni narodi, kakor morje povzroči svojim valovom, da se vzdignejo gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'In uničili bodo zidove Tira in porušili njegove stolpe. Prav tako bom iz njega postrgal prah in ga naredil podobnega vrhu skale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'To bo kraj za razprostiranje mrež sredi morja, kajti jaz sem to govoril,‹ govori Gospod Bog: ›in bo postal plen narodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, '§ In njegove hčere, ki so na polju, bodo umorjene z mečem; in spoznali bodo, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Kajti tako govori Gospod Bog: ›Poglej, nad Tir bom privedel babilonskega kralja Nebukadnezarja, kralja kraljev, iz severa, s konji in bojnimi vozovi in s konjeniki in skupinami in mnogo ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Na polju bo z mečem ubil tvoje hčere in naredil bo utrdbo zoper tebe in zoper tebe nasul nasip in zoper tebe vzdignil majhen ščit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Svoje vojne stroje bo uperil zoper tvoje zidove in s svojimi sekirami bo porušil tvoje stolpe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Zaradi obilja njegovih konj te bo pokril njihov prah. Tvoji zidovi se bodo tresli ob hrupu konjenikov, koles in bojnih vozov, ko bo vstopil v tvoja velika vrata, kakor možje vstopijo v mesto, v katerem je narejena vrzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'S kopiti svojih konj bo pomendral vse tvoje ulice. Tvoje ljudstvo bo pobil z mečem in tvoje močne posadke bodo popadale na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Iz tvojih bogastev bodo naredili plen in zaplenili bodo tvoje trgovanje in porušili bodo tvoje zidove in uničili tvoje prijetne hiše in tvoje kamne, tvoj les in tvoj prah bodo pometali v sredo voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'In povzročil bom, da bo hrup tvojih pesmi prenehal, in zvoka tvojih harf ne bo več slišati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'In naredil te bom kakor vrh skale. Ti boš kraj, na katerem se razprostirajo mreže; ne boš več pozidan, kajti jaz, Gospod, sem to govoril,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tako govori Gospod Bog Tiru: ›Mar se ne bodo otoki stresli ob zvoku tvojega padca, ko bodo ranjeni jokali, ko bo v tvoji sredi narejen pokol?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Potem bodo vsi morski princi stopili dol iz svojih prestolov in odložili svoja svečana oblačila in slekli svoje izvezene obleke. Oblekli se bodo s trepetanjem. Sedeli bodo na tleh in trepetali bodo vsak trenutek in osupli bodo nad teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'In zate bodo povzdignili žalostinko in ti rekli: ›Kako si uničen, ki si bil naseljen s pomorščaki, ugledno mesto, ki je bilo močno na morju, ono in njegovi prebivalci, ki so svoji strahoti povzročili, da je bila na vseh, ki so ga strašili!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Sedaj bodo otoki trepetali na dan tvojega padca; da, otoki, ki so na morju, bodo vznemirjeni ob tvojem odhodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Kajti tako govori Gospod Bog: ›Ko te bom naredil [za] zapuščeno mesto, podobno mestom, ki niso naseljena; ko bom nadte privedel globino in te bodo pokrile velike vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'ko te bom privedel dol s tistimi, ki se spuščajo v jamo, z ljudstvom iz starih časov in te bodo postavili v spodnje kraje zemlje, na kraje, ki so zapuščeni od davnine, s tistimi, ki gredo dol do jame, da ne boš naseljen, in jaz bom postavil slavo v deželi živih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'naredil te bom strahoto in tebe ne bo več. Čeprav te bodo iskali, vendar nikoli več ne boš najden,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '»Torej ti, človeški sin, vzdigni žalostinko za Tirom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'in reci Tiru: ›Oh ti, ki si postavljen na vhodu morja, ki si trgovec ljudstvom na številnih otokih: ›Tako govori Gospod Bog: ›O Tir, rekel si: ›Jaz sem popolne lepote.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tvoje meje so v sredi morij, tvoji graditelji so dovršili tvojo lepoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Vse tvoje ladijske deske so naredili iz cipresovega lesa iz Senírja. Vzeli so libanonske cedre, da bi zate naredili jambore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, '§ Iz bašánskih hrastov so naredili tvoja vesla; skupina Ašhúrcev je naredila tvoje klopi iz slonovine, pripeljane iz kitéjskih otokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Tanko laneno platno z izvezenim delom iz Egipta je bilo to, kar si razširjala, da bi bilo tvoje jadro; modro in vijolično z otokov Elišája, je bilo to, kar te je pokrivalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Prebivalci Sidóna in Arváda so bili tvoji mornarji. Tvoji modri možje, oh Tir, ki so bili v tebi, so bili tvoji krmarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Gebálski starci in njegovi modri možje so bili v tebi tvoji popravljavci razpok. Vse morske ladje s svojimi mornarji so bile v tebi, da so prekupčevali tvoje trgovsko blago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Tisti iz Perzije in iz Luda in iz Puta so bili v tvoji vojski, tvoji bojevniki. V tebi so obešali ščit in čelado; oni kažejo tvojo ljubkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Možje Arváda, s tvojo vojsko, so bili na tvojih zidovih naokoli in Gamádci so bili v tvojih stolpih. Svoje ščite so obešali naokoli po tvojih zidovih; tvojo lepoto so naredili popolno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Taršíš je bil tvoj trgovec zaradi razloga množice vseh vrst bogastev; s srebrom, železom, kositrom in svincem so trgovali na tvojih sejmih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javán, Tubál in Mešeh so bili tvoji trgovci. Trgovali so s človeškimi osebami in posodami iz brona na tvojem trgu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Tisti iz hiše Togarmá so na tvojih sejmih trgovali s konji, konjeniki in mulami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Možje iz Dedána so bili tvoji trgovci, številni otoki so bili trgovsko blago tvoje roke, za darilo so ti prinašali rogove iz slonovine in ebenovino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, '§ Sirija je bila tvoj trgovski partner zaradi razloga množičnosti stvari tvoje izdelave. Na tvojih sejmih so se zaposlovali s smaragdi, vijoličnim in izvezenim delom in tankim lanenim platnom in koraldo in ahatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda in Izraelova dežela so bili tvoji trgovci. Trgovali so na tvojem trgu s pšenico iz Miníta in Pannago in medom, oljem in balzamom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damask je bil tvoj trgovski partner v množici stvari tvoje izdelave zaradi množice vseh bogastev; z vinom iz Helbóna in belo volno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Tudi Dán in Javán, ki sta šla sem ter tja, sta se zaposlovala na tvojih sejmih. Svetlo železo, kasija in kolmež so bili na tvojem trgu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedán je bil tvoj trgovec v dragocenih oblačilih za bojne vozove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabija in vsi princi Kedárja so se zaposlovali s teboj z jagnjeti, ovni in kozli; v teh so bili oni tvoji trgovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Trgovci iz Sabe in Ramája, oni so bili tvoji trgovci. Zaposlovali so se na tvojih sejmih z glavnino izmed vseh dišav in z vsemi dragocenimi kamni in z zlatom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Harán in Kané in Eden, trgovci iz Sabe, Asúrja in Kilmáda so bili tvoji trgovci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, '§ To so bili tvoji trgovci v vseh vrstah stvari, v modrih oblačilih in izvezenem delu in v skrinjah bogatega videza, povezanih z vrvicami in narejenimi iz cedre, med tvojim trgovanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Ladje iz Taršíša so pele o tebi na tvojem trgu in ti si bil na novo napolnjen in zelo veličastno narejen v sredi morij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tvoji veslači so te privedli v velike vode. Vzhodni veter te je zlomil v sredi morij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tvoja bogastva, tvoji sejmi, tvoji trgovci, tvoji mornarji in tvoji krmarji, tvoji popravljavci razpok, zaposlovalci tvojega trgovanja in vsi tvoji bojevniki, ki so v tebi in v vsej tvoji skupini, ki je v tvoji sredi, bodo padli v sredo morij na dan tvojega propada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Predmestja se bodo tresla ob zvoku krika tvojih krmarjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'In vsi, ki prijemajo veslo, mornarji in vsi krmarji morja bodo prišli dol iz svojih ladij, stali bodo na kopnem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'in svojemu glasu bodo povzročili, da bo slišan zoper tebe in grenko bodo jokali in metali prah na svoje glave in se valjali v pepelu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'in zate se bodo naredili popolnoma plešaste in se prepasali z vrečevino in jokali bodo zaradi tebe s srčno grenkobo in grenko tarnali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'In v svojem tarnanju bodo vzdignili žalostinko za teboj in žalovali nad teboj, rekoč: ›Katero mesto je podobno Tiru, podobno uničenemu v sredi morja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Ko so tvoje stvari šle naprej iz morij, si sitil mnoga ljudstva, kralje zemlje si obogatil z množico svojih bogastev in od svojega trgovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, '§ V času, ko boš zlomljen z morji, v globinah voda, bo tvoje trgovsko blago in vsa tvoja druščina padla v tvoji sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Vsi prebivalci otokov bodo osupli nad teboj in njihovi kralji bodo boleče prestrašeni, vznemirjeni bodo na svojem obličju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Trgovci med ljudstvom bodo sikali nad teboj; strahota boš in nikoli več te ne bo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '»Človeški sin, povej princu Tira: ›Tako govori Gospod Bog: ›Ker je tvoje srce povzdignjeno in si rekel: ›Jaz sem Bog, sedim na Božjem sedežu v sredi morij;‹ vendar si človek in ne Bog, čeprav si svoje srce postavljal kakor srce Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Glej, modrejši si kakor Daniel; ni skrivnosti, ki jo lahko skrijejo pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'S svojo modrostjo in s svojim razumevanjem si si pridobil bogastva in v svojih zakladnicah si si pridobil zlato in srebro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'S svojo veliko modrostjo in s svojim preprodajanjem si povečal svoja bogastva in tvoje srce je povzdignjeno zaradi tvojih bogastev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Zato tako govori Gospod Bog: ›Ker si svoje srce postavil kakor srce Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'glej, zato bom nadte privedel tujce, strašne izmed narodov. Svoje meče bodo izvlekli zoper lepoto tvoje modrosti in omadeževali bodo tvoj sijaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Privedli te bodo dol do jame in umrl boš [s] smrtmi tistih, ki so umorjeni v sredi morij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Ali boš še govoril pred tistim, ki te ubija: ›Jaz sem Bog?‹ Toda ti boš mož in ne Bog, v roki tistega, ki te ubija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Umrl boš s smrtmi neobrezancev, po roki tujcev, kajti jaz sem to govoril,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '»Človeški sin, vzdigni žalostinko nad kraljem Tira in mu reci: ›Tako govori Gospod Bog: ›Ti pečatiš vsoto, poln si modrosti in popoln v lepoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Bil si v Raju, Božjem vrtu; vsak dragocen kamen je bil tvoje pokrivalo: sardij, topaz in diamant, beril, oniks in jaspis, safir, smaragd, granat in zlato. Izdelava tvojih bobničev in tvojih piščali je bila pripravljena v tebi na dan, ko si bil ustvarjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ti si maziljen kerub, ki zaslanja; in jaz sem te tako postavil. Bil si na sveti gori Boga; hodil si gor in dol v sredi ognjenih kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Bil si popoln na svojih poteh, od dneva, ko si bil ustvarjen, dokler ni bila v tebi najdena krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Z množico tvojih trgovanj so tvojo sredo napolnili z nasiljem in si grešil, zato te bom pahnil, kot oskrunjenega iz Božje gore in te bom uničil, oh zaslanjajoči kerub, iz srede ognjenih kamnov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Tvoje srce se je povzdignilo zaradi tvoje lepote, svojo modrost si izpridil zaradi svojega sijaja. Jaz te bom vrgel na tla, jaz te bom položil pred kralje, da te bodo lahko gledali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Svoja svetišča si omadeževal z množico svojih krivičnosti, s krivičnostjo svojega preprodajanja; zato bom privedel ogenj iz tvoje srede; ta te bo požrl, jaz pa te bom spremenil v pepel na zemlji, pred očmi vseh tistih, ki te gledajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'In tisti, ki te med ljudstvom poznajo, bodo osupli nad teboj. Strahota boš in nikoli te ne bo več.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '»Človeški sin, naravnaj svoj obraz proti Sidónu in prerokuj zoper njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'ter reci: ›Tako govori Gospod Bog: ›Glej, zoper tebe sem, oh Sidón; in proslavljen bom v tvoji sredi in vedeli bodo, da jaz sem Gospod, ko bom izvršil sodbe v njem in bom posvečen v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Kajti vanj bom poslal kužno bolezen in kri na njegove ulice; in ranjeni bodo sojeni v njegovi sredi z mečem na njem, na vsaki strani; in spoznali bodo, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'In ne bo več bodečega osata nad Izraelovo hišo niti kakršnegakoli bolečega trna od vseh, ki so okoli njih, ki so jih prezirali; in spoznali bodo, da jaz sem Gospod Bog.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tako govori Gospod Bog: ›Ko bom Izraelovo hišo zbral izmed ljudstev, med katere so razkropljeni in bom posvečen v njih v očeh poganov, potem bodo prebivali v svoji deželi, ki sem jo dal svojemu služabniku Jakobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'In v njej bodo varno prebivali in gradili bodo hiše in sadili vinograde; da, prebivali bodo z zaupanjem, ko izvršim sodbe nad vsemi tistimi, ki jih prezirajo naokoli njih; in spoznali bodo, da jaz sem Gospod, njihov Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'V desetem letu, v desetem mesecu, na dvanajsti dan meseca je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '»Človeški sin, naravnaj svoj obraz proti faraonu, egiptovskemu kralju in prerokuj zoper njega in zoper ves Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Govori in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, faraon, egiptovski kralj, veliki zmaj, ki ležiš v sredi svojih rek, ki praviš: ›Moja reka je moja lastna in naredil sem jo zase.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Toda dal ti bom kavlje v čeljusti in ribam tvojih rek bom povzročil, da se prilepijo na tvoje luskine in izvlekel te bom iz srede tvojih rek in vse ribe tvojih rek se bodo prilepile na tvoje luskine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'In pustil te bom vreči v divjino, tebe in vse ribe tvojih rek. Padel boš na odprta polja; ne boš zbližan niti ne zbran. Dal sem te za hrano poljskim živalim in perjadi neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'In vsi prebivalci Egipta bodo spoznali, da jaz sem Gospod, ker so bili trstična palica za Izraelovo hišo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Kadar so te prijeli za tvojo roko, si se zlomil in raztrgal vso njihovo ramo, in ko so se oprli nate, si se zlomil in storil, da vsa njihova ledja odrevenijo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Zato tako govori Gospod Bog: ›Glej, nadte bom privedel meč in iz tebe iztrebil človeka in žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'In egiptovska dežela bo zapuščena in opustošena; in spoznali bodo, da jaz sem Gospod, ker je rekel: ›Reka je moja in jaz sem jo naredil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Glej, zato sem zoper tebe in zoper tvoje reke in egiptovsko deželo bom naredil popolnoma opustošeno in zapuščeno od Siénskega stolpa celó do meje Etiopije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Skoznjo ne bo šlo nobeno človeško stopalo niti ne bo šlo skozi živalsko stopalo niti štirideset let ne bo naseljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'In egiptovsko deželo bom naredil zapuščeno v sredi pokrajin, ki so zapuščene in njena mesta, med mesti, ki so opustošena, bodo zapuščena štirideset let in Egipčane bom razkropil med narode in jih razpodil po pokrajinah.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Vendar tako govori Gospod Bog: ›Ob koncu štiridesetih let bom zbral Egipčane izmed ljudstev, kamor so bili razkropljeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'in ponovno bom privedel ujetništvo Egipta in povzročil jim bom, da se vrnejo v deželo Patrós, v deželo svojega prebivališča; in tam bodo nizko kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'To bo najnižje izmed kraljestev niti se ne bo več povzdigovalo nad narodi, kajti jaz jih bom zmanjšal, da ne bodo več vladali nad narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'In le-to ne bo več zaupanje Izraelove hiše, ki v spomin prinaša njihovo krivičnost, ko bodo gledali za njimi, toda spoznali bodo, da jaz sem Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Pripetilo se je v sedemindvajsetem letu, v prvem mesecu, na prvi dan meseca, [da] je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '»Človeški sin, babilonski kralj Nebukadnezar je svoji vojski storil, da služi sijajno službo zoper Tir. Vsaka glava je bila narejena plešasto in vsaka rama je bila oluščena, vendar ni imel nobenih plačil niti njegova vojska za Tir, za službo, ki jo je opravil zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Zato tako govori Gospod Bog: ›Glej, egiptovsko deželo bom dal Nebukadnezarju, babilonskemu kralju; in on bo zajel njeno množico in vzel njeno ukradeno blago in vzel njen plen; in to bodo plačila za njegovo vojsko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Izročil sem mu egiptovsko deželo za njegov trud, s katerim je služil zoper njo, ker so delali zame,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, '›Na tisti dan bom rogu Izraelove hiše povzročil, da vzbrsti in jaz ti bom dal odprtje ust v njihovi sredi, in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '»Človeški sin, prerokuj in reci: ›Tako govori Gospod Bog: ›Tulite: ›Dan, vreden gorja!‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Kajti dan je blizu, celo Gospodov dan je blizu, oblačen dan; to bo čas poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Meč bo prišel nad Egipt in velika bolečina bo v Etiopiji, ko bodo umorjeni padli v Egiptu in bodo proč odpeljali njegovo množico in njegovi temelji bodo zrušeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, '§ Etiopija, Libija in Ludéja in vsa pomešana ljudstva in Kub in možje dežele, ki je v zavezi, bodo z njimi padli pod mečem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tako govori Gospod: ›Tudi tisti, ki podpirajo Egipt, bodo padli; in ponos njegove oblasti se bo zrušil. Od siénskega stolpa bodo v njem padli pod mečem,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, '›In opustošeni bodo v sredi dežel, ki so opustošene in njegova mesta bodo v sredi mest, ki so opustošena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'In spoznali bodo, da jaz sem Gospod, ko sem dal ogenj v Egipt in ko bodo vsi njegovi pomočniki uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Na tisti dan bodo poslanci šli pred menoj na ladjah, da prestrašijo brezskrbne Etiopijce in velika bolečina bo prišla nadnje kakor na dan Egipta, kajti, glej, ta prihaja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tako govori Gospod Bog: ›Tudi egiptovski množici bom storil, da odneha po roki babilonskega kralja Nebukadnezarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On in njegovo ljudstvo z njim, strašni izmed narodov, bodo privedeni, da uničijo deželo in svoje meče bodo izvlekli zoper Egipt in deželo napolnili z umorjenimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, '§ Posušil bom reke in deželo prodal v roko zlobnega, in deželo in vse, kar je v njej, bom naredil opustošenje po roki tujcev. Jaz, Gospod sem to govoril.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tako govori Gospod Bog: ›Prav tako bom uničil malike in njihovim podobam bom povzročil, da bodo izginile iz Nofa; in tam ne bo nič več princa iz egiptovske dežele, in na egiptovsko deželo bom položil strah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Patrós bom naredil zapuščen in prižgal bom ogenj na Coanu in izvršil bom sodbe v Noju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'In svojo razjarjenost bom izlil nad Sin, moč Egipta; in iztrebil bom množico iz Noja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Zanetil bom ogenj v Egiptu. Sin bo imel veliko bolečino in No bo raztrgan in Nof bo imel dnevne tegobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Mladeniči iz Avena in iz Pi Beseta bodo padli pod mečem, in ta mesta bodo šla v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Tudi v Tahpanhésu bo dan otemnel, ko bom tam zlomil egiptovske jarme, in pomp njegove moči bo prenehal v njem. Kar se tiče njega, oblak ga bo pokril in njegove hčere bodo šle v ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Tako bom izvršil sodbe v Egiptu, in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'In pripetilo se je v enajstem letu, v prvem mesecu, na sedmi dan meseca, da je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '»Človeški sin zlomil sem laket faraonu, egiptovskemu kralju; in glej, ta ne bo obvezan, da bi bil ozdravljen, da položi povoj, da ga poveže, da ga naredi močnega za držanje meča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Zato tako govori Gospod Bog: ›Glej jaz sem zoper faraona, egiptovskega kralja in zlomil bom njegova lakta, zdravega in tistega, ki je bil zlomljen; in storil bom, da iz njegove roke pade meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Egipčane bom razkropil med narode in jih razpodil po deželah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Okrepil pa bom lakte babilonskega kralja in v njegovo roko položim svoj meč. Toda faraonova lakta bom zlomil in pred njim bo stokal s stokanjem smrtno ranjenega moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Toda okrepil bom lakta babilonskega kralja, faraonova lakta pa bosta upadla in spoznali bodo, da jaz sem Gospod, ko bom svoj meč položil v roko babilonskega kralja in iztegnil ga bo nad egiptovsko deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'In Egipčane bom razkropil med narode in jih razpodil med dežele; in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'In pripetilo se je v enajstem letu, v tretjem mesecu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '»Človeški sin, spregovori faraonu, egiptovskemu kralju in njegovi množici: ›Komu si podoben v svoji veličini?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Glej, Asirec je bil cedra na Libanonu, z lepimi mladikami in s senčnato kopreno in visoke rasti; in njegov vrh je bil med debelimi vejami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vode so ga naredile velikega, globina ga je s svojimi rekami, ki tečejo naokoli njegovih rastlin, postavila gor na višavo in pošiljala ven svoje majhne reke do vseh poljskih dreves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Zatorej je bila njegova višina povišana nad vsa poljska drevesa in njegove veje so bile pomnožene in njegove mladike so postale dolge zaradi obilice voda, ko je poganjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Vsa perjad neba je naredila svoja gnezda v njegovih vejah in pod njegovimi mladikami so vse živali polja kotile svoje mlade in pod njegovo senco so prebivali vsi veliki narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Tako je bil lep v svoji veličini, v dolžini svojih mladik, kajti njegova korenina je bila ob velikih vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedre v Božjem vrtu ga niso mogle skriti. Ciprese niso bile podobne njegovim vejam in kostanjeva drevesa niso bila podobna njegovim mladikam; niti katerokoli drevo v Božjem vrtu ni bilo podobno njemu v njegovi lepoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Naredil sem ga lepega z množico njegovih mladik, tako da so mu vsa edenska drevesa, ki so bila v Božjem vrtu, zavidala.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Zato tako govori Gospod Bog: ›Ker si se povzdigoval na višino in je svoj vrh poganjal med debelimi vejami in je njegovo srce povzdignjeno na njegovo višino;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'zato sem ga izročil v roko mogočnega izmed poganov; zagotovo bo obračunal z njim. Ven sem ga izgnal zaradi njegove zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'In tujci, strašni izmed narodov, so ga odrezali in ga zapustili. Po gorah in po vseh dolinah so padle njegove mladike in njegove veje so zlomljene ob vseh rekah dežele; in vsa ljudstva zemlje so šla dol iz njegove sence in ga zapustila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Na njegovem uničenju bo ostala vsa perjad neba in vse živali polja bodo na njegovih mladikah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'z namenom, da se nobeno izmed vseh dreves ob vodah ne bo povzdigovalo zaradi svoje višine niti svojega vrha poganjalo med debele veje niti ne bodo njihova drevesa stala na njihovi višini, vsa, ki pijejo vodo, kajti vsa so izročena smrti, k spodnjim delom zemlje, v sredo človeških otrok, s tistimi, ki gredo dol k jami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tako govori Gospod Bog: ›Na dan, ko je šel dol do groba, sem povzročil žalovanje. Zanj sem pokril globino in omejil njegove tokove in velike vode so bile ustavljene. Libanonu sem storil, da je žaloval za njim in vsa poljska drevesa so medlela zaradi njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Narodom sem storil, da se tresejo ob zvoku njegovega padca, ko sem ga vrgel dol do pekla, s tistimi, ki se spuščajo v jamo in vsa edenska drevesa, izbrana in najboljša iz Libanona, vsa, ki pijejo vodo, bodo potolažena v spodnjih delih zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Tudi oni so z njim odšli dol v pekel, k tistim, ki so umorjeni z mečem; in tisti, ki so bili njegov laket, ki so prebivali pod njegovo senco v sredi narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Komu si ti tako podoben v slavi in v veličini med edenskimi drevesi? Vendar boš z edenskimi drevesi priveden dol v spodnje dele zemlje. Ležal boš v sredi neobrezancev, s tistimi, ki so umorjeni z mečem. To je faraon in vsa njegova množica,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'In pripetilo se je v dvanajstem letu, v dvanajstem mesecu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '»Človeški sin, vzdigni žalostinko za faraonom, egiptovskim kraljem in mu reci: ›Podoben si mlademu levu izmed narodov in ti si kakor kit v morjih in prihajaš naprej s svojimi rekami in s svojimi stopali burkaš vode in usmrajuješ njihove reke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tako govori Gospod Bog: ›Zato bom nad teboj razprostrl svojo mrežo s spremstvom mnogih ljudstev; in privedli te bodo gor v mojo mrežo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Potem te bom pustil na deželi, vrgel te bom naprej na odprto polje in vsej perjadi neba bom povzročil, da ostanejo na tebi in s teboj bom nasitil živali celotne zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'In tvoje meso bom položil na gore in s tvojo višino napolnil doline.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Tudi s tvojo krvjo bom namočil deželo, v kateri plavaš, celó do gora; in reke te bodo polne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Ko te bom ugasnil, bom pokril nebo in zatemnil zvezde; sonce bom pokril z oblakom in luna ne bo dajala svoje svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Vse svetle luči neba nad teboj bom otemnil in postavil temo nad tvojo deželo,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Prav tako bom dražil srca mnogih ljudi, ko bom med narode privedel tvoje uničenje, v dežele, ki jih nisi poznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Da, naredil bom, da bodo mnoga ljudstva osupla nad teboj in njihovi kralji bodo strašno prestrašeni zaradi tebe, ko bom pred njimi vihtel svoj meč; in trepetali bodo ob vsakem trenutku, vsak človek za svoje lastno življenje, na dan tvojega padca.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Kajti tako govori Gospod Bog: ›Meč babilonskega kralja bo prišel nadte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Z meči mogočnega bom tvoji množici povzročil, da pade, strašni izmed narodov, vsi izmed njih, in oplenili bodo pomp Egipta in vsa njegova množica bo uničena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Prav tako bom uničil tudi vse njegove živali, ki so poleg velikih vodá. Niti jih ne bo več vznemirjalo človeško stopalo niti jih ne bodo vznemirjala kopita živine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Potem bom njihove vode naredil globoke in njihovim rekam povzročil, da tečejo kakor olje,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, '›Ko bom egiptovsko deželo naredil zapuščeno in bo dežela oropana tega, česar je bila polna, ko bom udaril vse tiste, ki prebivajo tam, takrat bodo vedeli, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'To je žalostinka, s katero ga bodo objokovali. Hčere narodov ga bodo objokovale. Žalovali bodo za njim, celó za Egiptom in za vso njegovo množico,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'In prav tako se je pripetilo v dvanajstem letu, na petnajsti dan meseca, da je k meni prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '»Človeški sin, tarnaj za egiptovsko množico in vrzi jo dol, celó njo in hčere slavnih narodov, v spodnje dele zemlje, s tistimi, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Koga prekašaš v lepoti? Pojdi dol in bodi položen z neobrezanimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Padli bodo v sredo tistih, ki so umorjeni z mečem. Izročen je meču. Potegni njega in vse njegove množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Močni izmed mogočnih mu bodo govorili iz srede pekla s tistimi, ki mu pomagajo. Odšli so dol, ležijo neobrezani, umorjeni z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tam je Asúr in vse njegovo spremstvo. Njegovi grobovi so okoli njega, vsi izmed njih umorjeni, padli pod mečem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'katerih grobovi so postavljeni ob straneh jame in njegovo spremstvo je naokoli njegovega groba; vsi izmed njih umorjeni, padli pod mečem, ki so povzročili strahoto v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tam je Elám in vsa njegova množica naokoli njegovega groba, vsi izmed njih umorjeni, padli pod mečem, ki so neobrezani odšli dol, v spodnje dele zemlje, ki so povzročili njihovo strahoto v deželi živih; vendar so nosili svojo sramoto s tistimi, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Pripravili so mu posteljo v sredi umorjenih, z vso njegovo množico. Njegovi grobovi so okoli njega; vsi izmed njih neobrezani, umorjeni z mečem. Čeprav je bila njihova strahota storjena v deželi živih, so vendar nosili svojo sramoto s tistimi, ki gredo dol v jamo. Položen je v sredo tistih, ki so umorjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tam je Mešeh, Tubál in vsa njegova množica. Njegovi grobovi so okoli njega; vsi izmed njih neobrezani, umorjeni z mečem, četudi so svojo strahoto povzročali v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Ne bodo ležali z mogočnimi, ki so padli od neobrezancev, ki so odšli dol k peklu z njihovimi bojnimi orožji. Njihove meče so položili pod njihove glave, toda njihove krivičnosti bodo na njihovih kosteh, čeprav so bili strahota mogočnih v deželi živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Da, zlomljen boš v sredi neobrezancev in ležal boš s tistimi, ki so umorjeni z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tam je Edóm, njegovi kralji in vsi njegovi princi, ki so s svojo močjo položeni od tistih, ki so bili umorjeni z mečem. Ležali bodo z neobrezanimi in s tistimi, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tam bodo princi iz severa, vsi izmed njih in vsi Sidónci, ki so odšli dol z umorjenimi; s svojo strahoto se sramujejo svoje moči; in ležijo neobrezani, s tistimi, ki so umorjeni z mečem in svojo sramoto nosijo s tistimi, ki gredo dol v jamo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraon jih bo videl in potolažen bo nad vso svojo množico, celó faraon in vsa njegova vojska, umorjena z mečem,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, '›Kajti povzročil sem svojo strahoto v deželi živih in položen bo v sredo neobrezancev, s tistimi, ki so umorjeni z mečem, celó faraon in vsa njegova množica,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Ponovno je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '»Človeški sin, spregovori otrokom svojega ljudstva in jim reci: ›Ko privedem meč nad deželo, če ljudstvo dežele vzame človeka iz svojih obal in ga postavi za svojega stražarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Če ta zatrobi na šofar in posvari ljudstvo, kadar vidi nad deželo prihajati meč;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'potem kdorkoli sliši zvok šofarja in ne sprejme svarila; če pride meč in ga vzame, bo njegova kri na njegovi lastni glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Slišal je zvok šofarja in ni sprejel svarila; njegova kri bo nad njim. Toda kdor sprejme svarilo, bo rešil svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Toda če stražar vidi prihajati meč, pa ne zatrobi na šofar in ljudstvo ni posvarjeno, če pride meč in vzame kateregakoli človeka izmed njih, je ta odvzet v svoji krivičnosti; toda njegovo kri bom zahteval iz stražarjeve roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Tako sem tebe, oh človeški sin, postavil [za] stražarja Izraelovi hiši; zato boš slišal besedo pri mojih ustih in jih posvaril v mojem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Ko rečem zlobnemu: ›Oh zlobni človek, zagotovo boš umrl;‹ če ne spregovoriš, da zlobnega posvariš pred njegovo potjo, bo ta zloben človek umrl v svoji krivičnosti, toda njegovo kri bom zahteval pri tvoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Vendar če posvariš zlobnega o njegovi poti, da se odvrne od nje; če se ta ne odvrne iz svoje poti, bo umrl v svoji krivičnosti; toda ti si rešil svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Zato, oh ti, človeški sin, spregovori Izraelovi hiši: ›Tako govorite, rekoč: ›Če so naši prestopki in naši grehi nad nami in v njih hiramo, kako bi potem živeli?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Reci jim: › Kakor jaz živim,‹ govori Gospod Bog, ›nobenega zadovoljstva nimam v smrti zlobnega; temveč, da se zlobni odvrne od svoje poti in živi. Obrnite se, obrnite se od svojih zlih poti; kajti zakaj hočete umreti, oh hiša Izraelova?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Zato ti, človeški sin, reci otrokom svojega ljudstva: ›Pravičnost pravičnega ga ne bo rešila na dan njegovega prestopka. Glede zlobnosti zlobnega, on s tem ne bo padel na dan, ko se obrne od svoje zlobnosti; niti pravični ne bo zmožen živeti po svoji pravičnosti na dan, ko greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Ko bom rekel pravičnemu, da bo zagotovo živel; če ta zaupa svoji lastni pravičnosti in zagreši krivičnost, se vse njegove pravičnosti ne bo spominjalo; toda zaradi svoje krivičnosti, ki jo je zagrešil, bo zaradi nje umrl.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Ponovno, kadar rečem zlobnemu: ›Ti boš zagotovo umrl;‹ če se ta obrne od svojega greha in dela to, kar je zakonito in pravilno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'če zlobni povrne jamstvo, ponovno da, kar je naropal, se ravna po zakonih življenja, ne da bi zagrešil krivičnost; zagotovo bo živel, ne bo umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Nobeden izmed njegovih grehov, ki jih je zagrešil, mu ne bo omenjen. Storil je to, kar je zakonito in pravilno; zagotovo bo živel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Vendar otroci tvojega ljudstva pravijo: ›Gospodova pot ni enakovredna.‹ Toda kar se tiče njih, njihova pot ni enakovredna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Ko se pravični obrne od svoje pravičnosti in grešno zagreši krivičnost, bo s tem torej umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Toda če se zlobni odvrne od svoje zlobnosti in počne to, kar je zakonito in pravilno, bo s tem živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Vendar vi pravite: ›Gospodova pot ni enakovredna.‹ Oh vi, hiša Izraelova, vsakogar bom sodil po njegovih poteh.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'In pripetilo se je v dvanajstem letu našega ujetništva, v desetem mesecu, na peti dan meseca, da je tisti, ki je pobegnil iz [prestolnice] Jeruzalem, prišel k meni, rekoč: »Mesto je udarjeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Torej Gospodova roka je bila nad menoj zvečer, prej, preden je prišel ta, ki je pobegnil. Odprl je moja usta, dokler ni oni zjutraj prišel k meni; in moja usta so bila odprta in nisem bil več nem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Potem je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '»Človeški sin, tisti, ki poseljujejo opustošenosti dežele Izrael, govorijo, rekoč: ›Abraham je bil en in je podedoval deželo, toda nas je mnogo. Dežela nam je dana v dediščino.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Zato jim reci: ›Tako govori Gospod Bog: ›Vi jeste s krvjo in svoje oči povzdigujete k svojim malikom in prelivate kri; in ali boste vzeli v last deželo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Stojite na svojem meču, počnete ogabnost in omadežujete, vsak ženo svojega soseda; in ali boste vzeli v last deželo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tako jim reci: ›Tako govori Gospod Bog: › Kakor jaz živim, zagotovo bodo tisti, ki so v opustošenostih, padli pod mečem in kdor je na odprtem polju, ga bom izročil živalim, da bo požrt in tisti, ki so v utrdbah in votlinah, bodo umrli od kužne bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Kajti jaz bom deželo naredil najbolj zapuščeno in pomp njene moči bo prenehal; in gore Izraelove bodo zapuščene, da nihče ne bo šel čeznje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Potem bodo vedeli, da jaz sem Gospod, ko sem deželo naredil najbolj zapuščeno zaradi vseh njihovih ogabnosti, ki so jih zagrešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Tudi ti, človeški sin, otroci tvojega ljudstva še vedno govorijo zoper tebe pri zidovih in v vratih hiš in drug drugemu govorijo, vsak svojemu bratu, rekoč: ›Pridi, prosim te in poslušaj, kakšna je beseda, ki prihaja od Gospoda.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'In k tebi pridejo kakor prihajajo ljudje in sedijo pred teboj kakor moje ljudstvo in slišijo tvoje besede, toda nočejo jih izpolnjevati, kajti s svojimi usti so pokazali mnogo ljubezni, toda njihovo srce gre za njihovo pohlepnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'In glej, ti si jim kakor zelo očarljiva pesem nekoga, ki ima prijeten glas in lahko dobro igra na glasbilo, kajti slišijo tvoje besede, toda po njih se ne ravnajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'In ko se to zgodi (glej, to bo prišlo), potem bodo vedeli, da je bil med njimi prerok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '»Človeški sin prerokuj proti Izraelovim pastirjem, prerokuj in jim reci: ›Tako govori Gospod Bog pastirjem: ›Gorje bodi Izraelovim pastirjem, ki pasejo same sebe! Ali naj ne bi pastirji pasli tropov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Jeste tolščo in se oblačite z volno, koljete tiste, ki so rejeni, toda tropa ne pasete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Bolnih niste krepili, niti niste zdravili tega, kar je bilo bolno, niti niste povezali tega, kar je bilo zlomljeno, niti niste ponovno privedli tega, kar je bilo odpeljano, niti niste iskali tega, kar je bilo izgubljeno; temveč ste jim vladali s silo in s krutostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'In bili so razkropljeni, ker tam ni pastirja. In ko so bili razkropljeni, so postali hrana vsem živalim polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Moje ovce so tavale po vseh gorah in na vsakem visokem hribu; da, moj trop je bil razkropljen po vsem obličju zemlje in nihče ni preiskoval ali iskal za njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Zato, vi pastirji, poslušajte Gospodovo besedo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, '› Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo, ker je moj trop postal plen in je moj trop postal hrana vsaki divji živali polja, ker tam ni bilo pastirja niti moji pastirji niso iskali za mojim tropom, temveč so pastirji pasli same sebe in niso pasli mojega tropa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'zato, oh vi pastirji, poslušajte Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tako govori Gospod Bog: ›Glejte, jaz sem proti pastirjem; in svoj trop bom zahteval iz njihove roke in jim povzročil, da prenehajo pasti trop; niti pastirji ne bodo več pasli same sebe; kajti svoj trop bom osvobodil iz njihovih ust, da ne bodo več hrana zanje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Kajti tako govori Gospod Bog: ›Glejte, jaz, celó jaz, bom tako iskal svoje ovce kot jih poiskal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Kakor pastir išče svoj trop na dan, ko je med svojimi ovcami, ki so razkropljene; tako bom poiskal svoje ovce in osvobodil jih bom iz vseh krajev, kamor so bile razkropljene na oblačen in temačen dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'In jaz jih bom privedel izmed ljudstva in jih zbral izmed dežel in jih privedel k njihovi lastni deželi in jih pasel na Izraelovih gorah, poleg rek in po vseh naseljenih krajih dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Pasel jih bom na dobrem pašniku in na visokih Izraelovih gorah bo njihova staja. Tam bodo ležale v dobri staji in pasle se bodo na obilnem pašniku na Izraelovih gorah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Jaz bom pasel svoj trop in povzročil jim bom, da se uležejo,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, '›Iskal bom tisto, kar je bilo izgubljeno in ponovno privedel to, kar je bilo odvedeno stran in povezal bom to, kar je bilo zlomljeno in okrepil to, kar je bilo bolno. Toda uničil bom debelo in močno; jaz jih bom pasel s sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Glede vas pa, oh moj trop,‹ tako govori Gospod Bog: ›Glejte, jaz sodim med živino in živino, med ovni in kozli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ali se vam zdi majhna stvar, da ste pojedli dobro pašo, toda s svojimi stopali morate pomendrati preostanek svojih pašnikov? In da ste pili od globokih vodá, toda preostanek morate zapacati s svojimi stopali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'In glede mojega tropa, jedo to, kar ste poteptali s svojimi stopali, in pijejo to, kar ste zapacali s svojimi stopali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Zato jim tako govori Gospod Bog: ›Glejte, jaz, celó jaz, bom sodil med debelo živino in med suho živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Ker ste odrivali s stranjo in z ramo in vse bolne porivali s svojimi rogovi, dokler jih niste razkropili na tuje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'zatorej bom rešil svoj trop in nič več ne bodo plen; in sodil bom med živino in živino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'In nadnje bom postavil enega pastirja in ta jih bo pasel, celó svojega služabnika Davida; pasel jih bo in on bo njihov pastir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'In jaz, Gospod, bom njihov Bog in moj služabnik David princ med njimi;‹ jaz, Gospod, sem to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, '§ ›In z njimi bom sklenil zavezo miru in zlim živalim bom povzročil, da izginejo iz dežele; in tam bodo varno prebivali v divjini in spali v gozdovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'In jaz bom naredil njih in kraje naokoli svojega hriba blagoslov; in nalivu bom povzročil, da pride dol v svojem obdobju; tam bodo nalivi blagoslova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, '§ In drevo polja bo obrodilo svoj sad in zemlja bo obrodila svoj donos in oni bodo varni v svoji deželi in spoznali bodo, da jaz sem Gospod, ko zlomim vezi njihovega jarma in jih osvobodim iz roke tistih, ki so si od njih dali streči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'In nič več ne bodo plen poganom niti jih ne bodo požrle kopenske živali; temveč bodo varno prebivali in nihče jih ne bo prestrašil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'In jaz bom zanje vzdignil ugleden nasad in ne bodo več použiti z lakoto v deželi niti ne bodo več nosili sramote poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Tako bodo vedeli, da sem jaz, Gospod, njihov Bog, z njimi in da so oni, celó Izraelova hiša, moje ljudstvo,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, '›Vi pa, moj trop, trop mojega pašnika, ste ljudje in jaz sem vaš Bog,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '»Človeški sin, naravnaj svoj obraz proti gori Seír in prerokuj zoper njo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'ter ji reci: ›Tako govori Gospod Bog: ›Glej, oh gora Seír, jaz sem zoper tebe in zoper tebe bom iztegnil svojo roko in naredil te bom najbolj zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Tvoja mesta bom opustošil in zapuščena boš in vedela boš, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Ker si imela neprestano sovraštvo in si s silo meča prelila kri Izraelovih otrok v času njihove katastrofe, v času, ko je njihova krivičnost imela konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Zato kakor jaz živim,‹ govori Gospod Bog, ›te bom pripravil za kri in kri te bo zasledovala. Ker nisi sovražila krvi, te bo celo kri zasledovala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Tako bom goro Seír naredil najbolj zapuščeno in iz nje iztrebil tistega, ki gre skozi in tistega, ki se vrača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Njene gore bom napolnil z njenimi umorjenimi možmi. Na tvojih hribih in v tvojih dolinah in v vseh tvojih rekah bodo padli, ki so umorjeni z mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Naredil te bom za neprestana opustošenja in tvoja mesta se ne bodo vrnila. In spoznali boste, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Ker si rekla: ›Ta dva naroda in ti dve deželi bosta moji in mi bomo to vzeli v last; medtem ko je bil tam Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Zatorej, kakor jaz živim,‹ govori Gospod Bog, ›storil bom celo glede na tvojo jezo in glede na tvojo zavist, ki si jo uporabila iz svojega sovraštva zoper njih; in jaz se bom med njimi dal spoznati, ko sem te sodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Vedela boš, da jaz sem Gospod in da sem slišal vsa tvoja bogokletja, ki si jih govorila zoper Izraelove gore, rekoč: ›Zapuščene so, dane so nam, da jih použijemo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Tako ste se s svojimi usti bahali zoper mene in pomnožili svoje besede zoper mene. Jaz sem jih slišal. ‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tako govori Gospod Bog: ›Ko se vsa zemlja razveseljuje, bom jaz tebe naredil zapuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Kakor si se ti razveseljeval ob dediščini Izraelove hiše, ker je bila zapuščena, tako bom jaz storil tebi. Zapuščena boš, oh gora Seír in ves Edóm, celó ves. In spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '»Tudi ti, človeški sin, prerokuj Izraelovim goram in reci: ›Ve Izraelove gore, poslušajte Gospodovo besedo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, '›Tako govori Gospod Bog: ›Ker je sovražnik rekel proti vam: ›Aha, celo starodavni visoki kraji so naša posest;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'zato prerokuj in reci: ›Tako govori Gospod Bog: ›Ker so vas naredili opustošene in vas požrli na vsaki strani, da bi lahko bile posest preostanku poganov in ste vzete na ustnice jezičnikov in ste razvpitost ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Zato ve gore Izraelove, poslušajte besedo Gospoda Boga: ›Tako govori Gospod Bog goram in hribom, rekam in dolinam, pustim opustošenostim in mestom, ki so zapuščena, ki so postala plen in posmeh preostanku poganov, ki so naokoli;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'zato tako govori Gospod Bog: ›Zagotovo sem govoril v ognju svoje ljubosumnosti zoper preostanek poganov in zoper ves Edóm, ki so mojo deželo določili v svojo posest z radostjo vsega svojega srca, s krutimi umi, da bi ga vrgli ven za plen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Zato prerokuj glede dežele Izrael in reci goram in gričem, rekam in dolinam: ›Tako govori Gospod Bog: ›Glejte, govoril sem v svoji ljubosumnosti in v svoji razjarjenosti, ker ste nosili sramoto poganov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Zato tako govori Gospod Bog: ›Povzdignil sem svojo roko: ›Zagotovo bodo pogani, ki so okoli vas, nosili svojo sramoto.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Toda ve, oh Izraelove gore, boste pognale svoje mladike in obrodile svoj sad mojemu ljudstvu Izraelu; kajti pri roki so, da pridejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Kajti, glejte, jaz sem za vas in obrnil se bom k vam in ve boste preorane in posejane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'in jaz bom pomnožil ljudi na vas, vso Izraelovo hišo, celó vse izmed njih, in mesta bodo naseljena in opustošenosti bodo pozidane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'in jaz bom na vas pomnožil človeka in žival; in narasli bodo in prinašali sad. In jaz vas bom naselil po vaših prejšnjih posestvih in vam bom storil boljše kakor ob vaših začetkih: in spoznale boste, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Da, ljudem bom povzročil, da hodijo po vas, celó moje ljudstvo Izrael; in vzeli te bodo v last in boš njihova dediščina in odslej jih ne boš več oropala ljudi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tako govori Gospod Bog: ›Ker ti pravijo: ›Ti dežela, požiraš ljudi in si oropala svoje narode;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'zatorej ne boš več požirala ljudi niti ne boš več oropala svojih narodov,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, '›Niti ne bom več povzročal ljudem, da v tebi slišijo sramoto poganov niti ne boš več nosila graje ljudstev niti ne boš več povzročala padca svojim narodom,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '»Človeški sin, ko je Izraelova hiša prebivala v svoji lastni deželi, so jo omadeževali s svojo lastno potjo in svojimi lastnimi početji. Njihova pot je bila pred menoj kakor nečistost odstranjene ženske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Zatorej sem nanje izlil svojo razjarjenost zaradi krvi, ki so jo prelili nad deželo in zaradi njihovih malikov, s katerimi so jo oskrunili');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'in razgnal sem jih med pogane in razpršeni so bili med dežele; glede na njihovo pot in glede na njihova dejanja sem jih sodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'In ko so vstopili k poganom, kamorkoli so odšli, so oskrunili moje sveto ime, ko so jim rekli: ›Ti so Gospodovo ljudstvo, pa so odšli ven iz njegove dežele.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Toda imel sem usmiljenje zaradi svojega svetega imena, ki ga je Izraelova hiša oskrunila med pogani, kamor so odšli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: › Tega ne delam zaradi tebe, oh hiša Izraelova, temveč zaradi svojega svetega imena, ki ste ga oskrunili med pogani, kamor ste odšli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'In jaz bom svoje veliko ime, ki je bilo oskrunjeno med pogani, ki ste ga oskrunili v njihovi sredi, posvetil; in pogani bodo spoznali, da jaz sem Gospod ‹, govori Gospod Bog, ›ko bom v vas posvečen, pred njihovimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Kajti jaz vas bom vzel izmed poganov in vas zbral iz vseh dežel in vas privedel v vašo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Potem bom na vas poškropil čisto vodo in boste čisti. Pred vso vašo umazanostjo in pred vsemi vašimi maliki vas bom očistil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Prav tako vam bom dal novo srce in novega duha bom položil znotraj vas in iz vašega mesa bom odvzel kamnito srce in vam dal meseno srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Svojega duha bom položil znotraj vas in povzročim vam, da se boste ravnali po mojih zakonih in boste ohranjali moje sodbe in jih izvajali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'In prebivali boste v deželi, ki sem jo dal vašim očetom; in vi boste moje ljudstvo in jaz bom vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Prav tako vas bom rešil pred vašo nečistostjo, in jaz bom poklical žito in ga povečal, na vas pa ne bom položil nobene lakote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'In pomnožil bom sad od drevesa in donos od polja, da ne boste več prejeli graje zaradi lakote med pogani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Potem se boste spomnili svojih lastnih zlih poti in svojih početij, ki niso bila dobra in gnusili se boste v svojih lastnih očeh zaradi svojih krivičnosti in zaradi svojih ogabnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Tega ne storim zaradi vas,‹ govori Gospod Bog, ›to naj vam bo znano: bodite osramočeni in zbegani zaradi svojih lastnih poti, oh hiša Izraelova.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tako govori Gospod Bog: ›Na dan, ko vas bom očistil pred vsemi vašimi krivičnostmi, vam bom prav tako povzročil, da prebivate v mestih in opustošenosti bodo pozidane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'In zapuščena dežela bo preorana, kakor ta leži zapuščena pred očmi vseh, ki so hodili mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'In rekli bodo: ›Ta dežela, ki je bila zapuščena, je postala podobna edenskemu vrtu; in opustošena in zapuščena in porušena mesta so postala ograjena in naseljena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Potem bodo pogani, ki so ostali okoli vas, vedeli, da sem jaz, Gospod, zgradil porušene kraje in zasadil to, kar je bilo zapuščeno. Jaz, Gospod, sem to govoril in jaz bom to storil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tako govori Gospod Bog: ›Vendar bom zaradi tega povpraševan od Izraelove hiše, da to storim zanje; povečal jih bom z možmi kakor trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Kakor svet trop, kakor trop [prestolnice] Jeruzalem ob njenih slovesnih praznikih, tako bodo opustošena mesta napolnjena s tropi ljudi, in spoznali bodo, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Gospodova roka je bila nad menoj in me odvedla ven v Gospodovem duhu in me postavila dol v sredo doline, ki je bila polna kosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'in dal mi je, da sem šel okoli njih. In glej, tam jih je bilo zelo veliko v odprti dolini. In glej, bile so zelo suhe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Rekel mi je: »Človeški sin, ali lahko te kosti živijo?« Odgovoril sem: »Oh Gospod Bog, ti veš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Ponovno mi je rekel: »Prerokuj nad temi kostmi in jim reci: ›Oh ve, suhe kosti, poslušajte Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tako govori Gospod Bog tem kostem: ›Glejte, povzročil bom, da v vas vstopi dih in boste živele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Na vas bom položil kite in privedel meso na vas in vas pokril s kožo in položil dih v vas in ve boste živele in spoznale boste, da jaz sem Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Tako sem prerokoval, kakor mi je bilo zapovedano. Ko sem prerokoval, je bil tam hrup in glej tresenje in kosti so prišle skupaj, kost k svoji kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'In ko sem gledal, glej, kite in meso so prišli nanje in zgoraj jih je pokrila koža, toda v njih ni bilo diha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Potem mi je rekel: »Prerokuj vetru, prerokuj, človeški sin in reci vetru: ›Tako govori Gospod Bog: ›Pridi iz štirih vetrov, oh dih in dihni na te umorjene, da bodo lahko živeli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Tako sem prerokoval, kakor mi je zapovedal in dih je prišel vanje in oživeli so in vstali na svoja stopala, silno velika vojska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, '§ Potem mi je rekel: »Človeški sin, te kosti so celotna Izraelova hiša. Glej, govorijo: ›Naše kosti so suhe in naše upanje je izgubljeno. Odrezani smo iz svoje dežele.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Zato prerokuj in jim reci: ›Tako govori Gospod Bog: ›Glej, oh moje ljudstvo, odprl bom vaše grobove in povzročim vam, da pridete iz svojih grobov in vas privedem v Izraelovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'In vi boste spoznali, da jaz sem Gospod, ko odprem vaše grobove, oh moje ljudstvo in vas privedel gor, ven iz vaših grobov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Svojega duha bom položil v vas in boste živeli in namestil vas bom v vašo lastno deželo. Potem boste vedeli, da sem jaz, Gospod, to govoril in to izvêdel, govori Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Beseda Gospodova je ponovno prišla k meni, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '»Poleg tega si ti, človeški sin, vzemi eno palico in nanjo napiši: ›Za Juda in za Izraelove otroke, njegove družabnike.‹ Potem vzemi drugo palico in nanjo napiši: ›Za Jožefa, Efrájimovo palico in za vso Izraelovo hišo njegovih družabnikov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Pridruži ju eno k drugi, v eno palico; in postali bosta eno v tvoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'In ko ti bodo otroci tvojega ljudstva govorili, rekoč: ›Ali nam ne boš pokazal, kaj misliš s tem?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'jim reci: ›Tako govori Gospod Bog: ›Glejte, vzel bom Jožefovo palico, ki je v Efrájimovi roki in Izraelove rodove, njegove rojake in jih položil z njim, celó z Judovo palico in jih naredil eno palico in oni bodo eno v moji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'In palici, na kateri pišeš, bosta v tvoji roki pred njihovimi očmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'In reci jim: ›Tako govori Gospod Bog: ›Glej vzel bom Izraelove otroke izmed poganov, kamor so odšli in zbral jih bom na vsaki strani in jih privedel v njihovo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'In naredil jih bom en narod v deželi, na Izraelovih gorah; in en kralj bo kralj nad njimi vsemi, in ne bodo več dva naroda niti sploh ne bodo več razdeljeni v dve kraljestvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Niti se ne bodo več omadeževali s svojimi maliki niti s svojimi ostudnimi stvarmi niti s katerimikoli izmed njihovih prestopkov, temveč jih bom rešil iz vseh njihovih bivališč, v katerih so grešili in jih bom očistil. Tako bodo moje ljudstvo in jaz bom njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Moj služabnik David bo kralj nad njimi; in vsi bodo imeli enega pastirja. Prav tako se bodo ravnali po mojih sodbah in obeleževali moje zakone in jih izvajali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'In prebivali bodo v deželi, ki sem jo dal Jakobu, svojemu služabniku, v kateri so prebivali vaši očetje; in prebivali bodo tam, celó oni, njihovi otroci in otroci njihovih otrok na veke, in moj služabnik David bo njihov princ na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Poleg tega bom z njimi sklenil zavezo miru. To bo večna zaveza z njimi in jaz jih bom namestil in jih pomnožil in svoje svetišče bom postavil v njihovi sredi na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Prav tako bo z njimi moje šotorsko svetišče. Da, jaz bom njihov Bog in oni bodo moje ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'In pogani bodo spoznali, da jaz, Gospod, posvečujem Izraela, ko bo moje svetišče v njihovi sredi na vékomaj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'In k meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '»Človeški sin, naravnaj svoj obraz zoper Gog, deželo Magóg, glavnega princa Mešeha in Tubála in prerokuj zoper njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Gog, glavni princ Mešeha in Tubála.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Obrnil te bom nazaj in vtaknil kavlje v tvoje čeljusti in te privedel naprej in vso tvojo vojsko, konje in konjenike, vse izmed njih oblečene z vsemi vrstami bojne opreme, celo veliko družbo z majhnimi ščiti in ščiti; vsi izmed njih rokujejo z meči:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perzija, Etiopija in Libija z njimi; vsi izmed njih s ščitom in čelado:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer in vse njegove čete; hiša Togarmá od severnih četrti in vse njegove čete in mnogo ljudstva s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Bodi pripravljen in pripravi zase, ti in vsa tvoja skupina, ki so zbrani k tebi in ti jim bodi stražar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Po mnogih dneh boš obiskan. V zadnjih letih boš prišel v deželo, ki je privedena nazaj pred mečem in je zbrana izmed številnih ljudstev zoper Izraelove gore, ki so bile vedno opustošene, toda ta je privedena izmed narodov in vsi izmed njih bodo varno prebivali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Povzpel se boš in prišel kakor vihar, podoben boš oblaku, da pokriješ deželo, ti in vse tvoje čete in mnogo ljudstev s teboj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tako govori Gospod Bog: ›Zgodilo se bo tudi to, da bodo ob istem času v tvoj um prišle stvari, ti pa boš mislil zlo misel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Rekel boš: ›Šel bom gor k deželi neobzidanih vasi; šel bom k tem, ki so v miru, ki varno prebivajo, vsi izmed njih prebivajo zunaj zidov in nimajo niti zapahov niti velikih vrat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'da vzamem ukradeno blago in da vzamem plen; da svojo roko obrnem nad zapuščene kraje, ki so sedaj naseljeni in nad ljudstva, ki so zbrana izmed narodov, ki so pridobili živino in dobrine, ki prebivajo v sredi dežele.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Saba in Dedán in trgovci iz Taršíša, z vsemi njihovimi mladimi levi, ti bodo govorili: ›Ali si prišel, da vzameš plen? Ali si zbral svojo družbo, da vzameš plen? Da odneseš srebro in zlato, da odneseš govedo in dobrine, da vzameš velik plen?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Zatorej, človeški sin, prerokuj in reci Gogu: ›Tako govori Gospod Bog: ›Na tisti dan, ko bo moje ljudstvo Izrael varno prebivalo, mar tega ne boš vedel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'In prišel boš iz svojega kraja, iz severnih delov, ti in številna ljudstva s teboj, vsi izmed njih bodo jahali na konjih, velika družba in mogočna vojska');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'in prišel boš gor zoper moje ljudstvo Izraela kakor oblak, da pokriješ deželo; to bo v zadnjih dneh in privedel te bom zoper mojo deželo, da me bodo pogani lahko spoznali, ko bom posvečen v tebi, oh Gog, pred njihovimi očmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tako govori Gospod Bog: › Ali si ti tisti, o katerem sem govoril v starih časih po svojih služabnikih, Izraelovih prerokih, ki so prerokovali v tistih dneh mnoga leta, da te bom privedel zoper njih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'In zgodilo se bo ob istem času, ko bo proti Izraelovi deželi prišel Gog,‹ govori Gospod Bog, › da bo na moj obraz prišla moja razjarjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Kajti v svojem ljubosumju in v ognju svojega besa sem govoril: ›Zagotovo bo na ta dan v Izraelovi deželi veliko tresenje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'tako da bodo ribe morja in perjad neba in poljske živali in vse plazeče stvari, ki se plazijo po zemlji in vsi ljudje, ki so na obličju zemlje, trepetali ob moji prisotnosti in gore bodo zrušene in strmi kraji bodo padli in vsak zid bo padel na tla.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'In proti njemu bom prek vseh svojih gora poklical meč,‹ govori Gospod Bog. ›Vsakogar meč bo zoper svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'In jaz bom navajal dokaze zoper njega s kužno boleznijo in s krvjo, in deževal bom nanj in na njegove čete in na mnoga ljudstva, ki so z njim, preplavljajoč dež in velika zrna toče, ogenj in žveplo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Tako se bom poveličal in se posvetil; in znan bom v očeh mnogih narodov in spoznali bodo, da jaz sem Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '›Zato, ti, človeški sin, prerokuj zoper Gog in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Gog, glavni princ Mešeha in Tubála,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'in obrnil te bom nazaj in pustil samo šesti del tebe in ti povzročil, da prideš gor iz severnih krajev in privedel te bom na Izraelove gore');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'in izbil ti bom lok iz tvoje leve roke in tvojim puščicam povzročil, da izpadejo iz tvoje desnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Padel boš na Izraelovih gorah, ti in vse tvoje čete in ljudstvo, ki je s teboj. Izročil te bom pticam roparicam vsake vrste in k živalim polja, da boš požrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Padel boš na odprtem polju, kajti jaz sem to govoril,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, '›In poslal bom ogenj na Magóg in med tiste, ki brezskrbno prebivajo na otokih. In spoznali bodo, da jaz sem Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Tako bom svoje sveto ime naredil znano v sredi svojega ljudstva Izraela; in ne bom jim več dopustil, da oskrunijo moje sveto ime. In pogani bodo spoznali, da jaz sem Gospod, Sveti v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Glej, prišel je in narejeno je,‹ govori Gospod Bog; ›to je dan, o katerem sem govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Tisti, ki prebivajo v Izraelovih mestih, bodo šli naprej in bodo zakurili ogenj, sežgali orožje, tako ščite in majhne ščite, loke, puščice, krepelca ter sulice in sedem let jih bodo sežigali z ognjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'tako da ne bodo vzeli nobenega lesa iz polja niti posekali nobenega iz gozdov; kajti orožje bodo sežigali z ognjem in plenili bodo tiste, ki so jih plenili in ropali bodo tiste, ki so jih ropali,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '›In na tisti dan se bo zgodilo, da bom Gogu dal kraj za grobove v Izraelu, dolino popotnikov na vzhodu morja, in ta bo zamašila nosove popotnikom, in tam bodo sežgali Goga in vso njegovo množico in imenovali jo bodo Dolina Gogove množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'In sedem mesecev jih bo Izraelova hiša pokopavala, da bodo lahko očistili deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Da, vse ljudstvo dežele jih bo pokopavalo; in to jim bo ugled na dan, ko bom proslavljen,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '§ ›In oddvojili bodo može z nenehno zaposlitvijo, ki bodo hodili skozi deželo, da bi s potniki pokopavali tiste, ki ostajajo na obličju zemlje, da jo očistijo; po koncu sedmih mesecev bodo iskali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'In potniki, ki gredo skozi deželo, ko kdorkoli zagleda človeško kost, potem bo ob njej postavil znamenje, dokler je grobarji ne pokopljejo v dolini Gogove množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'In ime mesta bo prav tako Hamóna. Tako bodo očistili deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'In ti, človeški sin,‹ tako govori Gospod Bog: ›Govori vsaki operjeni perjadi in vsaki živali polja: ›Zberite se in pridite; zberite se na vsaki strani k moji klavni daritvi, ki jo darujem za vas, torej veliki klavni daritvi na Izraelovih gorah, da boste lahko jedle meso in pile kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Jedle boste meso mogočnih in pile kri zemeljskih princev, ovnov, jagnjet in koz, bikcev, vsi izmed njih bašánski pitanci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'In jedle boste tolščo, dokler ne boste nasičene in pile kri, dokler ne boste pijane od moje klavne daritve, ki sem jo žrtvoval za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Tako boste nasičene pri moji mizi s konji in bojnimi vozovi in z mogočnimi možmi in z vsemi bojevniki,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '›In svojo slavo bom postavil med pogane in vsi pogani bodo videli mojo sodbo, ki sem jo izvršil in mojo roko, ki sem jo položil nanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Tako bo Izraelova hiša spoznala, da jaz sem Gospod, njihov Bog, od tega dne naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'In pogani bodo vedeli, da je hiša Izraelova odšla v ujetništvo zaradi svojih krivičnosti, ker so kršili zoper mene, zato sem svoj obraz skril pred njimi in jih izročil v roko njihovih sovražnikov; tako so vsi padli pod mečem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Glede na njihovo nečistost in glede na njihove prestopke sem jim storil in svoj obraz sem skril pred njimi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Zato tako govori Gospod Bog: ›Sedaj bom ponovno privedel Jakobovo ujetništvo in usmiljenje bom imel nad celotno Izraelovo hišo in ljubosumen bom zaradi svojega svetega imena;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'po tem, ko so nosili svojo sramoto in vse svoje prestopke, s katerimi so kršili zoper mene, ko so varno prebivali v svoji deželi in jih nihče ni strašil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Ko sem jih ponovno privedel izmed ljudstva in jih zbral iz dežel njihovih sovražnikov in sem posvečen v njih pred očmi mnogih narodov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'potem bodo spoznali, da jaz sem Gospod, njihov Bog, ki jim je storil, da so bili odvedeni v ujetništvo med pogane, toda zbral sem jih k njihovi lastni deželi in nikogar izmed njih nisem več pustil tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Niti svojega obraza ne bom več skrival pred njimi, kajti svojega duha sem izlil na Izraelovo hišo,‹ govori Gospod Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'V petindvajsetem letu našega ujetništva, v začetku leta, na deseti dan meseca, v štirinajstem letu, potem ko je bilo mesto udarjeno, na prav isti dan, je bila nad menoj Gospodova roka in me privedla tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'V Božjih videnjih me je privedel v deželo Izrael in me postavil na zelo visoko goro, pri kateri je bil kakor okvir mesta na jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'In privedel me je tja in glej, tam je bil mož, katerega videz je bil podoben videzu brona, z laneno vrvico v svoji roki in merilno trstiko; in stal je v velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'In mož mi je rekel: »Človeški sin, glej s svojimi očmi in poslušaj s svojimi ušesi in svoje srce naravnaj na vse to, kar ti bom pokazal; kajti z namenom, da ti jih lahko pokažem, si bil priveden sèm. Vse to, kar vidiš, oznani Izraelovi hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Glej obzidje zunaj, naokoli hiše in v človeški roki merilna trstika, šest komolcev dolga, po komolec in širino roke, tako je izmeril širino zgradbe, ena trstika; in višino, ena trstika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Potem je prišel k velikim vratom, ki gledajo proti vzhodu in odšel gor po njegovih stopnicah in izmeril prag velikih vrat, ki je bil širok eno trstiko; in drugi prag velikih vrat, ki je bil širok eno trstiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'In vsaka majhna soba je bila eno trstiko dolga in eno trstiko široka; in med majhnimi sobami je bilo pet komolcev; in prag velikih vrat, znotraj, pri preddverju velikih vrat, je bil eno trstiko [širok].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Izmeril je tudi preddverje znotraj velikih vrat, ena trstika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Potem je izmeril preddverje velikih vrat, osem komolcev; in njegovi podboji, dva komolca; in preddverje velikih vrat je bilo znotraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'In majhne sobe velikih vrat proti vzhodu so bile tri na tej strani in tri na oni strani; te tri so bile ene mere; in podboji so imeli eno mero na tej strani in na oni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'In izmeril je širino vhoda velikih vrat, deset komolcev; in dolžino velikih vrat, trinajst komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Tudi prostora pred majhnimi sobami je bilo en komolec na tej strani in en komolec prostora je bilo na oni strani; in majhne sobe so bile šest komolcev na tej strani in šest komolcev na oni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Potem je izmeril velika vrata od strehe ene majhne sobe do strehe druge: širina je bila petindvajset komolcev, vrata nasproti vratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Naredil je tudi podboje šestdesetih komolcev, celo podboj dvora naokoli velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'In od pročelja velikih vrat vhoda do pročelja preddverja notranjih velikih vrat je bilo petdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'In tam so bila ozka okna k majhnim sobam in k njihovim podbojem znotraj, naokoli velikih vrat in podobno k obokom, in okna so bila naokoli navznoter sobe, in na vsakem podboju so bila palmova drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Potem me je privedel na zunanji dvor in glej, tam so bile sobe in tlak, narejen za dvor naokoli. Trideset sob je bilo na tlaku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'In tlak, ki je bil pri strani velikih vrat, nasproti dolžine velikih vrat, je bil nižji tlak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Potem je izmeril širino od sprednjega dela spodnjih velikih vrat do sprednjega dela notranjega dvora zunaj; sto komolcev proti vzhodu in proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'In velika vrata zunanjega dvora, ki so gledala proti severu, izmeril je njihovo dolžino in njihovo širino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'In njihove majhne sobe so bile tri na tej strani in tri na oni strani; in njihovi podboji in njihovi oboki so bili po meri prvih vrat. Njihova dolžina je bila petdeset komolcev in širina petindvajset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'In njihova okna in njihovi oboki in njihova palmova drevesa so bila po meri velikih vrat, ki gledajo proti vzhodu; in k tem so se vzpeli po sedmih stopnicah; in njihovi oboki so bili pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'In velika vrata notranjega dvora so bila nasproti velikih vrat proti severu in proti vzhodu; in od velikih vrat do velikih vrat je izmeril sto komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Po tem me je privedel proti jugu in glej, velika vrata proti jugu. Izmeril je njihove podboje in njihove oboke, glede na te mere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'In tam so bila okna in njihovi oboki naokoli, podobni tistim oknom. Dolžina je bila petdeset komolcev in širina petindvajset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'In tam je bilo sedem stopnic, da se gre gor do njih in njihovi oboki so bili pred njimi. Ta so imela palmovi drevesi, eno na tej strani in drugo na oni strani, na njihovih podbojih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'In na notranjem dvoru, proti jugu, so bila velika vrata, in od velikih vrat do velikih vrat je proti jugu izmeril sto komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'In privedel me je na notranji dvor pri južnih velikih vratih: in južna velika vrata je izmeril glede na te mere;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'in njihove majhne sobe in njihovi podboji in njihovi oboki, glede na te mere: in tam so bila okna v njej in njihovi oboki naokoli: in ta so bila petdeset komolcev dolga in petindvajset komolcev široka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Oboki naokoli so bili petindvajset komolcev dolgi in pet komolcev široki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Njihovi oboki so bili proti skrajnemu dvoru; palmova drevesa so bila na njihovih podbojih. Gor do njih je vodilo osem stopnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Privedel me je na notranji dvor proti vzhodu in izmeril velika vrata glede na te mere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Njihove majhne sobe, njihovi podboji in njihovi oboki so bili glede na te mere. Tam so bila okna v njihovih obokih naokoli. To je bilo petdeset komolcev dolgo in petindvajset komolcev široko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Njihovi oboki so bili proti zunanjemu dvoru; in palmova drevesa so bila na njihovih podbojih, na tej strani in na oni strani in gor do njih je vodilo osem stopnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Privedel me je k severnim velikim vratom in jih izmeril glede na te mere;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'njihove majhne sobe, njihove podboje in njihove oboke in okna k tem naokoli; dolžina je bila petdeset komolcev in širina petindvajset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Njihovi podboji so bili proti skrajnemu dvoru; in palmova drevesa so bila na njihovih podbojih, na tej strani in na oni strani in gor do njih je vodilo osem stopnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Sobe in njihovi vhodi so bili ob podbojih velikih vrat, kjer so prali žgalno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'V preddverju velikih vrat sta bili dve mizi na tej strani in dve mizi na oni strani, da na njih zakoljejo žgalno daritev in daritev za greh in daritev za prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Zunaj ob strani, kakor gre kdo gor k vhodu severnih velikih vrat, sta bili dve mizi; in na drugi strani, ki je bila pri preddverju velikih vrat, sta bili dve mizi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Štiri mize so bile na tej strani in štiri mize na oni strani, pri straneh velikih vrat; osem miz, na katerih so klali svoje daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Štiri mize so bile iz klesanega kamna za žgalno daritev, komolec in pol dolge in komolec in pol široke in en komolec visoke, na katere so prav tako položili orodje, s katerim so zaklali žgalno daritev in klavno daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Znotraj so bili kavlji, dlan široki, pritrjeni naokoli in na mizah je bilo meso daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Zunaj notranjih velikih vrat so bile sobe pevcev notranjega dvora, ki je bil ob strani severnih velikih vrat in njihova pročelja so bila proti jugu. Ena je bila ob strani vzhodnih velikih vrat in imela pročelje proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'In rekel mi je: »Ta soba, katere pročelje je proti jugu, je za duhovnike, čuvaje oskrbe hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Soba, katere pročelje je proti severu, je za duhovnike, čuvaje oskrbe oltarja: to so Cadókovi sinovi med Lévijevimi sinovi, ki so prišli blizu h Gospodu, da mu služijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Tako je izmeril dvor, sto komolcev dolg in sto komolcev širok, štirioglat; in oltar, ki je bil pred hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Privedel me je k preddverju hiše in izmeril vsak podboj preddverja, pet komolcev na tej strani in pet komolcev na oni strani in širina velikih vrat je bila tri komolce na tej strani in tri komolce na oni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, '§ Dolžina preddverja je bila dvajset komolcev in širina enajst komolcev; in privedel me je poleg stopnic, po katerih so se dvignili do njega. Tam so bili stebri ob podbojih, eden na tej strani, drugi pa na oni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Potem me je privedel k templju in izmeril podboje, šest komolcev široke na eni strani in šest komolcev široke na drugi strani, kar je bila širina šotorskega svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Širina vrat je bila deset komolcev; in strani vrat na eni strani je bilo pet komolcev in pet komolcev na drugi strani: in izmeril je njihovo dolžino, štirideset komolcev; in širino: dvajset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Potem je odšel noter in izmeril podboj vrat: dva komolca; in vrata: šest komolcev; in širino vrat: sedem komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Tako je izmeril njegovo dolžino: dvajset komolcev; in širino: dvajset komolcev, pred templjem. Rekel mi je: »To je najsvetejši prostor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Potem je izmeril zid hiše: šest komolcev; in širino vsake stranske sobe: štiri komolce naokoli hiše na vsaki strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Stranske sobe so bile tri, ena nad drugo in trideset v vrsti; in vstopale so v zid, ki je bil iz hiše za stranske sobe naokoli, da bi lahko imele oporo, toda te se niso držale v zidu hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'In tam je bila razširitev in okljuke naokrog strmo navzgor k stranskim sobam, kajti okljuke naokrog hiše so šle strmo navzgor naokrog hiše. Zato je bila širina hiše strmo navzgor in se tako povečevala od najnižjih sob do najvišjih ob sredini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Prav tako sem videl višino hiše naokrog. Temelji stranskih sob so bili cela trstika iz šestih velikih komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Debelina zidu, ki je bil znotraj, za stransko sobo, je bila pet komolcev. In to, kar je preostalo, je bil prostor stranskih sob, ki so bile znotraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Med sobami je bila širina dvajsetih komolcev naokoli hiše na vsaki strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Vrata stranskih sob so bila proti kraju, ki je preostal, ena vrata proti severu in druga vrata proti jugu. Širina prostora, ki je preostal, je bila pet komolcev naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Torej zgradba, ki je bila pred ločenim krajem na koncu proti zahodu, je bila sedemdeset komolcev široka; in zid zgradbe je bil naokoli debel pet komolcev in njegova dolžina devetdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Tako je izmeril hišo, sto komolcev dolga; in ločen kraj in zgradbo, z njenimi zidovi, sto komolcev dolgo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'tudi širino pročelja hiše in ločenega kraja proti vzhodu: sto komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Izmeril je dolžino zgradbe nasproti ločenemu kraju, ki je bil za njo in njene galerije na eni strani in na drugi strani: sto komolcev, z notranjim templjem in preddverji dvora;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'podboje vrat in ozka okna in galerije naokoli na svojih treh nadstropjih, nasproti vratom, naokrog obloženi z lesom in od tal gor do oken in okna so bila pokrita;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'k tem nad vrati, celo do notranje hiše in zunaj in pri vsem zidu naokoli, znotraj in zunaj, po meri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'To je bilo narejeno s kerubi in palmovimi drevesi, tako da je bilo palmovo drevo med kerubom in kerubom; in vsak kerub je imel dva obraza;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'tako da je bilo obličje človeka proti palmovemu drevesu na tej strani in obličje mladega leva proti palmovemu drevesu na oni strani. To je bilo narejeno po vsej hiši naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Od tal do nad vrati so bili narejeni kerubi in palmova drevesa in na zidu templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Podboji templja so bili pravokotni in pročelje svetišča; videz enega kakor videz drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Oltar iz lesa je bil tri komolce visok in njegova dolžina dva komolca; in njegovi vogali in njegova dolžina in njegove stene so bile iz lesa. Rekel mi je: »To je miza, ki je pred Gospodom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Tempelj in svetišče sta imela dvoje vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Vsaka vrata so imela dvoje kril, dvoje obračajočih se kril; dve krili za ena vrata in dve krili za druga vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Na njih so bili narejeni, na vratih templja, kerubi in palmova drevesa, podobna, kakor so bila narejena na stenah; in tam so bile debele deske na pročelju zunaj preddverja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'In bila so ozka okna in palmova drevesa na eni strani in na drugi strani, na straneh preddverja in na stranskih sobah hiše na debelih deskah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Potem me je odvedel naprej na skrajni dvor, ob poti proti severu in me privedel v sobo, ki je bila nasproti ločenemu kraju in ki je bila pred zgradbo proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Pred dolžino stotih komolcev so bila severna vrata in širina je bila petdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Nasproti dvajsetim komolcem, ki so bili za notranji dvor in nasproti tlaku, ki je bil za skrajni dvor, je bila galerija nasproti galeriji, v treh nadstropjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Pred sobami je bil hodnik desetih komolcev širine znotraj, pot enega komolca; in njihova vrata proti severu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Torej zgornje sobe so bile krajše, kajti galerije so bile višje kakor te, kakor spodnje in kakor tiste, ki so bile v sredini zgradbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Kajti bile so v treh nadstropjih, toda niso imele stebrov kakor stebri dvora, zato je bila zgradba ožja, bolj kakor nižje in srednje od tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Zid, ki je bil zunaj, nasproti sobam, proti skrajnemu dvoru, na sprednjem delu sob, njegova dolžina je bila petdeset komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Kajti dolžina sob, ki so bile na skrajnem dvoru, je bila petdeset komolcev, in glej, pred templjem je bilo sto komolcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Izpod teh sob je bil vhod na vzhodni strani, kakor gre nekdo vanje od skrajnega dvora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Sobe so bile v debelini zidu dvora proti vzhodu, nasproti ločenemu kraju in nasproti zgradbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Pot pred njimi je bila podobna videzu sob, ki so bile proti severu, tako dolga kakor one in tako široka kakor one, in vsi njihovi izhodi so bili tako glede na njihove oblike kakor glede na njihova vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Glede na vrata sob, ki so bila proti jugu, so bila vrata na začetku poti, celó na poti neposredno pred zidom proti vzhodu, kakor nekdo vstopa vanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Potem mi je rekel: »Severne sobe in južne sobe, ki so pred ločenim krajem, te so svete sobe, kjer bodo duhovniki, ki pristopajo h Gospodu, jedli najsvetejše stvari. Tam bodo polagali najsvetejše stvari in jedilno daritev in daritev za greh in daritev za prestopke; kajti kraj je svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Ko duhovniki vstopijo vanj, potem ne bodo šli ven iz svetega kraja na skrajni dvor, temveč bodo tam odložili oblačila, v katerih so služili, kajti ta so sveta in nadeli si bodo druga oblačila in pristopili bodo k tistim stvarem, ki so za ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Torej ko je končal merjenje notranje hiše, me je privedel naprej proti velikim vratom, katerih pročelje je proti vzhodu in ga izmeril naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Izmeril je vzhodno stran z merilno trstiko, petsto trstik, z merilno trstiko naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Izmeril je severno stran, petsto trstik, z merilno trstiko naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Izmeril je južno stran, petsto trstik, z merilno trstiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Obrnil se je k zahodni strani in izmeril petsto trstik z merilno trstiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Izmeril jo je ob štirih straneh. Naokrog je imela obzidje, petsto trstik dolgo in petsto široko, da bi naredil oddvojitev med svetiščem in oskrunjenim krajem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Zatem me je privedel k velikim vratom, celó velikim vratom, ki gledajo proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'In glej, slava Izraelovega Boga je prišla po poti od vzhoda, in njegov glas je bil podoben hrupu mnogih vodá, in zemlja je zasijala z njegovo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'In to je bilo glede na videz videnja, ki sem ga videl, celó glede na videnje, ki sem ga videl, ko sem prišel, da uničim mesto; in videnja so bila podobna videnju, ki sem ga videl pri reki Kebár; in padel sem na svoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Gospodova slava je prišla v hišo po poti velikih vrat, katerih pročelje je proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Tako me je duh vzel gor in me privedel na notranji dvor; in, glej, Gospodova slava je napolnila hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Slišal sem ga, kako mi govori iz hiše; in poleg mene je stal mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Rekel mi je: »Človeški sin, prostor mojega prestola in kraj za podplate mojih stopal, kjer bom na veke prebival v sredi Izraelovih otrok in mojega svetega imena Izraelova hiša ne bo več omadeževala, niti oni, niti njihovi kralji s svojim vlačugarstvom, niti s trupli svojih kraljev na svojih visokih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'V njihovi postavitvi njihovega praga ob mojih pragovih in njihovega podboja ob mojih podbojih in zidom med menoj in njimi, so celo omadeževali moje sveto ime s svojimi ogabnostmi, ki so jih zagrešili. Zatorej sem jih použil v svoji jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Torej naj odstranijo svoje vlačugarstvo in trupla svojih kraljev daleč od mene in jaz bom prebival v njihovi sredi na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ti, človeški sin, pokaži Izraelovi hiši, da jih bo lahko sram njihovih krivičnosti in naj izmerijo vzorec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Če se bodo sramovali vsega, kar so storili, jim pokaži obliko hiše, njen slog, njene izhode, njene vhode, vse njene oblike, vse njene odredbe, vse njene oblike in vse njene postave, in zapiši jih v njihovem pogledu, da se bodo lahko držali njene celotne oblike in vseh njenih odredb in jih izpolnjevali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'To je postava hiše: ›Na vrhu gore bo njena celotna meja naokrog najsvetejšega.‹ Glej, to je postava hiše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'In to so mere oltarja po komolcih: ›Komolec je komolec in širina roke; celo dno bo komolec in širina komolca in njena meja ob njenem robu naokrog bo pedenj in to bo višji kraj oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Od dna na tleh, celó do spodnjega podzidka, bo dva komolca in širina en komolec; in od manjšega podzidka celó do večjega podzidka, bo štiri komolce in širina en komolec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Tako bo oltar štiri komolce; in od oltarja in navzgor bodo štirje rogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, '§ Oltar bo dvanajst komolcev dolg, dvanajst širok, kvadraten v svojih štirih oglih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Podzidek bo štirinajst komolcev dolg in štirinajst širok v svojih štirih oglih; in rob okoli njega bo pol komolca; in njegovo dno bo komolec naokrog; in njegove stopnice bodo gledale proti vzhodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Rekel mi je: »Človeški sin, tako govori Gospod Bog: ›To so odredbe oltarja na dan, ko ga bodo naredili, da bodo na njem darovali žgalne daritve in da bodo na njem škropili kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Duhovnikom Lévijevcem, ki bodo od Cadókovega semena, ki pristopajo k meni, da bi mi služili,‹ govori Gospod Bog, ›boš dal mladega bikca za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Vzel boš od njegove krvi in jo nanesel na štiri njegove rogove in na štiri vogle podzidka in na rob naokoli. Tako ga boš očistil in prečistil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Vzel boš tudi bikca daritve za greh in zažgal ga bo na določenem prostoru hiše, zunaj svetišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Na drugi dan boš daroval kozlička od koz, brez pomanjkljivosti, za daritev za greh; in očistili bodo oltar, kakor so ga očistili z bikcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Ko narediš konec njegovemu očiščevanju, boš daroval mladega bikca, brez pomanjkljivosti in ovna iz tropa, brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Daroval ju boš pred Gospodom in duhovniki bodo nanje vrgli sol in darovali jih bodo za žgalno daritev Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Sedem dni boš vsak dan pripravljal kozla za daritev za greh. Pripravljali bodo tudi mladega bikca in ovna iz tropa, brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sedem dni bodo očiščevali oltar in ga prečiščevali in se uméščali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Ko se ti dnevi iztečejo, bo tako, da bodo na osmi dan in tako naprej, duhovniki pripravljali vaše žgalne daritve na oltarju in vaše mirovne daritve; in jaz vas bom sprejel,‹ govori Gospod Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Potem me je privedel nazaj po poti velikih vrat zunanjega svetišča, ki gledajo proti vzhodu; in ta so bila zaprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Potem mi je Gospod rekel: »Ta velika vrata bodo zaprta, ne bodo odprta in noben človek ne bo vstopil skoznje; ker je Gospod, Izraelov Bog, vstopil skoznje, zato bodo zaprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Ta so za princa; princ bo sedel v njih, da jé kruh pred Gospodom; vstopil bo po poti preddverja teh velikih vrat in ven bo šel po isti poti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Potem me je privedel po poti severnih velikih vrat pred hišo. Pogledal sem in glej, Gospodova slava je napolnila Gospodovo hišo in padel sem na svoj obraz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Gospod mi je rekel: »Človeški sin, dobro zaznamuj in glej s svojimi očmi in poslušaj s svojimi ušesi vse, kar ti rečem glede vseh odredb Gospodove hiše in vse njegove postave; in dobro zaznamuj vhod hiše, z vsakim vstopanjem v svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Upornim boš rekel, celó Izraelovi hiši: ›Tako govori Gospod Bog: ›Oh vi, Izraelova hiša, naj vam bo dovolj vseh vaših ogabnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'v tem, da ste v moje svetišče privedli tujce, neobrezane v srcu in neobrezane v mesu, da bi bili v mojem svetišču, da ga oskrunijo, celó mojo hišo, ko darujete moj kruh, tolščo in kri in zaradi vseh vaših ogabnosti so prelamljali mojo zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Vi niste skrbeli za moje svete stvari, temveč ste si zase postavili čuvaje moje zadolžitve v mojem svetišču.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tako govori Gospod Bog: ›Noben tujec, neobrezan v srcu niti neobrezan v mesu, izmed kateregakoli tujca, ki je med Izraelovimi otroki, ne bo vstopil v moje svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Lévijevci, ki so šli daleč proč od mene, ko je Izrael zašel, ki so zašli proč od mene, za svojimi maliki; oni bodo torej nosili svojo krivdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Vendar bodo služabniki v mojem svetišču in imeli bodo zadolžitev pri velikih vratih hiše in služili bodo hiši. Klali bodo žgalno daritev in klavno daritev za ljudstvo in stali bodo pred njimi, da jim služijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Ker so jim služili pred njihovimi maliki in Izraelovi hiši povzročili, da pade v krivičnost; zatorej sem proti njim vzdignil svojo roko,‹ govori Gospod Bog ›in nosili bodo svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'In ne bodo mi prišli blizu, da bi mi opravljali duhovniško službo niti da bi se približali katerikoli izmed mojih svetih stvari na najsvetejšem kraju, temveč bodo nosili svojo sramoto in svoje ogabnosti, ki so jih zagrešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Toda naredil jih bom čuvaje oskrbe hiše, za vso njeno službo in za vse, kar bo v njej storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Toda duhovniki Lévijevcev, Cadókovi sinovi, ki so skrbeli za moje svetišče, ko so Izraelovi otroci zašli od mene, mi bodo prišli blizu, da bi mi služili in stali bodo pred menoj, da mi darujejo tolščo in kri,‹ govori Gospod Bog:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, '›Vstopali bodo v moje svetišče in se približali moji mizi, da bi mi služili in skrbeli za mojo zadolžitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'In zgodilo se bo, ko vstopajo pri velikih vratih notranjega dvora, da bodo oblečeni s platnenimi oblačili; in nobena volna ne bo prišla nanje, medtem ko služijo pri velikih vratih notranjega dvora in znotraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Na svojih glavah bodo imeli platnene klobučke in na svojih ledjih bodo imeli kratke platnene hlače; ne bodo se opasovali s čimerkoli, kar povzroča znojenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Ko gredo naprej, na skrajni dvor, celó na skrajni dvor ljudstva, bodo odložili svoja oblačila, v katerih so služili in jih položili v svete sobe in nadeli si bodo druga oblačila in ljudstva ne bodo posvetili s svojimi oblačili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Niti si ne bodo brili svojih glav niti ne bodo pustili pramenom, da zrastejo dolgi. Svoje glave si bodo zgolj strigli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Niti ne bo katerikoli duhovnik pil vina, ko vstopa na notranji dvor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Niti si za svoje žene ne bodo jemali vdove, niti tiste, ki je odslovljena, temveč si bodo jemali device od semena Izraelove hiše ali vdovo, ki je imela poprej duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Moje ljudstvo bodo učili razliko med svetim in oskrunjenim in jim povzročili, da razpoznavajo med nečistim in čistim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'V polemiki bodo razsojali in sodili jo bodo glede na moje sodbe in držali se bodo mojih postav in mojih zakonov in vseh mojih pravil, v vseh mojih zborih; in posvečevali bodo moje šabate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Ne bodo prišli k nobeni mrtvi osebi, da se omadežujejo, razen za očeta ali za mater ali za sina, ali za hčer, za brata ali za sestro, ki nima soproga, se lahko omadežujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Potem ko je očiščen, mu bodo prišteli sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Na dan, ko gre v svetišče, na notranji dvor, da služi v svetišču, bo daroval svojo daritev za greh,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, '›To jim bo za dediščino: jaz sem njihova dediščina. Ne boste jim dali posesti v Izraelu. Jaz sem njihova posest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Jedli bodo jedilno daritev in daritev za greh in daritev za prestopek in vsaka posvečena stvar v Izraelu bo njihova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Prvo izmed vseh prvih sadov od vseh stvari in vsaka daritev od vsega, od vsake vrste izmed vaših daritev, bo duhovnikova. Prav tako boste dali duhovniku prvo od svojega testa, da bo lahko povzročil, da v tvoji hiši počiva blagoslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Duhovniki ne bodo jedli od česarkoli, kar je umrlo samo od sebe ali je bilo raztrgano, naj bo to perjad ali žival.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Poleg tega, ko boste deželo z žrebom razdeljevali v dediščino, boste darovali daritev Gospodu, sveti delež dežele: dolžina bo petindvajset tisoč trstik in širina bo deset tisoč trstik. To bo sveto na vseh njihovih mejah naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Od tega bo tam za svetišče petsto v dolžino, s petsto v širino, kvadratno naokoli; in petdeset komolcev naokoli za njegova predmestja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Od te mere boš izmeril dolžino petindvajset tisoč in širino deset tisoč, in na njem bo svetišče in najsvetejši prostor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Sveti delež dežele bo za duhovnike, služabnike svetišča, ki se bodo približali, da bi služili Gospodu in to bo prostor za njihove hiše in sveti prostor za svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, '§ Petindvajset tisoč dolžine in deset tisoč širine bodo prav tako imeli Lévijevci, služabniki hiše, zase, za posest, za dvajset sob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Določili boste posest mesta, pet tisoč široko in petindvajset tisoč dolgo, nasproti daritve svetega deleža. Ta bo za celotno Izraelovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Delež bo za princa na eni strani in na drugi strani daritve svetega deleža in od mestne posesti, pred daritvijo svetega deleža in pred mestno posestjo od zahodne strani proti zahodu in od vzhodne strani proti vzhodu, in dolžina bo nasproti enemu izmed deležev od zahodne meje do vzhodne meje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'V deželi bo njegova posest v Izraelu in moji princi ne bodo več zatirali mojega ljudstva in preostanek dežele bodo dali Izraelovi hiši, glede na njihove rodove.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tako govori Gospod Bog: ›Naj vam to zadostuje, oh Izraelovi princi: odstranite nasilje in rop, izvršujte sodbo in pravico, odstranite svoje razlastitve od mojega ljudstva,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, '›Imeli boste pravične tehtnice in pravičen škaf in pravičen čeber.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Škaf in čeber bosta ene mere, da bo čeber lahko vseboval deseti del tovora in škaf deseti del tovora; njegova mera bo po tovoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Šekel bo dvajset ger. Dvajset šeklov, petindvajset šeklov, petnajst šeklov bo vaša mina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'To je daritev, ki jo boste darovali: šesti del škafa od tovora pšenice in dali boste šesti del škafa od tovora ječmena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Glede odredbe olja, čeber olja; darovali boste deseti del čebra iz kadi, kar je tovor desetih čebrov, kajti deset čebrov je tovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Eno jagnje iz tropa, izmed dvesto, iz obilnih Izraelovih pašnikov; za jedilno daritev in za žgalno daritev in za mirovne daritve, da zanje opravijo pobotanje,‹ govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, '›Vse ljudstvo dežele bo dalo to daritev za princa v Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'To bo delež princa, da da žgalne daritve in jedilne daritve in pitne daritve ob praznikih, ob mlajih, ob šabatih, ob vseh slovesnostih Izraelove hiše. Pripravil bo daritev za greh, jedilno daritev, žgalno daritev in mirovne daritve, da opravi pobotanje za Izraelovo hišo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tako govori Gospod Bog: ›V prvem mesecu, na prvi dan meseca, boš vzel mladega bikca brez pomanjkljivosti in očistil svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Duhovnik bo vzel od krvi daritve za greh in jo pomazal na podboje hiše in na štiri vogale oltarnega podzidka in na podboje velikih vrat notranjega dvora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tako boš delal sedmi dan meseca, za vsakega, ki se moti in za tistega, ki je preprost. Tako boš pobotal hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'V prvem mesecu, na štirinajsti dan meseca, boste imeli pasho, sedemdnevni praznik; jedel se bo nekvašeni kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Na tisti dan bo princ zase in za vse ljudstvo dežele pripravil bikca za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Sedem dni praznika bo pripravljal žgalno daritev Gospodu, sedem bikcev in sedem ovnov brez pomanjkljivosti, vsak dan, sedem dni; in vsak dan kozlička od koz za daritev za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Pripravil bo jedilno daritev: škaf za bikca, škaf za ovna in vrč olja za škaf.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'V sedmem mesecu, na petnajsti dan meseca, bo podobno storil ob prazniku sedmih dni, glede na daritev za greh, glede na žgalno daritev in glede na jedilno daritev in glede na olje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tako govori Gospod Bog: ›Velika vrata notranjega dvora, ki gledajo proti vzhodu, bodo zaprta šest delovnih dni; toda na šabat bodo ta odprta in na mlaj bodo ta odprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Princ bo vstopil po poti preddverja teh velikih vrat od zunaj in stal bo pri podboju velikih vrat in duhovniki bodo pripravili njegovo žgalno daritev in njegove mirovne daritve in oboževal bo na pragu velikih vrat in potem bo šel naprej; toda velika vrata ne bodo zaprta do večera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Podobno bo ljudstvo dežele oboževalo ob vratih teh velikih vrat pred Gospodom na šabate in na mlaje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Žgalna daritev, ki jo bo princ daroval Gospodu na šabatni dan, bo šest jagnjet brez pomanjkljivosti in oven brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Jedilna daritev bo škaf za ovna in jedilna daritev za jagnjeta, kakor bo ta zmožen dati in vrč olja k škafu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Na dan mlaja bo mlad bikec brez pomanjkljivosti in šest jagnjet in oven; ti bodo brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Pripravil bo jedilno daritev, škaf za bikca, škaf za ovna, za jagnjeta pa glede na to, kolikor bo njegova roka dosegla in vrč olja k škafu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Ko bo princ vstopil, bo vstopil po poti preddverja tistih velikih vrat in naprej bo šel po tisti poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Toda ko bo ljudstvo dežele ob slovesnih praznikih prišlo pred Gospoda, bo tisti, ki vstopa po poti severnih velikih vrat, da bi oboževal, šel ven po poti južnih velikih vrat; in tisti, ki vstopa po poti južnih velikih vrat, bo šel naprej po poti severnih velikih vrat. Ne bo se vrnil po poti velikih vrat, pri katerih je vstopil, temveč bo šel naprej proti nasprotnim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Princ v njihovi sredi bo vstopil, ko bodo oni vstopili; in ko bodo šli naprej, bo šel naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Ob praznikih in ob slovesnostih bo jedilna daritev škaf k bikcu in škaf k ovnu, za jagnjeta pa kolikor je zmožen dati in vrč olja k škafu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Torej ko bo princ pripravil prostovoljno žgalno daritev ali mirovne daritve prostovoljno Gospodu, mu bo takrat nekdo odprl velika vrata, ki gledajo proti vzhodu in pripravil bo svojo žgalno daritev in svoje mirovne daritve, kot je to storil na šabatni dan. Takrat bo šel naprej in potem ko bo šel naprej, bo nekdo zaprl vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Dnevno boš pripravljal žgalno daritev Gospodu od jagnjeta prvega leta brez pomanjkljivosti. To boš pripravljal vsako jutro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Zanj boš vsako jutro pripravil jedilno daritev, šesti del škafa in tretji del vrča olja, da to umešaš s fino moko; nenehna jedilna daritev po večni odredbi Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Tako bodo pripravili jagnje in jedilno daritev in olje, vsako jutro za nenehno žgalno daritev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tako govori Gospod Bog: ›Če da princ darilo kateremukoli izmed svojih sinov, bo ta dediščina od njegovih sinov; to bo njihova posest po dediščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Toda če da darilo svoje dediščine enemu izmed svojih služabnikov, potem bo to njegovo do leta osvoboditve; po tem se bo vrnilo princu, toda njegova dediščina bo za njegove sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Še več, princ ne bo vzel od dediščine ljudstva z zatiranjem, da bi jih sunil iz njihove posesti, temveč bo dal dediščino svojim sinovom od svoje lastne posesti, da moje ljudstvo ne bo razpršeno, vsak mož iz svoje posesti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Potem me je privedel skozi vhod, ki je bil ob strani velikih vrat, v svete sobe duhovnikov, ki so gledale proti severu, in glej, tam je bil kraj, na dveh straneh proti zahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Potem mi je rekel: »To je kraj, kjer bodo duhovniki vreli daritev za prestopek in daritev za greh in kjer bodo pekli jedilno daritev; da jih ne bodo nosili ven na skrajni dvor, da bi posvetili ljudstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Potem me je privedel na skrajni dvor in mi storil, da grem mimo štirih vogalov dvora; in glej, na vsakem vogalu dvora je bil dvor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Na štirih vogalih dvora so bili dvori združeni iz štiridesetih komolcev dolžine in tridesetih širine. Ti štirje vogali so bili ene mere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Tam je bila okoli njih vrsta zgradb, okrog vseh štirih in narejena je bila s kraji za vretje pod vrstami naokrog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Potem mi je rekel: »To so kraji tistih, ki vrejo, kjer bodo služabniki hiše vreli klavno daritev ljudstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Potem me je ponovno privedel k vratom hiše; in glej, vode so izhajale ven izpod praga hiše proti vzhodu, kajti pročelje hiše je stalo proti vzhodu in vode so prihajale dol izpod desne strani hiše pri južni strani oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Potem me je privedel ven, po poti velikih vrat proti severu in me vodil naokrog po zunanji poti, k skrajnim velikim vratom, po poti, ki gleda proti vzhodu in glej, tam so vode iztekale na desni strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Ko je človek, ki je imel v svoji roki vrvico, šel proti vzhodu, je izmeril tisoč komolcev in me privedel skozi vode; vode so bile do gležnjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Ponovno je izmeril tisoč in me privedel skozi vode; vode so bile do kolen. Ponovno je izmeril tisoč in me privedel skozi; vode so bile do ledij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Potem je izmeril tisoč; in to je bila reka, ki je nisem mogel prebresti, kajti vode so narasle, vode za plavanje v njih, reka, ki ne more biti prebredena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Rekel mi je: »Človeški sin, ali si videl tole?« Potem me je privedel in mi storil, da se vrnem k bregu reke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Torej, ko sem se vrnil, glej, na bregu reke je bilo zelo veliko dreves na tej strani in na drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Potem mi je rekel: »Te vode iztekajo proti vzhodni deželi in gredo dol v puščavo in gredo v morje; katerega vode, ko bodo privedene v morje, bodo ozdravljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'In zgodilo se bo, da vsaka stvar, ki živi, ki se giblje, kamor koli bodo prišle reke, bo živela, in tam bo zelo velika množica rib, ker bodo te vode prišle tja, kajti ozdravljene bodo; in vsaka stvar bo živela, kamor prihaja reka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'In zgodilo se bo, da bodo na njej stali ribiči, od En Gedija celo do En Eglájima; one bodo kraj za razširjanje mrež; njihovih rib bo glede na njihove vrste, kakor rib vélikega morja, izjemno veliko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Toda njeni blatni kraji in njena močvirja ne bodo ozdravljena; izročena bodo soli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Ob reki, na njenem bregu, na tej strani in na tisti strani, bodo rasla vsa drevesa za hrano, katerih listje ne bo ovenelo niti njihov sad ne bo použit. Rodila bodo nov sad, glede na njegove mesece, ker so njihove vode izvirale iz svetišča in njihov sad bo za hrano in njihovo listje bo za zdravilo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tako govori Gospod Bog: »To bo meja, po kateri boste podedovali deželo glede na dvanajst Izraelovih rodov. Jožef bo imel dva deleža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'To boste podedovali, tako eden kakor drugi; glede katere sem dvignil svojo roko, da jo izročim vašim očetom, in ta dežela bo padla vam v dediščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'To bo meja dežele proti severni strani, od vélikega morja, pot Hetlóna, kakor gredo ljudje v Cedád;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamát, Beróte, Sibrájim, ki je med mejo Damaska in mejo Hamáta; Hacár Atikon, ki je ob obali Havrána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Meja od morja bo Hacár Enán, meja Damaska in severno proti severu in meja Hamáta. To je severna stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Vzhodno stran boš meril od Havrána in od Damaska in od Gileáda in od dežele Izrael ob Jordanu, od meje k vzhodnemu morju. To je vzhodna stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Južna stran proti jugu, od Tamára celó k vodam prepira v Kadešu, reka k vélikemu morju. To je južna stran proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Tudi zahodna stran bo véliko morje od meje, dokler človek ne pride nasproti Hamátu. To je zahodna stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Tako si boste razdelili to deželo glede na Izraelove rodove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Zgodilo se bo, da jo boste razdelili z žrebom v dediščino sebi in tujcem, ki začasno prebivajo med vami, ki bodo med vami zaplodili otroke in oni vam bodo kakor rojeni v deželi med Izraelovimi otroki; imeli bodo dediščino z vami med Izraelovimi rodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'In zgodilo se bo, da pri rodu, v katerem začasno prebiva tujec, tam mu boste dali njegovo dediščino,« govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Torej to so imena rodov. Od severnega konca do obale, po poti v Hetlón, kot gre nekdo do Hamáta, Hacár Enána, meje Damaska proti severu, do obale Hamáta; kajti to so njegove strani vzhodno in zahodno; delež za Dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Ob meji Dana, od vzhodne strani do zahodne strani, delež za Aserja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Ob meji Aserja, od vzhodne strani, celo do zahodne strani, delež za Neftálija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Ob meji Neftálija, od vzhodne strani do zahodne strani, delež za Manáseja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Ob meji Manáseja, od vzhodne strani do zahodne strani, delež za Efrájim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Ob meji Efrájima, od vzhodne strani, celo do zahodne strani, delež za Rubena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Ob meji Rubena, od vzhodne strani do zahodne strani, delež za Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Ob meji Juda, od vzhodne strani do zahodne strani, bo daritev, ki jo boste darovali petindvajset tisoč trstik po širini in po dolžini kakor enega izmed drugih deležev, od vzhodne strani do zahodne strani, in svetišče bo v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, '§ Daritev, ki jo boste darovali Gospodu, bo petindvajset tisoč po dolžini in deset tisoč po širini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Zanje, celó za duhovnike, bo to sveta daritev; proti severu petindvajset tisoč po dolžini in proti zahodu deset tisoč po širini in proti vzhodu deset tisoč po širini in proti jugu petindvajset tisoč po dolžini; in Gospodovo svetišče bo v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'To bo za duhovnike, ki so posvečeni izmed Cadókovih sinov; ki so se držali moje zadolžitve, ki niso zašli, ko so Izraelovi otroci zašli, kakor so zašli Lévijevci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Ta daritev dežele, ki je darovana, jim bo najsvetejša stvar ob meji Lévijevcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Nasproti meji duhovnikov bodo Lévijevci imeli petindvajset tisoč po dolžini in deset tisoč po širini; vsa dolžina bo petindvajset tisoč in širina deset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'In od tega ne bodo prodali niti zamenjali niti odtujili prvih sadov dežele, kajti to je sveto Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Pet tisoč, ki preostanejo po širini, nasproti petindvajset tisočem, bo oskrunjen kraj za mesto, za prebivanje in za predmestja; in mesto bo v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'To bodo njegove mere: severna stran štiri tisoč petsto, južna stran štiri tisoč petsto, na vzhodni strani štiri tisoč petsto in zahodna stran štiri tisoč petsto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Predmestja mesta bodo proti severu dvesto petdeset, proti jugu dvesto petdeset, proti vzhodu dvesto petdeset in proti zahodu dvesto petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Preostanek v dolžini nasproti daritve svetega deleža bo deset tisoč proti vzhodu in deset tisoč proti zahodu, in to bo nasproti daritve svetega deleža; njegov donos bo za hrano tistim, ki služijo mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Tisti, ki služijo mestu, mu bodo služili izmed vseh Izraelovih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Vseh daritev bo petindvajset tisoč krat petindvajset tisoč. Darovali boste štirioglato sveto daritev z mestno posestjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Preostanek pa bo za princa na eni strani in na drugi od svete daritve in od mestne posesti nasproti petindvajset tisočim od daritve proti vzhodni meji in zahodno, nasproti petindvajset tisočim proti zahodni meji, nasproti deležem za princa. To bo sveta daritev in svetišče hiše bo v njegovi sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Poleg tega bo za princa od posesti Lévijevcev in od mestne posesti, ki je v sredi tega, kar pripada princu, med Judovo mejo in Benjaminovo mejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Glede preostanka rodov od vzhodne strani do zahodne strani bo imel delež Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Ob Benjaminovi meji, od vzhodne strani do zahodne strani, bo imel delež Simeon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Ob Simeonovi meji, od vzhodne strani do zahodne strani, Isahárjev delež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Ob Isahárjevi meji, od vzhodne strani do zahodne strani, Zábulonov delež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Ob Zábulonovi meji, od vzhodne strani do zahodne strani, Gadov delež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Ob Gadovi meji, pri južni strani proti jugu, bo meja celo od Tamára do vodá prepira v Kadešu in do reke proti vélikemu morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'To je dežela, ki jo boste razdelili z žrebom Izraelovim rodovom za dediščino in to so njihovi deleži,« govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'To so izhodi iz mesta na severni strani, štiri tisoč petsto mer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Velika vrata mesta bodo po imenih Izraelovih rodov; troje velikih vrat proti severu: ena Rubenova velika vrata, ena Judova velika vrata, ena Lévijeva velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Pri vzhodni strani štiri tisoč petsto; in troje velikih vrat: in ena Jožefova velika vrata, ena Benjaminova velika vrata, ena Danova velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Pri južni strani štiri tisoč petsto mer; in troje velikih vrat: ena Simeonova velika vrata, ena Isahárjeva velika vrata, ena Zábulonova velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Pri zahodni strani štiri tisoč petsto, z njihovimi tremi velikimi vrati: ena Gadova velika vrata, ena Aserjeva velika vrata, ena Neftálijeva velika vrata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Naokoli je bilo osemnajst tisoč mer. Ime mesta bo od tega dne: Gospod je tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'V tretjem letu kraljevanja Judovega kralja Jojakíma je prišel babilonski kralj Nebukadnezar iz Babilona do Jeruzalema in ga oblegal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Gospod je Judovega kralja Jojakíma izročil v njegovo roko, z delom posod iz Božje hiše, ki jih je odnesel v deželo Šinár, k hiši svojega Boga in posode je prinesel v zakladno hišo svojega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Kralj je spregovoril Ašpenázu, gospodarju svojih evnuhov, da naj privede nekatere izmed Izraelovih otrok, izmed kraljevega potomstva in izmed princev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'otroke, na katerih ni bilo madeža, temveč lepega videza in spretne v vsej modrosti in bistroumne v spoznanju in razumevanju znanosti in takšne, ki imajo v sebi zmožnost stati v kraljevi palači in ki bi jih lahko učili znanja in jezika Kaldejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Kralj jim je določil dnevno preskrbo kraljeve hrane in od vina, ki ga je pil. Tako jih je hranil tri leta, da bi ob njihovem izteku lahko stali pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Torej med temi so bili od Judovih otrok Daniel, Hananjá, Mišaél in Azarjá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'ki jim je princ evnuhov dal imena, kajti Danielu je dal ime Beltšacár, Hananjáju Šadráh, Mišaélu Mešáh in Azarjáju Abéd Negó.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Toda Daniel se je v svojem srcu namenil, da se ne bi omadeževal z deležem kraljeve hrane niti z vinom, ki ga je ta pil, zatorej je od princa evnuhov prosil, da se mu ne bi bilo treba omadeževati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Torej Bog je Daniela privedel v naklonjenost in nežno prijaznost s princem evnuhov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Princ evnuhov je Danielu rekel: »Bojim se svojega gospoda kralja, ki vam je določil vašo hrano in vašo pijačo, kajti zakaj bi videl vaša obličja videti slabša kakor od otrok, ki so iz vaše vrste? Potem bi mene prisilili ogrožati mojo glavo kralju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, '§ Potem je Daniel rekel Melzarju, ki ga je princ evnuhov postavil nad Daniela, Hananjája, Mišaéla in Azarjája:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '»Potrdi svojim služabnikom, rotim te, deset dni, in naj nam dajo za jesti rastlinsko hrano in vodo za pitje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Potem naj bodo naša obličja ogledana pred teboj in obličje otrok, ki jedo od deleža kraljeve hrane, in kakor vidiš [tako] postopaj s svojimi služabniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Tako se je ta strinjal z njimi v tej zadevi in jim potrdil deset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Ob koncu desetih dni so bila njihova obličja videti svetlejša in obilnejša v mesu kakor od vseh otrok, ki so jedli od deleža kraljeve hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, '§ Potem je Melzar odvzel delež njihove hrane in vino, ki naj bi ga pili in jim dajal rastlinsko hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Glede teh štirih otrok, jim je Bog dal znanje in spretnost v vsem učenju in modrosti. Daniel je imel razumevanje o vseh videnjih in sanjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Torej ob koncu dni, o katerih je kralj rekel, da naj jih privede, jih je potem princ evnuhov privedel pred Nebukadnezarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Kralj se je z njimi pogovarjal in med njimi vsemi ni našel nikogar podobnega Danielu, Hananjáju, Mišaélu in Azarjáju. Zato so stali pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'V vseh vrstah modrosti in razumevanja, ki jih je kralj poizvedel od njih, jih je našel desetkrat boljše od vseh čarovnikov in astrologov, ki so bili v vsem njegovem območju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel je ostal celó do prvega leta kralja Kira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'V drugem letu kraljevanja Nebukadnezarja je Nebukadnezar sanjal sanje, s čimer je bil njegov duh vznemirjen in njegovo spanje se je ločilo od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Potem je kralj zapovedal, da pokličejo čarovnike, astrologe, čarodeje in Kaldejce, da kralju razodenejo njegove sanje. Tako so prišli in stali pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Kralj jim je rekel: »Sanjal sem sanje in moj duh je bil vznemirjen, da bi razumel sanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Potem so Kaldejci spregovorili kralju po sirsko: »Oh kralj, živi na veke. Povej svojim služabnikom sanje, mi pa bomo pokazali pomen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kralj je odgovoril in Kaldejcem rekel: »Ta stvar je odšla od mene. Če mi ne boste razložili sanj, z njihovo razlago, boste razrezani na koščke, vaše hiše pa bodo narejene za gnojišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Toda če mi boste pokazali sanje in njihov pomen, boste od mene prejeli darila in nagrade in veliko čast. Zatorej mi razodenite sanje in njihov pomen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Ponovno so odgovorili in rekli: »Naj kralj pove svojim služabnikom sanje, mi pa bomo pokazali njihov pomen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kralj je odgovoril in rekel: »Zagotovo vem, da hočete pridobiti čas, ker ste videli, da je stvar odšla od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Toda če mi ne boste pokazali sanj, je za vas samo en odlok, kajti pripravili ste lažnive in izprijene besede, da jih govorite pred menoj, dokler čas ne bo spremenjen. Zato mi povejte sanje in vedel bom, da mi lahko pokažete njihovo razlago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Kaldejci so pred kraljem odgovorili in rekli: »Na zemlji ni človeka, ki lahko pokaže kraljevo zadevo. Zato tam ni kralja, gospodarja niti vladarja, ki bi zahteval takšne besede pri kateremkoli čarovniku ali astrologu ali Kaldejcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'To je redka stvar, ki jo kralj zahteva in nikogar drugega ni, ki lahko to razodene pred kraljem, razen bogov, katerih prebivališče ni z mesom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Zaradi tega razloga je bil kralj jezen in zelo besen in ukazal, da uničijo vse modre babilonske može.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Odlok je odšel naprej, da bodo modri možje umorjeni, in iskali so Daniela in njegove tovariše, da bi bili umorjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Potem je Daniel z nasvetom in preudarnostjo odgovoril Arjóhu, poveljniku kraljeve straže, ki je odšel, da umori modre babilonske može.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Odgovoril je in kraljevemu poveljniku Arjóhu rekel: »Zakaj je kraljevi odlok tako nagel?« Potem je Arjóh stvar razložil Danielu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Potem je Daniel vstopil in želel od kralja, da naj mu da čas in da bo on kralju pokazal razlago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Potem je Daniel odšel k svoji hiši in dal stvar spoznati Hananjáju, Mišaélu in Azarjáju, svojim družabnikom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'da bi glede te skrivnosti želeli milosti od Boga nebes; da se Daniel in njegovi tovariši ne bi pogubili z ostalimi modrimi babilonskimi možmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Potem je bila Danielu skrivnost razodeta v nočnem videnju. Potem je Daniel blagoslovil Boga nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel je odgovoril in rekel: »Blagoslovljeno bodi ime Boga na veke vekov, kajti modrost in moč sta njegovi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'in on spreminja čase ter obdobja. Odstranja kralje in postavlja kralje. Daje modrost modrim in spoznanje tistim, ki poznajo razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Razodeva globoke in skrite stvari. Ve kaj je v temi in razsvetljenje prebiva z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Zahvaljujem se ti in te hvalim, oh ti Bog mojih očetov, ki si mi dal modrost in moč in si mi sedaj razodel, kar smo želeli od tebe, kajti sedaj si nam pokazal kraljevo zadevo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Zato je Daniel vstopil k Arjóhu, ki mu je kralj odredil, da uniči modre babilonske može. Odšel je in mu takole rekel: »Ne uniči modrih babilonskih mož, privedi me pred kralja in kralju bom pokazal razlago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Potem je Arjóh Daniela v naglici privedel pred kralja in mu takole rekel: »Našel sem moža izmed Judovih ujetnikov, ki bo kralju dal spoznati razlago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kralj je odgovoril in rekel Danielu, čigar ime je bilo Beltšacár: »Ali si mi zmožen pokazati sanje, ki sem jih videl in njihovo razlago?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel je v prisotnosti kralja odgovoril in rekel: »Skrivnosti, ki jo je kralj zahteval, modri možje, astrologi, čarovniki [in] napovedovalci usode kralju ne morejo pokazati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'toda Bog je v nebesih, ki razodeva skrivnosti in daje spoznati kralju Nebukadnezarju, kaj bo v zadnjih dneh. Tvoje sanje in videnja tvoje glave na tvoji postelji so ta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Kar se tebe tiče, oh kralj, tvoje misli so prišle v tvoj um na tvoji postelji, kaj se bo odslej zgodilo in on, ki razodeva skrivnosti, ti daje spoznati, kaj se bo zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Toda kar se mene tiče, mi ta skrivnost ni bila razodeta zaradi kakršnekoli modrosti, ki bi jo imel več kakor katerikoli živeči, temveč zaradi tistih, ki bodo dali spoznati razlago kralju in da boš lahko poznal misli svojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Ti, oh kralj, si videl in ogledoval veliko podobo. Ta velika podoba, katere sijaj je bil odličen, je stala pred teboj in njena oblika je bila strašna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Glava te podobe je bila iz čistega zlata, njene prsi in njeni lakti iz srebra, njen trebuh in njena stegna iz brona,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'njene noge iz železa, njena stopala deloma iz železa, deloma pa iz ila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Gledal si, dokler ni bil brez rok izklesan kamen, ki je zadel podobo v njena stopala, ki so bila iz železa in ila in jih zlomil na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Potem so bili železo, il, bron, srebro in zlato skupaj zlomljeni na koščke in postali kakor pleve na poletnem mlatišču, in veter jih je odnesel, da zanje ni bilo najti nobenega prostora. Kamen, ki je zadel podobo, pa je postal velika gora in napolnil celotno zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'To so sanje in njihovo razlago bomo povedali pred kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Ti, oh kralj, si kralj kraljev, kajti Bog nebes ti je dal kraljestvo, oblast, moč in slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Kjerkoli prebivajo človeški otroci, je v tvojo roko dal živali polja in perjad neba in te naredil vladarja nad njimi vsemi. Ti si ta glava iz zlata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Za teboj pa bo vstalo drugo kraljestvo, slabše od tvojega in še eno, tretje kraljestvo iz brona, ki bo vladalo nad celotno zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Četrto kraljestvo bo čvrsto kakor železo. Kakor železo zlomi na koščke in podjarmi vse stvari, in kakor železo, ki zlomi vse te, [tako] bo to razbilo na koščke in poškodovalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Kakor si videl stopala in prste, delno iz lončarjevega ila in delno iz železa, bo kraljestvo razdeljeno, toda v njem bo moč železa, ker si videl železo pomešano z blatnim ilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'In kakor so bili prsti stopal deloma iz železa in deloma iz ila, tako bo kraljestvo delno močno in delno zlomljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Kakor si videl železo, pomešano z blatnim ilom, tako se bodo mešali med seboj s človeškim semenom, toda ne bodo se držali drug drugega, celó kakor železo ni pomešano z ilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'V dneh teh kraljev bo Bog nebes vzpostavil kraljestvo, ki ne bo nikoli uničeno. In kraljestvo ne bo ostalo drugemu ljudstvu, temveč bo zlomilo na koščke in požrlo vsa ta kraljestva, sámo pa bo obstalo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Ker si videl, da je bil kamen brez rok izklesan iz gore in da je ta zlomil na koščke železo, bron, ilo, srebro in zlato; véliki Bog je dal spoznati kralju, kaj se bo odslej zgodilo. Sanje so zanesljive in njihova razlaga nedvoumna.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Potem je kralj Nebukadnezar padel na svoj obraz, oboževal Daniela in zapovedal, da mu morajo darovati daritev in prijetne dišave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Kralj je Danielu odgovoril in rekel: »Resnično je to, da je vaš Bog Bog bogov in gospod kraljev in [ta], ki razodeva skrivnosti, glede na to, da si lahko razodel to skrivnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Potem je kralj Daniela naredil za velikega moža in mu dal mnoga sijajna darila in ga naredil vladarja nad celotno provinco Babilon in glavnega izmed voditeljev nad vsemi modrimi možmi Babilona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Potem je Daniel prosil kralja in ta je postavil Šadráha, Mešáha in Abéd Negója nad zadeve babilonske province, toda Daniel je sedel pri kraljevih velikih vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Kralj Nebukadnezar je naredil podobo iz zlata, katere višina je bila šestdeset komolcev, njena širina pa šest komolcev. Postavil jo je na ravnini Dura v provinci Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Potem je kralj Nebukadnezar poslal, da zbere skupaj prince, voditelje in poveljnike, sodnike, zakladnike, svetovalce, šerife in vse vladarje provinc, da pridejo k posvetitvi podobe, ki jo je postavil kralj Nebukadnezar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Potem so bili princi, voditelji in poveljniki, sodniki, zakladniki, svetovalci, šerifi in vsi vladarji provinc zbrani skupaj k posvetitvi podobe, ki jo je postavil kralj Nebukadnezar in stali so pred podobo, ki jo je postavil Nebukadnezar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Potem je glasnik naglas zavpil: »Vam je to zapovedano, oh ljudstvo, narodi in jeziki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'da kadar zaslišite zvok kornéta, flavte, harfe, pozavne, plunke, citer in vseh vrst glasbe, padite dol in obožujte zlato podobo, ki jo je postavil kralj Nebukadnezar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Kdorkoli ne pade dol in ne obožuje, bo isto uro vržen v sredo goreče ognjene talilne peči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Zatorej ob tistem času, ko je vse ljudstvo zaslišalo zvok kornéta, flavte, harfe, pozavne, plunke in vseh vrst glasbe, so vsa ljudstva, narodi in jeziki padli dol in oboževali zlato podobo, ki jo je postavil kralj Nebukadnezar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Zaradi česar so se ob tistem času približali neki Kaldejci in obtožili Jude.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Spregovorili so in rekli kralju Nebukadnezarju: »Oh kralj, živi na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ti, oh kralj, si izdal odlok, da naj vsak človek, ki bo zaslišal glas kornéta, flavte, harfe, pozavne, plunke in citer in vseh vrst glasbe, pade dol in obožuje zlato podobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Kdorkoli pa ne pade dol in je ne obožuje, ta bo vržen v sredo goreče ognjene talilne peči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Tam so nekateri Judje, ki si jih postavil nad zadeve babilonske province: Šadráh, Mešáh in Abéd Negó. Ti možje, oh kralj, te niso upoštevali. Ne služijo tvojim bogovom niti ne obožujejo zlate podobe, ki si jo ti postavil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Potem je Nebukadnezar v svoji besnosti in razjarjenosti zapovedal, da privedejo Šadráha, Mešáha in Abéd Negója. Potem so te može privedli pred kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnezar je spregovoril in jim rekel: » Je to res, oh Šadráh, Mešáh in Abéd Negój, [da] ne služite mojim bogovom niti ne obožujete zlate podobe, ki sem jo postavil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Torej če ste pripravljeni, da kadar zaslišite zvok kornéta, flavte, harfe, pozavne, plunke in citer in vse vrste glasbe, padete dol in obožujete podobo, ki sem jo naredil; dobro. Toda če je ne obožujete, boste isto uro vrženi v sredo goreče ognjene talilne peči, in kdo je tisti Bog, ki vas bo osvobodil iz mojih rok?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Šadráh, Mešáh in Abéd Negó so odgovorili in kralju rekli: »Oh Nebukadnezar, mi nismo zaskrbljeni, da ti odgovorimo v tej zadevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Če bo temu tako, naš Bog, ki mu služimo, nas je zmožen osvoboditi pred gorečo ognjeno talilno pečjo in on nas bo osvobodil iz tvoje roke, oh kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Toda če ne, bodi to znano tebi, oh kralj, da ne bomo služili tvojim bogovom niti oboževali zlate podobe, ki si jo postavil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Potem je bil Nebukadnezar poln razjarjenosti in videz njegovega obličja je bil spremenjen napram Šadráhu, Mešáhu in Abéd Negóju. Zatorej je spregovoril in zapovedal, da naj talilno peč sedemkrat bolj segrejejo, kot je bila običajno segreta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Zapovedal je najmočnejšim možem, ki so bili v njegovi vojski, da zvežejo Šadráha, Mešáha in Abéd Negója in da jih vržejo v gorečo ognjeno talilno peč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Potem so bili ti možje zvezani v njihovih plaščih, njihovih hlačah in njihovih klobukih in drugih njihovih oblačilih in vrženi so bili v sredo goreče ognjene talilne peči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Torej, ker je bila kraljeva zapoved nujna in talilna peč izjemno vroča, je plamen ognja usmrtil tiste može, ki so vzdignili Šadráha, Mešáha in Abéd Negója.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Ti trije možje, Šadráh, Mešáh in Abéd Negó so zvezani padli dol v sredo goreče ognjene talilne peči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Potem je bil kralj Nebukadnezar osupel, v naglici vstal in spregovoril ter svojim svetovalcem rekel: »Mar nismo v sredo ognja vrgli treh zvezanih mož?« Odgovorili so in rekli kralju: »Resnica, oh kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, '§ Ta je odgovoril in rekel: »Glejte, vidim štiri razvezane može, ki hodijo v sredi ognja in nimajo nobene poškodbe, oblika četrtega pa je podobna Božjemu Sinu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Potem se je Nebukadnezar približal odprtini goreče ognjene talilne peči in spregovoril ter rekel: »Šadráh, Mešáh in Abéd Negó, vi služabniki najvišjega Boga, pojdite ven in pridite sem.« Potem so Šadráh, Mešáh in Abéd Negó prišli naprej iz srede ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Princi, voditelji, poveljniki in kraljevi svetovalci, ki so bili zbrani skupaj, so videli te može, nad čigar telesi ogenj ni imel nobene oblasti, niti las njihove glave ni bil osmojen, niti njihovi plašči niso bili spremenjeni, niti nanje ni prešel vonj ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Potem je Nebukadnezar spregovoril in rekel: »Blagoslovljen bodi Bog Šadráha, Mešáha in Abéd Negója, ki je poslal svojega angela in rešil svoje služabnike, ki so zaupali vanj in spremenili kraljevo besedo in predali svoja telesa, da ne bi služili niti oboževali kateregakoli boga, razen svojega lastnega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Zato izdajam odlok: ›Da bo vsako ljudstvo, narod in jezik, ki spregovori karkoli neprimernega zoper Boga Šadráha, Mešáha in Abéd Negója, razrezano na koščke in njihove hiše bodo narejene za gnojišče, zato ker ni drugega Boga, ki lahko reši na ta način.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Potem je kralj povišal Šadráha, Mešáha in Abéd Negója v provinci Babilon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Kralj Nebukadnezar vsem ljudstvom, narodom in jezikom, ki prebivajo po vsej zemlji: »Mir naj se vam pomnoži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Zdelo se mi je dobro pokazati [preroška] znamenja in čudeže, ki jih je vzvišeni Bog izvršil napram meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Kako velika so njegova [preroška] znamenja! In kako mogočni so njegovi čudeži! Njegovo kraljestvo je večno kraljestvo in njegovo gospostvo je od roda do roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Jaz, Nebukadnezar, sem bil pri počitku v svoji hiši in uspešen v svoji palači.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Videl sem sanje, ki so me prestrašile in misli na moji postelji in videnja moje glave so me vznemirila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Zatorej sem izdal odlok, da privedejo predme vse modre može Babilona, da bi mi lahko dali spoznati razlago sanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Potem so vstopili čarovniki, astrologi, Kaldejci in napovedovalci usode, in pred njimi sem jim povedal sanje, toda niso mi dali spoznati njihove razlage.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Toda na koncu je prišel predme Daniel, katerega ime je bilo Beltšacár, glede na ime mojega boga in v katerem je duh svetih bogov. Pred njim sem povedal sanje, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '›Oh Beltšacár, gospodar čarovnikov, ker vem, da je v tebi duh svetih bogov in da te nobena skrivnost ne vznemirja, mi povej videnja mojih sanj, ki sem jih videl in njihovo razlago.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Takšna so bila videnja moje glave na moji postelji. Videl sem in glej drevo [je bilo] sredi zemlje in njegova višina je bila velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Drevo je raslo in bilo močno in njegova višina je segala do neba in njegovo vidno polje do konca vse zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Njegovo listje je bilo lepo in njegovega sadu obilo in na njem je bilo hrane za vse. Živali polja so pod njim imele senco in perjad neba je prebivala v njegovih vejah in vse meso je bilo od njega nahranjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Videl sem v videnjih svoje glave na svoji postelji in glej, stražar in sveti je prišel dol z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Glasno je zavpil in rekel takole: ›Posekajte drevo in odrežite njegove veje, otresite listje in raztresite njegov sad. Naj gredo živali proč izpod njega in perjad od njegovih mladik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'kljub temu pa pustite štor njegovih korenin v zemlji, celo v okovu iz železa in brona, v nežni travi polja in ta naj bo omočen z roso neba in njegov delež naj bo z živalmi na zemeljski travi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Naj bo njegovo srce spremenjeno od človeškega in naj mu bo dano živalsko srce, in nad njim naj mine sedem dob.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Ta stvar je po odloku stražarjev in zahteva po besedi svetih, z namenom, da bodo živi lahko spoznali, da Najvišji vlada v kraljestvu ljudi in ga daje komur hoče in postavi nadenj najnižjega izmed ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Te sanje sem jaz, kralj Nebukadnezar, videl. Torej ti, oh Beltšacár, razglasi njihovo razlago, ker vsi modri ljudje mojega kraljestva niso zmožni, da bi mi dali spoznati razlago, toda ti si zmožen, kajti duh svetih bogov je v tebi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Potem je bil Daniel, katerega ime je bilo Beltšacár, za eno uro osupel in njegove misli so ga vznemirile. Kralj je spregovoril in rekel: »Beltšacár, ne pusti, da bi te sanje ali njihova razlaga vznemirile.« Beltšacár je odgovoril in rekel: »Moj gospod, sanje naj bodo njim, ki te sovražijo in njihova razlaga tvojim sovražnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Drevo, ki si ga videl, ki je raslo in je bilo močno, katerega višina je segla do neba in katerega vidno polje je po vsej zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'katerega listje je bilo lepo in njegov sad obilen in je bilo na njem hrane za vse, pod katerim so prebivale živali polja in na čigar vejah je imela perjad neba svoje prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'To si ti, oh kralj, ki si zrasel in postal močan, kajti tvoja veličina je zrasla in sega do neba in tvoje gospostvo do konca zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Medtem ko je kralj videl stražarja in svetega prihajati dol z neba in reči: ›Posekajte drevo in ga uničite, vendar od njega pustite v zemlji štor s koreninami, celo z okovom iz železa in brona, v nežni travi polja; in naj bo ta omočen z roso neba in njegov delež naj bo z živalmi polja, dokler nad njim ne mine sedem dob.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'To je razlaga, oh kralj in to je odlok Najvišjega, ki je prišel nad mojega gospoda kralja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'da te bodo pregnali od ljudi in tvoje prebivališče bo z živalmi polja in pripravili te bodo, da boš jedel travo kakor voli in močili te bodo z roso neba in sedem dob bo prešlo nad teboj, dokler ne spoznaš, da Najvišji vlada v kraljestvu ljudi in ga daje komurkoli on hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Zapovedali so, da pustijo štor od drevesnih korenin; tvoje kraljestvo bo zagotovo pripadlo tebi, potem ko boš spoznal, da nebesa vladajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, '§ Zatorej, oh kralj, naj ti bo moj nasvet sprejemljiv in svoje grehe zlomi s pravičnostjo in svoje krivičnosti z izkazovanjem usmiljenja revnim; če bi to lahko bilo podaljšanje tvoje umirjenosti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Vse to je prišlo nad kralja Nebukadnezarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Ob koncu dvanajstih mesecev je hodil v palači babilonskega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Kralj je spregovoril in rekel: »Ali ni to veliki Babilon, ki sem ga jaz zgradil za hišo kraljestva po moči svoje oblasti in za čast svojega veličanstva?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Medtem ko je bila beseda v kraljevih ustih, je padel glas z neba, rekoč: »Oh kralj Nebukadnezar, tebi je govorjeno: ›Kraljestvo je odšlo od tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Pregnali te bodo od ljudi in tvoje prebivališče bo z živalmi polja. Prisilili te bodo, da boš jedel travo kakor voli in sedem dob bo prešlo nad teboj, dokler ne spoznaš, da Najvišji vlada v kraljestvu ljudi in ga daje komurkoli on hoče.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'To isto uro je bila stvar nad Nebukadnezarjem izpolnjena. Pregnan je bil od ljudi, jedel travo kakor voli in njegovo telo je bilo omočeno z roso z neba, dokler njegovi lasje niso zrasli kakor orlovo perje in njegovi nohti kakor ptičji kremplji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '»In ob koncu dni sem jaz, Nebukadnezar, povzdignil svoje oči k nebu in moje razumevanje se je vrnilo k meni in blagoslovil sem Najvišjega in hvalil in častil njega, ki živi na veke, katerega gospostvo je večno gospostvo in njegovo kraljestvo je od roda do roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Vsi prebivalci zemlje so šteti kakor nič in on dela glede na svojo voljo v vojski nebes in med prebivalci zemlje, in nihče ne more zadržati njegove roke ali mu reči: ›Kaj počneš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Ob istem času se je moj razum vrnil k meni in zaradi slave mojega kraljestva sta se moja čast in moj sijaj vrnila k meni in moji svetovalci in moji velikaši so me poiskali, jaz pa sem bil utrjen v svojem kraljestvu in dodano mi je bilo odlično veličanstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Sedaj jaz, Nebukadnezar, hvalim, povzdigujem in častim Kralja nebes. Vsa njegova dela so resnica in njegove poti sodba, tiste pa, ki hodijo v ponosu, je zmožen ponižati.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Kralj Belšacár je priredil veliko zabavo svojim tisoč velikašem in pil vino pred tisočimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Medtem ko je Belšacár okušal vino, je zapovedal, da prinesejo zlate in srebrne posode, ki jih je njegov oče Nebukadnezar odnesel iz templja, ki je bil v Jeruzalemu, da bi kralj in njegovi princi, njegove žene in njegove priležnice lahko pili iz njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Potem so prinesli zlate posode, ki so bile odnesene iz templja Božje hiše, ki je bila v Jeruzalemu; in kralj, njegovi princi, njegove žene in njegove priležnice so pili iz njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Pili so vino in hvalili bogove iz zlata in iz srebra, iz brona, iz železa, iz lesa in iz kamna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'V isti uri so prišli prsti človeške roke in pisali nasproti svečniku na zidnem ometu kraljeve palače, in kralj je zagledal del roke, ki je pisala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Potem je bilo kraljevo obličje spremenjeno in njegove misli so ga vznemirile, tako da so bili sklepi njegovih ledij mlahavi in njegova kolena so udarjala druga ob drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Kralj je glasno zaklical, da pripeljejo astrologe, Kaldejce in napovedovalce usode. In kralj je spregovoril in rekel modrim možem iz Babilona: »Kdorkoli bo prebral to pisanje in mi pokazal njegovo razlago, bo oblečen v škrlat in okoli svojega vratu bo imel verižico iz zlata in bo tretji vladar v kraljestvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Potem so vstopili vsi kraljevi modri možje, toda niso mogli prebrati pisanja niti kralju razglasiti njegove razlage.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Potem je bil kralj Belšacár silno vznemirjen in njegovo obličje na njem je bilo spremenjeno in njegovi velikaši so bili osupli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Torej kraljica je zaradi razloga besed kralja in njegovih velikašev prišla v hišo gostije in kraljica je spregovorila ter rekla: »Oh kralj, živi na veke. Naj te tvoje misli ne vznemirjajo niti naj tvoje obličje ne bo spremenjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'V tvojem kraljestvu je mož, v katerem je duh svetih bogov in v dneh tvojega očeta je bilo v njem najti razsvetljenje, razumevanje in modrost, podobno modrosti bogov; ki ga je kralj Nebukadnezar, tvoj oče, kralj, pravim, tvoj oče, postavil za gospodarja čarovnikov, astrologov, Kaldejcev in napovedovalcev usode;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'ker se je v tem istem Danielu, ki ga je kralj poimenoval Beltšacár, našel odličen duh, spoznanje, razumevanje sanj, naznanjanje težkih razsodb in razreševanje dvomov. Naj bo torej Daniel poklican in pokazal bo razlago.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Potem je bil Daniel priveden pred kralja. In kralj je spregovoril ter Danielu rekel: » Ali si ti tisti Daniel, ki si izmed otrok Judovega ujetništva, ki jih je kralj, moj oče, privedel iz Judeje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'O tebi sem slišal celo, da je v tebi duh bogov in da je v tebi najti razsvetljenje, razumevanje in odlično modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Sedaj so bili predme privedeni modri možje, astrologi, da bi prebrali to pisanje in mi dali spoznati njegovo razlago, toda niso mogli pokazati razlage stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'O tebi pa sem slišal, da lahko daješ razlage in razrešuješ dvome. Torej če lahko prebereš pisanje in mi razglasiš njegov pomen, potem boš oblečen s škrlatom in okoli svojega vratu boš imel zlato verižico in boš tretji vladar v kraljestvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Potem je Daniel odgovoril in pred kraljem rekel: »Naj tvoja darila [ostanejo] tebi in svoje nagrade daj drugemu; kljub temu bom kralju prebral pisanje in mu dal spoznati razlago.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ti, oh kralj. Najvišji Bog je dal tvojemu očetu Nebukadnezarju kraljestvo, veličanstvo, slavo in čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Zaradi veličanstva, ki mu ga je on dal, so vsa ljudstva, narodi in jeziki trepetali in se bali pred njim. Kogar je želel, je usmrtil; in kogar je želel, je ohranil živega; in kogar je želel, je povišal; in kogar je želel, je odstavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Toda ko je bilo njegovo srce povišano in je njegov um zakrknil v ponosu, je bil odstavljen od svojega kraljevskega prestola in njegovo slavo so odvzeli od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Pregnan je bil izmed človeških sinov in njegovo srce je bilo narejeno kakor živalsko in njegovo prebivališče je bilo z divjimi osli. Hranili so ga s travo kakor vole in njegovo telo je bilo omočeno z roso neba, dokler ni vedel, da najvišji Bog vlada v kraljestvu ljudi in da on postavlja čezenj kogarkoli on želi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ti, njegov sin, oh Belšacár, nisi ponižal svojega srca, čeprav si vse to vedel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'temveč si se povzdignil zoper Gospoda nebes in predte so privedli posode njegove hiše in ti in tvoji velikaši, tvoje žene in tvoje priležnice so iz njih pili vino, in hvalil si bogove iz srebra, zlata, brona, železa, lesa in kamna, ki ne vidijo niti ne slišijo niti ne vedo. Boga pa, v čigar roki je tvoj dih in katerega so vse tvoje poti, ti nisi slavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Torej je bil od njega poslan del roke, in zapisano je bilo to pisanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'To je pisanje, ki je bilo zapisano: MENE, MENE, TEKEL, UPHARSIN.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'To je razlaga stvari: MENE: ›Bog je preštel tvoje kraljestvo in ga končal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'TEKEL: ›Stehtan si bil na tehtnici in si najden pomanjkljiv.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PERES: ›Tvoje kraljestvo je razdeljeno in dano Medijcem in Perzijcem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Potem je Belšacár zapovedal in Daniela so oblekli s škrlatom in okoli njegovega vratu obesili verižico iz zlata in glede njega naredili razglas, da naj bi bil tretji vladar v kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'V tej noči je bil Belšacár, kralj Kaldejcev, umorjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Medijec Darej je dobil kraljestvo; bil je star okoli dvainšestdeset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Dareju je ugajalo, da postavi nad kraljestvo sto dvajset princev, ki naj bi bili nad celotnim kraljestvom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'in nad temi tri predstojnike, od katerih je bil Daniel prvi, da bi jim princi lahko dajali obračun in kralj ne bi trpel nobene škode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Potem je bil ta Daniel povišan nad predstojnike in prince, ker je bil v njem odličen duh, in kralj ga je mislil postaviti nad celotno območje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Potem so predstojniki in princi iskali, da najdejo povod zoper Daniela glede kraljestva, toda niso mogli najti nobenega povoda niti krivde, ker je bil zvest niti ni bilo na njem najti nobene napake ali krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Potem so ti možje rekli: »Nobenega razloga ne bomo našli zoper tega Daniela, razen če zoper njega najdemo to, kar se tiče postave njegovega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Potem so se ti predstojniki in princi zbrali skupaj h kralju in mu rekli takole: »Kralj Darej, živi na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Vsi predstojniki kraljestva, voditelji in princi, svetovalci in poveljniki, smo se skupaj posvetovali, da bi osnovali kraljevo pravilo in da bi naredili trden odlok, da kdorkoli bi prosil prošnjo od kateregakoli Boga ali človeka v tridesetih dneh, razen od tebe, oh kralj, bo vržen v levji brlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Torej, oh kralj, uveljavi odlok in podpiši pisanje, da to ne more biti spremenjeno, glede na postavo Medijcev in Perzijcev, ki se ne predrugači.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Zatorej je kralj Darej podpisal pisanje in odlok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Torej ko je Daniel izvedel, da je bilo pisanje podpisano, je odšel v svojo hišo. Pri svojih oknih v svoji sobi, odprtih proti Jeruzalemu, je trikrat na dan pokleknil na svoja kolena in molil ter se zahvaljeval pred svojim Bogom, kot je to delal poprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Potem so se ti možje zbrali in našli Daniela, kako moli in dela ponižne prošnje pred svojim Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Potem so prišli blizu in pred kraljem spregovorili glede kraljevega odloka: »Mar nisi podpisal odloka, da katerikoli človek, ki bo prosil prošnjo od kateregakoli Boga ali človeka, znotraj tridesetih dni, razen od tebe, oh kralj, bo vržen v levji brlog?« Kralj je odgovoril in rekel: »Stvar je resnična glede na postavo Medijcev in Perzijcev, ki se ne predrugači.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Potem so odgovorili in pred kraljem rekli: »Tisti Daniel, ki je od otrok Judovega ujetništva, te ne upošteva, oh kralj niti odloka, ki si ga podpisal, temveč trikrat na dan opravlja svojo prošnjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Potem je bil kralj, ko je slišal te besede, sam pri sebi boleče nejevoljen in je svoje srce naravnal na Daniela, da ga osvobodi, in do sončnega zahoda se je trudil, da ga osvobodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Potem so se tisti možje zbrali h kralju in kralju rekli: »Vedi, oh kralj, da je postava Medijcev in Perzijcev: ›Da noben odlok niti nobeno pravilo, ki ga je osnoval kralj, ne more biti spremenjeno.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, '§ Potem je kralj ukazal in privedli so Daniela ter ga vrgli v levji brlog. Kralj je torej spregovoril in Danielu rekel: »Tvoj Bog, ki mu nenehno služiš, on te bo osvobodil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Prinesen je bil kamen in položen na odprtino brloga in kralj ga je zapečatil s svojim lastnim pečatom in s pečati svojih gospodov, da se namen glede Daniela ne bi mogel spremeniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, '§ Potem je kralj odšel v svojo palačo in noč prebil v postu niti predenj niso bili prineseni glasbeni instrumenti in njegovo spanje je odšlo od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Potem je kralj zelo zgodaj zjutraj vstal in v naglici odšel k levjemu brlogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Ko je prišel k brlogu, je z žalostnim glasom zaklical k Danielu, in kralj je spregovoril ter Danielu rekel: »Oh Daniel, služabnik živega Boga, ali te je tvoj Bog, ki mu nenehno služiš, mogel osvoboditi pred levi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Potem je Daniel rekel kralju: »Oh kralj, živi na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Moj Bog je poslal svojega angela in zaprl levom usta, da me niso poškodovali, ker je bila v meni najdena nedolžnost pred njim in tudi pred teboj, oh kralj, nisem storil nobene škode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Potem je bil kralj zaradi njega silno vesel in zapovedal, da naj Daniela izvlečejo iz brloga. Tako je bil Daniel vzet gor iz brloga in nobena vrsta poškodbe ni bila najdena na njem, ker je veroval v svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'In kralj je zapovedal in privedli so tiste može, ki so Daniela obtožili in jih vrgli v levji brlog, njih, njihove otroke in njihove žene. Levi so imeli oblast nad njimi in vse njihove kosti so zlomili na koščke, še preden so prileteli na dno brloga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Potem je kralj Darej napisal vsemu ljudstvu, narodom in jezikom, ki prebivajo na vsej zemlji: »Mir naj se vam pomnoži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Naredim odlok: ›Da v vsakem gospostvu mojega kraljestva ljudje trepetajo in se bojijo pred Danielovim Bogom, kajti on je živi Bog in neomajen na veke in njegovo kraljestvo tisto, ki ne bo uničeno in njegovo gospostvo bo celo do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'On osvobaja in rešuje, dela [preroška] znamenja in čudeže v nebesih in na zemlji, ki je Daniela osvobodil pred oblastjo levov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Tako je ta Daniel uspeval v Darejevem kraljevanju in v kraljevanju Perzijca Kira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'V prvem letu babilonskega kralja Belšacárja je imel Daniel sanje in videnja svoje glave na svoji postelji. Potem je sanje zapisal in povedal povzetek stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel je spregovoril in rekel: »Videl sem v svojem videnju ponoči in glej, štirje vetrovi neba so se borili nad velikim morjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Štirje veliki zverniki so prišli iz morja, različni drug od drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Prvi je bil podoben levu in imel je orlove peruti. Gledal sem, dokler niso bile njegove peruti izpuljene in dvignjen je bil z zemlje in primoran stati na stopalih kakor človek, in temu je bilo dano človeško srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Glej še en zvernik, drug, podoben medvedu in ta se je dvignil na eno stran in v ustih, med svojimi zobmi, je imel tri rebra. Rekli so mu takole: ›Vzdigni se, požri veliko mesa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Potem sem zagledal in glej drug, podoben leopardu, ki je imel na svojem hrbtu štiri krila perjadi. Zvernik je imel tudi štiri glave in dano mu je bilo gospostvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Potem sem v nočnih videnjih zagledal in glej četrtega zvernika, groznega, strašnega in silno močnega. Ta je imel velike železne zobe. Požiral je in lomil na koščke in preostanek poteptal s svojimi stopali. Ta je bil različen od vseh zvernikov, ki so bili pred njim, in ta je imel deset rogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Opazoval sem rogove in glej, tam se je med njimi vzdignil drug, majhen rog, pred katerim so bili trije izmed prvih rogov izruvani s koreninami. Glej na tem rogu so bile oči, podobne očem človeka in usta, ki so govorila velike stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Gledal sem, dokler niso bili prestoli zrušeni in se je Starodavni usedel, katerega obleka je bila bela kakor sneg in lasje njegove glave podobni čisti volni. Njegov prestol je bil podoben ognjenemu plamenu in njegova kolesa kakor goreč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Goreč tok je izviral in prihajal izpred njega. Tisoči tisočev so mu služili in desettisočkrat deset tisoči so stali pred njim. Sodba je bila odrejena in knjige so bile odprte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Takrat sem gledal zaradi glasu velikih besed, ki jih je rog spregovoril. Gledal sem, dokler ni bil zvernik pokončan, njegovo telo uničeno in izročeno gorečemu plamenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Glede ostalih zvernikov, njihovo gospostvo jim je bilo odvzeto. Vendar so bila njihova življenja podaljšana za obdobje in čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Videl sem v nočnih videnjih in glej, nekdo, podoben Sinu človekovemu, je prišel z oblaki neba in prišel k Starodavnemu in privedli so ga blizu predenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Dano mu je bilo gospostvo, slava in kraljestvo, da bi mu služila vsa ljudstva, narodi in jeziki. Njegovo gospostvo je večno gospostvo, ki ne bo preminilo in njegovo kraljestvo tisto, ki ne bo uničeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Jaz, Daniel, sem bil užaloščen v svojem duhu v sredi svojega telesa in videnja moje glave so me vznemirila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Približal sem se k tistemu izmed njih, ki je stal poleg in ga vprašal resnico o vsem tem. Tako mi je povedal in mi dal spoznati razlago o stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ti veliki zverniki, ki so štirje, so štirje kralji, ki se bodo vzdignili iz zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Toda Sveti Najvišjega bodo prejeli kraljestvo in kraljestvo bodo obdržali v lasti na veke, celo na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Potem sem želel vedeti resnico o četrtem zverniku, ki je bil različen od vseh ostalih, silno grozen, katerega zobje so bili iz železa in njegovi kremplji iz brona, ki je žrl, lomil na koščke in preostanek poteptal s svojimi stopali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'in o desetih rogovih, ki so bili na njegovi glavi in o drugem, ki se je dvignil in pred katerim so trije padli. Celo o tistem rogu, ki je imel oči in usta, ki so govorila zelo velike stvari, katerega pogled je bil arogantnejši kakor od njegovih tovarišev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Pogledal sem in isti rog je začel vojno s svetimi in prevladal zoper njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'dokler ni prišel Starodavni in je bila sodba dana svetim Najvišjega in je prišel čas, da so sveti vzeli v last kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Tako je rekel: ›Četrti zvernik bo četrto kraljestvo na zemlji, ki bo različno od vseh kraljestev in požrlo bo celotno zemljo in jo pomendralo ter jo zlomilo na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Deset rogov iz tega kraljestva je deset kraljev, ki bodo vstali in drug bo vstal za njimi. Ta bo različen od prvega in podvrgel bo tri kralje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Govoril bo velike besede zoper Najvišjega in izmučil bo svete Najvišjega in mislil, da spremeni čase in postave, oni pa bodo dani v njegovo roko do časa in [dveh] časov in polovice časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'F Toda sodba se bo usedla in odvzeli bodo njegovo gospostvo, da použije in da ga uniči do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Kraljestvo, gospostvo in veličina kraljestva pod celotnim nebom bo dano ljudstvu svetih Najvišjega, katerega kraljestvo je večno kraljestvo in vsa njegova gospostva mu bodo služila in ga ubogala.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Do zdaj je konec zadeve. Kar se tiče mene, Daniela, me je moje poglobljeno razmišljanje zelo vznemirilo in moje obličje na meni je bilo spremenjeno, toda zadevo sem obdržal v svojem srcu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'V tretjem letu kraljevanja kralja Belšacárja se mi je prikazalo videnje, celo meni, Danielu, po tistem, ki se mi je prikazalo najprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Videl sem v videnju in pripetilo se je, ko sem gledal, da sem bil v [mestu] Suze, v palači, ki je v provinci Elám, in videl sem v videnju in bil sem pri reki Uláj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Potem sem povzdignil svoje oči, videl in glej, tam pred reko je stal oven, ki je imel dva rogova in dva rogova sta bila visoka. Toda eden je bil višji kakor drug in višji je prišel zadnji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Videl sem ovna bosti proti zahodu in proti severu in proti jugu, tako, da noben zvernik ni mogel stati pred njim niti tam ni bilo nikogar, ki bi ga lahko osvobodil iz njegove roke, temveč je počel glede na svojo voljo in postal velik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Ko sem preudarjal, glej, je od zahoda prišel kozel na obličje celotne zemlje, tal pa se ni dotaknil, in kozel je imel med svojimi očmi opazen rog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Ta je prišel k ovnu, ki je imel dva rogova, ki sem ga videl stati pred reko in stekel k njemu v razjarjenosti svoje moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Videl sem ga približevati se ovnu in prevzet je bil z gnevom zoper njega in udaril ovna ter zlomil dva njegova rogova. V ovnu pa ni bilo moči, da stoji pred njim, temveč ga je vrgel dol k tlom in ga poteptal, in nikogar ni bilo, ki bi mogel ovna osvoboditi iz njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Zato je kozel postal zelo velik, in ko je bil močan, je bil veliki rog zlomljen in za tem so prišli gor štirje opazni, [razdeljeni] proti štirim vetrovom neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Iz enega izmed njih je prišel majhen rog, ki je postal silno velik, proti jugu in proti vzhodu in proti prijetni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Ta je postal velik, celó do nebeške vojske, in ta je vrgel dol nekatere izmed vojske in od zvezd k tlom in poteptal nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Da, poveličeval je samega sebe, celo do princa vojske in z njim je bilo odvzeto dnevno žrtvovanje in prostor njegovega svetišča je bil vržen dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'In dana mu je bila vojska zoper dnevno žrtvovanje zaradi razloga prestopka in ta je vrgel resnico dol k tlom in to izvedel in uspel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Potem sem zaslišal nekega svetega govoriti in drugi sveti je rekel temu nekemu svetemu, ki je govoril: »Doklej bo videnje glede dnevnega žrtvovanja in prestopka zapuščenosti, da bosta tako svetišče kakor vojska pogažena pod stopalom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Rekel mi je: »Do dva tisoč tristo dni, potem bo svetišče očiščeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Pripetilo se je, ko sem jaz, celó jaz, Daniel, videl videnje in si prizadeval najti pomen, potem, glej, je tam pred menoj stal kakor videz moža.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Zaslišal sem človeški glas med bregovoma Ulája, ki je zaklical in rekel: »Gabriel, stôri temu človeku, da razume videnje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Tako se je približal, kjer sem stal. Ko je prišel, sem bil prestrašen in padel na svoj obraz, toda rekel mi je: »Razumi, oh človeški sin, kajti videnje bo ob času konca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Torej, ko je govoril z menoj, sem bil v globokem spanju, s svojim obrazom proti tlom, toda dotaknil se me je in me postavil pokonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Rekel je: »Glej, dal ti bom spoznati kaj bo v zadnjem koncu ogorčenja, kajti ob določenem času bo konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Oven, ki si ga videl, ki je imel dva rogova, sta kraljestvi Medije in Perzije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Razmršen kozel je kralj Grčije, in velik rog, ki je med njegovimi očmi, je prvi kralj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Torej ta je bil zlomljen, medtem ko so štirje vstali namesto tega; štiri kraljestva bodo vstala iz naroda, toda ne v njegovi moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'V zadnjem času njihovega kraljestva, ko pridejo prestopniki v polni meri, bo vstal kralj krutega obličja in razumevanja temnih razsodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Njegova moč bo mogočna, toda ne z njegovo lastno močjo. Ta bo izvrstno uničeval in uspeval bo in izvedel in uničil bo mogočnega in sveto ljudstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Zaradi svoje strategije bo tudi povzročil, da bo prebrisanost uspevala v njegovi roki, in poveličeval se bo v svojem srcu in z mirom bo uničil mnoge. Stal bo tudi zoper Princa princev, toda zlomljen bo brez roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Videnje večera in jutra, ki je bilo povedano, je resnično. Zato zastri videnje, kajti to bo za mnoge dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Jaz, Daniel, sem bil nekaj dni slaboten in bolan. Potem sem se dvignil in opravljal kraljeva opravila, bil pa sem osupel nad videnjem, toda nihče ga ni razumel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'V prvem letu Dareja, sina Ahasvérja, iz rodu Medijcev, ki je bil postavljen za kralja nad območjem Kaldejcev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'v prvem letu njegovega kraljevanja sem jaz, Daniel, po knjigah razumel število let, o čemer je Gospodova beseda prišla preroku Jeremiju, da bo dovršil sedemdeset let v opustošenjih Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Svoj obraz sem naravnal h Gospodu Bogu, da [ga] iščem z molitvijo, ponižnimi prošnjami, postom, vrečevino in pepelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Molil sem h Gospodu, svojemu Bogu in naredil svoje priznanje ter rekel: »Oh Gospod, velik in grozen Bog, ki ohranja zavezo in usmiljenje tistim, ki ga ljubijo in tistim, ki se držijo njegovih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Grešili smo in zagrešili krivičnost, počeli zlobno in se uprli, celo z odhajanjem od tvojih predpisov in od tvojih sodb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Niti nismo prisluhnili tvojim služabnikom prerokom, ki so v tvojem imenu govorili našim kraljem, našim princem in našim očetom in vsemu ljudstvu dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Oh Gospod, pravičnost pripada tebi, toda nam zmešnjava obrazov, kakor na ta dan; možem iz Juda in prebivalcem Jeruzalema in vsemu Izraelu, ki so blizu in ki so daleč, po vseh deželah, kamor si jih pognal zaradi njihovega prekrška, ki so ga zagrešili zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Oh Gospod, nam pripada osramotitev obrazov, našim kraljem, našim princem in našim očetom, ker smo grešili zoper tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Gospodu, našemu Bogu, pripadajo usmiljenja in odpuščanja, čeprav smo grešili zoper njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'niti se nismo pokoravali glasu Gospoda, svojega Boga, da se ravnamo po njegovih postavah, ki jih je postavil pred nami po svojih služabnikih prerokih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Da, ves Izrael je prekršil pravila tvoje postave, celo z odhajanjem, da ne bi ubogali tvojega glasu. Zato je nad nas izlito prekletstvo in prisega, ki je zapisana v postavi Božjega služabnika Mojzesa, ker smo grešili zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'In on je potrdil svoje besede, ki jih je govoril zoper nas in zoper naše sodnike, ki so nas sodili, s tem, da je nad nas privedel veliko zlo, kajti pod celotnim nebom se ni zgodilo, kakor se je zgodilo nad Jeruzalemom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Kakor je to zapisano v Mojzesovi postavi, je vse to zlo prišlo nad nas, vendar nismo opravili svoje molitve pred Gospodom, svojim Bogom, da bi se lahko obrnili od svojih krivičnosti in razumeli tvojo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Zato je Gospod bedel nad zlom in ga privedel nad nas, kajti Gospod, naš Bog, je pravičen v vseh svojih delih, ki jih počne, kajti nismo ubogali njegovega glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Sedaj, oh Gospod, naš Bog, ki si svoje ljudstvo z mogočno roko privedel iz egiptovske dežele in si si pridobil ugled kakor na ta dan; grešili smo, počeli smo zlobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Oh Gospod, glede na vso tvojo pravičnost te rotim, naj bo tvoja jeza in tvoja razjarjenost obrnjena proč od tvojega mesta, Jeruzalema, tvoje svete gore, ker so zaradi naših grehov in zaradi krivičnosti naših očetov Jeruzalem in tvoje ljudstvo postali graja vsem, ki so okoli nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Zdaj torej, oh naš Bog, prisluhni molitvi svojega služabnika in njegovim ponižnim prošnjam in povzroči svojemu obrazu, da zasije nad tvojim svetiščem, ki je zapuščeno zaradi Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Oh moj Bog, nagni svoje uho in prisluhni. Odpri svoje oči in glej naša opustošenja in mesto, ki je imenovano s tvojim imenom, kajti ne predstavljamo svojih ponižnih prošenj pred teboj zaradi svoje pravičnosti, temveč zaradi tvojih velikih usmiljenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Oh Gospod, prisluhni; oh Gospod, odpusti; oh Gospod, prisluhni in stôri. Ne odlašaj zaradi sebe, oh moj Bog, kajti tvoje mesto in tvoje ljudstvo se imenujeta po tvojem imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Medtem ko sem govoril in molil ter priznaval svoj greh in greh svojega ljudstva Izraela in predstavljal svojo ponižno prošnjo pred Gospodom, svojim Bogom, za sveto goro svojega Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'da, medtem ko sem govoril v molitvi, je celo mož Gabriel, ki sem ga videl v videnju na začetku, naglo priletel in se me dotaknil ob času večerne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Poučil me je, govoril z menoj in rekel: »Oh Daniel, sedaj sem prišel, da ti dam znanje in razumevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Na začetku tvoje ponižne prošnje je prišla zapoved in prišel sem, da se ti pokažem, kajti ti si silno ljubljen, zato razumi zadevo in preudari videnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sedemdeset tednov je določenih nad tvojim ljudstvom in nad tvojim svetim mestom, da preneha prestopek in se naredi konec grehom in se naredi pobotanje za krivičnost in da se vpelje večna pravičnost in se zapečatita videnje in prerokovanje in da se mazili Najsvetejše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Vedi torej in razumi, da bo od izida zapovedi, da se obnovi in zgradi Jeruzalem, do Mesija, Princa, sedem tednov in dvainšestdeset tednov. Ulica bo ponovno zgrajena in obzidje, celo v težkih časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, '§ Po dvainšestdesetih tednih bo Mesija usmrčen, toda ne zaradi sebe; in ljudstvo princa, ki bo prišlo, bo uničilo mesto in svetišče. Njegov konec bo s poplavo in do konca so določena vojna opustošenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, '§ Potrdil bo to zavezo z mnogimi za en teden. In v sredi tedna bo povzročil, da bo klavna daritev in jedilna daritev prenehala in zaradi razširjanja ogabnosti bo on to opustošil, celo do použitja in to določeno bo izlito na opustošenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, '§ V tretjem letu perzijskega kralja Kira je bila stvar razodeta Danielu, katerega ime je bilo imenovano Beltšacár. Stvar je bila resnična, toda določeni čas je bil dolg, in razumel je stvar in imel je razumevanje videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'V tistih dneh sem jaz, Daniel, žaloval tri polne tedne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Nisem jedel nobenega prijetnega kruha, niti ni prišlo v moja usta meso, niti vino, niti se sploh nisem mazilil, dokler niso bili izpolnjeni dnevi treh tednov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, '§ Na štiriindvajseti dan prvega meseca, medtem ko sem bil ob bregu velike reke, ki je Hidekel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, '§ takrat sem povzdignil svoje oči in pogledal in glej, neki mož, oblečen v platno, čigar ledja so bila opasana s finim zlatom iz Ufaza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Tudi njegovo telo je bilo podobno berilu in njegov obraz kakor videz bliskanja in njegove oči kakor ognjene svetilke in njegovi lakti in njegova stopala podobna barvi zloščenega brona in glas njegovih besed podoben glasu množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Samo jaz, Daniel, sem videl videnje, kajti ljudje, ki so bili z menoj, videnja niso videli, toda nanje je padlo veliko drgetanje, tako da so zbežali, da se poskrijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, '§ Torej sem ostal sam in gledal to veliko videnje in v meni ni ostalo nobene moči, kajti moja ljubkost je bila v meni spremenjena v pokvarjenost in nobene moči nisem ohranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Vendar sem zaslišal glas njegovih besed. Ko sem poslušal glas njegovih besed, sem bil potem v globokem spanju na svojem obrazu in s svojim obrazom proti tlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Glej, dotaknila se me je roka, ki me je postavila na moja kolena in na dlani mojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Rekel mi je: »Oh Daniel, silno ljubljen mož, razumi besede, ki ti jih govorim in stoj pokončno, kajti sedaj sem poslan k tebi.« In ko mi je govoril to besedo, sem trepetajoč stal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Potem mi je rekel: »Ne boj se, Daniel, kajti od prvega dne, ko si pripravil svoje srce k razumevanju in da se ponižaš pred svojim Bogom, so bile tvoje besede uslišane in prišel sem zaradi tvojih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, '§ Toda princ perzijskega kraljestva se mi je zoperstavljal enaindvajset dni. Toda glej, prišel je Mihael, eden izmed glavnih princev, da mi pomaga, in ostal sem tam s perzijskimi kralji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Sedaj sem prišel, da ti dam razumevanje, kaj bo doletelo tvoje ljudstvo v zadnjih dneh, kajti videnje je še za mnoge dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Ko mi je govoril takšne besede, sem pobesil svoj obraz proti tlom in postal nem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Glej, nekdo podoben človeškim sinovom, se je dotaknil mojih ustnic. Potem sem odprl svoja usta in spregovoril ter rekel temu, ki je stal pred menoj: »Oh moj gospod, po videnju so se moje bridkosti obrnile k meni in nisem ohranil nobene moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Kajti kako lahko služabnik tega mojega gospoda govori s tem mojim gospodom? Kajti kar se mene tiče, nemudoma v meni ni ostalo nobene moči niti v meni ni ostalo diha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Potem je ponovno prišel in se me dotaknil nekdo, podoben videzu človeka, me okrepil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'in rekel: »Oh silno ljubljeni mož, ne boj se. Mir ti bodi, bodi močan, da, bodi močan.« Ko mi je govoril, sem bil okrepljen in rekel [sem]: »Naj moj gospod govori, kajti okrepil si me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Potem je rekel: »Ali veš zakaj sem prišel k tebi? Sedaj se bom vrnil, da se borim s princem Perzije. Ko odidem, glej, bo prišel princ Grčije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Toda pokazal ti bom to, kar je zabeleženo v pismu resnice, in tam ni nikogar, ki drži z menoj v teh stvareh, razen Mihaela, vašega princa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Tudi jaz sem v prvem letu Medijca Dareja, celó jaz, stal, da ga potrdim in okrepim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, '§ Sedaj ti bom pokazal resnico: »Glej, v Perziji bodo vstali še trije kralji, četrti pa bo mnogo bogatejši kakor oni vsi. S svojo močjo bo po svojih bogastvih vse razvnel zoper področje Grčije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Vstal bo mogočen kralj, ki bo vladal z velikim gospostvom in počel glede na svojo voljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Ko bo vstal, bo njegovo kraljestvo zlomljeno in razdeljeno bo proti štirim vetrovom neba, in ne k njegovemu potomstvu niti glede na njegovo gospostvo, ki mu je vladal, kajti njegovo kraljestvo bo izpuljeno, celo za druge poleg teh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Južni kralj bo močan in eden izmed njegovih princev in on bo močan nad njim in imel bo gospostvo; njegovo gospostvo bo veliko gospostvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, '§ Ob koncu let se bosta združila skupaj, kajti kraljeva hči iz juga bo prišla k severnemu kralju, da sklene dogovor. Toda ona ne bo obdržala moči lakta niti on ne bo obstal niti njegov laket, temveč bo izdana in tisti, ki so jo privedli in tisti, ki jo je zaplodil in kdor jo je okrepil v teh časih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Toda iz mladike njenih korenin bo vstal nekdo v svoji lastnini, ki bo prišel z vojsko in vstopil v trdnjavo severnega kralja in se bo spoprijel zoper njih in bo prevladal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, '§ Prav tako bo ujete odvedel v Egipt njihove bogove z njihovimi princi in z njihovimi dragocenimi posodami iz srebra in zlata, in nadaljeval bo več let kakor kralj iz severa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Tako bo južni kralj prišel v svoje kraljestvo in se bo vrnil v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Toda njegova sinova bosta razvneta in bosta zbrala množico velikih sil, in nekdo bo zagotovo prišel, preplavil in šel skozi. Potem se bo vrnil in bo razvnet, celó do svoje trdnjave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Južni kralj bo prevzet z gnevom in prišel bo in se boril z njim, celó s severnim kraljem, in postavil bo veliko množico, toda množica bo dana v njegovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'In ko bo odvedel množico, bo njegovo srce povzdignjeno in podrl bo mnogo deset tisočev, toda s tem ne bo okrepljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Kajti severni kralj se bo vrnil in vzpostavil množico, večjo kakor prejšnja in zagotovo bo prišel čez določena leta z veliko vojsko in z mnogimi bogastvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'V tistih časih bodo mnogi vstali zoper južnega kralja. Tudi roparji tvojega ljudstva se bodo povišali, da vzpostavijo videnje; vendar bodo padli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Tako bo prišel severni kralj in nasul nasip in zavzel najbolj utrjena mesta, in orožje iz juga se ne bo zoperstavilo niti njegovo izvoljeno ljudstvo niti ne bo nobene moči, da se zoperstavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Toda tisti, ki prihaja zoper njega, bo storil glede na svojo lastno voljo in nihče ne bo obstal pred njim. Ta pa bo stal v veličastni deželi, ki bo z njegovo roko použita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, '§ Svoj obraz bo tudi naravnal, da vstopi z močjo svojega celotnega kraljestva in pokončni z njim. Tako bo storil. Dal mu bo hčer izmed žensk, kvareč jo, toda ona ne bo obstala na njegovi strani niti ne bo zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Potem bo svoj obraz obrnil k otokom in bo mnoge zavzel, toda princ bo zaradi svoje koristi povzročil, da bo zasramovanje, ki ga je ta dajal, prenehalo. Brez njegovega lastnega zasramovanja mu bo povzročil, da se to obrne nadenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Potem bo svoj obraz obrnil proti utrdbi svoje lastne dežele, toda spotaknil se bo, padel in ne bo najden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Potem bo v svoji lastnini vstal prenašalec davkov v slavi kraljestva, toda v nekaj dneh bo uničen, niti z jezo, niti v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'V njegovi lastnini bo vstala podla oseba, ki ji ne bodo dali časti kraljestva, toda vstopil bo miroljubno in kraljestvo dosegel z laskanji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, '§ S silami poplave bodo odplavljeni izpred njega in bodo zlomljeni; da, tudi princ zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Potem ko z njim sklene sodelovanje, bo postopal varljivo, kajti prišel bo gor in postal močan z majhnim ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Vstopil bo miroljubno, celo na najrodovitnejše kraje province. Počel bo to, kar njegovi očetje niso storili niti očetje njihovih očetov. Mednje bo razkropil plen, oplenjeno in bogastva. Da, napovedal bo svoje naklepe zoper oporišča, celo za nekaj časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Z veliko vojsko bo razvnel svojo moč in svoj pogum zoper južnega kralja, in južni kralj bo razvnet v bitko z veliko in mogočno vojsko, toda ne bo obstal, kajti zoper njega bodo napovedali naklepe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Da, tisti, ki se hranijo od deleža njegove hrane, ga bodo uničili in njegova vojska se bo razkropila. Mnogi bodo popadali umorjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Srci obeh teh kraljev bosta počeli vragolijo in pri eni mizi bosta govorila laži. Toda to ne bo uspelo, kajti vendar bo konec ob določenem času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Potem se bo vrnil v svojo deželo z velikimi bogastvi, in njegovo srce bo zoper sveto zavezo. Počel bo junaška dejanja in se vrnil v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Ob določenem času se bo vrnil in prišel proti jugu, toda ta ne bo kakor prejšnji ali kakor zadnji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Kajti ladje Kitéjcev bodo prišle zoper njega. Zato bo užaloščen, se vrnil in bo ogorčen zoper sveto zavezo. Tako bo storil; torej vrnil se bo in imel posvet s tistimi, ki so zapustili sveto zavezo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, '§ Sile bodo stopile na njegovo stran in oskrunili bodo svetišče moči in odpravili bodo dnevno daritev in postavili ogabnost, ki dela opustošenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Tiste, ki zlobno ravnajo zoper zavezo, bo pokvaril z laskanji, toda ljudstvo, ki pozna svojega Boga, bo močno in delalo bo junaška dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Tisti med ljudstvom, ki razumejo, bodo poučevali mnoge, vendar bodo padali pod mečem in v plamenu, v ujetništvu in po plenjenju, mnogo dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Torej ko bodo padali, jim bo pomagano z majhno pomočjo, toda mnogi se jih bodo oklenili z laskanji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Nekateri izmed tistih z razumevanjem bodo padli, da se jih preizkusi in prečisti in se jih naredi bele, celó do časa konca, ker je to še za določeni čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Kralj pa bo počel glede na svojo voljo in poviševal se bo in se poveličeval nad vsakega boga in govoril bo osupljive stvari zoper Boga bogov in uspeval bo, dokler ne bo dovršeno ogorčenje, kajti to, kar je določeno, bo storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Niti se ne bo oziral na Boga svojih očetov, niti na željo žensk, niti na kateregakoli boga, kajti poveličeval se bo nad vse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Toda v svoji lastnini bo spoštoval boga sil, in boga, ki ga njegovi očetje niso poznali, bo častil z zlatom, srebrom, dragocenimi kamni in prijetnimi stvarmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, '§ Tako bo storil v najmočnejših oporiščih s tujim bogom, ki ga bo priznal in narastel s slavo. Povzročil jim bo, da vladajo nad mnogimi in deželo bo razdelil zaradi dobička.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Ob času konca bo južni kralj pritisnil nanj in severni kralj bo prišel proti njemu kot vrtinčast veter, z bojnimi vozovi in s konjeniki in z mnogimi ladjami in vstopil bo v dežele, jih preplavil in prešel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Vstopil bo tudi v veličastno deželo in mnoge dežele bodo premagane, toda te bodo pobegnile iz njegove roke, celó Edóm, Moáb in vodja Amónovih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Svojo roko bo iztegnil tudi nad dežele in egiptovska dežela ne bo ubežala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Toda imel bo oblast nad zakladi iz zlata, srebra in nad vsemi dragocenimi egiptovskimi stvarmi in Libijci in Etiopijci bodo pri njegovih korakih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Toda novice iz vzhoda in iz severa ga bodo vznemirile, zato bo šel naprej z veliko razjarjenostjo, da uniči in popolnoma odpravi mnoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Zasadil bo šotorska svetišča svoje palače med morjem in veličastno sveto goro, vendar bo prišel do svojega konca in nihče mu ne bo pomagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Ob tistem času bo vstal Mihael, veliki princ, ki stoji za otroke tvojega ljudstva in tam bo čas stiske, tak, kakršnega ni bilo, odkar je bil tam narod, celó do tega istega časa. In ob tistem času bo tvoje ljudstvo osvobojeno, vsak, kdor bo najden zapisan v knjigi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Mnogi izmed teh, ki spijo v prahu zemlje, se bodo zbudili, nekateri za večno življenje, nekateri pa za sramoto in večno zaničevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Tisti, ki so modri, bodo svetili kakor sijaj nebesnega svoda in tisti, ki mnoge obračajo k pravičnosti, [bodo] kakor zvezde na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, '§ Toda ti, oh Daniel, zakleni besede in zapečati knjigo, celó do časa konca. Mnogi bodo tekali sem ter tja in spoznanje se bo povečalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Potem sem jaz, Daniel, pogledal in glej tam sta stala druga dva, eden na tej strani rečnega brega, drugi pa na drugi strani rečnega brega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'In eden je rekel možu, oblečenemu v lan, ki je bil na vodah reke: »Doklej bo to do konca teh čudežev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Slišal sem moža, oblečenega v lan, ki je bil na vodah reke, ko je držal svojo desno roko in svojo levo roko k nebu in prisegel pri njem, ki živi na veke, da bo to za čas, [dva] časa in polovico, in ko bo dovršil, da razkropi moč svetega ljudstva, se bodo vse te stvari končale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Slišal sem, toda nisem razumel. Potem sem rekel: »Oh moj Gospod, kakšen bo konec teh stvari?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Rekel je: »Pojdi svojo pot, Daniel, kajti besede so zaklenjene in zapečatene do časa konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Mnogi bodo očiščeni, pobeljeni in preizkušeni, toda zlobni bodo delali zlobno in nihče izmed zlobnih ne bo razumel, toda modri bodo razumeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Od časa, ko bo dnevno žrtvovanje odvzeto in postavljena ogabnost, ki dela opustošenje, bo tisoč dvesto devetdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Blagoslovljen je kdor čaka in prihaja k tisoč tristo petintridesetim dnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Toda ti pojdi svojo pot, dokler ne bo konec, kajti počival boš in stal v svojem deležu ob koncu dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Gospodova beseda, ki je prišla Beeríjevemu sinu Ozeju v dneh Uzíjaha, Jotáma, Aháza in Ezekíja, Judovih kraljev in v dneh Joáševega sina Jerobeáma, Izraelovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Začetek Gospodove besede po Ozeju. Gospod je Ozeju rekel: »Pojdi, vzemi si ženo vlačugarstev in otroke vlačugarstev, kajti dežela je zagrešila veliko vlačugarstvo, odhajajoč od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Torej je odšel in vzel Diblájimovo hčer Gómero, ki je spočela in mu rodila sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Gospod mu je rekel: »Njegovo ime kliči Jezreél, kajti le še malo in jaz bom maščeval kri Jezreéla na Jehújevi hiši in povzročil bom, da bo prenehalo kraljestvo Izraelove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Na ta dan se bo zgodilo, da bom Izraelov lok zlomil v dolini Jezreél.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, '§ Ponovno je spočela in rodila hčer. Bog mu je rekel: »Njeno ime kliči Nepomiloščena, kajti ne bom več imel milosti nad Izraelovo hišo, temveč jih bom popolnoma odvedel stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Toda imel bom usmiljenje nad Judovo hišo in rešil jih bom po Gospodu, njihovem Bogu in ne bom jih rešil z lokom, niti z mečem, niti z bitko, [niti] s konji, niti s konjeniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Torej, ko je odstavila Nepomiloščeno, je spočela in rodila sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Potem je Bog rekel: »Njegovo ime kliči Ne-moje-ljudstvo, kajti vi niste moje ljudstvo in jaz ne bom vaš Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Vendar bo število Izraelovih otrok kakor morskega peska, ki ne more biti izmerjen niti preštet in zgodilo se bo, da jim bo na kraju, kjer jim je bilo rečeno: ›Vi niste moje ljudstvo,‹ tam jim bo rečeno: › Vi ste sinovi živega Boga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Potem bodo Judovi otroci in Izraelovi otroci zbrani skupaj in določili si bodo eno glavo in prišli bodo gor iz dežele, kajti velik bo Jezreélov dan.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Svojim bratom recite: ›Moje ljudstvo‹ in svojim sestram: ›Pomiloščena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Pravdajte se s svojo materjo, pravdajte, kajti ona ni moja žena niti jaz nisem njen soprog. Naj torej odloži svoja vlačugarstva iz svojega pogleda in svoja zakonolomstva izmed svojih prsi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'da je ne bom slekel do golega in jo postavil kakor na dan, ko je bila rojena in jo naredil kakor divjino in jo postavil kakor suho deželo in jo pogubil z žejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Ne bom se usmilil njenih otrok, kajti oni so otroci vlačugarstev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Kajti njihova mati je igrala pocestnico. Ta, ki jih je spočela, je storila sramotno, kajti rekla je: ›Hodila bom za svojimi ljubimci, ki mi dajejo moj kruh in mojo vodo, mojo volno in moj lan, moje olje in mojo pijačo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Zatorej glej, tvojo pot bom ogradil s trnjem in naredil zid, da ne bo našla svojih steza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Sledila bo za svojimi ljubimci, toda ne bo jih dohitela in iskala jih bo, toda ne bo jih našla. Tedaj bo rekla: ›Šla bom in se vrnila k svojemu prvemu soprogu, kajti takrat je bilo z menoj bolje kakor sedaj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Kajti ni vedela, da sem ji jaz dajal njeno žito, vino, olje in množil njeno srebro in zlato, ki so ga pripravili za Báala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Zatorej se bom vrnil in odvzel svoje žito ob njegovem času in svoje vino v njegovem obdobju in nazaj bom dobil svojo volno in svoj lan, izročen, da pokrije njeno nagoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Sedaj bom odkril njeno nespodobnost pred očmi njenih ljubimcev in nihče je ne bo rešil iz moje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Prav tako bom vsemu njenemu veselju povzročil, da bo prenehalo, njenim prazničnim dnevom, njenim mlajem, njenim šabatom in vsem njenim slovesnim praznikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Uničil bom njene trte in njena figova drevesa, o katerih je rekla: ›To so moje nagrade, ki so mi jih dajali moji ljubimci.‹ Jaz pa jih bom naredil za gozd in živali polja jih bodo jedle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Na njej bom obiskal dneve Báalov, na katere jim je zažigala kadilo in se krasila s svojimi uhani in svojimi dragocenostmi in hodila za svojimi ljubimci, mene pa pozabila,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, '»Zatorej glej, jaz jo bom privabil in jo pripeljal v divjino in ji tolažilno prigovarjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Jaz ji bom od tam dal njene vinograde in dolino Ahór za vrata upanja in ona bo tam prepevala kakor v dneh svoje mladosti in kakor na dan, ko je prišla gor iz egiptovske dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'In zgodilo se bo tisti dan,« govori Gospod, » da me boš klicala: ›Ishi‹ in ne boš me več klicala: ›Báali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Kajti odstranil bom imena Báalov iz njenih ust in po njihovem imenu se jih ne bodo več spominjali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, '§ Na ta dan bom zanje sklenil zavezo s poljskimi živalmi, s perjadjo neba in s plazečimi stvarmi zemlje. Prelomil bom lok, meč in bitko z zemlje in storil jim bom, da se varno zleknejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'In zaročil te bom k sebi za vedno. Da, zaročil te bom k sebi v pravičnosti, v sodbi, v ljubeči skrbnosti in v milostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Zaročil te bom k sebi, celo v zvestobi in spoznala boš Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Zgodilo se bo na tisti dan; uslišal bom,« govori Gospod, »uslišal bom nebo in to bo uslišalo zemljo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'in zemlja bo uslišala žito in vino in olje in ti bodo uslišali Jezreéla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Posejal si jo bom na zemlji in usmilil se bom nje, ki ni dosegla usmiljenja in rekel bom tistim, ki niso bili moje ljudstvo: ›Vi ste moje ljudstvo.‹ In oni bodo rekli: › Ti si moj Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Potem mi je Gospod rekel: »Pojdi že, ljubi žensko, ljubljeno od njenega prijatelja, vendar zakonolomko, glede na Gospodovo ljubezen do Izraelovih otrok, ki gledajo k drugim bogovom in ljubijo flaškone vina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Tako sem si jo kupil za petnajst koščkov srebra in za tovor ječmena in pol tovora ječmena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Rekel sem ji: »Mnogo dni boš čakala name. Ne boš igrala pocestnice in ne boš za drugega moškega; tako bom tudi jaz nate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, '§ Kajti Izraelovi otroci bodo mnogo dni ostali brez kralja, brez princa, brez klavne daritve, brez podobe, brez efóda in brez družinskega malika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, '§ Potem se bodo Izraelovi otroci vrnili in iskali Gospoda, svojega Boga in Davida, svojega kralja in bali se bodo Gospoda in njegove dobrote v zadnjih dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Poslušajte Gospodovo besedo, vi Izraelovi otroci, kajti Gospod ima polemiko s prebivalci dežele, zato ker tam ni resnice niti usmiljenja niti spoznanja Boga v deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'S priseganjem, laganjem, ubijanjem, krajo in zagrešitvami zakonolomstva so izbruhnili in kri se dotika krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Zato bo dežela žalovala in kdor v njej prebiva bo opešal, z živalmi polja in s perjadjo neba. Da, tudi ribe morja bodo odvzete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Vendarle naj se noben človek ne prepira niti naj ne graja drugega, kajti tvoje ljudstvo je kakor tisti, ki se prepirajo z duhovnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, '»Zato boš padel podnevi in tudi prerok bo padel s teboj ponoči in jaz bom uničil tvojo mater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Moje ljudstvo je uničeno zaradi pomanjkanja spoznanja. Ker si zavrnil spoznanje, bom tudi jaz zavrnil tebe, da mi ne boš duhovnik. Ker si pozabil postavo svojega Boga, bom tudi jaz pozabil tvoje otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Kakor so bili pomnoženi, tako so grešili zoper mene, zato bom njihovo slavo spremenil v sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, '§ Jedo greh mojega ljudstva in svoja srca naravnavajo na svojo krivičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'In tam bo, kakršno ljudstvo, takšen duhovnik, in jaz jih bom kaznoval za njihove poti in jim nagradil njihova početja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Kajti jedli bodo, pa ne bodo imeli dovolj, zagrešili bodo vlačugarstvo, pa se ne bodo pomnožili, ker so opustili, da bi bili pozorni na Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Vlačugarstvo, vino in novo vino jemljejo srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Moje ljudstvo sprašuje za nasvet pri svojih kladah in njihova palica jim napoveduje, kajti duh vlačugarstev jim je povzročil, da blodijo in odšli so se vlačugat proč izpred svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Žrtvujejo na vrhovih gora in kadilo zažigajo na hribih, pod hrasti, topoli in bresti, ker je njihova senca dobra. Zatorej bodo vaše hčere zagrešile vlačugarstvo in vaše snahe bodo zagrešile zakonolomstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Ne bom kaznoval vaših hčera, ko bodo zagrešile vlačuganje niti vaših snah, kadar bodo zagrešile zakonolomstvo, kajti oni sami so oddvojeni z vlačugami in žrtvujejo s pocestnicami. Zatorej bo ljudstvo, ki ne razume, padlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Čeprav ti, Izrael, igraš pocestnico, naj vendar Juda ne greši. Ne prihajajte v Gilgál, niti ne hodite gor v Bet Aven, niti ne prisegajte: › Gospod živi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Kajti Izrael drsi nazaj kakor nazaj zdrknjena telica. Sedaj jih bo Gospod pasel kakor jagnje na velikem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efrájim je pridružen malikom, pusti ga samega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, '§ Njihova pijača je kisla. Spet in spet zagrešujejo vlačugarstvo. Njegovi vladarji ljubijo s sramoto: ›Dajajte.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Veter je [Izraela] zvezal v svoje peruti in osramočeni bodo zaradi svojih [klavnih] daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Poslušajte to, oh duhovniki in pazljivo prisluhnite, vi, Izraelova hiša in nagnite uho, oh kraljeva hiša, kajti sodba je zoper vas, ker ste bili zanka na Micpi in mreža, razpeta na [gori] Tabor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, '§ Puntarji so prodorni, da naredijo pokol, čeprav sem bil jaz oštevalec njih vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Poznam Efrájima in Izrael ni skrit pred menoj, kajti sedaj, oh Efrájim, zagrešuješ vlačugarstvo in Izrael je omadeževan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Svojih ravnanj ne bodo snovali, da bi se obrnili k svojemu Bogu, kajti duh vlačugarstev je v njihovi sredi in niso spoznali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Izraelov ponos pričuje v njegov obraz, zatorej bosta Izrael in Efrájim padla v svoji krivičnosti. Tudi Juda bo padel z njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Šli bodo s svojimi tropi in s svojimi čredami, da bi iskali Gospoda, toda ne bodo ga našli. On se je oddaljil od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Zahrbtno so ravnali zoper Gospoda, kajti zaplodili so tuje otroke. Sedaj jih bo požrl mesec z njihovimi deleži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Zatrobite na kornét v Gíbei in na trobento v Rami, kričite glasno pri Bet Avenu, za teboj, oh Benjamin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efrájim bo zapuščen na dan oštevanja. Med Izraelovimi rodovi sem dal spoznati tisto, kar zagotovo bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Judovi princi so bili kakor tisti, ki odstranjujejo mejo, zatorej bom nanje izlil svoj bes kakor vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efrájim je zatiran in razklan na sodbi, zato ker je voljan hodil za [človeško] zapovedjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, '»Zato bom Efrájimu kakor molj, Judovi hiši pa kakor gniloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Ko je Efrájim videl svojo slabost in Juda videl svojo rano, takrat je šel Efrájim k Asircu in poslal h kralju Jarebu in vendar vas on ni mogel ozdraviti niti ozdraviti vaše rane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Kajti jaz bom Efrájimu kakor lev in kakor mlad lev Judovi hiši. Jaz, celó jaz, bom raztrgal in odšel proč, jaz bom odnesel in nihče ga ne bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Šel bom in se vrnil na svoj kraj, dokler ne bodo priznali svojega prestopka in iskali mojega obraza. V svoji stiski me bodo zgodaj iskali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Pridite in vrnimo se h Gospodu, kajti on je raztrgal in on nas bo ozdravil. Udaril je in nas bo obvezal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Po dveh dneh nas bo oživil, v tretjem dnevu nas bo dvignil in živeli bomo v njegovem pogledu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Takrat bomo vedeli ali še naprej sledimo, da bi spoznali Gospoda; njegov izhod je pripravljen kakor jutro in prišel bo k nam kakor dež, kakor pozni in prvi dež na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, '»Oh Efrájim, kaj naj ti storim? Oh Juda, kaj naj ti storim? Kajti vaša dobrota je kakor jutranji oblak in kakor zgodnja rosa odide proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Zatorej sem jih obtesaval po prerokih, moril sem jih z besedami iz svojih ust. Tvoje sodbe so kakor svetloba, ki gre naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Kajti želel sem usmiljenja in ne klavne daritve, in spoznanja Boga bolj kakor žgalne daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Toda podobni so ljudem, ki so prestopili zavezo. Tam so zoper mene ravnali zahrbtno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileád je mesto tistih, ki počno krivičnost in je oskrunjeno s krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Kakor krdela roparjev prežijo na človeka, tako skupina duhovnikov mori po poti z odobravanjem, kajti zagrešujejo nespodobnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Videl sem strašno stvar v Izraelovi hiši. Tam je vlačugarstvo Efrájima, Izrael je omadeževan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Prav tako, oh Juda, on je zate pripravil žetev, ko vrnem ujetništvo svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Ko sem hotel ozdraviti Izraela, takrat je bila odkrita krivičnost Efrájima in zlobnost Samarije, kajti zagrešili so neresnico. In tat vstopa in krdelo roparjev pleni zunaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'V svojih srcih pa ne preudarijo, da se spominjam vse njihove zlobnosti. Sedaj so jih njihova lastna dejanja obkrožila; pred mojim obrazom so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Kralja razveseljujejo s svojo zlobnostjo in prince s svojimi lažmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Vsi so zakonolomci, kakor peč, ki jo segreje pek, ki preneha kuriti, potem ko je pregnetel testo, dokler to ni vzhajano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, '§ Na dan našega kralja so ga princi naredili bolnega z vinskimi mehovi; svojo roko podaja s posmehljivci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, '§ Kajti svoje srce so pripravili kakor peč, medtem ko prežijo v zasedi. Njihov pek spi vso noč; zjutraj ta gori kakor plameneč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Vsi so vroči kakor peč in požrli so svoje sodnike; vsi njihovi kralji so padli; tam ni nobenega izmed njih, ki kliče k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efrájim se je pomešal med ljudstvo, Efrájim je neobrnjen kolač.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Tujci so požrli njegovo moč, on pa tega ne spoznava. Da, sivi lasje so tu in tam na njem, vendar ne spoznava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Izraelov ponos pričuje v njegov obraz, oni pa se ne vrnejo h Gospodu, svojemu Bogu niti ga zaradi vsega tega ne iščejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Tudi Efrájim je podoben neumni golobici brez srca; kličejo k Egiptu, hodijo v Asirijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Ko bodo šli, bom nadnje razširil svojo mrežo. Sklatil jih bom dol kakor perjad neba, kaznoval jih bom, kakor je slišala njihova skupnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Gorje jim! Kajti zbežali so od mene. Naj jim bo namenjeno uničenje! Ker so se prekršili zoper mene. Čeprav sem jih odkupil, so oni kljub temu zoper mene govorili laži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'In niso klicali k meni s svojim srcem, ko so tulili na svojih posteljah; zbrali so se zaradi žita in vina in se uprli zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Čeprav sem utrdil in okrepil njihove lakte, so zoper mene še vedno domišljali vragolijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Vračajo se, toda ne k Najvišjemu; so kot varljiv lok; njihovi princi bodo padli pod mečem zaradi besa njihovega jezika. To bo v njihov posmeh v egiptovski deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Nastavi šofar k svojim ustom. Prišel bo kakor orel zoper Gospodovo hišo, zato ker so prekršili mojo zavezo in se prekršili zoper mojo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Izrael bo klical k meni: ›Moj Bog, mi te poznamo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Izrael je zavrgel stvar, ki je dobra; sovražnik ga bo zasledoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Nastavljali so si kralje, toda ne po meni. Nameščali so si prince, jaz pa tega nisem vedel. Iz svojega srebra in svojega zlata so si delali malike, da bi bili lahko iztrebljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Tvoje tele, oh Samarija, te je zavrglo. Moja jeza se je vnela zoper njih. Kako dolgo bo, preden se bodo dokopali do nedolžnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Kajti tudi to je bilo iz Izraela; delavec ga je naredil, zato to ni Bog, temveč bo tele iz Samarije zlomljeno na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Kajti sejali so veter, želi bodo pa vihar. Ta nima stebla, brst ne obrodi moke. Če bo tako, da obrodi, ga bodo pogoltnili tujci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Izrael je požrt; sedaj bodo med pogani kakor posoda, v kateri ni zadovoljstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Kajti šli so gor v Asirijo, osamljen divji osel sam zase. Efrájim si je najel ljubimce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Da, čeprav so najemali med narodi, jih bom sedaj zbral in bodo malce žalovali zaradi bremena kralja princev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Ker je Efrájim naredil mnogo oltarjev za greh, bodo oltarji njemu v greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Njemu sem napisal velike stvari iz svoje postave, vendar so bile štete kakor čudna stvar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Žrtvujejo meso za klavno daritev mojih daritev in ga jedo, toda Gospod jih ne sprejema. Sedaj se bo spomnil njihove krivičnosti in obiskal njihove grehe; vrnili se bodo v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, '»Kajti Izrael je pozabil svojega Stvarnika in zgradil templje in Juda je pomnožil utrjena mesta, toda na njegova mesta bom poslal ogenj in ta bo požrl njegove palače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne veseli se, oh Izrael, zaradi radosti kakor drugo ljudstvo, kajti šel si vlačugarsko od svojega Boga, ljubil si nagrado na vsakem žitnem mlatišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Mlatišče in vinska stiskalnica jih ne bosta hranila in novo vino se bo pokvarilo v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ne bodo prebivali v Gospodovi deželi, temveč se bo Efrájim vrnil v Egipt in v Asiriji bodo jedli nečiste stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ne bodo več darovali vinskih daritev Gospodu niti mu ne bodo ugajale. Njihove klavne daritve jim bodo kakor kruh žalovalcev. Vsi, ki bodo jedli od njih, bodo oskrunjeni, kajti njihov kruh, za njihovo dušo, ne bo prišel v Gospodovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Kaj boste storili na slovesen dan in na dan Gospodovega praznika?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Kajti glej, odšli so zaradi uničenja. Egipt jih bo zbral, Memfis jih bo pokopal. Prijetne kraje za njihovo srebro bodo imele koprive v lasti, trnje bo v njihovih šotorskih svetiščih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Prišli so dnevi obiskanja, prišli so dnevi povračila, Izrael bo to vedel. Prerok je bedak, duhoven človek je zmešan zaradi množice tvoje krivičnosti in velikega sovraštva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efrájimov stražar je bil z mojim Bogom, toda prerok je ptičarjeva zanka na vseh njegovih poteh in sovraštvo v hiši njegovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Globoko so se izpridili, kakor v dneh Gíbee, zato se bo spomnil njihove krivičnosti, obiskal bo njihove grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, '»Izraela sem našel podobnega trtam v divjini. Vaše očete sem videl kakor prvi sad na figovem drevesu ob njegovem prvem času, toda odšli so k Báal Peórju in se oddvojili v to sramoto in njihove ogabnosti so bile glede na to, kar so ljubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Glede Efrájima, njihova slava bo odletela proč kakor ptica, od poroda in od maternice in od spočetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Čeprav bodo vzredili svoje otroke, jih bom vendar oropal, da tam noben človek ne bo ostal. Da, gorje tudi tistim, ko odidem od njih!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efrájim je, kakor sem videl Tir, zasajen na prijetnem kraju, toda Efrájim bo svoje otroke privedel k morilcu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Daj jim, oh Gospod. Kaj hočeš dati? Daj jim maternico, ki splavlja in suhe prsi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, '»Vsa njihova zlobnost je v Gilgálu, kajti tam sem jih zasovražil. Zaradi zlobnosti njihovih početij jih bom pognal iz svoje hiše. Ne bom jih več ljubil. Vsi njihovi princi so puntarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efrájim je udarjen, njihova korenina je posušena, nobenega sadu ne bodo obrodili. Da, čeprav bodo obrodili, bom vendar ubil celó ljubljeni sad njihove maternice.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Moj Bog jih bo zavrgel, ker mu niso prisluhnili in oni bodo postopači med narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael je prazna trta, sebi prinaša sad. Glede na množico svojega sadu je množil oltarje. Glede na dobroto njegove dežele so naredili čedne podobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Njihovo srce je razdeljeno, sedaj bodo najdeni pomanjkljivi. Zrušil bo njihove oltarje, oplenil njihove podobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Kajti sedaj bodo rekli: ›Nimamo kralja, ker se nismo bali Gospoda. Kaj naj bi nam torej storil kralj?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Govorili so besede, lažno prisegali pri sklepanju zaveze. Tako sodba poganja kakor pikasti mišjak na brazdah polja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Prebivalci Samarije bodo trepetali zaradi telet Bet Avena, kajti ljudstvo le-teh bo nad tem žalovalo in duhovniki le-teh, ki so se ob tem veselili, [bodo trepetali] zaradi slave [bogov zlatih telet], zato ker je ta odšla od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Prav tako bo le-to odneseno v Asirijo za darilo kralju Jarebu. Efrájim bo prejel sramoto in Izrael se bo sramoval svojega lastnega nasveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, '§ Glede Samarije, njen kralj je odsekan kakor pena na vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Prav tako bodo uničeni visoki kraji Avena, Izraelov greh. Trnje in osat bosta pognala na njihovih oltarjih in goram bodo rekli: »Pokrijte nas« in hribom: »Padite na nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Oh Izrael, grešil si od dni Gíbee. Tam so stali, bitka v Gíbei zoper otroke krivičnosti jih ni dosegla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Po moji želji je, da naj jih kaznujem, in ljudstvo se bo zbralo zoper njih, ko se bodo zvezali v svojih dveh brazdah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efrájim je kakor telica, ki je poučena in rada mendra žito, toda jaz sem šel čez njen lepi vrat. Efrájima bom pripravil, da jaha, Juda bo oral, Jakob pa bo branal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Sejte si v pravičnosti, žanjite v usmiljenju, pobranajte svoja neposejana tla, kajti čas je, da iščete Gospoda, dokler ne pride in na vas dežuje pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Orali ste zlobnost, želi ste krivičnost, jedli ste sad laži, ker ste zaupali v svojo pot in v množico svojih mogočnih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Zato bo med tvojim ljudstvom vstal nemir in vse tvoje trdnjave bodo oplenjene, kakor je na dan bitke Šalmán oplenil Bet Arbeél. Mati je bila raztreščena na koščke na svojih otrocih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Tako vam bo storil Betel zaradi vaše velike zlobnosti. Zjutraj bo Izraelov kralj popolnoma iztrebljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Ko je bil Izrael otrok, takrat sem ga ljubil in svojega sina poklical iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Kakor so jih [preroki] klicali, tako so odhajali od njih. Žrtvovali so Báalom in rezanim podobam zažigali kadilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, '§ Tudi Efrájima sem učil hoditi in jih držal za njihove lakte, toda niso spoznali, da sem jih jaz ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, '§ Pritegoval sem jih s človeškimi vrvicami, z vezmi ljubezni in bil sem jim kakor tisti, ki snamejo jarem z njihovih čeljusti in jaz sem jim dajal hrano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ne bo se vrnil v egiptovsko deželo, temveč bo Asirec njegov kralj, ker so zavrnili, da bi se vrnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, '§ Meč bo ostajal na njegovih mestih in použije njegove mladike in jih požre zaradi njihovih lastnih nasvetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, '§ Moje ljudstvo je nagnjeno k odpadu od mene. Čeprav so jih klicali k Najvišjemu, ga sploh nihče ni hotel povišati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kako naj bi se ti odrekel, Efrájim? Kako naj bi te izročil, Izrael? Kako naj bi te naredil kakor Admo? Kako naj bi te postavil kakor Cebojím? Moje srce je spremenjeno znotraj mene, poleg tega so se moja kesanja razvnela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Ne bom izvršil okrutnosti svoje jeze, ne bom se vrnil, da uničim Efrájima, kajti jaz sem Bog in ne človek, Sveti v tvoji sredi in ne bom vstopil v mesto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, '§ Hodili bodo za Gospodom, rjovel bo kakor lev. Ko bo zarjovel, potem bodo otroci pritrepetali od zahoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Pritrepetali bodo kakor ptica iz Egipta in kakor golobica iz asirske dežele in postavil jih bom v njihove hiše,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '»Efrájim me obdaja z lažmi in Izraelova hiša s prevaro, toda Juda še vlada z Bogom in je zvest s svetimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efrájim se hrani z vetrom in sledi vzhodnemu vetru, dnevno povečuje laži in opustošenje, sklepa zavezo z Asirci in olje nosi v Egipt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Prav tako ima Gospod polemiko z Judom in kaznoval bo Jakoba glede na njegove poti; poplačal mu bo glede na njegova dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'V maternici je svojega brata prijel za peto in s svojo močjo je imel moč z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Da, imel je moč nad angelom in je prevladal. Jokal je in ponižno prosil k njemu. Našel ga je v Betelu in tam je [Bog] govoril z nami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'celo Gospod Bog nad bojevniki; Gospod je njegov spomenik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Zatorej se obrni k svojemu Bogu, ohranjaj usmiljenje in sodbo in nenehno čakaj na svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'On je trgovec, v njegovi roki so tehtnice prevare, rad zatira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Efrájim je rekel: »Vendar sem postal bogat, pridobil sem si imetje, v vseh mojih naporih ne bodo našli v meni nobene krivičnosti, da bi bila greh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '»Jaz pa, ki sem Gospod, tvoj Bog, od egiptovske dežele, te bom vendarle prisilil, da prebivaš v šotorih kakor v dneh slovesnega praznika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Prav tako sem govoril po prerokih in množil videnja ter po služenju prerokov uporabljal prilike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ali je v Gileádu krivičnost? Oni so zagotovo ničevost. V Gilgálu žrtvujejo bikce. Da, njihovi oltarji so kakor kupi na brazdah polj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, '§ Jakob je zbežal v sirsko deželo in Izrael je služil za ženo in za ženo je varoval ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'In po preroku je Gospod Izraela privedel iz Egipta in po preroku je bil obvarovan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Efrájim ga je silno grenko izzival k jezi, zatorej bo njegovo kri pustil nad njim in njegovo grajo bo njegov Gospod povrnil k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Ko je Efrájim trepetajoč govoril, se je povišal v Izraelu, toda ko se je pohujšal z Báalom, je umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, '§ In sedaj bolj in bolj grešijo in iz svojega srebra so si naredili ulite podobe in malike, glede na svoje lastno razumevanje. Vsi ti so delo rokodelcev, o njih pravijo: ›Naj možje, ki žrtvujejo, poljubijo teleta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Zatorej bodo kakor jutranji oblak in kakor zgodnja rosa, ki izginja, kakor pleve, ki je z vrtinčastim vetrom odpihnjeno iz mlatišča in kakor dim iz dimnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'In vendar jaz sem Gospod, tvoj Bog, od egiptovske dežele in razen mene ne boš poznal nobenega boga, kajti poleg mene ni rešitelja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Poznal sem te v divjini, v deželi velike suše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Glede na njihov pašnik, tako so bili nasičeni; nasičeni so bili in njihovo srce je bilo povzdignjeno, zato so me pozabili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Zatorej jim bom kakor lev, kakor leopard ob poti jih bom opazoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Srečal jih bom kakor medvedka, ki je oropana svojih mladičev in raztrgal bom opno njihovega srca in tam jih bom požrl kakor lev. Divja žival jih bo trgala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, '§ Oh Izrael, uničeval si samega sebe, toda v meni je tvoja pomoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, '§ Jaz bom tvoj kralj. Kje je katerikoli drug, ki te lahko reši v vseh tvojih mestih? In tvoji sodniki, o katerih praviš: ›Daj mi kralja in prince?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'V svoji jezi sem ti dal kralja in v svojem besu sem ga vzel proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Krivičnost Efrájima je zvezana, njegov greh je skrit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Bridkosti ženske v porodnih mukah bodo prišle nadenj. On je nespameten sin, kajti ne bi smel dolgo ostati v odprtini rojevanja otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, '§ Odkupil jih bom pred oblastjo groba; odkupil jih bom pred smrtjo. ›Oh smrt, jaz bom tvoje kuge;‹ ›Oh grob, jaz bom tvoje uničenje.‹ Kesanje bo skrito mojim očem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Čeprav bi bil rodoviten med svojimi brati, bo prišel vzhodni veter, veter od Gospoda bo prišel gor iz divjine in njegov izvir se bo posušil in njegov studenec bo osušen. Oplenil bo zaklad vseh prijetnih posod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samarija bo postala zapuščena, kajti uprla se je zoper svojega Boga. Padli bodo pod mečem, njihovi otročiči bodo razbiti na koščke in njihove nosečnice bodo razparane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Oh Izrael, vrni se h Gospodu, svojemu Bogu, kajti padel si zaradi svoje krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'S seboj vzemite besede in se obrnite h Gospodu. Recite mu: ›Odvzemi proč vso krivičnost in nas milostljivo sprejmi, tako bomo povrnili teleta svojih ustnic.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Asúr nas ne bo rešil, ne bomo jahali na konjih niti delu naših rok ne bomo več rekli: › Vi ste naši bogovi,‹ kajti v tebi osiroteli najde usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Jaz bom ozdravil njihov odpad, velikodušno jih bom ljubil, kajti moja jeza se je odvrnila od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Izraelu bom kakor rosa. Rasel bo kakor lilija in svoje korenine poganjal kakor Libanon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Njegove mladike se bodo razširile in njegova lepota bo kakor oljka in njegov vonj kakor Libanon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Tisti, ki prebivajo pod njegovo senco, se bodo vrnili; oživeli bodo kakor žito in rastli kakor trta. Njegova vonjava bo kakor libanonsko vino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efrájim bo rekel: ›Kaj imam še opraviti z maliki?‹ Slišal sem ga in ga opazil. Podoben sem zeleni cipresi. Od mene je najti tvoj sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kdo je moder in bo razumel te stvari? Razsoden in jih bo spoznal? Kajti Gospodove poti so pravilne in pravični se bo ravnal po njih. Toda prestopniki bodo padli na njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Gospodova beseda, ki je prišla Joélu, Petuélovemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Poslušajte to, vi starci in pazljivo prisluhnite, vsi vi prebivalci dežele. Ali je bilo to v vaših dneh ali celo v dneh vaših očetov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Pripovedujte svojim otrokom o tem in naj vaši otroci pripovedujejo svojim otrokom in njihovi otroci naslednjemu rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'To, kar je kosmata gosenica pustila, je pojedla leteča kobilica; in to, kar je leteča kobilica pustila, je pojedla škodljiva gosenica; in to, kar je pustila škodljiva gosenica, je pojedla gosenica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Prebudite se, vi pijanci in jokajte, tulite vsi vi vinski pivci zaradi novega vina, kajti odrezan je od vaših ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Kajti narod je prišel nad mojo deželo, močan in brezštevilen, katerih zobje so zobje leva in ima kočnike velikega leva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Opustošil je mojo trto in olupil moje figovo drevo. Naredil ga je razgaljenega in ga vrgel proč; njegove mladike so pobeljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Žalujte kakor devica, opasana z vrečevino za soprogom svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Jedilna daritev in pitna daritev je odrezana od Gospodove hiše. Duhovniki, Gospodovi služabniki, žalujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Polje je opustošeno, zemlja žaluje, kajti žito je opustošeno. Novo vino je posušeno, olje peša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Bodite osramočeni, oh vi poljedelci. Tulite, oh vi obrezovalci trte, zaradi pšenice in zaradi ječmena, ker je žetev polja propadla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Trta je posušena in figovo drevo peša. Granatovec, tudi palmovo drevo in jablana, celó vsa poljska drevesa so ovenela, ker je veselje zamrlo pred človeškimi sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Opašite se in objokujte, vi duhovniki; tulite, služabniki oltarja, pridite, vso noč ležite v vrečevini, vi služabniki mojega Boga, kajti jedilna daritev in pitna daritev je zadržana pred hišo vašega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Posvetite post, skličite slovesen zbor, zberite starešine in vse prebivalce dežele v hišo Gospoda, svojega Boga in kličite h Gospodu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '»Gorje zaradi dneva!« Kajti dan Gospodov je pri roki in to bo prišlo kakor uničenje od Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Mar ni hrana odrezana izpred naših oči, da, radost in veselje od hiše našega Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Seme je razpadlo pod njihovimi grudami, kašče ležijo zapuščene, skednji so razpadli, kajti žito je ovenelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Kako stokajo živali! Živine črede so zmedene, ker nimajo pašnika; da, tropi ovac so zapuščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Oh Gospod, k tebi bom klical, kajti ogenj je požrl pašnike divjine in plamen je požgal vsa poljska drevesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Tudi poljske živali kličejo k tebi, kajti reke vodá so posušene in ogenj je pogoltnil pašnike divjine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Zatrobite na šofar na Sionu in razglasite alarm na moji sveti gori. Naj vsi prebivalci dežele trepetajo, kajti dan Gospodov prihaja, kajti ta je blizu, pri roki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'dan teme in mračnosti, dan oblakov in goste teme se kot jutro razširjajo nad gorami. Veliko ljudstvo in močno, nikoli ni bilo podobnega niti ga ne bo več za tem, celó do let mnogih rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Ogenj požira pred njimi in za njimi gori plamen. Dežela je pred njimi kakor edenski vrt in za njimi zapuščena divjina; da, in nič jim ne bo pobegnilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Njihov videz je kakor videz konjev in kakor konjeniki, tako bodo tekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Poskakovali bodo kakor hrup bojnih vozov na vrhovih gora, kakor hrup ognjenega plamena, ki požira strnišče, kakor močno ljudstvo, postavljeno v bojno razvrstitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Pred njihovim obrazom bo ljudstvo močno zaskrbljeno. Vsi obrazi bodo zbirali črnino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Tekli bodo kakor mogočni možje, obzidje bodo preplezali kakor bojevniki in korakali bodo vsak po svojih poteh in svojih vrst ne bodo pretrgali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Niti eden ne bo sunil drugega. Hodili bodo vsak po svoji stezi in ko padejo na meč, ne bodo ranjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Tekali bodo sem ter tja po mestu, tekli bodo na obzidje, splezali bodo na hiše, vstopili bodo pri oknih kakor tat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Zemlja se bo tresla pred njimi, nebo bo trepetalo, sonce in luna bosta otemnela in zvezde bodo umaknile svoje svetlikanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Gospod bo izustil svoj glas pred svojo vojsko, kajti njegov tabor je zelo velik, kajti on je močan, ki izvršuje svojo besedo, kajti dan Gospodov je velik in zelo strašen in kdo ga lahko prenese?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '»Zato se tudi sedaj,« govori Gospod, »obrnite celó k meni z vsem svojim srcem in s postom in z jokom in z žalovanjem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'in pretrgajte svoje srce, ne pa svojih oblačil in obrnite se h Gospodu, svojemu Bogu, kajti on je milostljiv in usmiljen, počasen za jezo in velike prijaznosti in se kesa zla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kdo ve, če se bo vrnil in pokesal in pustil blagoslov za seboj, celó jedilno daritev in pitno daritev Gospodu, svojemu Bogu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Zatrobite na šofar na Sionu, posvetite post, skličite slovesen zbor,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'zberite ljudstvo, posvetite skupnost, zberite starešine, naberite otroke in tiste, ki sesajo pri prsih. Naj pride ženin iz svoje sobe in nevesta iz svoje sobice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Naj duhovniki, Gospodovi služabniki, jokajo med preddverjem in oltarjem in naj govorijo: »Prizanesi svojemu ljudstvu, oh Gospod in svoje dediščine ne izroči v zasmeh, da bi nad njimi vladali pogani. Zakaj bi med ljudstvom rekli: ›Kje je njihov Bog?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Potem bo Gospod ljubosumen nad svojo deželo in se usmilil svojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Da, Gospod bo odgovoril in rekel svojemu ljudstvu: »Glejte, poslal vam bom žito, vino in olje in nasičeni boste s tem in ne bom vas več naredil v zasmeh med pogani,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'toda daleč od vas bom odstranil severno vojsko in pregnal jih bom v jalovo in zapuščeno deželo, s svojim obrazom proti vzhodnemu morju in s svojim zadnjim delom proti skrajnemu morju in njegov smrad se bo vzdignil in njegovo zaudarjanje se bo vzdignilo, ker je storil velike stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne boj se, oh dežela, bodi vesela in se raduj, kajti Gospod bo storil velike stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne bodite prestrašene, ve poljske živali, kajti pašniki divjine poganjajo, kajti drevo rodi svoj sad, figovo drevo in trta predajata svojo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Bodite torej veseli, vi sionski otroci in veselite se v Gospodu, svojem Bogu, kajti dal vam je zmerno prvi dež in povzročil bo, da vam bo prišel dež, prvi dež in pozni dež v prvem mesecu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Tla bodo polna pšenice in kadi bodo prekipevale od vina in olja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, '»Povrnil vam bom leta, ki jih je požrla leteča kobilica, škodljiva gosenica, gosenica in kosmata gosenica, moja velika vojska, ki sem jo poslal med vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Jedli boste v obilju in boste nasičeni in slavili ime Gospoda, svojega Boga, ki je z vami čudovito ravnal in moje ljudstvo nikoli ne bo osramočeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Vedeli boste, da sem jaz v Izraelovi sredi in da sem jaz Gospod, vaš Bog in nihče drug, in moje ljudstvo nikoli ne bo osramočeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Potem se bo zgodilo, da bom svojega duha izlil na vse meso. Vaši sinovi in vaše hčere bodo prerokovali, vaši starci bodo sanjali sanje, vaši mladeniči bodo videli videnja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Tudi na služabnike in na pomočnice bom v tistih dneh izlil svojega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Pokazal bom čudeže na nebu in na zemlji, kri in ogenj in stebre dima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Sonce se bo spremenilo v temo in luna v kri pred velikim in strašnim dnevom Gospodovega prihoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'In zgodilo se bo, da kdorkoli bo klical h Gospodovemu imenu, bo osvobojen, kajti osvoboditev bo na gori Sion in v Jeruzalemu, kakor je rekel Gospod in v ostanku, ki ga bo Gospod poklical.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '»Kajti glej, v tistih dneh in v tistem času, ko bom ponovno privedel ujetništvo Juda in Jeruzalema,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'bom prav tako zbral vse narode in jih privedel dol v dolino Józafat in tam se bom pravdal z njimi zaradi svojega ljudstva in zaradi svoje dediščine Izraela, ki so jih razkropili med narode in razdelili mojo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Za moje ljudstvo so metali žrebe in dajali fanta za pocestnico in punco prodajali za vino, da bi lahko pili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Da, in kaj imate vi z menoj, oh Tir in Sidón in vse obale Palestine? Ali mi boste vrnili povračilo? In če mi povrnete, bom brez odlašanja in hitro vaše povračilo povrnil na vašo lastno glavo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'zato ker ste jemali moje srebro in moje zlato in ste v svoje templje odnesli čudovite, prijetne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Prav tako ste Grkom prodajali Judove otroke in jeruzalemske otroke, da bi jih lahko spravili daleč proč od njihove meje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Glej, dvignil jih bom iz kraja, kamor ste jih prodali in povrnil vam bom vaše povračilo na vašo lastno glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Vaše sinove in vaše hčere bom prodal v roko Judovih otrok in prodali jih bodo Sabejcem, ljudstvu, ki je daleč proč,« kajti Gospod je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Razglasite to med pogani: »Pripravite vojno, prebudite mogočne može, naj se vsi bojevniki približajo, naj pridejo gor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Prekujte svoje lemeže v meče in svoje obrezovalne kavlje v sulice. Naj slabotni reče: ›Močan sem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Zberite se in pridite vsi vi pogani in zberite se skupaj naokrog. Tamkaj primoraj svoje mogočne, da pridejo dol, oh Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Naj bodo pogani prebujeni in pridejo gor v dolino Józafat, kajti tam bom sedel, da sodim vsem poganom naokoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Nastavite srp, kajti žetev je zrela. Pridite, spustite se, kajti stiskalnica je polna, maščoba preplavlja, kajti njihova zlobnost je velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Množice, množice v dolini odločitve; kajti dan Gospodov je blizu v dolini odločitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Sonce in luna bosta otemnela in zvezde bodo umaknile svoje svetlikanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Gospod bo tudi rjovel iz Siona in izustil svoj glas iz Jeruzalema, in nebo in zemlja se bosta tresla, toda Gospod bo upanje svojemu ljudstvu in moč Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Tako boste vedeli, da jaz sem Gospod, vaš Bog, ki prebivam na Sionu, moji sveti gori. Potem bo Jeruzalem svet in nikakršni tujci ne bodo več hodili skozenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Na tisti dan se bo zgodilo, da bodo gore kapljale novo vino in z gričev se bo cedilo mleko in v vseh Judovih rekah bodo tekle vode in studenec bo izviral iz Gospodove hiše in namakal dolino Šitím.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egipt bo opustošenje in Edóm bo zapuščena divjina zaradi nasilja zoper Judove otroke, ker so v njihovi deželi prelivali nedolžno kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Toda Juda bo prebival na veke in Jeruzalem od roda do roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Kajti jaz bom očistil njihovo kri, ki je nisem očistil, kajti Gospod prebiva na Sionu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Besede Amosa, ki je bil med čredniki iz Tekóe, ki jih je videl glede Izraela v dneh Uzíjaha, Judovega kralja in v dneh Jerobeáma, Jehoáševega sina, Izraelovega kralja, dve leti pred potresom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Rekel je: » Gospod bo rjovel iz Siona in izustil svoj glas iz Jeruzalema in prebivališča pastirjev bodo žalovala in vrh Karmela se bo posušil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tako govori Gospod: »Zaradi treh prestopkov Damaska in zaradi štirih ne bom odvrnil njegove kazni, ker so Gileád mlatili z mlatilnimi orodji iz železa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Temveč bom poslal ogenj v Hazaélovo hišo, ki bo použil Ben Hadádove palače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Zlomil bom tudi zapah Damaska in iztrebil prebivalca iz ravnine Aven in tistega, ki drži žezlo, iz edenske hiše in ljudstvo iz Sirije bo šlo v ujetništvo v Kir,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tako govori Gospod: »Zaradi treh prestopkov Gaze in zaradi štirih ne bom odvrnil njene kazni, ker so odvedli proč ujete, celotno ujetništvo, da jih izročijo Edómu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'toda poslal bom ogenj na obzidje Gaze, ki bo pogoltnil njene palače');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'in iztrebil bom prebivalca iz Ašdóda in tistega, ki drži žezlo iz Aškelóna. Svojo roko bom obrnil zoper Ekrón in preostanek Filistejcev bo izginil,« govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tako govori Gospod: »Zaradi treh prestopkov Tira in zaradi štirih ne bom odvrnil njegove kazni, ker so celotno ujetništvo izročili Edómu in se niso spomnili bratske zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Toda jaz bom na obzidje Tira poslal ogenj, ki bo požrl njegove palače.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tako govori Gospod: »Zaradi treh prestopkov Edóma in zaradi štirih ne bom odvrnil njegove kazni, ker je svojega brata zasledoval z mečem in zavrgel vse usmiljenje in je njegova jeza neprestano trgala in je svoj bes ohranjal na veke;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'toda poslal bom ogenj nad Temán, ki bo požrl palače v Bocri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tako govori Gospod: »Zaradi treh prestopkov Amónovih otrok in zaradi štirih ne bom odvrnil njegove kazni, ker so razparali nosečnice iz Gileáda, da bi lahko razširili svojo mejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Toda jaz bom zanetil ogenj na obzidju Rabe in ta bo požrl njene palače z vpitjem na dan bitke, z viharjem na dan vrtinčastega vetra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Njihov kralj bo šel v ujetništvo, on in njegovi princi skupaj,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tako govori Gospod: »Zaradi treh prestopkov Moába in zaradi štirih ne bom odvrnil njegove kazni, ker je kosti edómskega kralja sežgal v žganem apnu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Toda jaz bom poslal ogenj nad Moáb in ta bo požrl palače Kerijóta, in Moáb bo umrl s hrupom, z vpitjem in z zvokom šofarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Iztrebil bom sodnika iz njegove srede in z njim bom ubil vse njegove prince,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tako govori Gospod: »Zaradi treh prestopkov Juda in zaradi štirih ne bom odvrnil njegove kazni; ker so prezirali Gospodovo postavo in se niso držali njegovih zapovedi in njihove laži so jim povzročile, da se motijo, za katerimi so hodili njihovi očetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Toda jaz bom poslal ogenj nad Juda in ta bo požrl jeruzalemske palače.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tako govori Gospod: »Zaradi treh prestopkov Izraela in zaradi štirih ne bom odvrnil njegove kazni, ker so pravičnega prodajali za srebro in revnega za par čevljev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'ki koprnijo po zemeljskem prahu na glavi revnega in zavijajo pot krotkega. Moški in njegov oče bosta šla noter k isti deklici, da oskrunita moje sveto ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Ob vsakem oltarju legajo na oblačila, položena za jamstvo in pijejo vino obsojenih v hiši svojega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Čeprav sem pred njimi uničil Amoréjca, katerega višina je bila podobna višini ceder in je bil močan kakor hrasti, vendar sem uničil njegov sad od zgoraj in njegove korenine od spodaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Privedel sem vas tudi iz egiptovske dežele in vas štirideset let vodil skozi divjino, da vzamete v last deželo Amoréjca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Izmed vaših sinov sem dvignil preroke in izmed vaših mladeničev nazirce. Mar ni to celo tako, oh vi Izraelovi otroci?« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '»Toda nazircem ste dajali piti vino in prerokom zapovedovali, rekoč: ›Ne prerokujte.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Glejte, stlačen sem pod vami, kakor je stlačen voz, ki je poln snopov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Zato bo pred naglim izginil umik in močni ne bo okrepil svoje moči niti mogočni sebe ne bo osvobodil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'niti ne bo stal tisti, ki prijema lok in kdor je naglih stopal sebe ne bo osvobodil niti kdor jaha konja sebe ne bo osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'In kdor je pogumen med mogočnimi, bo na ta dan nag pobegnil proč,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Poslušajte to besedo, ki jo je Gospod govoril zoper vas, oh Izraelovi otroci, zoper celotno družino, ki sem jo privedel iz egiptovske dežele, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '»Samo vas sem poznal izmed vseh zemeljskih družin, zato vas bom kaznoval zaradi vseh vaših krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Mar lahko dva hodita skupaj, razen če se strinjata?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Ali bo lev rjovel v gozdu, kadar nima plena? Ali bo mlad lev vpil iz svojega brloga, če ni ničesar dobil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Ali lahko ptica pade v zanko na tla, kjer zanjo ni nobene pasti? Mar nekdo pobere zanko s tal in ni sploh ničesar ujel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Mar bo šofar zatrobil v mestu in ljudstvo ne bo prestrašeno? Mar bo zlo v mestu in Gospod tega ni storil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Zagotovo Gospod Bog ne bo storil ničesar, da ne bi svojo skrivnost razodeval svojim služabnikom prerokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lev je zarjovel, kdo se ne bo bal? Gospod Bog je spregovoril, kdo ne bi prerokoval?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Razglasi v palačah pri Ašdódu in v palačah egiptovske dežele in reci: ›Zberite se na gorah Samarije in glejte velike nemire v njeni sredi in zatirane v njeni sredi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Kajti ne znajo delati pravilno,« govori Gospod, »tisti, ki kopičijo nasilje in rop v svojih palačah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Zato tako govori Gospod Bog: »Nasprotnik bo celo naokoli dežele in tvojo moč bo privedel dol od tebe in tvoje palače bodo oplenjene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tako govori Gospod: »Kakor pastir iz levjih ust izvleče dve nogi ali košček ušesa, tako bodo izvlečeni Izraelovi otroci, ki prebivajo v Samariji, v kotu postelje in na ležišču v Damasku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Prisluhnite in pričujte v Jakobovi hiši,« govori Gospod Bog, Bog nad bojevniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, '»da na dan, ko bom na njem obiskal Izraelove prestopke, bom obiskal tudi oltarje Betela in oltarni rogovi bodo odsekani in padli na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Zimsko hišo bom udaril s poletno hišo [vred] in slonokoščene hiše bodo izginile in velike hiše bodo uničene,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, '»Poslušajte to besedo, ve bašánske krave, ki ste na samarijski gori, ki stiskate uboge, ki drobite pomoči potrebne, ki svojim gospodarjem pravite: ›Prinesite in naj pijemo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Gospod Bog je prisegel pri svoji svetosti, da, glejte, nad vas bodo prišli dnevi, ko vas bo odvedel proč s kavlji in vaše potomstvo s trnki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Šle boste ven pri vrzelih, vsaka krava pri tisti, ki je pred njo, in vrgle jih boste v palačo,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '§ »Prihajate v Betel in grešite, pri Gilgálu množite prestopek in vsako jutro prinašajte svoje klavne daritve in svoje desetine po treh letih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'in darujte žrtev zahvaljevanja s kvasom in razglašajte in objavljajte prostovoljne daritve, kajti to vam je všeč, oh vi, Izraelovi otroci,« govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '»In tudi jaz sem vam dal čistost zob po vseh vaših mestih in pomanjkanje kruha po vseh vaših krajih. Vendar se niste vrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '»In tudi jaz sem zadržal dež pred vami, ko je bilo še tri mesece do žetve in mu dal, da dežuje nad enim mestom in dal, da ne dežuje nad drugim mestom. Na en kos je deževalo, kos pa, na katerega ni deževalo, se je posušil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Tako so dva ali tri mesta tavala k enemu mestu, da pijejo vodo, toda niso bila nasičena. Vendar se niste vrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '»Udaril sem vas s kvarjenjem in plesnijo. Ko so se množili vaši vrtovi in vaši vinogradi in vaša figova drevesa in vaše oljke, jih je požrla kosmata gosenica. Vendar se niste vrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '»Med vas sem poslal kužno bolezen po načinu iz Egipta. Vaše mladeniče sem umoril z mečem in vaše konje odvedel proč in storil sem, da se smrad vaših taborov vzdigne do vaših nosnic, vendar se niste vrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '»Uničil sem nekatere izmed vas, kakor je Bog razdejal Sódomo in Gomóro in ste bili kakor kos tlečega lesa, izvlečenega iz gorenja, vendar se niste vrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, '»Zato ti bom tako storil, oh Izrael in ker ti bom to storil, se pripravi, da srečaš svojega Boga, oh Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Kajti glej, tisti ki oblikuje gore in ustvarja veter in razglaša človeku, kaj je njegova misel, ki dela jutranjo temo in mendra na visokih krajih zemlje. Gospod, Bog nad bojevniki, je njegovo ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Poslušajte to besedo, ki jo vzdigujem zoper vas, celó žalostinko, oh Izraelova hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Devica Izrael je padla, ne bo več vstala, zapuščena je na svoji zemlji, tam ni nikogar, ki bi jo vzdignil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Kajti tako govori Gospod Bog: »Mestu, ki je šlo ven po tisoč, jih preostane sto in tistemu, ki je šlo naprej po sto, jih preostane deset, Izraelovi hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Kajti tako govori Gospod Izraelovi hiši: »Iščite me in boste živeli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'toda ne iščite Betela niti ne vstopajte v Gilgál in ne prečkajte v Beeršébo, kajti Gilgál bo zagotovo šel v ujetništvo in Betel bo prišel v nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Iščite Gospoda in boste živeli, da ne izbruhne kakor ogenj v Jožefovi hiši in jo použije in tam ne bo nikogar, da bi jo gasil v Betelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Vi, ki prevračate sodbo v grenkobo in opuščate pravičnost na zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'iščite njega, ki določa sedem zvezd in Orion in obrača senco smrti v jutro in dan mrači z nočjo, ki kliče po vodah morja in jih izliva na obličje zemlje, Gospod je njegovo ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'ki jača oplenjenega zoper močnega, tako da bo oplenjeni prišel zoper trdnjavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sovražijo tistega, ki graja v velikih vratih in prezirajo tistega, ki govori iskreno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Ker kakor je torej vaše mendranje nad revnim in vi od njega jemljete bremena žita; zgradili ste hiše iz klesanega kamna, toda ne boste prebivali v njih; sadili ste prijetne vinograde, toda ne boste pili vina od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Kajti jaz poznam vaše mnogotere prestopke in vaše mogočne grehe; stiskajo pravičnega, jemljejo podkupnino in v velikih vratih revne odvračajo od njihove pravice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Zato bo v tem času razsoden molčal, kajti to je hud čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Iščite dobro in ne zla, da boste lahko živeli in tako bo Gospod, Bog nad bojevniki, z vami, kakor ste govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Sovražite zlo in ljubite dobro in vzpostavite sodbo v velikih vratih. Morda bo Gospod, Bog nad bojevniki, milostljiv Jožefovemu preostanku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Zato Gospod, Bog nad bojevniki, Gospod, tako govori: »Tarnanje bo na vseh ulicah in na vseh glavnih cestah bodo govorili: ›Ojoj! Ojoj!‹ in poklicali bodo poljedelca, da žaluje in tiste, ki so vešči objokovanja, da tarnajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'In v vseh vinogradih bo tarnanje, kajti jaz pojdem skozte,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, '»Gorje vam, ki si želite Gospodovega dneva! Čemu vam bo to? Dan Gospodov je tema in ne svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Kakor če je človek pobegnil pred levom in ga je srečal medved; ali odšel v hišo in svojo roko naslonil na zid in ga je pičila kača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Mar ne bo Gospodov dan tema in ne svetloba? Celo zelo temen in nobenega svetlikanja v njem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Sovražim, preziram vaše praznične dni in nočem povonjati vaših slovesnih zborov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Čeprav mi darujete žgalne daritve in jedilne daritve, jih ne bom sprejel niti se ne bom oziral na mirovne daritve vaših debelih živali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Šum svojih pesmi vzemi proč od mene, kajti ne bom poslušal melodije tvojih lir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Temveč naj sodba teče dol kakor vode in pravičnost kakor mogočen vodotok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Mar ste mi darovali klavne daritve in jedilne daritve štirideset let v divjini, oh hiša Izraelova?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, '§ Toda nosili ste šotor svojega Moloha in Kijúna, svojih podob, zvezdo svojega boga, kar ste si naredili zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Zatorej vam bom povzročil, da greste v ujetništvo onkraj Damaska,« govori Gospod, čigar ime je Bog nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, '»Gorje tistim, ki so v udobju na Sionu in zaupajo v samarijsko goro, ki se imenujejo vodje narodov, h katerim je prihajala Izraelova hiša!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Prečkajte v Kalne in poglejte in od tam pojdite v veliki Hamát. Potem pojdite dol v Gat Filistejcev. Mar so boljši kakor ta kraljestva? Je njihova meja večja kakor vaša meja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Vi, ki zli dan polagate daleč stran in sedežu nasilja naredite, da pride blizu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'ki ležite na posteljah iz slonovine in se iztegujete na svojih ležiščih in jeste jagnjeta iz tropa in teleta iz srede hleva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'ki monotono pojete na zvok lire in si izmišljate glasbene instrumente, podobno kakor David;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'ki pijete vino v skledicah in se mazilite z vodilnimi mazili. Toda niso užaloščeni zaradi Jožefove stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Zato bodo sedaj šli ujeti s prvimi, ki gredo ujeti in gostija tistih, ki so se iztegovali, bo odstranjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Gospod Bog je prisegel pri samem sebi,« govori Gospod, Bog nad bojevniki, »preziram odličnost Jakoba in sovražim njegove palače, zato bom izročil mesto, z vsem, kar je v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'In zgodilo se bo, če tam ostane deset ljudi v eni hiši, da bodo umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'In njegov stric ga bo vzdignil in tisti, ki ga sežiga, da odnese kosti iz hiše in rekel bo tistemu, ki je pri straneh hiše: › Je tam še kdo s teboj?‹ Ta pa bo rekel: ›Ne.‹ Potem bo rekel: ›Molči, kajti ne smemo omenjati Gospodovega imena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Kajti glej, Gospod zapoveduje in veliko hišo bo udaril z vrzelmi in majhno hišo z razpokami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Mar bodo konji tekli po skali? Ali bo tam kdo oral z voli? Kajti sodbo ste obrnili v žolč in sad pravičnosti v pikasti mišjak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vi, ki se veselite v ničevi stvari, ki pravite: ›Mar nismo s svojo lastno močjo k sebi vzeli rogov?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Toda glejte, zoper vas bom dvignil narod, oh Izraelova hiša,« govori Gospod, Bog nad bojevniki, »in stiskali vas bodo od vstopanja v Hamát, do reke iz divjine.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Tako mi je Gospod Bog pokazal in glej, oblikoval je kobilice v začetku poganjanja otave in glej, to je bila otava po kraljevih košnjah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Pripetilo se je, ko so končale z objedanjem trave dežele, da sem nato rekel: »Oh Gospod Bog, odpusti, rotim te. Po kom bo Jakob vstal? Kajti majhen je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Gospod se je zaradi tega pokesal. »To ne bo,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tako mi je Gospod Bog pokazal in glej, Gospod Bog je klical k pričkanju z ognjem in ta je požrl veliko globino in pojedel del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Potem sem rekel: »Oh Gospod Bog, odnehaj, rotim te. Po kom bo Jakob vstal? Kajti majhen je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Gospod se je zaradi tega pokesal: »Tudi to se ne bo zgodilo,« govori Gospod Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Zato mi je pokazal in glej, Gospod je stal na zidu, narejenem s svinčnico, s svinčnico v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Gospod mi je rekel: »Amos, kaj vidiš?« Rekel sem: »Svinčnico.« Potem je Gospod rekel: »Glej, postavil bom svinčnico v sredo svojega ljudstva Izraela. Ne bom več ponovno šel mimo njega');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'in Izakovi visoki kraji bodo zapuščeni in Izraelova svetišča bodo opustošena in z mečem se bom dvignil zoper Jerobeámovo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Potem je Amacjá, duhovnik iz Betela, poslal k Jerobeámu, Izraelovemu kralju, rekoč: »Amos se je zarotil zoper tebe v sredi Izraelove hiše. Dežela ni zmožna prenesti vseh njegovih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Kajti tako govori Amos: ›Jerobeám bo umrl pod mečem in Izrael bo zagotovo iz svoje lastne dežele odveden v ujetništvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Amacjá je prav tako rekel Amosu: »Oh ti videc, pojdi, pobegni proč v Judovo deželo in tam jej kruh in tam prerokuj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'toda ne prerokuj ponovno pri Betelu, kajti to je kraljeva kapela in to je kraljevi dvor.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Potem je Amos odgovoril in rekel Amacjáju: »Jaz nisem bil nikakršen prerok niti nisem bil prerokov sin, temveč sem bil črednik in obiralec sadu egiptovske smokve');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'in Gospod me je vzel, medtem ko sem sledil tropu in Gospod mi je rekel: ›Pojdi, prerokuj mojemu ljudstvu Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Zdaj torej poslušaj Gospodovo besedo: ›Praviš: ›Ne prerokuj zoper Izrael in ne kapljaj svoje besede zoper Izakovo hišo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Zato tako govori Gospod: ›Tvoja žena bo pocestnica v mestu in tvoji sinovi in tvoje hčere bodo padli pod mečem in tvoja dežela bo razdeljena z vrvico, ti pa boš umrl v oskrunjeni deželi, in Izrael bo zagotovo odšel v ujetništvo, iz svoje dežele.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Tako mi je pokazal Gospod Bog in glej, košara poletnega sadja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Rekel je: »Amos, kaj vidiš?« Rekel sem: »Košaro poletnega sadja.« Potem mi je Gospod rekel: »Konec je prišel nad moje ljudstvo Izrael; ne bom ponovno šel mimo njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Tempeljske pesmi bodo vpitje na ta dan,« govori Gospod Bog. »Na vsakem kraju bo mnogo trupel; metali jih bodo v tišini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Poslušajte to, oh vi, ki pogoltnete pomoči potrebnega, celo da revnemu v deželi storite, da propade,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'rekoč: ›Kdaj bo minil mlaj, da bomo lahko prodajali žito? In šabat, da bomo lahko odpremili pšenico, naredili škaf majhen in šekel velik in s prevaro izkrivili tehtnice?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Da lahko ubogega kupimo za srebro in pomoči potrebnega za par čevljev, da, in prodamo pleve od pšenice?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Gospod je prisegel pri Jakobovi odličnosti: »Zagotovo ne bom nikoli pozabil nobenega izmed njihovih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Mar ne bo zemlja zaradi tega trepetala in vsak človek žaloval, ki prebiva na njej? Vstala bo v celoti kakor poplava, vržena bo ven in potopljena, kakor z egiptovsko poplavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Na tisti dan se bo zgodilo,« govori Gospod Bog, »da bom soncu povzročil, da zaide opoldan in na jasen dan bom zatemnil zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Vaše praznike bom obrnil v žalovanje in vse vaše pesmi v žalostinko in privedel bom vrečevino na vsa ledja in plešavost na vsako glavo in naredil jo bom kakor žalovanje za edinim sinom in njen konec kakor grenek dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Glejte, pridejo dnevi,« govori Gospod Bog, »da bom v deželo poslal lakoto, ne lakote po kruhu niti žeje po vodi, temveč [lakoto] po poslušanju Gospodovih besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Tavali bodo od morja do morja in od severa, celo do vzhoda, tekali bodo sem ter tja, da iščejo besedo od Gospoda, pa je ne bodo našli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Na tisti dan bodo lepe device in mladeniči slabeli zaradi žeje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Tisti, ki prisegajo pri grehu Samarije in pravijo: ›Tvoj bog, oh Dan, živi;‹ in: ›Način Beeršébe živi;‹ celo padli bodo in nikoli več ne bodo ponovno vstali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Videl sem Gospoda stati na oltarju in rekel je: »Udari vratno preklado, da se bodo podboji lahko tresli, in ureži jih na glavi, vse izmed njih in jaz bom zadnje izmed njih ubil z mečem in kdor izmed njih beži, ne bo pobegnil proč in kdor se izmed njih umika, ne bo osvobojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Čeprav kopljejo v pekel, jih bo moja roka vzela od tam. Čeprav plezajo gor do nebes, jih bom od tam privedel dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Čeprav se skrijejo na vrhu Karmela, jih poiščem in vzamem od tam. Čeprav so skriti pred mojim pogledom na dnu morja, bom tam zapovedal kači in ta jih bo pičila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Čeprav gredo v ujetništvo pred svojimi sovražniki, bom tja poslal meč in ta jih bo ubil in svoje oči bom naravnal nanje za zlo in ne za dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Gospod Bog nad bojevniki je tisti, ki se dotika dežele in ta se bo stopila in vsi, ki prebivajo v njej, bodo žalovali. In ta se bo vzdignila v celoti kakor poplava in potopljena bo kakor z egiptovsko poplavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'On je tisti, ki gradi svoja nadstropja v nebesih in je utemeljil svoje krdelo na zemlji. On, ki kliče za morskimi vodami in jih izliva na obličje zemlje. Gospod je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, '» Ali mi niste kakor otroci Etiopijcev, oh Izraelovi otroci?« govori Gospod: »Mar nisem jaz Izraela privedel gor iz egiptovske dežele? In Filistejce iz Kaftorja in Sirce iz Kira?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Glejte, oči Gospoda Boga so nad grešnim kraljestvom in uničil ga bom izpred obličja zemlje; le, da ne bom popolnoma uničil Jakobove hiše,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '»Kajti glejte, zapovedal bom in Izraelovo hišo bom presejal med vse narode, kakor je žito presejano na situ, vendar niti najmanjše zrno ne bo padlo na zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Vsi grešniki mojega ljudstva bodo umrli pod mečem, ki pravijo: ›Zlo nas ne bo dohitelo niti nas ne bo srečalo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Na tisti dan bom vzdignil Davidovo šotorsko svetišče, ki je padlo in zaprl njegove vrzeli. In vzdignil bom njegove ruševine in zgradil ga bom kakor v dneh davnine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'da bodo lahko vzeli v last preostanek Edóma in vseh poganov, ki so imenovani z mojim imenom,« govori Gospod, ki to dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, '»Glejte, pridejo dnevi,« govori Gospod, »ko bo orač prehitel žanjca in tlačitelj grozdja tistega, ki seje seme, in gore bodo kapljale sladko vino in vsi hribi se bodo topili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Ponovno bom privedel ujetništvo svojega ljudstva Izraela in zgradili bodo opustošena mesta in jih poselili, in sadili bodo vinograde in pili njihovo vino; prav tako bodo naredili vrtove in jedli njihov sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Jaz jih bom zasadil na njihovi deželi in ne bodo več potegnjeni iz svoje dežele, ki sem jim jo dal,« govori Gospod, tvoj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Abdíjevo videnje. Tako govori Gospod Bog glede Edóma: »Slišali smo govorico od Gospoda in predstavnik je poslan med pogane: ›Vstanite in vzdignimo se v bitki zoper njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Glej, naredil sem te majhnega med pogani, silno si preziran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Ponos tvojega srca te je zavedel, ti, ki prebivaš v skalnih razpokah, katerega prebivališče je visoko, ki v svojem srcu praviš: ›Kdo me bo privedel dol na tla?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Čeprav se povišuješ kakor orel in čeprav si svoje gnezdo postavil med zvezde, te bom od tam privedel dol,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, '›Če pridejo k tebi tatovi, če roparji ponoči (kako si iztrebljen!), mar ne bodo kradli, dokler nimajo dovolj? Če pridejo k tebi obiralci grozdja, mar ne bodo pustili nekaj grozdov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Kako so Ezavove stvari preiskane! Kako so njegove skrite stvari poiskane!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Vsi možje tvoje zaveze so te privedli, celó k meji. Možje, ki so bili v miru s teboj, so te zavedli in prevladali zoper tebe. Tisti, ki jedo tvoj kruh, so položili rano pod teboj. Nobenega razumevanja ni v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Mar ne bom na ta dan,‹ govori Gospod, ›celo uničil modre može iz Edóma in razumevanje z Ezavove gore?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'In tvoji mogočni ljudje, oh Temán, bodo zaprepadeni do konca, z namenom, da bo vsakdo z Ezavove gore iztrebljen s pokolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Zaradi tvojega nasilja zoper tvojega brata Jakoba te bo pokrila sramota in iztrebljen boš na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Na dan, ko stojiš na drugi strani, na dan, ko tujci odvedejo njegove sile ujete in tuji ljudje vstopijo v njegova velika vrata in mečejo žrebe nad Jeruzalemom, si bil celo ti kakor eden izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Toda ne bi smel gledati na dan svojega brata, na dan, ko je postal tujec, niti ne bi smel imeti veselja nad Judovimi otroki na dan njihovega uničenja, niti ne bi smel ponosno govoriti na dan tegobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Ne bi smel vstopiti v velika vrata mojega ljudstva na dan njihove katastrofe. Da, ne bi smel gledati na njihovo stisko na dan njihove katastrofe niti rok položiti na njihovo imetje na dan njihove katastrofe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'niti ne bi smel stati na razpotju, da bi iztrebil tiste izmed njegovih, ki so pobegnili; niti ne bi smel izročiti tistih izmed njegovih, ki so pobegnili na dan stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Kajti dan Gospodov je blizu nad vsemi pogani. Kakor si ti storil, tako bo storjeno tebi. Tvoja nagrada se bo povrnila na tvojo lastno glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Kajti kakor ste pili na moji sveti gori, tako bodo vsi pogani nenehno pili, da, pili bodo in bodo požirali in bodo, kot da jih ni bilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Toda na gori Sion bo osvoboditev in tam bo svetost, in Jakobova hiša bo v last vzela njihove posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Jakobova hiša bo ogenj in Jožefova hiša plamen, Ezavova hiša pa strnišče in v njih se bodo vneli in jih požrli, in tam ne bo nobenega ostanka Ezavove hiše, kajti Gospod je to govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Tisti iz juga bodo vzeli v last goro Ezav, in tisti iz ravnine Filistejce in vzeli bodo v last Efrájimova polja in polja Samarije, Benjamin pa bo posedel Gileád.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Ujetništvo te vojske Izraelovih otrok bo vzelo v last to od Kánaancev, celó do Zarepte; in ujetništvo Jeruzalema, ki je v Sefarádu, bo posedlo južna mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Rešitelji bodo prišli na goro Sion, da sodijo Ezavovo goro, in kraljestvo bo Gospodovo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Torej Gospodova beseda je prišla k Jonu, Amitájevemu sinu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '»Vstani, pojdi v Ninive, to veliko mesto in kliči zoper njega, kajti njihova zlobnost je prišla predme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Toda Jona se je dvignil, da pred Gospodovo prisotnostjo zbeži v Taršíš in je odšel dol v Jopo in našel ladjo, ki je šla v Taršíš. Tako je plačal njeno voznino in odšel dol vanjo, da gre z njimi v Taršíš, proč od Gospodove prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Toda Gospod je na morje odposlal velik veter in tam na morju je bil mogočen vihar, tako da je ladjo hotel zlomiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Potem so bili mornarji prestrašeni in vsak je klical k svojemu bogu in odvrgli [so] blago, ki je bilo na ladji, v morje, da jo olajšajo. Jona pa je odšel dol med ladijske boke in legel ter trdno zaspal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Tako je kapitan prišel k njemu in mu rekel: »Kaj ti misliš, oh zaspanec? Vstani, kliči k svojemu Bogu, če je tako, da bo Bog mislil na nas, da se ne pogubimo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'In rekli so vsak svojemu tovarišu: »Pridimo in mečimo žrebe, da bomo lahko izvedeli zaradi čigavega vzroka je nad nami to zlo.« Tako so metali žrebe in žreb je padel na Jona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Potem so mu rekli: »Povej nam, prosimo te, zaradi čigavega vzroka je nad nami to zlo. Kakšen je tvoj poklic? In od kod prihajaš? Katera je tvoja dežela? In iz katerega ljudstva si?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Rekel jim je: »Jaz sem Hebrejec in se bojim Gospoda, Boga nebes, ki je naredil morje in kopno zemljo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Potem so bili ljudje silno prestrašeni in mu rekli: »Zakaj si to storil?« Kajti ljudje so vedeli, da je pobegnil izpred Gospodovega obličja, ker jim je povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Potem so mu rekli: »Kaj naj ti storimo, da se nam morje lahko umiri?« Kajti morje se je maščevalo in bilo viharno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Rekel jim je: »Vzemite me in me vrzite v morje. Tako se vam bo morje umirilo, kajti vem, da je zaradi mene ta veliki vihar nad vami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Kljub temu so možje trdo veslali, da jo privedejo k obali, toda niso mogli, kajti morje se je maščevalo in bilo viharno proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Zato so klicali h Gospodu in rekli: »Rotimo te, oh Gospod, rotimo te, naj se ne pogubimo zaradi življenja tega moža in ne položi na nas nedolžne krvi, kajti ti, oh Gospod, si storil, kakor ti je ugajalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Tako so vzeli Jona in ga vrgli v morje in morje je odnehalo od svojega besnenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Potem so se možje silno zbali Gospoda in Gospodu darovali klavno daritev in naredili zaobljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Torej Gospod je pripravil veliko ribo, da je pogoltnila Jona. In Jona je bil v ribjem trebuhu tri dni in tri noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Potem je Jona iz ribjega trebuha molil h Gospodu, svojemu Bogu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, '§ in rekel: »Zaradi razloga svoje stiske sem klical h Gospodu in me je slišal. Ven iz trebuha pekla sem klical in ti si slišal moj glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Kajti vrgel si me v globino, v sredo morij, in poplave so me obkrožile. Vsi tvoji veliki valovi in tvoji valovi so me preleteli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Potem sem rekel: »Vržen sem iz tvojega pogleda, vendar bom ponovno gledal k tvojemu svetemu templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Vode so me obkrožile, celó do duše, globine so me zaprle naokoli, plevel je bil zavit okoli moje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Odšel sem navzdol, k vznožjem gora. Zemlja, s svojimi zapahi, je bila okoli mene na veke, vendar si ti moje življenje privedel gor iz trohnenja, oh Gospod, moj Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Ko je moja duša slabela znotraj mene, sem se spomnil Gospoda. Moja molitev je vstopila k tebi, v tvoj sveti tempelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Tisti, ki obeležujejo lažnive ničevosti, zapuščajo svoje lastno usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Toda jaz ti bom žrtvoval z glasom zahvaljevanja; plačal bom to, kar sem se zaobljubil. Rešitev duš je od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'In Gospod je spregovoril ribi in izbljuvala je Jona na kopno zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Gospodova beseda je drugič prišla Jonu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '»Vstani, pojdi v Ninive, to veliko mesto in mu oznani pridigo, ki sem ti jo zapovedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tako je Jona vstal in odšel v Ninive, glede na Gospodovo besedo. Torej Ninive so bile silno veliko mesto treh dni potovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Jona je začel vstopati v mesto [prvi] dan potovanja ter vpil in govoril: »Še štirideset dni in Ninive bodo uničene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Tako je ljudstvo v Ninivah verovalo Bogu in razglasilo post in si nadelo vrečevino, od največjih izmed njih, celo do najmanjših izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Kajti beseda je prišla h kralju Niniv in vstal je s svojega prestola in iz sebe odložil svoje svečano oblačilo in se pokril z vrečevino in sédel na pepel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'In storil je to, da se je razglasilo in oznanilo skozi Ninive, po odloku kralja in njegovih plemičev, rekoč: »Naj niti človek niti žival, [niti] trop niti čreda ničesar ne pokusijo, naj se ne pasejo niti ne pijejo vode,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'temveč naj bosta človek in žival pokrita z vrečevino in mogočno kličeta k Bogu, da naj se oni, vsakdo izmed njih, obrnejo od svoje zle poti in od nasilja, ki je v njihovih rokah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kdo lahko pove, če se bo Bog obrnil, pokesal in odvrnil proč od svoje krute jeze, da se ne pogubimo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'In Bog je videl njihova dela, da so se odvrnili od svoje zle poti in Bog se je pokesal od zla, ki ga je rekel, da jim bo storil in tega ni storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Toda to je Jona silno razžalilo in bil je zelo jezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Molil je h Gospodu ter rekel: »Prosim te, oh Gospod, ali ni bila to moja beseda, ko sem bil še v svoji deželi? Zatorej sem prej pobegnil v Taršíš, kajti vedel sem, da si milostljiv Bog in usmiljen, počasen za jezo in zelo prijazen in se kesaš zlega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Zatorej sedaj, oh Gospod, vzemi, rotim te, moje življenje od mene, kajti zame je bolje, da umrem, kakor da živim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Potem je Gospod rekel: »Delaš pravilno, da si jezen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Tako je Jona odšel ven iz mesta in se usedel na vzhodni strani mesta in si tam postavil šotor in sedèl pod njim v senco, toliko časa, da lahko vidi kaj bo iz mesta nastalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Gospod Bog pa je pripravil bučo in ji storil, da vzklije nad Jona, da bi bila ta lahko senca nad njegovo glavo, da ga osvobodi pred njegovo žalostjo. Tako je bil Jona buče silno vesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Toda ko je naslednjega dne vstalo jutro, je Bog pripravil ličinko in ta je napadla bučo, da je ovenela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Ko je sonce vstalo, se je pripetilo, da je Bog pripravil silovit vzhodnik. Sonce je udarjalo na Jonovo glavo, da je slabel in si v sebi želel, da umre ter rekel: »Zame je boljše, da umrem, kakor da živim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Bog je Jonu rekel: »Delaš pravilno, da si jezen zaradi buče?« Ta je rekel: »Pravilno delam, da sem jezen, celó do smrti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Potem je Gospod rekel: »Usmiljenje imaš za bučo, za katero nisi delal niti ji storil, da zraste, ki je v [eni] noči vzklila in v [eni] noči propadla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'jaz pa naj ne bi prizanesel Ninivam, temu velikemu mestu, v katerem je več kot sto dvajset tisoč oseb, ki ne morejo razlikovati med svojo desnico in svojo levico in tudi veliko živine?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Beseda Gospodova, ki je prišla Miheju Moréšečanu v dneh Jotáma, Aháza in Ezekíja, Judovih kraljev, ki jo je videl glede Samarije in Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, '»Poslušajte, vsa ve ljudstva, prisluhni, oh zemlja in vsi, ki so na njej, in naj bo Gospod Bog priča zoper vas, Gospod od svojega svetega templja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Kajti glejte, Gospod prihaja iz svojega kraja in bo prišel dol in stopil na visoke kraje zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Gore bodo stopljene pod njim in doline bodo razklane kakor vosek pred ognjem in kakor vode, ki so izlite dol po strmini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Zaradi Jakobovega prestopka je vse to in zaradi grehov Izraelove hiše. Kaj je Jakobov prestopek? Mar ni Samarija? In kaj so visoki Judovi kraji? Ali niso oni Jeruzalem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Zato bom Samarijo naredil kakor kup polja in kakor zasajanje vinograda in njene kamne bom izlil dol v dolino in odkril bom njene temelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Vse njene rezane podobe bodo stolčene na koščke in vsa njena plačila bodo požgana z ognjem in vse njene malike bom pustil zapuščene, kajti to je zbirala od plačila pocestnice in vrnili se bodo k plačilu pocestnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Zato bom tarnal in tulil, šel bom slečen in nag. Naredil bom tarnanje kakor zmaji in žalovanje kakor sove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Kajti njena rana je nezaceljiva, kajti ta je prišla v Juda; prišla je v velika vrata mojega ljudstva, celó do Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Tega ne razglasite pri Gatu, sploh ne jokajte. V Bet Leáfri se valjajte v prahu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Odidi proč, ti prebivalec Šafírja, ki imaš svojo sramoto golo. Prebivalec Caanána ne pridi naprej v žalovanju Bet Ecela; ta bo od vas prejel svojo postojanko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Kajti prebivalec Maróta je skrbno čakal na dobro, toda zlo je prišlo dol od Gospoda k velikim vratom Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Oh ti prebivalec Lahíša, naprezi bojni voz k hitri živali. Ta je začetek greha sionski hčeri, kajti prestopke Izraela je bilo najti v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Zato boš dal darila Moréšet Gatu. Ahzíbove hiše bodo laž Izraelovim kraljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Vendar bom k tebi privedel dediča, oh prebivalec Marešá. Prišel bo k Adulámu, Izraelovi slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Naredi se plešast in ostriži se zaradi svojih prefinjenih otrok. Svojo plešavost povečaj kakor orel, kajti od tebe so odšli v ujetništvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, '»Gorje tistim, ki snujejo krivičnost in na svojih posteljah počnejo zlo! Ko je jutro svetlo, to izvajajo, ker je to v moči njihove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Poželijo si polja in jih zavzamejo z nasiljem, hiše in si jih vzamejo. Tako zatirajo moža, njegovo hišo in njegovo dediščino, celo moža in njegovo dediščino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Zato tako govori Gospod: »Glej, zoper to družino snujem zlo, od katerega svojih vratov ne boste odstranili niti ne boste hodili ošabno, kajti ta čas je hud.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Na tisti dan bo nekdo vzel prispodobo zoper vas in žaloval z otožnim žalovanjem in rekel: ›Popolnoma bomo oplenjeni. Spremenil je delež mojega ljudstva. Kako je to odstranjeno od mene! Obračajoč se stran je razdelil naša polja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Zato ne boš imel nobenega, ki bi z žrebom vrgel vrvico v Gospodovi skupnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '»Ne prerokujte,« pravijo tistim, ki prerokujejo. Naj jim ne prerokujejo, da oni ne bi odvrnili sramote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Oh ti, ki si poimenovan Jakobova hiša, mar je Gospodov duh omejen? Mar so to njegova dejanja? Ali moje besede ne delajo dobro tistemu, ki hodi pošteno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Celo od davnine je moje ljudstvo vstalo kakor sovražnik. Ogrinjalo z oblačilom vlečete s tistih, ki varno hodijo mimo, kakor ljudje, ki so nasprotni vojni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Ženske mojega ljudstva ste metali iz njihovih prijetnih hiš; njihovim otrokom ste mojo slavo vzeli na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Vstanite in odidite, kajti to ni vaš počitek. Ker je ta [dežela] omadeževana, vas bo uničila, celo z bolečim uničenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Če človek, ki hodi v duhu in neresnici, laže, rekoč: ›Prerokoval ti bom o vinu in o močni pijači,‹ bo ta torej prerok temu ljudstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Zagotovo te bom vsega združil, oh Jakob, zagotovo bom zbral Izraelov preostanek. Skupaj jih bom postavil kakor ovce iz Bocre, kakor trop v sredi njihove staje. Naredili bodo velik hrup zaradi razloga množice ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Lomilec je prišel gor prednje. Vlomili so in prešli skozi velika vrata in pri njih odšli ven, in njihov kralj bo šel pred njimi in Gospod jim bo na čelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Rekel sem: »Poslušajte, prosim vas, oh Jakobovi poglavarji in vi princi Izraelove hiše: › Mar ni to za vas, da poznate sodbo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Ki sovražite dobro in ljubite zlo, ki njihovo kožo trgate iz njih in njihovo meso iz njihovih kosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'ki tudi jeste meso mojega ljudstva in odirate njihovo kožo iz njih; in lomijo njihove kosti in jih sekajo na koščke, kakor za lonec in kakor meso znotraj kotla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Potem bodo klicali h Gospodu, toda ne bo jih slišal. Ob tistem času bo celo svoj obraz skril pred njimi, kakor so se oni slabo obnašali v svojih ravnanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tako govori Gospod glede prerokov, ki mojemu ljudstvu povzročajo, da se moti, ki grizejo s svojimi zobmi in kličejo: ›Mir;‹ in kdor ne daje v njihova usta, pripravljajo celo vojno zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Zato bo nad vami noč, da ne boste imeli videnja; in ta vam bo temna, da ne boste vedeževali; in sonce bo zašlo nad preroki in dan bo otemnel nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Takrat bodo vidci osramočeni in vedeževalci zbegani. Da, vsi bodo pokrivali svoje ustnice, kajti tam ni odgovora od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Toda resnično, jaz sem po Gospodovem duhu poln oblasti, sodbe in moči, da Jakobu razglasim njegov prestopek in Izraelu njegov greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Poslušajte to, prosim vas, vi poglavarji Jakobove hiše in princi Izraelove hiše, ki se vam gnusi sodba in izkrivljate vso pravico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Sion gradijo s krvjo in Jeruzalem s krivičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Njihovi poglavarji sodijo zaradi nagrade in njihovi duhovniki učijo zaradi plačila in preroki vedežujejo zaradi denarja. Vendar ali se bodo naslonili na Gospoda in rekli: › Mar ni Gospod med nami? Nobeno zlo ne more priti nad nas.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Zato bo zaradi vas Sion preoran kakor polje in Jeruzalem bo spremenjen v razvaline in gore [te] hiše kakor visoki kraji gozda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Toda v poslednjih dneh se bo zgodilo, da bo gora hiše Gospodove utrjena na vrhu gora in ta bo povišana nad hribe, in ljudstvo se bo stekalo k njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'In številni narodi bodo prišli ter rekli: »Pridite, pojdimo gor do Gospodove gore in do hiše Jakobovega Boga in učil nas bo svojih poti in hodili bomo po njegovih stezah, kajti postava bo izšla iz Siona in Gospodova beseda iz Jeruzalema.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Sodil bo med mnogimi ljudstvi in oštel oddaljene močne narode in svoje meče bodo prekovali v lemeže in svoje sulice v obrezovalne kavlje. Narod ne bo vzdignil meča zoper narod niti se ne bodo več učili vojskovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Temveč bodo sedeli, vsak pod svojo trto in pod svojim figovim drevesom in nihče jih ne bo strašil, kajti usta Gospoda nad bojevniki so to govorila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Kajti vsa ljudstva bodo hodila, vsako v imenu svojega boga, mi pa bomo hodili v imenu Gospoda, svojega Boga, na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Na ta dan,« govori Gospod, »bom zbral tisto, kar šepa in zbral tisto, kar je izgnano in tisto, kar sem prizadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Tisto, kar šepa, bom naredil ostanek in tisto, ki je bilo vrženo daleč proč, močan narod, in Gospod bo kraljeval nad njimi na gori Sion od zdaj naprej, celo na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Ti pa, oh stolp tropa, oporišče hčere sionske, k tebi bo prišlo, celo prvo gospostvo, kraljestvo bo prišlo k jeruzalemski hčeri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Zakaj torej kričiš na glas? Mar ni kralja v tebi? Je tvoj svetovalec izginil? Kajti ostre bolečine so te zgrabile kakor žensko v porodnih mukah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Bodi v bolečini in trudi se, da rodiš, oh hči sionska, kakor ženska v porodnih mukah, kajti sedaj boš šla naprej iz mesta in prebivala boš na polju in šla boš celo do Babilona. Tam boš osvobojena, tam te bo Gospod odkupil iz roke tvojih sovražnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Sedaj je tudi mnogo narodov zbranih zoper tebe, ki pravijo: ›Naj bo omadeževana in naj naše oko gleda na Sion.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Toda oni ne poznajo Gospodovih misli niti ne razumejo njegovega nasveta, kajti zbral jih bo kakor snope na mlatišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Vzdigni se in mlati, oh hči sionska, kajti tvoj rog bom naredil železo in tvoja kopita bom naredil bron. Na koščke boš zdrobila številna ljudstva in njihov dobiček bom posvetil Gospodu in njihovo imetje Gospodu celotne zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Sedaj se zberi v krdela, oh hči krdel. Zoper nas je položil obleganje. Izraelovega sodnika bodo s palico udarjali na lice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, '§ Toda ti, Betlehem Efráta, čeprav si majhen med Judovimi tisočimi, vendar bo iz tebe prišel k meni tisti, ki bo vladar v Izraelu, katerega izhodi so bili od davnine, od večnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Zato jih bo predal do časa, ko tista, ki je imela porodne muke, rodi. Potem se bo preostanek njegovih bratov vrnil k Izraelovim otrokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'In stal bo in pasel v Gospodovi moči, v veličastvu imena Gospoda, svojega Boga; in oni bodo prebivali, kajti sedaj bo velik do koncev zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'In ta mož bo mir, ko bo Asirec prišel v našo deželo, in ko bo teptal v naših palačah, takrat bomo zoper njega vzdignili sedem pastirjev in osem glavnih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'In z mečem bodo opustošili deželo Asirije in Nimródovo deželo na njenih vhodih. Tako nas bo osvobodil pred Asirci, ko pride v našo deželo in ko mendra znotraj naših meja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Jakobov preostanek bo v sredi številnih ljudstev, kakor rosa od Gospoda, kakor nalivi na travo, ki ne čakajo na človeka niti ne čakajo na človeške sinove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Jakobov preostanek bo med pogani v sredi številnega ljudstva kakor lev med gozdnimi živalmi, kakor mlad lev med tropi ovc. Če gre ta skozi, tako pomendra kakor raztrga na koščke in nihče ne more osvoboditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Tvoja roka bo vzdignjena nad tvoje nasprotnike in vsi tvoji sovražniki bodo iztrebljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'In zgodilo se bo na tisti dan,« govori Gospod, »da bom iz tvoje srede iztrebil tvoje konje in uničil tvoje bojne vozove');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'in iztrebil bom mesta tvoje dežele in zrušil vsa tvoja oporišča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'in iztrebil bom čaranja iz tvoje roke in ne boš več imel napovedovalcev usode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Tudi tvoje rezane podobe bom iztrebil in tvoje stoječe podobe iz tvoje srede in ne boš več oboževal dela svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Izruval bom tvoje ašere iz tvoje srede. Tako bom uničil tvoja mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Nad pogani bom izvršil maščevanje v jezi in razjarjenosti, takšno, o kakršnem niso slišali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Poslušajte sedaj, kar govori Gospod: »Vstani, poteguj se pred gorami in naj hribi slišijo tvoj glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Prisluhnite, oh gore, Gospodovo polemiko in vi močni temelji zemlje, kajti Gospod ima polemiko s svojim ljudstvom in pravdal se bo z Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Oh moje ljudstvo, kaj sem ti storil? In v čem sem te izmučil? Pričaj zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Kajti privedel sem te gor iz egiptovske dežele in te odkupil iz hiše služabnikov in pred teboj sem poslal Mojzesa, Arona in Mirjam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Oh moje ljudstvo, spomnite se sedaj kaj je svetoval moábski kralj Balák, in kaj mu je Beórjev sin Bileám odgovoril iz Šitíma do Gilgála, da boste lahko spoznali Gospodovo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'S čim bom prišel pred Gospoda in se priklonil pred vzvišenim Bogom? Naj pridem predenj z žgalnimi daritvami, z enoletnimi teleti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Mar bo Gospod zadovoljen s tisoči ovnov ali z deset tisočimi rekami olja? Naj dam svojega prvorojenca za svoj prestopek, sad mojega telesa za greh moje duše?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Pokazal ti je, oh človek, kaj je dobro. Kaj zahteva Gospod od tebe, razen da ravnaš pravično, da ljubiš usmiljenje in da ponižno hodiš s svojim Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, '§ Gospodov glas kliče v mesto in človek modrosti bo videl tvoje ime. Poslušaj palico in tistega, ki jo je določil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, '§ Ali so še zakladi zlobnosti v hiši zlobnega in skopa mera, kar je gnusno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Mar jih bom štel za čiste z zlobnimi tehtnicami in s torbo varljivih uteži?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Kajti njegovi bogataši so polni nasilja in njegovi prebivalci so govorili laži in njihov jezik je varljiv v njihovih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Zato te bom tudi jaz naredil bolnega, ko te bom udarjal, ko te bom pustošil zaradi tvojih grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Jedel boš, toda ne boš nasičen in tvoja sestradanost bo v tvoji sredi in prijel boš, toda ne boš rešil in to, kar rešiš, bom izročil meču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Sejal boš, toda ne boš žel; tlačil olive, toda z oljem se ne boš mazilil; in sladko vino, toda vina ne boš pil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Kajti držijo se Omrijevih zakonov in vseh del Ahábove hiše in vi se ravnate po njihovih nasvetih, da bi te naredil za opustošenje in njegove prebivalce za posmeh. Zatorej boste nosili grajo mojega ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Gorje meni! Kajti sem kakor, ko so zbrali poletne sadove, kakor paberkovanje grozdne trgatve. Tam ni nobenega grozda, da bi ga jedel; moja duša si je želela prvi sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Dober človek je izginil z zemlje in nobenega poštenega ni med ljudmi. Vsi v zasedi prežijo na kri, vsak svojega brata z mrežo lovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Da lahko počnejo zlo, iskreno, z obema rokama. Princ zahteva in sodnik povprašuje po nagradi. In velik človek, on izreka svojo pogubno željo. Tako to sprevračajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Najboljši izmed njih je kakor osat. Najpokončnejši je ostrejši, kakor trnova ograja. Dan tvojih stražarjev in tvojega obiskanja prihaja; sedaj bo [to] njihova zmedenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne zaupaj prijatelju, ne položi zaupanja v vodiča, varuj vrata svojih ust pred njo, ki leži v tvojem naročju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Kajti sin ne spoštuje očeta, hči se vzdiguje zoper svojo mater, snaha zoper svojo taščo. Človeku so sovražniki ljudje iz njegove lastne hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Zatorej bom gledal h Gospodu, čakal bom na Boga rešitve moje duše. Moj Bog me bo slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne razveseljuj se zoper mene, oh moja sovražnica. Ko padem, bom vstal; ko sedim v temi, mi bo Gospod svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Prenašal bom Gospodovo ogorčenje, ker sem grešil zoper njega, dokler ne brani mojega primera in ne izvrši sodbe zame. Privedel me bo k svetlobi in gledal bom njegovo pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Potem bo tista, ki je moja sovražnica, to videla in sramota bo pokrila tisto, ki mi je rekla; ›Kje je Gospod, tvoj Bog?‹ Moje oči jo bodo gledale. Sedaj bo pomendrana kakor ulično blato.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, '§ Na dan, ko naj bi bili zgrajeni tvoji zidovi, na tisti dan bo odlok odstranjen daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Na ta dan bo tudi on prišel k tebi, celo iz Asirije in od utrjenih mest in od trdnjave, celo do reke in od morja do morja in od gore do gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Vendar bo dežela zapuščena zaradi tistih, ki prebivajo v njej, zaradi sadov njihovih početij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pasi svoje ljudstvo s svojo palico, trop svoje dediščine, ki prebiva osamljeno v goščavi, v sredi Karmela. Naj se pasejo v Bašánu in Gileádu, kakor v dneh davnine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Kakor v dneh tvojega prihoda iz egiptovske dežele mu bom pokazal čudovite stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Narodi bodo videli in bodo zbegani ob vsej njihovi moči. Svojo roko bodo položili na svoja usta, njihova ušesa bodo gluha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Prah bodo lizali kakor kača, iz svojih lukenj bodo prilezli kakor črvi zemlje. Bali se bodo Gospoda, našega Boga in bali se bodo zaradi tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kdo je Bog, podoben tebi, ki oprošča krivičnost in gre mimo prestopka, preostanka svoje dediščine? Svoje jeze ne ohranja na veke, ker se razveseljuje v usmiljenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Ponovno se bo obrnil, nad nami bo imel sočutje, podjarmil bo naše krivičnosti in vse njihove grehe boš vrgel v globine morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Jakobu boš izvršil resnico in Abrahamu usmiljenje, ki si ga od dni davnine prisegel našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Breme Niniv. Knjiga videnja Nahuma Elkošána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Bog je ljubosumen in Gospod maščuje; Gospod maščuje in je razjarjen; Gospod se bo maščeval na svojih nasprotnikih in on prihranja bes za svoje sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Gospod je počasen za jezo in silen v moči in sploh ne bo oprostil tožbe zlobnih. Gospod ima svojo pot v vrtinčastem vetru in v viharju in oblaki so prah njegovih stopal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Ošteva morje in ga osušuje in suši vse reke. Bašán peša in Karmel in cvet Libanona peša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Gore se tresejo ob njem in hribi se topijo in zemlja je sežgana ob njegovi prisotnosti, da, zemeljski [krog] in vsi, ki prebivajo na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kdo lahko obstane pred njegovim ogorčenjem? In kdo lahko prebiva v okrutnosti njegove jeze? Njegova razjarjenost je izlita kakor ogenj in skale so vržene dol po njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Gospod je dober, oporišče v dnevu stiske in pozna tiste, ki zaupajo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Toda s preplavljajočo povodnjijo bo naredil popoln konec njihovemu kraju in tema bo zasledovala njegove sovražnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Kaj si domišljate zoper Gospoda? On bo naredil popoln konec. Stiska se drugič ne bo vzdignila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Kajti medtem ko so zviti skupaj kakor trnje in medtem ko so pijani kakor pijanci, bodo požrti kakor popolnoma suho strnišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Nekdo je izšel iz tebe, ki si je zoper Gospoda domišljal hudobijo, zloben svetovalec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tako govori Gospod: »Čeprav so tihi in prav tako številni, vendar bodo tako posekani, ko bo šel skozi. Čeprav sem te prizadel, te ne bom več prizadel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Kajti sedaj bom zlomil njegov jarem iznad tebe in tvoje vezi razpočil narazen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Gospod je glede tebe dal zapoved, da se ne bo več sejalo iz tvojega imena. Iz hiše tvojih bogov bom iztrebil izrezljano podobo in ulito podobo. Pripravil ti bom grob; kajti hudoben si.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Poglej na gorah stopala tistega, ki prinaša dobre novice, ki razglaša mir! Oh Juda, ohranjaj svoje slovesne praznike, izpolni svoje zaobljube, kajti zlobni ne bo šel več skozte; popolnoma je uničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Kdor razbija na koščke je prišel gor, pred tvoj obraz. Varuj oporišče, pazi na pot, naredi svoja ledja močna, mogočno utrdi svojo moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Kajti Gospod je odvrnil Jakobovo odličnost kakor odličnost Izraela, kajti izpraznjevalci so jih izpraznili in skazili njihove trtne mladike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Ščit njegovih mogočnih mož je pordečel, hrabri možje so v škrlatu. Bojni vozovi bodo s plamenečimi baklami na dan njegove priprave in ciprese bodo strašno stresene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Bojni vozovi bodo besneli po ulicah, zadevali se bodo drug ob drugega na širokih poteh, zdeli se bodo kakor bakle, tekli bodo kakor bliski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Spomnil se bo svojih vrlih. Spotaknili se bodo v svoji hoji, podvizali se bodo k njegovemu obzidju in obramba bo pripravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Velika vrata rek bodo odprta in palača se bo raztopila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, '§ Huzzab bo odvedena v ujetništvo, privedena bo gor in njene služabnice jo bodo vodile kakor z glasom golobic, ki se bijejo po svojih prsih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Toda Ninive so od davnine podobne vodnemu zbiralniku, vendar bodo pobegnile. »Stojte, stojte;« bodo kričali toda, nihče ne bo pogledal nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Vzemite plen srebra, vzemite plen zlata, kajti ni konca zaloge in slave vseh dragocenih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Prazna je, izpraznjena in opustošena. Srce se topi in kolena udarjajo skupaj in precej bolečine je v vseh ledjih in vsi njihovi obrazi zbirajo črnino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kje je prebivališče levov in kraj za hranjenje mladih levov, kjer je hodil lev, celó star lev in levji mladič in nihče ju ni prestrašil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Lev je raztrgal na koščke dovolj za svoje mladiče in zadavil za svoje levinje in svoje jame napolnil s plenom in svoje brloge z ropom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, '»Glej, jaz sem zoper tebe,« govori Gospod nad bojevniki, »in jaz bom sežgal njene bojne vozove v dimu in meč bo použil tvoje mlade leve in iztrebil bom tvoj plen z zemlje in glasu tvojih poslancev ne bo več slišati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Gorje krvoločnemu mestu! To je polno laži in ropa, plen ga ne zapusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Tlesk biča in hrup ropotanja koles in drvečih konj in poskakujočih bojnih vozov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Konjenik dviguje tako bleščeč meč kakor lesketajočo sulico in tam je množica umorjenih in veliko število trupel in tam ni konca njihovih trupel; spotikajo se na njihovih truplih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Zaradi številnih vlačugarstev dobro favorizirane pocestnice, gospodarice čaranj, ki prodaja narode preko svojih vlačugarstev in družine preko svojih čaranj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '»Glej, jaz sem zoper tebe,« govori Gospod nad bojevniki, »in odkril bom krajce tvojega oblačila nad tvojim obrazom in narodom bom pokazal tvojo nagoto in kraljestvom tvojo sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Nate bom vrgel gnusno umazanijo in te naredil ogabno in te postavil kakor predmet zaničevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'In zgodilo se bo, da bodo vsi, ki gledajo nate, pobegnili od tebe in rekli: ›Ninive so opustošene, kdo jih bo objokoval? Od kod bom iskal tolažnike zate?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Mar si boljša kakor gosto naseljen No, ki je bil umeščen med reke, ki je imel okoli sebe vode, katerega obrambni zid je bilo morje in je bil njegov zid od morja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiopija in Egipt sta bila njegova moč in ta je bila neskončna; Put in Libija sta bila tvoja pomočnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Vendar je bil odveden proč, odšel je v ujetništvo. Tudi njegovi mladi otroci so bili raztreščeni na koščke na vrhu vseh ulic in metali so žrebe za njegove častitljive može in vsi njegovi veliki možje so bili zvezani v verigah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tudi ti boš pijana. Skrita boš, tudi ti boš iskala moč zaradi sovražnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Vsa tvoja oporišča bodo podobna figovemu drevesu s sadom prvih fig. Če bodo potresena, bodo torej padla v usta jedca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Glej, tvoje ljudstvo v tvoji sredi so ženske. Velika vrata tvoje dežele bodo na široko odprta tvojim sovražnikom. Ogenj bo pogoltnil tvoje zapahe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Zajemi vode zaradi obleganja, utrdi svoja oporišča. Pojdi v ilo in tlači malto, ojačaj opekarsko peč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam te bo požrl ogenj, odsekal te bo meč, pojedel te bo kakor škodljiva gosenica. Naredi se tako številna kakor škodljiva gosenica, naredi se tako številna kakor leteče kobilice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Pomnožila si svoje trgovce nad [številom] zvezd neba. Škodljiva gosenica uničuje in odleti proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tvoji kronani so kakor leteče kobilice in tvoji poveljniki kakor velike kobilice, ki taborijo na ograjah na mrzel dan, toda ko vstane sonce, odletijo proč in nihče ne ve za prostor, kjer so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tvoji pastirji dremajo, oh asirski kralj, tvoji plemiči bodo prebivali v prahu, tvoje ljudstvo je razkropljeno po gorah in nihče jih ne zbira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ni ozdravljenja tvojega zloma, tvoja rana je boleča. Vsi, ki slišijo objavo o tebi, bodo z rokami ploskali nad teboj, kajti nad kom tvoja zlobnost ni nenehno besnela?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Breme, ki ga je videl prerok Habakúk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Oh Gospod, doklej bom klical in ne boš slišal! Celó klical k tebi o nasilju in ne boš rešil!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Zakaj mi kažeš krivičnost in mi povzročaš, da gledam gorje? Kajti plenjenje in nasilje sta pred menoj in tam so takšni, ki vzdigujejo spor in prepir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Zatorej je postava ohlapna in sodba nikoli ne gre naprej, kajti zlobni obdaja pravičnega, zato izhaja napačna sodba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Poglejte med pogane in preudarite in se silno čudite, kajti jaz bom naredil delo, delo v vaših dneh, ki ga ne boste verjeli, čeprav bi vam bilo povedano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Kajti glejte, vzdignil bom Kaldejce, ki so zagrenjen in nagel narod, ki bo korakal skozi širino dežele, da vzame v last prebivališča, ki niso njihova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Strašni so in grozni. Njihova sodba in njihovo dostojanstvo bo izšlo iz njih samih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, '§ Tudi njihovi konji so hitrejši kakor leopardi in bolj kruti kakor večerni volkovi. Njihovi konjeniki se bodo razprostrli in njihovi konjeniki bodo prišli od daleč. Leteli bodo kakor orel, ki hiti, da žre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, '§ Vsi bodo prišli zaradi nasilja. Njihovi obrazi bodo izpiti kakor vzhodnik in ujetništva bodo zbrali kakor peska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Norčevali se bodo iz kraljev in princi jim bodo prezir. Zasmehovali bodo vsako oporišče, kajti nagrmadili bodo prah in ga zavzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Potem se bo njegov um spremenil, šel bo mimo in se pohujšal, prištevajoč to svojo moč svojemu bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Mar nisi ti od večnosti, oh Gospod, moj Bog, moj Sveti? Ne bomo umrli. Oh Gospod, za sodbo si jih odredil. Oh mogočni Bog, utrdil si jih za grajanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Tvoje oči so preveč čiste, da bi gledal zlo in ne moreš gledati na krivičnost. Zakaj torej gledaš na tiste, ki postopajo zahrbtno in zadržuješ svoj jezik, ko zlobni požira človeka, ki je pravičnejši kakor on?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'In ljudi delaš kakor ribe morja, kakor plazeče stvari, ki nimajo nobenega vladarja nad seboj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Vse izmed njih privlečejo s trnkom, lovijo jih v svojo mrežo in jih zbirajo v svojo vlako; zato se veselijo in so veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Zato darujejo svoji mreži in svoji vrši zažigajo kadilo, ker po njima je njihov delež obilen in njihova hrana obilna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Ali bodo zato praznili svojo mrežo in ne bodo nenehno prizanašali pobijanju narodov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Stal bom na svoji straži in se postavil na stolp in stražil bom, da vidim kaj mi bo rekel in kaj bom odgovoril, ko bom pograjan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Gospod mi je odgovoril in rekel: »Zapiši videnje in ga naredi razločnega na ploščah, da bo lahko tekel, kdor ga bo bral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Kajti še je videnje za določeni čas, toda ob koncu bo govorilo in ne bo lagalo. Čeprav odlaša, čakaj nanj, kajti zagotovo bo prišlo, ne bo odlašalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Glej, njegova duša, ki je povzdignjena, ni iskrena v njem, toda pravični bo živel po svoji veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Da, prav tako, ker greši z vinom, je ponosen človek niti se ne drži doma, ki svojo željo povečuje kakor pekel in je kakor smrt in ne more biti nasičen, temveč k sebi zbira vse narode in k sebi kopiči vsa ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Mar ne bodo vsi ti vzdignili prispodobe zoper njega in zbadljiv pregovor zoper njega in rekli: »Gorje tistemu, ki povečuje to, kar ni njegovo!« Doklej? In tistemu, ki se oblaga z zastavljenimi dobrinami!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Mar se ne bodo nenadoma dvignili tisti, ki te bodo grizli in se prebudili tisti, ki te bodo mučili, ti pa jim boš v plen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Ker si oplenil mnoge narode, bo ves preostanek ljudstva oplenil tebe zaradi človeške krvi in zaradi nasilja deželi, mestu in vsem, ki prebivajo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Gorje tistemu, ki hlepi s hudobno pohlepnostjo za svojo hišo, da bi lahko postavil svoje gnezdo na visoko, da bi bil lahko osvobojen pred močjo zla!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Svetoval si sramoto svoji hiši, s tem, da si uničil mnoga ljudstva in si grešil zoper svojo dušo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Kajti kamen bo vpil iz zidu in bruno iz lesa mu bo odgovarjalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Gorje tistemu, ki gradi mesto s krvjo in mesto utrjuje s krivičnostjo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Glej, mar ni to od Gospoda nad bojevniki, da se bo ljudstvo trudilo v samem ognju in se bo ljudstvo izmučilo za samo ničnost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Kajti zemlja bo napolnjena s spoznanjem Gospodove slave, kakor vode pokrivajo morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Gorje mu, ki daje svojemu bližnjemu piti, ki svoje mehove polaga k njemu in ga dela tudi pijanega, da bi lahko gledal na njihovo nagoto!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Napolnjen si s sramoto namesto s slavo. Pij tudi ti in naj bo tvoja prednja kožica odkrita. Čaša Gospodove desnice bo obrnjena k tebi in sramotno pljuvanje bo na tvoji slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Kajti nasilje Libanona te bo pokrilo in plen živali, ki si jih prestrašil zaradi človeške krvi in zaradi nasilja dežele, mesta in vseh, ki prebivajo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Kaj koristi rezana podoba, ki jo je njen izdelovalec izrezal; ulita podoba in učiteljica laži, da izdelovalec svojega dela zaupa vanjo, da izdeluje neme malike?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Gorje tistemu, ki govori lesu: »Zbudi se.« Nememu kamnu: »Vstani, ta bo učil!« Glej, ta je prevlečen z zlatom in srebrom in tam, v njegovi sredi, sploh ni nobenega diha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Toda Gospod je v svojem svetem templju. Naj vsa zemlja ohrani molk pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Molitev preroka Habakúka na Šiginot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Oh Gospod, slišal sem tvoj govor in bil sem prestrašen. Oh Gospod, oživi svoje delo v sredi let, v sredi let ga daj spoznati, v besu se spomni usmiljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Bog je prišel iz Temána in Sveti z gore Parán. Sela. Njegova slava je pokrila nebo in zemlja je bila polna njegove hvale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Njegov sijaj je bil kakor svetloba; imel je rogove, izhajajoče iz njegove roke in tam je bilo skrivališče njegove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Pred njim je odšla kužna bolezen in goreče oglje je šlo naprej ob njegovih stopalih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Stal je in izmeril zemljo. Pogledal je in razgnal narode in večne gore so bile razkropljene, starodavni hribi so se upognili. Njegove poti so večne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Videl sem kušánske šotore v stiski in zavese midjánske dežele so trepetale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Mar je bil Gospod nezadovoljen zoper reke? Je bila tvoja jeza zoper reke? Je bil tvoj bes zoper morje, da si jahal na svojih konjih in svojih bojnih vozovih rešitve duš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Tvoj lok je bil razgaljen, glede na prisege rodov, celo tvojo besedo. Sela. Zemljo si oklenil z rekami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Gore so te videle in so trepetale, preplavljanje vodá je šlo mimo, globina je izustila svoj glas in svoje roke vzdignila na visoko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sonce in luna sta mirno stala v svojem prebivališču. Ob svetlobi tvojih puščic sta šla in ob siju tvoje lesketajoče sulice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'V ogorčenju si korakal skozi deželo, pogane si mlatil v jezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Šel si naprej zaradi rešitve duš svojega ljudstva, celó zaradi rešitve duš s svojim maziljenim. Ti raniš poglavarja hiše zlobnih z razkritjem temelja do vratu. Sela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Z njegovimi kopji si prebodel poglavarja njegovih vasi. Ven so prišli kakor vrtinčast veter, da me razkropijo. Njihovo razveseljevanje je bilo kakor, da bi na skrivaj požrli ubogega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Skozi morje si hodil s svojimi konji, skozi kup velikih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Ko sem slišal, je moj trebuh trepetal, moje ustnice so drgetale ob glasu. Gniloba je vstopila v moje kosti in v sebi sem trepetal, da bi lahko počival na dan stiske. Ko prihaja gor k ljudstvu, jih bo preplavil s svojimi krdeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Čeprav figovo drevo ne bo cvetelo niti ne bo sadu na trtah, [čeprav] bo trud oljke odpovedal in polja ne bodo obrodila nobene hrane; [čeprav] bo trop odrezan od staje in v hlevih ne bo črede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'se bom vendar veselil v Gospodu, užival bom v Bogu rešitve moje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Gospod Bog je moja moč in on bo moja stopala naredil podobna košutinim stopalom in dal mi bo, da hodim na svojih visokih krajih. Vodilnemu pevcu na moja glasbila na strune.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Gospodova beseda, ki je prišla Sofoniju, sinu Kušíja, sinú Gedaljája, sinú Amarjá, sinú Hezekija, v dneh Jošíja, Amónovega sina, Judovega kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '»Popolnoma bom použil vse stvari iz dežele,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, '»Použil bom človeka in žival. Z zlobnimi bom použil perjad neba in ribe morja in kamne spotike in človeka bom iztrebil iz dežele,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, '»Prav tako bom svojo roko iztegnil nad Juda in nad vse prebivalce Jeruzalema in iztrebil bom preostanek Báala iz tega mesta in ime Kemarimov z duhovniki;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'in tiste, ki obožujejo vojsko neba na hišnih strehah; in tiste, ki obožujejo in ki prisegajo pri Gospodu in prisegajo pri Milkómu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'in tiste, ki so obrnjeni nazaj od Gospoda; in tiste, ki niso iskali Gospoda niti poizvedovali za njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Mirujte ob prisotnosti Gospoda Boga, kajti dan Gospodov je pri roki, kajti Gospod je pripravil klavno daritev, povabil je svoje goste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, '»In zgodilo se bo, na dan Gospodove klavne daritve, da bom kaznoval prince in kraljeve otroke in vse tiste, ki so oblečeni s tujo obleko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'V istem dnevu bom kaznoval tudi vse tiste, ki poskakujejo na pragu, ki napolnjujejo hiše svojih gospodarjev z nasiljem in prevaro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Na tisti dan se bo zgodilo,« govori Gospod, » da bo glas vpitja od Ribjih velikih vrat in tuljenja od drugih in veliko lomljenje s hribov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Tulite, vi prebivalci Maltarke, kajti vse trgovsko ljudstvo je posekano. Vsi tisti, ki nosijo srebro, so iztrebljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Ob tistem času se bo zgodilo, da bom Jeruzalem preiskal s svetilkami in kaznoval ljudi, ki so naseljeni na svojih usedlinah, ki v svojem srcu pravijo: › Gospod ne bo storil dobrega niti ne bo storil zlega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Zato bodo njihove dobrine postale plen in njihove hiše opustošenje. Prav tako bodo gradili hiše, toda ne bodo jih poselili in sadili bodo vinograde, toda od njihovega vina ne bodo pili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Gospodov véliki dan je blizu, ta je blizu in silno hiti, celó glas Gospodovega dneva. Mogočen človek bo tam grenko jokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Tisti dan je dan besa, dan stiske in tegobe, dan pustote in opustošenja in dan teme in mračnosti, dan oblakov in goste teme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'dan šofarja in alarma zoper utrjena mesta in zoper visoke stolpe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, '»Na ljudi bom privedel tegobo, da bodo hodili kakor slepi ljudje, ker so grešili zoper Gospoda in njihova kri bo izlita kakor prah in njihovo meso kakor gnoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Niti jih njihovo srebro niti njihovo zlato ne bo moglo osvoboditi na dan Gospodovega besa, temveč bo celotna dežela použita z ognjem njegove ljubosumnosti, kajti celo zelo hitro se bo znebil vseh tistih, ki prebivajo v deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Zberite se skupaj, da, zberite se skupaj, oh narod, ki ni zaželen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Preden se rodi odlok, preden dan mine kakor pleve, preden pride nad vas kruta Gospodova jeza, preden pride nad vas dan Gospodove jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Iščite Gospoda, vsi vi krotki na zemlji, ki ste vršili njegovo sodbo, iščite pravičnost, iščite krotkost. Morda bo, da boste skriti na dan Gospodove jeze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Kajti Gaza bo zapuščena in Aškelón opustošenje. Ašdód bodo izgnali opoldan in Ekrón bo izkoreninjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Gorje prebivalcem morske obale, narodu Keretéjcev! Gospodova beseda je zoper tebe, oh Kánaan, dežela Filistejcev, celo uničil te bom, da tam ne bo nobenega prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Morska obala bodo pašniki in koče za pastirje in staje za trope.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Obala bo za preostanek Judove hiše. Pasli se bodo na njej. V aškelónskih hišah bodo zvečer legli, kajti Gospod, njihov Bog, jih bo obiskal in odvrnil njihovo ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '»Slišal sem grajo Moába in zasramovanja Amónovih otrok, s katerimi so grajali moje ljudstvo in se poveličevali zoper njihovo mejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Zato kakor jaz živim,« govori Gospod nad bojevniki, Izraelov Bog: »Zagotovo bo Moáb kakor Sódoma in Amónovi otroci kakor Gomóra, celó gojenje kopriv in solne jame in nenehno opustošenje. Preostanek mojega ljudstva jih bo oplenil in preostanek mojega ljudstva jih bo vzel v last.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To bodo imeli zaradi svojega ponosa, ker so grajali in se poveličevali zoper ljudstvo Gospoda nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Gospod jim bo strašen, kajti izstradal bo vse bogove zemlje in ljudje ga bodo oboževali, vsak iz svojega kraja, celó vsi otoki poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, '»Tudi vi Etiopijci boste umorjeni z mojim mečem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Svojo roko bo iztegnil zoper sever in uničil Asirijo in Ninive bo naredil opustošenje in suho kakor divjina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Tropi se bodo ulegli v njegovi sredi, vse živali narodov, tako kormoran kot bobnarica bosta prenočevala v njegovih zgornjih prekladah. Njihov glas bo prepeval na oknih, opustošenje bo na pragih, kajti odkril bo cedrovo oblogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'To je veseleče se mesto, ki je brezskrbno prebivalo, ki je v svojem srcu govorilo: ›Jaz sem in poleg mene ni nikogar.‹ Kako je postalo opustošenje, kraj za živali, da se uležejo v njem! Vsak, kdor gre mimo njega, ga bo izžvižgal in zamahnil s svojo roko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Gorje njej, ki je umazana in oskrunjena, zatiralskemu mestu, [prestolnici Jeruzalem]!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ni ubogala glasu, ni sprejela grajanja, ni zaupala v Gospoda, ni se približala k svojemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Njeni princi znotraj nje so rjoveči levi; njeni sodniki so večerni volkovi; kosti ne zgrizejo do naslednjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Njeni preroki so nepomembni in zahrbtne osebe, njeni duhovniki so oskrunili svetišče, postavi so storili nasilje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Pravičen Gospod je v njeni sredi. Ne bo storil krivičnosti, vsako jutro svojo sodbo prinaša na svetlo, ne odpove. Toda krivičnik ne pozna sramu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '»Iztrebil sem narode; njihovi stolpi so zapuščeni, njihove ulice sem naredil opustošene, da nihče ne hodi mimo. Njihova mesta so uničena, tako da tam ni nobenega človeka, da tam ni nobenega prebivalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Rekel sem: ›Zagotovo se me boš bala, prejela boš poučevanje.‹ Tako njihova prebivališča ne bi smela biti iztrebljena, vendar sem jih kaznoval; vendar so vstali zgodaj in izpridili vsa svoja početja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Zatorej čakajte name,« govori Gospod, »do dneva, ko se dvignem k plenu, kajti moja odločitev je, da zberem narode, da lahko zberem kraljestva, da nanje izlijem svoje ogorčenje, celó vso svojo kruto jezo, kajti vsa zemlja bo požrta z ognjem moje ljubosumnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Kajti takrat se bom obrnil k ljudstvu čistega jezika, da bodo lahko vsi klicali h Gospodovemu imenu, da mu soglasno služijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Iz druge strani reke Etiopije mi bodo slavilci, celó hči mojih razkropljencev, prinesli mojo daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Na tisti dan ne boš osramočena zaradi vseh svojih početij, s katerimi si se prekršila zoper mene, kajti takrat bom iz tvoje srede odvedel vse tiste, ki se veselijo v tvojem ponosu in ne boš več ošabna zaradi moje svete gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Prav tako bom v tvoji sredi pustil trpeče in ubogo ljudstvo in ti bodo zaupali v Gospodovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Izraelov preostanek ne bo počel krivičnosti niti govoril laži niti v njihovih ustih ne bo najden varljiv jezik, kajti pasli se bodo in se zleknili in nihče jih ne bo strašil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Prepevaj, oh hči sionska; vzklikaj, oh Izrael; bodi vesela in razveseljuj se z vsem srcem, oh hči jeruzalemska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Gospod je odvzel tvoje obsodbe, pregnal tvojega sovražnika. Izraelov kralj, celó Gospod, je v tvoji sredi. Nobenega zla ne boš več videla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Na tisti dan bo [prestolnici] Jeruzalem rečeno: ›Ne boj se.‹ in Sionu: ›Ne dopusti, da bi bile tvoje roke mlahave.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Gospod, tvoj Bog, v tvoji sredi je mogočen. Rešil bo, z radostjo se bo veselil nad teboj, počival bo v svoji ljubezni, nad teboj se bo veselil s prepevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Zbral bom tiste, ki žalujejo po slovesnem zboru, ki so iz tebe, ki jim je bila ta sramota breme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Glej, ob tistem času bom odstranil vse tiste, ki te stiskajo in rešil bom tisto, kar šepa in zbral tisto, kar je bilo izgnano in dal jim bom hvalo in sloves v vsaki deželi, kjer so bili osramočeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Ob tistem času vas bom ponovno privedel, celo v času, ko vas zberem, kajti naredil vas bom za ime in hvalo med vsemi narodi zemlje, ko pred vašimi očmi obrnem vaše ujetništvo nazaj,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'V drugem letu kralja Dareja, v šestem mesecu, na prvi dan meseca, je prišla Gospodova beseda po preroku Ageju k Zerubabélu, Šealtiélovemu sinu, voditelju Juda in k Ješúu, Jocadákovemu sinu, vélikemu duhovniku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '»Tako govori Gospod nad bojevniki, rekoč: ›To ljudstvo pravi: ›Čas ni prišel, čas, da bi bila zgrajena Gospodova hiša.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Potem je prišla Gospodova beseda po preroku Ageju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '› Ali je čas za vas, oh vi, da prebivate v svojih obitih hišah, ta hiša pa leži zapuščena?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Zdaj torej tako govori Gospod nad bojevniki: ›Preudarite svoje poti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Mnogo ste sejali, prinesli pa malo; jedli ste, toda nimate dovolj; pijete, toda niste nasičeni s pijačo; oblačite se, toda nihče ni ogret; in tisti, ki zasluži plačila, zasluži plačila, da jih daje v torbo z luknjami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tako govori Gospod nad bojevniki: ›Preudarite svoje poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Pojdite gor na goro, pripeljite les, zgradite hišo in razveseljeval se bom v njej in jaz bom proslavljen,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Precej ste iskali in glejte, postalo je malo; in ko ste to prinesli domov, sem pihnil na to. Zakaj?‹ govori Gospod nad bojevniki. ›Zaradi moje hiše, ki je opustošena, vi pa tečete vsakdo za svojo lastno hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Zatorej je nebo nad vami zadržano pred roso in zemlja je zadržana pred njenim sadom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'In jaz sem poklical sušo na deželo, na gore, na žito, na novo vino, na olje in na to, kar prinašajo tla, na ljudi, na živino in na ves trud rok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Potem sta Zerubabél, Šealtiélov sin in Ješúa, Jocadákov sin, véliki duhovnik, z vsem preostankom ljudstva, ubogala glas Gospoda, svojega Boga in besede preroka Ageja, kakor mu jih je poslal Gospod, njihov Bog in ljudstvo se je balo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Potem je spregovoril Agej, Gospodov poslanec v Gospodovi poslanici ljudstvu, rekoč: ›Jaz sem z vami,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'In Gospod je razvnel duha Zerubabéla, Šealtiélovega sina, voditelja Judeje in duha Ješúa, Jocadákovega sina, vélikega duhovnika in duha vsega preostanka ljudstva in prišli so in delali v hiši Gospoda nad bojevniki, svojega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'v štiriindvajsetem dnevu šestega meseca, v drugem letu kralja Dareja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'V sedmem mesecu, na enaindvajseti dan meseca, je prišla Gospodova beseda po preroku Ageju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '»Govori sedaj Zerubabélu, Šealtiélovemu sinu, voditelju Judeje in Ješúu, Jocadákovemu sinu, vélikemu duhovniku in preostanku ljudstva, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, '›Kdo je preostal med vami, ki je to hišo videl v njeni prvi slavi? In kakšno jo vidite sedaj? Mar ni to v vaših očeh v primerjavi z njo kakor nič?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Vendar bodi sedaj močan, oh Zerubabél,‹ govori Gospod ›in bodi močan, oh Ješúa, Jocadákov sin, véliki duhovnik in bodi močno, vse ljudstvo dežele,‹ govori Gospod ›in delajte, kajti jaz sem z vami,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Glede na besedo, s katero sem se zavezal z vami, ko ste prišli iz Egipta, tako moj duh ostaja med vami. Ne bojte se.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Kajti tako govori Gospod nad bojevniki: ›Še enkrat, to je kratek čas in stresel bom nebo, zemljo, morje in kopno zemljo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'in stresel bom vse narode in želja vseh narodov bo prišla in to hišo bom napolnil s slavo,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '›Moje je srebro in moje je zlato,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, '›Slava te poslednje hiše bo večja kakor prejšnje,‹ govori Gospod nad bojevniki, ›in na tem kraju bom dal mir,‹ govori Gospod nad bojevniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Na štiriindvajseti dan devetega meseca, v drugem letu Dareja, je prišla Gospodova beseda po preroku Ageju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '»Tako govori Gospod nad bojevniki: ›Vprašaj torej duhovnike glede postave, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, '›Če nekdo nosi sveto meso v krajcu svoje obleke in se s krajcem svojega oblačila dotakne kruha ali juhe ali vina ali olja ali katerekoli hrane, ali bo ta postala sveta?‹« Duhovniki so odgovorili in rekli: »Ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Potem je Agej rekel: »Če se nekdo, ki je nečist s truplom, dotakne karkoli od tega ali bo to nečisto?« Duhovniki so odgovorili in rekli: »To bo nečisto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Potem je Agej odgovoril in rekel: »Takšno je to ljudstvo in takšen je ta narod pred menoj,« govori Gospod, »in takšno je vsako delo njihovih rok; in to, kar tam darujejo, je nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'In sedaj vas prosim, preudarite od tega dne in naprej, od preden je bil kamen položen na kamen v Gospodovem templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Odkar so bili tisti dnevi, ko je nekdo prišel h kupu dvajsetih mer, jih je bilo tam samo deset. Ko je nekdo prišel, da iz stiskalnice zajame petdeset posod, jih je bilo tam samo dvajset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Udaril sem vas s kvarjenjem in s plesnijo in s točo v vseh naporih vaših rok, vendar se niste obrnili k meni,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Preudarite torej od tega dne in naprej, od štiriindvajsetega dne devetega meseca, celo od dneva, ko je bil položen temelj Gospodovega templja, preudarite to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Je seme še v skednju? Da, do tega trenutka trta, figovo drevo, granatno jabolko in oljka še niso obrodili. Od tega dne vas bom blagoslavljal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Ponovno je prišla Gospodova beseda k Ageju, v štiriindvajsetem dnevu meseca, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '»Govori Zerubabélu, voditelju Juda, rekoč: ›Stresel bom nebo in zemljo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'in prevrnil bom prestol kraljestev in uničil bom moč poganskih kraljestev in prevrnil bom bojne vozove in tiste, ki se peljejo na njih, in konji in njihovi jezdeci bodo padli, vsak pod mečem svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Na tisti dan,« govori Gospod nad bojevniki, »te bom vzel, oh Zerubabél, moj služabnik, Šealtiélov sin,« govori Gospod »in te naredil kakor pečat, kajti tebe sem izbral,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'V osmem mesecu, v drugem letu Dareja, je prišla Gospodova beseda Zahariju, Berehjájevemu sinu, Idójevemu sinu, preroku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '» Gospod je bil ogorčeno nezadovoljen z vašimi očeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Zato jim reci: ›Tako govori Gospod nad bojevniki: ›Obrnite se k meni,‹ govori Gospod nad bojevniki ›in jaz se bom obrnil k vam,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, '›Ne bodite kakor vaši očetje, h katerim so klicali prejšnji preroki, rekoč: ›Tako govori Gospod nad bojevniki: ›Obrnite se sedaj iz svojih zlih poti in od svojih zlih početij,‹ toda niso poslušali niti mi niso prisluhnili,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '›Vaši očetje, kje so? In preroki, mar večno živijo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Toda mar se moje besede in moji zakoni, ki sem jih zapovedal svojim služabnikom prerokom niso prijeli vaših očetov? In pokesali so se ter rekli: ›Kakor nam je Gospod nad bojevniki mislil storiti, glede na naše poti in glede na naša početja, tako je postopal z nami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Na štiriindvajseti dan enajstega meseca, ki je mesec šebát, v drugem letu kralja Dareja, je prišla Gospodova beseda Zahariju, Berehjájevemu sinu, Idójevemu sinu, preroku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, '»Videl sem ponoči in glej moža, jahajočega na rdečem konju in stal je med mirtinimi drevesi, ki so bila na dnu in za njimi so bili rdeči konji, lisasti in beli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Potem sem rekel: »Oh moj gospod, kdo so ti?« Angel, ki je govoril z menoj, mi je rekel: »Pokazal ti bom kdo so ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Mož, ki je stal med mirtinimi drevesi, je odgovoril in rekel: »To so tisti, ki jih je Gospod poslal, da hodijo sem ter tja po zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Odgovorili so Gospodovemu angelu, ki je stal med mirtinimi drevesi in rekli: »Hodili smo sem ter tja po zemlji in glej, vsa zemlja mirno sedi in je pri počitku.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Potem je Gospodov angel odgovoril in rekel: »Oh Gospod nad bojevniki, doklej ne boš imel usmiljenja nad Jeruzalemom in nad Judovimi mesti, zoper katere si imel ogorčenje teh sedemdeset let?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Gospod je odgovoril angelu, ki je govoril z menoj, z dobrimi besedami in tolažilnimi besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Tako mi je angel, ki je govoril z menoj, rekel: »Kliči, rekoč: ›Tako govori Gospod nad bojevniki: ›Ljubosumen sem zaradi Jeruzalema in zaradi Siona z velikim ljubosumjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Silno sem ogorčeno nezadovoljen s pogani, ki so oholi, kajti bil sem le malo nezadovoljen, oni pa so pomagali, da je stiska napredovala.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Zato tako govori Gospod: »Z usmiljenji sem se vrnil k Jeruzalemu. Moja hiša bo zgrajena v njem,« govori Gospod nad bojevniki »in [merilna] vrvica bo raztegnjena nad Jeruzalemom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Še kliči, rekoč: ›Tako govori Gospod nad bojevniki: ›Moja mesta bodo prek blaginje še razširjena naokoli, in Gospod bo še potolažil Sion in bo še izbral Jeruzalem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Potem sem povzdignil svoje oči in videl in glej, štirje rogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Rekel sem angelu, ki je govoril z menoj: »Kaj so tile?« Odgovoril mi je: »Ti so rogovi, ki so razkropili Juda, Izraela in Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Gospod mi je pokazal štiri tesarje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Potem sem rekel: »Kaj so ti prišli delat?« Spregovoril je, rekoč: »Ti so rogovi, ki so razkropili Juda, tako da noben človek ni vzdignil svoje glave, toda prišli so, da jih prestrašijo, da odbijejo rogove poganov, ki so svoje rogove povzdignili nad Judovo deželo, da jo razkropijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Ponovno sem povzdignil svoje oči in pogledal in glej, mož z merilno vrvico v svoji roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Potem sem rekel: »Kam greš?« Rekel mi je: »Da izmerim Jeruzalem, da vidim kakšna je njegova širina in kakšna je njegova dolžina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Glej, angel, ki je govoril z menoj, je šel naprej in drug angel je odšel ven, da ga sreča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'ter mu rekel: »Teci, govori temu mladeniču, rekoč: › [Prestolnica] Jeruzalem bo naseljena kakor mesta brez zidov, zaradi množice ljudi in živine v njej.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Kajti jaz,« govori Gospod, »ji bom ognjen zid vsenaokrog in bom slava v njeni sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Hej, hej, pridite in pobegnite iz severne dežele,« govori Gospod, »kajti razkropil sem vas naokrog kakor štiri vetrove neba,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, '»Osvobodi se, oh Sion, ki prebivaš z babilonsko hčerjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Kajti tako govori Gospod nad bojevniki: »Za slavo me je poslal k narodom, ki so vas plenili. Kajti kdor se dotakne vas, se dotakne punčice njegovega očesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Kajti glej, svojo roko bom stresel nad njimi in postali bodo plen svojim služabnikom in vedeli boste, da me je poslal Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Prepevaj in razveseljuj se, oh hči sionska, kajti glej, prihajam in prebival bom v tvoji sredi,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, '»Na tisti dan bodo številni narodi pridruženi h Gospodu in bodo moje ljudstvo in jaz bom prebival v tvoji sredi in vedela boš, da me je Gospod nad bojevniki poslal k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Gospod bo podedoval Juda in njegov delež v sveti deželi in ponovno bo izbral Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Molči, oh vse meso, pred Gospodom, kajti vzdignjen je iz svojega svetega prebivališča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Pokazal mi je Ješúa, vélikega duhovnika, stati pred Gospodovim angelom in Satana, stoječega na njegovi desnici, da se mu upira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Gospod je rekel Satanu: » Gospod te oštej, oh Satan. Celó Gospod, ki je izbral Jeruzalem, naj te ošteje. Mar ni to ogorek, potegnjen iz ognja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Torej Ješúa je bil oblečen v umazane obleke in stal pred angelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Odgovoril je in spregovoril tistim, ki so stali pred njim, rekoč: »Odvzemite umazane obleke z njega.« Rekel mu je: »Glej, tvoji krivičnosti sem velel, da gre od tebe in oblekel te bom z zamenjavo oblačil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Rekel sem: »Naj na njegovo glavo postavijo lep turban.« Tako so na njegovo glavo postavili lep turban in ga oblekli z oblekami. In Gospodov angel je stal poleg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Gospodov angel je izpričal Ješúu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '»Tako govori Gospod nad bojevniki: ›Če se boš ravnal po mojih poteh in če se boš držal moje zadolžitve, potem boš sodil tudi mojo hišo in se boš držal mojih dvorov in dal ti bom prostore za hojo med tistimi, ki stojijo poleg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Poslušaj sedaj, oh Ješúa, véliki duhovnik, ti in tvoji tovariši, ki sedijo pred teboj, kajti oni so ljudje čudenja. Kajti, glej, privedel bom svojega služabnika MLADIKO.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Kajti poglej, kamen, ki sem ga položil pred Ješúa. Na enem kamnu bo sedem oči. Glej, vrezal bom graviranje le-tega,« govori Gospod nad bojevniki »in krivičnost te dežele bom odstranil v enem dnevu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Na ta dan,« govori Gospod nad bojevniki, »boste vabili vsakdo svojega soseda pod trto in pod figovo drevo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Angel, ki je govoril z menoj, je ponovno prišel in me prebudil, kakor človeka, ki je prebujen iz svojega spanja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'ter mi rekel: »Kaj vidiš?« Rekel sem: »Pogledal sem in glej, svečnik, ves iz zlata, s skledico na njegovem vrhu in njegovih sedem svetilk na njem in sedem cevk k sedmim svetilkam, ki so na njegovem vrhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'In ob njem dve oljki, eno na desni strani skledice in drugo na njeni levi strani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Tako sem odgovoril in spregovoril angelu, ki je govoril z menoj, rekoč: »Kaj so ti, moj gospod?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Potem je angel, ki je govoril z menoj, odgovoril in mi rekel: »Ali ne veš kaj so ti?« Rekel sem: »Ne, moj gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Potem je odgovoril in mi spregovoril, rekoč: »To je beseda od Gospoda Zerubabélu, rekoč: ›Ne z močjo niti ne z oblastjo, temveč z mojim duhom,‹« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, '›Kdo si ti, oh velika gora? Pred Zerubabélom boš postala ravnina in on bo privedel njen zaključni kamen z vriskanji, kličoč: ›Milost, milost njemu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Poleg tega je prišla k meni Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '»Zerubabélove roke so položile temelj tej hiši. Njegove roke jo bodo tudi dokončale in vedel boš, da me je k vam poslal Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Kajti kdo je preziral dan majhnih stvari? Kajti razveseljevali se bodo in videli grezilo v roki Zerubabéla s tistimi sedmimi. Te so Gospodove oči, ki tečejo sem ter tja po celotni zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Potem sem odgovoril in mu rekel: »Kaj sta ti dve oljki na desni strani svečnika in na njegovi levi strani?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Ponovno sem odgovoril in mu rekel: »Kaj sta ti dve oljkovi mladiki, ki skozi dve zlati cevki praznita zlato olje iz njiju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Odgovoril mi je in rekel: »Ne veš kaj sta le-ti? Rekel sem: »Ne, moj gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Potem je rekel: »To sta dva maziljenca, ki stojita pri Gospodu celotne zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Potem sem se obrnil, povzdignil svoje oči, pogledal in zagledal leteči zvitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Rekel mi je: »Kaj vidiš?« Odgovoril sem: »Vidim leteči zvitek. Njegova dolžina je dvajset komolcev in njegova širina deset komolcev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Potem mi je rekel: »To je prekletstvo, ki gre naprej preko obličja celotne zemlje, kajti vsak, kdor krade, bo pokončan kakor na tej strani, glede na to; in vsak, kdor prisega, bo pokončan kakor na tisti strani, glede na to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, '»Privedel ga bom naprej,« govori Gospod nad bojevniki »in ta bo vstopil v hišo tatu in v hišo tistega, ki krivo prisega pri mojem imenu. In ta bo ostal v sredi njegove hiše in použil jo bo z njenim lesom in njenimi kamni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Potem je angel, ki je govoril z menoj, odšel naprej in mi rekel: »Dvigni sedaj svoje oči in poglej kaj je to, kar gre naprej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Rekel sem: »Kaj je to?« Rekel je: »To je škaf, ki gre naprej.« Poleg tega je rekel: »To je njihov videz po vsej zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Glej, tam je bil dvignjen talent iz svinca in to je ženska, ki sedi na sredi škafa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Rekel je: »To je zlobnost.« In vrgel jo je na sredo škafa in svinčeno utež je vrgel na njegovo odprtino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Potem sem povzdignil svoje oči in pogledal in glej, tam sta prišli ven dve ženski in veter je bil v njunih perutih, kajti peruti sta imeli podobni perutim štorklje in škaf sta dvignili med zemljo in nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Potem sem rekel angelu, ki je govoril z menoj: »Kam ti [dve] nosita škaf?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Rekel mi je: »Da mu zgradijo hišo v deželi Šinár. In ta bo utrjena in tam ga postavita na njegov lastni temelj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Obrnil sem se, povzdignil svoje oči, pogledal in glej, prišli so štirje vozovi izmed dveh gora in gori sta bili gori iz brona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Pri prvem vozu so bili rdeči konji, pri drugem vozu črni konji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'pri tretjem vozu beli konji in pri četrtem vozu osiveli in rjavi konji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Potem sem odgovoril in rekel angelu, ki je govoril z menoj: »Kaj so ti, moj gospod?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Angel je odgovoril in mi rekel: »To so štirje nebeški duhovi, ki gredo naprej, [potem ko so stali] pred Gospodom vse zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Črni konji, ki so pri njem, gredo v severno deželo. Beli gredo za njimi in osiveli gredo proti južni deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Rjavci pa so šli naprej in iskali, da bi lahko hodili sem ter tja po zemlji. Rekel je: »Pojdite od tod, hodite sem ter tja po zemlji.« Tako so hodili sem ter tja po zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Potem mi je zaklical in mi spregovoril, rekoč: »Poglej, ti, ki gredo proti severni deželi, so utišali mojega duha v severni deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'K meni je prišla Gospodova beseda, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '»Vzemi od teh iz ujetništva, torej od Heldája, od Tobija in od Jedajája, ki so prišli iz Babilona in pridi isti dan in pojdi v hišo Cefanjájevega sina Jošíja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Potem vzemi srebro in zlato in naredi krone in jih postavi na glavo Ješúa, Jocadákovega sina, vélikega duhovnika');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'in mu spregovori, rekoč: ›Tako govori Gospod nad bojevniki, rekoč: ›Glej, mož, katerega ime je MLADIKA; in rastel bo iz svojega kraja in zgradil bo Gospodov tempelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Celo on bo zgradil Gospodov tempelj in nosil bo slavo in sedel bo in vladal na svojem prestolu in bo duhovnik na svojem prestolu in namera miru bo med obema.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Krone bodo Helému, Tobiju, Jedajáju in Cefanjájevemu sinu Henu v spomin, v Gospodovem templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Tisti, ki so daleč proč, bodo prišli in gradili v Gospodovem templju in vedeli boste, da me je Gospod nad bojevniki poslal k vam. In to se bo zgodilo, če boste marljivo ubogali glas Gospoda, svojega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Pripetilo se je v četrtem letu kralja Dareja, da je Gospodova beseda prišla Zahariju na četrti dan devetega meseca, torej v kislévu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'ko so poslali v Božjo hišo Sarécerja in Regem Meleha in njune može, da molijo pred Gospodom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'in da govorijo duhovnikom, ki so bili v hiši Gospoda nad bojevniki in prerokom, rekoč: »Ali naj bi jokal v petem mesecu in se zadrževal, kot sem to počel ta mnoga leta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Potem je prišla k meni beseda Gospoda nad bojevniki, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '»Govori vsemu ljudstvu dežele in duhovnikom, rekoč: ›Ko ste se postili in žalovali v petem in sedmem mesecu, celo teh sedemdeset let, ali ste se sploh postili meni, celó zame?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'In ko ste jedli in ko ste pili, mar niste jedli zase in pili zase?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Mar naj ne bi slišali besed, ki jih je Gospod klical po prejšnjih prerokih, ko je bil Jeruzalem naseljen in v uspevanju in njegova mesta okoli njega, ko so ljudje naseljevali jug in ravnino?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Gospodova beseda je prišla Zahariju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '»Tako govori Gospod nad bojevniki, rekoč: ›Izvajajte resnično sodbo in izkazujte usmiljenje in sočutja vsakdo svojemu bratu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'in ne stiskajte vdove, niti osirotelega, niti tujca, niti revnega, in naj si nihče izmed vas v svojem srcu ne domišlja zla zoper svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Toda zavrnili so, da bi prisluhnili in odmaknili so ramo in si zamašili svoja ušesa, da ne bi slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Da, svoja srca so naredili kakor diamantni kamen, da ne bi slišali postave in besed, ki jih je Gospod nad bojevniki poslal po svojem duhu po prejšnjih prerokih, zato je prišel velik bes od Gospoda nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Zato se je zgodilo, da kakor je on klical in niso hoteli slišati, tako so klicali in nisem hotel slišati,« govori Gospod nad bojevniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, '»temveč sem jih z vrtinčastim vetrom razkropil med vse narode, ki jih niso poznali. Tako je bila dežela za njimi zapuščena, da noben človek ni šel skoznjo niti se ni vrnil, kajti prijetno deželo so spremenili v opustošeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Ponovno je prišla k meni beseda Gospoda nad bojevniki, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '»Tako govori Gospod nad bojevniki: ›Z velikim ljubosumjem sem bil ljubosumen zaradi Siona in zaradi njega sem bil ljubosumen s silno razjarjenostjo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tako govori Gospod: ›Vrnem se k Sionu in prebival bom v sredi Jeruzalema in Jeruzalem bo imenovan mesto resnice in gora Gospoda nad bojevniki sveta gora.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tako govori Gospod nad bojevniki: ›Še bodo starci in starke prebivali na ulicah Jeruzalema in vsak mož s svojo palico v svoji roki zaradi visoke starosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ulice mesta bodo polne fantov in deklet, ki se bodo igrali na ulicah le-tega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tako govori Gospod nad bojevniki: ›Če je to čudovito v očeh preostanka tega ljudstva v tistih dneh, mar ne bi bilo čudovito tudi v mojih očeh?‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tako govori Gospod nad bojevniki: ›Glej, rešil bom svoje ljudstvo iz vzhodne dežele in iz zahodne dežele');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'in privedel jih bom in prebivali bodo v sredi Jeruzalema. In oni bodo moje ljudstvo in jaz bom njihov Bog v resnici in v pravičnosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tako govori Gospod nad bojevniki: ›Naj bodo vaše roke močne, vi, ki v teh dneh slišite te besede po ustih prerokov, ki so bili na dan, ko je bil položen temelj hiše Gospoda nad bojevniki, da bi bil tempelj lahko zgrajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Kajti pred temi dnevi ni bilo plačila za moža niti kateregakoli plačila za žival; niti zaradi stiske ni bilo nobenega miru tistemu, ki je odhajal ali prihajal, kajti vse ljudi sem naravnal, vsakega zoper svojega soseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Toda sedaj preostanku tega ljudstva ne bom kakor v prejšnjih dneh,‹ govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '›Kajti seme bo uspešno; trta bo dajala svoj sad in tla bodo dajala svoj prirastek in nebo bo dajalo svojo roso. In preostanku tega ljudstva bom povzročil, da vzamejo v last vse te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'In zgodilo se bo, da kakor ste bili prekletstvo med pogani, oh hiša Judova in hiša Izraelova, tako vas bom rešil in boste blagoslov. Ne bojte se, temveč naj bodo vaše roke močne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Kajti tako govori Gospod nad bojevniki: ›Kakor sem vas mislil kaznovati, ko so me vaši očetje dražili do besa,‹ govori Gospod nad bojevniki in se nisem pokesal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'tako sem v teh dneh ponovno mislil, da storim dobro Jeruzalemu in Judovi hiši. Ne bojte se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'To so stvari, ki jih boste storili: ›Govorite vsak človek resnico svojemu sosedu; izvršujte sodbo resnice in miru v svojih velikih vratih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'in naj si nihče izmed vas v svojih srcih ne domišlja zla zoper svojega soseda in ne ljubite krive prisege, kajti vse to so stvari, ki jih sovražim,‹ govori Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Prišla mi je beseda Gospoda nad bojevniki, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '»Tako govori Gospod nad bojevniki: ›Post četrtega meseca, post petega, post sedmega in post desetega bo Judovi hiši radost in veselje in vedre gostije, zato ljubite resnico in mir.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tako govori Gospod nad bojevniki: ›Še se bo zgodilo, da bodo prihajala ljudstva in prebivalci mnogih mest');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'in prebivalci enega mesta bodo šli k drugemu, rekoč: ›Pojdimo naglo, da molimo pred Gospodom in da iščemo Gospoda nad bojevniki.‹ ›Tudi jaz bom šel.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Da, številna ljudstva in močni narodi bodo prišli, da iščejo Gospoda nad bojevniki v Jeruzalemu in da molijo pred Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tako govori Gospod nad bojevniki: »V tistih dneh se bo zgodilo, da bo deset mož iz vseh jezikov narodov prijelo tistega, ki je Jud in celo prijelo krajec njegovega oblačila, rekoč: ›Šli bomo s teboj, kajti slišali smo, da je z vami Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, '§ »Breme Gospodove besede v deželi Hadráh in Damask bo njegov počitek, ko bodo oči človeka kakor od vseh Izraelovih rodov, [usmerjene] proti Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Tudi Hamát bo njegova meja, Tir in Sidón, čeprav je ta zelo moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, '[Naselbina] Tir si je zgradila oporišče in nakopičila srebra kakor prahu in čistega zlata kakor uličnega blata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Glej, Gospod jo bo vrgel ven in udaril bo njeno oblast na morju in použita bo z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Aškelón bo to videl in se bo bal. Tudi Gaza bo to videla in bo zelo žalostna in Ekrón, kajti njegovo pričakovanje bo osramočeno in kralj bo odtaval iz Gaze in Aškelón ne bo naseljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Mešanec bo prebival v Ašdódu in jaz bom iztrebil ponos Filistejcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Njegovo kri bom odvzel iz njegovih ust in njegove ogabnosti izmed njegovih zob. Toda kdor ostaja, celo on, bo za našega Boga in bo kakor voditelj v Judu in Ekrón bo kakor Jebusejec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Utaboril se bom okrog svoje hiše zaradi vojske, zaradi tistega, ki gre mimo in zaradi tistega, ki se vrača. Noben zatiralec ne bo več šel skoznje, kajti sedaj sem videl s svojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Silno se veseli, oh sionska hči. Vriskaj, oh jeruzalemska hči. Glej, tvoj Kralj prihaja k tebi; pravičen je in ima rešitev duše; ponižen in jahajoč na oslu in žrebetu, osličjem žrebetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Iztrebil bom voz iz Efrájima, konja iz Jeruzalema in bojni lok bo odrezan in govoril bo mir poganom. Njegovo gospostvo bo od morja celó do morja in od reke celó do koncev zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Tudi kar se tebe tiče, s krvjo tvoje zaveze sem tvoje jetnike poslal iz jame, v kateri ni vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Obrnite se k oporišču, vi jetniki upanja. Celo danes razglašam, da ti bom povrnil dvojno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'ko sem si ukrivil Juda, lok napolnil z Efrájimom in vzdignil tvoje sinove, oh Sion, zoper tvoje sinove, oh Grčija in te naredil kakor meč mogočnega človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Gospod bo viden nad njimi in njegova puščica bo šla naprej kakor bliskanje in Gospod Bog bo zatrobil na šofar in pojde z južnimi vrtinčastimi vetrovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Gospod nad bojevniki jih bo branil in požrli bodo in podjarmili s kamni [iz] prače, in pili bodo in naredili hrup kakor od vina; in napolnjeni bodo kakor skledice in kakor oltarni vogali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Gospod, njihov Bog, jih bo na tisti dan rešil, kakor trop svojega ljudstva, kajti oni bodo kakor kamni krone, povzdignjeni kakor zastava nad njegovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Kajti kako velika je njegova dobrota in kako velika je njegova lepota! Žito bo mladeniče naredilo radostne in novo vino mladenke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Zahtevajte od Gospoda dež v času poznejšega dežja. Tako bo Gospod naredil svetle oblake in jim dal nalive dežja, vsaki travi na polju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Kajti maliki so govorili ničevost, vedeževalci so videli laž in povedali napačne sanje. Zaman tolažijo. Zatorej so odšli po svoji poti kakor trop, zaskrbljeni so bili, ker ni bilo pastirja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Moja jeza je bila vžgana zoper pastirje in kaznoval sem kozle, kajti Gospod nad bojevniki je obiskal svoj trop, Judovo hišo in jih naredil kakor odličnega konja v bitki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, '§ Iz njega bo prišel vogal, iz njega klin, iz njega bojni lok, iz njega tudi vsak zatiralec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Oni bodo kakor mogočni ljudje, ki v bitki pomendrajo svoje sovražnike v uličnem blatu in borili se bodo, ker je Gospod z njimi in jezdeci na konjih bodo zbegani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Okrepil bom Judovo hišo in rešil Jožefovo hišo in ponovno jih bom privedel, da jih namestim, kajti usmiljenje imam nad njimi in oni bodo, kakor jih ne bi zavrgel, kajti jaz sem Gospod, njihov Bog in uslišal jih bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Tisti iz Efrájima bodo podobni mogočnemu človeku in njihovo srce se bo veselilo kakor zaradi vina. Da, njihovi otroci bodo to videli in bodo veseli; njihovo srce se bo veselilo v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, '»Požvižgal jim bom in jih zbral, ker sem jih odkupil in narasli bodo, kakor so oni narasli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Sejal jih bom med ljudstvom in spomnili se me bodo v daljnih deželah in živeli bodo s svojimi otroki in se ponovno vrnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ponovno jih bom privedel tudi iz egiptovske dežele in jih zbral iz Asirije. Privedel jih bom v deželo Gileád in Libanon in ne bo najti prostora zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'S stisko bo prešel skozi morje in udaril bo valove v morju in vse globine reke se bodo posušile. Ponos Asirije bo ponižan in egiptovsko žezlo bo odšlo proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Okrepil jih bom v Gospodu in hodili bodo gor in dol v njegovem imenu,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Odpri svoja vrata, oh Libanon, da bo ogenj lahko pogoltnil tvoje cedre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Tuli cipresa, kajti cedra je padla, ker so mogočni oplenjeni. Tulite, oh vi, bašánski hrasti, kajti neprehoden gozd je posekan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Tam je glas tuljenja pastirjev, kajti njihova slava je oplenjena. Glas rjovenja mladih levov, kajti ponos Jordana je oplenjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tako govori Gospod, moj Bog: »Hrani trop za zakol,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'katerih lastniki jih ubijajo in se nimajo za krive; in tisti, ki jih prodajajo, pravijo: ›Blagoslovljen bodi Gospod, kajti bogat sem,‹ in njihovi lastni pastirji jim ne prizanašajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Kajti ne bom več prizanašal prebivalcem dežele,‹ govori Gospod, ›temveč glej, izročil bom ljudi, vsakega v roko njegovega soseda in v roko njegovega kralja in udarili bodo deželo in iz njihove roke jih ne bom osvobodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Jaz bom pasel trop za zakol, celó vas, oh ubogi izmed tropa. Vzel sem si dve palici. Eno sem imenoval Lepota, drugo pa sem imenoval Vezi; in jaz sem pasel trop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Tudi tri pastirje uničim v enem mesecu in moji duši so se gnusili in tudi njihova duša je zaničevala mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Potem sem rekel: ›Ne bom vas pasel. Tisti, ki umira, naj umre in tisti, ki naj bi bil uničen, naj bo ta uničen, preostali pa naj jedo vsakdo meso drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Vzel sem svojo palico, celó Lepoto in jo zlomil, da bi lahko prelomil svojo zavezo, ki sem jo sklenil z vsem ljudstvom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Ta je bila prelomljena na tisti dan.‹« In tako so ubogi iz tropa, ki so čakali name, vedeli, da je bila to Gospodova beseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Rekel sem jim: »Če mislite dobro, mi dajte moje plačilo, in če ne, opustite.« Tako so odtehtali za moje plačilo trideset koščkov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Gospod mi je rekel: »Vrzi to lončarju. Lepo plačilo, za katero so me ovrednotili.« Vzel sem trideset koščkov srebra in jih vrgel v Gospodovo hišo, k lončarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Potem sem zlomil svojo drugo palico, celó Vezi, da bi lahko prelomil bratstvo med Judom in Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Gospod mi je rekel: »K sebi vzemi še priprave nespametnega pastirja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Kajti glej, vzdignil bom pastirja v deželi, ki ne bo obiskoval tistih, ki so uničeni niti ne bo iskal mladih niti zdravil tega, kar je zlomljeno niti pasel tega, kar stoji mirno, temveč bo jedel meso rejenega in njihove parklje trgal na koščke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Gorje malikovalskemu pastirju, ki zapušča čredo! Meč bo nad njegovim laktom in nad njegovim desnim očesom. Njegov laket bo popolnoma osušen in njegovo desno oko bo skrajno otemnelo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, '»Breme o Gospodovi besedi za Izrael,« govori Gospod, ki razprostira nebo in polaga temelj zemlji in oblikuje človeškega duha znotraj njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '»Glej, Jeruzalem bom naredil čašo trepetanja vsemu ljudstvu naokoli, ko bodo v obleganju tako zoper Juda in zoper Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Na tisti dan bom naredil [prestolnico] Jeruzalem obremenilni kamen za vse ljudstvo. Vsi, ki se bremenijo s tem, bodo razsekani na koščke, čeprav bo vse ljudstvo zemlje zbrano zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Na tisti dan,« govori Gospod, »bom vsakega konja udaril z osuplostjo in njegovega jezdeca z norostjo in svoje oči bom odprl nad Judovo hišo in vsakega konja ljudstva bom udaril s slepoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Voditelji Juda bodo v svojem srcu rekli: ›Prebivalci Jeruzalema bodo moja moč v Gospodu nad bojevniki, njihovem Bogu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Na tisti dan bom naredil voditelje Juda kakor ognjeno ognjišče med lesom in ognjeno baklo v snopu in použili bodo vse ljudstvo naokoli, na desni roki in na levi in Jeruzalem bo ponovno naseljen na svojem lastnem kraju, celó v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Gospod bo tudi najprej rešil Judove šotore, da se slava Davidove hiše in slava prebivalcev Jeruzalema ne bo poveličevala zoper Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Na tisti dan bo Gospod branil prebivalce Jeruzalema. Kdor bo na tisti dan med njimi slaboten, bo kakor David in Davidova hiša bo kakor Bog, kakor Gospodov angel pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'In zgodilo se bo na tisti dan, da si bom prizadeval uničiti vse narode, ki pridejo zoper Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Na Davidovo hišo in na prebivalce Jeruzalema bom izlil duha milosti in ponižnih prošenj in gledali bodo name, ki so ga prebodli in žalovali bodo za njim, kakor nekdo žaluje za svojim edinim sinom in v grenkobi bodo za njim, kakor nekdo, ki je v grenkobi zaradi svojega prvorojenca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Na tisti dan bo v Jeruzalemu veliko žalovanje, kakor žalovanje za Hadád Rimónom v dolini Megído.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Dežela bo žalovala, vsaka družina posebej; družina Davidove hiše posebej in njihove žene posebej, družina Natánove hiše posebej in njihove žene posebej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'družina Lévijeve hiše posebej in njihove žene posebej, Šimíjeva družina posebej in njihove žene posebej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Vse družine, ki preostanejo, vsaka družina posebej in njihove žene posebej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, '»Na tisti dan bo studenec odprt Davidovi hiši in prebivalcem Jeruzalema zaradi greha in zaradi nečistosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'In zgodilo se bo na tisti dan,« govori Gospod nad bojevniki, » da bom iz dežele iztrebil imena malikov in ne bodo se jih več spominjali, in prav tako bom prerokom in nečistemu duhu povzročil, da zapustijo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'In zgodilo se bo, da kdorkoli bo še prerokoval, potem mu bosta njegov oče in njegova mati, ki sta ga zaplodila, rekla: ›Ne boš živel, kajti v Gospodovem imenu govoriš laži.‹ Njegov oče in njegova mati, ki sta ga zaplodila, ga bosta prebodla, ko prerokuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Na tisti dan se bo zgodilo, da bodo preroki osramočeni, vsak zaradi svoje vizije, ko je prerokoval. Niti ne bodo nosili grobe obleke, da bi zavajali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'temveč bo rekel: ›Jaz nisem prerok, poljedelec sem. Kajti mož me je od moje mladosti naučil, da varujem živino.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'In nekdo mu bo rekel: ›Kaj so te rane na tvojih rokah?‹ Potem bo odgovoril: › Tiste, s katerimi sem bil ranjen v hiši svojih prijateljev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Prebudi se, oh meč, zoper mojega pastirja in zoper človeka, ki je moj družabnik,« govori Gospod nad bojevniki, »udari pastirja in ovce bodo razkropljene in svojo roko bom [ponovno] obrnil nad malčke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'In zgodilo se bo, da bosta v vsej tej deželi,« govori Gospod, »dva njena dela odsekana in bosta umrla, toda tretji bo ostal v njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'In tretji del bom popeljal skozi ogenj in prečistil jih bom, kakor se prečiščuje srebro in preizkusil jih bom, kakor se preizkuša zlato. Klicali bodo k mojemu imenu in jaz jih bom slišal: ›Rekel bom: ›To je moje ljudstvo‹ in rekli bodo: » Gospod je moj Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, '»Poglej, dan Gospodov prihaja in tvoj plen bo razdeljen v tvoji sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Kajti vse narode bom zbral, da se borijo zoper Jeruzalem. Mesto bo zavzeto, hiše oplenjene in ženske posiljene. Polovica mesta bo odšla v ujetništvo, preostanek ljudstva pa ne bo iztrebljen iz mesta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Takrat bo prišel Gospod in se boril zoper te narode, kakor ko se je boril na dan bitke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Na tisti dan bodo njegova stopala stopila na Oljsko goro, ki je na vzhodu, pred Jeruzalemom in Oljska gora se bo razklala po sredi proti vzhodu in proti zahodu in tam bo zelo velika dolina. Polovica gore bo odstranjena proti severu, polovica pa proti jugu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Bežali boste k dolini [med] gorama, kajti dolina [med] gorama bo segala do Azela. Da, bežali boste, podobno kakor ste bežali pred potresom v dneh Judovega kralja Uzíjaha. In Gospod, moj Bog, bo prišel in vsi sveti [bodo] s teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, '§ In zgodilo se bo na tisti dan, da svetloba ne bo razločna, niti tema,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'temveč bo en dan, ki bo poznan Gospodu, niti dan, niti noč, temveč se bo zgodilo, da bo ob večernem času svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'In to bo na tisti dan, da bodo žive vode izšle iz Jeruzalema. Polovica izmed njih proti prvemu morju in polovica proti zadnjemu morju. To bo poleti in pozimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'In Gospod bo kralj nad vso zemljo. Na tisti dan bo en Gospod in njegovo ime eno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Vsa dežela bo narejena kakor ravnina od Gebe do Rimóna, južno od Jeruzalema, in ta bo dvignjen in naseljen na svojem kraju, od Benjaminovih velikih vrat, do mesta prvih velikih vrat, do Vogalnih velikih vrat in od Hananélovega stolpa do kraljevih vinskih stiskalnic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'V njem bodo prebivali ljudje in tam ne bo več skrajnega uničenja, temveč bo Jeruzalem varno naseljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'To pa bo kuga, s katero bo Gospod udaril vsa ljudstva, ki so se borila zoper Jeruzalem. Njihovo meso bo zgnilo, medtem ko stojijo na svojih stopalih in njihove oči bodo zgnile v njihovih jamicah in njihov jezik bo zgnil v njihovih ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Na tisti dan se bo zgodilo, da bo med njimi velika zmešnjava od Gospoda, in vsakdo bo zgrabil roko svojega soseda in svojo roko bo vzdignil zoper roko svojega soseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Tudi Juda se bo bojeval v Jeruzalemu in premoženje vseh poganov naokoli se bo zbralo skupaj, zlata, srebra in oblačil v velikem obilju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Kakor ta kuga, takšna bo kuga konja, mule, kamele, osla in vseh živali, ki bodo v teh šotoriščih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Zgodilo se bo, da kdor preostane izmed vseh narodov, ki so prišli zoper Jeruzalem, bo torej hodil gor iz leta v leto, da obožuje kralja, Gospoda nad bojevniki in da praznuje šotorski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'In zgodilo se bo, da kdorkoli, izmed vseh družin zemlje, ne bo prišel gor v Jeruzalem, da obožuje Kralja, Gospoda nad bojevniki, celo nad njim ne bo dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'In če družina iz Egipta ne gre gor in ne pride, da tam ni dežja, bo tam kuga, s katero bo Gospod udaril pogane, ki ne pridejo gor, da praznujejo šotorski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'To bo kazen Egiptu in kazen vsem narodom, ki ne pridejo gor, da praznujejo šotorski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Na tisti dan bo na konjskih zvončkih SVETO Gospodu in lonci v Gospodovi hiši bodo podobni skledicam pred oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Da, vsak lonec v Jeruzalemu in v Judeji bo svetost Gospodu nad bojevniki. Vsi tisti, ki žrtvujejo, bodo prišli in jemali iz njih in kuhali v njih. Na tisti dan ne bo več Kánaancev v hiši Gospoda nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Breme Gospodove besede Izraelu, po Malahiju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '»Ljubil sem vas,« govori Gospod. Vendar pravite: »V čem si nas ljubil?« » Mar ni bil Ezav Jakobov brat?« govori Gospod, »vendar sem ljubil Jakoba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ezava pa sovražil ter opustošil njegove gore in njegovo dediščino za zmaje divjine.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Kakor govori Edóm: »Obubožani smo, toda vrnili se bomo in pozidali zapuščene kraje,« tako govori Gospod nad bojevniki: »Gradili bodo, toda jaz bom rušil. Imenovali jih bodo: ›Meja zlobnosti‹ in ›Ljudstvo, zoper katero ima Gospod ogorčenje na veke.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Vaše oči bodo videle in rekli boste: » Gospod bo poveličan prek Izraelove meje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, '»Sin časti svojega očeta in služabnik svojega gospodarja. Če sem jaz potem oče, kje je moja čast? In če sem jaz gospodar, kje je moj strah?« govori Gospod nad bojevniki, »vam, oh duhovniki, ki prezirate moje ime. Vi pa pravite: ›V čem smo prezirali tvoje ime?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Na mojem oltarju ste darovali oskrunjen kruh, vi pa pravite: ›V čem smo te oskrunili?‹ V tem, da pravite: › Gospodova miza je zaničevanja vredna.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'In če darujete slepo za žrtev, mar ni to zlo? In če darujete hromo in bolno, mar ni to zlo? Daruj to sedaj svojemu voditelju; ali bo zadovoljen s teboj, ali sprejme tvojo osebo?« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '»In sedaj vas prosim, rotite Boga, da nam bo milostljiv. To je bilo z vašimi sredstvi. Mar bo cenil vaše osebe?« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '§ »Kdo je tam, celo med vami, da bi zaman zaprl vrata? Niti na mojem oltarju ognja ne netite zaman. Nobenega zadovoljstva nimam z vami,« govori Gospod nad bojevniki, »niti ne bom sprejel daritve iz vaše roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Kajti od sončnega vzhoda, celo do zahajanja istega bo moje ime veliko med pogani in na vsakem kraju bo mojemu imenu darovano kadilo in čista daritev, kajti moje ime bo veliko med pogani,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, '»Toda vi ste to oskrunili v tem, ko pravite: › Gospodova miza je oskrunjena; in njen sad, celó njegova jed, je zaničevanja vredna.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Pravite tudi: ›Glej, kakšna težava je to!‹ In vi ste nad tem vihali nos,« govori Gospod nad bojevniki, »in privedli to, kar je bilo raztrgano in hromo in bolno. Tako daritev ste privedli. Mar naj bi to sprejel iz vaše roke?« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Toda preklet bodi slepar, ki ima v svojem tropu samca, pa prisega in žrtvuje Gospodu pokvarjeno stvar, kajti jaz sem velik Kralj,« govori Gospod nad bojevniki, »in moje ime je grozno med pogani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, '»In sedaj, oh vi duhovniki, ta zapoved je za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Če ne boste poslušali in če si tega ne boste položili k srcu, da izročite slavo mojemu imenu,« govori Gospod nad bojevniki, »bom nad vas poslal celo prekletstvo in bom preklel vaše blagoslove. Da, že sem jih preklel, ker si tega niste vzeli k srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Glejte, pokvaril bom vaše seme in razmazal gnoj na vaše obraze, celó gnoj vaših slovesnih praznikov in nekdo vas bo odvedel z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'In vedeli boste, da sem to zapoved poslal k vam, da bi bila moja zaveza lahko z Levijem,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, '»Moja zaveza z njim je bila o življenju in miru in dal sem mu jih za strah, s katerim se me je bal in je bil prestrašen pred mojim imenom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Postava resnice je bila v njegovih ustih in krivičnosti ni bilo najti na njegovih ustnicah. Z menoj je hodil v miru in nepristranskosti in mnoge je odvrnil proč od krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Kajti duhovnikove ustnice naj bi ohranile spoznanje in pri njegovih ustih naj bi iskali postavo, kajti on je poslanec od Gospoda nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Toda odšli ste iz poti, mnogim ste povzročili, da se spotaknejo ob postavi, pokvarili ste Lévijevo zavezo,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '»Zato sem vas tudi naredil zaničevanja vredne in vas ponižal pred vsem ljudstvom, glede na to, da se niste držali mojih poti, temveč ste bili delni v postavi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Mar nimamo vsi istega očeta? Mar nas ni ustvaril en Bog? Zakaj zahrbtno postopamo vsak človek zoper svojega brata z oskrunitvijo zaveze naših očetov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda je postopal zahrbtno in ogabnost je zagrešena v Izraelu in v Jeruzalemu, kajti Juda je oskrunil svetost Gospoda, ki ga je ljubil in poročil hčer tujega boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Gospod bo iztrebil človeka, ki to počne, gospodarja in učenca, iz Jakobovih šotorov in tistega, ki daruje daritev Gospodu nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'In to ste ponovno storili, pokrivajoč Gospodov oltar s solzami, z jokanjem in z vzklikanjem, do take mere, da se ni več oziral na daritev ali to z dobro voljo sprejemal iz vaše roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Vendar pravite: ›Zakaj?‹ Ker je bil Gospod priča med teboj in ženo tvoje mladosti, proti kateri si zahrbtno ravnal, čeprav je ona tvoja družabnica in žena tvoje zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Mar ni on naredil eno? Vendar je imel preostanek duha. In zakaj eno? Da bi lahko iskal bogaboječe seme. Zato pazite na svojega duha in naj nihče ne postopa zahrbtno zoper ženo svoje mladosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Kajti Gospod, Izraelov Bog, pravi, da sovraži ločitev, kajti nekdo zakriva nasilje s svojo obleko,‹ govori Gospod nad bojevniki. ›Zato pazite na svojega duha, da ne ravnate zahrbtno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'S svojimi besedami ste izmučili Gospoda. Vendar pravite: ›V čem smo ga izmučili?‹ Ko pravite: ›Vsak, kdor počenja zlo, je dober v Gospodovih očeh in on se razveseljuje v njih‹ ali: ›Kje je Bog sodbe?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '»Glejte, poslal bom svojega poslanca in pripravil bo pot pred menoj in Gospod, ki ga iščete, bo nenadoma prišel k svojemu templju, celo poslanec zaveze, v katerem se razveseljujete. Glejte, prišel bo,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Toda kdo lahko prenese dan njegovega prihoda? In kdo bo obstal, ko se pojavi? Kajti podoben je prečiščevalčevemu ognju in podoben pralčevemu milu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Sédel bo kakor prečiščevalec in čistilec srebra in očistil bo Lévijeve sinove in jih presejal kakor zlato in srebro, da bodo lahko Gospodu darovali daritev v pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Potem bo daritev Juda in Jeruzalema prijetna Gospodu, kakor v dneh iz davnine in kakor v prejšnjih letih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'In prišel bom bliže k vam, da sodim in bom hitra priča zoper čarodeje in zoper zakonolomce in zoper krivoprisežnike in zoper tiste, ki zatirajo najemnika pri njegovih plačilih, vdovo in osirotelega in ki odvračajo tujca pred njegovo pravico, mene pa se ne bojijo,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, '»Kajti jaz sem Gospod, jaz se ne spreminjam; zatorej vi, Jakobovi sinovi, niste uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Celo od dni svojih očetov ste odstopali od mojih odredb in se jih niste držali. Vrnite se k meni in jaz se bom vrnil k vam,« govori Gospod nad bojevniki. »Toda rekli ste: ›V čem se bomo vrnili?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Ali bo človek oropal Boga? Vendar ste me oropali. Toda vi pravite: ›V čem smo te oropali?‹ V desetinah in daritvah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Prekleti ste s prekletstvom, kajti oropali ste me, celó ves ta narod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Prinesite vse desetine v skladišče, da bo lahko hrana v moji hiši in preizkusite me sedaj s tem,« govori Gospod nad bojevniki, »če vam ne bom odprl oken neba in vam izlil blagoslova, tako da ne bo dovolj prostora, da bi ga sprejeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Zaradi vas bom oštel požiralca in ne bo uničil sadov vaše zemlje niti vaša trta na polju svojega sadu ne bo odvrgla pred časom,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '»In vsi narodi vas bodo klicali blagoslovljeni, kajti vi boste krasna dežela,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '»Vaše besede so bile arogantne zoper mene,« govori Gospod. »Vendar pravite: ›Kaj smo tako zelo govorili zoper tebe?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Rekli ste: ›Prazno je služiti Bogu in kakšna korist je to, da smo se držali njegove odredbe in da smo žalujoč hodili pred Gospodom nad bojevniki?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'In sedaj ponosnega imenujemo srečen. Da, tisti, ki počnejo zlobnost, so povzdignjeni; da, tisti, ki skušajo Boga, so celo osvobojeni.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Potem so tisti, ki so se bali Gospoda, pogosto govorili drug drugemu. Gospod je prisluhnil in to slišal in knjiga spominov je bila napisana pred njim za tiste, ki so se bali Gospoda in tiste, ki mislijo na njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '»Oni bodo moji,« govori Gospod nad bojevniki, »na tisti dan, ko bom pripravil svoje dragocenosti; in jim prizanesel, kakor mož prizanese svojemu lastnemu sinu, ki mu služi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Potem se boste vrnili in razločevali med pravičnim in zlobnim, med tistim, ki služi Bogu in tistim, ki mu ne služi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, '»Kajti glejte, prihaja dan, ki bo gorel kakor peč in vsi ponosni, da in vsi, ki počno zlobno, bodo strnišče. In dan, ki prihaja, jih bo požgal,« govori Gospod nad bojevniki, »da jim ne preostane niti korenina niti mladika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Toda vam, ki se bojite mojega imena, bo vzšlo Sonce pravičnosti, z ozdravljenjem v njegovih perutih, in šli boste naprej in rastli kakor teleta iz hleva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Pomendrali boste zlobne, kajti oni bodo pepel pod podplati vaših stopal, na dan, ko bom to storil,« govori Gospod nad bojevniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, '»Spominjajte se postave Mojzesa, mojega služabnika, ki sem mu jo zapovedal na Horebu, z zakoni in sodbami za ves Izrael.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Glejte, poslal vam bom Elija, preroka, pred prihodom velikega in groznega dneva Gospodovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Obrnil bo srca očetov k otrokom in srca otrok k njihovim očetom, da ne pridem in udarim zemlje s prekletstvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Knjiga rodu Jezusa Kristusa, Davidovega sina, Abrahamovega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham je zaplodil Izaka, in Izak je zaplodil Jakoba in Jakob je zaplodil Juda in njegove brate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'in Juda je s Tamaro zaplodil Pereca in Zeraha, in Perec je zaplodil Hecróna in Hecrón je zaplodil Rama,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'in Ram je zaplodil Aminadába, in Aminadáb je zaplodil Nahšóna, in Nahšón je zaplodil Salmóna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'in Salmón je z Rahábo zaplodil Boaza, in Boaz je z Ruto zaplodil Obéda, in Obéd je zaplodil Jeseja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'in Jese je zaplodil Davida, kralja, in kralj David je zaplodil Salomona z njo, ki je bila žena Urijájeva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'in Salomon je zaplodil Roboáma, in Roboám je zaplodil Abíja, in Abíja je zaplodil Asá,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'in Asá je zaplodil Józafata, in Józafat je zaplodil Joráma, in Jorám je zaplodil Uzíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'in Uzíja je zaplodil Jotáma, in Jotám je zaplodil Aháza, in Aház je zaplodil Ezekíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, '§ in Ezekíja je zaplodil Manáseja, in Manáse je zaplodil Amóna, in Amón je zaplodil Jošíja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'in Jošíja je zaplodil Jojahína in njegove brate, približno ob času, ko so bili odpeljani v Babilon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'in potem ko so bili pripeljani v Babilon, je Jojahín zaplodil Šaltiéla, in Šaltiél je zaplodil Zerubabéla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'in Zerubabél je zaplodil Abihúda, in Abihúd je zaplodil Eljakíma, in Eljakím je zaplodil Azórja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'in Azór je zaplodil Cadóka, in Cadók je zaplodil Ahíma, in Ahím je zaplodil Eliúda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'in Eliúd je zaplodil Eleazarja, in Eleazar je zaplodil Matána, in Matán je zaplodil Jakoba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'in Jakob je zaplodil Jožefa, Marijinega soproga, iz katere je bil rojen Jezus, ki je bil imenovan Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Vseh rodov torej, od Abrahama do Davida, je štirinajst rodov, in od Davida do preselitve v Babilon je štirinajst rodov, in od preselitve v Babilon do Kristusa je štirinajst rodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Rojstvo Jezusa Kristusa je bilo torej na ta način: ravno ko je bila njegova mati Marija zaročena z Jožefom, preden sta prišla skupaj, je bila najdena z otrokom od Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Takrat je njen soprog Jožef, ki je bil pravičen človek in ne voljan narediti jo za javen zgled, razmišljal, da jo na skrivaj odslovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Toda medtem ko je premišljeval o teh stvareh, glej, se mu je v sanjah prikazal Gospodov angel, rekoč: »Jožef, Davidov sin, ne boj se vzeti k sebi svoje žene Marije, kajti to, kar je spočeto v njej, je od Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'In rodila bo sina in njegovo ime boš imenoval JEZUS, kajti svoje ljudi bo rešil pred njihovimi grehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Vse to je bilo torej storjeno, da bi se lahko izpolnilo, kar je Gospod govoril po preroku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '›Glej, devica bo z otrokom in rodila bo sina in njegovo ime bodo imenovali Emanuel, kar je prevedeno: ›Bog z nami.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Tedaj je Jožef, dvignjen iz spanja, storil, kakor mu je Gospodov angel zaukazal in svojo ženo vzel k sebi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, '§ in ni je spoznal, dokler ni rodila svojega prvorojenega sina in njegovo ime je imenoval JEZUS.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Ko je bil torej Jezus rojen v Betlehemu, v Judeji, v dneh kralja Heroda, glej, so od vzhoda v Jeruzalem prišli modri možje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'rekoč: »Kje je tisti judovski Kralj, ki je rojen? Kajti njegovo zvezdo smo videli na vzhodu in prišli smo, da ga obožujemo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ko je kralj Herod slišal te besede, je bil zaskrbljen in z njim ves Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'In ko je zbral skupaj vse visoke duhovnike in pisarje izmed ljudstva, jih je povprašal, kje naj bi bil Kristus rojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Rekli so mu: »V judejskem Betlehemu, kajti tako je napisano po preroku:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '›In ti Betlehem, v deželi Judovi, nisi najmanjši med Judovimi princi, kajti iz tebe bo prišel Voditelj, ki bo vladal mojemu ljudstvu Izraelu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tedaj je Herod, ko je na skrivnem poklical modre može, od njih marljivo poizvedel, kdaj se je zvezda prikazala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'In poslal jih je v Betlehem ter rekel: »Pojdite in marljivo iščite za mladim otrokom in ko ga boste našli, mi ponovno prinesite sporočilo, da lahko tudi jaz pridem in ga obožujem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Ko so slišali kralja, so odšli. In glej, zvezda, ki so jo videli na vzhodu, je šla pred njimi, dokler ni prišla in obstala zgoraj, kjer je bil mladi otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Ko so zagledali zvezdo, so se razveselili s silno veliko radostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'In ko so prišli v hišo, so zagledali mladega otroka z Marijo, njegovo materjo in padli dol ter ga oboževali. In ko so odprli svoje zaklade, so mu izročili darila: zlato in kadilo in miro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'In od Boga v sanjah posvarjeni, da naj se ne bi vrnili k Herodu, so po drugi poti odšli v svojo lastno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'In ko so odšli, glej, se je Jožefu v sanjah prikazal Gospodov angel, rekoč: »Vstani in vzemi mladega otroka in njegovo mater ter beži v Egipt in bodi tam, dokler ti ne prinesem besede, kajti Herod bo mladega otroka iskal, da ga pokonča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Ko je vstal, je ponoči vzel mladega otroka in njegovo mater ter odšel v Egipt');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'in tam je bil do Herodove smrti, da bi se lahko izpolnilo, kar je bilo rečeno od Gospoda po preroku, rekoč: »Iz Egipta sem poklical svojega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Potem je bil Herod, ko je videl, da je bil zasmehovan od modrih mož, silno ogorčen in poslal ter usmrtil vse otroke, ki so bili v Betlehemu in v vseh teh krajih, od dveh let starosti in mlajše, glede na čas, ki ga je marljivo poizvedel od modrih mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tedaj je bilo izpolnjeno to, kar je bilo rečeno po preroku Jeremiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '›Tam v Rami je bilo slišati glas, objokovanje in jokanje ter veliko žalovanje. Rahela je jokala za svojimi otroki, pa ne bo potolažena, ker jih ni več.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Toda ko je bil Herod mrtev, glej, se Gospodov angel prikaže Jožefu v sanjah v Egiptu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'rekoč: »Vstani in vzemi mladega otroka in njegovo mater ter pojdi v Izraelovo deželo, kajti tisti, ki so mlademu otroku stregli po življenju, so mrtvi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'In vstal je in vzel mladega otroka in njegovo mater ter prišel v Izraelovo deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Toda ko je slišal, da je Arhelaj vladal v Judeji namesto svojega očeta Heroda, se je bal iti tja; in v sanjah od Boga posvarjen, se je obrnil proč, v galilejske kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'In prišel ter bival v mestu, imenovanem Nazaret, da se je lahko izpolnilo, kar je bilo rečeno po prerokih: »Imenoval se bo Nazarečan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'V tistih dneh je prišel Janez Krstnik, ki je v divjini Judeje pridigal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'in govoril: »Pokesajte se, kajti nebeško kraljestvo je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Kajti to je tisti, o katerem je govoril prerok Izaija, rekoč: ›Glas vpijočega v divjini: ›Pripravite Gospodovo pot, izravnajte njegove steze.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'In isti Janez je imel svoja oblačila iz kamelje dlake in usnjen pas okoli svojih ledij, njegova hrana pa so bile kobilice in divji med.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tedaj so hodili k njemu Jeruzalem in vsa Judeja in vsa področja okoli Jordana');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'in v Jordanu so bili krščeni po njem, priznavajoč svoje grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Toda ko je mnoge izmed farizejev in saducejev videl priti k njegovemu krstu, jim je rekel: »Oh gadji rod, kdo vas je opozoril, da pobegnete pred besom, ki pride?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Obrodite torej sadove, primerne kesanju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'in ne mislite, da v sebi rečete: ›Mi imamo Abrahama za svojega očeta,‹ kajti povem vam, da je Bog iz teh kamnov zmožen Abrahamu obuditi otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'In sedaj je poleg tega na korenino dreves položena sekira; zatorej bo vsako drevo, ki ne prinaša dobrega sadu, posekano in vrženo v ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Zares vas krščujem z vodo v kesanje, toda kdor prihaja za menoj, je veličastnejši kakor jaz, čigar čevljev nisem vreden prenašati; on vas bo krstil s Svetim Duhom in z ognjem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'katerega vejálnik je v njegovi roki in svoja tla bo temeljito očistil in svojo pšenico zbral v kaščo, toda pleve bo sežgal z nepogasljivim ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tedaj pride Jezus iz Galileje k Jordanu, do Janeza, da bi se mu dal krstiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Toda Janez mu je prepovedal, rekoč: »Jaz imam potrebo biti krščen od tebe, pa ti prihajaš k meni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jezus mu odgovori in reče: »Dopusti, da je to sedaj tako, kajti tako se nama spodobi, da izpolniva vso pravičnost.« Tedaj mu je pustil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, '§ Ko je bil Jezus krščen, je nemudoma stopil iz vode, in glej, pred njim so se odprla nebesa in zagledal je Božjega Duha spuščati se kakor golobico in blesketanje nad njim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'in glej, glas iz nebes, rekoč: »Ta je moj ljubljeni Sin, s katerim sem zelo zadovoljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tedaj je bil Jezus po Duhu voden v divjino, da bi bil skušan od hudiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Ko se je štirideset dni in štirideset noči postil, je bil potem lačen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'In ko je prišel k njemu skušnjavec, je rekel: »Če si Božji Sin, ukaži, da ti kamni postanejo kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'On pa je odgovoril in rekel: »Pisano je: ›Človek ne bo živel zgolj od kruha, temveč od vsake besede, ki izvira iz Božjih ust.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Tedaj ga hudič vzame gor v sveto mesto in ga postavi na vrh templja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'ter mu reče: »Če si Božji Sin, se vrzi dol, kajti pisano je: ›Svojim angelom bo dodelil zapoved glede tebe, in na svojih rokah te bodo nosili, da ne bi kadarkoli svojega stopala treščil ob kamen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jezus mu je rekel: »Prav tako je pisano: ›Ti ne boš skušal Gospoda, svojega Boga.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Hudič ga ponovno vzame na izjemno visoko goro in mu razkazuje vsa kraljestva sveta in njihovo slavo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'in mu reče: »Vse te stvari ti bom dal, če boš padel dol in me oboževal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tedaj mu Jezus reče: »Pojdi stran, Satan, kajti pisano je: ›Oboževal boš Gospoda, svojega Boga in njemu samemu boš služil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tedaj ga hudič pusti in glej, prišli so angeli ter mu služili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Ko je torej Jezus slišal, da je bil Janez vržen v ječo, je odšel v Galilejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'In ko je zapustil Nazaret, je prišel in prebival v Kafarnáumu, ki je ob morski obali, na mejah Zábulona in Neftálija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'da bi se lahko izpolnilo, kar je bilo rečeno po preroku Izaiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '›Dežela Zábulonova in dežela Neftálijeva, ob poti k morju, onstran Jordana, poganska Galileja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'ljudje, ki so sedeli v temi, so zagledali veliko svetlobo; in tem, ki so sedeli v področju in senci smrti, je zasvetila svetloba.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Od tedaj je Jezus začel oznanjati in govoriti: »Pokesajte se, kajti nebeško kraljestvo je blizu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'In Jezus, ko je hodil ob Galilejskem morju, je zagledal dva brata: Simona, imenovanega Peter ter njegovega brata Andreja, ki sta v morje metala mrežo, kajti bila sta ribiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'In jima reče: »Sledita mi in naredil vaju bom za ribiča ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'In nemudoma sta zapustila svoje mreže ter mu sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Ko je šel naprej od tam, je na ladji, z njunim očetom Zebedejem, zagledal dva druga brata, Jakoba, Zebedejevega sina ter njegovega brata Janeza, ki sta popravljala svoje mreže; in ju poklical.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'In takoj sta zapustila ladjo in svojega očeta ter mu sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'In Jezus je obkrožil vso Galilejo in učil v njihovih sinagogah in med ljudmi oznanjal evangelij kraljestva in ozdravljal vse vrste slabosti in vse vrste bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'In njegov slôves je šel po vsej celotni Siriji in k njemu so prinašali vse bolne ljudi, ki so bili prevzeti z različnimi boleznimi ter mukami in te, ki so bili obsedeni s hudiči in te, ki so bili blazni in te, ki so imeli paralizo in jih je ozdravljal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'In sledile so mu velike množice ljudi iz Galileje in iz Deseteromestja in iz Jeruzalema in iz Judeje in iz druge strani Jordana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'In ko je zagledal množice, se je povzpel na goro, in ko se je usedel, so k njemu prišli njegovi učenci');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'in odprl je svoja usta ter jih učil, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '»Blagoslovljeni so ubogi v duhu, kajti njihovo je nebeško kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Blagoslovljeni so tisti, ki žalujejo, kajti potolaženi bodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Blagoslovljeni so krotki, kajti podedovali bodo zemljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Blagoslovljeni so tisti, ki so lačni in žejni pravičnosti, kajti nasičeni bodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Blagoslovljeni so usmiljeni, kajti dosegli bodo usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Blagoslovljeni so čisti v srcu, kajti videli bodo Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Blagoslovljeni so miritelji, kajti imenovani bodo Božji otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Blagoslovljeni so tisti, ki so preganjani zaradi pravičnosti, kajti njihovo je nebeško kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Blagoslovljeni ste vi, ko vas bodo ljudje zasramovali in vas preganjali in bodo zaradi mene proti vam lažno govorili vse vrste zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Veselite se in bodite silno veseli, kajti velika je vaša nagrada v nebesih, kajti tako so preganjali preroke, ki so bili pred vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vi ste sol zemlje, toda če je sol izgubila svoj okus, s čim bo osoljena? Odslej ni dobra za nič, razen da je vržena proč in da jo ljudje pomendrajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vi ste svetloba svetu. Mesto, ki je postavljeno na hribu, ne more biti skrito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Niti ljudje ne prižgejo sveče in je ne postavijo pod mernik, temveč na svečnik in ta daje svetlobo vsem, ki so v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Naj vaša svetloba takó sveti pred ljudmi, da bodo lahko videli vaša dobra dela in proslavljali vašega Očeta, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne mislite, da sem prišel uničit postavo ali preroke; nisem prišel uničit, temveč izpolnit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Kajti resnično, povem vam: ›Dokler nebo in zemlja ne preideta, ena pika ali en delček nikakor ne bosta izpuščena iz postave, dokler se vsa ne izpolni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Kdorkoli bo torej prekršil eno od teh najmanjših zapovedi in bo tako učil ljudi, bo v nebeškem kraljestvu imenovan najmanjši, toda kdorkoli jih bo izpolnjeval in jih učil, isti bo v nebeškem kraljestvu imenovan velik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Kajti povem vam: ›Razen če vaša pravičnost ne bo presegla pravičnosti pisarjev in farizejev, v nobenem primeru ne boste vstopili v nebeško kraljestvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Slišali ste, da je bilo rečeno po teh iz starih časov: ›Ne boš ubil. Kdorkoli pa ubije, bo v nevarnosti sodbe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, '§ Toda povem vam: ›Da kdorkoli je brez razloga jezen na svojega brata, bo v nevarnosti sodbe,‹ in kdorkoli bo svojemu bratu rekel: ›Raka,‹ bo v nevarnosti pred vélikim zborom. Toda kdorkoli bo rekel: ›Ti bedak,‹ bo v nevarnosti peklenskega ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Zatorej, če prineseš svoj dar k oltarju in se tam spomniš, da ima tvoj brat zoper tebe dolg,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'pusti svoj dar tam pred oltarjem in pojdi svojo pot; najprej se pobotaj s svojim bratom in potem pridi ter daruj svoj dar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Hitro se dogovori s svojim nasprotnikom, medtem ko si z njim na poti, da te ne bi kadarkoli nasprotnik izročil sodniku, sodnik pa te izroči častniku in boš vržen v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Resnično, povem ti: ›Nikakor ne prideš od tam, dokler ne odplačaš zadnjega novčiča.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Slišali ste, da je bilo rečeno po teh iz starih časov: ›Ne boš zagrešil zakonolomstva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Toda povem vam: ›Da kdorkoli s poželenjem pogleda na žensko, je v svojem srcu z njo že zagrešil zakonolomstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'In če te tvoje desno oko pohujšuje, ga iztakni in ga vrzi od sebe; kajti zate je koristno, da bi eden izmed tvojih udov propadel in ne, da bi tvoje celó telo moralo biti vrženo v pekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'In če te tvoja desnica pohujšuje, jo odsekaj in jo vrzi od sebe; kajti zate je koristno, da bi eden izmed tvojih udov propadel, ne pa da bi tvoje celó telo moralo biti vrženo v pekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Rečeno je bilo: ›Kdorkoli bo odslovil svojo ženo, naj ji dá pisanje o ločitvi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, '§ Toda povem vam: ›Da kdorkoli bo odslovil svojo ženo, razen zaradi razloga prešuštva, ji povzroči, da ona zagreši zakonolomstvo; in kdorkoli bo poročil tisto, ki je ločena, zagreši zakonolomstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Ponovno, slišali ste, da je bilo rečeno po teh iz starih časov: ›Sebi ne boš prisegal krivo, temveč svoje prisege izpolni Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Toda povem vam: ›Sploh ne prisegajte; niti pri nebesih, kajti to je Božji prestol,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'niti pri zemlji, kajti ta je njegova pručka, niti pri Jeruzalemu, kajti to je mesto vélikega Kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Niti ne prisegaj pri svoji glavi, ker niti enega lasu ne moreš narediti belega ali črnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Toda vaš govor naj bo: ›Da, da;‹ ›Ne, ne.‹ Kajti karkoli je več kakor to, prihaja od zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Slišali ste, da je bilo rečeno: ›Oko za oko in zob za zob.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Toda povem vam: ›Da se ne upirajte zlu, temveč kdorkoli te bo udaril na tvoje desno lice, obrni k njemu tudi drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'In če se hoče katerikoli človek pravdati s teboj na sodišču in ti odvzeti tvoj plašč, naj ima tudi tvoje ogrinjalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'In kdorkoli te prisili, da greš miljo, pojdi z njim dve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Daj tistemu, ki te prosi in pred tistim, ki bi si izposodil od tebe, se ne obrni proč.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Slišali ste, da je bilo rečeno: ›Ljubil boš svojega bližnjega in sovražil svojega sovražnika.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, '§ Toda jaz vam povem: ›Ljubíte svoje sovražnike, blagoslavljajte te, ki vas preklinjajo, delajte dobro tem, ki vas sovražijo in molíte za tiste, ki vas kruto izkoriščajo in vas preganjajo,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'da boste lahko otroci svojega Očeta, ki je v nebesih, kajti on daje svojemu soncu, da vzhaja na zle in na dobre, ter pošilja dež na pravične in na nepravične.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, '§ Kajti če ljubite te, ki vas ljubijo, kakšno nagrado imate? Ne delajo celó davkarji tako?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'In če pozdravljate samo svoje brate, kaj delate več kakor drugi? Ne delajo celó davkarji tako?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Bodite zato popolni, prav tako, kakor je popoln vaš Oče, ki je v nebesih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '»Pazite se, da svoje miloščine ne izkazujete pred ljudmi, da bi jo le-ti videli, sicer nimate nobene nagrade od svojega Očeta, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Zato kadar daješ svojo miloščino, ne trobi pred seboj, kakor počno hinavci v sinagogah in na ulicah, da bi lahko imeli slavo od ljudi. Resnično, povem vam: ›Imajo svojo nagrado.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Toda kadar ti daješ miloščino, naj tvoja levica ne ve kaj počne tvoja desnica,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'da bo tvoja miloščina lahko na skrivnem in tvoj Oče, ki sam vidi na skrivnem, te bo javno nagradil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'In kadar moliš, ne bodi kakor so hinavci, kajti ti radi molijo, stoječ v sinagogah in na vogalih ulic, da jih ljudje lahko vidijo. Resnično, povem vam: ›Imajo svojo nagrado.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Toda ti, kadar ti moliš, vstopi v svojo sobico in ko si zaprl svoja vrata, moli k svojemu Očetu, ki je na skrivnem; in tvoj Oče, ki vidi na skrivnem, te bo nagradil javno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Toda ko molite, ne uporabljajte jalovih ponavljanj, kakor to počno pogani, kajti mislijo, da bodo uslišani zaradi svojega mnogega govorjenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne bodite jim zato podobni, kajti vaš Oče ve, katere stvari potrebujete, preden ga prosite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Zatorej molíte na ta način: ›Oče naš, ki si v nebesih: ›Posvečuje naj se tvoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Pridi tvoje kraljestvo. Zgôdi se tvoja volja na zemlji, kakor je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Daj nam danes naš vsakdanji kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'In odpusti nam naše dolge, kakor mi odpuščamo svojim dolžnikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, '§ In ne vôdi nas v skušnjavo, temveč nas osvobodi pred zlom, kajti tvoje je kraljestvo in moč in slava, na veke. Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Kajti če ljudem odpustite njihove prekrške, bo prav tako vaš nebeški Oče odpustil vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Toda če ljudem ne odpustite njihovih prekrškov, tudi vaš Oče ne bo odpustil vaših prekrškov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Poleg tega, kadar se postite, ne bodite kakor hinavci, potrtega obličja; kajti kazijo svoje obraze, da bi bilo ljudem videti, da se postijo. Resnično, povem vam: ›Imajo svojo nagrado.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Toda kadar se ti postiš, mazili svojo glavo in umij svoj obraz,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'da ne bo videti ljudem, da se postiš, temveč tvojemu Očetu, ki je na skrivnem, in tvoj Oče, ki vidi na skrivnem, te bo nagradil javno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne shranjujte si zakladov na zemlji, kjer molj in rja delata razkroj in kjer tatovi vlamljajo in kradejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'temveč si zase shranjujte zaklade v nebesih, kjer niti molj niti rja ne delata razkroja in kjer tatovi ne vlamljajo niti ne kradejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'kajti kjer je tvoj zaklad, tam bo tudi tvoje srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, '§ Svetloba telesa je oko; če je torej tvoje oko enovito, bo tvoje celotno telo polno svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Toda če bo tvoje oko hudobno, bo tvoje celotno telo polno teme. Če bo torej svetloba, ki je v tebi, tema, kako velika je ta tema!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nihče ne more služiti dvema gospodarjema; kajti ali bo enega sovražil in drugega ljubil, ali pa se bo držal k enemu in preziral drugega. Ne morete služiti Bogu in mamonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Zatorej vam pravim: ›Ne vznemirjajte se in ne skrbite glede svojega življenja, kaj boste jedli ali kaj boste pili niti za svoje telo, kaj boste oblekli. Kaj ni življenje več kot hrana in telo več kot oblačilo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Poglejte perjad neba, kajti ne seje niti ne žanje niti ne zbira v skednje, vendar jih vaš nebeški Oče hrani. Ali niste mnogo boljši kakor one?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kdo izmed vas lahko z vznemirjanjem in skrbmi svoji postavi doda en komolec?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'In zakaj se vznemirjate in skrbite za oblačilo? Preudarite o lilijah travnika, kako rastejo; ne garajo niti ne predejo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'In vendar vam povem: ›Da celó Salomon, v vsej svoji slavi, ni bil oblečen tako kakor ena izmed teh.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Zatorej, če Bog tako oblači travo polja, ki danes je, jutri pa je vržena v peč, ali ne bo mnogo bolj oblačil vas, oh vi, maloverni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Zato se ne vznemirjate in ne skrbite, rekoč: ›Kaj bomo jedli?‹ ali: ›Kaj bomo pili?‹ ali: ›S čim bomo oblečeni?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, '(Kajti za vsemi temi stvarmi povprašujejo pogani), kajti vaš nebeški Oče ve, da potrebujete vse te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Toda iščite najprej Božje kraljestvo in njegovo pravičnost in vse te stvari vam bodo dodane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Zato se ne vznemirjate in ne skrbite za jutrišnji dan, kajti jutrišnji dan bo sam poskrbel za stvari. Zadostno je dnevu le tega zlo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '»Ne sodite, da ne boste sojeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Kajti s kakršno sodbo vi sodite, boste sojeni in s kakršno mero merite, vam bo ponovno odmerjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'In zakaj gledaš drobec, ki je v očesu tvojega brata, toda ne preudarjaš o brunu, ki je v tvojem lastnem očesu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ali kako lahko rečeš svojemu bratu: ›Dovoli mi iz tvojega očesa izvleči drobec,‹ in glej, bruno je v tvojem lastnem očesu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Ti hinavec, najprej vrzi bruno iz svojega lastnega očesa in tedaj boš razločno videl vreči ven drobec iz očesa svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne dajajte tega, kar je sveto, psom niti ne mečite svojih biserov pred svinje, da jih ne bi pomendrale pod svojimi stopali in se obrnile proti vam in vas raztrgale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Prosite in to vam bo dano; iščite in boste našli; trkajte in se vam bo odprlo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'kajti vsak, kdor prosi, prejema; in kdor išče, najde; in tistemu, ki trka, se bo odprlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ali kakšen človek je tam izmed vas, če ga njegov sin prosi kruha, ali mu bo dal kamen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Ali če prosi ribe ali mu bo dal kačo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Če potem vi, ki ste hudobni, veste kako dajati dobra darila svojim otrokom, kako mnogo bolj bo vaš Oče, ki je v nebesih, dajal dobre stvari tistim, ki ga prosijo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Zatorej vse stvari, katerekoli si želite, da bi ljudje storili vam, storite vi njim popolnoma tako, kajti to je postava in preroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Vstopite pri ozkih vratih, kajti široka so vrata in prostrana je pot, ki vodi k uničenju in mnogo jih bo tam, ki gredo tja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'zato ker ozka so vrata in tesna je pot, ki vodi v življenje in tam jih bo malo, ki jo najdejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Varujte se lažnih prerokov, ki prihajajo k vam v ovčjih oblačilih, toda navznoter so požrešni volkovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Spoznali jih boste po njihovih sadovih. Mar ljudje obirajo grozdje iz trnja ali fige iz osata?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Točno takó vsako dobro drevo prinaša dober sad, toda slabo drevo prinaša hudoben sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Dobro drevo ne more obroditi hudobnega sadu niti slabo drevo ne more obroditi dobrega sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Vsako drevo, ki ne prinaša dobrega sadu, je posekano in vrženo v ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Zatorej jih boste spoznali po njihovih sadovih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ne bo vsak, kdor mi pravi: ›Gospod, Gospod,‹ vstopil v nebeško kraljestvo, temveč kdor izvršuje voljo mojega Očeta, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Mnogi mi bodo na tisti dan rekli: ›Gospod, Gospod, ali nismo v tvojem imenu prerokovali in v tvojem imenu izganjali hudičev in v tvojem imenu storili mnogo čudovitih del?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'In tedaj jim bom zatrdil: ›Nikoli vas nisem poznal. Odidite od mene, vi, ki počnete krivičnost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Zatorej kdorkoli sliši te moje besede in jih izvršuje, ga bom primerjal z modrim človekom, ki je svojo hišo zgradil na skali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'in padal je dež in prišle so poplave in pihali so vetrovi in udarili na to hišo; in ni padla, kajti bila je utemeljena na skali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'In vsak, kdor posluša te moje besede in jih ne izvršuje, bo primerjan z nespametnim človekom, ki je svojo hišo zgradil na pesku;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'in padal je dež in prišle so poplave in pihali so vetrovi ter udarili na to hišo; in je padla in njen padec je bil velik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'In pripetilo se je, ko je Jezus končal te govore, da je bila množica nad njegovim naukom osupla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'kajti poučeval jih je kakor nekdo, ki ima oblast in ne tako kakor pisarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Ko je prišel z gore, so mu sledile velike množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'In glej, prišel je gobavec ter ga oboževal, rekoč: »Gospod, če hočeš, me lahko očistiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jezus je iztegnil svojo roko in se ga dotaknil, rekoč: »Hočem; bodi čist.« In njegova gobavost je bila takoj očiščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'In Jezus mu reče: »Glej, da nikomur ne poveš, ampak pojdi svojo pot, pokaži se duhovniku in ponudi dar, ki ga je Mojzes zapovedal, njim v pričevanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'In ko je Jezus vstopil v Kafarnáum, je prišel k njemu stotnik, ki ga je rotil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'in govoril: »Gospod, moj služabnik leži doma bolan zaradi paralize, boleče mučen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'In Jezus mu reče: »Prišel bom in ga ozdravil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Stotnik je odgovoril in rekel: »Gospod, nisem vreden, da bi prišel pod mojo streho, ampak spregovori samo besedo in moj služabnik bo ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Kajti človek sem pod oblastjo, pod seboj imam vojake in temu možu rečem: ›Pojdi,‹ in gre; in drugemu: ›Pridi,‹ in pride; in svojemu služabniku: ›Naredi to‹ in to stori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Ko je Jezus to slišal, se je čudil in rekel tem, ki so mu sledili: »Resnično, povem vam: ›Nisem našel tako velike vere, ne, niti v Izraelu ne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'In pravim vam: ›Da bodo mnogi prišli od vzhoda in zahoda in se bodo usedli z Abrahamom in Izakom in Jakobom v nebeškem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Toda otroci kraljestva bodo vrženi ven v zunanjo temo; tam bo jokanje in škripanje z zobmi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'In Jezus je rekel stotniku: »Pojdi svojo pot in kakor si veroval, tako naj ti bo storjeno.« In njegov služabnik je bil prav isto uro ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'In ko je Jezus prišel v Petrovo hišo, je videl njegovo taščo ležati in bolno zaradi vročice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'In dotaknil se je njene roke in vročica jo je zapustila; in vstala je ter jim stregla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, '§ Ko je prišel večer, so k njemu privedli mnoge, ki so bili obsedeni s hudiči; in s svojo besedo je izgnal duhove in ozdravil vse, ki so bili bolni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'da bi se lahko izpolnilo, kar je bilo rečeno po preroku Izaiju, rekoč: ›On sam je vzel naše slabotnosti in nosil naše bolezni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Potem ko je Jezus okoli sebe videl velike množice, je dal zapoved, da odidejo na drugo stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Prišel pa je nek pisar in mu rekel: »Učitelj, sledil ti bom, kamorkoli greš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jezus mu reče: »Lisice imajo luknje in ptice neba imajo gnezda, toda Sin človekov nima kam nasloniti svoje glave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'In še eden izmed njegovih učencev mu je rekel: »Gospod, dovoli mi najprej, da grem in pokopljem svojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Toda Jezus mu je rekel: »Sledi mi, mrtvi pa naj pokopljejo svoje mrtve.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'In ko je stopil na ladjo, so mu njegovi učenci sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'In glej, na morju se je vzdignil velik vihar, do take mere, da je bila ladja pokrita z valovi. Toda on je spal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'In njegovi učenci so prišli k njemu ter ga zbudili, rekoč: »Gospod reši nas, mi umiramo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'In reče jim: »Zakaj ste boječi, oh vi maloverni?« Tedaj je vstal in oštel vetrove in morje in bil je velik mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Toda možje so se čudili, rekoč: »Kakšne vrste človek je ta, da so mu pokorni celó vetrovi in morje!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'In ko je prišel na drugo stran, v Gadársko deželo, sta ga tam srečala dva obsedena s hudiči, ki sta prihajala iz grobnic, silno kruta, tako da noben človek ni mogel iti mimo po tej poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'In glej, zakričala sta, rekoč: »Kaj imava midva opraviti s teboj, Jezus, ti Božji Sin? Ali si prišel sèm, da nas pred časom mučiš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Daleč proč od njih pa je bila čreda mnogih svinj, ki so se pasle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Hudiči so ga torej rotili, rekoč: »Če nas izženeš, nam pusti, da gremo proč, v čredo svinj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'In rekel jim je: »Pojdite.« In ko so prišli ven, so odšli v čredo svinj. In glej, cela čreda svinj je silovito stekla po strmini navzdol v morje ter poginila v vodah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'In tisti, ki so jih čuvali, so pobegnili in po svojih poteh odšli v mesto in povedali vsako stvar in kaj je doletelo obsedena od hudičev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'In glej, celó mesto je prišlo ven, da sreča Jezusa; in ko so ga zagledali, so ga rotili, da odide iz njihovih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'In vstopil je na ladjo in se peljal čez ter prišel v svoje lastno mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'In glej, k njemu so prinesli moža, bolnega zaradi paralize, ki je ležal na postelji. Ko pa je Jezus videl njihovo vero, je rekel bolnemu zaradi paralize: »Sin, bodi dobre volje, tvoji grehi so ti odpuščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'In glej, nekateri izmed pisarjev so v sebi govorili: »Ta človek preklinja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Ker pa je Jezus poznal njihove misli, je rekel: »Zakaj v svojih srcih razmišljate hudobno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Kajti ali je lažje reči: ›Tvoji grehi so ti odpuščeni‹ ali reči: ›Vstani in hôdi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Toda da boste lahko vedeli, da ima Sin človekov na zemlji oblast odpuščati grehe,« (tedaj reče bolnemu zaradi paralize), »vstani, vzemi svojo posteljo in pojdi v svojo hišo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'In ta je vstal in odšel v svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Toda ko so množice to videle, so se čudile in slavile Boga, ki je ljudem dal takšno oblast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'In ko je Jezus šel naprej od tam, je zagledal moža, imenovanega Matej, ki je sedel pri kraju plačevanja davkov in mu rekel: »Sledi mi.« In ta je vstal ter mu sledil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'In pripetilo se je, da ko je Jezus v hiši sedel pri obedu, glej, je prišlo mnogo davkarjev in grešnikov ter sédlo z njim in njegovimi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'In ko so farizeji to videli, so njegovim učencem rekli: »Zakaj vaš Učitelj jé z davkarji in grešniki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Toda ko je Jezus to zaslišal, jim je rekel: »Tisti, ki so zdravi, ne potrebujejo zdravnika, temveč tisti, ki so bolni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, '§ Toda pojdite in se naučite, kaj pomeni to: ›Usmiljenje hočem imeti, ne pa žrtve, kajti nisem prišel, da kličem pravične, temveč grešnike h kesanju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tedaj so k njemu prišli Janezovi učenci, rekoč: »Zakaj se mi in farizeji često postimo, tvoji učenci pa se ne postijo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jezus jim je rekel: »Ali lahko otroci svatovske sobe žalujejo, dokler je z njimi ženin? Toda prišli bodo dnevi, ko bo ženin odvzet od njih in tedaj se bodo postili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Nihče ne polaga koščka novega oblačila na staro obleko, kajti to, kar je vstavljeno, da jo zapolni, trga iz obleke in nastane hujša raztrganina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Niti ljudje novega vina ne dajejo v stare mehove. Sicer mehovi počijo in vino izteče ven in mehovi propadejo; temveč novo vino vlivajo v nove mehove in je oboje ohranjeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Medtem ko jim je govoril vse te besede, glej, je prišel nek vladar in ga oboževal, rekoč: »Moja hči je pravkar umrla, toda pridi in položi nanjo svojo roko in bo živela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'In Jezus je vstal in mu sledil in tako so storili tudi njegovi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'In glej, ženska, ki je bila dvanajst let bolna s težavo krvi, je prišla za njim ter se dotaknila obšiva njegove obleke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'kajti v sebi je rekla: »Če se lahko samo dotaknem njegove obleke, bom postala zdrava.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Toda Jezus se je obrnil in ko jo je zagledal, je rekel: »Hči, bodi dobro potolažena, tvoja vera te je naredila zdravo.« In ženska je bila od te ure zdrava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Ko je Jezus prišel v vladarjevo hišo in videl flavtiste in množico, ki je delala hrup,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'jim je rekel: »Dajte prostor, kajti deklica ni mrtva, temveč spi.« Oni pa so se mu smejali do norčevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Toda ko je bila množica porinjena ven, je vstopil ter jo prijel za roko in deklica je vstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'In slôves o tem je šel daleč po vsej tej deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'In ko je Jezus odšel od tam, sta mu sledila dva slepa človeka, ki sta vpila in govorila: » Ti, Davidov Sin, usmili se naju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'In ko je prišel v hišo, sta k njemu prišla slepa človeka in Jezus jima reče: »Ali verujeta, da sem zmožen to storiti?« Rekla sta mu: »Da, Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tedaj se je dotaknil njunih oči, rekoč: »Naj se vama zgodi glede na vajino vero.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'In njune oči so bile odprte in Jezus jima je strogo naročil, rekoč: »Glejta, da tega nihče ne izve.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Toda ko sta onadva odšla, sta v vsej tej deželi povsod razširila njegov slôves.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, '§ Ko sta odšla ven, glej, so k njemu prinesli nemega moža, obsedenega s hudičem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'In ko je bil hudič izgnan, je nemi spregovoril in množice so se čudile, rekoč: »Nikoli ni bilo tega videti v Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Toda farizeji so rekli: »Hudiče izganja s pomočjo princa hudičev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, '§ In Jezus je hodil naokrog po vseh mestih in vaseh in učil v njihovih sinagogah ter oznanjal evangelij kraljestva in med ljudmi ozdravljal vsako slabost in vsako bolezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Toda ko je videl množice, je bil prevzet s sočutjem do njih, ker so oslabeli in so bili razkropljeni naokoli kakor ovce brez pastirja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tedaj reče svojim učencem: »Žetev je resnično obilna, toda delavcev je malo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Prosite torej Gospoda žetve, da bo poslal delavce na svojo žetev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'In ko je k sebi poklical svojih dvanajst učencev, jim je dal oblast zoper nečiste duhove, da jih izženejo in da ozdravijo vse vrste slabosti in vse vrste bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Imena dvanajsterih apostolov so torej ta: prvi Simon, ki so ga imenovali Peter in njegov brat Andrej; Jakob, Zebedejev sin in njegov brat Janez;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, '§ Filip in Bartolomej; Tomaž in Matej davkar; Jakob, Alfejev sin in Lebej, katerega vzdevek je bil Tadej;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon Kananej in Juda Iškarijot, ki ga je tudi izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Teh dvanajst je Jezus poslal in jim zapovedal, rekoč: »Ne pojdite na pot poganov in ne vstopite v nobeno samarijsko mesto,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'temveč pojdite raje k izgubljenim ovcam Izraelove hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'In ko greste, oznanjujte, rekoč: ›Nebeško kraljestvo je blizu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Ozdravljajte bolne, očiščujte gobave, obujajte mrtve, izganjajte hudiče. Zastonj ste prejeli, zastonj dajajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne priskrbite si ne zlata ne srebra ne brona v svojih mošnjah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ne malhe za svojo pot niti dveh plaščev niti čevljev in tudi ne palic, kajti delavec je vreden svoje hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'In v katerokoli mesto ali vas boste vstopili, povprašajte kdo v njej je vreden in tam ostanite, dokler ne greste od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'In ko vstopite v hišo, jo pozdravite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'In če je hiša vredna, naj pride nanjo vaš mir, toda če tega ni vredna, naj se vaš mir povrne k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Kdorkoli pa vas ne bo sprejel niti ne bo poslušal vaših besed, ko odidete iz te hiše ali mesta, si iz svojih stopal otresite prah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Resnično, povem vam: ›Bolj znosno bo na dan sodbe za deželo Sódome in Gomóre, kakor za to mesto.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Glejte, pošiljam vas kakor ovce v sredo volkov. Bodite torej modri kakor kače in neškodljivi kakor golobice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Toda varujte se ljudi, kajti izročali vas bodo sodiščem in vas bičali v njihovih sinagogah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'in zaradi mene boste privedeni pred voditelje in kralje, v pričevanje proti njim in poganom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Toda ko vas izročijo, se ne vznemirjate in ne skrbite kako ali kaj boste govorili, kajti v tej isti uri vam bo dano, kar boste govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Kajti niste vi, ki govorite, temveč Duh vašega Očeta je, ki govori v vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'In brat bo brata izročil v smrt in oče otroka in otroci se bodo dvignili zoper svoje starše in jim povzročili, da bodo usmrčeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'In vsi ljudje vas bodo sovražili zaradi mojega imena, toda kdor vztraja do konca, bo rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Toda ko vas preganjajo v tem mestu, bežite v drugo, kajti resnično, povem vam: ›Ne boste šli skozi Izraelova mesta, dokler ne pride Sin človekov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Učenec ni nad svojim učiteljem niti ni služabnik nad svojim gospodarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Dovolj je za učenca, da postane kakor njegov učitelj in služabnik kakor njegov gospodar. Če so hišnega učitelja imenovali Bélcebub, koliko bolj bodo imenovali te iz njegove družine?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne bojte se jih torej, kajti nič ni prikrito, kar ne bo razkrito in skrito, kar se ne bo izvedelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Kar vam povem v temi, to govorite na svetlobi in kar slišite na uho, to oznanjujte na hišnih strehah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'In ne bojte se tistih, ki ubijejo telo, toda niso zmožni ubiti duše, temveč se raje bojte njega, ki je zmožen uničiti tako dušo kakor telo v peklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Ali nista dva vrabca prodajana za novčič? In nobeden izmed njiju ne bo padel na tla brez vašega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Toda celó lasje vaše glave so vsi prešteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne bojte se torej, vredni ste več kakor mnogo vrabcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Kdorkoli bo torej mene priznal pred ljudmi, bom prav tako jaz njega priznal pred svojim Očetom, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Toda kdorkoli me bo zatajil pred ljudmi, bom prav tako jaz njega zatajil pred svojim Očetom, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne mislite, da sem prišel, da pošljem mir na zemljo; nisem prišel, da pošljem mir, temveč meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Kajti prišel sem, da postavim človeka v nestrinjanje proti svojemu očetu in hčer proti njeni materi in snaho proti njeni tašči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'In človekovi sovražniki bodo tisti iz njegove lastne družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kdor ima rajši očeta ali mater bolj kakor mene, me ni vreden; in kdor ima rajši sina ali hčer bolj kakor mene, me ni vreden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'In kdor ne vzame svojega križa in mi ne sledi, me ni vreden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kdor najde svoje življenje, ga bo izgubil; kdor pa izgubi svoje življenje zaradi mene, ga bo našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kdor sprejema vas, sprejema mene in kdor sprejema mene, sprejema tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kdor sprejema preroka v imenu preroka, bo prejel nagrado preroka; in kdor sprejema pravičnega človeka v imenu pravičnega človeka, bo prejel nagrado pravičnega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'In kdorkoli bo dal piti enemu od teh malčkov samo čašo mrzle vode v imenu učenca, resnično, povem vam, nikakor ne bo izgubil svoje nagrade.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'In pripetilo se je, ko je Jezus končal z naročanjem svojim dvanajsterim učencem, [da] je odšel od tam, da uči in oznanja v njihovih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Potem ko je Janez v ječi slišal Kristusova dela, je poslal dva izmed svojih učencev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'in [ta dva] sta mu rekla: »Ali si ti tisti, ki naj bi prišel ali naj pričakujemo drugega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jezus je odgovoril in jima rekel: »Pojdita in Janezu ponovno izpričajta te stvari, ki jih slišita in vidita:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, '›Slepi prejemajo svoj vid in hromi hodijo, gobavi so očiščeni in gluhi slišijo, mrtvi so obujeni in revnim se oznanja evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'In blagoslovljen je tisti, ki v meni ne bo pohujšan.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Ko sta odšla, je Jezus začel množicam govoriti glede Janeza: »Kaj ste odšli gledat ven v divjino? Trst, ki se maje z vetrom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Toda kaj ste šli ven, da bi videli? Moža, oblečenega v mehka oblačila? Glejte, tisti, ki nosijo mehka oblačila, so v kraljevih hišah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Toda kaj ste šli ven, da bi videli? Preroka? Da, povem vam in več kakor preroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Kajti ta je tisti, o katerem je pisano: ›Glejte, pošljem svojega poslanca pred tvojim obrazom, ki bo pripravil tvojo pot pred teboj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Resnično, povem vam: ›Med temi, ki so rojeni iz žensk, ni bil obujen večji kakor Janez Krstnik, vendar kdor je v nebeškem kraljestvu najmanjši, je večji kakor on.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'In od dni Janeza Krstnika do sedaj nebeško kraljestvo trpi nasilje in nasilni ga zavzemajo s silo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Kajti vsi preroki in postava so prerokovali do Janeza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'In če boste to sprejeli, to je Elija, ki je moral priti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kdor ima ušesa, da sliši, naj posluša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Toda s kom bom primerjal ta rod? Podoben je otrokom, ki sedijo po trgih in kličejo svojim rojakom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'ter govorijo: ›Piskali smo vam, pa niste plesali; objokovali smo vam, pa niste žalovali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Kajti Janez je prišel, niti ni jedel, niti ni pil, pa pravijo: ›Hudiča ima.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, '§ Sin človekov je prišel in jé in pije, pa pravijo: ›Glejte, požrešen človek in vinski bratec, prijatelj davkarjev in grešnikov.‹ Toda modrost je opravičena po svojih otrocih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tedaj je začel oštevati mesta, v katerih je bila storjena večina njegovih mogočnih del, ker se nista pokesala:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '»›Gorje ti, Horazín! Gorje ti, Betsajda! Kajti če bi se mogočna dela, ki so bila storjena v vama, storila v Tiru in Sidónu, bi se že davno pokesala v vrečevini in pepelu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Toda povem vam: ›Bolj znosno bo na dan sodbe za Tir in Sidón, kakor vama.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'In ti, Kafarnáum, ki si bil vzvišen do neba, boš priveden navzdol do pekla; kajti če bi se mogočna dela, ki so bila storjena v tebi, zgodila v Sódomi, bi preostala do današnjega dne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Toda povem ti: ›Da bo na dan sodbe bolj znosno za sódomsko deželo kakor zate.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Ob tistem času je Jezus odgovoril in rekel: »Zahvaljujem se tebi, oh Oče, Gospodar neba in zemlje, ker si te stvari skril pred modrimi in razsodnimi, razodel pa si jih otročičem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Točno tako, Oče, kajti tako se je zdelo dobro v tvojih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Vse stvari so mi izročene od mojega Očeta in noben človek ne pozna Sina, razen Očeta, niti noben človek ne pozna Očeta, razen Sina in tega komurkoli ga bo Sin razodel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Pridite k meni vsi vi, ki se trudite in ste težko obremenjeni in dal vam bom počitek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Vzemite nase moj jarem in se učite od mene, ker sem krotak in ponižen v srcu, in našli boste počitek svojim dušam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Kajti moj jarem je udoben in moje breme je lahko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Ob tistem času je šel Jezus na šabatni dan skozi žitna polja, njegovi učenci pa so bili lačni in začeli smukati žitno klasje ter jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Toda ko so to videli farizeji, so mu rekli: »Glej, tvoji učenci delajo to, česar ni zakonito početi na šabatni dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Toda rekel jim je: »Ali niste brali, kaj je storil David, ko je bil lačen in tisti, ki so bili z njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'kako je vstopil v Božjo hišo in jedel hlebe navzočnosti, ki jih ni bilo dovoljeno jesti njemu niti ne tistim, ki so bili z njim, temveč samo duhovnikom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ali niste brali v postavi, kako to, da ob šabatnih dneh duhovniki v templju skrunijo šabat in so brez krivde?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Toda povem vam: ›Da je na tem kraju nekdo večji kakor tempelj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Toda če bi vedeli, kaj to pomeni: ›Usmiljenje hočem imeti in ne žrtve,‹ ne bi obsojali nedolžnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Kajti Sin človekov je Gospod celó šabatnemu dnevu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'In ko je odšel od tam, je šel v njihovo sinagogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'In glej, tam je bil človek, ki je imel svojo roko izsušeno. In da bi ga lahko obdolžili, so ga vprašali, rekoč: »Ali je zakonito zdraviti na šabatne dneve?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'In rekel jim je: »Kateri človek bi bil tukaj med vami, ki bi imel eno ovco in če bi ta na šabatni dan padla v jamo ali je ne bi prijel ter je dvignil ven?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Koliko bolj je potem človek boljši kakor ovca? Zaradi tega je na šabatne dneve zakonito delati dobro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tedaj reče človeku: »Iztegni svojo roko.« In ta jo je iztegnil in bila je v celoti ozdravljena, podobno kakor druga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Potem so farizeji odšli ven in imeli zborovanje proti njemu, kako bi ga lahko pokončali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Toda ko je Jezus to izvedel, se je umaknil od tam in sledile so mu velike množice in vse je ozdravil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'ter jim naročil, da naj ga ne razglašajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'da bi se lahko izpolnilo, kar je bilo rečeno po preroku Izaiju, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '›Glej moj služabnik, ki sem ga izbral, moj ljubljeni, v katerem je moja duša zelo zadovoljna. Svojega duha bom položil nadenj in oznanil bo sodbo poganom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ne bo se ne prepiral niti ne vpil niti na ulicah nihče ne bo slišal njegovega glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Poškodovanega trsta ne bo zlomil in kadečega stenja ne bo pogasil, dokler ne privede sodbe do zmage.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'In v njegovo ime bodo zaupali pogani.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, '§ Tedaj je bil k njemu priveden nekdo obseden s hudičem, slep in nem in ga je ozdravil, do take mere, da je slepi in nemi tako govoril kakor videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'In vsa množica je bila osupla ter rekla: »Ali ni ta Davidov sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Toda ko so farizeji to slišali, so rekli: »Ta ne izganja hudičev, razen z Bélcebubom, princem hudičev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, '§ Jezus pa je poznal njihove misli in jim rekel: »Vsako kraljestvo, razdeljeno zoper sebe, je privedeno v opustošenje in nobeno mesto ali hiša, razdeljena zoper sebe, ne bosta obstala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'In če Satan izganja Satana, je razdeljen zoper sebe; kako bo potem obstalo njegovo kraljestvo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'In če z Bélcebubom izganjam hudiče, s kom jih izganjajo vaši otroci? Zatorej bodo oni vaši sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Toda če z Božjim Duhom izganjam hudiče, potem je k vam prišlo Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Kako lahko sicer nekdo vstopi v hišo močnega in opleni njegove dobrine, razen če najprej ne zveže močnega? In tedaj bo oplenil njegovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kdor ni z menoj, je proti meni; in kdor ne zbira z menoj, razsipa na široko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Zatorej vam pravim: ›Vsake vrste greh in bogokletje bo ljudem odpuščeno, toda bogokletje zoper Svetega Duha ljudem ne bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'In kdorkoli govori besedo zoper Sina človekovega, mu bo to odpuščeno; toda kdorkoli govori zoper Svetega Duha, mu ne bo odpuščeno ne na tem svetu ne v svetu, ki pride.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ali drevo dobro obrodi in je njegov sad dober, ali pa drevo slabo obrodi in je njegov sad slab; kajti drevo se spozna po njegovem sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Oh gadji rod, kako lahko vi, ki ste hudobni, govorite dobre besede? Kajti iz obilja srca usta govoré.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dober človek iz dobrega zaklada srca prinaša dobre stvari, hudobnež pa iz zlega zaklada prinaša zle stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Toda povem vam: ›Za vsako prazno besedo, ki jo bodo ljudje izgovorili, bodo na dan sodbe o tem dajali obračun.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Kajti po svojih besedah boš opravičen in po svojih besedah boš obsojen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tedaj so nekateri izmed pisarjev in farizejev odgovorili, rekoč: »Učitelj, od tebe želimo videti znamenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Toda odgovoril jim je in rekel: »Hudoben in zakonolomen rod išče znamenje, pa mu ne bo dano nobeno drugo znamenje, razen znamenja preroka Jona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Kajti tako, kakor je bil Jona tri dni in tri noči v kitovem trebuhu, tako bo Sin človekov tri dni in tri noči v osrčju zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ljudje iz Niniv bodo ob sodbi vstali s tem rodom in ga obsodili, ker so se ob Jonovem oznanjevanju pokesali; in glejte, tukaj je večji kakor Jona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Kraljica z juga bo ob sodbi vstala s tem rodom in ga obsodila, kajti prišla je iz najbolj oddaljenih krajev zemlje, da sliši Salomonovo modrost; in glejte, tukaj je večji kakor Salomon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Kadar je nečisti duh odšel iz človeka, hodi po suhih krajih, iščoč počitka, in ga ne najde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Potem reče: ›Vrnil se bom v svojo hišo, od koder sem izšel.‹ In ko pride, jo najde prazno, pometeno in okrašeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tedaj gre in s seboj vzame sedem drugih duhov, zlobnejših kakor on sam in vstopijo ter prebivajo tam in končno stanje tega človeka je slabše kakor prvo. Točno tako bo tudi temu zlobnemu rodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Medtem ko je še govoril množici, glej, so stali zunaj njegova mati in njegovi bratje, želeč govoriti z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Potem mu je nekdo rekel: »Glej, tvoja mati in tvoji bratje stojijo zunaj in želijo govoriti s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Toda odgovoril je in rekel tistemu, ki mu je povedal: »Kdo je moja mati? In kdo so moji bratje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'In svojo roko je iztegnil proti svojim učencem ter rekel: »Glejte, moja mati in moji bratje!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Kajti kdorkoli bo izvrševal voljo mojega Očeta, ki je v nebesih, ta je moj brat in sestra in mati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Isti dan je Jezus odšel iz hiše in se usedel ob morski obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'In k njemu so bile zbrane skupaj velike množice, tako da je odšel na ladjo in se usedel, vsa množica pa je stala na bregu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'In v prispodobah jim je govoril mnoge besede, rekoč: »Glejte, sejalec je odšel sejat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'in ko je sejal, je nekaj semen padlo poleg poti in prišla je perjad ter jih požrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Nekaj jih je padlo na kamnita mesta, kjer niso imela veliko zemlje in so nemudoma pognala, ker niso imela globine zemlje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'in ko je bilo sonce zgoraj, so bila ožgana in ker niso imela korenine, so ovenela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'In nekaj jih je padlo med trnje in trnje je pognalo ter jih zadušilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Toda druga so padla v dobro zemljo in obrodila sad, nekatera stoternega, nekatera šestdeseternega, nekatera trideseternega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kdor ima ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'In prišli so učenci ter mu rekli: »Zakaj jim govoriš v prispodobah?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Odgovoril je in jim rekel: »Ker je vam dano spoznati skrivnosti nebeškega kraljestva, toda njim to ni dano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Kajti kdorkoli ima, njemu bo dano in imel bo večje obilje; toda kdorkoli nima, bo od njega vzeto proč celó to, kar ima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Zatorej jim govorim v prispodobah, ker gledajo, a ne vidijo in poslušajo, a ne slišijo niti ne razumejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'In v njih se je izpolnila Izaijeva prerokba, ki pravi: ›S poslušanjem boste slišali, pa ne boste razumeli; in gledali boste ter videli, pa ne boste zaznali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'kajti srce teh ljudi je otopelo in njihova ušesa so naglušna in svoje oči so zaprli, da ne bi lahko kadarkoli s svojimi očmi videli in s svojimi ušesi slišali in bi s svojim srcem razumeli ter bi bili spreobrnjeni in bi jih jaz ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Toda blagoslovljene so vaše oči, ker vidijo, in vaša ušesa, ker slišijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Kajti resnično, povem vam: ›Da je veliko prerokov in pravičnih ljudi želelo videti te stvari, ki jih vi vidite, pa jih niso videli; in slišati te besede, ki jih vi slišite, pa jih niso slišali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Poslušajte torej prispodobo o sejalcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Kadar kdorkoli sliši besedo o kraljestvu, pa je ne razume, potem pride ta zlobni in izdere to, kar je bilo posejano v njegovo srce. To je tisti, ki je seme sprejel poleg poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Toda kdor je seme sprejel na kamnita mesta, je isti kakor kdor sliši besedo in jo takoj z radostjo sprejme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'vendar v sebi nima korenine, toda nekaj časa vztraja. Ko pa zaradi besede nastane stiska ali preganjanje, on v kratkem greši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Tudi tisti, ki je seme sprejel med trnje, je tisti, ki sliši besedo. Skrb tega sveta in zapeljivost bogastev pa zadušita besedo in on postaja brez sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Toda kdor je seme sprejel v dobro zemljo, je tisti, ki sliši besedo in jo razume, ki prav tako prinaša sad in obrodi, eden stoternega, drugi šestdeseternega, [spet] drugi trideseternega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Podal jim je drugo prispodobo, rekoč: »Nebeško kraljestvo je podobno človeku, ki je na svojo njivo posejal dobro seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Toda medtem ko so ljudje spali, je prišel njegov sovražnik in med pšenico posejal plevel ter odšel svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Toda ko je bilka pognala in obrodila sad, potem se je prikazal tudi plevel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Služabniki hišnega gospodarja so torej prišli in mu rekli: ›Gospod, ali nisi v svojo njivo posejal dobrega semena? Od kod ima potem le-ta plevel?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Rekel jim je: ›To je storil sovražnik.‹ Služabniki so mu rekli: ›Hočeš potem, da gremo in ga poberemo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Toda rekel je: ›Ne, da ne bi, medtem ko pobirate plevel, z njim izruvali tudi pšenice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Naj oboje skupaj raste do žetve, in ob času žetve bom rekel žanjcem: ›Zberite skupaj najprej plevel in ga povežite v svežnje za sežig, toda pšenico zberite v moj skedenj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Podal jim je drugo prispodobo, rekoč: »Nebeško kraljestvo je podobno zrnu gorčičnega semena, ki ga je človek vzel in posejal na svoji njivi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'ki je zares najmanjše od vseh semen, toda ko to zraste, je največje med zelišči in postane drevo, tako da pridejo ptice neba in prenočujejo na njegovih vejah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Povedal jim je drugo prispodobo: »Nebeško kraljestvo je podobno kvasu, ki ga je ženska vzela in skrila v treh merah moke, dokler ni bilo vse prekvašeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Vse te besede je Jezus množici govoril v prispodobah; brez prispodobe pa jim ni govoril,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'da bi se lahko izpolnilo, kar je bilo rečeno po preroku, rekoč: »Svoja usta bom odprl v prispodobah, izrekel bom besede, ki so bile od ustanovitve sveta hranjene na skrivnem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tedaj je Jezus množico poslal proč in odšel v hišo, in njegovi učenci so prišli k njemu, rekoč: »Pojasni nam prispodobo o poljskem plevelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Odgovoril je in jim rekel: »Kdor seje dobro seme, je Sin človekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Njiva je svet. Dobro seme so otroci kraljestva, toda plevel so otroci zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Sovražnik, ki jih je posejal, je hudič. Žetev je konec sveta, žanjci pa so angeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Kakor je torej plevel pobran in v ognju sežgan, tako bo ob koncu tega sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Sin človekov bo poslal svoje angele in iz njegovega kraljestva bodo pobrali vse stvari, ki so padle v greh in tiste, ki počno krivičnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'in vrgli jih bodo v ognjeno talilno peč. Tam bo tarnanje in škripanje z zobmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Potem bodo pravični zasijali kakor sonce v kraljestvu svojega Očeta. Kdor ima ušesa, da slišijo, naj posluša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Ponovno, nebeško kraljestvo je podobno zakladu, skritemu na njivi. Ko ga je človek našel, ga skrije in zaradi radosti gre in proda vse, kar ima in to polje kupi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Ponovno, nebeško kraljestvo je podobno trgovcu, ki išče lepe bisere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'ki je, ko je našel en biser velike vrednosti, šel in prodal vse, kar je imel ter ga kupil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Ponovno, nebeško kraljestvo je podobno mreži, ki je bila vržena v morje in je zajela od vseh vrst,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'ki so jo, ko je bila polna, odvlekli do obale in se usedli ter dobre zbrali v posode, toda slabe so vrgli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tako bo torej ob koncu sveta. Prišli bodo angeli in zlobne bodo oddvojili od pravičnih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'in jih vrgli v ognjeno talilno peč. Tam bo tarnanje in škripanje z zobmi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '§ Jezus jim reče: »Ste razumeli vse te besede?« Rečejo mu: »Da, Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Tedaj jim je rekel: »Zato je vsak pisar, ki je poučen o nebeškem kraljestvu, podoben človeku, ki je hišni gospodar, ki prinaša iz svojega zaklada nove in stare stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'In pripetilo se je, ko je Jezus zaključil te prispodobe, da je odšel od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'In ko je prišel v svojo lastno deželo, jih je v njihovi sinagogi učil, do take mere, da so bili osupli in govorili: »Od kod ima ta človek to modrost in ta mogočna dela?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ali ni to tesarjev sin? Ali ni njegova mati imenovana Marija? In njegovi bratje Jakob in Jožef in Simon in Juda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'In njegove sestre ali niso vse z nami? Od kod ima potem ta človek vse te stvari?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'In pohujševali so se nad njim. Toda Jezus jim je rekel: »Prerok ni brez spoštovanja, razen v svoji lastni deželi in v svoji lastni hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'In tam zaradi njihove nevere ni storil veliko mogočnih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, '§ Ob tistem času je Herod, vladar četrtinskega dela province, slišal o Jezusovem slôvesu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'in rekel svojim služabnikom: »To je Janez Krstnik. Obujen je od mrtvih in zato so se v njem naznanila mogočna dela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Kajti Herod je prijel Janeza in ga zvezal ter ga posadil v ječo zaradi Herodiade, žene svojega brata Filipa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Kajti Janez mu je rekel: »Zate ni zakonito, da jo imaš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Ko pa ga je skušal usmrtiti, se je zbal množice, ker so ga šteli za preroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Toda ko je bil Herodov rojstni dan, je Herodiadina hči plesala pred njimi in se dopadla Herodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Nakar ji je ta s prisego obljubil dati, karkoli bi prosila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'In ona je, prej poučena od svoje matere, rekla: »Daj mi tukaj, na velikem pladnju, glavo Janeza Krstnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'In kralju je bilo žal. Kljub temu je zaradi prisege in teh, ki so z njim sedeli pri obedu, velel, da naj ji bo dana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'In poslal je ter v ječi obglavil Janeza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'In njegova glava je bila prinesena na velikem pladnju ter dana gospodični in ona jo je odnesla svoji materi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'In prišli so njegovi učenci in vzeli telo ter ga pokopali in odšli ter povedali Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Ko je Jezus slišal o tem, je od tam z ladjo ločeno odplul v zapuščen kraj. In ko je množica slišala o tem, mu je peš sledila iz mest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, '§ In Jezus je odšel naprej in zagledal veliko množico in bil prevzet s sočutjem do njih in ozdravil njihove bolne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'In ko je bil večer, so k njemu prišli njegovi učenci, rekoč: »To je zapuščen kraj in čas je sedaj potekel. Pošlji množico proč, da bodo lahko šli v vasi in si kupili živeža.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Toda Jezus jim je rekel: »Ni jim treba oditi proč, vi jim dajte jesti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'In rekli so mu: »Mi imamo tukaj samo pet hlebov in dve ribi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Rekel je: »Prinesite jih sèm k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'In velel je množici, naj séde na travo in vzel je pet hlebov ter dve ribi in zroč k nebu, je blagoslovil in razlomil ter hlebe dal svojim učencem, učenci pa množici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'In vsi so jedli in bili nasičeni in od odlomkov, ki so ostali, so pobrali dvanajst polnih košar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'In teh, ki so jedli, je bilo okoli pet tisoč mož, poleg žensk in otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, '§ In Jezus je svoje učence nemudoma primoral, naj stopijo na ladjo in da gredo pred njim na drugo stran, sam pa je medtem odpustil množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'In ko je odpustil množice, je sam posebej odšel na goro, da moli. In ko je prišel večer, je bil tam sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Toda ladja je bila sedaj na sredi morja, premetavana z valovi, kajti bil je nasproten veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'In ob četrti nočni straži je Jezus šel proti njim, hodeč po morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'In ko so ga učenci zagledali hoditi po morju, so bili prestrašeni, rekoč: »To je duh.« In od strahu so zakričali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Toda Jezus jim je nemudoma spregovoril, rekoč: »Bodite dobre volje, jaz sem, ne bojte se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'In Peter mu je odgovoril ter rekel: »Gospod, če si ti, mi zaukaži po vodi priti k tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'In on je rekel: »Pridi.« In ko je Peter prišel dol iz ladje, da pride k Jezusu, je hodil po vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Toda ko je videl silovitost vetra, je bil prestrašen. In ko se je začel utapljati, je zavpil, rekoč: »Gospod, reši me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'In Jezus je takoj iztegnil svojo roko ter ga prijel in mu rekel: »Oh ti maloveren, zakaj si podvomil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'In ko sta prišla na ladjo, je veter ponehal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Potem so prišli oni, ki so bili na ladji in ga oboževali, rekoč: »Resnično, ti si Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'In ko so se prepeljali, so prišli v deželo Genezaret.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'In ko so ljudje tega kraja dobili spoznanje o njem, so razposlali v vso to pokrajino naokoli in privedli k njemu vse, ki so bili bolni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'in rotili so ga, da bi se lahko samo dotaknili obšiva njegove obleke in prav vsi, ki so se ga dotaknili, so postali popolnoma zdravi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tedaj so k Jezusu prišli pisarji in farizeji, ki so bili iz Jeruzalema, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '»Zakaj tvoji učenci prestopajo izročila starešin? Kajti kadar jedo kruh, si ne umijejo svojih rok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Toda odgovoril jim je in rekel: »Zakaj vi prav tako s svojim izročilom prestopate Božjo zapoved?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Kajti Bog je zapovedal, rekoč: ›Spoštuj svojega očeta in mater‹ in: ›Kdor preklinja očeta ali mater, naj življenje konča s smrtjo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Toda vi pravite: ›Kdorkoli bo rekel svojemu očetu ali svoji materi: ›To je dar, s čimerkoli bi ti mogoče imel korist od mene,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'in ne spoštuje svojega očeta ali svoje matere, bo prost. Tako ste s svojim izročilom naredili Božjo zapoved brez učinka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Vi hinavci, Izaija je dobro prerokoval o vas, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '§ ›Ti ljudje se s svojimi usti bližajo k meni in me spoštujejo s svojimi ustnicami, toda njihovo srce je daleč od mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Toda zaman me obožujejo, učeč nauke človeških zapovedi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'In poklical je množico ter jim rekel: »Poslušajte in razumite:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, '›Ni to, kar gre v usta, [kar] omadežuje človeka, temveč to, kar prihaja iz ust, to omadežuje človeka.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tedaj so prišli njegovi učenci in mu rekli: »Ali veš, da so bili farizeji, potem ko so slišali to govorjenje, užaljeni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Toda odgovoril je in rekel: »Vsaka rastlina, ki je ni vsadil moj nebeški Oče, bo izkoreninjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Pustite jih pri miru. Slepi voditelji slepih so. Če pa slepi vodi slepega, bosta oba padla v jarek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Potem je odgovoril Peter in mu rekel: »Pojasni nam to prispodobo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, '§ Jezus pa je rekel: »Ali ste tudi vi še vedno brez razumevanja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ali še vedno ne razumete, da karkoli vstopi pri ustih, gre v trebuh in je vrženo ven, v zunanje stranišče?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Toda te besede, ki izvirajo iz ust, prihajajo iz srca in te omadežujejo človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Kajti iz srca izvirajo zle misli, umori, zakonolomstva, prešuštva, tatvine, kriva pričevanja, bogokletja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'To so stvari, ki omadežujejo človeka, toda jesti z neumitimi rokami človeka ne omadežuje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Potem je Jezus odšel od tam in odšel v tirske in sidónske kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'In glej, ženska iz Kánaana je prišla iz teh istih krajev ter vpila k njemu, rekoč: »Usmili se me, oh Gospod, ti Davidov Sin. Moja hči je boleče nadlegovana od hudiča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Toda on ji ni odgovoril niti besede. In prišli so njegovi učenci ter ga rotili, rekoč: »Pošlji jo proč, ker vpije za nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Toda odgovoril je in rekel: »Nisem poslan [k nikomur], razen k izgubljenim ovcam Izraelove hiše.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Potem je prišla in ga oboževala, rekoč: »Gospod, pomagaj mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Toda odgovoril je in rekel: »Ni primerno vzeti kruha otrokom in ga vreči psom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Ona pa je rekla: »Res je, Gospod, vendar psi jedo od drobtinic, ki padajo z mize njihovih gospodarjev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tedaj je Jezus odgovoril in ji rekel: »Oh žena, velika je tvoja vera, zgodi naj se ti, kakor hočeš.« In njena hči je bila ozdravljena od točno tiste ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'In Jezus je odšel od tam ter prišel v bližino Galilejskega morja in odšel na goro ter se tam usedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'In k njemu so prišle velike množice, ki so imele s seboj tiste, ki so bili hromi, slepi, nemi, pohabljeni ter mnoge druge in polagali so jih k Jezusovim stopalom in jih je ozdravil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'do take mere, da se je množica čudila, ko so videli nemega spregovoriti, pohabljenega biti zdravega, hromega hoditi in slepega videti. In slavili so Izraelovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Potem je Jezus svoje učence poklical k sebi in rekel: »Sočutje imam do množice, ker že tri dni vztrajajo z menoj in nimajo nič za jesti; in ne bom jih poslal proč tešče, da na poti ne oslabijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'In njegovi učenci so mu rekli: »Od kod naj imamo v divjini tako veliko kruha, za nasičenje tako velike množice?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'In Jezus jim reče: »Koliko hlebov imate?« Rekli so: »Sedem in nekaj majhnih rib.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'In velel je množici, naj séde na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'In vzel je sedem hlebov in ribe ter se zahvalil in jih razlomil ter dal svojim učencem, učenci pa množici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'In vsi so jedli ter bili nasičeni in pobrali so od ostankov obeda, kar je ostalo, sedem polnih košar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'In teh, ki so jedli, je bilo štiri tisoč mož, poleg žensk in otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'In odpustil je množico ter stopil na ladjo in prišel v magadánske kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Tudi farizeji so prišli skupaj s saduceji in ga skušali ter zahtevali, da bi jim pokazal znamenje z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Odgovoril je in jim rekel: »Ko je večer, pravite: ›Lepo vreme bo, kajti nebo je rdeče.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Zjutraj pa: ›Danes bo grdo vreme, kajti nebo je rdeče in mračno.‹ O vi hinavci, lahko razpoznavate obličje neba, toda ne morete razpoznati znamenj časov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Zlobni in zakonolomni rod išče znamenje, pa mu ne bo dano nobeno znamenje, razen znamenja preroka Jona.« In zapustil jih je ter odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Ko so njegovi učenci prišli na drugo stran, so pozabili vzeti kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Potem jim je Jezus rekel: »Pazite in varujte se kvasa farizejev in saducejev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'In med seboj so razpravljali, rekoč: » To je zato, ker nismo vzeli kruha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Ko je Jezus to zaznal, jim je rekel: »Oh vi maloverni, zakaj med seboj razmišljate, ker niste prinesli nobenega kruha?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ali še vedno ne razumete niti se ne spominjate petih hlebov pet tisočim in koliko košar ste pobrali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Niti sedmih hlebov štiri tisočim in koliko košar ste pobrali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Kako to, da ne razumete, da vam tega nisem govoril v zvezi s kruhom, da bi se varovali kvasa farizejev in saducejev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Potem so razumeli, da jim je zaukazal, naj se ne varujejo kruhovega kvasa, temveč nauka farizejev in saducejev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Ko je Jezus prišel v kraje Cezareje Filipove, je vprašal svoje učence, rekoč: »Kdo ljudje pravijo, da jaz, Sin človekov, sem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Rekli so: »Nekateri pravijo, da si Janez Krstnik, nekateri Elija in drugi Jeremija ali eden izmed prerokov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Reče jim: »Toda kdo vi pravite, da sem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'In Simon Peter je odgovoril ter rekel: »Ti si Kristus, Sin živega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'In Jezus je odgovoril ter mu rekel: »Blagoslovljen si, Simon, Jonov sin, kajti meso in kri ti tega nista razodela, temveč moj Oče, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'In jaz ti prav tako pravim: ›Da si ti Peter in na tej skali bom zgradil svojo cerkev in velika vrata pekla ne bodo prevladala proti njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'In dal ti bom ključe nebeškega kraljestva; in karkoli boš zvezal na zemlji, bo zvezano v nebesih; in karkoli boš razvezal na zemlji, bo razvezano v nebesih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, '§ Tedaj je svojim učencem naročil, da naj nobenemu človeku ne povedo, da je bil on Jezus, Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Od tedaj naprej je Jezus svojim učencem začel kazati, da mora oditi v Jeruzalem in od starešin in visokih duhovnikov in pisarjev pretrpeti mnoge stvari in biti umorjen in tretji dan obujen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Potem ga je Peter prijel in ga začel oštevati, rekoč: »To naj bo daleč od tebe, Gospod. To naj se ti ne zgodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Toda on se je obrnil in Petru rekel: »Spravi se za menoj, Satan. V spotiko si mi, kajti ne posvečaš se stvarem, ki so od Boga, temveč tem, ki so od ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tedaj je Jezus rekel svojim učencem: »Če hoče katerikoli človek slediti meni, naj se odpove samemu sebi in vzame svoj križ ter hodi za menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Kajti kdorkoli hoče rešiti svoje življenje, ga bo izgubil, kdorkoli pa bo izgubil svoje življenje zaradi mene, ga bo našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, '§ Kajti kaj človeku koristi, če si bo pridobil ves svet, izgubil pa svojo lastno dušo? Ali kaj bo človek dal v zameno za svojo dušo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Kajti Sin človekov bo prišel v slavi svojega Očeta s svojimi angeli in tedaj bo vsakega človeka nagradil glede na njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Resnično, povem vam: ›Tam bo nekaj tukaj navzočih, ki ne bodo okusili smrti, dokler ne vidijo Sina človekovega prihajati v svojem kraljestvu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'In po šestih dneh Jezus vzame Petra, Jakoba in njegovega brata Janeza ter jih posebej privede na visoko goro');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'in pred njimi je bil preobražen; in njegov obraz je sijal kakor sonce in njegovo oblačilo je bilo belo kakor svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'In glej, prikazala sta se jim Mojzes in Elija, ki sta govorila z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Potem je Peter odgovoril in Jezusu rekel: »Gospod, dobro je za nas, da smo tukaj. Če želiš, naredimo tukaj tri šotore; enega zate, enega za Mojzesa in enega za Elija.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Medtem ko je še govoril, glej, jih je obsenčil svetel oblak, in glej, glas iz oblaka, ki je rekel: »Ta je moj ljubljeni Sin, s katerim sem zelo zadovoljen; njega poslušajte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Ko so učenci to slišali, so padli na svoj obraz in bili boleče prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Prišel je Jezus in se jih dotaknil ter rekel: »Vstanite in ne bojte se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'In ko so povzdignili svoje oči, niso videli nobenega človeka, razen samo Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'In ko so prišli dol z gore, jim je Jezus naročil, rekoč: »Tega videnja ne povejte nikomur, dokler ne bo Sin človekov vstal od mrtvih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'In njegovi učenci so ga vprašali, rekoč: »Zakaj potem pisarji pravijo, da mora prej priti Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jezus jim je odgovoril in rekel: »Elija bo resnično prišel prej in obnovil vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Toda povem vam: ›Da je Elija že prišel, pa ga niso spoznali, temveč so mu storili, karkoli so želeli.‹ Tako bo tudi Sin človekov trpel od njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tedaj so učenci razumeli, da jim je govoril o Janezu Krstniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'In ko so prišli k množici, je prišel k njemu nek človek, ki je pokleknil navzdol k njemu ter rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '»Gospod, usmili se mojega sina, kajti blazen je in boleče nadlegovan, kajti pogosto pada v ogenj in često v vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'In pripeljal sem ga k tvojim učencem, pa ga niso mogli ozdraviti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Potem je Jezus odgovoril in rekel: »Oh neveren in sprevržen rod, kako dolgo bom še z vami? Doklej vas bom še prenašal? Privedite mi ga sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'In Jezus je oštel hudiča in ta je odšel iz njega; in otrok je bil ozdravljen od točno tiste ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Tedaj so prišli učenci ločeno k Jezusu in rekli: »Zakaj ga mi nismo mogli izgnati iz njega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, '§ Jezus pa jim je rekel: »Zaradi vaše nevere, kajti resnično, povem vam: ›Če imate vero kakor zrno gorčičnega semena, boste tej gori rekli: ›Odstrani se od tod na tamkajšnji kraj;‹‹ in bo premeščena in nič vam ne bo nemogoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '§ Vendar ta vrsta ne gre ven, razen z molitvijo in postom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'In medtem ko so prebivali v Galileji, jim je Jezus rekel: »Sin človekov bo izdan v roke ljudem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'in ubili ga bodo in tretji dan bo znova obujen.« In bili so silno žalostni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Ko pa so prišli v Kafarnáum, so ti, ki so prejeli davčni denar, prišli k Petru in rekli: »Ali vaš učitelj ne plačuje davka?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Rekel je: »Da.« Ko pa je prišel v hišo, ga je Jezus prehitel, rekoč: »Kaj misliš Simon? Od koga zemeljski kralji jemljejo carino ali davek? Od svojih lastnih otrok ali od tujcev?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Peter mu reče: »Od tujcev.« Jezus mu reče: »Potem so otroci prosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Vendar pa, da jih ne bi pohujšala, pojdi k morju, vrzi trnek in dvigni ribo, ki prva pride gor. In ko ji boš odprl usta, boš našel kos denarja. Vzemi ga ter jim ga daj zame in zase.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Ob istem času so prišli k Jezusu učenci, rekoč: »Kdo je največji v nebeškem kraljestvu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'In Jezus je k sebi poklical majhnega otroka in ga postavil v sredo mednje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'ter rekel: »Resnično, povem vam: ›Razen, če se ne spreobrnete in ne postanete kakor majhni otroci, ne boste vstopili v nebeško kraljestvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kdorkoli bo torej samega sebe ponižal kakor ta majhen otrok, ta je največji v nebeškem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'In kdorkoli bo sprejel enega takšnega majhnega otroka v mojem imenu, sprejema mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Toda kdorkoli bo pohujšal enega od teh malčkov, ki verujejo vame, bi bilo bolje zanj, da bi bil mlinski kamen obešen okoli njegovega vratu in da bi bil potopljen v globino morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Gorje svetu zaradi prestopkov! Kajti nujno se mora zgoditi, da prestopki pridejo, toda gorje tistemu človeku, po katerem prestopki prihajajo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Zatorej, če te tvoja roka ali tvoje stopalo pohujšuje, ju odsekaj proč in ju vrzi od sebe. Bolje je zate, da v življenje vstopiš šepav ali pohabljen, raje kakor imeti dve roki ali dve stopali in biti vržen v večni ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'In če te tvoje oko pohujšuje, ga iztakni in ga vrzi od sebe. Bolje je zate, da vstopiš v življenje z enim očesom, raje kakor imeti dve očesi in biti vržen v peklenski ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Pazite, da ne prezirate niti enega od teh malčkov, kajti povem vam: ›Da njihovi angeli v nebesih vedno zrejo obraz mojega Očeta, ki je v nebesih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Kajti Sin človekov je prišel rešit to, kar je bilo izgubljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Kaj mislite? Če ima človek sto ovac in bi ena od njih zašla ali ne bo pustil devetindevetdesetih in šel v gore in iskal tiste, ki je zašla?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'In če se zgodi, da jo najde, resnično, povem vam, se bolj veseli te ovce kakor devetindevetdesetih, ki niso zašle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Točno tako ni volja vašega Očeta, ki je v nebesih, da bi propadel eden izmed teh malčkov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Poleg tega, če se bo tvoj brat prekršil zoper tebe, pojdi in mu na samem povej njegovo krivdo med seboj in njim. Če te bo poslušal, si pridobil svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Toda če te ne bo poslušal, potem vzemi s seboj dodatno še enega ali dva, da je vsaka beseda lahko potrjena po ustih dveh ali treh prič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Če pa jih bo zanemarjal poslušati, povej to cerkvi. Toda če zanemarja poslušati cerkev, naj ti bo kakor pogan in davkar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Resnično, povem vam: ›Karkoli boste zvezali na zemlji, bo zvezano v nebesih, in karkoli boste razvezali na zemlji, bo razvezano v nebesih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Ponovno vam pravim: ›Da če se bosta dva izmed vas na zemlji strinjala glede katerekoli stvari, za katero bosta prosila, bo to storjeno zanju od mojega Očeta, ki je v nebesih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Kajti kjer sta dva ali trije zbrani skupaj v mojem imenu, tam sem jaz v sredi med njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tedaj je prišel k njemu Peter in rekel: »Gospod, kako pogosto lahko moj brat greši zoper mene in mu jaz odpustim? Do sedemkrat?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jezus mu reče: »Ne pravim ti: ›Do sedemkrat,‹ temveč: ›do sedemdesetkrat sedemkrat.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Zato je nebeško kraljestvo podobno nekemu kralju, ki je hotel narediti obračun s svojimi služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'In ko je začel z obračunom, so k njemu privedli nekoga, ki mu je bil dolžan deset tisoč talentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Toda ker ni mogel toliko odplačati, mu je njegov gospodar ukazal, naj bo prodan on in njegova žena in otroci ter vse, kar je imel in se pripravi plačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Služabnik je torej padel dol in ga oboževal, rekoč: ›Gospod, imej potrpljenje z menoj in vse ti bom plačal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Potem je bil gospodar tega služabnika prevzet s sočutjem in ga izpustil ter mu odpustil dolg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Toda ta isti služabnik je odšel ven in našel enega izmed svojih soslužabnikov, ki mu je bil dolžan sto denarjev in nanj položil roki ter [ga] prijel za vrat, rekoč: ›Plačaj mi to, kar dolguješ.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'In njegov soslužabnik je padel dol ob njegovih stopalih in ga rotil, rekoč: ›Imej potrpljenje z menoj in vse ti bom plačal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Ta pa ni hotel, temveč je šel in ga vrgel v ječo, dokler ne bi odplačal dolga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Ko so torej njegovi soslužabniki videli, kaj se je zgodilo, so bili zelo žalostni in so prišli ter svojemu gospodarju povedali vse, kar se je zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tedaj mu je njegov gospodar, potem ko ga je poklical, rekel: ›Oh ti zlobni služabnik, ker si me prosil, sem ti ves ta dolg odpustil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ali naj ne bi tudi ti prav tako imel sočutje do svojega soslužabnika, prav tako kakor sem jaz imel usmiljenje do tebe?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'In njegov gospodar je bil ogorčen in ga izročil mučiteljem, dokler ne bi odplačal vsega tega, kar mu je bil dolžan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Prav tako bo moj nebeški Oče storil tudi vam, če iz svojih src ne odpustite vsak svojemu bratu njihove prekrške.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'In pripetilo se je, ko je Jezus zaključil te govore, da je odšel iz Galileje in prišel v judejske kraje onstran Jordana;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'in sledile so mu velike množice in jih je tam ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Prav tako so k njemu prišli farizeji, ki so ga skušali in mu rekli: »Ali je za moža zakonito, da zaradi kateregakoli vzroka odslovi svojo ženo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, '§ In odgovoril je ter jim rekel: »Mar niste brali, da je tisti, ki ju je ustvaril na začetku, ustvaril moškega in žensko');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'ter rekel: ›Zaradi tega razloga bo mož zapustil očeta in mater in se bo trdno pridružil k svoji ženi, in oba skupaj bosta eno meso?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Zatorej nista več dva, temveč eno meso. Kar je torej Bog združil skupaj, naj človek ne daje narazen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Rekli so mu: »Zakaj je potem Mojzes zapovedal dati pismo o ločitvi in jo odsloviti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Reče jim: »Mojzes vam je zaradi trdote vaših src dovolil odsloviti vaše žene, toda od začetka to ni bilo tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'In pravim vam: ›Kdorkoli bo odslovil svojo ženo, razen če je to zaradi prešuštva in poročil drugo, zagreši zakonolomstvo; in kdorkoli poroči tisto, ki je odslovljena, zagreši zakonolomstvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Njegovi učenci so mu rekli: »Če je zadeva moža z njegovo ženo takšna, se ni dobro poročiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Toda rekel jim je: »Vsi ljudje ne morejo sprejeti tega govorjenja, razen teh, ki jim je to dano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Kajti nekaj evnuhov je, ki so bili takšni rojeni iz maternice svoje matere, in nekaj evnuhov je, ki so jih ljudje naredili za evnuhe, in so evnuhi, ki so sami sebe naredili evnuhe zavoljo nebeškega kraljestva. Kdor je zmožen to sprejeti, naj to sprejme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tedaj so k njemu privedli majhne otroke, da bi nanje položil svoji roki in molil, učenci pa so jih ošteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Toda Jezus je rekel: »Dovolite majhnim otrokom in ne prepovejte jim priti k meni, kajti takšnih je nebeško kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'In nanje je položil svoji roki in odšel od tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'In glej, nekdo je prišel ter mu rekel: »Dobri Učitelj, katero dobro stvar naj storim, da bom lahko imel večno življenje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Rekel mu je: »Zakaj me imenuješ dober? Nihče ni dober razen enega, to je Boga; toda če želiš vstopiti v življenje, se drži zapovedi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Reče mu: »Katerih?« Jezus je odgovoril: »Ne stôri umora. Ne zagreši zakonolomstva. Ne kradi. Ne pričaj po krivem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Spoštuj svojega očeta in svojo mater. In ljubi svojega bližnjega kakor samega sebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Mladenič mu reče: »Vseh teh stvari sem se držal od svoje mladosti dalje. Kaj mi še manjka?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jezus mu je rekel: »Če želiš biti popoln, pojdi in prodaj, kar imaš ter daj revnim in imel boš zaklad v nebesih, in pridi ter mi sledi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Toda ko je mladenič slišal to govorjenje, je žalosten odšel proč, kajti imel je veliko posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Potem je Jezus rekel svojim učencem: »Resnično, povem vam: ›Da bo bogataš komajda vstopil v nebeško kraljestvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'In ponovno vam pravim: ›Lažje je za kamelo iti skozi šivankino oko, kakor za bogataša vstopit v Božje kraljestvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Ko so njegovi učenci to slišali, so bili silno osupli, rekoč: »Kdo je potem lahko rešen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Toda Jezus jih je pogledal in jim rekel: »Pri ljudeh je to nemogoče, toda z Bogom so vse stvari mogoče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tedaj je Peter odgovoril in mu rekel: »Glej, vse smo zapustili in ti sledili. Kaj bomo torej prejeli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jezus jim je rekel: »Resnično, povem vam: ›Da boste vi, ki ste mi sledili, v obnovi, ko se bo Sin človekov usedel na prestol svoje slave, tudi vi sedeli na dvanajstih prestolih in sodili dvanajstere Izraelove rodove.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, '§ In vsak, kdor je zaradi mojega imena zapustil hiše ali brate ali sestre ali očeta ali mater ali ženo ali otroke ali zemljišča, bo prejel stokratno in bo podedoval večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Toda mnogi, ki so prvi, bodo zadnji; in zadnji bodo prvi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '»Kajti nebeško kraljestvo je podobno človeku, ki je hišni gospodar in je zgodaj zjutraj odšel ven, da najame delavce v svoj vinograd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'In ko se je z delavci dogovoril za en kovanec na dan, jih je poslal v svoj vinograd.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'In odšel je ven okoli tretje ure in videl druge stati brez dela na trgu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'in jim rekel: ›Pojdite tudi vi v vinograd in karkoli je prav, vam bom dal.‹ In odšli so svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Ponovno je odšel ven okoli šeste ure in devete ure in storil prav tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'In okoli enajste ure je odšel ven in našel druge stati brez dela in jim reče: ›Zakaj stojite tukaj ves dan brez dela?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, '§ Rekli so mu: ›Ker nas nihče ni najel.‹ Reče jim: ›Pojdite tudi vi v vinograd; in karkoli je prav, to boste prejeli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Ko je torej prišel večer, gospodar vinograda reče svojemu oskrbniku: ›Pokliči delavce in jim daj njihovo plačilo ter začni od zadnjih do prvih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'In ko so prišli tisti, ki so bili najeti okoli enajste ure, so prejeli vsak [po] en kovanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Toda ko so prišli prvi, so domnevali, da bi morali prejeti več; pa so prav tako prejeli vsak [po] en kovanec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'In ko so to prejeli, so godrnjali zoper hišnega očeta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'rekoč: ›Ti zadnji so delali samo eno uro in si jih naredil enake nam, ki smo prenašali breme in vročino dneva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Toda enemu izmed njih je odgovoril in rekel: ›Prijatelj, ne delam ti nobene krivice; ali se nisi z menoj dogovoril za en kovanec?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Vzemi to, kar je tvoje in pojdi svojo pot. Temu zadnjemu bom dal enako kakor tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ali mi ni dovoljeno, da s svojo lastnino storim kar hočem? Ali je tvoje oko hudobno, ker sem jaz dober?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, '§ Tako bodo zadnji prvi in prvi zadnji, kajti veliko je poklicanih, toda malo izbranih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'In ko je šel gor v Jeruzalem, je Jezus na poti vzel dvanajst učencev na stran ter jim rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '»Glejte, mi gremo gor v Jeruzalem in Sin človekov bo izdan visokim duhovnikom in pisarjem in obsodili ga bodo na smrt');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'in izročili ga bodo poganom v zasmeh in bičanje in da ga križajo in tretji dan bo ponovno vstal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tedaj je prišla k njemu mati Zebedejevih otrok s svojima sinovoma, ga oboževala in od njega želela neko stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'In rekel ji je: »Kaj želiš?« Ona mu reče: »Zagotovi, da bosta lahko ta dva moja sinova, v tvojem kraljestvu, sedela eden na tvoji desni roki, drugi pa na levi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, '§ Toda Jezus je odgovoril in rekel: »Ne veste, kaj prosite. Ali zmoreta piti iz čaše, iz katere bom jaz pil in biti krščena s krstom, s katerim sem jaz krščen?« Rekla sta mu: »Midva zmoreva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, '§ In jima reče: »Zares bosta pila iz moje čaše in krščena bosta s krstom, s katerim sem jaz krščen. Toda sedeti na moji desni roki in na moji levi, ni moje da dam, temveč bo dano tem, za katere je to pripravljeno od mojega Očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Ko so deseteri to slišali, so bili prevzeti z ogorčenjem zoper ta dva brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Toda Jezus jih je poklical k sebi in rekel: »Vi veste, da princi poganov izvajajo gospostvo nad njimi in oni, ki so veliki, izvajajo oblast nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Toda med vami naj ne bo tako, temveč kdorkoli hoče biti med vami velik, naj bo vaš sluga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'in kdorkoli hoče biti med vami vodja, naj bo vaš služabnik;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'prav tako tudi Sin človekov ni prišel, da bi mu služili, temveč da služi in da svoje življenje dá v odkupnino za mnoge.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'In ko so odšli iz Jerihe, mu je sledila velika množica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'In glej, dva slepa človeka sta sedela ob poti. Ko sta zaslišala, da je šel mimo Jezus, sta zakričala, rekoč: »Usmili se naju, oh Gospod, ti Davidov Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Množica pa ju je oštela, ker bi morala molčati. Toda onadva sta še bolj vpila, rekoč: »Usmili se naju, oh Gospod, ti Davidov Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'In Jezus se je ustavil in ju poklical ter rekel: »Kaj želita, da vama storim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Rekla sta mu: »Gospod, da bi se najine oči lahko odprle.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jezus je imel torej do njiju sočutje in se dotaknil njunih oči. In njune oči so takoj prejele vid in sta mu sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'In ko so se bližali Jeruzalemu in so prišli do Bétfage pri Oljski gori, je Jezus torej poslal dva učenca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'rekoč jima: »Pojdita v vas tam pred vama in nemudoma bosta našla privezano oslico in žrebe z njo. Odvežita ju in ju privedita k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'In če vama bo katerikoli človek karkoli rekel, mu bosta rekla: ›Gospod ju potrebuje;‹ in nemudoma ju bo poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Vse to je bilo storjeno, da bi se lahko izpolnilo, kar je bilo rečeno po preroku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '»Povejte sionski hčeri: ›Glej, tvoj Kralj prihaja k tebi, krotak in sedeč na oslici in žrebetu, osličjem žrebetu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'In učenca sta odšla ter storila, kakor jima je Jezus zapovedal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'in pripeljala sta oslico ter žrebe in nanju položila svoja oblačila in posadili so ga nanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Zelo velika množica je svoje obleke razgrnila na pot; drugi pa so odsekali veje iz dreves in jih nastlali po poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'In množice, ki so šle spredaj in te, ki so sledile, so vzklikale, rekoč: »Hozana Davidovemu Sinu: ›Blagoslovljen je, kdor prihaja v Gospodovem imenu. Hozana na višavah.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'In ko je prišel v Jeruzalem, je bilo vse mesto razdraženo, govoreč: »Kdo je to?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Množica je rekla: »To je Jezus, prerok iz Nazareta v Galileji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'In Jezus je odšel v Božji tempelj in izgnal vse tiste, ki so v templju prodajali in kupovali in prevrnil mize menjalcem denarja in stole tem, ki so prodajali golobice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'ter jim rekel: »Pisano je: ›Moja hiša naj se imenuje hiša molitve,‹ toda vi ste jo naredili za brlog razbojnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'V templju so prišli k njemu slepi in hromi in jih je ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Ko so visoki duhovniki in pisarji videli čudovita dela, ki jih je storil in otroke, ki so v templju vzklikali ter govorili: »Hozana Davidovemu Sinu,« so bili hudo nezadovoljni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'in so mu rekli: »Slišiš, kaj tile govorijo?« Jezus pa jim reče: »Seveda. Mar niste nikoli brali: ›Iz ust otročičev in dojenčkov si izpopolnil hvalo?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'In zapustil jih je ter odšel iz mesta v Betanijo in tam prenočil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Torej zjutraj, ko se je vrnil v mesto, je postal lačen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'In ko je na poti zagledal figovo drevo, je prišel k njemu, pa na njem ni našel nič, razen listja samega in mu rekel: »Naj odslej na tebi nikoli več ne zraste noben sad.« In figovo drevo je takoj ovenelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Ko so učenci to videli, so se čudili, rekoč: »Kako hitro je figovo drevo ovenelo!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jezus jim je odgovoril in rekel: »Resnično, povem vam: ›Če imate vero in ne dvomite, ne boste delali samo tega, kar je bilo storjeno figovemu drevesu, temveč tudi, če boste rekli tej gori: ›Bodi odstranjena in vržena v morje,‹ se bo to zgodilo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'In vse stvari, katerekoli boste verujoč prosili v molitvi, boste prejeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'In ko je prišel v tempelj, so k njemu, medtem ko je učil, prišli visoki duhovniki in starešine izmed ljudi ter rekli: »S kakšno oblastjo delaš te stvari? In kdo ti je dal to oblast?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jezus je odgovoril in jim rekel: »Tudi jaz vas bom vprašal eno besedo in če mi jo poveste, vam bom tudi jaz povedal, s kakšno oblastjo delam te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Janezov krst, od kod je bil? Iz nebes ali od ljudi?« In med seboj so razpravljali, rekoč: »Če bomo rekli: ›Iz nebes;‹ nam bo rekel: ›Zakaj mu potem niste verjeli?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Toda če bomo rekli: ›Od ljudi,‹ se bojimo množice, kajti Janeza so vsi imeli za preroka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'In odgovorili so Jezusu ter rekli: »Ne moremo povedati.« In rekel jim je: »Tudi jaz vam ne povem, s kakšno oblastjo delam te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Toda kaj vi mislite? Neki človek je imel dva sinova. In prišel je k prvemu ter rekel: ›Sin, pojdi danes delat v moj vinograd.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Ta je odgovoril in rekel: ›Nočem,‹ toda kasneje se je pokesal in odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'In prišel je k drugemu ter rekel enako. Ta je odgovoril in rekel: › Grem, gospod,‹ pa ni odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kateri izmed njiju dveh je izvršil voljo svojega očeta?« Povedo mu: »Prvi.« Jezus jim reče: »Resnično, povem vam: ›Da pojdejo davkarji in vlačuge pred vami v Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Kajti Janez je prišel k vam po poti pravičnosti, pa mu niste verjeli, toda davkarji in vlačuge so mu verjeli. Vi pa, ko ste to videli, se potem niste pokesali, da bi mu lahko verjeli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Poslušajte še eno prispodobo: ›Bil je nek hišni gospodar, ki je zasadil vinograd in ga ogradil naokoli in v njem izkopal vinsko stiskalnico in zgradil stolp in ga prepustil poljedelcem ter odšel v daljno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'In ko se je približal čas sadu, je k poljedelcem poslal svoje služabnike, da bi lahko prejeli njegove sadove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Poljedelci pa so njegove služabnike prijeli in enega pretepli in drugega ubili in še enega kamnali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Ponovno pošlje druge služabnike, več kakor prvič, pa so jim storili enako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Toda zadnjega od vseh je poslal k njim svojega sina, rekoč: ›Mojega sina bodo spoštovali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Toda ko so poljedelci zagledali sina, so si med seboj rekli: ›Ta je dedič. Pridite, ubijmo ga in se polastimo njegove dediščine.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'In zgrabili so ga in ga vrgli iz vinograda in ga usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Kadar torej pride gospodar vinograda, kaj bo storil tem poljedelcem?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Rekli so mu: »Te zlobneže bo bedno uničil, svoj vinograd pa bo prepustil drugim poljedelcem, ki mu bodo povrnili sadove ob svojih pravih obdobjih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jezus jim reče: »Mar niste nikoli brali v pismih: ›Kamen, ki so ga graditelji zavrgli, ta isti je postal glava vogalu. To je Gospodovo delo in to je čudovito v naših očeh?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Zatorej vam pravim: ›Božje kraljestvo vam bo vzeto in dano narodu, ki prinaša njegove sadove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'In kdorkoli bo padel na ta kamen, bo razbit. Toda na kogarkoli bo ta padel, tega bo zmlel v prah.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'In ko so visoki duhovniki in farizeji slišali njegove prispodobe, so zaznali, da je govoril o njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Toda ko so si prizadevali položiti roke nanj, so se zbali množice, ker so ga imeli za preroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Jezus pa je odgovoril in jim ponovno govoril v prispodobah ter rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '»Nebeško kraljestvo je podobno nekemu kralju, ki je pripravil svatbo svojemu sinu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'in poslal je svoje služabnike, da pokličejo na poroko te, ki so bili povabljeni, pa oni niso hoteli priti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Ponovno pošlje druge služabnike, rekoč: ›Povejte tem, ki so povabljeni: ›Glejte, pripravil sem svojo večerjo. Moji voli in moji pitanci so zaklani in vse stvari so pripravljene. Pridite na svatbo.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Toda to so jemali na lahko in odšli [po] svojih poteh, en k svoji kmetiji, drugi k svojemu trgovanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'preostali pa so prijeli njegove služabnike in [z njimi] hudobno ravnali ter jih usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Toda ko je kralj slišal o tem, je bil ogorčen. In poslal je svoje vojske in uničil te morilce ter požgal njihovo mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Potem reče svojim služabnikom: ›Poroka je pripravljena, toda tisti, ki so bili povabljeni, niso bili vredni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Pojdite torej na glavne ceste in toliko, kolikor jih najdete, jih povabite na svatbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Tako so ti služabniki odšli ven na glavne ceste in zbrali skupaj vse, tako veliko, kot so jih našli, tako hudobne kakor dobre, in poroka je bila napolnjena z gosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'In ko je kralj vstopil, da vidi goste, je zagledal tam človeka, ki ni imel nadete poročne obleke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'in mu reče: ›Prijatelj, kako si prišel sèm, ne da bi imel poročno obleko?‹ Ta pa je bil brez besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tedaj je kralj rekel služabnikom: ›Zvežite mu roko in stopalo ter ga odvedite proč in ga vrzite v zunanjo temo. Tam bo jokanje in škripanje z zobmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Kajti mnogo je poklicanih, toda malo je izbranih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tedaj so farizeji odšli in se posvetovali, kako bi ga lahko ujeli v njegovem govorjenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'In k njemu so poslali svoje učence s herodovci, rekoč: »›Učitelj, vemo, da si pošten in v resnici učiš Božjo pot niti se ne oziraš na nobenega človeka, kajti ne oziraš se na zunanjost ljudi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Povej nam torej: ›Kaj misliš? Ali je zakonito dajati cesarju davek ali ne?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Toda Jezus je zaznal njihovo zlobnost in rekel: »Zakaj me skušate, vi hinavci?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Pokažite mi davčni denar.« In prinesli so mu denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'In reče jim: »Čigava sta ta podoba in napis?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Rečejo mu: »Cesarjeva.« Tedaj jim reče: »Povrnite torej cesarju stvari, ki so cesarjeve, in Bogu stvari, ki so Božje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Ko so slišali te besede, so se čudili in ga pustili ter odšli svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Isti dan so prišli k njemu saduceji, ki pravijo, da ni vstajenja in ga vprašali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'rekoč: »Učitelj, Mojzes je rekel: ›Če mož umre brez otrok, naj njegov brat poroči njegovo ženo in svojemu bratu obudi seme.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Torej z nami je bilo sedem bratov in ko je prvi poročil ženo, je umrl in ker ni imel otrok, je svojo ženo zapustil svojemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Podobno tudi drugi in tretji, do sedmega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'In zadnja od vseh je umrla tudi ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Čigava žena, od teh sedmih, bo torej ob vstajenju? Kajti vsi so jo imeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jezus jim je odgovoril in rekel: »Motite se, ker ne poznate ne pisem niti ne Božje moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Kajti ob vstajenju se niti ne poročajo niti niso dane v zakon, temveč so kakor Božji angeli v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Toda kar se tiče vstajenja mrtvih, kaj niste brali tega, kar vam je bilo rečeno od Boga, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '›Jaz sem Bog Abrahamov in Bog Izakov in Bog Jakobov‹? Bog ni Bog mrtvih, temveč živih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'In ko je množica to slišala, je bila osupla nad tem naukom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Toda ko so farizeji slišali, da je utišal saduceje, so se zbrali skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Potem mu je eden izmed njih, ki je bil izvedenec v postavi, zastavil vprašanje, ter ga skušal in rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '»Učitelj, katera je največja zapoved v postavi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, '§ Jezus mu je rekel: »›Ljubil boš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo in z vsem svojim mišljenjem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'To je prva in velika zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Druga pa ji je podobna: ›Svojega bližnjega boš ljubil kakor samega sebe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Na teh dveh zapovedih visita vsa postava in preroki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Medtem ko so bili farizeji zbrani skupaj, jih je Jezus vprašal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'rekoč: »Kaj mislite o Kristusu? Čigav sin je?« Rečejo mu: ›Davidov Sin.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Reče jim: »Kako mu torej David v duhu reče Gospod, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '› Gospod je rekel mojemu Gospodu: ›Sédi na mojo desnico, dokler ne storim tvojih sovražnikov za tvojo pručko?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Če ga torej David imenuje Gospod, kako je njegov sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'In noben človek mu ni bil zmožen odgovoriti besede niti se mu noben človek od tega dne dalje ni drznil zastaviti še več vprašanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tedaj je Jezus spregovoril množici in svojim učencem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'rekoč: »Pisarji in farizeji sedijo na Mojzesovem stolu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Torej vse, karkoli vam ukažejo, obeležujte, to obeležujte in storite; toda ne delajte po njihovih delih, kajti oni govorijo, pa ne delajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Kajti vežejo težka bremena in bridka za prenašanje in jih polagajo ljudem na ramena, toda [sami] jih niti z enim izmed svojih prstov nočejo premakniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Toda vsa svoja dela počnejo zato, da bi jih ljudje videli. Širijo svoje molitvene jermene in povečujejo robove svojih oblek');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'in radi imajo najpomembnejše prostore na zabavah ter vodilne sedeže v sinagogah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'in pozdrave na trgih ter da bi jih ljudje klicali: ›Rabi, Rabi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, '§ Toda ne dajte se imenovati Rabi, kajti eden je vaš Učitelj, celó Kristus, vi vsi pa ste bratje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'In na zemlji nobenega moža ne kličite vaš oče, kajti eden je vaš Oče, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Niti se ne dajte imenovati učitelji, kajti eden je vaš Učitelj, celó Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Temveč kdor je med vami največji, naj bo vaš služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'In kdorkoli se bo poviševal, bo ponižan; in kdor bo sebe ponižal, bo povišan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Toda gorje vam, pisarji in farizeji, hinavci! Kajti nebeško kraljestvo ste zaprli pred ljudmi, kajti sami ne greste noter niti tem, ki vstopajo, ne dovolite, da bi šli noter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '§ Gorje vam, pisarji in farizeji, hinavci! Kajti vdovam goltate hiše in za pretvezo opravljate dolgo molitev; zatorej boste prejeli večjo obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Gorje vam, pisarji in farizeji, hinavci! Kajti obidete morje in zemljo, da naredite enega spreobrnjenca in ko je narejen, ga naredite dvakrat bolj otroka pekla, kakor ste sami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Gorje vam, vi slepi vodniki, ki pravite: ›Kdorkoli bo prisegel pri templju, ni to nič; toda kdorkoli bo prisegel pri tempeljskem zlatu, je dolžnik!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Vi bedaki in slepci. Kajti kaj je večje, zlato ali tempelj, ki posvečuje zlato?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, '§ In: ›Kdorkoli bo prisegel pri oltarju, ni to nič; toda kdorkoli prisega pri daru, ki je na njem, je kriv.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, '§ Vi bedaki in slepci. Kajti kaj je večje, dar ali oltar, ki posvečuje dar?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Kdorkoli bo torej prisegel pri oltarju, prisega pri njem in pri vseh stvareh na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'In kdorkoli bo prisegel pri templju, prisega pri njem in pri tistem, ki prebiva v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'In kdor bo prisegel pri nebesih, prisega pri Božjem prestolu in pri tistem, ki sedi na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, '§ Gorje vam, pisarji in farizeji, hinavci! Kajti plačujete desetino od mete in janeža in kumine, zanemarili pa ste pomembnejše zadeve iz postave, sodbo, usmiljenje in vero. Te bi morali storiti in ne pustiti drugih nenarejenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Vi slepi vodniki, ki precejate komarja in požirate kamelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Gorje vam, pisarji in farizeji, hinavci! Ker naredite zunanjost čaše in pladnja čisto, toda znotraj ste polni izsiljevanja in izgreda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Ti slepi farizej, očisti najprej to, kar je znotraj čaše in pladnja, da bo tudi njuna zunanjost lahko čista.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Gorje vam, pisarji in farizeji, hinavci! Kajti podobni ste pobeljenim mavzolejem, ki so na zunaj videti zares krasni, toda znotraj so polni kosti mrtvih ljudi in vse nečistosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Točno tako se tudi vi navzven kažete ljudem pravične, toda znotraj ste polni hinavščine in krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Gorje vam, pisarji in farizeji, hinavci! Kajti prerokom gradite grobnice in okrašujete mavzoleje pravičnih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'in pravite: ›Če bi bili mi v dneh svojih očetov, ne bi bili z njimi soudeleženi pri prelivanju krvi prerokov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Zatorej ste priče vam samim, da ste otroci teh, ki so morili preroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Napolnite torej mero svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Vi kače, vi gadji rod, kako lahko pobegnete obsodbi na pekel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Zatorej glejte, k vam pošiljam preroke in modre može ter pisarje. In nekatere izmed njih boste ubili in križali; in nekatere izmed njih boste bičali v svojih sinagogah in jih preganjali od mesta do mesta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'da lahko pride nad vas vsa pravična kri, prelita na zemlji, od krvi pravičnega Abela, do krvi Zaharija, Berehjájevega sina, ki ste ga umorili med templjem in oltarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Resnično, povem vam: ›Vse te stvari bodo prišle nad ta rod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Oh Jeruzalem, Jeruzalem, ti, ki ubijaš preroke in kamnaš tiste, ki so poslani k tebi, kako pogosto sem hotel zbrati skupaj tvoje otroke, prav tako kakor koklja zbira svoje piščance pod svoje peruti, pa niste hoteli!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, '§ Glejte, vaša hiša je zapuščena, prepuščena vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Kajti povem vam: ›Odslej me ne boste več videli, dokler ne boste rekli: ›Blagoslovljen je, kdor prihaja v Gospodovem imenu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'In Jezus je šel ven in odšel od templja, in njegovi učenci so prišli k njemu, da mu pokažejo tempeljske stavbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, '§ Jezus jim je rekel: »Ali ne vidite vseh teh stvari? Resnično, jaz vam povem: ›Tukaj ne bo ostal en kamen na drugem, ki ne bo zrušen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'In ko je sedèl na Oljski gori, so k njemu zaupno prišli učenci, rekoč: »Povej nam, kdaj bodo te stvari? In kakšno bo znamenje tvojega prihoda in konca sveta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'In Jezus jim je odgovoril ter rekel: »Pazite, da vas nihče ne prevara.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Kajti mnogo jih bo prišlo v mojem imenu, rekoč: ›Jaz sem Kristus,‹ in bodo mnoge prevarali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'In slišali boste o vojnah in govorice o vojnah; glejte, da ne boste zaskrbljeni, kajti vse te stvari se morajo pripetiti, toda ni še konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, '§ Kajti narod se bo dvignil zoper narod in kraljestvo zoper kraljestvo in lakote, kužne bolezni in potresi bodo na raznih krajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Vse to so začetki bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Takrat vas bodo izročali, da boste trpeli in vas ubijali, in vsi narodi vas bodo sovražili zaradi mojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'In tedaj se bodo mnogi pohujšali in izdajali bodo drug drugega in drug drugega bodo sovražili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'In mnogo lažnih prerokov bo vstalo in bodo mnoge prevarali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'In ker bo krivičnost obilna, se bo ljubezen pri mnogih ohladila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Toda kdor bo vztrajal do konca, ta isti, bo rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'In ta evangelij kraljestva bo oznanjen po vsem svetu v pričevanje vsem narodom, in tedaj bo prišel konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Kadar boste torej videli ogabnost opustošenja, o kateri govori prerok Daniel, stati na svetem prostoru (kdorkoli bere, naj razume),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'takrat naj tisti, ki bodo v Judeji, bežijo v gore.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Tisti, ki je na hišni strehi, naj ne pride dol, da bi iz svoje hiše karkoli vzel,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'niti naj se tisti, ki je na njivi, ne vrača nazaj, da vzame svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'In gorje tem, ki so z otrokom in tem, ki v tistih dneh dojijo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Toda molíte, da vaš pobeg ne bo pozimi niti ne na šabatni dan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'kajti takrat bo velika stiska, takšna, kakršne ni bilo od začetka sveta do tega časa niti je nikoli več ne bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'In razen če ti dnevi ne bi bili skrajšani, ne bi bilo rešeno nobeno meso; toda zaradi izvoljenih bodo ti dnevi skrajšani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Če vam bo takrat katerikoli človek rekel: ›Glejte! Tukaj je Kristus ali tam; tega ne verjemite.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Kajti vstali bodo lažni Kristusi in lažni preroki in prikazovali bodo velika znamenja in čudeže; do take mere, da bodo, če bi bilo mogoče, prevarali tudi izvoljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Glejte, vnaprej sem vam povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Zatorej, če vam bodo rekli: ›Glejte, v puščavi je;‹ ne pojdite tja: ›Glejte, v skrivnih sobah je;‹ tega ne verjemite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Kajti kakor bliskanje prihaja od vzhoda in sveti celó do zahoda, takšen bo tudi prihod Sina človekovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Kajti kjerkoli je truplo, tam bodo orli zbrani skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Takoj po stiski tistih dni bo sonce otemnelo in luna ne bo dajala svoje svetlobe in zvezde bodo padale iz neba in moči neba se bodo tresle,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, '§ in tedaj se bo na nebu prikazalo znamenje Sina človekovega, in tedaj bodo žalovali vsi zemeljski rodovi in videli bodo Sina človekovega prihajati na oblakih neba z močjo in veliko slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'In z močnim donenjem trobente bo poslal svoje angele in zbrali bodo skupaj njegove izvoljene iz štirih vetrov, od enega konca neba do drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Od figovega drevesa se torej naučite prispodobo: ›Kadar je njegova mladika še nežna in poganja liste, veste, da je poletje blizu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Tako tudi vi, ko boste videli vse te stvari, védite, da je to blizu, celó pri vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Resnično, povem vam: ›Ta rod ne bo prešel, dokler vse te stvari ne bodo izpolnjene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Nebo in zemlja bosta prešla, toda moje besede ne bodo prešle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, '§ Toda o tem dnevu in uri ne ve noben človek, ne, niti nebeški angeli ne, temveč samo moj Oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Toda kakršni so bili Noetovi dnevi, takšen bo tudi prihod Sina človekovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Kajti kakor so v dneh, ki so bili pred poplavo, jedli in pili, se poročali ter dajali v zakon, do dneva, ko je Noe vstopil v barko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'in niso spoznali, dokler ni prišla poplava in jih vse odnesla; takšen bo tudi prihod Sina človekovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Takrat bosta dva na njivi; eden bo vzet, drugi pa puščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dve ženski bosta mleli pri mlinu; ena bo vzeta, druga pa puščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Stražite torej, kajti ne veste, katero uro pride vaš Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Toda vedite to, da če bi hišni oče vedel, ob kateri uri bi tat prišel, bi stražil in ne bi dopustil, da bi bila njegova hiša vlomljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Zatorej bodite tudi vi pripravljeni, kajti Sin človekov prihaja ob taki uri, za katero ne mislite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, '§ Kdo je torej zvesti in modri služabnik, ki ga je njegov gospodar določil nad njegovo družino, da jim daje obed ob pravšnjem obdobju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Blagoslovljen je ta služabnik, ki ga bo njegov gospodar, ko pride, našel tako delati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Resnično, povem vam: ›Da ga bo naredil za gospodarja nad vsemi svojimi dobrinami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Toda če bo ta hudobni služabnik v svojem srcu rekel: ›Moj gospodar odlaša svoj prihod,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'in bo začel udarjati svoje soslužabnike ter jesti in piti s pijanimi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'bo gospodar tega služabnika prišel na dan, ko ga ne pričakuje in ob uri, ki se je ne zaveda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'in presekal ga bo narazen ter mu določil njegov delež s hinavci; tam bo jokanje in škripanje z zobmi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '»Takrat bo nebeško kraljestvo podobno desetim devicam, ki so vzele svoje svetilke in šle, da srečajo ženina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'In pet izmed njih je bilo modrih, pet pa je bilo nespametnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Te, ki so bile nespametne, so vzele svoje svetilke, niso pa z njimi vzele olja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'toda modre so s svojimi svetilkami v svojih posodah vzele olje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Medtem ko se je ženin mudil, so vse podremale in zaspale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Ob polnoči pa je nastalo vpitje: ›Glejte, ženin prihaja. Pojdite ven, da ga srečate.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tedaj so vse te device vstale in očistile svoje svetilke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'In nespametne so rekle modrim: ›Dajte nam od svojega olja, kajti naše svetilke so ugasnile.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Toda modre so odgovorile, rekoč: ›Ne tako, da ne bi bilo premalo za nas in vas, toda pojdite raje k tem, ki prodajajo in si kupite zase.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Medtem ko so odšle kupovat, pa je prišel ženin, in tiste, ki so bile pripravljene, so vstopile z njim v zakon in vrata so se zaprla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Kasneje so prišle tudi druge device, rekoč: ›Gospod, Gospod, odpri nam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Toda odgovoril je in rekel: ›Resnično, povem vam: ›Ne poznam vas.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, '§ Stražite torej, kajti ne veste niti dneva niti ure, v kateri prihaja Sin človekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Kajti nebeško kraljestvo je kakor človek, ki potuje v daljno deželo, ki je sklical svoje lastne služabnike ter jim izročil svoje dobrine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'In enemu je dal pet talentov, drugemu dva in naslednjemu enega; vsakemu človeku glede na njegove razne sposobnosti; in nemudoma je odšel na svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Potem je tisti, ki je prejel pet talentov, šel in s temi trgoval in tem prislužil še pet drugih talentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'In podobno je tisti, ki je prejel dva, prav tako pridobil še dva druga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Toda tisti, ki je prejel enega, je šel in kopál v zemljo in skril denar svojega gospodarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Po dolgem času pride gospodar teh služabnikov in z njimi poračuna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'In tako je tisti, ki je prejel pet talentov, prišel in prinesel pet drugih talentov, rekoč: ›Gospodar, izročil si mi pet talentov. Glej, poleg teh sem pridobil še pet talentov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Njegov gospodar mu je rekel: ›Dobro narejeno, ti dobri in zvesti služabnik. Zvest si bil nad malo stvarmi, naredil te bom za vladarja nad mnogimi stvarmi; vstopi v radost svojega gospodarja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Tudi tisti, ki je prejel dva talenta, je prišel in rekel: ›Gospodar, izročil si mi dva talenta; glej, poleg teh sem pridobil še dva druga talenta.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Njegov gospodar mu je rekel: ›Dobro narejeno, dobri in zvesti služabnik. Zvest si bil nad malo stvarmi, naredil te bom za vladarja nad mnogimi stvarmi; vstopi v radost svojega gospodarja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Potem je prišel tisti, ki je prejel en talent in rekel: ›Gospodar, poznal sem te, da si trd človek, žanješ, kjer nisi sejal in zbiraš, kjer nisi nastlal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'in sem se bal in sem šel ter tvoj talent skril v zemljo. Glej tukaj imaš, kar je tvojega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Njegov gospodar je odgovoril in mu rekel: ›Ti zlobni in leni služabnik, vedel si, da žanjem, kjer nisem sejal in zbiram tam, kjer nisem nastlal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'dolžan si bil torej dati moj denar menjalcem in tedaj, ob mojem prihodu, bi jaz svojo lastnino prejel z obrestmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Vzemite mu torej talent in ga dajte temu, ki ima deset talentov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Kajti vsak, kdor ima, mu bo dano in bo imel obilje, toda od tistega, ki nima, bo vzeto proč celó to, kar ima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Nekoristnega služabnika pa vrzite v zunanjo temo; tam bo jokanje in škripanje z zobmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '§ Ko bo prišel Sin človekov v svoji slavi in vsi sveti angeli z njim, potem bo sédel na prestol svoje slave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'in pred njim bodo zbrani vsi narodi, in oddvojil jih bo ene od drugih, kakor pastir ločuje svoje ovce od koz;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'in ovce bo postavil na svojo desno roko, toda koze na levo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tedaj bo Kralj rekel tistim na svoji desnici: ›Pridite, blagoslovljeni od mojega Očeta, podedujte kraljestvo, za vas pripravljeno od ustanovitve sveta,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'kajti bil sem lačen in ste mi dali obrok; bil sem žejen in ste mi dali piti; bil sem tujec in ste me sprejeli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'nag in ste me oblekli; bil sem bolan in ste me obiskali; bil sem v ječi in ste prišli k meni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tedaj mu bodo pravični odgovorili, rekoč: ›Gospodar, kdaj smo te videli lačnega in te nahranili ali žejnega in [ti] dali piti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Kdaj smo te videli tujca in te sprejeli? Ali nagega in te oblekli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Ali kdaj smo te videli bolnega ali v ječi in prišli k tebi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'In kralj jim bo odgovoril in rekel: ›Resnično, povem vam: ›V kolikor ste to storili enemu najmanjšemu izmed teh mojih bratov, ste to storili meni.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Tedaj bo prav tako rekel tem na levici: ›Odidite od mene, vi prekleti, v večni ogenj, pripravljen za hudiča in njegove angele;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'kajti lačen sem bil, pa mi niste dali obroka; žejen sem bil, pa mi niste dali piti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'tujec sem bil, pa me niste sprejeli; nag in me niste oblekli; bolan in v ječi, pa me niste obiskali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tedaj mu bodo tudi oni odgovorili, rekoč: ›Gospodar, kdaj smo te videli lačnega ali žejnega ali tujca ali nagega ali bolnega ali v ječi in ti nismo postregli?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Tedaj jim bo odgovoril, rekoč: ›Resnično, povem vam: ›V kolikor tega niste storili enemu izmed teh najmanjših, tega niste storili meni.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'In ti bodo šli proč v večno kazen, toda pravični v večno življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'In pripetilo se je, ko je Jezus končal vse te govore, da je rekel svojim učencem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '»Veste, da je čez dva dni praznik pashe in Sin človekov je izdan, da bi bil križan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tedaj so se skupaj zbrali visoki duhovniki in pisarji ter starešine izmed ljudstva, k palači vélikega duhovnika, ki mu je bilo ime Kajfa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'in se posvetovali, da bi lahko Jezusa s premetenostjo prijeli ter ga ubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Toda rekli so: »Ne na prazničen dan, da med ljudmi ne bi bilo vstaje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Torej ko je bil Jezus v Betaniji, v hiši Simona gobavca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'je prišla k njemu ženska, ki je imela alabastrno škatlo zelo dragocenega mazila in ko je sedel pri mizi, ga je izlila na njegovo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Toda ko so njegovi učenci to videli, so bili ogorčeni, rekoč: »S kakšnim namenom je ta potrata?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Kajti to mazilo bi bilo lahko drago prodano in dano revnim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Ko je Jezus to spoznal, jim je rekel: »Zakaj nadlegujete žensko? Kajti na meni je storila dobro delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Kajti revne imate vedno s seboj, toda mene nimate vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Ker je to mazilo izlila na moje telo, je to storila za moj pokop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Resnično, povem vam: ›Kjerkoli se bo ta evangelij oznanjal po vsem svetu, tam se bo tudi to, kar je ta ženska storila, pripovedovalo v spomin nanjo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tedaj je eden izmed dvanajsterih, imenovan Juda Iškarijot, odšel k visokim duhovnikom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, '§ in jim rekel: »Kaj mi boste dali in vam ga bom izročil?« In z njim so se sporazumeli za trideset koščkov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'In od tedaj je iskal priložnost, da ga izda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Učenci so torej prvi dan [praznika] nekvašenega kruha prišli k Jezusu in mu rekli: »Kje želiš, da ti pripravimo, da boš jedel pashalno jagnje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'In rekel je: »Pojdite v mesto k temu in temu človeku ter mu recite: ›Učitelj pravi: ›Moj čas je blizu; s svojimi učenci bom v tvoji hiši praznoval pasho.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'In učenci so storili, kakor jim je Jezus določil; in pripravili so pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Torej, ko je prišel večer, se je z dvanajsterimi usedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'In ko so jedli, je rekel: »Resnično, povem vam, da me bo eden izmed vas izdal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Bili so silno žalostni in začeli so mu vsak izmed njih govoriti: »Gospod, ali sem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'In odgovoril je ter rekel: »Kdor pomaka svojo roko z menoj v skledo, ta isti me bo izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Sin človekov gre, kakor je pisano o njem, toda gorje temu človeku, po katerem je Sin človekov izdan! Dobro bi bilo za tega človeka, če se ne bi rodil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Potem je Juda, ki ga je izdal, odgovoril in rekel: »Učitelj, ali sem jaz?« Rekel mu je: »Ti si rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'In medtem ko so jedli je Jezus vzel kruh in ga blagoslovil in ga razlomil ter ga dal učencem in rekel: »Vzemite, jejte; to je moje telo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'In vzel je čašo in se zahvalil ter jim jo dal, rekoč: »Pijte iz nje vsi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'kajti to je moja kri nove zaveze, ki je prelita za mnoge v odpuščanje grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Toda povem vam: ›Odslej ne bom pil od tega sadu vinske trte do tistega dne, ko bom z vami pil novega v kraljestvu svojega Očeta.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'In ko so odpeli hvalnico, so odšli ven na Oljsko goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tedaj jim Jezus reče: »Vsi se boste to noč pohujšali zaradi mene, kajti pisano je: ›Udaril bom pastirja in ovce tropa bodo razkropljene naokoli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Toda potem, ko bom obujen, bom pred vami šel v Galilejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Peter je odgovoril in mu rekel: »Čeprav se bodo vsi ljudje pohujšali zaradi tebe, se vendarle jaz nikoli ne bom pohujšal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jezus mu je rekel: »Resnično, povem ti: ›Da me boš to noč, preden petelin zapoje, trikrat zatajil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Peter mu je rekel: »Čeprav bi moral umreti s teboj, te vendarle ne bom zatajil.« Tudi vsi učenci so enako govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tedaj pride Jezus z njimi na kraj, imenovan Getsemani in reče učencem: »Sédite tukaj, medtem ko grem in tamle molim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'In s seboj je vzel Petra ter dva Zebedejeva sinova in postajal je žalosten ter zelo potrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tedaj jim reče: »Moja duša je silno žalostna, celó do smrti; zadržujte se tukaj in bedite z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'In odšel je še malce dlje ter padel na svoj obraz in molil, rekoč: »Oh moj Oče, če je to mogoče, naj gre ta čaša mimo mene, vendar ne kakor jaz hočem, temveč kakor hočeš ti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'In pride k učencem in jih najde speče ter reče Petru: »Kaj, eno uro niste zmogli bedeti z menoj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Bedite in molíte, da ne pridete v skušnjavo. Duh je zares voljan, toda meso je šibko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Zopet je, drugič, odšel proč in molil, rekoč: »Oh moj Oče, če ta čaša ne more iti mimo mene, ne da jo izpijem, zgôdi se tvoja volja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'In prišel je ter jih ponovno našel speče, kajti njihove oči so bile težke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'In zapustil jih je ter ponovno odšel proč in tretjič molil, govoreč iste besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Potem pride k svojim učencem in jim reče: »Spite torej in vzemite si [svoj] počitek; glejte, ura je blizu, in Sin človekov je izdan v roke grešnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Vstanite, pojdimo. Glejte, tisti, ki me izdaja, je blizu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'In medtem ko je še govoril, glej, je prišel Juda, eden izmed dvanajsterih in z njim velika množica z meči in palicami, od visokih duhovnikov in starešin izmed ljudstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Torej tisti, ki ga je izdal, jim je dal znamenje, rekoč: »Kogarkoli bom poljubil, ta isti je on; trdno ga primite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'In nemudoma je prišel k Jezusu in rekel: »Pozdravljen, učitelj,« ter ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jezus pa mu je rekel: »Prijatelj, zakaj si prišel?« Tedaj so prišli in na Jezusa položili roke ter ga prijeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'In glej, eden izmed njih, ki je bil z Jezusom, je iztegnil svojo roko ter dvignil svoj meč in udaril služabnika vélikega duhovnika in odbil njegovo uho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tedaj mu je Jezus rekel: »Vtakni svoj meč ponovno na njegovo mesto, kajti vsi tisti, ki primejo za meč, bodo z mečem pokončani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Ali mislite, da ne morem sedaj moliti k svojemu Očetu in bi mi takoj dal več kot dvanajst legij angelov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Toda kako naj se potem izpolnijo pisma, da mora biti tako?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'In v tej isti uri je Jezus rekel množicam: »Ali ste prišli ven kot proti razbojniku, z meči in palicami, da me primete? Dnevno sem sedel z vami ter učil v templju, pa me niste prijeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Toda vse to je bilo storjeno, da se lahko izpolnijo pisma prerokov.« Tedaj so ga vsi učenci zapustili in pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Tisti pa, ki so Jezusa zgrabili, so ga odpeljali proč h Kajfu, vélikemu duhovniku, kjer so bili zbrani pisarji in starešine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Toda Peter mu je od daleč sledil do palače vélikega duhovnika in vstopil ter sédel s služabniki, da vidi konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, '§ Visoki duhovniki in starešine in ves véliki zbor so torej iskali krivih prič zoper Jezusa, da bi ga usmrtili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'toda niso našli nobene; da, čeprav je prišlo mnogo krivih prič, vendar niso našli nobene. Na koncu sta prišli dve krivi priči');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'in rekli sta: »Ta je rekel: ›Zmožen sem uničiti Božji tempelj in ga v treh dneh zgraditi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'In véliki duhovnik je vstal ter mu rekel: »Nič ne odgovarjaš? Kaj je to, kar ti priči pričujeta zoper tebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Toda Jezus je ohranil svoj mir. In véliki duhovnik je odgovoril ter mu rekel: »Zaklinjam te pri živem Bogu, da nam poveš, ali si ti Kristus, Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jezus mu reče: »Ti si rekel, vendar ti jaz pravim: ›Odslej boste videli Sina človekovega sedeti na desnici moči in prihajati na oblakih neba.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tedaj je véliki duhovnik raztrgal svoja oblačila, rekoč: »Govoril je bogokletje; imamo kakšno dodatno potrebo po pričah? Glejte, sedaj ste slišali njegovo bogokletje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Kaj vi mislite?« Oni pa so odgovorili in rekli: »Kriv je smrti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tedaj so mu pljuvali v njegov obraz in ga klofutali; in drugi so ga udarjali z dlanmi svojih rok,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'rekoč: »Prerokuj nam, ti Kristus: ›Kdo je tisti, ki te je udaril?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Peter je torej sedèl zunaj v palači; in k njemu je prišla gospodična, rekoč: »Tudi ti si bil z Jezusom iz Galileje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Toda on je pred vsemi njimi zanikal, rekoč: »Ne vem, kaj govoriš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'In ko je odšel ven v preddverje, ga je videla druga služabnica in rekla tem, ki so bili tam: »Ta je bil prav tako z Jezusom Nazarečanom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'In ponovno je s prisego zanikal: »Ne poznam tega človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'In čez nekaj časa so prišli k njemu tisti, ki so stali ob strani ter rekli Petru: »Zagotovo si ti eden izmed njih, kajti tvoje narečje te izdaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tedaj je začel preklinjati in prisegati, rekoč: »Ne poznam [tega] človeka.« In petelin je takoj zapel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'In Peter se je spomnil Jezusove besede, ki mu jo je rekel: »Preden petelin zapoje, me boš trikrat zatajil.« In odšel je ven ter se bridko zjokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Ko je prišlo jutro, so se vsi visoki duhovniki in starešine izmed ljudstva posvetovali zoper Jezusa, da ga usmrtijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'In ko so ga zvezali, so ga odvedli proč ter ga izročili voditelju Ponciju Pilatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Potem se je Juda, ki ga je izdal, ko je videl, da je bil obsojen, pokesal in trideset koščkov srebra prinesel nazaj k visokim duhovnikom in starešinam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'rekoč: »Grešil sem, ker sem izdal nedolžno kri.« Oni pa so rekli: »Kaj je to nam? Ti glej na to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'In srebrne koščke je vrgel v tempelj in odšel ter samega sebe obesil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Visoki duhovniki pa so vzeli koščke srebra in rekli: »Ni zakonito, da jih damo v zakladnico, ker so cena krvi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'In posvetovali so se ter z njimi kupili lončarjevo njivo, da bi v njej pokopavali tujce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Zatorej je bilo to polje do današnjega dne imenovano Njiva krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tedaj je bilo izpolnjeno to, kar je bilo rečeno po preroku Jeremiju, rekoč: ›In vzeli so trideset koščkov srebra, ceno tistega, ki je bil ocenjen, ki so ga Izraelovi otroci ocenili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'in dali so jih za lončarjevo njivo, kakor mi je določil Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'In Jezus je stal pred voditeljem in voditelj ga je vprašal, rekoč: »Ali si ti judovski Kralj?« Jezus mu je rekel: »Ti praviš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'In ko je bil obtožen od visokih duhovnikov in starešin, ni ničesar odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tedaj mu je Pilat rekel: »Ali ne slišiš, koliko besed pričajo zoper tebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Pa mu ni odgovoril niti na eno besedo, tako, da se je voditelj silno čudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Torej, na ta praznik je imel voditelj navado množici izpustiti jetnika, ki bi ga hotela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, '§ In takrat so imeli opaznega jetnika, imenovanega Baraba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, '§ Ko so bili torej zbrani skupaj, jim je Pilat rekel: »Katerega hočete, da vam izpustim? Baraba ali Jezusa, ki se imenuje Kristus?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Kajti vedel je, da so mu ga izročili zaradi zavisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Ko se je usedel na sodni stol, je njegova žena poslala k njemu, rekoč: »Nič ne imej s tem pravičnim človekom, kajti danes sem v sanjah zaradi njega trpela mnoge stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Toda visoki duhovniki in starešine so pregovorili množico, da bi zahtevali Baraba in uničili Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Voditelj je odgovoril in jim rekel: »Katerega od teh dveh hočete, da vam izpustim?« Rekli so: »Baraba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilat jim reče: »Kaj naj potem storim z Jezusom, ki se imenuje Kristus?« Vsi so mu rekli: »Križan naj bo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'In voditelj jim je rekel: »Zakaj, kakšno zlo je storil?« Vendar so še bolj kričali, rekoč: »Križan naj bo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Ko je Pilat videl, da niti malo ne more prevladati, temveč da je bil toliko bolj storjen nemir, je vzel vodo in svoje roke umil pred množico, rekoč: »Nedolžen sem pri krvi te pravične osebe; vi glejte na to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Potem so vsi ljudje odgovorili in rekli: »Njegova kri bodi na nas in na naših otrocih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tedaj jim je izpustil Baraba in ko je Jezusa prebičal, ga je izročil, da bi bil križan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tedaj so voditeljevi vojaki Jezusa vzeli v skupno dvorano in k njemu zbrali vso četo vojakov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'In ga slekli ter mu oblekli škrlatno svečano oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'In ko so spletli krono iz trnja, so jo dali na njegovo glavo in trst v njegovo desnico; in poklekovali so pred njim ter ga zasmehovali, rekoč: »Pozdravljen, judovski Kralj!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'In pljuvali so vanj in vzeli trst ter ga udarjali po glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Potem pa, ko so ga zasmehovali, so z njega slekli svečano oblačilo in nanj nadeli njegova lastna oblačila ter ga odpeljali proč, da ga križajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'In ko so prišli ven, so našli človeka iz Cirene, Simona po imenu; njega so prisilili, da je nesel njegov križ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'In ko so prišli na kraj, imenovan Golgota, ki se mu reče ›kraj lobanje,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, '§ so mu dali piti kisa, pomešanega z žolčem; in ko je le-tega pokusil, ni hotel piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, '§ Oni pa so ga križali in metaje žreb razdelili njegove obleke, da bi se lahko izpolnilo, kar je bilo rečeno po preroku: ›Moje obleke so si delili med seboj in za mojo suknjo so metali žrebe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'In sedeli so ter ga tam stražili;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'in nad njegovo glavo so namestili njegovo napisano obtožbo: TA JE JEZUS, JUDOVSKI KRALJ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Takrat sta bila tam z njim križana dva tatova, eden na desni roki, drugi pa na levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Tisti pa, ki so hodili mimo, so ga zasramovali in zmajevali s svojimi glavami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'ter govorili: »Ti, ki podiraš tempelj in ga zgradiš v treh dneh, reši samega sebe. Če si Božji Sin, pridi s križa dol.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Podobno so ga zasmehovali tudi visoki duhovniki s pisarji in starešinami ter govorili:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '»Rešil je druge; samega sebe ne more rešiti. Če je on Izraelov Kralj, naj sedaj pride dol s križa in mu bomo verjeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Zaupal je v Boga; naj ga sedaj osvobodi, če ga hoče imeti, kajti rekel je: ›Jaz sem Božji Sin.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Prav tako sta ga sramotila tudi tatova, ki sta bila križana z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Od šeste ure je bila torej tema po vsej deželi do devete ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Okoli devete ure pa je Jezus z močnim glasom zaklical, rekoč: »Elí, Elí, láma sabahtáni?« kar se reče: »Moj Bog, moj Bog, zakaj si me zapustil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Ko so nekateri izmed teh, ki so tam stali, to slišali, so rekli: »Ta človek kliče Elija.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'In eden izmed njih je nemudoma stekel in vzel gobo ter jo napojil s kisom in jo nataknil na trst ter mu dal piti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Ostali so rekli: »Pústi, naj vidimo, če bo prišel Elija, da ga reši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Ko je Jezus z močnim glasom ponovno zavpil, je odposlal duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'In glej, tempeljsko zagrinjalo se je raztrgalo na dvoje od vrha do tal; in zemlja se je stresla in skale so se razklale;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'in grobovi so se odprli; in mnogo teles svetih, ki so spali, je vstalo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'in po njegovem vstajenju so prišli iz grobov in odšli v sveto mesto in se mnogim prikazali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Torej, ko so stotnik in ti, ki so bili z njim, ki so stražili Jezusa, videli potres in te stvari, ki so se zgodile, so se silno bali, rekoč: »Resnično, ta je bil Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Tam je bilo mnogo žensk, ki so zrle od daleč, ki so Jezusu sledile iz Galileje ter mu stregle,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'med katerimi je bila Marija Magdalena in Marija, Jakobova in Jožefova mati ter mati Zebedejevih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Ko je prišel večer, je tja prišel bogataš iz Arimateje, imenovan Jožef, ki je bil tudi sam Jezusov učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Odšel je k Pilatu in prosil za Jezusovo telo. Tedaj je Pilat ukazal, naj bo telo izročeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Ko je Jožef vzel telo, ga je ovil v čisto laneno oblačilo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'in ga položil v svojo novo grobnico, ki jo je izklesal v skalo, in k vratom mavzoleja zavalil velik kamen ter odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'In tam sta bili Marija Magdalena in druga Marija, ki sta sedeli nasproti mavzoleju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Torej naslednji dan, ki je sledil dnevu priprave, so visoki duhovniki in farizeji skupaj prišli k Pilatu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'rekoč: »Gospod, spominjamo se, da je ta slepar, medtem ko je bil še živ, rekel: ›Po treh dneh bom ponovno vstal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Ukaži torej, da bo mavzolej zavarovan do tretjega dne, da ne pridejo ponoči njegovi učenci ter ga skrivaj odnesejo in rečejo ljudem: ›Obujen je od mrtvih;‹ tako bo zadnja prevara hujša kakor prva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilat jim je rekel: »Imate stražo; pojdite svojo pot, naredite to tako varno kakor lahko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Tako so šli in zapečatili kamen ter postavili stražo in mavzolej naredili varen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Ob koncu šabata, ko se je začelo svitati k prvemu dnevu tedna, sta prišli Marija Magdalena in druga Marija, da pogledata mavzolej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'In glej, bil je velik potres, kajti Gospodov angel se je spustil iz nebes in prišel ter odvalil kamen od vrat in sédel nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Njegovo obličje je bilo kakor bliskanje in njegovo oblačilo belo kakor sneg,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'in zaradi strahu pred njim so se čuvaji tresli ter postali kakor mrtvi možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'In angel je odgovoril ter ženskama rekel: »Ne bojta se, kajti vem, da iščeta Jezusa, ki je bil križan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Ni ga tukaj, kajti vstal je, kakor je rekel. Pridita, poglejta prostor, kjer je ležal Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'In pojdita hitro ter povejta njegovim učencem, da je obujen od mrtvih. In glejta, pred vami gre v Galilejo, tam ga boste videli. Glejta, povedal sem vama.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Hitro sta s strahom in veliko radostjo odšli od mavzoleja, in tekli, da prineseta sporočilo njegovim učencem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Ko sta šli, da povesta njegovim učencem, glej, ju sreča Jezus, rekoč: »Pozdravljeni.« In prišli sta ter mu objeli stopala in ga oboževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tedaj jima je Jezus rekel: »Ne bojta se. Pojdita, povejta mojim bratom, naj gredo v Galilejo in tam me bodo videli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Ko sta torej odhajali, glej, je prišlo v mesto nekaj stražarjev in visokim duhovnikom so naznanili vse stvari, ki so se zgodile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'In ko so bili zbrani s starešinami in imeli posvet, so vojakom dali veliko denarja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'rekoč: »Recite: ›Njegovi učenci so prišli ponoči in ga kradoma odnesli proč, medtem ko smo spali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'In če pride to do voditeljevih ušes, ga bomo mi pregovorili in vas obvarovali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Tako so vzeli denar in storili, kakor so bili poučeni. In to govorjenje je pogosto pripovedovano med Judi do tega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Potem je enajstero učencev odšlo proč v Galilejo, na goro, kamor jim je Jezus določil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'In ko so ga zagledali, so ga oboževali, toda nekateri so dvomili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'In Jezus je pristopil in jim spregovoril, rekoč: »Meni je dana vsa oblast, v nebesih in na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Pojdite torej in učite vse narode, krščujoč jih v ime Očeta in Sina in Svetega Duha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, '§ učeč jih obeleževati vse besede, katerekoli sem vam zapovedal. In glejte, jaz sem z vami vedno, celó do konca sveta. Amen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Začetek evangelija Jezusa Kristusa, Božjega Sina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'kakor je zapisano v prerokih: »Glej, pošiljam svojega poslanca pred tvojim obličjem, ki bo pripravil tvojo pot pred teboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Glas nekoga, ki kliče v divjini: ›Pripravite Gospodovo pot, izravnajte njegove steze.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Janez je krščeval v divjini in oznanjal krst kesanja v odpuščanje grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'In k njemu je prišla vsa judejska dežela in tisti iz Jeruzalema in vsi so bili po njem krščeni v reki Jordan ter priznavali svoje grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'In Janez je bil odet s kameljo dlako in s pasom iz usnja okoli svojih ledij; in jedel je kobilice in divji med,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'in oznanjal, rekoč: »Za menoj prihaja nekdo, močnejši kakor jaz, čigar čevljev jermena nisem vreden, da bi se sklonil in ju odvezal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Zares sem vas krstil z vodo, toda on vas bo krstil s Svetim Duhom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'In pripetilo se je v tistih dneh, da je prišel Jezus iz Nazareta v Galileji in je bil po Janezu krščen v Jordanu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'In nemudoma, ko se je vzpenjal iz vode, je zagledal odprta nebesa in Duha, podobnega golobici, spuščati se nadenj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'in prišel je glas z neba, rekoč: »Ti si moj ljubljeni Sin, s katerim sem zelo zadovoljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'In Duh ga je takoj gnal v divjino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'In tam, v divjini, je bil štirideset dni skušan od Satana in bil je z divjimi živalmi in angeli so mu stregli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Potem ko je bil torej Janez vtaknjen v ječo, je Jezus prišel v Galilejo in oznanjal evangelij Božjega kraljestva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, '§ ter govoril: »Čas je dopolnjen in Božje kraljestvo se je približalo. Pokesajte se in verjemite evangeliju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Ko je torej hodil ob Galilejskem morju, je zagledal Simona in njegovega brata Andreja metati mrežo v morje, kajti bila sta ribiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Jezus jima je rekel: »Pridita za menoj in storil vama bom, da postaneta ribiča ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'In nemudoma sta zapustila svoje mreže ter mu sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'In ko je odšel malce naprej od tam, je zagledal Jakoba, Zebedejevega sina in njegovega brata Janeza, ki sta bila prav tako na ladji in popravljala svoje mreže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'In nemudoma ju je poklical; in zapustila sta svojega očeta Zebedeja z najetimi služabniki na ladji ter odšla za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'In odšli so v Kafarnáum in nemudoma, na šabatni dan, je vstopil v sinagogo ter učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'In nad njegovim naukom so bili osupli, kajti učil jih je kakor nekdo, ki ima oblast in ne kakor pisarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'In v njihovi sinagogi je bil človek z nečistim duhom, in ta je zakričal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'rekoč: »Daj nam mir; kaj imamo opraviti s teboj, ti, Jezus Nazarečan? Ali si prišel, da nas uničiš? Vem, kdo si, Sveti od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'In Jezus ga je oštel, rekoč: »Umolkni in pojdi iz njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'In ko ga je nečisti duh trgal in zavpil z močnim glasom, je prišel iz njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'In vsi so bili osupli, tako zelo, da so se med seboj spraševali, rekoč: »Kakšna beseda je to? Kakšen novi nauk je to? Kajti z oblastjo ukazuje celó nečistim duhovom in oni ga ubogajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'In njegov slôves se je takoj razširil po vsem celotnem področju okoli Galileje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'In ko so prišli iz sinagoge, so z Jakobom in Janezom nemudoma vstopili v Simonovo in Andrejevo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Toda Simonova tašča je ležala bolna zaradi vročice in takoj so mu povedali o njej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'In prišel je ter jo prijel za roko in jo dvignil; in vročica jo je takoj zapustila in jim je stregla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'In zvečer, ko je sonce zašlo, so k njemu privedli vse tiste, ki so bili bolni in tiste, ki so bili obsedeni s hudiči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'In vse mesto je bilo skupaj zbrano pri vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'In ozdravil je mnoge, ki so bili bolni zaradi različnih bolezni in izgnal mnogo hudičev; hudičem pa ni dovolil govoriti, ker so ga poznali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'In zjutraj, ko je vstal veliko pred dnevom, je odšel ven ter se odpravil na samoten kraj in tam molil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon in tisti, ki so bili z njim, pa so sledili za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'In ko so ga našli, so mu rekli: »Vsi ljudje te iščejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Rekel jim je: »Pojdimo v naslednja mesta, da bom lahko tudi tam oznanjal, kajti zato sem prišel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'In po vsej celotni Galileji je oznanjal v njihovih sinagogah ter izganjal hudiče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'In k njemu je prišel gobavec, ga rotil in pokleknil navzdol k njemu ter mu rekel: »Če hočeš, me moreš narediti čistega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'In Jezus, prevzet s sočutjem, je iztegnil svojo roko in se ga dotaknil in mu reče: »Hočem; bodi čist.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, '§ In brž, ko je izgovoril, je gobavost takoj odšla od njega in bil je očiščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, '§ In strogo mu je zabičal ter ga nemudoma poslal proč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'ter mu rekel: »Glej, da nikomur nič ne poveš, temveč pojdi svojo pot, pokaži se duhovniku in daruj za svoje očiščenje te stvari, ki jih je Mojzes zapovedal, njim v pričevanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Toda ta je odšel ven in začel to zelo naznanjati in besedo na široko razglašati, tako da Jezus ni mogel več javno vstopiti v mesto, temveč je bil zunaj na zapuščenih krajih, in k njemu so prihajali iz vsake četrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Po nekaj dneh je ponovno vstopil v Kafarnáum, in razglasilo se je, da je v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'In nemudoma so bili zbrani mnogi, toliko, da tam ni bilo več prostora, da jih sprejme, ne, niti pred vrati ne; in oznanjal jim je besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'In prišli so k njemu in prinesli nekoga, bolnega zaradi paralize, ki je bil prenašan od štirih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Ko pa zaradi gneče niso mogli priti bliže k njemu, so odkrili streho, kjer je bil. In ko so jo predrli, so spustili posteljo, na kateri je ležal bolni zaradi paralize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Ko je Jezus videl njihovo vero, je rekel bolnemu zaradi paralize: »Sin, tvoji grehi so ti odpuščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Toda bili so nekateri izmed pisarjev, ki so tam sedeli ter v svojih srcih razmišljali:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '»Zakaj ta človek govori takšna bogokletja? Kdo lahko odpušča grehe razen Boga samega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'In takoj, ko je Jezus v svojem duhu zaznal, da so v sebi tako modrovali, jim je rekel: »Zakaj v svojih srcih razmišljate te besede?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Ali je bolnemu zaradi paralize lažje reči: ›Tvoji grehi so ti odpuščeni‹ ali reči: ›Vstani in vzemi svojo posteljo ter hôdi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Toda da boste lahko vedeli, da ima Sin človekov na zemlji oblast odpuščati grehe, (reče bolnemu zaradi paralize)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'pravim ti: ›Vstani in vzemi svojo posteljo ter pojdi svojo pot v svojo hišo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'In ta je takoj vstal, vzel posteljo ter pred njimi vsemi odšel, tako da so bili vsi osupli in slavili Boga, rekoč: »Nikoli tega nismo videli na tak način.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'In ponovno je odšel naprej ob morski obali, in vsa množica je krenila k njemu in jih je učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'In ko je hodil mimo, je zagledal Levija, Alfejevega sina, ki je sedel pri kraju plačevanja davkov ter mu rekel: »Sledi mi.« In ta je vstal ter mu sledil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'In pripetilo se je, ko je Jezus v njegovi hiši sedel pri obedu, da je tudi mnogo davkarjev in grešnikov sedelo skupaj z Jezusom in njegovimi učenci, kajti bilo jih je mnogo in so mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'In ko so ga pisarji in farizeji videli jesti z davkarji in grešniki, so njegovim učencem rekli: »Kako to, da jé in pije z davkarji in grešniki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, '§ Ko je Jezus to slišal, jim reče: »Tisti, ki so zdravi, nimajo nobene potrebe po zdravniku, temveč tisti, ki so bolni; nisem prišel klicat pravičnih, temveč grešnike h kesanju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Janezovi učenci in učenci farizejev so se postili; in prišli so ter mu rekli: »Zakaj se Janezovi učenci in učenci farizejev postijo, tvoji učenci pa se ne postijo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jezus jim je rekel: »Ali se lahko otroci svatovske sobe postijo, dokler je z njimi ženin? Kolikor dolgo imajo s seboj ženina, se ne morejo postiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Toda prišli bodo dnevi, ko bo ženin vzet proč od njih in tedaj, v tistih dneh, se bodo postili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Tudi nihče ne prišije koščka novega oblačila na staro obleko; sicer bo nov košček, ki jo je zapolnil, odvzel iz stare in nastane hujša raztrganina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'In novega vina nihče ne vliva v stare mehove, sicer novo vino mehove razžene, vino pa se izlije in mehovi bodo poškodovani; temveč mora biti novo vino vlito v nove mehove.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'In pripetilo se je, da je na šabatni dan šel skozi žitna polja; in njegovi učenci so med hojo začeli smukati žitno klasje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Farizeji so mu rekli: »Glej, zakaj delajo na šabatni dan to, kar ni zakonito?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Rekel jim je: »Ali niste nikoli brali, kaj je storil David, ko je imel potrebo in je bil lačen on in tisti, ki so bili z njim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Kako je v dneh vélikega duhovnika Abjatárja odšel v Božjo hišo in jedel hlebe navzočnosti, kar ni zakonito jesti [nikomur] razen duhovnikom in je dal tudi tem, ki so bili z njim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'In rekel jim je: »Šabat je bila narejena zaradi človeka, ne pa človek zaradi šabate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'zato je Sin človekov Gospod tudi [čez] šabat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Ponovno je vstopil v sinagogo; in tam je bil človek, ki je imel izsušeno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'In opazovali so ga, ali ga bo ozdravil na šabatni dan; da bi ga lahko obtožili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'In človeku, ki je imel izsušeno roko, reče: »Stopi naprej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'In jim reče: »Ali je na šabatne dneve zakonito delati dobro ali delati zlo? Rešiti življenje ali ubiti?« Toda molčali so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, '§ Ko je z jezo pogledal na te naokoli, užaloščen zaradi trdote njihovih src, reče človeku: »Iztegni svojo roko.« In iztegnil jo je; in njegova roka je bila v celoti ozdravljena, tako kot druga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'In farizeji so odšli ter se s herodovci nemudoma posvetovali zoper njega, kako bi ga lahko pokončali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Toda Jezus se je s svojimi učenci umaknil k morju, in sledila mu je velika množica iz Galileje in iz Judeje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'in iz Jeruzalema in iz Idumeje in iz onstran Jordana; in tisti okoli Tira in Sidóna, velika množica je prišla k njemu, ko so slišali, kakšna velika dela je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'In svojim učencem je rekel, da naj ga zaradi množice pričakuje majhna ladja, da ne bi pritiskali nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Kajti mnoge je ozdravil; tako da so pritiskali nanj, da bi se ga dotaknili, kateri so imeli nadloge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'In kadar so ga zagledali nečisti duhovi, so pred njim padali dol in vpili, rekoč: »Ti si Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'In strogo jim je zapovedoval, da naj ga ne razglašajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'In povzpne se na goro ter pokliče k sebi katere je hotel, in prišli so k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'In določil jih je dvanajst, da bi bili z njim in da bi jih lahko poslal naprej oznanjat');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, '§ ter bi imeli oblast, da ozdravljajo bolezni ter da izganjajo hudiče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, '§ In Simonu je dal vzdevek Peter;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'in Jakoba, Zebedejevega sina in Janeza, Jakobovega brata; in dal jima je vzdevek Boanergés, to je: ›Sinova groma,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'in Andreja in Filipa in Bartolomeja in Mateja in Tomaža in Jakoba, Alfejevega sina in Tadeja in Simona Kananeja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'in Juda Iškarijota, ki ga je tudi izdal, in odšli so v hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'In množica ponovno pride skupaj, tako da so komaj jedli kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'In ko so njegovi prijatelji slišali o tem, so odšli ven, da ga primejo, kajti rekli so: »Brez pameti je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'In pisarji, ki so prišli dol iz Jeruzalema, so rekli: »Bélcebuba ima in s princem hudičev izganja hudiče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'In poklical jih je k sebi ter jim govoril v prispodobah: »Kako lahko Satan izžene Satana?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'In če se kraljestvo razdvoji zoper sebe, takšno kraljestvo ne more obstati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'In če se hiša razdvoji zoper sebe, takšna hiša ne more obstati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'In če se Satan dvigne zoper samega sebe in se razdvoji, ne more obstati, temveč ima konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nihče ne more vstopiti v hišo močnega in opleniti njegove dobrine, razen če ne bo najprej zvezal močnega; in tedaj bo oplenil njegovo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Resnično, povem vam: ›Vsi grehi bodo človeškim sinovom oproščeni in bogokletja, s katerimi bodo kakorkoli preklinjali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'toda kdor bo preklinjal zoper Svetega Duha, nima nikoli odpuščanja, temveč je v nevarnosti večnega prekletstva,‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'kajti govorili so: »Nečistega duha ima.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Tja so potem prišli njegovi bratje, njegova mati in stoječ zunaj, so poslali k njemu, [da] ga pokličejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'In okoli njega je sedela množica in rekli so mu: »Glej, tvoja mati in tvoji bratje so zunaj [in] te iščejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'In odgovoril jim je, rekoč: »Kdo je moja mati ali moji bratje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Pogledal je naokoli na te, ki so sedeli okoli njega ter rekel: »Glejte, moja mati in moji bratje!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Kajti kdorkoli bo izvrševal Božjo voljo, ta isti je moj brat in moja sestra in mati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'In ponovno je začel učiti ob morski obali, in tam se je k njemu zbrala velika množica, tako da je vstopil na ladjo in [na njej] sedel na morju; celotna množica pa je bila ob morju na kopnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'In s prispodobami jih je učil mnoge stvari in jim s svojim naukom govoril:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '»Prisluhnite: ›Glejte, sejalec je odšel sejat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'in pripetilo se je, medtem ko je sejal, da je nekaj padlo poleg poti in prišla je perjad neba in to pozobala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'In nekaj je padlo na kamnita tla, kjer ni imelo dovolj zemlje; in je takoj pognalo, ker ni imelo nobene globine zemlje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'toda ko je sonce vzšlo, je bilo ožgano; in ker ni imelo korenine, se je posušilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'In nekaj je padlo med trnje in trnje je zraslo in ga zadušilo in ni obrodilo sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Drugo pa je padlo na dobro zemljo in rodilo sad, ki je pognal in se povečeval; in obrodilo, nekatero trideseterno in nekatero šestdeseterno in nekatero stoterno.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'In rekel jim je: »Kdor ima ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Ko je bil sam, so ga ti, ki so bili z dvanajsterimi okoli njega, vprašali o prispodobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Rekel jim je: »Vam je dano, da poznate skrivnost Božjega kraljestva, toda tem, ki so zunaj, so vse te stvari prikazane v prispodobah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'da bi z gledanjem lahko videli, pa ne zaznali; in s poslušanjem lahko slišali, pa ne razumeli; da se ne bi kadarkoli spreobrnili in bi jim bili njihovi grehi odpuščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'In rekel jim je: »Ali ne razumete te prispodobe? In kako boste potem razumeli vse prispodobe?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Sejalec seje besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, '§ In ti so tisti ob poti, kjer je bila posejana beseda, toda ko so jo slišali, takoj pride Satan in vzame besedo, ki je bila posejana v njihova srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'In ti so prav tako tisti, ki so posejani na kamnita tla; ko so slišali besedo, jo takoj z veseljem sprejmejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'v sebi pa nimajo korenine in tako zdržijo le nekaj časa. Kasneje, ko zaradi besede nastaneta stiska ali preganjanje, pa so takoj pohujšani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'In ti so tisti, ki so posejani med trnje; tisti, ki slišijo besedo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'in skrbi tega sveta, zapeljivost bogastev in poželenja po drugih stvareh vstopijo, zadušijo besedo in ta postane brezplodna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'In ti so tisti, ki so posejani na dobra tla; takšni, ki slišijo besedo in jo sprejmejo ter obrodijo sad, nekateri trideseternega, nekateri šestdeseternega in nekateri stoternega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'In rekel jim je: »Ali se sveča prinese, da se postavi pod mernik ali pod posteljo? In ali se ne postavi na svečnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Kajti nič ni skrito, kar ne bo jasno pokazano; niti nič ni bilo obdržano tajno, razen da bi postalo znano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Če ima katerikoli človek ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Rekel jim je: »Pazite, kaj poslušate; s kakršno mero merite, tako vam bo odmerjeno; in vam, ki slišite, vam bo dano več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Kajti kdor ima, njemu bo dano; kdor pa nima, bo od njega vzeto celó to, kar ima.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'In rekel je: »Božje kraljestvo je takšno, kot če bi človek v zemljo vrgel seme,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'in bi spal in vstajal ponoči ter podnevi in seme bi pognalo in raslo, da sam ne ve kako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Kajti zemlja sama od sebe prinaša sad; najprej bilko, potem klas in nató polno žita v klasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Toda ko sad obrodi, takoj pošlje srp, kajti prišla je žetev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'In rekel je: »S čim naj primerjamo Božje kraljestvo? Ali s kakšno primerjavo naj ga primerjamo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Podobno je zrnu gorčičnega semena, ki je, ko je posejano v zemljo, manjše od vseh semen, ki so v zemlji;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'toda ko je posejano, zraste in postane večje od vseh zelišč in poganja ven velike mladike, tako da lahko pod njegovo senco prenočuje perjad neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'In z mnogimi takšnimi prispodobami jim je govoril besedo, kakor so jo bili zmožni slišati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Toda brez prispodobe jim ni govoril. Ko pa so bili sami, je svojim učencem pojasnil vse besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'In istega dne, ko je prišel večer, jim reče: »Prepeljimo se na drugo stran.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Ko so množico odpustili, so ga vzeli na ladjo, tako kakor je bil. Z njim pa so bile tam tudi druge majhne ladje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'In vzdignil se je velik vetroven vihar in valovi so udarjali v ladjo, tako, da je bila v kratkem polna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'On pa je bil na zadnjem delu ladje, speč na blazini in zbudili so ga ter mu rekli: »Učitelj, te ne skrbi, da ginemo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'In vstal je, zapretil vetru in rekel morju: »Mir, bodi mirno.« In veter je ponehal in bil je velik mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'In rekel jim je: »Zakaj ste tako boječi? Kako to, da nimate vere?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'In silno so se ga bali in drug drugemu govorili: »Kakšne vrste človek je to, da ga ubogata celó veter in morje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'In prišli so preko, na drugo stran morja, v deželo Géračanov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'In ko je prišel z ladje, ga je takoj srečal tisti iz grobnic, človek z nečistim duhom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'ki je imel svoje prebivališče med grobnicami; in noben človek ga ni mogel zvezati, ne, niti z verigami ne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'zato ker je bil pogosto zvezan z okovi in verigami, pa je verige potrgal narazen in okove razbil na koščke; niti ga noben človek ni mogel obvladati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'In vedno, ponoči in podnevi, je bil po gorah ter v grobnicah in kričal ter samega sebe rezal s kamni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Toda ko je od daleč zagledal Jezusa, je stekel in ga oboževal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'in z močnim glasom zakričal ter rekel: »Kaj imam opraviti s teboj, Jezus, ti Sin najvišjega Boga? Zaklinjam te pri Bogu, da me ne mučiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Kajti rekel mu je: »Pridi ven iz človeka, ti nečisti duh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'In vprašal ga je: »Kakšno je tvoje ime?« On pa je odgovoril, rekoč: »Moje ime je Legija, ker nas je veliko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'In zelo ga je rotil, da jih ne bi poslal proč, ven iz dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Tam je bila torej, blizu gorá, velika čreda svinj, ki so se pasle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'In vsi hudiči so ga rotili, rekoč: »Pošlji nas v svinje, da bomo lahko vstopili vanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Jezus jim je nemudoma dal dovoljenje. In nečisti duhovi so odšli ven ter vstopili v svinje, in čreda je silovito stekla navzdol po strmini v morje (bilo jih je okoli dva tisoč) in so se zadušile v morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'In tisti, ki so pasli svinje, so pobegnili in to povedali v mestu in na deželi. In ti so odšli, da vidijo, kaj je bilo to, kar se je zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'In prišli so k Jezusu ter zagledali tega, ki je bil obseden s hudičem in imel legijo, kako je sedel oblečen in pri zdravi pameti; in bili so prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Tisti, ki so to videli, so jim povedali, kako se je pripetilo temu, ki je bil obseden s hudičem in tudi glede svinj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'In začeli so ga prositi, naj odide iz njihovih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Ko je prišel na ladjo, ga je ta, ki je bil obseden s hudičem, prosil, da bi bil lahko z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Vendar mu Jezus ni dovolil, temveč mu reče: »Pojdi domov k svojim prijateljem in jim povej, kako velike stvari je Gospod storil zate in je imel sočutje do tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'In ta je odšel ter v Deseteromestju začel razglašati, kako velike stvari je Jezus storil zanj, in vsi ljudje so se čudili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Ko je Jezus z ladjo ponovno prešel na drugo stran, se je k njemu zbralo mnogo ljudi; bil pa je blizu morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'In glej, prihajal je eden izmed predstojnikov sinagoge, Jaír po imenu; in ko ga je ta zagledal, je padel k njegovim stopalom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'in ga silno rotil, rekoč: »Moja majhna hčerka leži na točki smrti. Prosim te, pridi in nanjo položi svoje roke, da bo lahko ozdravljena in da bo živela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'In Jezus je odšel z njim in sledilo mu je veliko ljudi ter pritiskalo nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'In neka ženska, ki je imela dvanajst let težavo s krvjo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'in je od mnogih zdravnikov pretrpela mnoge stvari in porabila vse, kar je imela, pa se ni nič izboljšalo, temveč raje postalo huje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'je, ko je slišala o Jezusu, prišla v gnečo za njim in se dotaknila njegove obleke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Kajti rekla je: »Če se lahko samo dotaknem njegovih oblek, bom zdrava.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'In studenec njene krvi je bil nemudoma posušen; in v svojem telesu je začutila, da je bila ozdravljena od te nadloge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Jezus pa je v sebi takoj vedel, da je iz njega odšla moč, se v gneči obrnil in rekel: »Kdo se je dotaknil mojih oblačil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Njegovi učenci pa so mu rekli: »Množico vidiš, ki pritiska nate, pa praviš: ›Kdo se me je dotaknil?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Pogledal je naokoli, da bi videl tisto, ki je storila to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Toda ženska, prestrašena in trepetajoča, ker je vedela, kaj se je v njej zgodilo, je pristopila in padla dol pred njim ter mu povedala vso resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'In rekel ji je: »Hči, tvoja vera te je naredila zdravo; pojdi v miru in bodi ozdravljena od svoje nadloge.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Medtem ko je še govoril, je od hiše predstojnika sinagoge prišel nekdo, ki je rekel: »Tvoja hči je mrtva, zakaj še vedno vznemirjaš Učitelja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Brž ko je Jezus slišal besedo, ki je bila izgovorjena, reče predstojniku sinagoge: »Ne boj se, samo veruj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'In nobenemu človeku ni dovolil, da mu sledi, razen Petru in Jakobu in Janezu, Jakobovemu bratu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'In pride v hišo predstojnika sinagoge in vidi hrup ter te, ki so jokali in silno tarnali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'In ko je vstopil, jim reče: »Zakaj delate ta trušč in jok? Gospodična ni mrtva, temveč spi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'In smejali so se mu do norčevanja. Toda ko jih je vse postavil ven, vzame očeta in mater od gospodične in te, ki so bili z njim in vstopi tja, kjer je ležala gospodična.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'In gospodično je prijel za roko ter ji rekel: »Talíta kumi,« kar je prevedeno: »Gospodična,« rečem ti, »vstani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'In gospodična je nemudoma vstala ter hodila, kajti bila je stara dvanajst let. Oni pa so bili osupli z veliko osuplostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'In strogo jim je naročil, naj noben človek ne izve za to; in velel je, da naj ji bo nekaj dano za jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'In od tam je odšel ven ter prišel v svojo lastno deželo, in njegovi učenci so mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'In ko je prišel šabatni dan, je začel učiti v sinagogi, in mnogi, ki so ga poslušali, so bili osupli, rekoč: »Od kod ima ta človek te besede? In kakšna je ta modrost, ki mu je dana, da so po njegovih rokah storjena celó takšna mogočna dela?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ali ni to tesar, Marijin sin, brat Jakoba in Jozéja in od Juda in Simona? In ali niso njegove sestre tukaj z nami?« In pohujševali so se nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Toda Jezus jim je rekel: »Prerok ni brez spoštovanja, razen v svoji lastni deželi in med svojim lastnim rodom in v svoji lastni hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'In tam ni mogel storiti nobenega mogočnega dela, razen da je svoje roke položil na nekaj bolnih ljudi in jih ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'In čudil se je zaradi njihove nevere. In odšel je naokoli po vaseh ter učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'In k sebi je poklical dvanajstere ter jih začel pošiljati po dva in dva, in dal jim je oblast nad nečistimi duhovi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'in jim zapovedal, da naj na svojo pot ne jemljejo ničesar razen zgolj palice; ne malhe, ne kruha, ne denarja v svoji mošnji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'temveč naj bodo obuti v sandale in naj ne oblečejo dveh plaščev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'In rekel jim je: »V kateremkoli kraju vstopite v hišo, tam ostanite, dokler ne odidete iz tega kraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, '§ Kdorkoli pa vas ne bo sprejel niti vas ne bo poslušal, ko odidete od tam, otresite prah pod vašimi stopali v pričevanje proti njim. Resnično, povem vam: ›Bolj znosno bo za Sódomo in Gomóro na dan sodbe, kakor za to mesto.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'In odšli so ven ter oznanjali, da naj bi se ljudje pokesali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'In izgnali so mnogo hudičev in z oljem mazilili mnoge, ki so bili bolni in jih ozdravili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'In kralj Herod je slišal o njem; (kajti njegovo ime je bilo razglašeno povsod) in rekel: »Da je bil Janez Krstnik obujen od mrtvih in zato se v njem kažejo mogočna dela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Drugi so rekli: »Da je Elija.« Drugi pa so rekli: »Da je prerok ali kakor eden izmed prerokov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Toda ko je Herod slišal o tem, je rekel: »To je Janez, ki sem ga obglavil. Obujen je od mrtvih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Kajti sam Herod je poslal in zgrabil Janeza ter ga zvezal v ječi zaradi Herodiade, žene svojega brata Filipa, ker se je z njo poročil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Kajti Janez je rekel Herodu: »Zate ni zakonito, da imaš ženo svojega brata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Zato je imela Herodiada proti njemu spor in bi ga ubila, toda ni mogla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, '§ kajti Herod se je bal Janeza, ker je vedel, da je bil pravičen človek in svet in ga je spoštoval; in ko ga je poslušal, je storil mnoge stvari, poslušal pa ga je rade volje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Ko pa je prišel primeren dan, da je Herod na svoj rojstni dan pripravil večerjo svojim velikašem, visokim stotnikom in upravnikom posestev Galileje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'in ko je vstopila hči od že omenjene Herodiade in plesala ter ugajala Herodu in tem, ki so sedeli z njim, je kralj rekel gospodični: »Prosi me, karkoli si želiš in ti bom to dal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'In prisegel ji je: »Karkoli me boš prosila, ti bom to dal, do polovice svojega kraljestva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'In odšla je in rekla svoji materi: »Kaj naj prosim?« Ta pa je rekla: »Glavo Janeza Krstnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'In nemudoma je z naglico vstopila h kralju ter prosila, rekoč: »Hočem, da mi v kratkem na velikem pladnju izročiš glavo Janeza Krstnika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'In kralj je bil silno žalosten, vendar je zaradi svoje prisege in zaradi teh, ki so sedeli z njim, ni hotel zavrniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'In kralj je takoj poslal rablja ter ukazal, da se prinese njegova glava; in ta je odšel ter ga v ječi obglavil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'in na velikem pladnju prinesel njegovo glavo ter jo dal gospodični, gospodična pa jo je dala svoji materi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Ko so njegovi učenci slišali o tem, so prišli in vzeli njegovo truplo in ga položili v grobnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'In apostoli so se skupaj zbrali k Jezusu ter mu povedali vse stvari, tako kaj so delali, kakor kaj so učili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'In rekel jim je: »Pridite sami, ločeno, na zapuščen kraj in nekaj časa počijte,« kajti tam so bili mnogi, ki so prihajali in odhajali in niso imeli nobenega prostega časa, niti toliko, da bi jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'In skrivoma so z ladjo odpluli na zapuščen kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Množica pa jih je videla odhajati in mnogi so ga poznali in iz vseh mest so peš tekli tja ter jih prehiteli in skupaj prišli k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Ko pa je Jezus prišel ven, je zagledal mnogo ljudi in bil prevzet s sočutjem do njih, ker so bili kakor ovce, ki nimajo pastirja, in začel jih je učiti mnogo stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Ko pa je dan davno minil, so k njemu prišli njegovi učenci in rekli: »To je zapuščen kraj in sedaj je čas davno potekel;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'pošlji jih proč, da lahko gredo naokoli po deželi in v vasi in si kupijo kruha zase, kajti nič nimajo za jesti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Odgovoril je in jim rekel: »Dajte jim vi jesti.« Oni pa so mu rekli: »Ali naj gremo in kupimo za dvesto denarjev kruha ter jim damo jesti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Reče jim: »Koliko hlebov imate? Pojdite in poglejte.« In ko so vedeli, so rekli: »Pet in dve ribi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'In ukazal jim je, naj se vsi po skupinah posedejo na zeleno travo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'In posedli so se v vrstah, po sto in po petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Ko je vzel pet hlebov in dve ribi, je pogledal gor v nebo in blagoslovil in razlomil hlebe in jih dal svojim učencem, da jih postavijo prednje; in dve ribi je razdelil med njih vse.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'In vsi so jedli in bili nasičeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'In pobrali so dvanajst polnih košar odlomkov in od rib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Teh pa, ki so jedli od hlebov, je bilo okoli pet tisoč mož.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'In svoje učence je nemudoma primoral, da gredo v ladjo in da gredo naprej, na drugo stran, v Betsajdo, medtem ko je on odpustil množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'In ko jih je odpustil, je odšel na goro molit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Ko pa je prišel večer, je bila ladja na sredi morja, on sam pa na kopnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'In videl jih je garati v veslanju, kajti veter jim je bil nasproten. In okoli četrte nočne straže je prihajal k njim, hodil je po morju in bi šel mimo njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Toda ko so ga videli hoditi po morju, so domnevali, da je bil to duh in so zakričali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'kajti vsi so ga videli in so bili zaskrbljeni. On pa je z njimi takoj spregovoril in jim reče: »Bodite dobre volje; jaz sem, ne bojte se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'In vzpel se je k njim na ladjo in veter je ponehal in v sebi so bili zelo osupli, prekomerno in so se čudili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Kajti niso še preudarili čudeža s hlebi, ker je bilo njihovo srce zakrknjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Ko pa so se prepeljali, so prišli v deželo Genezaret in se približali obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'In ko so prišli z ladje, so ga nemudoma spoznali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'in tekli naokoli prek celotnega področja in začeli s seboj nositi v posteljah te, ki so bili bolni, kjer so slišali, da se je nahajal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, '§ In kamorkoli je vstopil, v vasi ali mesta ali deželo, so na ulice polagali bolne in ga rotili, da bi se lahko dotaknili vsaj roba njegove obleke. In tako veliko, kot se ga je dotaknilo, so bili ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Potem so prišli skupaj k njemu farizeji in nekateri izmed pisarjev, ki so prišli iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'In ko so videli nekatere izmed njegovih učencev jesti kruh z omadeževanimi, to se pravi z neumitimi rokami, so našli krivdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Kajti farizeji in vsi Judje ne jedo, razen če si svojih rok pogosto ne umivajo, ker se držijo izročila starešin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'In ko pridejo iz trga, ne jedo, razen če se ne umijejo. In mnogo drugih stvari je, ki so jih sprejeli, da se jih drže, kot umivanje čaš in vrčev, bakrenih posod in miz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Potem so ga farizeji in pisarji vprašali: »Zakaj tvoji učenci ne živijo glede na izročilo starešin, temveč jedo kruh z neumitimi rokami?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Odgovoril je in jim rekel: »Dobro je Izaija prerokoval o vas hinavcih, kakor je pisano: ›Ti ljudje me spoštujejo s svojimi ustnicami, toda njihovo srce je daleč od mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Čeprav me zaman obožujejo, ker za nauke učijo človeške zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ker se z odlaganjem Božje zapovedi na stran držite človeških izročil, kakor je umivanje čaš in vrčev in počnete še mnoge druge takšne stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'In rekel jim je: »Prav dobro zavračate Božjo zapoved, da bi lahko obdržali svoje lastno izročilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Kajti Mojzes je rekel: ›Spoštuj svojega očeta in svojo mater,‹ in: ›Kdorkoli preklinja očeta ali mater, naj življenje konča s smrtjo,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'toda vi pravite: ›Če bo človek rekel svojemu očetu ali materi: ›To je korbán, to se pravi dar, po čemerkoli bi lahko imel korist od mene,‹ bo prost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'In mu nič več ne dovolite, da bi za svojega očeta ali svojo mater karkoli storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'S svojim izročilom, ki ste ga izročili, delate Božjo besedo brez učinka in počnete mnogo takšnih podobnih stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'In ko je k sebi poklical vso množico, jim je rekel: »Vsak izmed vas naj mi prisluhne in razume:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, '›Nič ni zunaj človeka, kar bi ga z vstopanjem vanj lahko omadeževalo, toda besede, ki pridejo iz njega, te so tiste, ki omadežujejo človeka.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Če ima katerikoli človek ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Ko je od množice vstopil v hišo, so ga njegovi učenci vprašali glede prispodobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'In reče jim: »Ali ste tudi vi tako brez razumevanja? Ali ne zaznate, da ga katerakoli stvar, ki od zunaj vstopa v človeka, ta ne more omadeževati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'ker ta ne vstopa v njegovo srce, temveč v trebuh in gre ven v zunanje stranišče, očiščujoč vso hrano?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'In rekel je: »To, kar prihaja iz človeka, to omadežuje človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Kajti od znotraj, iz človekovega srca, izvirajo zle misli, zakonolomstva, prešuštva, umori,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'tatvine, pohlepnost, zlobnost, prevara, pohotnost, hudoben pogled, bogokletje, ponos, nespametnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'vse te zle stvari prihajajo od znotraj in omadežujejo človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'In vstal je od tam ter odšel v meje Tira in Sidóna in vstopil v hišo in hotel, da tega ne bi izvedel noben človek, toda ni mogel ostati skrit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Kajti neka ženska, katere mlada hči je imela nečistega duha, je slišala o njem in prišla ter padla k njegovim stopalom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Ženska je bila Grkinja, Sirofeničanka po rodu, in rotila ga je, da bi iz njene hčere izgnal hudiča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Toda Jezus ji je rekel: »Naj bodo najprej nasičeni otroci, kajti ni primerno vzeti kruha otrokom in ga vreči psom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Ona pa je odgovorila in mu rekla: »Da, Gospod, vendar psi pod mizo jedo od otroških drobtin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'In rekel ji je: »Zaradi tega govora pojdi svojo pot; hudič je izšel iz tvoje hčere.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'In ko je prišla k svoji hiši, je spoznala, da je hudič izšel in svojo hčer [našla] ležečo na postelji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'In spet, ko je odšel iz tirskih in sidónskih pokrajin, je prišel h Galilejskemu morju, skozi sredo krajev Deseteromestja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'In k njemu prinesejo nekoga, ki je bil gluh in je imel motnjo v svojem govoru in rotili so ga, naj nanj položi svojo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'In vzel ga je proč od množice in svoja prsta položil v njegova ušesa in pljunil ter se dotaknil njegovega jezika');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'in zroč k nebu, je vzdihnil ter mu rekel: »Efatá!« to je: »Odpri se.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'In njegova ušesa so se nemudoma odprla in vez njegovega jezika se je sprostila in je jasno govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'In naročil jim je, da naj ne povedo nobenemu človeku, toda bolj, kot jim je naročal, toliko bolj na veliko so to razglašali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'in bili so preko mere osupli, rekoč: »Vse stvari je storil dobro; tako gluhim daje slišati, kakor nemim govoriti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'V tistih dneh, [ko] je bila množica zelo velika in ni imela nič za jesti, je Jezus poklical k sebi svoje učence in jim rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '»Sočutje imam do množice, ker so z menoj sedaj že tri dni, pa nimajo ničesar za jesti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'in če jih pošljem proč k njihovim lastnim hišam tešče, bodo med potjo oslabeli, kajti številni izmed njih so prišli od daleč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'In njegovi učenci so mu odgovorili: »Od kod lahko človek, tukaj v divjini, te ljudi nasiti s kruhom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'In vprašal jih je: »Koliko hlebov imate?« In rekli so: »Sedem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'In zapovedal je množici, da se usede na tla, in vzel je sedem hlebov ter se zahvalil in prelomil ter dal svojim učencem, da jih postavijo prednje in oni so jih postavili pred množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'In imeli so nekaj majhnih rib, in blagoslovil je ter velel, da jih prav tako postavijo pred njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Tako so jedli in bili nasičeni; in od odlomkov hrane, ki je ostala, so pobrali sedem košar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'In teh, ki so jedli, je bilo okoli štiri tisoč; in poslal jih je proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'In s svojimi učenci je nemudoma vstopil na ladjo ter prišel v dalmanútske kraje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'In prišli so farizeji, ter se začeli pričkati z njim in ga skušali in od njega iskali znamenje z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'In v svojem duhu je globoko vzdihnil in rekel: »Zakaj ta rod išče znamenje? Resnično, povem vam: ›Temu rodu ne bo dano nobeno znamenje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'In zapustil jih je ter vstopil na ladjo in ponovno odplul na drugo stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Učenci so torej pozabili vzeti kruh niti s seboj na ladji niso imeli več kakor en hleb.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'In naročil jim je, rekoč: »Pazite, varujte se farizejskega kvasa in Herodovega kvasa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'In med seboj so razpravljali, rekoč: » To je zato, ker nimamo kruha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Ko je Jezus to spoznal, jim reče: »Zakaj razmišljate, ker nimate kruha? Še niste zaznali niti razumeli? Ali imate svoje srce še vedno zakrknjeno?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Imate oči, pa ne vidite? Imate ušesa, pa ne slišite? In ali se ne spominjate?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Ko sem prelomil pet hlebov med pet tisoč, koliko košar, polnih odlomkov, ste pobrali?« Rekli so mu: »Dvanajst.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '»In ko sedem med štiri tisoč, koliko košar, polnih odlomkov, ste pobrali?« In rekli so: »Sedem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'In rekel jim je: »Kako to, da ne razumete?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'In pride v Betsajdo, in k njemu privedejo slepega moža in rotili so ga, da se ga dotakne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'In z roko je prijel slepega moža in ga odvedel iz mesta in ko je pljunil na njegove oči in svoji roki položil nanj, ga je vprašal, ali karkoli vidi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'In ta je pogledal gor ter rekel: »Vidim ljudi kakor drevesa, hodijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Nató je svoje roke ponovno položil na njegove oči in ga pripravil, da pogleda gor, in bil je ozdravljen in razločno videl vsakega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, '§ In poslal ga je proč k njegovi hiši, rekoč: »Niti ne pojdi v mesto niti tega ne povej nikomur v mestu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'In Jezus je odšel ven ter njegovi učenci, v mesta Cezareje Filipove. Med potjo pa je svoje učence vprašal, rekoč jim: »Kdo ljudje pravijo, da sem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Odgovorili so: »Janez Krstnik,« toda nekateri pravijo »Elija,« drugi pa: »Eden izmed prerokov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'In reče jim: »Toda kdo vi pravite, da sem jaz?« In Peter odgovori ter mu reče: »Ti si Kristus.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'In naročil jim je, da naj nobenemu človeku ne povedo o njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'In začel jih je učiti, da mora Sin človekov pretrpeti mnoge stvari in biti zavrnjen od starešin in od visokih duhovnikov in pisarjev in biti ubit ter po treh dneh ponovno vstati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'In ta govor je govoril javno. Peter pa ga je prijel in ga začel oštevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Toda ko se je obrnil okoli in pogledal na svoje učence, je Petra oštel, rekoč: »Spravi se za menoj, Satan, kajti ne posvečaš se stvarem, ki so Božje, temveč stvarem, ki so od ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'In ko je k sebi poklical množico, skupaj s svojimi učenci, jim je rekel: »Kdorkoli hoče priti za menoj, naj se odpove samemu sebi in vzame svoj križ in mi sledi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Kajti kdorkoli hoče rešiti svoje življenje, ga bo izgubil, toda kdorkoli bo izgubil svoje življenje zaradi mene in evangelija, ta isti ga bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, '§ Kajti kaj bo koristilo človeku, če bo pridobil ves svet, izgubil pa svojo lastno dušo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, '§ Ali kaj bo dal človek v zamenjavo za svojo dušo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Kdorkoli se bo torej v tem zakonolomnem in grešnem rodu sramoval mene in mojih besed, tega se bo sramoval tudi Sin človekov, ko pride v slavi svojega Očeta s svetimi angeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'In rekel jim je: »Resnično, povem vam: ›Da bo nekaj od teh, ki stojijo tukaj, ki ne bodo okusili smrti, dokler ne bodo videli Božjega kraljestva priti z močjo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'In po šestih dneh Jezus vzame s seboj Petra in Jakoba in Janeza in jih posebej vodi na visoko goro; in pred njimi je bil preobražen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'In njegova oblačila so postala sijoča, silno bela kakor sneg, tako kot jih noben belivec na zemlji ne more pobeliti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'In prikazal se jim je Elija z Mojzesom; in onadva sta se pogovarjala z Jezusom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, '§ In Peter je odgovoril ter Jezusu rekel: »Učitelj, dobro je za nas, da smo tukaj; in naredimo tri šotore, enega zate in enega za Mojzesa in enega za Elija.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Kajti ni vedel, kaj bi rekel, ker so bili boleče prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'In tam je bil oblak, ki jih je obsenčil in iz oblaka je prišel glas, rekoč: »Ta je moj ljubljeni Sin, njega poslušajte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Nenadoma pa, ko so pogledali naokoli, niso videli nobenega človeka več, razen samo Jezusa, ki je bil z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'In ko so prišli dol z gore, jim je naročil, naj nobenemu človeku ne povedo, kakšne stvari so videli, dokler ne bo Sin človekov vstal od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'In ta govor so zadržali med njimi samimi in drug drugega spraševali, kaj naj bi pomenilo vstati od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'In vprašali so ga, rekoč: »Zakaj pravijo pisarji, da mora najprej priti Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Odgovoril je in jim rekel: »Elija resnično prihaja prvi in obnavlja vse stvari in kako je pisano o Sinu človekovemu, da mora trpeti mnoge stvari ter biti zaničevan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Toda povem vam: ›Da je Elija zares prišel in storili so mu, karkoli so si zahoteli, kakor je pisano o njem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'In ko je prišel k svojim učencem, je okoli njih zagledal veliko množico in pisarje pričkati se z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'In nemudoma, ko so ga zagledali, je bila vsa množica silno osupla ter stekla k njemu, da ga pozdravijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'In pisarje je vprašal: »Kaj se pričkate z njimi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Nekdo iz množice pa je odgovoril in rekel: »Učitelj, k tebi sem privedel svojega sina, ki ima nemega duha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'in kjerkoli ga zgrabi, ga trga in se peni in škripa s svojimi zobmi in hira; in rekel sem tvojim učencem, da naj ga izženejo ven, pa niso mogli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Odgovarja mu in reče: »Oh neverni rod, kako dolgo bom z vami? Doklej vas bom trpel? Pripeljite ga k meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'In pripeljali so ga k njemu; in ko ga je zagledal, ga je duh nemudoma trgal, in padel je na tla ter se penast valjal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'In njegovega očeta je vprašal: »Kako dolgo je že, odkar je ta prišel vanj?« In odgovoril je: »Od otroštva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'In da ga pokonča, ga je pogosto vrgel v ogenj in v vode, toda če lahko karkoli storiš, imej sočutje do nas in nam pomagaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jezus mu je rekel: »Če lahko veruješ, so vse stvari mogoče tistemu, ki veruje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'In otrokov oče je nemudoma zavpil in s solzami rekel: »Gospod, verujem, pomagaj moji neveri.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Ko je Jezus videl, da je množica tekla skupaj, je oštel nečistega duha, rekoč mu: » Ti, nemi in gluhi duh, ukazujem ti, pridi iz njega in ne vstopi več vanj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'In duh je zavpil ter ga hudo zgrabil in prišel iz njega; in bil je kakor nekdo, [ki je] mrtev, tako da so mnogi rekli: »Mrtev je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Toda Jezus ga je prijel za roko in ga dvignil in ta je vstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Ko pa je prišel v hišo, so ga njegovi učenci na samem vprašali: »Zakaj ga mi nismo mogli izgnati ven?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, '§ In rekel jim je: »Ta vrsta ne pride ven z ničimer, razen z molitvijo in postom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'In odšli so od tam ter šli skozi Galilejo, in ni želel, da bi katerikoli človek to izvedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Kajti svoje učence je učil in jim govoril: »Sin človekov je izročen v človeške roke, in ubili ga bodo. In potem, ko bo umorjen, bo tretji dan vstal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Tega govora pa niso razumeli in bali so se ga vprašati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'In prišel je v Kafarnáum. In ko so bili v hiši, jih je vprašal: »Kaj je bilo to, da ste se po poti prerekali med seboj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Vendar so molčali, kajti med potjo so se med seboj prerekali, kdo naj bi bil največji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'In usedel se je, poklical dvanajstere in jim spregovoril: »Če želi katerikoli človek biti prvi, ta isti naj bo zadnji izmed vseh in služabnik vsem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'In vzel je otroka ter ga posadil v sredo mednje, in ko ga je vzel v svoje naročje, jim je rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '»Kdorkoli bo sprejel enega od takšnih otrok v mojem imenu, sprejema mene; in kdorkoli bo sprejel mene, ne sprejema mene, temveč tistega, ki me je poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'In Janez mu je odgovoril, rekoč: »Učitelj, videli smo nekoga v tvojem imenu izganjati hudiče, pa nam ta ne sledi, in smo mu prepovedali, ker nam ne sledi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Vendar je Jezus rekel: »Ne prepovejte mu, kajti nobenega človeka ni, ki bi v mojem imenu storil čudež, da bi lahko brž hudobno govoril o meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Kajti kdor ni proti nam, je na naši strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Kajti kdorkoli vam bo za pitje ponudil čašo vode v mojem imenu, ker pripadate Kristusu, resnično vam povem, ne bo izgubil svoje nagrade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'In kdorkoli bo pohujšal enega od teh malčkov, ki verujejo vame, je bolje zanj, da bi bil okoli njegovega vratu obešen mlinski kamen in bi bil vržen v morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'In če te tvoja roka pohujšuje, jo odsekaj proč; bolje je zate, da vstopiš v življenje pohabljen, kakor imeti dve roki in iti v pekel, v ogenj, ki ne bo nikoli pogašen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'kjer njihov črv ne umre in ogenj ni pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'In če te tvoje stopalo pohujšuje, ga odsekaj proč; bolje je zate, da vstopiš v življenje šepav, kakor imeti dve stopali in biti vržen v pekel, v ogenj, ki ne bo nikoli pogašen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '§ kjer njihov črv ne umre in ogenj ni pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'In če te tvoje oko pohujšuje, ga iztakni ven; bolje je zate, da vstopiš v Božje kraljestvo z enim očesom, kakor biti z dvema očesoma vržen v peklenski ogenj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '§ kjer njihov črv ne umre in ogenj ni pogašen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Kajti vsakdo bo osoljen z ognjem in vsaka žrtev bo osoljena s soljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Sol je dobra, toda če je sol izgubila svojo slanost, s čim jo boste začinili? Imejte sol v sebi in imejte mir drug z drugim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'In vzdignil se je od tam ter po drugi strani Jordana prihajal v judejske kraje; in množica je ponovno krenila k njemu, in kakor je bil navajen, jih je ponovno učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'In k njemu so prišli farizeji ter ga vprašali: »Ali je možu zakonito odsloviti svojo ženo?« ker so ga skušali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'In odgovoril jim je ter rekel: »Kaj vam je zapovedal Mojzes?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Rekli so: »Mojzes je dopustil napisati ločitveni list in [jo] odsloviti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jezus pa je odgovoril in jim rekel: »Zaradi trdote vašega srca vam je napisal ta predpis.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Toda od začetka stvarstva ju je Bog ustvaril moškega in žensko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Zaradi tega razloga bo mož zapustil svojega očeta in mater ter se trdno pridružil k svoji ženi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'in ta dva bosta eno meso. Tako potem nista nič več dva, temveč eno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Kar je torej Bog združil skupaj, naj človek ne loči narazen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'In v hiši so ga njegovi učenci ponovno vprašali o isti zadevi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Rekel jim je: »Kdorkoli bo odslovil svojo ženo in poročil drugo, proti njej zagreši zakonolomstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'In če bo ženska odslovila svojega soproga in bo poročena k drugemu, zagreši zakonolomstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'In k njemu so prinašali mlajše otroke, da bi se jih dotaknil; njegovi učenci pa so ošteli te, ki so jih prinašali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Vendar ko je Jezus to videl, je bil zelo nezadovoljen in jim rekel: »Dovolite majhnim otrokom, da pridejo k meni in ne prepovejte jim, kajti takšnih je Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Resnično, povem vam: ›Kdorkoli Božjega kraljestva ne bo sprejel kakor majhen otrok, ne bo vstopil vanj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'In dvignil jih je v svoje naročje, nanje položil svoji roki in jih blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'In ko je odšel naprej po poti, je nekdo pritekel in pokleknil k njemu ter ga prosil: »Dobri Učitelj, kaj naj storim, da bom lahko podedoval večno življenje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jezus mu je rekel: »Čemu me kličeš dober? Nihče ni dober razen enega, to je Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Zapovedi poznaš: ›Ne zagreši zakonolomstva,‹ ›Ne ubijaj,‹ ›Ne kradi,‹ ›Ne pričaj po krivem,‹ ›Ne goljufaj,‹ ›Spoštuj svojega očeta in mater.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Odgovoril je in mu rekel: »Učitelj, vse to sem obeleževal od svoje mladosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Potem ga je Jezus pogledal, ga ljubil, ter mu rekel: »Ena stvar ti manjka, pojdi svojo pot, prodaj karkoli imaš in daj revnim in imel boš zaklad v nebesih in pridi, vzemi križ ter hodi za menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'In ob tej besedi je bil žalosten ter užaloščen odšel proč, kajti imel je veliko posesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Jezus pa je pogledal naokoli in rekel svojim učencem: »Kako težko bodo tisti, ki imajo bogastva, vstopili v Božje kraljestvo!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'In učenci so bili ob njegovih besedah osupli. Vendar Jezus ponovno odgovarja in jim reče: »Otroci, kako težko je tem, ki zaupajo v bogastva, vstopiti v Božje kraljestvo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Lažje je za kamelo, da gre skozi šivankino uho, kakor bogatašu vstopiti v Božje kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'In bili so prekomerno osupli ter med seboj govorili: »Kdo je potem lahko rešen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'In Jezus, ko pogleda nanje, reče: »Pri ljudeh je to nemogoče, toda ne z Bogom, kajti z Bogom so vse stvari mogoče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Potem mu je Peter začel govoriti: »Glej, vse smo zapustili in ti sledili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jezus pa je odgovoril in rekel: »Resnično, povem vam: ›Nikogar ni, ki je zapustil hišo ali brate ali sestre ali očeta ali mater ali ženo ali otroke ali zemljišča zaradi mene in evangelija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'toda prejel bo stokratno, sedaj, v tem času, hiš in bratov in sester in mater in otrok in zemljišč s preganjanji; in večno življenje v svetu, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Toda mnogi, ki so prvi, bodo zadnji, in zadnji prvi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'In bili so na poti, ki gre gor v Jeruzalem in Jezus je šel pred njimi in bili so osupli in medtem ko so ga spremljali, so bili prestrašeni. In ponovno je vzel dvanajstere ter jim začel pripovedovati, kakšne stvari naj bi se mu pripetile,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'rekoč: »Glejte, mi gremo gor v Jeruzalem in Sin človekov bo izročen visokim duhovnikom in pisarjem in oni ga bodo obsodili na smrt ter ga izročili poganom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'in zasmehovali ga bodo in ga bičali in pljuvali nanj ter ga umorili, toda tretji dan bo ponovno vstal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'In Jakob in Janez, Zebedejeva sinova, sta prišla k njemu, rekoč: »Učitelj, midva hočeva, da nama storiš, karkoli bova prosila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'In rekel jima je: »Kaj hočeta, da bi vama storil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Rekla sta mu: »Usliši naju, da bova lahko sedela v tvoji slavi, eden na tvoji desnici, drugi pa na tvoji levici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Toda Jezus jima je rekel: »Vidva ne vesta, česa prosita. Ali moreta piti iz čaše, iz katere jaz pijem? In biti krščena s krstom, s katerim sem jaz krščen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'In odgovorila sta mu: »Moreva.« Jezus pa jima je rekel: »Vidva bosta zares pila iz čaše, iz katere jaz pijem; in s krstom, s katerim sem jaz krščen, bosta tudi vidva krščena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'toda sedeti na moji desnici in na moji levici, ni moje, da dam, temveč bo dano tistim, ki jim je to pripravljeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'In ko so deseteri to slišali, so postali zelo nezadovoljni z Jakobom in Janezom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Toda Jezus jih je poklical k sebi in jim reče: »Vi veste, da tisti, ki se štejejo, da vladajo nad pogani, izvajajo gospostvo nad njimi, in njihovi velikaši izvajajo oblast nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Toda med vami naj ne bo tako, temveč kdorkoli hoče biti med vami velik, naj bo vaš sluga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'in kdorkoli izmed vas hoče biti glavni, naj bo sluga vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Kajti celo Sin človekov ni prišel, da bi mu služili, temveč, da služi in da svoje življenje daruje v odkupnino za mnoge.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'In prišli so v Jeriho, in ko je s svojimi učenci in velikim številom ljudi odšel iz Jerihe, je slepi Bartimáj, Timájev sin, sedel ob glavni cesti in beračil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'In ko je slišal, da je bil to Jezus Nazarečan, je začel vzklikati ter govoriti: »Jezus, ti Davidov Sin, usmili se me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'In mnogi so ga opozarjali, naj molči, toda še veliko glasneje je vpil: » Ti, Davidov Sin, usmili se me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jezus je obstal in velel, naj ga pokličejo. In poklicali so slepega moža ter mu rekli: »Bodi dobro potolažen, vstani, kliče te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'In ta, ko je odvrgel svojo obleko proč, je vstal in prišel k Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'In Jezus je odgovoril ter mu rekel: »Kaj hočeš, da naj ti storim?« Slepi mož mu je rekel: »Gospod, da bi lahko prejel svoj vid.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'In Jezus mu je rekel: »Pojdi svojo pot; tvoja vera te je naredila zdravega.« In takoj je prejel svoj vid ter sledil Jezusu po poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'In ko so prišli blizu Jeruzalema, k Bétfagi in Betaniji, ob Oljski gori, pošlje naprej dva izmed svojih učencev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'in jima reče: »Pojdita svojo pot v vas pred vama in brž ko bosta vstopila vanjo, bosta našla privezano žrebe, na katerem človek nikoli ni sedel; odvežita ga in ga pripeljita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Če pa bi vama katerikoli človek rekel: ›Čemu to počneta?‹ recita, da ima Gospod potrebo po njem; in on ga bo nemudoma poslal sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'In odšla sta svojo pot ter našla zunaj pri vratih privezano žrebe, na kraju, kjer sta se srečali dve poti in sta ga odvezala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Nekateri izmed tistih, ki so stali tam, pa so jima rekli: »Kaj počneta, da odvezujeta žrebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'In rekla sta jim torej kot je naročil Jezus in pustili so ju oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'In žrebe sta privedla k Jezusu in svoje obleke vrgla nanj in on je sédel nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'In mnogi so svoje obleke razgrnili na pot, drugi pa so z dreves odsekali mladike ter z njimi nastlali pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'In tisti, ki so šli spredaj in tisti, ki so sledili, so vzklikali, rekoč: »›Hozana;‹ blagoslovljen je ta, ki prihaja v imenu Gospodovem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'blagoslovljeno bodi kraljestvo našega očeta Davida, ki prihaja v imenu Gospodovem: ›Hozana na višavah.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'In Jezus je vstopil v Jeruzalem in v tempelj. In ko se je razgledal naokoli po vseh stvareh in je torej prihajal večer, je z dvanajsterimi odšel ven v Betanijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'In naslednji dan, ko so prišli iz Betanije, je bil lačen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'In ko je daleč stran zagledal figovo drevo, ki je imelo listje, je prišel, če bi morda lahko karkoli našel na njem. In ko je prišel k njemu, ni našel nič razen listov, kajti ni bil še čas za fige.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'In Jezus je odgovoril ter mu rekel: »Nihče naj od tebe odslej nikoli več ne jé sadu.« In njegovi učenci so to slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'In prišli so v Jeruzalem in Jezus je odšel v tempelj ter začel izganjati te, ki so v templju prodajali in kupovali, menjalcem denarja pa je prevrnil mize in sedeže teh, ki so prodajali golobice');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'in ni dovolil, da bi katerikoli človek skozi tempelj nosil kakršnokoli posodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'In učil jih je, rekoč: »Ali ni pisano: ›Moja hiša se bo od vseh narodov imenovala hiša molitve?‹ Vi pa ste jo naredili za brlog razbojnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Pisarji in visoki duhovniki pa so to slišali ter iskali, kako bi ga lahko pokončali, kajti bali so se ga, ker je bila vsa množica osupla nad njegovim naukom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'In ko je prišel večer, je odšel iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'In zjutraj, ko so šli mimo, so videli figovo drevo posušeno iz korenin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Peter pa se spomni in mu reče: »Učitelj, glej, figovo drevo, ki si ga preklel, je ovenelo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'In Jezus jim odgovarja, rekoč: »Imejte vero v Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Kajti resnično, povem vam: ›Da kdorkoli bo rekel tej gori: ›Prestavi se in bodi vržena v morje‹ in v svojem srcu ne bo dvomil, temveč bo veroval, da se te besede, ki jih reče, pripetijo, bo imel, karkoli reče.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Zatorej vam pravim: ›Katerekoli stvari si želite, ko molite, verujte, da jih prejemate in imeli jih boste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'In ko vstanete k molitvi, odpustite, če imate kaj proti komu, da vam tudi vaš Oče, ki je v nebesih, lahko odpusti vaše prekrške.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '§ Toda če vi ne odpustite, tudi vaš Oče, ki je v nebesih, ne bo odpustil vaših prekrškov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'In ponovno so prišli v Jeruzalem in ko je hodil po templju, so prišli k njemu visoki duhovniki in pisarji in starešine');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'ter mu rekli: »S kakšno oblastjo delaš te stvari? In kdo ti je dal to oblast, da delaš te stvari?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jezus je odgovoril in jim rekel: »Tudi jaz vas bom vprašal neko vprašanje in odgovorite mi in povedal vam bom, s kakšno oblastjo delam te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Janezov krst, ali je bil ta iz nebes ali od ljudi? Odgovorite mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'In med seboj so razpravljali, rekoč: »Če bomo rekli: ›Iz nebes,‹ bo rekel: ›Zakaj mu potem niste verovali?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Toda če bomo rekli: ›Od ljudi,‹ so se bali ljudstva, kajti vsi ljudje so šteli Janeza, da je bil zares prerok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'In odgovorili so ter rekli Jezusu: »Ne moremo povedati.« Jezus pa jim odgovarja, rekoč: »Niti vam jaz ne povem, s kakšno oblastjo delam te stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'In začel jim je govoriti s prispodobami. » Neki človek je zasadil vinograd in okoli njega postavil ograjo ter izkopal prostor za vinsko kad in zgradil stolp ter to prepustil poljedelcem in odšel v daljno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'In ob primernem času je k poljedelcem poslal služabnika, da bi od poljedelcev lahko prejel sad od vinograda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Oni pa so ga zgrabili in ga pretepli ter ga odgnali praznega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'In ponovno je poslal k njim drugega služabnika; in nanj so metali kamne in ga ranili na glavi ter ga spodili nespodobno obravnavanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'In ponovno je poslal drugega; in so ga ubili in mnoge druge; nekatere so pretepli, druge pa ubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Imel je torej še enega sina, svojega srčno ljubljenega, tudi njega je zadnjega poslal k njim, rekoč: ›Mojega sina bodo spoštovali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Toda tisti poljedelci so med seboj govorili: ›Ta je dedič; pridite, ubijmo ga in dediščina bo naša.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'In vzeli so ga in ga ubili ter ga vrgli iz vinograda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Kaj naj torej stori gospodar vinograda? Prišel bo in uničil poljedelce in vinograd dal drugim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'In ali niste brali tega pisma: »Kamen, ki so ga graditelji zavrnili, je postal glava vogalu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'to je bilo Gospodovo delo in to je čudovito v naših očeh?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'In prizadevali so si, da ga primejo, toda bali so se množice, kajti vedeli so, da je prispodobo govoril zoper njih; in pustili so ga ter odšli svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'In k njemu so poslali nekatere izmed farizejev in herodovcev, da ga ujamejo v njegovih besedah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'In ko so prišli, mu rečejo: »Učitelj, vemo, da si pošten in se ne oziraš na človeka, kajti ne oziraš se na zunanjost ljudi, temveč v resnici učiš Božjo pot: ›Ali je zakonito dajati cesarju davek ali ne?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Ali naj dajemo ali naj ne dajemo?‹« Ker pa je vedel za njihovo hinavščino, jim je rekel: »Kaj me skušate? Prinesite mi kovanec, da ga lahko pogledam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'In prinesli so ga. On pa jim reče: »Čigava je ta podoba in napis?« In rekli so mu: »Cesarjeva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Jezus jim je odgovoril, rekoč: »Povrnite cesarju stvari, ki so cesarjeve, Bogu pa stvari, ki so Božje.« In so se mu čudili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Potem so k njemu prišli saduceji, ki pravijo, da ni vstajenja; in vprašali so ga, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '»Učitelj, Mojzes nam je zapisal: ›Če komu umre brat in za seboj zapusti svojo ženo, pa ne zapusti otrok, da naj njegov brat vzame njegovo ženo in svojemu bratu obudi seme.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Bilo je torej sedem bratov; in prvi je vzel ženo in umirajoč ni zapustil semena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'In vzel jo je drugi ter umrl [in] niti on ni zapustil semena in tretji prav tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'In sedem jo je imelo, pa niso zapustili semena. Zadnja od vseh je umrla tudi ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Ob vstajenju torej, ko bodo vstali, čigava žena bo od teh? Kajti sedem jo je imelo za ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jezus jim je odgovoril, rekoč: »Ali se ne motite zato, ker ne poznate [ne] pisem niti Božje moči?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Kajti ko bodo vstali od mrtvih, se ne bodo niti poročali niti ne bodo dane v zakon; temveč so kakor angeli, ki so v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'In glede mrtvih, da bodo obujeni; kaj niste brali v Mojzesovi knjigi, kako mu je Bog govoril v grmu, rekoč: ›Jaz sem Bog Abrahamov in Bog Izakov in Bog Jakobov?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'On ni Bog mrtvih, temveč Bog živih. Torej delate veliko napako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'In prišel je eden izmed pisarjev in jih slišal skupaj razmišljati in ker je dojel, da jim je dobro odgovoril, ga je vprašal: »Katera je prva izmed vseh zapovedi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jezus mu je odgovoril: »Prva izmed vseh zapovedi je: ›Poslušaj, oh Izrael: ›Gospod, naš Bog, je edini Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, '§ In ljubil boš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo in z vsem svojim mišljenjem in z vso svojo močjo;‹‹ to je prva zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Druga pa je podobna, namreč ta: ›Ljubi svojega bližnjega kakor samega sebe.‹ Nobena druga zapoved ni večja kakor ti [dve].«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'In pisar mu je rekel: »Dobro, Učitelj, povedal si resnico, kajti samo en Bog je; in ni drugega razen njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, '§ In ljubiti njega z vsem srcem in z vsem razumevanjem in z vso dušo in z vso močjo in ljubiti svojega bližnjega kakor samega sebe, je več kakor vse žgalne daritve in žrtvovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Ko je Jezus videl, da je razumno odgovoril, mu je rekel: »Nisi daleč od Božjega kraljestva.« In nató se mu nihče ni drznil zastaviti kakršnegakoli vprašanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'In Jezus je, medtem ko je učil v templju, odgovoril in rekel: »Kako pravijo pisarji, da je Kristus Davidov Sin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Kajti sam David je po Svetem Duhu rekel: › Gospod je rekel mojemu Gospodu: ›Sédi na mojo desnico, dokler ne naredim tvojih sovražnikov za tvojo pručko.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David mu torej sam reče Gospod in od kod je on potem njegov sin?« In preprosto ljudstvo ga je rade volje poslušalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'In v svojem nauku jim je rekel: »Pazite se pisarjev, ki radi hodijo v dolgih oblačilih in imajo radi pozdrave na trgih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'in vodilne sedeže v sinagogah in najpomembnejša mesta na praznovanjih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'ki vdovam požirajo hiše in za pretvezo delajo dolge molitve; ti bodo prejeli večjo obsodbo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'In Jezus je sedel nasproti zakladnici in gledal, kako množica meče denar v zakladnico; in mnogi, ki so bili bogati, so veliko vrgli vanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Prišla pa je neka siromašna vdova in vanjo vrgla dva kovanca, kar je en novčič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'K sebi je poklical svoje učence in jim reče: »Resnično, povem vam: ›Da je ta siromašna vdova vrgla vanjo več kakor vsi, ki so metali v zakladnico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'kajti vsi ti so metali od svojega obilja, toda ona je od svojega siromaštva vrgla vanjo vse, kar je imela, celó ves svoj dohodek.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'In ko je odšel iz templja, mu eden izmed njegovih učencev reče: »Učitelj, glej kakšne vrste kamnov in kakšne zgradbe so tukaj!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'In Jezus mu odgovori ter reče: »Te velike stavbe gledaš? Tam ne bo ostal en kamen na drugem, ki ne bi bil zrušen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'In ko je sedèl na Oljski gori, nasproti templju, so ga Peter in Jakob in Janez ter Andrej na samem vprašali:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '»Povej nam, kdaj bodo te stvari? In kakšno bo znamenje, ko se bodo vse te besede dopolnile?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'In Jezus jim je odgovoril ter začel govoriti: »Pazite, da vas katerikoli človek ne prevara,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'kajti mnogi bodo prišli v mojem imenu, rekoč: ›Jaz sem Kristus ‹ in bodo mnoge prevarali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Ko pa boste slišali o vojnah in govorice o vojnah, ne bodite zaskrbljeni, kajti takšne stvari brezpogojno bodo, toda ne bo še konec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Kajti narod se bo dvignil proti narodu in kraljestvo proti kraljestvu in potresi bodo na raznih krajih in lakote bodo ter nevšečnosti; te so začetek bridkosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Toda pazite se, kajti izročali vas bodo sodiščem in v sinagogah boste pretepeni in zaradi mene boste privedeni pred vladarje in kralje, v pričevanje proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Najprej pa se mora evangelij razglasiti med vsemi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Toda ko vas bodo vodili in izročali, ne premišljujte vnaprej kaj boste govorili niti ne delajte naklepov, temveč karkoli vam bo v tej uri dano, to govorite, kajti to niste vi, ki govorite, temveč Sveti Duh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Brat bo torej brata izdajal v smrt in oče sina; in otroci bodo vstajali zoper svoje starše ter jim povzročali, da bodo usmrčeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'In zaradi mojega imena boste osovraženi od vseh ljudi, toda kdor bo vztrajal do konca, ta isti bo rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, '§ Toda ko boste videli ogabnost opustošenja, o kateri govori prerok Daniel, stati, kjer ne bi smela, (naj tisti, ki bere, razume) takrat naj tisti, ki so v Judeji, bežijo v gore;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'in naj tisti, ki je na hišni strehi, ne gre dol v hišo niti ne vstopi vanjo, da iz svoje hiše karkoli vzame;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'in naj se tisti, ki je na polju, ne obrne ponovno nazaj, da vzame svojo obleko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Toda gorje tem, ki so z otrokom in tem, ki v tistih dneh dojijo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'In molíte, da vaš pobeg ne bo pozimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Kajti v teh dneh bo stiska, kakršne ni bilo od začetka stvarstva, ki ga je Bog ustvaril, do tega časa niti je ne bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'In razen če Gospod ne bi skrajšal teh dni, ne bi bilo rešeno nobeno meso, toda zaradi izvoljenih, ki jih je izbral, je dneve skrajšal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'In če vam katerikoli človek tedaj reče: ›Glej! Tukaj je Kristus\' ali: ›Glej, tam je,‹ mu ne verjemite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Kajti vstali bodo lažni Kristusi in lažni preroki in prikazovali bodo znamenja in čudeže, da zapeljejo, če bi bilo mogoče, celó izvoljene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Toda pazite se, glejte, napovedal sem vam vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Toda v tistih dneh, po tisti stiski, bo sonce otemnelo in luna ne bo dajala svoje svetlobe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'in zvezde neba bodo padale in moči, ki so na nebu, se bodo tresle.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'In tedaj bodo videli Sina človekovega prihajati na oblakih z veliko močjo in slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'In potem bo poslal svoje angele in bo zbral skupaj svoje izvoljene iz štirih vetrov, od skrajnega dela zemlje do skrajnega dela neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Naučite se torej prispodobe o figovem drevesu: ›Kadar je njegova veja še mlada in poganja liste, veste, da je poletje blizu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Tudi vi na podoben način, ko boste videli, da se te stvari dogajajo, védite, da je to blizu, celó pri vratih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Resnično, povem vam, da ta rod ne bo prešel, dokler se vse te stvari ne zgodijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Nebo in zemlja bosta minila, toda moje besede ne bodo minile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Toda za tisti dan in tisto uro ne ve nihče, niti angeli ne vedo, ki so na nebu, niti ne Sin, temveč Oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, '§ Pazite se, bedite in molíte, kajti ne veste, kdaj je čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Kajti Sin človekov je kakor človek, ki je šel na dolgo pot, ki je zapustil svojo hišo in svojim služabnikom dal oblast in vsakemu človeku svoje delo, vratarju pa je naročil, naj bedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Čujte torej, kajti ne veste, kdaj prihaja hišni gospodar, zvečer ali opolnoči ali ob petelinjem petju ali zjutraj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'da vas ob nenadnem prihodu ne najde spečih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'In kar pravim vam, pravim vsem: ›Čujte.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Dva dni kasneje je bil praznik pashe in nekvašenega kruha. In visoki duhovniki in pisarji so si prizadevali, kako bi ga lahko s prebrisanostjo prijeli in ga usmrtili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Vendar so rekli: »Ne na prazničen dan, da ne bi bilo vstaje med ljudmi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'In ko je bil v Betaniji, v hiši Simona gobavca, medtem ko je sedel pri obedu, je prišla ženska, ki je imela alabastrno škatlo zelo dragocenega mazila iz narde; in strla škatlo ter jo izlila na njegovo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'In tam so bili nekateri, ki so imeli v sebi ogorčenje in rekli: »Čemu je bila narejena ta potrata mazila?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Kajti lahko bi bilo prodano za več kakor tristo denarjev in dano revnim.« In godrnjali so zoper njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jezus pa je rekel: »Pustite jo pri miru. Zakaj jo nadlegujete? Na meni je storila dobro delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Kajti uboge imate vedno med seboj in kadarkoli želite, jim lahko storite dobro, toda mene nimate vedno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Naredila je, kar je lahko; prišla je vnaprej, da moje telo mazili za pokop.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Resnično, povem vam: ›Kjerkoli se bo ta evangelij oznanjal po vsem svetu, se bo tudi to, kar je ona storila, govorilo njej v spomin.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Juda Iškarijot, eden izmed dvanajsterih, pa je odšel k visokim duhovnikom, da bi jim ga izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Ko so oni to slišali, so bili veseli in so mu obljubili, da mu dajo denar. In iskal je, kako bi ga lahko ob priložnosti izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'In prvi dan nekvašenega kruha, ko so zaklali pashalno jagnje, so mu njegovi učenci rekli: »Kam hočeš, da gremo in pripravimo, da boš lahko jedel pashalno jagnje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'In pošlje dva izmed svojih učencev ter jima reče: »Pojdita v mesto in tam vaju bo srečal mož, ki nese lončen vrč vode. Sledita mu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'In kjerkoli bo vstopil, recita hišnemu očetu: ›Učitelj pravi: ›Kje je soba za goste, kjer bom s svojimi učenci jedel pashalno jagnje?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'In pokazal vama bo veliko zgornjo sobo, opremljeno in pripravljeno; tam pripravita za nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'In njegova učenca sta odšla naprej ter prišla v mesto in našla, kakor jima je rekel; in pripravila sta pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'In zvečer je prišel z dvanajsterimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'In ko so se usedli ter jedli, je Jezus rekel: »Resnično, povem vam: ›Eden izmed vas, ki jé z menoj, me bo izdal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, '§ Postajali pa so žalostni in mu drug za drugim govorili: ›Ali sem jaz?‹ in drugi je rekel: ›Ali sem jaz?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Odgovoril je in jim rekel: »Eden izmed dvanajsterih je, ki z menoj pomaka v skledo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Sin človekov zares gre, kakor je pisano o njem, toda gorje tistemu človeku, po katerem je bil Sin človekov izdan! Dobro bi bilo za tega človeka, če se nikoli ne bi rodil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, '§ In ko so pojedli, je Jezus vzel kruh in blagoslovil in ga razlomil in jim dal ter rekel: »Vzemite, jejte, to je moje telo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'In vzel je čašo in ko se je zahvalil, jim jo je dal in vsi so pili iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, '§ In rekel jim je: »To je moja kri nove zaveze, ki se preliva za mnoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Resnično, povem vam: ›Nič več ne bom pil od sadu vinske trte do tistega dne, ko bom pil novega v Božjem kraljestvu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'In ko so odpeli hvalnico, so odšli ven na Oljsko goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, '§ In Jezus jim reče: »Vsi se boste to noč pohujšali zaradi mene, kajti pisano je: ›Udaril bom pastirja in ovce se bodo razkropile.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Toda potem, ko bom obujen, bom pred vami šel v Galilejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Toda Peter mu je rekel: »Četudi se bodo vsi pohujšali, se vendarle jaz ne bom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jezus pa mu reče: »Resnično, povem ti: ›Da me boš ta dan, celó v tej noči, preden petelin dvakrat zapoje, trikrat zatajil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Toda on je še bolj silovito govoril: »Če naj bi umrl s teboj, te na noben način ne bom zatajil.« Prav tako so govorili tudi vsi drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'In prišli so na kraj, ki je bil imenovan Getsemani. In svojim učencem reče: »Sedíte tukaj, dokler bom molil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'In s seboj vzame Petra in Jakoba in Janeza in postajal je boleče prepaden in zelo potrt');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'in jim reče: »Moja duša je silno žalostna do smrti. Zadržujte se tukaj in bedite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'In odšel je malce naprej ter padel na tla in molil, če bi bilo mogoče, da gre ta ura mimo njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'In rekel je: »Aba, Oče, tebi so vse stvari mogoče. To čašo odvzemi od mene, vendar ne kar jaz hočem, temveč kar ti hočeš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'In pride ter jih najde speče in reče Petru: »Simon, spiš? Nisi mogel eno uro bedeti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Bedite in molíte, da ne bi vstopili v skušnjavo. Duh je resnično voljan, toda meso je šibko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'In ponovno je odšel proč ter molil in govoril iste besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'In ko se je vrnil, jih je ponovno našel speče (kajti njihove oči so bile težke) niti niso vedeli, kaj naj mu odgovorijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'In pride tretjič ter jim reče: »Spite torej in vzemite si svoj počitek; dovolj je, ura je prišla; glejte, Sin človekov je izdan v roke grešnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Vstanite, pojdimo; glejte, tisti, ki me izdaja, je blizu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Medtem pa, ko je še govoril, takoj pride Juda, eden izmed dvanajsterih in z njim velika množica z meči in palicami od vélikih duhovnikov in pisarjev in starešin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'In tisti, ki ga je izdal, jim je dal znak, rekoč: »Kogarkoli bom poljubil, ta isti je on; primite ga in ga varno odvedite proč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, '§ In brž, ko je prišel, je nemudoma šel k njemu in reče: »Učitelj, učitelj;« in ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Oni pa so svoje roke položili nanj ter ga prijeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Eden izmed tistih, ki je stal poleg, pa je izvlekel meč in udaril služabnika vélikega duhovnika ter mu odsekal uho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'In Jezus je odgovoril ter jim rekel: »Ali ste prišli ven, da me primete kakor zoper tatu, z meči in s palicami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Dnevno sem bil z vami v templju in poučeval, pa me niste prijeli, toda pisma morajo biti izpolnjena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'In vsi so ga zapustili ter pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Sledil pa mu je nek mladenič, ki je imel okoli svojega nagega telesa ogrnjeno laneno oblačilo; in mladeniča so zgrabili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'ta pa je pustil laneno oblačilo in nag pobegnil od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'In Jezusa so odvedli k vélikemu duhovniku; in z njim so bili zbrani vsi visoki duhovniki in starešine in pisarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'In Peter mu je sledil od daleč, celó v palačo vélikega duhovnika; in sedèl je s služabniki ter se grel pri ognju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'In visoki duhovniki in ves véliki zbor so iskali pričevanje zoper Jezusa, da ga usmrté, pa niso našli nobenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Kajti mnogo jih je krivo pričalo proti njemu, toda njihova pričevanja se niso ujemala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'In tam so vstali nekateri in krivo pričali proti njemu, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '»Slišali smo ga reči: ›Uničil bom ta tempelj, ki je narejen z rokami in v treh dneh bom zgradil novega, narejenega brez rok.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Toda niti tako se njihova pričevanja niso ujemala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Véliki duhovnik pa je vstal, [stopil] v sredo in vprašal Jezusa, rekoč: »Nič ne odgovarjaš? Kaj je to, kar ti pričajo zoper tebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Vendar je ohranil svoj mir in ni nič odgovoril. Véliki duhovnik ga je ponovno vprašal in mu rekel: »Ali si ti Kristus, Sin Blagoslovljenega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'In Jezus je rekel: »Jaz sem, in videli boste Sina človekovega sedeti na desnici moči in prihajati na oblakih neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Tedaj je véliki duhovnik raztrgal svoja oblačila in reče: »Kaj nam je treba nadaljnjih prič?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Slišali ste bogokletje, kaj mislite?« In vsi so ga obsodili, da je kriv smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Nekateri pa so začeli pljuvati nanj in zakrivati njegov obraz ter ga klofutati in mu govoriti: »Prerokuj.« Služabniki pa so ga udarjali z dlanmi svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'In ko je bil Peter spodaj v palači, pride ena izmed služabnic vélikega duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'In ko je videla Petra, kako se greje, ga je pogledala in rekla: »In tudi ti si bil z Jezusom Nazarečanom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Vendar je zanikal, rekoč: »Ne vem niti ne razumem kaj praviš.« In odšel je ven v preddverje, petelin pa je zakikirikal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'In služkinja ga je ponovno videla in začela govoriti tem, ki so stali poleg: »Ta je eden izmed njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, '§ On pa je ponovno zanikal. In malce kasneje so tisti, ki so stali poleg, ponovno rekli Petru: »Zagotovo si eden izmed njih, kajti Galilejec si in tvoje narečje se ujema k temu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Vendar je začel preklinjati in prisegati, rekoč: »Ne poznam tega človeka, o katerem govorite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'In petelin je drugič zapel. Peter pa se je spomnil besede, ki mu jo je rekel Jezus: »Preden bo petelin dvakrat zapel, me boš trikrat zatajil.« Ko pa je o tem premišljeval, je zajokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'In takoj zjutraj so imeli visoki duhovniki posvet s starešinami in pisarji ter celotnim vélikim zborom in zvezali Jezusa in ga odvedli proč ter ga izročili Pilatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'In Pilat ga je vprašal: »Ali si ti Kralj Judov?« In odgovoril je ter mu rekel: »Ti praviš to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'In visoki duhovniki so ga obtožili mnogih stvari. Toda nič ni odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'In Pilat ga je ponovno vprašal, rekoč: »Nič ne odgovarjaš? Glej, koliko stvari pričujejo zoper tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Vendar Jezus še vedno ni nič odgovoril, tako da se je Pilat čudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Torej na ta praznik jim je izpustil enega jetnika, kateregakoli so želeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Tam pa je bil nekdo, imenovan Baraba, ki je ležal zvezan s temi, ki so z njim storili upor in ki je v uporu zagrešil umor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'In množica je na glas kričala in začela zahtevati, da stori, kakor jim je vedno storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Toda Pilat jim je odgovoril, rekoč: »Hočete, da vam izpustim Kralja Judov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Kajti vedel je, da so mu ga visoki duhovniki izročili iz zavisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Toda visoki duhovniki so napeljali množico, da naj jim raje izpusti Baraba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilat pa je odgovoril in jim ponovno rekel: »Kaj potem hočete, da naj storim tistemu, ki ga imenujete Kralj Judov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'In ponovno so zavpili: »Križaj ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Potem jim je Pilat rekel: »Zakaj, kakšno zlo je storil?« Oni pa so še bolj silno vpili: »Križaj ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'In tako jim je Pilat, voljan ustreči množici, izpustil Baraba in ko je prebičal Jezusa, ga je izročil, da bi bil križan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'In vojaki so ga odvedli proč v dvorano, imenovano Praetorium in sklicali vso četo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'In oblekli so ga s škrlatom in spletli krono iz trnja ter jo nadeli na njegovo glavo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'in ga začeli pozdravljati: »Pozdravljen, Kralj Judov!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'In s trstom so ga udarjali po glavi in pljuvali nanj in ko so upogibali svoja kolena, so ga oboževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'In ko so ga zasmehovali, so z njega sneli škrlat in nanj nadeli njegova lastna oblačila ter ga odvedli ven, da ga križajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Prisilili pa so nekega Simona Cirenca, Aleksandrovega in Rufovega očeta, ki je šel mimo in prihajal iz dežele, da nese njegov križ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'In privedli so ga na kraj Golgota, kar je prevedeno: ›Kraj lobanje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'In dali so mu za piti vina, pomešanega z miro, toda ni ga sprejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'In ko so ga križali, so razdelili njegove obleke in zanje metali žreb, kaj naj bi vsak mož vzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'In bila je tretja ura, oni pa so ga križali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'In napis njegove obtožbe je bil napisan nad njim: KRALJ JUDOV.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'In z njim so križali dva tatova; enega na njegovi desni roki, drugega pa na njegovi levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '§ In pismo je bilo izpolnjeno, ki pravi: »In bil je prištet skupaj s prestopniki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Tisti pa, ki so hodili mimo, so se mu posmehovali in zmajevali s svojimi glavami ter govorili: »Ah, ti, ki uničiš tempelj in ga v treh dneh zgradiš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'reši samega sebe in pridi dol s križa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Podobno so ga zasmehovali tudi visoki duhovniki in s pisarji med seboj govorili: »Druge je rešil; sebe ne more rešiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Naj se Kristus, Izraelov Kralj, torej spusti s križa, da bomo lahko videli in verovali.« Ta dva, ki sta bila križana z njim, pa sta ga zasramovala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'In ko je prišla šesta ura, je bila tema čez vso deželo do devete ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Ob deveti uri pa je Jezus z močnim glasom zavpil, rekoč: »Eloí, Eloí, lemá sabahtáni?« kar je prevedeno: »Moj Bog, moj Bog, zakaj si me zapustil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Nekateri izmed teh, ki so stali poleg, pa so, ko so to slišali, rekli: »Glejte, Elija kliče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'In nekdo je stekel ter celotno gobo napojil s kisom in jo nataknil na trst in mu dal piti, rekoč: »Pustite pri miru; poglejmo, ali bo prišel Elija, da ga sname dol.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'In Jezus je z močnim glasom zavpil in izročil duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'In tempeljsko zagrinjalo se je raztrgalo na dvoje od vrha do tal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Ko je stotnik, ki je stal poleg, njemu nasproti, videl, da je tako zavpil in izročil duha, je rekel: »Resnično, ta človek je bil Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Tam so bile tudi ženske, ki so gledale od daleč; med katerimi je bila Marija Magdalena in Marija, mater Jakoba mlajšega in od Jozéja in Salóma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, '(ki so mu, ko je bil v Galileji, tudi sledile in mu služile) in mnoge druge ženske, ki so z njim prišle gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'In sedaj, ko je prišel večer, ker je bila priprava, to je dan pred šabat,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'je Jožef iz Arimateje, častitljiv svetovalec, ki je prav tako pričakoval Božje kraljestvo, prišel in pogumno stopil k Pilatu ter prosil za Jezusovo telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'In Pilat se je začudil, da je bil že mrtev; in ko je k sebi poklical stotnika, ga je vprašal ali je bil že nekaj časa mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'In ko je od stotnika to izvedel, je telo poklonil Jožefu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'In ta je kupil tanko laneno platno in ga snel ter zavil v laneno platno in ga položil v mavzolej, ki je bil izklesan iz skale in k vratom mavzoleja zavalil kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Marija Magdalena in Marija, Jozéjeva mati, pa sta opazovali, kam je bil položen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Ko je šabat minil, so Marija Magdalena in Marija, Jakobova mati in Salóma kupile prijetne dišave, da bi lahko prišle ter ga pomazilile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'In zelo zgodaj zjutraj, prvega dne v tednu, so ob sončnem vzhodu prišle k mavzoleju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'In med seboj so govorile: »Kdo nam bo odvalil kamen proč izpred vrat mavzoleja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Ko pa so pogledale, so videle, da je bil kamen odvaljen proč, kajti bil je zelo velik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'In vstopajoč v mavzolej, so zagledale mladeniča, ki je sedel na desni strani, oblečenega v dolgo belo obleko; in bile so zgrožene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'On pa jim reče: »Ne bodite zgrožene. Ve iščete Jezusa Nazarečana, ki je bil križan. Obujen je, ni ga tukaj. Poglejte prostor, kamor so ga položili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Toda pojdite svojo pot, povejte njegovim učencem in Petru, da gre pred vami v Galilejo; tam ga boste videli, kakor vam je rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'In hitro so odšle ven in pobegnile od mavzoleja, kajti trepetale so in bile osuple niti niso ničesar povedale nobenemu človeku, kajti bile so prestrašene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Ko je torej Jezus zgodaj prvega dne v tednu vstal, se je najprej prikazal Mariji Magdaleni, iz katere je izgnal sedem hudičev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'In odšla je ter povedala tem, ki so bili z njim, ki so žalovali in jokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'In ko so slišali, da je bil živ in da ga je videla, niso verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Nató se je v drugi obliki prikazal dvema izmed njih, ki sta hodila in šla na deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'In odšla sta ter to povedala preostalim. Niti njima niso verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Potem se je prikazal enajsterim, ko so sedeli pri obedu in jih oštel zaradi njihove nevere in trdote srca, ker niso verjeli tem, ki so ga videli potem, ko je bil obujen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'In rekel jim je: »Pojdite po vsem svetu in oznanite evangelij vsakemu ustvarjenemu bitju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kdor veruje in je krščen, bo rešen; toda kdor ne veruje, bo obsojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'In ta znamenja bodo spremljala tiste, ki verujejo: ›V mojem imenu bodo izganjali hudiče, govorili bodo z novimi jeziki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'dvigali bodo kače in če popijejo kakršnokoli smrtonosno stvar, jim ta ne bo škodila; polagali bodo roke na bolne in ti bodo ozdraveli.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Tako je bil potem, ko jim je Gospod govoril, sprejet gor v nebo in je sédel na Božjo desnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Oni pa so šli naprej ter povsod oznanjali in Gospod je delal z njimi in besedo potrjeval s spremljajočimi znamenji. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Ker so že mnogi vzeli v roko, da po vrsti uredijo izjavo o teh stvareh, ki se najbolj gotovo verjamejo med nami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'celo kakor so nam jih izročili [tisti], ki so bili od začetka priče in služabniki besede,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'se je tudi meni zdelo dobro, od samega začetka imeti popolno razumevanje o vseh stvareh, da tebi, nadvse odlični Teófil, napišem po vrsti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'da lahko spoznaš zanesljivost o teh besedah, o katerih si bil poučen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'V dneh Heroda, judejskega kralja, je bil nek duhovnik, imenovan Zaharija, iz Abíjeve skupine, in njegova žena je bila izmed Aronovih hčera in njeno ime je bilo Elizabeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Oba sta bila pravična pred Bogom in sta brez krivde živela po vseh Gospodovih zapovedih in odredbah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Ker je bila Elizabeta jalova nista imela nobenega otroka in oba sta bila zelo zvrhana v letih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'In pripetilo se je, medtem ko je pred Bogom opravljal duhovniško službo, po vrstnem redu svoje skupine,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'glede na navado duhovniške službe, je bil na njem žreb, da zažge kadilo, ko je odšel v Gospodov tempelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Celotna množica ljudi pa je ob času zažiganja kadila zunaj molila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'In prikazal se mu je Gospodov angel, stoječ na desni strani kadilnega oltarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Ko pa ga je Zaharija zagledal, se je vznemiril in strah ga je spreletel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Toda angel mu je rekel: »Ne boj se, Zaharija, kajti tvoja molitev je uslišana in tvoja žena Elizabeta ti bo rodila sina in ti boš klical njegovo ime Janez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Imel boš radost in veselje in mnogi se bodo veselili ob njegovem rojstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Kajti velik bo v Gospodovih očeh in ne bo pil niti vina niti močne pijače in celó od maternice svoje matere bo izpolnjen s Svetim Duhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'In mnoge izmed Izraelovih otrok bo obrnil h Gospodu, njihovemu Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Pred njim bo šel z Elijevim duhom in močjo, da obrne srca očetov k otrokom in neposlušne k modrosti pravičnih; da pripravi ljudstvo, pripravljeno za Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Zaharija je angelu rekel: »Po čem bom to spoznal? Kajti starec sem in moja žena je zelo zvrhana v letih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Angel mu odgovori in reče: »Jaz sem Gabriel, ki stojim v prisotnosti Boga in poslan sem, da ti govorim in da ti pokažem te vesele novice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Glej, ker nisi verjel mojim besedam, ki se bodo uresničile ob njihovem pravem času, boš postal nem in ne boš mogel govoriti do dne, ko se bodo te besede izpolnile.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'In ljudje so čakali na Zaharija in se čudili, da se je tako dolgo mudil v templju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Ko pa je prišel ven, jim ni mogel spregovoriti, in zaznali so, da je videl v templju videnje, kajti dajal jim je znamenja, ostal pa je brez besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Pripetilo se je, kakor hitro so bili dnevi njegovega služenja dovršeni, da se je odpravil k svoji lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Po teh dneh je njegova žena Elizabeta spočela in se pet mesecev skrivala, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '»Tako je Gospod ravnal z menoj v dneh, v katerih je pogledal name, da odvzame mojo grajo izmed ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'V šestem mesecu pa je bil od Boga poslan angel Gabriel v galilejsko mesto, imenovano Nazaret,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'k devici, zaročeni z možem, katerega ime je bilo Jožef, iz Davidove hiše; in devici je bilo ime Marija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, '§ Angel je vstopil k njej in rekel: »Pozdravljena, ti, ki si zelo spoštovana, Gospod je s teboj, blagoslovljena si med ženskami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ko pa ga je zagledala, je bila ob njegovem govoru zaskrbljena in v svojih mislih preudarjala, kakšne vrste pozdrav naj bi to bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Angel ji je rekel: »Ne boj se, Marija, kajti pri Bogu si našla naklonjenost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Glej, v svoji maternici boš spočela in rodila sina in njegovo ime boš klicala JEZUS.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Velik bo in imenovan bo Sin Najvišjega; in Gospod Bog mu bo dal prestol njegovega očeta Davida');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'in nad Jakobovo hišo bo vladal večno in njegovemu kraljestvu ne bo konca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Potem je Marija rekla angelu: »Kako se bo to zgodilo, glede na to, da ne poznam moškega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Angel je odgovoril in ji rekel: »Sveti Duh bo prišel nadte in moč Najvišjega te bo obsenčila, zato bo tudi ta sveta oseba, ki bo rojena od tebe, imenovana Božji Sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Glej, tvoja sestrična Elizabeta je prav tako v svoji visoki starosti spočela sina, in to je šesti mesec z njo, ki je bila imenovana jalova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Kajti z Bogom nič ne bo nemogoče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Marija je rekla: »Glej, Gospodova pomočnica; naj se mi zgodi glede na tvojo besedo.« In angel je odšel od nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Marija je v tistih dneh vstala in z naglico odšla v hribovito deželo, v Judovo mesto');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'in vstopila v Zaharijevo hišo ter pozdravila Elizabeto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'In pripetilo se je, ko je Elizabeta zaslišala Marijin pozdrav, da je dete poskočilo v njeni maternici in Elizabeta je bila izpolnjena s Svetim Duhom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'in zaklicala z močnim glasom ter rekla: »Blagoslovljena si ti med ženskami in blagoslovljen je sad tvoje maternice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Od kod je meni to, da bi prišla k meni mati mojega Gospoda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Kajti glej, brž ko je glas tvojega pozdrava zazvenel v mojih ušesih, je dete v moji maternici od radosti poskočilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Blagoslovljena je tista, ki je verovala, kajti izpolnile se bodo te besede, ki so ji bile povedane od Gospoda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Marija je rekla: »Moja duša poveličuje Gospoda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'in moj duh se veseli v Bogu, mojem Odrešeniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Kajti ozrl se je na nizek stan svoje pomočnice, kajti glej, odslej me bodo vsi rodovi imenovali blagoslovljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Kajti tisti, ki je mogočen, mi je storil velike stvari in sveto je njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'In njegovo usmiljenje je od roda do roda nad tistimi, ki se ga bojijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'S svojim laktom je pokazal moč, ponosne je razgnal v domišljiji njihovih src.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Mogočne je odstranil z njihovih prestolov in povišal te z nizkim položajem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Lačne je napolnil z dobrinami, bogate pa je odpustil prazne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Pomagal je svojemu služabniku Izraelu, v spomin na svoje usmiljenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'kakor je govoril našim očetom, Abrahamu in njegovemu semenu na veke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marija je z njo ostala približno tri mesece in se vrnila v svojo lastno hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Torej prišel je Elizabetin polni čas, ko naj bi rodila; in rodila je sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Njeni sosedje in njeni sorodniki so slišali, kako je Gospod nad njo izkazal veliko usmiljenje in veselili so se z njo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Pripetilo pa se je, da so na osmi dan prišli, da obrežejo otroka in poimenovali so ga Zaharija, po imenu njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Njegova mati pa je odgovorila in rekla: »Ne tako, temveč se bo imenoval Janez.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Oni pa so ji rekli: »Nikogar v tvojem sorodstvu ni, ki je poimenovan s tem imenom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'In naredili so znamenja njegovemu očetu, kako bi ga on imenoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'In prosil je za pisalno deščico ter napisal, rekoč: »Njegovo ime je Janez.« In vsi so se čudili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'In njegova usta so se takoj odprla in njegov jezik se je sprostil in spregovoril je ter hvalil Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'In strah je prišel na vse, ki so prebivali naokoli njih; in vse te besede so se razglasile naokoli po vsej judejski hriboviti deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'In vsi, ki so jih slišali, so si jih položili v svoja srca, rekoč: »Kakšne vrste otrok bo to!« In Gospodova roka je bila z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'In njegov oče Zaharija je bil izpolnjen s Svetim Duhom in prerokoval, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '»Blagoslovljen bodi Gospod, Izraelov Bog; kajti obiskal je in odkupil svoje ljudi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'in za nas je dvignil rog rešitve duš v hiši svojega služabnika Davida,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'kakor je govoril po ustih svojih svetih prerokov, ki so bili, odkar je svet nastal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'da bi bili mi lahko rešeni pred našimi sovražniki in iz roke vseh, ki nas sovražijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'da opravi usmiljenje, obljubljeno našim očetom in se spomni svoje svete zaveze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'prisege, s katero je prisegel našemu očetu Abrahamu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'da nam bo zagotovil, da mu bomo osvobojeni iz roke svojih sovražnikov, lahko služili brez strahu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'v svetosti in pravičnosti pred njim, vse dni našega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Ti pa, otrok, boš imenovan prerok Najvišjega, kajti šel boš pred Gospodov obraz, da pripraviš njegove poti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'da daš njegovim ljudem spoznanje o rešitvi duš z odpuščanjem njihovih grehov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'po nežnem usmiljenju našega Boga; po katerem nas je obiskalo svitanje od zgoraj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'da da svetlobo tem, ki sedijo v temi in v smrtni senci, da vodi naša stopala na pot miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Otrok pa je rasel in se krepil v duhu in bil je v puščavah do dneva njegove pojavitve Izraelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, '§ In pripetilo se je v tistih dneh, da je od cesarja Avgusta izšel odlok, naj se obdavči ves svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '§ (In to obdavčenje je bilo prvič narejeno, ko je bil Kvirinij voditelj Sirije.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, '§ In vsi so odšli, da bi se obdavčili, vsakdo v svoje lastno mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'In tudi Jožef je odšel iz Galileje, iz mesta Nazaret, gor v Judejo, v Davidovo mesto, ki se imenuje Betlehem, (ker je bil iz Davidove hiše in rodovine)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, '§ da bi bil obdavčen z Marijo, svojo zaročeno ženo, ki je bila noseča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'In bilo je tako, medtem ko sta bila tam, da so se ji dovršili dnevi, ko naj bi rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'In rodila je svojega prvorojenega sina ter ga zavila v plenice in ga položila v jasli, kajti v gostišču zanje ni bilo prostora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'In v isti deželi so bili pastirji, ki so se zadrževali na polju in so ponoči stražili nad svojim tropom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'In glej, Gospodov angel je prišel nadnje in Gospodova slava je zasijala naokoli njih in bili so boleče prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Angel pa jim je rekel: »Ne bojte se, kajti glejte, prinašam vam dobre novice o veliki radosti, ki bo za vse ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Kajti ta dan se vam je v Davidovem mestu rodil Odrešenik, ki je Kristus Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'In to vam bo znamenje: ›Našli boste dojenčka, zavitega v plenice, ležečega v jaslih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'In nenadoma je bila pri angelu množica nebeške vojske, ki je slavila Boga in govorila:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '§ »Slava Bogu na višavah in na zemlji mir, dobro voljo napram ljudem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'In pripetilo se je, ko so angeli odšli proč od njih v nebesa, da so pastirji drug drugemu rekli: »Pojdimo sedaj celó v Betlehem in poglejmo to reč, ki se je pripetila, ki nam jo je dal spoznati Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Prišli so v naglici ter našli Marijo in Jožefa ter dojenčka, ležečega v jaslih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'In ko so to videli, so povsod razglasili govor, ki jim je bil povedan glede tega otroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'In vsi, ki so to slišali, so se čudili ob teh besedah, ki so jim jih povedali pastirji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Toda Marija je vse te besede ohranila in jih preudarjala v svojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'In pastirji so se vrnili, slavili in hvalili Boga za vse stvari, ki so jih slišali in videli, tako, kakor jim je bilo povedano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'In ko je bilo dovršenih osem dni za otrokovo obrezovanje, je bilo njegovo ime imenovano JEZUS, tako, kakor je bil poimenovan po angelu, preden je bil spočet v maternici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'In ko so se dovršili dnevi njenega očiščevanja, glede na Mojzesovo postavo, so ga prinesli v Jeruzalem, da ga darujejo Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(kakor je pisano v Gospodovi postavi: ›Vsak moški, ki odpre maternico, bo imenovan svet Gospodu;‹)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'in da darujejo žrtvovanje glede na to, kar je rečeno v Gospodovi postavi: ›Par grlic ali dva mlada goloba.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'In glej, v Jeruzalemu je bil mož, katerega ime je bilo Simeon; in isti mož je bil pravičen ter predan, [in je] pričakoval Izraelovo tolažbo in Sveti Duh je bil nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'In po Svetem Duhu mu je bilo razodeto, da naj ne bi videl smrti, dokler ne bo videl Gospodovega Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'In po Duhu je prišel v tempelj, in ko so starši prinesli otroka Jezusa, da bi zanj storili po običaju postave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'ga je nató vzel v svoje naročje in blagoslovil Boga ter rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '»Gospod, sedaj odpuščaš svojega služabnika umreti v miru, glede na svojo besedo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'kajti moje oči so videle tvojo rešitev duš,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'ki si jo pripravil pred obličjem vseh ljudi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'svetlobo, da razsvetli pogane in slavo tvojega ljudstva Izraela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, '§ In Jožef in njegova mati sta se čudila ob vseh teh besedah, ki so se govorile o njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'In Simeon jih je blagoslovil in rekel Mariji, njegovi materi: »Glej, ta otrok je v Izraelu postavljen za padec in ponovno vstajenje mnogih in za znamenje, ki se mu bo ugovarjalo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(da, meč bo presunil tudi tvojo lastno dušo), da se bodo lahko razodele misli mnogih src.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'In tam je bila neka Ana, prerokinja, Fanuélova hči, iz Aserjevega rodu. Bila je visoke starosti in od svojega devištva je sedem let preživela s soprogom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'in bila je vdova, stara okoli štiriinosemdeset let, ki ni odhajala iz templja, temveč je noč in dan s posti in molitvami služila Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'In ko je vstopila, je tisto uro na isti način dala zahvalo Gospodu in o njem spregovorila vsem, ki so v Jeruzalemu pričakovali odkupitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'In ko so opravili vse stvari, glede na Gospodovo postavo, so se vrnili v Galilejo, v svoje lastno mesto Nazaret.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, '§ In otrok je rasel in se krepil v duhu, napolnjen z modrostjo in Božja milost je bila nad njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Njegovi starši so torej ob prazniku pashe vsako leto hodili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'In ko je bil star dvanajst let, so po praznični navadi odšli gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, '§ In ko so dovršili dneve, medtem ko so se vračali, je otrok Jezus ostal zadaj v Jeruzalemu; Jožef in njegova mati pa nista nič vedela o tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Toda onadva, ker sta mislila, da je v skupini, sta šla pot enega dne in ga iskala med svojo žlahto in znanci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'In ko ga nista našla, sta se, iščoč ga, ponovno obrnila nazaj v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'In pripetilo se je, da sta ga po treh dneh našla v templju, sedečega v sredi med učenimi možmi in on jih je tako poslušal kakor jim zastavljal vprašanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'In vsi, ki so ga slišali, so bili osupli nad njegovim razumevanjem in odgovori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'In ko sta ga zagledala, sta bila osupla in njegova mati mu je rekla: »Sin, zakaj si tako ravnal z nama? Glej, tvoj oče in jaz sva te zaskrbljena iskala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Rekel jima je: »Kako to, da sta me iskala? Mar nista vedela, da moram biti pri opravilu svojega Očeta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Onadva pa nista razumela besed, ki jima jih je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'In z njima je odšel dol in prišel v Nazaret ter jima bil pokoren, toda njegova mati je vse te besede ohranila v svojem srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jezus pa je rasel v modrosti in postavi in naklonjenosti pri Bogu in ljudeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Torej v petnajstem letu vladanja cesarja Tiberija, ko je bil Poncij Pilat voditelj Judeje in Herod vladar četrtinskega dela province Galileje in njegov brat Filip vladar četrtinskega dela province Itureje in področja Trahonítide ter Lizanija vladar četrtinskega dela province Abilene,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Hana in Kajfa pa vélika duhovnika, je v divjini prišla Božja beseda k Janezu, Zaharijevemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'In ta je prišel v vso deželo okoli Jordana ter pridigal krst kesanja v odpuščanje grehov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'kakor je pisano v knjigi besed preroka Izaija, rekoč: »Glas nekoga vpijočega v divjini: ›Pripravite Gospodovo pot, izravnajte njegove steze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Vsaka dolina naj bo napolnjena in vsaka gora in hrib naj bosta znižana in skrivljeno naj bo izravnano in neravne poti naj bodo izglajene');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'in vse meso bo videlo Božjo rešitev duš.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Potem je rekel množici, ki je prihajala, da bi jih krstil: »Oh gadji rod, kdo vas je opozoril, da pobegnete pred besom, ki pride?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Obrodite torej sadove, vredne kesanja in ne začnite v sebi govoriti: ›Abrahama imamo za svojega očeta,‹ kajti povem vam: ›Da je Bog iz teh kamnov zmožen Abrahamu obuditi otroke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'In sedaj je prav tako sekira nastavljena drevesom na korenino; vsako drevo, ki torej ne prinaša dobrega sadu, je posekano in vrženo v ogenj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'In množica ga je spraševala, rekoč: »Kaj naj potem storimo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Odgovarja in jim reče: »Kdor ima dva plašča, naj da tistemu, ki nima nobenega; in kdor ima hrano, naj stori enako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Potem so prišli tudi davkarji, da bi bili krščeni in mu rekli: »Učitelj, kaj naj storimo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Rekel jim je: »Ne terjajte nič več kakor to, kar vam je določeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'In prav tako so od njega zahtevali vojaki, rekoč: »In kaj naj mi storimo?« In rekel jim je: »Nobenemu človeku ne storite nasilja niti nikogar po krivem ne obdolžite in zadovoljni bodite s svojimi plačami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'In medtem ko so bili ljudje v pričakovanju in so vsi ljudje v svojih srcih razglabljali o Janezu, če je bil on Kristus ali ne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'je Janez odgovoril, rekoč njim vsem: »Zares, jaz vas krščujem z vodo, toda prihaja nekdo mogočnejši od mene, čigar čevljev jermena nisem vreden odvezati. On vas bo krstil s Svetim Duhom in z ognjem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'katerega vejálnik je v njegovi roki in svoje mlatišče bo temeljito očistil in pšenico bo spravil v svojo kaščo, toda pleve bo sežgal z nepogasljivim ognjem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, '§ In mnoge druge besede je v svojem spodbujanju oznanjal ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Toda Herod, vladar četrtinskega dela province, od njega pograjan zaradi Herodiade, žene njegovega brata Filipa in zaradi vseh hudobij, ki jih je storil Herod,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'je povrh vsega dodal še to, da je Janeza zaprl v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Ko so bili torej vsi ljudje krščeni, se je pripetilo, da je bil krščen tudi Jezus, in ko je molil, se je odprlo nebo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'in Sveti Duh se je spustil nadenj v telesni obliki, podoben golobici in glas je prišel z neba, ki je rekel: »Ti si moj ljubljeni Sin; s teboj sem zelo zadovoljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'In sam Jezus je šel v trideseto leto starosti, in (kakor se je domnevalo) je bil sin Jožefa, ki je bil Élijev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'ki je bil Matátov sin, ki je bil Lévijev sin, ki je bil Melhíjev sin, ki je bil Janájev sin, ki je bil Jožefov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'ki je bil Matitjájev sin, ki je bil Amosov sin, ki je bil Nahumov sin, ki je bil Heslíjev sin, ki je bil Nangájev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'ki je bil Mahatov sin, ki je bil Matitjájev sin, ki je bil Šimíjev sin, ki je bil Jozéhov sin, ki je bil Jodájev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'ki je bil Johanánov sin, ki je bil Rezájev sin, ki je bil Zerubabélov sin, ki je bil Šaltiélov sin, ki je bil Neríjev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'ki je bil Melhíjev sin, ki je bil Adíjev sin, ki je bil Kosámov sin, ki je bil Elmadámov sin, ki je bil Erov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'ki je bil Jošúov sin, ki je bil Eliézerjev sin, ki je bil Jorímov sin, ki je bil Matátov sin, ki je bil Lévijev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'ki je bil Simeonov sin, ki je bil Judov sin, ki je bil Jožefov sin, ki je bil Jonámov sin, ki je bil Eljakímov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'ki je bil Meleájev sin, ki je bil Menájev sin, ki je bil Matatájev sin, ki je bil Natánov sin, ki je bil Davidov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'ki je bil Jesejev sin, ki je bil Obédov sin, ki je bil Boazov sin, ki je bil Salmónov sin, ki je bil Nahšónov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, '§ ki je bil Aminadábov sin, ki je bil Aramov sin, ki je bil Hecrónov sin, ki je bil Perecov sin, ki je bil Judov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'ki je bil Jakobov sin, ki je bil Izakov sin, ki je bil Abrahamov sin, ki je bil Terahov sin, ki je bil Nahórjev sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'ki je bil Serúgov sin, ki je bil Regujev sin, ki je bil Pelegov sin, ki je bil Eberjev sin, ki je bil Šelahov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'ki je bil Kenánov sin, ki je bil Arpahšádov sin, ki je bil Semov sin, ki je bil Noetov sin, ki je bil Lamehov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'ki je bil Matuzalemov sin, ki je bil Henohov sin, ki je bil Jeredov sin, ki je bil Mahalalélov sin, ki je bil Kenánov sin,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'ki je bil Enóšev sin, ki je bil Setov sin, ki je bil Adamov sin, ki je bil Božji sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'In Jezus se je poln Svetega Duha vrnil od Jordana in po Duhu je bil voden v divjino');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'in štirideset dni je bil skušan od hudiča. In v tistih dneh ni ničesar jedel, in ko so se končali, je bil potem lačen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'In hudič mu je rekel: »Če si Božji Sin, ukaži temu kamnu, da naj postane kruh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, '§ In Jezus mu je odgovoril, rekoč: »Pisano je: ›Da človek ne bo živel samo od kruha, temveč od vsake Božje besede.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'In hudič, ki ga je vzel gor na visoko goro, mu je v trenutku časa pokazal vsa kraljestva sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'In hudič mu je rekel: »Vso to oblast hočem predati tebi in njihovo slavo, kajti ta mi je izročena in dam jo komurkoli hočem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Če me torej hočeš oboževati, bo vsa tvoja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, '§ Jezus pa je odgovoril in mu rekel: »Spravi se za menoj, Satan, kajti pisano je: ›Gospoda, svojega Boga, obožuj in njemu samemu služi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'In odvedel ga je v Jeruzalem in ga postavil na vrh templja ter mu rekel: »Če si Božji Sin, se vrzi od tod dol,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'kajti pisano je: ›Svojim angelom bo zate naročil, da te varujejo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'in na svojih rokah te bodo prenašali, da ne bi kadarkoli s svojo nogo treščil ob kamen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jezus pa mu odgovori in reče: »Rečeno je: ›Ne boš skušal Gospoda, svojega Boga.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'In ko je hudič končal vse skušnjave, je za nekaj časa odšel od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'In Jezus se je v moči Duha vrnil v Galilejo in tam je šel slôves o njem naokoli po vsem področju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'In učil je v njihovih sinagogah in od vseh je bil proslavljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'In prišel je v Nazaret, kjer je bil vzgojen in kakor je bila njegova navada, je na šabatni dan odšel v sinagogo in vstal, da bi bral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'In izročena mu je bila knjiga preroka Izaija. In ko je odprl knjigo, je našel mesto, kjer je bilo zapisano:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '»Gospodov Duh je nad menoj, ker me je mazilil, da oznanim evangelij revnim. Poslal me je, da ozdravim zlomljene v srcu, da oznanim jetnikom osvoboditev in slepim okrevanje vida, da izpustim na prostost te, ki so ranjeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'da oznanim sprejemljivo leto Gospodovo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'In zaprl je knjigo in jo dal nazaj služitelju ter se usedel. In oči vseh, ki so bili v sinagogi, so bile uprte vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'In začel jim je govoriti: »Ta dan se je to pismo izpolnilo v vaših ušesih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'In vsi so očitno pričevali zanj ter se čudili ob milostnih besedah, ki so izvirale iz njegovih ust. In rekli so: »Ali ni to Jožefov sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Rekel jim je: »Zagotovo mi boste povedali ta pregovor: ›Zdravnik, ozdravi sebe.‹ Karkoli smo slišali, da je bilo storjeno v Kafarnáumu, prav tako stôri tukaj, v svoji deželi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'In rekel je: »Resnično, povem vam: ›Noben prerok ni sprejet v svoji lastni deželi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Toda povem vam po resnici, mnogo vdov je bilo v Izraelu v Elijevih dneh, ko je bilo nebo zaprto tri leta in šest mesecev, ko je bila velika lakota po vsej celotni deželi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'toda k nobeni izmed njih ni bil poslan Elija, razen v Sarepto, mesto na Sidónskem, k ženski, ki je bila vdova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'In v času preroka Elizeja je bilo v Izraelu mnogo gobavcev. In nobeden izmed njih ni bil očiščen, razen Sirca Naamána.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'In ko so vsi ti v sinagogi slišali te besede, so bili izpolnjeni z besom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'in vstali so in ga pahnili iz mesta in ga odvedli na skalno strmino hriba, na katerem je bilo zgrajeno njihovo mesto, da bi ga lahko z glavo naprej vrgli dol.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Toda šel je skozi njihovo sredo in odšel svojo pot');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'in prišel dol v Kafarnáum, mesto v Galileji ter jih na šabatne dneve učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'In nad njegovim naukom so bili osupli, kajti njegova beseda je bila z oblastjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'In v sinagogi je bil človek, ki je imel duha nečistega hudiča in z močnim glasom je zakričal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'rekoč: »Pusti nas pri miru, kaj imamo s teboj, ti Jezus Nazarečan? Si prišel, da nas uničiš? Poznam te, kdo si; Sveti od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Jezus pa ga je oštel, rekoč: »Umolkni in pridi ven iz njega.« In ko ga je hudič vrgel na sredo, je prišel iz njega in ga ni poškodoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'In vsi so bili osupli in med seboj so govorili, rekoč: »Kakšna beseda je to! Kajti z oblastjo in močjo ukazuje nečistim duhovom in ti pridejo ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'In njegov slôves je šel naokoli v vsak kraj te dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'In vstal je iz sinagoge ter vstopil v Simonovo hišo. Simonova tašča pa je bila prevzeta z veliko vročico in oni so ga zaradi nje rotili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'In stopil je nad njo in oštel vročico in ta jo je zapustila in takoj je vstala ter jim služila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Torej ko je sonce zahajalo, so vsi, ki so imeli kogarkoli bolnega z raznimi boleznimi, te pripeljali k njemu in na vsakogar izmed njih je položil svoji roki ter jih ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'In tudi hudiči so izhajali iz mnogih, kričali in govorili: »Ti si Kristus, Božji Sin.« In ko jih je ukoril, jim ni dovolil govoriti, kajti vedeli so, da je bil on Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'In ko je bil dan, se je odpravil in odšel na zapuščen kraj in množica ga je iskala in prišla k njemu in ga zadržala, da ne bi odšel od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Rekel jim je: »Tudi drugim mestom moram oznaniti Božje kraljestvo, kajti zato sem poslan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'In oznanjal je po galilejskih sinagogah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'In pripetilo se je, medtem ko je množica pritiskala nanj, da sliši Božjo besedo, [da] je stal ob Genezareškem jezeru');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'in zagledal dve ladji, pripravljeni pri jezeru, toda ribiči so odšli iz njiju ter izpirali svoje mreže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'In vstopil je v eno izmed ladij, ki je bila Simonova in ga prosil, da bi odrinil malce proč od kopnega. In usedel se je ter iz ladje učil množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, '§ Torej, ko je prenehal govoriti, je rekel Simonu: »Kreni na globoko in spusti dol svoje mreže za vleko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Simon pa mu odgovori in reče: »Učitelj, celó noč smo garali, pa nismo nič ujeli. Vendar bom na tvojo besedo to mrežo spustil dol.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'In ko so to storili, so zajeli veliko množino rib in njihova mreža se je pretrgala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'In dali so znamenje svojim družabnikom, ki so bili na drugi ladji, da naj pridejo ter jim pomagajo. In prišli so ter napolnili obe ladji, tako da sta se začeli potapljati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Ko je Simon Peter to videl, je pri Jezusovih kolenih padel dol, rekoč: »Odidi od mene, oh Gospod, kajti grešen človek sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Kajti nad ulovom rib, ki so jih zajeli, je bil osupel on in vsi ti, ki so bili z njim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'in tako sta bila tudi Jakob in Janez, Zebedejeva sinova, ki sta bila Simonova družabnika. In Jezus je Simonu rekel: »Ne boj se, odslej boš lovil ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'In ko so svoji ladji pripeljali do kopnega, so vse zapustili in mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'In pripetilo se je, ko je bil v nekem mestu, [da] zagleda človeka polnega gobavosti. Ko je [le-ta] zagledal Jezusa, je padel na svoj obraz ter ga rotil, rekoč: »Gospod, če hočeš, me lahko očistiš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'In iztegnil je svojo roko ter se ga dotaknil, rekoč: »Hočem, bodi čist.« In gobavost je takoj odšla od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'In naročil mu je, da ne pove nobenemu človeku: »Temveč pojdi in se pokaži duhovniku ter daruj za svoje očiščenje glede na Mojzesovo zapoved, njim v pričevanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Toda beseda o njem je toliko bolj na veliko šla naokoli in velike množice so prišle skupaj, da poslušajo in da bi bile po njem ozdravljene svojih slabotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'On pa se je umaknil v divjino in molil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'In pripetilo se je na določeni dan, medtem ko je učil, da so bili tam, sedeči poleg, farizeji in učeni možje postave, ki so prišli iz vsakega mesta Galileje, Judeje in Jeruzalema. In Gospodova moč je bila prisotna, da jih ozdravi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'In glej, možje so prinesli na postelji človeka, ki je bil prevzet s paralizo in iskali so načine, da ga prinesejo noter in da ga položijo predenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Ko pa zaradi množice niso mogli najti, po kateri poti bi ga lahko prinesli noter, so odšli na hišno streho in ga z njegovim ležiščem vred spustili navzdol skozi strešno kritino v sredo pred Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'In ko je videl njihovo vero, mu je rekel: »Človek, tvoji grehi so ti odpuščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'In pisarji in farizeji so začeli premišljevati, rekoč: »Kdo je ta, ki govori bogokletja? Kdo lahko odpušča grehe razen samo Bog?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Toda ko je Jezus zaznal njihove misli, jim je odgovoril in rekel: »Kaj razmišljate v svojih srcih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Ali je lažje reči: ›Tvoji grehi naj ti bodo odpuščeni‹ ali reči: ›Dvigni se in hôdi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Toda da boste lahko vedeli, da ima Sin človekov na zemlji oblast odpuščati grehe,« (je rekel bolnemu zaradi paralize) »jaz ti pravim: ›Vstani in vzemi svoje ležišče in pojdi v svojo hišo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'In ta je pred njimi takoj vstal ter pobral to, na čemer je ležal in odšel k svoji lastni hiši, proslavljajoč Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'In vsi so bili osupli in slavili Boga in izpolnjeni so bili s strahom, rekoč: »Danes smo videli čudne stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Po teh stvareh pa je odšel dalje in zagledal davkarja, imenovanega Levi, ki je sedel pri kraju plačevanja davkov in mu rekel: »Sledi mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'In ta je pustil vse, vstal ter mu sledil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'In Levi mu je v svoji lastni hiši pripravil veliko praznovanje; in bila je velika skupina davkarjev in drugih, ki so se z njimi usedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Toda njihovi pisarji in farizeji so godrnjali zoper njegove učence, rekoč: »Zakaj jeste in pijete z davkarji in grešniki?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'In Jezus jim odgovori ter reče: »Tisti, ki so zdravi, ne potrebujejo zdravnika, temveč tisti, ki so bolni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nisem prišel klicat pravičnih, temveč grešnike h kesanju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'In rekli so mu: »Zakaj se Janezovi učenci pogosto postijo in opravljajo molitve in enako učenci farizejev, tvoji pa jedo in pijejo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Rekel jim je: »Ali lahko primorate otroke svatovske sobe, da se postijo, medtem ko je z njimi ženin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Toda prišli bodo dnevi, ko bo ženin odvzet od njih in tedaj, v tistih dneh, se bodo postili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'In povedal jim je tudi prispodobo: »Nihče ne polaga koščka iz nove obleke na staro; če drugače, potem nov dela raztrganino in tudi košček, ki je bil odvzet iz nove, se ne ujema s staro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'In novega vina nihče ne vliva v stare mehove, sicer bo novo vino mehove razgnalo in bo izlito in mehovi bodo propadli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, '§ Toda novo vino mora biti vlito v nove mehove in oboje je ohranjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Prav tako nihče, ki je pil staro vino, noče nemudoma novega, kajti pravi: ›Staro je boljše.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'In pripetilo se je na drugi šabat za prvim, da je šel skozi žitna polja in njegovi učenci so smukali žitno klasje, ga méli v svojih rokah in jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Nekateri izmed farizejev so jim rekli: »Zakaj delate to, kar ni zakonito delati na šabatne dneve?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Jezus jim odgovori in reče: »Mar niste brali tega, kar je storil David, ko je bil lačen on sam in ti, ki so bili z njim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'kako je odšel v Božjo hišo in vzel in jedel hlebe navzočnosti in jih dal tudi tistim, ki so bili z njim; kar ni zakonito jésti [nikomur], razen samo duhovnikom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Rekel jim je: »Sin človekov je tudi Gospodar šabata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'In prav tako se je na še en šabat pripetilo, da je vstopil v sinagogo ter učil, in tam je bil človek, čigar desna roka je bila izsušena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'In pisarji in farizeji so ga opazovali ali bo ozdravljal na šabatni dan, da bi zoper njega lahko našli obtožbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Toda poznal je njihove misli in rekel možu, ki je imel izsušeno roko: »Vstani in stopi na sredo.« In ta je vstal ter stopil naprej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Potem jim je Jezus rekel: »Eno stvar vas bom vprašal: ›Ali je na šabatne dneve zakonito delati dobro ali delati zlo? Rešiti življenje ali ga uničiti?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, '§ In ko je pogledal naokoli po vseh, je rekel možu: »Iztegni svojo roko.« In ta je storil tako in njegova roka je bila v celoti ozdravljena, tako kakor druga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'In bili so izpolnjeni z besom in drug z drugim so se posvetovali, kaj bi lahko storili Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'In pripetilo se je v tistih dneh, da je odšel ven na goro, da moli in je vso noč vztrajal v molitvi k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'In ko je bil dan, je k sebi poklical svoje učence in izmed njih jih je izbral dvanajst, ki jih je imenoval tudi apostole:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simona (ki ga je imenoval tudi Peter) in njegovega brata Andreja, Jakoba in Janeza, Filipa in Bartolomeja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateja in Tomaža, Jakoba, Alfejevega sina in Simona, imenovanega Gorečnik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'in Juda, Jakobovega brata in Juda Iškarijota, ki je bil tudi izdajalec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'In z njimi je prišel dol ter stal na ravnem in skupina njegovih učencev ter velika množica ljudi iz vse Judeje in Jeruzalema in pokrajin Tira in Sidóna, ki so prišli, da ga poslušajo in da bi bili ozdravljeni svojih bolezni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'in tisti, ki so bili nadlegovani z nečistimi duhovi in bili so ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'In celotna množica si je prizadevala, da bi se ga dotaknila, kajti iz njega je izhajala moč in jih vse ozdravljala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'In povzdignil je svoje oči na svoje učence ter rekel: »Blagoslovljeni bodite vi ubogi, kajti vaše je Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Blagoslovljeni ste vi, ki ste sedaj lačni, kajti nasičeni boste. Blagoslovljeni ste vi, ki sedaj jokate, kajti smejali se boste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Blagoslovljeni ste, ko vas bodo ljudje sovražili in ko vas bodo oddvojili od svoje družbe in vas bodo grajali in zaradi Sina človekovega vaše ime zavrgli kot hudobno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Veselite se na tisti dan in poskakujte od radosti, kajti, glejte, vaša nagrada v nebesih je velika, kajti na podoben način so njihovi očetje delali prerokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Toda gorje vam, ki ste bogati! Kajti prejeli ste svojo tolažbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Gorje vam, ki ste siti! Kajti lačni boste. Gorje vam, ki se sedaj smejete! Kajti žalovali boste in jokali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Gorje vam, ko bodo vsi ljudje o vas lepo govorili! Kajti tako so njihovi očetje delali lažnim prerokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Toda jaz pravim vam, ki slišite: ›Ljubite svoje sovražnike, delajte dobro tem, ki vas sovražijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'blagoslavljajte te, ki vas preklinjajo in molite za tiste, ki vas kruto izkoriščajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'In tistemu, ki te udarja na eno lice, ponudi še drugo; in tistemu, ki odvzema tvoje ogrinjalo, ne prepovej vzeti tudi svojega plašča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Vsakemu človeku daj, kar prosi od tebe in od tistega, ki jemlje tvoje dobrine, ne prosi ponovno zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'In kakor želite, da bi ljudje storili vam, prav tako tudi vi storite njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Kajti če ljubite te, ki ljubijo vas, kakšno hvalo imate? Kajti tudi grešniki ljubijo tiste, ki ljubijo njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'In če delate dobro tem, ki delajo dobro vam, kakšno hvalo imate? Kajti tudi grešniki celó enako delajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'In če posojate tistim, od katerih upate, da prejmete, kakšno hvalo imate? Kajti tudi grešniki posojajo grešnikom, da prejmejo toliko nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Toda ljubite svoje sovražnike in delajte dobro in posojajte ter se ničesar ne nadejajte v vrnitev in vaša nagrada bo velika in boste otroci Najvišjega, kajti on je prijazen do nehvaležnih in do hudobnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Bodite torej usmiljeni, kakor je tudi vaš Oče usmiljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Ne sodite in ne boste sojeni, ne obsojajte in ne boste obsojeni, odpuščajte in vam bo odpuščeno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'dajajte in to vam bo dano; dobro mero, potlačeno in skupaj zbrano in čez rob polno vam bodo ljudje dali v vaše naročje. Kajti z enako mero, s katero vi merite, bo tudi vam ponovno odmerjeno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'In spregovoril jim je prispodobo: ›Mar lahko slepi vodi slepega? Ali ne bosta oba padla v jarek?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Učenec ni nad svojim učiteljem, toda vsak, kdor je popoln, bo kakor njegov učitelj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'In zakaj gledaš drobec, ki je v očesu svojega brata, toda ne zaznavaš bruna, ki je v tvojem lastnem očesu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Ali kako lahko rečeš svojemu bratu: ›Brat, dovoli mi izvleči drobec, ki je v tvojem očesu,‹ ko sam ne zapaziš bruna, ki je v tvojem lastnem očesu? Ti hinavec, vrzi ven najprej bruno iz svojega lastnega očesa in tedaj boš jasno videl izvleči drobec, ki je v očesu tvojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Kajti dobro drevo ne prinaša slabega sadu niti slabo drevo ne prinaša dobrega sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Kajti vsako drevo je razpoznano po svojem lastnem sadu. Kajti ljudje fig ne nabirajo s trnja niti z robidovega grma ne nabirajo grozdja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Dober človek iz dobrega zaklada svojega srca prinaša to, kar je dobro, hudobnež pa iz zlega zaklada svojega srca prinaša to, kar je zlo, kajti iz obilja srca njegova usta govoré.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'In zakaj me kličete: ›Gospod, Gospod,‹ pa ne delate stvari, ki jih govorim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Kdorkoli pride k meni in posluša moje besede ter jih izpolnjuje, vam bom pokazal, komu je podoben.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, '§ Podoben je človeku, ki je gradil hišo in globoko kopál ter položil temelj na skalo. In ko je nastala poplava, je na to hišo silovito udaril vodni tok in je ni mogel omajati, kajti utemeljena je bila na skali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Toda kdor posluša, pa ne dela, je podoben človeku, ki je na zemlji zgradil hišo brez temelja, proti kateri je silovito udaril vodni tok in ta je takoj padla in ruševina te hiše je bila velika.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Ko je torej končal vse svoje govore pred občinstvom ljudi, je vstopil v Kafarnáum.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Neki služabnik stotnika, ki mu je bil dragocen, je bil bolan in pripravljen na smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Ko je slišal o Jezusu, je k njemu poslal judovske starešine in ga rotil, da bi prišel in ozdravil njegovega služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ko so prišli k Jezusu, so ga takoj iskreno rotili, rekoč: »Vreden je bil, da bi to storil zanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'kajti rad ima naš narod in sinagogo nam je zgradil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Potem je Jezus odšel z njimi. In ko je bil torej nedaleč od hiše, je stotnik k njemu poslal prijatelje, rekoč mu: »Gospod, ne delaj si sitnosti, kajti nisem vreden, da bi stopil pod mojo streho,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'zato se tudi nisem imel za vrednega, da bi prišel k tebi, toda reci besedo in moj služabnik bo ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Kajti tudi sam sem človek, postavljen pod oblast. Pod seboj imam vojake in nekomu rečem: ›Pojdi,‹ in gre, in drugemu: ›Pridi‹ in pride, in svojemu služabniku: ›Naredi to,‹ in to stori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Ko je Jezus slišal te besede, se je začudil nad njim in se obrnil ter rekel množici, ki mu je sledila: »Povem vam: ›Nisem našel tako velike vere, ne, niti v Izraelu ne.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, '§ In tisti, ki so bili poslani, so se vrnili k hiši in našli služabnika, ki je bil bolan, zdravega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, '§ Pripetilo se je dan kasneje, da je odšel v mesto, imenovano Nain in z njim so odšli mnogi izmed njegovih učencev ter veliko ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Ko je torej prišel blizu k mestnim velikim vratom, glej, je bil ven odnesen mrtev človek, edini sin njegove matere in ta je bila vdova; in z njo je bilo veliko ljudi iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Ko jo je Gospod zagledal, je imel sočutje do nje in ji je rekel: »Ne jokaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Prišel je in se dotaknil mrtvaškega odra, in tisti, ki so ga nosili, so mirno stali. In rekel je: »Mladenič, rečem ti: ›Vstani.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'In ta, ki je bil mrtev, se je usedel in začel govoriti. In izročil ga je njegovi materi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Strah je prišel na vse in slavili so Boga, rekoč, da je med nami vstal velik prerok in da je Bog obiskal svoje ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'In ta govorica o njem je šla naprej po vsej celotni Judeji in naokoli po vsem celotnem področju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'In Janezovi učenci so mu povedali o vseh teh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, '§ In Janez je k sebi poklical dva izmed svojih učencev in ju poslal k Jezusu, rekoč: »Ali si ti tisti, ki naj bi prišel? Ali [naj] pričakujemo drugega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Ko sta moža prišla k njemu, sta rekla: »Janez Krstnik naju je poslal k tebi, rekoč: ›Ali si ti tisti, ki naj bi prišel? Ali [naj] pričakujemo drugega?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'In v tej isti uri je mnoge ozdravil njihovih slabotnosti in nadlog ter od zlih duhov, in mnogim, ki so bili slepi, je dal vid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Potem jima Jezus odgovori in reče: »Pojdita svojo pot in povejta Janezu, kakšne stvari sta videla in slišala: kako slepi vidijo, hromi hodijo, gobavi so očiščeni, gluhi slišijo, mrtvi so obujeni, revnim je oznanjen evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'In blagoslovljen je, kdorkoli se ne bo spotaknil ob mene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'In ko sta Janezova poslanca odšla, je množici začel govoriti glede Janeza: »Kaj ste odšli ven v divjino, da vidite? Trst, ki se maje z vetrom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Toda kaj ste odšli ven, da vidite? Človeka, oblečenega v mehka oblačila? Glejte, tisti, ki so krasno oblečeni in žive prefinjeno, so na kraljevih dvorih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Toda kaj ste odšli ven, da vidite? Preroka? Da, povem vam in veliko več kakor preroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'To je on, o katerem je pisano: ›Glej, svojega poslanca pošljem pred tvoj obraz, ki bo pripravil tvojo pot pred teboj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Kajti povem vam: ›Med temi, ki so rojeni iz žensk, ni večjega preroka kakor Janez Krstnik, toda kdor je v Božjem kraljestvu najmanjši, je večji od njega.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'In vsi ljudje, ki so ga slišali in davkarji, so resničnost Boga opravičili s tem, da so se krstili z Janezovim krstom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Toda farizeji in izvedenci v postavi so zavrnili nasvet Boga, sami zoper sebe, tako da se mu niso dali krstiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '§ In Gospod je rekel: »S kom naj torej primerjam ljudi tega rodu? In čemú so podobni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Podobni so otrokom, sedečim na trgu, ki kličejo drug drugemu ter govorijo: ›Piskali smo vam, pa niste plesali; objokovali smo vam, pa niste jokali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Kajti Janez Krstnik je prišel [in] niti ni jedel kruha niti ni pil vina; vi pa pravite: ›Hudiča ima.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Sin človekov je prišel in jé ter pije; vi pa pravite: ›Glejte, požrešen človek in vinski bratec, prijatelj davkarjev in grešnikov!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Toda modrost je opravičena po vseh svojih otrocih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Eden izmed farizejev pa ga je prosil, da bi lahko jedel z njim. In odšel je v farizejevo hišo ter se usedel k obedu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'In glej, ko je ženska, ki je bila v mestu grešnica, spoznala, da je Jezus sedel v farizejevi hiši pri obedu, je prinesla alabastrno škatlo mazila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'ter jokajoč od zadaj pristopila k njegovim stopalom in njegova stopala začela umivati s solzami in jih brisati z lasmi svoje glave in poljubljala je njegova stopala ter jih mazilila z mazilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Ko je torej to videl farizej, ki ga je povabil, si je rekel sam pri sebi, rekoč: »Če bi bil ta človek prerok, bi vedel, kdo in kakšne vrste je ta ženska, ki se ga dotika, kajti grešnica je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'In Jezus mu odgovori ter reče: »Simon, nekaj ti imam povedati.« On pa reče: »Učitelj, povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '»Bil je nek upnik, ki je imel dva dolžnika. Eden mu je bil dolžan petsto denarjev, drugi pa petdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'In ko nista imela nič, s čimer bi plačala, jima je obema odkrito odpustil. Povej mi torej, kateri izmed njiju ga bo bolj ljubil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon je odgovoril in rekel: »Domnevam, da tisti, ki mu je več odpustil.« On pa mu je rekel: »Pravilno si presodil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'In obrnil se je k ženski ter rekel Simonu: »Vidiš to žensko? V tvojo hišo sem vstopil, pa mi nisi dal vode za moja stopala, toda ona je moja stopala umila s solzami in jih obrisala z lasmi svoje glave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nisi mi dal poljuba, toda odkar sem vstopil, ta ženska ni prenehala poljubljati mojih stopal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Moje glave nisi mazilil z oljem, toda ta ženska je moja stopala mazilila z mazilom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Zato ti pravim: ›Njeni grehi, ki jih je mnogo, so odpuščeni,‹ kajti veliko je ljubila, toda komur je malo oproščeno, ta malo ljubi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Njej pa je rekel: »Tvoji grehi so odpuščeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'In tisti, ki so pri obedu sedeli z njim, so v sebi začeli govoriti: »Kdo je ta, da tudi grehe odpušča?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'In ženski je rekel: »Tvoja vera te je rešila, pojdi v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'In pripetilo se je potem, da je šel skozi vsako mesto in vas in oznanjal ter prikazoval vesele novice Božjega kraljestva in z njim so bili dvanajsteri');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'in neke ženske, ki so bile ozdravljene od zlih duhov in slabotnosti: Marija, imenovana Magdalena, iz katere je odšlo sedem hudičev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, '§ in Joana, žena Herodovega oskrbnika Husa ter Suzana in mnoge druge, ki so mu služile iz svojega imetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'In ko je bilo skupaj zbranih veliko ljudi in so prišli k njemu iz vsakega mesta, je spregovoril s prispodobo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '»Sejalec je odšel ven sejat svoje seme in ko je sejal, je nekaj padlo poleg poti in to je bilo pomendrano in pozobala ga je perjad neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'In nekaj je padlo na skalo in takoj, ko je pognalo, je ovenelo, ker mu je primanjkovalo vlage.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'In nekaj je padlo med trnje in trnje je pognalo z njim ter ga zadušilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Drugo pa je padlo na dobro zemljo in pognalo ter obrodilo stoteren sad.« In ko je povedal te besede, je zaklical: »Kdor ima ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Njegovi učenci pa so ga vprašali, rekoč: »Kaj bi bila ta prispodoba?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'In rekel je: »Vam je dano spoznati skrivnosti Božjega kraljestva, toda drugim v prispodobah; da z gledanjem ne bi mogli videti in s poslušanjem ne bi mogli razumeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Torej prispodoba je ta: ›Seme je Božja beseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Tisti ob poti so tisti, ki slišijo; potem pride hudič in iz njihovih src odvzema besedo, da ne bi verjeli in ne bi bili rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Tisti na skali so tisti, ki, ko slišijo, z radostjo sprejmejo besedo; in ti nimajo korenine, ki nekaj časa verujejo, ob času skušnjave pa padejo stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'In to, kar je padlo med trnje, so tisti, ki, ko so slišali, gredo naprej in so zadušeni s skrbmi in bogastvi in užitki tega življenja in nobenega sadu ne privedejo do zrelosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Toda to, na dobri zemlji, so tisti, ki so z iskrenim in dobrim srcem slišali besedo, jo obdržali in s potrpežljivostjo prinašajo sad.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '›Nihče, ko je prižgal svetilko, je ne pokrije s posodo ali jo postavi pod posteljo, temveč jo postavi na svečnik, da tisti, ki vstopajo noter, lahko vidijo svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Kajti nič ni skrito, kar ne bo razodeto niti ni nobena stvar skrita, da se ne bo izvedela in postala znana.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Pazite torej kako poslušate, kajti kdorkoli ima, njemu bo dano; kdorkoli pa nima, bo od njega vzeto celó to, kar se mu zdi, da ima.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Tedaj so prišli k njemu njegova mati in njegovi bratje, pa zaradi gneče niso mogli priti do njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'In povedano mu je bilo po nekom, ki je rekel: »Tvoja mati in tvoji bratje stojijo zunaj in te želijo videti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'In odgovoril je ter jim rekel: »Moja mati in moji bratje so tisti, ki poslušajo Božjo besedo in jo izvršujejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Pripetilo se je torej na nek dan, da je s svojimi učenci odšel na ladjo in jim rekel: »Pojdimo preko, na drugo stran jezera.« In so odrinili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Toda ko so jadrali, je zaspal. Dol na jezero pa je prišel vetroven vihar in bili so napolnjeni z vodo in v nevarnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'In prišli so k njemu ter ga zbudili, rekoč: »Učitelj, učitelj, mi ginemo.« Potem je vstal, oštel veter in besnenje vode, in ponehala sta in bil je mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Rekel jim je: »Kje je vaša vera?« In prestrašeno začudeni so drug drugemu govorili: »Kakšne vrste človek je to! Kajti ukazuje celó vetrovom in vodi in so mu pokorni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'In prispeli so v Géraško deželo, ki je na drugi strani, nasproti Galileji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'In ko je šel naprej v deželo, ga je tam zunaj mesta srečal nek mož, ki je imel dolgo časa hudiče in ni nosil oblačil niti ni prebival v nobeni hiši, temveč v grobnicah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Ko je zagledal Jezusa, je zakričal in padel dol pred njim ter z močnim glasom rekel: »Kaj imam opraviti s teboj, Jezus, ti Sin od Boga najvišjega? Rotim te, ne muči me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, '(Kajti nečistemu duhu je ukazal, da pride iz tega človeka. Kajti ta ga je pogosto zgrabil in bil je držan zvezan z verigami in okovi, pa je prelomil vezi in po hudiču je bil gnan v divjino.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'In Jezus ga je vprašal, rekoč: »Kako ti je ime?« In ta je rekel: »Legija,« ker je vanj vstopilo mnogo hudičev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'In rotili so ga, da jim ne bi ukazal oditi ven, v brezno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Tam pa je bila čreda mnogih svinj, ki so se pasle na gori in rotili so ga, naj jim dovoli vstopiti vanje. In dovolil jim je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Tedaj so hudiči odšli iz človeka in vstopili v svinje in čreda je silovito stekla navzdol po strmini v jezero in so se zadušile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Ko so tisti, ki so jih hranili, videli, kaj je bilo storjeno, so pobegnili in odšli ter to povedali v mestu in na deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Potem so odšli ven, da vidijo kaj je bilo storjeno in prišli so k Jezusu in našli človeka, iz katerega so odšli hudiči, sedečega pri Jezusovih stopalih, oblečenega in pri zdravi pameti, in bili so prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Tisti, ki so to videli, so jim povedali tudi na kakšen način je bil ta, ki je bil obseden s hudiči, ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, '§ Potem ga je celotna množica naokoli iz Géraške dežele rotila, naj odide od njih, kajti bili so prevzeti z velikim strahom, on pa je odšel gor na ladjo in se ponovno vrnil nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Torej mož, iz katerega so izšli hudiči, ga je rotil, da bi bil lahko z njim, toda Jezus ga je poslal proč, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '»Vrni se k svoji lastni hiši in pokaži, kako velike stvari ti je storil Bog.« In ta je odšel svojo pot ter po vsem mestu razglašal kako velike stvari mu je storil Jezus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'In pripetilo se je, ko se je Jezus vrnil, da ga je množica veselo sprejela, kajti vsi so ga pričakovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'In glej, tja je prišel mož, po imenu Jaír in bil je predstojnik sinagoge in ta je padel dol k Jezusovim stopalom ter ga rotil, da bi prišel v njegovo hišo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'kajti imel je eno samo hčer, staro okoli dvanajst let in ta je umirala. Toda ko je šel, je množica pritiskala nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'In ženska, ki je dvanajst let imela težave s krvjo, ki je ves svoj dohodek potrošila za zdravnike niti je nihče ni mogel ozdraviti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'je prišla za njim ter se dotaknila roba njegove obleke in njena težava s krvjo se je takoj ustavila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, '§ In Jezus je rekel: »Kdo se me je dotaknil?« Ko so vsi zanikali, so Peter in tisti, ki so bili z njim, rekli: »Učitelj, množica te preriva in pritiska, ti pa praviš: ›Kdo se me je dotaknil?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jezus je rekel: »Nekdo se me je dotaknil, kajti zaznal sem, da je iz mene šla moč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'In ko je ženska videla, da ni bila skrita, je trepetajoč prišla in padla dol pred njim. Pred vsemi ljudmi mu je priznala, zaradi kakšnega razloga se ga je dotaknila in kako je bila takoj ozdravljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, '§ In rekel ji je: »Hči, bodi dobro potolažena. Tvoja vera te je ozdravila, pojdi v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Medtem ko je še govoril, pride tja nekdo iz hiše predstojnika sinagoge in mu reče: »Tvoja hči je mrtva, ne nadleguj Učitelja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ko je Jezus to slišal, mu je odgovoril, rekoč: »Ne boj se, samo veruj in ozdravela bo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'In ko je prišel v hišo, nobenemu človeku ni dovolil vstopiti noter, razen Petru, Jakobu in Janezu ter očetu in materi deklice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'In vsi so jokali ter jo objokovali, toda rekel je: »Ne jokajte. Ona ni mrtva, temveč spi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'In smejali so se mu do norčevanja, ker so vedeli, da je bila mrtva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'In vse jih je postavil ven, jo prijel za roko in jo poklical, rekoč: »Deklica, vstani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'In njen duh je ponovno prišel in nemudoma je vstala in ukazal je, naj ji dajo jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'In njena starša sta bila osupla, toda naročil jima je, naj nobenemu človeku ne povesta, kaj se je zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Potem je sklical skupaj svoje dvanajstere učence in jim dal moč in oblast nad vsemi hudiči in za ozdravljanje bolezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'In poslal jih je, da oznanjajo Božje kraljestvo in da ozdravljajo bolne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Rekel jim je: »Za svoje potovanje ne vzemite ničesar, niti palic, prav tako ne malhe, niti kruha, niti denarja, niti ne imejte vsak po dva plašča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'In v katerokoli hišo vstopite, tam ostanite in od tam odidite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Kdorkoli vas ne bo sprejel, kadar greste iz tega mesta, si iz svojih stopal otresite prav [ta] prah, v pričevanje proti njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'In odpravili so se in šli skozi mesta in oznanjali evangelij in povsod ozdravljali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Torej Herod, vladar četrtinskega dela province, je slišal o vsem, kar je bilo storjeno po njem; in bil je zmeden, zato ker so nekateri rekli, da je bil Janez obujen od mrtvih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'in od nekaterih, da se je pojavil Elija in od drugih, da je vstal eden izmed starih prerokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Herod pa je rekel: »Janeza sem jaz obglavil, toda kdo je ta, o katerem slišim takšne stvari?« In želel si je, da bi ga videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'In apostoli, ko so se vrnili, so mu povedali vse, kar so storili. In vzel jih je in odšel stran, na samo, v zapuščen kraj, ki je pripadal mestu z imenom Betsajda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Ko je množica to izvedela, mu je sledila in sprejel jih je ter jim govoril o Božjem kraljestvu in ozdravil te, ki so imeli potrebo po ozdravljenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'In ko je dan začel minevati, potem so prišli dvanajsteri ter mu rekli: »Pošlji množico proč, da lahko gredo v mesta in naokoli po deželi ter prenočijo in si preskrbijo živeža, kajti tukaj smo na samotnem kraju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Toda rekel jim je: »Vi jim dajte jesti.« Oni pa so rekli: »Nimamo več kot pet hlebov in dve ribi, razen, če bi šli in za vse te ljudi kupili hrano.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Kajti bilo jih je okoli pet tisoč mož. In svojim učencem je rekel: »Primorajte jih, da se usedejo v skupine po petdeset.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'In storili so tako in vse so primorali sesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Tedaj je vzel pet hlebov in dve ribi in jih, zroč k nebu, blagoslovil in razlomil in dal učencem, da jih postavijo pred množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'In jedli so in vsi so bili nasičeni. In od odlomkov, ki so jim ostali, je bilo nabranih dvanajst košar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'In pripetilo se je, ko je bil sam in molil, [da] so bili z njim njegovi učenci. In vprašal jih je, rekoč: »Kdo pravi množica, da sem jaz?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Rekli so in odgovorili: »›Janez Krstnik,‹ toda nekateri pravijo: ›Elija‹ in drugi pravijo, da je vstal eden izmed starih prerokov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Rekel jim je: »Toda kdo vi pravite, da sem jaz?« Peter mu reče in odgovori: »Kristus od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'In strogo jim je naročil in jim ukazal, da te besede ne povedo nobenemu človeku,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'rekoč: »Sin človekov mora pretrpeti mnoge stvari in biti zavrnjen od starešin in visokih duhovnikov in pisarjev in umorjen bo in tretji dan bo obujen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Njim vsem pa je rekel: »Če hoče katerikoli človek priti za menoj, naj se odpove samemu sebi in vsak dan vzame svoj križ ter mi sledi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Kajti kdorkoli hoče rešiti svoje življenje, ga bo izgubil, toda kdorkoli hoče izgubiti svoje življenje zaradi mene, ta isti ga bo rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Kajti kaj človeku koristi, če si pridobi ves svet, pa izgubi samega sebe ali je zavržen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Kajti kdorkoli se bo sramoval mene in mojih besed, njega se bo sramoval Sin človekov, ko bo prišel v svoji lastni slavi in v [slavi] svojega Očeta in svetih angelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Toda povem vam po resnici, tam bo nekaj tukaj navzočih, ki ne bodo okusili smrti, dokler ne bodo videli Božjega kraljestva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'In pripetilo se je okoli osmega dne po teh govorih, da je vzel Petra in Janeza in Jakoba ter odšel gor na goro, da moli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'In medtem ko je molil, je bil videz njegovega obličja predrugačen in njegova oblačila so bila bela in sijoča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'In glej, z njim sta govorila dva moža, ki sta bila Mojzes in Elija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Prikazala sta se v slavi in govorila o njegovem odhodu, ki naj bi ga dovršil v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Toda Peter in ta dva, ki sta bila z njim, so bili obteženi s spanjem. Ko so se zbudili, so videli njegovo slavo in dva moža, ki sta stala z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'In pripetilo se je, ko sta odšla od njega, da je Peter rekel Jezusu: »Učitelj, dobro je za nas, da smo tukaj. Naredimo tri šotore: enega zate in enega za Mojzesa in enega za Elija,« pa ni vedel, kaj je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Medtem ko je tako govoril, je prišel oblak in jih zasenčil in ko so vstopili v oblak, so se prestrašili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'In iz oblaka je prišel glas, rekoč: »Ta je moj ljubljeni Sin, njega poslušajte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'In ko je glas minil, se je Jezus znašel sam. Oni pa so [to] obdržali zase in v tistih dneh nobenemu človeku niso povedali o teh stvareh, ki so jih videli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'In pripetilo se je, da ga je naslednji dan, ko so prišli dol s hriba, srečalo mnogo ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'In glej, mož iz skupine je zavpil, rekoč: »Učitelj, rotim te, poglej na mojega sina, kajti on je moj edini otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'In glej, duh ga napada in nenadoma vpije in trga ga, da se ponovno peni in ko ga močno udari, odide od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'In rotil sem tvoje učence, da ga izženejo iz njega, pa niso mogli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jezus pa odgovori in reče: »O neverni in sprevrženi rod, kako dolgo bom še z vami in vas prenašal? Privedi svojega sina sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'In ko je šele prihajal, ga je hudič vrgel dol ter ga trgal. In Jezus je oštel nečistega duha in ozdravil otroka ter ga ponovno izročil njegovemu očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'In vsi so bili osupli nad mogočno Božjo močjo. Toda medtem ko so se vsi čudili ob vseh stvareh, ki jih je Jezus storil, je svojim učencem rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '»Naj te besede prodrejo v vaša ušesa, kajti Sin človekov bo izročen v človeške roke.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Toda tega govora niso razumeli in ta je bil skrit pred njimi, da ga niso zaznali in bali so se ga vprašati o tem govoru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Potem je med njimi nastalo razmišljanje, kdo izmed njih naj bi bil največji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'In Jezus, zaznavajoč misel njihovega srca, je vzel otroka ter ga postavil poleg sebe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'ter jim rekel: »Kdorkoli bo tega otroka sprejel v mojem imenu, sprejema mene in kdorkoli bo sprejel mene, sprejema tistega, ki me je poslal, kajti kdor je najmanjši med vami vsemi, ta isti bo velik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'In Janez je odgovoril ter rekel: »Učitelj, nekoga smo videli v tvojem imenu izganjati hudiče in smo mu prepovedali, ker ne hodi skupaj z nami.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, '§ Toda Jezus mu je rekel: »Ne prepovejte mu, kajti kdor ni proti nam, je za nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'In pripetilo se je, ko je prišel čas, da naj bi bil sprejet gor, se je on neomajno odločil, da gre v Jeruzalem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'in pred svojim obrazom je poslal poslance in ti so šli ter vstopili v vas Samarijanov, da pripravijo zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, '§ Oni pa ga niso sprejeli, ker je bil njegov obraz, kakor da hoče iti v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, '§ In ko sta njegova učenca, Jakob in Janez, to videla, sta rekla: »Gospod, hočeš, da ukaževa ognju, da pride dol z neba in jih pogoltne, kakor je storil Elija?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, '§ Toda on se je obrnil in ju oštel ter rekel: »Vidva ne vesta, iz kakšne vrste duha sta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, '§ Kajti Sin človekov ni prišel, da pokonča človeška življenja, temveč, da jih reši.« In odšli so v drugo vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'In pripetilo se je, ko so šli po poti, da mu je nek človek rekel: »Gospod, sledil ti bom, kamorkoli greš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'In Jezus mu je rekel: »Lisice imajo luknje in ptice neba imajo gnezda, toda Sin človekov nima kam nasloniti svoje glave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'In drugemu je rekel: »Sledi mi.« Vendar je ta rekel: »Gospod, dovoli mi najprej, da grem in pokopljem svojega očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Jezus mu je rekel: »Naj mrtvi pokopljejo svoje mrtve, ti pa pojdi in oznanjaj Božje kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Prav tako je rekel drugi: »Gospod, sledil ti bom, toda naj grem najprej in se poslovim od teh, ki so doma v moji hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'In Jezus mu je rekel: »Nihče, ki svojo roko položi na plug in gleda nazaj, ni primeren za Božje kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, '§ Po teh besedah je Gospod določil tudi drugih sedemdeset in jih poslal po dva in dva pred seboj v vsako mesto in kraj, kamor bi sam prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Zato jim je rekel: »Žetev je resnično velika, toda delavcev je malo. Prosite torej Gospoda žetve, da bi poslal delavce na svojo žetev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Pojdite [po] svojih poteh. Glejte, pošiljam vas kakor jagnjeta med volkove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne nosite niti mošnje niti malhe niti čevljev in po poti ne pozdravljajte nobenega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'In v katerokoli hišo vstopite, najprej recite: ›Mir bodi tej hiši.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'In če bo tam sin miru, bo vaš mir počival na njej; če ne, se bo ponovno obrnil k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'In v isti hiši ostanite, jejte in pijte te stvari, ki vam jih dajo, kajti delavec je vreden svojega plačila. Ne hodite od hiše do hiše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'In v katerokoli mesto vstopite in vas sprejmejo, jejte te stvari, ki so postavljene pred vas');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'in ozdravljajte bolne, ki so v njem in govorite jim: ›Božje kraljestvo je prišlo blizu k vam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Toda v katerokoli mesto vstopite in vas ne sprejmejo, pojdite po svojih poteh ven na ulice le-tega in recite:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '›Celo prav [ta] prah iz vašega mesta, ki se je [trdno] prilepil na nas, otresamo zoper vas. Vendar pa bodite prepričani o tem, da je Božje kraljestvo prišlo blizu k vam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Toda povem vam, da bo na tisti dan bolj znosno za Sódomo kakor za to mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Gorje ti, Horazín! Gorje ti, Betsajda! Kajti če bi bila ta mogočna dela, ki so bila storjena v tebi, storjena v Tiru in Sidónu, bi se že davno pokesala, sedeč v vrečevini in pepelu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Toda ob sodbi bo bolj znosno za Tir in Sidón kakor za vaju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'In ti Kafarnáum, ki si vzvišen do neba, boš pahnjen navzdol do pekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kdor posluša vas, posluša mene; kdor pa prezira vas, prezira mene; in kdor prezira mene, prezira tistega, ki me je poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, '§ In sedemdeset se jih je ponovno vrnilo z radostjo, rekoč: »Gospod, celó hudiči so nam pokorni v tvojem imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Rekel jim je: »Gledal sem Satana kakor bliskanje pasti z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, '§ Glejte, dajem vam oblast, da stopate na kače in škorpijone in čez vso sovražnikovo oblast in nič vam ne bo na kakršenkoli način škodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Vendar se ne veselite tega, da so vam duhovi podrejeni, temveč se raje veselite, ker so vaša imena zapisana v nebesih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'V tej uri se je Jezus razveselil v duhu in rekel: »Zahvaljujem se ti, oh Oče, Gospodar neba in zemlje, da si te besede skril pred modrimi in razsodnimi, razodel pa si jih otročičem. Točno tako, Oče, kajti tako je bilo videti dobro v tvojih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Vse stvari so mi izročene od mojega Očeta in noben človek ne ve, kdo je Sin, razen Očeta in kdo je Oče, razen Sina in tistega, ki mu ga bo Sin razodel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'In obrnil se je k svojim učencem in na samem rekel: »Blagoslovljene so oči, ki vidijo stvari, ki jih vi vidite,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'kajti povem vam, da je mnogo prerokov in kraljev želelo videti te stvari, ki jih vi vidite, pa jih niso videli, in slišati te besede, ki jih vi slišite, pa jih niso slišali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'In glej, nek izvedenec v postavi je vstal ter ga skušal, rekoč: »Učitelj, kaj naj storim, da podedujem večno življenje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Rekel mu je: »Kaj je zapisano v postavi? Kako bereš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'In ta odgovori in reče: »Gospoda svojega Boga boš ljubil z vsem svojim srcem in z vso svojo dušo in z vso svojo močjo in z vsem svojim mišljenjem, in svojega bližnjega kakor samega sebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'In rekel mu je: »Prav si odgovoril. To delaj in boš živel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Toda ker je hotel opravičiti samega sebe, je Jezusu rekel: »In kdo je moj bližnji?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'In Jezus mu odgovori ter reče: »Neki človek je šel iz Jeruzalema navzdol v Jeriho in padel med tatove, ki so mu slekli njegova oblačila in ga ranili in odšli ter ga pustili napol mrtvega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'In po naključju pride dol po tej poti nek duhovnik; in ko ga je zagledal, je po drugi strani šel mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'In podobno je Lévijevec, ko je bil na tem kraju, prišel ter pogledal nanj in šel mimo po drugi strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Toda nek Samarijan, ki je potoval, je prišel tja, kjer je bil, in ko ga je zagledal, je imel do njega sočutje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'in šel k njemu ter povezal njegove rane, izlivajoč vanje olja in vina in ga namestil na svojo lastno žival ter ga privedel do gostišča in zanj poskrbel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'In naslednjega dne, ko je odšel, je vzel ven dva denarja in ju dal gostilničarju ter mu rekel: ›Poskrbi zanj in karkoli porabiš več, ti bom poplačal, ko ponovno pridem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, '›Kaj meniš, kateri torej od teh treh je bil bližnji temu, ki je padel med tatove?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'In ta je rekel: »Kdor mu je izkazal usmiljenje.« Potem mu je Jezus rekel: »Pojdi in ti delaj enako.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Pripetilo se je torej, ko so šli, da je vstopil v neko vas in neka ženska, po imenu Marta, ga je sprejela v svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'In imela je sestro, po imenu Marija, ki je prav tako sedla k Jezusovim stopalom in poslušala njegovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Toda Marta je bila obremenjena glede tolikšne postrežbe in je prišla k njemu ter rekla: »Gospod, ti ni mar, da me je moja sestra pustila, da sama strežem? Ukaži ji vendar, naj mi pomaga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, '§ Jezus pa je odgovoril ter ji rekel: »Marta, Marta, vznemirjaš se in skrbiš glede mnogih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Toda ena stvar je potrebna in Marija si je izbrala ta dobri del, ki od nje ne bo odvzet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'In pripetilo se je, medtem ko je na nekem kraju molil, ko je prenehal, da mu je eden izmed njegovih učencev rekel: »Gospod, nauči nas moliti, kakor je tudi Janez naučil svoje učence.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, '§ Rekel jim je: »Kadar vi molite, recite: ›Naš Oče, ki si v nebesih: ›Posvečuje naj se tvoje ime. Pridi tvoje kraljestvo. Zgôdi se tvoja volja, kakor je v nebesih, tako na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Daj nam dan za dnem naš vsakdanji kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, '§ In odpusti nam naše grehe, kajti tudi mi odpuščamo vsakemu, ki nam je dolžan. In ne vôdi nas v skušnjavo, temveč nas osvobodi pred zlom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'In rekel jim je: »Kateri izmed vas bo imel prijatelja in bo šel k njemu ob polnoči ter mu rekel: ›Prijatelj, posodi mi tri hlebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'kajti moj prijatelj je na svojem potovanju prišel k meni, pa nimam ničesar, da postavim predenj?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'In ta od znotraj bo odgovoril ter rekel: ›Ne moti me. Vrata so sedaj zaprta in moji otroci so z menoj v postelji. Ne morem vstati in ti dati.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Povem vam: ›Čeprav ne bo vstal in mu dal, ker je njegov prijatelj, bo vendarle vstal zaradi njegove vsiljivosti ter mu dal toliko, kolikor potrebuje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'In jaz vam pravim: ›Prosite in to vam bo dano. Iščite in boste našli. Trkajte in to se vam bo odprlo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Kajti vsak, kdor prosi, prejema; in kdor išče, najde; in tistemu, ki trka, se bo odprlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, '§ Če bo sin kogarkoli izmed vas, ki je oče, prosil kruha ali mu bo dal kamen? Ali če prosi ribe ali mu bo namesto ribe dal kačo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ali če bo prosil jajce ali mu bo ponudil škorpijona?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Če torej vi, ki ste hudobni, veste kako dajati svojim otrokom dobre darove, koliko bolj bo vaš nebeški Oče dal Svetega Duha tistim, ki ga prosijo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'In izganjal je hudiča, ta pa je bil nem. In pripetilo se je, ko je hudič odšel ven, [da] je nemi spregovoril in množica se je čudila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Toda nekateri izmed njih so rekli: »Hudiče izganja preko Bélcebuba, vodilnega izmed hudičev.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'In drugi so ga skušali in od njega hoteli znamenje z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Vendar jim je on, ker je poznal njihove misli, rekel: »Vsako kraljestvo, razdvojeno zoper sebe, je privedeno v opustošenje; in hiša, razdvojena zoper hišo, pade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Če bi bil tudi Satan razdeljen zoper samega sebe, kako bi obstalo njegovo kraljestvo, ker pravite, da s pomočjo Bélcebuba izganjam hudiče?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'In če jaz z Bélcebubom izganjam hudiče, s kom [jih] izganjajo vaši sinovi? Zatorej bodo oni vaši sodniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, '§ Toda če jaz z Božjim prstom izganjam hudiče, je brez dvoma nad vas prišlo Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Ko močan mož oborožen čuva svojo palačo, so njegove dobrine v miru,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'toda ko bo nadenj prišel močnejši od njega in ga premagal, mu odvzame vso njegovo bojno opremo, v katero je zaupal in razdeli njegove plene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kdor ni z menoj, je proti meni, in kdor ne zbira z menoj, raztresa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Ko je nečisti duh odšel iz človeka, hodi skozi suhe kraje, iščoč počitka; ker pa ga ne najde, pravi: ›Vrnil se bom k svoji hiši, od koder sem prišel ven.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'In ko pride, jo najde pometeno in okrašeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tedaj gre in vzame k sebi sedem drugih duhov, zlobnejših kakor on sam; in vstopijo vanjo ter tam prebivajo in zadnje stanje tega človeka je hujše kakor prvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'In pripetilo se je, medtem ko je govoril te besede, [da] je neka ženska iz skupine povzdignila svoj glas in mu rekla: »Blagoslovljena je maternica te, ki te je nosila in prsi, ki si jih sesal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Toda rekel je: »Da, toliko bolj blagoslovljeni so tisti, ki poslušajo Božjo besedo in se je držijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'In ko je bila množica zbrana tesno skupaj, je začel govoriti: »To je hudoben rod. Iščejo znamenje, pa jim ne bo dano nobeno znamenje, razen znamenja preroka Jona.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Kajti kakor je bil Jona znamenje Ninivljanom, tako bo tudi Sin človekov temu rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Kraljica juga bo ob sodbi vstala z ljudmi tega rodu in jih obsodila, kajti prišla je iz skrajnih delov zemlje, da sliši Salomonovo modrost; in glejte, večji kakor Salomon je tukaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ljudje iz Niniv bodo ob sodbi vstali s tem rodom in ga obsodili, kajti pokesali so se ob Jonovem oznanjevanju; in glejte, večji kakor Jona je tukaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Nihče, ko je prižgal svetilko, je ne položi na skrivno mesto niti ne pod mernik, temveč na svečnik, da tisti, ki vstopajo, lahko vidijo svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, '§ Svetloba telesa je oko. Ko je torej tvoje oko enovito, je tudi tvoje celó telo polno svetlobe, toda kadar je tvoje oko hudobno, je tudi tvoje telo polno teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Pazite torej potemtakem, da svetloba, ki je v tebi, ne bo tema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Če je torej tvoje celotno telo polno svetlobe in nima nobenega dela temnega, bo vse polno svetlobe, kot kadar ti lesketajoče sijanje svečnika daje svetlobo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'In medtem ko je govoril, ga je nek farizej rotil, naj obeduje z njim. In vstopil je ter se usedel k obedu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Ko je farizej to videl, se je čudil, da se pred obedom ni najprej umil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Gospod pa mu je rekel: »Torej vi farizeji čistite zunanjost čaše in pladnja, toda vaš notranji del je poln požrešnosti in zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Vi bedaki, mar ni tisti, ki je naredil to, kar je zunaj, naredil tudi tega, kar je znotraj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Toda raje dajte miloščino od takih stvari, kot jih imate, in glejte, vse stvari so vam čiste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Toda gorje vam, farizeji! Kajti desetinite meto in ruto ter vse vrste zelišč, prezirate pa sodbo in Božjo ljubezen; te bi morali imeti narejene in ne pustiti drugih nenarejenih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Gorje vam, farizeji! Ker ljubite najvišje sedeže v sinagogah in pozdrave na trgih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, '§ Gorje vam, pisarji in farizeji, hinavci! Kajti vi ste kakor grobovi, ki se ne razločijo in ljudje, ki hodijo čeznje, se jih ne zavedajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Potem je odgovoril eden izmed izvedencev v postavi in mu rekel: »Učitelj, s takšnim govorjenjem grajaš tudi nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'On pa je rekel: »Gorje tudi vam, vi, izvedenci v postavi! Kajti ljudi natovarjate z bremeni, bridkimi za prenašanje, vi sami pa se niti z enim izmed svojih prstov ne dotaknete teh bremen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Gorje vam! Kajti prerokom gradite mavzoleje, vaši očetje pa so jih ubili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Resnično, vi pričujete, da odobravate dejanja svojih očetov; kajti zares so jih ubili, vi pa gradite njihove mavzoleje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Zaradi tega je tudi Božja modrost rekla: ›Poslala jim bom preroke in apostole in nekatere izmed njih bodo ubili in preganjali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'da bo od tega rodu lahko zahtevana kri vseh prerokov, ki je bila prelita od ustanovitve sveta;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'od krvi Abela do krvi Zaharija, ki je umrl med oltarjem in templjem.‹ Resnično, povem vam: ›Zahtevala se bo od tega rodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Gorje vam, izvedenci v postavi! Kajti odvzeli ste ključ spoznanja. Sami niste vstopili, tem, ki so vstopali, pa ste preprečevali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'In ko jim je povedal te besede, so ga pisarji in farizeji začeli silovito nagovarjati in ga izzivati, da bi govoril o mnogih stvareh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, '§ ker so prežali nanj in si prizadevali, da ujamejo kaj iz njegovih ust, da bi ga lahko obtožili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Medtem ko je bila tam skupaj zbrana brezštevilna množica ljudstva, do take mere, da so stopali drug po drugem, je najprej začel govoriti svojim učencem: »Pazite se kvasa farizejev, ki je hinavščina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Kajti nič ni prikrito, kar ne bo razkrito niti skrito, kar se ne bo izvedelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Zatorej karkoli ste govorili v temi, bo slišano na svetlobi; in to, kar ste govorili v sobicah na ušesa, bo razglašeno na hišnih strehah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Vam, svojim prijateljem, pa pravim: ›Ne bojte se teh, ki ubijejo telo in nató ne morejo nič več storiti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Toda posvaril vas bom, koga se bojte: ›Bojte se njega, ki ima, potem ko je ubil, oblast, da vrže v pekel.‹ Da, pravim vam: ›Bojte se ga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ali ni pet vrabcev prodanih za dva novčiča, pa niti eden izmed njih ni pozabljen pred Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Toda celó vsi lasje vaše glave so prešteti. Ne bojte se torej, vredni ste več kakor mnogo vrabcev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Prav tako vam pravim: ›Kdorkoli me bo priznal pred ljudmi, njega bo prav tako Sin človekov priznal pred Božjimi angeli,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'toda kdor me zanika pred ljudmi, bo zanikan pred Božjimi angeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'In kdorkoli bo govoril besedo zoper Sina človekovega, mu bo odpuščeno, toda tistemu, ki preklinja zoper Svetega Duha, ne bo odpuščeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'In ko vas privedejo v sinagoge in k sodnikom in oblastem, se ne vznemirjajte in ne skrbite kakšno ali katero besedo boste odgovorili ali kaj boste rekli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'kajti Sveti Duh vas bo v tej isti uri poučil, kaj morate reči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Eden iz skupine pa mu je rekel: »Učitelj, spregovori mojemu bratu, naj dediščino deli z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Rekel mu je: »Človek, kdo me je naredil sodnika ali delivca nad vama?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'In rekel jim je: »Pazite in čuvajte se pohlepnosti, kajti bistvo človeškega življenja ni v obilju stvari, ki jih poseduje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'In povedal jim je prispodobo, rekoč: »Zemlja nekega bogataša je obilno obrodila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'in mislil si je sam pri sebi, rekoč: ›Kaj bom storil, ker nimam prostora, kamor bi spravil svoje sadove?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Pa je rekel: ›To bom storil, podrl bom svoje skednje in zgradil večje in tja bom spravil vse svoje sadove in svoje dobrine.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Svoji duši pa bom rekel: ›Duša, veliko dobrin imaš spravljenih za mnogo let; vzemi si počitek, jej, pij in bodi vesela.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Toda Bog mu je rekel: ›Ti bedak, to noč bo tvoja duša zahtevana od tebe. Čigave bodo potem te stvari, ki si jih priskrbel?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tak je, kdor zaklade shranjuje zase, ni pa bogat pred Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Svojim učencem pa je rekel: »Zatorej vam pravim: ›Ne vznemirjajte se in ne skrbite za svoje življenje, kaj boste jedli; niti za telo, kaj boste oblekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Življenje je več kakor hrana in telo je več kakor oblačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Preudarite o krokarjih, kajti niti ne sejejo niti ne žanjejo; ki nimajo niti skladišča niti skednja, pa jih Bog hrani. Kako silno ste vi boljši kakor perjad?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, '§ In kdo izmed vas lahko z vznemirjanjem in skrbmi svoji postavi doda en komolec?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Če torej niste zmožni storiti te stvari, ki je najmanj pomembna, zakaj se vznemirjate in skrbite za ostalo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Preudarite lilije, kako rastejo; ne garajo, ne predejo in vendar vam jaz pravim, da Salomon v vsej svoji slavi ni bil oblečen kakor ena izmed teh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Če torej Bog tako oblači travo, ki je danes na polju in je jutri vržena v peč; kako mnogo bolj bo oblačil vas, oh vi maloverni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'In ne iščite, kaj boste jedli ali kaj boste pili niti ne bodite dvomljivega mišljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Kajti za vsemi temi stvarmi povprašujejo narodi sveta in vaš Oče ve, da imate potrebo za temi stvarmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Toda raje iščite Božje kraljestvo in vse te stvari vam bodo dodane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne bojte se, mali trop, kajti dobra volja vašega Očeta je, da vam da kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Prodajte, kar imate in dajte miloščino. Priskrbite si mošnje, ki ne ostarijo, zaklad v nebesih, ki ne izneveri, kjer se noben tat ne približa niti molj ne razkraja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Kajti kjer je vaš zaklad, tam bo tudi vaše srce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Naj bodo vaša ledja opasana in vaše svetilke prižgane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'vi sami pa podobni ljudem, ki čakajo na svojega gospodarja, kdaj se bo vrnil s poroke, da kadar pride in potrka, mu lahko takoj odprejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Blagoslovljeni so tisti služabniki, ki jih bo gospodar, ko pride, našel čuječe. Resnično, pravim vam, da se bo opasal in jih primoral, da se usedejo k obedu in bo prišel naprej ter jim stregel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'In če bo prišel ob drugi straži ali če pride ob tretji straži in jih najde takó, blagoslovljeni so tisti služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'In vedite to, da če bi hišni oče vedel, katero uro bi prišel tat, bi stražil in ne bi dovolil, da bi bila njegova hiša vlomljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Bodite torej tudi vi pripravljeni, kajti Sin človekov prihaja ob uri, za katero ne mislite.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Potem mu je Peter rekel: »Gospod, govoriš to prispodobo nam ali celó vsem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Gospod pa je rekel: »Kdo je potem tisti zvesti in modri oskrbnik, ki ga bo njegov gospodar naredil za vladarja nad njegovo družino, da jim ob pravšnjem obdobju da njihove deleže hrane?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Blagoslovljen je tisti služabnik, ki ga bo njegov gospodar, ko pride, našel tako početi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Resnično vam povem, da ga bo naredil za vladarja nad vsem, kar ima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Toda če pa ta služabnik v svojem srcu reče: ›Moj gospodar odlaša svoj prihod‹ in bo začel pretepati sluge in dekle, jesti in piti ter biti pijan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'bo gospodar tega služabnika prišel na dan, ko ga ne pričakuje in ob uri, ki se je ne zaveda in ga bo razsekal narazen ter mu določil njegov delež z neverniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Ta služabnik pa, ki je poznal voljo svojega gospodarja in se ni pripravil niti ni storil glede na njegovo voljo, bo pretepen z mnogimi udarci biča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Toda kdor ni vedel, pa je zagrešil stvari, vredne bičanja, bo pretepen z malo udarci biča. Kajti komurkoli je mnogo dano, se bo od njega mnogo zahtevalo, in komur so ljudje mnogo izročili, bodo od njega terjali tem več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Prišel sem, da pošljem ogenj na zemljo in kako si želim, da bi bil ta prižgan?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, '§ Toda imam krst, da bom z njim krščen in kako sem omejen, dokler se to ne dovrši!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Mislite, da sem prišel, da dam mir na zemljo? Povem vam: ›Ne, temveč prej razkol,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'kajti odslej jih bo v eni hiši pet razdeljenih, trije proti dvema in dva proti trem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Oče bo razdeljen proti sinu in sin proti očetu; mati proti hčeri in hči proti materi; tašča proti snahi in snaha proti svoji tašči.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Množici pa je rekel tudi: ›Ko vidite oblak dvigati se iz zahoda, nemudoma pravite: ›Dež prihaja,‹ in tako se zgodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'In ko vidite pihati južni veter, pravite: ›Vroče bo,‹ in tako se pripeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Vi hinavci, lahko razpoznate obličje neba in zemlje, toda kako to, da ne razpoznate tega časa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Da, in zakaj celó sami od sebe ne sodite, kar je prav?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Ko greš s svojim nasprotnikom k oblastniku, ko si še na poti, se posveti prizadevanju, da boš lahko osvobojen pred njim; da te ta ne bi privlekel k sodniku in sodnik te izroči častniku, častnik pa te vrže v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Povem ti; ne boš odšel od tam, dokler ne odplačaš tudi zadnjega kovanca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Ob tistem času jih je bilo tam prisotnih nekaj, ki so mu povedali o Galilejcih, katerih kri je Pilat pomešal z njihovimi žrtvami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Jezus pa jim odgovori in reče: »Mislite, da so bili ti Galilejci večji grešniki kakor vsi Galilejci, ker so pretrpeli te stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Povem vam: ›Ne. Toda razen če se ne pokesate, boste vsi enako pokončani.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ali tistih osemnajst, na katere je padel stolp v Síloi in jih usmrtil, mislite, da so bili večji grešniki od vseh ljudi, ki prebivajo v Jeruzalemu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Povem vam: ›Ne. Toda razen če se ne pokesate, boste vsi enako pokončani.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Povedal je tudi to prispodobo: »Neki človek je imel v svojem vinogradu posajeno figovo drevo in je prišel ter na njem iskal sadeža, pa ni našel nobenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Potem je rekel obrezovalcu trte svojega vinograda: ›Glej, ta tri leta sem prihajal in iskal sadu na tem figovem drevesu, pa ga nisem našel. Posekaj ga, čemú bremeni zemljo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Ta pa odgovori in mu reče: ›Gospod, pusti jo še letos, da jo okopljem in pognojim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'in če obrodi sad, dobro, če pa ne, jo boš torej potem posekal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'In na šabat je učil v eni izmed sinagog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'In glej, tam je bila ženska, ki je osemnajst let imela duha šibkosti in je bila sključena in se nikakor ni mogla sama vzravnati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'In ko jo je Jezus zagledal, jo je poklical k sebi ter ji rekel: »Ženska, odvezana si od svoje šibkosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'In nanjo je položil svoje roke in takoj je postala vzravnana ter slavila Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Predstojnik sinagoge pa je odgovoril z ogorčenjem, zato ker je Jezus zdravil na šabatni dan in rekel množici: »Šest dni je, v katerih morajo ljudje delati, v teh torej pridite in bodite zdravljeni, ne pa na šabatni dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Potem mu je Gospod odgovoril in rekel: » Ti hinavec ali ne odveže vsak izmed vas na šabat svojega vola ali svojega osla od jasli in ga vodi proč napajat?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'In ali ne bi morala biti ta ženska, ki je Abrahamova hči, ki jo je imel Satan zvezano, glejte, teh osemnajst let, odvezana te vezi na šabatni dan?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Ko je povedal te stvari, so bili vsi njegovi nasprotniki osramočeni in vsa množica se je veselila zaradi vseh teh veličastnih stvari, ki so bile narejene po njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Tedaj je rekel: »Čému je podobno Božje kraljestvo? In s čim naj ga primerjam?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Podobno je zrnu gorčičnega semena, ki ga je človek vzel in ga vrgel na svoj vrt, in to je zraslo ter se razvilo v veliko drevo in na njegovih mladikah je prenočevala perjad neba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'In ponovno je rekel: »Čému naj primerjam Božje kraljestvo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Podobno je kvasu, ki ga je ženska vzela in skrila v treh merah moke, dokler ni bilo vse prekvašeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'On pa je šel skozi mesta in vasi ter učil in potoval proti Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Tedaj mu je nekdo rekel: »Gospod ali je malo teh, ki bodo rešeni?« On pa jim je rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '»Prizadevajte si, da vstopite pri ozkih vratih, kajti povem vam, mnogi bodo poskušali vstopiti, pa ne bodo mogli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Ko enkrat hišni gospodar vstane in zapre vrata, pričnete stati zunaj ter trkati na vrata, rekoč: ›Gospod, Gospod, odpri nam,‹ on pa vam bo odgovoril in rekel: ›Ne poznam vas, od kod ste.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tedaj boste začeli govoriti: ›V tvoji prisotnosti smo jedli in pili in na naših ulicah si učil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Toda rekel vam bo: ›Povem vam, ne vem, od kod ste; odidite od mene, vsi vi delavci krivičnosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tam bo jokanje in škripanje z zobmi, ko boste videli Abrahama, Izaka in Jakoba ter vse preroke v Božjem kraljestvu, vas same pa pahnjene ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'In prišli bodo od vzhoda in od zahoda in od severa in od juga in usedli se bodo v Božjem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'In glej, so zadnji, ki bodo prvi in so prvi, ki bodo zadnji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Istega dne so prišli tja nekateri izmed farizejev, rekoč mu: »Pojdi ven in odidi od tod, kajti Herod te hoče ubiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, '§ On pa jim je rekel: »Pojdite in povejte temu lisjaku: ›Glej, izganjam hudiče in ozdravljam danes in jutri, tretji dan pa bom dovršen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Vendar moram danes in jutri in naslednji dan hoditi, kajti ni mogoče, da prerok umre zunaj Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Oh Jeruzalem, Jeruzalem, ki ubijaš preroke in kamnaš tiste, ki so poslani k tebi; kako pogosto sem hotel zbrati tvoje otroke skupaj, kakor koklja zbira svoj zarod pod svoje peruti, pa niste hoteli!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Glejte, vaša hiša vam ostane zapuščena in resnično vam pravim: ›Ne boste me videli, dokler ne pride čas, ko boste rekli: ›Blagoslovljen je, kdor prihaja v Gospodovem imenu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'In pripetilo se je, medtem ko je odšel v hišo enega izmed vodilnih farizejev, da bi na šabatni dan jedel kruh, da so ga ti opazovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'In glej, pred njim je bil nek človek, ki je imel vodenico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'In Jezus je izvedencem v postavi in farizejem odgovarjal ter govoril, rekoč: »Ali je zakonito zdraviti na šabatni dan?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Oni pa so molčali. In prijel ga je in ozdravil ter ga pustil oditi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, '§ in odgovoril jim je, rekoč: »Komu izmed vas pade osel ali vol v jamo in ga ne bo nemudoma, na šabatni dan, izvlekel ven?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'In ponovno mu niso mogli odgovoriti na te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'In ko je opazil, kako izbirajo vodilna mesta, je tem, ki so bili povabljeni, podal prispodobo, rekoč jim:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '»Kadar te katerikoli človek povabi na poroko, se ne usedi na najvišje mesto, da ne bi le-ta povabil častitljivejšega človeka, kakor si ti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'in ne bi prišel ta, ki je povabil tebe in njega in ti rekel: ›Daj prostor temu človeku,‹ ti pa si boš s sramoto začel jemati najnižji prostor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Toda kadar si povabljen, pojdi in se usedi na najnižji prostor, da ti lahko reče, kdor te je povabil, ko pride k tebi: ›Prijatelj, pojdi višje,‹ potem boš imel oboževanje v prisotnosti teh, ki s teboj sedijo pri obedu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Kajti kdorkoli se povišuje, bo ponižan, kdor pa se ponižuje, bo povišan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Potem je prav tako rekel tistemu, ki ga je povabil: »Kadar pripravljaš kosilo ali večerjo, ne pokliči svojih prijateljev, niti svojih bratov, niti svojih sorodnikov, niti svojih bogatih sosedov, da te ne bi tudi oni povabili in ti povrnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Toda kadar pripravljaš pojedino, pokliči revne, pohabljene, hrome, slepe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'in boš blagoslovljen, ker ti ne morejo poplačati, kajti poplačano ti bo ob vstajenju pravičnih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'In ko je eden izmed teh, ki je pri obedu sedel z njim, slišal te stvari, mu je rekel: »Blagoslovljen je, kdor bo jedel kruh v Božjem kraljestvu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'On pa mu je potem rekel: »Neki človek je priredil veliko večerjo in povabil mnoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Ob času večerje pa je poslal svojega služabnika, da pove tem, ki so bili povabljeni: ›Pridite, kajti sedaj so vse stvari pripravljene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Vsi pa so se začeli soglasno opravičevati. Prvi mu je rekel: ›Kupil sem kos zemlje in nujno ga moram iti pogledat. Prosim te, imej me za opravičenega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'In drugi je rekel: ›Kupil sem pet jarmov volov in grem, da jih preizkusim. Prosim te, imej me za opravičenega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'In drugi je rekel: ›Poročil sem ženo in zato ne morem priti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Tako, da je ta služabnik prišel in te stvari sporočil svojemu gospodarju. Potem je hišni gospodar jezen rekel svojemu služabniku: ›Pojdi hitro ven na ulice in mestne ceste ter pripelji sèm revne in pohabljene in šepave in slepe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'In služabnik je rekel: ›Gospod, narejeno je, kakor si zapovedal in še je prostor.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'In gospodar je rekel služabniku: ›Pojdi ven na glavne ceste ter ograje in jih prisili, da vstopijo, da se bo moja hiša lahko napolnila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Kajti povem vam: ›Da nihče izmed tistih ljudi, ki so bili povabljeni, ne bo okusil moje večerje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'In z njim so šle velike množice, on pa se je obrnil in jim rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '»Če katerikoli človek pride k meni in ne sovraži svojega očeta in matere in žene in otrok in bratov in sester, da in tudi svojega lastnega življenja, ne more biti moj učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'In kdorkoli ne nosi svojega križa in ne sledi meni, ne more biti moj učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Kajti kdo izmed vas, ki hoče zgraditi stolp, se prej ne usede in ne prešteje stroška, ali ima zadosti, da ga dokonča?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Da ga ne bi morda potem, ko je položil temelj, pa ga ne bi bil zmožen dokončati, vsi tisti, ki so to gledali, začeli zasmehovati,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'rekoč: ›Ta človek je začel graditi, pa ni bil zmožen dokončati.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ali kateri kralj, ki pripravlja vojno proti drugemu kralju, prej ne séde in se posvetuje, če bo zmožen z deset tisoči srečati tistega, ki prihaja nadenj z dvajsetimi tisoči?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Sicer, dokler je drugi še daleč, on pošlje poslanstvo in prosi pogoje za mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Torej podobno, kdorkoli izmed vas, ki ne zapusti vsega, kar ima, ne more biti moj učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Sol je dobra, toda če je sol izgubila svoj okus, s čim se bo začinila?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Niti ni primerna za zemljo niti za gnojišče, temveč jo ljudje mečejo ven. Kdor ima ušesa, da slišijo, naj posluša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Potem so se mu približali vsi davkarji in grešniki, da bi ga poslušali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Farizeji in pisarji pa so godrnjali, rekoč: »Ta človek sprejema grešnike in z njimi jé.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Povedal pa jim je to prispodobo, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '»Kateri mož izmed vas, ki ima sto ovac, če izgubi eno izmed njih, ali ne bo zapustil devetindevetdesetih v divjini in šel za to, ki je izgubljena, dokler je ne najde?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'In ko jo najde, jo vesel naprti na svoja ramena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'In ko pride domov, skliče skupaj svoje prijatelje ter sosede, rekoč jim: ›Veselite se z menoj, kajti našel sem svojo ovco, ki je bila izgubljena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Povem vam, da bo na nebu podobna radost nad enim grešnikom, ki se pokesa, bolj kakor nad devetindevetdesetimi pravičnimi osebami, ki ne potrebujejo kesanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ali katera ženska, ki ima deset koščkov srebra, če izgubi en košček ali ne prižge svetilke in ne pomete hiše in marljivo išče, dokler ga ne najde?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Ko pa ga je našla, skliče skupaj svoje prijateljice in svoje sosede, rekoč: ›Veselite se z menoj, kajti našla sem košček, ki sem ga izgubila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Povem vam, enaka radost je v prisotnosti Božjih angelov nad enim grešnikom, ki se pokesa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'In rekel je: »Neki človek je imel dva sina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'in mlajši izmed njiju je rekel svojemu očetu: ›Oče, daj mi moj delež dobrin, ki mi pripadajo.‹ In razdelil jima je svoja sredstva za preživljanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Ne veliko dni kasneje pa je mlajši sin zbral vse skupaj in šel na pot v daljno deželo in tam z razuzdanim življenjem potrošil svoje imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Ko pa je vse zapravil, je v tej deželi nastala silna lakota in začel je živeti v pomanjkanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'In odšel je ter se pridružil meščanu te dežele, ta pa ga je poslal na svoja polja, da pase svinje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Svoj trebuh pa si je želel napolniti z luščinami, ki so jih jedle svinje, pa mu [jih] nihče ni dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, '§ Ko pa je prišel k sebi, je rekel: ›Koliko najetih služabnikov mojega očeta ima kruha na pretek, jaz pa umiram od lakote!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Vstal bom ter odšel k svojemu očetu in mu bom rekel: ›Oče, grešil sem zoper nebo in pred teboj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'in nisem več vreden, da bi se imenoval tvoj sin. Naredi me kakor enega svojih najetih služabnikov.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'In vstal je ter prišel k svojemu očetu. Toda ko je bil še daleč, ga je njegov oče zagledal ter imel sočutje in pritekel ter se oklenil njegovega vratu in ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Sin pa mu je rekel: ›Oče, grešil sem zoper nebo in v tvojih očeh in nisem več vreden, da bi se imenoval tvoj sin.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Toda oče je svojim služabnikom rekel: ›Prinesite najboljše svečano oblačilo in ga nadenite nanj in na njegovo roko dajte prstan ter čevlje na njegova stopala');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'in privedite sèm pitano tele in ga zakoljite in jejmo ter bodimo veseli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'kajti ta moj sin je bil mrtev, pa je ponovno živ; bil je izgubljen, pa je najden.‹ In začeli so se veseliti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Torej njegov starejši sin je bil na polju. Ko pa je prišel ter se bližal hiši, je zaslišal glasbo in ples.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'In poklical je enega izmed služabnikov in vprašal, kaj pomenijo te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'In ta mu je rekel: ›Tvoj brat je prišel in tvoj oče je zaklal pitano tele, ker ga je prejel živega in zdravega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'In bil je jezen in ni hotel vstopiti, zato je njegov oče prišel ven ter ga povabil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'In odgovoril je in rekel svojemu očetu: ›Glej! Ta mnoga leta ti služim niti nisem kadarkoli prestopil tvoje zapovedi, pa mi vendarle še nikoli nisi dal kozlička, da bi se s svojimi prijatelji lahko poveselil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'toda takoj, ko je prišel ta tvoj sin, ki je z vlačugami požrl tvoja sredstva za preživljanje, si zanj zaklal pitano tele.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'On pa mu je rekel: ›Sin, ti si vedno z menoj in vse, kar imam, je tvoje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Primerno je bilo, da bi se poveselili in bili veseli, kajti ta tvoj brat je bil mrtev, pa je ponovno živ; in bil je izgubljen, pa je najden.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Svojim učencem pa je prav tako rekel: »Bil je nek bogataš, ki je imel oskrbnika in ta isti mu je bil zatožen, da je zapravljal njegove dobrine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'In poklical ga je ter mu rekel: ›Kako to, da to slišim o tebi? Daj mi obračun svojega oskrbništva, kajti ne boš več mogel biti oskrbnik.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Potem je oskrbnik sam pri sebi rekel: ›Kaj naj storim? Kajti moj gospodar od mene jemlje oskrbništvo; kopáti ne morem, prositi me je sram.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Odločil sem se kaj storiti, da me bodo lahko sprejeli v svoje hiše, ko bom odstavljen od oskrbništva.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Tako je k sebi poklical vsakega izmed dolžnikov svojega gospodarja in rekel prvemu: ›Koliko dolguješ mojemu gospodarju?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'In ta je rekel: ›Sto meric olja.‹ Rekel mu je: ›Vzemi svojo zadolžnico in hitro sedi ter zapiši petdeset.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Potem je rekel drugemu: ›In koliko dolguješ ti?‹ In ta je rekel: ›Sto meric pšenice.‹ In rekel mu je: ›Vzemi svojo zadolžnico in zapiši osemdeset.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'In gospodar je pohvalil nepravičnega oskrbnika, ker je modro ravnal, kajti otroci tega sveta so v svojem rodu modrejši od otrok svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'In pravim vam: ›Prijatelje si pridobivajte s krivičnim mamonom, da vas, ko padete, lahko sprejmejo v večna prebivališča.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kdor je zvest v tem, kar je najmanjše, je zvest tudi v velikem; kdor pa je nepravičen v najmanjšem, je nepravičen tudi v velikem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Če torej niste bili zvesti s krivičnim mamonom, kdo bo vašemu zaupanju poveril resnična bogastva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'In če niste bili zvesti s tem, kar je od drugih ljudi, kdo vam bo dal to, kar je vaše?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Noben služabnik ne more služiti dvema gospodarjema, ker ali bo enega sovražil in drugega ljubil, ali pa se bo držal k enemu in preziral drugega. Ne morete služiti Bogu in mamonu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'In tudi farizeji, ki so bili lakomni, so slišali vse te stvari in ga zasmehovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Rekel jim je: »Vi ste tisti, ki sebe opravičujete pred ljudmi, toda Bog pozna vaša srca, kajti to, kar je zelo cenjeno med ljudmi, je v Božjih očeh ogabnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Postava in preroki so bili do Janeza. Od tedaj se oznanja Božje kraljestvo in vsak pritiska vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Lažje pa je za nebo in zemljo, da preideta, kakor da manjka ena pičica postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Kdorkoli odslovi svojo ženo in poroči drugo, zagreši zakonolomstvo, in kdorkoli poroči njo, ki jo je njen soprog odslovil, zagreši zakonolomstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Bil je nek bogataš, ki je bil oblečen v škrlat in tanko laneno platno in vsak dan razkošno jedel in pil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'in bil je nek berač, po imenu Lazar, ki je bil poln vnetij položen pred njegova velika vrata');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'in želel je biti nahranjen z drobtinami, ki so padale z bogataševe mize; poleg tega so prišli psi in lizali njegova vnetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Pripetilo pa se je, da je berač umrl in angeli so ga odnesli v Abrahamovo naročje, in tudi bogataš je umrl ter bil pokopan');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, '§ in v peklu je povzdignil svoje oči, medtem ko je bil mučen in daleč stran zagledal Abrahama in Lazarja v njegovem naročju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'In zaklical je ter rekel: ›Oče Abraham, usmili se me in pošlji Lazarja, da bi lahko konico svojega prsta pomočil v vodo in ohladil moj jezik, kajti mučen sem v tem plamenu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Toda Abraham je rekel: ›Sin, spomni se, da si v svojem življenju prejemal svoje dobre stvari in prav tako Lazar zle stvari; toda on je sedaj potolažen, ti pa si mučen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Poleg vsega tega pa je med nami in teboj velik, nespremenljiv prepad, tako da tisti, ki bi hoteli prečkati od tod k vam, ne morejo niti oni ne morejo prečkati k nam, da bi prišli od tam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Potem je rekel: ›Prosim te torej oče, da ga pošlješ k hiši mojega očeta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'kajti pet bratov imam, da jim bo lahko pričeval, da ne bi tudi oni prišli v ta kraj mučenja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham mu reče: ›Imajo Mojzesa in preroke, naj njih poslušajo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Ta pa je rekel: ›Ne, oče Abraham, toda če gre k njim kdo od mrtvih, se bodo pokesali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'On pa mu je rekel: ›Če ne poslušajo ne Mojzesa in ne prerokov, ne bodo pregovorjeni, četudi nekdo vstane od mrtvih.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Potem je rekel učencem: »Ni mogoče, da prestopki ne bi prišli, toda gorje tistemu, po katerem bodo prišli!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Bolje bi bilo zanj, da bi bil mlinski kamen obešen okoli njegovega vratu, on sam pa vržen v morje, kakor da bi pohujšal enega od teh malčkov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Pazite se: ›Če se tvoj brat prekrši zoper tebe, ga oštej; če pa se pokesa, mu odpusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'In če se sedemkrat dnevno prekrši zoper tebe in se sedemkrat dnevno ponovno obrne k tebi, rekoč: ›Kesam se,‹ mu boš odpustil.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'In apostoli so rekli Gospodu: »Povečaj našo vero.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Gospod pa je rekel: »Če bi imeli vero kakor zrno gorčičnega semena, bi lahko rekli temu drevesu črne murve: ›Bodi izruvana s korenino in bodi posajena v morje‹ in bi vam bila pokorna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Toda kdo izmed vas, ki ima služabnika, ki orje ali pase živino, mu bo v kratkem, ko pride iz polja, rekel: ›Pojdi in sedi k obedu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'In ali mu ne bo raje rekel: ›Pripravi mi nekaj, da bom lahko večerjal in se opaši ter mi strezi, dokler se ne najem in napijem, potem pa boš ti jedel in pil?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Mar se bo zahvalil temu služabniku, ker je storil stvari, ki so mu bile ukazane? Menim, da ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tako tudi vi, ko boste naredili vse te stvari, ki so vam ukazane, recite: ›Nekoristni služabniki smo. Naredili smo to, kar je bila naša dolžnost, da storimo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'In pripetilo se je, ko je šel v Jeruzalem, da je šel čez sredo Samarije in Galileje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'In ko je vstopil v neko vas, ga je tam srečalo deset mož, ki so bili gobavi, ki so stali daleč stran');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'in povzdignili so svoje glasove ter rekli: »Jezus, Učitelj, usmili se nas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'In ko jih je zagledal, jim je rekel: »Pojdite, pokažite se duhovnikom.« In pripetilo se je, da ko so šli, so bili očiščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'In ko je eden izmed njih videl, da je bil ozdravljen, se je obrnil nazaj in z močnim glasom slavil Boga');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'in pri njegovih stopalih je padel dol na svoj obraz in mu dal zahvalo; in ta je bil Samarijan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'In Jezus odgovori ter reče: »Mar ni bilo tu deset očiščenih? Toda kje je onih devet?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nikogar ni najti, ki bi se vrnil, da izroči slavo Bogu, razen tega tujca.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, '§ In rekel mu je: »Vstani, pojdi svojo pot, tvoja vera te je naredila zdravega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'In ko so ga farizeji povprašali, kdaj naj bi prišlo Božje kraljestvo, jim je odgovoril in rekel: »Božje kraljestvo ne prihaja z opazovanjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, '§ tudi ne bodo rekli: ›Glejte, tukaj!‹ ali: ›Glejte tam!‹ kajti glejte, Božje kraljestvo je znotraj vas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Učencem pa je rekel: »Prišli bodo dnevi, ko boste želeli videti enega izmed dni Sina človekovega, pa ga ne boste videli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'In govorili vam bodo: ›Glejte tukaj‹ ali: ›Glejte tam.‹ Ne hodite za njimi niti jim ne sledite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Kajti kakor bliskanje, ki zasveti iz enega konca pod nebom, sveti do drugega konca pod nebom, tako bo tudi Sin človekov na svoj dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Toda najprej mora pretrpeti mnoge stvari in biti zavržen od tega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'In kakor je bilo v Noetovih dneh, takó bo tudi v dneh Sina človekovega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Jedli so, pili, poročali so žene, dane so bile v zakon, vse do dne, ko je Noe vstopil v barko in je prišla poplava ter jih vse uničila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Podobno bo, kot je bilo v Lotovih dneh; jedli so, pili, kupovali, prodajali, sadili, zidali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'toda istega dne, ko je Lot odšel iz Sódome, sta z neba deževala ogenj in žveplo ter jih vse uničila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Točno takó bo na dan, ko se razodene Sin človekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Na tisti dan naj tisti, ki bo na hišni strehi in njegove stvari v hiši, ne pride dol, da jih vzame proč; in kdor je na polju, naj se prav tako ne vrača nazaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Spomnite se Lotove žene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kdorkoli si bo prizadeval rešiti svoje življenje, ga bo izgubil; kdorkoli pa bo izgubil svoje življenje, ga bo ohranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Povem vam, v tej noči bosta dva človeka na eni postelji; eden bo vzet, drugi pa puščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dve ženski bosta skupaj mleli; ena bo vzeta, druga pa puščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '§ Dva moža bosta na polju; eden bo vzet, drugi pa puščen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'In odgovorili so mu ter rekli: »Kje, Gospod?« In on jim je rekel: »Kjerkoli je telo, tam bodo orli zbrani skupaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'In povedal jim je priliko zato, da morajo ljudje vedno moliti in ne izgubiti poguma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'rekoč: »V mestu je bil sodnik, ki se ni bal Boga niti se ni oziral na človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'In v tistem mestu je bila vdova in prišla je k njemu, rekoč: ›Maščuj me pred mojim nasprotnikom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'On pa nekaj časa ni hotel, toda kasneje si je sam pri sebi rekel: ›Čeprav se ne bojim Boga niti se ne oziram na človeka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'vendarle, ker me ta vdova nadleguje, ji bom izvršil pravico, da me s svojim nenehnim prihajanjem ne bi izmučila.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Gospod pa je rekel: »Poslušajte, kaj pravi nepravični sodnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'In ali ne bo Bog maščeval svojih lastnih izvoljenih, ki dan in noč vpijejo k njemu, čeprav jih dolgo prenaša?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Povem vam, da jih bo naglo maščeval. Vendar ko pride Sin človekov, ali bo našel vero na zemlji?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Nekaterim pa, ki so zaupali sami vase, da so bili pravični in so prezirali druge, je povedal to prispodobo:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '»Dva človeka sta šla gor v tempelj molit: en farizej, drugi pa davkar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Farizej je stal in sam s seboj takole molil: ›Bog, zahvaljujem se ti, ker nisem kakor so drugi ljudje, izsiljevalci, nepravični, zakonolomci ali celó kakor ta davkar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Postim se dvakrat tedensko, desetine dajem od vsega, kar imam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Davkar pa, ki je stal daleč stran, ni hotel niti svojih oči povzdigniti k nebu, temveč se je udarjal po svojih prsih, rekoč: ›Bog bodi usmiljen meni grešniku.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Povem vam, ta človek je odšel dol k svoji hiši toliko bolj opravičen kakor drugi, kajti vsak, kdor sebe povišuje, bo ponižan; kdor pa sebe ponižuje, bo povišan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'K njemu pa so privedli tudi otročiče, da bi se jih dotaknil, toda ko so njegovi učenci to videli, so jih ošteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Toda Jezus jih je poklical k sebi in rekel: »Dovolite majhnim otrokom prihajati k meni in ne prepovejte jim, kajti takšnih je Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Resnično, povem vam: ›Kdorkoli ne bo sprejel Božjega kraljestva kakor majhen otrok, nikakor ne bo vstopil vanj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'In nek vladar ga je vprašal, rekoč: »Dobri Učitelj, kaj naj storim, da bom podedoval večno življenje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jezus pa mu je rekel: »Zakaj me kličeš dober? Nihče ni dober, razen enega, to je Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Zapovedi poznaš: ›Ne zagreši zakonolomstva,‹ ›Ne ubijaj,‹ ›Ne kradi,‹ ›Ne pričaj po krivem,‹ ›Spoštuj svojega očeta in svojo mater.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'On pa je rekel: »Vsega tega sem se držal od svoje mladosti dalje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Torej ko je Jezus slišal te besede, mu je rekel: »Vendarle ti manjka ena stvar. Prodaj vse, kar imaš in razdeli revnim in imel boš zaklad v nebesih in pridi, hodi za menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'In ko je oni to slišal, je bil zelo žalosten, kajti bil je zelo bogat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'In ko je Jezus videl, da je bil zelo žalosten, je rekel: »Kako težko bodo tisti, ki imajo bogastva, vstopili v Božje kraljestvo!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Kajti lažje je za kamelo, da gre skozi šivankino uho, kakor za bogataša vstopiti v Božje kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Tisti pa, ki so to slišali, so rekli: »Kdo je potem lahko rešen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'In rekel je: »Stvari, ki so nemogoče z ljudmi, so mogoče z Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Potem je Peter rekel: »Glej! Vse smo zapustili in ti sledili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'In rekel jim je: »Resnično, povem vam: ›Ni človeka, ki je zapustil hišo ali starše ali brate ali ženo ali otroke zaradi Božjega kraljestva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'ki ne bo prejel mnogokrat več v tem sedanjem času in večno življenje v svetu, ki pride.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Potem je k sebi vzel dvanajstere in jim rekel: »Glejte, mi gremo gor v Jeruzalem in vse besede, ki so glede Sina človekovega napisane po prerokih, se bodo dovršile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Kajti izročen bo poganom in bo zasmehovan in hudobno tretiran ter opljuvan,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'pa tudi bičali ga bodo in usmrtili in tretji dan bo ponovno vstal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Oni pa niso razumeli nobene od teh besed in ta govor je bil skrit pred njimi niti niso razumeli besed, ki so bile izgovorjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'In pripetilo se je, da ko je prišel blizu Jerihe, da je ob poti sedèl nek slepi mož ter beračil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'In ko je slišal iti mimo množico, je vprašal, kaj je to pomenilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'In povedali so mu, da gre mimo Jezus Nazarečan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'In ta je zavpil, rekoč: »Jezus, ti Davidov Sin, usmili se me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Tisti pa, ki so hodili spredaj, so ga ošteli, da naj molči, toda on je bolj in bolj vpil: » Ti, Davidov Sin, usmili se me.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'In Jezus se je ustavil ter ukazal, naj bo priveden k njemu in ko je ta prišel bliže, ga je vprašal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'rekoč: »Kaj hočeš, da naj ti storim?« On pa je rekel: »Gospod, da lahko prejmem svoj vid.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Jezus mu je rekel: »Prejmi svoj vid, tvoja vera te je rešila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'In takoj je prejel svoj vid in mu sledil ter proslavljal Boga. In ko so vsi ljudje to videli, so dali hvalo Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'In Jezus je vstopil [v Jeriho] in šel skozi Jeriho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'In glej, tam je bil mož, imenovan Zahej, ki je bil šef med davkarji in je bil bogat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'In prizadeval si je, da bi videl, kdo je bil Jezus, pa ni mogel zaradi množice, ker je bil majhne postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'In stekel je naprej ter splezal na egiptovsko smokvo, da bi ga videl, kajti moral bi iti mimo po tej poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Ko je Jezus prišel na ta kraj, je pogledal gor, ga zagledal in mu rekel: »Zahej, podvizaj se in pridi dol, kajti danes moram ostati v tvoji hiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'In ta je pohitel in prišel dol ter ga radostno sprejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'In ko so to videli, so vsi godrnjali, rekoč: »Ta je odšel, da bi bil gost pri človeku, ki je grešnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zahej pa je vstal in rekel Gospodu: »Glej, Gospod, polovico svojih dobrin dam revnim in če sem po krivem obtožen, da sem karkoli vzel od kateregakoli človeka, mu štirikratno povrnem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jezus pa mu je rekel: »Ta dan je prišla k tej hiši rešitev duše, glede na to, da je tudi on Abrahamov sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Kajti Sin človekov je prišel, da poišče in da reši to, kar je bilo izgubljeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'In medtem ko so slišali te stvari, je dodal in povedal prispodobo, kajti bil je blizu Jeruzalema in ker so mislili, da naj bi se Božje kraljestvo prikazalo takoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Rekel je torej: »Neki visoki plemič je odšel v daljno deželo, da prejme zase kraljestvo in da se vrne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, '§ In poklical je svojih deset služabnikov ter jim razdelil deset funtov in jim rekel: ›Zaposlite se s trgovanjem, dokler ne pridem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Toda njegovi državljani so ga sovražili in za njim poslali sporočilo, rekoč: ›Nočemo, da bi ta človek zavladal nad nami.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Pripetilo pa se je, ko se je vrnil, da je prejel kraljestvo. Potem je ukazal, naj te služabnike, ki jim je dal denar, pokličejo k njemu, da lahko izve, koliko je vsak človek pridobil s trgovanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Potem je prišel prvi, rekoč: ›Gospodar, tvoj funt je pridobil deset funtov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Rekel mu je: ›V redu, ti dobri služabnik, ker si bil zvest v zelo majhnem, imej oblast nad desetimi mesti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'In prišel je drugi, rekoč: ›Gospod, tvoj funt je pridobil pet funtov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'In tudi njemu je rekel podobno: ›Tudi ti bodi nad petimi mesti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'In prišel je še en, rekoč: ›Gospod, glej, tukaj je tvoj funt, ki sem ga hranil v prtiču,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'kajti bal sem se te, ker si strog človek; jemlješ to, česar nisi položil in žanješ to, česar nisi posejal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'On pa mu reče: ›Po tvojih lastnih ustih te bom sodil, ti zlobni služabnik. Vedel si, da sem bil strog človek, ki jemljem to, česar nisem položil in žanjem to, česar nisem posejal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Zakaj torej mojega denarja nisi dal v banko, da bi lahko ob svojem prihodu svojo lastnino zahteval z obrestmi?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'In rekel je tem, ki so stali poleg: ›Vzemite od njega funt in ga dajte tistemu, ki ima deset funtov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '(Oni pa so mu rekli: ›Gospod, ta ima deset funtov.‹)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Kajti povem vam: ›Da se bo vsakemu, ki ima, dalo; od tistega, ki nima, pa se bo odvzelo celó to, kar ima.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Toda tiste moje sovražnike, ki niso hoteli, da bi jim jaz vladal, privedite sèm in jih pokončajte pred menoj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'In ko je tako govoril, je šel pred njimi ter se vzpenjal v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Pripetilo pa se je, ko je prišel blizu Bétfage in Betanije, pri gori, ki se imenuje Oljska gora, [da] je poslal dva izmed svojih učencev,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'rekoč: »Pojdita v vas nasproti vama, v kateri bosta ob svojem vstopu našla privezano žrebe, na katerem človek še nikoli ni sedel. Odvežita ga in ga privedita sèm.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Če pa vaju katerikoli človek vpraša: ›Zakaj ga odvezujeta?‹ mu recita takole: ›Ker ga potrebuje Gospod.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'In onadva, ki sta bila poslana, sta šla svojo pot in našla tako, kakor jima je povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'In ko sta odvezovala žrebe, so jima lastniki le-tega rekli: »Zakaj odvezujeta žrebe?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Onadva pa sta rekla: »Gospod ga potrebuje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'In privedla sta ga k Jezusu in svoje obleke vrgla na žrebe ter nanj posadila Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'In ko je šel, so na pot razgrinjali svoja oblačila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Ko je prišel blizu, torej celó k pobočju Oljske gore, se je celotna množica učencev začela veseliti in z močnim glasom hvaliti Boga za vsa mogočna dela, ki so jih videli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'rekoč: »Blagoslovljen naj bo Kralj, ki prihaja v imenu Gospodovem. V nebesih mir in slava na višavah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Nekaj farizejev izmed množice pa mu je reklo: »Učitelj, oštej svoje učence.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'In odgovoril jim je in jim rekel: »Povem vam, da če bi ti molčali, bodo takoj kamni zavpili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Ko pa je prišel bliže, je zagledal mesto ter se razjokal nad njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'rekoč: »Če bi ti spoznalo, celó ti, vsaj na ta tvoj dan, stvari, ki pripadajo tvojemu miru! Toda sedaj so skrite pred tvojimi očmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Kajti nadte bodo prišli dnevi, ko bodo tvoji sovražniki okoli tebe nasuli okope in te obkolili in te stiskali na vsaki strani');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'in zravnali te bodo z zemljo in tvoje otroke v tebi; in v tebi ne bodo pustili enega kamna na drugem, ker nisi spoznalo časa svojega obiskanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, '§ In odšel je v tempelj ter začel izganjati te, ki so v njem prodajali in te, ki so kupovali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'rekoč jim: »Pisano je: ›Moja hiša je hiša molitve,‹ toda vi ste jo naredili za brlog razbojnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'In vsak dan je učil v templju. Toda visoki duhovniki in pisarji in vodje ljudstva so si prizadevali, da ga pokončajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'pa niso mogli najti, kaj bi lahko storili, kajti vsi ljudje so ga zelo pozorno poslušali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'In pripetilo se je, da so na enega izmed tistih dni, ko je v templju učil ljudi in oznanjal evangelij, prišli nad njega visoki duhovniki in pisarji s starešinami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'in mu spregovorili, rekoč: »Povej nam, s kakšno oblastjo delaš te stvari? Ali kdo je tisti, ki ti je dal to oblast?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'In odgovoril je ter jim rekel: »Tudi jaz vas bom vprašal eno besedo in odgovorite mi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, '›Ali je bil Janezov krst iz nebes ali od ljudi?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Oni pa so razpravljali med seboj, rekoč: »Če bomo rekli: ›Iz nebes,‹ bo rekel: ›Zakaj mu potem niste verjeli?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Toda če rečemo: ›Od ljudi,‹ nas bodo vsi ljudje kamnali, kajti pregovorjeni so, da je bil Janez prerok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'In odgovorili so, da ne morejo povedati, od kod je bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'In Jezus jim je rekel: »Niti vam jaz ne povem, s kakšno oblastjo delam te stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Potem je začel ljudem govoriti to prispodobo: »Neki človek je zasadil vinograd in ga prepustil poljedelcem ter za dolgo časa odšel v daljno deželo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Ob primernem obdobju pa je poslal k poljedelcem služabnika, da bi mu lahko dali od sadu vinograda, toda poljedelci so ga pretepli in ga odposlali praznega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'On pa je ponovno poslal drugega služabnika in tudi njega so pretepli in sramotno ravnali z njim ter ga odposlali praznega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Pa je ponovno poslal tretjega in tudi njega so ranili ter ga vrgli ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Potem je gospodar vinograda rekel: ›Kaj naj storim? Poslal bom svojega ljubljenega sina. Ko ga bodo videli, ga bodo mogoče spoštovali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Toda ko so ga poljedelci zagledali, so med seboj razpravljali, rekoč: ›Ta je dedič. Pridite, ubijmo ga, da bo dediščina lahko naša.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Tako so ga vrgli iz vinograda in ga ubili. Kaj jim bo torej storil gospodar vinograda?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Prišel bo in uničil te poljedelce, vinograd pa bo dal drugim.« Ko pa so to slišali, so rekli: »Bog ne daj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'On pa jih je pogledal in rekel: »Kaj je torej to, kar je pisano: ›Kamen, ki so ga graditelji zavrgli, ta isti je postal glava vogalu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Kdorkoli bo padel na ta kamen, bo razbit, toda na kogarkoli bo ta padel, ga bo zmlel v prah.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'In visoki duhovniki ter pisarji so skušali to isto uro položiti roke nanj; bali pa so se ljudi, kajti zaznali so, da je to prispodobo govoril proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'In opazovali so ga ter poslali oglednike, ki naj bi se hlinili [za] pravične može, da bi ga lahko prijeli za njegove besede, da bi ga tako lahko izročili voditeljevi moči in oblasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'In vprašali so ga, rekoč: »Učitelj, vemo, da prav govoriš in učiš niti ne sprejemaš zunanjega videza kogarkoli, temveč resnično učiš Božjo pot:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, '›Ali je za nas zakonito, da dajemo cesarju davek ali ne?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Vendar je zaznal njihovo prebrisanost in jim rekel: »Zakaj me skušate?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Pokažite mi kovanec. Čigavo podobo in napis ima?« Odgovorili so in rekli: »Cesarjevo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'In rekel jim je: »Povrnite torej cesarju stvari, ki so cesarjeve, Bogu pa stvari, ki so Božje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'In pred ljudmi ga niso mogli prijeti zaradi njegovih besed in čudili so se ob njegovem odgovoru in molčali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Potem so prišli k njemu nekateri izmed saducejev, ki zanikajo, da obstaja kakršnokoli vstajenje in vprašali so ga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'rekoč: »Učitelj, Mojzes nam je napisal: ›Če komu umre brat, ki ima ženo in umre brez otrok, da naj njegov brat vzame njegovo ženo in svojemu bratu obudi seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Bilo je torej sedem bratov in prvi je vzel ženo ter umrl brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, '§ In drugi jo je vzel za ženo ter umrl brez otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'In vzel jo je tretji in na podoben način tudi sedmi, pa niso zapustili otrok in so umrli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Zadnja izmed vseh je umrla tudi ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Čigava žena od teh bo torej ob vstajenju? Kajti sedem jo je imelo za ženo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Jezus jim odgovori in reče: »Otroci tega sveta se poročajo in so dane v zakon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'toda tisti, ki bodo šteti za vredne, da dosežejo oni svet in vstajenje od mrtvih, se ne bodo niti poročali, niti ne bodo dane v zakon,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'niti ne morejo več umreti, kajti enaki so angelom in so Božji otroci, saj so otroci vstajenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Torej, da so mrtvi obujeni, je pokazal celó Mojzes pri grmu, ko je imenoval Gospoda ›Bog Abrahamov in Bog Izakov in Bog Jakobov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Kajti on ni Bog mrtvih, temveč živih, kajti njemu vsi živijo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Tedaj so nekateri izmed pisarjev odgovorili in rekli: »Učitelj, dobro si povedal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Nató pa se ga niso drznili vprašati nobenega vprašanja več.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'In rekel jim je: »Kako pravijo, da je Kristus Davidov sin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'In sam David pravi v knjigi Psalmov: › Gospod je rekel mojemu Gospodu: ›Sedi na mojo desnico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'dokler ne naredim tvojih sovražnikov [za] tvojo pručko.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David mu torej reče Gospod, kako je potem on njegov sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Potem je pred občinstvom vseh ljudi svojim učencem rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '»Pazite se pisarjev, ki želijo hoditi v dolgih svečanih oblačilih in imajo radi pozdrave na trgih in najvišje sedeže v sinagogah ter vodilna mesta na praznovanjih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'ki vdovam požirajo hiše in zaradi lepšega delajo dolge molitve; isti bodo prejeli večje prekletstvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'In pogledal je navzgor in videl bogataše metati svoje darove v zakladnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Videl pa je tudi neko siromašno vdovo vreči vanjo dva kovanca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'In rekel je: »Resnično, jaz vam pravim, da je ta siromašna vdova vrgla vanjo več kot vsi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'kajti vsi ti so iz svojega obilja vrgli vanjo daritve Bogu, toda ona je iz svojega uboštva vrgla vanjo vsa sredstva za preživljanje, ki jih je imela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'In ko so nekateri govorili o templju, kako je okrašen z lepimi kamni in darovi, je rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '» Glede teh stvari, ki jih gledate, pa bodo prišli dnevi, v katerih ne bo ostal en kamen na drugem, ki ne bi bil zrušen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'In vprašali so ga, rekoč: »Učitelj, toda kdaj bodo te stvari? In kakšno znamenje se bo zgodilo, ko se bodo te stvari pripetile?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'In rekel je: »Pazite, da ne boste zavedeni, kajti mnogi bodo prišli v mojem imenu, rekoč: ›Jaz sem Kristus in čas se je približal;‹ ne pojdite torej za njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Toda ko boste slišali o vojnah in vstajah, ne bodite prestrašeni, kajti te stvari se morajo najprej zgoditi, toda konec še ni v kratkem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tedaj jim je rekel: »Narod bo vstal zoper narod in kraljestvo zoper kraljestvo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'in veliki potresi bodo na raznih krajih in lakote ter kužne bolezni in strašni prizori ter velika znamenja se bodo zgodila z neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Toda pred vsem tem bodo nad vas iztegovali svoje roke in vas preganjali ter vas izročali v shodnice in ječe [in] zaradi mojega imena boste privedeni pred kralje in vladarje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'To pa se bo obrnilo k vam za pričevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Pomirite se torej v svojih srcih, da ne boste prej premišljevali, kaj boste odgovorili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'kajti jaz vam bom dal usta in modrost, kateri vsi vaši nasprotniki ne bodo mogli ugovarjati niti se ji upirati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Izdajali pa vas bodo tako starši kakor bratje, žlahta in prijatelji in nekaterim izmed vas bodo povzročili, da boste usmrčeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'In vsi ljudje vas bodo sovražili zaradi mojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Toda niti las z vaše glave ne bo propadel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, '§ S svojim potrpljenjem si pridobivate svoje duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'In ko boste videli Jeruzalem obdan z vojskami, tedaj vedite, da je blizu opustošenje le-tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Potem naj tisti, ki so v Judeji, pobegnejo v gore; in naj tisti, ki so v njegovi sredi, odidejo ven; in naj tisti, ki so na podeželju, ne vstopijo vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Kajti to so dnevi maščevanja, da se bodo lahko izpolnile vse stvari, ki so napisane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Toda gorje v tistih dneh tem, ki so z otrokom in tem, ki dojijo! Kajti v deželi bo velika tegoba in bes nad temi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'In padali bodo pod ostrino meča in odvedeni bodo v ujetništvo med vse narode in Jeruzalem bodo mendrali pogani, dokler se ne dopolnijo časi poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'In znamenja bodo na soncu in na luni in na zvezdah; in nad zemljo tegoba narodov z zmedenostjo; morje in valovi bodo rjoveli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'srca bodo ljudem odpovedovala zaradi strahu in zaradi opazovanja za temi stvarmi, ki prihajajo na zemljo, kajti moči neba se bodo majale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'In tedaj bodo videli Sina človekovega prihajati v oblaku z močjo in veliko slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Ko pa se bodo te stvari začele dogajati, potem poglejte gor in dvignite svoje glave, kajti vaša odkupitev se približuje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'In spregovoril jim je v prispodobi: »Poglejte figovo drevo in vsa drevesa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'ko sedaj poganjajo, vi vidite in sami veste, da je torej poletje blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tako tudi vi, ko vidite, da se te stvari dogajajo, védite, da je Božje kraljestvo blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Resnično, povem vam: ›Ta rod ne bo preminil, dokler ne bo vse izpolnjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Nebo in zemlja bosta minila, toda moje besede ne bodo minile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Pazite pa se, da ne bi bila vaša srca kadarkoli preobremenjena s prenasičenostjo in pijanostjo in skrbmi tega življenja in tako, da ta dan nad vas ne pride nepričakovano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Kajti kakor zanka bo prišel na vse tiste, ki prebivajo na obličju celotne zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Čujte torej in nenehno molíte, da boste lahko šteti za vredne, da pobegnete vsem tem stvarem, ki se bodo pripetile in stopite pred Sina človekovega.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'In podnevi je učil v templju, ponoči pa je odšel ven ter prebival na gori, ki se imenuje Oljska gora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'In vsi ljudje so prihajali zgodaj zjutraj k njemu v tempelj, da bi ga poslušali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Torej približal se je praznik nekvašenega kruha, ki se imenuje Pasha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Visoki duhovniki in pisarji pa so si prizadevali, kako bi ga lahko ubili, kajti bali so se ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Tedaj je Satan vstopil v Juda, z vzdevkom Iškarijot, ki je bil izmed dvanajsterih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'In ta je odšel svojo pot ter se posvetoval z visokimi duhovniki in stotniki, kako bi jim ga lahko izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'In ti so bili veseli in se obvezali, da mu dajo denar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'In obljubil je ter iskal priložnost, da jim ga izda v odsotnosti množice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Potem je prišel dan nekvašenega kruha, ko mora biti zaklano pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'In poslal je Petra ter Janeza, rekoč: »Pojdita in nam pripravita pashalno jagnje, da bomo lahko jedli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'In rekla sta mu: »Kje želiš, da ga pripraviva?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Rekel jima je: »Glejta, ko vstopita v mesto, vaju bo srečal moški, nesoč lončen vrč vode; sledita mu v hišo, v katero vstopa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Hišnemu očetu pa bosta rekla: ›Učitelj ti pravi: ›Kje je soba za goste, kjer bom s svojimi učenci jedel pashalno jagnje?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'In pokazal vama bo veliko opremljeno zgornjo sobo; tam pripravita.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'In onadva sta odšla ter našla, kakor jima je rekel in pripravila sta pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Ko pa je prišla ura, se je usedel in dvanajsteri apostoli z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Rekel jim je: »S hrepenenjem sem si želel, da bi to pashalno jagnje jedel z vami, še predem trpim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'kajti povem vam: ›Ne bom več jedel od tega, dokler to ne bo izpolnjeno v Božjem kraljestvu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'In vzel je čašo ter se zahvalil in rekel: »Vzemite jo in si to razdelite med seboj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'kajti povem vam: ›Ne bom pil od sadu vinske trte, dokler ne pride Božje kraljestvo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'In vzel je kruh in se zahvalil in ga razlomil ter jim dal, rekoč: »To je moje telo, ki je dano za vas, to delajte v spomin name.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Podobno tudi čašo po večerji, rekoč: »Ta čaša je nova zaveza v moji krvi, ki se preliva za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Toda glejte, roka tistega, ki me izdaja, je z menoj pri mizi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'In Sin človekov resnično gre, kakor je bilo določeno, toda gorje temu človeku, po katerem je izdan!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'In med seboj so se začeli spraševati, kdo izmed njih je bil, da bi storil to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Med njimi pa je bil tudi prepir, kdo izmed njih naj bi veljal za največjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'On pa jim je rekel: »Kralji poganov izvajajo gospostvo nad njimi, in kateri izvajajo oblast nad njimi, so imenovani dobrotniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Toda vi ne bodite takšni, temveč kdor je med vami največji, naj bo kakor mlajši in kdor je šef kakor tisti, ki streže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Kajti kdo je večji, kdor sedi pri mizi ali kdor streže? Mar ni, kdor sedi pri mizi? Toda jaz sem med vami kakor tisti, ki streže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Vi ste tisti, ki ste vztrajali z menoj v mojih skušnjavah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'In določam vam kraljestvo, kakor ga je moj Oče določil meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'da boste lahko jedli in pili pri moji mizi v mojem kraljestvu in sedeli na prestolih ter sodili dvanajst Izraelovih rodov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'In Gospod je rekel: »Simon, Simon, glej, Satan je zahlepel, da bi te imel, da te lahko preseje kakor pšenico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'toda jaz sem molil zate, da tvoja vera ne opeša; ko pa boš spreobrnjen, okrépi svoje brate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'In ta mu je rekel: »Gospod, pripravljen sem iti s teboj, tako v ječo, kakor v smrt.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'On pa je rekel: »Povem ti, Peter, danes petelin ne bo zapel, preden ne boš trikrat zatajil, da me poznaš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'In rekel jim je: »Ko sem vas poslal brez mošnje in malhe in čevljev ali vam je karkoli manjkalo?« In rekli so: »Nič.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Potem jim je rekel: »Toda kdor ima mošnjo, naj jo sedaj vzame in prav tako svojo malho; in kdor nima meča, naj proda svojo obleko in enega kupi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Kajti povem vam, da se mora na meni dovršiti še to, kar je pisano: ›In prištet je bil med prestopnike,‹ kajti stvari glede mene imajo konec.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'In rekli so: »Gospod, glej, tukaj sta dva meča.« On pa jim je rekel: »Dovolj je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'In prišel je ven ter odšel, kakor je bil navajen, na Oljsko goro in tudi njegovi učenci so mu sledili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Ko pa je bil na mestu, jim je rekel: »Molíte, da ne vstopite v skušnjavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'In od njih je bil oddaljen približno za lučaj kamna ter pokleknil in molil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'rekoč: »Oče, če si voljan, odstrani to čašo od mene, vendar ne moja volja, temveč tvoja naj se zgodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'In prikazal se mu je angel iz nebes ter ga krepil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, '§ Medtem ko je bil v neznosni bolečini, pa je še iskrenejše molil in njegov pot je bil, kakor bi na zemljo padale velike kaplje krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'In ko se je dvignil od molitve in prišel k svojim učencem, jih je zaradi bridkosti našel speče');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'in jim rekel: »Čemu spite? Vstanite in molíte, da ne vstopite v skušnjavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'In medtem ko je še govoril, zagleda množico in tisti, ki se je imenoval Juda, eden izmed dvanajsterih, je šel pred njimi in se približal Jezusu, da bi ga poljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Toda Jezus mu je rekel: »Juda, s poljubom izdajaš Sina človekovega?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Ko so ti, ki so bili okoli njega, videli, kaj bo sledilo, so mu rekli: »Gospod ali naj udarimo z mečem?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'In eden izmed njih je udaril služabnika vélikega duhovnika ter mu odsekal desno uho.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'In Jezus je odgovoril ter rekel: »Pustite do tod.« In dotaknil se je njegovega ušesa ter ga ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Potem je Jezus rekel visokim duhovnikom in tempeljskim stotnikom ter starešinam, ki so prišli k njemu: »Ali ste prišli ven, kakor proti tatu, z meči in palicami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Ko sem bil vsak dan z vami v templju, zoper mene niste iztegnili rok, toda to je vaša ura in oblast teme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Potem so ga vzeli in ga odvedli ter ga privedli v hišo vélikega duhovnika. Peter pa je sledil od daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'In ko so sredi dvorane prižgali ogenj ter skupaj sedli, je Peter sédel mednje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Toda zagledala ga je neka služkinja, ko je sedel poleg ognja in ga tehtno pogledala ter rekla: »Tudi ta človek je bil z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'On pa ga je zanikal, rekoč: »Ženska, ne poznam ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'In malo za tem ga je opazil drug ter rekel: »Tudi ti si izmed njih.« Peter pa je rekel: »Človek, nisem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'In približno eno uro kasneje je še en prepričano potrdil, rekoč: »Resnično, tudi ta je bil z njim, kajti Galilejec je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Peter pa je rekel: »Človek, ne vem kaj praviš.« In takoj, medtem ko je še govoril, je petelin zapel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Gospod pa se je obrnil in pogledal na Petra. In Peter se je spomnil Gospodove besede, kako mu je rekel: »Preden petelin zapoje, me boš trikrat zatajil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'In Peter je odšel ven ter se bridko zjokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Možje, ki so prijeli Jezusa, so ga zasmehovali in ga udarjali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'In ko so mu zavezali oči, so ga udarili po obrazu in ga vprašali, rekoč: »Prerokuj, kdo je ta, ki te je udaril?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'In mnogo drugih stvari so bogokletno govorili zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'In takoj, ko je bil dan, so prišli skupaj starešine izmed ljudi, visoki duhovniki ter pisarji in ga odvedli v svoj véliki zbor, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, '»Ali si ti Kristus? Povej nam.« On pa jim je rekel: »Če vam povem, ne boste verjeli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, '§ in tudi če vas vprašam, mi ne boste odgovorili niti mi [ne boste] pustili oditi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Odslej bo Sin človekov sedel na desnici Božje moči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Potem so vsi rekli: »Ali si ti potem Božji Sin?« On pa jim je rekel: »Vi pravite, da sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Rekli so: »Kaj potrebujemo kakršnihkoli nadaljnjih prič? Kajti sami smo slišali iz njegovih lastnih ust.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'In vsa množica teh je vstala ter ga odvedla k Pilatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'In začeli so ga obtoževati, rekoč: »Našli smo tega, da izkrivlja narod in prepoveduje dajati cesarju davek, rekoč, da je on sam Kristus Kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'In Pilat ga je vprašal, rekoč: »Ali si ti judovski Kralj?« On pa mu je odgovoril in rekel: »Ti praviš to.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Potem je Pilat rekel visokim duhovnikom in množici: »Na tem človeku ne najdem nobene krivde.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Oni pa so bili še bolj kruti, rekoč: »Razvnema ljudi, ko uči po vsej celotni Judeji, začenši v Galileji, do tega mesta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Ko je Pilat slišal o Galileji, je vprašal, ali je bil ta človek Galilejec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Takoj pa, ko je spoznal, da pripada pod Herodovo pristojnost, ga je poslal k Herodu, ki je bil ob tistem času tudi sam v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Ko je Herod zagledal Jezusa, je bil silno vesel, kajti že dlje časa si ga je želel videti, ker je o njem slišal mnoge stvari; in upal je, da bo videl kak čudež, ki ga bo storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Potem ga je zasliševal z mnogimi besedami, toda nič mu ni odgovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Poleg pa so stali visoki duhovniki in pisarji ter ga silovito obtoževali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'In Herod ga je s svojimi bojevniki ponižal ter ga zasmehoval in ga oblekel v krasno svečano oblačilo ter ga ponovno poslal k Pilatu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'In tega istega dne sta se Pilat in Herod spoprijateljila, kajti prej sta si bila med seboj sovražna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Ko pa je Pilat sklical skupaj visoke duhovnike in vladarje ter ljudstvo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'jim je rekel: »Privedli ste mi tega človeka, kot nekoga, ki izkrivlja ljudi in glejte, pred vami sem ga izprašal. Nobene krivde nisem našel na tem človeku glede teh stvari, za katere ga tožite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ne, in tudi Herod ne, kajti poslal sem vas k njemu. In glejte, nič smrti vrednega mu ni bilo storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Kaznoval ga bom torej in ga izpustil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '§ (Kajti nujno jim je moral na praznik nekoga izpustiti.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'In vsi so hkrati zakričali, rekoč: »Proč s tem človekom in izpusti nam Baraba,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '(ki je bil vržen v ječo zaradi nekega upora, storjenega v mestu in zaradi umora.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilat jim je torej, voljan izpustiti Jezusa, ponovno spregovoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Toda oni so vpili, rekoč: »Križaj ga, križaj ga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'In tretjič jim je rekel: »Zakaj, kakšno zlo je storil? Nobenega razloga za smrt nisem našel na njem. Kaznoval ga bom torej in ga izpustil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Oni pa so bili neposredni z močnimi glasovi in zahtevali, da bi bil križan. In prevladali so glasovi teh ter visokih duhovnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'In Pilat je razsodil, da naj bi bilo kakor zahtevajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'In izpustil jim je tega, ki so ga zahtevali, ki je bil zaradi upora in umora vržen v ječo, toda Jezusa je izročil njihovi volji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'In ko so ga odvedli proč, so prijeli nekega Simona, Cirenčana, ki je prihajal s podeželja in nanj položili križ, da bi ga nosil za Jezusom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'In sledila mu je velika skupina ljudi ter žensk, ki so ga tudi objokovale ter žalovale za njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Toda Jezus jim je, ko se je obrnil k njim, rekel: »Hčere jeruzalemske, ne jokajte zaradi mene, temveč jokajte nad seboj in nad svojimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Kajti glejte, prihajajo dnevi, v katerih bodo rekli: ›Blagoslovljene so jalove in maternice, ki niso nikoli nosile ter prsi, ki niso nikoli nudile sesanja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Potem bodo začeli govoriti goram: ›Padite na nas;‹ in hribom: ›Pokrijte nas.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Kajti če te stvari počnejo z zelenim drevesom, kaj se bo zgodilo s suhim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Z njim pa sta bila odvedena tudi dva druga hudodelca, da bi bila usmrčena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'In ko so prišli na kraj, ki se imenuje Kalvarija, so tam križali njega in hudodelca, enega na desni roki, drugega pa na levi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Potem je Jezus rekel: »Oče, odpusti jim, kajti ne vedo, kaj delajo.« Oni pa so si razdelili njegova oblačila ter metali žrebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'In ljudje so stoje gledali. Prav tako pa so ga z njimi zasmehovali vladarji, rekoč: »Rešil je druge, naj reši sebe, če je on Kristus, Božji izvoljenec.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'In tudi vojaki so ga zasmehovali, ko so prišli k njemu in mu ponujali kisa');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'ter rekli: »Če si judovski kralj, reši samega sebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, '§ Nad njim pa je bil tudi nadpis, napisan v črkah grščine in latinščine ter hebrejščine: TO JE JUDOVSKI KRALJ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Eden izmed hudodelcev, ki sta visela, pa ga je zasmehoval, rekoč: »Če si ti Kristus, reši sebe in naju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Vendar mu je drugi odgovoril, ga oštel in rekel: »Ali se ne bojiš Boga, glede na to, da si ti v isti obsodbi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'In midva zares po pravici, kajti prejemava nagrado, primerno svojim dejanjem, toda ta človek ni storil nič narobe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, '§ In Jezusu je rekel: »Gospod, spomni se me, ko prideš v svoje kraljestvo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, '§ In Jezus mu je rekel: »Resnično, povem ti: ›Danes boš z menoj v raju.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'In bilo je okoli šeste ure in bila je tema po vsej zemlji do devete ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'In sonce je otemnelo in tempeljsko zagrinjalo se je raztrgalo po sredini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, '§ In ko je Jezus zavpil z močnim glasom, je rekel: »Oče, v tvoje roke izročam svojega duha.« In ko je to izrekel, je izročil duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Torej ko je stotnik videl, kaj se je zgodilo, je slavil Boga, rekoč: »Zagotovo je bil to pravičen človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'In vsa množica, ki je prišla skupaj k temu prizoru in gledala te stvari, ki so se zgodile, se je tolkla po svojih prsih in se vrnila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Vsi njegovi znanci in ženske, ki so mu sledili iz Galileje, pa so stali daleč stran in gledali te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'In glej, tam je bil mož, po imenu Jožef, svetovalec. In bil je dober mož ter pravičen');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(isti ni soglašal z nasvetom in njihovim dejanjem). Bil je iz Arimateje, judovskega mesta, ki je tudi sam pričakoval Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Ta mož je odšel k Pilatu in prosil [za] Jezusovo telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'In snel ga je ter ga zavil v laneno platno in ga položil v mavzolej, ki je bil vsekan v skalo, v katerega človek še nikoli prej ni bil položen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'In ta dan je bila priprava in približeval se je šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, '§ In tudi ženske, ki so prišle z njim iz Galileje, so potem sledile ter [si] ogledale mavzolej in kako je bilo njegovo telo položeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'In vrnile so se in pripravile dišave ter mazila in glede na zapoved počivale na šabatni dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, '§ Torej na prvi dan tedna so zelo zgodaj zjutraj prišle k mavzoleju in nosile dišave, ki so jih pripravile in nekatere druge z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Našle pa so kamen odvaljen od mavzoleja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'In vstopile so vanj, pa niso našle telesa Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'In pripetilo se je, medtem ko so bile glede tega zelo zmedene, glej, dva moža sta stala poleg njih v sijočih oblekah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'in medtem ko so bile prestrašene in so svoje obraze sklonile k zemlji, sta jim rekla: »Zakaj iščete živega med mrtvimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Njega ni tukaj, temveč je bil obujen. Spomnite se, kako vam je govoril, ko je bil še v Galileji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'rekoč: ›Sin človekov mora biti izročen v roke grešnih ljudi in biti križan ter tretji dan ponovno vstati.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'In spomnile so se njegovih besed');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'ter se vrnile od mavzoleja in vse te stvari povedale enajsterim ter vsem ostalim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Bile so Marija Magdalena in Joana in Marija, Jakobova mati ter druge ženske, ki so bile z njimi, ki so te stvari povedale apostolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Njihove besede pa so se jim zdele kakor prazno opravljanje in jim niso verjeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Potem je vstal Peter in stekel k mavzoleju. In sklonjen dol je zagledal lanene trakove, položene posebej, ter odšel in se v sebi spraševal o tem, kar se je pripetilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'In glej, dva izmed njih sta tega istega dne odšla proti vasi, z imenom Emavs, ki je bila okoli šestdeset dolžin brazd od Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'In skupaj sta se pogovarjala o vseh teh stvareh, ki so se zgodile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'In pripetilo se je, medtem ko sta se skupaj posvetovala in razpravljala, da se je približal sam Jezus in šel z njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Vendar so bile njune oči zadržane, da ga ne bi spoznala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'On pa jima je rekel: »Kakšne vrste pogovori so to, ki jih imata drug z drugim, medtem ko hodita in sta žalostna?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Eden izmed njiju, ki mu je bilo ime Kleopa, pa mu odgovori in reče: »Ali si ti edini tujec v Jeruzalemu in nisi izvedel stvari, ki so se v teh dneh tam zgodile?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'In rekel jima je: »Katere stvari?« In rekla sta mu: »Glede Jezusa Nazarečana, ki je bil prerok, mogočen v dejanju in besedi, pred Bogom in vsemi ljudmi');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'in kako so ga visoki duhovniki in naši vladarji izročili, da bi bil obsojen na smrt in ga križali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Toda mi smo zaupali, da je bil on tisti, ki naj bi odkupil Izraela; in poleg vsega tega je danes tretji dan, odkar so se te stvari zgodile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Da, in nekatere ženske, prav tako iz naše skupine, ki so bile zgodaj pri mavzoleju, so nas osupnile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'In ko niso našle njegovega telesa, so prišle, rekoč, da so prav tako videle videnje angelov, ki sta rekla, da je bil živ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'In nekateri izmed teh, ki so bili z nami, so odšli k mavzoleju in našli točno takó, kakor so rekle ženske, toda njega niso videli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Potem jima je rekel: »Oh bedaka in počasnega srca za verovanje vsega, kar so govorili preroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ali ni moral Kristus pretrpeti te stvari in vstopiti v svojo slavo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'In začel je pri Mojzesu in vseh prerokih ter jima v vseh pismih pojasnil besede glede njega samega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'In približali so se blizu k vasi, kamor sta šla, on pa je storil, kakor da bo odšel dalje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Vendar sta ga primorala, rekoč: »Ostani z nama, kajti blizu večera je in dan je davno minil.« In odšel je noter, da ostane z njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'In pripetilo se je, medtem ko je z njima sedel pri hrani, [da] je vzel kruh in ga blagoslovil in prelomil ter jima dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'In njune oči so bile odprte in sta ga spoznala, on pa je izginil iz njunega pogleda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'In rekla sta drug drugemu: »Ali ni najino srce gorelo znotraj naju, medtem ko je z nama govoril po poti in medtem ko nama je odpiral pisma?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'In vstala sta še isto uro in se vrnila v Jeruzalem in našla skupaj zbrane enajstere in tiste, ki so bili z njimi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'govoreče: »Gospod je bil resnično obujen in se prikazal Simonu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'In povedala sta, kakšne stvari so se zgodile na poti in kako sta ga prepoznala po lomljenju kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'In ko sta tako govorila, je sam Jezus stal v njihovi sredi in jim reče: »Mir vam bodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Toda bili so prestrašeni in zgroženi in domnevali so, da so videli duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Rekel jim je: »Zakaj ste zaskrbljeni? In zakaj v vaših srcih vstajajo misli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Poglejte moje roke in moja stopala, da sem to jaz sam. Potipajte me in poglejte, kajti duh nima mesa in kosti, kakor vidite, da jih imam jaz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'In ko je tako govoril, jim je pokazal svoje roke in svoja stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'In medtem ko zaradi radosti niso verjeli ter se čudili, jim je rekel: »Imate tukaj kaj hrane?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, '§ In dali so mu kos pečene ribe in od satovja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'In vzel je to ter pred njimi pojedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'In rekel jim je: »To so besede, ki sem vam jih govoril, medtem ko sem bil še z vami, da se morajo izpolniti vse stvari, ki so bile glede mene zapisane v Mojzesovi postavi in v prerokih in v psalmih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tedaj jim je odprl njihov razum, da so lahko razumeli pisma');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'in jim rekel: »Tako je pisano in tako se je Kristusu spodobilo trpeti in tretji dan vstati od mrtvih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'in da bi se kesanje ter odpuščanje grehov oznanjalo v njegovem imenu med vsemi narodi, začenši v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'In vi ste priče teh stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, '§ In glejte, nad vas pošiljam obljubo svojega Očeta, toda ostanite v jeruzalemskem mestu, dokler ne boste opremljeni z močjo od zgoraj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'In odvedel jih je ven, prav do Betanije in povzdignil svoje roke in jih blagoslovil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'In medtem ko jih je blagoslavljal, se je pripetilo, [da] je bil ločen od njih in odnesen gor v nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'In oni so ga oboževali in se z veliko radostjo vrnili v Jeruzalem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, '§ in bili so nenehno v templju in hvalili in blagoslavljali Boga. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'V začetku je bila Beseda in Beseda je bila z Bogom in Beseda je bila Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ista je bila v začetku z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Vse stvari so bile narejene po njem in brez njega ni bilo narejeno nič, kar je bilo narejeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'V njem je bilo življenje in življenje je bilo svetloba ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'In svetloba sveti v temi, tema pa je ni doumela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Bil je človek, poslan od Boga, katerega ime je bilo Janez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ta isti je prišel za pričo, da pričuje o Svetlobi, da bodo vsi ljudje po njem lahko verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Ni bil on ta Svetloba, ampak je bil poslan, da pričuje o tej Svetlobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, '§ To je bila resnična Svetloba, ki razsvetljuje vsakega človeka, ki prihaja na svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Bil je na svetu in svet je bil narejen po njem, svet pa ga ni spoznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Prišel je k svojim lastnim, njegovi lastni pa ga niso sprejeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Toda tolikim, kot so ga sprejeli, njim je on dal moč, da postanejo Božji sinovi, torej njim, ki verujejo v njegovo ime,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'ki so bili rojeni, ne iz krvi niti ne iz volje mesa niti ne iz volje moža, temveč iz Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'In Beseda je bila narejena meso in prebivala med nami (in zagledali smo njegovo slavo, slavo kot od edinorojenega od Očeta) polno milosti in resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Janez je pričeval o njem in klical, rekoč: »Ta je bil tisti, o katerem sem govoril: ›Kdor prihaja za menoj, je obstajal pred menoj, kajti bil je prej kakor jaz.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'In iz njegove polnosti smo vsi prejeli in to milost za milostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Kajti postava je bila dana po Mojzesu, toda milost in resnica sta prišli po Jezusu Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, '§ Noben človek nikoli ni videl Boga. Edinorojeni Sin, ki je v Očetovem naročju, on ga je razodel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'In to je Janezovo pričevanje, ko so Judje poslali iz Jeruzalema duhovnike in Lévijevce, da ga vprašajo: »Kdo si ti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, '§ In priznal je in ni zanikal, temveč priznal: »Jaz nisem Kristus.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'In vprašali so ga: »Kaj torej? Ali si Elija?« In reče: »Nisem.« »Ali si ti ta prerok?« In odgovoril je: »Ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Potem so mu rekli: »Kdo si? Da bomo lahko dali odgovor tem, ki so nas poslali. Kaj praviš sam o sebi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Rekel je: »Jaz sem glas nekoga, ki kliče v divjini: ›Naredite Gospodovo pot ravno,‹ kakor je rekel prerok Izaija.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Ti pa, ki so bili poslani, so bili izmed farizejev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'In vprašali so ga ter mu rekli: »Zakaj potem krščuješ, če ti nisi ta Kristus niti Elija niti ta prerok?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Janez jim je odgovoril, rekoč: »Jaz krščujem z vodo, toda tam, med vami, stoji nekdo, ki ga vi ne poznate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, '§ On je ta, ki prihaja za menoj, in je pred menoj, čigar čevljev jermena nisem vreden odvezati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Te stvari so se zgodile v Betaniji, onstran Jordana, kjer je Janez krščeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Naslednji dan zagleda Janez k njemu prihajati Jezusa in reče: »Glejte, Jagnje Božje, ki odvzema greh sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'To je on, o katerem sem rekel: ›Za menoj prihaja mož, ki je obstajal pred menoj, kajti bil je pred menoj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'In nisem ga poznal, vendar sem zato prišel krščevat z vodo, da bi se on razodel Izraelu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'In Janez je izjavil, rekoč: »Videl sem Duha spuščati se z neba, kakor golobico in je ostal na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'In nisem ga poznal, toda kdor me je poslal, da krščujem z vodo, isti mi je rekel: ›Na kogar boš videl spuščati se Duha in ostajati na njem, isti je ta, ki krščuje s Svetim Duhom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'In videl sem in izjavil, da je ta Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Naslednji dan je Janez ponovno stal in dva izmed njegovih učencev');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'in ko je gledal na Jezusa, medtem ko je hodil, reče: »Glej, Jagnje Božje!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Dva učenca pa sta ga slišala govoriti in šla za Jezusom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Potem se je Jezus obrnil in ju videl slediti ter jima reče: »Kaj iščeta?« Rekla sta mu: »Rabi (kar prevedeno pomeni Učitelj), kje prebivaš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Reče jima: »Pridita in poglejta.« Prišla sta in videla, kje prebiva ter ta dan ostala z njim, kajti bilo je okrog desete ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, '§ Eden izmed dveh, ki sta slišala Janeza govoriti in sta mu sledila, je bil Andrej, brat Simona Petra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Ta je najprej našel svojega lastnega brata Simona in mu rekel: »Našli smo Mesija,« kar je prevedeno, Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, '§ In privedel ga je k Jezusu. In ko ga je Jezus pogledal, je rekel: »Ti si Simon, Jonov sin. Imenoval se boš Kefa,« kar je po razlagi: ›Kamen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Naslednji dan je Jezus nameraval oditi naprej v Galilejo in najde Filipa ter mu reče: »Sledi mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Torej Filip pa je bil iz Betsajde, Andrejevega in Petrovega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filip najde Natánaela in mu reče: »Našli smo tistega, o katerem so Mojzes in preroki pisali v postavi, Jezusa iz Nazareta, Jožefovega sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Natánael pa mu je rekel: »Ali lahko iz Nazareta pride kakršnakoli dobra stvar?« Filip mu reče: »Pridi in poglej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jezus je videl k njemu prihajati Natánaela in reče o njem: »Glejte, pravi Izraelec, v katerem ni zvijače!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natánael mu reče: »Od kod me poznaš?« Jezus je odgovoril in mu rekel: »Preden te je Filip poklical, sem te videl, ko si bil pod figovim drevesom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natánael je odgovoril in mu reče: »Rabi, ti si Božji Sin. Ti si Izraelov Kralj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jezus je odgovoril in mu rekel: »Ker sem ti rekel: ›Videl sem te pod figovim drevesom,‹ veruješ? Videl boš večje stvari kakor te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'In reče mu: »Resnično, resnično, povem vam: ›Odslej boste videli odprta nebesa in Božje angele, ki se vzpenjajo in spuščajo nad Sinom človekovim.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'In tretji dan je bila v galilejski Kani svatba in Jezusova mati je bila tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Na svatbo pa so bili povabljeni tako Jezus kakor njegovi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'In ko je zmanjkalo vina, mu Jezusova mati reče: »Vina nimajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jezus ji reče: »Ženska, kaj imam opraviti s teboj? Moja ura še ni prišla.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Njegova mati reče služabnikom: »Karkoli vam reče, to storite.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'In tam je bilo postavljenih šest kamnitih posod za vodo, po običaju judovskega očiščevanja, ki so vsebovale vsaka po dva ali tri sodčke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jezus jim reče: »Napolnite posode za vodo z vodo.« In napolnili so jih do roba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'In reče jim: »Zajemite torej in nesite k vodju gostije.« In oni so to odnesli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Ko je vodja gostije pokusil vodo, ki je postala vino in ni vedel, od kod je bila (toda služabniki, ki so zajemali vodo, so vedeli), je vodja gostije poklical ženina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'ter mu reče: »Vsak človek na začetku postavi dobro vino, potem pa, ko se ljudje temeljito napijejo, to, ki je slabše. Toda ti si dobro vino prihranil do zdaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ta začetek čudežev je Jezus storil v galilejski Kani in jasno pokazal svojo slavo in njegovi učenci so verovali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Po tem je odšel dol v Kafarnáum, on in njegova mati, njegovi bratje ter njegovi učenci in tam so ostali ne mnogo dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'In blizu je bila judovska pasha in Jezus je odšel gor v Jeruzalem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'in našel v templju te, ki so prodajali vole in ovce in golobice in menjalce denarja sedeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'In ko je iz majhnih vrvi naredil bič, jih je vse izgnal iz templja in ovce in vole in iztresel denar menjalcem ter prevrnil mize');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'in rekel tem, ki so prodajali golobice: »Odnesite te stvari od tod. Ne delajte hiše mojega Očeta za hišo trgovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'In njegovi učenci so se spomnili, da je bilo pisano: ›Gorečnost za tvojo hišo me je použila.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Potem so Judje odgovorili in mu rekli: »Kakšno znamenje nam pokažeš, glede na to, da delaš te stvari?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jezus je odgovoril in jim rekel: »Uničite ta tempelj in v treh dneh ga bom postavil pokonci.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Tedaj so Judje rekli: »Ta tempelj je bil v gradnji šestinštirideset let, ti pa ga hočeš postaviti v treh dneh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Toda govoril je o templju svojega telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Ko je bil torej obujen od mrtvih, so se njegovi učenci spomnili, da jim je to rekel in verjeli so pismu ter besedi, ki jo je Jezus rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Torej ko je bil za pasho, na praznični dan, v Jeruzalemu, so mnogi, ko so videli čudeže, ki jih je storil, verovali v njegovo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Toda Jezus se jim ni zaupal, ker je vse ljudi poznal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'in ni potreboval, da bi kdorkoli pričeval o človeku, kajti vedel je, kaj je bilo v človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Bil je človek izmed farizejev, po imenu Nikodém, vladar Judov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ta isti je ponoči prišel k Jezusu in mu rekel: »Rabi, vemo, da si učitelj, ki je prišel od Boga, kajti noben človek ne more delati teh čudežev, ki jih delaš ti, razen če ni Bog z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jezus je odgovoril in mu rekel: »Resnično, resnično, povem ti: ›Razen če se človek ponovno ne rodi, ne more videti Božjega kraljestva.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodém mu reče: »Kako je lahko človek ponovno rojen, ko je star? Ali lahko drugič vstopi v maternico svoje matere in se rodi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jezus je odgovoril: »Resnično, resnično, povem ti: ›Razen če se človek ne rodi iz vode in iz Duha, ne more vstopiti v Božje kraljestvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'To, kar je rojeno iz mesa, je meso, in to, kar je rojeno iz Duha, je duh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne čudi se, da sem ti rekel: ›Morate se ponovno roditi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Veter piha, kjer želi in slišiš zvok le-tega, toda ne moreš povedati, od kod prihaja in kam gre. Tako je z vsakim, ki je rojen iz Duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodém je odgovoril in mu rekel: »Kako so te stvari mogoče?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jezus je odgovoril in mu rekel: »Ali si ti učitelj Izraelu, pa ne veš teh stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Resnično, resnično, povem ti: ›Mi govorimo to, kar vemo in pričujemo to, kar smo videli, vi pa našega pričevanja ne sprejemate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Če sem vam govoril zemeljske stvari in niste verovali, kako boste verovali, če vam povem o nebeških stvareh?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, '§ In noben človek se ni dvignil v nebesa, razen tisti, ki je prišel dol iz nebes, celó Sin človekov, ki je v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'In kakor je Mojzes povzdignil kačo v divjini, točno tako mora biti povzdignjen Sin človekov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, '§ da se, kdorkoli veruje vanj, ne bo pogubil, temveč bo imel večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, '§ Kajti Bog je tako ljubil svet, da je dal svojega edinorojenega Sina, da kdorkoli veruje vanj, se ne bo pogubil, temveč bo imel večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Kajti Bog svojega Sina ni poslal na svet, da svet obsodi, temveč, da bi bil svet po njem lahko rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kdor veruje vanj, ni obsojen, toda kdor ne veruje, je že obsojen, ker ni veroval v ime edinorojenega Božjega Sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'In to je obsodba, da je svetloba prišla na svet, ljudje pa so raje ljubili temo kakor svetlobo, ker so bila njihova dejanja hudobna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Kajti vsak, kdor počne zlo, sovraži svetlobo niti ne prihaja k svetlobi, da njegova dejanja ne bi bila pograjana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Toda kdor ravna po resnici, prihaja k svetlobi, da bi se njegova dejanja lahko razodela, da so narejena v Bogu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Po teh besedah so prišli Jezus in njegovi učenci v judejsko deželo in z njimi je ostal tam ter krščeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Pa tudi Janez je krščeval v Enónu blizu Salíma, ker je bilo tam veliko vode; in prihajali so in bili so krščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Kajti Janez še ni bil vržen v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Potem je med nekaterimi Janezovimi učenci in Judi nastalo pričkanje glede očiščevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'In prišli so k Janezu ter mu rekli: »Rabi, kdor je bil s teboj onstran Jordana, o katerem prinašaš pričevanje, glej, isti krščuje in vsi ljudje prihajajo k njemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Janez je odgovoril in rekel: »Človek ne more ničesar prejeti, razen če mu ni dano iz nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vi sami mi prinašate pričevanje, da sem rekel: ›Jaz nisem Kristus, temveč, da sem poslan pred njim.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kdor ima nevesto, je ženin, toda ženinov prijatelj, ki stoji in ga posluša, se silno razveseljuje zaradi ženinovega glasu. Ta moja radost je torej dopolnjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'On mora rasti, toda jaz se moram manjšati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kdor prihaja od zgoraj, je nad vsem. Kdor je z zemlje, je zemeljski in govori zemeljsko. Kdor prihaja iz nebes, je nad vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Kar je videl in slišal, to pričuje in noben človek ne sprejema njegovega pričevanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kdor je sprejel njegovo pričevanje, je pristavil k njegovemu pečatu, da je Bog resničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Kajti tisti, ki ga je Bog poslal, govori Božje besede, kajti Bog mu ne daje Duha na mero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Oče ljubi Sina in mu je vse stvari dal v njegovo roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kdor veruje v Sina, ima večno življenje; kdor pa ne veruje Sinu, ne bo videl življenja, temveč na njem ostaja Božji bes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, '§ Ko je torej Gospod izvedel, kako so farizeji slišali, da je Jezus pridobil in krstil več učencev kakor Janez,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(čeprav Jezus sam ni krščeval, temveč njegovi učenci),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'je zapustil Judejo in ponovno odšel v Galilejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Brezpogojno pa je moral iti skozi Samarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Potem je prišel v samarijsko mesto, ki se imenuje Sihár, blizu kosa zemljišča, ki ga je Jakob dal svojemu sinu Jožefu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Torej tam [pa] je bil Jakobov vodnjak. Jezus zatorej, opešan od svojega potovanja, tako sede na vodnjak; bilo pa je okoli šeste ure.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Tja prihaja ženska iz Samarije, da zajame vode. Jezus ji reče: »Daj mi piti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Kajti njegovi učenci so odšli proč v mesto, da kupijo hrano.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Potem mu ženska iz Samarije reče: »Kako je to, da ti, ki si Jud, prosiš piti od mene, ki sem ženska iz Samarije? Kajti Judje s Samarijani nimajo nobenega opravka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jezus je odgovoril in ji rekel: »Če bi poznala Božji dar in kdo je, ki ti govori: ›Daj mi, da pijem,‹ bi prosila od njega in dal bi ti žive vode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Ženska mu reče: »Gospod, nimaš s čim zajeti, vodnjak pa je globok. Od kod imaš potem to živo vodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Ali si ti večji kakor naš oče Jakob, ki nam je dal vodnjak in je od tega pil on sam in njegovi otroci in njegova živina?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jezus je odgovoril in ji rekel: »Kdorkoli pije od te vode, bo ponovno žejen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'toda kdorkoli pije od vode, ki mu jo bom jaz dal, ne bo nikoli žejen, temveč bo voda, ki mu jo bom jaz dal, postala v njem izvir vode, ki izvira v večno življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Ženska mu reče: »Gospod, daj mi te vode, da ne bom žejna niti ne bom hodila sèm zajemat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jezus ji reče: »Pojdi, pokliči svojega soproga in pridi sèm.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Ženska je odgovorila in rekla: »Nimam soproga.« Jezus ji je rekel: »To si dobro povedala: ›Nimam soproga,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'kajti imela si pet soprogov in ta, ki ga imaš sedaj, ni tvoj soprog. To si iskreno povedala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Ženska mu reče: »Gospod, zaznavam, da si prerok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Naši očetje so oboževali na tej gori, vi pa pravite, da je v Jeruzalemu kraj, kjer morajo ljudje oboževati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jezus ji reče: »Ženska, veruj mi, prihaja ura, ko ne boste oboževali Očeta ne na tej gori niti ne v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vi obožujete, česar ne poznate. Mi vemo kaj obožujemo, kajti rešitev duš je od Judov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Toda prihaja ura in je sedaj, ko bodo pravi oboževalci oboževali Očeta v duhu in resnici, kajti Oče išče takšne, da ga obožujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bog je Duh, tisti pa, ki ga obožujejo, ga morajo oboževati v duhu in v resnici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Ženska mu reče: »Vem, da prihaja Mesija, ki se imenuje Kristus. Ko pride, nam bo povedal vse stvari.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jezus ji reče: » Jaz, ki ti govorim, sem ta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Zatem pa so prišli njegovi učenci in se čudili, da se je pogovarjal z žensko, vendarle noben človek ni rekel: ›Kaj iščeš?‹ ali: ›Zakaj govoriš z njo?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Tedaj je ženska pustila svojo posodo za vodo in odšla svojo pot v mesto ter reče ljudem:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '»Pridite, poglejte človeka, ki mi je povedal vse stvari, ki sem jih kdaj storila. Ali ni to Kristus?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Potem so odšli iz mesta in prišli k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Medtem pa so ga njegovi učenci prosili, rekoč: »Učitelj, jej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Vendar jim je rekel: »Jaz imam za jed hrano, ki je vi ne poznate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Zato so učenci drug drugemu rekli: »Ali mu je katerikoli človek prinesel kaj za jesti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jezus jim reče: »Moja hrana je, da izvršim voljo tistega, ki me je poslal in da zaključim njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ali ne pravite: ›Še štiri mesece in potem prihaja žetev?‹ Glejte, povem vam: ›Povzdignite svoje oči in poglejte na polja, kajti že so bela za žetev.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'In kdor žanje, prejema plače in zbira sad za večno življenje, da se lahko skupaj veselita oba, kdor seje in kdor žanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'In v tem je ta beseda resnična: ›Eden seje, drugi pa žanje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Pošiljam vas, da požanjete to, za kar niste priložili nobenega truda. Drugi ljudje so se trudili, vi pa ste vstopili v njihove napore.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'In mnogi izmed Samarijanov iz tega mesta so verovali vanj zaradi besed ženske, ki je pričevala: »Povedal mi je vse, kar sem kdaj storila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Torej ko so Samarijani prišli k njemu, so ga rotili, da bi ostal z njimi. In ostal je tam dva dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'In veliko več jih je verovalo zaradi njegove lastne besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Ženski pa so rekli: »Sedaj verjamemo, ne zaradi tvojih besed, kajti sami smo ga slišali in vemo, da je ta zares Kristus, Odrešenik sveta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Torej po dveh dneh je odšel od tam in šel v Galilejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Kajti Jezus je sam izpričal, da prerok v svoji lastni deželi nima spoštovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Potem ko je prišel v Galilejo, so ga Galilejci sprejeli, ker so videli vse stvari, ki jih je na praznik storil v Jeruzalemu, kajti tudi sami so odšli na praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Tako je Jezus ponovno prišel v galilejsko Kano, kjer je vodo spremenil v vino. Tam pa je bil nek visoki plemič, čigar sin je bil bolan v Kafarnáumu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ko je slišal, da je Jezus prišel iz Judeje v Galilejo, je odšel k njemu in ga rotil, da bi prišel dol in ozdravil njegovega sina, kajti ta je bil na točki smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Tedaj mu je Jezus rekel: »Razen če ne vidite znamenj in čudežev, ne boste verovali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Visoki plemič mu reče: »Gospod, pridi dol, preden moj otrok umre.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jezus mu reče: »Pojdi svojo pot, tvoj sin živi.« In mož je verjel besedi, ki mu jo je Jezus govoril in je odšel svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Ko je torej šel navzdol, so ga srečali njegovi služabniki in mu povedali, rekoč: »Tvoj sin živi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Potem je od njih poizvedel uro, ko je začel okrevati. In oni so mu rekli: »Včeraj ob sedmi uri ga je vročica pustila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tako je oče spoznal, da je bilo to ob isti uri, ob kateri mu je Jezus rekel: »Tvoj sin živi.« In veroval je on sam in njegova celotna hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'To je spet drugi čudež, ki ga je Jezus storil, ko je prišel iz Judeje v Galilejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Po tem je bil judovski praznik in Jezus je odšel gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Torej v Jeruzalemu je pri ovčjem trgu bazen, ki se v hebrejskem jeziku imenuje Betésda in ima pet preddverij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'V teh leži velika množica nemočnih ljudi, slepih, šepavih in oslabelih, ki čakajo na gibanje vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Kajti angel je ob nekem času odšel dol v bazen in vzburkal vodo. Kdorkoli je potem prvi po vzburkanju vode stopil vanj, je bil ozdravljen, katerokoli bolezen je imel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'In tam je bil nek človek, ki je osemintrideset let imel šibkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Ko ga je Jezus videl ležati in je vedel, da je bil torej dolgo časa v tem stanju, mu reče: »Hočeš ozdraveti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Nemočen človek mu je odgovoril: »Gospod, ko je voda vzburkana, nimam nobenega človeka, da bi me dal v bazen, toda medtem ko prihajam, drug stopi dol pred menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jezus mu reče: »Vstani, vzemi svojo posteljo in hôdi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'In mož je bil takoj ozdravljen in vzel svojo posteljo ter hodil. Na isti dan pa je bil šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Judje so torej rekli temu, ki je bil ozdravljen: »Šabatni dan je. Zate ni zakonito, da nosiš svojo posteljo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Odgovoril jim je: »Tisti, ki me je ozdravil, isti mi je rekel: ›Vzemi svojo posteljo in hôdi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Potem so ga vprašali: »Kateri človek je ta, ki ti je rekel: ›Vzemi svojo posteljo in hôdi?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Tisti pa, ki je bil ozdravljen, ni vedel kdo je bil ta, ker se je Jezus na skrivaj odstranil, [kajti] množica je bila na tem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Kasneje ga Jezus najde v templju in mu reče: »Glej, ozdravljen si. Ne greši več, da ne bi prišla k tebi hujša stvar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Mož je odšel in Judom povedal, da je bil Jezus ta, ki ga je ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, '§ In zato so Judje preganjali Jezusa in si prizadevali, da ga ubijejo, ker je te stvari delal na šabatni dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Toda Jezus jim je odgovoril: »Moj Oče dela do zdaj in jaz delam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Zato so si Judje še bolj prizadevali, da ga ubijejo, ker ni samo prekršil šabata, temveč je tudi rekel, da je bil njegov Oče Bog in se izenačil z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Tedaj je Jezus odgovoril in jim rekel: »Resnično, resnično, povem vam: ›Sin ne more ničesar storiti sam od sebe, temveč kar vidi delati Očeta, kajti katerekoli stvari dela on, te prav tako enako dela Sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Kajti Oče ima Sina rad in mu kaže vse stvari, ki jih dela sam in pokazal mu bo večja dela kakor ta, da se boste lahko čudili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Kajti kakor Oče obuja mrtve in jih oživlja, točno tako Sin oživlja kogar hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Kajti Oče ne sodi nobenega človeka, temveč je vso sodbo izročil Sinu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'da bi vsi ljudje spoštovali Sina, tako kakor spoštujejo Očeta. Kdor ne spoštuje Sina, ne spoštuje Očeta, ki ga je poslal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Resnično, resnično, povem vam: ›Kdor sliši mojo besedo in veruje vanj, ki me je poslal, ima večno življenje in ne bo prišel v obsodbo, temveč je iz smrti prešel v življenje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Resnično, resnično, povem vam: ›Prihaja ura in je sedaj, ko bodo mrtvi slišali glas Božjega Sina, in tisti, ki ga zaslišijo, bodo živeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Kajti kakor ima Oče življenje v sebi, tako je dal Sinu, da ima življenje v sebi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'in dal mu je tudi oblast, da izvrši sodbo, ker je Sin človekov.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne čudite se temu, kajti prihaja ura, v kateri bodo vsi, ki so v grobovih, slišali njegov glas');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'in bodo prišli naprej; tisti, ki so delali dobro, k vstajenju življenja; tisti pa, ki so delali zlo, k vstajenju prekletstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, '§ Jaz sam od sebe ne morem ničesar storiti. Kakor slišim, sodim in moja sodba je pravična, ker ne iščem svoje lastne volje, temveč voljo Očeta, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Če jaz pričujem o sebi, moje pričevanje ni resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Drug je, ki prinaša pričevanje o meni in vem, da je pričevanje, s katerim pričuje o meni, resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vi ste poslali k Janezu in on pričuje za resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Toda jaz pričevanja ne sprejemam od človeka, toda te stvari govorim, da bi bili vi lahko rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'On je bil goreča in sijoča svetloba in vi ste se bili voljni nekaj časa veseliti v njegovi svetlobi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Toda jaz imam večje pričevanje kakor [to] od Janeza, kajti dela, ki mi jih je Oče dal, da jih dokončam, ista dela, ki jih jaz opravljam, pričujejo o meni, da me je poslal Oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'In sam Oče, ki me je poslal, je prinesel pričevanje o meni. Vi niste nikoli slišali njegovega glasu, niti videli njegovega videza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'In vi nimate njegove besede, ki bi ostajala v vas, kajti kogar je on poslal, njemu ne verujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Preiskujete pisma, kajti v njih mislite, [da] imate večno življenje. To pa so ta, ki pričujejo o meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'In vi nočete priti k meni, da bi lahko imeli življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ne sprejemam časti od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Toda poznam vas, da v sebi nimate Božje ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Prišel sem v imenu svojega Očeta in me ne sprejmete. Če bo kdo drug prišel v svojem lastnem imenu, ga boste sprejeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kako lahko verujete vi, ki sprejemate čast drug od drugega, pa ne iščete časti, ki prihaja samo od Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne mislite, da vas bom jaz tožil Očetu. Nekdo je, ki vas toži, celó Mojzes, v katerega zaupate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Kajti če bi verovali Mojzesu, bi verovali meni, kajti pisal je o meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Toda če ne verujete njegovim pisanjem, kako boste verovali mojim besedam?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Po teh besedah se je Jezus peljal preko Galilejskega morja, kar je Tiberijsko morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Sledila mu je velika množica, ker so videli njegove čudeže, ki jih je storil na teh, ki so bili bolni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, '§ In Jezus je odšel gor na goro ter tam sédel s svojimi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'In blizu je bila pasha, judovski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Ko je Jezus tedaj povzdignil svoje oči in zagledal k njemu prihajati veliko skupino, reče Filipu: »Od kod naj kupimo kruha, da bodo ti lahko jedli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'To pa je rekel, da bi ga preizkusil, kajti sam je vedel, kaj bo storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filip mu je odgovoril: »Dvesto denarjev kruha zanje ni zadosti, da bi vsak izmed njih lahko nekaj vzel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Eden izmed njegovih učencev, Andrej, brat Simona Petra, mu reče:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '»Tukaj je deček, ki ima pet ječmenovih hlebov in dve majhni ribi. Toda kaj je to med tako mnogimi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'In Jezus je dejal: »Storite, da se ljudje usedejo.« Torej na tem kraju je bilo mnogo trave. Tako so se ljudje usedli, po številu okoli pet tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'In Jezus je vzel hlebe in ko se je zahvalil, je razdelil učencem in učenci tem, ki so se usedli, in podobno od rib, toliko, kolikor so hoteli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Ko so bili nasičeni, je svojim učencem rekel: »Zberite odlomke, ki ostanejo, da ne bo nič izgubljeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Zato so jih zbrali skupaj in napolnili dvanajst košar z odlomki od petih ječmenovih hlebov, ki so ostali vrh tega tem, ki so jedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Tedaj so ti ljudje, ko so videli čudež, ki ga je Jezus storil, rekli: »To je resnično ta prerok, ki naj bi prišel na svet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Ko je torej Jezus zaznal, da bodo prišli in ga s silo odvedli, da ga postavijo za kralja, je ponovno sam odšel na goro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'In sedaj, ko je prišel večer, so njegovi učenci odšli dol k morju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'in vstopili na ladjo ter se preko morja peljali proti Kafarnáumu. Bilo pa je že temno in Jezus ni prišel k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Zaradi velikega vetra, ki je pihal, se je morje vzdignilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Ko so preveslali že okoli petindvajset ali trideset dolžin brazd, so zagledali Jezusa hoditi po morju in prihajati bliže k ladji in bili so prestrašeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Toda on jim reče: »Jaz sem, ne bodite prestrašeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Potem so ga voljno sprejeli na ladjo in ladja je bila takoj pri deželi, kamor so šli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Naslednjega dne, ko je množica, ki je stala na drugi strani morja, videla, da tam ni bilo nobenega drugega čolna, razen tistega, v katerega so vstopili njegovi učenci in da Jezus s svojimi učenci ni vstopil na čoln, temveč, da so njegovi učenci odšli sami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(čeprav so iz Tiberije prišli drugi čolni v bližino kraja, kjer so jedli kruh, potem ko se je Gospod zahvalil);');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'ko je množica torej videla, da Jezusa ni bilo tam niti njegovih učencev, so se tudi sami, ker so iskali Jezusa, vkrcali in prišli v Kafarnáum.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'In ko so ga našli na drugi strani morja, so mu rekli: »Rabi, kdaj si prišel sèm?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jezus jim je odgovoril in rekel: »Resnično, resnično, povem vam: ›Ne iščete me, ker ste videli čudeže, temveč ker ste jedli od hlebov in bili nasičeni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Ne trudite se za jed, ki propada, temveč za jed, ki vzdrži v večno življenje, ki vam jo bo dal Sin človekov, kajti njega je potrdil Oče Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Tedaj so mu rekli: »Kaj naj storimo, da bomo lahko delali Božja dela?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jezus je odgovoril in jim rekel: »Božje delo je to, da verujete v tistega, ki ga je on poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Rekli so mu torej: »Kakšno znamenje torej pokažeš, da bomo lahko videli in ti verovali? Kaj delaš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Naši očetje so v puščavi jedli mano, kakor je pisano: ›Kruh iz nebes jim je dajal jesti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Potem jim je Jezus rekel: »Resnično, resnično, povem vam: ›Ni vam Mojzes dal tega kruha iz nebes, temveč vam moj Oče daje resničen kruh iz nebes.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Kajti Božji kruh je tisti, ki prihaja dol iz nebes in daje svetu življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Tedaj so mu rekli: »Gospod, vselej nam daj tega kruha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'In Jezus jim je rekel: »Jaz sem kruh življenja. Kdor prihaja k meni, ne bo nikoli lačen. In kdor vame veruje, ne bo nikoli žejen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Toda rekel sem vam: ›Da ste me vi tudi videli, pa ne verujete.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Vse, kar mi daje Oče, bo prišlo k meni, in tistega, ki prihaja k meni, nikakor ne bom izgnal ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Kajti prišel sem dol iz nebes, ne da delam svojo lastno voljo, temveč voljo tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'In to je volja Očeta, ki me je poslal, da od vsega, kar mi je dal, ne bi ničesar izgubil, temveč bi ob poslednjem dnevu to ponovno dvignil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'In to je volja tistega, ki me je poslal, da bo vsakdo, ki vidi Sina in veruje vanj, lahko imel večno življenje in jaz ga bom dvignil na poslednji dan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Judje so tedaj godrnjali nad njim, ker je rekel: »Jaz sem kruh, ki je prišel dol iz nebes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'In govorili so: »Ali ni to Jezus, Jožefov sin, katerega očeta in mater poznamo? Kako to potem, da pravi: ›Prišel sem dol iz nebes?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jezus je torej odgovoril in jim rekel: »Ne godrnjajte med seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nihče ne more priti k meni, razen če ga ne pritegne Oče, ki me je poslal in jaz ga bom dvignil na poslednji dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'V prerokih je pisano: ›In vsi bodo poučeni od Boga.‹ Vsak torej, ki je slišal in se naučil od Očeta, prihaja k meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ne da je katerikoli človek videl Očeta, samo tisti, ki je od Boga, on je videl Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, '§ Resnično, resnično, povem vam: ›Kdor veruje vame, ima večno življenje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Jaz sem ta kruh življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vaši očetje so v divjini jedli mano in so mrtvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'To je kruh, ki prihaja dol iz nebes, da lahko človek od tega jé in ne umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Jaz sem živi kruh, ki je prišel dol iz nebes. Če katerikoli človek od tega kruha jé, bo živel večno, in kruh, ki ga bom jaz dal, je moje meso, ki ga bom dal za življenje sveta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Judje so se torej med seboj prepirali, rekoč: »Kako nam lahko ta človek da jesti svoje meso?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Tedaj jim je Jezus rekel: »Resnično, resnično, povem vam: ›Razen, če ne jeste mesa Sina človekovega in ne pijete njegove krvi, v sebi nimate življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kdorkoli jé moje meso in pije mojo kri, ima večno življenje in jaz ga bom dvignil na poslednji dan.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Kajti zares je moje meso hrana in zares je moja kri pijača.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kdor jé moje meso in pije mojo kri, prebiva v meni in jaz v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Kakor me je poslal živi Oče in jaz živim po Očetu. Ravno tako, kdor mene jé, celó ta bo živel po meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, '§ To je ta kruh, ki je prišel dol iz nebes. Ne kakor vaši očetje, ki so jedli mano in so mrtvi. Kdor jé od tega kruha, bo živel večno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Te stvari je povedal v sinagogi, ko je učil v Kafarnáumu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Zatorej so mnogi izmed njegovih učencev, ko so to slišali, rekli: »To je trda beseda, kdo jo lahko posluša?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Potem ko je Jezus v sebi vedel, da so njegovi učenci nad tem godrnjali, jim je rekel: »Ali vas to pohujšuje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Kaj pa, če boste videli Sina človekovega dvigniti se gor, kjer je bil prej?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duh je, ki oživlja, meso nič ne koristi. Besede, ki vam jih govorim, te so duh in te so življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Toda tam so nekateri izmed vas, ki ne verujejo.« Kajti Jezus je že od začetka vedel kdo so bili ti, ki niso verovali in kdo naj bi ga izdal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'In rekel je: »Zato sem vam rekel, da nihče ne more priti k meni, razen če mu ni dano od mojega Očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Od tega časa je mnogo izmed njegovih učencev odšlo nazaj in niso več hodili z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Tedaj je Jezus dvanajsterim rekel: »Ali hočete tudi vi oditi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Potem mu je Simon Peter odgovoril: »Gospod, h komu naj gremo? Ti imaš besede večnega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, '§ In mi verujemo in smo prepričani, da si ti ta Kristus, Sin živega Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jezus jim je odgovoril: »Ali vas nisem izbral dvanajst in je eden izmed vas hudič?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Govoril je o Judu Iškarijotu, Simonovem sinu, kajti on je bil ta, ki naj bi ga izdal in je izmed dvanajsterice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Po teh besedah je Jezus hodil po Galileji, kajti ni želel hoditi po Judeji, ker so si Judje prizadevali, da ga ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Torej blizu je bil judovski šotorski praznik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Njegovi bratje so mu zatorej rekli: »Odidi od tod in pojdi v Judejo, da bodo tudi tvoji učenci lahko videli dela, ki jih delaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Kajti nobenega človeka ni, ki karkoli dela na skrivnem in si sam prizadeva, da bi bil javno znan. Če delaš te stvari, se pokaži svetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Kajti niti njegovi bratje niso verovali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Tedaj jim je Jezus rekel: »Moj čas še ni prišel, toda vaš čas je vedno pripravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Vas svet ne more sovražiti, toda mene sovraži, ker pričujem o njem, da so le-tega dela hudobna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, '§ Pojdite gor na ta praznik. Jaz še ne grem na ta praznik, kajti moj čas še ni dopolnjen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Ko jim je povedal te besede, je še vedno prebival v Galileji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Toda ko so njegovi bratje odšli gor, potem je tudi on odšel gor na praznik, ne javno, temveč kakor bi bilo na skrivnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Potem so ga Judje med praznikom iskali in govorili: »Kje je tisti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'In glede njega je bilo med množico mnogo mrmranja, kajti nekateri so rekli: »Dober človek je,« drugi so rekli: »Ne, temveč zavaja množico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Vendar zaradi strahu pred Judi noben človek o njem ni govoril javno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Torej okoli srede praznika je Jezus odšel gor v tempelj in učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'In Judje so se čudili, rekoč: »Kako ta človek pozna pisma, saj se jih nikoli ni učil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jezus jim je odgovoril in rekel: »Moj nauk ni moj, temveč tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Če hoče katerikoli človek storiti njegovo voljo, bo iz nauka spoznal, če je to od Boga ali če govorim sam od sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kdor govori o sebi, išče svojo lastno slavo, toda kdor išče slavo tistega, ki ga je poslal, isti je resničen in v njem ni nobene nepravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Ali vam ni Mojzes dal postave in še izmed vas se nihče ne drži postave? Zakaj me poskušate ubiti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Množica je odgovorila in rekla: »Hudiča imaš. Kdo se pripravlja, da te ubije?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jezus je odgovoril in jim rekel: »Eno delo sem storil in vsi se čudite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Mojzes vam je torej dal obrezovanje (ne, ker je od Mojzesa, temveč od očetov) in vi na šabatni dan obrežete človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Če človek na šabat prejme obrezovanje, da se Mojzesova postava ne bi prekršila; ali ste jezni name, ker sem na šabatni dan ozdravil vsak najmanjši delček človeka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne sodite glede na videz, temveč sodite pravično sodbo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tedaj so nekateri izmed teh iz Jeruzalema rekli: »Ali ni to ta, ki si ga prizadevajo ubiti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Ampak glejte, pogumno govori, pa mu ničesar ne rečejo. Ali so vladarji zares spoznali, da je ta pravi Kristus?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Vendar mi vemo, od kod je ta človek; toda ko pride Kristus, noben človek ne bo vedel, od kod je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Tedaj je Jezus, med poučevanjem v templju, zaklical, rekoč: »Vi me tako poznate, kakor veste od kod sem in nisem prišel sam od sebe, temveč je tisti, ki me je poslal, resničen, ki ga vi ne poznate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Toda jaz ga poznam, ker sem od njega in me je on poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Prizadevali so si torej, da ga primejo, toda noben človek nanj ni položil rok, ker njegova ura še ni prišla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mnogi izmed množice pa so verovali vanj in rekli: »Ko pride Kristus ali bo storil več čudežev, kakor jih je storil ta človek?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Farizeji so slišali, da množica glede njega godrnja takšne besede, in farizeji in visoki duhovniki so poslali častnike, da ga primejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Potem jim je Jezus rekel: »Še malo časa sem z vami in potem grem k tistemu, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Iskali me boste, pa me ne boste našli; in kjer sem jaz, tja vi ne morete priti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, '§ Tedaj so Judje med seboj govorili: »Kam bo šel, da ga ne bomo našli? Ali bo šel k razkropljenim med pogane in učil pogane?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Kakšne vrste govorjenje je to, da je rekel: ›Iskali me boste, pa me ne boste našli; in kjer sem jaz, tja vi ne morete priti?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Na zadnji dan, veliki dan praznika, je Jezus vstal in zaklical, rekoč: »Če je katerikoli človek žejen, naj pride k meni in pije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kdor veruje vame, kakor pravi pismo, bodo iz njegovega trebuha tekle reke žive vode.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(Toda to je govoril o Duhu, ki naj bi ga prejeli tisti, ki verujejo vanj, kajti Sveti Duh še ni bil dan, zato ker Jezus še ni bil proslavljen.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Mnogi izmed množice so torej, ko so slišali te besede, rekli: »Resnično, ta je Prerok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Drugi so rekli: »Ta je Kristus.« Toda nekateri so rekli: »Mar bo Kristus prišel iz Galileje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Mar ni pismo reklo: ›Da prihaja Kristus iz Davidovega semena in iz mesta Betlehem, kjer je bil David?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Med množico je bilo torej zaradi njega nesoglasje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'In nekateri izmed njih so ga hoteli prijeti, toda nanj noben človek ni položil rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Potem so prišli častniki k visokim duhovnikom in farizejem in ti so jim rekli: »Zakaj ga niste privedli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Častniki so odgovorili: »Nikoli [noben] človek ni govoril kakor ta človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Tedaj so jim farizeji odgovorili: »Ali ste tudi vi zavedeni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Ali je kdo izmed vladarjev ali izmed farizejev veroval vanj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Toda ta množica, ki ne pozna postave, je prekleta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nikodém (tisti, ki je ponoči prišel k Jezusu in je bil eden izmed njih) jim reče:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '»Ali naša postava kateregakoli človeka obsodi, preden ga ne zasliši in ne izve, kaj on dela?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Odgovorili so in mu rekli: »Ali si tudi ti iz Galileje? Preišči in poglej, kajti iz Galileje ne vstane noben prerok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'In vsak je odšel v svojo lastno hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jezus je odšel k Oljski gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Zgodaj zjutraj je ponovno prišel v tempelj in vsi ljudje so prišli k njemu, in usedel se je ter jih učil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'In pisarji in farizeji so k njemu privedli žensko, zasačeno v zakonolomstvu; in ko so jo postavili v sredo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, '§ so mu rekli: »Učitelj, ta ženska je bila zasačena v zakonolomstvu, pri samem dejanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Torej Mojzes nam je v postavi ukazal, da naj bi bili taki kamnani. Toda kaj praviš ti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'To so rekli, ker so ga skušali, da bi ga lahko obtožili. Jezus pa se je sklonil in s svojim prstom pisal po tleh, kakor da jih ni slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Torej, ko so ga še naprej spraševali, se je vzravnal in jim rekel: »Kdor je med vami brez greha, naj prvi vrže kamen vanjo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'In ponovno se je sklonil ter pisal po tleh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, '§ In ti, ki so to slišali, so obsojeni po svoji lastni vesti, drug za drugim odšli ven, s pričetkom pri najstarejših, celó do zadnjega; in Jezus je ostal sam ter ženska, stoječa v sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Ko se je Jezus dvignil in ni videl nikogar razen ženske, ji je rekel: »Ženska, kje so ti tvoji tožniki? Ali te nihče ni obsodil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Rekla je: »Noben človek, Gospod.« In Jezus ji je rekel: »Niti te jaz ne obsojam. Pojdi in ne greši več.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Potem jim je Jezus ponovno spregovoril, rekoč: »Jaz sem svetloba sveta. Kdor sledi meni, ne bo hodil v temi, temveč bo imel svetlobo življenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Farizeji so mu torej rekli: »Ti prinašaš pričevanje o sebi; tvoje pričevanje ni resnično.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jezus je odgovoril in jim rekel: »Četudi pričujem o samem sebi, je vendarle moje pričevanje resnično, kajti jaz vem, od kod sem prišel in kam grem, toda vi ne morete povedati, od kod sem prišel in kam grem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vi sodite po mesu; jaz ne sodim nobenega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Če pa vendarle sodim, je moja sodba resnična, kajti nisem sam, temveč jaz in Oče, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Tudi v vaši postavi je zapisano, da je pričevanje dveh ljudi resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jaz sem nekdo, ki pričuje o samem sebi in Oče, ki me je poslal, prinaša pričevanje o meni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Tedaj so mu rekli: »Kje je tvoj Oče?« Jezus je odgovoril: »Vi ne poznate niti mene niti mojega Očeta. Če bi poznali mene, bi poznali tudi mojega Očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Te besede je Jezus govoril v zakladnici, medtem ko je učil v templju. In nanj noben človek ni položil rok, kajti njegova ura še ni prišla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Potem jim je Jezus ponovno rekel: »Jaz grem svojo pot in iskali me boste in umrli boste v svojih grehih. Kamor grem jaz, vi ne morete priti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Tedaj so Judje rekli: »Ali bo samega sebe ubil, ker pravi: ›Kamor grem jaz, vi ne morete priti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'In rekel jim je: »Vi ste od spodaj, jaz sem od zgoraj; vi ste od tega sveta, jaz nisem od tega sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Povedal sem vam torej, da boste umrli v svojih grehih; kajti če ne verujete, da jaz sem, boste umrli v svojih grehih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Tedaj so mu rekli: »Kdo si?« In Jezus jim reče: »Celo isti, kakor sem vam povedal od začetka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Povedati vam imam mnogo besed in soditi o vas, toda tisti, ki me je poslal, je resničen in svetu govorim te besede, ki sem jih slišal od njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Niso pa razumeli, da jim je govoril o Očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Tedaj jim je Jezus rekel: »Ko boste povzdignili Sina človekovega, potem boste spoznali, da jaz sem in da ničesar ne delam sam od sebe, temveč te stvari govorim, kakor me je naučil moj Oče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'In tisti, ki me je poslal, je z menoj. Oče me ni pustil samega, kajti vedno delam te stvari, ki mu ugajajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Ko je govoril te besede, so mnogi verovali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Tem Judom, ki so verovali vanj, je tedaj Jezus rekel: »Če ostanete v moji besedi, potem ste zares moji učenci');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'in spoznali boste resnico in resnica vas bo osvobodila.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Odgovorili so mu: »Mi smo Abrahamovo seme in nikoli nismo bili nobenemu človeku v suženjstvu. Kako praviš: ›Osvobojeni boste?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jezus jim je odgovoril: »Resnično, resnično, povem vam: ›Kdorkoli zagreši greh, je služabnik greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'In služabnik v hiši ne ostaja za vedno, toda Sin ostaja večno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Če vas bo torej Sin osvobodil, boste zares svobodni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Vem, da ste Abrahamovo seme, toda vi si prizadevate, da me ubijete, ker moja beseda v vas nima prostora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Jaz govorim to, kar sem videl pri svojem Očetu, vi pa delate to, kar ste videli pri svojem očetu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odgovorili so in mu rekli: »Naš oče je Abraham.« Jezus jim reče: »Če bi bili Abrahamovi otroci, bi delali Abrahamova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Toda sedaj si prizadevate, da me ubijete, človeka, ki vam je povedal resnico, ki sem jo slišal od Boga. Tega Abraham ni storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vi opravljate dela svojega očeta.« Tedaj so mu rekli: »Mi nismo rojeni iz prešuštva; mi imamo enega Očeta, celó Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jezus jim je rekel: »Če bi bil vaš Oče Bog, bi me ljubili, kajti jaz sem izšel in sem prišel od Boga; niti nisem prišel sam od sebe, temveč me je on poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Zakaj ne razumete mojega govora? Zato ker celó ne morete poslušati moje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vi ste od svojega očeta, hudiča in počeli boste poželjivosti svojega očeta. On je bil od začetka morilec in ni ostal v resnici, ker v njem ni resnice. Ko govori laž, govori iz svojega lastnega, kajti on je lažnivec in oče le-te.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'In ker vam govorim resnico, mi ne verjamete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kdo izmed vas me prepričuje o grehu? Če pa govorim resnico, zakaj mi ne verjamete?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kdor je iz Boga, posluša Božje besede. Vi jih torej ne poslušate, ker niste iz Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Tedaj so Judje odgovorili in mu rekli: »Ali ne govorimo prav, da si Samarijan in imaš hudiča?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jezus je odgovoril: »Jaz nimam hudiča, temveč častim svojega Očeta, vi pa me onečaščate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'In ne iščem svoje lastne slave; obstaja nekdo, ki išče in sodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Resnično, resnično, povem vam: ›Če se človek drži moje besede, nikoli ne bo videl smrti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Tedaj so mu Judje rekli: »Torej, mi vemo, da imaš hudiča. Abraham je mrtev in preroki; ti pa praviš: ›Če se človek drži moje besede, nikoli ne bo okusil smrti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Ali si ti večji kakor naš oče Abraham, ki je mrtev? In tudi preroki so mrtvi. Koga se ti sam delaš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jezus je odgovoril: »Če jaz častim samega sebe, moja čast ni nič. Moj Oče je ta, ki me časti, o katerem vi pravite, da je on vaš Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Vendarle ga vi niste spoznali, toda jaz ga poznam. In če bi rekel: ›Ne poznam ga,‹ bi bil lažnivec, podoben vam. Toda jaz ga poznam in se držim njegove besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Vaš oče Abraham se je razveselil, da vidi moj dan. In videl ga je in je bil vesel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Tedaj so mu Judje rekli: »Še petdeset let nisi star in si videl Abrahama?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jezus jim je rekel: »Resnično, resnično, povem vam: ›Preden je bil Abraham, jaz sem.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, '§ Tedaj so pobrali kamne, da bi jih vrgli vanj, toda Jezus se je skril in odšel iz templja, gredoč skozi njihovo sredo in tako odšel mimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'In ko je Jezus šel mimo, je zagledal človeka, ki je bil slep od svojega rojstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'In njegovi učenci so ga vprašali, rekoč: »Učitelj, kdo je storil greh, ta človek ali njegovi starši, da je bil rojen slep.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jezus je odgovoril: »Niti ni ta človek grešil niti njegovi starši, temveč, da bi se na njem razodela Božja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Dokler je dan, moram delati dela tistega, ki me je poslal. Prihaja noč, ko noben človek ne more delati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Kolikor dolgo sem na svetu, sem svetloba sveta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ko je to izgovoril, je pljunil na tla in iz sline naredil blato in z blatom mazilil oči slepega človeka');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'ter mu rekel: »Pojdi, umij se v bazenu Síloi,« (kar je po razlagi: ›Poslani.‹) Odšel je torej svojo pot in se umil in prišel ter videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Torej sosedje in tisti, ki so ga prej videli, da je bil slep, so rekli: »Ali ni to tisti, ki je sedel in beračil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Nekateri so rekli: »To je on,« drugi so rekli: »Podoben mu je.« Toda on je rekel: »Jaz sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Zaradi tega so mu rekli: »Kako so bile tvoje oči odprte?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Odgovoril je in rekel: »Človek, ki se imenuje Jezus, je naredil blato ter mazilil moje oči in mi rekel: ›Pojdi k bazenu Síloa in umij.‹ In odšel sem in umil ter prejel vid.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Potem so mu rekli: »Kje je tisti?« Rekel je: »Ne vem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'K farizejem so privedli tistega, ki je bil poprej slep.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'In bil je šabatni dan, ko je Jezus naredil blato in odprl njegove oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Tedaj so ga tudi farizeji ponovno vprašali, kako je prejel svoj vid. Rekel jim je: »Na moje oči je položil blato in sem umil ter vidim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Zato so nekateri izmed farizejev rekli: »Ta človek ni od Boga, ker se ne drži šabatnega dne.« Drugi so rekli: »Kako lahko človek, ki je grešnik, dela takšne čudeže?« In med njimi je bilo nesoglasje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Slepemu možu so ponovno rekli: »Kaj praviš o tistem, ki ti je odprl tvoje oči?« Rekel je: »Prerok je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Toda Judje glede njega niso verjeli, da je bil slep in je prejel svoj vid, dokler niso poklicali staršev tega, ki je prejel svoj vid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'In vprašali so ju, rekoč: »Je to vajin sin, o katerem pravite, da je bil rojen slep? Kako potem sedaj vidi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Njegova starša sta jim odgovorila in rekla: »Midva veva, da je to najin sin in da je bil rojen slep,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'toda na kakšen način on sedaj vidi, midva ne veva; ali kdo je odprl njegove oči, midva ne veva. Dovolj je star, njega vprašajte, on bo govoril zase.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Te besede so njegovi starši govorili zato, ker so se bali Judov, kajti Judje so se že sporazumeli, da če bi katerikoli človek priznal, da je bil on Kristus, bi bil le-ta izločen iz sinagoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Zaradi tega so njegovi starši rekli: »Dovolj je star, njega vprašajte.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Tedaj so ponovno poklicali moža, ki je bil slep in mu rekli: »Daj Bogu hvalo. Mi vemo, da je ta človek grešnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Odgovoril je in rekel: »Če je grešnik ali ne, ne vem. Eno stvar vem, glede na to, da sem bil slep, sedaj vidim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Tedaj so mu ponovno rekli: »Kaj ti je storil? Kako je odprl tvoje oči?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odgovoril jim je: »Povedal sem vam že, pa niste poslušali. Zakaj bi to radi ponovno slišali? Hočete biti tudi vi njegovi učenci?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Tedaj so ga zasramovali in rekli: »Ti si njegov učenec, toda mi smo Mojzesovi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Mi vemo, da je Mojzesu govoril Bog; glede tega pa ne vemo, od kod je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Človek je odgovoril in jim rekel: »Zakaj v tem je čudovita stvar, da vi ne veste, od kod je, pa je vendar odprl moje oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Torej vemo, da Bog ne sliši grešnikov; toda če je katerikoli človek oboževalec Boga in izvršuje njegovo voljo, njega on sliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Odkar je svet nastal, se ni slišalo, da bi katerikoli človek odprl oči nekoga, ki je bil rojen slep.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Če ta človek ne bi bil od Boga, ne bi mogel ničesar storiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Odgovorili so mu in mu rekli: »Povsem si bil rojen v grehih in nas ti učiš?« In vrgli so ga ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jezus je slišal, da so ga vrgli ven. In ko ga je našel, mu je rekel: »Ali veruješ v Božjega Sina?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Odgovoril je in rekel: »Kdo je ta, Gospod, da bi lahko veroval vanj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jezus mu je rekel: »Ti si ga oboje [in] videl in ta je, ki govori s teboj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'In rekel je: »Gospod, verujem.« In ga je oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Jezus je rekel: »Za sodbo sem prišel na ta svet, da bi tisti, ki ne vidijo, lahko videli in da bi tisti, ki vidijo, lahko oslepeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Nekateri izmed farizejev, ki so bili z njim, so slišali te besede in mu rekli: »Ali smo tudi mi slepi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jezus jim je rekel: »Če bi bili slepi, ne bi imeli greha, toda sedaj pravite: ›Vidimo,‹ zato vaš greh ostaja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '»Resnično, resnično, povem vam: ›Kdor v ovčjo stajo ne vstopa pri vratih, temveč se vzpenja po neki drugi poti, ta isti je tat in razbojnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Toda kdor vstopa pri vratih, je pastir ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Njemu vratar odpira in ovce slišijo njegov glas in svoje lastne ovce kliče po imenu in jih vodi ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'In ko svoje lastne ovce poganja naprej, gre pred njimi in ovce mu sledijo, kajti njegov glas poznajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Tujcu pa ne bodo sledile, temveč bodo bežale pred njim, kajti glasu tujcev ne poznajo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jezus jim je povedal to prispodobo, toda niso razumeli, kaj bi bile te besede, ki jim jih je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Potem jim je Jezus ponovno rekel: »Resnično, resnično, povem vam: ›Jaz sem vrata ovcam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Vsi, ki so kadarkoli prišli pred menoj, so tatovi in razbojniki, toda ovce jih niso poslušale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Jaz sem vrata; če kdorkoli vstopi noter po meni, bo rešen in bo hodil ven in noter ter najde pašo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Tat ne prihaja, razen da krade in da ubija ter da uničuje. Jaz sem prišel, da bi lahko imeli življenje in da bi ga lahko imeli bolj obilno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Jaz sem dobri pastir. Dobri pastir daje svoje življenje za ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Toda kdor je najemnik in ni pastir, katerega ovce niso njegova last, vidi prihajati volka in zapusti ovce ter zbeži, volk pa ovce lovi in jih razkropi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Najemnik beži, ker je najemnik in ne skrbi za ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Jaz sem dobri pastir in poznam svoje ovce in moje poznajo mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Kakor Oče pozna mene, točno tako jaz poznam Očeta in svoje življenje dam za ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Imam pa tudi druge ovce, ki niso iz te staje. Tudi te moram privesti in bodo slišale moj glas in bo ena staja in en pastir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Zato me moj Oče ljubi, ker dam svoje življenje, da ga lahko ponovno prejmem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nihče ga ne jemlje od mene, temveč ga dajem sam od sebe. Imam moč, da ga dam in imam moč, da ga ponovno prejmem. To zapoved sem prejel od svojega Očeta.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Zaradi teh besed je bilo med Judi ponovno nesoglasje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'In mnogi izmed njih so rekli: »Hudiča ima, pa tudi nor je; zakaj ga poslušate?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Drugi so rekli: »To niso besede tistega, ki ima hudiča. Ali lahko hudič slepemu odpre oči?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'V Jeruzalemu pa je bil praznik posvetitve in bila je zima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'In Jezus je hodil v templju po Salomonovem preddverju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Potem so prišli Judje, ga obkrožili in mu rekli: »Doklej nas boš še pustil, da dvomimo? Če si ti Kristus, nam odkrito povej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jezus jim je odgovoril: »Povedal sem vam, pa niste verovali. Dela, ki jih delam v imenu svojega Očeta, ta pričujejo o meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Toda vi ne verujete, ker kakor sem vam povedal, niste izmed mojih ovc.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Moje ovce slišijo moj glas in jaz jih poznam in one mi sledijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'in dam jim večno življenje in nikoli ne bodo propadle niti jih noben človek ne bo iztrgal iz moje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Moj Oče, ki jih je dal meni, je večji od vseh in noben človek jih ne more izpuliti iz roke mojega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Jaz in moj Oče sva eno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Po tem so Judje ponovno pobrali kamne, da ga kamnajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jezus jim je odgovoril: »Mnogo dobrih del sem vam pokazal od svojega Očeta; za katerega izmed teh del me kamnate?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Judje so mu odgovorili, rekoč: »Ne kamnamo te zaradi dobrega dela; temveč zaradi bogokletja; in zato, ker se ti, ki si človek, sebe delaš Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jezus jim je odgovoril: »Ali ni v vaši postavi zapisano: ›Rekel sem: ›Vi ste bogovi?‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Če pa je imenoval bogove te, ki jim je prišla Božja beseda in pismo ne more biti prekršeno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'pravite o njem, ki ga je Oče posvetil in poslal na svet: ›Ti preklinjaš,‹ ker sem rekel, da sem Božji Sin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Če ne opravljam del svojega Očeta, mi ne verjemite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Toda če jih opravljam, čeprav mi ne verjamete, verjemite delom, da boste lahko spoznali in verovali, da je Oče v meni in jaz v njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Zato so si ponovno prizadevali, da ga primejo, toda pobegnil je iz njihove roke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'in ponovno odšel proč, onstran Jordana, na kraj, kjer je Janez najprej krščeval in tam ostal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'In mnogi so krenili k njemu ter rekli: »Janez ni storil nobenega čudeža, toda vse besede, ki jih je Janez govoril o tem človeku, so bile resnične.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'In tam so mnogi verovali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Torej nek mož je bil bolan, po imenu Lazar, iz Betanije, mesta Marije in njene sestre Marte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(Marija je bila tista, ki je Gospoda mazilila z mazilom in je s svojimi lasmi obrisala njegova stopala, katere brat Lazar je bil bolan.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Zato sta njegovi sestri poslali k njemu, rekoč: »Gospod, glej, tisti, ki ga imaš rad, je bolan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Ko je Jezus to slišal, je rekel: »Ta bolezen ni za smrt, temveč za Božjo slavo, da bo Božji Sin s tem lahko proslavljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Torej Jezus je ljubil Marto in njeno sestro ter Lazarja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Ko je torej slišal, da je bil bolan, je še dva dni ostal na istem kraju, kjer je bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Šele nató reče svojim učencem: »Ponovno pojdimo v Judejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Njegovi učenci mu rečejo: »Učitelj, Judje so si nedavno prizadevali, da te kamnajo, ti pa greš ponovno tja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jezus je odgovoril: »Ali ni v dnevu dvanajst ur? Če katerikoli človek hodi podnevi, se ne spotika, ker vidi svetlobo tega sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Toda če človek hodi ponoči, se spotika, ker v njem ni svetlobe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Te besede je rekel in nató jim reče: »Naš prijatelj Lazar spi, vendar grem, da ga lahko zbudim iz spanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Tedaj so njegovi učenci rekli: »Gospod, če spi, bo okreval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Vendar je Jezus govoril o njegovi smrti, toda mislili so, da je govoril o počitku v spanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tedaj jim je Jezus odkrito povedal: »Lazar je mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Zaradi vas pa sem vesel, da nisem bil tam, z namenom, da boste lahko verovali, vendar pojdimo k njemu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tedaj je Tomaž, ki se je imenoval Dvojček, rekel svojim součencem: »Naj gremo tudi mi, da bomo lahko umrli z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Potem ko je Jezus prišel, je odkril, da je že štiri dni ležal v grobu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Torej Betanija je bila blizu Jeruzalema, okoli petnajst dolžin brazd proč');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'in mnogi izmed Judov so prišli k Marti in Mariji, da ju tolažijo glede njunega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Potem je Marta, takoj ko je slišala, da je prihajal Jezus, odšla in ga srečala, toda Marija je še vedno sedela v hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Tedaj je Marta rekla Jezusu: »Gospod, če bi bil ti tukaj, moj brat ne bi umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Toda jaz vem, da celó sedaj, karkoli hočeš prositi od Boga, ti bo Bog to dal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jezus ji reče: »Tvoj brat bo ponovno vstal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta mu reče: »Vem, da bo ponovno vstal na vstajenje ob poslednjem dnevu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, '§ Jezus ji je rekel: »Jaz sem vstajenje in življenje. Kdor vame veruje, četudi bi bil mrtev, bo vendarle živel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'In kdorkoli živi in veruje vame, ne bo nikoli umrl. Veruješ to?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Ona mu reče: »Da, Gospod. Verujem, da si ti Kristus, Božji Sin, ki naj bi prišel na svet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'In ko je tako rekla, je šla svojo pot in na skrivnem poklicala svojo sestro Marijo, rekoč: »Učitelj je prišel in te kliče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Brž ko je ona to zaslišala, je hitro vstala in prišla k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Torej Jezus še ni prišel v mesto, temveč je bil na kraju, kjer ga je srečala Marta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Ko so Judje, ki so bili z njo v hiši in jo tolažili, videli Marijo, da je v naglici vstala in odšla ven, so ji potem sledili, rekoč: »H grobu gre, da bi tam jokala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Torej ko je Marija prišla tja, kjer je bil Jezus in ga zagledala, je padla dol k njegovim stopalom in mu rekla: »Gospod, če bi bil ti tukaj, moj brat ne bi umrl.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Ko jo je Jezus torej videl jokajočo in jokajoče tudi Jude, ki so prišli z njo, je v duhu zastokal in bil vznemirjen');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'ter rekel: »Kam ste ga položili?« Rekli so mu: »Gospod, pridi in poglej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jezus se je zjokal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Tedaj so Judje rekli: »Glejte, kako ga je imel rad!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Nekateri izmed njih pa so rekli: »Mar ni mogel ta človek, ki je slepemu odprl oči, storiti, da ta mož sploh ne bi umrl?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jezus torej, v sebi ponovno stokajoč, pride h grobu. To je bila votlina in nanjo je bil položen kamen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jezus je rekel: »Odstranite kamen proč.« Marta, sestra tega, ki je bil mrtev, mu reče: »Gospod, do sedaj že zaudarja, kajti mrtev je štiri dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jezus ji reče: »Kaj ti nisem rekel, da če boš verovala, boš videla Božjo slavo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Tedaj so odstranili kamen z mesta, kamor je bil mrtvi položen. Jezus pa je povzdignil svoje oči in rekel: »Oče, hvala ti, da si me uslišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'In vedel sem, da me ti vedno uslišiš, toda to sem rekel zaradi množice, ki stoji zraven, da bi lahko verovala, da si me ti poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'In ko je tako govoril, je z močnim glasom zaklical: »Lazar, pridi naprej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'In tisti, ki je bil mrtev, je prišel naprej, z rokami in nogami, povezanimi s pogrebnimi oblačili in njegov obraz je bil naokoli povezan s prtičem. Jezus jim reče: »Odvežite ga in ga pustite oditi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Potem so mnogi izmed Judov, ki so prišli k Mariji in videli stvari, ki jih je Jezus storil, verovali vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Toda nekateri izmed njih so odšli po svojih poteh k farizejem in jim povedali, kakšne stvari je Jezus storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Tedaj so visoki duhovniki in farizeji zbrali véliki zbor ter rekli: »Kaj [naj] storimo? Kajti ta človek dela mnoge čudeže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Če ga pustimo tako pri miru, bodo vsi ljudje verovali vanj in prišli bodo Rimljani in odvzeli tako naš prostor kakor narod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'In eden izmed njih, po imenu Kajfa, ki je bil to isto leto véliki duhovnik, jim je rekel: »Vi čisto nič ne veste,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'niti ne preudarite, da je za nas koristno, da naj bi en človek umrl za ljudi, ne pa da propade celoten narod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'To pa ni govoril [sam] od sebe, temveč ker je bil tisto leto véliki duhovnik, je prerokoval, da naj bi Jezus umrl za ta narod,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'in ne samo za ta narod, temveč da naj bi tudi Božje otroke, ki so bili razkropljeni naokoli, skupaj zbral v enem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Torej so se od tega dne dalje skupaj posvetovali, da ga usmrtijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jezus torej med Judi ni več hodil javno, temveč je od tam odšel v deželo poleg divjine, v mesto, imenovano Efrájim in tam ostal s svojimi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'In blizu je bila judovska pasha in mnogi iz dežele so pred pasho odšli gor v Jeruzalem, da se očistijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Medtem ko so stali v templju, so torej iskali Jezusa in med seboj govorili: »Kaj mislite, da ne bo prišel na praznik?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Torej tako visoki duhovniki kakor farizeji so izdali zapoved, da če katerikoli človek ve, kje bi bil, naj to pokaže, da bi ga lahko prijeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Potem je Jezus, šest dni pred pasho, prišel v Betanijo, kjer je bil Lazar, ki je bil mrtev, ki ga je obudil od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Tam so mu pripravili večerjo in Marta je stregla, toda Lazar je bil eden izmed teh, ki je z njim sedel za mizo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Tedaj je Marija vzela funt zelo dragocenega mazila iz narde in mazilila Jezusova stopala in s svojimi lasmi obrisala njegova stopala, in hiša je bila napolnjena z vonjem mazila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, '§ Potem reče eden izmed njegovih učencev, Juda Iškarijot, Simonov sin, ki naj bi ga izdal:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '»Zakaj ni bilo to mazilo prodano za tristo denarjev in dano revnim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, '§ To je rekel, ne, ker bi skrbel za revne, temveč zato, ker je bil tat in je imel mošnjo ter nosil, kar je bilo dano vanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Potem je Jezus rekel: »Pusti jo pri miru. To je zadržala za dan mojega pokopa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Kajti revne imate vedno s seboj, mene pa nimate vedno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Veliko ljudi izmed Judov je torej vedelo, da je bil tam. Niso pa prišli samo zaradi Jezusa, temveč, da bi lahko videli tudi Lazarja, ki ga je obudil od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Toda visoki duhovniki so se posvetovali, da bi mogli usmrtiti tudi Lazarja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'zato ker je zaradi tega razloga mnogo izmed Judov odšlo proč in verovalo v Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Naslednji dan je mnogo ljudi, ki so prišli na praznik, ko so slišali, da je v Jeruzalem prihajal Jezus,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'vzelo mladike palmovih dreves in mu odšlo naproti, da ga srečajo ter klicali: »Hozana: ›Blagoslovljen je Izraelov Kralj, ki prihaja v Gospodovem imenu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'In Jezus, ko je našel mladega osla, je sédel nanj, kakor je pisano:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '»Ne boj se, hči sionska, glej, tvoj Kralj prihaja, sedeč na osličjem žrebetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Teh stvari njegovi učenci sprva niso razumeli, toda ko je bil Jezus poveličan, potem so se spomnili, da so bile te stvari pisane o njem in da so mu te stvari storili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Množica torej, ki je bila z njim, ko je Lazarja poklical iz njegovega groba in ga obudil od mrtvih, je pričevala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Zaradi tega razloga ga je množica tudi srečala, ker so slišali, da je storil ta čudež.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Farizeji so torej med seboj govorili: » [Ali] ne zaznate, kako ničesar ne prevladate? Glejte, svet je odšel za njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'In med njimi so bili neki Grki, ki so ob prazniku prišli gor oboževat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Isti so torej prišli k Filipu, ki je bil iz Betsajde v Galileji in ga prosili, rekoč: »Gospod, mi bi videli Jezusa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filip prihaja ter pove Andreju in prav tako Andrej ter Filip povesta Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'In Jezus jima je odgovoril, rekoč: »Ura je prišla, da naj bi bil Sin človekov poveličan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Resnično, resnično, povem vam: ›Razen če pšenično zrno ne pade na tla in ne umre, ostaja sámo; toda če umre, obrodi mnogo sadu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kdor ima rad svoje življenje, ga bo izgubil; kdor pa svoje življenje na tem svetu sovraži, ga bo ohranil za večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Če katerikoli človek služi meni, naj mi sledi; in kjer sem jaz, tam bo tudi moj služabnik. Če katerikoli človek služi meni, ga bo moj Oče počastil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Sedaj je moja duša vznemirjena in kaj naj rečem? ›Oče, reši me pred to uro.‹ Toda zaradi tega razloga sem prišel v to uro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, '›Oče, proslavi svoje ime.‹« Tedaj je tja prišel glas iz nebes, rekoč: »Proslavil sem ga in ponovno ga bom proslavil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Množica torej, ki je stala poleg in to slišala, je rekla, da je zagrmelo; drugi so rekli: »Angel mu je govoril.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jezus je odgovoril in rekel: »Ta glas ni prišel zaradi mene, temveč zaradi vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Sedaj je sodba tega sveta. Sedaj bo princ tega sveta izgnan ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, '§ In jaz, če bom povzdignjen z zemlje, bom k sebi pritegnil vse ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'To je rekel, ker je naznanil, kakšne smrti naj bi umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Množica mu je odgovorila: »Iz postave smo slišali, da Kristus ostaja večno; in kako praviš ti: ›Sin človekov mora biti dvignjen?‹ Kdo je ta Sin človekov?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Potem jim je Jezus rekel: »Še malo časa je z vami svetloba. Hodíte, dokler imate svetlobo, da ne bi nad vas prišla tema, kajti kdor hodi v temi, ne ve, kam gre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dokler imate svetlobo, verujte v svetlobo, da boste lahko otroci svetlobe.« Te besede je govoril Jezus in odšel ter se skril pred njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Toda čeprav je pred njimi storil toliko čudežev, kljub temu niso verovali vanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'da se je lahko izpolnila beseda preroka Izaija, ki je govoril: ›Gospod, kdo je veroval našemu poročilu in komu se je razodel Gospodov laket?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Torej niso mogli verovati, zato ker je ta Izaija ponovno rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '›Oslepel je njihove oči in zakrknil njihovo srce, da ne bi mogli videti s svojimi očmi niti razumeti s svojim srcem in ne bi bili spreobrnjeni in bi jih jaz ne ozdravil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Te besede je izrekel Izaija, ko je videl njegovo slavo in govoril o njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Vendar so tudi med visokimi vladarji mnogi verovali vanj, toda zaradi farizejev ga niso priznali, da ne bi bili izločeni iz sinagoge,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'kajti bolj so ljubili hvalo ljudi kakor Božjo hvalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jezus je zaklical in rekel: »Kdor veruje vame, ne veruje vame, temveč v tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'In kdor vidi mene, vidi tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Prišel sem, svetloba na svet, da kdorkoli veruje vame, ne bi ostal v temi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'In če katerikoli človek sliši moje besede in ne veruje, ga ne sodim jaz, kajti nisem prišel, da svet sodim, temveč da svet rešim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kdor zavrača mene in ne sprejema mojih besed, ima nekoga, ki ga sodi. Beseda, ki sem jo govoril, ta ista ga bo sodila na poslednji dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Kajti nisem govoril sam od sebe, temveč Oče, ki me je poslal, mi je dal zapoved, kaj naj rečem in kaj naj govorim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'In jaz vem, da je njegova zapoved večno življenje. Karkoli torej govorim, govorim tako, celó kakor mi je rekel Oče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Torej pred praznikom pashe, ko je Jezus spoznal, da je prišla njegova ura, da naj bi odšel s tega sveta k Očetu in ker je ljubil svoje, ki so bili na svetu, jih je ljubil do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'In ko se je večerja končala, je torej hudič Judu Iškarijotu, Simonovemu sinu, v srce položil, da ga izda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Ker je Jezus vedel, da je Oče vse stvari dal v njegove roke in da je prišel od Boga in odšel k Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'se dvigne od večerje in odloži svoje obleke in vzame brisačo ter se opaše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Nató vlije vodo v umivalnik in začne učencem umivati stopala ter jih brisati z brisačo, s katero je bil opasan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Potem pride k Simonu Petru in Peter mu reče: »Gospod, ti mi umivaš moja stopala?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jezus je odgovoril in mu rekel: »Kar delam, ti sedaj ne veš, toda spoznal boš pozneje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Peter mu reče: »Nikoli ne boš umival mojih stopal.« Jezus mu je odgovoril: »Če te ne umijem, nimaš deleža z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Peter mu reče: »Gospod, ne samo mojih stopal, temveč tudi moje roke in mojo glavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jezus mu reče: »Kdor je umit, se mu razen svojih stopal ni treba umiti, ampak je čist vsak delček; in vi ste čisti, toda ne vsi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Kajti vedel je, kdo naj bi ga izdal, zato je rekel: »Niste vsi čisti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Torej potem, ko jim je umil njihova stopala in vzel svoje obleke ter se ponovno usedel, jim je rekel: »Ali veste, kaj sem vam storil?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vi me kličete Učitelj in Gospod, in pravilno govorite, kajti to sem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Če sem vam torej jaz, vaš Gospod in Učitelj, umil vaša stopala, morate tudi vi drug drugemu umivati stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Kajti dal sem vam zgled, da bi tudi vi delali tako, kakor sem vam storil jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Resnično, resnično, povem vam: ›Služabnik ni večji kakor njegov gospodar; niti kdor je poslan, ni večji kakor tisti, ki ga je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Če poznate te stvari, ste srečni, če jih izvršujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ne govorim o vas vseh. Vem, katere sem izbral, toda da bi se lahko izpolnilo pismo: ›Kdor jé kruh z menoj, je dvignil svojo peto zoper mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Sedaj vam pravim, preden pride, da ko se zgodi, boste lahko verovali, da jaz sem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Resnično, resnično, povem vam: ›Kdor sprejme, kogarkoli jaz pošljem, sprejme mene; in kdor sprejme mene, sprejme tistega, ki me je poslal.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Ko je Jezus tako rekel, je bil v duhu vznemirjen in pričeval ter rekel: »Resnično, resnično, povem vam, da me bo eden izmed vas izdal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Potem so učenci pogledali drug na drugega, dvomeč, o kom je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Torej na Jezusovo naročje je bil naslonjen eden izmed njegovih učencev, ki ga je Jezus ljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Peter mu je torej dal znamenje, da naj vpraša, kdo bi bil ta, o katerem je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'On mu potem, ležeč na Jezusovih prsih, reče: »Gospod, kdo je ta?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jezus je odgovoril: »To je tisti, ki mu bom dal grižljaj, ko ga bom pomočil.« In ko je grižljaj pomočil, ga je dal Judu Iškarijotu, Simonovemu sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'In po grižljaju je vanj vstopil Satan. Tedaj mu je Jezus rekel: »To, kar delaš, stôri hitro.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Torej noben človek pri mizi ni vedel, za kakšen namen mu je to rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Kajti nekateri izmed njih so mislili, ker je imel Juda mošnjo, da mu je Jezus rekel: »Kupi te stvari, ki jih potrebujemo za praznik,« ali da naj bi nekaj dal ubogim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Potem ko je prejel grižljaj, je takoj odšel ven; bila pa je noč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Torej ko je odšel ven, je Jezus rekel: »Sedaj je Sin človekov proslavljen in Bog je proslavljen v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Če je Bog proslavljen v njem, bo tudi Bog njega proslavil v sebi in nemudoma ga bo proslavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Majhni otroci, še malo časa sem z vami. Iskali me boste in kakor sem rekel Judom: ›Kamor grem jaz, vi ne morete priti,‹ tako sedaj pravim vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Dajem vam novo zapoved: ›Da ljubite drug drugega, kakor sem vas jaz ljubil, da tudi vi ljubite drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Po tem bodo vsi ljudje spoznali, da ste moji učenci, če imate drug do drugega ljubezen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Peter mu je rekel: »Gospod, kam greš?« Jezus mu je odgovoril: »Kamor jaz grem, mi sedaj ne moreš slediti, toda sledil mi boš pozneje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Peter mu je rekel: »Gospod, zakaj ti ne morem slediti sedaj? Svoje življenje hočem dati zaradi tebe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jezus mu je odgovoril: »Življenje hočeš dati zaradi mene? Resnično, resnično, povem ti: ›Petelin ne bo zapel, dokler me trikrat ne zanikaš.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '»Ne dopustite, da bi bilo vaše srce vznemirjeno. Verujte v Boga, tudi vame verujte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'V hiši mojega Očeta je mnogo graščin. Če ne bi bilo tako, bi vam povedal. Grem, da pripravim prostor za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Če pa grem in pripravim prostor za vas, bom ponovno prišel in vas sprejel k sebi, da kjer sem jaz, boste tam lahko tudi vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, '§ In kamor jaz grem, veste in pot poznate.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tomaž mu reče: »Gospod, ne vemo, kam greš in kako moremo poznati pot?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jezus mu reče: »Jaz sem pot, resnica in življenje. Nihče ne pride k Očetu, razen po meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Če bi spoznali mene, bi spoznali tudi mojega Očeta in odslej ga poznate in ste ga videli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filip mu reče: »Gospod, pokaži nam Očeta in to nam zadošča.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jezus mu reče: »Filip, toliko časa sem bil z vami, pa me vendar nisi spoznal? Kdor je videl mene, je videl Očeta, in kako potem praviš: ›Pokaži nam Očeta?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne verjameš, da sem jaz v Očetu in Oče v meni? Besede, ki vam jih govorim, ne govorim sam od sebe, temveč Oče, ki prebiva v meni, on opravlja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Verjemite mi, da sem v Očetu in Oče v meni; če pa ne, mi verjemite zaradi del samih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Resnično, resnično, povem vam: ›Kdor veruje vame, bo dela, ki jih jaz opravljam, tudi sam opravljal; in opravljal bo večja dela kakor ta, ker grem k svojemu Očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'In karkoli boste zahtevali v mojem imenu, bom to storil, da bo Oče lahko proslavljen v Sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Če boste karkoli zahtevali v mojem imenu, bom jaz to storil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Če ljubite mene, se držite mojih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'In prosil bom Očeta in dal vam bo drugega Tolažnika, da bo lahko večno ostal z vami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'celó Duha resnice, ki ga svet ne more prejeti zato, ker ga ne vidi niti ga ne pozna. Toda vi ga poznate, kajti on prebiva z vami in bo v vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ne bom vas zapustil brez tolažbe. Prišel bom k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Še malo časa in svet me ne vidi več, toda vi me vidite. Ker jaz živim, boste živeli tudi vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Na tisti dan boste vedeli, da jaz sem v svojem Očetu in vi v meni in jaz v vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'In kdor ima moje zapovedi in se jih drži, je tisti, ki me ljubi. In kdor ljubi mene, bo ljubljen od mojega Očeta in jaz ga bom ljubil in se mu bom razodel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Juda, ne Iškarijot, mu reče: »Gospod, kako to, da se hočeš razodeti nam, ne pa svetu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jezus je odgovoril in mu rekel: »Če me človek ljubi, se bo držal mojih besed in moj Oče ga bo ljubil in prišla bova k njemu in naredila prebivališče z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'In kdor me ne ljubi, se ne drži mojih izjav. In beseda, ki jo slišite, ni moja, temveč od Očeta, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Te stvari sem vam govoril, ko sem bil še prisoten z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Toda Tolažnik, ki je Sveti Duh, ki ga bo Oče poslal v mojem imenu, vas bo učil vseh stvari in vam bo v vaš spomin privedel vse besede, karkoli sem vam povedal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Mir zapustim z vami, svoj mir vam dam. Ne kakor daje svet, vam ga jaz dam. Ne dopustite, da bi bila vaša srca vznemirjena niti naj ne bodo prestrašena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Slišali ste, kako sem vam rekel: ›Jaz grem proč in ponovno pridem k vam.‹ Če ste ljubili mene, bi se razveselili, ker sem rekel: ›Jaz grem k Očetu,‹ kajti moj Oče je večji od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'In sedaj sem vam povedal, preden se zgodi, da boste lahko verovali, ko se zgodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Odslej ne bom več veliko govoril z vami, kajti princ tega sveta prihaja, toda v meni nima ničesar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Toda, da bo svet lahko spoznal, da ljubim Očeta in kakor mi je Oče dal zapoved, točno tako delam jaz. Vstanite, pojdimo od tod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '»Jaz sem resnična vinska trta in moj Oče je poljedelec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Vsako mladiko na meni, ki ne prinaša sadu, on odstranja in vsako vejo, ki prinaša sad, očiščuje, da bo lahko obrodila več sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Torej vi ste čisti po besedi, ki sem vam jo govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Ostanite v meni in jaz v vas. Kakor mladika sama od sebe ne more obroditi sadu, razen če ne ostane na vinski trti, nič bolj ne morete vi, razen če ne ostanete v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Jaz sem trta, vi ste mladike. Kdor ostaja v meni in jaz v njem, ta isti prinaša obilo sadu, kajti brez mene ne morete storiti ničesar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Če človek ne ostane v meni, je odvržen kakor mladika in se posuši; in ljudje jih zberejo ter jih vržejo v ogenj in so sežgane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Če ostanete v meni in moje besede ostanejo v vas, boste prosili, kar hočete in se vam bo to zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'V tem je moj Oče proslavljen, da obrodite obilo sadu; tako boste postali moji učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Kakor je Oče mene ljubil, tako sem jaz vas ljubil. Ostanite v moji ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Če se držite mojih zapovedi, boste ostali v moji ljubezni; kakor sem se jaz držal Očetovih zapovedi in ostajam v njegovi ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Te besede sem vam govoril, da moja radost lahko ostane v vas in da bo vaša radost lahko popolna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'To je moja zapoved: ›Da ljubite drug drugega, kakor sem vas jaz ljubil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nihče nima večje ljubezni, kakor je ta, da človek svoje življenje žrtvuje za svoje prijatelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vi ste moji prijatelji, če storite, karkoli vam zapovem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Odslej vas ne imenujem služabnike, kajti služabnik ne ve, kaj dela njegov gospodar; toda vas sem imenoval prijatelje, kajti dal sem vam spoznati vse stvari, ki sem jih slišal od svojega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Niste vi mene izbrali, ampak sem jaz izbral vas in vam odredil, da bi šli in obrodili sad in da bi vaš sad ostal, da karkoli boste zahtevali od mojega Očeta v mojem imenu, vam bo on to lahko dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Te besede vam zapovedujem, da ljubite drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Če vas svet sovraži, vedite, da je mene sovražil, preden je sovražil vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Če bi bili od sveta, bi svet svoje imel rad, toda ker niste od sveta, temveč sem vas izbral od sveta, vas torej svet sovraži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Spomnite se besede, ki sem vam jo rekel: ›Služabnik ni večji kot njegov gospodar.‹ Če so preganjali mene, bodo prav tako preganjali vas; če so se držali mojih izjav, se bodo držali tudi vaših.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Toda vse te stvari vam bodo storili zaradi mojega imena, ker ne poznajo tistega, ki me je poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Če ne bi prišel in jim ne bi govoril, ne bi imeli greha, toda sedaj za svoj greh nimajo nobene pretveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kdor sovraži mene, sovraži tudi mojega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Če med njimi ne bi storil del, ki jih noben drug človek ni storil, ne bi imeli greha, toda sedaj so tako videli kakor sovražili, tako mene kakor mojega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Toda to se dogaja, da se bo lahko izpolnila beseda, ki je zapisana v njihovi postavi: ›Sovražili so me brez razloga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Toda ko pride Tolažnik, ki ga bom poslal k vam od Očeta, celó Duh resnice, ki izvira od Očeta, bo on pričeval o meni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'in tudi vi boste pričevali, ker ste bili od začetka z menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '»Te besede sem vam govoril, da se ne bi pohujšali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Izločali vas bodo iz sinagog; da, prihaja čas, da bo, kdorkoli vas ubija, mislil, da opravlja službo Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'In te stvari vam bodo počeli, ker niso spoznali niti Očeta niti mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Toda te stvari sem vam povedal, da se boste lahko spomnili, ko bo prišel čas, da sem vam povedal o njih. Teh stvari pa vam na začetku nisem povedal, ker sem bil z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Toda sedaj grem svojo pot k njemu, ki me je poslal, pa me nihče izmed vas ne vpraša: ›Kam greš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Toda ker sem vam povedal te stvari, je vaše srce napolnila bridkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Vendar vam govorim resnico. Za vas je koristno, da odidem, kajti če ne odidem, potem Tolažnik ne bo prišel k vam, toda če odidem, vam ga bom poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'In ko on pride, bo grajal svet o grehu in o pravičnosti in o sodbi:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'o grehu, ker ne verujejo vame;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'o pravičnosti, ker grem k svojemu Očetu in me ne boste več videli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'o sodbi, ker je princ tega sveta obsojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Imam vam povedati še mnogo stvari, toda sedaj jih ne morete nositi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Vendar ko pride on, Duh resnice, vas bo usmerjal v vso resnico, kajti ne bo govoril iz sebe, temveč karkoli bo slišal, to bo govoril in pokazal vam bo stvari, ki pridejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'On me bo proslavil, kajti prejel bo od mojega in vam bo to pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Vse stvari, ki jih ima Oče, so moje. Torej sem rekel, da bo vzel od mojega in vam bo to pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '§ Malo časa in me ne boste videli in ponovno, malo časa in me boste videli, ker grem k Očetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Tedaj so nekateri izmed njegovih učencev med seboj govorili: »Kaj je to, da nam pravi: ›Malo časa in me ne boste videli, in ponovno, malo časa in me boste videli‹ in: ›Ker grem k Očetu?‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Rekli so torej: »Kaj je to, kar pravi: ›Malo časa?‹ Ne moremo povedati, kaj pravi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Torej Jezus je vedel, da so ga bili željni vprašati in jim je rekel: »Ali med seboj povprašujete, ker sem rekel: ›Malo časa in me ne boste videli, in ponovno, malo časa in me boste videli?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Resnično, resnično, povem vam: ›Da boste jokali in žalovali, toda svet se bo veselil; vi pa boste žalostni, toda vaša žalost bo obrnjena v radost.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Ženska, ko je v porodnih mukah, ima bridkost, ker je prišla njena ura; toda takoj, ko je razbremenjena otroka, se zaradi radosti, da je človek rojen na svet, ne spominja več tesnobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'In zato imate sedaj bridkost. Toda ponovno vas bom videl in vaše srce se bo veselilo in vaše radosti vam nihče ne bo odvzel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'In na tisti dan me ne boste ničesar vprašali. Resnično, resnično, povem vam: ›Karkoli boste zahtevali od Očeta v mojem imenu, vam bo to dal.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Doslej niste ničesar zahtevali v mojem imenu. Zahtevajte in boste prejeli, da bo vaša radost lahko popolna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Te stvari sem vam govoril v pregovorih, toda prihaja čas, ko vam ne bom več govoril v pregovorih, temveč vam bom o Očetu odkrito pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Na tisti dan boste prosili v mojem imenu, in ne pravim vam, da bom jaz prosil Očeta za vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'kajti sam Oče vas ima rad, ker ste me imeli radi in ste verovali, da sem prišel od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Prišel sem od Očeta in prišel sem na svet; zopet zapustim svet in grem k Očetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Njegovi učenci so mu rekli: »Glej, sedaj govoriš odkrito in ne govoriš pregovora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Sedaj smo prepričani, da veš vse stvari in ne potrebuješ, da bi te katerikoli človek vprašal. Po tem verujemo, da si prišel od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jezus jim je odgovoril: »Sedaj verujete?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Glejte, prihaja ura, da, pravkar je prišla, da boste razkropljeni, vsak k svojemu lastnemu, mene pa boste pustili samega; in vendar nisem sam, ker je Oče z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Te stvari sem vam govoril, da boste lahko imeli mir v meni. Na svetu boste imeli stisko, toda bodite dobre volje, jaz sem svet premagal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Te besede je govoril Jezus in svoje oči povzdignil k nebu ter rekel: »Oče, prišla je ura; proslavi svojega Sina, da bo lahko tudi tvoj Sin proslavil tebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'kakor si mu izročil oblast nad vsem mesom, da bi on lahko dal večno življenje tolikim, kolikor si mu jih dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'In to je večno življenje, da bi oni lahko spoznali tebe, edinega resničnega Boga in Jezusa Kristusa, ki si ga poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Jaz sem te proslavil na zemlji. Končal sem delo, ki si mi ga dal, da ga opravim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'In sedaj, oh Oče, me proslavi pri samem sebi s slavo, ki sem jo imel s teboj, preden je bil svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Jasno sem pokazal tvoje ime ljudem, ki mi jih daješ ven iz sveta. Bili so tvoji in ti jih daješ meni in ohranili so tvojo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Sedaj so spoznali, da so vse stvari, katerekoli si mi dal, od tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Kajti dal sem jim besede, ki jih ti daješ meni in sprejeli so jih in zagotovo so spoznali, da sem prišel od tebe in verovali so, da si me ti poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Jaz prosim zanje. Ne prosim za svet, temveč za tiste, ki si mi jih ti dal, kajti tvoji so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'In vse moje je tvoje in tvoje je moje in proslavljen sem v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'In sedaj nisem več na svetu, toda ti so na svetu, jaz pa prihajam k tebi. Sveti Oče, po svojem lastnem imenu ohrani te, ki si mi jih dal, da bodo lahko eno, kakor sva midva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, '§ Dokler sem bil z njimi na svetu, sem jih varoval v tvojem imenu. Te, ki mi jih daješ, sem obvaroval in nihče izmed njih ni izgubljen, razen sina pogube, da se lahko izpolni pismo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'In sedaj prihajam k tebi in te stvari govorim na svetu, da bodo mojo radost lahko imeli v sebi izpolnjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Dal sem jim tvojo besedo, svet pa jih je sovražil, ker niso od sveta, celó kakor jaz nisem od sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ne prosim, da bi jih vzel iz sveta, temveč, da bi jih varoval pred zlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Niso od sveta, celó kakor jaz nisem od sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Posvetí jih po svoji resnici. Tvoja beseda je resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Kakor si me ti poslal v svet, točno tako sem jih tudi jaz poslal v svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'In zaradi njih se posvečujem, da bodo tudi oni lahko posvečeni preko resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Niti ne prosim samo za té, temveč tudi za tiste, ki bodo po njihovi besedi verovali vame,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'da bi bili lahko vsi eno, kakor si ti, Oče, v meni in jaz v tebi, da bi bili lahko tudi oni eno v nas [treh], da bi svet lahko veroval, da si me ti poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'In slavo, ki mi jo daješ, sem dal njim, da bodo lahko eno, tako kakor smo mi [trije] eno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'jaz v njih in ti v meni, da bodo lahko izpopolnjeni v enem in da bo svet lahko spoznal, da si me ti poslal in da si jih ljubil, kakor si ljubil mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Oče, hočem, da bodo tudi tisti, ki si mi jih dal, z menoj, kjer sem jaz, da bodo lahko gledali mojo slavo, ki si mi jo dal, kajti ljubil si me pred ustanovitvijo sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Oh pravični Oče, svet te ni spoznal, toda jaz sem te spoznal in ti so spoznali, da si me ti poslal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'In razglasil sem jim tvoje ime in ga bom razglašal, da bo ljubezen, s katero si me ljubil, lahko v njih in jaz v njih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Ko je Jezus povedal te besede, je s svojimi učenci odšel čez potok Cedron, kjer je bil vrt, v katerega je vstopil on in njegovi učenci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'In tudi Juda, ki ga je izdal, je poznal kraj, kajti Jezus se je s svojimi učenci pogosto napotil tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Juda je potem, ko je od visokih duhovnikov in farizejev prejel četo mož in častnikov, prihajal tja s svetilkami, baklami in orožjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jezus je torej, vedoč vse stvari, ki naj bi prišle nadenj, šel naprej in jim rekel: »Koga iščete?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odgovorili so mu: »Jezusa Nazarečana.« Jezus jim reče: »Jaz sem.« In tudi Juda, ki ga je izdal, je stal z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Takoj potem, ko jim je rekel: »Jaz sem,« so stopili nazaj in padli na tla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Potem jih je ponovno vprašal: »Koga iščete?« In rekli so: »Jezusa Nazarečana.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jezus je odgovoril: »Povedal sem vam, da jaz sem. Če torej iščete mene, pustite te oditi svojo pot,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'da bi se lahko izpolnila beseda, ki jo je govoril: »Izmed teh, ki mi jih daješ, nisem izgubil nobenega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Takrat je Simon Peter, ki je imel meč, tega izvlekel in udaril služabnika vélikega duhovnika in odsekal njegovo desno uho. Služabnikovo ime je bilo Malh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Tedaj je Jezus rekel Petru: »Spravi svoj meč v nožnico. Ali naj ne izpijem čaše, ki mi jo je dal moj Oče?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Tedaj so četa in stotnik in judovski častniki vzeli Jezusa ter ga zvezali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'in ga odvedli najprej k Hanu, kajti bil je tast Kajfu, ki je bil to isto leto véliki duhovnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Torej Kajfa je bil tisti, ki je Judom dal nasvet, da je bilo koristno, da bi en človek umrl za ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Peter pa je sledil Jezusu in tako je storil [tudi] drug učenec. Ta učenec je bil poznan vélikemu duhovniku in je z Jezusom vstopil v palačo vélikega duhovnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Toda Peter je stal zunaj pri vratih. Potem je odšel ven ta drugi učenec, ki je bil poznan vélikemu duhovniku in spregovoril njej, ki je stražila vrata in Petra privedel noter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Tedaj reče Petru gospodična, ki je stražila vrata: »Ali nisi tudi ti eden izmed učencev tega človeka?« Reče ji: »Nisem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'In tam so stali služabniki in častniki, ki so pripravili žerjavico, kajti bilo je hladno in so se greli, in Peter je stal z njimi ter se grel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Véliki duhovnik je tedaj vprašal Jezusa o njegovih učencih in o njegovem nauku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jezus mu je odgovoril: »Javno sem govoril svetu, vselej sem učil v sinagogi in v templju, kamor Judje vedno zahajajo in ničesar nisem povedal na skrivnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Zakaj sprašuješ mene? Vprašaj tiste, ki so me slišali, kaj sem jim povedal. Glej, vedo, kaj sem rekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'In ko je tako govoril, je eden izmed častnikov, ki je stal poleg, z dlanjo svoje roke udaril Jezusa, rekoč: »Tako odgovarjaš vélikemu duhovniku?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jezus mu je odgovoril: »Če sem govoril zlo, pričuj o zlu; toda če dobro, zakaj me tolčeš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Torej ga je Hana zvezanega poslal k vélikemu duhovniku Kajfu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Peter pa je stal in se grel. Torej so mu rekli: »Mar nisi tudi ti eden izmed njegovih učencev?« To je zanikal in rekel: »Nisem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Eden izmed služabnikov vélikega duhovnika, sorodnik tistega, čigar uho je Peter odsekal, reče: »Ali te nisem videl z njim na vrtu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Tedaj je Peter ponovno zanikal in petelin je takoj zapel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Potem so od Kajfa Jezusa odvedli v sodno dvorano; in bilo je zgodaj, oni sami pa niso odšli v sodno dvorano, da ne bi bili omadeževani, temveč da bi smeli jesti pashalno jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilat je potem odšel ven k njim in rekel: »Kakšno obtožbo ste prinesli zoper tega človeka?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Odgovorili so mu in mu rekli: »Če bi ne bil hudodelec, bi ti ga ne izročili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Tedaj jim je Pilat rekel: »Vzemite ga in ga sodite glede na svojo postavo.« Judje so mu torej rekli: »Za nas ni zakonito, da usmrtimo kateregakoli človeka,«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'da bi se lahko izpolnila Jezusova beseda, ki jo je govoril, ko je naznanil, kakšne smrti naj bi umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Tedaj je Pilat ponovno vstopil v sodno dvorano in poklical Jezusa ter mu rekel: »Ali si ti judovski Kralj?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jezus mu je odgovoril: »Praviš to besedo sam od sebe ali so ti to drugi povedali o meni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilat je odgovoril: »Sem mar Jud? Tvoj narod in visoki duhovniki so te izročili meni. Kaj si storil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jezus je odgovoril: »Moje kraljestvo ni od tega sveta. Če bi bilo moje kraljestvo od tega sveta, potem bi se moji služabniki bojevali, da ne bi bil izročen Judom, toda sedaj moje kraljestvo ni od tod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilat mu je torej rekel: »Ali si ti potem kralj?« Jezus je odgovoril: »Ti praviš, da sem kralj. Za ta namen sem bil rojen in zaradi tega razloga sem prišel na svet, da naj bi pričeval k resnici. Vsak, kdor je iz resnice, posluša moj glas.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilat mu reče: »Kaj je resnica?« In ko je to rekel, je ponovno odšel k Judom in jim reče: »Na njem sploh ne najdem nobene krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Ampak vi imate navado, da naj bi vam za pasho enega izpustil. Hočete torej, da vam izpustim judovskega Kralja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Potem so vsi ponovno zavpili, rekoč: »Ne tega človeka, temveč Baraba.« Torej Baraba je bil razbojnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tedaj je torej Pilat vzel Jezusa in ga prebičal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'In vojaki so iz trnja spletli krono in jo položili na njegovo glavo in nanj nadeli škrlatno svečano oblačilo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'ter rekli: »Pozdravljen, judovski Kralj!« in ga udarjali s svojimi rokami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilat je torej ponovno odšel naprej, rekoč jim: »Glejte, privedem ga k vam, da boste lahko spoznali, da ne najdem krivde na njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Potem je prišel Jezus naprej, noseč trnovo krono in škrlatno svečano oblačilo. In Pilat jim reče: »Glejte, človek!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Ko so ga torej visoki duhovniki in častniki zagledali, so zavpili, rekoč: »Križaj ga, križaj ga.« Pilat jim reče: »Vzemite ga in ga križajte, kajti jaz ne najdem krivde na njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Judje so mu odgovorili: »Mi imamo postavo in po naši postavi bi moral umreti, ker se je delal Božjega Sina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Ko je torej Pilat slišal to besedo, se je še bolj zbal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'in ponovno odšel v sodno dvorano in reče Jezusu: »Od kod si?« Toda Jezus mu ni dal odgovora.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Tedaj mu Pilat reče: »Meni ne odgovoriš? Ne veš, da imam oblast, da te križam in imam oblast, da te izpustim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jezus je odgovoril: »Zoper mene sploh ne bi mogel imeti nobene oblasti, razen če ti ne bi bila dana od zgoraj. Zato ima večji greh tisti, ki me je izročil tebi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'In odslej si je Pilat prizadeval, da ga izpusti. Toda Judje so zavpili, rekoč: »Če tega človeka izpustiš, nisi cesarjev prijatelj; kdorkoli sebe dela kralja, govori zoper cesarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Ko je torej Pilat slišal to besedo, je privedel Jezusa naprej in sedel na sodni stol na kraju, ki se imenuje Tlak, toda v hebrejščini Gabatá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Bila pa je priprava na pasho in okoli šeste ure; in Judom reče: »Glejte, vaš Kralj!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Toda oni so zakričali: »Proč z njim, proč z njim, križaj ga.« Pilat jim reče: »Ali naj križam vašega Kralja?« Visoki duhovniki so odgovorili: »Nimamo kralja razen cesarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tedaj jim ga je torej izročil, da bi bil križan. In vzeli so Jezusa ter ga odvedli proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'In ko je nesel svoj križ, je odšel naprej na kraj, imenovan kraj lobanje, ki se v hebrejščini imenuje Golgota,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'kjer so ga križali in z njim dva druga, na vsaki strani enega in Jezusa v sredi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'In Pilat je napisal napis ter ga postavil na križ. In pisanje je bilo: JEZUS NAZAREČAN, JUDOVSKI KRALJ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Ta napis so potem brali mnogi izmed Judov, kajti kraj, kjer je bil Jezus križan, je bil blizu mesta, in to je bilo napisano v hebrejščini in grščini ter latinščini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Tedaj so visoki judovski duhovniki Pilatu rekli: »Ne napiši: ›Judovski Kralj,‹ temveč, da je on rekel: ›Jaz sem Kralj Judov.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilat je odgovoril: »Kar sem napisal, sem napisal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Potem so vojaki, ko so Jezusa križali, vzeli njegove obleke in naredili štiri dele, za vsakega vojaka del in prav tako njegov plašč. Torej plašč [pa] je bil brez šiva, ves spleten od vrha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Med seboj so torej govorili: »Ne razparajmo ga, temveč mečimo žrebe zanj, čigav bo,« da bi se lahko izpolnilo pismo, ki pravi: ›Moja oblačila so si razdelili med seboj in za mojo suknjo so metali žrebe.‹ Te stvari so torej storili vojaki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Torej tam, ob Jezusovem križu, so stale njegova mati in sestra njegove matere, Klopájeva žena Marija in Marija Magdalena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Ko je torej Jezus videl svojo mater in učenca, ki je stal poleg, ki ga je ljubil, reče svoji materi: »Ženska, glej tvoj sin!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Potem reče učencu: »Glej, tvoja mati!« In od te ure jo je ta učenec vzel v svoj lastni dom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Po tem, ker je Jezus vedel, da so bile vse stvari sedaj dovršene, da bi se lahko izpolnilo pismo, reče: »Žejen sem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Torej, tam je bila postavljena posoda, polna kisa; in gobo so napolnili s kisom in jo nataknili na izop ter jo pristavili k njegovim ustom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Ko je torej Jezus prejel kis, je rekel: »Dovršeno je« in nagnil svojo glavo ter izročil duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Judje so torej zato, ker je bila priprava, da na šabatni dan telesa ne bi ostala na križu (kajti ta šabatni dan je bil na prazničen dan), prosili Pilata, da bi bile lahko njihove noge zlomljene in da bi bili lahko odstranjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Potem so prišli vojaki in zlomili noge prvega in drugega, ki sta bila križana z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Toda ko so prišli k Jezusu in videli, da je bil že mrtev, njegovih nog niso zlomili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'toda eden izmed vojakov je s sulico prebodel njegovo stran in nemudoma sta od tam pritekli kri in voda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'In tisti, ki je to videl, je izjavil in njegova izjava je resnična; in on ve, da govori resnico, da bi vi lahko verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Kajti te stvari so bile storjene, da bi bilo izpolnjeno pismo: ›Nobena njegova kost ne bo zlomljena.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'In ponovno drugo pismo pravi: ›Gledali bodo nanj, ki so ga prebodli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'In po tem je Jožef iz Arimateje, ki je bil Jezusov učenec, toda zaradi strahu pred Judi skrivaj, prosil Pilata, da bi lahko odnesel Jezusovo telo; in Pilat mu je dal dovoljenje. Prišel je torej in vzel Jezusovo telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'In prav tako je prišel Nikodém, ki je najprej ponoči prišel k Jezusu in prinesel mešanico mire in aloje, težko okoli sto funtov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Potem sta snela Jezusovo telo in ga z dišavami ovila v lanene trakove, kakršen je judovski običaj pokopa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Torej na kraju, kjer je bil križan, je bil vrt in na vrtu nov mavzolej, v katerega človek še nikoli ni bil položen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Zaradi judovskega dneva priprave sta torej Jezusa položila tja, kajti mavzolej je bil blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Prvi dan tedna pride Marija Magdalena zgodaj, ko je bilo še temno, k mavzoleju in vidi kamen odvzet stran od mavzoleja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Tedaj steče in pride k Simonu Petru in k drugemu učencu, ki ga je imel Jezus rad in jima reče: »Gospoda so odnesli iz mavzoleja in ne vemo, kam so ga položili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Peter in ta drugi učenec sta torej odšla naprej in prišla k mavzoleju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Tako sta oba skupaj tekla; drugi učenec pa je Petra prehitel in prvi prišel k mavzoleju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'In ko se je sklonil navzdol in pogledal noter, je videl ležati lanene trakove, vendar ni vstopil vanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Tedaj pride Simon Peter, ki mu je sledil in gre v mavzolej ter vidi ležati lanene trakove;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'prtič pa, ki je bil okoli njegove glave, ni ležal z lanenimi trakovi, temveč je bil sam zase skupaj zvit na kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Tedaj je vstopil tudi ta drugi učenec, ki je prvi prišel k mavzoleju in videl je in veroval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Kajti doslej še nista poznala pisma, da mora vstati od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Potem sta učenca ponovno odšla na njun lastni dom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Toda Marija je jokajoč stala zunaj mavzoleja in med jokom se je sklonila navzdol ter pogledala v mavzolej');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'in vidi sedeti dva angela v belem, enega pri glavi, drugega pa pri stopalih, kjer je ležalo Jezusovo telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'In onadva sta ji rekla: »Ženska, zakaj jokaš?« Reče jima: »Ker so odnesli mojega Gospoda, pa ne vem, kam so ga položili.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'In ko je to rekla, se je obrnila nazaj ter zagledala Jezusa, kako stoji, pa ni vedela, da je bil to Jezus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jezus ji reče: »Ženska, zakaj jokaš? Koga iščeš?« Ker je mislila, da je vrtnar, mu reče: »Gospod, če si ga odnesel od tod, mi povej, kam si ga položil in odnesla ga bom proč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jezus ji reče: »Marija.« Obrnila se je in mu reče: »Rabuni,« kar pomeni: »Učitelj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jezus ji reče: »Ne dotakni se me, kajti nisem se še dvignil k svojemu Očetu, toda pojdi k mojim bratom in jim povej: ›Dvignem se k svojemu Očetu in vašemu Očetu in k svojemu Bogu in vašemu Bogu.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marija Magdalena je prišla ter učencem povedala, da je videla Gospoda in da ji je govoril te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Potem je istega dne zvečer, ko je bil prvi dan tedna, ko so bila vrata, kjer so bili učenci zbrani, zaradi strahu pred Judi zaprta, prišel Jezus ter stopil na sredo in jim reče: »Mir vam bodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'In ko je tako rekel, jim je pokazal svoji roki in svojo stran. Potem ko so videli Gospoda, so bili učenci veseli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Tedaj jim je Jezus ponovno rekel: »Mir vam bodi. Kakor me je moj Oče poslal, točno tako jaz vas pošiljam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'In ko je to rekel, je dihnil nanje in jim reče: »Prejmite Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Katerimkoli grehe odpustite, so jim odpuščeni; in katerimkoli grehe zadržite, so jim zadržani.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Toda ko je prišel Jezus, Tomaža, enega izmed dvanajsterih, ki se je imenoval Dvojček, ni bilo z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Drugi učenci so mu torej rekli: »Videli smo Gospoda.« On pa jim je rekel: »Razen če ne bom videl na njegovih rokah odtisa žebljev in svojega prsta položil v odtis žebljev in svoje roke porinil v njegovo stran, ne bom veroval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'In po osmih dneh so bili njegovi učenci ponovno znotraj in Tomaž z njimi. Potem je pri zaprtih vratih prišel Jezus in stal na sredi ter rekel: »Mir vam bodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potem reče Tomažu: »Sezi s svojim prstom sèm in poglej moji roki in sezi s svojo roko tja ter jo porini v mojo stran in ne bodi neveren, temveč veren.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'In Tomaž je odgovoril ter mu rekel: »Moj Gospod in moj Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jezus mu reče: »Tomaž, ker si me videl, si veroval; blagoslovljeni so tisti, ki niso videli, pa so vendarle verovali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'In resnično je v prisotnosti svojih učencev Jezus storil mnoga druga znamenja, ki niso zapisana v tej knjigi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'toda ta so zapisana, da bi vi lahko verovali, da Jezus je Kristus, Božji Sin in da bi verujoč, lahko imeli življenje v njegovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Po teh stvareh je Jezus sebe učencem ponovno prikazal pri Tiberijskem morju in sebe je prikazal na ta način.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Tam so bili skupaj Simon Peter in Tomaž, imenovan Dvojček in Natánael iz galilejske Kane in Zebedejeva sinova ter dva druga izmed njegovih učencev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Peter jim reče: »Grem na ribolov.« Dejali so mu: »Tudi mi gremo s teboj.« Odšli so in takoj vstopili na ladjo, pa tisto noč niso ničesar ujeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Toda sedaj, ko je torej prišlo jutro, je na obali stal Jezus, toda učenci niso vedeli, da je bil Jezus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Potem jim Jezus reče: »Otroci, imate kaj hrane?« Odgovorili so mu: »Ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'In rekel jim je: »Vrzite mrežo na desno stran ladje in boste našli.« Zato so jo vrgli, pa je torej niso mogli izvleči zaradi množice rib.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Ta učenec, ki ga je Jezus ljubil, reče torej Petru: »Gospod je.« Takoj ko je Simon Peter slišal, da je bil to Gospod, si je k sebi opasal svoj ribiški plašč (kajti bil je nag) in se vrgel v morje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Ostali učenci pa so prišli na majhni ladji; (kajti niso bili daleč od kopnega, temveč kot bi bilo dvesto komolcev) ter vlekli mrežo z ribami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Takoj ko so prišli h kopnini, so tam zagledali žerjavico in na njej položeno ribo ter kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jezus jim reče: »Prinesite od rib, ki ste jih pravkar ujeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Peter se je povzpel in potegnil mrežo, polno velikih rib, sto triinpetdeset, na kopno; in četudi jih je bilo vseh tako mnogo, se mreža vendarle ni strgala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jezus jim reče: »Pridite in obedujte.« Nihče izmed učencev pa si ga ni drznil vprašati: »Kdo si?« ker so vedeli, da je bil Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jezus potem pride in vzame kruh in jim ga daje ter prav tako ribo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'To je sedaj tretjič, da se je Jezus prikazal svojim učencem, potem ko je bil obujen od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Torej ko so obedovali, reče Jezus Simonu Petru: »Simon, Jonov sin, me ljubiš bolj kakor tile?« On mu reče: »Da Gospod, ti veš, da te imam rad.« Rekel mu je: »Hrani moja jagnjeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Ponovno mu drugič reče: »Simon, Jonov sin, me ljubiš?« Rekel mu je: »Da Gospod, ti veš, da te imam rad.« Rekel mu je: »Pasi moje ovce.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Reče mu tretjič: »Simon, Jonov sin, me imaš rad?« Peter je bil užaloščen, ker mu je tretjič rekel: »Ali me imaš rad?« In rekel mu je: »Gospod, ti veš vse stvari; ti veš, da te imam rad.« Jezus mu reče: »Hrani moje ovce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Resnično, resnično, povem ti: ›Ko si bil mlad, si se opasoval in hodil, kamor si hotel, toda ko boš star, boš iztegnil svoji roki in drug te bo opasal in te vodil, kamor nočeš.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'To je govoril in s tem naznanil s kakšno smrtjo naj bi proslavil Boga. In ko je to povedal, mu reče: »Sledi mi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Potem je Peter, ko se je obrnil okoli, videl slediti učenca, ki ga je Jezus ljubil, ki je prav tako pri večerji slonel na njegovih prsih in rekel: »Gospod, kdo je tisti, ki te izdaja?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Medtem ko ga je Peter gledal, reče Jezusu: »Gospod in kaj bo ta človek storil?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jezus mu reče: »Če hočem, da ostane, dokler ne pridem, kaj ti je to mar? Ti hodi za menoj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Potem je šla ta beseda naokoli med brati, da naj ta učenec ne bi umrl, čeprav mu Jezus ni rekel: »Ne bo umrl,« temveč: »Če jaz hočem, da ostane, dokler ne pridem, kaj ti je to mar?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'To je učenec, ki pričuje o teh stvareh in je napisal te stvari in mi vemo, da je njegovo pričevanje resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'In obstaja tudi mnogo drugih stvari, ki jih je Jezus storil, katere, če bi jih vse zapisali, mislim, da celó sam svet ne bi mogel vsebovati knjig, ki bi bile napisane. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, '§ Prejšnje poročilo sem naredil, oh Teófil, o vsem, kar je Jezus začel, tako delati kakor učiti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'do dne, v katerem je bil vzet gor, potem ko je po Svetem Duhu dal zapovedi apostolom, ki jih je izbral;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, '§ katerim se je, po svojem trpljenju, tudi pokazal živega, z mnogimi nezmotljivimi dokazi, ki so jih gledali štirideset dni in govorili o stvareh, ki se nanašajo na Božje kraljestvo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'in ko je bil zbran skupaj z njimi, jim je zapovedal, da naj ne odidejo iz Jeruzalema, temveč čakajo na Očetovo obljubo: »Katero,« on pravi, »ste slišali od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Kajti Janez je resnično krščeval z vodo, toda vi boste krščeni s Svetim Duhom, čez ne mnogo dni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ko so torej prišli skupaj, so ga vprašali, rekoč: »Gospod, ali boš v tem času Izraelu ponovno obnovil kraljestvo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'In rekel jim je: »Ni za vas, da bi vedeli čase ali obdobja, ki jih je Oče postavil v svoji lastni oblasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Toda prejeli boste moč, po tem, ko Sveti Duh pride nad vas, in vi mi boste priče, tako v Jeruzalemu kakor po vsej Judeji in v Samariji ter do skrajnega dela zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'In ko je govoril te besede, medtem ko so ga gledali, je bil vzet gor, in oblak ga je sprejel iz njihovega pogleda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'In medtem ko so neomajno gledali proti nebu, ko je šel gor, glej, sta poleg njih stala dva moža v belih oblekah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'ki sta prav tako rekla: »Vi, možje iz Galileje, zakaj stojite strmeč v nebo? Ta isti Jezus, ki je bil od vas vzet gor v nebesa, bo prišel tako, na podoben način, kakor ste ga videli iti v nebo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tedaj so se z gore, imenovane Oljska, ki je šabatni dan poti od Jeruzalema, vrnili v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'In ko so prišli vanj, so odšli gor v gornjo sobo, kjer so prebivali Peter in Jakob in Janez in Andrej, Filip in Tomaž, Bartolomej in Matej, Alfejev sin Jakob in Simon Gorečnik ter Jakobov brat Juda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Vsi ti so soglasno vztrajali v molitvi in ponižni prošnji z ženskami in Marijo, Jezusovo materjo ter z njegovimi brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'In v tistih dneh je sredi učencev vstal Peter ter rekel (skupno število imen je bilo okoli sto dvajset):');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '»Možje in bratje, to pismo se je brezpogojno moralo izpolniti, ki ga je Sveti Duh po Davidovih ustih prej govoril glede Juda, ki je bil vodnik tem, ki so prijeli Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Kajti bil je štet z nami in je dosegel delež te službe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Torej ta človek je s krivično nagrado kupil polje in ko je padel z glavo naprej, se je po sredi razpočil in vsa njegova notranjost se je izlila ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'In to je bilo znano vsem jeruzalemskim prebivalcem, tako zelo, da se to polje v njihovem pravem jeziku imenuje Hakéldama, to se pravi: ›Njiva krvi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Kajti pisano je v knjigi Psalmov: ›Naj bo njegovo prebivališče zapuščeno in naj noben človek ne prebiva v njem in njegovo duhovno nadzorništvo naj prevzame nekdo drug.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Zatorej izmed teh ljudi, ki so se z nami družili ves čas, ko je Gospod Jezus hodil med nami noter in ven,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'začenši od Janezovega krsta do tega istega dne, ko je bil od nas vzet gor, mora biti nekdo odrejen, da bo z nami priča njegovega vstajenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'In določili so dva, Jožefa, imenovanega Bársaba, ki je bil imenovan z vzdevkom Just ter Matija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'In molili so ter rekli: »Ti, Gospod, ki poznaš srca vseh ljudi, pokaži, katerega izmed teh dveh si izbral,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, '§ da lahko prevzame del te službe in apostolstva, od katerega je Juda s prestopkom odpadel, da bi lahko šel na svoj lasten kraj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'In naznanili so svoje žrebe in žreb je padel na Matija in ta je bil prištet enajsterim apostolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'In ko je popolnoma prišel Binkoštni dan, so bili vsi soglasni na enem kraju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'In nenadoma je prišel z neba šum kakor besneč mogočen veter ter napolnil vso hišo, kjer so sedeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'In prikazali so se jim razcepljeni jeziki, podobni ognjenim ter sedli na vsakogar izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'In vsi so bili izpolnjeni s Svetim Duhom in začeli so govoriti z drugimi jeziki, kakor jim je Duh dajal izgovarjati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'V Jeruzalemu pa so prebivali Judje, predani možje, iz vsakega naroda pod nebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Torej, ko se je to razglasilo naokoli, so prišle skupaj množice in bili so zbegani, zato ker jih je vsakdo slišal govoriti v svojem lastnem jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'In vsi so bili osupli ter se čudili in drug drugemu govorili: »Glejte, ali niso vsi ti, ki govorijo, Galilejci?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'In kako mi vsakega človeka slišimo v svojem lastnem jeziku, kjer smo bili rojeni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parti in Medijci in Elámci in prebivalci v Mezopotamiji in v Judeji in Kapadokiji, v Pontu in Aziji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frigiji in Pamfiliji, v Egiptu in v libijskih krajih okoli Cirene in tujci iz Rima, Judje in spreobrnjenci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Krečani in Arabci, mi jih v svojih jezikih slišimo govoriti čudovita Božja dela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'In vsi so bili osupli in bili so v dvomu, govoreč drug drugemu: »Kaj to pomeni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Drugi so zasmehljivo rekli: »Ti ljudje so polni novega vina.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Vendar je Peter, ko je javno nastopil z enajsterimi, povzdignil svoj glas in jim rekel: »Vi ljudje iz Judeje in vsi vi, ki prebivate v Jeruzalemu, to vam bodi znano in prisluhnite mojim besedam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'kajti ti niso pijani, kakor vi mislite, glede na to, da je šele tretja dnevna ura.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Ampak to je to, kar je bilo rečeno po preroku Joélu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '›In zgodilo se bo v poslednjih dneh, govori Bog: ›Izlil bom od svojega Duha na vse meso, in vaši sinovi in vaše hčere bodo prerokovali in vaši mladeniči bodo videli videnja in vaši starci bodo sanjali sanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'in na svoje služabnike in na svoje pomočnice bom v tistih dneh izlil od svojega Duha in bodo prerokovali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'in pokazal bom čudeže zgoraj na nebu in znamenja spodaj na zemlji: kri in ogenj in dimne meglice;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'sonce se bo spremenilo v temo in luna v kri, preden pride ta veliki in opazni dan Gospodovega prihoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'In zgodilo se bo, da kdorkoli se bo skliceval na Gospodovo ime, bo rešen.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Vi, možje Izraelci, prisluhnite tem besedam. Jezus Nazarečan, mož med vami, po čudežnih močeh, čudežih in znamenjih potrjen od Boga, ki jih je Bog po njem storil v sredi med vami, kakor tudi vi sami veste;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'njega, ki je bil izročen po določeni nameri in vnaprejšnjem védenju Boga, ste vi prijeli in po zlobnih rokah križali ter umorili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, '§ ki ga je Bog dvignil in odvezal bolečin smrti; ker ni bilo mogoče, da bi ga ta zadržala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Kajti David glede njega govori: ›Vedno sem slutil Gospoda pred svojim obrazom, kajti on je na moji desnici, da ne bi bil omajan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Zato se je moje srce veselilo in moj jezik je bil vesel; poleg tega bo tudi moje meso počivalo v upanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, '§ ker moje duše nočeš pustiti v peklu niti nočeš trpeti, da bi tvoj Sveti videl trohnenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Spoznati si mi dal poti življenja; s svojim obličjem me boš napravil polnega radosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Možje in bratje, naj vam odkrito spregovorim o očaku Davidu, da je tako mrtev kakor pokopan in njegov mavzolej je med nami do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, '§ Ker je bil torej prerok in je vedel, da mu je Bog prisegel s prisego, da bo od sadu njegovih ledij, glede na meso, vzdignil Kristusa, da sedi na njegovem prestolu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, '§ in ker je to videl vnaprej, je govoril o Kristusovem vstajenju, da njegova duša ni ostala v peklu niti njegovo meso ni videlo trohnenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tega Jezusa je Bog vzdignil, o čemer smo mi vsi priče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Torej je bil z Božjo desnico povišan in je od Očeta prejel obljubo Svetega Duha, ki ga je razlil, kakor sedaj vidite in slišite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Kajti David ni dvignjen v nebesa, toda on sam pravi: › Gospod je rekel mojemu Gospodu: ›Sedi na mojo desnico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'dokler ne naredim tvojih sovražnikov [za] tvojo pručko.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Zato naj vsa Izraelova hiša brez dvoma ve, da je Bog tega istega Jezusa, ki ste ga vi križali, naredil tako Gospoda kakor Kristusa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Torej ko so to slišali, so bili v svojem srcu spodbujeni ter rekli Petru in ostalim apostolom: »Možje in bratje, kaj naj storimo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Potem jim je Peter rekel: »Pokesajte se in vsak izmed vas naj bo krščen v imenu Jezusa Kristusa v odpuščanje grehov in prejeli boste dar Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Kajti obljuba je dana vam in vašim otrokom in vsem, ki so daleč stran, celó tolikim, kolikor jih bo poklical Gospod, naš Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'In z mnogimi drugimi besedami je pričeval ter spodbujal, rekoč: »Rešite se iz tega sprijenega rodu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Potem so bili tisti, ki so z veseljem sprejeli njegovo besedo, krščeni in istega dne se jim je dodalo okoli tri tisoč duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'In neomajno so nadaljevali v apostolskem nauku in družbi in v lomljenju kruha ter v molitvah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'In strah je prišel nad vsako dušo; in po apostolih je bilo storjenih mnogo čudežev in znamenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'In vsi, ki so verovali, so bili skupaj in vse stvari so imeli skupne;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'in prodajali so svoje posesti ter dobrine in jih delili vsem ljudem, kolikor je vsak potreboval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'In vsak dan so soglasno nadaljevali v templju in od hiše do hiše lomili kruh [in] z veseljem in iskrenim srcem jedli svojo hrano,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'ter slavili Boga in imeli naklonjenost pri vseh ljudeh. Gospod pa je k cerkvi dnevno dodajal takšne, ki naj bi bili rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Torej Peter in Janez sta ob uri molitve skupaj odšla gor v tempelj; bila je deveta ura.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Nekega moža, hromega od maternice njegove matere, pa so nosili in ga dnevno polagali pri tempeljskih velikih vratih, ki se imenujejo Lepa, da prosi miloščine od teh, ki so vstopali v tempelj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'ki je, ko je videl Petra in Janeza namenjena v tempelj, prosil miloščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'In ko se je Peter z Janezom zazrl v njegove oči, je rekel: »Poglej naju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'In ta jima je posvetil pozornost, ker je pričakoval, da bo od njiju kaj prejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Potem je Peter rekel: »Srebra in zlata nimam, toda to, kar imam, ti dam: ›V imenu Jezusa Kristusa iz Nazareta vstani in hôdi.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'In prijel ga je za desnico ter ga dvignil in takoj so njegova stopala ter kosti gležnja prejeli moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'In poskočil je pokonci ter hodil in z njima vstopil v tempelj, kjer je hodil in poskakoval ter slavil Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'In vsi ljudje so ga videli hoditi in slaviti Boga');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'in vedeli so, da je bil to ta, ki je zaradi miloščine sedel pri tempeljskih Lepih velikih vratih. In izpolnjeni so bili s čudenjem ter osuplostjo nad tem, kar se mu je zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'In medtem ko se je hromi mož, ki je bil ozdravljen, držal Petra in Janeza, so vsi ljudje, ker so se silno čudili, skupaj stekli k njima v preddverje, ki se je imenovalo Salomonovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'In ko je Peter to videl, je ljudem odgovoril: »Vi, možje iz Izraela, zakaj se čudite nad tem? Ali zakaj tako iskreno gledate na naju, kakor da bi z najino lastno močjo ali svetostjo tega moža pripravila hoditi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, '§ Bog Abrahama in Izaka in Jakoba, Bog naših očetov, je proslavil svojega Sina Jezusa, ki ste ga vi izročili in ga zatajili v Pilatovi prisotnosti, ko je bil ta odločen, da ga izpusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Toda zatajili ste Svetega in Pravičnega ter prosili, da se vam zagotovi morilec;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, '§ ubili pa ste Princa življenja, ki ga je Bog obudil od mrtvih; o čemer smo mi priče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'In njegovo ime je po veri v njegovo ime tega moža naredilo močnega, ki ga vidite in poznate. Da, vera, ki je po njem, mu je dala to popolno zdravje v prisotnosti vas vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'In sedaj, bratje, vem, da ste to storili po nevednosti, kakor so storili tudi vaši vladarji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, '§ Toda te besede, ki jih je Bog prej oznanil po ustih vseh svojih prerokov, da naj bi Kristus trpel, je on tako izpolnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, '§ Pokesajte se torej in bodite spreobrnjeni, da bodo vaši grehi lahko izbrisani, ko bodo od Gospodove prisotnosti prišli časi osvežitve;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, '§ in poslal bo Jezusa Kristusa, ki vam je bil prej oznanjen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'ki ga morajo sprejeti nebesa do časov obnovitve vseh stvari, ki jih je Bog govoril po ustih vseh svojih svetih prerokov, odkar je svet nastal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Kajti Mojzes je očetom resnično rekel: ›Preroka vam bo Gospod, vaš Bog, vzdignil izmed vaših bratov, podobnega meni; njega boste poslušali v vseh stvareh, karkoli vam bo govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'In zgodilo se bo, da bo vsaka duša, ki ne bo poslušala tega preroka, uničena izmed ljudi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Da, in vsi preroki od Samuela in tisti, ki so sledili, kolikor jih je govorilo, so enako napovedali o teh dneh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vi ste otroci prerokov in zaveze, ki jo je Bog sklenil z našimi očeti, rekoč Abrahamu: ›In v tvojem semenu bodo blagoslovljena vsa sorodstva zemlje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, '§ K vam je najprej Bog, ki je vzdignil svojega Sina Jezusa, njega poslal, da vas blagoslovi z odvračanjem vsakega izmed vas od njegovih krivičnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'In medtem ko sta govorila ljudem, so nadnju prišli duhovniki in tempeljski stotnik ter saduceji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'ki so bili užaloščeni, da sta učila ljudi in oznanjala vstajenje od mrtvih po Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, '§ In nanju so položili roke ter ju zadržali do naslednjega dne, kajti sedaj je bil večer.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Vendar so mnogi izmed teh, ki so slišali besedo, verovali; in število ljudi je bilo okoli pet tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'In pripetilo se je naslednji dan, da so se njihovi vladarji in starešine in pisarji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'in Hana, véliki duhovnik in Kajfa in Janez in Aleksander in kolikor jih je bilo iz sorodstva vélikega duhovnika, skupaj zbrali v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'In ko so ju postavili medse, so vprašali: »S kakšno močjo ali s čigavim imenom sta to naredila?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tedaj jim je Peter, izpolnjen s Svetim Duhom, rekel: »Vi vladarji ljudi in starešine v Izraelu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'če sva ta dan zasliševana o dobrem delu, storjenem nemočnemu človeku, na kakšen način je bil on ozdravljen;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'bodi znano vam vsem in vsem ljudem v Izraelu, da v imenu Jezusa Kristusa iz Nazareta, ki ste ga križali, ki ga je Bog obudil od mrtvih, celó po njem ta človek sedaj tukaj pred vami stoji ozdravljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, '§ To je kamen, ki je bil zaničevan od vas graditeljev, ki je postal glava vogalu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Niti ni rešitve duš v nikomer drugem, kajti pod nebom med ljudmi ni dano drugega imena, s katerim moremo biti rešeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Torej ko so videli Petrov in Janezov pogum ter zaznali, da sta bila neizobražena in nepoučena človeka, so se čudili; in o njiju so spoznali, da sta bila z Jezusom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'In ko so gledali moža, ki je bil ozdravljen, stati z njimi, proti temu niso mogli reči ničesar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Toda ko so jima zapovedali, da se odstranita od vélikega zbora, so se med seboj posvetovali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'rekoč: »Kaj naj storimo tema možema? Kajti ta zares opazen čudež, storjen po njima, je očiten vsem tistim, ki prebivajo v Jeruzalemu; in tega ne moremo zanikati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Toda da se to ne razširi naprej med ljudmi, jima strogo zagrozimo, da odslej nobenemu človeku ne govorita v tem imenu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'In poklicali so ju ter jima zapovedali sploh ne govoriti niti učiti v Jezusovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Toda Peter in Janez sta odgovorila in jim rekla: »Sami presodite, ali je v Božjih očeh bolj pravilno poslušati vas kakor Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Kajti midva ne moreva, da ne bi govorila stvari, ki sva jih videla in slišala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Torej ko so jima še naprej grozili, so ju izpustili zaradi ljudi, ker niso našli ničesar, da bi ju lahko kaznovali, kajti vsi ljudje so slavili Boga za to, kar je bilo storjeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Kajti mož, na katerem se je prikazal ta čudež ozdravljenja, je bil star več kot štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'In ko sta bila izpuščena, sta odšla k svoji lastni druščini ter poročala o vsem, kar so jima visoki duhovniki in starešine rekli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'In ko so oni to slišali, so svoje glasove soglasno povzdignili k Bogu ter rekli: »Gospod, ti si Bog, ki je naredil nebo in zemljo in morje ter vse, kar je v njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'ki si po ustih svojega služabnika Davida rekel: ›Zakaj besnijo pogani in si ljudje domišljajo prazne stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Kralji zemlje so vstali in vladarji so bili skupaj zbrani zoper Gospoda in zoper njegovega Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, '§ Kajti resnično so se proti tvojemu svetemu otroku Jezusu, ki si ga ti mazilil, skupaj zbrali tako Herod kakor Poncij Pilat s pogani in Izraelovi ljudje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'da storijo, karkoli je tvoja roka in tvoja namera poprej določila, da se stori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'In sedaj, Gospod, glej njihove grožnje in zagotovi svojim služabnikom, da bodo lahko z vsem pogumom govorili tvojo besedo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'z iztegnitvijo svoje roke, da ozdravlja; in da bodo znamenja in čudeži lahko storjeni z imenom tvojega svetega otroka Jezusa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'In ko so molili, se je zatresel kraj, kjer so bili skupaj zbrani; in vsi so bili izpolnjeni s Svetim Duhom in s pogumom so govorili Božjo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Množica teh, ki so verovali, pa je bila enega srca in ene duše; niti nobeden izmed njih ni rekel, da je bilo karkoli od stvari, ki jih je imel v lasti, njegovo, temveč so vse stvari imeli skupne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Apostoli pa so z veliko močjo podajali pričevanje o vstajenju Gospoda Jezusa, in nad njimi vsemi je bila velika milost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Niti ni bilo med njimi nikogar, ki bi trpel pomanjkanje, kajti kolikor jih je bilo lastnikov zemljišč ali hiš, so jih prodali in prinesli vrednost stvari, ki so bile prodane');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'in jih polagali k stopalom apostolov in narejena je bila porazdelitev vsakemu človeku glede na njegovo potrebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'In Jožef, ki je bil po apostolih imenovan z vzdevkom Barnaba (kar je prevedeno: ›Sin tolažbe‹), Lévijevec in iz dežele Cipra,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'je imel zemljo, jo prodal in prinesel denar ter ga položil k stopalom apostolov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Toda nek človek, po imenu Hananija, je s Safíro, svojo ženo, prodal posestvo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'in zadržal del denarne vsote in tudi njegova žena je bila seznanjena s tem in prinesel je določen del ter ga položil k stopalom apostolov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Toda Peter je rekel: »Hananija, zakaj je Satan napolnil tvoje srce, da lažeš Svetemu Duhu in da zadržiš del vsote od zemljišča?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Dokler je ostajalo ali ni bilo tvoje lastno? In potem, ko je bilo prodano ali ni bilo v tvoji lastni oblasti? Zakaj si v svojem srcu spočel to stvar? Nisi lagal ljudem, temveč Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'In ko je Hananija slišal te besede, je padel dol ter izročil duha. In velik strah je prišel na vse tiste, ki so slišali te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Mladeniči pa so vstali, ga ovili in ga odnesli ven ter ga pokopali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'In bilo je približno tri ure kasneje, ko je vstopila njegova žena, ki ni vedela, kaj se je bilo zgodilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'In Peter jo je ogovoril: »Povej mi ali sta za toliko prodala zemljišče?« In ona je rekla: »Da, za toliko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Tedaj ji je Peter rekel: »Kako je to, da sta se skupaj strinjala, da skušata Gospodovega Duha? Glej, stopala teh, ki so pokopala tvojega soproga, so pri vratih in odnesli te bodo ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Potem je nemudoma padla ob njegovih stopalih in izročila duha. In vstopili so mladeniči ter jo našli mrtvo in ko so jo odnesli, so jo pokopali poleg njenega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'In velik strah je prišel nad vso cerkev in nad vse, ki so slišali te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Po rokah apostolov pa se je med ljudmi zgodilo mnogo znamenj in čudežev; (in vsi so bili s soglasjem v Salomonovem preddverju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Od preostalih pa se jim noben človek ni drznil pridružiti, toda ljudje so jih poveličevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'In še več vernikov je bilo dodanih h Gospodu, množice tako moških kakor žensk.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Toliko, da so na ulice prinašali bolne in jih polagali na postelje ter ležišča, da bi lahko vsaj Petrova senca, ko je šel mimo, zasenčila nekatere izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Tudi ven iz mest naokoli Jeruzalema je prišla množica, ki je prinašala bolne ljudi in te, ki so bili nadlegovani z nečistimi duhovi; in vsi so bili ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Tedaj je vstal véliki duhovnik in vsi tisti, ki so bili z njim (kar je saducejska ločina) in izpolnjeni so bili z ogorčenjem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'in svoje roke so položili na apostole ter jih vtaknili v skupno ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Toda Gospodov angel je ponoči odprl vrata ječe in jih privedel naprej ter rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '»Pojdite, stopíte in govorite ljudem v templju vse besede tega življenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'In ko so to slišali, so zgodaj zjutraj vstopili v tempelj ter učili. Toda prišel je véliki duhovnik in tisti, ki so bili z njim in so sklicali skupaj véliki zbor in ves senat Izraelovih otrok in poslali k ječi, da bi jih privedli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Toda ko so prišli častniki in jih niso našli v ječi, so se vrnili ter povedali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'rekoč: »Ječo smo resnično našli zaprto z vso varnostjo in čuvaje, ki so stali zunaj pred vrati, toda ko smo odprli, v njej nismo našli nobenega človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Torej ko so véliki duhovnik in tempeljski stotnik ter visoki duhovniki slišali te besede, so se bali k čému se bo to razvilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Tedaj je nekdo prišel ter jim povedal, rekoč: »Glejte, možje, ki ste jih vtaknili v ječo, stojijo v templju in učijo ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tedaj je stotnik s častniki odšel in jih privedel brez nasilja, kajti bali so se ljudi, da jih ne bi kamnali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'In ko so jih privedli, so jih postavili pred véliki zbor in véliki duhovnik jih je vprašal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'rekoč: »Ali vam nismo strogo zapovedali, da naj ne bi učili v tem imenu? In glejte, Jeruzalem ste napolnili s svojim naukom in nad nas nameravate privesti kri tega človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Potem so Peter in drugi apostoli odgovorili ter rekli: »Mi moramo bolj ubogati Boga kakor ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bog naših očetov je obudil Jezusa, ki ste ga vi usmrtili in obesili na les.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, '§ Njega je Bog s svojo desnico povišal, da postane Princ in Odrešenik, da bi Izraelu dal kesanje in odpuščanje grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'In mi smo njegove priče o teh stvareh; in tako je tudi Sveti Duh, ki ga je Bog dal tistim, ki ga ubogajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Ko so to slišali, so bili do srca zbodeni in se posvetovali, da jih ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Potem je nekdo v vélikem zboru vstal, farizej, po imenu Gamáliel, učen mož postave, ugleden med vsemi ljudmi in velel, da jih za nekaj časa vržejo ven;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'in jim rekel: »Vi, možje v Izraelu, pazite se, kaj nameravate storiti glede teh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Kajti pred temi dnevi je vstal Tevdá, ki se je bahal, da je pomemben; kateremu so se pridružili številni ljudje, okoli štiristo; ki je bil umorjen, in vsi, kolikor se mu jih je pokoravalo, so bili razkropljeni in uničeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Po tem možu je, v dneh obdavčenja, vstal Juda iz Galileje in za seboj potegnil mnogo ljudi; tudi on je umrl in vsi so bili razkropljeni, celó tako mnogi, kot so ga ubogali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'In sedaj vam povem: ›Zadržite se pred temi ljudmi in pustite jih pri miru. Kajti če je ta namera ali to delo od ljudi, se bo izjalovilo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'toda če je to od Boga, tega ne morete premagati, da ne bi bili morda najdeni celo, da se borite zoper Boga.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'In strinjali so se z njim. Ko pa so poklicali apostole ter jih pretepli, so jim zapovedali, da naj ne govorijo v Jezusovem imenu in jih izpustili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'In odšli so izpred prisotnosti vélikega zbora, veseli, da so bili spoznani za vredne trpeti sramoto zaradi njegovega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'In niso prenehali v templju in v vsaki hiši vsak dan učiti ter oznanjati Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'In v tistih dneh, ko je bilo število učencev pomnoženo, je nastalo mrmranje Grkov zoper Hebrejce, ker so bile njihove vdove zapostavljene pri vsakodnevni oskrbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Potem je dvanajsterica k sebi poklicala množico učencev in rekla: »To ni razlog, da bi opuščali Božjo besedo in stregli [pri] mizah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Zatorej bratje, poiščite med seboj sedem mož, na dobrem glasu, polnih Svetega Duha in modrosti, ki jim lahko določimo to opravilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Toda mi se bomo predali v nenehno molitev in službo besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'In ta beseda je ugajala vsej množici. In izbrali so Štefana, moža, polnega vere in Svetega Duha in Filipa in Prohorja in Nikánorja in Timona in Parmenája ter Nikolaja, spreobrnjenca iz Antiohije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'ki jih so postavili pred apostole. In ko so molili, so nanje položili svoje roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'In Božja beseda je rasla in število učencev v Jeruzalemu se je silno pomnožilo in velika skupina duhovnikov je bila pokorna veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'In Štefan je, poln vere in moči, delal med ljudmi velike čudeže in čudežne moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Potem so vstali nekateri iz sinagoge, ki se je imenovala sinagoga Libertincev in Cirencev in Aleksandríncev in teh iz Kilikije ter iz Azije in so razpravljali s Štefanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Niso pa se mogli upirati modrosti in duhu, po katerem je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tedaj so podkupili može, ki so rekli: »Slišali smo ga govoriti bogokletne besede zoper Mojzesa in zoper Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'In razvneli so ljudi in starešine ter pisarje in prišli nad njega in ga zgrabili ter ga privedli k vélikemu zboru');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'in postavili krive priče, ki so rekle: »Ta človek ne preneha govoriti bogokletnih besed proti temu svetemu prostoru in postavi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'kajti slišali smo ga govoriti, da bo ta Jezus Nazarečan uničil ta kraj in spremenil običaje, ki nam jih je izročil Mojzes.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'In vsi, ki so sedeli v vélikem zboru, so neomajno zrli vanj in videli njegov obraz, kot bi bil obraz angela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Potem je véliki duhovnik rekel: »Ali so te stvari take?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'In rekel je: »Možje, bratje in očetje, prisluhnite: ›Bog slave se je prikazal našemu očetu Abrahamu, ko je bil v Mezopotamiji, preden je prebival v Haránu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'in mu rekel: ›Pojdi ven iz svoje dežele in iz svojega sorodstva ter pridi v deželo, ki ti jo bom pokazal.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, '§ Tedaj je prišel iz kaldejske dežele in prebival v Haránu; ko pa je bil njegov oče mrtev, se je od tam odpravil v to deželo, v kateri vi sedaj prebivate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'V njej pa mu ni dal nobene dediščine niti toliko ne, da nanjo postavi svoje stopalo, vendar je obljubil, da mu jo bo dal v posest in njegovemu semenu za njim, ko takrat še ni imel otroka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'In Bog je govoril na ta način: ›Da naj bi njegovo seme začasno bivalo v tuji deželi in da naj bi jih privedli v suženjstvo ter štiristo let z njimi hudobno ravnali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Narodu pa, pri katerem bodo suženjevali, bom sodil jaz,‹ je rekel Bog: ›in potem bodo prišli ter mi služili na tem kraju.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'In dal mu je zavezo obrezovanja. In tako je Abraham zaplodil Izaka in ga osmi dan obrezal; in Izak je zaplodil Jakoba; in Jakob je zaplodil dvanajstere očake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'In očaki so, prevzeti z zavistjo, Jožefa prodali v Egipt. Toda Bog je bil z njim');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'in ga osvobodil iz vseh njegovih stisk in mu dal naklonjenost ter modrost v očeh faraona, egiptovskega kralja in ga naredil za voditelja nad Egiptom ter vso svojo hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Torej nad vso egiptovsko deželo in Kánaan je prišlo pomanjkanje in velika stiska in naši očetje niso našli hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Toda ko je Jakob slišal, da je bilo v Egiptu žito, je najprej odposlal naše očete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'In ob drugi priložnosti se je Jožef dal spoznati svojim bratom; in Jožefovo sorodstvo je bilo predstavljeno faraonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Potem je Jožef odposlal in k sebi poklical svojega očeta Jakoba in vse njegovo sorodstvo, petinsedemdeset duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Tako je Jakob odšel dol v Egipt ter umrl, on in naši očetje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'in bili so preneseni preko v Sihem in položeni v mavzolej, ki ga je Abraham kupil za vsoto denarja od sinov Hemórja, očeta iz Sihema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Toda ko se je približal obljubljeni čas, ki ga je Bog prisegel Abrahamu, so ljudje v Egiptu rasli in se množili,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'dokler ni vstal drug kralj, ki ni poznal Jožefa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ta isti je z našim sorodstvom premeteno ravnal in hudobno tretiral naše očete, tako da so izpostavili svoje majhne otroke, z namenom, da ne bi živeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'V tem času je bil rojen Mojzes, bil pa je silno lep in tri mesece so ga vzgajali v hiši njegovega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Ko pa je bil izpostavljen, ga je vzela faraonova hči in ga vzgojila za svojega lastnega sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'In Mojzes je bil izučen v vsej egipčanski modrosti in mogočen je bil v besedah in dejanjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Ko je bil star polnih štirideset let, je prišlo v njegovo srce, da obišče svoje brate, Izraelove otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'In ko je videl enega izmed njih krivično trpeti, ga je branil in maščeval tega, ki je bil zatiran ter ubil Egipčana,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'kajti domneval je, da bodo njegovi bratje razumeli, kako jih hoče Bog po njegovi roki osvoboditi. Toda niso razumeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'In medtem ko so se prepirali, se jim je naslednji dan pokazal ter jih ponovno skušal pomiriti, rekoč: ›Možje, vi ste bratje; zakaj drug drugemu delate krivico?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Toda tisti, ki je svojemu bližnjemu storil krivico, ga je odrinil proč, rekoč: ›Kdo te je naredil za vladarja in sodnika nad nami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Ali me hočeš ubiti, kakor si včeraj storil Egipčanu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Ob tej besedi je Mojzes pobegnil in bil tujec v midjánski deželi, kjer je zaplodil dva sinova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Ko pa je preteklo štirideset let, se mu je v divjini Sinajske gore prikazal Gospodov angel v plamenu gorečega grma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Ko je Mojzes to videl, se je čudil prizoru. Ko pa se je približal, da bi to pogledal, je prišel do njega Gospodov glas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'rekoč: ›Jaz sem Bog tvojih očetov, Bog Abrahamov in Bog Izakov in Bog Jakobov.‹ Potem je Mojzes trepetal in si ni drznil pogledati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Nato mu je Gospod rekel: ›Sezuj si svoje čevlje s svojih stopal, kajti kraj, kjer stojiš, je sveta zemlja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Videl sem, videl sem stisko svojih ljudi, ki so v Egiptu in slišal sem njihovo stokanje in sem prišel dol, da jih osvobodim. In sedaj pridi, poslal te bom v Egipt.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tega Mojzesa, ki so ga zavrnili, rekoč: ›Kdo te je naredil vladarja in sodnika?‹ istega je Bog poslal, da bi bil vladar in osvoboditelj po roki angela, ki se mu je prikazal v grmu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Potem ko je v egiptovski deželi in v Rdečem morju ter v divjini štirideset let prikazoval čudeže in znamenja, jih je privedel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, '§ To je ta Mojzes, ki je Izraelovim otrokom rekel: ›Preroka vam bo Gospod, vaš Bog, obudil izmed vaših bratov, podobnega meni; njega boste poslušali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, '§ To je tisti, ki je bil v cerkvi v divjini z angelom, ki je govoril z njim na Sinajski gori in z našimi očeti; ki je prejel žive prerokbe, da jih izroči nam;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'katerega naši očetje niso hoteli ubogati, temveč so ga pahnili od sebe in se v svojih srcih ponovno obrnili nazaj v Egipt,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'rekoč Aronu: ›Naredi nam bogove, da gredo pred nami, kajti glede tega Mojzesa, ki nas je privedel iz egiptovske dežele, ne vemo, kaj je nastalo iz njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'In v tistih dneh so naredili tele in maliku darovali žrtev ter se veselili v delih svojih lastnih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Potem se je Bog obrnil in jih predal, da obožujejo vojsko neba; kakor je pisano v knjigi prerokov: ›Oh hiša Izraelova ali ste meni darovali zaklane živali in žrtve v obdobju štiridesetih let v divjini?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Da, vzeli ste Molohov šotor in zvezdo svojega boga Rajfána, kipe, ki ste jih naredili, da bi jih oboževali; jaz pa vas bom odvedel onstran Babilona.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Naši očetje so imeli v divjini šotorsko svetišče pričevanja, kakor je določil on, govoreč Mojzesu, da naj ga naredi glede na videz, ki ga je videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, '§ Katerega so tudi naši očetje, ki so prišli kasneje, vnesli z Jezusom na posest poganov, ki jih je Bog pregnal izpred obličja naših očetov do Davidovih dni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'ki je našel naklonjenost pred Bogom in si želel najti šotorsko svetišče za Jakobovega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Toda Salomon mu je zgradil hišo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Vendar Najvišji ne prebiva v templjih, zgrajenimi z rokami; kakor pravi prerok:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '›Nebesa so moj prestol in zemlja je moja pručka. Kakšno hišo mi hočete zgraditi?‹ govori Gospod: ›Ali kaj je prostor mojega počitka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Ali ni vse te stvari naredila moja roka?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Vi trdovratni in neobrezani v srcu in ušesih, vi se vedno upirate Svetemu Duhu. Kakor so počeli vaši očetje, tako počnete vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Katerega izmed prerokov vaši očetje niso preganjali? In umorili so te, ki so vnaprej kazali na prihod Pravičnega, katerega izdajalci in morilci ste bili sedaj vi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'ki ste po uredbi angelov prejeli postavo, pa se je niste držali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Ko so slišali te besede, so bili zarezani do srca in s svojimi zobmi so škripali proti njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Toda on je, poln Svetega Duha, neomajno gledal gor v nebesa in videl Božjo slavo ter Jezusa stati na Božji desnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'In rekel: »Glejte, nebesa vidim odprta in Sina človekovega stati na Božji desnici.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Tedaj so z močnim glasom zakričali in zamašili svoja ušesa ter soglasno stekli nadenj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'in ga vrgli iz mesta ter ga kamnali. Priče pa so svoja oblačila položile k stopalom mladeniča, katerega ime je bilo Savel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'In kamnali so Štefana, ki je klical k Bogu ter govoril: »Gospod Jezus, sprejmi mojega duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'In pokleknil je ter z močnim glasom zaklical: »Gospod, tega greha jim ne položi na njihovo obtožnico.« In ko je to rekel, je zaspal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'In Savel je privolil v njegovo smrt. In ob tistem času je bilo tam veliko preganjanje zoper cerkev, ki je bila v Jeruzalemu; in vsi, razen apostolov, so bili razkropljeni povsod po vseh področjih Judeje in Samarije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'In predani možje so Štefana odnesli k njegovemu pokopu ter za njim pripravili veliko objokovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Toda Savel je napravil veliko opustošenje cerkve, ko je vstopal v vsako hišo in vlačil [ven] moške in ženske ter jih zapiral v ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Zaradi tega so tisti, ki so bili razkropljeni naokoli, odšli povsod in oznanjali besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Potem je Filip odšel dol v samarijsko mesto in jim oznanil Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'In množica je soglasno dala pozornost tem stvarem, ki jih je Filip govoril in poslušala ter gledala čudeže, ki jih je delal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Kajti nečisti duhovi so kričê, z močnim glasom prihajali iz mnogih, ki so bili z njimi obsedeni. In mnogi prevzeti s paralizo ter tisti, ki so bili hromi, so bili ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'In v tistem mestu je bila velika radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Vendar je bil tam nek mož, imenovan Simon, ki je poprej v istem mestu uporabljal čaranje in privlačil pogane iz Samarije ter objavljal, da je bil on sam nekaj velikega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'ki so mu vsi posvetili pozornost, od najmanjših do največjih, rekoč: »Ta mož je velika Božja moč.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'In ozirali so se nanj, zato ker jih je že dolgo časa privlačil s svojimi čarodejstvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Toda ko so verovali Filipu, ki je oznanjal besede glede Božjega kraljestva in ime Jezusa Kristusa, so bili krščeni, tako moški kakor ženske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Potem je tudi sam Simon veroval; in ko je bil krščen, je ostal s Filipom in se čudil ter gledal čudeže in znamenja, ki so bila storjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Ko so torej apostoli, ki so bili v Jeruzalemu, slišali, da je Samarija sprejela Božjo besedo, so jim poslali Petra in Janeza,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'ki sta, ko sta prišla dol, molila zanje, da bi mogli prejeti Svetega Duha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(kajti do takrat še ni padel na nobenega izmed njih. Bili so samo krščeni v imenu Gospoda Jezusa.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tedaj sta nanje polagala svoje roke in prejemali so Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'In ko je Simon videl, da je bil Sveti Duh dan po polaganju rok apostolov, jima je ponudil denar,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'rekoč: »Dajta tudi meni to moč, da na kogarkoli položim roke, bo lahko prejel Svetega Duha.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Vendar mu je Peter rekel: »Tvoj denar naj propade s teboj, ker si pomislil, da se Božji dar lahko kupi z denarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Ti nimaš niti vloge niti deleža v tej stvari, kajti tvoje srce ni iskreno v Božjih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Pokesaj se torej od te svoje zlobnosti in prosi Boga, če ti bo mogoče lahko odpuščena misel tvojega srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Kajti zaznavam, da si v žolču grenkobe in v vezi krivičnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Potem je Simon odgovoril in rekel: »Prosita zame h Gospodu, da nobena izmed teh stvari, ki sta jih govorila, ne pride nadme.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'In onadva, ko sta pričevala in oznanila Gospodovo besedo, sta se vrnila v Jeruzalem ter v mnogih vaseh Samarije oznanila evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Gospodov angel pa je spregovoril Filipu, rekoč: »Vstani in pojdi proti jugu, na pot, ki gre dol iz Jeruzalema v Gazo, ki je zapuščena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'In vstal je ter odšel. In glej, človek iz Etiopije, evnuh z veliko oblastjo pod Kandáko, kraljico Etiopijcev, ki je imel skrb za vso njeno zakladnico in je prišel v Jeruzalem, da bi oboževal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'se je vračal in sedé na svoji kočiji bral preroka Izaija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Potem je Duh rekel Filipu: »Pojdi poleg in se pridruži tej kočiji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'In Filip je stekel tja k njemu in ga slišal brati preroka Izaija ter rekel: »Razumeš, kaj bereš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'In rekel je: »Kako bi lahko, razen če me ne bi vodil nek človek?« In prosil je Filipa, da pride gor in se usede z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Mesto iz pisma, ki ga je bral, je bilo to: ›Odveden je bil kakor ovca h klanju; in kakor je jagnje pred svojim strižcem nemo, tako on ni odprl svojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'V njegovem ponižanju je bila njegova sodba odstranjena in kdo bo razglašal njegov rod? Kajti njegovo življenje je vzeto z zemlje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'In evnuh je odgovoril Filipu ter rekel: »Prosim te, o kom govori to prerok? O sebi ali nekem drugem človeku?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Potem je Filip odprl svoja usta in začel pri istem pismu in mu oznanil Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'In medtem ko sta nadaljevala po njuni poti, sta prišla do neke vode, in evnuh je rekel: »Poglej, tukaj je voda, kaj mi preprečuje biti krščen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '§ In Filip je rekel: »Če veruješ z vsem svojim srcem, smeš.« In ta je odgovoril ter rekel: »Verujem, da je Jezus Kristus Božji Sin.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'In velel je kočiji, da se ustavi. In skupaj sta odšla dol v vodo, tako Filip kakor evnuh; in ga je krstil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'In ko sta se povzpela iz vode, je Gospodov Duh Filipa vzel, da ga evnuh ni več videl in ta je radosten odšel na svojo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Toda Filip se je znašel pri Ašdódu. In ko je potoval skozi, je v vseh mestih oznanjal, dokler ni prišel do Cezareje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Savel pa, ki je še vedno izdihoval grožnje in poboj zoper Gospodove učence, je odšel k vélikemu duhovniku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'in si od njega izprosil pisem za shodnice v Damasku, da če najde kogarkoli od te poti, bodisi moške ali ženske, bi jih lahko zvezane privedel v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Medtem ko je potoval, se je približal Damasku in nenadoma je naokoli njega zasvetila svetloba iz nebes');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'in padel je na tla ter zaslišal glas, ki mu je rekel: »Savel, Savel, zakaj me preganjaš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, '§ On pa je rekel: »Kdo si ti, Gospod?« In Gospod je rekel: »Jaz sem Jezus, ki ga ti preganjaš. Zate je to težko, da se upiraš bodicam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, '§ In ta je trepetajoč in osupel rekel: »Gospod, kaj hočeš, da storim?« In Gospod mu je rekel: »Vstani in pojdi v mesto in povedano ti bo, kaj moraš storiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Možje, ki so potovali z njim, pa so stali brez besed, ker so poslušali glas, vendar niso videli nobenega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'In Savel se je dvignil s tal in ko so bile njegove oči odprte, ni videl nobenega človeka, ampak so ga vodili za roko in ga privedli v Damask.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'In tri dni je bil brez vida in ni ne jedel, ne pil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'V Damasku pa je bil nek učenec, po imenu Hananija in njemu je Gospod v videnju rekel: »Hananija.« In ta je rekel: »Glej, jaz sem tu, Gospod.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'In Gospod mu je rekel: »Vstani in pojdi v ulico, ki se imenuje Ravna in v Judovi hiši povprašaj za nekoga, ki se imenuje Savel iz Tarza; kajti glej, on moli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'in v videnju je videl moža, imenovanega Hananija, ki je vstopil in nanj položil svojo roko, da bi lahko prejel svoj vid.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Potem je Hananija odgovoril: »Gospod, od mnogih sem slišal o tem človeku, koliko zla je storil tvojim svetim v Jeruzalemu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'in tukaj ima od visokih duhovnikov oblast, da zveže vse, ki kličejo tvoje ime.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Toda Gospod mu je rekel: »Odpravi se, kajti on mi je izbrana posoda, da ponese moje ime pred pogane in kralje in Izraelove otroke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'kajti pokazal mu bom, kako velike stvari mora trpeti zaradi mojega imena.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'In Hananija je odšel svojo pot ter vstopil v hišo in ko je svoje roke položil nanj, je rekel: »Brat Savel, Gospod, celó Jezus, ki se ti je prikazal na poti, ko si prihajal, me je poslal, da lahko prejmeš svoj vid in izpolnjen boš s Svetim Duhom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'In takoj so z njegovih oči padle, kot bi bile luskine, in nemudoma je prejel vid in vstal ter bil krščen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'In ko je prejel hrano, je bil okrepljen. Potem je bil Savel nekaj dni z učenci, ki so bili v Damasku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'In nemudoma je v sinagogah oznanjal Kristusa, da je on Božji Sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Toda vsi, ki so ga slišali, so bili osupli in rekli: »Ali ni to tisti, ki je uničil tiste, ki so se v Jeruzalemu sklicevali na to ime in je prišel sèm zaradi tega namena, da bi jih lahko zvezane privedel k visokim duhovnikom?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Toda Savel je še bolj narasel v moči in zbegal Jude, ki so prebivali v Damasku ter dokazoval, da je ta pravi Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'In potem, ko so bili izpolnjeni mnogi dnevi, so se Judje posvetovali, da ga ubijejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'toda njihovo prežanje v zasedi je bilo sporočeno Savlu. In noč in dan so stražili velika vrata, da ga ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Potem so ga učenci ponoči vzeli in ga v košari spustili dol ob obzidju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'In ko je Savel prišel v Jeruzalem, se je poskusil pridružiti učencem, toda vsi so se ga bali in niso verjeli, da je bil učenec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Vendar ga je Barnaba vzel in ga privedel k apostolom ter jim razodel, kako je na poti videl Gospoda in da mu je govoril ter kako je v Damasku pogumno oznanjal v Jezusovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'In bil je z njimi in prihajal in odhajal iz Jeruzalema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'In pogumno je govoril v imenu Gospoda Jezusa ter se prerekal proti Grkom, toda oni so ga poskušali umoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Nakar, ko so bratje [to] izvedeli, so ga odvedli dol v Cezarejo in ga poslali v Tarz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Potem so imele cerkve po vsej celotni Judeji in Galileji ter Samariji mir in se izgrajevale, in ker so živele v strahu Gospodovem ter v tolažbi Svetega Duha, so bile pomnožene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'In pripetilo se je, ko je Peter potoval po vseh celotnih okoliših, [da] je prišel tudi dol k svetim, ki so prebivali v Lidi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'In tam je našel nekega moža, po imenu Enéj, ki se je osem let držal svoje postelje in je bil bolan zaradi paralize.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'In Peter mu je rekel: »Enéj, Jezus Kristus te celostno ozdravlja. Vstani in postelji svojo posteljo.« In ta je takoj vstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'In vsi tisti, ki so prebivali v Lidi in Šarónu, so ga videli ter se obrnili h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Torej v Jopi je bila neka učenka, po imenu Tabíta, kar se po razlagi imenuje Gazela. Ta ženska je bila polna dobrih del in dejanj miloščine, ki jih je storila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'In pripetilo se je v tistih dneh, da je bila bolna in je umrla. Ko so jo umili, so jo položili v zgornjo sobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Ker pa je bila Lida blizu Jope in so učenci slišali, da je bil tam Peter, so k njemu poslali dva moža, ki sta ga prosila, da ne bi odlašal priti k njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Potem je Peter vstal in odšel z njima. Ko je prišel, so ga odvedli v zgornjo sobo, in vse vdove so jokaje stale poleg njega in kazale plašče ter obleke, ki jih je naredila Gazela, dokler je bila z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Vendar jih je Peter vse vrgel ven ter pokleknil in molil, in ko se je obrnil k telesu, je rekel: »Tabíta, vstani.« In odprla je svoje oči, in ko je zagledala Petra, se je usedla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'In dal ji je svojo roko ter jo dvignil. In ko je poklical svete ter vdove, jo je izročil živo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'In to se je razvedelo po vsej celotni Jopi in mnogi so verovali v Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'In pripetilo se je, da je mnogo dni ostal v Jopi pri nekem strojarju Simonu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'V Cezareji je bil nek mož, imenovan Kornelij, stotnik čete, imenovana itálska četa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'predan mož in nekdo, ki se je z vso svojo hišo bal Boga, ki je ljudem dajal veliko miloščine in vedno molil k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Okoli devete dnevne ure je v videnju jasno videl Božjega angela prihajati k njemu, rekoč mu: »Kornelij.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'In ko je pogledal nanj, je bil prestrašen in rekel: »Kaj je, Gospod?« On pa mu je rekel: »Tvoje molitve in tvoje miloščine so prišle gor v spomin pred Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'In sedaj pošlji može v Jopo in pokliči nekega Simona, katerega vzdevek je Peter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, '§ Ta prenočuje pri nekem strojarju Simonu, čigar hiša je ob morski obali. On ti bo povedal, kaj moraš storiti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'In ko je angel, ki je govoril Korneliju, odšel, je ta poklical dva izmed svojih hišnih služabnikov in predanega vojaka izmed teh, ki so nenehno čakali nanj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'in ko jim je razglasil vse te stvari, jih je poslal v Jopo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Naslednji dan, ko so odšli na svoje potovanje in se približali mestu, se je Peter okoli šeste ure povzpel na hišno streho, da bi molil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Postal pa je zelo lačen in bi želel jesti, toda medtem ko so pripravljali, je padel v zamaknjenje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'in videl odprto nebo ter nekakšno posodo spuščati se k njemu, kot bi bil to velik pleten prt s štirimi vogali in se spuščal k zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'v katerem so bile vse vrste štirinožnih zemeljskih živali in divjih zveri in plazečih stvari ter perjad neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'In do njega je prišel glas: »Vstani, Peter, zakolji in jej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Vendar je Peter rekel: »Ne tako, Gospod, kajti še nikoli nisem jedel česarkoli, kar je oskrunjeno ali nečisto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Glas pa mu je ponovno, drugič, rekel: »Kar je Bog očistil, tega ne imenuj oskrunjeno.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'To se je zgodilo trikrat in posoda je bila ponovno sprejeta gor v nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Torej medtem ko je bil Peter v sebi zaskrbljen, kaj bi to videnje, ki ga je videl, lahko pomenilo, glej, so možje, ki so bili poslani od Kornelija, povprašali po Simonovi hiši in stali pred velikimi vrati');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'in zaklicali ter vprašali, ali je tam prenočeval Simon, ki je bil imenovan z vzdevkom Peter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Medtem ko je Peter premišljeval o videnju, mu je Duh rekel: »Glej, trije možje te iščejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Vstani torej in se spusti ter pojdi z njimi in nič ne dvomi, kajti jaz sem jih poslal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, '§ Potem je Peter odšel dol k možem, ki so bili k njemu poslani od Kornelija in rekel: »Glejte, jaz sem ta, ki ga iščete. Kakšen je razlog, zaradi česar ste prišli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'In rekli so: »Stotnik Kornelij, pravičen mož in nekdo, ki se boji Boga ter je na dobrem glasu med vsem judovskim narodom, je bil po svetem angelu od Boga obveščen, da pošlje v to hišo pote in da od tebe sliši besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Potem jih je poklical noter in jih prenočil. In naslednji dan je Peter z njimi odšel, spremljali pa so ga neki bratje iz Jope.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'In naslednji dan so vstopili v Cezarejo. In Kornelij jih je pričakoval ter sklical skupaj svoje sorodnike in bližnje prijatelje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'In ko je Peter vstopil, ga je srečal Kornelij in padel dol k njegovim stopalom ter ga oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Vendar ga je Peter dvignil, rekoč: »Vstani, tudi jaz sem človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'In medtem ko se je pogovarjal z njim, je vstopil ter našel mnoge, ki so bili zbrani skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'In rekel jim je: »Vi veste, da je to nezakonita stvar za človeka, ki je Jud, da se druži ali pride k nekomu iz drugega naroda. Toda Bog mi je pokazal, da naj nobenega človeka ne imenujem oskrunjenega ali nečistega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Zato sem brez ugovarjanja prišel k vam takoj, ko sem bil poklican. Sprašujem torej, zaradi kakšnega namena ste poslali pome?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, '§ In Kornelij je rekel: »Pred štirimi dnevi sem se postil do te ure. In ob deveti uri sem v svoji hiši molil in glej, pred menoj je stal mož v svetlem oblačilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'In rekel: ›Kornelij, tvoja molitev je uslišana in tvoje miloščine so v spominu v Božjih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, '§ Pošlji torej v Jopo in pokliči sèm Simona, katerega vzdevek je Peter. Nastanjen je ob morski obali, v hiši nekega strojarja Simona. Ko ta pride, ti bo spregovoril.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Takoj sem torej poslal pote in dobro si storil, da si prišel. Sedaj smo torej mi vsi tukaj zbrani pred Bogom, da slišimo vse stvari, ki so ti zapovedane od Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Tedaj je Peter odprl svoja usta in rekel: »Resnično zaznavam, da se Bog ne ozira na osebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'temveč je v vsakem narodu pri njem sprejet, kdor se ga boji in dela pravično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Besedo, ki jo je Bog poslal Izraelovim otrokom, ko je oznanjal mir po Jezusu Kristusu; (on je Gospod vsega),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'to besedo, pravim, vi poznate, ki je bila razglašena po vsej celotni Judeji in se začela iz Galileje, po krstu, ki ga je oznanjal Janez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Kako je Bog s Svetim Duhom in z močjo mazilil Jezusa iz Nazareta, ki je hodil okoli, delal dobro in ozdravljal vse, ki so bili zatirani od hudiča, kajti Bog je bil z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'In mi smo priče vseh stvari, ki jih je storil, tako v judovski deželi kakor v Jeruzalemu, ki so ga umorili in obesili na križ.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Njega je Bog tretji dan obudil in ga javno prikazal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ne vsem ljudem, temveč od Boga vnaprej izbranim pričam, celó nam, ki smo z njim jedli in pili potem, ko je vstal od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'In naročil nam je, naj oznanjamo ljudem in naj pričujemo, da je on tisti, ki je bil od Boga odrejen, da bo Sodnik živih in mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Njemu vsi preroki dajejo pričevanje, da bo po njegovem imenu, kdorkoli veruje vanj, prejel odpuščanje grehov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Medtem ko je Peter še govoril te besede, je Sveti Duh padel na vse te, ki so slišali besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'In tisti iz obreze, ki so verovali, so bili osupli, kolikor jih je prišlo s Petrom, zato ker je bil dar Svetega Duha izlit tudi na pogane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Kajti slišali so jih govoriti z jeziki in poveličevati Boga. Potem je Peter odgovoril:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '»Ali more kdorkoli prepovedati vodo, da ti, ki so enako kakor mi, prejeli Svetega Duha, ne bi bili krščeni?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, '§ In naročil jim je, naj jih krstijo v Gospodovem imenu. Potem so ga prosili, naj ostane nekaj dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Apostoli in bratje, ki so bili v Judeji, pa so slišali, da so tudi pogani sprejeli Božjo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'In ko je Peter prišel gor v Jeruzalem, so se tisti, ki so bili iz obreze, pričkali z njim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'rekoč: »Odšel si k neobrezanim ljudem in jedel z njimi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Toda Peter jim je zadevo ponovil od začetka in jim jo po vrsti pojasnil, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '»Bil sem v mestu Jopa in molil in v zamaknjenju sem videl videnje: ›Neka posoda se je spuščala, kot bi bil to velik prt, s štirimi vogali spuščan dol iz neba in ta je prišel celó do mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, '§ Na katerem sem, ko sem [vanj] uprl svoje oči, opazoval in zagledal štirinožne zemeljske živali in divje zveri in plazeče stvari ter perjad neba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'In zaslišal sem glas, ki mi je rekel: ›Vstani, Peter, zakolji in jej.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Vendar sem rekel: ›Ne tako, Gospod, kajti v moja usta nikoli ni vstopilo nič oskrunjenega ali nečistega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Toda glas iz neba mi je ponovno odgovoril: ›Kar je Bog očistil, tega ne imenuj oskrunjeno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'To pa se je zgodilo trikrat in vse je bilo ponovno dvignjeno v nebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'In glej, takoj so bili tam trije možje, poslani k meni iz Cezareje, [ki so] že prišli k hiši, kjer sem bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'In Duh mi je zaukazal, naj grem z njimi, ne da bi kaj dvomil. Poleg tega me je spremljalo teh šest bratov in vstopili smo v moževo hišo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'in razložil nam je, kako je v svoji hiši videl angela, ki je stal ter mu rekel: ›Pošlji može v Jopo in pokliči Simona, katerega vzdevek je Peter,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'ki ti bo povedal besede, po katerih boš rešen ti in vsa tvoja hiša.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'In ko sem začel govoriti, je nanje padel Sveti Duh, kakor v začetku na nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Potem sem se spomnil Gospodove besede, kako je rekel: ›Janez je zares krščeval z vodo, toda vi boste krščeni s Svetim Duhom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Torej jim je tedaj Bog dal podoben dar, kakor ga je dal nam, ki smo verovali v Gospoda Jezusa Kristusa. Kaj sem bil jaz, da bi se mogel zoperstaviti Bogu?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Ko so slišali te stvari, so molčali in slavili Boga, rekoč: »Torej je Bog tudi poganom zagotovil kesanje v življenje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Torej tisti, ki so bili razkropljeni naokoli zaradi preganjanja, ki je nastalo okoli Štefana, so potovali prav do Fenikije in Cipra in Antiohije in nikomur niso oznanjali besede, razen samo Judom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Nekateri izmed teh pa so bili možje s Cipra in Cirene, ki so, ko so prišli v Antiohijo, govorili Grkom ter oznanjali Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'In Gospodova roka je bila z njimi, in veliko število [jih] je verovalo ter se spreobrnilo h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Potem so besede o teh stvareh prišle do ušes cerkve, ki je bila v Jeruzalemu, in poslali so naprej Barnaba, da bi šel prav do Antiohije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Kateri, ko je prišel in videl Božjo milost, je bil vesel in vse spodbujal, da bi se s srčnim namenom trdno držali Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Kajti bil je dober človek ter poln Svetega Duha in vere. In mnogo ljudi je bilo dodanih h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Potem se je Barnaba odpravil v Tarz, da poišče Savla,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'in ko ga je našel, ga je privedel v Antiohijo. In pripetilo se je, da sta se celo leto zbirala s cerkvijo ter učila mnogo ljudi. In učenci so bili v Antiohiji prvič imenovani kristjani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'In v teh dneh so prišli preroki iz Jeruzalema v Antiohijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'In vstal je nekdo, po imenu Agab ter po Duhu kazal, da naj bi bilo veliko pomanjkanje po vsem celotnem svetu, ki se je zgodilo v dneh cesarja Klavdija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Potem so bili učenci, vsak mož glede na svojo zmožnost, odločeni, da pošljejo pomoč bratom, ki prebivajo v Judeji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'kar so tudi storili in to po Barnabovih ter Savlovih rokah poslali starešinam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Torej okoli tega časa je kralj Herod iztegnil svoje roke, da nadleguje nekatere iz cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'In z mečem je ubil Jakoba, Janezovega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Ker pa je videl, [da] je Judom to ugajalo, je še bolj nadaljeval, da zgrabi tudi Petra. (Takrat so bili dnevi nekvašenega kruha.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, '§ In ko ga je zgrabil, ga je vtaknil v ječo ter ga izročil štirim četvericam vojakov, da ga varujejo, ker ga je mislil po Veliki noči privesti k ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Peter je bil torej zadržan v ječi, toda cerkev je zanj brez prenehanja molila k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'In ko naj bi ga Herod privedel, je isto noč Peter spal med dvema vojakoma, privezan z dvema verigama, čuvaji pred vrati pa so stražili ječo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'In glej, Gospodov angel je prišel nad njega in svetloba je zasijala v ječi in Petra je udaril v stran ter ga dvignil, rekoč: »Hitro vstani.« In njegove verige so odpadle z njegovih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'In angel mu je rekel: »Opaši se in si poveži svoje sandale.« In tako je storil. In mu reče: »Ogrni svojo obleko okoli sebe in mi sledi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'In odšel je ven ter mu sledil in ni vedel, da je bilo res, kar se je zgodilo po angelu, temveč je mislil, da je videl videnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Ko sta bila mimo prve in druge straže, sta prišla k velikim železnim vratom, ki vodijo v mesto, ki so se jima sama od sebe odprla in odšla sta ven ter šla skozi neko ulico in angel je nemudoma odšel od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Ko je Peter prišel k sebi, je rekel: »Sedaj zagotovo vem, da je Gospod poslal svojega angela in me osvobodil iz Herodove roke ter pred vsem pričakovanjem ljudi izmed Judov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Ko pa je stvar preudaril, je prišel k hiši Marije, Janezove matere, katerega vzdevek je bil Marko, kjer so bili mnogi skupaj zbrani ter molili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'In ko je Peter potrkal na velika vhodna vrata, je prišla prisluhnit gospodična, po imenu Roda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'In ko je spoznala Petrov glas, zaradi veselja ni odprla velikih vrat, temveč je stekla noter ter povedala, kako pred velikimi vrati stoji Peter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Oni pa so ji rekli: »Nora si.« Toda nenehno je zatrjevala, da je bilo točno tako. Tedaj so ji rekli: »To je njegov angel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Toda Peter je nenehno trkal in ko so odprli vrata ter ga zagledali, so bili osupli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Vendar ko jim je z roko namignil, naj molčijo, jim je razodel, kako ga je Gospod privedel iz ječe. In rekel je: »Pojdite, oznanite te stvari Jakobu in bratom.« In odšel je in šel v drug kraj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Torej brž, ko je bil dan, med vojaki ni bila majhna razvnetost, kaj je nastalo s Petrom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'In ko ga je Herod iskal in ga ni našel, je zaslišal čuvaje ter ukazal, da naj bi bili le-ti usmrčeni. In iz Judeje je odšel dol v Cezarejo ter ostal tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Herod pa je bil zelo jezen na te iz Tira in Sidóna, toda oni so soglasno prišli k njemu in ker so naredili Blasta, kraljevega glavnega dvornega upravitelja, za svojega prijatelja, so želeli mir, kajti njihova dežela je bila hranjena s pomočjo kraljeve dežele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Na določen dan pa se je Herod oblekel v kraljevsko obleko, se usedel na svoj prestol ter jim naredil slovesen govor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Ljudstvo [dežele] pa je vzklikalo, rekoč: »To je božji glas, ne pa od človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'In takoj ga je udaril Gospodov angel, ker ni dal slave Bogu in pojeden je bil od črvov ter izročil duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Toda Božja beseda je rasla in se množila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'In ko sta izpolnila svojo službo, sta se Barnaba in Savel vrnila iz Jeruzalema ter s seboj vzela Janeza, katerega vzdevek je bil Marko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Torej v cerkvi, ki je bila v Antiohiji, so bili določeni preroki in učitelji, kot Barnaba in Simeon, ki so ga imenovali Niger in Lukij iz Cirene in Manaén, ki je bil vzgojen s Herodom, vladarjem četrtinskega dela province ter Savel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Medtem ko so služili Gospodu in se postili, je Sveti Duh rekel: »Oddvojite mi Barnaba in Savla za delo, kamor sem ju poklical.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'In ko so se postili ter molili in svoje roke položili nanju, so ju odposlali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Tako sta, odposlana po Svetem Duhu, odšla v Selevkíjo in od tam sta odjadrala na Ciper.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'In ko sta bila v Salamini, sta v judovskih sinagogah oznanjala Božjo besedo in za svojo službo sta imela tudi Janeza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'In ko sta šla prek otoka do Pafosa, sta našla nekega čarodeja, lažnega preroka, Juda, katerega ime je bilo Barjezus,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'ki je bil z namestnikom dežele, Sergijem Pavlom, razsodnim človekom, ki je dal poklicati Barnaba in Savla ter želel slišati Božjo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Toda čarodej Elíma (kajti takšno je po razlagi njegovo ime), se jima je zoperstavil ter si prizadeval namestnika odvrniti od vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Potem je Savel (ki se imenuje tudi Pavel), izpolnjen s Svetim Duhom, svoje oči uprl vanj');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'in rekel: »Oh poln vseh premetenosti in vseh vragolij, ti hudičev otrok, ti sovražnik vse pravičnosti, ali ne boš prenehal izkrivljati Gospodovih ravnih poti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'In sedaj glej, Gospodova roka je nad teboj in oslepel boš ter za nekaj časa ne boš videl sonca.« In takoj sta padla nanj zamegljenost in tema in krožil je ter iskal nekoga, da ga vodi za roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Potem je namestnik, ko je videl, kaj se je zgodilo, veroval in bil osupel nad Gospodovim naukom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Torej ko so Pavel in njegova skupina odpluli iz Pafosa, so prišli v Pergo v Pamfiliji. Janez pa se je ločil od njiju in se vrnil v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Toda ko sta se odpravila iz Perge, sta prišla v Antiohijo v Pizidiji in na šabatni dan odšla v sinagogo ter se usedla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Po branju postave in prerokov pa so predstojniki sinagoge poslali ponju, rekoč: » Vidva moža in brata, če imata kako spodbudno besedo za ljudi, povejta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Tedaj je Pavel vstal in s svojo roko dal znamenje ter rekel: »Možje Izraelci in vi, ki se bojite Boga, poslušajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bog teh ljudi iz Izraela je izbral naše očete in povišal ljudi, ko so kot tujci prebivali v egiptovski deželi in jih s povzdignjenim laktom privedel ven iz nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'In približno okoli štirideset let je prenašal njihovo obnašanje v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'In ko je v kánaanski deželi uničil sedem narodov, jim je njihovo deželo razdelil z žrebom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Nató pa jim je dajal sodnike za približno štiristo petdeset let, do preroka Samuela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'In zatem so zahtevali kralja in Bog jim je dal Savla, Kiševega sina, moža iz Benjaminovega rodu, za približno štirideset let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'In ko ga je odstranil, jim je dvignil Davida, da bi bil njihov kralj, ki mu je dal tudi pričevanje ter rekel: ›Našel sem Davida, Jesejevega sina, moža po svojem lastnem srcu, ki bo izpolnil vso mojo voljo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, '§ Iz semena tega človeka je Bog, glede na svojo obljubo, Izraelu obudil Odrešenika, Jezusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'ko je pred njegovim prihodom Janez oznanjal krst kesanja vsem ljudem iz Izraela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'In ko je Janez izpolnil svoj tek, je rekel: ›Kdo mislite, da sem jaz? Jaz nisem on. Toda glejte, za menoj prihaja nekdo, čigar čevljev z njegovih stopal nisem vreden odvezati.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Možje in bratje, otroci Abrahamove rase ter kdorkoli se med vami boji Boga, vam je poslana beseda te rešitve duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Kajti tisti, ki prebivajo v Jeruzalemu in njihovi vladarji, ker niso spoznali njega niti glasov prerokov, ki se berejo vsak šabatni dan, so jih izpolnili z njegovo obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'In čeprav na njem niso našli nobenega razloga za smrt, so od Pilata zahtevali, da naj bi bil umorjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'In ko so izpolnili vse, kar je bilo pisano o njem, so ga sneli z lesa ter ga položili v mavzolej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Toda Bog ga je obudil od mrtvih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'in mnogo dni so ga videli tisti, ki so prišli z njim iz Galileje v Jeruzalem, ki so njegove priče ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'In mi vam razodevamo vesele novice, kako je to obljubo, ki je bila narejena očetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Bog izpolnil nam, njihovim otrokom, v tem, da je ponovno dvignil Jezusa, kakor je tudi pisano v drugem psalmu: ›Ti si moj Sin, danes sem te rodil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'In glede na to, da ga je obudil od mrtvih, sedaj ni več vrnitve k trohnenju, je rekel na ta način: ›Dal vam bom zanesljive Davidove milosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Zato tudi pravi v še enem psalmu: ›Svojemu Svetemu ne boš dal videti trohnenja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Kajti David je, potem ko je po Božji volji služil svojemu lastnemu rodu, zaspal in bil položen k svojim očetom ter videl trohnenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'toda ta, ki ga je Bog ponovno obudil, ni videl trohnenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Naj bo torej znano vam, možje in bratje, da se vam po tem človeku oznanjuje odpuščanje grehov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'in po njem ste vsi, ki verujete, opravičeni vseh stvari, od katerih niste mogli biti opravičeni po Mojzesovi postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Pazite se torej, da ne pride nad vas to, o čemer je govora v prerokih:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '›Glejte, vi prezirljivci in čudite se ter izginite, kajti v vaših dneh delam delo, delo katerega nikakor ne boste verovali, četudi vam ga človek razodene.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, '§ In ko so Judje odšli iz sinagoge, so pogani prosili, da bi jim bile te besede lahko oznanjene naslednjo šabat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Torej ko je bila skupnost razpuščena, so mnogi izmed Judov in religioznih spreobrnjencev sledili Pavlu in Barnabu, ki sta jim govorila in jih prepričevala naj nadaljujejo v Božji milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Naslednji šabatni dan pa je prišlo skupaj skoraj celotno mesto, da sliši Božjo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Toda ko so Judje videli množice, so bili izpolnjeni z zavistjo in ugovarjali ter preklinjali in govorili proti tem stvarem, ki jih je govoril Pavel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Tedaj sta Pavel in Barnaba postala pogumna in rekla: »Potrebno je bilo, da bi se Božja beseda najprej spregovorila vam, toda ker ste jo postavili proč od sebe in sebe sodite nevredne večnega življenja, glejte, se obračava k poganom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Kajti tako nam je ukazal Gospod, rekoč: ›Postavil sem te, da bi bil svetloba poganom, da naj bi bil za rešitev duš do koncev zemlje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'In ko so pogani to slišali, so bili veseli in slavili Gospodovo besedo; in kolikor jih je bilo odrejenih za večno življenje, je verovalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'In Gospodova beseda je bila razglašena po vsem celotnem področju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Toda Judje so razvneli predane in častitljive ženske ter vodilne može mesta ter dvignili preganjanje zoper Pavla in Barnaba ter ju izgnali iz svojih krajev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Vendar sta proti njim otresla prah s svojih stopal in prišla v Ikónij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Učenci pa so bili izpolnjeni z radostjo in s Svetim Duhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Pripetilo pa se je v Ikóniju, da sta oba skupaj odšla v judovsko sinagogo in tako govorila, da je velika množica, tako Judov kakor tudi Grkov, verovala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Toda neverni Judje so razvneli pogane in hudobno vplivali na njihovo mišljenje proti bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Ostala sta torej dolgo časa in pogumno govorila v Gospodu, ki je dal pričevanje k besedi svoje milosti in zagotovil, da so se po njunih rokah dogajala znamenja in čudeži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Vendar je bila množica iz mesta razdeljena; del je držal z Judi, del pa z apostoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'In ko je bil storjen napad, ki so ga sprožili tako pogani kakor tudi Judje s svojimi vladarji, da z njima kruto ravnajo in da ju kamnajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'sta bila o tem obveščena in pobegnila v Listro in Derbo, mesti v Likaoniji in k področju, ki leži naokoli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'in tam oznanjala evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'In v Listri je sedel nek mož, nemočen v svojih stopalih, pohabljen že od maternice svoje matere, ki nikoli ni hodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Isti je slišal Pavla govoriti. Ta je neomajno zrl vanj in zaznavajoč, da je imel vero, da bi bil ozdravljen,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'je z močnim glasom rekel: »Stopi pokonci na svoja stopala.« In poskočil je in hodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'In ko je množica videla, kaj je Pavel storil, so povzdignili svoje glasove, rekoč v likaonskem jeziku: »K nam dol sta prišla bogova v človeški podobi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'In Barnaba so imenovali Jupitra, Pavla pa Merkurja, ker je bil glavni govornik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Potem je Jupitrov svečenik, ki je bil pred njihovim mestom, k velikim vratom privedel vola in vence in z množico želel opraviti žrtvovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Nakar, ko sta apostola Barnaba in Pavel to slišala, sta razparala svoja oblačila in stekla med množico, vzklikajoč');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'in govoreč: »Možje, zakaj počnete te stvari? Tudi midva sva z vami človeka podobnih strasti in oznanjava vam, da naj bi se od teh ničevosti obrnili k živemu Bogu, ki je naredil nebo in zemljo in morje ter vse stvari, ki so v njih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'ki je v prejšnjih časih prenašal vse narode, da hodijo po svojih lastnih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Vendar sebe ni pustil brez pričevanja, ker je delal dobro in nam dajal dež z neba ter rodovitna obdobja in naša srca napolnjeval s hrano in veseljem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'In s temi besedami sta komaj zadržala množico, da jima ni opravila žrtvovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'In tja so prišli neki Judje iz Antiohije in Ikónija, ki so pregovorili množico in ko so kamnali Pavla, so ga izvlekli iz mesta, ker so mislili, da je bil mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Vendar ko so ga obkrožili učenci, je vstal ter prišel v mesto in naslednji dan z Barnabom odšel v Derbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'In ko sta temu mestu oznanila evangelij ter mnoge učila, sta se ponovno vrnila v Listro in v Ikónij in Antiohijo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'ter krepila duše učencev in jih spodbujala, naj nadaljujejo v veri in da moramo skozi veliko stisko vstopiti v Božje kraljestvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'In ko sta jim v vsaki cerkvi odredila starešine ter molila s postom, sta jih priporočila Gospodu, ki so mu verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'In potem, ko sta prepotovala skozi vso Pizidijo, sta prišla v Pamfilijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'In ko sta besedo oznanila v Pergi, sta odšla dol v Atálejo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'in od tam sta odjadrala v Antiohijo, od koder sta bila priporočena Božji milosti za delo, ki sta ga izvršila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'In ko sta prišla in so skupaj zbrali cerkev, sta jim ponovila vse, kar je Bog z njima storil in kako je odprl vrata vere k poganom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'In tam sta z učenci ostala dolgo časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Neki ljudje, ki so prišli dol iz Judeje, pa so učili brate in govorili: »Razen če ne boste obrezani po Mojzesovem običaju, ne morete biti rešeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Ko sta imela torej Pavel in Barnaba z njimi ne majhno razhajanje mnenj ter se z njimi pričkala, so odločili, da naj bi glede tega vprašanja Pavel in Barnaba ter nekateri drugi izmed njih šli gor v Jeruzalem, k apostolom in starešinam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'In na njihovo pot spremljani s cerkvijo, so šli skozi Fenikijo in Samarijo in razglašali spreobrnitev poganov in vsem bratom so napravili veliko radost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'In ko so prišli v Jeruzalem, so bili sprejeti od cerkve in od apostolov ter starešin in razglasili so vse stvari, ki jih je Bog z njimi storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Toda vstali so nekateri iz ločine farizejev, ki so verovali, rekoč: »Da jih je treba obrezati in jim naročiti, naj se držijo Mojzesove postave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'In apostoli in starešine so prišli skupaj, da preudarijo o tej besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'In ko je bilo mnogo razpravljanja, je vstal Peter ter jim rekel: »Možje in bratje, vi veste, kako to, da je Bog pred davnim časom naredil med nami izbiro, da naj bi pogani po mojih ustih slišali besedo evangelija in verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'In Bog, ki pozna srca, jim pričuje, ker jim daje Svetega Duha, prav tako kakor je storil nam');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'in ni naredil nobene razlike med nami ter njimi, ko je po veri očistil njihova srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Zakaj torej zdaj skušate Boga, da nadenete na vrat učencev jarem, ki ga niti naši očetje niti mi nismo mogli nositi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Ampak mi verujemo, da bomo rešeni po milosti Gospoda Jezusa Kristusa, prav tako kakor oni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Potem je vsa množica molčala in poslušala Barnaba in Pavla, ki sta razglašala, kakšne čudežne moči in čudeže je po njiju Bog storil med pogani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'In potem, ko so molčali, je Jakob odgovoril, rekoč: »Možje in bratje, prisluhnite mi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simeon je povedal, kako je Bog najprej obiskal pogane, da vzame izmed njih ljudi za svoje ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'In k temu se ujemajo besede prerokov, kakor je pisano:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '›Po tem se bom vrnil in ponovno zgradil Davidovo šotorsko svetišče, ki je padlo in ruševine le-tega bom ponovno zgradil in jaz ga bom ponovno postavil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'da bi lahko preostanek ljudi iskal Gospoda in vsi pogani, nad katere je klicano moje ime, govori Gospod, ki dela vse te stvari.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Bogu so vsa njegova dela znana od začetka sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Zatorej je moja razsodba, da ne vznemirjamo teh, ki so se iz poganstva obrnili k Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'temveč, da jim napišemo, da se vzdržijo pred oskrunitvijo od malikov in pred prešuštvom in pred zadavljenimi stvarmi in pred krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Kajti Mojzes ima od starih časov v vsakem mestu tiste, ki ga oznanjajo, beroč vsak šabatni dan v sinagogah.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tedaj je apostolom in starešinam s celotno cerkvijo to ugajalo, da s Pavlom in Barnabom pošljejo v Antiohijo izbrana moža iz svoje lastne skupine; namreč Juda, imenovanega z vzdevkom Bársaba in Sila, vodilna moža med brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'In po njiju so napisali pisma na ta način: ›Apostoli, starešine in bratje pošiljamo pozdrave bratom, ki so izmed poganov v Antiohiji in Siriji ter Kilikiji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, '§ ker smo slišali, da so vas nekateri, ki so odšli izmed nas, vznemirjali z besedami in spodkopavali vaše duše, rekoč: ›Vi morate biti obrezani in se držati postave,‹ katerim nismo dali nobene takšne zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Nam, ki smo soglasno zbrani, se zdi dobro, da z našima ljubljenima Barnabom in Pavlom pošljemo k vam izbrana moža,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'moža, ki sta svoja življenja tvegala zaradi imena našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Poslali smo torej Juda in Sila, ki vam bosta iste stvari povedala ustno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Kajti Svetemu Duhu in nam se zdi dobro, da vam ne nalagamo večjega bremena kakor te potrebne stvari:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'da se vzdržite pred hrano, darovano malikom in pred krvjo in pred zadavljenimi stvarmi ter pred prešuštvom. Če sebe obvarujete pred njimi, boste storili v redu. Mnogo uspeha.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Torej ko so bili odposlani, so prišli v Antiohijo in ko so skupaj zbrali množico, so izročili poslanico,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'katere so se, zaradi tolažbe, ko so jo brali, razveselili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Juda in Sila, ki sta bila tudi sama preroka, pa sta brate z mnogimi besedami spodbujala in jih krepila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'In potem, ko sta se kratek čas mudila tam, sta od bratov v miru odšla k apostolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '§ Vendar je Sili ugajalo, da še ostane tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Tudi Pavel in Barnaba sta prav tako nadaljevala z mnogimi drugimi v Antiohiji in učila ter oznanjala Gospodovo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Nekaj dni kasneje je Pavel rekel Barnabu: »Pojdiva ponovno in obiščiva naše brate v vsakem mestu, kjer sva oznanjala Gospodovo besedo in poglejva, kako so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'In Barnaba se je odločil, da s seboj vzameta Janeza, katerega vzdevek je bil Marko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Toda Pavlu se ni zdelo dobro z njima vzeti tistega, ki je iz Pamfilije odšel od njiju in z njima ni odšel na delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Spor med njima pa je bil tako oster, da sta se ločila narazen drug od drugega. In tako je Barnaba vzel Marka ter odjadral na Ciper,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Pavel pa je izbral Sila in odšel, od bratov priporočen Božji milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'In odšel je skozi Sirijo in Kilikijo in krepil cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Potem je prišel v Derbe in Listro. In glej, tam je bil nek učenec, po imenu Timótej, sin neke ženske, ki je bila Judinja in je verovala, toda njegov oče je bil Grk,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'ki je bil pri bratih, ki so bili v Listri in Ikóniju, na dobrem glasu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Njega je Pavel hotel vzeti s seboj in vzel ga je ter ga obrezal zaradi Judov, ki so bili v teh četrtih, kajti vsi so vedeli, da je bil njegov oče Grk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'In ko so šli skozi mesta, so jim izročali odloke, da se jih držijo, ki so bili odrejeni od apostolov in starešin, ki so bili v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'In tako so bile cerkve utrjene v veri in so številčno dnevno naraščale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Torej ko so šli skozi Frigijo in področje Galacije in jim je Sveti Duh prepovedal oznanjati besedo v Aziji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, '§ so potem, ko so prišli do Mízije, poskušali iti v Bitinijo, toda Duh jim ni dovolil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'In šli so mimo Mízije in se spustili do Troáde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Ponoči pa se je Pavlu prikazalo videnje: »Tam je stal Makedonec in ga prosil, rekoč: ›Pridi sem v Makedonijo in nam pomagaj.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'In po tem, ko je imel videnje, smo si takoj prizadevali iti v Makedonijo, ker smo brez dvoma sklepali, da nas je poklical Gospod, da jim oznanimo evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Zato smo, ko smo dvignili sidro iz Troáde, prispeli z ravno smerjo v Samotrake in naslednjega dne v Neápolo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'in od tam v Filípe, ki je glavno mesto tega dela Makedonije ter [rimska] kolonija. In v tem mestu smo prebivali nekaj dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'In na šabat smo odšli iz mesta k bregu reke, kjer je bila običajno molitev in se usedli ter govorili ženskam, ki so tja zahajale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'In neka ženska, po imenu Lidija, prodajalka škrlata, iz mesta Tiatira, ki je oboževala Boga, nas je poslušala, katere srce je Gospod odprl, da je prisluhnila besedam, ki jih je govoril Pavel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'In ko je bila krščena ona in njena družina, nas je rotila, rekoč: »Če ste me presodili, da sem zvesta Gospodu, pridite v mojo hišo in ostanite tam.« In primorala nas je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'In pripetilo se je, ko smo šli k molitvi, da nas je srečala neka gospodična, obsedena z duhom vedeževanja, ki je z napovedovanjem usode prinašala veliko dobička svojim gospodarjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ta je sledila Pavlu in nam ter vpila, rekoč: »Ti ljudje so služabniki Boga najvišjega, ki nam kažejo pot rešitve duš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'In to je počela mnogo dni. Toda Pavel se je užaloščen obrnil in duhu rekel: »Zapovedujem ti v imenu Jezusa Kristusa, da prideš iz nje.« In še isto uro je prišel ven.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'In ko so njeni gospodarji videli, da je izginilo upanje na njihov dobiček, so ujeli Pavla in Sila ter ju zvlekli na trg k vladarjem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'in ju privedli k oblastnikom, rekoč: »Ta moža, ki sta Juda, delata našemu mestu silne težave');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, '§ ter učita običaje, ki za nas, ki smo Rimljani, niso zakoniti za sprejetje niti za obeleževanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'In množica je skupaj vstala proti njima in oblastniki so jima raztrgali njuna oblačila ter ukazali naj ju pretepejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'In ko so nanju položili mnogo udarcev z bičem, so ju vrgli v ječo ter ječarju ukazali, naj ju varno straži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Ta ju je, ker je prejel tak ukaz, pahnil v notranjo ječo in njuna stopala pričvrstil v kladi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Ob polnoči pa sta Pavel in Sila molila ter pela hvalnice Bogu, jetniki pa so ju poslušali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'In nenadoma je bil močan potres, tako da so bili zamajani temelji ječe in takoj so se vsa vrata odprla in vezi vseh so bile odvezane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'In čuvaj ječe, ki se je prebudil iz svojega spanja in videl vrata ječe odprta, je izvlekel svoj meč in se hotel ubiti, ker je mislil, da so jetniki pobegnili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Toda Pavel je z močnim glasom zaklical, rekoč: »Ne stôri si ničesar hudega, kajti vsi smo tukaj.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Ta je potem zahteval luč in skočil noter in drhteč prišel ter padel dol pred Pavla in Sila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'in ju privedel ven ter rekel: »Gospoda, kaj moram storiti, da bom rešen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'In onadva sta rekla: »Veruj v Gospoda Jezusa Kristusa in rešen boš ti in tvoja hiša.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'In Gospodovo besedo sta govorila njemu in vsem, ki so bili v njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'In še isto uro noči ju je vzel ter umil njune udarce in nemudoma je bil krščen on in vsi njegovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'In ko ju je privedel v svojo hišo, je pred njiju postavil jed ter se veselil, ker je z vso svojo hišo veroval v Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'In ko je bil dan, so oblastniki poslali narednike, rekoč: »Izpusti tista človeka.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'In čuvaj ječe je te besede povedal Pavlu: »Oblastniki so poslali, naj vaju izpustim. Sedaj torej odidita in pojdita v miru.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Vendar jim je Pavel rekel: »Naju, ki sva Rimljana, so neobsojena javno pretepli in naju vrgli v ječo. In sedaj naju mečejo ven na skrivaj? Ne, resnično, temveč naj sami pridejo in naju spravijo ven.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'In naredniki so te besede povedali oblastnikom in ko so slišali, da sta bila Rimljana, so se zbali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'In prišli so ter ju rotili in ju privedli ven ter od njiju želeli, da odideta iz mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'In odšla sta iz ječe ter vstopila v Lidijino hišo; in ko sta videla brate, sta jih potolažila ter odšla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Torej ko sta šla skozi Amfípolo in Apolonijo sta prišla do Tesaloníke, kjer je bila judovska sinagoga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'In kakor je bila njegova navada, je Pavel vstopil k njim in tri šabatne dneve z njimi razpravljal iz pisem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'razkrival in trdil, da je Kristus brezpogojno moral trpeti in ponovno vstati od mrtvih in da je ta Jezus, ki vam ga oznanjam, Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'In nekateri izmed njih so verovali in se družili s Pavlom in Silom, in velika množica izmed predanih Grkov ter ne malo izmed vodilnih žensk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Toda Judje, ki niso verovali, so prevzeti z zavistjo, vzeli k sebi neke ničvredne pajdaše iz prostaške sorte in zbrali skupino in po vsem mestu zanetili vstajo ter napadli Jazonovo hišo in si prizadevali, da ju privedejo k ljudstvu [dežele].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Ko pa ju niso našli, so Jazona in neke brate odvlekli k vladarjem mesta ter kričali: »Tile, ki so obrnili svet na glavo, so prišli tudi sèm,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'ki jih je sprejel Jazon, in vsi ti delajo nasprotno cesarjevim odlokom, rekoč, da obstaja drug kralj, nek Jezus.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'In vznemirili so množico in mestne vladarje, ko so slišali te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'In ko so od Jazona in od drugih prejeli varščino, so jih izpustili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'In bratje so Pavla ter Sila takoj ponoči odposlali v Berójo. Ko sta prispela tja, sta odšla v judovsko sinagogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ti so bili plemenitejši, kakor tisti v Tesaloníki, ker so z vso prisebnostjo sprejeli besedo in dnevno preiskovali pisma, če so bile te stvari take.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Zato so mnogi izmed njih verovali, tudi častitljive ženske, ki so bile Grkinje in izmed mož ne malo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Toda ko so Judje iz Tesaloníke spoznali, da je Pavel Božjo besedo oznanjal v Beróji, so prišli tudi tja in razvneli množico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'In potem so bratje Pavla takoj odposlali, da gre, kot bi bilo k morju, toda Sila in Timótej sta še vedno ostala tam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'In ti, ki so spremljali Pavla, so ga privedli v Atene in ko so prejeli zapoved za Sila in Timóteja, naj z vso naglico prideta k njemu, so odšli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Torej medtem ko je Pavel v Atenah čakal nanju, je bil njegov duh v njem razvnet, ko je videl mesto v celoti predano malikovanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Zato se je v sinagogi prerekal z Judi in s predanimi osebami in vsakodnevno na trgu s temi, ki so se srečevali z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, '§ Potem so mu ugovarjali neki filozofi izmed epikurejcev in izmed stoikov. In nekateri so rekli: »Kaj hoče povedati ta blebetavec?« Drugi nekako: »Zdi se, da je oznanjevalec tujih bogov,« ker jim je oznanjal Jezusa in vstajenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'In prijeli so ga ter ga privedli na Areopag, rekoč: »Ali lahko izvemo, kakšen je ta novi nauk, o katerem govoriš?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Kajti v naša ušesa prinašaš nekatere čudne besede. Hočemo torej izvedeti, kaj te stvari pomenijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(Kajti vsi Atenci in tujci, ki so bili tam, svojega časa niso porabljali za nič drugega, razen da so ali govorili ali poslušali kako novo stvar.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, '§ Tedaj je Pavel na sredi Marsovega hriba vstal in rekel: » Vi atenski možje, zaznavam, da ste v vseh stvareh preveč vraževerni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Kajti ko sem šel mimo in gledal vaše predmete čaščenja, sem našel oltar s tem napisom: NEPOZNANEMU BOGU. Katerega torej vi nevedno obožujete, tega vam jaz razglašam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bog, ki je naredil svet in vse stvari na njem, glede na to, da je on Gospodar neba in zemlje, ne prebiva v templjih, narejenimi z rokami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'tudi ni oboževan s človeškimi rokami, kakor da karkoli potrebuje, glede na to, da vsem daje življenje in dihanje in vse stvari');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'in je iz ene krvi naredil vse narode ljudi, da prebivajo na vsem obličju zemlje in je vnaprej določil določene čase in meje njihovega prebivanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, '§ da bi iskali Gospoda, če bi ga morda dotipali in ga našli, čeprav ni daleč od vsakega izmed nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Kajti v njem živimo in se gibljemo in obstajamo, kakor so rekli celó nekateri izmed vaših lastnih pesnikov: ›Kajti tudi mi smo njegovo potomstvo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Kot smo torej zagotovo potomstvo Boga, ne bi smeli misliti, da je Božanstvo podobno zlatu ali srebru ali kamnu, vrezanemu od umetnika in [s] človeško pripravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'In nad časi te nevednosti je Bog zamižal, toda sedaj povsod vsem ljudem zapoveduje, da se pokesajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'kajti določil je dan, na katerega bo sodil svet v pravičnosti, po tem možu, ki ga je določil. O tem je dal zagotovilo vsem ljudem, ker ga je obudil od mrtvih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Ko pa so slišali o vstajenju mrtvih, so se nekateri posmehovali, drugi pa so rekli: »Oh tej zadevi te bomo ponovno poslušali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Tako je Pavel odšel izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Vendar so se mu določeni možje trdno pridružili in verovali, med katerimi je bil Dionizij Areopagít in ženska, po imenu Dámaris in drugi z njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Po teh stvareh je Pavel odšel iz Aten in prišel v Korint');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'in našel nekega Juda po imenu Ákvila, rojenega v Pontu, [ki je] s svojo ženo Prískilo nedavno prišel iz Italije; (zato ker je Klavdij vsem Judom ukazal oditi iz Rima) in prišel k njima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'In ker je bil iste obrti, je ostal z njima in delal, kajti po njunem poklicu sta bila izdelovalca šotorov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'In vsak šabat je razpravljal v sinagogi in pregovarjal Jude ter Grke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, '§ In ko sta iz Makedonije prišla Sila in Timótej, je bil Pavel v duhu gnan in Judom pričeval, da Jezus je bil Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'In ko so nasprotovali samim sebi in izrekali bogokletje, je otresel svoje oblačilo ter jim rekel: »Vaša kri naj bo na vaših lastnih glavah. Jaz sem čist. Odslej bom šel k poganom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, '§ In odšel je od tam ter vstopil v hišo nekega moža, po imenu Just, nekoga, ki je oboževal Boga, čigar hiša je bila tik poleg shodnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'In Krisp, glavni predstojnik sinagoge, je z vso svojo hišo veroval v Gospoda in mnogi izmed Korinčanov so ob poslušanju verovali in bili so krščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Potem je ponoči v videnju Pavlu govoril Gospod: »Ne boj se, temveč govori in ne molči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'kajti jaz sem s teboj in nihče se ne bo spravil nadte, da te poškoduje, kajti v tem mestu imam veliko ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'In tam je nadaljeval leto in šest mesecev ter med njimi učil Božjo besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'In ko je bil namestnik Ahaje Galíon, so Judje proti Pavlu soglasno naredili upor in ga privedli k sodnemu stolu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'rekoč: »Ta pregovarja ljudi, da obožujejo Boga v nasprotju s postavo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'In ko je Pavel že skoraj odprl svoja usta, je Galíon rekel Judom: »Če bi bil razlog krivična zadeva ali zlobna nespodobnost, oh vi Judje, bi vas bil voljan prenašati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Toda če je to vprašanje besed in imen in vaše postave, vi glejte na to, kajti v teh zadevah ne bom sodnik.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'In spodil jih je od sodnega stola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Tedaj so vsi Grki prijeli Sosténa, glavnega predstojnika sinagoge in ga pretepli pred sodnim stolom. Galíon pa se ni zmenil za nobeno od teh stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'In Pavel je po tem ostal tam še dolgo časa in se nató poslovil od bratov ter od tam odjadral v Sirijo in z njim Prískila in Ákvila, ko je v Kenhrejah ostrigel svojo glavo, kajti imel je zaobljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'In prišel je v Efez ter ju pustil tam, toda on sam je vstopil v sinagogo in razpravljal z Judi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Ko so ga prosili, da ostane z njimi dlje časa, ni privolil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, '§ temveč se je poslovil, rekoč: »Vsekakor moram ta praznik, ki prihaja, praznovati v Jeruzalemu. Toda ponovno se bom vrnil k vam, če Bog hoče.« In odjadral je iz Efeza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'In ko je pristal v Cezareji in šel gor ter pozdravil cerkev, je odšel dol v Antiohijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'In potem, ko je tam preživel nekaj časa, je odšel in se po vrsti odpravil preko vse dežele Galačanov in Frigije ter krepil vse učence.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'In v Efez je prišel nek Jud, po imenu Apolo, rojen v Aleksandriji, zgovoren človek in mogočen v pismih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ta človek je bil poučen o Gospodovi poti. Ker pa je bil v duhu goreč, je govoril in marljivo učil stvari o Gospodu, poznavajoč samo Janezov krst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'In v sinagogi je začel pogumno govoriti. Ko sta ga Prískila in Ákvila slišala, sta ga vzela k sebi in mu podrobneje pojasnila Božjo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'In ko je bil pripravljen, da odide v Ahajo, so bratje pisali in spodbudili učence, da ga sprejmejo. Ko je prišel, je mnogo pomagal tem, ki so po milosti verovali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'kajti mogočno je prepričeval Jude in to javno in s pismi dokazoval, da je Jezus bil Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'In pripetilo se je, medtem ko je bil Apolo v Korintu, da je Pavel, ko je šel skozi gornje kraje, prišel v Efez. In ko je našel nekatere učence,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'jim je rekel: »Ali ste, odkar ste verovali, prejeli Svetega Duha?« Oni pa so mu rekli: »Mi smo komaj slišali, ali obstaja nek Sveti Duh.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'In rekel jim je: »V kaj ste bili tedaj krščeni?« In rekli so: »Z Janezovim krstom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Potem je Pavel rekel: »Janez je resnično krščeval s krstom kesanja, govoreč ljudem, da naj verujejo v tistega, ki naj bi prišel za njim, to je v Kristusa Jezusa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Ko so to slišali, so bili krščeni v imenu Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'In ko je Pavel nanje položil svoje roke, je prišel nadnje Sveti Duh, in govorili so z jeziki ter prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'In vseh mož je bilo okoli dvanajst.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'In odšel je v sinagogo in približno tri mesece pogumno govoril, razpravljal in prepričeval [o] stvareh glede Božjega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Toda ko so bili številni zakrknjeni in niso verovali, temveč so pred množico o tej poti govorili hudobno, je odšel od njih in oddvojil učence in dnevno razpravljal v šoli nekega Tirána.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'In to se je nadaljevalo približno dve leti, tako da so vsi, ki so prebivali v Aziji, slišali besedo Gospoda Jezusa, tako Judje kakor Grki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'In Bog je po Pavlovih rokah delal posebne čudeže,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'tako da so od njegovega telesa bolnim nosili robce ali predpasnike, in bolezni so odhajale od njih in zli duhovi so izhajali iz njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Takrat so se tudi nekateri potepuški Judje, izganjalci duhov, lotili klicati ime Gospoda Jezusa nad temi, ki so imeli zle duhove, rekoč: »Mi vas zaklinjamo pri Jezusu, ki ga oznanja Pavel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'In bilo je sedem sinov nekega Skevá, Juda in vodilnega izmed duhovnikov, ki so to delali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Zli duh pa je odgovoril in rekel: »Jezusa poznam in Pavla poznam, toda kdo ste vi?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'In človek, v katerem je bil zli duh, je skočil nanje ter jih premagal in prevladal proti njim, tako da so iz te hiše pobegnili nagi in ranjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'In to je postalo znano vsem Judom in Grkom, ki so prav tako prebivali v Efezu in strah se je spustil na vse [izmed] njih in ime Gospoda Jezusa je bilo poveličano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'In mnogi, ki so verovali, so prišli in priznali ter razodeli svoja dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Tudi mnogi izmed teh, ki so uporabljali magijo, so svoje knjige prinesli skupaj in jih sežgali pred vsemi ljudmi, in izračunali so njihovo vrednost ter ugotovili, [da] je petdeset tisoč koščkov srebra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tako je Božja beseda mogočno rasla in prevladala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Ko so bile te stvari končane, se je Pavel v duhu namenil, ko je šel skozi Makedonijo in Ahajo, da gre do Jeruzalema, rekoč: »Potem ko sem bil tukaj, moram videti tudi Rim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Tako je v Makedonijo poslal dva izmed teh, ki so mu služili, Timóteja in Erásta, toda on sam je nekaj časa ostal v Aziji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'In hkrati je tam nastala ne majhna razvnetost glede te poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Kajti nek človek, po imenu Demetrij, srebrar, ki je izdeloval srebrne svetinje za Diano, ki so prinašale rokodelcem ne malo dobička,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'ki jih je skupaj z delavci podobnega poklica sklical in rekel: »Gospodje, vi veste, da imamo od te obrti svoje premoženje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Poleg tega vidite in slišite, da je, ne samo v Efezu, temveč skoraj po vsej celotni Aziji, ta Pavel prepričal in odvrnil mnogo ljudi, govoreč, da niso nikakršni bogovi, ki so narejeni z rokami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'tako da ni samo naša obrt v nevarnosti, da bo zaničevana, temveč, da naj bi bil preziran tudi tempelj velike boginje Diane in uničena naj bi bila njena veličastnost, ki jo obožuje vsa Azija in svet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'In ko so slišali te besede, so bili polni besa in vpili, rekoč: »Velika je Diana Efeška.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'In celotno mesto je bilo napolnjeno z zmešnjavo. In ko so ujeli Gaja in Aristarha, moža iz Makedonije, Pavlova družabnika na potovanju, so z njima soglasno zdrveli v gledališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Ko pa je Pavel hotel vstopiti k ljudstvu [dežele], mu učenci niso dovolili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Nekateri izmed azijskih voditeljev, ki so bili njegovi prijatelji, pa so poslali k njemu ter ga prosili, da sebe v gledališču ne bi izpostavljal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Nekateri so torej vpili eno stvar, nekateri pa drugo, kajti zbor je bil zmeden in večji del ni vedel, zakaj so prišli skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'In iz množice so potegnili Aleksandra, ki so ga Judje porivali naprej. In Aleksander je z roko dal znamenje in želel narediti svoj zagovor pred ljudstvom [dežele].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Vendar ko so spoznali, da je bil Jud, so vsi soglasno približno dve uri vpili: »Velika je Diana Efeška.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'In ko je mestni uradnik pomiril množico, je rekel: » Vi efeški možje, kateri človek tukaj ne ve, kako je mesto Efežanov oboževalec velike boginje Diane in podobe, ki je padla dol iz Jupitra?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Ker pa se torej zoper te stvari ne more govoriti, morate biti mirni in ne storite ničesar prenagljenega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Kajti sèm ste privedli ta moža, ki nista niti roparja cerkvá niti nista bogokletnika vaše boginje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Zatorej, če imajo Demetrij in rokodelci, ki so z njim, besedo proti kateremukoli človeku, je sodišče odprto in tam so namestniki; naj drug drugega tožijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Toda če karkoli povprašujete glede drugih zadev, bo to odločeno na zakonitem zboru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Kajti v nevarnosti smo, da bi bili klicani na zagovor zaradi vstaje tega dne, kajti nobenega razloga ni, s čimer lahko damo obračun tega vrveža.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '§ In ko je to rekel, je razpustil zbor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'In potem, ko je vstaja prenehala, je Pavel k sebi poklical učence ter jih objel in odšel, češ da gre v Makedonijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'In ko je odšel preko teh krajev in jim dal mnogo spodbude, je prišel v Grčijo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'in tam je ostal tri mesece. In ko so Judje prežali nanj, ko je že skoraj odplul v Sirijo, se je namenil vrniti preko Makedonije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, '§ In v Azijo so ga spremljali Sópater iz Beróje; in iz Tesaloníke Aristarh in Sekúndus; in Gaj iz Derbe in Timótej; in iz Azije Tihik in Trofim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ti, ki so šli pred nami, so nas pričakali v Troádi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'In po dneh nekvašenega kruha smo odjadrali iz Filípov in v petih dneh prišli k tem v Troádo, kjer smo ostali sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'In na prvi dan tedna, ko so učenci prišli skupaj k lomljenju kruha, jim je Pavel oznanjal, pripravljen, da jutri odide; in svoj govor nadaljeval do polnoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'V zgornji sobi, kjer so bili skupaj zbrani, pa je bilo mnogo svetilk.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'In na oknu je sedel nek mladenič, po imenu Evtih, ki je padel v globoko spanje. In medtem ko je Pavel dolgo pridigal, se je pogreznil v spanje in padel dol z [najvišjega], tretjega nadstropja in pobran je bil mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'In Pavel je odšel dol, se zgrudil nanj, ga objel ter rekel: »Ne vznemirjajte se, kajti njegovo življenje je v njem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Ko je torej ponovno prišel gor in prelomil kruh in jedel ter še dolgo časa govoril, celó do svita, je tako odšel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'In mladeniča so privedli živega in bili so ne malo potolaženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'In šli smo naprej k ladji in odjadrali do Asosa. Tam smo nameravali sprejeti Pavla, kajti tako je določil, ker je nameraval iti peš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'In ko se je z nami srečal pri Asosu, smo ga sprejeli in prišli v Mitiléno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, '§ In od tam smo odjadrali in naslednji dan prišli nasproti Hiosu. In naslednji dan smo prispeli v Samos in ostali v Trogilu. In naslednji dan smo prišli v Milet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Kajti Pavel se je odločil, da jadra mimo Efeza, ker v Aziji ni želel porabiti časa, kajti hitel je, če bi mu bilo mogoče, da bo na binkoštni dan v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'In iz Mileta je poslal v Efez in poklical starešine cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'In ko so prišli k njemu, jim je rekel: »Od prvega dne, ko sem prišel v Azijo, veste, na kakšen način sem bil z vami v vseh obdobjih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'in služil Gospodu z vso ponižnostjo mišljenja ter z mnogimi solzami in preizkušnjami, ki so me doletele med prežanjem Judov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'in kako nisem ničesar zamolčal, kar vam je bilo koristno, temveč sem vam pokazal in vas javno učil ter od hiše do hiše');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'pričeval obojim, tako Judom kakor tudi Grkom, kesanje pred Bogom in vero v našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'In sedaj glejte, grem v Jeruzalem, zvezan v duhu in ne poznam stvari, ki me bodo tam doletele,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'razen da Sveti Duh v vsakem mestu pričuje, rekoč, da me čakajo vezi in stiske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, '§ Toda nobena od teh besed me ne gane niti ne cenim svojega življenja dragocenega sebi, tako da bom lahko dokončal svoj tek z radostjo in službo, ki sem jo prejel od Gospoda Jezusa, da pričujem evangelij o Božji milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'In sedaj glejte, vem, da vi vsi, med katere sem odšel in oznanjal Božje kraljestvo, ne boste več videli mojega obraza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Zaradi tega vam danes dajem izjavo, da sem čist pred krvjo vseh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Kajti nisem se izogibal, da vam oznanim vso Božjo namero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Zatorej pazite nase in na ves trop, nad katerim vas je Sveti Duh naredil nadzornike, da pasete Božjo cerkev, ki jo je pridobil s svojo lastno krvjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Kajti vem to, da bodo po mojem odhodu vstopili med vas nadležni volkovi, ki ne bodo prizanašali tropu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Prav tako bodo izmed vas vstali možje, ki bodo govorili sprevržene besede, da učence odtegnejo za seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Torej čujte in se spomnite, da v obdobju treh let, ponoči in podnevi, nisem prenehal s solzami vsakogar svariti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'In sedaj, bratje, vas priporočam Bogu in besedi njegove milosti, ki je zmožna, da vas izgradi in da vam da dediščino med vsemi temi, ki so posvečeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Nisem hlepel po nikogaršnjem srebru ali zlatu ali obleki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Da, tudi vi sami veste, da so te roke služile mojim potrebam in tem, ki so bili z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Pokazal sem vam vse stvari, da moramo s takšnim trudom podpirati slabotne in se spominjati besed Gospoda Jezusa, kako je rekel: ›Bolj blagoslovljeno je dajati kakor prejemati.‹ «');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'In ko je tako govoril, je pokleknil in z njimi vsemi molil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'In vsi so bridko jokali in se oklenili Pavlovega vratu ter ga poljubljali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'in žalovali predvsem zaradi vseh besed, ki jih je govoril, da naj ne bi več videli njegovega obraza. In pospremili so ga k ladji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'In pripetilo se je, da potem, ko smo odšli od njih in odrinili, smo z ravno smerjo prispeli na Kos in naslednji dan na Rodos in od tam v Pátaro,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'in ko smo našli ladjo, ki je jadrala preko do Fenikije, smo se vkrcali in odpotovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Torej ko smo odkrili Ciper, smo ga pustili na levi roki in odjadrali v Sirijo ter pristali v Tiru, kajti tam je ladja iztovorila svoj tovor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'In ko smo našli učence, smo tam ostali sedem dni. Ti so Pavlu po Duhu povedali, da naj ne bi šel gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'In ko smo te dneve dovršili, smo se odpravili in odšli [po] naši poti. In na našo pot so nas vsi pospremili z ženami in otroki, dokler nismo bili izven mesta, in pokleknili smo na obali ter molili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'In ko smo se poslovili drug od drugega, smo se odpeljali z ladjo, oni pa so se ponovno vrnili domov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'In ko smo dokončali naše potovanje iz Tira, smo prišli v Ptolemáido in pozdravili brate in en dan ostali z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'In naslednji dan smo mi, ki smo bili iz Pavlove skupine, odšli ter prišli v Cezarejo in vstopili v hišo evangelista Filipa, ki je bil eden izmed sedmih; in ostali z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'In isti mož je imel štiri hčere, device, ki so prerokovale.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'In ko smo se tam mudili mnogo dni, je prišel dol iz Judeje nek prerok, po imenu Agab.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'In ko je prišel k nam, je vzel Pavlov pas ter si zvezal svoje lastne roke in stopala ter rekel: »Tako govori Sveti Duh: ›Tako bodo Judje v Jeruzalemu zvezali moža, ki ima v lasti ta pas in ga izročili v roke poganom.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'In ko smo slišali te stvari, smo ga rotili, tako mi kakor tudi tisti iz tega kraja, naj ne hodi gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Potem je Pavel odgovoril: »Kaj mislite, da jokate in da mi lomite moje srce? Pripravljen sem ne samo biti zvezan, temveč v Jeruzalemu tudi umreti za ime Gospoda Jezusa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'In ko ni želel biti pregovorjen, smo prenehali, rekoč: »Zgôdi se Gospodova volja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'In po teh dneh smo vzeli svojo prtljago in odšli gor v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, '§ Z nami so šli tja tudi nekateri učenci iz Cezareje in s seboj so privedli nekega Mnazona iz Cipra, starega učenca, pri katerem naj bi prenočili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'In ko smo prišli v Jeruzalem, so nas bratje veselo sprejeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'In naslednji dan je Pavel z nami odšel k Jakobu in prisotne so bile vse starešine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'In ko jih je pozdravil, je podrobno pojasnil, kakšne stvari je Bog po njegovi službi storil med pogani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'In ko so to slišali, so slavili Gospoda in mu rekli: »Vidiš, brat, kako mnogo tisočev Judov je tukaj, ki verujejo, in vsi so goreči za postavo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'o tebi pa so obveščeni, da vse Jude, ki so med pogani, učiš, da zapustijo Mojzesa, rekoč, da jim ni treba obrezati njihovih otrok niti živeti po običajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Kaj je to torej? Množica mora brezpogojno priti skupaj, kajti slišali bodo, da si prišel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Pravimo ti, stôri torej tole: ›Imamo štiri može, ki imajo na sebi zaobljubo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'vzemi jih in se z njimi očisti in naj bodo tvoji stroški, da si bodo lahko obrili svoje glave, in vsi bodo lahko spoznali, da te stvari, o katerih so bili glede tebe obveščeni, niso nič, temveč da tudi sam živiš redno in se držiš postave.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, '§ Kar zadeva pogane, ki verujejo, smo pisali in sklenili, da [naj] ne obeležujejo nobene takšne stvari, razen samo, da se varujejo pred stvarmi darovanim malikom in pred krvjo in pred zadavljenim in pred prešuštvom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tedaj je Pavel vzel može in naslednji dan, ko se je očistil, je z njimi vstopil v tempelj, da naznani dovršitev dni očiščevanja, dokler se ne bi za vsakega izmed njih darovala daritev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'In ko se je sedem dni skoraj dokončalo, so Judje, ki so bili iz Azije, ko so ga zagledali v templju, razvneli vso množico in nanj položili roke');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'ter vzklikali: »Možje Izraelci, pomagajte: ›To je človek, ki povsod vse može uči proti ljudem in postavi ter temu kraju, in razen tega je tudi Grke privedel v tempelj in oskrunil ta sveti prostor.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(Kajti prej so v mestu videli z njim Efežana Trofima, za katerega so domnevali, da ga je Pavel privedel v tempelj.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'In vse mesto je bilo razdraženo in ljudje so tekli skupaj in prijeli so Pavla ter ga odvlekli iz templja in nemudoma so bila vrata zaprta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'In medtem ko so ga poskušali ubiti, so prišle k vrhovnemu poveljniku čete novice, da je bil ves Jeruzalem v vstaji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Ki je takoj vzel vojake in stotnike ter stekel dol k njim. In ko so zagledali vrhovnega poveljnika in vojake, so Pavla prenehali pretepati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tedaj se je približal vrhovni poveljnik in ga prijel ter mu ukazal, naj bo zvezan z dvema verigama in zahteval je kdo je bil in kaj je storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'In nekateri so med množico vpili eno stvar, nekateri drugo in ko ni mogel zanesljivo izvedeti gotovosti za hrup, je ukazal, da ga s seboj vzamejo v grad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'In ko je prišel na stopnice, je bilo tako, da so ga zaradi nasilja množice nesli vojaki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Kajti množica ljudi je sledila za njimi in kričala: »Proč z njim.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'In ko naj bi bil Pavel odveden v grad, je vrhovnemu poveljniku rekel: »Ti smem spregovoriti?« Ki je rekel: »Znaš govoriti grško?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Ali nisi ti tisti Egipčan, ki je pred temi dnevi naredil vstajo in v divjino odvedel štiri tisoč mož, ki so bili morilci?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Vendar je Pavel rekel: »Jaz sem človek, ki sem Jud iz Tarza, mesta v Kilikiji, meščan ne nepomembnega mesta, in rotim te, dovoli mi, da spregovorim ljudem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'In ko mu je dal dovoljenje, je Pavel stal na stopnicah in z roko dal znamenje ljudem. In ko je nastala velika tišina, jim je spregovoril v hebrejskem jeziku, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '»Možje, bratje in očetje, poslušajte moj zagovor, ki vam ga sedaj delam.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, '(In ko so slišali, da jim je spregovoril v hebrejskem jeziku, so ohranili še večjo tišino, in on reče):');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '»Jaz sem resnično človek, ki sem Jud, rojen v Tarzu, mestu v Kilikiji, vendar vzgojen v tem mestu pri Gamálielovih stopalih in poučevan glede na popolne običaje postave očetov in bil sem goreč za Boga, kakor ste danes vi vsi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'In to pot sem preganjal do smrti ter zvezoval in izročal v ječe tako moške kakor ženske.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Kakor tudi véliki duhovnik pričuje o meni in vse visoke starešine, od katerih sem prav tako prejel pisma za brate in odšel v Damask, da privedem te, ki so bili tam, zvezane v Jeruzalem, da bi bili kaznovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'In pripetilo se je, da ko sem bil na potovanju in sem okoli poldneva prišel blizu Damaska, je nenadoma okoli mene z neba zasijala močna svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'In padel sem na tla ter zaslišal glas, ki mi je rekel: ›Savel, Savel, zakaj me preganjaš?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, '§ In odgovoril sem: ›Kdo si ti, Gospod?‹ On pa mi je rekel: ›Jaz sem Jezus Nazarečan, ki ga ti preganjaš.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'In tisti, ki so bili z menoj, so zares videli svetlobo in so bili prestrašeni, toda niso slišali glasu tistega, ki mi je govoril.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'In rekel sem: ›Kaj naj storim, Gospod.‹ In Gospod mi je rekel: ›Vstani in pojdi v Damask in tam ti bo povedano o vseh stvareh, ki so ti določene, da jih storiš.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'In ko zaradi slave te svetlobe nisem mogel videti, sem voden za roko teh, ki so bili z menoj, prišel v Damask.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'In nek Hananija, glede na postavo predan mož, na dobrem glasu od vseh Judov, ki so prebivali tam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'je prišel k meni in se ustavil ter mi rekel: ›Brat Savel, prejmi svoj vid.‹ In isto uro sem pogledal nanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'In rekel je: ›Bog naših očetov te je izbral, da bi spoznal njegovo voljo in vidiš tega Pravičnega in da bi slišal glas iz njegovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Kajti ti boš njegova priča vsem ljudem o tem, kar si videl in slišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'In sedaj, zakaj se mudiš? Vstani in bodi krščen in izperi svoje grehe ter kliči Gospodovo ime.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'In pripetilo se je, ko sem ponovno prišel v Jeruzalem, medtem ko sem molil v templju, da sem bil v zamaknjenju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'in videl sem njega, ki mi je rekel: ›Podvizaj se in pojdi hitro iz Jeruzalema, kajti ne bodo sprejeli tvojega pričevanja glede mene.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'In rekel sem: ›Gospod, oni vedo, da sem v vsaki sinagogi zapiral in pretepal te, ki so verovali vate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'in ko je bila prelita kri tvojega mučenca Štefana, sem tudi sam stal poleg in soglašal k njegovi smrti in varoval obleko teh, ki so ga usmrtili.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'In rekel mi je: ›Pojdi, kajti od tod te bom poslal daleč k poganom.‹ «');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'In poslušali so ga do te besede in nato so povzdignili svoje glasove ter rekli: »Proč z zemlje z njim, kajti ne spodobi se, da bi živel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'In ko so zakričali in odvrgli svoja oblačila ter v zrak metali prah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'mu je vrhovni poveljnik velel, naj bo priveden v grad in zaukazal, da naj bi bil zaslišan z bičanjem, da bi lahko izvedel, zakaj so tako vpili zoper njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'In ko so ga zvezali z jermeni, je Pavel rekel stotniku, ki je stal poleg: »Ali je za vas zakonito, da bičate človeka, ki je Rimljan in neobsojen?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Ko je stotnik to slišal, je odšel in povedal vrhovnemu poveljniku, rekoč: »Pazi, kaj delaš, kajti ta človek je Rimljan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Potem je prišel vrhovni poveljnik in mu rekel: »Povej mi, ali si Rimljan?« Rekel je: »Da.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, '§ In vrhovni poveljnik je odgovoril: »Z velikim zneskom sem dosegel to svobodo.« Pavel pa je rekel: »Toda jaz sem bil rojen svoboden.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Potem so nemudoma odstopili od njega ti, ki naj bi ga zaslišali. In tudi vrhovni poveljnik je bil prestrašen, potem ko je izvedel, da je bil Rimljan in ker ga je zvezal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Naslednji dan, ker je hotel zagotovo izvedeti, zakaj je bil obtožen od Judov, ga je odvezal od njegovih jermenov ter visokim duhovnikom in vsemu njihovemu vélikemu zboru ukazal, da se prikažejo in Pavla privedel dol ter ga postavil prednje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'In ko je Pavel iskreno gledal véliki zbor, je rekel: »Možje in bratje, do danes sem živel po vsej dobri vesti pred Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Véliki duhovnik Hananija pa je ukazal tem, ki so stali poleg, da ga udarijo po ustih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Potem mu je Pavel rekel: »Bog bo udaril tebe, ti pobeljeni zid, kajti sediš, da mi sodiš po postavi, velevaš pa, da sem udarjen v nasprotju s postavo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'In ti, ki so stali poleg, so rekli: »Ti zasramuješ Božjega vélikega duhovnika?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Potem je Pavel rekel: »Nisem vedel, bratje, da je véliki duhovnik, kajti pisano je: ›O vladarju svojih ljudi ne boš govoril hudobno.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, '§ Toda ko je Pavel zaznal, da jih je bilo v vélikem zboru en del saducejev, drugi pa farizeji, je v zboru vzkliknil: »Možje in bratje, jaz sem farizej, sin farizeja; zaradi upanja in vstajenja mrtvih sem poklican na zaslišanje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'In ko je tako rekel, je med farizeji in saduceji nastalo nesoglasje, in množica je bila razdeljena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Kajti saduceji pravijo, da ni vstajenja niti angela niti duha, toda farizeji oboje priznavajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, '§ In nastalo je veliko vpitje. In pisarji, ki so bili iz farizejskega dela, so vstali ter se prepirali, rekoč: »Na tem človeku ne najdemo nobenega zla, temveč če mu je govoril duh ali angel, se ne bojujmo proti Bogu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'In ko je nastalo veliko nesoglasje, je vrhovni poveljnik, ker se je bal, da ne bi Pavla raztrgali na koščke, ukazal vojakom, da gredo dol in ga na silo vzamejo izmed njih ter ga privedejo v grad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'In naslednjo noč je poleg njega stal Gospod ter rekel: »Bodi dobre volje, Pavel, kajti kakor si pričeval o meni v Jeruzalemu, tako moraš pričevati tudi v Rimu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'In ko je bil dan, so se nekateri izmed Judov zbrali skupaj ter se pod prekletstvom zavezali, rekoč, da ne bodo niti jedli niti pili, dokler Pavla ne ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'In bilo jih je več kot štirideset, ki so sklenili to zaroto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'In prišli so k visokim duhovnikom in starešinam ter rekli: »Mi smo se pod velikim prekletstvom zavezali, da ne bomo ničesar jedli, dokler Pavla ne umorimo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Zdaj torej z vélikim zborom naznanite vrhovnemu poveljniku, da ga naslednji dan privede dol k vam, kot da glede njega zahtevate nekaj bolj podrobnega, mi pa smo pripravljeni, da ga ubijemo, preden pride blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'In ko je sin Pavlove sestre slišal o njihovem prežanju, je odšel in vstopil v grad ter povedal Pavlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Potem je Pavel k sebi poklical enega izmed stotnikov in rekel: »Spremite tega mladeniča k vrhovnemu poveljniku, kajti povedati mu ima neko stvar.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Tedaj ga je ta vzel in ga spremil k vrhovnemu poveljniku in rekel: »Jetnik Pavel me je poklical k sebi in me prosil, da tega mladeniča spremim k tebi, ki ti ima nekaj povedati.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Potem ga je vrhovni poveljnik prijel za roko in odšel z njim stran na samo ter ga vprašal: »Kaj je to, kar mi imaš povedati?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'In rekel je: »Judje so se strinjali, da od tebe zahtevajo, da jim naslednji dan privedeš Pavla dol v véliki zbor, kakor da bodo od njega zahtevali nekaj bolj podrobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Ampak ne ukloni se jim, kajti nanj preži izmed njih več kot štirideset mož, ki so se s prisego zavezali, da ne bodo niti jedli niti pili, dokler ga ne ubijejo. In sedaj so pripravljeni, ker od tebe pričakujejo obljubo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tako je potem vrhovni poveljnik pustil mladeniču oditi in mu naročil: » Glej, da nobenemu človeku ne poveš, da si mi razodel te besede.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'In k sebi je poklical dva stotnika, rekoč: »Pripravita dvesto vojakov in sedemdeset konjenikov in dvesto suličarjev, da gredo ob tretji nočni uri v Cezarejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'in priskrbite jim živali, da bodo lahko Pavla posadili nanje in ga varno privedite k voditelju Feliksu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'In napisal je pismo na ta način:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '›Klavdij Lizija pošilja pozdrav nadvse odličnemu voditelju Feliksu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tega moža so Judje prijeli in bi ga bili ubili. Potem sem prišel z vojsko in ko sem izvedel, da je bil Rimljan, sem ga rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'In ko sem hotel izvedel razlog, zakaj so ga obtožili, sem ga privedel v njihov véliki zbor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'O njem sem zaznal, da je obtožen vprašanj iz svoje postave, toda k njegovi obtožbi ni položenega ničesar vrednega smrti ali ujetništva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'In ko mi je bilo povedano, kako Judje prežijo na tega človeka, sem ga nemudoma poslal k tebi in tudi njegovim tožnikom sem dal zapoved, da pred teboj povedo, kar so imeli zoper njega. Zbogom.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Potem so vojaki, kakor jim je bilo ukazano, vzeli Pavla in ga ponoči privedli do Antipatríde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Naslednji dan so konjenike pustili, da gredo z njim in se vrnili h gradu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Ki so, ko so prišli v Cezarejo in poslanico izročili voditelju, predenj izročili tudi Pavla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'In ko je voditelj pismo prebral, je vprašal, iz katere province je. In ko je razumel, da je bil iz Kilikije,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'je rekel: »Poslušal te bom, ko pridejo tudi tvoji tožniki.« In ukazal ga je zadržati v Herodovi sodni dvorani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Po petih dneh pa je prišel dol Hananija, véliki duhovnik, s starešinami in z nekim govornikom po imenu Tertúl, ki je voditelja poučil zoper Pavla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'In ko je bil le-ta poklican, ga je Tertúl začel obtoževati, rekoč: »Glede na to, da po tebi uživamo veliko spokojnost in da so po tvoji previdnosti temu narodu storjena zelo plemenita dejanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '§ to priznavamo vedno in na vseh krajih, najplemenitejši Feliks, z vso hvaležnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Vendar da te ne bom še bolj zadrževal, te prosim, da nam po svoji dobrotljivosti prisluhneš nekaj besed.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Kajti tega človeka smo spoznali [za] kužnega in povzročitelja upora med vsemi Judi po vsem svetu in kolovodja ločine Nazarečanov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, '§ ki je poskušal oskruniti tudi tempelj; ki smo prijeli in hoteli soditi glede na našo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, '§ Vendar je nad nas prišel vrhovni poveljnik Lizija in ga z veliko silo odvedel iz naših rok');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, '§ in njegovim tožnikom velel, da pridejo k tebi; s čigar zasliševanjem si boš lahko pridobil spoznanje o vseh teh stvareh, česar ga obtožujemo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'In tudi Judje so soglašali, rekoč, da so bile te stvari takšne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Nató je Pavel, potem ko mu je voditelj dal znamenje, da govori, odgovoril: »Ker vem, da si bil že mnogo let sodnik temu narodu, se še bolj vedro zagovarjam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'zato, da boš lahko razumel, da je šele dvanajst dni, odkar sem odšel gor v Jeruzalem, da bi oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'In niti me niso našli v templju razpravljati s katerimkoli človekom niti podpihovati množice, ne v sinagogah ne v mestu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Niti ne morejo dokazati besed, s katerimi me sedaj obtožujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Toda to ti priznam, da po poti, ki ji pravijo kriva vera, na ta način obožujem Boga svojih očetov in verujem vse stvari, ki so zapisane v postavi in prerokih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'in upanje imam v Boga, ki ga tudi sami dopuščajo, da bo vstajenje mrtvih, tako pravičnih kakor nepravičnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'In v tem sebe vežbam, da imam vest nenehno povsem brez prestopka pred Bogom in pred ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Torej po mnogih letih sem prišel, da svojemu narodu prinesem miloščine in daritve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Nakar so me neki Judje iz Azije našli v templju očiščenega, niti skupaj z množico niti s hrupom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Ki bi morali biti tukaj pred teboj in ugovarjati, če bi imeli karkoli zoper mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Sicer naj ti isti tukaj povedo, če so našli na meni kakršnokoli zlo dejanje, medtem ko sem stal pred vélikim zborom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'razen, če je to zaradi tistega enega glasu, ko sem med njimi stal in vzkliknil: ›Gledé vstajenja mrtvih ste me danes poklicali na zaslišanje.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'In ko je Feliks, ki je imel popolnejše spoznanje o tej poti, slišal te besede, jih je preložil ter rekel: »Ko bo prišel dol vrhovni poveljnik Lizija, bom spoznal vse o vaši zadevi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, '§ In stotniku je ukazal, da varuje Pavla in mu pusti imeti prostost in da naj nikomur od njegovih znancev ne bi prepovedal streči ali priti k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, '§ In po nekaj dneh, ko je prišel Feliks s svojo ženo Druzílo, ki je bila Judinja, je poklical Pavla in ga poslušal glede vere v Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'In ko je razpravljal o pravičnosti, zmernosti in sodbi, ki pride, je Feliks zatrepetal in odgovoril: »Za sedaj pojdi svojo pot. Ko bom imel primeren čas, te bom poklical.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, '§ Upal je tudi, da bi mu bil od Pavla dan denar, da bi ga lahko osvobodil, zaradi česar ga je pogosteje poklical in se posvetoval z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Toda po dveh letih pa je na Feliksovo mesto prišel Porkij Fest. Feliks pa, voljan ustreči Judom, je Pavla pustil zvezanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Torej ko je Fest prišel v provinco, se je po treh dneh povzpel iz Cezareje v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Potem sta ga véliki duhovnik in judovski voditelj poučila zoper Pavla in ga rotila');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'ter zoper njega želela naklonjenosti, da bi ga dal poslati v Jeruzalem, prežeč na poti, da ga ubijejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Toda Fest je odgovoril, da naj bo Pavel čuvan v Cezareji in da bo sam v kratkem odšel tja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '»Naj torej tisti,« je rekel, »ki so med vami zmožni, odidejo z menoj dol in tega moža obtožijo, če je v njem kakršnakoli zlobnost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'In ko se je med njimi mudil več kot deset dni, je odšel dol v Cezarejo; in naslednji dan je sedeč na sodnem stolu zapovedal, naj pripeljejo Pavla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'In ko je ta prišel, so naokoli stali Judje, ki so prišli dol iz Jeruzalema in zoper Pavla vložili mnoge in boleče ovadbe, ki jih niso mogli dokazati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Medtem se je zagovarjal: »Niti zoper judovsko postavo, niti zoper tempelj, niti zoper cesarja nisem čisto nič zagrešil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Toda Fest je, voljan ustreči Judom, Pavlu odgovoril in rekel: »Hočeš iti gor v Jeruzalem in biti tam, pred menoj, sojen o teh stvareh?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Potem je Pavel rekel: »Pred cesarskim sodnim stolom stojim, kjer moram biti sojen. Judom nisem storil nobene krivice, kakor ti zelo dobro veš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Kajti če sem prestopnik ali sem zagrešil karkoli vrednega smrti, se ne branim umreti, toda če ni nobene od teh stvari, za katere me ti tožijo, me noben človek ne more izročiti njim. Na cesarja se sklicujem.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tedaj je Fest, ko se je posvetoval z zborom, odgovoril: »Na cesarja si se skliceval? K cesarju pojdeš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'In po nekaj dneh sta v Cezarejo prišla kralj Agripa in Bereníka, da pozdravita Festa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'In ko sta bila tam mnogo dni, je Fest kralju razodel Pavlovo zadevo, rekoč: »Tukaj je nek mož, ki ga je Feliks pustil v vezeh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'o katerem so me, ko sem bil v Jeruzalemu, visoki duhovniki in judovski starešine obvestili, ker so proti njemu želeli imeti sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Katerim sem odgovoril: ›Rimljani nimajo navade kateregakoli človeka izročiti, da umre, preden se ta, ki je obtožen, ne sooči s tožniki in ima dovoljenje, da se brani glede zločina, vloženega zoper njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Torej ko so prišli sèm, sem brez kakršnegakoli odlašanja naslednji dan sédel na sodni stol in ukazal, da moža privedejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Proti kateremu, ko so tožniki vstali, niso prinesli nobene obtožbe o takšnih stvareh, kakor sem predpostavljal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'temveč so imeli zoper njega neka vprašanja o njihovem lastnem praznoverju in o nekem Jezusu, ki je bil mrtev, o katerem je Pavel trdil, da živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'In ker sem dvomil o takšnem načinu zaslišanj, sem ga vprašal, ali bi odšel v Jeruzalem in bi bil tam sojen o teh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, '§ Toda ko se je Pavel skliceval, da se zadrži za Avgustovo zaslišanje, sem ukazal, da ga stražijo, dokler ga ne pošljem k cesarju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Potem je Agripa rekel Festu: »Tudi sam bi rad slišal tega človeka.« »Naslednji dan,« je rekel, »ga boš slišal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'In naslednji dan, ko sta z velikim pompom prišla Agripa in Bereníka in vstopila na kraj zaslišanja z vrhovnimi poveljniki ter glavnimi možmi mesta, je bil na Festovo zapoved priveden Pavel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'In Fest je rekel: »Kralj Agripa in vsi ljudje, ki ste z nami tukaj prisotni, vidite tega človeka, glede katerega se je vsa množica Judov pogajala z menoj, tako v Jeruzalemu kakor tudi tukaj in kričala, da ne bi smel več živeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Toda ko sem spoznal, da ni zagrešil ničesar vrednega smrti in da se je on sam skliceval na Avgusta, sem določil, da ga pošljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'O katerem ne vem nobene zanesljive stvari, da napišem svojemu gospodu. In zato sem ga privedel pred vas in zlasti predte, oh kralj Agripa, da bi po zaslišanju lahko imel kaj napisati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Kajti zdi se mi nerazumno poslati jetnika in istočasno ne naznaniti zločinov, vloženih zoper njega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Potem je Agripa rekel Pavlu: »Dovoljeno ti je, da se zagovarjaš.« Nató je Pavel iztegnil svojo roko in se zagovarjal:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '»Imam se za srečnega, kralj Agripa, ker se bom danes pred teboj zagovarjal gledé vseh stvari, katere me Judje obtožujejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'še posebej, ker te poznam, da si poznavalec vseh običajev in vprašanj, ki so med Judi, te zaradi tega rotim, da me potrpežljivo poslušaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Moj življenjski slog od moje mladosti, ki je bila najprej med mojim lastnim narodom v Jeruzalemu, poznajo vsi Judje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'ki so me poznali od začetka, če bi [le] želeli pričevati, da sem po najstrožji ločini našega bogoslužja živel kot farizej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'In sedaj stojim in sem sojen zaradi upanja o od Boga dani obljubi našim očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'K tej obljubi se naši dvanajsteri rodovi, ki dan in noč iskreno služijo Bogu, nadejajo, da se uresniči. Zaradi tega upanja, kralj Agripa, sem obtožen od Judov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Zakaj bi vam bila neverjetna misel, da bi Bog obujal mrtve?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Jaz sem sam pri sebi resnično mislil, da moram mnoge stvari narediti nasprotno imenu Jezusa Nazarečana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Kar sem tudi počel v Jeruzalemu. In mnoge izmed svetih sem zapiral v ječo, ker sem prejel oblast od visokih duhovnikov. In ko so jih morili, sem dajal svoj glas zoper nje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'In pogosto sem jih v vsaki sinagogi kaznoval ter jih silil k bogokletju in zoper njih sem bil silno besen. Preganjal sem jih celó v tujih mestih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Nakar, ko sem odšel v Damask, z oblastjo in pooblastilom od visokih duhovnikov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'sem sredi dneva, oh kralj, na poti videl svetlobo z neba, nad sijajem sonca, ki je svetilo naokoli mene in teh, ki so potovali z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'In ko smo vsi popadali na zemljo, sem zaslišal glas, ki mi je spregovoril in v hebrejskem jeziku rekel: ›Savel, Savel, zakaj me preganjaš? Zate je to težko, da se upiraš bodicam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'In rekel sem: ›Kdo si ti, Gospod?‹ In rekel je: ›Jaz sem Jezus, ki ga ti preganjaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Toda vstani in stopi na svoja stopala, kajti prikazal sem se ti zaradi tega namena, da te naredim za služabnika in pričo tako o teh stvareh, ki si jih videl, kakor o teh stvareh, v katerih se ti bom prikazal,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'in te reševal pred ljudmi ter pred pogani, h katerim te sedaj pošiljam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'da odpreš njihove oči in da jih obrneš od teme k svetlobi in od Satanove oblasti k Bogu, da bi lahko prejeli odpuščanje grehov in dediščino med temi, ki so posvečeni po veri, ki je v meni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Nakar, oh kralj Agripa, nisem bil neposlušen nebeškemu videnju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'temveč sem se najprej pokazal tem iz Damaska in v Jeruzalemu in po vseh celotnih krajih Judeje in potem poganom, da bi se pokesali in se obrnili k Bogu in opravljali dela, primerna kesanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Zaradi teh razlogov so me v templju Judje zgrabili in me poskušali ubiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ker sem torej dobil pomoč od Boga, sem nadaljeval do današnjega dne in pričeval tako malim kakor velikim in nisem govoril nobenih drugih besed kakor te, ki so jih govorili preroki in Mojzes, da naj bi se zgodile,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'da naj bi Kristus trpel in da naj bi bil on prvi, ki bi vstal od mrtvih in bi naznanil svetlobo ljudem ter poganom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'In ko se je tako zagovarjal, je Fest z močnim glasom rekel: »Pavel, izgubil si pamet. Mnogo učenja te je naredilo norega.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Vendar je ta odvrnil: »Nisem zmešan, najplemenitejši Fest, temveč govorim besede resnice in treznosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Kajti kralj, pred katerim tudi sam pogumno govorim, ve o teh stvareh, kajti prepričan sem, da nobena teh stvari pred njim ni skrita, kajti ta stvar se ni zgodila v zakotju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Kralj Agripa, verjameš prerokom? Vem, da verjameš.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Potem je Agripa rekel Pavlu: »Skoraj me pregovoriš, da postanem kristjan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'In Pavel je rekel: »Bog daj, da ne bi bil samo ti, temveč tudi vsi, ki so me danes slišali, tako skoraj, kakor povsem tako kakor jaz, toda brez teh vezi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'In ko je tako govoril, so vstali kralj in voditelj in Bereníka in vsi, ki so sedeli z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'In ko so odšli proč, so se med seboj pogovarjali, rekoč: »Ta človek ne dela nič vrednega smrti ali ujetništva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Potem je Agripa rekel Festu: »Tega človeka bi lahko izpustili na prostost, če se ne bi skliceval na cesarja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'In ko je bilo določeno, da naj bi odpluli v Italijo, so Pavla in nekatere druge jetnike izročili nekomu, po imenu Julij, stotniku Avgustove čete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'In ko smo vstopili na ladjo iz Adramítija, smo odrinili ter mislili pluti ob obalah Azije. Z nami je bil neki Aristarh, Makedonec iz Tesaloníke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, '§ In naslednjega dne smo pristali v Sidónu. In Julij je s Pavlom človekoljubno ravnal ter mu dal dovoljenje za odhod na kopno k svojim prijateljem, da se okrepi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'In ko smo od tam odpluli, smo jadrali pod Ciprom, ker so bili vetrovi nasprotni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'In ko smo jadrali prek morja Kilikije in Pamfilije, smo prišli v Miro, mesto v Likiji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'In tam je stotnik našel ladjo iz Aleksandrije, ki je plula v Italijo, in nas vkrcal nanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'In ko smo mnogo dni počasi jadrali in smo komaj prišli nasproti Knidosa in ker nam veter ni dovoljeval, smo jadrali pod Kreto, nasproti Salmone,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'in ko smo jo komaj prešli, smo prišli v kraj, ki se imenuje Dobri pristani; blizu katerega je bilo mesto Lasája.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Torej potem ko je bilo porabljenega mnogo časa in ko je bilo torej jadranje nevarno, ker je post sedaj že minil, jih je Pavel opomnil');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'in jim rekel: »Možje, zaznavam, da bo to potovanje z bolečino in veliko škodo, ne samo za tovor in ladjo, temveč tudi za naša življenja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Vendar je stotnik bolj zaupal gospodarju in lastniku ladje kakor tem besedam, ki so bile spregovorjene po Pavlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'In ker pristanišče ni bilo primerno za prezimovanje, je večina svetovala, da tudi od tam odplujejo, če bi na kakršenkoli način lahko dosegli Fojniks in tam prezimili; ki je pristanišče na Kreti in leži proti jugozahodu in severozahodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'In ko je nežno pihal južni veter, ker so mislili, da so dosegli svoj namen, so od tam dvignili sidro ter jadrali blizu Krete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Toda ne dolgo potem se proti njej dvigne viharen veter, imenovan evrakílon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'In ko je bila ladja ujeta in ni mogla jadrati proti vetru, smo jo pustili peljati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'In ko je drvela pod nekim otokom, ki je bil imenovan Kavda, smo imeli mnogo dela, da zavarujemo čoln.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Ko so ga dvignili, so uporabili pripomočke ter opasali ladjo in ker so se bali, da ne bi nepričakovano nasedli na sipine, so spustili jadra in tako smo bili gnani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'In ker nas je vihar silno premetaval, so naslednji dan razbremenili ladjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'in tretji dan smo z svojimi lastnimi rokami odvrgli ladijsko opremo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'In ko se mnogo dni ni pokazalo niti sonce niti zvezde in je na nas pritiskal ne majhen vihar, je bilo odvzeto vsako upanje, da bi bili rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Toda po dolgi vzdržnosti je Pavel stopil v sredo mednje in rekel: »Možje, morali bi mi prisluhniti in ne odpluti od Krete ter tako ne pridobiti te škode in izgube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'In sedaj vas spodbujam, da bodite dobre volje, kajti med vami ne bo nobene izgube kateregakoli človeškega življenja, razen ladje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Kajti to noč je poleg mene stal angel Boga, čigar sem in ki mu služim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'rekoč: ›Ne boj se, Pavel. Priveden moraš biti pred cesarja in glej, Bog ti je podaril vse te, ki jadrajo s teboj.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'In zato, možje, bodite dobre volje, kajti verjamem Bogu, da bo tako, kakor mi je bilo rečeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Vendar moramo biti vrženi na nek otok.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Toda ko je prišla štirinajsta noč, ko smo bili gnani gor in dol po Adriji, se je okoli polnoči mornarjem zdelo, da so se približali neki deželi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'In izmerili so globino in jo namerili dvajset sežnjev, in ko so se pomaknili malo naprej, so ponovno izmerili in jo namerili petnajst sežnjev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Potem so, ker so se bali, da ne bi padli na skale, s krme vrgli štiri sidra in hrepeneli po dnevu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'In medtem ko so mornarji nameravali pobegniti z ladje, ko so hoteli čoln spustiti v morje, pod krinko, kot da bodo vrgli sidra tudi iz premca,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'je Pavel rekel stotniku in vojakom: »Razen če ti ne ostanejo na ladji, vi ne morete biti rešeni.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Potem so vojaki presekali vrvi čolna in ga pustili pasti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'In medtem ko je prihajal dan, jih je Pavel vse rotil, naj vzamejo hrano, rekoč: »Danes je štirinajsti dan, ko ste čakali in vztrajali ter se postili, ne da bi kaj vzeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Zato vas prosim, da vzamete nekaj hrane, kajti to je za vaše zdravje, kajti nikomur od vas niti las ne bo padel z glave.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'In ko je tako govoril, je vzel kruh in se v prisotnosti vseh zahvalil Bogu; in ko ga je prelomil, je začel jesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Potem so bili vsi dobre volje in so tudi sami vzeli nekaj hrane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Vseh skupaj pa nas je bilo na ladji dvesto šestinsedemdeset duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'In ko so se dovolj najedli, so razbremenili ladjo in v morje vrgli pšenico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'In ko je bil dan, niso poznali kopnine, toda odkrili so nek zaliv z obalo, v katerega bi radi, če bi bilo mogoče, vrinili ladjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'In ko so dvignili sidra, so se predali morju ter odvezali krmilne vrvi in dvignili veliko jadro k vetru ter se usmerili proti obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'In ko je nepričakovano prišla na kraj, kjer sta se stikali dve morji, je ladja nasedla, in sprednji del je trdno obtičal in ostal nepremičen, toda zadnji del je bil zaradi sile valov razbit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'In nasvet vojakov je bil, da pobijejo jetnike, da ne bi kateri od njih odplaval in pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Toda stotnik, voljan rešiti Pavla, je preprečil njihov namen in ukazal, naj se tisti, ki lahko plavajo, najprej vržejo v morje in dosežejo kopno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'ostali pa, nekateri na deskah in nekateri na ladijskih razbitinah. In tako se je zgodilo, da so se vsi varno rešili na kopno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'In ko so bili rešeni, so potem izvedeli, da se otok imenuje Malta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, '§ In barbarsko ljudstvo nam je pokazalo ne malo prijaznosti, kajti prižgali so ogenj in nas zaradi navzočega dežja in zaradi mraza, vse sprejeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'In ko je Pavel nabral sveženj vej in jih položil na ogenj, je zaradi vročine ven prišel gad in se oprijel njegove roke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'In ko so barbari videli strupeno žival viseti na njegovi roki, so med seboj govorili: »Brez dvoma je ta človek morilec, čeprav je ušel morju, ki mu maščevanje vendar ne pusti živeti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'On pa je žival otresel v ogenj in ni čutil nobene škode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Vendar so gledali, ko naj bi imel oteklino ali nenadoma padel mrtev. Toda potem, ko so dolgo časa gledali in so videli, da se mu ni zgodilo nič hudega, so spremenili svoja mišljenja in rekli, da je bil bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'V istih četrtih so bile posesti vodilnega moža otoka, katerega ime je bilo Publij, ki nas je sprejel in nas tri dni prijazno prenočeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Pripetilo pa se je, da je Publijev oče ležal bolan zaradi vročice in zaradi krvave griže; h kateremu je vstopil Pavel in molil ter položil svoji roki nanj in ga ozdravil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Torej ko se je to zgodilo, so prišli tudi drugi, ki so na otoku imeli bolezni in so bili ozdravljeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'ki so nas prav tako počastili z mnogimi častmi. In ko smo odšli, so nas obložili s takšnimi stvarmi, kot je bilo potrebno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, '§ In po treh mesecih smo se vkrcali na ladjo iz Aleksandrije, ki je prezimila na otoku, katere znamenje sta bila Kastor in Poluks.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'In ko smo se izkrcali v Sirakuzi, smo se tam mudili tri dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'In od tam smo šli po ovinkih ter prišli v Région. In po enem dnevu je zapihal južni veter in naslednji dan smo prišli v Putéole,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'kjer smo našli brate in želeli so, da ostanemo z njimi sedem dni; in tako smo odšli proti Rimu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'In ko so bratje slišali o nas, so prišli od tam, da nas srečajo, prav do Apijevega trga in Treh Tavern. Ko jih je Pavel zagledal, se je zahvalil Bogu in se opogumil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, '§ In ko smo prišli v Rim, je stotnik jetnike izročil poveljniku straže, toda Pavlu je bilo dovoljeno, da prebiva sam zase z vojakom, ki ga je varoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'In pripetilo se je, da je po treh dneh Pavel sklical skupaj judovske voditelje in ko so prišli skupaj, jim je rekel: »Možje in bratje, čeprav nisem ničesar zagrešil proti ljudem ali običajem naših očetov, sem bil vendarle jetnik, iz Jeruzalema izročen v roke Rimljanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Ki so me po zaslišanju hoteli izpustiti, ker na meni ni bilo razloga za smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Toda ko so Judje temu ugovarjali, sem se bil primoran sklicevati na cesarja, ne da bi moral obtoževati svoj narod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Zaradi tega razloga sem vas torej dal poklicati, da vas vidim in spregovorim z vami, zato ker sem s to verigo zvezan zaradi Izraelovega upanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'In rekli so mu: »Glede tebe nismo prejeli niti pisem iz Judeje niti nobeden izmed bratov, ki je prišel, [te] ni naznanil ali škodljivo govoril o tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Toda od tebe želimo slišati, kaj misliš; kajti glede te ločine vemo, da ji povsod ugovarjajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'In ko so mu določili dan, so mnogi prišli k njemu v njegovo stanovanje; katerim je od jutra do večera pojasnjeval in dokazoval Božje kraljestvo, jih prepričeval glede Jezusa, tako iz Mojzesove postave kakor iz prerokov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'In nekateri so verjeli besedam, ki so bile govorjene, nekateri pa niso verjeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'In ko se med seboj niso strinjali, so odšli, po tem, ko je Pavel spregovoril eno besedo: »Dobro je Sveti Duh govoril našim očetom po preroku Izaiju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'rekoč: ›Pojdi k tem ljudem in reci: ›S poslušanjem boste slišali, pa ne boste razumeli; in z gledanjem boste videli, pa ne zaznali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'kajti srce teh ljudi je otopelo in njihova ušesa so naglušna in svoje oči so zaprli, da ne bi videli s svojimi očmi in [da ne bi] slišali s svojimi ušesi in [da ne bi] razumeli s svojim srcem in [da ne bi] bili spreobrnjeni in [bi] jih jaz ozdravil.‹‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Bodi vam torej znano, da je Božja rešitev duš poslana k poganom in da jo bodo poslušali.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '§ In ko je rekel te besede, so Judje odšli in med seboj imeli veliko razpravljanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'In Pavel je celi dve leti prebival v lastni najeti hiši in sprejemal vse, ki so prihajali k njemu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'ter z vso samozavestjo oznanjal Božje kraljestvo in učil te stvari, ki se tičejo Gospoda Jezusa Kristusa in noben človek mu ni branil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pavel, služabnik Jezusa Kristusa, poklican, da bi bil apostol, odbran za evangelij Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '(ki ga je vnaprej obljubil po svojih prerokih v svetih pismih),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'glede svojega Sina Jezusa Kristusa, našega Gospoda, ki je glede na meso zrasel iz Davidovega potomca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'in z vstajenjem od mrtvih je, glede na duha svetosti, razglasil, da je Božji Sin z močjo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'po katerem smo zaradi njegovega imena prejeli milost in apostolstvo, za poslušnost veri med vsemi narodi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'med katere ste po Jezusu Kristusu poklicani tudi vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Vsem, ki ste v Rimu, Božji ljubljenci, poklicani, da ste sveti: ›Milost vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Najprej se po Jezusu Kristusu zahvaljujem svojemu Bogu za vas vse, da se o vaši veri govori po vsem celotnem svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Kajti Bog je moja priča, ki mu služim s svojim duhom v evangeliju njegovega Sina, da vas brez prenehanja vedno omenjam v svojih molitvah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, '§ ker prosim, če bi na kakršenkoli način torej končno lahko imel uspešno potovanje, da po Božji volji pridem k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Kajti hrepenim, da vas vidim, da bi vam lahko posredoval kak duhoven dar, z namenom, da boste lahko utrjeni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'to je, da bom lahko skupaj z vami potolažen po vzajemni veri, tako vaši kakor moji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Torej, nočem, da bi bili nepoučeni, bratje, da sem se pogosto namenil priti k vam (toda doslej sem bil zadržan), da bi lahko imel, kakor med drugimi pogani, nekaj sadu tudi med vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Dolžnik sem, tako Grkom kakor barbarom, tako modrim, kakor ne modrim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Torej, kar se mene tiče, sem pripravljen evangelij oznaniti tudi vam, ki ste v Rimu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Kajti ne sramujem se Kristusovega evangelija, kajti ta je Božja moč za rešitev duš vsakemu, ki veruje; najprej Judu in tudi Grku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Kajti v njem se razodeva Božja pravičnost, iz vere v vero, kakor je pisano: ›Pravični bo živel iz vere.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, '§ Kajti Božji bes je razodet iz nebes zoper vso brezbožnost in nepravičnost ljudi, ki resnico zadržujejo v nepravičnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'zato ker je to, kar je lahko spoznano od Boga, očitno v njih; kajti Bog jim je to pokazal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Kajti od stvarjenja sveta so nevidne stvari o njem jasno vidne, ker so razumljene po stvareh, ki so narejene; celó njegova večna moč in Božanstvo, tako da so brez opravičila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Zato ker ko so spoznali Boga, ga niso slavili kakor Boga niti niso bili hvaležni, temveč so v svojih zamislih postali prazni in njihovo nespametno srce je otemnelo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Ker so o sebi izpovedovali, da so modri, so postali bedaki');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'in slavo netrohljivega Boga spremenili v podobo, podobno trohljivemu človeku in pticam in štirinožnim živalim in plazečim stvarem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Zato jih je tudi Bog, zaradi poželenj njihovih lastnih src, prepustil nečistosti, da med seboj onečaščajo svoja lastna telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, '§ Ki so Božjo resnico zamenjali v laž in so bolj oboževali in služili stvarstvu kakor Stvarniku, ki je blagoslovljen na veke. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Zaradi tega razloga jih je Bog prepustil ogabnim strastem; kajti celó njihove ženske so spremenile naravno uporabo v to, kar je protinaravno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'In prav tako so tudi moški, ki so opustili naravno uporabo ženske, v svojem poželenju goreli eden k drugemu; moški so z moškimi počenjali to, kar je nespodobno in na sebi prejemali to povračilo svoje zablode, ki je bilo primerno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'In celó kot v svojem spoznanju niso želeli obdržati Boga, jih je Bog izročil pokvarjenemu umu, da počenjajo te stvari, ki niso primerne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, '§ Izpolnjeni so z vso nepravičnostjo, prešuštvom, zlobnostjo, pohlepnostjo, zlonamernostjo; polni zavisti, umora, razpravljanja, prevar, pogubnosti; opravljivci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'obrekovalci, sovražniki Boga, kruti, ponosni, bahači, izmišljevalci hudobnih stvari, neposlušni staršem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, '§ brez razumevanja, lomilci zavez, brez naravne naklonjenosti, nespravljivi, neusmiljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Ki poznajo Božje sodbe, da so tisti, ki zagrešijo takšne stvari, vredni smrti, ne samo, da to počenjajo, temveč imajo zadovoljstvo v tistih, ki jih počno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Torej si neopravičljiv, oh človek, kdorkoli si, ki sodiš; kajti v čemer sodiš drugega, obsojaš sebe; kajti ti, ki sodiš, počneš iste stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Toda mi smo prepričani, da je Božja sodba, glede na resnico, zoper te, ki izvajajo takšne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'In mar misliš ti, oh človek, ki sodiš tiste, ki takšne stvari počno in delaš isto, da boš ubežal Božji sodbi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ali preziraš bogastva njegove dobrote in prizanašanja in potrpežljivosti, ne vedoč, da te Božja dobrota vodi h kesanju?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Toda po svojem brezčutnem in zakrknjenem srcu si nabiraš bes za dan besa in razodetja pravične Božje sodbe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'ki bo vsakemu človeku povrnil glede na njegova dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Večno življenje tem, ki si s potrpežljivim vztrajanjem v dobrem ravnanju prizadevajo za slavo in čast in nesmrtnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'toda tistim, ki so prepirljivi in ne ubogajo resnice, temveč ubogajo nepravičnost, ogorčenost in bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Stiska in tesnoba nad vsako dušo človeka, ki počne zlo, najprej judovsko in prav tako pogansko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'toda slava, čast in mir vsakemu človeku, ki dela dobro, najprej Judu in tudi poganu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'kajti pri Bogu ni oziranja na osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Kajti kolikor jih je grešilo brez postave, bodo tudi propadli brez postave; in kolikor jih je grešilo v postavi, bodo sojeni po postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Kajti pred Bogom niso pravični poslušalci postave, temveč bodo opravičeni uresničevalci postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Kajti kadar pogani, ki nimajo postave, po naravi delajo stvari, ki so vsebovane v postavi, so tisti, ki nimajo postave, samim sebi postava;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'ki kažejo delo postave, zapisano v njihovih srcih in tudi njihova vest pričuje in njihove misli se medtem obtožujejo ali pa opravičujejo druga drugo),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'na dan, ko bo Bog po Jezusu Kristusu sodil skrivnosti ljudi, glede na moj evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Glej, imenuješ se Jud in počivaš na postavi in se bahaš z Bogom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'in poznaš njegovo voljo in ker si poučen iz postave, odobravaš stvari, ki so odličnejše;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'in si prepričan, da si ti sam vodnik slepim, svetloba tem, ki so v temi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'inštruktor nespametnih, učitelj otročičev, ki imaš v postavi obrazec spoznanja in resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Ti torej, ki poučuješ drugega, samega sebe [pa] ne poučiš? Ti, ki oznanjaš naj človek ne krade, [pa] kradeš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Ti, ki praviš, naj človek ne stori zakonolomstva, [pa] storiš zakonolomstvo? Ti, ki preziraš malike, [pa] storiš svetoskrunstvo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Ti, ki se bahaš s postavo, [pa] zaradi prelamljanja postave onečaščaš Boga?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Kajti zaradi vas se med pogani izreka bogokletje proti Božjemu imenu, kakor je pisano.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Kajti obreza resnično koristi, če se držiš postave; toda če si lomilec postave, je tvoja obreza postala neobreza.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Torej, če se neobrezani drži pravičnosti postave, mar ne bo njegova neobreza šteta za obrezo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'In ali ne bo neobrezani, ki je po naravi, če izpolnjuje postavo, sodil tebe, ki po črki in obrezi prestopaš postavo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Kajti ni Jud tisti, ki je tak na zunaj; niti ni obreza ta, ki je zunanja, v mesu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'toda Jud je tisti, ki je tak navznoter; in obreza je ta od srca, v duhu in ne po črki; katerega hvala ni od ljudi, temveč od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Kakšno prednost ima potem Jud? Ali kakšna korist je od obreze?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Velika, [v] vsakem pogledu, predvsem, ker so bili Božji izreki zaupani njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, '§ Kajti kaj, če nekateri niso verovali? Mar bo njihova nevera naredila Božjo vero brez učinka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Bog ne daj; da, naj bo Bog resničen, toda vsak človek lažnivec, kakor je pisano: ›Da boš lahko opravičen po svojih besedah in lahko zmagaš, kadar si sojen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Toda če naša nepravičnost razkriva Božjo pravičnost, kaj bomo rekli? Ali je Bog, ki se maščuje, nepravičen? (Govorim kakor človek),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Bog ne daj; kajti kako bo potem Bog sodil svet?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Kajti če je Božja resnica zaradi moje laži v njegovo slavo bolj obilna; zakaj sem tudi jaz še vedno sojen kakor grešnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'In ne raje (kot smo obrekljivo prikazani in kot nekateri zatrjujejo, da pravimo): ›Delajmo zlo, da lahko pride dobro?‹ katerih obsodba je pravična.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Kaj torej? Ali smo mi boljši kakor oni? Ne, nikakor ne, kajti prej smo tako Judom kakor poganom dokazali, da so vsi pod grehom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'kakor je pisano: ›Nobenega pravičnega ni, ne, niti enega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Nobenega ni, ki razume, nobenega ni, ki išče Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Vsi so odšli proč s poti, skupaj so postali nekoristni; nobenega ni, ki dela dobro, ne, niti enega ni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Njihovo grlo je odprt mavzolej; s svojimi jeziki so uporabljali prevaro; strup kober je pod njihovimi ustnicami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'katerih usta so polna preklinjanja in grenkobe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'njihova stopala so hitra, da prelijejo kri;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'uničenje in beda sta na njihovih poteh;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'in poti miru niso spoznali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'pred njihovimi očmi ni strahu Božjega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Torej mi vemo, da katerekoli besede govori postava, govori tistim, ki so pod postavo, da se vsaka usta lahko zamaše in ves svet lahko postane kriv pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Torej po dejanjih postave v njegovem pogledu ne bo opravičeno nobeno meso, kajti spoznanje greha je po postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Toda sedaj je jasno pokazana Božja pravičnost brez postave, ker je izpričana po postavi in prerokih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'celó Božja pravičnost, ki je po veri Jezusa Kristusa vsem in nad vsemi temi, ki verujejo; kajti nobene razlike ni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'kajti vsi so grešili in niso dosegli Božje slave;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'opravičeni pa so zastonj, po njegovi milosti prek odkupitve, ki je v Kristusu Jezusu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'ki ga je Bog postavil, da postane spravna daritev po veri v njegovo kri, da po Božji prizanesljivosti oznani svojo pravičnost za odpuščanje grehov, ki so minuli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'da oznani, pravim, ob tem času svojo pravičnost; da je lahko sam pravičen in opravičevalec tistega, ki veruje v Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kje je torej bahanje? Izključeno je. Po kakšni postavi? Po delih? Ne, temveč po postavi vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Torej sklenemo, da je človek opravičen po veri, brez del postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ali je on samo Bog Judov? Ali ne tudi poganov? Da, tudi poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Ker je resnično en Bog, ki bo obrezo opravičil po veri in neobrezo preko vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Ali mi potem preko vere postavo razveljavljamo? Bog ne daj; da, mi utrjujemo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Kaj bomo torej rekli, da je našel Abraham, naš oče, kar se nanaša na meso?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Kajti če bi bil Abraham opravičen po delih, bi se imel s čim ponašati; toda ne pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Kajti kaj pravi pismo? Abraham je verjel Bogu in to mu je bilo šteto za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Torej tistemu, ki dela, nagrada ni šteta po milosti, temveč po dolgu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Toda tistemu, ki ne dela, temveč veruje v tistega, ki opravičuje brezbožnega, je njegova vera šteta za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Celo kakor tudi David opisuje blaženost človeka, ki mu Bog pripisuje pravičnost brez del,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'rekoč: ›Blagoslovljeni so tisti, katerih krivičnosti so odpuščene in katerih grehi so pokriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Blagoslovljen je človek, ki mu Gospod ne bo pripisal greha.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Prihaja potem ta blaženost samo na obrezo ali tudi na neobrezo? Kajti pravimo, da je bila vera Abrahamu šteta za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kako je bila potem šteta? Ko je bil v obrezi ali v neobrezi? Ne v obrezi, temveč [ko je bil] v neobrezi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'In ko je bil še neobrezan, je prejel znamenje obreze, pečat pravičnosti vere, ki jo je imel, da bi bil lahko oče vseh teh, ki verujejo, čeprav niso obrezani, da bi bila lahko tudi njim pripisana pravičnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'in oče obrezanih, teh, ki niso samo iz obreze, temveč ki tudi hodijo po stopinjah tiste vere našega očeta Abrahama, ki jo je imel, ko je bil še neobrezan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, '§ Kajti obljuba, da naj bi bil dedič sveta, ni bila [dana] Abrahamu ali njegovemu semenu preko postave, temveč preko pravičnosti iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Kajti če bodo dediči tisti, ki so iz postave, je vera ničeva in obljuba brez učinka;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'zato ker postava povzroča bes; kajti kjer ni nobene postave, tam ni prestopka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Torej je to iz vere, da bi bilo lahko po milosti; z namenom, da bi bila obljuba lahko zanesljiva vsemu semenu; ne samo temu, ki je iz postave, temveč tudi temu, ki je iz Abrahamove vere, ki je oče nas vseh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(kakor je pisano: ›Naredil sem te za očeta mnogih narodov‹) pred njim, ki mu je veroval, celó [pred] Bogom, ki oživlja mrtve in kliče te stvari, ki niso, kakor da bi bile.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Ki je proti upanju veroval v upanje, da bi lahko postal oče mnogih narodov; glede na to, kar je bilo spregovorjeno: ›Takšno bo tvoje seme.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'In ker ni bil slaboten v veri, ko je bil star okoli sto let, svojega lastnega telesa torej ni imel za mrtvega niti ne še omrtvelost Sarine maternice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Ob Božji obljubi ni okleval zaradi nevere, temveč je bil močan v veri in dal slavo Bogu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'in je bil popolnoma prepričan, da kar je on obljubil, je zmožen tudi izpolniti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Zato mu je bilo to šteto za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Torej, da mu je bilo šteto, to ni bilo napisano samo zaradi njega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, '§ temveč tudi zaradi nas, ki nam bo šteto, če verujemo v tistega, ki je obudil našega Gospoda Jezusa od mrtvih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'ki je bil izročen zaradi naših prestopkov in je bil ponovno obujen zaradi našega opravičenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Torej, ker smo opravičeni iz vere, imamo po našem Gospodu Jezusu Kristusu z Bogom mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Po njem imamo tudi po veri dostop v to milost, v kateri stojimo in se veselimo v upanju Božje slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'In ne samo to, temveč se ponašamo tudi s stiskami, ker vemo, da stiska dela potrpežljivost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'in potrpežljivost preizkušenost, in preizkušenost upanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'upanje pa ne sramotí, ker je Božja ljubezen prelita v naša srca po Svetem Duhu, ki nam je dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Kajti ko smo bili še brez moči, je Kristus ob primernem času umrl za brezbožne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Kajti komaj bi nekdo umrl za pravičnega človeka, čeprav bi si morda nekdo celó upal umreti za dobrega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Toda Bog izkazuje svojo ljubezen do nas v tem, da je Kristus umrl za nas, medtem ko smo bili še grešniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Toliko bolj bomo potem po njem rešeni pred besom, ker smo sedaj opravičeni po njegovi krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Kajti če smo bili s smrtjo njegovega Sina pobotani k Bogu, ko smo bili sovražniki, bomo toliko bolj, ker smo pobotani, po njegovem življenju rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'In ne samo tako, temveč se tudi veselimo v Bogu po svojem Gospodu Jezusu Kristusu, po katerem smo sedaj prejeli spravo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Zatorej, kakor je po enem človeku na svet vstopil greh in po grehu smrt; in je tako smrt prešla na vse ljudi, ker so vsi grešili;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '(kajti do postave je bil na svetu greh, toda greh ni pripisan v času, ko ni postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Vendar je od Adama do Mojzesa kraljevala smrt, celó nad temi, ki niso grešili po podobnosti Adamovega prestopka, ki je podoba tega, ki je imel priti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Toda z zastonjskim darom ni tako kakor s pregreho. Kajti če so po prestopku enega mnogi mrtvi, sta toliko bolj Božja milost in darilo po milosti, ki je po enem človeku, Jezusu Kristusu, mnoge obogatila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'In z darom ni tako kakor je bilo s tistim, ki je grešil. Kajti sodba je bila po enem v obsodbo, toda zastonjski dar je od mnogih prestopkov k opravičenju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Kajti če je po prestopku enega človeka zakraljevala smrt, bodo toliko bolj tisti, ki prejemajo obilje milosti in od daru pravičnosti, v življenju kraljevali po enem, Jezusu Kristusu.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Torej kakor je prišla po prestopku enega sodba nad vse ljudi v obsodbo, točno tako je prišel po pravičnosti enega zastonjski dar nad vse ljudi v opravičenje življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Kajti kakor so po neposlušnosti enega človeka mnogi postali grešniki, tako bodo po poslušnosti enega mnogi postali pravični.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Poleg tega je postava vstopila, da bi bil prestopek lahko obilen. Toda kjer je greh obilen, je milost storila veliko več obilja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'da kakor je greh kraljeval za smrt, točno tako lahko milost kraljuje po pravičnosti za večno življenje po Jezusu Kristusu, našem Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Kaj bomo potem rekli? Ali bomo nadaljevali v grehu, da bo milost lahko obilna?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Bog ne daj. Kako bomo mi, ki smo mrtvi grehu, še živeli v njem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ali ne veste, da tako mnogi izmed nas, ki smo bili krščeni v Jezusa Kristusa, smo bili krščeni v njegovo smrt?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Torej smo s krstom z njim pokopani v smrt, da naj bi podobno kakor je bil Kristus obujen od mrtvih po Očetovi slavi, točno tako tudi mi hodili v novosti življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Kajti če smo bili skupaj posajeni v podobnost njegove smrti, bomo tudi v podobnost njegovega vstajenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'ker vemo to, da je naš stari človek križan z njim, da bi bilo telo greha lahko uničeno, da naj odslej ne bi več služili grehu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Kajti kdor je mrtev, je osvobojen pred grehom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Torej, če smo s Kristusom mrtvi, verujemo, da bomo z njim tudi živeli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'vedoč, da Kristus, ko je bil obujen od mrtvih, nič več ne umira; nad njim smrt nima več gospostva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, '§ Kajti kdor je umrl, je enkrat umrl grehu, toda kdor živi, živi Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, '§ Prav tako tudi sebe štejte za zares mrtve grehu, toda žive za Boga, po Jezusu Kristusu, našem Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Ne dopustite, da torej greh kraljuje v vašem umrljivem telesu, da bi ga morali ubogati v njegovih poželenjih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Niti ne dajajte svojih udov grehu, kot orodja krivičnosti, temveč dajte sebe Bogu, kakor tisti, ki so od mrtvih živi in svoje ude kot orodja pravičnosti Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Kajti greh nad vami ne bo imel gospostva; kajti niste pod postavo, temveč pod milostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Kaj torej? Mar bomo grešili, ker nismo pod postavo, temveč pod milostjo? Bog ne daj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ali ne veste, da komur same sebe dajete [za] služabnike v pokorščino, ste njegovi služabniki, komur se pokoravate; bodisi grehu v smrt ali poslušnosti v pravičnost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Toda hvala Bogu, da ste bili služabniki grehu, vendar ste iz srca ubogali to obliko nauka, ki vam je bil izročen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Ko ste bili torej osvobojeni greha, ste postali služabniki pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Zaradi šibkosti vašega mesa govorim po običaju ljudi; kajti kakor ste svoje služabniške ude dali nečistosti in krivičnosti za krivičnost; točno tako dajte sedaj svoje služabniške ude pravičnosti za svetost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, '§ Kajti ko ste bili služabniki grehu, ste bili svobodni, [prosti] pred pravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Kakšen sad ste takrat imeli v tistih stvareh, ki se jih sedaj sramujete? Kajti konec tistih stvari je smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Toda sedaj, ko ste osvobojeni greha in ste postali služabniki Bogu, imate svoj sad v svetost in konec večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Kajti plačila za greh so smrt; toda Božji dar je večno življenje po Jezusu Kristusu, našem Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ali ne veste, bratje (kajti govorim tem, ki poznajo postavo), da ima postava gospostvo nad človekom, dokler on živi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Kajti ženska, ki ima soproga, je po postavi vezana k svojemu soprogu, dokler ta živi; toda če soprog umre, je odvezana od postave svojega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Torej če bo poročena k drugemu moškemu, medtem ko njen soprog živi, bo zaradi tega imenovana zakonolomka; toda če je njen soprog mrtev, je osvobojena te postave, tako da ni zakonolomka, čeprav je poročena k drugemu moškemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tako, moji bratje, ste tudi vi po Kristusovem telesu postali mrtvi postavi, da bi bili poročeni k drugemu, celó k njemu, ki je obujen od mrtvih, da naj bi obrodili sad za Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Kajti ko smo bili v mesu, so v naših udih delovale spodbude grehov, ki so bili po postavi, da obrodijo sad za smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Toda sedaj smo osvobojeni postave, da bi mrtvi [postavi], pod katero smo bili držani, služili v novosti duha, ne pa v starosti črke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Kaj bomo torej rekli? Ali je postava greh? Bog ne daj. Ne, nisem spoznal greha, razen po postavi; kajti ne bi spoznal poželenja, razen če postava ne bi rekla: ›Ne boš požêlel.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Toda greh, ki [si] po zapovedi jemlje priložnost, je v meni oblikoval vse vrste poželjivosti. Kajti brez postave je bil greh mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Kajti nekoč sem bil živ brez postave; toda ko je prišla zapoved, je greh oživel, jaz pa sem umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'In zapoved, ki je bila odrejena za življenje, sem spoznal, da je za smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Kajti greh, ki [si] jemlje priložnost po zapovedi, me je zavedel in me po njej usmrtil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Torej je postava svéta in zapoved svéta in pravična ter dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Mi je potem to, kar je dobro, storilo smrt? Bog ne daj. Toda greh, da bi se lahko pokazal greh, dela s tem, kar je dobro, v meni smrt; ta greh utegne postati prek zapovedi silno grešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Kajti vemo, da je postava duhovna, toda jaz sem mesen, prodan pod greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Kajti tega, kar delam, ne dopuščam; kajti kar bi želel, tega ne delam, temveč počenjam to, kar sovražim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Če torej počenjam to, česar nočem, soglašam k postavi, da je ta dobra.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Torej potem nisem več jaz, ki to počnem, temveč greh, ki prebiva v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Kajti vem, da v meni (to je, v mojem mesu) ne prebiva nobena dobra stvar; kajti hoteti je z menoj pri roki, toda ne najdem tega, kako izvesti to, kar je dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Kajti dobrega, ki ga hočem, ne delam, temveč zlo, ki ga nočem, to počnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Torej če delam to, česar nočem, to nisem več jaz, ki to počnem, temveč greh, ki prebiva v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Odkril sem torej postavo, da ko sem hotel delati dobro, je z menoj prisotno zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Kajti po notranjem človeku se veselim v Božji postavi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'toda v svojih udih vidim drugo postavo, ki se bori proti postavi mojega uma in me prinaša v sužnost postavi greha, ki je v mojih udih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Oh pomilovanja vreden človek sem! Kdo me bo osvobodil iz telesa te smrti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Zahvaljujem se Bogu po Jezusu Kristusu, našem Gospodu. Tako potem z umom služim Božji postavi, toda z mesom postavi greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, '§ Torej sedaj ni nobene obsodbe tem, ki so v Kristusu Jezusu, ki ne živijo po mesu, temveč po Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Kajti postava Duha življenja v Kristusu Jezusu me je osvobodila postave greha in smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Kajti česar postava ni mogla storiti, ker je bila slabotna po mesu, je [storil] Bog, ki je poslal svojega lastnega Sina v podobnosti grešnega mesa in za greh [in] obsodil greh v mesu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'da bi se lahko dopolnila pravičnost postave v nas, ki ne živimo po mesu, temveč po Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Kajti tisti, ki so po mesu, razmišljajo mesene stvari; toda tisti, ki so po Duhu, stvari od Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Kajti biti mesenega mišljenja je smrt; toda biti duhovnega mišljenja je življenje in mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Ker je meseno mišljenje sovraštvo zoper Boga; kajti to ni podrejeno Božji postavi niti zares ne more biti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Zaradi tega tisti, ki so v mesu, ne morejo ugajati Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Toda vi niste v mesu, temveč v Duhu, če je tako, da v vas prebiva Božji Duh. Torej, če katerikoli človek nima Kristusovega Duha, ni njegov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'In če je Kristus v vas, je telo mrtvo zaradi greha; toda Duh je življenje zaradi pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Toda če v vas prebiva Duh tistega, ki je Jezusa obudil od mrtvih, bo tisti, ki je po svojem Duhu, ki prebiva v vas, obudil Kristusa od mrtvih, tudi oživil vaša umrljiva telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Torej bratje, mi smo dolžniki, [vendar] ne mesu, da bi živeli po mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Kajti če živite po mesu, boste umrli, toda če po Duhu morite dejanja telesa, boste živeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Kajti kolikor jih je vodeno po Božjem Duhu, so Božji sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Kajti niste ponovno prejeli duha suženjstva za strah, temveč ste prejeli Duha posvojitve, s katerim kličemo: »Aba, Oče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Sam Duh z našim duhom prinaša pričevanje, da smo Božji otroci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'In če smo otroci, potem smo dediči; Božji dediči in sodediči s Kristusom, če je tako, da z njim trpimo, da bomo lahko tudi skupaj proslavljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Kajti menim, da trpljenja tega sedanjega časa niso vredna, da se primerjajo s slavo, ki se bo razodela v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Kajti iskreno pričakovanje stvarstva pričakuje manifestacijo Božjih sinov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Kajti stvarstvo je bilo podvrženo ničevosti, ne voljno, temveč zaradi njega, ki si je le-to podvrgel v upanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'ker bo tudi stvarstvo samo rešeno iz suženjstva trohnenja v veličastno svobodo Božjih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Kajti vemo, da celotno stvarstvo do zdaj skupaj stoka in se muči v bolečini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Pa ne samo oni, temveč tudi mi, ki imamo prve sadove Duha, celo mi sami v sebi stokamo in čakamo na posvojitev, to je, odkupitev našega telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Kajti rešeni smo po upanju; toda upanje, ki je videno, ni upanje; kajti kar človek vidi, čemu potem še upa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Toda če upamo na to, česar ne vidimo, potem to pričakujemo s potrpežljivostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Prav tako tudi Duh pomaga našim slabotnostim; kajti ne vemo, za kaj naj bi molili, kot bi morali, toda sam Duh posreduje za nas s stoki, ki ne morejo biti izrečeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'In tisti, ki preiskuje srca, ve, kakšno je mišljenje Duha, ker on posreduje za svete glede na Božjo voljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'In mi vemo, da vse stvari skupaj delajo v dobro tem, ki ljubijo Boga, tem, ki so poklicani glede na njegov namen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Kajti katere je vnaprej poznal, je prav tako vnaprej določil, da bodo skladni podobi njegovega Sina, da bi bil ta lahko prvorojenec med mnogimi brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Poleg tega, katere je vnaprej določil, jih je tudi poklical; in katere je poklical, te je tudi opravičil; in katere je opravičil, te je tudi proslavil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Kaj bomo potem rekli k tem stvarem? Če je Bog za nas, kdo je lahko zoper nas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'On, ki ni prizanesel svojemu lastnemu sinu, temveč ga je izročil za nas vse, kako nam ne bo z njim velikodušno dal tudi vseh stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kdo bo karkoli položil k obtožbi Božjih izvoljencev? Bog je, ki opravičuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kdo je, kdor obsoja? To je Kristus, ki je umrl, da, bolje rečeno, ki je bil obujen, ki je celó na Božji desnici, ki prav tako posreduje za nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kdo nas bo ločil od Kristusove ljubezni? Nas bo tegoba ali nesreča ali preganjanje ali lakota ali nagota ali nevarnost ali meč?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Kakor je pisano: ›Kajti zaradi tebe smo ves dan pobijani, imajo nas kakor ovce za klanje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, '§ Ne, v vseh teh stvareh smo več kot zmagovalci po njem, ki nas je vzljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Kajti prepričan sem, da nas niti smrt, niti življenje, niti angeli, niti kneževine, niti moči, niti sedanje stvari, niti stvari, ki pridejo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'niti višina, niti globina, niti katerokoli drugo ustvarjeno bitje ne bo zmožno ločiti od Božje ljubezni, ki je v Kristusu Jezusu, našem Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Govorim resnico v Kristusu, ne lažem, prav tako mi moja vest pričuje v Svetem Duhu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'da imam v svojem srcu veliko potrtost in nenehno bridkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Kajti lahko bi si želel, da bi bil jaz sam preklet pred Kristusom za svoje brate, moje sorodnike glede na meso;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'ki so Izraelci, ki jim pripada posvojitev in slava in zaveze in dajanje postave in bogoslužje in obljube;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'katerih so očetje in iz katerih je, glede na meso, prišel Kristus, ki je čez vse, Bog, blagoslovljen na veke. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Ne, kakor da Božja beseda ne učinkuje. Kajti niso vsi Izraelci, ki so iz Izraela;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'niti zato, ker so Abrahamovi potomci, niso vsi otroci, temveč: ›Po Izaku se bo imenovalo tvoje seme.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'To se pravi: »Tisti, ki so meseni otroci, tisti niso Božji otroci, temveč so za potomstvo šteti otroci obljube.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Kajti to je beseda obljube: ›Ob tem času bom prišel in Sara bo imela sina.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Pa ne samo to; temveč, ko je tudi Rebeka spočela po enem, celó po našem očetu Izaku');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '(kajti otroka se še nista rodila niti nista naredila ničesar dobrega ali zlega, da lahko ostane Božji namen glede na izvolitev, ne iz del, temveč iz njega, ki kliče),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'ji je bilo rečeno: ›Starejši bo služil mlajšemu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Kakor je pisano: ›Jakoba sem ljubil, toda Ezava sem sovražil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Kaj bomo torej rekli? Ali je pri Bogu nepravičnost? Bog ne daj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Kajti Mojzesu je rekel: ›Usmilil se bom, kogar se hočem usmiliti in sočutje bom imel, do kogar hočem imeti sočutje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Torej potem to ni od tistega, ki hoče niti od tistega, ki teče, temveč od Boga, ki izkazuje usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Kajti pismo pravi faraonu: ›Celo za ta isti namen sem te dvignil, da lahko na tebi pokažem svojo moč in da se bo moje ime lahko razglasilo po vsej celotni zemlji.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Torej se usmili, kogar se hoče usmiliti in kogar hoče, tega zakrkne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Torej mi boš rekel: »Zakaj še najde krivdo? Kajti kdo se je uprl njegovi volji?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Ne, vendar, oh človek, kdo si ti, ki nasprotuješ Bogu? Ali bo oblikovana stvar rekla tistemu, ki jo je ustvaril: »Zakaj si me naredil takšno?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Mar nima lončar moči nad ilom, da iz iste grude naredi eno posodo v čast, drugo pa v nečast?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Kaj pa, če je Bog, voljan pokazati svoj bes in pokazati svojo moč, z veliko potrpežljivosti prenašal posode besa, primerne za uničenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'in da bi lahko dal spoznati bogastva svoje slave na posodah usmiljenja, ki jih je vnaprej pripravil za slavo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'celó nas, ki nas je poklical, ne samo izmed Judov, temveč tudi izmed poganov?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Kakor tudi pravi v Ozeju: ›Ljudi, ki niso bili moji, bom imenoval moji ljudje; in njo, ki ni bila ljubljena, ljubljeno.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'In zgodilo se bo, da na kraju, kjer jim je bilo rečeno: ›Vi niste moji ljudje,‹ tam bodo imenovani otroci živega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Tudi Izaija kliče glede Izraela: ›Četudi bo število Izraelovih otrok kakor morskega peska, bo rešen ostanek;‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, '§ kajti dokončal bo delo in ga nenadoma prekinil v pravičnosti; ker bo Gospod na zemlji hitro opravil svoje delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'In kakor je prej rekel Izaija: ›Razen če nam Gospod nad vojskami ne bi pustil semena, bi bili kakor Sódoma in bi posnemali Gomóro.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Kaj bomo potem rekli? Da so se pogani, ki si niso prizadevali za pravičnost, dokopali do pravičnosti, celó pravičnosti, ki je iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Toda Izrael, ki si je prizadeval za postavo pravičnosti, se ni dokopal do postave pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Zakaj? Ker tega niso iskali po veri, temveč kakor bi bilo to po delih postave. Kajti spotaknili so se ob tisti kamen spotike,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'kakor je pisano: ›Glej, na Sionu položim kamen spotike in skalo pohujšanja; in kdorkoli veruje vanj, ne bo osramočen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bratje, moja srčna želja in prošnja k Bogu za Izrael je, da bi bili oni lahko rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Kajti prinašam jim pričevanje, da imajo gorečnost za Boga, toda ne glede spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Kajti ker so bili nevedni glede Božje pravičnosti in so nameravali vzpostaviti svojo lastno pravičnost, se niso podvrgli Božji pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Kajti Kristus je konec postave za pravičnost vsakemu, ki veruje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Kajti Mojzes opisuje pravičnost, ki je iz postave: ›Da bi človek, ki dela te stvari, živel po njih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Toda pravičnost, ki je iz vere, govori na ta način: »Ne reci v svojem srcu: ›Kdo se bo povzpel v nebo?‹ (to je, Kristusa privedel dol od zgoraj);');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ali: ›Kdo se bo spustil v brezno?‹ (to je, da Kristusa ponovno privede gor od mrtvih).«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Toda kaj ta pravi? Beseda je blizu tebe, celó v tvojih ustih in v tvojem srcu; to je, beseda vere, ki jo oznanjamo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'da če boš s svojimi usti priznal Gospoda Jezusa in boš v svojem srcu veroval, da ga je Bog obudil od mrtvih, boš rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Kajti s srcem človek veruje v pravičnost, z usti pa je narejeno priznanje v rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Kajti pismo pravi: ›Kdorkoli veruje vanj, ne bo osramočen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Kajti ni razlike med Judom in Grkom, kajti isti Gospod nad vsemi je bogat do vseh, ki kličejo k njemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Kajti kdorkoli bo klical h Gospodovemu imenu, bo rešen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Kako bodo torej klicali njega, v katerega niso verovali? In kako bodo verovali vanj, o katerem niso slišali? In kako bodo slišali brez oznanjevalca?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'In kako bodo oznanjali, razen če niso poslani? Kakor je pisano: ›Kako krasna so stopala teh, ki oznanjajo evangelij miru in prinašajo vesele novice o dobrih stvareh!‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Toda evangeliju niso bili vsi poslušni. Kajti Izaija pravi: ›Gospod, kdo je verjel našemu poročilu?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, '§ Tako potem vera prihaja po poslušanju in poslušanje po Božji besedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Vendar pravim: »Mar niso slišali?« Da, resnično, njihov glas je šel po vsej zemlji in njihove besede do koncev sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Toda pravim: »Mar Izrael ni spoznal?« Mojzes najprej pravi: ›Izzval te bom k ljubosumju s tistimi, ki niso ljudstvo in z nespametnim narodom te bom jezil.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Toda Izaija je zelo pogumen in pravi: ›Našli so me tisti, ki me niso iskali; razodet sem bil tem, ki po meni niso spraševali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Toda Izraelu reče: ›Cel ljubi dan sem svoje roke iztegoval k neposlušnim in upornim ljudem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Potem pravim: ›Mar je Bog zavrgel svoje ljudi?‹ Bog ne daj. Kajti tudi sam sem Izraelec, iz Abrahamovega semena, iz Benjaminovega rodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Bog svojih ljudi, ki jih je vnaprej poznal, ni zavrgel. Mar ne veste, kaj pravi pismo o Eliju? Kako je posredoval k Bogu zoper Izraela, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '›Gospod, pobili so tvoje preroke in spodkopali tvoje oltarje; in jaz sam sem ostal in strežejo mi po življenju.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Toda kaj mu pravi Božji odgovor? ›Prihranil sem si sedem tisoč mož, ki niso upognili kolena k Báalovi podobi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Celó tako je tudi v tem sedanjem času ostanek glede na milosten izbor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, '§ In če je po milosti, potem to ni več iz del, drugače milost ni več milost. Toda če je iz del, potem to ni več milost, drugače delo ni več delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Kaj torej? Izrael ni dosegel tega, za kar si je prizadeval, temveč so to dosegli izvoljeni, ostali pa so bili zaslepljeni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '(glede na to, kakor je pisano: ›Bog jim je dal duha omrtvelosti, oči, da ne bi videli, ušesa, da ne bi slišali‹) do današnjega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'In David pravi: ›Naj jim njihova miza postane zanka in past in kamen spotike in njihovo povračilo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'naj njihove oči postanejo zatemnjene, da ne bodo mogli videti in vedno upogni njihov hrbet.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Potem pravim: ›Ali so se spotaknili, da bi padli?‹ Bog ne daj; temveč je po njihovem padcu rešitev duš toliko bolj prišla k poganom, da jih draži do ljubosumja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Če so torej njihov padec bogastva sveta in njihovo zmanjševanje bogastva poganov; koliko bolj njihova polnost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Kajti govorim vam, poganom, v kolikor sem apostol poganom, poveličujem svojo službo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'če lahko na kakršenkoli način izzovem kosanje teh, ki so moje meso in lahko rešim nekatere izmed njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Kajti če je odvračanje teh pobotanje sveta, kaj bo sprejemanje teh, če ne življenje iz mrtvih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Kajti če je prvi sad svét, je svéta tudi gruda; in če je korenina svéta, so tudi veje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'In če so bile nekatere izmed vej odlomljene in si bil ti, ki si divja oljka, vcepljen v sredo mednje in si z njimi udeležen korenine in mastnosti oljke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'se ne bahaj zoper veje. Toda če se bahaš, ne nosiš korenine ti, temveč korenina tebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Rekel boš torej: ›Veje so bile odlomljene, da sem bil jaz lahko vcepljen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Pravilno, ker so bile odlomljene zaradi nevere, ti pa stojiš po veri. Ne bodi vzvišen, temveč se boj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Kajti če Bog ni prizanesel naravnim vejam, pazi, sicer tudi tebi ne prizanese.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Glej torej Božjo dobroto in strogost; na teh, ki so padli, strogost; toda do tebe dobroto, če nadaljuješ v njegovi dobroti; sicer boš tudi ti odsekan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'In tudi oni bodo vcepljeni, če ne bodo nenehno ostajali v neveri, kajti Bog jih je zmožen ponovno vcepiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Kajti če si bil odsekan z oljke, ki je po naravi divja in si bil vcepljen nasprotno naravi, na dobro oljko; koliko mnogo bolj bodo tisti, ki so naravne veje, vcepljeni na svojo lastno oljko?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Kajti nočem bratje, da bi bili nevedni o tej skrivnosti, da ne bi bili modri v svojih lastnih domišljavostih; ta delna slepota se je zgodila Izraelu, dokler ne bo vstopila polnost poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'In tako bo rešen ves Izrael, kakor je pisano: ›S Siona bo izšel Osvoboditelj in brezbožnost bo odvrnil od Jakoba;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'kajti to je moja zaveza njim, ko jim bom odvzel njihove grehe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Kar zadeva evangelij, so zaradi vas sovražniki; toda kar se tiče izbire, so ljubljeni zaradi očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Kajti darovi in Božja poklicanost so brez kesanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Kajti kakor v preteklih časih niste verjeli Bogu, ste sedaj po njihovi neveri vendarle dosegli usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Točno tako tudi ti sedaj niso verjeli, da po vašem usmiljenju tudi sami lahko dosežejo usmiljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Kajti Bog jih je vse zaprl v nevero, da bi se lahko vseh usmilil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Oh globina bogastev, tako Božje modrosti kakor Božjega spoznanja! Kako nedoumljive so njegove sodbe in njegove poti neodkrite!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Kajti kdo je spoznal Gospodovo mišljenje? Ali kdo je bil njegov svetovalec?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ali kdo mu je prvi dal in mu bo to ponovno poplačano?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Kajti iz njega in preko njega in njemu so vse stvari; ki mu bodi slava na veke. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Po Božjih milostih vas torej rotim, bratje, da ponudite svoja telesa v živo žrtev, sveto, Bogu sprejemljivo, kar je vaše smiselno bogoslužje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'In ne bodite prilagojeni temu svetu, temveč bodite preobraženi s prenavljanjem svojega mišljenja, da boste lahko razločili, kaj je tista dobra, sprejemljiva in popolna Božja volja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Kajti po meni dani milosti pravim vsakemu človeku, ki je med vami, naj ne misli o samem sebi višje, kakor bi moral misliti; temveč naj misli trezno, glede na to, kakor je Bog vsakemu človeku podelil mero vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Kajti kakor imamo v enem telesu mnogo udov in vsi udje nimajo iste službe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'tako smo mi, ki nas je mnogo, eno telo v Kristusu in vsakdo udje drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Ker imamo torej darove, ki se razlikujejo glede na milost, ki nam je dana, če prerokba, prerokujmo glede na mero vere;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'če služenje, počakajmo na naše služenje; ali kdor poučuje, na poučevanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'ali kdor spodbuja, na spodbudo; kdor daje, naj to dela s preprostostjo; kdor vlada, z marljivostjo; kdor izkazuje usmiljenje, z vedrostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Naj bo ljubezen brez pretvarjanja. Sovražite to, kar je zlo; trdno se držite tega, kar je dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Bodite drug drugemu prijazno naklonjeni z bratoljúbjem; v spoštovanju dajajte prednost drug drugemu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'ne leni v poslu, [temveč] goreči v duhu; služeč Gospodu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'veseleč se v upanju; potrpežljivi v stiski; neprenehoma [neprenehoma: gr. iskreno, vztrajno, marljivo] nadaljujte v molitvi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'razdeljujte nujnim potrebam svetih, predani gostoljubnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Blagoslavljajte te, ki vas preganjajo, blagoslavljajte in ne preklinjajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Veselite se s temi, ki se veselijo in jokajte s temi, ki jokajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Drug do drugega bodite istega mišljenja. Ne mislite visokih stvari, temveč se ponižajte k ljudem nizkega stanu. V svojih lastnih domišljavostih ne bodite modri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Nobenemu človeku ne poplačajte zla za zlo. Pred očmi vseh ljudi skrbite za poštene stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Če je mogoče, kolikor je v vaši moči, živite miroljubno z vsemi ljudmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, '§ Srčno ljubljeni, sami se ne maščujte, temveč raje dajte prostor besu, kajti pisano je: ›Moje je maščevanje, jaz bom povrnil, govori Gospod.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Torej če je tvoj sovražnik lačen, ga nahrani; če je žejen, mu daj piti, kajti s takšnim početjem boš kopičil ognjeno oglje na njegovo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne bodite premagani od zla, temveč zlo premagajte z dobrim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, '§ Naj bo vsaka duša podrejena višjim oblastem. Kajti ni oblasti, razen od Boga; oblasti, ki so, so odrejene od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Kdorkoli se torej upira oblasti, se upira Božji odredbi in tisti, ki se upirajo, bodo sebi prejeli obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Kajti vladarji niso strahota dobrim delom, temveč zlim. Se torej ne boš bal oblasti? Delaj to, kar je dobro in imel boš pohvalo od nje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'kajti ona je Božja služabnica, tebi v dobro. Toda če počneš to, kar je zlo, se boj, ker meča ne nosi zaman; kajti Božja služabnica je, maščevalka, da izvrši bes nad tistim, ki počenja zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Zatorej morate biti nujno podrejeni, ne samo zaradi besa, temveč tudi zaradi vesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Kajti zaradi tega razloga tudi plačujete davek, kajti oni so Božji služabniki, ki nenehno skrbijo prav za to stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Povrnite torej vsem njihove dolgove: davek, komur gre davek, carino, komur carino, strah, komur strah, spoštovanje, komur spoštovanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Nobenemu človeku ničesar ne dolgujte, razen da ljubite drug drugega; kajti kdor ljubi drugega, je izpolnil postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, '§ Zaradi tega: ›Ne boš zagrešil zakonolomstva,‹ ›Ne boš ubil,‹ ›Ne boš kradel,‹ ›Ne boš pričal po krivem,‹ ›Ne boš požêlel;‹ in če obstaja katera druga zapoved, je le-ta na kratko obsežena v tej besedi, namreč: ›Ljubil boš svojega bližnjega kakor samega sebe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Ljubezen svojemu bližnjemu ne dela škode; torej je ljubezen izpolnitev postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'In ker poznamo čas, da je sedaj skrajni čas, da se prebudimo iz spanja, kajti sedaj je naša rešitev duš bližje, kakor ko smo [začeli] verovati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noč je davno minila, dan je blizu. Odvrzimo torej dela teme in si nadenimo bojno opremo svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Živimo pošteno, kakor podnevi; ne v upornosti in pijanosti, ne v nespodobnosti in razuzdanosti, ne v prepiru in zavisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Temveč si nadenite Gospoda Jezusa Kristusa in ne delajte si preskrbe za meso, da [bi] izpolnili poželenja le-tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Tistega, ki je v veri slaboten, sprejmite, toda ne k dvomljivim pričkanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Kajti nekdo veruje, da lahko jé vse stvari; drug, ki je šibek, jé zelišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Naj tisti, ki jé, ne prezira tistega, ki ne jé; in kdor ne jé, naj ne sodi tistega, ki jé; kajti Bog ga je sprejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kdo si ti, da sodiš služabnika drugega moža? Svojemu lastnemu gospodarju stoji ali pade. Da, obdržan bo pokonci; kajti Bog ga je zmožen postaviti pokonci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Nek človek čisla en dan nad drugim, drugi čisla vsak dan enako. Naj bo vsak v svojem lastnem mišljenju popolnoma prepričan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, '§ Kdor upošteva dan, ga upošteva za Gospoda; kdor pa dneva ne upošteva, ga ne upošteva Gospodu. Kdor jé, jé za Gospoda, kajti zahvale daje Bogu; kdor pa ne jé, ne jé Gospodu in zahvalo daje Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Kajti nihče izmed nas ne živi zase in noben človek ne umira zase.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Kajti če živimo, živimo za Gospoda; in če umremo, umremo za Gospoda. Če torej živimo ali umremo, smo Gospodovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, '§ Kajti zato je Kristus tako umrl kakor vstal in oživel, da bi bil lahko Gospod tako mrtvih kakor živih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, '§ Toda zakaj sodiš svojega brata? Ali zakaj zasmehuješ svojega brata? Kajti vsi bomo stali pred Kristusovim sodnim stolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Kajti pisano je: ›Kakor jaz živim, govori Gospod, bo vsako koleno pokleknilo k meni in vsak jezik bo priznal Boga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Tako bo potem vsak izmed nas Bogu dal obračun o sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Torej ne sodimo več drug drugega, temveč raje sodimo to, da noben človek ne postavi kamna spotike ali priložnosti, da pade, na pot svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Vem in po Gospodu Jezusu sem prepričan, da ni nič sámo po sebi nečisto; toda temu, ki mêni, da je karkoli nečisto, je to zanj nečisto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Toda če je tvoj brat užaloščen s tvojo jedjo, torej ne živiš v ljubezni. S svojo jedjo ne uničuj tega, za kogar je Kristus umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Naj se potem o vašem dobrem ne govori zlo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'kajti Božje kraljestvo ni hrana in pijača, temveč pravičnost in mir in radost v Svetem Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Kajti kdor v teh stvareh služi Kristusu, je sprejemljiv za Boga in potrjen od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Prizadevajmo si torej za stvari, ki delajo za mir in za stvari, s katerimi lahko eden izgrajuje drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Zaradi hrane ne uničuj Božjega dela. Vse stvari so zares čiste; toda zlo je za tistega človeka, ki jé s spotiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Dobro je ne jesti mesa niti piti vina niti katerekoli stvari, s čimer se tvoj brat spotika ali je užaljen ali je postal slaboten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Imaš vero? Imej jo zase pred Bogom. Srečen je, kdor sebe ne obsoja v tej stvari, ki jo on dopušča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Kdor pa dvomi, je obsojen če jé, ker ne jé iz vere; kajti karkoli ni iz vere, je greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Torej moramo mi, ki smo močni, prenašati slabotnosti šibkih, ne pa da ugajamo sebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Naj vsak izmed nas ugaja svojemu bližnjemu v njegovo dobro, za izgrajevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Kajti celó Kristus ni ugajal sebi; temveč, kakor je pisano: ›Graje teh, ki so te grajali, so padle name.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Kajti katerekoli stvari so bile vnaprej napisane, so bile napisane za naše učenje, da bi lahko preko potrpežljivosti in tolažbe iz pisem imeli upanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Naj vam torej Bog potrpežljivosti in tolažbe zagotovi, da boste istih misli drug do drugega glede na Kristusa Jezusa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'da boste lahko z enim umom in enimi usti slavili Boga, celó Očeta našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Zatorej sprejemajte drug drugega, kakor je tudi Kristus nas sprejel v Božjo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Torej pravim, da je bil Jezus Kristus služabnik obreze za Božjo resnico, da potrdi obljube, narejene očetom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'in da lahko pogani zaradi njegovega usmiljenja slavijo Boga; kakor je pisano: ›Zaradi tega razloga te bom priznal med pogani in prepeval tvojemu imenu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'In ponovno pravi: ›Veselite se, vi pogani, z njegovimi ljudmi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'In ponovno: ›Hvalíte Gospoda, vsi pogani; in povzdigujte ga vsi ljudje.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'In ponovno Izaija pravi: ›Jesejeva korenina bo in tisti, ki se bo dvignil, da kraljuje nad pogani; vanj bodo zaupali pogani.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Torej Bog upanja naj vas napolni z velikim veseljem in mirom v verovanju, da boste, po môči Svetega Duha, obilni v upanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'In tudi jaz sam sem prepričan o vas, moji bratje, da ste tudi vi polni dobrote, izpolnjeni z vsem spoznanjem, zmožni tudi drug drugega opominjati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Vendar, bratje, zaradi milosti, ki mi je dana od Boga, sem vam napisal na nek način pogumneje, kakor da vas spomnim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'da naj bi bil jaz služabnik Jezusa Kristusa za pogane, ko služim Božjemu evangeliju, da bi bila daritev poganov, posvečena po Svetem Duhu, lahko sprejemljiva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Torej imam nekaj, s čimer se lahko po Jezusu Kristusu ponašam v teh stvareh, ki se nanašajo na Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Kajti ne bom si drznil govoriti o katerikoli izmed tistih stvari, ki jih Kristus ni naredil po meni, da bi naredil pogane poslušne v besedi in dejanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'preko mogočnih znamenj in čudežev, po moči Božjega Duha; tako da sem od Jeruzalema in naokoli do Ilirika obširno oznanil Kristusov evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Da, tako sem si prizadeval, da ne oznanim evangelija, kjer je bil Kristus imenovan, da ne bi gradil na temelju drugega človeka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'temveč kakor je pisano: ›Katerim ni bilo govorjeno, bodo videli; in tisti, ki niso slišali, bodo razumeli.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Zaradi tega razloga sem bil tudi sam zelo oviran, da pridem k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Toda sedaj, ko v teh krajih nimam več prostora in imam ta mnoga leta veliko željo, da pridem k vam;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'kadarkoli se odpravim na svoje potovanje v Španijo, bom prišel k vam, kajti zaupam, da vas na svojem potovanju vidim in da bom na svoji poti tja priveden mimo vas, da bi bil najprej nekoliko izpolnjen z vašo druščino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Toda sedaj grem v Jeruzalem, da služim svetim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Kajti tem iz Makedonije in Ahaje je ugajalo, da zberejo nek prispevek za revne svete, ki so v Jeruzalemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'To jih je resnično veselilo; in njihovi dolžniki so. Kajti če so pogani postali soudeleženi njihovih duhovnih stvari, je tudi njihova dolžnost, da jim služijo v mesenih stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Ko bom torej to opravil in jim zapečatil ta sad, bom mimo vas prišel v Španijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, '§ In prepričan sem, ko pridem k vam, da bom prišel v polnosti blagoslova Kristusovega evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Sedaj vas rotim, bratje, zaradi Gospoda Jezusa Kristusa in zaradi ljubezni Duha, da se skupaj z menoj borite v svojih molitvah zame k Bogu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'da bom lahko rešen pred temi, ki v Judeji ne verujejo; in da bodo mojo službo, ki jo imam za Jeruzalem, sveti lahko sprejeli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'da bom lahko po Božji volji z veseljem prišel k vam in bom lahko skupaj z vami okrepčan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Torej Bog miru bodi z vami vsemi. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Priporočam vam našo sestro Fojbo, ki je služabnica cerkve, ki je v Kenhrejah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'da jo sprejmete v Gospodu, kakor se spodobi svetim in da ji pomagate v kateremkoli opravilu vas potrebuje. Kajti bila je pomočnica mnogim in tudi meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdravite Prisko in Ákvila, moja pomočnika v Kristusu Jezusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'ki sta za moje življenje tvegala svoja lastna vratova; ki se jima ne zahvaljujem samo jaz, temveč tudi vse cerkve poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Prav tako pozdravite cerkev, ki je v njuni hiši. Pozdrav mojemu srčno ljubljenemu Epájnetu, ki je prvenec Ahaje Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdravite Marijo, ki je trdo delala z mnogim trudom za nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdrav Andróniki in Juniju, mojima sorodnikoma in mojima sojetnikoma, ki sta pomembna med apostoli, ki sta bila tudi pred menoj v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdravite Ampliáta, mojega ljubljenega v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdrav Urbanu, našemu pomočniku v Kristusu in Stahiju, mojemu ljubljenemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdrav Apélu, potrjenemu v Kristusu. Pozdrav tem, ki so iz Aristóbulove družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdrav Heródionu, mojemu sorodniku. Pozdravite te, ki so iz Narcísove družine, ki so v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdrav Trífajni in Trifózi, ki se trudita v Gospodu. Pozdrav ljubljeni Pêrsidi, ki se je veliko trudila v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdravite Rufa, izbranca v Gospodu in njegovo mater in mojo [mater].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdrav Asínkritu, Flegonu, Hermesu, Patrobáju, Hermáju in bratom, ki so z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdrav Filológu in Juliji, Neréju in njegovi sestri ter Olimpáju in vsem svetim, ki so z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdravite drug drugega s svetim poljubom. Pozdravljajo vas Kristusove cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Torej, rotim vas, bratje, zapomnite si te, ki povzročajo nesoglasja in prestopke, nasprotne nauku, ki ste se ga naučili; in izogibajte se jih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Kajti ti, ki so takšni, ne služijo našemu Gospodu Jezusu Kristusu, temveč svojemu lastnemu trebuhu; in z lepimi besedami ter vljudnimi govori zavajajo srca preprostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Kajti vaša poslušnost je šla naokoli k vsem ljudem. Zaradi vas sem torej vesel; toda kljub temu bi vas želel imeti modre do tega, kar je dobro in nepokvarjene glede zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'In Bog miru bo v kratkem zmečkal Satana pod vašimi stopali. Milost našega Gospoda Jezusa Kristusa naj bo z vami. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdravljajo vas Timótej, moj delovni družabnik in moji sorodniki Lukij in Jazon in Sozípater.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Jaz, Tertij, ki sem napisal to poslanico, vas pozdravljam v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdravlja vas Gaj, gostitelj mene in celotne cerkve. Pozdravlja vas Erást, glavni upravitelj mesta in brat Kvart.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '§ Milost našega Gospoda Jezusa Kristusa naj bo z vami vsemi. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Torej njemu, ki je sposoben, da vas utrdi v skladu z mojim evangelijem in oznanjevanjem Jezusa Kristusa, glede na razodetje skrivnosti, ki je bila tajno čuvana od nastanka sveta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'toda sedaj je razodeta in po pismih prerokov, glede na zapoved večnega Boga, razglašena vsem narodom zaradi poslušnosti veri;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Bogu, edinemu modremu, bodi slava po Jezusu Kristusu na veke. Amen. [Napisano Rimljanom iz Korinta in poslano po služabnici Fojbi iz kenhrejske cerkve.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pavel, poklican, da je po Božji volji apostol Jezusa Kristusa in naš brat Sostén,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Božji cerkvi, ki je v Korintu, tem, ki so posvečeni v Kristusu Jezusu, poklicani, da so sveti, z vsemi, ki na vsakem kraju, tako njihovem kakor našem, kličejo ime Jezusa Kristusa, našega Gospoda:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Vedno se vam v prid zahvaljujem svojemu Bogu za Božjo milost, ki vam je dana po Jezusu Kristusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'da ste v vsaki stvari obogateni po njem, v vsej izgovarjavi in v vsem spoznanju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'celó kakor je bilo Kristusovo pričevanje potrjeno v vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'tako da vam, ki pričakujete prihod našega Gospoda Jezusa Kristusa, ne primanjkuje nobenega daru;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'ki vas bo tudi do konca potrdil, da boste lahko brez krivde na dan našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Bog je zvest, po katerem ste bili poklicani v družbo njegovega Sina Jezusa Kristusa, našega Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Torej vas rotim, bratje, v imenu našega Gospoda Jezusa Kristusa, da vsi govorite isto stvar in da med vami ne bo nobenih nesoglasij; temveč da boste popolnoma združeni skupaj, v istem mišljenju in v isti sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Kajti razodeto mi je bilo o vas, moji bratje, po teh, ki so iz Hloine hiše, da so med vami prepiri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Pravim torej to, da vsak izmed vas govori: »Jaz sem Pavlov, jaz Apolov, jaz Kefov, jaz pa Kristusov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ali je Kristus razdeljen? Ali je bil Pavel križan za vas? Ali ste bili krščeni v Pavlovo ime?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Zahvaljujem se Bogu, da nisem krstil nobenega izmed vas razen Krispa in Gaja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'da ne bi kdorkoli lahko rekel, da sem krščeval v svojem lastnem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'In krstil sem tudi Stefanájevo družino; razen tega ne vem, če sem krstil kogarkoli drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Kajti Kristus me ni poslal krščevat, temveč oznanjat evangelij; ne z modrostjo besed, da ne bi bil Kristusov križ storjen brez učinka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Kajti oznanjevanje križa je tem, ki propadajo, nespametnost; toda nam, ki smo rešeni, je Božja moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Kajti pisano je: ›Uničil bom modrost modrih in zavrgel bom razum razsodnih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kje je modri? Kje je pisar? Kje je razpravljavec tega sveta? Mar ni modrosti tega sveta Bog naredil za nespametnost?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Kajti potem, ko v Božji modrosti svet po modrosti ni spoznal Boga, je Bogu ugajalo, da po nespametnosti oznanjevanja reši te, ki verujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, '§ Kajti Judje zahtevajo znamenje in Grki iščejo modrost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'toda mi oznanjamo križanega Kristusa, Judom kamen spotike in Grkom nespametnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'toda tem, ki so poklicani, tako Judom kakor Grkom, [je] Kristus Božja moč in Božja modrost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Kajti Božja nespametnost je modrejša od ljudi in Božja slabost močnejša od ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Kajti vidite svoj klic, bratje, da ni poklicanih veliko modrih po mesu, ne veliko mogočnih, ne veliko plemenitih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'toda Bog je izbral nespametne stvari sveta, da zbega modre; in Bog je izbral slabotne stvari sveta, da zbega stvari, ki so mogočne;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'in nizke stvari sveta in stvari, ki so prezirane, je Bog izbral, da, in stvari, ki niso, da zavrže stvari, ki so,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'da se v njegovi prisotnosti ne bi poveličevalo nobeno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Toda vi ste iz njega v Kristusu Jezusu, ki je za nas postal modrost od Boga in pravičnost in posvečenje in odkupitev;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'da, kakor je pisano: ›Kdor se ponaša, naj se ponaša v Gospodu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'In jaz, bratje, ko sem prišel k vam, razglašajoč Božje pričevanje, nisem prišel z odličnostjo govora ali z modrostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Kajti odločil sem ne vedeti med vami nobene stvari, razen Jezusa Kristusa in njega križanega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'In z vami sem bil v slabosti in v strahu ter v mnogem trepetanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'In moj govor in moje oznanjevanje nista bila s prepričevalnimi besedami človeške modrosti, temveč v prikazu Duha in moči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'da vaša vera ne bi stala na človeški modrosti, temveč na Božji moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Vendar govorimo modrost med temi, ki so popolni; vendar ne modrosti tega sveta niti princev tega sveta, ki se izjalovi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'temveč govorimo Božjo modrost v skrivnosti, celó prikrito modrost, ki jo je Bog pred svetom odredil v našo slavo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'ki je nobeden izmed princev tega sveta ni spoznal. Kajti če bi jo spoznali, ne bi križali Gospoda slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Toda kakor je pisano: ›Oko ni videlo niti uho slišalo niti ni vstopilo v človekovo srce, stvari, ki jih je Bog pripravil za tiste, ki ga ljubijo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Toda Bog nam jih je razodel po svojem Duhu, kajti Duh preiskuje vse stvari, da, globoke Božje stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Kajti kateri človek ve stvari o človeku razen človekovega duha, ki je v njem? Točno tako Božje stvari ne pozna noben človek, razen Božjega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, '§ Torej nismo prejeli duha sveta, temveč duha, ki je od Boga; da bi lahko spoznali stvari, ki so nam velikodušno dane od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'O katerih stvareh tudi govorimo, ne z besedami, ki jih uči človeška modrost, temveč ki jih uči Sveti Duh; [in] duhovne stvari primerjamo z duhovnimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Toda naraven človek ne sprejema stvari od Božjega Duha, kajti te so mu nespametnost; niti jih ne more razpoznati, ker se spoznavajo duhovno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Toda kdor je duhoven, presoja vse stvari, čeprav on sam ni sojen od nobenega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Kajti kdo je spoznal Gospodov um, da bi ga lahko poučil? Toda mi imamo Kristusov um.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'In jaz, bratje, vam nisem mogel govoriti kot duhovnim, temveč kot mesenim, celó kot otročičem v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Hranil sem vas z mlekom in ne z jedjo, kajti doslej je niste bili zmožni prenesti niti še sedaj ne zmorete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, '§ Kajti še vedno ste meseni; kajti glede na to, da so med vami zavist in prepir in nesoglasja, mar niste meseni in živite kot ljudje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Kajti dokler nekdo govori: »Jaz sem Pavlov,« drugi pa: »Jaz sem Apolov;« mar niste še meseni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kdo je potem Pavel in kdo je Apolo, če ne služabnika, po katerih verujete, prav kakor je Gospod dal vsakemu človeku?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Jaz sem zasadil, Apolo zalil, toda Bog je dal rast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Torej potem ni nič, kdor sadi niti kdor zaliva, temveč Bog, ki daje rast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Torej kdor sadi in kdor zaliva, sta eno; in vsak bo svojo lastno nagrado prejel glede na svoj lastni trud.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Kajti midva sva delavca skupaj z Bogom. Vi ste Božje poljedelstvo, vi ste Božja zgradba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Glede na milost od Boga, ki mi je dana kot modremu stavbeniku, sem položil temelj in drug gradi na njem. Toda vsak naj pazi, kako gradi na njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Kajti drugega temelja, kot je položen, ki je Jezus Kristus, noben človek ne more položiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Torej če katerikoli človek na tem temelju gradi zlato, srebro, dragocene kamne, les, seno, strnišče;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'delo vsakega bo razodeto, kajti razkril ga bo dan, ker bo razodet z ognjem; in ogenj bo preizkusil delo vsakega, kakšne vrste je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Če delo kateregakoli človeka, ki je gradil na njem, ostane, bo prejel nagrado.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Če bo delo kateregakoli človeka zgorelo, bo trpel izgubo, toda on sam bo rešen; vendar tako kakor z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ali ne veste, da ste Božji tempelj in da Božji Duh prebiva v vas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Če katerikoli človek omadežuje Božji tempelj, bo Bog uničil njega; kajti Božji tempelj je svét, čigar tempelj ste vi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Naj se noben človek ne vara. Če se komurkoli med vami zdi, da je v tem svetu moder, naj postane bedak, da bo lahko moder.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Kajti modrost tega sveta je pri Bogu norost. Kajti pisano je: ›Modre zasači v njihovi lastni prebrisanosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'In ponovno: ›Gospod pozna misli modrih, da so prazne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Torej naj se noben človek ne ponaša z ljudmi. Kajti vse stvari so vaše:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'bodisi Pavel ali Apolo ali Kefa ali svet ali življenje ali smrt ali sedanje stvari ali stvari, ki pridejo; vse so vaše;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'vi ste Kristusovi, Kristus pa je Božji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Naj človek tako misli o nas kakor o Kristusovih služabnikih in oskrbnikih Božjih skrivnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Poleg tega je pri oskrbnikih zahtevano, da je človek najden zvest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Toda kar se mene tiče je to zelo majhna stvar, da bi bil sojen od vas ali od človeške sodbe. Da, jaz samega sebe ne sodim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Kajti sam od sebe ne vem nič, čeprav s tem nisem opravičen; toda kdor sodi mene, je Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Torej ničesar ne sodite pred časom, dokler ne pride Gospod, ki bo na svetlobo privedel tako skrite stvari teme, kakor bo razodel namene src; in tedaj bo vsak prejel pohvalo od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'In te stvari, bratje, sem zaradi vas v podobi prenesel nase in na Apola, da bi se lahko na nama naučili ne misliti o ljudeh preko tega, kar je pisano, da se nobeden izmed vas ne bi napihoval drug proti drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Kajti kdo te dela, da se razlikuješ od drugega? In kaj imaš, česar nisi prejel? Torej, če si to prejel, zakaj se ponašaš, kakor če tega nisi prejel?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Sedaj ste siti, sedaj ste bogati, brez nas ste zakraljevali kakor kralji; in Bog daj, da ste zakraljevali, da bomo lahko tudi mi kraljevali z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Kajti mislim, da je Bog nas apostole postavil zadnje, kakor bi bili določeni za smrt; kajti postali smo prizor svetu, angelom in ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Mi smo bedaki za Kristusa, toda vi ste modri v Kristusu; mi smo slabotni, toda vi ste močni; vi ste častitljivi, toda mi smo prezirani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Celó do sedanje ure smo tako lačni kakor žejni, nagi, oklofutani in nimamo zanesljivega bivališča;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'in trudimo se ter delamo s svojimi lastnimi rokami; ko smo zasramovani, blagoslavljamo; ko smo preganjani, to potrpimo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'ko smo psovani, milo prosimo. Postali smo kakor umazanija sveta in do današnjega dne smo izvržki vseh stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Teh stvari vam ne pišem, da vas sramotim, temveč vas kot svoje ljubljene sinove svarim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Kajti čeprav imate deset tisoč učiteljev v Kristusu, vendarle nimate mnogo očetov; kajti v Kristusu Jezusu sem vas po evangeliju rodil jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Zatorej vas rotim, bodite moji posnemovalci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Zaradi tega razloga sem k vam poslal Timóteja, ki je moj ljubljeni sin in zvest v Gospodu, ki vam bo priklical v spomin moje poti, ki so v Kristusu, kakor povsod v vsaki cerkvi učim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Torej nekateri so napihnjeni, kot da ne bom prišel k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Toda k vam bom prišel v kratkem, če Gospod hoče in ne bom spoznal govora teh, ki se napihujejo, temveč moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Kajti Božje kraljestvo ni v besedi, temveč v moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Kaj hočete? Naj pridem k vam s palico ali v ljubezni in v duhu krotkosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Pogosto se sporoča, da je med vami prešuštvo in to prešuštvo, kakršno je komaj imenovano med pogani, da naj bi nekdo imel ženo svojega očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'In vi ste napihnjeni in niste raje žalovali, da bi bil tisti, ki je to dejanje storil, lahko odvzet izmed vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Kajti resnično, čeprav telesno odsoten, toda prisoten v duhu, sem že sodil, kakor da sem bil prisoten, glede tistega, ki je storil to dejanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, '§ v imenu našega Gospoda Jezusa Kristusa, ko ste z močjo našega Gospoda Jezusa Kristusa skupaj zbrani vi in moj duh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'da se takšnega izroči Satanu v uničenje mesa, da bi bil duh lahko rešen na dan Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Vaše ponašanje ni dobro. Mar ne veste, da malo kvasa prekvasi celotno gmoto?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, '§ Počistite torej stari kvas, da boste lahko nova gmota, ker ste nekvašeni. Kajti celó Kristus, naše pashalno jagnje, je žrtvovan za nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Torej praznujmo praznik, ne s starim kvasom niti s kvasom hudobije in zlobnosti, temveč z nekvašenim kruhom iskrenosti in resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'V poslanici sem vam napisal, da se ne družite s prešuštvovalci,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'čeprav ne skupaj s prešuštvovalci tega sveta ali z lakomniki ali izsiljevalci ali z malikovalci; kajti potem morate brezpogojno oditi s sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Toda sedaj sem vam napisal, da se ne družite, če je katerikoli človek, ki se imenuje brat, prešuštvovalec ali lakomnik ali malikovalec ali obrekljivec ali pijanec ali izsiljevalec; s takšnim niti ne jejte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Kajti kaj moram storiti, da sodim tudi tiste, ki so zunaj? Mar ne sodite vi tistih, ki so znotraj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Toda tiste, ki so zunaj, sodi Bog. Torej to zlobno osebo odslovite izmed sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Ali si drzne kdo izmed vas, ki ima zadevo zoper drugega, tožiti pred nepravičnimi, ne pa pred svetimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Mar ne veste, da bodo sveti sodili svet? In če bo svet sojen po vas ali ste nevredni, da sodite najmanjšim zadevam?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Mar ne veste, da bomo sodili angelom? Koliko bolj stvarem, ki se nanašajo na to življenje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Če imate torej sodbe o stvareh, ki se nanašajo na to življenje, postavljate za sodnike tiste, ki so v cerkvi najmanj spoštovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Govorim v vašo sramoto. Ali je tako, da med vami ni modrega? Ni niti enega, ki bi bil sposoben razsoditi med svojimi brati?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Vendar se brat toži z bratom in to pred neverniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Torej je zato med vami skrajna krivica, ker se tožite drug z drugim. Zakaj raje ne sprejmete krivice? Zakaj raje ne dopustite, da ste ogoljufani?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Ne, vi delate krivico in goljufate, in to svoje brate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Mar ne veste, da nepravični ne bodo podedovali Božjega kraljestva? Ne bodite zavedeni; niti prešuštvovalci, niti malikovalci, niti zakonolomci, niti poženščeni, niti tisti, ki sami sebe zlorabljajo z možmi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'niti tatovi, niti lakomniki, niti pijanci, niti zasramovalci, niti izsiljevalci ne bodo podedovali Božjega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, '§ In takšni ste bili nekateri izmed vas; toda vi ste umiti, toda vi ste posvečeni, toda vi ste opravičeni v imenu Gospoda Jezusa in z Duhom našega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Dovoljene so mi vse stvari, toda vse stvari niso koristne. Dovoljene so mi vse stvari, toda podvržen ne bom pod oblast nobene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Jedi [so] za trebuh in trebuh za jedi, toda Bog bo uničil tako to kakor te. Telo torej ni za prešuštvovanje, temveč za Gospoda; in Gospod za telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'In Bog je obudil tako Gospoda, kakor bo po svoji lastni moči obudil tudi nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Mar ne veste, da so vaša telesa Kristusovi udje? Mar naj torej vzamem Kristusove ude in jih naredim za ude pocestnice? Bog ne daj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Kaj? Mar ne veste, da kar je združeno s pocestnico, je eno telo? ›Kajti dva,‹ pravi on, ›bosta eno meso.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Toda kdor je pridružen h Gospodu, je en duh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Bežite pred prešuštvom. Vsak greh, ki ga stori človek, je zunaj telesa; toda kdor zagreši prešuštvo, greši zoper svoje lastno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Kaj? Mar ne veste, da je vaše telo tempelj Svetega Duha, ki je v vas, ki ga imate od Boga in niste sami svoji?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, '§ Kajti odkupljeni ste s ceno; zato proslavite Boga v vašem telesu in v vašem duhu, ki sta Božja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Torej glede stvari, o katerih ste mi pisali: ›Dobro je za moškega ne dotikati se ženske.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Kljub temu naj ima, v izogib prešuštvovanju, vsak mož svojo lastno ženo in vsaka ženska naj ima svojega lastnega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Naj soprog ženi vrača dolžno dobrohotnost in prav tako žena soprogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Žena nima oblasti nad svojim lastnim telesom, temveč soprog. In prav tako tudi soprog nima oblasti nad svojim lastnim telesom, temveč žena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, '§ Ne prikrajšujta se drug drugemu, razen če je to s soglasjem za nekaj časa, da se lahko predata postu in molitvi; in ponovno pridita skupaj, da vaju zaradi vajinega pomanjkanja samoobvladovanja ne skuša Satan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Toda to govorim z dovoljenjem in ne po zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Kajti želim, da bi bili vsi ljudje kakor jaz. Toda vsak človek ima svoj primeren dar od Boga, eden na ta način, drugi pa na drug.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Torej neporočenim in vdovam pravim: »Zanje je dobro, če ostanejo kakor jaz.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Toda če se ne morejo brzdati, naj se poročé; kajti bolje se je poročiti kakor plameneti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Poročenim pa naročam, čeprav ne jaz, temveč Gospod: »Naj žena ne odide od svojega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Toda če odide, naj ostane neomožena ali naj se pobota k svojemu soprogu, in soprog naj svoje žene ne odslovi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Toda drugim govorim jaz, ne Gospod: »Če ima katerikoli brat ženo, ki ne veruje in je zadovoljna, da prebiva z njim, naj je ne odslovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'In ženska, ki ima soproga, ki ne veruje in če je zadovoljen, da prebiva z njo, naj ga ona ne zapusti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Kajti neverni soprog je posvečen po ženi in neverna žena je posvečena po soprogu; sicer bi bili vaši otroci nečisti, toda sedaj so sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Toda če neverni odide, naj odide. Brat ali sestra v teh primerih nista pod suženjstvom; toda Bog nas je poklical k miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Kajti kaj veš ti, oh žena, če boš rešila svojega soproga? Ali kako veš ti, oh mož, če boš rešil svojo ženo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Toda kakor je Bog vsakemu človeku razdelil, kakor je Gospod vsakogar poklical, tako naj hodi. In tako določam v vseh cerkvah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Ali je poklican katerikoli mož, ki je obrezan? Naj ne postane neobrezan. Ali je kateri poklican neobrezan? Naj ne bo obrezan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obreza ni nič in neobreza ni nič, temveč izpolnjevanje Božjih zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Naj vsak ostane v isti poklicanosti, v katero je bil poklican.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Ali si bil poklican kot služabnik? Ne skrbi za to. Toda če lahko postaneš svoboden, to vsekakor izkoristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Kajti kdor je poklican v Gospodu kot služabnik, je Gospodov osvobojenec; prav tako tudi kdor je poklican kot svoboden, je Kristusov služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Odkupljeni ste za ceno; ne bodite služabniki ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Bratje, naj vsak ostane z Bogom v tem, v čemer je bil poklican.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Torej glede devic nimam zapovedi od Gospoda; čeprav dam svoje mnenje kakor nekdo, ki je dosegel usmiljenje od Gospoda, da je zvest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Domnevam torej, da je to dobro zaradi sedanje stiske; pravim, da je to dobro za človeka, da je tako.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Ali si vezan k ženi? Ne skušaj biti razvezan. Ali si razvezan od žene? Ne išči žene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Toda če pa se poročiš, nisi grešil; in če se devica poroči, ni grešila. Vendar bodo taki imeli stisko v mesu; toda prizanašam vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Toda pravim to, bratje, čas je kratek. Preostaja to, da so tisti, ki imajo žene, kakor da jih ne bi imeli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'in tisti, ki jokajo, kakor ne bi jokali; in tisti, ki se veselijo, kakor da se ne bi veselili; in tisti, ki kupujejo, kakor ne bi imeli v lasti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'in tisti, ki uporabljajo ta svet, kakor ga ne bi zlorabljali; kajti videz tega sveta mineva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Toda hočem, da ste brez skrbi. Kdor je neporočen, skrbi za stvari, ki pripadajo Gospodu, kako bi lahko ugajal Gospodu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, '§ toda kdor je poročen, skrbi za stvari, ki so od sveta, kako bi lahko ugajal svoji ženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, '§ Razlika je tudi med ženo in devico. Neporočena ženska skrbi za Gospodove stvari, da bi bila lahko sveta, tako v telesu kakor v duhu; toda tista, ki je poročena, skrbi za svetne stvari, kako bi lahko ugodila svojemu soprogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'In to govorim v vašo lastno korist; ne da bi na vas lahko vrgel zanko, temveč k temu kar je ljubko in da bi lahko nemoteno služili Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, '§ Toda če kateri človek misli, da se do svoje device vede nespodobno, če je minil cvet njenih let in potreba tako zahteva, naj stôri, kar hoče, ne greši; naj se poročita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Vendar kdor v svojem srcu neomajno stoji in nima nujne potrebe, temveč ima oblast nad svojo lastno voljo in je v svojem srcu tako določil, da bo ohranil svojo devico, stori pravilno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Tako torej kdor jo daje v zakon, stori pravilno; toda kdor je ne daje v zakon, stori bolje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Žena je vezana s postavo, dokler njen soprog živi; toda če njen soprog umre, je prosta, da se poroči s komer hoče; le v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Toda po moji sodbi je srečnejša, če ostane tako; in mislim, da imam tudi jaz Božjega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Torej glede stvari, darovanih malikom, vemo, da imamo vsi spoznanje. Spoznanje napihuje, toda ljubezen izgrajuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'In če katerikoli človek misli, da karkoli pozna, še nič ne pozna, kakor bi moral poznati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Toda če katerikoli človek ljubi Boga, isti je spoznan od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, '§ Kar torej zadeva uživanje tistih stvari, ki so darovane v žrtvovanje malikom, vemo, da v svetu malik ni nič in da ne obstaja drug Bog razen enega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Kajti čeprav obstajajo ti, ki se imenujejo bogovi, bodisi na nebu ali na zemlji (kakor obstaja mnogo bogov in mnogo gospodov),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'toda za nas ni drugega razen enega Boga, Očeta, od katerega so vse stvari in mi v njem; in en Gospod Jezus Kristus, po katerem so vse stvari in mi po njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Vendar to spoznanje ne obstaja v vsakem človeku; kajti nekateri z vestjo malikov do te ure to jedo kot stvar, darovano maliku; in njihova slabotna vest je omadeževana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Toda jed nas ne približa Bogu; kajti niti če jemo, nismo boljši; niti če ne jemo, nismo slabši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Toda pazite, da ne bi na kakršenkoli način ta vaša svoboda postala kamen spotike tem, ki so slabotni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Kajti če te katerikoli človek, ki ima spoznanje, vidi v templju malikov sedeti pri jedi, ali ne bo njegova vest, ki je slabotna, postala ohrabrena, da jé te stvari, ki so darovane malikom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'in zaradi tvojega spoznanja bo propadel slaboten brat, za katerega je Kristus umrl?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Toda kadar tako grešite proti bratom in prizadenete njihovo slabotno vest, grešite zoper Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Zatorej, če jed stori, da se moj brat pohujša, dokler stoji svet ne bom jedel mesa, da ne bi svojega brata primoral grešiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Mar nisem apostol? Ali nisem svoboden? Mar nisem videl Jezusa Kristusa, našega Gospoda? Mar niste vi moje delo v Gospodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Če nisem apostol drugim, sem pa nedvomno vam; kajti vi ste pečat mojega apostolstva v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Moj odgovor tem, ki me zaslišujejo, je ta:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, '›Ali nimamo pravice jesti in piti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Ali nimamo pravice okrog voditi sestro, ženo, prav tako kakor drugi apostoli in kakor Gospodovi bratje ter Kefa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ali se samo jaz in Barnaba nimava pravice zadržati pred delom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kdo se kadarkoli gre vojskovanje na svoje lastne stroške? Kdo zasaja vinograd, pa ne jé od sadov le-tega? Ali kdo pase trop, pa ne jé mleka od tropa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Ali govorim te besede kakor človek? Ali ne govori istega tudi postava?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Kajti v Mojzesovi postavi je pisano: ›Ne boš zavezal gobca volu, ki mane žito.‹ Ali Bog skrbi za vole?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Ali govori to predvsem zaradi nas? Zaradi nas, brez dvoma, tako je pisano; da naj bi tisti, ki orje, oral v upanju; in da bi bil tisti, ki mlati v upanju soudeleženec njegovega upanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Če smo vam sejali duhovne stvari, ali je velika stvar, če bomo želi vaše mesene stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Če so drugi udeleženci te pravice nad vami, ali nismo tem bolj mi? Pa vendar te pravice nismo uporabili, temveč vse stvari prenašamo, da ne bi ovirali Kristusovega evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ali ne veste, da tisti, ki služijo pri svetih stvareh, živijo od tempeljskih stvari? In da so tisti, ki prisostvujejo pri oltarju, udeleženci z oltarjem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Točno tako je Gospod odredil, da naj tisti, ki oznanjajo evangelij, živijo od evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Toda sam nisem uporabil nobene od teh stvari niti nisem napisal teh stvari, da naj bi se mi tako zgodilo. Kajti zame bi bilo bolje, da umrem, kakor da bi katerikoli človek onemogočil moje ponašanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Kajti čeprav oznanjam evangelij, se nimam s čim ponašati, ker je name položena nuja; da, gorje meni, če ne oznanjam evangelija!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Kajti če to stvar počnem voljno, imam nagrado. Toda če proti svoji volji, mi je bilo zaupano razdeljevanje evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Kaj je potem moja nagrada? Resnično, da kadar oznanjam evangelij, smem narediti Kristusov evangelij brezplačen, da ne bi izkoriščal svoje pravice v evangeliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Kajti čeprav sem osvobojen vseh ljudi, sem vendar sebe naredil služabnika vsem, da bi jih lahko več pridobil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'In Judom sem postal kakor Jud, da bi lahko pridobil Jude; tem, ki so pod postavo, kakor pod postavo, da bi lahko pridobil te, ki so pod postavo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'tem, ki so brez postave, kakor brez postave (ne brez postave Bogu, temveč pod Kristusovo postavo), da bi lahko pridobil te, ki so brez postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Slabotnim sem postal kakor slaboten, da lahko pridobim slabotne. Storil sem vse stvari vsem ljudem, da bi jih vsekakor nekaj rešil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'In to počnem zaradi evangelija, da bom lahko z vami udeleženec le-tega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Mar ne veste, da tisti, ki tečejo na tekmi, vsi tečejo, toda eden prejme nagrado? Tako tecite, da jo lahko dosežete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Vsak pa, ki si prizadeva za nagrado, je zmeren v vseh stvareh. Torej oni to počno, da dosežejo ovenljiv venec; toda mi neovenljivega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Zatorej tako tečem, ne kakor negotovo; tako se borim, ne kakor nekdo, ki tolče zrak;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'temveč potlačim svoje telo in ga privedem v podložnost, da ne bi bil na kakršenkoli način, ko sem oznanjal drugim, sam bil zavržen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Poleg tega bratje nočem, da vi ne bi premislili, da so bili vsi naši očetje pod oblakom in so vsi šli skozi morje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'in vsi so bili krščeni v Mojzesa, v oblaku in v morju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'in vsi so jedli isto duhovno jed,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'in vsi so pili isto duhovno pijačo. Kajti pili so iz te duhovne Skale, ki jih je spremljala. In ta Skala je bil Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Toda z mnogimi izmed njih Bog ni bil zelo zadovoljen; zato so bili zrušeni v divjini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Torej te stvari so bile naši zgledi, z namenom, da mi ne bi hlepeli po zlih stvareh, prav tako kakor so oni poželeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Niti ne bodite malikovalci, kakor so bili nekateri izmed njih; kakor je pisano: ›Ljudje so se usedli, da bi jedli in pili in vstali, da bi se zabavali.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Niti ne zagrešimo prešuštvovanja, kakor so storili nekateri izmed njih in [jih] je v enem dnevu padlo triindvajset tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Niti ne skušajmo Kristusa, kakor so skušali tudi nekateri izmed njih in so bili pokončani od kač.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Niti ne godrnjajte, kakor so tudi nekateri izmed njih godrnjali in so bili pokončani od uničevalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Torej vse te stvari so se jim zgodile za zglede. Napisane pa so v svarilo nam, nad katere so prišli konci sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Zato naj tisti, ki misli, da stoji, pazi, da ne pade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nobene preizkušnje niste prestali razen takšne, ki je človeku običajna. Toda Bog je zvest, ki ne bo dovolil, da bi bili skušani nad tem, kar ste zmožni; toda s preizkušnjo bo prav tako pripravil pot za pobeg, da jo boste lahko prestali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Moji srčno ljubljeni, bežite torej od malikovanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Govorim kot modrim možem; presodite, kaj govorim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Mar ni čaša blagoslova, ki jo blagoslavljamo, udeležba pri Kristusovi krvi? Mar ni kruh, ki ga lomimo, udeležba pri Kristusovem telesu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Kajti mi, ki nas je mnogo, smo en kruh in eno telo; ker smo vsi udeleženci tega enega kruha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Glejte Izrael po mesu. Mar niso tisti, ki jedo od žrtev, udeleženci oltarja?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Kaj torej pravim? Da je malik kaj, ali je to, kar je darovano v žrtvovanje malikom kaj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Temveč pravim, da stvari, ki jih pogani žrtvujejo, žrtvujejo hudičem, ne pa Bogu; in ne želim, da bi vi imeli družbo s hudiči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ne morete piti Gospodove čaše in čaše hudičev. Ne morete biti udeleženci Gospodove mize in mize hudičev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Ali Gospoda dražimo do ljubosumnosti? Ali smo močnejši od njega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Dovoljene so mi vse stvari, toda vse stvari niso koristne. Dovoljene so mi vse stvari, toda vse stvari ne izgrajujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Naj noben človek ne išče svojega lastnega, temveč vsak srečo drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Karkoli se prodaja v mesnicah, to jejte, ne postavljajoč nobenih vprašanj glede vesti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'kajti Gospodova je zemlja in njena polnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Če vas kdorkoli od teh, ki ne veruje, povabi na pojedino in ste pripravljeni, da greste; jejte karkoli je postavljeno pred vas in ne sprašujte se nobenih vprašanj glede vesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, '§ Toda če vam katerikoli človek reče: »To je darovano v žrtev malikom,« ne jejte zaradi tistega, ki je to pokazal in zaradi vesti; kajti zemlja je Gospodova in njena polnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Vesti pravim, ne tvoje lastne, temveč od drugega; kajti zakaj je moja svoboda sojena od vesti drugega človeka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Kajti če sem udeleženec po milosti, zakaj sem obrekovan zaradi tega, za kar se zahvaljujem?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Če torej jeste ali pijete ali delate karkoli, vse to delajte v Božjo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne dajajte nobenega povoda, niti Judom, niti poganom, niti Božji cerkvi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'tako kakor jaz v vseh stvareh ugajam vsem ljudem in ne iščem svoje lastne koristi, temveč korist mnogih, da bodo oni lahko rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Bodite moji posnemovalci, celó kakor sem tudi jaz Kristusov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Hvalim vas torej, bratje, da se me spominjate v vseh stvareh in se držite odredb, kakor sem vam jih izročil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Toda želel bi, da veste, da je glava vsakemu možu Kristus; in glava ženski je mož; in glava Kristusu je Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Vsak mož, ki moli ali prerokuje in ima svojo glavo pokrito, onečašča svojo glavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Toda vsaka ženska, ki moli ali prerokuje s svojo nepokrito glavo, onečašča svojo glavo; ker je to celó isto, kakor če bi bila ostrižena na kratko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Kajti če se ženska ne pokriva, naj bo tudi ostrižena; toda če je za žensko sramotno, da bi bila ostrižena ali ostrižena na kratko, naj bo pokrita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Kajti mož zares ne bi smel pokrivati svoje glave, ker je podoba in slava Boga; toda ženska je slava moškega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Kajti moški ni iz ženske, temveč ženska iz moškega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Niti ni bil moški ustvarjen zaradi ženske, temveč ženska zaradi moškega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Zaradi tega razloga mora ženska na svoji glavi imeti oblast, zaradi angelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Pa vendar v Gospodu ni niti moškega brez ženske niti ženske brez moškega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Kajti kakor je ženska iz moškega, točno tako je tudi moški po ženski; toda vse stvari od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Presodite v sebi; ali je primerno, da ženska nepokrita moli k Bogu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Ali vas ne uči celó sama narava, če ima moški dolge lase, da je to njemu sramota?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Toda če ima ženska dolge lase, je njej to slava, kajti lasje so ji dani za pokrivalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Toda če je katerikoli človek videti prepirljiv, mi take navade nimamo niti Božje cerkve ne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Torej s tem, kar vam navajam, vas ne hvalim, ker se ne shajate na boljše, temveč na slabše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Kajti predvsem, ko se shajate v cerkvi, slišim, da so med vami nesoglasja; in deloma temu verjamem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Kajti med vami morajo biti tudi krivoverci, da se med vami lahko razodenejo tisti, ki so preizkušeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Ko torej pridete skupaj na en kraj, to ni, da jeste Gospodovo večerjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Ker pri jedi vsakdo poprej vzame svojo lastno večerjo; in je eden lačen, drugi pa pijan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Kaj? Mar nimate hiš, da bi v njih jedli in pili? Ali prezirate Božjo cerkev in sramotite te, ki nimajo? Kaj naj vam rečem? Naj vas hvalim v tem? Ne hvalim vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Kajti od Gospoda sem prejel to, kar sem vam tudi izročil: »Da je Gospod Jezus isto noč, v kateri je bil izdan, vzel kruh');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'in ko se je zahvalil, ga je razlomil in rekel: ›Vzemite, jejte. To je moje telo, ki je zlomljeno za vas. To delajte v moj spomin.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Na isti način je vzel tudi čašo, ko je srknil, rekoč: ›Ta čaša je nova zaveza v moji krvi. To delajte tako pogosto, kot to pijete, v moj spomin.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Kajti tako pogosto, kot jeste ta kruh in pijete to čašo, razodevate Gospodovo smrt, dokler ne pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Zato kdorkoli bo nevredno jedel ta kruh in pil to Gospodovo čašo, bo kriv Gospodovega telesa in krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Toda vsak človek naj izpraša samega sebe in naj tako jé od tega kruha in pije od te čaše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Kajti kdor jé in pije nevredno, jé in pije obsodbo samemu sebi in ne razpoznava Gospodovega telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Zaradi tega razloga so mnogi med vami slabotni in bolehni in mnogi spijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Kajti če bi sodili sami sebe, bi ne bili sojeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, '§ Toda ko smo sojeni, smo okarani od Gospoda, da ne bi bili obsojeni s svetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Zatorej, moji bratje, kadar pridete skupaj, da jeste, počakajte drug na drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'In če je katerikoli človek lačen, naj jé doma, da se ne shajate v obsodbo. Ostalo pa bom uredil, ko pridem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Torej glede duhovnih darov, bratje, vas ne bi hotel imeti nevedne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vi veste, da ste bili pogani, zapeljani k tem nemim malikom, celó kakor ste bili vodeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Zatorej vam dajem razumeti, da nihče, ki govori po Božjem Duhu, ne imenuje Jezusa preklet; in da noben človek ne more reči, da Jezus je Gospod, razen po Svetem Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Torej obstaja raznolikost darov, toda isti Duh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'In obstaja drugačnost služenj, toda isti Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'In obstaja raznolikost del, toda to je isti Bog, ki dela vse v vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Toda manifestacija Duha je dana vsakemu človeku, da s tem koristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Kajti enemu je po Duhu dana beseda modrosti; drugemu po istem Duhu beseda spoznanja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'drugemu vera po istem Duhu; še drugemu po istem Duhu darovi ozdravljanja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'drugemu delanje čudežev; drugemu prerokba; drugemu razpoznavanje duhov; drugemu številne vrste jezikov; drugemu razlaga jezikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Toda vse to počne ta en in točno isti Duh, ki vsakemu človeku razdeljuje posamično, kakor on hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Kajti kakor je telo eno in ima mnogo udov in so vsi udi od tega enega telesa, čeprav mnogi, so eno telo; tako je tudi Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Kajti po enem Duhu smo vsi krščeni v eno telo, bodisi smo Judje ali pogani, bodisi smo vezani ali svobodni; vsi pa smo bili napojeni v enem Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Kajti telo ni en ud, temveč mnogo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Če bo stopalo reklo: »Ker nisem roka, nisem od telesa;« ali potemtakem ni od telesa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'In če bo uho reklo: »Ker nisem oko, nisem od telesa;« ali potemtakem ni od telesa?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Če bi bilo celotno telo oko, kje bi bil sluh? Če bi bilo celotno sluh, kje bi bil vonj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Toda sedaj je Bog vsakega od teh udov razporedil po telesu, kakor mu je ugajalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'In če bi bili vsi en ud, kje bi bilo telo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Vendar so sedaj oni številni udje, vendar samo eno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'In oko ne more reči roki: »Ne potrebujem te,« prav tako tudi ne glava stopalu: »Ne potrebujem te.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Ne, potrebnih je veliko več teh telesnih udov, ki so videti slabotnejši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'In ti telesni udje, za katere mislimo, da so manj častitljivi, na te podelimo obilnejšo čast; in naši neprivlačni deli imajo obilnejšo ljubkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Kajti naši ljubki deli nimajo potrebe; toda Bog je pripravil skupaj telo in dal obilnejšo čast temu delu, ki trpi pomanjkanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'da v telesu ne bi bilo razkola; temveč, da bi imeli udje enako skrb drug za drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'In če en ud trpi, vsi udje trpijo z njim; ali [če] je en ud spoštovan, se vsi udje veselijo z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Torej vi ste Kristusovo telo in predvsem udje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'In Bog je postavil nekatere v cerkvi, najprej apostole, drugič preroke, tretjič učitelje, nató čudeže, potem darove ozdravljanj, pomoči, upravljanj, raznolikost jezikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'So vsi apostoli? So vsi preroki? So vsi učitelji? So vsi delavci čudežev?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Imajo vsi darove ozdravljanja? Ali vsi govorijo z jeziki? Ali vsi razlagajo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Toda iskreno hrepenite po najboljših darovih; in vendar vam pokažem še odličnejšo pot.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Čeprav govorim s človeškimi in angelskimi jeziki, pa nimam ljubezni, sem postal kakor brneč bron ali zveneča cimbala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'In čeprav imam dar preroštva in razumem vse skrivnosti in vsa spoznanja; in čeprav imam vso vero, tako da lahko premikam gore, pa nimam ljubezni, nisem nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'In čeprav podelim vse svoje dobrine, da nahranim revne in čeprav izročim svoje telo, da bi izgorelo, nimam pa ljubezni, mi to nič ne koristi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Ljubezen dolgo prenaša in je prijazna; ljubezen ni nevoščljiva; ljubezen sebe ne povzdiguje, ni napihnjena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'se ne ponaša nespodobno, ne išče svojega lastnega, ni lahko izzvana, ne misli zlega;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'ne razveseljuje se v krivičnosti, temveč se razveseljuje v resnici;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'prenese vse stvari, veruje vsem stvarem, upa [v] vse stvari, vzdrži vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Ljubezen nikoli ne izneveri. Toda če bodo preroštva, bodo prenehala; če bodo jeziki, bodo prenehali; če bo spoznanje, bo to izginilo proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Kajti spoznavamo deloma in prerokujemo deloma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Toda ko pride to, kar je popolno, takrat bo to, kar je deloma, odpravljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Ko sem bil otrok, sem govoril kakor otrok, razumel kakor otrok, mislil kakor otrok. Toda ko sem postal mož, sem otročje stvari dal stran.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, '§ Kajti sedaj vidimo skozi steklo, temno; toda takrat iz obličja v obličje; sedaj spoznavam deloma, toda takrat bom spoznal enako, kakor sem bil tudi spoznan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'In sedaj ostajajo vera, upanje, ljubezen, to troje; toda največja od teh je ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Prizadevajte si za ljubezen in želite si duhovne darove, toda rajši, da boste lahko prerokovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, '§ Kajti kdor govori v neznanem jeziku, ne govori ljudem, temveč Bogu, kajti noben človek ga ne razume, čeprav v duhu govori skrivnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Toda kdor prerokuje, govori ljudem v izgrajevanje, spodbudo in tolažbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kdor govori v neznanem jeziku, izgrajuje sebe; toda kdor prerokuje, izgrajuje cerkev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Hočem, da vi vsi govorite z jeziki, toda rajši, da prerokujete. Kajti večji je, kdor prerokuje, kakor kdor govori z jeziki, razen če razlaga, da lahko cerkev prejme izgrajevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Torej bratje, če pridem k vam, govoreč z jeziki, kaj vam bom koristil, razen če vam ne bom govoril ali po razodetju ali po spoznanju ali po prerokovanju ali po nauku?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'In celó stvari brez življenja dajejo zvok, bodisi piščal ali harfa [in] razen če ne dajo razlike v zvokih, kako bo razpoznano kaj je piskano ali harfano?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Kajti če trobenta da nerazločen zvok, kdo se bo pripravil za boj?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tako tudi vi, razen če ne boste z jezikom izrekli lahko razumljivih besed, kako se bo izvedelo, kar je rečeno? Kajti v zrak boste govorili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Obstaja, kakor se vé, tako veliko vrst glasov in nobeden od njih ni brez pomena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Zatorej, če ne vem pomena glasu, bom temu, ki govori, tujec in kdor govori, bo zame tujec.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tako si tudi vi, ker ste vneti za duhovne darove, prizadevajte, da se boste lahko izkazali pri izgrajevanju cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Zatorej naj tisti, ki govori v neznanem jeziku, moli, da bo lahko razlagal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Kajti če molim v neznanem jeziku, moli moj duh, toda moje razumevanje je brez sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Kaj je to torej? Molil bom z duhom in molil bom tudi z razumom; pel bom z duhom in pel bom tudi z razumom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Sicer, ko boš blagoslavljal z duhom, kako bo, kdor zavzema prostor nepoučenega, ob tvojem zahvaljevanju rekel: »Amen,« glede na to, da ne razume, kar praviš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Kajti ti resnično daješ prisrčno zahvalo, toda drug ni izgrajen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Zahvaljujem se svojemu Bogu, bolj kakor vi vsi govorim z jeziki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Vendar v cerkvi raje spregovorim pet besed s svojim razumom, da bi lahko s svojim glasom poučil tudi druge, kakor deset tisoč besed v neznanem jeziku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bratje, ne bodite otroci v razumevanju. Čeprav ste v zlobnosti otroci, vendar v razumevanju bodite možje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'V postavi je pisano: ›Z ljudmi drugih jezikov in drugih ustnic bom govoril tem ljudem; in vendar me kljub vsemu temu ne bodo slišali,‹ govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Zato so jeziki za znamenje, ne tem, ki verujejo, temveč tem, ki ne verujejo. Toda prerokovanje ne služi tem, ki ne verujejo, temveč tem, ki verujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Če bi torej celotna cerkev prišla skupaj na en kraj in bi vsi govorili z jeziki in vstopijo tisti, ki so nepoučeni ali neverniki, ali ne bodo rekli, da ste blazni?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Toda če vsi prerokujejo in vstopi nekdo, ki ne veruje ali nekdo nepoučen, je prepričan od vseh, je sojen od vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'In tako so razodete skrivnosti njegovega srca; in tako pade na svoj obraz in bo oboževal Boga ter naznanil, da je Bog resnično v vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Kako je to potem, bratje? Ko pridete skupaj, ima vsak izmed vas psalm, ima nauk, ima jezik, ima razodetje, ima razlago. Naj bodo vse stvari storjene k izgrajevanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, '§ Če katerikoli človek govori v neznanem jeziku, naj bosta po dva ali največ po trije in to po vrsti; eden pa naj razlaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Toda če tam ni razlagalca, naj v cerkvi molči; govori pa naj sebi in Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Naj spregovorijo dva ali trije preroki, drugi pa naj sodijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Če je katerakoli stvar razodeta drugemu, ki sedi v bližini, naj prvi molči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Kajti vsi lahko prerokujete eden za drugim, da se vsi lahko učijo in ste vsi lahko potolaženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'In duhovi prerokov so podrejeni prerokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Kajti Bog ni povzročitelj zmešnjave, temveč miru, kakor v vseh cerkvah svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Naj vaše ženske v cerkvah molčijo, kajti ni jim dovoljeno govoriti; temveč jim je naročeno biti pod poslušnostjo, kakor pravi tudi postava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'In če se hočejo karkoli naučiti, naj doma vprašajo svoje soproge, kajti za ženske je sramotno, da v cerkvi govorijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Kaj? Ali je Božja beseda prišla od vas? Je dospela samo k vam?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Če katerikoli človek misli o sebi, da je prerok ali duhoven, naj prizna, da so besede, ki vam jih pišem, zapovedi od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Toda če je katerikoli človek neveden, naj bo neveden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Zato bratje, hrepenite da prerokujete in ne prepovejte govoriti z jeziki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Naj bodo vse stvari storjene spodobno in urejeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Poleg tega, bratje, vam razglašam evangelij, ki sem vam ga oznanil, ki ste ga tudi sprejeli in v katerem stojite;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'po katerem ste tudi rešeni, če obdržite v spominu, kar sem vam oznanil, razen če ste zaman verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Kajti predvsem sem vam izročil to, kar sem tudi sam prejel, kako je ta Kristus umrl za naše grehe, glede na pisma;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'in da je bil pokopan in da je bil tretji dan obujen, glede na pisma;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'in da ga je videl Kefa, nató dvanajsteri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Potem ga je hkrati videlo več kot petsto bratov; od katerih jih je večji del ostal do sedaj, toda nekateri so zaspali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Nató ga je videl Jakob, potem vsi apostoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'In zadnji od vseh sem ga videl tudi jaz, kakor nekdo rojen izven pravšnjega časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Kajti jaz sem najmanjši izmed apostolov, ki nisem primeren, da sem imenovan apostol, ker sem preganjal Božjo cerkev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Toda po Božji milosti sem, kar sem, in njegova milost, ki mi je bila podeljena, ni bila zaman; temveč sem se trudil bolj obilno kakor vsi oni. Vendar ne jaz, temveč Božja milost, ki je bila z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Torej bodisi sem bil jaz ali oni, takó oznanjamo in takó ste verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Torej če se oznanja Kristusa, ki je obujen od mrtvih, kako nekateri izmed vas pravite, da ni vstajenja mrtvih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Toda če ni bilo vstajenja mrtvih, potem Kristus ni obujen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Če pa Kristus ni bil obujen, potem je naše oznanjevanje prazno in je tudi vaša vera prazna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Da, spoznani smo [za] krive Božje priče, ker smo pričevali o Bogu, ki je obudil Kristusa; ki ga ni obudil, če je tako, da mrtvi ne vstajajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Kajti če mrtvi ne vstajajo, potem Kristus ni obujen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Če pa Kristus ni bil obujen, je vaša vera prazna; še vedno ste v svojih grehih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Tedaj so propadli tudi tisti, ki so zaspali v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Če imamo samo v tem življenju upanje v Kristusa, smo od vseh ljudi najbolj bedni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Toda sedaj je Kristus obujen od mrtvih in postal prvenec teh, ki so zaspali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Kajti odkar je po človeku prišla smrt, je po človeku prišlo tudi vstajenje mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Kajti kakor v Adamu vsi umrejo, bodo točno tako v Kristusu vsi oživljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Toda vsak po svojem lastnem redu; prvenec Kristus, zatem tisti, ki so Kristusovi, ob njegovem prihodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Potem pride konec, ko bo kraljestvo izročil Bogu, celó Očetu; ko bo odstranil vsako vladavino in vsako oblast ter moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Kajti on mora kraljevati, dokler ne položi vseh sovražnikov pod njegova stopala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Zadnji sovražnik, ki bo uničen, je smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Kajti vse stvari je položil pod njegova stopala. Toda ko pravi, vse stvari so položene pod njega, je očitno, da je tisti, ki je vse stvari položil pod njega, izvzet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'In ko mu bodo vse stvari podjarmljene, potem bo tudi Sin sebe podvrgel njemu, ki je vse stvari položil pod njega, da bo lahko Bog vse v vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Sicer kaj bodo storili tisti, ki se krščujejo za mrtve, če mrtvi sploh niso obujeni? Zakaj so bili potem krščeni za mrtve?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'In čemu mi vsako uro stojimo v nevarnosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Pri svojem veselju, ki ga imam v Kristusu Jezusu, našem Gospodu, izjavljam: »Vsak dan umiram.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Če sem se v Efezu po človeško boril z zvermi, kaj mi koristi, če mrtvi niso obujeni? Jejmo in pijmo, kajti jutri umremo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, '§ Ne bodite zavedeni. Zli pogovori pokvarijo dobre manire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Zbudite se k pravičnosti in ne grešite, kajti nekateri nimajo Božjega spoznanja. To vam govorim v vašo sramoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Toda nekateri ljudje bodo rekli: »Kako so mrtvi obujeni? In s kakšnim telesom pridejo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Ti bedak, to kar ti seješ, ne oživi, razen če ne umre.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'In to, kar ti seješ, ne seješ tega telesa, ki bo, temveč golo zrno, to je lahko pšenica ali neko drugo zrno;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'toda Bog mu daje telo, kakor mu ugaja in vsakemu semenu svoje lastno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ni vse meso isto meso, ampak je ena vrsta mesa od ljudi, drugo meso od živali, drugo od rib in drugo od ptic.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Tam so tudi nebesna telesa in zemeljska telesa; toda slava nebesnih je ena, slava zemeljskih pa je druga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Ena je slava sonca, druga slava lune in druga slava zvezd, kajti ena zvezda se od druge zvezde razlikuje po slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tako je tudi vstajenje mrtvih. Sejano je v trohljivosti, obujeno je v netrohljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Sejano je v nečast, dvignjeno je v slavo. Sejano je v slabosti, dvignjeno je v moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, '§ Sejano je v naravno telo, dvignjeno je duhovno telo. Obstaja naravno telo in obstaja duhovno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'In tako je pisano: ›Prvi človek Adam je postal živa duša;‹ zadnji Adam je postal oživljajoč duh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Vendar ni bilo najprej to, kar je duhovno, temveč to, kar je naravno, in potem to, kar je duhovno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Prvi človek je iz tal, zemeljski; drugi človek je Gospod iz nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Kakršen je zemeljski, takšni so tudi tisti, ki so zemeljski; in kakršen je nebeški, takšni so tudi tisti, ki so nebeški.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'In kakor smo nosili zemeljsko podobo, bomo nosili tudi nebeško podobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Torej povem to, bratje, da meso in kri ne moreta podedovati Božjega kraljestva; niti trohnenje ne podeduje netrohnenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Glejte, pokažem vam skrivnost: ›Ne bomo vsi zaspali, toda vsi bomo spremenjeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'v trenutku, kot bi trenil z očesom, ob zadnji trobenti, kajti trobenta bo zadonela in mrtvi bodo vstali netrohneči in mi bomo spremenjeni.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Kajti ta trohljivost si mora nadeti netrohljivost in to umrljivo si mora nadeti nesmrtnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Torej ko si bo ta trohljivost nadela netrohljivost in si bo to umrljivo nadelo nesmrtnost, tedaj se bo izpolnila beseda, ki je zapisana: ›Smrt je požrta v zmagi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '§ Oh smrt, kje je tvoje želo? Oh grob, kje je tvoja zmaga?‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Želo smrti je greh, moč greha pa je postava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Toda zahvaljen bodi Bog, ki nam daje zmago po našem Gospodu Jezusu Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Torej, moji ljubljeni bratje, bodite neomajni, nepremakljivi, vedno obilni v Gospodovem delu, ker veste, da vaš trud v Gospodu ni zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Torej glede nabirke za svete, kakor sem dal naročilo cerkvam v Galatiji, točno tako storite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Na prvi dan tedna naj vsak izmed vas položi poleg sebe v shrambo, kakor ga je Bog osrečil, da ne bo zbiranj, ko pridem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'In ko pridem, katerekoli boste z vašimi pismi priporočili, te bom poslal, da prinesejo vašo velikodušnost v Jeruzalem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Če pa bo primerno, da grem tudi jaz, bodo šli z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Torej, ko bom šel skozi Makedonijo, bom prišel k vam; kajti pojdem skozi Makedonijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, '§ In lahko bo, da bom ostal, da in prezimil z vami, da me boste lahko spremili na moje potovanje, kamorkoli pojdem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Kajti ne bom vas torej videl mimogrede; temveč zaupam, da ostanem nekaj časa z vami, če Gospod dovoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Toda v Efezu bom ostal do binkošti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Kajti velika in uspešna vrata so se mi odprla in tam je mnogo nasprotnikov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Torej če pride Timótej, glejte, da bo lahko z vami brez strahu, kajti opravlja Gospodovo delo, kakor ga opravljam tudi jaz.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Naj ga torej nihče ne prezira, temveč ga spremite v miru, da bo lahko prišel k meni, ker ga pričakujem z brati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Glede našega brata Apola, sem ga silno prosil, da pride z brati k vam, toda njegova volja sploh ni bila, da pride ob tem času; toda prišel bo, ko bo imel primeren čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Čujte, trdno stojte v veri, obnašajte se kakor možje, bodite močni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Naj bodo vse vaše stvari narejene z ljubeznijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Rotim vas, bratje (vi poznate Stefanájevo hišo, da je ta prvenec Ahaje in da so sebe posvetili službi svetim),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'da se takšnim podredite in vsakemu, ki pomaga z nami in se trudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, '§ Vesel sem Stefanájevega, Fortunatovega in Aháikovega prihoda, kajti preskrbeli so to, kar je manjkalo na vaši strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Kajti okrepčali so mojega in vašega duha; zatorej jim priznajte, da so takšni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdravljajo vas cerkve iz Azije. V Gospodu vas zelo pozdravljata Ákvila in Priska, s cerkvijo, ki je v njuni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdravljajo vas vsi bratje. Drug drugega pozdravite s svetim poljubom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdrav od mene, Pavla, z mojo lastno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Če kateri človek nima rad Gospoda Jezusa Kristusa, naj bo Anathema Maranatha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, '§ Milost našega Gospoda Jezusa Kristusa bodi z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Moja ljubezen bodi z vami vsemi v Kristusu Jezusu. Amen. [Prva poslanica Korinčanom je bila napisana iz Filipov po Stefanáju in Fortunatu in Aháiku in Timóteju.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pavel, po Božji volji apostol Jezusa Kristusa, in naš brat Timótej Božji cerkvi, ki je v Korintu, z vsemi svetimi, ki so po vsej Ahaji:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Blagoslovljen bodi Bog, celó Oče našega Gospoda Jezusa Kristusa, Oče usmiljenj in Bog vse tolažbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'ki nas tolaži v vsaki naši stiski, da bomo sposobni tolažiti te, ki so v kakršnikoli težavi, s tolažbo, s katero smo mi sami potolaženi od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Kajti kakor so Kristusova trpljenja obilna v nas, tako je obilna tudi naša tolažba po Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Če pa smo stiskani, je to za vašo tolažbo in rešitev duš, ki je učinkovita v prestajanju istih trpljenj, ki jih tudi mi prenašamo; ali če smo potolaženi, je to zaradi vaše tolažbe in rešitve duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'In naše upanje o vas je neomajno, vedoč, da kakor ste udeleženci trpljenj, tako boste postali tudi tolažbe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Kajti nočemo, bratje, da bi bili vi nevedni o naši težavi, ki je k nam prišla v Aziji, da smo bili stiskani preko mere, nad močjo, tako zelo, da smo obupali celó nad življenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Toda v sebi smo imeli smrtno obsodbo, da ne bi zaupali vase, temveč v Boga, ki obuja mrtve;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'ki nas je osvobodil iz tako velike smrti in še osvobaja; v katerega zaupamo, da nas bo še osvobajal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Tudi vi skupaj pomagate z molitvijo za nas, da bi bila lahko zaradi daru, podarjenega nam, s pomočjo mnogih oseb, dana zahvala z naše strani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Kajti naše veselje je to, pričevanje naše vesti, da smo se v svetu vedli s preprostostjo in pobožno iskrenostjo, ne z meseno modrostjo, temveč z Božjo milostjo in bolj obilno posebej do vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Kajti ne pišemo vam nobenih drugih stvari, kakor kar berete ali spoznavate; in zaupam, da boste spoznali celó do konca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'kakor ste nas tudi vi deloma spoznali, da smo mi vaše veselje, celó kakor ste tudi vi naše na dan Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'V tem zaupanju sem bil voljan prej priti k vam, da bi vi lahko imeli dvojno korist;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'in mimo vas iti v Makedonijo in iz Makedonije ponovno priti k vam in bi bil od vas pospremljen na svoji poti proti Judeji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Ko sem bil torej takih misli, ali sem uporabil lahkomiselnost? Ali stvari, ki jih nameravam, nameravam storiti glede na meso, da bo z menoj »da,« »da« in »ne,« »ne«?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Toda kakor je Bog resničen, naša beseda do vas ni bila »da« in »ne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Kajti Božji Sin, Jezus Kristus, ki je bil med vami oznanjen po nas, celó po meni in Silvánu ter Timóteju, ni bil »da« in »ne,« temveč je bil v njem »da.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Kajti vse Božje obljube so v njem »da« in v njem »Amen« v Božjo slavo po nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Torej tisti, ki nas z vami utrjuje v Kristusu in nas je mazilil, je Bog;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'ki nas je tudi zapečatil in v naša srca dal poroštvo Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Poleg tega kličem Boga za pričo nad svojo dušo, da doslej še nisem prišel k vam v Korint, da bi vam prizanesel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ne, ker bi imeli gospostvo nad vašo vero, temveč smo pomočniki vaše radosti; kajti stojite po veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Toda sam pri sebi sem sklenil, da k vam ne bom ponovno prišel s potrtostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Kajti če vas užalostim, kdo je torej tisti, ki me razveseljuje, razen istega, ki je po meni užaloščen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'In to isto sem napisal vam, da ne bi, ko pridem, imel bridkost od teh, od katerih bi se moral veseliti; ker imam zaupanje v vas vse, da je moje veselje veselje vas vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Kajti iz precejšnje stiske in tesnobe srca sem vam pisal z mnogimi solzami; ne da bi bili vi užaloščeni, temveč da bi lahko spoznali ljubezen, ki jo imam bolj obilno do vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Toda če je kdorkoli povzročil žalost, ni užalostil mene, temveč deloma, da vas ne bom vse preobremenil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Takšnemu človeku je primerna ta kazen, katera [mu] je bila naložena od večine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tako da mu morate nasprotno vi raje odpustiti in ga potolažiti, da ne bi bil mogoče tak požrt s preveliko bridkostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Zatorej vas rotim, da boste potrdili svojo ljubezen do njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Kajti zato sem vam tudi pisal, da bi lahko spoznal dokaz o vas, če ste v vseh stvareh poslušni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Komur kaj odpustite, odpuščam tudi jaz. Kajti če sem kaj odpustil, komur sem zaradi vas to odpustil, sem to odpustil v Kristusovi osebi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, '§ da Satan ne bi pridobil prednosti pred nami; kajti o njegovih naklepih nismo nevedni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Nadalje, ko sem prišel v Troádo, da oznanim Kristusov evangelij in so mi bila odprta vrata v Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'v svojem duhu nisem imel počitka, ker nisem našel svojega brata Tita. Toda ko sem se od njih poslovil, sem od tam odšel v Makedonijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Torej hvala bodi Bogu, ki nam vedno povzroča, da slavimo zmago v Kristusu in po nas na vsakem kraju razodeva vonj njegovega spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Kajti Bogu smo prijeten Kristusov vonj med temi, ki so rešeni in med temi, ki se pogubljajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Nekomu smo vonj po smrti za smrt, drugemu pa vonj po življenju za življenje. In kdo je primeren za te stvari?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, '§ Kajti nismo kakor mnogi, ki kvarijo Božjo besedo; temveč kot iz iskrenosti, vendar kot od Boga, v Božjih očeh govorimo v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Ali ponovno začenjamo priporočati sami sebe? Ali potrebujemo, kot nekateri drugi, za vas priporočilne poslanice ali priporočilna pisma od vas?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vi ste naša poslanica, napisana v naših srcih, od vseh ljudi poznana in brana,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'ker ste vidno oznanili, da ste Kristusova poslanica, dana po nas, ne napisana s črnilom, temveč z Duhom živega Boga; ne na kamnite plošče, temveč na mesene plošče srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'In tako zaupanje imamo po Kristusu usmerjeno k Bogu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'ne da smo sami zadostni, da mislimo karkoli kakor od nas samih, temveč je naša zadostnost od Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'ki nas je tudi storil zmožne služabnike nove zaveze; ne po črki, temveč po duhu; kajti črka ubija, toda duh daje življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Toda če je bilo veličastno služenje smrti, zapisano in vrezano v kamne, tako da Izraelovi otroci, zaradi slave njegove zunanjosti, niso mogli neomajno gledati Mojzesovega obraza, katerega slava je bila odpravljena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'kako ne bo služba duha precej veličastnejša?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Kajti če je služba obsodbi slava, [jo] služba pravičnosti veliko bolj prekaša v slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Kajti celó to, kar je postalo slavno, v tem oziru ni imelo slave, zaradi slave, ki prekaša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Kajti če je bilo slavno to, kar je bilo odpravljeno, je veliko bolj slavno to, kar ostaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ker imamo torej tolikšno upanje, uporabljamo veliko razumljivost govora,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'in ne kakor Mojzes, ki si je prek svojega obraza nadel zagrinjalo, da Izraelovi otroci niso mogli neomajno gledati konca tega, kar je odpravljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Toda njihovi umi so bili zaslepljeni. Kajti do danes ostaja pri branju Stare zaveze isto zagrinjalo neodgrnjeno; katere zagrinjalo je odpravljeno v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Toda celó do današnjega dne, kadar se bere Mojzes, je na njihovem srcu zagrinjalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Pa vendar, ko se bodo obrnili h Gospodu, bo zagrinjalo odvzeto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Torej Gospod je ta Duh, in kjer je Gospodov Duh, tam je svoboda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Toda mi vsi, ki z odgrnjenim obrazom gledamo kakor v steklu Gospodovo slavo, smo iz slave v slavo preobraženi v isto podobo, celó kakor po Gospodovem Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Ker imamo to službo, kakor smo prejeli usmiljenje, ne omahujemo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'temveč smo se odrekli skritim stvarem nepoštenosti in ne hodimo v prebrisanosti niti z Božjo besedo ne ravnamo varljivo, temveč se z manifestacijo resnice v Božjih očeh priporočamo vesti vsakega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Toda če je naš evangelij skrit, je skrit tistim, ki so izgubljeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'v katerih je bog tega sveta zaslepil misli tistih, ki ne verujejo, da jim ne bi zasijala svetloba veličastnega Kristusovega evangelija, ki je podoba Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Kajti ne oznanjamo sebe, temveč Kristusa Jezusa, Gospoda; in sebe, vaše služabnike, zaradi Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Kajti Bog, ki je zapovedal svetlobi, da zasije iz teme, je zasijal v naših srcih, da nudi svetlobo spoznanja Božje slave na obrazu Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Toda ta zaklad imamo v lončenih posodah, da bi bila odličnost moči lahko od Boga in ne od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Na vsaki strani smo vznemirjeni, vendar ne v tegobi; zmedeni smo, vendar ne v obupu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'preganjani, toda ne zapuščeni; mêtani [ob tla], toda ne uničeni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'vedno v telesu naokrog prenašamo umiranje Gospoda Jezusa, da bi se lahko tudi v našem telesu razodelo Jezusovo življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Kajti mi, ki živimo, smo zaradi Jezusa nenehno izročani v smrt, da bi se tudi Jezusovo življenje lahko razodelo v našem umrljivem mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Tako potem v nas deluje smrt, toda v vas življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Ker imamo istega duha vere, glede na to, kakor je pisano: ›Veroval sem in zato sem govoril;‹ tudi mi verujemo in zato govorimo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'vedoč, da tisti, ki je obudil Gospoda Jezusa, bo po Jezusu obudil tudi nas in nas postavil z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Kajti vse stvari so zaradi vas, da bi lahko obilna milost zaradi zahvaljevanja mnogih prekipevala v Božjo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Zaradi tega razloga ne omagujemo; kajti kljub temu, da naš zunanji človek umira, je vendarle naš notranji človek iz dneva v dan obnovljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Kajti naša lahka stiska, ki je samo za trenutek, opravlja za nas veliko večjo, presegajočo in večno težo slave;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'medtem ko ne gledamo na stvari, ki so vidne, temveč na stvari, ki so nevidne. Kajti stvari, ki so vidne, so začasne, toda stvari, ki so nevidne, so večne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Kajti vemo, da če bi naša zemeljska hiša tega šotorskega svetišča razpadla, imamo v nebesih večno Božjo stavbo, hišo ne narejeno z rokami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Kajti v tem stokamo in iskreno želimo, da bi se povrh odeli z našo hišo, ki je iz nebes;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, '§ če je tako, da ko bomo oblečeni, ne bi bili najdeni goli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Kajti mi, ki smo v tem šotoru, obteženi stokamo. Ne zato, ker hočemo biti neoblečeni, temveč oblečeni povrh, da bi bila umrljivost lahko požrta z življenjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Torej kdor nas je naredil za točno isto stvar, je Bog, ki nam je dal tudi poroštvo Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Torej smo vedno zaupljivi, ker vemo, da medtem ko smo doma v telesu, smo odsotni od Gospoda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(kajti hodimo po veri, ne po pogledu).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Zaupljivi smo, pravim in voljni rajši biti odsotni iz telesa in biti prisotni z Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Zatorej se trudimo, da bomo bodisi prisotni ali odsotni, lahko pri njem sprejeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Kajti vsi se moramo prikazati pred Kristusovim sodnim stolom, da bo vsakdo lahko prejel stvari, storjene v svojem telesu, glede na to, kar je storil, bodisi je to dobro ali slabo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Ker torej poznamo Gospodov strah, pregovarjamo ljudi; toda Bogu smo postali očitni; in zaupam tudi, [da] smo postali očitni v svojih vesteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Kajti ne priporočamo se vam ponovno, temveč vam dajemo priložnost, da ste zavoljo nas ponosni, da boste imeli nekaj, da odgovorite tem, ki se ponašajo na zunaj, ne pa v srcu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Kajti če smo brez pameti, je to za Boga, ali če smo zdravega mišljenja, je to zaradi vaše stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Kajti sili nas Kristusova ljubezen; ker tako sodimo, da če je eden umrl za vse, potem so bili mrtvi vsi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'In da je umrl za vse, da tisti, ki živijo, odslej ne bi živeli več zase, temveč za tistega, ki je zanje umrl in ponovno vstal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Zatorej odslej nobenega človeka ne poznamo po mesu. Da, četudi smo Kristusa poznali po mesu, ga vendarle sedaj ne poznamo več [po mesu].');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, '§ Torej, če je katerikoli človek v Kristusu, je novo ustvarjeno bitje. Stare stvari so minile; glejte, vse stvari so postale nove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'In vse stvari so od Boga, ki nas je po Jezusu Kristusu spravil s seboj in nam dal službo pobotanja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'namreč, da je bil Bog v Kristusu, ko je svet pobotal s seboj, ker jim ni pripisal njihovih prekrškov, nam pa predal besedo sprave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Torej smo potem predstavniki za Kristusa, kakor da vas je po nas rotil Bog. Namesto Kristusa vas prosimo, bodite spravljeni z Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Kajti njega, ki ni poznal greha, je zaradi nas storil, da postane greh, da bi mi lahko postali Božja pravičnost v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Mi vas potem kot delavci skupaj z njim tudi rotimo, da Božje milosti niste prejeli zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(Kajti pravi: »Uslišal sem te v sprejemljivem času in na dan rešitve duše sem ti pomagal; glej, sedaj je odobren čas; glej, sedaj je dan rešitve duše.«)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Ne dajemo nobene spotike v nobeni stvari, da služba ne bo ošteta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Toda v vseh stvareh se priporočamo kakor Božji služabniki, v veliki potrpežljivosti, v stiskah, v potrebah, v tegobah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'v bičanjih, v ječah, pri uporih, v naporih, v bedenjih, v postih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 's čistostjo, s spoznanjem, s potrpežljivostjo, s prijaznostjo, s Svetim Duhom, z nehlinjeno ljubeznijo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'z besedo resnice, z Božjo močjo, z bojno opremo pravičnosti na desni roki in na levi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 's spoštovanjem in nespoštovanjem, na slabem in dobrem glasu; kakor sleparji, pa vendar iskreni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'kakor neznani, pa vendar dobro znani; kakor umirajoči in glej, živimo; kakor kaznovani, pa ne ubiti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'kakor žalostni, vendar vedno veseli; kakor ubogi, vendar mnoge bogatimo; kakor ne bi imeli nič, pa vendar posedujemo vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Oh vi Korinčani, naša usta so vam odprta, naše srce je širokosrčno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Vi niste omejeni v nas, temveč ste omejeni v svojih lastnih notranjostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Torej za povračilo v enakem (govorim vam kakor svojim otrokom), bodite tudi vi širokosrčni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne bodite neenako vpreženi skupaj z neverniki, kajti kakšno družbo ima pravičnost z nepravičnostjo? Ali kakšno udeležbo ima svetloba s temo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'In kakšno soglasje ima Kristus z Beliálom? Ali kakšen delež ima, kdor veruje, z neverniki?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, '§ In kakšno strinjanje ima Božji tempelj z maliki? Kajti vi ste tempelj živega Boga; kakor je rekel Bog: »Prebival bom v njih in hodil v njih in jaz bom njihov Bog in oni bodo moji ljudje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Zatorej pridite ven izmed njih in bodite oddvojeni,« govori Gospod »in nečiste stvari se ne dotikajte; in jaz vas bom sprejel');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'in vam bom Oče in vi boste moji sinovi in hčere,« govori Gospod Vsemogočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Ker imamo torej te obljube, srčno ljubljeni, se očistimo pred vso umazanijo mesa in duha ter v strahu Božjem dovršujmo svetost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, '§ Sprejmite nas; nikomur nismo storili krivice, nobenega človeka nismo pokvarili, nobenega človeka nismo ogoljufali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Tega ne govorim, da vas obsodim, kajti prej sem rekel, da ste v naših srcih, da z vami umremo in živimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Velika je moja drznost govora do vas, veliko je moje ponašanje glede vas. Napolnjen sem s tolažbo, silno radosten v vsej naši stiski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Kajti ko smo prišli v Makedonijo, naše meso ni imelo počitka, temveč smo bili stiskani na vsaki strani; zunaj so bili boji, znotraj so bili strahovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Kljub temu nas je Bog, ki tolaži te, ki so potrti, potolažil s Titovim prihodom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'pa ne samo z njegovim prihodom, temveč s tolažbo, s katero je bil potolažen med vami, ko nam je pripovedoval vašo iskreno željo, vaše žalovanje, vaše goreče mišljenje do mene; tako, da sem se tem bolj veselil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Kajti čeprav sem vas s pismom užalostil, se ne kesam, čeprav sem se kesal; kajti zaznavam, da vas je ista poslanica užalostila, čeprav je bilo to samo za nekaj časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Sedaj se veselim, ne da ste bili užaloščeni, temveč da ste [bili] užaloščeni do kesanja. Kajti užaloščeni ste bili na bogaboječ način, da od nas v ničemer ne bi prejeli škode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Kajti bogaboječa žalost opravlja kesanje v rešitev duše, ki se je ne bomo kesali, toda svetna žalost ustvarja smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Kajti glejte to točno isto stvar, da ste bili užaloščeni na bogaboječ način, kakšno skrbnost je to storilo v vas, da, kakšno čiščenje vas samih, da, kakšno ogorčenost, da, kakšen strah, da, kakšno silovito hrepenenje, da, kakšno gorečnost, da, kakšno maščevanje! V vseh stvareh ste sebe potrdili, da ste v tej zadevi čisti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Zatorej čeprav sem vam pisal, sem to storil ne zaradi razloga tistega, ki je storil krivico niti zaradi razloga tistega, ki je trpel krivico, temveč, da se vam lahko pokaže naša skrb za vas v Božjih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, '§ Torej smo bili potolaženi v vaši tolažbi. Da in silno bolj smo se veselili zaradi Titovega veselja, ker je bil po vas vseh njegov duh okrepčan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Kajti če sem se mu kakorkoli bahal z vami, nisem osramočen; temveč kakor smo vam govorili vse stvari v resnici, se je celó tako naše bahanje, ki sem ga storil pred Titom, izkazalo [za] resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'In njegova notranja strast je do vas obilnejša, medtem ko se spominja poslušnosti vas vseh, kako ste ga sprejeli s strahom in trepetanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Veselim se torej, da imam v vas zaupanje v vseh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Poleg tega, bratje, vam storimo, da veste o Božji milosti, podeljeni makedonskim cerkvam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'da je bila v veliki preizkušnji stiske obilica njihovega veselja in njihova globoka revščina obilna v bogastvih njihove velikodušnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Kajti po svoji moči, pričujem, da in preko svojih moči so bili sami voljni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'in [so] nas z mnogimi prošnjami prosili, da bi mi sprejeli dar in [oni] nase vzeli družbo služenja svetim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'In to so storili, ne kakor smo upali, temveč so najprej sebe izročili Gospodu in po Božji volji nam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tako, da smo prosili Tita, da kakor je začel, tako naj isto milost v vas tudi konča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Torej kakor ste obilni v vsaki stvari, v veri, izgovarjavi, spoznanju, v vsej marljivosti in v vaši ljubezni do nas, glejte, da ste obilni tudi v tej milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ne govorim po zapovedi, temveč z razlogom gorečnosti drugih in da dokažem iskrenost vaše ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Kajti poznate milost našega Gospoda Jezusa Kristusa, da čeprav je bil bogat, je vendar zaradi vas postal ubog, da bi po njegovi revščini vi lahko obogateli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'In v tem dajem svoj nasvet, kajti to je koristno za vas, ki ste prej začeli, ne samo delati, temveč ste bili prizadevni tudi pred enim letom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Zdaj torej izvršite to delo; da kakor je bila pripravljenost hoteti, tako bo lahko tudi izvršitev iz tega, kar imate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Kajti če je bil najprej voljan um, je sprejet glede na to, kar človek ima, in ne glede na to, česar nima.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Kajti ne mislim, da bi bili drugi ljudje olajšani, vi pa obteženi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'temveč prek enakosti, da lahko sedaj, ob tem času, vaše obilje postane oskrba za njihovo siromaštvo, da bo njihovo obilje lahko tudi oskrba za vaše siromaštvo, da bo lahko enakost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'kakor je pisano: ›Kdor je nabral veliko, ni imel ničesar preveč, in kdor je nabral malo, ni imel pomanjkanja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Toda zahvala bodi Bogu, ki je na Titovo srce položil isto iskreno skrb za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Kajti zares je sprejel spodbudo; toda ker je bil bolj prizadeven, je k vam odšel iz svojega lastnega nagiba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'In z njim smo poslali brata, katerega hvala v evangeliju je po vseh celotnih cerkvah;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'in ne samo to, temveč ki je bil tudi od cerkvá izbran, da potuje z nami s to milostjo, ki je po nas preskrbljena v slavo istega Gospoda in izjavi vašega pripravljenega mišljenja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'izogibajoč se temu, da nas noben človek ne bi mogel oštevati v tem obilju, ki je preskrbljeno po nas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'ko skrbimo za poštene stvari, ne samo v Gospodovih očeh, temveč tudi v očeh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'In z njima smo poslali našega brata, ki se nam je pogosto v mnogih stvareh izkazal marljivega, toda sedaj mnogo bolj marljivega na veliko zaupanje, ki ga imam v vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Če kdorkoli poizveduje o Titu, je glede vas moj družabnik in sopomočnik, ali če bodo poizvedovali o [dveh] naših bratih, sta odposlanca cerkvá in Kristusova slava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Zatorej pokažite njim in pred cerkvami dokaz svoje ljubezni in našega bahanja vam v prid.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Kajti glede služenja svetim, je zame odveč, da vam pišem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'kajti poznam pripravljenost vašega mišljenja, zaradi katerega se o vas baham tem iz Makedonije, da je bila Ahaja pripravljena pred enim letom; in vaša gorečnost je spodbudila zelo mnoge.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Vendar sem poslal brate, da ne bi bilo naše bahanje o vas, vam v prid, zaman; da boste, kakor sem rekel, vi lahko pripravljeni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'da ne bi bili morda, če pridejo z menoj tisti iz Makedonije in vas najdejo nepripravljene, mi (da ne rečem vi) osramočeni v tem istem zaupljivem bahanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Zatorej sem mislil, da je treba spodbuditi brate, da bi prej šli k vam in vnaprej pripravili vaš dar, o katerem ste prej imeli obvestilo, da bo isti lahko pripravljen kot resnična radodarnost in ne kakor od pohlepnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Toda rečem to: »Kdor varčno seje, bo tudi varčno žel; in kdor radodarno seje, bo tudi radodarno žel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Vsak naj tako da, glede na to, kakor se je nameril v svojem srcu; ne nejevoljno ali iz nuje, kajti Bog ljubi vedrega darovalca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'In Bog je zmožen storiti, da bo vsa milost obilna do vas, da boste vedno imeli vso zadostnost v vseh stvareh [in boste] lahko bogati za vsako dobro delo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, '(kakor je pisano: ›Razdelil je povsod, dal je revnim. Njegova pravičnost ostaja na veke.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Torej kdor daje seme sejalcu, daje tako kruh za vašo hrano, kakor množi vaše posejano seme in povečuje sadove vaše pravičnosti)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'obogateli ste v vsaki stvari za vso radodarnost, ki po nas povzroča zahvaljevanje k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Kajti služenje tej službi ni samo oskrba potreb svetih, temveč je po mnogih zahvaljevanjih tudi obilna Bogu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'čeprav s poskusom tega služenja proslavljajo Boga zaradi vaše izražene podložnosti Kristusovemu evangeliju in zaradi vaše velikodušne razdelitve njim in vsem ljudem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'in z njihovo molitvijo za vas, kateri zaradi silne Božje milost v vas hrepenijo po vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Hvala bodi Bogu za njegov neizrekljivi dar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Torej jaz sam, Pavel, ki sem v navzočnosti med vami pohleven, toda odsoten sem drzen do vas, vas pri Kristusovi krotkosti in blagosti rotim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Toda rotim vas, da ne bi bil drzen, ko sem prisoten s tem zaupanjem, s katerim mislim biti do nekaterih drzen, ki mislijo o nas, kakor da smo živeli glede na meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Kajti čeprav živimo v mesu, se ne borimo po mesu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(kajti orožja našega vojskovanja niso mesena, temveč mogočna po Bogu, da podirajo trdnjave);');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'podiramo zamisli in vsako visoko stvar, ki sebe povzdiguje proti spoznanju Boga ter vsako misel prinašamo v ujetništvo, v poslušnost Kristusu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'in v pripravljenosti smo, da maščujemo vso neposlušnost, ko se vaša poslušnost dopolni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Ali gledate na stvari po zunanjem videzu? Če katerikoli človek zaupa sebi, da je Kristusov, naj sam v sebi to ponovno razmisli, da kakor je on Kristusov, točno tako smo mi Kristusovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, '§ Kajti čeprav bi se malce bolj bahal z našo oblastjo, ki nam jo je Gospod dal za izgrajevanje in ne za vaše uničenje, ne bi bil osramočen;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'da ne bom videti, kakor če vas hočem strašiti s pismi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Kajti [za] njegova pisma, pravijo, [da] so tehtna in vplivna, toda njegova telesna prisotnost je šibka in njegov govor zaničevanja vreden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Naj takšni mislijo to, da takšni, kakor smo mi z besedo po črkah, ko smo odsotni, bomo takšni tudi v dejanju, ko smo prisotni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Kajti ne drznemo se meriti ali primerjati z nekaterimi, ki priporočajo sami sebe. Toda tisti, ki sebe merijo s seboj in se primerjajo med seboj, niso modri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Toda mi se ne bomo bahali o stvareh zunaj naše mere, temveč glede na mero oblasti, ki nam jo je Bog razdelil, mero, da smo segli celó do vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Kajti ne iztezamo se preko naše mere, kakor da nismo prispeli do vas, kajti z oznanjevanjem Kristusovega evangelija smo prišli tudi prav do vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'O stvareh se ne bahamo prek naše mere, to je z napori drugih ljudi, temveč imamo upanje, ko se vaša vera okrepi, da bomo obilno povečani po vas glede na naše območje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'da oznanimo evangelij v pokrajinah onstran vas in ne da se bahamo na področju drugega človeka o stvareh, ki so bile pripravljene k naši roki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Toda kdor se ponaša, naj se ponaša v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Kajti ni potrjen kdor priporoča sebe, temveč kogar priporoča Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Bog daj, da bi lahko z menoj malo zdržali v moji neumnosti, in zares potrpite z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Kajti nad vami sem ljubosumen z bogaboječo ljubosumnostjo, kajti zaročil sem vas z enim soprogom, da vas lahko kakor čiste device predstavim Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Toda bojim se, da ne bi bila na kakršenkoli način, kakor je kača s svojo premetenostjo preslepila Evo, tudi vaša mišljenja pokvarjena proč od preprostosti, ki je v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Kajti če tisti, ki prihaja, oznanja drugega Jezusa, ki ga nismo oznanili ali če sprejmete drugega duha, ki ga niste prejeli ali drug evangelij, ki ga niste sprejeli, bi bili mogoče z njim prizanesljivi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Kajti domnevam, da nisem bil niti malo za zelo vodilnimi apostoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Toda čeprav sem grob v govoru, pa nisem v spoznanju; toda med vami smo se temeljito razodeli v vseh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ali sem zagrešil prestopek s poniževanjem samega sebe, da bi bili vi lahko povišani, ker sem vam brez plačila oznanil Božji evangelij?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Odvzel sem drugim cerkvam in od njih jemal plačila, da vam storim uslugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'In ko sem bil prisoten z vami in trpel pomanjkanje, nisem bil v breme nobenemu človeku, kajti to, kar mi je primanjkovalo, so preskrbeli bratje, ki so prišli iz Makedonije. In v vseh stvareh sem se varoval pred tem, da bi vam bil v breme in tako se bom varoval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Kakor je Kristusova resnica v meni, me v področjih Ahaje noben človek ne bo ustavil v tem bahanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Zakaj? Ker vas ne ljubim? Bog ve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Toda kar delam, to bom delal, da bom lahko odsekal priložnost pred temi, ki želijo priložnost; da bodo, v čemer se ponašajo, lahko najdeni kakor mi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Kajti takšni so lažni apostoli, varljivi delavci, ki se prenarejajo v Kristusove apostole.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'In nič čudnega; kajti sam Satan se prenareja v angela svetlobe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Torej ni nič posebnega, če so tudi njegovi služabniki prenarejeni kakor služabniki pravičnosti, katerih konec bo glede na njihova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Ponovno pravim: ›Naj me noben človek nima za bedaka; če drugače, me vendar sprejmite kakor bedaka, da se bom lahko malce bahal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'To, kar govorim, tega ne govorim po Gospodu, temveč kakor bi bilo nespametno v tem zaupanju bahanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Ker pa se mnogi ponašajo po mesu, se bom tudi jaz ponašal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Kajti z veseljem trpite bedake, ker ste vi sami modri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Kajti trpite, če vas človek privleče v suženjstvo, če vas človek požira, če od vas človek jemlje, če človek sebe povišuje, če vas človek udari po obrazu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Govorim glede graje, kakor bi bili šibki. Čeprav v čemer je kdorkoli drzen (govorim nespametno), sem tudi sam drzen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ali so Hebrejci? Tudi jaz sem. Ali so Izraelci? Tudi jaz sem. Ali so Abrahamovo seme? Tudi jaz sem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Ali so Kristusovi služabniki? (Govorim kakor bedak.) Jaz sem bolj; obilnejši v naporih, nad mero pri bičanjih, pogosteje v ječah, često v smrtnih nevarnostih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Judov sem petkrat prejel štirideset udarcev z bičem, izvzemši enega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Trikrat sem bil pretepen s šibami, enkrat sem bil kamnan, trikrat sem pretrpel brodolom, noč in dan sem bil na globokem morju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'pogosto na potovanjih, v nevarnostih od vodá, v nevarnostih od roparjev, v nevarnostih od svojih lastnih rojakov, v nevarnostih od poganov, v nevarnostih v mestu, v nevarnostih v divjini, v nevarnostih na morju, v nevarnostih med lažnivimi brati;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'v utrujenostih in bolestih, v pogostih bedenjih, v lakoti in žeji, v pogostih postih, v mrazu in nagoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Poleg teh stvari, ki so zunanje, to, kar dnevno prihaja nadme, [še] skrb za vse cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kdo je slaboten in jaz nisem slaboten? Kdo je užaljen in jaz ne gorim?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Če se moram nujno ponašati, se bom ponašal s stvarmi, ki se tičejo mojih slabotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bog in Oče našega Gospoda Jezusa Kristusa, ki je blagoslovljen na vékomaj, ve, da ne lažem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'V Damasku je voditelj pod kraljem Arétom z garnizijo zastražil mesto Damaščanov, željan, da me zgrabi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'pa sem bil skozi okno v košu spuščen dol ob zidu in pobegnil njegovim rokam.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, '§ Zame ni primerno, da bi se sedaj poveličeval. Prišel bom k videnjem in razodetjem od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Pred okoli štirinajstimi leti sem spoznal človeka v Kristusu (bodisi v telesu, ne morem reči; ali izven telesa, ne morem povedati; Bog ve), nekoga vzetega gor do tretjih nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'In poznal sem takšnega človeka (bodisi v telesu ali izven telesa, ne morem povedati; Bog ve),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'kako je bil vzet gor v raj in je slišal neizgovorljive besede, ki jih človeku ni zakonito izreči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'S takšnim se bom ponašal. Vendar se ne bom ponašal sam s seboj, temveč s svojimi slabotnostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Kajti kljub temu da bi se želel ponašati, ne bom bedak; kajti povedal bom resnico. Toda sedaj potrpim, da ne bi katerikoli človek mislil o meni več, kakor me vidi, da sem ali kar sliši o meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'In da se ne bi zaradi obilja razodetij, prek mere povišal, mi je bil dan v meso trn, Satanov poslanec, da me udari, da ne bi bil prek mere vzvišen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Za to stvar sem trikrat rotil Gospoda, da bi jo odstranil od mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'In mi je rekel: »Dovolj ti je moja milost, kajti moja moč je izpopolnjena v slabotnosti.« Torej se bom z največjim veseljem raje ponašal s svojimi slabotnostmi, da bo na meni lahko počivala Kristusova moč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Torej bom zaradi Kristusa užival v slabotnostih, v grajah, v potrebah, v preganjanjih, v tegobah; kajti kadar sem slaboten, tedaj sem močan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Postal sem bedak v ponašanju. Prisilili ste me, kajti od vas bi moral biti priporočen. Kajti v ničemer ne zaostajam za vašimi najvodilnejšimi apostoli, čeprav nisem nič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Resnično, znamenja apostola so bila med vami storjena v vsej potrpežljivosti, z znamenji in čudeži ter mogočnimi dejanji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Kajti kaj je to, v čemer ste bili slabši do drugih cerkvá, razen tega, da vam jaz nisem bil v breme? Odpustite mi to krivico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Glejte, tretjič sem pripravljen priti k vam, in vam ne bom v breme, kajti ne iščem vašega, temveč vas. Kajti ne bi smeli biti otroci obvezani varčevati za starše, temveč starši za otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'In zelo rad se hočem razdati in biti razdan za vas; četudi vas obilneje ljubim, sem manj ljubljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Toda naj bo tako, nisem vas bremenil; kljub temu sem vas, ker sem prebrisan, ujel z zvijačo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Ali sem vas izkoristil po kom od teh, ki sem jih poslal k vam?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Naprosil sem Tita in z njim sem poslal brata. Ali vas je izkoristil Tit? Ali nisva hodila v istem duhu? Ali nisva hodila po istih stopinjah?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Ponovno, ali mislite, da se vam opravičujemo? Govorimo pred Bogom v Kristusu. Toda, srčno ljubljeni, vse stvari počenjamo v vaše izgrajevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Kajti bojim se, da ko pridem, vas ne bom našel takšnih, kakor vas želim in da me boste vi našli takšnega, kakor si ne želite; da ne bi bilo razpravljanj, zavisti, jeze, prepirov, obrekovanj, šepetanj, napihovanj, uporov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'In da me ne bi, ko ponovno pridem, moj Bog med vami ponižal in da bom objokoval mnoge, ki so že grešili in se niso pokesali od nečistosti in prešuštvovanja in pohotnosti, ki so jih zagrešili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'To je tretjič, [da] prihajam k vam. Po ustih dveh ali treh prič bo ugotovljena vsaka beseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Povedal sem vam že nekoč in vam drugič napovedujem, kakor če bi bil prisoten; in sedaj odsoten pišem tem, ki so poprej grešili in vsem drugim, da če ponovno pridem, ne bom prizanašal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Ker iščete dokaz, da Kristus govori v meni, ki posebej do vas ni slaboten, temveč je v vas mogočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Kajti čeprav je bil križan zaradi slabosti, vendarle živi z Božjo močjo. Kajti tudi mi smo šibki v njem, toda z Božjo močjo bomo živeli z njim za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Izprašajte se, ali ste v veri. Preizkusite se. Ali se ne poznate, da je Jezus Kristus v vas, razen če ste zavrženi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Toda zaupam, da boste spoznali, da mi nismo zavrženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Sedaj molim k Bogu, da ne storite nobenega zla; ne da bi se mi izkazali potrjene, temveč da bi vi storili to, kar je pošteno, čeprav smo mi kakor zavrženi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Kajti ničesar ne moremo storiti proti resnici, temveč za resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Kajti veseli smo, ko smo mi slabotni, vi pa močni; in to tudi želimo, celó vašo popolnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Zatorej pišem te stvari v odsotnosti, da ne bi navzoč uporabil ostrine, glede na oblast, ki mi jo je Gospod dal za izgrajevanje in ne za uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Končno, bratje, zbogom. Bodite popolni, bodite dobro potolaženi, bodite enega mišljenja, živite v miru; in z vami bo Bog ljubezni in miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdravite drug drugega s svetim poljubom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Pozdravljajo vas vsi sveti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Milost Gospoda Jezusa Kristusa in Božja ljubezen in soudeležba Svetega Duha bodi z vami vsemi. Amen. [Druga poslanica Korinčanom je bila napisana iz Filipov, mesta v Makedoniji, po Titu in Luku.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pavel, apostol (ne od ljudi niti ne po človeku, temveč po Jezusu Kristusu in Bogu Očetu, ki ga je obudil od mrtvih)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'in vsi bratje, ki so z menoj, cerkvam v Galatiji:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, '›Milost bodi vam in mir od Boga Očeta in od našega Gospoda Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'ki je samega sebe dal za naše grehe, da nas lahko osvobodi iz tega sedanjega hudobnega sveta, glede na voljo Boga in našega Očeta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'ki mu bodi slava na veke vekov. Amen.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Čudim se, da ste se tako hitro oddaljili od tistega, ki vas je poklical v Kristusovo milost, k drugemu evangeliju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'ki ni drug, temveč so tam nekateri, ki vas vznemirjajo in hočejo izkriviti Kristusov evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Toda čeprav vam mi ali angel iz nebes oznanja kak drug evangelij, kakor tega, ki smo vam ga oznanili, naj bo ta preklet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Kakor smo rekli prej, tako ponovno govorim sedaj: »Če vam katerikoli človek oznani kak drug evangelij, kakor ta, ki ste ga prejeli, naj bo preklet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Kajti ali sedaj pregovarjam ljudi ali Boga? Ali poskušam ugajati ljudem? Kajti če bi še ugajal ljudem, ne bi bil Kristusov služabnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Toda potrjujem vam, bratje, da evangelij, ki je bil oznanjen po meni, ni po človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Kajti niti ga nisem prejel od človeka niti se ga nisem naučil, temveč po razodetju Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Kajti slišali ste o mojem vedênju, v preteklem času v judovski religiji, da sem preko mere preganjal Božjo cerkev in jo pustošil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'in v judovski religiji napredoval nad mnoge svoje vrstnike v svojem lastnem narodu in bil še silno vnet za izročila svojih očetov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Toda ko je Bogu, ki me je od maternice moje matere odbral in me poklical po svoji milosti, ugajalo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'da v meni razodene svojega Sina, da bi ga lahko oznanjal med pogani, se nisem takoj posvetoval z mesom in krvjo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'niti nisem odšel gor v Jeruzalem k tem, ki so bili apostoli pred menoj, temveč sem odšel v Arabijo in se ponovno vrnil v Damask.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potem sem po treh letih odšel gor v Jeruzalem, da vidim Petra in z njim ostal petnajst dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Toda izmed apostolov nisem videl nobenega drugega, razen Jakoba, Gospodovega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Torej stvari, ki vam jih pišem, glejte, pred Bogom, ne lažem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Kasneje sem prišel v področja Sirije in Kilikije;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'in po obrazu sem bil nepoznan cerkvam v Judeji, ki so bile v Kristusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'toda samo slišali so: »Da tisti, ki nas je v preteklih časih preganjal, sedaj oznanja vero, ki jo je nekoč uničeval.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, '§ In slavili so Boga v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potem sem po štirinajstih letih ponovno z Barnabom odšel gor v Jeruzalem in s seboj vzel tudi Tita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'In gor sem odšel po razodetju in jim posredoval ta evangelij, ki ga oznanjam med pogani, toda skrivaj tem, ki so bili ugledni, da ne bi na kakršenkoli način tekel ali sem tekel zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Toda niti Tit, ki je bil z menoj, ki je bil Grk, ni bil prisiljen, da se obreže.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'In to zaradi nepričakovano privedenih lažnih bratov, ki so prišli na skrivnem, da zalezujejo našo svobodo, ki jo imamo v Kristusu Jezusu, da bi nas lahko privedli v suženjstvo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'katerim nismo niti za eno uro dali prostora s podložnostjo, da bi se evangelijska resnica lahko nadaljevala z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Toda izmed teh, ki so se zdeli, da so nekaj (karkoli so bili, mi ni važno; Bog ne sprejema človeške zunanjosti), kajti tisti, ki so se zdeli, da so nekaj, mi na posvetovanju niso ničesar dodali,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'temveč nasprotno, ko so videli, da je bil evangelij neobreze zaupan meni, kakor je bil evangelij obreze Petru');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(kajti, kdor je učinkovito deloval v Petru k apostolstvu obrezanih, isti je bil mogočen v meni za pogane).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'In ko so Jakob, Kefa in Janez, ki se zdijo, da so stebri, zaznali milost, ki mi je bila dana, so meni in Barnabu podali desnice družabništva, da bi midva šla k poganom, oni pa k obrezanim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Le želeli so, da bi se spominjala revnih; isto kar sem si tudi sam prizadeval storiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Toda ko je Peter prišel v Antiohijo, sem se mu v obraz uprl, ker je bil za ošteti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Kajti preden so prišli nekateri od Jakoba, je jedel s pogani. Toda ko so prišli, se je umaknil in se oddvojil, ker se je bal teh, ki so bili iz obreze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'In prav tako so se z njim pretvarjali drugi Judje; do te mere, da je bil tudi Barnaba zapeljan z njihovim pretvarjanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Toda ko sem videl, da niso živeli pošteno, glede na resnico evangelija, sem pred vsemi temi rekel Petru: »Če ti, ki si Jud, živiš po načinu poganov, ne pa, kakor počno Judje, zakaj siliš pogane, da živijo, kakor počno Judje?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Mi, ki smo Judje po naravi, ne pa poganski grešniki,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'vemo, da človek ni opravičen po delih postave, temveč po veri v Jezusa Kristusa, celó mi smo verovali v Jezusa Kristusa, da bi bili lahko opravičeni po veri v Kristusa, ne pa po delih postave, kajti po delih postave ne bo opravičeno nobeno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Toda če smo, medtem ko si prizadevamo biti opravičeni po Kristusu, tudi mi sami spoznani [za] grešnike, je potemtakem Kristus služabnik greha? Bog ne daj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Kajti če ponovno gradim stvari, ki sem jih uničil, samega sebe delam prestopnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Kajti po postavi sem mrtev postavi, da bi lahko živel Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Križan sem s Kristusom, pa vendar živim; vendar ne jaz, temveč Kristus živi v meni. In življenje, ki ga sedaj živim v mesu, živim po veri v Božjega Sina, ki me je ljubil in dal zame samega sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Ne onemogočam Božje milosti; kajti če je pravičnost prišla po postavi, potem je Kristus umrl zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, '§ O nespametni Galačani, kdo vas je uročil, da ne bi ubogali resnice, pred čigar očmi je bil očitno postavljen Jezus Kristus, križan med vami?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Samo to hočem izvedeti od vas: »Ali ste prejeli Duha z deli postave ali s poslušnostjo veri?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Ali ste tako nespametni? Ali ste, začenši z Duhom, sedaj popolni v mesu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Ali ste toliko stvari pretrpeli zaman? Če bi bile vendarle zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'On torej, ki vam daje Duha in med vami dela čudeže, ali jih dela po delih postave ali po poslušnosti veri?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Celó kakor je Abraham veroval Bogu in mu je bilo to šteto za pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Spoznajte torej, da so Abrahamovi otroci tisti, ki so iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'In ker je pismo slutilo, da bo Bog pogane opravičil po veri, je poprej oznanjalo evangelij Abrahamu, rekoč: ›V tebi bodo blagoslovljeni vsi narodi.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Tako so torej tisti, ki so iz vere, blagoslovljeni z zvestim Abrahamom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Kajti kolikor jih je iz del postave, so pod prekletstvom, kajti pisano je: ›Preklet je vsak, kdor ne vztraja v vseh stvareh, ki so pisane v knjigi postave, da jih izvrši.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Toda očitno je to, da v Božjih očeh noben človek ni opravičen s postavo, kajti: ›Pravični bo živel iz vere.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Postava pa ni iz vere, temveč: ›Človek, ki jih izvršuje, bo živel po njih.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus nas je odkupil od prekletstva postave, ko je za nas postal prekletstvo, kajti pisano je: ›Preklet je vsak, kdor visi na drevesu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Da bi Abrahamov blagoslov lahko po Jezusu Kristusu prešel na pogane, da bi mi po veri lahko prejeli obljubo Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bratje, govorim po človeških običajih: »Čeprav je to samo človeška zaveza, vendar če je potrjena, je noben človek ne razveljavlja ali dodaja k njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Torej obljube so bile izrečene Abrahamu in njegovemu semenu. Ni rekel: ›In semenom,‹ kakor mnogim; temveč kakor enemu: ›In tvojemu semenu,‹ ki je Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, '§ In pravim to, da zaveze, ki je bila prej potrjena od Boga v Kristusu, postava, ki je bila štiristo trideset let kasneje, ne more razveljaviti, da bi obljubo storila brez učinka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Kajti če je dediščina po postavi, le-ta ni več po obljubi; toda Bog jo je Abrahamu dal po obljubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Čemu potem služi postava? Dodana je bila zaradi prestopkov, dokler ne bi prišel potomec, ki mu je bila dana obljuba; in ta je bila odrejena po angelih v roko posrednika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Torej posrednik ni posrednik enega, toda Bog je eden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Ali je potem postava zoper Božje obljube? Bog ne daj, kajti če bi bila dana postava, ki bi lahko dala življenje, bi bila pravičnost resnično po postavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Toda pismo je vse zaprlo pod greh, da bi bila lahko tem, ki verujejo, dana obljuba po veri Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Toda preden je prišla vera, smo bili držani pod postavo, zaprti veri, ki naj bi se razodela kasneje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Zatorej je bila postava naša vzgojiteljica, da nas privede h Kristusu, da bi bili mi lahko opravičeni iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Toda potem, ko je prišla vera, nismo več pod vzgojiteljico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Kajti vi vsi ste Božji otroci po veri v Kristusa Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Kajti tako veliko, kot vas je bilo krščenih v Kristusa, ste oblekli Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Ni niti Juda niti Grka, ni niti sužnja niti svobodnega, ni niti moškega niti ženske; kajti vsi vi ste eno v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Če pa ste Kristusovi, potem ste Abrahamovo seme in dediči glede na obljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Pravim torej: » Da se dedič, dokler je še otrok, nič ne razlikuje od služabnika, čeprav je gospodar vsega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'temveč je pod varuhi in vzgojitelji do časa, določenega od očeta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Točno tako smo bili mi, ko smo bili otroci, v suženjstvu pod prvinami sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Toda ko je prišla polnost časa, je Bog poslal svojega Sina, rojenega iz ženske, postavljenega pod postavo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'da odkupi te, ki so bili pod postavo, da bi mi lahko prejeli posinovljenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'In ker ste sinovi, je Bog v vaša srca poslal Duha svojega Sina, ki kliče: »Aba, Oče.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, '§ Zatorej nisi več služabnik, temveč sin; če pa [si] sin, [si] potem po Kristusu Božji dedič.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Vendar ste tedaj, ko niste poznali Boga, služili tem, ki po naravi niso bogovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Toda sedaj, potem ko ste spoznali Boga, ali bolje rečeno ste spoznani od Boga, kako se ponovno obračate k slabotnim in bednim prvinam, ki jim želite biti ponovno v suženjstvu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Obeležujete dneve in mesece in čase in leta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Bojim se za vas, da nisem na vas zaman priložil truda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Bratje, rotim vas, bodite kakor sem jaz; kajti jaz sem kakor ste vi; sploh me niste prizadeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Vi veste, kako sem vam na začetku oznanjal evangelij iz šibkosti mesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, '§ In moje preizkušnje, ki je bila v mojem mesu, niste niti prezirali niti zavrgli, temveč ste me sprejeli kot Božjega angela, celó kot Kristusa Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kje je potem blagoslovljenost, o kateri ste govorili? Kajti pričujem vam, da če bi bilo mogoče, bi si iztaknili lastne oči in mi jih dali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Sem torej postal vaš sovražnik, ker vam govorim resnico?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Oni so vam goreče naklonjeni, toda ne pravilno; da, izključili bi vas, da bi jim vi bili goreče naklonjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Toda dobro je biti nenehno goreče naklonjen v dobri stvari in ne samo, kadar sem prisoten z vami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Moji majhni otroki, zaradi katerih se mučim v ponovnem rojevanju, dokler ne bo v vas oblikovan Kristus,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'sedaj želim biti prisoten z vami in spremeniti svoj glas; kajti stojim s pomislekom o vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Povejte mi vi, ki želite biti pod postavo, ali ne slišite postave?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Kajti pisano je, da je imel Abraham dva sinova, enega s sužnjico, drugega pa s svobodno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Toda ta, ki je bil iz sužnje, je bil rojen po mesu; toda tisti iz svobodne, je bil po obljubi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Katere stvari so prispodoba, kajti to sta dve zavezi; ena z gore Sinaj, ki povzroča suženjstvo, ki je Hagára.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Kajti ta Hagára je gora Sinaj v Arabiji in ustreza [prestolnici] Jeruzalem, ki je sedaj in je v suženjstvu s svojimi otroki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Toda [prestolnica] Jeruzalem, ki je zgoraj, je svobodna, ki je mati nas vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Kajti pisano je: ›Veseli se, ti jalova, ki ne rojevaš; izbruhni in zavpij, ti, ki nisi v porodnih mukah; kajti zapuščena ima mnogo več otrok kakor tista, ki ima soproga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Torej smo mi, bratje, kot je bil Izak, otroci obljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Toda kakor je takrat, kdor je bil rojen po mesu, preganjal tistega, ki je bil rojen po Duhu, točno tako je to sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Vendar kaj pravi pismo? ›Spôdi sužnjo in njenega sina, kajti sin sužnje ne bo dedič s sinom svobodne.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Zaradi tega, bratje, nismo otroci sužnje, temveč svobodne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Stojte torej trdno v svobodi, s katero nas je Kristus osvobodil in ne bodite ponovno vpleteni z jarmom sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Glejte, jaz, Pavel, vam povem, da če boste obrezani, vam Kristus ne bo nič koristil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Kajti ponovno pričujem vsakemu človeku, ki je obrezan, da je dolžnik izpolnjevanja celotne postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Katerikoli izmed vas ste opravičeni po postavi, vam je Kristus postal nekoristen; odpadli ste od milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Kajti mi po Duhu čakamo na upanje pravičnosti iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Kajti v Jezusu Kristusu niti obreza ne koristi nič niti neobreza, temveč vera, ki deluje po ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Dobro ste tekli; kdo vas je oviral, da ne bi ubogali resnice?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'To prepričevanje ne prihaja od tistega, ki vas kliče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Malo kvasa prekvasi celotno gmoto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Po Gospodu imam zaupanje v vas, da ne boste drugače misleči; toda kdor vas nadleguje, bo nosil svojo obsodbo, kdorkoli bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'In jaz, bratje, če vendarle oznanjam obrezo, zakaj še vedno trpim preganjanje? Potem je pohujšanje križa prenehalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Kateri pa vas begajo, želim, da bi bili celó odrezani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Kajti bratje, poklicani ste bili v svobodo; samo svobode ne uporabite za priložnost mesu, temveč v ljubezni služite drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Kajti vsa postava je izpolnjena v eni besedi, celó v tej: ›Svojega bližnjega boš ljubil kakor samega sebe.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Toda če drug drugega grizete in hrustate, pazite, da ne boste požrti eden od drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Pravim torej to: »Hodite v Duhu in ne boste uresničili poželenja mesa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Kajti meso hrepeni zoper Duha, Duh pa zoper meso; in ta dva sta drug drugemu nasprotna, tako da ne morete delati stvari, ki bi jih želeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Toda če ste vodeni od Duha, niste pod postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, '§ Torej dela mesa so očitna, ki so ta: zakonolomstvo, prešuštvovanje, nečistost, pohotnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'malikovanje, čaranje, sovraštvo, prerekanje, tekmovanja, bes, prepir, upori, krivoverstva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'zavisti, umori, pijanost, veseljačenja in podobno; o katerih vam vnaprej povem, kakor sem vam tudi povedal v preteklem času, da tisti, ki počenjajo takšne stvari, ne bodo podedovali Božjega kraljestva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Toda sad Duha je ljubezen, radost, mir, potrpežljivost, blagost, dobrota, vera,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'krotkost, zmernost; zoper te ni postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'In tisti, ki so Kristusovi, so meso križali s strastmi in poželenji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Če živimo po Duhu, tudi hodimo v Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne bodimo željni prazne slave z izzivanjem drug drugega in zavidanjem drug drugemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, '§ Bratje, če je človek zasačen v krivdi, vi, ki ste duhovni, obnovite takšnega v duhu krotkosti; in se opazujte, da ne bi bili tudi vi skušani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Nosite bremena drug drugemu in tako izpolnite Kristusovo postavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Kajti če človek misli, da je on sam kaj, ko ni nič, samega sebe zavaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, '§ Toda vsakdo naj preizkusi svoje lastno delo in potem bo imel veselje le v sebi in ne v drugem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Kajti vsak človek bo nosil svoje lastno breme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Kdor je poučevan v besedi, naj vse dobrine deli s tistim, ki poučuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne bodite zavedeni; Bog se ne [pusti] zasmehovati; kajti karkoli človek seje, to bo tudi žel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Kajti kdor seje v svoje meso, bo od mesa požel trohljivost; toda kdor seje v Duha, bo od Duha požel večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'In ne bodimo naveličani v izvrševanju dobrega, kajti če ne izgubimo poguma, bomo v pravšnjem obdobju želi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Medtem ko imamo torej priložnost, delajmo dobro vsem ljudem, še posebej tem, ki so iz verne družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, '§ Poglejte kako veliko pismo sem vam napisal s svojo lastno roko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Kolikor jih želi storiti dober prikaz v mesu, vas silijo, da bi bili obrezani; samo da oni ne bi trpeli preganjanja zaradi Kristusovega križa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Kajti niti oni sami, ki so obrezani, se ne držijo postave; temveč vas želijo imeti obrezane, da bi se lahko ponašali z vašim mesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Toda Bog ne daj, da bi se jaz ponašal, razen s križem našega Gospoda Jezusa Kristusa, po katerem je svet križan meni, jaz pa svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, '§ Kajti v Kristusu Jezusu niti obreza ne koristi nič niti neobreza, temveč novo ustvarjeno bitje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'In kateri živijo glede na to pravilo, mir bodi nad njimi in usmiljenje in nad Božjim Izraelom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Odslej naj me noben človek ne vznemirja, kajti na svojem telesu nosim znamenja Gospoda Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Bratje, milost našega Gospoda Jezusa Kristusa bodi z vašim duhom. Amen. [Galačanom, napisano iz Rima.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pavel, po Božji volji apostol Jezusa Kristusa, svetim, ki so v Efezu in zvestim v Kristusu Jezusu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Blagoslovljen bodi Bog in Oče našega Gospoda Jezusa Kristusa, ki nas je blagoslovil z vsemi duhovnimi blagoslovi v nebeških prostorih v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Kakor nas je pred ustanovitvijo sveta izbral v njem, da bi bili pred njim sveti in brez graje, v ljubezni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'nas je glede na dobro voljo svojega hotenja zase vnaprej določil za posvojitev otrok po Jezusu Kristusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'v hvalo slave njegove milosti, v kateri nas je naredil sprejete v ljubljenem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'V katerem imamo po njegovi krvi odkupitev, odpuščanje grehov glede na bogastva njegove milosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'v čemer je imel do nas obilje v vsej modrosti in razumnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'ko nam je dal spoznati skrivnost svoje volje, po svojem zadovoljstvu, ki ga je namenil v sebi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, '§ da v razdeljevanju polnosti časov lahko zbere skupaj v eno vse stvari v Kristusu, tako te, ki so na nebu, kakor te, ki so na zemlji; celó v njem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'v katerem smo dosegli tudi dediščino, vnaprej določeni glede na namen njega, ki vse stvari dela po sklepu svoje lastne volje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'da bi bili mi, ki smo prvi zaupali v Kristusa, v hvalo njegove slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'V katerega ste tudi vi zaupali, potem ko ste slišali besedo resnice, evangelij rešitve svojih duš. V katerem ste bili potem, ko ste verovali, tudi zapečateni s tem Svetim Duhom obljube,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'ki je poroštvo naše dediščine do odkupitve kupljene lastnine, v hvalo njegove slave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Zato se tudi jaz, potem ko sem slišal o vaši veri v Gospoda Jezusa in ljubezni do vseh svetih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'ne preneham zahvaljevati za vas in vas omenjati v svojih molitvah;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'da bi vam Bog našega Gospoda Jezusa Kristusa, Oče slave, lahko dal duha modrosti in razodetja v spoznanju njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Da bi bile oči vašega razumevanja razsvetljene, da boste lahko vedeli kakšno je upanje njegovega klicanja in kakšna bogastva slave njegove dediščine v svetih');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'in kakšna je silna veličina njegove moči do nas, ki verujemo, glede na delovanje njegove mogočne moči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'ki jo je učinkovito prikazal v Kristusu, ko ga je obudil od mrtvih in ga postavil na svojo lastno desnico v nebeških prostorih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'daleč nad vsako kneževino in oblast in moč in gospostvo ter [nad] vsako ime, ki je poimenovano ne samo na tem svetu, temveč tudi na tem, ki prihaja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'In vse stvari je položil pod njegova stopala in mu dal, da je nad vsemi stvarmi, glava cerkvi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'ki je njegovo telo, polnost njega, ki izpolnjuje vse v vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'In oživil je vas, ki ste bili mrtvi v prestopkih in grehih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'v katerih ste v preteklem času živeli glede na način tega sveta, glede na princa oblasti zraka, duha, ki sedaj deluje v otrocih neposlušnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'med katerimi smo tudi mi vsi imeli v preteklih časih svoje vedênje v poželenjih našega mesa in uresničevali smo želje mesa in mišljenja in smo bili po naravi otroci besa, tako kakor drugi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Toda Bog, ki je bogat v usmiljenju, nas je zaradi svoje velike ljubezni, s katero nas je vzljubil,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'celó ko smo bili mrtvi v grehih, skupaj s Kristusom oživil (po milosti ste rešeni)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'in nas skupaj dvignil in nas skupaj posadil v nebeške prostore v Kristusu Jezusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'da bi v prihajajočih časih lahko pokazal izjemna bogastva svoje milosti v svoji prijaznosti do nas po Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Kajti z milostjo ste rešeni po veri; in to ni od vas, to je Božji dar;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ne [pa] iz del, da se ne bi katerikoli človek bahal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Kajti mi smo njegova izdelava, ustvarjeni v Kristusu Jezusu za dobra dela, ki jih je Bog poprej odredil, da bi v njih hodili.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Zatorej se spomnite, da ste bili v preteklem času pogani v mesu, ki ste imenovani Neobreza po tistih, ki [sebe] imenujejo Obreza v mesu, storjena z rokami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'da ste bili v tistem času brez Kristusa, neznanci pred Izraelovo republiko in tujci pred zavezami obljube in niste imeli upanja in ste bili brez Boga na svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Toda sedaj ste v Kristusu Jezusu vi, ki ste bili včasih daleč proč, približani po Kristusovi krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Kajti on je naš mir, ki je oba napravil eno in je med nami zlomil srednji zid pregrade');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'in v svojem mesu odpravil sovraštvo, celó zakon zapovedi, vsebovan v odredbah; zato da naredi v sebi iz dveh enega novega človeka in tako sklene mir;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'in da lahko oba v enem telesu po križu spravi k Bogu ter s tem umori sovraštvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'In prišel je ter oznanil mir vam, ki ste bili daleč stran in tem, ki so bili blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Kajti po njem imamo oboji po enem Duhu dostop k Očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Zdaj torej niste več tujci in tuji ljudje, temveč sodržavljani s svetimi in iz Božje družine');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'in zgrajeni ste na temelju apostolov ter prerokov, sam Jezus Kristus pa je glavni vogalni kamen;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'v katerem vsa zgradba, primerno zasnovana skupaj, raste v svet tempelj v Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'v katerem ste tudi vi po Duhu skupaj sezidani za Božje prebivališče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Zaradi tega razloga jaz, Pavel, jetnik Jezusa Kristusa za vas pogane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'če ste slišali o razdeljevanju Božje milosti, katera mi je dana posebej do vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'kako, da mi je po razodetju dal spoznati skrivnost (kakor sem prej napisal z nekaj besedami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 's čimer, ko berete, lahko razumete moj vpogled v Kristusovo skrivnost);');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'ki v drugih časih ni bila razglašena človeškim sinovom, kakor je sedaj po Duhu razodeta njegovim svetim apostolom in prerokom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'da naj bi bili pogani sodediči in iz istega telesa ter po evangeliju udeleženci njegove obljube v Kristusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'katerega služabnik sem postal, glede na Božji dar milosti, dane meni, po dejavnem delovanju njegove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, '§ Meni, ki sem manj, kakor najmanjši izmed vseh svetih, je dana ta milost, da naj bi med pogani oznanjal nedoumljiva Kristusova bogastva');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, '§ in storil, da vsi ljudje vidijo, kakšna je družba skrivnosti, ki je bila od začetka sveta skrita v Bogu, ki je po Jezusu Kristusu ustvaril vse stvari;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'z namenom, da se lahko zdaj kneževinam in oblastem v nebeških prostorih prek cerkve da spoznati mnogovrstna Božja modrost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'glede na večen namen, ki ga je nameraval v Kristusu Jezusu, našem Gospodu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'v katerem imamo pogum in dostop z zaupanjem po njegovi veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Zatorej želim, da ob mojih stiskah za vas, kar je vaša slava, ne opešate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, '§ Zaradi tega razloga upogibam svoja kolena k Očetu našega Gospoda Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'po katerem je imenovana celotna družina na nebu in zemlji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'da vam bo zagotovil, glede na bogastva svoje slave, da boste v notranjem človeku okrepljeni z močjo njegovega Duha;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'da lahko Kristus po veri prebiva v vaših srcih, da bi ukoreninjeni in utemeljeni v ljubezni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'lahko z vsemi svetimi zmogli doumeti, kolikšna je širina in dolžina in globina in višina');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'ter da spoznate Kristusovo ljubezen, ki presega spoznanje, da bi bili lahko izpolnjeni z vso Božjo polnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Torej njemu, ki je zmožen, glede na moč, ki deluje v nas, narediti presegajoče obilno povrh vsega, kar prosimo ali mislimo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, '§ njemu bodi slava v cerkvi po Kristusu Jezusu skozi vsa obdobja, od veka do veka. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Jaz torej, Gospodov jetnik, vas rotim, da živite vredno Božjemu pozivu, s katerim ste poklicani,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'z vso ponižnostjo in krotkostjo, s potrpežljivostjo prenašajte drug drugega v ljubezni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'in prizadevajte si ohraniti enotnost Duha z vezjo miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Obstaja eno telo in en Duh, točno tako kot ste poklicani v enem upanju vaše poklicanosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'en Gospod, ena vera, en krst,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'en Bog in Oče vseh, ki je nad vsemi in po vseh in v vas vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Toda vsakomur izmed nas je dana milost glede na mero Kristusovega daru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Zatorej pravi: ›Ko se je povzpel gor na višavo, je odpeljal ujeto ujetništvo in dal darove ljudem.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(Torej, da se je povzpel, kaj je to razen, da se je tudi najprej spustil v nižje dele zemlje?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, '§ On, ki se je spustil, je tudi isti, ki se je povzpel daleč nad vsa nebesa, da bi lahko izvršil vse stvari.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'In dal je nekatere apostole in nekatere preroke in nekatere evangeliste in nekatere pastirje in učitelje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'za izpopolnjevanje svetih, za delo služenja, za izgrajevanje Kristusovega telesa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'dokler mi vsi ne pridemo k enotnosti vere in spoznanja Božjega Sina, do popolnega človeka, do mere postave Kristusove polnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Tako odslej ne bomo več otroci, premetavani sem ter tja in prenašani okoli z vsakim vetrom nauka, s človeško pretkanostjo in spretno prekanjenostjo, s čimer oni prežijo, da bi zavedli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'temveč, ker govorimo resnico v ljubezni, lahko v vseh stvareh rastemo vanj, ki je glava, celó Kristus,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'iz katerega celotno telo, primerno združeno skupaj in strnjeno s tem, kar vsak sklep oskrbuje, glede na dejavno delovanje po meri vsakega dela, omogoča rast telesa v izgrajevanje sebe v ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'To torej pravim in pričujem v Gospodu, da odslej ne živite, kakor živijo drugi pogani, v ničevosti svojega uma,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'ki imajo zatemnjeno razumevanje, odtujeni so od Božjega življenja preko nevednosti, ki je v njih, zaradi slepote njihovega srca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'ki so se prek svojega občutka predali v pohotnost, da s pohlepom počenjajo vso nečistost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Toda vi se niste tako učili Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'če je tako, da ste ga slišali in ste bili po njem poučeni, kakor je resnica v Jezusu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'da glede na prejšnje vedênje odložite starega človeka, ki je pokvarjen glede varljivih poželenj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'in bodite obnovljeni v duhu svojega uma;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'in da si oblečete novega človeka, ki je po Bogu ustvarjen v pravičnosti in resnični svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Zatorej zavračajte laganje in vsak [naj] govori resnico s svojim bližnjim, kajti mi smo udje drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '§ Bodite jezni in ne grešite; sonce naj ne zaide nad vašim besom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'niti ne dajajte prostora hudiču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kdor je kradel, naj ne krade več, temveč naj se raje trudi in s svojimi rokami dela stvar, ki je dobra, da bo imel [kaj] dati tistemu, ki potrebuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Nobenemu umazanemu govoru ne dopustite iziti iz svojih ust, temveč to, kar je dobro, v prid izgrajevanju, da lahko nudi milost poslušalcem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'In ne žalostite Božjega Svetega Duha, s katerim ste zapečateni za dan odkupitve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Naj bo vsa grenkoba in bes in jeza in razgrajanje ter zlo govorjenje vzdignjeno od vas z vso zlobnostjo [vred];');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'in bodite prijazni drug do drugega, nežnega srca, odpuščajoč drug drugemu, celó kakor je Bog zaradi Kristusa odpustil vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Bodite torej Božji posnemovalci, kakor ljubljeni otroci');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'in živite v ljubezni, kakor nas je tudi Kristus ljubil in dal samega sebe za nas kot daritev in žrtev Bogu v blagodišeč vonj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Toda prešuštvovanje in vse nečistosti ali pohlepnosti naj ne bodo niti enkrat omenjene med vami, kakor se spodobi svetim;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'niti umazanost, niti nespametno govorjenje, niti šaljiva vulgarnost, ki niso primerne, temveč rajši zahvaljevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Kajti to veste, da ne vlačugar ne nečista oseba niti pohlepnež, ki je malikovalec, nima nobene dediščine v Kristusovem in Božjem kraljestvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Naj vas noben človek ne vara s praznimi besedami, kajti zaradi teh stvari prihaja Božji bes na otroke neposlušnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Ne bodite torej udeleženci z njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Kajti včasih ste bili tema, toda sedaj ste svetloba v Gospodu. Živite kot otroci svetlobe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '§ (kajti sad Duha je v vsej dobroti in pravičnosti ter resnici)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'in preizkušajte, kaj je sprejemljivo Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'In ne imejte družbe z brezplodnimi deli teme, temveč jih raje grajajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Kajti sramota je celó govoriti o teh stvareh, ki so po njih storjene na skrivnem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Toda vse stvari, ki so pograjane, so razodete po svetlobi; kajti karkoli razodeva je svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Zatorej on pravi: ›Prebúdi se ti, ki spiš in vstani od mrtvih in Kristus ti bo dal svetlobo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Glejte torej, da živite preudarno, ne kakor bedaki, temveč kakor modri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Izkoristite čas, kajti dnevi so hudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Zatorej ne bodite nemodri, temveč razumevajte, kaj je Gospodova volja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'In ne bodite opiti z vinom, v čemer je izgred, temveč bodite napolnjeni z Duhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Nagovarjajte se s psalmi in hvalnicami ter duhovnimi pesmimi, prepevajte in v svojem srcu skladajte napeve Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Vedno se zahvaljujte Bogu in Očetu v imenu našega Gospoda Jezusa Kristusa za vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Drug drugemu se podrejajte v strahu Božjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Žene, podredite se svojim lastnim soprogom kakor Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Kajti soprog je glava ženi, kakor je tudi Kristus glava cerkvi; in on je rešitelj telesa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Torej kakor je cerkev podrejena Kristusu, tako naj bodo v vsaki stvari žene svojim lastnim soprogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Soprogi, ljubite svoje žene, prav tako kakor je tudi Kristus ljubil cerkev in dal zanjo samega sebe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'da bi jo lahko posvetil in očistil z vodnim izpiranjem po besedi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'da bi lahko sebi predstavil krasno cerkev, ki nima madeža ali gube ali katerekoli takšne stvari, temveč da bi bila sveta in brez pomanjkljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tako so možje dolžni ljubiti svoje žene kakor svoja lastna telesa. Kdor ljubi svojo ženo, ljubi sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, '§ Kajti še nikoli ni noben človek sovražil svojega lastnega mesa, temveč ga hrani in neguje, kakor Gospod cerkev;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, '§ kajti mi smo udje njegovega telesa, iz njegovega mesa in iz njegovih kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Zaradi tega razloga bo mož zapustil svojega očeta in mater in bo pridružen k svoji ženi in ona dva bosta eno meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'To je velika skrivnost, vendar jaz govorim glede Kristusa in cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Vseeno naj vsak izmed vas še posebej ljubi svojo ženo, celo kakor samega sebe; in žena [naj] gleda, da spoštuje svojega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Otroci, ubogajte svoje starše v Gospodu, kajti to je prav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Spoštuj svojega očeta in mater (kar je prva zapoved z obljubo),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'da bo lahko dobro s teboj in boš lahko dolgo živel na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'In vi očetje, ne provocirajte svojih otrok do besa, temveč jih vzgajajte v Gospodovem poučevanju in svarilu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Služabniki, bodite poslušni tem, ki so vaši gospodarji glede na meso, s strahom in trepetom, v iskrenosti svojega srca kakor Kristusu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ne z navidezno vdanostjo, kakor bi raje ugajali ljudem, temveč kot Kristusovi služabniki iz srca izpolnjujte Božjo voljo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'z dobro voljo izvršujte službo kakor Gospodu in ne ljudem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'ker veste, da katerokoli dobro stvar kdorkoli stori, isto bo prejel od Gospoda, bodisi je suženj ali svoboden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'In vi, gospodarji, jim storite iste stvari in prizanašajte grožnjam, ker veste, da je tudi vaš Gospodar v nebesih; niti pri njem ni oziranja na osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Končno, moji bratje, bodite močni v Gospodu in v sili njegove moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Nadenite si vso Božjo bojno opremo, da boste zmožni obstati proti hudičevim zvijačam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Kajti ne borimo se proti mesu in krvi, temveč proti kneževinam, proti oblastem, proti vladarjem teme tega sveta, proti duhovni zlobnosti na visokih položajih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Zato vzemite nase celotno Božjo bojno opremo, da se boste zmožni na hudoben dan zoperstaviti in vse storiti ter obstati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stojte torej in imejte svoja ledja opasana z resnico in na sebi imejte prsni oklep pravičnosti');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'in svoja stopala, obuta s pripravljenostjo evangelija miru;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'predvsem vzemite ščit vere, s katerim boste zmožni pogasiti vse ognjene puščice zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'In vzemite čelado rešitve duše in meč Duha, kar je Božja beseda;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'in vedno molíte z vso molitvijo in ponižno prošnjo v Duhu in k temu bedite z vso vztrajnostjo in ponižno prošnjo za vse svete;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'in zame, da mi bo lahko dana izgovarjava, da bom lahko pogumno odpiral svoja usta, da se razglasi skrivnost evangelija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'za katerega sem predstavnik v vezeh, da bom v tem lahko pogumno govoril, kakor bi moral govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Toda, da boste lahko poznali tudi moje zadeve in kako delam, vam bo Tihik, moj ljubljeni brat in zvesti služabnik v Gospodu, oznanil vse stvari;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'katerega sem poslal k vam zaradi istega namena, da bi vi lahko spoznali naše zadeve in da bi on lahko potolažil vaša srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Mir bodi bratom in ljubezen z vero od Boga Očeta in Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, '§ Milost bodi z vsemi tistimi, ki z iskrenostjo ljubijo našega Gospoda Jezusa Kristusa. Amen. [Napisano iz Rima Efežanom po Tihiku.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pavel in Timótej, služabnika Jezusa Kristusa, vsem svetim v Kristusu Jezusu, ki so v Filípih, z duhovnimi nadzorniki in pomočniki [Božjih] služabnikov:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Svojemu Bogu se zahvaljujem vsakič, ko se vas spominjam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'vedno v vsaki svoji molitvi z radostjo prosim za vas vse,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'zaradi vaše družbe v evangeliju, od prvega dne do sedaj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'ker sem prepričan o tej sami stvari, da on, ki je v vas začel dobro delo, ga bo opravil do dneva Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Prav tako je zame primerno, da tako mislim o vas vseh, ker vas imam v svojem srcu; glede na to, da ste vi vsi udeleženci moje milosti, tako v mojih verigah kakor v obrambi in potrjevanju evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Kajti Bog je moja priča, kako silno hrepenim po vas vseh v notranjostih Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'In molim to, da bo vaša ljubezen lahko še bolj in bolj obilna v spoznanju in v vsaki razsodbi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'da boste lahko presojali stvari, ki so odlične; da boste lahko iskreni in brez pohujšanja do Kristusovega dne;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'izpolnjeni s sadovi pravičnosti, ki so po Jezusu Kristusu, v slavo in hvalo Božjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Toda, [da] bi razumeli, bratje, da so stvari, ki so se mi zgodile, toliko bolj izpadle v pospeševanje evangelija;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'tako da so moje vezi v Kristusu razpoznavne po vsej palači in po vseh drugih krajih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'in mnogi izmed bratov v Gospodu so z mojimi vezmi povečali samozavest, da so mnogo pogumneje, brez strahu, govorili besedo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Nekateri zares oznanjajo Kristusa celó iz zavisti in prepira, nekateri pa tudi iz dobre volje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'nekdo oznanja Kristusa iz spora, ne iskreno, ker misli, da mojim vezem dodaja stisko,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'toda drug iz ljubezni, vedoč, da sem določen za obrambo evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Kaj torej? Vseeno, vsak način, bodisi s pretvezo ali z resnico, Kristus se oznanja; in v tem se veselim, da in veselil se bom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Kajti vem, da se bo to, po vaših molitvah in oskrbi Duha Jezusa Kristusa, obrnilo k rešitvi moje duše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'glede na moje iskreno pričakovanje in moje upanje, da v ničemer ne bom osramočen, temveč, da bo z vso srčnostjo, kot vedno, tako tudi sedaj, Kristus poveličan v mojem telesu, bodisi bo to z življenjem ali s smrtjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Kajti zame je živeti Kristus in umreti je dobiček.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Toda če živim v mesu, je to sad mojega truda; vendar ne vem, kaj bi izbral.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Kajti v škripcu sem med dvema, ker hrepenim oditi in biti s Kristusom; kar je veliko bolje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'pa vendar je zaradi vas bolj potrebno ostati v mesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'In ker imam to zaupanje, vem, da bom zaradi vašega napredovanja in veselja vere ostal in nadaljeval z vami vsemi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'da bo vaše veselje v Jezusu Kristusu lahko bolj obilno zaradi mene, z mojim ponovnim prihodom k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Samo vaše vedênje naj bo, kakor se to spodobi Kristusovemu evangeliju, da bom bodisi prišel in vas videl, bodisi [da] bom odsoten, lahko slišal o vaših zadevah, da trdno stojite v enem duhu, enega mišljenja in si skupaj prizadevate za vero evangelija;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'in v ničemer prestrašeni od svojih nasprotnikov, kar je njim očiten simbol pogube, toda vam rešitev duš in to od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, '§ Kajti zaradi Kristusa vam je dano, da ne samo verujete vanj, ampak da zaradi njega tudi trpite;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'in imate isti boj, ki ste ga videli v meni in sedaj slišite, da je v meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Če obstaja torej kakršnakoli tolažba v Kristusu, če kakršnakoli tolažba ljubezni, če kakršnakoli družba Duha, če kakršnakoli čustva in usmiljenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'izpolnite moje veselje, da ste istih misli in imate isto ljubezen, da ste soglasni, enega mišljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Naj se nič ne stori zaradi prepira ali ošabnosti, temveč naj vsak v skromnosti mišljenja bolj upošteva drugega kakor sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ne glejte vsakdo na svoje stvari, temveč vsakdo tudi na stvari drugih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'V vas naj bo to mišljenje, ki je bilo tudi v Kristusu Jezusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, '§ ki je, četudi v Božji podobi, mislil, da ni rop, da bi bil enak z Bogom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'temveč je samega sebe naredil brez slôvesa in si privzel obliko služabnika in bil narejen po človeški podobnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'in po videzu zaznan kakor moški, je samega sebe ponižal in postal pokoren do smrti, celó smrti na križu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Zatorej ga je Bog tudi visoko povišal in mu dal ime, ki je nad vsakim imenom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'da naj bi ob imenu Jezus pokleknilo vsako koleno, od stvari na nebu in stvari na zemlji ter stvari pod zemljo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'ter da bi vsak jezik priznal, da je Jezus Kristus Gospod, v slavo Boga Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Zatorej, moji ljubljeni, kakor ste vedno ubogali, ne kakor samo v moji prisotnosti, temveč veliko bolj zdaj, v moji odsotnosti, s strahom in trepetom uresničite svojo lastno rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Kajti Bog je, ki deluje v vas oboje, da hočete in da delate iz njegovega dobrega zadovoljstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Vse stvari delajte brez mrmranj in razpravljanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'da boste lahko brez krivde in neškodljivi Božji sinovi, brez oštevanja v sredi sprijenega in sprevrženega naroda, med katerim sijete kakor luči na svetu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'držeč se besede življenja, da se bom na Kristusov dan lahko veselil, da nisem zaman tekel niti [se nisem] zaman trudil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Da, in če bi bil darovan na žrtev in službo vaše vere, se radostim in se z vami vsemi veselim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Zaradi istega razloga se tudi vi veselite in razveseljujte z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Toda zaupam v Gospoda Jezusa, da v kratkem pošljem k vam Timóteja, da bom tudi jaz, ko izvem vaše stanje, lahko dobro potolažen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Kajti nimam nobenega človeka istih misli, ki bo naravno skrbel za vaše stanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Kajti vsi iščejo svoje lastno, ne [pa] stvari, ki so Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Vendar poznate dokaz o njem, da je z menoj služil v evangeliju kakor sin z očetom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Njega se torej nadejam poslati tako kmalu, kot bom videl, kako bo z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Toda zaupam v Gospoda, da bom kmalu prišel tudi sam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Vendar se mi je zdelo potrebno poslati k vam Epafrodita, mojega brata in družabnika v trudu in soborca, toda vašega odposlanca in tega, ki je služil mojim potrebam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Kajti hrepenel je po vas vseh in bil poln potrtosti; zato ker ste slišali, da je bil bolan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Kajti zares je bil bolan, blizu smrti, toda Bog se ga je usmilil; in ne samo njega, ampak tudi mene, da ne bi imel bridkost na bridkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Poslal sem ga torej bolj hitro, da ko ga boste ponovno videli, se boste lahko razveselili in da bom jaz lahko manj žalosten.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Sprejmite ga torej v Gospodu z vsem veseljem; in take imejte v časti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'ker je bil zaradi Kristusovega dela blizu smrti, ne oziraje se na svoje življenje, da dopolni pomanjkanje vašega služenja do mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Končno, moji bratje, veselite se v Gospodu. Da vam pišem iste stvari, meni zares ni nadležno, toda za vas je to varno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, '§ Pazite se psov, pazite se zlih delavcev, pazite se razkola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, '§ Kajti mi smo obreza, ki obožujemo Boga v duhu in se veselimo v Kristusu Jezusu in nimamo zaupanja v meso.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Čeprav bi tudi jaz lahko imel zaupanje v meso. Če katerikoli drug človek misli, da ima [kaj], glede česar bi lahko zaupal v meso, jaz bolj:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'obrezan osmi dan, iz Izraelove rase, iz Benjaminovega rodu, Hebrejec izmed Hebrejcev, glede postave farizej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'glede gorečnosti sem preganjal cerkev, glede pravičnosti, ki je po postavi, brez krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Toda te stvari, ki so bile zame dobiček, te sem štel izgubo za Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, '§ Da, nedvomno in vse stvari štejem le za izgubo zaradi odličnosti spoznanja Kristusa Jezusa, svojega Gospoda, za katerega sem pretrpel izgubo vseh stvari in jih štejem le za iztrebek, da lahko pridobim Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'in najden bom v njem, ne ker bi imel svojo lastno pravičnost, ki je iz postave, temveč to, ki je po Kristusovi veri, pravičnost, ki je od Boga, po veri;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'da bi lahko spoznal njega in moč njegovega vstajenja in udeležbo njegovih trpljenj in postal podoben njegovi smrti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'če na kakršenkoli način lahko dospem do vstajenja mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne da bi že dospel ali bi bil že popoln; vendar si prizadevam za tem, če bi lahko željno vzel to, zaradi česar sem tudi jaz željno vzet od Kristusa Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bratje, ne štejem se, da sem željno vzet, toda delam to eno stvar in pozabljam te stvari, ki so zadaj in se iztegujem k tem stvarem, ki so spredaj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'pritiskam proti cilju zaradi nagrade visoke poklicanosti od Boga v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Bodimo torej, kolikor nas je popolnih, takega mišljenja; in če ste v katerikoli stvari drugače misleči, vam bo Bog razodel še to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, '§ Pa vendar, kateri smo že dospeli, živimo po istem načelu, mislimo isto stvar.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Bratje, bodite skupaj moji posnemovalci in zapomnite si tiste, ki živijo tako, kakor imate nas za zgled.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, '(Kajti mnogi živijo, o katerih sem vam pogosto povedal in vam sedaj govorim jokaje, da so sovražniki Kristusovega križa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'katerih konec je uničenje, katerih Bog je njihov trebuh in katerih slava je v njihovi sramoti, ki mislijo zemeljske stvari.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Kajti naše državljanstvo je v nebesih, od koder tudi pričakujemo Odrešenika, Gospoda Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'ki bo, glede na delovanje, s katerim si je zmožen k sebi podjarmiti celó vse stvari, spremenil naša nizkotna telesa, da bodo oblikovana podobno njegovemu veličastnemu telesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Zato, moji bratje, srčno ljubljeni in zaželeni, moja radost in krona, tako stojte trdno v Gospodu, moji srčno ljubljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Rotim Evodíjo in rotim Sintího, da bosta istega mišljenja v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'In prosim tudi tebe, resnični soborec, pomagaj tema ženskama, ki sta se z menoj trudili v evangeliju; tudi s Klemnom in z drugimi mojimi sodelavci, katerih imena so v knjigi življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Nenehno se veselite v Gospodu. In ponovno pravim: ›Veselite se.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Naj bo vaša zmernost znana vsem ljudem. Gospod je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ne vznemirjate se in ne skrbite glede ničesar, temveč naj bodo v vsaki stvari vaše želje razglašene Bogu z molitvijo in ponižno prošnjo, z zahvaljevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'In Božji mir, ki presega vse razumevanje, bo varoval vaša srca in mišljenja po Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Končno, bratje, katerekoli stvari so resnične, katerekoli stvari so iskrene, katerekoli stvari so pravične, katerekoli stvari so čiste, katerekoli stvari so očarljive, katerekoli stvari so na dobrem glasu; če obstaja kakršnakoli moč in če obstaja kakršnakoli hvala, mislite na te stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Stvari, ki ste se jih tako naučili, kakor sprejeli in slišali ter videli na meni, te izvršujte; in z vami bo Bog miru.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Toda silno sem se razveselil v Gospodu, da je vaša skrbnost do mene sedaj končno ponovno vzcvetela; v čemer ste tudi bili skrbni, toda manjkala vam je priložnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ne da govorim glede na pomanjkanje, kajti naučil sem se, v kakršnemkoli stanju sem, biti s tem zadovoljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Vem oboje, kako je biti ponižen in vem, kako je biti bogat; povsod in v vseh stvareh sem poučen, tako biti sit kakor biti lačen, tako biti bogat kakor prenašati pomanjkanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Vse stvari lahko storim v Kristusu, ki me krepi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Vendar ste dobro storili, da ste soudeleženi pri moji stiski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Torej vi Filipljani veste tudi, da na začetku evangelija, ko sem odšel iz Makedonije, nobena cerkev ni sodelovala z menoj glede dajanja in sprejemanja, razen vas samih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Kajti celó v Tesaloníko ste večkrat poslali za mojo nujno potrebo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ne, ker [bi si] želel daru, temveč si želim sad, da bo obilen na vaš račun.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Toda imam vse in obilo; sem poln, ker sem od Epafrodita prejel stvari, ki so bile poslane od vas, dišavo sladkega vonja, sprejemljivo žrtvovanje, všečno Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, '§ Toda moj Bog bo preskrbel vse vaše potrebe, glede na svoja bogastva, v slavi, po Jezusu Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Torej Bogu in našemu Očetu bodi slava na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdravite vsakega svetega v Kristusu Jezusu. Pozdravljajo vas bratje, ki so z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdravljajo vas vsi sveti, predvsem tisti, ki so iz cesarjeve družine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Milost našega Gospoda Jezusa Kristusa bodi z vami vsemi. Amen. [To je bilo napisano Filipljanom iz Rima po Epafroditu.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pavel, po Božji volji apostol Jezusa Kristusa in naš brat Timótej,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'svetim in zvestim bratom v Kristusu, ki ste v Kolósah: ›Milost bodi vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Zahvaljujemo se Bogu in Očetu našega Gospoda Jezusa Kristusa, ko nenehno molimo za vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'odkar smo slišali o vaši veri v Kristusa Jezusa in o ljubezni, ki jo imate do vseh svetih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'zaradi upanja, ki je za vas prihranjeno v nebesih, o katerem ste prej slišali v besedi resnice evangelija,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'ki je prišel k vam tako, kakor je po vsem svetu; in prinaša sad, kakor tudi v vas, od dneva, ko ste slišali o njem in spoznali Božjo milost v resnici;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'kakor ste se tudi naučili od Epafrá, našega dragega soslužabnika, ki je za vas zvest Kristusov služabnik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'ki nam je tudi pojasnil vašo ljubezen v Duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Zaradi tega razloga tudi mi od dneva, ko smo to slišali, ne prenehamo moliti za vas in želimo, da bi bili vi lahko izpolnjeni s spoznanjem njegove volje, v vsej modrosti in duhovnem razumevanju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'da bi lahko hodili vredno Gospoda v vsej všečnosti, bili rodovitni v vsakem dobrem delu in rastli v spoznanju Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'okrepljeni z vso močjo, glede na njegovo veličastno moč, v vsej vztrajnosti in potrpežljivosti, z veseljem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'in se zahvaljevali Očetu, ki nas je naredil primerne za udeležence dediščine svetih v svetlobi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'ki nas je osvobodil pred oblastjo teme in nas prenesel v kraljestvo svojega ljubljenega Sina;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, '§ v katerem imamo po njegovi krvi odkupitev, torej odpuščanje grehov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'ki je podoba nevidnega Boga, prvorojenec vsakega ustvarjenega bitja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'kajti po njem so bile ustvarjene vse stvari, ki so na nebu in ki so na zemlji, vidne in nevidne, bodisi so to prestoli ali gospostva ali kneževine ali oblasti; vse stvari so bile ustvarjene po njem in zanj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'in on je pred vsemi stvarmi in po njem vse stvari stojijo skupaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'In on je glava telesa, cerkve; ki ji je začetek, prvorojenec od mrtvih; da bi lahko v vseh stvareh imel prvenstvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, '§ Kajti Očetu je ugajalo, da bi v njem prebivala vsa polnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'in je sklenil mir po krvi njegovega križa, da po njem pobota k sebi vse stvari; po njem, pravim, bodisi, da so stvari na zemlji ali stvari v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'In vas, ki ste bili nekoč odtujeni in v svojem mišljenju po zlobnih delih sovražniki, je vendar sedaj pobotal');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'v telesu njegovega mesa skozi smrt, da vas predstavi svete in neoporečne in brezgrajne v svojem pogledu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'če utemeljeni in ustaljeni nadaljujete v veri in se ne boste oddaljili od upanja evangelija, ki ste ga slišali in ki je bil oznanjen vsakemu ustvarjenemu bitju, ki je pod nebom; katerega sem jaz, Pavel, postal služabnik;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'ki se sedaj veselim v svojih trpljenjih za vas in v svojem mesu dopolnjujem to, kar je zaradi njegovega telesa, ki je cerkev, primanjkovalo Kristusovim stiskam;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'katerega služabnik sem postal, glede na Božjo razdelitev, ki mi je bila dana za vas, da izpolnim Božjo besedo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'celó skrivnost, ki je bila skrita pred veki in pred rodovi, toda sedaj je razodeta njegovim svetim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'katerim je Bog hotel razodeti kakšna so bogastva slave te skrivnosti med pogani; ki je Kristus v vas, upanje slave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, '§ katerega oznanjamo in vsakega človeka svarimo in vsakega človeka učimo v vsej modrosti; da lahko vsakega človeka prikažemo popolnega v Kristusu Jezusu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'zato se tudi trudim in se borim, glede na njegovo delovanje, ki v meni mogočno deluje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Kajti hočem, da bi vedeli, kako velik boj imam za vas in za te iz Laodikeje in za mnoge, četudi niso videli mojega obraza v mesu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, '§ da bodo njihova srca lahko potolažena, stkana skupaj v ljubezni in v vseh bogastvih polnega zagotovila razumevanja, k spoznanju Božje skrivnosti in Očetove in Kristusove;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'v katerem so skriti vsi zakladi modrosti in spoznanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'In to pravim, da vas ne bi katerikoli človek preslepil s prepričevalnimi besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Kajti čeprav sem odsoten v mesu, sem vendar z vami v duhu in se veselim ter zrem vašo urejenost in neomajnost vaše vere v Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Tako kakor ste torej sprejeli Gospoda Kristusa Jezusa, tako živite v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Ukoreninjeni in zgrajeni v njem ter potrjeni v veri, kakor ste bili poučeni in v tem obilni z zahvaljevanjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Pazite, da vas ne bi katerikoli človek oplenil s filozofijo in prazno prevaro po človeškem izročilu, po temeljnih principih sveta, ne pa po Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Kajti v njem telesno prebiva vsa polnost Božanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'In vi ste popolni v njem, ki je glava vseh kneževin in oblasti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, '§ v katerem ste tudi obrezani z obrezo, narejeno brez rok, s slačenjem grešnega mesenega telesa, s Kristusovo obrezo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 's krstom pokopani z njim, v katerem ste tudi vi z njim vstali, po veri Božjega delovanja, ki ga je obudil od mrtvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'In vas, mrtve v vaših grehih in neobrezanosti vašega mesa, je on oživil skupaj z njim ter vam odpustil vse grehe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'in izbrisal rokopis odredb, ki so bile zoper nas, ki nam je bil nasproten in ga odstranil s poti ter ga pribil na svoj križ;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'in ker imamo pokvarjene kneževine in oblasti, je naredil iz njih javni prikaz, slaveč v tem zmago nad njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Ne pustite torej nobenemu človeku, da vas sodi v jedi ali v pijači ali pri spoštovanju svetega dne ali mlaja ali šabatnih dni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'ki so senca stvari, ki pridejo; toda telo je Kristusovo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Ne pustite nobenemu človeku, da vas preslepi glede vaše nagrade, [tako da je] prostovoljno ponižen in obožuje angele in se vsiljuje v te stvari, ki jih ni videl, prazno napihnjen s svojim mesenim umom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'ne drži pa se Glave, od katere ima vse telo po sklepih in vezeh nudeno hrano in stkano skupaj raste z rastjo od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Zatorej, če ste s Kristusom mrtvi temeljnim principom sveta, zakaj ste podrejeni odredbam, kakor da živite v svetu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '(ne dotikaj, ne okušaj, ne prijemaj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'ki bodo z uporabo vsi odmrli) po človeških zapovedih in naukih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Katere stvari imajo resnično navidezen prikaz modrosti v pobožnem oboževanju in ponižnosti in zapostavljanju telesa; v zadovoljevanje mesa, ne pa v kakršnokoli vrednost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Če ste bili torej obujeni s Kristusom, iščite te stvari, ki so zgoraj, kjer Kristus sedi na Božji desnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Naravnajte svojo naklonjenost na stvari zgoraj, ne na stvari na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Kajti umrli ste in vaše življenje je s Kristusom skrito v Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Ko se bo prikazal Kristus, ki je naše življenje, tedaj se boste tudi vi prikazali z njim v slavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Mrtvite torej svoje ude, ki so na zemlji: prešuštvovanje, nečistost, nebrzdano strast, zlo poželjivost in pohlepnost, kar je malikovanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'kajti zaradi teh stvari prihaja Božji bes na otroke neposlušnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'v katerih ste tudi vi nekaj časa hodili, ko ste živeli v njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Toda sedaj tudi vse to odložite: jezo, bes, zlobnost, bogokletje, umazan govor iz vaših ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ne lažite drug drugemu, ker ste slekli starega človeka z njegovimi dejanji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'in si nadeli novega človeka, ki je obnovljen v spoznanju, po podobi njega, ki ga je ustvaril;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'kjer ni niti Grka, niti Juda, obreze, niti neobreze, tujca, Skita, sužnja, niti svobodnega, temveč je Kristus vse in v vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Nadenite si torej, kot Božji izvoljenci, sveti in ljubljeni, čustva usmiljenja, prijaznost, ponižnost mišljenja, krotkost, potrpežljivost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'prizanašajte drug drugemu in odpuščajte drug drugemu, če ima katerikoli človek spor proti komurkoli. Torej kakor je Kristus odpustil vam, tako tudi vi počnite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'In nad vsemi temi stvarmi si oblecite ljubezen, ki je vez popolnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'In Božji mir naj vlada v vaših srcih, h kateremu ste tudi poklicani v enem telesu; in bodite hvaležni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Naj Kristusova beseda bogato prebiva v vas v vsej modrosti; drug drugega učite in opominjajte s psalmi in hvalnicami ter duhovnimi pesmimi in prepevajte Gospodu z milostjo v svojih srcih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'In karkoli delate v besedi ali dejanju, vse delajte v imenu Gospoda Jezusa in po njem dajajte zahvalo Bogu in Očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Žene, podredite se svojim lastnim soprogom, kakor se to spodobi v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Soprogi, ljubíte svoje žene in ne bodite osorni proti njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Otroci, ubogajte svoje starše v vseh stvareh, kajti to je zelo prijetno Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Očetje, ne provocirajte svojih otrok k jezi, da ne bi izgubili poguma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, '§ Služabniki, v vseh stvareh ubogajte svoje gospodarje po mesu; ne z navidezno vdanostjo, kakor da bi raje ugajali ljudem; temveč v iskrenosti srca, boječ se Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'In karkoli delate, delajte to iz srca, kakor Gospodu in ne ljudem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'vedoč, da boste od Gospoda prejeli nagrado dediščine; kajti vi služite Gospodu Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Toda kdor dela krivico, bo za krivico prejel, kar je storil; in ni oziranja na osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Gospodarji, dajajte svojim služabnikom to, kar je pravično in primerno; vedoč, da imate tudi vi Gospodarja v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Vztrajajte v molitvi in bedite v njej z zahvaljevanjem;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'poleg tega molíte tudi za nas, da bi nam Bog odprl vrata izgovarjave, da bomo govorili Kristusovo skrivnost, zaradi katere sem tudi v vezeh;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'da jo bom lahko prikazal, kakor sem dolžan govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Živite v modrosti do teh, ki so zunaj in izkoristite čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Naj bo vaš govor vedno z milostjo, začinjen s soljo, da boste lahko vedeli, kako bi morali odgovarjati vsakemu človeku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Ves moj položaj vam bo razglasil Tihik, ki je ljubljeni brat in zvest služabnik ter soslužabnik v Gospodu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, '§ ki sem ga k vam poslal z istim namenom, da bi lahko spoznal vaš položaj in potolažil vaša srca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'z Onézimom, zvestim in ljubljenim bratom, ki je eden izmed vas. Dala vam bosta spoznati vse stvari, ki so storjene tukaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdravljajo vas Aristarh, moj sojetnik in Marko, sin Barnabove sestre (glede katerega ste prejeli zapovedi; če pride k vam, ga sprejmite)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'in Jezus, ki se imenuje Just, ki so iz obreze. Samo ti so moji sodelavci za Božje kraljestvo, ki so mi bili v tolažbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, '§ Pozdravlja vas Epafrá, ki je eden izmed vas, Kristusov služabnik, ki se vedno goreče bori za vas v molitvah, da bi lahko stali popolni in dovršeni, v vsej Božji volji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Kajti prinašam mu pričevanje, da ima veliko gorečnost za vas in za tiste, ki so v Laodikeji in za one v Hierápoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdravljata vas Luka, ljubljeni zdravnik in Demá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdravite brate, ki so v Laodikeji in Nimfása ter cerkev, ki je v njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'In ko preberete to poslanico med vami, poskrbite, da se bo brala tudi v cerkvi Laodikejcev; in da tudi vi preberete poslanico iz Laodikeje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'In Arhipu recite: »Pazi na službo, ki si jo prejel v Gospodu, da jo izpolnjuješ.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdrav z mojo, Pavlovo roko. Spominjajte se mojih vezi. Milost bodi z vami. Amen. [Napisano iz Rima Kološanom, po Tihiku in Onézimu.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, '§ Pavel in Silván ter Timótej cerkvi Tesaloníčanov, ki je v Bogu Očetu in v Gospodu Jezusu Kristusu: ›Milost bodi vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Vedno se za vas vse zahvaljujemo Bogu in vas omenjamo v svojih molitvah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'ko se brez prenehanja spominjamo vašega dela vere in truda ljubezni ter potrpežljivosti upanja v našega Gospoda Jezusa Kristusa, pred očmi Boga in našega Očeta;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'ker poznamo, ljubljeni bratje, vašo izvolitev od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Kajti naš evangelij ni prišel k vam samo v besedi, temveč tudi v moči in v Svetem Duhu in v precejšnjem zagotovilu; kakor veste, kakšne vrste ljudje smo bili med vami zaradi vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'In vi ste postali naši in Gospodovi sledilci, ker ste besedo sprejeli v veliki stiski, z veseljem Svetega Duha,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'tako da ste bili zgledi vsem, ki verujejo v Makedoniji in Ahaji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Kajti od vas je odmevala Gospodova beseda ne samo po Makedoniji in Ahaji, temveč se je vaša, do Boga usmerjena vera, razširila tudi naokoli, po vsakem kraju; tako da nam ni treba karkoli govoriti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'kajti oni sami so o nas prikazali kakšne vrste prihod smo imeli k vam in kako ste se od malikov obrnili k Bogu, da služite živemu in resničnemu Bogu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'in da čakate na njegovega Sina iz nebes, ki ga je obudil od mrtvih, celó Jezusa, ki nas je osvobodil pred besom, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Kajti bratje, vi sami veste, da naš prihod k vam ni bil zaman,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'temveč smo celó potem, ko smo poprej v Filípih trpeli in bili sramotno obravnavani, kakor veste, smo bili v našem Bogu pogumni, da smo vam v velikem boju izpričali Božji evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Kajti naše spodbujanje ni bilo iz prevare niti iz nečistosti niti v zvijači,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'temveč kakor nam je Bog dopustil, da nam zaupa evangelij, točno tako govorimo; ne kakor ugajajoči ljudem, temveč Bogu, ki preizkuša naša srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Kajti niti nismo ob kateremkoli času uporabili laskavih besed, kakor veste niti pretveze pohlepnosti; Bog je priča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Niti nismo iskali slave od ljudi niti od vas niti ne od drugih, ko bi lahko bili obremenjujoči kot Kristusovi apostoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Toda med vami smo bili nežni, tako kakor dojilja neguje svoje otroke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Tako smo vas bili vdano željni, da smo vam bili voljni podeliti ne samo Božji evangelij, ampak tudi naše duše, ker ste nam bili dragi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Kajti spomnite se, bratje, našega truda in muke; kajti ponoči in podnevi smo garali, ker nismo želeli biti obremenitev komurkoli izmed vas, ko smo vam pridigali Božji evangelij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vi ste priče in tudi Bog, kako sveto in pravično in neoporečno smo se vêdli med vami, ki verujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Prav tako veste, kako smo tolažili in opozarjali vsakega izmed vas, tako kakor oče počne svojim otrokom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'da bi vi živeli vredno Boga, ki vas je poklical v svoje kraljestvo in slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Zaradi tega razloga se prav tako brez prenehanja zahvaljujemo Bogu, kajti ko ste prejeli Božjo besedo, ki ste jo slišali od nas, je niste sprejeli kakor človeško besedo, temveč takšno, kot je v resnici, Božjo besedo, ki učinkovito deluje tudi v vas, ki verujete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Kajti vi, bratje, ste postali sledilci Božjih cerkvá, ki so v Judeji v Kristusu Jezusu; kajti tudi vi ste trpeli podobne stvari od svojih lastnih rojakov, takšne, kot so jih oni od Judov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'ki so ubili tako Gospoda Jezusa kakor svoje lastne preroke in so preganjali nas; pa ne ugajajo Bogu in so nasprotni vsem ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Branijo nam govoriti poganom, da bi bili le-ti lahko rešeni in da bi vsakič dopolnili svoje grehe; kajti bes je prišel nadnje do skrajnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Toda mi, bratje, ki smo bili za kratek čas vzeti od vaše navzočnosti, [toda] ne v srcu, smo si z velikim hrepenenjem toliko obilneje prizadevali, da vidimo vaše obličje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Zato smo želeli priti k vam, celó jaz Pavel, enkrat in ponovno; toda Satan nas je zadržal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Kajti kaj je naše upanje ali veselje ali krona radosti? Ali ne celó vi v prisotnosti našega Gospoda Jezusa Kristusa ob njegovem prihodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Kajti vi ste naša slava in veselje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Zato, ko nismo mogli več potrpeti, smo mislili, da je dobro, da v Atenah ostanemo sami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'in smo poslali Timóteja, našega brata in Božjega služabnika in našega sodelavca pri Kristusovem evangeliju, da vas utrdi in da vas potolaži glede vaše vere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'da ne bi bil noben človek omajan s temi stiskami, kajti vi sami veste, da smo določeni za to.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Kajti resnično, ko smo bili z vami, smo vam vnaprej povedali, da naj bi trpeli stisko; kakor se je zgodilo in vi to veste.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Zaradi tega razloga, ko nisem mogel več potrpeti, sem poslal, da spoznam vašo vero, da vas ne bi z nekimi načini skušal skušnjavec in bi bil naš trud zaman.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Toda sedaj, ko je od vas k nam prišel Timótej in nam prinesel dobre novice o vaši veri ter ljubezni in da nas imate vedno v lepem spominu ter si silno želite, da nas vidite, kakor si tudi mi [želimo] videti vas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'zato smo bili, bratje, po vaši veri potolaženi glede vas v vsej naši stiski in tegobi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'kajti zdaj živimo, če vi trdno stojite v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Kajti kakšne zahvale lahko spet za vas vrnemo Bogu, za vse veselje, s katerim se zaradi vas veselimo pred svojim Bogom?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Ponoči in podnevi silno prosimo, da bi lahko videli vaš obraz in lahko dovršili to, kar primanjkuje vaši veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Torej sam Bog in naš Oče in naš Gospod Jezus Kristus [naj] našo pot usmerjata k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'In Gospod [naj] vam stori, da rastete in [ste] obilni v ljubezni drug do drugega in do vseh ljudi, prav tako kakor mi počnemo vam,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'z namenom, da bi lahko vaša srca utrdil brez graje v svetosti pred Bogom, celó našim Očetom, ob prihodu našega Gospoda Jezusa Kristusa z vsemi njegovimi svetimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Nadalje vas potem rotimo, bratje in vas spodbujamo po Gospodu Jezusu, da kakor ste od nas prejeli, kako bi morali živeti in ugajati Bogu, tako da bi bili bolj in bolj obilni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Kajti veste, kakšne zapovedi smo vam dali po Gospodu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Kajti to je Božja volja, celó vaše posvečenje, da naj bi se vzdržali pred prešuštvovanjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'da bi vsakdo izmed vas vedel, kako čuvati svojo posodo v posvečenju in časti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ne [pa] v poželenju pohotnosti, tako kakor pogani, ki ne poznajo Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'da noben človek ne gre preko in ne goljufa svojega brata v katerikoli zadevi; zato ker je Gospod maščevalec vsega tega, kakor smo vas tudi mi svarili in pričevali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Kajti Bog nas ni poklical k nečistosti, temveč v svetost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Kdor torej prezira, ne prezira človeka, temveč Boga, ki nam je prav tako dal svojega Svetega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Toda glede bratoljúbja ne potrebujete, da vam pišem, kajti vi sami ste od Boga poučeni, da ljubite drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'In zares to delajte do vseh bratov, ki so po vsej Makedoniji. Toda rotimo vas, bratje, da bolj in bolj rastete');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'in da se učite biti mirni ter opravljati svoje lastno opravilo in da delate s svojimi lastnimi rokami, kakor smo vam zapovedali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'da boste lahko živeli iskreno do teh, ki so zunaj in da ne boste ničesar potrebovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Toda ne želim, da bi bili vi nevedni, bratje, glede teh, ki so zaspali, da ne žalujete, tako kakor drugi, ki nimajo upanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Kajti če verujemo, da je Jezus umrl in ponovno vstal, bo točno tako tudi tiste, ki spijo v Jezusu, Bog privedel z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Kajti to vam rečemo po Gospodovi besedi, da mi, ki smo živi in ostanemo do Gospodovega prihoda, ne bomo vodili teh, ki so zaspali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Kajti sam Gospod se bo spustil iz nebes z vzklikom, z glasom nadangela in z Božjo trobento; in prvi bodo vstali mrtvi v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Potem pa bomo mi, ki smo živi in preostanemo, vzeti skupaj z njimi v oblake, da srečamo Gospoda v zraku, in tako bomo vedno z Gospodom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Zato drug drugega tolažite s temi besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Toda o časih in obdobjih, bratje, ni potrebno, da vam pišem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Kajti vi sami prav dobro veste, da dan Gospodov prihaja tako, kakor tat ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Kajti ko bodo govorili: »Mir in varnost,« tedaj nenadoma pride nadnje uničenje, kakor porodne muke na žensko z otrokom; in ne bodo ubežali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Toda vi, bratje, niste v temi, da vas tisti dan preseneti kakor tat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Vi vsi ste otroci svetlobe in otroci dneva. Nismo od noči niti od teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Zatorej ne spimo, kakor počno drugi, temveč čujmo in bodimo trezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Kajti tisti, ki spijo, spijo ponoči; in tisti, ki se opijajo, so pijani ponoči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Toda mi, ki smo od dneva, bodimo trezni, nadenimo si prsni oklep vere in ljubezni in za čelado upanje rešitve duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Kajti Bog nas ni določil za bes, temveč da dosežemo rešitev duše po našem Gospodu Jezusu Kristusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'ki je umrl za nas, da bodisi smo budni ali spimo, naj bi živeli skupaj z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Zato se skupaj tolažite in izgrajujte drug drugega, kakor tudi počnete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'In rotimo vas bratje, da spoznate te, ki se med vami trudijo in so nad vami v Gospodu ter vas opominjajo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'in da jih zaradi njihovega dela zelo visoko spoštujte v ljubezni. In bodite v miru med seboj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Torej vas spodbujamo, bratje, posvarite te, ki so nepodrejeni, tolažite malodušne, podpirajte slabotne, bodite potrpežljivi do vseh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Glejte, da nihče nobenemu človeku ne vrača zla za zlo, temveč vedno sledite temu, kar je dobro, tako med seboj kakor do vseh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Neprenehoma se veselite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Molíte brez prenehanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'V vsaki stvari se zahvaljujte, kajti to je Božja volja v Kristusu Jezusu glede vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ne gasite Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Ne prezirajte prerokovanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Preizkušajte vse stvari; trdno držite to, kar je dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, '§ Vzdržite se vsega videza zla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'In sam Bog miru naj vas popolnoma posveti; in prosim Boga, da bodo vaš celoten duh in duša in telo ohranjeni neomadeževani do prihoda našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Zvest je on, ki vas kliče, ki bo to tudi storil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bratje, molíte za nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdravite vse brate s svetim poljubom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Po Gospodu vam naročam, da bo ta poslanica prebrana vsem svetim bratom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Milost našega Gospoda Jezusa Kristusa bodi z vami. Amen. [Prva poslanica Tesaloníčanom je bila napisana iz Aten.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pavel in Silván ter Timótej, cerkvi Tesaloníčanov v Bogu, našem Očetu in Gospodu Jezusu Kristusu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, '›Milost vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Dolžni smo, da se vedno zahvaljujemo Bogu za vas, bratje, kakor se spodobi, zato ker ta vaša vera silno raste in je ljubezen vsakogar izmed vas vseh do drug drugega obilna,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'tako, da se mi sami ponašamo z vami po Božjih cerkvah, zaradi vaše potrpežljivosti in vere, v vseh vaših preganjanjih in stiskah, ki jih prenašate;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'kar je razpoznaven simbol pravične Božje sodbe, da boste lahko šteti vredne Božjega kraljestva, za katerega tudi trpite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Čeprav je pri Bogu pravična stvar, da poplača stisko tem, ki vas stiskajo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'vam pa, ki ste stiskani, počitek z nami, ko se bo Gospod Jezus, razodet iz nebes, s svojimi mogočnimi angeli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'v plamenečem ognju maščeval na teh, ki ne poznajo Boga in ne ubogajo evangelija našega Gospoda Jezusa Kristusa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'ki bodo kaznovani z večnim uničenjem proč od Gospodove prisotnosti in proč od slave njegove moči;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, '§ ko bo prišel, da bo proslavljen v svojih svetih in da bo občudovan v vseh teh, ki verujejo (ker so verovali našemu pričevanju med vami) na tisti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Zatorej tudi vedno molimo za vas, da vas bo naš Bog imel za vredne te poklicanosti in izpolnite vso dobro voljo njegove dobrote ter delo vere v môči;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'da bo v vas lahko proslavljeno ime našega Gospoda Jezusa Kristusa in vi v njem, glede na milost našega Boga in Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Torej vas rotimo, bratje, pri prihodu našega Gospoda Jezusa Kristusa in pri našem zbiranju k njemu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'da ne boste kmalu pretreseni v mišljenju ali bili vznemirjeni, niti po duhu, niti z besedo, niti s pismom kot od nas, kakor da je blizu Kristusov dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Nobenemu človeku ne pustite, da vas na kakršenkoli način zavede, kajti ta dan ne bo prišel, razen če ne bo najprej prišlo odpadanje in da se razodene grešen človek, sin pogube,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'ki nasprotuje in se povišuje nad vse, kar se imenuje Bog ali kar se obožuje, tako da se le-ta kakor Bog usede v Božji tempelj in se razkazuje, da je Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Se ne spomnite, da ko sem bil še z vami, sem vam te stvari povedal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Sedaj poznate, kaj ga zadržuje, da bi se lahko razodel ob svojem času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Kajti skrivnost krivičnosti že deluje. Samo tisti, ki sedaj ovira, bo oviral, dokler ne bo umaknjen s poti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'In takrat bo razodet ta Zlobni, ki ga bo Gospod pokončal z dihom svojih ust in uničil s sijajem svojega prihoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Torej njega, katerega prihod je po Satanovem delovanju z vso močjo in znamenji ter lažnimi čudeži');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'in z vso varljivostjo nepravičnosti v teh, ki umirajo, zato ker niso sprejeli ljubezni do resnice, da bi bili lahko rešeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'In zaradi tega razloga jim bo Bog poslal močno zablodo, da bi verjeli laži;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'da bodo lahko obsojeni vsi, ki niso verjeli resnici, temveč so uživali v nepravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Toda mi smo dolžni, da se nenehno zahvaljujemo Bogu za vas, od Gospoda ljubljeni bratje, ker vas je Bog od začetka izbral za rešitev duše s posvečenjem Duha in prepričanjem v resnico;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'kamor vas je poklical po našem evangeliju, k doseganju slave našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Torej bratje, stojte trdno in držite se izročil, o katerih ste bili poučeni, bodisi z besedo ali našo poslanico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Torej sam naš Gospod Jezus Kristus in Bog, celó naš Oče, ki nas je ljubil in nam je po milosti dal večno tolažbo ter dobro upanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, '[naj] tolaži vaša srca ter vas utrdi v vsaki dobri besedi in delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Končno, bratje, molíte za nas, da bi Gospodova beseda imela prosto pot in bi bila proslavljena, tako kakor je pri vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'in da bi bili mi lahko rešeni pred nerazumnimi in zlobneži, kajti vsi ljudje nimajo vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Toda Gospod je zvest, ki vas bo utrdil in vas varoval pred zlom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Glede vas pa imamo zaupanje v Gospodu, da tako delate, kakor boste delali stvari, ki vam jih zapovedujemo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'In Gospod naj vodi vaša srca v Božjo ljubezen in v potrpežljivo čakanje na Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Torej vam naročamo, bratje, v imenu našega Gospoda Jezusa Kristusa, da se oddaljite od vsakega brata, ki živi neredno in ne po izročilu, ki ga je prejel od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Kajti vi sami veste, kako nas morate posnemati, kajti med vami se nismo vedli neredno');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'niti nismo zastonj jedli kruha kateregakoli človeka, temveč smo noč in dan delali z muko in garanjem, da ne bi bili nikomur izmed vas v breme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Ne, ker ne bi imeli avtoritete, temveč da sebe naredimo za zgled vam, da bi nas posnemali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Kajti celó, ko smo bili z vami, smo vam zapovedali to, da če kdorkoli noče delati, naj tudi ne bi jedel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Kajti slišimo, da so med vami nekateri, ki živijo neredno, ki sploh ne delajo, temveč so vtikljivci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Torej tem, ki so takšni, velevamo in jih spodbujamo pri našem Gospodu Jezusu Kristusu, da v spokojnosti delajo in jedo svoj lastni kruh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Toda vi, bratje, ne bodite izmučeni v počenjanju dobrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'In če kdorkoli ni poslušen naši besedi v tej poslanici, tega človeka si zaznamujte in se ne družite z njim, da bo osramočen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Vendar ga ne imejte za sovražnika, ampak ga opominjajte kakor brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Torej sam Gospod miru [naj] vam vsekakor vedno daje mir. Gospod bodi z vami vsemi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdrav od Pavla z mojo lastno roko, kar je simbol v vsaki poslanici. Tako pišem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, '§ Milost našega Gospoda Jezusa Kristusa bodi z vami vsemi. Amen. [Druga poslanica Tesaloníčanom je bila napisana iz Aten.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, '§ Pavel, apostol Jezusa Kristusa po zapovedi Boga, našega Odrešenika in Gospoda Jezusa Kristusa, ki je naše upanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timóteju, mojemu lastnemu sinu v veri: ›Milost, usmiljenje in mir od Boga, našega Očeta in Jezusa Kristusa, našega Gospoda.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Kakor sem te rotil, ko sem odšel v Makedonijo, da še ostaneš v Efezu, da bi lahko nekaterim naročil, da ne učijo nobenega drugega nauka,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'niti ne dajo pozornosti bajkam in neskončnim rodovnikom, kar prej podpira razprave, kakor [pa] bogaboječe izgrajevanje, ki je v veri. Tako delajte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Torej namen zapovedi je ljubezen iz čistega srca in iz dobre vesti ter iz nehlinjene vere,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'od katere so se nekateri oddaljili in obrnili stran k praznemu blebetanju;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'želeč biti učitelji postave; [pa] niti ne razumejo kaj govorijo niti o čemer zatrjujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Toda mi vemo, da je postava dobra, če jo človek uporablja zakonito;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'vedoč to, da postava ni narejena za pravičnega človeka, temveč za nepostavnega in neposlušnega, za brezbožnega in za grešnike, za nesvete in oskrunjene, za morilce očetov in morilce mater, za ubijalce,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'za vlačugarje, za tiste, ki sebe omadežujejo z možmi, za ugrabitelje ljudi, za lažnivce, za krivoprisežnike in če je katerakoli druga stvar, ki je nasprotna zdravemu nauku;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'glede na slavni evangelij blagoslovljenega Boga, ki je bil zaupan mojemu varstvu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'In zahvaljujem se Kristusu Jezusu, našemu Gospodu, ki me je usposobil in me postavil v službo, kajti imel me je za zvestega;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'ki sem bil prej bogokletnik in preganjalec ter škodljivec. Toda dosegel sem usmiljenje, ker sem to počel nevedno, v nejeveri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Milost našega Gospoda pa je bila silno bogata z vero in ljubeznijo, ki je v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'To je zvest izrek in vreden popolnega sprejetja, da je Kristus Jezus prišel na svet, da reši grešnike; od katerih sem jaz vodilni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Vendar sem zaradi tega razloga dosegel usmiljenje, da bi Jezus Kristus lahko vnaprej na meni pokazal vso potrpežljivost za vzor tem, ki naj bi odslej verovali vanj za večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Torej Kralju, večnemu, nesmrtnemu, nevidnemu, edinemu modremu Bogu, bodi čast in slava na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'To naročilo sem zaupal tebi, sin Timótej, glede na prerokbe, ki so izšle poprej o tebi, da boš po njih lahko bojeval dober boj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'in obdržiš vero in dobro vest; ki so jo nekateri zavrgli in glede vere storili brodolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Od katerih sta Himénaj in Aleksander; ki sem ju izročil Satanu, da bi se lahko naučila ne preklinjati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Predvsem torej spodbujam, da naj bodo ponižne prošnje, molitve, posredovanja in zahvaljevanja narejeni za vse ljudi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'za kralje in za vse, ki so na oblasti; da bomo lahko preživljali tiho in mirno življenje, v vsej bogaboječnosti in poštenosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Kajti to je dobro in sprejemljivo v očeh Boga, našega Odrešenika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'ki hoče, da bi bili vsi ljudje rešeni in da pridejo do spoznanja resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Kajti obstaja en Bog in en posrednik med Bogom in ljudmi, človek Kristus Jezus;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'ki je samega sebe dal v odkupnino za vse, da se bo pričevalo ob primernem času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, '§ Kateremu sem določen za pridigarja in apostola (govorim resnico v Kristusu in ne lažem), učitelja poganov v veri in resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Hočem torej, da možje povsod molijo, vzdigujoč svete roke, brez besa in dvoma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'In da na podoben način tudi ženske sebe olepšajo s preprosto obleko, s sramežljivostjo in preudarnostjo; ne s prepletanjem las ali zlatom ali biseri ali dragim oblačilom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'temveč (kar je primerno ženskam, ki izražajo bogaboječnost) z dobrimi deli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Naj se ženska pouči v tišini z vso podložnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Toda ženski ne dovolim poučevati niti da si prisvoji oblast nad moškim, ampak, da je v tišini.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Kajti najprej je bil oblikovan Adam, potem Eva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'In ni bil zaveden Adam, temveč ženska, ki je bila zavedena v prestopek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Vendar pa bo rešena z rojevanjem, če oni nadaljujejo v veri in ljubezni in svetosti s preudarnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'To je zvest izrek: »Če človek hrepeni po službi duhovnega nadzornika, želi dobro delo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Duhovni nadzornik mora biti torej brez krivde, soprog ene žene, oprezen, trezen, dobrega vedênja, predan gostoljubnosti, zmožen za poučevanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, '§ Ne vdan vinu, ne razuzdanec, ne pohlepen ali umazano grabežljiv; temveč potrpežljiv, ne razgrajač, ne lakomen;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'tisti, ki dobro vodi svojo lastno družino, ima svoje otroke v podložnosti z vso resnostjo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(kajti če mož ne ve, kako vladati svoji lastni hiši, kako bo skrbel za Božjo cerkev?)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Ne novinec, da ne bi, kipeč od ponosa, padel v hudičevo obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Poleg tega mora imeti dober glas od teh, ki so zunaj; da ne pade v grajo ter v hudičevo zanko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Prav tako morajo biti pomočniki [Božjih] služabnikov dostojanstveni, ne dvoumnih besed, ne vdani obilnemu vinu, ne pohlepni po umazani grabežljivosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'ki s čisto vestjo obdržijo skrivnost vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'In ti naj bodo najprej preizkušeni; potem pa naj, najdeni brez krivde, služijo kot pomočniki [Božjega] služabnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Prav tako morajo biti njihove žene dostojanstvene, ne obrekovalke, trezne, zveste v vseh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Naj bodo pomočniki [Božjih] služabnikov soprogi ene žene, ki dobro vladajo svojim otrokom in svoji lastni hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Kajti tisti, ki so se pravilno posluževali službe pomočnika [Božjega] služabnika, so si pridobili dober položaj in veliko hrabrost v veri, ki je v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Te stvari ti pišem, ker upam, da v kratkem pridem k tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Toda če se bom dolgo mudil, da boš lahko vedel, kako bi se moral obnašati v Božji hiši, ki je cerkev živega Boga, steber in temelj resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, '§ In skrivnost prave bogaboječnosti je brez polemike velika. Bog je bil razodet v mesu, opravičen v Duhu, viden od angelov, oznanjen poganom, svet je vanj veroval, sprejet je bil gor v slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Duh torej izrecno govori, da bodo v poznejših časih nekateri odšli od vere in dajali pozornost zapeljivim duhovom in hudičevim naukom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'v hinavščini govoreč laži; ki imajo svojo vest ožgano z vročim železom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'prepovedovali bodo poročanje in zapovedovali vzdržati se jedi, ki jih je Bog ustvaril, da bi bile sprejete z zahvaljevanjem teh, ki verujejo in poznajo resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Kajti vsako Božje bitje je dobro in nič naj ne bo odklonjeno, če je to sprejeto z zahvaljevanjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'kajti posvečeno je z Božjo besedo in molitvijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Če brate spominjaš na te stvari, boš dober služabnik Jezusa Kristusa, hranjen z besedami vere in zdravega nauka, ki si mu sledil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Toda zavrni bajke oskrunjenih in starih žensk ter se raje uri v bogaboječnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Kajti telesno urjenje malo koristi, toda bogaboječnost je koristna za vse stvari, ki ima obljubo življenja, ki je sedaj in tega, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'To je zvest izrek in vreden popolnega sprejetja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Kajti zato se tako trudimo, kakor prenašamo grajo, ker zaupamo v živega Boga, ki je Odrešenik vseh ljudi, zlasti teh, ki verujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Te stvari zapoveduj in uči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ne dopusti, da kdorkoli prezira tvojo mladost; temveč bodi zgled vernikom v besedi, vedênju, v ljubezni, v duhu, v veri, v čistosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Dokler ne pridem, daj pozornost branju, spodbujanju [in] nauku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne zanemarjaj daru, ki je v tebi, ki ti je bil dan po prerokbi, s polaganjem rok zbora starešin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, '§ Premišljuj o teh stvareh; v celoti se jim izroči; da bo tvoj napredek lahko viden vsem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Pazi nase in na nauk; nadaljuj v njih, kajti s takšnim ravnanjem boš rešil tako sebe kakor tudi tiste, ki te poslušajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne oštej starešine, temveč ga milo prosi kakor očeta; in mlajše može kakor brate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'starejše ženske kakor matere; mlajše kakor sestre, z vso čistostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Spoštuj vdove, ki so zares vdove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Toda če ima katerakoli vdova otroke ali nečake, naj se najprej naučijo doma pokazati spoštovanje in povračati svojim staršem; kajti to je dobro in sprejemljivo pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Torej tista, ki je zares vdova in zapuščena, zaupa v Boga ter noč in dan nadaljuje v ponižnih prošnjah ter molitvah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Toda tista, ki živi v užitku, je mrtva, medtem ko živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'In zapoveduj te stvari, da bodo lahko brez krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Toda če kdorkoli ne skrbi za svoje lastne in [še] posebej za tiste iz svoje lastne hiše, je zanikal vero in je slabši kot nevernik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Ne pustite, da bi bila sprejeta vdova z manj kot šestdesetimi leti, ki je bila žena enega moža,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'z dobrim pričevanjem o dobrih delih; če je vzgajala otroke, če je prenočevala tujce, če je svetim umivala stopala, če je pomagala trpečim, če je marljivo sledila vsakemu dobremu delu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Toda mlajše vdove zavrni, kajti ko začnejo postajati poltene, zoper Kristusa, se hočejo možiti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'imajo obsodbo, ker so zavrgle svojo prvo vero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'In poleg tega se naučijo biti brezdelne in se klatijo okoli od hiše do hiše; in ne samo brezdelja, temveč tudi klepetanja in vtikljivosti [v zadeve drugih], govoreč stvari, ki jih ne bi smele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Hočem torej, da se mlajše ženske omožijo, rodijo otroke, vodijo hišo, ne dajo nobene priložnosti nasprotniku, da govori grajajoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Kajti nekatere so se že obrnile proč za Satanom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Če ima katerikoli moški ali ženska, ki veruje, vdove, naj jih podpira in naj se ne obremenjuje cerkev, da bo ta lahko podpirala tiste, ki so zares vdove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Naj bodo starešine, ki dobro vladajo, šteti za vredne dvojne časti, posebej tisti, ki se trudijo v besedi in nauku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Kajti pismo pravi: ›Ne boš zavezal gobca volu, ki mane žito.‹ In: ‹Delavec je vreden svoje nagrade.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Proti starešini ne sprejmi obtožbe, razen pred dvema ali tremi pričami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Te, ki grešijo, oštej pred vsemi, da se bodo tudi drugi lahko bali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, '§ Naročam ti pred Bogom in Gospodom Jezusom Kristusom in izvoljenimi angeli, da obeležuješ te stvari, brez dajanja prednosti enemu pred drugim in ničesar ne delaj s pristranskostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Na nobenega človeka naglo ne polagaj rok niti ne bodi soudeleženec grehov drugih ljudi. Sebe ohrani čistega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne pij več vode, temveč zaradi trebuha in svojih pogostih slabotnosti užij malce vina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Grehi nekaterih ljudi so razkriti vnaprej in gredo prej na sodbo; in [grehi] nekaterih ljudi sledijo kasneje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Podobno so tudi dobra dela nekaterih vnaprej razodeta; in tista, ki so drugačna, ne morejo biti skrita.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Toliko služabnikov, kot jih je podjarmljenih, naj imajo svoje lastne gospodarje za vredne vse časti, da se zoper Božje ime in njegov nauk ne bi izrekalo bogokletje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'In tisti, ki imajo verne gospodarje, naj jih ne prezirajo zato, ker so bratje; temveč naj jim raje služijo, ker so zvesti in ljubljeni, soudeleženci dobička. Te stvari úči in spodbujaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Če katerikoli človek uči drugače in ne pritrjuje zdravim besedam, celó besedam našega Gospoda Jezusa Kristusa in nauku, ki je glede na bogaboječnost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'je ponosen in ničesar ne ve, marveč boleha glede vprašanj in besednih prepirov, od česar prihajajo zavist, prepir, posmehovanja, hudobna domnevanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, '§ sprevržena razpravljanja ljudi izprijenih misli in oropanih resnice, ki mislijo, da je bogaboječnost [vir] dobička. Od takšnih se umaknite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, '§ Toda bogaboječnost je, skupaj z zadovoljstvom, velik dobiček.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Kajti ničesar nismo prinesli na ta svet in nedvomno je, [da] ničesar ne moremo odnesti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'In bodimo zadovoljni s tem, da imamo hrano in obleko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Toda tisti, ki hočejo biti bogati, padejo v skušnjavo in zanko ter v mnoga nespametna in škodljiva poželenja, ki ljudi potopijo v uničenje in pogubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Kajti ljubezen do denarja je korenina vsega zla; za katerim so nekateri zahlepeli, zašli od vere in se prebodli z mnogimi bridkostmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Toda ti, oh Božji mož, beži od teh stvari in si prizadevaj za pravičnost, bogaboječnost, vero, ljubezen, potrpežljivost in krotkost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Bojuj dober boj vere, oprimi se večnega življenja, kamor si tudi poklican in si pred mnogimi pričami izpovedal dobro izpoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Dajem ti naročilo v očeh Boga, ki oživlja vse stvari in pred Kristusom Jezusom, ki je pred Poncijem Pilatom pričeval dobro priznanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'da ohraniš to zapoved brez madeža, brezgrajno do pojavitve našega Gospoda Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'ki jo bo ob svojih časih pokazal, ki je blagoslovljen in edini Vladar, Kralj kraljev in Gospod gospodov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'ki ima edini nesmrtnost in prebiva v svetlobi, ki sem mu noben človek ne more približati; katerega noben človek ni videl niti ne more videti; njemu bodi čast in večna oblast. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Naročajte tem, ki so na tem svetu bogati, da naj ne bodo vzvišeni niti naj ne zaupajo v negotova bogastva, temveč v živega Boga, ki nam bogato daje v uživanje vse stvari;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'da delajo dobro, da bodo bogati v dobrih delih, pripravljeni za razdeljevanje, voljni za posredovanje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'in si v shrambi privarčevali dober temelj za čas, ki pride, da se bodo lahko oprijeli večnega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, '§ Oh Timótej, varuj to, kar je zaupano tvojemu varstvu, izogibajoč se oskrunjenih in praznih blebetanj ter tako imenovanih lažnih znanstvenih oporekanj,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, '§ ki so jih nekateri izpovedovali in zašli glede vere. Milost bodi s teboj. Amen. [Prvo Timóteju je bilo napisano iz Laodikeje, ki je glavno mesto Frigije Pacatiane.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pavel, po Božji volji apostol Jezusa Kristusa, glede na obljubo življenja, ki je v Kristusu Jezusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timóteju, mojemu srčno ljubljenemu sinu: ›Milost, usmiljenje in mir od Boga Očeta in Kristusa Jezusa, našega Gospoda.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Zahvaljujem se Bogu, ki mu služim s čisto vestjo od svojih pradedov, da se te brez prenehanja, noč in dan, spominjam v svojih molitvah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'in silno si želim, da te vidim, zavedajoč se tvojih solz, da bom lahko izpolnjen z radostjo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'ko se spominjam nehlinjene vere, ki je v tebi, ki je najprej prebivala v tvoji stari materi Loídi in tvoji materi Evníki; in prepričan sem, da tudi v tebi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Zatorej te spominjam, da razvnameš Božji dar, ki je v tebi po polaganju mojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Kajti Bog nam ni dal duha strahu, temveč moči, ljubezni in zdravega razuma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ti se torej ne sramuj pričevanja o našem Gospodu niti o meni, njegovem jetniku, temveč bodi soudeleženec trpljenj evangelija glede na Božjo moč;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, '§ ki nas je rešil in nas poklical s sveto poklicanostjo, ne glede na naša dela, temveč glede na svoj lastni namen in milost, ki nam je bila dana v Kristusu Jezusu pred začetkom sveta,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'toda sedaj je prikazana s pojavitvijo našega Odrešenika Jezusa Kristusa, ki je odpravil smrt in po evangeliju prinesel življenje in nesmrtnost na svetlobo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Kateremu sem bil jaz določen za pridigarja in apostola in učitelja poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Zaradi tega razloga tudi trpim te stvari. Pa vendar nisem osramočen, ker vem, komu sem veroval in prepričan sem, da je on zmožen obdržati to, kar sem mu izročil, za tisti dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Trdno drži vzorec zdravih besed, ki si jih slišal od mene, v veri in ljubezni, ki je v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, '§ To dobro stvar, ki ti je bila zaupana, varuj s Svetim Duhom, ki prebiva v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'To veš, da so se vsi, ki so v Aziji, obrnili proč od mene; izmed katerih sta Figel in Hermógen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Gospod naj da usmiljenje Onezíforjevi hiši, kajti pogosto me je poživil in ni bil osramočen zaradi mojih verig.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Toda ko je bil v Rimu, me je zelo marljivo iskal in me našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Gospod naj mu zagotovi, da bo na tisti dan lahko našel usmiljenje od Gospoda. In ti zelo dobro veš, v kako mnogih stvareh mi je služil v Efezu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Ti torej, moj sin, bodi močan v milosti, ki je v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Stvari pa, ki si jih med mnogimi pričami slišal od mene, iste izroči zvestim ljudem, ki bodo zmožni tudi druge poučiti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Ti torej prenašaj trdoto kot dober vojak Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Noben človek, ki se bojuje, se ne zapleta z zadevami tega življenja, da lahko ugodi njemu, ki ga je izbral, da bi bil vojak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'In če si človek prav tako prizadeva za zmago, kljub temu ni okronan, razen če si ne prizadeva zakonito.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Poljedelec, ki dela, mora biti prvi udeleženec sadov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Preudari, kar pravim in Gospod naj ti da razumevanje v vseh stvareh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Spominjaj se, da je bil Jezus Kristus, iz Davidovega semena, obujen od mrtvih glede na moj evangelij,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'za katerega prenašam stisko kakor hudodelec, celó do vezi; toda Gospodova beseda ni zvezana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Zato zaradi izvoljenih prenašam vse stvari, da bi lahko tudi oni dosegli rešitev duš, ki je v Kristusu Jezusu z večno slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'To je zvest izrek: ›Kajti če smo z njim umrli, bomo z njim tudi živeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Če trpimo, bomo z njim tudi kraljevali. Če ga zatajimo, nas bo tudi on zatajil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Če ne verujemo, vendar on ostaja zvest; sebe ne more zatajiti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Spominjaj jih o teh stvareh in naročaj jim pred Gospodom, da se ne pričkajo glede besed, kar ne koristi, temveč spodkopava poslušalce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, '§ Prizadevaj si, da se pokažeš potrjenega Bogu, delavca, ki se mu ni treba sramovati, ki pravilno razdeljuje besedo resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Toda izogibaj se oskrunjenih in praznih blebetanj, ker se bodo okrepila k večji brezbožnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'In njihova beseda bo razjedala kakor rak; izmed katerih sta Himénaj in Filét,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'ki sta zašla glede resnice, rekoč, da je vstajenje že minilo; in zrušila vero nekaterih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, '§ Kljub temu Božji temelj trdno stoji in ima ta pečat: »Gospod pozna te, ki so njegovi.« In: »Naj se vsak, kdor imenuje Kristusovo ime, odreče krivičnosti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Toda v veliki hiši niso samo posode iz zlata in iz srebra, temveč tudi iz lesa in iz ila; in nekatere v čast, nekatere pa v nečast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Če se človek torej očisti od le-teh, bo postal posoda v čast, posvečena ter primerna za gospodarjevo uporabo in pripravljena za vsako dobro delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Béži tudi pred mladostnimi poželenji, toda sledi pravičnosti, veri, ljubezni, miru, s tistimi, ki iz čistega srca kličejo h Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Toda izogibaj se nespametnih in primitivnih razprav, ker veš, da povzročajo prepire.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'In Gospodov služabnik se ne sme prepirati, temveč [mora] biti blag do vseh ljudi, zmožen za poučevanje, potrpežljiv,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, '§ da v krotkosti vzgaja te, ki nasprotujejo sebi; če jim bo Bog morda dal kesanje za priznanje resnice;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'in da bodo lahko prišli k sebi, ven iz zanke hudiča, ki jih je ujel v svojo voljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Vedi tudi to, da bodo v poslednjih dneh nastopili nevarni časi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Kajti ljudje bodo samoljubni, lakomni, bahači, ponosni, bogokletniki, neposlušni staršem, nehvaležni, nesveti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'brez naravne prijaznosti, prelamljali bodo premirje, lažni obtoževalci, neobrzdani, kruti, prezirljivci tistih, ki so dobri,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'izdajalci, prekanjeni, vzvišeni, raje bi imeli užitke kakor imeli radi Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'ki imajo podobo pobožnosti, toda zanikajo njeno moč. Od takšnih se odvrni proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Kajti od te vrste so tisti, ki se plazijo v hiše in peljejo v ujetništvo neumne ženske, natovorjene z grehi, speljane s številnimi poželenji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'ki se vedno učè in nikoli niso zmožni priti do spoznanja resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Torej kakor sta se Janes in Jambrés uprla Mojzesu, tako se tudi ti upirajo resnici; ljudje pokvarjenih umov, izprijeni glede vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Vendar ne bodo nič dlje napredovali, kajti njihova neumnost bo očitna vsem ljudem, kakor je bila tudi njuna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Toda ti si popolnoma spoznal moj nauk, način življenja, namen, vero, potrpežljivost, ljubezen, potrpljenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'preganjanja, stiske, ki so prišle k meni v Antiohiji, v Ikóniju, v Listri; kakšna preganjanja sem prestal, toda iz vseh teh me je osvobodil Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Da, in vsi, ki hočejo bogaboječe živeti v Kristusu Jezusu, bodo trpeli preganjanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Toda hudobneži in zapeljivci bodo postajali slabši in slabši, varali bodo in bodo varani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Toda ti nadaljuj pri stvareh, ki si se jih naučil in se o njih prepričal, ker veš, od koga si se jih učil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'in da si od otroštva poznal sveta pisma, ki so te zmožna storiti modrega za rešitev duše po veri, ki je v Kristusa Jezusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Vse pismo je dano po navdihu od Boga in je koristno za nauk, za opomin, za grajanje, za poučevanje v pravičnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'da bi bil Božji mož lahko popoln, temeljito opremljen za vsa dobra dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Zato te rotim pred Bogom in Gospodom Jezusom Kristusom, ki bo sodil žive in mrtve ob njegovi pojavitvi in njegovem kraljestvu:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'oznanjuj besedo, bodi takojšen v sezoni, izven sezone, grajaj, oštevaj, spodbujaj z vso potrpežljivostjo in naukom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Kajti prišel bo čas, ko ne bodo hoteli prenašati zdravega nauka, ampak si bodo po svojih lastnih poželenjih, ker imajo željna ušesa, kopičili učitelje');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'in svoja ušesa bodo odvračali od resnice in zapeljani bodo v bajke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Toda ti pazi v vseh stvareh, pretrpi stiske, opravi delo evangelista, naredi popoln dokaz svoje službe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Kajti sedaj sem pripravljen, da bom žrtvovan in čas mojega odhoda je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Bojeval sem dober boj, zaključil svoj tek, vero ohranil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Odslej je zame prihranjena krona pravičnosti, ki mi jo bo na tisti dan dal Gospod, pravičen sodnik; in ne samo meni, temveč tudi vsem tem, ki ljubijo njegovo pojavitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Uporabi svojo prizadevnost, da v kratkem prideš k meni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'kajti Demá me je zapustil, ker je vzljubil ta sedanji svet in je odpotoval v Tesaloníko; Kreskens v Galatijo, Tit v Dalmacijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Samo Luka je z menoj. Vzemi Marka in ga privedi s seboj, kajti koristen mi je za službo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tihika pa sem poslal v Efez.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Ko prideš, prinesi s seboj ogrinjalo, ki sem ga pustil v Troádi, pri Karpu in knjige in še posebej pergamente.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Kotlar Aleksander mi je storil mnogo hudega. Gospod ga nagradi glede na njegova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Njega se tudi ti pazi, kajti silno se je upiral našim besedam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Ob mojem prvem zagovoru noben človek ni stal z menoj, temveč so me vsi ljudje zapustili. Prosim Boga, da to ne bo prišlo v poštev k njihovi obtožnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Vendar je z menoj stal Gospod in me krepil, da bi lahko po meni postalo oznanjevanje popolnoma znano in da bi vsi pogani lahko slišali; in rešen sem bil iz levjih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'In Gospod me bo osvobodil iz vsakega zlega dela in me ohranil za svoje nebeško kraljestvo. Njemu bodi slava na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdravi Prisko in Ákvila ter Onezíforjevo družino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erást je ostal v Korintu, le Trofima sem bolnega pustil v Miletu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Uporabi svojo prizadevnost, da prideš pred zimo. Pozdravljajo te Evbúl in Pudent in Lin in Klavdija ter vsi bratje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, '§ Gospod Jezus Kristus bodi s tvojim duhom. Milost bodi z vami. Amen. [Druga poslanica Timóteju, prvemu določenemu duhovnemu nadzorniku cerkve Efežanov, je bila napisana iz Rima, ko je bil Pavel drugič priveden pred Nerona.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pavel, Božji služabnik in apostol Jezusa Kristusa, glede na vero Božjih izvoljencev in priznavanje resnice, ki je po bogaboječnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, '§ v upanju večnega življenja, ki ga je Bog, ki ne more lagati, obljubil, preden je svet nastal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'toda ob primernih časih je svojo besedo jasno pokazal prek oznanjevanja, ki mi je bila zaupana glede na zapoved Boga, našega Odrešenika;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, '§ Titu, mojemu lastnemu sinu, po skupni veri: ›Milost, usmiljenje in mir od Boga Očeta in Gospoda Jezusa Kristusa, našega Odrešenika.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Na Kreti sem te pustil zaradi tega razloga, da urediš stvari, ki so pomanjkljive, ter v vsakem mestu določiš starešine, kakor sem ti določil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'če je kdorkoli brez krivde, soprog ene žene, z zvestimi otroki, [ki] niso obtoženi razgrajanja ali neposlušnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Kajti duhovni nadzornik mora biti brez krivde, kakor Božji oskrbnik, ne samovoljen, ne hitro jezen, ne vdan vinu, ne razuzdanec, ne vdan umazani grabežljivosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'temveč ima rad gostoljubnost, ima rad dobre ljudi, trezen, pravičen, svet, zmeren;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'ki trdno drži zvesto besedo, kakor je bil poučen, da bo lahko zmožen z zdravim naukom ugovarjalce tako spodbujati kakor prepričevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Kajti mnogo je neposlušnih in praznih blebetačev ter sleparjev, posebno tistih iz obreze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'katerih usta se morajo zapreti, ki zaradi umazanega dobička spodkopavajo cele družine, ko učijo stvari, ki jih ne bi smeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Eden izmed njih, njihov lastni prerok, je rekel: »Krečani so vedno lažnivci, zle živali, počasni trebuhi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'To pričevanje je resnično. Zatorej jih ostro oštej, da bodo lahko zdravi v veri;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'ne dajajoč pozornosti judovskim bajkam in človeškim zapovedim, ki odvračajo od resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Čistim so vse stvari čiste, toda tem, ki so omadeževani in neverni, ni nič čisto, temveč so omadeževane celó njihove misli in vest.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Izpovedujejo, da poznajo Boga, toda z deli ga zanikajo, ker so gnusni in neposlušni in neuporabni za vsako dobro delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Toda ti govori stvari, ki so primerne zdravemu nauku,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'da bodo starejši možje trezni, dostojanstveni, zmerni, brez graje v veri, v ljubezni, v potrpežljivosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Prav tako starejše ženske, da bodo v obnašanju, kakor se spodobi svetosti, ne lažne obtoževalke, ne vdane mnogemu vinu, učiteljice dobrih stvari;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'da bodo lahko učile mlade ženske biti trezno misleče, imeti rade svoje soproge, imeti rade svoje otroke,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'biti razumne, čiste, varuhinje doma, dobre, poslušne svojim soprogom, da se zoper Božjo besedo ne izreka bogokletja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Prav tako spodbujaj mladeniče, da bodo treznega mišljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'V vseh stvareh se kaži za vzor dobrih del. V nauku prikaži nepokvarjenost, resnost, iskrenost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'zdrav govor, ki ne more biti obsojen; da bo lahko osramočen, kdor je iz nasprotne strani, ker ne bo imel o tebi povedati nobene hudobne stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Spodbujaj služabnike, da so poslušni svojim lastnim gospodarjem in da jim res v vseh stvareh ugodijo brez ugovarjanja;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'brez kraje, temveč prikažejo vso dobro zvestobo; da lahko v vseh stvareh olepšajo nauk Boga, našega Odrešenika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, '§ Kajti Božja milost, ki prinaša rešitev duš, se je prikazala vsem ljudem');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'in nas uči, da naj bi v tem sedanjem svetu zanikali brezbožnost in posvetna poželenja, živeli trezno, pravično in bogaboječe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'in pričakovali to blagoslovljeno upanje in veličastno pojavitev vélikega Boga in našega Odrešenika, Jezusa Kristusa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'ki je samega sebe dal za nas, da bi nas lahko odkupil pred vso krivičnostjo in zase očistil izvoljene ljudi, vnete za dobra dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Te stvari govori in spodbujaj in oštevaj z vso oblastjo. Ne dopusti, da te kdorkoli prezira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, '§ Spomni jih, naj bodo podrejeni kneževinam in oblastem, da se podredijo avtoritetam, da so pripravljeni za vsako dobro delo,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'da o nobenem človeku ne govorijo hudobno, da niso razgrajači, temveč blagi in izkazujejo vso krotkost do vseh ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Kajti tudi mi sami smo bili včasih nespametni, neposlušni, zavedeni in [smo] služili raznim poželenjem ter užitkom in živeli v zlobnosti ter zavisti, osovraženi in [smo] sovražili drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Toda potem se je prikazala prijaznost in človekoljubnost Boga, našega Odrešenika,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'ne z deli pravičnosti, ki smo jih storili, temveč nas je rešil glede na njegovo usmiljenje, s kopeljo prerojenja in obnovitve Svetega Duha;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'ki ga je po Jezusu Kristusu, našem Odrešeniku, obilno izlil na nas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'da naj bi, opravičeni po njegovi milosti, postali dediči glede na upanje večnega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'To je zvesto govorjenje in te stvari hočem, da nenehno izjavljaš, da bodo tisti, ki verujejo v Boga, lahko pazljivi, da skrbijo za dobra dela. Te stvari so dobre in koristne ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Toda izogibaj se neumnih vprašanj in rodovnikov in sporov ter pričkanj glede postave; kajti te so nekoristne in prazne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Človeka, ki je krivoverec, po prvem in drugem svarilu zavrni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'vedoč, da kdor je takšen, je spodkopan in greši in sam od sebe obsojen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Ko bom k tebi poslal Artemája ali Tihika si prizadevaj, da prideš k meni v Nikópolo, kajti sklenil sem, da tam prezimim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenája, izvedenca v postavi in Apola marljivo pospremi na njuno pot, da jima ne bo ničesar manjkalo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'In naj se tudi naši naučijo, da obdržijo dobra dela za potrebne zadeve, da ne bodo brez sadu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, '§ Pozdravljajo te vsi, ki so z menoj. Pozdravi tiste, ki nas imajo radi v veri. Milost bodi z vami vsemi. Amen. [To je bilo napisano Titu, prvemu posvečenemu duhovnemu nadzorniku cerkve Krečanov, iz Nikópole v Makedoniji.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pavel, jetnik Jezusa Kristusa in naš brat Timótej, našemu srčno ljubljenemu Filémonu in sodelavcu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'in naši dragi Apíji in Arhipu, našemu sobojevniku ter cerkvi v tvoji hiši:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, '›Milost vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Vedno, kadar te omenjam v svojih molitvah, se zahvaljujem svojemu Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'ker slišim o tvoji ljubezni in o tvoji veri, ki jo imaš do Gospoda Jezusa in do vseh svetih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'da bi prenos tvoje vere lahko postal učinkovit s priznavanjem vsake dobre stvari, ki je v tebi v Kristusu Jezusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Kajti v tvoji ljubezni imamo veliko veselje in tolažbo, ker so po tebi, brat, osvežene notranjosti svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Zatorej čeprav bi bil v Kristusu lahko zelo drzen, da ti zapovem to, kar je primerno,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'te vendar zaradi ljubezni raje rotim, tak, kakršen sem, Pavel, starec in sedaj tudi jetnik Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Rotim te za svojega sina Onézima, ki sem ga rodil v svojih vezeh,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'ki ti je bil v preteklem času nekoristen, toda sedaj koristi tebi in meni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Njega sem ponovno poslal. Ti ga torej sprejmi, to je, mojo lastno notranjost;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'katerega sem želel obdržati pri sebi, da bi mi namesto tebe lahko služil v vezeh evangelija.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Toda brez tvojega mišljenja ne želim storiti ničesar; da tvoja korist ne bi bila, kakor bi bila iz nuje, temveč prostovoljna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Kajti zato je mogoče za nekaj časa odpotoval, da bi ga sprejel za zmeraj;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'sedaj ne kot služabnika, temveč več kot služabnika, ljubljenega brata, predvsem meni, toda koliko bolj tebi, tako v mesu kakor v Gospodu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Če me imaš torej za družabnika, ga sprejmi kakor mene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Če ti je prizadel krivico ali ti karkoli dolguje, pripiši to na moj račun;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'jaz, Pavel, sem to napisal s svojo lastno roko, sam ti bom to povrnil; čeprav ti ne rečem, kako mi poleg tega dolguješ celó samega sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Da, brat, naj imam veselje s teboj v Gospodu. Osveži mojo notranjost v Gospodu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ker imam zaupanje v tvojo poslušnost, sem ti pisal, vedoč, da boš storil tudi več, kakor pravim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Toda poleg tega mi pripravi tudi stanovanje, kajti zaupam, da vam bom podarjen zaradi vaših molitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdravljajo te Epafrá, moj sojetnik v Kristusu Jezusu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marko, Aristarh, Demá, Luka, moji sodelavci.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, '§ Milost našega Gospoda Jezusa Kristusa bodi z vašim duhom. Amen. [Napisano iz Rima Filemonu, po služabniku Onézimu.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Bog, ki je ob različnih časih in na številne načine v preteklem času govoril očetom po prerokih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'nam je v teh poslednjih dneh spregovoril po svojem Sinu, ki ga je določil [za] dediča vseh stvari, po katerem je tudi naredil svetove;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'ki je sijaj njegove slave in natančna podoba njegove osebe in po besedi svoje moči nosi vse stvari; ko nas je po sebi očistil naših grehov, je sédel na desnico Veličanstva na višavi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'narejen je bil toliko boljši kakor angeli, kolikor je s podedovanjem dosegel odličnejše ime kakor oni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Kajti kateremu izmed angelov je on kadarkoli rekel: »Ti si moj Sin, danes sem te rodil?« In ponovno: »Jaz mu bom Oče in on mi bo Sin?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'In ponovno, ko privede prvorojenca na svet, pravi: »In obožujejo naj ga vsi Božji angeli.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, '§ In o angelih pravi: »Kdor dela svoje angele duhove in svoje služabnike ognjene plamene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Toda sinu pravi: »Tvoj prestol, oh Bog, je na veke vekov; žezlo pravičnosti je žezlo tvojega kraljestva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ljubil si pravičnost in sovražil krivičnost; zatorej te je Bog, celó tvoj Bog, mazilil z oljem veselja bolj kakor tvoje tovariše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'In: »Ti, Gospod, si v začetku položil temelj zemlji in nebesa so delo tvojih rok;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'ona bosta propadla, toda ti ostajaš; in vsa se bosta postarala kakor obleka;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'in zložil ju boš kakor suknjo in se bosta spremenila, toda ti si isti in tvoja leta ne bodo prenehala.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Toda kateremu izmed angelov je ob kateremkoli času rekel: »Sédi na mojo desnico, dokler ne naredim tvojih sovražnikov [za] tvojo pručko?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Mar niso vsi ti službujoči duhovi, poslani, da služijo zaradi tistih, ki bodo dediči rešitve duš?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Zatorej smo dolžni dati iskrenejšo pozornost besedam, ki smo jih slišali, da jim ne bi kadarkoli pustili izmuzniti se.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Kajti če je bila beseda, govorjena po angelih, neomajna in je vsak prestopek ter neposlušnost prejel pravično povračilo nagrade;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'kako bomo ušli mi, če zanemarimo tako veliko rešitev duš, o kateri je najprej začel govoriti Gospod in nam je bila potrjena po tistih, ki smo ga slišali;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, '[ko] njim Bog prav tako prinaša pričevanje, tako z znamenji kakor s čudeži in z različnimi čudežnimi močmi ter darovi Svetega Duha, glede na svojo lastno voljo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Kajti angelom ni položil v podreditev sveta, ki pride, o katerem govorimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Temveč je nekdo na nekem kraju pričeval, rekoč: »Kaj je človek, da misliš nanj? Ali človeški sin, da ga obiskuješ?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '§ Naredil si ga malo nižjega od angelov; kronaš ga s slavo in častjo in postavljaš ga nad dela svojih rok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Vse stvari si podvrgel pod njegova stopala.« Kajti ker je vse podvrgel pod njega, ni pustil ničesar, kar ni položeno pod njega. Vendar sedaj še ne vidimo vseh stvari položenih pod njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Toda vidimo Jezusa, ki je bil postavljen malo nižje od angelov, zaradi smrtnega trpljenja, kronanega s slavo in častjo; da bi po Božji milosti okusil smrt za vsakega človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Kajti spodobilo se je njemu, za katerega so vse stvari in po katerem so vse stvari v prinašanju mnogih sinov v slavo, da naredi poveljnika njihove rešitve duš popolnega skozi trpljenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Kajti vsi so iz enega, tako kdor posvečuje kakor tisti, ki so posvečeni. Zaradi tega razloga ni osramočen, da jih kliče brate,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'rekoč: »Oznanjal bom tvoje ime svojim bratom, na sredi cerkve ti bom prepeval hvalo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'In ponovno: »Svoje trdno upanje bom položil vanj.« In ponovno: »Glej, jaz in otroci, ki mi jih je dal Bog.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ker ste potem kot otroci soudeleženci mesa in krvi, je tudi sam prav tako vzel del od istega, da bi skozi smrt lahko uničil tistega, ki je imel smrtno oblast, to je hudiča');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'in osvobodil tiste, ki so bili zaradi strahu pred smrtjo vse svoje življenje podrejeni sužnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Kajti resnično nase ni prevzel narave angelov, temveč je nase prevzel Abrahamovo seme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, '§ Zatorej se je zanj v vseh stvareh spodobilo, da je bil narejen podoben svojim bratom, da bi bil lahko usmiljen in zvest véliki duhovnik v stvareh, ki se nanašajo na Boga, da opravi pobotanje za grehe ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Kajti ker je on sam trpel in bil skušan, je zmožen okrepiti te, ki so skušani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, '§ Zatorej sveti bratje, soudeleženci nebeške poklicanosti, preudarite Apostola in Vélikega Duhovnika naše veroizpovedi, Kristusa Jezusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'ki je bil zvest tistemu, ki ga je določil, kakor je bil tudi Mojzes zvest v vsej njegovi hiši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Kajti ta človek je bil štet za vrednega večje slave kakor Mojzes, ker kdor je hišo zgradil, ima večjo čast kakor hiša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Kajti vsaka hiša je zgrajena po nekem človeku, toda kdor je zgradil vse stvari, je Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'In Mojzes je bil resnično zvest v vsej njegovi hiši kot služabnik, za pričevanje o teh stvareh, o katerih naj bi se pozneje govorilo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, '§ toda Kristus [pa] kot sin nad svojo lastno hišo; katerega hiša smo mi, če trdno držimo zaupanje in se trdno veselimo upanja do konca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Zatorej (kakor govori Sveti Duh: »Če boste danes zaslišali njegov glas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'ne zakrknite svojih src kakor v izzivanju, na dan preizkušnje v divjini,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'ko so me vaši očetje skušali, me presojali in štirideset let gledali moja dela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Zato sem bil užaloščen s tem rodom in rekel: »Vedno se motijo v svojem srcu in niso spoznali mojih poti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Tako sem prisegel v svojem besu: »Ne bodo vstopili v moj počitek.«)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Pazite bratje, da ne bi bilo v katerem izmed vas hudobno srce nevere v umikanju od živega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Temveč vsakodnevno drug drugega spodbujajte, dokler se imenuje: »Danes,« da ne bi kdorkoli izmed vas zakrknil zaradi zapeljivosti greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Kajti postali smo Kristusovi soudeleženci, če začetek našega zaupanja neomajno držimo do konca;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'dokler je rečeno: »Če boste danes zaslišali njegov glas, ne zakrknite svojih src kakor v izzivanju.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, '§ Kajti nekateri, ko so slišali, so izzivali; čeprav ne vsi, ki so prišli po Mojzesu iz Egipta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Toda nad kom je bil štirideset let užaloščen? Mar ni bil s temi, ki so grešili, katerih trupla so popadala v divjini?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'In katerim je prisegel, da naj ne bi vstopili v njegov počitek, če ne tem, ki niso verovali?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Tako vidimo, da niso mogli vstopiti zaradi nevere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Bojmo se torej, da se ne bi komurkoli izmed vas zdelo, da je zamudil obljubo o vstopu v njegov počitek, ki nam je bila zapuščena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Kajti evangelij je bil oznanjen nam kakor tudi njim. Toda oznanjena beseda tem ni koristila, ker ni bila pridružena veri tistih, ki so jo slišali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Kajti mi, ki smo verovali, vstopamo v počitek, kakor pravi: »Kakor sem prisegel v svojem besu, če bodo vstopili v moj počitek;« čeprav so bila dela končana od ustanovitve sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Kajti na nekem mestu je o sedmem dnevu govoril na ta način: »In Bog je počival sedmi dan od vseh svojih del.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'In na tem mestu ponovno: »Če bodo vstopili v moj počitek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ker torej ostaja to, da morajo nekateri vstopiti vanj in tisti, ki jim je bilo to najprej oznanjeno, zaradi nevere niso vstopili;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'znova omejuje nek dan, rekoč v Davidu: »Danes,« po tako dolgem času; kakor je rečeno: »Če boste danes zaslišali njegov glas, ne zakrknite svojih src.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Kajti če jim je Jezus dal počitek, potem pozneje ne bi govoril o drugem dnevu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Zaradi tega ostaja [šabatni] počitek za Božje ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Kajti kdor je vstopil v njegov počitek, je tudi prenehal s svojimi lastnimi deli, kakor je Bog s svojimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Trudimo se torej, da vstopimo v ta počitek, da ne bi katerikoli človek padel po istem zgledu nevere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Kajti Božja beseda je živa in močna in ostrejša kakor vsak dvorezen meč, ki prodre celó do ločitve duše in duha, sklepov in mozga ter je razpoznavalka misli in namenov srca.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Niti ni nobene stvari, ki se ne razpozna v njegovem pogledu, temveč so vse stvari razgaljene in odprte očem tistega, s katerim imamo opraviti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Ker imamo veličastnega vélikega duhovnika, ki je prešel v nebesa, Jezusa, Božjega sina, torej trdno držimo svojo veroizpoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Kajti nimamo vélikega duhovnika, ki ne more biti ganjen z občutenjem naših slabosti; temveč je bil skušan v vseh ozirih, podobno kakor smo mi, vendar brez greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Pristopimo torej pogumno k prestolu milosti, da bomo lahko dosegli usmiljenje in našli milost za pomoč v času potrebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Kajti vsak véliki duhovnik, vzet izmed ljudi, je odrejen za ljudi v stvareh, ki se nanašajo na Boga, da lahko daruje tako darove kakor žrtve za grehe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'ki ima lahko sočutje za nevedne in za tiste, ki so izven poti; kajti tudi on sam je obdan s šibkostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'In zaradi tega razloga mora kakor za ljudi, tako tudi zase darovati za grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'In noben človek si te časti ne jemlje sam, temveč kdor je poklican od Boga, kakor je bil Aron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tako tudi Kristus ni samega sebe proslavil, da bi postal véliki duhovnik, temveč tisti, ki mu je rekel: »Ti si moj Sin, danes sem te rodil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Kakor pravi tudi na drugem mestu: »Ti si duhovnik na veke po Melkízedekovem redu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Ki je v dneh svojega mesa, ko je z močnim vpitjem in solzami daroval molitve in ponižne prošnje k njemu, ki ga je bil zmožen rešiti pred smrtjo in je bil uslišan, zato ker se je bal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'čeprav je bil Sin, pa se je iz stvari, ki jih je pretrpel, naučil poslušnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'in ker je postal popoln, je postal avtor večne rešitve duš vsem tistim, ki ga ubogajo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'véliki duhovnik, poklican od Boga, po Melkízedekovem redu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'O katerem imamo povedati mnogo besed in bi [jih] težko izrekel, glede na to, da ste leni za poslušanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Kajti v času, ko bi morali biti učitelji, imate potrebo, da vas nekdo ponovno uči, katera so začetna načela Božjih izrekov; in postali ste takšni, ki imajo potrebo po mleku in ne po močni hrani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Kajti vsak, kdor je deležen mleka, je nevešč v besedi pravičnosti, ker je dojenček.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Toda močna hrana pripada tem, ki so polnoletni, torej tistim, ki imajo zaradi razloga uporabe svoja čutila trenirana, da razlikujejo tako dobro kakor zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Zatorej pustimo načela Kristusovega nauka, nadaljujmo k popolnosti; in ne polagajmo ponovno temelja kesanja od mrtvih del in vere v Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'nauka o krščevanjih in o polaganju rok in o vstajenju mrtvih ter o večni sodbi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'In to bomo storili, če Bog dovoli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Kajti nemogoče je za tiste, ki so bili enkrat razsvetljeni in so okusili nebeški dar in so postali soudeleženci Svetega Duha');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'in so okusili dobro Božjo besedo in moči sveta, ki pride,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'če bodo odpadli, da se jih ponovno obnovi v kesanje, ker sami sebi na novo križajo Božjega Sina in ga izpostavljajo javni sramoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Kajti zemlja, ki posrka dež, ki pogosto pada nanjo in obrodi zelišča, primerna za tiste, ki so jo obdelovali, prejema blagoslov od Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Toda tista, ki rodi trnje in osat, je zavrnjena in je blizu prekletstva; katere konec je, da bo požgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Toda ljubljeni, mi smo glede vas prepričani o boljših stvareh in stvareh, ki spremljajo rešitev duš, čeprav tako govorimo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Kajti Bog ni krivičen, da pozabi vaše delo in trud ljubezni, ki ste ga pokazali njegovemu imenu, ker ste služili svetim in še služite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'In želimo, da vsak izmed vas do konca izkazuje isto vnemo k polni gotovosti upanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'da ne boste leni, temveč posnemovalci teh, ki zaradi vere in potrpežljivosti podedujejo obljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Kajti ko je Bog dal Abrahamu obljubo, je prisegel pri samem sebi, ker ni mogel priseči pri nikomer večjem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'rekoč: »Zagotovo, z blagoslavljanjem te bom blagoslovil in z množenjem te bom pomnožil.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, '§ In tako je, potem ko je potrpežljivo vztrajal, dosegel obljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Kajti ljudje resnično prisegajo pri večjem; in prisega za potrditev jim je konec vsega prepira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'V čemer je Bog, voljan dedičem obljube obilneje pokazati nespremenljivost svoje namere, to potrdil s prisego;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'da imamo z dvema nespremenljivima izjavama, v katerih je bilo za Boga nemogoče lagati, lahko močno tolažbo mi, ki smo pobegnili zaradi zatočišča, da se oprimemo upanja, postavljenega pred nas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'katerega upanje imamo kakor sidro duše, tako gotovo kakor neomajno in ki vstopa v to notranjost zagrinjala;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'kamor je za nas vstopil predhodnik, celó Jezus, postavljen [za] vélikega duhovnika na veke po Melkízedekovem redu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Kajti ta Melkízedek, kralj v Salemu, duhovnik najvišjega Boga, ki je srečal Abrahama, ko se je ta vračal iz poboja kraljev in ga blagoslovil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'ki mu je tudi Abraham dal desetino od vsega; najprej pomeni Kralj pravičnosti in nató tudi Kralj Salema, kar je Kralj miru;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'brez očeta, brez matere, brez porekla niti nima začetka dni niti konca življenja, toda narejen podoben Božjemu Sinu trajno ostaja duhovnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Torej preudarite, kako velik je bil ta mož, ki mu je celó očak Abraham dal desetino od plenov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'In resnično imajo tisti, ki so iz Lévijevih sinov, ki prejemajo službo duhovništva, zapoved, naj glede na postavo od ljudi pobirajo desetine, to je, od svojih bratov, čeprav so izšli iz Abrahamovih ledij;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'toda on, katerega poreklo ni šteto od njih, je prejel Abrahamove desetine in blagoslovil tistega, ki je imel obljube.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'In brez vseh ugovarjanj je manjše blagoslovljeno od boljšega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'In tukaj prejemajo desetine ljudje, ki umirajo, toda tam jih prejema on, o katerem je pričevano, da živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'In tako lahko potemtakem rečem: »Tudi Levi, ki prejema desetine, je plačal desetine po Abrahamu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Kajti bil je še v ledjih svojega očeta, ko ga je srečal Melkízedek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Če je bila torej popolnost po Lévijevem duhovništvu (kajti pod njim so ljudje prejeli postavo), kakšna je bila nadaljnja potreba, da bi nastopil drug duhovnik po Melkízedekovem redu in ne bi bil imenovan po Aronovem redu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Kajti zaradi spremembe duhovništva je storjena tudi potreba po spremembi postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Kajti on, o katerem se govorijo te stvari, pripada drugemu rodu, od katerega noben človek ni daroval prisotnost pri oltarju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Kajti očitno je, da naš Gospod izvira iz Juda, iz rodu, o katerem glede duhovništva Mojzes ni ničesar rekel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'In še mnogo bolj očitno je, kajti po Melkízedekovi podobnosti vstaja drug duhovnik,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'ki ni postal po postavi mesene zapovedi, temveč po moči neskončnega življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Kajti on pričuje: »Ti si duhovnik na veke po Melkízedekovem redu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Kajti razveljavitev prejšnje zapovedi je resnična zaradi njene slabosti in nekoristnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Kajti postava ni ničesar storila popolno, toda vpeljava boljšega upanja je; po katerem se bližamo k Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'In še toliko bolj, ker ni bil narejen za duhovnika brez prisege;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(kajti ti duhovniki so postali brez prisege; toda ta s prisego po tistem, ki mu je rekel: »Gospod je prisegel in se ne bo kesal: ›Ti si duhovnik na veke po Melkízedekovem redu‹«).');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'S tem je bil Jezus postavljen za pôroka boljše zaveze.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'In onih je bilo resnično mnogo duhovnikov, ker jim zaradi smrti ni bilo dopuščeno, da ostanejo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'toda ta človek, ker ostaja večno, ima nespremenljivo duhovništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Zatorej jih je tudi zmožen rešiti do zadnjega, da po njem pridejo k Bogu, glede na to, da vedno živi, da posreduje zanje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Kajti takšen véliki duhovnik nam je bil primeren, ki je svet, neškodljiv, neomadeževan, ločen od grešnikov in je postal višji od nebes;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'ki mu ni treba vsak dan, kakor tistim vélikim duhovnikom, darovati žrtvovanje, najprej za svoje lastne grehe in potem za grehe ljudi. Kajti to je storil enkrat, ko je daroval samega sebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Kajti postava dela ljudi [za] vélike duhovnike, ki imajo šibkost; toda beseda prisege, ki je bila, odkar [je] postava, postavlja Sina, ki je posvečen na vékomaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Torej od stvari, ki smo jih govorili, je to povzetek: ›Imamo takšnega vélikega duhovnika, ki je postavljen na desnico prestola Veličanstva v nebesih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'služabnika svetišča in resničnega šotorskega svetišča, ki ga je postavil Gospod in ne človek.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Kajti vsak véliki duhovnik je določen, da daruje darove in žrtve, zato je potrebno, da ima tudi ta človek nekaj, da daruje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Kajti če bi bil na zemlji, ne bi bil duhovnik, glede na to, da so tu duhovniki, ki darujejo daritve glede na postavo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'ki služijo zgledu in senci nebeških stvari, kakor je bil Mojzes opomnjen od Boga, ko je bil na tem, da postavi šotorsko svetišče, kajti: »Glej,« pravi, » da narediš vse stvari glede na zgled, ki ti je bil pokazan na gori.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Toda sedaj je dosegel toliko odličnejšo službo, kolikor je tudi posrednik boljše zaveze, ki je bila osnovana na boljših obljubah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Kajti če bi bila tista prva zaveza brezhibna, potem se ne bi iskalo prostora za drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Kajti ko je pri njih našel krivdo, jim pravi: »Glejte, pridejo dnevi, govori Gospod, ko bom z Izraelovo hišo in z Judovo hišo sklenil novo zavezo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'ne glede na zavezo, ki sem jo sklenil z njihovimi očeti na dan, ko sem jih prijel za roko, da jih izpeljem iz egiptovske dežele; ker niso ostali v moji zavezi in se nisem ozrl nanje,« govori Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '»Kajti to je zaveza, ki jo bom sklenil z Izraelovo hišo po tistih dneh,« govori Gospod, »svoje postave bom položil v njihove misli in jih zapisal v njihova srca, in jaz jim bom Bog in oni mi bodo ljudje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'in ne bodo učili vsak svojega bližnjega in vsak svojega brata, rekoč: ›Spoznajte Gospoda,‹ kajti vsi me bodo poznali, od najmanjšega do največjega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Kajti usmiljen bom do njihovih nepravičnosti in njihovih grehov ter njihovih krivičnosti se ne bom več spominjal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Ker pravi: »Novo zavezo,« je prvo naredil staro. Torej to, kar propada in postaja staro, je pripravljeno, da izgine proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Torej prva zaveza je resnično imela tudi odredbe o bogoslužju in posvetnem svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Kajti postavljeno je bilo šotorsko svetišče; prvo, v katerem je bil svečnik in miza ter hlebi navzočnosti; kar je imenovano Svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Za drugim zagrinjalom pa šotorsko svetišče, ki se imenuje Najsvetejše;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'ki je imelo zlato kadilnico in skrinjo zaveze v celoti prevlečeno z zlatom, v kateri je bila zlata posoda, ki je imela mano in Aronova palica, ki je vzbrstela ter plošči zaveze;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'in nad njo keruba slave, ki zasenčujeta sedež milosti [skrinje zaveze]; o katerem sedaj ne moremo podrobno govoriti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Torej ko so bile te stvari tako odrejene, so duhovniki, opravljajoč službo Bogu, vedno šli v prvo šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Toda v drugo je véliki duhovnik odšel sam, enkrat vsako leto, ne brez krvi, ki jo je daroval zase in za grehe ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Sveti Duh tako naznanja, da pot v najsvetejše še ni bila razodeta, dokler je še stalo prvo šotorsko svetišče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Ta je bil podoba za tedaj pripravljeni čas, v katerem so bili darovani tako darovi kakor žrtve, ki niso mogli storiti popolnega, kar se tiče vesti, tistega, ki je službo opravljal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'To je veljalo samo za jedi in pijače in številna umivanja ter mesene odredbe, naložene nanje do časa preureditve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Toda Kristus, ki je prišel [kot] véliki duhovnik prihodnjih dobrih stvari, z večjim in popolnejšim šotorskim svetiščem, ne narejenim z rokami, to se pravi, ne od te zgradbe;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'niti ne s krvjo koz in telet, temveč je s svojo lastno krvjo enkrat vstopil v sveti prostor in za nas dosegel večno odkupitev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Kajti če kri bikov in kozlov ter pepel telice, škropeč nečiste, posvečuje do očiščenja mesa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'koliko bolj bo Kristusova kri, ki je po večnem Duhu samega sebe brez madeža daroval Bogu, očistila vašo vest pred mrtvimi deli, da služite živemu Bogu?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'In zaradi tega razloga je on posrednik nove zaveze, da bi s pomočjo smrti, za odkupitev od prestopkov, ki so bili pod prvo zavezo, tisti, ki so poklicani, lahko prejeli obljubo večne dediščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Kajti kjer je oporoka, tam mora biti tudi potreba po smrti oporočnika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Kajti oporoka je veljavna potem, ko so ljudje mrtvi; sicer nima nobene moči, vse dokler oporočnik živi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Nakar niti prva zaveza ni bila posvečena brez krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Kajti ko je Mojzes vsem ljudem govoril vsak predpis, glede na postavo, je vzel kri telet in kozlov, z vodo in škrlatno volno ter izop in poškropil tako knjigo kakor vse ljudi,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'rekoč: »To je kri zaveze, ki vam jo je Bog ukazal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Poleg tega je s krvjo poškropil tako šotorsko svetišče kakor vse posode za služenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'In skoraj vse stvari se po postavi očiščuje s krvjo; in brez prelivanja krvi ni odpuščanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Bilo je torej potrebno, da naj bi bili vzori stvari v nebesih očiščeni s temi; toda same nebeške stvari [pa] z boljšimi žrtvami kakor te.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Kajti Kristus ni vstopil v svete prostore, narejene z rokami, ki so slike resničnih; temveč v sama nebesa, da se sedaj za nas pokaže v Božji prisotnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Niti ne, da bi samega sebe pogosto daroval, kakor véliki duhovnik vsako leto s krvjo drugih vstopa v sveti prostor;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'kajti potem bi moral od ustanovitve sveta pogosto trpeti. Toda sedaj se je prikazal enkrat ob koncu sveta, da z žrtvovanjem samega sebe odstrani greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'In kakor je določeno ljudem enkrat umreti, toda po tem sodba;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'tako je bil Kristus enkrat darovan, da nosi grehe mnogih; in tem, ki ga pričakujejo, se bo drugič prikazal brez greha v rešitev duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Kajti postava, ki vsebuje senco dobrih stvari, ki pridejo in ne prave podobe stvari, s temi žrtvami, ki jih leto za letom stalno darujejo, še prišlecev nikoli ne more storiti popolnih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Kajti ali takrat ne bi nehali biti darovani? Zato ker ti oboževalci, enkrat očiščeni, naj ne bi imeli nič več zavedanja o grehih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Toda s temi daritvami je vsako leto storjen ponoven opomin zaradi grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Kajti ni mogoče, da naj bi kri bikov in kozlov odvzemala grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Zato, ko prihaja na svet, pravi: »Žrtvovanja in daritve nočeš, toda telo si mi pripravil;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'v žgalnih daritvah in daritvah za greh nimaš nobenega veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tedaj sem rekel: ›Glej, prihajam (v zvitku knjige je to zapisano o meni), da izpolnim tvojo voljo, oh Bog.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Še več, ko je rekel: »Žrtve in darovanja in žgalnih daritev ter darovanja za greh nočeš niti nimaš veselja v teh,« ki so darovane po postavi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, '§ je potem rekel: »Glej, prihajam, da izpolnim tvojo voljo, oh Bog.« Odpravlja prvo, da lahko vzpostavi drugo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Po tej volji smo z daritvijo telesa Jezusa Kristusa posvečeni enkrat za vselej.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'In vsak duhovnik vsak dan stoji, služi in pogosto daruje iste žrtve, ki nikoli ne morejo odvzeti grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Toda ta človek, potem ko je daroval eno žrtev za grehe na veke, je sédel na Božjo desnico;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'in od tega časa naprej čaka, dokler ne bodo njegovi sovražniki narejeni [za] njegovo pručko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Kajti z eno daritvijo je na veke izpopolnil te, ki so posvečeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'O tem nam je priča tudi Sveti Duh; kajti potem ko nam je prej rekel:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '»To je zaveza, ki jo bom sklenil z njimi po tistih dneh,« govori Gospod, »svoje postave bom položil v njihova srca in v njihove misli jih bom zapisal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'in njihovih grehov ter krivičnosti se ne bom več spominjal.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Torej kjer je odpuščanje le-teh, ni več daritve za greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Ker imamo torej, bratje, hrabrost, da po Jezusovi krvi vstopimo v najsvetejše,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'po novi in živi poti, ki jo je za nas posvetil skozi zagrinjalo, to se pravi svoje meso;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'in ker imamo vélikega duhovnika nad Božjo hišo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'se približajmo z resničnim srcem, v polni gotovosti vere, ker smo naša srca poškropili pred zlo vestjo in naša telesa umili s čisto vodo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Trdno, brez omahovanja, se držimo veroizpovedi naše vere (ker je zvest on, ki je obljubil)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'in preudarimo drug drugega, da spodbujamo k ljubezni in k dobrim delom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Ne zapuščajmo zbiranja nas samih, kakor je navada nekaterih, temveč drug drugega spodbujajmo in [to] toliko bolj, kakor vidite, da se približuje dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Kajti če namerno grešimo, potem ko smo prejeli spoznanje o resnici, za grehe ne ostane nobena žrtev več,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'temveč neizogibno strašno pričakovanje sodbe in ognjene vročine, ki bo požrla nasprotnike.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kdor je preziral Mojzesovo postavo, je na osnovi dveh ali treh prič brez usmiljenja umrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Predvidevajte, koliko hujše kazni bo vreden tisti, ki je pod stopalom pomendral Božjega Sina in je štel kri zaveze, s katero je bil posvečen, za nesveto stvar in [to] storil navzlic Duhu milosti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Kajti poznamo tistega, ki je rekel: »Maščevanje pripada meni, jaz bom poplačal,« govori Gospod. In ponovno: »Gospod bo sodil svoje ljudi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'To je strašna stvar, pasti v roke živega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Toda spomnite se prejšnjih dni, v katerih ste, potem ko ste bili razsvetljeni, pretrpeli velik boj stisk;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'deloma, medtem ko ste bili narejeni [za] predmet zaničevanja, tako z grajami kakor s stiskami, in deloma medtem ko ste postali družabniki teh, ki so bili tega navajeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, '§ Kajti do mene ste imeli sočutje v mojih vezeh in ste radostno sprejeli plenjenje svojih dobrin, vedoč v sebi, da imate v nebesih boljše in trajno imetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne odvrzite torej svoje zaupnosti, ki ima veliko povračilo nagrade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Kajti potrebo imate po potrpežljivosti, da potem ko ste storili Božjo voljo, lahko prejmete obljubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Kajti še malo časa in on, ki prihaja, bo prišel in ne bo okleval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Torej pravični bo živel iz vere. Toda če se kdorkoli umakne, moja duša nad njim ne bo imela veselja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Toda mi nismo od teh, ki se umikajo v pogubo, temveč od teh, ki verujejo v rešitev duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Vera je torej zagotovilo stvarem, v katere upamo, dokaz nevidnih stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Kajti po njej so starešine dosegli dober glas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Po veri razumemo, da so bili svetovi zasnovani po Božji besedi, tako da stvari, ki so vidne, niso bile narejene iz stvari, ki se kažejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Po veri je Abel Bogu daroval odličnejšo žrtev kakor Kajn, s katero je dosegel pričevanje, da je bil pravičen, ker je Bog pričeval o njegovih darovih; in po njih, čeprav mrtev, še vedno govori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Po veri je bil Henoh prestavljen, da ne bi videl smrti; in ni ga bilo najti, ker ga je Bog prestavil, kajti pred njegovo prestavitvijo je imel to pričevanje, da je ugajal Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Toda brez vere mu je nemogoče ugajati, kajti kdor prihaja k Bogu, mora verovati, da on je in da je nagrajevalec teh, ki ga marljivo iščejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, '§ Po veri je Noe, ki je bil posvarjen od Boga, o še nevidenih stvareh, prevzet s strahom, pripravil barko za rešitev svoje hiše, po kateri je obsodil svet in postal dedič pravičnosti, ki je po veri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Po veri je Abraham ubogal, ko je bil poklican, da gre ven, na kraj, ki naj bi ga kasneje prejel v dediščino; in odšel je ven, ne vedoč kam je šel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Po veri se je mudil v obljubljeni deželi kot v tuji deželi in prebival v šotorih z Izakom in Jakobom, z njim sodedičema iste obljube;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'kajti iskal je mesto, ki ima temelje, katerega graditelj in izdelovalec je Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Preko vere je tudi sama Sara prejela moč, da spočne seme in rodila otroka, ko je bila čez starost, ker je tega, ki je obljubil, precenila zvestega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Zatorej jih je izšlo celó iz enega in skoraj mrtvega, tako velika množica kakor zvezd neba in kakor peska, ki je brezštevilen ob morski obali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Vsi ti so umrli v veri in niso prejeli obljub, vendar so jih videli od daleč in bili prepričani o njih in jih sprejeli ter priznali, da so bili tujci in romarji na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Kajti tisti, ki govorijo takšne stvari, odkrito razglašajo, da iščejo domovino.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'In resnično, če bi razmišljali o tej domovini, od koder so izšli, bi mogoče imeli priložnost, da se vrnejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Toda odslej si želijo boljšo domovino, to je, nebeško. Zato Bog ni osramočen, da se imenuje njihov Bog, kajti zanje je pripravil mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Po veri je Abraham, ko je bil preizkušan, daroval Izaka. In on, ki je prejel obljube, je daroval svojega edinorojenega sina,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'o katerem je bilo rečeno: ›Da se bo tvoje seme imenovalo po Izaku,‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'ker je menil, da ga je bil Bog zmožen obuditi celó od mrtvih; od koder ga je po podobi tudi prejel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Po veri je, glede na stvari, ki pridejo, Izak blagoslovil Jakoba in Ezava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Po veri je Jakob, ko je umiral, blagoslovil oba Jožefova sinova, in oboževal oprt na vrh svoje palice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Po veri je Jožef, ko je umiral, naredil omembo odhoda Izraelovih otrok in dal zapoved glede svojih kosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Po veri so Mojzesa, ko je bil rojen, njegovi starši tri mesece skrivali, ker so videli, da je bil čeden otrok, in se niso bali kraljeve zapovedi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Po veri je Mojzes, ko je prišel v leta, odklonil, da bi bil imenovan sin faraonove hčere;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'raje si je izbral, da z Božjimi ljudmi trpi stisko, kakor da nekaj časa uživa zadovoljstva greha;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Kristusovo grajanje je cenil za večja bogastva kakor zaklade v Egiptu, kajti imel je spoštovanje do povračila nagrade.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Po veri je zapustil Egipt in se ni bal kraljevega besa, kajti vztrajal je, kakor [bi] zrl tistega, ki je neviden.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Prek vere je praznoval pasho in škropljenje s krvjo, da se jih ne bi dotaknil tisti, ki je uničil prvorojence.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Po veri so šli skozi Rdeče morje, kakor po kopni zemlji, kar so poskušali storiti Egipčani, [pa] so bili utopljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Po veri so padli dol zidovi Jerihe, potem ko so jo obkrožali sedem dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Po veri pocestnica Rahába, ko je v miru sprejela oglednika, ni umrla s temi, ki niso verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'In kaj naj še rečem? Kajti zmanjkalo bi mi časa, da vam povem o Gideónu in o Baráku in o Samsonu in o Jefteju; tudi o Davidu in Samuelu ter o prerokih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'ki so po veri podjarmljali kraljestva, izvrševali pravičnost, dosegali obljube, mašili gobce levom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'gasili silovitost ognja, pobegnili rezilu meča, iz slabosti postajali močni, v boju postajali hrabri, vojske neznancev obračali v beg.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Ženske so ponovno prejemale svoje mrtve, dvignjene v življenje. Drugi pa so bili mučeni, ker niso sprejeli osvoboditve; da bi lahko dosegli boljše vstajenje;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'in drugi so imeli preizkušnjo krutih zasmehovanj ter bičanj, da, poleg tega vezi in ujetništvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Bili so kamnani, bili so žagani narazen, bili so skušani, bili so umorjeni z mečem. Okoli so tavali v ovčjih in kozjih kožah; bili so v pomanjkanju, užaloščeni, mučeni');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(katerih svet ni bil vreden). Tavali so po puščavah in po gorah in po brlogih in zemeljskih votlinah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'In vsi ti, ki so prek vere dosegli dober glas, niso prejeli obljube,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'kajti Bog je za nas priskrbel neko boljšo stvar, da oni ne bi postali popolni brez nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Zato vidite, ker smo tudi mi obdani naokoli s tako velikim oblakom pričevalcev, odložimo vsako breme in greh, ki nas tako z lahkoto pesti in s potrpežljivostjo tecimo tekmo, ki je postavljena pred nas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'glejmo k Jezusu, avtorju in dopolnitelju naše vere; ki je zaradi radosti, ki je bila postavljena predenj, pretrpel križ in preziral sramoto in je posedèn na desnico Božjega prestola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Kajti razmislite vendar o tistem, ki je prestal takšno nasprotovanje grešnikov proti sebi, da ne bi bili vi utrujeni in oslabeli v svojih umih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Niste se še do krvi uprli v boju zoper greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'In pozabili ste na spodbujanje, ki vam govori kakor otrokom: »Moj sin, ne preziraj Gospodovega karanja niti ne izgubljaj poguma, kadar te ošteva;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'kajti kogar Gospod ljubi, strogo vzgaja, in biča vsakega sina, ki ga sprejema.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Če ste prestali vzgojo, Bog z vami ravna kakor s sinovi; kajti kakšen sin je ta, ki ga oče ne bi strogo vzgajal?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Toda če ste brez vzgoje, česar so vsi soudeleženi, potem ste nezakonski otroci, ne pa sinovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Nadalje smo imeli očete svojega mesa, ki so nas vzgajali in smo jim dali spoštovanje. Mar ne bomo veliko raje v podrejenosti Očetu duhov in živeli?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Kajti oni so nas resnično strogo vzgajali za nekaj dni, po svoji lastni volji; toda on za našo korist, da mi lahko postanemo soudeleženci njegove svetosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Torej nobeno opominjanje zaenkrat ni videti, da bi bilo veselo, temveč bridko. Kljub temu potem obrodi miren sad pravičnosti v teh, ki so z njim izurjeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Zatorej dvignite roke, ki visijo in slabotna kolena;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'in naredite ravne steze za svoja stopala, da se ne bi to, kar šepa, obrnilo proč s poti, temveč naj bo raje ozdravljeno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Prizadevajte si za mir z vsemi ljudmi in svetost, brez katere noben človek ne bo videl Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Marljivo zrite, da ne bi katerikoli človek padel od Božje milosti; da vas ne bi zbegala nobena korenina grenkobe, ki poganja in bi bili z njo mnogi omadeževani;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'da ne bi bilo nobenega prešuštvovalca ali oskrunjene osebe, kakor Ezav, ki je za en košček hrane prodal pravico svojega prvorojenstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Kajti veste, kako je bil potem, ko je želel podedovati blagoslov, zavrnjen; kajti ni našel nobenega prostora za kesanje, čeprav ga je skrbno iskal s solzami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Kajti niste prišli h gori, ki se jo lahko dotakne in ki gori z ognjem in niti k črnosti in ne temi in ne viharju');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'in ne donenju trobente in ne glasu besed; katerega glas so tisti, ki so poslušali, rotili, da jim beseda ne bi bila več izgovorjena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '§ (Kajti niso mogli prenesti tega, kar je bilo ukazano: »In če se žival komaj dotakne gore, naj bo kamnana ali prebodena s puščico.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'In prizor je bil tako strašen, da je Mojzes rekel: »Silno se bojim in tresem.«)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Toda vi ste prišli h gori Sion in k mestu živega Boga, nebeškemu Jeruzalemu in k nepreštevni angelski druščini,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'h glavnemu zboru in cerkvi prvorojenih, ki so zapisani v nebesih in k Bogu, Sodniku vseh in k duhovom pravičnih ljudi, ki so dosegli popolnost');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'in k Jezusu, posredniku nove zaveze in h krvi škropljenja, ki govori boljše stvari kakor ta od Abela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Glejte, da ne zavrnete tistega, ki govori. Kajti če niso ušli tisti, ki so zavrnili tistega, ki je govoril na zemlji, koliko bolj ne bomo ušli mi, če se odvrnemo od tistega, ki govori iz nebes;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'katerega glas je takrat stresel zemljo; toda sedaj je obljubil, rekoč: »Še enkrat stresem, ne samo zemljo, temveč tudi nebo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'In ta beseda: »Še enkrat,« pomeni odstranitev tistih stvari, ki so lahko stresene, kakor od stvari, ki so narejene, da te stvari, ki ne morejo biti stresene, lahko ostanejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Zaradi tega mi, ki prejemamo kraljestvo, ki ne more biti omajano, imejmo milost, s katero lahko sprejemljivo služimo Bogu, s spoštovanjem in bogaboječim strahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Kajti naš Bog je požirajoč ogenj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Naj se bratoljúbje nadaljuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, '§ Ne bodite pozabljivi, da pogostite tujce, kajti s tem so nekateri nevedoč pogostili angele.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Spominjajte se teh, ki so v vezeh kakor zvezani z njimi; in teh, ki prenašajo nadloge, kakor ste tudi vi sami v telesu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Zakon je častitljiv v vsem in postelja neomadeževana, toda vlačugarje in zakonolomce bo sodil Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Naj bo vaše vedênje brez pohlepnosti in bodite zadovoljni s temi stvarmi, kar jih imate; kajti rekel je: »Nikoli te ne bom zapustil niti se te ne bom odrekel.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tako da lahko pogumno rečemo: »Gospod je moj pomočnik in ne bom se bal, kaj mi bo storil človek.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Spominjajte se teh, ki imajo nad vami vladarstvo, ki so vam govorili Božjo besedo; katerih vero posnemajte in upoštevajte konec njihovega vedênja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jezus Kristus, isti včeraj in danes in na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne bodite nošeni naokoli z različnimi in tujimi nauki. Kajti dobra stvar je, da je srce utrjeno z milostjo; ne [pa] z jedmi, ki niso koristile tem, ki so bili zavzeti s tem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Imamo oltar, s katerega nimajo pravice jesti tisti, ki služijo šotorskemu svetišču.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Kajti telesa teh živali, katerih kri prinese véliki duhovnik v svetišče za greh, so zažgana zunaj šotorišča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Zato je tudi Jezus, da je lahko s svojo lastno krvjo ljudi posvetil, trpel zunaj velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Zato pojdimo naprej k njemu zunaj šotorišča in prenašajmo njegovo grajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Kajti tukaj nimamo trajnega mesta, temveč iščemo tega, ki pride.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Po njem torej Bogu nenehno darujmo hvalno žrtev, to je, sad naših ustnic, ki dajejo zahvalo njegovemu imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Toda ne pozabite delati dobro in razdeljevati, kajti s takšnimi žrtvami je Bog zelo zadovoljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Ubogajte te, ki imajo vladarstvo nad vami in se podredite; kajti oni bedijo nad vašimi dušami kakor tisti, ki morajo dati obračun, da bodo to lahko delali z radostjo in ne z žalostjo, kajti to je za vas nekoristno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Molite za nas, kajti zaupamo, [da] imamo dobro vest [in smo] v vseh stvareh voljni iskreno živeti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Toda rotim vas, raje delajte to, da vam bom lahko prej vrnjen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Torej Bog miru, ki je od mrtvih ponovno privedel našega Gospoda Jezusa, ta véliki pastir ovc, naj vas po krvi večne zaveze,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'naredi popolne v vsakem dobrem delu, da izpolnite njegovo voljo, ki povzroča v vas to, kar je prijetno v njegovem pogledu, po Jezusu Kristusu, ki mu bodi slava na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'In rotim vas, bratje, dopustite besedo opominjanja, kajti pismo sem vam napisal z nekaj besedami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Védite, da je naš brat Timótej izpuščen na prostost; s katerim, če pride v kratkem, vas bom videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdravite vse tiste, ki vladajo nad vami in vse svete. Pozdravljajo vas tisti iz Italije.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Milost bodi z vami vsemi. Amen. [Napisano Hebrejcem iz Italije po Timóteju.]');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakob, služabnik Boga in Gospoda Jezusa Kristusa, dvanajsterim rodovom, ki so razkropljeni naokoli, pozdrav.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Moji bratje, kadar zapadate v številne skušnjave, štejte to [za] veliko veselje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'ker veste to, da preizkušenost vaše vere ustvarja potrpežljivost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Toda naj ima potrpežljivost svoje popolno delo, da boste lahko popolni in celotni, [da vam] ničesar ne manjka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Če [pa] komu izmed vas manjka modrosti, naj prosi od Boga, ki velikodušno daje vsem ljudem in ne očita; in dana mu bo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Toda prosi naj v veri niti malo omahujoč. Kajti kdor omahuje, je podoben morskemu valu, [ki ga] žene veter in ga premetava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Kajti tak človek naj ne misli, da bo karkoli prejel od Gospoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Človek dvojnih misli je nestanoviten na vseh svojih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Naj se brat nizkega položaja veseli v tem, da je povišan;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'toda bogat v tem, da je ponižan, ker bo minil kakor cvet na travi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Kajti takoj, ko sonce vzide z žgočo vročino, to izsuši travo in njen cvet pade in lepota njenega videza propade; tako bo tudi bogataš zbledel na svojih poteh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Blagoslovljen je človek, ki preizkušnjo vzdrži; kajti ko je preizkušen, bo prejel krono življenja, ki jo je Gospod obljubil tistim, ki ga ljubijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Naj noben človek, ko je skušan, ne reče: »Skušan sem od Boga,« kajti Bog ne more biti skušan z zlom niti sam nikogar ne skuša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Toda vsak je skušan, ko je odtegnjen s svojimi lastnimi poželenji in premamljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Ko je potem poželenje spočeto, rojeva greh. Greh pa, ko je dovršen, rojeva smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne motite se, moji ljubljeni bratje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Vsak dober dar in vsako popolno darilo je od zgoraj in prihaja dol od Očeta svetil, s katerim ni nestanovitnosti niti sence obračanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Po svoji lastni volji nas je zaplodil z besedo resnice, da naj bi bili mi nekako prvenci njegovih ustvarjenih bitij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Zatorej, moji ljubljeni bratje, naj bo vsak človek hiter za poslušanje, počasen za govorjenje, počasen za bes;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'kajti človekov bes ne uresničuje Božje pravičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Zatorej dajte proč vso umazanost in odvečno porednost ter s krotkostjo sprejmite vcepljeno besedo, ki je zmožna rešiti vaše duše.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Toda bodite uresničevalci besede in ne le poslušalci, ki sami sebe varajo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Kajti če je kdorkoli poslušalec besede, ne pa uresničevalec, je podoben človeku, ki svoj naraven obraz ogleduje v zrcalu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'kajti gleda sebe in gre svojo pot ter nemudoma pozabi, kakšne vrste človek je bil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Toda kdorkoli gleda v popolno postavo svobode in ostaja v njej, ni pozabljiv poslušalec, temveč izvrševalec dela, bo ta človek blagoslovljen v svojem dejanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Če je katerikoli človek med vami videti religiozen, pa ne brzda svojega jezika, temveč zavaja svoje lastno srce, je bogoslužje tega človeka prazno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Čisto in neomadeževano bogoslužje pred Bogom in Očetom je to: »Obiskovati osirotele in vdove v njihovi stiski ter se ohraniti neomadeževanega od sveta.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Moji bratje, vere našega Gospoda Jezusa Kristusa, Gospoda slave, ne imejte z oziranjem na osebe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Kajti če pride v vaš zbor mož z zlatim prstanom in čedno obleko, pride pa tudi revež v grdem oblačilu;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'in se ozirate k tistemu, ki nosi elegantno oblačilo ter mu rečete: »Sédi tukaj na dobro mesto;« revnemu pa rečete: »Stoj tukaj ali sédi tukaj pod mojo pručko.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Mar niste potem v sebi pristranski in ste postali sodniki s hudobnimi mislimi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Poslušajte, moji ljubljeni bratje: »Ali ni Bog izbral revnih tega sveta, bogatih v veri in dedičev kraljestva, ki ga je obljubil tem, ki ga ljubijo?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Toda vi ste prezirali revnega. Ali vas ne zatirajo bogataši in vas vlečejo pred sodne stole?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ali ne preklinjajo oni tega vrednega imena, po katerem ste imenovani?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Če izpolnite kraljevo postavo glede pisma: »Svojega bližnjega boš ljubil kakor samega sebe,« delate pravilno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Toda če se ozirate na osebe, storite greh in ste po postavi pograjani kot prestopniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Kajti kdorkoli se bo držal celotne postave in se vendar prekrši v eni točki, je kriv vseh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Kajti kdor je rekel: »Ne počni zakonolomstva,« je rekel tudi: »Ne ubijaj.« Torej če ne počneš zakonolomstva, vendar če ubijaš, si postal prestopnik postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tako govorite in tako delajte kakor tisti, ki bodo sojeni po postavi svobode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Kajti tisti, ki ni pokazal nobenega usmiljenja, bo sodbo prejel brez usmiljenja; in usmiljenje se razveseljuje zoper sodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Kaj to koristi, moji bratje, četudi človek reče, [da] ima vero, nima pa del? Mar ga lahko vera reši?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Če sta brat ali sestra naga in brez dnevne hrane,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'in jima kdo izmed vas reče: »Odidita v miru, bodita ogreta in nasičena;« čeprav jima ne daste teh stvari, ki so potrebne telesu; kaj to koristi?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Prav tako vera, če ta nima del, je sama zase mrtva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Da, človek lahko reče: »Ti imaš vero, jaz pa imam dela. Pokaži mi svojo vero brez svojih del in pokazal ti bom svojo vero s svojimi deli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ti veruješ, da obstaja en Bog; pravilno ravnaš. Tudi hudiči verujejo in trepetajo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Toda ali hočeš spoznati, oh prazni človek, da je vera brez del mrtva?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Mar ni bil naš oče Abraham opravičen z deli, ko je na oltarju daroval svojega sina Izaka?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vidiš, kako je vera sodelovala z njegovimi deli in je vera z deli postala popolna?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'In izpolnjeno je bilo pismo, ki pravi: ›Abraham je veroval Bogu in to mu je bilo pripisano v pravičnost;‹ in imenovan je bil: ›Prijatelj Boga.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vidite torej kako, da je človek opravičen z deli in ne samo iz vere.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Ali ni bila prav tako tudi pocestnica Rahába opravičena z deli, ko je sprejela poslanca in ju odposlala [po] drugi poti?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Kajti kakor je telo brez duha mrtvo, tako je tudi vera brez del mrtva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Moji bratje, ne bodite mnogi učitelji, ker veste, da bomo prejeli večjo obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Kajti v mnogih stvareh vsi grešimo. Če katerikoli človek ne greši z besedo, je isti popoln mož in tudi zmožen obrzdati celotno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Glejte, konjem v usta dajemo žvale, da nas lahko ubogajo in obračamo njihovo celotno telo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, '§ Glejte tudi ladje, katere, čeprav so tako velike in jih ženejo kruti vetrovi, se vendar obračajo z zelo majhnim krmilom, kamorkoli krmar hoče.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Prav tako je jezik majhen ud, pa se baha [z] velikimi stvarmi. Glejte, kako veliko stvar prižge majhen ogenj!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'In jezik je ogenj, svet krivičnosti. Tako je jezik med našimi udi, da omadežuje celotno telo in razvnema zakon narave; in ta je vžgan iz pekla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Kajti vsaka vrsta, od živali in od ptic in od kač in od stvari v morju, je ukrotljiva in je bila ukročena od človeštva,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'toda jezika ne more ukrotiti noben človek; je neukrotljivo zlo, polno smrtonosnega strupa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Z njim blagoslavljamo Boga, celó Očeta; in z njim preklinjamo ljudi, ki so ustvarjeni po Božji podobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Iz istih ust izvirata blagoslavljanje in preklinjanje. Moji bratje, te stvari ne smejo biti takšne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Mar daje studenec na istem mestu sladko in grenko vodo?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Ali lahko figovo drevo, moji bratje, rodi olive? Ali trta fige? Tako noben studenec ne more dajati obeh, slane in sladke vode.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kdo je med vami moder človek in opremljen s spoznanjem? Naj s krotkostjo modrosti kaže dobro vedênje svojih del.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Toda če imate v svojih srcih grenko zavist in prepir, se ne ponašajte in ne lažite zoper resnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ta modrost se ne spušča od zgoraj, temveč je zemeljska, čutna, vražja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Kajti kjer sta zavist in prepir, tam je zmešnjava in vsako hudobno delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Toda modrost, ki je od zgoraj, je najprej čista, potem mirna, nežna in lahka za ravnanje, polna usmiljenja in dobrih sadov, brez pristranskosti in brez hinavščine.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'In sad pravičnosti sejejo v miru tisti, ki delajo mir.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Od kod prihajajo med vami vojne in boji? Ali ne pridejo od tod, celó iz vaših poželenj, ki se vojskujejo v vaših udih?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vi hlepite, pa nimate. Ubijate in želite imeti, pa ne morete doseči. Bojujete se in vojskujete, vendar nimate, ker ne prosite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Prosite, pa ne prejmete, ker prosite neprimerno, da bi to porabili za svoja poželenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Vi zakonolomci in zakonolomke ali ne veste, da je prijateljstvo s svetom sovraštvo do Boga? Kdorkoli bo torej prijatelj sveta, postane Božji sovražnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, '§ Ali mislite, da pismo zaman pravi: »Duh, ki prebiva v nas, hrepeni do zavisti?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Toda on daje več milosti. Zatorej pravi: »Bog se ponosnim upira, toda ponižnim daje milost.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Podvrzite se torej Bogu. Uprite se hudiču in bo od vas pobegnil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Približajte se Bogu in se vam bo približal. Očistite si svoje roke, vi grešniki; in očistite svoja srca, vi, [ki ste] dvojnih misli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Bodite užaloščeni in žalujte ter jokajte. Naj bo vaš smeh obrnjen v žalovanje in vaša radost v potrtost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Ponižajte se v Gospodovih očeh in vas bo povišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Bratje, drug o drugem ne govorite hudobno. Kdor o svojem bratu govori hudobno in svojega brata sodi, govori hudobno o postavi in sodi postavo. Toda če sodiš postavo, nisi uresničevalec postave, temveč sodnik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, '§ En zakonodajalec je, ki je zmožen rešiti in uničiti. Kdo si ti, da sodiš drugega?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Pojdite torej, vi, ki pravite: »Danes ali jutri bomo šli v to mesto in tam ostali eno leto in kupovali in prodajali ter zaslužili dobiček;«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'medtem ko ne veste, kaj bo jutri. Kajti kaj je vaše življenje? Je celó meglica, ki se za kratek čas prikaže in potem izgine proč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Kajti takó morate reči: »Če Gospod hoče, bomo živeli in delali to ali ono.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Toda sedaj se razveseljujete v svojih bahanjih. Vsako takšno razveseljevanje je zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Torej tistemu, ki zna delati dobro, pa tega ne dela, mu je to [v] greh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Pojdite torej, vi bogataši, jokajte in tulite zaradi svojih bed, ki bodo prišle nad vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vaša bogastva so pokvarjena in vaše obleke so požrte od moljev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Vaše zlato in srebro je postalo zarjavelo; in njuna rja bo priča zoper vas in bo razjedla vaše meso, kakor bi bila ogenj. Nakopičili ste skupaj zaklad za poslednje dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Glejte, plačilo delavcev, ki so poželi vaša polja, ki ste si jih pridržali s sleparstvom, kriči. In kriki teh, ki so poželi, so vstopili v ušesa Gospoda nad vojskami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Na zemlji ste živeli v užitku in bili polteni; svoja srca ste redili kakor za dan zakola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Obsodili in ubili ste pravičnega; in se vam ne upira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Bodite torej potrpežljivi, bratje, do Gospodovega prihoda. Glejte, poljedelec pričakuje dragocen sad zemlje in ima za to veliko potrpežljivost, dokler ne prejme zgodnjega in poznega dežja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Bodite tudi vi potrpežljivi. Utrdite svoja srca, kajti Gospodov prihod se približuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne godrnjajte drug proti drugemu, bratje, da ne bi bili obsojeni. Glejte, sodnik stoji pred vrati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Moji bratje, za zgled prenašanja stiske in potrpežljivosti vzemite preroke, ki so govorili v Gospodovem imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Glejte, mi štejemo za srečne te, ki vztrajajo. Slišali ste o Jobovi potrpežljivosti in videli Gospodov konec; da je Gospod zelo sočuten in nežno usmiljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Toda nad vsemi stvarmi, moji bratje, ne prisegajte, niti pri nebu, niti pri zemlji, niti s kako drugo prisego. Temveč vaš »da« naj bo »da« in vaš »ne« [naj bo] »ne«, da ne zapadete v obsodbo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, '§ Ali je kdo med vami v stiski? Naj moli. Ali je kdo vesel? Naj prepeva psalme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Je kdo med vami bolan? Naj pokliče starešine cerkve in naj nad njim molijo ter ga v Gospodovem imenu mazilijo z oljem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'In molitev vere bo rešila bolnika in Gospod ga bo vzdignil; in če je storil grehe, mu bodo odpuščeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, '§ Drug drugemu priznavajte svoje napake in molíte drug za drugega, da boste lahko ozdravljeni. Veliko koristi energična, goreča molitev pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elija je bil človek, podvržen podobnim strastem, kakor smo mi in je iskreno molil, da ne bi deževalo. In na zemljo ni deževalo v obdobju treh let in šestih mesecev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'In ponovno je molil in nebo je dalo dež in zemlja je obrodila svoj sad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Bratje, če kdo izmed vas zaide od resnice in ga nekdo spreobrne,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'naj ta ve, da kdor je grešnika spreobrnil od zmote njegove poti, bo rešil dušo pred smrtjo in zakril množico grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Peter, apostol Jezusa Kristusa, tujcem, razpršenim vsepovsod po Pontu, Galatiji, Kapadokiji, Aziji in Bitiniji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'izvoljenim glede na vnaprejšnje védenje Boga Očeta, s posvečenjem Duha, k poslušnosti in škropljenju s krvjo Jezusa Kristusa: ›Milost vam in mir naj se pomnožita.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Blagoslovljen bodi Bog in Oče našega Gospoda Jezusa Kristusa, ki nas je glede na svoje obilno usmiljenje, z vstajenjem Jezusa Kristusa od mrtvih, ponovno rodil v živo upanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'k dediščini, netrohneči in neomadeževani in ki ne propada, prihranjeni v nebesih za vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'ki ste varovani z Božjo močjo po veri v rešitev duš, ki je pripravljena, da se razodene v poslednjem času.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'V kateri se silno veselite, čeprav ste sedaj za nekaj časa, če je potrebno, v potrtosti po mnogovrstnih preizkušnjah,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'da bo preizkušenost vaše vere, ki je veliko bolj dragocena kakor zlato, ki izgineva, čeprav je to preizkušeno z ognjem, lahko najdena v hvalo, čast in slavo, ob pojavitvi Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, '§ Katerega niste videli, vi ljubite; v katerega, čeprav ga sedaj ne vidite, vendar verujete [in] se veselite z nepopisno radostjo in polni slave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'ko prejemate konec svoje vere, celó rešitev svojih duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'O tej rešitvi duš so poizvedovali in marljivo preiskovali preroki, ki so prerokovali o milosti, ki naj bi prišla k vam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'In preiskovali so kaj ali na kakšno vrsto časa je kazal Kristusov Duh, ki je bil v njih, ko je vnaprej pričeval o Kristusovem trpljenju in slavi, ki naj bi sledila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Katerim je bilo razodeto, da ne njim, temveč so besede služile nam, sedaj pa so sporočene vam, po teh, ki so vam s Svetim Duhom, poslanim iz nebes, oznanili evangelij; v katere stvari želijo pogledati angeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Zatorej opašite ledja svojega uma, bodite trezni in do konca upajte na milost, ki bo privedena k vam ob razodetju Jezusa Kristusa;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'kot poslušni otroci se ne prilagajajte glede na prejšnja poželenja, v svoji nevednosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'temveč kakor je svet on, ki vas je poklical, tako bodite sveti vi, v vseh vrstah vedênja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'ker je pisano: »Bodite sveti, kajti jaz sem svet.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'In če kličete k Očetu, ki sodi brez oziranja na osebe, glede na delo vsakega človeka, preživite čas svojega začasnega bivanja tukaj v strahu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'ker veste, da iz vašega praznega vedênja, prejetega po izročilu od vaših očetov, niste bili odkupljeni s trohljivimi stvarmi, kot sta srebro in zlato,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'temveč z dragoceno Kristusovo krvjo, kakor od jagnjeta brez pomanjkljivosti in brez madeža;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'ki je bil resnično vnaprej določen, pred ustanovitvijo sveta, toda v teh poslednjih časih je bil razodet za vas,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'ki po njem verujete v Boga, ki ga je obudil od mrtvih in mu izročil slavo; da bo vaša vera in upanje lahko v Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ker ste svoje duše, v pokorščini resnici skozi Duha, očistili v nehlinjeno bratoljúbje, glejte, da goreče, s čistim srcem, ljubíte drug drugega,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'ker ste ponovno rojeni, ne iz trohljivega semena, temveč iz netrohljivega, po Božji besedi, ki živi in ostaja na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Kajti vse meso je kot trava in vsa človeška slava kakor cvet trave. Trava ovene in njen cvet pade proč,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'toda Gospodova beseda vztraja za vedno. In to je beseda, ki vam je oznanjena po evangeliju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Zatorej dajte na stran vso zlobnost in vso zvijačo in hinavščine in nevoščljivosti in vsa hudobna govorjenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, '§ kot novorojeni otročiči si želite pristnega mleka besede, da boste s tem lahko rastli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'če je tako, ste okusili, da je Gospod milostljiv.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'H kateremu prihajajte kakor k živemu kamnu, zares zavrnjenemu od ljudi, toda od Boga izbranemu in dragocenemu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, '§ Tudi vi ste kot živi kamni, vgrajeni [v] duhovno hišo, sveto duhovništvo, da darujete duhovne žrtve, po Jezusu Kristusu sprejemljive Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Zatorej je tudi vsebovano v pismu: »Glej, na Sionu položim glavni vogalni kamen, izvoljen, dragocen, in kdor veruje vanj, ne bo zbegan.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Vam torej, ki verujete, je dragocen; toda tem, ki so neposlušni, je kamen, ki so ga graditelji zavrnili, ta isti postal glava vogalu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'in kamen spotike in skala pohujšanja, celó tem, ki se spotikajo ob besedo, ki so neposlušni; za kar so bili tudi določeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Toda vi ste izbran rod, kraljevo duhovništvo, svet narod, posebni ljudje; da naj bi naznanjali hvale tistega, ki vas je iz teme poklical v svojo čudovito svetlobo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'ki v preteklem času niste bili ljudstvo, toda sedaj ste Božje ljudstvo; ki niste dosegli usmiljenja, toda sedaj ste usmiljenje dosegli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Srčno ljubljeni, rotim vas kot tujce in romarje; vzdržite se pred mesenimi poželenji, ki se bojujejo zoper dušo;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'imejte svoje vedênje iskreno med pogani, da bodo, medtem ko govorijo proti vam kot hudodelcem, lahko po vaših dobrih delih, ki jih bodo gledali, na dan obiskanja proslavili Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, '§ Zaradi Gospoda se podredite vsaki človeški odredbi; bodisi je to kralj, kot najvišji,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'bodisi voditeljem, kot tistim, ki so po njem poslani za kaznovanje hudodelcev in za hvalo teh, ki delajo dobro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Kajti taka je Božja volja, da boste s počenjanjem dobrega lahko utišali nevednost nespametnih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Kot svobodni, pa svoje svobode ne uporabljajte za ogrinjalo zlonamernosti, temveč kakor Božji služabniki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Spoštujte vse ljudi. Ljubite bratstvo. Bojte se Boga. Spoštujte kralja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Služabniki, z vsem strahom bodite podrejeni svojim gospodarjem; ne samo dobrim in blagim, temveč tudi osornim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Kajti vredno hvale je to, če človek, ki krivično trpi zaradi zavedanja pred Bogom, prenaša žalost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Kajti kakšna čast je to, če boste, ko ste oklofutani zaradi svojih napak, to potrpežljivo prestali? Toda ko delate dobro in zaradi tega trpite, če to potrpežljivo prestanete, je to sprejemljivo pri Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Kajti celó k temu ste bili poklicani, ker je tudi Kristus trpel za nas in nam pustil zgled, da naj bi vi sledili njegovim stopinjam;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'ki ni storil greha niti v njegovih ustih ni bilo najti zvijače;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'ki ni ponovno zasramoval, ko je bil zasramovan; ko je trpel, ni grozil; temveč je sebe izročil njemu, ki sodi pravično;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'ki je sam, v svojem lastnem telesu, naše grehe ponesel na les, da naj bi mi, mrtvi grehom, lahko živeli v pravičnosti; s čigar udarci z bičem ste bili ozdravljeni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Kajti bili ste kakor ovce, ki so zašle, toda sedaj ste vrnjeni k Pastirju in duhovnemu Nadzorniku svojih duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Prav tako bodite, ve žene, podložne svojim lastnim soprogom; da bi bili lahko, če kateri ne ubogajo besede, prav tako pridobljeni brez besede, z vedênjem žena,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'medtem ko gledajo vaše čisto vedênje, združeno s strahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Katerih okrasitev naj ne bo ta zunanja okrasitev, s prepletanjem las in z nošenjem zlata ali z oblačenjem oblek,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'temveč naj bo to skriti človek srca, v tem kar ni trohljivo, celó ornament krotkega in tihega duha, kar ima v očeh Boga veliko ceno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Kajti na ta način so v starih časih tudi svete ženske, ki so zaupale v Boga, sebe okrasile s tem, da so bile podložne svojim lastnim soprogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Celó kakor je Sara ubogala Abrahama in ga klicala gospodar; katere hčere ste ve, dokler delate dobro in niste prestrašene s kakršnimkoli preplahom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Prav tako vi soprogi, prebivajte z njimi glede na spoznanje in dajajte čast ženi kot šibkejši posodi in kakor ste skupaj sodediči milosti življenja, da vaše molitve ne bodo ovirane.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Končno, bodite vsi enega mišljenja s tem, da imate sočutje drug do drugega, imejte se radi kot bratje, bodite sočutni, bodite prijazni,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'ne vračajte zla za zlo ali posmehovanja za posmehovanje, temveč nasprotno, blagoslavljajte; ker veste, da ste bili k temu poklicani, da naj bi podedovali blagoslov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Kajti kdor hoče ljubiti življenje in videti dobre dni, naj zadržuje svoj jezik od zla in svoje ustnice, da ne bodo govorile nobene zvijače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Naj se ogiblje zla in dela dobro; naj išče mir in mu sledi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Kajti Gospodove oči so nad pravičnimi in njegova ušesa so odprta k njihovim molitvam, toda Gospodov obraz je zoper te, ki počnejo zlo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'In kdo je ta, ki vam bo škodil, če boste privrženci tega, kar je dobro?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Toda če pa trpite zaradi pravičnosti, ste srečni; in ne bojte se njihovih strahot niti ne bodite zaskrbljeni;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, '§ temveč v svojih srcih Gospoda Boga posvetite. In bodite vedno pripravljeni, s krotkostjo in strahom, dati odgovor vsakemu človeku, ki vas sprašuje za razlog upanja, ki je v vas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 's tem, da imate dobro vest; da bodo, glede na to, da o vas govorijo hudobno, kakor o hudodelcih, lahko osramočeni tisti, ki zmotno obtožujejo vaše dobro vedênje v Kristusu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Kajti bolje je, če je taka Božja volja, da trpite zaradi početja dobrega, kakor zaradi početja zlega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Kajti tudi Kristus je enkrat trpel za grehe, pravični za nepravične, da bi nas lahko privedel k Bogu, je bil v mesu usmrčen, toda oživljen po Duhu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'po katerem je tudi šel in oznanjal duhovom v ječi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'ki so bili nekdaj neposlušni, ko je Božja potrpežljivost nekoč, v Noetovih dneh, čakala, medtem ko se je pripravljala barka, v kateri je bilo malo, to je osem duš, rešeno po vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Podobna podoba kakor celó krst nas tudi sedaj rešuje (in ne odstranjuje umazanije mesa, temveč jamči o dobri vesti pred Bogom), z vstajenjem Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'ki je odšel v nebesa in je na Božji desnici; podrejeni so mu bili angeli in oblasti ter moči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Ker je torej Kristus za nas trpel v mesu, se podobno tudi vi oborožite z istim mišljenjem, kajti kdor je trpel v mesu, je prenehal z grehom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'da preostanek svojega časa v mesu ne bi več živel za človeška poželenja, temveč za Božjo voljo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Kajti pretekli čas našega življenja nam lahko zadošča, da smo izvrševali voljo poganov, ko smo hodili v pohotnosti, poželenjih, vinskih izgredih, veseljačenjih, gostijah in gnusnih malikovanjih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'pri čemer imajo za čudno, da ne tečete z njimi k istemu izgredu upornosti, govoreč zlo o vas;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'ki bodo dali obračun tistemu, ki je pripravljen, da sodi žive in mrtve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, '§ Zaradi tega razloga je bil evangelij oznanjen tudi tem, ki so mrtvi, da bi bili lahko sojeni po človeško, v mesu, toda glede Boga bi živeli v duhu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Toda konec vseh stvari je blizu; bodite torej trezni in čujte v molitvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Bolj pa kakor karkoli drugega imejte med seboj gorečo ljubezen, kajti ljubezen pokrije množico grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Brez godrnjanja uporabljajte gostoljubnost drug do drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Kakor je vsak prejel dar, točno tako enako služite drug drugemu kot dobri oskrbniki mnogovrstne Božje milosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Če katerikoli človek govori, naj govori kakor Božje izreke; če katerikoli človek služi, naj to opravlja kakor iz zmožnosti, ki jo daje Bog; da bo v vseh stvareh Bog lahko proslavljen po Jezusu Kristusu, ki mu bodi hvala in gospostvo na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Ljubljeni, ne mislite čudno glede ognjene preizkušnje, ki je, da vas preizkusi, kakor da se vam je zgodila neka čudna stvar,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'temveč se veselite, kolikor ste soudeleženci Kristusovih trpljenj; da ko se bo razodela njegova slava, boste lahko tudi veseli s silno radostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, '§ Če ste grajani zaradi Kristusovega imena, ste srečni; kajti na vas počiva duh slave in Boga; na njihovi strani je obrekovanje, toda na vaši strani je on proslavljen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Toda nihče izmed vas naj ne trpi kot morilec ali kot tat ali kot hudodelec ali kot vtikljivec v zadeve drugih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Vendar če katerikoli človek trpi kot kristjan, naj ne bo osramočen, temveč naj zaradi tega proslavlja Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Kajti prihaja čas, da se mora sodba začeti v Božji hiši; in če se ta najprej začne pri nas, kakšen bo konec teh, ki ne ubogajo Božjega evangelija?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'In če bo pravični komaj rešen, kje se bo pokazal brezbožnež in grešnik?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Zatorej naj tisti, ki trpijo glede na Božjo voljo, čuvanje svojih duš izročijo njemu kot zvestemu Stvarniku, s početjem dobrega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starešine, ki so med vami, spodbujam jaz, ki sem tudi starešina in priča Kristusovih trpljenj in tudi soudeleženec slave, ki se bo razodela;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'pasite Božji trop, ki je med vami in prevzemite nadzor nad njim, ne s prisilo, temveč voljno; ne zaradi umazane grabežljivosti, temveč s primernim namenom;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'niti kakor bi bili gospodarji nad Božjo dediščino, temveč zgledi tropu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'In ko se bo pojavil glavni Pastir, boste prejeli krono slave, ki ne propada.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Podobno se vi mlajši podredite starejšim. Da, vsi izmed vas bodite podrejeni drug drugemu in bodite oblečeni s ponižnostjo; kajti Bog se ponosnim upira, ponižnim pa daje milost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Ponižajte se torej pod mogočno Božjo roko, da vas bo lahko ob primernem času povišal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Vso svojo skrb vrzite nanj, kajti on skrbi za vas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Bodite trezni, bodite oprezni, ker vaš nasprotnik hudič hodi naokrog kakor rjoveč lev in išče, koga bi lahko požrl;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'kateremu se uprite neomajni v veri, vedoč, da so ista trpljenja dovršena v vaših bratih, ki so po svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Toda Bog vse milosti, ki nas je poklical v svojo večno slavo po Kristusu Jezusu, potem ko ste nekaj časa trpeli, vas stori popolne, utrjene, okrepljene, vas ustali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, '§ Njemu bodi slava in gospostvo na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Po Silvánu, zvestemu bratu, sem vam, kakor mislim, napisal na kratko in spodbujal ter pričeval, da je to resnična Božja milost, v kateri stojite.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdravlja vas cerkev, ki je v Babilonu, izvoljena skupaj z vami, in tudi Marko, moj sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, '§ Pozdravite drug drugega s poljubom ljubezni. Mir bodi z vami vsemi, ki ste v Kristusu Jezusu. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Peter, služabnik in apostol Jezusa Kristusa tem, ki so z nami po Božji pravičnosti in našem Odrešeniku Jezusu Kristusu dosegli podobno dragoceno vero:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, '›Milost in mir naj se vam pomnožita prek spoznanja Boga in Jezusa, našega Gospoda,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'glede na to, kot nam je njegova božanska moč dala vse stvari, ki se nanašajo na življenje in bogaboječnost, prek spoznanja tistega, ki nas je poklical v slavo in moč;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'po katerih so nam dane silno velike in dragocene obljube, da bi bili po teh lahko soudeleženci božanske narave, ko smo pobegnili propadljivosti, ki je na svetu prek poželenja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'In poleg tega darujte vso marljivost, dodajte svoji veri krepost, in kreposti spoznanje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'in spoznanju zmernost, in zmernosti potrpežljivost, in potrpežljivosti bogaboječnost,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'in bogaboječnosti bratsko prijaznost, in bratski prijaznosti ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Kajti če so te stvari v vas in [so] obilne, vas naredijo, da ne boste niti jalovi niti brez sadu v spoznanju našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Toda komur te stvari primanjkujejo, je slep in kratkoviden in je pozabil, da je bil očiščen od svojih starih grehov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Bratje, zatorej si raje prizadevajte, da storite svojo poklicanost in izvoljenost zanesljivo; kajti če te stvari počnete, nikoli ne boste padli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'kajti tako vam bo razkošno odprt vstop v večno kraljestvo našega Gospoda in Odrešenika Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Zato ne bom nemaren, da vas ne bi vedno opominjal o teh stvareh, čeprav jih veste in ste utrjeni v pričujoči resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Da, mislim, da je primerno, dokler sem v tem šotoru, da vas razvnamem s tem, da vas spomnim,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'vedoč, da bom moral v kratkem odložiti ta svoj šotor, kakor mi je pokazal naš Gospod Jezus Kristus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Poleg tega si bom prizadeval, da boste po mojem odhodu [s sveta] lahko imeli te stvari vedno v spominu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Kajti ko smo vam dali spoznati moč in prihod našega Gospoda Jezusa Kristusa, nismo sledili pretkano izmišljenim bajkam, ampak smo bili očividci njegovega veličanstva.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Kajti od Boga Očeta je prejel čast in slavo, ko je iz odlične slave k njemu prišel takšen glas: »Ta je moj ljubljeni Sin, v katerem sem zelo zadovoljen.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'In ta glas, ki je prišel z neba, smo slišali, ko smo bili z njim na sveti gori.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Imamo tudi zanesljivejšo preroško besedo; zato pravilno delate, da pazite nanjo kakor na svetilko, ki sije na temnem kraju, dokler ne zasveti zora in v vaših srcih ne vzide zvezda danica;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'vedoč najprej to, da nobena prerokba iz pisem ni iz kakršnekoli osebne razlage.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Kajti prerokba v starih časih ni prišla s človeško voljo, temveč so sveti Božji možje govorili, kakor bi bili spodbujeni s Svetim Duhom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Vendar so bili lažni preroki tudi med ljudmi, točno tako bodo med vami lažni učitelji, ki bodo na skrivnem vnašali preklenska krivoverstva in celó tajili Gospoda, ki jih je odkupil ter si nase nakopali hiter propad.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'In mnogi bodo sledili njihovim pogubnim potem; zaradi katerih se bo obrekovala pot resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'In zaradi pohlepnosti bodo s hlinjenimi besedami iz vas naredili trgovsko blago; katerih sodba se sedaj že dolgo ne obotavlja in njihovo prekletstvo ne dremlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Kajti če Bog ni prizanesel angelom, ki so grešili, temveč jih je vrgel navzdol v pekel in jih izročil verigam teme, da bodo pridržani do sodbe,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'in ni prizanesel staremu svetu, temveč rešil Noeta, osmo osebo, oznanjevalca pravičnosti, ko je poslal potop na svet brezbožnih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'in spremenil mesti Sódome in Gomóre v pepel, ju je obsodil z uničenjem in ju naredil zgled tem, ki naj bi kasneje brezbožno živeli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'in osvobodil pravičnega Lota, prizadetega z umazanim razgovorom zlobnih;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(kajti ta pravičen mož je prebival med njimi in z videnjem in slišanjem iz dneva v dan z njihovimi nezakonitimi dejanji mučil svojo pravično dušo.)');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Gospod ve kako bogaboječega osvoboditi iz preizkušenj in nepravične prihraniti za dan sodbe, da bodo kaznovani.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Toda predvsem te, ki hodijo za mesom v nečistosti poželenja in prezirajo vlado. Predrzni so, svojevoljni, ne bojijo se hudobno govoriti o dostojanstvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Medtem ko angeli, ki so večji v moči in mogočnosti, pred Gospoda ne prinašajo posmehljivih obtožb zoper njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Toda ti, kot naravne okrutne živali, narejene, da so ujete in uničene, govorijo hudobno o stvareh, ki jih ne razumejo; in v svoji lastni pokvarjenosti bodo popolnoma propadli;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'in prejeli bodo nagrado nepravičnosti, kakor tisti, ki imajo za užitek razgrajanje podnevi. Madeži so in izvržki, ki se zabavajo s svojimi lastnimi zavajanji, medtem ko se gostijo z vami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'ki imajo oči, polne zakonolomstva in ki ne morejo prenehati z grehom; ki zapeljujejo omahljive duše, srce pa so urili s pohlepnimi navadami; prekleti otroci;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'ki so zapustili pravo pot in zašli ter sledili Beórjevemu sinu Bileámu, ki je vzljubil plačila nepravičnosti;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'toda za svojo krivičnost je bil oštet; nemi osel, govoreč s človeškim glasom, je preprečil prerokovo norost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ti so vodnjaki brez vode, oblaki, ki so nošeni z viharjem, ki jim je večno prihranjena zamegljena črnina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Kajti ko govorijo velike, napihnjene besede ničevosti, privabljajo s poželenji mesa, skozi mnoge razuzdanosti te, ki so zares pobegnili pred temi, ki živijo v zmoti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Medtem ko jim obljubljajo svobodo, [pa] so oni sami služabniki izprijenosti. Kajti od česar je človek premagan, od istega je priveden v sužnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Kajti če so potem, ko so prek spoznanja Gospoda in Odrešenika Jezusa Kristusa pobegnili umazanostim sveta, bili ponovno vpleteni vanje in premagani, je zadnji konec z njimi slabši kakor začetek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Kajti zanje bi bilo bolje, da ne bi spoznali poti pravičnosti, kakor pa, potem ko so jo spoznali, da se obrnejo od svete zapovedi, ki jim je bila izročena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Toda to se jim je zgodilo glede na resničen pregovor: ›Pes se ponovno obrne k svojemu lastnemu izbljuvku; in svinja, ki je bila umita, k svojemu valjanju v blatu.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Ljubljeni, sedaj vam pišem torej to drugo poslanico; v katerih obeh sem vaše čiste ume razvnel z načinom spominjanja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'da boste lahko razmišljali o besedah, ki so bile prej izgovorjene po svetih prerokih in o zapovedi od nas, apostolov Gospoda in Odrešenika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Vedite najprej to, da bodo v poslednjih dneh prišli porogljivci, ki bodo hodili za svojimi lastnimi poželenji');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'ter govorili: »Kje je obljuba njegovega prihoda? Kajti odkar so očetje zaspali, se vse stvari nadaljujejo, kakor so bile od začetka stvarstva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Kajti oni tega nočejo spoznati, da je bilo po Božji besedi nebo od davnine in [da] zemlja sestoji iz vode in v vodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'S čimer je bil svet, ki je bil takrat, preplavljen z vodo, uničen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Toda nebo in zemlja, ki sta sedaj, sta po isti besedi držana v rezervi, prihranjena ognju za dan sodbe in pogube brezbožnih ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Toda ljubljeni, ne bodite nevedni o tej eni stvari, da je en dan z Gospodom kakor tisoč let in tisoč let kakor en dan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Gospod ni počasen glede svoje obljube, kakor nekateri ljudje razumejo počasnost, temveč je do nas potrpežljiv, ne voljan, da bi se kdorkoli pogubil, temveč da bi vsi prišli do kesanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, '§ Toda Gospodov dan bo prišel kakor tat v noči; v kateri bo nebo preminilo z velikim hrupom in prvine se bodo stopile z gorečo vročino; tudi zemlja in dela, ki so na njej, bodo sežgana.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ker se bodo torej vse te stvari raztopile, kakšna vrsta oseb morate biti v vsem svetem vedênju in bogaboječnosti,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'da pričakujete in hitite k prihajanju Božjega dne, ko se bo nebo goreče stopilo in se bodo prvine stopile z gorečo vročino?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Kljub temu pa mi, glede na njegovo obljubo, pričakujemo novo nebo in novo zemljo, kjer prebiva pravičnost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Torej, ljubljeni, glede na to, da pričakujete takšne stvari, si prizadevajte, da vas bo lahko našel v miru, brez madeža in brez krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'In upoštevajte, da je potrpežljivost našega Gospoda rešitev duš; kakor vam je napisal tudi naš ljubljeni brat Pavel, glede na modrost, ki mu je bila dana;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'kakor je tudi v vseh njegovih poslanicah, kjer v njih govori o teh stvareh; v katerih so nekatere stvari težke za razumevanje, ki jih tisti, ki so nepoučeni in omahljivi, pačijo, kakor počno tudi drugim pismom, v svoje lastno uničenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vi torej, ljubljeni, glede na to, da vidim, da poprej poznate te stvari, se varujte, da ne bi tudi vi, zavedeni z zmoto zlobnih, odpadli od svoje lastne neomajnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Temveč rastite v milosti in v spoznanju našega Gospoda in Odrešenika Jezusa Kristusa. Njemu bodi slava tako sedaj in na veke. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'To, kar je bilo od začetka, kar smo slišali, kar smo videli s svojimi lastnimi očmi, kar smo opazovali in so naše roke prijele, Besedo življenja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(kajti življenje je bilo jasno pokazano in videli smo ga in pričujemo in vam kažemo to večno življenje, ki je bilo z Očetom in je bilo jasno pokazano nam),');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'to, kar smo videli in slišali, to oznanjamo vam, da boste tudi vi lahko imeli z nami družbo; in resnično, naša družba je z Očetom in z njegovim Sinom Jezusom Kristusom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'In te stvari vam pišemo, da bo vaše veselje lahko popolno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'To je torej sporočilo, ki smo ga slišali od njega in ga oznanjamo vam, da je Bog svetloba in v njem sploh ni nobene teme.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Če rečemo, da imamo družbo z njim, pa hodimo v temi, lažemo in ne delamo resnice;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, '§ toda če hodimo v svetlobi, kakor je on v svetlobi, imamo družbo drug z drugim in kri Jezusa Kristusa, njegovega Sina, nas očiščuje pred vsakim grehom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Če rečemo, da nimamo greha, sami sebe zavajamo in resnice ni v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Če priznavamo svoje grehe, je zvest in pravičen, da nam naše grehe odpusti in da nas očisti pred vso nepravičnostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Če rečemo, da nismo grešili, ga naredimo lažnivca in njegove besede ni v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Moji mali otroci, te stvari vam pišem, da ne grešite. Če pa katerikoli človek greši, imamo pri Očetu zagovornika, Jezusa Kristusa, pravičnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'In on je spravna daritev za naše grehe, pa ne samo za naše, ampak tudi za grehe celotnega sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'In s tem spoznamo, da ga poznamo, če se ravnamo po njegovih zapovedih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kdor pravi: »Poznam ga,« pa se ne drži njegovih zapovedi, je lažnivec in v njem ni resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Toda kdorkoli se drži njegove besede, je v njem Božja ljubezen resnično izpopolnjena; s tem spoznamo, da smo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kdor pravi, [da] ostaja v njem, mora tudi sam tako živeti, kakor je živel on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, '§ Bratje, ne pišem vam nobene nove zapovedi, temveč staro zapoved, ki ste jo imeli od začetka. Stara zapoved je beseda, ki ste jo slišali od začetka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Ponovno vam pišem novo zapoved, katere beseda je resnična v njem in v vas; zato ker je tema minila in sedaj sije resnična svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kdor pravi, [da] je v svetlobi, pa sovraži svojega brata, je v temi celó do sedaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kdor ljubi svojega brata, ostaja v svetlobi in v njem ni nobene priložnosti za spotiko.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Toda kdor sovraži svojega brata, je v temi in hodi po temi in ne ve, kam gre, zato ker mu je ta tema zaslepila njegove oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Pišem vam, otročički, ker so vam zaradi njegovega imena odpuščeni vaši grehi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pišem vam, očetje, ker ste spoznali njega, ki je od začetka. Pišem vam, mladeniči, ker ste premagali zlobnega. Pišem vam, majhni otroci, ker ste spoznali Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pisal sem vam, očetje, ker ste spoznali njega, ki je od začetka. Pisal sem vam, mladeniči, ker ste močni in Božja beseda ostaja v vas in ste premagali zlobnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Ne ljubite sveta niti stvari, ki so v svetu. Če katerikoli človek ljubi svet, v njem ni Očetove ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Kajti vse, kar je v svetu, poželenje mesa, poželenje oči in napuh življenja, ni od Očeta, temveč od sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'In svet mineva in njegovo poželenje; kdor pa izpolnjuje Božjo voljo, ostaja na veke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Majhni otroci, poslednji čas je in kakor ste slišali, da bo prišel antikrist, je celó sedaj tam mnogo antikristov; po čemer vemo, da je poslednji čas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Izšli so od nas, toda niso bili od nas; kajti če bi bili od nas, bi brez dvoma ostali z nami, toda odšli so ven, da bi bili lahko jasno prikazani, da niso bili vsi od nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Toda vi imate maziljenje od Svetega in poznate vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nisem vam pisal, ker ne poznate resnice, temveč ker jo poznate in da nobena laž ni iz resnice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kdo je lažnivec razen, kdor zanika, da Jezus je Kristus? Ta je antikrist, ki zanika Očeta in Sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Kdorkoli zanika Sina, ta isti nima Očeta; [toda] kdor priznava Sina, ima tudi Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Naj torej v vas ostaja to, kar ste slišali od začetka. Če bo to, kar ste slišali od začetka, ostalo v vas, boste tudi vi ostali v Sinu in v Očetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'In to je obljuba, ki nam jo je obljubil, celó večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Te stvari sem vam napisal glede teh, ki vas zapeljujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Toda maziljenje, ki ste ga prejeli od njega, ostaja v vas in ne potrebujete, da vas katerikoli človek uči. Toda kakor vas isto maziljenje uči o vseh stvareh in je resnično in ni laž in celo tako kakor vas je poučilo, boste ostali v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'In sedaj, majhni otroci, ostanite v njem, da ko se bo prikazal, bomo lahko imeli zaupanje in ob njegovem prihodu ne bomo osramočeni pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Če veste, da je pravičen, spoznavate, da je vsak, kdor ravna pravično, rojen iz njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, '§ Glejte, kakšno vrsto ljubezni nam je podelil Oče, da naj bi bili imenovani Božji sinovi; zato nas svet ne spoznava, ker ni spoznal njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Ljubljeni, sedaj smo Božji sinovi, ni pa se še pokazalo, kaj bomo; toda vemo, da ko se bo prikazal, bomo podobni njemu, kajti videli ga bomo, kakršen je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'In vsak človek, ki ima to upanje vanj, se očiščuje, celó kakor je on čist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Kdorkoli zagreši greh, prestopa tudi postavo, kajti greh je prekršitev postave.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'In vi veste, da je bil jasno pokazan, da odvzame naše grehe; in v njem ni greha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Kdorkoli ostaja v njem, ne greši. Kdorkoli pa greši, ga ni videl niti ga ni spoznal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Majhni otroci, naj vas noben človek ne zavede. Kdor ravna pravično, je pravičen, celó kakor je pravičen on.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kdor zagreši greh, je od hudiča, kajti hudič greši od začetka. Zaradi tega namena je bil jasno pokazan Božji Sin, da bi lahko uničil hudičeva dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Kdorkoli je rojen iz Boga, ne stori greha, kajti njegovo seme ostaja v njem; in ne more grešiti, ker je rojen iz Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'V tem so prikazani Božji otroci in hudičevi otroci: kdorkoli ne dela pravičnosti, ni od Boga niti kdor ne ljubi svojega brata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Kajti to je sporočilo, ki ste ga slišali od začetka, da naj ljubimo drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne kakor Kajn, ki je bil od tega zlobnega in je usmrtil svojega brata. In zakaj ga je usmrtil? Ker so bila njegova lastna dela hudobna, njegovega brata pa pravična.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne čudite se, moji bratje, če vas svet sovraži.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Mi vemo, da smo iz smrti prešli v življenje, ker ljubimo brate. Kdor svojega brata ne ljubi, ostaja v smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Kdorkoli sovraži svojega brata, je morilec; in veste, da noben morilec nima večnega življenja, ki [bi] ostajalo v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'S tem zaznavamo Božjo ljubezen, ker je svoje življenje dal za nas, in mi moramo svoja življenja dati za brate.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Toda kdorkoli ima dobrine tega sveta in vidi svojega brata v potrebi in pred njim zapre svoja čustva sočutja, kako v njem prebiva Božja ljubezen?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Moji majhni otroci, ne ljubimo z besedo niti z jezikom; temveč v dejanju in v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'In s tem vemo, da smo iz resnice in bomo svoja srca potrdili pred njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Kajti če nas naše srce obsoja, je Bog večji kakor naše srce in pozna vse stvari.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Ljubljeni, če nas naše srce ne obsoja, potem imamo zaupanje do Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'In karkoli prosimo, od njega prejmemo, ker se ravnamo po njegovih zapovedih in delamo te stvari, ki so všečne v njegovih očeh.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'In to je njegova zapoved: »Da naj verujemo v ime njegovega Sina Jezusa Kristusa in ljubimo drug drugega,« kakor nam je dal zapoved.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'In kdor se ravna po njegovih zapovedih, prebiva v njem in on v njem. In zaradi tega vemo, da on ostaja v nas, po Duhu, ki nam ga je dal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Ljubljeni, ne verjemite vsakemu duhu, temveč duhove preizkušajte, ali so od Boga, ker je mnogo lažnih prerokov odšlo v svet.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'S tem prepoznate Božjega Duha: »Vsak duh, ki priznava, da je Jezus Kristus prišel v mesu, je od Boga;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, '§ in noben duh, ki ne priznava, da je Jezus Kristus prišel v mesu, ni od Boga; in to je ta duh antikrista, o katerem ste slišali, da naj bi prišel; in je celó že sedaj na svetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Vi ste od Boga, majhni otroci in ste jih premagali, ker je večji tisti, ki je v vas, kakor ta, ki je v svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Oni so od sveta; zaradi tega govorijo o svetu in svet jih posluša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Mi [pa] smo od Boga; kdor pozna Boga, nas posluša, kdor [pa] ni od Boga, nas ne posluša. S tem spoznamo duha resnice in duha zmote.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Ljubljeni, ljubimo drug drugega, kajti ljubezen je od Boga, in vsak, kdor ljubi, je rojen iz Boga in pozna Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kdor ne ljubi, ne pozna Boga, kajti Bog je ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'V tem je bila do nas jasno pokazana Božja ljubezen, zato ker je ta Bog poslal svojega edinorojenega Sina v svet, da bi mi lahko živeli po njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'V tem je ljubezen, ne da smo mi ljubili Boga, temveč, da nas je on ljubil in poslal svojega Sina, da postane spravna daritev za naše grehe.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Ljubljeni, če nas je Bog tako ljubil, bi morali tudi mi ljubiti drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Noben človek nikoli ni videl Boga. Če ljubimo drug drugega, Bog prebiva v nas in je njegova ljubezen izpopolnjena v nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'S tem vemo, da prebivamo v njem in on v nas, ker nam je dal od svojega Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'In videli smo in pričujemo, da je Oče poslal Sina, da bi bil Odrešenik sveta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Kdorkoli bo priznal, da je Jezus Božji Sin, Bog prebiva v njem in on v Bogu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'In mi smo spoznali in verovali ljubezni, ki jo ima Bog do nas. Bog je ljubezen in kdor prebiva v ljubezni, prebiva v Bogu in Bog v njem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'V tem se je naša ljubezen dovršila, da imamo lahko srčnost na dan sodbe; ker kakor je on, tako smo mi na tem svetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'V ljubezni ni nobenega strahu, temveč popolna ljubezen izganja strah; ker strah vsebuje muko. Kdor se boji, ni izpopolnjen v ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Mi ga ljubimo, ker je najprej on ljubil nas.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Če človek reče: »Ljubim Boga,« pa sovraži svojega brata, je lažnivec; kajti kdor ne ljubi svojega brata, ki ga je videl, kako lahko ljubi Boga, ki ga ni videl?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'In od njega imamo to zapoved: »Da kdor ljubi Boga, ljubi tudi svojega brata.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Kdorkoli veruje, da Jezus je Kristus, je rojen iz Boga; in vsak, kdor ljubi tistega, ki je zaplodil, ljubi tudi tistega, ki je zaplojen od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Da ljubimo Božje otroke, spoznamo s tem, ko ljubimo Boga in se ravnamo po njegovih zapovedih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Kajti to je Božja ljubezen, da se ravnamo po njegovih zapovedih; in njegove zapovedi niso mučne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Kajti karkoli je rojeno iz Boga, premaga svet; in to je zmaga, ki premaga svet, celó naša vera.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kdo je tisti, ki premaga svet, če ne tisti, ki veruje, da je Jezus Božji Sin?');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'To je on, ki je prišel z vodo in krvjo, celó Jezus Kristus; ne samo z vodo, temveč z vodo in krvjo. In to je Duh, ki prinaša pričevanje, ker Duh je resnica.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, '§ Kajti trije so, ki pričujejo na nebu: Oče, Beseda in Sveti Duh; in ti trije so eno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, '§ In trije so, ki pričujejo na zemlji: Duh in voda in kri; in ti trije se strinjajo v enem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Če smo sprejeli pričevanje od ljudi, je pričevanje od Boga večje, kajti to je pričevanje Boga, ki je pričeval o svojem Sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kdor veruje v Božjega Sina, ima pričevanje v sebi. Kdor pa ne veruje Bogu, ga je storil za lažnivca, ker ne veruje zapisu, ki ga je Bog dal o svojem Sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'In to je zapis, da nam je Bog dal večno življenje in to življenje je v njegovem Sinu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kdor ima Sina, ima življenje; kdor pa nima Božjega Sina, nima življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, '§ Te besede sem napisal vam, ki verujete v ime Božjega Sina; da boste lahko vedeli, da imate večno življenje in da lahko verujete v ime Božjega Sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'In to je zaupanje, ki ga imamo v njem, da če prosimo katerokoli stvar, glede na njegovo voljo, nas on usliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'In če vemo, da nas sliši, karkoli prosimo, vemo, da imamo prošnje, ki smo jih želeli od njega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Če katerikoli človek vidi svojega brata grešiti [z] grehom, ki ni za smrt, bo prosil in on mu bo dal življenje, za tiste, ki ne grešijo za smrt. Obstaja greh za smrt; ne pravim, da naj prosi zanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Vsa nepravičnost je greh; obstaja pa greh, ki ni za smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, '§ Vemo, da kdorkoli je rojen iz Boga, ne greši; temveč kdor je rojen iz Boga, sebe varuje in ta zlobni se ga ne dotika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'In mi vemo, da smo od Boga, celoten svet pa leži v zlobnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'In mi vemo, da je Božji Sin prišel ter nam dal razumevanje, da bi lahko spoznali tistega, ki je resničen in mi smo v njem, ki je resničen, celó v njegovem Sinu Jezusu Kristusu. Ta je resničen Bog in večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, '§ Majhni otroci, varujte se pred maliki. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Starešina izvoljeni gospe in njenim otrokom, ki jih ljubim v resnici; pa ne samo jaz, temveč tudi vsi tisti, ki so spoznali resnico;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'zaradi resnice, ki prebiva v nas in bo za vedno z nami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, '§ Milost bodi z vami, usmiljenje in mir od Boga Očeta in od Gospoda Jezusa Kristusa, Očetovega Sina, v resnici in ljubezni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Silno sem se razveselil, da sem našel nekatere izmed tvojih otrok, ki hodijo v resnici, kakor smo prejeli zapoved od Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'In sedaj te rotim, gospa, ne kakor da sem ti napisal novo zapoved, temveč to, ki smo jo imeli od začetka, da ljubimo drug drugega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'In to je ljubezen, da živimo po njegovih zapovedih. To je zapoved: »Da kakor ste slišali od začetka, naj bi hodili v njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Kajti mnogo sleparjev je vstopilo na svet, ki ne priznavajo, da je Jezus Kristus prišel v mesu. Ta je slepar in antikrist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Glejte nase, da ne izgubimo teh stvari, ki smo jih izvršili, temveč, da prejmemo popolno plačilo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Kdorkoli greši in ne ostaja v Kristusovem nauku, nima Boga. Kdor ostaja v Kristusovem nauku, ima tako Očeta kakor Sina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, '§ Če kdo pride k vam in vam ne prinese tega nauka, ga ne sprejmite v svojo hišo niti mu ne želite: »Bog te obvarji! Srečno!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, '§ Kajti kdor mu želi: »Bog te obvarji! Srečno!« je soudeleženec njegovih zlih dejanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Ker vam imam napisati mnogo stvari, ne želim pisati s papirjem in črnilom, temveč zaupam, da pridem k vam in spregovorim iz obličja v obličje, da bo naše veselje lahko popolno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, '§ Pozdravljajo te otroci tvoje izvoljene sestre. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Starešina srčno ljubljenemu Gaju, ki ga ljubim v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Ljubljeni, nad vsemi stvarmi si najbolj želim, da bi ti lahko uspeval in bil zdrav, celó kakor uspeva tvoja duša.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Kajti silno sem se razveselil, ko so prišli bratje in pričevali o resnici, ki je v tebi, celó kako živiš v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Nimam večjega veselja, kakor da slišim, da moji otroci živijo v resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Ljubljeni, zvesto delaš, karkoli delaš bratom in tujcem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'ki so pred cerkvijo nosili pričevanje o tvoji ljubezni. Katerim, če jim pomagaš na poti na bogaboječ način, boš storil prav,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'zato ker so odšli zaradi njegovega imena in ničesar niso jemali od poganov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Take bi morali torej sprejemati, da bi lahko postali sopomočniki k resnici.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Pisal sem cerkvi, toda Diotréf, ki ima med njimi rad premoč, nas ne sprejema.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Zatorej, če pridem, se bom spomnil njegovih dejanj, ki jih počne, ko proti nam žlobudra s hudobnimi besedami, in ni zadovoljen s tem niti sam ne sprejema bratov in prepoveduje tem, ki bi jih hoteli in jih izganja iz cerkve.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Ljubljeni, ne sledi temu, kar je hudobno, temveč temu, kar je dobro. Kdor dela dobro, je od Boga; kdor pa dela hudobno, ni videl Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrij ima dober glas od vseh ljudi in od same resnice; da, in tudi mi pričujemo; in veš, da je naše pričevanje resnično.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Mnogo stvari sem imel napisati, toda nočem ti pisati s črnilom in peresom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'temveč zaupam, da te bom v kratkem videl in spregovorila bova iz obličja v obličje. Mir ti bodi. Pozdravljajo te naši prijatelji. Pozdravi prijatelje po imenu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, '§ Juda, služabnik Jezusa Kristusa in Jakobov brat, tem, ki so posvečeni po Bogu Očetu in ohranjeni v Jezusu Kristusu in poklicani:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, '›Usmiljenje in mir in ljubezen naj se vam pomnožijo.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Ljubljeni, ko sem posvetíl vso marljivost, da vam pišem o skupni rešitvi duš, je bilo zame nujno, da vam pišem in vas spodbujam, da se resno borite za vero, ki je bila enkrat [za vselej] izročena svetim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Kajti ne-sluteč so se prikradli določeni ljudje, ki so bili že od davno odrejeni za to obsodbo, brezbožni ljudje, ki milost našega Boga sprevračajo v opolzkost in zanikajo edinega Gospoda Boga in našega Gospoda Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Hočem vas torej spomniti, čeprav ste nekoč to vedeli, da je Gospod, ki je ljudi rešil iz egiptovske dežele, potem uničil te, ki niso verovali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'In angele, ki niso obdržali svojega prvega stanja, temveč so zapustili svoje prebivališče, je ohranil v večnih verigah pod temo, do sodbe vélikega dne.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Celó kakor so Sódoma in Gomóra in na podoben način mesta okoli njiju, ki so same sebe predajala v prešuštvo in hodila za tujim mesom, postavljena kot zgled, trpeč maščevanje večnega ognja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Podobno tudi ti umazani sanjači omadežujejo meso, prezirajo gospostvo in hudobno govorijo o dostojanstvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Vendarle si nadangel Mihael, ko se je pričkal s hudičem in prerekal glede Mojzesovega telesa, ni drznil zoper njega udrihati obtožbe, temveč je rekel: »Gospod te ošteje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Toda ti govorijo hudobno o teh stvareh, ki jih ne poznajo; toda kar naravno vedo kot brezčutne živali, v teh stvareh sami sebe kvarijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Gorje jim! Kajti odšli so na Kajnovo pot in lakomno tekli za Bileámovo zmoto po nagrado in propadli v Korahovem uporu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ti so madeži na vaših dobrodelnih pojedinah, ko se zabavajo z vami in se hranijo brez strahu. Oblaki so brez vode, ki jih vetrovi nosijo okoli; drevesa, katerih sad vene, brez sadu, dvakrat mrtva, izruvana s koreninami;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'besneči morski valovi, ki se penijo od svoje lastne sramote; blodeče zvezde, ki jim je za vedno prihranjena črna temà.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'In tudi Henoh, sedmi od Adama, je prerokoval o njih, rekoč: ›Glej, Gospod prihaja z deset tisoči svojih svetih,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, '§ da izvrši sodbo nad vsemi in da prepriča vse, ki so med njimi brezbožni, o vseh njihovih brezbožnih dejanjih, ki so jih brezbožno zagrešili in o vseh njihovih trdih govorih, ki so jih brezbožni grešniki govorili zoper njega.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'To so godrnjači, pritoževalci, ki hodijo za svojimi lastnimi poželenji; in njihova usta govorijo velike napihnjene besede, ker zaradi koristi občudujejo človeško zunanjost.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Toda ljubljeni, spominjajte se besed, ki so vam jih prej govorili apostoli našega Gospoda Jezusa Kristusa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'kako so vam povedali, da bodo v poslednjem času zasmehovalci, ki naj bi hodili za svojimi lastnimi brezbožnimi poželenji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ti so tisti, ki se oddvojijo, čutni, ki nimajo Duha.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Toda vi, ljubljeni, se izgrajujte v svoji najsvetejši veri, moleč v Svetem Duhu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'ohranite se v Božji ljubezni, pričakujte usmiljenje našega Gospoda Jezusa Kristusa, za večno življenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, '§ In do nekaterih imejte sočutje, s tem da delate razliko;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, '§ druge pa rešite s strahom in jih potegnite iz ognja; in sovražite celó obleko, omadeževano z mesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Torej njemu, ki vas je zmožen varovati pred padcem in vas s silno radostjo predstaviti brezhibne pred prisotnost svoje slave,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'edinemu modremu Bogu, našemu Odrešeniku, bodi slava in veličanstvo, gospostvo in oblast, tako sedaj kot na veke. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Razodetje Jezusa Kristusa, ki mu ga je dal Bog, da bi pokazal svojim služabnikom stvari, ki se morajo v kratkem zgoditi; in poslal je ter to po svojem angelu predstavil svojemu služabniku Janezu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'ki je pričeval o Božji besedi in o pričevanju Jezusa Kristusa in o vseh stvareh, ki jih je videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Blagoslovljen je, kdor bere in tisti, ki slišijo besede te prerokbe in se držijo teh stvari, ki so v njej zapisane; kajti čas je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Janez sedmim cerkvam, ki so v Aziji: »Milost bodi vam in mir od njega, ki je in ki je bil in ki pride in od sedmih Duhov, ki so pred njegovim prestolom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'in od Jezusa Kristusa, ki je zvesta priča in prvorojenec izmed umrlih in princ kraljev zemlje. Njemu, ki nas je vzljubil in nas je v svoji lastni krvi umil naših grehov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'in nas naredil kralje in duhovnike Bogu ter svojemu Očetu; njemu bodi slava in gospostvo na veke vekov. Amen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Glej, prihaja z oblaki in videlo ga bo vsako oko in tudi tisti, ki so ga prebodli in zaradi njega bodo žalovala vsa sorodstva zemlje. Točno tako: ›Amen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '§ »Jaz sem Alfa in Omega, začetek in konec,« govori Gospod, ki je in ki je bil in ki pride, Vsemogočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Jaz, Janez, ki sem tudi vaš brat in družabnik v stiski in v kraljestvu in potrpežljivosti Jezusa Kristusa, sem bil zaradi Božje besede in zaradi pričevanja o Jezusu Kristusu na otoku, ki se imenuje Patmos.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Na Gospodov dan sem bil v Duhu in za seboj sem zaslišal močan glas kakor od trobente,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, '§ rekoč: »Jaz sem Alfa in Omega, prvi in zadnji.« In: »Kar vidiš, zapiši v knjigo in jo pošlji sedmim cerkvam, ki so v Aziji: v Efez in v Smirno in v Pêrgamon in v Tiatiro in v Sarde in v Filadelfijo in v Laodikejo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'In obrnil sem se, da vidim glas, ki je govoril z menoj. In ko sem se obrnil, sem zagledal sedem zlatih svečnikov');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'in sredi sedmih svečnikov nekoga, podobnega Sinu človekovemu, oblečenega z obleko, ki sega do stopal in okoli prsi opasanega z zlatim pasom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Njegova glava in njegovi lasje so bili beli kakor volna, tako beli kakor sneg in njegove oči so bile kakor plamen ognja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'in njegova stopala podobna čistemu bronu, kakor če bi bila žgana v talilni peči in njegov glas kakor šum mnogih vodá.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'In v svoji desnici je imel sedem zvezd in iz njegovih ust je izhajal oster, dvorezen meč in njegovo obličje je bilo, kot [kadar] sonce sije v svoji môči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'In ko sem ga zagledal, sem padel k njegovim stopalom kakor mrtev. In svojo desnico je položil name ter mi rekel: »Ne boj se; jaz sem prvi in zadnji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, '§ Jaz sem ta, ki živi in je bil mrtev; in glej, živ sem na vékomaj, Amen; in ključe imam od pekla in od smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Zapiši stvari, ki si jih videl, in stvari, ki so, in stvari, ki bodo odslej;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'skrivnost sedmih zvezd, ki jih vidiš v moji desni in sedmih zlatih svečnikov. Sedem zvezd so angeli sedmih cerkvá in sedem svečnikov, ki jih vidiš, je sedem cerkvá.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '»Angelu cerkve v Efezu piši: ›Te stvari govori on, ki v svoji desnici drži sedem zvezd, ki hodi v sredi sedmih zlatih svečnikov;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'poznam tvoja dela in tvoj trud in tvojo potrpežljivost in kako ne moreš prenašati teh, ki so hudobni in preizkusil si tiste, ki pravijo, da so apostoli, pa to niso in si jih našel lažnivce.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'In prenašal si in imaš potrpežljivost in si se trudil zaradi mojega imena in nisi izgubil poguma.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Vendar imam nekaj proti tebi, kajti zapustil si svojo prvo ljubezen.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, '§ Spomni se torej, od kod si padel in se pokesaj in opravljaj prva dela, sicer bom hitro prišel k tebi in bom odstranil tvoj svečnik z njegovega mesta, razen če se ne pokesaš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Toda to imaš, da sovražiš dejanja nikolajevcev, ki jih tudi sam sovražim.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Tistemu, ki premaga, bom dal jesti od drevesa življenja, ki je na sredini Božjega raja.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '»In angelu cerkve v Smirni piši: ›Te stvari govori prvi in zadnji, ki je bil mrtev in je živ;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, '§ poznam tvoja dela in stisko in revščino (toda bogat si) in poznam bogokletje teh, ki pravijo, da so Judje, pa niso, temveč so Satanova sinagoga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne boj se nobene od teh stvari, ki jih boš pretrpel. Glej, hudič bo nekatere izmed vas vrgel v ječo, da boste lahko preizkušeni in deset dni boste imeli stisko. Bodi zvest do smrti in dal ti bom krono življenja.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Kdor premaga, ne bo poškodovan od druge smrti.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, '»In angelu cerkve v Pêrgamonu piši: ›Te besede govori on, ki ima oster meč z dvema ostrinama;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'poznam tvoja dela in kje prebivaš, celó kjer je Satanov prestol. In trdno držiš moje ime in moje vere nisi zanikal celó v tistih dneh, v katerih je bil Antípa, moj zvesti mučenec, ki je bil umorjen med vami, kjer prebiva Satan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Toda zoper tebe imam nekaj stvari, ker imaš tam tiste, ki se drže Bileámovega nauka, ki je učil Baláka metati kamen spotike pred Izraelove otroke, da jedo stvari žrtvovane malikom in da zagrešijo prešuštvo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, '§ Tako imaš tudi tiste, ki se držijo nauka nikolajevcev, katerih besedo sovražim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, '§ Pokesaj se, sicer bom hitro prišel k tebi in proti njim se bom boril z mečem svojih ust.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Tistemu, ki premaga, bom dal jesti od skrite mane in dal mu bom bel kamen in na kamnu napisano novo ime, ki ga ne pozna noben človek, razen, kdor ga prejme.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, '»In angelu cerkve v Tiatiri piši: ›Te stvari govori Božji Sin, ki ima svoje oči podobne plamenu ognja in so njegova stopala kakor čist bron;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'poznam tvoja dela in ljubezen in služenje in vero in tvojo potrpežljivost in tvoja dela; in zadnjih je več kakor prvih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Vendar imam zoper tebe nekaj stvari, ker trpiš to žensko Jezabelo, ki sebe imenuje prerokinjo, da uči in da zapeljuje moje služabnike, da zagrešijo prešuštvo in da jedo stvari, žrtvovane malikom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'In dal sem ji čas, da se pokesa od svojega prešuštvovanja, pa se ni pokesala.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Glej, vrgel jo bom na posteljo in te, ki z njo grešijo zakonolomstvo, v veliko stisko, razen če se ne pokesajo od svojih dejanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'In njene otroke bom pobil s smrtjo in vse cerkve bodo vedele, da sem jaz tisti, ki preiskujem notranjosti in srca; in vsakemu od vas bom dal glede na vaša dejanja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Toda tebi in ostalim iz Tiatire pravim, kdor nima tega nauka in tem, ki niso spoznali Satanovih globin, kakor govorijo; na vas ne bom nadel nobenega drugega bremena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Temveč da trdno držite to, kar že imate, dokler ne pridem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'In kdor zmaga in moja dela ohrani do konca, njemu bom dal oblast nad narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'In vladal jim bo z železno palico; kakor lončena posoda bodo razbiti do črepinj; celo kot sem jaz prejel od svojega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'In dal mu bom jutranjo zvezdo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '»In angelu cerkve v Sardah piši: ›Te besede govori on, ki ima sedem Božjih Duhov in sedem zvezd; poznam tvoja dela, da imaš ime, da živiš, pa si mrtev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Bodi oprezen in okrépi stvari, ki ostanejo, ki so pripravljene, da umro, kajti tvojih del nisem našel popolnih pred Bogom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, '§ Spomni se torej, kako si prejel in slišal in trdno drži ter se pokesaj. Če torej ne boš stražil, bom prišel nadte kakor tat in ne boš vedel, katero uro bom prišel nadte.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Nekaj imen imaš celó v Sardah, ki si niso omadeževali svojih oblek; in ti bodo hodili z menoj v belem, kajti vredni so.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kdor premaga, ta isti bo oblečen v belo oblačilo in njegovega imena ne bom izbrisal iz knjige življenja, temveč bom njegovo ime priznal pred svojim Očetom in pred njegovimi angeli.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '»In angelu cerkve v Filadelfiji piši: ›Te besede govori tisti, ki je svét, tisti, ki je resničen, tisti, ki ima Davidov ključ, tisti, ki odpira in noben človek ne zapira; in zapira, pa noben človek ne odpira.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Poznam tvoja dela. Glej, pred teboj sem postavil odprta vrata in noben človek jih ne more zapreti, kajti majhno moč imaš in ohranil si mojo besedo in nisi zanikal mojega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Glej, prisilil bom te, iz Satanove shodnice, ki pravijo, da so Judje, pa niso, temveč lažejo; glej, prisilil jih bom, da pridejo in obožujejo pred tvojimi stopali in da spoznajo, da sem te vzljubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ker si ohranil besedo moje potrpežljivosti, bom tudi jaz tebe obvaroval pred uro preizkušnje, ki bo prišla nad ves svet, da preizkusi tiste, ki prebivajo na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Glej, pridem hitro. Trdno drži to, kar imaš, da ti noben človek ne odvzame tvoje krone.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Tistega, ki premaga, bom naredil [za] steber v templju svojega Boga in ne bo več šel ven; in nanj bom napisal ime svojega Boga in ime mesta svojega Boga, ki je novi Jeruzalem, ki prihaja dol z neba od mojega Boga in nanj bom napisal svoje novo ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, '»In angelu cerkve Laodikejcev piši: ›Te besede govori Amen, zvesta in resnična priča, začetek Božjega stvarstva;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'poznam tvoja dela, da nisi niti mrzel niti vroč. Želim si, da bi bil mrzel ali vroč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Zaradi tega, ker si mlačen in nisi niti mrzel niti vroč, te bom izpljunil iz svojih ust.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ker praviš: ›Bogat sem in okrepil sem se z dobrinami in ne potrebujem ničesar;‹ pa ne veš, da si pomilovanja vreden in beden in reven in slep ter nag,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'ti svetujem, da kupiš od mene zlata, prečiščenega v ognju, da boš lahko bogat in belo oblačilo, da boš lahko oblečen in da se ne prikaže sramota tvoje nagote in svoje oči mazili z mazilom za oči, da boš lahko videl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, '§ Kolikor jih imam rad, oštevam in karam. Bodi torej goreč in se pokesaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Glej, stojim pred vrati in trkam. Če katerikoli človek sliši moj glas in odpre vrata, bom vstopil k njemu in bom večerjal z njim in on z menoj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Tistemu, ki premaga, bom zagotovil, da sede z menoj na moj prestol, celo kakor sem tudi sam zmagal in sem s svojim Očetom poseden na njegovem prestolu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potem sem pogledal in glej, vrata na nebu so bila odprta in prvi glas, ki sem ga zaslišal, je bil, kakor bi bil od trobente, govoreče z menoj, ki je rekel: »Pridi sèm gor in pokazal ti bom stvari, ki morajo biti odslej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'In takoj sem bil v duhu in glej, prestol je bil postavljen v nebesih in nekdo je sedel na prestolu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'In tisti, ki je sedel, je bil videti podoben kamnu jaspisu in sardiju in naokoli prestola je bila mavrica, na pogled podobna smaragdu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'In naokoli prestola je bilo štiriindvajset prestolov in na prestolih sem videl sedeti štiriindvajset starešin, oblečenih v bela oblačila in na svojih glavah so imeli zlate krone.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, '§ In pred prestolom so izvirali bliski in grmenja ter glasovi; in pred prestolom je bilo sedem gorečih ognjenih svetilk, ki so sedem Božjih Duhov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'In pred prestolom je bilo stekleno morje, podobno kristalu; in v sredini prestola in naokoli prestola so bile štiri živali, spredaj in zadaj polne oči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'In prva žival je bila podobna levu in druga žival podobna teletu in tretja žival je imela obraz kakor človek, četrta žival pa je bila podobna letečemu orlu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'In štiri živali so imele vsaka izmed njih okoli sebe po šest peruti in znotraj so bile polne oči; in niso počivale dan in noč, rekoč: »Svet, svet, svet, Gospod Bog Vsemogočni, ki je bil in je in ki pride.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'In ko so te živali dale slavo in čast in zahvalo njemu, ki je sedel na prestolu, ki živi na veke vekov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'je štiriindvajset starešin padlo dol pred njim, ki je sedel na prestolu in oboževalo njega, ki živi na veke vekov in svoje krone vrglo pred prestol, rekoč:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '»Vreden si, oh Gospod, da prejmeš slavo in čast ter moč, kajti ustvaril si vse stvari in zaradi tvojega zadovoljstva so in so bile ustvarjene.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'In v desnici njega, ki je sedèl na prestolu, sem videl knjigo, popisano znotraj in na zadnji strani, zapečateno s sedmimi pečati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'In videl sem krepkega angela razglašati z močnim glasom: »Kdo je vreden, da odpre knjigo in da odtrga njene pečate?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'In nihče na nebu niti na zemlji niti pod zemljo, ni bil zmožen, da odpre knjigo niti, da pogleda nanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'In zelo sem jokal, ker se ni našel nihče vreden, da odpre in da bere knjigo niti, da pogleda nanjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'In eden izmed starešin mi reče: »Ne jokaj; glej, Lev iz Judovega rodu, Davidova Korenina, je prevladal, da odpre knjigo in da razveže njenih sedem pečatov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, '§ In pogledal sem in glej, na sredini prestola in štirih živali in sredi starešin je stalo Jagnje, kot bi bilo zaklano in je imelo sedem rogov in sedem oči, ki so sedem Božjih Duhov, poslanih po vsej zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'In prišlo je ter vzelo knjigo iz desnice tistega, ki je sedel na prestolu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'In ko je vzelo knjigo, so štiri živali in štiriindvajset starešin padli dol pred Jagnjetom in vsi izmed njih so imeli harfe in zlate stekleničke, polne dišav, ki so molitve svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'In peli so novo pesem, rekoč: »Vredno si, da vzameš to knjigo in da odpreš njene pečate; kajti bilo si umorjeno in s svojo krvjo si nas odkupilo Bogu izmed vsakega sorodstva in jezika in ljudstva in naroda');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, '§ in si nas naredilo [za] kralje in duhovnike pri našemu Bogu, in mi bomo kraljevali na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'In zagledal sem in zaslišal glas mnogih angelov naokoli prestola in živali in starešin, in njihovo število je bilo desettisočkrat deset tisoč in tisočev tisoči,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, '§ ki so z močnim glasom govorili: »Vredno je Jagnje, ki je bilo zaklano, da prejme oblast in bogastva in modrost in moč in čast in slavo in blagoslov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, '§ In vsako ustvarjeno bitje, ki je na nebu in na zemlji in pod zemljo in takšna, kot so v morju in vse, ki so v njem, sem slišal govoriti: »Blagoslov in čast in slava in oblast naj bo njemu, ki sedi na prestolu in Jagnjetu na veke vekov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, '§ In štiri živali so rekle: »Amen.« In štiriindvajset starešin je padlo dol in oboževalo tistega, ki živi na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'In potem sem videl, ko je Jagnje odprlo enega izmed pečatov in slišal sem, kakor bi bil hrup grmenja, eno izmed štirih živali govoriti: »Pridi in poglej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'In videl sem ter zagledal belega konja; in tisti, ki je sedel na njem, je imel lok in dana mu je bila krona in odšel je naprej zmagovat in da zmaga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'In ko je odprlo drugi pečat, sem zaslišal drugo žival reči: »Pridi in poglej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, '§ In odšel je drug konj, ki je bil rdeč; in tistemu, ki je sedel na njem, je bila dana oblast z zemlje odvzeti mir in da naj bi drug drugega klali, in dan mu je bil velik meč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'In ko je odprlo tretji pečat, sem zaslišal tretjo žival reči: »Pridi in poglej.« In pogledal sem in glej črn konj; in tisti, ki je sedel na njem, je imel v svoji roki tehtnico.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'In zaslišal sem glas na sredini med štirimi živalmi reči: »Mera pšenice za kovanec in tri mere ječmena za kovanec; in glej, [da] ne škoduješ olju in vinu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'In ko je odprlo četrti pečat, sem zaslišal glas četrte živali reči: »Pridi in poglej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, '§ In pogledal sem in zagledal konja mrtvaško blede barve; in tistemu, ki je sedel na konju, je bilo ime Smrt in Pekel je sledil za njim. In izročena jima je bila oblast nad četrtino zemlje, da ubijata z mečem in z lakoto in s smrtjo in z zemeljskimi živalmi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'In ko je odprlo peti pečat, sem videl pod oltarjem duše teh, ki so bili zaklani zaradi Božje besede in zaradi pričevanja, ki so ga imeli');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'in z močnim glasom so vpili, rekoč: »Doklej, oh Gospod, svét in resničen, ne boš sodil in maščeval naše krvi na teh, ki prebivajo na zemlji?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, '§ In vsakemu izmed njih so bila dana bela svečana oblačila in rečeno jim je bilo, da naj še za kratek čas počivajo, dokler se ne bi izpolnili tudi njihovi soslužabniki in njihovi bratje, ki naj bi bili ubiti, kakor so bili oni sami.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'In gledal sem, ko je odprlo šesti pečat in glej, bil je velik potres, in sonce je postalo črno kakor vrečevina iz dlak in luna je postala kakor kri,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'in zvezde neba so popadale na zemljo, celo kakor figovo drevo odvrže svoje nezrele fige, ko ga stresa mogočen veter.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'In nebo je odšlo kakor zvitek pergamenta, ko je zvit skupaj, in vsaka gora in otok sta bila premaknjena s svojega mesta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Kralji zemlje, pomembni ljudje, bogataši, vrhovni poveljniki, mogočneži, vsak suženj in vsak prost človek pa so se skrili v brloge in v skale gorovij;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'in rekli so goram in skalam: »Padite na nas in nas skrijte pred obrazom njega, ki sedi na prestolu in pred Jagnjetovim besom,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, '§ kajti prišel je véliki dan njegovega besa in kdo bo zmožen obstati?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'In po teh stvareh sem zagledal štiri angele stati na štirih vogalih zemlje, ki so držali štiri vetrove zemlje, da veter ne bi pihal ne na zemljo, niti ne na morje, niti ne v nobeno drevo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'In videl sem drugega angela dvigovati se od vzhoda, ki je imel pečat živega Boga; in ta je z močnim glasom zaklical štirim angelom, ki jim je bilo dano, da škodujejo zemlji in morju,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'rekoč: »Ne škodujte zemlji niti morju niti drevesom, dokler ne zapečatimo služabnikov našega Boga na njihovih čelih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'In slišal sem število teh, ki so bili zapečateni. In zapečatenih je bilo sto štiriinštirideset tisoč izmed vseh rodov Izraelovih otrok.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Iz Judovega rodu je bilo zapečatenih dvanajst tisoč. Iz Rubenovega rodu je bilo zapečatenih dvanajst tisoč. Iz Gadovega rodu je bilo zapečatenih dvanajst tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Iz Aserjevega rodu je bilo zapečatenih dvanajst tisoč. Iz Neftálijevega rodu je bilo zapečatenih dvanajst tisoč. Iz Manásejevega rodu je bilo zapečatenih dvanajst tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Iz Simeonovega rodu je bilo zapečatenih dvanajst tisoč. Iz Lévijevega rodu je bilo zapečatenih dvanajst tisoč. Iz Isahárjevega rodu je bilo zapečatenih dvanajst tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Iz Zábulonovega rodu je bilo zapečatenih dvanajst tisoč. Iz Jožefovega rodu je bilo zapečatenih dvanajst tisoč. Iz Benjaminovega rodu je bilo zapečatenih dvanajst tisoč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, '§ Potem sem pogledal in glej, velika množica, ki je noben človek ne bi mogel prešteti, izmed vseh narodov in sorodstev in ljudi in jezikov, je stala pred prestolom in pred Jagnjetom, oblečena v bela svečana oblačila in [s] palmami v svojih rokah');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'in vpila z močnim glasom, rekoč: »Rešitev duš našemu Bogu, ki sedi na prestolu in Jagnjetu.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'In vsi angeli so stali naokrog prestola in okoli starešin in štirih živali in pred prestolom so padli na svoje obraze in oboževali Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, '§ rekoč: »Amen: ›Blagoslov, slava, modrost, zahvaljevanje, čast, oblast in moč bodi našemu Bogu na veke vekov. Amen.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, '§ In eden izmed starešin je odgovoril ter mi rekel: »Kaj so ti, ki so oblečeni v bela svečana oblačila? In od kod so prišli?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, '§ In rekel sem mu: »Gospod, ti veš.« In rekel mi je: »To so tisti, ki so prišli iz velike stiske in so oprali svoja svečana oblačila in jih pobelili v Jagnjetovi krvi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, '§ Zato so pred Božjim prestolom in v njegovem templju mu služijo dan in noč. In tisti, ki sedi na prestolu, bo prebival med njimi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ne bodo več lačni, niti ne več žejni, niti nanje ne bo svetilo sonce, niti nobena vročina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Kajti Jagnje, ki je v sredi prestola, jih bo paslo in jih vodilo k živim studencem vodá in Bog bo obrisal vse solze z njihovih oči.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'In ko je odprlo sedmi pečat, je bila na nebu kake pol ure tišina.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'In videl sem sedem angelov, ki so stali pred Bogom in tem je bilo danih sedem trobent.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'In prišel je drug angel in stal pred oltarjem, ki je imel zlato kadilnico in dano mu je bilo veliko kadila, da bi ga z molitvami vseh svetih daroval na zlatem oltarju, ki je bil pred prestolom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'In dim kadila, ki je prišel z molitvami svetih, se je iz angelove roke dvignil pred Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'In angel je vzel kadilnico in jo napolnil z ognjem z oltarja in jo vrgel v zemljo; in tam so bili glasovi, grmenja, bliski in potres.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'In sedem angelov, ki so imeli sedem trobent, se je pripravilo, da zatrobijo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, '§ Zatrobil je prvi angel in sledila sta toča in ogenj, pomešana s krvjo in bila sta vržena na zemljo, in zgorela je tretjina dreves in zgorela je vsa zelena trava.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'In zatrobil je drugi angel in kakor bi bila velika gora, ki je gorela z ognjem, vržena v morje, in tretjina morja je postala kri,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, '§ in tretjina ustvarjenih bitij, ki so bila v morju in so imela življenje, je poginila, in uničena je bila tretjina ladij.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'In zatrobil je tretji angel in z neba je padla velika zvezda, goreča, kot bi bila svetilka in ta je padla na tretjino rek in na studence vodá;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'in zvezda se je imenovala Pelin, in tretjina vodá je postala grenka; in mnogo ljudi je umrlo zaradi vodá, ker so postale grenke.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'In zatrobil je četrti angel in udarjena je bila tretjina sonca in tretjina lune in tretjina zvezd, tako kot bi njihova tretjina potemnela in dan ni sijal za svojo tretjino in prav tako noč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, '§ In gledal sem in slišal angela leteti po sredi neba, rekoč z močnim glasom: »Gorje, gorje, gorje prebivalcem zemlje zaradi preostalih glasov trobente treh angelov, ki bodo še zatrobili!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, '§ In zatrobil je peti angel in videl sem zvezdo pasti z neba na zemljo in dan mu je bil ključ od jame brez dna.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'In odprl je jamo brez dna in iz jame se je dvignil dim kakor dim velike talilne peči; in zaradi dima iz jame sta potemnela sonce in zrak.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'In iz dima so prišle na zemljo kobilice in dana jim je bila oblast, kakor imajo škorpijoni oblast na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'In naročeno jim je bilo, da naj ne bi škodili zemeljski travi niti nobeni zeleni stvari niti nobenemu drevesu, temveč samo tistim ljudem, ki na svojih čelih nimajo Božjega pečata.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'In dano jim je bilo, da naj jih ne bi pobijale, temveč da naj bi bili pet mesecev mučeni, in njihovo mučenje je bilo kakor mučenje škorpijona, ko piči človeka.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'In v tistih dneh bodo ljudje iskali smrt, pa je ne bodo našli; in želeli bodo umreti, smrt pa bo bežala od njih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'In oblika kobilic je bila podobna konjem, pripravljenim za boj; in na njihovih glavah so bile, kot bi bile krone podobne zlatu in njihovi obrazi so bili kakor človeški obrazi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'In imele so lase kakor ženski lasje in njihovi zobje so bili kakor levji zobje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'In imele so prsne oklepe, kot bi bili prsni oklepi iz železa; in zvok njihovih peruti je bil kakor zvok bojnih voz z mnogimi konji, drvečimi v boj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'In imele so repe kot škorpijoni in na njihovih repih so bila žela; in njihova oblast je bila pet mesecev škoditi ljudem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'In nad seboj so imele kralja, ki je angel iz jame brez dna, katerega ime je v hebrejskem jeziku Ábadon, toda v grškem jeziku ima svoje ime Apolíon.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Eno gorje je minilo, in glej, zatem pride še dvoje gorje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'In zatrobil je šesti angel in od zlatega oltarja, ki je pred Bogom, sem zaslišal glas iz štirih rogov,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'rekoč šestemu angelu, ki je imel trobento: »Odveži štiri angele, ki so zvezani v veliki reki Evfrat.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'In štirje angeli, ki so bili pripravljeni na to uro in dan in mesec in leto, so bili odvezani, da pobijejo tretjino ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'In število vojske jezdecev je bilo dvesto milijonov; in slišal sem njihovo število.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, '§ In tako sem v videnju videl konje in te, ki so sedeli na njih, da imajo prsni oklepi [barvo] ognja in hijacinta ter žvepla; in glave konj so bile kakor levje glave, in iz njihovih ust so prihajali ogenj in dim in žveplo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Od teh treh je bila tretjina ljudi ubita z ognjem, z dimom in z žveplom, ki so prihajali iz njihovih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Kajti njihova oblast je v njihovih ustih in v njihovih repih, kajti njihovi repi so bili podobni kačam in imeli so glave in z njimi škodujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, '§ In preostali izmed ljudi, ki niso bili pobiti s temi nadlogami, se še niso pokesali od del svojih rok, da ne bi oboževali hudičev, zlatih malikov, srebrnih in bronastih, kamnitih in lesenih, ki niti ne morejo videti, niti slišati, niti hoditi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'niti se niso pokesali od svojih umorov, niti od svojih čarodejstev, niti od svojih prešuštvovanj, niti od svojih tatvin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'In videl sem drugega mogočnega angela priti dol z neba, oblečenega z oblakom, in nad njegovo glavo je bila mavrica in njegov obraz je bil, kakor bi bil sonce in njegova stopala kakor ognjeni stebri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'In v svoji roki je imel odprto majhno knjigo; in svoje desno stopalo je postavil na morje, svoje levo stopalo pa na zemljo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'ter zavpil z močnim glasom, kot kadar rjove lev. In ko je zavpil, je sedem gromov izustilo svoje glasove.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'In ko je sedem gromov izustilo svoje glasove, sem bil na tem, da napišem. Zaslišal pa sem glas iz nebes, ki mi je rekel: »Zapečati te besede, ki jih je spregovorilo sedem gromov in jih ne zapiši.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'In angel, ki sem ga videl stati na morju in na zemlji, je svojo roko vzdignil k nebu');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'in prisegel pri njem, ki živi na veke vekov, ki je ustvaril nebo in stvari, ki so na njem in zemljo in stvari, ki so na njej in morje in stvari, ki so v njem, da naj ne bi bilo več časa,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'toda v dneh glasu sedmega angela, ko bo ta začel trobiti, naj bi se dokončala Božja skrivnost, kakor jo je razglasil svojim služabnikom prerokom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'In glas, ki sem ga slišal z neba, mi je ponovno spregovoril ter rekel: »Pojdi in vzemi majhno knjigo, ki je odprta v roki angela, ki stoji na morju in na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'In odšel sem k angelu ter mu rekel: »Daj mi majhno knjigo.« In rekel mi je: »Vzemi jo in jo pojej, in tvoj trebuh bo naredila grenek, toda v tvojih ustih bo sladka kakor med.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'In iz angelove roke sem vzel majhno knjigo in jo pojedel in v mojih ustih je bila sladka kakor med in takoj, ko sem jo pojedel, je bil moj trebuh grenek.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'In rekel mi je: »Ponovno moraš prerokovati pred mnogimi ljudmi, narodi, jeziki in kralji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, '§ In dan mi je bil trst, podoben palici in angel je stal, rekoč: »Vstani in izmeri Božji tempelj in oltar in te, ki v njem obožujejo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Toda dvor, ki je zunaj templja, izpusti in ga ne izmeri, kajti dan je poganom in dvainštirideset mesecev bodo pod stopali pohojali sveto mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'In svojima dvema pričama bom dal oblast in prerokovala bosta tisoč dvesto in šestdeset dni, oblečeni v vrečevino.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'To sta dve oljki in dva svečnika, ki stojita pred Bogom zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'In če jima bo katerikoli človek škodil, iz njunih ust izide ogenj in požre njune sovražnike. Če pa ju bo katerikoli človek poškodoval, mora biti na ta način ubit.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ta [dva] imata oblast, da zapreta nebo, da v dneh njunega prerokovanja ne dežuje in oblast imata nad vodami, da jih spremenita v kri, zemljo pa udarita z vsemi nadlogami, tako pogosto, kakor hočeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'In ko bosta končala svoje pričevanje, se bo iz jame brez dna povzpel zvernik, ki bo povzročil vojno proti njima in ju premagal ter ju ubil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Njuni trupli pa bosta ležali na ulici velikega mesta, ki se mu duhovno reče Sódoma in Egipt, kjer je bil križan tudi naš Gospod.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'In tisti izmed ljudi in sorodstev in jezikov in narodov bodo tri dni in pol gledali njuni trupli in ne bodo pustili, da bi bili njuni trupli položeni v grobova.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'In tisti, ki prebivajo na zemlji, se bodo veselili nad njima in se zabavali ter bodo drug drugemu pošiljali darila, ker sta ta dva preroka mučila te, ki prebivajo na zemlji.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Po treh dneh in pol pa je vanju vstopil Duh življenja od Boga in vstala sta na svoja stopala in na te, ki so ju videli, je padel velik strah.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'In zaslišala sta močan glas z neba, ki jima je rekel: »Pridita sèm gor.« In v oblaku sta se vzpela do neba, njuni sovražniki pa so ju gledali.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'In isto uro je bil tam velik potres in padel je deseti del mesta in v potresu jih je bilo izmed ljudi umorjenih sedem tisoč; preostanek pa je bil zgrožen in dal slavo Bogu nebes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Drugo gorje je minilo in glej, hitro pride tretje gorje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, '§ In zatrobil je sedmi angel in na nebu so bili močni glasovi, govoreč: »Kraljestva tega sveta so postala kraljestva našega Gospoda in njegovega Kristusa in vladal bo na veke vekov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'In štiriindvajset starešin, ki so na svojih sedežih sedeli pred Bogom, je padlo na svoje obraze ter oboževalo Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, '§ rekoč: »Zahvaljujemo se ti, oh Gospod Bog Vsemogočni, ki si in si bil in boš prišel, ker si si vzel svojo veliko oblast in si zakraljeval.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'In narodi so bili jezni in prišel je tvoj bes in čas mrtvih in da bi jim bilo sojeno in da bi dal nagrado svojim služabnikom prerokom in svetim ter tem, ki se bojijo tvojega imena, majhnim in velikim, in da bi uničil te, ki uničujejo zemljo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'In na nebu se je odprl Božji tempelj in v njegovem templju je bilo videti skrinjo njegove zaveze; in bili so bliski in glasovi in grmenja in potres in velika toča.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'In na nebu se je prikazalo veliko znamenje; ženska, oblečena s soncem in luna pod njenimi stopali in krona dvanajsterih zvezd na njeni glavi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'In ona, ki je bila z otrokom, je vpila v porodnih mukah in bolečinah, da bi rodila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'In na nebu se je prikazalo drugo znamenje in glej, velik rdeč zmaj, ki je imel sedem glav in deset rogov ter na njegovih glavah sedem kron.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'In njegov rep je potegnil z neba tretjino zvezd ter jih vrgel na zemljo in zmaj je stal pred žensko, ki je bila pripravljena, da rodi, da bi požrl njenega otroka takoj, ko bi se rodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'In rodila je fantka, ki je bil [namenjen], da vsem narodom vlada z železno palico in njen otrok je bil vzet k Bogu in k njegovemu prestolu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'In ženska je pobegnila v divjino, kjer je imela prostor, pripravljen od Boga, da naj bi jo tam hranili tisoč dvesto in šestdeset dni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'In bila je vojna v nebesih. Mihael in njegovi angeli so se bojevali proti zmaju in zmaj se je bojeval ter njegovi angeli,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'pa niso prevladali niti se na nebu zanje ni več našel prostor.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'In véliki zmaj je bil vržen ven, ta stara kača, imenovana hudič in Satan, ki zavaja ves svet. Izgnan je bil na zemljo in njegovi angeli so bili izgnani z njim.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'In na nebu sem zaslišal močan glas, rekoč: »Sedaj je prišla rešitev duš in moč in kraljestvo našega Boga in oblast njegovega Kristusa, kajti vržen je dol obtoževalec naših bratov, ki jih je dan in noč obtoževal pred našim Bogom.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'In oni so ga premagali s krvjo Jagnjeta in z besedo svojega pričevanja in svojih življenj niso ljubili do smrti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Zato se veselite, ve nebesa in vi, ki prebivate v njih. Gorje prebivalcem zemlje in morja! Kajti hudič je prišel dol k vam, zelo ogorčen, ker ve, da ima le malo časa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'In ko je zmaj videl, da je bil vržen na zemljo, je preganjal žensko, ki je rodila moško dete.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'In ženski sta bili dani dve peruti velikega orla, da bi lahko odletela v divjino, na njen kraj, kjer je bila hranjena čas in čase in polovico časa, proč od obraza kače.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'In kača je iz svojih ust vrgla za žensko vodo kot poplavo, da bi lahko povzročila, da jo poplava odnese.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'In zemlja je pomagala ženski in zemlja je odprla svoja usta ter požrla poplavo, ki jo je zmaj vrgel iz svojih ust.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'In zmaj je bil ogorčen proti ženski in odšel, da povzroči vojno proti preostanku njenega potomstva, ki se drži Božjih zapovedi in ima pričevanje Jezusa Kristusa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, '§ In stal sem na morskem pesku in videl zvernika dvigniti se iz morja, ki je imel sedem glav ter deset rogov in na svojih rogovih deset kron in na svojih glavah bogokletno ime.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'In zvernik, ki sem ga videl, je bil podoben leopardu in njegova stopala so bila kakor medvedja stopala in njegova usta kakor levja usta. In zmaj mu je dal svojo moč in svoj prestol ter veliko oblast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'In videl sem eno izmed njegovih glav, kot bi bila ranjena do smrti in njegova smrtna rana je bila ozdravljena in ves svet se je spraševal o zverniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'In oboževali so zmaja, ki je dal oblast zverniku in oboževali so zvernika, rekoč: »Kdo je podoben zverniku? Kdo se je zmožen bojevati z njim?«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'In dana so mu bila usta, ki so govorila velike stvari ter bogokletja in dana mu je bila oblast, da nadaljuje dvainštirideset mesecev.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'In svoja usta je odprl v bogokletju proti Bogu, da preklinja njegovo ime in njegovo šotorsko svetišče in te, ki prebivajo v nebesih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'In dano mu je bilo, da se vojskuje s svetimi in da jih premaga in dana mu je bila oblast nad vsemi sorodstvi in jeziki in narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'In oboževali ga bodo vsi, ki prebivajo na zemlji, katerih imena že od ustanovitve sveta niso zapisana v knjigi življenja zaklanega Jagnjeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Če ima katerikoli človek uho, naj sliši.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, '§ Kdor vodi v ujetništvo, bo šel v ujetništvo. Kdor ubija z mečem, mora biti ubit z mečem. Tukaj je potrpežljivost in vera svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'In zagledal sem še enega zvernika prihajati gor iz zemlje in imel je dva rogova, podobna jagnjetovim, govoril pa je kakor zmaj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'In izvajal je vso oblast prvega zvernika pred njim in povzroča zemlji in tistim, ki prebivajo na njej, da obožujejo prvega zvernika, katerega smrtna rana se je pozdravila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'In dela velike čudeže, tako da naredi pred očmi ljudi, da pride ogenj z neba na zemljo');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'in zavaja te, ki prebivajo na zemlji, s pomočjo teh čudežev, za katere je imel oblast, da jih je delal pred očmi zvernika, rekoč tistim, ki prebivajo na zemlji, da bi morali narediti podobo zvernika, ki je imel rano od meča in je oživel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'In imel je moč, da dá življenje podobi zvernika, da naj bi podoba zvernika tako govorila kakor povzročila, da naj bi bili pobiti vsi, ki ne bi oboževali podobe zvernika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'In povzroči vsem, tako malim kakor velikim, bogatim in revnim, svobodnim in sužnjem, da sprejmejo znamenje v svojo desnico ali v svoja čela');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'in da noben človek ne bi smel kupovati ali prodajati, razen, kdor je imel znamenje ali ime zvernika ali število njegovega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tukaj je modrost. Naj tisti, ki ima razum, prešteje število zvernika; kajti to je število človeka in njegovo število je šeststo šestinšestdeset.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, '§ In pogledal sem in glej, Jagnje je stalo na gori Sion in z njim sto štiriinštirideset tisoč [tistih], ki so imeli na svojih čelih napisano ime njihovega Očeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'In zaslišal sem glas z neba, kakor glas mnogih vodá in kakor glas velikega groma in slišal sem glas harfistov igrati s svojimi harfami');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'in peli so, kakor bi bila to nova pesem, pred prestolom in pred štirimi živalmi in starešinami in noben človek se ni mogel naučiti te pesmi razen sto štiriinštiridesetih tisočev, ki so bili odkupljeni z zemlje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'To so tisti, ki niso bili omadeževani z ženskami, kajti deviški so. To so tisti, ki sledijo Jagnjetu, kamorkoli gre. Ti so bili odkupljeni izmed ljudi, so prvi sadovi Bogu in Jagnjetu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, '§ In v njihovih ustih ni bilo najti zvijače, kajti pred Božjim prestolom so brez krivde.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'In videl sem drugega angela leteti po sredi neba, ki je imel večen evangelij, da ga oznani tem, ki prebivajo na zemlji in vsakemu narodu, sorodstvu, jeziku in ljudem,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'govoreč z močnim glasom: »Bojte se Boga in dajte mu slavo, kajti prišla je ura njegove sodbe; in obožujte njega, ki je naredil nebo in zemljo in morje ter studence vodá.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'In sledil je še en angel, govoreč: » [Metropola] Babilon je padla, padla je, ta velika metropola, zato ker je vse narode prisilila piti od vina besa svojega prešuštvovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'In tema je sledil še tretji angel, govoreč z močnim glasom: »Če katerikoli človek obožuje zvernika in njegovo podobo ter v svoje čelo ali v svojo roko sprejme njegovo znamenje,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, '§ bo ta isti pil od vina Božjega besa, ki je brez mešanja izlit v čašo njegovega ogorčenja in v prisotnosti svetih angelov in v Jagnjetovi prisotnosti bo mučen z ognjem in žveplom');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'in dim njihovega mučenja se vzpenja na veke vekov in ne podnevi ne ponoči nima počitka, kdor obožuje zvernika ter njegovo podobo in kdorkoli sprejme znamenje njegovega imena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tukaj je potrpežljivost svetih; tukaj so tisti, ki se držijo Božjih zapovedi in Jezusove vere.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'In zaslišal sem glas z neba, ki mi je rekel: »Zapiši: ›Blagoslovljeni so mrtvi, ki odslej umrejo v Gospodu.‹ ›Da,‹ govori Duh, ›da se lahko odpočijejo od svojih naporov; in njihova dela jim sledijo.‹«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'In pogledal sem ter zagledal bel oblak in na oblaku sedeti nekoga, podobnega Sinu človekovemu, ki ima na svoji glavi zlato krono in v svoji roki oster srp.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'In iz templja je prišel drug angel in tistemu, ki je sedel na oblaku, je z močnim glasom zaklical: »Zamahni s svojim srpom in požanji, kajti zate je prišel čas, da žanješ; kajti žetev zemlje je dozorela.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'In tisti, ki je sedèl na oblaku, je s svojim srpom zamahnil po zemlji in zemlja je bila požeta.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'In drug angel je prišel iz templja, ki je v nebesih, ki je tudi imel oster srp.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'In drug angel je prišel od oltarja, ki je imel oblast nad ognjem in z glasnim krikom je zaklical tistemu, ki je imel oster srp, rekoč: »Zamahni s svojim ostrim srpom in zberi zemeljske trtne grozde, kajti njeno grozdje je popolnoma dozorelo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'In angel je s svojim srpom zamahnil po zemlji in zbral vino zemlje in ga vrgel v veliko vinsko stiskalnico Božjega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'In vinska stiskalnica je bila pohojana zunaj mesta in iz vinske stiskalnice je prišla kri, celó konjem do uzd, tisoč in šeststo dolžin brazd daleč.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'In na nebu sem videl drugo znamenje, veliko in čudovito, sedem angelov, ki so imeli sedem zadnjih nadlog, kajti z njimi je dopolnjen Božji bes.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'In videl sem, kot bi bilo stekleno morje, pomešano z ognjem; in ti, ki so dosegli zmago nad zvernikom in nad njegovo podobo in nad njegovim znamenjem in nad številom njegovega imena, so z Božjimi harfami stali na steklenem morju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'In peli so pesem Božjega služabnika Mojzesa in Jagnjetovo pesem, rekoč: »Velika in čudovita so tvoja dela, Gospod Bog Vsemogočni; tvoje poti so pravične in resnične, ti Kralj svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kdo se te ne bi bal, oh Gospod in ne proslavil tvojega imena? Kajti samo ti si svet, kajti vsi narodi bodo prišli in oboževali pred teboj, kajti tvoje sodbe so postale očitne.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'In nató sem pogledal in glej, tempelj šotorskega svetišča pričevanja v nebesih je bil odprt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'In iz templja je prišlo sedem angelov, ki so imeli sedem nadlog, oblečenih v čisto in belo platno in preko prsi, opasanih z zlatimi pasovi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'In ena izmed štirih živali je dala sedmim angelom sedem zlatih stekleničk, polnih besa Boga, ki živi na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, '§ In tempelj je bil napolnjen z dimom od Božje slave in od njegove moči in noben človek ni bil sposoben vstopiti v tempelj, dokler se ne bi izpolnile sedmere nadloge sedmih angelov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'In iz templja sem zaslišal močan glas, ki je sedmim angelom rekel: »Pojdite po svojih poteh in na zemljo izlijte stekleničke Božjega besa.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'In odšel je prvi in svojo stekleničko izlil na zemljo; in na ljudi, ki so imeli znamenje zvernika in na tiste, ki so oboževali njegovo podobo, je padlo ogabno in boleče vnetje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'In drugi angel je svojo stekleničko izlil na morje in postalo je kakor kri mrtvega človeka in vsaka živa duša v morju je umrla.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'In tretji angel je svojo stekleničko izlil v reke in studence vodá; in postale so kri.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'In slišal sem reči angela vodá: »Ti si pravičen, oh Gospod, ki si in si bil in boš, ker si tako sodil.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Kajti prelili so kri svetih in prerokov in dal si jim piti kri, kajti zaslužili so.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'In od oltarja sem nekoga slišal reči: »Točno tako, Gospod Bog Vsemogočni, resnične in pravične so tvoje sodbe.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'In četrti angel je svojo stekleničko izlil na sonce in dana mu je bila oblast, da z ognjem žge ljudi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'In ljudje so bili žgani z veliko vročino in izrekali bogokletje proti imenu Boga, ki ima oblast nad temi nadlogami, pa se niso pokesali, da bi mu dali slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'In peti angel je svojo stekleničko izlil na zvernikov prestol in njegovo kraljestvo je bilo polno teme in zaradi bolečine so si grizli svoje jezike');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'in zaradi svojih bolečin in svojih vnetij so izrekali bogokletje proti Bogu nebes in se niso pokesali od svojih dejanj.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'In šesti angel je svojo stekleničko izlil na veliko reko Evfrat in njena voda se je posušila, da bi se lahko pripravila pot kraljem z vzhoda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'In videl sem iz ust zmaja in iz ust zvernika ter iz ust lažnega preroka priti tri nečiste duhove, podobne žabam.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Kajti to so duhovi hudičev, ki delajo čudeže, ki gredo do kraljev zemlje celotnega sveta, da jih zberejo na bitko tistega vélikega dne Boga Vsemogočnega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '»Glej, pridem kakor tat. Blagoslovljen je, kdor straži in obdrži svoje obleke, da ne bi hodil nag in bi videli njegovo sramoto.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'In zbral jih je skupaj na kraju, v hebrejskem jeziku imenovanem Harmagedón.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'In sedmi angel je svojo stekleničko izlil v zrak in iz nebeškega templja je prišel od prestola močan glas, rekoč: »Narejeno je.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'In tam so bili glasovi in gromi in bliski in bil je velik potres, kakršnega še ni bilo, odkar so bili na zemlji ljudje, tako mogočen potres in tako velik.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'In veliko mesto je bilo razdeljeno na tri dele in mesta narodov so se podrla in vélika [metropola] Babilon je prišla v spomin pred Boga, da ji da čašo vina okrutnosti svojega besa.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'In vsak otok je zbežal proč in gorá ni bilo najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'In z neba je padala na ljudi velika toča, vsak kamen težak okoli talent in ljudje so zaradi nadloge toče izrekali bogokletje proti Bogu; kajti nadloga od tega je bila silno velika.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'In prišel je eden izmed sedmih angelov, ki so imeli sedem stekleničk in govoril z menoj ter mi rekel: »Pridi sèm, pokazal ti bom sodbo vélike vlačuge, ki sedi nad mnogimi vodami,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 's katero so kralji zemlje zagrešili prešuštvovanje, prebivalci zemlje pa so bili opiti z vinom njenega prešuštvovanja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Tako me je v duhu odvedel proč v divjino in videl sem žensko sedeti na škrlatno obarvanem zverniku, polnem imen bogokletstev, ki je imel sedem glav in deset rogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'In ženska je bila oblečena v vijolično in škrlatno [rdečo] barvo in odeta z zlatom in dragocenimi kamni in biseri in v svoji roki je imela zlato čašo polno ogabnosti in umazanosti svojega prešuštvovanja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'in na njenem čelu je bilo napisano ime: SKRIVNOST, VÉLIKA [METROPOLA] BABILON, MATI POCESTNIC IN OGABNOSTI ZEMLJE.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'In videl sem žensko, pijano s krvjo svetih in s krvjo Jezusovih mučencev in ko sem jo zagledal, sem se čudil z veliko osuplostjo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Angel pa mi je rekel: »Zakaj se čudiš? Povedal ti bom skrivnost ženske in zvernika, ki jo prenaša, ki ima sedem glav in deset rogov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Zvernik, ki si ga videl, je bil in ga ni in vzpel se bo iz jame brez dna in šel v pogubo in tisti, ki prebivajo na zemlji, katerih imena od ustanovitve sveta niso bila zapisana v knjigi življenja, se bodo čudili, ko bodo gledali zvernika, ki je bil in ga ni, pa vendar je.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'In tukaj je um, ki ima modrost. Sedem glav je sedem gorá, na katerih sedi ženska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'In tam je sedem kraljev; pet je padlih in eden je, drugi pa še ni prišel; ko pa pride, mora kratek čas nadaljevati.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Zvernik pa, ki je bil in ga ni, je celó osmi in je izmed sedmih in gre v pogubo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'In deset rogov, ki si jih videl, je deset kraljev, ki doslej še niso prejeli kraljestva, toda kot kralji prejmejo oblast z zvernikom za eno uro.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ti imajo en um, svojo oblast in moč pa bodo dali zverniku.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ti se bodo vojskovali z Jagnjetom, Jagnje pa jih bo premagalo, kajti on je Gospod gospodov in Kralj kraljev in tisti, ki so z njim, so poklicani in izbrani in zvesti.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'In rekel mi je: »Te vode, ki jih vidiš, kjer sedi vlačuga, so ljudje in množice in narodi in jeziki.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, '§ In deset rogov, ki si jih videl na zverniku, ti bodo sovražili vlačugo in naredili jo bodo opustošeno in nago in jedli bodo njeno meso ter jo sežgali z ognjem.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Kajti Bog je na njihova srca položil, da izpolnijo njegovo voljo in da se strinjajo in svoje kraljestvo izročijo zverniku, dokler ne bodo izpolnjene Božje besede.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Ženska pa, ki si jo videl, je to veliko mesto, ki kraljuje nad kralji zemlje.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'In po teh stvareh sem videl drugega angela priti dol z neba, ki je imel veliko oblast in zemlja je bila razsvetljena z njegovo slavo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'In mogočno je vpil z močnim glasom, rekoč: »Vélika [metropola] Babilon je padla, padla je in postala prebivališče hudičev in ječa vsakega nečistega duha in kletka vsake nečiste in osovražene ptice.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, '§ Kajti vsi narodi so pili od vina besa njenega prešuštvovanja in kralji zemlje so z njo zagrešili prešuštvovanje in trgovci zemlje so obogateli od obilja njenih poslastic.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'In zaslišal sem drug glas z neba, rekoč: »Pridite iz nje, moji ljudje, da ne boste soudeleženi z njenimi grehi in da ne prejmete od njenih nadlog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Kajti njeni grehi so segli do neba in Bog se je spomnil njenih krivičnosti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Nagradite jo, kakor vas je sama nagradila in podvojite ji dvojno glede na njena dela; v čašo, ki jo je napolnila, ji napolnite dvojno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Kolikor je samo sebe slavila in slastno živela, toliko muk in bridkosti ji dajte, kajti v svojem srcu pravi: ›Sedim kraljica in nisem vdova in ne bom videla bridkosti.‹');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Zatorej bodo njene nadloge prišle v enem dnevu; smrt in žalovanje in lakota in popolnoma bo požgana z ognjem, kajti močan je Gospod Bog, ki jo sodi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'In kralji zemlje, ki so zagrešili prešuštvovanje in z njo slastno živeli, jo bodo objokovali in žalovali za njo, ko bodo videli dim njenega gorenja,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'stoječ daleč stran zaradi strahu pred njenim mučenjem, rekoč: »Ojoj, ojoj, ta vélika metropola Babilon, ta mogočna metropola! Kajti v eni uri je prišla tvoja sodba.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'In trgovci zemlje bodo jokali in žalovali nad njo, kajti noben človek ne kupuje več njihovega trgovskega blaga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'trgovskega blaga iz zlata in srebra in dragocenih kamnov in iz biserov in tankega lanenega platna in bagra in svile in škrlata in vsakega dišečega lesa in vseh vrst posod iz slonovine in vseh vrst posod iz najdragocenejšega lesa in iz brona in železa in marmorja');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, '§ in cimeta in dišav in mazil in kadil in vina in olja in fine moke in pšenice in živali in ovc in konj in bojnih vozov in sužnjev in človeških duš.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, '§ In sadeži, po katerih je hlepela tvoja duša, so odšli od tebe in vse stvari, ki so bile okusne in lepe, so odšle od tebe in sploh jih ne boš več našel.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Trgovci s temi stvarmi, ki so po njej obogateli, bodo zaradi strahu pred njenimi mukami stali daleč stran ter jokali in tarnali');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'in govorili: »Ojoj, ojoj, ta vélika metropola, ki je bila oblečena v tanko laneno platno in bager in škrlat in odeta z zlatom in dragocenimi kamni in biseri!');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, '§ Kajti v eni uri pridejo v nič tako velika bogastva.« In vsak kapitan in vse spremstvo na ladjah in mornarji in kolikor jih trguje po morju, so stali daleč stran');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'in ko so zagledali dim njenega gorenja, so vpili, rekoč: »Katero mesto je podobno tej véliki metropoli!«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, '§ In na svoje glave so metali prah in vpili, jokali in tarnali, rekoč: »Ojoj, ojoj, ta vélika metropola, v kateri so zaradi njene visoke cene postali bogati vsi, ki so imeli ladje na morju! Kajti v eni uri je postala opustošena.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Veselite se nad njo, ve nebesa in vi sveti apostoli ter preroki, kajti Bog vas je maščeval na njej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'In mogočen angel je pobral kamen, podoben velikemu mlinskemu kamnu in ga vrgel v morje, rekoč: »Tako bo ta vélika metropola Babilon z nasiljem zrušena in sploh je ne bo več najti.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'In v tebi se sploh ne bo več slišal zvok harfistov in glasbenikov in piskačev ter trobentačev in v tebi ne bo več najti nobenega rokodelca, katerekoli umetnosti je že in v tebi se sploh ne bo več slišal zvok mlinskega kamna');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'in v tebi sploh ne bo več svetila svetloba sveče in v tebi se sploh ne bo več slišal glas ženina in neveste, kajti tvoji trgovci so bili veliki možje zemlje, kajti s tvojimi čarodejstvi so bili zavedeni vsi narodi.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'In v njej je bila najdena kri prerokov in svetih in vseh, ki so bili zaklani na zemlji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'In po teh besedah sem zaslišal močan glas mnogih ljudi v nebesih, rekoč: »Aleluja. Rešitev duš in slava in čast ter oblast Gospodu, našemu Bogu,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'kajti njegove sodbe so resnične in pravične, kajti obsodil je véliko vlačugo, ki je s svojim prešuštvovanjem pokvarila zemljo in pri njeni roki je maščeval kri svojih služabnikov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'In ponovno so rekli: »Aleluja. In njen dim se je vzdigoval na veke vekov.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'In štiriindvajset starešin in četvero živali je padlo dol ter oboževalo Boga, ki je sedel na prestolu, rekoč: »Amen. Aleluja.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'In od prestola je prišel glas, rekoč: »Hvalíte našega Boga, vsi vi njegovi služabniki in vi, ki se ga bojite, oboji, mali in veliki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'In zaslišal sem, kakor bi bil glas velike množice in kakor glas mnogih vodá in kakor glas mogočnih grmenj, rekoč: »Aleluja, kajti kraljuje Gospod Bog vsegamogočni.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Bodimo veseli in veselimo se in dajmo mu čast, kajti prišla je Jagnjetova svatba in njegova žena se je pripravila.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'In zagotovljeno ji je bilo, da bi bila oblečena v tanko laneno platno, čisto in belo,« kajti tanko laneno platno je pravičnost svetih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'In rekel mi je: »Piši: ›Blagoslovljeni so tisti, ki so poklicani na Jagnjetovo poročno večerjo.‹« In rekel mi je: »To so resnični Božji izreki.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'In padel sem k njegovim stopalom, da ga obožujem. On pa mi je rekel: »Glej, ne stôri tega. Jaz sem tvoj soslužabnik in izmed tvojih bratov, ki imajo Jezusovo pričevanje. Obožuj Boga, kajti pričevanje o Jezusu je duh preroštva.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'In videl sem odprto nebo in glej, bel konj in kdor je sedel na njem, je bil imenovan Zvesti in Resnični in on v pravičnosti sodi ter se vojskuje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Njegove oči so bile kakor plamen ognja in na njegovi glavi je bilo mnogo kron in imel je napisano ime, ki ga ni poznal noben človek, razen njega samega.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'In oblečen je bil v suknjo, pomočeno v kri in njegovo ime se imenuje Božja Beseda.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'In vojske teh, ki so bile na nebu, so mu sledile na belih konjih, oblečene v tanko, belo in čisto laneno platno.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'In iz njegovih ust izhaja oster meč, da naj bi z njim udaril narode in vladal jim bo z železno palico in tlači vinsko stiskalnico okrutnosti in besa Vsemogočnega Boga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'In na svoji suknji in na svojem stegnu ima napisano ime: KRALJ KRALJEV IN GOSPOD GOSPODOV.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'In videl sem angela stati na soncu in ta je z močnim glasom zaklical, rekoč vsej perjadi, ki leti po sredi neba: »Pridite in zberite se skupaj k večerji vélikega Boga,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'da boste lahko jedle meso kraljev in meso častnikov in meso mogočnežev in meso konj in od teh, ki sedijo na njih in meso vseh ljudi, tako svobodnih kakor zasužnjenih, tako malih kakor velikih.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'In videl sem zvernika in kralje zemlje ter njihove vojske zbrane skupaj, da se vojskujejo proti njemu, ki je sedel na konju in proti njegovi vojski.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'In zvernik je bil ujet in z njim lažni prerok, ki je delal čudeže pred njim, s katerimi je zavajal te, ki so sprejeli znamenje zvernika in te, ki so oboževali njegovo podobo. Oba sta bila živa vržena v ognjeno jezero, goreče z žveplom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Preostanek pa je bil umorjen z mečem tistega, ki je sedel na konju, katerega meč je prihajal iz njegovih ust in vsa perjad je bila nasičena z njihovim mesom.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'In videl sem angela priti dol z neba, ki je imel v svoji roki ključ od jame brez dna ter veliko verigo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'In zgrabil je zmaja, to staro kačo, ki je hudič in Satan in ga zvezal za tisoč let');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'in ga vrgel v jamo brez dna in ga zaprl ter zapečatil nad njim, da naj ne bi več zavajal narodov, dokler se ne bi dopolnilo tisoč let, potem pa mora biti malo časa odvezan.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'In videl sem prestole in sedeli so na njih in dana jim je bila sodba. In videl sem duše teh, ki so bili obglavljeni zaradi pričevanja o Jezusu in zaradi Božje besede in ki niso oboževali zvernika, niti njegove podobe, niti niso sprejeli njegovega znamenja v svoja čela ali v svoje roke; in živeli in kraljevali so s Kristusom tisoč let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Toda preostanek mrtvih ni ponovno oživel, dokler ni bilo zaključenih tisoč let. To je prvo vstajenje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Blagoslovljen in svet je, kdor ima delež v prvem vstajenju; nad takšnimi druga smrt nima oblasti, temveč bodo Božji in Kristusovi duhovniki in z njim bodo kraljevali tisoč let.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Ko pa mine tisoč let, bo Satan izpuščen iz svoje ječe');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'in šel bo ven, da zavede narode, ki so na štirih četrtinah zemlje, Goga in Magóga, da jih zbere skupaj na bitko; katerih število je kot morskega peska.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'In odšli so na zemljino prostranstvo in obkolili tabor svetih ter ljubljeno mesto in prišel je ogenj dol z neba od Boga ter jih požrl.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Hudič, ki jih je zavedel, pa je bil vržen v ognjeno in žvepleno jezero, kjer sta zvernik in lažni prerok in mučeni bodo dan in noč, na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'In videl sem velik bel prestol in njega, ki je sedel na njem, pred katerega obrazom sta pobegnila zemlja in nebo in ni bilo najti prostora zanju.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'In videl sem mrtve, male in velike, stati pred Bogom in knjige so bile odprte in še ena knjiga je bila odprta, ki je knjiga življenja in mrtvi so bili sojeni iz teh stvari, ki so bile napisane v knjigah, glede na njihova dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'In morje se je odreklo mrtvim, ki so bili v njem; in smrt in pekel sta izročila mrtve, ki so bili v njiju in bili so sojeni, vsak glede na svoja dela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'In smrt in pekel sta bila vržena v ognjeno jezero. To je druga smrt.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'In kdorkoli ni bil najden zapisan v knjigi življenja, je bil vržen v ognjeno jezero.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'In videl sem novo nebo in novo zemljo, kajti prvo nebo in prva zemlja sta prešla in ni bilo več morja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'In jaz, Janez, sem videl sveto mesto, novi Jeruzalem, prihajati dol od Boga, iz nebes, pripravljeno, kakor je nevesta okrašena za svojega soproga.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'In zaslišal sem močan glas z neba, rekoč: »Glej, šotorsko svetišče Boga je z ljudmi in prebival bo z njimi in oni bodo njegovi ljudje in sam Bog bo z njimi in bo njihov Bog.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'In Bog bo obrisal vse solze z njihovih oči; in ne bo več smrti, niti bridkosti, niti jokanja, niti ne bo več nobene bolečine, kajti prejšnje stvari so minile.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'In tisti, ki je sedel na prestolu, je rekel: »Poglej, vse stvari delam nove.« In rekel mi je: »Zapiši, kajti te besede so resnične in zveste.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'In rekel mi je: »Končano je. Jaz sem Alfa in Omega, začetek in konec. Temu, ki je žejen, bom zastonj dal iz studenca vode življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kdor premaga, bo podedoval vse stvari; in jaz bom njegov Bog, on pa bo moj sin.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Toda strahopetci, neverniki, gnusneži, morilci, vlačugarji, čarodeji, malikovalci in vsi lažnivci bodo imeli svoj delež v jezeru, ki gori z ognjem in žveplom, kar je druga smrt.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'In k meni je prišel eden izmed sedmih angelov, ki so imeli sedem stekleničk, polnih sedmih zadnjih nadlog in govoril z menoj, rekoč: »Pridi sèm, pokazal ti bom nevesto, Jagnjetovo ženo.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'In v duhu me je odvedel proč, k veliki in visoki gori in mi pokazal tisto veliko mesto, sveti Jeruzalem, ki se je od Boga spuščal z neba,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'ki je imel Božjo slavo in njegova svetloba je bila podobna najdragocenejšemu kamnu, celó podobna kamnu jaspisu, čistemu kakor kristal;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'in imelo je veliko in visoko obzidje in dvanajst velikih vrat in ob velikih vratih dvanajst angelov in na njih so bila napisana imena, ki so imena dvanajsterih rodov Izraelovih otrok:');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'na vzhodu troje velikih vrat, na severu troje velikih vrat, na jugu troje velikih vrat in na zahodu troje velikih vrat.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'In obzidje mesta je imelo dvanajst temeljev in na njih imena dvanajsterih Jagnjetovih apostolov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'In tisti, ki je govoril z menoj, je imel zlat trst, da izmeri mesto in njegova velika vrata in njegovo obzidje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'In mesto leži štirioglato in dolžina je tako velika kakor širina; in s trstom je izmeril mesto, dvanajst tisoč dolžin brazd. Njegova dolžina in širina in višina so enake.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'In izmeril je njegovo obzidje: sto štiriinštirideset komolcev, glede na človeško mero, to je, od angela.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'In obzidje je bilo zgrajeno iz jaspisa in mesto je bilo čisto zlato, podobno čistemu steklu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'In temelji mestnega obzidja so bili okrašeni z vsemi vrstami dragocenih kamnov. Prvi temelj je bil jaspis, drugi safir, tretji kalcedon, četrti smaragd,');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'peti sardoniks, šesti sardij, sedmi hrizolit, osmi beril, deveti topaz, deseti hrizopraz, enajsti hijacint, dvanajsti ametist.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'In dvanajst velikih vrat je bilo dvanajst biserov; vsaka posamezna velika vrata so bila iz enega bisera in ulica mesta je bila čisto zlato, kakor bi bilo prosojno steklo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'In v njem nisem videl templja, kajti njegov tempelj sta Gospod Bog Vsemogočni in Jagnje.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'In mesto ni potrebovalo sonca niti lune, da bi sijala nanj, kajti razsvetljevala ga je Božja slava in Jagnje je njegova svetloba.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, '§ In narodi teh, ki so rešeni, bodo hodili v njegovi svetlobi in kralji zemlje vanj prinesejo svojo slavo in čast.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'In njegova velika vrata se podnevi sploh ne bodo zaprla, kajti tam ne bo noči.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'In vanj bodo prinesli slavo in čast narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'In tja nikakor ne bo stopilo karkoli, kar omadežuje niti karkoli počne ogabno ali počne laž, temveč tisti, ki so zapisani v Jagnjetovi knjigi življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'In pokazal mi je bistro reko vode življenja, čisto kakor kristal, ki je izvirala iz Božjega in Jagnjetovega prestola.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'In na sredi njegove ulice in na obeh straneh reke je bilo drevo življenja, ki je rodilo dvanajst vrst sadja in je vsak mesec obrodilo svoj sad, listi drevesa pa so bili za ozdravljanje narodov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'In nič več ne bo prekletstva, temveč bo v njem Božji in Jagnjetov prestol in njegovi služabniki mu bodo služili');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'in videli bodo njegov obraz in njegovo ime bo na njihovih čelih.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'In tam ne bo noči in ne potrebujejo nobene sveče niti sončne svetlobe, kajti Gospod Bog jim daje svetlobo in kraljevali bodo na veke vekov.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'In rekel mi je: »Ti izreki so zvesti in resnični.« In Gospod, Bog svetih prerokov, je poslal svojega angela, da pokaže svojim služabnikom stvari, ki morajo biti v kratkem storjene.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '»Glej, pridem hitro; blagoslovljen je, kdor ohranja izreke preroštva iz te knjige.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'In jaz, Janez, sem videl te stvari in jih slišal. In ko sem jih slišal in videl, sem padel dol pred stopala angela, ki mi je pokazal te stvari, da bi ga oboževal.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Potem mi je rekel: »Poglej, ne delaj tega, kajti jaz sem tvoj soslužabnik in izmed tvojih bratov prerokov in izmed teh, ki ohranjajo izreke te knjige; obožuj Boga.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'In rekel mi je: »Ne zapečati izrekov preroštva te knjige, kajti čas je blizu.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kdor je nepravičen, naj bo nepravičen še naprej; in kdor je umazan, naj bo umazan še naprej; in kdor je pravičen, naj bo še naprej pravičen; in kdor je svet, naj bo svet še naprej.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '»In glej, pridem hitro in moja nagrada je z menoj, da dam vsakemu človeku glede na to, kakšno bo njegovo delo.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jaz sem Alfa in Omega, začetek in konec, prvi in poslednji.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, '§ Blagoslovljeni so tisti, ki izpolnjujejo njegove zapovedi, da bi lahko imeli pravico do drevesa življenja in bi lahko skozi velika vrata vstopili v mesto.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Kajti zunaj so psi in čarodeji in vlačugarji in morilci in malikovalci in kdorkoli ima rad [laž] ter počne laž.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '»Jaz, Jezus, sem poslal svojega angela, da vam te stvari pričuje po cerkvah. Jaz sem korenina in rod Davidov in svetla ter jutranja zvezda.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'In Duh in nevesta pravita: »Pridi.« In naj tisti, ki sliši, reče: »Pridi.« In naj tisti, ki je žejen, pride. In kdorkoli hoče, naj zastonj vzame vodo življenja.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Kajti jaz pričujem vsakemu človeku, ki sliši besede preroštva te knjige: »Če bo katerikoli človek tem besedam dodal, mu bo Bog dodal nadloge, ki so napisane v tej knjigi;');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'in če bo katerikoli človek odvzel od besed knjige tega preroštva, bo Bog odvzel njegov delež iz knjige življenja in iz svetega mesta in od stvari, ki so napisane v tej knjigi.«');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, '§ Tisti, ki pričuje te stvari, pravi: »Zagotovo pridem hitro.« Amen. Točno tako, pridi, Gospod Jezus.');
INSERT INTO `SloKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Milost našega Gospoda Jezusa Kristusa naj bo z vami vsemi. Amen.');
